INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f5c231f2eb04431e8ff2a7ecbb7d07c2',NULL,NULL,'{\n  "properties": {},\n  "id": "f5c231f2eb04431e8ff2a7ecbb7d07c2",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "01.门户首页",\n  "createTime": 1782660713507,\n  "updateTime": 1786586792887,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/index",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"org.ssssssss.script.exception.MagicScriptException: PreparedStatementCallback; uncategorized SQLException for SQL [insert into test(asset_name,id,table_name) values (?,?,?)]; SQL state [HY000]; error code [1366]; Incorrect integer value: \'表资产99\' for column \'asset_name\' at row 1; nested exception is java.sql.BatchUpdateException: Incorrect integer value: \'表资产99\' for column \'asset_name\' at row 1 at Row:5~5,Col:25~38\\\\n\\\\nreturn db.table(\'test\').batchInsert(a);\\\\r\\\\n                        ^^^^^^^^^^^^^^  \\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "读取当前租户可公开展示的系统配置，组装门户首页所需的名称、标识等资料并返回。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "desc",\n        "value": "操作成功",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "systemName",\n            "value": "数据要素操作平台",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "loginLogo",\n            "value": "",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：01.门户首页\n// 路由：GET /portal/index\n// 业务说明：读取当前租户可公开展示的系统配置，组装门户首页所需的名称、标识等资料并返回。\n// 门户首页：处理 GET /index 的核心查询和组装返回数据逻辑。\nimport systemConfig\n\nreturn systemConfig.publicSettings()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/01.系统门户/01.门户首页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c98ee7cf1481482586080eb71cf423d5',NULL,NULL,'{\n  "properties": {},\n  "id": "c98ee7cf1481482586080eb71cf423d5",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "02.单点登录",\n  "createTime": 1782660713568,\n  "updateTime": 1784459658799,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/ssoLogin",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "ticket",\n      "value": "ZT-2063843563657363457",\n      "description": "真实数据示例参数：ticket",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "code",\n      "value": "测试",\n      "description": "真实数据示例参数：code",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"org.ssssssss.script.exception.MagicScriptException: 400 Bad Request: \\\\\\"{\\\\\\"error\\\\\\":\\\\\\"invalid_request\\\\\\",\\\\\\"error_description\\\\\\":\\\\\\"ticket已失效\\\\\\"}\\\\\\" at Row:31~31,Col:6~11\\\\n\\\\n    .post()\\\\r\\\\n     ^^^^^^ \\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "核验当前租户的登录请求，区分公安本地账号与其他租户原有认证分支；登录成功后建立会话并记录登录结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.单点登录\n// 路由：GET /portal/ssoLogin\n// 业务说明：核验当前租户的登录请求，区分公安本地账号与其他租户原有认证分支；登录成功后建立会话并记录登录结果。\nimport tenantAccounts\nimport cn.hutool.core.util.StrUtil\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil;\nimport jsons\nimport \'@/common/configData\' as configData\nimport systemConfig\nimport http\nimport log\nimport request\nimport cn.hutool.http.useragent.UserAgentUtil\nimport cn.hutool.http.useragent.UserAgent\nimport tenantRuntime\n\n\n// 入参判断\nif (!ticket && !code){\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit 500, "无效权限"\n}\n\n// 1.根据 ticket 获取 access_token\nvar url = ``\nif (ticket){\n  url = `${configData().ssoServerUrl}/oauth/token?client_id=${configData().client_id}&client_secret=${systemConfig.legacySsoClientSecret()}&grant_type=ticket&ticket=${ticket}&scope=all`\n}\n\nif (code){\n  url = `${configData().ssoServerUrl}/oauth/token?client_id=${configData().client_id}&client_secret=${systemConfig.legacySsoClientSecret()}&grant_type=authorization_code&code=${code}&scope=all`\n}\n\n// try{\n  // return url\n  var {access_token} =  http.connect(url)\n    .post()\n    .getBody()\n// }catch(e) {\n//   log.info("获取token令牌报错")\n// }\n\n\nif(access_token == null){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,"获取token令牌报错"\n}\n\n// 2. 根据 access_token 获取用户信息 \nvar url = `${configData().ssoServerUrl}/user/current?access_token=${access_token}`\nvar user =  http.connect(url)\n    .get()\n    .getBody()\n\n\n// 3. SSO 账号必须拥有控制库中的有效租户成员关系。\nvar appId = configData().appId;\nvar requestedTenantId = tenantRuntime.requireLoginMembership(user.id)\nif(tenantAccounts.isLocal(requestedTenantId)) {exit 403,\'当前租户使用独立账号，请通过本地登录页面登录\';}\n\nUserAgent ua = UserAgentUtil.parse(request.getHeaders("User-Agent")[0])\nStpUtil.login(user.id)\nvar loginTenant = tenantRuntime.activateLoginTenant(requestedTenantId)\nvar tenantId = loginTenant.tenantId\nvar saToken;\nsaToken = StpUtil.getTokenValueByLoginId(user.id)\n\ndb.table(\'log_user_login_t\').insert({\n    tid: IdUtil.getSnowflakeNextIdStr(),\n    account: user.userName,\n    is_success: 1,\n    token: saToken,\n    ip: request.getClientIP(),\n    browser: ua.getBrowser().toString(),\n    os: ua.getOs().toString(),\n    created_by: user.id,\n    updated_by: user.id,\n    created_time: new Date(),\n    updated_time: new Date(),\n    is_del: 0,\n    tenant_id: tenantId\n})\nuser.appId = appId;\ntenantAccounts.session().set("user", user);\n\n//用户统一token获取\ntenantAccounts.session().set("name", user.userName);\ntenantAccounts.session().set("appId", appId);\n\n// 返回当前业务分支的标准结果。\nreturn {\n    token: saToken\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/01.系统门户/02.单点登录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d2798a4f10be4633ba12b75156e89fb5',NULL,NULL,'{\n  "properties": {},\n  "id": "d2798a4f10be4633ba12b75156e89fb5",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "03.登入配置",\n  "createTime": 1782660713639,\n  "updateTime": 1784798375116,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/loginConfig",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取当前租户登录页需要的公开配置，返回登录方式及可展示的系统资料。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.登入配置\n// 路由：POST /portal/loginConfig\n// 业务说明：读取当前租户登录页需要的公开配置，返回登录方式及可展示的系统资料。\n import \'@/common/configData\' as configData\nimport systemConfig\n import cn.dev33.satoken.stp.StpUtil\n import cn.hutool.core.util.URLUtil\n \n //判断是否走显性登入\nif(configData().loginType == 0 || configData().loginType == 2){\n    StpUtil.logout()\n    // 返回当前业务分支的标准结果。\n    return "/login"\n}else if(configData().loginType == 1){\n    StpUtil.logout()\n    enUrl = URLUtil.encode(configData().redirect_uri)\n    url = `${configData().ssoServerUrl}/oauth/authorize?client_id=${configData().client_id}&client_secret=${systemConfig.legacySsoClientSecret()}&response_type=code&redirect_uri=${enUrl}&scope=all`\n    // 返回当前业务分支的标准结果。\n    return url\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/01.系统门户/03.登入配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('10def1f21f6e42769e696534efbb91a9',NULL,NULL,'{\n  "properties": {},\n  "id": "10def1f21f6e42769e696534efbb91a9",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "04.系统登出",\n  "createTime": 1782660713650,\n  "updateTime": 1784798379882,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/logout",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "清理当前登录会话及相关票据，记录退出结果并返回登出状态。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.系统登出\n// 路由：POST /portal/logout\n// 业务说明：清理当前登录会话及相关票据，记录退出结果并返回登出状态。\nimport log\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.http.useragent.UserAgentUtil\nimport cn.hutool.http.useragent.UserAgent\nimport cn.dev33.satoken.secure.SaSecureUtil\nimport cn.hutool.core.util.IdUtil\nimport \'@/common/configData\' as configData\nimport http\n\n//UserAgent ua = UserAgentUtil.parse(request.getHeaders("User-Agent")[0])\n\n//广播登出\naccess_token = StpUtil.getTokenValue()//?.get("accessToken")\n\n//判断是否走显性登入\nif(configData().logoutType == 0 || configData().logoutType == 2){\n    if(configData().logoutType == 2)\n    {\n        //调用统一隐形登出    \n        url = `${configData().ssoServerUrl}/notice/logout?access_token=${access_token}`\n        ticketInfo = http.connect(url)\n            .post()\n            .getBody()\n    }\n    StpUtil.logout()\n    // 返回当前业务分支的标准结果。\n    return "/login"\n}else if(configData().logoutType == 1){\n    //前端重定向退出\n    StpUtil.logout()\n    url = `${configData().ssoServerUrl}/notice/logout?access_token=${access_token}&redirect_uri=${configData().redirect_uri}`\n    // 返回当前业务分支的标准结果。\n    return url\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/01.系统门户/04.系统登出.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a80cee404da84a95b79eb8619493898a',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "portal_login_01",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "05.用户登录",\n  "createTime": null,\n  "updateTime": 1790779806604,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/login",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"account\\": \\"本地账号\\", \\"password\\": \\"<SM3密码摘要>\\", \\"tenantId\\": \\"应用运行租户ID\\", \\"appId\\": \\"本地权限应用ID\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 tenantId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.用户登录\n// 路由：POST /portal/login\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 tenantId。\n\nimport \'@/tenant-account/login\' as localLogin\nvar loginTarget=(body?.tenantId||\'\')+\'\';\nif(loginTarget==\'\') {\n var options=db.table(\'baseline.sym_tenant_t\').columns(\'tid\').where().eq(\'status\',1).eq(\'is_del\',0).orderBy(\'sort_no\',\'asc\').orderBy(\'created_time\',\'asc\').select();\n if(options==null || options.size()==0) {exit -1,\'当前没有可用租户\';}\n loginTarget=options[0].tid+\'\';\n}\nreturn localLogin({...body,tenantId:loginTarget});\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/01.系统门户/05.用户登录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6ee73a631d6f4719b5b7f3aee0ccc39e',NULL,NULL,'{\n  "properties": {},\n  "id": "5e5d48c9fced4fc9a18b8308d102936f",\n  "script": null,\n  "groupId": "90ef9a3f03244c9b97aa655b8c59b0b6",\n  "name": "06.修改本人密码",\n  "createTime": null,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/account/password",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"oldPassword\\":\\"SM3摘要\\",\\"newPassword\\":\\"SM3摘要\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "核验当前用户原密码，修改本人密码并注销旧会话。"\n}\n================================\n// 接口：修改当前登录用户密码\n// 路由：POST /portal/account/password\n// 请求：{ oldPassword: SM3(当前密码), newPassword: SM3(新密码) }\n// 仅使用服务端会话确定租户与用户；不得接受客户端传入的用户 ID 或租户 ID。\nimport db;\nimport tenantRuntime;\nimport tenantAccounts;\nimport cn.dev33.satoken.stp.StpUtil;\nimport com.linewell.dataelement.utils.PwdRuleUtil;\n\ntry {\n    tenantAccounts.session();\n} catch (e) {\n    exit 401, \'登录已过期，请重新登录\';\n}\n\nvar tenantId = (tenantRuntime.id() || \'\') + \'\';\nif (tenantId == \'\' || !tenantAccounts.isLocal(tenantId)) {\n    exit 403, \'当前账号不支持此密码修改方式\';\n}\nvar userId = StpUtil.getLoginId() + \'\';\nvar oldDigest = ((body?.oldPassword || \'\') + \'\').trim().toUpperCase();\nvar newDigest = ((body?.newPassword || \'\') + \'\').trim().toUpperCase();\nif (!oldDigest.matches(\'[0-9A-F]{64}\') || !newDigest.matches(\'[0-9A-F]{64}\')) {\n    exit 400, \'密码参数不正确\';\n}\nif (oldDigest == newDigest) {\n    exit 400, \'新密码不能与当前密码相同\';\n}\n\nvar sql = db.normal();\nsql.transaction(() => {\n    var user = sql.selectOne(`\nselect password as "password"\n  from rm_user_t\n where tenant_id=#{tenantId} and id=#{userId} and deleted=0 and status=0\n for update`);\n    if (user == null || user.password == null || !PwdRuleUtil.checkPwdBySalt(oldDigest, user.password)) {\n        exit 400, \'当前密码不正确\';\n    }\n    var encoded = PwdRuleUtil.encryptPwdBySalt(newDigest);\n    sql.update(`\nupdate rm_user_t\n   set password=#{encoded}, update_id=#{userId}, update_time=current_timestamp\n where tenant_id=#{tenantId} and id=#{userId} and deleted=0 and status=0`);\n    return true;\n});\ntenantAccounts.revoke(userId);\nreturn { relogin: true };\n',NULL,NULL,0,NULL,'/magic-api/api/01.系统门户/06.修改本人密码.ms');
