           "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "updatedTime",\r\n            "value" : "2026-08-18 15:25:12",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "regTime_date",\r\n            "value" : "2026-08-18 12:34:43",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "createdTime_date",\r\n            "value" : "2026-08-18 12:34:43",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "updatedTime_date",\r\n            "value" : "2026-08-18 15:25:12",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "dbNum",\r\n            "value" : "0",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "Integer",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "tableNum",\r\n            "value" : "0",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "Integer",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "catalogNum",\r\n            "value" : "0",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "Integer",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "tid",\r\n            "value" : "019147d4db30442e9ad4db78116b6c3c",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "id",\r\n            "value" : "019147d4db30442e9ad4db78116b6c3c",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          }, {\r\n            "name" : "orgName",\r\n            "value" : "漳州市公安局",\r\n            "description" : "",\r\n            "required" : false,\r\n            "dataType" : "String",\r\n            "type" : null,\r\n            "defaultValue" : null,\r\n            "validateType" : "",\r\n            "error" : "",\r\n            "expression" : "",\r\n            "children" : [ ]\r\n          } ]\r\n        } ]\r\n      } ]\r\n    }, {\r\n      "name" : "timestamp",\r\n      "value" : "1788940789387",\r\n      "description" : "",\r\n      "required" : false,\r\n      "dataType" : "Long",\r\n      "type" : null,\r\n      "defaultValue" : null,\r\n      "validateType" : "",\r\n      "error" : "",\r\n      "expression" : "",\r\n      "children" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\n// 接口：01.应用系统分页查询\n// 路由：POST /dst/application/page\n// 业务说明：按当前租户和页面筛选条件从应用系统检索索引读取分页数据，补充组织等展示字段后返回列表与总数。\nimport tenantEs\nimport tenantRuntime\nimport \'@/common/configData\' as configData\nimport java.util.List\n\n// 高频列表只读 dataassets 索引。MySQL 主表仍是事实来源，索引由保存接口和盘点维护接口同步。\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => text(value).trim() == \'\'\nvar addCondition = (must, mustNot, item) => {\n    if (item == null || blank(item.field) || item.field == \'assetType\') {\n        return\n    }\n    var type = item.type == null ? \'match\' : item.type\n    var value = item.value\n    if (type == \'null\') {\n        mustNot.add({ exists: { field: item.field } })\n    } else if (!blank(value) && type == \'like\') {\n        must.add({ wildcard: { [item.field]: `*${value}*` } })\n    } else if (!blank(value) && type == \'in\') {\n        must.add({ terms: { [item.field]: value instanceof List ? value : [value] } })\n    } else if (!blank(value)) {\n        must.add({ term: { [item.field]: value } })\n    }\n}\n// 解析请求体并为可选参数设置默认值。\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\nvar tenantId = tenantRuntime.id()\nvar must = [ { term: { assetType: \'app\' } } ]\nvar mustNot = [\n    { wildcard: { appName: \'未匹配业务系统*\' } },\n    { wildcard: { applicationSystemName: \'未匹配业务系统*\' } }\n]\nfor (condition in (body?.conditions == null ? [] : body.conditions)) {\n    addCondition(must, mustNot, condition)\n}\nvar sortField = blank(body?.sortField) ? \'updatedTime\' : body.sortField\nvar sortDir = text(body?.sortDir).toLowerCase() == \'asc\' ? \'asc\' : \'desc\'\nvar sort = {}\nsort[sortField] = { order: sortDir, unmapped_type: \'keyword\' }\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar result = tenantEs.index(configData().es_dataassets).search({\n    from: (pageNum - 1) * pageSize,\n    size: pageSize,\n    track_total_hits: true,\n    query: { bool: { must: must, must_not: mustNot } },\n    sort: [sort]\n})\nvar list = []\nfor (hit in (result?.hits?.hits == null ? [] : result.hits.hits)) {\n    if (hit?._source != null) {\n        list.add(hit._source)\n    }\n}\n// orgId 是应用主数据的唯一组织关联键；当前页组织一次性批量回填，绝不以 manageUnit 替代 orgId。\nvar orgIds = []\nvar seenOrgIds = {}\nfor (item in list) {\n    var orgId = text(item?.orgId).trim()\n    if (!blank(orgId) && seenOrgIds[orgId] == null) {\n        orgIds.add(orgId)\n        seenOrgIds[orgId] = true\n    }\n}\nvar orgNameById = {}\nif (orgIds.size() > 0) {\n    var orgRows = db.table(\'rm_org_t\').where()\n        .in(\'id\', orgIds)\n        .eq(\'tenantId\', tenantId)\n        .eq(\'deleted\', \'0\')\n        .select()\n    for (org in (orgRows == null ? [] : orgRows)) {\n        orgNameById[text(org.id)] = text(org.name)\n    }\n}\nfor (item in list) {\n    var orgId = text(item?.orgId).trim()\n    item.orgName = orgNameById[orgId] == null ? \'\' : orgNameById[orgId]\n}\nvar totalObject = result?.hits?.total\nvar total = totalObject?.value == null ? (totalObject == null ? 0 : totalObject) : totalObject.value\n// 返回当前业务分支的标准结果。\nreturn { pageNum: pageNum, pageSize: pageSize, total: total, list: list }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/01.应用系统分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_application_detail_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_application_detail_01",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "02.应用系统详情",\n  "createTime": null,\n  "updateTime": 1790434056338,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tid\\":\\"01910f1ff2ba4933b2cd759057d3fbf4\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"contactPhone\\": \\"87094269\\",\\n        \\"dbTotal\\": \\"2\\",\\n        \\"contactName\\": \\"董玉珂\\",\\n        \\"applicationClass\\": \\"基础类\\",\\n        \\"applicationSystemName\\": \\"福建省流动人口综合信息服务管理信息平台\\",\\n        \\"assetStatusOther\\": \\"在用\\",\\n        \\"buildUnit\\": null,\\n        \\"migrationSourceId\\": \\"01910f1ff2ba4933b2cd759057d3fbf4\\",\\n        \\"onlineTime\\": \\"2024-04-29 15:09:26\\",\\n        \\"appName\\": \\"福建省流动人口综合信息服务管理信息平台\\",\\n        \\"provinceUrl\\": null,\\n        \\"offlineTime\\": null,\\n        \\"orgId\\": \\"1351480093888868353\\",\\n        \\"manageUnit\\": \\"1351480093888868353\\",\\n        \\"tid\\": \\"01910f1ff2ba4933b2cd759057d3fbf4\\",\\n        \\"assetDesc\\": \\"福建省流动人口综合信息服务管理信息平台\\",\\n        \\"migrationSourceTable\\": \\"asset_application_t\\",\\n        \\"migrationSourceDb\\": \\"dataassets_registration_ga\\",\\n        \\"id\\": \\"01910f1ff2ba4933b2cd759057d3fbf4\\",\\n        \\"assetType\\": \\"app\\",\\n        \\"tenantId\\": null,\\n        \\"createdTime\\": \\"2024-04-29 15:09:26\\",\\n        \\"updatedTime\\": \\"2024-05-24 16:34:05\\",\\n        \\"regTime\\": \\"2024-04-29 15:09:25\\",\\n        \\"assetStatus\\": 2,\\n        \\"_debug\\": {\\n            \\"tid\\": \\"01910f1ff2ba4933b2cd759057d3fbf4\\",\\n            \\"clientId\\": null,\\n            \\"clientSecret\\": null,\\n            \\"appName\\": \\"福建省流动人口综合信息服务管理信息平台\\",\\n            \\"appDesc\\": \\"福建省流动人口综合信息服务管理信息平台\\",\\n            \\"appUrl\\": null,\\n            \\"autoApprove\\": null,\\n            \\"accressValidity\\": null,\\n            \\"refreshValidity\\": null,\\n            \\"notifyUrl\\": null,\\n            \\"returnUrl\\": null,\\n            \\"scope\\": null,\\n            \\"authTypes\\": null,\\n            \\"isUse\\": 1,\\n            \\"seq\\": null,\\n            \\"logo\\": null,\\n            \\"publicKey\\": null,\\n            \\"privateKey\\": null,\\n            \\"autoapprove1\\": null,\\n            \\"assetClass\\": \\"基础类\\",\\n            \\"sortNo\\": null,\\n            \\"config\\": \\"{\\\\\\"contactPhone\\\\\\":\\\\\\"87094269\\\\\\",\\\\\\"dbTotal\\\\\\":\\\\\\"2\\\\\\",\\\\\\"contactName\\\\\\":\\\\\\"董玉珂\\\\\\",\\\\\\"applicationClass\\\\\\":\\\\\\"基础类\\\\\\",\\\\\\"applicationSystemName\\\\\\":\\\\\\"福建省流动人口综合信息服务管理信息平台\\\\\\",\\\\\\"assetStatusOther\\\\\\":\\\\\\"在用\\\\\\",\\\\\\"buildUnit\\\\\\":null,\\\\\\"migrationSourceId\\\\\\":\\\\\\"01910f1ff2ba4933b2cd759057d3fbf4\\\\\\",\\\\\\"onlineTime\\\\\\":\\\\\\"2024-04-29 15:09:26\\\\\\",\\\\\\"appName\\\\\\":\\\\\\"福建省流动人口综合信息服务管理信息平台\\\\\\",\\\\\\"provinceUrl\\\\\\":null,\\\\\\"offlineTime\\\\\\":null,\\\\\\"orgId\\\\\\":\\\\\\"1351480093888868353\\\\\\",\\\\\\"manageUnit\\\\\\":\\\\\\"1351480093888868353\\\\\\",\\\\\\"tid\\\\\\":\\\\\\"01910f1ff2ba4933b2cd759057d3fbf4\\\\\\",\\\\\\"assetDesc\\\\\\":\\\\\\"福建省流动人口综合信息服务管理信息平台\\\\\\",\\\\\\"migrationSourceTable\\\\\\":\\\\\\"asset_application_t\\\\\\",\\\\\\"migrationSourceDb\\\\\\":\\\\\\"dataassets_registration_ga\\\\\\"}\\",\\n            \\"departId\\": \\"1351480093888868353\\",\\n            \\"createdBy\\": \\"1377560448924127233\\",\\n            \\"createdTime\\": \\"2024-04-29 15:09:26\\",\\n            \\"updatedBy\\": \\"1377560448924127233\\",\\n            \\"updatedTime\\": \\"2024-05-24 16:34:05\\",\\n            \\"isDel\\": 0,\\n            \\"tenantId\\": null,\\n            \\"revision\\": null,\\n            \\"regTime\\": \\"2024-04-29 15:09:25\\",\\n            \\"assetStatus\\": 2,\\n            \\"flowStatus\\": 0,\\n            \\"flowOrderId\\": null,\\n            \\"dbTotal\\": 2\\n        }\\n    }\\n}",\n  "description": "根据 tid 从 sym_application_t 与 da_prop_t 合并应用系统详情，不读取 ES。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.应用系统详情\n// 路由：POST /dst/application/detail\n// 业务说明：根据 tid 从 sym_application_t 与 da_prop_t 合并应用系统详情，不读取 ES。\nimport java.util.Map\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar tid = body?.tid\nvar appName = body?.appName\nvar orgId = body?.orgId\nvar silent = body?.silent == true\nif (blank(tid) && blank(appName)) {\n    if (silent) {\n        return { found: false }\n    }\n    exit 400, \'tid不能为空\'\n}\nvar main = blank(tid) ? null : db.table(\'sym_application_t\').where().eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (main == null && !blank(appName)) {\n    var query = db.table(\'sym_application_t\').where().eq(\'app_name\', appName).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    // 按名称兜底查找时必须限定当前登记部门，避免跨部门同名应用系统误关联。\n    if (!blank(orgId)) {\n        query.eq(\'org_id\', orgId)\n    }\n    main = query.selectOne()\n}\nif (main == null) {\n    if (silent) {\n        return { found: false }\n    }\n    exit 404, \'应用系统不存在\'\n}\ntid = first(main, [\'tid\'])\nvar result = {}\nfor (prop in db.table(\'da_prop_t\').where().eq(\'parent_id\', tid).eq(\'tenant_id\', tenantId).eq(\'data_type\', \'app\').eq(\'is_del\', 0).select()) {\n    var name = first(prop, [\'propName\', \'prop_name\'])\n    if (!blank(name)) {\n        result[name] = first(prop, [\'propValue\', \'prop_value\'])\n    }\n}\nresult.tid = tid\nresult.id = tid\nresult.assetType = \'app\'\nresult.appName = first(main, [\'appName\', \'app_name\'])\nresult.assetDesc = first(main, [\'appDesc\', \'app_desc\'])\nresult.appUrl = first(main, [\'appUrl\', \'app_url\'])\nresult.provinceUrl = result.appUrl\nresult.applicationClass = first(main, [\'assetClass\', \'asset_class\'])\nresult.orgId = first(main, [\'orgId\', \'org_id\'])\nresult.tenantId = first(main, [\'tenantId\', \'tenant_id\'])\nresult.createdTime = first(main, [\'createdTime\', \'created_time\'])\nresult.updatedTime = first(main, [\'updatedTime\', \'updated_time\'])\nresult.regTime = first(main, [\'regTime\', \'reg_time\'])\nresult.assetStatus = 2\nresult.found = true\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/02.应用系统详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_application_save_01',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "datapd_application_save_01",\r\n  "script" : null,\r\n  "groupId" : "7868bf218e904ebc999a94f041d91c36",\r\n  "name" : "03.保存应用系统",\r\n  "createTime" : null,\r\n  "updateTime" : 1791112153775,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/save",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"tid\\": \\"2e83a7abf33140c7a3df27d0c79e98c1\\",\\n    \\"propList\\": {\\n    }\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"tid\\":\\"\\"}",\r\n  "description" : "保存当前租户的业务系统主记录与动态属性；先校验业务系统归属、一次预取已有属性，再逐项保存变更，并同步刷新检索投影；返回业务系统 ID。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：03.保存应用系统\n// 路由：POST /dst/application/save\n// 业务说明：业务系统和扩展属性只写当前登录租户；一次预取已有属性，避免逐属性查库。\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\n\nimport cn.hutool.core.util.IdUtil\nimport jsons\nimport java.util.List\nimport java.util.Map\nimport tenantRuntime\n\nvar text = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar now = new Date()\nvar tid = blank(body?.tid) ? IdUtil.getSnowflakeNextIdStr() : body.tid\nvar props = body?.propList == null ? {} : body.propList\nif (!(props instanceof Map) || blank(props.appName)) {\n    exit 400, \'业务系统名称不能为空\'\n}\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再保存应用系统\'\n}\nvar valueText = (value) => value == null ? null : (value instanceof Map || value instanceof List ? jsons.toJSONStr(value) : text(value))\nvar propType = (key) => key.endsWith(\'_date\') ? \'4\' : (key.endsWith(\'_num\') ? \'1\' : \'0\')\nvar propName = (key) => key.endsWith(\'_date\') || key.endsWith(\'_num\') ? key.substring(0, key.length() - 5) : key\n\nvar main = {\n    tid: tid,\n    app_name: props.appName,\n    app_desc: props.assetDesc,\n    app_url: props.provinceUrl,\n    asset_class: props.applicationClass,\n    org_id: props.orgId,\n    is_use: 1,\n    is_del: 0,\n    tenant_id: tenantId,\n    asset_status: 2,\n    flow_status: 2,\n    flow_order_id: null,\n    updated_time: now,\n    reg_time: now\n}\nvar old = db.table(\'sym_application_t\').where().eq(\'tid\', tid).eq(\'tenant_id\', tenantId).selectOne()\nif (!blank(body?.tid) && (old == null || old.isDel == 1 || old.is_del == 1)) {\n    exit 404, \'业务系统不存在或不属于当前租户\'\n}\nif (old == null) {\n    main.created_time = now\n    db.table(\'sym_application_t\').primary(\'tid\').insert(main)\n} else {\n    db.table(\'sym_application_t\').primary(\'tid\').update(main, true)\n}\n\nvar physicalProp = (key) => [\'tid\',\'id\',\'assetType\',\'tenantId\',\'appName\',\'appDesc\',\'assetDesc\',\'appUrl\',\'provinceUrl\',\'applicationClass\',\'assetClass\',\'orgId\',\'dbTotal\',\'clientId\',\'clientSecret\',\'publicKey\',\'privateKey\',\'createdTime\',\'updatedTime\',\'regTime\',\'assetStatus\',\'flowStatus\',\'flowOrderId\'].contains(key)\n\n// 属性增改仍逐条写入，但已有属性只读一次；保留同名历史记录的首条匹配语义。\nvar existingProps = {}\nfor (existingRow in db.table(\'da_prop_t\').where().eq(\'parent_id\', tid)\n    .eq(\'tenant_id\', tenantId).eq(\'data_type\', \'app\').eq(\'is_del\', 0).select()) {\n    var existingName = text(existingRow.propName == null ? existingRow.prop_name : existingRow.propName)\n    if (!blank(existingName) && existingProps[existingName] == null) {\n        existingProps[existingName] = existingRow\n    }\n}\nfor (rawKey in props.keySet()) {\n    var name = propName(rawKey)\n    if (physicalProp(rawKey) || physicalProp(name)) {\n        continue\n    }\n    var row = existingProps[name]\n    var data = {\n        parent_id: tid, tenant_id: tenantId, prop_name: name, prop_value: valueText(props[rawKey]),\n        prop_type: propType(rawKey), data_type: \'app\', is_del: 0, updated_time: now\n    }\n    if (row == null) {\n        data.tid = IdUtil.getSnowflakeNextIdStr()\n        data.created_time = now\n        db.table(\'da_prop_t\').primary(\'tid\').insert(data)\n        existingProps[name] = { tid: data.tid }\n    } else {\n        data.tid = row.tid\n        db.table(\'da_prop_t\').primary(\'tid\').update(data, true)\n    }\n}\nvar savedTid = tid\nbody = { tid: savedTid }\nrefreshAssetIndex()\nreturn { tid: savedTid }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/03.保存应用系统.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_application_delete_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_application_delete_01",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "04.删除应用系统",\n  "createTime": null,\n  "updateTime": 1787153758406,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2080000000000000000\\",\\n  \\"dryRun\\": true\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"deleted\\": false,\\n  \\"dryRun\\": true\\n}",\n  "description": "按应用系统标识查找关联数据源、表、字段、目录及接入任务；dryRun 仅预估清理范围，正式执行时清理关联平台元数据和索引，不删除业务物理表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.删除应用系统\n// 路由：POST /dst/application/delete\n// 业务说明：按应用系统标识查找关联数据源、表、字段、目录及接入任务；dryRun 仅预估清理范围，正式执行时清理关联平台元数据和索引，不删除业务物理表。\n// 删除应用系统：处理 POST /delete 的核心写入或状态变更逻辑。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar addUnique = (rows, value) => {\n    var normalized = text(value)\n    if (normalized != \'\' && !rows.contains(normalized)) {\n        rows.add(normalized)\n    }\n}\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]) != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar tid = body == null ? null : body.tid\nif (text(tid) == \'\') {\n    exit 400, \'tid is required\'\n}\ntid = text(tid)\nvar dryRun = body != null && (body.dryRun == true || body.dryRun == 1 || body.dryRun == \'1\')\nvar application = db.table(\'sym_application_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (application == null) {\n    return { deleted: false, dryRun: dryRun, alreadyDeleted: true, cleanup: { datasources: 0, tables: 0, columns: 0, catalogs: 0, tasks: 0 } }\n}\n\nvar datasourceIds = []\nfor (datasource in db.table(\'db_datasource_t\').where().eq(\'app_id\', tid).eq(\'is_del\', 0).select()) {\n    addUnique(datasourceIds, rowValue(datasource, [\'tid\']))\n}\nvar tableIds = []\nvar catalogIds = []\nif (datasourceIds.size() > 0) {\n    for (tableRow in db.table(\'db_table_t\').where().in(\'datasource_id\', datasourceIds).eq(\'is_del\', 0).select()) {\n        addUnique(tableIds, rowValue(tableRow, [\'tid\']))\n        addUnique(catalogIds, rowValue(tableRow, [\'sourceCatalogId\', \'source_catalog_id\']))\n    }\n    for (catalog in db.table(\'da_catalog_t\').where().in(\'db_id\', datasourceIds).eq(\'is_del\', 0).select()) {\n        addUnique(catalogIds, rowValue(catalog, [\'tid\']))\n    }\n}\nif (tableIds.size() > 0) {\n    for (catalog in db.table(\'da_catalog_t\').where().in(\'source_table_id\', tableIds).eq(\'is_del\', 0).select()) {\n        addUnique(catalogIds, rowValue(catalog, [\'tid\']))\n    }\n}\nvar columnCount = tableIds.size() == 0 ? 0 : db.table(\'db_table_column_t\').where().in(\'table_id\', tableIds).eq(\'is_del\', 0).count()\nvar taskIds = []\nvar pipelineIds = []\nvar collectTasks = rows => { for (task in rows) { addUnique(taskIds, rowValue(task, [\'tid\'])); addUnique(pipelineIds, rowValue(task, [\'pipelineId\', \'pipeline_id\'])) } }\nif (datasourceIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'source_db_id\', datasourceIds).eq(\'is_del\', 0).select())\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'target_db_id\', datasourceIds).eq(\'is_del\', 0).select())\n}\nif (tableIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'source_table_id\', tableIds).eq(\'is_del\', 0).select())\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'target_table_id\', tableIds).eq(\'is_del\', 0).select())\n}\nif (catalogIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'data_catalog_id\', catalogIds).eq(\'is_del\', 0).select())\n}\nif (dryRun) {\n    return { deleted: false, dryRun: true, appName: rowValue(application, [\'appName\', \'app_name\']), cleanup: { datasources: datasourceIds.size(), tables: tableIds.size(), columns: columnCount, catalogs: catalogIds.size(), tasks: taskIds.size() } }\n}\n\nvar nowTime = new Date()\nif (taskIds.size() > 0) {\n    db.table(\'data_access_field_mapping\').where().in(\'task_id\', taskIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n    db.table(\'data_access_task_monitor_snap_t\').where().in(\'task_id\', taskIds).eq(\'is_del\', 0).update({ is_del: 1 })\n    db.table(\'data_access_agg_task_t\').where().in(\'tid\', taskIds).eq(\'is_del\', 0).update({ is_del: 1, task_status: 0, updated_time: nowTime })\n}\nif (pipelineIds.size() > 0) {\n    db.table(\'nifi_pipeline_t\').where().in(\'id\', pipelineIds).eq(\'is_del\', 0).update({ is_del: 1, updated_at: System.currentTimeMillis() })\n}\nif (tableIds.size() > 0) {\n    db.table(\'db_table_column_t\').where().in(\'table_id\', tableIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n    db.table(\'db_table_t\').where().in(\'tid\', tableIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n}\nif (catalogIds.size() > 0) {\n    db.table(\'da_catalog_item_t\').where().in(\'catalog_id\', catalogIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n    db.table(\'da_prop_t\').where().in(\'parent_id\', catalogIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n    db.table(\'da_catalog_t\').where().in(\'tid\', catalogIds).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowTime })\n}\nif (datasourceIds.size() > 0) {\n    db.table(\'db_datasource_t\').where().in(\'tid\', datasourceIds).eq(\'is_del\', 0).update({ is_del: 1, is_enable: 0, updated_time: nowTime })\n}\nvar changed = db.table(\'sym_application_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).update({ is_del: 1, is_use: 0, updated_time: nowTime })\nvar projectionFailures = []\nfor (assetId in [tid].concat(datasourceIds).concat(tableIds).concat(catalogIds)) {\n    try { esCommonService.deleteById(\'dataassets\', assetId) } catch (e) { projectionFailures.add({ assetId: assetId, error: e.message }) }\n}\nreturn { deleted: changed > 0, dryRun: false, cleanup: { datasources: datasourceIds.size(), tables: tableIds.size(), columns: columnCount, catalogs: catalogIds.size(), tasks: taskIds.size() }, projectionFailures: projectionFailures }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/04.删除应用系统.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_application_databases_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_application_databases_01",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "05.查询应用系统数据源",\n  "createTime": null,\n  "updateTime": 1787156089361,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/databases",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"appId\\":\\"01910f1ff2ba4933b2cd759057d3fbf4\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": []\\n}",\n  "description": "从 db_datasource_t 查询应用系统下的数据源，并合并 connection extension property 连接参数；主数据字段以 db_datasource_t 为准，不读取 ES 或 da_prop_t；使用请求参数 appId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.查询应用系统数据源\n// 路由：POST /dst/application/databases\n// 业务说明：从 db_datasource_t 查询应用系统下的数据源，并合并 connection extension property 连接参数；主数据字段以 db_datasource_t 为准，不读取 ES 或 da_prop_t；使用请求参数 appId。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\n// 查询应用系统数据源：处理 POST /databases 的核心查询和组装返回数据逻辑。\nimport java.util.Map\nimport cn.hutool.json.JSONUtil as jsons\nvar appId = body?.appId\nif (appId == null || (appId + \'\').trim() == \'\') {\n    exit 400, \'appId不能为空\'\n}\nvar first = (row, keys) => {\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar result = []\nfor (main in db.table(\'db_datasource_t\').where().eq(\'app_id\', appId).eq(\'is_del\', 0).orderBy(\'updated_time\', \'desc\').select()) {\n    var item = {}\n    var tid = first(main, [\'tid\'])\n    var connectionConfig = datasourceConnectionConfig(\'read\', tid, null, false)\n    var hasConnection = connectionConfig != null && !connectionConfig.isEmpty()\n    if (hasConnection) {\n        item.putAll(connectionConfig)\n    }\n    item.tid = tid\n    item.id = tid\n    item.assetType = \'db\'\n    item.dbName = first(main, [\'dbName\', \'db_name\'])\n    item.dbType = first(main, [\'dbType\', \'db_type\'])\n    item.orgId = first(main, [\'orgId\', \'org_id\'])\n    item.storageDomain = first(main, [\'storageDomain\', \'storage_domain\'])\n    item.nodeId = first(main, [\'nodeId\', \'node_id\'])\n    item.assetDesc = first(main, [\'remark\'])\n    item.showConnect = hasConnection ? 1 : 0\n    item.tableNum = first(main, [\'tableNum\', \'table_num\'])\n    item.appId = appId\n    item.assetStatus = 2\n    result.add(item)\n}\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/05.查询应用系统数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5d64f064de164fe89cc96509b518620e',NULL,NULL,'{\n  "properties": {},\n  "id": "5d64f064de164fe89cc96509b518620e",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "06.查询应用系统数据表",\n  "createTime": null,\n  "updateTime": 1787153758483,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"appId\\": \\"2e83a7abf33140c7a3df27d0c79e98c1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "应用系统 06：查询应用系统关联的数据表；使用请求参数 appId；涉及 db_datasource_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.查询应用系统数据表\n// 路由：POST /dst/application/tables\n// 业务说明：应用系统 06：查询应用系统关联的数据表；使用请求参数 appId；涉及 db_datasource_t、db_table_t 等业务表。\nimport java.util.Map\n\n/*\n * 应用系统 06：查询应用系统关联的数据表。\n *\n * 通过 db_datasource_t.app_id -> db_table_t.datasource_id 直接查询主表，\n * 不读取 da_asset_t 或 da_prop_t。\n */\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n// 解析请求体并为可选参数设置默认值。\nvar appId = body == null ? null : body.appId\nif (blank(appId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'appId不能为空\'\n}\nvar dbIds = []\n// 从 MySQL 业务表读取当前有效数据。\nfor (source in db.table(\'db_datasource_t\').where()\n    .eq(\'app_id\', appId).eq(\'is_del\', 0).select()) {\n    dbIds.add(first(source, [\'tid\']))\n}\nif (dbIds.size() == 0) {\n    // 返回当前业务分支的标准结果。\n    return []\n}\nvar result = []\n// 从 MySQL 业务表读取当前有效数据。\nfor (table in db.table(\'db_table_t\').where()\n    .in(\'datasource_id\', dbIds).eq(\'is_del\', 0).select()) {\n    var tid = first(table, [\'tid\'])\n    result.add({\n        tid: tid,\n        id: tid,\n        assetType: \'table\',\n        appId: appId,\n        dbId: first(table, [\'datasourceId\', \'datasource_id\']),\n        datasourceId: first(table, [\'datasourceId\', \'datasource_id\']),\n        tableName: first(table, [\'tableName\', \'table_name\']),\n        tableNameEn: first(table, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\']),\n        tableNameCn: first(table, [\'tableNameCn\', \'table_name_cn\']),\n        tableComment: first(table, [\'tableComment\', \'table_comment\']),\n        tableType: first(table, [\'tableType\', \'table_type\']),\n        businessType: first(table, [\'businessType\', \'business_type\']),\n        recordCount: first(table, [\'recordCount\', \'record_count\']),\n        fieldCount: first(table, [\'fieldCount\', \'field_count\']),\n        storageSize: first(table, [\'storageSize\', \'storage_size\']),\n        dataSourceType: first(table, [\'dataSourceType\', \'data_source_type\']),\n        annotated: first(table, [\'annotated\']),\n        createdTime: first(table, [\'createdTime\', \'created_time\']),\n        updatedTime: first(table, [\'updatedTime\', \'updated_time\'])\n    })\n}\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/06.查询应用系统数据表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_application_list_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_application_list_01",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "07.应用系统列表",\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"公安\\",\\n  \\"limit\\": 50\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "应用系统下拉列表，默认返回最近 100 条，支持关键词检索；使用请求参数 keyword、limit。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.应用系统列表\n// 路由：POST /dst/application/list\n// 业务说明：应用系统下拉列表，默认返回最近 100 条，支持关键词检索；使用请求参数 keyword、limit。\n// 应用系统列表：处理 POST /list 的核心查询和组装返回数据逻辑。\nimport tenantEs\nimport \'@/common/configData\' as configData\n\nvar filters = [{ term: { assetType: \'app\' } }]\nvar excluded = [\n  { wildcard: { appName: \'未匹配业务系统\' } },\n  { wildcard: { applicationSystemName: \'未匹配业务系统\' } }\n]\nvar keyword = body?.keyword == null ? \'\' : (body.keyword + \'\').trim()\nif (keyword != \'\') {\n  filters.add({\n    bool: {\n      should: [\n        { wildcard: { appName: `*${keyword}*` } },\n        { wildcard: { applicationSystemName: `*${keyword}*` } }\n      ],\n      minimum_should_match: 1\n    }\n  })\n}\nvar size = body?.limit == null ? 100 : body.limit::int\nif (size < 1) { size = 100 }\nif (size > 100) { size = 100 }\nvar result = tenantEs.index(configData().es_dataassets).search({\n  size: size,\n  query: { bool: { filter: filters, must_not: excluded } },\n  sort: [{ updatedTime: { order: \'desc\', unmapped_type: \'keyword\' } }]\n})\nvar list = []\nfor (hit in (result?.hits?.hits == null ? [] : result.hits.hits)) {\n  if (hit?._source != null) {\n    list.add(hit._source)\n  }\n}\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/07.应用系统列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3cf61021a65a4562a5240c4c8c6a6be7',NULL,NULL,'{\n  "properties": {},\n  "id": "application_options_01",\n  "script": null,\n  "groupId": "7868bf218e904ebc999a94f041d91c36",\n  "name": "08.应用系统选择项",\n  "createTime": null,\n  "updateTime": 1787731056308,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"keyword\\":\\"公安\\",\\"limit\\":50}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"message\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"value\\": \\"e1aa194a0dc04e13ac63a27c36dd0d12\\",\\n            \\"label\\": \\"闽侯公安多维融合实战指挥平台\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"d5bb7c4be7ad4af0835db8ac44dde21b\\",\\n            \\"label\\": \\"福建省公安厅终端防病毒系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"d692101322be4f5e805c98a8186fe928\\",\\n            \\"label\\": \\"漳平市公安视频图像信息应用平台\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"ca644aa017ed4c98ac9d9681f3df564a\\",\\n            \\"label\\": \\"福建公安厅云会商系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"87ba412b008747b79a385eb797e5bca0\\",\\n            \\"label\\": \\"福建省公安云计算平台\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"810177924bc74c699040625c0eba944e\\",\\n            \\"label\\": \\"福建省公安厅信息系统一屏八舱安全舱\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"6dea9896e5374816873f8d4d8b6406ce\\",\\n            \\"label\\": \\"公安部云鉴系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"71c6b8c77ed04e128a2fd89ed4b26f90\\",\\n            \\"label\\": \\"福建省公安厅信息系统应用行为大数据分析系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"7824b5a1ef604899a396bbef0ad6b5d2\\",\\n            \\"label\\": \\"福建省公共数据汇聚共享平台公安节点\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"62d195afd2434ec1b7c8f87b34e10ec5\\",\\n            \\"label\\": \\"福建省公安机关现场执法视音频管理系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"57381691d92a4c84bb28a126ff16cf2f\\",\\n            \\"label\\": \\"长汀公安视频图像信息应用平台系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"592af3805276450d967b810d4fa27388\\",\\n            \\"label\\": \\"福建公安融合通信系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"52e8feb51d82482694e7b7f658c0d3e3\\",\\n            \\"label\\": \\"公安部人像比对系统（云鉴）\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"3c4b53b7ec9d40b8a3c6a32fb3f1c72d\\",\\n            \\"label\\": \\"长汀县公安局执法办案智能系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"4623555b35be43b68275e50ce6a7ce79\\",\\n            \\"label\\": \\"公安部视综平台\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"2e4bc464d5724e349388f86f39f7af11\\",\\n            \\"label\\": \\"福建省公安厅安全管理系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"2ed667356c154e0381d97d7f15c51399\\",\\n            \\"label\\": \\"福建公安警用地理信息系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"26ec51b6578548c6a2de661d81aaf5fd\\",\\n            \\"label\\": \\"石狮公安内部OA系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"26fce0bb69474092bbb1c089b4500461\\",\\n            \\"label\\": \\"福建省公安厅信息系统应用安全日志审计系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"295c8ed9a2fe4afd872af8fcb50847b5\\",\\n            \\"label\\": \\"长汀公安网上督察监控系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"1d3e2e1c86f94050a350d1f4e43480aa\\",\\n            \\"label\\": \\"福建省公安厅信息数据安全智能分析系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"1fc4b5c382fd4b06b0a1cc68be2ef4d4\\",\\n            \\"label\\": \\"公安电子证照管理系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        },\\n        {\\n            \\"value\\": \\"1b8a33f0b97d4a18b650754fe63f2915\\",\\n            \\"label\\": \\"公安部云搜索系统\\",\\n            \\"orgId\\": \\"1351480104462708738\\"\\n        }\\n    ],\\n    \\"timestamp\\": 1787209743915\\n}",\n  "description": "应用系统轻量选择项（POST /dst/application/options）。复用数据源管理菜单的数据范围：ALL 返回全部应用系统，ORG 返回本部门范围，OWNER 仅返回本人登记项；前端参数不参与范围判定；涉及 pingao_application_sync_state_t、sym_application_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "message",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Array",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "",\n            "value": "",\n            "description": "",\n            "required": false,\n            "dataType": "Object",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": [\n              {\n                "name": "value",\n                "value": "e1aa194a0dc04e13ac63a27c36dd0d12",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              },\n              {\n                "name": "label",\n                "value": "闽侯公安多维融合实战指挥平台",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              },\n              {\n                "name": "orgId",\n                "value": "1351480104462708738",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              }\n            ]\n          }\n        ]\n      },\n      {\n        "name": "timestamp",\n        "value": "1787209743915",\n        "description": "",\n        "required": false,\n        "dataType": "Long",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：08.应用系统选择项\n// 路由：POST /dst/application/options\n// 业务说明：应用系统轻量选择项（POST /dst/application/options）。复用数据源管理菜单的数据范围：ALL 返回全部应用系统，ORG 返回本部门范围，OWNER 仅返回本人登记项；前端参数不参与范围判定；涉及 pingao_application_sync_state_t、sym_application_t 等业务表。\n// Data-source registration application options use the same configurable\n// ALL / ORG / OWNER scope as the data-source management list.\n// Scope comes only from the authenticated session; client parameters cannot\n// expand an application\'s visible range.\nimport tenantRuntime\nimport dataScope\n\nvar tenantId = tenantRuntime.id()\nvar escapedTenantId = (tenantId + \'\').replace("\'", "\'\'")\nvar scopeResource = \'MENU:2081000000000000002\'\nvar state = db.select("""\n    select has_success as hasSuccess\n      from pingao_application_sync_state_t\n     where tenant_id = \'${escapedTenantId}\'\n""")\nvar hasSuccessfulSnapshot = state != null && state.size() > 0 && state[0].hasSuccess == 1\nif (hasSuccessfulSnapshot) {\n    var applications = db.select("""\n        select app_name as label, tid as value, org_id as orgId, created_by as createdBy\n          from sym_application_t\n         where tenant_id = \'${escapedTenantId}\'\n           and data_origin = \'PINGAO\'\n           and sync_active = 1\n           and ifnull(is_del, 0) = 0\n         order by app_name asc, tid asc\n    """)\n    return dataScope.visibleDataSourcesFor(scopeResource, applications)\n}\nvar applications = db.select("""\n    select concat(app_name, \'（历史）\') as label, tid as value, org_id as orgId, created_by as createdBy\n      from sym_application_t\n     where tenant_id = \'${escapedTenantId}\'\n       and data_origin = \'LEGACY\'\n       and ifnull(is_del, 0) = 0\n     order by app_name asc, tid asc\n""")\nreturn dataScope.visibleDataSourcesFor(scopeResource, applications)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/01.应用系统/08.应用系统选择项.ms');
