INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5c1e80431c9b440881fcce698f0b8634',NULL,NULL,'{\n  "properties": {},\n  "id": "5c1e80431c9b440881fcce698f0b8634",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "01.数据源联通测试",\n  "createTime": 1782955344253,\n  "updateTime": 1787156109406,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/test-connection",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"codex_oracle_helowin\\",\\n    \\"dbType\\": \\"oracle\\",\\n    \\"host\\": \\"192.168.175.86\\",\\n    \\"port\\": 1521,\\n    \\"database\\": \\"helowin\\",\\n    \\"username\\": \\"system\\",\\n    \\"password\\": \\"******\\",\\n    \\"jdbcURL\\": \\"jdbc:oracle:thin:@192.168.175.86:1521:helowin\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据源联通测试（POST /dst/database/metadata/test-connection）。读取 db_datasource_t 中已保存的连接配置，调用 Java DataSourceConnectionTestService 完成协议适配、连接探测和统一异常诊断，并写入 db_datasource_t.connection_status；该接口是数据源登记页的主连通性测试端点；使用请求参数 tid。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.数据源联通测试\n// 路由：POST /dst/database/metadata/test-connection\n// 业务说明：数据源联通测试（POST /dst/database/metadata/test-connection）。读取 db_datasource_t 中已保存的连接配置，调用 Java DataSourceConnectionTestService 完成协议适配、连接探测和统一异常诊断，并写入 db_datasource_t.connection_status；该接口是数据源登记页的主连通性测试端点；使用请求参数 tid。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.metautil.service.DataSourceConnectionTestService as dataSourceConnectionTestService\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\nvar failure = (message) => ({\n    connected: false,\n    success: false,\n    product: \'数据源\',\n    errorCode: \'CONNECTION-TEST-001\',\n    error: message,\n    elapsedMs: 0\n})\n\nif (body == null) {\n    return failure(\'请求参数不能为空\')\n}\n\n/*\n * 已登记数据源以主表和 da_prop_t 连接扩展属性为唯一可靠配置来源。登记页动态表单会提交\n * 未填字段的空串，空串不能覆盖已保存的连接参数，否则会把一次测试变成假失败。\n */\nvar source = {}\nvar persistedTid = null\nvar requestTid = body.tid\nif (!blank(requestTid)) {\n    var main = db.table(\'db_datasource_t\')\n        .where()\n        .eq(\'tid\', requestTid)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (main == null) {\n        return failure(\'数据源不存在或已删除，请返回第一步重新选择数据源\')\n    }\n\n    persistedTid = main.tid    source.putAll(datasourceConnectionConfig(\'read\', main.tid, null, false))\n\n    // 主表字段补齐连接扩展属性，保持和详情/探查同一口径。\n    source.tid = main.tid\n    if (!blank(main.dbType)) {\n        source.dbType = main.dbType\n    }\n    if (!blank(main.databaseType)) {\n        source.databaseType = main.databaseType\n    }\n    if (!blank(main.host)) {\n        source.host = main.host\n    }\n    if (!blank(main.port)) {\n        source.port = main.port\n    }\n    if (!blank(main.database)) {\n        source.database = main.database\n    }\n    if (!blank(main.dbName)) {\n        source.dbName = main.dbName\n    }\n    if (!blank(main.jdbcUrl)) {\n        source.jdbcURL = main.jdbcUrl\n    }\n    if (!blank(main.username)) {\n        source.username = main.username\n    }\n    if (!blank(main.password)) {\n        source.password = main.password\n    }\n    if (!blank(main.appId)) {\n        source.appId = main.appId\n    }\n    if (!blank(main.orgId)) {\n        source.orgId = main.orgId\n    }\n    if (!blank(main.showConnect)) {\n        source.showConnect = main.showConnect\n    }\n}\n\n// 仅使用前端传入的非空值覆盖配置，支持尚未保存的新数据源和用户刚修改的参数。\nvar overrideKeys = [\n    \'dbType\', \'databaseType\', \'dataSourceType\', \'dbName\', \'database\', \'host\', \'dbIp\',\n    \'port\', \'dbPort\', \'username\', \'password\', \'jdbcURL\', \'jdbcUrl\', \'schema\',\n    \'defaultSchema\', \'currentSchema\', \'dbVersion\', \'jdbcType\', \'serviceName\',\n    \'dbMetaType\', \'dbMetaDbName\', \'dbMetaIp\', \'dbMetaPort\', \'dbMetaUser\', \'dbMetaPassword\',\n    \'maxcomputeEndpoint\', \'maxcomputeProject\', \'maxcomputeAccessKeyId\',\n    \'maxcomputeAccessKeySecret\', \'maxcomputeTunnelEndpoint\', \'minioEndpoint\',\n    \'minioAccessKey\', \'minioSecretKey\', \'minioBucket\', \'minioRegion\', \'minioUseSSL\',\n    \'minioPrefix\', \'minioFilePattern\', \'minioSingleFile\',\n    \'ftpProtocol\', \'ftpHost\', \'ftpPort\', \'ftpPath\', \'ftpUsername\', \'ftpPassword\',\n    \'ftpPassiveMode\', \'ftpFilePattern\', \'ftpRecursive\', \'ftpCharset\', \'ftpDelimiter\',\n    \'apiMethod\', \'apiUrl\', \'apiAuthType\', \'apiUsername\', \'apiPassword\', \'apiToken\',\n    \'apiKeyName\', \'apiKeyValue\', \'apiKeyPosition\', \'apiHeaders\', \'apiBody\',\n    \'apiTimeoutSeconds\', \'apiCollectionPaths\', \'kafkaBootstrapServers\', \'kafkaTopic\',\n    \'kafkaGroupId\', \'kafkaSecurityProtocol\', \'kafkaSaslMechanism\', \'kafkaUsername\',\n    \'kafkaPassword\', \'kafkaSchemaRegistryUrl\', \'kafkaSampleSize\', \'kafkaPollTimeoutMs\',\n    \'nodes\', \'protocol\', \'authMethod\', \'apiKey\', \'manifestKey\'\n]\nfor (key in overrideKeys) {\n    if (!blank(body[key])) {\n        source[key] = body[key]\n    }\n}\nif (blank(source.tid) && !blank(requestTid)) {\n    source.tid = requestTid\n}\n\nvar result = null\ntry {\n    result = dataSourceConnectionTestService.test(source)\n} catch (error) {\n    // Java 服务已处理大多数协议异常；这里兜住脚本边界异常，绝不向登记页泄漏 HTTP 500。\n    result = failure(\'连接测试失败：\' + (blank(error?.message) ? \'请检查连接参数和网络可达性\' : error.message))\n}\n\n// 状态记录不参与连接测试结果。写入或历史数据异常时保留测试结果，不能影响前端。\nif (!blank(persistedTid)) {\n    try {\n        var status = result != null && result.connected == true ? \'success\' : \'failed\'\n        db.table(\'db_datasource_t\')\n            .where()\n            .eq(\'tid\', persistedTid)\n            .eq(\'is_del\', 0)\n            .update({\n                connection_status: status,\n                updated_time: new Date()\n            })\n    } catch (ignored) {\n    }\n}\n\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/01.数据源联通测试.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_nifi_connection_test_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_nifi_connection_test_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "02.统一连接测试(NiFi兼容)",\n  "createTime": 1783639496542,\n  "updateTime": 1784437772000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/connection-test",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"manifestKey\\": \\"source.mysql\\",\\n    \\"config\\": {\\n        \\"host\\": \\"127.0.0.1\\",\\n        \\"port\\": 3306,\\n        \\"database\\": \\"test\\",\\n        \\"username\\": \\"root\\",\\n        \\"password\\": \\"***\\"\\n    }\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "兼容 data-element-nifi 现有入参：{ manifestKey, config }。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.统一连接测试(NiFi兼容)\n// 路由：POST /dst/database/metadata/connection-test\n// 业务说明：兼容 data-element-nifi 现有入参：{ manifestKey, config }。\nimport com.linewell.dataelement.integrated.nifi.canvas.controller.ConnectionTestController as connectionTestController\n\n// 兼容 data-element-nifi 现有入参：{ manifestKey, config }\n// 返回 { success, url, product, version, elapsedMs, error }\nvar response = connectionTestController.test(body)\n// 返回当前业务分支的标准结果。\nreturn response.getBody()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/02.统一连接测试(NiFi兼容).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_nifi_tables_probe_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_nifi_tables_probe_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "03.统一表结构探查(NiFi兼容)",\n  "createTime": 1783639496542,\n  "updateTime": 1784437772003,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables-probe",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"manifestKey\\": \\"source.mysql\\",\\n    \\"config\\": {\\n        \\"host\\": \\"127.0.0.1\\",\\n        \\"port\\": 3306,\\n        \\"database\\": \\"test\\",\\n        \\"username\\": \\"root\\",\\n        \\"password\\": \\"***\\"\\n    },\\n    \\"keyword\\": \\"测试\\",\\n    \\"limit\\": 200,\\n    \\"columns\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "关系型数据库仍复用 NiFi JDBC 元数据能力；API/FTP/SFTP/Kafka 这类非表型数据源在 Magic API 中生成虚拟结构，便于后续按业务规则调整；使用请求参数 config、manifestKey、columns。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.统一表结构探查(NiFi兼容)\n// 路由：POST /dst/database/metadata/tables-probe\n// 业务说明：关系型数据库仍复用 NiFi JDBC 元数据能力；API/FTP/SFTP/Kafka 这类非表型数据源在 Magic API 中生成虚拟结构，便于后续按业务规则调整；使用请求参数 config、manifestKey、columns。\nimport com.linewell.dataelement.integrated.nifi.canvas.controller.ConnectionTestController as connectionTestController\nimport com.fasterxml.jackson.databind.ObjectMapper\nimport java.util.Map\nimport java.util.List\n\n// 统一表/结构探查。\n// 关系型数据库仍复用 NiFi JDBC 元数据能力；API/FTP/SFTP/Kafka 这类非表型数据源在 Magic API 中生成虚拟结构，便于后续按业务规则调整。\n\nvar mapper = new ObjectMapper()\nvar blank = (value) => value == null || String(value).trim() == \'\'\n// 解析请求体并为可选参数设置默认值。\nvar cfg = body?.config == null ? {} : body.config\nvar manifestKey = body?.manifestKey == null ? \'\' : String(body.manifestKey).toLowerCase()\n\nvar first = (keys) => {\n    for (key in keys) {\n        var value = cfg[key]\n        if (blank(value) && body != null) {\n            value = body[key]\n        }\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar parseJson = (text) => {\n    if (blank(text)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return mapper.readValue(String(text), Object.class)\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n}\n\nvar scalarType = (value) => {\n    if (value == null) { return \'VARCHAR\' }\n    var s = String(value)\n    if (s == \'true\' || s == \'false\') { return \'BOOLEAN\' }\n    if (s.matches(\'^-?\\\\d+$\')) { return \'BIGINT\' }\n    if (s.matches(\'^-?\\\\d+\\\\.\\\\d+$\')) { return \'DECIMAL\' }\n    if (s.matches(\'^\\\\d{4}-\\\\d{2}-\\\\d{2}.*\')) { return \'TIMESTAMP\' }\n    // 返回当前业务分支的标准结果。\n    return \'VARCHAR\'\n}\n\nvar countJsonFields = null\ncountJsonFields = (obj) => {\n    if (obj == null) { return 0 }\n    if (obj instanceof Map) {\n        var total = 0\n        for (entry in obj.entrySet()) {\n            var child = entry.getValue()\n            if (child instanceof Map) {\n                var childCount = countJsonFields(child)\n                total = total + (childCount == 0 ? 1 : childCount)\n            } else if (child instanceof List) {\n                if (child.size() > 0) {\n                    var childCount2 = countJsonFields(child[0])\n                    total = total + (childCount2 == 0 ? 1 : childCount2)\n                } else {\n                    total = total + 1\n                }\n            } else {\n                total = total + 1\n            }\n        }\n        // 返回当前业务分支的标准结果。\n        return total\n    }\n    if (obj instanceof List && obj.size() > 0) {\n        // 返回当前业务分支的标准结果。\n        return countJsonFields(obj[0])\n    }\n    // 返回当前业务分支的标准结果。\n    return 1\n}\n\nvar splitHeader = (text) => {\n    if (blank(text)) { return [] }\n    var firstLine = String(text).split(\'\\\\r?\\\\n\')[0]\n    var delimiter = firstLine.indexOf(\'\\t\') >= 0 ? \'\\t\' : (firstLine.indexOf(\'|\') >= 0 ? \'\\\\|\' : \',\')\n    var arr = firstLine.split(delimiter)\n    var names = []\n    for (name in arr) {\n        if (!blank(name)) { names.add(String(name).trim()) }\n    }\n    // 返回当前业务分支的标准结果。\n    return names\n}\n\nvar columnCount = () => {\n    if (body?.columns != null) { return body.columns.size() }\n    if (cfg.columns != null) { return cfg.columns.size() }\n    var jsonSample = first([\'responseSample\', \'requestBody\', \'apiBody\', \'sampleMessage\', \'kafkaSampleMessage\', \'sampleJson\'])\n    var parsed = parseJson(jsonSample)\n    if (parsed != null) { return countJsonFields(parsed) }\n    var header = first([\'headerRow\', \'sampleText\', \'fileContent\', \'csvSample\'])\n    // 返回当前业务分支的标准结果。\n    return splitHeader(header).size()\n}\n\nvar virtualTable = (name, comment, kind) => {\n    // 返回当前业务分支的标准结果。\n    return {\n        tableName: name,\n        tableComment: comment,\n        schemaName: kind,\n        tableType: kind,\n        metadataKind: kind,\n        virtualTable: true,\n        fieldCount: columnCount()\n    }\n}\n\nif (manifestKey == \'source.api\' || manifestKey == \'api\') {\n    var url = first([\'apiUrl\', \'url\'])\n    var name = first([\'resourceName\', \'apiName\', \'tableName\', \'name\'])\n    if (blank(name) && !blank(url)) {\n        var parts = String(url).split(\'/\')\n        name = parts[parts.length - 1]\n    }\n    if (blank(name)) { name = \'api_payload\' }\n    var item = virtualTable(name, \'HTTP API 请求/响应数据结构\', \'API\')\n    item.url = url\n    item.method = first([\'apiMethod\', \'method\']) == null ? \'GET\' : first([\'apiMethod\', \'method\'])\n    // 返回当前业务分支的标准结果。\n    return { success: true, tables: [item], total: 1, sourceType: \'api\' }\n}\n\nif (manifestKey == \'source.kafka\' || manifestKey == \'kafka\') {\n    var topic = first([\'kafkaTopic\', \'topic\'])\n    if (blank(topic)) { topic = \'kafka_message\' }\n    var item = virtualTable(topic, \'Kafka Topic 消息结构\', \'KAFKA\')\n    item.bootstrapServers = first([\'kafkaBootstrapServers\', \'bootstrapServers\'])\n    // 返回当前业务分支的标准结果。\n    return { success: true, tables: [item], total: 1, sourceType: \'kafka\' }\n}\n\nif (manifestKey == \'source.ftp\' || manifestKey == \'ftp\' || manifestKey == \'sftp\') {\n    var protocol = first([\'ftpProtocol\', \'protocol\'])\n    if (blank(protocol)) { protocol = \'ftp\' }\n    var path = first([\'ftpPath\', \'path\', \'fileName\'])\n    var name = first([\'resourceName\', \'tableName\', \'fileName\'])\n    if (blank(name) && !blank(path)) {\n        var parts = String(path).split(\'/\')\n        name = parts[parts.length - 1]\n    }\n    if (blank(name)) { name = protocol + \'_file\' }\n    var item = virtualTable(name, String(protocol).toUpperCase() + \' 文件结构\', String(protocol).toUpperCase())\n    item.path = path\n    item.host = first([\'ftpHost\', \'hostname\', \'host\'])\n    // 返回当前业务分支的标准结果。\n    return { success: true, tables: [item], total: 1, sourceType: String(protocol).toLowerCase() }\n}\n\nvar response = connectionTestController.tablesProbe(body)\n// 返回当前业务分支的标准结果。\nreturn response.getBody()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/03.统一表结构探查(NiFi兼容).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_nifi_columns_probe_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_nifi_columns_probe_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "04.统一字段结构探查(NiFi兼容)",\n  "createTime": 1783639496542,\n  "updateTime": 1784437772005,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/columns-probe",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"manifestKey\\": \\"source.mysql\\",\\n    \\"config\\": {\\n        \\"host\\": \\"127.0.0.1\\",\\n        \\"port\\": 3306,\\n        \\"database\\": \\"test\\",\\n        \\"username\\": \\"root\\",\\n        \\"password\\": \\"***\\"\\n    },\\n    \\"table\\": \\"sys_user\\",\\n    \\"columns\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "API/Kafka 支持从 JSON 请求体、响应样例、消息样例推导字段；FTP/SFTP 支持从 CSV/TSV 表头或前端传入 columns 推导字段；使用请求参数 config、manifestKey、columns、table。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.统一字段结构探查(NiFi兼容)\n// 路由：POST /dst/database/metadata/columns-probe\n// 业务说明：API/Kafka 支持从 JSON 请求体、响应样例、消息样例推导字段；FTP/SFTP 支持从 CSV/TSV 表头或前端传入 columns 推导字段；使用请求参数 config、manifestKey、columns、table。\nimport com.linewell.dataelement.integrated.nifi.canvas.controller.ConnectionTestController as connectionTestController\nimport com.fasterxml.jackson.databind.ObjectMapper\nimport java.util.Map\nimport java.util.List\n\n// 统一字段/结构探查。\n// API/Kafka 支持从 JSON 请求体、响应样例、消息样例推导字段；FTP/SFTP 支持从 CSV/TSV 表头或前端传入 columns 推导字段。\n// 关系型数据库继续走 NiFi JDBC DatabaseMetaData，覆盖 OB、人大金仓、达梦、高斯、DB2、ClickHouse、GBase、Oscar、HighGo、TDSQL 等驱动型元数据。\n\nvar mapper = new ObjectMapper()\nvar blank = (value) => value == null || String(value).trim() == \'\'\n// 解析请求体并为可选参数设置默认值。\nvar cfg = body?.config == null ? {} : body.config\nvar manifestKey = body?.manifestKey == null ? \'\' : String(body.manifestKey).toLowerCase()\n\nvar first = (keys) => {\n    for (key in keys) {\n        var value = cfg[key]\n        if (blank(value) && body != null) {\n            value = body[key]\n        }\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar parseJson = (text) => {\n    if (blank(text)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return mapper.readValue(String(text), Object.class)\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n}\n\nvar guessType = (value) => {\n    if (value == null) { return \'VARCHAR\' }\n    if (value instanceof Map) { return \'OBJECT\' }\n    if (value instanceof List) { return \'ARRAY\' }\n    var s = String(value)\n    if (s == \'true\' || s == \'false\') { return \'BOOLEAN\' }\n    if (s.matches(\'^-?\\\\d+$\')) { return \'BIGINT\' }\n    if (s.matches(\'^-?\\\\d+\\\\.\\\\d+$\')) { return \'DECIMAL\' }\n    if (s.matches(\'^\\\\d{4}-\\\\d{2}-\\\\d{2}.*\')) { return \'TIMESTAMP\' }\n    // 返回当前业务分支的标准结果。\n    return \'VARCHAR\'\n}\n\nvar addColumn = (columns, name, value, comment) => {\n    if (blank(name)) { return }\n    columns.add({\n        columnName: String(name),\n        columnComment: blank(comment) ? String(name) : comment,\n        dataType: guessType(value),\n        typeName: guessType(value),\n        nullable: true,\n        primaryKey: false,\n        ordinalPosition: columns.size() + 1,\n        virtualColumn: true\n    })\n}\n\nvar walk = null\nwalk = (columns, prefix, value) => {\n    if (value instanceof Map) {\n        for (entry in value.entrySet()) {\n            var name = blank(prefix) ? String(entry.getKey()) : prefix + \'.\' + entry.getKey()\n            var child = entry.getValue()\n            if (child instanceof Map) {\n                walk(columns, name, child)\n            } else if (child instanceof List) {\n                if (child.size() > 0 && child[0] instanceof Map) {\n                    walk(columns, name, child[0])\n                } else {\n                    addColumn(columns, name, child, name)\n                }\n            } else {\n                addColumn(columns, name, child, name)\n            }\n        }\n    } else if (value instanceof List) {\n        if (value.size() > 0) {\n            walk(columns, prefix, value[0])\n        }\n    }\n}\n\nvar normalizeColumns = (rawColumns) => {\n    var columns = []\n    if (rawColumns == null) { return columns }\n    for (item in rawColumns) {\n        if (item instanceof Map) {\n            var name = item.columnName == null ? (item.name == null ? item.colName : item.name) : item.columnName\n            columns.add({\n                columnName: name,\n                columnComment: item.columnComment == null ? (item.comment == null ? name : item.comment) : item.columnComment,\n                dataType: item.dataType == null ? (item.type == null ? \'VARCHAR\' : item.type) : item.dataType,\n                typeName: item.typeName == null ? (item.type == null ? \'VARCHAR\' : item.type) : item.typeName,\n                nullable: item.nullable == null ? true : item.nullable,\n                primaryKey: item.primaryKey == null ? false : item.primaryKey,\n                ordinalPosition: columns.size() + 1,\n                virtualColumn: true\n            })\n        } else if (!blank(item)) {\n            addColumn(columns, String(item), null, String(item))\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return columns\n}\n\nvar splitHeaderColumns = (text) => {\n    var columns = []\n    if (blank(text)) { return columns }\n    var firstLine = String(text).split(\'\\\\r?\\\\n\')[0]\n    var delimiter = firstLine.indexOf(\'\\t\') >= 0 ? \'\\t\' : (firstLine.indexOf(\'|\') >= 0 ? \'\\\\|\' : \',\')\n    var arr = firstLine.split(delimiter)\n    for (name in arr) {\n        if (!blank(name)) {\n            addColumn(columns, String(name).trim(), null, String(name).trim())\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return columns\n}\n\nvar nonTableColumns = () => {\n    var raw = body?.columns == null ? cfg.columns : body.columns\n    var columns = normalizeColumns(raw)\n    if (columns.size() > 0) { return columns }\n\n    var sample = first([\'responseSample\', \'requestBody\', \'apiBody\', \'sampleMessage\', \'kafkaSampleMessage\', \'sampleJson\'])\n    var parsed = parseJson(sample)\n    if (parsed != null) {\n        walk(columns, \'\', parsed)\n        if (columns.size() > 0) { return columns }\n    }\n\n    var header = first([\'headerRow\', \'sampleText\', \'fileContent\', \'csvSample\'])\n    columns = splitHeaderColumns(header)\n    // 返回当前业务分支的标准结果。\n    return columns\n}\n\nvar virtualTableName = () => {\n    var name = body?.table\n    if (!blank(name)) { return name }\n    name = first([\'tableName\', \'resourceName\', \'apiName\', \'kafkaTopic\', \'topic\', \'fileName\'])\n    if (!blank(name)) { return name }\n    if (manifestKey == \'source.api\' || manifestKey == \'api\') { return \'api_payload\' }\n    if (manifestKey == \'source.kafka\' || manifestKey == \'kafka\') { return \'kafka_message\' }\n    if (manifestKey == \'source.ftp\' || manifestKey == \'ftp\' || manifestKey == \'sftp\') { return \'ftp_file\' }\n    // 返回当前业务分支的标准结果。\n    return \'virtual_structure\'\n}\n\nif (manifestKey == \'source.api\' || manifestKey == \'api\' || manifestKey == \'source.kafka\' || manifestKey == \'kafka\' || manifestKey == \'source.ftp\' || manifestKey == \'ftp\' || manifestKey == \'sftp\') {\n    var columns = nonTableColumns()\n    // 返回当前业务分支的标准结果。\n    return {\n        success: true,\n        table: virtualTableName(),\n        columns: columns,\n        total: columns.size(),\n        sourceType: manifestKey,\n        virtualTable: true,\n        error: columns.size() == 0 ? \'未提供可识别的样例数据或表头；请上传样例文件、填写请求/响应样例，或传入 columns。\' : \'\'\n    }\n}\n\nvar response = connectionTestController.columnsProbe(body)\n// 返回当前业务分支的标准结果。\nreturn response.getBody()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/04.统一字段结构探查(NiFi兼容).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_tables_preview_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_tables_preview_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "05.轻量探查数据库表(预览别名)",\n  "createTime": 1783639496542,\n  "updateTime": 1789378460165,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables/preview",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dbId\\": \\"codex_kingbase_firmament_data_v6\\",\\n    \\"pageNo\\": 1,\\n    \\"pageSize\\": 50,\\n    \\"keyword\\": \\"\\",\\n    \\"schemaName\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"pageNo\\": 1,\\n  \\"pageSize\\": 50,\\n  \\"total\\": 350,\\n  \\"rows\\": []\\n}",\n  "description": "轻量探查数据库表（POST /dst/database/metadata/tables/preview）。从 db_datasource_t 读取连接信息，调用 MetadataExplorerService 分页读取物理库表/视图摘要；Oracle 默认限定为登录用户，仅返回当前连接可探查且包含对象的用户列表，schemaName 可切换指定用户，旧的失效选择会自动回退；无关键字全量口径会把探查总表数同步回 db_datasource_t.table_num，供数据源管理列表统计使用；前端第二步使用 pageNo/pageSize 加载更多，旧 limit 调用继续兼容；使用请求参数 dbId、silent、keyword、limit、pageNo、pageSize、schemaName、annotationStatus；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.轻量探查数据库表(预览别名)\n// 路由：POST /dst/database/metadata/tables/preview\n// 业务说明：轻量探查数据库表（POST /dst/database/metadata/tables/preview）。从 db_datasource_t 读取连接信息，调用 MetadataExplorerService 分页读取物理库表/视图摘要；Oracle 默认限定为登录用户，仅返回当前连接可探查且包含对象的用户列表，schemaName 可切换指定用户，旧的失效选择会自动回退；无关键字全量口径会把探查总表数同步回 db_datasource_t.table_num，供数据源管理列表统计使用；前端第二步使用 pageNo/pageSize 加载更多，旧 limit 调用继续兼容；使用请求参数 dbId、silent、keyword、limit、pageNo、pageSize、schemaName、annotationStatus；执行数据库写入并返回处理结果。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport com.linewell.dataelement.metautil.structured.StructuredSourceProbeService as structuredSourceProbeService\nimport tenantRuntime\nimport java.util.Map\nimport java.util.Date\nimport java.util.ArrayList\nimport java.util.HashSet\n\n/*\n * 元数据管理 05：轻量预览物理数据库表/视图。\n * 轻写：不写 db_table_t / db_table_column_t；无关键字探查时只同步 db_datasource_t.table_num。\n * 新流程优先使用数据库侧分页，避免 Kingbase、Oracle 等大库首次进入时全量探查。\n */\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => blank(value) ? \'\' : textOf(value).toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            return value\n        }\n    }\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        return null\n    }\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    if (main == null) {\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']),\n        id: rowValue(main, [\'tid\']),\n        assetType: \'db\',\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\']),\n        appId: rowValue(main, [\'appId\', \'app_id\']),\n        orgId: rowValue(main, [\'orgId\', \'org_id\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        return DatabaseType.MYSQL\n    }\n    try {\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\n\nvar dbId = body == null ? null : body.dbId\nvar silent = body != null && body.silent == true\nif (blank(dbId)) {\n    if (silent) {\n        return { found: false, rows: [], list: [], total: 0, physicalTotal: 0 }\n    }\n    exit 400, \'dbId 不能为空\'\n}\nvar asset = loadAsset(dbId)\nif (asset == null) {\n    if (silent) {\n        return { found: false, rows: [], list: [], total: 0, physicalTotal: 0 }\n    }\n    exit 404, \'数据源资产不存在\'\n}\n\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'登录状态已失效，请重新登录\'\n}\n\nvar keyword = lower(body == null ? null : body.keyword)\nvar limit = body == null || body.limit == null ? 200 : body.limit::int\nvar pageNo = body == null || body.pageNo == null ? null : body.pageNo::int\nvar pageSize = body == null || body.pageSize == null ? null : body.pageSize::int\nvar paged = pageNo != null || pageSize != null\nvar unlimited = limit <= 0\nvar tables = []\nvar total = 0\nvar physicalTotal = 0\nvar sourceType = lower(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\nvar structuredSource = sourceType == \'api\' || sourceType == \'ftp\' || sourceType == \'kafka\'\nvar oracleSource = sourceType == \'oracle\'\nvar loginUsername = textOf(firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\']))\nvar loginSchema = blank(loginUsername) ? null : textOf(loginUsername).trim().toUpperCase()\nvar requestedSchema = body == null ? null : body.schemaName\nvar selectedSchema = null\nvar metadataConfig = dataSourceOf(asset)\nvar schemaOptions = new ArrayList()\nif (oracleSource) {\n    selectedSchema = blank(requestedSchema) ? loginSchema : textOf(requestedSchema).trim().toUpperCase()\n    // 仅返回当前连接可通过 ALL_TABLES / ALL_VIEWS 探查、且至少有一个对象的\n    // Owner。该服务在 Oracle 侧用一次聚合查询完成，不能在这里逐用户探查。\n    var availableSchemas = metadataExplorerService.getSchemasWithTables(metadataConfig)\n    var availableSchemaSet = new HashSet()\n    schemaOptions = new ArrayList()\n    for (schemaOption in availableSchemas == null ? [] : availableSchemas) {\n        var normalizedSchema = blank(schemaOption) ? null : textOf(schemaOption).trim().toUpperCase()\n        if (!blank(normalizedSchema) && !availableSchemaSet.contains(normalizedSchema)) {\n            availableSchemaSet.add(normalizedSchema)\n            schemaOptions.add(normalizedSchema)\n        }\n    }\n    // 已保存的选择可能来自旧列表、权限变更或数据源切换。自动回退到当前账号\n    // （若其有可探查对象），否则回退到首个可用 Owner，页面不会再收到 400。\n    if (!blank(selectedSchema) && !availableSchemaSet.contains(selectedSchema)) {\n        if (!blank(loginSchema) && availableSchemaSet.contains(loginSchema)) {\n            selectedSchema = loginSchema\n        } else if (!schemaOptions.isEmpty()) {\n            selectedSchema = schemaOptions.get(0)\n        } else {\n            selectedSchema = loginSchema\n        }\n    }\n    // 当前连接账号有可探查对象时固定排在首位，其他 Owner 保持数据库返回顺序。\n    var orderedSchemas = new ArrayList()\n    if (!blank(loginSchema) && availableSchemaSet.contains(loginSchema)) {\n        orderedSchemas.add(loginSchema)\n    }\n    for (schemaOption in schemaOptions) {\n        if (lower(schemaOption) != lower(loginSchema)) {\n            orderedSchemas.add(schemaOption)\n        }\n    }\n    schemaOptions = orderedSchemas\n    metadataConfig.setSchema(selectedSchema)\n}\nvar physicalTableName = (table) => {\n    var name = table == null ? null : table.tableName\n    if (!oracleSource || blank(name)) {\n        return name\n    }\n    var owner = table.schemaName\n    if (blank(owner) || lower(owner) == lower(loginUsername) || textOf(name).indexOf(\'.\') >= 0) {\n        return name\n    }\n    return textOf(owner) + \'.\' + textOf(name)\n}\nvar annotationStatus = lower(body == null ? null : body.annotationStatus)\nvar unmarkedOnly = annotationStatus == \'unmarked\'\nvar pendingOnly = annotationStatus == \'pending\'\n// “暂不处理”只读取已保存的 db_table_t 草稿快照并在控制库分页，\n// 不再为了筛选该分类枚举全部物理表。物理表删除仍由用户显式“重新探查”确认。\nif (pendingOnly) {\n    var safePendingPageNo = pageNo == null || pageNo < 1 ? 1 : pageNo\n    var safePendingPageSize = pageSize == null || pageSize < 1 ? 100 : Math.min(pageSize, 100)\n    var pendingQuery = db.table(\'db_table_t\').where()\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'datasource_id\', dbId)\n        .eq(\'is_del\', 0)\n        .in(\'business_type\', [\'暂不处理\', \'不确定\'])\n    if (!blank(keyword)) {\n        pendingQuery.like(\'table_name\', \'%\' + keyword + \'%\')\n    }\n    var pendingPage = pendingQuery.orderBy(\'updated_time\', \'desc\')\n        .page(safePendingPageSize, (safePendingPageNo - 1) * safePendingPageSize)\n    var pendingRows = pendingPage == null || pendingPage.list == null ? [] : pendingPage.list\n    var pendingTotal = pendingPage == null || pendingPage.total == null ? pendingRows.size() : pendingPage.total\n    var pendingPreviewRows = new ArrayList()\n    for (pendingRow in pendingRows) {\n        var pendingTableName = firstValue(pendingRow, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\n        if (blank(pendingTableName)) {\n            continue\n        }\n        var pendingResourceName = firstValue(pendingRow, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\'])\n        pendingPreviewRows.add({\n            dbId: dbId,\n            tid: firstValue(pendingRow, [\'tid\']),\n            tableId: firstValue(pendingRow, [\'tid\']),\n            tableName: pendingTableName,\n            tableNameEn: pendingTableName,\n            physicalTableComment: pendingResourceName,\n            savedResourceName: pendingResourceName,\n            tableNameCn: pendingResourceName,\n            tableComment: pendingResourceName,\n            tableType: firstValue(pendingRow, [\'tableType\', \'table_type\']),\n            businessType: firstValue(pendingRow, [\'businessType\', \'business_type\']),\n            businessTypeReason: firstValue(pendingRow, [\'businessTypeReason\', \'business_type_reason\']),\n            schemaName: firstValue(pendingRow, [\'schemaName\', \'schema_name\']),\n            recordCount: firstValue(pendingRow, [\'recordCount\', \'record_count\']) == null ? 0 : firstValue(pendingRow, [\'recordCount\', \'record_count\']),\n            fieldCount: firstValue(pendingRow, [\'fieldCount\', \'field_count\', \'columnCount\', \'column_count\']) == null ? 0 : firstValue(pendingRow, [\'fieldCount\', \'field_count\', \'columnCount\', \'column_count\']),\n            storageSize: firstValue(pendingRow, [\'storageSize\', \'storage_size\', \'totalSizeFormatted\', \'total_size_formatted\']) || \'0 B\',\n            totalSizeFormatted: firstValue(pendingRow, [\'totalSizeFormatted\', \'total_size_formatted\', \'storageSize\', \'storage_size\']) || \'0 B\',\n            totalSizeBytes_num: firstValue(pendingRow, [\'totalSizeBytes\', \'total_size_bytes\']) == null ? 0 : firstValue(pendingRow, [\'totalSizeBytes\', \'total_size_bytes\']),\n            annotated: false,\n            registered: false\n        })\n    }\n    return {\n        found: true,\n        dbId: dbId,\n        pageNo: safePendingPageNo,\n        pageSize: safePendingPageSize,\n        total: pendingTotal,\n        physicalTotal: pendingTotal,\n        annotationStatus: annotationStatus,\n        oracle: oracleSource,\n        selectedSchema: selectedSchema,\n        schemaOptions: schemaOptions,\n        rows: pendingPreviewRows,\n        list: pendingPreviewRows\n    }\n}\n// validationOnly 不返回表明细，只返回覆盖全部物理表的下一步校验汇总。\n// 它不能使用浏览器当前页数据，否则大库分页时会错误拦截“全部暂不处理”的场景。\nvar validationOnlyValue = body == null ? null : body.validationOnly\nvar validationOnly = validationOnlyValue == true\nif (!validationOnly && validationOnlyValue != null) {\n    validationOnly = lower(validationOnlyValue) == \'true\'\n}\nvar draftMetadataByName = {}\n\nif (unmarkedOnly) {\n    // 标注状态属于平台资产语义，必须在后端完成物理表与 db_table_t 的合并后再分页。\n    // 否则先分页物理表、再由前端剔除已标注表，会出现“总数 173 但首屏 0/21 条”的错页。\n    var managedRows = db.table(\'db_table_t\').where()\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'datasource_id\', dbId)\n        .eq(\'is_del\', 0)\n        .orderBy(\'updated_time\', \'desc\')\n        .select()\n    var registeredNames = new HashSet()\n    var registeredNameList = new ArrayList()\n    // managedRows are newest first. Evaluate each physical table once so a\n    // historical annotated snapshot cannot inflate the current unmarked count.\n    var resolvedManagedNames = new HashSet()\n    for (managed in managedRows == null ? [] : managedRows) {\n        var managedName = lower(firstValue(managed, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\']))\n        var managedInSelectedSchema = true\n        if (oracleSource && !blank(managedName)) {\n            var qualifiedManagedName = managedName.indexOf(\'.\') > 0\n            var selectedPrefix = lower(selectedSchema) + \'.\'\n            if (lower(selectedSchema) == lower(loginSchema)) {\n                managedInSelectedSchema = !qualifiedManagedName || managedName.indexOf(selectedPrefix) == 0\n            } else {\n                managedInSelectedSchema = managedName.indexOf(selectedPrefix) == 0\n            }\n        }\n        if (!blank(managedName) && managedInSelectedSchema && !resolvedManagedNames.contains(managedName)) {\n            resolvedManagedNames.add(managedName)\n            var annotatedValue = lower(rowValue(managed, [\'annotated\']))\n            var isAnnotated = annotatedValue == \'1\' || annotatedValue == \'true\'\n            if (isAnnotated) {\n                if (!registeredNames.contains(managedName)) {\n                    registeredNames.add(managedName)\n                    registeredNameList.add(managedName)\n                }\n            } else if (draftMetadataByName[managedName] == null) {\n                // 重新标注后的资产仍保留用户已填写的中文名和业务分类，重新进入第二步时回填。\n                draftMetadataByName[managedName] = managed\n            }\n        }\n    }\n\n    if (validationOnly) {\n        var validationPhysicalTables = new ArrayList()\n        if (structuredSource) {\n            var summaryPageNo = 1\n            var summaryPageSize = 500\n            var summaryExpectedTotal = 0\n            while (true) {\n                var summaryPage = structuredSourceProbeService.getTablesPage(asset, summaryPageNo, summaryPageSize, null)\n                var summaryRows = summaryPage == null || summaryPage.rows == null ? [] : summaryPage.rows\n                for (summaryRow in summaryRows) {\n                    validationPhysicalTables.add(summaryRow)\n                }\n                summaryExpectedTotal = summaryPage == null || summaryPage.total == null ? validationPhysicalTables.size() : summaryPage.total\n                if (summaryRows.size() < summaryPageSize || validationPhysicalTables.size() >= summaryExpectedTotal) {\n                    break\n                }\n                summaryPageNo = summaryPageNo + 1\n            }\n        } else {\n            validationPhysicalTables = metadataExplorerService.getTables(metadataConfig)\n        }\n\n        var totalUnmarked = 0\n        var pendingUnmarked = 0\n        var blockingUnmarked = 0\n        for (physical in validationPhysicalTables == null ? [] : validationPhysicalTables) {\n            var physicalName = lower(physicalTableName(physical))\n            if (blank(physicalName) || registeredNames.contains(physicalName)) {\n                continue\n            }\n            totalUnmarked = totalUnmarked + 1\n            var draftMetadata = draftMetadataByName[physicalName]\n            var draftType = lower(firstValue(draftMetadata, [\'businessType\', \'business_type\']))\n            if (draftType == \'暂不处理\' || draftType == \'不确定\') {\n                pendingUnmarked = pendingUnmarked + 1\n            } else {\n                blockingUnmarked = blockingUnmarked + 1\n            }\n        }\n        return {\n            found: true,\n            dbId: dbId,\n            totalUnmarked: totalUnmarked,\n            pendingUnmarked: pendingUnmarked,\n            blockingUnmarked: blockingUnmarked,\n            canProceed: blockingUnmarked == 0,\n            oracle: oracleSource,\n            selectedSchema: selectedSchema,\n            schemaOptions: schemaOptions\n        }\n    }\n\n    if (structuredSource) {\n        // 文件、对象存储和 API 等结构化来源的单页上限是 500；这里必须继续读取\n        // 后续页，再合并已登记快照并计算“未标注”总数。只取第一页会把第 501 条\n        // 之后的表误判为不存在，页面随即错误显示“数据表标注已完成”。\n        var allPhysicalTables = new ArrayList()\n        var structuredPageNo = 1\n        var structuredPageSize = 500\n        var structuredExpectedTotal = 0\n        while (true) {\n            var structuredPage = structuredSourceProbeService.getTablesPage(\n                asset,\n                structuredPageNo,\n                structuredPageSize,\n                textOf(body == null ? null : body.keyword)\n            )\n            var structuredRows = structuredPage == null || structuredPage.rows == null ? [] : structuredPage.rows\n            for (structuredRow in structuredRows) {\n                allPhysicalTables.add(structuredRow)\n            }\n            structuredExpectedTotal = structuredPage == null || structuredPage.total == null\n                ? allPhysicalTables.size()\n                : structuredPage.total\n            if (structuredRows.size() < structuredPageSize || allPhysicalTables.size() >= structuredExpectedTotal) {\n                break\n            }\n            structuredPageNo = structuredPageNo + 1\n        }\n        physicalTotal = structuredExpectedTotal\n        var unmarkedTables = new ArrayList()\n        for (physical in allPhysicalTables == null ? [] : allPhysicalTables) {\n            var physicalName = lower(physical.tableName)\n            var physicalComment = lower(physical.tableComment)\n            var keywordMatched = blank(keyword) || physicalName.indexOf(keyword) >= 0 || physicalComment.indexOf(keyword) >= 0\n            if (keywordMatched && !registeredNames.contains(physicalName)) {\n                unmarkedTables.add(physical)\n            }\n        }\n        total = unmarkedTables.size()\n        var safePageNo = pageNo == null || pageNo < 1 ? 1 : pageNo\n        var safePageSize = pageSize == null || pageSize < 1 ? 100 : pageSize\n        var fromIndex = (safePageNo - 1) * safePageSize\n        var toIndex = Math.min(fromIndex + safePageSize, total)\n        tables = fromIndex >= total ? [] : unmarkedTables.subList(fromIndex, toIndex)\n    } else {\n        var unmarkedPage = metadataExplorerService.getTablesPageExcluding(\n            metadataConfig,\n            pageNo == null || pageNo < 1 ? 1 : pageNo,\n            pageSize == null || pageSize < 1 ? 100 : pageSize,\n            textOf(body == null ? null : body.keyword),\n            registeredNameList\n        )\n        tables = unmarkedPage == null || unmarkedPage.rows == null ? [] : unmarkedPage.rows\n        total = unmarkedPage == null || unmarkedPage.total == null ? 0 : unmarkedPage.total\n        physicalTotal = total + registeredNames.size()\n    }\n} else if (structuredSource) {\n    var structuredPage = structuredSourceProbeService.getTablesPage(\n        asset,\n        paged ? pageNo : 1,\n        paged ? pageSize : (unlimited ? 500 : limit),\n        textOf(body == null ? null : body.keyword)\n    )\n    tables = structuredPage == null || structuredPage.rows == null ? [] : structuredPage.rows\n    total = structuredPage == null || structuredPage.total == null ? 0 : structuredPage.total\n    physicalTotal = total\n} else if (paged) {\n    var page = metadataExplorerService.getTablesPage(metadataConfig, pageNo, pageSize, textOf(body == null ? null : body.keyword))\n    tables = page == null || page.rows == null ? [] : page.rows\n    total = page == null || page.total == null ? 0 : page.total\n    physicalTotal = total\n} else {\n    tables = metadataExplorerService.getTables(metadataConfig)\n    total = tables == null ? 0 : tables.size()\n    physicalTotal = total\n}\n\n// 只有无关键字时，total 才代表该数据源的物理库表总数；关键字过滤后的 total 不能回写。\nif (blank(body == null ? null : body.keyword) && physicalTotal > 0) {\n    var oldDatasource = db.table(\'db_datasource_t\').where().eq(\'tid\', dbId).eq(\'is_del\', 0).selectOne()\n    var oldTableNum = oldDatasource == null ? 0 : (rowValue(oldDatasource, [\'tableNum\', \'table_num\']) == null ? 0 : rowValue(oldDatasource, [\'tableNum\', \'table_num\'])::int)\n    if (physicalTotal > oldTableNum) {\n        db.table(\'db_datasource_t\').primary(\'tid\').update({ tid: dbId, table_num: physicalTotal, updated_time: new Date() }, true)\n    }\n}\n\nvar rows = []\nfor (table in tables == null ? [] : tables) {\n    var tableName = physicalTableName(table)\n    var tableComment = blank(table.tableComment) ? tableName : table.tableComment\n    var draftMetadata = draftMetadataByName[lower(tableName)]\n    // Keep the physical comment separately for traceability.  The data-resource\n    // name is editable business metadata, so an already saved name must be\n    // returned as the display value instead of being overwritten by an older\n    // physical-table comment on blur or after a reload.\n    var savedResourceName = firstValue(draftMetadata, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\'])\n    var displayResourceName = blank(savedResourceName) ? tableComment : savedResourceName\n    if (!paged && !blank(keyword) && lower(tableName).indexOf(keyword) < 0 && lower(tableComment).indexOf(keyword) < 0) {\n        continue\n    }\n    rows.add({\n        dbId: dbId,\n        tableName: tableName,\n        tableNameEn: tableName,\n        physicalTableComment: tableComment,\n        savedResourceName: savedResourceName,\n        tableNameCn: displayResourceName,\n        tableComment: displayResourceName,\n        tableType: table.tableType,\n        businessType: firstValue(draftMetadata, [\'businessType\', \'business_type\']),\n        businessTypeReason: firstValue(draftMetadata, [\'businessTypeReason\', \'business_type_reason\']),\n        schemaName: table.schemaName,\n        recordCount: table.rowCount == null ? 0 : table.rowCount,\n        fieldCount: table.columnCount == null ? 0 : table.columnCount,\n        columns: structuredSource ? table.columns : null,\n        storageSize: blank(table.totalSizeFormatted) ? \'0 B\' : table.totalSizeFormatted,\n        totalSizeFormatted: blank(table.totalSizeFormatted) ? \'0 B\' : table.totalSizeFormatted,\n        totalSizeBytes_num: table.totalSizeBytes == null ? 0 : table.totalSizeBytes\n    })\n    if (!paged && !unlimited && rows.size() >= limit) {\n        break\n    }\n}\n\nif (paged) {\n    return {\n        pageNo: pageNo == null || pageNo < 1 ? 1 : pageNo,\n        pageSize: pageSize == null || pageSize < 1 ? 50 : pageSize,\n        total: total,\n        physicalTotal: physicalTotal,\n        annotationStatus: annotationStatus,\n        oracle: oracleSource,\n        selectedSchema: selectedSchema,\n        schemaOptions: schemaOptions,\n        rows: rows,\n        list: rows\n    }\n}\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/05.轻量探查数据库表(预览别名).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('52e398a9f2fc429da79048b9ea719b37',NULL,NULL,'{\n  "properties": {},\n  "id": "52e398a9f2fc429da79048b9ea719b37",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "06.获取表列表",\n  "createTime": 1782955344303,\n  "updateTime": 1790483136251,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "dbId",\n      "value": "codex_kingbase_firmament_data_v6",\n      "description": "数据源ID",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "paged",\n      "value": "false",\n      "description": "true时返回第二步已标注表分页结果，默认保持数组响应兼容旧调用",\n      "required": false,\n      "dataType": "Boolean",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "pageNo",\n      "value": "1",\n      "description": "分页页码",\n      "required": false,\n      "dataType": "Integer",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "pageSize",\n      "value": "50",\n      "description": "每页条数，最大100",\n      "required": false,\n      "dataType": "Integer",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "businessType",\n      "value": "",\n      "description": "可选业务类型筛选",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "keyword",\n      "value": "",\n      "description": "按数据表英文名或数据资源中文名筛选",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "annotatedOnly",\n      "value": null,\n      "description": "审查页仅返回已标注表及保存配置；与第二步已标注列表去重口径一致",\n      "required": false,\n      "dataType": "Boolean",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "includeGovernance",\n      "value": "true",\n      "description": "是否返回字段治理配置；第五步首屏传 false，展开单表时再读取完整配置",\n      "required": false,\n      "dataType": "Boolean",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "获取当前数据源已保存的数据表快照（GET /dst/database/metadata/tables）。默认返回数组兼容步骤三至五；paged=true 时按租户、数据源、业务类型和名称关键词在数据库侧去重分页，供登记第二步右侧列表使用；不连接物理数据源；涉及 db_datasource_t、metadata_table_collection_job_t、db_table_t、da_catalog_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.获取表列表\n// 路由：GET /dst/database/metadata/tables\n// 业务说明：获取当前数据源已保存的数据表快照（GET /dst/database/metadata/tables）。默认返回数组兼容步骤三至五；paged=true 时按租户、数据源、业务类型和名称关键词在数据库侧去重分页，供登记第二步右侧列表使用；不连接物理数据源；涉及 db_datasource_t、metadata_table_collection_job_t、db_table_t、da_catalog_t 等业务表。\nimport java.util.Map\nimport jsons\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n\n/*\n * 元数据管理 06：读取当前数据源的表资产快照。\n * 标注状态的事实来源是 db_table_t；物理表实时清单由 /tables/preview 提供。\n */\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\n// 第五步大数据源首屏只需要表级摘要。默认保留完整治理配置，传 false 时显式省略大字段。\nvar includeGovernanceFlag = !(textOf(includeGovernance).trim().toLowerCase() == \'false\' || textOf(includeGovernance) == \'0\')\nvar rowValue = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) { return value }\n    }\n    return null\n}\n\nvar tableItem = (row, datasource) => {\n    var tid = rowValue(row, [\'tid\'])\n    var datasourceId = firstValue(row, [\'datasourceId\', \'datasource_id\'])\n    var tableName = firstValue(row, [\'tableName\', \'table_name\'])\n    var item = {\n        tid: tid,\n        id: tid,\n        assetType: \'table\',\n        datasourceId: datasourceId,\n        dbId: datasourceId,\n        tableName: tableName,\n        tableNameEn: firstValue(row, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\']),\n        // This endpoint is the persisted registration snapshot used by the\n        // right pane, so its resource name must not be replaced by a physical\n        // database comment returned from a later exploration.\n        registeredResourceName: firstValue(row, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\']),\n        tableNameCn: firstValue(row, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']),\n        tableComment: firstValue(row, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\']),\n        tableType: firstValue(row, [\'tableType\', \'table_type\']),\n        businessType: firstValue(row, [\'businessType\', \'business_type\']),\n        businessTypeReason: firstValue(row, [\'businessTypeReason\', \'business_type_reason\']),\n        annotated: rowValue(row, [\'annotated\']),\n        recordCount: rowValue(row, [\'recordCount\', \'record_count\']),\n        fieldCount: rowValue(row, [\'fieldCount\', \'field_count\']),\n        storageSize: firstValue(row, [\'storageSize\', \'storage_size\']),\n        totalSizeBytes: rowValue(row, [\'totalSizeBytes\', \'total_size_bytes\']),\n        totalSizeFormatted: firstValue(row, [\'totalSizeFormatted\', \'total_size_formatted\', \'storageSize\', \'storage_size\']),\n        orgId: firstValue(row, [\'orgId\', \'org_id\', \'manageUnit\', \'manage_unit\']),\n        orgPath: firstValue(row, [\'orgPath\', \'org_path\']),\n        appId: firstValue(row, [\'appId\', \'app_id\']),\n        relatedDirectory: firstValue(row, [\'relatedDirectory\', \'related_directory\']),\n        dataSourceType: firstValue(row, [\'dataSourceType\', \'data_source_type\']),\n        timestampField: firstValue(row, [\'timestampField\', \'timestamp_field\']),\n        dictionaryStructureType: firstValue(row, [\'dictionaryStructureType\', \'dictionary_structure_type\']),\n        dictionaryTableFlag: rowValue(row, [\'dictionaryTableFlag\', \'dictionary_table_flag\']),\n        sourceCatalogId: firstValue(row, [\'sourceCatalogId\', \'source_catalog_id\']),\n        sourceTableId: firstValue(row, [\'sourceTableId\', \'source_table_id\', \'tid\']),\n        sourceTableName: firstValue(row, [\'sourceTableName\', \'source_table_name\', \'tableName\', \'table_name\']),\n        manageUnit: firstValue(row, [\'manageUnit\', \'manage_unit\', \'orgId\', \'org_id\']),\n        assetDesc: firstValue(row, [\'assetDesc\', \'asset_desc\', \'tableComment\', \'table_comment\']),\n        catalogName: firstValue(row, [\'catalogName\', \'catalog_name\', \'tableNameCn\', \'table_name_cn\']),\n        catalogNameEn: firstValue(row, [\'catalogNameEn\', \'catalog_name_en\', \'tableName\', \'table_name\']),\n        tenantId: firstValue(row, [\'tenantId\', \'tenant_id\']),\n        assetStatus: rowValue(row, [\'assetStatus\', \'asset_status\']),\n        flowStatus: rowValue(row, [\'flowStatus\', \'flow_status\']),\n        regTime: rowValue(row, [\'regTime\', \'reg_time\']),\n        createdTime: rowValue(row, [\'createdTime\', \'created_time\']),\n        updatedTime: rowValue(row, [\'updatedTime\', \'updated_time\']),\n        dbName: firstValue(datasource, [\'dbName\', \'db_name\'])\n    }\n    if (blank(item.appId)) { item.appId = firstValue(datasource, [\'appId\', \'app_id\']) }\n    if (blank(item.orgId)) { item.orgId = firstValue(datasource, [\'orgId\', \'org_id\']) }\n    item.regTime_date = item.regTime\n    item.createdTime_date = item.createdTime\n    item.updatedTime_date = item.updatedTime\n    if (includeGovernanceFlag) {\n        item.fieldGovernanceConfig = rowValue(row, [\'fieldGovernanceConfig\', \'field_governance_config\'])\n        item.dictionaryProfiles = rowValue(row, [\'dictionaryProfiles\', \'dictionary_profiles\'])\n        item.dictionaryProfile = rowValue(row, [\'dictionaryProfile\', \'dictionary_profile\'])\n        item.dictionaryCategories = rowValue(row, [\'dictionaryCategories\', \'dictionary_categories\'])\n    }\n    return item\n}\n\nif (blank(dbId)) {\n    exit 400, \'dbId 不能为空\'\n}\n\nvar datasource = db.table(\'db_datasource_t\')\n    .columns(\'tid\', \'db_name\', \'app_id\', \'org_id\', \'tenant_id\')\n    .where().eq(\'tid\', dbId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n\n/* 登记目录抽屉：复用同一 db_table_t 采集快照，按目录关联状态真分页。\n * 只读、不连接源库、不写资产；不传 catalogPaged 时保持第二步原有接口行为。\n */\nif (textOf(catalogPaged) == \'1\' || textOf(catalogPaged).toLowerCase() == \'true\') {\n    if (datasource == null) { exit 404, \'数据源不存在或无访问权限\' }\n    var safePageNo = pageNo == null || pageNo::int < 1 ? 1 : pageNo::int\n    var safePageSize = pageSize == null || pageSize::int < 1 ? 20 : Math.min(pageSize::int, 100)\n    var registeredMode = textOf(catalogStatus) == \'registered\'\n    var selectedBusinessType = blank(businessType) || textOf(businessType) == \'全部\' ? null : textOf(businessType)\n    var tableKeywords = []\n    for (word in textOf(tableNames).split(\'\\n\')) {\n        if (!blank(word)) { tableKeywords.add(\'%\' + textOf(word).trim().toLowerCase() + \'%\') }\n    }\n    var catalogKeywords = []\n    for (word in textOf(catalogNames).split(\'\\n\')) {\n        if (!blank(word)) { catalogKeywords.add(\'%\' + textOf(word).trim().toLowerCase() + \'%\') }\n    }\n    // 与第二步一致：采集未匹配的未标注行不回到待登记；已标注和目录关联行保留。\n    var missingNames = []\n    if (textOf(checkCollectionMissing) == \'1\') {\n        var job = db.table(\'metadata_table_collection_job_t\').columns(\'deleted_detail\')\n            .where().eq(\'tenant_id\', tenantId).eq(\'datasource_id\', dbId)\n            .eq(\'status\', \'SUCCEEDED\').eq(\'is_del\', 0)\n            .orderBy(\'created_time\', \'desc\').orderBy(\'tid\', \'desc\').selectOne()\n        var detail = rowValue(job, [\'deletedDetail\', \'deleted_detail\'])\n        if (!blank(detail)) {\n            for (missing in jsons.toJSONArray(textOf(detail))) {\n                var name = textOf(rowValue(missing, [\'tableName\', \'table_name\'])).trim().toLowerCase()\n                if (!blank(name)) { missingNames.add(name) }\n            }\n        }\n    }\n    var catalogBaseSql = """\n        select * from (\n            select t.tid, t.datasource_id, t.table_name, t.table_name_en, t.table_name_cn,\n                   t.table_comment, t.table_type,\n                   case\n                     when (t.annotated=1 or t.business_type_reason like \'%人工调整%\')\n                          and t.business_type is not null and t.business_type<>\'\' then t.business_type\n                     when t.business_type in (\'不确定\', \'暂不处理\') then t.business_type\n                     when regexp_like(regexp_replace(lower(t.table_name), \'[^a-z0-9]+\', \'_\'), \'(^|_)(bak|backup|bk|old|copy|his|history|archive|arch|dump)(_|$)\')\n                       or regexp_like(regexp_replace(lower(t.table_name), \'[^a-z0-9]+\', \'_\'), \'(^|_)(19|20)[0-9]{6,12}($|_)\')\n                       or regexp_like(concat(concat(lower(t.table_name), \' \'), lower(coalesce(t.table_comment, t.table_name_cn, \'\'))), \'备份|历史|归档|副本\') then \'备份表\'\n                     when regexp_like(regexp_replace(lower(t.table_name), \'[^a-z0-9]+\', \'_\'), \'(^|_)(log|logs|audit|trace|access|operate|operation|login)(_|$)\')\n                       or regexp_like(concat(concat(lower(t.table_name), \' \'), lower(coalesce(t.table_comment, t.table_name_cn, \'\'))), \'日志|审计|轨迹|访问记录|操作记录|登录记录\') then \'日志表\'\n                     when regexp_like(regexp_replace(lower(t.table_name), \'[^a-z0-9]+\', \'_\'), \'(^|_)(dict|dictionary|code|enum|lookup|type|param|params|config|constant)(_|$)\')\n                       or regexp_like(concat(concat(lower(t.table_name), \' \'), lower(coalesce(t.table_comment, t.table_name_cn, \'\'))), \'字典|码表|代码表|枚举|参数|配置|常量|类型\') then \'字典表\'\n                     when regexp_like(regexp_replace(lower(t.table_name), \'[^a-z0-9]+\', \'_\'), \'(^|_)(flow|workflow|process|proc|task|approval|approve|node|todo|bpm)(_|$)\')\n                       or regexp_like(concat(concat(lower(t.table_name), \' \'), lower(coalesce(t.table_comment, t.table_name_cn, \'\'))), \'流程|过程|审批|工单|任务|节点|待办\') then \'过程表\'\n                     else coalesce(nullif(t.business_type, \'\'), \'业务表\')\n                   end as business_type, t.business_type_reason,\n                   t.annotated, t.field_count, t.org_id, t.org_path, t.tenant_id,\n                   t.asset_status, t.flow_status, t.created_time, t.updated_time,\n                   c.tid as source_catalog_id, c.catalog_name, c.catalog_name_en,\n                   row_number() over (\n                       partition by lower(trim(t.table_name))\n                       order by case when c.tid is not null then 1 else 0 end desc, coalesce(t.annotated, 0) desc,\n                                t.updated_time desc, coalesce(t.field_count, 0) desc, t.tid desc\n                   ) as row_rank\n              from db_table_t t\n              left join da_catalog_t c on c.tid=t.source_catalog_id\n                   and c.tenant_id=#{tenantId} and c.is_del=0\n             where t.tenant_id=#{tenantId} and t.datasource_id=#{dbId} and t.is_del=0\n               <if test="missingNames.size() > 0">\n                 and (t.annotated=1 or c.tid is not null or lower(trim(t.table_name)) not in\n                   <foreach collection="missingNames" item="missingName" open="(" close=")" separator=",">#{missingName}</foreach>)\n               </if>\n        ) ranked where ranked.row_rank=1\n    """\n    var counts = db.select(\'select case when ranked.source_catalog_id is not null then 1 else 0 end as registered, count(1) as total from (\' + catalogBaseSql + \') ranked group by case when ranked.source_catalog_id is not null then 1 else 0 end\')\n    var pendingTotal = 0\n    var registeredTotal = 0\n    for (count in counts) {\n        if (textOf(rowValue(count, [\'registered\'])) == \'1\' || textOf(rowValue(count, [\'registered\'])) == \'true\') {\n            registeredTotal = rowValue(count, [\'total\'])::long\n        } else { pendingTotal = rowValue(count, [\'total\'])::long }\n    }\n    var catalogFilterSql = """\n        <if test="registeredMode">and ranked.source_catalog_id is not null</if>\n        <if test="!registeredMode">and ranked.source_catalog_id is null</if>\n        <if test="selectedBusinessType != null and selectedBusinessType != \'\'">\n          and ranked.business_type=#{selectedBusinessType}\n        </if>\n        <if test="tableKeywords.size() > 0">\n          and <foreach collection="tableKeywords" item="word" open="(" close=")" separator=" or ">lower(ranked.table_name) like #{word}</foreach>\n        </if>\n        <if test="catalogKeywords.size() > 0">\n          and <foreach collection="catalogKeywords" item="word" open="(" close=")" separator=" or ">lower(coalesce(ranked.catalog_name, \'\')) like #{word}</foreach>\n        </if>\n    """\n    var page = db.page(catalogBaseSql + catalogFilterSql + \' order by ranked.table_name, ranked.tid\', safePageSize, (safePageNo - 1) * safePageSize)\n    var rows = []\n    for (row in page.list == null ? [] : page.list) {\n        var item = tableItem(row, datasource)\n        item.catalogId = item.sourceCatalogId\n        item.catalogName = rowValue(row, [\'catalogName\', \'catalog_name\'])\n        item.catalogNameEn = rowValue(row, [\'catalogNameEn\', \'catalog_name_en\'])\n        rows.add(item)\n    }\n    return {pageNo: safePageNo, pageSize: safePageSize, total: page.total,\n        pendingTotal: pendingTotal, registeredTotal: registeredTotal, rows: rows, list: rows}\n}\n\n/*\n * 第二步右侧列表使用数据库真分页。先按当前租户和表名去重，避免历史重复资产\n * 同时占用分页位置并造成总数与展示不一致；默认数组模式保持原接口兼容性。\n * pending=true 仅提供“暂不处理”的已保存快照给左侧物理表合并，绝不作为已标注表显示。\n */\nvar pendingMode = textOf(pending).trim().toLowerCase() == \'true\' || textOf(pending) == \'1\'\nif (pendingMode) {\n    // 只返回未标注持久化快照，供第二步左侧合并使用；前端仅对业务类型为\n    // “暂不处理 / 不确定”的记录采用其分类，其他未标注记录仍按物理元数据推断。\n    // 直接返回 NamedTable 行，避免额外对象转换导致字段名在不同驱动下丢失。\n    return db.table(\'db_table_t\').where()\n        .eq(\'datasource_id\', dbId)\n        .eq(\'is_del\', 0)\n        .eq(\'annotated\', 0)\n        .orderBy(\'updated_time\', \'desc\')\n        .select()\n}var pagedMode = textOf(paged).trim().toLowerCase() == \'true\' || textOf(paged) == \'1\'\nif (pagedMode) {\n    var safePageNo = pageNo == null || pageNo::int < 1 ? 1 : pageNo::int\n    var safePageSize = pageSize == null || pageSize::int < 1 ? 50 : Math.min(pageSize::int, 100)\n    var selectedBusinessType = blank(businessType) || textOf(businessType) == \'全部\' ? null : textOf(businessType)\n    var searchKeyword = blank(keyword) ? null : \'%\' + textOf(keyword).trim().toLowerCase() + \'%\'\n    var dedupSql = """\n        select * from (\n            select t.tid, t.datasource_id, t.table_name, t.table_name_en, t.table_name_cn,\n                   t.table_comment, t.table_type, t.business_type, t.business_type_reason,\n                   t.annotated, t.record_count, t.field_count, t.storage_size,\n                   t.total_size_bytes, t.total_size_formatted, t.org_id, t.org_path,\n                   t.related_directory, t.data_source_type, t.timestamp_field,\n                   t.dictionary_structure_type, t.dictionary_table_flag, t.source_catalog_id,\n                   t.field_governance_config, t.dictionary_profiles,\n                   t.dictionary_profile, t.dictionary_categories,\n                   t.source_table_id, t.source_table_name, t.manage_unit, t.asset_status,\n                   t.flow_status, t.reg_time, t.created_time, t.updated_time, t.tenant_id,\n                   row_number() over (\n                       partition by lower(t.table_name)\n                       order by coalesce(t.field_count, 0) desc, t.updated_time desc, t.tid desc\n                   ) as row_rank\n              from db_table_t t\n             where t.tenant_id = #{tenantId}\n               and t.datasource_id = #{dbId}\n               and t.is_del = 0\n               and t.annotated = 1\n        ) ranked\n        where ranked.row_rank = 1\n          <if test="selectedBusinessType != null and selectedBusinessType != \'\'">\n            and ranked.business_type = #{selectedBusinessType}\n          </if>\n          <if test="searchKeyword != null and searchKeyword != \'\'">\n            and (lower(coalesce(ranked.table_name, \'\')) like #{searchKeyword}\n                 or lower(coalesce(ranked.table_name_cn, \'\')) like #{searchKeyword}\n                 or lower(coalesce(ranked.table_comment, \'\')) like #{searchKeyword})\n          </if>\n    """\n    var page = db.page(dedupSql + \' order by ranked.updated_time desc, ranked.tid desc\', safePageSize, (safePageNo - 1) * safePageSize)\n    var rows = []\n    for (row in page.list == null ? [] : page.list) {\n        rows.add(tableItem(row, datasource))\n    }\n\n    var statsRows = db.select("""\n        select coalesce(grouped.business_type, \'业务表\') as business_type, count(1) as total\n          from (\n            select ranked.business_type\n              from (\n                select t.table_name, t.business_type,\n                       row_number() over (\n                           partition by lower(t.table_name)\n                           order by coalesce(t.field_count, 0) desc, t.updated_time desc, t.tid desc\n                       ) as row_rank\n                  from db_table_t t\n                 where t.tenant_id = #{tenantId}\n                   and t.datasource_id = #{dbId}\n                   and t.is_del = 0\n                   and t.annotated = 1\n              ) ranked\n             where ranked.row_rank = 1\n          ) grouped\n         group by coalesce(grouped.business_type, \'业务表\')\n    """)\n    var businessStats = {}\n    var annotatedTotal = 0\n    for (stat in statsRows == null ? [] : statsRows) {\n        var type = firstValue(stat, [\'businessType\', \'business_type\'])\n        var count = rowValue(stat, [\'total\']) == null ? 0 : rowValue(stat, [\'total\'])::long\n        businessStats[blank(type) ? \'业务表\' : type] = count\n        annotatedTotal = annotatedTotal + count\n    }\n    return {\n        pageNo: safePageNo,\n        pageSize: safePageSize,\n        total: page.total == null ? 0 : page.total,\n        annotatedTotal: annotatedTotal,\n        businessStats: businessStats,\n        rows: rows,\n        list: rows\n    }\n}\n\n// datasource_id 必须下推到数据库查询，禁止读取整个租户的表后在 Magic 内存过滤。\nvar tableRows = []\n// 审查页只传输已标注表及其持久化治理配置，不传输上万张未标注表，\n// 也不探查源端字段。排序/去重与第二步右侧已标注列表完全一致。\nif (textOf(annotatedOnly).trim().toLowerCase() == \'true\' || textOf(annotatedOnly) == \'1\') {\n    tableRows = db.select("""\n        select * from (\n            select t.*, row_number() over (\n                partition by lower(t.table_name)\n                order by coalesce(t.field_count, 0) desc, t.updated_time desc, t.tid desc\n            ) as row_rank\n            from db_table_t t\n            where t.tenant_id = #{tenantId} and t.datasource_id = #{dbId}\n              and t.is_del = 0 and t.annotated = 1\n        ) ranked where ranked.row_rank = 1\n        order by ranked.updated_time desc, ranked.tid desc\n    """)\n} else {\n    tableRows = db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'datasource_id\', dbId).eq(\'is_del\', 0)\n        .orderBy(\'updated_time\', \'desc\').select()\n}\n// One physical table can have historical registration snapshots.  Keep the latest\n// persisted snapshot so an older dictionary classification cannot mask a newer process-table edit.\nvar latestByTableName = {}\nvar updatedValue = (row) => {\n    var value = firstValue(row, [\'updatedTime\', \'updated_time\', \'createdTime\', \'created_time\'])\n    return blank(value) ? \'\' : textOf(value)\n}\nfor (row in tableRows == null ? [] : tableRows) {\n    var tableNameKey = textOf(firstValue(row, [\'tableName\', \'table_name\'])).trim().toLowerCase()\n    if (tableNameKey == \'\') { continue }\n    var current = latestByTableName[tableNameKey]\n    if (current == null || updatedValue(row) > updatedValue(current)) {\n        latestByTableName[tableNameKey] = row\n    }\n}\nvar rows = []\nfor (row in tableRows == null ? [] : tableRows) {\n    var tableNameKey = textOf(firstValue(row, [\'tableName\', \'table_name\'])).trim().toLowerCase()\n    if (tableNameKey != \'\' && latestByTableName[tableNameKey] == row) {\n        rows.add(tableItem(row, datasource))\n    }\n}\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/06.获取表列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a9dc328184b7410781b389f67fad1233',NULL,NULL,'{\n  "properties": {},\n  "id": "a9dc328184b7410781b389f67fad1233",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "07.获取字段列表",\n  "createTime": 1782955344294,\n  "updateTime": 1790385855266,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/columns",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "",\n      "description": "已登记数据表ID，可选",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "dbId",\n      "value": "372b36d08059473eb4e248fd06276a41",\n      "description": "数据源ID，首次探查时与 tableName 一起传入",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "tableName",\n      "value": "police_person_info",\n      "description": "物理表名，首次探查时与 dbId 一起传入",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "snapshotOnly",\n      "value": "false",\n      "description": "true 时仅从 db_table_column_t 读取，空快照不连接来源库",\n      "required": false,\n      "dataType": "Boolean",\n      "type": null,\n      "defaultValue": "false",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "获取字段列表（GET /dst/database/metadata/columns）。登记第三、四步传 tid + snapshotOnly=true 仅读 db_table_column_t；其他探查场景保留实时来源库兼容。只读接口。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.获取字段列表\n// 路由：GET /dst/database/metadata/columns\n// 业务说明：获取字段列表（GET /dst/database/metadata/columns）。登记第三、四步传 tid + snapshotOnly=true 仅读 db_table_column_t；其他探查场景保留实时来源库兼容。只读接口。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport java.util.Map\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\n\n/*\n * 元数据管理 07：读取数据表字段结构。\n *\n * 已登记表优先读取 db_table_column_t 快照；第二步首次探查尚未生成表 ID 时，\n * 支持使用 dbId + tableName 直连物理数据库实时读取字段。全程只读，不登记表资产。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) { return value }\n    }\n    return null\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) { return DatabaseType.MYSQL }\n    try {\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        return DatabaseType.MYSQL\n    }\n}\nvar loadDatasource = (datasourceId) => {\n    if (blank(datasourceId)) { return null }\n    var row = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\n    if (row == null) { return null }\n    var result = {\n        tid: rowValue(row, [\'tid\']),\n        dbName: rowValue(row, [\'dbName\', \'db_name\']),\n        dbType: rowValue(row, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(row, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(row, [\'username\']),\n        password: rowValue(row, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(row, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(row, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(row, [\'dbType\', \'db_type\']) }\n    if (rowValue(row, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(row, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(row, [\'username\']) != null) { result.username = rowValue(row, [\'username\']) }\n    if (rowValue(row, [\'password\']) != null) { result.password = rowValue(row, [\'password\']) }\n    return result\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\nvar excludes = [\'tenantId\', \'revision\', \'createdBy\', \'createdTime\', \'updatedBy\', \'updatedTime\']\nif (!blank(tid)) {\n    if ((tid + \'\').contains(\',\')) {\n        var tids = (tid + \'\').split(\',\').filter(item => !blank(item))\n        var rows = db.table(\'db_table_column_t\').excludes(excludes).where()\n            .in(\'table_id\', tids).eq(\'is_del\', 0).select()\n        return rows.group(item => item.tableId)\n    }\n    var snapshot = db.table(\'db_table_column_t\').excludes(excludes).where()\n        .eq(\'table_id\', tid).eq(\'is_del\', 0).select()\n    if (snapshot != null && snapshot.size() > 0) { return snapshot }\n    // 登记第三、四步只读 MySQL 字段快照；空快照也绝不回退物理探查。\n    if (snapshotOnly == true || textOf(snapshotOnly) == \'1\' || textOf(snapshotOnly) == \'true\') { return [] }\n    // registered table asset fallback: old dirty snapshots may have no columns.\n    var tableAsset = db.table(\'db_table_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n    if (tableAsset != null) {\n        dbId = firstValue(tableAsset, [\'datasourceId\', \'datasource_id\'])\n        tableName = firstValue(tableAsset, [\'tableName\', \'table_name\'])\n    }\n}\n\n// 首次进入第二步的物理表没有 tid，使用数据源和表名实时读取字段结构。\nif (blank(dbId) || blank(tableName)) {\n    exit 400, \'tid 为空时必须提供 dbId 和 tableName\'\n}\nvar datasource = loadDatasource(dbId)\nif (datasource == null) { exit 404, \'数据源不存在\' }\nreturn metadataExplorerService.getColumns(dataSourceOf(datasource), tableName + \'\')\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/07.获取字段列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4347c17766bf43ac867654bea91e0d9a',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "4347c17766bf43ac867654bea91e0d9a",\r\n  "script" : null,\r\n  "groupId" : "6e30fb6d565c40b18d480b219e13b20e",\r\n  "name" : "08.探查数据库表",\r\n  "createTime" : 1782955344232,\r\n  "updateTime" : 1791112525954,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/exploreDbTables",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"dbId\\": \\"数据库资产ID\\",\\n    \\"tenantId\\": \\"可选租户ID\\",\\n    \\"dryRun\\": false,\\n    \\"refreshExisting\\": false,\\n    \\"tableOverrides\\": \\"测试\\"\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "探查当前租户的数据源物理表并登记/刷新表与字段快照；dryRun=true 只读。一次预取该数据源已登记字段，刷新时按表在内存比对并保留旧字段 ID/治理配置，不按物理表逐次补查平台数据库。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：08.探查数据库表\n// 路由：POST /dst/database/metadata/exploreDbTables\n// 业务说明：元数据管理 08：探查物理数据库并登记数据表快照；使用请求参数 dbId、dryRun、refreshExisting、tableOverrides；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表；执行数据库写入并返回处理结果。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport com.linewell.dataelement.metautil.structured.StructuredSourceProbeService as structuredSourceProbeService\nimport jsons\nimport java.util.Map\nimport log\nimport tenantRuntime\n/*\n * 元数据管理 08：探查物理数据库并登记数据表快照。\n *\n * 读取 db_datasource_t 的连接信息，调用底层 MetadataExplorerService 探查物理表。\n * 新表写 db_table_t、db_table_column_t，并同步 dataassets ES；不再写\n * da_asset_t。dryRun=true 时完全只读。refreshExisting=true 时刷新已有物理元数据，\n * 同名字段沿用原 tid 和治理配置，避免覆盖登记步骤 3/4 的人工配置。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar nowTime = () => new Date()\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再探查数据源\'\n}\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value == null) {\n            var upperKey = textOf(key).toUpperCase()\n            value = row instanceof Map ? row.get(upperKey) : row[upperKey]\n        }\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadDatasource = (datasourceId) => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var source = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (source == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: datasourceId,\n        tenantId: rowValue(source, [\'tenantId\', \'tenant_id\']),\n        dbName: rowValue(source, [\'dbName\', \'db_name\']),\n        dbType: rowValue(source, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(source, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(source, [\'username\']),\n        password: rowValue(source, [\'password\']),\n        appId: rowValue(source, [\'appId\', \'app_id\']),\n        orgId: rowValue(source, [\'orgId\', \'org_id\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(source, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    result.tid = datasourceId\n    result.dbName = rowValue(source, [\'dbName\', \'db_name\'])\n    result.dbType = rowValue(source, [\'dbType\', \'db_type\'])\n    result.jdbcURL = rowValue(source, [\'jdbcUrl\', \'jdbc_url\'])\n    result.username = rowValue(source, [\'username\'])\n    result.password = rowValue(source, [\'password\'])\n    result.appId = rowValue(source, [\'appId\', \'app_id\'])\n    result.orgId = rowValue(source, [\'orgId\', \'org_id\'])\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(lower(code))\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\nvar registeredMapOf = (datasourceId) => {\n    var result = {}\n    // 从 MySQL 业务表读取当前有效数据。\n    var rows = db.table(\'db_table_t\').where()\n        .eq(\'datasource_id\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n    for (row in rows) {\n        var tableName = firstValue(row, [\'tableName\', \'table_name\'])\n        if (!blank(tableName) && result[lower(tableName)] == null) {\n            result[lower(tableName)] = row\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar typeName = (rawType) => {\n    // 返回当前业务分支的标准结果。\n    return !blank(rawType) && lower(rawType).indexOf(\'view\') >= 0 ? \'视图\' : \'数据表\'\n}\nvar containsAny = (value, words) => {\n    var source = lower(value)\n    for (word in words) {\n        if (source.indexOf(word) >= 0) {\n            // 返回当前业务分支的标准结果。\n            return true\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return false\n}\nvar inferBusinessType = (tableName, comment) => {\n    var value = lower(tableName) + \' \' + lower(comment)\n    if (containsAny(value, [\'log\', \'audit\', \'trace\', \'日志\', \'审计\', \'轨迹\'])) {\n        // 返回当前业务分支的标准结果。\n        return { type: \'日志表\', reason: \'命中日志或审计关键字\' }\n    }\n    if (containsAny(value, [\'dict\', \'dictionary\', \'code\', \'enum\', \'字典\', \'码表\', \'枚举\'])) {\n        // 返回当前业务分支的标准结果。\n        return { type: \'字典表\', reason: \'命中字典或码表关键字\' }\n    }\n    if (containsAny(value, [\'tmp\', \'temp\', \'临时\'])) {\n        // 返回当前业务分支的标准结果。\n        return { type: \'临时表\', reason: \'命中临时表关键字\' }\n    }\n    if (containsAny(value, [\'bak\', \'backup\', \'history\', \'archive\', \'备份\', \'历史\', \'归档\'])) {\n        // 返回当前业务分支的标准结果。\n        return { type: \'备份表\', reason: \'命中备份或历史关键字\' }\n    }\n    // 返回当前业务分支的标准结果。\n    return { type: \'业务表\', reason: \'默认识别为业务表\' }\n}\nvar columnValues = (tableId, columnId, col, tenantId) => {\n    // 返回当前业务分支的标准结果。\n    return {\n        tid: columnId,\n        table_id: tableId,\n        tenant_id: tenantId,\n        column_name: col.columnName,\n        column_comment: col.columnComment,\n        data_type: col.dataType,\n        column_type: col.columnType,\n        length: col.length,\n        precision_length: col.precision,\n        scale: col.scale,\n        nullable: col.nullable == true ? 1 : 0,\n        default_value: col.defaultValue,\n        primary_key: col.primaryKey == true ? 1 : 0,\n        auto_increment: col.autoIncrement == true ? 1 : 0,\n        is_unique: col.unique == true ? 1 : 0,\n        indexed: col.indexed == true ? 1 : 0,\n        ordinal_position: col.ordinalPosition,\n        charset: col.charset,\n        collation: col.collation,\n        extra: col.extra,\n        is_del: 0,\n        updated_time: nowTime()\n    }\n}\nvar saveColumns = (tableId, columns, tenantId, oldRows) => {\n    var oldMap = {}\n    for (old in oldRows == null ? [] : oldRows) {\n        oldMap[lower(firstValue(old, [\'columnName\', \'column_name\']))] = old\n    }\n    var count = 0\n    for (col in columns == null ? [] : columns) {\n        var key = lower(col.columnName)\n        var old = oldMap[key]\n        var columnId = old == null ? newId() : firstValue(old, [\'tid\'])\n        var values = columnValues(tableId, columnId, col, tenantId)\n        if (old == null) {\n            values.created_time = nowTime()\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').primary(\'tid\').insert(values)\n        } else {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').primary(\'tid\').update(values, true)\n            oldMap[key] = null\n        }\n        count = count + 1\n    }\n    for (key in oldMap.keySet()) {\n        var old = oldMap[key]\n        if (old != null) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').primary(\'tid\').update({\n                tid: firstValue(old, [\'tid\']),\n                is_del: 1,\n                updated_time: nowTime()\n            }, true)\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return count\n}\nvar saveEs = (tableId, doc) => {\n    try {\n        // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n        esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(doc), false)\n    } catch (e) {\n        log.warn(\'同步数据表 ES 失败, tid: {}, error: {}\', tableId, e.message)\n    }\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar datasourceId = body == null ? null : body.dbId\nif (blank(datasourceId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'dbId 不能为空\'\n}\nvar dryRun = body != null && body.dryRun == true\nvar refreshExisting = body != null && body.refreshExisting == true\nvar source = loadDatasource(datasourceId)\nif (source == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'数据源不存在\'\n}\nvar sourceType = lower(firstValue(source, [\'dbType\', \'databaseType\', \'dataSourceType\']))\nvar structuredSource = sourceType == \'api\' || sourceType == \'ftp\' || sourceType == \'kafka\'\nvar physicalTables = structuredSource\n    ? structuredSourceProbeService.getTablesPage(source, 1, 500, null).rows\n    : metadataExplorerService.getTables(dataSourceOf(source))\nvar registeredMap = registeredMapOf(datasourceId)\n// 一次取得此数据源已登记字段。只探查/复用时仅需存在性；刷新并写入时\n// 一并预取完整旧字段，供后续逐表比对复用原 tid 和人工治理配置。\nvar storedColumnRows = refreshExisting && !dryRun\n    ? db.select("""\n        select c.*\n          from db_table_column_t c\n          join db_table_t t on t.tid = c.table_id\n         where t.datasource_id = #{datasourceId}\n           and t.tenant_id = #{tenantId}\n           and c.tenant_id = #{tenantId}\n           and t.is_del = 0\n           and c.is_del = 0\n    """)\n    : db.select("""\n        select distinct c.table_id as tableId\n          from db_table_column_t c\n          join db_table_t t on t.tid = c.table_id\n         where t.datasource_id = #{datasourceId}\n           and t.tenant_id = #{tenantId}\n           and c.tenant_id = #{tenantId}\n           and t.is_del = 0\n           and c.is_del = 0\n    """)\nvar storedColumnTableIds = {}\nvar storedColumnsByTable = {}\nfor (storedColumn in storedColumnRows == null ? [] : storedColumnRows) {\n    var storedTableId = textOf(firstValue(storedColumn, [\'tableId\', \'table_id\']))\n    if (blank(storedTableId)) { continue }\n    storedColumnTableIds[storedTableId] = true\n    if (refreshExisting && !dryRun) {\n        if (storedColumnsByTable[storedTableId] == null) { storedColumnsByTable[storedTableId] = [] }\n        storedColumnsByTable[storedTableId].add(storedColumn)\n    }\n}\nvar overrideMap = {}\nfor (override in body == null || body.tableOverrides == null ? [] : body.tableOverrides) {\n    var overrideName = firstValue(override, [\'tableName\', \'tableNameEn\'])\n    if (!blank(overrideName)) {\n        overrideMap[lower(overrideName)] = override\n    }\n}\nvar rows = []\nvar createdCount = 0\nvar reusedCount = 0\nvar refreshedCount = 0\n\nfor (tableInfo in physicalTables == null ? [] : physicalTables) {\n    var tableName = tableInfo.tableName\n    if (blank(tableName)) {\n        continue\n    }\n    var existing = registeredMap[lower(tableName)]\n    var override = overrideMap[lower(tableName)]\n    var tableId = existing == null ? newId() : firstValue(existing, [\'tid\'])\n    var action = existing == null ? \'create\' : (refreshExisting ? \'refresh\' : (override == null ? \'reuse\' : \'configure\'))\n    var needsColumnBootstrap = existing != null && storedColumnTableIds[tableId] != true\n    if (action == \'reuse\' && needsColumnBootstrap) {\n        action = \'bootstrap\'\n    }\n    var comment = firstValue(override, [\'tableComment\', \'tableNameCn\'])\n    if (blank(comment)) {\n        comment = blank(tableInfo.tableComment) ? tableName : tableInfo.tableComment\n    }\n    var business = existing == null ? inferBusinessType(tableName, comment) : {\n        type: firstValue(existing, [\'businessType\', \'business_type\']),\n        reason: firstValue(existing, [\'businessTypeReason\', \'business_type_reason\'])\n    }\n    if (!blank(firstValue(override, [\'businessType\']))) {\n        business = {\n            type: firstValue(override, [\'businessType\']),\n            reason: firstValue(override, [\'businessTypeReason\'])\n        }\n    }\n    var columns = []\n    var fieldCount = tableInfo.columnCount == null ? 0 : tableInfo.columnCount\n    var shouldLoadColumns = action == \'create\' || action == \'refresh\' || needsColumnBootstrap\n    if (shouldLoadColumns) {\n        columns = structuredSource\n            ? structuredSourceProbeService.getColumns(source, tableName)\n            : metadataExplorerService.getColumns(dataSourceOf(source), tableName)\n        fieldCount = columns == null ? 0 : columns.size()\n    } else if (rowValue(existing, [\'fieldCount\', \'field_count\']) != null) {\n        fieldCount = rowValue(existing, [\'fieldCount\', \'field_count\'])\n    }\n    var output = {\n        tid: tableId,\n        id: tableId,\n        assetType: \'table\',\n        datasourceId: datasourceId,\n        dbId: datasourceId,\n        tableName: tableName,\n        tableNameEn: tableName,\n        tableNameCn: comment,\n        tableComment: comment,\n        tableType: typeName(tableInfo.tableType),\n        businessType: blank(business.type) ? \'业务表\' : business.type,\n        businessTypeReason: business.reason,\n        recordCount: tableInfo.rowCount == null ? 0 : tableInfo.rowCount,\n        fieldCount: fieldCount,\n        storageSize: blank(tableInfo.totalSizeFormatted) ? \'0 B\' : tableInfo.totalSizeFormatted,\n        totalSizeBytes: tableInfo.totalSizeBytes == null ? 0 : tableInfo.totalSizeBytes,\n        orgId: firstValue(source, [\'orgId\']),\n        orgPath: firstValue(source, [\'orgPath\']),\n        appId: firstValue(source, [\'appId\']),\n        annotated: override == null ? rowValue(existing, [\'annotated\']) : 1,\n        action: action\n    }\n    if (!dryRun && action != \'reuse\') {\n        var values = {\n            tid: tableId,\n            datasource_id: datasourceId,\n            table_name: tableName,\n            table_name_en: tableName,\n            table_name_cn: comment,\n            table_comment: comment,\n            table_type: output.tableType,\n            business_type: output.businessType,\n            business_type_reason: output.businessTypeReason,\n            annotated: output.annotated == null ? 0 : output.annotated,\n            record_count: output.recordCount,\n            field_count: output.fieldCount,\n            storage_size: output.storageSize,\n            total_size_formatted: output.storageSize,\n            total_size_bytes: output.totalSizeBytes,\n            ddl_create_time: tableInfo.createTime,\n            ddl_update_time: tableInfo.updateTime,\n            org_id: output.orgId,\n            org_path: output.orgPath,\n            source_table_id: tableId,\n            source_table_name: tableName,\n            manage_unit: output.orgId,\n            asset_desc: comment,\n            tenant_id: tenantId,\n            asset_status: existing == null ? 0 : firstValue(existing, [\'assetStatus\', \'asset_status\']),\n            flow_status: existing == null ? 0 : firstValue(existing, [\'flowStatus\', \'flow_status\']),\n            flow_order_id: null,\n            is_del: 0,\n            updated_time: nowTime()\n        }\n        if (existing == null) {\n            values.created_time = nowTime()\n            values.reg_time = nowTime()\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_t\').primary(\'tid\').insert(values)\n            createdCount = createdCount + 1\n        } else {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_t\').primary(\'tid\').update(values, true)\n            refreshedCount = refreshedCount + 1\n        }\n        if (shouldLoadColumns) {\n            saveColumns(tableId, columns, tenantId, storedColumnsByTable[tableId])\n        }\n        output.assetStatus = values.asset_status\n        output.flowStatus = values.flow_status\n        output.updatedTime = date_format(now)\n        saveEs(tableId, output)\n    } else if (action == \'reuse\') {\n        reusedCount = reusedCount + 1\n    } else if (action == \'create\') {\n        createdCount = createdCount + 1\n    } else {\n        refreshedCount = refreshedCount + 1\n    }\n    rows.add(output)\n}\n// 返回当前业务分支的标准结果。\nreturn {\n    dbId: datasourceId,\n    dryRun: dryRun,\n    refreshExisting: refreshExisting,\n    totalScanned: physicalTables == null ? 0 : physicalTables.size(),\n    createdCount: createdCount,\n    reusedCount: reusedCount,\n    refreshedCount: refreshedCount,\n    rows: rows\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/08.探查数据库表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_db_info_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_db_info_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "09.查询数据库元信息",\n  "createTime": 1783639496542,\n  "updateTime": 1787156076783,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dbInfo",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "8b0a98de552b4bc68a203293fadfff33",\n      "description": "数据库资产ID",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "元数据管理 09：查询数据库概览信息；涉及 db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.查询数据库元信息\n// 路由：GET /dst/database/metadata/dbInfo\n// 业务说明：元数据管理 09：查询数据库概览信息；涉及 db_datasource_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport java.util.Map\n\n/*\n * 元数据管理 09：查询数据库概览信息。\n *\n * 只读接口。根据数据库资产 tid 组装 DataSourceConfig，调用底层 MetadataExplorerService\n * 读取物理数据库概览，返回容量、表数量、视图数量、存储过程数量和用户数量。\n * 这里只返回实时概览，不写资产属性；需要刷新并持久化概览请走 10。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']), id: rowValue(main, [\'tid\']), assetType: \'db\',\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\nvar countValue = (value) => value == null ? 0 : value\nvar sizeValue = (value) => blank(value) ? \'0 B\' : value\n\nif (blank(tid)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid 不能为空\'\n}\nvar asset = loadAsset(tid)\nif (asset == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'数据源资产不存在\'\n}\nvar info = metadataExplorerService.getDatabaseInfo(dataSourceOf(asset))\nvar totalSize = sizeValue(info == null ? null : info.totalSizeFormatted)\nvar dataSize = sizeValue(info == null ? null : info.dataSizeFormatted)\nif (dataSize == \'0 B\' && totalSize != \'0 B\') {\n    dataSize = totalSize\n}\n// 返回当前业务分支的标准结果。\nreturn {\n    dbVersion: info == null ? \'\' : (blank(info.version) ? \'\' : info.version),\n    db_version: info == null ? \'\' : (blank(info.version) ? \'\' : info.version),\n    dataSize: dataSize,\n    tableCount: countValue(info == null ? null : info.tableCount),\n    viewCount: countValue(info == null ? null : info.viewCount),\n    procedureCount: countValue(info == null ? null : info.procedureCount),\n    totalSize: totalSize,\n    userCount: countValue(info == null ? null : info.userCount)\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/09.查询数据库元信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_refresh_db_info_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_refresh_db_info_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "10.刷新数据库元信息",\n  "createTime": 1783639496542,\n  "updateTime": 1787156377648,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/refreshDbInfo",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "8b0a98de552b4bc68a203293fadfff33",\n      "description": "数据库资产ID",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "waitSeconds",\n      "value": "10",\n      "description": "等待表刷新完成的秒数，可选，默认由服务端控制",\n      "required": false,\n      "dataType": "Integer",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 400,\\n    \\"msg\\": \\"参数[waitSeconds]不合法\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "刷新数据库元信息（GET /dst/database/metadata/refreshDbInfo）。读取物理数据库概览，将表数量、视图数量、存储过程数量、用户数量、容量等元数据写入 db_datasource_t 独立字段，并刷新单条数据源 ES 投影；connection extension property 只保留数据库连接信息，不作为元数据存储。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.刷新数据库元信息\n// 路由：GET /dst/database/metadata/refreshDbInfo\n// 业务说明：刷新数据库元信息（GET /dst/database/metadata/refreshDbInfo）。读取物理数据库概览，将表数量、视图数量、存储过程数量、用户数量、容量等元数据写入 db_datasource_t 独立字段，并刷新单条数据源 ES 投影；connection extension property 只保留数据库连接信息，不作为元数据存储。\nimport \'@get:/dst/database/metadata/dbInfo\' as queryDatabaseInfo\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\n\n/*\n * 元数据管理 10：刷新并持久化数据库概览。\n *\n * 实时概览来自 09，落库到 db_datasource_t 的物理概览字段；\n * 连接扩展属性仅保存连接参数，不能再写容量、视图数、过程数等元数据。\n * 本接口只刷新数据源概览，不写 da_prop_t，也不隐式登记数据表。\n */\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\nif (blank(tid)) {\n    // 缺少数据源主键时直接终止，避免误更新其他记录。\n    exit 400, \'tid 不能为空\'\n}\n// 数据源主表是概览信息的唯一持久化目标。\nvar datasource = db.table(\'db_datasource_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (datasource == null) {\n    exit 404, \'数据源不存在\'\n}\n// 从物理数据库读取容量、表、视图、存储过程和用户统计。\nvar info = queryDatabaseInfo()\n// 元数据概览写入独立字段，详情页和 ES 重建均以这些字段为准。\nvar affected = db.update("""\n    UPDATE db_datasource_t\n       SET table_num = #{info.tableCount},\n           db_version = #{info.dbVersion},\n           view_count = #{info.viewCount},\n           procedure_count = #{info.procedureCount},\n           user_count = #{info.userCount},\n           data_size = #{info.dataSize},\n           total_size = #{info.totalSize},\n           updated_time = CURRENT_TIMESTAMP\n     WHERE tid = #{tid}\n       AND is_del = 0\n""")\nif (affected == 0) {\n    exit 404, \'数据源不存在或已删除\'\n}\n// 主表保存成功后同步刷新单条 ES 投影；索引异常后续可通过批量重建补偿，不回滚主表元数据。\ntry {\n    body = { tid: tid, assetType: \'db\' }\n    refreshAssetIndex()\n} catch (e) {\n    // ES 刷新失败不影响元数据主表保存。\n}\n// 仅返回可直接序列化的标量字段；同时提供前端常用 camelCase 与数据库 snake_case 名称。\nreturn {\n    tid: tid,\n    dbVersion: info.dbVersion,\n    db_version: info.dbVersion,\n    dataSize: info.dataSize,\n    data_size: info.dataSize,\n    tableCount: info.tableCount,\n    tableNum: info.tableCount,\n    table_num: info.tableCount,\n    viewCount: info.viewCount,\n    view_count: info.viewCount,\n    procedureCount: info.procedureCount,\n    procedure_count: info.procedureCount,\n    totalSize: info.totalSize,\n    total_size: info.totalSize,\n    userCount: info.userCount,\n    user_count: info.userCount\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/10.刷新数据库元信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8315865f538845249d49f66c47a0ab27',NULL,NULL,'{\n  "properties": {},\n  "id": "8315865f538845249d49f66c47a0ab27",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "11.根据表id刷新表元数据信息",\n  "createTime": 1782955344272,\n  "updateTime": 1787156076836,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/refreshTableInfo",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"95fb07dab8094dbcafdfafd96359a3a4\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据已登记表标识读取所属数据源，重新探查物理表及字段结构，更新本地表和字段快照并刷新检索索引。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.根据表id刷新表元数据信息\n// 路由：POST /dst/database/metadata/refreshTableInfo\n// 业务说明：根据已登记表标识读取所属数据源，重新探查物理表及字段结构，更新本地表和字段快照并刷新检索索引。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport jsons\nimport java.util.Map\nimport log\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar nowText = () => date_format(new Date())\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    var assetType = \'db\'\n    if (main == null) {\n        // 从 MySQL 业务表读取当前有效数据。\n        main = db.table(\'db_table_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n        assetType = \'table\'\n    }\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']),\n        id: rowValue(main, [\'tid\']),\n        assetType: assetType,\n        dbId: rowValue(main, [\'datasourceId\', \'datasource_id\']),\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\']),\n        tableName: rowValue(main, [\'tableName\', \'table_name\']),\n        tableNameEn: rowValue(main, [\'tableName\', \'table_name\']),\n        tableNameCn: rowValue(main, [\'tableNameCn\', \'table_name_cn\']),\n        tableComment: rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    if (assetType == \'table\' && !blank(result.dbId)) {\n        var datasourceRows = db.select("""\n            select tid, db_name as dbName, app_id as appId, org_id as orgId\n              from db_datasource_t\n             where ifnull(is_del, 0) = 0\n               and tid = #{result.dbId}\n             limit 1\n        """)\n        var datasource = datasourceRows == null || datasourceRows.size() == 0 ? null : datasourceRows[0]\n        if (datasource != null) {\n            var datasourceName = datasource.dbname || datasource.dbName || datasource.db_name\n            result.datasourceId = result.dbId\n            result.datasourceName = datasourceName\n            result.dbName = datasourceName\n            result.sourceDbName = datasourceName\n            result.appId = datasource.appid || datasource.appId || datasource.app_id\n            result.orgId = datasource.orgid || datasource.orgId || datasource.org_id\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var databaseType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = databaseType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\'])\n    if (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username)))) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? databaseType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(password == null ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    dsConfig.setSchema(firstValue(asset, [\'schema\', \'defaultSchema\']))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    // 返回当前业务分支的标准结果。\n    return dsConfig\n}\nvar columnKey = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar columnData = (tableId, col) => {\n    // 返回当前业务分支的标准结果。\n    return {\n        table_id: tableId,\n        column_name: col.columnName,\n        column_comment: col.columnComment,\n        data_type: col.dataType,\n        column_type: col.columnType,\n        length: col.length,\n        precision_length: col.precision,\n        scale: col.scale,\n        nullable: col.nullable == true ? 1 : 0,\n        default_value: col.defaultValue,\n        primary_key: col.primaryKey == true ? 1 : 0,\n        auto_increment: col.autoIncrement == true ? 1 : 0,\n        is_unique: col.unique == true ? 1 : 0,\n        indexed: col.indexed == true ? 1 : 0,\n        ordinal_position: col.ordinalPosition,\n        charset: col.charset,\n        collation: col.collation,\n        extra: col.extra,\n        is_del: 0,\n        updated_time: nowText()\n    }\n}\nvar refreshColumns = (tableId, columns) => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var existing = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableId).eq(\'is_del\', 0).select()\n    var existingMap = {}\n    for (old in existing) {\n        existingMap[columnKey(rowValue(old, [\'columnName\', \'column_name\']))] = old\n    }\n    var inserted = 0\n    var updated = 0\n    var deleted = 0\n    for (col in columns == null ? [] : columns) {\n        var key = columnKey(col.columnName)\n        if (blank(key)) {\n            continue\n        }\n        var old = existingMap[key]\n        var data = columnData(tableId, col)\n        if (old == null) {\n            data.tid = IdUtil.getSnowflakeNextIdStr()\n            data.created_time = nowText()\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').primary(\'tid\').insert(data)\n            inserted = inserted + 1\n        } else {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').where().eq(\'tid\', rowValue(old, [\'tid\'])).update(data)\n            existingMap[key] = null\n            updated = updated + 1\n        }\n    }\n    for (key in existingMap.keySet()) {\n        var old = existingMap[key]\n        if (old != null) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'db_table_column_t\').where().eq(\'tid\', rowValue(old, [\'tid\'])).update({ is_del: 1, updated_time: nowText() })\n            deleted = deleted + 1\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return { inserted: inserted, updated: updated, deleted: deleted }\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar tableId = body == null ? null : body.tableId\nif (blank(tableId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tableId不能为空\'\n}\n\nvar oldTable = loadAsset(tableId)\nif (oldTable == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tableId不正确\'\n}\nvar dbAsset = loadAsset(firstValue(oldTable, [\'dbId\']))\nif (dbAsset == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'表所属数据源不存在\'\n}\n\nvar tableName = firstValue(oldTable, [\'tableName\', \'tableNameEn\'])\nvar dsConfig = dataSourceOf(dbAsset)\nvar tableInfo = metadataExplorerService.getTableInfo(dsConfig, tableName)\nif (tableInfo == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'表不存在或无法获取表信息\'\n}\nvar rowCount = metadataExplorerService.getTableRowCount(dsConfig, tableName)\nif (rowCount != null) {\n    tableInfo.setRowCount(rowCount)\n}\nvar columns = metadataExplorerService.getColumns(dsConfig, tableName)\nvar columnSummary = refreshColumns(tableId, columns)\n\nvar tableComment = blank(tableInfo.tableComment) ? tableName : tableInfo.tableComment\nvar totalSizeFormatted = blank(tableInfo.totalSizeFormatted) ? \'0 B\' : tableInfo.totalSizeFormatted\nvar totalSizeBytes = tableInfo.totalSizeBytes == null ? 0 : tableInfo.totalSizeBytes\nvar fieldCount = columns == null ? 0 : columns.size()\nvar recordCount = tableInfo.rowCount == null ? 0 : tableInfo.rowCount\n\n\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table(\'db_table_t\').primary(\'tid\').update({\n    tid: tableId,\n    table_name_cn: tableComment,\n    table_comment: tableComment,\n    record_count: recordCount,\n    field_count: fieldCount,\n    storage_size: totalSizeFormatted,\n    total_size_bytes: totalSizeBytes,\n    ddl_create_time: tableInfo.createTime,\n    ddl_update_time: tableInfo.updateTime,\n    updated_time: nowText()\n}, true)\n\nvar patch = {\n    tid: tableId,\n    id: tableId,\n    dbId: oldTable.dbId,\n    datasourceId: oldTable.datasourceId || oldTable.dbId,\n    datasourceName: oldTable.datasourceName || oldTable.dbName,\n    dbName: oldTable.datasourceName || oldTable.dbName,\n    sourceDbName: oldTable.datasourceName || oldTable.dbName,\n    tableNameCn: tableComment,\n    tableName: tableName,\n    tableNameEn: tableName,\n    recordCount: recordCount,\n    fieldCount: fieldCount,\n    storageSize: totalSizeFormatted,\n    totalSizeFormatted: totalSizeFormatted,\n    totalSizeBytes_num: totalSizeBytes,\n    ddlCreatTime: tableInfo.createTime,\n    ddlUpdateTime: tableInfo.updateTime,\n    updatedTime: nowText(),\n    updatedTime_date: nowText(),\n    columnRefresh: columnSummary\n}\n\ntry {\n    var merged = loadAsset(tableId)\n    if (merged == null) {\n        merged = patch\n    } else {\n        for (key in patch.keySet()) {\n            merged[key] = patch[key]\n        }\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(merged), false)\n    // 返回当前业务分支的标准结果。\n    return merged\n} catch (e) {\n    log.warn(\'sync dataassets es failed, tid: {}, error: {}\', tableId, e.message)\n    // 返回当前业务分支的标准结果。\n    return patch\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/11.根据表id刷新表元数据信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('06ee6f0e37e44762be967dbd2d764780',NULL,NULL,'{\n  "properties": {},\n  "id": "06ee6f0e37e44762be967dbd2d764780",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "12.数据库表抽样",\n  "createTime": 1782955344245,\n  "updateTime": 1787156076883,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/table/sample-data",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"可选，已登记表ID\\",\\n    \\"dbId\\": \\"372b36d08059473eb4e248fd06276a41\\",\\n    \\"tableName\\": \\"police_person_info\\",\\n    \\"sampleSize\\": 10\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据库表抽样（POST /dst/database/metadata/table/sample-data）。已登记表可传 tableId；第二步首次探查可传 dbId + tableName，直接读取物理表前 N 行。只读，不登记表资产；涉及 db_datasource_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：12.数据库表抽样\n// 路由：POST /dst/database/metadata/table/sample-data\n// 业务说明：数据库表抽样（POST /dst/database/metadata/table/sample-data）。已登记表可传 tableId；第二步首次探查可传 dbId + tableName，直接读取物理表前 N 行。只读，不登记表资产；涉及 db_datasource_t、db_table_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.model.dto.SampleRequest\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport java.util.Map\n\n/*\n * 元数据管理 12：数据库表抽样。\n *\n * 只读接口。根据 tableId 找到表资产和所属数据库资产，组装 SampleRequest 后调用底层元数据抽样服务。\n * 与 13 的区别：12 返回抽样模型，适合“前 N 条/随机抽样”等场景；13 返回分页模型，适合弹框预览。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    var assetType = \'db\'\n    if (main == null) {\n        // 从 MySQL 业务表读取当前有效数据。\n        main = db.table(\'db_table_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n        assetType = \'table\'\n    }\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']), id: rowValue(main, [\'tid\']), assetType: assetType,\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbId: rowValue(main, [\'datasourceId\', \'datasource_id\']),\n        tableName: rowValue(main, [\'tableName\', \'table_name\']),\n        tableNameEn: rowValue(main, [\'tableName\', \'table_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\n// 物化目标表仅允许一个 _TARGET 后缀。历史上重复生成的登记记录可能带有\n// _TARGET_TARGET，抽样必须回落到真实物理表名，避免对业务库发出无效 SQL。\nvar normalizePhysicalTableName = (value) => {\n    var name = textOf(value)\n    if (blank(name)) {\n        return name\n    }\n    while (name.toUpperCase().endsWith(\'_TARGET_TARGET\')) {\n        name = name.substring(0, name.length() - \'_TARGET\'.length())\n    }\n    return name\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\n// 解析请求体并为可选参数设置默认值。\nvar tableId = body == null ? null : body.tableId\nvar directDbId = body == null ? null : body.dbId\nvar directTableName = body == null ? null : body.tableName\nvar dbAsset = null\nvar resolvedTableName = null\nif (!blank(tableId)) {\n    var table = loadAsset(tableId)\n    if (table == null) { exit 404, \'tableId 参数不正确\' }\n    dbAsset = loadAsset(firstValue(table, [\'dbId\']))\n    resolvedTableName = firstValue(table, [\'tableName\', \'tableNameEn\'])\n} else {\n    // 第二步首次进入时表尚未登记，直接使用 dbId + tableName 读取物理表样例。\n    if (blank(directDbId) || blank(directTableName)) {\n        exit 400, \'tableId 为空时必须提供 dbId 和 tableName\'\n    }\n    dbAsset = loadAsset(directDbId)\n    resolvedTableName = directTableName\n}\nif (dbAsset == null) { exit 404, \'表所属数据源不存在\' }\n\nresolvedTableName = normalizePhysicalTableName(resolvedTableName)\nvar request = new SampleRequest()\nrequest.setDataSource(dataSourceOf(dbAsset))\nrequest.setTableName(resolvedTableName + \'\')\nrequest.setSampleSize(body == null || body.sampleSize == null ? 20 : body.sampleSize::int)\nrequest.setSampleMethod(SampleRequest.SampleMethod.FIRST)\nif (body != null && body.columns != null) {\n    request.setColumns(body.columns)\n}\nif (body != null && body.whereClause != null) {\n    request.setWhereClause(body.whereClause)\n}\n\n// 返回当前业务分支的标准结果。\nreturn metadataExplorerService.sampleData(request)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/12.数据库表抽样.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bc30a3edb1f04bceaeee373ed5952d4a',NULL,NULL,'{\n  "properties": {},\n  "id": "bc30a3edb1f04bceaeee373ed5952d4a",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "13.数据表预览",\n  "createTime": 1782955344263,\n  "updateTime": 1787156076929,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/table/preview-data",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"f370414d9ff64565a9fa06cbaa13d861\\",\\n    \\"pageNo\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"conditions\\": {\\n        \\"datasource\\": \\"1\\",\\n        \\"id\\": \\"00e4a8e8cc254c708925a853200bf5b9\\"\\n    },\\n    \\"columns\\": \\"测试\\",\\n    \\"sorts\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "元数据管理 13：数据表分页预览；使用请求参数 tableId、pageNo、pageSize、columns、conditions、sorts、groupByColumn、groupNameColumn；涉及 db_datasource_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：13.数据表预览\n// 路由：POST /dst/database/metadata/table/preview-data\n// 业务说明：元数据管理 13：数据表分页预览；使用请求参数 tableId、pageNo、pageSize、columns、conditions、sorts、groupByColumn、groupNameColumn；涉及 db_datasource_t、db_table_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.dto.PageQueryCondition\nimport com.linewell.dataelement.metautil.model.dto.PageQueryRequest\nimport com.linewell.dataelement.metautil.model.dto.PageQuerySort\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataDataQueryService as metadataDataQueryService\nimport java.util.Map\n\n/*\n * 元数据管理 13：数据表分页预览。\n *\n * 只读接口。根据 tableId 解析表资产和数据源资产，支持 pageNo/pageSize、columns、conditions、sorts。\n * conditions 支持 Map 形式的模糊查询，也兼容数组形式的 {field, op, value} 条件。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    var assetType = \'db\'\n    if (main == null) {\n        // 从 MySQL 业务表读取当前有效数据。\n        main = db.table(\'db_table_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n        assetType = \'table\'\n    }\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']), id: rowValue(main, [\'tid\']), assetType: assetType,\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbId: rowValue(main, [\'datasourceId\', \'datasource_id\']),\n        tableName: rowValue(main, [\'tableName\', \'table_name\']),\n        tableNameEn: rowValue(main, [\'tableName\', \'table_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var databaseType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = databaseType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\'])\n    if (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username)))) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? databaseType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(password == null ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    dsConfig.setSchema(firstValue(asset, [\'schema\', \'defaultSchema\']))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    // 返回当前业务分支的标准结果。\n    return dsConfig\n}\nvar toConditionList = (conditions) => {\n    var list = []\n    if (conditions == null) {\n        // 返回当前业务分支的标准结果。\n        return list\n    }\n    if (conditions instanceof Map) {\n        for (key in conditions.keySet()) {\n            var value = conditions[key]\n            if (!blank(value)) {\n                var c = new PageQueryCondition()\n                c.setField(key)\n                c.setOp(\'like\')\n                c.setValue(value)\n                list.add(c)\n            }\n        }\n        // 返回当前业务分支的标准结果。\n        return list\n    }\n    for (item in conditions) {\n        var field = firstValue(item, [\'field\', \'column\', \'name\'])\n        if (blank(field)) {\n            continue\n        }\n        var c = new PageQueryCondition()\n        c.setField(field)\n        c.setOp(firstValue(item, [\'op\', \'operator\']) == null ? \'like\' : firstValue(item, [\'op\', \'operator\']))\n        c.setValue(rowValue(item, [\'value\']))\n        list.add(c)\n    }\n    // 返回当前业务分支的标准结果。\n    return list\n}\nvar toSortList = (sorts) => {\n    var list = []\n    if (sorts == null) {\n        // 返回当前业务分支的标准结果。\n        return list\n    }\n    for (item in sorts) {\n        var field = firstValue(item, [\'field\', \'column\', \'name\'])\n        if (blank(field)) {\n            continue\n        }\n        var s = new PageQuerySort()\n        s.setField(field)\n        s.setDirection(firstValue(item, [\'direction\', \'order\']) == null ? \'ASC\' : firstValue(item, [\'direction\', \'order\']))\n        list.add(s)\n    }\n    // 返回当前业务分支的标准结果。\n    return list\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar tableId = body == null ? null : body.tableId\nif (blank(tableId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tableId不能为空\'\n}\n\nvar table = loadAsset(tableId)\nif (table == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tableId不正确\'\n}\nvar dbAsset = loadAsset(firstValue(table, [\'dbId\']))\nif (dbAsset == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'表所属数据源不存在\'\n}\n\nvar request = new PageQueryRequest()\nrequest.setDataSource(dataSourceOf(dbAsset))\nrequest.setTableName(firstValue(table, [\'tableName\', \'tableNameEn\']))\nrequest.setPageNo(body == null || body.pageNo == null ? 1 : body.pageNo::int)\nrequest.setPageSize(body == null || body.pageSize == null ? 20 : body.pageSize::int)\nif (body != null && body.columns != null) {\n    request.setColumns(body.columns)\n}\nrequest.setConditions(toConditionList(body == null ? null : body.conditions))\nrequest.setSorts(toSortList(body == null ? null : body.sorts))\n\nif (body != null && !blank(body.groupByColumn)) {\n    // 多类别码表按真实数据源全量分组，不能从分页预览样例推导类别。\n    return { groupedValues: metadataDataQueryService.queryGroupedValues(request, textOf(body.groupByColumn), textOf(body.groupNameColumn)) }\n}\n\n// 返回当前业务分支的标准结果。\nreturn metadataDataQueryService.queryPage(request)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/13.数据表预览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8a56e7d664934c1499102cfa508cd58a',NULL,NULL,'{\n  "properties": {},\n  "id": "8a56e7d664934c1499102cfa508cd58a",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "14.获取ddl建表语句",\n  "createTime": 1782955344281,\n  "updateTime": 1790118995803,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getCreateTableDDL",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"propList\\": {\\n        \\"dbType\\": \\"MYSQL\\",\\n        \\"tableNameCn\\": \\"字典表aaa\\",\\n        \\"tableName\\": \\"sys_file_aaa\\",\\n        \\"dbId\\": \\"8940a21f79c34bcf9a165a6b0ee8dc08\\"\\n    },\\n    \\"tableItems\\": [\\n        {\\n            \\"columnName\\": \\"id\\",\\n            \\"columnComment\\": \\"主键\\",\\n            \\"dataType\\": \\"varchar\\",\\n            \\"columnType\\": \\"varchar(36)\\",\\n            \\"length\\": 36,\\n            \\"precisionLength\\": 0,\\n            \\"scale\\": 0,\\n            \\"nullable\\": 0,\\n            \\"primaryKey\\": 1,\\n            \\"autoIncrement\\": 0,\\n            \\"isUnique\\": 1,\\n            \\"indexed\\": 1,\\n            \\"ordinalPosition\\": 1,\\n            \\"charset\\": \\"utf8mb4\\",\\n            \\"collation\\": \\"utf8mb4_general_ci\\"\\n        },\\n        {\\n            \\"columnName\\": \\"id1\\",\\n            \\"columnComment\\": \\"主键\\",\\n            \\"dataType\\": \\"int\\",\\n            \\"columnType\\": \\"int(0)\\",\\n            \\"length\\": 0,\\n            \\"precisionLength\\": 0,\\n            \\"scale\\": 0,\\n            \\"nullable\\": 0,\\n            \\"primaryKey\\": 1,\\n            \\"autoIncrement\\": 0,\\n            \\"isUnique\\": 0,\\n            \\"indexed\\": 0,\\n            \\"ordinalPosition\\": 3,\\n            \\"charset\\": \\"utf8mb4\\",\\n            \\"collation\\": \\"utf8mb4_general_ci\\"\\n        },\\n        {\\n            \\"columnName\\": \\"desc_ribe\\",\\n            \\"columnComment\\": \\"描述\\",\\n            \\"dataType\\": \\"varchar\\",\\n            \\"columnType\\": \\"varchar(100)\\",\\n            \\"length\\": 100,\\n            \\"precisionLength\\": 0,\\n            \\"scale\\": 0,\\n            \\"nullable\\": 1,\\n            \\"defaultValue\\": \\"356\\",\\n            \\"primaryKey\\": 0,\\n            \\"autoIncrement\\": 0,\\n            \\"isUnique\\": 0,\\n            \\"indexed\\": 0,\\n            \\"ordinalPosition\\": 2,\\n            \\"charset\\": \\"utf8mb4\\",\\n            \\"collation\\": \\"utf8mb4_general_ci\\"\\n        }\\n    ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "元数据管理 14：生成建表 DDL；使用请求参数 propList、tableItems、canvas、sourceDatabaseType；涉及 db_datasource_t 等业务表；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：14.获取ddl建表语句\n// 路由：POST /dst/database/metadata/getCreateTableDDL\n// 业务说明：元数据管理 14：生成建表 DDL；使用请求参数 propList、tableItems、canvas、sourceDatabaseType；涉及 db_datasource_t 等业务表；读取或计算后返回业务结果。\n\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport tenantRuntime\nimport canvasTableDdl\nimport com.linewell.dataelement.dataassets.runtime.DataSourceConnectionPropertyResolver as connectionProperties\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.ColumnInfo\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport java.util.Map\n\n/*\n * 元数据管理 14：生成建表 DDL。\n *\n * 只读接口。根据 propList.tableName/tableNameCn 和 tableItems 字段定义生成目标库方言的 CREATE TABLE。\n * 传 dbId 时按目标数据库类型生成；不传 dbId 时使用默认 MySQL 配置，仅用于模板预览。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'当前登录状态已失效，请重新登录后再生成建表脚本\'\n}\n\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).eq(\'tenant_id\', tenantId).selectOne()\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']), id: rowValue(main, [\'tid\']), assetType: \'db\',\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var host = firstValue(asset, [\'host\', \'dbIp\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\'])\n    var databaseType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = databaseType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var schema = firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\', \'schemaName\', \'owner\', \'dbSchema\'])\n    if (databaseType == DatabaseType.DAMENG) {\n        // 旧达梦数据源可能未单独存储 Schema。达梦业务账号的默认 Schema 即用户名，\n        // 因此在未显式配置时安全回退到该账号；系统账号仍会在下方被明确拦截。\n        if (blank(schema)) {\n            schema = username\n        }\n        if (blank(schema)) {\n            exit 400, \'达梦目标数据源未配置业务模式（Schema）；请在数据源连接信息中填写可建表的业务 Schema 后重试\'\n        }\n        var normalizedSchema = textOf(schema).trim().toUpperCase()\n        var damengSystemSchemas = [\'SYS\', \'SYSTEM\', \'SYSDBA\', \'SYSAUDITOR\', \'SYSSSO\', \'SYSJOB\', \'SYSDATE\', \'SYSCONSOLE\', \'SYSDBO\', \'CTISYS\', \'DBA\', \'INFORMATION_SCHEMA\']\n        if (damengSystemSchemas.indexOf(normalizedSchema) >= 0) {\n            exit 400, \'达梦目标数据源的默认模式 \' + normalizedSchema + \' 是系统内部模式；请改为业务 Schema 后重试\'\n        }\n    }\n    if (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username)))) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? databaseType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(password == null ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    dsConfig.setSchema(schema)\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    // 返回当前业务分支的标准结果。\n    return dsConfig\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar propList = body == null ? null : body.propList\nvar tableItems = body == null ? null : body.tableItems\nif (tableItems == null || tableItems.size() == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'字段列表不能为空\'\n}\nif (propList == null || blank(propList.tableName)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tableName不能为空\'\n}\n\nvar dsConfig\nif (body.canvas == true) {\n    if (blank(propList.dbId)) { exit 400, \'请选择已登记的目标库\' }\n    var registered = connectionProperties.resolve(tenantRuntime.id(), textOf(propList.dbId))\n    if (registered == null || registered.isEmpty()) { exit 404, \'当前租户中不存在所选目标数据源\' }\n    // DDL generation only needs target dialect/scope; managed Hive credentials stay on the server.\n    dsConfig = new DataSourceConfig()\n    var targetType = DatabaseType.fromCode(textOf(registered.dbType).toLowerCase())\n    if (targetType == null) { exit 400, \'目标数据源未配置数据库类型\' }\n    dsConfig.setDatabaseType(targetType)\n    dsConfig.setDatabase(firstValue(registered, [\'database\', \'dbName\', \'dbMetaDbName\']))\n    dsConfig.setUsername(firstValue(registered, [\'username\', \'user\']))\n    dsConfig.setSchema(firstValue(registered, [\'schema\', \'defaultSchema\', \'currentSchema\', \'schemaName\']))\n} else if (propList != null && !blank(propList.dbId)) {\n    var dbAsset = loadAsset(propList.dbId)\n    if (dbAsset == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'dbId参数不正确\'\n    }\n    // DDL 预览只依赖目标库方言和可选的库/模式名，并不会建立 JDBC 连接。\n    // 因此不能复用 dataSourceOf 的“主机、账号、连接参数完整”校验：\n    // 该校验属于实际建表/连通性测试，若用于预览会把本可生成的 DDL 错误地拦截。\n    dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseTypeOf(firstValue(dbAsset, [\'dbType\', \'databaseType\', \'dataSourceType\'])))\n    dsConfig.setDatabase(firstValue(dbAsset, [\'database\', \'dbName\', \'dbMetaDbName\']))\n    dsConfig.setUsername(firstValue(dbAsset, [\'username\', \'dbUser\', \'user\']))\n    dsConfig.setSchema(firstValue(dbAsset, [\'schema\', \'defaultSchema\', \'currentSchema\', \'schemaName\', \'owner\', \'dbSchema\']))\n} else {\n    dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseTypeOf(propList == null ? null : propList.dbType))\n    dsConfig.setHost(\'localhost\')\n    dsConfig.setPort(3306)\n    dsConfig.setDatabase(\'test\')\n    dsConfig.setUsername(\'root\')\n    dsConfig.setPassword(\'123456\')\n}\n\n// Final DDL guard for the protected ODS ingestion timestamps.  Callers may send\n// stale/editable table rows, so derive their physical type from the resolved\n// target datasource instead of trusting the request\'s generic `datetime` value.\nvar materializationTimeType = (databaseType) => {\n    var code = databaseType == null ? \'\' : textOf(databaseType.getCode()).trim().toLowerCase()\n    if (code.indexOf(\'oceanbase\') >= 0 || code == \'oracle\' || code == \'dameng\') {\n        return \'DATE\'\n    }\n    if (code == \'postgresql\' || code == \'kingbase\' || code == \'gaussdb\'\n        || code == \'vertica\' || code == \'hetu\' || code == \'hive\') {\n        return \'TIMESTAMP\'\n    }\n    if (code == \'sqlserver\') {\n        return \'DATETIME2\'\n    }\n    return \'DATETIME\'\n}\nvar columns = []\nfor (item in tableItems) {\n    var columnInfo = new ColumnInfo()\n    columnInfo.setSourceDatabaseType(body.sourceDatabaseType == null ? null : textOf(body.sourceDatabaseType))\n    var columnName = firstValue(item, [\'columnName\', \'name\'])\n    var normalizedColumnName = blank(columnName) ? \'\' : textOf(columnName).trim().toUpperCase()\n    var dataType = firstValue(item, [\'dataType\', \'type\'])\n    var columnType = firstValue(item, [\'columnType\'])\n    if (normalizedColumnName == \'ODS_RKSJ\' || normalizedColumnName == \'ODS_GXSJ\') {\n        dataType = materializationTimeType(dsConfig.getDatabaseType())\n        columnType = dataType\n    }\n    columnInfo.setColumnName(columnName)\n    columnInfo.setColumnComment(firstValue(item, [\'columnComment\', \'comment\']))\n    columnInfo.setDataType(dataType)\n    columnInfo.setColumnType(columnType)\n    if (rowValue(item, [\'length\']) != null) {\n        columnInfo.setLength(rowValue(item, [\'length\'])::long)\n    }\n    if (rowValue(item, [\'precisionLength\']) != null) {\n        columnInfo.setPrecision(rowValue(item, [\'precisionLength\'])::int)\n    }\n    if (rowValue(item, [\'scale\']) != null) {\n        columnInfo.setScale(rowValue(item, [\'scale\'])::int)\n    }\n    columnInfo.setNullable(rowValue(item, [\'nullable\']) == 1 || rowValue(item, [\'nullable\']) == true)\n    columnInfo.setDefaultValue(rowValue(item, [\'defaultValue\']))\n    columnInfo.setPrimaryKey(rowValue(item, [\'primaryKey\']) == 1 || rowValue(item, [\'primaryKey\']) == true)\n    columnInfo.setAutoIncrement(rowValue(item, [\'autoIncrement\']) == 1 || rowValue(item, [\'autoIncrement\']) == true)\n    columnInfo.setUnique(rowValue(item, [\'isUnique\', \'unique\']) == 1 || rowValue(item, [\'isUnique\', \'unique\']) == true)\n    columnInfo.setIndexed(rowValue(item, [\'indexed\']) == 1 || rowValue(item, [\'indexed\']) == true)\n    if (rowValue(item, [\'ordinalPosition\']) != null) {\n        columnInfo.setOrdinalPosition(rowValue(item, [\'ordinalPosition\'])::int)\n    }\n    columnInfo.setCharset(rowValue(item, [\'charset\']))\n    columnInfo.setCollation(rowValue(item, [\'collation\']))\n    columnInfo.setExtra(rowValue(item, [\'extra\']))\n    columns.add(columnInfo)\n}\n\n// 返回当前业务分支的标准结果。\ntry {\n    var ddl = metadataExplorerService.generateCreateTableDdl(dsConfig, propList.tableName, columns, propList.tableNameCn)\n    if (body.canvas == true) {\n        // Use the same single-table and target-scope validation as physical creation.\n        var parsed = canvasTableDdl.parse(ddl, dsConfig)\n        return parsed.ddl\n    }\n    return ddl\n} catch (e) {\n    exit 400, \'生成建表语句失败：\' + e.getMessage()\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/14.获取ddl建表语句.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a0b5bba38fbf428c8e3646864d83d56b',NULL,NULL,'{\n  "properties": {},\n  "id": "a0b5bba38fbf428c8e3646864d83d56b",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "15.建表接口",\n  "createTime": 1782955344211,\n  "updateTime": 1790843736559,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/createTable",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"ddl\\": \\"CREATE TABLE sys_gen_info_traget (\\\\n  id int(0) NOT NULL AUTO_INCREMENT COMMENT \'序号\',\\\\n  name varchar(50) NOT NULL COMMENT \'姓名\',\\\\n  nationality varchar(50) NOT NULL COMMENT \'国籍\',\\\\n  id_number varchar(50) NOT NULL COMMENT \'证件号码\',\\\\n  entry_date date(0) NOT NULL COMMENT \'入境日期\',\\\\n  entry_port varchar(100) NOT NULL COMMENT \'入境口岸\',\\\\n  current_location varchar(100) NOT NULL COMMENT \'当前位置\',\\\\n  in_border_status varchar(20) NOT NULL COMMENT \'在境状态\',\\\\n  risk_level varchar(20) NOT NULL COMMENT \'风险等级\',\\\\n  last_activity_time datetime(0) NOT NULL COMMENT \'最后活动时间\',\\\\n  is_del tinyint(0) NOT NULL DEFAULT 0 COMMENT \'删除标记（0-未删除，1-已删除）\',\\\\n  create_time datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间\',\\\\n  update_time datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'更新时间\',\\\\n  is_deleted int(1) NOT NULL AUTO_INCREMENT COMMENT \'删除标志\',\\\\n  PRIMARY KEY (id)\\\\n) COMMENT=\'生成表信息\';\\\\n\\",\\n    \\"dbId\\": \\"62d25cc8bf1344d6b9f41fed23af4eaf\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "建表接口（POST /dst/database/metadata/createTable）。写接口；根据 dbId 连接已登记的目标数据源并执行 DDL。默认严格执行；物化业务可传 tableName 与 skipIfExists=true，在同名物理表已存在时返回复用结果而不重复执行 DDL。 画布可传 canvas=true，按当前租户解析目标库，校验单表 DDL，返回 created/exists 状态；托管 Hive 使用服务端 hwhive；涉及 db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：15.建表接口\n// 路由：POST /dst/database/metadata/createTable\n// 业务说明：建表接口（POST /dst/database/metadata/createTable）。写接口；根据 dbId 连接已登记的目标数据源并执行 DDL。默认严格执行；物化业务可传 tableName 与 skipIfExists=true，在同名物理表已存在时返回复用结果而不重复执行 DDL。 画布可传 canvas=true，按当前租户解析目标库，校验单表 DDL，返回 created/exists 状态；托管 Hive 使用服务端 hwhive；涉及 db_datasource_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport java.util.Map\nimport tenantRuntime\nimport canvasTableDdl\nimport hwhive\nimport com.linewell.dataelement.dataassets.runtime.DataSourceConnectionPropertyResolver as connectionProperties\nimport com.linewell.dataelement.metautil.jdbc.JdbcDriverPropertyResolver\n\n/*\n * 元数据管理 15：执行建表 DDL。\n *\n * 写接口。根据 dbId 找到目标数据库连接，然后执行 body.ddl。\n * 本接口只负责物理建表，不自动登记资产；建表后若要资产快照，请调用 08 或页面登记流程。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadAsset = (assetId) => {\n    if (blank(assetId)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: rowValue(main, [\'tid\']), id: rowValue(main, [\'tid\']), assetType: \'db\',\n        dbName: rowValue(main, [\'dbName\', \'db_name\']),\n        dbType: rowValue(main, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(main, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(main, [\'username\']),\n        password: rowValue(main, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(main, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(main, [\'dbName\', \'db_name\']))) { result.dbName = rowValue(main, [\'dbName\', \'db_name\']) }\n    if (!blank(rowValue(main, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(main, [\'dbType\', \'db_type\']) }\n    if (rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(main, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(main, [\'username\']) != null) { result.username = rowValue(main, [\'username\']) }\n    if (rowValue(main, [\'password\']) != null) { result.password = rowValue(main, [\'password\']) }\n    if (!blank(rowValue(main, [\'datasourceId\', \'datasource_id\']))) { result.dbId = rowValue(main, [\'datasourceId\', \'datasource_id\']) }\n    if (!blank(rowValue(main, [\'tableName\', \'table_name\']))) {\n        result.tableName = rowValue(main, [\'tableName\', \'table_name\'])\n        result.tableNameEn = rowValue(main, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\'])\n        result.tableNameCn = rowValue(main, [\'tableNameCn\', \'table_name_cn\'])\n        result.tableComment = rowValue(main, [\'tableComment\', \'table_comment\'])\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n    try {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        // 返回当前业务分支的标准结果。\n        return DatabaseType.MYSQL\n    }\n}\nvar dataSourceOf = (asset) => {\n    var databaseType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = databaseType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\'])\n    if (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username)))) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(databaseType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? databaseType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(password == null ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    dsConfig.setSchema(firstValue(asset, [\'schema\', \'defaultSchema\']))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setJdbcProperties(JdbcDriverPropertyResolver.resolve(asset))\n    // 返回当前业务分支的标准结果。\n    return dsConfig\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar dbId = body == null ? null : body.dbId\nvar ddl = body == null ? null : body.ddl\nvar tableName = body == null ? null : body.tableName\nvar skipIfExists = body != null && body.skipIfExists == true\nif (blank(dbId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'dbId参数不正确\'\n}\nif (blank(ddl)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'ddl不能为空\'\n}\n\n// Canvas uses the same physical creation capability as materialization. Resolve\n// its selected target exclusively inside the active tenant, then validate DDL.\nif (body.canvas == true) {\n    var tenantId = tenantRuntime.id()\n    var registered = connectionProperties.resolve(tenantId, textOf(dbId))\n    if (registered == null || registered.isEmpty()) { exit 404, \'当前租户中不存在所选目标数据源\' }\n    var managedHive = textOf(registered.dbType).toLowerCase() == \'hive\'\n        && (registered.metadataAccessMode == \'server-managed-mrs\' || registered.hiveConnectionMode == \'huawei-mrs\'\n            || !blank(registered.hiveProfile))\n    var config = null\n    if (managedHive) {\n        config = new DataSourceConfig()\n        config.setDatabaseType(DatabaseType.HIVE)\n        config.setDatabase(firstValue(registered, [\'database\', \'dbName\', \'dbMetaDbName\']))\n    } else {\n        config = dataSourceOf(registered)\n    }\n    var parsed = null\n    try { parsed = canvasTableDdl.parse(textOf(ddl), config) }\n    catch (e) { exit 400, \'建表语句校验失败：\' + e.getMessage() }\n    if (!blank(tableName) && !canvasTableDdl.matches(parsed, textOf(tableName).trim(), parsed.schemaName)) {\n        exit 400, \'建表语句中的目标表名与当前填写的目标表名不一致\'\n    }\n    if (body.validateOnly == true) {\n        return { valid: true, tableName: parsed.tableName, targetScope: parsed.schemaName, ddl: parsed.ddl, sideEffectsApplied: false }\n    }\n    config.setSchema(parsed.schemaName)\n    if (managedHive) {\n        for (candidate in hwhive.showTables(config.getDatabase())) {\n            if (canvasTableDdl.matches(parsed, candidate, config.getDatabase())) {\n                return { status: \'exists\', created: false, tableName: parsed.tableName, message: \'目标表已存在，请直接选择已有表\' }\n            }\n        }\n    } else {\n        var page = metadataExplorerService.getTablesPage(config, 1, 500, parsed.lookupName)\n        for (candidate in (page == null || page.rows == null ? [] : page.rows)) {\n            if (canvasTableDdl.matches(parsed, candidate.tableName, candidate.schemaName)) {\n                return { status: \'exists\', created: false, tableName: parsed.tableName, message: \'目标表已存在，请直接选择已有表\' }\n            }\n        }\n    }\n    try {\n        if (managedHive) { hwhive.execDDLSqlInDatabase(config.getDatabase(), parsed.ddl) }\n        else { metadataExplorerService.createTable(config, parsed.ddl) }\n    } catch (e) {\n        if (canvasTableDdl.alreadyExists(e)) {\n            return { status: \'exists\', created: false, tableName: parsed.tableName, message: \'目标表已存在，请直接选择已有表\' }\n        }\n        throw e\n    }\n    return { status: \'created\', created: true, tableName: parsed.tableName, message: \'物化建表成功\' }\n}\n\nvar dbAsset = loadAsset(dbId)\nif (dbAsset == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'dbId参数不正确\'\n}\n\nvar targetConfig = dataSourceOf(dbAsset)\nif (skipIfExists && !blank(tableName)) {\n    try {\n        var page = metadataExplorerService.getTablesPage(targetConfig, 1, 200, textOf(tableName).trim())\n        var candidates = page == null || page.rows == null ? [] : page.rows\n        for (candidate in candidates) {\n            if (!blank(candidate.tableName)\n                && textOf(candidate.tableName).trim().toLowerCase() == textOf(tableName).trim().toLowerCase()) {\n                return { status: \'exists\', created: false, tableName: candidate.tableName }\n            }\n        }\n    } catch (ignored) {\n        // Some target drivers fail metadata paging; DDL execution below still handles existing-table reuse.\n    }\n}\n\ntry {\n    metadataExplorerService.createTable(targetConfig, ddl)\n} catch (e) {\n    var errorText = textOf(e == null ? \'\' : e.getMessage())\n    if (skipIfExists && (errorText.indexOf(\'已存在\') >= 0\n        || errorText.toLowerCase().indexOf(\'already exists\') >= 0\n        || errorText.toLowerCase().indexOf(\'exists\') >= 0)) {\n        return { status: \'exists\', created: false, tableName: tableName }\n    }\n    throw e\n}\nif (skipIfExists) {\n    return { status: \'created\', created: true, tableName: tableName }\n}\n// 返回当前业务分支的标准结果。\nreturn \'success\'\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/15.建表接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e715b6141da34c4ca9ebd5cc62379c5b',NULL,NULL,'{\n  "properties": {},\n  "id": "e715b6141da34c4ca9ebd5cc62379c5b",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "16.表类型智能标注",\n  "createTime": 1782955344324,\n  "updateTime": 1787153758888,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tableTypeAnnocation",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dbId\\": \\"aa912e396efb4e5daad7f3a9f383ce4f\\",\\n    \\"dryRun\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "元数据管理 16：智能标注 db_table_t 中的数据表业务类型；使用请求参数 dbId、dryRun；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：16.表类型智能标注\n// 路由：POST /dst/database/metadata/tableTypeAnnocation\n// 业务说明：元数据管理 16：智能标注 db_table_t 中的数据表业务类型；使用请求参数 dbId、dryRun；执行数据库写入并返回处理结果。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport java.util.Map\nimport log\n\n/*\n * 元数据管理 16：智能标注 db_table_t 中的数据表业务类型。\n *\n * dryRun=true 只返回建议；否则直接更新 db_table_t.business_type、\n * business_type_reason、annotated 并同步 ES，不再写 da_prop_t。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => textOf(value).toLowerCase()\nvar first = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar containsAny = (value, words) => {\n    var source = lower(value)\n    for (word in words) {\n        if (source.indexOf(word) >= 0) {\n            // 返回当前业务分支的标准结果。\n            return true\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return false\n}\nvar inferType = (table) => {\n    var value = lower(first(table, [\'tableName\', \'table_name\'])) + \' \' +\n        lower(first(table, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\']))\n    if (containsAny(value, [\'log\', \'audit\', \'trace\', \'日志\', \'审计\', \'轨迹\'])) {\n        // 返回当前业务分支的标准结果。\n        return { businessType: \'日志表\', reason: \'命中日志或审计关键字\' }\n    }\n    if (containsAny(value, [\'dict\', \'dictionary\', \'code\', \'enum\', \'字典\', \'码表\', \'枚举\'])) {\n        // 返回当前业务分支的标准结果。\n        return { businessType: \'字典表\', reason: \'命中字典或码表关键字\' }\n    }\n    if (containsAny(value, [\'tmp\', \'temp\', \'临时\'])) {\n        // 返回当前业务分支的标准结果。\n        return { businessType: \'临时表\', reason: \'命中临时表关键字\' }\n    }\n    if (containsAny(value, [\'bak\', \'backup\', \'history\', \'archive\', \'备份\', \'历史\', \'归档\'])) {\n        // 返回当前业务分支的标准结果。\n        return { businessType: \'备份表\', reason: \'命中备份或历史关键字\' }\n    }\n    // 返回当前业务分支的标准结果。\n    return { businessType: \'业务表\', reason: \'未命中特殊类型关键字，默认业务表\' }\n}\n// 解析请求体并为可选参数设置默认值。\nvar dbId = body == null ? null : body.dbId\nif (blank(dbId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'数据源dbId不能为空\'\n}\nvar dryRun = body != null && body.dryRun == true\n// 从 MySQL 业务表读取当前有效数据。\nvar tables = db.table(\'db_table_t\').where()\n    .eq(\'datasource_id\', dbId).eq(\'is_del\', 0).select()\nvar rows = []\nfor (table in tables) {\n    var tableId = first(table, [\'tid\'])\n    var decision = inferType(table)\n    var item = {\n        tid: tableId,\n        id: tableId,\n        assetType: \'table\',\n        dbId: dbId,\n        tableName: first(table, [\'tableName\', \'table_name\']),\n        tableNameEn: first(table, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\']),\n        tableNameCn: first(table, [\'tableNameCn\', \'table_name_cn\']),\n        suggestedBusinessType: decision.businessType,\n        annotationReason: decision.reason\n    }\n    if (!dryRun) {\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table(\'db_table_t\').primary(\'tid\').update({\n            tid: tableId,\n            business_type: decision.businessType,\n            business_type_reason: decision.reason,\n            annotated: 1,\n            updated_time: date_format(now)\n        }, true)\n        item.businessType = decision.businessType\n        item.annotated = 1\n        try {\n            // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n            esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(item), false)\n        } catch (e) {\n            log.warn(\'同步表类型标注到 ES 失败, tid: {}, error: {}\', tableId, e.message)\n        }\n    }\n    rows.add(item)\n}\n// 返回当前业务分支的标准结果。\nreturn { dbId: dbId, dryRun: dryRun, total: rows.size(), rows: rows }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/16.表类型智能标注.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b7f83d6c642b4b70a52715ef23f40117',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_tables_reexplore_diff_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "17.数据库表变更探查",\n  "createTime": 1784103600000,\n  "updateTime": 1789199477547,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables/reExplore",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dbId\\": \\"数据库资产ID\\",\\n    \\"keyword\\": \\"可选\\",\\n    \\"limit\\": 0\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据库表变更探查（POST /dst/database/metadata/tables/reExplore）。比较物理表与登记快照，并同步校验字段治理配置中的字典表关联：同名有效字典自动迁移，失效关联标记为待重新关联；使用请求参数 dbId；涉及 db_table_t、db_datasource_t、db_table_column_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：17.数据库表变更探查\n// 路由：POST /dst/database/metadata/tables/reExplore\n// 业务说明：数据库表变更探查（POST /dst/database/metadata/tables/reExplore）。比较物理表与登记快照，并同步校验字段治理配置中的字典表关联：同名有效字典自动迁移，失效关联标记为待重新关联；使用请求参数 dbId；涉及 db_table_t、db_datasource_t、db_table_column_t 等业务表；执行数据库写入并返回处理结果。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport java.util.Map\n\n/*\n * 元数据管理 17：比较物理库与 db_table_t 登记快照。\n *\n * 只读接口，不修改 MySQL、ES 或物理数据库。字段差异来自 db_table_column_t；\n * 返回 added/modified/deleted/unchanged，供 db-table 页面按结构视图着色。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => textOf(value).trim().toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar parseGovernanceConfig = (value) => {\n    if (blank(value)) { return null }\n    try { return value instanceof Map ? value : jsons.toJSONObject(textOf(value)) } catch (e) { return null }\n}\nvar isDictionaryRelation = (relation) => {\n    if (relation == null) { return false }\n    var enabled = lower(relation.enabled)\n    var sourceType = lower(relation.sourceType == null ? relation.mode : relation.sourceType)\n    return enabled != \'false\' && sourceType != \'enum\' && sourceType != \'standard\'\n        && (!blank(relation.dictionaryTableId) || !blank(relation.dictionaryTable))\n}\n// Reconcile every active field-governance relation against the current active\n// dictionary snapshots.  This repairs same-name ID replacement and persists an\n// explicit invalid marker when no usable dictionary asset remains.\nvar reconcileDictionaryRelations = (datasourceId, registeredRows, deletedRows) => {\n    var result = { affectedTables: 0, affectedFields: 0, migratedFields: 0, invalidatedFields: 0, restoredFields: 0 }\n    var missingIds = {}\n    var missingNames = {}\n    for (missing in deletedRows == null ? [] : deletedRows) {\n        var missingId = textOf(firstValue(missing, [\'tid\']))\n        var missingName = lower(firstValue(missing, [\'tableName\', \'table_name\']))\n        if (!blank(missingId)) { missingIds[missingId] = true }\n        if (!blank(missingName)) { missingNames[missingName] = true }\n    }\n    var dictionaryById = {}\n    var dictionaryByName = {}\n    for (candidate in registeredRows == null ? [] : registeredRows) {\n        var candidateId = textOf(firstValue(candidate, [\'tid\']))\n        var candidateName = lower(firstValue(candidate, [\'tableName\', \'table_name\']))\n        var candidateType = textOf(firstValue(candidate, [\'businessType\', \'business_type\']))\n        if (candidateType != \'字典表\' || missingIds[candidateId] == true) { continue }\n        dictionaryById[candidateId] = candidate\n        if (!blank(candidateName) && missingNames[candidateName] != true) { dictionaryByName[candidateName] = candidate }\n    }\n    for (owner in registeredRows == null ? [] : registeredRows) {\n        var ownerId = textOf(firstValue(owner, [\'tid\']))\n        var config = parseGovernanceConfig(firstValue(owner, [\'fieldGovernanceConfig\', \'field_governance_config\']))\n        if (config == null || config.fields == null) { continue }\n        var tableChanged = false\n        for (field in config.fields) {\n            var relation = field.dictionaryRelation == null ? field.dictionary_relation : field.dictionaryRelation\n            if (!isDictionaryRelation(relation)) { continue }\n            var relationId = textOf(relation.dictionaryTableId)\n            var relationName = lower(relation.dictionaryTable)\n            var candidate = blank(relationId) ? null : dictionaryById[relationId]\n            if (candidate == null && !blank(relationName)) { candidate = dictionaryByName[relationName] }\n            if (candidate != null) {\n                var candidateId = textOf(firstValue(candidate, [\'tid\']))\n                var candidateName = textOf(firstValue(candidate, [\'tableName\', \'table_name\']))\n                var wasInvalid = lower(relation.invalid) == \'true\'\n                if (relationId != candidateId || relationName != lower(candidateName) || wasInvalid) {\n                    relation.dictionaryTableId = candidateId\n                    relation.dictionaryTable = candidateName\n                    relation.invalid = false\n                    relation.invalidReason = \'\'\n                    relation.invalidTableId = \'\'\n                    relation.invalidTableName = \'\'\n                    tableChanged = true\n                    result.affectedFields = result.affectedFields + 1\n                    if (relationId != candidateId) { result.migratedFields = result.migratedFields + 1 }\n                    if (wasInvalid) { result.restoredFields = result.restoredFields + 1 }\n                }\n            } else {\n                var alreadyInvalid = lower(relation.invalid) == \'true\'\n                if (!alreadyInvalid || textOf(relation.invalidTableId) != relationId || lower(relation.invalidTableName) != relationName) {\n                    relation.invalid = true\n                    relation.invalidReason = \'关联字典已失效，请重新关联\'\n                    relation.invalidTableId = relationId\n                    relation.invalidTableName = textOf(relation.dictionaryTable)\n                    tableChanged = true\n                    result.affectedFields = result.affectedFields + 1\n                    result.invalidatedFields = result.invalidatedFields + 1\n                }\n            }\n        }\n        if (tableChanged) {\n            db.table(\'db_table_t\').where().eq(\'tid\', ownerId).eq(\'is_del\', 0)\n                // Hutool\'s parser preserves JSON nulls as JSONNull; use its own\n                // serializer here so legacy nullable governance fields remain valid JSON.\n                .update({ field_governance_config: JSONUtil.toJsonStr(config), updated_time: new Date() })\n            result.affectedTables = result.affectedTables + 1\n        }\n    }\n    return result\n}\nvar columnNameOf = (column) => column instanceof Map\n    ? firstValue(column, [\'columnName\', \'column_name\'])\n    : column == null ? null : column.columnName\nvar columnTypeOf = (column) => column instanceof Map\n    ? firstValue(column, [\'columnType\', \'column_type\', \'dataType\', \'data_type\'])\n    : column == null ? null : (blank(column.columnType) ? column.dataType : column.columnType)\nvar columnCommentOf = (column) => column instanceof Map\n    ? firstValue(column, [\'columnComment\', \'column_comment\'])\n    : column == null ? null : column.columnComment\nvar normalizeColumnTypeForDiff = (value) => {\n    var text = lower(value)\n    if (blank(text)) {\n        return \'\'\n    }\n    var bracket = text.indexOf(\'(\')\n    var base = bracket >= 0 ? text.substring(0, bracket).trim() : text\n    // JDBC often reports DATETIME as DATETIME(19); this is display size, not a schema change.\n    if (base == \'datetime\' || base == \'timestamp\' || base == \'date\' || base == \'time\' || base == \'year\') {\n        return base\n    }\n    // MySQL integer display width is also not a meaningful structural change.\n    if (base == \'int\' || base == \'integer\' || base == \'bigint\' || base == \'smallint\' || base == \'tinyint\' || base == \'mediumint\') {\n        return base\n    }\n    // Length-bearing text/decimal/binary types keep their precision in the normalized value.\n    return text.replaceAll(\'\\\\s+\', \' \')\n}\nvar loadSource = (datasourceId) => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var source = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\n    if (source == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: datasourceId,\n        dbName: rowValue(source, [\'dbName\', \'db_name\']),\n        dbType: rowValue(source, [\'dbType\', \'db_type\']),\n        username: rowValue(source, [\'username\']),\n        password: rowValue(source, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(source, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    result.tid = datasourceId\n    result.dbName = rowValue(source, [\'dbName\', \'db_name\'])\n    result.dbType = rowValue(source, [\'dbType\', \'db_type\'])\n    result.username = rowValue(source, [\'username\'])\n    result.password = rowValue(source, [\'password\'])\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar dataSourceOf = (source) => {\n    var config = new DataSourceConfig()\n    var code = firstValue(source, [\'dbType\', \'databaseType\'])\n    try {\n        config.setDatabaseType(blank(code) ? DatabaseType.MYSQL : DatabaseType.fromCode(lower(code)))\n    } catch (e) {\n        config.setDatabaseType(DatabaseType.MYSQL)\n    }\n    config.setHost(textOf(firstValue(source, [\'ftpHost\', \'host\', \'dbIp\'])))\n    var port = firstValue(source, [\'ftpPort\', \'port\', \'dbPort\'])\n    config.setPort(blank(port) ? 3306 : port::int)\n    config.setDatabase(textOf(firstValue(source, [\'database\', \'dbName\', \'dbMetaDbName\'])))\n    config.setUsername(textOf(firstValue(source, [\'ftpUsername\', \'username\', \'dbUser\', \'dbMetaUser\'])))\n    config.setPassword(textOf(firstValue(source, [\'ftpPassword\', \'password\', \'dbPassword\', \'dbMetaPassword\'])))\n    // 保留 FTP 协议、目录、匹配规则及解析选项，使第二步与第一步识别同一批文件。\n    config.setConnectorProperties(source)\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    config.setJdbcUrl(firstValue(source, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    config.setSchema(firstValue(source, [\'schema\', \'defaultSchema\']))\n    // MinIO uses the optional object prefix as its table-discovery scope.\n    // Reuse schema only inside the Java MinIO explorer; it keeps the shared\n    // DataSourceConfig contract unchanged for every relational connector.\n    if (config.getDatabaseType() == DatabaseType.MINIO) {\n        config.setSchema(firstValue(source, [\'minioPrefix\', \'objectPrefix\', \'prefix\']))\n    }\n    // 返回当前业务分支的标准结果。\n    return config\n}\nvar columnMap = (columns) => {\n    var result = {}\n    for (column in columns == null ? [] : columns) {\n        var name = columnNameOf(column)\n        if (!blank(name)) {\n            result[lower(name)] = column\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar datasourceId = body == null ? null : body.dbId\nif (blank(datasourceId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'dbId 不能为空\'\n}\nvar source = loadSource(datasourceId)\nif (source == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'数据源不存在\'\n}\nvar config = dataSourceOf(source)\nvar physicalRows = metadataExplorerService.getTables(config)\n// 从 MySQL 业务表读取当前有效数据。\nvar registeredRows = db.table(\'db_table_t\').where()\n    .eq(\'datasource_id\', datasourceId).eq(\'is_del\', 0).select()\n// 结构化数据源会随着文件、对象或接口响应变化。先形成本轮可发现表的集合，\n// 仅对仍存在的登记表读取字段；不再用已经消失的历史表名调用远端读取。\nvar physicalTableKeys = {}\nfor (physical in physicalRows == null ? [] : physicalRows) {\n    var physicalTableName = physical.tableName\n    if (!blank(physicalTableName)) {\n        physicalTableKeys[lower(physicalTableName)] = true\n    }\n}\nvar registeredMap = {}\nvar registeredTableIds = []\nvar registeredTableNames = []\nfor (row in registeredRows) {\n    var tableName = firstValue(row, [\'tableName\', \'table_name\'])\n    if (!blank(tableName)) {\n        var tableKey = lower(tableName)\n        registeredMap[tableKey] = row\n        // 不存在于本轮探查结果的记录将在下方按“已删除”返回，不能再请求其字段。\n        if (physicalTableKeys[tableKey] == true) {\n            registeredTableNames.add(tableName)\n        }\n        registeredTableIds.add(firstValue(row, [\'tid\']))\n    }\n}\n// 一次批量读取仍存在表的字段，避免远端逐表调用及历史表导致整批失败。\nvar physicalColumnsByTable = metadataExplorerService.getColumnsByTables(config, registeredTableNames)\nvar storedColumnsByTable = {}\nif (registeredTableIds.size() > 0) {\n    var storedColumns = db.table(\'db_table_column_t\').where()\n        .in(\'table_id\', registeredTableIds).eq(\'is_del\', 0).select()\n    for (column in storedColumns) {\n        var storedTableId = textOf(firstValue(column, [\'tableId\', \'table_id\']))\n        if (storedColumnsByTable[storedTableId] == null) {\n            storedColumnsByTable[storedTableId] = []\n        }\n        storedColumnsByTable[storedTableId].add(column)\n    }\n}\nvar added = []\nvar modified = []\nvar unchanged = []\nvar deleted = []\n\nfor (physical in physicalRows == null ? [] : physicalRows) {\n    var tableName = physical.tableName\n    if (blank(tableName)) {\n        continue\n    }\n    var key = lower(tableName)\n    var before = registeredMap[key]\n    registeredMap[key] = null\n    // 表列表接口已经返回字段数。新增表只需要先展示在“新增”列表，不要逐表读取字段，\n    // 否则 Kingbase/Oracle 等大库会因为几百张表逐个查字段导致详情页探查超时。\n    var currentColumns = before == null ? [] : physicalColumnsByTable[key]\n    if (currentColumns == null) {\n        currentColumns = []\n    }\n    var physicalColumnCount = physical.columnCount == null ? 0 : physical.columnCount\n    var current = {\n        tableName: tableName,\n        tableNameEn: tableName,\n        tableNameCn: blank(physical.tableComment) ? tableName : physical.tableComment,\n        tableComment: blank(physical.tableComment) ? tableName : physical.tableComment,\n        tableType: physical.tableType,\n        fieldCount: before == null ? physicalColumnCount : (currentColumns == null ? 0 : currentColumns.size()),\n        columnCount: before == null ? physicalColumnCount : (currentColumns == null ? 0 : currentColumns.size()),\n        recordCount: physical.rowCount == null ? 0 : physical.rowCount,\n        storageSize: physical.totalSizeFormatted,\n        columns: currentColumns == null ? [] : currentColumns\n    }\n    if (before == null) {\n        added.add(current)\n        continue\n    }\n    var tableId = firstValue(before, [\'tid\'])\n    // 从 MySQL 业务表读取当前有效数据。\n    var oldColumns = storedColumnsByTable[textOf(tableId)]\n    if (oldColumns == null) {\n        oldColumns = []\n    }\n    var oldMap = columnMap(oldColumns)\n    var newMap = columnMap(currentColumns)\n    var columnsAdded = []\n    var columnsDeleted = []\n    var columnsModified = []\n    for (columnKey in newMap.keySet()) {\n        var afterColumn = newMap[columnKey]\n        var beforeColumn = oldMap[columnKey]\n        if (beforeColumn == null) {\n            columnsAdded.add(columnNameOf(afterColumn))\n        } else {\n            var beforeType = columnTypeOf(beforeColumn)\n            var afterType = columnTypeOf(afterColumn)\n            var beforeComment = columnCommentOf(beforeColumn)\n            var afterComment = columnCommentOf(afterColumn)\n            // Compare field types by database semantics: case and JDBC display width must not reset the workflow.\n            if (normalizeColumnTypeForDiff(beforeType) != normalizeColumnTypeForDiff(afterType) || lower(beforeComment) != lower(afterComment)) {\n                columnsModified.add(columnNameOf(afterColumn))\n            }\n            oldMap[columnKey] = null\n        }\n    }\n    for (columnKey in oldMap.keySet()) {\n        var oldColumn = oldMap[columnKey]\n        if (oldColumn != null) {\n            columnsDeleted.add(columnNameOf(oldColumn))\n        }\n    }\n    // 中文表名是登记分类信息，不是物理文件的备注；仅比较真实备注，避免误报结构变更。\n    var beforeComment = firstValue(before, [\'tableComment\', \'table_comment\'])\n    // Legacy/imported records may have an empty table comment snapshot. A newly read physical comment is enrichment,\n    // not a structural change that should reset the registration workflow.\n    // FTP 的文件名只是探查备注，不能覆盖或影响用户维护的中文表名。\n    var commentChanged = config.getDatabaseType() != DatabaseType.FTP &&\n        !blank(beforeComment) && lower(beforeComment) != lower(current.tableComment)\n    var fieldCountChanged = oldColumns.size() != current.fieldCount\n    var hasChange = commentChanged || fieldCountChanged ||\n        columnsAdded.size() > 0 || columnsDeleted.size() > 0 || columnsModified.size() > 0\n    if (hasChange) {\n        modified.add({\n            tableName: tableName,\n            before: {\n                tid: tableId,\n                tableName: firstValue(before, [\'tableName\', \'table_name\']),\n                tableNameCn: beforeComment,\n                tableComment: beforeComment,\n                tableType: firstValue(before, [\'tableType\', \'table_type\']),\n                fieldCount: oldColumns.size(),\n                recordCount: rowValue(before, [\'recordCount\', \'record_count\']),\n                storageSize: firstValue(before, [\'storageSize\', \'storage_size\'])\n            },\n            after: current,\n            changes: {\n                tableCommentChanged: commentChanged,\n                fieldCountChanged: fieldCountChanged,\n                tableTypeChanged: false,\n                recordCountChanged: false,\n                columnsAdded: columnsAdded,\n                columnsDeleted: columnsDeleted,\n                columnsModified: columnsModified\n            }\n        })\n    } else {\n        unchanged.add(current)\n    }\n}\nfor (key in registeredMap.keySet()) {\n    var row = registeredMap[key]\n    if (row != null) {\n        deleted.add({\n            tid: firstValue(row, [\'tid\']),\n            tableName: firstValue(row, [\'tableName\', \'table_name\']),\n            tableNameEn: firstValue(row, [\'tableName\', \'table_name\']),\n            tableNameCn: firstValue(row, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']),\n            tableComment: firstValue(row, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\']),\n            tableType: firstValue(row, [\'tableType\', \'table_type\']),\n            businessType: firstValue(row, [\'businessType\', \'business_type\']),\n            fieldCount: rowValue(row, [\'fieldCount\', \'field_count\']),\n            recordCount: rowValue(row, [\'recordCount\', \'record_count\'])\n        })\n    }\n}\nvar relationRepair = reconcileDictionaryRelations(datasourceId, registeredRows, deleted)\n// 返回当前业务分支的标准结果。\nreturn {\n    summary: {\n        totalScanned: physicalRows == null ? 0 : physicalRows.size(),\n        addedCount: added.size(),\n        modifiedCount: modified.size(),\n        deletedCount: deleted.size(),\n        unchangedCount: unchanged.size(),\n        relationRepair: relationRepair\n    },\n    added: added,\n    modified: modified,\n    deleted: deleted,\n    unchanged: unchanged,\n    relationRepair: relationRepair\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/17.数据库表变更探查.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_tables_delete_asset_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_tables_delete_asset_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "18.删除已登记表资产",\n  "createTime": null,\n  "updateTime": 1790152445533,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tables/deleteAsset",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"dbId\\":\\"6b1bbbcf1e8b448fb9c072a4f07d6a7b\\",\\"tableIds\\":[\\"2903feee5161484cac3c8b0b2894bedc\\"],\\"dryRun\\":true}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"deleted\\":true,\\"batch\\":true,\\"requestedCount\\":1,\\"deletedCount\\":1,\\"deletedTableIds\\":[],\\"failed\\":[]}",\n  "description": "删除已失效表资产（POST /dst/database/metadata/tables/deleteAsset）。支持 tableId 或 tableIds 一次批量级联清理；兼容历史租户缺少的非核心目录关联表；不删除物理表，dryRun=true 仅统计；涉及 db_table_t、da_prop_t、data_access_agg_task_t、db_table_column_t、da_asset_catalog_item_t、da_app_catalog_rela 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：18.删除已登记表资产\n// 路由：POST /dst/database/metadata/tables/deleteAsset\n// 业务说明：删除已失效表资产（POST /dst/database/metadata/tables/deleteAsset）。支持 tableId 或 tableIds 一次批量级联清理；兼容历史租户缺少的非核心目录关联表；不删除物理表，dryRun=true 仅统计；涉及 db_table_t、da_prop_t、data_access_agg_task_t、db_table_column_t、da_asset_catalog_item_t、da_app_catalog_rela 等业务表。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport java.util.Map\nimport tenantRuntime\n\n/*\n * 元数据管理 18：级联删除已登记但物理库已不存在的数据表资产。\n *\n * 只清理平台登记资产。共享目录仍被其他表引用时仅解除当前表关系，\n * 不会误删共享目录，也绝不连接业务库执行 DROP TABLE。\n */\n\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar datasourceId = body == null ? null : body.dbId\nvar tableId = body == null ? null : body.tableId\nvar dryRun = body != null && (body.dryRun == true || body.dryRun == 1 || body.dryRun == \'1\')\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'租户会话已失效，请重新登录\'\n}\nif (blank(datasourceId)) {\n    exit 400, \'dbId 不能为空\'\n}\ndatasourceId = (datasourceId + \'\').trim()\ntableId = blank(tableId) ? null : (tableId + \'\').trim()\n\nvar textOf = value => value == null ? \'\' : (value + \'\').trim()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && textOf(row[key]) != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar addUnique = (list, value) => {\n    var normalized = textOf(value)\n    if (normalized != \'\' && list.filter(item => textOf(item) == normalized).size() == 0) {\n        list.add(normalized)\n    }\n}\n\n// 支持单表和批量删除：批量请求只提交一次，由服务端统一执行清理。\nvar tableIds = []\nvar rawTableIds = body == null ? null : body.tableIds\nif (rawTableIds != null) {\n    for (candidateId in rawTableIds) {\n        addUnique(tableIds, candidateId)\n    }\n}\naddUnique(tableIds, tableId)\nif (tableIds.size() == 0) {\n    exit 400, \'tableId 或 tableIds 不能为空\'\n}\ntableId = tableIds[0]\n\n// 历史租户可能尚未创建部分目录关联表。缺表时跳过该非核心关联清理，\n// 不能阻断 db_table_t、字段与目录属性的正常删除。\nvar skippedLegacyTables = []\nvar safeUpdate = (tableName, operation) => {\n    try {\n        return operation()\n    } catch (e) {\n        var message = textOf(e).toLowerCase()\n        if (message.indexOf("doesn\'t exist") >= 0 || message.indexOf(\'table not found\') >= 0 || message.indexOf(\'不存在\') >= 0) {\n            addUnique(skippedLegacyTables, tableName)\n            return 0\n        }\n        throw e\n    }\n}\nvar table = null\n\n// Reconcile dictionary relations before/after a dictionary table asset is retired.\n// A same-name active dictionary is treated as the replacement; otherwise the\n// relation remains visible but is explicitly marked invalid for Step 4 repair.\nvar parseGovernanceConfig = (value) => {\n    if (value == null || textOf(value) == \'\') { return null }\n    try { return value instanceof Map ? value : jsons.toJSONObject(textOf(value)) } catch (e) { return null }\n}\nvar isDictionaryRelation = (relation) => {\n    if (relation == null) { return false }\n    var enabled = textOf(relation.enabled).toLowerCase()\n    var sourceType = textOf(relation.sourceType == null ? relation.mode : relation.sourceType).toLowerCase()\n    return enabled != \'false\' && sourceType != \'enum\' && sourceType != \'standard\'\n        && (textOf(relation.dictionaryTableId) != \'\' || textOf(relation.dictionaryTable) != \'\')\n}\nvar reconcileRetiredDictionaryRelations = (applyChanges) => {\n    var result = { affectedTables: 0, affectedFields: 0, migratedFields: 0, invalidatedFields: 0, replacementTableId: null }\n    var businessType = textOf(rowValue(table, [\'businessType\', \'business_type\']))\n    if (businessType != \'字典表\') { return result }\n    var retiredName = textOf(rowValue(table, [\'tableName\', \'table_name\'])).toLowerCase()\n    var activeRows = db.table(\'db_table_t\').where().eq(\'datasource_id\', datasourceId).eq(\'is_del\', 0).select()\n    var replacement = null\n    for (candidate in activeRows) {\n        var candidateId = textOf(rowValue(candidate, [\'tid\']))\n        var candidateName = textOf(rowValue(candidate, [\'tableName\', \'table_name\'])).toLowerCase()\n        var candidateType = textOf(rowValue(candidate, [\'businessType\', \'business_type\']))\n        if (candidateId != tableId && candidateType == \'字典表\' && candidateName == retiredName) {\n            replacement = candidate\n            break\n        }\n    }\n    var replacementId = replacement == null ? \'\' : textOf(rowValue(replacement, [\'tid\']))\n    var replacementName = replacement == null ? \'\' : textOf(rowValue(replacement, [\'tableName\', \'table_name\']))\n    result.replacementTableId = replacementId == \'\' ? null : replacementId\n    for (owner in activeRows) {\n        var ownerId = textOf(rowValue(owner, [\'tid\']))\n        if (ownerId == tableId) { continue }\n        var config = parseGovernanceConfig(rowValue(owner, [\'fieldGovernanceConfig\', \'field_governance_config\']))\n        if (config == null || config.fields == null) { continue }\n        var tableChanged = false\n        for (field in config.fields) {\n            var relation = field.dictionaryRelation == null ? field.dictionary_relation : field.dictionaryRelation\n            if (!isDictionaryRelation(relation)) { continue }\n            var relationId = textOf(relation.dictionaryTableId)\n            var relationName = textOf(relation.dictionaryTable).toLowerCase()\n            if (relationId != tableId && !(relationId == \'\' && relationName == retiredName)) { continue }\n            result.affectedFields = result.affectedFields + 1\n            tableChanged = true\n            if (replacementId != \'\') {\n                relation.dictionaryTableId = replacementId\n                relation.dictionaryTable = replacementName\n                relation.invalid = false\n                relation.invalidReason = \'\'\n                relation.invalidTableId = \'\'\n                relation.invalidTableName = \'\'\n                result.migratedFields = result.migratedFields + 1\n            } else {\n                relation.invalid = true\n                relation.invalidReason = \'关联字典已失效，请重新关联\'\n                relation.invalidTableId = tableId\n                relation.invalidTableName = textOf(rowValue(table, [\'tableName\', \'table_name\']))\n                result.invalidatedFields = result.invalidatedFields + 1\n            }\n        }\n        if (tableChanged) {\n            result.affectedTables = result.affectedTables + 1\n            if (applyChanges) {\n                db.table(\'db_table_t\').where().eq(\'tid\', ownerId).eq(\'is_del\', 0)\n                    // Preserve nullable historical fields without exposing Hutool\n                    // JSONNull to the platform Jackson serializer.\n                    .update({ field_governance_config: JSONUtil.toJsonStr(config), updated_time: new Date() })\n            }\n        }\n    }\n    return result\n}\n\nvar deleteOne = itemId => {\n    tableId = textOf(itemId)\n    table = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (table == null) {\n    return { deleted: false, dryRun: dryRun, reason: \'notFound\', cleanup: { columns: 0, catalogs: 0, tasks: 0 } }\n}\nif (!blank(rowValue(table, [\'datasourceId\', \'datasource_id\'])) && textOf(rowValue(table, [\'datasourceId\', \'datasource_id\'])) != datasourceId) {\n    exit 400, \'数据表不属于当前数据源\'\n}\n\n// 收集表直接关联的目录，再识别哪些目录为该表独占，避免误删共享目录。\nvar candidateCatalogIds = []\naddUnique(candidateCatalogIds, rowValue(table, [\'sourceCatalogId\', \'source_catalog_id\']))\nvar catalogTableProps = db.table(\'da_prop_t\').where()\n    .eq(\'data_type\', \'catalog\')\n    .in(\'prop_name\', [\'sourceTableId\', \'targetTableId\'])\n    .eq(\'prop_value\', tableId)\n    .eq(\'is_del\', 0)\n    .select()\nfor (prop in catalogTableProps) {\n    addUnique(candidateCatalogIds, rowValue(prop, [\'parentId\', \'parent_id\']))\n}\n\nvar catalogIds = []\nfor (candidateCatalogId in candidateCatalogIds) {\n    var shared = false\n    var relationProps = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', candidateCatalogId)\n        .eq(\'data_type\', \'catalog\')\n        .in(\'prop_name\', [\'sourceTableId\', \'targetTableId\'])\n        .eq(\'is_del\', 0)\n        .select()\n    for (prop in relationProps) {\n        if (textOf(rowValue(prop, [\'propValue\', \'prop_value\'])) != tableId) {\n            shared = true\n        }\n    }\n    if (!shared) {\n        addUnique(catalogIds, candidateCatalogId)\n    }\n}\n\n// 表及其专属目录关联的任务无法继续运行，需要一并清理。\nvar taskIds = []\nvar pipelineIds = []\nvar collectTasks = rows => {\n    for (task in rows) {\n        addUnique(taskIds, rowValue(task, [\'tid\']))\n        addUnique(pipelineIds, rowValue(task, [\'pipelineId\', \'pipeline_id\']))\n    }\n}\ncollectTasks(db.table(\'data_access_agg_task_t\').where().eq(\'source_table_id\', tableId).eq(\'is_del\', 0).select())\ncollectTasks(db.table(\'data_access_agg_task_t\').where().eq(\'target_table_id\', tableId).eq(\'is_del\', 0).select())\nif (catalogIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where().in(\'data_catalog_id\', catalogIds).eq(\'is_del\', 0).select())\n}\n\nvar columnCount = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableId).eq(\'is_del\', 0).count()\nvar dictionaryRelationPlan = reconcileRetiredDictionaryRelations(false)\nif (dryRun) {\n    return {\n        deleted: false,\n        dryRun: true,\n        tableName: rowValue(table, [\'tableName\', \'table_name\']),\n        cleanup: { columns: columnCount, catalogs: catalogIds.size(), tasks: taskIds.size(), dictionaryRelations: dictionaryRelationPlan }\n    }\n}\n\nvar nowTime = new Date()\nvar cleanup = { columns: columnCount, catalogs: catalogIds.size(), tasks: taskIds.size(), relationRows: 0, propertyRows: 0, skippedLegacyTables: skippedLegacyTables }\n\n// 先删字段、属性和所有指向当前表的关系。\ncleanup.columns = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableId).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: nowTime })\ncleanup.propertyRows = cleanup.propertyRows + db.table(\'da_prop_t\').where().eq(\'parent_id\', tableId).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: nowTime })\ncleanup.relationRows = cleanup.relationRows + db.table(\'da_prop_t\').where()\n    .eq(\'data_type\', \'catalog\')\n    .in(\'prop_name\', [\'sourceTableId\', \'targetTableId\'])\n    .eq(\'prop_value\', tableId)\n    .eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: nowTime })\n\n// 仅删除没有其他表引用的专属目录及其下游关系。\nif (catalogIds.size() > 0) {\n    cleanup.relationRows = cleanup.relationRows + safeUpdate(\'da_asset_catalog_item_t\', () =>\n        db.table(\'da_asset_catalog_item_t\').where().in(\'catalog_id\', catalogIds).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: nowTime })\n    )\n    cleanup.relationRows = cleanup.relationRows + safeUpdate(\'da_app_catalog_rela\', () =>\n        db.table(\'da_app_catalog_rela\').where().in(\'data_catalog_id\', catalogIds).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: nowTime })\n    )\n    cleanup.relationRows = cleanup.relationRows + safeUpdate(\'da_asset_api_rela\', () =>\n        db.table(\'da_asset_api_rela\').where().in(\'catalog_id\', catalogIds).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: nowTime })\n    )\n    cleanup.relationRows = cleanup.relationRows + db.table(\'data_apply_form_catalog_rela\').where().in(\'catalog_id\', catalogIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    cleanup.relationRows = cleanup.relationRows + db.table(\'data_market_shopping_cart_t\').where().in(\'catalog_id\', catalogIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    cleanup.propertyRows = cleanup.propertyRows + db.table(\'da_prop_t\').where().in(\'parent_id\', catalogIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    safeUpdate(\'da_asset_t\', () =>\n        db.table(\'da_asset_t\').where().in(\'tid\', catalogIds).eq(\'asset_type\', \'catalog\').eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: nowTime })\n    )\n}\n\nif (taskIds.size() > 0) {\n    db.table(\'data_access_field_mapping\').where().in(\'task_id\', taskIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    db.table(\'data_access_task_monitor_snap_t\').where().in(\'task_id\', taskIds).eq(\'is_del\', 0)\n        .update({ is_del: 1 })\n    db.table(\'data_access_agg_task_t\').where().in(\'tid\', taskIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime, task_status: 0 })\n}\nif (pipelineIds.size() > 0) {\n    db.table(\'nifi_pipeline_t\').where().in(\'id\', pipelineIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_at: System.currentTimeMillis() })\n}\n\nvar assetIds = [tableId]\nfor (catalogId in catalogIds) {\n    addUnique(assetIds, catalogId)\n}\ncleanup.relationRows = cleanup.relationRows + safeUpdate(\'da_order_asset_rela\', () =>\n    db.table(\'da_order_asset_rela\').where().in(\'asset_id\', assetIds).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n)\n\nvar tableDeleted = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: nowTime })\ncleanup.dictionaryRelations = tableDeleted > 0 ? reconcileRetiredDictionaryRelations(true) : dictionaryRelationPlan\n\n// 删除 ES 投影，确保资源列表不再命中已删除表和专属目录。\nif (tableDeleted > 0) {\n    esCommonService.deleteById(\'dataassets\', tableId)\n}\nfor (catalogId in catalogIds) {\n    esCommonService.deleteById(\'dataassets\', catalogId)\n}\n\nreturn { deleted: tableDeleted > 0, dryRun: false, tableId: tableId, cleanup: cleanup }\n}\n\nvar results = []\nvar deletedTableIds = []\nvar failed = []\nfor (requestedTableId in tableIds) {\n    if (tableIds.size() == 1) {\n        results.add(deleteOne(requestedTableId))\n        continue\n    }\n    try {\n        var result = deleteOne(requestedTableId)\n        results.add(result)\n        if (dryRun) {\n            continue\n        }\n        if (result != null && result.deleted == true) {\n            addUnique(deletedTableIds, requestedTableId)\n        } else {\n            failed.add({ tableId: requestedTableId, reason: result == null ? \'deleteFailed\' : (result.reason || \'deleteFailed\') })\n        }\n    } catch (e) {\n        failed.add({ tableId: requestedTableId, reason: textOf(e) })\n    }\n}\nif (tableIds.size() == 1) {\n    return results[0]\n}\nreturn {\n    deleted: failed.size() == 0,\n    batch: true,\n    dryRun: dryRun,\n    requestedCount: tableIds.size(),\n    deletedCount: deletedTableIds.size(),\n    deletedTableIds: deletedTableIds,\n    failed: failed,\n    results: results,\n    skippedLegacyTables: skippedLegacyTables\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/18.删除已登记表资产.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_remote_table_data_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_remote_table_data_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "19.远程表数据操作",\n  "createTime": 1784419200000,\n  "updateTime": 1784437772101,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remote-table/data",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNo\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"sortField\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据数据源连接、表名和 action 执行远程表数据查询或写入；校验批次、关键字段及目标库类型后返回操作结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：19.远程表数据操作\n// 路由：POST /dst/database/metadata/remote-table/data\n// 业务说明：根据数据源连接、表名和 action 执行远程表数据查询或写入；校验批次、关键字段及目标库类型后返回操作结果。\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.dto.PageQueryRequest\nimport com.linewell.dataelement.metautil.model.dto.PageQuerySort\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataDataQueryService as metadataDataQueryService\nimport com.linewell.dataelement.metautil.service.RemoteTableDataService as remoteTableDataService\n\n/**\n * 连接参数兼容旧文件资源接口中的 user/dbType 命名，也接受标准\n * username/databaseType 命名。密码只用于本次 JDBC 调用，不写入日志。\n */\nvar connection = body?.connection || body?.dataSource || {}\nvar rawType = (body?.dbType || connection?.dbType || connection?.databaseType || "").toString().toLowerCase()\nvar typeNames = {\n    mysql: "MYSQL",\n    postgresql: "POSTGRESQL",\n    postgres: "POSTGRESQL",\n    oracle: "ORACLE",\n    dameng: "DAMENG",\n    dm: "DAMENG",\n    gaussdb: "GAUSSDB",\n    kingbase: "KINGBASE",\n    hive: "HIVE",\n    oceanbase_mysql: "OCEANBASE_MYSQL",\n    oceanbase_oracle: "OCEANBASE_ORACLE"\n}\nvar typeName = typeNames[rawType]\nif (!typeName) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "不支持的数据库类型: " + rawType\n}\n\nvar config = new DataSourceConfig()\nconfig.setDatabaseType(DatabaseType.valueOf(typeName))\nconfig.setHost(connection?.host)\nconfig.setPort(connection?.port == null ? null : connection.port.toString()::int())\nconfig.setDatabase(connection?.database || connection?.serviceName)\nconfig.setSchema(connection?.schema)\nconfig.setUsername(connection?.username || connection?.user)\nconfig.setPassword(connection?.password)\n// Reuse the exact JDBC URL entered by the user, including Oracle connection mode.\nconfig.setJdbcUrl(connection?.jdbcURL || connection?.jdbcUrl)\nconfig.setExtraParams(connection?.extraParams)\n\nif (!config.host || !config.username || config.password == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "远程数据库 host、username/user、password 不能为空"\n}\n\nvar action = body?.action\nvar tableName = body?.tableName\n\nif (action == "count") {\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.count(config, tableName)\n}\n\nif (action == "listTables") {\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.listTables(config)\n}\n\nif (action == "batchInsert") {\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.batchInsert(config, tableName, body?.rows || [], body?.batchSize || 500)\n}\n\nif (action == "batchResetInsert") {\n    var rows = body?.rows || []\n    var key = body?.key\n    if (!key) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "batchResetInsert 操作的 key 不能为空"\n    }\n    var values = []\n    rows.each(row => {\n        if (row[key] != null) {\n            values.add(row[key])\n        }\n    })\n    if (values.size() > 0) {\n        remoteTableDataService.deleteByValues(config, tableName, key, values)\n    }\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.batchInsert(config, tableName, rows, body?.batchSize || 500)\n}\n\nif (action == "deleteByValues") {\n    var values = body?.values\n    if (values == null) {\n        values = [body?.value]\n    }\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.deleteByValues(config, tableName, body?.key, values)\n}\n\nif (action == "deleteBefore") {\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.deleteBefore(config, tableName, body?.key, body?.value)\n}\n\nif (action == "deleteAll") {\n    // 返回当前业务分支的标准结果。\n    return remoteTableDataService.deleteAll(config, body?.tableNames || [])\n}\n\nif (action == "preview") {\n    var request = new PageQueryRequest()\n    request.setDataSource(config)\n    request.setTableName(tableName)\n    request.setPageNo(body?.pageNo == null ? 1 : body.pageNo.toString()::int())\n    request.setPageSize(body?.pageSize == null ? 20 : body.pageSize.toString()::int())\n    if (body?.sortField) {\n        var sort = new PageQuerySort()\n        sort.setField(body.sortField)\n        sort.setDirection(body?.sortDirection || "DESC")\n        request.setSorts([sort])\n    }\n    // 返回当前业务分支的标准结果。\n    return metadataDataQueryService.queryPage(request)\n}\n\n// 参数或业务状态不满足要求时立即终止请求。\nexit 500, "不支持的远程表操作: " + action\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/19.远程表数据操作.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_import_snapshot_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_import_snapshot_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "20.手工导入元数据快照",\n  "createTime": 1784640000000,\n  "updateTime": 1787153759135,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/importSnapshot",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"dbId\\": \\"00b062694d774515a9155581aa20e06e\\",\\n  \\"dataSourceType\\": \\"mysql\\",\\n  \\"dryRun\\": true,\\n  \\"tables\\": [{\\"tableName\\": \\"police_case_info\\", \\"tableComment\\": \\"治安案件信息\\", \\"tableType\\": \\"数据表\\", \\"businessType\\": \\"业务表\\"}],\\n  \\"fieldMap\\": {\\"police_case_info\\": [{\\"columnName\\": \\"case_id\\", \\"columnComment\\": \\"案件标识\\", \\"columnType\\": \\"varchar\\", \\"columnLength\\": \\"64\\", \\"primaryKey\\": true, \\"nullable\\": false, \\"isTimestamp\\": false}, {\\"columnName\\": \\"update_time\\", \\"columnComment\\": \\"更新时间\\", \\"columnType\\": \\"datetime\\", \\"primaryKey\\": false, \\"nullable\\": true, \\"isTimestamp\\": true}]}\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "手工导入元数据快照（POST /dst/database/metadata/importSnapshot）。写入 db_table_t、db_table_column_t 和数据源表数量，不连接物理库；严格校验数据资源名称、表类型、业务类型、字段中文名、字段类型及必填布尔属性，并保存时间戳字段初始配置，使离线导入数据与自动探查数据共用第二步至第五步登记流程。传 dryRun=true 时只校验并返回表/字段数量，不写数据库；使用请求参数 tables、tableRows、fieldMap、dryRun。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：20.手工导入元数据快照\n// 路由：POST /dst/database/metadata/importSnapshot\n// 业务说明：手工导入元数据快照（POST /dst/database/metadata/importSnapshot）。写入 db_table_t、db_table_column_t 和数据源表数量，不连接物理库；严格校验数据资源名称、表类型、业务类型、字段中文名、字段类型及必填布尔属性，并保存时间戳字段初始配置，使离线导入数据与自动探查数据共用第二步至第五步登记流程。传 dryRun=true 时只校验并返回表/字段数量，不写数据库；使用请求参数 tables、tableRows、fieldMap、dryRun。\nimport tenantRuntime\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport log\nimport java.util.Map\nimport java.util.regex.Pattern\n\n/*\n * Metadata import 20: persist offline/manual metadata snapshot.\n * This endpoint never connects to the physical datasource. It writes imported tables to db_table_t\n * and imported columns to db_table_column_t so step 2-5 can reuse exactly the same registered\n * snapshot APIs as auto-explored datasources.\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar nowTime = () => new Date()\nvar rowValue = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) { return value }\n    }\n    return null\n}\nvar boolValue = (value, defaultValue) => {\n    if (value == null) { return defaultValue }\n    if (value == true || value == 1) { return true }\n    var text = lower(value)\n    if (text == \'true\' || text == \'1\' || text == \'yes\' || text == \'y\' || text == \'shi\' || text == \'是\') { return true }\n    if (text == \'false\' || text == \'0\' || text == \'no\' || text == \'n\' || text == \'fou\' || text == \'否\') { return false }\n    return defaultValue\n}\nvar intValue = (value, defaultValue) => {\n    if (blank(value)) { return defaultValue }\n    try { return value::int } catch (e) { return defaultValue }\n}\nvar longValue = (value, defaultValue) => {\n    if (blank(value)) { return defaultValue }\n    try { return value::long } catch (e) { return defaultValue }\n}\nvar normalizeType = (value, defaultValue) => {\n    var text = textOf(value)\n    if (blank(text)) { return defaultValue }\n    var low = lower(text)\n    if (low == \'view\' || low == \'视图\') { return \'视图\' }\n    if (low == \'dataset\' || low == \'resource\' || low == \'数据集\') { return \'数据集\' }\n    return text\n}\nvar normalizeBusinessType = (value) => {\n    var text = textOf(value)\n    if (blank(text)) { return \'业务表\' }\n    return text\n}\nvar allowedSourceTypes = [\n    \'mysql\', \'oracle\', \'oceanbasemysql\', \'oceanbaseoracle\', \'gaussdb\', \'gbase8a\',\n    \'sqlserver\', \'hive\', \'maxcompute\', \'vertica\', \'dameng\', \'postgresql\',\n    \'kingbase8\', \'minio\', \'ftp\', \'api\', \'kafka\', \'receive\'\n]\nvar allowedTableTypes = [\'数据表\', \'视图\', \'数据集\']\nvar allowedBusinessTypes = [\'业务表\', \'日志表\', \'字典表\', \'过程表\', \'备份表\']\nvar inOptions = (value, options) => {\n    var normalized = lower(value)\n    if (blank(normalized)) { return false }\n    for (option in options) {\n        if (lower(option) == normalized) { return true }\n    }\n    return false\n}\nvar hasChinese = (value) => {\n    if (blank(value)) { return false }\n    return Pattern.compile(\'[\\\\u4e00-\\\\u9fff]\').matcher(textOf(value)).find()\n}\nvar buildColumnType = (col) => {\n    var columnType = firstValue(col, [\'columnType\', \'typeName\', \'dataType\', \'fieldType\'])\n    var len = firstValue(col, [\'columnLength\', \'length\', \'columnSize\'])\n    if (blank(columnType)) { columnType = \'varchar\' }\n    if (!blank(len) && textOf(columnType).indexOf(\'(\') < 0) { return textOf(columnType) + \'(\' + textOf(len) + \')\' }\n    return textOf(columnType)\n}\nvar existingTableMap = (dbId) => {\n    var map = {}\n    var rows = db.table(\'db_table_t\').where().eq(\'datasource_id\', dbId).eq(\'is_del\', 0).select()\n    for (row in rows == null ? [] : rows) {\n        var name = firstValue(row, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\n        if (!blank(name)) { map[lower(name)] = row }\n    }\n    return map\n}\nvar columnsFor = (fieldMap, table) => {\n    var tableName = firstValue(table, [\'tableName\', \'tableNameEn\', \'name\'])\n    var fields = firstValue(table, [\'fields\', \'columns\', \'columnList\', \'tableColumns\'])\n    if (fields != null && fields instanceof java.util.List) { return fields }\n    if (fieldMap == null || blank(tableName)) { return [] }\n    var direct = fieldMap[tableName]\n    if (direct == null) { direct = fieldMap[lower(tableName)] }\n    return direct == null ? [] : direct\n}\nvar columnValues = (tableId, columnId, col, index, tenantId) => {\n    var columnName = firstValue(col, [\'columnName\', \'name\', \'fieldName\', \'column_name\'])\n    var dataType = firstValue(col, [\'dataType\', \'typeName\', \'fieldType\'])\n    var columnType = buildColumnType(col)\n    if (blank(dataType)) { dataType = columnType }\n    return {\n        tid: columnId,\n        table_id: tableId,\n        tenant_id: tenantId,\n        column_name: columnName,\n        column_comment: firstValue(col, [\'columnComment\', \'comment\', \'fieldComment\', \'column_comment\']),\n        data_type: dataType,\n        column_type: columnType,\n        length: longValue(firstValue(col, [\'columnLength\', \'length\', \'columnSize\']), null),\n        precision_length: intValue(firstValue(col, [\'precision\', \'precisionLength\']), null),\n        scale: intValue(firstValue(col, [\'scale\', \'decimalDigits\']), null),\n        nullable: boolValue(firstValue(col, [\'nullable\']), true) ? 1 : 0,\n        default_value: firstValue(col, [\'defaultValue\', \'default_value\']),\n        primary_key: boolValue(firstValue(col, [\'primaryKey\', \'pk\']), false) ? 1 : 0,\n        auto_increment: boolValue(firstValue(col, [\'autoIncrement\']), false) ? 1 : 0,\n        is_unique: boolValue(firstValue(col, [\'unique\', \'isUnique\']), false) ? 1 : 0,\n        indexed: boolValue(firstValue(col, [\'indexed\', \'index\']), false) ? 1 : 0,\n        ordinal_position: intValue(firstValue(col, [\'ordinalPosition\', \'serialNo\', \'sortNo\']), index + 1),\n        is_del: 0,\n        data_standard_id: firstValue(col, [\'dataStandardId\', \'standardField\']),\n        is_dict: boolValue(firstValue(col, [\'isDict\', \'dictionary\', \'enableCodeTable\']), false) ? 1 : 0,\n        dict_name: firstValue(col, [\'dictName\', \'dictionaryName\']),\n        updated_time: nowTime()\n    }\n}\nvar saveColumns = (tableId, columns, tenantId) => {\n    var oldRows = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableId).eq(\'is_del\', 0).select()\n    var oldMap = {}\n    for (old in oldRows == null ? [] : oldRows) {\n        oldMap[lower(firstValue(old, [\'columnName\', \'column_name\']))] = old\n    }\n    var count = 0\n    var index = 0\n    for (col in columns == null ? [] : columns) {\n        var columnName = firstValue(col, [\'columnName\', \'name\', \'fieldName\', \'column_name\'])\n        if (blank(columnName)) { continue }\n        var key = lower(columnName)\n        var old = oldMap[key]\n        var columnId = old == null ? newId() : firstValue(old, [\'tid\'])\n        var values = columnValues(tableId, columnId, col, index, tenantId)\n        if (old == null) {\n            values.created_time = nowTime()\n            db.table(\'db_table_column_t\').primary(\'tid\').insert(values)\n        } else {\n            db.table(\'db_table_column_t\').primary(\'tid\').update(values, true)\n            oldMap[key] = null\n        }\n        count = count + 1\n        index = index + 1\n    }\n    for (key in oldMap.keySet()) {\n        var old = oldMap[key]\n        if (old != null) {\n            db.table(\'db_table_column_t\').primary(\'tid\').update({ tid: firstValue(old, [\'tid\']), is_del: 1, updated_time: nowTime() }, true)\n        }\n    }\n    return count\n}\nvar saveEs = (tableId, doc) => {\n    try {\n        esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(doc), false)\n    } catch (e) {\n        log.warn(\'sync imported table ES failed, tid: {}, error: {}\', tableId, e.message)\n    }\n}\n\nif (body == null) { exit 400, \'request body cannot be empty\' }\nvar dbId = firstValue(body, [\'dbId\', \'datasourceId\', \'tid\'])\nif (blank(dbId)) { exit 400, \'dbId cannot be empty\' }\nvar datasource = db.table(\'db_datasource_t\').where().eq(\'tid\', dbId).eq(\'is_del\', 0).selectOne()\nif (datasource == null) { exit 404, \'datasource not found\' }\n// 租户只能来自已认证请求的上下文，禁止由导入载荷或数据源记录决定。\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) { exit 401, \'当前登录租户无效，请重新登录后再导入元数据\' }\nvar sourceType = firstValue(body, [\'dataSourceType\', \'dbType\'])\nif (blank(sourceType)) { sourceType = firstValue(datasource, [\'dbType\', \'db_type\']) }\nvar tables = body.tables == null ? (body.tableRows == null ? [] : body.tableRows) : body.tables\nvar fieldMap = body.fieldMap == null ? {} : body.fieldMap\nif ((tables == null || tables.size() == 0) && fieldMap != null) {\n    tables = []\n    for (name in fieldMap.keySet()) {\n        tables.add({ tableName: name, tableComment: name, businessType: \'业务表\' })\n    }\n}\nif (tables == null || tables.size() == 0) { exit 400, \'imported table list cannot be empty\' }\n\n// 在写库前进行后端强校验，避免绕过 Excel 下拉和前端校验写入不完整元数据。\nif (!inOptions(sourceType, allowedSourceTypes)) {\n    exit 400, \'不支持的数据源类型: \' + textOf(sourceType)\n}\nvar validationErrors = []\nvar seenTables = {}\nfor (table in tables) {\n    var tableName = firstValue(table, [\'tableName\', \'tableNameEn\', \'name\'])\n    var comment = firstValue(table, [\'tableComment\', \'tableNameCn\', \'comment\'])\n    var tableType = firstValue(table, [\'tableType\', \'type\', \'tableKind\'])\n    var businessType = firstValue(table, [\'businessType\'])\n    if (blank(tableName)) { validationErrors.add(\'数据表名不能为空\') }\n    if (blank(comment)) {\n        validationErrors.add(\'数据表\' + (blank(tableName) ? \'\' : \'[\' + tableName + \']\') + \'的数据资源名称不能为空\')\n    } else if (!hasChinese(comment)) {\n        validationErrors.add(\'数据表[\' + tableName + \']的数据资源名称必须包含中文\')\n    } else if (!blank(tableName) && lower(comment) == lower(tableName)) {\n        validationErrors.add(\'数据表[\' + tableName + \']的数据资源名称不能直接使用英文表名\')\n    }\n    if (!inOptions(tableType, allowedTableTypes)) {\n        validationErrors.add(\'数据表[\' + tableName + \']的表类型无效\')\n    }\n    if (!inOptions(businessType, allowedBusinessTypes)) {\n        validationErrors.add(\'数据表[\' + tableName + \']的业务类型无效\')\n    }\n    var tableKey = lower(tableName)\n    if (!blank(tableKey)) {\n        if (seenTables[tableKey] != null) {\n            validationErrors.add(\'数据表名重复: \' + tableName)\n        } else {\n            seenTables[tableKey] = true\n        }\n    }\n    var columns = columnsFor(fieldMap, table)\n    if (columns == null || columns.size() == 0) {\n        validationErrors.add(\'数据表[\' + tableName + \']至少需要一个数据项\')\n    } else {\n        var seenColumns = {}\n        var timestampCount = 0\n        for (col in columns) {\n            var columnName = firstValue(col, [\'columnName\', \'name\', \'fieldName\', \'column_name\'])\n            var columnComment = firstValue(col, [\'columnComment\', \'comment\', \'fieldComment\', \'column_comment\'])\n            var columnType = firstValue(col, [\'columnType\', \'typeName\', \'dataType\', \'fieldType\'])\n            var primaryKeyValue = rowValue(col, [\'primaryKey\', \'pk\'])\n            var nullableValue = rowValue(col, [\'nullable\'])\n            var timestampValue = rowValue(col, [\'isTimestamp\', \'isTimestampField\'])\n            if (blank(columnName)) { validationErrors.add(\'数据表[\' + tableName + \']存在字段英文名为空的数据项\') }\n            if (blank(columnComment)) {\n                validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的字段中文名不能为空\')\n            } else if (!hasChinese(columnComment)) {\n                validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的字段中文名必须包含中文\')\n            }\n            if (blank(columnType)) { validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的字段类型不能为空\') }\n            if (primaryKeyValue == null) { validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的是否主键不能为空\') }\n            if (nullableValue == null) { validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的是否可空不能为空\') }\n            if (timestampValue == null) { validationErrors.add(\'字段[\' + tableName + \'.\' + columnName + \']的是否时间戳字段不能为空\') }\n            var columnKey = lower(columnName)\n            if (!blank(columnKey)) {\n                if (seenColumns[columnKey] != null) {\n                    validationErrors.add(\'数据表[\' + tableName + \']字段名重复: \' + columnName)\n                } else {\n                    seenColumns[columnKey] = true\n                }\n            }\n            if (boolValue(timestampValue, false)) { timestampCount = timestampCount + 1 }\n        }\n        if (timestampCount > 1) {\n            validationErrors.add(\'数据表[\' + tableName + \']只能设置一个时间戳字段\')\n        }\n    }\n}\nif (validationErrors.size() > 0) {\n    var shownErrors = []\n    var maxErrors = validationErrors.size() > 8 ? 8 : validationErrors.size()\n    var errorIndex = 0\n    for (errorItem in validationErrors) {\n        if (errorIndex < maxErrors) { shownErrors.add(errorItem) }\n        errorIndex = errorIndex + 1\n    }\n    var suffix = validationErrors.size() > maxErrors ? \'；另有\' + (validationErrors.size() - maxErrors) + \'项错误\' : \'\'\n    exit 400, shownErrors.join(\'；\') + suffix\n}\n\n// 安全校验模式供 Magic 编辑器和回归测试使用：通过完整规则校验后立即返回，不产生资产数据。\nvar dryRun = boolValue(body.dryRun, false)\nif (dryRun) {\n    var validatedFieldCount = 0\n    for (table in tables) {\n        var validatedColumns = columnsFor(fieldMap, table)\n        validatedFieldCount = validatedFieldCount + (validatedColumns == null ? 0 : validatedColumns.size())\n    }\n    return {\n        dryRun: true,\n        validated: true,\n        dbId: dbId,\n        dataSourceType: sourceType,\n        tableCount: tables.size(),\n        fieldCount: validatedFieldCount\n    }\n}\n\nvar existingMap = existingTableMap(dbId)\nvar rows = []\nvar importedFieldCount = 0\nfor (table in tables) {\n    var tableName = firstValue(table, [\'tableName\', \'tableNameEn\', \'name\'])\n    if (blank(tableName)) { continue }\n    var key = lower(tableName)\n    var existing = existingMap[key]\n    var tableId = existing == null ? newId() : firstValue(existing, [\'tid\'])\n    var columns = columnsFor(fieldMap, table)\n    var fieldCount = columns == null ? 0 : columns.size()\n    var comment = firstValue(table, [\'tableComment\', \'tableNameCn\', \'comment\'])\n    if (blank(comment)) { comment = tableName }\n    var tableType = normalizeType(firstValue(table, [\'tableType\', \'type\', \'tableKind\']), \'数据表\')\n    var existingAnnotated = existing == null ? null : firstValue(existing, [\'annotated\'])\n    var explicitAnnotated = rowValue(table, [\'annotated\'])\n    var annotatedValue = explicitAnnotated == null ? (existingAnnotated == null ? 0 : existingAnnotated) : (boolValue(explicitAnnotated, false) ? 1 : 0)\n    var businessType = normalizeBusinessType(firstValue(table, [\'businessType\']))\n    var timestampField = \'\'\n    var governanceFields = []\n    for (governanceColumn in columns) {\n        var governanceColumnName = firstValue(governanceColumn, [\'columnName\', \'name\', \'fieldName\', \'column_name\'])\n        var governanceTimestamp = boolValue(firstValue(governanceColumn, [\'isTimestamp\', \'isTimestampField\']), false)\n        if (governanceTimestamp) { timestampField = governanceColumnName }\n        governanceFields.add({\n            columnName: governanceColumnName,\n            columnComment: firstValue(governanceColumn, [\'columnComment\', \'comment\', \'fieldComment\', \'column_comment\']),\n            standardField: \'\',\n            dictionaryRole: \'\',\n            dictionaryCategoryCode: tableName,\n            dictionaryCategoryName: \'\',\n            dictionaryCategoryValue: \'\',\n            isTimestampField: governanceTimestamp,\n            dictionaryRelation: null\n        })\n    }\n    var governanceConfig = {\n        version: 2,\n        tableName: tableName,\n        tableComment: comment,\n        businessType: businessType,\n        dictionaryStructureType: \'single\',\n        timestampField: timestampField,\n        dictionaryProfile: null,\n        dictionaryProfiles: [],\n        fields: governanceFields\n    }\n    var values = {\n        tid: tableId,\n        datasource_id: dbId,\n        table_name: tableName,\n        table_name_en: tableName,\n        table_name_cn: comment,\n        table_comment: comment,\n        table_type: tableType,\n        business_type: businessType,\n        business_type_reason: firstValue(table, [\'businessTypeReason\']) == null ? \'离线模板导入\' : firstValue(table, [\'businessTypeReason\']),\n        timestamp_field: timestampField,\n        field_governance_config: jsons.toJSONStr(governanceConfig),\n        annotated: annotatedValue,\n        record_count: longValue(firstValue(table, [\'recordCount\', \'rowCount\']), 0),\n        field_count: fieldCount,\n        storage_size: firstValue(table, [\'storageSize\', \'totalSizeFormatted\']) == null ? \'0 B\' : firstValue(table, [\'storageSize\', \'totalSizeFormatted\']),\n        total_size_formatted: firstValue(table, [\'totalSizeFormatted\', \'storageSize\']) == null ? \'0 B\' : firstValue(table, [\'totalSizeFormatted\', \'storageSize\']),\n        total_size_bytes: longValue(firstValue(table, [\'totalSizeBytes\', \'totalSizeBytes_num\']), 0),\n        org_id: firstValue(table, [\'orgId\']) == null ? firstValue(datasource, [\'orgId\', \'org_id\']) : firstValue(table, [\'orgId\']),\n        org_path: firstValue(table, [\'orgPath\']),\n        data_source_type: sourceType,\n        source_table_id: tableId,\n        source_table_name: tableName,\n        manage_unit: firstValue(datasource, [\'orgId\', \'org_id\']),\n        asset_desc: comment,\n        tenant_id: tenantId,\n        asset_status: 2,\n        flow_status: 2,\n        flow_order_id: null,\n        is_del: 0,\n        updated_time: nowTime()\n    }\n    if (existing == null) {\n        values.created_time = nowTime()\n        values.reg_time = nowTime()\n        db.table(\'db_table_t\').primary(\'tid\').insert(values)\n    } else {\n        db.table(\'db_table_t\').primary(\'tid\').update(values, true)\n    }\n    fieldCount = saveColumns(tableId, columns, tenantId)\n    importedFieldCount = importedFieldCount + fieldCount\n    if (fieldCount != values.field_count) {\n        values.field_count = fieldCount\n        db.table(\'db_table_t\').primary(\'tid\').update({ tid: tableId, field_count: fieldCount, updated_time: nowTime() }, true)\n    }\n    var output = {\n        tid: tableId,\n        id: tableId,\n        assetType: \'table\',\n        datasourceId: dbId,\n        dbId: dbId,\n        tableName: tableName,\n        tableNameEn: tableName,\n        tableNameCn: comment,\n        tableComment: comment,\n        tableType: tableType,\n        businessType: businessType,\n        businessTypeReason: values.business_type_reason,\n        recordCount: values.record_count,\n        fieldCount: fieldCount,\n        storageSize: values.storage_size,\n        totalSizeBytes: values.total_size_bytes,\n        annotated: annotatedValue,\n        metadataSource: \'template\',\n        action: existing == null ? \'create\' : \'update\'\n    }\n    saveEs(tableId, output)\n    rows.add(output)\n}\nvar activeTableCount = db.table(\'db_table_t\').where().eq(\'datasource_id\', dbId).eq(\'is_del\', 0).select().size()\ndb.table(\'db_datasource_t\').primary(\'tid\').update({ tid: dbId, table_num: activeTableCount, updated_time: nowTime() }, true)\nreturn {\n    dbId: dbId,\n    importedTableCount: rows.size(),\n    importedFieldCount: importedFieldCount,\n    tableCount: activeTableCount,\n    rows: rows\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/20.手工导入元数据快照.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_structured_columns_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_structured_columns_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "21.结构化来源字段",\n  "createTime": 1785686400000,\n  "updateTime": 1788342975992,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/structuredColumns",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"dbId\\": \\"数据源ID\\",\\n  \\"tableName\\": \\"探查得到的数据集名称\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取 API、FTP/SFTP、Kafka 数据源配置，并返回选定数据集的标准字段元数据；使用请求参数 dbId、tableName；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：21.结构化来源字段\n// 路由：POST /dst/database/metadata/structuredColumns\n// 业务说明：读取 API、FTP/SFTP、Kafka 数据源配置，并返回选定数据集的标准字段元数据；使用请求参数 dbId、tableName；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport tenantRuntime\nimport java.util.Map\nimport com.linewell.dataelement.metautil.structured.StructuredSourceProbeService as structuredSourceProbeService\n\n/*\n * 元数据管理 21：读取结构化来源字段。\n *\n * 正常的 API、文件、消息等结构化来源仍通过 StructuredSourceProbeService 实时探查；\n * 数据上报方式没有物理连接，改从导入模板已保存的 db_table_t / db_table_column_t\n * 快照读取字段。接口全程只读，不写 MySQL、ES 或物理数据源。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            return value\n        }\n    }\n    return null\n}\nvar falseLike = (value) => {\n    var normalized = lower(value)\n    return normalized == \'0\' || normalized == \'false\' || normalized == \'no\' || normalized == \'off\'\n}\nvar loadSource = (datasourceId, tenantId) => {\n    var row = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (row == null) {\n        return null\n    }\n    var result = {\n        tid: rowValue(row, [\'tid\']),\n        dbType: rowValue(row, [\'dbType\', \'db_type\']),\n        dbName: rowValue(row, [\'dbName\', \'db_name\']),\n        username: rowValue(row, [\'username\']),\n        password: rowValue(row, [\'password\']),\n        showConnect: rowValue(row, [\'showConnect\', \'show_connect\']),\n        accessMode: rowValue(row, [\'accessMode\', \'access_mode\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(row, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) {\n        result.putAll(connectionConfig)\n    }\n    result.dbType = rowValue(row, [\'dbType\', \'db_type\'])\n    result.showConnect = rowValue(row, [\'showConnect\', \'show_connect\'])\n    return result\n}\nvar snapshotColumns = (datasourceId, tableName, tenantId) => {\n    var table = db.table(\'db_table_t\').where()\n        .eq(\'datasource_id\', datasourceId).eq(\'table_name\', tableName)\n        .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (table == null) {\n        return []\n    }\n    return db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', rowValue(table, [\'tid\'])).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n        .orderBy(\'ordinal_position\', \'asc\').select()\n}\nvar isDataUploadSource = (source) => {\n    var accessMode = lower(firstValue(source, [\'accessMode\', \'access_mode\']))\n    return accessMode == \'upload\' || accessMode == \'data-upload\' || falseLike(firstValue(source, [\'showConnect\', \'show_connect\']))\n}\nvar hasProbeEndpoint = (source) => !blank(firstValue(source, [\n    \'url\', \'apiUrl\', \'apiBaseUrl\', \'baseUrl\', \'endpoint\', \'host\', \'jdbcURL\', \'jdbcUrl\', \'jdbc_url\',\n    \'ftpHost\', \'nodes\', \'bootstrapServers\', \'kafkaBootstrapServers\'\n]))\n\nvar dbId = body == null ? null : body.dbId\nvar tableName = body == null ? null : body.tableName\nif (blank(dbId) || blank(tableName)) {\n    exit 400, \'dbId 和 tableName 不能为空\'\n}\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'租户会话已失效，请重新登录\'\n}\nvar source = loadSource(dbId, tenantId)\nif (source == null) {\n    exit 404, \'数据源不存在\'\n}\n\n// 数据上报没有探查连接；缺少探查地址时同样安全降级为已登记快照，避免调用服务时报 URL 为空。\nif (isDataUploadSource(source) || !hasProbeEndpoint(source)) {\n    return snapshotColumns(dbId, textOf(tableName), tenantId)\n}\nreturn structuredSourceProbeService.getColumns(source, textOf(tableName))\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/21.结构化来源字段.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('metadata_structured_sample_01',NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_structured_sample_01",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "22.结构化来源样例数据",\n  "createTime": 1785686400000,\n  "updateTime": 1788343414621,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/structuredSampleData",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"dbId\\": \\"数据源ID\\",\\n  \\"tableName\\": \\"探查得到的数据集名称\\",\\n  \\"sampleSize\\": 10\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取 API、FTP/SFTP、Kafka 数据源配置，并返回选定数据集的标准样例行；使用请求参数 dbId、tableName、sampleSize；涉及 db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：22.结构化来源样例数据\n// 路由：POST /dst/database/metadata/structuredSampleData\n// 业务说明：读取 API、FTP/SFTP、Kafka 数据源配置，并返回选定数据集的标准样例行；使用请求参数 dbId、tableName、sampleSize；涉及 db_datasource_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport tenantRuntime\nimport java.util.Map\nimport com.linewell.dataelement.metautil.structured.StructuredSourceProbeService as structuredSourceProbeService\n\n/*\n * 元数据管理 22：读取结构化来源样例数据。\n *\n * 正常可连接来源继续实时读取样例数据；数据上报方式无探查连接，实际业务数据\n * 尚未在登记阶段推送，安全返回空样例而不伪造数据或调用带空 URL 的探查服务。\n * 接口全程只读，不写 MySQL、ES 或物理数据源。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            return value\n        }\n    }\n    return null\n}\nvar falseLike = (value) => {\n    var normalized = lower(value)\n    return normalized == \'0\' || normalized == \'false\' || normalized == \'no\' || normalized == \'off\'\n}\nvar loadSource = (datasourceId, tenantId) => {\n    var row = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (row == null) {\n        return null\n    }\n    var result = {\n        tid: rowValue(row, [\'tid\']),\n        dbType: rowValue(row, [\'dbType\', \'db_type\']),\n        dbName: rowValue(row, [\'dbName\', \'db_name\']),\n        username: rowValue(row, [\'username\']),\n        password: rowValue(row, [\'password\']),\n        showConnect: rowValue(row, [\'showConnect\', \'show_connect\']),\n        accessMode: rowValue(row, [\'accessMode\', \'access_mode\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(row, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) {\n        result.putAll(connectionConfig)\n    }\n    result.dbType = rowValue(row, [\'dbType\', \'db_type\'])\n    result.showConnect = rowValue(row, [\'showConnect\', \'show_connect\'])\n    return result\n}\nvar isDataUploadSource = (source) => {\n    var accessMode = lower(firstValue(source, [\'accessMode\', \'access_mode\']))\n    return accessMode == \'upload\' || accessMode == \'data-upload\' || falseLike(firstValue(source, [\'showConnect\', \'show_connect\']))\n}\nvar hasProbeEndpoint = (source) => !blank(firstValue(source, [\n    \'url\', \'apiUrl\', \'apiBaseUrl\', \'baseUrl\', \'endpoint\', \'host\', \'jdbcURL\', \'jdbcUrl\', \'jdbc_url\',\n    \'ftpHost\', \'nodes\', \'bootstrapServers\', \'kafkaBootstrapServers\'\n]))\n\nvar dbId = body == null ? null : body.dbId\nvar tableName = body == null ? null : body.tableName\nif (blank(dbId) || blank(tableName)) {\n    exit 400, \'dbId 和 tableName 不能为空\'\n}\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'租户会话已失效，请重新登录\'\n}\nvar source = loadSource(dbId, tenantId)\nif (source == null) {\n    exit 404, \'数据源不存在\'\n}\n\n// 数据上报的登记模板只提供表结构；实际行数据待完成审查后推送，预览显示为空即可。\nif (isDataUploadSource(source) || !hasProbeEndpoint(source)) {\n    return []\n}\nreturn structuredSourceProbeService.sampleData(source, textOf(tableName), body.sampleSize)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/22.结构化来源样例数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('mrs_hive_jdbc_debug_23',NULL,NULL,'{\n  "properties": {},\n  "id": "mrs_hive_jdbc_debug_23",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "23.华为MRSHive元数据网关",\n  "createTime": 1788220800000,\n  "updateTime": 1788699901492,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/huaweiMrsHiveJdbcDebug",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"action\\": \\"jdbcExample\\",\\n  \\"database\\": \\"Hive 数据库（tables/columns 等动作需要）\\",\\n  \\"table\\": \\"Hive 表名（表级动作需要）\\",\\n  \\"limit\\": 100,\\n  \\"confirm\\": \\"EXECUTE_JDBC_EXAMPLE\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 400,\\n    \\"msg\\": \\"执行 JDBC 示例需要 confirm=EXECUTE_JDBC_EXAMPLE 才会执行\\",\\n    \\"message\\": \\"执行 JDBC 示例需要 confirm=EXECUTE_JDBC_EXAMPLE 才会执行\\",\\n    \\"success\\": false,\\n    \\"data\\": null,\\n    \\"timestamp\\": 1788699858978,\\n    \\"error\\": {\\n        \\"code\\": \\"MAGIC-BUSINESS-400\\",\\n        \\"message\\": \\"执行 JDBC 示例需要 confirm=EXECUTE_JDBC_EXAMPLE 才会执行\\",\\n        \\"detail\\": \\"执行 JDBC 示例需要 confirm=EXECUTE_JDBC_EXAMPLE 才会执行\\",\\n        \\"traceId\\": \\"4EFDAA27E9AE4077\\",\\n        \\"type\\": \\"BusinessException\\",\\n        \\"method\\": \\"POST\\",\\n        \\"path\\": \\"/dst/database/metadata/huaweiMrsHiveJdbcDebug\\"\\n    }\\n}",\n  "description": "华为 MRS Hive 统一元数据网关（POST /dst/database/metadata/huaweiMrsHiveJdbcDebug）。登记五步和 NiFi 可使用同一套动作完成连通性、库表字段、建表 DDL、抽样、统计与只读查询。接口只使用服务端 hwhive 连接池；不接受任意写入 SQL。建表、加字段、删表及 JDBC 示例必须携带明确确认值。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "400",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "不支持的 action：health | databases | tables | columns | tableDetail | ddl | sample | count | query | createTable | addColumns | dropTable | jdbcExample",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "message",\n        "value": "不支持的 action：health | databases | tables | columns | tableDetail | ddl | sample | count | query | createTable | addColumns | dropTable | jdbcExample",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "timestamp",\n        "value": "1788697654787",\n        "description": "",\n        "required": false,\n        "dataType": "Long",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "error",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "code",\n            "value": "MAGIC-BUSINESS-400",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "message",\n            "value": "不支持的 action：health | databases | tables | columns | tableDetail | ddl | sample | count | query | createTable | addColumns | dropTable | jdbcExample",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "detail",\n            "value": "不支持的 action：health | databases | tables | columns | tableDetail | ddl | sample | count | query | createTable | addColumns | dropTable | jdbcExample",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "traceId",\n            "value": "6C18B0B4D2A24604",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "type",\n            "value": "BusinessException",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "method",\n            "value": "POST",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "path",\n            "value": "/dst/database/metadata/huaweiMrsHiveJdbcDebug",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：23.华为MRSHive元数据网关\n// 路由：POST /dst/database/metadata/huaweiMrsHiveJdbcDebug\n// 业务说明：华为 MRS Hive 统一元数据网关（POST /dst/database/metadata/huaweiMrsHiveJdbcDebug）。登记五步和 NiFi 可使用同一套动作完成连通性、库表字段、建表 DDL、抽样、统计与只读查询。接口只使用服务端 hwhive 连接池；不接受任意写入 SQL。建表、加字段、删表及 JDBC 示例必须携带明确确认值。\nimport hwhive\nimport tenantRuntime\nimport java.util.Map\n\n/*\n * 元数据管理 23：华为 MRS Hive 统一元数据网关。\n *\n * 登记五步需要的动作：\n *   health、databases、tables、columns、tableDetail、ddl、sample、count、createTable、addColumns\n * NiFi 建模需要的动作：\n *   health、databases、tables、columns、tableDetail、sample、count、query\n *\n * hwhive 是服务端 MRS Hive 连接池模块，连接参数、Kerberos 配置与 keytab 均只从后端部署节点读取。\n * 本接口不接收 JDBC URL、账号、密码、keytab、Kerberos 配置路径，也不暴露任意 DDL/DML 直通执行。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'当前登录状态已失效，请重新登录后访问华为 MRS Hive 元数据\'\n}\nif (body == null) {\n    exit 400, \'请求体不能为空\'\n}\n\nvar action = blank(body.action) ? \'health\' : textOf(body.action).trim()\nvar allowedActions = [\n    \'health\', \'databases\', \'tables\', \'columns\', \'tableDetail\', \'ddl\', \'sample\', \'count\', \'query\',\n    \'createTable\', \'addColumns\', \'dropTable\', \'jdbcExample\'\n]\nif (allowedActions.indexOf(action) < 0) {\n    exit 400, \'不支持的 action：\' + action\n}\n\nvar identifier = (value, label) => {\n    var normalized = textOf(value).trim()\n    if (!normalized.matches(\'[A-Za-z_][A-Za-z0-9_]*\')) {\n        exit 400, label + \'只能包含字母、数字和下划线，且必须以字母或下划线开头\'\n    }\n    return normalized\n}\nvar quoted = (value, label) => \'`\' + identifier(value, label) + \'`\'\nvar databaseOf = () => identifier(body.database, \'database\')\nvar tableOf = () => identifier(body.table, \'table\')\nvar qualifiedTable = () => quoted(databaseOf(), \'database\') + \'.\' + quoted(tableOf(), \'table\')\nvar limitOf = (fallback, max) => {\n    var value = body.limit == null ? fallback : body.limit::int\n    if (value < 1) { return 1 }\n    return value > max ? max : value\n}\nvar escapeLiteral = (value) => textOf(value).replaceAll("\'", "\'\'")\nvar valuesOf = (rows) => {\n    var values = []\n    for (row in rows == null ? [] : rows) {\n        if (row instanceof Map && !row.isEmpty()) {\n            for (entry in row.entrySet()) {\n                values.add(entry.getValue())\n                break\n            }\n        }\n    }\n    return values\n}\nvar requireConfirm = (expected, label) => {\n    if (textOf(body.confirm).trim() != expected) {\n        exit 400, label + \'需要 confirm=\' + expected + \' 才会执行\'\n    }\n}\nvar requireReadSql = (sql) => {\n    var statement = textOf(sql).trim()\n    if (blank(statement) || statement.indexOf(\';\') >= 0) {\n        exit 400, \'只读查询必须是一条非空 SQL，且不能包含分号\'\n    }\n    var upper = statement.toUpperCase()\n    if (!(upper.startsWith(\'SELECT \') || upper.startsWith(\'WITH \') || upper.startsWith(\'SHOW \') || upper.startsWith(\'DESCRIBE \') || upper.startsWith(\'EXPLAIN \'))) {\n        exit 400, \'query 仅支持 SELECT、WITH、SHOW、DESCRIBE 或 EXPLAIN\'\n    }\n    var forbidden = [\'INSERT \', \'UPDATE \', \'DELETE \', \'MERGE \', \'CREATE \', \'ALTER \', \'DROP \', \'TRUNCATE \', \'GRANT \', \'REVOKE \', \'SET \', \'USE \']\n    for (keyword in forbidden) {\n        if (upper.indexOf(keyword) >= 0) {\n            exit 400, \'query 不能包含写操作关键字：\' + keyword.trim()\n        }\n    }\n    return statement\n}\nvar hiveType = (value) => {\n    var normalized = textOf(value).trim().toUpperCase().replaceAll(\'\\\\s+\', \' \')\n    if (blank(normalized) || normalized.indexOf(\';\') >= 0 || normalized.indexOf("\'") >= 0\n        || normalized.indexOf(\'"\') >= 0 || !normalized.matches(\'[A-Z][A-Z0-9_() ,<>]*\')) {\n        exit 400, \'字段类型不合法：\' + textOf(value)\n    }\n    return normalized\n}\nvar columnDefinitions = (columns, label) => {\n    if (columns == null || columns.size() == 0) {\n        exit 400, label + \'不能为空\'\n    }\n    var definitions = []\n    for (column in columns) {\n        var name = column instanceof Map ? column.get(\'name\') : column.name\n        var type = column instanceof Map ? column.get(\'type\') : column.type\n        var comment = column instanceof Map ? column.get(\'comment\') : column.comment\n        var definition = quoted(name, \'字段名\') + \' \' + hiveType(type)\n        if (!blank(comment)) {\n            definition = definition + " COMMENT \'" + escapeLiteral(comment) + "\'"\n        }\n        definitions.add(definition)\n    }\n    return definitions\n}\n\n// 连通性探测只从 hwhive 的服务端连接池取连接，close() 表示归还连接池。\nif (action == \'health\') {\n    var connection = null\n    try {\n        connection = hwhive.getConnection()\n        return { success: true, tenantId: tenantId, action: action, message: \'华为 MRS Hive 连接正常\' }\n    } finally {\n        if (connection != null) { connection.close() }\n    }\n}\n\nif (action == \'databases\') {\n    var rows = hwhive.queryTable(\'SHOW DATABASES\')\n    return { success: true, action: action, rows: rows, databases: valuesOf(rows) }\n}\n\nif (action == \'tables\') {\n    var database = databaseOf()\n    var rows = hwhive.queryTable(\'SHOW TABLES IN \' + quoted(database, \'database\'))\n    return { success: true, action: action, database: database, rows: rows, tables: valuesOf(rows) }\n}\n\nif (action == \'columns\') {\n    var database = databaseOf()\n    var table = tableOf()\n    return {\n        success: true,\n        action: action,\n        database: database,\n        table: table,\n        columns: hwhive.queryTable(\'DESCRIBE \' + qualifiedTable())\n    }\n}\n\nif (action == \'tableDetail\') {\n    var database = databaseOf()\n    var table = tableOf()\n    return {\n        success: true,\n        action: action,\n        database: database,\n        table: table,\n        details: hwhive.queryTable(\'DESCRIBE FORMATTED \' + qualifiedTable())\n    }\n}\n\nif (action == \'ddl\') {\n    var database = databaseOf()\n    var table = tableOf()\n    return {\n        success: true,\n        action: action,\n        database: database,\n        table: table,\n        ddl: hwhive.queryTable(\'SHOW CREATE TABLE \' + qualifiedTable())\n    }\n}\n\nif (action == \'sample\') {\n    var database = databaseOf()\n    var table = tableOf()\n    var limit = limitOf(100, 1000)\n    return {\n        success: true,\n        action: action,\n        database: database,\n        table: table,\n        limit: limit,\n        rows: hwhive.queryTable(\'SELECT * FROM \' + qualifiedTable() + \' LIMIT \' + limit)\n    }\n}\n\nif (action == \'count\') {\n    var database = databaseOf()\n    var table = tableOf()\n    return {\n        success: true,\n        action: action,\n        database: database,\n        table: table,\n        rows: hwhive.queryTable(\'SELECT COUNT(*) AS row_count FROM \' + qualifiedTable())\n    }\n}\n\nif (action == \'query\') {\n    var sql = requireReadSql(body.sql)\n    return { success: true, action: action, rows: hwhive.queryTable(sql) }\n}\n\nif (action == \'createTable\') {\n    var database = databaseOf()\n    var table = tableOf()\n    requireConfirm(\'CREATE_TABLE:\' + database + \'.\' + table, \'创建 Hive 表\')\n    var definitions = columnDefinitions(body.columns, \'columns\')\n    var ddl = \'CREATE TABLE IF NOT EXISTS \' + qualifiedTable() + \' (\' + definitions.join(\', \') + \')\'\n    if (body.partitionColumns != null && body.partitionColumns.size() > 0) {\n        ddl = ddl + \' PARTITIONED BY (\' + columnDefinitions(body.partitionColumns, \'partitionColumns\').join(\', \') + \')\'\n    }\n    var storedAs = blank(body.storedAs) ? \'\' : textOf(body.storedAs).trim().toUpperCase()\n    if (!blank(storedAs)) {\n        if ([\'ORC\', \'PARQUET\', \'TEXTFILE\', \'AVRO\'].indexOf(storedAs) < 0) {\n            exit 400, \'storedAs 仅支持 ORC、PARQUET、TEXTFILE 或 AVRO\'\n        }\n        ddl = ddl + \' STORED AS \' + storedAs\n    }\n    if (!blank(body.tableComment)) {\n        ddl = ddl + " COMMENT \'" + escapeLiteral(body.tableComment) + "\'"\n    }\n    hwhive.execDDLSql(ddl)\n    return { success: true, action: action, database: database, table: table, ddl: ddl }\n}\n\nif (action == \'addColumns\') {\n    var database = databaseOf()\n    var table = tableOf()\n    requireConfirm(\'ADD_COLUMNS:\' + database + \'.\' + table, \'为 Hive 表增加字段\')\n    var ddl = \'ALTER TABLE \' + qualifiedTable() + \' ADD COLUMNS (\' + columnDefinitions(body.columns, \'columns\').join(\', \') + \')\'\n    hwhive.execDDLSql(ddl)\n    return { success: true, action: action, database: database, table: table, ddl: ddl }\n}\n\nif (action == \'dropTable\') {\n    var database = databaseOf()\n    var table = tableOf()\n    requireConfirm(\'DROP_TABLE:\' + database + \'.\' + table, \'删除 Hive 表\')\n    var ddl = \'DROP TABLE IF EXISTS \' + qualifiedTable()\n    hwhive.execDDLSql(ddl)\n    return { success: true, action: action, database: database, table: table, ddl: ddl }\n}\n\n// 兼容图片中的 JDBC 最小验证流程。默认不会运行，且建表必须由调用方显式确认。\nif (action == \'jdbcExample\') {\n    requireConfirm(\'EXECUTE_JDBC_EXAMPLE\', \'执行 JDBC 示例\')\n    var connection = null\n    try {\n        connection = hwhive.getConnection()\n        hwhive.execDDLSql(\'CREATE TABLE IF NOT EXISTS employees_info(id INT,name STRING)\')\n        hwhive.execDMLSql(\'SELECT COUNT(*) FROM employees_info\')\n        return { success: true, action: action, message: \'JDBC 示例已执行；已按图片依次完成连接、建表和计数查询\' }\n    } finally {\n        if (connection != null) { connection.close() }\n    }\n}\n\nexit 400, \'未处理的 action：\' + action\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/23.华为MRSHive元数据网关.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "metadata_columns_collect_24",\n  "script": null,\n  "groupId": "6e30fb6d565c40b18d480b219e13b20e",\n  "name": "24.按需采集数据表字段快照",\n  "createTime": 1790386199138,\n  "updateTime": 1790388386216,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/collectColumns",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tableId\\":\\"数据表ID\\",\\"force\\":false,\\"dryRun\\":false}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "登记第三、四步按表采集/同步字段（POST /dst/database/metadata/collectColumns）。默认已有 db_table_column_t 快照直接返回；force=true 时重新探查当前物理表，按字段名保留已有 ID 和治理设置，更新结构、新增字段，并将来源已移除字段软删除。数据行预览由独立接口实时查询。 支持 dryRun=true 仅探查并返回字段差异，不写入；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：24.按需采集数据表字段快照\n// 路由：POST /dst/database/metadata/collectColumns\n// 业务说明：登记第三、四步按表采集/同步字段（POST /dst/database/metadata/collectColumns）。默认已有 db_table_column_t 快照直接返回；force=true 时重新探查当前物理表，按字段名保留已有 ID 和治理设置，更新结构、新增字段，并将来源已移除字段软删除。数据行预览由独立接口实时查询。 支持 dryRun=true 仅探查并返回字段差异，不写入；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。\nimport tenantRuntime\nimport hwhive\nimport com.linewell.dataelement.metautil.structured.StructuredSourceProbeService as structuredSourceProbeService\nimport metadataAsset\nimport cn.hutool.core.util.IdUtil\nimport java.util.Date\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport jsons\nimport java.util.Map\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\n\n/*\n * 元数据管理 24：登记第三、四步按当前表采集或同步字段。\n * 读取 db_table_t/db_datasource_t；有快照时默认只读 db_table_column_t。\n * 缺失快照或 force=true 时探查当前物理表，写入/更新字段快照；\n * dryRun=true 只返回差异，不修改 MySQL 或物理数据源。数据行预览由独立接口负责。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) { return value }\n    }\n    return null\n}\nvar databaseTypeOf = (code) => {\n    if (blank(code)) { return DatabaseType.MYSQL }\n    try {\n        return DatabaseType.fromCode(textOf(code).toLowerCase())\n    } catch (e) {\n        return DatabaseType.MYSQL\n    }\n}\nvar loadDatasource = (datasourceId) => {\n    if (blank(datasourceId)) { return null }\n    var row = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\n    if (row == null) { return null }\n    var result = {\n        tid: rowValue(row, [\'tid\']),\n        dbName: rowValue(row, [\'dbName\', \'db_name\']),\n        dbType: rowValue(row, [\'dbType\', \'db_type\']),\n        jdbcURL: rowValue(row, [\'jdbcUrl\', \'jdbc_url\']),\n        username: rowValue(row, [\'username\']),\n        password: rowValue(row, [\'password\'])\n    }\n    var connectionConfig = datasourceConnectionConfig(\'read\', rowValue(row, [\'tid\']), null, false)\n    if (connectionConfig != null && !connectionConfig.isEmpty()) { result.putAll(connectionConfig) }\n    if (!blank(rowValue(row, [\'dbType\', \'db_type\']))) { result.dbType = rowValue(row, [\'dbType\', \'db_type\']) }\n    if (rowValue(row, [\'jdbcUrl\', \'jdbc_url\']) != null) { result.jdbcURL = rowValue(row, [\'jdbcUrl\', \'jdbc_url\']) }\n    if (rowValue(row, [\'username\']) != null) { result.username = rowValue(row, [\'username\']) }\n    if (rowValue(row, [\'password\']) != null) { result.password = rowValue(row, [\'password\']) }\n    return result\n}\nvar dataSourceOf = (asset) => {\n    var dbType = databaseTypeOf(firstValue(asset, [\'dbType\', \'databaseType\', \'dataSourceType\']))\n    var typeCode = textOf(dbType.getCode()).toLowerCase()\n    var virtualResource = !dbType.isRelational()\n    var zookeeperQuorum = firstValue(asset, [\'zookeeperQuorum\', \'zkQuorum\'])\n    var hiveZooKeeperDiscovery = dbType == DatabaseType.HIVE && !blank(zookeeperQuorum)\n    var host = firstValue(asset, [\'host\', \'dbIp\', \'minioEndpoint\', \'apiUrl\', \'url\', \'nodes\', \'ftpHost\', \'hostname\', \'bootstrapServers\', \'kafkaBootstrapServers\', \'maxcomputeEndpoint\'])\n    var port = firstValue(asset, [\'port\', \'dbPort\', \'ftpPort\'])\n    var databaseName = firstValue(asset, [\'database\', \'dbName\', \'dbMetaDbName\', \'schema\', \'defaultSchema\', \'currentSchema\', \'maxcomputeProject\', \'minioBucket\', \'bucket\', \'topic\', \'kafkaTopic\', \'indexName\', \'apiName\', \'assetName\', \'name\'])\n    var username = firstValue(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\', \'maxcomputeAccessKeyId\', \'minioAccessKey\', \'ftpUsername\', \'apiUser\'])\n    var password = firstValue(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\', \'maxcomputeAccessKeySecret\', \'minioSecretKey\', \'ftpPassword\', \'apiToken\'])\n    if (!virtualResource && (blank(databaseName) || (!hiveZooKeeperDiscovery && (blank(host) || blank(username))))) {\n        exit 400, \'数据源连接参数不完整\'\n    }\n    var dsConfig = new DataSourceConfig()\n    dsConfig.setDatabaseType(dbType)\n    dsConfig.setHost(blank(host) ? (hiveZooKeeperDiscovery ? \'\' : \'virtual\') : textOf(host))\n    dsConfig.setPort(blank(port) ? dbType.getDefaultPort() : port::int)\n    dsConfig.setDatabase(blank(databaseName) ? typeCode + \'_resource\' : textOf(databaseName))\n    dsConfig.setUsername(blank(username) ? \'\' : textOf(username))\n    dsConfig.setPassword(blank(password) ? \'\' : textOf(password))\n    // Oracle SID and Service Name use different URL formats; reuse the tested JDBC URL.\n    dsConfig.setJdbcUrl(blank(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ? null : textOf(firstValue(asset, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])))\n    dsConfig.setSchema(blank(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])) ? null : textOf(firstValue(asset, [\'schema\', \'defaultSchema\', \'currentSchema\'])))\n    dsConfig.setAuthMode(firstValue(asset, [\'authMode\', \'auth\']))\n    dsConfig.setPrincipal(firstValue(asset, [\'principal\', \'hivePrincipal\', \'servicePrincipal\']))\n    dsConfig.setUserPrincipal(firstValue(asset, [\'userPrincipal\', \'clientPrincipal\', \'kerberosUserPrincipal\']))\n    dsConfig.setKeytabPath(firstValue(asset, [\'keytabPath\', \'keytab\', \'userKeytab\']))\n    dsConfig.setKrb5ConfPath(firstValue(asset, [\'krb5ConfPath\', \'krb5Conf\', \'krb5\']))\n    dsConfig.setJaasConfPath(firstValue(asset, [\'jaasConfPath\', \'jaasConfig\']))\n    dsConfig.setZookeeperQuorum(blank(zookeeperQuorum) ? null : textOf(zookeeperQuorum))\n    dsConfig.setZookeeperNamespace(firstValue(asset, [\'zookeeperNamespace\', \'zooKeeperNamespace\']))\n    dsConfig.setServiceDiscoveryMode(firstValue(asset, [\'serviceDiscoveryMode\', \'serviceDiscovery\']))\n    dsConfig.setSaslQop(firstValue(asset, [\'saslQop\', \'sasl.qop\']))\n    dsConfig.setClientConfigDir(firstValue(asset, [\'clientConfigDir\', \'mrsClientConfigDir\']))\n    dsConfig.setExtraParams(blank(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])) ? null : textOf(firstValue(asset, [\'extraParams\', \'connectParams\', \'jdbcParams\', \'maxcomputeEndpoint\'])))\n    dsConfig.setConnectionTimeout(30)\n    return dsConfig\n}\n\n/* 登记第三、四步按表按需采集字段。已有 db_table_column_t 快照时不接触来源库；预览数据另走实时接口。 */\nvar requestedTableId = body == null ? null : body.tableId\nif (blank(requestedTableId)) { exit 400, "tableId 不能为空" }\nvar tableAsset = db.table("db_table_t").where().eq("tid", requestedTableId).eq("is_del", 0).selectOne()\nif (tableAsset == null) { exit 404, "数据表不存在或无访问权限" }\nvar snapshot = db.table("db_table_column_t").where().eq("table_id", requestedTableId).eq("is_del", 0).select()\nvar force = body != null && (body.force == true || textOf(body.force) == \'true\')\nvar dryRun = body != null && (body.dryRun == true || textOf(body.dryRun) == \'true\')\nif (!force && !dryRun && snapshot != null && snapshot.size() > 0) { return snapshot }\nvar datasourceId = firstValue(tableAsset, ["datasourceId", "datasource_id"])\nvar physicalName = firstValue(tableAsset, ["tableName", "table_name"])\nif (blank(datasourceId) || blank(physicalName)) { exit 400, "数据表缺少来源数据源或物理表名" }\nvar datasource = loadDatasource(datasourceId)\nif (datasource == null) { exit 404, "数据源不存在或无访问权限" }\nvar sourceType = textOf(firstValue(datasource, ["dbType", "db_type"])).toLowerCase()\nvar structured = sourceType == "ftp" || sourceType == "api" || sourceType == "kafka"\nvar managedHive = sourceType == "hive" && (\n    textOf(firstValue(datasource, ["metadataAccessMode", "metadata_access_mode"])) == "server-managed-mrs"\n    || !blank(firstValue(datasource, ["hiveProfile", "hive_profile"]))\n)\nvar physicalColumns = []\nif (managedHive) {\n    var hiveDatabase = firstValue(datasource, ["database", "dbName", "db_name"])\n    if (blank(hiveDatabase) || !(hiveDatabase + "").matches("[A-Za-z_][A-Za-z0-9_]*")\n        || !(physicalName + "").matches("[A-Za-z_][A-Za-z0-9_]*")) {\n        exit 400, "Hive 库名或表名格式不正确"\n    }\n    var hiveRows = hwhive.queryTable("DESCRIBE `" + hiveDatabase + "`.`" + physicalName + "`")\n    for (hiveRow in hiveRows == null ? [] : hiveRows) {\n        var hiveName = firstValue(hiveRow, ["col_name", "COL_NAME", "colName", "column_name"])\n        if (blank(hiveName) || (hiveName + "").startsWith("#")) { continue }\n        var hiveType = firstValue(hiveRow, ["data_type", "DATA_TYPE", "dataType", "type"])\n        physicalColumns.add({ columnName: hiveName, columnComment: firstValue(hiveRow, ["comment", "COMMENT"]),\n            dataType: hiveType, columnType: hiveType, ordinalPosition: physicalColumns.size() + 1 })\n    }\n} else if (structured) {\n    physicalColumns = structuredSourceProbeService.getColumns(datasource, physicalName + "")\n} else {\n    physicalColumns = metadataExplorerService.getColumns(dataSourceOf(datasource), physicalName + "")\n}\nif (physicalColumns == null || physicalColumns.isEmpty()) { exit 422, "来源表未返回字段，请检查表名和访问权限" }\nvar now = new Date()\nvar rows = []\nfor (index, column in physicalColumns) {\n    if (blank(column.columnName)) { continue }\n    rows.add({\n        tid: IdUtil.getSnowflakeNextIdStr(), table_id: requestedTableId, tenant_id: tenantRuntime.id(),\n        column_name: column.columnName, column_comment: column.columnComment,\n        data_type: column.dataType, column_type: column.columnType,\n        length: column.length, precision_length: column.precision, scale: column.scale,\n        nullable: column.nullable, default_value: column.defaultValue,\n        primary_key: column.primaryKey, auto_increment: column.autoIncrement,\n        is_unique: column.unique, indexed: column.indexed,\n        ordinal_position: column.ordinalPosition == null ? index + 1 : column.ordinalPosition,\n        charset: column.charset, collation: column.collation, extra: column.extra,\n        is_del: 0, created_time: now, updated_time: now\n    })\n}\nif (rows.isEmpty()) { exit 422, "来源表字段名称为空" }\nvar previousByName = {}\nfor (previous in snapshot == null ? [] : snapshot) {\n    if (!blank(previous.columnName)) { previousByName[textOf(previous.columnName).toLowerCase()] = previous }\n}\nif (dryRun) {\n    var incoming = {}\n    var addedCount = 0\n    for (column in rows) {\n        var key = textOf(column.column_name).toLowerCase()\n        incoming[key] = true\n        if (previousByName[key] == null) { addedCount = addedCount + 1 }\n    }\n    var removedCount = 0\n    for (previous in snapshot == null ? [] : snapshot) {\n        if (!blank(previous.columnName) && incoming[textOf(previous.columnName).toLowerCase()] != true) { removedCount = removedCount + 1 }\n    }\n    return { dryRun: true, tableId: requestedTableId, sourceFieldCount: rows.size(),\n        snapshotFieldCount: snapshot == null ? 0 : snapshot.size(), added: addedCount, removed: removedCount }\n}\nvar retained = {}\nvar additions = []\nfor (row in rows) {\n    var key = textOf(row.column_name).toLowerCase()\n    var previous = previousByName[key]\n    if (previous == null) {\n        additions.add(row)\n        continue\n    }\n    retained[key] = true\n    db.table("db_table_column_t").where()\n        .eq("tid", previous.tid).eq("table_id", requestedTableId).eq("is_del", 0)\n        .update({\n            column_comment: row.column_comment, data_type: row.data_type, column_type: row.column_type,\n            length: row.length, precision_length: row.precision_length, scale: row.scale,\n            nullable: row.nullable, default_value: row.default_value,\n            auto_increment: row.auto_increment, is_unique: row.is_unique, indexed: row.indexed,\n            ordinal_position: row.ordinal_position, charset: row.charset,\n            collation: row.collation, extra: row.extra, updated_time: now\n        })\n}\nif (!additions.isEmpty()) { metadataAsset.batchInsertTableColumns(additions) }\n// Remove stale fields only after every current field has been updated or inserted.\nfor (previous in snapshot == null ? [] : snapshot) {\n    if (blank(previous.columnName) || retained[textOf(previous.columnName).toLowerCase()] == true) { continue }\n    db.table("db_table_column_t").where()\n        .eq("tid", previous.tid).eq("table_id", requestedTableId).eq("is_del", 0)\n        .update({ is_del: 1, updated_time: now })\n}\ndb.table("db_table_t").where().eq("tid", requestedTableId).eq("is_del", 0)\n    .update({ field_count: rows.size(), updated_time: now })\nreturn db.table("db_table_column_t").where().eq("table_id", requestedTableId).eq("is_del", 0).select()\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/24.按需采集数据表字段快照.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6e30fb6d565c40b18d480b219e13b20e',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "6e30fb6d565c40b18d480b219e13b20e",\r\n  "name" : "01.元数据管理",\r\n  "type" : "api",\r\n  "parentId" : "datapd_database_group_01",\r\n  "path" : "/metadata",\r\n  "paths" : [ ],\r\n  "options" : [ ],\r\n  "updateTime" : 1784437771888\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.元数据管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_database_page_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_database_page_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "01.数据源分页查询",\n  "createTime": null,\n  "updateTime": 1790467385060,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"conditions\\": [\\n    {\\"field\\": \\"assetType\\", \\"type\\": \\"match\\", \\"value\\": \\"db\\"},\\n    {\\"field\\": \\"dbType\\", \\"type\\": \\"match\\", \\"value\\": \\"mysql\\"},\\n    {\\"field\\": \\"registrationState\\", \\"type\\": \\"match\\", \\"value\\": \\"pending\\"}\\n  ],\\n  \\"sortField\\": \\"updatedTime\\",\\n  \\"sortDir\\": \\"desc\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"total\\":0,\\"list\\":[]}",\n  "description": "数据源分页查询（POST /dst/database/page）。Elasticsearch 负责关键字和组合筛选，控制库 db_datasource_t 是数据源资产存在性、租户边界与状态的事实来源；每次结果采用一次批量回查校验，过滤 ES 中残留的失效投影；使用请求参数 includeMetadataCounts、pageNum、pageSize、conditions、sortField、sortDir。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.数据源分页查询\n// 路由：POST /dst/database/page\n// 业务说明：数据源分页查询（POST /dst/database/page）。Elasticsearch 负责关键字和组合筛选，控制库 db_datasource_t 是数据源资产存在性、租户边界与状态的事实来源；每次结果采用一次批量回查校验，过滤 ES 中残留的失效投影；使用请求参数 includeMetadataCounts、pageNum、pageSize、conditions、sortField、sortDir。\nimport tenantEs\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nimport \'@/common/configData\' as configData\nimport log\nimport dataScope\n\n/*\n * 数据源分页查询。\n * 数据读取：Elasticsearch dataassets 索引负责检索，db_datasource_t 负责资产准入校验。\n * 数据写入：无。\n * 核心逻辑：一次 ES 检索后批量回查当前租户的有效数据源，避免 ES 残留投影进入登记流程。\n */\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\n\n\n/*\n * Optional governance summary: one grouped query over persisted snapshots for\n * the already-authorized page only. No external connection or per-source reads.\n */\nvar withMetadataCounts = rows => {\n    if (body?.includeMetadataCounts != true || rows.size() == 0) { return rows }\n    var quotedIds = []\n    for (row in rows) { quotedIds.add("\'" + text(row.tid).replace("\'", "\'\'") + "\'") }\n    var counts = db.select("""\n        select t.datasource_id as sourceId,\n               count(distinct t.tid) as collectedTableCount,\n               count(c.tid) as collectedFieldCount\n          from db_table_t t\n          left join db_table_column_t c\n            on c.table_id = t.tid and c.tenant_id = #{tenantId} and ifnull(c.is_del, 0) = 0\n         where t.tenant_id = #{tenantId} and ifnull(t.is_del, 0) = 0\n           and t.datasource_id in (${quotedIds.join(\',\')})\n         group by t.datasource_id\n    """)\n    var bySource = {}\n    for (count in counts) { bySource[text(count.sourceid)] = count }\n    for (row in rows) {\n        var count = bySource[text(row.tid)]\n        row.collectedTableCount = count == null ? 0 : count.collectedtablecount\n        row.fieldCount = count == null ? 0 : count.collectedfieldcount\n    }\n    return rows\n}\n\nvar addCondition = (must, mustNot, condition) => {\n    if (condition == null || blank(condition.value)) {\n        return\n    }\n    var field = condition.field\n    var value = condition.value\n    var type = blank(condition.type) ? \'match\' : condition.type\n\n    // 登记状态在回表后以 db_datasource_t.asset_status 为准，避免索引延迟误判。\n    if (field == \'registrationState\') {\n        return\n    } else if (field == \'keyword\') {\n        must.add({\n            bool: {\n                should: [\n                    { wildcard: { dbName: \'*\' + value + \'*\' } },\n                    { wildcard: { appName: \'*\' + value + \'*\' } },\n                    { wildcard: { database: \'*\' + value + \'*\' } }\n                ],\n                minimum_should_match: 1\n            }\n        })\n    } else if (type == \'in\') {\n        if (value == null || value.size() == 0) {\n            return\n        }\n        var terms = {}\n        terms[field] = value\n        must.add({ terms: terms })\n    } else if (type == \'like\') {\n        var wildcard = {}\n        wildcard[field] = \'*\' + value + \'*\'\n        must.add({ wildcard: wildcard })\n    } else if (type == \'notPrefix\') {\n        var excluded = {}\n        excluded[field] = value + \'*\'\n        mustNot.add({ wildcard: excluded })\n    } else {\n        var term = {}\n        term[field] = value\n        must.add({ term: term })\n    }\n}\n\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\nvar requestConditions = body?.conditions == null ? [] : body.conditions\nvar must = [ { term: { assetType: \'db\' } } ]\nvar mustNot = [\n    { wildcard: { dbName: \'codex_*\' } },\n    { wildcard: { database: \'codex_*\' } }\n]\nfor (condition in requestConditions) {\n    addCondition(must, mustNot, condition)\n}\n\nvar sortField = blank(body?.sortField) ? \'updatedTime\' : body.sortField\nvar sortDir = text(body?.sortDir).toLowerCase() == \'asc\' ? \'asc\' : \'desc\'\nvar sort = {}\nsort[sortField] = { order: sortDir, unmapped_type: \'keyword\' }\n\n// 数据源数量通常远小于数据表数量。先取回匹配的索引候选，再一次性以控制库校验，\n// 这样既保留 ES 的检索能力，也不会让删除后的索引残留成为可操作数据源。\nvar result = null\nvar esAvailable = true\ntry {\n    result = tenantEs.index(configData().es_dataassets).search({\n        from: 0,\n        size: 10000,\n        track_total_hits: true,\n        query: { bool: { must: must, must_not: mustNot } },\n        sort: [sort]\n    })\n} catch (e) {\n    // ES is a search projection. A temporary transport failure must not make\n    // the authoritative datasource list unavailable.\n    esAvailable = false\n    log.warn(\'数据源 ES 查询失败，改用 MySQL 兜底: {}\', e?.message)\n}\n\nvar hits = result?.hits?.hits == null ? [] : result.hits.hits\nif (!esAvailable) {\n    var fallbackRows = db.table(\'db_datasource_t\').where()\n        .eq(\'is_del\', 0).orderBy(\'updated_time\', sortDir).select()\n    fallbackRows = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', fallbackRows)\n    var fallbackItems = []\n    for (source in fallbackRows) {\n        var item = {}\n        item.putAll(source)\n        item.dbName = blank(item.dbName) ? item.db_name : item.dbName\n        item.appName = blank(item.appName) ? item.app_name : item.appName\n        item.updatedTime = blank(item.updatedTime) ? item.updated_time : item.updatedTime\n        item.createdTime = blank(item.createdTime) ? item.created_time : item.createdTime\n        item.assetStatus = item.assetStatus == null ? item.asset_status : item.assetStatus\n        item.flowStatus = item.flowStatus == null ? item.flow_status : item.flowStatus\n        item.displayStatus = text(item.assetStatus) == \'2\' ? 2 : 0\n        item.display_status = item.displayStatus\n        item.asset_status = item.displayStatus\n        item.tableNum = item.tableNum == null ? 0 : item.tableNum\n        item.table_num = item.tableNum\n\n        var matched = true\n        for (condition in requestConditions) {\n            if (condition == null || blank(condition.value) || !matched) {\n                continue\n            }\n            var field = condition.field\n            var value = condition.value\n            if (field == \'assetType\') {\n                matched = text(value) == \'db\'\n            } else if (field == \'registrationState\') {\n                matched = (text(item.assetStatus) == \'2\' ? \'completed\' : \'pending\') == text(value)\n            } else if (field == \'keyword\') {\n                var keyword = text(value).toLowerCase()\n                matched = text(item.dbName).toLowerCase().indexOf(keyword) >= 0\n                    || text(item.appName).toLowerCase().indexOf(keyword) >= 0\n                    || text(item.database).toLowerCase().indexOf(keyword) >= 0\n            } else if (condition.type == \'in\') {\n                matched = value.contains(item[field])\n            } else {\n                matched = text(item[field]) == text(value)\n            }\n        }\n        if (matched) {\n            fallbackItems.add(item)\n        }\n    }\n    var fallbackTotal = fallbackItems.size()\n    var fallbackStart = (pageNum - 1) * pageSize\n    if (fallbackStart < 0) {\n        fallbackStart = 0\n    }\n    var fallbackEnd = fallbackStart + pageSize\n    fallbackEnd = fallbackEnd > fallbackTotal ? fallbackTotal : fallbackEnd\n    var fallbackList = fallbackStart >= fallbackTotal ? [] : fallbackItems.subList(fallbackStart::int, fallbackEnd::int)\n    return { pageNum: pageNum, pageSize: pageSize, total: fallbackTotal, list: withMetadataCounts(fallbackList) }\n}\n\nvar candidateIds = []\nfor (hit in hits) {\n    var candidateId = hit?._source?.tid || hit?._id\n    if (!blank(candidateId)) {\n        candidateIds.add(candidateId + \'\')\n    }\n}\n\nvar datasourceById = {}\nif (candidateIds.size() > 0) {\n    var datasourceRows = db.table(\'db_datasource_t\').where()\n        .in(\'tid\', candidateIds).eq(\'is_del\', 0).select()\n    datasourceRows = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', datasourceRows)\n    for (datasource in datasourceRows) {\n        var datasourceId = datasource?.tid\n        if (!blank(datasourceId)) {\n            datasourceById[datasourceId + \'\'] = datasource\n        }\n    }\n}\n\nvar validItems = []\nfor (hit in hits) {\n    if (hit?._source == null) {\n        continue\n    }\n    var indexItem = hit._source\n    var tid = indexItem.tid || hit._id\n    var datasource = blank(tid) ? null : datasourceById[tid + \'\']\n    // The named-table tenant interceptor applies the current tenant condition here.\n    // An ES document without a matching active control-table row is stale and must not\n    // be shown as an editable data source.\n    if (datasource == null) {\n        continue\n    }\n\n    var item = {}\n    item.putAll(indexItem)\n    item.putAll(datasource)\n\n    var assetStatus = datasource.asset_status == null ? datasource.assetStatus : datasource.asset_status\n    var flowStatus = item.flowStatus\n    var displayStatus = text(assetStatus) == \'2\' ? 2 : 0\n    item.tid = tid\n    item.assetStatus = assetStatus\n    item.asset_status = assetStatus\n    item.flowStatus = flowStatus\n    item.flow_status = flowStatus\n    item.displayStatus = displayStatus\n    item.display_status = displayStatus\n    item.tableNum = item.tableNum == null ? 0 : item.tableNum\n    item.table_num = item.tableNum\n    // 列表仅用于展示与定位，连接凭据必须留在服务端主表。\n    item.remove(\'password\')\n    item.remove(\'username\')\n    item.remove(\'jdbcUrl\')\n    item.remove(\'jdbc_url\')\n    item.remove(\'poolCfg\')\n    item.remove(\'pool_cfg\')\n    var requestedRegistrationState = null\n    for (condition in requestConditions) {\n        if (condition?.field == \'registrationState\' && !blank(condition.value)) {\n            requestedRegistrationState = text(condition.value)\n        }\n    }\n    if (blank(requestedRegistrationState) || requestedRegistrationState == (displayStatus == 2 ? \'completed\' : \'pending\')) {\n        validItems.add(item)\n    }\n}\n\nvar total = validItems.size()\nvar start = (pageNum - 1) * pageSize\nif (start < 0) {\n    start = 0\n}\nvar end = start + pageSize\nend = end > total ? total : end\nvar list = start >= total ? [] : validItems.subList(start::int, end::int)\nreturn { pageNum: pageNum, pageSize: pageSize, total: total, list: withMetadataCounts(list) }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/01.数据源分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_database_list_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_database_list_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "02.数据源列表查询",\n  "createTime": null,\n  "updateTime": 1784510683572,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"appId\\": \\"可选\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "下拉列表同样读取 ES，避免每次打开表单扫描主表和全部动态属性；使用请求参数 appId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据源列表查询\n// 路由：POST /dst/database/list\n// 业务说明：下拉列表同样读取 ES，避免每次打开表单扫描主表和全部动态属性；使用请求参数 appId。\nimport tenantEs\nimport \'@/common/configData\' as configData\n\n// 下拉列表同样读取 ES，避免每次打开表单扫描主表和全部动态属性。\nvar filters = [ { term: { assetType: \'db\' } } ]\nvar excluded = [\n    { wildcard: { dbName: \'codex_*\' } },\n    { wildcard: { database: \'codex_*\' } }\n]\n// 解析请求体并为可选参数设置默认值。\nif (body?.appId != null && (body.appId + \'\').trim() != \'\') {\n    filters.add({ term: { appId: body.appId } })\n}\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar result = tenantEs.index(configData().es_dataassets).search({ size: 10000, query: { bool: { filter: filters, must_not: excluded } }, sort: [ { updatedTime: { order: \'desc\', unmapped_type: \'keyword\' } } ] })\nvar list = []\nfor (hit in (result?.hits?.hits == null ? [] : result.hits.hits)) {\n    if (hit?._source != null) {\n        list.add(hit._source)\n    }\n}\n// 返回当前业务分支的标准结果。\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据源列表查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_page_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_page_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "01.数据表分页查询",\n  "createTime": 1784454007655,\n  "updateTime": 1790394629431,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"dbId\\": \\"可选数据源ID\\",\\n    \\"conditions\\": [\\n        {\\n            \\"field\\": \\"assetType\\",\\n            \\"type\\": \\"match\\",\\n            \\"value\\": \\"app\\"\\n        }\\n    ],\\n    \\"keyword\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据表管理 01：分页查询已登记数据表；使用请求参数 tid、dbId、datasourceId、conditions、keyword、pageNum、pageSize；涉及 db_table_t、db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.数据表分页查询\n// 路由：POST /dst/database/table/page\n// 业务说明：数据表管理 01：分页查询已登记数据表；使用请求参数 tid、dbId、datasourceId、conditions、keyword、pageNum、pageSize；涉及 db_table_t、db_datasource_t 等业务表。\nimport java.util.Map\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n\n/*\n * 数据表管理 01：分页查询已登记数据表。\n *\n * 主数据及全部表属性直接读取 db_table_t，数据源名称读取 db_datasource_t。\n * 本接口只读，不访问物理业务库、不写 MySQL 或 Elasticsearch。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => textOf(value).trim().toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar putIfPresent = (target, name, value) => {\n    if (value != null) {\n        target[name] = value\n    }\n}\nvar tableData = (row) => {\n    var tid = rowValue(row, [\'tid\'])\n    var item = {\n        tid: tid,\n        id: tid,\n        assetType: \'table\',\n        datasourceId: firstValue(row, [\'datasourceId\', \'datasource_id\']),\n        dbId: firstValue(row, [\'datasourceId\', \'datasource_id\']),\n        tableName: firstValue(row, [\'tableName\', \'table_name\']),\n        tableNameEn: firstValue(row, [\'tableNameEn\', \'table_name_en\', \'tableName\', \'table_name\']),\n        tableNameCn: firstValue(row, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']),\n        tableComment: firstValue(row, [\'tableComment\', \'table_comment\', \'tableNameCn\', \'table_name_cn\']),\n        tableType: firstValue(row, [\'tableType\', \'table_type\']),\n        businessType: firstValue(row, [\'businessType\', \'business_type\']),\n        businessTypeReason: firstValue(row, [\'businessTypeReason\', \'business_type_reason\']),\n        annotated: rowValue(row, [\'annotated\']),\n        recordCount: rowValue(row, [\'recordCount\', \'record_count\']),\n        fieldCount: rowValue(row, [\'fieldCount\', \'field_count\']),\n        storageSize: firstValue(row, [\'storageSize\', \'storage_size\']),\n        totalSizeBytes: rowValue(row, [\'totalSizeBytes\', \'total_size_bytes\']),\n        totalSizeFormatted: firstValue(row, [\'totalSizeFormatted\', \'total_size_formatted\', \'storageSize\', \'storage_size\']),\n        ddlCreatTime: firstValue(row, [\'ddlCreateTime\', \'ddl_create_time\']),\n        ddlUpdateTime: firstValue(row, [\'ddlUpdateTime\', \'ddl_update_time\']),\n        orgId: firstValue(row, [\'orgId\', \'org_id\']),\n        orgPath: firstValue(row, [\'orgPath\', \'org_path\']),\n        relatedDirectory: firstValue(row, [\'relatedDirectory\', \'related_directory\']),\n        dataSourceType: firstValue(row, [\'dataSourceType\', \'data_source_type\']),\n        timestampField: firstValue(row, [\'timestampField\', \'timestamp_field\']),\n        dictionaryStructureType: firstValue(row, [\'dictionaryStructureType\', \'dictionary_structure_type\']),\n        dictionaryTableFlag: rowValue(row, [\'dictionaryTableFlag\', \'dictionary_table_flag\']),\n        fieldGovernanceConfig: rowValue(row, [\'fieldGovernanceConfig\', \'field_governance_config\']),\n        dictionaryProfiles: rowValue(row, [\'dictionaryProfiles\', \'dictionary_profiles\']),\n        dictionaryProfile: rowValue(row, [\'dictionaryProfile\', \'dictionary_profile\']),\n        dictionaryCategories: rowValue(row, [\'dictionaryCategories\', \'dictionary_categories\']),\n        sourceCatalogId: firstValue(row, [\'sourceCatalogId\', \'source_catalog_id\']),\n        sourceTableId: firstValue(row, [\'sourceTableId\', \'source_table_id\', \'tid\']),\n        sourceTableName: firstValue(row, [\'sourceTableName\', \'source_table_name\', \'tableName\', \'table_name\']),\n        manageUnit: firstValue(row, [\'manageUnit\', \'manage_unit\', \'orgId\', \'org_id\']),\n        assetDesc: firstValue(row, [\'assetDesc\', \'asset_desc\', \'tableComment\', \'table_comment\']),\n        catalogName: firstValue(row, [\'catalogName\', \'catalog_name\', \'tableNameCn\', \'table_name_cn\']),\n        catalogNameEn: firstValue(row, [\'catalogNameEn\', \'catalog_name_en\', \'tableName\', \'table_name\']),\n        tenantId: firstValue(row, [\'tenantId\', \'tenant_id\']),\n        assetStatus: rowValue(row, [\'assetStatus\', \'asset_status\']),\n        flowStatus: rowValue(row, [\'flowStatus\', \'flow_status\']),\n        regTime: rowValue(row, [\'regTime\', \'reg_time\']),\n        createdTime: rowValue(row, [\'createdTime\', \'created_time\']),\n        updatedTime: rowValue(row, [\'updatedTime\', \'updated_time\'])\n    }\n    item.regTime_date = item.regTime\n    item.createdTime_date = item.createdTime\n    item.updatedTime_date = item.updatedTime\n    // 返回当前业务分支的标准结果。\n    return item\n}\nvar matches = (item, condition) => {\n    if (condition == null || blank(condition.field)) {\n        // 返回当前业务分支的标准结果。\n        return true\n    }\n    var actual = item[condition.field]\n    var expected = condition.value\n    var type = blank(condition.type) ? \'match\' : condition.type\n    if (type == \'null\') {\n        // 返回当前业务分支的标准结果。\n        return blank(actual)\n    }\n    if (type == \'like\') {\n        // 返回当前业务分支的标准结果。\n        return lower(actual).indexOf(lower(expected)) >= 0\n    }\n    if (type == \'in\') {\n        if (expected == null) {\n            // 返回当前业务分支的标准结果。\n            return true\n        }\n        for (value in expected) {\n            if (textOf(actual) == textOf(value)) {\n                // 返回当前业务分支的标准结果。\n                return true\n            }\n        }\n        // 返回当前业务分支的标准结果。\n        return false\n    }\n    // 返回当前业务分支的标准结果。\n    return textOf(actual) == textOf(expected)\n}\n\n// 先将精确的表/数据源范围下推到 MySQL，避免登记一张表时读取整个租户的治理配置。\nvar requestedTableId = body?.tid\nvar requestedSourceId = blank(body?.dbId) ? body?.datasourceId : body.dbId\nvar tableRows = []\nif (!blank(requestedTableId)) {\n    tableRows = db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0).eq(\'tid\', requestedTableId).select()\n} else if (!blank(requestedSourceId)) {\n    tableRows = db.select("""\n        SELECT * FROM db_table_t\n         WHERE tenant_id = #{tenantId} AND is_del = 0 AND datasource_id = #{requestedSourceId}\n         ORDER BY updated_time DESC, created_time DESC\n    """)\n} else {\n    tableRows = db.select("""\n        SELECT * FROM db_table_t\n         WHERE tenant_id = #{tenantId} AND is_del = 0\n         ORDER BY updated_time DESC, created_time DESC\n    """)\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar datasourceRows = db.select("""\n    SELECT tid, db_name, app_id, org_id\n      FROM db_datasource_t\n     WHERE is_del = 0\n""")\nvar datasourceMap = {}\nfor (source in datasourceRows) {\n    datasourceMap[firstValue(source, [\'tid\'])] = source\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar conditions = body == null || body.conditions == null ? [] : body.conditions\nfor (field in [\'tid\', \'dbId\', \'datasourceId\', \'businessType\', \'dataSourceType\', \'orgId\', \'assetStatus\']) {\n    if (body != null && !blank(body[field])) {\n        conditions.add({ field: field, value: body[field], type: \'match\' })\n    }\n}\nvar keyword = body == null ? null : body.keyword\nvar rows = []\nfor (tableRow in tableRows) {\n    var item = tableData(tableRow)\n    var source = datasourceMap[item.datasourceId]\n    if (source != null) {\n        item.dbName = firstValue(source, [\'dbName\', \'db_name\'])\n        item.appId = firstValue(source, [\'appId\', \'app_id\'])\n        if (blank(item.orgId)) {\n            item.orgId = firstValue(source, [\'orgId\', \'org_id\'])\n        }\n    }\n    var accepted = true\n    for (condition in conditions) {\n        if (!matches(item, condition)) {\n            accepted = false\n        }\n    }\n    if (accepted && !blank(keyword)) {\n        var searchText = lower(item.tableName) + \' \' + lower(item.tableNameCn) + \' \' + lower(item.tableComment)\n        accepted = searchText.indexOf(lower(keyword)) >= 0\n    }\n    if (accepted) {\n        rows.add(item)\n    }\n}\n\nvar betterRow = (next, current) => {\n    if (current == null) { return true }\n    var nextFields = next.fieldCount == null ? 0 : next.fieldCount::int\n    var currentFields = current.fieldCount == null ? 0 : current.fieldCount::int\n    if (nextFields != currentFields) { return nextFields > currentFields }\n    var nextAnnotated = next.annotated == null ? 0 : next.annotated::int\n    var currentAnnotated = current.annotated == null ? 0 : current.annotated::int\n    return nextAnnotated > currentAnnotated\n}\nvar rowByKey = {}\nvar dedupedRows = []\nfor (item in rows) {\n    var key = firstValue(item, [\'datasourceId\', \'dbId\']) + \'@@\' + lower(item.tableName)\n    if (blank(item.tableName) || blank(firstValue(item, [\'datasourceId\', \'dbId\']))) {\n        dedupedRows.add(item)\n    } else if (rowByKey[key] == null) {\n        rowByKey[key] = item\n        dedupedRows.add(item)\n    } else if (betterRow(item, rowByKey[key])) {\n        var oldItem = rowByKey[key]\n        rowByKey[key] = item\n        for (idx, existing in dedupedRows) { if (existing.tid == oldItem.tid) { dedupedRows[idx] = item } }\n    }\n}\nrows = dedupedRows\n\nvar pageNum = body == null || body.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body == null || body.pageSize == null ? 20 : body.pageSize::int\nif (pageNum < 1) {\n    pageNum = 1\n}\nif (pageSize < 1) {\n    pageSize = 20\n}\nvar offset = (pageNum - 1) * pageSize\nvar pageRows = []\nfor (index, item in rows) {\n    if (index >= offset && index < offset + pageSize) {\n        pageRows.add(item)\n    }\n}\n// 返回当前业务分支的标准结果。\nreturn {\n    pageNum: pageNum,\n    pageSize: pageSize,\n    total: rows.size(),\n    list: pageRows\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/01.数据表分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_list_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_list_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "02.数据表列表查询",\n  "createTime": 1784454007655,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dbId\\": \\"可选数据源ID\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据表管理 02：返回符合条件的已登记数据表列表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据表列表查询\n// 路由：POST /dst/database/table/list\n// 业务说明：数据表管理 02：返回符合条件的已登记数据表列表。\nimport \'@post:/dst/database/table/page\' as tablePage\n\n/*\n * 数据表管理 02：返回符合条件的已登记数据表列表。\n *\n * 复用分页查询的统一字段拼装与过滤逻辑；只读，不修改表资产或 ES。\n */\n\nvar originalBody = body\nbody = {\n    ...(originalBody == null ? {} : originalBody),\n    pageNum: 1,\n    pageSize: originalBody == null || originalBody.pageSize == null ? 10000 : originalBody.pageSize\n}\nvar result = tablePage()\nbody = originalBody\n// 返回当前业务分支的标准结果。\nreturn result == null || result.list == null ? [] : result.list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/02.数据表列表查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_detail_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_detail_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "03.数据表详情",\n  "createTime": 1784454007655,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"00e4a8e8cc254c708925a853200bf5b9\\",\\n    \\"tid\\": \\"00e4a8e8cc254c708925a853200bf5b9\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据表管理 03：读取单张数据表的登记详情和治理配置；使用请求参数 tid、tableId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据表详情\n// 路由：POST /dst/database/table/detail\n// 业务说明：数据表管理 03：读取单张数据表的登记详情和治理配置；使用请求参数 tid、tableId。\nimport \'@post:/dst/database/table/list\' as tableList\n\n/*\n * 数据表管理 03：读取单张数据表的登记详情和治理配置。\n *\n * 主表为 db_table_t；字段详情由 /dst/database/metadata/columns 单独读取。\n * 本接口只读，不自动刷新物理元数据，也不自动保存。\n */\n\nvar tableId = body == null ? null : (body.tid == null ? body.tableId : body.tid)\nif (tableId == null || (tableId + \'\').trim() == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tableId 不能为空\'\n}\nvar oldBody = body\nbody = { tid: tableId, pageSize: 1 }\nvar rows = tableList()\nbody = oldBody\n// 返回当前业务分支的标准结果。\nreturn rows == null || rows.size() == 0 ? null : rows[0]\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/03.数据表详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_save_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_save_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "04.保存数据表",\n  "createTime": 1784454007655,\n  "updateTime": 1787153759051,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"可选\\",\\n    \\"propList\\": {\\n        \\"dbId\\": \\"8b0a98de552b4bc68a203293fadfff33\\",\\n        \\"tableName\\": \\"表名\\"\\n    },\\n    \\"tenantId\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据表管理 04：新增或修改 db_table_t；使用请求参数 propList；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.保存数据表\n// 路由：POST /dst/database/table/saveOrUpdate\n// 业务说明：数据表管理 04：新增或修改 db_table_t；使用请求参数 propList；执行数据库写入并返回处理结果。\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport log\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\nimport tenantRuntime\n\n/*\n * 数据表管理 04：新增或修改 db_table_t。\n *\n * 全部表属性写入 db_table_t 物理字段，并同步 dataassets ES 文档。表 ID 沿用\n * 调用方传入的 tid；不写 da_prop_t、da_asset_t 或审批关系。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar nowTime = () => new Date()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstBody = (keys) => {\n    for (key in keys) {\n        var value = body == null ? null : body[key]\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar props = body == null || body.propList == null ? {} : body.propList\nvar tableId = firstBody([\'tid\', \'tableId\', \'id\'])\nif (blank(tableId)) {\n    tableId = newId()\n}\nvar datasourceId = props.datasourceId == null ? props.dbId : props.datasourceId\nif (blank(datasourceId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'datasourceId 不能为空\'\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar existing = db.table(\'db_table_t\').where().eq(\'tid\', tableId).selectOne()\nvar tableName = props.tableName == null ? props.tableNameEn : props.tableName\nif (blank(tableName) && existing == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tableName 不能为空\'\n}\n// 数据表资产必须继承当前登录租户，不能信任调用方携带的 tenantId。\nvar tenantId = textOf(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再保存数据表\'\n}\nvar values = {\n    tid: tableId,\n    datasource_id: datasourceId,\n    table_name: tableName,\n    table_name_en: tableName,\n    table_name_cn: props.tableNameCn,\n    table_comment: props.tableComment == null ? props.tableNameCn : props.tableComment,\n    table_type: props.tableType,\n    business_type: props.businessType,\n    business_type_reason: props.businessTypeReason,\n    annotated: props.annotated,\n    record_count: props.recordCount,\n    field_count: props.fieldCount,\n    storage_size: props.storageSize,\n    total_size_formatted: props.totalSizeFormatted == null ? props.storageSize : props.totalSizeFormatted,\n    total_size_bytes: props.totalSizeBytes == null ? props.totalSizeBytes_num : props.totalSizeBytes,\n    org_id: props.orgId,\n    org_path: props.orgPath,\n    related_directory: props.relatedDirectory,\n    data_source_type: props.dataSourceType,\n    source_table_id: tableId,\n    source_table_name: tableName,\n    manage_unit: props.manageUnit == null ? props.orgId : props.manageUnit,\n    asset_desc: props.assetDesc == null ? props.tableComment : props.assetDesc,\n    tenant_id: tenantId,\n    asset_status: 2,\n    flow_status: 2,\n    flow_order_id: null,\n    is_del: 0,\n    updated_time: nowTime()\n}\nif (existing == null) {\n    values.created_time = nowTime()\n    values.reg_time = nowTime()\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'db_table_t\').primary(\'tid\').insert(values)\n} else {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'db_table_t\').primary(\'tid\').update(values, true)\n}\nvar doc = {\n    tid: tableId,\n    id: tableId,\n    assetType: \'table\',\n    dbId: datasourceId,\n    datasourceId: datasourceId,\n    tableName: tableName,\n    tableNameEn: tableName,\n    tableNameCn: props.tableNameCn,\n    tableComment: props.tableComment == null ? props.tableNameCn : props.tableComment,\n    tableType: props.tableType,\n    businessType: props.businessType,\n    recordCount: props.recordCount,\n    fieldCount: props.fieldCount,\n    storageSize: props.storageSize,\n    orgId: props.orgId,\n    orgPath: props.orgPath,\n    dataSourceType: props.dataSourceType,\n    assetStatus: 2,\n    flowStatus: 2,\n    updatedTime: date_format(now)\n}\nvar excludedIndexProps = {\n    fieldGovernanceConfig: true,\n    dictionaryProfiles: true,\n    dictionaryProfile: true,\n    dictionaryCategories: true,\n    columns: true\n}\nfor (key in props.keySet()) {\n    if (excludedIndexProps[key] == null) {\n        doc[key] = props[key]\n    }\n}\ntry {\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(doc), false)\n} catch (e) {\n    log.warn(\'同步数据表 ES 失败, tid: {}, error: {}\', tableId, e.message)\n}\n// 返回当前业务分支的标准结果。\ntry {\n    body = { tid: datasourceId }\n    refreshAssetIndex()\n} catch (e) {\n    log.warn(\'sync datasource ES stats failed, tid: {}, error: {}\', datasourceId, e.message)\n}\nreturn { tid: tableId, id: tableId, assetType: \'table\' }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/04.保存数据表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_govern_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_govern_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "05.保存数据表治理配置",\n  "createTime": 1784454007655,\n  "updateTime": 1787155350373,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/governance/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"00e4a8e8cc254c708925a853200bf5b9\\",\\n    \\"propList\\": {\\n    },\\n    \\"columns\\": [\\n    ],\\n    \\"tid\\": \\"00e4a8e8cc254c708925a853200bf5b9\\",\\n    \\"fieldGovernanceConfig\\": \\"测试\\",\\n    \\"catalogItems\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据表管理 05：保存登记步骤 3/4 的表治理配置；使用请求参数 tableId、tid、propList、fieldGovernanceConfig、dryRun、columns、catalogItems、fields；涉及 db_table_column_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.保存数据表治理配置\n// 路由：POST /dst/database/table/governance/save\n// 业务说明：数据表管理 05：保存登记步骤 3/4 的表治理配置；使用请求参数 tableId、tid、propList、fieldGovernanceConfig、dryRun、columns、catalogItems、fields；涉及 db_table_column_t、db_table_t 等业务表。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport \'@/common/registeredTableCatalogProjection\' as registeredTableCatalogProjection\nimport java.util.Map\nimport java.util.List\nimport log\nimport cn.hutool.core.util.IdUtil\nimport metadataAsset\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n\n/*\n * 数据表管理 05：保存登记步骤 3/4 的表治理配置。\n *\n * 表级配置写 db_table_t 物理字段，字段治理配置写 db_table_column_t。\n * 不写 da_prop_t，不创建 asset_type=catalog 的资产、目录关系或审批关系。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar nowTime = () => new Date()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar valueText = (value) => {\n    if (value == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 返回当前业务分支的标准结果。\n    return value instanceof Map || value instanceof List ? jsons.toJSONStr(value) : textOf(value)\n}\nvar itemValue = (item, keys) => {\n    for (key in keys) {\n        if (item != null && item[key] != null) {\n            // 返回当前业务分支的标准结果。\n            return item[key]\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar toInt = (value, fallback) => blank(value) ? fallback : value::int\n// 第四步保存的字段配置是登记后的字段主数据。探查尚未创建字段读模型时也必须在这里落库，\n// 让物化建表直接读取登记字段，而不是依赖后续 refreshTableInfo 补数据。\nvar saveColumns = (tableId, items) => {\n    if (items == null || items.size() == 0) {\n        return 0\n    }\n    var existingRows = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', tableId).eq(\'is_del\', 0).select()\n    var existingByName = {}\n    for (existing in (existingRows == null ? [] : existingRows)) {\n        var existingName = textOf(rowValue(existing, [\'columnName\', \'column_name\']))\n        if (!blank(existingName)) {\n            existingByName[existingName.trim().toLowerCase()] = existing\n        }\n    }\n    var newRows = []\n    var ordinal = 0\n    for (item in items) {\n        ordinal = ordinal + 1\n        var columnName = itemValue(item, [\'columnName\', \'colEn\', \'fieldName\'])\n        if (blank(columnName)) {\n            continue\n        }\n        var key = textOf(columnName).trim().toLowerCase()\n        var existing = existingByName[key]\n        var columnId = existing == null ? newId() : rowValue(existing, [\'tid\'])\n        var values = {\n            tid: columnId,\n            table_id: tableId,\n            column_name: columnName,\n            column_comment: itemValue(item, [\'columnComment\', \'colName\']) || columnName,\n            data_type: itemValue(item, [\'dataType\', \'columnType\']),\n            column_type: itemValue(item, [\'columnType\', \'dataType\']),\n            length: toInt(itemValue(item, [\'length\', \'columnLength\']), 0),\n            precision_length: toInt(itemValue(item, [\'precisionLength\', \'precision\', \'colPrecision\']), 0),\n            scale: toInt(itemValue(item, [\'scale\']), 0),\n            nullable: toInt(itemValue(item, [\'nullable\']), 1),\n            default_value: itemValue(item, [\'defaultValue\']),\n            primary_key: toInt(itemValue(item, [\'primaryKey\']), 0),\n            auto_increment: toInt(itemValue(item, [\'autoIncrement\']), 0),\n            is_unique: toInt(itemValue(item, [\'isUnique\', \'unique\']), 0),\n            indexed: toInt(itemValue(item, [\'indexed\']), 0),\n            ordinal_position: toInt(itemValue(item, [\'ordinalPosition\']), ordinal),\n            charset: itemValue(item, [\'charset\']),\n            collation: itemValue(item, [\'collation\']),\n            extra: itemValue(item, [\'extra\']),\n            source_table_column_id: itemValue(item, [\'sourceTableColumnId\']) || columnId,\n            is_del: 0,\n            updated_time: nowTime()\n        }\n        if (existing == null) {\n            values.created_time = nowTime()\n            newRows.add(values)\n        } else {\n            db.table(\'db_table_column_t\').primary(\'tid\').update(values, true)\n        }\n    }\n    if (newRows.size() > 0) {\n        metadataAsset.batchInsertTableColumns(newRows)\n    }\n    return newRows.size()\n}\n// 解析请求体并为可选参数设置默认值。\nvar tableId = body == null ? null : (body.tableId == null ? body.tid : body.tableId)\nif (blank(tableId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tableId 不能为空\'\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar table = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (table == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'数据表不存在或已删除\'\n}\nvar props = body.propList == null ? {} : body.propList\nvar governance = body.fieldGovernanceConfig == null ? props.fieldGovernanceConfig : body.fieldGovernanceConfig\nvar dictionaryCategories = props.dictionaryCategories\nvar dictionaryProfiles = props.dictionaryProfiles\nvar dictionaryProfile = props.dictionaryProfile\n// “暂不处理”是已记录但尚未标注的特殊状态。历史数据中的“不确定”一并按该语义处理，\n// 不能在保存治理配置时又被强制写为已标注，否则返回第二步会进入右侧已标注列表。\nvar businessType = blank(props.businessType)\n    ? textOf(rowValue(table, [\'businessType\', \'business_type\']))\n    : textOf(props.businessType).trim()\nvar pendingBusinessType = businessType == \'暂不处理\' || businessType == \'不确定\'\nvar annotated = pendingBusinessType ? 0 : 1\nif (body?.dryRun == true) {\n    return { tid: tableId, tableId: tableId, assetStatus: 2, flowStatus: 2, annotated: annotated, dryRun: true }\n}\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table(\'db_table_t\').primary(\'tid\').update({\n    tid: tableId,\n    table_name_cn: props.tableNameCn,\n    table_name_en: props.tableName,\n    table_comment: props.tableComment == null ? props.tableNameCn : props.tableComment,\n    business_type: businessType,\n    business_type_reason: props.businessTypeReason,\n    timestamp_field: props.timestampField,\n    dictionary_structure_type: props.dictionaryStructureType,\n    dictionary_table_flag: props.dictionaryTableFlag,\n    field_governance_config: valueText(governance),\n    dictionary_categories: valueText(dictionaryCategories),\n    dictionary_profiles: valueText(dictionaryProfiles),\n    dictionary_profile: valueText(dictionaryProfile),\n    catalog_name: props.catalogName == null ? props.tableNameCn : props.catalogName,\n    catalog_name_en: props.catalogNameEn == null ? props.tableName : props.catalogNameEn,\n    source_table_id: tableId,\n    source_table_name: props.tableName,\n    manage_unit: props.manageUnit == null ? props.orgId : props.manageUnit,\n    asset_desc: props.assetDesc,\n    annotated: annotated,\n    asset_status: 2,\n    flow_status: 2,\n    flow_order_id: null,\n    updated_time: nowTime(),\n    is_del: 0\n}, true)\nvar items = body.columns\nif (items == null) {\n    items = body.catalogItems\n}\nif (items == null) {\n    items = body.fields\n}\nif (items == null && governance instanceof Map) {\n    items = governance.get(\'fields\')\n}\nsaveColumns(tableId, items)\nfor (item in items == null ? [] : items) {\n    var columnId = itemValue(item, [\'sourceTableColumnId\', \'tableColumnId\', \'tid\', \'id\'])\n    var column = null\n    if (!blank(columnId)) {\n        // 从 MySQL 业务表读取当前有效数据。\n        column = db.table(\'db_table_column_t\').where()\n            .eq(\'tid\', columnId).eq(\'table_id\', tableId).eq(\'is_del\', 0).selectOne()\n    }\n    if (column == null && !blank(itemValue(item, [\'columnName\', \'colEn\']))) {\n        // 从 MySQL 业务表读取当前有效数据。\n        column = db.table(\'db_table_column_t\').where()\n            .eq(\'table_id\', tableId)\n            .eq(\'column_name\', itemValue(item, [\'columnName\', \'colEn\']))\n            .eq(\'is_del\', 0)\n            .selectOne()\n    }\n    if (column == null) {\n        continue\n    }\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'db_table_column_t\').primary(\'tid\').update({\n        tid: rowValue(column, [\'tid\']),\n        catalog_item_name: itemValue(item, [\'catalogItemName\', \'colName\']),\n        catalog_item_en: itemValue(item, [\'catalogItemEn\', \'colEn\']),\n        catalog_item_type: itemValue(item, [\'catalogItemType\', \'colType\']),\n        is_masking: itemValue(item, [\'isMasking\']),\n        is_fk: itemValue(item, [\'isFk\']),\n        date_format: itemValue(item, [\'dateFormat\']),\n        mark_lvl: itemValue(item, [\'markLvl\']),\n        col_unit: itemValue(item, [\'colUnit\']),\n        col_precision: itemValue(item, [\'colPrecision\']),\n        masking_id: itemValue(item, [\'maskingId\']),\n        share_type: itemValue(item, [\'shareType\']),\n        share_condition: itemValue(item, [\'shareCondition\']),\n        is_dict: itemValue(item, [\'isDict\']),\n        dict_name: itemValue(item, [\'dictName\']),\n        col_max_length: itemValue(item, [\'colMaxLength\']),\n        data_standard_id: itemValue(item, [\'dataStandardId\']),\n        quality_rule: itemValue(item, [\'qualityRule\']),\n        enable_code_table: itemValue(item, [\'enableCodeTable\']),\n        code_table_id: itemValue(item, [\'codeTableId\']),\n        source_table_column_id: rowValue(column, [\'tid\']),\n        updated_time: nowTime()\n    }, true)\n}\n\n// 目录是“已标注”登记表的派生视图。暂不处理表只保存在物理表登记状态中，\n// 不建立目录投影，确保第二步回读时始终进入左侧未标注列表。\nvar catalogProjection = pendingBusinessType\n    ? { catalogId: null, indexed: false }\n    : registeredTableCatalogProjection(\'ensure\', tableId, true, null)\n\nvar doc = {\n    tid: tableId,\n    id: tableId,\n    assetType: \'table\',\n    dbId: rowValue(table, [\'datasourceId\', \'datasource_id\']),\n    datasourceId: rowValue(table, [\'datasourceId\', \'datasource_id\']),\n    tableName: rowValue(table, [\'tableName\', \'table_name\']),\n    tableNameEn: rowValue(table, [\'tableName\', \'table_name\']),\n    tableNameCn: props.tableNameCn,\n    businessType: businessType,\n    businessTypeReason: props.businessTypeReason,\n    annotated: annotated,\n    timestampField: props.timestampField,\n    dictionaryStructureType: props.dictionaryStructureType,\n    dictionaryTableFlag: props.dictionaryTableFlag,\n    assetStatus: 2,\n    flowStatus: 2,\n    updatedTime: date_format(nowTime())\n}\nvar excludedIndexProps = {\n    fieldGovernanceConfig: true,\n    dictionaryProfiles: true,\n    dictionaryProfile: true,\n    dictionaryCategories: true,\n    columns: true\n}\nfor (key in props.keySet()) {\n    if (excludedIndexProps[key] == null) {\n        doc[key] = props[key]\n    }\n}\ntry {\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.saveOrUpdate(\'dataassets\', tableId, jsons.toJSONStr(doc), false)\n} catch (e) {\n    log.warn(\'同步数据表治理配置到 ES 失败, tid: {}, error: {}\', tableId, e.message)\n}\n// 返回当前业务分支的标准结果。\nreturn {\n    tid: tableId,\n    tableId: tableId,\n    assetType: \'table\',\n    catalogId: catalogProjection.catalogId,\n    catalogIndexed: catalogProjection.indexed,\n    businessType: businessType,\n    businessTypeReason: props.businessTypeReason,\n    annotated: annotated,\n    saved: true\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/05.保存数据表治理配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_delete_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_delete_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "06.删除数据表",\n  "createTime": 1784454007655,\n  "updateTime": 1786436400000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tableId\\": \\"00e4a8e8cc254c708925a853200bf5b9\\",\\n    \\"tid\\": \\"00e4a8e8cc254c708925a853200bf5b9\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "删除数据表（POST /dst/database/table/delete）。仅删除登记元数据、字段快照和 Elasticsearch 索引，不删除物理业务库中的表；使用请求参数 tableId、tid；涉及 db_table_t、db_table_column_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.删除数据表\n// 路由：POST /dst/database/table/delete\n// 业务说明：删除数据表（POST /dst/database/table/delete）。仅删除登记元数据、字段快照和 Elasticsearch 索引，不删除物理业务库中的表；使用请求参数 tableId、tid；涉及 db_table_t、db_table_column_t 等业务表。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport log\n\n/*\n * 数据表删除接口：仅删除已登记的元数据资产。\n *\n * 只软删除 db_table_t、db_table_column_t 中的登记元数据并同步 ES 文档；\n * 不操作物理业务数据库，不执行 DROP TABLE，避免误删实际业务数据。\n */\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\n\n// 兼容 tableId 和 tid 两种入参，优先使用 tableId。\nvar tableId = body == null ? null : (body.tableId == null ? body.tid : body.tableId)\nif (blank(tableId)) {\n    exit 400, \'tableId 参数不能为空\'\n}\n\n// 从控制库读取当前有效的表资产。\nvar table = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (table == null) {\n    exit 404, \'数据表不存在或已删除\'\n}\n\nvar nowText = new Date()\n\n// 先删除字段快照，再删除表资产，避免保留孤儿字段。\nvar columnDeleted = db.table(\'db_table_column_t\').where()\n    .eq(\'table_id\', tableId).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowText })\nvar tableDeleted = db.table(\'db_table_t\').where()\n    .eq(\'tid\', tableId).eq(\'is_del\', 0).update({ is_del: 1, updated_time: nowText })\n\ntry {\n    // ES 同步失败不回滚元数据删除，避免索引异常阻塞管理操作。\n    esCommonService.delete(\'dataassets\', tableId)\n} catch (e) {\n    log.warn(\'删除数据表 ES 文档失败, tid: {}, error: {}\', tableId, e.message)\n}\n\nreturn {\n    tableId: tableId,\n    tableDeleted: tableDeleted,\n    columnDeleted: columnDeleted\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/06.删除数据表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('db_table_batch_annotate_01',NULL,NULL,'{\n  "properties": {},\n  "id": "db_table_batch_annotate_01",\n  "script": null,\n  "groupId": "datapd_db_table_group_01",\n  "name": "07.批量标注数据表",\n  "createTime": null,\n  "updateTime": 1787153759223,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/batchAnnotate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"dbId\\": \\"4b5d9992d89744b9b514f8905dc27998\\",\\n  \\"annotated\\": 1,\\n  \\"dryRun\\": true,\\n  \\"refreshDatasource\\": false,\\n  \\"tables\\": [\\n    {\\n      \\"tid\\": \\"076de72a58024af2aad48c5261df440e\\",\\n      \\"propList\\": {\\n        \\"tableName\\": \\"police_case_record\\",\\n        \\"tableNameCn\\": \\"公安案件登记业务表\\",\\n        \\"tableComment\\": \\"公安案件登记业务表\\",\\n        \\"tableType\\": \\"数据表\\",\\n        \\"businessType\\": \\"业务表\\",\\n        \\"businessTypeReason\\": \\"人工批量标注业务类型\\",\\n        \\"fieldCount\\": 10,\\n        \\"recordCount\\": 0\\n      }\\n    }\\n  ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "批量标注数据表（POST /dst/database/table/batchAnnotate）。批量写入 db_table_t，并使用一次 bulk 请求同步当前分片的 dataassets ES 投影；同一数据源的已有表只预读一次，避免逐表 N+1 查询。refreshDatasource=false 可由分片客户端延迟到全部分片完成后统一刷新数据源统计；dryRun=true 时只校验和返回待写入结果；使用请求参数 tables、rows、list、datasourceId、dbId、annotated、dryRun、refreshDatasource。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.批量标注数据表\n// 路由：POST /dst/database/table/batchAnnotate\n// 业务说明：批量标注数据表（POST /dst/database/table/batchAnnotate）。批量写入 db_table_t，并使用一次 bulk 请求同步当前分片的 dataassets ES 投影；同一数据源的已有表只预读一次，避免逐表 N+1 查询。refreshDatasource=false 可由分片客户端延迟到全部分片完成后统一刷新数据源统计；dryRun=true 时只校验和返回待写入结果；使用请求参数 tables、rows、list、datasourceId、dbId、annotated、dryRun、refreshDatasource。\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport log\nimport metadataAsset\nimport tenantRuntime\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\n\n/*\n * 数据表管理 07：第二步批量标注数据表。\n *\n * 该接口服务 register-dbTable 的多选/当前筛选分片标注场景。每个数据源只预读一次\n * db_table_t，分片内逐表幂等写主表，再按 dataassets 既有 mapping 批量同步搜索投影。\n * 数据表仍以 db_table_t 为唯一主表，不写 da_asset_t/da_prop_t/审批关系。\n */\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar nowTime = () => new Date()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar normalizeKey = (value) => blank(value) ? \'\' : textOf(value).trim().toLowerCase()\nvar requiresStandardName = (businessType) => {\n    var type = blank(businessType) ? \'业务表\' : textOf(businessType).trim()\n    return type == \'字典表\' || type == \'业务表\' || type == \'日志表\'\n}\nvar syncGovernanceBusinessType = (existing, businessType) => {\n    var raw = rowValue(existing, [\'fieldGovernanceConfig\', \'field_governance_config\'])\n    if (blank(raw) || blank(businessType)) {\n        return raw\n    }\n    try {\n        var config = jsons.toJSONObject(textOf(raw))\n        config.businessType = businessType\n        return jsons.toJSONStr(config)\n    } catch (e) {\n        log.warn(\'sync field_governance_config businessType failed, tableId: {}, error: {}\', rowValue(existing, [\'tid\']), e.message)\n        return raw\n    }\n}\n\n// 解析请求体：tables/rows/list 兼容前端不同命名，annotated 默认按批量标注处理。\nvar tableItems = body == null ? null : (body.tables == null ? (body.rows == null ? body.list : body.rows) : body.tables)\nif (tableItems == null || tableItems.size() == 0) {\n    exit 400, \'tables 不能为空\'\n}\nvar requestDatasourceId = body == null ? null : (body.datasourceId == null ? body.dbId : body.datasourceId)\nvar requestAnnotated = body == null || body.annotated == null ? 1 : body.annotated\nvar annotatedFlag = textOf(requestAnnotated) == \'0\' ? 0 : 1\nvar dryRun = body != null && body.dryRun == true\nvar refreshDatasource = body == null || body.refreshDatasource != false\nvar tenantId = tenantRuntime.id()\n\n// 先完成整批参数校验，避免第 N 条业务参数错误时前 N-1 条已经落库。\nvar preparedItems = []\nfor (item in tableItems) {\n    var props = rowValue(item, [\'propList\', \'props\'])\n    if (props == null) {\n        props = item\n    }\n    var datasourceId = rowValue(props, [\'datasourceId\', \'dbId\'])\n    if (blank(datasourceId)) {\n        datasourceId = requestDatasourceId\n    }\n    if (blank(datasourceId)) {\n        exit 400, \'datasourceId 不能为空\'\n    }\n    var tableName = rowValue(props, [\'tableName\', \'tableNameEn\', \'sourceTableName\'])\n    if (blank(tableName)) {\n        exit 400, \'tableName 不能为空\'\n    }\n    var tableComment = rowValue(props, [\'tableComment\', \'tableNameCn\', \'catalogName\'])\n    var businessType = rowValue(props, [\'businessType\', \'business_type\'])\n    if (annotatedFlag == 1 && requiresStandardName(businessType)\n        && (blank(tableComment) || normalizeKey(tableComment) == normalizeKey(tableName))) {\n        exit 400, tableName + \' 请规范填写数据资源名称，不能留空或直接使用英文表名\'\n    }\n    preparedItems.add({\n        item: item,\n        props: props,\n        datasourceId: datasourceId,\n        tableName: tableName,\n        tableComment: tableComment\n    })\n}\n\n// 同一分片通常只有一个数据源；每个数据源只查一次已有表，替代逐表最多两次查询。\nvar existingCache = {}\nvar existingQueryCount = 0\nvar existingMapsOf = (datasourceId) => {\n    var datasourceKey = textOf(datasourceId)\n    var cached = existingCache[datasourceKey]\n    if (cached != null) {\n        return cached\n    }\n    var byId = {}\n    var byName = {}\n    var existingRows = db.table(\'db_table_t\').where()\n        .eq(\'datasource_id\', datasourceId).select()\n    existingQueryCount = existingQueryCount + 1\n    for (existingRow in existingRows) {\n        var existingId = rowValue(existingRow, [\'tid\'])\n        if (!blank(existingId)) {\n            byId[textOf(existingId)] = existingRow\n        }\n        if (textOf(rowValue(existingRow, [\'isDel\', \'is_del\'])) == \'0\') {\n            var existingName = rowValue(existingRow, [\'tableName\', \'table_name\'])\n            if (!blank(existingName)) {\n                byName[normalizeKey(existingName)] = existingRow\n            }\n        }\n    }\n    cached = { byId: byId, byName: byName }\n    existingCache[datasourceKey] = cached\n    return cached\n}\nvar saveColumns = (tableId, columns, tenantId) => {\n    if (columns == null || columns.size() == 0) {\n        return 0\n    }\n    var oldRows = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableId).eq(\'is_del\', 0).select()\n    var oldMap = {}\n    for (old in oldRows) {\n        oldMap[normalizeKey(rowValue(old, [\'columnName\', \'column_name\']))] = old\n    }\n    var ordinal = 0\n    var newRows = []\n    for (column in columns) {\n        ordinal = ordinal + 1\n        var columnName = rowValue(column, [\'columnName\', \'name\'])\n        if (blank(columnName)) {\n            continue\n        }\n        var old = oldMap[normalizeKey(columnName)]\n        var columnId = old == null ? newId() : rowValue(old, [\'tid\'])\n        var values = {\n            tid: columnId,\n            table_id: tableId,\n            tenant_id: tenantId,\n            column_name: columnName,\n            column_comment: old == null ? rowValue(column, [\'columnComment\']) : rowValue(old, [\'columnComment\', \'column_comment\']),\n            data_type: rowValue(column, [\'dataType\']),\n            column_type: rowValue(column, [\'columnType\', \'dataType\']),\n            length: rowValue(column, [\'length\', \'columnLength\']),\n            precision_length: rowValue(column, [\'precision\']),\n            scale: rowValue(column, [\'scale\']),\n            nullable: rowValue(column, [\'nullable\']) == false ? 0 : 1,\n            default_value: rowValue(column, [\'defaultValue\']),\n            primary_key: rowValue(column, [\'primaryKey\']) == true ? 1 : 0,\n            auto_increment: rowValue(column, [\'autoIncrement\']) == true ? 1 : 0,\n            is_unique: rowValue(column, [\'unique\']) == true ? 1 : 0,\n            indexed: rowValue(column, [\'indexed\']) == true ? 1 : 0,\n            ordinal_position: rowValue(column, [\'ordinalPosition\']) == null ? ordinal : rowValue(column, [\'ordinalPosition\']),\n            charset: rowValue(column, [\'charset\']),\n            collation: rowValue(column, [\'collation\']),\n            extra: rowValue(column, [\'extra\']),\n            is_del: 0,\n            updated_time: now\n        }\n        if (old == null) {\n            values.created_time = now\n            newRows.add(values)\n        } else {\n            db.table(\'db_table_column_t\').primary(\'tid\').update(values, true)\n        }\n    }\n    if (newRows.size() > 0) {\n        metadataAsset.batchInsertTableColumns(newRows)\n    }\n    return columns.size()\n}\n\nvar resultRows = []\nvar esIds = []\nvar esDocs = []\nvar affected = 0\nvar now = nowTime()\n\nfor (prepared in preparedItems) {\n    var item = prepared.item\n    var props = prepared.props\n    var datasourceId = prepared.datasourceId\n    var tableName = prepared.tableName\n    var tableComment = prepared.tableComment\n    var tableId = rowValue(item, [\'tid\', \'tableId\', \'id\'])\n    if (blank(tableId)) {\n        tableId = rowValue(props, [\'tid\', \'tableId\', \'id\'])\n    }\n\n    var existingMaps = existingMapsOf(datasourceId)\n    var existing = blank(tableId) ? null : existingMaps.byId[textOf(tableId)]\n    if (existing == null) {\n        existing = existingMaps.byName[normalizeKey(tableName)]\n    }\n    if (existing != null) {\n        tableId = rowValue(existing, [\'tid\'])\n    }\n    if (blank(tableId)) {\n        tableId = newId()\n    }\n\n    var valueOrExisting = (propKeys, existingKeys) => {\n        var value = rowValue(props, propKeys)\n        if (value == null && existing != null) {\n            value = rowValue(existing, existingKeys)\n        }\n        return value\n    }\n\n    // 组装 db_table_t 主表字段：保持与单表 saveOrUpdate 字段一致。\n    var values = {\n        tid: tableId,\n        datasource_id: datasourceId,\n        table_name: tableName,\n        table_name_en: tableName,\n        table_name_cn: valueOrExisting([\'tableNameCn\', \'tableComment\', \'catalogName\'], [\'tableNameCn\', \'table_name_cn\']),\n        table_comment: tableComment,\n        table_type: valueOrExisting([\'tableType\'], [\'tableType\', \'table_type\']),\n        business_type: valueOrExisting([\'businessType\'], [\'businessType\', \'business_type\']),\n        business_type_reason: valueOrExisting([\'businessTypeReason\'], [\'businessTypeReason\', \'business_type_reason\']),\n        annotated: annotatedFlag,\n        record_count: valueOrExisting([\'recordCount\'], [\'recordCount\', \'record_count\']),\n        field_count: valueOrExisting([\'fieldCount\'], [\'fieldCount\', \'field_count\']),\n        storage_size: valueOrExisting([\'storageSize\'], [\'storageSize\', \'storage_size\']),\n        total_size_formatted: valueOrExisting([\'totalSizeFormatted\', \'storageSize\'], [\'totalSizeFormatted\', \'total_size_formatted\']),\n        total_size_bytes: valueOrExisting([\'totalSizeBytes\', \'totalSizeBytes_num\'], [\'totalSizeBytes\', \'total_size_bytes\']),\n        org_id: valueOrExisting([\'orgId\'], [\'orgId\', \'org_id\']),\n        org_path: valueOrExisting([\'orgPath\'], [\'orgPath\', \'org_path\']),\n        related_directory: valueOrExisting([\'relatedDirectory\'], [\'relatedDirectory\', \'related_directory\']),\n        data_source_type: valueOrExisting([\'dataSourceType\'], [\'dataSourceType\', \'data_source_type\']),\n        source_table_id: tableId,\n        source_table_name: tableName,\n        manage_unit: rowValue(props, [\'manageUnit\', \'orgId\']),\n        asset_desc: rowValue(props, [\'assetDesc\', \'tableComment\']),\n        field_governance_config: syncGovernanceBusinessType(existing, valueOrExisting([\'businessType\'], [\'businessType\', \'business_type\'])),\n        tenant_id: tenantId,\n        asset_status: 0,\n        flow_status: 0,\n        flow_order_id: null,\n        is_del: 0,\n        updated_time: now\n    }\n\n    if (!dryRun) {\n        if (existing == null) {\n            values.created_time = now\n            values.reg_time = now\n            db.table(\'db_table_t\').primary(\'tid\').insert(values)\n        } else if (annotatedFlag == 0) {\n            // “暂不处理”仍属于用户已确认的分类决定：保留在未标注列表，\n            // 但必须持久化 business_type 和原因，返回上一步时不能再次被物理表名自动分类覆盖。\n            // 不重写字段快照，避免暂不处理动作覆盖后续步骤登记的字段配置。\n            db.table(\'db_table_t\').primary(\'tid\').update({\n                tid: tableId,\n                business_type: values.business_type,\n                business_type_reason: values.business_type_reason,\n                annotated: 0,\n                asset_status: 0,\n                flow_status: 0,\n                updated_time: now\n            }, true)\n        } else {\n            db.table(\'db_table_t\').primary(\'tid\').update(values, true)\n        }\n        affected = affected + 1\n        existingMaps.byId[textOf(tableId)] = values\n        existingMaps.byName[normalizeKey(tableName)] = values\n        if (annotatedFlag == 1) {\n            saveColumns(tableId, rowValue(props, [\'columns\']), values.tenant_id)\n        }\n\n        // 先收集轻量搜索文档，整批主表写完后统一调用一次 ES bulk。\n        var doc = {\n            tid: tableId,\n            id: tableId,\n            assetType: \'table\',\n            dbId: datasourceId,\n            datasourceId: datasourceId,\n            tableName: tableName,\n            tableNameEn: tableName,\n            tableNameCn: values.table_name_cn,\n            tableComment: tableComment,\n            tableType: values.table_type,\n            businessType: values.business_type,\n            businessTypeReason: values.business_type_reason,\n            annotated: annotatedFlag,\n            recordCount: values.record_count,\n            fieldCount: values.field_count,\n            storageSize: values.storage_size,\n            orgId: values.org_id,\n            orgPath: values.org_path,\n            dataSourceType: values.data_source_type,\n            assetStatus: 0,\n            flowStatus: 0,\n            tenantId: tenantId,\n            updatedTime: textOf(now)\n        }\n        var excludedIndexProps = {\n            fieldGovernanceConfig: true,\n            dictionaryProfiles: true,\n            dictionaryProfile: true,\n            dictionaryCategories: true,\n            columns: true\n        }\n        for (key in props.keySet()) {\n            if (excludedIndexProps[key] == null) {\n                doc[key] = props[key]\n            }\n        }\n        esIds.add(textOf(tableId))\n        esDocs.add(doc)\n    }\n\n    resultRows.add({\n        tid: tableId,\n        id: tableId,\n        datasourceId: datasourceId,\n        dbId: datasourceId,\n        tableName: tableName,\n        tableNameEn: tableName,\n        tableNameCn: values.table_name_cn,\n        tableComment: tableComment,\n        tableType: values.table_type,\n        businessType: values.business_type,\n        businessTypeReason: values.business_type_reason,\n        annotated: annotatedFlag,\n        fieldCount: values.field_count,\n        recordCount: values.record_count\n    })\n}\n\nvar esSynced = dryRun || esDocs.size() == 0\nvar esError = null\nif (!dryRun && esDocs.size() > 0) {\n    try {\n        // 使用显式 ID 的 bulk index 作为 upsert：历史表可能尚未进入 ES，partial update\n        // 会因 _doc 不存在而失败。主表已先成功落库，投影同步必须能创建缺失文档。\n        // dataassets 同时承载 app/db/table/catalog 等多类文档，不能用单个表文档反推整个索引 mapping。\n        esCommonService.bulkSaveWithIds(\'dataassets\', esIds, esDocs)\n        esSynced = true\n    } catch (e) {\n        esError = e.message\n        log.warn(\'批量标注同步数据表 ES 失败, count: {}, error: {}\', esDocs.size(), e.message)\n    }\n}\n\nif (!dryRun && refreshDatasource) {\n    var refreshedDatasourceIds = {}\n    for (row in resultRows) {\n        var rowDatasourceId = textOf(row.datasourceId)\n        if (!blank(rowDatasourceId) && refreshedDatasourceIds[rowDatasourceId] == null) {\n            refreshedDatasourceIds[rowDatasourceId] = true\n            try {\n                body = { tid: rowDatasourceId }\n                refreshAssetIndex()\n            } catch (e) {\n                log.warn(\'sync datasource ES stats failed, tid: {}, error: {}\', rowDatasourceId, e.message)\n            }\n        }\n    }\n}\n\nreturn {\n    affected: affected,\n    total: tableItems.size(),\n    dryRun: dryRun,\n    existingQueryCount: existingQueryCount,\n    esSynced: esSynced,\n    esError: esError,\n    refreshDatasource: refreshDatasource,\n    rows: resultRows\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/07.批量标注数据表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_table_group_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_db_table_group_01",\n  "name": "02.数据表管理",\n  "type": "api",\n  "parentId": "datapd_database_group_01",\n  "path": "/table",\n  "paths": [],\n  "options": []\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/02.数据表管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_database_detail_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_database_detail_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "03.数据源详情",\n  "createTime": null,\n  "updateTime": 1787156037968,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"8b0a98de552b4bc68a203293fadfff33\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{}",\n  "description": "数据源 03：读取 db_datasource_t 详情；使用请求参数 tid、silent。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据源详情\n// 路由：POST /dst/database/detail\n// 业务说明：数据源 03：读取 db_datasource_t 详情；使用请求参数 tid、silent。\nimport com.fasterxml.jackson.databind.ObjectMapper\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nimport java.util.Map\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\n\n/*\n * 数据源 03：读取 db_datasource_t 详情。\n *\n * 连接参数统一从 db_datasource_t.pool_cfg 读取；主数据、描述、网域、统计字段从 db_datasource_t 读取。\n * showConnect 由 show_connect 派生，兼容前端旧字段。\n */\n\nvar blank = (value) => value == null || (value + \'\').trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstText = (row, keys) => {\n    var value = first(row, keys)\n    return blank(value) ? null : value + \'\'\n}\nvar inferDbType = (value, jdbcUrl) => {\n    var raw = blank(value) ? \'\' : (value + \'\').toLowerCase()\n    if (!blank(raw)) {\n        return raw\n    }\n    var url = blank(jdbcUrl) ? \'\' : (jdbcUrl + \'\').toLowerCase()\n    if (url.indexOf(\':oracle:\') >= 0) {\n        return \'oracle\'\n    }\n    if (url.indexOf(\':mysql:\') >= 0) {\n        return \'mysql\'\n    }\n    if (url.indexOf(\':postgresql:\') >= 0) {\n        return \'postgresql\'\n    }\n    if (url.indexOf(\':dm:\') >= 0) {\n        return \'dameng\'\n    }\n    if (url.indexOf(\':kingbase\') >= 0) {\n        return \'kingbase8\'\n    }\n    if (url.indexOf(\':sqlserver:\') >= 0) {\n        return \'sqlserver\'\n    }\n    return null\n}\nvar databaseTypeName = (code) => {\n    if (blank(code)) {\n        return null\n    }\n    var value = (code + \'\').toLowerCase()\n    var names = {\n        mysql: \'MySQL\',\n        oracle: \'Oracle\',\n        kingbase8: \'Kingbase\',\n        kingbase: \'Kingbase\',\n        dm: \'Dameng\',\n        dameng: \'Dameng\',\n        postgres: \'PostgreSQL\',\n        postgresql: \'PostgreSQL\',\n        sqlserver: \'SQL Server\',\n        elasticsearch: \'Elasticsearch\',\n        es: \'Elasticsearch\',\n        hive: \'Hive\',\n        maxcompute: \'MaxCompute\',\n        vertica: \'Vertica\',\n        gbase8a: \'GBase 8a\'\n    }\n    return names[value] == null ? code + \'\' : names[value]\n}\n// 解析请求体并为可选参数设置默认值。\nvar tid = body == null ? null : body.tid\nvar silent = body != null && body.silent == true\nif (blank(tid)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tid不能为空\'\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar main = db.table(\'db_datasource_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (main == null) {\n    if (silent) {\n        return { found: false, tid: tid, id: tid }\n    }\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'数据源不存在\'\n}\nvar result = {}\nresult.found = true\nvar connectionConfig = datasourceConnectionConfig(\'read\', tid, null, false)\nvar hasConnectionConfig = connectionConfig != null && !connectionConfig.isEmpty()\n// show_connect 表示是否提供连接；实际参数由 da_prop_t 的 connection.* 属性统一承载。\nvar showConnectValue = first(main, [\'showConnect\', \'show_connect\'])\nvar hasConnection = showConnectValue == 1 || showConnectValue == \'1\'\nif (hasConnectionConfig) {\n    result.putAll(connectionConfig)\n}\nresult.tid = tid\nresult.id = tid\nresult.assetType = \'db\'\nresult.dbName = first(main, [\'dbName\', \'db_name\'])\nresult.database = blank(result.database) ? result.dbName : result.database\nresult.jdbcURL = first(main, [\'jdbcUrl\', \'jdbc_url\'])\nresult.dbType = inferDbType(first(main, [\'dbType\', \'db_type\']), result.jdbcURL || first(result, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\nresult.db_type = result.dbType\nresult.databaseType = result.dbType\nresult.username = first(main, [\'username\'])\nresult.password = first(main, [\'password\'])\nresult.appId = first(main, [\'appId\', \'app_id\'])\nresult.orgId = first(main, [\'orgId\', \'org_id\'])\nresult.storageDomain = first(main, [\'storageDomain\', \'storage_domain\'])\nresult.SSWL = result.storageDomain\nvar storedNodeId = first(main, [\'nodeId\', \'node_id\'])\nresult.nodeId = storedNodeId\nresult.dbVersion = first(main, [\'dbVersion\', \'db_version\'])\nresult.userCount = first(main, [\'userCount\', \'user_count\'])\nresult.viewCount = first(main, [\'viewCount\', \'view_count\'])\nresult.procedureCount = first(main, [\'procedureCount\', \'procedure_count\'])\nresult.dataSize = first(main, [\'dataSize\', \'data_size\'])\nresult.totalSize = first(main, [\'totalSize\', \'total_size\'])\nresult.contactName = first(connectionConfig, [\'contactName\', \'contact_name\'])\nresult.contactPhone = first(connectionConfig, [\'contactPhone\', \'contact_phone\'])\nresult.showConnect = hasConnection ? 1 : 0\nresult.assetDesc = first(main, [\'remark\'])\nresult.tableCount = first(main, [\'tableNum\', \'table_num\'])\nresult.tenantId = first(main, [\'tenantId\', \'tenant_id\'])\nresult.createdTime = first(main, [\'createdTime\', \'created_time\'])\nresult.updatedTime = first(main, [\'updatedTime\', \'updated_time\'])\nresult.regTime = first(main, [\'regTime\', \'reg_time\'])\nresult.assetStatus = first(main, [\'assetStatus\', \'asset_status\'])\nresult.flowStatus = first(main, [\'flowStatus\', \'flow_status\'])\n// 登记与连通状态是库详情动态表单的基础字段：登记状态允许在编辑态调整，\n// 连通状态仅反映最近一次连通性检测结果，保持只读。\nresult.connectionStatus = first(main, [\'connectionStatus\', \'connection_status\'])\n// “数据组织”是库详情动态表单属性，读取与保存统一使用 da_prop_t。\n// dataSourceType 已由上方连接扩展属性直接回填。\nif (!blank(result.appId)) {\n    var app = db.table(\'sym_application_t\').where().eq(\'tid\', result.appId).eq(\'is_del\', 0).selectOne()\n    result.appName = firstText(app, [\'appName\', \'app_name\', \'applicationName\', \'application_name\', \'name\'])\n    result.applicationName = result.appName\n    result.systemName = result.appName\n}\nif (!blank(storedNodeId)) {\n    var node = db.table(\'sym_dict_t\').where().eq(\'tid\', storedNodeId).eq(\'is_del\', 0).selectOne()\n    // dict-select 的 option.value 是 dict_code；数据库仍保存字典 tid 以维持关联完整性。\n    result.nodeId = firstText(node, [\'dictCode\', \'dict_code\']) || storedNodeId\n    result.nodeName = firstText(node, [\'dictName\', \'dict_name\', \'name\'])\n    result.nodeTypeName = result.nodeName\n}\nresult.dbTypeName = databaseTypeName(result.dbType)\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/03.数据源详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_save_update_datasource_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_save_update_datasource_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "04.保存数据源",\n  "createTime": null,\n  "updateTime": 1790641057850,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tid\\":\\"4b5d9992d89744b9b514f8905dc27998\\",\\"propList\\":{\\"dbName\\":\\"出入境人员动管系统数据库\\",\\"dbType\\":\\"mysql\\",\\"appId\\":\\"2e83a7abf33140c7a3df27d0c79e98c\\"}}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "保存数据源主记录、应用关系和 db_datasource_t.pool_cfg 连接配置，并同步 Elasticsearch；不使用 da_prop_t 动态属性；使用请求参数 tid、propList、dryRun、deferIndexRefresh。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.保存数据源\n// 路由：POST /dst/database/saveOrUpdate\n// 业务说明：保存数据源主记录、应用关系和 db_datasource_t.pool_cfg 连接配置，并同步 Elasticsearch；不使用 da_prop_t 动态属性；使用请求参数 tid、propList、dryRun、deferIndexRefresh。\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport tenantRuntime\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.json.JSONUtil\nimport java.util.Map\nimport jsons\nimport log\n\n/*\n * 数据源 04：新增或修改 db_datasource_t。\n *\n * 保存接口只写数据源主表和应用关系，并同步 ES 搜索投影；不连接物理库、不执行元数据探查。\n * 连接参数统一保存到 db_datasource_t.pool_cfg JSON 对象。第五步完成登记使用 completeOnly=true，只更新 asset_status，不触碰连接信息。\n */\nvar text = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar nowTime = new Date()\nvar tenantId = tenantRuntime.id()\n\n// 解析请求体并为可选参数设置默认值。\nvar tid = blank(body == null ? null : body.tid) ? IdUtil.getSnowflakeNextIdStr() : body.tid\nvar props = body == null || body.propList == null ? {} : body.propList\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\n\nif (blank(tenantId)) {\n    exit 400, \'无法识别当前租户，请重新登录后再保存数据源\'\n}\n// 只在尝试完成登记时读取表配置。普通第一步保存与第二至四步“下一步”不做完成校验。\n// asset_status=2 是可用元数据，不能替代第三、四步显式保存的 registrationSavedPhase。\nvar completionReview = null\nvar requestedStatus = first(props, [\'assetStatus\', \'asset_status\'])\nif (props.completeOnly == true || text(requestedStatus) == \'2\') {\n    var existed = db.table(\'db_datasource_t\').where().eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (existed == null) {\n        exit 404, \'数据源不存在或不属于当前租户\'\n    }\n    var completionTables = db.table(\'db_table_t\').where().eq(\'datasource_id\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n    var unannotatedTableCount = 0\n    var deferredTableCount = 0\n    var pendingDictionaryCount = 0\n    var pendingBusinessCount = 0\n    var pendingLogCount = 0\n    var completionIssues = []\n    for (completionTable in completionTables) {\n        var typeValue = first(completionTable, [\'businessType\', \'business_type\'])\n        var businessTypeText = blank(typeValue) ? \'\' : text(typeValue).trim()\n        var annotatedValue = first(completionTable, [\'annotated\'])\n        var annotatedText = blank(annotatedValue) ? \'\' : text(annotatedValue).trim().toLowerCase()\n        var annotated = annotatedText == \'1\' || annotatedText == \'true\' || annotatedText == \'yes\'\n        var tableName = first(completionTable, [\'tableName\', \'table_name_en\', \'table_name\'])\n        var tableId = first(completionTable, [\'tid\'])\n        if (!annotated || ![\'字典表\', \'业务表\', \'日志表\', \'过程表\', \'备份表\', \'不确定\', \'暂不处理\'].contains(businessTypeText)) {\n            unannotatedTableCount = unannotatedTableCount + 1\n            completionIssues.add({ tableId: tableId, tableName: tableName, step: 2, message: \'尚未完成标注\' })\n            continue\n        }\n        if ([\'不确定\', \'暂不处理\'].contains(businessTypeText)) {\n            deferredTableCount = deferredTableCount + 1\n            continue\n        }\n        if (![\'字典表\', \'业务表\', \'日志表\'].contains(businessTypeText)) {\n            continue\n        }\n        var configValue = first(completionTable, [\'fieldGovernanceConfig\', \'field_governance_config\'])\n        var config = null\n        try {\n            config = configValue instanceof Map ? configValue : blank(configValue) ? null : JSONUtil.parseObj(text(configValue))\n        } catch (parseError) {\n            // 无效 JSON 同未保存配置一样阻断完成登记，不使用历史资产状态兜底。\n            config = null\n        }\n        var expectedPhase = businessTypeText == \'字典表\' ? \'dictionary\' : \'business\'\n        var savedPhase = first(config, [\'registrationSavedPhase\'])\n        var savedType = first(config, [\'businessType\'])\n        if (text(savedPhase) != expectedPhase || (!blank(savedType) && text(savedType) != businessTypeText)) {\n            if (businessTypeText == \'字典表\') {\n                pendingDictionaryCount = pendingDictionaryCount + 1\n            } else if (businessTypeText == \'业务表\') {\n                pendingBusinessCount = pendingBusinessCount + 1\n            } else {\n                pendingLogCount = pendingLogCount + 1\n            }\n            completionIssues.add({ tableId: tableId, tableName: tableName, step: businessTypeText == \'字典表\' ? 3 : 4, message: \'尚未完成\' + businessTypeText + \'登记\' })\n        }\n    }\n    var tableReviewReady = completionTables.size() > 0 && completionIssues.size() == 0\n    completionReview = {\n        tid: tid, completionEligible: tableReviewReady, tableReviewReady: tableReviewReady,\n        tableCount: completionTables.size(), unannotatedTableCount: unannotatedTableCount,\n        deferredTableCount: deferredTableCount, pendingDictionaryCount: pendingDictionaryCount,\n        pendingBusinessCount: pendingBusinessCount, pendingLogCount: pendingLogCount, issues: completionIssues\n    }\n    // dryRun 仅报告真实校验结果，不修改 MySQL / ES，也不伪装成已完成。\n    if (props.dryRun == true || body?.dryRun == true) {\n        completionReview.dryRun = true\n        completionReview.assetStatus = first(existed, [\'assetStatus\', \'asset_status\'])\n        return completionReview\n    }\n    if (!tableReviewReady) {\n        var reasons = []\n        if (completionTables.size() == 0) { reasons.add(\'尚未采集或登记数据表\') }\n        if (unannotatedTableCount > 0) { reasons.add(unannotatedTableCount + \' 张表未完成标注\') }\n        if (pendingDictionaryCount > 0) { reasons.add(pendingDictionaryCount + \' 张字典表未完成登记\') }\n        if (pendingBusinessCount > 0) { reasons.add(pendingBusinessCount + \' 张业务表未完成登记\') }\n        if (pendingLogCount > 0) { reasons.add(pendingLogCount + \' 张日志表未完成登记\') }\n        var samples = []\n        for (issue in completionIssues) {\n            if (samples.size() >= 3) { break }\n            samples.add(issue.tableName + \'：\' + issue.message)\n        }\n        exit 400, \'不能结束登记：\' + reasons.join(\'、\') + \'。\' + samples.join(\'；\') + \'。请返回对应步骤完善并保存。\'\n    }\n}\n// 第五步完成登记只落流程状态，不重写连接池配置，避免隐藏密码导致连接信息被清空。\nvar completionAssetStatus = 2\nif (props.completeOnly == true) {\n    db.table(\'db_datasource_t\').where().eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).update({\n        asset_status: completionAssetStatus,\n        flow_status: 2,\n        updated_time: nowTime\n    })\n    var completionIndexFields = {\n        assetStatus: completionAssetStatus,\n        flowStatus: 2,\n        updatedTime: nowTime,\n        updatedTime_date: nowTime\n    }\n    var indexSyncMode = \'status-patch\'\n    try {\n        var dataassetsExists = esCommonService.existsById(\'dataassets\', tid)\n        if (dataassetsExists) {\n            esCommonService.partialUpdateFieldsFast(\'dataassets\', tid, completionIndexFields)\n        } else {\n            body = { tid: tid, assetType: \'db\' }\n            refreshAssetIndex()\n            indexSyncMode = \'single-rebuild\'\n        }\n    } catch (e) {\n        log.warn(\'Datasource completion index sync failed; rebuilding one datasource: {}\', e.message)\n        body = { tid: tid, assetType: \'db\' }\n        try {\n            refreshAssetIndex()\n            indexSyncMode = \'single-rebuild\'\n        } catch (refreshError) {\n            log.warn(\'Datasource completion index rebuild failed: {}\', refreshError.message)\n            indexSyncMode = \'failed\'\n        }\n    }\n    return {\n        tid: tid,\n        assetStatus: completionAssetStatus,\n        displayStatus: completionAssetStatus,\n        completionEligible: true,\n        tableReviewReady: completionReview.tableReviewReady,\n        tableCount: completionReview.tableCount,\n        unannotatedTableCount: completionReview.unannotatedTableCount,\n        deferredTableCount: completionReview.deferredTableCount,\n        indexSync: indexSyncMode\n    }\n}\nvar sourceOrgId = first(props, [\'sourceOrgId\', \'source_org_id\', \'orgId\', \'org_id\'])\nvar preserveSourceOrgFlag = first(props, [\'departmentOnly\', \'department_only\'])\nvar preserveSourceOrg = props.preserveSourceOrg == true ||\n    (!blank(preserveSourceOrgFlag) && text(preserveSourceOrgFlag).toLowerCase() == \'true\')\nif (!blank(props.appId) && preserveSourceOrg != true) {\n    var application = db.table(\'sym_application_t\').where()\n        .eq(\'tid\', props.appId).eq(\'is_del\', 0).selectOne()\n    var applicationOrgId = first(application, [\'departId\', \'org_id\'])\n    if (!blank(applicationOrgId)) {\n        sourceOrgId = applicationOrgId\n    }\n}\n\nvar connectionNames = [\n    \'host\', \'port\', \'database\', \'username\', \'password\', \'jdbcURL\', \'schema\',\n    \'jdbcType\', \'serviceName\', \'sid\', \'currentSchema\', \'defaultSchema\',\n    \'authMode\', \'auth\', \'principal\', \'hivePrincipal\', \'servicePrincipal\', \'userPrincipal\', \'clientPrincipal\', \'hiveConnectionMode\',\n    \'keytabPath\', \'keytab\', \'userKeytab\', \'krb5ConfPath\', \'krb5Conf\', \'jaasConfPath\', \'jaasConfig\',\n    \'clientConfigDir\', \'mrsClientConfigDir\', \'zookeeperQuorum\', \'zkQuorum\', \'zookeeperNamespace\',\n    \'zooKeeperNamespace\', \'serviceDiscoveryMode\', \'serviceDiscovery\', \'saslQop\', \'sasl.qop\', \'ssl\',\n    \'driverPath\', \'driverClassName\', \'sslMode\', \'encrypt\', \'trustServerCertificate\',\n    \'dbMetaType\', \'dbMetaDbName\', \'dbMetaIp\', \'dbMetaPort\', \'dbMetaUser\', \'dbMetaPassword\',\n    \'dbIp\', \'dbPort\', \'dbUser\', \'dbPassword\', \'dbServerName\',\n    \'maxcomputeEndpoint\', \'maxcomputeProject\', \'maxcomputeAccessKeyId\',\n    \'maxcomputeAccessKeySecret\', \'maxcomputeTunnelEndpoint\',\n    \'minioEndpoint\', \'minioAccessKey\', \'minioSecretKey\', \'minioBucket\',\n    \'minioRegion\', \'minioUseSSL\', \'minioPrefix\', \'minioFilePattern\', \'minioSingleFile\',\n    \'ftpProtocol\', \'protocol\', \'ftpHost\', \'hostname\',\n    \'ftpPort\', \'ftpPath\', \'ftpUsername\', \'ftpPassword\', \'ftpPassiveMode\', \'sftpKnownHosts\',\n    \'ftpFilePattern\', \'ftpRecursive\', \'ftpSingleFile\', \'ftpCharset\', \'ftpDelimiter\',\n    \'apiMethod\', \'method\', \'apiUrl\', \'url\', \'apiAuthType\', \'apiUsername\', \'apiPassword\',\n    \'apiToken\', \'token\', \'authHeader\', \'authorization\', \'apiKeyName\', \'apiKeyValue\',\n    \'apiKeyPosition\', \'apiHeaders\', \'headers\', \'apiBody\', \'requestBody\', \'responseSample\',\n    \'apiTimeoutSeconds\', \'apiCollectionPaths\', \'apiPullItems\',\n    \'kafkaBootstrapServers\', \'bootstrapServers\', \'kafkaTopic\', \'topic\', \'kafkaGroupId\',\n    \'kafkaSecurityProtocol\', \'securityProtocol\', \'kafkaSaslMechanism\', \'saslMechanism\',\n    \'kafkaUsername\', \'saslUsername\', \'kafkaPassword\', \'saslPassword\', \'kafkaSchemaRegistryUrl\',\n    \'kafkaSampleSize\', \'kafkaPollTimeoutMs\',\n    \'nodes\'\n]\n// Existing values are the source of truth for fields not rendered in step one.\nvar old = db.table(\'db_datasource_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nvar oldConnectionConfig = old == null ? {} : datasourceConnectionConfig(\'read\', tid, null, false)\nvar oldShowConnect = old == null ? null : first(old, [\'showConnect\', \'show_connect\'])\nvar connectionConfig = {}\nvar connectionCount = 0\n// The registration page sends blank values for controls the user deliberately clears.\n// Preserve an omitted or hidden field, but let a blank value overwrite the selected\n// connector\'s own fields so stale pool_cfg values cannot reappear after a refresh.\nvar requestedConnectionType = blank(first(props, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\']))\n    ? \'\' : text(first(props, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])).trim().toLowerCase()\nif (requestedConnectionType == \'sftp\') {\n    requestedConnectionType = \'ftp\'\n}\nvar blankOverwriteNamesByType = {\n    minio: {\n        minioEndpoint: true, minioAccessKey: true, minioSecretKey: true,\n        minioBucket: true, minioRegion: true, minioUseSSL: true,\n        minioPrefix: true, minioFilePattern: true, minioSingleFile: true\n    },\n    ftp: {\n        ftpProtocol: true, ftpHost: true, ftpPort: true, ftpPath: true,\n        ftpUsername: true, ftpPassword: true, ftpPassiveMode: true,\n        ftpFilePattern: true, ftpRecursive: true, ftpSingleFile: true,\n        ftpCharset: true, ftpDelimiter: true\n    }\n}\nvar blankOverwriteNames = blankOverwriteNamesByType[requestedConnectionType] || {}\nfor (name in connectionNames) {\n    var value = props instanceof Map ? props.get(name) : props[name]\n    if (value != null && (!blank(value) || blankOverwriteNames[name] == true)) {\n        connectionConfig[name] = value\n        if (!blank(value)) {\n            connectionCount = connectionCount + 1\n        }\n    }\n}\nvar showConnect = 0\nif (text(props.showConnect) == \'0\') {\n    showConnect = 0\n} else if (connectionCount > 0) {\n    showConnect = 1\n} else if (old != null && text(oldShowConnect) == \'1\') {\n    showConnect = 1\n}\nif (showConnect == 0) {\n    connectionConfig = {}\n    connectionCount = 0\n}\n// 数据组织与协议专属字段保存到数据源主表的 pool_cfg；没有回传的隐藏凭据沿用已有配置。\n// 联系人是数据源的低频扩展信息，不再占用主表列；即使不提供连接也保留。\nif (props instanceof Map && props.containsKey(\'contactName\')) {\n    connectionConfig.contactName = props.contactName\n}\nif (props instanceof Map && props.containsKey(\'contactPhone\')) {\n    connectionConfig.contactPhone = props.contactPhone\n}\nvar dataSourceType = first(props, [\'dataSourceType\', \'data_source_type\'])\nif (!blank(dataSourceType)) {\n    connectionConfig.dataSourceType = text(dataSourceType)\n}\n// 接入方式是登记流程配置，不属于物理连接凭据。即使“不提供连接信息”，\n// 也必须写入 pool_cfg，供重新编辑和第五步审查摘要恢复正确方式。\nvar normalizeAccessMode = (value) => {\n    if (blank(value)) {\n        return null\n    }\n    var normalized = text(value).trim().toLowerCase()\n    var aliases = {\n        extract: \'explore\',\n        extraction: \'explore\',\n        push: \'receive\',\n        pull: \'capture\',\n        report: \'upload\'\n    }\n    if (aliases[normalized] != null) {\n        normalized = aliases[normalized]\n    }\n    var validModes = { explore: true, receive: true, capture: true, upload: true }\n    return validModes[normalized] == true ? normalized : null\n}\nvar accessMode = normalizeAccessMode(first(props, [\n    \'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\', \'registrationAccessMode\'\n]))\nif (blank(accessMode)) {\n    accessMode = normalizeAccessMode(first(oldConnectionConfig, [\n        \'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\', \'registrationAccessMode\'\n    ]))\n}\nif (!blank(accessMode)) {\n    connectionConfig.accessMode = accessMode\n}\n// 数据推送由平台提供统一接入通道，不依赖调用方填写物理库连接；将其明确记录为已提供，\n// 以便列表状态和登记确认页不会误显示为“未提供连接信息”。\nif (accessMode == \'receive\') {\n    showConnect = 1\n    connectionConfig.pushChannelProvided = true\n}\n// 数据推送能力声明是可选配置。提供了值时服务端复核枚举；未选择不阻断保存，\n// 且不会对 JDBC/FTP/Kafka 等其他接入方式写入该配置。\nvar receivePayloadSize = first(props, [\'receivePayloadSize\', \'receive_payload_size\'])\n// `receiveTimeliness` 是上一版字段。保留读取兼容，使已登记的数据源进入编辑页后\n// 可以自动转成“批量推送”；新保存只写 receivePushFrequency。\nvar receivePushFrequency = first(props, [\'receivePushFrequency\', \'receive_push_frequency\', \'receiveTimeliness\', \'receive_timeliness\'])\nvar receiveProfile = {}\nif (accessMode == \'receive\') {\n    var validReceivePayloadSizes = {\n        \'10B-100KB\': true,\n        \'100KB-10MB\': true,\n        \'10MB-1GB\': true\n    }\n    if (text(receivePushFrequency) == \'non-realtime\') {\n        receivePushFrequency = \'batch\'\n    }\n    var validReceivePushFrequencies = {\n        realtime: true,\n        batch: true\n    }\n    if (!blank(receivePayloadSize) && validReceivePayloadSizes[text(receivePayloadSize)] != true) {\n        exit 400, \'推送数据大小不正确，请选择 10B-100KB、100KB-10MB 或 10MB-1GB\'\n    }\n    if (!blank(receivePushFrequency) && validReceivePushFrequencies[text(receivePushFrequency)] != true) {\n        exit 400, \'推送数据频率不正确，请选择实时推送或批量推送\'\n    }\n    if (!blank(receivePayloadSize)) {\n        receiveProfile.receivePayloadSize = text(receivePayloadSize)\n        connectionConfig.receivePayloadSize = receiveProfile.receivePayloadSize\n    }\n    if (!blank(receivePushFrequency)) {\n        receiveProfile.receivePushFrequency = text(receivePushFrequency)\n        connectionConfig.receivePushFrequency = receiveProfile.receivePushFrequency\n    }\n}\nvar dbName = blank(props.dbName) ? props.database : props.dbName\n\nvar dbTypeCode = (value) => {\n    var code = blank(value) ? \'\' : text(value).toLowerCase()\n    var values = {\n        mysql: 1, mariadb: 1, \'tdsql-mysql\': 1, oracle: 2, postgresql: 3,\n        \'tdsql-pg\': 3, highgo: 3, sqlserver: 4, hive: 5, gaussdb: 6,\n        gbase8a: 7, dameng: 8, dm: 8, kingbase8: 9, kingbase: 9, vertica: 10,\n        oceanbasemysql: 11, oceanbaseoracle: 12, oceanbase: 13, db2: 14,\n        clickhouse: 15, gbase8s: 16, oscar: 17, maxcompute: 20, minio: 21,\n        ftp: 22, sftp: 22, api: 23, kafka: 24, elasticsearch: 25\n    }\n    return values[code] == null ? 0 : values[code]\n}\nvar inferDbType = (value, jdbcUrl) => {\n    var raw = blank(value) ? \'\' : text(value).toLowerCase()\n    if (!blank(raw)) {\n        return raw\n    }\n    var url = blank(jdbcUrl) ? \'\' : text(jdbcUrl).toLowerCase()\n    if (url.indexOf(\':oracle:\') >= 0) {\n        return \'oracle\'\n    }\n    if (url.indexOf(\':mysql:\') >= 0) {\n        return \'mysql\'\n    }\n    if (url.indexOf(\':postgresql:\') >= 0) {\n        return \'postgresql\'\n    }\n    if (url.indexOf(\':dm:\') >= 0) {\n        return \'dameng\'\n    }\n    if (url.indexOf(\':kingbase\') >= 0) {\n        return \'kingbase8\'\n    }\n    if (url.indexOf(\':sqlserver:\') >= 0) {\n        return \'sqlserver\'\n    }\n    return null\n}\n\n// 租户仅来自当前已认证请求的服务端上下文：TenantWebInterceptor 会先将\n// Sa-Token 会话中的 tenantId 绑定到 TenantContext。绝不采纳请求体或旧记录，\n// 以免跨租户写入或在编辑历史数据时掩盖会话异常。\nif (blank(tenantId)) {\n    exit 400, \'无法识别当前租户，请重新登录后再保存数据源\'\n}\n// 详情页“是否已注册”直接绑定 db_datasource_t.asset_status：0 待注册、1 审核中、2 已注册。\n// 审核中只作为既有状态展示，人工编辑只允许在 0 和 2 之间切换。\nvar explicitAssetStatus = first(props, [\'assetStatus\', \'asset_status\'])\nvar explicitAssetStatusText = blank(explicitAssetStatus) ? \'\' : text(explicitAssetStatus)\nvar oldAssetStatus = old == null ? null : first(old, [\'assetStatus\', \'asset_status\'])\nvar oldConnectionStatus = old == null ? null : first(old, [\'connectionStatus\', \'connection_status\'])\n// 仅登记页测试连接生成的有效状态可以覆盖历史状态；未测试的普通保存仍保留未知。\n// 页面仅在服务端连通性检测返回后提交 success 或 failed，避免将任意文本写成状态。\nvar incomingConnectionStatus = text(first(props, [\'connectionStatus\', \'connection_status\']))\nvar normalizedIncomingConnectionStatus = blank(incomingConnectionStatus) ? \'\' : incomingConnectionStatus.trim().toLowerCase()\nvar connectionStatus = oldConnectionStatus\nif (accessMode == \'receive\') {\n    // 推送端点由平台统一提供，登记保存即代表该接入通道已就绪。\n    connectionStatus = \'success\'\n} else if (showConnect == 0) {\n    connectionStatus = \'unprovided\'\n} else if ([\'success\', \'connected\', \'ok\', \'true\', \'1\'].contains(normalizedIncomingConnectionStatus)) {\n    connectionStatus = \'success\'\n} else if ([\'failed\', \'fail\', \'error\', \'false\', \'0\'].contains(normalizedIncomingConnectionStatus)) {\n    connectionStatus = \'failed\'\n} else if (blank(connectionStatus)) {\n    connectionStatus = \'unknown\'\n}\nvar oldFlowStatus = old == null ? null : first(old, [\'flowStatus\', \'flow_status\'])\nvar dbType = inferDbType(first(props, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\']), first(props, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\nif (blank(dbType) && old != null) {\n    dbType = inferDbType(first(old, [\'dbType\', \'db_type\']), first(old, [\'jdbcUrl\', \'jdbc_url\']))\n}\n// 华为 MRS Hive 的元数据仅由服务端 hwhive 模块访问。登记时只持久化模式标记，\n// 供登记后续步骤和 NiFi 重新加载当前租户的数据源，不信任浏览器提交的 JDBC/Kerberos 参数。\nvar hiveConnectionMode = first(props, [\'hiveConnectionMode\', \'hive_connection_mode\'])\nif (blank(hiveConnectionMode)) {\n    hiveConnectionMode = first(oldConnectionConfig, [\'hiveConnectionMode\', \'hive_connection_mode\'])\n}\nvar isServerManagedHuaweiMrs = (blank(dbType) ? \'\' : text(dbType)).trim().toLowerCase() == \'hive\' &&\n    (blank(hiveConnectionMode) ? \'\' : text(hiveConnectionMode)).trim().toLowerCase() == \'huawei-mrs\'\nif (isServerManagedHuaweiMrs) {\n    connectionConfig.hiveConnectionMode = \'huawei-mrs\'\n    connectionConfig.metadataAccessMode = \'server-managed-mrs\'\n} else if (!blank(hiveConnectionMode)) {\n    connectionConfig.hiveConnectionMode = text(hiveConnectionMode).trim()\n    connectionConfig.metadataAccessMode = \'jdbc\'\n}var assetStatus = oldAssetStatus == null ? 0 : oldAssetStatus\nvar flowStatus = oldFlowStatus == null ? 0 : oldFlowStatus\nvar changedWhenProvided = (oldValue, inputValue) => !blank(inputValue) && text(oldValue) != text(inputValue)\n// 连接属性由键值记录承载；隐藏凭据和未展示字段不参与重置判断。\n// connector fields otherwise turn an unchanged edit into a false re-registration.\nvar connectionChanged = old != null && (\n    changedWhenProvided(inferDbType(first(old, [\'dbType\', \'db_type\']), first(old, [\'jdbcUrl\', \'jdbc_url\'])), dbType) ||\n    changedWhenProvided(first(old, [\'jdbcUrl\', \'jdbc_url\']), first(props, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'])) ||\n    (text(props.showConnect) == \'0\' && text(oldShowConnect) == \'1\')\n)\nif (connectionChanged && text(oldAssetStatus) == \'2\' && explicitAssetStatusText != \'2\') {\n    assetStatus = 0\n    flowStatus = 0\n}\n// 资产状态是“是否已注册”的唯一来源；登记页首次保存不自动完成第五步。\nif (explicitAssetStatusText == \'0\') {\n    assetStatus = 0\n    flowStatus = 0\n} else if (explicitAssetStatusText == \'2\') {\n    assetStatus = 2\n    flowStatus = 2\n}\n\n// node_id 只保存 sym_dict_t 中 nodeType 子项的 tid；兼容旧入参误传中文/编码时自动归一为字典 ID。\nvar resolveNodeTypeId = (value) => {\n    if (blank(value)) {\n        return null\n    }\n    var raw = text(value).trim()\n    var root = db.table(\'sym_dict_t\').where().eq(\'dict_code\', \'nodeType\').eq(\'is_del\', 0).selectOne()\n    var parentId = root == null ? null : root.tid\n    var existed = db.table(\'sym_dict_t\').where().eq(\'tid\', raw).eq(\'is_del\', 0).selectOne()\n    if (existed != null && (blank(parentId) || first(existed, [\'parentId\', \'parent_id\']) == parentId)) {\n        return raw\n    }\n    if (!blank(parentId)) {\n        var byName = db.table(\'sym_dict_t\').where().eq(\'parent_id\', parentId).eq(\'dict_name\', raw).eq(\'is_del\', 0).selectOne()\n        if (byName != null) {\n            return byName.tid\n        }\n        var byCode = db.table(\'sym_dict_t\').where().eq(\'parent_id\', parentId).eq(\'dict_code\', raw).eq(\'is_del\', 0).selectOne()\n        if (byCode != null) {\n            return byCode.tid\n        }\n    }\n    return raw\n}\n\nvar storageDomain = first(props, [\'storageDomain\', \'storage_domain\', \'SSWL\', \'networkDomain\', \'network_domain\'])\nvar nodeId = resolveNodeTypeId(first(props, [\'nodeId\', \'node_id\']))\nvar valueOrOld = (value, keys) => blank(value) && old != null ? first(old, keys) : value\nvar mainJdbcUrl = valueOrOld(first(props, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']), [\'jdbcUrl\', \'jdbc_url\'])\nvar mainUsername = valueOrOld(props.username, [\'username\'])\nvar mainPassword = valueOrOld(props.password, [\'password\'])\n\nvar main = {\n    tid: tid,\n    db_name: dbName,\n    database_type: dbTypeCode(dbType),\n    db_type: dbType,\n    driver_class_name: showConnect == 1 ? valueOrOld(props.driverClassName, [\'driverClassName\', \'driver_class_name\']) : null,\n    jdbc_url: showConnect == 1 ? mainJdbcUrl : null,\n    username: showConnect == 1 ? mainUsername : null,\n    password: showConnect == 1 ? mainPassword : null,\n    remark: valueOrOld(props.assetDesc, [\'remark\']),\n    is_enable: old == null ? 1 : valueOrOld(props.isEnable, [\'isEnable\', \'is_enable\']),\n    app_id: valueOrOld(props.appId, [\'appId\', \'app_id\']),\n    // 数据源部门归属在创建时确定。编辑人、表单回填值和所属应用的事权单位\n    // 都不能覆盖已有记录的 org_id，否则部门范围与创建归属会被错误改写。\n    org_id: old == null\n        ? valueOrOld(sourceOrgId, [\'orgId\', \'org_id\'])\n        : first(old, [\'orgId\', \'org_id\']),\n    storage_domain: valueOrOld(storageDomain, [\'storageDomain\', \'storage_domain\']),\n    node_id: valueOrOld(nodeId, [\'nodeId\', \'node_id\']),\n    db_version: valueOrOld(props.dbVersion, [\'dbVersion\', \'db_version\']),\n    user_count: valueOrOld(props.userCount, [\'userCount\', \'user_count\']),\n    view_count: valueOrOld(props.viewCount, [\'viewCount\', \'view_count\']),\n    procedure_count: valueOrOld(props.procedureCount, [\'procedureCount\', \'procedure_count\']),\n    data_size: valueOrOld(props.dataSize, [\'dataSize\', \'data_size\']),\n    total_size: valueOrOld(props.totalSize, [\'totalSize\', \'total_size\']),\n    show_connect: showConnect,\n    connection_status: connectionStatus,\n    tenant_id: tenantId,\n    table_num: valueOrOld(props.tableCount, [\'tableCount\', \'tableNum\', \'table_num\']),\n    asset_status: assetStatus,\n    flow_status: flowStatus,\n    flow_order_id: old == null ? null : first(old, [\'flowOrderId\', \'flow_order_id\']),\n    is_del: 0,\n    updated_time: nowTime,\n    reg_time: old == null ? nowTime : first(old, [\'regTime\', \'reg_time\'])\n}\nif (old == null) {\n    main.created_time = nowTime\n    db.table(\'db_datasource_t\').primary(\'tid\').insert(main)\n} else {\n    db.table(\'db_datasource_t\').primary(\'tid\').update(main, true)\n}\n\n// 数据组织、密码、令牌及协议专属参数都由数据源主表 pool_cfg JSON 统一承载。\n// 局部编辑没有回传的字段不会被覆盖；明确关闭连接时才会清空连接配置。\n// 接入方式是无连接登记也需要保留的业务配置，清空连接后单独写回它。\nif (showConnect == 0) {\n    datasourceConnectionConfig(\'save\', tid, {}, true)\n    var registrationConfig = {}\n    if (!blank(accessMode)) {\n        registrationConfig.accessMode = accessMode\n    }\n    if (accessMode == \'receive\') {\n        if (!blank(receiveProfile.receivePayloadSize)) {\n            registrationConfig.receivePayloadSize = receiveProfile.receivePayloadSize\n        }\n        if (!blank(receiveProfile.receivePushFrequency)) {\n            registrationConfig.receivePushFrequency = receiveProfile.receivePushFrequency\n        }\n    }\n    if (!blank(accessMode)) {\n        datasourceConnectionConfig(\'save\', tid, registrationConfig, false)\n    }\n} else {\n    datasourceConnectionConfig(\'save\', tid, connectionConfig, false)\n}\n\nvar savedTid = tid\n// ES 是查询投影而非主数据。编辑页可要求把索引重建放到成功返回后执行，避免\n// 网络超时将已持久化的数据源保存操作卡在等待状态。\nvar deferIndexRefresh = body != null && (body.deferIndexRefresh == true || body.deferIndexRefresh == 1 || body.deferIndexRefresh == \'1\')\nif (deferIndexRefresh) {\n    return { tid: savedTid, indexRefreshPending: true }\n}\nbody = { tid: savedTid }\ntry {\n    refreshAssetIndex()\n} catch (e) {\n    // 主数据已经提交；ES 为投影索引，连接故障不能回滚或阻断数据源保存。\n    log.warn(\'刷新数据源搜索索引失败，稍后可通过盘点维护重试: {}\', e.message)\n}\nreturn { tid: savedTid, indexRefreshPending: false }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/04.保存数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_database_delete_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_database_delete_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "05.删除数据源",\n  "createTime": null,\n  "updateTime": 1787153758635,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2086644303757058048\\",\\n  \\"dryRun\\": true\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"deleted\\": false,\\n  \\"dryRun\\": true\\n}",\n  "description": "删除以租户业务库为事实来源：先软删除数据源及其当前租户内的关联记录，；使用请求参数 tid、dryRun；涉及 db_datasource_t、db_table_t、da_catalog_t、db_table_column_t、data_access_agg_task_t、data_access_field_mapping 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.删除数据源\n// 路由：POST /dst/database/delete\n// 业务说明：删除以租户业务库为事实来源：先软删除数据源及其当前租户内的关联记录，；使用请求参数 tid、dryRun；涉及 db_datasource_t、db_table_t、da_catalog_t、db_table_column_t、data_access_agg_task_t、data_access_field_mapping 等业务表。\n/*\n * 删除数据源。\n *\n * 删除以租户业务库为事实来源：先软删除数据源及其当前租户内的关联记录，\n * 再清理当前租户 Elasticsearch 投影。重复删除仍会执行投影清理，避免\n * “数据库已经删除、列表中的 ES 卡片仍然存在”而无法自愈。\n */\nimport tenantRuntime\nimport tenantEs\nimport \'@/common/configData\' as configData\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar addUnique = (rows, value) => {\n    var normalized = text(value)\n    if (normalized != \'\' && !rows.contains(normalized)) {\n        rows.add(normalized)\n    }\n}\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]) != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\n\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') {\n    exit 401, \'无法识别当前租户\'\n}\n\nvar tid = body == null ? null : body.tid\nif (text(tid) == \'\') {\n    exit 400, \'tid is required\'\n}\ntid = text(tid)\nvar dryRun = body != null && (body.dryRun == true || body.dryRun == 1 || body.dryRun == \'1\')\n\nvar datasourceRow = db.table(\'db_datasource_t\').where()\n    .eq(\'tid\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .selectOne()\nvar datasource = db.table(\'db_datasource_t\').where()\n    .eq(\'tid\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nvar tableRows = db.table(\'db_table_t\').where()\n    .eq(\'datasource_id\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .select()\nvar activeTableRows = db.table(\'db_table_t\').where()\n    .eq(\'datasource_id\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .select()\nvar tableIds = []\nvar catalogIds = []\nfor (tableRow in tableRows) {\n    addUnique(tableIds, rowValue(tableRow, [\'tid\']))\n    addUnique(catalogIds, rowValue(tableRow, [\'sourceCatalogId\', \'source_catalog_id\']))\n}\n\nfor (catalog in db.table(\'da_catalog_t\').where()\n    .eq(\'db_id\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .select()) {\n    addUnique(catalogIds, rowValue(catalog, [\'tid\']))\n}\nif (tableIds.size() > 0) {\n    for (catalog in db.table(\'da_catalog_t\').where()\n        .in(\'source_table_id\', tableIds)\n        .eq(\'tenant_id\', tenantId)\n        .select()) {\n        addUnique(catalogIds, rowValue(catalog, [\'tid\']))\n    }\n}\n\nvar columnCount = tableIds.size() == 0 ? 0 : db.table(\'db_table_column_t\').where()\n    .in(\'table_id\', tableIds)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .count()\n\nvar taskIds = []\nvar pipelineIds = []\nvar collectTasks = rows => {\n    for (task in rows) {\n        addUnique(taskIds, rowValue(task, [\'tid\']))\n        addUnique(pipelineIds, rowValue(task, [\'pipelineId\', \'pipeline_id\']))\n    }\n}\ncollectTasks(db.table(\'data_access_agg_task_t\').where()\n    .eq(\'source_db_id\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .select())\ncollectTasks(db.table(\'data_access_agg_task_t\').where()\n    .eq(\'target_db_id\', tid)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .select())\nif (tableIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where()\n        .in(\'source_table_id\', tableIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .select())\n    collectTasks(db.table(\'data_access_agg_task_t\').where()\n        .in(\'target_table_id\', tableIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .select())\n}\nif (catalogIds.size() > 0) {\n    collectTasks(db.table(\'data_access_agg_task_t\').where()\n        .in(\'data_catalog_id\', catalogIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .select())\n}\n\nvar cleanup = {\n    tables: activeTableRows.size(),\n    columns: columnCount,\n    catalogs: catalogIds.size(),\n    tasks: taskIds.size()\n}\nif (dryRun) {\n    return {\n        deleted: false,\n        dryRun: true,\n        exists: datasourceRow != null,\n        alreadyDeleted: datasource == null,\n        dbName: rowValue(datasourceRow, [\'dbName\', \'db_name\']),\n        cleanup: cleanup\n    }\n}\n\nvar nowTime = new Date()\nif (taskIds.size() > 0) {\n    db.table(\'data_access_field_mapping\').where()\n        .in(\'task_id\', taskIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    db.table(\'data_access_task_monitor_snap_t\').where()\n        .in(\'task_id\', taskIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1 })\n    db.table(\'data_access_agg_task_t\').where()\n        .in(\'tid\', taskIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, task_status: 0, updated_time: nowTime })\n}\nif (pipelineIds.size() > 0) {\n    db.table(\'nifi_pipeline_t\').where()\n        .in(\'id\', pipelineIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_at: System.currentTimeMillis() })\n}\nif (tableIds.size() > 0) {\n    db.table(\'db_table_column_t\').where()\n        .in(\'table_id\', tableIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    db.table(\'db_table_t\').where()\n        .in(\'tid\', tableIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n}\nif (catalogIds.size() > 0) {\n    db.table(\'da_catalog_item_t\').where()\n        .in(\'catalog_id\', catalogIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    db.table(\'da_prop_t\').where()\n        .in(\'parent_id\', catalogIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n    db.table(\'da_catalog_t\').where()\n        .in(\'tid\', catalogIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: nowTime })\n}\n\nvar changed = 0\nif (datasource != null) {\n    changed = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', tid)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, is_enable: 0, updated_time: nowTime })\n}\n\n// 必须清理 tenantEs 的物理租户索引。即使主记录早已软删除，也继续执行，\n// 让历史残留投影可通过再次点击删除自动修复。\nvar projectionFailures = []\nvar projectionMisses = 0\nvar projectionIds = []\naddUnique(projectionIds, tid)\nfor (tableId in tableIds) {\n    addUnique(projectionIds, tableId)\n}\nfor (catalogId in catalogIds) {\n    addUnique(projectionIds, catalogId)\n}\nvar dataassetsIndex = tenantEs.index(configData().es_dataassets)\nfor (assetId in projectionIds) {\n    try {\n        dataassetsIndex.delete(assetId)\n    } catch (e) {\n        var projectionError = text(e.message)\n        // ES 把删除不存在的文档返回为 404；幂等删除中这是正常结果，不应当作为失败。\n        if (projectionError.contains(\'404 Not Found\') || projectionError.contains(\'"result":"not_found"\')) {\n            projectionMisses = projectionMisses + 1\n        } else {\n            projectionFailures.add({ assetId: assetId, error: e.message })\n        }\n    }\n}\n\nreturn {\n    deleted: changed > 0,\n    alreadyDeleted: datasource == null,\n    dryRun: false,\n    cleanup: cleanup,\n    projectionMisses: projectionMisses,\n    projectionFailures: projectionFailures\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/05.删除数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_dept_datasources_01',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "datapd_dept_datasources_01",\r\n  "script" : null,\r\n  "groupId" : "datapd_database_group_01",\r\n  "name" : "06.本部门数据源清单",\r\n  "createTime" : null,\r\n  "updateTime" : 1791109965040,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/departmentDataSources",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"mode\\":\\"summary\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "",\r\n  "description" : "本部门数据源管理：mode=summary 返回轻量概要与批量统计；mode=tables 按 datasourceId 分页读取已登记表。当前租户及菜单数据权限校验；默认模式兼容历史调用者；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 db_datasource_t、db_table_t、sym_application_t、rm_org_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：06.本部门数据源清单\n// 路由：POST /dst/database/departmentDataSources\n// 业务说明：本部门数据源管理：mode=summary 返回轻量概要与批量统计；mode=tables 按 datasourceId 分页读取已登记表；mode=reportTables 批量分页读取可见上报数据源的业务表和日志表。当前租户及菜单数据权限校验；默认模式兼容历史调用者；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 db_datasource_t、db_table_t、sym_application_t、rm_org_t 等业务表。\nimport "@post:/sym/user/me" as me\nimport tenantRuntime\nimport tenantEs\nimport dataScope\nimport tenantAccounts\nimport \'@/common/configData\' as configData\n\n/*\n * 本部门数据源管理接口。\n * 数据读取：优先 Elasticsearch dataassets 索引；ES 数据源或表投影缺失时批量回退 db_datasource_t/db_table_t，禁止列表循环回查 MySQL。\n * 安全边界：不信任前端 orgId，始终使用当前会话 /sym/user/me 的部门过滤数据源。\n * mode=summary：数据源概要、MySQL 批量统计、ES size=0 变更聚合；mode=tables：权限校验后分页读取已登记表。\n * 默认模式兼容历史调用者；只读，不连接外部来源库、不采集字段。\n */\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar numberValue = (value) => value == null ? 0 : value::int\n\n// CODEX_ACTIVE_DATASOURCE_GUARD: 以当前租户业务库的有效记录过滤 ES 残留投影。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'无法识别当前租户\'\n}\n\nvar userInfo = me()\nvar orgId = userInfo?.orgId\nvar scopeResource = \'MENU:2081000000000000002\'\n\nvar requestMode = text(body?.mode).trim()\nif (!blank(requestMode) && ![\'summary\', \'tables\', \'reportTables\'].contains(requestMode)) { exit 400, \'不支持的清单查询模式\' }\nif (requestMode == \'reportTables\') {\n    // 一页报告的表跨数据源批量读取；前端不得对每个数据源再发一次表查询。\n    var submittedIds = body?.datasourceIds\n    if (!(submittedIds instanceof List) || submittedIds.size() == 0 || submittedIds.size() > 200) {\n        exit 400, \'数据源标识必须是 1 至 200 项的数组\'\n    }\n    var requestedIds = []\n    for (rawId in submittedIds) {\n        var sourceId = text(rawId).trim()\n        if (blank(sourceId) || sourceId.length() > 32) { exit 400, \'数据源标识不合法\' }\n        if (!requestedIds.contains(sourceId)) { requestedIds.add(sourceId) }\n    }\n    // 先按租户过滤主表，再应用当前菜单的角色数据范围，任何越权项使整批失败。\n    var allowedSources = db.select("""\n        select tid, org_id, created_by,\n               coalesce(\n                   nullif(json_unquote(json_extract(if(json_valid(pool_cfg), pool_cfg, \'{}\'), \'$.accessMode\')), \'\'),\n                   nullif(json_unquote(json_extract(if(json_valid(pool_cfg), pool_cfg, \'{}\'), \'$.dataAccessMode\')), \'\'),\n                   \'\'\n               ) as accessMode\n          from db_datasource_t\n         where tenant_id=#{tenantId} and is_del=0 and tid in\n               <foreach collection="requestedIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n    """)\n    allowedSources = dataScope.visibleDataSourcesFor(scopeResource, allowedSources)\n    if (allowedSources == null || allowedSources.size() != requestedIds.size()) {\n        exit 403, \'数据源不存在或无权访问\'\n    }\n    var allowedIds = []\n    for (source in allowedSources) {\n        var accessMode = text(source.accessmode || source.accessMode).trim().toLowerCase()\n        if (accessMode != \'upload\') { exit 403, \'数据源不是数据上报方式\' }\n        allowedIds.add(text(source.tid))\n    }\n    var reportPageNum = body?.pageNum == null ? 1 : body.pageNum::int\n    var reportPageSize = body?.pageSize == null ? 100 : body.pageSize::int\n    if (reportPageNum < 1) { reportPageNum = 1 }\n    if (reportPageSize < 1) { reportPageSize = 100 }\n    if (reportPageSize > 100) { reportPageSize = 100 }\n    // 与单源元数据表接口保持相同去重优先级：同名先取已标注，再取最近更新。\n    // 过滤业务类型置于去重之后，不能让较旧的同名业务表重新进入结果。\n    var reportSql = """\n        select ranked.tid, ranked.datasource_id, ranked.table_name, ranked.table_name_cn,\n               ranked.table_comment, ranked.table_type, ranked.business_type,\n               ranked.field_count, ranked.record_count, ranked.timestamp_field,\n               ranked.updated_time\n          from (\n            select t.tid, t.datasource_id, t.table_name, t.table_name_cn,\n                   t.table_comment, t.table_type, t.business_type, t.annotated,\n                   t.field_count, t.record_count, t.timestamp_field, t.updated_time,\n                   row_number() over (\n                       partition by t.datasource_id, lower(t.table_name)\n                       order by coalesce(t.annotated, 0) desc, t.updated_time desc, t.tid desc\n                   ) as name_rank\n              from db_table_t t\n             where t.tenant_id=#{tenantId} and t.is_del=0\n               and t.datasource_id in\n                   <foreach collection="allowedIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n          ) ranked\n         where ranked.name_rank=1 and ranked.annotated=1\n           and ranked.business_type in (\'业务表\', \'日志表\')\n         order by ranked.updated_time desc, ranked.tid desc\n    """\n    var reportPage = db.page(reportSql, reportPageSize, (reportPageNum - 1) * reportPageSize)\n    var reportRows = []\n    for (row in (reportPage.list == null ? [] : reportPage.list)) {\n        reportRows.add({\n            tid: row.tid, datasourceId: row.datasourceId,\n            tableName: row.tableName, tableNameCn: row.tableNameCn,\n            tableComment: row.tableComment, tableType: row.tableType,\n            businessType: row.businessType, fieldCount: numberValue(row.fieldCount),\n            recordCount: numberValue(row.recordCount), timestampField: row.timestampField,\n            businessTimeField: \'\', updatedTime: row.updatedTime\n        })\n    }\n    return { pageNum: reportPageNum, pageSize: reportPageSize,\n        total: numberValue(reportPage.total), list: reportRows }\n}\nif (requestMode == \'tables\') {\n    var datasourceId = text(body?.datasourceId).trim()\n    if (blank(datasourceId)) { exit 400, \'缺少数据源标识\' }\n    var sourceRows = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n    sourceRows = dataScope.visibleDataSourcesFor(scopeResource, sourceRows)\n    if (sourceRows == null || sourceRows.size() == 0) { exit 404, \'数据源不存在或无权访问\' }\n    var pageNum = body?.pageNum == null ? 1 : body.pageNum::int\n    var pageSize = body?.pageSize == null ? 10 : body.pageSize::int\n    if (pageNum < 1) { pageNum = 1 }\n    if (pageSize < 1) { pageSize = 10 }\n    if (pageSize > 100) { pageSize = 100 }\n    var escapedSourceId = datasourceId.replace("\'", "\'\'")\n    var escapedPageTenant = tenantId.replace("\'", "\'\'")\n    var pageWhere = " datasource_id = \'" + escapedSourceId + "\' and tenant_id = \'" + escapedPageTenant\n        + "\' and ifnull(is_del, 0) = 0 and asset_status = 2"\n        + " and lower(ifnull(business_type, \'\')) not in (\'暂不处理\', \'暂不登记\', \'不确定\', \'deferred\')"\n    var totalRows = db.select("select count(1) as total from db_table_t where " + pageWhere)\n    var total = numberValue(totalRows[0].total)\n    var maxPage = total == 0 ? 1 : ((total + pageSize - 1) / pageSize)::int\n    if (pageNum > maxPage) { pageNum = maxPage }\n    var offset = (pageNum - 1) * pageSize\n    // 仅返回当前页的展示字段，不读取连接信息、字段快照或治理 JSON。\n    var pageRows = db.select("""\n        select tid, datasource_id as datasourceId, table_name as tableName,\n               table_name_en as tableNameEn, table_name_cn as tableNameCn,\n               table_comment as tableComment, table_type as tableType,\n               business_type as businessType, field_count as fieldCount,\n               asset_status as assetStatus, created_time as createdTime, updated_time as updatedTime\n          from db_table_t where ${pageWhere}\n         order by created_time desc, updated_time desc, table_name asc, tid asc\n         limit ${offset}, ${pageSize}\n    """)\n    var pageList = []\n    for (row in pageRows) {\n        pageList.add({ tid: row.tid, id: row.tid, datasourceId: row.datasourceid,\n            dbId: row.datasourceid, tableName: row.tablename || row.tablenameen,\n            tableNameCn: row.tablenamecn || row.tablecomment, tableComment: row.tablecomment,\n            tableType: row.tabletype, businessType: row.businesstype, fieldCount: row.fieldcount,\n            assetStatus: row.assetstatus, createdTime: row.createdtime, updatedTime: row.updatedtime })\n    }\n    // 只为当前页补齐显式变更标签，禁止下载数据源下所有表文档。\n    var pageIds = []\n    for (item in pageList) { pageIds.add(text(item.tid)) }\n    if (pageIds.size() > 0) {\n        var pageChanges = tenantEs.index(configData().es_dataassets).search({\n            size: pageSize, _source: [\'tid\', \'changeStatus\', \'change_status\'],\n            query: { bool: { must: [\n                { term: { assetType: \'table\' } }, { ids: { values: pageIds } }\n            ] } }\n        })\n        var changeById = {}\n        for (hit in (pageChanges?.hits?.hits == null ? [] : pageChanges.hits.hits)) {\n            changeById[text(hit?._source?.tid || hit._id)] = text(hit?._source?.changeStatus || hit?._source?.change_status).toLowerCase()\n        }\n        for (item in pageList) { item.changeStatus = changeById[text(item.tid)] || \'unchanged\' }\n    }\n    return { datasourceId: datasourceId, pageNum: pageNum, pageSize: pageSize, total: total, list: pageList }\n}\nvar summaryOnly = requestMode == \'summary\'\n\n\n// 页面只提供关键字搜索；最终范围由“数据源管理”菜单的角色数据权限统一过滤。\nvar keywordText = text(body?.keyword).trim()\nvar datasourceMust = [\n    { term: { assetType: \'db\' } }\n]\nif (!blank(keywordText)) {\n    // 关键字也在 ES 过滤，前端不能借搜索绕过部门权限。\n    datasourceMust.add({\n        bool: {\n            should: [\n                { wildcard: { dbName: \'*\' + keywordText + \'*\' } },\n                { wildcard: { appName: \'*\' + keywordText + \'*\' } },\n                { wildcard: { database: \'*\' + keywordText + \'*\' } },\n                { wildcard: { dbType: \'*\' + keywordText + \'*\' } }\n            ],\n            minimum_should_match: 1\n        }\n    })\n}\n\n// ES 仅作为候选投影；全部 / 本部门 / 本人范围在主表过滤阶段统一裁剪。\nvar datasourceSearch = tenantEs.index(configData().es_dataassets).search({\n    _source: summaryOnly ? [\'tid\', \'id\', \'dbName\', \'appId\', \'appName\', \'dbType\', \'databaseType\',\n        \'database\', \'schema\', \'host\', \'port\', \'accessMode\', \'dataAccessMode\', \'orgId\', \'orgName\',\n        \'tableNum\', \'assetStatus\', \'showConnect\', \'connectionStatus\', \'description\',\n        \'createdTime\', \'updatedTime\', \'createdBy\', \'storageDomain\', \'nodeId\'] : true,\n    size: 1000,\n    track_total_hits: true,\n    query: {\n        bool: {\n            must: datasourceMust,\n            must_not: [\n                { wildcard: { dbName: \'codex_*\' } },\n                { wildcard: { database: \'codex_*\' } }\n            ]\n        }\n    },\n    sort: [ { updatedTime: { order: \'desc\', unmapped_type: \'keyword\' } } ]\n})\n\nvar result = []\nvar resultById = {}\nvar datasourceIds = []\nfor (hit in (datasourceSearch?.hits?.hits == null ? [] : datasourceSearch.hits.hits)) {\n    if (hit?._source == null) {\n        continue\n    }\n    var item = hit._source\n    item.tid = item.tid || hit._id\n    item.id = item.id || item.tid\n    item.orgName = userInfo?.orgName\n    // 数据源 ES 投影里可能已经有最近一次探查得到的物理总表数。\n    // 这个总数和 db_table_t 已保存行数不是同一个口径，不能在后续统计时被清零丢掉。\n    item.exploredTableNum = numberValue(item.tableNum || item.table_num || item.tableCount || item.table_count)\n    item.tableNum = 0\n    item.annotatedTableNum = 0\n    item.unannotatedTableNum = 0\n    item.registeredTableNum = 0\n    item.unregisteredTableNum = 0\n    item.businessTableNum = 0\n    item.dictionaryTableNum = 0\n    item.logTableNum = 0\n    item.coreTableNum = 0\n    item.registeredCoreTableNum = 0\n    item.deferredTableNum = 0\n    item.issueTableNum = 0\n    item.problemTableNum = 0\n    item.changedTableNum = 0\n    item.addedTableNum = 0\n    item.modifiedTableNum = 0\n    item.deletedTableNum = 0\n    item.tables = []\n    datasourceIds.add(item.tid)\n    resultById[text(item.tid)] = true\n    result.add(item)\n}\n\n// ES 数据源主投影可能存在刷新延迟。按当前租户批量回表补齐主卡片，\n// 并由菜单级角色范围过滤，避免前端参数扩大可见范围。\nvar escapedTenantId = tenantId.replace("\'", "\'\'")\nvar keywordSql = ""\nif (!blank(keywordText)) {\n    var escapedKeyword = keywordText.replace("\'", "\'\'")\n    keywordSql = " and (d.db_name like \'%" + escapedKeyword + "%\' or ifnull(a.app_name, \'\') like \'%" + escapedKeyword + "%\' or ifnull(d.db_type, \'\') like \'%" + escapedKeyword + "%\')"\n}\nvar activeDatasourceById = {}\nvar datasourceRows = db.select("""\n    select d.tid,\n           d.db_name as dbName,\n           d.remark as description,\n           d.app_id as appId,\n           a.app_name as appName,\n           d.db_type as dbType,\n           d.database_type as databaseType,\n           coalesce(\n             nullif(json_unquote(json_extract(if(json_valid(d.pool_cfg), d.pool_cfg, \'{}\'), \'$.accessMode\')), \'\'),\n             nullif(json_unquote(json_extract(if(json_valid(d.pool_cfg), d.pool_cfg, \'{}\'), \'$.dataAccessMode\')), \'\'),\n             \'\'\n           ) as accessMode,\n           d.org_id as orgId,\n           d.created_by as createdBy,\n           o.name as orgName,\n           o.org_path as orgPath,\n           ifnull(d.table_num, 0) as exploredTableNum,\n           d.asset_status as assetStatus,\n           d.show_connect as showConnect,\n           d.connection_status as connectionStatus,\n           d.updated_time as updatedTime,\n           d.created_time as createdTime,\n           d.storage_domain as storageDomain,\n           d.node_id as nodeId\n      from db_datasource_t d\n      left join sym_application_t a\n        on a.tid = d.app_id\n       and ifnull(a.is_del, 0) = 0\n      left join rm_org_t o\n        on o.id = d.org_id\n       and ifnull(o.deleted, 0) = 0\n     where ifnull(d.is_del, 0) = 0\n       and d.tenant_id = \'${escapedTenantId}\'\n       and ifnull(d.db_name, \'\') not like \'codex_%\'\n       ${keywordSql}\n     order by d.updated_time desc\n     limit 1000\n""")\n// 按“数据源管理”菜单绑定的角色范围过滤：全部 / 本部门 / 本人登记。\ndatasourceRows = dataScope.visibleDataSourcesFor(scopeResource, datasourceRows)\n// 创建人主数据位于控制库；批量解析可见数据源的显示名称，避免逐卡片查询。\nvar creatorIds = []\nfor (row in datasourceRows) {\n    var creatorId = text(row.createdby)\n    if (!blank(creatorId) && !creatorIds.contains(creatorId)) {\n        creatorIds.add(creatorId)\n    }\n}\nvar creatorNames = tenantAccounts.names(creatorIds)\nfor (row in datasourceRows) {\n    var rowTid = text(row.tid)\n    if (blank(rowTid)) {\n        continue\n    }\n    activeDatasourceById[rowTid] = true\n    if (resultById[rowTid] == true) {\n        // ES 投影可能是旧版本；部门树以业务库中的组织信息为准，补全/覆盖现有投影。\n        for (existingItem in result) {\n            if (text(existingItem.tid) == rowTid) {\n                existingItem.orgId = row.orgid\n                existingItem.orgName = row.orgname || userInfo?.orgName\n                existingItem.orgPath = row.orgpath\n                existingItem.appId = row.appid || existingItem.appId\n                existingItem.appName = row.appname || existingItem.appName\n                existingItem.dbType = row.dbtype || existingItem.dbType\n                existingItem.databaseType = row.databasetype || existingItem.databaseType\n                existingItem.accessMode = row.accessmode || existingItem.accessMode\n                existingItem.assetStatus = row.assetstatus\n                // ES 可能仍是探查前的连接信息；卡片的接入方式展示以业务主表为准。\n                existingItem.showConnect = row.showconnect\n                existingItem.connectionStatus = row.connectionstatus || existingItem.connectionStatus\n                existingItem.createdBy = row.createdby\n                existingItem.createdByName = creatorNames[text(row.createdby)] || \'\'\n                existingItem.createdTime = row.createdtime || existingItem.createdTime\n                existingItem.updatedTime = row.updatedtime || existingItem.updatedTime\n                break\n            }\n        }\n        continue\n    }\n    var item = {\n        tid: rowTid,\n        id: rowTid,\n        dbName: row.dbname,\n        description: row.description,\n        appId: row.appid,\n        appName: row.appname,\n        dbType: row.dbtype,\n        databaseType: row.databasetype,\n        accessMode: row.accessmode,\n        orgId: row.orgid,\n        createdBy: row.createdby,\n        createdByName: creatorNames[text(row.createdby)] || \'\',\n        orgName: row.orgname || userInfo?.orgName,\n        orgPath: row.orgpath,\n        exploredTableNum: numberValue(row.exploredtablenum),\n        tableNum: 0,\n        annotatedTableNum: 0,\n        unannotatedTableNum: 0,\n        registeredTableNum: 0,\n        unregisteredTableNum: 0,\n        businessTableNum: 0,\n        dictionaryTableNum: 0,\n        logTableNum: 0,\n        coreTableNum: 0,\n        registeredCoreTableNum: 0,\n        deferredTableNum: 0,\n        issueTableNum: 0,\n        problemTableNum: 0,\n        changedTableNum: 0,\n        addedTableNum: 0,\n        modifiedTableNum: 0,\n        deletedTableNum: 0,\n        assetStatus: row.assetstatus,\n        showConnect: row.showconnect,\n        connectionStatus: row.connectionstatus,\n        updatedTime: row.updatedtime,\n        createdTime: row.createdtime,\n        storageDomain: row.storagedomain,\n        nodeId: row.nodeid,\n        tables: []\n    }\n    datasourceIds.add(rowTid)\n    resultById[rowTid] = true\n    result.add(item)\n}\n\n// ES 只作为加速投影；已在业务库软删除或不属于当前租户的主记录不得返回。\nvar activeResult = []\nvar activeDatasourceIds = []\nfor (item in result) {\n    var itemTid = text(item.tid)\n    if (activeDatasourceById[itemTid] == true) {\n        activeResult.add(item)\n        activeDatasourceIds.add(itemTid)\n    }\n}\nresult = activeResult\ndatasourceIds = activeDatasourceIds\n\n// 旧调用者保留兼容；管理首屏跳过所有表文档读取及全量表循环。\nif (!summaryOnly) {\nvar tableGroups = {}\nif (datasourceIds.size() > 0) {\n    // 第二次 ES 查询：批量读取当前结果集下的表，避免每个数据源分别查询数据库。\n    var tableSearch = null\n    try {\n        tableSearch = tenantEs.index(configData().es_dataassets).search({\n        size: 10000,\n        query: {\n            bool: {\n                must: [\n                    { term: { assetType: \'table\' } },\n                    {\n                        bool: {\n                            should: [\n                                { terms: { datasourceId: datasourceIds } },\n                                { terms: { dbId: datasourceIds } }\n                            ],\n                            minimum_should_match: 1\n                        }\n                    }\n                ]\n            }\n        },\n        sort: [\n            { updatedTime: { order: \'desc\', unmapped_type: \'keyword\' } },\n            { tableName: { order: \'asc\', unmapped_type: \'keyword\' } }\n        ]\n        })\n    } catch (tableSearchError) {\n        // 表索引超时不能阻断数据源管理；下方按 datasource_id 批量回表补齐。\n        tableSearch = null\n    }\n\n    for (hit in (tableSearch?.hits?.hits == null ? [] : tableSearch.hits.hits)) {\n        if (hit?._source == null) {\n            continue\n        }\n        var table = hit._source\n        table.tid = table.tid || hit._id\n        table.id = table.id || table.tid\n        var datasourceId = text(table.datasourceId || table.dbId)\n        if (blank(datasourceId)) {\n            continue\n        }\n        var rawChangeStatus = text(table.changeStatus || table.change_status).toLowerCase()\n\n        // 变更类型只使用显式探查结果，不再从登记工作流字段猜测。\n        if (blank(rawChangeStatus)) {\n            rawChangeStatus = \'unchanged\'\n        }\n        table.changeStatus = rawChangeStatus\n        table.hasIssue = text(table.assetStatus) != \'2\'\n        if (tableGroups[datasourceId] == null) {\n            tableGroups[datasourceId] = []\n        }\n        tableGroups[datasourceId].add(table)\n    }\n\n    // ES 表投影历史上未包含 createdTime。这里按当前数据源一次性回读表主表的\n    // 创建/修改时间，并回填到 ES 表对象；避免页面误把修改时间当创建时间，也避免逐表查询。\n    var tableTimeById = {}\n    var tableTimeByName = {}\n    if (datasourceIds.size() > 0) {\n        var timeQuotedDatasourceIds = []\n        for (timeDatasourceId in datasourceIds) {\n            timeQuotedDatasourceIds.add("\'" + text(timeDatasourceId).replace("\'", "\'\'") + "\'")\n        }\n        var tableTimeRows = db.select("""\n            select tid,\n                   datasource_id as datasourceId,\n                   table_name as tableName,\n                   created_time as createdTime,\n                   updated_time as updatedTime,\n                   asset_status as assetStatus\n             from db_table_t\n             where ifnull(is_del, 0) = 0\n               and tenant_id = \'${escapedTenantId}\'\n               and datasource_id in (${timeQuotedDatasourceIds.join(\',\')})\n        """)\n        for (timeRow in tableTimeRows) {\n            tableTimeById[text(timeRow.tid)] = timeRow\n            tableTimeByName[text(timeRow.datasourceid) + \'::\' + text(timeRow.tablename).toLowerCase()] = timeRow\n        }\n        for (timeDatasourceId in datasourceIds) {\n            var timeGroup = tableGroups[text(timeDatasourceId)]\n            if (timeGroup == null) {\n                continue\n            }\n            for (table in timeGroup) {\n                var timeRow = tableTimeById[text(table.tid || table.id)]\n                if (timeRow == null) {\n                    var timeTableName = text(table.tableName || table.table_name || table.sourceTableName || table.tableNameEn).toLowerCase()\n                    timeRow = tableTimeByName[text(timeDatasourceId) + \'::\' + timeTableName]\n                }\n                if (timeRow != null) {\n                    table.createdTime = timeRow.createdtime\n                    table.updatedTime = timeRow.updatedtime\n                    table.assetStatus = timeRow.assetstatus\n                    table.hasIssue = text(timeRow.assetstatus) != \'2\'\n                }\n            }\n        }\n    }\n\n    var missingDatasourceIds = []\n    for (datasourceId in datasourceIds) {\n        var group = tableGroups[text(datasourceId)]\n        if (group == null || group.size() == 0) {\n            missingDatasourceIds.add(datasourceId)\n        }\n    }\n\n    // ES 表投影未刷新或缺失时，按 datasource_id 批量从 db_table_t 补齐统计和展开清单；\n    // 仍然避免逐数据源回表查询，保证本部门页面不会因为单行循环拖慢。\n    if (missingDatasourceIds.size() > 0) {\n        var quotedIds = []\n        for (missingId in missingDatasourceIds) {\n            quotedIds.add("\'" + text(missingId).replace("\'", "\'\'") + "\'")\n        }\n        var dbTableRows = db.select("""\n            select tid,\n                   datasource_id as datasourceId,\n                   table_name as tableName,\n                   table_name_en as tableNameEn,\n                   table_name_cn as tableNameCn,\n                   table_comment as tableComment,\n                   table_type as tableType,\n                   business_type as businessType,\n                   field_count as fieldCount,\n                   annotated,\n                   asset_status as assetStatus,\n                   updated_time as updatedTime,\n                   created_time as createdTime\n              from db_table_t\n             where ifnull(is_del, 0) = 0\n               and tenant_id = \'${escapedTenantId}\'\n               and datasource_id in (${quotedIds.join(\',\')})\n             order by table_name asc\n        """)\n        for (row in dbTableRows) {\n            var datasourceId = text(row.datasourceid)\n            if (blank(datasourceId)) {\n                continue\n            }\n            var table = {\n                tid: row.tid,\n                id: row.tid,\n                datasourceId: datasourceId,\n                dbId: datasourceId,\n                tableName: row.tablename || row.tablenameen,\n                tableNameCn: row.tablenamecn || row.tablecomment,\n                tableComment: row.tablecomment,\n                tableType: row.tabletype,\n                businessType: row.businesstype,\n                fieldCount: row.fieldcount,\n                annotated: row.annotated,\n                assetStatus: row.assetstatus,\n                changeStatus: \'unchanged\',\n                updatedTime: row.updatedtime,\n                createdTime: row.createdtime\n            }\n            table.hasIssue = text(row.assetstatus) != \'2\'\n            if (tableGroups[datasourceId] == null) {\n                tableGroups[datasourceId] = []\n            }\n            tableGroups[datasourceId].add(table)\n        }\n    }\n}\n\n// 在内存中组装表级统计，确保卡片指标与展开清单来自同一批 ES 文档。\nfor (item in result) {\n    var tables = tableGroups[text(item.tid)]\n    item.tables = tables == null ? [] : tables\n    item.tableNum = item.tables.size()\n    for (table in item.tables) {\n        if (numberValue(table.annotated) == 1) {\n            item.annotatedTableNum = item.annotatedTableNum + 1\n        } else {\n            item.unannotatedTableNum = item.unannotatedTableNum + 1\n        }\n\n        if (text(table.assetStatus) == \'2\') {\n            item.registeredTableNum = item.registeredTableNum + 1\n        } else {\n            item.unregisteredTableNum = item.unregisteredTableNum + 1\n        }\n        var businessType = blank(table.businessType) ? \'\' : text(table.businessType).toLowerCase()\n        var coreTable = [\'business\', \'业务表\', \'dict\', \'dictionary\', \'字典表\', \'log\', \'日志表\'].contains(businessType)\n        var deferredTable = [\'暂不处理\', \'暂不登记\', \'不确定\'].contains(businessType)\n        if (coreTable) {\n            item.coreTableNum = item.coreTableNum + 1\n            if (text(table.assetStatus) == \'2\') {\n                item.registeredCoreTableNum = item.registeredCoreTableNum + 1\n            }\n        }\n        if (deferredTable) {\n            item.deferredTableNum = item.deferredTableNum + 1\n        }\n        if (businessType == \'business\' || businessType == \'业务表\') {\n            item.businessTableNum = item.businessTableNum + 1\n        } else if (businessType == \'dict\' || businessType == \'dictionary\' || businessType == \'字典表\') {\n            item.dictionaryTableNum = item.dictionaryTableNum + 1\n        } else if (businessType == \'log\' || businessType == \'日志表\') {\n            item.logTableNum = item.logTableNum + 1\n        }\n        if (table.hasIssue) {\n            item.issueTableNum = item.issueTableNum + 1\n        }\n        // 未登记且有问题的同一张表只计一次。\n        if (text(table.assetStatus) != \'2\' || table.hasIssue) {\n            item.problemTableNum = item.problemTableNum + 1\n        }\n\n        if (table.changeStatus == \'added\') {\n            item.addedTableNum = item.addedTableNum + 1\n            item.changedTableNum = item.changedTableNum + 1\n        } else if (table.changeStatus == \'deleted\') {\n            item.deletedTableNum = item.deletedTableNum + 1\n            item.changedTableNum = item.changedTableNum + 1\n        } else if (table.changeStatus == \'modified\') {\n            item.modifiedTableNum = item.modifiedTableNum + 1\n            item.changedTableNum = item.changedTableNum + 1\n        }\n    }\n}\n\n\n}\nvar mysqlStatsByDb = {}\nif (datasourceIds.size() > 0) {\n    var quotedStatIds = []\n    for (statId in datasourceIds) {\n        quotedStatIds.add("\'" + text(statId).replace("\'", "\'\'") + "\'")\n    }\n    var datasourceStoredTotals = {}\n    var datasourceTotalRows = db.select("""\n        select tid,\n               ifnull(table_num, 0) as tableNum,\n               remark as description\n          from db_datasource_t\n         where ifnull(is_del, 0) = 0\n           and tenant_id = \'${escapedTenantId}\'\n           and tid in (${quotedStatIds.join(\',\')})\n    """)\n    for (totalRow in datasourceTotalRows) {\n        var totalDatasourceId = text(totalRow.tid)\n        if (!blank(totalDatasourceId)) {\n            datasourceStoredTotals[totalDatasourceId] = {\n                tableNum: numberValue(totalRow.tablenum),\n                description: totalRow.description\n            }\n        }\n    }\n\n    var statRows = db.select("""\n        select datasource_id as datasourceId,\n               count(1) as tableNum,\n               sum(case when ifnull(annotated, 0) = 1 then 1 else 0 end) as annotatedTableNum,\n               sum(case when ifnull(annotated, 0) <> 1 then 1 else 0 end) as unannotatedTableNum,\n               sum(case when ifnull(asset_status, 0) = 2 then 1 else 0 end) as registeredTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'business\', \'业务表\') then 1 else 0 end) as businessTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'dict\', \'dictionary\', \'字典表\') then 1 else 0 end) as dictionaryTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'log\', \'日志表\') then 1 else 0 end) as logTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'business\', \'业务表\', \'dict\', \'dictionary\', \'字典表\', \'log\', \'日志表\') then 1 else 0 end) as coreTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'business\', \'业务表\', \'dict\', \'dictionary\', \'字典表\', \'log\', \'日志表\')\n                         and ifnull(asset_status, 0) = 2 then 1 else 0 end) as registeredCoreTableNum,\n               sum(case when lower(ifnull(business_type, \'\')) in (\'暂不处理\', \'暂不登记\', \'不确定\') then 1 else 0 end) as deferredTableNum,\n               sum(case when ifnull(asset_status, 0) <> 2 then 1 else 0 end) as problemTableNum\n          from db_table_t\n         where ifnull(is_del, 0) = 0\n           and tenant_id = \'${escapedTenantId}\'\n           and datasource_id in (${quotedStatIds.join(\',\')})\n         group by datasource_id\n    """)\n    for (stat in statRows) {\n        var statDatasourceId = text(stat.datasourceid)\n        if (!blank(statDatasourceId)) {\n            var statTableNum = numberValue(stat.tablenum)\n            var statAnnotatedTableNum = numberValue(stat.annotatedtablenum)\n            var statRegisteredTableNum = numberValue(stat.registeredtablenum)\n            mysqlStatsByDb[statDatasourceId] = {\n                tableNum: statTableNum,\n                annotatedTableNum: statAnnotatedTableNum,\n                unannotatedTableNum: numberValue(stat.unannotatedtablenum),\n                registeredTableNum: statRegisteredTableNum,\n                unregisteredTableNum: statTableNum - statRegisteredTableNum,\n                businessTableNum: numberValue(stat.businesstablenum),\n                dictionaryTableNum: numberValue(stat.dictionarytablenum),\n                logTableNum: numberValue(stat.logtablenum),\n                coreTableNum: numberValue(stat.coretablenum),\n                registeredCoreTableNum: numberValue(stat.registeredcoretablenum),\n                deferredTableNum: numberValue(stat.deferredtablenum),\n                problemTableNum: numberValue(stat.problemtablenum)\n            }\n        }\n    }\n    for (item in result) {\n        var mysqlStats = mysqlStatsByDb[text(item.tid)]\n        var exploredTotal = numberValue(item.exploredTableNum)\n        var storedDatasource = datasourceStoredTotals[text(item.tid)]\n        var storedTotal = storedDatasource == null ? 0 : numberValue(storedDatasource.tableNum)\n        if (storedTotal > exploredTotal) {\n            exploredTotal = storedTotal\n        }\n        if (storedDatasource != null && !blank(storedDatasource.description)) {\n            // MySQL 主表是数据源描述的权威来源，覆盖 ES 可能滞后的空投影。\n            item.description = storedDatasource.description\n        }\n        if (mysqlStats != null) {\n            var displayTableNum = mysqlStats.tableNum\n            if (exploredTotal > displayTableNum) {\n                displayTableNum = exploredTotal\n            }\n            item.tableNum = displayTableNum\n            item.annotatedTableNum = mysqlStats.annotatedTableNum\n            item.unannotatedTableNum = displayTableNum - mysqlStats.annotatedTableNum\n            item.registeredTableNum = mysqlStats.registeredTableNum\n            item.unregisteredTableNum = displayTableNum - mysqlStats.registeredTableNum\n            item.businessTableNum = mysqlStats.businessTableNum\n            item.dictionaryTableNum = mysqlStats.dictionaryTableNum\n            item.logTableNum = mysqlStats.logTableNum\n            item.coreTableNum = mysqlStats.coreTableNum\n            item.registeredCoreTableNum = mysqlStats.registeredCoreTableNum\n            item.deferredTableNum = mysqlStats.deferredTableNum\n            item.problemTableNum = mysqlStats.problemTableNum\n        } else if (exploredTotal > item.tableNum) {\n            item.tableNum = exploredTotal\n            item.unannotatedTableNum = exploredTotal - item.annotatedTableNum\n            item.unregisteredTableNum = exploredTotal - item.registeredTableNum\n        }\n        if (item.unannotatedTableNum < 0) { item.unannotatedTableNum = 0 }\n        if (item.unregisteredTableNum < 0) { item.unregisteredTableNum = 0 }\n    }\n}\n\n\nif (summaryOnly && datasourceIds.size() > 0) {\n    var sourceFilters = {}\n    for (sourceId in datasourceIds) {\n        sourceFilters[text(sourceId)] = { bool: { should: [\n            { term: { datasourceId: sourceId } }, { term: { dbId: sourceId } }\n        ], minimum_should_match: 1 } }\n    }\n    var changeResult = tenantEs.index(configData().es_dataassets).search({\n        size: 0,\n        query: { term: { assetType: \'table\' } },\n        aggs: { bySource: {\n            filters: { filters: sourceFilters },\n            aggs: { changes: { filters: { filters: {\n                added: { bool: { should: [{term:{changeStatus:\'added\'}},{term:{change_status:\'added\'}}], minimum_should_match:1 } },\n                modified: { bool: { should: [{term:{changeStatus:\'modified\'}},{term:{change_status:\'modified\'}}], minimum_should_match:1 } },\n                deleted: { bool: { should: [{term:{changeStatus:\'deleted\'}},{term:{change_status:\'deleted\'}}], minimum_should_match:1 } }\n            } } } }\n        } }\n    })\n    for (item in result) {\n        var counts = changeResult?.aggregations?.bySource?.buckets[text(item.tid)]?.changes?.buckets\n        item.addedTableNum = numberValue(counts?.added?.doc_count)\n        item.modifiedTableNum = numberValue(counts?.modified?.doc_count)\n        item.deletedTableNum = numberValue(counts?.deleted?.doc_count)\n        item.changedTableNum = item.addedTableNum + item.modifiedTableNum + item.deletedTableNum\n        item.remove(\'tables\')\n        // 概要必须为轻量投影：不携带凭据、配置、列数组或历史治理 JSON。\n        for (key in [\'password\',\'username\',\'jdbcUrl\',\'jdbc_url\',\'poolCfg\',\'pool_cfg\',\'columns\',\n                     \'fieldGovernanceConfig\',\'field_governance_config\',\'dictionaryProfiles\',\'dictionaryProfile\']) {\n            item.remove(key)\n        }\n    }\n}\n\nvar sourceSortKey = (item) => {\n    var value = item?.updatedTime || item?.updated_time || item?.createdTime || item?.created_time\n    return blank(value) ? \'\' : text(value).replace(\'T\', \' \').replace(\'Z\', \'\')\n}\n\n// Sort after ES and MySQL fallback rows are merged, so newly saved fallback rows do not stay at the end.\nresult = result.sort((left, right) => {\n    var leftKey = sourceSortKey(left)\n    var rightKey = sourceSortKey(right)\n    if (rightKey > leftKey) {\n        return 1\n    }\n    if (rightKey < leftKey) {\n        return -1\n    }\n    return 0\n})\n\nvar total = result.size()\nreturn { orgId: orgId, orgName: userInfo?.orgName, total: total, list: result }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/06.本部门数据源清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_db_tree_stats_20260723',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_database_tree_statistics_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "07.数据源组织业务系统统计",\n  "createTime": 1784814000000,\n  "updateTime": 1784814000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/treeStatistics",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"出入境\\",\\n  \\"dbType\\": \\"mysql\\",\\n  \\"registrationState\\": \\"pending\\",\\n  \\"orgIds\\": []\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"total\\": 1,\\n  \\"assignedTotal\\": 1,\\n  \\"unassignedTotal\\": 0,\\n  \\"orgCounts\\": {\\"1351480103971975170\\": 1},\\n  \\"orgApps\\": {\\"1351480103971975170\\": [{\\"value\\": \\"1980105567668809728\\", \\"label\\": \\"福建公安出入境人员动态管控系统\\", \\"count\\": 1, \\"type\\": \\"app\\", \\"datasources\\": [{\\"value\\": \\"4b5d9992d89744b9b514f8905dc27998\\", \\"label\\": \\"出入境人员动管系统数据库\\", \\"count\\": 1, \\"dbType\\": \\"mysql\\", \\"type\\": \\"datasource\\"}]}]},\\n  \\"dbTypes\\": {\\"mysql\\": 1},\\n  \\"assetStatuses\\": {\\"completed\\": 0,\\"pending\\": 1}\\n}",\n  "description": "数据源组织业务系统统计（POST /dst/database/treeStatistics）。只读页面专用接口；完全从 Elasticsearch dataassets 索引按关键字、数据库类型和登记状态筛选，通过 orgId→appId 嵌套聚合返回组织机构、业务系统及数据源数量，并同时返回数据库类型和登记状态分面；不查询或写入数据库；使用请求参数 keyword、dbType、registrationState、orgIds；涉及 db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.数据源组织业务系统统计\n// 路由：POST /dst/database/treeStatistics\n// 业务说明：数据源组织业务系统统计（POST /dst/database/treeStatistics）。只读页面专用接口；完全从 Elasticsearch dataassets 索引按关键字、数据库类型和登记状态筛选，通过 orgId→appId 嵌套聚合返回组织机构、业务系统及数据源数量，并同时返回数据库类型和登记状态分面；不查询或写入数据库；使用请求参数 keyword、dbType、registrationState、orgIds；涉及 db_datasource_t 等业务表。\nimport tenantEs\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nimport \'@/common/configData\' as configData\nimport dataScope\n\n/*\n * 数据源组织树统计。\n * 数据读取：Elasticsearch dataassets 索引负责筛选，db_datasource_t 负责当前租户\n * 有效数据源准入校验。必须与 /dst/database/page 保持相同口径，避免 ES 删除残留\n * 进入左树统计而右侧列表不可见。\n * 数据写入：无。\n * 核心逻辑：使用 orgId terms + appId + tid 子聚合，一次请求构建“部门→业务系统→数据源”统计树。\n * 数据源列表、数据目录和数据接入页面共用该接口，所有左树节点与数据源范围保持一致。\n */\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\n\nvar filters = [ { term: { assetType: \'db\' } } ]\nvar keyword = text(body?.keyword).trim()\nvar dbType = text(body?.dbType).trim()\nvar registrationState = text(body?.registrationState).trim()\nvar orgIds = body?.orgIds\n\n// 统计接口与分页接口保持完全相同的筛选口径。\nif (!blank(keyword)) {\n    filters.add({\n        bool: {\n            should: [\n                { wildcard: { dbName: \'*\' + keyword + \'*\' } },\n                { wildcard: { appName: \'*\' + keyword + \'*\' } },\n                { wildcard: { database: \'*\' + keyword + \'*\' } }\n            ],\n            minimum_should_match: 1\n        }\n    })\n}\nif (!blank(dbType)) {\n    filters.add({ term: { dbType: dbType } })\n}\nif (orgIds != null && orgIds.size() > 0) {\n    filters.add({ terms: { orgId: orgIds } })\n}\n\n// 先取得与分页接口完全相同的 ES 候选集，再一次性回查当前租户未删除的数据源。\n// 数据源数量远小于表资产数量，10000 的上限与分页接口一致。\nvar result = tenantEs.index(configData().es_dataassets).search({\n    from: 0,\n    size: 10000,\n    track_total_hits: true,\n    query: {\n        bool: {\n            filter: filters,\n            must_not: [\n                { wildcard: { dbName: \'codex_*\' } },\n                { wildcard: { database: \'codex_*\' } }\n            ]\n        }\n    }\n})\n\nvar hits = result?.hits?.hits == null ? [] : result.hits.hits\nvar candidateIds = []\nfor (hit in hits) {\n    var candidateId = hit?._source?.tid || hit?._id\n    if (!blank(candidateId)) {\n        candidateIds.add(candidateId + \'\')\n    }\n}\n\nvar datasourceById = {}\nif (candidateIds.size() > 0) {\n    var datasourceRows = db.table(\'db_datasource_t\').where()\n        .in(\'tid\', candidateIds).eq(\'is_del\', 0).select()\n    datasourceRows = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', datasourceRows)\n    for (datasource in datasourceRows) {\n        var datasourceId = datasource?.tid\n        if (!blank(datasourceId)) {\n            datasourceById[datasourceId + \'\'] = datasource\n        }\n    }\n}\n\nvar validItems = []\nfor (hit in hits) {\n    var indexItem = hit?._source\n    if (indexItem == null) {\n        continue\n    }\n    var datasourceId = indexItem.tid || hit._id\n    var datasource = blank(datasourceId) ? null : datasourceById[datasourceId + \'\']\n    if (datasource == null) {\n        continue\n    }\n    var item = {}\n    item.putAll(indexItem)\n    item.putAll(datasource)\n    item.tid = datasourceId\n    var registered = text(datasource.asset_status == null ? datasource.assetStatus : datasource.asset_status) == \'2\'\n    if (blank(registrationState) || registrationState == (registered ? \'completed\' : \'pending\')) {\n        item.assetStatus = datasource.asset_status == null ? datasource.assetStatus : datasource.asset_status\n        validItems.add(item)\n    }\n}\n\nvar orgCounts = {}\nvar orgApps = {}\nvar dbTypes = {}\nvar assetStatuses = { completed: 0, pending: 0 }\nvar appAccumulators = {}\nfor (item in validItems) {\n    var orgId = text(item?.orgId).trim()\n    var appId = text(item?.appId).trim()\n    var appName = text(item?.appName).trim()\n    var dbName = text(item?.dbName).trim()\n    var dbTypeValue = text(item?.dbType).trim()\n    var assetStatusValue = text(item?.assetStatus) == \'2\' ? \'completed\' : \'pending\'\n\n    if (!blank(orgId)) {\n        orgCounts[orgId] = (orgCounts[orgId] == null ? 0 : orgCounts[orgId]) + 1\n    }\n    if (!blank(dbTypeValue)) {\n        dbTypes[dbTypeValue] = (dbTypes[dbTypeValue] == null ? 0 : dbTypes[dbTypeValue]) + 1\n    }\n    assetStatuses[assetStatusValue] =\n        (assetStatuses[assetStatusValue] == null ? 0 : assetStatuses[assetStatusValue]) + 1\n\n    // 历史“未匹配业务系统”占位项不进入树，部门总数仍保留有效数据源。\n    if (blank(orgId) || blank(appId) || blank(appName)\n            || text(appName).startsWith(\'未匹配业务系统\')) {\n        continue\n    }\n    var key = orgId + \'::\' + appId\n    var app = appAccumulators[key]\n    if (app == null) {\n        app = {\n            value: appId,\n            label: appName,\n            count: 0,\n            type: \'app\',\n            datasources: [],\n            datasourceIds: {}\n        }\n        appAccumulators[key] = app\n        if (orgApps[orgId] == null) {\n            orgApps[orgId] = []\n        }\n        orgApps[orgId].add(app)\n    }\n    app.count = app.count + 1\n    var datasourceId = text(item?.tid)\n    if (!blank(datasourceId) && blank(app.datasourceIds[datasourceId]) && !blank(dbName)) {\n        app.datasourceIds[datasourceId] = true\n        app.datasources.add({\n            value: datasourceId,\n            label: dbName,\n            count: 1,\n            dbType: dbTypeValue,\n            type: \'datasource\'\n        })\n    }\n}\n\nvar assigned = 0\nfor (key, value in orgCounts) {\n    assigned = assigned + value\n}\n\nfor (orgId, apps in orgApps) {\n    for (app in apps) {\n        app.remove(\'datasourceIds\')\n    }\n}\n\nreturn {\n    total: validItems.size(),\n    assignedTotal: assigned,\n    unassignedTotal: validItems.size() - assigned,\n    orgCounts: orgCounts,\n    orgApps: orgApps,\n    dbTypes: dbTypes,\n    assetStatuses: assetStatuses\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/02.数据库表/07.数据源组织业务系统统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_report_data_01",\n  "script": null,\n  "groupId": "datapd_database_group_01",\n  "name": "08.数据上报落库",\n  "createTime": 1788347944807,\n  "updateTime": 1788389142945,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/report-data",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"action\\":\\"list\\",\\"datasourceId\\":\\"2095081172819283968\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据上报工作区接口。按登记表字段白名单校验，将实际上报数据和批次记录写入 test1；支持批次列表、实际入库数据预览、导入与删除；使用请求参数 tables；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.数据上报落库\n// 路由：POST /dst/database/report-data\n// 业务说明：数据上报工作区接口。按登记表字段白名单校验，将实际上报数据和批次记录写入 test1；支持批次列表、实际入库数据预览、导入与删除；使用请求参数 tables；涉及 db_datasource_t、db_table_t、db_table_column_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport cn.hutool.core.util.IdUtil\nimport java.util.Map\n\n/*\n * 数据源 31：数据上报落库。\n *\n * 当前上报存储库固定为 MySQL test1；后续配置化只需替换 storageSchema 的解析方式。\n * 上报数据按登记库 db_table_t / db_table_column_t 的表和字段白名单校验，实际业务行写入\n * test1 中的同名表；批次及批次-表关系也保存在 test1，避免把大量上报状态塞入 pool_cfg。\n */\nvar storageSchema = \'test1\'\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    return null\n}\nvar firstText = (row, keys) => {\n    var value = first(row, keys)\n    return blank(value) ? \'\' : textOf(value).trim()\n}\nvar identifier = (value, label) => {\n    var name = textOf(value).trim()\n    if (blank(name) || name.length() > 64 || !name.matches(\'^[A-Za-z][A-Za-z0-9_]{0,63}$\')) {\n        exit 400, label + \'只能包含英文字母、数字和下划线，且必须以字母开头\'\n    }\n    return name\n}\nvar mysqlType = (column) => {\n    var raw = firstText(column, [\'columnType\', \'column_type\', \'dataType\', \'data_type\']).toLowerCase()\n    var length = first(column, [\'length\', \'columnLength\', \'column_length\'])\n    var size = length == null ? 0 : (length + \'\')::int\n    if (raw == \'日期时间\' || raw == \'datetime\' || raw == \'timestamp\') { return \'datetime\' }\n    if (raw == \'日期\' || raw == \'date\') { return \'date\' }\n    if (raw == \'时间\' || raw == \'time\') { return \'time\' }\n    if (raw == \'整数\' || raw == \'int\' || raw == \'integer\' || raw == \'bigint\' || raw == \'long\') { return \'bigint\' }\n    if (raw == \'小数\' || raw == \'数字\' || raw == \'decimal\' || raw == \'number\' || raw == \'numeric\') { return \'decimal(30,10)\' }\n    if (raw == \'布尔\' || raw == \'boolean\' || raw == \'bool\') { return \'tinyint(1)\' }\n    if (raw == \'文本\' || raw == \'text\' || raw == \'longtext\') { return \'text\' }\n    if (raw.matches(\'^(var)?char\\\\([0-9]{1,5}\\\\)$\')) { return raw }\n    return \'varchar(\' + (size > 0 && size <= 4000 ? size : 500) + \')\'\n}\nvar ensureMetadataTables = () => {\n    db.update("""\n        create table if not exists `test1`.`de_data_report_batch_t` (\n          `batch_id` varchar(40) not null,\n          `datasource_id` varchar(40) not null,\n          `tenant_id` varchar(40) not null,\n          `file_id` varchar(64) null,\n          `file_name` varchar(255) not null,\n          `file_url` varchar(1000) null,\n          `table_count` int not null default 0,\n          `row_count` bigint not null default 0,\n          `status` varchar(20) not null default \'completed\',\n          `error_message` varchar(1000) null,\n          `created_by` varchar(64) null,\n          `created_name` varchar(100) null,\n          `created_time` datetime not null,\n          `is_del` tinyint not null default 0,\n          primary key (`batch_id`),\n          key `idx_report_batch_source` (`tenant_id`, `datasource_id`, `is_del`, `created_time`)\n        ) engine=InnoDB default charset=utf8mb4 comment=\'数据上报批次\'\n    """)\n    db.update("""\n        create table if not exists `test1`.`de_data_report_batch_table_t` (\n          `tid` varchar(40) not null,\n          `batch_id` varchar(40) not null,\n          `datasource_id` varchar(40) not null,\n          `tenant_id` varchar(40) not null,\n          `table_id` varchar(40) not null,\n          `table_name` varchar(64) not null,\n          `table_name_cn` varchar(255) null,\n          `row_count` bigint not null default 0,\n          `created_time` datetime not null,\n          `is_del` tinyint not null default 0,\n          primary key (`tid`),\n          key `idx_report_batch_table` (`batch_id`, `is_del`)\n        ) engine=InnoDB default charset=utf8mb4 comment=\'数据上报批次表明细\'\n    """)\n}\nvar tenantId = textOf(tenantRuntime.id()).trim()\nif (blank(tenantId)) { exit 401, \'无法识别当前租户，请重新登录后再操作\' }\nvar datasourceId = firstText(body, [\'datasourceId\', \'datasource_id\', \'dbId\', \'tid\'])\nif (blank(datasourceId)) { exit 400, \'数据源不能为空\' }\nvar source = db.table(\'db_datasource_t\').where()\n    .eq(\'tid\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (source == null) { exit 404, \'数据源不存在或不属于当前租户\' }\nvar sourceConfig = datasourceConnectionConfig(\'read\', datasourceId, null, false)\nvar accessMode = firstText(sourceConfig, [\'accessMode\', \'access_mode\']).toLowerCase()\nif (accessMode == \'report\') { accessMode = \'upload\' }\nif (accessMode != \'upload\') { exit 400, \'只有数据上报方式的数据源可以使用上报工作区\' }\n\nensureMetadataTables()\nvar action = firstText(body, [\'action\']).toLowerCase()\nif (blank(action)) { action = \'list\' }\nvar listBatches = () => db.select("""\n    select b.batch_id as batchId,\n           b.file_id as fileId,\n           b.file_name as fileName,\n           b.file_url as fileUrl,\n           b.table_count as tableCount,\n           b.row_count as rowCount,\n           b.status,\n           b.created_by as createdBy,\n           b.created_name as createdName,\n           b.created_time as createdTime,\n           group_concat(concat(t.table_name_cn, \'（\', t.table_name, \'，\', t.row_count, \' 行）\')\n                        order by t.table_name separator \'、\') as tableSummary\n      from test1.de_data_report_batch_t b\n      left join test1.de_data_report_batch_table_t t\n        on t.batch_id = b.batch_id and t.tenant_id = b.tenant_id and t.is_del = 0\n     where b.tenant_id = #{tenantId}\n       and b.datasource_id = #{datasourceId}\n       and b.is_del = 0\n     group by b.batch_id, b.file_id, b.file_name, b.file_url, b.table_count, b.row_count,\n              b.status, b.created_by, b.created_name, b.created_time\n     order by b.created_time desc\n""")\nif (action == \'list\') {\n    return { storageDatabase: storageSchema, list: listBatches() }\n}\n\n/*\n * 数据预览只读取当前租户、当前数据源、已登记的业务表/日志表。\n * 表名和字段名均取自登记元数据白名单，避免动态 SQL 越权访问 test1 中的其他表。\n */\nif (action == \'preview\') {\n    var reportableTables = db.table(\'db_table_t\').where()\n        .eq(\'datasource_id\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n    var previewTableOptions = []\n    var selectedTable = null\n    var requestedPreviewTableName = firstText(body, [\'tableName\', \'table_name\'])\n    for (registeredTable in reportableTables) {\n        var registeredBusinessType = firstText(registeredTable, [\'businessType\', \'business_type\'])\n        if (registeredBusinessType != \'业务表\' && registeredBusinessType != \'日志表\') { continue }\n        var registeredTableName = identifier(firstText(registeredTable, [\'tableName\', \'table_name\']), \'数据表名\')\n        previewTableOptions.add({\n            tableId: firstText(registeredTable, [\'tid\']),\n            tableName: registeredTableName,\n            tableNameCn: firstText(registeredTable, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']),\n            businessType: registeredBusinessType\n        })\n        if (selectedTable == null && (blank(requestedPreviewTableName) || registeredTableName == requestedPreviewTableName)) {\n            selectedTable = registeredTable\n        }\n    }\n    if (selectedTable == null) {\n        if (previewTableOptions.size() == 0) {\n            return { storageDatabase: storageSchema, tables: [], columns: [], list: [], total: 0, pageNo: 1, pageSize: 20, tableExists: false }\n        }\n        exit 400, \'请选择当前数据源已登记的业务表或日志表\'\n    }\n    var previewTableName = identifier(firstText(selectedTable, [\'tableName\', \'table_name\']), \'数据表名\')\n    var previewTableId = firstText(selectedTable, [\'tid\'])\n    var pageNoText = firstText(body, [\'pageNo\', \'page_no\'])\n    var pageSizeText = firstText(body, [\'pageSize\', \'page_size\'])\n    if (!blank(pageNoText) && !pageNoText.matches(\'^[0-9]{1,5}$\')) { exit 400, \'页码格式错误\' }\n    if (!blank(pageSizeText) && !pageSizeText.matches(\'^[0-9]{1,3}$\')) { exit 400, \'每页条数格式错误\' }\n    var pageNo = blank(pageNoText) ? 1 : (pageNoText::int)\n    var pageSize = blank(pageSizeText) ? 20 : (pageSizeText::int)\n    if (pageNo < 1) { pageNo = 1 }\n    if (pageSize < 1) { pageSize = 20 }\n    if (pageSize > 100) { pageSize = 100 }\n\n    var previewColumns = []\n    var selectColumns = []\n    var previewColumnIndex = 0\n    var registeredPreviewColumns = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', previewTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n        .orderBy(\'ordinal_position\', \'asc\').select()\n    for (registeredColumn in registeredPreviewColumns) {\n        var previewColumnName = identifier(firstText(registeredColumn, [\'columnName\', \'column_name\']), \'字段名\')\n        var previewColumnLabel = firstText(registeredColumn, [\'columnComment\', \'column_comment\', \'columnNameCn\', \'column_name_cn\', \'comment\'])\n        if (blank(previewColumnLabel)) { previewColumnLabel = previewColumnName }\n        var previewResponseName = \'c\' + previewColumnIndex\n        previewColumns.add({\n            name: previewResponseName,\n            sourceName: previewColumnName,\n            label: previewColumnLabel,\n            columnType: firstText(registeredColumn, [\'columnType\', \'column_type\', \'dataType\', \'data_type\']),\n            length: first(registeredColumn, [\'length\', \'columnLength\', \'column_length\'])\n        })\n        selectColumns.add(\'`\' + previewColumnName + \'` as \' + previewResponseName)\n        previewColumnIndex = previewColumnIndex + 1\n    }\n    previewColumns.add({ name: \'c\' + previewColumnIndex, sourceName: \'_report_batch_id\', label: \'上报批次\' })\n    selectColumns.add(\'`_report_batch_id` as c\' + previewColumnIndex)\n    previewColumnIndex = previewColumnIndex + 1\n    previewColumns.add({ name: \'c\' + previewColumnIndex, sourceName: \'_report_uploaded_at\', label: \'上报时间\' })\n    selectColumns.add(\'`_report_uploaded_at` as c\' + previewColumnIndex)\n\n    var previewExistsParams = { schemaName: storageSchema, tableName: previewTableName }\n    var previewTableExists = db.selectInt("""\n        select count(1) from information_schema.tables\n         where table_schema = #{schemaName} and table_name = #{tableName}\n    """, previewExistsParams) > 0\n    if (!previewTableExists) {\n        return { storageDatabase: storageSchema, tables: previewTableOptions, tableName: previewTableName,\n                 columns: previewColumns, list: [], total: 0, pageNo: pageNo, pageSize: pageSize, tableExists: false }\n    }\n    var reportMarkerCount = db.selectInt("""\n        select count(1) from information_schema.columns\n         where table_schema = #{schemaName} and table_name = #{tableName}\n           and column_name = \'_report_datasource_id\'\n    """, previewExistsParams)\n    if (reportMarkerCount == 0) {\n        return { storageDatabase: storageSchema, tables: previewTableOptions, tableName: previewTableName,\n                 columns: previewColumns, list: [], total: 0, pageNo: pageNo, pageSize: pageSize, tableExists: false }\n    }\n    var previewParams = { datasourceId: datasourceId, tenantId: tenantId, pageSize: pageSize, offset: (pageNo - 1) * pageSize }\n    var previewTotal = db.selectInt(\'select count(1) from `test1`.`\' + previewTableName + \'` where `_report_datasource_id` = #{datasourceId} and `_report_tenant_id` = #{tenantId}\', previewParams)\n    var previewRows = db.select(\'select \' + selectColumns.join(\', \') + \' from `test1`.`\' + previewTableName + \'` where `_report_datasource_id` = #{datasourceId} and `_report_tenant_id` = #{tenantId} order by `_report_uploaded_at` desc, `_report_row_id` desc limit #{pageSize} offset #{offset}\', previewParams)\n    return { storageDatabase: storageSchema, tables: previewTableOptions, tableName: previewTableName,\n             columns: previewColumns, list: previewRows, total: previewTotal, pageNo: pageNo, pageSize: pageSize, tableExists: true }\n}\n\nif (action == \'delete\') {\n    var batchId = firstText(body, [\'batchId\', \'batch_id\'])\n    if (blank(batchId)) { exit 400, \'上报批次不能为空\' }\n    var batch = db.selectOne("""\n        select batch_id as batchId, file_id as fileId\n          from test1.de_data_report_batch_t\n         where batch_id = #{batchId} and datasource_id = #{datasourceId}\n           and tenant_id = #{tenantId} and is_del = 0\n    """)\n    if (batch == null) { exit 404, \'上报批次不存在或已删除\' }\n    var batchTables = db.select("""\n        select table_name as tableName\n          from test1.de_data_report_batch_table_t\n         where batch_id = #{batchId} and datasource_id = #{datasourceId}\n           and tenant_id = #{tenantId} and is_del = 0\n    """)\n    for (batchTable in batchTables) {\n        var tableName = identifier(firstText(batchTable, [\'tableName\', \'table_name\', \'tablename\']), \'数据表名\')\n        var deleteParams = { batchId: batchId, datasourceId: datasourceId, tenantId: tenantId }\n        db.update(\'delete from `test1`.`\' + tableName + \'` where `_report_batch_id` = #{batchId} and `_report_datasource_id` = #{datasourceId} and `_report_tenant_id` = #{tenantId}\', deleteParams)\n    }\n    db.update("""\n        update test1.de_data_report_batch_table_t set is_del = 1\n         where batch_id = #{batchId} and datasource_id = #{datasourceId} and tenant_id = #{tenantId}\n    """)\n    db.update("""\n        update test1.de_data_report_batch_t set is_del = 1\n         where batch_id = #{batchId} and datasource_id = #{datasourceId} and tenant_id = #{tenantId}\n    """)\n    return { batchId: batchId, fileId: firstText(batch, [\'fileId\', \'file_id\', \'fileid\']), list: listBatches() }\n}\n\nif (action != \'import\') { exit 400, \'不支持的数据上报操作\' }\nvar uploadedTables = body == null ? null : body.tables\nif (uploadedTables == null || uploadedTables.size() == 0) { exit 400, \'上报文件中没有可导入的数据\' }\nif (uploadedTables.size() > 100) { exit 400, \'单个上报文件最多包含 100 张数据表\' }\nvar fileName = firstText(body, [\'fileName\', \'file_name\'])\nif (blank(fileName)) { exit 400, \'上报文件名不能为空\' }\nvar totalRows = 0\nfor (uploaded in uploadedTables) {\n    var inputRows = uploaded == null ? null : uploaded.rows\n    totalRows = totalRows + (inputRows == null ? 0 : inputRows.size())\n}\nif (totalRows <= 0) { exit 400, \'上报文件没有填写业务数据\' }\nif (totalRows > 20000) { exit 400, \'单次上报最多导入 20000 行，请拆分文件后重试\' }\n\nvar principal = approvalRuntime.principal()\nvar batchId = IdUtil.getSnowflakeNextIdStr()\nvar nowTime = new Date()\nvar completedTables = []\nvar importedTableCount = 0\ntry {\n    for (uploaded in uploadedTables) {\n        var requestedTableId = firstText(uploaded, [\'tableId\', \'table_id\', \'tid\'])\n        var requestedTableName = identifier(firstText(uploaded, [\'tableName\', \'table_name\']), \'数据表名\')\n        var tableQuery = db.table(\'db_table_t\').where()\n            .eq(\'datasource_id\', datasourceId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n        var registeredTable = blank(requestedTableId)\n            ? tableQuery.eq(\'table_name\', requestedTableName).selectOne()\n            : tableQuery.eq(\'tid\', requestedTableId).eq(\'table_name\', requestedTableName).selectOne()\n        if (registeredTable == null) { exit 400, \'数据表 \' + requestedTableName + \' 未在当前数据源中登记\' }\n        var businessType = firstText(registeredTable, [\'businessType\', \'business_type\'])\n        if (businessType != \'业务表\' && businessType != \'日志表\') {\n            exit 400, \'数据表 \' + requestedTableName + \' 不是业务表或日志表，不能上报业务数据\'\n        }\n        var tableId = firstText(registeredTable, [\'tid\'])\n        var registeredColumns = db.table(\'db_table_column_t\').where()\n            .eq(\'table_id\', tableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n            .orderBy(\'ordinal_position\', \'asc\').select()\n        if (registeredColumns == null || registeredColumns.size() == 0) {\n            exit 400, \'数据表 \' + requestedTableName + \' 尚未登记字段\'\n        }\n        var columnMap = {}\n        var columnNames = []\n        for (column in registeredColumns) {\n            var columnName = identifier(firstText(column, [\'columnName\', \'column_name\']), \'字段名\')\n            columnMap[columnName] = column\n            columnNames.add(columnName)\n        }\n        var existsParams = { schemaName: storageSchema, tableName: requestedTableName }\n        var existedCount = db.selectInt("""\n            select count(1) from information_schema.tables\n             where table_schema = #{schemaName} and table_name = #{tableName}\n        """, existsParams)\n        if (existedCount == 0) {\n            var definitions = []\n            definitions.add(\'`_report_row_id` varchar(40) not null\')\n            for (column in registeredColumns) {\n                var columnName = identifier(firstText(column, [\'columnName\', \'column_name\']), \'字段名\')\n                definitions.add(\'`\' + columnName + \'` \' + mysqlType(column) + \' null\')\n            }\n            definitions.add(\'`_report_batch_id` varchar(40) not null\')\n            definitions.add(\'`_report_datasource_id` varchar(40) not null\')\n            definitions.add(\'`_report_tenant_id` varchar(40) not null\')\n            definitions.add(\'`_report_file_name` varchar(255) null\')\n            definitions.add(\'`_report_uploaded_at` datetime not null\')\n            definitions.add(\'primary key (`_report_row_id`)\')\n            definitions.add(\'key `idx_report_batch` (`_report_tenant_id`, `_report_datasource_id`, `_report_batch_id`)\')\n            db.update(\'create table `test1`.`\' + requestedTableName + \'` (\' + definitions.join(\',\') + \') engine=InnoDB default charset=utf8mb4\')\n        } else {\n            var markerCount = db.selectInt("""\n                select count(1) from information_schema.columns\n                 where table_schema = #{schemaName} and table_name = #{tableName}\n                   and column_name = \'_report_datasource_id\'\n            """, existsParams)\n            if (markerCount == 0) {\n                exit 409, \'test1.\' + requestedTableName + \' 已存在且不是平台上报表，为避免覆盖数据已停止导入\'\n            }\n            for (column in registeredColumns) {\n                var columnName = identifier(firstText(column, [\'columnName\', \'column_name\']), \'字段名\')\n                var columnParams = { schemaName: storageSchema, tableName: requestedTableName, columnName: columnName }\n                var columnCount = db.selectInt("""\n                    select count(1) from information_schema.columns\n                     where table_schema = #{schemaName} and table_name = #{tableName}\n                       and column_name = #{columnName}\n                """, columnParams)\n                if (columnCount == 0) {\n                    db.update(\'alter table `test1`.`\' + requestedTableName + \'` add column `\' + columnName + \'` \' + mysqlType(column) + \' null\')\n                }\n            }\n        }\n        var inputRows = uploaded == null ? null : uploaded.rows\n        if (inputRows == null || inputRows.size() == 0) { continue }\n        // 业务错误使用 exit 返回，不会进入 catch；因此必须整表预校验通过后才能写入第一行。\n        var inputRowNumber = 0\n        for (inputRow in inputRows) {\n            inputRowNumber = inputRowNumber + 1\n            if (!(inputRow instanceof Map)) { exit 400, requestedTableName + \' 第 \' + inputRowNumber + \' 行格式错误\' }\n            for (inputColumnName in inputRow.keySet()) {\n                if (columnMap[inputColumnName] == null) {\n                    exit 400, requestedTableName + \' 包含未登记字段：\' + inputColumnName\n                }\n            }\n            for (columnName in columnNames) {\n                var column = columnMap[columnName]\n                var value = inputRow.get(columnName)\n                var nullable = first(column, [\'nullable\', \'isNullable\', \'is_nullable\'])\n                if ((nullable + \'\') == \'0\' && blank(value)) {\n                    exit 400, requestedTableName + \' 第 \' + inputRowNumber + \' 行必填字段 \' + columnName + \' 不能为空\'\n                }\n            }\n        }\n        // 从这里开始只剩数据库写入错误，catch 可以按批次清理已写入的部分数据。\n        completedTables.add(requestedTableName)\n        inputRowNumber = 0\n        for (inputRow in inputRows) {\n            inputRowNumber = inputRowNumber + 1\n            var insertColumns = []\n            var placeholders = []\n            var params = {}\n            var parameterIndex = 0\n            for (columnName in columnNames) {\n                var column = columnMap[columnName]\n                var value = inputRow.get(columnName)\n                var parameterName = \'p\' + parameterIndex\n                insertColumns.add(\'`\' + columnName + \'`\')\n                placeholders.add(\'#{\' + parameterName + \'}\')\n                params[parameterName] = blank(value) ? null : value\n                parameterIndex = parameterIndex + 1\n            }\n            var systemValues = {\n                _report_row_id: IdUtil.getSnowflakeNextIdStr(),\n                _report_batch_id: batchId,\n                _report_datasource_id: datasourceId,\n                _report_tenant_id: tenantId,\n                _report_file_name: fileName,\n                _report_uploaded_at: nowTime\n            }\n            for (systemName in systemValues.keySet()) {\n                var parameterName = \'p\' + parameterIndex\n                insertColumns.add(\'`\' + systemName + \'`\')\n                placeholders.add(\'#{\' + parameterName + \'}\')\n                params[parameterName] = systemValues[systemName]\n                parameterIndex = parameterIndex + 1\n            }\n            var insertSql = \'insert into `test1`.`\' + requestedTableName + \'` (\' + insertColumns.join(\',\') + \') values (\' + placeholders.join(\',\') + \')\'\n            db.update(insertSql, params)\n        }\n        var batchTableParams = {\n            tid: IdUtil.getSnowflakeNextIdStr(), batchId: batchId, datasourceId: datasourceId,\n            tenantId: tenantId, tableId: tableId, tableName: requestedTableName,\n            tableNameCn: firstText(registeredTable, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']),\n            rowCount: inputRows.size(), createdTime: nowTime\n        }\n        db.update("""\n            insert into test1.de_data_report_batch_table_t\n              (tid, batch_id, datasource_id, tenant_id, table_id, table_name, table_name_cn, row_count, created_time, is_del)\n            values (#{tid}, #{batchId}, #{datasourceId}, #{tenantId}, #{tableId}, #{tableName}, #{tableNameCn}, #{rowCount}, #{createdTime}, 0)\n        """, batchTableParams)\n        importedTableCount = importedTableCount + 1\n    }\n    var batchParams = {\n        batchId: batchId, datasourceId: datasourceId, tenantId: tenantId,\n        fileId: firstText(body, [\'fileId\', \'file_id\']), fileName: fileName,\n        fileUrl: firstText(body, [\'fileUrl\', \'file_url\']), tableCount: importedTableCount,\n        rowCount: totalRows, status: \'completed\',\n        createdBy: principal == null ? \'\' : firstText(principal, [\'userId\', \'user_id\', \'id\']),\n        createdName: principal == null ? \'\' : firstText(principal, [\'userName\', \'user_name\', \'name\']),\n        createdTime: nowTime\n    }\n    db.update("""\n        insert into test1.de_data_report_batch_t\n          (batch_id, datasource_id, tenant_id, file_id, file_name, file_url, table_count, row_count,\n           status, created_by, created_name, created_time, is_del)\n        values (#{batchId}, #{datasourceId}, #{tenantId}, #{fileId}, #{fileName}, #{fileUrl}, #{tableCount}, #{rowCount},\n                #{status}, #{createdBy}, #{createdName}, #{createdTime}, 0)\n    """, batchParams)\n} catch (e) {\n    for (tableName in completedTables) {\n        var rollbackParams = { batchId: batchId, datasourceId: datasourceId, tenantId: tenantId }\n        try {\n            db.update(\'delete from `test1`.`\' + tableName + \'` where `_report_batch_id` = #{batchId} and `_report_datasource_id` = #{datasourceId} and `_report_tenant_id` = #{tenantId}\', rollbackParams)\n        } catch (ignored) { }\n    }\n    try {\n        db.update("delete from test1.de_data_report_batch_table_t where batch_id = #{batchId} and tenant_id = #{tenantId}")\n    } catch (ignored) { }\n    throw e\n}\nreturn { batchId: batchId, storageDatabase: storageSchema, list: listBatches() }\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/02.数据库表/08.数据上报落库.ms');
