\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577103503826946\\",\\n            \\"ins_time\\": \\"2026-03-11 11:45:01\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577103503826945\\",\\n            \\"ins_time\\": \\"2026-03-11 11:45:01\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577103503826944\\",\\n            \\"ins_time\\": \\"2026-03-11 11:45:01\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577084788842497\\",\\n            \\"ins_time\\": \\"2026-03-11 11:44:56\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577084788842498\\",\\n            \\"ins_time\\": \\"2026-03-11 11:44:56\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577084788842496\\",\\n            \\"ins_time\\": \\"2026-03-11 11:44:56\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031576438559842306\\",\\n            \\"ins_time\\": \\"2026-03-11 11:42:22\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031576438559842305\\",\\n            \\"ins_time\\": \\"2026-03-11 11:42:22\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031576438559842304\\",\\n            \\"ins_time\\": \\"2026-03-11 11:42:22\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568290260295682\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:59\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568290260295681\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:59\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568290260295680\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:59\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568270417043458\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:55\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568270417043457\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:55\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568270417043456\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:55\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        },\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031568239844761600\\",\\n            \\"ins_time\\": \\"2026-03-11 11:09:47\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        }\\n    ]\\n}",\n  "description": "1. 获取上传数据：分全量上传、部分上传；使用请求参数 data。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.上传文件数据(互联网)\n// 路由：POST /dst/catalog/files/upload\n// 业务说明：1. 获取上传数据：分全量上传、部分上传；使用请求参数 data。\n// ============== 互联网数据 --> 公安网数据 ==============\n// 1. 获取上传数据：分全量上传、部分上传\n// 2. 调用公安网插入数据接口\n// 3. 收尾：依据情况执行是否删除已上传数据\n// ========================================================\nimport log;\nimport http;\nimport cn.hutool.core.codec.Base64;\n\nimport request;\nimport "@post:/dst/catalog/detail" as queryById;\nimport "@get:/dst/catalog/files/curd-data" as curdData;\n\n\n// token\nvar token =  token || request.getHeaders("token")[0]\n\n\n// 公安网地址\nvar url = "http://192.168.175.86:8088/"\n\n// 解析请求体并为可选参数设置默认值。\nconst {tid,op,data} = body;\n//全量情况下先初始化、然后批量获取数据（服用查询预览接口）\nif(op=="all"){\n    // 上传全部数据，则需获取表所有数据\n    body.data = [];\n    var { resName, tableId, dbId } = queryById();\n\n    // 表中全部数据\n    var action = "get"\n    var pageNo = 1\n    var pageSize = 9999999\n    var {rows} = curdData();\n\n    // 上传数据\n     body = {\n        tid,\n        data: rows\n    }\n    async http.connect(`${url}dataassets/manage/fileCatalog/upload-ga`)\n           .contentType("application/json")\n            .header({token})\n           .body(body)   \n           .post()\n           .getBody();\n    // 返回当前业务分支的标准结果。\n    return "全量上报提交成功，请耐心等待";\n}\n// -------------------------------生产逻辑-------------------------------------\n// 1. 调外部 POST\n// result = http.connect("http://192.168.39.5:30800/server/forward")\n//            .contentType("application/json")\n//            .header("X-Node-Address", "http://44.1.1.218:81/api/govern/saveToTableGa")\n//            .body(body)      // 直接传 Map，框架自动序列化 JSON\n//            .post()\n//            .getBody()\n// --------------------------------本次调试-------------------------------------\n// 2. 调本地 POST\nlog.debug("params->{}",body);\nvar result = http.connect(`${url}dataassets/manage/fileCatalog/upload-ga`)\n           .contentType("application/json")\n            .header({token})\n           .body(body)   \n           .post()\n           .getBody();\n// 返回当前业务分支的标准结果。\nreturn result.data;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/01.上传文件数据(互联网).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('32ea747d631a40dcaf7a20e0f1daa5ea',NULL,NULL,'{\n  "properties": {},\n  "id": "32ea747d631a40dcaf7a20e0f1daa5ea",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "02.上传文件数据(公安网)",\n  "createTime": 1782955343940,\n  "updateTime": 1784437771722,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/upload-ga",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"b868f2b30a6c4d6aaa23f70627e10b6d\\",\\n    \\"data\\": [\\n        {\\n            \\"drama_length\\": \\"2\\",\\n            \\"drama_theme\\": \\"2\\",\\n            \\"production_permit_number\\": \\"2\\",\\n            \\"drama_name\\": \\"2\\",\\n            \\"cooperation_organization\\": \\"2\\",\\n            \\"unique_id\\": \\"2031577149343375362\\",\\n            \\"ins_time\\": \\"2026-03-11 11:45:11\\",\\n            \\"data_from\\": \\"互联网\\",\\n            \\"upload_user\\": \\"zn\\"\\n        }\\n    ]\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"org.ssssssss.script.exception.MagicScriptException: 找不到函数saveAsset() at Row:56~56,Col:1~11\\\\n\\\\nsaveAsset();\\\\r\\\\n^^^^^^^^^^^  \\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "1. 根据 目录 uuid，表数据，执行插入数据方法。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.上传文件数据(公安网)\n// 路由：POST /dst/catalog/files/upload-ga\n// 业务说明：1. 根据 目录 uuid，表数据，执行插入数据方法。\n// ============== 公安网数据插入 ==============\n// 1. 根据 目录 uuid，表数据，执行插入数据方法\n// ===========================================\n\n\n//下边是公安网逻辑\nimport log;\nimport cn.hutool.core.date.DateUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.codec.Base64;\nimport "@post:/dst/database/metadata/remote-table/data" as remoteTableData;\nimport request;\nimport "@post:/dst/catalog/saveOrUpdate" as saveAsset;\nimport "@post:/dst/catalog/detail" as queryById;\n\n// token\nvar token =  token || request.getHeaders("token")[0]\n\n// 解析请求体并为可选参数设置默认值。\nconst {tid,data} = body;\nlog.debug("接口参数{}",body)\n//校验\nif(is_blank(tid) || (is_null(data) && op !== "all")){\n    // 返回当前业务分支的标准结果。\n    return "必要参数不能为空"\n}\n// 查询目录的库信息\nbody = {tid}\nvar { resName, tableId, dbId } = queryById();\nif (!tableId){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "未建表";\n}\nbody = {tid: dbId}\n// 库\nvar db = queryById(); \nvar datasourceParam = {\n    "host": db.host,\n    "port": db.port.asInt(),\n    "user": db.user,\n    "password": db.password,\n    "database": db.database,\n    "serviceName":db.serviceName, //ORACLE\n    "charset": "UTF-8"\n};\n\n// 插入或更新数据，unique_id为记录唯一id\nvar dataParam = data;\nlog.debug("准备插入的数据对象{}",dataParam);\n\n// ------------------------生产调式逻辑--------------------\n// //插入数据（重置数据并插入版）\n// 更新目录的 recordCount\n\n//------------------------本地调式逻辑--------------------\nbody = {action: "batchResetInsert", dbType: db.dbType, connection: datasourceParam, tableName: resName + "_copy1", rows: dataParam, key: "unique_id"};\nremoteTableData();\n// 更新目录的 recordCount\nbody = {action: "count", dbType: db.dbType, connection: datasourceParam, tableName: resName + "_copy1"};\nvar recordCount = remoteTableData();\nbody = { tid, propList: {recordCount} };\nsaveAsset();\n\n// 返回当前业务分支的标准结果。\nreturn "成功上报"+dataParam.getLength() + "条数据";\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/02.上传文件数据(公安网).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3002ad9de30b4d22ac0644a965f629b7',NULL,NULL,'{\n  "properties": {},\n  "id": "3002ad9de30b4d22ac0644a965f629b7",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "03.下载文件导入模板",\n  "createTime": 1782955343957,\n  "updateTime": 1784437771723,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/download",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": "真实数据示例参数：tid",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "isFull",\n      "value": true,\n      "description": "真实数据示例参数：isFull",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "0",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据数据项下载excel模版, 分空模板、带全量数据模板。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.下载文件导入模板\n// 路由：GET /dst/catalog/files/download\n// 业务说明：根据数据项下载excel模版, 分空模板、带全量数据模板。\n// 根据数据项下载excel模版, 分空模板、带全量数据模板\nimport cn.hutool.core.io.IoUtil;\nimport cn.hutool.poi.excel.ExcelUtil;\nimport cn.hutool.poi.excel.ExcelWriter;\nimport jakarta.servlet.ServletOutputStream;\nimport cn.hutool.core.codec.Base64;\nimport response;\nimport log;\n\nimport "@post:/dst/catalog/detail" as queryById;\nimport "@post:/dst/catalog/catalog-items/list" as getCatalogItem;\nimport "@get:/dst/catalog/files/curd-data" as curdData;\n\n\nvar excel_result = [];\n// 目录\nbody = {tid}\ncols = getCatalogItem();\nvar {resName} = queryById();\n\n// ==== 增量导入模版 ====\nvar items = cols.map(item => item.colName);\nexcel_result.add(items);\n\n// ==== 全量导入模版，额外添加所有表数据 ====\nif (isFull === "1"){\n    var action = "get"\n    var pageNo = 1\n    var pageSize = 9999999\n    var {originRows} = curdData();\n    originRows.each(item => {\n        excel_result.add(item.subList(0, cols.size()))\n    })\n}\n\nExcelWriter writer = ExcelUtil.getWriter(true);\nwriter.write(excel_result, true);\n\nfilename = filename?filename:"excel_export";\nresponse.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=utf-8");\nresponse.setHeader("Content-Disposition","attachment;filename="+resName+".xlsx"); \nServletOutputStream out=response.getOutputStream(); \n\nwriter.flush(out, true);\nwriter.close();\nIoUtil.close(out);\n\n// 返回当前业务分支的标准结果。\nreturn response.end();\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/03.下载文件导入模板.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5753ca0ff70d49c3872694ce10fb438a',NULL,NULL,'{\n  "properties": {},\n  "id": "5753ca0ff70d49c3872694ce10fb438a",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "04.刷新文件元数据",\n  "createTime": 1782955343972,\n  "updateTime": 1784437771725,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/refresh-meta",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": "真实数据示例参数：tid",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"recordCount\\": 0,\\n        \\"fieldCount\\": 5\\n    }\\n}",\n  "description": "数据条数: 查表记录数, 元数据探查。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.刷新文件元数据\n// 路由：GET /dst/catalog/files/refresh-meta\n// 业务说明：数据条数: 查表记录数, 元数据探查。\n// 获取字段数 + 数据条数\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService;\nimport "@post:/dst/database/metadata/remote-table/data" as remoteTableData;\nimport "@post:/dst/catalog/detail" as queryById;\nimport "@post:/dst/catalog/saveOrUpdate" as saveAsset;\nimport "@post:/dst/catalog/catalog-items/list" as getCatalogItem;\n\n// 获取字段数\nbody = {tid}\ncols = getCatalogItem();\nvar fieldCount = cols.size();\n\n\n// 数据条数: 查表记录数, 元数据探查\nvar { resName, tableId, dbId } = queryById();\n\nbody = {tid: dbId}\nvar db = queryById();\nvar datasourceParam = {\n    "host": db.host,\n    "port": db.port.asInt(),\n    "user": db.user,\n    "password": db.password,\n    "database": db.database,\n    "serviceName": db.serviceName, //ORACLE\n    "charset": "UTF-8"\n};\n\nbody = {action: "count", dbType: db.dbType, connection: datasourceParam, tableName: resName};\nvar countSum = remoteTableData();\n\n// 更新目录的 recordCount 和 fieldCount\nvar propList = {recordCount: countSum, fieldCount}\nbody = { tid, propList };\nsaveAsset();\n\n// 返回当前业务分支的标准结果。\nreturn propList;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/04.刷新文件元数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('83f7d0fb43d64b94af7519d90e2ea801',NULL,NULL,'{\n  "properties": {},\n  "id": "83f7d0fb43d64b94af7519d90e2ea801",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "05.同步文件目录(互联网)",\n  "createTime": 1782955343984,\n  "updateTime": 1784437771742,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/sync-catalog",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "uuid",\n      "value": "R-1773133185131",\n      "description": "真实数据示例参数：uuid",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"完成目录唯一标识为R-1773133185131同步\\"\\n}",\n  "description": "1. 请求远程接口传入 uuid 获取 目录信息 与 数据项信息，根据目录 获取库信息。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.同步文件目录(互联网)\n// 路由：GET /dst/catalog/files/sync-catalog\n// 业务说明：1. 请求远程接口传入 uuid 获取 目录信息 与 数据项信息，根据目录 获取库信息。\n// ============== 根据 唯一标识符uuid 将公安网的目录同步到本地 ==============\n// 1. 请求远程接口传入 uuid 获取 目录信息 与 数据项信息，根据目录 获取库信息\n// 2. 本地保存接口保存文件目录和库信息\n// =======================================================================\n\nimport log;\nimport http;\nimport "@post:/dst/catalog/saveOrUpdate" as saveAsset;\nimport "@post:/dst/catalog/list" as assetList;\nimport request;\n\n\n// token\nvar token =  token || request.getHeaders("token")[0]\n\n// 公安网地址\nvar url = "http://192.168.175.86:8088/"\n\n\n// 远程接口\nvar res = http.connect(`${url}dataassets/manage/assets/list`)\n                .contentType("application/json")\n                .header({token})\n                .body({uuid})\n                .post()\n                .getBody();\nvar catalogs = res.data;\nif (!catalogs || catalogs.size() === 0){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "请核实此唯一标识符是否正确";\n}\nvar tid = catalogs[0].tid\n\n// 目录\nres = http.connect(`${url}dataassets/manage/assets/queryById`)\n                .contentType("application/json")\n                .header({token})\n                .body({tid})\n                .post()\n                .getBody();\nvar catalog = res.data\n\n// 目录项\nres = http.connect(`${url}/dst/catalog/catalog-items/list`)\n                .contentType("application/json")\n                .header({token})\n                .body({tid: catalog.tid, token})   \n                .post()\n                .getBody();\nvar catalogItems = res.data;\n\n// 库\nres = http.connect(`${url}dataassets/manage/assets/queryById`)\n                .contentType("application/json")\n                .header({token})\n                .body({tid: catalog.dbId})\n                .post()\n                .getBody();\nvar db = res.data\n\n// 步骤2-保存到本地\nbody = {\n    propList: catalog,\n    catalogItems\n}\nsaveAsset();\n\nbody = {\n    propList: db\n}\nsaveAsset();\n\n\n// 返回当前业务分支的标准结果。\nreturn "完成目录唯一标识为"+uuid+"同步"\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/05.同步文件目录(互联网).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0de479d6e10340358b40c11991375065',NULL,NULL,'{\n  "properties": {},\n  "id": "0de479d6e10340358b40c11991375065",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "06.导入文件数据",\n  "createTime": 1782955343993,\n  "updateTime": 1784437771748,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/import",\n  "method": "POST",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": "真实数据示例参数：tid",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "file",\n      "value": {},\n      "description": "真实数据示例参数：file",\n      "required": false,\n      "dataType": "MultipartFile",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "isFull",\n      "value": null,\n      "description": "真实数据示例参数：isFull",\n      "required": false,\n      "dataType": "Boolean",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"导入成功，若数据较大，请耐心等待\\"\\n}",\n  "description": "校验请求资料后执行导入文件数据，返回保存或配置结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.导入文件数据\n// 路由：POST /dst/catalog/files/import\n// 业务说明：校验请求资料后执行导入文件数据，返回保存或配置结果。\nimport tenantAccounts\nimport log;\nimport "@post:/dst/database/metadata/remote-table/data" as remoteTableData;\nimport cn.hutool.poi.excel.ExcelReader;\nimport cn.hutool.poi.excel.ExcelUtil;\nimport java.io.File;\nimport org.apache.commons.io.FileUtils;\nimport cn.hutool.core.codec.Base64;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.date.DateUtil;\nimport cn.dev33.satoken.stp.StpUtil;\nimport "@post:/sym/user/me" as me;\nimport "@post:/dst/catalog/catalog-items/list" as getCatalogItem;\nimport request;\nimport "@post:/dst/catalog/detail" as queryById;\n\n\n\n//获取用户名称\nvar session =  StpUtil.getTokenSession();\nvar userName = tenantAccounts.session().dataMap.user.userName;\n\nif(!file){\n    // 返回当前业务分支的标准结果。\n    return "文件不存在，请上传文件"\n}\nvar fileName = file.getOriginalFilename();\nvar dotIndex = fileName.lastIndexOf(\'.\');\nif (fileName.substring(dotIndex + 1) !== "xlsx"){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "请上传excel文件"\n}\nvar tempFile = File.createTempFile(fileName.substring(0, dotIndex), "."+fileName.substring(dotIndex + 1));\nFileUtils.writeByteArrayToFile(tempFile, file.getBytes());\nExcelReader reader = ExcelUtil.getReader(tempFile);\nvar rowIndex = 0;\n\n// 目录\nbody = {tid}\ncols = getCatalogItem();\nvar { resName, tableId, dbId } = queryById();\nif (!tableId){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "未建表";\n}\nbody = {tid: dbId}\n// 库\nvar db = queryById(); \nvar datasourceParam = {\n    "host": db.host,\n    "port": db.port.asInt(),\n    "user": db.user,\n    "password": db.password,\n    "database": db.database,\n    "serviceName":db.serviceName, //ORACLE\n    "charset": "UTF-8"\n};\n\n// 读取文件 字段名 字段值\nvar columnNamesEn = [];\nvar values = [];\nreader.read().each(rows => {\n    if(rowIndex == 0){\n    }else{\n        values.add(rows);\n    }\n    rowIndex ++;\n});\nvar result = [];\nvar index = 0;\nvar now = DateUtil.now();\nvalues.each(value => {\n    var data = {};\n    for (col in cols) {\n        data.put(col.colEn, value[index] || "");\n        index++;\n    }\n    data.put("unique_id", IdUtil.getSnowflakeNextIdStr());\n    data.put("ins_time", now);\n    data.put("data_from","互联网"); //互联网\n    data.put("upload_user",userName); //互联网\n    result.add(data);\n    index = 0;\n});\nbody = {action: "batchInsert", dbType: db.dbType, connection: datasourceParam, tableName: resName, rows: result};\nvar insertData = remoteTableData();\nif(isFull){\n    body = {action: "deleteBefore", dbType: db.dbType, connection: datasourceParam, tableName: resName, key: "ins_time", value: now};\n    remoteTableData();\n}\n\n// 返回当前业务分支的标准结果。\nreturn "导入成功，若数据较大，请耐心等待";\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/06.导入文件数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f7f2ee0a5eb5410fbf30a027d48ca8da',NULL,NULL,'{\n  "properties": {},\n  "id": "f7f2ee0a5eb5410fbf30a027d48ca8da",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "07.操作文件数据",\n  "createTime": 1782955344001,\n  "updateTime": 1784437771752,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/curd-data",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "action",\n      "value": "测试",\n      "description": "真实数据示例参数：action",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "get",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": "真实数据示例参数：tid",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "pageNo",\n      "value": null,\n      "description": "真实数据示例参数：pageNo",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "pageSize",\n      "value": null,\n      "description": "真实数据示例参数：pageSize",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "rowId",\n      "value": null,\n      "description": "真实数据示例参数：rowId",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"columns\\": [\\n            \\"drama_length\\",\\n            \\"drama_theme\\",\\n            \\"production_permit_number\\",\\n            \\"drama_name\\",\\n            \\"cooperation_organization\\",\\n            \\"unique_id\\",\\n            \\"ins_time\\",\\n            \\"data_from\\",\\n            \\"upload_user\\"\\n        ],\\n        \\"rows\\": [\\n            {\\n                \\"drama_length\\": \\"2\\",\\n                \\"drama_theme\\": \\"2\\",\\n                \\"production_permit_number\\": \\"2\\",\\n                \\"drama_name\\": \\"2\\",\\n                \\"cooperation_organization\\": \\"2\\",\\n                \\"unique_id\\": \\"2031255854370103296\\",\\n                \\"ins_time\\": \\"2026-03-10 14:28:29\\",\\n                \\"data_from\\": \\"互联网\\",\\n                \\"upload_user\\": \\"zn\\"\\n            },\\n            {\\n                \\"drama_length\\": \\"2\\",\\n                \\"drama_theme\\": \\"2\\",\\n                \\"production_permit_number\\": \\"2\\",\\n                \\"drama_name\\": \\"2\\",\\n                \\"cooperation_organization\\": \\"2\\",\\n                \\"unique_id\\": \\"2031255815962861568\\",\\n                \\"ins_time\\": \\"2026-03-10 14:28:20\\",\\n                \\"data_from\\": \\"互联网\\",\\n                \\"upload_user\\": \\"zn\\"\\n            },\\n            {\\n                \\"drama_length\\": \\"2\\",\\n                \\"drama_theme\\": \\"2\\",\\n                \\"production_permit_number\\": \\"2\\",\\n                \\"drama_name\\": \\"2\\",\\n                \\"cooperation_organization\\": \\"2\\",\\n                \\"unique_id\\": \\"2031255272083267584\\",\\n                \\"ins_time\\": \\"2026-03-10 14:26:10\\",\\n                \\"data_from\\": \\"互联网\\",\\n                \\"upload_user\\": \\"zn\\"\\n            }\\n        ]\\n    }\\n}",\n  "description": "按文件目录标识读取数据项和目标表，区分数据预览与增删改操作，并将请求转发至对应的数据表接口。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.操作文件数据\n// 路由：GET /dst/catalog/files/curd-data\n// 业务说明：按文件目录标识读取数据项和目标表，区分数据预览与增删改操作，并将请求转发至对应的数据表接口。\n// 数据预览\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService;\nimport "@post:/dst/catalog/detail" as queryById;\nimport "@post:/dst/catalog/catalog-items/list" as getCatalogItem;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService;\nimport "@post:/dst/database/metadata/remote-table/data" as remoteTableData;\nimport "@get:/dst/catalog/files/create-table" as createTable;\n\n// 获取字段数\nbody = {tid}\ncols = getCatalogItem();\nvar { resName, tableId, dbId } = queryById();\n\nif (!tableId){\n  createTable();\n}\n\nbody = {tid: dbId}\nvar db = queryById();\nvar datasourceParam = {\n    "host": db.host,\n    "port": db.port.asInt(),\n    "user": db.user,\n    "password": db.password,\n    "database": db.database,\n    "serviceName": db.serviceName, //ORACLE\n    "charset": "UTF-8"\n};\n\n// ==== 查询 ====\nif(action == \'get\'){\n    body = {action: "preview", dbType: db.dbType, connection: datasourceParam, tableName: resName, pageNo: pageNo || 1, pageSize: pageSize || 20, sortField: "ins_time", sortDirection: "DESC"};\n    result = remoteTableData();\n    var { columns, rows } = result;\n    var formattedRows = rows.map(row => {\n        var obj = {};\n        columns.each((key, index) => {\n            obj[key] = row[index];\n        });\n        // 返回当前业务分支的标准结果。\n        return obj;\n    });\n    body = {action: "count", dbType: db.dbType, connection: datasourceParam, tableName: resName};\n    var total = remoteTableData();\n    // 返回当前业务分支的标准结果。\n    return {\n        columns, \n        rows: formattedRows,\n        originRows,\n        total\n    }\n}\n\n// ==== 删除记录 ====\nif(action == \'delete\'){\n    if (!rowId){\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit -1, "传入删除记录项唯一ID"\n    }\n    body = {action: "deleteByValues", dbType: db.dbType, connection: datasourceParam, tableName: resName, key: db.dbType !== "oracle" ? "unique_id" : "UNIQUE_ID", values: [rowId]};\n    result = remoteTableData();\n    // 返回当前业务分支的标准结果。\n    return result;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/07.操作文件数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('28ab37e70de24570a2015c72d289ec89',NULL,NULL,'{\n  "properties": {},\n  "id": "28ab37e70de24570a2015c72d289ec89",\n  "script": null,\n  "groupId": "ae2bf97ab5e84d0c8c9bbd063d292c59",\n  "name": "08.文件数据物化建表",\n  "createTime": 1782955344009,\n  "updateTime": 1784437771755,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/create-table",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "tid",\n      "value": "85368b91972c4a35b83b8fa73e34e740",\n      "description": "真实数据示例参数：tid",\n      "required": true,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": "pass",\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [\n    {\n      "name": "tid",\n      "value": "b868f2b30a6c4d6aaa23f70627e10b6d",\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 400,\\n    \\"msg\\": \\"参数[tid]为必填项\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "根据文件目录数据项+resName，指定dbId建表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "已建表，无需再建",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：08.文件数据物化建表\n// 路由：GET /dst/catalog/files/create-table\n// 业务说明：根据文件目录数据项+resName，指定dbId建表。\n// 根据文件目录数据项+resName，指定dbId建表\nimport "@post:/dst/database/metadata/getCreateTableDDL" as getCreateTableDDL;\nimport "@post:/dst/database/metadata/createTable" as createTable;\nimport "@post:/dst/catalog/catalog-items/list" as getCatalogItem;\nimport "@post:/dst/catalog/detail" as queryById;\nimport "@post:/dst/catalog/saveOrUpdate" as saveAsset;\n\n// 1.查询 文件目录项 resName tableId\nbody = {tid}\nvar { resName, tableId, dbId, fileCatalogName } = queryById();\nvar cols = getCatalogItem();\nif (tableId){\n  // 返回当前业务分支的标准结果。\n  return "已建表，无需再建";\n}\ncols = cols.map(el => ({\n    "columnName": el.colEn,\n    "columnComment": el.colName,\n    "dataType": "varchar",\n    "columnType": `varchar(${el.colLength || 255})`,\n    "length": el.colLength || 255,\n    "precisionLength": 0,\n    "scale": 0,\n    "nullable": el.isNullable == 0 ? false : true,\n    "defaultValue": null,\n    "primaryKey": el.isPk ? el.isPk : 0,\n    "autoIncrement": 0,\n    "isUnique": el.isPk ? el.isPk : 0,\n    "indexed": el.isPk ? el.isPk : 0,\n    "ordinalPosition": el.sortNo ? el.sortNo : 0,\n    "charset": "utf8mb4",\n    "collation": "utf8mb4_general_ci",\n    "extra": null\n}))\n// 增加字段：unique_id ins_time data_from upload_user\nvar otherCols = [\n    {colName: "唯一标识符", colEn: "unique_id"},\n    {colName: "入库时间", colEn: "ins_time"},\n    {colName: "数据来源", colEn: "data_from"},\n    {colName: "上报单位用户", colEn: "upload_user"},\n]\nvar i = cols.size();\notherCols.each(item => {\n    cols.push({\n        "columnName": item.colEn,\n        "columnComment": item.colName,\n        "dataType": "varchar",\n        "columnType": `varchar(255)`,\n        "length": 255,\n        "precisionLength": 0,\n        "scale": 0,\n        "nullable": 0,\n        "defaultValue": null,\n        "primaryKey": 0,\n        "autoIncrement": 0,\n        "isUnique": 0,\n        "indexed": 0,\n        "ordinalPosition": i++,\n        "charset": "utf8mb4",\n        "collation": "utf8mb4_general_ci",\n        "extra": null\n    })\n})\n\n\n// 2.获取建表ddl\nbody = {\n    "propList":{\n        dbId, tableName: resName, tableNameCn: fileCatalogName\n    },\n    "tableItems": cols\n}\nconst ddl = getCreateTableDDL();\n\n\n// 3.建表\ndbId = "badb2b8bbb8248049780884f4b1930b5";\nbody = { ddl, dbId };\ncreateTable();\n\n// 建表成功更新目录的 tableId 和 dbId，标识建表成功\nbody = { tid, propList:{tableId: resName, dbId} };\nsaveAsset();\n\n// 返回当前业务分支的标准结果。\nreturn {\n    tableId: resName\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/08.文件数据物化建表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ae2bf97ab5e84d0c8c9bbd063d292c59',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "ae2bf97ab5e84d0c8c9bbd063d292c59",\r\n  "name" : "02.文件资源管理",\r\n  "type" : "api",\r\n  "parentId" : "datapd_catalog_group_01",\r\n  "path" : "/files",\r\n  "createTime" : 1784420517826,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/02.文件资源管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_page_compat_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_catalog_page_compat_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "03.数据目录分页",\n  "createTime": null,\n  "updateTime": 1790484171436,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"conditions\\": []\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"total\\":0,\\"list\\":[]}",\n  "description": "数据目录分页接口（POST /dst/catalog/page）。目录、树统计和详情统一读取 da_catalog_t；使用请求参数 conditions、keyword、statisticsOnly、pageNum、pageSize、sortField、sortDir。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据目录分页\n// 路由：POST /dst/catalog/page\n// 业务说明：数据目录分页接口（POST /dst/catalog/page）。目录、树统计和详情统一读取 da_catalog_t；使用请求参数 conditions、keyword、statisticsOnly、pageNum、pageSize、sortField、sortDir。\nimport tenantRuntime\nimport java.util.LinkedHashMap\nimport java.util.ArrayList\nimport java.util.List\n\n/* 数据目录分页（只读）：da_catalog_t 为权威来源，不以源表登记状态作为准入条件。\n * 组织树统计复用同一查询条件。所有主表、属性和关联对象均限制在登录租户内。\n * 不补建目录，不修改源表；分页仅加载当前页及该页动态属性。\n */\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar blank = value => text(value) == \'\'\nvar sqlValue = value => "\'" + text(value).replace("\'", "\'\'") + "\'"\nvar rowValue = (row, keys) => {\n  for (key in keys) {\n    if (row != null && row[key] != null) { return row[key] }\n  }\n  return null\n}\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'当前登录租户无效，请重新登录\' }\nvar propExpr = name => "(select p.prop_value from da_prop_t p where p.tenant_id=c.tenant_id and p.parent_id=c.tid and p.data_type=\'catalog\' and ifnull(p.is_del,0)=0 and p.prop_name=" + sqlValue(name) + " order by p.updated_time desc,p.tid desc limit 1)"\nvar fields = {\n  tid:\'c.tid\', tenantId:\'c.tenant_id\', assetStatus:\'c.asset_status\', flowStatus:\'c.flow_status\',\n  regTime:\'c.reg_time\', createdTime:\'c.created_time\', updatedTime:\'c.updated_time\',\n  catalogName:\'c.catalog_name\', catalogNameEn:\'c.catalog_name_en\', assetDesc:\'c.asset_desc\',\n  appId:\'c.app_id\', dbId:\'c.db_id\', sourceTableId:\'c.source_table_id\', sourceTableName:\'c.source_table_name\',\n  orgId:\'c.org_id\', manageUnit:\'c.manage_unit\', businessType:\'c.business_type\', timestampField:\'c.timestamp_field\',\n  dictionaryTableFlag:\'c.dictionary_table_flag\',\n  appName:"coalesce(nullif(c.app_name,\'\'),a.app_name)",\n  dbName:"coalesce(nullif(c.db_name,\'\'),d.db_name)",\n  dataSourceType:"coalesce(nullif(c.data_source_type,\'\')," + propExpr(\'dataSourceType\') + ",\'ods\')",\n  dataLevel:propExpr(\'dataLevel\'), shareType:propExpr(\'shareType\')\n}\nvar fromSql = " from da_catalog_t c left join sym_application_t a on a.tid=c.app_id and a.tenant_id=c.tenant_id and ifnull(a.is_del,0)=0 left join db_datasource_t d on d.tid=c.db_id and d.tenant_id=c.tenant_id and ifnull(d.is_del,0)=0 "\nvar whereSql = " where c.tenant_id=" + sqlValue(tenantId) + " and ifnull(c.is_del,0)=0 "\nvar conditions = body == null || body.conditions == null ? [] : body.conditions\nfor (condition in conditions) {\n  if (condition == null || blank(condition.field) || condition.value == null || text(condition.value) == \'\') { continue }\n  var field = text(condition.field)\n  if (field == \'assetType\') {\n    if (text(condition.value) != \'catalog\') { whereSql = whereSql + \' and 1=0 \' }\n    continue\n  }\n  if (field == \'orgIds\') { field = \'orgId\' }\n  if (fields[field] == null) { exit 400, \'不支持的数据目录筛选字段：\' + field }\n  var expr = fields[field]\n  var type = text(condition.type).toLowerCase()\n  if (type == \'in\') {\n    var values = condition.value\n    if (!(values instanceof List)) { exit 400, \'多值筛选必须传入数组\' }\n    if (values.size() == 0) { whereSql = whereSql + \' and 1=0 \'; continue }\n    whereSql = whereSql + \' and \' + expr + \' in (\' + values.map(v => sqlValue(v)).join(\',\') + \')\'\n  } else if (type == \'like\') {\n    // 名称查询同时匹配关联数据资源；instr 将用户的 %/_ 当作普通字符。\n    if (field == \'catalogName\') {\n      whereSql = whereSql + \' and (instr(lower(ifnull(\' + fields.catalogName + ",\'\')),lower(" + sqlValue(condition.value) + \'))>0 or instr(lower(ifnull(\' + fields.sourceTableName + ",\'\')),lower(" + sqlValue(condition.value) + \'))>0)\'\n    } else {\n      whereSql = whereSql + \' and instr(lower(ifnull(\' + expr + ",\'\')),lower(" + sqlValue(condition.value) + \'))>0\'\n    }\n  } else if (type == \'\' || type == \'match\' || type == \'eq\') {\n    whereSql = whereSql + \' and \' + expr + \'=\' + sqlValue(condition.value)\n  } else { exit 400, \'不支持的数据目录筛选方式：\' + type }\n}\nvar keyword = body == null ? \'\' : text(body.keyword)\nif (keyword != \'\') {\n  whereSql = whereSql + \' and (instr(lower(ifnull(\' + fields.catalogName + ",\'\')),lower(" + sqlValue(keyword) + \'))>0 or instr(lower(ifnull(\' + fields.sourceTableName + ",\'\')),lower(" + sqlValue(keyword) + \'))>0)\'\n}\n\n// 同一目录集合生成树统计，避免“树显示数量”和“点击后的列表”口径分裂。\nif (body != null && body.statisticsOnly == true) {\n  var rows = db.select(\'select c.org_id orgId,c.app_id appId,\' + fields.appName + \' appName,c.db_id dbId,\' + fields.dbName + \' dbName,d.db_type dbType,count(1) total\' + fromSql + whereSql + \' group by c.org_id,c.app_id,c.app_name,a.app_name,c.db_id,c.db_name,d.db_name,d.db_type\')\n  var total = 0\n  var orgCounts = new LinkedHashMap()\n  var appMap = new LinkedHashMap()\n  for (row in rows) {\n    var count = rowValue(row,[\'total\',\'TOTAL\'])::int\n    total = total + count\n    var orgId = text(rowValue(row,[\'orgId\',\'orgid\',\'ORGID\']))\n    var appId = text(rowValue(row,[\'appId\',\'appid\',\'APPID\']))\n    if (orgId == \'\') { continue }\n    orgCounts[orgId] = (orgCounts[orgId] == null ? 0 : orgCounts[orgId]) + count\n    if (appId == \'\') { continue }\n    if (appMap[orgId] == null) { appMap[orgId] = new LinkedHashMap() }\n    if (appMap[orgId][appId] == null) {\n      var appName = text(rowValue(row,[\'appName\',\'appname\',\'APPNAME\']))\n      appMap[orgId][appId] = { label: appName == \'\' ? \'未命名业务系统\' : appName, value:appId, type:\'app\', count:0, datasources:[] }\n    }\n    var app = appMap[orgId][appId]\n    app.count = app.count + count\n    var dbId = text(rowValue(row,[\'dbId\',\'dbid\',\'DBID\']))\n    if (dbId != \'\') {\n      app.datasources.add({label:rowValue(row,[\'dbName\',\'dbname\',\'DBNAME\']),value:dbId,count:count,dbType:rowValue(row,[\'dbType\',\'dbtype\',\'DBTYPE\'])})\n    }\n  }\n  var orgApps = new LinkedHashMap()\n  for (orgId in appMap.keySet()) { orgApps[orgId] = new ArrayList(appMap[orgId].values()) }\n  return { total:total, orgCounts:orgCounts, orgApps:orgApps }\n}\n\nvar pageNum = body == null || body.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body == null || body.pageSize == null ? 20 : body.pageSize::int\nif (pageNum < 1) { pageNum = 1 }\nif (pageSize < 1) { pageSize = 20 }\nif (pageSize > 100) { pageSize = 100 }\nvar countRows = db.select(\'select count(1) total\' + fromSql + whereSql)\nvar total = rowValue(countRows[0],[\'total\',\'TOTAL\'])::int\nvar sortField = body == null ? \'\' : text(body.sortField)\nif (![\'updatedTime\',\'createdTime\',\'regTime\',\'catalogName\',\'tid\'].contains(sortField)) { sortField = \'updatedTime\' }\nvar sortDir = body != null && text(body.sortDir).toLowerCase() == \'asc\' ? \'asc\' : \'desc\'\nvar columns = []\nfor (field in fields.keySet()) { columns.add(fields[field] + \' \' + field) }\nvar rows = db.select(\'select \' + columns.join(\',\') + fromSql + whereSql + \' order by \' + fields[sortField] + \' \' + sortDir + \',c.tid \' + sortDir + \' limit \' + ((pageNum-1)*pageSize) + \',\' + pageSize)\nvar list = []\nvar ids = []\nvar itemMap = {}\nfor (row in rows) {\n  var item = {assetType:\'catalog\',props:{}}\n  for (field in fields.keySet()) { item[field] = rowValue(row,[field,field.toLowerCase(),field.toUpperCase()]) }\n  item.id = item.tid\n  item.displayStatus = item.flowStatus == 1 ? 1 : item.assetStatus\n  list.add(item)\n  ids.add(sqlValue(item.tid))\n  itemMap[text(item.tid)] = item\n}\nif (ids.size() > 0) {\n  var props = db.select("select parent_id parentId,prop_name propName,prop_value propValue from da_prop_t where tenant_id=" + sqlValue(tenantId) + " and ifnull(is_del,0)=0 and data_type=\'catalog\' and parent_id in (" + ids.join(\',\') + \') order by updated_time,tid\')\n  for (prop in props) {\n    var item = itemMap[text(rowValue(prop,[\'parentId\',\'parentid\',\'PARENTID\']))]\n    var name = text(rowValue(prop,[\'propName\',\'propname\',\'PROPNAME\']))\n    if (item == null || name == \'\') { continue }\n    var value = rowValue(prop,[\'propValue\',\'propvalue\',\'PROPVALUE\'])\n    item.props[name] = value\n    // 身份、状态以及组织归属仅以主表为准；动态属性补全其余表单内容。\n    if (![\'tid\',\'id\',\'tenantId\',\'assetType\',\'assetStatus\',\'flowStatus\',\'orgId\',\'appId\',\'dbId\',\'sourceTableId\',\'displayStatus\',\'props\'].contains(name) && blank(item[name])) { item[name] = value }\n  }\n}\nreturn {pageNum:pageNum,pageSize:pageSize,total:total,list:list}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/03.数据目录分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_detail_compat_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_catalog_detail_compat_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "04.数据目录详情",\n  "createTime": null,\n  "updateTime": 1787153759311,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2086383506325794816\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"tid\\": \\"2086383506325794816\\",\\n  \\"catalogName\\": \\"公安案件登记业务表\\"\\n}",\n  "description": "数据目录详情兼容接口（POST /dst/catalog/detail）。统一从 da_catalog_t 与 da_prop_t 读取登记完成的源头数据目录；使用请求参数 tid、id。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.数据目录详情\n// 路由：POST /dst/catalog/detail\n// 业务说明：数据目录详情兼容接口（POST /dst/catalog/detail）。统一从 da_catalog_t 与 da_prop_t 读取登记完成的源头数据目录；使用请求参数 tid、id。\n// 数据目录详情：处理 POST /detail 的核心查询和组装返回数据逻辑。\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || text(value).trim() == \'\'\nvar sqlValue = value => "\'" + text(value).replace("\'", "\'\'") + "\'"\nvar rowValue = (row, keys) => {\n    for (key in keys) {\n        if (row != null && row[key] != null) {\n            return row[key]\n        }\n    }\n    return null\n}\n\nvar tid = body == null ? null : (blank(body.tid) ? body.id : body.tid)\nif (blank(tid)) {\n    exit 400, \'目录标识不能为空\'\n}\n\nvar rows = db.select(\n    "select c.tid,c.tenant_id tenantId,c.asset_status assetStatus,c.flow_status flowStatus," +\n    "c.reg_time regTime,c.created_time createdTime,c.updated_time updatedTime," +\n    "c.catalog_name catalogName,c.catalog_name_en catalogNameEn,c.asset_desc assetDesc," +\n    "c.app_id appId,c.app_name appName,c.db_id dbId,c.db_name dbName," +\n    "c.source_table_id sourceTableId,c.source_table_name sourceTableName," +\n    "c.source_db_id sourceDbId,c.source_db_name sourceDbName," +\n    "c.target_table_id targetTableId,c.target_table_name targetTableName,c.target_db_id targetDbId,c.target_db_type targetDbType," +\n    "c.org_id orgId,c.manage_unit manageUnit,c.business_type businessType,c.data_source_type dataSourceType," +\n    "c.timestamp_field timestampField,c.dictionary_table_flag dictionaryTableFlag,c.field_governance_config fieldGovernanceConfig " +\n    "from da_catalog_t c where ifnull(c.is_del,0)=0 and c.tid=" + sqlValue(tid) + " limit 1")\nif (rows == null || rows.size() == 0) {\n    exit 404, \'数据目录不存在或已删除\'\n}\n\nvar row = rows[0]\nvar item = {\n    tid: rowValue(row, [\'tid\']), id: rowValue(row, [\'tid\']), tenantId: rowValue(row, [\'tenantId\', \'tenantid\']),\n    assetType: \'catalog\', assetStatus: rowValue(row, [\'assetStatus\', \'assetstatus\']), flowStatus: rowValue(row, [\'flowStatus\', \'flowstatus\']),\n    regTime: rowValue(row, [\'regTime\', \'regtime\']), createdTime: rowValue(row, [\'createdTime\', \'createdtime\']), updatedTime: rowValue(row, [\'updatedTime\', \'updatedtime\']),\n    catalogName: rowValue(row, [\'catalogName\', \'catalogname\']), catalogNameEn: rowValue(row, [\'catalogNameEn\', \'catalognameen\']), assetDesc: rowValue(row, [\'assetDesc\', \'assetdesc\']),\n    appId: rowValue(row, [\'appId\', \'appid\']), appName: rowValue(row, [\'appName\', \'appname\']), dbId: rowValue(row, [\'dbId\', \'dbid\']), dbName: rowValue(row, [\'dbName\', \'dbname\']),\n    sourceTableId: rowValue(row, [\'sourceTableId\', \'sourcetableid\']), sourceTableName: rowValue(row, [\'sourceTableName\', \'sourcetablename\']),\n    sourceDbId: rowValue(row, [\'sourceDbId\', \'sourcedbid\']), sourceDbName: rowValue(row, [\'sourceDbName\', \'sourcedbname\']),\n    targetTableId: rowValue(row, [\'targetTableId\', \'targettableid\']), targetTableName: rowValue(row, [\'targetTableName\', \'targettablename\']),\n    targetDbId: rowValue(row, [\'targetDbId\', \'targetdbid\']), targetDbType: rowValue(row, [\'targetDbType\', \'targetdbtype\']),\n    orgId: rowValue(row, [\'orgId\', \'orgid\']), manageUnit: rowValue(row, [\'manageUnit\', \'manageunit\']), businessType: rowValue(row, [\'businessType\', \'businesstype\']),\n    dataSourceType: rowValue(row, [\'dataSourceType\', \'datasourcetype\']), timestampField: rowValue(row, [\'timestampField\', \'timestampfield\']),\n    dictionaryTableFlag: rowValue(row, [\'dictionaryTableFlag\', \'dictionarytableflag\']), fieldGovernanceConfig: rowValue(row, [\'fieldGovernanceConfig\', \'fieldgovernanceconfig\'])\n}\nitem.asset_type = item.assetType\nitem.asset_status = item.assetStatus\nitem.flow_status = item.flowStatus\n\nvar props = {}\nvar propRows = db.select("select prop_name propName,prop_value propValue from da_prop_t where ifnull(is_del,0)=0 and data_type=\'catalog\' and parent_id=" + sqlValue(tid))\nfor (prop in propRows) {\n    var name = rowValue(prop, [\'propName\', \'propname\'])\n    var value = rowValue(prop, [\'propValue\', \'propvalue\'])\n    if (!blank(name)) {\n        props[name] = value\n        if (item[name] == null || item[name] == \'\') {\n            item[name] = value\n        }\n    }\n}\nitem.props = props\nreturn item\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/04.数据目录详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cat_org_tree_compat_01',NULL,NULL,'{\n  "properties": {},\n  "id": "cat_org_tree_compat_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "05.组织业务系统数据库树",\n  "createTime": 1784769000000,\n  "updateTime": 1787153759350,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/organization-tree",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"parentId\\": \\"2026503859392086017\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[{\\"id\\":\\"机构ID\\",\\"label\\":\\"机构名称\\",\\"value\\":\\"机构ID\\",\\"children\\":[],\\"catalogNum\\":0}]",\n  "description": "组织业务系统数据库树兼容接口（POST /dst/catalog/organization-tree）。只读接口；读取 SSO 组织树、sym_application_t、db_datasource_t、da_asset_t 与 da_prop_t，返回数据接入/数据汇聚页面左侧树；请求示例 parentId 来自当前用户根机构。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.组织业务系统数据库树\n// 路由：POST /dst/catalog/organization-tree\n// 业务说明：组织业务系统数据库树兼容接口（POST /dst/catalog/organization-tree）。只读接口；读取 SSO 组织树、sym_application_t、db_datasource_t、da_asset_t 与 da_prop_t，返回数据接入/数据汇聚页面左侧树；请求示例 parentId 来自当前用户根机构。\nimport tenantRuntime\nimport java.util.Map\n\n/* 数据目录树：部门 → 应用系统 → 已完成登记的数据源，仅统计可自动生成目录的已登记表。 */\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar blank = value => text(value) == \'\'\nvar first = (row, keys) => {\n  for (key in keys) {\n    if (row != null && row[key] != null) {\n      return row[key]\n    }\n  }\n  return null\n}\nvar tenantId=text(tenantRuntime.id())\nif (tenantId == \'\') {\n  exit 401, \'当前登录租户无效，请重新登录\'\n}\nvar parentId=body==null?null:body.parentId\nif (blank(parentId)) {\n  exit 400, \'parentId不能为空\'\n}\nvar counts={}\nfor(row in db.select("select t.datasource_id db_id,d.app_id,count(1) catalog_num from db_table_t t join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=t.tenant_id where t.tenant_id=\'"+tenantId+"\' and ifnull(t.is_del,0)=0 and ifnull(d.is_del,0)=0 and t.asset_status=2 and t.flow_status=2 and d.asset_status=2 and ifnull(d.is_enable,1)=1 group by t.datasource_id,d.app_id")){counts[text(first(row,[\'dbId\',\'db_id\']))]={appId:text(first(row,[\'appId\',\'app_id\'])),count:(first(row,[\'catalogNum\',\'catalog_num\'])+\'\')::int}}\nvar orgRows=db.table(\'rm_org_t\').where().eq(\'deleted\',0).select()\nvar rows=[]\nvar orgIds={}\nfor (org in orgRows) {\n  var oid=text(first(org,[\'id\',\'tid\',\'orgId\',\'org_id\']))\n  if (oid == \'\') {\n    continue\n  }\n  var node={}\n  node.putAll(org)\n  node.id=oid\n  node.value=oid\n  node.label=first(org,[\'name\',\'orgName\',\'org_name\'])\n  node.type=\'org\'\n  node.children=[]\n  node.catalogNum=0\n  rows.add(node)\n  orgIds[oid]=true\n}\nvar apps={}\nvar appCounts={}\nfor (sourceId in counts.keySet()) {\n  var appId=counts[sourceId].appId\n  if (appId != \'\') {\n    appCounts[appId]=(appCounts[appId]||0)+counts[sourceId].count\n  }\n}\nfor (app in db.table(\'sym_application_t\').where().eq(\'tenant_id\',tenantId).eq(\'is_del\',0).select()) {\n  var appId=text(first(app,[\'tid\',\'id\']))\n  var orgId=text(first(app,[\'orgId\',\'org_id\',\'departId\']))\n  if (appCounts[appId] == null || orgIds[orgId] == null) {\n    continue\n  }\n  var node={id:appId,tid:appId,parentId:orgId,value:appId,label:first(app,[\'appName\',\'app_name\']),name:first(app,[\'appName\',\'app_name\']),type:\'app\',children:[],catalogNum:appCounts[appId]}\n  rows.add(node)\n  apps[appId]=node\n}\nfor (source in db.table(\'db_datasource_t\').where().eq(\'tenant_id\',tenantId).eq(\'is_del\',0).eq(\'asset_status\',2).eq(\'is_enable\',1).select()) {\n  var sourceId=text(first(source,[\'tid\',\'id\']))\n  var info=counts[sourceId]\n  var appId=text(first(source,[\'appId\',\'app_id\']))\n  if (info == null || apps[appId] == null) {\n    continue\n  }\n  rows.add({id:sourceId,tid:sourceId,parentId:appId,value:sourceId,label:first(source,[\'dbName\',\'db_name\']),name:first(source,[\'dbName\',\'db_name\']),type:\'db\',dbType:first(source,[\'dbType\',\'db_type\']),children:[],catalogNum:info.count})\n}\nvar toTree\ntoTree=(pid)=>{\n  var result=[]\n  for (row in rows) {\n    if (text(first(row,[\'parentId\',\'parent_id\',\'pid\'])) == text(pid)) {\n      row.children=toTree(first(row,[\'id\']))\n      result.add(row)\n    }\n  }\n  return result\n}\nvar rollup\nrollup=(nodes)=>{\n  var total=0\n  for (node in nodes) {\n    var child=rollup(node.children||[])\n    var own=(node.catalogNum||0)::int\n    node.catalogNum=own>child?own:child\n    total=total+node.catalogNum\n  }\n  return total\n}\nvar tree=toTree(parentId)\nrollup(tree)\nreturn tree\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/05.组织业务系统数据库树.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_tree_stats_01',NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_catalog_tree_stats_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "06.数据目录树统计",\n  "createTime": null,\n  "updateTime": 1790484211140,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/treeStatistics",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"orgIds\\":[]}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"total\\":0,\\"orgCounts\\":{},\\"orgApps\\":{}}",\n  "description": "数据目录树统计。以 da_catalog_t 已完成目录为唯一真值，返回组织、业务系统和数据源下的目录数量；使用请求参数 conditions、orgIds、keyword。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.数据目录树统计\n// 路由：POST /dst/catalog/treeStatistics\n// 业务说明：数据目录树统计。以 da_catalog_t 已完成目录为唯一真值，返回组织、业务系统和数据源下的目录数量；使用请求参数 conditions、orgIds、keyword。\nimport \'@post:/dst/catalog/page\' as catalogPage\nimport java.util.ArrayList\n\n/* 只读目录统计：与目录分页共用同一份租户范围、动态属性及筛选逻辑。 */\nvar conditions = body == null || body.conditions == null ? [] : new ArrayList(body.conditions)\nif (body != null && body.orgIds != null && body.orgIds.size() > 0) {\n  conditions.add({field:\'orgIds\',value:body.orgIds,type:\'in\'})\n}\nbody = {statisticsOnly:true,conditions:conditions,keyword:body == null ? \'\' : body.keyword}\nreturn catalogPage()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/06.数据目录树统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_items_list_01',NULL,'api','{\n  "properties": {},\n  "id": "datapd_catalog_items_list_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "07.数据目录数据项列表",\n  "path": "/catalog-items/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2086383506325794816\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "数据目录数据项列表（POST /dst/catalog/catalog-items/list）。读取 da_catalog_item_t，供目录详情、登记和文件目录兼容调用；使用请求参数 catalogId、tid、id。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.数据目录数据项列表\n// 路由：POST /dst/catalog/catalog-items/list\n// 业务说明：数据目录数据项列表（POST /dst/catalog/catalog-items/list）。读取 da_catalog_item_t，供目录详情、登记和文件目录兼容调用；使用请求参数 catalogId、tid、id。\n// 数据目录数据项列表：处理 POST /catalog-items/list 的核心查询和组装返回数据逻辑。\nimport cn.hutool.json.JSONUtil as jsons\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || text(value).trim() == \'\'\nvar sqlValue = value => "\'" + text(value).replace("\'", "\'\'") + "\'"\nvar rowValue = (row, keys) => {\n    for (key in keys) {\n        if (row != null && row[key] != null) {\n            return row[key]\n        }\n    }\n    return null\n}\n\nvar catalogId = body == null ? null : (blank(body.catalogId) ? (blank(body.tid) ? body.id : body.tid) : body.catalogId)\nif (blank(catalogId)) {\n    exit 400, \'目录标识不能为空\'\n}\nvar rows = db.select(\n    "select tid,catalog_id catalogId,tenant_id tenantId,col_name colName,col_en colEn,col_type colType,col_comment colComment," +\n    "col_length colLength,is_pk isPk,is_masking isMasking,is_fk isFk,is_nullable isNullable,date_format dateFormat," +\n    "mark_lvl markLvl,col_unit colUnit,col_precision colPrecision,masking_id maskingId,sort_no sortNo,share_type shareType," +\n    "share_condition shareCondition,is_dict isDict,dict_name dictName,col_max_length colMaxLength,default_value defaultValue," +\n    "data_standard_id dataStandardId,quality_rule qualityRule,enable_code_table enableCodeTable,code_table_id codeTableId," +\n    "source_table_column_id sourceTableColumnId,target_table_column_id targetTableColumnId " +\n    "from da_catalog_item_t where ifnull(is_del,0)=0 and catalog_id=" + sqlValue(catalogId) + " order by ifnull(sort_no,2147483647),created_time,tid")\nvar items = []\nfor (row in rows) {\n    items.add({\n        tid: rowValue(row, [\'tid\']), catalogId: rowValue(row, [\'catalogId\', \'catalogid\']), tenantId: rowValue(row, [\'tenantId\', \'tenantid\']),\n        colName: rowValue(row, [\'colName\', \'colname\']), colEn: rowValue(row, [\'colEn\', \'colen\']), colType: rowValue(row, [\'colType\', \'coltype\']),\n        colComment: rowValue(row, [\'colComment\', \'colcomment\']), colLength: rowValue(row, [\'colLength\', \'collength\']), isPk: rowValue(row, [\'isPk\', \'ispk\']),\n        isMasking: rowValue(row, [\'isMasking\', \'ismasking\']), isFk: rowValue(row, [\'isFk\', \'isfk\']), isNullable: rowValue(row, [\'isNullable\', \'isnullable\']),\n        dateFormat: rowValue(row, [\'dateFormat\', \'dateformat\']), markLvl: rowValue(row, [\'markLvl\', \'marklvl\']), colUnit: rowValue(row, [\'colUnit\', \'colunit\']),\n        colPrecision: rowValue(row, [\'colPrecision\', \'colprecision\']), maskingId: rowValue(row, [\'maskingId\', \'maskingid\']), sortNo: rowValue(row, [\'sortNo\', \'sortno\']),\n        shareType: rowValue(row, [\'shareType\', \'sharetype\']), shareCondition: rowValue(row, [\'shareCondition\', \'sharecondition\']),\n        isDict: rowValue(row, [\'isDict\', \'isdict\']), dictName: rowValue(row, [\'dictName\', \'dictname\']), colMaxLength: rowValue(row, [\'colMaxLength\', \'colmaxlength\']),\n        defaultValue: rowValue(row, [\'defaultValue\', \'defaultvalue\']), dataStandardId: rowValue(row, [\'dataStandardId\', \'datastandardid\']),\n        qualityRule: rowValue(row, [\'qualityRule\', \'qualityrule\']), enableCodeTable: rowValue(row, [\'enableCodeTable\', \'enablecodetable\']),\n        codeTableId: rowValue(row, [\'codeTableId\', \'codetableid\']), sourceTableColumnId: rowValue(row, [\'sourceTableColumnId\', \'sourcetablecolumnid\']),\n        targetTableColumnId: rowValue(row, [\'targetTableColumnId\', \'targettablecolumnid\'])\n    })\n}\n// Some previously registered tables retained governance fields only. Use that\n// snapshot as a read-only fallback so historical directories still show items.\nif (items.size() == 0) {\n    var catalogRows = db.select("select field_governance_config fieldGovernanceConfig from da_catalog_t where ifnull(is_del,0)=0 and tid=" + sqlValue(catalogId) + " limit 1")\n    if (catalogRows != null && catalogRows.size() > 0) {\n        try {\n            var configText = rowValue(catalogRows[0], [\'fieldGovernanceConfig\', \'fieldgovernanceconfig\'])\n            var config = blank(configText) ? null : jsons.parseObj(configText)\n            var fields = config == null ? null : config.get(\'fields\')\n            if (fields != null) {\n                var sortNo = 0\n                for (field in fields) {\n                    sortNo = sortNo + 1\n                    items.add({\n                        catalogId: catalogId,\n                        colName: rowValue(field, [\'columnComment\', \'colName\', \'catalogItemName\']),\n                        colEn: rowValue(field, [\'columnName\', \'colEn\', \'catalogItemEn\']),\n                        colType: rowValue(field, [\'columnType\', \'colType\', \'dataType\']),\n                        colLength: rowValue(field, [\'length\', \'columnLength\']),\n                        colComment: rowValue(field, [\'columnComment\', \'colName\']),\n                        isPk: rowValue(field, [\'primaryKey\', \'isPk\']) ? \'1\' : \'0\',\n                        isNullable: rowValue(field, [\'nullable\', \'isNullable\']) == false ? \'0\' : \'1\',\n                        sourceTableColumnId: rowValue(field, [\'tid\', \'sourceTableColumnId\']),\n                        sortNo: sortNo,\n                        enableCodeTable: 0\n                    })\n                }\n            }\n        } catch (e) {\n            log.warn(\'read catalog governance snapshot failed, catalogId: {}, error: {}\', catalogId, e.message)\n        }\n    }\n}\nreturn items\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/03.数据目录/07.数据目录数据项列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_save_01',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "datapd_table_catalog_save_01",\r\n  "script" : null,\r\n  "groupId" : "datapd_catalog_group_01",\r\n  "name" : "08.保存数据目录",\r\n  "createTime" : 1783613131792,\r\n  "updateTime" : 1791030855523,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/saveOrUpdate",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : null,\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "保存目录主表、动态属性、数据项与来源表关联；数据库事务先提交，再同步检索投影。dryRun=true仅验证；使用请求参数 assetType、propList、tid、dryRun、catalogItems；涉及 da_prop_t、da_catalog_t、da_catalog_item_t、db_table_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport java.util.Map\nimport java.util.List\nimport log\nimport tenantRuntime\n\n// 数据盘点统一保存接口。\n// 目标是承接原 /dst/catalog/saveOrUpdate 的核心保存能力，业务逻辑直接落在 Magic API，便于后续调整。\n// 原平台登记仍直接生效；数据中心传 reviewRequired=true 时保存为待提交审核。\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar nowTime = () => new Date()\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\n\nvar valueText = (value) => {\n    if (value == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    if (value instanceof Map || value instanceof List) {\n        // 返回当前业务分支的标准结果。\n        return jsons.toJSONStr(value)\n    }\n    // 返回当前业务分支的标准结果。\n    return textOf(value)\n}\n\nvar propValue = (props, key) => {\n    if (props == null || key == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    // 返回当前业务分支的标准结果。\n    return props[key]\n}\n\nvar firstValue = (props, keys) => {\n    for (key in keys) {\n        var value = propValue(props, key)\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar getPropType = (key) => {\n    if (key == null) {\n        // 返回当前业务分支的标准结果。\n        return \'0\'\n    }\n    if (key.endsWith(\'_date\')) {\n        // 返回当前业务分支的标准结果。\n        return \'4\'\n    }\n    if (key.endsWith(\'_num\')) {\n        // 返回当前业务分支的标准结果。\n        return \'1\'\n    }\n    if (key.endsWith(\'_file\')) {\n        // 返回当前业务分支的标准结果。\n        return \'5\'\n    }\n    if (key.endsWith(\'_dict\')) {\n        // 返回当前业务分支的标准结果。\n        return \'3\'\n    }\n    if (key.endsWith(\'_range\')) {\n        // 返回当前业务分支的标准结果。\n        return \'6\'\n    }\n    if (key.endsWith(\'_time\')) {\n        // 返回当前业务分支的标准结果。\n        return \'7\'\n    }\n    // 返回当前业务分支的标准结果。\n    return \'0\'\n}\n\nvar getRealPropName = (key) => {\n    if (key == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var suffixes = [\'_date\', \'_num\', \'_file\', \'_dict\', \'_range\', \'_time\']\n    for (suffix in suffixes) {\n        if (key.endsWith(suffix)) {\n            // 返回当前业务分支的标准结果。\n            return key.substring(0, key.length() - suffix.length())\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return key\n}\n\nvar upsertAssetProps = (assetId, tenantId, assetType, props) => {\n    var now = nowTime()\n    // 从 MySQL 业务表读取当前有效数据。\n    var oldRows = db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'parent_id\', assetId).eq(\'is_del\', 0).select()\n    var oldMap = {}\n    for (old in oldRows) {\n        oldMap[rowValue(old, [\'propName\', \'prop_name\'])] = old\n    }\n    if (props == null) {\n        return\n    }\n    for (rawKey in props.keySet()) {\n        var propName = getRealPropName(rawKey)\n        if (blank(propName)) {\n            continue\n        }\n        var propType = getPropType(rawKey)\n        var propText = valueText(props[rawKey])\n        var old = oldMap[propName]\n        if (old == null) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_prop_t\').primary(\'tid\').insert({\n                tid: newId(),\n                tenant_id: tenantId,\n                parent_id: assetId,\n                prop_name: propName,\n                prop_value: propText,\n                prop_type: propType,\n                data_type: assetType,\n                is_del: 0,\n                created_time: now,\n                updated_time: now\n            })\n        } else {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_prop_t\').primary(\'tid\').update({\n                tid: rowValue(old, [\'tid\']),\n                prop_value: propText,\n                prop_type: propType,\n                data_type: assetType,\n                updated_time: now,\n                is_del: 0\n            }, true)\n        }\n    }\n}\n\nvar buildAssetResultData = (assetId) => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var asset = db.table(\'da_catalog_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne()\n    var result = {}\n    if (asset != null) {\n        result.id = rowValue(asset, [\'tid\'])\n        result.tid = rowValue(asset, [\'tid\'])\n        result.tenantId = rowValue(asset, [\'tenantId\', \'tenant_id\'])\n        result.assetType = \'catalog\'\n        result.assetStatus = rowValue(asset, [\'assetStatus\', \'asset_status\']) == null ? 2 : rowValue(asset, [\'assetStatus\', \'asset_status\'])\n        result.flowStatus = rowValue(asset, [\'flowStatus\', \'flow_status\']) == null ? 2 : rowValue(asset, [\'flowStatus\', \'flow_status\'])\n        result.regTime = rowValue(asset, [\'regTime\', \'reg_time\'])\n        result.createdTime = rowValue(asset, [\'createdTime\', \'created_time\'])\n        result.updatedTime = rowValue(asset, [\'updatedTime\', \'updated_time\'])\n        result.regTime_date = result.regTime\n        result.createdTime_date = result.createdTime\n        result.updatedTime_date = result.updatedTime\n        result.dataCatalogNum = rowValue(asset, [\'dataCatalogNum\', \'data_catalog_num\'])\n        result.tableNum = rowValue(asset, [\'tableNum\', \'table_num\'])\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var props = db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'parent_id\', assetId).eq(\'is_del\', 0).select()\n    for (prop in props) {\n        var name = rowValue(prop, [\'propName\', \'prop_name\'])\n        if (!blank(name)) {\n            result[name] = rowValue(prop, [\'propValue\', \'prop_value\'])\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\n\nvar saveToEs = (assetId, data) => {\n    if (blank(assetId) || data == null) {\n        return\n    }\n    try {\n        // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n        esCommonService.saveOrUpdate(\'dataassets\', assetId, jsons.toJSONStr(data), false)\n    } catch (e) {\n        log.warn(\'sync dataassets es failed, tid: {}, error: {}\', assetId, e.message)\n    }\n}\n\nvar itemValue = (item, keys) => {\n    if (item == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = item[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\nvar saveCatalogItems = (catalogId, tenantId, items) => {\n    if (blank(catalogId) || items == null) {\n        return\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var oldRows = db.table(\'da_catalog_item_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'catalog_id\', catalogId).eq(\'is_del\', 0).select()\n    var oldMap = {}\n    for (old in oldRows) {\n        oldMap[rowValue(old, [\'tid\'])] = old\n    }\n    var now = nowTime()\n    var sort = 1\n    for (item in items) {\n        var itemId = itemValue(item, [\'tid\', \'id\'])\n        var data = {\n            catalog_id: catalogId,\n            tenant_id: tenantId,\n            col_name: itemValue(item, [\'colName\', \'col_name\']),\n            col_en: itemValue(item, [\'colEn\', \'col_en\', \'columnName\']),\n            col_type: itemValue(item, [\'colType\', \'col_type\', \'dataType\']),\n            col_comment: itemValue(item, [\'colComment\', \'col_comment\', \'columnComment\']),\n            col_length: itemValue(item, [\'colLength\', \'col_length\', \'columnSize\']),\n            is_pk: itemValue(item, [\'isPk\', \'is_pk\', \'primaryKey\']),\n            is_masking: itemValue(item, [\'isMasking\', \'is_masking\']),\n            is_fk: itemValue(item, [\'isFk\', \'is_fk\']),\n            is_nullable: itemValue(item, [\'isNullable\', \'is_nullable\', \'nullable\']),\n            date_format: itemValue(item, [\'dateFormat\', \'date_format\']),\n            mark_lvl: itemValue(item, [\'markLvl\', \'mark_lvl\']),\n            col_unit: itemValue(item, [\'colUnit\', \'col_unit\']),\n            col_precision: itemValue(item, [\'colPrecision\', \'col_precision\']),\n            masking_id: itemValue(item, [\'maskingId\', \'masking_id\']),\n            sort_no: itemValue(item, [\'sortNo\', \'sort_no\']) == null ? sort : itemValue(item, [\'sortNo\', \'sort_no\']),\n            share_type: itemValue(item, [\'shareType\', \'share_type\']),\n            share_condition: itemValue(item, [\'shareCondition\', \'share_condition\']),\n            is_dict: itemValue(item, [\'isDict\', \'is_dict\']),\n            dict_name: itemValue(item, [\'dictName\', \'dict_name\']),\n            col_max_length: itemValue(item, [\'colMaxLength\', \'col_max_length\']),\n            default_value: itemValue(item, [\'defaultValue\', \'default_value\']),\n            data_standard_id: itemValue(item, [\'dataStandardId\', \'data_standard_id\']),\n            quality_rule: itemValue(item, [\'qualityRule\', \'quality_rule\']),\n            enable_code_table: itemValue(item, [\'enableCodeTable\', \'enable_code_table\']),\n            code_table_id: itemValue(item, [\'codeTableId\', \'code_table_id\']),\n            source_table_column_id: itemValue(item, [\'sourceTableColumnId\', \'source_table_column_id\']),\n            target_table_column_id: itemValue(item, [\'targetTableColumnId\', \'target_table_column_id\']),\n            updated_time: now,\n            is_del: 0\n        }\n        if (!blank(itemId) && oldMap[itemId] != null) {\n            data.tid = itemId\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_catalog_item_t\').primary(\'tid\').update(data, true)\n            oldMap[itemId] = null\n        } else {\n            // 客户端行标识可能来自源字段，目录数据项必须生成独立主键。\n            data.tid = newId()\n            data.created_time = now\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_catalog_item_t\').primary(\'tid\').insert(data)\n        }\n        sort = sort + 1\n    }\n    for (oldKey in oldMap.keySet()) {\n        var old = oldMap[oldKey]\n        if (old != null) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_catalog_item_t\').primary(\'tid\').update({\n                tid: rowValue(old, [\'tid\']),\n                is_del: 1,\n                updated_time: now\n            }, true)\n        }\n    }\n}\n\n\n/*\n * 目录保存：同一事务写 da_catalog_t / da_prop_t / da_catalog_item_t 与 db_table_t 关联。\n * 不读写源库物理表；先校验当前登录租户归属。dryRun=true 仅校验并返回计划。\n */\nif (body == null) { exit 400, \'请求参数不能为空\' }\nvar tenantId = tenantRuntime.id()\nvar assetType = blank(body.assetType) ? \'catalog\' : textOf(body.assetType)\nif (assetType != \'catalog\') { exit 400, \'本接口只允许保存数据目录\' }\nvar props = body.propList\nif (props == null || !(props instanceof Map)) { exit 400, \'目录属性不能为空\' }\nvar tid = body.tid\nvar old = blank(tid) ? null : db.table(\'da_catalog_t\').where()\n    .eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (!blank(tid) && old == null) { exit 404, \'数据目录不存在或无访问权限\' }\nvar oldProps = blank(tid) ? {} : buildAssetResultData(tid)\nvar sourceProvided = props.containsKey(\'sourceTableId\')\nvar sourceTableId = sourceProvided ? props.sourceTableId :\n    firstValue(oldProps, [\'sourceTableId\'])\nif (!sourceProvided && blank(sourceTableId)) { sourceTableId = rowValue(old, [\'sourceTableId\', \'source_table_id\']) }\nvar sourceTable = blank(sourceTableId) ? null : db.table(\'db_table_t\').where()\n    .eq(\'tid\', sourceTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (!blank(sourceTableId) && sourceTable == null) { exit 404, \'关联的数据表不存在或无访问权限\' }\nvar name = props.containsKey(\'catalogName\') ? props.catalogName :\n    firstValue(oldProps, [\'catalogName\'])\nif (blank(name)) { name = rowValue(old, [\'catalogName\', \'catalog_name\']) }\nif (blank(name)) { exit 400, \'数据目录名称不能为空\' }\nif (body.dryRun == true) { return {dryRun: true, tid: tid, catalogName: name, sourceTableId: sourceTableId} }\nvar reviewRequired = body.reviewRequired == true\nvar saved = db.transaction(() => {\n    var now = nowTime()\n    // 元数据登记保持原有即登记完成的行为；数据中心编目显式进入待提交审核。\n    var values = { tenant_id: tenantId, asset_status: reviewRequired ? 0 : 2,\n        flow_status: reviewRequired ? 0 : 2, is_del: 0, updated_time: now }\n    if (reviewRequired) {\n        values.resource_revision_no = old == null ? 1 :\n            ((rowValue(old, [\'resourceRevisionNo\', \'resource_revision_no\']) == null ? 1 :\n                rowValue(old, [\'resourceRevisionNo\', \'resource_revision_no\']))::int) + 1\n    }\n    var fields = {\n        catalogName: \'catalog_name\', catalogNameEn: \'catalog_name_en\', assetDesc: \'asset_desc\',\n        appId: \'app_id\', appName: \'app_name\', dbId: \'db_id\', dbName: \'db_name\',\n        sourceTableId: \'source_table_id\', sourceTableName: \'source_table_name\',\n        sourceDbId: \'source_db_id\', sourceDbName: \'source_db_name\',\n        targetTableId: \'target_table_id\', targetTableName: \'target_table_name\',\n        targetDbId: \'target_db_id\', targetDbType: \'target_db_type\', orgId: \'org_id\',\n        manageUnit: \'manage_unit\', businessType: \'business_type\', dataSourceType: \'data_source_type\',\n        timestampField: \'timestamp_field\', dictionaryTableFlag: \'dictionary_table_flag\',\n        fieldGovernanceConfig: \'field_governance_config\'\n    }\n    for (key in fields.keySet()) {\n        if (props.containsKey(key)) { values[fields[key]] = valueText(props[key]) }\n    }\n    values.catalog_name = name\n    if (!props.containsKey(\'catalogNameEn\') && old != null) {\n        values.catalog_name_en = rowValue(old, [\'catalogNameEn\', \'catalog_name_en\'])\n    }\n    if (sourceTable != null) {\n        values.source_table_id = sourceTableId\n        if (blank(values.source_table_name)) { values.source_table_name = rowValue(sourceTable, [\'tableName\', \'table_name\']) }\n        if (blank(values.db_id)) { values.db_id = rowValue(sourceTable, [\'datasourceId\', \'datasource_id\']) }\n    }\n    if (old == null) {\n        tid = newId()\n        values.tid = tid\n        values.created_time = now\n        values.reg_time = now\n        db.table(\'da_catalog_t\').primary(\'tid\').insert(values)\n    } else {\n        values.tid = tid\n        db.table(\'da_catalog_t\').primary(\'tid\').update(values, true)\n    }\n    upsertAssetProps(tid, tenantId, \'catalog\', props)\n    // 基础列与兼容属性保持一致，旧列表与详情都可读取相同的数据。\n    for (key in fields.keySet()) {\n        if (values.containsKey(fields[key])) {\n            var singleProp = {}\n            singleProp[key] = values[fields[key]]\n            upsertAssetProps(tid, tenantId, \'catalog\', singleProp)\n        }\n    }\n    if (body.catalogItems != null) { saveCatalogItems(tid, tenantId, body.catalogItems) }\n    // 若重新绑定来源表，先清除原表仍指向本目录的关联。\n    db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId).eq(\'source_catalog_id\', tid)\n        .update({source_catalog_id: null, catalog_name: null, catalog_name_en: null, updated_time: now}, true)\n    if (sourceTable != null) {\n        db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', sourceTableId).eq(\'is_del\', 0)\n            .update({source_catalog_id: tid, catalog_name: name, catalog_name_en: values.catalog_name_en, updated_time: now}, true)\n    }\n    var result = buildAssetResultData(tid)\n    result.assetStatus = values.asset_status\n    result.flowStatus = values.flow_status\n    return result\n})\n// 索引是查询投影；数据库事务成功后再更新，索引故障不回滚已保存的目录。\nsaveToEs(saved.tid, saved)\nreturn saved\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/03.数据目录/08.保存数据目录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_delete_01',NULL,'api','{\n  "properties": {},\n  "id": "datapd_catalog_delete_01",\n  "script": null,\n  "groupId": "datapd_catalog_group_01",\n  "name": "09.删除数据目录",\n  "createTime": null,\n  "updateTime": 1790644837589,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2086383506325794816\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"tid\\":\\"2086383506325794816\\",\\"deleted\\":true}",\n  "description": "按当前租户软删除目录和关联；兼容未安装历史关联表的租户库，保留已采集表及字段；使用请求参数 tid、id、dryRun；涉及 da_catalog_t、da_catalog_item_t、db_table_t、da_prop_t、da_app_catalog_rela 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.删除数据目录\n// 路由：POST /dst/catalog/delete\n// 业务说明：按当前租户软删除目录和关联；兼容未安装历史关联表的租户库，保留已采集表及字段；使用请求参数 tid、id、dryRun；涉及 da_catalog_t、da_catalog_item_t、db_table_t、da_prop_t、da_app_catalog_rela 等业务表。\nimport tenantRuntime\nimport identityRuntime\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport log\n\n// Shared catalog soft-delete. Read/write: da_catalog_t, da_prop_t,\n// da_catalog_item_t and table-to-catalog references; never drop collected tables.\n// dryRun checks ownership and reports affected counts without changing data.\nvar tenantId = tenantRuntime.id()\nvar tid = body == null ? null : (body.tid == null ? body.id : body.tid)\nif (tid == null || (tid + \'\').trim() == \'\') { exit 400, \'目录标识不能为空\' }\nvar catalog = db.table(\'da_catalog_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (catalog == null) { exit 404, \'数据目录不存在或无访问权限\' }\n// Historical restores need not contain the retired app/catalog association.\n// Inspect the CURRENT TENANT database before opening the write transaction.\n// Other SQL/schema errors are not swallowed; they must roll back the delete.\nvar hasLegacyAssociation = identityRuntime.hasTable(\'da_app_catalog_rela\')\nif (body.dryRun == true) {\n    return { tid: tid, dryRun: true, catalogName: catalog.catalogName,\n        dataItems: db.table(\'da_catalog_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'catalog_id\', tid).eq(\'is_del\', 0).count(),\n        associatedTables: db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId).eq(\'source_catalog_id\', tid).eq(\'is_del\', 0).count() }\n}\ndb.transaction(() => {\n    var updatedTime = new Date()\n    var affected = db.table(\'da_catalog_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({is_del: 1, updated_time: updatedTime})\n    if (affected != 1) { exit 409, \'目录状态已变化，请刷新后重试\' }\n    db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', tid).eq(\'is_del\', 0).update({is_del: 1, updated_time: updatedTime})\n    db.table(\'da_catalog_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'catalog_id\', tid).eq(\'is_del\', 0).update({is_del: 1, updated_time: updatedTime})\n    if (hasLegacyAssociation) {\n        db.table(\'da_app_catalog_rela\').where().eq(\'tenant_id\', tenantId).eq(\'data_catalog_id\', tid).eq(\'is_del\', 0).update({is_del: 1, updated_time: updatedTime})\n    }\n    db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId).eq(\'source_catalog_id\', tid)\n        .update({source_catalog_id: null, catalog_name: null, catalog_name_en: null, updated_time: updatedTime}, true)\n})\nvar indexRefreshPending = false\ntry { esCommonService.deleteById(\'dataassets\', tid) }\ncatch (error) {\n    indexRefreshPending = true\n    log.warn(\'Catalog deleted; ES projection cleanup pending: id={}, message={}\', tid, error.message)\n}\nreturn { tid: tid, deleted: true, indexRefreshPending: indexRefreshPending }\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/03.数据目录/09.删除数据目录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('datapd_catalog_group_01',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "datapd_catalog_group_01",\r\n  "name" : "03.数据目录",\r\n  "type" : "api",\r\n  "parentId" : "ae3a63e77a194c2db32d854923f4983a",\r\n  "path" : "/catalog",\r\n  "createTime" : 1784420517826,\r\n  "updateTime" : 1784437772101,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/02.数据盘点/03.数据目录/group.json');
