INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "7d35c0cb9698421d9c9c408d21eab301",\n  "script": null,\n  "groupId": "9c4f2b37ec2e4c7f9c6b31cdb4de1201",\n  "name": "01.资源登记概览",\n  "createTime": 1788813873852,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/summary",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "祺智资源中心当前租户的应用、数据源、数据表和字段登记摘要。只读。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.资源登记概览\n// 路由：GET /dst/qizhi-resource/summary\n// 业务说明：祺智资源中心当前租户的应用、数据源、数据表和字段登记摘要。只读。\n// 祺智资源中心：读取当前租户的登记摘要。\n// 读取 sym_application_t、db_datasource_t、db_table_t、db_table_column_t；不写入任何表。\n// 安全校验：租户仅由 tenantRuntime.id() 提供。\nimport tenantRuntime;\nvar tenantId = tenantRuntime.id();\nvar activeCount = (tableName) => {\n  try {\n    var rows = db.select(`select count(1) as total from ${tableName} where is_del = 0`);\n    return {available: true, count: rows == null || rows.size() == 0 ? 0 : rows[0].total};\n  } catch (error) {\n    return {available: false, count: 0};\n  }\n};\nreturn {\n  tenantId: tenantId,\n  tenantCode: tenantId + \'\',\n  tenantName: \'当前租户\',\n  metrics: {\n    applicationSystems: activeCount(\'sym_application_t\'),\n    registeredDataSources: activeCount(\'db_datasource_t\'),\n    registeredDataTables: activeCount(\'db_table_t\'),\n    registeredFields: activeCount(\'db_table_column_t\')\n  }\n};\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/06.祺智资源中心/01.资源登记概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "7d35c0cb9698421d9c9c408d21eab302",\n  "script": null,\n  "groupId": "9c4f2b37ec2e4c7f9c6b31cdb4de1201",\n  "name": "02.应用系统登记",\n  "createTime": 1788813874034,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applications",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "祺智资源中心当前租户已登记应用系统。只读；涉及 sym_application_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.应用系统登记\n// 路由：GET /dst/qizhi-resource/applications\n// 业务说明：祺智资源中心当前租户已登记应用系统。只读；涉及 sym_application_t 等业务表。\n// 祺智资源中心：读取当前租户已登记应用系统。\n// 读取 sym_application_t；不写入任何表。\n// 安全校验：租户仅由 tenantRuntime.id() 提供，物理库由租户路由选择。\nimport tenantRuntime;\nvar tenantId = tenantRuntime.id();\ntry {\n  var items = db.select(\'select tid as id, app_name as name, app_desc as description, is_use as enabled, asset_status as assetStatus, updated_time as updatedTime from sym_application_t where is_del = 0 order by updated_time desc limit 100\');\n  return {available: true, items: items == null ? [] : items};\n} catch (error) {\n  return {available: false, items: []};\n}\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/06.祺智资源中心/02.应用系统登记.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "7d35c0cb9698421d9c9c408d21eab303",\n  "script": null,\n  "groupId": "9c4f2b37ec2e4c7f9c6b31cdb4de1201",\n  "name": "03.数据源登记",\n  "createTime": 1788813874090,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/data-sources",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "祺智资源中心当前租户已登记数据源，不返回连接凭据。只读；涉及 db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据源登记\n// 路由：GET /dst/qizhi-resource/data-sources\n// 业务说明：祺智资源中心当前租户已登记数据源，不返回连接凭据。只读；涉及 db_datasource_t 等业务表。\n// 祺智资源中心：读取当前租户已登记数据源。\n// 读取 db_datasource_t；不返回 pool_cfg 或连接凭据，不写入任何表。\n// 安全校验：租户仅由 tenantRuntime.id() 提供，物理库由租户路由选择。\nimport tenantRuntime;\nvar tenantId = tenantRuntime.id();\ntry {\n  var items = db.select(\'select tid as id, db_name as name, db_type as databaseType, database_type as databaseTypeCode, table_num as tableCount, is_enable as enabled, asset_status as assetStatus, updated_time as updatedTime from db_datasource_t where is_del = 0 order by updated_time desc limit 100\');\n  return {available: true, items: items == null ? [] : items};\n} catch (error) {\n  return {available: false, items: []};\n}\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/06.祺智资源中心/03.数据源登记.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "7d35c0cb9698421d9c9c408d21eab304",\n  "script": null,\n  "groupId": "9c4f2b37ec2e4c7f9c6b31cdb4de1201",\n  "name": "04.数据表登记",\n  "createTime": 1788813874159,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/data-tables",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "祺智资源中心当前租户已登记数据表。只读；涉及 db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.数据表登记\n// 路由：GET /dst/qizhi-resource/data-tables\n// 业务说明：祺智资源中心当前租户已登记数据表。只读；涉及 db_table_t 等业务表。\n// 祺智资源中心：读取当前租户已登记数据表。\n// 读取 db_table_t；不写入任何表。\n// 安全校验：租户仅由 tenantRuntime.id() 提供，物理库由租户路由选择。\nimport tenantRuntime;\nvar tenantId = tenantRuntime.id();\ntry {\n  var items = db.select(\'select tid as id, datasource_id as dataSourceId, table_name as name, table_name_cn as displayName, table_type as tableType, business_type as businessType, record_count as recordCount, field_count as fieldCount, updated_time as updatedTime from db_table_t where is_del = 0 order by updated_time desc limit 100\');\n  return {available: true, items: items == null ? [] : items};\n} catch (error) {\n  return {available: false, items: []};\n}\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/06.祺智资源中心/04.数据表登记.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "7d35c0cb9698421d9c9c408d21eab305",\n  "script": null,\n  "groupId": "9c4f2b37ec2e4c7f9c6b31cdb4de1201",\n  "name": "05.登记字段",\n  "createTime": 1788813874211,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/fields",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "祺智资源中心当前租户已登记表字段。只读；涉及 db_table_column_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.登记字段\n// 路由：GET /dst/qizhi-resource/fields\n// 业务说明：祺智资源中心当前租户已登记表字段。只读；涉及 db_table_column_t、db_table_t 等业务表。\n// 祺智资源中心：读取当前租户已登记表字段。\n// 读取 db_table_column_t 与 db_table_t；不写入任何表。\n// 安全校验：租户仅由 tenantRuntime.id() 提供，物理库由租户路由选择。\nimport tenantRuntime;\nvar tenantId = tenantRuntime.id();\ntry {\n  var items = db.select(\'select c.tid as id, c.table_id as tableId, t.table_name as tableName, t.table_name_cn as tableDisplayName, c.column_name as name, c.column_comment as description, c.data_type as dataType, c.column_type as columnType, c.length as length, c.nullable as nullable, c.primary_key as primaryKey, c.ordinal_position as position from db_table_column_t c left join db_table_t t on t.tid = c.table_id and t.is_del = 0 where c.is_del = 0 order by t.table_name, c.ordinal_position limit 500\');\n  return {available: true, items: items == null ? [] : items};\n} catch (error) {\n  return {available: false, items: []};\n}\n',NULL,NULL,0,NULL,'/magic-api/api/02.数据盘点/06.祺智资源中心/05.登记字段.ms');
