INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('api_pull_service_list_01',NULL,'api','{\n  "properties": {},\n  "id": "api_pull_service_list_01",\n  "script": null,\n  "groupId": "tenant_magic_api_pull_20261003",\n  "name": "01.API 拉取 - 接口服务列表",\n  "path": "/api-pull/services",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "仅 API 数据拉取来源读取当前租户的数据源接口服务；不返回认证明文。"\n}\n================================\n// 接口：API 接口服务列表\n// 业务说明：验证当前租户 API 拉取数据源后，读取服务配置；只返回凭据引用，不返回明文凭据。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nvar sourceId = datasourceId == null ? \'\' : (\'\' + datasourceId).trim()\nif (sourceId == \'\') { exit 400, \'数据源标识不能为空\' }\napiPullConfig.validateDatasource(sourceId)\n\nreturn db.select("""\n    SELECT tid,\n           datasource_id,\n           service_name,\n           service_code,\n           base_url,\n           path_prefix,\n           protocol,\n           service_type,\n           media_type,\n           network_mode,\n           outbound_allowlist,\n           connect_timeout_ms,\n           read_timeout_ms,\n           max_response_bytes,\n           tls_mode,\n           client_cert_ref,\n           common_headers_json,\n           auth_type,\n           credential_ref,\n           auth_config_json,\n           status,\n           created_time,\n           updated_time\n      FROM data_pull_service_t\n     WHERE tenant_id = #{tenantId}\n       AND datasource_id = #{sourceId}\n       AND is_del = 0\n     ORDER BY service_name, tid\n""")\n',NULL,NULL,0,NULL,'/magic-api/api/02.租户端/02.数据库/05.API拉取/01.API 拉取 - 接口服务列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('api_pull_service_save_01',NULL,'api','{\n  "properties": {},\n  "id": "api_pull_service_save_01",\n  "script": null,\n  "groupId": "tenant_magic_api_pull_20261003",\n  "name": "02.API 拉取 - 保存接口服务",\n  "path": "/api-pull/services/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "校验当前租户的数据源、服务名称/编码、Base URL 和认证引用，再保存接口服务；只存凭据引用，不存认证明文。"\n}\n================================\n// 接口：保存 API 拉取服务\n// 业务说明：校验当前租户的数据源、服务名称/编码、Base URL 和认证引用，再保存接口服务；只存凭据引用，不存认证明文。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nif (body?.datasourceId == null || (\'\' + body.datasourceId).trim() == \'\') { exit 400, \'请选择数据源\' }\nif (body?.serviceName == null || (\'\' + body.serviceName).trim() == \'\') { exit 400, \'请填写接口服务名称\' }\nvar code = body?.serviceCode == null ? \'\' : (\'\' + body.serviceCode).trim().toLowerCase()\nif (!code.matches(\'^[a-z][a-z0-9_-]{1,95}$\')) { exit 400, \'接口服务编码只能使用小写字母、数字、-、_\' }\nvar baseUrl = body?.baseUrl == null ? \'\' : (\'\' + body.baseUrl).trim()\nif (baseUrl == \'\') { exit 400, \'请填写 Base URL\' }\nvar authType = body?.authType == null ? \'NONE\' : (\'\' + body.authType).trim().toUpperCase()\nif (authType != \'NONE\' && (body?.credentialRef == null || (\'\' + body.credentialRef).trim() == \'\')) {\n    exit 400, \'认证方式启用后必须填写凭据引用\'\n}\n\n// URL 主机、协议、敏感请求头和目标租户归属由 Java 安全边界再次验证。\nreturn apiPullConfig.saveService(body)\n',NULL,NULL,0,NULL,'/magic-api/api/02.租户端/02.数据库/05.API拉取/02.API 拉取 - 保存接口服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('api_pull_rule_list_01',NULL,'api','{\n  "properties": {},\n  "id": "api_pull_rule_list_01",\n  "script": null,\n  "groupId": "tenant_magic_api_pull_20261003",\n  "name": "03.API 拉取 - 表规则列表",\n  "path": "/api-pull/rules",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "读取当前租户 API 拉取来源的逻辑表拉取规则；规则保存本身不创建 NiFi 任务。"\n}\n================================\n// 接口：API 表级拉取规则列表\n// 业务说明：按当前租户与数据源读取规则；可选择指定逻辑表，不会创建或启动 NiFi 任务。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nvar sourceId = datasourceId == null ? \'\' : (\'\' + datasourceId).trim()\nif (sourceId == \'\') { exit 400, \'数据源标识不能为空\' }\nvar tableId = sourceTableId == null || (\'\' + sourceTableId).trim() == \'\' ? null : (\'\' + sourceTableId).trim()\napiPullConfig.validateDatasource(sourceId)\n\nreturn db.select("""\n    SELECT tid,\n           datasource_id,\n           source_table_id,\n           service_id,\n           rule_name,\n           endpoint_method,\n           endpoint_path,\n           request_template_json,\n           response_config_json,\n           pagination_config_json,\n           incremental_config_json,\n           orchestration_config_json,\n           mapping_config_json,\n           quality_config_json,\n           delete_config_json,\n           runtime_config_json,\n           trigger_mode,\n           cron_expression,\n           nifi_task_id,\n           enabled,\n           created_time,\n           updated_time\n      FROM data_pull_rule_t\n     WHERE tenant_id = #{tenantId}\n       AND datasource_id = #{sourceId}\n       AND (#{tableId} IS NULL OR source_table_id = #{tableId})\n       AND is_del = 0\n     ORDER BY updated_time DESC, tid\n""")\n',NULL,NULL,0,NULL,'/magic-api/api/02.租户端/02.数据库/05.API拉取/03.API 拉取 - 表规则列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('api_pull_rule_save_01',NULL,'api','{\n  "properties": {},\n  "id": "api_pull_rule_save_01",\n  "script": null,\n  "groupId": "tenant_magic_api_pull_20261003",\n  "name": "04.API 拉取 - 保存表规则",\n  "path": "/api-pull/rules/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "校验数据源、逻辑表、接口服务及请求路径；保存规则配置，不创建或启动 NiFi 任务。"\n}\n================================\n// 接口：保存 API 表级拉取规则\n// 业务说明：校验数据源、逻辑表、接口服务及请求路径；保存规则配置，不创建或启动 NiFi 任务。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nif (body?.datasourceId == null || (\'\' + body.datasourceId).trim() == \'\') { exit 400, \'请选择数据源\' }\nif (body?.sourceTableId == null || (\'\' + body.sourceTableId).trim() == \'\') { exit 400, \'请选择逻辑数据表\' }\nif (body?.serviceId == null || (\'\' + body.serviceId).trim() == \'\') { exit 400, \'请选择接口服务\' }\nif (body?.ruleName == null || (\'\' + body.ruleName).trim() == \'\') { exit 400, \'请填写拉取规则名称\' }\nvar endpointPath = body?.endpointPath == null ? \'\' : (\'\' + body.endpointPath).trim()\nif (!endpointPath.startsWith(\'/\')) { exit 400, \'接口路径必须以 / 开头\' }\nvar triggerMode = body?.triggerMode == null ? \'MANUAL\' : (\'\' + body.triggerMode).trim().toUpperCase()\nif (triggerMode == \'CRON\' && (body?.cronExpression == null || (\'\' + body.cronExpression).trim() == \'\')) {\n    exit 400, \'定时任务必须填写 Cron 表达式\'\n}\n\n// Java 校验表和服务确实属于当前租户，保留 NiFi 任务 ID 的内部关联约束。\nreturn apiPullConfig.saveRule(body)\n',NULL,NULL,0,NULL,'/magic-api/api/02.租户端/02.数据库/05.API拉取/04.API 拉取 - 保存表规则.ms');
