INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_nifi_node_page_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_nifi_node_page_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "01.数据同步节点列表",\n  "path": "/nifi-node/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"主节点\\"\\n}",\n  "responseBody": "{\\n  \\"list\\": [],\\n  \\"total\\": 0\\n}",\n  "description": "数据同步节点列表（POST /ods/nifi-node/page）。读取当前登录租户的 nifi_node_t，仅返回本租户未删除节点；使用请求参数 keyword。",\n  "script": null\n}\n================================\n// 接口：01.数据同步节点列表\n// 路由：POST /ods/nifi-node/page\n// 业务说明：数据同步节点列表（POST /ods/nifi-node/page）。读取当前登录租户的 nifi_node_t，仅返回本租户未删除节点；使用请求参数 keyword。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar keyword = text(body?.keyword).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再查看节点配置\'\n}\n// 以下从 sym_dict_t 业务表读取或维护当前操作涉及的记录。\nvar root = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'dict_code\', \'SSWL\').eq(\'is_del\', 0).selectOne()\nvar networkNames = {}\nvar networkIcons = {}\nif (root != null) {\n    var dictionaries = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', root.tid).eq(\'is_del\', 0).select()\n    for (dictionary in (dictionaries == null ? [] : dictionaries)) {\n        var dictionaryCode = text(dictionary.dictCode == null ? dictionary.dict_code : dictionary.dictCode).trim()\n        if (dictionaryCode != \'\') {\n            networkNames[dictionaryCode] = text(dictionary.dictName == null ? dictionary.dict_name : dictionary.dictName).trim()\n            networkIcons[dictionaryCode] = text(dictionary.icon).trim()\n        }\n    }\n}\n\nvar rows = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    .orderBy(\'is_default\', \'desc\').orderBy(\'updated_time\', \'desc\').select()\nvar list = []\nfor (row in (rows == null ? [] : rows)) {\n    var nodeName = row.nodeName == null ? row.node_name : row.nodeName\n    var nodeCode = row.nodeCode == null ? row.node_code : row.nodeCode\n    var legacyNetwork = text(row.networkType == null ? row.network_type : row.networkType).trim()\n    var networkCode = text(row.networkCode == null ? row.network_code : row.networkCode).trim()\n    if (networkCode == \'\') {\n        networkCode = legacyNetwork == \'公安网\' ? \'GAW\' : (legacyNetwork == \'互联网\' ? \'HLW\' : (legacyNetwork == \'专网\' || legacyNetwork == \'ZWW\' ? \'SPZW\' : legacyNetwork))\n    }\n    var networkName = text(networkNames[networkCode]).trim()\n    if (networkName == \'\') {\n        networkName = legacyNetwork == \'\' ? networkCode : legacyNetwork\n    }\n    if (keyword != \'\' && text(nodeName).indexOf(keyword) < 0 && text(nodeCode).indexOf(keyword) < 0 && networkCode.indexOf(keyword) < 0 && networkName.indexOf(keyword) < 0) {\n        continue\n    }\n    list.add({\n        tid: row.tid,\n        nodeName: nodeName,\n        nodeCode: nodeCode,\n        networkCode: networkCode,\n        networkName: networkName,\n        networkIcon: text(networkIcons[networkCode]).trim(),\n        baseUrl: row.baseUrl == null ? row.base_url : row.baseUrl,\n        rootProcessGroupId: row.rootProcessGroupId == null ? row.root_process_group_id : row.rootProcessGroupId,\n        authUsername: row.authUsername == null ? row.auth_username : row.authUsername,\n        insecureTls: row.insecureTls == null ? row.insecure_tls : row.insecureTls,\n        jdbcDriverDirectory: row.jdbcDriverLocations == null ? row.jdbc_driver_locations : row.jdbcDriverLocations,\n        remark: row.remark,\n        enabled: row.enabled == null ? 1 : row.enabled,\n        isDefault: row.isDefault == null ? row.is_default : row.isDefault,\n        updatedTime: row.updatedTime == null ? row.updated_time : row.updatedTime\n    })\n}\nreturn { list: list, total: list.size() }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/01.数据同步节点列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_nifi_node_save_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_nifi_node_save_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "02.保存数据同步节点",\n  "path": "/nifi-node/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"nodeName\\": \\"数据同步主节点\\",\\n  \\"nodeCode\\": \\"primary-nifi\\",\\n  \\"baseUrl\\": \\"https://nifi.example.com:8443\\"\\n}",\n  "responseBody": "{\\n  \\"tid\\": \\"2087600000000000001\\"\\n}",\n  "description": "保存数据同步节点（POST /ods/nifi-node/saveOrUpdate）。仅维护当前租户节点；每个所属网络保留一个默认节点，默认节点可以停用；使用请求参数 tid、nodeName、nodeCode、baseUrl、networkCode、authUsername、authPassword、insecureTls；涉及 sym_dict_t、nifi_node_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：02.保存数据同步节点\n// 路由：POST /ods/nifi-node/saveOrUpdate\n// 业务说明：保存数据同步节点（POST /ods/nifi-node/saveOrUpdate）。仅维护当前租户节点；每个所属网络保留一个默认节点，默认节点可以停用；使用请求参数 tid、nodeName、nodeCode、baseUrl、networkCode、authUsername、authPassword、insecureTls；涉及 sym_dict_t、nifi_node_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || text(value).trim() == \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar tid = text(body?.tid).trim()\nvar nodeName = text(body?.nodeName).trim()\nvar nodeCode = text(body?.nodeCode).trim()\nvar baseUrl = text(body?.baseUrl).trim().replaceAll(\'/+$\', \'\')\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(nodeName) || blank(nodeCode) || blank(baseUrl)) {\n    exit 400, \'节点名称、节点编码和 NiFi 地址不能为空\'\n}\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再维护节点\'\n}\nvar networkCode = text(body?.networkCode).trim()\nvar authUsername = text(body?.authUsername).trim()\nvar authPassword = text(body?.authPassword).trim()\nvar insecureTls = body?.insecureTls == false || text(body?.insecureTls) == \'0\' ? 0 : 1\nvar jdbcDriverDirectory = text(body?.jdbcDriverDirectory).trim()\nif (jdbcDriverDirectory != \'\' && (!jdbcDriverDirectory.startsWith(\'/\') || jdbcDriverDirectory.contains(\'\\n\') || jdbcDriverDirectory.contains(\'\\r\') || jdbcDriverDirectory.contains(\'=\'))) {\n    exit 400, \'JDBC 驱动目录必须填写 NiFi 节点上的 Linux 绝对目录，例如 /opt/nifi/nifi-current/lib/jdbc\'\n}\nif (networkCode == \'\') {\n    exit 400, \'请选择所属网络\'\n}\n// 以下从 sym_dict_t 业务表读取或维护当前操作涉及的记录。\nvar networkRoot = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'dict_code\', \'SSWL\').eq(\'is_del\', 0).selectOne()\nif (networkRoot == null || db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', networkRoot.tid).eq(\'dict_code\', networkCode).eq(\'is_del\', 0).selectOne() == null) {\n    exit 400, \'所属网络不存在或已停用\'\n}\nif (!baseUrl.matches(\'^https?://.+\')) {\n    exit 400, \'NiFi 地址必须以 http:// 或 https:// 开头\'\n}\nvar now = new Date()\nvar enabled = body?.enabled == false || text(body?.enabled) == \'0\' ? 0 : 1\nvar isDefault = body?.isDefault == true || text(body?.isDefault) == \'1\' ? 1 : 0\nvar duplicate = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'node_code\', nodeCode).eq(\'is_del\', 0).selectOne()\nif (duplicate != null && text(duplicate.tid) != tid) {\n    exit 400, \'节点编码已存在，请使用其他编码\'\n}\nvar networkDefault = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'network_code\', networkCode).eq(\'is_del\', 0).eq(\'is_default\', 1).selectOne()\nif (blank(tid) && networkDefault == null) {\n    isDefault = 1\n}\nif (isDefault == 1) {\n    db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'network_code\', networkCode).eq(\'is_del\', 0).update({ is_default: 0, updated_time: now })\n}\nif (blank(tid)) {\n    if (isDefault == 1 && (blank(authUsername) || blank(authPassword))) {\n        exit 400, \'默认节点必须配置 NiFi 用户名和密码\'\n    }\n    tid = IdUtil.getSnowflakeNextIdStr()\n    db.table(\'nifi_node_t\').primary(\'tid\').insert({\n        tid: tid, tenant_id: tenantId, node_name: nodeName, node_code: nodeCode, base_url: baseUrl,\n        network_code: networkCode, root_process_group_id: text(body?.rootProcessGroupId).trim(), auth_username: authUsername, auth_password: authPassword, insecure_tls: insecureTls, jdbc_driver_locations: jdbcDriverDirectory, remark: text(body?.remark).trim(),\n        enabled: enabled, is_default: isDefault, created_time: now, updated_time: now, is_del: 0\n    })\n} else {\n    var existing = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n    if (existing == null) {\n        exit 404, \'数据同步节点不存在或已删除\'\n    }\n    var persistedDefault = existing.isDefault == null ? existing.is_default : existing.isDefault\n    var persistedNetworkCode = text(existing.networkCode == null ? existing.network_code : existing.networkCode).trim()\n    var existingPassword = text(existing.authPassword == null ? existing.auth_password : existing.authPassword)\n    if ((persistedDefault == 1 || persistedDefault == true) && persistedNetworkCode != \'\' && persistedNetworkCode != networkCode) {\n        exit 400, \'默认节点不能直接变更所属网络，请先在原网络设置新的默认节点\'\n    }\n    if ((persistedDefault == 1 || persistedDefault == true) && isDefault == 0) {\n        exit 400, \'每个所属网络必须保留一个默认节点，请先将其他节点设为默认\'\n    }\n    if (isDefault == 1 && (blank(authUsername) || (blank(authPassword) && blank(existingPassword)))) {\n        exit 400, \'默认节点必须配置 NiFi 用户名和密码\'\n    }\n    db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({\n        node_name: nodeName, node_code: nodeCode, base_url: baseUrl,\n        network_code: networkCode, root_process_group_id: text(body?.rootProcessGroupId).trim(), auth_username: authUsername, auth_password: blank(authPassword) ? existingPassword : authPassword, insecure_tls: insecureTls, jdbc_driver_locations: jdbcDriverDirectory, remark: text(body?.remark).trim(),\n        enabled: enabled, is_default: isDefault, updated_time: now\n    })\n}\nreturn { tid: tid }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/02.保存数据同步节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_nifi_node_delete_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_nifi_node_delete_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "03.删除数据同步节点",\n  "path": "/nifi-node/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2087600000000000002\\"\\n}",\n  "responseBody": "{\\n  \\"success\\": true\\n}",\n  "description": "删除数据同步节点（POST /ods/nifi-node/delete）。仅逻辑删除当前租户的非默认节点；使用请求参数 tid；涉及 nifi_node_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：03.删除数据同步节点\n// 路由：POST /ods/nifi-node/delete\n// 业务说明：删除数据同步节点（POST /ods/nifi-node/delete）。仅逻辑删除当前租户的非默认节点；使用请求参数 tid；涉及 nifi_node_t 等业务表。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar tid = text(body?.tid).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tid == \'\') {\n    exit 400, \'节点标识不能为空\'\n}\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再维护节点\'\n}\n// 以下从 nifi_node_t 业务表读取或维护当前操作涉及的记录。\nvar node = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (node == null) {\n    exit 404, \'数据同步节点不存在或已删除\'\n}\nvar isDefault = node.isDefault == null ? node.is_default : node.isDefault\nif (text(isDefault) == \'1\' || isDefault == true) {\n    exit 400, \'默认节点不能删除，请先设置其他节点为默认节点\'\n}\ndb.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({ is_del: 1, updated_time: new Date() })\nreturn { success: true }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/03.删除数据同步节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_nifi_node_access_options_01','ods_nifi_node_access_options_01','api','{\n  "properties": {},\n  "id": "ods_nifi_node_access_options_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "04.数据接入节点选项",\n  "path": "/nifi-node/access-options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{}",\n  "responseBody": "{\\n  \\"list\\": []\\n}",\n  "description": "数据接入节点选项及所属网络图标配置（POST /ods/nifi-node/access-options）。默认读取当前租户已启用节点；action=saveNetworkIcon 用于维护 SSWL 网络图标；涉及 sym_dict_t、nifi_node_t 等业务表；执行数据库写入并返回处理结果。",\n  "script": null\n}\n================================\n// 接口：04.数据接入节点选项\n// 路由：POST /ods/nifi-node/access-options\n// 业务说明：数据接入节点选项及所属网络图标配置（POST /ods/nifi-node/access-options）。默认读取当前租户已启用节点；action=saveNetworkIcon 用于维护 SSWL 网络图标；涉及 sym_dict_t、nifi_node_t 等业务表；执行数据库写入并返回处理结果。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar action = text(body?.action).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再读取数据接入节点\'\n}\n\n// 以下从 sym_dict_t 业务表读取或维护当前操作涉及的记录。\nvar networkRoot = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'dict_code\', \'SSWL\').eq(\'is_del\', 0).selectOne()\nvar allowedIcons = [\'safe\', \'menu-earth\', \'tree\', \'database-network\', \'connection\', \'organisation\']\nif (action == \'saveNetworkIcon\') {\n    if (networkRoot == null) {\n        exit 400, \'未配置 SSWL 数据字典，无法设置所属网络图标\'\n    }\n    var targetNetworkCode = text(body?.networkCode).trim()\n    var targetIcon = text(body?.icon).trim()\n    if (targetNetworkCode == \'\' || targetIcon == \'\') {\n        exit 400, \'请选择所属网络和图标\'\n    }\n    if (allowedIcons.indexOf(targetIcon) < 0) {\n        exit 400, \'不支持的所属网络图标\'\n    }\n    var targetNetwork = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', networkRoot.tid).eq(\'dict_code\', targetNetworkCode).eq(\'is_del\', 0).selectOne()\n    if (targetNetwork == null) {\n        exit 400, \'所属网络不存在或已删除\'\n    }\n    db.table(\'sym_dict_t\').where().eq(\'tid\', targetNetwork.tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).update({ icon: targetIcon })\n    return { saved: true, networkCode: targetNetworkCode, icon: targetIcon }\n}\nvar networks = []\nvar networkNames = {}\nif (networkRoot != null) {\n    var dictionaryRows = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', networkRoot.tid).eq(\'is_del\', 0).orderBy(\'sort_no\', \'asc\').select()\n    for (dictionary in (dictionaryRows == null ? [] : dictionaryRows)) {\n        var networkCode = text(dictionary.dictCode == null ? dictionary.dict_code : dictionary.dictCode).trim()\n        var networkName = text(dictionary.dictName == null ? dictionary.dict_name : dictionary.dictName).trim()\n        if (networkCode != \'\' && networkName != \'\') {\n            networkNames[networkCode] = networkName\n            networks.add({ value: networkCode, label: networkName, tagType: text(dictionary.tagType == null ? dictionary.tag_type : dictionary.tagType).trim(), icon: text(dictionary.icon).trim() })\n        }\n    }\n}\n\nvar rows = db.table(\'nifi_node_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .eq(\'enabled\', 1)\n    .orderBy(\'is_default\', \'desc\')\n    .orderBy(\'updated_time\', \'desc\')\n    .select()\nvar list = []\nfor (row in (rows == null ? [] : rows)) {\n    var nodeCode = text(row.nodeCode == null ? row.node_code : row.nodeCode).trim()\n    var nodeName = text(row.nodeName == null ? row.node_name : row.nodeName).trim()\n    var legacyNetwork = text(row.networkType == null ? row.network_type : row.networkType).trim()\n    var networkCode = text(row.networkCode == null ? row.network_code : row.networkCode).trim()\n    if (networkCode == \'\') {\n        networkCode = legacyNetwork == \'公安网\' ? \'GAW\' : (legacyNetwork == \'互联网\' ? \'HLW\' : (legacyNetwork == \'专网\' || legacyNetwork == \'ZWW\' ? \'SPZW\' : legacyNetwork))\n    }\n    var networkName = text(networkNames[networkCode]).trim()\n    if (networkName == \'\') {\n        networkName = legacyNetwork == \'\' ? networkCode : legacyNetwork\n    }\n    var baseUrl = text(row.baseUrl == null ? row.base_url : row.baseUrl).trim().replaceAll(\'/+$\', \'\')\n    if (nodeCode == \'\' || nodeName == \'\' || baseUrl == \'\') {\n        continue\n    }\n    list.add({\n        value: nodeCode,\n        label: networkName + \' · \' + nodeName,\n        nodeId: text(row.tid),\n        tid: text(row.tid),\n        nodeCode: nodeCode,\n        nodeName: nodeName,\n        networkCode: networkCode,\n        networkName: networkName,\n        baseUrl: baseUrl,\n        isDefault: row.isDefault == null ? row.is_default : row.isDefault\n    })\n}\nreturn { list: list, networks: networks }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/04.数据接入节点选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_service_node_page_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_service_node_page_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "05.数据服务节点列表",\n  "path": "/service-node/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"发布\\"\\n}",\n  "responseBody": "{\\n  \\"list\\": [],\\n  \\"total\\": 0\\n}",\n  "description": "数据服务节点列表（POST /ods/service-node/page）。读取当前租户服务发布节点，不返回部署凭证引用以外的敏感信息；使用请求参数 keyword；涉及 service_node_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：05.数据服务节点列表\n// 路由：POST /ods/service-node/page\n// 业务说明：数据服务节点列表（POST /ods/service-node/page）。读取当前租户服务发布节点，不返回部署凭证引用以外的敏感信息；使用请求参数 keyword；涉及 service_node_t 等业务表。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar keyword = text(body?.keyword).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再查看节点配置\'\n}\n// 以下从 service_node_t 业务表读取或维护当前操作涉及的记录。\nvar rows = db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    .orderBy(\'is_default\', \'desc\').orderBy(\'updated_time\', \'desc\').select()\nvar list = []\nfor (row in (rows == null ? [] : rows)) {\n    var name = row.nodeName == null ? row.node_name : row.nodeName\n    var code = row.nodeCode == null ? row.node_code : row.nodeCode\n    var domain = row.businessDomain == null ? row.business_domain : row.businessDomain\n    var serviceType = row.serviceType == null ? row.service_type : row.serviceType\n    if (keyword != \'\' && text(name).indexOf(keyword) < 0 && text(code).indexOf(keyword) < 0 && text(domain).indexOf(keyword) < 0 && text(serviceType).indexOf(keyword) < 0) {\n        continue\n    }\n    list.add({\n        tid: row.tid, nodeName: name, nodeCode: code, businessDomain: domain, serviceType: serviceType,\n        baseUrl: row.baseUrl == null ? row.base_url : row.baseUrl,\n        managementUrl: row.managementUrl == null ? row.management_url : row.managementUrl,\n        credentialRef: row.credentialRef == null ? row.credential_ref : row.credentialRef,\n        enabled: row.enabled == null ? 1 : row.enabled,\n        isDefault: row.isDefault == null ? row.is_default : row.isDefault,\n        localNode: row.localNode == null ? row.local_node : row.localNode,\n        remark: row.remark,\n        updatedTime: row.updatedTime == null ? row.updated_time : row.updatedTime\n    })\n}\nreturn { list: list, total: list.size() }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/05.数据服务节点列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_service_node_save_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_service_node_save_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "06.保存数据服务节点",\n  "path": "/service-node/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"nodeName\\": \\"服务发布主节点\\",\\n  \\"nodeCode\\": \\"service-primary\\",\\n  \\"businessDomain\\": \\"公共服务\\",\\n  \\"serviceType\\": \\"API 服务\\",\\n  \\"baseUrl\\": \\"https://api.example.com\\"\\n}",\n  "responseBody": "{\\n  \\"tid\\": \\"2087600000000000001\\"\\n}",\n  "description": "保存数据服务节点（POST /ods/service-node/saveOrUpdate）。维护当前租户发布节点，部署凭证仅保存凭证引用；使用请求参数 tid、nodeName、nodeCode、businessDomain、serviceType、baseUrl、managementUrl、enabled；涉及 service_node_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：06.保存数据服务节点\n// 路由：POST /ods/service-node/saveOrUpdate\n// 业务说明：保存数据服务节点（POST /ods/service-node/saveOrUpdate）。维护当前租户发布节点，部署凭证仅保存凭证引用；使用请求参数 tid、nodeName、nodeCode、businessDomain、serviceType、baseUrl、managementUrl、enabled；涉及 service_node_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || text(value).trim() == \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar tid = text(body?.tid).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nvar name = text(body?.nodeName).trim()\nvar code = text(body?.nodeCode).trim()\nvar businessDomain = text(body?.businessDomain).trim()\nvar serviceType = text(body?.serviceType).trim()\nvar baseUrl = text(body?.baseUrl).trim().replaceAll(\'/+$\', \'\')\nvar managementUrl = text(body?.managementUrl).trim().replaceAll(\'/+$\', \'\')\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再维护节点\'\n}\nif (blank(name) || blank(code) || blank(businessDomain) || blank(serviceType) || blank(baseUrl)) {\n    exit 400, \'节点名称、节点编码、业务域、服务类型和服务地址不能为空\'\n}\nif (!baseUrl.matches(\'^https?://.+\') || (!blank(managementUrl) && !managementUrl.matches(\'^https?://.+\'))) {\n    exit 400, \'服务地址和管理部署地址必须以 http:// 或 https:// 开头\'\n}\nvar now = new Date()\nvar enabled = body?.enabled == false || text(body?.enabled) == \'0\' ? 0 : 1\nvar isDefault = body?.isDefault == true || text(body?.isDefault) == \'1\' ? 1 : 0\nvar localNode = body?.localNode == true || text(body?.localNode) == \'1\' ? 1 : 0\nif (isDefault == 1 && enabled == 0) {\n    exit 400, \'默认发布节点必须保持启用状态\'\n}\n// 以下从 service_node_t 业务表读取或维护当前操作涉及的记录。\nvar duplicate = db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'node_code\', code).eq(\'is_del\', 0).selectOne()\nif (duplicate != null && text(duplicate.tid) != tid) {\n    exit 400, \'节点编码已存在，请使用其他编码\'\n}\nif (isDefault == 1) {\n    db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).update({ is_default: 0, updated_time: now })\n}\nif (blank(tid)) {\n    tid = IdUtil.getSnowflakeNextIdStr()\n    db.table(\'service_node_t\').primary(\'tid\').insert({\n        tid: tid, tenant_id: tenantId, node_name: name, node_code: code, business_domain: businessDomain, service_type: serviceType,\n        base_url: baseUrl, management_url: managementUrl, credential_ref: text(body?.credentialRef).trim(), enabled: enabled,\n        is_default: isDefault, local_node: localNode, remark: text(body?.remark).trim(), created_time: now, updated_time: now, is_del: 0\n    })\n} else {\n    var existing = db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n    if (existing == null) {\n        exit 404, \'数据服务节点不存在或已删除\'\n    }\n    var existingLocal = existing.localNode == null ? existing.local_node : existing.localNode\n    if ((text(existingLocal) == \'1\' || existingLocal == true) && localNode == 0) {\n        exit 400, \'本机发布节点不能取消本机标记\'\n    }\n    db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({\n        node_name: name, node_code: code, business_domain: businessDomain, service_type: serviceType, base_url: baseUrl,\n        management_url: managementUrl, credential_ref: text(body?.credentialRef).trim(), enabled: enabled,\n        is_default: isDefault, local_node: localNode, remark: text(body?.remark).trim(), updated_time: now\n    })\n}\nreturn { tid: tid }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/06.保存数据服务节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_service_node_delete_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_service_node_delete_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "07.删除数据服务节点",\n  "path": "/service-node/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{\\n  \\"tid\\": \\"2087600000000000002\\"\\n}",\n  "responseBody": "{\\n  \\"success\\": true\\n}",\n  "description": "删除数据服务节点（POST /ods/service-node/delete）。本机节点和默认节点不可删除；使用请求参数 tid；涉及 service_node_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：07.删除数据服务节点\n// 路由：POST /ods/service-node/delete\n// 业务说明：删除数据服务节点（POST /ods/service-node/delete）。本机节点和默认节点不可删除；使用请求参数 tid；涉及 service_node_t 等业务表。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar tid = text(body?.tid).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tid == \'\') {\n    exit 400, \'节点标识不能为空\'\n}\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再维护节点\'\n}\n// 以下从 service_node_t 业务表读取或维护当前操作涉及的记录。\nvar node = db.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (node == null) {\n    exit 404, \'数据服务节点不存在或已删除\'\n}\nvar isDefault = node.isDefault == null ? node.is_default : node.isDefault\nvar localNode = node.localNode == null ? node.local_node : node.localNode\nif (text(isDefault) == \'1\' || isDefault == true) {\n    exit 400, \'默认发布节点不能删除，请先设置其他节点为默认节点\'\n}\nif (text(localNode) == \'1\' || localNode == true) {\n    exit 400, \'本机发布节点不能删除\'\n}\ndb.table(\'service_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({ is_del: 1, updated_time: new Date() })\nreturn { success: true }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/01.数据同步节点/07.删除数据服务节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "ods_nifi_node_page_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "01.数据同步节点列表",\n  "createTime": null,\n  "updateTime": 1790066867795,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/nifi-node/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"主节点\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"list\\": [],\\n  \\"total\\": 0\\n}",\n  "description": "数据同步节点列表（POST /ods/nifi-node/page）。读取当前登录租户的 nifi_node_t，仅返回本租户未删除节点；使用请求参数 keyword、revealPasswordNodeId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.数据同步节点列表\n// 路由：POST /ods/nifi-node/page\n// 业务说明：数据同步节点列表（POST /ods/nifi-node/page）。读取当前登录租户的 nifi_node_t，仅返回本租户未删除节点；使用请求参数 keyword、revealPasswordNodeId。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar keyword = text(body?.keyword).trim()\nvar revealPasswordNodeId = text(body?.revealPasswordNodeId).trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后再查看节点配置\'\n}\n// 以下从 sym_dict_t 业务表读取或维护当前操作涉及的记录。\nvar root = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'dict_code\', \'SSWL\').eq(\'is_del\', 0).selectOne()\nvar networkNames = {}\nvar networkIcons = {}\nif (root != null) {\n    var dictionaries = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', root.tid).eq(\'is_del\', 0).select()\n    for (dictionary in (dictionaries == null ? [] : dictionaries)) {\n        var dictionaryCode = text(dictionary.dictCode == null ? dictionary.dict_code : dictionary.dictCode).trim()\n        if (dictionaryCode != \'\') {\n            networkNames[dictionaryCode] = text(dictionary.dictName == null ? dictionary.dict_name : dictionary.dictName).trim()\n            networkIcons[dictionaryCode] = text(dictionary.icon).trim()\n        }\n    }\n}\n\nvar rows = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    .orderBy(\'is_default\', \'desc\').orderBy(\'updated_time\', \'desc\').select()\nvar list = []\nfor (row in (rows == null ? [] : rows)) {\n    var nodeName = row.nodeName == null ? row.node_name : row.nodeName\n    var nodeCode = row.nodeCode == null ? row.node_code : row.nodeCode\n    var legacyNetwork = text(row.networkType == null ? row.network_type : row.networkType).trim()\n    var networkCode = text(row.networkCode == null ? row.network_code : row.networkCode).trim()\n    if (networkCode == \'\') {\n        networkCode = legacyNetwork == \'公安网\' ? \'GAW\' : (legacyNetwork == \'互联网\' ? \'HLW\' : (legacyNetwork == \'专网\' || legacyNetwork == \'ZWW\' ? \'SPZW\' : legacyNetwork))\n    }\n    var networkName = text(networkNames[networkCode]).trim()\n    if (networkName == \'\') {\n        networkName = legacyNetwork == \'\' ? networkCode : legacyNetwork\n    }\n    if (keyword != \'\' && text(nodeName).indexOf(keyword) < 0 && text(nodeCode).indexOf(keyword) < 0 && networkCode.indexOf(keyword) < 0 && networkName.indexOf(keyword) < 0) {\n        continue\n    }\n    var storedPassword = text(row.authPassword == null ? row.auth_password : row.authPassword)\n    list.add({\n        tid: row.tid,\n        nodeName: nodeName,\n        nodeCode: nodeCode,\n        networkCode: networkCode,\n        networkName: networkName,\n        networkIcon: text(networkIcons[networkCode]).trim(),\n        hasAuthPassword: storedPassword.trim() != \'\',\n        authPassword: text(row.tid) == revealPasswordNodeId ? storedPassword : \'\',\n        baseUrl: row.baseUrl == null ? row.base_url : row.baseUrl,\n        rootProcessGroupId: row.rootProcessGroupId == null ? row.root_process_group_id : row.rootProcessGroupId,\n        authUsername: row.authUsername == null ? row.auth_username : row.authUsername,\n        insecureTls: row.insecureTls == null ? row.insecure_tls : row.insecureTls,\n        jdbcDriverDirectory: row.jdbcDriverLocations == null ? row.jdbc_driver_locations : row.jdbcDriverLocations,\n        remark: row.remark,\n        enabled: row.enabled == null ? 1 : row.enabled,\n        isDefault: row.isDefault == null ? row.is_default : row.isDefault,\n        updatedTime: row.updatedTime == null ? row.updated_time : row.updatedTime\n    })\n}\nreturn { list: list, total: list.size() }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/01.数据同步节点列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1155bcd0ccad47b49a6c4a94251cf52c',NULL,NULL,'{\n  "properties": {},\n  "id": "1155bcd0ccad47b49a6c4a94251cf52c",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "01.任务监控分页查询",\n  "createTime": 1782955344777,\n  "updateTime": 1790833930101,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"taskStatus\\": \\"all\\",\\n  \\"taskName\\": \\"出入境\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"code\\": 0,\\n  \\"msg\\": \\"success\\",\\n  \\"success\\": true,\\n  \\"data\\": {\\n    \\"total\\": 1,\\n    \\"list\\": [\\n      {\\n        \\"tid\\": \\"示例任务ID\\",\\n        \\"taskName\\": \\"数据接入同步任务\\",\\n        \\"taskStatus\\": 1,\\n        \\"sourceDbName\\": \\"出入境人员动管系统数据库\\",\\n        \\"sourceTableSummary\\": \\"3 张表\\",\\n        \\"targetDbName\\": \\"目标库\\",\\n        \\"targetTableSummary\\": \\"3 张表\\",\\n        \\"syncTables\\": [\\n          {\\n            \\"sourceTableName\\": \\"police_person_info\\",\\n            \\"targetTableName\\": \\"ods_police_person_info\\",\\n            \\"syncStatus\\": 1,\\n            \\"syncStatusText\\": \\"运行中\\"\\n          }\\n        ]\\n      }\\n    ]\\n  }\\n}",\n  "description": "任务监控分页查询（POST /ods/task/page）。只读接口；优先读取 data_access_agg_task_t，并补充 db_datasource_t、db_table_t 形成任务-表同步明细；旧任务表为空时兼容读取 nifi_pipeline_t 流水线快照；用于任务管理页面主表展开查看表同步情况；使用请求参数 pageNum、pageSize、taskStatus、taskName、nifiNetworkCode、nifiNodeId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.任务监控分页查询\n// 路由：POST /ods/task/page\n// 业务说明：任务监控分页查询（POST /ods/task/page）。只读接口；优先读取 data_access_agg_task_t，并补充 db_datasource_t、db_table_t 形成任务-表同步明细；旧任务表为空时兼容读取 nifi_pipeline_t 流水线快照；用于任务管理页面主表展开查看表同步情况；使用请求参数 pageNum、pageSize、taskStatus、taskName、nifiNetworkCode、nifiNodeId。\n/*\n * 任务监控分页查询（POST /ods/task/page）\n *\n * 业务语义：任务管理页面以“任务”为主行，展开后查看该任务下每张表的同步情况。\n * 读取范围：data_access_agg_task_t / db_datasource_t / db_table_t / nifi_pipeline_t。\n * 兼容策略：新登记的接入任务读 data_access_agg_task_t；如果旧任务表为空，则回退 nifi_pipeline_t。\n * 写入行为：只读，不创建任务、不启动任务、不更新运行状态。\n */\nimport java.util.ArrayList\nimport jsons\nimport tenantRuntime\n\nvar text = value => {\n    if (value == null) {\n        return \'\'\n    }\n    return (value + \'\').trim()\n}\n\nvar blank = value => text(value) == \'\'\n\nvar firstText = (config, keys) => {\n    if (config == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = config[key]\n        if (!blank(value)) {\n            return text(value)\n        }\n    }\n    return null\n}\n\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::long\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::long\npageNum = pageNum < 1 ? 1 : pageNum\npageSize = pageSize < 1 ? 20 : pageSize\nvar offset = (pageNum - 1) * pageSize\nvar status = text(body?.taskStatus)\nvar keyword = text(body?.taskName).toLowerCase()\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后查看接入任务\'\n}\n\n// 当前运行态由租户默认的数据接入节点负责。历史任务尚未记录独立节点时，\n// 按该实际运行节点过滤，避免树形筛选出现“选了节点却仍混入其他节点任务”。\nvar selectedNetworkCode = text(body?.nifiNetworkCode)\nvar selectedNodeId = text(body?.nifiNodeId)\nvar runtimeNode = db.table(\'nifi_node_t\')\n    .columns(\'tid\', \'network_code\', \'node_code\', \'node_name\')\n    .where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).eq(\'enabled\', 1)\n    .orderBy(\'is_default\', \'desc\').orderBy(\'updated_time\', \'desc\').selectOne()\nvar runtimeNodeId = runtimeNode == null ? \'\' : text(runtimeNode.tid)\nvar runtimeNetworkCode = runtimeNode == null ? \'\' : text(runtimeNode.networkCode)\nvar matchesRuntimeNode = (blank(selectedNetworkCode) || selectedNetworkCode == runtimeNetworkCode)\n    && (blank(selectedNodeId) || selectedNodeId == runtimeNodeId)\nif (!matchesRuntimeNode) {\n    return { pageNum: pageNum, pageSize: pageSize, total: 0, list: [] }\n}\n\n// 运行状态归一：0 未启用，1 运行中，2 运行异常。\nvar statusOf = value => {\n    var normalized = text(value).toUpperCase()\n    if (normalized == \'RUNNING\' || normalized == \'STARTING\' || normalized == \'DEPLOYING\') {\n        return 1\n    }\n    if (normalized.contains(\'ERROR\') || normalized == \'INVALID\' || normalized == \'FAILED\') {\n        return 2\n    }\n    return 0\n}\n\nvar datasourceName = id => {\n    if (blank(id)) {\n        return null\n    }\n    var row = db.table(\'db_datasource_t\').columns(\'db_name\').where()\n        .eq(\'tid\', id).eq(\'is_del\', 0).selectOne()\n    return row == null ? null : row.dbName\n}\n\nvar tableRow = id => {\n    if (blank(id)) {\n        return null\n    }\n    return db.table(\'db_table_t\').columns(\'tid\', \'table_name\', \'table_name_cn\', \'catalog_name\', \'record_count\').where()\n        .eq(\'tid\', id).eq(\'is_del\', 0).selectOne()\n}\n\nvar tableDisplayName = row => {\n    if (row == null) {\n        return null\n    }\n    return !blank(row.tableNameCn) ? row.tableNameCn : row.tableName\n}\n\nvar scheduleText = row => {\n    if (!blank(row.cronExpress)) {\n        return row.cronExpress\n    }\n    if (row.scheduleStrategy == 0) {\n        return \'实时\'\n    }\n    if (row.scheduleCycle == 1) {\n        return \'每日\'\n    }\n    if (row.scheduleCycle == 2) {\n        return \'每周\'\n    }\n    if (row.scheduleCycle == 3) {\n        return \'每月\'\n    }\n    return blank(row.scheduleCycle) ? null : row.scheduleCycle\n}\n\nvar statusTextOf = value => {\n    var v = value::int\n    if (v == 1) {\n        return \'运行中\'\n    }\n    if (v == 2) {\n        return \'运行异常\'\n    }\n    return \'未启用\'\n}\n\nvar matchesKeyword = row => {\n    if (blank(keyword)) {\n        return true\n    }\n    var content = (\n        text(row.taskName) + \' \' +\n        text(row.sourceDbName) + \' \' +\n        text(row.sourceTableName) + \' \' +\n        text(row.targetDbName) + \' \' +\n        text(row.targetTableName)\n    ).toLowerCase()\n    return content.contains(keyword)\n}\n\nvar decorateTaskRow = row => {\n    var sourceTable = tableRow(row.sourceTableId)\n    var targetTable = tableRow(row.targetTableId)\n    row.sourceDbName = datasourceName(row.sourceDbId)\n    row.targetDbName = datasourceName(row.targetDbId)\n    row.sourceTableName = tableDisplayName(sourceTable)\n    row.targetTableName = tableDisplayName(targetTable)\n    row.targetPhysicalTableName = targetTable == null ? null : targetTable.tableName\n    row.sourceTableSummary = row.sourceTableName\n    row.targetTableSummary = row.targetTableName\n    row.scheduleFrequency = scheduleText(row)\n    row.nifiNodeId = runtimeNodeId\n    row.nifiNetworkCode = runtimeNetworkCode\n    row.nifiNodeName = runtimeNode == null ? null : runtimeNode.nodeName\n    row.syncTables = [{\n        tid: row.tid,\n        taskId: row.tid,\n        sourceDbName: row.sourceDbName,\n        sourceTableId: row.sourceTableId,\n        sourceTableName: row.sourceTableName,\n        targetDbName: row.targetDbName,\n        targetTableId: row.targetTableId,\n        targetTableName: row.targetTableName,\n        targetPhysicalTableName: row.targetPhysicalTableName,\n        primaryKey: row.sourceTablePrimaryKey,\n        incrementKey: row.sourceTableIncrementKey,\n        dataCount: sourceTable == null ? null : sourceTable.recordCount,\n        lastRunning: row.lastRunning,\n        endRunning: row.endRunning,\n        syncStatus: row.taskStatus,\n        syncStatusText: statusTextOf(row.taskStatus),\n        monitorStatus: row.monitorStatus,\n        monitorMsg: row.monitorMsg\n    }]\n    return row\n}\n\n// 主任务表查询：这里保持按 data_access_agg_task_t 分页，避免一次性读取大量运行监控数据。\nvar query = db.table(\'data_access_agg_task_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\nif (!blank(status) && status != \'all\') {\n    var statusValue = status::int\n    if (statusValue == 2) {\n        query.eq(\'task_status\', 1).in(\'monitor_status\', [\'ERROR\', \'Error\', \'error\'])\n    } else if (statusValue == 1) {\n        query.eq(\'task_status\', 1).notIn(\'monitor_status\', [\'ERROR\', \'Error\', \'error\'])\n    } else {\n        query.eq(\'task_status\', statusValue)\n    }\n}\nif (!blank(body?.taskName)) {\n    query.like(\'task_name\', \'%\' + body.taskName + \'%\')\n}\n\nvar result = query.orderBy(\'updated_time\', \'desc\').page(pageSize, offset)\nresult.list = result.list == null ? [] : result.list\nvar decorated = new ArrayList()\nfor (row in result.list) {\n    var item = decorateTaskRow(row)\n    if (matchesKeyword(item)) {\n        decorated.add(item)\n    }\n}\nresult.list = decorated\n\n// 如果业务任务表为空，兼容展示 data-elements-yunti 迁移过来的 NiFi 流水线。\nvar existingTask = db.table(\'data_access_agg_task_t\').columns(\'tid\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nvar taskTotal = existingTask == null ? 0 : 1\nif (taskTotal > 0) {\n    return result\n}\n\nvar parseDatabaseFromJdbcUrl = jdbcUrl => {\n    var url = text(jdbcUrl)\n    if (blank(url)) {\n        return null\n    }\n    var queryIndex = url.indexOf(\'?\')\n    if (queryIndex >= 0) {\n        url = url.substring(0, queryIndex)\n    }\n    var slashIndex = url.lastIndexOf(\'/\')\n    if (slashIndex >= 0 && slashIndex < url.length() - 1) {\n        return url.substring(slashIndex + 1)\n    }\n    return null\n}\n\nvar extractDslInfo = pipeline => {\n    var info = {\n        sourceDbName: null,\n        sourceTableName: null,\n        targetDbName: null,\n        targetTableName: null,\n        scheduleFrequency: null\n    }\n    var dslText = text(pipeline.dslJson == null ? pipeline.dsl_json : pipeline.dslJson)\n    if (blank(dslText)) {\n        return info\n    }\n    var dsl = jsons.toJSONObject(dslText)\n    var nodes = dsl == null ? null : dsl.nodes\n    if (nodes == null) {\n        return info\n    }\n    for (node in nodes) {\n        var category = text(node.category).toLowerCase()\n        var manifestKey = text(node.manifestKey == null ? node.manifest_key : node.manifestKey).toLowerCase()\n        var config = node.config\n        if (config != null && text(config).startsWith(\'{\')) {\n            config = jsons.toJSONObject(text(config))\n        }\n        var isSource = category == \'source\' || manifestKey.startsWith(\'source.\')\n        var isTarget = category == \'sink\' || category == \'target\'\n            || manifestKey.startsWith(\'sink.\') || manifestKey.startsWith(\'target.\')\n        if (isSource) {\n            info.sourceDbName = info.sourceDbName || firstText(config, [\'database\', \'dbName\', \'host\', \'bucket\'])\n            info.sourceTableName = info.sourceTableName || firstText(config, [\'table\', \'tableName\', \'topic\', \'path\'])\n            info.scheduleFrequency = info.scheduleFrequency || firstText(config, [\'schedulingPeriod\', \'cronExpression\'])\n        }\n        if (isTarget) {\n            info.targetDbName = info.targetDbName || firstText(config, [\'database\', \'dbName\'])\n                || parseDatabaseFromJdbcUrl(config == null ? null : config.jdbcUrl)\n            info.targetTableName = info.targetTableName || firstText(config, [\'table\', \'tableName\', \'targetTable\', \'topic\'])\n        }\n    }\n    return info\n}\n\nvar filtered = new ArrayList()\nvar pipelines = db.table(\'nifi_pipeline_t\').where().eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).orderBy(\'updated_at\', \'desc\').select()\nfor (pipeline in pipelines) {\n    var taskStatus = statusOf(pipeline.status)\n    if (!blank(status) && status != \'all\' && taskStatus != status::int) {\n        continue\n    }\n    var dslInfo = extractDslInfo(pipeline)\n    var item = {\n        tid: pipeline.id,\n        id: pipeline.id,\n        pipelineId: pipeline.id,\n        processGroupId: pipeline.nifiProcessGroupId,\n        recordSource: \'pipeline\',\n        taskName: pipeline.name,\n        taskDesc: pipeline.description,\n        taskStatus: taskStatus,\n        currentStatus: pipeline.status,\n        lastRunning: pipeline.lastDeployedAt,\n        endRunning: pipeline.lastStoppedAt,\n        scheduleRunning: dslInfo.scheduleFrequency,\n        scheduleFrequency: dslInfo.scheduleFrequency,\n        sourceDbName: dslInfo.sourceDbName,\n        sourceTableName: dslInfo.sourceTableName,\n        sourceTableSummary: dslInfo.sourceTableName,\n        targetDbName: dslInfo.targetDbName,\n        targetTableName: dslInfo.targetTableName,\n        targetTableSummary: dslInfo.targetTableName,\n        createdTime: pipeline.createdAt,\n        updatedTime: pipeline.updatedAt,\n        syncTables: [{\n            taskId: pipeline.id,\n            sourceDbName: dslInfo.sourceDbName,\n            sourceTableName: dslInfo.sourceTableName,\n            targetDbName: dslInfo.targetDbName,\n            targetTableName: dslInfo.targetTableName,\n            lastRunning: pipeline.lastDeployedAt,\n            endRunning: pipeline.lastStoppedAt,\n            syncStatus: taskStatus,\n            syncStatusText: statusTextOf(taskStatus),\n            monitorStatus: pipeline.status,\n            monitorMsg: pipeline.description\n        }]\n    }\n    if (matchesKeyword(item)) {\n        filtered.add(item)\n    }\n}\n\nvar start = offset\nvar end = offset + pageSize\nif (start < 0) {\n    start = 0\n}\nif (end > filtered.size()) {\n    end = filtered.size()\n}\nreturn {\n    pageNum: pageNum,\n    pageSize: pageSize,\n    total: filtered.size(),\n    list: start >= filtered.size() ? [] : new ArrayList(filtered.subList(start::int, end::int))\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/01.任务监控分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('63a6b386f1d54d05aa0a622aa92d4510',NULL,NULL,'{\n  "properties": {},\n  "id": "63a6b386f1d54d05aa0a622aa92d4510",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "02.保存数据接入任务",\n  "createTime": 1782955344789,\n  "updateTime": 1786191945693,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dataCatalogId\\": \\"CAT-20240522\\",\\n    \\"taskName\\": \\"订单数据同步任务\\",\\n    \\"taskTypeName\\": \\"增量同步\\",\\n    \\"taskTypeId\\": \\"SYNC_02\\",\\n    \\"taskDesc\\": \\"从业务库定时抓取订单增量数据至数仓\\",\\n    \\"sourceDbId\\": \\"DB_SOURCE_001\\",\\n    \\"sourceTableId\\": \\"order_main\\",\\n    \\"sourceTablePrimaryKey\\": \\"id\\",\\n    \\"sourceTableIncrementKey\\": \\"update_time\\",\\n    \\"targetDbId\\": \\"DB_TARGET_001\\",\\n    \\"targetTableId\\": \\"ods_order_main\\",\\n    \\"targetTablePrimaryKey\\": \\"id\\",\\n    \\"scheduleStrategy\\": 2,\\n    \\"scheduleCycle\\": 0,\\n    \\"scheduleRunning\\": \\"2024-05-22 01:00:00\\",\\n    \\"scheduleRunningStart\\": \\"2024-05-01 00:00:00\\",\\n    \\"scheduleFaildRetry\\": 3,\\n    \\"cronExpress\\": \\"0 0 1 * * ?\\",\\n    \\"taskStatus\\": 0,\\n    \\"lastRunning\\": \\"2024-05-21 01:00:05\\",\\n    \\"lastStatusValue\\": \\"COMPLETED\\",\\n    \\"endRunning\\": \\"2024-05-21 01:05:20\\",\\n    \\"tenantId\\": \\"T-9527\\",\\n    \\"columnMapping\\": [\\n        {\\n            \\"sourceField\\": \\"order_id\\",\\n            \\"sourceFieldCn\\": \\"订单编号\\",\\n            \\"sourceFieldLength\\": 32,\\n            \\"sourceDataType\\": \\"VARCHAR\\",\\n            \\"targetField\\": \\"id\\",\\n            \\"targetFieldCn\\": \\"主键ID\\",\\n            \\"targetFieldLength\\": 32,\\n            \\"targetDataType\\": \\"VARCHAR\\",\\n            \\"dictEnable\\": 0,\\n            \\"funcEnable\\": 0\\n        },\\n        {\\n            \\"sourceField\\": \\"user_gender\\",\\n            \\"sourceFieldCn\\": \\"用户性别\\",\\n            \\"sourceFieldLength\\": 1,\\n            \\"sourceDataType\\": \\"INT\\",\\n            \\"targetField\\": \\"gender_code\\",\\n            \\"targetFieldCn\\": \\"性别代码\\",\\n            \\"targetFieldLength\\": 1,\\n            \\"targetDataType\\": \\"INT\\",\\n            \\"dictEnable\\": 1,\\n            \\"dictValue\\": \\"性别映射表\\",\\n            \\"dictCode\\": \\"DICT_GENDER\\",\\n            \\"funcEnable\\": 0\\n        },\\n        {\\n            \\"sourceField\\": \\"total_amount\\",\\n            \\"sourceFieldCn\\": \\"总金额\\",\\n            \\"sourceFieldLength\\": 12,\\n            \\"sourceDataType\\": \\"DECIMAL\\",\\n            \\"targetField\\": \\"total_price\\",\\n            \\"targetFieldCn\\": \\"支付金额\\",\\n            \\"targetFieldLength\\": 12,\\n            \\"targetDataType\\": \\"DECIMAL\\",\\n            \\"dictEnable\\": 0,\\n            \\"funcEnable\\": 1,\\n            \\"funcValue\\": \\"金额单位转换\\",\\n            \\"funcCode\\": \\"FUNC_CURRENCY_CONVERT\\"\\n        },\\n        {\\n            \\"sourceField\\": \\"user_mobile\\",\\n            \\"sourceFieldCn\\": \\"手机号\\",\\n            \\"sourceFieldLength\\": 11,\\n            \\"sourceDataType\\": \\"VARCHAR\\",\\n            \\"targetField\\": \\"phone_secret\\",\\n            \\"targetFieldCn\\": \\"脱敏手机号\\",\\n            \\"targetFieldLength\\": 11,\\n            \\"targetDataType\\": \\"VARCHAR\\",\\n            \\"dictEnable\\": 0,\\n            \\"funcEnable\\": 1,\\n            \\"funcValue\\": \\"手机号脱敏\\",\\n            \\"funcCode\\": \\"FUNC_MOBILE_MASK\\"\\n        },\\n        {\\n            \\"sourceField\\": \\"create_time\\",\\n            \\"sourceFieldCn\\": \\"创建时间\\",\\n            \\"sourceFieldLength\\": 0,\\n            \\"sourceDataType\\": \\"DATETIME\\",\\n            \\"targetField\\": \\"ods_create_time\\",\\n            \\"targetFieldCn\\": \\"同步录入时间\\",\\n            \\"targetFieldLength\\": 0,\\n            \\"targetDataType\\": \\"DATETIME\\",\\n            \\"dictEnable\\": 0,\\n            \\"funcEnable\\": 0\\n        }\\n    ],\\n    \\"tid\\": \\"2e83a7abf33140c7a3df27d0c79e98c1\\",\\n    \\"processGroupId\\": \\"测试\\",\\n    \\"processGroupVersion\\": \\"测试\\",\\n    \\"scheduleRunningEnd\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n        \\"dataCatalogId\\": \\"CAT-20240522\\",\\n        \\"taskName\\": \\"订单数据同步任务\\",\\n        \\"taskTypeName\\": \\"增量同步\\",\\n        \\"taskTypeId\\": \\"SYNC_02\\",\\n        \\"taskDesc\\": \\"从业务库定时抓取订单增量数据至数仓\\",\\n        \\"sourceDbId\\": \\"DB_SOURCE_001\\",\\n        \\"sourceTableId\\": \\"order_main\\",\\n        \\"sourceTablePrimaryKey\\": \\"id\\",\\n        \\"sourceTableIncrementKey\\": \\"update_time\\",\\n        \\"targetDbId\\": \\"DB_TARGET_001\\",\\n        \\"targetTableId\\": \\"ods_order_main\\",\\n        \\"targetTablePrimaryKey\\": \\"id\\",\\n        \\"scheduleStrategy\\": 2,\\n        \\"scheduleCycle\\": 0,\\n        \\"scheduleRunning\\": \\"2024-05-22 01:00:00\\",\\n        \\"scheduleRunningStart\\": \\"2024-05-01 00:00:00\\",\\n        \\"scheduleFaildRetry\\": 3,\\n        \\"cronExpress\\": \\"0 0 1 * * ?\\",\\n        \\"taskStatus\\": 0,\\n        \\"lastRunning\\": \\"2024-05-21 01:00:05\\",\\n        \\"lastStatusValue\\": \\"COMPLETED\\",\\n        \\"endRunning\\": \\"2024-05-21 01:05:20\\",\\n        \\"tenantId\\": \\"T-9527\\",\\n        \\"revision\\": null,\\n        \\"createdBy\\": null,\\n        \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n        \\"updatedBy\\": null,\\n        \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n        \\"isDel\\": 0,\\n        \\"columnMapping\\": [\\n            {\\n                \\"tid\\": \\"ef0076399f5245498ead8e34febc26f5\\",\\n                \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n                \\"sourceField\\": \\"order_id\\",\\n                \\"sourceFieldCn\\": \\"订单编号\\",\\n                \\"sourceFieldLength\\": 32,\\n                \\"sourceDataType\\": \\"VARCHAR\\",\\n                \\"targetField\\": \\"id\\",\\n                \\"targetFieldCn\\": \\"主键ID\\",\\n                \\"targetFieldLength\\": 32,\\n                \\"targetDataType\\": \\"VARCHAR\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 0,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"b24f5169c9e843e8bd5c2ad26f676c28\\",\\n                \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n                \\"sourceField\\": \\"user_gender\\",\\n                \\"sourceFieldCn\\": \\"用户性别\\",\\n                \\"sourceFieldLength\\": 1,\\n                \\"sourceDataType\\": \\"INT\\",\\n                \\"targetField\\": \\"gender_code\\",\\n                \\"targetFieldCn\\": \\"性别代码\\",\\n                \\"targetFieldLength\\": 1,\\n                \\"targetDataType\\": \\"INT\\",\\n                \\"dictEnable\\": 1,\\n                \\"dictValue\\": \\"性别映射表\\",\\n                \\"dictCode\\": \\"DICT_GENDER\\",\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 1,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"6aeffbf49a6d41ecaf8bb5c94c5d2140\\",\\n                \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n                \\"sourceField\\": \\"total_amount\\",\\n                \\"sourceFieldCn\\": \\"总金额\\",\\n                \\"sourceFieldLength\\": 12,\\n                \\"sourceDataType\\": \\"DECIMAL\\",\\n                \\"targetField\\": \\"total_price\\",\\n                \\"targetFieldCn\\": \\"支付金额\\",\\n                \\"targetFieldLength\\": 12,\\n                \\"targetDataType\\": \\"DECIMAL\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 1,\\n                \\"funcValue\\": \\"金额单位转换\\",\\n                \\"funcCode\\": \\"FUNC_CURRENCY_CONVERT\\",\\n                \\"sortNo\\": 2,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"e94d588077fd46c8813348eadc1bfea2\\",\\n                \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n                \\"sourceField\\": \\"user_mobile\\",\\n                \\"sourceFieldCn\\": \\"手机号\\",\\n                \\"sourceFieldLength\\": 11,\\n                \\"sourceDataType\\": \\"VARCHAR\\",\\n                \\"targetField\\": \\"phone_secret\\",\\n                \\"targetFieldCn\\": \\"脱敏手机号\\",\\n                \\"targetFieldLength\\": 11,\\n                \\"targetDataType\\": \\"VARCHAR\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 1,\\n                \\"funcValue\\": \\"手机号脱敏\\",\\n                \\"funcCode\\": \\"FUNC_MOBILE_MASK\\",\\n                \\"sortNo\\": 3,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"e54dba14592648b3a345a20d371b3f9b\\",\\n                \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n                \\"sourceField\\": \\"create_time\\",\\n                \\"sourceFieldCn\\": \\"创建时间\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"DATETIME\\",\\n                \\"targetField\\": \\"ods_create_time\\",\\n                \\"targetFieldCn\\": \\"同步录入时间\\",\\n                \\"targetFieldLength\\": 0,\\n                \\"targetDataType\\": \\"DATETIME\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 4,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 11:10:22\\",\\n                \\"isDel\\": 0\\n            }\\n        ]\\n    }\\n}",\n  "description": "Magic 负责参数校验、任务与字段映射持久化以及 NiFi 进程组创建编排；使用请求参数 taskName、taskTypeId、tid、processGroupId、processGroupVersion、dataCatalogId、taskTypeName、taskDesc；涉及 data_access_agg_task_t、data_access_field_mapping 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.保存数据接入任务\n// 路由：POST /ods/task/saveOrUpdate\n// 业务说明：Magic 负责参数校验、任务与字段映射持久化以及 NiFi 进程组创建编排；使用请求参数 taskName、taskTypeId、tid、processGroupId、processGroupVersion、dataCatalogId、taskTypeName、taskDesc；涉及 data_access_agg_task_t、data_access_field_mapping 等业务表。\n/*\n * 保存数据接入任务\n *\n * Magic 负责参数校验、任务与字段映射持久化以及 NiFi 进程组创建编排。\n * NiFiClient 仅作为鉴权和 HTTP 运行时适配器使用。更新任务时，仅在父分组\n * 发生变化后创建新进程组并清理旧组，避免无意义地重建运行资源。\n */\nimport cn.hutool.core.util.IdUtil\nimport com.fasterxml.jackson.databind.JsonNode\nimport com.linewell.dataelement.integration.nifi.canvas.nifi.NifiClient as nifiClient\nimport log\nimport tenantRuntime\nif (body == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'请求参数不能为空\'\n}\nvar tenantId = tenantRuntime.id()\n// 解析请求体并为可选参数设置默认值。\nif (body.taskName == null || body.taskName == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'taskName不能为空\'\n}\nif (body.taskTypeId == null || body.taskTypeId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'taskTypeId不能为空\'\n}\n\nvar now = new Date()\nvar tid = body.tid\nvar updating = tid != null && tid != \'\'\nvar old = updating\n    // 从 MySQL 业务表读取当前有效数据。\n    ? db.table(\'data_access_agg_task_t\').where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n    : null\nif (updating && old == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'任务不存在\'\n}\n\nvar processGroupId = body.processGroupId || old?.processGroupId\nvar processGroupVersion = body.processGroupVersion || old?.processGroupVersion\nvar needProcessGroup = !updating || old.taskTypeId != body.taskTypeId\nif (needProcessGroup) {\n    var request = {\n        revision: { version: 0 },\n        disconnectedNodeAcknowledged: false,\n        component: {\n            position: { x: 0, y: 0 },\n            name: body.taskName\n        }\n    }\n    var created = nifiClient.post(\n        \'/process-groups/\' + body.taskTypeId + \'/process-groups\',\n        request,\n        JsonNode.class\n    )\n    processGroupId = created.path(\'id\').asText()\n    if (processGroupId == null || processGroupId == \'\') {\n        processGroupId = created.path(\'component\').path(\'id\').asText()\n    }\n    processGroupVersion = created.path(\'revision\').path(\'version\').asInt(0)\n    if (processGroupId == null || processGroupId == \'\') {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'NiFi进程组创建失败\'\n    }\n}\n\nvar task = {\n    tid: updating ? tid : IdUtil.getSnowflakeNextIdStr(),\n    data_catalog_id: body.dataCatalogId,\n    task_name: body.taskName,\n    task_type_name: body.taskTypeName,\n    task_type_id: body.taskTypeId,\n    task_desc: body.taskDesc,\n    source_db_id: body.sourceDbId,\n    source_table_id: body.sourceTableId,\n    source_table_primary_key: body.sourceTablePrimaryKey,\n    source_table_increment_key: body.sourceTableIncrementKey,\n    target_db_id: body.targetDbId,\n    target_table_id: body.targetTableId,\n    target_table_primary_key: body.targetTablePrimaryKey,\n    schedule_strategy: body.scheduleStrategy,\n    schedule_cycle: body.scheduleCycle,\n    schedule_running: body.scheduleRunning,\n    schedule_running_start: body.scheduleRunningStart,\n    schedule_running_end: body.scheduleRunningEnd,\n    schedule_faild_retry: body.scheduleFaildRetry,\n    cron_express: body.cronExpress,\n    task_status: body.taskStatus,\n    last_running: body.lastRunning,\n    last_status_value: body.lastStatusValue,\n    end_running: body.endRunning,\n    tenant_id: tenantId,\n    process_group_id: processGroupId,\n    process_group_version: processGroupVersion,\n    updated_time: now\n}\n\nif (updating) {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_access_agg_task_t\').primary(\'tid\').update(task)\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_access_field_mapping\').where()\n        .eq(\'task_id\', tid).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_time: now})\n} else {\n    tid = task.tid\n    task.is_del = 0\n    task.created_time = now\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_access_agg_task_t\').primary(\'tid\').insert(task)\n}\n\nvar mappings = []\nfor (index, item in body.columnMapping || []) {\n    mappings.add({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        task_id: tid,\n        source_field: item.sourceField,\n        source_field_cn: item.sourceFieldCn,\n        source_field_length: item.sourceFieldLength,\n        source_data_type: item.sourceDataType,\n        target_field: item.targetField,\n        target_field_cn: item.targetFieldCn,\n        target_field_length: item.targetFieldLength,\n        target_data_type: item.targetDataType,\n        dict_enable: item.dictEnable,\n        dict_value: item.dictValue,\n        dict_code: item.dictCode,\n        func_enable: item.funcEnable,\n        func_value: item.funcValue,\n        func_code: item.funcCode,\n        sort_no: index,\n        tenant_id: tenantId,\n        is_del: 0,\n        created_time: now,\n        updated_time: now\n    })\n}\nif (mappings.size() > 0) {\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_access_field_mapping\').batchInsert(mappings)\n}\n\nif (updating && needProcessGroup && old.processGroupId != null && old.processGroupId != \'\') {\n    try {\n        nifiClient.cleanupProcessGroup(old.processGroupId)\n    } catch (e) {\n        log.warn(\'旧NiFi进程组清理失败, processGroupId={}, message={}\', old.processGroupId, e.message)\n    }\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar result = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n// 从 MySQL 业务表读取当前有效数据。\nresult.columnMapping = db.table(\'data_access_field_mapping\').where()\n    .eq(\'task_id\', tid).eq(\'is_del\', 0)\n    .orderBy(\'sort_no\', \'asc\').select()\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/02.保存数据接入任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0fae2484c3674bae8d7a3cc61cf67225',NULL,NULL,'{\n  "properties": {},\n  "id": "0fae2484c3674bae8d7a3cc61cf67225",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "03.根据id删除任务",\n  "createTime": 1782955344802,\n  "updateTime": 1790826928649,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/deleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"ab6611ed06ef4403b31b6cc605fd9e46\\",\\n    \\"props\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"任务不存在\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "当前租户内按任务 ID 取消接入；允许没有来源表的独立任务；使用请求参数 tid、dryRun；涉及 data_access_agg_task_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t、da_prop_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.根据id删除任务\n// 路由：POST /ods/task/deleteById\n// 业务说明：当前租户内按任务 ID 取消接入；允许没有来源表的独立任务；使用请求参数 tid、dryRun；涉及 data_access_agg_task_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t、da_prop_t 等业务表；执行数据库写入并返回处理结果。\n/*\n * 删除数据接入任务\n *\n * 当前租户内按任务 ID 取消接入；允许没有来源表的独立任务。\n * 先逻辑删除任务、字段映射、监控快照和流水线持久化记录，再清理 NiFi\n * 进程组。只清空指向该任务的目录 accessTaskId，不删除目标物理表。\n * dryRun=true 只校验任务归属并返回计划，不写入或清理运行态。\n */\nimport com.linewell.dataelement.integration.nifi.canvas.nifi.NifiClient as nifiClient\nimport log\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar tid = text(body?.tid)\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'登录状态已失效，请重新登录\' }\nif (tid == \'\') { exit 400, \'tid不能为空\' }\n\n// 独立任务也可能没有来源表；删除权限始终由当前登录租户和任务 ID 决定。\nvar task = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (task == null) { exit 404, \'当前租户下任务不存在\' }\n\nif (body?.dryRun == true) {\n    return {\n        dryRun: true,\n        tid: tid,\n        sourceTableId: text(task.sourceTableId),\n        pipelineId: text(task.pipelineId),\n        sideEffectsApplied: false\n    }\n}\n\nvar now = new Date()\ndb.table(\'data_access_agg_task_t\').where().eq(\'tid\', tid).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    .update({is_del: 1, task_status: 0, updated_time: now})\ndb.table(\'data_access_field_mapping\').where().eq(\'task_id\', tid).eq(\'is_del\', 0)\n    .update({is_del: 1, updated_time: now})\ndb.table(\'data_access_task_monitor_snap_t\').where().eq(\'task_id\', tid).eq(\'is_del\', 0)\n    .update({is_del: 1})\nif (task.pipelineId != null && task.pipelineId != \'\') {\n    db.table(\'nifi_pipeline_t\').where().eq(\'id\', task.pipelineId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_at: System.currentTimeMillis()})\n}\n\nif (task.dataCatalogId != null && task.dataCatalogId != \'\') {\n    var accessTaskProp = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', task.dataCatalogId)\n        .eq(\'prop_name\', \'accessTaskId\')\n        .eq(\'prop_value\', tid)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (accessTaskProp != null) {\n        db.table(\'da_prop_t\').primary(\'tid\').update({\n            tid: accessTaskProp.tid,\n            prop_value: null,\n            updated_time: now\n        }, true)\n    }\n}\n\nif (task.processGroupId != null && task.processGroupId != \'\') {\n    try {\n        nifiClient.cleanupProcessGroup(task.processGroupId)\n    } catch (e) {\n        log.warn(\'NiFi进程组清理失败, processGroupId={}, message={}\', task.processGroupId, e.message)\n    }\n}\n\nreturn {tid: tid, sourceTableId: text(task.sourceTableId), targetTableDeleted: false}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/03.根据id删除任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('47f25be1c4eb4ed89c6f3e7fb36dfd17',NULL,NULL,'{\n  "properties": {},\n  "id": "47f25be1c4eb4ed89c6f3e7fb36dfd17",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "04.根据id查询接入任务信息",\n  "createTime": 1782955344810,\n  "updateTime": 1784437771822,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"3147156bbcc54704822f534f93a7913f\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n        \\"dataCatalogId\\": \\"CAT-20240522\\",\\n        \\"taskName\\": \\"订单数据同步任务\\",\\n        \\"taskTypeName\\": \\"增量同步\\",\\n        \\"taskTypeId\\": \\"SYNC_02\\",\\n        \\"taskDesc\\": \\"从业务库定时抓取订单增量数据至数仓\\",\\n        \\"sourceDbId\\": \\"DB_SOURCE_001\\",\\n        \\"sourceTableId\\": \\"order_main\\",\\n        \\"sourceTablePrimaryKey\\": \\"id\\",\\n        \\"sourceTableIncrementKey\\": \\"update_time\\",\\n        \\"targetDbId\\": \\"DB_TARGET_001\\",\\n        \\"targetTableId\\": \\"ods_order_main\\",\\n        \\"targetTablePrimaryKey\\": \\"id\\",\\n        \\"scheduleStrategy\\": 2,\\n        \\"scheduleCycle\\": 0,\\n        \\"scheduleRunning\\": \\"2024-05-22 01:00:00\\",\\n        \\"scheduleRunningStart\\": \\"2024-05-01 00:00:00\\",\\n        \\"scheduleFaildRetry\\": 3,\\n        \\"cronExpress\\": \\"0 0 1 * * ?\\",\\n        \\"taskStatus\\": 0,\\n        \\"lastRunning\\": \\"2024-05-21 01:00:05\\",\\n        \\"lastStatusValue\\": \\"COMPLETED\\",\\n        \\"endRunning\\": \\"2024-05-21 01:05:20\\",\\n        \\"tenantId\\": \\"T-9527\\",\\n        \\"revision\\": null,\\n        \\"createdBy\\": null,\\n        \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n        \\"updatedBy\\": null,\\n        \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n        \\"isDel\\": 0,\\n        \\"columnMapping\\": [\\n            {\\n                \\"tid\\": \\"34d5a68192ff4d9ca29e87ce3f748eb4\\",\\n                \\"taskId\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n                \\"sourceField\\": \\"order_id\\",\\n                \\"sourceFieldCn\\": \\"订单编号\\",\\n                \\"sourceFieldLength\\": 32,\\n                \\"sourceDataType\\": \\"VARCHAR\\",\\n                \\"targetField\\": \\"id\\",\\n                \\"targetFieldCn\\": \\"主键ID\\",\\n                \\"targetFieldLength\\": 32,\\n                \\"targetDataType\\": \\"VARCHAR\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 0,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"2126a6f1b8c74044861451d9424caa9e\\",\\n                \\"taskId\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n                \\"sourceField\\": \\"user_gender\\",\\n                \\"sourceFieldCn\\": \\"用户性别\\",\\n                \\"sourceFieldLength\\": 1,\\n                \\"sourceDataType\\": \\"INT\\",\\n                \\"targetField\\": \\"gender_code\\",\\n                \\"targetFieldCn\\": \\"性别代码\\",\\n                \\"targetFieldLength\\": 1,\\n                \\"targetDataType\\": \\"INT\\",\\n                \\"dictEnable\\": 1,\\n                \\"dictValue\\": \\"性别映射表\\",\\n                \\"dictCode\\": \\"DICT_GENDER\\",\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 1,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"a993181fdeba41a2a3ca7b6248dcbf4b\\",\\n                \\"taskId\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n                \\"sourceField\\": \\"total_amount\\",\\n                \\"sourceFieldCn\\": \\"总金额\\",\\n                \\"sourceFieldLength\\": 12,\\n                \\"sourceDataType\\": \\"DECIMAL\\",\\n                \\"targetField\\": \\"total_price\\",\\n                \\"targetFieldCn\\": \\"支付金额\\",\\n                \\"targetFieldLength\\": 12,\\n                \\"targetDataType\\": \\"DECIMAL\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 1,\\n                \\"funcValue\\": \\"金额单位转换\\",\\n                \\"funcCode\\": \\"FUNC_CURRENCY_CONVERT\\",\\n                \\"sortNo\\": 2,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"0ad290ef16dc46d8b57fb7793e95b404\\",\\n                \\"taskId\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n                \\"sourceField\\": \\"user_mobile\\",\\n                \\"sourceFieldCn\\": \\"手机号\\",\\n                \\"sourceFieldLength\\": 11,\\n                \\"sourceDataType\\": \\"VARCHAR\\",\\n                \\"targetField\\": \\"phone_secret\\",\\n                \\"targetFieldCn\\": \\"脱敏手机号\\",\\n                \\"targetFieldLength\\": 11,\\n                \\"targetDataType\\": \\"VARCHAR\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 1,\\n                \\"funcValue\\": \\"手机号脱敏\\",\\n                \\"funcCode\\": \\"FUNC_MOBILE_MASK\\",\\n                \\"sortNo\\": 3,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"isDel\\": 0\\n            },\\n            {\\n                \\"tid\\": \\"6f5aadc763d8419daf290d36de43469a\\",\\n                \\"taskId\\": \\"3147156bbcc54704822f534f93a7913f\\",\\n                \\"sourceField\\": \\"create_time\\",\\n                \\"sourceFieldCn\\": \\"创建时间\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"DATETIME\\",\\n                \\"targetField\\": \\"ods_create_time\\",\\n                \\"targetFieldCn\\": \\"同步录入时间\\",\\n                \\"targetFieldLength\\": 0,\\n                \\"targetDataType\\": \\"DATETIME\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null,\\n                \\"sortNo\\": 4,\\n                \\"tenantId\\": \\"T-9527\\",\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": \\"2026-03-02 10:52:50\\",\\n                \\"isDel\\": 0\\n            }\\n        ]\\n    }\\n}",\n  "description": "按接入任务标识读取未删除的主记录及字段映射，并按保存顺序组装编辑页面详情。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.根据id查询接入任务信息\n// 路由：POST /ods/task/queryById\n// 业务说明：按接入任务标识读取未删除的主记录及字段映射，并按保存顺序组装编辑页面详情。\n/*\n * 数据接入任务详情\n *\n * 主表和字段映射均以逻辑删除标记为准。字段映射按 sort_no 返回，\n * 保证编辑页面再次进入时顺序与保存时一致。\n */\nvar tid = body?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tid不能为空\'\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar task = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\nif (task == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'任务不存在\'\n}\n\n// 从 MySQL 业务表读取当前有效数据。\ntask.columnMapping = db.table(\'data_access_field_mapping\').where()\n    .eq(\'task_id\', tid).eq(\'is_del\', 0)\n    .orderBy(\'sort_no\', \'asc\').select()\n// 返回当前业务分支的标准结果。\nreturn task\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/04.根据id查询接入任务信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3ba19eea403c45208c9fb14fdf9a77fe',NULL,NULL,'{\n  "properties": {},\n  "id": "3ba19eea403c45208c9fb14fdf9a77fe",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "05.资源目录集成任务关联",\n  "createTime": 1782955344820,\n  "updateTime": 1784437771823,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "catalogTaskRela",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"catalogId\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n    \\"processGroupId\\": \\"248b7b66-019e-1000-cf70-679477bce2e1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"success\\"\\n}",\n  "description": "清理资源目录与接入任务的关联；使用请求参数 catalogId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.资源目录集成任务关联\n// 路由：POST /ods/task/catalogTaskRela\n// 业务说明：清理资源目录与接入任务的关联；使用请求参数 catalogId。\n/*\n * 清理资源目录与接入任务的关联\n *\n * 该接口只清空目录动态属性 accessTaskId，不删除接入任务。\n * 目录属性保存接口同时负责更新数据库和 ES 投影。\n */\nimport \'@post:/dst/catalog/properties/save\' as saveCatalogProperties\n\n// 解析请求体并为可选参数设置默认值。\nvar catalogId = body?.catalogId\nif (catalogId == null || catalogId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'catalogId不能为空\'\n}\n\nbody = {\n    tid: catalogId,\n    props: { accessTaskId: null }\n}\nsaveCatalogProperties()\n// 返回当前业务分支的标准结果。\nreturn \'success\'\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/05.资源目录集成任务关联.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f541570df3bc4bf3a38e9466d2e16cd7',NULL,NULL,'{\n  "properties": {},\n  "id": "f541570df3bc4bf3a38e9466d2e16cd7",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "06.任务监控快照分页",\n  "createTime": 1784439136875,\n  "updateTime": 1784439136875,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/monitorSnapPage",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"taskId\\": \\"测试\\",\\n    \\"pipelineId\\": \\"测试\\",\\n    \\"processGroupId\\": \\"测试\\",\\n    \\"delayLevel\\": \\"测试\\",\\n    \\"monitorStatus\\": 2,\\n    \\"beginTime\\": \\"2026-07-20 10:00:00\\",\\n    \\"endTime\\": \\"2026-07-20 10:00:00\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "支持按任务、流水线、NiFi 进程组、延迟等级、运行状态和监控时间范围过滤；使用请求参数 pageNum、pageSize、taskId、pipelineId、processGroupId、delayLevel、monitorStatus、beginTime；涉及 data_access_task_monitor_snap_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.任务监控快照分页\n// 路由：POST /ods/task/monitorSnapPage\n// 业务说明：支持按任务、流水线、NiFi 进程组、延迟等级、运行状态和监控时间范围过滤；使用请求参数 pageNum、pageSize、taskId、pipelineId、processGroupId、delayLevel、monitorStatus、beginTime；涉及 data_access_task_monitor_snap_t 等业务表。\n/*\n * 数据接入任务运行快照分页\n *\n * 支持按任务、流水线、NiFi 进程组、延迟等级、运行状态和监控时间范围过滤。\n * 本接口只读持久化快照，不触发 NiFi 运行时调用。\n */\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\npageNum = pageNum < 1 ? 1 : pageNum\npageSize = pageSize < 1 ? 20 : pageSize\n\n// 从 MySQL 业务表读取当前有效数据。\nvar query = db.table(\'data_access_task_monitor_snap_t\').where().eq(\'is_del\', 0)\nif (body?.taskId != null && body.taskId != \'\') {\n    query.eq(\'task_id\', body.taskId)\n}\nif (body?.pipelineId != null && body.pipelineId != \'\') {\n    query.eq(\'pipeline_id\', body.pipelineId)\n}\nif (body?.processGroupId != null && body.processGroupId != \'\') {\n    query.eq(\'process_group_id\', body.processGroupId)\n}\nif (body?.delayLevel != null && body.delayLevel != \'\') {\n    query.eq(\'delay_level\', body.delayLevel)\n}\nif (body?.monitorStatus != null && body.monitorStatus != \'\') {\n    query.eq(\'monitor_status\', body.monitorStatus)\n}\nif (body?.beginTime != null && body.beginTime != \'\') {\n    query.ge(\'monitor_time\', body.beginTime)\n}\nif (body?.endTime != null && body.endTime != \'\') {\n    query.le(\'monitor_time\', body.endTime)\n}\n\nvar result = query.orderBy(\'monitor_time\', \'desc\')\n    .orderBy(\'created_time\', \'desc\')\n    .page(pageSize, (pageNum - 1) * pageSize)\nresult.list = result.list || []\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/06.任务监控快照分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8f8b59890a174e36ad43a290e748290a',NULL,NULL,'{\n  "properties": {},\n  "id": "8f8b59890a174e36ad43a290e748290a",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "07.手工清理任务监控历史",\n  "createTime": 1790845752950,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/monitorSnapCleanup",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"retentionDays\\":30,\\"dryRun\\":true}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "手工预览或清理当前租户超过保留天数的任务监控历史快照。执行清理必须显式传入 confirm=true；不会删除接入任务与最新监控状态；使用请求参数 retentionDays、dryRun、confirm；涉及 data_access_task_monitor_snap_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.手工清理任务监控历史\n// 路由：POST /ods/task/monitorSnapCleanup\n// 业务说明：手工预览或清理当前租户超过保留天数的任务监控历史快照。执行清理必须显式传入 confirm=true；不会删除接入任务与最新监控状态；使用请求参数 retentionDays、dryRun、confirm；涉及 data_access_task_monitor_snap_t 等业务表。\nimport java.time.LocalDateTime;\nimport java.time.format.DateTimeFormatter;\n\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar retentionDays = body?.retentionDays::int(30)\nif (retentionDays < 1 || retentionDays > 1000) {\n    throw new IllegalArgumentException(\'保留天数必须在 1–1000 天之间\')\n}\nvar cutoff = LocalDateTime.now().minusDays(retentionDays)\n    .format(DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss\'))\n// 以下从 data_access_task_monitor_snap_t 业务表读取或维护当前操作涉及的记录。\nvar count = db.table(\'data_access_task_monitor_snap_t\').where()\n    .eq(\'is_del\', 0).lt(\'monitor_time\', cutoff).count()\n\nif (body?.dryRun != false) {\n    return {retentionDays: retentionDays, cutoff: cutoff, count: count, deleted: 0}\n}\nif (body?.confirm != true) {\n    throw new IllegalArgumentException(\'请先预览并确认清理范围\')\n}\nvar deleted = 0\nif (count > 0) {\n    deleted = db.table(\'data_access_task_monitor_snap_t\').where()\n        .eq(\'is_del\', 0).lt(\'monitor_time\', cutoff).delete()\n}\nreturn {retentionDays: retentionDays, cutoff: cutoff, count: count, deleted: deleted}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/07.手工清理任务监控历史.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b36e38effc614a97b017eebae79eba13',NULL,NULL,'{\n  "properties": {},\n  "id": "b36e38effc614a97b017eebae79eba13",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "08.获取最近5次Cron执行时间",\n  "createTime": 1782955344767,\n  "updateTime": 1784437771802,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/lastFiveCron",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"cron\\": \\"5 4 * * * *\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"无效的 Cron 表达式: 5 4 * * * *2 s\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "导入 Spring 提供的 Cron 表达式工具类；使用请求参数 cron；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.获取最近5次Cron执行时间\n// 路由：POST /ods/task/lastFiveCron\n// 业务说明：导入 Spring 提供的 Cron 表达式工具类；使用请求参数 cron；读取或计算后返回业务结果。\n// 导入 Spring 提供的 Cron 表达式工具类\nimport org.springframework.scheduling.support.CronExpression\nimport java.time.ZonedDateTime\nimport java.time.format.DateTimeFormatter\n\n// 获取参数中的 cron 表达式\nvar cron = body.cron \n\n// 1. 校验 Cron 表达式是否有效\nif (!CronExpression.isValidExpression(cron)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "无效的 Cron 表达式: " + cron\n}\n\n// 2. 解析表达式\nvar expression = CronExpression.parse(cron)\nvar result = []\nvar nextTime = ZonedDateTime.now()\n\n// 3. 循环计算最近 5 次执行时间\nfor ( i in range(0,4)) {\n    nextTime = expression.next(nextTime)\n    if (nextTime == null) {\n      break\n    }\n    result.add(nextTime.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")))\n}\n\n// 返回当前业务分支的标准结果。\nreturn  result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/08.获取最近5次Cron执行时间.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b964b2d54ba0477b86d3fb6e6d18c45b',NULL,NULL,'{\n  "properties": {},\n  "id": "b964b2d54ba0477b86d3fb6e6d18c45b",\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "09.任务监控小时趋势",\n  "path": "/monitor/trend",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"beginTime\\":\\"2026-10-03 00:00:00\\",\\"endTime\\":\\"2026-10-04 00:00:00\\",\\"interval\\":\\"hour\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/task/monitor/trend；当前租户至多7天小时级监控快照峰值，绝非目标库确认写入。",\n  "script": null\n}\n================================\n// 流入/流出是 NiFi 快照窗口计数，连续采样可能重叠。按任务取每小时峰值再求和，避免直接相加采样值。\nimport tenantRuntime\nimport cn.hutool.core.date.DateUtil\nimport java.sql.Timestamp\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后查看趋势\'\n}\nvar beginTime = body?.beginTime == null ? \'\' : (\'\' + body.beginTime).trim()\nvar endTime = body?.endTime == null ? \'\' : (\'\' + body.endTime).trim()\nvar interval = body?.interval == null ? \'hour\' : (\'\' + body.interval).trim().toLowerCase()\nif (interval != \'hour\') {\n    exit 400, \'当前只支持按小时汇总\'\n}\nif (!beginTime.matches(\'^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$\')\n    || !endTime.matches(\'^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$\')) {\n    exit 400, \'时间格式必须为YYYY-MM-DD HH:mm:ss\'\n}\nvar startMillis = DateUtil.parse(beginTime, \'yyyy-MM-dd HH:mm:ss\').getTime()\nvar finishMillis = DateUtil.parse(endTime, \'yyyy-MM-dd HH:mm:ss\').getTime()\nif (finishMillis <= startMillis || finishMillis - startMillis > 7 * 24 * 60 * 60 * 1000) {\n    exit 400, \'时间范围必须大于0且不超过7天\'\n}\nvar beginBound = new Timestamp(startMillis)\nvar endBound = new Timestamp(finishMillis)\n\n// 只取原始快照并在脚本内按小时聚合，避免 MySQL DATE_FORMAT 方言绑定。\n// 单次最多 50000 行；超出时明确拒绝，不能静默截断出错误的趋势。\nvar maxRows = 50000\nvar raw = db.page("""\n    SELECT task_id AS taskId,\n           monitor_time AS monitorTime,\n           COALESCE(flow_files_in, 0) AS flowFilesIn,\n           COALESCE(flow_files_out, 0) AS flowFilesOut,\n           COALESCE(bytes_in, 0) AS bytesIn,\n           COALESCE(bytes_out, 0) AS bytesOut,\n           COALESCE(queued_count, 0) AS queuedCount\n      FROM data_access_task_monitor_snap_t\n     WHERE tenant_id = #{tenantId}\n       AND is_del = 0\n       AND monitor_time >= #{beginBound}\n       AND monitor_time < #{endBound}\n     ORDER BY monitor_time, task_id\n""", maxRows + 1, 0)\nif (raw.total > maxRows) {\n    exit 413, \'时间范围内快照超过50000条，请缩短查询时间范围\'\n}\nvar value = (row, name) => {\n    if (row[name] != null) { return row[name] }\n    if (row[name.toLowerCase()] != null) { return row[name.toLowerCase()] }\n    return row[name.toUpperCase()]\n}\nvar asLong = (item) => item == null ? 0 : item::long\nvar finishBucket = (bucket, tasks) => {\n    var point = {\n        bucketTime: bucket, sampleCount: 0, flowFilesIn: 0, flowFilesOut: 0,\n        bytesIn: 0, bytesOut: 0, queuedCountMax: 0\n    }\n    for (task in tasks) {\n        point.sampleCount = point.sampleCount + task.sampleCount\n        point.flowFilesIn = point.flowFilesIn + task.flowFilesIn\n        point.flowFilesOut = point.flowFilesOut + task.flowFilesOut\n        point.bytesIn = point.bytesIn + task.bytesIn\n        point.bytesOut = point.bytesOut + task.bytesOut\n        point.queuedCountMax = Math.max(point.queuedCountMax, task.queuedCountMax)\n    }\n    return point\n}\nvar series = []\nvar currentBucket = \'\'\nvar tasks = []\nvar taskIndex = {}\nfor (row in (raw.list == null ? [] : raw.list)) {\n    // JDBC 的 DATETIME/TIMESTAMP.toString() 均以 yyyy-MM-dd HH 开头；T 分隔符也兼容。\n    var monitorText = (\'\' + value(row, \'monitorTime\')).replace(\'T\', \' \')\n    if (!monitorText.matches(\'^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:.*$\')) {\n        exit 500, \'监控快照时间格式无法识别，已拒绝返回不完整趋势\'\n    }\n    var bucket = monitorText.substring(0, 13) + \':00:00\'\n    if (currentBucket != \'\' && bucket != currentBucket) {\n        series.add(finishBucket(currentBucket, tasks))\n        tasks = []\n        taskIndex = {}\n    }\n    currentBucket = bucket\n    var taskId = \'\' + value(row, \'taskId\')\n    var index = taskIndex[taskId]\n    if (index == null) {\n        tasks.add({sampleCount: 0, flowFilesIn: 0, flowFilesOut: 0,\n            bytesIn: 0, bytesOut: 0, queuedCountMax: 0})\n        index = tasks.size()\n        taskIndex[taskId] = index\n    }\n    var task = tasks[index - 1]\n    task.sampleCount = task.sampleCount + 1\n    task.flowFilesIn = Math.max(task.flowFilesIn, asLong(value(row, \'flowFilesIn\')))\n    task.flowFilesOut = Math.max(task.flowFilesOut, asLong(value(row, \'flowFilesOut\')))\n    task.bytesIn = Math.max(task.bytesIn, asLong(value(row, \'bytesIn\')))\n    task.bytesOut = Math.max(task.bytesOut, asLong(value(row, \'bytesOut\')))\n    task.queuedCountMax = Math.max(task.queuedCountMax, asLong(value(row, \'queuedCount\')))\n}\nif (currentBucket != \'\') {\n    series.add(finishBucket(currentBucket, tasks))\n}\nreturn {\n    interval: \'hour\',\n    metric: \'SUM_OF_TASK_HOURLY_SNAPSHOT_PEAKS\',\n    beginTime: beginTime,\n    endTime: endTime,\n    points: series\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/09.任务监控小时趋势.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "c562ecb2777d466f8ce04907409b70a7",\r\n  "script" : null,\r\n  "groupId" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "10.多表编组分页",\r\n  "createTime" : 1791112739532,\r\n  "updateTime" : 1791118050574,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/multi/page",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"pageNum\\":1,\\"pageSize\\":20,\\"keyword\\":\\"\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"list\\":[],\\"total\\":0}",\r\n  "description" : "只读当前会话租户下的多表任务编组与成员，逐表状态从已有单表接入任务实时读取；支持名称搜索和分页，不创建或运行NiFi流程。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：多表任务编组分页（POST /ods/task/multi/page）\n// 服务端分页后一次关联读取本页全部成员，按来源数据源角色范围过滤整组。\nimport tenantRuntime\nimport dataScope\nimport cn.hutool.core.util.NumberUtil\n\nvar text = value => value == null ? \'\' : (\'\' + value).trim()\n// 不同 JDBC 驱动可能把未加引号的别名保留原样、转小写或转大写。\nvar field = (row, name) => row == null ? null :\n    (row[name] != null ? row[name] :\n     (row[name.toLowerCase()] != null ? row[name.toLowerCase()] : row[name.toUpperCase()]))\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'当前租户无效\' }\nvar pageNum = text(body?.pageNum).matches(\'^[0-9]+$\') ? NumberUtil.parseInt(text(body.pageNum)) : 1\nvar pageSize = text(body?.pageSize).matches(\'^[0-9]+$\') ? NumberUtil.parseInt(text(body.pageSize)) : 20\nif (pageNum < 1 || pageNum > 100000) { pageNum = 1 }\nif (pageSize < 1 || pageSize > 20) { pageSize = 20 }\nvar keyword = text(body?.keyword)\nif (keyword.length() > 100) { exit 400, \'搜索词过长\' }\nvar likeKeyword = \'%\' + keyword + \'%\'\n\nvar scope = dataScope.dataSource()\nvar scopeMode = text(scope?.scope)\nvar scopeUserId = text(scope?.userId)\nvar scopeOrgIds = scope?.organizationIds == null ? [] : scope.organizationIds\nif (![\'ALL\', \'ORG\', \'OWNER\'].contains(scopeMode) || scopeUserId == \'\') { exit 403, \'无法确定当前数据范围\' }\n// SQL 片段只由服务端角色枚举决定；身份、部门和租户值均使用参数绑定。\nvar visibleSql = scopeMode == \'ALL\' ? \'1=1\' :\n    (scopeMode == \'OWNER\' ? \'d.created_by=#{scopeUserId}\' :\n     (scopeOrgIds.size() == 0 ? \'1=0\' :\n      \'d.org_id in <foreach collection="scopeOrgIds" item="orgId" open="(" close=")" separator=",">#{orgId}</foreach>\'))\n\n// 一组任一来源超出范围时隐藏整组，不返回部分成员造成信息泄露。\nvar groupSql = """\n    select g.tid as groupId, g.group_name as groupName, g.created_by as createdBy,\n           g.created_time as createdTime, g.updated_time as updatedTime\n      from data_access_multi_group_t g\n     where g.tenant_id=#{tenantId} and g.is_del=0\n       and (#{keyword}=\'\' or g.group_name like #{likeKeyword})\n       and not exists (\n           select 1 from data_access_multi_group_item_t m\n           left join db_table_t t on t.tid=m.source_table_id\n                and t.tenant_id=g.tenant_id and t.is_del=0\n           left join db_datasource_t d on d.tid=t.datasource_id\n                and d.tenant_id=g.tenant_id and d.is_del=0\n           where m.group_id=g.tid and m.tenant_id=g.tenant_id\n             and (t.tid is null or d.tid is null or not (${visibleSql}))\n       )\n     order by g.created_time desc, g.tid desc\n"""\nvar groupPage = db.page(groupSql, pageSize, (pageNum - 1) * pageSize)\nvar groupRows = groupPage?.list == null ? [] : groupPage.list\nvar groupIds = []\nvar itemMap = {}\nfor (group in groupRows) {\n    var id = text(field(group, \'groupId\'))\n    groupIds.add(id)\n    itemMap[id] = []\n}\nif (groupIds.size() > 0) {\n    var members = db.select("""\n        select m.tid as itemId, m.group_id as groupId, m.source_table_id as sourceTableId,\n               m.access_task_id as taskId, m.sort_no as sortNo,\n               t.table_name as sourceTableName, t.table_name_cn as sourceTableNameCn,\n               a.tid as availableTaskId, a.task_name as taskName, a.task_status as taskStatus,\n               a.pipeline_id as pipelineId, a.monitor_status as monitorStatus,\n               a.monitor_msg as monitorMessage, a.last_running as lastRunning,\n               a.end_running as endRunning\n          from data_access_multi_group_item_t m\n          join db_table_t t on t.tid=m.source_table_id\n               and t.tenant_id=#{tenantId} and t.is_del=0\n          join db_datasource_t d on d.tid=t.datasource_id\n               and d.tenant_id=#{tenantId} and d.is_del=0\n          left join data_access_agg_task_t a on a.tid=m.access_task_id\n               and a.source_table_id=m.source_table_id\n               and a.tenant_id=#{tenantId} and a.is_del=0\n         where m.tenant_id=#{tenantId}\n           and m.group_id in <foreach collection="groupIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n           and ${visibleSql}\n         order by m.group_id, m.sort_no, m.tid\n    """)\n    for (member in members) {\n        var id = text(field(member, \'groupId\'))\n        if (itemMap[id] != null) {\n            itemMap[id].add({\n                itemId: field(member, \'itemId\'),\n                sourceTableId: field(member, \'sourceTableId\'),\n                taskId: field(member, \'taskId\'),\n                sortNo: field(member, \'sortNo\'),\n                taskAvailable: text(field(member, \'availableTaskId\')) != \'\',\n                taskName: field(member, \'taskName\'),\n                taskStatus: field(member, \'taskStatus\'),\n                pipelineId: field(member, \'pipelineId\'),\n                monitorStatus: field(member, \'monitorStatus\'),\n                monitorMessage: field(member, \'monitorMessage\'),\n                lastRunning: field(member, \'lastRunning\'),\n                endRunning: field(member, \'endRunning\'),\n                sourceTableName: field(member, \'sourceTableName\'),\n                sourceTableNameCn: field(member, \'sourceTableNameCn\')\n            })\n        }\n    }\n}\nvar groups = []\nfor (group in groupRows) {\n    var id = text(field(group, \'groupId\'))\n    var creator = text(field(group, \'createdBy\'))\n    groups.add({groupId: id, groupName: field(group, \'groupName\'),\n        createdBy: creator, canManage: creator == scopeUserId,\n        createdTime: field(group, \'createdTime\'),\n        updatedTime: field(group, \'updatedTime\'), items: itemMap[id]})\n}\nreturn {list: groups, total: groupPage?.total == null ? 0 : groupPage.total,\n    pageNum: pageNum, pageSize: pageSize}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/02.接入任务/10.多表编组分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "c276687fa7cb4a0fada25b972ccda4b1",\r\n  "script" : null,\r\n  "groupId" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "11.保存多表编组",\r\n  "createTime" : 1791112840367,\r\n  "updateTime" : 1791118050698,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/multi/save",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"groupId\\":\\"32位UUID\\",\\"groupName\\":\\"案件多表接入\\",\\"taskIds\\":[\\"任务1\\",\\"任务2\\"]}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"success\\":true}",\r\n  "description" : "创建多表任务编组：事务验证当前租户现有单表任务及来源表，固定请求标识重复提交返回原编组。只建立关联，不部署或运行统一NiFi流程。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：创建多表任务编组（POST /ods/task/multi/save）\n// 单次预取 2–100 个单表任务、来源表及数据源，再在内存逐 ID 校验。\nimport tenantRuntime\nimport dataScope\nimport cn.dev33.satoken.stp.StpUtil\nimport java.util.UUID\nimport java.util.HashSet\nimport java.util.ArrayList\n\nvar text = value => value == null ? \'\' : (\'\' + value).trim()\nvar field = (row, name) => row == null ? null :\n    (row[name] != null ? row[name] :\n     (row[name.toLowerCase()] != null ? row[name.toLowerCase()] : row[name.toUpperCase()]))\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'当前租户无效\' }\nvar groupId = text(body?.groupId)\nvar groupName = text(body?.groupName)\nvar taskIds = body?.taskIds\nif (!groupId.matches(\'^[a-fA-F0-9]{32}$\')) { exit 400, \'编组请求标识无效\' }\nif (groupName == \'\' || groupName.length() > 200) { exit 400, \'编组名称须为1到200个字符\' }\nif (taskIds == null || taskIds.size() < 2 || taskIds.size() > 100) { exit 400, \'每个编组需包含2至100个单表任务\' }\nvar orderedIds = new ArrayList()\nvar seenIds = new HashSet()\nfor (rawId in taskIds) {\n    var taskId = text(rawId)\n    if (!taskId.matches(\'^[A-Za-z0-9_-]{1,32}$\') || !seenIds.add(taskId)) {\n        exit 400, \'单表任务标识无效或重复\'\n    }\n    orderedIds.add(taskId)\n}\nif (!StpUtil.isLogin()) { exit 401, \'登录已失效\' }\nvar actor = text(StpUtil.getLoginId())\nvar scope = dataScope.dataSource()\nvar scopeMode = text(scope?.scope)\nvar scopeUserId = text(scope?.userId)\nvar scopeOrgIds = scope?.organizationIds == null ? [] : scope.organizationIds\nif (![\'ALL\', \'ORG\', \'OWNER\'].contains(scopeMode) || scopeUserId != actor) { exit 403, \'无法确定当前数据范围\' }\nvar visibleSql = scopeMode == \'ALL\' ? \'1=1\' :\n    (scopeMode == \'OWNER\' ? \'d.created_by=#{scopeUserId}\' :\n     (scopeOrgIds.size() == 0 ? \'1=0\' :\n      \'d.org_id in <foreach collection="scopeOrgIds" item="orgId" open="(" close=")" separator=",">#{orgId}</foreach>\'))\n\nvar compareSaved = existing => {\n    if (text(existing.createdBy || existing.created_by || existing.CREATED_BY) != actor) { exit 403, \'无权使用此编组请求标识\' }\n    var isDeleted = existing.isDel == null ? (existing.is_del == null ? existing.IS_DEL : existing.is_del) : existing.isDel\n    if (isDeleted != 0) { exit 409, \'此编组请求已经删除，请重新创建\' }\n    var saved = db.table(\'data_access_multi_group_item_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'group_id\', groupId)\n        .orderBy(\'sort_no\', \'asc\').select()\n    if (text(existing.groupName || existing.group_name || existing.GROUP_NAME) != groupName || saved.size() != orderedIds.size()) {\n        exit 409, \'相同请求标识已用于其他编组内容\'\n    }\n    var index = 0\n    for (savedRow in saved) {\n        if (text(savedRow.accessTaskId || savedRow.access_task_id || savedRow.ACCESS_TASK_ID) != text(orderedIds[index])) {\n            exit 409, \'相同请求标识已用于其他编组成员\'\n        }\n        index++\n    }\n    return {groupId: groupId, created: false, tableCount: saved.size()}\n}\nvar precheckPassed = false\ntry {\nreturn db.transaction(() => {\n    // 关联查询限定当前租户并套用角色数据范围。缺失/越权 ID 必须使整批失败。\n    var taskRows = db.select("""\n        select a.tid as taskId, t.tid as sourceId\n          from data_access_agg_task_t a\n          join db_table_t t on t.tid=a.source_table_id\n               and t.tenant_id=#{tenantId} and t.is_del=0\n          join db_datasource_t d on d.tid=t.datasource_id\n               and d.tenant_id=#{tenantId} and d.is_del=0\n         where a.tenant_id=#{tenantId} and a.is_del=0\n           and a.tid in <foreach collection="orderedIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n           and ${visibleSql}\n    """)\n    if (taskRows.size() != orderedIds.size()) { exit 403, \'部分单表任务不存在或无权访问\' }\n    var taskSource = {}\n    for (task in taskRows) {\n        taskSource[text(field(task, \'taskId\'))] = text(field(task, \'sourceId\'))\n    }\n    var sources = new HashSet()\n    var rows = new ArrayList()\n    for (taskId in orderedIds) {\n        var sourceId = text(taskSource[text(taskId)])\n        if (sourceId == \'\' || !sources.add(sourceId)) { exit 400, \'来源表缺失或在编组中重复\' }\n        rows.add({taskId: taskId, sourceId: sourceId})\n    }\n    precheckPassed = true\n    var existing = db.table(\'data_access_multi_group_t\').where()\n        .eq(\'tid\', groupId).eq(\'tenant_id\', tenantId).selectOne()\n    if (existing != null) { return compareSaved(existing) }\n    db.table(\'data_access_multi_group_t\').primary(\'tid\').insert({\n        tid: groupId, tenant_id: tenantId, group_name: groupName,\n        created_by: actor, created_time: new Date(), updated_time: new Date(), is_del: 0\n    })\n    var order = 1\n    for (row in rows) {\n        db.table(\'data_access_multi_group_item_t\').primary(\'tid\').insert({\n            tid: UUID.randomUUID().toString().replace(\'-\', \'\'), tenant_id: tenantId,\n            group_id: groupId, source_table_id: row.sourceId,\n            access_task_id: row.taskId, sort_no: order,\n            created_time: new Date(), updated_time: new Date()\n        })\n        order++\n    }\n    return {groupId: groupId, created: true, tableCount: rows.size()}\n})\n} catch (error) {\n    // 同一请求键的并发提交可能都读到“尚不存在”，然后第二个在主键插入处失败。\n    // 必须在失败事务回滚后开启新读视图核对赢家，不能把主键冲突直接返给重试者。\n    if (!precheckPassed) { throw error }\n    var winner = db.table(\'data_access_multi_group_t\').where()\n        .eq(\'tid\', groupId).eq(\'tenant_id\', tenantId).selectOne()\n    if (winner == null) { throw error }\n    return compareSaved(winner)\n}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/02.接入任务/11.保存多表编组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "59ce9120d637482a8b63cdc643510727",\r\n  "script" : null,\r\n  "groupId" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "12.删除多表编组",\r\n  "createTime" : 1791112840406,\r\n  "updateTime" : 1791118144267,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/multi/delete",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"groupId\\":\\"32位UUID\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"success\\":true}",\r\n  "description" : "软删除当前租户的多表编组，原单表任务、NiFi画布和已有数据均保留；重复删除幂等。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：删除多表任务编组（POST /ods/task/multi/delete）\n// 只软删除编组；全部成员来源数据源仍须落在当前角色范围，不触碰单表任务或 NiFi。\nimport tenantRuntime\nimport dataScope\nimport cn.dev33.satoken.stp.StpUtil\n\nvar text = value => value == null ? \'\' : (\'\' + value).trim()\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'当前租户无效\' }\nif (!StpUtil.isLogin()) { exit 401, \'登录已失效\' }\nvar actor = text(StpUtil.getLoginId())\nvar groupId = text(body?.groupId)\nif (!groupId.matches(\'^[a-fA-F0-9]{32}$\')) { exit 400, \'编组标识无效\' }\nvar scope = dataScope.dataSource()\nvar scopeMode = text(scope?.scope)\nvar scopeUserId = text(scope?.userId)\nvar scopeOrgIds = scope?.organizationIds == null ? [] : scope.organizationIds\nif (![\'ALL\', \'ORG\', \'OWNER\'].contains(scopeMode) || scopeUserId != actor) { exit 403, \'无法确定当前数据范围\' }\nvar visibleSql = scopeMode == \'ALL\' ? \'1=1\' :\n    (scopeMode == \'OWNER\' ? \'d.created_by=#{scopeUserId}\' :\n     (scopeOrgIds.size() == 0 ? \'1=0\' :\n      \'d.org_id in <foreach collection="scopeOrgIds" item="orgId" open="(" close=")" separator=",">#{orgId}</foreach>\'))\n\nreturn db.transaction(() => {\n    // 一次关联反查验证整组所有来源，不在循环内逐成员 SELECT。\n    var group = db.selectOne("""\n        select g.tid as groupId, g.is_del as deleted\n          from data_access_multi_group_t g\n         where g.tid=#{groupId} and g.tenant_id=#{tenantId}\n           and g.created_by=#{actor}\n           and not exists (\n               select 1 from data_access_multi_group_item_t m\n               left join db_table_t t on t.tid=m.source_table_id\n                    and t.tenant_id=g.tenant_id and t.is_del=0\n               left join db_datasource_t d on d.tid=t.datasource_id\n                    and d.tenant_id=g.tenant_id and d.is_del=0\n               where m.group_id=g.tid and m.tenant_id=g.tenant_id\n                 and (t.tid is null or d.tid is null or not (${visibleSql}))\n           )\n    """)\n    if (group == null) { exit 403, \'编组不存在或当前无权删除\' }\n    var deleted = group.deleted == null ? group.DELETED : group.deleted\n    if (deleted == 0) {\n        db.table(\'data_access_multi_group_t\').where()\n            .eq(\'tid\', groupId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n            .update({is_del: 1, updated_time: new Date()})\n    }\n    return {groupId: groupId, deleted: true, memberTasksPreserved: true}\n})\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/02.接入任务/12.删除多表编组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "9dc102c8fc8845d2a48c161b442385b8",\r\n  "script" : null,\r\n  "groupId" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "13.补齐多表成员关联",\r\n  "createTime" : 1791112840450,\r\n  "updateTime" : 1791118144374,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/multi/relink",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"groupId\\":\\"32位UUID\\",\\"sourceTableId\\":\\"来源表ID\\",\\"taskId\\":\\"任务ID\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"success\\":true}",\r\n  "description" : "重试单表任务确保后，验证编组、来源表和新任务同属当前租户且匹配，幂等更新成员关联；不触及其他单表任务。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：重试后补齐多表编组成员关联\n// 路由：POST /ods/task/multi/relink\n// 当前来源表重新执行幂等单表确保接口后，只允许关联同租户同来源表的真实单表任务。\nimport tenantRuntime\nimport dataScope\nimport cn.dev33.satoken.stp.StpUtil\n\nvar tenantId = tenantRuntime.id()\nif (!StpUtil.isLogin()) { exit 401, \'登录已失效\' }\nvar actor = \'\' + StpUtil.getLoginId()\nvar text = (value) => value == null ? \'\' : (\'\' + value).trim()\nvar groupId = text(body?.groupId)\nvar sourceTableId = text(body?.sourceTableId)\nvar taskId = text(body?.taskId)\nif (!groupId.matches(\'^[a-fA-F0-9]{32}$\') || sourceTableId == \'\' || taskId == \'\') {\n    exit 400, \'编组、来源表和单表任务标识不能为空\'\n}\nvar scope = dataScope.dataSource()\nvar scopeMode = text(scope?.scope)\nvar scopeUserId = text(scope?.userId)\nvar scopeOrgIds = scope?.organizationIds == null ? [] : scope.organizationIds\nif (![\'ALL\', \'ORG\', \'OWNER\'].contains(scopeMode) || scopeUserId != actor) { exit 403, \'无法确定当前数据范围\' }\nvar visibleSql = scopeMode == \'ALL\' ? \'1=1\' :\n    (scopeMode == \'OWNER\' ? \'d.created_by=#{scopeUserId}\' :\n     (scopeOrgIds.size() == 0 ? \'1=0\' :\n      \'d.org_id in <foreach collection="scopeOrgIds" item="orgId" open="(" close=")" separator=",">#{orgId}</foreach>\'))\nreturn db.transaction(() => {\n    // 与编组分页相同：任一成员来源失效或失权，整组都不得再被修改。\n    var group = db.selectOne("""\n        select g.tid as groupId\n          from data_access_multi_group_t g\n         where g.tid=#{groupId} and g.tenant_id=#{tenantId}\n           and g.is_del=0 and g.created_by=#{actor}\n           and not exists (\n               select 1 from data_access_multi_group_item_t m\n               left join db_table_t t on t.tid=m.source_table_id\n                    and t.tenant_id=g.tenant_id and t.is_del=0\n               left join db_datasource_t d on d.tid=t.datasource_id\n                    and d.tenant_id=g.tenant_id and d.is_del=0\n               where m.group_id=g.tid and m.tenant_id=g.tenant_id\n                 and (t.tid is null or d.tid is null or not (${visibleSql}))\n           )\n    """)\n    if (group == null) { exit 403, \'编组不存在或当前无权修复\' }\n    var item = db.table(\'data_access_multi_group_item_t\').where()\n        .eq(\'group_id\', groupId).eq(\'source_table_id\', sourceTableId)\n        .eq(\'tenant_id\', tenantId).selectOne()\n    var task = db.table(\'data_access_agg_task_t\').where()\n        .eq(\'tid\', taskId).eq(\'source_table_id\', sourceTableId)\n        .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    var source = db.table(\'db_table_t\').where()\n        .eq(\'tid\', sourceTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (item == null || task == null || source == null) {\n        exit 400, \'编组成员或同来源表的单表任务不存在\'\n    }\n    if (text(item.accessTaskId || item.access_task_id) != taskId) {\n        db.table(\'data_access_multi_group_item_t\').where()\n            .eq(\'tid\', item.tid).eq(\'tenant_id\', tenantId).eq(\'group_id\', groupId)\n            .update({access_task_id: taskId, updated_time: new Date()})\n    }\n    return {groupId: groupId, sourceTableId: sourceTableId, taskId: taskId, linked: true}\n})\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/02.接入任务/13.补齐多表成员关联.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "c8754c53bb644104a178b88fbcebb7cd",\r\n  "script" : null,\r\n  "groupId" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "14.多表可选单表任务分页",\r\n  "createTime" : 1791118144463,\r\n  "updateTime" : 1791118144089,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/multi/candidates",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"pageNum\\":1,\\"pageSize\\":20,\\"keyword\\":\\"\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"list\\":[],\\"total\\":0}",\r\n  "description" : "分页查询当前会话租户及角色数据范围内可选的真实单表接入任务，供创建多表编组；最多每页50条，不新建任务或NiFi流程。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：多表编组可选单表任务分页（POST /ods/task/multi/candidates）\n// 仅展示当前租户、当前角色数据范围内已经存在且有来源表的真实单表任务。\nimport tenantRuntime\nimport dataScope\nimport cn.hutool.core.util.NumberUtil\n\nvar text = value => value == null ? \'\' : (\'\' + value).trim()\nvar field = (row, name) => row == null ? null :\n    (row[name] != null ? row[name] :\n     (row[name.toLowerCase()] != null ? row[name.toLowerCase()] : row[name.toUpperCase()]))\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') { exit 401, \'当前租户无效\' }\nvar pageNum = text(body?.pageNum).matches(\'^[0-9]+$\') ? NumberUtil.parseInt(text(body.pageNum)) : 1\nvar pageSize = text(body?.pageSize).matches(\'^[0-9]+$\') ? NumberUtil.parseInt(text(body.pageSize)) : 10\nif (pageNum < 1 || pageNum > 100000) { pageNum = 1 }\nif (pageSize < 1 || pageSize > 50) { pageSize = 10 }\nvar keyword = text(body?.keyword)\nif (keyword.length() > 100) { exit 400, \'搜索词过长\' }\nvar likeKeyword = \'%\' + keyword + \'%\'\n\nvar scope = dataScope.dataSource()\nvar scopeMode = text(scope?.scope)\nvar scopeUserId = text(scope?.userId)\nvar scopeOrgIds = scope?.organizationIds == null ? [] : scope.organizationIds\nif (![\'ALL\', \'ORG\', \'OWNER\'].contains(scopeMode) || scopeUserId == \'\') { exit 403, \'无法确定当前数据范围\' }\nvar visibleSql = scopeMode == \'ALL\' ? \'1=1\' :\n    (scopeMode == \'OWNER\' ? \'d.created_by=#{scopeUserId}\' :\n     (scopeOrgIds.size() == 0 ? \'1=0\' :\n      \'d.org_id in <foreach collection="scopeOrgIds" item="orgId" open="(" close=")" separator=",">#{orgId}</foreach>\'))\n\nvar result = db.page("""\n    select a.tid as taskId, a.task_name as taskName, a.task_status as taskStatus,\n           a.pipeline_id as pipelineId, t.tid as sourceTableId,\n           t.table_name as sourceTableName, t.table_name_cn as sourceTableNameCn,\n           d.db_name as datasourceName\n      from data_access_agg_task_t a\n      join db_table_t t on t.tid=a.source_table_id\n           and t.tenant_id=#{tenantId} and t.is_del=0\n      join db_datasource_t d on d.tid=t.datasource_id\n           and d.tenant_id=#{tenantId} and d.is_del=0\n     where a.tenant_id=#{tenantId} and a.is_del=0\n       and (#{keyword}=\'\' or a.task_name like #{likeKeyword}\n            or t.table_name like #{likeKeyword} or t.table_name_cn like #{likeKeyword})\n       and ${visibleSql}\n     order by a.updated_time desc, a.tid desc\n""", pageSize, (pageNum - 1) * pageSize)\nvar list = []\nfor (row in (result?.list == null ? [] : result.list)) {\n    list.add({taskId: field(row, \'taskId\'), taskName: field(row, \'taskName\'),\n        taskStatus: field(row, \'taskStatus\'), pipelineId: field(row, \'pipelineId\'),\n        sourceTableId: field(row, \'sourceTableId\'),\n        sourceTableName: field(row, \'sourceTableName\'),\n        sourceTableNameCn: field(row, \'sourceTableNameCn\'),\n        datasourceName: field(row, \'datasourceName\')})\n}\nreturn {list: list,\n    total: result?.total == null ? 0 : result.total,\n    pageNum: pageNum, pageSize: pageSize}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/02.接入任务/14.多表可选单表任务分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99c8dd7189af40939e5110b76bcd7160',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "99c8dd7189af40939e5110b76bcd7160",\r\n  "name" : "02.接入任务",\r\n  "type" : "api",\r\n  "parentId" : "1f4028f20aaa4f379b5e37a343b99fa9",\r\n  "path" : "/task",\r\n  "createTime" : 1781960050355,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4b2978ef33c74494a690fe709ef15f1f',NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cc82b6b0f5db45439f01f14f5e3309de',NULL,NULL,'{\n  "properties": {},\n  "id": "cc82b6b0f5db45439f01f14f5e3309de",\n  "groupId": "a6b70761965047169f1ce26f877ebac7",\n  "name": "01.登记预检",\n  "path": "/validate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"externalFlowId\\":\\"external-001\\",\\"pipelineId\\":\\"已有NiFi流程ID（可选）\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/task/registry/validate；只检查当前租户外部流程ID和已有NiFi流程绑定，不转换原海通本地Flow。",\n  "script": null\n}\n================================\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后登记流程\'\n}\nvar externalFlowId = body?.externalFlowId == null ? \'\' : (\'\' + body.externalFlowId).trim()\nvar pipelineId = body?.pipelineId == null ? \'\' : (\'\' + body.pipelineId).trim()\nif (!externalFlowId.matches(\'^[A-Za-z0-9._:-]{1,128}$\')) {\n    exit 400, \'外部流程ID只能包含字母、数字、点、下划线、冒号或连字符，最长128位\'\n}\nif (pipelineId != \'\' && !pipelineId.matches(\'^[A-Za-z0-9_-]{1,64}$\')) {\n    exit 400, \'NiFi流程ID无效\'\n}\nvar existing = db.table(\'nifi_pipeline_external_ref_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'external_flow_id\', externalFlowId).selectOne()\nvar assigned = pipelineId == \'\' ? null : db.table(\'nifi_pipeline_external_ref_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'pipeline_id\', pipelineId).selectOne()\nvar pipeline = pipelineId == \'\' ? null : db.table(\'nifi_pipeline_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'id\', pipelineId).eq(\'is_del\', 0).selectOne()\nvar field = (row, snake, camel) => {\n    if (row == null) { return null }\n    if (row[camel] != null) { return row[camel] }\n    if (row[snake] != null) { return row[snake] }\n    return row[snake.toUpperCase()]\n}\nreturn {\n    externalFlowId: externalFlowId,\n    exists: existing != null,\n    pipelineId: field(existing, \'pipeline_id\', \'pipelineId\'),\n    sameBinding: existing != null && pipelineId != \'\' && field(existing, \'pipeline_id\', \'pipelineId\') == pipelineId,\n    pipelineExists: pipeline != null,\n    pipelineAssignedElsewhere: assigned != null && field(assigned, \'external_flow_id\', \'externalFlowId\') != externalFlowId,\n    sourceFormat: \'CANVAS_DSL_V1\'\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/01.登记预检.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3e7384111e1c432484ea4f68ce080d67',NULL,NULL,'{\n  "properties": {},\n  "id": "3e7384111e1c432484ea4f68ce080d67",\n  "groupId": "a6b70761965047169f1ce26f877ebac7",\n  "name": "02.保存登记",\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"externalFlowId\\":\\"external-001\\",\\"pipelineId\\":\\"已保存NiFi流程ID\\",\\"sourceFormat\\":\\"CANVAS_DSL_V1\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/task/registry/save；将当前租户唯一外部ID绑定到已保存且版本为1的真实NiFi流程，重复请求幂等。",\n  "script": null\n}\n================================\nimport tenantRuntime\nimport cn.hutool.core.util.IdUtil\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后登记流程\'\n}\nvar externalFlowId = body?.externalFlowId == null ? \'\' : (\'\' + body.externalFlowId).trim()\nvar pipelineId = body?.pipelineId == null ? \'\' : (\'\' + body.pipelineId).trim()\nvar sourceFormat = body?.sourceFormat == null ? \'CANVAS_DSL_V1\' : (\'\' + body.sourceFormat).trim()\nif (!externalFlowId.matches(\'^[A-Za-z0-9._:-]{1,128}$\')) {\n    exit 400, \'外部流程ID只能包含字母、数字、点、下划线、冒号或连字符，最长128位\'\n}\nif (!pipelineId.matches(\'^[A-Za-z0-9_-]{1,64}$\')) {\n    exit 400, \'NiFi流程ID无效\'\n}\nif (sourceFormat != \'CANVAS_DSL_V1\') {\n    exit 400, \'只能登记NiFi Canvas DSL v1；原海通Flow JSON不能直接转换或部署\'\n}\nvar pipeline = db.table(\'nifi_pipeline_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'id\', pipelineId).eq(\'is_del\', 0).selectOne()\nif (pipeline == null) {\n    exit 404, \'NiFi流程不存在或无权访问\'\n}\nvar field = (row, snake, camel) => {\n    if (row == null) { return null }\n    if (row[camel] != null) { return row[camel] }\n    if (row[snake] != null) { return row[snake] }\n    return row[snake.toUpperCase()]\n}\nvar dslVersion = field(pipeline, \'dsl_version\', \'dslVersion\')\nvar dslHash = field(pipeline, \'dsl_hash\', \'dslHash\')\nif ((\'\' + dslVersion) != \'1\' || dslHash == null || (\'\' + dslHash).trim() == \'\') {\n    exit 409, \'NiFi流程尚未保存有效的Canvas DSL v1\'\n}\nvar existing = db.table(\'nifi_pipeline_external_ref_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'external_flow_id\', externalFlowId).selectOne()\nif (existing != null) {\n    if (field(existing, \'pipeline_id\', \'pipelineId\') != pipelineId) {\n        exit 409, \'此外部流程ID已绑定另一条NiFi流程\'\n    }\n    return { tid: field(existing, \'tid\', \'tid\'), externalFlowId: externalFlowId, pipelineId: pipelineId, created: false, sourceFormat: field(existing, \'source_format\', \'sourceFormat\') }\n}\nvar assigned = db.table(\'nifi_pipeline_external_ref_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'pipeline_id\', pipelineId).selectOne()\nif (assigned != null) {\n    exit 409, \'该NiFi流程已绑定另一外部流程ID\'\n}\nvar tid = IdUtil.getSnowflakeNextIdStr()\nvar nowTime = new Date()\ntry {\n    db.table(\'nifi_pipeline_external_ref_t\').primary(\'tid\').insert({\n        tid: tid,\n        tenant_id: tenantId,\n        external_flow_id: externalFlowId,\n        pipeline_id: pipelineId,\n        source_format: sourceFormat,\n        dsl_hash_at_import: dslHash,\n        created_time: nowTime,\n        updated_time: nowTime\n    })\n} catch (e) {\n    // 数据库唯一键是并发登记的最终裁决：相同绑定按幂等返回，异绑定明确冲突。\n    var concurrent = db.table(\'nifi_pipeline_external_ref_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'external_flow_id\', externalFlowId).selectOne()\n    if (concurrent != null) {\n        if (field(concurrent, \'pipeline_id\', \'pipelineId\') == pipelineId) {\n            return { tid: field(concurrent, \'tid\', \'tid\'), externalFlowId: externalFlowId, pipelineId: pipelineId, created: false, sourceFormat: field(concurrent, \'source_format\', \'sourceFormat\') }\n        }\n        exit 409, \'此外部流程ID已被并发登记到另一条NiFi流程\'\n    }\n    var otherExternal = db.table(\'nifi_pipeline_external_ref_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'pipeline_id\', pipelineId).selectOne()\n    if (otherExternal != null) {\n        exit 409, \'该NiFi流程已被并发登记到另一外部流程ID\'\n    }\n    throw e\n}\nreturn { tid: tid, externalFlowId: externalFlowId, pipelineId: pipelineId, created: true, sourceFormat: sourceFormat }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/02.保存登记.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('94c9cc1afcd742a6a2486fce18adaa77',NULL,NULL,'{\n  "properties": {},\n  "id": "94c9cc1afcd742a6a2486fce18adaa77",\n  "groupId": "a6b70761965047169f1ce26f877ebac7",\n  "name": "03.登记记录分页",\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"keyword\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/task/registry/page；当前租户真实NiFi流程的外部ID登记历史，不包含本地IndexedDB演示登记。",\n  "script": null\n}\n================================\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后查看登记记录\'\n}\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\npageNum = pageNum < 1 ? 1 : pageNum\npageSize = pageSize < 1 ? 20 : (pageSize > 100 ? 100 : pageSize)\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nif (keyword.length() > 100) {\n    exit 400, \'搜索词过长\'\n}\nvar keywordPattern = \'%\' + keyword + \'%\'\nvar result = db.page("""\n    SELECT r.tid,\n           r.external_flow_id AS externalFlowId,\n           r.pipeline_id AS pipelineId,\n           p.name AS pipelineName,\n           p.status AS pipelineStatus,\n           p.nifi_process_group_id AS processGroupId,\n           r.source_format AS sourceFormat,\n           r.created_time AS createdTime\n      FROM nifi_pipeline_external_ref_t r\n      JOIN nifi_pipeline_t p ON p.id = r.pipeline_id AND p.tenant_id = r.tenant_id AND p.is_del = 0\n     WHERE r.tenant_id = #{tenantId}\n       AND (#{keyword} = \'\' OR r.external_flow_id LIKE #{keywordPattern}\n            OR p.name LIKE #{keywordPattern})\n     ORDER BY r.created_time DESC, r.tid DESC\n""", pageSize, (pageNum - 1) * pageSize)\nvar items = []\nvar value = (row, key) => {\n    if (row[key] != null) { return row[key] }\n    if (row[key.toLowerCase()] != null) { return row[key.toLowerCase()] }\n    return row[key.toUpperCase()]\n}\nfor (row in (result.list == null ? [] : result.list)) {\n    items.add({\n        tid: value(row, \'tid\'),\n        externalFlowId: value(row, \'externalFlowId\'),\n        pipelineId: value(row, \'pipelineId\'),\n        pipelineName: value(row, \'pipelineName\'),\n        pipelineStatus: value(row, \'pipelineStatus\'),\n        processGroupId: value(row, \'processGroupId\'),\n        sourceFormat: value(row, \'sourceFormat\'),\n        createdTime: value(row, \'createdTime\')\n    })\n}\nreturn { pageNum: pageNum, pageSize: pageSize, total: result.total, list: items }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/03.登记记录分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('28d9a96c33d34c84a628add5d44d7b8e',NULL,NULL,'{\n  "properties": {},\n  "id": "28d9a96c33d34c84a628add5d44d7b8e",\n  "groupId": "a6b70761965047169f1ce26f877ebac7",\n  "name": "04.NiFi流程选项分页",\n  "path": "/pipeline-options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"keyword\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/task/registry/pipeline-options；按当前租户分页搜索可登记的 NiFi Canvas DSL v1 流程，只返回选择框所需元数据。",\n  "script": null\n}\n================================\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后选择NiFi流程\'\n}\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nif (pageNum < 1 || pageNum > 1000 || pageSize < 1 || pageSize > 100) {\n    exit 400, \'页码或每页条数超出限制，请使用搜索缩小范围\'\n}\nif (keyword.length() > 100) {\n    exit 400, \'搜索词不能超过100字\'\n}\nvar keywordPattern = \'%\' + keyword + \'%\'\n// 单次 db.page 完成 count 与有界当前页查询；没有逐流程读取或 DSL 大字段反序列化。\n// NiFi 流程当前的数据范围是租户级；租户 ID 仅从服务端会话获得，忽略任何前端 tenantId。\nvar result = db.page("""\n    SELECT id,\n           name,\n           status,\n           nifi_process_group_id AS processGroupId\n      FROM nifi_pipeline_t\n     WHERE tenant_id = #{tenantId}\n       AND is_del = 0\n       AND dsl_version = 1\n       AND dsl_hash IS NOT NULL\n       AND dsl_hash <> \'\'\n       AND (#{keyword} = \'\' OR name LIKE #{keywordPattern} OR id LIKE #{keywordPattern})\n     ORDER BY updated_at DESC, id DESC\n""", pageSize, (pageNum - 1) * pageSize)\nvar value = (row, key) => {\n    if (row[key] != null) { return row[key] }\n    if (row[key.toLowerCase()] != null) { return row[key.toLowerCase()] }\n    return row[key.toUpperCase()]\n}\nvar items = []\nfor (row in (result.list == null ? [] : result.list)) {\n    items.add({\n        id: value(row, \'id\'),\n        name: value(row, \'name\'),\n        status: value(row, \'status\'),\n        processGroupId: value(row, \'processGroupId\')\n    })\n}\nreturn { pageNum: pageNum, pageSize: pageSize, total: result.total, list: items }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/04.NiFi流程选项分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a6b70761965047169f1ce26f877ebac7',NULL,NULL,'{\n  "properties": {},\n  "id": "a6b70761965047169f1ce26f877ebac7",\n  "name": "外部流程登记",\n  "type": "api",\n  "parentId": "99c8dd7189af40939e5110b76bcd7160",\n  "path": "/registry",\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.接入任务/外部流程登记/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e3320ec899a24426adf5f77e2dab36f9',NULL,NULL,'{\n  "properties": {},\n  "id": "e3320ec899a24426adf5f77e2dab36f9",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "02.数据接入物化建表",\n  "createTime": 1782955344712,\n  "updateTime": 1790843736643,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/createTapleApply",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"015c09572d174e89b9bea9c765ef72df\\",\\n  \\"propList\\": {\\"dbId\\":\\"62d25cc8bf1344d6b9f41fed23af4eaf\\",\\"tableName\\":\\"police_reexplore_new_case_clue_TARGET\\",\\"tableNameCn\\":\\"公安重新探查新增线索表\\"},\\n  \\"tableItems\\": []\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"tid\\": \\"17fe19f8f69849f88a34352550039ee3\\",\\n  \\"targetTableId\\": \\"17fe19f8f69849f88a34352550039ee3\\",\\n  \\"catalogId\\": \\"faae1bc3ebaa4611aded5ed4a52d6a03\\",\\n  \\"sourceTableId\\": \\"015c09572d174e89b9bea9c765ef72df\\",\\n  \\"physicalTableReused\\": false\\n}",\n  "description": "数据接入物化建表（POST /ods/createTapleApply）。写接口；接收来源表 ID 或旧目录 ID，幂等创建或复用目标库同名物理表，写入 db_table_t/db_table_column_t，自动生成或更新代表目标表的数据目录 da_asset_t/da_prop_t，并同步 ES。用于数据接入-创建任务链路中的来源表=>目标表(目录)物化步骤；使用请求参数 tid、sourceTableId、tableId、sourceCatalogId、catalogId、id、propList、tableItems。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据接入物化建表\n// 路由：POST /ods/createTapleApply\n// 业务说明：数据接入物化建表（POST /ods/createTapleApply）。写接口；接收来源表 ID 或旧目录 ID，幂等创建或复用目标库同名物理表，写入 db_table_t/db_table_column_t，自动生成或更新代表目标表的数据目录 da_asset_t/da_prop_t，并同步 ES。用于数据接入-创建任务链路中的来源表=>目标表(目录)物化步骤；使用请求参数 tid、sourceTableId、tableId、sourceCatalogId、catalogId、id、propList、tableItems。\nimport tenantRuntime\n/*\n * 物化建表并自动补目录。\n *\n * 最新接入链路：\n * 来源表（右侧列表点击的 db_table_t.tid）=> 字段映射 => 目标表（物化到目标库）\n * 目标表会自动生成/更新一条目录资产，目录属性同时保存 sourceTableId 与 targetTableId，\n * 以便继续复用原来的目录/NiFi 模板逻辑。\n */\nimport cn.hutool.core.util.IdUtil\nimport jsons\nimport metadataAsset\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport \'@post:/dst/database/metadata/getCreateTableDDL\' as getCreateTableDDL\nimport \'@post:/dst/database/metadata/createTable\' as createTable\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]).trim() != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar upsertCatalogProp = (catalogId, name, value, now) => {\n    var old = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', catalogId)\n        .eq(\'prop_name\', name)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (old == null) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({\n            tid: IdUtil.getSnowflakeNextIdStr(),\n            parent_id: catalogId,\n            prop_name: name,\n            prop_value: value,\n            prop_type: \'0\',\n            data_type: \'catalog\',\n            is_del: 0,\n            created_time: now,\n            updated_time: now\n        })\n    } else {\n        db.table(\'da_prop_t\').where()\n            .eq(\'tid\', old.tid)\n        .update({ prop_value: value, updated_time: now })\n    }\n}\n// ODS ingestion timestamps must use the target database\'s native temporal type.\n// OceanBase explicitly uses DATE; Oracle/DM share the same date-time semantics,\n// PostgreSQL-like engines and Hive use TIMESTAMP, and SQL Server uses DATETIME2.\nvar materializationTimeType = (dbType) => {\n    var code = text(dbType).trim().toLowerCase()\n    if (code.indexOf(\'oceanbase\') >= 0 || code == \'oracle\' || code == \'dameng\' || code == \'dm\') {\n        return \'date\'\n    }\n    if (code == \'postgresql\' || code == \'postgres\' || code == \'kingbase\' || code == \'kingbase8\'\n        || code == \'gaussdb\' || code == \'opengauss\' || code == \'gauss\'\n        || code == \'vertica\' || code == \'hetu\' || code == \'trino\' || code == \'presto\'\n        || code == \'hive\') {\n        return \'timestamp\'\n    }\n    if (code == \'sqlserver\') {\n        return \'datetime2\'\n    }\n    return \'datetime\'\n}\nvar odsSystemColumns = (dbType) => {\n    var timeType = materializationTimeType(dbType)\n    return [\n    {\n        columnName: \'ODS_UUID\',\n        columnComment: \'ODS主键\',\n        dataType: \'varchar\',\n        columnType: \'varchar\',\n        length: 32,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 1,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 1,\n        isUnique: 1,\n        odsSystemColumn: true\n    },\n    {\n        columnName: \'ODS_RKSJ\',\n        columnComment: \'ODS入库时间\',\n        dataType: timeType,\n        columnType: timeType,\n        length: 0,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 0,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 0,\n        isUnique: 0,\n        odsSystemColumn: true\n    },\n    {\n        columnName: \'ODS_GXSJ\',\n        columnComment: \'ODS更新时间\',\n        dataType: timeType,\n        columnType: timeType,\n        length: 0,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 0,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 0,\n        isUnique: 0,\n        odsSystemColumn: true\n    }\n    ]\n}\nvar ensureOdsSystemColumns = (items, dbType) => {\n    var normalized = []\n    var hasBusinessPrimaryKey = false\n    for (item in (items == null ? [] : items)) {\n        if (blank(item.columnName)) {\n            continue\n        }\n        var key = text(item.columnName).toLowerCase()\n        if (key == \'ods_uuid\' || key == \'ods_rksj\' || key == \'ods_gxsj\') {\n            continue\n        }\n        // Preserve a source business primary key. ODS_UUID is an ingestion id and\n        // must not replace it when the target needs to support MERGE/UPSERT.\n        var primaryKeyValue = text(item.primaryKey).trim().toLowerCase()\n        hasBusinessPrimaryKey = hasBusinessPrimaryKey || primaryKeyValue == \'1\' || primaryKeyValue == \'true\'\n        normalized.add(item)\n    }\n    for (fixed in odsSystemColumns(dbType)) {\n        if (text(fixed.columnName).toUpperCase() == \'ODS_UUID\') {\n            fixed.primaryKey = hasBusinessPrimaryKey ? 0 : 1\n            fixed.indexed = hasBusinessPrimaryKey ? 0 : 1\n            fixed.isUnique = hasBusinessPrimaryKey ? 0 : 1\n        }\n        fixed.ordinalPosition = normalized.size()\n        normalized.add(fixed)\n    }\n    return normalized\n}\nvar safeIdentifier = (value) => text(value).trim().matches(\'^[A-Za-z_][A-Za-z0-9_$]*$\')\nvar parseGovernanceConfig = (value) => {\n    if (value == null || blank(value)) {\n        return {}\n    }\n    try {\n        return value instanceof Map ? value : jsons.toJSONObject(text(value))\n    } catch (e) {\n        return {}\n    }\n}\n// New registrations keep the snapshot on db_table_t; historical catalog saves\n// keep it in da_prop_t and link the catalog through sourceTableId.  Materialize\n// requests must accept both formats so existing dictionary registrations work.\nvar configHasFields = (config) => config != null && config.fields != null && config.fields.size() > 0\nvar governanceConfigFromProperties = (properties) => {\n    var fallback = {}\n    for (property in (properties == null ? [] : properties)) {\n        var propertyName = text(first(property, [\'propName\', \'prop_name\'])).trim().toLowerCase()\n        if (propertyName != \'fieldgovernanceconfig\' && propertyName != \'field_governance_config\'\n            && propertyName != \'fieldgovernancecfg\') { continue }\n        var candidate = parseGovernanceConfig(first(property, [\'propValue\', \'prop_value\']))\n        if (configHasFields(candidate)) { return candidate }\n        fallback = candidate\n    }\n    return fallback\n}\nvar governanceConfigOf = (table) => {\n    var persisted = parseGovernanceConfig(first(table, [\n        \'fieldGovernanceConfig\', \'field_governance_config\', \'fieldGovernanceCfg\'\n    ]))\n    if (configHasFields(persisted)) { return persisted }\n    var tableId = text(first(table, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(tableId)) { return persisted }\n    var direct = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', tableId).eq(\'is_del\', 0).select())\n    if (configHasFields(direct)) { return direct }\n    var sourceLinks = db.table(\'da_prop_t\').where()\n        .eq(\'prop_name\', \'sourceTableId\').eq(\'prop_value\', tableId).eq(\'is_del\', 0).select()\n    for (link in sourceLinks) {\n        var catalogId = text(first(link, [\'parentId\', \'parent_id\'])).trim()\n        if (blank(catalogId)) { continue }\n        var catalogConfig = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n            .eq(\'parent_id\', catalogId).eq(\'is_del\', 0).select())\n        if (configHasFields(catalogConfig)) { return catalogConfig }\n    }\n    return configHasFields(direct) ? direct : persisted\n}\n// A mandatory-standard relation is an enumerated code alignment.  It has no\n// dictionary table.  The materialization UI may suggest a sibling <code>_cn\n// field, but its actual output column is persisted as an explicit binding\n// below and is never inferred from this naming convention at runtime.\nvar mandatoryStandardMappings = (relation) => {\n    var result = []\n    if (relation == null) {\n        return result\n    }\n    var forceEnabled = text(relation.forceStandardEnabled).trim().toLowerCase()\n    var sourceType = text(relation.sourceType).trim().toLowerCase()\n    var mode = text(relation.mode).trim().toLowerCase()\n    // A small fixed dictionary may be persisted as sourceType/mode=enum.\n    // It uses the same deterministic code-to-label mapping as a mandatory\n    // standard and must retain its output binding during materialization.\n    if (!(forceEnabled == \'true\' || forceEnabled == \'1\' || forceEnabled == \'yes\'\n        || sourceType == \'standard\' || mode == \'standard\'\n        || sourceType == \'enum\' || mode == \'enum\')) {\n        return result\n    }\n    var values = relation.forceStandardValueMappings == null ? [] : relation.forceStandardValueMappings\n    if (values.size() == 0) { values = relation.enumItems == null ? [] : relation.enumItems }\n    var seen = {}\n    for (value in values) {\n        var code = text(first(value, [\'sourceCode\', \'sourceValue\', \'value\', \'code\'])).trim()\n        var label = text(first(value, [\'standardLabel\', \'label\', \'sourceLabel\', \'name\'])).trim()\n        if (!blank(code) && !blank(label) && seen[code] == null) {\n            result.add({ code: code, label: label })\n            seen[code] = true\n        }\n    }\n    return result\n}\n// Production may persist a checked dictionary association only on the source\n// column. Resolve that durable registration into a relation before writing the\n// target\'s field-transform bindings; the target must not depend on optional\n// source relation JSON being complete.\nvar registeredDictionaryRelations = (sourceTable) => {\n    var result = []\n    var sourceTableId = text(first(sourceTable, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(sourceTableId)) { return result }\n    var sourceColumns = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', sourceTableId).eq(\'is_del\', 0).select()\n    for (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n        var sourceName = text(first(sourceColumn, [\'columnName\', \'column_name\'])).trim()\n        var enabled = text(first(sourceColumn, [\'enableCodeTable\', \'enable_code_table\', \'isDict\', \'is_dict\'])).trim().toLowerCase()\n        var dictionaryTableId = text(first(sourceColumn, [\'codeTableId\', \'code_table_id\', \'dictId\', \'dict_id\'])).trim()\n        if (blank(sourceName) || (enabled != \'1\' && enabled != \'true\' && enabled != \'yes\' && blank(dictionaryTableId))) {\n            continue\n        }\n        var dictionaryTable = blank(dictionaryTableId) ? null : db.table(\'db_table_t\').where()\n            .eq(\'tid\', dictionaryTableId).eq(\'is_del\', 0).selectOne()\n        if (dictionaryTable == null) { continue }\n        var dictionaryConfig = governanceConfigOf(dictionaryTable)\n        var profile = dictionaryConfig.dictionaryProfile\n        if (profile == null && dictionaryConfig.dictionaryProfiles != null && dictionaryConfig.dictionaryProfiles.size() > 0) {\n            profile = dictionaryConfig.dictionaryProfiles[0]\n        }\n        if (profile == null && dictionaryConfig.dictionaryCategories != null && dictionaryConfig.dictionaryCategories.size() > 0) {\n            profile = dictionaryConfig.dictionaryCategories[0]\n        }\n        var keyField = text(first(profile, [\'codeField\', \'code_field\', \'dictionaryKeyField\', \'dictionary_key_field\'])).trim()\n        var labelField = text(first(profile, [\'labelField\', \'label_field\', \'nameField\', \'name_field\', \'dictionaryLabelField\', \'dictionary_label_field\'])).trim()\n        for (dictionaryField in (dictionaryConfig.fields == null ? [] : dictionaryConfig.fields)) {\n            var fieldName = text(first(dictionaryField, [\'columnName\', \'column_name\', \'fieldName\', \'field_name\'])).trim()\n            var role = text(first(dictionaryField, [\'dictionaryRole\', \'dictionary_role\'])).trim().toLowerCase()\n            if (blank(keyField) && role == \'code\') { keyField = fieldName }\n            if (blank(labelField) && role == \'label\') { labelField = fieldName }\n        }\n        var dictionaryColumns = db.table(\'db_table_column_t\').where()\n            .eq(\'table_id\', dictionaryTableId).eq(\'is_del\', 0).select()\n        for (dictionaryColumn in (dictionaryColumns == null ? [] : dictionaryColumns)) {\n            var columnName = text(first(dictionaryColumn, [\'columnName\', \'column_name\'])).trim()\n            var normalizedName = columnName.toLowerCase()\n            if (blank(keyField) && (text(first(dictionaryColumn, [\'primaryKey\', \'primary_key\'])).trim() == \'1\'\n                || text(first(dictionaryColumn, [\'isUnique\', \'is_unique\'])).trim() == \'1\'\n                || normalizedName.indexOf(\'code\') >= 0)) {\n                keyField = columnName\n            }\n            if (blank(labelField) && (normalizedName == \'name\' || normalizedName == \'label\'\n                || normalizedName.endsWith(\'_name\') || normalizedName.endsWith(\'_label\'))) {\n                labelField = columnName\n            }\n        }\n        var dictionaryName = text(first(dictionaryTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])).trim()\n        if (safeIdentifier(sourceName) && safeIdentifier(dictionaryName)\n            && safeIdentifier(keyField) && safeIdentifier(labelField)) {\n            result.add({\n                sourceName: sourceName,\n                relationKind: \'DICTIONARY\',\n                dictionaryTable: dictionaryName,\n                dictionaryTableId: dictionaryTableId,\n                dictionaryKeyField: keyField,\n                dictionaryLabelField: labelField,\n                conditions: []\n            })\n        }\n    }\n    return result\n}\n// Dictionary relations are stored with the Step 4 field-governance snapshot.\n// Only registered business/log fields carry registrationSavedPhase=business.\nvar dictionaryRelations = (sourceTable) => {\n    var config = governanceConfigOf(sourceTable)\n    var result = {}\n    for (field in (config.fields == null ? [] : config.fields)) {\n        var relation = first(field, [\'dictionaryRelation\', \'dictionary_relation\', \'dictionaryConfig\', \'dictionary_config\'])\n        var sourceName = text(first(field, [\'columnName\', \'column_name\', \'fieldName\', \'field_name\'])).trim()\n        var sourceType = text(relation == null ? \'\' : relation.sourceType).trim().toLowerCase()\n        var dictionaryTable = text(relation == null ? \'\' : first(relation, [\'dictionaryTable\', \'dictionary_table\', \'dictTable\', \'dict_table\'])).trim()\n        var keyField = text(relation == null ? \'\' : first(relation, [\'dictionaryKeyField\', \'dictionary_key_field\', \'keyField\', \'key_field\', \'codeField\', \'code_field\'])).trim()\n        var labelField = text(relation == null ? \'\' : first(relation, [\'dictionaryLabelField\', \'dictionary_label_field\', \'labelField\', \'label_field\', \'nameField\', \'name_field\'])).trim()\n        var standardValues = mandatoryStandardMappings(relation)\n        if (relation != null && text(relation.enabled).toLowerCase() != \'false\'\n            && safeIdentifier(sourceName) && standardValues.size() > 0) {\n            result[sourceName.toLowerCase()] = {\n                sourceName: sourceName,\n                relationKind: \'MANDATORY_STANDARD\',\n                standardValues: standardValues,\n                multiValue: text(relation.multiValue).toLowerCase() == \'true\',\n                multiValueSeparator: blank(relation.multiValueSeparator) ? \',\' : text(relation.multiValueSeparator)\n            }\n        } else if (relation != null && text(relation.enabled).toLowerCase() != \'false\' && sourceType != \'enum\'\n            && safeIdentifier(sourceName) && safeIdentifier(dictionaryTable)\n            && safeIdentifier(keyField) && safeIdentifier(labelField)) {\n            result[sourceName.toLowerCase()] = {\n                sourceName: sourceName,\n                relationKind: \'DICTIONARY\',\n                dictionaryTable: dictionaryTable,\n                dictionaryKeyField: keyField,\n                dictionaryLabelField: labelField,\n                multiValue: text(relation.multiValue).toLowerCase() == \'true\',\n                multiValueSeparator: blank(relation.multiValueSeparator) ? \',\' : text(relation.multiValueSeparator)\n            }\n        }\n    }\n    // Explicit source rules retain their category conditions. Column-level\n    // dictionary bindings fill only relations missing from older snapshots.\n    for (registeredRelation in registeredDictionaryRelations(sourceTable)) {\n        var key = registeredRelation.sourceName.toLowerCase()\n        if (result[key] == null) {\n            result[key] = registeredRelation\n        }\n    }\n    return result\n}\nvar appendDictionaryTranslationColumns = (items, sourceTable) => {\n    var relations = dictionaryRelations(sourceTable)\n    var names = {}\n    for (item in items) {\n        names[text(item.columnName).toLowerCase()] = true\n    }\n    var result = []\n    for (item in items) {\n        result.add(item)\n        var sourceName = text(item.columnName).trim()\n        var relation = relations[sourceName.toLowerCase()]\n        var translationName = sourceName + \'_cn\'\n        if (relation != null && names[translationName.toLowerCase()] == null) {\n            result.add({\n                columnName: translationName,\n                columnComment: text(item.columnComment).trim() + \'翻译\',\n                dataType: \'varchar\',\n                columnType: \'varchar(255)\',\n                length: 255,\n                precisionLength: 0,\n                scale: 0,\n                primaryKey: 0,\n                nullable: 1,\n                defaultValue: null,\n                ordinalPosition: result.size(),\n                autoIncrement: 0,\n                indexed: 0,\n                isUnique: 0,\n                dictionaryTranslationField: true,\n                dictionarySourceField: sourceName\n            })\n            names[translationName.toLowerCase()] = true\n        }\n    }\n    return result\n}\n\n// A target table owns the output-side association of its transformed fields.\n// The source table\'s fieldGovernanceConfig owns the rule definition itself.\n// Keeping the binding on the target makes one source safely materializable to\n// multiple targets, even when each target uses a different output field name.\nvar buildFieldTransformBindings = (sourceTable, sourceColumns, targetTableId, tableItems, columns) => {\n    var relations = dictionaryRelations(sourceTable)\n    var sourceByName = {}\n    for (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n        sourceByName[text(sourceColumn.columnName).toLowerCase()] = sourceColumn\n    }\n    var bindings = []\n    for (index, item in (tableItems == null ? [] : tableItems)) {\n        var targetColumn = columns == null ? null : columns[index]\n        var sourceName = text(item.dictionarySourceField).trim()\n        var relation = relations[sourceName.toLowerCase()]\n        var sourceColumn = sourceByName[sourceName.toLowerCase()]\n        if (targetColumn == null || relation == null || sourceColumn == null || blank(item.columnName)) {\n            continue\n        }\n        bindings.add({\n            bindingId: targetTableId + \':\' + text(targetColumn.tid),\n            sourceTableId: text(sourceTable.tid),\n            sourceColumnId: text(sourceColumn.tid),\n            sourceField: relation.sourceName,\n            targetTableId: targetTableId,\n            targetColumnId: text(targetColumn.tid),\n            targetField: text(item.columnName).trim(),\n            ruleType: relation.relationKind,\n            governanceField: relation.sourceName,\n            enabled: true,\n            origin: \'materialization\'\n        })\n    }\n    return bindings\n}\n\nvar inputId = text(body?.tid || body?.sourceTableId || body?.tableId || body?.sourceCatalogId || body?.catalogId || body?.id).trim()\nvar propList = body?.propList\nvar tableItems = body?.tableItems\n// 租户只来自当前认证请求的 TenantContext，不能从 principal、请求体或历史资产推断。\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再提交物化建表\'\n}\nif (blank(inputId)) {\n    exit 400, \'tid不能为空\'\n}\nif (propList == null) {\n    exit 400, \'propList不能为空\'\n}\nif (blank(propList.dbId)) {\n    exit 400, \'propList.dbId不能为空\'\n}\nif (blank(propList.tableName)) {\n    exit 400, \'propList.tableName不能为空\'\n}\npropList.tableName = text(propList.tableName).trim()\nif (tableItems == null || tableItems.size() == 0) {\n    exit 400, \'tableItems不能为空\'\n}\n\n// 兼容旧入口：如果 tid 是目录，则读取目录的来源表；否则 tid 就是来源表。\nvar catalogId = \'\'\nvar sourceTableId = \'\'\nvar inputCatalog = null\ntry {\n    inputCatalog = esCommonService.getDocument(\'dataassets\', inputId)\n} catch (e) {\n    // ES 只作为目录快速判断；失败时继续使用 MySQL 元数据兜底。\n    inputCatalog = null\n}\nif (inputCatalog != null && text(inputCatalog.assetType) == \'catalog\') {\n    catalogId = inputId\n    sourceTableId = text(inputCatalog.sourceTableId)\n}\nif (blank(sourceTableId)) {\n    var sourceProp = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', inputId)\n        .eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (sourceProp != null) {\n        catalogId = inputId\n        sourceTableId = text(sourceProp.propValue)\n    }\n}\nif (blank(sourceTableId)) {\n    sourceTableId = inputId\n}\n\nvar sourceTable = db.table(\'db_table_t\').where()\n    .eq(\'tid\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (sourceTable == null) {\n    exit 404, \'来源表不存在\'\n}\ntableItems = appendDictionaryTranslationColumns(tableItems, sourceTable)\n\nvar sourceDatasource = db.table(\'db_datasource_t\').where()\n    .eq(\'tid\', sourceTable.datasourceId)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nvar targetDatasource = db.table(\'db_datasource_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'tid\', propList.dbId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (targetDatasource == null) {\n    exit 404, \'目标数据源不存在\'\n}\nif (targetDatasource.showConnect == 0) {\n    exit 400, \'目标数据源未提供连接信息\'\n}\n// The submitted rows are editable client data, so normalize the two protected\n// ODS time columns again from the authoritative target datasource before DDL\n// generation and metadata persistence.\ntableItems = ensureOdsSystemColumns(tableItems, targetDatasource.dbType)\n// Keep the submit boundary aligned with the target datasource selector. In addition\n// to completed registrations, a datasource explicitly bound to a current-tenant ODS\n// domain is a governed materialization target and must not be rejected merely\n// because it is managed as a warehouse target rather than a normal registered source.\nvar targetAssetStatus = text(first(targetDatasource, [\'assetStatus\', \'asset_status\']))\nvar targetRegistered = targetAssetStatus == \'2\'\nvar dataSourceTypeRoot = db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'dict_code\', \'dataSourceType\')\n    .eq(\'parent_id\', \'0\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nvar odsNode = dataSourceTypeRoot == null ? null : db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'parent_id\', dataSourceTypeRoot.tid)\n    .eq(\'dict_code\', \'ods\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nvar targetOdsDomainBound = false\nif (odsNode != null) {\n    var odsDomains = db.table(\'sym_dict_t\').where()\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'parent_id\', odsNode.tid)\n        .eq(\'is_del\', 0)\n        .select()\n    var odsDomainIds = []\n    for (odsDomain in (odsDomains == null ? [] : odsDomains)) {\n        odsDomainIds.add(text(odsDomain.tid))\n    }\n    if (odsDomainIds.size() > 0) {\n        var odsTargetBinding = db.table(\'dwm_center_layer_source_t\').where()\n            .eq(\'tenant_id\', tenantId)\n            .eq(\'target_type\', \'domain\')\n            .in(\'target_id\', odsDomainIds)\n            .eq(\'datasource_id\', propList.dbId)\n            .eq(\'is_del\', 0)\n            .selectOne()\n        targetOdsDomainBound = odsTargetBinding != null\n    }\n}\nif (!targetRegistered && !targetOdsDomainBound) {\n    exit 400, \'目标数据源未完成登记且未配置为贴源层 ODS 分域的数据源，不能用于物化建表\'\n}\n// A manually edited statement is validated against the selected tenant-owned\n// datasource and exact target table before any placeholder metadata is changed.\nvar submittedDdl = text(body?.ddl).trim()\nif (!blank(submittedDdl)) {\n    var validationBody = body\n    body = { canvas: true, validateOnly: true, ddl: submittedDdl,\n        dbId: propList.dbId, tableName: propList.tableName }\n    createTable()\n    body = validationBody\n}\n// 表名由用户在物化抽屉中最终确认。按当前目标数据源枚举后做 trim + 不区分大小写\n// 对比，避免历史空格或数据库大小写规则造成“看似不同、实际重复”的误导。\nvar duplicateRows = db.table(\'db_table_t\').where()\n    .eq(\'datasource_id\', propList.dbId)\n    .eq(\'is_del\', 0)\n    .select()\nvar duplicate = null\nvar reuseTargetTable = false\nvar duplicateCheckTime = new Date()\nfor (candidate in (duplicateRows == null ? [] : duplicateRows)) {\n    if (text(first(candidate, [\'tableName\', \'table_name\'])).trim().toLowerCase() != propList.tableName.toLowerCase()) {\n        continue\n    }\n    var candidateId = text(candidate.tid)\n    var candidateSourceId = text(candidate.sourceTableId)\n    if (candidateSourceId == sourceTableId) {\n        duplicate = candidate\n        reuseTargetTable = true\n        break\n    }\n    var columnCount = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', candidateId)\n        .eq(\'is_del\', 0)\n        .count()\n    var sourceTaskCount = db.table(\'data_access_agg_task_t\').where()\n        .eq(\'source_table_id\', candidateId)\n        .eq(\'is_del\', 0)\n        .count()\n    var targetTaskCount = db.table(\'data_access_agg_task_t\').where()\n        .eq(\'target_table_id\', candidateId)\n        .eq(\'is_del\', 0)\n        .count()\n    var propCount = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', candidateId)\n        .eq(\'is_del\', 0)\n        .count()\n    var stalePlaceholder = (blank(candidateSourceId) || candidateSourceId == candidateId)\n        && columnCount == 0\n        && sourceTaskCount == 0\n        && targetTaskCount == 0\n        && propCount == 0\n    if (stalePlaceholder) {\n        db.table(\'db_table_t\').where().eq(\'tid\', candidateId)\n            .update({ is_del: 1, updated_time: duplicateCheckTime })\n    } else {\n        exit 400, \'目标数据表「\' + propList.tableName + \'」已存在于目标数据源「\'\n            + text(first(targetDatasource, [\'dbName\', \'db_name\'])) + \'」，请修改表名后重试\'\n    }\n}\n\n// 表字段名称去重，避免 DDL 创建失败后才暴露错误。\nvar names = {}\nfor (index, item in tableItems) {\n    if (blank(item.columnName)) {\n        exit 400, \'第\' + (index + 1) + \'个字段名称不能为空\'\n    }\n    var key = text(item.columnName).toLowerCase()\n    if (names[key] != null) {\n        exit 400, \'第\' + names[key] + \'个和第\' + (index + 1) + \'个字段名称重复\'\n    }\n    names[key] = index + 1\n}\n\n// 复用现有 DDL 生成和建表能力，保持各数据库类型的适配口径统一。\n// 如果上一次请求已经完成物理建表和 MySQL 目标表落库、但在 ES 同步处失败，\n// 本次重试直接复用同一目标表，避免重复建表/重复插主表。\nvar originalBody = body\nvar physicalTableReused = reuseTargetTable\nif (!reuseTargetTable) {\n    var ddl = submittedDdl\n    if (blank(ddl)) {\n        var ddlRequestBody = {\n            // Preserve the existing generated-DDL path for clients that do not\n            // explicitly submit an edited statement.\n            canvas: true,\n            propList: propList,\n            tableItems: tableItems\n        }\n        body = ddlRequestBody\n        ddl = getCreateTableDDL()\n    }\n    var createTableRequestBody = {\n        // Keep the execution strategy aligned with DDL generation: ordinary\n        // targets use JDBC, while server-managed MRS Hive uses hwhive on the\n        // deployment host and never reads a browser-side JDBC URL.\n        canvas: true,\n        ddl: ddl,\n        dbId: propList.dbId,\n        tableName: propList.tableName,\n        skipIfExists: true\n    }\n    body = createTableRequestBody\n    var createResult = createTable()\n    body = originalBody\n    // A physical table that is not registered for this source must not be adopted silently.\n    // Otherwise the next task creation can point at an incomplete target and open an empty canvas.\n    if (createResult != null && createResult.created == false) {\n        exit 409, \'目标物理表已存在，请先删除目标表或改用其他目标表名后再创建任务\'\n    }\n    physicalTableReused = createResult != null && createResult.created == false\n}\n\nvar now = new Date()\nvar targetTableId = reuseTargetTable ? text(duplicate.tid) : IdUtil.getSnowflakeNextIdStr()\nvar tableNameCn = propList.tableNameCn || propList.tableName\nvar lowerName = text(propList.tableName).toLowerCase()\nvar businessType = lowerName.endsWith(\'log\') ? \'日志表\'\n    : lowerName.endsWith(\'dict\') ? \'字典表\'\n    : lowerName.endsWith(\'temp\') || lowerName.endsWith(\'tmp\') ? \'临时表\'\n    : (first(sourceTable, [\'businessType\', \'business_type\']) || \'业务表\')\n\n// 写目标表主数据，并用 source_table_id 明确来源表。\nvar targetTableValues = {\n    datasource_id: propList.dbId,\n    table_name: propList.tableName,\n    table_name_cn: tableNameCn,\n    table_comment: tableNameCn,\n    table_type: propList.tableType || \'数据表\',\n    business_type: businessType,\n    record_count: 0,\n    field_count: tableItems.size(),\n    storage_size: \'0 KB\',\n    total_size_bytes: 0,\n    total_size_formatted: \'0 KB\',\n    related_directory: \'自动生成目录\',\n    source_table_id: sourceTableId,\n    source_table_name: first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\']),\n    org_id: sourceTable.orgId || targetDatasource.orgId,\n    tenant_id: tenantId,\n    is_del: 0,\n    asset_status: 2,\n    flow_status: 2,\n    updated_time: now\n}\nif (reuseTargetTable) {\n    db.table(\'db_table_t\').where().eq(\'tid\', targetTableId).update(targetTableValues)\n    db.table(\'db_table_column_t\').where().eq(\'table_id\', targetTableId).update({ is_del: 1, updated_time: now })\n} else {\n    targetTableValues.tid = targetTableId\n    targetTableValues.reg_time = now\n    targetTableValues.created_time = now\n    db.table(\'db_table_t\').primary(\'tid\').insert(targetTableValues)\n}\n\nvar columns = []\nvar sourceColumns = db.table(\'db_table_column_t\').where()\n    .eq(\'table_id\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .select()\nvar sourceColumnMap = {}\nfor (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n    sourceColumnMap[text(sourceColumn.columnName).toLowerCase()] = sourceColumn\n}\nfor (index, item in tableItems) {\n    var sourceColumn = sourceColumnMap[text(item.columnName).toLowerCase()]\n    if (sourceColumn == null && !blank(item.dictionarySourceField)) {\n        sourceColumn = sourceColumnMap[text(item.dictionarySourceField).toLowerCase()]\n    }\n    columns.add({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        table_id: targetTableId,\n        column_name: item.columnName,\n        column_comment: item.columnComment,\n        data_type: item.dataType,\n        column_type: item.columnType,\n        length: item.length,\n        precision_length: item.precisionLength,\n        scale: item.scale,\n        nullable: item.nullable,\n        default_value: item.defaultValue,\n        primary_key: item.primaryKey,\n        auto_increment: item.autoIncrement,\n        is_unique: item.isUnique,\n        indexed: item.indexed,\n        ordinal_position: index,\n        charset: item.charset,\n        collation: item.collation,\n        extra: item.extra,\n        source_table_column_id: sourceColumn == null ? null : sourceColumn.tid,\n        tenant_id: tenantId,\n        is_del: 0,\n        created_time: now,\n        updated_time: now\n    })\n}\n// Java 通用持久化层依据当前数据库的标识符规则引用保留字列，兼容 MySQL、达梦等数据库。\ntry {\n    metadataAsset.batchInsertTableColumns(columns)\n} catch (e) {\n    // 当前运行包存在 MySQL 驱动批处理兼容问题时，回退为 Magic 命名表逐行插入。\n    for (column in columns) {\n        db.table(\'db_table_column_t\').primary(\'tid\').insert(column)\n    }\n}\n\n// Persist a first-class source-to-target binding for every dictionary\n// translation/mandatory-standard output.  <source>_cn remains the default\n// field created by the UI, but the workflow later reads this binding rather\n// than deriving semantics from the target field name.\nvar targetGovernanceConfig = {\n    version: 3,\n    registrationSavedPhase: \'materialized\',\n    sourceTableId: sourceTableId,\n    sourceTableName: first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\']),\n    fieldTransformBindings: buildFieldTransformBindings(sourceTable, sourceColumns, targetTableId, tableItems, columns)\n}\ndb.table(\'db_table_t\').where().eq(\'tid\', targetTableId).eq(\'is_del\', 0)\n    .update({ field_governance_config: jsons.toJSONStr(targetGovernanceConfig), updated_time: now })\n\n// 目标表同步到 ES，供列表和详情快速读取。\nvar targetDoc = {\n    tid: targetTableId,\n    assetType: \'table\',\n    datasourceId: propList.dbId,\n    dbId: propList.dbId,\n    dbName: targetDatasource.dbName,\n    appId: targetDatasource.appId,\n    orgId: targetDatasource.orgId,\n    tableName: propList.tableName,\n    tableNameCn: tableNameCn,\n    tableComment: tableNameCn,\n    tableType: propList.tableType || \'数据表\',\n    businessType: businessType,\n    sourceTableId: sourceTableId,\n    sourceTableName: first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\']),\n    recordCount: 0,\n    fieldCount: tableItems.size(),\n    storageSize: \'0 KB\',\n    totalSizeBytes: 0,\n    totalSizeFormatted: \'0 KB\',\n    assetStatus: 2,\n    flowStatus: 2,\n    regTime: date_format(now),\n    createdTime: date_format(now),\n    updatedTime: date_format(now),\n    regTime_date: date_format(now),\n    createdTime_date: date_format(now),\n    updatedTime_date: date_format(now)\n}\ntry {\n    esCommonService.saveOrUpdate(\'dataassets\', targetTableId, jsons.toJSONStr(targetDoc), false)\n} catch (e) {\n    // elements_dataassets 是混合投影索引，历史 mapping 里 datasourceId 等字符串字段可能是 text。\n    // saveOrUpdate 的动态 mapping 校验会把普通字符串推断为 keyword 并误判冲突；\n    // 这里目标表文档字段均为 ES 可接受的普通标量，回退到直接按 id 写入，避免物化链路中断。\n    try {\n        esCommonService.save(\'dataassets\', targetTableId, targetDoc)\n    } catch (ignored) {\n        // ES 临时不可用时不阻断物理表和 MySQL 元数据提交。\n    }\n}\n\n// 如果来源表已有自动目录则复用，否则新建。目录代表目标表，但保留来源表属性形成完整链路。\nif (blank(catalogId)) {\n    var sourceCatalogProps = db.table(\'da_prop_t\').where()\n        .eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', sourceTableId)\n        .eq(\'is_del\', 0)\n        .select()\n    for (sourceCatalogProp in (sourceCatalogProps == null ? [] : sourceCatalogProps)) {\n        var sourceCatalogAsset = db.table(\'da_catalog_t\').where()\n            .eq(\'tid\', sourceCatalogProp.parentId)\n            .eq(\'is_del\', 0)\n            .selectOne()\n        if (sourceCatalogAsset != null && blank(catalogId)) {\n            catalogId = text(sourceCatalogProp.parentId)\n        }\n    }\n}\nif (blank(catalogId)) {\n    catalogId = IdUtil.getSnowflakeNextIdStr()\n    db.table(\'da_catalog_t\').primary(\'tid\').insert({\n        tid: catalogId,\n        is_del: 0,\n        reg_time: now,\n        asset_status: 2,\n        flow_status: 2,\n        created_time: now,\n        updated_time: now\n    })\n} else {\n    db.table(\'da_catalog_t\').where()\n        .eq(\'tid\', catalogId)\n        .update({ updated_time: now, asset_status: 2, flow_status: 2, is_del: 0 })\n}\n\nvar catalogName = tableNameCn\nvar sourceTableName = first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\nupsertCatalogProp(catalogId, \'catalogName\', catalogName, now)\nupsertCatalogProp(catalogId, \'catalogNameEn\', propList.tableName, now)\nupsertCatalogProp(catalogId, \'assetDesc\', catalogName, now)\nupsertCatalogProp(catalogId, \'dataSourceType\', \'ods\', now)\nupsertCatalogProp(catalogId, \'businessType\', businessType, now)\nupsertCatalogProp(catalogId, \'sourceDbId\', sourceTable.datasourceId, now)\nupsertCatalogProp(catalogId, \'sourceDbName\', sourceDatasource == null ? \'\' : sourceDatasource.dbName, now)\nupsertCatalogProp(catalogId, \'sourceTableId\', sourceTableId, now)\nupsertCatalogProp(catalogId, \'sourceTableName\', sourceTableName, now)\nupsertCatalogProp(catalogId, \'targetDbId\', propList.dbId, now)\nupsertCatalogProp(catalogId, \'targetDbType\', targetDatasource.dbType || \'mysql\', now)\nupsertCatalogProp(catalogId, \'targetTableId\', targetTableId, now)\nupsertCatalogProp(catalogId, \'targetTableName\', propList.tableName, now)\nupsertCatalogProp(catalogId, \'dbId\', propList.dbId, now)\nupsertCatalogProp(catalogId, \'orgId\', sourceTable.orgId || targetDatasource.orgId, now)\nupsertCatalogProp(catalogId, \'manageUnit\', sourceTable.orgId || targetDatasource.orgId, now)\n\nvar catalogDoc = {\n    tid: catalogId,\n    assetType: \'catalog\',\n    catalogName: catalogName,\n    catalogNameEn: propList.tableName,\n    assetDesc: catalogName,\n    dataSourceType: \'ods\',\n    businessType: businessType,\n    sourceDbId: sourceTable.datasourceId,\n    sourceDbName: sourceDatasource == null ? \'\' : sourceDatasource.dbName,\n    sourceTableId: sourceTableId,\n    sourceTableName: sourceTableName,\n    targetDbId: propList.dbId,\n    targetDbType: targetDatasource.dbType || \'mysql\',\n    targetTableId: targetTableId,\n    targetTableName: propList.tableName,\n    dbId: propList.dbId,\n    orgId: sourceTable.orgId || targetDatasource.orgId,\n    assetStatus: 2,\n    flowStatus: 2,\n    regTime: date_format(now),\n    createdTime: date_format(now),\n    updatedTime: date_format(now)\n}\ntry {\n    esCommonService.saveOrUpdate(\'dataassets\', catalogId, jsons.toJSONStr(catalogDoc), false)\n} catch (e) {\n    try {\n        esCommonService.save(\'dataassets\', catalogId, catalogDoc)\n    } catch (ignored) {\n        // ES 临时不可用时不阻断物理表和 MySQL 元数据提交。\n    }\n}\n\n// 反写来源表与目标表的目录关联，后续列表和任务创建都能直接定位。\ndb.table(\'db_table_t\').where().eq(\'tid\', sourceTableId).eq(\'is_del\', 0)\n    .update({ source_catalog_id: catalogId, catalog_name: catalogName, updated_time: now })\ndb.table(\'db_table_t\').where().eq(\'tid\', targetTableId).eq(\'is_del\', 0)\n    .update({ source_catalog_id: catalogId, catalog_name: catalogName, updated_time: now })\n\nreturn {\n    tid: targetTableId,\n    targetTableId: targetTableId,\n    catalogId: catalogId,\n    sourceTableId: sourceTableId,\n    physicalTableReused: physicalTableReused\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/02.数据接入物化建表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "ods_nifi_node_save_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "03.保存数据同步节点",\n  "createTime": null,\n  "updateTime": 1788228593757,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/nifi-node/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"nodeName\\": \\"数据同步主节点\\",\\n  \\"nodeCode\\": \\"primary-nifi\\",\\n  \\"baseUrl\\": \\"https://nifi.example.com:8443\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"tid\\": \\"2087600000000000001\\"\\n}",\n  "description": "保存数据同步节点（POST /ods/nifi-node/saveOrUpdate）。仅维护当前租户节点，每个所属网络必须且只能有一个默认节点；使用请求参数 tid、nodeName、nodeCode、baseUrl、networkCode、enabled、isDefault、rootProcessGroupId；涉及 sym_dict_t、nifi_node_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.保存数据同步节点\n// 路由：POST /ods/nifi-node/saveOrUpdate\n// 业务说明：保存数据同步节点（POST /ods/nifi-node/saveOrUpdate）。仅维护当前租户节点，每个所属网络必须且只能有一个默认节点；使用请求参数 tid、nodeName、nodeCode、baseUrl、networkCode、enabled、isDefault、rootProcessGroupId；涉及 sym_dict_t、nifi_node_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || text(value).trim() == \'\'\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar tid = text(body?.tid).trim()\nvar nodeName = text(body?.nodeName).trim()\nvar nodeCode = text(body?.nodeCode).trim()\nvar baseUrl = text(body?.baseUrl).trim().replaceAll(\'/+$\', \'\')\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(nodeName) || blank(nodeCode) || blank(baseUrl)) {\n    exit 400, \'节点名称、节点编码和 NiFi 地址不能为空\'\n}\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再维护节点\'\n}\nvar networkCode = text(body?.networkCode).trim()\nif (networkCode == \'\') {\n    exit 400, \'请选择所属网络\'\n}\n// 以下从 sym_dict_t 业务表读取或维护当前操作涉及的记录。\nvar networkRoot = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'dict_code\', \'SSWL\').eq(\'is_del\', 0).selectOne()\nif (networkRoot == null || db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', networkRoot.tid).eq(\'dict_code\', networkCode).eq(\'is_del\', 0).selectOne() == null) {\n    exit 400, \'所属网络不存在或已停用\'\n}\nif (!baseUrl.matches(\'^https?://.+\')) {\n    exit 400, \'NiFi 地址必须以 http:// 或 https:// 开头\'\n}\nvar now = new Date()\nvar enabled = body?.enabled == false || text(body?.enabled) == \'0\' ? 0 : 1\nvar isDefault = body?.isDefault == true || text(body?.isDefault) == \'1\' ? 1 : 0\nvar duplicate = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'node_code\', nodeCode).eq(\'is_del\', 0).selectOne()\nif (duplicate != null && text(duplicate.tid) != tid) {\n    exit 400, \'节点编码已存在，请使用其他编码\'\n}\nvar networkDefault = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'network_code\', networkCode).eq(\'is_del\', 0).eq(\'is_default\', 1).selectOne()\nif (blank(tid) && networkDefault == null) {\n    isDefault = 1\n}\nif (isDefault == 1) {\n    db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'network_code\', networkCode).eq(\'is_del\', 0).update({ is_default: 0, updated_time: now })\n}\nif (blank(tid)) {\n    tid = IdUtil.getSnowflakeNextIdStr()\n    db.table(\'nifi_node_t\').primary(\'tid\').insert({\n        tid: tid, tenant_id: tenantId, node_name: nodeName, node_code: nodeCode, base_url: baseUrl,\n        network_code: networkCode, root_process_group_id: text(body?.rootProcessGroupId).trim(), remark: text(body?.remark).trim(),\n        enabled: enabled, is_default: isDefault, created_time: now, updated_time: now, is_del: 0\n    })\n} else {\n    var existing = db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n    if (existing == null) {\n        exit 404, \'数据同步节点不存在或已删除\'\n    }\n    var persistedDefault = existing.isDefault == null ? existing.is_default : existing.isDefault\n    var persistedNetworkCode = text(existing.networkCode == null ? existing.network_code : existing.networkCode).trim()\n    if ((persistedDefault == 1 || persistedDefault == true) && persistedNetworkCode != \'\' && persistedNetworkCode != networkCode) {\n        exit 400, \'默认节点不能直接变更所属网络，请先在原网络设置新的默认节点\'\n    }\n    if ((persistedDefault == 1 || persistedDefault == true) && isDefault == 0) {\n        exit 400, \'每个所属网络必须保留一个默认节点，请先将其他节点设为默认\'\n    }\n    db.table(\'nifi_node_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', tid).eq(\'is_del\', 0).update({\n        node_name: nodeName, node_code: nodeCode, base_url: baseUrl,\n        network_code: networkCode, root_process_group_id: text(body?.rootProcessGroupId).trim(), remark: text(body?.remark).trim(),\n        enabled: enabled, is_default: isDefault, updated_time: now\n    })\n}\nreturn { tid: tid }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/03.保存数据同步节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f186f33ba36d466e9f84359de432ff46',NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dc3a0d7cd3b04a959a71eac11398379f',NULL,NULL,'{\n  "properties": {},\n  "id": "dc3a0d7cd3b04a959a71eac11398379f",\n  "groupId": "56755e012bc14bec93d431716f86b595",\n  "name": "01.概览",\n  "path": "/summary",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/summary；只读；汇总当前租户的策略、执行状态和未处理差异；页面级业务接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：01.概览\n// 路由：POST /summary（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/summary；只读；汇总当前租户的策略、执行状态和未处理差异；页面级业务接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 只接受当前登录会话的业务租户；统计窗口固定为最近 30 天。\nvar tenantId = tenantRuntime.id()\nreturn reconcile.summary(30)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fb722da18e7b4c218c29bb65eb96dfed',NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a51c07d0f6814d78b15fbcd1adfed1c8',NULL,NULL,'{\n  "properties": {},\n  "id": "a51c07d0f6814d78b15fbcd1adfed1c8",\n  "groupId": "ccb8f94e621a4feaa18362a325890270",\n  "name": "01.策略分页",\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"page\\":1,\\"size\\":20,\\"keyword\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/policy/page；只读；分页查询当前租户对账策略及最近一次执行结果；策略列表主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：01.策略分页\n// 路由：POST /page（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/policy/page；只读；分页查询当前租户对账策略及最近一次执行结果；策略列表主接口。\n\nimport tenantRuntime\nimport reconcile\nimport cn.hutool.core.util.NumberUtil\n\n// 从当前会话取得租户，并规范化筛选词和分页参数。\nvar tenantId = tenantRuntime.id()\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\n\n// 仓储只查询当前租户的策略，保留既有排序和最近执行结果。\nreturn reconcile.policyPage(keyword, page, size)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/01.策略分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('19657ee2c5e541d9b2f881f6920cf55d',NULL,NULL,'{\n  "properties": {},\n  "id": "19657ee2c5e541d9b2f881f6920cf55d",\n  "groupId": "ccb8f94e621a4feaa18362a325890270",\n  "name": "02.策略详情",\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"policyId\\":\\"策略ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/policy/detail；只读；读取当前租户策略、接入任务、源目标表和字段规则；策略详情主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：02.策略详情\n// 路由：POST /detail（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/policy/detail；只读；读取当前租户策略、接入任务、源目标表和字段规则；策略详情主接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 策略标识为必填；具体记录还必须在当前租户范围内存在。\nvar tenantId = tenantRuntime.id()\nvar policyId = body?.policyId == null ? \'\' : (\'\' + body.policyId).trim()\nif (policyId == \'\') { exit 400, \'策略ID不能为空\' }\nreturn reconcile.policyDetail(policyId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/02.策略详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7e1e2a2090934d67954d5d9e3df59c66',NULL,NULL,'{\n  "properties": {},\n  "id": "7e1e2a2090934d67954d5d9e3df59c66",\n  "groupId": "ccb8f94e621a4feaa18362a325890270",\n  "name": "03.保存策略",\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"policyName\\":\\"接入任务每日主键对账\\",\\"accessTaskId\\":\\"接入任务ID\\",\\"compareMode\\":\\"KEY\\",\\"triggerMode\\":\\"MANUAL\\",\\"bucketCount\\":8,\\"fetchSize\\":2000}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/policy/save；写入；保存策略并从 data_access_field_mapping 初始化字段规则；策略维护主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：03.保存策略\n// 路由：POST /save（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/policy/save；写入；保存策略并从 data_access_field_mapping 初始化字段规则；策略维护主接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 先检查策略名称和接入任务；新增时仓储从接入任务字段映射初始化规则。\nvar tenantId = tenantRuntime.id()\nif (body == null) { exit 400, \'请填写对账策略\' }\nif (body?.policyName == null || (\'\' + body.policyName).trim() == \'\') { exit 400, \'策略名称不能为空\' }\nif (body?.accessTaskId == null || (\'\' + body.accessTaskId).trim() == \'\') { exit 400, \'请选择数据接入任务\' }\nvar triggerMode = body?.triggerMode == null ? \'MANUAL\' : (\'\' + body.triggerMode).trim()\nif (triggerMode == \'CRON\' && (body?.cronExpression == null || (\'\' + body.cronExpression).trim() == \'\')) {\n    exit 400, \'定时策略必须配置 Cron 表达式\'\n}\n\n// 策略和规则的多表写入由仓储事务完成；保存后重新读取完整详情。\nvar policyId = reconcile.persistPolicy(body)\nreturn reconcile.policyDetail(policyId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/03.保存策略.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9b5e2f59c4f04b8c900f81f178c27458',NULL,NULL,'{\n  "properties": {},\n  "id": "9b5e2f59c4f04b8c900f81f178c27458",\n  "groupId": "ccb8f94e621a4feaa18362a325890270",\n  "name": "04.策略预检",\n  "path": "/precheck",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"policyId\\":\\"策略ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/policy/precheck；读写；检查源目标连接、表字段和唯一索引并回写预检结果；策略启用前置接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：04.策略预检\n// 路由：POST /precheck（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/policy/precheck；读写；检查源目标连接、表字段和唯一索引并回写预检结果；策略启用前置接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 预检跨源、目标两个数据库，只检查连接、主键、字段及能力，不扫描全表。\nvar tenantId = tenantRuntime.id()\nvar policyId = body?.policyId == null ? \'\' : (\'\' + body.policyId).trim()\nif (policyId == \'\') { exit 400, \'策略ID不能为空\' }\nvar result = reconcile.inspectPolicy(policyId)\n\n// 把原始预检结果保存到策略，启用接口再据此判定是否允许启用。\nreconcile.persistPrecheck(policyId, result)\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/04.策略预检.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fe4bfa8569fb4f22ab05ddf2af860118',NULL,NULL,'{\n  "properties": {},\n  "id": "fe4bfa8569fb4f22ab05ddf2af860118",\n  "groupId": "ccb8f94e621a4feaa18362a325890270",\n  "name": "05.策略启停",\n  "path": "/enable",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"policyId\\":\\"策略ID\\",\\"enabled\\":true}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/policy/enable；写入；启用或停用当前租户策略，启用前必须通过预检；策略状态接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：05.策略启停\n// 路由：POST /enable（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/policy/enable；写入；启用或停用当前租户策略，启用前必须通过预检；策略状态接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 接口明确解析启停意图；仓储最终强制执行“预检通过才可启用”。\nvar tenantId = tenantRuntime.id()\nvar policyId = body?.policyId == null ? \'\' : (\'\' + body.policyId).trim()\nif (policyId == \'\') { exit 400, \'策略ID不能为空\' }\nvar enabled = body?.enabled == true || body?.enabled == 1 || (\'\' + body?.enabled).toLowerCase() == \'true\' || body?.enabled == \'1\'\nreturn reconcile.setPolicyEnabled(policyId, enabled)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/05.策略启停.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ccb8f94e621a4feaa18362a325890270',NULL,NULL,'{\n  "properties": {},\n  "id": "ccb8f94e621a4feaa18362a325890270",\n  "name": "01.策略管理",\n  "type": "api",\n  "parentId": "56755e012bc14bec93d431716f86b595",\n  "path": "/policy",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/01.策略管理/group.json');
