INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9ab9834851824ee4aedc909a53a47d56',NULL,NULL,'{\n  "properties": {},\n  "id": "9ab9834851824ee4aedc909a53a47d56",\n  "groupId": "986c0e9209674f818072e3044d98013c",\n  "name": "01.手动发起",\n  "path": "/manual",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"policyId\\":\\"策略ID\\",\\"lowerWatermark\\":\\"2026-07-29 00:00:00\\",\\"upperWatermark\\":\\"2026-07-30 00:00:00\\",\\"requestId\\":\\"页面生成的幂等ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/manual；写入；创建幂等对账实例并交由 Worker 异步执行；手动执行主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：01.手动发起\n// 路由：POST /manual（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/manual；写入；创建幂等对账实例并交由 Worker 异步执行；手动执行主接口。\n\nimport tenantRuntime\nimport reconcile\nimport java.util.UUID\n\n// 只投递执行实例，不在 HTTP 请求线程扫描源表和目标表。\nvar tenantId = tenantRuntime.id()\nvar policyId = body?.policyId == null ? \'\' : (\'\' + body.policyId).trim()\nif (policyId == \'\') { exit 400, \'策略ID不能为空\' }\nvar requestId = body?.requestId == null || (\'\' + body.requestId).trim() == \'\' ? UUID.randomUUID().toString() : \'\' + body.requestId\nvar accessRunId = body?.accessRunId == null ? null : \'\' + body.accessRunId\nvar lower = body?.lowerWatermark == null ? null : \'\' + body.lowerWatermark\nvar upper = body?.upperWatermark == null ? null : \'\' + body.upperWatermark\n\n// 仓储以 requestId 和水位生成幂等键；重复提交返回既有实例。\nvar runId = reconcile.createRun(policyId, \'MANUAL\', accessRunId, lower, upper, requestId)\nreturn reconcile.runDetail(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/01.手动发起.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9451d67137ed4cec98caa1a91039e086',NULL,NULL,'{\n  "properties": {},\n  "id": "9451d67137ed4cec98caa1a91039e086",\n  "groupId": "986c0e9209674f818072e3044d98013c",\n  "name": "02.接入完成触发",\n  "path": "/access-completed",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"accessTaskId\\":\\"接入任务ID\\",\\"accessRunId\\":\\"NiFi执行实例ID\\",\\"lowerWatermark\\":\\"2026-07-29 00:00:00\\",\\"upperWatermark\\":\\"2026-07-30 00:00:00\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/access-completed；写入；接收 NiFi 接入完成事件并为已启用 ACCESS_EVENT 策略创建对账实例；NiFi 回调接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：02.接入完成触发\n// 路由：POST /access-completed（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/access-completed；写入；接收 NiFi 接入完成事件并为已启用 ACCESS_EVENT 策略创建对账实例；NiFi 回调接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 接入完成事件只触发当前租户已启用的 ACCESS_EVENT 策略。\nvar tenantId = tenantRuntime.id()\nvar accessTaskId = body?.accessTaskId == null ? \'\' : (\'\' + body.accessTaskId).trim()\nvar accessRunId = body?.accessRunId == null ? \'\' : (\'\' + body.accessRunId).trim()\nif (accessTaskId == \'\') { exit 400, \'接入任务ID不能为空\' }\nif (accessRunId == \'\') { exit 400, \'接入实例ID不能为空\' }\nvar lower = body?.lowerWatermark == null ? null : \'\' + body.lowerWatermark\nvar upper = body?.upperWatermark == null ? null : \'\' + body.upperWatermark\nvar runs = []\n\n// 同一接入实例重复通知时复用仓储的幂等键，不生成重复对账。\nfor (policyId in reconcile.accessEventPolicyIds(accessTaskId)) {\n    var runId = reconcile.createRun(policyId, \'ACCESS_EVENT\', accessRunId, lower, upper, accessRunId)\n    runs.add(reconcile.runDetail(runId))\n}\nreturn runs\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/02.接入完成触发.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e3e39c7d77a3481685b05a20dc8c780f',NULL,NULL,'{\n  "properties": {},\n  "id": "e3e39c7d77a3481685b05a20dc8c780f",\n  "groupId": "986c0e9209674f818072e3044d98013c",\n  "name": "03.实例分页",\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"page\\":1,\\"size\\":20,\\"status\\":\\"\\",\\"keyword\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/page；只读；分页查询当前租户历史执行实例及一致率；历史对账单主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：03.实例分页\n// 路由：POST /page（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/page；只读；分页查询当前租户历史执行实例及一致率；历史对账单主接口。\n\nimport tenantRuntime\nimport reconcile\nimport cn.hutool.core.util.NumberUtil\n\n// 分页展示当前租户历史实例，并允许按状态和关键词筛选。\nvar tenantId = tenantRuntime.id()\nvar status = body?.status == null ? \'\' : (\'\' + body.status).trim()\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\nreturn reconcile.runPage(status, keyword, page, size)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/03.实例分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1efb293c48c34d83bc74d4a7794153e7',NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/03.差异明细/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6b0450ec31e341be8c075c4d93d330e1',NULL,NULL,'{\n  "properties": {},\n  "id": "6b0450ec31e341be8c075c4d93d330e1",\n  "groupId": "0c0fe2ac06f04679b4b52cfa19c54d96",\n  "name": "01.差异分页",\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"执行实例ID\\",\\"type\\":\\"VALUE_MISMATCH\\",\\"page\\":1,\\"size\\":20}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/diff/page；只读；分页查询脱敏后的字段级差异；差异明细主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：01.差异分页\n// 路由：POST /page（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/diff/page；只读；分页查询脱敏后的字段级差异；差异明细主接口。\n\nimport tenantRuntime\nimport reconcile\nimport cn.hutool.core.util.NumberUtil\n\n// 差异明细只展示当前租户指定实例的脱敏字段差异。\nvar tenantId = tenantRuntime.id()\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'对账实例ID不能为空\' }\nvar type = body?.type == null ? \'\' : (\'\' + body.type).trim()\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\nreturn reconcile.diffPage(runId, type, page, size)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/03.差异明细/01.差异分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8d8b3bc50f054a0dbeb2baf22500e8a6',NULL,NULL,'{\n  "properties": {},\n  "id": "8d8b3bc50f054a0dbeb2baf22500e8a6",\n  "groupId": "0c0fe2ac06f04679b4b52cfa19c54d96",\n  "name": "02.差异完整导出",\n  "path": "/export",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"执行实例ID\\",\\"type\\":\\"VALUE_MISMATCH\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/diff/export；当前租户已完成实例的全部脱敏差异，最多5000条，超限明确拒绝，不截断。",\n  "script": null\n}\n================================\n// 复用仓储层的租户隔离与脱敏查询。运行中的差异仍可能增加，不作为完整导出。\nimport tenantRuntime\nimport reconcile\nimport cn.hutool.core.util.NumberUtil\n\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (\'\' + tenantId).trim() == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录后导出\'\n}\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (!runId.matches(\'^[A-Za-z0-9_-]{1,64}$\')) {\n    exit 400, \'对账实例ID无效\'\n}\nvar type = body?.type == null ? \'\' : (\'\' + body.type).trim()\nif (type.length() > 64) {\n    exit 400, \'差异类型无效\'\n}\nvar ownedRun = db.table(\'data_reconcile_run_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'tid\', runId).selectOne()\nif (ownedRun == null) {\n    exit 404, \'对账实例不存在或无权访问\'\n}\nvar run = reconcile.runDetail(runId)\nvar runStatus = run.status == null ? \'\' : (\'\' + run.status).trim().toUpperCase()\nif (runStatus != \'CONSISTENT\' && runStatus != \'INCONSISTENT\') {\n    exit 409, \'仅已完成的对账实例可完整导出差异\'\n}\n\nvar limit = 5000\nvar pageSize = 200\nvar first = reconcile.diffPage(runId, type, 1, pageSize)\nvar total = NumberUtil.parseLong(\'\' + first.total)\nif (total < 0) {\n    exit 500, \'差异总数无效，请稍后重试\'\n}\nif (total > limit) {\n    exit 413, \'差异共\' + total + \'条，超过单次导出上限5000条；请缩小差异类型范围或使用后台分片导出\'\n}\nvar rows = []\nvar page = 1\nvar current = first\nwhile (rows.size() < total) {\n    var batch = current.list == null ? [] : current.list\n    if (batch.size() == 0) {\n        exit 409, \'差异数据在导出期间发生变化，请重新导出\'\n    }\n    for (diff in batch) {\n        rows.add({\n            businessKey: diff.business_key,\n            diffType: diff.diff_type,\n            fieldName: diff.field_name,\n            sourceValueMasked: diff.source_value_masked,\n            targetValueMasked: diff.target_value_masked\n        })\n    }\n    if (rows.size() >= total) { break }\n    page = page + 1\n    current = reconcile.diffPage(runId, type, page, pageSize)\n}\nif (rows.size() != total) {\n    exit 409, \'差异数据在导出期间发生变化，请重新导出\'\n}\nreturn {\n    runId: runId,\n    runStatus: runStatus,\n    type: type,\n    total: total,\n    limit: limit,\n    filename: \'reconciliation-diffs-\' + runId + \'.json\',\n    rows: rows\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/03.差异明细/02.差异完整导出.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0c0fe2ac06f04679b4b52cfa19c54d96',NULL,NULL,'{\n  "properties": {},\n  "id": "0c0fe2ac06f04679b4b52cfa19c54d96",\n  "name": "03.差异明细",\n  "type": "api",\n  "parentId": "986c0e9209674f818072e3044d98013c",\n  "path": "/diff",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/03.差异明细/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bf5e4120008242979d347ccd67de8604',NULL,NULL,'{\n  "properties": {},\n  "id": "bf5e4120008242979d347ccd67de8604",\n  "groupId": "986c0e9209674f818072e3044d98013c",\n  "name": "04.实例详情",\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"执行实例ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/detail；只读；读取实例、分桶进度、统计和差异分类；执行详情主接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：04.实例详情\n// 路由：POST /detail（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/detail；只读；读取实例、分桶进度、统计和差异分类；执行详情主接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 读取实例、分桶进度和差异分类；仓储强制当前租户归属。\nvar tenantId = tenantRuntime.id()\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'对账实例ID不能为空\' }\nreturn reconcile.runDetail(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/04.实例详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('901cb59ef73f4404bdee6049f20889ef',NULL,NULL,'{\n  "properties": {},\n  "id": "901cb59ef73f4404bdee6049f20889ef",\n  "groupId": "986c0e9209674f818072e3044d98013c",\n  "name": "05.取消实例",\n  "path": "/cancel",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"执行实例ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /ods/reconciliation/run/cancel；写入；设置取消标记，由 Worker 在流式检查点安全停止；执行控制接口。",\n  "createTime": 1785340800000,\n  "updateTime": 1785340800000,\n  "script": null\n}\n================================\n// 接口：05.取消实例\n// 路由：POST /cancel（完整路由由目录分组组合）\n// 业务说明：POST /ods/reconciliation/run/cancel；写入；设置取消标记，由 Worker 在流式检查点安全停止；执行控制接口。\n\nimport tenantRuntime\nimport reconcile\n\n// 只设置取消标记；Worker 在流式检查点安全结束，保留已完成进度。\nvar tenantId = tenantRuntime.id()\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'对账实例ID不能为空\' }\nreturn reconcile.requestCancel(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/03.数据对账/02.执行管理/05.取消实例.ms');
