null ? [] : sourceRows)) { sourceTableMap[text(sourceRow.tid)] = sourceRow }\n}\n\nvar sourceDatasourceIds = []\nfor (sourceId in sourceIds) {\n  var sourceTable = sourceTableMap[sourceId]\n  if (sourceTable != null) {\n    var sourceDatasourceId = text(sourceTable.datasourceId || sourceTable.datasource_id)\n    if (!blank(sourceDatasourceId) && !sourceDatasourceIds.contains(sourceDatasourceId)) { sourceDatasourceIds.add(sourceDatasourceId) }\n  }\n}\nvar sourceDatasourceMap = {}\nif (sourceDatasourceIds.size() > 0) {\n  var sourceDatasources = db.table(\'db_datasource_t\').where()\n    .in(\'tid\', sourceDatasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (sourceDatasource in (sourceDatasources == null ? [] : sourceDatasources)) { sourceDatasourceMap[text(sourceDatasource.tid)] = sourceDatasource }\n}\n\nvar orgCounts = {}\nvar appMaps = {}\nvar total = 0\nfor (row in targetRows) {\n  var sourceId = text(row.sourceTableId || row.source_table_id)\n  var sourceTable = sourceTableMap[sourceId]\n  if (sourceTable == null) { continue }\n  var sourceDatasourceId = text(sourceTable.datasourceId || sourceTable.datasource_id)\n  var sourceDatasource = sourceDatasourceMap[sourceDatasourceId]\n  // 历史来源数据源可能已被注销；仍保留其已物化目标表，避免左树与总表数量不一致。\n  if (blank(sourceDatasourceId)) { sourceDatasourceId = \'history:\' + sourceId }\n  var orgId = text(sourceTable.orgId || sourceTable.org_id || row.orgId || row.org_id)\n  var appId = sourceDatasource == null ? \'\' : text(sourceDatasource.appId || sourceDatasource.app_id || sourceDatasource.applicationId || sourceDatasource.application_id)\n  var appLabel = sourceDatasource == null ? \'\' : text(sourceDatasource.appName || sourceDatasource.app_name || sourceDatasource.applicationName || sourceDatasource.application_name)\n  if (blank(appId)) { appId = \'datasource:\' + sourceDatasourceId }\n  if (blank(appLabel)) { appLabel = sourceDatasource == null ? \'历史来源数据源\' : (sourceDatasource.dbName || sourceDatasource.db_name || \'未归属应用\') }\n  orgCounts[orgId] = (orgCounts[orgId] || 0) + 1\n  if (appMaps[orgId] == null) { appMaps[orgId] = {} }\n  if (appMaps[orgId][appId] == null) { appMaps[orgId][appId] = { label: appLabel, value: appId, count: 0, datasourceMap: {} } }\n  var app = appMaps[orgId][appId]\n  app.count = app.count + 1\n  if (app.datasourceMap[sourceDatasourceId] == null) {\n    app.datasourceMap[sourceDatasourceId] = {\n      label: sourceDatasource == null ? sourceDatasourceId : (sourceDatasource.dbName || sourceDatasource.db_name || sourceDatasourceId),\n      value: sourceDatasourceId, count: 0,\n      dbType: sourceDatasource == null ? \'\' : (sourceDatasource.dbType || sourceDatasource.db_type || \'\'),\n      connectionStatus: sourceDatasource == null ? \'\' : (sourceDatasource.connectionStatus || sourceDatasource.connection_status || \'\'),\n      showConnect: sourceDatasource == null ? null : (sourceDatasource.showConnect || sourceDatasource.show_connect), children: []\n    }\n  }\n  app.datasourceMap[sourceDatasourceId].count = app.datasourceMap[sourceDatasourceId].count + 1\n  total = total + 1\n}\nvar orgApps = {}\nfor (orgId in appMaps.keySet()) {\n  var apps = []\n  for (appId in appMaps[orgId].keySet()) {\n    var app = appMaps[orgId][appId]\n    var datasources = []\n    for (sourceDatasourceId in app.datasourceMap.keySet()) { datasources.add(app.datasourceMap[sourceDatasourceId]) }\n    apps.add({ label: app.label, value: app.value, count: app.count, datasources: datasources })\n  }\n  orgApps[orgId] = apps\n}\nreturn {\n  total: total, orgCounts: orgCounts, orgApps: orgApps\n}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/06.Hive原始库组织树接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_data_agg_tree_statistics_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_data_agg_tree_statistics_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "07.数据汇聚数据表树统计",\n  "createTime": 1785060000000,\n  "updateTime": 1790155763671,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dataAggTreeStatistics",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"出入境\\",\\n  \\"orgIds\\": []\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"total\\": 374,\\n  \\"orgCounts\\": {\\"1351480103971975170\\": 23},\\n  \\"orgApps\\": {\\"1351480103971975170\\": [{\\"value\\": \\"1980105567668809728\\", \\"label\\": \\"福建省指挥中心警情受理处置应用系统\\", \\"count\\": 3, \\"datasources\\": [{\\"value\\": \\"4b5d9992d89744b9b514f8905dc27998\\", \\"label\\": \\"出入境人员动管系统数据库\\", \\"count\\": 9}]}]}\\n}",\n  "description": "数据接入左侧树数据表统计（POST /ods/dataAggTreeStatistics）。只读接口；关系库限定已完成登记的数据源，Elasticsearch dataassets 投影提供层级信息并统计可接入数据表（业务表/日志表/字典表）；没有表的数据源统计为 0。与右侧列表使用相同的数据源资格边界；使用请求参数 keyword、orgIds；涉及 db_datasource_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.数据汇聚数据表树统计\n// 路由：POST /ods/dataAggTreeStatistics\n// 业务说明：数据接入左侧树数据表统计（POST /ods/dataAggTreeStatistics）。只读接口；关系库限定已完成登记的数据源，Elasticsearch dataassets 投影提供层级信息并统计可接入数据表（业务表/日志表/字典表）；没有表的数据源统计为 0。与右侧列表使用相同的数据源资格边界；使用请求参数 keyword、orgIds；涉及 db_datasource_t、db_table_t 等业务表。\nimport tenantEs\nimport tenantRuntime\nimport \'@/common/configData\' as configData\n\n/*\n * 数据接入左树统计接口（POST /ods/dataAggTreeStatistics）。\n *\n * 1. 先从关系库取得已完成登记的数据源，再读取对应 ES 数据源投影；\n * 2. 读取同一数据源范围内的 ES table 投影，统计业务表、日志表、字典表数量；\n * 3. 只返回统计与层级结构，不写入 MySQL / ES，右侧列表仍由 /ods/dataAggPage 按相同表口径分页查询。\n */\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]).trim() != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar normalize = (value) => text(value).toLowerCase().replace(\'_\', \'\').replace(\'-\', \'\').replace(\' \', \'\')\nvar safeAssetSearch = (query) => {\n    try {\n        return tenantEs.index(configData().es_dataassets).search(query)\n    } catch (e) {\n        return { hits: { hits: [] } }\n    }\n}\nvar isAccessTableType = (value) => {\n    var v = normalize(value)\n    return v == \'业务表\' || v == \'日志表\' || v == \'字典表\' ||\n        v == \'business\' || v == \'businesstable\' || v == \'log\' || v == \'logtable\' ||\n        v == \'dict\' || v == \'dictionary\' || v == \'dictionarytable\'\n}\nvar addUnique = (list, value) => {\n    var v = text(value)\n    if (!blank(v) && !list.contains(v)) {\n        list.add(v)\n    }\n}\nvar safeName = (value) => {\n    var v = text(value).trim()\n    if (blank(v) || v.startsWith(\'未匹配业务系统\')) {\n        return \'\'\n    }\n    return v\n}\n\n// 统计必须和 /ods/dataAggPage 一样，仅以当前登录租户作为业务数据边界。\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'登录状态已失效，请重新登录\'\n}\n\nvar keyword = text(body?.keyword).trim()\nvar orgIds = body?.orgIds\n\n// 数据源是否已登记以关系库主表为准；ES 仅用于补充检索投影和统计数据表。\n// 树保留已完成登记的数据源节点，即使其中暂时没有右表可展示的接入候选表。\n// 实际计数另以 /ods/dataAggPage 的已登记资产状态作为准入条件。\nvar registeredDatasourceRows = db.table(\'db_datasource_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n    .eq(\'asset_status\', 2).select()\nvar registeredDatasourceIds = []\nvar registeredDatasourceMap = {}\nfor (registeredDatasourceRow in (registeredDatasourceRows == null ? [] : registeredDatasourceRows)) {\n    var registeredDatasourceId = text(first(registeredDatasourceRow, [\'tid\']))\n    if (blank(registeredDatasourceId)) {\n        continue\n    }\n    registeredDatasourceMap[registeredDatasourceId] = registeredDatasourceRow\n    addUnique(registeredDatasourceIds, registeredDatasourceId)\n}\nif (registeredDatasourceIds.size() == 0) {\n    return { total: 0, orgCounts: {}, orgApps: {} }\n}\n\n// 数据源结构优先读取 ES db 投影；没有投影时使用已登记主表兜底，避免树和列表范围不一致。\nvar dbFilters = [\n    { term: { assetType: \'db\' } },\n    { terms: { tid: registeredDatasourceIds } }\n]\nif (orgIds != null && orgIds.size() > 0) {\n    dbFilters.add({ terms: { orgId: orgIds } })\n}\nif (!blank(keyword)) {\n    dbFilters.add({\n        bool: {\n            should: [\n                { wildcard: { dbName: \'*\' + keyword + \'*\' } },\n                { wildcard: { datasourceName: \'*\' + keyword + \'*\' } },\n                { wildcard: { database: \'*\' + keyword + \'*\' } },\n                { wildcard: { schema: \'*\' + keyword + \'*\' } },\n                { wildcard: { appName: \'*\' + keyword + \'*\' } },\n                { wildcard: { applicationName: \'*\' + keyword + \'*\' } },\n                { wildcard: { systemName: \'*\' + keyword + \'*\' } }\n            ],\n            minimum_should_match: 1\n        }\n    })\n}\n\nvar dbSearch = safeAssetSearch({\n    from: 0,\n    size: 10000,\n    track_total_hits: true,\n    query: {\n        bool: {\n            filter: dbFilters,\n            must_not: [\n                { wildcard: { dbName: \'codex_*\' } },\n                { wildcard: { database: \'codex_*\' } }\n            ]\n        }\n    },\n    _source: [\n        \'tid\', \'id\',\n        \'orgId\', \'org_id\',\n        \'appId\', \'app_id\', \'appName\', \'app_name\', \'applicationName\', \'application_name\', \'systemName\',\n        \'datasourceName\', \'datasource_name\', \'dbName\', \'db_name\', \'database\', \'schema\', \'dbType\',\n        \'connectionStatus\', \'connection_status\', \'showConnect\', \'show_connect\', \'assetStatus\', \'asset_status\'\n    ]\n})\n\nvar datasourceMap = {}\nvar datasourceIds = []\nfor (hit in (dbSearch?.hits?.hits == null ? [] : dbSearch.hits.hits)) {\n    var doc = hit?._source\n    if (doc == null) {\n        continue\n    }\n    var datasourceId = text(first(doc, [\'tid\', \'id\']) || hit._id)\n    if (blank(datasourceId)) {\n        continue\n    }\n    doc.tid = datasourceId\n    datasourceMap[datasourceId] = doc\n    addUnique(datasourceIds, datasourceId)\n}\nfor (registeredDatasourceId in registeredDatasourceIds) {\n    if (datasourceMap[registeredDatasourceId] != null) {\n        continue\n    }\n    var registeredDatasource = registeredDatasourceMap[registeredDatasourceId]\n    registeredDatasource.tid = registeredDatasourceId\n    datasourceMap[registeredDatasourceId] = registeredDatasource\n    addUnique(datasourceIds, registeredDatasourceId)\n}\n\n// 左树数量必须与 /ods/dataAggPage 的 table 分支完全同口径：\n// 仅计入当前租户、已完成登记的表资产，以及可创建接入任务的三类业务表。\n// 不能以 ES/物理库的全量表投影计数，否则未登记表会让左树与右表失真。\nvar tableCountsByDatasource = {}\nvar total = 0\nif (datasourceIds.size() > 0) {\n    var registeredTableRows = db.table(\'db_table_t\')\n        .columns(\'tid\', \'datasource_id\', \'business_type\')\n        .where()\n        .in(\'datasource_id\', datasourceIds)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .eq(\'asset_status\', 2)\n        .in(\'business_type\', [\'业务表\', \'日志表\', \'字典表\'])\n        .select()\n    for (registeredTableRow in (registeredTableRows == null ? [] : registeredTableRows)) {\n        var tableDatasourceId = text(first(registeredTableRow, [\'datasourceId\', \'datasource_id\']))\n        if (blank(tableDatasourceId) || datasourceMap[tableDatasourceId] == null) {\n            continue\n        }\n        tableCountsByDatasource[tableDatasourceId] =\n            (tableCountsByDatasource[tableDatasourceId] == null ? 0 : tableCountsByDatasource[tableDatasourceId]) + 1\n        total = total + 1\n    }\n}\n\nvar orgCounts = {}\nvar appMap = {}\nvar datasourceMapForApp = {}\n\n// 按“部门 -> 应用系统 -> 数据源”组装树扩展节点；0 表数据源 count=0 仍保留。\nfor (datasourceId in datasourceIds) {\n    var datasourceDoc = datasourceMap[datasourceId]\n    var orgId = text(first(datasourceDoc, [\'orgId\', \'org_id\']))\n    var appId = text(first(datasourceDoc, [\'appId\', \'app_id\']))\n    var appName = safeName(first(datasourceDoc, [\'appName\', \'app_name\', \'applicationName\', \'application_name\', \'systemName\']))\n    var datasourceName = text(first(datasourceDoc, [\'datasourceName\', \'datasource_name\', \'dbName\', \'db_name\', \'database\', \'schema\']))\n    var datasourceCount = tableCountsByDatasource[datasourceId] == null ? 0 : tableCountsByDatasource[datasourceId]\n\n    if (blank(orgId) || blank(datasourceName)) {\n        continue\n    }\n    if (blank(appId)) {\n        appId = \'unbound-\' + orgId\n    }\n    if (blank(appName)) {\n        appName = \'未绑定业务系统\'\n    }\n\n    orgCounts[orgId] = (orgCounts[orgId] == null ? 0 : orgCounts[orgId]) + datasourceCount\n\n    var appKey = orgId + \'::\' + appId\n    if (appMap[appKey] == null) {\n        appMap[appKey] = {\n            orgId: orgId,\n            value: appId,\n            label: appName,\n            count: 0,\n            type: \'app\',\n            children: [],\n            datasources: []\n        }\n        datasourceMapForApp[appKey] = {}\n    }\n    appMap[appKey].count = appMap[appKey].count + datasourceCount\n\n    datasourceMapForApp[appKey][datasourceId] = {\n        value: datasourceId,\n        label: datasourceName,\n        count: datasourceCount,\n        type: \'datasource\',\n        dbType: text(first(datasourceDoc, [\'dbType\'])),\n        connectionStatus: first(datasourceDoc, [\'connectionStatus\', \'connection_status\']),\n        showConnect: first(datasourceDoc, [\'showConnect\', \'show_connect\']),\n        assetStatus: first(datasourceDoc, [\'assetStatus\', \'asset_status\']),\n        children: []\n    }\n}\n\nvar orgApps = {}\nfor (appKey, app in appMap) {\n    var datasources = []\n    for (datasourceKey, datasource in datasourceMapForApp[appKey]) {\n        datasources.add(datasource)\n    }\n    app.datasources = datasources\n    app.children = datasources\n    if (orgApps[app.orgId] == null) {\n        orgApps[app.orgId] = []\n    }\n    orgApps[app.orgId].add(app)\n}\n\nreturn {\n    total: total,\n    orgCounts: orgCounts,\n    orgApps: orgApps\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/07.数据汇聚数据表树统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_api_pull_dir_01',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/08.API拉取/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_api_pull_sync_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_api_pull_sync_01",\n  "script": null,\n  "groupId": "ods_api_pull_group_01",\n  "name": "01.同步第一步API定义",\n  "path": "/sync",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "API 拉取登记、表规则与 NiFi 任务绑定；不保存明文凭据；使用请求参数 datasourceId。"\n}\n================================\n// 接口：同步第一步 API 定义\n// 业务说明：用户保存 API 数据源后，将第一步定义整理为服务和表级规则草稿；不会创建或启动 NiFi 任务。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nvar datasourceId = body?.datasourceId == null ? \'\' : (\'\' + body.datasourceId).trim()\nif (datasourceId == \'\') { exit 400, \'数据源标识不能为空\' }\n\n// 先由服务端验证数据源归属与接入方式，并解析第一步保存的 API 定义。\nvar definitions = apiPullConfig.definitions(datasourceId)\nvar services = 0\nvar rules = 0\nvar entries = []\n\nfor (item in definitions) {\n    var tableName = item.tableName == null ? \'\' : (\'\' + item.tableName).trim()\n    var tableComment = item.tableComment == null ? \'\' : (\'\' + item.tableComment).trim()\n    var serviceName = item.serviceName == null ? \'\' : (\'\' + item.serviceName).trim()\n    var baseUrl = item.baseUrl == null ? \'\' : (\'\' + item.baseUrl).trim()\n    var endpointPath = item.endpointPath == null ? \'\' : (\'\' + item.endpointPath).trim()\n    if (tableName == \'\') { exit 400, \'API 定义缺少数据表英文名\' }\n    if (tableComment == \'\') { exit 400, \'API 定义缺少数据表中文名\' }\n    if (serviceName == \'\') { exit 400, \'API 定义缺少接口服务名称\' }\n    if (baseUrl == \'\') { exit 400, \'API 定义缺少 Base URL\' }\n    if (endpointPath == \'\') { exit 400, \'API 定义缺少接口路径\' }\n\n    var serviceCode = apiPullConfig.suggestedServiceCode(tableName, serviceName)\n    var existingService = db.selectOne("""\n        SELECT tid\n          FROM data_pull_service_t\n         WHERE tenant_id = #{tenantId}\n           AND datasource_id = #{datasourceId}\n           AND service_code = #{serviceCode}\n           AND is_del = 0\n         LIMIT 1\n    """)\n    var service = {\n        datasourceId: datasourceId,\n        serviceName: serviceName,\n        serviceCode: serviceCode,\n        baseUrl: baseUrl,\n        commonHeadersJson: item.commonHeadersJson,\n        authType: item.authType == null ? \'NONE\' : item.authType,\n        credentialRef: item.credentialRef\n    }\n    if (existingService != null) { service.tid = existingService.tid }\n    var savedService = apiPullConfig.saveService(service)\n    services = services + 1\n\n    // 第二步未登记逻辑表时只保存服务；下次保存会继续补齐表级规则。\n    var table = db.selectOne("""\n        SELECT tid\n          FROM db_table_t\n         WHERE tenant_id = #{tenantId}\n           AND datasource_id = #{datasourceId}\n           AND table_name = #{tableName}\n           AND is_del = 0\n         ORDER BY updated_time DESC, tid\n         LIMIT 1\n    """)\n    var entry = {tableName: tableName, tableComment: tableComment,\n                 serviceId: savedService.tid, ruleReady: table != null}\n    if (table != null) {\n        var tableId = table.tid\n        var existingRule = db.selectOne("""\n            SELECT tid, nifi_task_id, enabled\n              FROM data_pull_rule_t\n             WHERE tenant_id = #{tenantId}\n               AND datasource_id = #{datasourceId}\n               AND source_table_id = #{tableId}\n               AND is_del = 0\n             ORDER BY updated_time DESC, tid\n             LIMIT 1\n        """)\n        var rule = {\n            datasourceId: datasourceId, sourceTableId: tableId,\n            serviceId: savedService.tid, ruleName: tableComment + \'拉取规则\',\n            endpointMethod: item.endpointMethod == null ? \'GET\' : item.endpointMethod,\n            endpointPath: endpointPath,\n            requestTemplateJson: item.requestTemplateJson,\n            responseConfigJson: item.responseConfigJson,\n            paginationConfigJson: item.paginationConfigJson,\n            incrementalConfigJson: item.incrementalConfigJson,\n            runtimeConfigJson: item.runtimeConfigJson,\n            triggerMode: item.triggerMode == null ? \'MANUAL\' : item.triggerMode,\n            cronExpression: item.cronExpression\n        }\n        if (existingRule != null) {\n            rule.tid = existingRule.tid\n            rule.nifiTaskId = existingRule.nifi_task_id\n            rule.enabled = existingRule.enabled\n        }\n        var savedRule = apiPullConfig.saveRule(rule)\n        entry.tableId = tableId\n        entry.ruleId = savedRule.tid\n        rules = rules + 1\n    }\n    entries.add(entry)\n}\n\nreturn {datasourceId: datasourceId, definitions: definitions.size(), services: services,\n        rules: rules, entries: entries,\n        message: rules == definitions.size()\n            ? \'API 服务与表级拉取规则已同步，下一步可创建 NiFi 任务\'\n            : \'API 服务已同步；请在第二步完成相应数据表标注后再次保存，系统会自动生成表级规则\'}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/08.API拉取/01.同步第一步API定义.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_api_pull_bind_task_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_api_pull_bind_task_01",\n  "script": null,\n  "groupId": "ods_api_pull_group_01",\n  "name": "02.绑定NiFi任务",\n  "path": "/bind-task",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "API 拉取登记、表规则与 NiFi 任务绑定；不保存明文凭据；使用请求参数 datasourceId、sourceTableId、pipelineId。"\n}\n================================\n// 接口：绑定 NiFi 任务\n// 业务说明：显式创建接入任务后，把对应 API 表级规则与 NiFi 流程关联；其他类型数据源安全跳过。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nvar datasourceId = body?.datasourceId == null ? \'\' : (\'\' + body.datasourceId).trim()\nvar sourceTableId = body?.sourceTableId == null ? \'\' : (\'\' + body.sourceTableId).trim()\nvar pipelineId = body?.pipelineId == null ? \'\' : (\'\' + body.pipelineId).trim()\nif (datasourceId == \'\') { exit 400, \'数据源标识不能为空\' }\nif (sourceTableId == \'\') { exit 400, \'来源表标识不能为空\' }\nif (pipelineId == \'\') { exit 400, \'NiFi 流程标识不能为空\' }\n\nvar datasource = db.selectOne("""\n    SELECT db_type, pool_cfg\n      FROM db_datasource_t\n     WHERE tid = #{datasourceId}\n       AND tenant_id = #{tenantId}\n       AND is_del = 0\n""")\nif (datasource == null) { exit 400, \'数据源不存在或不属于当前租户\' }\n\n// 只有 API 拉取或采集数据源才存在需要绑定的表级规则。\nvar type = datasource.db_type == null ? \'\' : (\'\' + datasource.db_type).toLowerCase()\nvar pool = datasource.pool_cfg == null ? \'\' : (\'\' + datasource.pool_cfg).replaceAll(\'\\\\s\', \'\').toLowerCase()\nif (type != \'api\' || !(pool.contains(\'"accessmode":"capture"\') || pool.contains(\'"accessmode":"pull"\'))) {\n    return {applicable: false, message: \'当前来源不是 API 数据拉取，未绑定表规则\'}\n}\n\n// 仅维护已保存的规则，不在这里启动调度或创建 NiFi 流程。\napiPullConfig.prepareRuleSchema()\nvar changed = db.update("""\n    UPDATE data_pull_rule_t\n       SET nifi_task_id = #{pipelineId},\n           updated_by = \'system\',\n           updated_time = NOW(6)\n     WHERE tenant_id = #{tenantId}\n       AND datasource_id = #{datasourceId}\n       AND source_table_id = #{sourceTableId}\n       AND is_del = 0\n""")\nreturn {applicable: true, pipelineId: pipelineId, boundRules: changed,\n        message: changed > 0\n            ? \'表级拉取规则已绑定 NiFi 任务；可在画布中部署、手动启动或按 Cron 调度\'\n            : \'当前表尚未同步出 API 拉取规则，请返回第二步保存表标注后重试\'}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/08.API拉取/02.绑定NiFi任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_api_pull_rules_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_api_pull_rules_01",\n  "script": null,\n  "groupId": "ods_api_pull_group_01",\n  "name": "03.表级规则列表",\n  "path": "/rules",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "API 拉取登记、表规则与 NiFi 任务绑定；不保存明文凭据；读取或计算后返回业务结果。"\n}\n================================\n// 接口：API 表级拉取规则列表\n// 业务说明：按当前租户与数据源读取规则；可选择指定逻辑表，不会创建或启动 NiFi 任务。\nimport tenantRuntime\nimport apiPullConfig\n\nvar tenantId = tenantRuntime.id()\nvar sourceId = datasourceId == null ? \'\' : (\'\' + datasourceId).trim()\nif (sourceId == \'\') { exit 400, \'数据源标识不能为空\' }\nvar tableId = sourceTableId == null || (\'\' + sourceTableId).trim() == \'\' ? null : (\'\' + sourceTableId).trim()\napiPullConfig.validateDatasource(sourceId)\n\nreturn db.select("""\n    SELECT tid,\n           datasource_id,\n           source_table_id,\n           service_id,\n           rule_name,\n           endpoint_method,\n           endpoint_path,\n           request_template_json,\n           response_config_json,\n           pagination_config_json,\n           incremental_config_json,\n           orchestration_config_json,\n           mapping_config_json,\n           quality_config_json,\n           delete_config_json,\n           runtime_config_json,\n           trigger_mode,\n           cron_expression,\n           nifi_task_id,\n           enabled,\n           created_time,\n           updated_time\n      FROM data_pull_rule_t\n     WHERE tenant_id = #{tenantId}\n       AND datasource_id = #{sourceId}\n       AND (#{tableId} IS NULL OR source_table_id = #{tableId})\n       AND is_del = 0\n     ORDER BY updated_time DESC, tid\n""")\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/08.API拉取/03.表级规则列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_api_pull_group_01',NULL,NULL,'{\n  "properties" : { },\n  "id" : "ods_api_pull_group_01",\n  "name" : "08.API拉取",\n  "type" : "api",\n  "parentId" : "1f4028f20aaa4f379b5e37a343b99fa9",\n  "path" : "/api-pull",\n  "createTime" : 1789106804607,\n  "updateTime" : 1789106804607\n}',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/08.API拉取/group.json');
