\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            },\\n            {\\n                \\"tid\\": \\"4f0b3252e2b241d093774abcc2a9c035\\",\\n                \\"tableId\\": \\"e622254f6307419781a2bdc43a2a1d49\\",\\n                \\"columnName\\": \\"risk_level\\",\\n                \\"columnComment\\": \\"风险等级\\",\\n                \\"dataType\\": \\"varchar\\",\\n                \\"columnType\\": \\"varchar(20)\\",\\n                \\"length\\": 20,\\n                \\"precisionLength\\": 0,\\n                \\"scale\\": 0,\\n                \\"nullable\\": 0,\\n                \\"defaultValue\\": null,\\n                \\"primaryKey\\": 0,\\n                \\"autoIncrement\\": 0,\\n                \\"isUnique\\": 0,\\n                \\"indexed\\": 0,\\n                \\"ordinalPosition\\": 8,\\n                \\"charset\\": \\"utf8mb4\\",\\n                \\"collation\\": \\"utf8mb4_0900_ai_ci\\",\\n                \\"extra\\": null,\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": null,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"isDel\\": 0,\\n                \\"isMasking\\": null,\\n                \\"dataCatalogItemId\\": null,\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            },\\n            {\\n                \\"tid\\": \\"2b882785e9c14281a4ba7e1c6611ff92\\",\\n                \\"tableId\\": \\"e622254f6307419781a2bdc43a2a1d49\\",\\n                \\"columnName\\": \\"last_activity_time\\",\\n                \\"columnComment\\": \\"最后活动时间\\",\\n                \\"dataType\\": \\"datetime\\",\\n                \\"columnType\\": \\"datetime\\",\\n                \\"length\\": 0,\\n                \\"precisionLength\\": 0,\\n                \\"scale\\": 0,\\n                \\"nullable\\": 0,\\n                \\"defaultValue\\": null,\\n                \\"primaryKey\\": 0,\\n                \\"autoIncrement\\": 0,\\n                \\"isUnique\\": 0,\\n                \\"indexed\\": 0,\\n                \\"ordinalPosition\\": 9,\\n                \\"charset\\": null,\\n                \\"collation\\": null,\\n                \\"extra\\": null,\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": null,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"isDel\\": 0,\\n                \\"isMasking\\": null,\\n                \\"dataCatalogItemId\\": null,\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            },\\n            {\\n                \\"tid\\": \\"9ef53bb607364261b9873d84341619c8\\",\\n                \\"tableId\\": \\"e622254f6307419781a2bdc43a2a1d49\\",\\n                \\"columnName\\": \\"is_del\\",\\n                \\"columnComment\\": \\"删除标记（0-未删除，1-已删除）\\",\\n                \\"dataType\\": \\"tinyint\\",\\n                \\"columnType\\": \\"tinyint\\",\\n                \\"length\\": 0,\\n                \\"precisionLength\\": 3,\\n                \\"scale\\": 0,\\n                \\"nullable\\": 0,\\n                \\"defaultValue\\": \\"0\\",\\n                \\"primaryKey\\": 0,\\n                \\"autoIncrement\\": 0,\\n                \\"isUnique\\": 0,\\n                \\"indexed\\": 0,\\n                \\"ordinalPosition\\": 10,\\n                \\"charset\\": null,\\n                \\"collation\\": null,\\n                \\"extra\\": null,\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": null,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"isDel\\": 0,\\n                \\"isMasking\\": null,\\n                \\"dataCatalogItemId\\": null,\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            },\\n            {\\n                \\"tid\\": \\"e2b5bde127474df083c9a033bc2695c5\\",\\n                \\"tableId\\": \\"e622254f6307419781a2bdc43a2a1d49\\",\\n                \\"columnName\\": \\"create_time\\",\\n                \\"columnComment\\": \\"创建时间\\",\\n                \\"dataType\\": \\"datetime\\",\\n                \\"columnType\\": \\"datetime\\",\\n                \\"length\\": 0,\\n                \\"precisionLength\\": 0,\\n                \\"scale\\": 0,\\n                \\"nullable\\": 0,\\n                \\"defaultValue\\": \\"CURRENT_TIMESTAMP\\",\\n                \\"primaryKey\\": 0,\\n                \\"autoIncrement\\": 0,\\n                \\"isUnique\\": 0,\\n                \\"indexed\\": 0,\\n                \\"ordinalPosition\\": 11,\\n                \\"charset\\": null,\\n                \\"collation\\": null,\\n                \\"extra\\": \\"DEFAULT_GENERATED\\",\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": null,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"isDel\\": 0,\\n                \\"isMasking\\": null,\\n                \\"dataCatalogItemId\\": null,\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            },\\n            {\\n                \\"tid\\": \\"70575af097dc4589ad7b33d5f0828d9a\\",\\n                \\"tableId\\": \\"e622254f6307419781a2bdc43a2a1d49\\",\\n                \\"columnName\\": \\"update_time\\",\\n                \\"columnComment\\": \\"更新时间\\",\\n                \\"dataType\\": \\"datetime\\",\\n                \\"columnType\\": \\"datetime\\",\\n                \\"length\\": 0,\\n                \\"precisionLength\\": 0,\\n                \\"scale\\": 0,\\n                \\"nullable\\": 0,\\n                \\"defaultValue\\": \\"CURRENT_TIMESTAMP\\",\\n                \\"primaryKey\\": 0,\\n                \\"autoIncrement\\": 0,\\n                \\"isUnique\\": 0,\\n                \\"indexed\\": 0,\\n                \\"ordinalPosition\\": 12,\\n                \\"charset\\": null,\\n                \\"collation\\": null,\\n                \\"extra\\": \\"DEFAULT_GENERATED on update CURRENT_TIMESTAMP\\",\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdBy\\": null,\\n                \\"createdTime\\": null,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"isDel\\": 0,\\n                \\"isMasking\\": null,\\n                \\"dataCatalogItemId\\": null,\\n                \\"dictId\\": null,\\n                \\"dataCatalogItemMountId\\": null\\n            }\\n        ]\\n    }\\n}",\n  "description": "目录目标表 ID 从 ES 目录投影读取；表和字段详情以 db_table_t、；使用请求参数 tid。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.查询目标信息\n// 路由：POST /ods/queryTargetTableInfo\n// 业务说明：目录目标表 ID 从 ES 目录投影读取；表和字段详情以 db_table_t、；使用请求参数 tid。\n/*\n * 查询资源目录已配置的目标表\n *\n * 目录目标表 ID 从 ES 目录投影读取；表和字段详情以 db_table_t、\n * db_table_column_t 为准，确保迁移后的物理主表是唯一事实来源。\n */\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\n\n// 解析请求体并为可选参数设置默认值。\nvar catalogId = body?.tid\nif (catalogId == null || catalogId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tid参数错误\'\n}\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar catalog = esCommonService.getDocument(\'dataassets\', catalogId + \'\')\nvar tableId = catalog?.targetTableId\nif (tableId == null || tableId == \'\') {\n    // 返回当前业务分支的标准结果。\n    return {propList: {}, tableItems: []}\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar table = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (table == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'目标表不存在\'\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar datasource = db.table(\'db_datasource_t\').where()\n    .eq(\'tid\', table.datasourceId).eq(\'is_del\', 0).selectOne()\n// 返回当前业务分支的标准结果。\nreturn {\n    propList: {\n        dbId: table.datasourceId,\n        dbType: datasource?.dbType,\n        tableNameCn: table.tableNameCn,\n        tableName: table.tableName\n    },\n    // 从 MySQL 业务表读取当前有效数据。\n    tableItems: db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', tableId).eq(\'is_del\', 0)\n        .orderBy(\'ordinal_position\', \'asc\').select()\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/08.查询目标信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1f475a245fda4ba4a885b3ac4f8e2d59','1f475a245fda4ba4a885b3ac4f8e2d59','api','{\n  "properties": {},\n  "id": "1f475a245fda4ba4a885b3ac4f8e2d59",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "09.Hive原始库数据表分页接口",\n  "createTime": 1790091177940,\n  "updateTime": 1790093531015,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/hiveTargetPage",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "Hive原始库数据表分页（POST /ods/hiveTargetPage）。只读；以OB阶段已物化的目标表为Hive新来源表，只关联Hive阶段新建的任务和目标表；使用请求参数 pageNum、pageSize、keyword、accessStatus、datasourceIds、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.Hive原始库数据表分页接口\n// 路由：POST /ods/hiveTargetPage\n// 业务说明：Hive原始库数据表分页（POST /ods/hiveTargetPage）。只读；以OB阶段已物化的目标表为Hive新来源表，只关联Hive阶段新建的任务和目标表；使用请求参数 pageNum、pageSize、keyword、accessStatus、datasourceIds、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表。\n// Hive 原始库数据表分页：只读。OB 物化目标表在此阶段成为来源表，只返回第二阶段任务与目标表。\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => text(value).trim() == \'\'\nvar first = (row, keys) => { for (key in keys) { if (row != null && row[key] != null && text(row[key]) != \'\') { return row[key] } } return null }\nvar taskStatusText = (value) => {\n  var status = text(value)\n  if (status == \'0\') { return \'待运行\' }\n  if (status == \'1\') { return \'运行中\' }\n  if (status == \'2\') { return \'停止\' }\n  if (status == \'3\') { return \'执行失败\' }\n  if (status == \'4\') { return \'执行成功\' }\n  return blank(status) ? \'未配置任务\' : status\n}\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) { exit 401, \'登录状态已失效，请重新登录\' }\n\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\nvar keyword = text(body?.keyword).trim().toLowerCase()\nvar accessStatus = text(body?.accessStatus)\nvar requestedDatasourceIds = body?.datasourceIds == null ? [] : body.datasourceIds\nvar requestedDatasourceId = text(body?.datasourceId)\nif (!blank(requestedDatasourceId) && !requestedDatasourceIds.contains(requestedDatasourceId)) { requestedDatasourceIds.add(requestedDatasourceId) }\n\nvar rows = db.table(\'db_table_t\').where()\n  .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n  .ne(\'source_table_id\', \'\').orderBy(\'updated_time\', \'desc\').select()\nvar targetRows = []\nvar targetIds = []\nvar sourceIds = []\nvar datasourceIds = []\nfor (row in (rows == null ? [] : rows)) {\n  var targetId = text(row.tid)\n  var sourceId = text(row.sourceTableId || row.source_table_id)\n  var datasourceId = text(row.datasourceId || row.datasource_id)\n  if (blank(targetId) || blank(sourceId) || targetId == sourceId || blank(datasourceId)) { continue }\n  targetRows.add(row); targetIds.add(targetId)\n  if (!sourceIds.contains(sourceId)) { sourceIds.add(sourceId) }\n  if (!datasourceIds.contains(datasourceId)) { datasourceIds.add(datasourceId) }\n}\n\nvar sourceTableMap = {}\nif (sourceIds.size() > 0) {\n  var sourceRows = db.table(\'db_table_t\').where().in(\'tid\', sourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (sourceRow in (sourceRows == null ? [] : sourceRows)) { sourceTableMap[text(sourceRow.tid)] = sourceRow }\n}\nvar datasourceMap = {}\nif (datasourceIds.size() > 0) {\n  var datasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', datasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (datasource in (datasourceRows == null ? [] : datasourceRows)) { datasourceMap[text(datasource.tid)] = datasource }\n}\nvar sourceDatasourceIds = []\nfor (sourceId in sourceIds) {\n  var originalSource = sourceTableMap[sourceId]\n  if (originalSource != null) {\n    var originalDatasourceId = text(originalSource.datasourceId || originalSource.datasource_id)\n    if (!blank(originalDatasourceId) && !sourceDatasourceIds.contains(originalDatasourceId)) { sourceDatasourceIds.add(originalDatasourceId) }\n  }\n}\nvar sourceDatasourceMap = {}\nif (sourceDatasourceIds.size() > 0) {\n  var sourceDatasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', sourceDatasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (sourceDatasource in (sourceDatasourceRows == null ? [] : sourceDatasourceRows)) { sourceDatasourceMap[text(sourceDatasource.tid)] = sourceDatasource }\n}\n\n// Hive 阶段任务以“OB 目标表”为 source_table_id；不能按 target_table_id 查询，否则会继承 OB 阶段任务。\nvar tasksBySource = {}\nif (targetIds.size() > 0) {\n  var taskRows = db.table(\'data_access_agg_task_t\').where().in(\'source_table_id\', targetIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).orderBy(\'updated_time\', \'desc\').select()\n  for (task in (taskRows == null ? [] : taskRows)) {\n    var hiveSourceId = text(task.sourceTableId || task.source_table_id)\n    if (blank(hiveSourceId)) { continue }\n    if (tasksBySource[hiveSourceId] == null) { tasksBySource[hiveSourceId] = [] }\n    tasksBySource[hiveSourceId].add(task)\n  }\n}\n\n// 已经由 Hive 阶段物化出来的下一跳目标表，同样以 source_table_id 关联当前行。\nvar nextTargetsBySource = {}\nvar nextTargetIds = []\nvar nextTargetDatasourceIds = []\nif (targetIds.size() > 0) {\n  var nextRows = db.table(\'db_table_t\').where().in(\'source_table_id\', targetIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (nextTarget in (nextRows == null ? [] : nextRows)) {\n    var nextTargetId = text(nextTarget.tid)\n    var hiveSourceId = text(nextTarget.sourceTableId || nextTarget.source_table_id)\n    if (blank(nextTargetId) || blank(hiveSourceId) || nextTargetId == hiveSourceId) { continue }\n    if (nextTargetsBySource[hiveSourceId] == null) { nextTargetsBySource[hiveSourceId] = [] }\n    nextTargetsBySource[hiveSourceId].add(nextTarget)\n    nextTargetIds.add(nextTargetId)\n    var nextDatasourceId = text(nextTarget.datasourceId || nextTarget.datasource_id)\n    if (!blank(nextDatasourceId) && !nextTargetDatasourceIds.contains(nextDatasourceId)) { nextTargetDatasourceIds.add(nextDatasourceId) }\n  }\n}\nvar nextTargetDatasourceMap = {}\nif (nextTargetDatasourceIds.size() > 0) {\n  var nextDatasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', nextTargetDatasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (nextDatasource in (nextDatasourceRows == null ? [] : nextDatasourceRows)) { nextTargetDatasourceMap[text(nextDatasource.tid)] = nextDatasource }\n}\n\nvar candidates = []\nfor (target in targetRows) {\n  var targetId = text(target.tid)\n  var sourceId = text(target.sourceTableId || target.source_table_id)\n  var source = sourceTableMap[sourceId]\n  var datasourceId = text(target.datasourceId || target.datasource_id)\n  var datasource = datasourceMap[datasourceId]\n  // 只有来源记录和目标库均存在，才能证明它是可追溯的物化产物。\n  if (source == null || datasource == null) { continue }\n  var originalDatasourceId = text(source.datasourceId || source.datasource_id)\n  if (requestedDatasourceIds.size() > 0 && !requestedDatasourceIds.contains(originalDatasourceId)) { continue }\n  var displayName = text(first(target, [\'tableNameCn\',\'table_name_cn\',\'tableComment\',\'table_comment\',\'tableName\',\'table_name\']))\n  var physicalName = text(first(target, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']))\n  var sourceName = text(first(source, [\'tableNameCn\',\'table_name_cn\',\'tableComment\',\'table_comment\',\'tableName\',\'table_name\']))\n  if (!blank(keyword) && !((displayName + \' \' + physicalName + \' \' + sourceName).toLowerCase().contains(keyword))) { continue }\n  var taskRows = tasksBySource[targetId] == null ? [] : tasksBySource[targetId]\n  if (accessStatus == \'0\' && taskRows.size() > 0) { continue }\n  if (accessStatus == \'1\' && taskRows.size() == 0) { continue }\n  var nextTargetRows = nextTargetsBySource[targetId] == null ? [] : nextTargetsBySource[targetId]\n  var targetTables = []\n  for (nextTarget in nextTargetRows) {\n    var nextDatasourceId = text(nextTarget.datasourceId || nextTarget.datasource_id)\n    var nextDatasource = nextTargetDatasourceMap[nextDatasourceId]\n    targetTables.add({\n      targetTableId: text(nextTarget.tid), targetTableName: first(nextTarget, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']),\n      targetDbId: nextDatasourceId, targetDbName: nextDatasource == null ? nextDatasourceId : (nextDatasource.dbName || nextDatasource.db_name),\n      targetDbType: nextDatasource == null ? \'\' : (nextDatasource.dbType || nextDatasource.db_type)\n    })\n  }\n  var tasks = []\n  for (task in taskRows) { tasks.add({\n    tid: task.tid, taskName: task.taskName || task.task_name || \'接入任务\', sourceTableId: targetId,\n    targetTableId: text(task.targetTableId || task.target_table_id), targetTableName: \'\', targetDbId: \'\', targetDbName: \'\', targetDbType: \'\',\n    scheduleCycle: task.scheduleCycle || task.schedule_cycle, lastRunning: task.endRunning || task.end_running || task.lastRunning || task.last_running,\n    taskStatus: task.taskStatus || task.task_status, taskStatusText: taskStatusText(task.taskStatus || task.task_status)\n  }) }\n  for (taskItem in tasks) {\n    for (targetTable in targetTables) {\n      if (taskItem.targetTableId == targetTable.targetTableId) {\n        taskItem.targetTableName = targetTable.targetTableName; taskItem.targetDbId = targetTable.targetDbId\n        taskItem.targetDbName = targetTable.targetDbName; taskItem.targetDbType = targetTable.targetDbType\n      }\n    }\n  }\n  candidates.add({\n    tid: targetId, targetTableId: targetTables.size() > 0 ? targetTables[0].targetTableId : \'\', tableId: targetId,\n    hiveCatalogId: nextTargetRows.size() > 0 ? text(nextTargetRows[0].sourceCatalogId || nextTargetRows[0].source_catalog_id) : \'\',\n    tableName: physicalName, tableNameCn: displayName, tableComment: first(target, [\'tableComment\',\'table_comment\']),\n    businessType: first(target, [\'businessType\',\'business_type\']), tableType: first(target, [\'tableType\',\'table_type\']),\n    datasourceId: datasourceId, dbId: datasourceId, datasourceName: datasource.dbName || datasource.db_name,\n    dbName: datasource.dbName || datasource.db_name, targetDbId: datasourceId, targetDbName: datasource.dbName || datasource.db_name,\n    targetDbType: datasource.dbType || datasource.db_type, sourceTableId: targetId, previousSourceTableId: sourceId,\n    sourceTableName: first(source, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']),\n    sourceTableNameCn: sourceName, sourceDatasourceId: originalDatasourceId,\n    createdTime: first(target, [\'createdTime\',\'created_time\']), updatedTime: first(target, [\'updatedTime\',\'updated_time\']),\n    dataCount: first(target, [\'recordCount\',\'record_count\']), fieldCount: first(target, [\'fieldCount\',\'field_count\']),\n    tasks: tasks, taskCount: tasks.size(), accessTaskId: tasks.size() > 0 ? tasks[0].tid : \'\',\n    accessStatusText: tasks.size() > 0 ? \'已接入\' : \'待接入\',\n    targetTables: targetTables\n  })\n}\nvar total = candidates.size()\nvar start = (pageNum - 1) * pageSize\nvar list = []\nvar itemIndex = 0\nfor (candidate in candidates) {\n  if (itemIndex >= start && list.size() < pageSize) { list.add(candidate) }\n  itemIndex = itemIndex + 1\n}\nreturn { pageNum: pageNum, pageSize: pageSize, total: total, list: list }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/09.Hive原始库数据表分页接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1f475a245fda4ba4a885b3ac4f8e2d59','1f475a245fda4ba4a885b3ac4f8e2d59','api','{\n  "properties": {},\n  "id": "1f475a245fda4ba4a885b3ac4f8e2d59",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "10.Hive原始库数据表分页接口",\n  "path": "/hiveTargetPage",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "Hive原始库数据表分页（POST /ods/hiveTargetPage）。只读；以OB阶段已物化的目标表为Hive新来源表，只关联Hive阶段新建的任务和目标表；使用请求参数 pageNum、pageSize、keyword、accessStatus、datasourceIds、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.Hive原始库数据表分页接口\n// 路由：POST /ods/hiveTargetPage\n// 业务说明：Hive原始库数据表分页（POST /ods/hiveTargetPage）。只读；以OB阶段已物化的目标表为Hive新来源表，只关联Hive阶段新建的任务和目标表；使用请求参数 pageNum、pageSize、keyword、accessStatus、datasourceIds、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表。\n// Hive 原始库数据表分页：只读。OB 物化目标表在此阶段成为来源表，只返回第二阶段任务与目标表。\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => text(value).trim() == \'\'\nvar first = (row, keys) => { for (key in keys) { if (row != null && row[key] != null && text(row[key]) != \'\') { return row[key] } } return null }\nvar taskStatusText = (value) => {\n  var status = text(value)\n  if (status == \'0\') { return \'待运行\' }\n  if (status == \'1\') { return \'运行中\' }\n  if (status == \'2\') { return \'停止\' }\n  if (status == \'3\') { return \'执行失败\' }\n  if (status == \'4\') { return \'执行成功\' }\n  return blank(status) ? \'未配置任务\' : status\n}\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) { exit 401, \'登录状态已失效，请重新登录\' }\n\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int\nvar keyword = text(body?.keyword).trim().toLowerCase()\nvar accessStatus = text(body?.accessStatus)\nvar requestedDatasourceIds = body?.datasourceIds == null ? [] : body.datasourceIds\nvar requestedDatasourceId = text(body?.datasourceId)\nif (!blank(requestedDatasourceId) && !requestedDatasourceIds.contains(requestedDatasourceId)) { requestedDatasourceIds.add(requestedDatasourceId) }\n\nvar rows = db.table(\'db_table_t\').where()\n  .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n  .ne(\'source_table_id\', \'\').orderBy(\'updated_time\', \'desc\').select()\nvar targetRows = []\nvar targetIds = []\nvar sourceIds = []\nvar datasourceIds = []\nfor (row in (rows == null ? [] : rows)) {\n  var targetId = text(row.tid)\n  var sourceId = text(row.sourceTableId || row.source_table_id)\n  var datasourceId = text(row.datasourceId || row.datasource_id)\n  if (blank(targetId) || blank(sourceId) || targetId == sourceId || blank(datasourceId)) { continue }\n  targetRows.add(row); targetIds.add(targetId)\n  if (!sourceIds.contains(sourceId)) { sourceIds.add(sourceId) }\n  if (!datasourceIds.contains(datasourceId)) { datasourceIds.add(datasourceId) }\n}\n\nvar sourceTableMap = {}\nif (sourceIds.size() > 0) {\n  var sourceRows = db.table(\'db_table_t\').where().in(\'tid\', sourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (sourceRow in (sourceRows == null ? [] : sourceRows)) { sourceTableMap[text(sourceRow.tid)] = sourceRow }\n}\nvar datasourceMap = {}\nif (datasourceIds.size() > 0) {\n  var datasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', datasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (datasource in (datasourceRows == null ? [] : datasourceRows)) { datasourceMap[text(datasource.tid)] = datasource }\n}\nvar sourceDatasourceIds = []\nfor (sourceId in sourceIds) {\n  var originalSource = sourceTableMap[sourceId]\n  if (originalSource != null) {\n    var originalDatasourceId = text(originalSource.datasourceId || originalSource.datasource_id)\n    if (!blank(originalDatasourceId) && !sourceDatasourceIds.contains(originalDatasourceId)) { sourceDatasourceIds.add(originalDatasourceId) }\n  }\n}\nvar sourceDatasourceMap = {}\nif (sourceDatasourceIds.size() > 0) {\n  var sourceDatasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', sourceDatasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (sourceDatasource in (sourceDatasourceRows == null ? [] : sourceDatasourceRows)) { sourceDatasourceMap[text(sourceDatasource.tid)] = sourceDatasource }\n}\n\n// Hive 阶段任务以“OB 目标表”为 source_table_id；不能按 target_table_id 查询，否则会继承 OB 阶段任务。\nvar tasksBySource = {}\nif (targetIds.size() > 0) {\n  var taskRows = db.table(\'data_access_agg_task_t\').where().in(\'source_table_id\', targetIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).orderBy(\'updated_time\', \'desc\').select()\n  for (task in (taskRows == null ? [] : taskRows)) {\n    var hiveSourceId = text(task.sourceTableId || task.source_table_id)\n    if (blank(hiveSourceId)) { continue }\n    if (tasksBySource[hiveSourceId] == null) { tasksBySource[hiveSourceId] = [] }\n    tasksBySource[hiveSourceId].add(task)\n  }\n}\n\n// 已经由 Hive 阶段物化出来的下一跳目标表，同样以 source_table_id 关联当前行。\nvar nextTargetsBySource = {}\nvar nextTargetIds = []\nvar nextTargetDatasourceIds = []\nif (targetIds.size() > 0) {\n  var nextRows = db.table(\'db_table_t\').where().in(\'source_table_id\', targetIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (nextTarget in (nextRows == null ? [] : nextRows)) {\n    var nextTargetId = text(nextTarget.tid)\n    var hiveSourceId = text(nextTarget.sourceTableId || nextTarget.source_table_id)\n    if (blank(nextTargetId) || blank(hiveSourceId) || nextTargetId == hiveSourceId) { continue }\n    if (nextTargetsBySource[hiveSourceId] == null) { nextTargetsBySource[hiveSourceId] = [] }\n    nextTargetsBySource[hiveSourceId].add(nextTarget)\n    nextTargetIds.add(nextTargetId)\n    var nextDatasourceId = text(nextTarget.datasourceId || nextTarget.datasource_id)\n    if (!blank(nextDatasourceId) && !nextTargetDatasourceIds.contains(nextDatasourceId)) { nextTargetDatasourceIds.add(nextDatasourceId) }\n  }\n}\nvar nextTargetDatasourceMap = {}\nif (nextTargetDatasourceIds.size() > 0) {\n  var nextDatasourceRows = db.table(\'db_datasource_t\').where().in(\'tid\', nextTargetDatasourceIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n  for (nextDatasource in (nextDatasourceRows == null ? [] : nextDatasourceRows)) { nextTargetDatasourceMap[text(nextDatasource.tid)] = nextDatasource }\n}\n\nvar candidates = []\nfor (target in targetRows) {\n  var targetId = text(target.tid)\n  var sourceId = text(target.sourceTableId || target.source_table_id)\n  var source = sourceTableMap[sourceId]\n  var datasourceId = text(target.datasourceId || target.datasource_id)\n  var datasource = datasourceMap[datasourceId]\n  // 只有来源记录和目标库均存在，才能证明它是可追溯的物化产物。\n  if (source == null || datasource == null) { continue }\n  var originalDatasourceId = text(source.datasourceId || source.datasource_id)\n  if (requestedDatasourceIds.size() > 0 && !requestedDatasourceIds.contains(originalDatasourceId)) { continue }\n  var displayName = text(first(target, [\'tableNameCn\',\'table_name_cn\',\'tableComment\',\'table_comment\',\'tableName\',\'table_name\']))\n  var physicalName = text(first(target, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']))\n  var sourceName = text(first(source, [\'tableNameCn\',\'table_name_cn\',\'tableComment\',\'table_comment\',\'tableName\',\'table_name\']))\n  if (!blank(keyword) && !((displayName + \' \' + physicalName + \' \' + sourceName).toLowerCase().contains(keyword))) { continue }\n  var taskRows = tasksBySource[targetId] == null ? [] : tasksBySource[targetId]\n  if (accessStatus == \'0\' && taskRows.size() > 0) { continue }\n  if (accessStatus == \'1\' && taskRows.size() == 0) { continue }\n  var nextTargetRows = nextTargetsBySource[targetId] == null ? [] : nextTargetsBySource[targetId]\n  var targetTables = []\n  for (nextTarget in nextTargetRows) {\n    var nextDatasourceId = text(nextTarget.datasourceId || nextTarget.datasource_id)\n    var nextDatasource = nextTargetDatasourceMap[nextDatasourceId]\n    targetTables.add({\n      targetTableId: text(nextTarget.tid), targetTableName: first(nextTarget, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']),\n      targetDbId: nextDatasourceId, targetDbName: nextDatasource == null ? nextDatasourceId : (nextDatasource.dbName || nextDatasource.db_name),\n      targetDbType: nextDatasource == null ? \'\' : (nextDatasource.dbType || nextDatasource.db_type)\n    })\n  }\n  var tasks = []\n  for (task in taskRows) { tasks.add({\n    tid: task.tid, taskName: task.taskName || task.task_name || \'接入任务\', sourceTableId: targetId,\n    targetTableId: text(task.targetTableId || task.target_table_id), targetTableName: \'\', targetDbId: \'\', targetDbName: \'\', targetDbType: \'\',\n    scheduleCycle: task.scheduleCycle || task.schedule_cycle, lastRunning: task.endRunning || task.end_running || task.lastRunning || task.last_running,\n    taskStatus: task.taskStatus || task.task_status, taskStatusText: taskStatusText(task.taskStatus || task.task_status)\n  }) }\n  for (taskItem in tasks) {\n    for (targetTable in targetTables) {\n      if (taskItem.targetTableId == targetTable.targetTableId) {\n        taskItem.targetTableName = targetTable.targetTableName; taskItem.targetDbId = targetTable.targetDbId\n        taskItem.targetDbName = targetTable.targetDbName; taskItem.targetDbType = targetTable.targetDbType\n      }\n    }\n  }\n  candidates.add({\n    tid: targetId, targetTableId: targetTables.size() > 0 ? targetTables[0].targetTableId : \'\', tableId: targetId,\n    hiveCatalogId: nextTargetRows.size() > 0 ? text(nextTargetRows[0].sourceCatalogId || nextTargetRows[0].source_catalog_id) : \'\',\n    tableName: physicalName, tableNameCn: displayName, tableComment: first(target, [\'tableComment\',\'table_comment\']),\n    businessType: first(target, [\'businessType\',\'business_type\']), tableType: first(target, [\'tableType\',\'table_type\']),\n    datasourceId: datasourceId, dbId: datasourceId, datasourceName: datasource.dbName || datasource.db_name,\n    dbName: datasource.dbName || datasource.db_name, targetDbId: datasourceId, targetDbName: datasource.dbName || datasource.db_name,\n    targetDbType: datasource.dbType || datasource.db_type, sourceTableId: targetId, previousSourceTableId: sourceId,\n    sourceTableName: first(source, [\'tableName\',\'table_name\',\'tableNameEn\',\'table_name_en\']),\n    sourceTableNameCn: sourceName, sourceDatasourceId: originalDatasourceId,\n    createdTime: first(target, [\'createdTime\',\'created_time\']), updatedTime: first(target, [\'updatedTime\',\'updated_time\']),\n    dataCount: first(target, [\'recordCount\',\'record_count\']), fieldCount: first(target, [\'fieldCount\',\'field_count\']),\n    tasks: tasks, taskCount: tasks.size(), accessTaskId: tasks.size() > 0 ? tasks[0].tid : \'\',\n    accessStatusText: tasks.size() > 0 ? \'已接入\' : \'待接入\',\n    targetTables: targetTables\n  })\n}\nvar total = candidates.size()\nvar start = (pageNum - 1) * pageSize\nvar list = []\nvar itemIndex = 0\nfor (candidate in candidates) {\n  if (itemIndex >= start && list.size() < pageSize) { list.add(candidate) }\n  itemIndex = itemIndex + 1\n}\nreturn { pageNum: pageNum, pageSize: pageSize, total: total, list: list }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/10.Hive原始库数据表分页接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f93a8e653ac6413e89660f5d77d45769',NULL,NULL,'{\n  "properties": {},\n  "id": "f93a8e653ac6413e89660f5d77d45769",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "11.根据表或目录获取建表申请模板",\n  "createTime": 1782955344746,\n  "updateTime": 1788451429685,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getTableTempalte",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"015c09572d174e89b9bea9c765ef72df\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"propList\\": {\\n    \\"sourceTableId\\": \\"015c09572d174e89b9bea9c765ef72df\\",\\n    \\"dbId\\": \\"648b94f1a6a745a3a36149a8788f36f3\\",\\n    \\"nodeId\\": \\"数据中心节点ID\\",\\n    \\"dbType\\": \\"mysql\\",\\n    \\"tableNameCn\\": \\"公安重新探查新增线索表\\",\\n    \\"tableName\\": \\"police_reexplore_new_case_clue\\"\\n  },\\n  \\"tableItems\\": [\\n    {\\n      \\"columnName\\": \\"clue_id\\",\\n      \\"columnComment\\": \\"线索编号\\",\\n      \\"dataType\\": \\"varchar\\",\\n      \\"length\\": 32,\\n      \\"primaryKey\\": 1,\\n      \\"nullable\\": 0\\n    }\\n  ]\\n}",\n  "description": "根据来源数据表或已登记目录获取物化建表模板（POST /ods/getTableTempalte）。只读接口；优先兼容旧目录 da_prop_t.sourceTableId，再直接读取 db_table_t/db_table_column_t，并以第四步 field_governance_config 中已登记的主键为默认主键；默认目标数据源优先读取已启用、数据组织为数据中心且数据源类型为 ODS 的首条数据源，旧资源中心 ODS 分层关联仅作为兼容回退。不依赖 ES，避免 ES 临时不可用导致建表弹框为空。用于数据接入-创建任务前的物化建表抽屉；使用请求参数 tid。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.根据表或目录获取建表申请模板\n// 路由：POST /ods/getTableTempalte\n// 业务说明：根据来源数据表或已登记目录获取物化建表模板（POST /ods/getTableTempalte）。只读接口；优先兼容旧目录 da_prop_t.sourceTableId，再直接读取 db_table_t/db_table_column_t，并以第四步 field_governance_config 中已登记的主键为默认主键；默认目标数据源优先读取已启用、数据组织为数据中心且数据源类型为 ODS 的首条数据源，旧资源中心 ODS 分层关联仅作为兼容回退。不依赖 ES，避免 ES 临时不可用导致建表弹框为空。用于数据接入-创建任务前的物化建表抽屉；使用请求参数 tid。\n/*\n * 物化建表模板读取接口。\n * - 入参 tid 可以是 db_table_t.tid，也可以是旧目录 ID；\n * - 不再把 ES 作为必经链路，ES 不可用时也必须能从 MySQL 主表读取来源表和字段；\n * - 目标数据源默认使用 dataSourceType 字典下贴源层 ODS 分域已关联的数据源。\n */\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport tenantRuntime\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]).trim() != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar toInt = (value, defaultValue) => {\n    if (blank(value)) {\n        return defaultValue\n    }\n    return value::int\n}\nvar lower = (value) => blank(value) ? \'\' : text(value).toLowerCase()\nvar isPrimaryKey = (value) => {\n    var normalized = text(value).trim().toLowerCase()\n    return normalized == \'1\' || normalized == \'true\' || normalized == \'yes\'\n}\n\nvar inputId = text(body?.tid).trim()\nif (blank(inputId)) {\n    exit 400, \'tid不能为空\'\n}\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'当前登录上下文无效，请重新登录\'\n}\n\n// 兼容旧链路：如果传入的是目录 ID，则从 da_prop_t.sourceTableId 找来源表。\nvar catalogId = \'\'\nvar sourceTableId = \'\'\nvar catalogProp = db.table(\'da_prop_t\').where()\n    .eq(\'parent_id\', inputId)\n    .eq(\'prop_name\', \'sourceTableId\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (catalogProp != null) {\n    catalogId = inputId\n    sourceTableId = text(first(catalogProp, [\'propValue\', \'prop_value\']))\n}\nif (blank(sourceTableId)) {\n    sourceTableId = inputId\n}\n\nvar sourceTable = db.table(\'db_table_t\').where()\n    .eq(\'tid\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (sourceTable == null) {\n    exit 404, \'来源表不存在\'\n}\n\n// 数据源登记第一步保存的 SSWL（所属网络）决定物化建表的默认接入网络。\n// 抽屉前端据此自动选中该网络下已启用的默认数据接入节点。\nvar sourceDatasource = db.table(\'db_datasource_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'tid\', first(sourceTable, [\'datasourceId\', \'datasource_id\']))\n    .eq(\'is_del\', 0)\n    .selectOne()\nvar sourceNetworkCode = sourceDatasource == null ? \'\' : text(first(sourceDatasource, [\n    \'storageDomain\', \'storage_domain\', \'SSWL\', \'networkDomain\', \'network_domain\'\n])).trim()\n// 物化抽屉需要回显登记第一步选择的接入方式。该值在数据源主表的\n// pool_cfg 中保存；历史记录也可能已提升为主表字段，因此两处均兼容读取。\nvar sourceDatasourceName = sourceDatasource == null ? \'\' : text(first(sourceDatasource, [\n    \'dbName\', \'db_name\', \'datasourceName\', \'datasource_name\', \'name\'\n])).trim()\nvar sourcePoolCfg = {}\nif (sourceDatasource != null) {\n    try {\n        sourcePoolCfg = jsons.toJSONObject(text(first(sourceDatasource, [\'poolCfg\', \'pool_cfg\'])))\n    } catch (e) {\n        sourcePoolCfg = {}\n    }\n}\nvar sourceAccessModeCode = sourceDatasource == null ? \'\' : text(first(sourceDatasource, [\n    \'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\'\n])).trim()\nif (blank(sourceAccessModeCode)) {\n    sourceAccessModeCode = text(first(sourcePoolCfg, [\n        \'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\'\n    ])).trim()\n}\nvar sourceAccessModeLabels = {\n    explore: \'数据抽取方式\',\n    extract: \'数据抽取方式\',\n    extraction: \'数据抽取方式\',\n    receive: \'数据推送方式\',\n    push: \'数据推送方式\',\n    capture: \'数据抓取方式\',\n    pull: \'数据抓取方式\',\n    upload: \'数据上报方式\',\n    report: \'数据上报方式\'\n}\nvar sourceAccessMode = sourceAccessModeLabels[lower(sourceAccessModeCode)] || sourceAccessModeCode\nif (blank(sourceAccessMode)) {\n    // 可连接的数据源在早期登记中没有保存 accessMode 时，沿用其既有的默认抽取语义。\n    sourceAccessMode = \'数据抽取方式\'\n}\n\n// 字段字典关联和强制对标均由登记第四步写入来源表治理快照。物化模板在此统一派生\n// <源字段>_cn，确保抽屉、DDL、目标元数据和后续 NiFi 映射使用同一字段口径。\nvar parseGovernanceConfig = (value) => {\n    if (value == null || blank(value)) {\n        return {}\n    }\n    try {\n        return value instanceof Map ? value : jsons.toJSONObject(text(value))\n    } catch (e) {\n        return {}\n    }\n}\n// New registrations persist this snapshot on db_table_t. Historical registrations\n// persist it on the generated catalog\'s properties, linked back by sourceTableId.\n// Read both locations so a re-opened production table keeps its dictionary rules.\nvar configHasFields = (config) => config != null && config.fields != null && config.fields.size() > 0\nvar governanceConfigFromProperties = (properties) => {\n    var fallback = {}\n    for (property in (properties == null ? [] : properties)) {\n        var propertyName = text(first(property, [\'propName\', \'prop_name\'])).trim().toLowerCase()\n        if (propertyName != \'fieldgovernanceconfig\' && propertyName != \'field_governance_config\'\n            && propertyName != \'fieldgovernancecfg\') {\n            continue\n        }\n        var candidate = parseGovernanceConfig(first(property, [\'propValue\', \'prop_value\']))\n        if (configHasFields(candidate)) {\n            return candidate\n        }\n        fallback = candidate\n    }\n    return fallback\n}\nvar governanceConfigOf = (table) => {\n    var persisted = parseGovernanceConfig(first(table, [\n        \'fieldGovernanceConfig\', \'field_governance_config\', \'fieldGovernanceCfg\'\n    ]))\n    if (configHasFields(persisted)) {\n        return persisted\n    }\n    var tableId = text(first(table, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(tableId)) {\n        return persisted\n    }\n    var direct = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', tableId)\n        .eq(\'is_del\', 0)\n        .select())\n    if (configHasFields(direct)) {\n        return direct\n    }\n    // Step 4 historically wrote a catalog property set. Locate that catalog by\n    // its sourceTableId property, then read the sibling governance snapshot.\n    var sourceLinks = db.table(\'da_prop_t\').where()\n        .eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', tableId)\n        .eq(\'is_del\', 0)\n        .select()\n    for (link in sourceLinks) {\n        var catalogId = text(first(link, [\'parentId\', \'parent_id\'])).trim()\n        if (blank(catalogId)) { continue }\n        var catalogConfig = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n            .eq(\'parent_id\', catalogId)\n            .eq(\'is_del\', 0)\n            .select())\n        if (configHasFields(catalogConfig)) {\n            return catalogConfig\n        }\n    }\n    return configHasFields(direct) ? direct : persisted\n}\nvar safeIdentifier = (value) => text(value).trim().matches(\'^[A-Za-z_][A-Za-z0-9_$]*$\')\nvar isForceStandardEnabled = (relation) => {\n    if (relation == null) { return false }\n    var value = text(relation.forceStandardEnabled).trim().toLowerCase()\n    var sourceType = text(relation.sourceType).trim().toLowerCase()\n    var mode = text(relation.mode).trim().toLowerCase()\n    // Fixed enumerations use the same generated <code>_cn output contract as\n    // mandatory standards, including older snapshots that only persist enum.\n    return value == \'true\' || value == \'1\' || value == \'yes\'\n        || sourceType == \'standard\' || mode == \'standard\'\n        || sourceType == \'enum\' || mode == \'enum\'\n}\nvar mandatoryStandardMappings = (relation) => {\n    var result = []\n    if (!isForceStandardEnabled(relation)) { return result }\n    var values = relation.forceStandardValueMappings == null ? [] : relation.forceStandardValueMappings\n    if (values.size() == 0) { values = relation.enumItems == null ? [] : relation.enumItems }\n    var seen = {}\n    for (value in values) {\n        var code = text(first(value, [\'sourceCode\', \'sourceValue\', \'value\', \'code\'])).trim()\n        var label = text(first(value, [\'standardLabel\', \'label\', \'sourceLabel\', \'name\'])).trim()\n        if (!blank(code) && !blank(label) && seen[code] == null) {\n            result.add({ code: code, label: label })\n            seen[code] = true\n        }\n    }\n    return result\n}\n// The column registration is the authoritative, minimal contract for the\n// materialization template. A checked dictionary association is persisted as\n// enable_code_table/code_table_id, so template generation does not need to\n// inspect the dictionary\'s physical key, label or join conditions.\nvar registeredDictionaryRelations = (table) => {\n    var result = {}\n    var tableId = text(first(table, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(tableId)) { return result }\n    var columns = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', tableId)\n        .eq(\'is_del\', 0)\n        .select()\n    for (column in columns) {\n        var sourceName = text(first(column, [\'columnName\', \'column_name\'])).trim()\n        var enabled = text(first(column, [\'enableCodeTable\', \'enable_code_table\', \'isDict\', \'is_dict\'])).trim().toLowerCase()\n        var dictionaryId = text(first(column, [\'codeTableId\', \'code_table_id\', \'dictId\', \'dict_id\'])).trim()\n        var bound = enabled == \'1\' || enabled == \'true\' || enabled == \'yes\' || !blank(dictionaryId)\n        if (bound && !blank(sourceName) && !sourceName.toLowerCase().endsWith(\'_cn\')) {\n            result[sourceName.toLowerCase()] = {\n                relationKind: \'DICTIONARY\',\n                dictionaryTableId: dictionaryId\n            }\n        }\n    }\n    return result\n}\nvar dictionaryRelations = (table) => {\n    var registered = registeredDictionaryRelations(table)\n    if (registered.size() > 0) {\n        return registered\n    }\n    // Fallback only for historical registrations that predate the per-column\n    // code-table fields. This fallback deliberately does not block template\n    // generation on a dictionary key/label configuration being incomplete.\n    var config = governanceConfigOf(table)\n    var result = {}\n    for (field in (config.fields == null ? [] : config.fields)) {\n        var relation = first(field, [\'dictionaryRelation\', \'dictionary_relation\', \'dictionaryConfig\', \'dictionary_config\'])\n        var sourceName = text(first(field, [\'columnName\', \'column_name\', \'fieldName\', \'field_name\'])).trim()\n        var sourceType = text(relation == null ? \'\' : relation.sourceType).trim().toLowerCase()\n        var standardValues = mandatoryStandardMappings(relation)\n        if (relation != null && text(relation.enabled).toLowerCase() != \'false\'\n            && safeIdentifier(sourceName) && standardValues.size() > 0) {\n            result[sourceName.toLowerCase()] = {\n                relationKind: \'MANDATORY_STANDARD\',\n                standardValues: standardValues\n            }\n        } else if (relation != null && text(relation.enabled).toLowerCase() != \'false\' && sourceType != \'enum\'\n            && !blank(sourceName)) {\n            result[sourceName.toLowerCase()] = { relationKind: \'DICTIONARY\' }\n        }\n    }\n    return result\n}\nvar appendDictionaryTranslationColumns = (items, table) => {\n    var relations = dictionaryRelations(table)\n    var existing = {}\n    for (item in items) {\n        existing[text(item.columnName).toLowerCase()] = true\n    }\n    var result = []\n    for (item in items) {\n        result.add(item)\n        var sourceName = text(item.columnName).trim()\n        var translationName = sourceName + \'_cn\'\n        var relation = relations[sourceName.toLowerCase()]\n        if (!sourceName.toLowerCase().endsWith(\'_cn\') && relation != null && existing[translationName.toLowerCase()] == null) {\n            result.add({\n                columnName: translationName,\n                columnComment: text(item.columnComment).trim() + (relation.relationKind == \'MANDATORY_STANDARD\' ? \'标准名称\' : \'翻译\'),\n                dataType: \'varchar\',\n                columnType: \'varchar(255)\',\n                length: 255,\n                precisionLength: 0,\n                scale: 0,\n                primaryKey: 0,\n                nullable: 1,\n                defaultValue: null,\n                ordinalPosition: result.size(),\n                autoIncrement: 0,\n                indexed: 0,\n                isUnique: 0,\n                dictionaryTranslationField: true,\n                dictionarySourceField: sourceName\n            })\n            existing[translationName.toLowerCase()] = true\n        }\n    }\n    return result\n}\n\nvar mapDataType = (sourceType, columnType, lengthValue) => {\n    var t = lower(sourceType)\n    var ct = lower(columnType)\n    if (blank(t)) {\n        t = ct\n    }\n    if (t.indexOf(\'char\') >= 0 || t == \'string\' || t == \'keyword\') {\n        return \'varchar\'\n    }\n    if (t == \'text\' || t == \'clob\' || t.indexOf(\'longvarchar\') >= 0) {\n        return \'text\'\n    }\n    if (t == \'number\' || t == \'numeric\' || t == \'decimal\' || t == \'float\' || t == \'double\' || t == \'real\') {\n        return \'decimal\'\n    }\n    if (t == \'bigint\' || t == \'long\') {\n        return \'bigint\'\n    }\n    if (t == \'int\' || t == \'integer\' || t == \'smallint\' || t == \'tinyint\') {\n        return \'int\'\n    }\n    if (t == \'date\') {\n        return \'date\'\n    }\n    if (t == \'datetime\' || t == \'timestamp\' || t.indexOf(\'time\') >= 0) {\n        return \'datetime\'\n    }\n    if (t == \'boolean\' || t == \'bool\') {\n        return \'tinyint\'\n    }\n    if (t.indexOf(\'blob\') >= 0 || t == \'binary\' || t == \'varbinary\') {\n        return \'blob\'\n    }\n    if (t == \'json\' || t == \'object\' || t == \'array\') {\n        return \'json\'\n    }\n    return \'varchar\'\n}\n// 物化建表必须以已登记数据源的实际字段定义为准。登记快照早期导入的数据\n// 可能只保留“字符串”等展示类型并且 length 为 0；直接用快照会导致每列都回退到 255。\n// 探查不可用时仍回退到快照，避免临时网络故障阻断建表抽屉打开。\n// 连接细节由 datasourceConnectionConfig 从 pool_cfg 解密并统一返回；\n// db_datasource_t 只保留 jdbc_url 等登记字段，不能假定 host/port 是直接列。\nvar dataSourceConfigOf = (source, connection) => {\n    var config = new DataSourceConfig()\n    var typeCode = first(source, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\n    try {\n        config.setDatabaseType(blank(typeCode) ? DatabaseType.MYSQL : DatabaseType.fromCode(lower(typeCode)))\n    } catch (e) {\n        config.setDatabaseType(DatabaseType.MYSQL)\n    }\n    var host = first(connection, [\'host\', \'dbMetaIp\']) || first(source, [\'host\', \'dbIp\', \'db_ip\'])\n    var port = first(connection, [\'port\', \'dbMetaPort\']) || first(source, [\'port\', \'dbPort\', \'db_port\'])\n    var databaseName = first(connection, [\'database\', \'dbName\', \'dbMetaDbName\']) || first(source, [\'database\', \'dbName\', \'db_name\', \'dbMetaDbName\'])\n    var username = first(connection, [\'username\', \'dbMetaUser\']) || first(source, [\'username\', \'dbUser\', \'db_user\', \'dbMetaUser\'])\n    var password = first(connection, [\'password\', \'dbMetaPassword\']) || first(source, [\'password\', \'dbPassword\', \'db_password\', \'dbMetaPassword\'])\n    config.setHost(blank(host) ? \'\' : text(host))\n    config.setPort(blank(port) ? config.getDatabaseType().getDefaultPort() : toInt(port, config.getDatabaseType().getDefaultPort()))\n    config.setDatabase(text(databaseName))\n    config.setUsername(text(username))\n    config.setPassword(text(password))\n    // 复用测试连接时登记的 JDBC URL，兼容 Oracle Service Name、达梦 Schema 等连接形式。\n    config.setJdbcUrl(first(connection, [\'jdbcURL\', \'jdbcUrl\']) || first(source, [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\']))\n    config.setSchema(first(connection, [\'schema\', \'defaultSchema\', \'currentSchema\']) || first(source, [\'schema\', \'defaultSchema\', \'default_schema\', \'currentSchema\', \'schemaName\', \'schema_name\']))\n    return config\n}\nvar sourcePhysicalColumns = (source, tableName) => {\n    var result = []\n    if (source == null || blank(tableName)) {\n        return result\n    }\n    try {\n        // 连接参数从统一配置解析，避免直接使用数据库中可能已加密的密码字段。\n        var connection = datasourceConnectionConfig(\'read\', first(source, [\'tid\']), null, false)\n        var physicalColumns = metadataExplorerService.getColumns(dataSourceConfigOf(source, connection), tableName)\n        for (physical in (physicalColumns == null ? [] : physicalColumns)) {\n            if (!blank(physical.columnName)) {\n                // MetadataExplorer 返回的是 Java ColumnInfo；后续模板逻辑按 Map 的\n                // 多字段兼容读取（first）工作，故先转为普通对象，不能直接混用两者。\n                result.add({\n                    columnName: physical.columnName,\n                    columnComment: physical.columnComment,\n                    dataType: physical.dataType,\n                    columnType: physical.columnType,\n                    length: physical.length,\n                    precision: physical.precision,\n                    scale: physical.scale,\n                    nullable: physical.nullable,\n                    primaryKey: physical.primaryKey,\n                    ordinalPosition: physical.ordinalPosition\n                })\n            }\n        }\n    } catch (e) {\n        // 模板查询保持可用：探查失败时由登记快照和 normalizeLength 的既有逻辑兜底。\n    }\n    return result\n}\nvar normalizeLength = (targetType, lengthValue, precisionValue) => {\n    var lengthNum = toInt(lengthValue, 0)\n    var precisionNum = toInt(precisionValue, 0)\n    if (targetType == \'varchar\') {\n        return lengthNum > 0 ? lengthNum : 255\n    }\n    if (targetType == \'decimal\') {\n        return precisionNum > 0 ? precisionNum : (lengthNum > 0 ? lengthNum : 18)\n    }\n    if (targetType == \'int\') {\n        return lengthNum > 0 ? lengthNum : 10\n    }\n    if (targetType == \'bigint\') {\n        return lengthNum > 0 ? lengthNum : 20\n    }\n    return lengthNum\n}\nvar normalizeNullable = (value) => {\n    if (value == null || blank(value)) {\n        return 1\n    }\n    var normalized = text(value).trim().toLowerCase()\n    if (normalized == \'false\' || normalized == \'no\' || normalized == \'0\') {\n        return 0\n    }\n    return 1\n}\nvar materializationTimeType = (dbType) => {\n    var code = text(dbType).trim().toLowerCase()\n    if (code.indexOf(\'oceanbase\') >= 0 || code == \'oracle\' || code == \'dameng\' || code == \'dm\') {\n        return \'date\'\n    }\n    if (code == \'postgresql\' || code == \'postgres\' || code == \'kingbase\' || code == \'kingbase8\'\n        || code == \'gaussdb\' || code == \'opengauss\' || code == \'gauss\'\n        || code == \'vertica\' || code == \'hetu\' || code == \'trino\' || code == \'presto\'\n        || code == \'hive\') {\n        return \'timestamp\'\n    }\n    if (code == \'sqlserver\') {\n        return \'datetime2\'\n    }\n    return \'datetime\'\n}\nvar odsSystemColumns = (dbType) => {\n    var timeType = materializationTimeType(dbType)\n    return [\n    {\n        columnName: \'ODS_UUID\',\n        columnComment: \'ODS主键\',\n        dataType: \'varchar\',\n        columnType: \'varchar\',\n        length: 32,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 1,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 1,\n        isUnique: 1,\n        odsSystemColumn: true\n    },\n    {\n        columnName: \'ODS_RKSJ\',\n        columnComment: \'ODS入库时间\',\n        dataType: timeType,\n        columnType: timeType,\n        length: 0,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 0,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 0,\n        isUnique: 0,\n        odsSystemColumn: true\n    },\n    {\n        columnName: \'ODS_GXSJ\',\n        columnComment: \'ODS更新时间\',\n        dataType: timeType,\n        columnType: timeType,\n        length: 0,\n        precisionLength: 0,\n        scale: 0,\n        primaryKey: 0,\n        nullable: 0,\n        defaultValue: null,\n        ordinalPosition: 0,\n        autoIncrement: 0,\n        indexed: 0,\n        isUnique: 0,\n        odsSystemColumn: true\n    }\n    ]\n}\nvar appendOdsSystemColumns = (items, dbType) => {\n    var existing = {}\n    var hasSourcePrimaryKey = false\n    for (item in items) {\n        if (!blank(item.columnName)) {\n            existing[text(item.columnName).toLowerCase()] = true\n            hasSourcePrimaryKey = hasSourcePrimaryKey || toInt(item.primaryKey, 0) == 1\n        }\n    }\n    for (fixed in odsSystemColumns(dbType)) {\n        var key = text(fixed.columnName).toLowerCase()\n        if (existing[key] == null) {\n            // 来源表已有业务主键时，ODS_UUID 仅作为系统追踪字段；无主键时才承担主键职责。\n            if (text(fixed.columnName).toUpperCase() == \'ODS_UUID\') {\n                fixed.primaryKey = hasSourcePrimaryKey ? 0 : 1\n            }\n            fixed.ordinalPosition = items.size()\n            items.add(fixed)\n            existing[key] = true\n        }\n    }\n    return items\n}\n\n// 第四步登记的字段治理快照是用户确认后的主键口径。物理探查列可能没有\n// primary_key 标记，因此建表模板必须优先合并该快照，不能把 ODS_UUID 当作默认主键。\nvar registeredPrimaryKeys = {}\nvar registeredFields = governanceConfigOf(sourceTable).fields\nfor (registeredField in (registeredFields == null ? [] : registeredFields)) {\n    var registeredColumnName = text(first(registeredField, [\'columnName\', \'column_name\'])).trim().toLowerCase()\n    if (!blank(registeredColumnName) && isPrimaryKey(first(registeredField, [\'primaryKey\', \'primary_key\', \'isPrimaryKey\', \'is_primary_key\']))) {\n        registeredPrimaryKeys[registeredColumnName] = true\n    }\n}\n\nvar sourceTableName = text(first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])).trim()\nvar physicalColumns = sourcePhysicalColumns(sourceDatasource, sourceTableName)\nvar physicalColumnsByName = {}\nfor (physical in (physicalColumns == null ? [] : physicalColumns)) {\n    if (!blank(physical.columnName)) {\n        physicalColumnsByName[lower(physical.columnName)] = physical\n    }\n}\n\nvar columns = db.table(\'db_table_column_t\').where()\n    .eq(\'table_id\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .orderBy(\'ordinal_position\', \'asc\')\n    .select()\n// 一些历史登记记录只保存了表级信息。快照为空时不能丢弃已成功探查的\n// 物理字段，否则抽屉只能显示 ODS 系统字段。\nif ((columns == null || columns.size() == 0) && physicalColumns != null && physicalColumns.size() > 0) {\n    columns = physicalColumns\n}\n\nvar tableItems = []\nfor (col in (columns == null ? [] : columns)) {\n    var columnName = first(col, [\'columnName\', \'column_name\'])\n    var physicalColumn = physicalColumnsByName[lower(columnName)]\n    // 优先采用实际源库类型和长度；未探查到时保持历史登记快照的兼容行为。\n    var sourceType = physicalColumn == null || blank(physicalColumn.dataType)\n        ? first(col, [\'dataType\', \'data_type\']) : physicalColumn.dataType\n    var columnType = physicalColumn == null || blank(physicalColumn.columnType)\n        ? first(col, [\'columnType\', \'column_type\']) : physicalColumn.columnType\n    var sourceLength = physicalColumn == null || toInt(physicalColumn.length, 0) <= 0\n        ? first(col, [\'length\']) : physicalColumn.length\n    var sourcePrecision = physicalColumn == null || toInt(physicalColumn.precision, 0) <= 0\n        ? first(col, [\'precisionLength\', \'precision_length\']) : physicalColumn.precision\n    var sourceScale = physicalColumn == null || toInt(physicalColumn.scale, 0) < 0\n        ? first(col, [\'scale\']) : physicalColumn.scale\n    var targetType = mapDataType(sourceType, columnType, sourceLength)\n    tableItems.add({\n        sourceColumnId: first(col, [\'tid\']),\n        columnName: columnName,\n        columnComment: first(col, [\'columnComment\', \'column_comment\']) || columnName,\n        sourceDataType: sourceType,\n        sourceColumnType: columnType,\n        dataType: targetType,\n        columnType: targetType,\n        length: normalizeLength(targetType, sourceLength, sourcePrecision),\n        precisionLength: toInt(sourcePrecision, 0),\n        scale: toInt(sourceScale, 0),\n        primaryKey: isPrimaryKey(first(col, [\'primaryKey\', \'primary_key\', \'isPrimaryKey\', \'is_primary_key\'])) || registeredPrimaryKeys[text(columnName).trim().toLowerCase()] == true ? 1 : 0,\n        nullable: normalizeNullable(first(col, [\'nullable\'])),\n        defaultValue: first(col, [\'defaultValue\', \'default_value\']),\n        ordinalPosition: toInt(first(col, [\'ordinalPosition\', \'ordinal_position\']), 0),\n        autoIncrement: toInt(first(col, [\'autoIncrement\', \'auto_increment\']), 0),\n        indexed: toInt(first(col, [\'indexed\']), 0),\n        isUnique: toInt(first(col, [\'isUnique\', \'is_unique\']), 0)\n    })\n}\ntableItems = appendDictionaryTranslationColumns(tableItems, sourceTable)\n\n// 目标库以数据组织字典为源：dataSourceType -> ODS -> 分域（例如原始库）；\n// 每个分域的目标数据源由分层分域配置维护，和物化弹窗下拉严格使用同一关系。\nvar dataSourceTypeRoot = db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'dict_code\', \'dataSourceType\')\n    .eq(\'parent_id\', \'0\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nvar odsNode = dataSourceTypeRoot == null ? null : db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'parent_id\', dataSourceTypeRoot.tid)\n    .eq(\'dict_code\', \'ods\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nvar odsDomains = odsNode == null ? [] : db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'parent_id\', odsNode.tid)\n    .eq(\'is_del\', 0)\n    .orderBy(\'sort_no\', \'asc\')\n    .select()\nvar domainIds = []\nfor (odsDomain in (odsDomains == null ? [] : odsDomains)) {\n    domainIds.add(text(odsDomain.tid))\n}\nvar domainRelations = domainIds.size() == 0 ? [] : db.table(\'dwm_center_layer_source_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'target_type\', \'domain\')\n    .in(\'target_id\', domainIds)\n    .eq(\'is_del\', 0)\n    .orderBy(\'updated_time\', \'desc\')\n    .select()\nvar targetDatasource = null\nvar targetDomain = null\nfor (odsDomain in (odsDomains == null ? [] : odsDomains)) {\n    var domainId = text(odsDomain.tid)\n    var relation = null\n    for (candidate in (domainRelations == null ? [] : domainRelations)) {\n        if (text(candidate.targetId) == domainId && !blank(candidate.datasourceId)) {\n            relation = candidate\n            break\n        }\n    }\n    if (relation == null) {\n        continue\n    }\n    var candidateDatasource = db.table(\'db_datasource_t\').where()\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'tid\', relation.datasourceId)\n        .eq(\'is_del\', 0)\n        .eq(\'show_connect\', 1)\n        .selectOne()\n    if (candidateDatasource != null) {\n        targetDatasource = candidateDatasource\n        targetDomain = odsDomain\n        break\n    }\n}\n\n// Source metadata may preserve an Oracle/DM owner prefix (for example\n// TEST0809.CAR_TURN_OVER). That prefix is needed for source probing, but it\n// must never become part of a physical target table name. Both task management\n// and the canvas consume this template, so normalize it once here.\nvar targetTableSourceName = sourceTableName\nvar ownerSeparator = targetTableSourceName.lastIndexOf(\'.\')\nif (ownerSeparator >= 0 && ownerSeparator < targetTableSourceName.length() - 1) {\n    targetTableSourceName = targetTableSourceName.substring(ownerSeparator + 1)\n}\nvar tablePrefix = \'ODS\'\nvar tableName = targetTableSourceName.toUpperCase().startsWith(tablePrefix + \'_\') ? targetTableSourceName : tablePrefix + \'_\' + targetTableSourceName\nvar tableNameCn = first(sourceTable, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']) || tableName\nvar dbId = targetDatasource == null ? \'\' : text(first(targetDatasource, [\'tid\']))\nvar dbName = targetDatasource == null ? \'\' : text(first(targetDatasource, [\'dbName\', \'db_name\']))\nvar nodeId = targetDatasource == null ? \'\' : text(first(targetDatasource, [\'nodeId\', \'node_id\']))\nvar dbType = targetDatasource == null ? \'\' : text(first(targetDatasource, [\'dbType\', \'db_type\']))\ntableItems = appendOdsSystemColumns(tableItems, dbType)\n\nreturn {\n    propList: {\n        sourceTableId: sourceTableId,\n        catalogId: catalogId,\n        sourceDatasourceName: sourceDatasourceName,\n        sourceAccessMode: sourceAccessMode,\n        sourceAccessModeCode: sourceAccessModeCode,\n        sourceNetworkCode: sourceNetworkCode,\n        dbId: dbId,\n        dbName: dbName,\n        nodeId: nodeId,\n        dbType: dbType,\n        sourceTableName: sourceTableName,\n        targetLayerCode: tablePrefix,\n        targetDomainId: targetDomain == null ? \'\' : text(targetDomain.tid),\n        targetDomainName: targetDomain == null ? \'\' : text(targetDomain.dictName),\n        assetType: \'table\',\n        tableNameCn: tableNameCn,\n        tableName: tableName,\n        tableType: \'数据表\',\n        recordCount: toInt(first(sourceTable, [\'recordCount\', \'record_count\']), 0),\n        storageSize: first(sourceTable, [\'storageSize\', \'storage_size\']) || \'0 KB\',\n        businessType: first(sourceTable, [\'businessType\', \'business_type\']) || \'业务表\',\n        relatedDirectory: \'自动生成目录\'\n    },\n    tableItems: tableItems\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/11.根据表或目录获取建表申请模板.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_data_agg_reject_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_data_agg_reject_01",\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "12.驳回接入登记修改",\n  "path": "/dataAggReject",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tableId\\":\\"来源表ID\\",\\"datasourceId\\":\\"数据源ID\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"tableId\\":\\"来源表ID\\",\\"assetStatus\\":0}",\n  "description": "接入发现登记信息有误时驳回修改。仅无接入任务的数据表允许驳回；只重置来源表的标注与登记状态，数据源保持已注册，并刷新资产索引；使用请求参数 tableId、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null,\n  "script": null\n}\n================================\n// 接口：12.驳回接入登记修改\n// 路由：POST /ods/dataAggReject\n// 业务说明：接入发现登记信息有误时驳回修改。仅无接入任务的数据表允许驳回；只重置来源表的标注与登记状态，数据源保持已注册，并刷新资产索引；使用请求参数 tableId、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表；执行数据库写入并返回处理结果。\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar tenantId = tenantRuntime.id()\nvar nowTime = new Date()\nvar tableId = body == null ? null : body.tableId\nvar requestedDatasourceId = body == null ? null : body.datasourceId\nif (blank(tableId)) {\n    exit 400, \'来源表不能为空\'\n}\n// db.table 使用后端命名表租户拦截器，查询与更新天然限定在当前登录租户；\n// 请求中不接受 tenantId，避免由前端决定租户范围。\nvar sourceTable = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (sourceTable == null) {\n    exit 404, \'来源表不存在或无访问权限\'\n}\nvar datasourceId = sourceTable.datasourceId == null ? sourceTable.datasource_id : sourceTable.datasourceId\nif (!blank(requestedDatasourceId) && text(requestedDatasourceId) != text(datasourceId)) {\n    exit 400, \'来源表与数据源不匹配\'\n}\nvar datasource = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\nif (datasource == null) {\n    exit 404, \'数据源不存在或无访问权限\'\n}\nvar taskCount = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'source_table_id\', tableId).eq(\'is_del\', 0).count()\nif (taskCount > 0) {\n    exit 409, \'该表已创建接入任务，不能驳回修改\'\n}\ndb.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).update({\n    asset_status: 0,\n    flow_status: 0,\n    updated_time: nowTime\n})\nbody = { tid: tableId }\nrefreshAssetIndex()\nreturn { tableId: tableId, datasourceId: datasourceId, assetStatus: 0 }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/12.驳回接入登记修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_data_agg_task_ensure_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_data_agg_task_ensure_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "13.按来源表补齐接入任务",\n  "createTime": 1785063600000,\n  "updateTime": 1790420562971,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dataAggTaskEnsure",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tableId\\": \\"015c09572d174e89b9bea9c765ef72df\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"created\\": true,\\n  \\"taskId\\": \\"03ac61c2b0b84c1a87ff11ae1e38b949\\",\\n  \\"task\\": {\\"tid\\":\\"03ac61c2b0b84c1a87ff11ae1e38b949\\"}\\n}",\n  "description": "按来源表补齐数据接入任务（POST /ods/dataAggTaskEnsure）。写接口；以 db_table_t 来源表为入口，读取自动目录和目标表，创建 nifi_pipeline_t 画布草稿、data_access_agg_task_t 任务及字段映射；已有任务时直接返回。用于数据接入-任务管理页面的创建任务按钮；使用请求参数 tableId、sourceTableId、tid、repair、forceRebuild、rebuild、catalogId；涉及 da_prop_t、db_table_column_t、db_table_t、da_catalog_t、dwm_center_layer_source_t、db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：13.按来源表补齐接入任务\n// 路由：POST /ods/dataAggTaskEnsure\n// 业务说明：按来源表补齐数据接入任务（POST /ods/dataAggTaskEnsure）。写接口；以 db_table_t 来源表为入口，读取自动目录和目标表，创建 nifi_pipeline_t 画布草稿、data_access_agg_task_t 任务及字段映射；已有任务时直接返回。用于数据接入-任务管理页面的创建任务按钮；使用请求参数 tableId、sourceTableId、tid、repair、forceRebuild、rebuild、catalogId；涉及 da_prop_t、db_table_column_t、db_table_t、da_catalog_t、dwm_center_layer_source_t、db_datasource_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\n/*\n * 按来源表确保接入任务存在。\n *\n * 业务链路：来源表 => 字段增强 => 目标表（目录）。\n * 如果来源表已经有 data_access_agg_task_t，则直接返回；\n * 否则读取 createTapleApply 自动生成的目录和目标表，写入任务与 NiFi 画布草稿，\n * 让前端能直接打开 data-element-nifi 继续查看/调整流程。\n */\nimport cn.hutool.core.util.IdUtil\nimport jsons\nimport metadataAsset\nimport targetTableSchema\nimport apiPullConfig\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        if (row[key] != null && text(row[key]).trim() != \'\') {\n            return row[key]\n        }\n    }\n    return null\n}\nvar jdbcUrl = (dbType, cfg, row) => {\n  var url = first(cfg, [\'jdbcURL\', \'jdbcUrl\', \'url\'])\n  if (blank(url)) { url = first(row, [\'jdbc_url\', \'jdbcURL\', \'jdbcUrl\', \'url\']) }\n  if (!blank(url)) { return text(url) }\n  var type = text(dbType).trim().toUpperCase()\n  var host = first(cfg, [\'host\', \'dbMetaIp\']) || first(row, [\'host\', \'db_meta_ip\']) || \'127.0.0.1\'\n  var port = first(cfg, [\'port\', \'dbMetaPort\']) || first(row, [\'port\', \'db_meta_port\'])\n  var database = first(cfg, [\'database\', \'serviceName\', \'sid\', \'dbName\', \'dbMetaDbName\']) || first(row, [\'dbName\', \'db_name\']) || \'\'\n  if (type == \'DM\' || type == \'DAMENG\') { return \'jdbc:dm://\' + host + \':\' + (blank(port) ? \'5236\' : port) + \'/\' + database }\n  if (type == \'ORACLE\' || type == \'ORACLE12\' || type == \'ORACLE_12\') {\n    var connectionType = text(first(cfg, [\'connectionType\', \'jdbcType\'])).trim().toUpperCase()\n    if (connectionType == \'SID\') { return \'jdbc:oracle:thin:@\' + host + \':\' + (blank(port) ? \'1521\' : port) + \':\' + database }\n    return \'jdbc:oracle:thin:@//\' + host + \':\' + (blank(port) ? \'1521\' : port) + \'/\' + database\n  }\n  if (type == \'POSTGRES\' || type == \'POSTGRESQL\' || type == \'TDSQL_PG\' || type == \'GAUSSDB\' || type == \'OPENGAUSS\') { return \'jdbc:postgresql://\' + host + \':\' + (blank(port) ? \'5432\' : port) + \'/\' + database }\n  if (type == \'SQLSERVER\' || type == \'MSSQL\' || type == \'MS_SQL\') { return \'jdbc:sqlserver://\' + host + \':\' + (blank(port) ? \'1433\' : port) + \';databaseName=\' + database }\n  if (type == \'KINGBASE\') { return \'jdbc:kingbase8://\' + host + \':\' + (blank(port) ? \'54321\' : port) + \'/\' + database }\n  if (type == \'CLICKHOUSE\') { return \'jdbc:clickhouse://\' + host + \':\' + (blank(port) ? \'8123\' : port) + \'/\' + database }\n  return \'jdbc:mysql://\' + host + \':\' + (blank(port) ? \'3306\' : port) + \'/\' + database\n}\nvar safeIdentifier = (value) => text(value).trim().matches(\'^[A-Za-z_][A-Za-z0-9_$]*$\')\n// Registrations from production commonly persist a dictionary table as\n// "SCHEMA.TABLE".  Keep both names separately: SQL can qualify the table\n// safely while datasource matching and metadata lookups use the table name.\nvar dictionaryTableReference = (value) => {\n    var raw = text(value).trim()\n    var dot = raw.indexOf(\'.\')\n    if (dot < 0) {\n        return safeIdentifier(raw) ? { schema: \'\', table: raw } : { schema: \'\', table: \'\' }\n    }\n    if (dot == 0 || dot == raw.length() - 1 || raw.substring(dot + 1).indexOf(\'.\') >= 0) {\n        return { schema: \'\', table: \'\' }\n    }\n    var schema = raw.substring(0, dot)\n    var table = raw.substring(dot + 1)\n    return safeIdentifier(schema) && safeIdentifier(table)\n        ? { schema: schema, table: table } : { schema: \'\', table: \'\' }\n}\nvar qualifiedDictionaryTable = (relation, dictionarySource) => {\n    var table = text(relation == null ? \'\' : relation.dictionaryTable).trim()\n    var schema = text(relation == null ? \'\' : relation.dictionarySchema).trim()\n    if (blank(schema) && dictionarySource != null) { schema = text(dictionarySource.schema).trim() }\n    return safeIdentifier(schema) ? schema + \'.\' + table : table\n}\nvar parseGovernanceConfig = (value) => {\n    if (value == null || blank(value)) {\n        return {}\n    }\n    try {\n        return value instanceof Map ? value : jsons.toJSONObject(text(value))\n    } catch (e) {\n        return {}\n    }\n}\n// Step 4\'s current save writes this snapshot on db_table_t. Earlier production\n// saves attached it to the generated catalog in da_prop_t.  Follow sourceTableId\n// to preserve dictionary enrichment for both registration generations.\nvar configHasFields = (config) => config != null && config.fields != null && config.fields.size() > 0\nvar governanceConfigFromProperties = (properties) => {\n    var fallback = {}\n    for (property in (properties == null ? [] : properties)) {\n        var propertyName = text(first(property, [\'propName\', \'prop_name\'])).trim().toLowerCase()\n        if (propertyName != \'fieldgovernanceconfig\' && propertyName != \'field_governance_config\'\n            && propertyName != \'fieldgovernancecfg\') { continue }\n        var candidate = parseGovernanceConfig(first(property, [\'propValue\', \'prop_value\']))\n        if (configHasFields(candidate)) { return candidate }\n        fallback = candidate\n    }\n    return fallback\n}\nvar governanceConfigOf = (table) => {\n    var persisted = parseGovernanceConfig(first(table, [\n        \'fieldGovernanceConfig\', \'field_governance_config\', \'fieldGovernanceCfg\'\n    ]))\n    if (configHasFields(persisted)) { return persisted }\n    var tableId = text(first(table, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(tableId)) { return persisted }\n    var direct = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', tableId).eq(\'is_del\', 0).select())\n    if (configHasFields(direct)) { return direct }\n    var sourceLinks = db.table(\'da_prop_t\').where()\n        .eq(\'prop_name\', \'sourceTableId\').eq(\'prop_value\', tableId).eq(\'is_del\', 0).select()\n    for (link in sourceLinks) {\n        var catalogId = text(first(link, [\'parentId\', \'parent_id\'])).trim()\n        if (blank(catalogId)) { continue }\n        var catalogConfig = governanceConfigFromProperties(db.table(\'da_prop_t\').where()\n            .eq(\'parent_id\', catalogId).eq(\'is_del\', 0).select())\n        if (configHasFields(catalogConfig)) { return catalogConfig }\n    }\n    return configHasFields(direct) ? direct : persisted\n}\n// A mandatory-standard relation is an enumerated code alignment.  It has no\n// dictionary table, but it must still materialize and populate <code>_cn.\nvar mandatoryStandardMappings = (relation) => {\n    var result = []\n    if (relation == null) {\n        return result\n    }\n    var forceEnabled = text(relation.forceStandardEnabled).trim().toLowerCase()\n    var sourceType = text(relation.sourceType).trim().toLowerCase()\n    var mode = text(relation.mode).trim().toLowerCase()\n    // Production registrations may also persist a small fixed dictionary as\n    // sourceType/mode=enum. It is executed exactly like a mandatory-standard\n    // mapping: no lookup table is needed, but the label must be written to the\n    // generated <code>_cn target field.\n    if (!(forceEnabled == \'true\' || forceEnabled == \'1\' || forceEnabled == \'yes\'\n        || sourceType == \'standard\' || mode == \'standard\'\n        || sourceType == \'enum\' || mode == \'enum\')) {\n        return result\n    }\n    var values = relation.forceStandardValueMappings == null ? [] : relation.forceStandardValueMappings\n    if (values.size() == 0) { values = relation.enumItems == null ? [] : relation.enumItems }\n    var seen = {}\n    for (value in values) {\n        var code = text(first(value, [\'sourceCode\', \'sourceValue\', \'value\', \'code\'])).trim()\n        var label = text(first(value, [\'standardLabel\', \'label\', \'sourceLabel\', \'name\'])).trim()\n        if (!blank(code) && !blank(label) && seen[code] == null) {\n            result.add({ code: code, label: label })\n            seen[code] = true\n        }\n    }\n    return result\n}\n// A field\'s checked dictionary association is persisted independently of the\n// detailed relation JSON.  Production registrations may only have these two\n// column values, so resolve the executable lookup from the registered\n// dictionary table instead of requiring the source relation JSON to be whole.\nvar registeredDictionaryRelations = (sourceTable) => {\n    var result = []\n    var sourceTableId = text(first(sourceTable, [\'tid\', \'id\', \'tableId\', \'table_id\'])).trim()\n    if (blank(sourceTableId)) { return result }\n    var sourceColumns = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', sourceTableId).eq(\'is_del\', 0).select()\n    for (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n        var sourceName = text(first(sourceColumn, [\'columnName\', \'column_name\'])).trim()\n        var enabled = text(first(sourceColumn, [\'enableCodeTable\', \'enable_code_table\', \'isDict\', \'is_dict\'])).trim().toLowerCase()\n        var dictionaryTableId = text(first(sourceColumn, [\'codeTableId\', \'code_table_id\', \'dictId\', \'dict_id\'])).trim()\n        if (blank(sourceName) || (enabled != \'1\' && enabled != \'true\' && enabled != \'yes\' && blank(dictionaryTableId))) {\n            continue\n        }\n        var dictionaryTable = blank(dictionaryTableId) ? null : db.table(\'db_table_t\').where()\n            .eq(\'tid\', dictionaryTableId).eq(\'is_del\', 0).selectOne()\n        if (dictionaryTable == null) { continue }\n        var dictionaryConfig = governanceConfigOf(dictionaryTable)\n        var profile = dictionaryConfig.dictionaryProfile\n        if (profile == null && dictionaryConfig.dictionaryProfiles != null && dictionaryConfig.dictionaryProfiles.size() > 0) {\n            profile = dictionaryConfig.dictionaryProfiles[0]\n        }\n        if (profile == null && dictionaryConfig.dictionaryCategories != null && dictionaryConfig.dictionaryCategories.size() > 0) {\n            profile = dictionaryConfig.dictionaryCategories[0]\n        }\n        var keyField = text(first(profile, [\'codeField\', \'code_field\', \'dictionaryKeyField\', \'dictionary_key_field\'])).trim()\n        var labelField = text(first(profile, [\'labelField\', \'label_field\', \'nameField\', \'name_field\', \'dictionaryLabelField\', \'dictionary_label_field\'])).trim()\n        for (dictionaryField in (dictionaryConfig.fields == null ? [] : dictionaryConfig.fields)) {\n            var fieldName = text(first(dictionaryField, [\'columnName\', \'column_name\', \'fieldName\', \'field_name\'])).trim()\n            var role = text(first(dictionaryField, [\'dictionaryRole\', \'dictionary_role\'])).trim().toLowerCase()\n            if (blank(keyField) && role == \'code\') { keyField = fieldName }\n            if (blank(labelField) && role == \'label\') { labelField = fieldName }\n        }\n        // The dictionary profile may be an early registration. Use its primary\n        // key and conventional name column only as metadata fallback, never as\n        // a reason to reject an otherwise saved source-field association.\n        var dictionaryColumns = db.table(\'db_table_column_t\').where()\n            .eq(\'table_id\', dictionaryTableId).eq(\'is_del\', 0).select()\n        for (dictionaryColumn in (dictionaryColumns == null ? [] : dictionaryColumns)) {\n            var columnName = text(first(dictionaryColumn, [\'columnName\', \'column_name\'])).trim()\n            var normalizedName = columnName.toLowerCase()\n            if (blank(keyField) && (text(first(dictionaryColumn, [\'primaryKey\', \'primary_key\'])).trim() == \'1\'\n                || text(first(dictionaryColumn, [\'isUnique\', \'is_unique\'])).trim() == \'1\'\n                || normalizedName.indexOf(\'code\') >= 0)) {\n                keyField = columnName\n            }\n            if (blank(labelField) && (normalizedName == \'name\' || normalizedName == \'label\'\n                || normalizedName.endsWith(\'_name\') || normalizedName.endsWith(\'_label\'))) {\n                labelField = columnName\n            }\n        }\n        var dictionaryReference = dictionaryTableReference(first(dictionaryTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\']))\n        if (safeIdentifier(sourceName) && safeIdentifier(dictionaryReference.table)\n            && safeIdentifier(keyField) && safeIdentifier(labelField)) {\n            result.add({\n                sourceName: sourceName,\n                relationKind: \'DICTIONARY\',\n                dictionaryTable: dictionaryReference.table,\n                dictionarySchema: dictionaryReference.schema,\n                dictionaryTableId: dictionaryTableId,\n                dictionaryKeyField: keyField,\n                dictionaryLabelField: labelField,\n                conditions: []\n            })\n        }\n    }\n    return result\n}\n// Step 4 persists each enabled dictionary or mandatory-standard relation with\n// the source table. Dictionary values are queried at runtime; mandatory\n// standards compile to a deterministic enum mapping without a database call.\nvar dictionaryRelations = (sourceTable) => {\n    var config = governanceConfigOf(sourceTable)\n    var result = {}\n    for (field in (config.fields == null ? [] : config.fields)) {\n        var relation = first(field, [\'dictionaryRelation\', \'dictionary_relation\', \'dictionaryConfig\', \'dictionary_config\'])\n        var sourceName = text(first(field, [\'columnName\', \'column_name\', \'fieldName\', \'field_name\'])).trim()\n        var sourceType = text(relation == null ? \'\' : relation.sourceType).trim().toLowerCase()\n        var dictionaryReference = dictionaryTableReference(relation == null ? \'\' : first(relation, [\'dictionaryTable\', \'dictionary_table\', \'dictTable\', \'dict_table\']))\n        var dictionaryTable = dictionaryReference.table\n        var keyField = text(relation == null ? \'\' : first(relation, [\'dictionaryKeyField\', \'dictionary_key_field\', \'keyField\', \'key_field\', \'codeField\', \'code_field\'])).trim()\n        var labelField = text(relation == null ? \'\' : first(relation, [\'dictionaryLabelField\', \'dictionary_label_field\', \'labelField\', \'label_field\', \'nameField\', \'name_field\'])).trim()\n        var standardValues = mandatoryStandardMappings(relation)\n        if (relation != null && text(relation.enabled).toLowerCase() != \'false\'\n            && safeIdentifier(sourceName) && standardValues.size() > 0) {\n            result[sourceName.toLowerCase()] = {\n                sourceName: sourceName,\n                relationKind: \'MANDATORY_STANDARD\',\n                standardValues: standardValues,\n                multiValue: text(relation.multiValue).toLowerCase() == \'true\',\n                multiValueSeparator: blank(relation.multiValueSeparator) ? \',\' : text(relation.multiValueSeparator)\n            }\n        } else if (relation != null && text(relation.enabled).toLowerCase() != \'false\' && sourceType != \'enum\'\n            && safeIdentifier(sourceName) && safeIdentifier(dictionaryTable)\n            && safeIdentifier(keyField) && safeIdentifier(labelField)) {\n            result[sourceName.toLowerCase()] = {\n                sourceName: sourceName,\n                relationKind: \'DICTIONARY\',\n                dictionaryTable: dictionaryTable,\n                dictionarySchema: dictionaryReference.schema,\n                dictionaryTableId: text(first(relation, [\'dictionaryTableId\', \'dictionary_table_id\'])).trim(),\n                dictionaryKeyField: keyField,\n                dictionaryLabelField: labelField,\n                conditions: relation.conditions == null ? [] : relation.conditions,\n                multiValue: text(relation.multiValue).toLowerCase() == \'true\',\n                multiValueSeparator: blank(relation.multiValueSeparator) ? \',\' : text(relation.multiValueSeparator)\n            }\n        }\n    }\n    // Preserve an explicit source relation when present because it may carry\n    // category/status conditions. Fill only the associations that production\n    // persisted at the column level.\n    for (registeredRelation in registeredDictionaryRelations(sourceTable)) {\n        var key = registeredRelation.sourceName.toLowerCase()\n        if (result[key] == null) {\n            result[key] = registeredRelation\n        }\n    }\n    return result\n}\n// Resolve governed outputs from the materialized target table.  An explicit\n// source-to-target binding takes precedence, but imported historical targets\n// may contain an incomplete binding array.  For any unbound <source>_cn\n// output, the source registration remains authoritative and restores the\n// dictionary/standard transformation from that registered relation.\nvar targetFieldTransformBindings = (sourceTable, targetTable, targetColumns) => {\n    var sourceRelations = dictionaryRelations(sourceTable)\n    var config = governanceConfigOf(targetTable)\n    var rawBindings = config.fieldTransformBindings == null ? [] : config.fieldTransformBindings\n    var targetNames = {}\n    for (targetColumn in (targetColumns == null ? [] : targetColumns)) {\n        targetNames[text(first(targetColumn, [\'columnName\', \'column_name\'])).toLowerCase()] = true\n    }\n    var result = []\n    var seenTargets = {}\n    for (rawBinding in rawBindings) {\n        if (text(rawBinding.enabled).toLowerCase() == \'false\') { continue }\n        var sourceName = text(first(rawBinding, [\'sourceField\', \'governanceField\'])).trim()\n        var targetName = text(rawBinding.targetField).trim()\n        var relation = sourceRelations[sourceName.toLowerCase()]\n        var expectedKind = text(rawBinding.ruleType).trim().toUpperCase()\n        if (relation == null || !safeIdentifier(targetName) || targetNames[targetName.toLowerCase()] == null\n            || seenTargets[targetName.toLowerCase()] != null\n            || (!blank(expectedKind) && expectedKind != relation.relationKind)) {\n            continue\n        }\n        result.add({ sourceField: relation.sourceName, targetField: targetName, relationKind: relation.relationKind,\n            sourceColumnId: text(rawBinding.sourceColumnId), targetColumnId: text(rawBinding.targetColumnId), legacy: false })\n        seenTargets[targetName.toLowerCase()] = true\n    }\n    // Reconcile incomplete imported binding metadata.  Do not overwrite an\n    // accepted explicit target above; only add a relation for an actual target\n    // translation column that does not yet have a valid binding.\n    for (targetColumn in (targetColumns == null ? [] : targetColumns)) {\n        var targetName = text(first(targetColumn, [\'columnName\', \'column_name\'])).trim()\n        if (!targetName.toLowerCase().endsWith(\'_cn\')) { continue }\n        var sourceName = targetName.substring(0, targetName.length() - 3)\n        var relation = sourceRelations[sourceName.toLowerCase()]\n        if (relation == null || seenTargets[targetName.toLowerCase()] != null) { continue }\n        result.add({ sourceField: relation.sourceName, targetField: targetName, relationKind: relation.relationKind,\n            sourceColumnId: text(first(targetColumn, [\'sourceTableColumnId\', \'source_table_column_id\'])),\n            targetColumnId: text(targetColumn.tid), legacy: true })\n        seenTargets[targetName.toLowerCase()] = true\n    }\n    return result\n}\n// 字典关联的附加条件（如 category_code=case_status）必须进入 NiFi 查询，\n// 否则同一通用码表会匹配到其他业务分类的错误表述。\nvar dictionaryLookupConditions = (relation) => {\n    var conditions = []\n    for (condition in (relation == null || relation.conditions == null ? [] : relation.conditions)) {\n        var field = text(condition.field).trim()\n        var operator = text(condition.operator).trim().toUpperCase()\n        var value = text(condition.value)\n        if (safeIdentifier(field) && (operator == \'=\' || operator == \'!=\' || operator == \'<>\'\n            || operator == \'>\' || operator == \'>=\' || operator == \'<\' || operator == \'<=\')) {\n            conditions.add(field + \' \' + operator + " \'" + value.replace("\'", "\'\'") + "\'")\n        } else if (safeIdentifier(field) && (operator == \'IN\' || operator == \'NOT IN\')) {\n            var values = []\n            for (rawValue in value.split(\',\')) {\n                var normalizedValue = text(rawValue).trim()\n                if (!blank(normalizedValue)) {\n                    values.add("\'" + normalizedValue.replace("\'", "\'\'") + "\'")\n                }\n            }\n            if (values.size() > 0) {\n                conditions.add(field + \' \' + operator + \' (\' + values.join(\', \') + \')\')\n            }\n        }\n    }\n    return conditions\n}\nvar readProp = (catalogId, name) => {\n    if (blank(catalogId)) {\n        return \'\'\n    }\n    var row = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', catalogId)\n        .eq(\'prop_name\', name)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    return row == null ? \'\' : text(row.propValue)\n}\nvar findCatalogBySource = (sourceTableId) => {\n    var props = db.table(\'da_prop_t\').where()\n        .eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', sourceTableId)\n        .eq(\'is_del\', 0)\n        .select()\n    for (prop in (props == null ? [] : props)) {\n        var asset = db.table(\'da_catalog_t\').where()\n            .eq(\'tid\', prop.parentId)\n            .eq(\'is_del\', 0)\n            .selectOne()\n        if (asset != null) {\n            return text(prop.parentId)\n        }\n    }\n    return \'\'\n}\nvar colName = (row) => first(row, [\'columnName\', \'column_name\'])\nvar readCfg = (row) => datasourceConnectionConfig(\'read\', first(row, [\'tid\']), null, false)\n// 数据上报/数据推送的数据文件已由上游落入 ODS 非结构化存储。\n// 创建任务时读取 fjghcc 域绑定的 FTP/SFTP，不能把其 api 类型误作数据拉取 API。\nvar pushAccessMode = (datasource, cfg) => {\n    var mode = first(cfg, [\'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\'])\n    if (blank(mode)) {\n        var pool = parseGovernanceConfig(first(datasource, [\'poolCfg\', \'pool_cfg\']))\n        mode = first(pool, [\'accessMode\', \'access_mode\', \'dataAccessMode\', \'data_access_mode\'])\n    }\n    return text(mode).trim().toLowerCase()\n}\nvar trimSlashes = (value) => {\n    var result = text(value).trim()\n    while (result.startsWith(\'/\')) { result = result.substring(1) }\n    while (result.endsWith(\'/\')) { result = result.substring(0, result.length() - 1) }\n    return result\n}\nvar resolveOdsPushFtp = (logicalDatasourceId, sourceTableName) => {\n    var binding = db.table(\'dwm_center_layer_source_t\').where()\n        .eq(\'target_type\', \'domain\').eq(\'layer_code\', \'fjghcc\').eq(\'is_del\', 0)\n        .orderBy(\'updated_time\', \'desc\').selectOne()\n    var bindingDatasourceId = binding == null ? \'\' : first(binding, [\'datasourceId\', \'datasource_id\'])\n    if (blank(bindingDatasourceId)) {\n        exit 400, \'资源中心 ODS 数据域 fjghcc 未绑定 FTP/SFTP 数据源\'\n    }\n    var storageId = text(bindingDatasourceId).trim()\n    var storage = db.table(\'db_datasource_t\').where().eq(\'tid\', storageId).eq(\'is_del\', 0).selectOne()\n    if (storage == null) { exit 404, \'资源中心 ODS 数据域 fjghcc 绑定的数据源不存在\' }\n    // readCfg is the same normalized/decrypted connection object used by normal task sources.\n    // Avoid re-merging heterogeneous config objects here: FTP fields are already authoritative in it.\n    var cfg = readCfg(storage)\n    if (cfg == null) { cfg = {} }\n    var dbType = text(first(storage, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])).trim().toUpperCase()\n    var protocol = text(first(cfg, [\'ftpProtocol\', \'ftp_protocol\', \'protocol\'])).trim().toLowerCase()\n    if ((dbType != \'FTP\' && dbType != \'SFTP\') || (protocol != \'\' && protocol != \'ftp\' && protocol != \'sftp\')) {\n        exit 400, \'资源中心 ODS 数据域 fjghcc 绑定的数据源不是 FTP/SFTP 类型\'\n    }\n    if (protocol == \'\') { protocol = dbType == \'SFTP\' ? \'sftp\' : \'ftp\' }\n    var root = text(first(cfg, [\'ftpPath\', \'ftp_path\', \'remotePath\', \'path\'])).trim()\n    while (root.endsWith(\'/\')) { root = root.substring(0, root.length() - 1) }\n    var sourceId = trimSlashes(logicalDatasourceId)\n    var table = trimSlashes(sourceTableName)\n    if (blank(root) || blank(sourceId) || blank(table) || sourceId.indexOf(\'..\') >= 0 || table.indexOf(\'..\') >= 0) {\n        exit 400, \'ODS FTP 根路径、来源数据源或来源表名配置无效\'\n    }\n    if (!root.startsWith(\'/\')) { root = \'/\' + root }\n    return { datasourceId: storageId, dbType: dbType, protocol: protocol, config: cfg, remotePath: root + \'/\' + sourceId + \'/\' + table + \'/\' }\n}\n// Dictionary records are allowed to live in another registered datasource.\n// Persist that exact connection in the lookup DSL so the canvas compiler does not\n// accidentally execute a dictionary query against the source table database.\nvar dictionaryLookupSource = (relation) => {\n    if (relation == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var dictionaryTableId = text(relation.dictionaryTableId).trim()\n    var dictionaryTable = blank(dictionaryTableId) ? null : db.table(\'db_table_t\').where()\n        .eq(\'tid\', dictionaryTableId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (dictionaryTable == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var datasourceId = text(first(dictionaryTable, [\'datasourceId\', \'datasource_id\'])).trim()\n    var datasource = blank(datasourceId) ? null : db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (datasource == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var cfg = readCfg(datasource)\n    var dbType = first(datasource, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\n    var database = first(cfg, [\'serviceName\', \'sid\', \'database\', \'dbName\', \'dbMetaDbName\'])\n    var schema = first(cfg, [\'defaultSchema\', \'schema\', \'currentSchema\', \'schemaName\', \'owner\', \'dbSchema\'])\n    if (blank(schema)) {\n        schema = first(dictionaryTable, [\'schemaName\', \'schema_name\', \'owner\', \'tableSchema\', \'table_schema\'])\n    }\n    return {\n        config: {\n            datasourceId: datasourceId,\n            dbType: dbType,\n            host: first(cfg, [\'host\', \'dbMetaIp\']),\n            port: first(cfg, [\'port\', \'dbMetaPort\']),\n            database: database,\n            jdbcUrl: jdbcUrl(dbType, cfg, datasource),\n            username: first(cfg, [\'username\', \'dbMetaUser\']),\n            password: first(cfg, [\'password\', \'dbMetaPassword\']),\n            defaultSchema: schema\n        },\n        schema: schema\n    }\n}\n// A registration may be re-probed and receive a new table ID while an already\n// saved field relation still carries the previous ID. Resolve the current,\n// active registered dictionary by name and datasource before rejecting a task.\nvar dictionaryLookupFallback = (relation, sourceTable) => {\n    if (relation == null || sourceTable == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var sourceDatasourceId = text(first(sourceTable, [\'datasourceId\', \'datasource_id\'])).trim()\n    var candidates = db.table(\'db_table_t\').where()\n        .eq(\'table_name\', relation.dictionaryTable)\n        .eq(\'is_del\', 0)\n        .select()\n    var dictionaryTable = null\n    for (candidate in (candidates == null ? [] : candidates)) {\n        var candidateDatasourceId = text(first(candidate, [\'datasourceId\', \'datasource_id\'])).trim()\n        if (!blank(sourceDatasourceId) && candidateDatasourceId == sourceDatasourceId) {\n            dictionaryTable = candidate\n            break\n        }\n        if (dictionaryTable == null) {\n            dictionaryTable = candidate\n        }\n    }\n    if (dictionaryTable == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var datasourceId = text(first(dictionaryTable, [\'datasourceId\', \'datasource_id\'])).trim()\n    var datasource = blank(datasourceId) ? null : db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', datasourceId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (datasource == null) {\n        return { config: {}, schema: \'\' }\n    }\n    var cfg = readCfg(datasource)\n    var dbType = first(datasource, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\n    var schema = first(cfg, [\'defaultSchema\', \'schema\', \'currentSchema\', \'schemaName\', \'owner\', \'dbSchema\'])\n    if (blank(schema)) {\n        schema = first(dictionaryTable, [\'schemaName\', \'schema_name\', \'owner\', \'tableSchema\', \'table_schema\'])\n    }\n    return {\n        config: {\n            datasourceId: datasourceId,\n            dbType: dbType,\n            host: first(cfg, [\'host\', \'dbMetaIp\']),\n            port: first(cfg, [\'port\', \'dbMetaPort\']),\n            database: first(cfg, [\'serviceName\', \'sid\', \'database\', \'dbName\', \'dbMetaDbName\']),\n            jdbcUrl: jdbcUrl(dbType, cfg, datasource),\n            username: first(cfg, [\'username\', \'dbMetaUser\']),\n            password: first(cfg, [\'password\', \'dbMetaPassword\']),\n            defaultSchema: schema\n        },\n        schema: schema,\n        tableId: text(dictionaryTable.tid)\n    }\n}\nvar normalizeSourceKey = (dbType, cfg) => {\n    var type = text(dbType).trim().toUpperCase()\n    if (type == \'MYSQL\') { return \'source.mysql\' }\n    if (type == \'TDSQL_MYSQL\') { return \'source.tdsql-mysql\' }\n    if (type == \'POSTGRES\' || type == \'POSTGRESQL\') { return \'source.postgresql\' }\n    if (type == \'GAUSSDB\' || type == \'OPENGAUSS\') { return \'source.gaussdb\' }\n    if (type == \'TDSQL_PG\') { return \'source.tdsql-pg\' }\n    if (type == \'ORACLE\' || type == \'ORACLE12\' || type == \'ORACLE_12\') { return \'source.oracle\' }\n    if (type == \'SQLSERVER\' || type == \'MSSQL\' || type == \'MS_SQL\') { return \'source.sqlserver\' }\n    if (type == \'MARIADB\') { return \'source.mariadb\' }\n    if (type == \'DB2\') { return \'source.db2\' }\n    if (type == \'DM\' || type == \'DAMENG\') { return \'source.dameng\' }\n    if (type == \'KINGBASE\') { return \'source.kingbase\' }\n    if (type == \'GBASE8A\') { return \'source.gbase8a\' }\n    if (type == \'GBASE8S\') { return \'source.gbase8s\' }\n    if (type == \'OSCAR\') { return \'source.oscar\' }\n    if (type == \'HIGHGO\') { return \'source.highgo\' }\n    if (type == \'HAILIANG\' || type == \'VASTBASE\') { return \'source.hailiang\' }\n    if (type == \'OCEANBASE\') { return \'source.oceanbase\' }\n    if (type == \'CLICKHOUSE\') { return \'source.clickhouse\' }\n    if (type == \'ELASTICSEARCH\') { return \'source.elasticsearch\' }\n    if (type == \'FTP\' || type == \'SFTP\') {\n        var ftpProtocol = text(first(cfg, [\'ftpProtocol\', \'ftp_protocol\', \'protocol\'])).trim().toLowerCase()\n        return type == \'SFTP\' || ftpProtocol == \'sftp\' ? \'source.sftp\' : \'source.ftp\'\n    }\n    if (type == \'MINIO\') { return \'source.minio\' }\n    return \'source.mysql\'\n}\nvar normalizeSinkType = (dbType) => {\n    var type = text(dbType).trim().toUpperCase()\n    if (type == \'DM\' || type == \'DAMENG\') { return \'DM\' }\n    if (type == \'MYSQL\' || type == \'TDSQL_MYSQL\') { return \'MySQL\' }\n    if (type == \'POSTGRES\' || type == \'POSTGRESQL\' || type == \'TDSQL_PG\' || type == \'GAUSSDB\' || type == \'OPENGAUSS\') { return \'PostgreSQL\' }\n    if (type == \'ORACLE\' || type == \'ORACLE12\' || type == \'ORACLE_12\') { return \'Oracle\' }\n    if (type == \'SQLSERVER\' || type == \'MSSQL\' || type == \'MS_SQL\') { return \'SQLSERVER\' }\n    if (type == \'KINGBASE\') { return \'KINGBASE\' }\n    if (type == \'GBASE8A\') { return \'GBASE8A\' }\n    if (type == \'GBASE8S\') { return \'GBASE8S\' }\n    if (type == \'OSCAR\') { return \'OSCAR\' }\n    if (type == \'HIGHGO\') { return \'HIGHGO\' }\n    if (type == \'OCEANBASE\') { return \'OCEANBASE\' }\n    if (type == \'CLICKHOUSE\') { return \'CLICKHOUSE\' }\n    if (type == \'ELASTICSEARCH\') { return \'ELASTICSEARCH\' }\n    return blank(dbType) ? \'MySQL\' : text(dbType)\n}\n// Huawei MRS Hive is a server-managed target.  Its registered datasource\n// intentionally has no browser-side jdbc_url, so the generated DSL must use\n// the dedicated Hive sink rather than falling into the generic JDBC sink.\nvar isServerManagedHuaweiMrsHive = (dbType, cfg) => {\n    if (text(dbType).trim().toUpperCase() != \'HIVE\') { return false }\n    var mode = text(first(cfg, [\'metadataAccessMode\', \'metadata_access_mode\'])).trim().toLowerCase()\n    var connectionMode = text(first(cfg, [\'hiveConnectionMode\', \'hive_connection_mode\'])).trim().toLowerCase()\n    var profile = text(first(cfg, [\'hiveProfile\', \'hive_profile\'])).trim()\n    return mode == \'server-managed-mrs\' || connectionMode == \'huawei-mrs\' || !blank(profile)\n}\nvar jdbcUrl = (dbType, cfg, row) => {\n    var url = first(cfg, [\'jdbcURL\', \'jdbcUrl\', \'url\'])\n    if (!blank(url)) { return text(url) }\n    var type = text(dbType).trim().toUpperCase()\n    var host = first(cfg, [\'host\', \'dbMetaIp\']) || first(row, [\'host\', \'db_meta_ip\']) || \'127.0.0.1\'\n    var port = first(cfg, [\'port\', \'dbMetaPort\']) || first(row, [\'port\', \'db_meta_port\'])\n    var database = first(cfg, [\'database\', \'serviceName\', \'sid\', \'dbName\', \'dbMetaDbName\']) || first(row, [\'dbName\', \'db_name\']) || \'\'\n    if (type == \'DM\' || type == \'DAMENG\') { return \'jdbc:dm://\' + host + \':\' + (blank(port) ? \'5236\' : port) + \'/\' + database }\n    if (type == \'ORACLE\' || type == \'ORACLE12\' || type == \'ORACLE_12\') {\n        var connectionType = text(first(cfg, [\'connectionType\', \'jdbcType\'])).trim().toUpperCase()\n        if (connectionType == \'SID\') {\n            return \'jdbc:oracle:thin:@\' + host + \':\' + (blank(port) ? \'1521\' : port) + \':\' + database\n        }\n        return \'jdbc:oracle:thin:@//\' + host + \':\' + (blank(port) ? \'1521\' : port) + \'/\' + database\n    }\n    if (type == \'KINGBASE\') { return \'jdbc:kingbase8://\' + host + \':\' + (blank(port) ? \'54321\' : port) + \'/\' + database }\n    if (type == \'POSTGRES\' || type == \'POSTGRESQL\') { return \'jdbc:postgresql://\' + host + \':\' + (blank(port) ? \'5432\' : port) + \'/\' + database }\n    return \'jdbc:mysql://\' + host + \':\' + (blank(port) ? \'3306\' : port) + \'/\' + database + \'?useSSL=false&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true\'\n}\nvar columnList = (rows) => {\n    var list = []\n    for (c in (rows == null ? [] : rows)) {\n        list.add({\n            columnName: colName(c),\n            columnComment: first(c, [\'columnComment\', \'column_comment\', \'comment\']),\n            dataType: first(c, [\'dataType\', \'data_type\', \'columnType\', \'column_type\']),\n            primaryKey: first(c, [\'primaryKey\', \'primary_key\', \'isPk\', \'is_pk\']),\n            isUnique: first(c, [\'isUnique\', \'is_unique\', \'unique\', \'uk\']),\n            ordinalPosition: first(c, [\'ordinalPosition\', \'ordinal_position\'])\n        })\n    }\n    return list\n}\nvar odsUuidExpression = "CAST(TIMESTAMPDIFF(SECOND, TIMESTAMP \'1970-01-01 00:00:00\', LOCALTIMESTAMP) AS VARCHAR) || CAST(100000000 + RAND_INTEGER(900000000) AS VARCHAR)"\nvar odsNowExpression = "LOCALTIMESTAMP"\nvar isOdsSystemColumn = (name) => {\n    var n = text(name).toUpperCase()\n    return n == \'ODS_UUID\' || n == \'ODS_RKSJ\' || n == \'ODS_GXSJ\'\n}\nvar odsSystemMapping = (name) => {\n    var n = text(name).toUpperCase()\n    if (n == \'ODS_UUID\') {\n        return {\n            expression: odsUuidExpression,\n            to: \'/ODS_UUID\',\n            comment: \'NiFi生成正数ODS主键（秒级时间戳加随机尾数）\'\n        }\n    }\n    if (n == \'ODS_RKSJ\') {\n        return {\n            expression: odsNowExpression,\n            to: \'/ODS_RKSJ\',\n            comment: \'NiFi写入当前入库时间\'\n        }\n    }\n    if (n == \'ODS_GXSJ\') {\n        return {\n            expression: odsNowExpression,\n            to: \'/ODS_GXSJ\',\n            comment: \'NiFi写入当前更新时间\'\n        }\n    }\n    return null\n}\nvar isStableBusinessKey = (column) => {\n    var name = text(colName(column)).toUpperCase()\n    if (name == \'ODS_UUID\') { return false }\n    var pk = text(first(column, [\'primaryKey\', \'primary_key\', \'isPrimaryKey\', \'is_primary_key\', \'isPk\', \'is_pk\']))\n    var unique = text(first(column, [\'isUnique\', \'is_unique\', \'unique\', \'uk\']))\n    return pk == \'1\' || pk.toLowerCase() == \'true\' || unique == \'1\' || unique.toLowerCase() == \'true\'\n}\nvar stableBusinessKeys = (rows) => {\n    var keys = []\n    for (c in (rows == null ? [] : rows)) {\n        if (isStableBusinessKey(c)) { keys.add(colName(c)) }\n    }\n    return keys\n}\nvar firstPk = (rows) => {\n    var keys = stableBusinessKeys(rows)\n    return keys.size() == 0 ? \'\' : keys[0]\n}\n// NiFi\'s ExecuteSQLRecord evaluates one split FlowFile at a time. JSON_TABLE\n// retains token position and duplicates; unknown codes remain visible when at\n// least one code resolves, matching the registration preview contract.\nvar multiSqlLiteral = (value) => "\'" + text(value).replace("\'", "\'\'") + "\'"\nvar mysqlMultiValueLookupSql = (targetName, dbType, dictionaryRows, separator) => {\n    var dialect = text(dbType).trim().toUpperCase()\n    if (dialect != \'MYSQL\') {\n        exit 400, \'多值翻译目前只支持 MySQL 8 字典或来源数据源；请勿按单值规则部署\'\n    }\n    var delimiter = text(separator)\n    if (blank(delimiter) || delimiter.length() > 8 || delimiter.indexOf(\'"\') >= 0\n        || delimiter.indexOf(\'\\\\\') >= 0) {\n        exit 400, \'多值翻译分隔符须为 1–8 个非引号、非反斜杠字符\'\n    }\n    return "SELECT CASE WHEN SUM(CASE WHEN dict.dict_name IS NOT NULL AND dict.dict_name <> \'\' "\n        + "THEN 1 ELSE 0 END) = 0 THEN NULL ELSE "\n        + \'GROUP_CONCAT(COALESCE(NULLIF(dict.dict_name, \\\'\\\'), TRIM(tokens.code)) \'\n        + \'ORDER BY tokens.ord SEPARATOR \' + multiSqlLiteral(delimiter) + \') END AS \' + targetName\n        + " FROM JSON_TABLE(CONCAT(\'[\', REPLACE(JSON_QUOTE(?), " + multiSqlLiteral(delimiter)\n        + ", CHAR(34,44,34)), \']\'), \'$[*]\' COLUMNS (ord FOR ORDINALITY, "\n        + "code VARCHAR(1024) PATH \'$\')) tokens LEFT JOIN " + dictionaryRows\n        + " dict ON CAST(dict.dict_code AS BINARY) = CAST(TRIM(tokens.code) AS BINARY) "\n        + "WHERE TRIM(tokens.code) <> \'\'"\n}\nvar mysqlStandardRows = (values) => {\n    var rows = []\n    for (value in values) {\n        rows.add(\'SELECT \' + multiSqlLiteral(value.code) + \' AS dict_code, \'\n            + multiSqlLiteral(value.label) + \' AS dict_name\')\n    }\n    if (rows.size() == 0) { exit 400, \'多值标准翻译缺少编码映射\' }\n    return \'(\' + rows.join(\' UNION ALL \') + \')\'\n}\nvar mysqlDictionaryRows = (relation, dictionaryName) => {\n    var conditions = dictionaryLookupConditions(relation)\n    return \'(SELECT \' + relation.dictionaryKeyField + \' AS dict_code, \'\n        + \'MAX(\' + relation.dictionaryLabelField + \') AS dict_name FROM \' + dictionaryName\n        + (conditions.size() == 0 ? \'\' : \' WHERE \' + conditions.join(\' AND \'))\n        + \' GROUP BY \' + relation.dictionaryKeyField + \')\'\n}\n\nvar mappingDsl = (sourceColumns, targetColumns, sourceTable, lookupSources, transformBindings, sourceLookupConfig) => {\n    var sourceNames = {}\n    var relations = dictionaryRelations(sourceTable)\n    for (c in (sourceColumns == null ? [] : sourceColumns)) {\n        sourceNames[text(colName(c)).toLowerCase()] = colName(c)\n    }\n    var bindingsByTarget = {}\n    for (binding in (transformBindings == null ? [] : transformBindings)) {\n        var bindingTargetName = text(binding.targetField).trim()\n        var bindingSourceName = text(binding.sourceField).trim()\n        // A binding is persisted metadata, so it may outlive a renamed/deleted\n        // column.  Ignore an incomplete binding instead of allowing it to\n        // interrupt creation of the entire access task.\n        if (blank(bindingTargetName) || blank(bindingSourceName)) { continue }\n        bindingsByTarget[bindingTargetName.toLowerCase()] = binding\n    }\n    var mappings = []\n    for (c in (targetColumns == null ? [] : targetColumns)) {\n        var name = colName(c)\n        var systemMapping = odsSystemMapping(name)\n        var binding = bindingsByTarget[text(name).toLowerCase()]\n        var sourceName = binding == null ? \'\' : text(binding.sourceField).trim()\n        var relation = blank(sourceName) ? null : relations[sourceName.toLowerCase()]\n        if (systemMapping != null) {\n            mappings.add(systemMapping)\n        } else if (relation != null && relation.relationKind == \'MANDATORY_STANDARD\' && safeIdentifier(name)) {\n            var standardValueMap = {}\n            for (standardValue in relation.standardValues) {\n                standardValueMap[standardValue.code] = standardValue.label\n            }\n            if (relation.multiValue) {\n                mappings.add({ from: \'/\' + relation.sourceName, to: \'/\' + name,\n                    lookup: { sql: mysqlMultiValueLookupSql(name, sourceLookupConfig.dbType,\n                            mysqlStandardRows(relation.standardValues), relation.multiValueSeparator),\n                        resultColumn: name, onMissing: \'NULL\', multiValue: true,\n                        multiValueSeparator: relation.multiValueSeparator, dataSource: sourceLookupConfig } })\n            } else {\n                mappings.add({ from: \'/\' + relation.sourceName, to: \'/\' + name,\n                    transform: { fn: \'enumMap\', args: [standardValueMap, null] } })\n            }\n        } else if (relation != null && relation.relationKind == \'DICTIONARY\' && safeIdentifier(name)) {\n            var dictionarySource = lookupSources[sourceName.toLowerCase()]\n            if (dictionarySource == null) {\n                dictionarySource = dictionaryLookupSource(relation)\n            }\n            if (dictionarySource == null || dictionarySource.config == null) {\n                exit 400, \'字段「\' + relation.sourceName + \'」关联的字典表未找到有效数据源配置，请检查数据源登记和字段关联配置\'\n            }\n            var dictionaryName = qualifiedDictionaryTable(relation, dictionarySource)\n            var lookupConditions = dictionaryLookupConditions(relation)\n            var lookupSql = \'SELECT \' + relation.dictionaryLabelField + \' AS \' + name\n                + \' FROM \' + dictionaryName + \' WHERE \' + relation.dictionaryKeyField + \' = ?\'\n            if (lookupConditions.size() > 0) {\n                lookupSql = lookupSql + \' AND \' + lookupConditions.join(\' AND \')\n            }\n            if (relation.multiValue) {\n                lookupSql = mysqlMultiValueLookupSql(name, dictionarySource.config.dbType,\n                    mysqlDictionaryRows(relation, dictionaryName), relation.multiValueSeparator)\n            }\n            mappings.add({\n                from: \'/\' + relation.sourceName,\n                to: \'/\' + name,\n                lookup: {\n                    sql: lookupSql,\n                    resultColumn: name,\n                    onMissing: \'NULL\',\n                    multiValue: relation.multiValue == true,\n                    multiValueSeparator: relation.multiValueSeparator,\n                    dataSource: dictionarySource.config\n                }\n            })\n        } else if (!blank(name) && sourceNames[text(name).toLowerCase()] != null) {\n            mappings.add({ from: \'/\' + name, to: \'/\' + name })\n        }\n    }\n    return jsons.toJSONStr({\n        version: \'1.0\',\n        passthroughUnmapped: false,\n        passthroughCaseSensitive: true,\n        onMissingSource: \'NULL\',\n        onTypeMismatch: \'SKIP_ROW\',\n        mappings: mappings\n    })\n}\n\nvar sourceTableId = text(body?.tableId || body?.sourceTableId || body?.tid).trim()\nvar tenantId = tenantRuntime.id()\n// Rebuilding an existing task is opt-in. Normal requests preserve a saved\n// pipeline even when a newer generator can produce richer mappings.\nvar forceRebuild = text(body?.repair || body?.forceRebuild || body?.rebuild).trim().toLowerCase()\nforceRebuild = forceRebuild == \'true\' || forceRebuild == \'1\' || forceRebuild == \'yes\'\nif (blank(sourceTableId)) {\n    exit 400, \'tableId不能为空\'\n}\n\nvar sourceTable = db.table(\'db_table_t\').where()\n    .eq(\'tid\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (sourceTable == null) {\n    exit 404, \'来源表不存在\'\n}\n\n// Validate dictionary metadata before retiring an existing task. Otherwise a\n// stale relation could delete a usable task and only then report the real issue.\nvar validatedDictionaryLookupSources = {}\nvar validatedDictionaryConfig = governanceConfigOf(sourceTable)\nfor (field in (validatedDictionaryConfig.fields == null ? [] : validatedDictionaryConfig.fields)) {\n    var relation = field.dictionaryRelation == null ? field.dictionary_relation : field.dictionaryRelation\n    var relationSourceName = text(first(field, [\'columnName\', \'column_name\'])).trim()\n    var relationSourceType = text(relation == null ? \'\' : relation.sourceType).trim().toLowerCase()\n    var standardValues = mandatoryStandardMappings(relation)\n    if (relation != null && text(relation.enabled).toLowerCase() != \'false\'\n        && safeIdentifier(relationSourceName) && standardValues.size() > 0) {\n        // Mandatory-standard mappings are embedded as a CASE/enumMap rule and\n        // intentionally do not need a dictionary datasource registration.\n        continue\n    }\n    var relationDictionaryReference = dictionaryTableReference(relation == null ? \'\' : relation.dictionaryTable)\n    if (relation == null || text(relation.enabled).toLowerCase() == \'false\' || relationSourceType == \'enum\'\n        || !safeIdentifier(relationSourceName) || !safeIdentifier(relationDictionaryReference.table)\n        || !safeIdentifier(text(relation.dictionaryKeyField).trim()) || !safeIdentifier(text(relation.dictionaryLabelField).trim())) {\n        continue\n    }\n    relation = {\n        sourceName: relationSourceName,\n        dictionaryTable: relationDictionaryReference.table,\n        dictionarySchema: relationDictionaryReference.schema,\n        dictionaryTableId: text(first(relation, [\'dictionaryTableId\', \'dictionary_table_id\'])).trim(),\n        dictionaryKeyField: text(relation.dictionaryKeyField).trim(),\n        dictionaryLabelField: text(relation.dictionaryLabelField).trim(),\n        conditions: relation.conditions == null ? [] : relation.conditions\n    }\n    var lookupSource = dictionaryLookupSource(relation)\n    if (lookupSource == null || lookupSource.config == null || blank(lookupSource.config.datasourceId)) {\n        lookupSource = dictionaryLookupFallback(relation, sourceTable)\n    }\n    if (lookupSource == null || lookupSource.config == null || blank(lookupSource.config.datasourceId)) {\n        exit 400, \'字段「\' + relation.sourceName + \'」关联的字典表「\' + relation.dictionaryTable\n            + \'」未找到有效登记数据源，请先在字典关联中重新选择已登记字典表\'\n    }\n    // Persist the repaired registration ID so the next task setup is direct.\n    if (!blank(lookupSource.tableId) && relation.dictionaryTableId != lookupSource.tableId) {\n        relation.dictionaryTableId = lookupSource.tableId\n    }\n    validatedDictionaryLookupSources[relation.sourceName.toLowerCase()] = lookupSource\n}\n\n// 一个来源表可以物化到多个目标数据源。db_table_t.source_table_id 是目标表\n// 与来源表的事实关联；目录中的 targetTableId 仅作为历史单目标数据的兼容回退。\nvar catalogId = text(body?.catalogId || sourceTable.sourceCatalogId || sourceTable.source_catalog_id)\nif (blank(catalogId)) {\n    catalogId = findCatalogBySource(sourceTableId)\n}\nvar materializedTargets = db.table(\'db_table_t\').where()\n    .eq(\'source_table_id\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .select()\nvar targetTables = []\nvar targetTableIds = []\nfor (candidateTarget in (materializedTargets == null ? [] : materializedTargets)) {\n    var candidateTargetId = text(first(candidateTarget, [\'tid\']))\n    if (!blank(candidateTargetId) && candidateTargetId != sourceTableId) {\n        targetTables.add(candidateTarget)\n        targetTableIds.add(candidateTargetId)\n        if (blank(catalogId)) {\n            catalogId = text(first(candidateTarget, [\'sourceCatalogId\', \'source_catalog_id\']))\n        }\n    }\n}\nif (targetTables.size() == 0) {\n    var legacyTargetTableId = readProp(catalogId, \'targetTableId\')\n    if (!blank(legacyTargetTableId)) {\n        var legacyTargetTable = db.table(\'db_table_t\').where()\n            .eq(\'tid\', legacyTargetTableId).eq(\'is_del\', 0).selectOne()\n        if (legacyTargetTable != null) {\n            targetTables.add(legacyTargetTable)\n            targetTableIds.add(legacyTargetTableId)\n        }\n    }\n}\nif (targetTables.size() == 0) {\n    exit 400, \'请先完成物化建表，生成至少一个目标表后才能创建接入任务\'\n}\n\n// A generated access task must have one mapping for every physical target\n// column.  A lower count means a previous batch failed part way through and\n// cannot be treated as an existing usable task.\nvar expectedMappingCount = 0\nfor (expectedTargetTable in targetTables) {\n    var expectedTargetTableId = text(first(expectedTargetTable, [\'tid\'])).trim()\n    if (!blank(expectedTargetTableId)) {\n        expectedMappingCount = expectedMappingCount + db.table(\'db_table_column_t\').where()\n            .eq(\'table_id\', expectedTargetTableId)\n            .eq(\'is_del\', 0)\n            .count()\n    }\n}\n\nvar exists = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'source_table_id\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .orderBy(\'updated_time\', \'desc\')\n    .selectOne()\nif (exists != null) {\n    var existingMappingCount = db.table(\'data_access_field_mapping\').where()\n        .eq(\'task_id\', exists.tid)\n        .eq(\'is_del\', 0)\n        .count()\n    var existingPipelineId = text(exists.pipelineId || exists.pipeline_id)\n    var existingPipeline = blank(existingPipelineId) ? null : db.table(\'nifi_pipeline_t\').where()\n        .eq(\'id\', existingPipelineId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    var existingDsl = existingPipeline == null ? \'\' : text(first(existingPipeline, [\'dslJson\', \'dsl_json\']))\n    // mappings is stored as an escaped JSON string inside the pipeline DSL, so\n    // quoted-token matching falsely reports a missing dataSource. Match the\n    // property names themselves; a real missing lookup still triggers repair.\n    var needsDictionaryLookupUpgrade = dictionaryRelations(sourceTable).size() > 0\n        && (existingDsl.indexOf(\'lookup\') < 0 || existingDsl.indexOf(\'dataSource\') < 0)\n    var needsTargetSinkUpgrade = false\n    for (expectedTargetTableId in targetTableIds) {\n        if (existingDsl.indexOf(text(expectedTargetTableId)) < 0) {\n            needsTargetSinkUpgrade = true\n            break\n        }\n    }\n    // A task with fewer mappings than target columns is not a usable\n    // user-owned task: it can only be left behind when this endpoint failed\n    // during its final mapping batch. Retire that incomplete pair and recreate\n    // it below. A complete task remains untouched, even when an upgrade is\n    // available.\n    // An explicit rebuild is an operator instruction to regenerate the\n    // registration-derived draft.  This is necessary after a source datasource\n    // or schema binding changes even when the previous mapping count and target\n    // sink still look structurally complete.\n    if (existingMappingCount < expectedMappingCount || forceRebuild) {\n        db.table(\'data_access_agg_task_t\').where().eq(\'tid\', exists.tid).update({\n            is_del: 1,\n            updated_time: now\n        })\n        if (existingPipeline != null) {\n            db.table(\'nifi_pipeline_t\').where().eq(\'id\', existingPipelineId).update({\n                is_del: 1,\n                updated_time: now\n            })\n        }\n    } else {\n    var repairReasons = []\n    if (existingPipeline == null) { repairReasons.add(\'关联流程不存在或已删除\') }\n    if (blank(existingDsl)) { repairReasons.add(\'关联流程没有可读取的画布定义\') }\n    if (needsDictionaryLookupUpgrade) { repairReasons.add(\'字典关联配置需要显式升级\') }\n    if (needsTargetSinkUpgrade) { repairReasons.add(\'目标表关联发生变化，需要显式确认重建\') }\n    return {\n        created: false,\n        taskId: exists.tid,\n        task: exists,\n        targetTableIds: targetTableIds,\n        repairRequired: repairReasons.size() > 0,\n        repairReasons: repairReasons\n    }\n    }\n}\n\nvar targetTable = targetTables[0]\nvar targetTableId = text(first(targetTable, [\'tid\']))\n\nvar sourceDbId = text(first(sourceTable, [\'datasourceId\', \'datasource_id\']))\nvar targetDbId = text(first(targetTable, [\'datasourceId\', \'datasource_id\']))\nvar sourceDb = db.table(\'db_datasource_t\').where().eq(\'tid\', sourceDbId).eq(\'is_del\', 0).selectOne()\nvar targetDb = db.table(\'db_datasource_t\').where().eq(\'tid\', targetDbId).eq(\'is_del\', 0).selectOne()\nvar sourceCfg = readCfg(sourceDb)\nvar targetCfg = readCfg(targetDb)\n\nvar sourceColumns = db.table(\'db_table_column_t\').where()\n    .eq(\'table_id\', sourceTableId)\n    .eq(\'is_del\', 0)\n    .orderBy(\'ordinal_position\', \'asc\')\n    .select()\nvar targetColumns = db.table(\'db_table_column_t\').where()\n    .eq(\'table_id\', targetTableId)\n    .eq(\'is_del\', 0)\n    .orderBy(\'ordinal_position\', \'asc\')\n    .select()\nvar sourceColumnMap = {}\nfor (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n    sourceColumnMap[text(colName(sourceColumn)).toLowerCase()] = sourceColumn\n}\nvar sourceDictionaryRelations = dictionaryRelations(sourceTable)\nvar dictionaryLookupSources = validatedDictionaryLookupSources\n\nvar now = new Date()\nvar nowMs = new Date().getTime()\nvar taskId = IdUtil.getSnowflakeNextIdStr()\nvar pipelineId = IdUtil.getSnowflakeNextIdStr()\nvar sourceTableName = first(sourceTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\nvar targetTableName = first(targetTable, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\nvar taskName = (first(sourceTable, [\'tableNameCn\', \'table_name_cn\', \'tableComment\', \'table_comment\']) || sourceTableName) + \'接入任务\'\nvar sourceDbType = first(sourceDb, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\nvar accessMode = pushAccessMode(sourceDb, sourceCfg)\nvar pushFileSource = (accessMode == \'receive\' || accessMode == \'upload\' || accessMode == \'push\')\n    ? resolveOdsPushFtp(sourceDbId, sourceTableName) : null\nvar targetDbType = first(targetDb, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\nvar sourceService = first(sourceCfg, [\'serviceName\', \'sid\', \'database\', \'dbName\', \'dbMetaDbName\'])\nvar sourceConnectionType = text(first(sourceCfg, [\'connectionType\', \'jdbcType\'])).trim().toUpperCase()\nif (sourceConnectionType != \'SID\') { sourceConnectionType = \'SERVICE_NAME\' }\nvar sourceSchema = first(sourceCfg, [\'defaultSchema\', \'schema\', \'currentSchema\', \'schemaName\', \'owner\', \'dbSchema\'])\nif (blank(sourceSchema)) {\n    sourceSchema = first(sourceTable, [\'schemaName\', \'schema_name\', \'owner\', \'tableSchema\', \'table_schema\'])\n}\nvar sourceJdbcUrl = jdbcUrl(sourceDbType, sourceCfg, sourceDb)\n\n// A valid explicit target binding is preferred.  Imported metadata may carry\n// an incomplete binding array though, so ensure every registered dictionary or\n// mandatory-standard source has its materialized <source>_cn output column.\nvar missingTranslationColumns = []\nfor (sourceColumn in (sourceColumns == null ? [] : sourceColumns)) {\n    var sourceName = text(colName(sourceColumn))\n    var relation = sourceDictionaryRelations[sourceName.toLowerCase()]\n    var translationName = relation == null ? \'\' : relation.sourceName + \'_cn\'\n    var targetColumnNames = {}\n    for (targetColumn in (targetColumns == null ? [] : targetColumns)) {\n        targetColumnNames[text(colName(targetColumn)).toLowerCase()] = true\n    }\n    if (relation != null && targetColumnNames[translationName.toLowerCase()] == null) {\n        missingTranslationColumns.add({\n            columnName: translationName,\n            sourceColumn: sourceColumn\n        })\n    }\n}\nif (missingTranslationColumns.size() > 0) {\n    if (targetTableId == sourceTableId) {\n        exit 400, \'目标表未物化为独立表，无法添加字典翻译字段，请先重新物化建表\'\n    }\n    var missingTranslationNames = []\n    for (translationColumn in missingTranslationColumns) {\n        missingTranslationNames.add(translationColumn.columnName)\n    }\n    var addedTranslationNames = targetTableSchema.ensureTranslationColumns({\n        jdbcUrl: jdbcUrl(targetDbType, targetCfg, targetDb),\n        username: first(targetCfg, [\'username\', \'dbMetaUser\']),\n        password: first(targetCfg, [\'password\', \'dbMetaPassword\'])\n    }, targetTableName, missingTranslationNames)\n    if (addedTranslationNames.size() > 0) {\n        var addedTranslationMap = {}\n        for (addedTranslationName in addedTranslationNames) {\n            addedTranslationMap[text(addedTranslationName).toLowerCase()] = true\n        }\n        var translationMetadata = []\n        var nextOrdinal = targetColumns == null ? 1 : targetColumns.size() + 1\n        for (translationColumn in missingTranslationColumns) {\n            var translationName = translationColumn.columnName\n            if (addedTranslationMap[translationName.toLowerCase()] != null) {\n                var sourceColumn = translationColumn.sourceColumn\n                translationMetadata.add({\n                    tid: IdUtil.getSnowflakeNextIdStr(),\n                    table_id: targetTableId,\n                    column_name: translationName,\n                    column_comment: text(first(sourceColumn, [\'columnComment\', \'column_comment\'])).trim() + \'翻译\',\n                    data_type: \'varchar\',\n                    column_type: \'varchar(255)\',\n                    length: 255,\n                    precision_length: 0,\n                    scale: 0,\n                    nullable: 1,\n                    default_value: null,\n                    primary_key: 0,\n                    auto_increment: 0,\n                    is_unique: 0,\n                    indexed: 0,\n                    ordinal_position: nextOrdinal,\n                    charset: null,\n                    collation: null,\n                    extra: null,\n                    source_table_column_id: sourceColumn.tid,\n                    is_del: 0,\n                    created_time: now,\n                    updated_time: now\n                })\n                nextOrdinal = nextOrdinal + 1\n            }\n        }\n        if (translationMetadata.size() > 0) {\n            metadataAsset.batchInsertTableColumns(translationMetadata)\n            db.table(\'db_table_t\').where().eq(\'tid\', targetTableId).eq(\'is_del\', 0)\n                .update({ field_count: targetColumns.size() + translationMetadata.size(), updated_time: now })\n            targetColumns = db.table(\'db_table_column_t\').where()\n                .eq(\'table_id\', targetTableId)\n                .eq(\'is_del\', 0)\n                .orderBy(\'ordinal_position\', \'asc\')\n                .select()\n        }\n    }\n}\n// This target-specific binding is authoritative for field enhancement.  It is\n// resolved after any legacy metadata refresh so the canvas sees final columns.\nvar targetFieldBindings = targetFieldTransformBindings(sourceTable, targetTable, targetColumns)\nvar targetBindingByField = {}\nfor (targetFieldBinding in targetFieldBindings) {\n    targetBindingByField[text(targetFieldBinding.targetField).toLowerCase()] = targetFieldBinding\n}\nvar sourceColumnsForNifi = columnList(sourceColumns)\nvar targetColumnsForNifi = columnList(targetColumns)\nvar primarySourceKeys = []\nvar primaryTargetKeys = []\nfor (targetColumn in (targetColumns == null ? [] : targetColumns)) {\n    var targetName = text(colName(targetColumn))\n    var sourceColumn = sourceColumnMap[targetName.toLowerCase()]\n    if (sourceColumn == null) {\n        var sourceColumnId = text(first(targetColumn, [\'sourceTableColumnId\', \'source_table_column_id\']))\n        if (!blank(sourceColumnId)) {\n            for (candidateSource in (sourceColumns == null ? [] : sourceColumns)) {\n                if (text(candidateSource.tid) == sourceColumnId) {\n                    sourceColumn = candidateSource\n                    break\n                }\n            }\n        }\n    }\n    if (sourceColumn != null && isStableBusinessKey(sourceColumn) && isStableBusinessKey(targetColumn)) {\n        primarySourceKeys.add(colName(sourceColumn))\n        primaryTargetKeys.add(targetName)\n    }\n}\nvar sourcePrimaryKeys = primarySourceKeys.join(\',\')\nvar targetPrimaryKeys = primaryTargetKeys.join(\',\')\nvar canUpsert = !blank(sourcePrimaryKeys) && !blank(targetPrimaryKeys)\n\n// 生成 data-element-nifi 可读取的基础画布草稿。来源和字段映射只保留一份，\n// 每个已物化目标表生成一个独立写入节点，字段映射后的 FlowFile 同时分发到所有目标。\nvar sourceNodeId = \'source-\' + sourceTableId\nvar mapNodeId = \'map-\' + taskId\nvar sourceNodeConfig = {\n    host: first(sourceCfg, [\'host\', \'dbMetaIp\']),\n    port: first(sourceCfg, [\'port\', \'dbMetaPort\']),\n    database: sourceService,\n    sid: sourceService,\n    serviceName: sourceService,\n    connectionType: sourceConnectionType,\n    jdbcUrl: sourceJdbcUrl,\n    defaultSchema: sourceSchema,\n    schema: sourceSchema,\n    username: first(sourceCfg, [\'username\', \'dbMetaUser\']),\n    password: first(sourceCfg, [\'password\', \'dbMetaPassword\']),\n    sourceDbId: sourceDbId,\n    sourceDbName: sourceDb == null ? \'\' : sourceDb.dbName,\n    sourceTableId: sourceTableId,\n    sourceTableName: sourceTableName,\n    table: sourceTableName,\n    sourceColumns: sourceColumnsForNifi,\n    incrementalColumn: firstPk(sourceColumns),\n    schedulingPeriod: \'60 sec\',\n    syncMode: \'FULL_THEN_INCR\',\n    initialStrategy: \'START_AT_BEGINNING\',\n    lookbackSeconds: 5,\n    safetyLagSeconds: 1,\n    batchSize: 5000,\n    maxRowsPerRun: 200000,\n    softDeleteEnabled: false,\n    deleteReconcileStrategy: \'NONE\'\n}\n// 普通 FTP/SFTP 探查接入也必须使用登记的连接，而不是 JDBC 默认配置。\n// 一条任务只读取其来源数据集，不能把目录里的其它表一起送入同一个目标。\nif (pushFileSource == null && (text(sourceDbType).trim().toLowerCase() == \'ftp\'\n        || text(sourceDbType).trim().toLowerCase() == \'sftp\')) {\n    var directProtocol = text(first(sourceCfg, [\'ftpProtocol\', \'ftp_protocol\', \'protocol\'])).trim().toLowerCase()\n    if (blank(directProtocol)) { directProtocol = text(sourceDbType).trim().toLowerCase() == \'sftp\' ? \'sftp\' : \'ftp\' }\n    var directPort = first(sourceCfg, [\'ftpPort\', \'ftp_port\', \'port\'])\n    if (blank(directPort)) { directPort = directProtocol == \'sftp\' ? 22 : 21 }\n    sourceNodeConfig = {\n        protocol: directProtocol,\n        hostname: first(sourceCfg, [\'ftpHost\', \'ftp_host\', \'hostname\', \'host\']),\n        port: directPort,\n        username: first(sourceCfg, [\'ftpUsername\', \'ftp_username\', \'username\']),\n        password: first(sourceCfg, [\'ftpPassword\', \'ftp_password\', \'password\']),\n        remotePath: first(sourceCfg, [\'ftpPath\', \'ftp_path\', \'remotePath\', \'path\']) || \'/\',\n        fileFilterRegex: \'(?i)^\\\\Q\' + text(sourceTableName) + \'\\\\E\\\\.(csv|json|xlsx|xls)$\',\n        passiveMode: first(sourceCfg, [\'ftpPassiveMode\', \'ftp_passive_mode\', \'passiveMode\']),\n        schedulingPeriod: \'60 sec\', syncMode: \'FULL\',\n        sourceDbId: sourceDbId, registeredDatasourceId: sourceDbId,\n        sourceDbName: sourceDb == null ? \'\' : sourceDb.dbName,\n        sourceTableId: sourceTableId, sourceTableName: sourceTableName, table: sourceTableName,\n        sourceColumns: sourceColumnsForNifi, fileHeaderMode: \'physical\'\n    }\n}\nif (pushFileSource != null) {\n    var ftpCfg = pushFileSource.config\n    var ftpPort = first(ftpCfg, [\'ftpPort\', \'ftp_port\', \'port\'])\n    if (blank(ftpPort)) { ftpPort = pushFileSource.protocol == \'sftp\' ? 22 : 21 }\n    var ftpFileFilter = first(ftpCfg, [\'ftpFilePattern\', \'ftp_file_pattern\', \'fileFilterRegex\', \'filePattern\'])\n    if (blank(ftpFileFilter)) { ftpFileFilter = \'.*\' }\n    sourceNodeConfig = {\n        protocol: pushFileSource.protocol,\n        hostname: first(ftpCfg, [\'ftpHost\', \'ftp_host\', \'hostname\', \'host\']),\n        port: ftpPort,\n        username: first(ftpCfg, [\'ftpUsername\', \'ftp_username\', \'username\']),\n        password: first(ftpCfg, [\'ftpPassword\', \'ftp_password\', \'password\']),\n        remotePath: pushFileSource.remotePath,\n        fileFilterRegex: ftpFileFilter,\n        passiveMode: first(ftpCfg, [\'ftpPassiveMode\', \'ftp_passive_mode\', \'passiveMode\']),\n        schedulingPeriod: \'60 sec\', syncMode: \'FULL\',\n        sourceDbId: sourceDbId, sourceDbName: sourceDb == null ? \'\' : sourceDb.dbName,\n        sourceTableId: sourceTableId, sourceTableName: sourceTableName, table: sourceTableName,\n        sourceColumns: sourceColumnsForNifi,\n        // 上传报送模板的 CSV/Excel 首行采用登记字段中文名；JSON 仍使用物理英文键。\n        fileHeaderMode: accessMode == \'upload\' ? \'registered-chinese\' : \'physical\',\n        registeredDatasourceId: pushFileSource.datasourceId,\n        logicalSourceDatasourceId: sourceDbId, pushStorageDomain: \'fjghcc\'\n    }\n}\n// API 拉取的请求、分页、增量与调度来自第一步的同一条 API 定义。这里仅在\n// 明确创建任务时读取并写入 NiFi 画布；不在第二步新增任何规则编辑入口。\nif (pushFileSource == null && text(sourceDbType).trim().toLowerCase() == \'api\') {\n    var apiRuntimeConfig = apiPullConfig.resolvePipelineSource(sourceDbId, text(sourceTableName))\n    for (apiKey in apiRuntimeConfig) { sourceNodeConfig[apiKey] = apiRuntimeConfig[apiKey] }\n    sourceNodeConfig.sourceDbId = sourceDbId\n    sourceNodeConfig.sourceDbName = sourceDb == null ? \'\' : sourceDb.dbName\n    sourceNodeConfig.sourceTableId = sourceTableId\n    sourceNodeConfig.sourceTableName = sourceTableName\n    sourceNodeConfig.table = sourceTableName\n    sourceNodeConfig.sourceColumns = sourceColumnsForNifi\n}\n// MinIO is an S3-compatible object store, not a JDBC database.  Preserve the\n// object-storage connection and the registered object key for the MinIO canvas\n// compiler; otherwise the generic MySQL fallback creates an empty task.\nif (text(sourceDbType).trim().toLowerCase() == \'minio\') {\n    var minioEndpoint = text(first(sourceCfg, [\'minioEndpoint\', \'endpoint\', \'url\'])).trim()\n    if (blank(minioEndpoint)) {\n        var minioUseSsl = text(first(sourceCfg, [\'minioUseSSL\', \'useSSL\'])).trim().toLowerCase() == \'true\'\n        minioEndpoint = (minioUseSsl ? \'https://\' : \'http://\')\n            + text(first(sourceCfg, [\'host\', \'dbMetaIp\'])).trim() + \':\'\n            + text(first(sourceCfg, [\'port\', \'dbMetaPort\'])).trim()\n    }\n    var minioObjectKey = text(first(sourceTable, [\'tableComment\', \'table_comment\'])).trim()\n    if (minioObjectKey.indexOf(\'MinIO对象 \') == 0) {\n        minioObjectKey = minioObjectKey.substring(8)\n    } else {\n        minioObjectKey = \'\'\n    }\n    sourceNodeConfig.minioEndpoint = minioEndpoint\n    sourceNodeConfig.minioAccessKey = first(sourceCfg, [\'minioAccessKey\', \'accessKey\', \'username\', \'dbMetaUser\'])\n    sourceNodeConfig.minioSecretKey = first(sourceCfg, [\'minioSecretKey\', \'secretKey\', \'password\', \'dbMetaPassword\'])\n    sourceNodeConfig.minioBucket = first(sourceCfg, [\'minioBucket\', \'bucket\', \'database\', \'dbName\', \'serviceName\'])\n    sourceNodeConfig.minioPrefix = first(sourceCfg, [\'minioPrefix\', \'objectPrefix\', \'prefix\'])\n    sourceNodeConfig.minioFilePattern = first(sourceCfg, [\'minioFilePattern\', \'filePattern\', \'fileFilterRegex\'])\n    sourceNodeConfig.minioObjectKey = minioObjectKey\n    sourceNodeConfig.syncMode = \'FULL\'\n}\nvar dslNodes = [\n    {\n        id: sourceNodeId,\n        manifestKey: pushFileSource == null ? normalizeSourceKey(sourceDbType, sourceCfg) : normalizeSourceKey(pushFileSource.dbType, pushFileSource.config),\n        label: pushFileSource == null ? \'来源表\' : \'FTP 文件来源\',\n        category: \'source\',\n        x: 0,\n        y: 120,\n        config: sourceNodeConfig\n    },\n    {\n        id: mapNodeId,\n        // New access tasks use the unified component by default.  It remains\n        // compatible with the existing mapping DSL while adding dictionary\n        // translation, standard-format processing and source-SQL pushdown.\n        manifestKey: \'transform.field-enrichment\',\n        label: \'字段增强\',\n        category: \'transform\',\n        x: 540,\n        y: 120,\n        config: {\n            sourceTableId: sourceTableId,\n            targetTableId: targetTableId,\n            executionMode: \'AUTO\',\n            mappings: mappingDsl(sourceColumns, targetColumns, sourceTable, dictionaryLookupSources,\n                targetFieldBindings, { datasourceId: sourceDbId, dbType: sourceDbType })\n        }\n    }\n]\nvar dslEdges = [{ id: \'edge-source-map\', source: sourceNodeId, target: mapNodeId, outlet: null }]\nvar targetSummaries = []\nfor (targetIndex, targetCandidate in targetTables) {\n    var candidateTargetId = text(first(targetCandidate, [\'tid\']))\n    var candidateTargetDbId = text(first(targetCandidate, [\'datasourceId\', \'datasource_id\']))\n    var candidateTargetDb = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', candidateTargetDbId).eq(\'is_del\', 0).selectOne()\n    if (candidateTargetDb == null) {\n        exit 404, \'目标数据源不存在：\' + candidateTargetDbId\n    }\n    var candidateTargetCfg = readCfg(candidateTargetDb)\n    var candidateTargetDbType = first(candidateTargetDb, [\'dbType\', \'db_type\', \'databaseType\', \'database_type\'])\n    var candidateTargetTableName = first(targetCandidate, [\'tableName\', \'table_name\', \'tableNameEn\', \'table_name_en\'])\n    var candidateTargetColumns = db.table(\'db_table_column_t\').where()\n        .eq(\'table_id\', candidateTargetId).eq(\'is_del\', 0)\n        .orderBy(\'ordinal_position\', \'asc\').select()\n    var candidateTargetKeys = []\n    for (candidateTargetColumn in (candidateTargetColumns == null ? [] : candidateTargetColumns)) {\n        var candidateTargetName = text(colName(candidateTargetColumn))\n        var matchingSourceColumn = sourceColumnMap[candidateTargetName.toLowerCase()]\n        // 写入幂等性由目标表的业务主键/唯一键决定。来源表的登记元数据\n        // 可能尚未标记 primaryKey（例如历史探查数据），但只要该目标键已有\n        // 对应的来源字段映射，就可以安全地作为 UPSERT 键，不能退回 INSERT。\n        if (matchingSourceColumn != null && isStableBusinessKey(candidateTargetColumn)) {\n            candidateTargetKeys.add(candidateTargetName)\n        }\n    }\n    var candidateTargetPrimaryKeys = candidateTargetKeys.join(\',\')\n    var candidateSinkId = \'sink-\' + candidateTargetId\n    var candidateIsHuaweiMrsHive = isServerManagedHuaweiMrsHive(candidateTargetDbType, candidateTargetCfg)\n    var candidateSinkManifestKey = candidateIsHuaweiMrsHive ? \'sink.hive\' : \'sink.jdbc\'\n    var candidateSinkConfig = {}\n    if (candidateIsHuaweiMrsHive) {\n        var candidateHiveDatabase = first(candidateTargetCfg, [\'database\', \'dbName\', \'dbMetaDbName\', \'serviceName\'])\n        if (blank(candidateHiveDatabase)) {\n            exit 400, \'华为 MRS Hive 目标数据源缺少已登记的 Hive 数据库名：\' + candidateTargetDbId\n        }\n        candidateSinkConfig = {\n            // Keep only the tenant-owned datasource reference and the logical\n            // MRS profile here.  The compiler resolves keytab, krb5.conf and\n            // HiveServer2/ZooKeeper settings on the server at deployment time.\n            dbType: \'HIVE\',\n            targetDbId: candidateTargetDbId,\n            targetDbName: candidateTargetDb.dbName,\n            targetTableId: candidateTargetId,\n            hiveProfile: first(candidateTargetCfg, [\'hiveProfile\', \'hive_profile\']) || \'default\',\n            hiveConnectionMode: \'huawei-mrs\',\n            metadataAccessMode: \'server-managed-mrs\',\n            database: candidateHiveDatabase,\n            targetTableName: candidateTargetTableName,\n            table: candidateTargetTableName,\n            schema: first(candidateTargetCfg, [\'schema\', \'defaultSchema\', \'currentSchema\', \'schemaName\'])\n                || first(targetCandidate, [\'schemaName\', \'schema_name\'])\n                || ((normalizeSinkType(candidateTargetDbType) == \'DM\') ? first(candidateTargetCfg, [\'database\', \'databaseName\']) : null),\n            targetColumns: columnList(candidateTargetColumns),\n            // Materialized Hive tables use the dedicated standard writer;\n            // generic JDBC UPSERT is not a valid Hive write operation.\n            hiveWriteMode: \'HIVE_RECORD_PUT\',\n            statementType: \'INSERT\',\n            updateKeys: \'\'\n        }\n    } else {\n        candidateSinkConfig = {\n            dbType: normalizeSinkType(candidateTargetDbType),\n            jdbcUrl: jdbcUrl(candidateTargetDbType, candidateTargetCfg, candidateTargetDb),\n            username: first(candidateTargetCfg, [\'username\', \'dbMetaUser\']),\n            password: first(candidateTargetCfg, [\'password\', \'dbMetaPassword\']),\n            targetDbId: candidateTargetDbId,\n            targetDbName: candidateTargetDb.dbName,\n            targetTableId: candidateTargetId,\n            targetTableName: candidateTargetTableName,\n            table: candidateTargetTableName,\n            targetColumns: columnList(candidateTargetColumns),\n            statementType: candidateTargetPrimaryKeys == \'\' ? \'INSERT\' : \'UPSERT\',\n            updateKeys: candidateTargetPrimaryKeys\n        }\n    }\n    dslNodes.add({\n        id: candidateSinkId,\n        manifestKey: candidateSinkManifestKey,\n        label: targetTables.size() > 1 ? \'目标表 \' + (targetIndex + 1) : \'目标表\',\n        category: \'sink\',\n        x: 1080,\n        y: 120 + targetIndex * 300,\n        config: candidateSinkConfig\n    })\n    dslEdges.add({ id: \'edge-map-sink-\' + candidateTargetId, source: mapNodeId, target: candidateSinkId, outlet: null })\n    targetSummaries.add({\n        targetTableId: candidateTargetId,\n        targetTableName: candidateTargetTableName,\n        targetDbId: candidateTargetDbId,\n        targetDbName: candidateTargetDb.dbName,\n        targetDbType: candidateTargetDbType\n    })\n}\nvar dsl = { version: 1, nodes: dslNodes, edges: dslEdges }\ndb.table(\'nifi_pipeline_t\').primary(\'id\').insert({\n    id: pipelineId,\n    tenant_id: tenantId,\n    name: taskName,\n    description: \'由数据接入页面按来源表自动创建\',\n    status: \'SAVED\',\n    dsl_json: jsons.toJSONStr(dsl),\n    dsl_version: 1,\n    created_at: nowMs,\n    updated_at: nowMs,\n    is_del: 0\n})\n\ndb.table(\'data_access_agg_task_t\').primary(\'tid\').insert({\n    tid: taskId,\n    tenant_id: tenantId,\n    data_catalog_id: catalogId,\n    task_name: taskName,\n    task_type_name: \'数据表接入\',\n    task_type_id: \'table_access\',\n    task_desc: \'来源表自动创建接入任务\',\n    source_db_id: sourceDbId,\n    source_table_id: sourceTableId,\n    source_table_primary_key: sourcePrimaryKeys,\n    target_db_id: targetDbId,\n    target_table_id: targetTableId,\n    target_table_primary_key: targetPrimaryKeys,\n    schedule_strategy: 0,\n    schedule_cycle: 0,\n    task_status: 0,\n    pipeline_id: pipelineId,\n    created_time: now,\n    updated_time: now,\n    is_del: 0\n})\n\nvar mappings = []\nfor (targetIndex, targetColumn in (targetColumns == null ? [] : targetColumns)) {\n    var targetName = text(colName(targetColumn))\n    var systemMapping = odsSystemMapping(targetName)\n    if (systemMapping != null) {\n        mappings.add({\n            tid: IdUtil.getSnowflakeNextIdStr(),\n            task_id: taskId,\n            source_field: \'SYSTEM:\' + targetName,\n            source_field_cn: \'NiFi系统字段\',\n            source_field_length: 0,\n            source_data_type: \'SYSTEM_EXPRESSION\',\n            target_field: targetName,\n            target_field_cn: first(targetColumn, [\'columnComment\', \'column_comment\']),\n            target_field_length: first(targetColumn, [\'length\']),\n            target_data_type: first(targetColumn, [\'dataType\', \'data_type\']),\n            dict_enable: 0,\n            func_enable: 1,\n            func_code: \'EXPRESSION\',\n            func_value: systemMapping.expression,\n            sort_no: targetIndex,\n            is_del: 0,\n            created_time: now,\n            updated_time: now\n        })\n        continue\n    }\n    var targetBinding = targetBindingByField[targetName.toLowerCase()]\n    var dictionarySourceName = targetBinding == null ? \'\' : text(targetBinding.sourceField).trim()\n    var dictionaryRelation = blank(dictionarySourceName) ? null\n        : sourceDictionaryRelations[dictionarySourceName.toLowerCase()]\n    if (dictionaryRelation != null) {\n        var dictionarySourceColumn = sourceColumnMap[text(dictionaryRelation.sourceName).toLowerCase()]\n        if (dictionarySourceColumn != null && dictionaryRelation.relationKind == \'MANDATORY_STANDARD\') {\n            var standardValueMap = {}\n            for (standardValue in dictionaryRelation.standardValues) {\n                standardValueMap[standardValue.code] = standardValue.label\n            }\n            mappings.add({\n                tid: IdUtil.getSnowflakeNextIdStr(),\n                task_id: taskId,\n                source_field: colName(dictionarySourceColumn),\n                source_field_cn: first(dictionarySourceColumn, [\'columnComment\', \'column_comment\']),\n                source_field_length: first(dictionarySourceColumn, [\'length\']),\n                source_data_type: first(dictionarySourceColumn, [\'dataType\', \'data_type\']),\n                target_field: targetName,\n                target_field_cn: first(targetColumn, [\'columnComment\', \'column_comment\']),\n                target_field_length: first(targetColumn, [\'length\']),\n                target_data_type: first(targetColumn, [\'dataType\', \'data_type\']),\n                dict_enable: 0,\n                func_enable: 1,\n                func_code: \'ENUM_MAP\',\n                // Persist the executable map, not merely a marker.  The canvas\n                // may be opened before deployment, so the enhanced component\n                // must be able to restore every mandatory-standard category.\n                func_value: jsons.toJSONStr({ ruleKind: \'MANDATORY_STANDARD\', values: standardValueMap,\n                    multiValue: dictionaryRelation.multiValue == true,\n                    multiValueSeparator: dictionaryRelation.multiValueSeparator }),\n                sort_no: targetIndex,\n                is_del: 0,\n                created_time: now,\n                updated_time: now\n            })\n            continue\n        }\n        if (dictionarySourceColumn != null && dictionaryRelation.relationKind == \'DICTIONARY\') {\n            var dictionaryDatasource = dictionaryLookupSources[dictionarySourceName.toLowerCase()]\n            if (dictionaryDatasource == null) {\n                dictionaryDatasource = dictionaryLookupSource(dictionaryRelation)\n            }\n            if (dictionaryDatasource == null || dictionaryDatasource.config == null) {\n                exit 400, \'字段「\' + dictionaryRelation.sourceName + \'」关联的字典表未找到有效数据源配置，请检查数据源登记和字段关联配置\'\n            }\n            var dictionaryName = qualifiedDictionaryTable(dictionaryRelation, dictionaryDatasource)\n            var dictionaryConditions = dictionaryLookupConditions(dictionaryRelation)\n            var dictionaryLookupSql = \'SELECT \' + dictionaryRelation.dictionaryLabelField + \' AS \' + targetName\n                + \' FROM \' + dictionaryName + \' WHERE \' + dictionaryRelation.dictionaryKeyField + \' = ?\'\n            if (dictionaryConditions.size() > 0) {\n                dictionaryLookupSql = dictionaryLookupSql + \' AND \' + dictionaryConditions.join(\' AND \')\n            }\n            if (dictionaryRelation.multiValue) {\n                dictionaryLookupSql = mysqlMultiValueLookupSql(targetName, dictionaryDatasource.config.dbType,\n                    mysqlDictionaryRows(dictionaryRelation, dictionaryName),\n                    dictionaryRelation.multiValueSeparator)\n            }\n            mappings.add({\n                tid: IdUtil.getSnowflakeNextIdStr(),\n                task_id: taskId,\n                source_field: colName(dictionarySourceColumn),\n                source_field_cn: first(dictionarySourceColumn, [\'columnComment\', \'column_comment\']),\n                source_field_length: first(dictionarySourceColumn, [\'length\']),\n                source_data_type: first(dictionarySourceColumn, [\'dataType\', \'data_type\']),\n                target_field: targetName,\n                target_field_cn: first(targetColumn, [\'columnComment\', \'column_comment\']),\n                target_field_length: first(targetColumn, [\'length\']),\n                target_data_type: first(targetColumn, [\'dataType\', \'data_type\']),\n                dict_enable: 1,\n                dict_value: dictionaryRelation.dictionaryTable,\n                dict_code: dictionaryRelation.dictionaryKeyField + \'->\' + dictionaryRelation.dictionaryLabelField,\n                func_enable: 1,\n                func_code: \'LOOKUP\',\n                // Some deployed metadata schemas keep func_value as VARCHAR.\n                // The complete executable contract belongs to the pipeline DSL\n                // above; persist a compact, backward-compatible summary here\n                // so the mapping batch cannot fail after the pipeline exists.\n                func_value: dictionaryRelation.multiValue\n                    ? jsons.toJSONStr({ ruleKind: \'DICTIONARY\', table: dictionaryRelation.dictionaryTable,\n                        keyField: dictionaryRelation.dictionaryKeyField,\n                        labelField: dictionaryRelation.dictionaryLabelField,\n                        sql: dictionaryLookupSql, multiValue: true,\n                        multiValueSeparator: dictionaryRelation.multiValueSeparator,\n                        dataSource: { datasourceId: dictionaryDatasource.config.datasourceId,\n                            dbType: dictionaryDatasource.config.dbType } })\n                    : dictionaryRelation.dictionaryTable + \':\'\n                        + dictionaryRelation.dictionaryKeyField + \'->\' + dictionaryRelation.dictionaryLabelField,\n                sort_no: targetIndex,\n                is_del: 0,\n                created_time: now,\n                updated_time: now\n            })\n            continue\n        }\n    }\n    var sourceColumn = sourceColumnMap[targetName.toLowerCase()]\n    if (sourceColumn == null && targetColumn.sourceTableColumnId != null) {\n        for (candidateSource in (sourceColumns == null ? [] : sourceColumns)) {\n            if (text(candidateSource.tid) == text(targetColumn.sourceTableColumnId)) {\n                sourceColumn = candidateSource\n            }\n        }\n    }\n    if (sourceColumn == null) {\n        continue\n    }\n    mappings.add({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        task_id: taskId,\n        source_field: colName(sourceColumn),\n        source_field_cn: first(sourceColumn, [\'columnComment\', \'column_comment\']),\n        source_field_length: first(sourceColumn, [\'length\']),\n        source_data_type: first(sourceColumn, [\'dataType\', \'data_type\']),\n        target_field: targetName,\n        target_field_cn: first(targetColumn, [\'columnComment\', \'column_comment\']),\n        target_field_length: first(targetColumn, [\'length\']),\n        target_data_type: first(targetColumn, [\'dataType\', \'data_type\']),\n        dict_enable: 0,\n        func_enable: 0,\n        sort_no: targetIndex,\n        is_del: 0,\n        created_time: now,\n        updated_time: now\n    })\n}\nif (mappings.size() > 0) {\n    for (mapping in mappings) { mapping.tenant_id = tenantId }\n    db.table(\'data_access_field_mapping\').batchInsert(mappings)\n}\n\nvar task = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'tid\', taskId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nreturn {\n    created: true,\n    taskId: taskId,\n    pipelineId: pipelineId,\n    catalogId: catalogId,\n    sourceTableId: sourceTableId,\n    targetTableId: targetTableId,\n    targetTableIds: targetTableIds,\n    targetTables: targetSummaries,\n    task: task\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/13.按来源表补齐接入任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('28ee5d9e32e04dfa8438756b9302b5de',NULL,NULL,'{\n  "properties": {},\n  "id": "28ee5d9e32e04dfa8438756b9302b5de",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "14.获取etl任务分组",\n  "createTime": 1782955344758,\n  "updateTime": 1784437771801,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "getEtlGroup",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"rootId\\": \\"root\\",\\n        \\"tree\\": [\\n            {\\n                \\"id\\": \\"8dba3ae7-019c-1000-ffff-ffff8762908e\\",\\n                \\"name\\": \\"1111\\",\\n                \\"label\\": \\"1111\\",\\n                \\"value\\": \\"8dba3ae7-019c-1000-ffff-ffff8762908e\\",\\n                \\"parentId\\": \\"21a49dad-019c-1000-e2ca-0d4d12775733\\",\\n                \\"children\\": []\\n            },\\n            {\\n                \\"id\\": \\"925ce836-019c-1000-ffff-ffffd3d25742\\",\\n                \\"name\\": \\"test\\",\\n                \\"label\\": \\"test\\",\\n                \\"value\\": \\"925ce836-019c-1000-ffff-ffffd3d25742\\",\\n                \\"parentId\\": \\"21a49dad-019c-1000-e2ca-0d4d12775733\\",\\n                \\"children\\": [\\n                    {\\n                        \\"id\\": \\"9dca35d6-019c-1000-ffff-fffffe895a4f\\",\\n                        \\"name\\": \\"123\\",\\n                        \\"label\\": \\"123\\",\\n                        \\"value\\": \\"9dca35d6-019c-1000-ffff-fffffe895a4f\\",\\n                        \\"parentId\\": \\"925ce836-019c-1000-ffff-ffffd3d25742\\",\\n                        \\"children\\": [\\n                            {\\n                                \\"id\\": \\"9dca5b07-019c-1000-0000-00005b404356\\",\\n                                \\"name\\": \\"123456\\",\\n                                \\"label\\": \\"123456\\",\\n                                \\"value\\": \\"9dca5b07-019c-1000-0000-00005b404356\\",\\n                                \\"parentId\\": \\"9dca35d6-019c-1000-ffff-fffffe895a4f\\",\\n                                \\"children\\": []\\n                            }\\n                        ]\\n                    }\\n                ]\\n            }\\n        ]\\n    }\\n}",\n  "description": "获取 NiFi 接入任务分组树。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：14.获取etl任务分组\n// 路由：GET /ods/getEtlGroup\n// 业务说明：获取 NiFi 接入任务分组树。\n/*\n * 获取 NiFi 接入任务分组树\n *\n * Magic 负责递归编排和页面结构组装，NifiClient 只负责认证后的运行时调用。\n * 根分组读取现有配置，未配置时按 NiFi root 处理。\n */\nimport com.fasterxml.jackson.databind.JsonNode\nimport com.linewell.dataelement.integration.nifi.canvas.nifi.NifiClient as nifiClient\nimport \'@/common/configData\' as configData\n\nvar configuredRoot = configData().nifi_gourpId\nvar rootId = configuredRoot == null || configuredRoot == \'\' ? \'root\' : configuredRoot\nvar loadChildren\nloadChildren = (processGroupId, parentId) => {\n    var response = nifiClient.get(\'/process-groups/\' + processGroupId + \'/process-groups\', JsonNode.class)\n    var result = []\n    var groups = response.path(\'processGroups\')\n    if (groups.isArray()) {\n        for (item in groups) {\n            var id = item.path(\'id\').asText()\n            var name = item.path(\'component\').path(\'name\').asText()\n            result.add({\n                id: id,\n                name: name,\n                label: name,\n                value: id,\n                parentId: parentId,\n                children: loadChildren(id, id)\n            })\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return result\n}\n\n// 返回当前业务分支的标准结果。\nreturn loadChildren(\'root\', rootId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/14.获取etl任务分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : {\r\n    "huaweiHiveTargetDeletion" : "magic-gateway-v2"\r\n  },\r\n  "id" : "ods_data_agg_reset_01",\r\n  "script" : null,\r\n  "groupId" : "1f4028f20aaa4f379b5e37a343b99fa9",\r\n  "name" : "15.取消接入流程与删除目标表",\r\n  "createTime" : 1786615200000,\r\n  "updateTime" : 1790955212007,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/dataAggReset",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n  \\"sourceTableId\\": \\"2087688601765228544\\",\\n  \\"deleteTargetTable\\": true\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "取消或重建数据接入；仅清理当前租户所选来源表关联的目标和流程。华为 MRS Hive 从登记配置读取配置集与数据库名，调用 23.华为MRSHive元数据网关执行 SHOW TABLES、确认删表与删除后校验，不要求登记 JDBC 地址或元数据库连接。dryRun=true 只读预检；使用请求参数 sourceTableId、tableId、tid、deleteTargetTable、dryRun、targetTableId、target_table_id、targetDbId；涉及 db_table_t、data_access_agg_task_t、db_datasource_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：15.取消接入流程与删除目标表\n// 路由：POST /ods/dataAggReset\n// 业务说明：取消或重建数据接入；仅清理当前租户所选来源表关联的目标和流程。华为 MRS Hive 从登记配置读取配置集与数据库名，使用服务端连接执行 SHOW TABLES、DROP TABLE 与删除后校验，不要求登记 JDBC 地址或元数据库连接。dryRun=true 只读预检；使用请求参数 sourceTableId、tableId、tid、deleteTargetTable、dryRun、targetTableId、target_table_id、targetDbId；涉及 db_table_t、data_access_agg_task_t、db_datasource_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\nimport \'@post:/dst/database/metadata/huaweiMrsHiveJdbcDebug\' as huaweiHiveGateway\n/*\n * Rebuild recovery for a source table.\n * The operation is deliberately source-scoped so one table cannot remove another\n * table\'s target metadata or deployed pipeline.\n * Huawei MRS Hive uses the registered server-owned profile, without browser JDBC\n * credentials or a Metastore connection. dryRun=true only probes physical state.\n */\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.integration.nifi.canvas.nifi.NifiClient as nifiClient\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.TargetTableDeletionService as targetTableDeletionService\nimport java.util.Map\nimport log\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar first = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (!blank(value)) { return value }\n    }\n    return null\n}\nvar safeTableName = (value) => text(value).trim().matches(\'^[A-Za-z_][A-Za-z0-9_]*(\\\\.[A-Za-z_][A-Za-z0-9_]*)?$\')\n// The metadata gateway owns the server-side MRS connection; this API only verifies\n// that the selected target belongs to the source task before asking it to act.\nvar managedHiveOf = (config) => config != null && config.getDatabaseType() == DatabaseType.HIVE\n    && text(config.getConnectorProperties()?.get(\'metadataAccessMode\')) == \'server-managed-mrs\'\nvar callHiveGateway = (request) => {\n    var originalBody = body\n    try {\n        body = request\n        var response = huaweiHiveGateway()\n        if (response == null || response.success != true) {\n            throw new IllegalStateException(\'华为 MRS Hive 元数据网关调用失败\')\n        }\n        return response\n    } finally {\n        body = originalBody\n    }\n}\nvar hivePreflight = (config, requestedName) => {\n    var scope = text(config.getDatabase()).trim()\n    if (!scope.matches(\'^[A-Za-z_][A-Za-z0-9_]*$\')) {\n        throw new IllegalArgumentException(\'Hive 目标数据库名不合法\')\n    }\n    var profile = text(config.getConnectorProperties()?.get(\'hiveProfile\')).trim()\n    if (profile != \'\' && profile.toLowerCase() != \'default\') {\n        throw new IllegalArgumentException(\'未配置的华为 MRS Hive 配置集: \' + profile)\n    }\n    var name = text(requestedName).trim()\n    var separator = name.indexOf(\'.\')\n    if (separator >= 0) {\n        var requestedScope = name.substring(0, separator)\n        if (requestedScope.toLowerCase() != scope.toLowerCase()) {\n            throw new IllegalArgumentException(\'目标表所属数据库或 Schema 与所选目标数据源不一致：\' + scope)\n        }\n        name = name.substring(separator + 1)\n    }\n    if (!name.matches(\'^[A-Za-z_][A-Za-z0-9_]*$\')) {\n        throw new IllegalArgumentException(\'Hive 目标表名不合法\')\n    }\n    var response = callHiveGateway({ action: \'tables\', contract: \'gateway\', database: scope })\n    var found = false\n    for (candidate in (response.tables == null ? [] : response.tables)) {\n        if (text(candidate).toLowerCase() == name.toLowerCase()) {\n            found = true\n            break\n        }\n    }\n    return { physicalExists: found, targetTableName: name, targetScope: scope, databaseType: \'hive\' }\n}\nvar hiveDrop = (config, requestedName) => {\n    var before = hivePreflight(config, requestedName)\n    if (!before.physicalExists) {\n        return { physicalExists: false, physicalDeleted: false, targetTableName: before.targetTableName,\n            targetScope: before.targetScope, databaseType: \'hive\' }\n    }\n    callHiveGateway({ action: \'dropTable\', contract: \'gateway\', database: before.targetScope,\n        table: before.targetTableName,\n        confirm: \'DROP_TABLE:\' + before.targetScope + \'.\' + before.targetTableName })\n    var after = hivePreflight(config, requestedName)\n    if (after.physicalExists) {\n        throw new IllegalStateException(\'华为 Hive 目标物理表删除后仍存在，已保留流程和元数据：\'\n            + before.targetScope + \'.\' + before.targetTableName)\n    }\n    return { physicalExists: true, physicalDeleted: true, targetTableName: before.targetTableName,\n        targetScope: before.targetScope, databaseType: \'hive\' }\n}\nvar dataSourceOf = (database) => {\n    var config = datasourceConnectionConfig(\'read\', first(database, [\'tid\']), null, false)\n    var dbTypeText = text(first(database, [\'dbType\', \'db_type\'])).trim().toLowerCase()\n    var jdbcUrl = text(first(config, [\'jdbcURL\', \'jdbcUrl\']) || first(database, [\'jdbcUrl\', \'jdbc_url\']))\n    var compatibleMode = text(first(config, [\'compatibleMode\', \'compatibilityMode\', \'mode\', \'databaseMode\', \'dbMode\'])\n        || first(database, [\'compatibleMode\', \'compatibilityMode\', \'mode\', \'databaseMode\', \'dbMode\'])).trim().toUpperCase()\n    var normalizedType = dbTypeText.replace(\'_\', \'\').replace(\'-\', \'\')\n    var type\n    if (normalizedType == \'oceanbase\') {\n        var lowerJdbcUrl = jdbcUrl.toLowerCase()\n        type = compatibleMode == \'ORACLE\'\n            || lowerJdbcUrl.startsWith(\'jdbc:oceanbase:oracle:\')\n            || lowerJdbcUrl.startsWith(\'jdbc:oceanbaseoracle:\')\n            || lowerJdbcUrl.startsWith(\'jdbc:oracle:\')\n            ? DatabaseType.OCEANBASE_ORACLE : DatabaseType.OCEANBASE_MYSQL\n    } else {\n        try { type = DatabaseType.fromCode(dbTypeText) }\n        catch (ignored) { exit 400, \'不支持的目标数据库类型，无法安全删除目标表：\' + dbTypeText }\n    }\n    var host = first(config, [\'host\', \'dbMetaIp\']) || first(database, [\'host\', \'db_ip\'])\n    var port = first(config, [\'port\', \'dbMetaPort\']) || first(database, [\'port\', \'db_port\'])\n    var databaseName = first(config, [\'database\', \'dbName\', \'dbMetaDbName\']) || first(database, [\'database\', \'db_name\'])\n    var username = first(config, [\'username\', \'dbMetaUser\']) || first(database, [\'username\', \'db_user\'])\n    var accessMode = text(first(config, [\'metadataAccessMode\', \'metadata_access_mode\'])).trim().toLowerCase()\n    var hiveMode = text(first(config, [\'hiveConnectionMode\', \'hive_connection_mode\'])).trim().toLowerCase()\n    var hiveProfile = text(first(config, [\'hiveProfile\', \'hive_profile\'])).trim()\n    var managedHive = type == DatabaseType.HIVE && accessMode != \'jdbc\' && hiveMode != \'open-source\'\n        && (accessMode == \'server-managed-mrs\' || hiveMode == \'huawei-mrs\' || !blank(hiveProfile))\n    if (blank(databaseName) || (!managedHive && (blank(host) || blank(username)))) {\n        exit 400, \'目标数据源连接信息不完整，无法删除目标物理表\'\n    }\n    var result = new DataSourceConfig()\n    result.setDatabaseType(type)\n    result.setHost(text(host))\n    result.setPort(blank(port) ? type.getDefaultPort() : port::int)\n    result.setDatabase(text(databaseName))\n    result.setUsername(text(username))\n    result.setPassword(text(first(config, [\'password\', \'dbMetaPassword\']) || first(database, [\'password\', \'db_password\'])))\n    result.setJdbcUrl(jdbcUrl)\n    if (managedHive) {\n        result.setConnectorProperties({\n            metadataAccessMode: \'server-managed-mrs\',\n            hiveConnectionMode: \'huawei-mrs\',\n            hiveProfile: blank(hiveProfile) ? \'default\' : hiveProfile\n        })\n    }\n    // 显式 Schema 优先；旧达梦登记的 database 保存业务 Schema。\n    // 与 AbstractMetadataExplorer.effectiveConfig / 建表链路使用相同回退，\n    // 不能让删除服务把管理账号 SYSDBA 误当成目标业务库。\n    var targetSchema = first(config, [\'schema\', \'defaultSchema\', \'currentSchema\', \'dbMetaSchema\', \'db_schema\'])\n        || first(database, [\'schema\', \'defaultSchema\', \'currentSchema\', \'dbMetaSchema\', \'db_schema\'])\n    if (blank(targetSchema) && type == DatabaseType.DAMENG) { targetSchema = databaseName }\n    result.setSchema(targetSchema)\n    return result\n}\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) { exit 401, \'登录状态已失效，请重新登录\' }\n\nvar sourceTableId = text(body?.sourceTableId || body?.tableId || body?.tid).trim()\nvar deleteTargetTable = body?.deleteTargetTable == true\nvar dryRun = body?.dryRun == true\nif (blank(sourceTableId)) { exit 400, \'sourceTableId不能为空\' }\n\nvar sourceTable = db.table(\'db_table_t\').where()\n    .eq(\'tid\', sourceTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\nif (sourceTable == null) { exit 404, \'来源表不存在\' }\n\nvar tasks = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'tenant_id\', tenantId).eq(\'source_table_id\', sourceTableId).eq(\'is_del\', 0).select()\nvar targetTable = null\nvar targetChosenByTask = false\nvar targetTableId = text(body?.targetTableId || body?.target_table_id).trim()\nvar targetDbId = text(body?.targetDbId || body?.targetDatasourceId || body?.target_db_id).trim()\nvar targetTableName = text(body?.targetTableName || body?.target_table_name).trim()\nvar targetSelectionMode = \'\'\nvar targetMetadataMissing = false\nvar sourceDatasourceId = text(first(sourceTable, [\'datasourceId\', \'datasource_id\']))\nvar sourceTableName = text(first(sourceTable, [\'tableName\', \'table_name\']))\nvar normalizeIdentifier = (value) => text(value).trim().toUpperCase()\nvar sameIdentifier = (left, right) => normalizeIdentifier(left) == normalizeIdentifier(right)\nvar taskForTargetId = (candidateId) => {\n    for (task in (tasks == null ? [] : tasks)) {\n        if (text(first(task, [\'targetTableId\', \'target_table_id\'])) == text(candidateId)) {\n            return task\n        }\n    }\n    return null\n}\n\nif (deleteTargetTable) {\n    if (blank(targetDbId) || blank(targetTableName) || !safeTableName(targetTableName)) {\n        exit 400, \'请提供合法的目标数据源 ID 和目标表名\'\n    }\n    if (targetDbId == sourceDatasourceId && sameIdentifier(targetTableName, sourceTableName)) {\n        exit 409, \'目标数据源和表名指向来源表本身，已拒绝删除\'\n    }\n    if (!blank(targetTableId) && targetTableId == sourceTableId) {\n        exit 409, \'目标表 ID 与来源表 ID 相同，已拒绝删除\'\n    }\n\n    if (!blank(targetTableId)) {\n        // An explicitly supplied metadata ID is authoritative, but it must\n        // match the exact target datasource/name and belong to this source.\n        targetSelectionMode = \'target_table_id\'\n        targetTable = db.table(\'db_table_t\').where()\n            .eq(\'tid\', targetTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n        if (targetTable == null) { exit 404, \'目标表 ID 不存在或不属于当前租户\' }\n        var resolvedTargetId = text(first(targetTable, [\'tid\']))\n        var resolvedTargetDbId = text(first(targetTable, [\'datasourceId\', \'datasource_id\']))\n        var resolvedTargetName = text(first(targetTable, [\'tableName\', \'table_name\']))\n        if (resolvedTargetId == sourceTableId) { exit 409, \'目标表 ID 指向来源表本身，已拒绝删除\' }\n        if (resolvedTargetDbId != targetDbId || !sameIdentifier(resolvedTargetName, targetTableName)) {\n            exit 409, \'目标表 ID 与指定的目标数据源或目标表名不匹配\'\n        }\n        var linkedTask = taskForTargetId(targetTableId)\n        targetChosenByTask = linkedTask != null\n        var targetSourceTableId = text(first(targetTable, [\'sourceTableId\', \'source_table_id\']))\n        if ((!blank(targetSourceTableId) && targetSourceTableId != sourceTableId)\n            || (blank(targetSourceTableId) && !targetChosenByTask)) {\n            exit 409, \'目标表元数据未关联到当前来源表，已拒绝删除\'\n        }\n        var taskTargetDbId = text(first(linkedTask, [\'targetDbId\', \'target_db_id\']))\n        if (!blank(taskTargetDbId) && taskTargetDbId != targetDbId) {\n            exit 409, \'接入任务的目标数据源与目标表元数据不一致\'\n        }\n    } else {\n        // Without an ID, only the exact datasource + exact table name may\n        // resolve metadata. Never fall back to source_table_id alone: source\n        // rows can carry that value too.\n        targetSelectionMode = \'datasource_and_table_name\'\n        var exactTargetRows = db.table(\'db_table_t\').where()\n            .eq(\'tenant_id\', tenantId).eq(\'datasource_id\', targetDbId)\n            .eq(\'table_name\', targetTableName).eq(\'is_del\', 0).select()\n        var exactTargetCandidates = []\n        for (candidate in (exactTargetRows == null ? [] : exactTargetRows)) {\n            var candidateId = text(first(candidate, [\'tid\']))\n            var candidateDbId = text(first(candidate, [\'datasourceId\', \'datasource_id\']))\n            var candidateName = text(first(candidate, [\'tableName\', \'table_name\']))\n            if (blank(candidateId) || candidateId == sourceTableId) { continue }\n            if (candidateDbId == targetDbId && sameIdentifier(candidateName, targetTableName)) {\n                exactTargetCandidates.add(candidate)\n            }\n        }\n        if (exactTargetCandidates.size() > 1) {\n            exit 409, \'目标数据源和表名匹配到多条元数据，请传入目标表 ID\'\n        }\n        if (exactTargetCandidates.size() == 1) {\n            targetTable = exactTargetCandidates[0]\n            var matchedTargetId = text(first(targetTable, [\'tid\']))\n            var matchedTargetSourceId = text(first(targetTable, [\'sourceTableId\', \'source_table_id\']))\n            var matchedTask = taskForTargetId(matchedTargetId)\n            targetChosenByTask = matchedTask != null\n            if ((!blank(matchedTargetSourceId) && matchedTargetSourceId != sourceTableId)\n                || (blank(matchedTargetSourceId) && !targetChosenByTask)) {\n                exit 409, \'匹配到的目标表元数据未关联到当前来源表，已拒绝删除\'\n            }\n            var matchedTaskDbId = text(first(matchedTask, [\'targetDbId\', \'target_db_id\']))\n            if (!blank(matchedTaskDbId) && matchedTaskDbId != targetDbId) {\n                exit 409, \'接入任务的目标数据源与目标表元数据不一致\'\n            }\n            targetTableId = matchedTargetId\n        } else {\n            targetMetadataMissing = true\n            if (body?.confirmUnmanagedTarget != true) {\n                exit 409, \'目标表未登记，请确认要按指定目标数据源和表名预检未登记表\'\n            }\n        }\n    }\n} else {\n    // Cancelling a task never requires resolving or deleting a target asset.\n    // Retain a target ID for response compatibility only when it is not the\n    // source row itself and belongs to the active tenant.\n    if (!blank(targetTableId) && targetTableId != sourceTableId) {\n        targetTable = db.table(\'db_table_t\').where()\n            .eq(\'tid\', targetTableId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    }\n    if (targetTable == null) {\n        for (task in (tasks == null ? [] : tasks)) {\n            var candidateId = text(first(task, [\'targetTableId\', \'target_table_id\']))\n            if (!blank(candidateId) && candidateId != sourceTableId) {\n                targetTable = db.table(\'db_table_t\').where()\n                    .eq(\'tid\', candidateId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n                if (targetTable != null) { targetTableId = candidateId; break }\n            }\n        }\n    }\n    if (targetTable != null) {\n        targetDbId = text(first(targetTable, [\'datasourceId\', \'datasource_id\']))\n        targetTableName = text(first(targetTable, [\'tableName\', \'table_name\']))\n    }\n}\n\n// Preflight before task cleanup: a target connection failure must not leave a\n// half-cancelled task that cannot be rebuilt from the page.\nvar preflightConfig = null\nvar preflightPhysicalExists = false\nvar preflightScope = \'\'\nvar preflightDatabaseType = \'\'\nvar physicalTargetTableName = targetTableName\nvar historicalScopeNormalized = false\nvar targetDatasourceMissing = false\nvar targetPhysicalDatasourceMissing = false\nvar targetPhysicalCleanupSkipped = false\nvar targetCleanupSkipReason = \'\'\nvar missingObjectMessage = (value) => {\n    var message = text(value).toLowerCase()\n    return message.indexOf(\'表不存在\') >= 0 || message.indexOf(\'对象不存在\') >= 0\n        || message.indexOf(\'无效的表或视图名\') >= 0 || message.indexOf(\'ora-00942\') >= 0\n        || message.indexOf(\'table or view does not exist\') >= 0\n        || message.indexOf(\'object does not exist\') >= 0\n}\nvar missingDatasourceMessage = (value) => {\n    var message = text(value).toLowerCase()\n    return message.indexOf(\'unknown database\') >= 0 || message.indexOf(\'database does not exist\') >= 0\n        || message.indexOf(\'数据库不存在\') >= 0 || message.indexOf(\'ora-12514\') >= 0\n        || message.indexOf(\'ora-12505\') >= 0 || message.indexOf(\'服务名不存在\') >= 0\n        || message.indexOf(\'服务名无效\') >= 0\n}\nif (deleteTargetTable) {\n    // A missing table-asset row is not permission to guess from source_table_id.\n    // In that case the explicit datasource/name pair is still preflighted, but\n    // no table metadata row can be soft-deleted.\n    var preflightDatasource = db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', targetDbId).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).selectOne()\n    if (preflightDatasource == null) {\n        exit 404, \'目标数据源不存在或不属于当前租户，已保留流程和元数据\'\n    } else {\n        preflightConfig = dataSourceOf(preflightDatasource)\n        try {\n        // Resolve against the entire selected datasource scope, not a 200-row\n        // page.  The Java service also locks Oracle/OceanBase Oracle to its\n        // configured schema and rejects a qualified name from another schema.\n        var preflight = managedHiveOf(preflightConfig)\n            ? hivePreflight(preflightConfig, physicalTargetTableName)\n            : targetTableDeletionService.preflight(preflightConfig, physicalTargetTableName)\n        preflightPhysicalExists = preflight.physicalExists == true\n        preflightScope = text(preflight.targetScope)\n        preflightDatabaseType = text(preflight.databaseType)\n        } catch (error) {\n        // Historical materialization rows can retain a qualified source-table\n        // name after the target datasource has been reconfigured to another\n        // schema.  Do not let that stale qualifier prevent cleanup forever.\n        // Probe the unqualified name only inside the datasource\'s configured\n        // scope; this never broadens the destructive operation to the old\n        // schema.  A missing table is then the normal idempotent cleanup case.\n        var preflightMessage = text(error.message || error)\n        var separator = targetTableName.lastIndexOf(\'.\')\n        if (managedHiveOf(preflightConfig) && missingDatasourceMessage(preflightMessage)) {\n            exit 400, \'华为 Hive 目标数据库无法确认，已保留流程和元数据：\' + preflightMessage\n        } else if (missingDatasourceMessage(preflightMessage)) {\n            targetPhysicalDatasourceMissing = true\n            targetPhysicalCleanupSkipped = true\n            targetCleanupSkipReason = \'target_physical_datasource_missing\'\n        } else if (preflightMessage.indexOf(\'不一致\') < 0 || separator < 1) {\n            exit 400, \'无法校验目标物理表，已保留流程和元数据：\' + preflightMessage\n        } else {\n            physicalTargetTableName = targetTableName.substring(separator + 1)\n            if (!safeTableName(physicalTargetTableName)) {\n                exit 400, \'目标表名不合法，已保留流程和元数据：\' + targetTableName\n            }\n            try {\n                var normalizedPreflight = managedHiveOf(preflightConfig)\n                    ? hivePreflight(preflightConfig, physicalTargetTableName)\n                    : targetTableDeletionService.preflight(preflightConfig, physicalTargetTableName)\n                preflightPhysicalExists = normalizedPreflight.physicalExists == true\n                preflightScope = text(normalizedPreflight.targetScope)\n                preflightDatabaseType = text(normalizedPreflight.databaseType)\n                historicalScopeNormalized = true\n            } catch (normalizedError) {\n                var normalizedMessage = text(normalizedError.message || normalizedError)\n                if (managedHiveOf(preflightConfig) && missingDatasourceMessage(normalizedMessage)) {\n                    exit 400, \'华为 Hive 目标数据库无法确认，已保留流程和元数据：\' + normalizedMessage\n                } else if (missingDatasourceMessage(normalizedMessage)) {\n                    targetPhysicalDatasourceMissing = true\n                    targetPhysicalCleanupSkipped = true\n                    targetCleanupSkipReason = \'target_physical_datasource_missing\'\n                } else {\n                    exit 400, \'无法校验目标物理表，已保留流程和元数据：\' + normalizedMessage\n                }\n            }\n        }\n    }\n}\n}\nif (dryRun) {\n    return {\n        dryRun: true,\n        sourceTableId: sourceTableId,\n        sourceDatasourceId: sourceDatasourceId,\n        sourceTableName: sourceTableName,\n        sourceTableExcluded: true,\n        sourceTableSoftDeletePlanned: false,\n        taskCount: tasks == null ? 0 : tasks.size(),\n        targetTableId: targetTable == null ? \'\' : text(first(targetTable, [\'tid\'])),\n        resolvedTargetTableId: targetTable == null ? \'\' : text(first(targetTable, [\'tid\'])),\n        targetDbId: targetDbId,\n        resolvedTargetDatabaseId: targetDbId,\n        targetTableName: targetTableName,\n        resolvedTargetTableName: targetTableName,\n        targetSelectionMode: targetSelectionMode,\n        targetPhysicalExists: preflightPhysicalExists,\n        targetScope: preflightScope,\n        targetDatabaseType: preflightDatabaseType,\n        resolvedTargetDatabaseType: preflightDatabaseType,\n        physicalTargetTableName: physicalTargetTableName,\n        historicalScopeNormalized: historicalScopeNormalized,\n        targetMetadataMissing: targetMetadataMissing,\n        targetDatasourceMissing: targetDatasourceMissing,\n        targetPhysicalDatasourceMissing: targetPhysicalDatasourceMissing,\n        targetPhysicalCleanupSkipped: targetPhysicalCleanupSkipped,\n        targetCleanupSkipReason: targetCleanupSkipReason,\n        deleteTargetTableRequested: deleteTargetTable,\n        targetTableDeleted: false,\n        sideEffectsApplied: false\n    }\n}\n\n// The physical-table action is deliberately first.  A driver, permission or\n// dialect failure (notably OceanBase Oracle) must leave the task, pipeline and\n// catalog rows available for recovery instead of creating a half-deleted flow.\nvar physicalDeleteResult = null\nif (deleteTargetTable && !targetPhysicalCleanupSkipped) {\n    try {\n        physicalDeleteResult = managedHiveOf(preflightConfig)\n            ? hiveDrop(preflightConfig, physicalTargetTableName)\n            : targetTableDeletionService.drop(preflightConfig, physicalTargetTableName)\n    } catch (error) {\n        var deleteMessage = text(error.message || error)\n        if (missingObjectMessage(deleteMessage)) {\n            targetPhysicalCleanupSkipped = true\n            targetCleanupSkipReason = \'target_physical_missing\'\n        } else {\n            exit 400, \'删除目标物理表失败，已保留流程和元数据：\' + deleteMessage\n        }\n    }\n}\n\nvar now = new Date()\nvar pipelineCount = 0\nfor (task in (tasks == null ? [] : tasks)) {\n    var taskId = text(first(task, [\'tid\']))\n    var pipelineId = text(first(task, [\'pipelineId\', \'pipeline_id\']))\n    db.table(\'data_access_field_mapping\').where().eq(\'task_id\', taskId).eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: now })\n    db.table(\'data_access_task_monitor_snap_t\').where().eq(\'task_id\', taskId).eq(\'is_del\', 0)\n        .update({ is_del: 1 })\n    db.table(\'data_access_agg_task_t\').where().eq(\'tid\', taskId).eq(\'is_del\', 0)\n        .update({ is_del: 1, task_status: 0, updated_time: now })\n    if (!blank(pipelineId)) {\n        db.table(\'nifi_pipeline_t\').where().eq(\'id\', pipelineId).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_at: now.getTime() })\n        pipelineCount = pipelineCount + 1\n    }\n    var processGroupId = text(first(task, [\'processGroupId\', \'process_group_id\']))\n    if (!blank(processGroupId)) {\n        try { nifiClient.cleanupProcessGroup(processGroupId) } catch (error) {\n            log.warn(\'Unable to clean NiFi process group {}, reason={}\', processGroupId, error.message)\n        }\n    }\n}\n\nif (deleteTargetTable) {\n    if (targetTable != null) {\n        var targetId = text(first(targetTable, [\'tid\']))\n        if (blank(targetId) || targetId == sourceTableId) {\n            exit 409, \'目标表元数据指向来源表本身，已拒绝软删除\'\n        }\n        db.table(\'db_table_column_t\').where().eq(\'table_id\', targetId).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: now })\n        db.table(\'db_table_t\').where().eq(\'tid\', targetId).ne(\'tid\', sourceTableId)\n            .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n            .update({ is_del: 1, updated_time: now })\n        try { esCommonService.deleteById(\'dataassets\', targetId) } catch (ignored) {}\n    }\n    var remainingTargets = db.table(\'db_table_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'source_table_id\', sourceTableId)\n        .ne(\'tid\', sourceTableId).eq(\'is_del\', 0).select()\n    var catalogs = db.table(\'da_prop_t\').where().eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', sourceTableId).eq(\'is_del\', 0).select()\n    if (remainingTargets == null || remainingTargets.size() == 0) {\n        for (catalogProp in (catalogs == null ? [] : catalogs)) {\n            var catalogId = text(first(catalogProp, [\'parentId\', \'parent_id\']))\n            db.table(\'da_prop_t\').where().eq(\'parent_id\', catalogId).eq(\'is_del\', 0)\n                .update({ is_del: 1, updated_time: now })\n            db.table(\'da_catalog_t\').where().eq(\'tid\', catalogId).eq(\'is_del\', 0)\n                .update({ is_del: 1, updated_time: now })\n            try { esCommonService.deleteById(\'dataassets\', catalogId) } catch (ignored) {}\n        }\n        db.table(\'db_table_t\').where().eq(\'tid\', sourceTableId).eq(\'is_del\', 0)\n            .update({ source_catalog_id: null, catalog_name: null, updated_time: now })\n    } else {\n        // 多目标场景删除其中一个目标后，其余目标仍然有效。目录保留并把兼容的\n        // 单目标属性指向首个剩余目标，避免后续重新创建任务时误判为无目标表。\n        var remainingTarget = remainingTargets[0]\n        var remainingTargetId = text(first(remainingTarget, [\'tid\']))\n        var remainingTargetDbId = text(first(remainingTarget, [\'datasourceId\', \'datasource_id\']))\n        var remainingTargetName = text(first(remainingTarget, [\'tableName\', \'table_name\']))\n        for (catalogProp in (catalogs == null ? [] : catalogs)) {\n            var remainingCatalogId = text(first(catalogProp, [\'parentId\', \'parent_id\']))\n            db.table(\'da_prop_t\').where().eq(\'parent_id\', remainingCatalogId)\n                .eq(\'prop_name\', \'targetTableId\').eq(\'is_del\', 0)\n                .update({ prop_value: remainingTargetId, updated_time: now })\n            db.table(\'da_prop_t\').where().eq(\'parent_id\', remainingCatalogId)\n                .eq(\'prop_name\', \'targetDbId\').eq(\'is_del\', 0)\n                .update({ prop_value: remainingTargetDbId, updated_time: now })\n            db.table(\'da_prop_t\').where().eq(\'parent_id\', remainingCatalogId)\n                .eq(\'prop_name\', \'targetTableName\').eq(\'is_del\', 0)\n                .update({ prop_value: remainingTargetName, updated_time: now })\n        }\n    }\n}\n\nreturn {\n    sourceTableId: sourceTableId,\n    sourceDatasourceId: sourceDatasourceId,\n    sourceTableName: sourceTableName,\n    sourceTableSoftDeleted: false,\n    taskCount: tasks == null ? 0 : tasks.size(),\n    pipelineCount: pipelineCount,\n    targetTableId: targetTable == null ? \'\' : text(first(targetTable, [\'tid\'])),\n    resolvedTargetTableId: targetTable == null ? \'\' : text(first(targetTable, [\'tid\'])),\n    targetDbId: targetDbId,\n    resolvedTargetDatabaseId: targetDbId,\n    targetTableDeleted: deleteTargetTable,\n    targetTableName: targetTableName,\n    resolvedTargetTableName: targetTableName,\n    targetSelectionMode: targetSelectionMode,\n    targetMetadataMissing: targetMetadataMissing,\n    physicalTargetTableName: physicalTargetTableName,\n    historicalScopeNormalized: historicalScopeNormalized,\n    targetMetadataMissing: targetMetadataMissing,\n    targetDatasourceMissing: targetDatasourceMissing,\n    targetPhysicalDatasourceMissing: targetPhysicalDatasourceMissing,\n    targetPhysicalCleanupSkipped: targetPhysicalCleanupSkipped,\n    targetCleanupSkipReason: targetCleanupSkipReason,\n    targetPhysicalExists: physicalDeleteResult == null ? false : physicalDeleteResult.physicalExists == true,\n    targetPhysicalDeleted: physicalDeleteResult == null ? false : physicalDeleteResult.physicalDeleted == true\n}\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/15.取消接入流程与删除目标表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "ods_data_agg_reject_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "16.接入审查驳回修改",\n  "createTime": 1785063600000,\n  "updateTime": 1790392921740,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dataAggReject",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tableId\\":\\"来源表ID\\",\\"datasourceId\\":\\"数据源ID\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"tableId\\":\\"来源表ID\\",\\"assetStatus\\":0}",\n  "description": "接入发现登记信息有误时驳回修改。仅无接入任务的数据表允许驳回；只重置来源表的标注与登记状态，数据源保持已注册，并刷新资产索引；使用请求参数 tableId、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：16.接入审查驳回修改\n// 路由：POST /ods/dataAggReject\n// 业务说明：接入发现登记信息有误时驳回修改。仅无接入任务的数据表允许驳回；只重置来源表的标注与登记状态，数据源保持已注册，并刷新资产索引；使用请求参数 tableId、datasourceId；涉及 db_table_t、db_datasource_t、data_access_agg_task_t 等业务表；执行数据库写入并返回处理结果。\nimport \'@post:/dst/maintenance/refresh\' as refreshAssetIndex\nimport tenantRuntime\n\nvar text = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || text(value).trim() == \'\'\nvar tenantId = tenantRuntime.id()\nvar nowTime = new Date()\nvar tableId = body == null ? null : body.tableId\nvar requestedDatasourceId = body == null ? null : body.datasourceId\nif (blank(tableId)) {\n    exit 400, \'来源表不能为空\'\n}\n// db.table 使用后端命名表租户拦截器，查询与更新天然限定在当前登录租户；\n// 请求中不接受 tenantId，避免由前端决定租户范围。\nvar sourceTable = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\nif (sourceTable == null) {\n    exit 404, \'来源表不存在或无访问权限\'\n}\nvar datasourceId = sourceTable.datasourceId == null ? sourceTable.datasource_id : sourceTable.datasourceId\nif (!blank(requestedDatasourceId) && text(requestedDatasourceId) != text(datasourceId)) {\n    exit 400, \'来源表与数据源不匹配\'\n}\nvar datasource = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\nif (datasource == null) {\n    exit 404, \'数据源不存在或无访问权限\'\n}\nvar taskCount = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'source_table_id\', tableId).eq(\'is_del\', 0).count()\nif (taskCount > 0) {\n    exit 409, \'该表已创建接入任务，不能驳回修改\'\n}\ndb.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).update({\n    asset_status: 0,\n    flow_status: 0,\n    updated_time: nowTime\n})\nbody = { tid: tableId }\nrefreshAssetIndex()\nreturn { tableId: tableId, datasourceId: datasourceId, assetStatus: 0 }\n',NULL,NULL,0,NULL,'/magic-api/api/03.数据接入/16.接入审查驳回修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('93adfae2a5074269981dc2a45d7358d5',NULL,NULL,'{\n  "properties": {},\n  "id": "93adfae2a5074269981dc2a45d7358d5",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "17.清理重建接入数据",\n  "createTime": 1784437770674,\n  "updateTime": 1787156377586,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/cleanup-rebuild",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dryRun\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "Magic 负责定位并逻辑删除接入任务、字段映射、监控快照、流水线、目标表；使用请求参数 dryRun、tid；涉及 db_datasource_t、db_table_t、data_access_agg_task_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：17.清理重建接入数据\n// 路由：POST /ods/cleanup-rebuild\n// 业务说明：Magic 负责定位并逻辑删除接入任务、字段映射、监控快照、流水线、目标表；使用请求参数 dryRun、tid；涉及 db_datasource_t、db_table_t、data_access_agg_task_t、data_access_field_mapping、data_access_task_monitor_snap_t、nifi_pipeline_t 等业务表。\nimport \'@/common/datasourceConnectionConfig\' as datasourceConnectionConfig\n/*\n * 清理并重建数据接入目标\n *\n * Magic 负责定位并逻辑删除接入任务、字段映射、监控快照、流水线、目标表\n * 及字段，并清空目录目标关系。NiFiClient 和 MetadataExplorerService 仅负责\n * 运行时进程组清理与远端物理删表。body.dryRun=true 时只返回影响范围。\n */\nimport cn.hutool.json.JSONUtil as jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.integration.nifi.canvas.nifi.NifiClient as nifiClient\nimport com.linewell.dataelement.metautil.model.dto.DataSourceConfig\nimport com.linewell.dataelement.metautil.model.enums.DatabaseType\nimport com.linewell.dataelement.metautil.service.MetadataExplorerService as metadataExplorerService\nimport java.util.Map\nimport log\n\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar valueOf = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (!blank(value)) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar loadDatabase = dbId => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var main = db.table(\'db_datasource_t\').where().eq(\'tid\', dbId).eq(\'is_del\', 0).selectOne()\n    if (main == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    var result = {\n        tid: main.tid,\n        dbType: main.dbType,\n        dbName: main.dbName,\n        jdbcURL: main.jdbcUrl,\n        username: main.username,\n        password: main.password\n    }\n    result.putAll(datasourceConnectionConfig(\'read\', main.tid, null, false))\n    // 返回当前业务分支的标准结果。\n    return result\n}\nvar dataSourceOf = asset => {\n    var host = valueOf(asset, [\'host\', \'dbIp\'])\n    var port = valueOf(asset, [\'port\', \'dbPort\'])\n    var databaseName = valueOf(asset, [\'database\', \'dbName\', \'dbMetaDbName\'])\n    var username = valueOf(asset, [\'username\', \'dbUser\', \'dbMetaUser\', \'user\'])\n    if (blank(host) || blank(databaseName) || blank(username)) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'旧目标数据库连接参数不完整\'\n    }\n    var type\n    try {\n        type = DatabaseType.fromCode(((valueOf(asset, [\'dbType\', \'databaseType\']) || \'mysql\') + \'\').toLowerCase())\n    } catch (e) {\n        type = DatabaseType.MYSQL\n    }\n    var config = new DataSourceConfig()\n    config.setDatabaseType(type)\n    config.setHost(host + \'\')\n    config.setPort(blank(port) ? type.getDefaultPort() : port::int)\n    config.setDatabase(databaseName + \'\')\n    config.setUsername(username + \'\')\n    config.setPassword((valueOf(asset, [\'password\', \'dbPassword\', \'dbMetaPassword\']) || \'\') + \'\')\n    config.setSchema(valueOf(asset, [\'schema\', \'defaultSchema\']))\n    // 返回当前业务分支的标准结果。\n    return config\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar catalogId = body?.tid\nif (blank(catalogId)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'tid参数不正确\'\n}\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar catalog = esCommonService.getDocument(\'dataassets\', catalogId + \'\')\nif (catalog == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'资源目录不存在\'\n}\n\nvar oldTableId = catalog.targetTableId\n// 从 MySQL 业务表读取当前有效数据。\nvar oldTable = blank(oldTableId) ? null : db.table(\'db_table_t\').where()\n    .eq(\'tid\', oldTableId).eq(\'is_del\', 0).selectOne()\nvar oldDbId = oldTable == null ? catalog.targetDbId : oldTable.datasourceId\nvar oldTableName = oldTable == null ? catalog.targetTableName : oldTable.tableName\n// 从 MySQL 业务表读取当前有效数据。\nvar tasks = db.table(\'data_access_agg_task_t\').where()\n    .eq(\'data_catalog_id\', catalogId).eq(\'is_del\', 0).select()\nvar taskIds = []\nfor (task in tasks) {\n    taskIds.add(task.tid)\n}\nvar result = {\n    catalogId: catalogId,\n    oldTableId: oldTableId,\n    oldDbId: oldDbId,\n    oldTableName: oldTableName,\n    taskIds: taskIds,\n    dryRun: body?.dryRun == true\n}\nif (body?.dryRun == true) {\n    // 返回当前业务分支的标准结果。\n    return result\n}\n\nvar now = new Date()\nfor (task in tasks) {\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_access_agg_task_t\').where().eq(\'tid\', task.tid).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_time: now})\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_access_field_mapping\').where().eq(\'task_id\', task.tid).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_time: now})\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_access_task_monitor_snap_t\').where().eq(\'task_id\', task.tid).eq(\'is_del\', 0)\n        .update({is_del: 1})\n    if (!blank(task.pipelineId)) {\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table(\'nifi_pipeline_t\').where().eq(\'id\', task.pipelineId).eq(\'is_del\', 0)\n            .update({is_del: 1, updated_at: System.currentTimeMillis()})\n    }\n    if (!blank(task.processGroupId)) {\n        try {\n            nifiClient.cleanupProcessGroup(task.processGroupId + \'\')\n        } catch (e) {\n            log.warn(\'NiFi进程组清理失败, processGroupId={}, message={}\', task.processGroupId, e.message)\n        }\n    }\n}\n\nif (!blank(oldTableId)) {\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'db_table_column_t\').where().eq(\'table_id\', oldTableId).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_time: now})\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'db_table_t\').where().eq(\'tid\', oldTableId).eq(\'is_del\', 0)\n        .update({is_del: 1, updated_time: now})\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.deleteById(\'dataassets\', oldTableId + \'\')\n}\n\nvar catalogPropsToClear = [\'targetTableId\', \'targetTableName\', \'targetDbType\', \'targetDbId\', \'accessTaskId\']\nfor (propName in catalogPropsToClear) {\n    var prop = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', catalogId)\n        .eq(\'prop_name\', propName)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (prop != null) {\n        db.table(\'da_prop_t\').primary(\'tid\').update({\n            tid: prop.tid,\n            prop_value: null,\n            updated_time: now\n        }, true)\n    }\n}\n\nif (!blank(oldDbId) && !blank(oldTableName)) {\n    if (!(oldTableName + \'\').matches(\'^[A-Za-z_][A-Za-z0-9_]*(\\\\.[A-Za-z_][A-Za-z0-9_]*)?$\')) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'旧目标表名称不合法，无法执行物理删表\'\n    }\n    var database = loadDatabase(oldDbId + \'\')\n    if (database == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'旧目标数据库不存在\'\n    }\n    metadataExplorerService.createTable(dataSourceOf(database), \'DROP TABLE IF EXISTS \' + oldTableName)\n}\n\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/17.清理重建接入数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_target_datasource_options_01',NULL,'api','{\n  "properties": {},\n  "id": "ods_target_datasource_options_01",\n  "script": null,\n  "groupId": "1f4028f20aaa4f379b5e37a343b99fa9",\n  "name": "18.目标数据源选项",\n  "createTime": 1785067200000,\n  "updateTime": 1787156377696,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/targetDatasource/options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"options\\": [\\n    {\\n      \\"label\\": \\"贴源层 ODS\\",\\n      \\"value\\": \\"ODS\\",\\n      \\"children\\": [\\n        {\\n          \\"label\\": \\"原始库 / 示例数据源\\",\\n          \\"value\\": \\"datasource-id\\",\\n          \\"layerCode\\": \\"ODS\\"\\n        }\\n      ]\\n    }\\n  ],\\n  \\"list\\": []\\n}",\n  "description": "目标数据源选项（POST /ods/targetDatasource/options）。只读接口；按当前租户的数据组织 dataSourceType 字典读取贴源层 ODS 及其分域，并通过分层分域配置的关联表返回每个分域已配置的目标数据源。用于数据接入物化建表弹框，不依赖 ES；涉及 sym_dict_t、dwm_center_layer_source_t、db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：18.目标数据源选项\n// 路由：POST /ods/targetDatasource/options\n// 业务说明：目标数据源选项（POST /ods/targetDatasource/options）。只读接口；按当前租户的数据组织 dataSourceType 字典读取贴源层 ODS 及其分域，并通过分层分域配置的关联表返回每个分域已配置的目标数据源。用于数据接入物化建表弹框，不依赖 ES；涉及 sym_dict_t、dwm_center_layer_source_t、db_datasource_t 等业务表。\n/*\n * 物化建表目标数据源选项。\n * 只读取当前租户 dataSourceType -> ODS 下的分域，并取每个分域在\n * dwm_center_layer_source_t 中关联的目标数据源；不会混入普通数据源登记列表。\n */\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => text(value).trim() == \'\'\nvar tenantId = text(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'当前登录上下文无效，请重新登录\'\n}\n\nvar root = db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'dict_code\', \'dataSourceType\')\n    .eq(\'parent_id\', \'0\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (root == null) {\n    return { options: [], list: [], total: 0 }\n}\n\nvar ods = db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'parent_id\', root.tid)\n    .eq(\'dict_code\', \'ods\')\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (ods == null) {\n    return { options: [], list: [], total: 0 }\n}\n\nvar domains = db.table(\'sym_dict_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'parent_id\', ods.tid)\n    .eq(\'is_del\', 0)\n    .orderBy(\'sort_no\', \'asc\')\n    .select()\nvar domainMap = {}\nvar domainIds = []\nfor (domain in (domains == null ? [] : domains)) {\n    var domainId = text(domain.tid)\n    domainMap[domainId] = domain\n    domainIds.add(domainId)\n}\nif (domainIds.size() == 0) {\n    return { options: [], list: [], total: 0 }\n}\n\nvar relations = db.table(\'dwm_center_layer_source_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'target_type\', \'domain\')\n    .in(\'target_id\', domainIds)\n    .eq(\'is_del\', 0)\n    .orderBy(\'updated_time\', \'desc\')\n    .select()\nvar relationByDomain = {}\nfor (relation in (relations == null ? [] : relations)) {\n    var relationDomainId = text(relation.targetId)\n    if (relationByDomain[relationDomainId] == null && !blank(relation.datasourceId)) {\n        relationByDomain[relationDomainId] = relation\n    }\n}\n\nvar datasourceIds = []\nfor (domainId in domainIds) {\n    var relation = relationByDomain[domainId]\n    if (relation != null) {\n        datasourceIds.add(text(relation.datasourceId))\n    }\n}\nif (datasourceIds.size() == 0) {\n    return { options: [], list: [], total: 0 }\n}\n\nvar datasourceRows = db.table(\'db_datasource_t\').where()\n    .eq(\'tenant_id\', tenantId)\n    .in(\'tid\', datasourceIds)\n    .eq(\'is_del\', 0)\n    .eq(\'show_connect\', 1)\n    .select()\nvar datasourceMap = {}\nfor (datasource in (datasourceRows == null ? [] : datasourceRows)) {\n    datasourceMap[text(datasource.tid)] = datasource\n}\n\nvar children = []\nvar list = []\nfor (domain in (domains == null ? [] : domains)) {\n    var domainId = text(domain.tid)\n    var relation = relationByDomain[domainId]\n    var datasource = relation == null ? null : datasourceMap[text(relation.datasourceId)]\n    if (datasource == null) {\n        continue\n    }\n    var datasourceId = text(datasource.tid)\n    var datasourceName = text(datasource.dbName).trim()\n    if (blank(datasourceName)) {\n        datasourceName = text(datasource.database).trim()\n    }\n    var option = {\n        label: text(domain.dictName) + \' / \' + datasourceName,\n        value: datasourceId,\n        tid: datasourceId,\n        datasourceId: datasourceId,\n        datasourceName: datasourceName,\n        dbType: datasource.dbType,\n        domainId: domainId,\n        domainName: domain.dictName,\n        domainCode: domain.dictCode,\n        layerCode: \'ODS\',\n        tablePrefix: \'ODS\',\n        parentValue: \'ODS\',\n        showConnect: datasource.showConnect,\n        assetStatus: datasource.assetStatus\n    }\n    children.add(option)\n    list.add(option)\n}\n\nvar options = children.size() == 0 ? [] : [{\n    label: ods.dictName,\n    value: \'ODS\',\n    layerCode: \'ODS\',\n    children: children\n}]\nreturn { options: options, list: list, total: list.size() }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/18.目标数据源选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ods_batch_create_job_01',NULL,'api','{\r\n  "properties" : { },\r\n  "id" : "ods_batch_create_job_01",\r\n  "script" : null,\r\n  "groupId" : "1f4028f20aaa4f379b5e37a343b99fa9",\r\n  "name" : "19.批量创建任务作业",\r\n  "createTime" : 1791112318054,\r\n  "updateTime" : 1791117206123,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/batchCreateJob",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"action\\":\\"list\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\"jobs\\":[]}",\r\n  "description" : "当前租户批量创建接入任务的持久作业。创建时核验来源库、唯一物化目标表及租户；可列出、查看、领取、回报、停止与重试。领取后调用已有 /ods/dataAggTaskEnsure，页面关闭后暂停，重新打开可续跑。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：19.批量创建任务作业\n// 路由：POST /ods/batchCreateJob\n// 业务说明：按当前租户保存批量作业及逐项结果；领取一项后由调用方执行既有\n// /ods/dataAggTaskEnsure，再携租约回报结果。页面离开时不在后台继续执行。\nimport tenantRuntime\nimport dataScope\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.json.JSONUtil\n\nvar text = value => value == null ? \'\' : value + \'\'\nvar blank = value => text(value).trim() == \'\'\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) { exit 401, \'当前登录租户无效，请重新登录\' }\nvar action = text(body?.action).trim()\nvar jobId = text(body?.jobId).trim()\nvar now = new Date()\nvar leaseCutoff = new Date(now.getTime() - 10 * 60 * 1000)\n\nvar visibleDbIdsFor = ids => {\n    if (ids.size() == 0) { return [] }\n    var rows = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0).in(\'tid\', ids).select()\n    var visible = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', rows)\n    var result = []\n    for (row in visible) { result.add(text(row.tid)) }\n    return result\n}\nvar assertJobVisible = job => {\n    if (job == null) { exit 404, \'批量作业不存在或不属于当前租户\' }\n    var visibleIds = visibleDbIdsFor([text(job.sourceDbId), text(job.targetDbId)])\n    if (!visibleIds.contains(text(job.sourceDbId)) || !visibleIds.contains(text(job.targetDbId))) {\n        exit 403, \'批量作业的来源库或目标库不在当前角色的数据范围内\'\n    }\n    return job\n}\nvar ownedJob = id => {\n    var job = db.table(\'ods_batch_create_job_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'job_id\', id).selectOne()\n    return assertJobVisible(job)\n}\nvar publicItem = row => ({\n    itemId: row.itemId, jobId: row.jobId, itemIndex: row.itemIndex,\n    sourceTableId: row.sourceTableId, sourceTableName: row.sourceTableName,\n    sourceCatalogId: row.sourceCatalogId, targetTableId: row.targetTableId,\n    targetTableName: row.targetTableName, status: row.status,\n    attemptCount: row.attemptCount, taskId: row.taskId,\n    wasExisting: row.wasExisting, errorMessage: row.errorMessage,\n    claimedTime: row.claimedTime, completedTime: row.completedTime\n})\nvar itemsOf = id => {\n    var rows = db.table(\'ods_batch_create_item_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'job_id\', id)\n        .orderBy(\'item_index\', \'asc\').select()\n    var result = []\n    for (row in rows) { result.add(publicItem(row)) }\n    return result\n}\nvar detail = id => {\n    var job = ownedJob(id)\n    if (job == null) { exit 404, \'批量作业不存在或不属于当前租户\' }\n    return {job: job, items: itemsOf(id)}\n}\nvar countsOf = id => {\n    return {\n        pending: db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', id).eq(\'status\', \'PENDING\').count(),\n        running: db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', id).eq(\'status\', \'RUNNING\').count(),\n        succeeded: db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', id).eq(\'status\', \'SUCCEEDED\').count(),\n        failed: db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', id).eq(\'status\', \'FAILED\').count()\n    }\n}\nvar refreshStatus = id => {\n    var job = ownedJob(id)\n    var counts = countsOf(id)\n    var status = \'RUNNING\'\n    var finished = null\n    if (job.stopRequested == true || text(job.stopRequested) == \'1\') {\n        status = \'STOPPED\'\n        finished = new Date()\n    } else if (counts.pending == 0 && counts.running == 0) {\n        status = counts.failed == 0 ? \'SUCCEEDED\' : (counts.succeeded > 0 ? \'PARTIAL\' : \'FAILED\')\n        finished = new Date()\n    }\n    db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', id)\n        .update({status: status, finished_time: finished, updated_time: new Date()})\n    return status\n}\n\nif (action == \'list\') {\n    // 最近 100 个租户作业的来源/目标库一次批量预取并按当前角色过滤。\n    var page = db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId)\n        .orderBy(\'created_time\', \'desc\').page(100, 0)\n    var rows = page == null || page.list == null ? [] : page.list\n    var ids = []\n    for (job in rows) {\n        var sourceId = text(job.sourceDbId)\n        var targetId = text(job.targetDbId)\n        if (!ids.contains(sourceId)) { ids.add(sourceId) }\n        if (!ids.contains(targetId)) { ids.add(targetId) }\n    }\n    var visibleIds = visibleDbIdsFor(ids)\n    var jobs = []\n    for (job in rows) {\n        if (visibleIds.contains(text(job.sourceDbId)) && visibleIds.contains(text(job.targetDbId))) {\n            jobs.add(job)\n        }\n    }\n    return {jobs: jobs}\n}\nif (action == \'sourceOptions\') {\n    // 在数据库分页之前施加当前角色的 ALL/ORG/OWNER 条件；不先取全量再过滤。\n    var scope = dataScope.resource(\'MENU:2081000000000000002\')\n    var query = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0).eq(\'asset_status\', 2)\n    if (scope.scope == \'OWNER\') { query = query.eq(\'created_by\', scope.userId) }\n    if (scope.scope == \'ORG\') {\n        if (scope.organizationIds == null || scope.organizationIds.size() == 0) {\n            return {list: [], total: 0}\n        }\n        query = query.in(\'org_id\', scope.organizationIds)\n    }\n    if (![\'ALL\', \'ORG\', \'OWNER\'].contains(text(scope.scope))) { exit 403, \'当前角色数据范围无效\' }\n    var optionsPage = query.orderBy(\'updated_time\', \'desc\').page(201, 0)\n    if (optionsPage != null && optionsPage.total > 200) {\n        exit 400, \'当前角色可见来源库超过200个，请先缩小数据范围\'\n    }\n    var options = []\n    var optionRows = optionsPage == null || optionsPage.list == null ? [] : optionsPage.list\n    for (row in optionRows) {\n        // 禁止将连接串、账号、口令等 db_datasource_t 原始配置返回浏览器。\n        options.add({tid: text(row.tid), dbName: text(row.dbName), dbType: text(row.dbType)})\n    }\n    return {list: options,\n        total: optionsPage == null ? 0 : optionsPage.total}\n}\nif (action == \'targetOptions\') {\n    // 目标库仍须属于 ODS 分域配置，同时按当前角色数据源范围过滤。\n    var dictRoot = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'dict_code\', \'dataSourceType\').eq(\'parent_id\', \'0\').eq(\'is_del\', 0).selectOne()\n    if (dictRoot == null) { return {list: [], total: 0} }\n    var odsRoot = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'parent_id\', dictRoot.tid).eq(\'dict_code\', \'ods\').eq(\'is_del\', 0).selectOne()\n    if (odsRoot == null) { return {list: [], total: 0} }\n    var domainPage = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'parent_id\', odsRoot.tid).eq(\'is_del\', 0).page(201, 0)\n    if (domainPage == null || domainPage.total > 200) { exit 400, \'ODS分域超过200个，请缩小范围\' }\n    var domainRows = domainPage.list == null ? [] : domainPage.list\n    var domainIds = []\n    for (domain in domainRows) { domainIds.add(text(domain.tid)) }\n    if (domainIds.size() == 0) { return {list: [], total: 0} }\n    var relationPage = db.table(\'dwm_center_layer_source_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'target_type\', \'domain\')\n        .eq(\'is_del\', 0).in(\'target_id\', domainIds).page(201, 0)\n    if (relationPage == null || relationPage.total > 200) { exit 400, \'ODS目标库关联超过200个，请缩小范围\' }\n    var relations = relationPage.list == null ? [] : relationPage.list\n    var dbIds = []\n    for (relation in relations) {\n        var candidateId = text(relation.datasourceId)\n        if (!blank(candidateId) && !dbIds.contains(candidateId)) { dbIds.add(candidateId) }\n    }\n    if (dbIds.size() == 0) { return {list: [], total: 0} }\n    var dbRows = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0).eq(\'show_connect\', 1).in(\'tid\', dbIds).select()\n    var visibleRows = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', dbRows)\n    var options = []\n    for (row in visibleRows) {\n        options.add({tid: text(row.tid), dbName: text(row.dbName), dbType: text(row.dbType)})\n    }\n    return {list: options, total: options.size()}\n}\nif (action == \'preview\') {\n    var previewDbId = text(body?.datasourceId).trim()\n    var pageNum = body?.pageNum == null ? 1 : body.pageNum::int\n    var pageSize = body?.pageSize == null ? 20 : body.pageSize::int\n    if (blank(previewDbId) || pageNum < 1 || pageNum > 100000 || pageSize < 1 || pageSize > 50) {\n        exit 400, \'来源表分页参数无效\'\n    }\n    var previewDb = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'tid\', previewDbId).eq(\'is_del\', 0).eq(\'asset_status\', 2).selectOne()\n    if (previewDb == null || dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', [previewDb]).size() != 1) {\n        exit 403, \'来源库不存在或不在当前角色的数据范围内\'\n    }\n    var tablePage = db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'datasource_id\', previewDbId).eq(\'is_del\', 0).eq(\'asset_status\', 2)\n        .in(\'business_type\', [\'业务表\', \'日志表\', \'字典表\'])\n        .orderBy(\'updated_time\', \'desc\').page(pageSize, (pageNum - 1) * pageSize)\n    var tableRows = tablePage == null || tablePage.list == null ? [] : tablePage.list\n    if (tableRows.size() == 0) {\n        return {list: [], total: tablePage == null ? 0 : tablePage.total}\n    }\n    var ids = []\n    for (row in tableRows) { ids.add(text(row.tid)) }\n    var linkedPage = db.table(\'db_table_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0).in(\'source_table_id\', ids).page(pageSize * 2 + 1, 0)\n    if (linkedPage == null || linkedPage.total > pageSize * 2) {\n        exit 400, \'当前页物化目标关系过多，请核对后重试\'\n    }\n    var targetGroups = {}\n    var linkedRows = linkedPage.list == null ? [] : linkedPage.list\n    var targetDbIds = []\n    for (targetRow in linkedRows) {\n        var candidateDbId = text(targetRow.datasourceId)\n        if (!blank(candidateDbId) && !targetDbIds.contains(candidateDbId)) { targetDbIds.add(candidateDbId) }\n    }\n    var visibleTargetDbIds = visibleDbIdsFor(targetDbIds)\n    var visibleTargetTableIds = []\n    var relationCounts = {}\n    for (targetRow in linkedRows) {\n        var sourceId = text(targetRow.sourceTableId)\n        if (text(targetRow.tid) == sourceId) { continue }\n        var key = \'id:\' + sourceId\n        relationCounts[key] = relationCounts[key] == null ? 1 : relationCounts[key] + 1\n        if (!visibleTargetDbIds.contains(text(targetRow.datasourceId))) { continue }\n        visibleTargetTableIds.add(text(targetRow.tid))\n        if (targetGroups[key] == null) { targetGroups[key] = [] }\n        targetGroups[key].add({targetTableId: text(targetRow.tid),\n            targetTableName: text(targetRow.tableName),\n            targetDbId: text(targetRow.datasourceId), targetDbName: \'\'})\n    }\n    var taskPage = db.table(\'data_access_agg_task_t\').where()\n        .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n        .in(\'source_table_id\', ids).page(pageSize * 5 + 1, 0)\n    if (taskPage == null || taskPage.total > pageSize * 5) {\n        exit 400, \'当前页已有接入任务过多，请核对后重试\'\n    }\n    var tasks = {}\n    var taskRows = taskPage.list == null ? [] : taskPage.list\n    for (task in taskRows) {\n        if (!visibleTargetTableIds.contains(text(task.targetTableId))) { continue }\n        var taskKey = \'id:\' + text(task.sourceTableId)\n        if (tasks[taskKey] == null) { tasks[taskKey] = task }\n    }\n    var result = []\n    for (row in tableRows) {\n        var key = \'id:\' + text(row.tid)\n        var targetTables = targetGroups[key] == null ? [] : targetGroups[key]\n        var existingTask = tasks[key]\n        result.add({tid: text(row.tid), datasourceId: previewDbId,\n            tableName: text(row.tableName), tableNameCn: text(row.tableNameCn),\n            sourceCatalogId: text(row.sourceCatalogId), targetTables: targetTables,\n            relationAmbiguous: relationCounts[key] != null && relationCounts[key] > 1,\n            taskCount: existingTask == null ? 0 : 1,\n            accessTaskId: existingTask == null ? \'\' : text(existingTask.tid)})\n    }\n    return {list: result, total: tablePage.total}\n}\nif (action == \'detail\') {\n    if (blank(jobId)) { exit 400, \'jobId不能为空\' }\n    return detail(jobId)\n}\nif (action == \'create\') {\n    var requestKey = text(body?.requestKey).trim()\n    var sourceDbId = text(body?.sourceDbId).trim()\n    var targetDbId = text(body?.targetDbId).trim()\n    var requested = body?.items\n    if (blank(requestKey) || requestKey.length() > 64 || !requestKey.matches(\'^[A-Za-z0-9_-]+$\')) {\n        exit 400, \'请求幂等键无效\'\n    }\n    if (blank(sourceDbId) || blank(targetDbId)) { exit 400, \'请选择来源库和目标库\' }\n    if (requested == null || requested.size() == 0 || requested.size() > 500) {\n        exit 400, \'每个批量作业须选择 1 至 500 张来源表\'\n    }\n    var rules = {\n        removePrefix: text(body?.matchRule?.removePrefix),\n        addPrefix: text(body?.matchRule?.addPrefix),\n        addSuffix: text(body?.matchRule?.addSuffix)\n    }\n    var ruleJson = JSONUtil.toJsonStr(rules)\n    var seen = {}\n    var sourceIds = []\n    var requestedPairs = []\n    for (requestedItem in requested) {\n        var sourceId = text(requestedItem?.sourceTableId).trim()\n        var targetId = text(requestedItem?.targetTableId).trim()\n        if (blank(sourceId) || blank(targetId) || seen[\'id:\' + sourceId] != null) {\n            exit 400, \'来源表或目标表标识缺失，或同一来源表重复提交\'\n        }\n        seen[\'id:\' + sourceId] = true\n        sourceIds.add(sourceId)\n        requestedPairs.add({sourceId: sourceId, targetId: targetId})\n    }\n    var verifySameRequest = priorJob => {\n        if (text(priorJob.sourceDbId) != sourceDbId || text(priorJob.targetDbId) != targetDbId\n            || text(priorJob.matchRuleJson) != ruleJson) {\n            exit 409, \'幂等键已用于不同的来源库、目标库或匹配规则\'\n        }\n        var priorItems = itemsOf(priorJob.jobId)\n        if (priorItems.size() != requestedPairs.size()) {\n            exit 409, \'幂等键已用于不同的来源表清单\'\n        }\n        var index = 0\n        for (pair in requestedPairs) {\n            if (text(priorItems[index].sourceTableId) != pair.sourceId\n                || text(priorItems[index].targetTableId) != pair.targetId) {\n                exit 409, \'幂等键已用于不同的来源表或目标表清单\'\n            }\n            index = index + 1\n        }\n        return detail(priorJob.jobId)\n    }\n    var sourceDb = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'tid\', sourceDbId).eq(\'is_del\', 0).selectOne()\n    var targetDb = db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'tid\', targetDbId).eq(\'is_del\', 0).selectOne()\n    if (sourceDb == null || targetDb == null || text(sourceDb.assetStatus) != \'2\') {\n        exit 400, \'所选数据库不存在、不属于当前租户或来源库尚未完成登记\'\n    }\n    // 当前会话角色的 ALL/ORG/OWNER 数据源范围只计算一次，随后每个\n    // 来源/目标 ID 都须通过已授权的数据源关系；混入无权项整单拒绝。\n    var visibleDbs = dataScope.visibleDataSourcesFor(\'MENU:2081000000000000002\', [sourceDb, targetDb])\n    var visibleDbIds = []\n    for (visibleDb in visibleDbs) { visibleDbIds.add(text(visibleDb.tid)) }\n    if (!visibleDbIds.contains(sourceDbId) || !visibleDbIds.contains(targetDbId)) {\n        exit 403, \'来源库或目标库不在当前角色的数据范围内\'\n    }\n    var prior = db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId)\n        .eq(\'request_key\', requestKey).selectOne()\n    if (prior != null) { return verifySameRequest(prior) }\n    try {\n    return db.transaction(() => {\n        var existing = db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'request_key\', requestKey).selectOne()\n        if (existing != null) { return verifySameRequest(existing) }\n        var newJobId = IdUtil.simpleUUID()\n        var jobName = text(body?.jobName).trim()\n        if (blank(jobName)) { jobName = \'批量创建任务\' }\n        if (jobName.length() > 255) { exit 400, \'作业名称不能超过255个字符\' }\n        // 每组最多 100 个 ID；查询带当前会话租户和已登记来源库约束。\n        // 关联目标每组只取最多 2N+1 行；超过 N 个唯一目标的请求必定无效，\n        // 因此无需全量装载异常的一对多关系。\n        var sourceRows = {}\n        var targetGroups = {}\n        var offset = 0\n        while (offset < sourceIds.size()) {\n            var end = offset + 100\n            if (end > sourceIds.size()) { end = sourceIds.size() }\n            var chunk = sourceIds.subList(offset::int, end::int)\n            var sourcesInChunk = db.table(\'db_table_t\').where()\n                .eq(\'tenant_id\', tenantId).eq(\'datasource_id\', sourceDbId)\n                .eq(\'is_del\', 0).in(\'tid\', chunk).select()\n            for (sourceRow in sourcesInChunk) {\n                sourceRows[\'id:\' + text(sourceRow.tid)] = sourceRow\n            }\n            var maxLinkedRows = chunk.size() * 2 + 1\n            var linkedPage = db.table(\'db_table_t\').where()\n                .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0)\n                .in(\'source_table_id\', chunk).page(maxLinkedRows, 0)\n            if (linkedPage == null || linkedPage.total > chunk.size() * 2) {\n                exit 400, \'物化目标表关联过多，请核对来源表后分批重试\'\n            }\n            var linkedRows = linkedPage.list == null ? [] : linkedPage.list\n            for (targetRow in linkedRows) {\n                var linkedSourceId = text(targetRow.sourceTableId)\n                var linkedTargetId = text(targetRow.tid)\n                if (linkedTargetId == linkedSourceId) { continue }\n                var key = \'id:\' + linkedSourceId\n                if (targetGroups[key] == null) { targetGroups[key] = [] }\n                targetGroups[key].add(targetRow)\n            }\n            offset = offset + 100\n        }\n        // 已批量预取所有来源与关联目标。这里逐 ID 校验只访问内存，\n        // 缺失、跨租户、非本库或一对多任一项都会拒绝整单，不静默跳过。\n        var checkedItems = []\n        for (requestedItem in requested) {\n            var sourceId = text(requestedItem?.sourceTableId).trim()\n            var targetId = text(requestedItem?.targetTableId).trim()\n            var sourceTable = sourceRows[\'id:\' + sourceId]\n            var linkedTargets = targetGroups[\'id:\' + sourceId]\n            var targetTable = linkedTargets == null || linkedTargets.size() != 1 ? null : linkedTargets[0]\n            if (sourceTable == null || text(sourceTable.assetStatus) != \'2\'\n                || ![\'业务表\', \'日志表\', \'字典表\'].contains(text(sourceTable.businessType))\n                || targetTable == null || text(targetTable.tid) != targetId\n                || text(targetTable.datasourceId) != targetDbId) {\n                exit 400, \'来源表或唯一物化目标表已变化，请刷新匹配预览\'\n            }\n            checkedItems.add({sourceId: sourceId, sourceTable: sourceTable,\n                targetId: targetId, targetTable: targetTable})\n        }\n        db.table(\'ods_batch_create_job_t\').primary(\'job_id\').insert({\n            job_id: newJobId, tenant_id: tenantId, request_key: requestKey,\n            job_name: jobName, source_db_id: sourceDbId, target_db_id: targetDbId,\n            match_rule_json: ruleJson, status: \'RUNNING\',\n            stop_requested: 0, total_count: requested.size(),\n            created_time: now, updated_time: now\n        })\n        var index = 0\n        for (checked in checkedItems) {\n            db.table(\'ods_batch_create_item_t\').primary(\'item_id\').insert({\n                item_id: IdUtil.simpleUUID(), job_id: newJobId, tenant_id: tenantId,\n                item_index: index, source_table_id: checked.sourceId,\n                source_table_name: text(checked.sourceTable.tableName),\n                source_catalog_id: checked.sourceTable.sourceCatalogId,\n                target_table_id: checked.targetId, target_table_name: text(checked.targetTable.tableName),\n                status: \'PENDING\', attempt_count: 0,\n                created_time: now, updated_time: now\n            })\n            index = index + 1\n        }\n        return detail(newJobId)\n    })\n    } catch (e) {\n        // 同一幂等键的并发首提可能在唯一约束处竞争；事务回滚后回读胜者。\n        var winner = db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'request_key\', requestKey).selectOne()\n        if (winner != null) { return verifySameRequest(winner) }\n        throw e\n    }\n}\n\nif (blank(jobId)) { exit 400, \'jobId不能为空\' }\nif (action == \'stop\') {\n    return db.transaction(() => {\n        var job = db.selectOne(\'SELECT * FROM ods_batch_create_job_t WHERE tenant_id = #{tenantId} AND job_id = #{jobId} FOR UPDATE\')\n        assertJobVisible(job)\n        db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', jobId)\n            .update({stop_requested: 1, status: \'STOPPED\', finished_time: new Date(), updated_time: new Date()})\n        return detail(jobId)\n    })\n}\nif (action == \'retry\') {\n    return db.transaction(() => {\n        var job = db.selectOne(\'SELECT * FROM ods_batch_create_job_t WHERE tenant_id = #{tenantId} AND job_id = #{jobId} FOR UPDATE\')\n        assertJobVisible(job)\n        var freshRunning = db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'job_id\', jobId).eq(\'status\', \'RUNNING\').gt(\'claimed_time\', leaseCutoff).selectOne()\n        if (freshRunning != null) { exit 409, \'仍有创建项正在执行，请稍后重试\' }\n        var counts = countsOf(jobId)\n        if (counts.pending + counts.failed + counts.running == 0) { return detail(jobId) }\n        for (status in [\'FAILED\', \'RUNNING\']) {\n            db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n                .eq(\'job_id\', jobId).eq(\'status\', status).update({\n                    status: \'PENDING\', lease_token: null, claimed_time: null,\n                    error_message: null, updated_time: new Date()\n                })\n        }\n        db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', jobId)\n            .update({stop_requested: 0, status: \'RUNNING\', finished_time: null, updated_time: new Date()})\n        return detail(jobId)\n    })\n}\nif (action == \'claim\') {\n    return db.transaction(() => {\n        var job = db.selectOne(\'SELECT * FROM ods_batch_create_job_t WHERE tenant_id = #{tenantId} AND job_id = #{jobId} FOR UPDATE\')\n        assertJobVisible(job)\n        if (job.stopRequested == true || text(job.stopRequested) == \'1\') {\n            return {done: true, stopped: true, status: \'STOPPED\'}\n        }\n        // 只允许同一作业同时执行一项；10 分钟失联租约可重新领取，确保断线可续跑。\n        var running = db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'job_id\', jobId).eq(\'status\', \'RUNNING\').orderBy(\'item_index\', \'asc\').selectOne()\n        if (running != null) {\n            var stale = running.claimedTime == null ? running : db.table(\'ods_batch_create_item_t\').where()\n                .eq(\'tenant_id\', tenantId).eq(\'item_id\', running.itemId)\n                .lte(\'claimed_time\', leaseCutoff).selectOne()\n            if (stale == null) { return {done: false, busy: true, status: \'RUNNING\'} }\n            db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n                .eq(\'item_id\', running.itemId).eq(\'status\', \'RUNNING\')\n                .update({status: \'PENDING\', lease_token: null, claimed_time: null, updated_time: new Date()})\n        }\n        var item = db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'job_id\', jobId).eq(\'status\', \'PENDING\').orderBy(\'item_index\', \'asc\').selectOne()\n        if (item == null) {\n            var finalStatus = refreshStatus(jobId)\n            return {done: true, status: finalStatus}\n        }\n        // 同一租户同一来源表的不同作业也不能并发调用单项确保接口。\n        // 先锁来源表行，使两个作业的领取事务串行，再检查跨作业租约。\n        var sourceTableId = text(item.sourceTableId)\n        var sourceLock = db.selectOne(\'SELECT tid FROM db_table_t WHERE tenant_id = #{tenantId} AND tid = #{sourceTableId} AND is_del = 0 FOR UPDATE\')\n        if (sourceLock == null) { exit 409, \'来源表已失效，请刷新批量作业\' }\n        var otherRunning = db.table(\'ods_batch_create_item_t\').where()\n            .eq(\'tenant_id\', tenantId).eq(\'source_table_id\', sourceTableId)\n            .eq(\'status\', \'RUNNING\').selectOne()\n        if (otherRunning != null) {\n            if (otherRunning.claimedTime != null && otherRunning.claimedTime.after(leaseCutoff)) {\n                return {done: false, busy: true, status: \'RUNNING\'}\n            }\n            db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n                .eq(\'item_id\', otherRunning.itemId).eq(\'status\', \'RUNNING\')\n                .update({status: \'PENDING\', lease_token: null, claimed_time: null,\n                    updated_time: new Date()})\n        }\n        var lease = IdUtil.simpleUUID()\n        db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'item_id\', item.itemId).eq(\'status\', \'PENDING\').update({\n                status: \'RUNNING\', lease_token: lease,\n                attempt_count: item.attemptCount + 1, claimed_time: new Date(),\n                updated_time: new Date()\n            })\n        db.table(\'ods_batch_create_job_t\').where().eq(\'tenant_id\', tenantId).eq(\'job_id\', jobId)\n            .update({status: \'RUNNING\', updated_time: new Date()})\n        var claimedItem = db.table(\'ods_batch_create_item_t\').where()\n            .eq(\'tenant_id\', tenantId).eq(\'item_id\', item.itemId).selectOne()\n        return {done: false, busy: false, item: publicItem(claimedItem), leaseToken: lease}\n    })\n}\nif (action == \'complete\') {\n    var itemId = text(body?.itemId).trim()\n    var leaseToken = text(body?.leaseToken).trim()\n    var success = body?.success == true\n    var taskId = text(body?.taskId).trim()\n    var errorMessage = text(body?.error).trim()\n    if (blank(itemId) || blank(leaseToken) || (success && blank(taskId))) {\n        exit 400, \'完成回报缺少创建项、租约或任务标识\'\n    }\n    if (!success && blank(errorMessage)) { errorMessage = \'创建接口未返回成功结果\' }\n    if (errorMessage.length() > 2000) { errorMessage = errorMessage.substring(0, 2000) }\n    return db.transaction(() => {\n        var job = db.selectOne(\'SELECT * FROM ods_batch_create_job_t WHERE tenant_id = #{tenantId} AND job_id = #{jobId} FOR UPDATE\')\n        assertJobVisible(job)\n        var item = db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'job_id\', jobId).eq(\'item_id\', itemId).selectOne()\n        if (item == null) { exit 404, \'创建项不存在或不属于当前租户\' }\n        if (success) {\n            // 客户端只报告结果；服务端按当前租户及本项来源/目标表确认真实任务。\n            var actualTask = db.table(\'data_access_agg_task_t\').where()\n                .eq(\'tenant_id\', tenantId).eq(\'tid\', taskId).eq(\'is_del\', 0)\n                .eq(\'source_table_id\', item.sourceTableId)\n                .eq(\'target_table_id\', item.targetTableId).selectOne()\n            if (actualTask == null) {\n                exit 409, \'回报的接入任务不存在或与当前来源表、目标表不一致\'\n            }\n        }\n        if (item.status == \'SUCCEEDED\' && success && item.taskId == taskId) { return detail(jobId) }\n        if (item.status != \'RUNNING\' || item.leaseToken != leaseToken) {\n            exit 409, \'创建项租约已失效，请刷新作业并按幂等流程重试\'\n        }\n        db.table(\'ods_batch_create_item_t\').where().eq(\'tenant_id\', tenantId)\n            .eq(\'job_id\', jobId).eq(\'item_id\', itemId).eq(\'lease_token\', leaseToken)\n            .update({status: success ? \'SUCCEEDED\' : \'FAILED\', task_id: success ? taskId : null,\n                was_existing: success ? (body?.existing == true ? 1 : 0) : null,\n                error_message: success ? null : errorMessage,\n                completed_time: new Date(), updated_time: new Date()})\n        refreshStatus(jobId)\n        return detail(jobId)\n    })\n}\nexit 400, \'不支持的批量作业操作\'\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/19.批量创建任务作业.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1f4028f20aaa4f379b5e37a343b99fa9',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "1f4028f20aaa4f379b5e37a343b99fa9",\r\n  "name" : "03.数据接入",\r\n  "type" : "api",\r\n  "parentId" : "0",\r\n  "path" : "/ods",\r\n  "createTime" : 1784420517826,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.数据接入/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('433544a14a5245e2b1be6ed6fef630c3',NULL,NULL,'{\n  "properties": {},\n  "id": "433544a14a5245e2b1be6ed6fef630c3",\n  "script": null,\n  "groupId": "99c8dd7189af40939e5110b76bcd7160",\n  "name": "01.接入任务首次获取字段映射模板",\n  "createTime": 1782955344828,\n  "updateTime": 1782955348384,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/autoMappingTemplate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"0d50a16cf9b5458398a22f6fa158ea57\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"sourceDbId\\": \\"38ef1b566eb4477ebfc07b4c0c8aa973\\",\\n        \\"sourceTableId\\": \\"192db5c37e69463c86061e66b3c89d89\\",\\n        \\"sourceTablePrimaryKey\\": \\"id\\",\\n        \\"sourceTableIncrementKey\\": \\"\\",\\n        \\"targetDbId\\": \\"62d25cc8bf1344d6b9f41fed23af4eaf\\",\\n        \\"targetTableId\\": \\"e85f4253dc8d4564a3bcef3b00053219\\",\\n        \\"targetTablePrimaryKey\\": \\"\\",\\n        \\"columnMapping\\": [\\n            {\\n                \\"sourceField\\": \\"id\\",\\n                \\"sourceFieldCn\\": \\"序号\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"int\\",\\n                \\"targetField\\": \\"id\\",\\n                \\"targetFieldCn\\": \\"主键\\",\\n                \\"targetFieldLength\\": 36,\\n                \\"targetDataType\\": \\"varchar\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"name\\",\\n                \\"sourceFieldCn\\": \\"姓名\\",\\n                \\"sourceFieldLength\\": 50,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"name\\",\\n                \\"targetFieldCn\\": \\"角色名称\\",\\n                \\"targetFieldLength\\": 255,\\n                \\"targetDataType\\": \\"varchar\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"nationality\\",\\n                \\"sourceFieldCn\\": \\"国籍\\",\\n                \\"sourceFieldLength\\": 50,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"id_number\\",\\n                \\"sourceFieldCn\\": \\"证件号码\\",\\n                \\"sourceFieldLength\\": 50,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"entry_date\\",\\n                \\"sourceFieldCn\\": \\"入境日期\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"date\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"entry_port\\",\\n                \\"sourceFieldCn\\": \\"入境口岸\\",\\n                \\"sourceFieldLength\\": 100,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"current_location\\",\\n                \\"sourceFieldCn\\": \\"当前位置\\",\\n                \\"sourceFieldLength\\": 100,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"in_border_status\\",\\n                \\"sourceFieldCn\\": \\"在境状态\\",\\n                \\"sourceFieldLength\\": 20,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"risk_level\\",\\n                \\"sourceFieldCn\\": \\"风险等级\\",\\n                \\"sourceFieldLength\\": 20,\\n                \\"sourceDataType\\": \\"varchar\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"last_activity_time\\",\\n                \\"sourceFieldCn\\": \\"最后活动时间\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"datetime\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"is_del\\",\\n                \\"sourceFieldCn\\": \\"删除标记（0-未删除，1-已删除）\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"tinyint\\",\\n                \\"targetField\\": \\"is_del\\",\\n                \\"targetFieldCn\\": \\"是否删除：0未删除，1已删除\\",\\n                \\"targetFieldLength\\": 0,\\n                \\"targetDataType\\": \\"int\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"create_time\\",\\n                \\"sourceFieldCn\\": \\"创建时间\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"datetime\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            },\\n            {\\n                \\"sourceField\\": \\"update_time\\",\\n                \\"sourceFieldCn\\": \\"更新时间\\",\\n                \\"sourceFieldLength\\": 0,\\n                \\"sourceDataType\\": \\"datetime\\",\\n                \\"targetField\\": \\"\\",\\n                \\"targetFieldCn\\": \\"\\",\\n                \\"targetFieldLength\\": null,\\n                \\"targetDataType\\": \\"\\",\\n                \\"dictEnable\\": 0,\\n                \\"dictValue\\": null,\\n                \\"dictCode\\": null,\\n                \\"funcEnable\\": 0,\\n                \\"funcValue\\": null,\\n                \\"funcCode\\": null\\n            }\\n        ]\\n    }\\n}",\n  "description": "按接入任务关联的源表读取字段定义，生成首次配置字段映射时使用的候选模板。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.接入任务首次获取字段映射模板\n// 路由：POST /autoMappingTemplate\n// 业务说明：按接入任务关联的源表读取字段定义，生成首次配置字段映射时使用的候选模板。\nimport log\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\n\n\n//查询es 获取主表数据\nvar catalog = esCommonService.getDocument("dataassets", body?.tid)\n\nvar sourceTableId = catalog.sourceTableId\nvar sourceTablePrimaryKey = ""\nvar sourceTableIncrementKey = ""\nvar targetTableId = catalog.targetTableId\nvar targetTablePrimaryKey = ""\n\n\nif( sourceTableId == null || sourceTableId == ""){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,"sourceTableId参数不能为空"\n}\n\nif( targetTableId == null || targetTableId == ""){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,"targetTableId参数不能为空"\n}\n\n//查询源表字段\nvar sourceTableColumns = db.table("db_table_column_t").where()\n    .eq("table_id", sourceTableId)\n    .eq("is_del","0")\n    .orderBy("ordinal_position", "asc")\n    .select()\n    \n\n//查询目标表字段\nvar targetTableColumns = db.table("db_table_column_t").where()\n    .eq("table_id", targetTableId)\n    .eq("is_del","0")\n    .select()\n\n\n\n//构建目标字段映射表（字段名 -> 字段信息）\nvar targetColumnMap = {}\nif (targetTableColumns != null && targetTableColumns.size() > 0) {\n    for (col in targetTableColumns) {\n        targetColumnMap[col.columnName] = col\n        //获取 主键\n        if(col.primaryKey == 1){\n            targetTablePrimaryKey =  col.columnName\n        }\n        \n    }\n}\n\n//生成字段映射结果\nvar mappingResult = []\nvar now = new Date()\n\n\nif (sourceTableColumns != null && sourceTableColumns.size() > 0) {\n    for (index, sourceCol in sourceTableColumns) {\n        //获取 主键\n        if(sourceCol.primaryKey == 1){\n            sourceTablePrimaryKey =  sourceCol.columnName\n        }\n        var mappingItem = {\n            sourceField: sourceCol.columnName,\n            sourceFieldCn: sourceCol.columnComment,\n            sourceFieldLength: sourceCol.length,\n            sourceDataType: sourceCol.dataType,\n            targetField: "",\n            targetFieldCn: "",\n            targetFieldLength: null,\n            targetDataType: "",\n            dictEnable: 0,\n            dictValue: null,\n            dictCode: null,\n            funcEnable: 0,\n            funcValue: null,\n            funcCode: null\n        }\n        \n        //通过字段名称匹配目标字段\n        var targetCol = targetColumnMap[sourceCol.columnName]\n        if (targetCol != null) {\n            mappingItem.targetField = targetCol.columnName\n            mappingItem.targetFieldCn = targetCol.columnComment\n            mappingItem.targetFieldLength = targetCol.length\n            mappingItem.targetDataType = targetCol.dataType\n        }\n        \n        mappingResult.add(mappingItem)\n    }\n}\n\nvar template = {\n    sourceDbId : catalog.dbId,\n    sourceTableId : catalog.sourceTableId,\n    sourceTablePrimaryKey : sourceTablePrimaryKey,\n    sourceTableIncrementKey : "",\n    targetDbId : catalog.targetDbId,\n    targetTableId : catalog.targetTableId,\n    targetTablePrimaryKey : targetTablePrimaryKey,\n    columnMapping : mappingResult\n\n}\n\nlog.info(\'自动字段映射成功, 源表字段数: {}, 匹配数: {}\', sourceTableColumns?.size() || 0, mappingResult.filter(item => item.targetField != "").size())\n\n// 返回当前业务分支的标准结果。\nreturn template\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/03.鏁版嵁鎺ュ叆/02.鎺ュ叆浠诲姟/01.接入任务首次获取字段映射模板.ms');
