INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5b83c2702e9b4c9687392a291ca9162a',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "5b83c2702e9b4c9687392a291ca9162a",\r\n  "script" : null,\r\n  "groupId" : "55c792d1ba0f4cb79b01a6d5c42dacea",\r\n  "name" : "01.数据元分页查询",\r\n  "createTime" : 1782955344950,\r\n  "updateTime" : 1791107424921,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/page",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"pageNum\\": \\"1\\",\\n    \\"pageSize\\": \\"10\\",\\n    \\"categoryPath\\": \\"0,1891200000000000003,1891200000000000301\\"\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "根据名称、编码、标准编码、分级、分类及发布状态筛选数据元，返回分页记录和总数。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : {\r\n    "name" : "",\r\n    "value" : "",\r\n    "description" : "",\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : "",\r\n    "error" : "",\r\n    "expression" : "",\r\n    "children" : [ {\r\n      "name" : "code",\r\n      "value" : "100120",\r\n      "description" : "",\r\n      "required" : false,\r\n      "dataType" : "Integer",\r\n      "type" : null,\r\n      "defaultValue" : null,\r\n      "validateType" : "",\r\n      "error" : "",\r\n      "expression" : "",\r\n      "children" : [ ]\r\n    }, {\r\n      "name" : "msg",\r\n      "value" : "user_no_login",\r\n      "description" : "",\r\n      "required" : false,\r\n      "dataType" : "String",\r\n      "type" : null,\r\n      "defaultValue" : null,\r\n      "validateType" : "",\r\n      "error" : "",\r\n      "expression" : "",\r\n      "children" : [ ]\r\n    }, {\r\n      "name" : "success",\r\n      "value" : "false",\r\n      "description" : "",\r\n      "required" : false,\r\n      "dataType" : "Boolean",\r\n      "type" : null,\r\n      "defaultValue" : null,\r\n      "validateType" : "",\r\n      "error" : "",\r\n      "expression" : "",\r\n      "children" : [ ]\r\n    }, {\r\n      "name" : "data",\r\n      "value" : "null",\r\n      "description" : "",\r\n      "required" : false,\r\n      "dataType" : "Object",\r\n      "type" : null,\r\n      "defaultValue" : null,\r\n      "validateType" : "",\r\n      "error" : "",\r\n      "expression" : "",\r\n      "children" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\n// 接口：01.数据元分页查询\n// 路由：POST /dwm/standard/element/page\n// 业务说明：根据名称、编码、标准编码、分级、分类及发布状态筛选数据元，返回分页记录和总数。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\nimport tenantRuntime\nimport cn.hutool.json.JSONUtil\n\n/**\n * 分页查询数据元管理\n * POST /api/gov/data/meta/page\n * \n * 支持分页查询数据元管理列表\n */\n\n// 获取分页参数\nvar pageNum = body?.pageNum::long(0)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0? 0 : (pageNum - 1)* pageSize\nvar tenantId = tenantRuntime.id()\nif (tenantId == null || (tenantId + \'\').trim() == \'\') {\n    exit 401, \'登录状态已失效，请重新登录\'\n}\n\n// 获取查询条件\nvar metaName = body?.metaName\nvar metaCode = body?.metaCode\nvar standardEncode = body?.standardEncode\nvar dataLevel = body?.dataLevel\nvar dataCategoryId = body?.dataCategoryId\nvar publishStatus = body?.publishStatus\nvar categoryPath = body?.categoryPath\n\n// 构建查询条件\nvar query = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n\nif (metaName != null && metaName != \'\') {\n    query = query.like(\'meta_name\', \'%\' + metaName + \'%\')\n}\n\nif (metaCode != null && metaCode != \'\') {\n    query = query.like(\'meta_code\', \'%\' + metaCode + \'%\')\n}\n\nif (standardEncode != null && standardEncode != \'\') {\n    query = query.like(\'standard_encode\', \'%\' + standardEncode + \'%\')\n}\n\nif (dataLevel != null && dataLevel != \'\') {\n    query = query.eq(\'data_level\', dataLevel)\n}\n\nif (dataCategoryId != null && dataCategoryId != \'\') {\n    query = query.eq(\'data_category_id\', dataCategoryId)\n}\n\nif (publishStatus != null) {\n    query = query.eq(\'publish_status\', publishStatus)\n}\n\nif (categoryPath != null) {\n    query = query.like(\'data_category_path\', categoryPath + "%")\n}\n\n// ========== 查询总数 ==========\nvar total = query.count()\n\n// ========== 查询列表 ==========\nvar list = query\n    .orderBy(\'created_time\', \'desc\')\n    .page(pageSize, offsetLimit)\n\n// 当前页需要展示数据字典项数。先批量取代码记录，再按原详情接口的\n// tid -> dict_code -> code_set 优先级回填，不能对每个数据元发一次详情查询。\nvar pageRows = list?.list == null ? [] : list.list\nvar domainIds = []\nvar seenDomainIds = {}\nfor (row in pageRows) {\n    var domainId = row?.valueDomainId == null ? \'\' : (row.valueDomainId + \'\').trim()\n    if (domainId != \'\' && seenDomainIds[domainId] == null) {\n        domainIds.add(domainId)\n        seenDomainIds[domainId] = true\n    }\n}\n\nvar codeByDomainId = {}\nif (domainIds.size() > 0) {\n    var directCodes = db.table(\'da_metadata_code_t\').where()\n        .in(\'tid\', domainIds).eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n    for (code in (directCodes == null ? [] : directCodes)) {\n        codeByDomainId[code.tid + \'\'] = code\n    }\n\n    var unresolvedIds = []\n    for (domainId in domainIds) {\n        if (codeByDomainId[domainId] == null) {\n            unresolvedIds.add(domainId)\n        }\n    }\n    if (unresolvedIds.size() > 0) {\n        var dictCodeRows = db.table(\'da_metadata_code_t\').where()\n            .in(\'dict_code\', unresolvedIds).eq(\'code_value\', \'__HEADER__\')\n            .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n        for (code in (dictCodeRows == null ? [] : dictCodeRows)) {\n            var codeKey = (code.dictCode == null ? code.dict_code : code.dictCode) + \'\'\n            if (codeByDomainId[codeKey] == null) {\n                codeByDomainId[codeKey] = code\n            }\n        }\n\n        var stillUnresolvedIds = []\n        for (domainId in unresolvedIds) {\n            if (codeByDomainId[domainId] == null) {\n                stillUnresolvedIds.add(domainId)\n            }\n        }\n        if (stillUnresolvedIds.size() > 0) {\n            var codeSetRows = db.table(\'da_metadata_code_t\').where()\n                .in(\'code_set\', stillUnresolvedIds).eq(\'code_value\', \'__HEADER__\')\n                .eq(\'tenant_id\', tenantId).eq(\'is_del\', 0).select()\n            for (code in (codeSetRows == null ? [] : codeSetRows)) {\n                var codeKey = (code.codeSet == null ? code.code_set : code.codeSet) + \'\'\n                if (codeByDomainId[codeKey] == null) {\n                    codeByDomainId[codeKey] = code\n                }\n            }\n        }\n    }\n}\n\nfor (row in pageRows) {\n    var domainId = row?.valueDomainId == null ? \'\' : (row.valueDomainId + \'\').trim()\n    var code = codeByDomainId[domainId]\n    var rawValues = code == null ? null : (code.dictItemValue == null ? code.dict_item_value : code.dictItemValue)\n    var dictionaryCount = 0\n    if (rawValues != null) {\n        try {\n            var jsonText = (rawValues + \'\').trim()\n            if (JSONUtil.isTypeJSONArray(jsonText)) {\n                dictionaryCount = JSONUtil.parseArray(jsonText).size()\n            }\n        } catch (e) {\n            dictionaryCount = 0\n        }\n    }\n    row.dictionaryCount = dictionaryCount\n}\n\nlog.info(\'分页查询数据元管理成功, pageNum: {}, pageSize: {}, total: {}\', pageNum, pageSize, total)\n\n// ========== 返回结果 ==========\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/01.数据元分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0b346b21034e4b0892f9ef825105f9c6',NULL,NULL,'{\n  "properties": {},\n  "id": "0b346b21034e4b0892f9ef825105f9c6",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "02.数据元详情",\n  "createTime": 1782955344986,\n  "updateTime": 1786716526792,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"6069308f214645588a368fef51ce2007\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按数据元主键读取未删除的定义和治理资料，返回编辑与查看页面使用的详情。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据元详情\n// 路由：POST /dwm/standard/element/queryById\n// 业务说明：按数据元主键读取未删除的定义和治理资料，返回编辑与查看页面使用的详情。\nimport log\n\n/**\n * 根据tid查询\n * \n */\n\n// 获取请求参数\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\n// ========== 查询数据 ==========\nvar result = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (result == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'规则不存在\'\n}\n\nlog.info(\'查询数据质量规则成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/02.数据元详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('11e28c173e4245b2b333a87649679aed',NULL,NULL,'{\n  "properties": {},\n  "id": "11e28c173e4245b2b333a87649679aed",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "03.数据元保存修改",\n  "createTime": 1782955344977,\n  "updateTime": 1786716711115,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/metaSaveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"ae1af8482a724d5e855649a9ebb1aead\\",\\n    \\"metaName\\": \\"数据元名称\\",\\n    \\"metaCode\\": \\"data_element_code\\",\\n    \\"standardEncode\\": \\"标准编码\\",\\n    \\"bizDef\\": \\"业务定义\\",\\n    \\"dataTypeId\\": \\"数据类型ID\\",\\n    \\"valueDomainId\\": \\"值域ID\\",\\n    \\"isNullable\\": 0,\\n    \\"dataLevel\\": \\"数据分级\\",\\n    \\"dataCategoryId\\": \\"数据分类ID\\",\\n    \\"dataCategoryName\\": \\"数据分类名称\\",\\n    \\"dataCategoryPath\\": \\"数据分类路径\\",\\n    \\"publishStatus\\": 0,\\n    \\"createdBy\\": \\"创建人\\",\\n    \\"createdTime\\": \\"2026-03-09 14:56:46\\",\\n    \\"updatedBy\\": \\"更新人\\",\\n    \\"updatedTime\\": \\"2026-03-09 14:56:46\\",\\n    \\"isDel\\": 0\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行数据元保存修改，返回保存或配置结果；使用请求参数 tid、metaName、metaCode、standardEncode、bizDef、dataTypeId、fieldType、fieldLength；涉及 da_metadata_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据元保存修改\n// 路由：POST /dwm/standard/element/metaSaveOrUpdate\n// 业务说明：校验请求资料后执行数据元保存修改，返回保存或配置结果；使用请求参数 tid、metaName、metaCode、standardEncode、bizDef、dataTypeId、fieldType、fieldLength；涉及 da_metadata_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport log\n\n/**\n * 保存或更新数据元管理\n * POST /api/gov/data/meta/saveOrUpdate\n * \n * 如果 body.tid 有值则更新，否则新增\n * 数据保存到 da_metadata_t 表\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar metaName = body?.metaName\nvar metaCode = body?.metaCode\nvar standardEncode = body?.standardEncode\nvar bizDef = body?.bizDef\nvar dataTypeId = body?.dataTypeId\nvar fieldType = body?.fieldType\nvar fieldLength = body?.fieldLength\nvar numericPrecision = body?.numericPrecision\nvar numericScale = body?.numericScale\nvar formatPattern = body?.formatPattern\nvar exampleValue = body?.exampleValue\nvar standardCodeSet = body?.standardCodeSet\nvar valueDomainId = body?.valueDomainId\nvar isNullable = body?.isNullable\nvar dataLevel = body?.dataLevel\nvar dataCategoryId = body?.dataCategoryId\nvar dataCategoryName = body?.dataCategoryName\nvar dataCategoryPath = body?.dataCategoryPath\nvar publishStatus = body?.publishStatus\nvar createdBy = body?.createdBy\nvar updatedBy = body?.updatedBy\nvar customRule = body?.customRule\nvar qualityRule = body?.qualityRule\n\nvar isUpdate = tid != null && tid != \'\'\n\nif (fieldType == null || fieldType == \'\') {\n    exit 400, \'fieldType is required\'\n}\n\nif (fieldLength == null || fieldLength::long(0) < 1) {\n    exit 400, \'fieldLength must be greater than zero\'\n}\n\nif (fieldType == \'decimal\' && numericPrecision != null && numericScale != null && numericScale::long(0) > numericPrecision::long(0)) {\n    exit 400, \'numericScale cannot exceed numericPrecision\'\n}\n\n// 当前时间\nvar now = new Date()\n\n// ========== 保存数据 da_metadata_t ==========\nif (isUpdate) {\n    // 更新数据\n    db.table(\'da_metadata_t\')\n        .primary(\'tid\')\n        .update({\n            tid: tid,\n            meta_name: metaName,\n            meta_code: metaCode,\n            standard_encode: standardEncode,\n            biz_def: bizDef,\n            data_type_id: dataTypeId,\n            field_type: fieldType,\n            field_length: fieldLength,\n            numeric_precision: numericPrecision,\n            numeric_scale: numericScale,\n            format_pattern: formatPattern,\n            example_value: exampleValue,\n            standard_code_set: standardCodeSet,\n            value_domain_id: valueDomainId,\n            is_nullable: isNullable,\n            data_level: dataLevel,\n            data_category_id: dataCategoryId,\n            data_category_name: dataCategoryName,\n            data_category_path: dataCategoryPath,\n            publish_status: publishStatus,\n            custom_rule: customRule,\n            quality_rule: qualityRule,\n            updated_by: updatedBy,\n            updated_time: now\n        })\n    log.info(\'更新数据元管理成功, tid: {}\', tid)\n} else {\n    // 新增数据，生成新的 tid\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'da_metadata_t\')\n        .primary(\'tid\')\n        .insert({\n            tid: tid,\n            meta_name: metaName,\n            meta_code: metaCode,\n            standard_encode: standardEncode,\n            biz_def: bizDef,\n            data_type_id: dataTypeId,\n            field_type: fieldType,\n            field_length: fieldLength,\n            numeric_precision: numericPrecision,\n            numeric_scale: numericScale,\n            format_pattern: formatPattern,\n            example_value: exampleValue,\n            standard_code_set: standardCodeSet,\n            value_domain_id: valueDomainId,\n            is_nullable: isNullable,\n            data_level: dataLevel,\n            data_category_id: dataCategoryId,\n            data_category_name: dataCategoryName,\n            data_category_path: dataCategoryPath,\n            publish_status: publishStatus || 0, // 默认为待发布\n            custom_rule: customRule,\n            quality_rule: qualityRule,\n            created_by: createdBy,\n            created_time: now,\n            updated_by: updatedBy,\n            updated_time: now,\n            is_del: 0\n        })\n    log.info(\'新增数据元管理成功, tid: {}\', tid)\n}\n\n// ========== 查询保存后的完整数据 ==========\n\nvar resultData = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\n\n// 返回当前业务分支的标准结果。\nreturn resultData\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/03.数据元保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('980b22c606a24830951e47836fc2e9ad',NULL,NULL,'{\n  "properties": {},\n  "id": "980b22c606a24830951e47836fc2e9ad",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "04.数据元发布状态修改",\n  "createTime": 1782955344968,\n  "updateTime": 1786716526626,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/updatePublishStatus",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据 tid 更新数据元的发布状态；涉及 da_metadata_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "user_no_login",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：04.数据元发布状态修改\n// 路由：POST /dwm/standard/element/updatePublishStatus\n// 业务说明：根据 tid 更新数据元的发布状态；涉及 da_metadata_t 等业务表。\nimport log\n\n/**\n * 修改数据元发布状态\n * POST /api/gov/data/meta/updatePublishStatus\n * \n * 根据 tid 更新数据元的发布状态\n * 请求参数：tid, publishStatus, updatedBy\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar publishStatus = body?.publishStatus\nvar updatedBy = body?.updatedBy\n\n// 参数校验\nif (tid == null || tid == \'\') {\n    throw \'tid不能为空\'\n}\n\nif (publishStatus == null) {\n    throw \'publishStatus不能为空\'\n}\n\n// 当前时间\nvar now = new Date()\n\n// ========== 更新发布状态 ==========\nvar updateCount = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)  // 只更新未删除的数据\n    .update({\n        publish_status: publishStatus,\n        updated_time: now\n    })\n\nif (updateCount == 0) {\n    // 如果没有更新到任何记录，可能是tid不存在或数据已被删除\n    log.error(\'更新发布状态失败，未找到对应数据或数据已被删除, tid: {}\', tid)\n    throw \'更新失败，未找到对应数据\'\n}\n\nlog.info(\'更新数据元发布状态成功, tid: {}, publishStatus: {}, 更新记录数: {}\', \n    tid, publishStatus, updateCount)\n\n// ========== 查询更新后的完整数据 ==========\nvar resultData = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (resultData == null) {\n    throw \'数据不存在或已被删除\'\n}\n\n// 返回当前业务分支的标准结果。\nreturn resultData\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/04.数据元发布状态修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5aad1c7bb48843a48a985ef41c0c2218',NULL,NULL,'{\n  "properties": {},\n  "id": "5aad1c7bb48843a48a985ef41c0c2218",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "05.数据元删除",\n  "createTime": 1782955344960,\n  "updateTime": 1786716526544,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/meatDeleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"de73de5f9daf42d9916f35fa2aee32e2\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据id删除数数据标准数据元；使用请求参数 tid；涉及 da_metadata_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.数据元删除\n// 路由：POST /dwm/standard/element/meatDeleteById\n// 业务说明：根据id删除数数据标准数据元；使用请求参数 tid；涉及 da_metadata_t 等业务表。\nimport log\n\n/**\n * 根据id删除数数据标准数据元\n * \n * 根据tid逻辑删除数据标准数据元\n */\n\n// 获取请求参数\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\n// 当前时间\nvar now = new Date()\n\n// ========== 逻辑删除数据 ==========\nvar result = db.table(\'da_metadata_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update({\n        is_del: 1,\n        updated_time: now\n    })\n\nif (result == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'规则不存在\'\n}\n\nlog.info(\'删除数据标准数据元成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/05.数据元删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_std_review_submit_01",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "06.提交数据元审核",\n  "createTime": 1789337365703,\n  "updateTime": 1789337949970,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/review/submit",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按请求目标与业务状态执行提交数据元审核，返回本次操作结果；使用请求参数 metaId、remark；涉及 da_metadata_t、asset_workbench_issue_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.提交数据元审核\n// 路由：POST /dwm/standard/element/review/submit\n// 业务说明：按请求目标与业务状态执行提交数据元审核，返回本次操作结果；使用请求参数 metaId、remark；涉及 da_metadata_t、asset_workbench_issue_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nimport cn.hutool.core.util.IdUtil\n\nvar tenantId = tenantRuntime.id()\nvar metaId = body?.metaId\nif(metaId == null || metaId == \'\') { exit 400,\'数据元ID不能为空\' }\nvar element = db.table(\'da_metadata_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',metaId).eq(\'is_del\',0).selectOne()\nif(element == null) { exit 404,\'数据元不存在\' }\nvar principal = approvalRuntime.principal()\nvar now = new Date()\nvar existing = db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'asset_type\',\'standard_element\').eq(\'asset_id\',metaId).eq(\'issue_type\',\'STANDARD_REVIEW\').eq(\'status\',\'PENDING\').eq(\'is_del\',0).selectOne()\nif(existing != null) { return existing }\nvar row = {tid:IdUtil.getSnowflakeNextIdStr(),tenant_id:tenantId,asset_type:\'standard_element\',asset_id:metaId,issue_type:\'STANDARD_REVIEW\',issue_code:element.metaCode,title:\'数据元审核：\'+element.metaName,detail:body?.remark,status:\'PENDING\',reporter_id:principal.userId,created_time:now,updated_time:now,is_del:0}\ndb.table(\'asset_workbench_issue_t\').primary(\'tid\').insert(row)\ndb.table(\'da_metadata_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',metaId).eq(\'is_del\',0).update({publish_status:0,updated_time:now})\nreturn row\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/06.提交数据元审核.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_std_review_decide_01",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "07.数据元审核决定",\n  "createTime": 1789337365759,\n  "updateTime": 1789337902940,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/review/decide",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "核验待审数据元工单与 APPROVE/REJECT 动作，记录审核意见，更新工单及数据元发布状态。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.数据元审核决定\n// 路由：POST /dwm/standard/element/review/decide\n// 业务说明：核验待审数据元工单与 APPROVE/REJECT 动作，记录审核意见，更新工单及数据元发布状态。\nimport tenantRuntime\nimport approvalRuntime\n\nvar tenantId = tenantRuntime.id()\nvar reviewId = body?.reviewId\nvar action = body?.action\nif(reviewId == null || reviewId == \'\' || (action != \'APPROVE\' && action != \'REJECT\')) { exit 400,\'审核参数不合法\' }\nvar review = db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',reviewId).eq(\'asset_type\',\'standard_element\').eq(\'issue_type\',\'STANDARD_REVIEW\').eq(\'status\',\'PENDING\').eq(\'is_del\',0).selectOne()\nif(review == null) { exit 404,\'待审核记录不存在\' }\nif(action == \'REJECT\' && (body?.opinion == null || body?.opinion.trim() == \'\')) { exit 400,\'退回时必须填写审核意见\' }\nvar principal = approvalRuntime.principal()\nvar now = new Date()\nvar status = action == \'APPROVE\' ? \'CLOSED\' : \'REJECTED\'\ndb.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',reviewId).update({status:status,assignee_org_id:principal.orgId,resolution:body?.opinion,resolved_time:now,updated_time:now})\nif(action == \'APPROVE\') { db.table(\'da_metadata_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',review.assetId).eq(\'is_del\',0).update({publish_status:1,updated_time:now}) }\nreturn true\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/07.数据元审核决定.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_std_review_page_01",\n  "script": null,\n  "groupId": "55c792d1ba0f4cb79b01a6d5c42dacea",\n  "name": "08.数据元审核列表",\n  "createTime": 1789337365631,\n  "updateTime": 1789337443530,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/review/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前租户、审核状态和分页参数读取待审数据元工单，返回列表与总数。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.数据元审核列表\n// 路由：POST /dwm/standard/element/review/page\n// 业务说明：按当前租户、审核状态和分页参数读取待审数据元工单，返回列表与总数。\nimport tenantRuntime\nvar tenantId=tenantRuntime.id();var page=body?.page::long(1);var size=body?.size::long(20);var status=body?.status;var rows=db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'asset_type\',\'standard_element\').eq(\'issue_type\',\'STANDARD_REVIEW\').eq(\'is_del\',0);if(status != null && status != \'\') {rows=rows.eq(\'status\',status)};return {list:rows.orderBy(\'updated_time\',\'desc\').page(size,(page-1)*size),total:rows.count(),page:page,size:size}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/08.数据元审核列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('55c792d1ba0f4cb79b01a6d5c42dacea',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "55c792d1ba0f4cb79b01a6d5c42dacea",\r\n  "name" : "01.数据元管理",\r\n  "type" : "api",\r\n  "parentId" : "019b772ee9b44705a27710f91bbd731a",\r\n  "path" : "/element",\r\n  "createTime" : 1781960051489,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.数据元管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cd79504e4b1448d3ab46ee6dc1034a8d',NULL,NULL,'{\n  "properties": {},\n  "id": "cd79504e4b1448d3ab46ee6dc1034a8d",\n  "script": null,\n  "groupId": "019b772ee9b44705a27710f91bbd731a",\n  "name": "01.标准目录树",\n  "createTime": 1782955344942,\n  "updateTime": 1784437771824,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "standard-class-list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "标准目录树：为数据元和标准代码页面提供统一分类树；使用请求参数 tid；涉及 sym_dict_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.标准目录树\n// 路由：POST /dwm/standard/standard-class-list\n// 业务说明：标准目录树：为数据元和标准代码页面提供统一分类树；使用请求参数 tid；涉及 sym_dict_t 等业务表。\n// 标准目录树：为数据元和标准代码页面提供统一分类树。\n// 只读 sym_dict_t 中 biz_type=standard_class、is_del=0 的记录，不修改业务数据。\n// 返回以 tid=0 为根节点的树；空目录安全返回空数组。\nvar tid = body?.tid ? body?.tid : query?.tid\nvar isDel = 0\n\n// ========== 1. 查询数据 ==========\nvar list = db.table(\'sym_dict_t\').excludes("createdBy","createdTime","updatedBy","updatedTime","isDel","tenantId")\n    .where().eq("biz_type","standard_class")\n    .eq(\'is_del\', isDel)\n\nif (tenantId != null && tenantId != \'\') {\n    list = list.eq(\'tenant_id\', tenantId)\n}\n\n\nvar rows = list.orderBy(\'sort_no\').select()\n\nif (rows == null) {\n    rows = []\n    // 返回当前业务分支的标准结果。\n    return rows\n}\n\n// 根据parentId 过滤当前节点\nvar toTree = (list,parentId)=>{\n    // 返回当前业务分支的标准结果。\n    return list.filter(it => it.parentId == parentId)\n    .each(it=>{\n        it.children = toTree(list,it.tid)    // 过滤后循环这些节点递归添加children属性\n    }) \n}\n\n//添加根节点\nvar root =  db.table(\'sym_dict_t\').excludes("createdBy","createdTime","updatedBy","updatedTime","isDel","tenantId")\n    .where().eq("tid","0")\n    .eq(\'is_del\', isDel).selectOne()\n\nif(root != null){\n    rows.addFirst(root)\n}\n\n\nvar root;\n//字段转换\nfor( item in rows){\n    item.label = item.dictName\n    item.value = item.dictCode\n    item.remove("dictName")\n    item.remove("dictCode")\n    //parentId\n    if(item.tid == \'0\'){\n        root = item;\n    }\n}\nif(rows.size() == 0){\n    // 返回当前业务分支的标准结果。\n    return rows\n}\n// 根节点为 0\nvar treeDate = toTree(rows, \'0\')\nroot.children = treeDate\n\n// 返回当前业务分支的标准结果。\nreturn root\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/01.标准目录树.ms');
