,\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "total",\n            "value": "8",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "list",\n            "value": "",\n            "description": "",\n            "required": false,\n            "dataType": "Array",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": [\n              {\n                "name": "",\n                "value": "",\n                "description": "",\n                "required": false,\n                "dataType": "Object",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": [\n                  {\n                    "name": "tid",\n                    "value": "3db170534c774fa5a8a264ffacfb6cf0",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dictName",\n                    "value": "性别代码",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dictCode",\n                    "value": "GB/T 2261.1",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dataCategoryId",\n                    "value": "cat_001",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dataCategoryName",\n                    "value": "基础数据/人口信息",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dataCategoryPath",\n                    "value": "/root/cat_001",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "desc",\n                    "value": "null",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Object",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "dictItemValue",\n                    "value": "[{\\"code\\":\\"0\\",\\"name\\":\\"未知的性别\\"},{\\"code\\":\\"1\\",\\"name\\":\\"男性\\"},{\\"code\\":\\"2\\",\\"name\\":\\"女性\\"},{\\"code\\":\\"9\\",\\"name\\":\\"未说明的性别\\"}]",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "createdBy",\n                    "value": "admin",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "createdTime",\n                    "value": "2026-03-10 15:34:08",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "updatedBy",\n                    "value": "admin",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "updatedTime",\n                    "value": "2026-03-10 15:34:08",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "isDel",\n                    "value": "0",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Integer",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：02.标准代码分页查询\n// 路由：POST /dwm/standard/code/page\n// 业务说明：支持按字典名称、字典编码、数据分类ID模糊查询；使用请求参数 pageNum、pageSize、dictName、categoryPath；涉及 da_metadata_code_t 等业务表。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\n\n/**\n * 分页查询标准代码表\n * POST /api/gov/standard/code/page\n * \n * 支持分页查询标准代码表列表\n * 支持按字典名称、字典编码、数据分类ID模糊查询\n */\n\n// 获取分页参数\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0 ? 0 : (pageNum - 1) * pageSize\n\n// 获取查询条件\nvar dictName = body?.dictName\nvar categoryPath = body?.categoryPath\n\n// 构建查询条件\nvar query = db.table(\'da_metadata_code_t\')\n    .where()\n    .eq(\'is_del\', 0)\n    .eq(\'code_value\', \'__HEADER__\')\n\nif (dictName != null && dictName != \'\') {\n    query = query.like(\'dict_name\', \'%\' + dictName + \'%\')\n}\n\nif (categoryPath != null) {\n    query = query.like(\'data_category_path\', categoryPath + "%")\n}\n\n// ========== 查询总数 ==========\nvar total = query.count()\n\n// ========== 查询列表 ==========\nvar list = query\n    .orderBy(\'created_time\', \'desc\')\n    .page(pageSize, offsetLimit)\n\nlog.info(\'分页查询标准代码表成功, pageNum: {}, pageSize: {}, total: {}\', pageNum, pageSize, total)\n\n// ========== 返回结果 ==========\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/02.标准代码管理/02.标准代码分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('684305fb587f4e60904f927b36331e34',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "684305fb587f4e60904f927b36331e34",\r\n  "script" : null,\r\n  "groupId" : "27defcc7cb47425eb18cd62f8bf153b0",\r\n  "name" : "03.标准代码详情",\r\n  "createTime" : 1782955345033,\r\n  "updateTime" : 1791111886673,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "queryById",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"tid\\": \\"6af9d796b7f64f178824b6b170b2a468\\",\\n    \\"dictItemValue\\": \\"122\\"\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "标准代码详情：兼容主键与代码集标识查询；只读 da_metadata_code_t；使用请求参数 tid、id、dictCode、codeSet、codeValue。",\r\n  "requestBodyDefinition" : {\r\n    "name" : "",\r\n    "value" : "",\r\n    "description" : "",\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : "",\r\n    "error" : "",\r\n    "expression" : "",\r\n    "children" : [ ]\r\n  },\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：03.标准代码详情\n// 路由：POST /dwm/standard/code/queryById\n// 业务说明：标准代码详情：兼容主键与代码集标识查询；lookups 可一次批量查询最多 50 个标识；只读当前租户 da_metadata_code_t。\n// 标准代码详情：兼容主键与代码集标识查询；只读 da_metadata_code_t。\nimport log\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nif (body?.lookups != null) {\n    var submitted = body.lookups\n    if (!(submitted instanceof List) || submitted.size() == 0 || submitted.size() > 50) {\n        exit 400, \'标准代码标识必须是 1 至 50 项的数组\'\n    }\n    var lookups = []\n    for (raw in submitted) {\n        var lookup = (\'\' + raw).trim()\n        if (lookup == \'\' || lookup.length() > 255) { exit 400, \'标准代码标识不合法\' }\n        if (!lookups.contains(lookup)) { lookups.add(lookup) }\n    }\n    var rows = db.select("""\n        select * from da_metadata_code_t\n         where tenant_id=#{tenantId} and is_del=0 and (\n             tid in <foreach collection="lookups" item="id" open="(" close=")" separator=",">#{id}</foreach>\n             or (code_value=\'__HEADER__\' and (\n                 dict_code in <foreach collection="lookups" item="id" open="(" close=")" separator=",">#{id}</foreach>\n                 or code_set in <foreach collection="lookups" item="id" open="(" close=")" separator=",">#{id}</foreach>\n             ))\n         )\n    """)\n    var byTid = {}\n    var byDictCode = {}\n    var byCodeSet = {}\n    for (row in rows) {\n        var tid = \'\' + row.tid\n        if (lookups.contains(tid) && byTid[tid] == null) { byTid[tid] = row }\n        if (row.codeValue == \'__HEADER__\') {\n            var dictCode = \'\' + row.dictCode\n            var codeSet = \'\' + row.codeSet\n            if (lookups.contains(dictCode) && byDictCode[dictCode] == null) { byDictCode[dictCode] = row }\n            if (lookups.contains(codeSet) && byCodeSet[codeSet] == null) { byCodeSet[codeSet] = row }\n        }\n    }\n    var result = {}\n    for (lookup in lookups) {\n        result[lookup] = byTid[lookup] || byDictCode[lookup] || byCodeSet[lookup] ||\n            { found: false, tid: lookup, message: \'标准代码不存在或已删除\', dict_item_value: \'[]\' }\n    }\n    return result\n}\n\nvar lookup = body?.tid || body?.id || body?.dictCode || body?.codeSet || body?.codeValue\nif (lookup == null || lookup == \'\') {\n    return { found: false, message: \'标准代码标识不能为空\', dict_item_value: \'[]\' }\n}\n\nvar data = db.table(\'da_metadata_code_t\')\n    .where()\n    .eq(\'tid\', lookup)\n    .eq(\'tenant_id\', tenantId)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (data == null) {\n    data = db.table(\'da_metadata_code_t\')\n        .where()\n        .eq(\'dict_code\', lookup)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'code_value\', \'__HEADER__\')\n        .eq(\'is_del\', 0)\n        .selectOne()\n}\n\nif (data == null) {\n    data = db.table(\'da_metadata_code_t\')\n        .where()\n        .eq(\'code_set\', lookup)\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'code_value\', \'__HEADER__\')\n        .eq(\'is_del\', 0)\n        .selectOne()\n}\n\nif (data == null) {\n    log.warn(\'未找到标准代码记录, lookup: {}\', lookup)\n    return { found: false, tid: lookup, message: \'标准代码不存在或已删除\', dict_item_value: \'[]\' }\n}\n\nreturn data\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/02.标准代码管理/03.标准代码详情.ms');
