    "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "dataCategoryId",\n        "value": "1891200000000000101",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "describe",\n        "value": "d",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "dataCategoryName",\n        "value": "基础通用标准",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "dataCategoryPath",\n        "value": "0,1891200000000000001,1891200000000000101",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "dictItemValue",\n        "value": "55",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  },\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "tid",\n            "value": "09673d1ff4b4424bb131e823ca2c4eef",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dictName",\n            "value": "性别代码",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dictCode",\n            "value": "R-INT-002",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dataCategoryId",\n            "value": "1891200000000000101",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dataCategoryName",\n            "value": "基础通用标准",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dataCategoryPath",\n            "value": "0,1891200000000000001,1891200000000000101",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "description",\n            "value": "d",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dictItemValue",\n            "value": "null",\n            "description": "",\n            "required": false,\n            "dataType": "Object",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "createdBy",\n            "value": "null",\n            "description": "",\n            "required": false,\n            "dataType": "Object",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "createdTime",\n            "value": "2026-03-11 14:50:25",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "updatedBy",\n            "value": "null",\n            "description": "",\n            "required": false,\n            "dataType": "Object",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "updatedTime",\n            "value": "2026-03-11 14:50:25",\n            "description": "",\n            "required": false,\n            "dataType": "String",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "isDel",\n            "value": "0",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：04.标准代码保存修改\n// 路由：POST /dwm/standard/code/saveOrUpdate\n// 业务说明：校验请求资料后执行标准代码保存修改，返回保存或配置结果；使用请求参数 tid、dictName、dictCode、dataCategoryId、dataCategoryName、dataCategoryPath、description、dictItemValue；涉及 da_metadata_code_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport jsons\n\nimport com.linewell.dataelement.utils.RedisUtils as redis\nimport "@/common/configData" as configData\n\n/**\n * 保存或更新标准代码表\n * POST /api/gov/standard/code/saveOrUpdate\n *\n * 如果 body.tid 有值则更新，否则新增\n * 数据保存到 da_metadata_code_t 表\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar dictName = body?.dictName\nvar dictCode = body?.dictCode\nvar dataCategoryId = body?.dataCategoryId\nvar dataCategoryName = body?.dataCategoryName\nvar dataCategoryPath = body?.dataCategoryPath\n\n\n\nvar describe = body?.description\nvar dictItemValue = body?.dictItemValue\nvar codeSet = body?.codeSet || dictCode\nvar codeValue = body?.codeValue || \'__HEADER__\'\nvar codeName = body?.codeName || dictName\nvar parentCode = body?.parentCode\nvar sortNo = body?.sortNo || 0\nvar status = body?.status == null ? 1 : body?.status\nvar createdBy = body?.createdBy\nvar updatedBy = body?.updatedBy\n\nvar isUpdate = tid != null && tid != \'\'\n\n// 当前时间\nvar now = new Date()\n\n// ========== 保存数据 da_metadata_code_t ==========\nif (isUpdate) {\n    // 更新数据\n    db.table(\'da_metadata_code_t\')\n        .primary(\'tid\')\n        .update({\n            tid: tid,\n            dict_name: dictName,\n            dict_code: dictCode,\n            data_category_id: dataCategoryId,\n            data_category_name: dataCategoryName,\n            data_category_path: dataCategoryPath,\n            description: describe,\n            dict_item_value: dictItemValue,\n            code_set: codeSet,\n            code_value: codeValue,\n            code_name: codeName,\n            parent_code: parentCode,\n            sort_no: sortNo,\n            status: status,\n            updated_by: updatedBy,\n            updated_time: now\n        })\n    log.info(\'更新标准代码表成功, tid: {}\', tid)\n} else {\n    // 新增数据，生成新的 tid\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'da_metadata_code_t\')\n        .primary(\'tid\')\n        .insert({\n            tid: tid,\n            dict_name: dictName,\n            dict_code: dictCode,\n            data_category_id: dataCategoryId,\n            data_category_name: dataCategoryName,\n            data_category_path: dataCategoryPath,\n            description: describe,\n            dict_item_value: dictItemValue,\n            code_set: codeSet,\n            code_value: codeValue,\n            code_name: codeName,\n            parent_code: parentCode,\n            sort_no: sortNo,\n            status: status,\n            created_by: createdBy,\n            created_time: now,\n            updated_by: updatedBy,\n            updated_time: now,\n            is_del: 0\n        })\n    log.info(\'新增标准代码表成功, tid: {}\', tid)\n}\n\n//更新数据到 redis\nvar nifi_dict_prefix = configData().nifi_dict_prefix\nvar jsonList = jsons.toJSONArray(dictItemValue)\nif(jsonList != null){\n    if(jsonList == []){\n        redis.set(nifi_dict_prefix + tid,[])\n    }else {\n        var list = []\n        for(item in jsonList){\n            list.add({\n                 `${item.code}` :  `${item.name}`         \n            })\n        }\n        redis.set(nifi_dict_prefix + tid, list)\n    }\n}\n\n\n// ========== 查询保存后的完整数据 ==========\n\nvar resultData = db.table(\'da_metadata_code_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\n// ========== 返回结果 ==========\nreturn resultData\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/02.标准代码管理/04.标准代码保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('af0138a85b1d4b6b9b7b7252c541aaa8',NULL,NULL,'{\n  "properties": {},\n  "id": "af0138a85b1d4b6b9b7b7252c541aaa8",\n  "script": null,\n  "groupId": "27defcc7cb47425eb18cd62f8bf153b0",\n  "name": "05.标准代码删除",\n  "createTime": 1782955345018,\n  "updateTime": 1786716527064,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "deleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据 tid 逻辑删除标准代码表，将 is_del 置为 1；涉及 da_metadata_code_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.标准代码删除\n// 路由：POST /dwm/standard/code/deleteById\n// 业务说明：根据 tid 逻辑删除标准代码表，将 is_del 置为 1；涉及 da_metadata_code_t 等业务表。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\n\n/**\n * 删除标准代码表（逻辑删除）\n * POST /api/gov/standard/code/delete\n * \n * 根据 tid 逻辑删除标准代码表，将 is_del 置为 1\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar updatedBy = body?.updatedBy\n\n// 参数校验\nif (tid == null || tid == \'\') {\n    throw \'tid不能为空\'\n}\n\n// 检查数据是否存在\nvar existingData = db.table(\'da_metadata_code_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (existingData == null) {\n    log.warn(\'尝试删除不存在的标准代码表记录, tid: {}\', tid)\n    throw \'数据不存在或已被删除\'\n}\n\n// 当前时间\nvar now = new Date()\n\n// ========== 逻辑删除 ==========\nvar deleteCount = db.table(\'da_metadata_code_t\')\n    .where()\n    .eq(\'tid\', tid)\n    .update({\n        is_del: 1,\n        updated_by: updatedBy,\n        updated_time: now\n    })\n\nif (deleteCount == 0) {\n    log.error(\'删除标准代码表失败, tid: {}\', tid)\n    throw \'删除失败\'\n}\n\nlog.info(\'删除标准代码表成功, tid: {}, 删除记录数: {}\', tid, deleteCount)\n\n// ========== 返回结果 ==========\nreturn {\n    tid: tid\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/01.数据标准/02.标准代码管理/05.标准代码删除.ms');
