INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_standard_landing_list_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_standard_landing_list_01",\n  "groupId": "dwm_standard_landing_group_01",\n  "name": "01.字段标准引用清单",\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "requestBody": "{}",\n  "description": "只读当前租户已采集字段及 da_metadata_t 标准引用，统计有效已发布标准覆盖率；涉及 db_table_t、db_datasource_t、db_table_column_t、da_metadata_t 等业务表。",\n  "script": null\n}\n================================\n// 接口：01.字段标准引用清单\n// 路由：POST /dwm/standard/landing/list\n// 业务说明：只读当前租户已采集字段及 da_metadata_t 标准引用，统计有效已发布标准覆盖率；涉及 db_table_t、db_datasource_t、db_table_column_t、da_metadata_t 等业务表。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n// Read-only. No physical datasource probe, registration change, or catalog creation.\nvar tables = db.select("""\n select t.tid,t.table_name,t.table_name_cn,t.table_comment,d.db_name\n from db_table_t t join db_datasource_t d on d.tid=t.datasource_id\n   and d.tenant_id=#{tenantId} and d.is_del=0\n where t.tenant_id=#{tenantId} and t.is_del=0 order by t.table_name,t.tid\n""")\nvar columns = db.select("""\n select c.tid,c.table_id,c.column_name,c.column_comment,c.data_type,c.length,\n        c.data_standard_id,m.meta_name,m.meta_code,m.publish_status,m.is_del as standard_deleted\n from db_table_column_t c\n join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n left join da_metadata_t m on m.tid=c.data_standard_id and m.tenant_id=#{tenantId}\n where c.tenant_id=#{tenantId} and c.is_del=0 order by t.table_name,c.ordinal_position,c.tid\n""")\nvar entities = []\nvar byId = {}\nvar items = []\nvar mapped = 0\nvar bound = 0\nfor (table in tables) {\n var entity = { id:table.tid, name:table.tableName, displayName:table.tableNameCn || table.tableComment || table.tableName, sourceName:table.dbName, fields:[] }\n entities.add(entity)\n byId[table.tid] = entity\n}\nfor (column in columns) {\n var standardId = column.dataStandardId == null ? null : (column.dataStandardId + \'\').trim()\n if (standardId == \'\') { standardId = null }\n var valid = standardId != null && column.metaName != null && column.publishStatus == 1 && column.standardDeleted == 0\n if (standardId != null) { bound = bound + 1 }\n if (valid) { mapped = mapped + 1 }\n var entity = byId[column.tableId]\n if (entity != null) {\n  entity.fields.add({id:column.tid,name:column.columnName,displayName:column.columnComment || column.columnName,type:column.dataType,length:column.length,standardId:standardId})\n  items.add({id:column.tid,entity_id:column.tableId,field_id:column.tid,mapping_mode:\'STANDARD\',target_id:standardId,status:standardId == null ? \'UNBOUND\' : (valid ? \'CONFIRMED\' : \'STALE\')})\n }\n}\nreturn {entities:entities,items:items,coverage:{totalFields:items.size(),mappedFields:mapped,boundFields:bound,coverage:items.size() == 0 ? 0 : mapped * 100.0 / items.size()}}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/01.数据标准/03.标准落地/01.字段标准引用清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_standard_landing_save_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_standard_landing_save_01",\n  "script": null,\n  "groupId": "dwm_standard_landing_group_01",\n  "name": "02.保存字段标准引用",\n  "createTime": null,\n  "updateTime": 1790595097815,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "只更新 db_table_column_t.data_standard_id；校验当前租户、已发布标准及并发修改，支持 dryRun；使用请求参数 tableId、columnId、standardId、expectedStandardId、dryRun。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.保存字段标准引用\n// 路由：POST /dwm/standard/landing/save\n// 业务说明：只更新 db_table_column_t.data_standard_id；校验当前租户、已发布标准及并发修改，支持 dryRun；使用请求参数 tableId、columnId、standardId、expectedStandardId、dryRun。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nvar tableId = body?.tableId\nvar columnId = body?.columnId\nvar standardId = body?.standardId\nvar expectedStandardId = body?.expectedStandardId == null ? \'\' : (body.expectedStandardId + \'\').trim()\nif (tableId == null || tableId == \'\' || columnId == null || columnId == \'\') { exit 400, \'请选择真实的数据表及字段\' }\nif (standardId != null) { standardId = (standardId + \'\').trim(); if (standardId == \'\') { standardId = null } }\nvar column = db.selectOne("""\n select c.tid,c.data_standard_id,c.column_comment\n from db_table_column_t c\n join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n where c.tenant_id=#{tenantId} and c.tid=#{columnId} and c.table_id=#{tableId} and c.is_del=0\n""")\nif (column == null) { exit 404, \'字段不存在或不属于当前租户\' }\nvar currentId = column.dataStandardId == null ? \'\' : (column.dataStandardId + \'\').trim()\nif (currentId != expectedStandardId) { exit 409, \'字段标准引用已被其他操作修改，请刷新后重试\' }\n// Dameng treats the empty string as NULL. Use a real null expected value and\n// explicit empty/null predicates so a first binding still has an atomic guard.\nvar expectedDbId = expectedStandardId == \'\' ? null : expectedStandardId\nif (standardId != null) {\n var standard = db.table(\'da_metadata_t\').where().eq(\'tid\',standardId).eq(\'tenant_id\',tenantId).eq(\'is_del\',0).selectOne()\n if (standard == null) { exit 404, \'标准不存在或不属于当前租户\' }\n if (standard.publishStatus != 1) { exit 409, \'只允许绑定已审批发布的数据元\' }\n}\nif (body?.dryRun == true) { return {columnId:columnId,standardId:standardId,dryRun:true,valid:true} }\n// Deliberately no table registration flags, field-governance bulk save, ES rebuild, or catalog projection.\nvar affected = db.update("""\n update db_table_column_t set data_standard_id=#{standardId},updated_time=current_timestamp(6)\n where tenant_id=#{tenantId} and tid=#{columnId} and table_id=#{tableId} and is_del=0\n   and ((#{expectedDbId} is null and\n         (data_standard_id is null or trim(data_standard_id) is null or trim(data_standard_id)=\'\'))\n        or trim(data_standard_id)=#{expectedDbId})\n""")\nif (affected == 0) { exit 409, \'字段标准引用保存冲突，请刷新后重试\' }\nreturn {columnId:columnId,standardId:standardId,saved:true}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/01.数据标准/03.标准落地/02.保存字段标准引用.ms');
