INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000001',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000001",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "01.质量概览",\n  "path": "/summary",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/summary；只读；汇总当前租户质检任务、近30日实例、质量得分与维度指标；数据质量首页主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：01.质量概览\n// 业务说明：POST /dwm/quality/summary；只读；汇总当前租户质检任务、近30日实例、质量得分与维度指标；数据质量首页主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 只统计当前会话所在租户的质量任务、执行结果和问题。\nreturn dataQuality.summary()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/01.质量概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000002',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000002",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "02.任务分页",\n  "createTime": 1785628800000,\n  "updateTime": 1790498525171,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/task/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"page\\":1,\\"size\\":20,\\"keyword\\":\\"人口\\",\\"status\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "POST /dwm/quality/task/page；只读；分页查询当前租户质检任务及最近执行结果；任务列表主接口。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.任务分页\n// 业务说明：POST /dwm/quality/task/page；只读；分页查询当前租户质检任务及最近执行结果；任务列表主接口。\n\nimport tenantRuntime\nimport dataQuality\nimport cn.hutool.core.util.NumberUtil\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 筛选任务状态、类型和关键词；非法类型应在查询前被拒绝。\nvar status = body?.status == null ? \'\' : (\'\' + body.status).trim()\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nvar kind = body?.kind == null || (\'\' + body.kind).trim() == \'\' ? null : (\'\' + body.kind).trim()\nif (kind != null && kind != \'PROFILE\' && kind != \'QUALITY\') { exit 400, \'任务类型无效\' }\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\nreturn dataQuality.taskPage(status, keyword, page, size, kind)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/02.任务分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000003',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000003",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "03.任务详情",\n  "path": "/task/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"taskId\\":\\"dq_police_population_demo\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/task/detail；只读；查询质检任务及其版本化规则配置；任务编辑接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：03.任务详情\n// 业务说明：POST /dwm/quality/task/detail；只读；查询质检任务及其版本化规则配置；任务编辑接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 按当前租户读取任务及规则，禁止跨租户读取。\nvar taskId = body?.taskId == null ? \'\' : (\'\' + body.taskId).trim()\nif (taskId == \'\') { exit 400, \'任务ID不能为空\' }\nreturn dataQuality.taskDetail(taskId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/03.任务详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000004',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000004",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "04.保存任务",\n  "path": "/task/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"taskName\\":\\"常住人口基础质量检查\\",\\"taskCode\\":\\"DQ_POLICE_POPULATION\\",\\"datasourceId\\":\\"dq_demo_source_20260802\\",\\"tableId\\":\\"dq_demo_population_meta\\",\\"shardKey\\":\\"person_id\\",\\"shardCount\\":8,\\"sampleLimit\\":200,\\"triggerMode\\":\\"MANUAL\\",\\"rules\\":[{\\"ruleName\\":\\"姓名非空\\",\\"ruleType\\":\\"NOT_EMPTY\\",\\"columnName\\":\\"person_name\\",\\"severity\\":\\"HIGH\\",\\"weight\\":20,\\"parameters\\":{}}]}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/task/save；写入 dq_quality_task_t 与 dq_quality_task_rule_t；保存真实可执行任务，任意SQL不在允许模型内；任务保存主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：04.保存任务\n// 业务说明：POST /dwm/quality/task/save；写入 dq_quality_task_t 与 dq_quality_task_rule_t；保存真实可执行任务，任意SQL不在允许模型内；任务保存主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 先检查必需资料；规则和任务在 Java 仓储的一次事务中保存。\nif (body == null) { exit 400, \'请填写质检任务\' }\nif (body?.taskName == null || (\'\' + body.taskName).trim() == \'\') { exit 400, \'任务名称不能为空\' }\nvar taskId = dataQuality.persistTask(body)\n// 返回仓储生成的任务标识及最新规则配置。\nreturn dataQuality.taskDetail(taskId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/04.保存任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000005',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000005",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "05.任务预检",\n  "path": "/task/precheck",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"taskId\\":\\"dq_police_population_demo\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/task/precheck；读写；验证注册数据源连接、物理表、字段、分片键和规则参数并保存根因；任务启用前主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：05.任务预检\n// 业务说明：POST /dwm/quality/task/precheck；读写；验证注册数据源连接、物理表、字段、分片键和规则参数并保存根因；任务启用前主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 预检连接和字段能力，再回写预检结果供任务启用时校验。\nvar taskId = body?.taskId == null ? \'\' : (\'\' + body.taskId).trim()\nif (taskId == \'\') { exit 400, \'任务ID不能为空\' }\nvar result = dataQuality.inspectTask(taskId)\ndataQuality.persistPrecheck(taskId, result)\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/05.任务预检.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dd4214943e5341c482a59821a64245eb",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "06.质量规则保存修改",\n  "createTime": 1782955345061,\n  "updateTime": 1786191945333,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"a3b8fb4786b64c3b98cb4a3d6978fab5\\",\\n    \\"ruleName\\": \\"非空校验2233\\",\\n    \\"ruleCode\\": \\"not_null_check\\",\\n    \\"checkDimension\\": \\"0\\",\\n    \\"ruleLevel\\": \\"0\\",\\n    \\"ruleDescription\\": \\"核心字段不含 NULL值\\",\\n    \\"scopeOfApplication\\": \\"所有必填字段\\",\\n    \\"configParameters\\": \\"column: 校验字段\\",\\n    \\"checkLogic\\": \\"SELECT count(1) FROM ${table} WHERE ${column} IS NULL\\",\\n    \\"createdBy\\": \\"admin\\",\\n    \\"updatedBy\\": \\"admin\\",\\n    \\"tenantId\\": \\"T-9527\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行质量规则保存修改，返回保存或配置结果；使用请求参数 tid、ruleName、ruleCode、checkDimension、ruleLevel、ruleDescription、scopeOfApplication、configParameters；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.质量规则保存修改\n// 路由：POST /dwm/quality/saveOrUpdate\n// 业务说明：校验请求资料后执行质量规则保存修改，返回保存或配置结果；使用请求参数 tid、ruleName、ruleCode、checkDimension、ruleLevel、ruleDescription、scopeOfApplication、configParameters；涉及 data_gov_quality_rule 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport tenantRuntime\n/**\n * 保存或更新数据质量校验规则\n * POST /api/gov/quality/rule/saveOrUpdate\n * \n * 如果 body.tid 有值则更新，否则新增\n * 数据保存到 data_gov_quality_rule 表\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar ruleName = body?.ruleName\nvar ruleCode = body?.ruleCode\nvar checkDimension = body?.checkDimension\nvar ruleLevel = body?.ruleLevel\nvar ruleDescription = body?.ruleDescription\nvar scopeOfApplication = body?.scopeOfApplication\nvar configParameters = body?.configParameters\nvar checkLogic = body?.checkLogic\nvar createdBy = body?.createdBy\nvar updatedBy = body?.updatedBy\nvar tenantId = tenantRuntime.id()\n\nvar isUpdate = tid != null && tid != \'\'\n\n// 当前时间\nvar now = new Date()\n\n// ========== 保存数据 data_gov_quality_rule ==========\nif (isUpdate) {\n    // 更新数据\n    db.table(\'data_gov_quality_rule\')\n        .primary(\'tid\')\n        .update({\n            tid: tid,\n            rule_name: ruleName,\n            rule_code: ruleCode,\n            check_dimension: checkDimension,\n            rule_level: ruleLevel,\n            rule_description: ruleDescription,\n            scope_of_application: scopeOfApplication,\n            config_parameters: configParameters,\n            check_logic: checkLogic,\n            updated_by: updatedBy,\n            updated_time: now,\n            tenant_id: tenantId\n        })\n    log.info(\'更新数据质量规则成功, tid: {}\', tid)\n} else {\n    // 新增数据，生成新的 tid\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_gov_quality_rule\')\n        .primary(\'tid\')\n        .insert({\n            tid: tid,\n            rule_name: ruleName,\n            rule_code: ruleCode,\n            check_dimension: checkDimension,\n            rule_level: ruleLevel,\n            rule_description: ruleDescription,\n            scope_of_application: scopeOfApplication,\n            config_parameters: configParameters,\n            check_logic: checkLogic,\n            created_by: createdBy,\n            created_time: now,\n            updated_by: updatedBy,\n            updated_time: now,\n            is_del: 0,\n            tenant_id: tenantId\n        })\n    log.info(\'新增数据质量规则成功, tid: {}\', tid)\n}\n\n// ========== 查询保存后的完整数据 ==========\n//     .where()\n//     .eq(\'tid\', tid)\n//     .eq(\'is_del\', 0)\n//     .selectOne()\n\n// 构建返回数据\n\n\n// ========== 返回结果 ==========\n//     code: 200,\n//     success: true,\n//     message: isUpdate ? \'更新成功\' : \'新增成功\',\n//     data: data\n// }\n\nreturn tid\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/06.质量规则保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000006',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000006",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "07.任务启停",\n  "path": "/task/enable",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"taskId\\":\\"dq_police_population_demo\\",\\"enabled\\":true}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/task/enable；写入 dq_quality_task_t；仅通过预检的任务可以启用；任务状态主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：07.任务启停\n// 业务说明：POST /dwm/quality/task/enable；写入 dq_quality_task_t；仅通过预检的任务可以启用；任务状态主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 启用前仓储仍会强制核验预检通过和任务归属。\nvar taskId = body?.taskId == null ? \'\' : (\'\' + body.taskId).trim()\nif (taskId == \'\') { exit 400, \'任务ID不能为空\' }\nvar enabled = body?.enabled == true || body?.enabled == 1 || body?.enabled == \'1\' || (\'\' + body?.enabled).toLowerCase() == \'true\'\nreturn dataQuality.setEnabled(taskId, enabled)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/07.任务启停.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000007',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000007",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "08.手动发起",\n  "path": "/run/manual",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"taskId\\":\\"dq_police_population_demo\\",\\"requestId\\":\\"page-generated-id\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/run/manual；写入 dq_quality_run_t；只投递幂等实例，由 Worker 异步扫描源库；手工执行主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：08.手动发起\n// 业务说明：POST /dwm/quality/run/manual；写入 dq_quality_run_t；只投递幂等实例，由 Worker 异步扫描源库；手工执行主接口。\n\nimport tenantRuntime\nimport dataQuality\nimport java.util.UUID\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 只创建幂等实例，耗时的分片扫描由 Worker 执行。\nvar taskId = body?.taskId == null ? \'\' : (\'\' + body.taskId).trim()\nif (taskId == \'\') { exit 400, \'任务ID不能为空\' }\nvar requestId = body?.requestId == null || (\'\' + body.requestId).trim() == \'\' ? UUID.randomUUID().toString() : \'\' + body.requestId\nvar runId = dataQuality.createRun(taskId, requestId)\nreturn dataQuality.runDetail(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/08.手动发起.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000008',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000008",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "09.实例分页",\n  "path": "/run/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"page\\":1,\\"size\\":20,\\"status\\":\\"\\",\\"keyword\\":\\"人口\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/run/page；只读；分页查询当前租户质检执行实例；执行记录主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：09.实例分页\n// 业务说明：POST /dwm/quality/run/page；只读；分页查询当前租户质检执行实例；执行记录主接口。\n\nimport tenantRuntime\nimport dataQuality\nimport cn.hutool.core.util.NumberUtil\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 读取当前租户的质检历史，并允许按任务类型和状态筛选。\nvar status = body?.status == null ? \'\' : (\'\' + body.status).trim()\nvar keyword = body?.keyword == null ? \'\' : (\'\' + body.keyword).trim()\nvar kind = body?.kind == null || (\'\' + body.kind).trim() == \'\' ? null : (\'\' + body.kind).trim()\nif (kind != null && kind != \'PROFILE\' && kind != \'QUALITY\') { exit 400, \'任务类型无效\' }\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\nreturn dataQuality.runPage(status, keyword, page, size, kind)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/09.实例分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000009',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000009",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "10.实例详情",\n  "path": "/run/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"质检实例ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/run/detail；只读；查询实例、分片进度和规则指标；实例详情主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：10.实例详情\n// 业务说明：POST /dwm/quality/run/detail；只读；查询实例、分片进度和规则指标；实例详情主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 返回实例指标和分片进度；仓储限定当前租户。\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'实例ID不能为空\' }\nreturn dataQuality.runDetail(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/10.实例详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000010',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000010",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "11.问题样例分页",\n  "path": "/run/issues",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"质检实例ID\\",\\"page\\":1,\\"size\\":20,\\"status\\":\\"OPEN\\",\\"severity\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/run/issues；只读；分页查询有限问题样例，聚合异常数以指标表为准；问题查看主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：11.问题样例分页\n// 业务说明：POST /dwm/quality/run/issues；只读；分页查询有限问题样例，聚合异常数以指标表为准；问题查看主接口。\n\nimport tenantRuntime\nimport dataQuality\nimport cn.hutool.core.util.NumberUtil\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 问题样例受实例归属约束，且仓储只返回数量受限的样例。\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'实例ID不能为空\' }\nvar status = body?.status == null ? \'\' : (\'\' + body.status).trim()\nvar severity = body?.severity == null ? \'\' : (\'\' + body.severity).trim()\nvar page = body?.page == null || !(\'\' + body.page).matches(\'^[0-9]+$\') ? 1 : NumberUtil.parseInt(\'\' + body.page)\nvar size = body?.size == null || !(\'\' + body.size).matches(\'^[0-9]+$\') ? 20 : NumberUtil.parseInt(\'\' + body.size)\nreturn dataQuality.issuePage(runId, status, severity, page, size)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/11.问题样例分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000011',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000011",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "12.取消实例",\n  "path": "/run/cancel",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"runId\\":\\"质检实例ID\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/run/cancel；写入 dq_quality_run_t；请求 Worker 停止未执行分片；实例取消主接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：12.取消实例\n// 业务说明：POST /dwm/quality/run/cancel；写入 dq_quality_run_t；请求 Worker 停止未执行分片；实例取消主接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 仅标记取消；Worker 在安全检查点结束未完成分片。\nvar runId = body?.runId == null ? \'\' : (\'\' + body.runId).trim()\nif (runId == \'\') { exit 400, \'实例ID不能为空\' }\nreturn dataQuality.cancel(runId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/12.取消实例.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000012',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000012",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "13.数据源选项",\n  "path": "/options/datasources",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/options/datasources；只读；查询当前租户已登记且包含数据表的 JDBC 数据源；任务表单选项接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：13.数据源选项\n// 业务说明：POST /dwm/quality/options/datasources；只读；查询当前租户已登记且包含数据表的 JDBC 数据源；任务表单选项接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 只列出当前租户具备质检能力的数据源。\nreturn dataQuality.datasources()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/13.数据源选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000013',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000013",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "14.数据表选项",\n  "path": "/options/tables",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"datasourceId\\":\\"dq_demo_source_20260802\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/options/tables；只读；查询指定数据源已登记数据表；任务表单选项接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：14.数据表选项\n// 业务说明：POST /dwm/quality/options/tables；只读；查询指定数据源已登记数据表；任务表单选项接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 根据已登记数据源读取其可质检表。\nvar datasourceId = body?.datasourceId == null ? \'\' : (\'\' + body.datasourceId).trim()\nif (datasourceId == \'\') { exit 400, \'数据源ID不能为空\' }\nreturn dataQuality.tables(datasourceId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/14.数据表选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000014',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000014",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "15.字段选项",\n  "path": "/options/columns",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tableId\\":\\"dq_demo_population_meta\\"}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/options/columns；只读；查询指定登记数据表字段、主键和索引属性；规则表单选项接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：15.字段选项\n// 业务说明：POST /dwm/quality/options/columns；只读；查询指定登记数据表字段、主键和索引属性；规则表单选项接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 根据已登记数据表读取字段，供规则表单选择。\nvar tableId = body?.tableId == null ? \'\' : (\'\' + body.tableId).trim()\nif (tableId == \'\') { exit 400, \'数据表ID不能为空\' }\nreturn dataQuality.columns(tableId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/15.字段选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1000000000000000000000000000015',NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000015",\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "16.规则模板",\n  "path": "/options/templates",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "description": "POST /dwm/quality/options/templates；只读；返回 Java 执行内核支持的受控规则模板，不包含任意SQL；规则表单选项接口。",\n  "createTime": 1785628800000,\n  "updateTime": 1785628800000,\n  "script": null\n}\n================================\n// 接口：16.规则模板\n// 业务说明：POST /dwm/quality/options/templates；只读；返回 Java 执行内核支持的受控规则模板，不包含任意SQL；规则表单选项接口。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 内置规则定义直接保存在可编辑接口中，页面可实时看到模板调整。\nreturn [\n    {ruleType:\'NOT_NULL\', ruleName:\'非空校验\', dimension:\'COMPLETENESS\', description:\'字段值不能为 NULL\'},\n    {ruleType:\'NOT_EMPTY\', ruleName:\'非空白校验\', dimension:\'COMPLETENESS\', description:\'文本字段不能为 NULL 或空字符串\'},\n    {ruleType:\'UNIQUE\', ruleName:\'唯一性校验\', dimension:\'UNIQUENESS\', description:\'一个或多个字段的组合不能重复\'},\n    {ruleType:\'RANGE\', ruleName:\'数值范围校验\', dimension:\'ACCURACY\', description:\'数值必须位于配置的最小值和最大值之间\'},\n    {ruleType:\'ENUM\', ruleName:\'枚举值校验\', dimension:\'VALIDITY\', description:\'字段值必须属于允许值集合\'},\n    {ruleType:\'LENGTH\', ruleName:\'长度校验\', dimension:\'VALIDITY\', description:\'文本长度必须位于配置范围\'},\n    {ruleType:\'REGEX\', ruleName:\'格式校验\', dimension:\'VALIDITY\', description:\'文本必须匹配配置的正则表达式\'},\n    {ruleType:\'TIMELINESS\', ruleName:\'时效性校验\', dimension:\'TIMELINESS\', description:\'时间字段处于执行提交时间的允许过去/未来区间\'},\n    {ruleType:\'REFERENCE\', ruleName:\'跨表引用校验\', dimension:\'CONSISTENCY\', description:\'同一登记数据源的目标表中存在对应单字段或联合键\'}\n]\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/16.规则模板.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000016",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "17.删除质检任务",\n  "createTime": 1790495138754,\n  "updateTime": 1790498525458,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/task/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按目标标识和当前状态执行删除质检任务，返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：17.删除质检任务\n// 业务说明：按目标标识和当前状态执行删除质检任务，返回处理结果。\n\nimport tenantRuntime\nimport dataQuality\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\n// 软删除任务并保留历史质检结果和审计记录。\nvar taskId = body?.taskId == null ? \'\' : (\'\' + body.taskId).trim()\nif (taskId == \'\') { exit 400, \'任务ID不能为空\' }\nreturn dataQuality.deleteTask(taskId)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/17.删除质检任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "a1000000000000000000000000000017",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "18.责任组织选项",\n  "createTime": 1790495138845,\n  "updateTime": 1790498525706,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/options/organizations",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取当前租户未删除的组织机构，按顺序返回质量整改责任组织选择项。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：18.责任组织选项\n// 路由：POST /dwm/quality/options/organizations\n// 业务说明：读取当前租户未删除的组织机构，按顺序返回质量整改责任组织选择项。\nimport tenantRuntime\n// Responsibility selector; never accept a browser-provided tenant.\nvar tenantId=tenantRuntime.id()\nreturn db.select(\'SELECT id AS tid,name,parent_id FROM rm_org_t WHERE tenant_id=#{tenantId} AND (deleted IS NULL OR deleted=0) AND id<>\\\'ROOT\\\' ORDER BY serial_number, name\')\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/18.责任组织选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_quality_work_create_01",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "19.创建质量工单",\n  "createTime": 1789337365872,\n  "updateTime": 1790498524575,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/workorders/create",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行创建质量工单，返回保存或配置结果；使用请求参数 issueId、assigneeOrgId、remark；涉及 asset_workbench_issue_t、rm_org_t、dq_quality_issue_sample_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：19.创建质量工单\n// 路由：POST /dwm/quality/workorders/create\n// 业务说明：校验请求资料后执行创建质量工单，返回保存或配置结果；使用请求参数 issueId、assigneeOrgId、remark；涉及 asset_workbench_issue_t、rm_org_t、dq_quality_issue_sample_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nimport cn.hutool.core.util.IdUtil\n// Create a remediation case from an actual bounded issue sample; idempotent under the issue lock.\nvar tenantId=tenantRuntime.id()\nvar issueId=body?.issueId\nif(issueId==null || issueId==\'\') {exit 400,\'质量问题ID不能为空\'}\nreturn db.transaction(()=>{\n    var issue=db.selectOne(\'SELECT * FROM dq_quality_issue_sample_t WHERE tenant_id=#{tenantId} AND tid=#{issueId} FOR UPDATE\')\n    if(issue==null) {exit 404,\'质量问题不存在或无权访问\'}\n    var existing=db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'asset_type\',\'quality_issue\').eq(\'asset_id\',issueId).eq(\'issue_type\',\'QUALITY_REMEDIATION\').eq(\'is_del\',0).selectOne()\n    if(existing!=null) {return existing}\n    var assignee=body?.assigneeOrgId\n    if(assignee!=null && assignee!=\'\' && db.table(\'rm_org_t\').where().eq(\'tenant_id\',tenantId).eq(\'id\',assignee).eq(\'deleted\',0).count()!=1) {exit 400,\'责任组织不存在或不属于当前租户\'}\n    var principal=approvalRuntime.principal()\n    var now=new Date()\n    var row={tid:IdUtil.getSnowflakeNextIdStr(),tenant_id:tenantId,asset_type:\'quality_issue\',asset_id:issueId,issue_type:\'QUALITY_REMEDIATION\',issue_code:issue.issueHash,title:\'质量整改：\'+(issue.columnName||\'字段异常\'),detail:body?.remark||\'由真实质检问题样例创建\',status:\'OPEN\',reporter_id:principal.userId,assignee_org_id:assignee,created_time:now,updated_time:now,is_del:0}\n    db.table(\'asset_workbench_issue_t\').primary(\'tid\').insert(row)\n    db.table(\'dq_quality_issue_sample_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',issueId).update({issue_status:\'ASSIGNED\',assigned_org_id:assignee,updated_time:now})\n    return row\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/19.创建质量工单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_quality_work_transition_01",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "20.推进质量工单",\n  "createTime": 1789337365935,\n  "updateTime": 1790498524318,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/workorders/transition",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "核验当前租户的质量整改工单与动作；支持开始处理、提交复检及在新质检结果满足要求后关闭，并记录意见和状态。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：20.推进质量工单\n// 路由：POST /dwm/quality/workorders/transition\n// 业务说明：核验当前租户的质量整改工单与动作；支持开始处理、提交复检及在新质检结果满足要求后关闭，并记录意见和状态。\nimport tenantRuntime\nimport approvalRuntime\n// Shared remediation state machine. Current tenant only; closing requires a newer real rule result.\nvar tenantId=tenantRuntime.id()\nvar orderId=body?.orderId\nvar action=body?.action\nif(orderId==null || orderId==\'\') {exit 400,\'工单ID不能为空\'}\nif(action!=\'START\' && action!=\'SUBMIT_RECHECK\' && action!=\'CLOSE\') {exit 400,\'工单动作不合法\'}\nvar expected=action==\'START\'?\'OPEN\':action==\'SUBMIT_RECHECK\'?\'IN_PROGRESS\':\'PENDING_RECHECK\'\nvar next=action==\'START\'?\'IN_PROGRESS\':action==\'SUBMIT_RECHECK\'?\'PENDING_RECHECK\':\'CLOSED\'\nvar opinion=body?.opinion\nif(action!=\'START\' && (opinion==null || (opinion+\'\').trim()==\'\')) {exit 400,\'请填写整改或复检说明\'}\nvar principal=approvalRuntime.principal()\nreturn db.transaction(()=>{\n    var row=db.selectOne(\'SELECT * FROM asset_workbench_issue_t WHERE tenant_id=#{tenantId} AND tid=#{orderId} AND asset_type=\\\'quality_issue\\\' AND issue_type=\\\'QUALITY_REMEDIATION\\\' AND is_del=0 FOR UPDATE\')\n    if(row==null) {exit 404,\'工单不存在或无权访问\'}\n    if(row.status!=expected) {exit 409,\'工单状态已变化或操作顺序不合法，请刷新后重试\'}\n    var assignee=body?.assigneeOrgId || row.assigneeOrgId\n    if(action==\'START\') {\n        if(assignee==null || assignee==\'\') {exit 400,\'请选择责任组织\'}\n        if(db.table(\'rm_org_t\').where().eq(\'tenant_id\',tenantId).eq(\'id\',assignee).eq(\'deleted\',0).count()!=1) {exit 400,\'责任组织不存在或不属于当前租户\'}\n    }\n    if(action==\'CLOSE\') {\n        var origin=db.selectOne(\'SELECT i.column_name,i.task_rule_id,m.rule_type,r.task_id,qr.parameters_json FROM dq_quality_issue_sample_t i JOIN dq_quality_metric_t m ON m.run_id=i.run_id AND m.task_rule_id=i.task_rule_id AND m.tenant_id=#{tenantId} JOIN dq_quality_task_rule_t qr ON qr.tid=i.task_rule_id AND qr.tenant_id=#{tenantId} JOIN dq_quality_run_t r ON r.tid=i.run_id AND r.tenant_id=#{tenantId} WHERE i.tid=#{row.assetId} AND i.tenant_id=#{tenantId}\')\n        if(origin==null) {exit 409,\'原始质量问题不存在，不能关闭\'}\n        // Edits create new rule IDs. Match the original rule meaning, not an obsolete\n        // ID/version; an unrelated passing rule or an empty source cannot close a case.\n        var checks=db.select(\'SELECT r.tid,m.violation_count,m.checked_count,qr.parameters_json FROM dq_quality_run_t r JOIN dq_quality_metric_t m ON m.run_id=r.tid AND m.tenant_id=#{tenantId} AND m.column_name=#{origin.columnName} AND m.rule_type=#{origin.ruleType} JOIN dq_quality_task_rule_t qr ON qr.tid=m.task_rule_id AND qr.tenant_id=#{tenantId} WHERE r.tenant_id=#{tenantId} AND r.task_id=#{origin.taskId} AND r.status IN (\\\'COMPLETED\\\',\\\'COMPLETED_WITH_ISSUES\\\') AND r.created_time>=#{row.updatedTime} AND r.is_del=0 ORDER BY r.finished_at DESC LIMIT 200\')\n        var passed=false\n        if(checks.size()>0){var latestRunId=checks[0].tid;for(check in checks){if(check.tid==latestRunId && (check.parametersJson+\'\')==(origin.parametersJson+\'\') && check.checkedCount>0 && check.violationCount==0){passed=true}}}\n        if(!passed) {exit 409,\'尚无提交复检后的有效通过结果，请先修复源数据并重新执行原任务；需保持原字段、规则类型和参数，空表或仍有异常时不能关闭\'}\n    }\n    var now=new Date()\n    db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',orderId).eq(\'status\',expected).update({status:next,assignee_org_id:assignee,resolution:opinion,updated_time:now,resolved_time:next==\'CLOSED\'?now:null},true)\n    db.table(\'dq_quality_issue_sample_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',row.assetId).update({issue_status:next,assigned_org_id:assignee,handled_by:principal.userId,handled_at:next==\'CLOSED\'?now:null,handle_remark:opinion,updated_time:now},true)\n    return true\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/20.推进质量工单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "wx_quality_work_page_01",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "21.质量工单列表",\n  "createTime": 1789337365813,\n  "updateTime": 1789337443571,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/workorders/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前租户、整改状态和分页参数读取质量整改工单，返回列表与总数。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：21.质量工单列表\n// 路由：POST /dwm/quality/workorders/page\n// 业务说明：按当前租户、整改状态和分页参数读取质量整改工单，返回列表与总数。\nimport tenantRuntime\nvar tenantId=tenantRuntime.id();var page=body?.page::long(1);var size=body?.size::long(20);var status=body?.status;var rows=db.table(\'asset_workbench_issue_t\').where().eq(\'tenant_id\',tenantId).eq(\'asset_type\',\'quality_issue\').eq(\'issue_type\',\'QUALITY_REMEDIATION\').eq(\'is_del\',0);if(status != null && status != \'\') {rows=rows.eq(\'status\',status)};return {list:rows.orderBy(\'updated_time\',\'desc\').page(size,(page-1)*size),total:rows.count(),page:page,size:size}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.数据质量/21.质量工单列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d5ce0d4911e94d7bb3c22a9f67547406',NULL,NULL,'{\n  "properties": {},\n  "id": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "02.数据质量",\n  "type": "api",\n  "parentId": "4fb5fbaf61b24db1a05ea12ae38437b1",\n  "path": "/quality",\n  "createTime": 1781960051814,\n  "updateTime": 1785628800000,\n  "paths": [],\n  "options": []\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.数据质量/group.json');
