INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('17326938ed5c4cd0a2e377a3ed68d239',NULL,NULL,'{\n  "properties": {},\n  "id": "17326938ed5c4cd0a2e377a3ed68d239",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "01.质检维度查询",\n  "createTime": 1782955345051,\n  "updateTime": 1784437771839,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "getQualityDimension",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取质检规则及字典中的维度定义，组装质量规则页面可选择的维度资料。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.质检维度查询\n// 路由：GET /dwm/quality/getQualityDimension\n// 业务说明：读取质检规则及字典中的维度定义，组装质量规则页面可选择的维度资料。\nimport \'@post:/sym/getDict\' as getDict \nimport log\n\n\n// 从 MySQL 业务表读取当前有效数据。\nvar list = db.table(\'sym_dict_t\').excludes("createdBy","createdTime","updatedBy","updatedTime","isDel")\n    .where()\n    .eq(\'is_del\', 0)\n\nvar parentId = "1891300000000000001"\n\nif (parentId != null && parentId != \'\' ) {\n    // 未传 tid 时可按 parentId 筛选\n    list = list.eq(\'parent_id\', parentId)\n}\n\nvar rows = list.orderBy(\'sort_no\').select()\n\n\nvar dimensionId = []\n\nif (rows == null) {\n    rows = []\n}else {\n  rows.each(item ->{\n    item.label = item.name\n    item.value = item.dictCode\n    dimensionId.add(item.value)\n  })\n\n  // 从 MySQL 业务表读取当前有效数据。\n  var map = db.table(\'data_gov_quality_rule\').columns("check_dimension","tid")\n    .where()\n    .in("check_dimension",dimensionId)\n    .eq(\'is_del\', 0)\n    .select()\n    // 根据api_group_id 分组，分组后，值为分组结果的大小\n    .group(it => it.checkDimension,list => list.size())\n    // 根据value排序\n    .sort((k1,k2,v1,v2) => v2 - v1)\n\n   rows.each(item ->{\n     if(map[item.dictCode] != null) {\n        item.count = map[item.dictCode]\n     }else {\n        item.count = 0\n     }   \n  })  \n}\n\n// 返回当前业务分支的标准结果。\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/01.质检维度查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7220cd17e6c24858a617d3e6f2d4ea42',NULL,NULL,'{\n  "properties": {},\n  "id": "7220cd17e6c24858a617d3e6f2d4ea42",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "02.质量规则列表",\n  "createTime": 1782955345078,\n  "updateTime": 1784437771853,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"ruleName\\": \\"测试\\",\\n    \\"ruleCode\\": \\"测试\\",\\n    \\"checkDimension\\": \\"0\\",\\n    \\"ruleLevel\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询数据质量校验规则列表（不分页）；使用请求参数 ruleName、ruleCode、checkDimension、ruleLevel；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "user_no_login",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：02.质量规则列表\n// 路由：POST /dwm/quality/list\n// 业务说明：查询数据质量校验规则列表（不分页）；使用请求参数 ruleName、ruleCode、checkDimension、ruleLevel；涉及 data_gov_quality_rule 等业务表。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\n\n/**\n * 查询数据质量校验规则列表\n * POST /api/gov/quality/rule/list\n * \n * 查询数据质量校验规则列表（不分页）\n */\n\n// 获取查询条件\nvar ruleName = body?.ruleName\nvar ruleCode = body?.ruleCode\nvar checkDimension = body?.checkDimension\nvar ruleLevel = body?.ruleLevel\n\n// 构建查询条件\nvar query = db.table(\'data_gov_quality_rule\')\n    .where()\n    .eq(\'is_del\', 0)\n\nif (ruleName != null && ruleName != \'\') {\n    query = query.like(\'rule_name\', \'%\' + ruleName + \'%\')\n}\n\nif (ruleCode != null && ruleCode != \'\') {\n    query = query.like(\'rule_code\', \'%\' + ruleCode + \'%\')\n}\n\nif (checkDimension != null && checkDimension != \'\') {\n    query = query.eq(\'check_dimension\', checkDimension)\n}\n\nif (ruleLevel != null && ruleLevel != \'\') {\n    query = query.eq(\'rule_level\', ruleLevel)\n}\n\n// ========== 查询列表 ==========\nvar list = query\n    .orderBy(\'created_time\', \'desc\')\n    .select()\n\nlog.info(\'查询数据质量规则列表成功, 共查询到 {} 条数据\', list.length)\n\n// ========== 返回结果 ==========\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/02.质量规则列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3c15325662a5467ea49e20753c3fa82d',NULL,NULL,'{\n  "properties": {},\n  "id": "3c15325662a5467ea49e20753c3fa82d",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "03.质量规则分页查询",\n  "createTime": 1782955345070,\n  "updateTime": 1784437771852,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": \\"1\\",\\n    \\"pageSize\\": \\"20\\",\\n    \\"ruleName\\": \\"22\\",\\n    \\"ruleCode\\": \\"not_null\\",\\n    \\"checkDimension\\": \\"0\\",\\n    \\"ruleLevel\\": \\"0\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "支持分页查询数据质量校验规则列表；使用请求参数 pageNum、pageSize、ruleName、ruleCode、checkDimension、ruleLevel；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.质量规则分页查询\n// 路由：POST /dwm/quality/page\n// 业务说明：支持分页查询数据质量校验规则列表；使用请求参数 pageNum、pageSize、ruleName、ruleCode、checkDimension、ruleLevel；涉及 data_gov_quality_rule 等业务表。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\n\n/**\n * 分页查询数据质量校验规则\n * POST /api/gov/quality/rule/page\n * \n * 支持分页查询数据质量校验规则列表\n */\n\n// 获取分页参数\nvar pageNum = body?.pageNum::long(0)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0? 0 : (pageNum - 1)* pageSize\n\n// 获取查询条件\nvar ruleName = body?.ruleName\nvar ruleCode = body?.ruleCode\nvar checkDimension = body?.checkDimension\nvar ruleLevel = body?.ruleLevel\n\n// 构建查询条件\nvar query = db.table(\'data_gov_quality_rule\')\n    .where()\n    .eq(\'is_del\', 0)\n\nif (ruleName != null && ruleName != \'\') {\n    query = query.like(\'rule_name\', \'%\' + ruleName + \'%\')\n}\n\nif (ruleCode != null && ruleCode != \'\') {\n    query = query.like(\'rule_code\', \'%\' + ruleCode + \'%\')\n}\n\nif (checkDimension != null && checkDimension != \'\') {\n    query = query.eq(\'check_dimension\', checkDimension)\n}\n\nif (ruleLevel != null && ruleLevel != \'\') {\n    query = query.eq(\'rule_level\', ruleLevel)\n}\n\n// ========== 查询总数 ==========\nvar total = query.count()\n\n// ========== 查询列表 ==========\nvar list = query\n    .orderBy(\'created_time\', \'desc\')\n    .page(pageSize, offsetLimit)\n\nlog.info(\'分页查询数据质量规则成功, pageNum: {}, pageSize: {}, total: {}\', pageNum, pageSize, total)\n\n// ========== 返回结果 ==========\nreturn {\n    total: total,\n    list: list\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/03.质量规则分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ed622b19f7834df19cec9b1af9989ed7',NULL,NULL,'{\n  "properties": {},\n  "id": "ed622b19f7834df19cec9b1af9989ed7",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "04.质量规则详情",\n  "createTime": 1782955345043,\n  "updateTime": 1784437771838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"222\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据tid查询数据质量校验规则；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.质量规则详情\n// 路由：POST /dwm/quality/queryById\n// 业务说明：根据tid查询数据质量校验规则；涉及 data_gov_quality_rule 等业务表。\nimport log\nimport request\n\n/**\n * 根据tid查询数据质量校验规则\n * GET /api/gov/quality/rule/query\n * \n * 根据tid查询数据质量校验规则详情\n */\n\n// 获取请求参数\nvar tid = request.getParameter(\'tid\')\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\n// ========== 查询数据 ==========\nvar result = db.table(\'data_gov_quality_rule\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (result == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'规则不存在\'\n}\n\nlog.info(\'查询数据质量规则成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/04.质量规则详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dd4214943e5341c482a59821a64245eb',NULL,NULL,'{\n  "properties": {},\n  "id": "dd4214943e5341c482a59821a64245eb",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "05.质量规则保存修改",\n  "createTime": 1782955345061,\n  "updateTime": 1784437771851,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"a3b8fb4786b64c3b98cb4a3d6978fab5\\",\\n    \\"ruleName\\": \\"非空校验2233\\",\\n    \\"ruleCode\\": \\"not_null_check\\",\\n    \\"checkDimension\\": \\"0\\",\\n    \\"ruleLevel\\": \\"0\\",\\n    \\"ruleDescription\\": \\"核心字段不含 NULL值\\",\\n    \\"scopeOfApplication\\": \\"所有必填字段\\",\\n    \\"configParameters\\": \\"column: 校验字段\\",\\n    \\"checkLogic\\": \\"SELECT count(1) FROM ${table} WHERE ${column} IS NULL\\",\\n    \\"createdBy\\": \\"admin\\",\\n    \\"updatedBy\\": \\"admin\\",\\n    \\"tenantId\\": \\"T-9527\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行质量规则保存修改，返回保存或配置结果；使用请求参数 tid、ruleName、ruleCode、checkDimension、ruleLevel、ruleDescription、scopeOfApplication、configParameters；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.质量规则保存修改\n// 路由：POST /dwm/quality/saveOrUpdate\n// 业务说明：校验请求资料后执行质量规则保存修改，返回保存或配置结果；使用请求参数 tid、ruleName、ruleCode、checkDimension、ruleLevel、ruleDescription、scopeOfApplication、configParameters；涉及 data_gov_quality_rule 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport tenantRuntime\n\n/**\n * 保存或更新数据质量校验规则\n * POST /api/gov/quality/rule/saveOrUpdate\n * \n * 如果 body.tid 有值则更新，否则新增\n * 数据保存到 data_gov_quality_rule 表\n */\n\n// 获取请求参数\nvar tid = body?.tid\nvar ruleName = body?.ruleName\nvar ruleCode = body?.ruleCode\nvar checkDimension = body?.checkDimension\nvar ruleLevel = body?.ruleLevel\nvar ruleDescription = body?.ruleDescription\nvar scopeOfApplication = body?.scopeOfApplication\nvar configParameters = body?.configParameters\nvar checkLogic = body?.checkLogic\nvar createdBy = body?.createdBy\nvar updatedBy = body?.updatedBy\nvar tenantId = tenantRuntime.id()\n\nvar isUpdate = tid != null && tid != \'\'\n\n// 当前时间\nvar now = new Date()\n\n// ========== 保存数据 data_gov_quality_rule ==========\nif (isUpdate) {\n    // 更新数据\n    db.table(\'data_gov_quality_rule\')\n        .primary(\'tid\')\n        .update({\n            tid: tid,\n            rule_name: ruleName,\n            rule_code: ruleCode,\n            check_dimension: checkDimension,\n            rule_level: ruleLevel,\n            rule_description: ruleDescription,\n            scope_of_application: scopeOfApplication,\n            config_parameters: configParameters,\n            check_logic: checkLogic,\n            updated_by: updatedBy,\n            updated_time: now,\n            tenant_id: tenantId\n        })\n    log.info(\'更新数据质量规则成功, tid: {}\', tid)\n} else {\n    // 新增数据，生成新的 tid\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'data_gov_quality_rule\')\n        .primary(\'tid\')\n        .insert({\n            tid: tid,\n            rule_name: ruleName,\n            rule_code: ruleCode,\n            check_dimension: checkDimension,\n            rule_level: ruleLevel,\n            rule_description: ruleDescription,\n            scope_of_application: scopeOfApplication,\n            config_parameters: configParameters,\n            check_logic: checkLogic,\n            created_by: createdBy,\n            created_time: now,\n            updated_by: updatedBy,\n            updated_time: now,\n            is_del: 0,\n            tenant_id: tenantId\n        })\n    log.info(\'新增数据质量规则成功, tid: {}\', tid)\n}\n\n// ========== 查询保存后的完整数据 ==========\n//     .where()\n//     .eq(\'tid\', tid)\n//     .eq(\'is_del\', 0)\n//     .selectOne()\n\n// 构建返回数据\n\n\n// ========== 返回结果 ==========\n//     code: 200,\n//     success: true,\n//     message: isUpdate ? \'更新成功\' : \'新增成功\',\n//     data: data\n// }\n\nreturn tid\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/05.质量规则保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f15e72e40a2c41f4af8620ceb68a393b',NULL,NULL,'{\n  "properties": {},\n  "id": "f15e72e40a2c41f4af8620ceb68a393b",\n  "script": null,\n  "groupId": "d5ce0d4911e94d7bb3c22a9f67547406",\n  "name": "06.质量规则删除",\n  "createTime": 1782955345090,\n  "updateTime": 1784437771853,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/deleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"2e83a7abf33140c7a3df27d0c79e98c1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据id删除数据质量校验规则；使用请求参数 tid；涉及 data_gov_quality_rule 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.质量规则删除\n// 路由：POST /dwm/quality/deleteById\n// 业务说明：根据id删除数据质量校验规则；使用请求参数 tid；涉及 data_gov_quality_rule 等业务表。\nimport log\n\n/**\n * 根据id删除数据质量校验规则\n * POST /api/gov/quality/rule/delete\n * \n * 根据tid逻辑删除数据质量校验规则\n */\n\n// 获取请求参数\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\n// 当前时间\nvar now = new Date()\n\n// ========== 逻辑删除数据 ==========\nvar result = db.table(\'data_gov_quality_rule\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update({\n        is_del: 1,\n        updated_time: now\n    })\n\nif (result == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'规则不存在\'\n}\n\nlog.info(\'删除数据质量规则成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/06.质量规则删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "a1000000000000000000000000000014",\r\n  "script" : null,\r\n  "groupId" : "d5ce0d4911e94d7bb3c22a9f67547406",\r\n  "name" : "15.字段选项",\r\n  "createTime" : 1785628800000,\r\n  "updateTime" : 1791111501368,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/options/columns",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\"tableId\\":\\"dq_demo_population_meta\\"}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "POST /dwm/quality/options/columns；只读；查询指定登记数据表字段、主键和索引属性；规则表单选项接口。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：15.字段选项\n// 业务说明：POST /dwm/quality/options/columns；只读；单表 tableId 兼容旧调用，tableIds 批量查询最多 50 张登记表的字段、主键和索引属性；规则表单选项接口。\n\nimport tenantRuntime\nimport dataQuality\nimport db\n\n// 业务租户始终来自当前登录会话。\nvar tenantId = tenantRuntime.id()\nif (body?.tableIds != null) {\n    var submittedIds = body.tableIds\n    if (!(submittedIds instanceof List) || submittedIds.size() == 0 || submittedIds.size() > 50) {\n        exit 400, \'数据表标识必须是 1 至 50 项的数组\'\n    }\n    var tableIds = []\n    for (rawId in submittedIds) {\n        var id = (\'\' + rawId).trim()\n        if (id == \'\' || id.length() > 32) { exit 400, \'数据表标识不合法\' }\n        if (!tableIds.contains(id)) { tableIds.add(id) }\n    }\n    var rows = db.select("""\n        select c.table_id, c.tid, c.column_name, c.column_comment, c.data_type,\n               c.column_type, c.nullable, c.primary_key, c.is_unique,\n               c.indexed, c.ordinal_position\n          from db_table_column_t c\n          join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n          join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n         where c.tenant_id=#{tenantId} and c.is_del=0 and c.table_id in\n               <foreach collection="tableIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n         order by c.table_id, c.ordinal_position, c.column_name\n    """)\n    var result = {}\n    for (id in tableIds) { result[id] = [] }\n    for (row in rows) {\n        var id = \'\' + row.tableId\n        if (result[id] != null) {\n            var item = {\n                tid: row.tid, column_name: row.columnName, column_comment: row.columnComment,\n                data_type: row.dataType, column_type: row.columnType, nullable: row.nullable,\n                is_unique: row.isUnique, indexed: row.indexed,\n                ordinal_position: row.ordinalPosition\n            }\n            if (row.primaryKey != null) { item.primary_key = row.primaryKey }\n            result[id].add(item)\n        }\n    }\n    return result\n}\n// 根据已登记数据表读取字段，供规则表单选择。\nvar tableId = body?.tableId == null ? \'\' : (\'\' + body.tableId).trim()\nif (tableId == \'\') { exit 400, \'数据表ID不能为空\' }\nreturn dataQuality.columns(tableId)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/02.质量规则/15.字段选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d5ce0d4911e94d7bb3c22a9f67547406',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "d5ce0d4911e94d7bb3c22a9f67547406",\r\n  "name" : "02.质量规则",\r\n  "type" : "api",\r\n  "parentId" : "4fb5fbaf61b24db1a05ea12ae38437b1",\r\n  "path" : "/quality",\r\n  "createTime" : 1781960051814,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/02.质量规则/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('77dd13a825764993848cb05d8cb6a771',NULL,'api','{\n  "properties": {},\n  "id": "77dd13a825764993848cb05d8cb6a771",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "01.资源中心总览",\n  "createTime": 1782955345141,\n  "updateTime": 1787153757526,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/layer-list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "资源中心 01：汇总 DST/ODS/DWD/DWM/DWS 五层数据；涉及 sym_dict_t、db_table_t、db_datasource_t、da_prop_t、dwm_center_layer_source_t、sym_application_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.资源中心总览\n// 路由：GET /dwm/center/layer-list\n// 业务说明：资源中心 01：汇总 DST/ODS/DWD/DWM/DWS 五层数据；涉及 sym_dict_t、db_table_t、db_datasource_t、da_prop_t、dwm_center_layer_source_t、sym_application_t 等业务表。\nimport \'@get:/dwm/center/dst-info\' as dstInfo\nimport java.util.Map\n\n/*\n * 资源中心 01：汇总 DST/ODS/DWD/DWM/DWS 五层数据。\n *\n * 分层字典读取 sym_dict_t；表资产读取 db_table_t，并通过 db_datasource_t 关联\n * 应用系统。全程只读，不依赖旧 catalog 资产或 Java DataAssetQueryService。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar lower = (value) => textOf(value).trim().toLowerCase()\nvar rowValue = (row, keys) => {\n    if (row == null) { return null }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) { return value }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar firstValue = (row, keys) => {\n    for (key in keys) {\n        var value = rowValue(row, [key])\n        if (!blank(value)) { return value }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar layerRows = db.select("""\n    SELECT tid, dict_name, dict_code, parent_id, tree_path, level_no, sort_no\n      FROM sym_dict_t\n     WHERE is_del = 0\n       AND tree_path LIKE \'0.8961bb1c926143a89dd9d0b0e0adb4ef.%\'\n     ORDER BY level_no, sort_no, dict_name\n""")\nvar roots = {}\nfor (row in layerRows) {\n    var code = lower(firstValue(row, [\'dictCode\', \'dict_code\']))\n    if ([\'dst\', \'ods\', \'dwd\', \'dwm\', \'dws\'].contains(code)) {\n        roots[code] = row\n    }\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar tableRows = db.select("""\n    SELECT *\n      FROM db_table_t\n     WHERE is_del = 0\n       AND asset_status = 2\n""")\n// 从 MySQL 业务表读取当前有效数据。\nvar datasourceRows = db.select("""\n    SELECT d.tid, d.db_name, d.app_id, d.org_id, d.db_type, d.node_id,\n           MAX(CASE WHEN p.prop_name IN (\'dataSourceType\', \'connection.dataSourceType\') AND p.is_del = 0 THEN p.prop_value END) AS data_source_type,\n           MAX(CASE WHEN p.prop_name = \'nodeId\' AND p.is_del = 0 THEN p.prop_value END) AS node_id_prop\n      FROM db_datasource_t d\n LEFT JOIN da_prop_t p ON p.parent_id = d.tid\n     WHERE d.is_del = 0\n     GROUP BY d.tid, d.db_name, d.app_id, d.org_id, d.db_type, d.node_id\n""")\nvar datasourceMap = {}\nfor (source in datasourceRows) {\n    datasourceMap[firstValue(source, [\'tid\'])] = source\n}\n\n// 读取资源中心分层/分域节点已经配置的数据中心数据源关联。\nvar sourceRelationRows = db.select("""\n    SELECT r.target_id, r.target_type, r.layer_code, r.datasource_id,\n           d.db_name, d.db_type, d.node_id\n      FROM dwm_center_layer_source_t r\n LEFT JOIN db_datasource_t d ON d.tid = r.datasource_id AND d.is_del = 0\n     WHERE r.is_del = 0\n""")\nvar sourceRelationMap = {}\nfor (relation in sourceRelationRows) {\n    sourceRelationMap[textOf(firstValue(relation, [\'targetType\', \'target_type\'])) + \'_\' + textOf(firstValue(relation, [\'targetId\', \'target_id\']))] = relation\n}\nvar sourceInfoOf = (targetType, targetId) => {\n    var relation = sourceRelationMap[textOf(targetType) + \'_\' + textOf(targetId)]\n    if (relation == null) {\n        return { datasourceId: null, datasourceName: null, dbType: null }\n    }\n    return {\n        datasourceId: firstValue(relation, [\'datasourceId\', \'datasource_id\']),\n        datasourceName: firstValue(relation, [\'dbName\', \'db_name\']),\n        dbType: firstValue(relation, [\'dbType\', \'db_type\'])\n    }\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar appRows = db.select("""\n    SELECT tid, app_name\n      FROM sym_application_t\n     WHERE is_del = 0\n       AND asset_status = 2\n""")\nvar appMap = {}\nfor (app in appRows) {\n    appMap[firstValue(app, [\'tid\'])] = app\n}\nvar layerTables = { dst: [], ods: [], dwd: [], dwm: [], dws: [] }\nvar sourceLayerOf = (source) => {\n    if (source == null) { return \'\' }\n    return lower(firstValue(source, [\'dataSourceType\', \'data_source_type\']))\n}\nvar rootCodeOf = (sourceType) => {\n    var code = lower(sourceType)\n    if (blank(code)) { return \'dst\' }\n    if (layerTables[code] != null) { return code }\n    for (rootCode in [\'ods\', \'dwd\', \'dwm\', \'dws\']) {\n        var root = roots[rootCode]\n        var rootId = firstValue(root, [\'tid\'])\n        var child = layerRows.find(item => lower(firstValue(item, [\'dictCode\', \'dict_code\'])) == code)\n        var treePath = firstValue(child, [\'treePath\', \'tree_path\'])\n        if (!blank(rootId) && !blank(treePath) && treePath.indexOf(rootId) >= 0) {\n            // 返回当前业务分支的标准结果。\n            return rootCode\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return \'dst\'\n}\nfor (table in tableRows) {\n    var source = datasourceMap[firstValue(table, [\'datasourceId\', \'datasource_id\'])]\n    // 表级数据组织优先；历史登记只在数据源 da_prop_t 保存了 ODS/DST 时，\n    // 回退到该数据源的登记属性，避免整库已归属 ODS 却在资源中心漏展示。\n    var sourceType = firstValue(table, [\'dataSourceType\', \'data_source_type\'])\n    if (blank(sourceType)) {\n        sourceType = sourceLayerOf(source)\n    }\n    var code = rootCodeOf(sourceType)\n    layerTables[code].add(table)\n}\nvar buildDictionaryItems = (rootCode) => {\n    var root = roots[rootCode]\n    var rootId = firstValue(root, [\'tid\'])\n    var children = layerRows.filter(item => textOf(firstValue(item, [\'parentId\', \'parent_id\'])) == textOf(rootId))\n    var items = []\n    for (child in children) {\n    var childCode = lower(firstValue(child, [\'dictCode\', \'dict_code\']))\n    var rows = layerTables[rootCode].filter(table =>\n            lower(firstValue(table, [\'dataSourceType\', \'data_source_type\'])) == childCode ||\n            lower(sourceLayerOf(datasourceMap[firstValue(table, [\'datasourceId\', \'datasource_id\'])])) == childCode\n        )\n        var dataCount = 0\n        for (table in rows) {\n            var recordCount = rowValue(table, [\'recordCount\', \'record_count\'])\n            dataCount = dataCount + (recordCount == null ? 0 : recordCount::long)\n        }\n        items.add({\n            id: firstValue(child, [\'tid\']),\n            name: firstValue(child, [\'dictName\', \'dict_name\']),\n            layerCode: childCode,\n            sourceId: sourceInfoOf(\'domain\', firstValue(child, [\'tid\'])).datasourceId,\n            sourceName: sourceInfoOf(\'domain\', firstValue(child, [\'tid\'])).datasourceName,\n            sourceDbType: sourceInfoOf(\'domain\', firstValue(child, [\'tid\'])).dbType,\n            catalogCount: rows.size(),\n            tableCount: rows.size(),\n            dataCount: dataCount\n        })\n    }\n    // 返回当前业务分支的标准结果。\n    return items\n}\n// ODS 与其他数仓层一致，按 dataSourceType 字典下的二级分类展示。\n// 例如 ODS 下的“原始库”节点即为可维护、可保存目标数据源的分域节点，\n// 不再按应用系统聚合，确保分域关联可以正确回显。\nvar odsItems = buildDictionaryItems(\'ods\')\nvar odsTableCount = layerTables.ods.size()\nvar dstResult = dstInfo()\nvar dwdItems = buildDictionaryItems(\'dwd\')\nvar dwmItems = buildDictionaryItems(\'dwm\')\nvar dwsItems = buildDictionaryItems(\'dws\')\nvar dwsId = firstValue(roots.dws, [\'tid\'])\nvar dwmId = firstValue(roots.dwm, [\'tid\'])\nvar dwdId = firstValue(roots.dwd, [\'tid\'])\nvar odsId = firstValue(roots.ods, [\'tid\'])\nvar dstId = firstValue(roots.dst, [\'tid\'])\nvar dwsSource = sourceInfoOf(\'layer\', dwsId)\nvar dwmSource = sourceInfoOf(\'layer\', dwmId)\nvar dwdSource = sourceInfoOf(\'layer\', dwdId)\nvar odsSource = sourceInfoOf(\'layer\', odsId)\nvar dstSource = sourceInfoOf(\'layer\', dstId)\n// 返回当前业务分支的标准结果。\nreturn [\n    {\n        id: dwsId,\n        name: \'DWS\',\n        title: \'服务层 DWS\',\n        sourceId: dwsSource.datasourceId,\n        sourceName: dwsSource.datasourceName,\n        sourceDbType: dwsSource.dbType,\n        categoryCount: layerTables.dws.size(),\n        domains: [{ name: \'专题库\', items: dwsItems }]\n    },\n    {\n        id: dwmId,\n        name: \'DWM\',\n        title: \'整合层 DWM\',\n        sourceId: dwmSource.datasourceId,\n        sourceName: dwmSource.datasourceName,\n        sourceDbType: dwmSource.dbType,\n        categoryCount: layerTables.dwm.size(),\n        domains: [{ name: \'主题库\', items: dwmItems }]\n    },\n    {\n        id: dwdId,\n        name: \'DWD\',\n        title: \'基础层 DWD\',\n        sourceId: dwdSource.datasourceId,\n        sourceName: dwdSource.datasourceName,\n        sourceDbType: dwdSource.dbType,\n        categoryCount: layerTables.dwd.size(),\n        domains: [{ name: \'标准库\', items: dwdItems }]\n    },\n    {\n        id: odsId,\n        name: \'ODS\',\n        title: \'贴源层 ODS\',\n        sourceId: odsSource.datasourceId,\n        sourceName: odsSource.datasourceName,\n        sourceDbType: odsSource.dbType,\n        categoryCount: odsTableCount,\n        domains: [{ name: \'原始库\', items: odsItems }]\n    },\n    {\n        id: dstId,\n        name: \'DST\',\n        title: \'数源层 DST\',\n        sourceId: dstSource.datasourceId,\n        sourceName: dstSource.datasourceName,\n        sourceDbType: dstSource.dbType,\n        tableCount: dstResult == null ? 0 : dstResult.dstTableCount,\n        domains: [{ name: \'原始库\', items: dstResult == null ? [] : dstResult.dst }]\n    }\n]\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/01.资源中心总览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5ab722975fb242aa9944638c3fa9c51b',NULL,NULL,'{\n  "properties": {},\n  "id": "5ab722975fb242aa9944638c3fa9c51b",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "02.基础层列表",\n  "createTime": 1782955345110,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dwd-list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"sortField\\": \\"updatedTime\\",\\n    \\"sortDir\\": \\"desc\\",\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"conditions\\": [\\n        {\\n            \\"field\\": \\"dataSourceType\\",\\n            \\"value\\": \\"qugzbzk\\",\\n            \\"type\\": \\"in\\"\\n        }\\n    ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "资源中心 02：基础层 DWD 数据表分页；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.基础层列表\n// 路由：POST /dwm/center/dwd-list\n// 业务说明：资源中心 02：基础层 DWD 数据表分页；读取或计算后返回业务结果。\nimport \'@post:/dwm/center/layer-page\' as layerPage\n\n/*\n * 资源中心 02：基础层 DWD 数据表分页。\n * 只读 db_table_t；可由 dataSourceType 条件筛选具体标准库。\n */\n\nvar oldBody = body\nbody = { ...(oldBody == null ? {} : oldBody), layerRoot: \'dwd\' }\nvar result = layerPage()\nbody = oldBody\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/02.基础层列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ea38fe47d5324bf0be61209dbfef3791',NULL,NULL,'{\n  "properties": {},\n  "id": "ea38fe47d5324bf0be61209dbfef3791",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "03.服务层列表",\n  "createTime": 1782955345120,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dws-list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"sortField\\": \\"updatedTime\\",\\n    \\"sortDir\\": \\"desc\\",\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"conditions\\": [\\n        {\\n            \\"field\\": \\"dataSourceType\\",\\n            \\"value\\": \\"qugzbzk\\",\\n            \\"type\\": \\"in\\"\\n        }\\n    ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "资源中心 03：服务层 DWS 数据表分页；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.服务层列表\n// 路由：POST /dwm/center/dws-list\n// 业务说明：资源中心 03：服务层 DWS 数据表分页；读取或计算后返回业务结果。\nimport \'@post:/dwm/center/layer-page\' as layerPage\n\n/*\n * 资源中心 03：服务层 DWS 数据表分页。\n * 只读 db_table_t；可由 dataSourceType 条件筛选具体专题库。\n */\n\nvar oldBody = body\nbody = { ...(oldBody == null ? {} : oldBody), layerRoot: \'dws\' }\nvar result = layerPage()\nbody = oldBody\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/03.服务层列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('resource_ods_list_01',NULL,NULL,'{\n  "properties": {},\n  "id": "resource_ods_list_01",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "04.贴源层列表",\n  "createTime": 1784454007655,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/ods-list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"conditions\\": [\\n    ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "资源中心 04：贴源层 ODS 数据表分页；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.贴源层列表\n// 路由：POST /dwm/center/ods-list\n// 业务说明：资源中心 04：贴源层 ODS 数据表分页；读取或计算后返回业务结果。\nimport \'@post:/dwm/center/layer-page\' as layerPage\n\n/*\n * 资源中心 04：贴源层 ODS 数据表分页。\n * 只读 db_table_t，不调用旧 Java 资产查询服务。\n */\n\nvar oldBody = body\nbody = { ...(oldBody == null ? {} : oldBody), layerRoot: \'ods\' }\nvar result = layerPage()\nbody = oldBody\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/04.贴源层列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('resource_layer_page_01',NULL,NULL,'{\n  "properties": {},\n  "id": "resource_layer_page_01",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "05.分层数据表公共分页",\n  "createTime": 1784454007655,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/layer-page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"conditions\\": [\\n    ],\\n    \\"layerRoot\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据 layerRoot 选择 ODS、DWD 或 DWS 分层，复用登记表分页接口筛选当前租户数据，并补齐页面所需目录字段。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.分层数据表公共分页\n// 路由：POST /dwm/center/layer-page\n// 业务说明：根据 layerRoot 选择 ODS、DWD 或 DWS 分层，复用登记表分页接口筛选当前租户数据，并补齐页面所需目录字段。\nimport \'@post:/dst/database/table/page\' as tablePage\n\n/*\n * 资源中心分层列表公共实现。\n *\n * 调用方通过 body.layerRoot 指定 ods/dwd/dws；页面传入子层 dataSourceType 时按子层\n * 过滤。结果以 db_table_t 为准，并补齐旧列表组件需要的目录兼容字段。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\n// 解析请求体并为可选参数设置默认值。\nvar root = body == null ? null : body.layerRoot\nvar conditions = body == null || body.conditions == null ? [] : body.conditions\nvar hasLayerCondition = conditions.find(item => item != null && item.field == \'dataSourceType\') != null\nif (!hasLayerCondition && !blank(root)) {\n    conditions.add({ field: \'dataSourceType\', value: root, type: \'match\' })\n}\nvar oldBody = body\nbody = {\n    ...(oldBody == null ? {} : oldBody),\n    conditions: conditions,\n    pageNum: oldBody == null || oldBody.pageNum == null ? 1 : oldBody.pageNum,\n    pageSize: oldBody == null || oldBody.pageSize == null ? 20 : oldBody.pageSize\n}\nvar result = tablePage()\nbody = oldBody\nvar list = []\nfor (item in result == null || result.list == null ? [] : result.list) {\n    list.add({\n        ...item,\n        catalogName: blank(item.catalogName) ? item.tableNameCn : item.catalogName,\n        catalogNameEn: blank(item.catalogNameEn) ? item.tableName : item.catalogNameEn,\n        sourceTableId: item.tid,\n        targetTableId: item.tid,\n        targetTable: item,\n        sourceDir: item.tableNameCn,\n        sourceCatalogName: item.tableNameCn,\n        processLogic: \'\',\n        status: \'1\'\n    })\n}\n// 返回当前业务分支的标准结果。\nreturn {\n    pageNum: result == null ? 1 : result.pageNum,\n    pageSize: result == null ? 20 : result.pageSize,\n    list: list,\n    total: result == null ? 0 : result.total\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/05.分层数据表公共分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('48f4dd83b6a943fbba6b252921c730f8',NULL,NULL,'{\n  "properties": {},\n  "id": "48f4dd83b6a943fbba6b252921c730f8",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "06.DST层总览",\n  "createTime": 1782955345100,\n  "updateTime": 1787153757484,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dst-info",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "资源中心 06：按当前组织树汇总 DST 层应用系统、数据源和数据表；涉及 rm_org_t、db_datasource_t、db_table_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.DST层总览\n// 路由：GET /dwm/center/dst-info\n// 业务说明：资源中心 06：按当前组织树汇总 DST 层应用系统、数据源和数据表；涉及 rm_org_t、db_datasource_t、db_table_t 等业务表。\nimport "@post:/sym/user/me" as me\nimport java.util.Map\n\n/*\n * 资源中心 06：按当前组织树汇总 DST 层应用系统、数据源和数据表。\n *\n * 统计直接读取 sym_application_t、db_datasource_t、db_table_t，避免 ES 短暂\n * 不可用时拖垮资源中心首页。该接口只读，不修改资产或索引。\n */\n\nvar textOf = (value) => value == null ? \'\' : value + \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar statsRows = db.select("""\n    SELECT d.org_id,\n           COUNT(DISTINCT d.app_id) AS app_count,\n           COUNT(DISTINCT d.tid) AS db_count,\n           COUNT(DISTINCT t.tid) AS table_count\n      FROM db_datasource_t d\n      LEFT JOIN db_table_t t\n        ON t.datasource_id = d.tid\n       AND t.is_del = 0\n       AND t.asset_status = 2\n     WHERE d.is_del = 0\n       AND d.asset_status = 2\n     GROUP BY d.org_id\n""")\nvar statsByOrg = {}\nfor (row in statsRows) {\n    var orgId = textOf(rowValue(row, [\'orgId\', \'org_id\']))\n    if (!orgId.isEmpty()) {\n        statsByOrg[orgId] = {\n            appCount: rowValue(row, [\'appCount\', \'app_count\']),\n            dbCount: rowValue(row, [\'dbCount\', \'db_count\']),\n            tableCount: rowValue(row, [\'tableCount\', \'table_count\'])\n        }\n    }\n}\n\nvar currentUser = me()\nvar rootSerial = rowValue(currentUser, [\'orgRootSerialNumber\', \'org_root_serial_number\'])\n// 从 MySQL 业务表读取当前有效数据。\nvar orgQuery = db.table(\'rm_org_t\')\n    .excludes(\'shortName\', \'creditCode\', \'standard\', \'createId\', \'updateId\', \'createTime\', \'updateTime\', \'deleted\')\n    .where()\n    .eq(\'deleted\', \'0\')\nif (rootSerial != null && !textOf(rootSerial).isEmpty()) {\n    orgQuery.like(\'serial_number\', textOf(rootSerial) + \'%\')\n}\nvar orgList = orgQuery.orderBy(\'sort_num\').select()\n\nvar result = []\nvar dstTableCount = 0\nvar dbCount = 0\nfor (org in orgList) {\n    var orgId = textOf(rowValue(org, [\'id\']))\n    var stats = statsByOrg[orgId]\n    if (stats != null && (stats.appCount > 0 || stats.dbCount > 0 || stats.tableCount > 0)) {\n        result.add({\n            orgId: orgId,\n            name: rowValue(org, [\'name\']),\n            appCount: stats.appCount,\n            dbCount: stats.dbCount,\n            tableCount: stats.tableCount\n        })\n        dstTableCount = dstTableCount + stats.tableCount\n        dbCount = dbCount + stats.dbCount\n    }\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    dstTableCount: dstTableCount,\n    dbCount: dbCount,\n    dst: result\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/06.DST层总览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6f3c094d24d8441eb97de48fd0adcb18',NULL,NULL,'{\n  "properties": {},\n  "id": "6f3c094d24d8441eb97de48fd0adcb18",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "07.DST表统计",\n  "createTime": 1782955345131,\n  "updateTime": 1784454007655,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dstTable",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "统计nodeId 为业务库的表，app org db 三个维度统计。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.DST表统计\n// 路由：POST /dwm/center/dstTable\n// 业务说明：统计nodeId 为业务库的表，app org db 三个维度统计。\n// 统计nodeId 为业务库的表，app org db 三个维度统计\n// table没有orgId，需要通过dbId关联db获取orgId\n\nimport tenantEs;\nimport \'@/common/configData\' as configData;\n\n// 第一步：查询所有在用的业务库，获取dbId、appId、orgId的映射关系\nvar dsl_db = {\n  "size": 1000,\n  "query": {\n    "bool": {\n      "must": [\n        { "term": { "assetType": "db" } },\n        { "term": { "assetStatus": 2 } },\n        { "term": { "nodeId": "业务库" } }\n      ]\n    }\n  },\n  "_source": ["id", "appId", "orgId"]  // 获取appId和orgId\n};\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar dbResult = tenantEs.index(configData().es_dataassets).search(dsl_db);\n\n// 构建映射关系\nvar dbIdToAppId = {};\nvar dbIdToOrgId = {};\nvar dbIds = [];\ndbResult.hits.hits.forEach((hit) => {\n  var dbId = hit._id;\n  var appId = hit._source.appId;\n  var orgId = hit._source.orgId;\n  dbIdToAppId[dbId] = appId;\n  dbIdToOrgId[dbId] = orgId;\n  dbIds.push(dbId);\n});\n\n// 第二步：查询属于业务库的table，按dbId聚合（table没有orgId）\nvar dsl_table = {\n  "size": 0,\n  "query": {\n    "bool": {\n      "must": [\n        { "term": { "assetType": "table" } },\n        { "terms": { "dbId": dbIds } }\n      ]\n    }\n  },\n  "aggs": {\n    "by_dbId": {\n      "terms": {\n        "field": "dbId",\n        "size": 10000\n      }\n    }\n  }\n};\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar tableResult = tenantEs.index(configData().es_dataassets).search(dsl_table);\n\n// 第三步：通过dbId关联，计算三个维度的统计\nvar orgIdStats = {};\nvar dbIdStats = {};\nvar appIdStats = {};\n\ntableResult.aggregations.by_dbId.buckets.forEach((bucket) => {\n  var dbId = bucket.key;\n  var count = bucket.doc_count;\n\n  // dbId维度：直接统计\n  dbIdStats[dbId] = count;\n\n  // orgId维度：通过dbIdToOrgId映射\n  var orgId = dbIdToOrgId[dbId];\n  if (orgId) {\n    if (!orgIdStats[orgId]) {\n      orgIdStats[orgId] = 0;\n    }\n    orgIdStats[orgId] = orgIdStats[orgId] + count;\n  }\n\n  // appId维度：通过dbIdToAppId映射\n  var appId = dbIdToAppId[dbId];\n  if (appId) {\n    if (!appIdStats[appId]) {\n      appIdStats[appId] = 0;\n    }\n    appIdStats[appId] = appIdStats[appId] + count;\n  }\n});\n\n// 返回结果\nvar result = {\n  orgId: orgIdStats,\n  dbId: dbIdStats,\n  appId: appIdStats\n};\n\n// 返回当前业务分支的标准结果。\nreturn result;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/07.DST表统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_center_datasource_options_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_center_datasource_options_01",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "08.资源中心关联数据源选项",\n  "createTime": 1785067200000,\n  "updateTime": 1785067200000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/datasource-options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"list\\": [\\n    {\\n      \\"label\\": \\"出入境人员动管系统数据库\\",\\n      \\"value\\": \\"4b5d9992d89744b9b514f8905dc27998\\",\\n      \\"dbType\\": \\"mysql\\",\\n      \\"nodeName\\": \\"业务库\\"\\n    }\\n  ],\\n  \\"total\\": 1\\n}",\n  "description": "资源中心关联数据源选项（POST /dwm/center/datasource-options）。只读接口；从 db_datasource_t 读取全部有效数据源并支持名称/库类型/节点类型模糊搜索，用于分层/分域配置选择关联数据源；不读取或返回 connection extension property 密码；使用请求参数 keyword。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.资源中心关联数据源选项\n// 路由：POST /dwm/center/datasource-options\n// 业务说明：资源中心关联数据源选项（POST /dwm/center/datasource-options）。只读接口；从 db_datasource_t 读取全部有效数据源并支持名称/库类型/节点类型模糊搜索，用于分层/分域配置选择关联数据源；不读取或返回 connection extension property 密码；使用请求参数 keyword。\n/*\n * 资源中心分层/分域配置的数据源下拉选项。\n * - 下拉展示全部有效数据源，方便从现有业务库/前置机/数据中心中选择；\n * - 真正保存时由 /dwm/center/node/save 将被关联数据源 node_id 归一为“数据中心”字典项。\n */\nvar keyword = body?.keyword == null ? \'\' : (body.keyword + \'\').trim()\nvar likeKeyword = \'%\' + keyword.replace("\'", "\'\'") + \'%\'\n\n// node_id 与字典 tid 在历史库里可能存在不同 collation，避免 SQL join 产生排序规则冲突。\nvar nodeRows = db.select("""\n    SELECT c.tid, c.dict_name\n      FROM sym_dict_t c\n      JOIN sym_dict_t p ON p.tid = c.parent_id AND p.is_del = 0\n     WHERE c.is_del = 0\n       AND p.dict_code = \'nodeType\'\n""")\nvar nodeNameById = {}\nfor (node in (nodeRows == null ? [] : nodeRows)) {\n    nodeNameById[node.tid + \'\'] = node.dictName\n}\n\nvar rows = db.select("""\n    SELECT tid, db_name, db_type, show_connect, connection_status, node_id\n      FROM db_datasource_t\n     WHERE is_del = 0\n       AND (tid IS NULL OR tid NOT LIKE \'codex\\_%\')\n       AND (db_name IS NULL OR db_name NOT LIKE \'codex\\_%\')\n     ORDER BY updated_time DESC, created_time DESC, db_name ASC\n     LIMIT 500\n""")\nvar list = []\nfor (row in (rows == null ? [] : rows)) {\n    var nodeName = nodeNameById[row.nodeId + \'\']\n    if (keyword != \'\') {\n        var hitText = ((row.dbName == null ? \'\' : row.dbName) + \' \' +\n            (row.dbType == null ? \'\' : row.dbType) + \' \' +\n            (nodeName == null ? \'\' : nodeName)).toLowerCase()\n        if (!hitText.contains(keyword.toLowerCase())) {\n            continue\n        }\n    }\n    list.add({\n        label: row.dbName,\n        value: row.tid,\n        tid: row.tid,\n        dbName: row.dbName,\n        dbType: row.dbType,\n        nodeId: row.nodeId,\n        nodeName: nodeName,\n        showConnect: row.showConnect,\n        connectionStatus: row.connectionStatus\n    })\n    if (list.size() >= 100) {\n        break\n    }\n}\n\nreturn { list: list, total: list.size() }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/08.资源中心关联数据源选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_center_node_save_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_center_node_save_01",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "09.保存分层节点配置",\n  "createTime": 1785067200000,\n  "updateTime": 1785067200000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/node/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"targetType\\": \\"layer\\",\\n  \\"targetId\\": \\"8961bb1c926143a89dd9d0b0e0adb4ef\\",\\n  \\"name\\": \\"数源层 DST\\",\\n  \\"datasourceId\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"success\\": true\\n}",\n  "description": "保存资源中心分层节点配置（POST /dwm/center/node/save）。写接口；更新 sym_dict_t.dict_name，维护 dwm_center_layer_source_t 中分层/分域节点到数据源的关联；选择关联数据源后同步将 db_datasource_t.node_id 设置为 nodeType=数据中心 的 sym_dict_t.tid；使用请求参数 targetType、targetId、name、datasourceId、layerCode、applyToAllDomains。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.保存分层节点配置\n// 路由：POST /dwm/center/node/save\n// 业务说明：保存资源中心分层节点配置（POST /dwm/center/node/save）。写接口；更新 sym_dict_t.dict_name，维护 dwm_center_layer_source_t 中分层/分域节点到数据源的关联；选择关联数据源后同步将 db_datasource_t.node_id 设置为 nodeType=数据中心 的 sym_dict_t.tid；使用请求参数 targetType、targetId、name、datasourceId、layerCode、applyToAllDomains。\n/*\n * 保存资源中心分层/分域节点配置。\n * - 名称写回 sym_dict_t.dict_name；\n * - 数据源关联写入 dwm_center_layer_source_t，确保下次打开编辑弹框可以反填；\n * - 选择任意有效数据源后，将该数据源 node_id 归一设置为 nodeType=数据中心 的字典 tid。\n */\nimport cn.hutool.core.util.IdUtil\n\nvar textOf = value => value == null ? \'\' : (value + \'\').trim()\nvar targetType = textOf(body?.targetType)\nvar targetId = textOf(body?.targetId)\nvar name = textOf(body?.name)\nvar datasourceId = textOf(body?.datasourceId)\nvar layerCode = textOf(body?.layerCode)\nvar applyToAllDomains = body?.applyToAllDomains === true\n\nif (![\'layer\', \'domain\'].contains(targetType)) {\n    exit 400, \'targetType 只能是 layer 或 domain\'\n}\nif (targetId == \'\') {\n    exit 400, \'targetId 不能为空\'\n}\n\nvar node = db.table(\'sym_dict_t\').where().eq(\'tid\', targetId).eq(\'is_del\', 0).selectOne()\nif (node == null) {\n    exit 404, \'分层节点不存在\'\n}\n\nif (name != \'\') {\n    db.table(\'sym_dict_t\').where().eq(\'tid\', targetId).eq(\'is_del\', 0).update({\n        dict_name: name,\n        updated_time: new Date()\n    })\n}\n\nvar dataCenterNode = db.selectOne("""\n    SELECT c.tid\n      FROM sym_dict_t c\n      JOIN sym_dict_t p ON p.tid = c.parent_id AND p.is_del = 0\n     WHERE c.is_del = 0\n       AND p.dict_code = \'nodeType\'\n       AND c.dict_name = \'数据中心\'\n     LIMIT 1\n""")\nif (dataCenterNode == null) {\n    exit 500, \'缺少 nodeType=数据中心 字典项，无法保存关联数据源\'\n}\n\nif (datasourceId == \'\') {\n    db.table(\'dwm_center_layer_source_t\').where()\n        .eq(\'target_id\', targetId)\n        .eq(\'target_type\', targetType)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: new Date() })\n} else {\n    var source = db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\n    if (source == null) {\n        exit 404, \'关联数据源不存在\'\n    }\n\n    // 业务约束：被资源中心分层/分域关联的数据源统一标记为 nodeType=数据中心。\n    db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).update({\n        node_id: dataCenterNode.tid,\n        updated_time: new Date()\n    })\n\n    // 整层关联时，将已选数据源批量写入该层的所有二级分类。\n    var targets = [{ id: targetId, type: targetType, code: layerCode }]\n    if (applyToAllDomains && targetType == \'layer\') {\n        var domains = db.table(\'sym_dict_t\').where()\n            .eq(\'parent_id\', targetId)\n            .eq(\'is_del\', 0)\n            .orderBy(\'sort_no\')\n            .select()\n        for (domain in (domains == null ? [] : domains)) {\n            targets.add({ id: domain.tid, type: \'domain\', code: domain.dictCode })\n        }\n    }\n\n    for (target in targets) {\n        var relation = db.table(\'dwm_center_layer_source_t\').where()\n            .eq(\'target_id\', target.id)\n            .eq(\'target_type\', target.type)\n            .eq(\'is_del\', 0)\n            .selectOne()\n        if (relation == null) {\n            db.table(\'dwm_center_layer_source_t\').primary(\'tid\').insert({\n                tid: IdUtil.getSnowflakeNextIdStr(),\n                target_id: target.id,\n                target_type: target.type,\n                layer_code: target.code,\n                datasource_id: datasourceId,\n                is_del: 0,\n                created_time: new Date(),\n                updated_time: new Date()\n            })\n        } else {\n            db.table(\'dwm_center_layer_source_t\').where().eq(\'tid\', relation.tid).update({\n                layer_code: target.code,\n                datasource_id: datasourceId,\n                updated_time: new Date()\n            })\n        }\n    }\n}\n\nreturn { success: true }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/09.保存分层节点配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "rc9c090d43fa64a71bf2f2a6d10a0001",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "10.资源运营概览",\n  "createTime": 1788453656475,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/operations/overview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "资源中心运营概览。仅统计当前租户的逻辑模型、物化计划、物化执行和目录发布申请。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.资源运营概览\n// 路由：GET /dwm/center/operations/overview\n// 业务说明：资源中心运营概览。仅统计当前租户的逻辑模型、物化计划、物化执行和目录发布申请。\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nvar countOf = (tableName) => {\n  var rows = db.select(\'SELECT COUNT(1) AS total FROM \' + tableName + \' WHERE tenant_id = #{tenantId} AND is_del = 0\', {tenantId: tenantId})\n  return rows == null || rows.isEmpty() ? 0 : (rows[0].total == null ? 0 : rows[0].total)\n}\nreturn {\n  tenantId: tenantId,\n  logicalModelCount: countOf(\'res_logical_model\'),\n  logicalModelFieldCount: countOf(\'res_logical_model_field\'),\n  materializationPlanCount: countOf(\'res_materialization_plan\'),\n  materializationExecutionCount: countOf(\'res_materialization_execution\'),\n  catalogPublishRequestCount: countOf(\'res_catalog_publish_request\')\n}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/10.资源运营概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "rc9c090d43fa64a71bf2f2a6d10a0002",\n  "script": null,\n  "groupId": "46fe687ba7304a608b5e2865725ad21c",\n  "name": "11.资源运营记录列表",\n  "createTime": 1788453732846,\n  "updateTime": null,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/operations/records",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取当前租户资源中心运营记录。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.资源运营记录列表\n// 路由：GET /dwm/center/operations/records\n// 业务说明：读取当前租户资源中心运营记录。\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nvar rowsOf = (tableName, orderBy) => db.select(\'SELECT * FROM \' + tableName + \' WHERE tenant_id = #{tenantId} AND is_del = 0 ORDER BY \' + orderBy, {tenantId: tenantId})\nreturn {\n  tenantId: tenantId,\n  logicalModels: rowsOf(\'res_logical_model\', \'updated_time DESC, tid DESC\'),\n  logicalModelFields: rowsOf(\'res_logical_model_field\', \'model_id, sort_no, tid\'),\n  materializationPlans: rowsOf(\'res_materialization_plan\', \'updated_time DESC, tid DESC\'),\n  materializationExecutions: rowsOf(\'res_materialization_execution\', \'created_time DESC, tid DESC\'),\n  catalogPublishRequests: rowsOf(\'res_catalog_publish_request\', \'created_time DESC, tid DESC\')\n}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/11.资源运营记录列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "rc9c090d43fa64a71bf2f2a6d10a0003",\r\n  "script" : null,\r\n  "groupId" : "46fe687ba7304a608b5e2865725ad21c",\r\n  "name" : "12.资源运营记录保存",\r\n  "createTime" : 1788453732929,\r\n  "updateTime" : 1790982799099,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/operations/record/save",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "",\r\n  "description" : "新建或更新当前租户资源中心运营记录；字段和表名均由服务端白名单控制；使用请求参数 recordType、fields、tid。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 旧路由兼容保护：POST /dwm/center/operations/record/save。\n// 通用记录编辑不能绕过模型冻结、目录审批或真实物化执行；查询路由继续保留。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nvar kind = body == null || body.recordType == null ? \'\' : (body.recordType + \'\').trim()\nif (kind == \'\') { exit 400, \'缺少记录类型\' }\nif ([\'logicalModel\',\'logicalModelField\',\'materializationPlan\',\'materializationExecution\',\'catalogPublishRequest\'].contains(kind)) {\n    exit 409, \'此记录已由资源中心业务流程管理，请进入对应模型、物化或目录页面操作；通用编辑不能直接修改审批及执行状态\'\n}\nexit 400, \'不支持的记录类型\'\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/12.资源运营记录保存.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "rc9c090d43fa64a71bf2f2a6d10a0004",\r\n  "script" : null,\r\n  "groupId" : "46fe687ba7304a608b5e2865725ad21c",\r\n  "name" : "13.资源运营记录删除",\r\n  "createTime" : 1788453733018,\r\n  "updateTime" : 1790982799160,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/operations/record/delete",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "",\r\n  "description" : "逻辑删除当前租户资源中心运营记录；使用请求参数 recordType、tid。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 旧路由兼容保护：POST /dwm/center/operations/record/delete。\n// 删除动作改由模型归档、物化取消、目录撤回/下线实现，保留版本和执行审计记录。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nvar kind = body == null || body.recordType == null ? \'\' : (body.recordType + \'\').trim()\nif (kind == \'\') { exit 400, \'缺少记录类型\' }\nif ([\'logicalModel\',\'logicalModelField\',\'materializationPlan\',\'materializationExecution\',\'catalogPublishRequest\'].contains(kind)) {\n    exit 409, \'此记录已由资源中心业务流程管理，请使用归档、撤回或下线操作，不能通过通用删除移除版本和执行记录\'\n}\nexit 400, \'不支持的记录类型\'\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/13.资源运营记录删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b6aaff9e31925977b94369d347e7c32a',NULL,'api','{\r\n  "properties" : { },\r\n  "id" : "b6aaff9e31925977b94369d347e7c32a",\r\n  "script" : null,\r\n  "groupId" : "46fe687ba7304a608b5e2865725ad21c",\r\n  "name" : "20.resource-command",\r\n  "createTime" : null,\r\n  "updateTime" : 1790982798990,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/resource-command",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "",\r\n  "description" : "磐石资源中心受控业务命令",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 02.资源中心业务命令入口。路由白名单、租户会话与乐观版本统一校验。\nimport tenantRuntime\nimport \'@/resource-center/planning-command\' as planningCommand\nimport \'@/resource-center/model-command\' as modelCommand\nimport \'@/resource-center/materialization-command\' as materializationCommand\nimport \'@/resource-center/resource-command\' as resourceCommand\nimport \'@/resource-center/catalog-command\' as catalogCommand\nvar tenantId = tenantRuntime.id()\nif (body == null || body.kind == null) { exit 400,\'缺少资源操作类型\' }\nvar command = body\nif (command.tenantId != null) { exit 400,\'业务租户由当前会话确定\' }\nif (![\'GET\',\'POST\',\'PUT\',\'DELETE\'].contains(command.method)) { exit 400,\'不支持的操作方法\' }\nif (command.body == null) { command.body = {} }\nif (command.body.tenantId != null) { exit 400,\'不能通过请求切换业务租户\' }\nvar kind = command.kind + \'\'\nif ([\'layers\',\'databases\',\'bindings\',\'classifications\'].contains(kind)) { return planningCommand(command) }\nif ([\'models\',\'itemsets\'].contains(kind)) { return modelCommand(command) }\nif (kind == \'materializations\') { return materializationCommand(command) }\nif (kind == \'resources\') { return resourceCommand(command) }\nif ([\'catalogs\',\'publications\',\'subscriptions\',\'deliveries\',\'policy\'].contains(kind)) { return catalogCommand(command) }\nexit 400,\'未知资源业务操作\'\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/20.resource-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f32458ca37a55794b4cb49cfb191ca76',NULL,'api','{\r\n  "properties" : { },\r\n  "id" : "f32458ca37a55794b4cb49cfb191ca76",\r\n  "script" : null,\r\n  "groupId" : "46fe687ba7304a608b5e2865725ad21c",\r\n  "name" : "21.resource-state",\r\n  "createTime" : null,\r\n  "updateTime" : 1791068229114,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/resource-state",\r\n  "method" : "GET",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "",\r\n  "description" : "磐石资源中心跨模块状态查询",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 01.资源中心工作台聚合查询；所有子函数共享认证会话与租户，不装载演示数据。\nimport tenantRuntime\nimport \'@/resource-center/technical-read\' as technicalRead\nimport \'@/resource-center/planning-read\' as planningRead\nimport \'@/resource-center/model-read\' as modelRead\nimport \'@/resource-center/catalog-read\' as catalogRead\nvar tenantId = tenantRuntime.id()\nvar technical = technicalRead({pageNo:param?.pageNo,pageSize:param?.pageSize,entityKeyword:param?.keyword})\nvar planning = planningRead({})\nvar models = modelRead({entities:technical.entities})\nvar catalog = catalogRead({})\nvar state = {schemaVersion:1,ignoredMatches:[],technicalRevisions:[],autoApprove:false,busConfigured:false}\nstate.putAll(planning); state.putAll(models)\nfor (key in [\'catalogs\',\'publications\',\'subscriptions\',\'deliveries\',\'autoApprove\',\'busConfigured\',\'deliveryScheduling\']) { state[key] = catalog[key] }\ntechnical.state = state\ntechnical.capabilities = {write:true,review:true,manage:true,execute:true,scheduledDelivery:false,manualDelivery:true,crossNetworkSync:false}\ntechnical.actor = catalog.actor\nreturn technical\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/03.资源中心/21.resource-state.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('46fe687ba7304a608b5e2865725ad21c',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "46fe687ba7304a608b5e2865725ad21c",\r\n  "name" : "03.资源中心",\r\n  "type" : "api",\r\n  "parentId" : "4fb5fbaf61b24db1a05ea12ae38437b1",\r\n  "path" : "/center",\r\n  "createTime" : 1781960051928,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/05.数据治理/03.资源中心/group.json');
