INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_summary_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_summary_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "01.安全中心概览",\n  "path": "/summary",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "description": "读取当前租户数据安全台账概览。"\n}\n================================\n// 接口：安全中心概览\n// 业务说明：按当前租户统计安全模型、规则、任务和策略；只查询租户库中的有效记录。\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\n\n// 固定表名与分类，避免用户输入参与 SQL 标识符拼接。\nvar counts = db.selectOne("""\n    SELECT\n        (SELECT COUNT(1) FROM sec_classification_model WHERE tenant_id = #{tenantId} AND is_del = 0) AS models,\n        (SELECT COUNT(1) FROM sec_classification_rule WHERE tenant_id = #{tenantId} AND is_del = 0) AS rules,\n        (SELECT COUNT(1) FROM sec_scan_task WHERE tenant_id = #{tenantId} AND is_del = 0) AS scanTasks,\n        (SELECT COUNT(1) FROM sec_scan_result WHERE tenant_id = #{tenantId} AND is_del = 0) AS scanResults,\n        (SELECT COUNT(1) FROM sec_review_task WHERE tenant_id = #{tenantId} AND is_del = 0 AND review_status = \'PENDING\') AS pendingReviews,\n        (SELECT COUNT(1) FROM sec_policy WHERE tenant_id = #{tenantId} AND is_del = 0) AS policies,\n        (SELECT COUNT(1) FROM sec_access_grant WHERE tenant_id = #{tenantId} AND is_del = 0) AS accessGrants,\n        (SELECT COUNT(1) FROM sec_masking_policy WHERE tenant_id = #{tenantId} AND is_del = 0) AS maskingPolicies,\n        (SELECT COUNT(1) FROM sec_encryption_task WHERE tenant_id = #{tenantId} AND is_del = 0) AS encryptionTasks,\n        (SELECT COUNT(1) FROM sec_watermark_task WHERE tenant_id = #{tenantId} AND is_del = 0) AS watermarkTasks\n""")\n\nreturn {tenantId: tenantId, metrics: {\n    \'分类模型\': counts.models,\n    \'识别规则\': counts.rules,\n    \'扫描任务\': counts.scanTasks,\n    \'识别结果\': counts.scanResults,\n    \'待人工复核\': counts.pendingReviews,\n    \'授权策略\': counts.policies,\n    \'访问授权\': counts.accessGrants,\n    \'脱敏策略\': counts.maskingPolicies,\n    \'加解密申请\': counts.encryptionTasks,\n    \'水印申请\': counts.watermarkTasks\n}}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/01.安全中心概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_list_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_list_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "02.安全台账列表",\n  "path": "/records/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "按类型读取当前租户安全台账。"\n}\n================================\n// 接口：安全台账列表\n// 业务说明：校验允许的安全台账类型后，只读取当前租户未删除的记录。\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nvar recordType = body?.recordType == null ? \'\' : (\'\' + body.recordType).trim()\nif (recordType == \'\') { exit 400, \'记录类型不能为空\' }\n\n// 表名只能来自固定白名单，请求参数不能作为任意表名执行。\nvar allowed = [\n    \'sec_classification_model\', \'sec_classification_rule\', \'sec_scan_task\',\n    \'sec_scan_result\', \'sec_review_task\', \'sec_policy\', \'sec_access_grant\',\n    \'sec_masking_policy\', \'sec_key_reference\', \'sec_encryption_task\',\n    \'sec_watermark_policy\', \'sec_watermark_task\'\n]\nif (!allowed.contains(recordType)) { exit 400, \'不支持的数据安全记录类型\' }\n\n// 业务行仍按最近更新时间排序，返回结构保持与原接口一致。\nvar items = db.select(\'SELECT * FROM \' + recordType + \' WHERE tenant_id = #{tenantId} AND is_del = 0 ORDER BY updated_time DESC, tid DESC\')\nreturn {tenantId: tenantId, recordType: recordType, items: items}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/02.安全台账列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_save_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_save_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "03.保存安全台账",\n  "path": "/records/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "新增或更新当前租户安全台账；后端白名单过滤字段。"\n}\n================================\n// 接口：保存安全台账\n// 业务说明：按记录类型的字段白名单校验并保存台账；数据变更与审计日志在同一事务内完成。\nimport tenantRuntime\nimport cn.dev33.satoken.stp.StpUtil\nimport java.util.UUID\nimport java.util.LinkedHashMap\n\nvar tenantId = tenantRuntime.id()\nvar recordType = body?.recordType == null ? \'\' : (\'\' + body.recordType).trim()\nif (recordType == \'\') { exit 400, \'记录类型不能为空\' }\n\n// 可写字段和新增必填字段集中写在此接口；新增类型时可直接在 Magic 编辑器调整。\nvar definitions = {\n    sec_classification_model: {fields:\'model_code,model_name,model_type,description,model_status\', required:\'model_code,model_name,model_type,model_status\'},\n    sec_classification_rule: {fields:\'rule_code,rule_name,target_type,field_pattern,content_pattern,sensitivity_level,rule_status\', required:\'rule_code,rule_name,target_type,field_pattern,sensitivity_level,rule_status\'},\n    sec_scan_task: {fields:\'task_code,task_name,model_id,target_scope,task_status,precheck_summary,executor_reference\', required:\'task_code,task_name,target_scope,task_status\'},\n    sec_scan_result: {fields:\'task_id,asset_type,asset_id,field_name,rule_id,sensitivity_level,match_summary,result_status\', required:\'task_id,asset_type,asset_id,field_name,sensitivity_level,result_status\'},\n    sec_review_task: {fields:\'scan_result_id,review_status,review_comment\', required:\'scan_result_id,review_status\'},\n    sec_policy: {fields:\'policy_code,policy_name,policy_type,asset_type,asset_id,policy_content,policy_status\', required:\'policy_code,policy_name,policy_type,policy_content,policy_status\'},\n    sec_access_grant: {fields:\'policy_id,asset_type,asset_id,subject_type,subject_id,access_scope,grant_status,expire_time\', required:\'asset_type,asset_id,subject_type,subject_id,access_scope,grant_status\'},\n    sec_masking_policy: {fields:\'policy_code,policy_name,asset_type,asset_id,field_pattern,masking_algorithm,masking_parameter,policy_status\', required:\'policy_code,policy_name,masking_algorithm,policy_status\'},\n    sec_key_reference: {fields:\'reference_code,reference_name,key_type,algorithm_name,provider_name,reference_status,rotate_time\', required:\'reference_code,reference_name,key_type,reference_status\'},\n    sec_encryption_task: {fields:\'task_code,task_name,key_reference_id,asset_type,asset_id,field_scope,encryption_algorithm,task_status,request_summary\', required:\'task_code,task_name,encryption_algorithm,task_status\'},\n    sec_watermark_policy: {fields:\'policy_code,policy_name,watermark_type,trace_template,file_type_scope,policy_status\', required:\'policy_code,policy_name,watermark_type,trace_template,policy_status\'},\n    sec_watermark_task: {fields:\'task_code,task_name,watermark_policy_id,asset_type,asset_id,file_name,trace_reference,task_status,request_summary\', required:\'task_code,task_name,task_status\'}\n}\nvar definition = definitions[recordType]\nif (definition == null) { exit 400, \'不支持的数据安全记录类型\' }\n\n// 只复制当前类型允许的字段，忽略请求中伪造的租户和系统字段。\nvar fields = body?.fields == null ? {} : body.fields\nvar accepted = new LinkedHashMap()\nfor (name in definition.fields.split(\',\')) {\n    if (fields[name] != null) { accepted.put(name, fields[name]) }\n}\nvar recordId = body?.recordId == null ? \'\' : (\'\' + body.recordId).trim()\nif (recordId == \'\' && fields.tid != null) { recordId = (\'\' + fields.tid).trim() }\nvar creating = recordId == \'\'\nif (creating) {\n    for (name in definition.required.split(\',\')) {\n        if (accepted[name] == null || (\'\' + accepted[name]).trim() == \'\') { exit 400, \'请填写\' + name }\n    }\n} else if (accepted.isEmpty()) {\n    exit 400, \'请至少提交一个可修改字段\'\n}\n\nvar actor = StpUtil.isLogin() ? \'\' + StpUtil.getLoginId() : \'system\'\nreturn db.transaction(() => {\n    if (creating) {\n        recordId = UUID.randomUUID().toString().replace(\'-\', \'\')\n        accepted.put(\'tid\', recordId)\n        accepted.put(\'tenant_id\', tenantId)\n        accepted.put(\'is_del\', 0)\n        db.table(recordType).primary(\'tid\').insert(accepted)\n    } else {\n        var changed = db.table(recordType).where().eq(\'tenant_id\', tenantId).eq(\'tid\', recordId).eq(\'is_del\', 0).update(accepted)\n        if (changed == 0) { exit 400, \'记录不存在或不属于当前租户\' }\n    }\n\n    // 台账变更和审计日志必须一起提交，便于追溯谁修改了什么类型的记录。\n    db.table(\'sec_operation_log\').primary(\'tid\').insert({\n        tid: UUID.randomUUID().toString().replace(\'-\', \'\'), tenant_id: tenantId,\n        record_type: recordType, record_id: recordId,\n        action_code: creating ? \'CREATE\' : \'UPDATE\', outcome: \'SUCCESS\',\n        detail_summary: creating ? \'已创建安全台账记录\' : \'已更新安全台账记录\', operator_id: actor\n    })\n    return db.table(recordType).where().eq(\'tenant_id\', tenantId).eq(\'tid\', recordId).eq(\'is_del\', 0).selectOne()\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/03.保存安全台账.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_delete_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_delete_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "04.删除安全台账",\n  "path": "/records/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "逻辑删除当前租户安全台账，并写入审计记录。"\n}\n================================\n// 接口：删除安全台账\n// 业务说明：按类型白名单软删除当前租户台账，并在同一事务中记录操作审计。\nimport tenantRuntime\nimport cn.dev33.satoken.stp.StpUtil\nimport java.util.UUID\n\nvar tenantId = tenantRuntime.id()\nvar recordType = body?.recordType == null ? \'\' : (\'\' + body.recordType).trim()\nvar recordId = body?.recordId == null ? \'\' : (\'\' + body.recordId).trim()\nif (recordId == \'\') { exit 400, \'记录标识不能为空\' }\nvar allowed = [\'sec_classification_model\',\'sec_classification_rule\',\'sec_scan_task\',\'sec_scan_result\',\n               \'sec_review_task\',\'sec_policy\',\'sec_access_grant\',\'sec_masking_policy\',\'sec_key_reference\',\n               \'sec_encryption_task\',\'sec_watermark_policy\',\'sec_watermark_task\']\nif (!allowed.contains(recordType)) { exit 400, \'不支持的数据安全记录类型\' }\n\nvar actor = StpUtil.isLogin() ? \'\' + StpUtil.getLoginId() : \'system\'\nreturn db.transaction(() => {\n    var changed = db.table(recordType).where().eq(\'tenant_id\', tenantId).eq(\'tid\', recordId).eq(\'is_del\', 0).update({is_del: 1})\n    if (changed == 0) { exit 400, \'记录不存在或不属于当前租户\' }\n    db.table(\'sec_operation_log\').primary(\'tid\').insert({\n        tid: UUID.randomUUID().toString().replace(\'-\', \'\'), tenant_id: tenantId,\n        record_type: recordType, record_id: recordId, action_code: \'DELETE\',\n        outcome: \'SUCCESS\', detail_summary: \'已逻辑删除\', operator_id: actor\n    })\n    return true\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/04.删除安全台账.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_restore_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_restore_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "05.恢复安全台账",\n  "path": "/records/restore",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "恢复当前租户逻辑删除的安全台账。"\n}\n================================\n// 接口：恢复安全台账\n// 业务说明：按类型白名单恢复当前租户已软删除的台账，并记录审计日志。\nimport tenantRuntime\nimport cn.dev33.satoken.stp.StpUtil\nimport java.util.UUID\n\nvar tenantId = tenantRuntime.id()\nvar recordType = body?.recordType == null ? \'\' : (\'\' + body.recordType).trim()\nvar recordId = body?.recordId == null ? \'\' : (\'\' + body.recordId).trim()\nif (recordId == \'\') { exit 400, \'记录标识不能为空\' }\nvar allowed = [\'sec_classification_model\',\'sec_classification_rule\',\'sec_scan_task\',\'sec_scan_result\',\n               \'sec_review_task\',\'sec_policy\',\'sec_access_grant\',\'sec_masking_policy\',\'sec_key_reference\',\n               \'sec_encryption_task\',\'sec_watermark_policy\',\'sec_watermark_task\']\nif (!allowed.contains(recordType)) { exit 400, \'不支持的数据安全记录类型\' }\n\nvar actor = StpUtil.isLogin() ? \'\' + StpUtil.getLoginId() : \'system\'\nreturn db.transaction(() => {\n    var changed = db.table(recordType).where().eq(\'tenant_id\', tenantId).eq(\'tid\', recordId).eq(\'is_del\', 1).update({is_del: 0})\n    if (changed == 0) { exit 400, \'记录不存在或不属于当前租户\' }\n    db.table(\'sec_operation_log\').primary(\'tid\').insert({\n        tid: UUID.randomUUID().toString().replace(\'-\', \'\'), tenant_id: tenantId,\n        record_type: recordType, record_id: recordId, action_code: \'RESTORE\',\n        outcome: \'SUCCESS\', detail_summary: \'已恢复记录\', operator_id: actor\n    })\n    return true\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/05.恢复安全台账.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_history_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_history_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "06.安全审计历史",\n  "path": "/records/history",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "查询当前租户单条安全台账的审计历史。"\n}\n================================\n// 接口：安全审计历史\n// 业务说明：根据记录标识读取当前租户的安全操作日志，按发生时间倒序展示。\nimport tenantRuntime\n\nvar tenantId = tenantRuntime.id()\nvar recordId = body?.recordId == null ? \'\' : (\'\' + body.recordId).trim()\nif (recordId == \'\') { exit 400, \'记录标识不能为空\' }\n\n// 历史记录按租户和记录标识共同限定，不能从客户端指定其他租户。\nvar items = db.select("""\n    SELECT tid,\n           record_type,\n           record_id,\n           action_code,\n           outcome,\n           detail_summary,\n           operator_id,\n           created_time\n      FROM sec_operation_log\n     WHERE tenant_id = #{tenantId}\n       AND record_id = #{recordId}\n     ORDER BY created_time DESC\n""")\nreturn {tenantId: tenantId, items: items}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/06.安全审计历史.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_action_01',NULL,'api','{\n  "properties": {},\n  "id": "dwm_security_action_01",\n  "script": null,\n  "groupId": "dwm_security_group_01",\n  "name": "07.安全受控操作",\n  "path": "/actions/execute",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "description": "执行受控安全工作流。"\n}\n================================\n// 接口：安全受控操作\n// 业务说明：只允许四种已登记的安全状态推进；更新与审计在同一事务中完成，不调用外部执行器。\nimport tenantRuntime\nimport cn.dev33.satoken.stp.StpUtil\nimport java.util.UUID\n\nvar tenantId = tenantRuntime.id()\nvar action = body?.action == null ? \'\' : (\'\' + body.action).trim().toUpperCase()\nvar recordId = body?.recordId == null ? \'\' : (\'\' + body.recordId).trim()\nif (action == \'\') { exit 400, \'操作类型不能为空\' }\nif (recordId == \'\') { exit 400, \'记录标识不能为空\' }\n\n// 操作对应的表、状态列和新状态均由服务端白名单决定。\nvar transitions = {\n    SEC_SCAN_VALIDATE: {table:\'sec_scan_task\', column:\'task_status\', state:\'READY\', audit:\'SCAN_PREFLIGHT\', detail:\'已完成配置预检，等待外部扫描执行器接入\'},\n    SEC_REVIEW_APPROVE: {table:\'sec_review_task\', column:\'review_status\', state:\'APPROVED\', audit:\'REVIEW_APPROVE\', detail:\'人工复核已通过\'},\n    SEC_ENCRYPTION_APPROVE: {table:\'sec_encryption_task\', column:\'task_status\', state:\'APPROVED\', audit:\'ENCRYPTION_APPROVE\', detail:\'加解密申请已批准，等待密钥服务执行\'},\n    SEC_WATERMARK_APPROVE: {table:\'sec_watermark_task\', column:\'task_status\', state:\'APPROVED\', audit:\'WATERMARK_APPROVE\', detail:\'水印申请已批准，等待水印服务执行\'}\n}\nvar selected = transitions[action]\nif (selected == null) { exit 400, \'不支持的数据安全操作\' }\nvar actor = StpUtil.isLogin() ? \'\' + StpUtil.getLoginId() : \'system\'\n\nreturn db.transaction(() => {\n    var changed = db.update(\'UPDATE \' + selected.table + \' SET \' + selected.column + \' = #{selected.state} WHERE tenant_id = #{tenantId} AND tid = #{recordId} AND is_del = 0\')\n    if (changed == 0) { exit 400, \'任务不存在或不属于当前租户\' }\n    db.table(\'sec_operation_log\').primary(\'tid\').insert({\n        tid: UUID.randomUUID().toString().replace(\'-\', \'\'), tenant_id: tenantId,\n        record_type: selected.table, record_id: recordId, action_code: selected.audit,\n        outcome: \'SUCCESS\', detail_summary: selected.detail, operator_id: actor\n    })\n    return db.table(selected.table).where().eq(\'tenant_id\', tenantId).eq(\'tid\', recordId).eq(\'is_del\', 0).selectOne()\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/07.安全受控操作.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_security_group_01',NULL,NULL,'{"properties":{},"id":"dwm_security_group_01","name":"04.数据安全","type":"api","parentId":"4fb5fbaf61b24db1a05ea12ae38437b1","path":"/security","paths":[],"options":[]}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/04.数据安全/group.json');
