INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('66cbe5cb30e2a02622788ee3c769b738',NULL,'api','{\n  "properties": {},\n  "id": "dwm_metadata_governance_catalog_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "01.已采集元数据目录",\n  "createTime": null,\n  "updateTime": 1790644820849,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/catalog",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "只读当前租户已采集的表、字段与逻辑关系；不探查源库，不返回连接凭据；涉及 db_datasource_t、db_table_t、db_table_column_t、dwm_metadata_relation_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.已采集元数据目录\n// 路由：POST /dwm/metadata-governance/catalog\n// 业务说明：只读当前租户已采集的表、字段与逻辑关系；不探查源库，不返回连接凭据；涉及 db_datasource_t、db_table_t、db_table_column_t、dwm_metadata_relation_t 等业务表。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n// Read-only shared projection. Authoritative tables: db_datasource_t,\n// db_table_t, db_table_column_t and dwm_metadata_relation_t. No source DB probes.\nvar sources = db.select("""\n select d.tid,d.db_name,coalesce(nullif(d.db_type,\'\'),d.database_type) as db_type,\n        d.is_enable,d.app_id,d.org_id,d.storage_domain,d.connection_status,d.updated_time\n from db_datasource_t d where d.tenant_id=#{tenantId} and d.is_del=0 order by d.db_name,d.tid\n""")\nvar tables = db.select("""\n select t.tid,t.datasource_id,t.table_name,t.table_name_cn,t.table_comment,t.table_type,\n        t.field_count,t.record_count,t.annotated,t.updated_time\n from db_table_t t join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n where t.tenant_id=#{tenantId} and t.is_del=0 order by t.table_name,t.tid\n""")\nvar columns = db.select("""\n select c.tid,c.table_id,c.column_name,c.column_comment,c.data_type,c.column_type,c.length,\n        c.nullable,c.primary_key,c.is_unique,c.indexed,c.ordinal_position,c.updated_time\n from db_table_column_t c\n join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n where c.tenant_id=#{tenantId} and c.is_del=0 order by c.table_id,c.ordinal_position,c.tid\n""")\nvar relations = db.select("""\n select r.*\n from dwm_metadata_relation_t r\n join db_table_t st on st.tid=r.source_table_id and st.tenant_id=#{tenantId} and st.is_del=0\n join db_table_column_t sc on sc.tid=r.source_column_id and sc.table_id=st.tid and sc.tenant_id=#{tenantId} and sc.is_del=0\n join db_table_t tt on tt.tid=r.target_table_id and tt.tenant_id=#{tenantId} and tt.is_del=0\n join db_table_column_t tc on tc.tid=r.target_column_id and tc.table_id=tt.tid and tc.tenant_id=#{tenantId} and tc.is_del=0\n where r.tenant_id=#{tenantId} and r.is_del=0 order by r.updated_time desc,r.tid\n""")\nreturn {sources:sources,tables:tables,columns:columns,relations:relations}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/01.已采集元数据目录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('17622f2008b87514827ab84be6f847ec',NULL,'api','{\n  "properties": {},\n  "id": "dwm_metadata_governance_discover_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "02.发现结构关系",\n  "createTime": null,\n  "updateTime": 1790614324337,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/discover",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "只读取当前租户已采集的表、字段和主键/唯一键快照，按名称与类型生成候选逻辑关系，不读取业务行或写入物理外键。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：发现结构关系\n// 业务说明：只读取当前租户已采集的表、字段和主键/唯一键快照，按名称与类型生成候选逻辑关系，不读取业务行或写入物理外键。\nimport tenantRuntime\nimport metadataGovernance\n\nvar tenantId = tenantRuntime.id()\n// 未指定 tableIds 时检查当前租户的已采集表；结构匹配和候选去重由复用的发现器完成。\nreturn metadataGovernance.discover(body == null ? {} : body)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/02.发现结构关系.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f0cc6fe477a76af96e31a1e36bfe906a',NULL,'api','{\n  "properties": {},\n  "id": "dwm_metadata_governance_save_relation_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "03.保存逻辑关系",\n  "createTime": null,\n  "updateTime": 1790614324411,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验当前租户的表、字段映射及条件，新增或按版本修改 ER 逻辑关系；已建立物理外键时不允许悄悄改映射。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：保存逻辑关系\n// 业务说明：校验当前租户的表、字段映射及条件，新增或按版本修改 ER 逻辑关系；已建立物理外键时不允许悄悄改映射。\n// 此接口只修改租户库中的关系台账，不执行源数据库 DDL。\nimport tenantRuntime\nimport metadataGovernance\nimport cn.hutool.json.JSONUtil\nimport java.util.UUID\n\nvar tenantId = tenantRuntime.id()\nvar sourceTableId = body?.sourceTableId == null ? \'\' : (\'\' + body.sourceTableId).trim()\nvar targetTableId = body?.targetTableId == null ? \'\' : (\'\' + body.targetTableId).trim()\nif (sourceTableId == \'\' || targetTableId == \'\') { exit 400, \'请选择来源数据表和目标数据表\' }\n\n// 字段映射和条件校验同时供物理外键预检查复用，检查每个字段都属于本租户对应的表。\nvar definition = metadataGovernance.prepareDefinition(body)\nvar mappings = definition.mappings\nvar sourceColumnId = mappings[0].sourceColumnId\nvar targetColumnId = mappings[0].targetColumnId\nvar definitionJson = JSONUtil.toJsonStr(definition)\n\nvar relationId = body?.tid == null ? \'\' : (\'\' + body.tid).trim()\nvar name = body?.relationName == null || (\'\' + body.relationName).trim() == \'\' ? \'逻辑关联\' : (\'\' + body.relationName).trim()\nvar type = body?.relationType == null ? \'REFERENCE\' : (\'\' + body.relationType).trim().toUpperCase()\nvar origin = body?.origin == null ? \'MANUAL\' : (\'\' + body.origin).trim().toUpperCase()\nvar status = body?.status == null ? \'CONFIRMED\' : (\'\' + body.status).trim().toUpperCase()\nif (![\'REFERENCE\',\'JOIN\'].contains(type) || ![\'MANUAL\',\'INFERENCE\'].contains(origin)\n    || ![\'CONFIRMED\',\'SUGGESTED\',\'REJECTED\',\'ARCHIVED\'].contains(status)) {\n    exit 400, \'关系类型、来源或状态不正确\'\n}\nif (name.length() > 160) { exit 400, \'关系名称过长\' }\nvar description = body?.description == null ? null : (\'\' + body.description).trim()\nif (description == \'\') { description = null }\nif (description != null && description.length() > 2000) { exit 400, \'业务说明最多 2000 字符\' }\nif (type == \'JOIN\' && description == null) { exit 400, \'一般连接关系必须填写业务说明\' }\nvar confidence = body?.confidence == null ? 0 : body.confidence::int\nif (confidence < 0) { confidence = 0 }\nif (confidence > 100) { confidence = 100 }\n\nreturn db.transaction(() => {\n    if (relationId == \'\') {\n        relationId = UUID.randomUUID().toString().replace(\'-\', \'\')\n        db.insert("""\n            INSERT INTO dwm_metadata_relation_t\n                (tid, tenant_id, source_table_id, source_column_id,\n                 target_table_id, target_column_id, relation_name, relation_type,\n                 relation_origin, relation_status, confidence, description,\n                 created_time, updated_time, is_del, definition_json, version_no)\n            VALUES\n                (#{relationId}, #{tenantId}, #{sourceTableId}, #{sourceColumnId},\n                 #{targetTableId}, #{targetColumnId}, #{name}, #{type},\n                 #{origin}, #{status}, #{confidence}, #{description},\n                 NOW(6), NOW(6), 0, #{definitionJson}, 1)\n        """)\n    } else {\n        // 锁住现有版本；一旦映射已经生成物理外键，就只能先撤销约束再另建逻辑关系。\n        var before = db.selectOne("""\n            SELECT version_no, definition_json, physical_fk_json, validation_json\n              FROM dwm_metadata_relation_t\n             WHERE tenant_id = #{tenantId} AND tid = #{relationId} AND is_del = 0\n             FOR UPDATE\n        """)\n        if (before == null) { exit 404, \'关系不存在或无权访问\' }\n        var version = before.versionNo::long\n        if (body?.expectedVersion != null && body.expectedVersion::long != version) {\n            exit 409, \'关系已被其他操作更新，请刷新后重试\'\n        }\n        var previousDefinition = before.definitionJson == null ? {} : JSONUtil.parseObj(before.definitionJson)\n        var sameDefinition = previousDefinition.equals(JSONUtil.parseObj(definitionJson))\n        var hasPhysicalKey = before.physicalFkJson != null && (\'\' + before.physicalFkJson).trim() != \'\'\n            && !JSONUtil.parseObj(before.physicalFkJson).isEmpty()\n        if (!sameDefinition && hasPhysicalKey) {\n            exit 409, \'此关系已创建物理外键；请先撤销该约束，再新建不同映射的逻辑关系\'\n        }\n        var validationJson = sameDefinition ? before.validationJson : null\n        var changed = db.update("""\n            UPDATE dwm_metadata_relation_t\n               SET source_table_id = #{sourceTableId},\n                   source_column_id = #{sourceColumnId},\n                   target_table_id = #{targetTableId},\n                   target_column_id = #{targetColumnId},\n                   relation_name = #{name}, relation_type = #{type},\n                   relation_origin = #{origin}, relation_status = #{status},\n                   confidence = #{confidence}, description = #{description},\n                   definition_json = #{definitionJson}, validation_json = #{validationJson},\n                   updated_time = NOW(6), version_no = version_no + 1\n             WHERE tenant_id = #{tenantId} AND tid = #{relationId}\n               AND is_del = 0 AND version_no = #{version}\n        """)\n        if (changed != 1) { exit 409, \'关系不存在或已被其他操作更新\' }\n    }\n\n    // 保持原接口返回结构，附上两侧表和字段名称供页面直接展示。\n    return db.selectOne("""\n        SELECT r.*,\n               st.table_name AS source_table_name,\n               sc.column_name AS source_column_name,\n               tt.table_name AS target_table_name,\n               tc.column_name AS target_column_name\n          FROM dwm_metadata_relation_t r\n          JOIN db_table_t st ON st.tid = r.source_table_id AND st.tenant_id = r.tenant_id AND st.is_del = 0\n          JOIN db_table_column_t sc ON sc.tid = r.source_column_id AND sc.table_id = st.tid\n                                    AND sc.tenant_id = r.tenant_id AND sc.is_del = 0\n          JOIN db_table_t tt ON tt.tid = r.target_table_id AND tt.tenant_id = r.tenant_id AND tt.is_del = 0\n          JOIN db_table_column_t tc ON tc.tid = r.target_column_id AND tc.table_id = tt.tid\n                                    AND tc.tenant_id = r.tenant_id AND tc.is_del = 0\n         WHERE r.tenant_id = #{tenantId} AND r.tid = #{relationId} AND r.is_del = 0\n    """)\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/03.保存逻辑关系.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('68e82553351c53b7f23196a97f4c313a',NULL,'api','{\n  "properties": {},\n  "id": "dwm_metadata_governance_delete_relation_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "04.删除逻辑关系",\n  "createTime": null,\n  "updateTime": 1790614324471,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "逻辑删除当前租户的 ER 关系记录。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：删除逻辑关系\n// 业务说明：只对当前登录租户的指定逻辑关系执行软删除；不存在或已删除时返回 false。\nimport tenantRuntime\n\n// 先核验关系标识，再从会话读取业务租户标识。\nvar relationId = body?.tid == null ? \'\' : (\'\' + body.tid).trim()\nif (relationId == \'\') { exit 400, \'关系ID不能为空\' }\nvar tenantId = tenantRuntime.id()\n\n// 只更新逻辑关系台账，不触碰源数据库的物理外键。\nvar affected = db.update("""\n    UPDATE dwm_metadata_relation_t\n       SET is_del = 1,\n           updated_time = NOW(6)\n     WHERE tenant_id = #{tenantId}\n       AND tid = #{relationId}\n       AND is_del = 0\n""")\nreturn affected > 0\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/04.删除逻辑关系.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_validate_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "05.验证关系数据",\n  "createTime": 1790635184974,\n  "updateTime": 1790644822906,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/validate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据当前租户关系定义执行受限的跨源键验证，将汇总证据按版本保存到关系台账；不返回源端业务行。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：验证逻辑关系的数据\n// 业务说明：根据当前租户关系定义执行受限的跨源键验证，将汇总证据按版本保存到关系台账；不返回源端业务行。\nimport tenantRuntime\nimport metadataGovernance\n\nvar tenantId = tenantRuntime.id()\nif (body?.tid == null || (\'\' + body.tid).trim() == \'\') { exit 400, \'关系标识不能为空\' }\n\n// JDBC 验证器处理不同数据库驱动和采样上限；保存证据时强制版本检查。\nreturn metadataGovernance.validateRelation(body)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/05.验证关系数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('16e92260bed2fe7c456549d46485d568',NULL,'api','{"properties":{},"id":"dwm_lineage_objects_01","script":null,"groupId":"dwm_lineage_analysis_group_01","name":"01.搜索血缘对象","path":"/objects","method":"POST","parameters":[],"options":[],"requestBody":null,"headers":[],"paths":[],"description":"搜索当前租户已登记的数据表、字段和模型；只接受规范对象 ID。"}\n================================\nimport tenantRuntime\nimport lineageAnalysis\nvar tenantId = tenantRuntime.id()\nreturn lineageAnalysis.objects(body)',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/01.搜索血缘对象.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5eee8e0507cb13c671e80c73231e4480',NULL,'api','{"properties":{},"id":"dwm_lineage_analyze_01","script":null,"groupId":"dwm_lineage_analysis_group_01","name":"02.分析全链归因影响","path":"/analyze","method":"POST","parameters":[],"options":[],"requestBody":null,"headers":[],"paths":[],"description":"按照全链、归因或影响模式遍历当前租户的设计或部署依赖；无运行事实冒用。"}\n================================\nimport tenantRuntime\nimport lineageAnalysis\nvar tenantId = tenantRuntime.id()\nreturn lineageAnalysis.analyze(body)',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/02.分析全链归因影响.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3f918ace5ddb29422479907694a867dd',NULL,'api','{"properties":{},"id":"dwm_lineage_evidence_01","script":null,"groupId":"dwm_lineage_analysis_group_01","name":"03.查看关系依据","path":"/evidence","method":"POST","parameters":[],"options":[],"requestBody":null,"headers":[],"paths":[],"description":"按关系 ID 查看明确的源、目标、任务和字段规则依据。"}\n================================\nimport tenantRuntime\nimport lineageAnalysis\nvar tenantId = tenantRuntime.id()\nreturn lineageAnalysis.evidence(body)',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/03.查看关系依据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c9af71c7e66478f6c4af4a1150fc7d4f',NULL,'api','{"properties":{},"id":"dwm_lineage_coverage_01","script":null,"groupId":"dwm_lineage_analysis_group_01","name":"04.查看血缘覆盖","path":"/coverage","method":"POST","parameters":[],"options":[],"requestBody":null,"headers":[],"paths":[],"description":"统计当前租户可分析的元数据和有依据的设计、部署依赖。"}\n================================\nimport tenantRuntime\nimport lineageAnalysis\nvar tenantId = tenantRuntime.id()\nreturn lineageAnalysis.coverage()',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/04.查看血缘覆盖.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dwm_lineage_analysis_group_01',NULL,NULL,'{"properties":{},"id":"dwm_lineage_analysis_group_01","name":"06.血缘分析","type":"api","parentId":"dwm_metadata_governance_group_01","path":"/lineage","paths":[],"options":[]}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.血缘分析/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_fk_preview_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "06.预检查物理外键",\n  "createTime": 1790635185084,\n  "updateTime": 1790644824492,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/foreign-key/preview",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "只读检查目标键、字段类型和数据库能力，生成外键 DDL、撤销 SQL 与确认摘要，不修改源库结构。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：预检查物理外键\n// 业务说明：只读检查目标键、字段类型和数据库能力，生成外键 DDL、撤销 SQL 与确认摘要，不修改源库结构。\nimport tenantRuntime\nimport metadataGovernance\n\nvar tenantId = tenantRuntime.id()\nif (body?.tid == null || (\'\' + body.tid).trim() == \'\') { exit 400, \'关系标识不能为空\' }\n\n// 物理数据库、驱动和索引检查由跨源适配器完成，预览结果供人工确认。\nreturn metadataGovernance.previewForeignKey(body)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/06.预检查物理外键.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_fk_create_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "07.创建物理外键",\n  "createTime": 1790635185171,\n  "updateTime": 1790644826249,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/relations/foreign-key/create",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "仅在明确确认且预览摘要匹配时，对源数据库执行已预览的外键 DDL，并按版本记录结果；不自动创建目标索引。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：创建物理外键\n// 业务说明：仅在明确确认且预览摘要匹配时，对源数据库执行已预览的外键 DDL，并按版本记录结果；不自动创建目标索引。\nimport tenantRuntime\nimport metadataGovernance\n\nvar tenantId = tenantRuntime.id()\nif (body?.tid == null || (\'\' + body.tid).trim() == \'\') { exit 400, \'关系标识不能为空\' }\nif (body?.confirmPhysicalChange != true) { exit 400, \'必须明确确认源数据库结构变更\' }\nif (body?.previewHash == null || (\'\' + body.previewHash).trim() == \'\') {\n    exit 400, \'请先预览物理外键\'\n}\n\n// DDL 不能像普通台账事务一样安全回滚；执行器强制再核对预览哈希并记录结果。\nreturn metadataGovernance.createForeignKey(body)\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/07.创建物理外键.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_bindings_list_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "08.字段对标引用清单",\n  "createTime": 1790635185255,\n  "updateTime": 1790644827184,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/bindings/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取共享技术字段上的质量规则/字段参照；不复制质量规则，不执行质检；涉及 dq_quality_task_rule_t、dq_quality_task_t、db_table_t、db_table_column_t、db_datasource_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.字段对标引用清单\n// 路由：POST /dwm/metadata-governance/bindings/list\n// 业务说明：读取共享技术字段上的质量规则/字段参照；不复制质量规则，不执行质检；涉及 dq_quality_task_rule_t、dq_quality_task_t、db_table_t、db_table_column_t、db_datasource_t 等业务表。\n// Read only: owned field references and existing configured task rules.\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nvar rules = db.select("""\n select r.tid as id,r.rule_name,r.column_name,r.rule_type,r.enabled,q.tid as task_id,q.task_name,q.table_id\n from dq_quality_task_rule_t r\n join dq_quality_task_t q on q.tid=r.task_id and q.tenant_id=#{tenantId} and q.is_del=0\n join db_table_t t on t.tid=q.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n where r.tenant_id=#{tenantId} and r.is_del=0\n""")\nvar columns = db.select("""\n select c.tid,c.table_id,c.quality_rule_id,c.reference_column_id,c.metadata_binding_version,\n   case when q.tid is not null and q.table_id=c.table_id and r.column_name=c.column_name and r.enabled=1 then r.tid else null end as valid_rule,\n   case when rd.tid is not null then rc.tid else null end as valid_reference\n from db_table_column_t c\n join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n left join dq_quality_task_rule_t r on r.tid=c.quality_rule_id and r.tenant_id=#{tenantId} and r.is_del=0\n left join dq_quality_task_t q on q.tid=r.task_id and q.tenant_id=#{tenantId} and q.is_del=0\n left join db_table_column_t rc on rc.tid=c.reference_column_id and rc.tenant_id=#{tenantId} and rc.is_del=0\n left join db_table_t rt on rt.tid=rc.table_id and rt.tenant_id=#{tenantId} and rt.is_del=0\n left join db_datasource_t rd on rd.tid=rt.datasource_id and rd.tenant_id=#{tenantId} and rd.is_del=0\n where c.tenant_id=#{tenantId} and c.is_del=0 and (c.quality_rule_id is not null or c.reference_column_id is not null)\n""")\nvar items = []\nfor (c in columns) {\n if (c.qualityRuleId != null && c.qualityRuleId != \'\') { items.add({id:c.tid+\':QUALITY\',entity_id:c.tableId,field_id:c.tid,mapping_mode:\'QUALITY\',target_id:c.qualityRuleId,version:c.metadataBindingVersion,status:c.validRule != null ? \'CONFIRMED\' : \'STALE\'}) }\n if (c.referenceColumnId != null && c.referenceColumnId != \'\') { items.add({id:c.tid+\':REFERENCE\',entity_id:c.tableId,field_id:c.tid,mapping_mode:\'REFERENCE\',target_id:c.referenceColumnId,version:c.metadataBindingVersion,status:c.validReference != null ? \'CONFIRMED\' : \'STALE\'}) }\n}\nreturn {items:items,rules:rules}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/08.字段对标引用清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_bindings_save_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "09.保存字段对标引用",\n  "createTime": 1790635185343,\n  "updateTime": 1790644828641,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/bindings/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "更新共享字段的 quality_rule_id/reference_column_id，校验租户、目标和并发版本；支持 dryRun；使用请求参数 tableId、columnId、mode、targetId、expectedTargetId、dryRun；涉及 db_table_column_t、db_datasource_t、db_table_t、dq_quality_task_rule_t、dq_quality_task_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.保存字段对标引用\n// 路由：POST /dwm/metadata-governance/bindings/save\n// 业务说明：更新共享字段的 quality_rule_id/reference_column_id，校验租户、目标和并发版本；支持 dryRun；使用请求参数 tableId、columnId、mode、targetId、expectedTargetId、dryRun；涉及 db_table_column_t、db_datasource_t、db_table_t、dq_quality_task_rule_t、dq_quality_task_t 等业务表。\n// Explicit field-reference write only. Does not create a rule or mutate business records.\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\nvar tableId = body?.tableId\nvar columnId = body?.columnId\nvar mode = body?.mode\nvar targetId = body?.targetId\nif (targetId != null) { targetId=(targetId+\'\').trim(); if (targetId==\'\') { targetId=null } }\nif (tableId==null || columnId==null || (mode!=\'QUALITY\' && mode!=\'REFERENCE\')) { exit 400,\'请选择字段和有效对标类型\' }\nreturn db.transaction(() => {\n// Serialize reference edits within the active tenant: two simultaneous A->B,\n// B->A writes must not both pass a snapshot-only cycle check. This locks only\n// owned source rows, not business records or other tenants\' catalogs.\nif (mode==\'REFERENCE\') {\n db.select(\'select tid from db_datasource_t where tenant_id=#{tenantId} and is_del=0 order by tid for update\')\n}\nvar c=db.selectOne("""\n select c.tid,c.column_name,c.quality_rule_id,c.reference_column_id,c.metadata_binding_version\n from db_table_column_t c join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n where c.tenant_id=#{tenantId} and c.tid=#{columnId} and c.table_id=#{tableId} and c.is_del=0\n""")\nif (c==null) { exit 404,\'字段不存在或不属于当前租户\' }\nvar expected=body?.expectedTargetId==null ? \'\' : (body.expectedTargetId+\'\').trim()\nvar current=mode==\'QUALITY\' ? c.qualityRuleId : c.referenceColumnId\ncurrent=current==null ? \'\' : (current+\'\').trim()\nif (current!=expected) { exit 409,\'此类型的对标引用已变更，请刷新重试\' }\nif (targetId!=null && mode==\'QUALITY\') {\n var r=db.selectOne("""\n select r.tid from dq_quality_task_rule_t r\n join dq_quality_task_t q on q.tid=r.task_id and q.tenant_id=#{tenantId} and q.is_del=0 and q.table_id=#{tableId}\n where r.tenant_id=#{tenantId} and r.tid=#{targetId} and r.is_del=0 and r.enabled=1 and r.column_name=#{c.columnName}\n """)\n if (r==null) { exit 400,\'只能绑定当前表、当前字段已有且启用的质检任务规则，请先在质检任务中配置规则\' }\n}\nif (targetId!=null && mode==\'REFERENCE\') {\n if (targetId==columnId) { exit 400,\'不能参照自身字段\' }\n var target=db.selectOne("""\n select rc.tid from db_table_column_t rc\n join db_table_t rt on rt.tid=rc.table_id and rt.tenant_id=#{tenantId} and rt.is_del=0\n join db_datasource_t rd on rd.tid=rt.datasource_id and rd.tenant_id=#{tenantId} and rd.is_del=0\n where rc.tenant_id=#{tenantId} and rc.tid=#{targetId} and rc.is_del=0\n """)\n if (target==null) { exit 404,\'参照字段不存在或不属于当前租户\' }\n // References must remain acyclic. A bounded walk fails closed on historical corrupt chains.\n var visited=[columnId]\n var next=targetId\n var depth=0\n while (next!=null && next!=\'\') {\n  if (visited.contains(next)) { exit 400,\'此参照会产生字段引用循环\' }\n  if (depth>=128) { exit 400,\'参照链过深，请先整理字段参照\' }\n  visited.add(next);depth=depth+1\n  var ref=db.table(\'db_table_column_t\').where().eq(\'tid\',next).eq(\'tenant_id\',tenantId).eq(\'is_del\',0).selectOne()\n  next=ref?.referenceColumnId\n }\n}\nvar version=c.metadataBindingVersion\nif (body?.dryRun==true) { return {valid:true,dryRun:true,version:version} }\nvar affected=0\nif (mode==\'QUALITY\') { affected=db.update(\'update db_table_column_t set quality_rule_id=#{targetId},metadata_binding_version=metadata_binding_version+1,updated_time=current_timestamp(6) where tenant_id=#{tenantId} and tid=#{columnId} and is_del=0 and metadata_binding_version=#{version}\') }\nelse { affected=db.update(\'update db_table_column_t set reference_column_id=#{targetId},metadata_binding_version=metadata_binding_version+1,updated_time=current_timestamp(6) where tenant_id=#{tenantId} and tid=#{columnId} and is_del=0 and metadata_binding_version=#{version}\') }\nif (affected==0) { exit 409,\'字段对标保存冲突，请刷新重试\' }\nreturn {saved:true,columnId:columnId,mode:mode,targetId:targetId,version:version+1}\n})\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/09.保存字段对标引用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "dwm_metadata_governance_summary_01",\n  "script": null,\n  "groupId": "dwm_metadata_governance_group_01",\n  "name": "10.治理总览统计",\n  "createTime": 1790644834214,\n  "updateTime": 1790907208399,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/summary",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "只读聚合当前租户数据源、实体、数据元和有效标准覆盖率；首屏不传输完整表字段目录；涉及 db_datasource_t、db_table_t、da_metadata_t、db_table_column_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.治理总览统计\n// 路由：POST /dwm/metadata-governance/summary\n// 业务说明：只读聚合当前租户数据源、实体、数据元和有效标准覆盖率；首屏不传输完整表字段目录；涉及 db_datasource_t、db_table_t、da_metadata_t、db_table_column_t 等业务表。\nimport tenantRuntime\nvar tenantId = tenantRuntime.id()\n// Read-only shared-table aggregation. No datasource probe or business-row read.\nvar sources = db.selectInt("select count(*) from db_datasource_t where tenant_id=#{tenantId} and is_del=0")\nvar entities = db.selectInt("""\n select count(*) from db_table_t t\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n where t.tenant_id=#{tenantId} and t.is_del=0\n""")\nvar standards = db.selectInt("select count(*) from da_metadata_t where tenant_id=#{tenantId} and is_del=0")\nvar fields = db.selectOne("""\n select count(*) as total_fields,\n coalesce(sum(case when m.is_del=0 and m.publish_status=1 then 1 else 0 end),0) as mapped_fields,\n coalesce(round(sum(case when m.is_del=0 and m.publish_status=1 then 1 else 0 end) * 100.0 / nullif(count(*),0),2),0) as coverage\n from db_table_column_t c\n join db_table_t t on t.tid=c.table_id and t.tenant_id=#{tenantId} and t.is_del=0\n join db_datasource_t d on d.tid=t.datasource_id and d.tenant_id=#{tenantId} and d.is_del=0\n left join da_metadata_t m on m.tid=c.data_standard_id and m.tenant_id=#{tenantId}\n where c.tenant_id=#{tenantId} and c.is_del=0\n""")\nreturn {sources:sources,entities:entities,standards:standards,coverage:{totalFields:fields.totalFields,mappedFields:fields.mappedFields,coverage:fields.coverage}}\n',NULL,NULL,0,NULL,'/magic-api/api/05.数据治理/05.元数据治理/10.治理总览统计.ms');
