INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('034139b7e1590d1beeb7bd62c66f57b8',NULL,NULL,'{\n  "properties": {},\n  "id": "034139b7e1590d1beeb7bd62c66f57b8",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "01.下线流程",\n  "createTime": 1784826967773,\n  "updateTime": 1784826967773,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/offline",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "注销已发布 Magic 路由并更新流程状态。示例：POST /dws/flowserve/flows/fl_demo/offline；涉及 fs_flow、fs_flow_version、fs_publish_record 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.下线流程\n// 路由：POST /dws/flowserve/flows/{id}/offline\n// 业务说明：注销已发布 Magic 路由并更新流程状态。示例：POST /dws/flowserve/flows/fl_demo/offline；涉及 fs_flow、fs_flow_version、fs_publish_record 等业务表。\n// 下线流程：处理 POST /flows/{id}/offline 的核心写入或状态变更逻辑。\nimport flowRuntime\nvar record = db.selectOne("""\nselect magic_resource_id resource_id\nfrom fs_publish_record\nwhere flow_id=#{id}\n    and status=\'published\'\norder by publish_time desc\nlimit 1\n""")\nif (record != null) { flowRuntime.undeploy(record.resourceId,{localNode:true}) }\ndb.table(\'fs_flow\').where().eq(\'id\',id).update({status:\'offline\',updated_at:new Date()})\ndb.table(\'fs_flow_version\').where().eq(\'flow_id\',id).eq(\'status\',\'published\').update({status:\'offline\'})\ndb.table(\'fs_publish_record\').where().eq(\'flow_id\',id).eq(\'status\',\'published\').update({status:\'offline\'})\nreturn {status:\'offline\'}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/01.下线流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ece7387ad85acf642ec762600aad847d',NULL,NULL,'{\n  "properties": {},\n  "id": "ece7387ad85acf642ec762600aad847d",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "02.保存流程",\n  "createTime": 1784826967486,\n  "updateTime": 1784826967486,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}",\n  "method": "PUT",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"flow\\":{\\"flowId\\":\\"fl_demo\\",\\"name\\":\\"订单查询\\"},\\"lockVersion\\":1}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "使用乐观锁保存设计器 DSL。请求示例：{\\"flow\\":{\\"flowId\\":\\"fl_demo\\"},\\"lockVersion\\":1}；涉及 fs_flow 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.保存流程\n// 路由：PUT /dws/flowserve/flows/{id}\n// 业务说明：使用乐观锁保存设计器 DSL。请求示例：{"flow":{"flowId":"fl_demo"},"lockVersion":1}；涉及 fs_flow 等业务表。\nimport jsons\nif (body == null || body.flow == null) { exit 400, \'flow 不能为空\' }\nvar flow = body.flow\n// lock_version 防止多人同时编辑时相互覆盖。\nvar updated = db.table(\'fs_flow\').where().eq(\'id\',id).eq(\'deleted\',0)\n  .eq(\'lock_version\',body.lockVersion)\n  .update({name:flow.name,flow_group:flow.group,dsl:jsons.toJSONStr(flow),\n           lock_version:body.lockVersion+1,updated_at:new Date()})\nif (updated == 0) { exit 409, \'保存失败：版本冲突，请刷新后重试\' }\nreturn {lockVersion:body.lockVersion+1}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/02.保存流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d50275ba88c6ec91747f783379ccaada',NULL,NULL,'{\n  "properties": {},\n  "id": "d50275ba88c6ec91747f783379ccaada",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "03.删除流程",\n  "createTime": 1784826967524,\n  "updateTime": 1784826967524,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}",\n  "method": "DELETE",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "软删除流程并下线已发布服务。示例：DELETE /dws/flowserve/flows/fl_demo；涉及 fs_flow、fs_publish_record 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.删除流程\n// 路由：DELETE /dws/flowserve/flows/{id}\n// 业务说明：软删除流程并下线已发布服务。示例：DELETE /dws/flowserve/flows/fl_demo；涉及 fs_flow、fs_publish_record 等业务表。\n// 删除流程：处理 DELETE /flows/{id} 的核心写入或状态变更逻辑。\nimport flowRuntime\nvar record = db.selectOne("""\nselect magic_resource_id as resource_id\nfrom fs_publish_record\nwhere flow_id=#{id}\n    and status=\'published\'\norder by publish_time desc\nlimit 1\n""")\nif (record != null) { flowRuntime.undeploy(record.resourceId,{localNode:true}) }\ndb.table(\'fs_flow\').where().eq(\'id\',id).update({deleted:1,status:\'deleted\',updated_at:new Date()})\ndb.table(\'fs_publish_record\').where().eq(\'flow_id\',id).update({status:\'deleted\'})\nreturn {ok:true}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/03.删除流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0436eed8163f5ff0aa263f0cec1da6cb',NULL,NULL,'{\n  "properties": {},\n  "id": "0436eed8163f5ff0aa263f0cec1da6cb",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "04.发布流程",\n  "createTime": 1784826967681,\n  "updateTime": 1784826967681,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/publish",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"remark\\":\\"首次发布\\",\\"targetNodeId\\":\\"local_magic_api\\",\\"script\\":\\"return {ok:true}\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "创建版本并发布脚本到选定运行节点。请求示例含 remark、targetNodeId、script；涉及 fs_flow、fs_runtime_node、fs_flow_version、fs_publish_record 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.发布流程\n// 路由：POST /dws/flowserve/flows/{id}/publish\n// 业务说明：创建版本并发布脚本到选定运行节点。请求示例含 remark、targetNodeId、script；涉及 fs_flow、fs_runtime_node、fs_flow_version、fs_publish_record 等业务表。\nimport flowRuntime\nimport jsons\nvar flowRow = db.table(\'fs_flow\').where().eq(\'id\',id).eq(\'deleted\',0).selectOne()\nif (flowRow == null) { exit 404, \'流程不存在\' }\nvar flow = jsons.toJSONObject(flowRow.dsl)\nvar script = body == null ? null : body.script\nif (script == null || script.trim() == \'\') { exit 400, \'发布脚本不能为空\' }\nvar node = body == null || body.targetNodeId == null\n  ? db.table(\'fs_runtime_node\').where().eq(\'default_node\',1).eq(\'enabled\',1).selectOne()\n  : db.table(\'fs_runtime_node\').where().eq(\'id\',body.targetNodeId).eq(\'enabled\',1).selectOne()\nif (node == null) { exit 400, \'未配置可用的运行节点\' }\nvar nextVersion = db.selectInt("""\nselect coalesce(max(version), 0)+1\nfrom fs_flow_version\nwhere flow_id=#{id}\n""")\nvar deployed = flowRuntime.deploy(id,flow,script,node)\n// 先成功部署，再落版本与发布记录，避免数据库显示已发布但路由不存在。\ndb.table(\'fs_flow_version\').insert({flow_id:id,version:nextVersion,dsl:jsons.toJSONStr(flow),\n  script:script,meta:\'{}\',publisher:\'flowserve\',remark:body.remark,status:\'published\'})\ndb.table(\'fs_flow\').where().eq(\'id\',id).update({status:\'published\',current_version:nextVersion,updated_at:new Date()})\ndb.table(\'fs_publish_record\').where().eq(\'flow_id\',id).eq(\'status\',\'published\').update({status:\'offline\'})\ndb.table(\'fs_publish_record\').insert({flow_id:id,version:nextVersion,runtime_node_id:node.id,\n  magic_resource_id:deployed.resourceId,url:deployed.url,status:\'published\'})\nreturn {version:nextVersion,url:deployed.url,status:\'published\',\n  runtimeNodeId:node.id,runtimeNodeName:node.name}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/04.发布流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1c698cf2c43db55cad6c2b2a0d0ec740',NULL,NULL,'{\n  "properties": {},\n  "id": "1c698cf2c43db55cad6c2b2a0d0ec740",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "05.回滚流程版本",\n  "createTime": 1784826967742,\n  "updateTime": 1784826967742,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/rollback",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"version\\":1}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "将指定历史版本恢复为当前草稿。请求示例：{\\"version\\":1}；涉及 fs_flow_version、fs_flow 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.回滚流程版本\n// 路由：POST /dws/flowserve/flows/{id}/rollback\n// 业务说明：将指定历史版本恢复为当前草稿。请求示例：{"version":1}；涉及 fs_flow_version、fs_flow 等业务表；执行数据库写入并返回处理结果。\n// 回滚流程版本：处理 POST /flows/{id}/rollback 的核心写入或状态变更逻辑。\nvar version = db.table(\'fs_flow_version\').where().eq(\'flow_id\',id).eq(\'version\',body.version).selectOne()\nif (version == null) { exit 404, \'版本不存在\' }\nvar current = db.table(\'fs_flow\').where().eq(\'id\',id).selectOne()\ndb.table(\'fs_flow\').where().eq(\'id\',id).update({dsl:version.dsl,current_version:body.version,\n  status:\'draft\',lock_version:current.lockVersion+1,updated_at:new Date()})\nreturn {lockVersion:current.lockVersion+1,status:\'draft\'}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/05.回滚流程版本.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('428694dbe01d733ddc0b6415a6d6835b',NULL,NULL,'{\n  "properties": {},\n  "id": "428694dbe01d733ddc0b6415a6d6835b",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "06.复制流程",\n  "createTime": 1784826967578,\n  "updateTime": 1784826967578,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/copy",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "复制现有流程为独立草稿。示例：POST /dws/flowserve/flows/fl_demo/copy；涉及 fs_flow 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.复制流程\n// 路由：POST /dws/flowserve/flows/{id}/copy\n// 业务说明：复制现有流程为独立草稿。示例：POST /dws/flowserve/flows/fl_demo/copy；涉及 fs_flow 等业务表；执行数据库写入并返回处理结果。\n// 复制流程：处理 POST /flows/{id}/copy 的核心写入或状态变更逻辑。\nimport flowDataSource\nimport jsons\nvar source = db.table(\'fs_flow\').where().eq(\'id\',id).eq(\'deleted\',0).selectOne()\nif (source == null) { exit 404, \'流程不存在\' }\nvar newId = flowDataSource.newId(\'fl\')\nvar flow = jsons.toJSONObject(source.dsl)\nflow.flowId = newId\nflow.name = flow.name + \' 副本\'\nflow.version = 1\ndb.table(\'fs_flow\').insert({id:newId,name:flow.name,flow_group:flow.group,status:\'draft\',\n  current_version:1,dsl:jsons.toJSONStr(flow),lock_version:1,deleted:0})\nreturn {flow:flow,status:\'draft\',lockVersion:1,updatedAt:new Date()+\'\'}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/06.复制流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f29f06100b6dc0101d5b591b362457f7',NULL,NULL,'{\n  "properties": {},\n  "id": "f29f06100b6dc0101d5b591b362457f7",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "07.新建流程",\n  "createTime": 1784826967425,\n  "updateTime": 1784826967425,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"name\\":\\"订单查询服务\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "新建可直接进入设计器编辑的流程草稿。请求示例：{\\"name\\":\\"订单查询服务\\"}；涉及 fs_flow 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.新建流程\n// 路由：POST /dws/flowserve/flows\n// 业务说明：新建可直接进入设计器编辑的流程草稿。请求示例：{"name":"订单查询服务"}；涉及 fs_flow 等业务表；执行数据库写入并返回处理结果。\nimport flowDataSource\nimport jsons\nvar flowId = flowDataSource.newId(\'fl\')\nvar triggerId = flowDataSource.newId(\'node\')\nvar responseId = flowDataSource.newId(\'node\')\nvar flowName = body == null || body.name == null || body.name == \'\' ? \'新建编排\' : body.name\n// 创建与设计器 DSL 完全兼容的最小触发器—响应流程。\nvar flow = {\n  flowId:flowId,name:flowName,description:\'\',version:1,group:\'默认分组\',\n  nodes:[\n    {id:triggerId,type:\'trigger\',name:\'API 触发器\',position:{x:80,y:200},\n     data:{method:\'GET\',path:\'/api/\'+flowId,group:\'默认分组\',\n           auth:{required:false,roles:[]},request:{query:[],path:[],header:[],body:null}}},\n    {id:responseId,type:\'response\',name:\'响应\',position:{x:520,y:200},\n     data:{mode:\'wrap\',source:\'\',wrap:true,statusCode:200}}\n  ],\n  edges:[{id:flowDataSource.newId(\'e\'),source:triggerId,target:responseId,sourcePort:\'out\',targetPort:\'in\'}],\n  settings:{timeoutMs:10000,transactional:false,errorStrategy:\'fail-fast\'}\n}\ndb.table(\'fs_flow\').insert({id:flowId,name:flowName,flow_group:\'默认分组\',status:\'draft\',\n  current_version:1,dsl:jsons.toJSONStr(flow),lock_version:1,deleted:0})\nreturn {flow:flow,status:\'draft\',lockVersion:1,updatedAt:new Date()+\'\'}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/07.新建流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5c95aa066571db36b089e44f948a9924',NULL,NULL,'{\n  "properties": {},\n  "id": "5c95aa066571db36b089e44f948a9924",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "08.查询流程列表",\n  "createTime": 1784826967365,\n  "updateTime": 1784826967365,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询全部未删除的数据服务编排及调用次数。示例：GET /dws/flowserve/flows。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.查询流程列表\n// 路由：GET /dws/flowserve/flows\n// 业务说明：查询全部未删除的数据服务编排及调用次数。示例：GET /dws/flowserve/flows。\n// 查询流程基础信息，并按调用日志聚合调用次数。\nvar rows = db.select("""\nselect f.id as flow_id, f.name, f.flow_group as \'group\', f.status, f.current_version as version,\n       date_format(f.updated_at, \'%Y-%m-%d %H:%i:%s\') as updated_at, coalesce(c.calls,\n        0) as calls\nfrom fs_flow f\nleft join\n    (select flow_id,count(*) calls\n     from fs_call_log\n     group by flow_id) c on c.flow_id=f.id\nwhere f.deleted=0\norder by f.updated_at desc\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/08.查询流程列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2532fe8d7e1cf618d32ab62d8512d4f6',NULL,NULL,'{\n  "properties": {},\n  "id": "2532fe8d7e1cf618d32ab62d8512d4f6",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "09.查询流程版本",\n  "createTime": 1784826967713,\n  "updateTime": 1784826967713,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/versions",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询发布版本、脚本和 DSL。示例：GET /dws/flowserve/flows/fl_demo/versions。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.查询流程版本\n// 路由：GET /dws/flowserve/flows/{id}/versions\n// 业务说明：查询发布版本、脚本和 DSL。示例：GET /dws/flowserve/flows/fl_demo/versions。\n// 查询流程版本：处理 GET /flows/{id}/versions 的核心查询和组装返回数据逻辑。\nimport jsons\nvar rows = db.select("""\nselect version,dsl,script,meta,date_format(publish_time,\n        \'%Y-%m-%d %H:%i:%s\') publish_time, remark,status\nfrom fs_flow_version\nwhere flow_id=#{id}\norder by version desc\n""")\nfor (row in rows) {\n  row.dsl = jsons.toJSONObject(row.dsl)\n  row.meta = row.meta == null || row.meta == \'\' ? {} : jsons.toJSONObject(row.meta)\n}\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/09.查询流程版本.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4137b68ac199eff6d7eda7c84e447a50',NULL,NULL,'{\n  "properties": {},\n  "id": "4137b68ac199eff6d7eda7c84e447a50",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "10.查询流程详情",\n  "createTime": 1784826967456,\n  "updateTime": 1784826967456,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按流程编号读取设计器 DSL。示例：GET /dws/flowserve/flows/fl_demo；涉及 fs_flow 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.查询流程详情\n// 路由：GET /dws/flowserve/flows/{id}\n// 业务说明：按流程编号读取设计器 DSL。示例：GET /dws/flowserve/flows/fl_demo；涉及 fs_flow 等业务表。\n// 查询流程详情：处理 GET /flows/{id} 的核心查询和组装返回数据逻辑。\nimport jsons\nvar row = db.table(\'fs_flow\').where().eq(\'id\',id).eq(\'deleted\',0).selectOne()\nif (row == null) { exit 404, \'流程不存在\' }\nvar flow = jsons.toJSONObject(row.dsl)\nreturn {flow:flow,status:row.status,\n  lockVersion:row.lockVersion,updatedAt:row.updatedAt+\'\'}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/10.查询流程详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0c053297830b26c02f91d85f678914d5',NULL,NULL,'{\n  "properties": {},\n  "id": "0c053297830b26c02f91d85f678914d5",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "11.校验编译结果",\n  "createTime": 1784826967609,\n  "updateTime": 1784826967609,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/compile",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"flow\\":{\\"flowId\\":\\"fl_demo\\"},\\"script\\":\\"return {ok:true}\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "接收前端编译器生成的 Magic 脚本并返回校验结果。请求示例：{\\"script\\":\\"return {}\\",\\"flow\\":{}}。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.校验编译结果\n// 路由：POST /dws/flowserve/flows/{id}/compile\n// 业务说明：接收前端编译器生成的 Magic 脚本并返回校验结果。请求示例：{"script":"return {}","flow":{}}。\n// 校验编译结果：处理 POST /flows/{id}/compile 的核心查询和组装返回数据逻辑。\nvar script = body == null ? null : body.script\nif (script == null || script.trim() == \'\') {\n  return {ok:false,script:\'\',errors:[{message:\'编译脚本不能为空\'}],warnings:[],meta:{}}\n}\nreturn {ok:true,script:script,errors:[],warnings:[],meta:{}}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/11.校验编译结果.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4c2f0f135762a126d404b61a2110f69f',NULL,NULL,'{\n  "properties": {},\n  "id": "4c2f0f135762a126d404b61a2110f69f",\n  "script": null,\n  "groupId": "962e0e1e86609a165de79f1eb5294c2f",\n  "name": "12.调试执行流程",\n  "createTime": 1784826967644,\n  "updateTime": 1784826967644,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/flows/{id}/debug",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"flow\\":{\\"flowId\\":\\"fl_demo\\",\\"nodes\\":[]},\\"script\\":\\"return {ok:true}\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "临时注册并执行前端编译的 Magic 脚本，执行结束立即注销。请求示例含 flow 与 script。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：12.调试执行流程\n// 路由：POST /dws/flowserve/flows/{id}/debug\n// 业务说明：临时注册并执行前端编译的 Magic 脚本，执行结束立即注销。请求示例含 flow 与 script。\nimport flowRuntime\nvar result = flowRuntime.debug(body.flow,body.script)\n// 转换为云梯前端既有的调试结果字段。\nreturn {\n  success:result.ok,totalMs:result.durationMs,trace:result.trace,\n  response:result.response,error:result.error\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/01.流程管理/12.调试执行流程.ms');
