INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a7231e129cab9ec4567e78167ae977bc',NULL,NULL,'{\n  "properties": {},\n  "id": "a7231e129cab9ec4567e78167ae977bc",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "01.修改编排数据源",\n  "createTime": 1784826967869,\n  "updateTime": 1784826967869,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources/{id}",\n  "method": "PUT",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"name\\":\\"order_db\\",\\"type\\":\\"jdbc\\",\\"config\\":{\\"url\\":\\"jdbc:mysql://127.0.0.1:3306/demo\\",\\"username\\":\\"root\\",\\"password\\":\\"******\\"}}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "修改配置并刷新具名运行时数据源。请求示例与新增接口一致；使用请求参数 config、name、type；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.修改编排数据源\n// 路由：PUT /dws/flowserve/datasources/{id}\n// 业务说明：修改配置并刷新具名运行时数据源。请求示例与新增接口一致；使用请求参数 config、name、type；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。\n// 修改编排数据源：处理 PUT /datasources/{id} 的核心写入或状态变更逻辑。\nimport flowDataSource\nvar old = db.table(\'fs_datasource\').where().eq(\'id\',id).selectOne()\nif (old == null) { exit 404, \'数据源不存在\' }\nvar configJson = flowDataSource.mergeConfig(id,body.config)\ndb.table(\'fs_datasource\').where().eq(\'id\',id).update({name:body.name,type:body.type,config:configJson})\nif (old.name != body.name) { flowDataSource.unregister(old.name) }\nflowDataSource.register(body.name,body.type,configJson)\nvar saved = db.table(\'fs_datasource\').where().eq(\'id\',id).selectOne()\nsaved.config = flowDataSource.maskedConfig(saved.config)\nsaved.createdAt = saved.createdAt+\'\'\nreturn saved\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/01.修改编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6d9943c58a59d9245e57bfab82653c2d',NULL,NULL,'{\n  "properties": {},\n  "id": "6d9943c58a59d9245e57bfab82653c2d",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "02.删除编排数据源",\n  "createTime": 1784826967899,\n  "updateTime": 1784826967899,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources/{id}",\n  "method": "DELETE",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "删除业务数据源并注销运行时连接。示例：DELETE /dws/flowserve/datasources/ds_demo；涉及 fs_datasource 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.删除编排数据源\n// 路由：DELETE /dws/flowserve/datasources/{id}\n// 业务说明：删除业务数据源并注销运行时连接。示例：DELETE /dws/flowserve/datasources/ds_demo；涉及 fs_datasource 等业务表。\n// 删除编排数据源：处理 DELETE /datasources/{id} 的核心写入或状态变更逻辑。\nimport flowDataSource\nvar old = db.table(\'fs_datasource\').where().eq(\'id\',id).selectOne()\nif (old != null) { flowDataSource.unregister(old.name) }\ndb.table(\'fs_datasource\').where().eq(\'id\',id).delete()\nreturn {ok:true}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/02.删除编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('94faaf01bd5af5e349fb1a8903db447f',NULL,NULL,'{\n  "properties": {},\n  "id": "94faaf01bd5af5e349fb1a8903db447f",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "03.复制编排数据源",\n  "createTime": 1784826967933,\n  "updateTime": 1784826967933,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources/{id}/clone",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "复制数据源配置为新记录。示例：POST /dws/flowserve/datasources/ds_demo/clone；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.复制编排数据源\n// 路由：POST /dws/flowserve/datasources/{id}/clone\n// 业务说明：复制数据源配置为新记录。示例：POST /dws/flowserve/datasources/ds_demo/clone；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。\n// 复制编排数据源：处理 POST /datasources/{id}/clone 的核心写入或状态变更逻辑。\nimport flowDataSource\nvar source = db.table(\'fs_datasource\').where().eq(\'id\',id).selectOne()\nif (source == null) { exit 404, \'数据源不存在\' }\nvar newId = flowDataSource.newId(\'ds\')\nvar newName = source.name + \'_copy\'\ndb.table(\'fs_datasource\').insert({id:newId,name:newName,type:source.type,config:source.config,created_by:\'flowserve\'})\nvar saved = db.table(\'fs_datasource\').where().eq(\'id\',newId).selectOne()\nsaved.config = flowDataSource.maskedConfig(saved.config)\nsaved.createdAt = saved.createdAt+\'\'\nreturn saved\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/03.复制编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ef8ea881acfd14f2171a3cd2e50c1b87',NULL,NULL,'{\n  "properties": {},\n  "id": "ef8ea881acfd14f2171a3cd2e50c1b87",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "04.新增编排数据源",\n  "createTime": 1784826967837,\n  "updateTime": 1784826967837,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"name\\":\\"order_db\\",\\"type\\":\\"jdbc\\",\\"config\\":{\\"url\\":\\"jdbc:mysql://127.0.0.1:3306/demo\\",\\"username\\":\\"root\\",\\"password\\":\\"123456\\"}}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "新增并注册运行时数据源。请求示例：{\\"name\\":\\"order_db\\",\\"type\\":\\"jdbc\\",\\"config\\":{\\"url\\":\\"jdbc:mysql://127.0.0.1:3306/demo\\",\\"username\\":\\"root\\",\\"password\\":\\"***\\"}}；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.新增编排数据源\n// 路由：POST /dws/flowserve/datasources\n// 业务说明：新增并注册运行时数据源。请求示例：{"name":"order_db","type":"jdbc","config":{"url":"jdbc:mysql://127.0.0.1:3306/demo","username":"root","password":"***"}}；涉及 fs_datasource 等业务表；执行数据库写入并返回处理结果。\n// 新增编排数据源：处理 POST /datasources 的核心写入或状态变更逻辑。\nimport flowDataSource\nvar newId = flowDataSource.newId(\'ds\')\nvar configJson = flowDataSource.encryptConfig(body.config)\ndb.table(\'fs_datasource\').insert({id:newId,name:body.name,type:body.type,config:configJson,created_by:\'flowserve\'})\nflowDataSource.register(body.name,body.type,body.config)\nvar saved = db.table(\'fs_datasource\').where().eq(\'id\',newId).selectOne()\nsaved.config = flowDataSource.maskedConfig(saved.config)\nsaved.createdAt = saved.createdAt+\'\'\nreturn saved\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/04.新增编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f64eca6665d34a38b3f67fb1d7cf2703',NULL,NULL,'{\n  "properties": {},\n  "id": "f64eca6665d34a38b3f67fb1d7cf2703",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "05.查询编排数据源",\n  "createTime": 1784826967806,\n  "updateTime": 1784826967806,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询云梯编排可使用的数据源，敏感配置统一掩码。示例：GET /dws/flowserve/datasources。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.查询编排数据源\n// 路由：GET /dws/flowserve/datasources\n// 业务说明：查询云梯编排可使用的数据源，敏感配置统一掩码。示例：GET /dws/flowserve/datasources。\n// 查询编排数据源：处理 GET /datasources 的核心查询和组装返回数据逻辑。\nimport flowDataSource\nvar rows = db.select("""\nselect id,name,type,config,date_format(created_at, \'%Y-%m-%d %H:%i:%s\') created_at\nfrom fs_datasource\norder by created_at desc\n""")\nfor (row in rows) { row.config = flowDataSource.maskedConfig(row.config) }\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/05.查询编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6e2238e0fe8046b0b24420282879c43a',NULL,NULL,'{\n  "properties": {},\n  "id": "6e2238e0fe8046b0b24420282879c43a",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "06.测试编排数据源",\n  "createTime": 1784826967966,\n  "updateTime": 1784826967966,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources/test",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"type\\":\\"jdbc\\",\\"config\\":{\\"url\\":\\"jdbc:mysql://127.0.0.1:3306/demo\\",\\"username\\":\\"root\\",\\"password\\":\\"123456\\"}}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "测试 JDBC、Kafka、ES、HTTP、Redis 连接。请求示例：{\\"type\\":\\"jdbc\\",\\"config\\":{\\"url\\":\\"jdbc:mysql://127.0.0.1:3306/demo\\",\\"username\\":\\"root\\",\\"password\\":\\"123456\\"}}。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.测试编排数据源\n// 路由：POST /dws/flowserve/datasources/test\n// 业务说明：测试 JDBC、Kafka、ES、HTTP、Redis 连接。请求示例：{"type":"jdbc","config":{"url":"jdbc:mysql://127.0.0.1:3306/demo","username":"root","password":"123456"}}。\n// 测试编排数据源：处理 POST /datasources/test 的核心查询和组装返回数据逻辑。\nimport flowDataSource\nreturn flowDataSource.test(body.type,body.config)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/06.测试编排数据源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ea9f4aee04564b8d97c8daa3d4b8522c',NULL,NULL,'{\n  "properties": {},\n  "id": "ea9f4aee04564b8d97c8daa3d4b8522c",\n  "script": null,\n  "groupId": "ac4cd10ea9538c94e502352f188a6fe7",\n  "name": "07.读取编排数据源元数据",\n  "createTime": 1784826968000,\n  "updateTime": 1784826968000,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/datasources/{id}/meta",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取 JDBC 数据源真实表和字段元数据。示例：GET /dws/flowserve/datasources/ds_demo/meta；涉及 fs_datasource 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.读取编排数据源元数据\n// 路由：GET /dws/flowserve/datasources/{id}/meta\n// 业务说明：读取 JDBC 数据源真实表和字段元数据。示例：GET /dws/flowserve/datasources/ds_demo/meta；涉及 fs_datasource 等业务表。\n// 读取编排数据源元数据：处理 GET /datasources/{id}/meta 的核心查询和组装返回数据逻辑。\nimport flowDataSource\nvar source = db.table(\'fs_datasource\').where().eq(\'id\',id).selectOne()\nif (source == null) { exit 404, \'数据源不存在\' }\nreturn flowDataSource.metadata(source.name)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/07.读取编排数据源元数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ac4cd10ea9538c94e502352f188a6fe7',NULL,NULL,'{\n  "properties" : { },\n  "id" : "ac4cd10ea9538c94e502352f188a6fe7",\n  "name" : "02.数据源管理",\n  "type" : "api",\n  "parentId" : "5d290a9b3bca3b2dd9ffd715dc47ce56",\n  "path" : "",\n  "createTime" : 1784828418421,\n  "updateTime" : 1784828418421,\n  "createBy" : null,\n  "updateBy" : null,\n  "paths" : [ ],\n  "options" : [ ]\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/02.数据源管理/group.json');
