INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c34565c33645efce10c7a339e70510cf',NULL,NULL,'{\n  "properties": {},\n  "id": "c34565c33645efce10c7a339e70510cf",\n  "script": null,\n  "groupId": "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name": "01.修改运行节点",\n  "createTime": 1784826968098,\n  "updateTime": 1784826968098,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/runtime-nodes/{id}",\n  "method": "PUT",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"name\\":\\"本机节点\\",\\"businessDomain\\":\\"平台数据服务\\",\\"serviceType\\":\\"Magic API\\",\\"baseUrl\\":\\"http://127.0.0.1:8088\\",\\"localNode\\":true,\\"defaultNode\\":true,\\"enabled\\":true}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "修改 Magic 运行节点；空令牌保留原值。请求示例同新增接口；使用请求参数 defaultNode、name、businessDomain、serviceType、baseUrl、managementUrl、localNode、enabled；涉及 fs_runtime_node 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.修改运行节点\n// 路由：PUT /dws/flowserve/runtime-nodes/{id}\n// 业务说明：修改 Magic 运行节点；空令牌保留原值。请求示例同新增接口；使用请求参数 defaultNode、name、businessDomain、serviceType、baseUrl、managementUrl、localNode、enabled；涉及 fs_runtime_node 等业务表；执行数据库写入并返回处理结果。\n// 修改运行节点：处理 PUT /runtime-nodes/{id} 的核心写入或状态变更逻辑。\nif (body.defaultNode == true) { db.table(\'fs_runtime_node\').where().ne(\'id\',id).update({default_node:0}) }\nvar patch = {name:body.name,business_domain:body.businessDomain,service_type:body.serviceType,\n  base_url:body.baseUrl,management_url:body.managementUrl,local_node:body.localNode?1:0,\n  default_node:body.defaultNode?1:0,enabled:body.enabled==false?0:1}\nif (body.deployToken != null && body.deployToken != \'\') { patch.deploy_token=body.deployToken }\ndb.table(\'fs_runtime_node\').where().eq(\'id\',id).update(patch)\nbody = null\nvar row = db.selectOne("""\nselect id,name,business_domain business_domain,service_type service_type, base_url base_url,\n       management_url management_url, case when deploy_token is null\n        or deploy_token=\'\' then false else true\n        end deploy_token_set,\n       local_node local_node,default_node default_node,enabled,created_at created_at\nfrom fs_runtime_node\nwhere id=#{id}\n""")\nreturn row\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/01.修改运行节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b31185413cb1bcf42cb51da20061da7c',NULL,NULL,'{\n  "properties": {},\n  "id": "b31185413cb1bcf42cb51da20061da7c",\n  "script": null,\n  "groupId": "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name": "02.删除运行节点",\n  "createTime": 1784826968131,\n  "updateTime": 1784826968131,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/runtime-nodes/{id}",\n  "method": "DELETE",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "删除非本机运行节点。示例：DELETE /dws/flowserve/runtime-nodes/rt_demo；涉及 fs_runtime_node 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.删除运行节点\n// 路由：DELETE /dws/flowserve/runtime-nodes/{id}\n// 业务说明：删除非本机运行节点。示例：DELETE /dws/flowserve/runtime-nodes/rt_demo；涉及 fs_runtime_node 等业务表。\n// 删除运行节点：处理 DELETE /runtime-nodes/{id} 的核心写入或状态变更逻辑。\ndb.table(\'fs_runtime_node\').where().eq(\'id\',id).eq(\'local_node\',0).delete()\nreturn {ok:true}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/02.删除运行节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b7602a392da7cabbe42a90e4783a5f0c',NULL,NULL,'{\n  "properties": {},\n  "id": "b7602a392da7cabbe42a90e4783a5f0c",\n  "script": null,\n  "groupId": "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name": "03.新增运行节点",\n  "createTime": 1784826968066,\n  "updateTime": 1784826968066,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/runtime-nodes",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"name\\":\\"本机节点\\",\\"businessDomain\\":\\"平台数据服务\\",\\"serviceType\\":\\"Magic API\\",\\"baseUrl\\":\\"http://127.0.0.1:8088\\",\\"localNode\\":true,\\"defaultNode\\":true,\\"enabled\\":true}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "新增 Magic 运行节点。请求示例包含 name、baseUrl、managementUrl；涉及 fs_runtime_node 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.新增运行节点\n// 路由：POST /dws/flowserve/runtime-nodes\n// 业务说明：新增 Magic 运行节点。请求示例包含 name、baseUrl、managementUrl；涉及 fs_runtime_node 等业务表；执行数据库写入并返回处理结果。\n// 新增运行节点：处理 POST /runtime-nodes 的核心写入或状态变更逻辑。\nimport flowDataSource\nvar newId = flowDataSource.newId(\'rt\')\nif (body.defaultNode == true) { db.table(\'fs_runtime_node\').update({default_node:0}) }\ndb.table(\'fs_runtime_node\').insert({id:newId,name:body.name,business_domain:body.businessDomain,\n  service_type:body.serviceType,base_url:body.baseUrl,management_url:body.managementUrl,\n  deploy_token:body.deployToken,local_node:body.localNode?1:0,default_node:body.defaultNode?1:0,\n  enabled:body.enabled==false?0:1})\nbody = null\nvar row = db.selectOne("""\nselect id,name,business_domain business_domain,service_type service_type, base_url base_url,\n       management_url management_url, case when deploy_token is null\n        or deploy_token=\'\' then false else true\n        end deploy_token_set,\n       local_node local_node,default_node default_node,enabled,created_at created_at\nfrom fs_runtime_node\nwhere id=#{newId}\n""")\nreturn row\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/03.新增运行节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ac00197306be80d43fe508fe80d2d232',NULL,NULL,'{\n  "properties": {},\n  "id": "ac00197306be80d43fe508fe80d2d232",\n  "script": null,\n  "groupId": "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name": "04.查询运行节点",\n  "createTime": 1784826968034,\n  "updateTime": 1784826968034,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/runtime-nodes",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询本机及远程 Magic 运行节点。示例：GET /dws/flowserve/runtime-nodes。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.查询运行节点\n// 路由：GET /dws/flowserve/runtime-nodes\n// 业务说明：查询本机及远程 Magic 运行节点。示例：GET /dws/flowserve/runtime-nodes。\n// 查询运行节点：处理 GET /runtime-nodes 的核心查询和组装返回数据逻辑。\nvar rows = db.select("""\nselect id,name,business_domain business_domain,service_type service_type, base_url base_url,\n       management_url management_url, case when deploy_token is null\n        or deploy_token=\'\' then false else true\n        end deploy_token_set,\n       local_node local_node,default_node default_node,enabled, date_format(created_at,\n        \'%Y-%m-%d %H:%i:%s\') created_at\nfrom fs_runtime_node\norder by default_node desc,created_at desc\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/04.查询运行节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1af61950c8a97d6bd1c7ffe510184de0',NULL,NULL,'{\n  "properties": {},\n  "id": "1af61950c8a97d6bd1c7ffe510184de0",\n  "script": null,\n  "groupId": "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name": "05.检查运行节点",\n  "createTime": 1784826968163,\n  "updateTime": 1784826968163,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/runtime-nodes/{id}/health",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "检查本机或远程 Magic 节点健康状态。示例：GET /dws/flowserve/runtime-nodes/local_magic_api/health；涉及 fs_runtime_node 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.检查运行节点\n// 路由：GET /dws/flowserve/runtime-nodes/{id}/health\n// 业务说明：检查本机或远程 Magic 节点健康状态。示例：GET /dws/flowserve/runtime-nodes/local_magic_api/health；涉及 fs_runtime_node 等业务表。\n// 检查运行节点：处理 GET /runtime-nodes/{id}/health 的核心查询和组装返回数据逻辑。\nimport flowRuntime\nvar node = db.table(\'fs_runtime_node\').where().eq(\'id\',id).selectOne()\nif (node == null) { exit 404, \'运行节点不存在\' }\nvar result = flowRuntime.health(node)\nreturn {nodeId:result.nodeId,ok:result.ok,\n  statusCode:result.status,latencyMs:result.latencyMs,message:result.message}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/05.检查运行节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9243108b5fe0f78c8fe28aac46f7ebf3',NULL,NULL,'{\n  "properties" : { },\n  "id" : "9243108b5fe0f78c8fe28aac46f7ebf3",\n  "name" : "03.发布节点",\n  "type" : "api",\n  "parentId" : "5d290a9b3bca3b2dd9ffd715dc47ce56",\n  "path" : "",\n  "createTime" : 1784828418421,\n  "updateTime" : 1784828418421,\n  "createBy" : null,\n  "updateBy" : null,\n  "paths" : [ ],\n  "options" : [ ]\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/03.发布节点/group.json');
