INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('51600e0fb05fc4067ae3be75bc5d1a73',NULL,NULL,'{\n  "properties": {},\n  "id": "51600e0fb05fc4067ae3be75bc5d1a73",\n  "script": null,\n  "groupId": "252018678f71bd2962b4ed7e5c2b6b56",\n  "name": "01.启停告警规则",\n  "createTime": 1784826968306,\n  "updateTime": 1784826968306,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/monitor/alert-rules/{id}/enabled",\n  "method": "PUT",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"enabled\\":true}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "启用或停用指定告警规则。请求示例：{\\"enabled\\":true}；涉及 fs_alert_rule 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.启停告警规则\n// 路由：PUT /dws/flowserve/monitor/alert-rules/{id}/enabled\n// 业务说明：启用或停用指定告警规则。请求示例：{"enabled":true}；涉及 fs_alert_rule 等业务表；执行数据库写入并返回处理结果。\n// 启停告警规则：处理 PUT /monitor/alert-rules/{id}/enabled 的核心写入或状态变更逻辑。\ndb.table(\'fs_alert_rule\').where().eq(\'id\',id).update({enabled:body.enabled?1:0})\nvar row = db.selectOne("""\nselect id,name,metric,\noperator,threshold_value threshold_value, duration_minutes duration_minutes,\n       notify_target notify_target,enabled,created_at created_at\nfrom fs_alert_rule\nwhere id=#{id}\n""")\nreturn row\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/01.启停告警规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7deb41d78fe4d9a46457fe2a5b4a33ac',NULL,NULL,'{\n  "properties": {},\n  "id": "7deb41d78fe4d9a46457fe2a5b4a33ac",\n  "script": null,\n  "groupId": "252018678f71bd2962b4ed7e5c2b6b56",\n  "name": "02.查询告警事件",\n  "createTime": 1784826968370,\n  "updateTime": 1784826968370,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/monitor/alert-events",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询最近告警事件；limit 默认 50。示例：GET /dws/flowserve/monitor/alert-events?limit=50。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.查询告警事件\n// 路由：GET /dws/flowserve/monitor/alert-events\n// 业务说明：查询最近告警事件；limit 默认 50。示例：GET /dws/flowserve/monitor/alert-events?limit=50。\n// 查询告警事件：处理 GET /monitor/alert-events 的核心查询和组装返回数据逻辑。\nvar rowLimit = limit == null ? 50 : Math.min(200,Math.max(1,limit::int))\nvar rows = db.select("""\nselect id,rule_id rule_id,rule_name rule_name,metric, actual_value actual_value,\n       threshold_value threshold_value,message, notify_target notify_target,status,\n       date_format(triggered_at, \'%Y-%m-%d %H:%i:%s\') triggered_at\nfrom fs_alert_event\norder by triggered_at desc\nlimit #{rowLimit}\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/02.查询告警事件.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('18367b4d53bf1b20a94aa7b17255e18e',NULL,NULL,'{\n  "properties": {},\n  "id": "18367b4d53bf1b20a94aa7b17255e18e",\n  "script": null,\n  "groupId": "252018678f71bd2962b4ed7e5c2b6b56",\n  "name": "03.查询告警规则",\n  "createTime": 1784826968271,\n  "updateTime": 1784826968271,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/monitor/alert-rules",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询数据服务监控告警规则。示例：GET /dws/flowserve/monitor/alert-rules。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.查询告警规则\n// 路由：GET /dws/flowserve/monitor/alert-rules\n// 业务说明：查询数据服务监控告警规则。示例：GET /dws/flowserve/monitor/alert-rules。\n// 查询告警规则：处理 GET /monitor/alert-rules 的核心查询和组装返回数据逻辑。\nvar rows = db.select("""\nselect id,name,metric,\noperator,threshold_value threshold_value, duration_minutes duration_minutes,\n       notify_target notify_target,enabled, date_format(created_at,\n        \'%Y-%m-%d %H:%i:%s\') created_at\nfrom fs_alert_rule\norder by created_at desc\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/03.查询告警规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('750e867eccab5a73439927cd6ecd6019',NULL,NULL,'{\n  "properties": {},\n  "id": "750e867eccab5a73439927cd6ecd6019",\n  "script": null,\n  "groupId": "252018678f71bd2962b4ed7e5c2b6b56",\n  "name": "04.查询调用日志",\n  "createTime": 1784826968236,\n  "updateTime": 1784826968236,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/monitor/calls",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询最近调用日志；limit 默认 50。示例：GET /dws/flowserve/monitor/calls?limit=50。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.查询调用日志\n// 路由：GET /dws/flowserve/monitor/calls\n// 业务说明：查询最近调用日志；limit 默认 50。示例：GET /dws/flowserve/monitor/calls?limit=50。\n// 查询调用日志：处理 GET /monitor/calls 的核心查询和组装返回数据逻辑。\nvar rowLimit = limit == null ? 50 : Math.min(500,Math.max(1,limit::int))\nvar rows = db.select("""\nselect id,flow_id flow_id,service_name service_name,method,path,status, success,duration_ms duration_ms,\n       error_message error_message, date_format(created_at,\n        \'%Y-%m-%d %H:%i:%s\') created_at\nfrom fs_call_log\norder by created_at desc\nlimit #{rowLimit}\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/04.查询调用日志.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e76f4152440c795b286040a5ba3de0c6',NULL,NULL,'{\n  "properties": {},\n  "id": "e76f4152440c795b286040a5ba3de0c6",\n  "script": null,\n  "groupId": "252018678f71bd2962b4ed7e5c2b6b56",\n  "name": "05.查询运行总览",\n  "createTime": 1784826968202,\n  "updateTime": 1784826968202,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/monitor/overview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "统计服务、调用、数据源、近十二小时趋势和错误排行。示例：GET /dws/flowserve/monitor/overview。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.查询运行总览\n// 路由：GET /dws/flowserve/monitor/overview\n// 业务说明：统计服务、调用、数据源、近十二小时趋势和错误排行。示例：GET /dws/flowserve/monitor/overview。\n// 查询运行总览：处理 GET /monitor/overview 的核心查询和组装返回数据逻辑。\nvar since12Hours = new Date(new Date().getTime() - 12 * 60 * 60 * 1000)\nvar since24Hours = new Date(new Date().getTime() - 24 * 60 * 60 * 1000)\nvar serviceCount = db.selectInt("""\nselect count(*)\nfrom fs_flow\nwhere status=\'published\'\n    and deleted=0\n""")\nvar todayCalls = db.selectInt("""\nselect count(*)\nfrom fs_call_log\nwhere created_at>=curdate()\n""")\nvar activeDataSources = db.selectInt("""\nselect count(*)\nfrom fs_datasource\n""")\nvar series = db.select("""\nselect date_format(created_at, \'%Y-%m-%d %H:00:00\') ts, count(*) qps,coalesce(avg(duration_ms),\n        0) p95,coalesce(avg(success),\n        1) success,\n       sum(case when success=0 then 1 else 0\n           end) error\nfrom fs_call_log\nwhere created_at>=#{since12Hours}\ngroup by date_format(created_at, \'%Y-%m-%d %H:00:00\')\norder by ts\n""")\nvar errorTop = db.select("""\nselect coalesce(service_name, path) name,count(*) errors\nfrom fs_call_log\nwhere success=0\n    and created_at>=#{since24Hours}\ngroup by coalesce(service_name, path)\norder by errors desc\nlimit 10\n""")\nreturn {serviceCount:serviceCount,todayCalls:todayCalls,\n  activeDataSources:activeDataSources,errorTop:errorTop,series:series}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/05.查询运行总览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e6a6c819e1ea60c97feb5e4988d49bab',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "e6a6c819e1ea60c97feb5e4988d49bab",\r\n  "script" : null,\r\n  "groupId" : "252018678f71bd2962b4ed7e5c2b6b56",\r\n  "name" : "06.立即评估告警",\r\n  "createTime" : 1784826968340,\r\n  "updateTime" : 1791111417322,\r\n  "lock" : null,\r\n  "createBy" : "flowserve",\r\n  "updateBy" : null,\r\n  "path" : "/monitor/alert-rules/evaluate",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "立即按当前近五分钟错误率和最大延迟评估启用规则。示例：POST /dws/flowserve/monitor/alert-rules/evaluate；涉及 fs_alert_rule、fs_alert_event 等业务表；执行数据库写入并返回处理结果。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：06.立即评估告警\n// 路由：POST /dws/flowserve/monitor/alert-rules/evaluate\n// 业务说明：一次计算近五分钟的错误率和最大延迟，再评估当前租户全部启用规则。\nimport tenantRuntime\nimport java.util.Map\n\nvar tenantId = tenantRuntime.id()\nvar since5Minutes = new Date(new Date().getTime() - 5 * 60 * 1000)\nvar dryRun = body?.dryRun == true\nvar metricValue = (row, key) => {\n    if (row == null) { return 0 }\n    var value = row instanceof Map ? row.get(key) : row[key]\n    if (value == null) {\n        var upperKey = key.toUpperCase()\n        value = row instanceof Map ? row.get(upperKey) : row[upperKey]\n    }\n    return value == null ? 0 : value\n}\n\n// 规则数可变，但指标来自同一五分钟窗口：只执行一次聚合查询。\nvar metrics = db.selectOne("""\n    select case when count(*) = 0 then 0\n                else sum(case when success = 0 then 1 else 0 end) * 100.0 / count(*)\n           end as errorRate,\n           coalesce(max(duration_ms), 0) as maxDuration\n      from fs_call_log\n     where tenant_id = #{tenantId}\n       and created_at >= #{since5Minutes}\n""")\nvar errorRate = metricValue(metrics, \'errorRate\')\nvar maxDuration = metricValue(metrics, \'maxDuration\')\nvar rules = db.table(\'fs_alert_rule\').where().eq(\'tenant_id\', tenantId).eq(\'enabled\', 1).select()\nfor (rule in rules) {\n    var actual = rule.metric == \'errorRate\' ? errorRate : maxDuration\n    if (actual >= rule.thresholdValue && !dryRun) {\n        db.table(\'fs_alert_event\').insert({\n            tenant_id: tenantId,\n            rule_id: rule.id,\n            rule_name: rule.name,\n            metric: rule.metric,\n            actual_value: actual,\n            threshold_value: rule.thresholdValue,\n            message: rule.name + \' 当前值 \' + actual + \' 已达到阈值 \' + rule.thresholdValue,\n            notify_target: rule.notifyTarget,\n            status: \'triggered\'\n        })\n    }\n}\nreturn db.select("""\n    select id, rule_id rule_id, rule_name rule_name, metric, actual_value actual_value,\n           threshold_value threshold_value, message, notify_target notify_target, status,\n           date_format(triggered_at, \'%Y-%m-%d %H:%i:%s\') triggered_at\n      from fs_alert_event\n     where tenant_id = #{tenantId}\n     order by triggered_at desc\n     limit 20\n""")\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/04.运行监控/06.立即评估告警.ms');
