INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e7c9a88d31e9e0f8d123b1cefd8d17db',NULL,NULL,'{\n  "properties": {},\n  "id": "e7c9a88d31e9e0f8d123b1cefd8d17db",\n  "script": null,\n  "groupId": "c1b0007a981f09175abefdcb0770ca37",\n  "name": "01.查询编排审计日志",\n  "createTime": 1784826968402,\n  "updateTime": 1784826968402,\n  "createBy": "flowserve",\n  "updateBy": "flowserve",\n  "path": "/audit",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "查询云梯流程及数据源操作审计记录。示例：GET /dws/flowserve/audit。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.查询编排审计日志\n// 路由：GET /dws/flowserve/audit\n// 业务说明：查询云梯流程及数据源操作审计记录。示例：GET /dws/flowserve/audit。\n// 查询编排审计日志：处理 GET /audit 的核心查询和组装返回数据逻辑。\nvar rows = db.select("""\nselect id,action,target,detail,date_format(created_at,\n        \'%Y-%m-%d %H:%i:%s\') created_at\nfrom fs_audit_log\norder by created_at desc\nlimit 200\n""")\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/05.审计日志/01.查询编排审计日志.ms');
