INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('064c536fa0d240fc1dbbfee3f03808df','fl_dwzeilf50h',NULL,'{\n  "properties": {},\n  "id": "064c536fa0d240fc1dbbfee3f03808df",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "01.人员档案核验服务",\n  "createTime": 1781574552339,\n  "updateTime": 1781574552278,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/person/archive-check",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按人员编号核验基础身份、涉案关联、布控状态和风险标签，支撑执法核查调用。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.人员档案核验服务\n// 路由：GET /dws/flowserve/published/police/person/archive-check\n// 业务说明：按人员编号核验基础身份、涉案关联、布控状态和风险标签，支撑执法核查调用。\n// === 自动生成，请勿手改；flowId: fl_dwzeilf50h ===\n\nif (personNo == null) {\n    return response.json(400, { code: 400, message: \'personNo 不能为空\' });\n}\n\n// 节点: sql-query [sql_person] 查询人员档案库\nvar person = db.chengtian.selectOne("SELECT \'FZRY202607001\' personNo, \'霞浦县重点人员档案库\' ownerName, \'刺网\' personType, \'有效\' annualStatus, \'重点监管\' tag");\n\n// 节点: transform [map_person] 档案字段标准化\nvar archiveResult = person;\n\n// 节点: log [log_person] 记录档案核验日志\n// log.info: person archive checked\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: archiveResult };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/01.人员档案核验服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6f0c068c614dad26b88b20cc1b7c0246','fl_nbpxp19kbl',NULL,'{\n  "properties": {},\n  "id": "6f0c068c614dad26b88b20cc1b7c0246",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "02.应急指挥并行汇聚服务",\n  "createTime": 1781574562482,\n  "updateTime": 1781574562432,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/command/dashboard",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "并行汇聚警情、视频、警力和车辆资源，形成应急指挥态势看板。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.应急指挥并行汇聚服务\n// 路由：GET /dws/flowserve/published/police/command/dashboard\n// 业务说明：并行汇聚警情、视频、警力和车辆资源，形成应急指挥态势看板。\n// === 自动生成，请勿手改；flowId: fl_nbpxp19kbl ===\n\n\n// 节点: parallel [parallel_fetch] 并行汇聚指挥资源\nvar parallelResult = {};\ntry {\n// 节点: script [script_weather] 气象预警分支\nvar weather = { weatherLevel:\'yellow\', windScale:8 };\n\n// 节点: script [script_dashboard] 生成指挥看板\nvar dashboard = { weatherLevel:\'yellow\', personsOnline:3862, riskyPersons:27, patrolTeams:12, responseTeams:4, action:\'启动重点区域巡控\' };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: dashboard };\n\n  parallelResult[\'weather\'] = { ok: true };\n} catch(e) {\n  parallelResult[\'weather\'] = { ok: false, error: e };\n  throw e;\n}\ntry {\n// 节点: script [script_persons] 船位在线分支\nvar persons = { personsOnline:3862, riskyPersons:27 };\n\n// 节点: script [script_dashboard] 生成指挥看板\nvar dashboard = { weatherLevel:\'yellow\', personsOnline:3862, riskyPersons:27, patrolTeams:12, responseTeams:4, action:\'启动重点区域巡控\' };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: dashboard };\n\n  parallelResult[\'persons\'] = { ok: true };\n} catch(e) {\n  parallelResult[\'persons\'] = { ok: false, error: e };\n  throw e;\n}\ntry {\n// 节点: script [script_resources] 执法资源分支\nvar resources = { patrolTeams:12, responseTeams:4 };\n\n// 节点: script [script_dashboard] 生成指挥看板\nvar dashboard = { weatherLevel:\'yellow\', personsOnline:3862, riskyPersons:27, patrolTeams:12, responseTeams:4, action:\'启动重点区域巡控\' };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: dashboard };\n\n  parallelResult[\'resources\'] = { ok: true };\n} catch(e) {\n  parallelResult[\'resources\'] = { ok: false, error: e };\n  throw e;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/02.应急指挥并行汇聚服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3e9673599d77f92c0a646abf469aa9e2','fl_t6xg9ldazp',NULL,'{\n  "properties": {},\n  "id": "3e9673599d77f92c0a646abf469aa9e2",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "03.治安巡控活动分页服务",\n  "createTime": 1781574559968,\n  "updateTime": 1781574559916,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/patrol/activity-page",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按页返回治安巡控活动、辖区、警力、处置数量和验收状态，支撑公开查询与业务查询。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.治安巡控活动分页服务\n// 路由：GET /dws/flowserve/published/police/patrol/activity-page\n// 业务说明：按页返回治安巡控活动、辖区、警力、处置数量和验收状态，支撑公开查询与业务查询。\n// === 自动生成，请勿手改；flowId: fl_t6xg9ldazp ===\n\n\n// 节点: script [script_release] 生成放流活动清单\nvar activities = [{ id:1, seaArea:\'厦门湾\', species:\'大黄鱼\', quantity:120000, accepted:true }, { id:2, seaArea:\'湄洲湾\', species:\'黑鲷\', quantity:80000, accepted:false }, { id:3, seaArea:\'东山湾\', species:\'花鲈\', quantity:60000, accepted:true }];\n\n// 节点: filter [filter_release] 过滤有效活动\nvar validActivities = activities;\n// filter predicate: item.quantity > 0\n\n// 节点: paginate [page_release] 活动分页\nvar __page = page == null ? 1 : page;\nvar __size = size == null ? 10 : size;\nvar pagedActivities = { page: __page, size: __size, list: validActivities };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: pagedActivities };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/03.治安巡控活动分页服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a6b04e11333413798cfe2cb213e3388a','fl_3e4h3p7im6',NULL,'{\n  "properties": {},\n  "id": "a6b04e11333413798cfe2cb213e3388a",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "04.涉稳线索上报异常兜底服务",\n  "createTime": 1781574563683,\n  "updateTime": 1781574563634,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/report/fallback-guard",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "保护涉稳线索上报链路，主链路异常时进入本地补偿队列和人工通知。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.涉稳线索上报异常兜底服务\n// 路由：POST /dws/flowserve/published/police/report/fallback-guard\n// 业务说明：保护涉稳线索上报链路，主链路异常时进入本地补偿队列和人工通知。\n// === 自动生成，请勿手改；flowId: fl_3e4h3p7im6 ===\n\nif (reportType == null) {\n    return response.json(400, { code: 400, message: \'reportType 不能为空\' });\n}\n\n// 节点: try-catch [try_guard] 保护上报主链路\ntry {\n// 节点: script [script_submit] 主链路上报处理\nvar reportResult = { ok:true, channel:\'provincial-data-hub\', reportType:reportType };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: reportResult };\n\n} catch(e) {\nvar reportError = e;\n// 节点: script [script_fallback] 异常兜底入库\nvar reportResult = { ok:false, channel:\'local-fallback-queue\', action:\'写入本地补偿队列并通知值班员\' };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: reportResult };\n\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/04.涉稳线索上报异常兜底服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e57f27492d2e90a1bd4a8ee7d1ad1c31','fl_bfj66wlvv5',NULL,'{\n  "properties": {},\n  "id": "e57f27492d2e90a1bd4a8ee7d1ad1c31",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "05.视频巡检联动服务",\n  "createTime": 1781574557032,\n  "updateTime": 1781574556941,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/video/inspection",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "联动视频平台巡检摄像头在线状态，生成点位设备健康结论和处置建议。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.视频巡检联动服务\n// 路由：GET /dws/flowserve/published/police/video/inspection\n// 业务说明：联动视频平台巡检摄像头在线状态，生成点位设备健康结论和处置建议。\n// === 自动生成，请勿手改；flowId: fl_bfj66wlvv5 ===\n\nif (portCode == null) {\n    return response.json(400, { code: 400, message: \'portCode 不能为空\' });\n}\n\n// 节点: http-call [http_video] 调用视频平台健康接口\nvar videoHealth = httpx.request({ method: \'GET\', url: \'http://127.0.0.1:9999/api/v1/runtime/health\', datasource: \'\', path: \'\', timeoutMs: 3000 });\n\n// 节点: script [script_video] 生成巡检结论\nvar inspection = { portCode: portCode, cameraOnlineRate: 0.96, abnormalCameras: 3, action: \'通知港区值守人员复核离线摄像头\' };\n\n// 节点: log [log_video] 记录视频巡检日志\n// log.info: port video inspection completed\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: inspection };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/05.视频巡检联动服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('484e4cd5e10840f28143712d9325a9b0','fl_9goq3dw5ec',NULL,'{\n  "properties": {},\n  "id": "484e4cd5e10840f28143712d9325a9b0",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "06.警情事件多路分拨服务",\n  "createTime": 1781574564856,\n  "updateTime": 1781574564804,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/event/multi-branch-dispatch",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按警情类型分拨到治安、交管、出入境、反恐和人工复核链路，并配置不同处置时限。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.警情事件多路分拨服务\n// 路由：POST /dws/flowserve/published/police/event/multi-branch-dispatch\n// 业务说明：按警情类型分拨到治安、交管、出入境、反恐和人工复核链路，并配置不同处置时限。\n// === 自动生成，请勿手改；flowId: fl_9goq3dw5ec ===\n\nif (eventType == null) {\n    return response.json(400, { code: 400, message: \'eventType 不能为空\' });\n}\nif (areaCode == null) {\n    return response.json(400, { code: 400, message: \'areaCode 不能为空\' });\n}\n\n// 节点: validate [validate_hazard] 事件参数校验\n// validate\nif (!(eventType != null && areaCode != null && eventType != \'\' && areaCode != \'\')) {\n  return response.json(400, { code: 400, message: \'参数校验失败\' });\n}\n\n// 节点: switch [switch_hazard] 按事件类型多路分支\nvar __switch_switch_hazard = eventType;\nif (__switch_switch_hazard == \'alarm_bulletin\') {\n// 节点: script [script_red] 警情处置链路\nvar dispatchResult = { route:\'警情监测组\', action:\'加密核查+属地派出所通知+县区联动\', sla:\'2小时\', areaCode:areaCode, level:level };\n\n}\nelse if (__switch_switch_hazard == \'major_alarm\') {\n// 节点: http-call [http_storm] 重大警情预案联动\nvar stormHealth = httpx.request({ method: \'GET\', url: \'http://127.0.0.1:9999/api/v1/runtime/health\', datasource: \'\', path: \'\', timeoutMs: 3000 });\n\n// 节点: script [script_storm] 重大警情响应方案\nvar dispatchResult = { route:\'重大警情处置专班\', action:\'联动情指中心+通知属地派出所处置准备\', sla:\'1小时\', areaCode:areaCode, level:level };\n\n}\nelse if (__switch_switch_hazard == \'person_distress\') {\n// 节点: script [script_distress] 人员险情派单\nvar dispatchResult = { route:\'应急指挥协调组\', action:\'定位人员+联动巡特警+通知属地派出所\', sla:\'15分钟\', areaCode:areaCode };\n\n}\nelse if (__switch_switch_hazard == \'mass_incident\') {\n// 节点: script [script_disease] 群体事件处置\nvar dispatchResult = { route:\'水产技术推广站\', action:\'抽样检测+处方建议+跟踪复测\', sla:\'4小时\', areaCode:areaCode };\n\n}\nelse if (__switch_switch_hazard == \'illegal_fishing\') {\n// 节点: log [log_illegal] 重点人员执法日志\n// log.warn: illegal fishing clue routed to enforcement\n\n// 节点: script [script_illegal] 重点人员执法派单\nvar dispatchResult = { route:\'派出所执法总队\', action:\'核验AIS轨迹+派发巡航任务+证据留存\', sla:\'30分钟\', areaCode:areaCode };\n\n}\nelse {\n// 节点: script [script_default] 默认人工复核\nvar dispatchResult = { route:\'省级值班室\', action:\'人工研判后转派对应处室\', sla:\'30分钟\', areaCode:areaCode, eventType:eventType };\n\n}\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: dispatchResult };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/06.警情事件多路分拨服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('eab7ec2cb2e39d8a600370675adeb594','fl_q1fkq8ckqx',NULL,'{\n  "properties": {},\n  "id": "eab7ec2cb2e39d8a600370675adeb594",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "07.警情监测快报服务",\n  "createTime": 1781574554863,\n  "updateTime": 1781574554810,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/alarm/bulletin",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "汇总多个辖区警情数量、风险等级和处置建议，形成面向值班室的快报结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.警情监测快报服务\n// 路由：GET /dws/flowserve/published/police/alarm/bulletin\n// 业务说明：汇总多个辖区警情数量、风险等级和处置建议，形成面向值班室的快报结果。\n// === 自动生成，请勿手改；flowId: fl_q1fkq8ckqx ===\n\n\n// 节点: script [script_alarm_bulletin] 生成警情站点明细\nvar alarmBulletinRows = [{ seaArea:\'鼓楼辖区\', alarmCount:8600, level:\'orange\' }, { seaArea:\'罗源湾\', alarmCount:3200, level:\'yellow\' }, { seaArea:\'鼓楼辖区\', alarmCount:9200, level:\'orange\' }];\n\n// 节点: aggregate [agg_alarm_bulletin] 按辖区聚合快报\nvar bulletin = alarmBulletinRows;\n// aggregate: 建议在 SQL/ES 侧下推；当前保留源数据供后续节点处理。\n\n// 节点: set-var [set_advice] 补充处置建议\nvar bulletinWithAdvice = { summary: bulletin, advice: \'加密核查，通知属地派出所，联动情指中心值班室\' };\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: bulletinWithAdvice };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/07.警情监测快报服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e22a49ce6f0e3c64a14ab7e74af85eba','fl_8tdpx19wtv',NULL,'{\n  "properties": {},\n  "id": "e22a49ce6f0e3c64a14ab7e74af85eba",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "08.警情线索研判服务",\n  "createTime": 1781574558755,\n  "updateTime": 1781574558518,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/clue/analysis",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "汇聚警情线索、案件要素和处置记录，判断线索紧急程度并输出研判建议。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.警情线索研判服务\n// 路由：GET /dws/flowserve/published/police/clue/analysis\n// 业务说明：汇聚警情线索、案件要素和处置记录，判断线索紧急程度并输出研判建议。\n// === 自动生成，请勿手改；flowId: fl_8tdpx19wtv ===\n\nif (personNo == null) {\n    return response.json(400, { code: 400, message: \'personNo 不能为空\' });\n}\nif (expireDays == null) {\n    return response.json(400, { code: 400, message: \'expireDays 不能为空\' });\n}\n\n// 节点: sql-query [sql_clue] 查询许可证基础信息\nvar clue = db.chengtian.selectOne("SELECT \'FZJQ202607001\' personNo, \'涉稳警情线索\' clueType, 12 expireDays, \'正常\' status");\n\n// 节点: condition [cond_expire] 是否临近到期\nif (expireDays <= 30) {\n// 节点: script [script_urgent] 生成续期提醒\nvar renewalDecision = { level:\'urgent\', action:\'发送短信并推送县级窗口\', personNo:personNo, expireDays:expireDays };\n\n} else {\n// 节点: script [script_normal] 生成常规状态\nvar renewalDecision = { level:\'normal\', action:\'纳入常规月度巡检\', personNo:personNo, expireDays:expireDays };\n\n}\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: renewalDecision };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/08.警情线索研判服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('289bb9b793969546781e6e4238e36074',NULL,NULL,'{\n  "properties": {},\n  "id": "289bb9b793969546781e6e4238e36074",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "09.订单查询服务_副本",\n  "createTime": 1780823417641,\n  "updateTime": 1781318876893,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/secure/order-summary",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按用户ID查询示例订单数据。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.订单查询服务_副本\n// 路由：GET /dws/flowserve/published/secure/order-summary\n// 业务说明：按用户ID查询示例订单数据。\n// === FlowServe 自动生成，请勿手改；flowId: fl_4975al6gof ===\n\nif (userId == null) {\n    return response.json(400, { code: 400, message: \'userId 不能为空\' });\n}\n\n// 节点: sql-query [node_7qoeb4m2qt] 查询订单\nvar orders = db.chengtian.select("select\\n  id as orderId,\\n  user_id as userId,\\n  product_name as productName,\\n  amount,\\n  status,\\n  date_format(created_at, \'%Y-%m-%d %H:%i:%s\') as createdAt\\nfrom fs_demo_orders\\nwhere user_id = #{userId}\\norder by created_at desc\\nlimit 20");\n\n// 节点: response [node_u5vix24ryi] 返回订单列表\nreturn { code: 0, message: \'success\', data: orders };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/09.订单查询服务_副本.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b4b18ecf6bc3b596107e7b7d9a011747','fl_af2eddodue',NULL,'{\n  "properties": {},\n  "id": "b4b18ecf6bc3b596107e7b7d9a011747",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "10.车辆布控预警服务",\n  "createTime": 1781574553650,\n  "updateTime": 1781574553596,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/vehicle/control-alert",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "接收车辆号牌和辖区编码，筛选异常通行记录并按风险等级输出预警。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.车辆布控预警服务\n// 路由：GET /dws/flowserve/published/police/vehicle/control-alert\n// 业务说明：接收车辆号牌和辖区编码，筛选异常通行记录并按风险等级输出预警。\n// === 自动生成，请勿手改；flowId: fl_af2eddodue ===\n\nif (areaCode == null) {\n    return response.json(400, { code: 400, message: \'areaCode 不能为空\' });\n}\n\n// 节点: validate [validate_area] 辖区参数校验\n// validate\nif (!(areaCode != null && areaCode != \'\')) {\n  return response.json(400, { code: 400, message: \'参数校验失败\' });\n}\n\n// 节点: script [script_samples] 生成水质监测样本\nvar samples = [{ station:\'鼓楼辖区1号\', ph:8.1, oxygen:5.6, risk:1 }, { station:\'鼓楼辖区2号\', ph:9.2, oxygen:3.1, risk:4 }, { station:\'东吾洋3号\', ph:8.8, oxygen:3.8, risk:3 }];\n\n// 节点: filter [filter_alert] 异常指标过滤\nvar alerts = samples;\n// filter predicate: item.risk >= 3\n\n// 节点: sort [sort_alert] 按风险等级排序\nvar rankedAlerts = alerts;\n// sort: risk desc\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: rankedAlerts };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/10.车辆布控预警服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('134d48c35915e997ffe8e723be82dfed','fl_ujze9ez5oe',NULL,'{\n  "properties": {},\n  "id": "134d48c35915e997ffe8e723be82dfed",\n  "script": null,\n  "groupId": "e5ce028f1797312d57c628b66ffcf657",\n  "name": "11.重点人员线索批处理服务",\n  "createTime": 1781574561306,\n  "updateTime": 1781574561258,\n  "lock": null,\n  "createBy": null,\n  "updateBy": "flowserve",\n  "path": "/police/person/clue-batch",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "批量处理重点人员轨迹、案件和布控线索，循环生成核查对象并聚合风险概况。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.重点人员线索批处理服务\n// 路由：POST /dws/flowserve/published/police/person/clue-batch\n// 业务说明：批量处理重点人员轨迹、案件和布控线索，循环生成核查对象并聚合风险概况。\n// === 自动生成，请勿手改；flowId: fl_ujze9ez5oe ===\n\nif (batchNo == null) {\n    return response.json(400, { code: 400, message: \'batchNo 不能为空\' });\n}\n\n// 节点: script [script_clues] 生成线索批次\nvar clues = [{ clueId:\'C001\', risk:92, source:\'AIS\' }, { clueId:\'C002\', risk:61, source:\'举报\' }, { clueId:\'C003\', risk:87, source:\'雷达\' }];\n\n// 节点: foreach [loop_clues] 逐条生成核查任务\nvar tasks = [];\nfor (clue in clues) {\n  tasks.add(clue);\n}\n\n// 节点: filter [filter_high_risk] 筛选高风险线索\nvar highRiskClues = tasks;\n// filter predicate: item.risk >= 80\n\n// 节点: response [response] 标准响应\nreturn { code: 0, message: \'success\', data: highRiskClues };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/11.重点人员线索批处理服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e5ce028f1797312d57c628b66ffcf657',NULL,NULL,'{\n  "properties" : { },\n  "id" : "e5ce028f1797312d57c628b66ffcf657",\n  "name" : "07.已发布服务",\n  "type" : "api",\n  "parentId" : "5d290a9b3bca3b2dd9ffd715dc47ce56",\n  "path" : "/published",\n  "createTime" : 1784828418423,\n  "updateTime" : 1784828418423,\n  "createBy" : null,\n  "updateBy" : null,\n  "paths" : [ ],\n  "options" : [ ]\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/07.已发布服务/group.json');
