INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('07ef9bbe176b43dcb275f479e1de839c',NULL,NULL,'{\n  "properties": {},\n  "id": "07ef9bbe176b43dcb275f479e1de839c",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "01.删除网关资产",\n  "createTime": 1784437770688,\n  "updateTime": 1785000000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"apiId\\": \\"2361887157562377213\\",\\n  \\"dryRun\\": true\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"apiId\\": \\"2361887157562377213\\",\\n  \\"paramCount\\": 1,\\n  \\"fileCount\\": 0,\\n  \\"dryRun\\": true\\n}",\n  "description": "删除服务编排服务（POST /dws/flowserve/gateway/delete）。写入 api_info_t 软删除状态，并递归软删除 api_param_t 参数及 api_file_t 脚本关联；dryRun=true 时只返回影响范围；使用请求参数 apiId、api_id、id、tid、dryRun。"\n}\n================================\n// 接口：01.删除网关资产\n// 路由：POST /dws/flowserve/gateway/delete\n// 业务说明：删除服务编排服务（POST /dws/flowserve/gateway/delete）。写入 api_info_t 软删除状态，并递归软删除 api_param_t 参数及 api_file_t 脚本关联；dryRun=true 时只返回影响范围；使用请求参数 apiId、api_id、id、tid、dryRun。\nimport magicResourceLink\n\n/*\n * 删除服务主记录，并清理参数表与脚本文件关联。\n * 这里只做业务软删除，不删除物理 Magic 文件内容，避免误删可复用脚本。\n */\nvar apiId = body?.apiId || body?.api_id || body?.id || body?.tid\nif (apiId == null || (apiId + \'\').trim() == \'\') {\n    exit 400, \'apiId不能为空\'\n}\n\nvar apiCount = db.table(\'api_info_t\').where().eq(\'tid\', apiId).eq(\'is_del\', 0).count()\nvar paramCount = db.table(\'api_param_t\').where().eq(\'api_id\', apiId).eq(\'is_del\', 0).count()\nvar fileCount = magicResourceLink.countByApiId(apiId + \'\')\nvar result = {apiId: apiId, apiCount: apiCount, paramCount: paramCount, fileCount: fileCount, dryRun: body?.dryRun == true}\nif (body?.dryRun == true) {\n    return result\n}\n\nvar now = new Date()\ndb.table(\'api_info_t\').where().eq(\'tid\', apiId).eq(\'is_del\', 0).update({is_del: 1, updated_time: now})\ndb.table(\'api_param_t\').where().eq(\'api_id\', apiId).eq(\'is_del\', 0).update({is_del: 1, updated_time: now})\nmagicResourceLink.unlinkByApiId(apiId + \'\')\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.删除网关资产.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.服务分组/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b51895b7229f4638b70233a29567ccd7',NULL,NULL,'{\n  "properties": {},\n  "id": "b51895b7229f4638b70233a29567ccd7",\n  "script": null,\n  "groupId": "fb9192d12472469f82f204f1a4310a28",\n  "name": "01.保存服务分组",\n  "createTime": 1782955363365,\n  "updateTime": 1785200000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"id\\": \\"api_service_group_marine\\",\\n  \\"name\\": \\"福建省海洋与渔业局\\",\\n  \\"code\\": \\"marine\\",\\n  \\"sortNo\\": 2\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"id\\": \\"api_service_group_marine\\",\\n  \\"name\\": \\"福建省海洋与渔业局\\",\\n  \\"code\\": \\"marine\\"\\n}",\n  "description": "保存服务分组（POST /dws/flowserve/gateway/group/save）。写入 sym_dict_t 中 biz_type=apiServiceGroup 的服务分组字典；用于服务编排管理左侧分组新增和编辑；使用请求参数 id、name、dictName、code、dictCode、sortNo、sort_no。"\n}\n================================\n// 接口：01.保存服务分组\n// 路由：POST /dws/flowserve/gateway/group/save\n// 业务说明：保存服务分组（POST /dws/flowserve/gateway/group/save）。写入 sym_dict_t 中 biz_type=apiServiceGroup 的服务分组字典；用于服务编排管理左侧分组新增和编辑；使用请求参数 id、name、dictName、code、dictCode、sortNo、sort_no。\nimport cn.hutool.core.util.IdUtil;\n\n/*\n * 服务分组保存。\n * 分组不再写旧网关 g_service_group，也不新建 api_service_group_t；\n * 统一落在 sym_dict_t，biz_type=apiServiceGroup，右侧 api_info_t.group_id 关联该字典 tid。\n */\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar clean = value => blank(value) ? null : (value + \'\').trim()\n\nvar id = clean(body?.id)\nvar name = clean(body?.name || body?.dictName)\nif (blank(name)) {\n    return {\n        success: false,\n        code: \'PARAM_REQUIRED\',\n        msg: \'分组名称不能为空\'\n    }\n}\n\nvar code = clean(body?.code || body?.dictCode)\nvar sortNo = body?.sortNo == null ? body?.sort_no : body?.sortNo\nsortNo = sortNo == null ? 999 : sortNo::int(999)\nvar now = new Date()\n\nif (blank(id)) {\n    id = \'api_service_group_\' + IdUtil.getSnowflakeNextIdStr()\n}\nif (blank(code)) {\n    code = id\n}\n\n// 同名或同编码校验，避免左侧树出现两个含义相同的分组。\nvar exists = db.select("""\nselect tid\n  from sym_dict_t\n where coalesce(is_del, 0) = 0\n   and biz_type = \'apiServiceGroup\'\n   and tid <> #{id}\n   and (dict_name = #{name} or dict_code = #{code})\n limit 1\n""")\nif (exists != null && exists.size() > 0) {\n    return {\n        success: false,\n        code: \'GROUP_EXISTS\',\n        msg: \'服务分组名称或编码已存在\'\n    }\n}\n\nvar row = {\n    tid: id,\n    dict_name: name,\n    dict_code: code,\n    biz_type: \'apiServiceGroup\',\n    sort_no: sortNo,\n    is_del: 0,\n    updated_time: now\n}\n\nvar old = db.table(\'sym_dict_t\').where().eq(\'tid\', id).selectOne()\nif (old == null) {\n    row.created_time = now\n    db.table(\'sym_dict_t\').primary(\'tid\').insert(row)\n} else {\n    db.table(\'sym_dict_t\').primary(\'tid\').update(row, true)\n}\n\nreturn {\n    id: id,\n    name: name,\n    code: code,\n    sortNo: sortNo\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.服务分组/01.保存服务分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5d26a3dfa99b49edbe32d53bdfca061e',NULL,NULL,'{\n  "properties": {},\n  "id": "5d26a3dfa99b49edbe32d53bdfca061e",\n  "script": null,\n  "groupId": "fb9192d12472469f82f204f1a4310a28",\n  "name": "02.服务分组列表",\n  "createTime": 1782955363375,\n  "updateTime": 1785000000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"keyword\\": \\"默认\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"children\\": [{\\"id\\": \\"api_service_group_default\\", \\"name\\": \\"默认分组\\", \\"count\\": 10}],\\n  \\"total\\": 10\\n}",\n  "description": "服务分组列表（POST /dws/flowserve/gateway/group/list）。读取 sym_dict_t 中 biz_type=apiServiceGroup 的服务分组字典，并聚合 api_info_t 服务数量；当前不新建独立分组表；使用请求参数 keyword、name。"\n}\n================================\n// 接口：02.服务分组列表\n// 路由：POST /dws/flowserve/gateway/group/list\n// 业务说明：服务分组列表（POST /dws/flowserve/gateway/group/list）。读取 sym_dict_t 中 biz_type=apiServiceGroup 的服务分组字典，并聚合 api_info_t 服务数量；当前不新建独立分组表；使用请求参数 keyword、name。\n/*\n * 服务分组树。\n * 分组暂不独立建表，统一使用 sym_dict_t 的业务字典：\n * biz_type=apiServiceGroup，默认分组 tid=api_service_group_default。\n */\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar sqlValue = value => "\'" + ((value + \'\').replace("\'", "\'\'")) + "\'"\nvar likeValue = value => "\'%" + ((value + \'\').replace("\'", "\'\'")) + "%\'"\n\nvar whereSql = " where is_del = 0 and biz_type = \'apiServiceGroup\' "\nif (!blank(body?.keyword || body?.name)) {\n    var keyword = body?.keyword || body?.name\n    whereSql += " and (dict_name like " + likeValue(keyword) + " or dict_code like " + likeValue(keyword) + ") "\n}\n\nvar rows = db.select("""\nselect\n  tid as id,\n  tid as value,\n  dict_name as name,\n  dict_name as label,\n  dict_code as code,\n  icon as icon,\n  sort_no as sortNo\nfrom sym_dict_t\n""" + whereSql + """\norder by sort_no, dict_name\n""")\n\nvar countRows = db.select("""\nselect coalesce(group_id, \'api_service_group_default\') as groupId, count(1) as total\n  from api_info_t\n where is_del = 0\n group by coalesce(group_id, \'api_service_group_default\')\n""")\nvar countMap = {}\nvar total = 0\nfor (item in countRows) {\n    var key = (item.groupId || item.groupid || item.group_id || \'api_service_group_default\') + \'\'\n    var num = item.total == null ? 0 : item.total::int(0)\n    countMap[key] = num\n    total = total + num\n}\n\nvar list = []\nfor (row in rows) {\n    var id = row.id + \'\'\n    row.count = countMap[id] == null ? 0 : countMap[id]\n    row.children = []\n    list.add(row)\n}\n\nreturn {\n    list: list,\n    children: list,\n    total: total,\n    totalGroups: list.size()\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.服务分组/02.服务分组列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('gateway_group_delete_20260726',NULL,NULL,'{\n  "properties": {},\n  "id": "gateway_group_delete_20260726",\n  "script": null,\n  "groupId": "fb9192d12472469f82f204f1a4310a28",\n  "name": "03.删除服务分组",\n  "createTime": 1785200000000,\n  "updateTime": 1785200000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"id\\": \\"api_service_group_marine\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"deleted\\": true,\\n  \\"id\\": \\"api_service_group_marine\\"\\n}",\n  "description": "删除服务分组（POST /dws/flowserve/gateway/group/delete）。软删除 sym_dict_t 中 biz_type=apiServiceGroup 的分组；若 api_info_t 仍有关联服务则拒绝删除；使用请求参数 id、tid。"\n}\n================================\n// 接口：03.删除服务分组\n// 路由：POST /dws/flowserve/gateway/group/delete\n// 业务说明：删除服务分组（POST /dws/flowserve/gateway/group/delete）。软删除 sym_dict_t 中 biz_type=apiServiceGroup 的分组；若 api_info_t 仍有关联服务则拒绝删除；使用请求参数 id、tid。\n/*\n * 服务分组删除。\n * 分组作为 api_info_t.group_id 的字典，不做级联删除服务；\n * 有服务占用时先提示用户调整或删除服务，避免右侧列表出现孤儿分组。\n */\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar id = body?.id || body?.tid\nif (blank(id)) {\n    return {\n        success: false,\n        code: \'PARAM_REQUIRED\',\n        msg: \'分组ID不能为空\'\n    }\n}\nif ((id + \'\') == \'api_service_group_default\') {\n    return {\n        success: false,\n        code: \'DEFAULT_GROUP_LOCKED\',\n        msg: \'默认分组不能删除\'\n    }\n}\n\nvar usingCount = db.table(\'api_info_t\').where().eq(\'group_id\', id).eq(\'is_del\', 0).count()\nif (usingCount > 0) {\n    return {\n        success: false,\n        code: \'GROUP_IN_USE\',\n        msg: \'分组下仍有服务，请先调整服务分组或删除服务\'\n    }\n}\n\ndb.table(\'sym_dict_t\').where()\n  .eq(\'tid\', id)\n  .eq(\'biz_type\', \'apiServiceGroup\')\n  .update({is_del: 1, updated_time: new Date()})\n\nreturn {\n    deleted: true,\n    id: id\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.服务分组/03.删除服务分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fb9192d12472469f82f204f1a4310a28',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "fb9192d12472469f82f204f1a4310a28",\r\n  "name" : "01.服务分组",\r\n  "type" : "api",\r\n  "parentId" : "2baeb325734a4f348df335661b205952",\r\n  "path" : "/group",\r\n  "createTime" : 1782955363338,\r\n  "updateTime" : 1784437771886,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/01.服务分组/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d28067686c114ad1aca3b65902443832',NULL,NULL,'{\n  "properties": {},\n  "id": "d28067686c114ad1aca3b65902443832",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "02.同步网关资产",\n  "createTime": 1784437770685,\n  "updateTime": 1787153758011,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/sync",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"enforce\\": \\"测试\\",\\n    \\"dryRun\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "同步云梯网关 API 到本地资产；使用请求参数 enforce、dryRun、catalogId；涉及 da_asset_t、da_asset_api_rela、da_prop_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.同步网关资产\n// 路由：POST /dws/flowserve/gateway/sync\n// 业务说明：同步云梯网关 API 到本地资产；使用请求参数 enforce、dryRun、catalogId；涉及 da_asset_t、da_asset_api_rela、da_prop_t 等业务表；执行数据库写入并返回处理结果。\n/*\n * 同步云梯网关 API 到本地资产\n *\n * GatewayUtils 只负责签名、令牌和 HTTP 重试；Magic 负责 API 详情转换、\n * 资产/目录关系、动态属性持久化和 ES 投影。body.enforce=true 时覆盖已有\n * 资产；body.dryRun=true 时只返回待同步 ID。\n */\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport jsons\nimport java.util.List\nimport java.util.Map\n\nvar toCamel\ntoCamel = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toCamelCase(keyName + \'\')] = toCamel(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(toCamel(item))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\n// 调用外部网关并统一处理返回结果与异常。\nvar apiIds = gatewayUtils.callGatewayApiForList(\'V2DescribeApiIdList\', {})\n// 解析请求体并为可选参数设置默认值。\nvar enforce = body?.enforce == true || body?.enforce == 1 || body?.enforce == \'1\'\nvar pending = []\nfor (apiId in apiIds) {\n    // 从 MySQL 业务表读取当前有效数据。\n    if (enforce || db.table(\'da_asset_t\').where()\n        .eq(\'tid\', apiId).eq(\'asset_type\', \'api\').eq(\'is_del\', 0).count() == 0) {\n        pending.add(apiId)\n    }\n}\nif (body?.dryRun == true) {\n    // 返回当前业务分支的标准结果。\n    return {total: apiIds.size(), pending: pending.size(), apiIds: pending, dryRun: true}\n}\n\nvar now = new Date()\nvar synced = 0\nvar skipped = 0\nvar failed = []\nfor (apiId in pending) {\n    try {\n        // 调用外部网关并统一处理返回结果与异常。\n        var detail = toCamel(gatewayUtils.callGatewayApi(\'V2DescribeApi\', {api_id: apiId}))\n        if (detail.errorCode == \'data_not_found\') {\n            skipped++\n            continue\n        }\n        detail.tid = apiId\n        detail.assetType = \'api\'\n        detail.serviceName = detail.name || \'\'\n        detail.serviceCreateType = detail.serviceBuildId ? \'apiBuild\' : \'api\'\n        detail.updatedTime = date_format(now)\n\n        var catalogId = detail.catalogId || body?.catalogId || \'1\'\n        // 从 MySQL 业务表读取当前有效数据。\n        if (catalogId != null && catalogId != \'\' && db.table(\'da_asset_api_rela\').where()\n            .eq(\'api_id\', apiId).eq(\'catalog_id\', catalogId).eq(\'is_del\', 0).count() == 0) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_asset_api_rela\').primary(\'tid\').insert({\n                tid: IdUtil.getSnowflakeNextIdStr(),\n                api_id: apiId,\n                catalog_id: catalogId,\n                is_del: 0,\n                created_time: now,\n                updated_time: now\n            })\n        }\n\n        // 从 MySQL 业务表读取当前有效数据。\n        var current = db.table(\'da_asset_t\').where().eq(\'tid\', apiId).selectOne()\n        if (current == null) {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_asset_t\').primary(\'tid\').insert({\n                tid: apiId,\n                asset_type: \'api\',\n                flow_status: 0,\n                asset_status: 2,\n                is_del: 0,\n                created_time: now,\n                updated_time: now,\n                reg_time: now\n            })\n        } else {\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table(\'da_asset_t\').where().eq(\'tid\', apiId).update({\n                asset_type: \'api\',\n                flow_status: 0,\n                asset_status: 2,\n                is_del: 0,\n                updated_time: now\n            })\n        }\n\n        // 调用外部网关并统一处理返回结果与异常。\n        var overview = toCamel(gatewayUtils.callGatewayApi(\'V2ApiCallOverview\', {api_id: apiId}))\n        if (overview != null) {\n            overview.successPercent = 100 - ((overview.errorPercent || \'0\')::double)\n            for (entry in overview.entrySet()) {\n                detail[keyName] = value[keyName]\n            }\n        }\n\n        for (entry in detail.entrySet()) {\n            var propName = keyName + \'\'\n            var rawValue = value[keyName]\n            var propValue = rawValue instanceof Map || rawValue instanceof List\n                ? jsons.toJSONStr(rawValue)\n                : rawValue == null ? null : rawValue + \'\'\n            // 从 MySQL 业务表读取当前有效数据。\n            var prop = db.table(\'da_prop_t\').where()\n                .eq(\'parent_id\', apiId).eq(\'prop_name\', propName).selectOne()\n            if (prop == null) {\n                // 将校验后的业务数据写入 MySQL 主表。\n                db.table(\'da_prop_t\').primary(\'tid\').insert({\n                    tid: IdUtil.getSnowflakeNextIdStr(),\n                    parent_id: apiId,\n                    prop_name: propName,\n                    prop_value: propValue,\n                    prop_type: \'0\',\n                    data_type: \'api\',\n                    is_del: 0,\n                    created_time: now,\n                    updated_time: now\n                })\n            } else {\n                // 将校验后的业务数据写入 MySQL 主表。\n                db.table(\'da_prop_t\').where().eq(\'tid\', prop.tid).update({\n                    prop_value: propValue,\n                    data_type: \'api\',\n                    is_del: 0,\n                    updated_time: now\n                })\n            }\n        }\n        // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n        esCommonService.saveOrUpdate(\'dataassets\', apiId + \'\', jsons.toJSONStr(detail), false)\n        synced++\n    } catch (e) {\n        failed.add({apiId: apiId, message: e.message})\n    }\n}\n\n// 返回当前业务分支的标准结果。\nreturn {total: apiIds.size(), pending: pending.size(), synced: synced, skipped: skipped, failed: failed}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/02.同步网关资产.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/02.服务列表/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('510fe82cba4a42248abd1faefc515441',NULL,NULL,'{\n  "properties": {},\n  "id": "510fe82cba4a42248abd1faefc515441",\n  "script": null,\n  "groupId": "45b082c7d94f4ff08e3b9bf367521723",\n  "name": "01.服务列表",\n  "createTime": 1782955363383,\n  "updateTime": 1787153757564,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"keyword\\": \\"人员\\",\\n  \\"groupId\\": \\"api_service_group_default\\",\\n  \\"method\\": \\"POST\\",\\n  \\"status\\": \\"published\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"list\\": [],\\n  \\"total\\": 0,\\n  \\"stats\\": {\\"total\\": 0, \\"draft\\": 0, \\"published\\": 0, \\"offline\\": 0}\\n}",\n  "description": "服务编排管理列表（POST /dws/flowserve/gateway/api/list）。读取 api_info_t 主表、api_param_t 参数表、api_file_t 脚本关联和 sym_dict_t 服务分组字典；按分组、方法、状态、关键字分页查询，是服务编排管理页面主接口；使用请求参数 pageNum、pageSize、keyword、groupId、method、status。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.服务列表\n// 路由：POST /dws/flowserve/gateway/api/list\n// 业务说明：服务编排管理列表（POST /dws/flowserve/gateway/api/list）。读取 api_info_t 主表、api_param_t 参数表、api_file_t 脚本关联和 sym_dict_t 服务分组字典；按分组、方法、状态、关键字分页查询，是服务编排管理页面主接口；使用请求参数 pageNum、pageSize、keyword、groupId、method、status。\nimport magicResourceLink\n\n/*\n * 服务编排管理列表。\n * 读取 api_info_t 作为服务主表，api_param_t/api_file_t 只聚合当前页服务，\n * sym_dict_t 中 biz_type=apiServiceGroup 的字典项作为左侧分组名称。\n */\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar sqlValue = value => "\'" + ((value + \'\').replace("\'", "\'\'")) + "\'"\nvar likeValue = value => "\'%" + ((value + \'\').replace("\'", "\'\'")) + "%\'"\nvar pageNum = body?.pageNum == null ? 1 : body.pageNum::int(1)\nvar pageSize = body?.pageSize == null ? 20 : body.pageSize::int(20)\nif (pageNum < 1) { pageNum = 1 }\nif (pageSize < 1) { pageSize = 20 }\nif (pageSize > 200) { pageSize = 200 }\n\nvar statusExpr = "coalesce(a.status, case when coalesce(a.is_use, 1) = 1 then \'published\' else \'offline\' end)"\nvar whereSql = " where a.is_del = 0 "\n\n// 关键字同时命中服务名称、服务编码、服务地址，避免前端多个输入框造成理解成本。\nif (!blank(body?.keyword)) {\n    var keyword = body.keyword\n    whereSql += " and (a.service_name like " + likeValue(keyword) +\n        " or a.service_code like " + likeValue(keyword) +\n        " or a.uri like " + likeValue(keyword) +\n        " or a.publish_address like " + likeValue(keyword) + ") "\n}\n\n// 左侧分组树点击后只过滤对应服务分组；未分组服务归入默认分组。\nif (!blank(body?.groupId)) {\n    whereSql += " and coalesce(a.group_id, \'api_service_group_default\') = " + sqlValue(body.groupId) + " "\n}\nif (!blank(body?.method)) {\n    whereSql += " and upper(coalesce(a.method, \'GET\')) = " + sqlValue((body.method + \'\').toUpperCase()) + " "\n}\nif (!blank(body?.status)) {\n    whereSql += " and " + statusExpr + " = " + sqlValue(body.status) + " "\n}\n\nvar offset = (pageNum - 1) * pageSize\n\nvar listSql = """\nselect\n  a.tid as id,\n  a.tid as tid,\n  a.service_name as serviceName,\n  a.service_name as name,\n  a.service_code as serviceCode,\n  a.service_code as code,\n  a.resource_id as resourceId,\n  coalesce(a.group_id, \'api_service_group_default\') as groupId,\n  a.service_type as serviceType,\n  coalesce(a.service_create_type, \'api\') as serviceCreateType,\n  """ + statusExpr + """ as status,\n  coalesce(a.protocol, \'HTTP\') as protocol,\n  coalesce(a.uri, \'\') as uri,\n  upper(coalesce(a.method, \'GET\')) as method,\n  coalesce(a.publish_address, a.uri, \'\') as publishAddress,\n  coalesce(a.publish_address_full, a.publish_address, a.uri, \'\') as publishAddressFull,\n  a.service_desc as serviceDesc,\n  a.version as version,\n  a.labels as labels,\n  a.catalog_id as catalogId,\n  a.org_id as orgId,\n  a.provider_config as providerConfig,\n  a.publish_config as publishConfig,\n  a.flow_id as flowId,\n  coalesce(a.call_count, 0) as requestCount,\n  coalesce(a.success_percent, 0) as successPercent,\n  (select count(1)\n     from api_param_t p\n    where p.api_id = a.tid\n      and p.is_del = 0) as paramCount,\n  0 as apiFileCount,\n  a.created_time as createdTime,\n  a.updated_time as updatedTime\nfrom api_info_t a\n""" + whereSql + """\norder by a.updated_time desc, a.created_time desc\nlimit """ + offset + ", " + pageSize\n\nvar list = db.select(listSql)\nlist = magicResourceLink.attachApiFileCounts(list)\n\n// 分组字典与服务主表可能来自不同时期建表，字符集排序规则不一定一致；\n// 这里用内存映射规避跨表 collation 问题，也方便后续切换达梦。\nvar groupRows = db.select("""\nselect tid as id, dict_name as name\n  from sym_dict_t\n where is_del = 0\n   and biz_type = \'apiServiceGroup\'\n""")\nvar groupMap = {}\nfor (group in groupRows) {\n    groupMap[(group.id || group.ID || group.tid || \'\') + \'\'] = group.name || group.dictName || group.dict_name\n}\nvar viewList = []\nfor (row in list) {\n    var gid = row.groupId || row.groupid || row.group_id || \'api_service_group_default\'\n    row.groupId = gid\n    row.groupName = groupMap[gid + \'\'] || \'默认分组\'\n    row.name = row.serviceName || row.servicename || row.service_name || row.name\n    row.serviceName = row.name\n    row.code = row.serviceCode || row.servicecode || row.service_code || row.code\n    row.serviceCode = row.code\n    // 输出给前端的 DTO 只保留一套字段，避免 DB 返回的小写别名和 camelCase 字段并存。\n    viewList.add({\n        id: row.id || row.tid,\n        tid: row.tid || row.id,\n        serviceName: row.serviceName || \'\',\n        name: row.serviceName || \'\',\n        serviceCode: row.serviceCode || \'\',\n        code: row.serviceCode || \'\',\n        resourceId: row.resourceId || row.resourceid || row.resource_id,\n        groupId: row.groupId || gid,\n        groupName: row.groupName || \'默认分组\',\n        serviceType: row.serviceType || row.servicetype || row.service_type,\n        serviceCreateType: row.serviceCreateType || row.servicecreatetype || row.service_create_type || \'api\',\n        status: row.status || \'published\',\n        protocol: row.protocol || \'HTTP\',\n        uri: row.uri || \'\',\n        method: row.method || \'GET\',\n        publishAddress: row.publishAddress || row.publishaddress || row.publish_address || \'\',\n        publishAddressFull: row.publishAddressFull || row.publishaddressfull || row.publish_address_full || \'\',\n        serviceDesc: row.serviceDesc || row.servicedesc || row.service_desc,\n        version: row.version,\n        labels: row.labels,\n        catalogId: row.catalogId || row.catalogid || row.catalog_id,\n        orgId: row.orgId || row.orgid || row.org_id,\n        providerConfig: row.providerConfig || row.providerconfig || row.provider_config,\n        publishConfig: row.publishConfig || row.publishconfig || row.publish_config,\n        extendInfo: {},\n        flowId: row.flowId || row.flowid || row.flow_id,\n        requestCount: row.requestCount || row.requestcount || row.request_count || 0,\n        successPercent: row.successPercent || row.successpercent || row.success_percent || 0,\n        paramCount: row.paramCount || row.paramcount || row.param_count || 0,\n        apiFileCount: row.apiFileCount || row.apifilecount || row.api_file_count || 0,\n        createdTime: row.createdTime || row.createdtime || row.created_time,\n        updatedTime: row.updatedTime || row.updatedtime || row.updated_time\n    })\n}\n\n// 统计当前过滤条件下不同服务状态的数量，供顶部卡片筛选使用。\nvar statsRows = db.select("""\nselect\n  count(1) as total,\n  sum(case when """ + statusExpr + """ = \'draft\' then 1 else 0 end) as draft,\n  sum(case when """ + statusExpr + """ = \'published\' then 1 else 0 end) as published,\n  sum(case when """ + statusExpr + """ = \'offline\' then 1 else 0 end) as offline\nfrom api_info_t a\n""" + whereSql)\nvar stats = statsRows == null || statsRows.size() == 0\n    ? {total: 0, draft: 0, published: 0, offline: 0}\n    : statsRows[0]\nvar total = stats.total == null ? 0 : stats.total\n\nreturn {\n    list: viewList,\n    total: total,\n    pageNum: pageNum,\n    pageSize: pageSize,\n    stats: stats\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/02.服务列表/01.服务列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1cc3266227a24804b9ba7c3a9e00d724',NULL,'api','{\n  "properties": {},\n  "id": "1cc3266227a24804b9ba7c3a9e00d724",\n  "script": null,\n  "groupId": "45b082c7d94f4ff08e3b9bf367521723",\n  "name": "02.服务详情",\n  "createTime": 1785025400000,\n  "updateTime": 1787153758165,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"apiId\\": \\"2436540554061808637\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"id\\": \\"2436540554061808637\\",\\n  \\"name\\": \\"数据组织\\",\\n  \\"publishParams\\": []\\n}",\n  "description": "服务详情（POST /dws/flowserve/gateway/api/detail）。只读 api_info_t 服务主表、api_param_t 参数表、api_file_t 脚本关联和 sym_dict_t 分组字典；用于服务编排管理详情页按 api_id 回填登记/构建表单。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.服务详情\n// 路由：POST /dws/flowserve/gateway/api/detail\n// 业务说明：服务详情（POST /dws/flowserve/gateway/api/detail）。只读 api_info_t 服务主表、api_param_t 参数表、api_file_t 脚本关联和 sym_dict_t 分组字典；用于服务编排管理详情页按 api_id 回填登记/构建表单。\n/*\n * 服务详情接口。\n * 以 api_info_t 为主表读取服务登记信息，api_param_t 回填请求参数，\n * api_file_t 仅统计关联脚本数量，接口不写入业务数据。\n */\nimport magicResourceLink\nimport cn.hutool.json.JSONUtil\n\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar sqlValue = value => "\'" + ((value + \'\').replace("\'", "\'\'")) + "\'"\nvar asObj = value => {\n    if (blank(value)) {\n        return {}\n    }\n    try {\n        return JSONUtil.parseObj(value)\n    } catch (e) {\n        return {}\n    }\n}\n\nvar apiId = body?.apiId || body?.api_id || body?.id || body?.tid || parameter?.apiId || parameter?.id\nif (blank(apiId)) {\n    exit 400, \'apiId不能为空\'\n}\n\n// 基础信息来自服务主表，兼容早期迁移数据中 method/status 为空的情况。\nvar rows = db.select("""\nselect\n  tid as id,\n  tid,\n  service_name as serviceName,\n  service_code as serviceCode,\n  resource_id as resourceId,\n  coalesce(group_id, \'api_service_group_default\') as groupId,\n  service_type as serviceType,\n  coalesce(service_create_type, \'api\') as serviceCreateType,\n  coalesce(status, case when coalesce(is_use, 1) = 1 then \'published\' else \'offline\' end) as status,\n  coalesce(protocol, \'HTTP\') as protocol,\n  coalesce(uri, \'\') as uri,\n  upper(coalesce(method, \'GET\')) as method,\n  coalesce(address, uri, \'\') as address,\n  coalesce(publish_address, uri, \'\') as publishAddress,\n  coalesce(publish_address_full, publish_address, uri, \'\') as publishAddressFull,\n  service_desc as serviceDesc,\n  version,\n  labels,\n  catalog_id as catalogId,\n  org_id as orgId,\n  provider_config as providerConfig,\n  publish_config as publishConfig,\n  flow_id as flowId,\n  return_type as returnType,\n  share_type as shareType,\n  data_domain as dataDomain,\n  data_category as dataCategory,\n  data_level as dataLevel,\n  source_business_name as sourceBusinessName,\n  source_business_item as sourceBusinessItem,\n  request_example as requestExample,\n  response_example as responseExample,\n  coalesce(call_count, 0) as requestCount,\n  coalesce(success_percent, 0) as successPercent,\n  service_sql as serviceSql,\n  created_time as createdTime,\n  updated_time as updatedTime\nfrom api_info_t\nwhere coalesce(is_del, 0) = 0\n  and tid = """ + sqlValue(apiId) + """\nlimit 1\n""")\nif (rows == null || rows.size() == 0) {\n    exit 404, \'服务不存在或已删除\'\n}\nvar row = rows[0]\n\n// 参数表按 sort_no 回填为登记表单使用的 publishParams 结构。\nvar paramRows = db.select("""\nselect\n  tid,\n  param_name as paramName,\n  param_desc as description,\n  param_type as paramType,\n  param_position as paramPosition,\n  required_flag as required,\n  default_value as defaultValue,\n  showcase_value as showcaseValue,\n  param_scope as paramScope,\n  sort_no as sortNo\nfrom api_param_t\nwhere coalesce(is_del, 0) = 0\n  and api_id = """ + sqlValue(apiId) + """\norder by coalesce(sort_no, 9999), created_time\n""")\nvar publishParams = []\nfor (p in paramRows) {\n    publishParams.add({\n        id: p.tid,\n        paramName: p.paramName || p.paramname || \'\',\n        description: p.description || \'\',\n        paramType: p.paramType || p.paramtype || \'\',\n        paramPosition: p.paramPosition || p.paramposition || \'\',\n        required: p.required || \'\',\n        defaultValue: p.defaultValue || p.defaultvalue || \'\',\n        showcaseValue: p.showcaseValue || p.showcasevalue || \'\',\n        paramScope: p.paramScope || p.paramscope || \'request\',\n        sortNo: p.sortNo || p.sortno\n    })\n}\n\nvar provider = asObj(row.providerConfig || row.providerconfig || row.provider_config)\nvar publish = asObj(row.publishConfig || row.publishconfig || row.publish_config)\nvar ext = {}\nvar extRows = db.table(\'da_prop_t\').where().eq(\'parent_id\', apiId).eq(\'data_type\', \'api\').eq(\'is_del\', 0).select()\nfor (prop in extRows) {\n    var propName = prop.propName || prop.prop_name\n    if (!blank(propName)) {\n        ext[propName] = prop.propValue == null ? prop.prop_value : prop.propValue\n    }\n}\n\n// 老数据可能只写了物理字段，没有写 JSON 配置；这里补齐表单需要的配置键。\nprovider.protocol = provider.protocol || row.protocol || \'HTTP\'\nprovider.address = provider.address || row.address || row.uri || \'\'\nprovider.httpMethod = provider.httpMethod || provider.httpmethod || row.method || \'GET\'\npublish.publishAddress = publish.publishAddress || publish.publishaddress || row.publishAddress || row.publishaddress || row.uri || \'\'\npublish.publishMethod = publish.publishMethod || publish.publishmethod || row.method || \'GET\'\next.catalogId = ext.catalogId || ext.catalogid || row.catalogId || row.catalogid || \'\'\next.orgId = ext.orgId || ext.orgid || row.orgId || row.orgid || \'\'\next.dataDomain = ext.dataDomain || ext.datadomain || row.dataDomain || row.datadomain || \'\'\next.dataCategory = ext.dataCategory || ext.datacategory || row.dataCategory || row.datacategory || \'\'\next.dataLevel = ext.dataLevel || ext.datalevel || row.dataLevel || row.datalevel || \'\'\next.sourceBusinessName = ext.sourceBusinessName || row.sourceBusinessName || row.sourcebusinessname || \'\'\next.sourceBusinessItem = ext.sourceBusinessItem || row.sourceBusinessItem || row.sourcebusinessitem || \'\'\next.returnType = ext.returnType || row.returnType || row.returntype || \'\'\next.shareType = ext.shareType || row.shareType || row.sharetype || \'\'\next.requestExample = ext.requestExample || row.requestExample || row.requestexample || \'\'\next.responseExample = ext.responseExample || row.responseExample || row.responseexample || \'\'\n\nvar groupRows = db.select("""\nselect dict_name as name\nfrom sym_dict_t\nwhere coalesce(is_del, 0) = 0\n  and biz_type = \'apiServiceGroup\'\n  and tid = """ + sqlValue(row.groupId || row.groupid || \'api_service_group_default\') + """\nlimit 1\n""")\nvar apiFileCount = magicResourceLink.countByApiId(apiId + \'\')\n\nreturn {\n    id: row.id || row.tid,\n    tid: row.tid || row.id,\n    name: row.serviceName || row.servicename || \'\',\n    serviceName: row.serviceName || row.servicename || \'\',\n    serviceCode: row.serviceCode || row.servicecode || \'\',\n    code: row.serviceCode || row.servicecode || \'\',\n    resourceId: row.resourceId || row.resourceid,\n    groupId: row.groupId || row.groupid || \'api_service_group_default\',\n    groupName: groupRows == null || groupRows.size() == 0 ? \'默认分组\' : groupRows[0].name,\n    serviceType: row.serviceType || row.servicetype || \'数据服务\',\n    serviceCreateType: row.serviceCreateType || row.servicecreatetype || \'api\',\n    status: row.status || \'draft\',\n    protocol: row.protocol || \'HTTP\',\n    uri: row.uri || \'\',\n    method: row.method || \'GET\',\n    address: row.address || \'\',\n    publishAddress: row.publishAddress || row.publishaddress || \'\',\n    publishAddressFull: row.publishAddressFull || row.publishaddressfull || \'\',\n    description: row.serviceDesc || row.servicedesc || \'\',\n    serviceDesc: row.serviceDesc || row.servicedesc || \'\',\n    version: row.version || \'1.0\',\n    labels: row.labels || \'\',\n    providerConfig: provider,\n    publishConfig: publish,\n    extendInfo: ext,\n    flowId: row.flowId || row.flowid || row.flow_id || provider.flowId || provider.flowid || \'\',\n    publishParams: publishParams,\n    requestExample: ext.requestExample || \'\',\n    responseExample: ext.responseExample || \'\',\n    requestCount: row.requestCount || row.requestcount || 0,\n    successPercent: row.successPercent || row.successpercent || 0,\n    apiFileCount: apiFileCount,\n    createdTime: row.createdTime || row.createdtime,\n    updatedTime: row.updatedTime || row.updatedtime\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/02.服务列表/02.服务详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('45b082c7d94f4ff08e3b9bf367521723',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "45b082c7d94f4ff08e3b9bf367521723",\r\n  "name" : "02.服务列表",\r\n  "type" : "api",\r\n  "parentId" : "2baeb325734a4f348df335661b205952",\r\n  "path" : "/api",\r\n  "createTime" : 1782955363352,\r\n  "updateTime" : 1784437771886,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/02.服务列表/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7f2bf7ddf58448f7ae07e3345e7a8b0e',NULL,NULL,'{\n  "properties": {},\n  "id": "7f2bf7ddf58448f7ae07e3345e7a8b0e",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "03.统一代理网关接口",\n  "createTime": 1784437770682,\n  "updateTime": 1784437772125,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/proxy",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"action\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取 body.action 作为网关动作，其余请求参数转换为下划线命名后透传。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.统一代理网关接口\n// 路由：POST /dws/flowserve/gateway/proxy\n// 业务说明：读取 body.action 作为网关动作，其余请求参数转换为下划线命名后透传。\n/*\n * 云梯网关统一代理\n *\n * 读取 body.action 作为网关动作，其余请求参数转换为下划线命名后透传。\n * GatewayUtils 只承担签名、令牌缓存、HTTP 调用和失效重试；业务参数编排在本脚本完成。\n * 本接口不写本地数据库。\n */\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport cn.hutool.core.util.StrUtil\nimport java.util.Map\nimport java.util.List\n\nvar toUnderline = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toUnderlineCase(keyName + \'\')] = toUnderline(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        // 返回当前业务分支的标准结果。\n        return value.map(item => toUnderline(item))\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\nvar toCamel = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toCamelCase(keyName + \'\')] = toCamel(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        // 返回当前业务分支的标准结果。\n        return value.map(item => toCamel(item))\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\n\nvar requestBody = toUnderline(body || {})\nvar action = requestBody.remove(\'action\')\nif (action == null || (action + \'\').trim() == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'action不能为空\'\n}\n// 调用外部网关并统一处理返回结果与异常。\nreturn toCamel(gatewayUtils.callGatewayApiForAny(action + \'\', requestBody))\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/03.统一代理网关接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d4a7019f5e4a4a92a34543c1f5290004',NULL,NULL,'{\n  "properties": {},\n  "id": "d4a7019f5e4a4a92a34543c1f5290004",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "04.获取用户网关应用",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/userAppInfo",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "Magic 负责当前用户识别、关联查询、首次创建和关系持久化；涉及 gateway_user_app_rela 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.获取用户网关应用\n// 路由：POST /dws/flowserve/gateway/userAppInfo\n// 业务说明：Magic 负责当前用户识别、关联查询、首次创建和关系持久化；涉及 gateway_user_app_rela 等业务表。\n/*\n * 获取当前用户的网关应用\n *\n * Magic 负责当前用户识别、关联查询、首次创建和关系持久化；\n * GatewayUtils 仅负责签名后的网关调用。\n */\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.integration.sso.service.SsoUserLookupService as userService\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\n\nvar userId = StpUtil.getLoginId() + \'\'\nif (userId == null || userId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 401, \'未获取到登录用户信息\'\n}\nvar user = userService.getUserById(userId)\nif (user == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'当前用户不存在\'\n}\nvar applicationName = user.realName + \'-\' + userId\n// 从 MySQL 业务表读取当前有效数据。\nvar relation = db.table(\'gateway_user_app_rela\').where()\n    .eq(\'user_id\', userId).eq(\'is_del\', 0).selectOne()\nvar applicationId = relation?.appId\nif (applicationId == null || applicationId == \'\') {\n    var created\n    try {\n        // 调用外部网关并统一处理返回结果与异常。\n        created = gatewayUtils.callGatewayApi(\'V2CreateApplicationInfo\', {\n            application_name: applicationName\n        })\n    } catch (e) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 502, \'创建网关应用失败: \' + e.message\n    }\n    if (created.error_message != null && created.error_message != \'\') {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, created.error_message\n    }\n    applicationId = created.id\n    if (applicationId == null || applicationId == \'\') {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'创建网关应用返回ID为空\'\n    }\n    var now = new Date()\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'gateway_user_app_rela\').primary(\'tid\').insert({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        app_id: applicationId,\n        user_id: userId,\n        is_del: 0,\n        created_time: now,\n        updated_time: now\n    })\n}\n\nvar result\ntry {\n    // 调用外部网关并统一处理返回结果与异常。\n    result = gatewayUtils.callGatewayApi(\'V2QueryApplicationInfo\', {\n        application_id: applicationId,\n        application_name: applicationName\n    })\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 502, \'查询网关应用失败: \' + e.message\n}\nif (result.error_message != null && result.error_message != \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, result.error_message\n}\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/04.获取用户网关应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d5a7019f5e4a4a92a34543c1f5290005',NULL,NULL,'{\n  "properties": {},\n  "id": "d5a7019f5e4a4a92a34543c1f5290005",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "05.保存网关服务",\n  "createTime": 1784450000000,\n  "updateTime": 1787153758086,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"id\\": \\"2361887157562377213\\",\\n  \\"name\\": \\"获取人员审核列表\\",\\n  \\"version\\": \\"1.0\\",\\n  \\"providerConfig\\": {\\"protocol\\": \\"HTTP\\", \\"address\\": \\"/userPro/planList\\", \\"httpMethod\\": \\"POST\\"},\\n  \\"publishConfig\\": {\\"publishAddress\\": \\"/userPro/planList\\"},\\n  \\"publishParams\\": [{\\"paramName\\": \\"userId\\", \\"paramType\\": \\"string\\", \\"paramPosition\\": \\"query\\", \\"required\\": \\"1\\"}]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"id\\": \\"2361887157562377213\\",\\n  \\"message\\": \\"保存成功\\"\\n}",\n  "description": "保存服务编排服务（POST /dws/flowserve/gateway/save）。写入 api_info_t 服务主表和 api_param_t 参数表；如请求包含 apiFileId/fileContent，则同步 api_file_t.api_id 关联服务主表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.保存网关服务\n// 路由：POST /dws/flowserve/gateway/save\n// 业务说明：保存服务编排服务（POST /dws/flowserve/gateway/save）。写入 api_info_t 服务主表和 api_param_t 参数表；如请求包含 apiFileId/fileContent，则同步 api_file_t.api_id 关联服务主表。\n/*\n * 保存服务登记信息。\n * api_info_t 是服务主表，api_param_t 保存登记参数，\n * api_file_t.api_id 只在存在脚本文件时建立关联。\n */\nimport magicResourceLink\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.json.JSONUtil\nimport tenantRuntime\n\nvar blank = value => value == null || (value + \'\').trim() == \'\'\nvar asJson = value => value == null ? null : JSONUtil.toJsonStr(value)\nvar now = new Date()\nvar tenantId = tenantRuntime.id()\nif (blank(tenantId)) {\n    exit 401, \'当前登录租户无效，请重新登录后再保存服务\'\n}\n\nif (body == null) {\n    exit 400, \'请求参数不能为空\'\n}\n\nvar apiId = body?.id || body?.apiId || body?.tid\nvar serviceName = body?.serviceName || body?.name\nif (blank(serviceName)) {\n    exit 400, \'服务名称不能为空\'\n}\nif (blank(apiId)) {\n    apiId = IdUtil.getSnowflakeNextIdStr()\n}\n\nvar provider = body?.providerConfig == null ? {} : body.providerConfig\nvar publish = body?.publishConfig == null ? {} : body.publishConfig\nvar ext = body?.extendInfo == null ? {} : body.extendInfo\nvar params = body?.publishParams || body?.params || body?.paramList || []\nvar method = body?.method || body?.httpMethod || provider.httpMethod || publish.publishMethod || \'GET\'\nmethod = (method + \'\').toUpperCase()\nvar uri = body?.uri || body?.address || provider.address || publish.publishAddress || body?.publishAddress || \'\'\nvar publishAddress = body?.publishAddress || publish.publishAddress || uri\nvar groupId = body?.groupId || ext.groupId || \'api_service_group_default\'\nvar old = db.table(\'api_info_t\').where().eq(\'tid\', apiId).eq(\'is_del\', 0).selectOne()\n\nvar row = {\n    tid: apiId,\n    resource_id: body?.resourceId || body?.resource_id || apiId,\n    service_name: serviceName,\n    service_code: body?.serviceCode || body?.code || body?.service_code || apiId,\n    service_type: body?.serviceType || body?.type || \'数据服务\',\n    service_desc: body?.serviceDesc || body?.description || ext.apiDescription || \'\',\n    uri: uri,\n    method: method,\n    service_sql: body?.serviceSql || body?.sql || \'\',\n    is_use: body?.isUse == null ? 1 : body.isUse,\n    group_id: groupId,\n    version: body?.version || \'1.0\',\n    status: body?.status || \'draft\',\n    protocol: body?.protocol || provider.protocol || \'HTTP\',\n    address: provider.address || uri,\n    publish_address: publishAddress,\n    publish_address_full: publishAddress,\n    provider_config: asJson(provider),\n    publish_config: asJson(publish),\n    labels: body?.labels || \'\',\n    return_type: ext.returnType || body?.returnType || \'\',\n    share_type: ext.shareType || body?.shareType || \'\',\n    data_domain: ext.dataDomain || \'\',\n    data_category: ext.dataCategory || \'\',\n    data_level: ext.dataLevel || \'\',\n    catalog_id: ext.catalogId || body?.catalogId || \'\',\n    org_id: ext.orgId || body?.orgId || \'\',\n    source_business_name: ext.sourceBusinessName || \'\',\n    source_business_item: ext.sourceBusinessItem || \'\',\n    request_example: ext.requestExample || \'\',\n    response_example: ext.responseExample || \'\',\n    service_create_type: body?.serviceCreateType || body?.service_create_type || \'api\',\n    flow_id: body?.flowId || body?.flow_id || old?.flow_id || old?.flowId || \'\',\n    tenant_id: tenantId,\n    updated_time: now,\n    updated_by: body?.updatedBy || body?.createdBy || \'\'\n}\n\nif (old == null) {\n    row.created_time = now\n    row.created_by = body?.createdBy || \'\'\n    row.is_del = 0\n    db.table(\'api_info_t\').primary(\'tid\').insert(row)\n} else {\n    db.table(\'api_info_t\').primary(\'tid\').update(row, true)\n}\n\n// 参数表采用先软删后重建，保证编辑时删除的参数能准确落库。\n// 扩展属性统一写入 da_prop_t；api_info_t 只保存稳定的物理字段。\nfor (key in ext.keySet()) {\n    var value = ext[key]\n    var propValue = value == null ? null : ((value instanceof java.util.Map || value instanceof java.util.List) ? asJson(value) : value + \'\')\n    var existingProp = db.table(\'da_prop_t\').where().eq(\'parent_id\', apiId).eq(\'data_type\', \'api\').eq(\'prop_name\', key).eq(\'is_del\', 0).selectOne()\n    var prop = { parent_id: apiId, tenant_id: tenantId, prop_name: key, prop_value: propValue, prop_type: \'0\', data_type: \'api\', is_del: 0, updated_time: now }\n    if (existingProp == null) {\n        prop.tid = IdUtil.getSnowflakeNextIdStr()\n        prop.created_time = now\n        db.table(\'da_prop_t\').primary(\'tid\').insert(prop)\n    } else {\n        prop.tid = existingProp.tid\n        db.table(\'da_prop_t\').primary(\'tid\').update(prop, true)\n    }\n}\n\ndb.table(\'api_param_t\').where().eq(\'api_id\', apiId).eq(\'is_del\', 0).update({\n    is_del: 1,\n    updated_time: now\n})\nfor (index, item in params) {\n    db.table(\'api_param_t\').primary(\'tid\').insert({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        api_id: apiId,\n        param_name: item.paramName || item.param_name || \'\',\n        param_desc: item.description || item.paramDesc || item.param_desc || \'\',\n        param_type: item.paramType || item.param_type || \'\',\n        param_position: item.paramPosition || item.param_position || \'\',\n        required_flag: item.required || item.requiredFlag || \'\',\n        default_value: item.defaultValue || item.default_value || \'\',\n        showcase_value: item.showcaseValue || item.showcase_value || \'\',\n        param_scope: item.res == 1 ? \'response\' : \'request\',\n        sort_no: index + 1,\n        created_time: now,\n        tenant_id: tenantId,\n    updated_time: now,\n        is_del: 0\n    })\n}\n\n// 若调用方传入脚本文件，则建立 api_file_t.api_id 关联；普通登记服务不会强行创建脚本。\nif (!blank(body?.apiFileId)) {\n    magicResourceLink.link(body.apiFileId + \'\', apiId + \'\')\n}\n\nreturn {\n    id: apiId,\n    tid: apiId,\n    message: \'保存成功\'\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/05.保存网关服务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d6a7019f5e4a4a92a34543c1f5290006',NULL,NULL,'{\n  "properties": {},\n  "id": "d6a7019f5e4a4a92a34543c1f5290006",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "06.API调用概览",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/apiCallOverview",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按 API 标识读取网关调用概览，将网关字段转换为页面字段并更新对应的接口检索投影。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.API调用概览\n// 路由：POST /dws/flowserve/gateway/apiCallOverview\n// 业务说明：按 API 标识读取网关调用概览，将网关字段转换为页面字段并更新对应的接口检索投影。\n/*\n * API 调用概览\n *\n * 网关参数使用下划线格式，页面响应使用驼峰格式。统计结果合并到现有\n * ES API 文档后统一保存，避免只写统计字段导致详情投影丢失。\n */\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport \'@/common/saveGatewayAsset\' as saveGatewayAsset\nimport java.util.List\nimport java.util.Map\n\nvar convert\nconvert = (value, underline) => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            var key = underline\n                ? StrUtil.toUnderlineCase(keyName + \'\')\n                : StrUtil.toCamelCase(keyName + \'\')\n            result[key] = convert(value[keyName], underline)\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(convert(item, underline))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar apiId = body?.apiId\nif (apiId == null || apiId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'apiId不能为空\'\n}\n// 调用外部网关并统一处理返回结果与异常。\nvar overview = convert(gatewayUtils.callGatewayApi(\'V2ApiCallOverview\', convert(body, true)), false)\noverview.successPercent = 100 - ((overview.errorPercent || \'0\')::double)\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar document = esCommonService.getDocument(\'dataassets\', apiId + \'\') || {}\nfor (entry in overview.entrySet()) {\n    document[keyName] = value[keyName]\n}\nsaveGatewayAsset(apiId, document, document.catalogId)\n// 返回当前业务分支的标准结果。\nreturn overview\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/06.API调用概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d7a7019f5e4a4a92a34543c1f5290007',NULL,NULL,'{\n  "properties": {},\n  "id": "d7a7019f5e4a4a92a34543c1f5290007",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "07.API调用统计",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/callStatistics",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "将页面筛选参数转换为网关参数，调用网关统计接口，再把返回数据转换为页面使用的字段结构。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.API调用统计\n// 路由：POST /dws/flowserve/gateway/callStatistics\n// 业务说明：将页面筛选参数转换为网关参数，调用网关统计接口，再把返回数据转换为页面使用的字段结构。\n/*\n * API 调用统计列表\n *\n * Magic 负责页面参数到网关下划线参数的递归转换；\n * GatewayUtils 只执行签名后的网关调用。\n */\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport java.util.List\nimport java.util.Map\n\nvar toUnderline\ntoUnderline = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toUnderlineCase(keyName + \'\')] = toUnderline(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(toUnderline(item))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\ntry {\n    // 调用外部网关并统一处理返回结果与异常。\n    var response = gatewayUtils.callGatewayApiForAny(\'V2CallStatistics\', toUnderline(body || {}))\n    if (response instanceof Map && response.result_code != null && response.result_code != \'\') {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 502, \'网关调用统计返回异常: \' + response.result_code\n    }\n    // 返回当前业务分支的标准结果。\n    return response\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 502, \'查询网关调用统计失败: \' + e.message\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/07.API调用统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d8a7019f5e4a4a92a34543c1f5290008',NULL,NULL,'{\n  "properties": {},\n  "id": "d8a7019f5e4a4a92a34543c1f5290008",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "08.服务日志列表",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/serviceLogList",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "将页面查询条件转换为网关参数，读取服务调用日志并转换字段格式；不修改本地资产。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.服务日志列表\n// 路由：POST /dws/flowserve/gateway/serviceLogList\n// 业务说明：将页面查询条件转换为网关参数，读取服务调用日志并转换字段格式；不修改本地资产。\n/*\n * 服务日志列表\n *\n * 页面请求转下划线，网关响应转驼峰；只做查询，不修改本地资产。\n */\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport java.util.List\nimport java.util.Map\n\nvar convert\nconvert = (value, underline) => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            var key = underline\n                ? StrUtil.toUnderlineCase(keyName + \'\')\n                : StrUtil.toCamelCase(keyName + \'\')\n            result[key] = convert(value[keyName], underline)\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(convert(item, underline))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\ntry {\n    // 调用外部网关并统一处理返回结果与异常。\n    return convert(gatewayUtils.callGatewayApi(\'V2ServiceLogList\', convert(body || {}, true)), false)\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 502, \'查询网关服务日志失败: \' + e.message\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/08.服务日志列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d9a7019f5e4a4a92a34543c1f5290009',NULL,NULL,'{\n  "properties": {},\n  "id": "d9a7019f5e4a4a92a34543c1f5290009",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "09.服务日志详情",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/serviceLogDetail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据日志标识查询网关服务调用详情，转换请求和响应字段格式后返回页面。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.服务日志详情\n// 路由：POST /dws/flowserve/gateway/serviceLogDetail\n// 业务说明：根据日志标识查询网关服务调用详情，转换请求和响应字段格式后返回页面。\n/*\n * 服务日志详情\n *\n * 页面请求转下划线，网关响应转驼峰；只做查询，不修改本地资产。\n */\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport java.util.List\nimport java.util.Map\n\nvar convert\nconvert = (value, underline) => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            var key = underline\n                ? StrUtil.toUnderlineCase(keyName + \'\')\n                : StrUtil.toCamelCase(keyName + \'\')\n            result[key] = convert(value[keyName], underline)\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(convert(item, underline))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\ntry {\n    // 调用外部网关并统一处理返回结果与异常。\n    return convert(gatewayUtils.callGatewayApi(\'V2ServiceLogDetail\', convert(body || {}, true)), false)\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 502, \'查询网关服务日志详情失败: \' + e.message\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/09.服务日志详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('daa7019f5e4a4a92a34543c1f5290010',NULL,NULL,'{\n  "properties": {},\n  "id": "daa7019f5e4a4a92a34543c1f5290010",\n  "script": null,\n  "groupId": "2baeb325734a4f348df335661b205952",\n  "name": "10.构建网关服务",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/buildApi",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "Magic 负责构建平台参数转换、响应校验、网关详情补齐和本地资产持久化；使用请求参数 isEmpty。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.构建网关服务\n// 路由：POST /dws/flowserve/gateway/buildApi\n// 业务说明：Magic 负责构建平台参数转换、响应校验、网关详情补齐和本地资产持久化；使用请求参数 isEmpty。\n/*\n * 构建网关服务\n *\n * Magic 负责构建平台参数转换、响应校验、网关详情补齐和本地资产持久化。\n * HTTP 模块与 GatewayUtils 分别承担构建平台和网关的运行时调用。\n */\nimport cn.hutool.core.util.StrUtil\nimport http\nimport jsons\nimport \'@/common/gatewayApiDetail\' as gatewayApiDetail\nimport \'@/common/saveGatewayAsset\' as saveGatewayAsset\nimport java.util.List\nimport java.util.Map\nimport org.springframework.core.env.Environment as environment\n\nvar toUnderline\ntoUnderline = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toUnderlineCase(keyName + \'\')] = toUnderline(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(toUnderline(item))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\n\n// 解析请求体并为可选参数设置默认值。\nif (body == null || body.isEmpty()) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'请求参数不能为空\'\n}\nvar requestBody = toUnderline(body)\nvar extendInfo = requestBody.extend_info\nvar serviceInfo = requestBody.service_info\nvar catalogId = extendInfo?.catalog_id\nif (catalogId == null || catalogId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'未选择服务目录\'\n}\nrequestBody.remove(\'extend_info\')\n\nvar raw = http.connect(environment.getProperty(\'gateway.buildapi.url\') + \'/openapi/api/sync\')\n    .contentType(\'application/json\')\n    .body(jsons.toJSONStr(requestBody))\n    .post()\n    .getBody()\nvar response = raw instanceof Map ? raw : jsons.parseObj(raw + \'\')\nif (response.result_code != \'sys-200\' || response.data == null || response.data.size() == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, response.result_code || \'服务构建失败\'\n}\nvar apiId = response.data[0].api_id\nif (apiId == null || apiId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'服务构建未返回API ID\'\n}\n\nvar detail = gatewayApiDetail(apiId)\nif (detail == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'资源不存在，无法获取API详情\'\n}\ndetail.catalogId = catalogId\ndetail.serviceName = serviceInfo?.name || detail.name || \'\'\ndetail.serviceCreateType = \'apiBuild\'\ndetail.buildApiInfo = body\nsaveGatewayAsset(apiId, detail, catalogId)\n// 返回当前业务分支的标准结果。\nreturn \'服务构建成功\'\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/01.服务编排/08.服务管理/10.构建网关服务.ms');
