INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ba237629207c463496217f6f8ddb5e27',NULL,NULL,'{\n  "properties": {},\n  "id": "ba237629207c463496217f6f8ddb5e27",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "01.我的共享",\n  "createTime": 1782955344058,\n  "updateTime": 1787153756999,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/myShare",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"total\\": 1,\\n        \\"list\\": [\\n            {\\n                \\"tid\\": \\"14254e9a22e941168bc119e4581fa1e0\\",\\n                \\"applyFormId\\": \\"dadce475dea5404fa11cf0d8348b6317\\",\\n                \\"catalogId\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n                \\"sortNo\\": 0,\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdTime\\": \\"2026-03-24 16:11:56\\",\\n                \\"updatedBy\\": \\"1995681734511165441\\",\\n                \\"updatedTime\\": \\"2026-03-24 16:11:56\\",\\n                \\"createdBy\\": \\"1995681734511165441\\",\\n                \\"isDel\\": 0,\\n                \\"catalogOrgId\\": \\"2026503859392086017\\",\\n                \\"catalogOrgPath\\": null,\\n                \\"catalogName\\": \\"生成目录信息(sys_gen_info)\\"\\n            }\\n        ]\\n    }\\n}",\n  "description": "按当前登录人员筛选其发起或参与的共享申请，结合关键词与流程状态返回分页列表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.我的共享\n// 路由：POST /dws/market/myShare\n// 业务说明：按当前登录人员筛选其发起或参与的共享申请，结合关键词与流程状态返回分页列表。\nimport "@post:/sym/user/me" as me;\nimport "@/common/localCache" as localCache\n\n\n// 解析请求体并为可选参数设置默认值。\nvar pageNum = body?.pageNum::int(1)\nvar pageSize = body?.pageSize::int(20)\nvar keyword = body?.keyword\nvar flowStatus = body?.flowStatus\n\nvar offsetLimit = pageNum == 0 ? 0 : (pageNum - 1) * pageSize\n\nvar userInfo = me()\nvar sharelyOrgId = userInfo?.orgId\n\nif (sharelyOrgId == null || sharelyOrgId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "当前用户组织信息为空"\n}\n\nvar sql = """\n    select * from data_apply_form_catalog_rela  rela\n    where \n    rela.catalog_org_id = #{sharelyOrgId}\n    and is_del = 0\n    order by created_time\n"""\n\n// 从 MySQL 业务表读取当前有效数据。\nvar pageList = db.page(sql,pageSize,offsetLimit)\n\nif(pageList != null && pageList.list != null){\n    pageList.list.each( item ->{\n        item.catalogName = localCache(item.catalogId, "catalog")\n    })\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    total: pageList.total,\n    list: pageList.list\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/01.我的共享.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('398a23638e464a368050b86c3813e070',NULL,NULL,'{\n  "properties": {},\n  "id": "398a23638e464a368050b86c3813e070",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "02.我的申请",\n  "createTime": 1782955344070,\n  "updateTime": 1787153757033,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/myApply",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"sortField\\": \\"createdTime\\",\\n    \\"sortDir\\": \\"desc\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"total\\": 1,\\n        \\"list\\": [\\n            {\\n                \\"tid\\": \\"14254e9a22e941168bc119e4581fa1e0\\",\\n                \\"applyFormId\\": \\"dadce475dea5404fa11cf0d8348b6317\\",\\n                \\"catalogId\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n                \\"sortNo\\": 0,\\n                \\"tenantId\\": null,\\n                \\"revision\\": null,\\n                \\"createdTime\\": \\"2026-03-24 16:11:56\\",\\n                \\"updatedBy\\": \\"1995681734511165441\\",\\n                \\"updatedTime\\": \\"2026-03-24 16:11:56\\",\\n                \\"createdBy\\": \\"1995681734511165441\\",\\n                \\"isDel\\": 0,\\n                \\"catalogName\\": \\"生成目录信息(sys_gen_info)\\"\\n            }\\n        ]\\n    }\\n}",\n  "description": "按请求目标与业务状态执行我的申请，返回本次操作结果；使用请求参数 pageNum、pageSize、keyword、flowStatus；涉及 data_apply_form_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.我的申请\n// 路由：POST /dws/market/myApply\n// 业务说明：按请求目标与业务状态执行我的申请，返回本次操作结果；使用请求参数 pageNum、pageSize、keyword、flowStatus；涉及 data_apply_form_t 等业务表。\nimport "@post:/sym/user/me" as me;\nimport "@/common/localCache" as localCache\n\n\n// 解析请求体并为可选参数设置默认值。\nvar pageNum = body?.pageNum::int(1)\nvar pageSize = body?.pageSize::int(20)\nvar keyword = body?.keyword\nvar flowStatus = body?.flowStatus\n\nvar offsetLimit = pageNum == 0 ? 0 : (pageNum - 1) * pageSize\n\nvar userInfo = me()\nvar applyOrgId = userInfo?.orgId\n\nif (applyOrgId == null || applyOrgId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "当前用户组织信息为空"\n}\n\nvar sql = """\n    select * from data_apply_form_catalog_rela  rela\n    where \n    rela.apply_form_id in (select tid from data_apply_form_t where apply_org_id = #{applyOrgId} and is_del = 0)\n    order by created_time\n"""\n\n// 从 MySQL 业务表读取当前有效数据。\nvar pageList = db.page(sql,pageSize,offsetLimit)\n\nif(pageList != null && pageList.list != null){\n    pageList.list.each( item ->{\n        item.catalogName = localCache(item.catalogId, "catalog")\n    })\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    total: pageList.total,\n    list: pageList.list\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/02.我的申请.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b78cf957a41645ccbea4fda1f6c6b9e9',NULL,NULL,'{\n  "properties": {},\n  "id": "b78cf957a41645ccbea4fda1f6c6b9e9",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "03.收藏接口",\n  "createTime": 1782955344081,\n  "updateTime": 1787153757069,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/collect",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"catalogId\\": \\"11\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"id\\": \\"1995681734511165441\\",\\n        \\"realName\\": \\"叶华\\",\\n        \\"userName\\": \\"zn\\",\\n        \\"phone\\": \\"13222222222\\",\\n        \\"gender\\": \\"2\\",\\n        \\"orgId\\": \\"2026503859392086017\\",\\n        \\"orgName\\": \\"福建省公安\\",\\n        \\"orgRootId\\": \\"2026503859392086017\\",\\n        \\"serialNumber\\": \\"0006\\",\\n        \\"orgPath\\": \\"福建省公安\\",\\n        \\"roles\\": [\\n            \\"admin\\"\\n        ],\\n        \\"perms\\": [\\n            \\"sym:asset:add\\"\\n        ]\\n    }\\n}",\n  "description": "按当前登录人员和目录标识检查已有收藏，再新增或取消收藏记录并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.收藏接口\n// 路由：POST /dws/market/collect\n// 业务说明：按当前登录人员和目录标识检查已有收藏，再新增或取消收藏记录并返回处理结果。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport "@post:/sym/user/me" as me\n\n// ========== 获取请求参数 ==========\nvar catalogId      = body?.catalogId\n\nvar userInfo = me()\n\nvar applyUserId    = userInfo.id\nvar applyUserName  = userInfo.userName\nvar applyOrgId  = userInfo.orgId\n\n// ========== 参数校验 ==========\nif (catalogId == null || catalogId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'catalog_id不能为空\'\n}\n\n// ========== 查询是否已收藏 ==========\nvar existing = db.table(\'data_market_collect_t\')\n    .where()\n    .eq(\'catalog_id\', catalogId)\n    .eq(\'apply_org_id\', applyOrgId)\n    .selectOne()\n\nif (existing != null) {\n    // 已收藏 -> 取消收藏（物理删除）\n    db.table(\'data_market_collect_t\')\n        .where()\n        .eq(\'tid\', existing.tid)\n        .delete()\n    log.info(\'取消收藏成功, catalog_id: {}, apply_org_id: {}\', catalogId, applyOrgId)\n    // 返回当前业务分支的标准结果。\n    return false\n} else {\n    // 未收藏 -> 新增收藏\n    var tid = IdUtil.getSnowflakeNextIdStr()\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_market_collect_t\').primary(\'tid\').insert({\n        tid: tid,\n        catalog_id: catalogId,\n        apply_user_id: applyUserId,\n        apply_user_name: applyUserName,\n        apply_org_id: applyOrgId,\n        org_tree_path: userInfo.serialNumber\n    })\n    log.info(\'收藏成功, tid: {}, catalog_id: {}, apply_user_id: {}\', tid, catalogId, applyUserId)\n    // 返回当前业务分支的标准结果。\n    return true\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/03.收藏接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f12fde8d078541abb7083a4cfc6fb3b4',NULL,NULL,'{\n  "properties": {},\n  "id": "f12fde8d078541abb7083a4cfc6fb3b4",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "04.浏览接口",\n  "createTime": 1782955344092,\n  "updateTime": 1784437771759,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/view",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"85368b91972c4a35b83b8fa73e34e740\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"id\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n            \\"tid\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n            \\"tenantId\\": null,\\n            \\"assetType\\": \\"catalog\\",\\n            \\"assetStatus\\": \\"2\\",\\n            \\"flowStatus\\": \\"2\\",\\n            \\"regTime\\": \\"2026-02-25 13:36:23\\",\\n            \\"createdTime\\": \\"2026-02-25 13:36:23\\",\\n            \\"updatedTime\\": \\"2026-03-13 11:54:35\\",\\n            \\"regTime_date\\": \\"2026-02-25 13:36:23\\",\\n            \\"createdTime_date\\": \\"2026-02-25 13:36:23\\",\\n            \\"updatedTime_date\\": \\"2026-03-16 09:30:54\\",\\n            \\"dataCatalogNum\\": null,\\n            \\"dataRegionScope\\": \\"1\\",\\n            \\"businessGuideName\\": \\"广电新媒体用户数据统计分析办事指南（2025版）\\",\\n            \\"targetTableName\\": \\"生成表信息\\",\\n            \\"sourceBusinessName\\": \\"国产电视剧片审查\\",\\n            \\"targetDbType\\": \\"mysql\\",\\n            \\"policeType\\": \\"public_security\\",\\n            \\"usage\\": \\"用于广电总局及省级广电机构开展新媒体运营效果评估、内容监管、用户需求分析，为新媒体内容生产、分发策略优化提供数据支撑，仅向各级广电管理部门授权开放使用。\\",\\n            \\"targetTableId\\": \\"f370414d9ff64565a9fa06cbaa13d861\\",\\n            \\"catalogName\\": \\"生成目录信息(sys_gen_info)\\",\\n            \\"recordCount\\": \\"1\\",\\n            \\"concatName\\": \\"1\\",\\n            \\"dataDomain\\": \\"11\\",\\n            \\"dataProcessLevel\\": \\"4\\",\\n            \\"manageUnit\\": \\"2026505033717514242\\",\\n            \\"sourceBusinessItem\\": \\"节目审核-初审\\",\\n            \\"targetDbId\\": \\"62d25cc8bf1344d6b9f41fed23af4eaf\\",\\n            \\"catalogNameEn\\": \\"sys_gen_info\\",\\n            \\"dataSourceType\\": \\"sensitive\\",\\n            \\"sourceTableId\\": \\"fb64c63470c14ee286a29fcea82a259c\\",\\n            \\"appId\\": \\"837fa16f795444b29c89ae7973cdd87f\\",\\n            \\"dbId\\": \\"38ef1b566eb4477ebfc07b4c0c8aa973\\",\\n            \\"orgId\\": \\"2026505347749249025\\",\\n            \\"concatPhone\\": \\"13222222222\\",\\n            \\"dataUpdateFreq\\": \\"2\\",\\n            \\"tableLevel\\": \\"special\\",\\n            \\"dataLevel\\": \\"1\\",\\n            \\"updateCycle\\": \\"monthly\\",\\n            \\"assetDesc\\": \\"该数据目录归集全国广电新媒体平台用户行为核心数据，涵盖用户基础信息、内容访问记录、互动行为（点赞/评论/分享）、收视时长等维度，数据覆盖国家级新媒体平台及31个省级分平台，支撑广电新媒体运营效果分析、内容精准推送、用户画像构建等核心业务场景。\\",\\n            \\"dataTheme\\": \\"item,vehicle,track\\",\\n            \\"dataSecurityLevel\\": \\"1\\",\\n            \\"dataTimeScope\\": \\"2026-02-10 00:00:00,2026-03-18 00:00:00\\",\\n            \\"shareType\\": \\"1\\",\\n            \\"openType\\": \\"是\\",\\n            \\"dataCategory\\": \\"01020201\\",\\n            \\"businessBasicCatalogName\\": \\"广电网络视听数据资源基本目录\\",\\n            \\"resourceSource\\": \\"video\\",\\n            \\"tableType\\": \\"数据表\\",\\n            \\"orgPath\\": \\"000600020001\\",\\n            \\"publishStatus\\": \\"1\\",\\n            \\"catalogType\\": \\"部门目录\\",\\n            \\"viewCount\\": 2\\n        }\\n    ]\\n}",\n  "description": "读取目标数据目录并更新浏览计数，返回最新的目录展示资料。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.浏览接口\n// 路由：POST /dws/market/view\n// 业务说明：读取目标数据目录并更新浏览计数，返回最新的目录展示资料。\nimport tenantEs;\nimport "@post:/dst/catalog/list" as assetList;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\n\nvar list = assetList();\nif (list.size() === 1){\n    var data = list.each(item=>item.put(\'viewCount\',item.viewCount ? item.viewCount + 1 : 1))[0]\n   // 解析请求体并为可选参数设置默认值。\n   esCommonService.saveOrUpdate("dataassets", body.tid ,jsons.toJSONStr(data), false);\n}\n// 返回当前业务分支的标准结果。\nreturn list;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/04.浏览接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7ddfe8a23a524cc0ad8f801cb57b7381',NULL,NULL,'{\n  "properties": {},\n  "id": "7ddfe8a23a524cc0ad8f801cb57b7381",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "05.聚合统计",\n  "createTime": 1782955344101,\n  "updateTime": 1784437771760,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/count",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"query\\": [\\n        {\\n            \\"term\\": {\\n                \\"assetType\\": \\"table\\"\\n            }\\n        }\\n    ],\\n    \\"aggs\\": {\\n        \\"orgPath\\": {\\n            \\"terms\\": {\\n                \\"field\\": \\"orgPath\\",\\n                \\"size\\": 10000\\n            }\\n        }\\n    },\\n    \\"indexType\\": \\"app\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 100120,\\n    \\"msg\\": \\"user_no_login\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "根据请求中的检索条件、索引类型和聚合定义，查询当前租户的检索索引并返回聚合桶。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.聚合统计\n// 路由：POST /dws/market/count\n// 业务说明：根据请求中的检索条件、索引类型和聚合定义，查询当前租户的检索索引并返回聚合桶。\nimport tenantEs;\nimport log;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport \'@/common/configData\' as configData\n\n// 解析请求体并为可选参数设置默认值。\nvar {query, indexType, aggs } = body;\nindexType = indexType || configData().es_dataassets\n\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar existInxex = esCommonService.indexExists("dataassets");\nif(!existInxex){\n    // 返回当前业务分支的标准结果。\n    return {}\n}\n\nvar dsl = {\n    query: {\n        bool: {\n            must: query\n        }\n    },\n};\n\n\nif (aggs !== null){\n    dsl["aggs"] = aggs\n} \n// 根据`DSL`语句搜索\nvar searchlist = tenantEs.index(indexType).search(dsl);\n\nvar data =  searchlist.aggregations\nvar result = {}\ndata.each((key, val) => {\n    result[key] = {}\n        val.buckets?.each(item => {\n            result[key][item.key] = item.doc_count\n        })\n})\n\n// 返回当前业务分支的标准结果。\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/05.聚合统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('624a0191565640a18c81c131ab0b4228',NULL,NULL,'{\n  "properties": {},\n  "id": "624a0191565640a18c81c131ab0b4228",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "06.购物车(保存或修改)",\n  "createTime": 1782955344110,\n  "updateTime": 1787153757107,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/shoppingCard",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"catalogId\\": \\"0d50a16cf9b5458398a22f6fa158ea57\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"该资产已在购物车中\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "校验请求资料后执行购物车(保存或修改)，返回保存或配置结果；使用请求参数 tid、catalogId；涉及 data_market_shopping_cart_t、data_apply_form_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.购物车(保存或修改)\n// 路由：POST /dws/market/shoppingCard\n// 业务说明：校验请求资料后执行购物车(保存或修改)，返回保存或配置结果；使用请求参数 tid、catalogId；涉及 data_market_shopping_cart_t、data_apply_form_t 等业务表。\n// 加购条件：当前用户未申请 未加购的目录\nimport cn.hutool.core.util.IdUtil\nimport log\nimport "@post:/sym/user/me" as me\nimport tenantRuntime\n// ========== 获取请求参数 ==========\nvar tid           = body?.tid\nvar catalogId     = body?.catalogId\n\nvar userInfo = me()\nvar applyUserId    = userInfo.id\nvar applyUserName  = userInfo.userName\nvar applyOrgId  = userInfo.orgId\n\nvar tenantId      = tenantRuntime.id()\nvar isUpdate      = tid != null && tid != \'\'\nvar now           = new Date()\n\n// ========== 参数校验 ==========\nif (catalogId == null || catalogId == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'catalog_id不能为空\'\n}\n\n\n// ========== 业务逻辑 ==========\nif (isUpdate) {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_market_shopping_cart_t\').primary(\'tid\').update({\n        catalog_id:      catalogId,\n        apply_user_id:   applyUserId,\n        apply_org_id:    applyOrgId,\n        apply_user_name: applyUserName,\n        updated_by:      applyUserId,\n        updated_time:    now\n    })\n    log.info(\'更新购物车成功, tid: {}\', tid)\n} else {\n    // 同一部门对同一资产只允许加入一次\n    var existing = db.table(\'data_market_shopping_cart_t\')\n        .where()\n        .eq(\'catalog_id\', catalogId)\n        .eq(\'apply_org_id\', applyOrgId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n    if (existing != null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'该资产已在购物车中\'\n    }\n\n     // 校验该目录是否已存在有效申请单（草稿/审批中/已通过）\n    var appliedForm = db.table(\'data_apply_form_t\')\n                        .where()\n                        .eq(\'apply_org_id\', applyOrgId)\n                        .like(\'catalog_ids\', `%${catalogId}%`)\n                        .in(\'flow_status\', [0,1,2])\n                        .eq(\'is_del\', 0)\n                        .select();\n    if (appliedForm != null && appliedForm.size() > 0) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'该目录已申请，不予加购\'\n    }\n\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_market_shopping_cart_t\').primary(\'tid\').insert({\n        tid:             tid,\n        catalog_id:      catalogId,\n        apply_user_id:   applyUserId,\n        apply_org_id:   applyOrgId,\n        apply_user_name: applyUserName,\n        tenant_id:       tenantId,\n        created_by:      applyUserId,\n        created_time:    now,\n        updated_by:      applyUserId,\n        updated_time:    now,\n        is_del:          0\n    })\n    log.info(\'新增购物车成功, tid: {}\', tid)\n}\n\n// 返回当前业务分支的标准结果。\nreturn tid\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/06.购物车(保存或修改).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9fc031d411354d8baff7006b11f5ad0a',NULL,NULL,'{\n  "properties": {},\n  "id": "9fc031d411354d8baff7006b11f5ad0a",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "07.购物车列表",\n  "createTime": 1782955344119,\n  "updateTime": 1787153757165,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/shoppingCardList",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"keyword\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": []\\n}",\n  "description": "按当前登录人员和关键词读取数据超市购物车记录，补充目录展示资料后返回列表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.购物车列表\n// 路由：POST /dws/market/shoppingCardList\n// 业务说明：按当前登录人员和关键词读取数据超市购物车记录，补充目录展示资料后返回列表。\nimport "@post:/sym/user/me" as me;\nimport "@post:/dws/market/list" as marketList;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\n\n\nvar userInfo = me()\nvar applyUserId    = userInfo.id\nvar applyOrgId    = userInfo.orgId\n\n// 从 MySQL 业务表读取当前有效数据。\nvar cars = db.table(\'data_market_shopping_cart_t\')\n                .where()\n                .eq(\'apply_org_id\', applyOrgId)\n                .eq(\'is_del\', 0)\n                .select();\n\nvar query = [\n        {\n            "terms": {\n                "tid": cars.map(el=>el.catalogId)\n            }\n        }\n    ]\n// 解析请求体并为可选参数设置默认值。\nif (body.keyword){\n    query.push({\n        "wildcard": {\n            "catalogName": `*${body.keyword}*`\n        }\n    })\n}\nbody = {\n    query\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nexistInxex = esCommonService.indexExists("dataassets");\nif(!existInxex){\n    // 返回当前业务分支的标准结果。\n    return []\n}\n\nvar {list} = marketList()\n\nlist = list.map(el => {\n    var item = cars.find(c => c.catalogId === el.tid)\n    // 返回当前业务分支的标准结果。\n    return {\n        ...el,\n        shoppingCarId: item.tid, // 加购记录tid\n        addTime: item.createdTime, // 加购时间\n    }\n})\n\n// 返回当前业务分支的标准结果。\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/07.购物车列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8cc51c590a964ad2b9a5b76656c5b3ce',NULL,NULL,'{\n  "properties": {},\n  "id": "8cc51c590a964ad2b9a5b76656c5b3ce",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "08.购物车移除",\n  "createTime": 1782955344127,\n  "updateTime": 1784437771765,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/shoppingCardRemove",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"6b6ba3bc8ef744d3a2be7213b2f47073\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按目标标识和当前状态执行购物车移除，返回处理结果；使用请求参数 tid；涉及 data_market_shopping_cart_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.购物车移除\n// 路由：POST /dws/market/shoppingCardRemove\n// 业务说明：按目标标识和当前状态执行购物车移除，返回处理结果；使用请求参数 tid；涉及 data_market_shopping_cart_t 等业务表；执行数据库写入并返回处理结果。\nimport log\n\n// ========== 获取请求参数 ==========\nvar tid = body?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\n// ========== 业务逻辑 ==========\nvar now    = new Date()\n// 从 MySQL 业务表读取当前有效数据。\nvar result = db.table(\'data_market_shopping_cart_t\')\n    .where().eq(\'tid\', tid).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: now })\n\nif (result == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'购物车数据不存在\'\n}\n\nlog.info(\'移除购物车成功, tid: {}\', tid)\n// 返回当前业务分支的标准结果。\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/08.购物车移除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('597176b6460544c395498e374bf8bfe8',NULL,NULL,'{\n  "properties": {},\n  "id": "597176b6460544c395498e374bf8bfe8",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "09.资产申请单保存更新",\n  "createTime": 1782955344136,\n  "updateTime": 1787153757200,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applyForm/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"30253579e54d4061bd95c7af602e17e7\\",\\n    \\"type\\": \\"catalogSubscribe\\",\\n    \\"propList\\": {\\n        \\"tid\\": \\"30253579e54d4061bd95c7af602e17e7\\",\\n        \\"applyName\\": \\"完成剧申报数据目录(res_1772095968985_copy28989)\\",\\n        \\"applyOrgId\\": \\"2026505033717514242\\",\\n        \\"usci\\": \\"9111000071780321XQ\\",\\n        \\"applyType\\": \\"政务服务\\",\\n        \\"applyTime\\": \\"2026-04-08 16:06:53\\",\\n        \\"userName\\": \\"33\\",\\n        \\"applicantName\\": \\"zeng343\\",\\n        \\"userPhone\\": \\"SFS\\",\\n        \\"applicantPhone\\": \\"EEERFE\\",\\n        \\"userEmail\\": \\"3333\\",\\n        \\"applicantEmail\\": \\"3334\\",\\n        \\"applyResource\\": [\\n            \\"685ee1e783064ff8a9d7b3d08c5fe89a\\"\\n        ],\\n        \\"useTitle\\": \\"测试\\",\\n        \\"averageFrequency\\": \\"测试\\",\\n        \\"peakFrequency\\": \\"测试\\",\\n        \\"useTime\\": \\"2026-07-20 10:00:00\\",\\n        \\"useDays\\": \\"测试\\",\\n        \\"otherRequests\\": \\"测试\\",\\n        \\"applyBasis\\": \\"测试\\",\\n        \\"appId\\": \\"a60c267ab6c1416d93e5965f0c2c15b5\\",\\n        \\"useScope\\": \\"1\\",\\n        \\"sceneType\\": \\"1\\",\\n        \\"businessScene\\": \\"SSSS\\"\\n    }\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"b71ef91ddcc940a99b220cc3d7cd9120\\"\\n    }\\n}",\n  "description": "1. 保存主表 data_apply_form_t；使用请求参数 tid、applyName、type、propList。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.资产申请单保存更新\n// 路由：POST /dws/market/applyForm/saveOrUpdate\n// 业务说明：1. 保存主表 data_apply_form_t；使用请求参数 tid、applyName、type、propList。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport jsons\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport "@post:/sym/user/me" as me\nimport tenantRuntime\n/**\n * 保存或更新申请表单\n * POST /api/apply/form/saveOrUpdate\n *\n * 业务说明：\n *   1. 保存主表 data_apply_form_t\n *   2. 保存动态属性 da_prop_t（对比新旧差量更新）\n *   3. apply_resource 数组拆分存入 data_apply_form_catalog_rela（差量同步）\n *   4. 同步写入 ES 索引 dataassets_apply_form\n *\n * 请求参数示例：\n * {\n *   "tid": "",\n *   "apply_user_id": "u001",\n *   "apply_user_name": "张三",\n *   "type": "apply",\n *   "tenant_id": "t001",\n *   "apply_resource": ["catalogId1", "catalogId2"],\n *   "propList": {\n *     "remark": "备注内容",\n *     "priority_num": 1,\n *     "expire_date": "2026-12-31"\n *   }\n * }\n */\n\n// ========== 获取请求参数 ==========\nvar tid           = body?.tid\n\nvar userInfo = me()\n\nvar applyUserId    = userInfo.id\nvar applyUserName  = userInfo.id\nvar applyOrgId     = userInfo.orgId\n\nvar applyName     = body?.applyName\nvar type          = body?.type\nvar tenantId      = tenantRuntime.id()\nvar applyResource = body?.propList?.applyResource  // Array, e.g. ["111","222"]\nvar propList      = body?.propList\nvar isUpdate      = tid != null && tid != \'\'\nvar now           = new Date()\n\n// ========== 参数校验 ==========\nif (tid == null || tid == \'\') {\n    // exit 500, \'tid不能为空\'\n}\n\n// ========== 工具函数：属性类型推断 ==========\nvar getPropType = (key) => {\n    if (key == null) {\n        // 返回当前业务分支的标准结果。\n        return \'0\'\n    }\n    if (key.endsWith(\'_date\')) {\n        // 返回当前业务分支的标准结果。\n        return \'4\'  // 日期类型\n    }\n    if (key.endsWith(\'_num\')) {\n        // 返回当前业务分支的标准结果。\n        return \'1\'  // 数字类型\n    }\n    if (key.endsWith(\'_file\')) {\n        // 返回当前业务分支的标准结果。\n        return \'5\'  // 文件类型\n    }\n    if (key.endsWith(\'_dict\')) {\n        // 返回当前业务分支的标准结果。\n        return \'3\'  // 字典类型\n    }\n    if (key.endsWith(\'_range\')) {\n        // 返回当前业务分支的标准结果。\n        return \'6\'  // 日期区间类型\n    }\n    if (key.endsWith(\'_time\')) {\n        // 返回当前业务分支的标准结果。\n        return \'7\'  // 时间区间类型\n    }\n    // 返回当前业务分支的标准结果。\n    return \'0\'  // 默认字符串类型\n}\n\n\nvar getRealPropName = (key) => {\n    if (key == null) {\n        // 返回当前业务分支的标准结果。\n        return key\n    }\n    var suffixes = [\'_date\', \'_num\', \'_file\', \'_dict\', \'_range\', \'_time\']\n    for (suffix in suffixes) {\n        if (key.endsWith(suffix)) {\n            // 返回当前业务分支的标准结果。\n            return key.substring(0, key.length() - suffix.length())\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return key\n}\n\n\n// ========== 1. 处理 apply_resource -> catalog_ids ==========\nvar catalogIds = \'\'\nif (applyResource != null && applyResource.size() > 0) {\n    catalogIds = applyResource.join(\',\')\n}\n\n// ========== 2. 保存主表 data_apply_form_t ==========\nif (isUpdate) {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_apply_form_t\').primary(\'tid\').update({\n        tid: tid,\n        apply_user_id:   applyUserId,\n        apply_org_id:   applyOrgId,\n        apply_user_name: applyUserName,\n        catalog_ids: catalogIds,\n        applyName:       applyName,\n        type:            type,\n        updated_by:      applyUserId,\n        updated_time:    now\n    })\n    log.info(\'更新申请表单成功, tid: {}\', tid)\n} else {\n    tid = IdUtil.getSnowflakeNextIdStr()\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'data_apply_form_t\').primary(\'tid\').insert({\n        tid:             tid,\n        apply_user_id:   applyUserId,\n        apply_org_id:   applyOrgId,\n        apply_user_name: applyUserName,\n        catalog_ids: catalogIds,\n        applyName:       applyName,\n        type:            type,\n        flow_status:     0,\n        tenant_id:       tenantId,\n        created_by:      applyUserId,\n        created_time:    now,\n        updated_by:      applyUserId,\n        updated_time:    now,\n        is_del:          0\n        \n    })\n    log.info(\'新增申请表单成功, tid: {}\', tid)\n}\n\n// ========== 3. 差量同步 data_apply_form_catalog_rela ==========\nif (applyResource != null) {\n    // 查询现有关联记录\n    var oldRelas = db.table(\'data_apply_form_catalog_rela\')\n        .where().eq(\'apply_form_id\', tid).eq(\'is_del\', 0).select()\n\n    // 构建旧数据 Map: catalog_id -> tid\n    var oldRelaMap = {}\n    for (rela in oldRelas) {\n        oldRelaMap[rela.catalogId] = rela\n    }\n\n    // 对比新数据\n    var relaInsertList = []\n    var sortIndex = 0\n    for (catalogId in applyResource) {\n        if (catalogId == null || catalogId == \'\') \n        {\n            continue;\n        }\n        if (oldRelaMap[catalogId] != null && oldRelaMap[catalogId].sortNo == sortIndex) {\n            // 已存在，标记已处理\n            oldRelaMap.remove(catalogId)\n        } else {\n            // 不存在，加入插入列表\n            relaInsertList.add({\n                tid:           IdUtil.getSnowflakeNextIdStr(),\n                apply_form_id: tid,\n                catalog_id:    catalogId,\n                sort_no:       sortIndex,\n                tenant_id:     tenantId,\n                created_by:    applyUserId,\n                created_time:  now,\n                updated_by:    applyUserId,\n                updated_time:  now,\n                // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n                catalog_org_id: esCommonService.getDocument("dataassets", catalogId).orgId,\n                catalog_org_path: "",\n                is_del:        0\n            })\n        }\n        sortIndex = sortIndex + 1\n    }\n\n    // 插入新关联\n    if (relaInsertList.size() > 0) {\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table(\'data_apply_form_catalog_rela\').batchInsert(relaInsertList)\n        log.info(\'新增申请单目录关联, 数量: {}\', relaInsertList.size())\n    }\n\n    // 软删除已移除的关联\n    var removeIds = []\n    for (val in oldRelaMap.values()) {\n        removeIds.add(val.tid)\n    }\n    if (removeIds.size() > 0) {\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table(\'data_apply_form_catalog_rela\')\n            .where().in(\'tid\', removeIds).delete()\n            //.update({ is_del: 1, updated_time: now })\n        log.info(\'移除申请单目录关联, 数量: {}\', removeIds.size())\n    }\n}\n\n// ========== 4. 差量同步 da_prop_t 动态属性 ==========\nvar insertList = []\nvar updateList = []\n\nif (isUpdate) {\n    // 查询旧属性\n    var oldProps = db.table(\'da_prop_t\')\n        .where().eq(\'parent_id\', tid).eq(\'is_del\', 0).select()\n\n    var oldPropMap = {}\n    for (prop in oldProps) {\n        oldPropMap[prop.propName] = { tid: prop.tid, prop_value: prop.propValue, prop_type: prop.propType }\n    }\n    log.info(\'旧属性数量: {}\', oldPropMap.size())\n\n    if (propList != null) {\n        for (key in propList.keySet()) {\n            var value    = propList[key]?.toString()\n            var propType = getPropType(key)\n            var propName = getRealPropName(key)\n            var oldProp  = oldPropMap[propName]\n\n            if (oldProp != null) {\n                if (oldProp.prop_value != value || oldProp.prop_type != propType) {\n                    updateList.add({\n                        tid:          oldProp.tid,\n                        prop_value:   value,\n                        prop_type:    propType,\n                        updated_time: now\n                    })\n                }\n                oldPropMap.remove(propName)\n            } else {\n                insertList.add({\n                    tid:          IdUtil.getSnowflakeNextIdStr(),\n                    tenant_id:    tenantId,\n                    parent_id:    tid,\n                    prop_name:    propName,\n                    prop_value:   value,\n                    prop_type:    propType,\n                    data_type:    \'apply_form\',\n                    is_del:       0,\n                    created_by:   applyUserId,\n                    created_time: now,\n                    updated_by:   applyUserId,\n                    updated_time: now\n                })\n            }\n        }\n    }\n\n    // 软删除旧属性中已不存在的项\n    // var deletePropIds = []\n    // for (propName in oldPropMap.keySet()) {\n    //     deletePropIds.add(oldPropMap[propName].tid)\n    // }\n    // if (deletePropIds.size() > 0) {\n    //     db.table(\'da_prop_t\').where().in(\'tid\', deletePropIds)\n    //         .update({ is_del: 1, updated_time: now })\n    //     log.info(\'删除旧属性, 数量: {}\', deletePropIds.size())\n    //}\n\n    // 更新变更属性\n    for (item in updateList) {\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table(\'da_prop_t\').where().eq(\'tid\', item.tid)\n            .update({ prop_value: item.prop_value, prop_type: item.prop_type, updated_time: item.updated_time }, true)\n    }\n    if (updateList.size() > 0) {\n        log.info(\'更新属性, 数量: {}\', updateList.size())\n    }\n\n} else {\n    // 新增模式：直接构建插入列表\n    if (propList != null) {\n        for (key in propList.keySet()) {\n            var value    = propList[key]?.toString()\n            var propType = getPropType(key)\n            var propName = getRealPropName(key)\n            insertList.add({\n                tid:          IdUtil.getSnowflakeNextIdStr(),\n                tenant_id:    tenantId,\n                parent_id:    tid,\n                prop_name:    propName,\n                prop_value:   value,\n                prop_type:    propType,\n                data_type:    \'apply_form\',\n                is_del:       0,\n                created_by:   applyUserId,\n                created_time: now,\n                updated_by:   applyUserId,\n                updated_time: now\n            })\n        }\n    }\n}\n\n// 批量插入属性\nif (insertList.size() > 0) {\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'da_prop_t\').batchInsert(insertList)\n    log.info(\'插入属性, 数量: {}\', insertList.size())\n}\n\n// ========== 5. 构建 ES 文档并同步 ==========\nvar mainData = db.table(\'data_apply_form_t\')\n    .where().eq(\'tid\', tid).eq(\'is_del\', 0).selectOne()\n\n// 从 MySQL 业务表读取当前有效数据。\nvar propData = db.table(\'da_prop_t\')\n    .where().eq(\'parent_id\', tid).eq(\'is_del\', 0).select()\n\nvar esDoc = {}\nif (mainData != null) {\n    esDoc.tid           = mainData.tid\n    esDoc.applyUserId   = mainData.applyUserId\n    esDoc.applyUserName = mainData.applyUserName\n    esDoc.applyName          = mainData.applyName\n    esDoc.type          = mainData.type\n    esDoc.catalogIds    = mainData.catalogIds\n    esDoc.flowStatus    = mainData.flowStatus\n    esDoc.tenantId      = mainData.tenantId\n    esDoc.createdTime   = mainData.createdTime\n    esDoc.updatedTime   = mainData.updatedTime\n}\n\nfor (prop in propData) {\n    esDoc[prop.propName] = prop.propValue\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nesCommonService.saveOrUpdate(\'dataassets_apply_form\', tid, jsons.toJSONStr(esDoc), isUpdate)\nlog.info(\'同步ES成功, tid: {}\', tid)\n\n// ========== 6. 清理关联的购物车记录 ==========\nif (!isUpdate && applyResource != null && applyResource.size() > 0) {\n    // 从 MySQL 业务表读取当前有效数据。\n    var deletedCount = db.table(\'data_market_shopping_cart_t\')\n        .where()\n        .in(\'catalog_id\', applyResource)\n        .eq(\'apply_org_id\', applyOrgId)\n        .eq(\'is_del\', 0)\n        .update({ is_del: 1, updated_time: new Date() })\n    log.info(\'清理购物车记录成功, 影响行数: {}\', deletedCount)\n}\n\n// ========== 返回结果 ==========\nreturn {\n  tid\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/09.资产申请单保存更新.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c4348978915046c4af25470dd509c239',NULL,NULL,'{\n  "properties": {},\n  "id": "c4348978915046c4af25470dd509c239",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "10.资产申请单列表",\n  "createTime": 1782955344148,\n  "updateTime": 1784437771770,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applyForm/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"tid\\": \\"218a6493926c485b85f6cd92983c23f9\\",\\n            \\"applyUserId\\": \\"1995681734511165441\\",\\n            \\"applyUserName\\": \\"1995681734511165441\\",\\n            \\"applyName\\": \\"动态组件目录(sys_dynamic_component)\\",\\n            \\"type\\": \\"catalogSubscribe\\",\\n            \\"catalogIds\\": \\"31583b5e1fc745aaa058d35b733c2f91\\",\\n            \\"flowStatus\\": 2,\\n            \\"tenantId\\": null,\\n            \\"createdTime\\": \\"2026-04-08 15:37:44\\",\\n            \\"updatedTime\\": \\"2026-04-08 15:37:44\\",\\n            \\"sceneType\\": \\"0\\",\\n            \\"applicantPhone\\": \\"aaa\\",\\n            \\"useDays\\": \\"\\",\\n            \\"usci\\": \\"9111000071780321XQ\\",\\n            \\"userPhone\\": \\"aaa\\",\\n            \\"businessScene\\": \\"eefe\\",\\n            \\"applyResource\\": \\"[31583b5e1fc745aaa058d35b733c2f91]\\",\\n            \\"attachment\\": \\"\\",\\n            \\"applyType\\": \\"政务服务\\",\\n            \\"useTime\\": \\"\\",\\n            \\"applicantName\\": \\"zz\\",\\n            \\"applyTime\\": \\"2026-04-08 15:37:36\\",\\n            \\"appId\\": \\"143c3b6d96774010a19fcc289441b704\\",\\n            \\"useScope\\": \\"0\\",\\n            \\"otherRequests\\": \\"\\",\\n            \\"userEmail\\": \\"zz\\",\\n            \\"useTitle\\": \\"\\",\\n            \\"applicantEmail\\": \\"zz\\",\\n            \\"peakFrequency\\": \\"\\",\\n            \\"applyBasis\\": \\"\\",\\n            \\"applyOrgId\\": \\"2026505033717514242\\",\\n            \\"userName\\": \\" zz\\",\\n            \\"averageFrequency\\": \\"\\",\\n            \\"flow_status\\": 1,\\n            \\"id\\": \\"218a6493926c485b85f6cd92983c23f9\\"\\n        },\\n        {\\n            \\"tid\\": \\"30253579e54d4061bd95c7af602e17e7\\",\\n            \\"applyUserId\\": \\"1995681734511165441\\",\\n            \\"applyUserName\\": \\"1995681734511165441\\",\\n            \\"applyName\\": \\"完成剧申报数据目录(res_1772095968985_copy28989)\\",\\n            \\"type\\": \\"catalogSubscribe\\",\\n            \\"catalogIds\\": \\"685ee1e783064ff8a9d7b3d08c5fe89a\\",\\n            \\"flowStatus\\": 2,\\n            \\"tenantId\\": null,\\n            \\"createdTime\\": \\"2026-04-08 17:04:18\\",\\n            \\"updatedTime\\": \\"2026-04-08 17:05:26\\",\\n            \\"businessScene\\": \\"SSSS\\",\\n            \\"otherRequests\\": \\"\\",\\n            \\"useTime\\": \\"\\",\\n            \\"applyBasis\\": \\"\\",\\n            \\"applyType\\": \\"政务服务\\",\\n            \\"applicantName\\": \\"zeng343\\",\\n            \\"useScope\\": \\"1\\",\\n            \\"useTitle\\": \\"\\",\\n            \\"applicantPhone\\": \\"EEERFE\\",\\n            \\"applyResource\\": \\"[685ee1e783064ff8a9d7b3d08c5fe89a]\\",\\n            \\"applicantEmail\\": \\"3334\\",\\n            \\"applyOrgId\\": \\"2026505033717514242\\",\\n            \\"useDays\\": \\"\\",\\n            \\"averageFrequency\\": \\"\\",\\n            \\"peakFrequency\\": \\"\\",\\n            \\"attachment\\": \\"[{\\\\\\"name\\\\\\":\\\\\\"25555.xlsx\\\\\\",\\\\\\"url\\\\\\":\\\\\\"/data/download?fileId=010146be47254171a1b591b2348ed350\\\\\\",\\\\\\"tid\\\\\\":\\\\\\"010146be47254171a1b591b2348ed350\\\\\\"}]\\",\\n            \\"applyTime\\": \\"2026-04-08 16:06:53\\",\\n            \\"appId\\": \\"a60c267ab6c1416d93e5965f0c2c15b5\\",\\n            \\"usci\\": \\"9111000071780321XQ\\",\\n            \\"sceneType\\": \\"1\\",\\n            \\"userName\\": \\"33\\",\\n            \\"userEmail\\": \\"3333\\",\\n            \\"userPhone\\": \\"SFS\\",\\n            \\"id\\": \\"30253579e54d4061bd95c7af602e17e7\\"\\n        },\\n        {\\n            \\"tid\\": \\"be4738f8783a46c7b04348df78e54a31\\",\\n            \\"applyUserId\\": \\"1995681734511165441\\",\\n            \\"applyUserName\\": \\"1995681734511165441\\",\\n            \\"applyName\\": \\"生成目录信息(sys_gen_info)\\",\\n            \\"type\\": \\"catalogSubscribe\\",\\n            \\"catalogIds\\": \\"85368b91972c4a35b83b8fa73e34e740\\",\\n            \\"flowStatus\\": 1,\\n            \\"tenantId\\": null,\\n            \\"createdTime\\": \\"2026-04-08 17:40:06\\",\\n            \\"updatedTime\\": \\"2026-04-09 10:21:21\\",\\n            \\"applyOrgId\\": \\"2026505033717514242\\",\\n            \\"useTime\\": \\"\\",\\n            \\"useTitle\\": \\"\\",\\n            \\"peakFrequency\\": \\"\\",\\n            \\"userEmail\\": \\"zzonia001@gmail.com\\",\\n            \\"attachment\\": \\"\\",\\n            \\"applicantName\\": \\"z\\",\\n            \\"businessScene\\": \\"1\\",\\n            \\"otherRequests\\": \\"\\",\\n            \\"applicantPhone\\": \\"1\\",\\n            \\"applicantEmail\\": \\"zzonia001@gmail.com\\",\\n            \\"userName\\": \\"zonia\\",\\n            \\"applyBasis\\": \\"\\",\\n            \\"usci\\": \\"9111000071780321XQ\\",\\n            \\"userPhone\\": \\"1\\",\\n            \\"applyType\\": \\"政务服务\\",\\n            \\"applyTime\\": \\"2026-04-08 17:40:25\\",\\n            \\"useDays\\": \\"\\",\\n            \\"averageFrequency\\": \\"\\",\\n            \\"sceneType\\": \\"0\\",\\n            \\"appId\\": \\"7d6efc981bfc4f92be875dd3bfc06857\\",\\n            \\"useScope\\": \\"0\\",\\n            \\"applyResource\\": \\"[85368b91972c4a35b83b8fa73e34e740]\\",\\n            \\"id\\": \\"be4738f8783a46c7b04348df78e54a31\\"\\n        },\\n        {\\n            \\"id\\": \\"71b6b05a4ba84079ba24b4d7fea8db5a\\",\\n            \\"flowStatus\\": 2\\n        },\\n        {\\n            \\"flowStatus\\": 1,\\n            \\"id\\": \\"order_000000000651\\"\\n        },\\n        {\\n            \\"flowStatus\\": 1,\\n            \\"id\\": \\"order_000000000652\\"\\n        },\\n        {\\n            \\"flowStatus\\": 1,\\n            \\"id\\": \\"order_000000000653\\"\\n        }\\n    ]\\n}",\n  "description": "读取资产申请单主记录和检索投影，按当前页面条件返回申请单列表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.资产申请单列表\n// 路由：POST /dws/market/applyForm/list\n// 业务说明：读取资产申请单主记录和检索投影，按当前页面条件返回申请单列表。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\n\n//项目初始化时创建空索引，有数据再查询es\nvar count = db.table("data_apply_form_t").count();\nif( count == 0){\n     // 返回当前业务分支的标准结果。\n     return {\n        total: 0,\n        list: []\n    }\n}\n\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nexistInxex = esCommonService.indexExists("dataassets_apply_form");\nif(!existInxex){\n    // 返回当前业务分支的标准结果。\n    return []\n}\n//多条件查询\nreturn esCommonService.list("dataassets_apply_form", body || {})\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/10.资产申请单列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1c10f955048340db9b921cb342b5e8f5',NULL,NULL,'{\n  "properties": {},\n  "id": "1c10f955048340db9b921cb342b5e8f5",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "11.资产申请单按id删除",\n  "createTime": 1782955344158,\n  "updateTime": 1787153757239,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applyForm/deleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"7d66f7d13848469c9964f975b884608e\\",\\n    \\"addToCart\\": true\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": true\\n}",\n  "description": "逻辑删除主表 data_apply_form_t、子表 da_prop_t、关联表 data_apply_form_catalog_rela；使用请求参数 tid、addToCart。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.资产申请单按id删除\n// 路由：POST /dws/market/applyForm/deleteById\n// 业务说明：逻辑删除主表 data_apply_form_t、子表 da_prop_t、关联表 data_apply_form_catalog_rela；使用请求参数 tid、addToCart。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport log\nimport "@post:/dws/market/shoppingCard" as addCar;\n\n/**\n * 删除申请表单\n * POST /api/apply/form/delete\n *\n * 逻辑删除主表 data_apply_form_t、子表 da_prop_t、关联表 data_apply_form_catalog_rela\n * 同步删除 ES 索引 dataassets_apply_form\n */\n\n// ========== 获取请求参数 ==========\nvar tid = body?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid不能为空\'\n}\n\nvar addToCart = body?.addToCart == true  // 是否重新加购\nvar now = new Date()\n\n// ========== 0. 若需加购，先查出关联目录 ID ==========\nvar toAddIds\nif (addToCart) {\n    // 从 MySQL 业务表读取当前有效数据。\n    var applyData = db.table(\'data_apply_form_t\')\n        .where().eq(\'tid\', tid).eq(\'is_del\', 0)\n        .selectOne()\n    if (!applyData){\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'申请单不存在\'\n    }\n    var catalogIds = applyData?.catalogIds?.split(",")\n\n    if (catalogIds) {\n        // 查当前用户购物车中已存在的 catalog_id，避免重复加购\n        var existingIds = db.table(\'data_market_shopping_cart_t\')\n            .where().eq(\'apply_org_id\', applyData.applyOrgId)\n            .eq(\'is_del\', 0)\n            .in(\'catalog_id\', catalogIds)\n            .select()\n            .map(it => it.catalogId)\n\n        toAddIds = catalogIds.filter(id => !existingIds.contains(id))\n    }\n}\n\n// ========== 1. 逻辑删除关联表 data_apply_form_catalog_rela ==========\nvar relaResult = db.table(\'data_apply_form_catalog_rela\')\n    .where().eq(\'apply_form_id\', tid)\n    .eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: now })\nlog.info(\'逻辑删除关联表 data_apply_form_catalog_rela, apply_form_id: {}, 影响行数: {}\', tid, relaResult)\n\n// ========== 2. 逻辑删除动态属性 da_prop_t ==========\nvar propResult = db.table(\'da_prop_t\')\n    .where().eq(\'parent_id\', tid).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: now })\nlog.info(\'逻辑删除子表 da_prop_t, parent_id: {}, 影响行数: {}\', tid, propResult)\n\n// ========== 3. 逻辑删除主表 data_apply_form_t ==========\nvar mainResult = db.table(\'data_apply_form_t\')\n    .where().eq(\'tid\', tid).eq(\'is_del\', 0)\n    .update({ is_del: 1, updated_time: now })\n\nif (mainResult == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'申请表单不存在或已删除\'\n}\nlog.info(\'逻辑删除主表 data_apply_form_t 成功, tid: {}\', tid)\n\n// ========== 4. 删除 ES 索引 ==========\nesCommonService.deleteById(\'dataassets_apply_form\', tid)\nlog.info(\'删除ES索引成功, tid: {}\', tid)\n\nif (addToCart && toAddIds){\n    for (id in toAddIds) {\n        body = {catalogId: id}\n        addCar();\n    }\n    log.info(\'重新加购目录到购物车, apply_form_id: {}, 加购数量: {}\', tid, toAddIds.size())\n}\n\n// 返回当前业务分支的标准结果。\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/11.资产申请单按id删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('db35431a36b34bc88b3b48914d7ba0ff',NULL,NULL,'{\n  "properties": {},\n  "id": "db35431a36b34bc88b3b48914d7ba0ff",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "12.资产申请单详情",\n  "createTime": 1782955344166,\n  "updateTime": 1786191947649,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applyForm/queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"b71ef91ddcc940a99b220cc3d7cd9120\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"0d50a16cf9b5458398a22f6fa158ea57\\"\\n}",\n  "description": "applyResource 返回申请目录详细；使用请求参数 tid；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：12.资产申请单详情\n// 路由：POST /dws/market/applyForm/queryById\n// 业务说明：applyResource 返回申请目录详细；使用请求参数 tid；读取或计算后返回业务结果。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport "@post:/dws/market/list" as marketList;\nimport tenantRuntime\n// 获取请求参数\nvar tid = body?.tid\nif(tid == null){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "tid不能为空";\n}\n\nvar tenantId = tenantRuntime.id()\n\n//查询es 获取主表数据\nvar applyData = esCommonService.getDocument("dataassets_apply_form", tid)\n\nif (!applyData){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "未找到申请单信息"\n}\n\nvar catalogIds =  applyData.catalogIds.split(",")\n// applyResource 返回申请目录详细\nbody = {\n    "query": [\n        {\n            "terms": {\n                "tid": catalogIds\n            }\n        }\n    ]\n}\n\nvar {list} = marketList();\nif (!list?.size()){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "未找到该资产"\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n  ...applyData,\n  applyResource: list\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/12.资产申请单详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('241456b9741748059d853cdbb4e12461',NULL,NULL,'{\n  "properties": {},\n  "id": "241456b9741748059d853cdbb4e12461",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "13.资源申请提交",\n  "createTime": 1782955344174,\n  "updateTime": 1784437771774,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/submit",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"approveType\\": \\"catalogSubscribe\\",\\n    \\"flowOrderId\\": \\"30253579e54d4061bd95c7af602e17e7\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {}\\n}",\n  "description": "按请求目标与业务状态执行资源申请提交，返回本次操作结果；使用请求参数 flowOrderId；涉及 data_apply_form_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：13.资源申请提交\n// 路由：POST /dws/market/submit\n// 业务说明：按请求目标与业务状态执行资源申请提交，返回本次操作结果；使用请求参数 flowOrderId；涉及 data_apply_form_t 等业务表。\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport log\n\n/*\n * 数据服务申请直接生效。\n *\n * 平台已取消审批流程，因此本接口不再创建流程实例，也不依赖审批中心。\n * 申请单直接更新为已通过，并同步申请单 ES 文档，保留原 /submit 路径供页面兼容调用。\n */\nvar flowOrderId = body?.flowOrderId\nif (flowOrderId == null || (flowOrderId + \'\').trim() == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'申请单号flowOrderId不能为空\'\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar form = db.table(\'data_apply_form_t\').where()\n    .eq(\'tid\', flowOrderId)\n    .eq(\'is_del\', 0)\n    .selectOne()\nif (form == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, \'申请单不存在\'\n}\n\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table(\'data_apply_form_t\').where().eq(\'tid\', flowOrderId).update({\n    flow_status: 2,\n    updated_time: new Date()\n})\n\ntry {\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var indexed = esCommonService.getDocument(\'dataassets_apply_form\', flowOrderId)\n    var document = indexed == null ? {} : indexed\n    document.id = flowOrderId\n    document.tid = flowOrderId\n    document.flowStatus = 2\n    document.updatedTime = new Date()\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.saveJsonAutoMapping(\n        \'dataassets_apply_form\',\n        flowOrderId,\n        jsons.toJSONStr(document)\n    )\n} catch (e) {\n    log.warn(\'同步数据服务申请单ES失败，flowOrderId: {}, error: {}\', flowOrderId, e.message)\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    flowOrderId: flowOrderId,\n    flowStatus: 2,\n    directGranted: true\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/13.资源申请提交.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('64c0bb65fad54c538d5b80423623cbf7',NULL,NULL,'{\n  "properties": {},\n  "id": "64c0bb65fad54c538d5b80423623cbf7",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "14.超市列表",\n  "createTime": 1782955344184,\n  "updateTime": 1787153757274,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"query\\": [\\n        {\\n            \\"term\\": {\\n                \\"publishStatus\\": 1\\n            }\\n        },\\n        {\\n            \\"term\\": {\\n                \\"assetType\\": \\"catalog\\"\\n            }\\n        }\\n    ],\\n    \\"sortField\\": \\"createdTime\\",\\n    \\"sortDir\\": \\"desc\\",\\n    \\"indexType\\": \\"app\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"org.ssssssss.script.exception.MagicScriptException: method [POST], host [http://192.168.175.86:19200], URI [/elements_sea_fishery_dataassets/_search], status line [HTTP/1.1 404 Not Found]\\\\n{\\\\\\"error\\\\\\":{\\\\\\"root_cause\\\\\\":[{\\\\\\"type\\\\\\":\\\\\\"index_not_found_exception\\\\\\",\\\\\\"reason\\\\\\":\\\\\\"no such index [elements_sea_fishery_dataassets]\\\\\\",\\\\\\"resource.type\\\\\\":\\\\\\"index_or_alias\\\\\\",\\\\\\"resource.id\\\\\\":\\\\\\"elements_sea_fishery_dataassets\\\\\\",\\\\\\"index_uuid\\\\\\":\\\\\\"_na_\\\\\\",\\\\\\"index\\\\\\":\\\\\\"elements_sea_fishery_dataassets\\\\\\"}],\\\\\\"type\\\\\\":\\\\\\"index_not_found_exception\\\\\\",\\\\\\"reason\\\\\\":\\\\\\"no such index [elements_sea_fishery_dataassets]\\\\\\",\\\\\\"resource.type\\\\\\":\\\\\\"index_or_alias\\\\\\",\\\\\\"resource.id\\\\\\":\\\\\\"elements_sea_fishery_dataassets\\\\\\",\\\\\\"index_uuid\\\\\\":\\\\\\"_na_\\\\\\",\\\\\\"index\\\\\\":\\\\\\"elements_sea_fishery_dataassets\\\\\\"},\\\\\\"status\\\\\\":404} at Row:39~39,Col:49~59\\\\n\\\\nvar searchlist = tenantEs.index(indexType).search(dsl);\\\\r\\\\n                                                ^^^^^^^^^^^  \\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "返回目录列表，及申请状态、收藏状态、关联资源类型；涉及 data_market_collect_t、data_market_shopping_cart_t、data_apply_form_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：14.超市列表\n// 路由：POST /dws/market/list\n// 业务说明：返回目录列表，及申请状态、收藏状态、关联资源类型；涉及 data_market_collect_t、data_market_shopping_cart_t、data_apply_form_t 等业务表。\n// 返回目录列表，及申请状态、收藏状态、关联资源类型\nimport jsons\nimport tenantEs;\nimport log;\nimport "@post:/sym/user/me" as me\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport \'@/common/configData\' as configData\n\n\n// 解析请求体并为可选参数设置默认值。\nvar {pageNum, pageSize, query, indexType, sortField, sortDir } = body;        \n//indexType = indexType || "elements_sea_fishery_dataassets"\n\nindexType = indexType || configData().es_dataassets\n\nvar dsl = {\n    query: {\n        bool: {\n            must: query\n        }\n    },\n};\n\nif (pageNum !== null && pageSize !== null){\n    dsl["from"] = pageNum?.asInt() - 1;\n    dsl["size"] = pageSize?.asInt() || 20;\n}\n\nif (sortField !== null){\n    dsl["sort"] = [\n        {[sortField]: {order: sortDir}}\n    ]\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nexistInxex = esCommonService.indexExists("dataassets");\nif(!existInxex){\n    // 返回当前业务分支的标准结果。\n    return {\n        total: 0,\n        list: []\n    }\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar searchlist = tenantEs.index(indexType).search(dsl);\nvar list = searchlist.hits.hits.map(e=>e._source)\n\n\n// ====== 获取当前用户信息 ======\nvar userInfo = me()\nvar applyUserId  = userInfo.id\nvar applyUserName  = userInfo.userName\nvar applyOrgId  = userInfo.orgId\nvar ids = list.map(item=>item.tid)\n\n// ====== 获取收藏目录id ======\nvar collects = db.table(\'data_market_collect_t\')\n    .where()\n    .eq(\'apply_org_id\', applyOrgId)\n    .in(\'catalog_id\', ids)\n    .select()\n\nvar collectIds = collects.map(item=>item.catalogId)\n\n// ====== 获取购物车目录id ======\nvar cartItems = db.table(\'data_market_shopping_cart_t\')\n    .where()\n    .eq(\'apply_org_id\', applyOrgId)\n    .eq(\'is_del\', 0)\n    .in(\'catalog_id\', ids)\n    .select()\n\nvar cartIds = cartItems.map(item=>item.catalogId)\n\n// ====== 获取申请单状态（只取有效状态 0/1/2/5）======\nvar applyForms = db.table(\'data_apply_form_t\')\n    .where()\n    .eq(\'apply_org_id\', applyOrgId)\n    .in(\'flow_status\', [0, 1, 2, 5, 4])\n    .eq(\'is_del\', 0)\n    .select()\n\n// 优先级： 2（已申请）> 1（申请中） > 5(已驳回) > 0（草稿/待申请）\nvar PRIORITY = {"2": 3, "1": 2, "5": 1, "0": 0}\nvar applyStatusMap = {}\n\napplyForms.each(form => {\n    var catalogIdList = form.catalogIds.split(\',\')\n    catalogIdList.each(cid => {\n        if (ids.contains(cid)) {\n            var newStatus = form.flowStatus\n            var existing = applyStatusMap[cid]\n            applyStatusMap[cid] = newStatus\n            // if (existing === undefined || PRIORITY[newStatus] > PRIORITY[existing]) {\n            //     applyStatusMap[cid] = newStatus\n            // }\n        }\n    })\n})\n\nlist = list.map(item => {\n    var obj = item\n    // 设置目录的关联资源\n    if (obj.assetType == "catalog"){\n        var res = []\n        !!obj.targetTableId && res.push("table")\n        !!obj.apiId && res.push("api")\n        !!obj.fileId && res.push("file")\n        !!obj.dirId && res.push("dir")\n        obj["resType"] = res\n    }\n\n    // 设置初始浏览量\n    obj["viewCount"] = obj["viewCount"] || 0\n\n    // 设置收藏状态\n    obj["collected"] = collectIds.contains(obj.tid)\n\n    // 设置申请状态\n    var applyStatus = applyStatusMap[obj.tid]\n    if (applyStatus !== undefined) {\n        obj["applyStatus"] = applyStatus == 4 ? 1 : applyStatus       // 0=待提交, 1=审核中, 2=已申请\n    } else if (cartIds.contains(obj.tid)) {\n        obj["applyStatus"] = "cart"             // 已加购\n    } else {\n        obj["applyStatus"] = null               // 默认，可申请\n    }\n    // 返回当前业务分支的标准结果。\n    return obj\n})\n\n\n// 返回当前业务分支的标准结果。\nreturn {\n    total: searchlist.hits.total.value,\n    list\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/14.超市列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bc7ab46f70354dab95ca7deb785d72fd',NULL,NULL,'{\n  "properties": {},\n  "id": "bc7ab46f70354dab95ca7deb785d72fd",\n  "script": null,\n  "groupId": "dataservice_resource_group_01",\n  "name": "15.超市详情",\n  "createTime": 1782955344192,\n  "updateTime": 1784521647429,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"85368b91972c4a35b83b8fa73e34e740\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"未找到该资产\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "按目录标识复用数据超市列表查询，并返回匹配资产的详细展示资料。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：15.超市详情\n// 路由：POST /dws/market/detail\n// 业务说明：按目录标识复用数据超市列表查询，并返回匹配资产的详细展示资料。\nimport "@post:/dws/market/list" as marketList;\n\nbody = {\n    "query": [\n        {\n            "term": {\n                // 解析请求体并为可选参数设置默认值。\n                "tid": body.tid\n            }\n        }\n    ]\n}\n\nvar {list} = marketList();\nif (!list?.size()){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "未找到该资产"  \n}\n\n// 返回当前业务分支的标准结果。\nreturn list[0]\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/15.超市详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dataservice_resource_group_01',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "dataservice_resource_group_01",\r\n  "name" : "02.数据超市",\r\n  "type" : "api",\r\n  "parentId" : "2c4350a98636412f9b4feb6e31969c00",\r\n  "path" : "/market",\r\n  "createTime" : 1784420517826,\r\n  "updateTime" : 1785021681888,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/02.数据超市/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('420c2b3f703845099c0ebe0df7dfbade',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "2c4350a98636412f9b4feb6e31969c00",\r\n  "name" : "06.数据服务",\r\n  "type" : "api",\r\n  "parentId" : "0",\r\n  "path" : "/dws",\r\n  "createTime" : 1784420517826,\r\n  "updateTime" : 1784437772101,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/06.数据服务/group.json');
