INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('acb1c21957514ca29bd54acd3fbc2d0a',NULL,NULL,'{\n  "properties": {},\n  "id": "acb1c21957514ca29bd54acd3fbc2d0a",\n  "script": null,\n  "groupId": "7c271b88983b467282fd9d498d0f8d66",\n  "name": "01.删除大屏",\n  "createTime": 1782955345206,\n  "updateTime": 1784437771874,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/deleteById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"success\\"\\n}",\n  "description": "按目标标识和当前状态执行删除大屏，返回处理结果；使用请求参数 tid；涉及 app_workshop_big_screen 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.删除大屏\n// 路由：POST /das/repository/bigScreen/deleteById\n// 业务说明：按目标标识和当前状态执行删除大屏，返回处理结果；使用请求参数 tid；涉及 app_workshop_big_screen 等业务表。\n// 解析请求体并为可选参数设置默认值。\nvar tid = body?.tid\n\n// 将校验后的业务数据写入 MySQL 主表。\nvar data = db.table("app_workshop_big_screen").where().eq("tid", tid).delete();\n\n// 返回当前业务分支的标准结果。\nreturn "success"\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/01.大屏/01.删除大屏.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fe55dadd11564ad4876470dc8f661041',NULL,NULL,'{\n  "properties": {},\n  "id": "fe55dadd11564ad4876470dc8f661041",\n  "script": null,\n  "groupId": "7c271b88983b467282fd9d498d0f8d66",\n  "name": "02.按tid查询大屏",\n  "createTime": 1782955345214,\n  "updateTime": 1784437771874,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"1\\",\\n        \\"tenantId\\": \\"1\\",\\n        \\"revision\\": \\"1\\",\\n        \\"createdBy\\": \\"2\\",\\n        \\"createdTime\\": \\"2026-04-15 15:14:45\\",\\n        \\"updatedBy\\": null,\\n        \\"updatedTime\\": null,\\n        \\"name\\": \\"2\\",\\n        \\"nameCn\\": \\"2\\",\\n        \\"sourceCode\\": \\"1\\",\\n        \\"thumbnail\\": \\"11\\"\\n    }\\n}",\n  "description": "按大屏主键读取应用工作坊的大屏配置与展示资料，返回单条记录。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.按tid查询大屏\n// 路由：POST /das/repository/bigScreen/getById\n// 业务说明：按大屏主键读取应用工作坊的大屏配置与展示资料，返回单条记录。\n// 解析请求体并为可选参数设置默认值。\nvar tid = body?.tid\n\n// 从 MySQL 业务表读取当前有效数据。\nvar data = db.table("app_workshop_big_screen").where().eq("tid", tid).selectOne();\n\n// 返回当前业务分支的标准结果。\nreturn data\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/01.大屏/02.按tid查询大屏.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('085a628db82248c9aec36a1e57e1f9f2',NULL,NULL,'{\n  "properties": {},\n  "id": "085a628db82248c9aec36a1e57e1f9f2",\n  "script": null,\n  "groupId": "7c271b88983b467282fd9d498d0f8d66",\n  "name": "03.新增大屏",\n  "createTime": 1782955345224,\n  "updateTime": 1784437771875,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"name\\": \\"123\\",\\n    \\"nameCn\\": \\"2323423\\",\\n    \\"sourceCode\\": \\"json\\",\\n    \\"thumbnail\\": \\"缩略图\\",\\n    \\"parentId\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"f55db88041a14eaba35fbd06dc91e171\\"\\n}",\n  "description": "校验请求资料后执行新增大屏，返回保存或配置结果；使用请求参数 name、nameCn、sourceCode、thumbnail、parentId；涉及 app_workshop_big_screen 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.新增大屏\n// 路由：POST /das/repository/bigScreen/save\n// 业务说明：校验请求资料后执行新增大屏，返回保存或配置结果；使用请求参数 name、nameCn、sourceCode、thumbnail、parentId；涉及 app_workshop_big_screen 等业务表。\nimport cn.hutool.json.JSONUtil\nimport log\nimport cn.hutool.core.util.IdUtil\nimport IdGenerator\nimport jsons\n\n\n// 解析请求体并为可选参数设置默认值。\nvar name = body?.name\nvar nameCn = body?.nameCn\nvar sourceCode = body?.sourceCode\nvar thumbnail = body?.thumbnail\nvar parentId = body?.parentId\n\nvar tid =  IdUtil.getSnowflakeNextIdStr()\nvar now = new Date()\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table("app_workshop_big_screen").insert({\n    tid : tid,\n    name : name,\n    name_cn : nameCn,\n    source_code : sourceCode,\n    thumbnail : thumbnail,\n    parent_id : parentId,\n    created_time: now,\n    updated_time: now\n})\n// 返回当前业务分支的标准结果。\nreturn tid\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/01.大屏/03.新增大屏.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b910193ab56143129466e2c69613286d',NULL,NULL,'{\n  "properties": {},\n  "id": "b910193ab56143129466e2c69613286d",\n  "script": null,\n  "groupId": "7c271b88983b467282fd9d498d0f8d66",\n  "name": "04.更新大屏",\n  "createTime": 1782955345232,\n  "updateTime": 1784437771876,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/update",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\",\\n    \\"name\\": \\"123\\",\\n    \\"nameCn\\": \\"2323423\\",\\n    \\"sourceCode\\": \\"json\\",\\n    \\"thumbnail\\": \\"缩略图\\",\\n    \\"parentId\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"1\\"\\n}",\n  "description": "校验请求资料后执行更新大屏，返回保存或配置结果；使用请求参数 tid、name、nameCn、sourceCode、thumbnail、parentId；涉及 app_workshop_big_screen 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.更新大屏\n// 路由：POST /das/repository/bigScreen/update\n// 业务说明：校验请求资料后执行更新大屏，返回保存或配置结果；使用请求参数 tid、name、nameCn、sourceCode、thumbnail、parentId；涉及 app_workshop_big_screen 等业务表。\nimport cn.hutool.json.JSONUtil\nimport log\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport IdGenerator\nimport jsons\n\n// 解析请求体并为可选参数设置默认值。\nvar tid = body?.tid\nif(tid == null || tid == ""){\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "tid不能为空";\n}\nvar name = body?.name\nvar nameCn = body?.nameCn\nvar sourceCode = body?.sourceCode\nvar thumbnail = body?.thumbnail\nvar parentId = body?.parentId\n\nvar currentUserId = StpUtil.getLoginId() + ""\n\nvar now = new Date()\n\n// 构建更新数据\nvar updateData = {\n    tid: oldTid,\n    updated_by: currentUserId,\n    updated_time: now\n}\n\nif (body?.name != null && body?.name != \'\') {\n    updateData.name = body?.name\n}\n\nif (body?.nameCn != null && body?.nameCn != \'\') {\n    updateData.nameCn = body?.nameCn\n}\n\nif (body?.sourceCode != null && body?.sourceCode != \'\') {\n    updateData.sourceCode = body?.sourceCode\n}\n\nif (body?.thumbnail != null && body?.thumbnail != \'\') {\n    updateData.thumbnail = body?.thumbnail\n}\n\nif (body?.parentId != null && body?.parentId != \'\') {\n    updateData.parentId = body?.parentId\n}\n\n\n//var tid =  IdUtil.getSnowflakeNextIdStr()\ndb.table("app_workshop_big_screen").where().eq("tid", tid).update(updateData)\n\n// db.table("app_workshop_big_screen").where().eq("tid", oldTid).update({\n//     is_del : "1",\n//     updated_time: now\n// })\n\nreturn tid\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/01.大屏/04.更新大屏.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7c271b88983b467282fd9d498d0f8d66',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "7c271b88983b467282fd9d498d0f8d66",\r\n  "name" : "01.大屏",\r\n  "type" : "api",\r\n  "parentId" : "37c35deab6bc4e678c8955cc951f2ffd",\r\n  "path" : "/bigScreen",\r\n  "createTime" : 1781960052307,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/01.大屏/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e38ba90d18b141488564a791ccdcefcd',NULL,NULL,'{\n  "properties": {},\n  "id": "e38ba90d18b141488564a791ccdcefcd",\n  "script": null,\n  "groupId": "37c35deab6bc4e678c8955cc951f2ffd",\n  "name": "02.删除应用",\n  "createTime": 1782955345162,\n  "updateTime": 1784437771870,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "逻辑删除（更新is_del字段为1）；使用请求参数 tid；涉及 app_workshop_repository 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.删除应用\n// 路由：POST /das/repository/delete\n// 业务说明：逻辑删除（更新is_del字段为1）；使用请求参数 tid；涉及 app_workshop_repository 等业务表。\nimport log\n\n/**\n * 应用仓库删除\n * DELETE /api/das/repository/delete/{tid}\n * \n * 逻辑删除应用仓库记录\n */\n\n// 获取应用ID\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用ID不能为空\'\n}\n\n// 检查记录是否存在\nvar exists = db.table(\'app_workshop_repository\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .count()\n\nif (exists == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用不存在\'\n}\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\n// 逻辑删除（更新is_del字段为1）\ndb.table(\'app_workshop_repository\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update({\n        is_del: 1,\n        updated_time: currentTime\n    })\n\nlog.info(\'删除应用仓库成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/02.删除应用.ms');
