INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e8c07b2ddfa84eb6a21655498a15e596',NULL,NULL,'{\n  "properties": {},\n  "id": "e8c07b2ddfa84eb6a21655498a15e596",\n  "script": null,\n  "groupId": "5e2962ddb12b4ed98ccdd9a389640db6",\n  "name": "01.删除图标",\n  "createTime": 1782955345242,\n  "updateTime": 1784437771876,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1e489cb251fd4c768fe2777cb9ce3458\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": true\\n}",\n  "description": "逻辑删除（更新is_del字段为1）；使用请求参数 tid；涉及 app_workshop_repository_self_icon 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.删除图标\n// 路由：POST /das/repository/icon/delete\n// 业务说明：逻辑删除（更新is_del字段为1）；使用请求参数 tid；涉及 app_workshop_repository_self_icon 等业务表。\nimport log\n\n/**\n * 应用仓库删除\n * DELETE /api/das/repository/delete/{tid}\n * \n * 逻辑删除应用仓库记录\n */\n\n// 获取应用ID\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用图标ID不能为空\'\n}\n\n// 检查记录是否存在\nvar exists = db.table(\'app_workshop_repository_self_icon\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .count()\n\nif (exists == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用不存在\'\n}\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\n// 逻辑删除（更新is_del字段为1）\ndb.table(\'app_workshop_repository_self_icon\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update({\n        is_del: 1,\n        updated_time: currentTime\n    })\n\nlog.info(\'删除应用图标成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/02.自定图标/01.删除图标.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3f0547c49dde4effa23196872929ac9c',NULL,NULL,'{\n  "properties": {},\n  "id": "3f0547c49dde4effa23196872929ac9c",\n  "script": null,\n  "groupId": "5e2962ddb12b4ed98ccdd9a389640db6",\n  "name": "02.图标列表",\n  "createTime": 1782955345251,\n  "updateTime": 1784437771877,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"tid\\": \\"1e489cb251fd4c768fe2777cb9ce3458\\",\\n            \\"tenantId\\": null,\\n            \\"revision\\": null,\\n            \\"createdBy\\": \\"1995681734511165441\\",\\n            \\"createdTime\\": \\"2026-04-20 11:01:25\\",\\n            \\"isDel\\": 0,\\n            \\"updatedBy\\": \\"1995681734511165441\\",\\n            \\"updatedTime\\": \\"2026-04-20 11:01:25\\",\\n            \\"orgId\\": null,\\n            \\"appIcon\\": \\"https://example.com/icon.png\\"\\n        }\\n    ]\\n}",\n  "description": "读取应用工作坊自定义图标清单，返回页面可选择的图标资料。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.图标列表\n// 路由：GET /das/repository/icon/list\n// 业务说明：读取应用工作坊自定义图标清单，返回页面可选择的图标资料。\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport log\n\n\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\nvar tid = IdUtil.getSnowflakeNextIdStr()\nvar currentUserId = StpUtil.getLoginId() + ""\n\n\n// 检查记录是否存在\nvar data = db.table(\'app_workshop_repository_self_icon\')\n    .where()\n    .eq(\'created_by\', currentUserId)\n    .eq(\'is_del\', 0)\n    .select()\n\n// 返回当前业务分支的标准结果。\nreturn data;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/02.自定图标/02.图标列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('430c40a44f8b49a58feb7194882b181e',NULL,NULL,'{\n  "properties": {},\n  "id": "430c40a44f8b49a58feb7194882b181e",\n  "script": null,\n  "groupId": "5e2962ddb12b4ed98ccdd9a389640db6",\n  "name": "03.新增图标",\n  "createTime": 1782955345260,\n  "updateTime": 1784437771878,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/add",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"appIcon\\": \\"https://example.com/icon.png\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"1e489cb251fd4c768fe2777cb9ce3458\\"\\n    }\\n}",\n  "description": "校验请求资料后执行新增图标，返回保存或配置结果；使用请求参数 appIcon；涉及 app_workshop_repository_self_icon 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.新增图标\n// 路由：POST /das/repository/icon/add\n// 业务说明：校验请求资料后执行新增图标，返回保存或配置结果；使用请求参数 appIcon；涉及 app_workshop_repository_self_icon 等业务表。\nimport log\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil\n\n/**\n * 应用仓库新增\n * POST /api/das/repository/add\n * \n * 新增应用仓库记录\n */\n\n// 参数校验\nvar appIcon = body?.appIcon\nif (appIcon == null || appIcon == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'appIcon不能为空\'\n}\n\n// 生成主键ID\nvar tid = IdUtil.getSnowflakeNextIdStr()\nvar currentUserId = StpUtil.getLoginId() + ""\nvar createdBy = currentUserId\nvar updatedBy = currentUserId\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\n// 插入数据\ndb.table(\'app_workshop_repository_self_icon\')\n    .insert({\n        tid: tid,\n        app_icon: body?.appIcon,\n        is_del: 0,\n        created_by: createdBy,\n        created_time: currentTime,\n        updated_by: updatedBy,\n        updated_time: currentTime\n    })\n\nlog.info(\'新增应用图标成功, tid: {}, appIcon: {}\', tid, appIcon)\n\n// ========== 返回结果 ==========\nreturn {\n        tid: tid \n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/02.自定图标/03.新增图标.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5e2962ddb12b4ed98ccdd9a389640db6',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "5e2962ddb12b4ed98ccdd9a389640db6",\r\n  "name" : "02.自定图标",\r\n  "type" : "api",\r\n  "parentId" : "37c35deab6bc4e678c8955cc951f2ffd",\r\n  "path" : "/icon",\r\n  "createTime" : 1781960052406,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/02.自定图标/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6d310836db5f463a8942fa81958c35ec',NULL,NULL,'{\n  "properties": {},\n  "id": "6d310836db5f463a8942fa81958c35ec",\n  "script": null,\n  "groupId": "37c35deab6bc4e678c8955cc951f2ffd",\n  "name": "03.应用分页查询",\n  "createTime": 1782955345170,\n  "updateTime": 1784437771871,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": \\"1\\",\\n    \\"pageSize\\": \\"20\\",\\n    \\"appName\\": \\"测试业务系统\\",\\n    \\"publishStatus\\": 2\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"total\\": 1,\\n        \\"list\\": [\\n            {\\n                \\"tid\\": \\"1\\",\\n                \\"tenantId\\": \\"1\\",\\n                \\"revision\\": \\"1\\",\\n                \\"createdBy\\": \\"2\\",\\n                \\"createdTime\\": \\"2026-04-22 11:16:17\\",\\n                \\"isDel\\": 0,\\n                \\"updatedBy\\": null,\\n                \\"updatedTime\\": null,\\n                \\"appName\\": null,\\n                \\"appType\\": null,\\n                \\"appIcon\\": null,\\n                \\"description\\": null,\\n                \\"publishStatus\\": null,\\n                \\"publishUrl\\": null,\\n                \\"publishId\\": null\\n            }\\n        ]\\n    }\\n}",\n  "description": "按应用名称、类型、发布状态及分页参数查询应用仓库，返回应用列表和总数。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.应用分页查询\n// 路由：POST /das/repository/page\n// 业务说明：按应用名称、类型、发布状态及分页参数查询应用仓库，返回应用列表和总数。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\nimport log\n\n/**\n * 应用仓库分页查询\n * POST /api/das/repository/page\n * \n * 支持分页查询应用仓库列表\n */\n\n// 获取分页参数\nvar pageNum = body?.pageNum::long(0)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0? 0 : (pageNum - 1)* pageSize\n\n// 获取查询条件\nvar appName = body?.appName\nvar appType = body?.appType\nvar publishStatus = body?.publishStatus\n\n// 构建查询条件\nvar query = db.table(\'app_workshop_repository\')\n    .where()\n    .eq(\'is_del\', 0)\n\nif (appName != null && appName != \'\') {\n    query = query.like(\'app_name\', \'%\' + appName + \'%\')\n}\n\n// if (appType != null) {\n//     query = query.eq(\'app_type\', appType)\n// }\n\nif (publishStatus != null) {\n    query = query.eq(\'publish_status\', publishStatus)\n}\n\n// ========== 查询总数 ==========\nvar total = query.count()\n\n// ========== 查询列表 ==========\nvar list = query\n    .orderBy(\'created_time\', \'desc\')\n    .page(pageSize, offsetLimit)\n\nlog.info(\'分页查询应用仓库成功, pageNum: {}, pageSize: {}, total: {}\', pageNum, pageSize, total)\n\n// ========== 返回结果 ==========\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.应用分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('39a9aaf9bc224581ac38baa0bd8066b9',NULL,NULL,'{\n  "properties": {},\n  "id": "39a9aaf9bc224581ac38baa0bd8066b9",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "01.关联页面绑定(新增调用)",\n  "createTime": 1782955345267,\n  "updateTime": 1784437771878,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/bind",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pid\\": \\"页签id\\",\\n    \\"tid\\": \\"子页面id\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行关联页面绑定(新增调用)，返回保存或配置结果；使用请求参数 pid、tid；涉及 app_workshop_repository_tab 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.关联页面绑定(新增调用)\n// 路由：POST /das/repository/tab/bind\n// 业务说明：校验请求资料后执行关联页面绑定(新增调用)，返回保存或配置结果；使用请求参数 pid、tid；涉及 app_workshop_repository_tab 等业务表。\n// 解析请求体并为可选参数设置默认值。\nvar tid = body?.pid\nvar relaId = body?.tid\n\n\n\n// 从 MySQL 业务表读取当前有效数据。\ndb.table(\'app_workshop_repository_tab\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update({\n      rela_id:relaId\n    })\n\n// 返回当前业务分支的标准结果。\nreturn "success"\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/01.关联页面绑定(新增调用).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('124c8c77129242f786e0903e5172a90b',NULL,NULL,'{\n  "properties": {},\n  "id": "124c8c77129242f786e0903e5172a90b",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "02.页签分页查询",\n  "createTime": 1782955345276,\n  "updateTime": 1784437771880,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": \\"1\\",\\n    \\"pageSize\\": \\"20\\",\\n    \\"pid\\": \\"测试\\",\\n    \\"tabType\\": \\"app\\",\\n    \\"keyword\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"total\\": 0,\\n        \\"list\\": null\\n    }\\n}",\n  "description": "按所属应用、页签类型和关键词查询应用仓库页签，返回分页资料与总数。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.页签分页查询\n// 路由：POST /das/repository/tab/page\n// 业务说明：按所属应用、页签类型和关键词查询应用仓库页签，返回分页资料与总数。\nimport log\nimport uiComponentAdmin\n\n/**\n * 应用仓库页签分页查询\n * POST /api/das/repository/tab/page\n */\n\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0 ? 0 : (pageNum - 1) * pageSize\n\nvar pid = body?.pid\nvar tabType = body?.tabType\nvar keyword = body?.keyword\n\nvar sql = """\n    select\n        t.tid,\n        t.pid,\n        --t.name,\n        -- t.name_cn,\n        t.tab_type,\n        t.rela_id,\n        t.publish_id,\n        t.thumbnail,\n        t.seq_no,\n        t.created_by,\n        t.created_time,\n        t.updated_by,\n        t.updated_time,\n        case\n            when t.tab_type = 3 then bs.name_cn\n            when t.tab_type = 2 then sf.form_name\n            else null\n        end as name_cn,\n        case\n            when t.tab_type = 3 then bs.name\n            when t.tab_type = 2 then sf.form_name\n            else null\n        end as name\n    from app_workshop_repository_tab t\n    left join app_workshop_big_screen bs on bs.tid = t.rela_id and bs.is_del = 0 and t.tab_type = 3\n    left join sym_form sf on sf.tid = t.rela_id and sf.is_del = 0 and t.tab_type = 2\n"""\n\nvar whereSql = " where t.is_del = 0 "\nif (pid != null && pid != \'\') {\n    whereSql = whereSql + " and t.pid = #{pid} "\n}\nif (tabType != null && tabType != \'\') {\n    whereSql = whereSql + " and t.tab_type = #{tabType} "\n}\nif (keyword != null && keyword != \'\') {\n    whereSql = whereSql + " and (t.name like concat(\'%\', #{keyword}, \'%\') or t.name_cn like concat(\'%\', #{keyword}, \'%\')) "\n}\n\nvar orderSql = " order by t.seq_no asc, t.created_time desc "\n// 从 MySQL 业务表读取当前有效数据。\nvar pageList = db.page(sql + whereSql + orderSql, pageSize, offsetLimit)\nuiComponentAdmin.enrichRepositoryTabs(pageList.list)\n\nlog.info(\'分页查询应用仓库页签成功, pid: {}, tabType: {}, pageNum: {}, pageSize: {}, total: {}\', pid, tabType, pageNum, pageSize, pageList?.total)\n\n// 返回当前业务分支的标准结果。\nreturn pageList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/02.页签分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99884ef7c8074a85a77e9effbf69f5b8',NULL,NULL,'{\n  "properties": {},\n  "id": "99884ef7c8074a85a77e9effbf69f5b8",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "03.页签删除",\n  "createTime": 1782955345284,\n  "updateTime": 1784437771881,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"xxxx\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "应用仓库页签删除（同步删除关联资源）；使用请求参数 tid；涉及 app_workshop_repository_tab、app_workshop_big_screen、sym_form 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.页签删除\n// 路由：POST /das/repository/tab/delete\n// 业务说明：应用仓库页签删除（同步删除关联资源）；使用请求参数 tid；涉及 app_workshop_repository_tab、app_workshop_big_screen、sym_form 等业务表。\nimport log\nimport uiComponentAdmin\n\n/**\n * 应用仓库页签删除（同步删除关联资源）\n * DELETE /api/das/repository/tab/delete/{tid}\n */\n\nvar tid = body?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "页签ID不能为空"\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar tab = db.table(\'app_workshop_repository_tab\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (tab == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "页签不存在"\n}\n\nvar tabType = tab?.tab_type::int\nvar relaId = tab?.rela_id\n\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table(\'app_workshop_repository_tab\').logic().where().eq(\'tid\', tid).delete()\n\nvar otherRefCount = 0\nif (relaId != null && relaId != \'\') {\n    otherRefCount = db.selectInt("""\n        select count(1)\n        from app_workshop_repository_tab\n        where is_del = 0\n        and tab_type = #{tabType}\n        and rela_id = #{relaId}\n        and tid != #{tid}\n    """)\n}\n\nvar deletedRela = false\nif (otherRefCount == 0 && relaId != null && relaId != \'\') {\n    if ([0,1].contains(tabType)) {\n        uiComponentAdmin.delete(relaId)\n        deletedRela = true\n    } else if (tabType == 3) {\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table(\'app_workshop_big_screen\').logic().where().eq(\'tid\', relaId).delete()\n        deletedRela = true\n    } else if (tabType == 2) {\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table(\'sym_form\').logic().where().eq(\'tid\', relaId).delete()\n        deletedRela = true\n    }\n}\n\nlog.info(\'删除应用仓库页签成功, tid: {}, tabType: {}, relaId: {}, deletedRela: {}\', tid, tabType, relaId, deletedRela)\n\n// 返回当前业务分支的标准结果。\nreturn true\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/03.页签删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8c12c7d95d1148f892182090e6006924',NULL,NULL,'{\n  "properties": {},\n  "id": "8c12c7d95d1148f892182090e6006924",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "04.页签新增",\n  "createTime": 1782955345291,\n  "updateTime": 1784437771882,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/add",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pid\\": \\"1f079665d86b4e06b7542247498eb9f0\\",\\n    \\"tabType\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"680185f2a6ed43adb6b4dd4766efeb67\\"\\n    }\\n}",\n  "description": "校验请求资料后执行页签新增，返回保存或配置结果；使用请求参数 pid、tabType、relaId、name、nameCn、thumbnail、publishId、seqNo；涉及 app_workshop_repository_tab 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.页签新增\n// 路由：POST /das/repository/tab/add\n// 业务说明：校验请求资料后执行页签新增，返回保存或配置结果；使用请求参数 pid、tabType、relaId、name、nameCn、thumbnail、publishId、seqNo；涉及 app_workshop_repository_tab 等业务表。\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport log\n\n\n/**\n * 应用仓库页签新增\n * POST /api/das/repository/tab/add\n */\n\nvar pid = body?.pid\nif (pid == null || pid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'应用仓库ID(pid)不能为空\' \n}\n\nvar tabType = body?.tabType\nif (tabType == null || tabType == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'页签类型(tabType)不能为空\' \n}\n\nif ([0,1,2,3].contains(tabType::int) == false) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'页签类型(tabType)仅支持 0/1/2/3\' \n}\n\nvar relaId = body?.relaId\n\nif (db.selectInt("select count(1) from app_workshop_repository where is_del = 0 and tid = #{pid}") == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'应用仓库不存在\' \n}\n\nif (relaId != null && relaId != \'\' && db.selectInt("""\n        select count(1)\n          from app_workshop_repository_tab\n         where is_del = 0 and pid = #{pid} and tab_type = #{tabType} and rela_id = #{relaId}\n    """) > 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'页签已存在\' \n}\n\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\nvar tid = IdUtil.getSnowflakeNextIdStr()\nvar currentUserId = StpUtil.getLoginId() + ""\n\ndb.table(\'app_workshop_repository_tab\')\n    .insert({\n        tid: tid,\n        pid: pid,\n        tab_type: tabType::int,\n        rela_id: relaId,\n        name: body?.name,\n        name_cn: body?.nameCn,\n        thumbnail: body?.thumbnail,\n        publish_id: body?.publishId,\n        seq_no: body?.seqNo::int(0),\n        is_del: 0,\n        created_by: currentUserId,\n        created_time: currentTime,\n        updated_by: currentUserId,\n        updated_time: currentTime\n    })\n\nlog.info(\'新增应用仓库页签成功, tid: {}, pid: {}, tabType: {}, relaId: {}\', tid, pid, tabType, relaId)\n\n// 返回当前业务分支的标准结果。\nreturn  {\n  tid : tid\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/04.页签新增.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ad917e60dad742ec94d462697944d7c7',NULL,NULL,'{\n  "properties": {},\n  "id": "ad917e60dad742ec94d462697944d7c7",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "05.页签缩略图",\n  "createTime": 1782955345299,\n  "updateTime": 1784437771883,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveTabThumbnail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"页签id\\",\\n    \\"thumbnail\\": \\"URL\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": \\"1ea1bd0491654e6e8dbbf9c5e1ee544f\\"\\n}",\n  "description": "校验页签标识和缩略图内容，更新应用仓库页签的缩略图字段并返回保存结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.页签缩略图\n// 路由：POST /das/repository/tab/saveTabThumbnail\n// 业务说明：校验页签标识和缩略图内容，更新应用仓库页签的缩略图字段并返回保存结果。\nimport log\nimport cn.dev33.satoken.stp.StpUtil;\n\n\n// 参数校验\nvar tid = body?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'页签ID不能为空\'\n}\n\n// 检查记录是否存在\nvar exists = db.table(\'app_workshop_repository_tab\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .count()\n\nif (exists == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'页签不存在\'\n}\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\nvar currentUserId = StpUtil.getLoginId() + ""\n\n// 构建更新数据\nvar updateData = {\n    updated_by: currentUserId,\n    updated_time: currentTime\n}\n\nif (body?.thumbnail != null && body?.thumbnail != \'\') {\n    updateData.thumbnail = body?.thumbnail\n}\n\n// 更新数据\ndb.table(\'app_workshop_repository_tab\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .update(updateData)\n\nlog.info(\'修改应用仓库成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn tid\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/05.页签缩略图.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('20df1f42ab43450f9ec60780f83df52b',NULL,NULL,'{\n  "properties": {},\n  "id": "20df1f42ab43450f9ec60780f83df52b",\n  "script": null,\n  "groupId": "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\n  "name": "06.页签详情",\n  "createTime": 1782955345307,\n  "updateTime": 1784437771886,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按页签主键读取应用仓库页签配置，返回编辑页面所需的详情。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.页签详情\n// 路由：POST /das/repository/tab/queryById\n// 业务说明：按页签主键读取应用仓库页签配置，返回编辑页面所需的详情。\nimport log\nimport uiComponentAdmin\n\n/**\n * 应用仓库页签详情\n * GET /api/das/repository/tab/detail/{tid}\n */\n\nvar tid = body?.tid || path?.tid\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "页签ID不能为空"\n}\n\nvar sql = """\n    select\n        t.tid,\n        t.pid,\n        t.name,\n        t.name_cn,\n        t.tab_type,\n        t.rela_id,\n        t.publish_id,\n        t.thumbnail,\n        t.seq_no,\n        t.created_by,\n        t.created_time,\n        t.updated_by,\n        t.updated_time,\n        case\n            when t.tab_type = 3 then bs.name_cn\n            when t.tab_type = 2 then sf.form_name\n            else null\n        end as rela_name_cn,\n        case\n            when t.tab_type = 3 then bs.name\n            when t.tab_type = 2 then sf.form_name\n            else null\n        end as rela_name\n    from app_workshop_repository_tab t\n    left join app_workshop_big_screen bs on bs.tid = t.rela_id and bs.is_del = 0 and t.tab_type = 3\n    left join sym_form sf on sf.tid = t.rela_id and sf.is_del = 0 and t.tab_type = 2\n    where t.is_del = 0\n    and t.tid = #{tid}\n"""\n\n// 从 MySQL 业务表读取当前有效数据。\nvar detail = db.selectOne(sql)\nif (detail == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, "页签不存在"\n}\nuiComponentAdmin.enrichRepositoryTabs([detail])\n\nlog.info(\'查询应用仓库页签详情成功, tid: {}\', tid)\n\n// 返回当前业务分支的标准结果。\nreturn detail\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/06.页签详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8f2a6564b6fd43c28ff7a5e35d4d7cd2',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "8f2a6564b6fd43c28ff7a5e35d4d7cd2",\r\n  "name" : "03.页签",\r\n  "type" : "api",\r\n  "parentId" : "37c35deab6bc4e678c8955cc951f2ffd",\r\n  "path" : "/tab",\r\n  "createTime" : 1781960052561,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/03.页签/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7620748a6f17464fab1e392b278c6365',NULL,NULL,'{\n  "properties": {},\n  "id": "7620748a6f17464fab1e392b278c6365",\n  "script": null,\n  "groupId": "37c35deab6bc4e678c8955cc951f2ffd",\n  "name": "04.应用发布",\n  "createTime": 1782955345178,\n  "updateTime": 1784437771872,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/publish",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"xxxx\\",\\n    \\"publishStatus\\": \\"0\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": null\\n}",\n  "description": "按请求目标与业务状态执行应用发布，返回本次操作结果；使用请求参数 tid、publishStatus；涉及 app_workshop_repository 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.应用发布\n// 路由：POST /das/repository/publish\n// 业务说明：按请求目标与业务状态执行应用发布，返回本次操作结果；使用请求参数 tid、publishStatus；涉及 app_workshop_repository 等业务表；执行数据库写入并返回处理结果。\nimport log\nimport cn.dev33.satoken.stp.StpUtil;\n\n// 解析请求体并为可选参数设置默认值。\nvar tid = body?.tid\nvar publishStatus  = body?.publishStatus\n\n// 生成主键ID\nvar currentUserId = StpUtil.getLoginId() + ""\nvar createdBy = currentUserId\nvar updatedBy = currentUserId\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\n// 构建更新数据\nvar updateData = {\n    updated_by: currentUserId,\n    updated_time: currentTime\n}\n\nif (body?.publishStatus != null && body?.publishStatus != \'\') {\n    updateData.publish_status = body?.publishStatus\n}\n\n\n// 从 MySQL 业务表读取当前有效数据。\ndb.table("app_workshop_repository").where()\n.eq("tid", tid).update(updateData)\n\n// 返回当前业务分支的标准结果。\nreturn "success"\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/04.应用发布.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9e49822ca4814e2bbad915ac4bd74c0f',NULL,NULL,'{\n  "properties": {},\n  "id": "9e49822ca4814e2bbad915ac4bd74c0f",\n  "script": null,\n  "groupId": "37c35deab6bc4e678c8955cc951f2ffd",\n  "name": "05.新增应用",\n  "createTime": 1782955345188,\n  "updateTime": 1784437771872,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/add",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"appName\\": \\"数据资产管理平台\\",\\n    \\"appType\\": 1,\\n    \\"description\\": \\"用于管理数据资产的综合性平台\\",\\n    \\"appIcon\\": \\"https://example.com/icon.png\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"1f079665d86b4e06b7542247498eb9f0\\"\\n    }\\n}",\n  "description": "校验请求资料后执行新增应用，返回保存或配置结果；使用请求参数 appName、appType、description、appIcon、publishStatus；涉及 app_workshop_repository 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.新增应用\n// 路由：POST /das/repository/add\n// 业务说明：校验请求资料后执行新增应用，返回保存或配置结果；使用请求参数 appName、appType、description、appIcon、publishStatus；涉及 app_workshop_repository 等业务表。\nimport log\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil\n\n/**\n * 应用仓库新增\n * POST /api/das/repository/add\n * \n * 新增应用仓库记录\n */\n\n// 参数校验\nvar appName = body?.appName\nif (appName == null || appName == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用名称不能为空\'\n}\n\nvar appType = body?.appType\nif (appType == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用类型不能为空\'\n}\n\n// 生成主键ID\nvar tid = IdUtil.getSnowflakeNextIdStr()\nvar currentUserId = StpUtil.getLoginId() + ""\nvar createdBy = currentUserId\nvar updatedBy = currentUserId\n\n// 获取当前时间\nvar now = new Date()\nvar currentTime = now.format(\'yyyy-MM-dd HH:mm:ss\')\n\n// 插入数据\ndb.table(\'app_workshop_repository\')\n    .insert({\n        tid: tid,\n        app_name: appName,\n        app_type: appType,\n        description: body?.description,\n        app_icon: body?.appIcon,\n        publish_status: body?.publishStatus::int(0),\n        is_del: 0,\n        created_by: createdBy,\n        created_time: currentTime,\n        updated_by: updatedBy,\n        updated_time: currentTime\n    })\n\nlog.info(\'新增应用仓库成功, tid: {}, appName: {}\', tid, appName)\n\n// ========== 返回结果 ==========\nreturn {\n        tid: tid \n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/05.新增应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('237d7a94845b43baadfdca2351155bae',NULL,NULL,'{\n  "properties": {},\n  "id": "237d7a94845b43baadfdca2351155bae",\n  "script": null,\n  "groupId": "37c35deab6bc4e678c8955cc951f2ffd",\n  "name": "06.根据ID获取应用",\n  "createTime": 1782955345197,\n  "updateTime": 1784437771873,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/queryById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"tid\\": \\"1\\",\\n        \\"tenantId\\": \\"1\\",\\n        \\"revision\\": \\"1\\",\\n        \\"createdBy\\": \\"2\\",\\n        \\"createdTime\\": \\"2026-04-22 11:16:17\\",\\n        \\"isDel\\": 0,\\n        \\"updatedBy\\": null,\\n        \\"updatedTime\\": null,\\n        \\"appName\\": null,\\n        \\"appType\\": null,\\n        \\"appIcon\\": null,\\n        \\"description\\": null,\\n        \\"publishStatus\\": null,\\n        \\"publishUrl\\": null,\\n        \\"publishId\\": null\\n    }\\n}",\n  "description": "根据ID查询应用仓库详细信息；使用请求参数 tid；涉及 app_workshop_repository 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.根据ID获取应用\n// 路由：POST /das/repository/queryById\n// 业务说明：根据ID查询应用仓库详细信息；使用请求参数 tid；涉及 app_workshop_repository 等业务表。\nimport log\n\n/**\n * 应用仓库详情查询\n * GET /api/das/repository/detail/{tid}\n * \n * 根据ID查询应用仓库详细信息\n */\n\n// 获取应用ID\nvar tid = body?.tid\n\nif (tid == null || tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用ID不能为空\'\n}\n\n// 查询应用详情\nvar appInfo = db.table(\'app_workshop_repository\')\n    .where()\n    .eq(\'tid\', tid)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\nif (appInfo == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500,\'应用不存在\'\n}\n\nlog.info(\'查询应用仓库详情成功, tid: {}\', tid)\n\n// ========== 返回结果 ==========\nreturn appInfo\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/06.根据ID获取应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('37c35deab6bc4e678c8955cc951f2ffd',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "37c35deab6bc4e678c8955cc951f2ffd",\r\n  "name" : "01.应用仓库",\r\n  "type" : "api",\r\n  "parentId" : "196ee3f39e364f1eb1a9eed14cd9f372",\r\n  "path" : "/repository",\r\n  "createTime" : 1781960052218,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/07.数据应用/01.应用仓库/group.json');
