INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0f92ce81bd7741378f287047353e5a61',NULL,NULL,'{\n  "properties": {},\n  "id": "0f92ce81bd7741378f287047353e5a61",\n  "script": null,\n  "groupId": "ed37113428464a0686dfafbe52429f2f",\n  "name": "01.同步删除es与库数据",\n  "createTime": 1782955343467,\n  "updateTime": 1784437771640,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/syncEsDbData",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"esTotal\\": 6527,\\n        \\"dbTotal\\": 6527,\\n        \\"deleted\\": 0,\\n        \\"message\\": \\"数据一致，无需删除\\"\\n    }\\n}",\n  "description": "清理 ES 中已经没有数据库主记录的资产。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.同步删除es与库数据\n// 路由：GET /scene/fix/syncEsDbData\n// 业务说明：清理 ES 中已经没有数据库主记录的资产。\n/*\n * 清理 ES 中已经没有数据库主记录的资产\n *\n * 数据库有效 ID 来自应用、数据源、数据表和通用资产四张主表。脚本只删除\n * ES 孤立文档；数据库存在但 ES 缺失的 ID 会返回给调用方，由盘点维护的\n * batchRefresh 接口统一重建，避免在修复脚本中复制索引组装逻辑。\n */\nimport tenantEs\nimport \'@/common/configData\' as configData\nimport java.util.HashSet\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar index = tenantEs.index(configData().es_dataassets)\nvar response = index.search({\n    size: 10000,\n    query: {match_all: {}},\n    _source: false\n})\nvar esIds = new HashSet()\nfor (hit in response.hits.hits || []) {\n    esIds.add(hit._id + \'\')\n}\n\nvar dbIds = new HashSet()\nfor (tableName in [\'sym_application_t\', \'db_datasource_t\', \'db_table_t\', \'da_asset_t\']) {\n    // 从 MySQL 业务表读取当前有效数据。\n    for (row in db.table(tableName).columns(\'tid\').where().eq(\'is_del\', 0).select()) {\n        dbIds.add(row.tid + \'\')\n    }\n}\n\nvar deletedIds = []\nfor (id in esIds) {\n    if (!dbIds.contains(id)) {\n        index.deleteById(id)\n        deletedIds.add(id)\n    }\n}\nvar dbOnlyIds = []\nfor (id in dbIds) {\n    if (!esIds.contains(id)) {\n        dbOnlyIds.add(id)\n    }\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    esTotal: esIds.size(),\n    dbTotal: dbIds.size(),\n    deleted: deletedIds.size(),\n    deletedIds: deletedIds,\n    dbOnlyCount: dbOnlyIds.size(),\n    dbOnlyIds: dbOnlyIds\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/01.修复数据脚本/01.同步删除es与库数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('20c77a091d414533b4e1f6a34fec5e91',NULL,NULL,'{\n  "properties": {},\n  "id": "20c77a091d414533b4e1f6a34fec5e91",\n  "script": null,\n  "groupId": "ed37113428464a0686dfafbe52429f2f",\n  "name": "02.数据一致性检查与修复接口",\n  "createTime": 1782955343476,\n  "updateTime": 1787153756892,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/syncAllEsDbData",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"esTotal\\": 6527,\\n        \\"dbTotal\\": 6550,\\n        \\"esOnlyCount\\": 0,\\n        \\"esOnlyIds\\": [],\\n        \\"dbOnlyCount\\": 23,\\n        \\"dbOnlyIds\\": [\\n            \\"14b050c6463145fbb7e6609adfe7475b\\",\\n            \\"6833a325770c4f2883696beb20bc04c3\\",\\n            \\"b20e23f919a14ae3bffd476525c345b8\\",\\n            \\"a376ce0b2e7a407fa7c7820971bf5df9\\",\\n            \\"7f5e19418bb34588841c3ccc3e2b4236\\",\\n            \\"a2595f305d0744b49a466751c770dbf1\\",\\n            \\"94c6c16e0c2f497ebf0a49038849ce2f\\",\\n            \\"af1f322269854974a7bba14a186404c9\\",\\n            \\"1bf1f54327b242d6b2035871f43f4143\\",\\n            \\"ff0d4acbbc074ec8a0437ba1ac6bd4dd\\",\\n            \\"4992dd7064e74ebfa358fbd4a7732689\\",\\n            \\"e8756faf938b49028bdd05c71b93e277\\",\\n            \\"3a12ba2ec6f04c0b9fca2090260a6aba\\",\\n            \\"dd8fd7573902496399236e3f1a424feb\\",\\n            \\"eda920c7cf5040ba9710dbf2bc1589c7\\",\\n            \\"775dfa8d00a7426ca3fe828feeac16b6\\",\\n            \\"7ad43e49b8a44ccf98c2b2b151870654\\",\\n            \\"f3b8f45c9cfc445982d710bc231f87b6\\",\\n            \\"7a206563dadf4e559491e8bd81958ac4\\",\\n            \\"8ae4ea06c7244c5f809ef356294134e5\\",\\n            \\"ee9ef838038f4148a491d9e0668c0bd4\\",\\n            \\"9c9fa0c666e84c10824da6b6b7f7d1cb\\",\\n            \\"85899a408fc7461faca66f2d2b1f6ebd\\"\\n        ],\\n        \\"mismatchCount\\": 0,\\n        \\"fixedCount\\": 0,\\n        \\"fixedFailed\\": 0,\\n        \\"mismatchList\\": [],\\n        \\"message\\": \\"检查完成\\"\\n    }\\n}",\n  "description": "说明: 检查DB和ES的数据一致性，修复动态字段不一致的数据；涉及 da_asset_t、da_prop_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据一致性检查与修复接口\n// 路由：GET /scene/fix/syncAllEsDbData\n// 业务说明：说明: 检查DB和ES的数据一致性，修复动态字段不一致的数据；涉及 da_asset_t、da_prop_t 等业务表；执行数据库写入并返回处理结果。\n// 数据一致性检查与修复接口\n// 路径: /api/dataassets/syncAll\n// 方法: POST\n// 参数: 无\n// 说明: 检查DB和ES的数据一致性，修复动态字段不一致的数据\n// da_asset_t: 主表（基础信息）\n// da_prop_t: 副表（动态字段，prop_name+prop_value，parent_id关联主表tid）\n\nimport tenantEs;\nimport \'@/common/configData\' as configData\n\ntry {\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var esIndex = tenantEs.index(configData().es_dataassets);\n\n    // 需要检查的动态字段列表\n    var checkFields = ["orgId", "dbId", "appId", "catalogId", "targetTableId", "sourceTableId"];\n\n    // ========== 1. 从ES查询所有记录 ==========\n    var esDsl = {\n        "size": 9000,\n        "query": { "match_all": {} },\n        "_source": checkFields\n    };\n    var esResult = esIndex.search(esDsl);\n    var esTotal = esResult.hits.total.value;\n\n    // ES数据：tid列表 + tid->source映射\n    var esTids = [];\n    var esSourceList = [];\n    for (hit in esResult.hits.hits) {\n        esTids.push(hit._id);\n        esSourceList.push(hit._source);\n    }\n\n    // ========== 2. 从主表查询所有资产tid ==========\n    var assetRecords = db.table("da_asset_t").select();\n    var dbTids = [];\n    for (record in assetRecords) {\n        dbTids.push(record.tid);\n    }\n\n    // ========== 3. 从副表查询动态字段 ==========\n    var propRecords = db.table("da_prop_t")\n        .where().in("prop_name", checkFields)\n        .select();\n\n    // 构建映射：用数组存储 { parentId, propName, propValue }\n    var propList = [];\n    for (record in propRecords) {\n        propList.push({\n            parentId: record.parent_id,\n            propName: record.prop_name,\n            propValue: record.prop_value\n        });\n    }\n\n    // ========== 4. 对比并找出不一致的记录 ==========\n    var mismatchList = [];\n    var fixedCount = 0;\n    var fixedFailed = 0;\n\n    for (idx in range(0, esTids.size().asInt() - 1)) {\n        var tid = esTids[idx];\n        var esSrc = esSourceList[idx];\n\n        // 从propList中找该tid的动态字段\n        var hasProp = false;\n        var hasMismatch = false;\n        var updateData = {};\n        var mismatchInfo = { tid: tid };\n\n        for (prop in propList) {\n            if (prop.parentId == tid) {\n                hasProp = true;\n                var field = prop.propName;\n                var dbVal = prop.propValue;\n                var esVal = esSrc[field];\n                if (!dbVal) { dbVal = \'\'; }\n                if (!esVal) { esVal = \'\'; }\n                if (dbVal != esVal) {\n                    hasMismatch = true;\n                    updateData[field] = dbVal;\n                    mismatchInfo[field] = { db: dbVal, es: esVal };\n                }\n            }\n        }\n\n        if (hasProp && hasMismatch) {\n            mismatchList.push(mismatchInfo);\n            try {\n                // esIndex.doc(tid).update(updateData);\n                fixedCount = fixedCount + 1;\n            } catch(ex) {\n                fixedFailed = fixedFailed + 1;\n            }\n        }\n    }\n\n    // ========== 5. 找出ES有但DB没有的记录 ==========\n    var esOnlyIds = [];\n    for (tid in esTids) {\n        var found = false;\n        for (dbTid in dbTids) {\n            if (dbTid == tid) { found = true; break; }\n        }\n        if (!found) { esOnlyIds.push(tid); }\n    }\n\n    // ========== 6. 找出DB有但ES没有的记录 ==========\n    var dbOnlyIds = [];\n    for (tid in dbTids) {\n        var found = false;\n        for (esTid in esTids) {\n            if (esTid == tid) { found = true; break; }\n        }\n        if (!found) { dbOnlyIds.push(tid); }\n    }\n\n    // ========== 7. 返回结果 ==========\n    return {\n        esTotal: esTotal,\n        dbTotal: dbTids.size().asInt(),\n        esOnlyCount: esOnlyIds.size().asInt(),\n        esOnlyIds: esOnlyIds,\n        dbOnlyCount: dbOnlyIds.size().asInt(),\n        dbOnlyIds: dbOnlyIds,\n        mismatchCount: mismatchList.size().asInt(),\n        fixedCount: fixedCount,\n        fixedFailed: fixedFailed,\n        mismatchList: mismatchList,\n        message: "检查完成"\n    };\n\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'检查失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/01.修复数据脚本/02.数据一致性检查与修复接口.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4fcea3331dc44d808464c76609faa343',NULL,NULL,'{\n  "properties": {},\n  "id": "4fcea3331dc44d808464c76609faa343",\n  "script": null,\n  "groupId": "ed37113428464a0686dfafbe52429f2f",\n  "name": "03.统一rowCount和recordCount",\n  "createTime": 1782955343485,\n  "updateTime": 1787153756964,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/execDsl_copy",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"result\\": []\\n    }\\n}",\n  "description": "统一表资产 rowCount 与 recordCount；涉及 db_table_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.统一rowCount和recordCount\n// 路由：GET /scene/fix/execDsl_copy\n// 业务说明：统一表资产 rowCount 与 recordCount；涉及 db_table_t 等业务表；执行数据库写入并返回处理结果。\n/*\n * 统一表资产 rowCount 与 recordCount\n *\n * db_table_t.record_count 是唯一持久化字段。脚本取 ES 两个历史字段的较大值\n * 回写主表，并重建当前表的 ES 投影字段；不再向 da_prop_t 写 table 属性。\n */\nimport tenantEs\nimport \'@/common/configData\' as configData\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar index = tenantEs.index(configData().es_dataassets)\nvar response = index.search({\n    size: 10000,\n    query: {term: {assetType: \'table\'}},\n    _source: true\n})\nvar changed = []\nfor (hit in response.hits.hits || []) {\n    // 从 MySQL 业务表读取当前有效数据。\n    var table = db.table(\'db_table_t\').where().eq(\'tid\', hit._id).eq(\'is_del\', 0).selectOne()\n    if (table == null) {\n        continue\n    }\n    var rowCount = hit._source?.rowCount == null ? 0 : hit._source.rowCount::long\n    var recordCount = hit._source?.recordCount == null ? 0 : hit._source.recordCount::long\n    var count = Math.max(rowCount, recordCount)\n    if ((table.recordCount || 0)::long != count) {\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table(\'db_table_t\').where().eq(\'tid\', hit._id)\n            .update({record_count: count, updated_time: new Date()})\n    }\n    var document = hit._source || {}\n    document.tid = hit._id\n    document.assetType = \'table\'\n    document.rowCount = count\n    document.recordCount = count\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    esCommonService.saveOrUpdate(\'dataassets\', hit._id + \'\', jsons.toJSONStr(document), false)\n    if (rowCount != count || recordCount != count) {\n        changed.add({tid: hit._id, rowCount: count, recordCount: count})\n    }\n}\n// 返回当前业务分支的标准结果。\nreturn {changed: changed.size(), list: changed}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/01.修复数据脚本/03.统一rowCount和recordCount.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ed37113428464a0686dfafbe52429f2f',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "ed37113428464a0686dfafbe52429f2f",\r\n  "name" : "01.修复数据脚本",\r\n  "type" : "api",\r\n  "parentId" : "5ac60a54d85b4682ab46fbb8def36ea2",\r\n  "path" : "/fix",\r\n  "createTime" : 1782721455984,\r\n  "updateTime" : 1784437771538,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/01.修复数据脚本/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0080724117804c1480eac250e14073b1',NULL,NULL,'{\n  "properties": {},\n  "id": "0080724117804c1480eac250e14073b1",\n  "script": null,\n  "groupId": "5ac60a54d85b4682ab46fbb8def36ea2",\n  "name": "01.资产全景标题",\n  "createTime": 1782955343347,\n  "updateTime": 1784437771540,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/title",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 100120,\\n    \\"msg\\": \\"no_login\\",\\n    \\"desc\\": \\"未登录\\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "返回脚本内固定的资产全景标题、导航和跳转地址；当前不从租户库实时计算。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "no_login",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "desc",\n        "value": "未登录",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：01.资产全景标题\n// 路由：GET /scene/title\n// 业务说明：返回脚本内固定的资产全景标题、导航和跳转地址；当前不从租户库实时计算。\n// 返回当前业务分支的标准结果。\nreturn {\n        scenceTitle: \'“海上福建”数据专区\',\n        nav: [\n            {\n            "title": "海洋要素中心",\n            "url": "http://192.168.175.86:10083/me/#/",\n            // "url": "http://14.103.233.56/me",\n            "target": "_self"\n            },\n            {\n            "title": "数据资源管理",\n            "url": "http://192.168.175.86:10083/#/zl/zl-sjzz/list",\n            "target": "_blank"\n            }\n        ],\n        layer: [\'数据开放层\', \'数据整合层\', \'数源层\'],\n\n        overview: [\'数据汇聚\', \'数据共享\'],\n        overviewTab: [\'数据资源\',\'数据目录\',\'业务系统\'],\n        // 页面上+中标题\n        topLeft: ["数据总量","今日新增"],\n        topRight: ["数据汇聚","数据共享"],\n        topUnit: ["条","条","条","条"],\n        middleLeft: "数据增长趋势",\n        middleRight: "数据汇聚共享情况",\n\n        bottomLeft: \'局内数据归集情况\',\n        bottomRight: \'外部数据归集情况\',\n        bottomRightTab: [],\n\n        // 第一层标题\n        shareLayerTitle: [\'数据汇聚\',\'应用场景\',\'数据共享\'],\n        shareLayerLeft: [\'汇聚系统\', \'汇聚目录\', \'汇聚数据\'],\n        shareLayerMiddle: [\'特色场景\', \'应用系统\', \'数据指标\'],\n        shareLayerRight: [\'API接口\', \'开放目录\', \'共享数据\'],\n\n        // 第三层标题\n        collectLayerLeft: [\'国家部委\', \'部委数据\', \'数据总量\'],\n        collectLayerMiddle: [\'局内系统\', \'局内数据\', \'数据总量\'],\n        collectLayerRight: [\'横向厅局\', \'厅局数据\', \'数据总量\'],\n      }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/01.资产全景标题.ms');
