INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d28034db5ada48bcbdf74959880f1a2e',NULL,NULL,'{\n  "properties": {},\n  "id": "d28034db5ada48bcbdf74959880f1a2e",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "01.局内数据归集情况",\n  "createTime": 1782955343551,\n  "updateTime": 1784437771675,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/innerStat",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"departId\\": \\"2058490591645663234\\",\\n            \\"departName\\": \\"办公室\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 1\\n        },\\n        {\\n            \\"departId\\": \\"2058552064266862593\\",\\n            \\"departName\\": \\"海洋经济处\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 2\\n        },\\n        {\\n            \\"departId\\": \\"2058552152884117505\\",\\n            \\"departName\\": \\"防灾减灾处\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058552216662704130\\",\\n            \\"departName\\": \\"渔业与质量监督处\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 1\\n        },\\n        {\\n            \\"departId\\": \\"2058552271218016258\\",\\n            \\"departName\\": \\"渔船渔港管理处\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058552438872735746\\",\\n            \\"departName\\": \\"科技与对外合作处\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058552749586776065\\",\\n            \\"departName\\": \\"福建省渔业资源监测中心\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058552847548940290\\",\\n            \\"departName\\": \\"福建省海洋预报台\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058552907896586242\\",\\n            \\"departName\\": \\"福建省海洋经济运行监测与评估中心\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2067450426957762560\\",\\n            \\"departName\\": \\"海洋与渔业数据中心\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        },\\n        {\\n            \\"departId\\": \\"2058493826078998529\\",\\n            \\"departName\\": \\"福建省渔业减灾中心\\",\\n            \\"dataHjCount\\": 25148984,\\n            \\"categoryHjCount\\": 84\\n        },\\n        {\\n            \\"departId\\": \\"2069338822711939072\\",\\n            \\"departName\\": \\"福建省水产研究所\\",\\n            \\"dataHjCount\\": 0,\\n            \\"categoryHjCount\\": 0\\n        }\\n    ]\\n}",\n  "description": "读取归集应用接口结果，筛出局内机构的数据归集情况并转换为大屏展示结构。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.局内数据归集情况\n// 路由：GET /scene/data-count/innerStat\n// 业务说明：读取归集应用接口结果，筛出局内机构的数据归集情况并转换为大屏展示结构。\nimport "@get:/scene/collect/app" as collectApp\n\n// 解析 HTTP 导入响应（兼容 magic-api 自动包裹的 {code, data} 格式）\nvar unwrap = (result) => {\n    if (result == null) { return null; }\n    // 如果响应被 magic-api 框架包裹为 { code, message, data } 格式，提取 data 部分\n    if (result.data != null && result.code != null) { return result.data; }\n    // 返回当前业务分支的标准结果。\n    return result;\n}\n\n// ==================== 构造 city_depart_hj（局内机构 → 部门汇总） ====================\nvar buildCityDepartHj = (jnResult) => {\n    var data = unwrap(jnResult)\n    var list = []\n    if (data != null && data.list != null) {\n        list = data.list\n    }\n    var cityDepartHj = []\n    for (item in list) {\n        cityDepartHj.add({\n            "departId": item.orgId != null ? item.orgId : "",\n            "departName": item.orgName != null ? item.orgName : "",\n            "dataHjCount": item.dataHjCount != null ? item.dataHjCount : 0,\n            "categoryHjCount": item.categoryHjCount != null ? item.categoryHjCount : 0\n        })\n    }\n    // 返回当前业务分支的标准结果。\n    return cityDepartHj\n}\nvar pageSize = 20\n// 返回当前业务分支的标准结果。\nreturn buildCityDepartHj(collectApp())\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/01.局内数据归集情况.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('728917c4af3943ccaee009539b18a004',NULL,NULL,'{\n  "properties": {},\n  "id": "728917c4af3943ccaee009539b18a004",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "02.局外数据归集情况",\n  "createTime": 1782955343560,\n  "updateTime": 1784437771684,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/outerStat",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 500,\\n    \\"msg\\": \\"org.ssssssss.script.exception.MagicScriptException: 在1中找不到属性data或者方法getData、方法isData,内部类data at Row:7~7,Col:16~19\\\\n\\\\n    if (result.data != null && result.code != null) { return result.data; }\\\\r\\\\n               ^^^^                                                         \\",\\n    \\"success\\": false,\\n    \\"data\\": null\\n}",\n  "description": "读取归集应用接口结果，筛出局外机构的数据归集情况并转换为大屏展示结构。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "500",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "org.ssssssss.script.exception.MagicScriptException: 在1中找不到属性data或者方法getData、方法isData,内部类data at Row:7~7,Col:16~19\\n\\n    if (result.data != null && result.code != null) { return result.data; }\\r\\n               ^^^^                                                         ",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：02.局外数据归集情况\n// 路由：GET /scene/data-count/outerStat\n// 业务说明：读取归集应用接口结果，筛出局外机构的数据归集情况并转换为大屏展示结构。\nimport "@get:/scene/collect/app" as collectApp\n\n// 解析 HTTP 导入响应（兼容 magic-api 自动包裹的 {code, data} 格式）\nvar unwrap = (result) => {\n    if (result == null) { return null; }\n    // 如果响应被 magic-api 框架包裹为 { code, message, data } 格式，提取 data 部分\n    if (result.data != null && result.code != null) { return result.data; }\n    // 返回当前业务分支的标准结果。\n    return result;\n}\n\n// ==================== 构造 area_hj（局外机构 → 厅局区域汇总） ====================\nvar queryType = 1\nvar buildAreaHj = (jwResult) => {\n    var data = unwrap(jwResult)\n    var list = []\n    if (data != null && data.list != null) {\n        list = data.list\n    }\n    var areaHj = []\n    for (item in list) {\n        areaHj.add({\n            "areaName": "\\n" + (item.orgName != null ? item.orgName : ""),\n            "tagCount": item.tagCount != null ? item.tagCount : 0,\n            "departCount": 0,\n            "appCount": 0,\n            "appHjCount": 0,\n            "categoryCount": item.categoryCount != null ? item.categoryCount : 0,\n            "categoryHjCount": item.categoryHjCount != null ? item.categoryHjCount : 0,\n            "dataCount": 0,\n            "dataHjCount": item.dataHjCount != null ? item.dataHjCount : 0,\n            "gxjsCount": 0,\n            "gxyhCount": 0,\n            "gxjsRate": 0\n        })\n    }\n    // 返回当前业务分支的标准结果。\n    return areaHj\n}\n\n// 返回当前业务分支的标准结果。\nreturn buildAreaHj(collectApp(queryType))\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/02.局外数据归集情况.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('40479a2f64a74864996b994895453196',NULL,NULL,'{\n  "properties": {},\n  "id": "40479a2f64a74864996b994895453196",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "03.数据开放层",\n  "createTime": 1782955343570,\n  "updateTime": 1784437771688,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/data-share",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"shareLayerLeft\\": [\\n            10,\\n            101,\\n            109647\\n        ],\\n        \\"shareLayerMiddle\\": [\\n            8,\\n            2,\\n            35\\n        ],\\n        \\"shareLayerRight\\": [\\n            0,\\n            2,\\n            836\\n        ]\\n    }\\n}",\n  "description": "统计共享应用、目录及数据量，按大屏的左中右三个区域组装开放层指标。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.数据开放层\n// 路由：GET /scene/data-count/data-share\n// 业务说明：统计共享应用、目录及数据量，按大屏的左中右三个区域组装开放层指标。\n// 数据开放层-大屏统计接口\n// 路径: /api/shareLayer/dashboard\n// 方法: POST\n// 参数: 无\n// 返回: { shareLayerLeft: [appCount, catalogCount, recordTotal], shareLayerMiddle: [fixed8, appCount, fieldTotal], shareLayerRight: [apiCount, catalogCount, recordTotal] }\n\nimport tenantEs;\nimport \'@/common/configData\' as configData;\nimport cn.hutool.core.util.StrUtil\n\nvar sumRecordScript = "if (doc[\'recordCount\'].size() == 0) { return 0; } def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;";\nvar sumFieldScript  = "if (doc[\'fieldCount\'].size() == 0)  { return 0; } def v = doc[\'fieldCount\'].value;  if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;";\n\ntry {\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var esIndex = tenantEs.index(configData().es_dataassets);\n\n    // ================================================================\n    // Q1: 汇聚目录统计 — catalog 有 targetTableId（数据汇聚）\n    // ================================================================\n    var convergeDsl = {\n        "size": 9000,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "catalog" } },\n                    // { "term": { "assetStatus": 2 } },\n                    { "exists": { "field": "targetTableId" } }\n                ]\n            }\n        },\n        "_source": ["appId", "targetTableId"]\n    };\n\n    var convergeResult = esIndex.search(convergeDsl);\n    var convergeAppCnt     = 0;\n    var convergeCatalogCnt = convergeResult.hits.total.value;\n    var convergeRecordSum  = 0;\n    var convergeTableIds = [];\n    var convergeAppIdMap = {};\n    for (hit in convergeResult.hits.hits) {\n        var src = hit._source;\n        if (src.targetTableId) { convergeTableIds.push(src.targetTableId); }\n        if (src.appId) { convergeAppIdMap[src.appId] = true; }\n    }\n    for (k in convergeAppIdMap.keySet()) { convergeAppCnt = convergeAppCnt + 1; }\n\n    // Q1.1: 查询挂接表的recordCount总和\n    if (convergeTableIds.size().asInt() > 0) {\n        var convergeTableDsl = {\n            "size": 0,\n            "query": {\n                "bool": {\n                    "filter": [\n                        { "term": { "assetType": "table" } },\n                        { "terms": { "tid": convergeTableIds } }\n                    ]\n                }\n            },\n            "aggs": {\n                "total_records": { "sum": { "script": { "source": sumRecordScript, "lang": "painless" } } }\n            }\n        };\n        var convergeTableResult = esIndex.search(convergeTableDsl);\n        convergeRecordSum = convergeTableResult.aggregations.total_records.value;\n    }\n\n    // ================================================================\n    // Q2: 已发布目录 — catalog.publishStatus = "1"\n    //     取出文档级数据供后续 Q3/Q4 使用\n    // ================================================================\n    var publishedDsl = {\n        "size": 9000,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "catalog" } },\n                    { "term": { "publishStatus": 1 } }\n                ]\n            }\n        },\n        "_source": ["id", "appId", "targetTableId", "recordCount"]\n    };\n\n    var publishedResult = esIndex.search(publishedDsl);\n    var publishedHits   = publishedResult.hits.hits;\n    var publishedTotal  = publishedResult.hits.total.value;\n\n    // 从已发布目录文档中提取:\n    //   catalogIds       → 用于 Q4 查 API\n    //   targetTableIds   → 用于 Q3 查 table 的 fieldCount\n    //   appIdMap         → 计算 distinct appId 数\n    //   publishedRecordTotal → 累计 recordCount\n    var catalogIds     = [];\n    var targetTableIds = [];\n    var appIdMap       = {};\n    var publishedRecordTotal = 0;\n\n    for (doc in publishedHits) {\n        var src = doc._source;\n        catalogIds.add(doc._id);\n        if (src.targetTableId) { targetTableIds.add(src.targetTableId); }\n        if (src.appId)         { appIdMap[src.appId] = true; }\n    }\n\n    // distinct appId 计数\n    var publishedAppCnt = 0;\n    for (k in appIdMap.keySet()) { publishedAppCnt = publishedAppCnt + 1; }\n\n    // ================================================================\n    // Q3: 已发布目录挂接表的字段总数\n    //     table._id in targetTableIds → sum(fieldCount)\n    // ================================================================\n    var publishedFieldTotal = 0;\n    if (targetTableIds.size() > 0) {\n        var tableDsl = {\n            "size": 0,\n            "query": {\n                "bool": {\n                    "filter": [\n                        { "term": { "assetType": "table" } },\n                        { "terms": { "_id": targetTableIds } }\n                    ]\n                }\n            },\n            "aggs": {\n                "total_fields": { "sum": { "script": { "source": sumFieldScript, "lang": "painless" } } },\n                "total_rows": { "sum": { "script": { "source": sumRecordScript, "lang": "painless" } } },\n            }\n        };\n        var tableResult = esIndex.search(tableDsl);\n        publishedFieldTotal = tableResult.aggregations.total_fields.value;\n        publishedRecordTotal = tableResult.aggregations.total_rows.value;\n    }\n\n    // ================================================================\n    // Q4: 已发布目录关联的 API 总数\n    //     api.catalogId in catalogIds\n    // ================================================================\n    var publishedApiCnt = 0;\n    if (catalogIds.size() > 0) {\n        var apiDsl = {\n            "size": 0,\n            "query": {\n                "bool": {\n                    "filter": [\n                        { "term": { "assetType": "api" } },\n                        { "terms": { "catalogId": catalogIds } }\n                    ]\n                }\n            }\n        };\n        var apiResult = esIndex.search(apiDsl);\n        publishedApiCnt = apiResult.hits.total.value;\n    }\n\n    // ================================================================\n    // 组装返回\n    // ================================================================\n    return {\n        shareLayerLeft:   [ convergeAppCnt,       convergeCatalogCnt,  convergeRecordSum      ],\n        shareLayerMiddle: [ 8,                    publishedAppCnt,     publishedFieldTotal     ],\n        shareLayerRight:  [ publishedApiCnt,      publishedTotal,      publishedRecordTotal    ]\n    };\n\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'大屏接口查询失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/03.数据开放层.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4fabfd48722c4b1a8d1aeb88acce5289',NULL,NULL,'{\n  "properties": {},\n  "id": "4fabfd48722c4b1a8d1aeb88acce5289",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "04.数据整合层",\n  "createTime": 1782955343581,\n  "updateTime": 1784437771690,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/data-zh",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"layerId\\": \\"dwm\\",\\n        \\"fileData\\": \\"1\\",\\n        \\"layerName\\": \\"整合层 DWM\\",\\n        \\"list\\": [\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"渔船渔港主题库目录数\\",\\n                \\"value\\": \\"1\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"渔船渔港主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"防灾减灾主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"防灾减灾主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋经济主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋经济主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋执法主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋执法主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"渔业养殖主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"渔业养殖主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋安全主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋安全主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋资源主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋资源主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋环境主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋环境主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋科创主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋科创主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"个\\",\\n                \\"name\\": \\"海洋地理主题库目录数\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            },\\n            {\\n                \\"unit\\": \\"条\\",\\n                \\"name\\": \\"海洋地理主题库数据量\\",\\n                \\"value\\": \\"0\\",\\n                \\"status\\": \\"\\"\\n            }\\n        ],\\n        \\"tid\\": \\"2b550e9f09e243cd94b1ce981f960559\\"\\n    }\\n}",\n  "description": "返回脚本内预设的整合层主题库展示内容；当前不从租户库实时计算。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.数据整合层\n// 路由：GET /scene/data-count/data-zh\n// 业务说明：返回脚本内预设的整合层主题库展示内容；当前不从租户库实时计算。\n// 返回当前业务分支的标准结果。\nreturn {\n    "bigdata_platform_list": [\n          {\n            "layerId": "1d51245d5d6b41c08cbdfcf3b286d533",\n            "fileData": "/assets/scense/bigdata1.png",\n            "icon": "0b22abd726834b81b55119ad71f19bc2",\n            "layerName": "渔船渔港 主题库",\n            "list": [\n              {\n                "unit": "个",\n                "name": "渔船总数",\n                "value": "3000",\n                "status": true\n              },\n              {\n                "unit": "个",\n                "name": "渔港总数",\n                "value": "87",\n                "status": true\n              }\n            ],\n            "tid": "a80c8fd8972840e38850699e7a5ec19a"\n          },\n          {\n            "layerId": "4327e401b68143a28edf9530d9d977ed",\n            "fileData": "/assets/scense/bigdata2.png",\n            "icon": "41056cbd13074e03b58343e73a6d0177",\n            "layerName": "渔业机构 主题库",\n            "list": [\n              {\n                "unit": "个",\n                "name": "养殖区数",\n                "value": "1500",\n                "status": true\n              },\n              {\n                "unit": "个",\n                "name": "水产市场",\n                "value": "80",\n                "status": true\n              }\n            ],\n            "tid": "6c10ff68702747359f3bce772900afd1"\n          },\n          {\n            "layerId": "116bf4ea10aa46a6898b78bec1c6b21b",\n            "fileData": "/assets/scense/bigdata3.png",\n            "icon": "185c4a81c5414894a446f4dbedeebbe7",\n            "layerName": "海洋经济 主题库",\n            "list": [\n              {\n                "unit": "家",\n                "name": "龙头企业",\n                "value": "396",\n                "url": "",\n                "status": true\n              },\n              {\n                "unit": "亿",\n                "name": "总产值",\n                "value": "19,786.3",\n                "status": true\n              }\n            ],\n            "tid": "2385a87748ba475a97f25bff6886d64e"\n          },\n          {\n            "layerId": "187bb4c7cdbf489d8fff6cc479bb3e5d",\n            "fileData": "/assets/scense/bigdata4.png",\n            "icon": "cd9fe84b48a1432f847e81b8443b2ba5",\n            "layerName": "水产养殖 主题库",\n            "list": [\n              {\n                "unit": "个",\n                "name": "养殖区数",\n                "value": "1500",\n                "status": true\n              },\n              {\n                "unit": "个",\n                "name": "水产市场",\n                "value": "80",\n                "status": true\n              }\n            ],\n            "tid": "1720b20a0b1c470d8d4338cd8d69e3fe"\n          },\n          {\n            "layerId": "61f1891ffcb2453ab572f5055f0daaa0b",\n            "fileData": "/assets/scense/bigdata5.png",\n            "icon": "d652e5cd3903449bba6b7e9ecdc27f10",\n            "layerName": "渔业资源 主题库",\n            "list": [\n              {\n                "unit": "条",\n                "name": "物种总数",\n                "value": "20",\n                "status": true\n              },\n              {\n                "unit": "条",\n                "name": "矿区数量",\n                "value": "28",\n                "status": true\n              }\n            ],\n            "tid": "bac40c7610b24f73b56c8e2999a0f317"\n          },\n          {\n            "layerId": "d27be954a63b4f3bb92c0b8d5919a69c",\n            "fileData": "/assets/scense/bigdata6.png",\n            "icon": "881d6b0b17c449aaa5014804fd9447e1",\n            "layerName": "海洋环境 主题库",\n            "list": [\n              {\n                "unit": "个",\n                "name": "生态保护区",\n                "value": "12",\n                "status": true\n              },\n              {\n                "unit": "万公里",\n                "name": "保护区面积",\n                "value": "34.34",\n                "status": true\n              }\n            ],\n            "tid": "ea8483aa157545a4bc1025d8bad6c344"\n          }\n        ],\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/04.数据整合层.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3e5a46b0a5de4ad9be6be4bc1eadbb91',NULL,NULL,'{\n  "properties": {},\n  "id": "3e5a46b0a5de4ad9be6be4bc1eadbb91",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "05.数据汇聚共享统计",\n  "createTime": 1782955343594,\n  "updateTime": 1784437771703,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/converge",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"cityAppHjCount\\": 5,\\n        \\"cityDbHjCount\\": 86,\\n        \\"cityCategoryHjCount\\": 198,\\n        \\"countyDbHjCount\\": 1,\\n        \\"countyAppHjCount\\": 0,\\n        \\"countyCategoryHjCount\\": 4\\n    }\\n}",\n  "description": "说明: 统计数据汇聚和共享情况，包括业务系统、数据目录、数据资源三个维度。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "cityAppHjCount",\n            "value": "2",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "cityDbHjCount",\n            "value": "83",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "cityCategoryHjCount",\n            "value": "5645",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "countyDbHjCount",\n            "value": "0",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "countyAppHjCount",\n            "value": "0",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "countyCategoryHjCount",\n            "value": "0",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：05.数据汇聚共享统计\n// 路由：GET /scene/data-count/converge\n// 业务说明：说明: 统计数据汇聚和共享情况，包括业务系统、数据目录、数据资源三个维度。\n// 数据汇聚共享情况接口\n// 路径: /dataassets/scence/aggregationShare/stat\n// 方法: get\n// 参数: 无\n// 说明: 统计数据汇聚和共享情况，包括业务系统、数据目录、数据资源三个维度\n//       数据汇聚(city前缀)：从dataassets索引统计资产挂载情况\n//       数据共享(county前缀)：从apply索引统计已通过申请单，\n//          countyDbHjCount=申请单中通过的目录数(去重catalogId)、\n//          countyAppHjCount=通过的目录中有挂载appId的数量、\n//          countyCategoryHjCount=目录下挂载的table+api+file资源总数\n\nimport tenantEs;\nimport \'@/common/configData\' as configData;\n\ntry {\n\n    // ============================================================\n    // Part 1: 数据汇聚统计 (city前缀)\n    // 从 sea_fishery_elements_dataassets 索引查询\n    // ============================================================\n\n    var hjDsl = {\n        "size": 0,\n        "aggs": {\n            // 有挂载表的业务系统：通过table的orgId聚合得到去重后的app数量\n            // table.orgId 对应所属app的id，每个唯一的orgId代表一个"有挂载表的业务系统"\n            "table_apps": {\n                "filter": { "term": { "assetType": "table" } },\n                "aggs": {\n                    "unique_apps": {\n                        "terms": { "field": "orgId", "size": 100000 }\n                    }\n                }\n            },\n            // 有挂载表的目录数：catalog有targetTableId的数量\n            "catalog_with_target": {\n                "filter": {\n                    "bool": {\n                        "filter": [\n                            { "term": { "assetType": "catalog" } },\n                            { "exists": { "field": "targetTableId" } }\n                        ]\n                    }\n                }\n            },\n            // 数据资源总数：table + api + file 三种类型文档数\n            "api_with_catalog": {\n                "filter": {\n                    "bool": {\n                        "filter": [\n                            { "term": { "assetType": "api" } },\n                            { "exists": { "field": "catalogId" } }\n                        ]\n                    }\n                }\n            },\n            "file_with_catalog": {\n                "filter": {\n                    "bool": {\n                        "filter": [\n                            { "term": { "assetType": "file" } },\n                            { "exists": { "field": "catalogId" } }\n                        ]\n                    }\n                }\n            },\n            "table_with_catalog": {\n                "filter": {\n                    "bool": {\n                        "filter": [\n                            { "term": { "assetType": "table" } },\n                            { "exists": { "field": "catalogId" } }\n                        ]\n                    }\n                }\n            }\n        }\n    };\n\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var hjResult = tenantEs.index(configData().es_dataassets).search(hjDsl);\n\n    var cityAppHjCount     = hjResult.aggregations.table_apps.unique_apps.buckets.size();\n    var cityDbHjCount      = hjResult.aggregations.catalog_with_target.doc_count;\n    var apiHjCount     = hjResult.aggregations.api_with_catalog.doc_count;\n    var fileHjCount    = hjResult.aggregations.file_with_catalog.doc_count;\n    var tableHjCount = hjResult.aggregations.table_with_catalog.doc_count;\n    var cityCategoryHjCount = apiHjCount + fileHjCount + tableHjCount;\n\n    // ============================================================\n    // Part 2: 数据共享统计 (county前缀)\n    // 从 sea_fishery_elements_dataassets_apply 索引查询已通过的申请单\n    // ============================================================\n\n    // 2.1 查询已通过的申请单（flowStatus=2），收集去重后的catalogId\n    var applyDsl = {\n        "size": 10000,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "flowStatus": 2 } }\n                ]\n            }\n        },\n        "_source": ["catalogIds"]\n    };\n\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var applyResult = tenantEs.index(configData().es_dataassets_apply).search(applyDsl);\n\n    // 收集所有唯一的catalogId\n    var allCatalogIds = {};\n\n    for (hit in applyResult.hits.hits) {\n        var src = hit._source;\n        var catalogIds = src.catalogIds;\n        if (catalogIds) {\n            var idList = catalogIds.split(\',\');\n            for (cid in idList) {\n                var trimmedId = cid.trim();\n                if (trimmedId) {\n                    allCatalogIds[trimmedId] = true;\n                }\n            }\n        }\n    }\n\n    // countyDbHjCount: 申请单中通过的目录数 = 去重后的catalogId数量\n    var countyDbHjCount = allCatalogIds.keySet().size();\n\n    // 2.2 分批查询共享目录，统计：\n    //   countyAppHjCount = 通过的目录中有挂载appId的数量\n    //   countyCategoryHjCount = 目录下挂载的table+api+file资源总数\n    var countyAppHjCount = 0;\n    var countyCategoryHjCount = 0;\n\n    if (countyDbHjCount > 0) {\n        var catalogIdList = [];\n        for (cid in allCatalogIds.keySet()) {\n            catalogIdList.push(cid);\n        }\n\n        var batchSize = 500;\n        var batchIndex = 0;\n        var totalBatches = (catalogIdList.size() + batchSize - 1) / batchSize;\n\n        while (batchIndex < totalBatches) {\n            var start = batchIndex * batchSize;\n            var end = start + batchSize;\n            if (end > catalogIdList.size()) { end = catalogIdList.size(); }\n            var batchIds = catalogIdList.subList(start, end);\n\n            // 查询有挂载appId的目录数\n            var catalogDsl = {\n                "size": 0,\n                "query": {\n                    "bool": {\n                        "filter": [\n                            { "term": { "assetType": "catalog" } },\n                            { "terms": { "id": batchIds } },\n                            { "exists": { "field": "appId" } }\n                        ]\n                    }\n                }\n            };\n\n            // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n            var catResult = tenantEs.index(configData().es_dataassets).search(catalogDsl);\n            if (catResult.hits && catResult.hits.total) {\n                var catTotal = catResult.hits.total.value != null ? catResult.hits.total.value : catResult.hits.total;\n                countyAppHjCount = countyAppHjCount + catTotal;\n            }\n\n            // 查询目录下挂载的table+api+file资源总数\n            var resourceDsl = {\n                "size": 0,\n                "query": {\n                    "bool": {\n                        "filter": [\n                            { "terms": { "assetType": ["table", "api", "file"] } },\n                            { "terms": { "catalogId": batchIds } }\n                        ]\n                    }\n                }\n            };\n\n            // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n            var resResult = tenantEs.index(configData().es_dataassets).search(resourceDsl);\n            if (resResult.hits && resResult.hits.total) {\n                var resTotal = resResult.hits.total.value != null ? resResult.hits.total.value : resResult.hits.total;\n                countyCategoryHjCount = countyCategoryHjCount + resTotal;\n            }\n\n            batchIndex = batchIndex + 1;\n        }\n    }\n\n    // ============================================================\n    // 返回结果\n    // ============================================================\n    return {\n        cityAppHjCount: cityAppHjCount,\n        cityDbHjCount: cityDbHjCount,\n        cityCategoryHjCount: cityCategoryHjCount,\n        countyDbHjCount: countyDbHjCount,\n        countyAppHjCount: countyAppHjCount,\n        countyCategoryHjCount: countyCategoryHjCount\n    };\n\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'查询数据汇聚共享情况失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/05.数据汇聚共享统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3cd606bbc1a247c19577f17f898ef3ad',NULL,NULL,'{\n  "properties": {},\n  "id": "3cd606bbc1a247c19577f17f898ef3ad",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "06.数源层",\n  "createTime": 1782955343606,\n  "updateTime": 1784437771706,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/data-dst",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"collectLayerLeft\\": [\\n            4,\\n            153,\\n            517\\n        ],\\n        \\"collectLayerMiddle\\": [\\n            12,\\n            5466,\\n            12402088\\n        ],\\n        \\"collectLayerRight\\": [\\n            30,\\n            13,\\n            31\\n        ]\\n    }\\n}",\n  "description": "按局内、局外和国家部委来源汇总机构、数据表及记录数，返回数源层大屏指标。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.数源层\n// 路由：GET /scene/data-count/data-dst\n// 业务说明：按局内、局外和国家部委来源汇总机构、数据表及记录数，返回数源层大屏指标。\n// dst层统计接口\n// 路径: /api/dataassets/dstLayer\n// 方法: POST\n// 参数: 无\n// 返回: { collectLayerLeft: [国家部委数量, 国家部委数据表数量, 国家部委数据总量], collectLayerMiddle: [局内单位数量, 局内数据表数量, 局内数据总数量], collectLayerRight: [横向厅局单位数量, 横向厅局数据表数量, 横向厅局数据总数量] }\n\nimport tenantEs;\nimport \'@/common/configData\' as configData;\n\ntry {\n    // ========== 配置 ==========\n    // 国家部委根ID（左侧）\n    var leftRootOrgId = \'2067073520506609664\';\n    // 局内共享部门根ID（中间）\n    var middleRootOrgIds = [\'2057658733680787457\', \'2058490433772060673\'];\n    // 横向厅局根ID（右侧）\n    var rightRootOrgId = \'2067073568296509440\';\n\n    // keyword字段求和脚本\n    var sumRecordScript = "if (doc[\'recordCount\'].size() == 0) { return 0; } def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;";\n\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var esIndex = tenantEs.index(configData().es_dataassets);\n\n    // ========== 查询业务库的dbId列表（table通过dbId关联） ==========\n    var dbDsl = {\n        "size": 1000,\n        "query": {\n            "bool": {\n                "must": [\n                    { "term": { "assetType": "db" } },\n                    { "term": { "assetStatus": 2 } },\n                    { "term": { "nodeId": "业务库" } }\n                ]\n            }\n        },\n        "_source": false\n    };\n    var dbResult = esIndex.search(dbDsl);\n    var businessDbIds = [];\n    dbResult.hits.hits.forEach((hit) => {\n        businessDbIds.add(hit._id);\n    });\n\n    // ========== 递归获取所有子机构ID ==========\n    var getAllChildOrgIds = (rootId) => {\n        var result = [];\n        result.add(rootId);\n        \n        // 从 MySQL 业务表读取当前有效数据。\n        var children = db.table("rm_org_t")\n            .where().eq("parent_id", rootId).eq("nature", 2).eq("deleted", 0)\n            .select();\n        \n        for (child in children) {\n            var subChildIds = getAllChildOrgIds(child.id);\n            for (subId in subChildIds) {\n                result.add(subId);\n            }\n        }\n        \n        // 返回当前业务分支的标准结果。\n        return result;\n    };\n\n    // ========== 1. collectLayerLeft: 国家部委(左) ==========\n    // 1.1 获取所有子机构ID\n    var leftOrgIds = getAllChildOrgIds(leftRootOrgId);\n    // 国家部委数量 = 子机构数量（排除根ID本身）\n    var leftOrgCount = leftOrgIds.size().asInt() - 1;\n\n    // 1.2 国家部委数据表数量: ES中orgId在leftOrgIds中, assetType=table, dbId在业务库中的数量\n    var leftTableDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": leftOrgIds } }\n                ]\n            }\n        }\n    };\n    var leftTableResult = esIndex.search(leftTableDsl);\n    var leftTableCount = leftTableResult.hits.total.value;\n\n    // 1.3 国家部委数据总量: ES中orgId在leftOrgIds中, assetType=table, dbId在业务库中的recordCount总和\n    var leftRecordDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": leftOrgIds } }\n                ]\n            }\n        },\n        "aggs": {\n            "total_records": { "sum": { "script": { "source": sumRecordScript, "lang": "painless" } } }\n        }\n    };\n    var leftRecordResult = esIndex.search(leftRecordDsl);\n    var leftRecordTotal = leftRecordResult.aggregations.total_records.value;\n\n    // ========== 2. collectLayerMiddle: 局内单位(中) ==========\n    // 2.1 获取所有子机构ID\n    var middleOrgIds = [];\n    for (rootId in middleRootOrgIds) {\n        var childIds = getAllChildOrgIds(rootId);\n        for (id in childIds) {\n            middleOrgIds.add(id);\n        }\n    }\n    // 局内单位数量 = 子机构数量（排除根ID本身）\n    var middleOrgCount = middleOrgIds.size().asInt() - middleRootOrgIds.size().asInt();\n\n    // 2.2 局内数据表数量: ES中orgId在middleOrgIds中, assetType=table, dbId在业务库中的数量\n    var middleTableDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": middleOrgIds } }\n                ]\n            }\n        }\n    };\n    var middleTableResult = esIndex.search(middleTableDsl);\n    var middleTableCount = middleTableResult.hits.total.value;\n\n    // 2.3 局内数据总数量: ES中orgId在middleOrgIds中, assetType=table, dbId在业务库中的recordCount总和\n    var middleRecordDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": middleOrgIds } }\n                ]\n            }\n        },\n        "aggs": {\n            "total_records": { "sum": { "script": { "source": sumRecordScript, "lang": "painless" } } }\n        }\n    };\n    var middleRecordResult = esIndex.search(middleRecordDsl);\n    var middleRecordTotal = middleRecordResult.aggregations.total_records.value;\n\n    // ========== 3. collectLayerRight: 横向厅局(右) ==========\n    // 3.1 获取所有子机构ID\n    var rightOrgIds = getAllChildOrgIds(rightRootOrgId);\n    // 横向厅局单位数量 = 子机构数量（排除根ID本身）\n    var rightOrgCount = rightOrgIds.size().asInt() - 1;\n\n    // 3.2 横向厅局数据表数量: ES中orgId在rightOrgIds中, assetType=table, dbId在业务库中的数量\n    var rightTableDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": rightOrgIds } }\n                ]\n            }\n        }\n    };\n    var rightTableResult = esIndex.search(rightTableDsl);\n    var rightTableCount = rightTableResult.hits.total.value;\n\n    // 3.3 横向厅局数据总数量: ES中orgId在rightOrgIds中, assetType=table, dbId在业务库中的recordCount总和\n    var rightRecordDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "terms": { "orgId": rightOrgIds } }\n                ]\n            }\n        },\n        "aggs": {\n            "total_records": { "sum": { "script": { "source": sumRecordScript, "lang": "painless" } } }\n        }\n    };\n    var rightRecordResult = esIndex.search(rightRecordDsl);\n    var rightRecordTotal = rightRecordResult.aggregations.total_records.value;\n\n    // ========== 返回结果 ==========\n    return {\n        // [国家部委数量, 国家部委数据表数量, 国家部委数据总量]\n        collectLayerLeft: [leftOrgCount, leftTableCount, leftRecordTotal],\n        // [局内单位数量, 局内数据表数量, 局内数据总数量]\n        collectLayerMiddle: [middleOrgCount, middleTableCount, middleRecordTotal],\n        // [横向厅局单位数量, 横向厅局数据表数量, 横向厅局数据总数量]\n        collectLayerRight: [rightOrgCount, rightTableCount, rightRecordTotal]\n    };\n\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'查询数据汇聚层统计失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/06.数源层.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4770f23e7671404ebe0b31f429336c84',NULL,NULL,'{\n  "properties": {},\n  "id": "4770f23e7671404ebe0b31f429336c84",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "07.近期业务数据量增长趋势",\n  "createTime": 1782955343616,\n  "updateTime": 1784437771708,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/recent",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"recent_week_hj\\": [\\n            {\\n                \\"timeValue\\": \\"04月13日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"04月20日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"04月27日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"05月04日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"05月11日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"05月18日\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"05月25日\\",\\n                \\"countNum\\": 97068\\n            },\\n            {\\n                \\"timeValue\\": \\"06月01日\\",\\n                \\"countNum\\": 6257422\\n            },\\n            {\\n                \\"timeValue\\": \\"06月08日\\",\\n                \\"countNum\\": 295619\\n            },\\n            {\\n                \\"timeValue\\": \\"06月15日\\",\\n                \\"countNum\\": 6254\\n            },\\n            {\\n                \\"timeValue\\": \\"06月22日\\",\\n                \\"countNum\\": 1414\\n            },\\n            {\\n                \\"timeValue\\": \\"06月29日\\",\\n                \\"countNum\\": 6273128\\n            }\\n        ],\\n        \\"recent_month_hj\\": [\\n            {\\n                \\"timeValue\\": \\"2025-09\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2025-10\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2025-11\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2025-12\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-01\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-02\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-03\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-04\\",\\n                \\"countNum\\": 0\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-05\\",\\n                \\"countNum\\": 97068\\n            },\\n            {\\n                \\"timeValue\\": \\"2026-06\\",\\n                \\"countNum\\": 12833837\\n            }\\n        ]\\n    }\\n}",\n  "description": "说明: 查询业务库下的表，按周/月统计recordCount总和（业务数据量增长趋势）。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.近期业务数据量增长趋势\n// 路由：GET /scene/data-count/recent\n// 业务说明：说明: 查询业务库下的表，按周/月统计recordCount总和（业务数据量增长趋势）。\n// 近期业务数据量增长趋势接口\n// 路径: /api/dataassets/recentBusiness\n// 方法: POST\n// 参数: 无\n// 说明: 查询业务库下的表，按周/月统计recordCount总和（业务数据量增长趋势）\n\nimport tenantEs;\nimport \'@/common/configData\' as configData\n\ntry {\n    // keyword字段求和脚本（recordCount是keyword类型，需转数值）\n    var sumScript = "if (doc[\'recordCount\'].size() > 0) { try { return Double.parseDouble(doc[\'recordCount\'].value); } catch(Exception e) {} } return 0;";\n\n    // ========== 查询业务库的dbId列表（table通过dbId关联） ==========\n    var dbDsl = {\n        "size": 1000,\n        "query": {\n            "bool": {\n                "must": [\n                    { "term": { "assetType": "db" } },\n                    { "term": { "assetStatus": 2 } },\n                    { "term": { "nodeId": "业务库" } }\n                ]\n            }\n        },\n        "_source": false\n    };\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var dbResult = tenantEs.index(configData().es_dataassets).search(dbDsl);\n    var businessDbIds = [];\n    dbResult.hits.hits.forEach((hit) => {\n        businessDbIds.push(hit._id);\n    });\n\n    if (businessDbIds.size().asInt() == 0) {\n        // 返回当前业务分支的标准结果。\n        return {\n            recent_week_hj: [],\n            recent_month_hj: []\n        };\n    }\n\n    // ========== 对table按regTime_date做周+月聚合（无时间范围过滤） ==========\n    var dsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "dbId": businessDbIds } },\n                    { "exists": { "field": "recordCount" } }\n                ]\n            }\n        },\n        "aggs": {\n            "recent_week_hj": {\n                "date_histogram": {\n                    "field": "regTime_date",\n                    "calendar_interval": "week",\n                    "format": "MM月dd日",\n                    "min_doc_count": 0,\n                    "extended_bounds": {\n                        "min": "now-11w/w",\n                        "max": "now"\n                    }\n                },\n                "aggs": {\n                    "total_row_count": {\n                        "sum": { "script": { "source": sumScript } }\n                    }\n                }\n            },\n            "recent_month_hj": {\n                "date_histogram": {\n                    "field": "regTime_date",\n                    "calendar_interval": "month",\n                    "format": "yyyy-MM",\n                    "min_doc_count": 0,\n                    "extended_bounds": {\n                        "min": "now-9M/M",\n                        "max": "now"\n                    }\n                },\n                "aggs": {\n                    "total_row_count": {\n                        "sum": { "script": { "source": sumScript } }\n                    }\n                }\n            }\n        }\n    };\n\n    // 执行ES查询\n    var result = tenantEs.index(configData().es_dataassets).search(dsl);\n\n    // 格式化周统计结果\n    var recentWeekHj = [];\n    var weekBuckets = result.aggregations.recent_week_hj.buckets;\n    for (bucket in weekBuckets) {\n        recentWeekHj.push({\n            timeValue: bucket.key_as_string,\n            countNum: bucket.total_row_count.value\n        });\n    }\n\n    // 格式化月统计结果\n    var recentMonthHj = [];\n    var monthBuckets = result.aggregations.recent_month_hj.buckets;\n    for (bucket in monthBuckets) {\n        recentMonthHj.push({\n            timeValue: bucket.key_as_string,\n            countNum: bucket.total_row_count.value\n        });\n    }\n\n    // 返回当前业务分支的标准结果。\n    return {\n        recent_week_hj: recentWeekHj,\n        recent_month_hj: recentMonthHj\n    };\n\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'查询近期业务数据量增长趋势失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/07.近期业务数据量增长趋势.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9ca047fe684845d59009d947fa3d0fe6',NULL,NULL,'{\n  "properties": {},\n  "id": "9ca047fe684845d59009d947fa3d0fe6",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "08.顶部数据统计",\n  "createTime": 1782955343625,\n  "updateTime": 1784437771711,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/stats",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": {\\n        \\"dataTotal\\": 6653042,\\n        \\"dataTodayTotal\\": 0,\\n        \\"dataConverge\\": 109647,\\n        \\"dataShare\\": 836\\n    }\\n}",\n  "description": "汇总业务库、登记表、今日新增、数据汇聚及共享申请等指标，返回资产全景顶部统计。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "dataTotal",\n            "value": "6886306",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "dataTodayTotal",\n            "value": "0",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：08.顶部数据统计\n// 路由：GET /scene/data-count/stats\n// 业务说明：汇总业务库、登记表、今日新增、数据汇聚及共享申请等指标，返回资产全景顶部统计。\n// 数据统计概览接口\n// 路径: /api/dataassets/stats\n// 业务库: 已注册assetStatus=2 nodeId=业务库 的db\n// 数据总量 = 业务库下 table 的 recordCount 总和\n// 今日新增 = 业务库下 注册时间regTime 为今日的 table 的 recordCount 总和\n// 数据汇聚 = 有 targetTableId 的 catalog 挂接表的 recordCount 总和\n// 数据共享 = 已审核的目录订阅申请单中订阅的 catalog 挂接表的 recordCount 总和\nimport tenantEs;\nimport \'@/common/configData\' as configData\nimport cn.hutool.core.util.StrUtil\n\n// ========== 查询业务库的dbId列表（table通过dbId关联） ==========\nvar dbDsl = {\n    "size": 5000,\n    "query": {\n        "bool": {\n            "must": [\n                { "term": { "assetType": "db" } },\n                { "term": { "assetStatus": 2 } },\n                { "term": { "nodeId": "业务库" } }\n            ]\n        }\n    },\n    "_source": false\n};\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar dbResult = tenantEs.index(configData().es_dataassets).search(dbDsl);\nvar businessDbIds = [];\ndbResult.hits.hits.forEach((hit) => {\n    businessDbIds.push(hit._id);\n});\n\nvar dsl = {\n  "size": 0,\n  "query": {\n    "bool": {\n      "must": [\n        {\n          "term": {\n            "assetType": "table"\n          }\n        },\n        {\n          "exists": {\n            "field": "recordCount"\n          }\n        }\n      ],\n      "filter": [\n        { "terms": { "dbId": businessDbIds } }\n      ]\n    }\n  },\n  "aggs": {\n    "total_row_count": {\n      "sum": {\n        "script": {\n          "source": "def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;"\n        }\n      }\n    }\n  }\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar dataTotal = tenantEs.index(configData().es_dataassets).search(dsl)?.aggregations?.total_row_count?.value;\nif (!dataTotal) { dataTotal = 0; }\n\nimport cn.hutool.core.date.DateUtil\nvar today = DateUtil.format(new Date(), "yyyy-MM-dd")\n\ndsl = {\n  "size": 0,\n  "query": {\n    "bool": {\n      "must": [\n        {\n          "term": {\n            "assetType": "table"\n          }\n        },\n        {\n          "range": {\n            "regTime_date": {\n              "gte": "now/d",\n              "lte": "now"\n            }\n          }\n        }\n      ],\n      "filter": [\n        { "terms": { "dbId": businessDbIds } }\n      ]\n    }\n  },\n  "aggs": {\n    "total_row_count": {\n      "sum": {\n        "script": {\n          "source": "if (doc[\'recordCount\'].size() == 0) { return 0; } def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;"\n        }\n      }\n    }\n  }\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar dataTodayTotal = tenantEs.index(configData().es_dataassets).search(dsl)?.aggregations?.total_row_count?.value;\nif (!dataTodayTotal) { dataTodayTotal = 0; }\n\n// ========== 数据汇聚 = 所有 catalog 挂接表的 recordCount 总和 ==========\n// 1. 查有 targetTableId 的 catalog，收集 tableId\nvar catalogDsl = {\n    "size": 9000,\n    "query": {\n        "bool": {\n            "filter": [\n                { "term": { "assetType": "catalog" } },\n                // { "term": { "assetStatus": 2 } },\n                { "exists": { "field": "targetTableId" } }\n            ]\n        }\n    },\n    "_source": ["targetTableId"]\n}\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar catalogResult = tenantEs.index(configData().es_dataassets).search(catalogDsl);\nvar convergeTableIds = [];\nfor (hit in catalogResult.hits.hits) {\n    var src = hit._source;\n    if (src.targetTableId) {\n        convergeTableIds.push(src.targetTableId);\n    }\n}\n\n// 2. 查这些表的 recordCount 总和\nvar dataConverge = 0;\nif (convergeTableIds.size().asInt() > 0) {\n    var convergeDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "_id": convergeTableIds } }\n                ]\n            }\n        },\n        "aggs": {\n            "total_row_count": {\n                "sum": {\n                    "script": {\n                        "source": "if (doc[\'recordCount\'].size() == 0) { return 0; } def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;"\n                    }\n                }\n            }\n        }\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    dataConverge = tenantEs.index(configData().es_dataassets).search(convergeDsl)?.aggregations?.total_row_count?.value;\n    if (!dataConverge) { dataConverge = 0; }\n}\n\n// ========== 数据共享 = 目录订阅申请单中订阅的目录挂接表的 recordCount 总和 ==========\n// 1. 查已审核的目录订阅申请单，收集 catalogIds\nvar applyDsl = {\n    "size": 9000,\n    "query": {\n        "bool": {\n            "filter": [\n                // { "term": { "assetType": "apply" } },\n                { "term": { "flowStatus": 2 } },\n                { "term": { "type": "catalogSubscribe" } }\n            ]\n        }\n    },\n    "_source": ["catalogIds"]\n}\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar applyResult = tenantEs.index(configData().es_dataassets_apply).search(applyDsl);\n// return applyResult\nvar sharedCatalogIds = [];\nfor (hit in applyResult.hits.hits) {\n    var src = hit._source;\n    if (src.catalogIds) {\n        for (cid in StrUtil.split(src.catalogIds, \',\')) {\n            sharedCatalogIds.push(cid);\n        }\n    }\n}\n\n// 2. 查这些 catalog 的 targetTableId\nvar sharedTableIds = [];\nif (sharedCatalogIds.size().asInt() > 0) {\n    var sharedCatalogDsl = {\n        "size": 1000,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "terms": { "_id": sharedCatalogIds } }\n                ]\n            }\n        },\n        "_source": ["targetTableId"]\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var sharedCatalogResult = tenantEs.index(configData().es_dataassets).search(sharedCatalogDsl);\n    for (hit in sharedCatalogResult.hits.hits) {\n        var src = hit._source;\n        if (src.targetTableId) {\n            sharedTableIds.push(src.targetTableId);\n        }\n    }\n}\n\n// 3. 查这些表的 recordCount 总和\nvar dataShare = 0;\nif (sharedTableIds.size().asInt() > 0) {\n    var shareDsl = {\n        "size": 0,\n        "query": {\n            "bool": {\n                "filter": [\n                    { "term": { "assetType": "table" } },\n                    { "terms": { "_id": sharedTableIds } }\n                ]\n            }\n        },\n        "aggs": {\n            "total_row_count": {\n                "sum": {\n                    "script": {\n                        "source": "if (doc[\'recordCount\'].size() == 0) { return 0; } def v = doc[\'recordCount\'].value; if (v != null && v != \'\') { return Double.parseDouble(v); } return 0;"\n                    }\n                }\n            }\n        }\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    dataShare = tenantEs.index(configData().es_dataassets).search(shareDsl)?.aggregations?.total_row_count?.value;\n    if (!dataShare) { dataShare = 0; }\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    dataTotal,\n    dataTodayTotal,\n    dataConverge,\n    dataShare\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/08.顶部数据统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a1b2c3d4e5f678901234567890abcdef',NULL,NULL,'{\n  "properties": {},\n  "id": "a1b2c3d4e5f678901234567890abcdef",\n  "script": null,\n  "groupId": "df01177ff7604bbfb813175969adba1b",\n  "name": "09.各部门DST表数量统计",\n  "createTime": 1784523373047,\n  "updateTime": 1787153758127,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dstTableByOrg",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "DST 表：db_table_t.business_type = \\"业务表\\"；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.各部门DST表数量统计\n// 路由：GET /scene/data-count/dstTableByOrg\n// 业务说明：DST 表：db_table_t.business_type = "业务表"；读取或计算后返回业务结果。\n/*\n * 各部门 DST 表数量统计\n *\n * DST 表：db_table_t.business_type = "业务表"\n * 部门：取所属库 db_datasource_t.org_id\n * 返回 orgId + tableCount，前端用组织树匹配部门名称\n */\n\nvar sql = "SELECT d.org_id AS orgId, COUNT(*) AS tableCount " +\n    "FROM db_table_t t " +\n    "JOIN db_datasource_t d ON t.datasource_id = d.tid " +\n    "WHERE t.is_del = 0 AND d.is_del = 0 AND t.business_type = \\"业务表\\" " +\n    "GROUP BY d.org_id " +\n    "ORDER BY tableCount DESC"\n\nvar result = db.select(sql).query()\n\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/09.各部门DST表数量统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('df01177ff7604bbfb813175969adba1b',NULL,NULL,'{\n  "properties" : { },\n  "id" : "df01177ff7604bbfb813175969adba1b",\n  "name" : "04.数据统计",\n  "type" : "api",\n  "parentId" : "5ac60a54d85b4682ab46fbb8def36ea2",\n  "path" : "/data-count",\n  "createTime" : null,\n  "updateTime" : 1784526662075,\n  "createBy" : null,\n  "updateBy" : null,\n  "paths" : [ ],\n  "options" : [ ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/api/08.数据全景/04.数据统计/group.json');
