aIndex\\": \\"categoryCount\\",\\n                \\"key\\": \\"categoryCount\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"汇聚目录\\",\\n                \\"dataIndex\\": \\"categoryHjCount\\",\\n                \\"key\\": \\"categoryHjCount\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"汇聚数据量\\",\\n                \\"dataIndex\\": \\"dataTotalCount\\",\\n                \\"key\\": \\"dataTotalCount\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"更新及时\\",\\n                \\"dataIndex\\": \\"gxjsCount\\",\\n                \\"key\\": \\"gxjsCount\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"更新延时\\",\\n                \\"dataIndex\\": \\"gxyhCount\\",\\n                \\"key\\": \\"gxyhCount\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"更新及时率\\",\\n                \\"dataIndex\\": \\"gxjsRateStr\\",\\n                \\"key\\": \\"gxjsRateStr\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,\\n                \\"width\\": \\"8%\\"\\n            },\\n            {\\n                \\"title\\": \\"数据更新情况\\",\\n                \\"dataIndex\\": \\"dataUpdateInfo\\",\\n                \\"key\\": \\"dataUpdateInfo\\",\\n                \\"align\\": \\"center\\",\\n                \\"ellipsis\\": true,