INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99198f1d6e154a938f9fd64542c52834',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "99198f1d6e154a938f9fd64542c52834",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "01.用户列表",\n  "createTime": 1782660716529,\n  "updateTime": 1785920400000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；读取或计算后返回业务结果。"\n}\n================================\n// 接口：01.用户列表\n// 路由：GET /sym/user/list\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；读取或计算后返回业务结果。\n\nimport \'@/tenant-account/users\' as localUsers\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport tenantRuntime\n// 用户列表：处理 GET /list 的核心查询和组装返回数据逻辑。\n\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit -1, "账号未登录或登录已过期"\n}\n\nreturn localUsers(\'list\',{userName:userName})\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/01.用户列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f75db35437b546f8a8c8e4eda6740e33',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "f75db35437b546f8a8c8e4eda6740e33",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "02.用户分页",\n  "createTime": 1782660716553,\n  "updateTime": 1787153759518,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"list\\": [],\\n  \\"total\\": 0\\n}",\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 orgId；涉及 rm_user_org_rela_t、rm_user_role_rela_t、rm_role_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.用户分页\n// 路由：POST /sym/user/page\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 orgId；涉及 rm_user_org_rela_t、rm_user_role_rela_t、rm_role_t 等业务表。\n\nimport \'@/tenant-account/users\' as localUsers\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport tenantRuntime\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit -1, "账号未登录或登录已过期"\n}\n\nvar filters = body || {}\n\n// 组织关系属于租户库，先换算成允许查询的本地用户ID。\nif (body?.orgId != null && (body.orgId + \'\').trim() != \'\') {\n    var orgUsers = db.table("rm_user_org_rela_t").where()\n        .eq("org_id", body.orgId)\n        .select()\n    filters.ids = orgUsers == null ? [] : orgUsers.map(item => item.userId)\n}\n\nvar userPage = localUsers(\'page\',filters)\nif (userPage.list == null || userPage.list.size() == 0) {\n    return userPage\n}\n\nvar userIds = userPage.list.map(item => item.id)\nvar roleRelations = db.table("rm_user_role_rela_t").where()\n    .in("user_id", userIds)\n    .select()\nvar roleNames = {}\nif (roleRelations != null && roleRelations.size() > 0) {\n    var roleIds = roleRelations.map(item => item.roleId)\n    var roles = db.table("rm_role_t").where()\n        .in("id", roleIds)\n        .eq("deleted", 0)\n        .select()\n    var namesById = {}\n    for (role in roles) {\n        namesById[role.id] = role.name\n    }\n    for (relation in roleRelations) {\n        var roleName = namesById[relation.roleId]\n        if (roleName != null && roleName != \'\') {\n            roleNames[relation.userId] = roleNames[relation.userId] == null\n                ? roleName\n                : roleNames[relation.userId] + \',\' + roleName\n        }\n    }\n}\n\nvar orgRelations = db.table("rm_user_org_rela_t").where()\n    .in("user_id", userIds)\n    .select()\nvar orgIds = {}\nif (orgRelations != null) {\n    for (relation in orgRelations) {\n        orgIds[relation.userId] = relation.orgId\n    }\n}\n\nfor (user in userPage.list) {\n    user.roleNames = roleNames[user.id] || \'\'\n    user.orgId = orgIds[user.id] || \'\'\n}\nreturn userPage\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/02.用户分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bced293de53e4b348940f99b1b5bdf9f',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "bced293de53e4b348940f99b1b5bdf9f",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "03.当前用户信息",\n  "createTime": 1782660715924,\n  "updateTime": 1788947882331,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/me",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "当前用户信息（POST /sym/user/me）。读取当前会话用户、角色、权限和主属部门；组织配置缺失时返回明确业务提示，不暴露脚本异常；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 appId；涉及 rm_user_role_rela_t、rm_role_t、rm_org_t、rm_role_menu_rela_t、rm_menu_t、rm_user_org_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.当前用户信息\n// 路由：POST /sym/user/me\n// 业务说明：当前用户信息（POST /sym/user/me）。读取当前会话用户、角色、权限和主属部门；组织配置缺失时返回明确业务提示，不暴露脚本异常；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 appId；涉及 rm_user_role_rela_t、rm_role_t、rm_org_t、rm_role_menu_rela_t、rm_menu_t、rm_user_org_rela_t 等业务表。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\nimport tenantRuntime\n\n\n\n/*\n * 当前用户信息。\n *\n * 只读接口。组织归属是当前用户权限与数据范围的前提；所有组织查询都以服务端\n * 当前租户为准。缺少用户、角色、主属部门、组织编码或根部门时返回业务错误，\n * 避免出现空对象脚本异常和向浏览器暴露调用栈。\n */\nvar text = value => value == null ? \'\' : (value + \'\').trim()\n\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit 401, \'账号未登录或登录已过期\'\n}\n\nvar tenantId = text(tenantRuntime.id())\nif (tenantId == \'\') {\n    exit 401, \'当前登录租户无效，请重新登录\'\n}\n\nvar appId = body?.appId || tenantAccounts.session().get(\'appId\')\nvar user = tenantAccounts.find(tenantId, StpUtil.getLoginId() + \'\')\nif (user == null) {\n    exit 401, \'当前登录账号不存在或已失效，请重新登录\'\n}\n\nvar newUser = {\n    id: user.id,\n    realName: user.realName,\n    userName: user.userName,\n    phone: user.phone,\n    gender: user.gender,\n    createId: user.createId\n}\n\nvar userRoleList = db.table(\'rm_user_role_rela_t\').where()\n    .eq(\'user_id\', StpUtil.getLoginId())\n    .select()\nif (userRoleList == null || userRoleList.isEmpty()) {\n    exit 400, \'当前用户未配置应用角色，请联系管理员\'\n}\n\nvar roleIds = userRoleList.map(item => item.roleId)\nvar roleQuery=db.table(\'rm_role_t\').where().eq(\'app_id\',appId).in(\'id\',roleIds);\nif(tenantAccounts.isLocal(tenantId)) {roleQuery=roleQuery.eq(\'deleted\',0).eq(\'status\',0);}\nvar roleList=roleQuery.select();\nif(tenantAccounts.isLocal(tenantId) && (roleList==null || roleList.size()==0)) {exit 400,\'当前用户未配置有效的应用角色，请联系管理员\';}\n\nvar roles = roleList == null ? [] : roleList.map(item => item.codeNum)\n\nvar permsSQL = """\n    select distinct res.*\n      from rm_role_t role\n      join rm_role_menu_rela_t rr on rr.role_id = role.id and rr.tenant_id = #{tenantId}\n      join rm_menu_t res on res.id = rr.app_resource_id and res.app_id = role.app_id and res.tenant_id = #{tenantId}\n     where role.app_id = #{appId}\n       and role.id in (#{roleIds})\n       and role.deleted = 0\n       and role.status = 0\n       and res.deleted = 0\n       and res.resource_type = 1\n       and role.tenant_id = #{tenantId}\n"""\nvar permsList = db.select(permsSQL)\nvar perms = permsList == null ? [] : permsList.map(item => item.sno)\n\nvar orgSQL = """\n    select u.user_id, org.id, org.name, org.serial_number, org.org_path\n      from rm_user_org_rela_t u\n      join rm_org_t org on org.id = u.org_id and org.tenant_id = #{tenantId}\n     where u.user_id = #{user.id}\n       and u.job_type = 1\n       and u.tenant_id = #{tenantId}\n"""\nvar org = db.selectOne(orgSQL)\nif (org == null) {\n    exit 400, \'当前用户未配置主属部门，请联系管理员\'\n}\n\nvar serialNumber = text(org.serialNumber)\nif (serialNumber == \'\') {\n    exit 400, \'当前用户主属部门的组织编码不完整，请联系管理员\'\n}\nvar orgPath = text(org.orgPath)\nif (orgPath == \'\') {\n    exit 400, \'当前用户主属部门的组织路径为空，请联系管理员\'\n}\n\nvar orgRootSerialNumber = serialNumber.substring(0, 4)\nvar orgRoot = db.table(\'rm_org_t\').where()\n    .eq(\'serialNumber\', orgRootSerialNumber)\n    .eq(\'parentId\', \'ROOT\')\n    .eq(\'nature\', \'2\')\n    .selectOne()\nif (orgRoot == null) {\n    exit 400, \'当前用户主属部门的组织编码未关联有效根部门，请联系管理员\'\n}\n\nreturn {\n    ...newUser,\n    orgId: org.id,\n    orgName: org.name,\n    serialNumber: serialNumber,\n    orgPath: orgPath,\n    roles: roles,\n    perms: perms,\n    orgRootId: orgRoot.id,\n    orgRootSerialNumber: orgRoot.serialNumber\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/03.当前用户信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('84d4f35904ab45d8a6a9c08ab67ece7e',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "84d4f35904ab45d8a6a9c08ab67ece7e",\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "04.用户删除",\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"id\\": \\"用户ID\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"id\\": \\"用户ID\\",\\n  \\"accountDeleted\\": false\\n}",\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 id。",\n  "script": null\n}\n================================\n// 接口：04.用户删除\n// 路由：POST /sym/user/delete\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 id。\nimport \'@/tenant-account/users\' as localUsers\nreturn localUsers(\'delete\',{id:body?.id||id});\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/04.用户删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('438022734caa445288081ecc7bcf247b',NULL,NULL,'{\n  "properties": {},\n  "id": "438022734caa445288081ecc7bcf247b",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "05.应用用户查询",\n  "path": "/user/application-list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "兼容用户查询接口；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.应用用户查询\n// 路由：GET /sym/user/user/application-list\n// 业务说明：兼容用户查询接口；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport tenantRuntime\n\n\ntry { tenantAccounts.session() } catch (e) { exit -1, \'账号未登录或登录已过期\' }\nreturn tenantAccounts.list(tenantRuntime.id(), null)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/05.应用用户查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0db56c0aa4a5420ebc7f303b2fc06e8b',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "0db56c0aa4a5420ebc7f303b2fc06e8b",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "06.用户保存修改",\n  "createTime": null,\n  "updateTime": 1786690392991,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"realName\\": \\"叶华\\",\\n  \\"phone\\": \\"13800000000\\",\\n  \\"userName\\": \\"yehua\\",\\n  \\"password\\": \\"******\\",\\n  \\"status\\": 1,\\n  \\"orgId\\": \\"组织ID\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"id\\": \\"用户ID\\"\\n}",\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.用户保存修改\n// 路由：POST /sym/user/saveOrUpdate\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役。\nimport \'@/tenant-account/users\' as localUsers\nreturn localUsers(\'save\',body||{});\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/06.用户保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('007841d72ac04f8589d817ad04436d7c',NULL,NULL,'{\n  "properties": {},\n  "id": "007841d72ac04f8589d817ad04436d7c",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "07.用户兼容分页",\n  "createTime": null,\n  "updateTime": 1787153759480,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/user/compat-page",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "兼容用户查询接口；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 rm_user_org_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.用户兼容分页\n// 路由：GET /sym/user/user/compat-page\n// 业务说明：兼容用户查询接口；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 rm_user_org_rela_t 等业务表。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport tenantRuntime\n\n\ntry { tenantAccounts.session() } catch (e) { exit -1, \'账号未登录或登录已过期\' }\n\nvar tenantId = tenantRuntime.id()\nvar pageSize = (limit || 10).asInt()\nvar offsetValue = (offset || 0).asInt()\nvar filters = { pageNum: (offsetValue / pageSize).asInt() + 1, pageSize: pageSize }\nif (ids != null && ids != \'\') { filters.ids = ids.split(\',\') }\nif (userName != null && userName != \'\') { filters.userName = userName }\nif (realName != null && realName != \'\') { filters.realName = realName }\n\n// Organization links are tenant-owned; account lookup is delegated to tenantAccounts.\nif (orgId != null && orgId != \'\') {\n    var relations = db.table(\'rm_user_org_rela_t\').where().eq(\'org_id\', orgId).select()\n    filters.ids = relations == null ? [] : relations.map(item => item.userId)\n}\nvar result = tenantAccounts.page(tenantId, filters.pageNum, filters.pageSize, filters.ids,\n    filters.userName, filters.realName)\nreturn result.list || []\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/07.用户兼容分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8e92fed1bb2e4931aea12567d273c54d',NULL,'api','this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/08.在线用户/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6743b6c46a384a7c8881d0a582a3947e',NULL,NULL,'{\n  "properties": {\n    "gaLocalSessionAdapter": "v1"\n  },\n  "id": "6743b6c46a384a7c8881d0a582a3947e",\n  "script": null,\n  "groupId": "8b441ce693f44c30af90b26d85743384",\n  "name": "01.在线用户分页",\n  "createTime": 1785640211460,\n  "updateTime": 1787182300236,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"keyword\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "在线用户分页（POST /sym/user/online/page）。读取当前租户 Sa-Token/Redis 会话，不返回可复用登录令牌；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 pageNum、pageSize、keyword。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.在线用户分页\n// 路由：POST /sym/user/online/page\n// 业务说明：在线用户分页（POST /sym/user/online/page）。读取当前租户 Sa-Token/Redis 会话，不返回可复用登录令牌；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 pageNum、pageSize、keyword。\nimport tenantAccounts\n\nimport \'@/tenant-account/users\' as localUsers\nimport cn.dev33.satoken.stp.StpUtil\nimport java.nio.charset.StandardCharsets\nimport java.security.MessageDigest\nimport java.util.HexFormat\nimport tenantRuntime\n\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar rowValue = (row, keys) => {\n  for (key in keys) {\n    if (row != null && row[key] != null) {\n      return row[key]\n    }\n  }\n  return null\n}\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar currentTenantId = text(tenantRuntime.id())\nif (currentTenantId == \'\') {\n  exit 401, \'未获取到当前租户\'\n}\nvar pageNum = body == null || body.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body == null || body.pageSize == null ? 20 : body.pageSize::int\npageNum = pageNum < 1 ? 1 : pageNum\npageSize = pageSize < 1 ? 20 : (pageSize > 200 ? 200 : pageSize)\nvar keyword = text(body == null ? null : body.keyword).toLowerCase()\nvar logic = StpUtil.getStpLogic()\nvar tokenValues = tenantAccounts.tokens()\nvar sessionRows = []\nvar loginIds = []\nvar fingerprint = token => HexFormat.of().formatHex(MessageDigest.getInstance(\'SHA-256\').digest((token + \'\').getBytes(StandardCharsets.UTF_8)))\nfor (token in tokenValues) {\n  try {\n    if (!logic.isValidToken(token)) {\n      continue\n    }\n    var accountId = logic.getLoginIdByTokenNotThinkFreeze(token)\n    if (accountId == null) {\n      continue\n    }\n    var tokenSession = logic.getTokenSessionByToken(token, false)\n    if (tokenSession == null || text(tokenSession.get(\'tenantId\')) != currentTenantId || (tenantAccounts.isLocal(currentTenantId) && tokenSession.get(\'authRealm\')!=\'tenant-local-v1\')) {\n      continue\n    }\n    var terminal = logic.getTerminalInfoByToken(token)\n    var loginTime = terminal == null ? tokenSession.getCreateTime() : terminal.getCreateTime()\n    var activeTime = 0\n    try {\n      activeTime = logic.getTokenLastActiveTime(token)\n    } catch (ignored) { }\n    var row = { sessionKey: fingerprint(token), tokenValue: token, loginId: text(accountId), deviceType: terminal == null ? null : terminal.getDeviceType(), deviceId: terminal == null ? null : terminal.getDeviceId(), loginTime: loginTime, lastActiveTime: activeTime, timeoutSeconds: logic.getTokenTimeout(token), current: token == StpUtil.getTokenValue() }\n    sessionRows.add(row)\n    if (!loginIds.contains(row.loginId)) {\n      loginIds.add(row.loginId)\n    }\n  } catch (ignored) { }\n}\nvar userMap = {}\nif (loginIds.size() > 0) {\n  for (user in tenantAccounts.page(currentTenantId,1,200,loginIds,null,null).list) {\n    userMap[text(rowValue(user, [\'id\']))] = user\n  }\n}\nvar result = []\nfor (session in sessionRows) {\n  var user = userMap[session.loginId]\n  session.userName = user == null ? session.loginId : rowValue(user, [\'userName\',\'user_name\'])\n  session.realName = user == null ? session.loginId : rowValue(user, [\'realName\',\'real_name\'])\n  var search = (text(session.loginId) + \' \' + text(session.userName) + \' \' + text(session.realName) + \' \' + text(session.deviceType) + \' \' + text(session.deviceId)).toLowerCase()\n  if (keyword == \'\' || search.contains(keyword)) {\n    session.remove(\'tokenValue\')\n    result.add(session)\n  }\n}\nvar from = (pageNum - 1) * pageSize\nif (from > result.size()) {\n  from = result.size()\n}\nvar to = from + pageSize\nif (to > result.size()) {\n  to = result.size()\n}\nreturn { list: result.subList(from, to), total: result.size(), pageNum: pageNum, pageSize: pageSize }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/08.在线用户/01.在线用户分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('72bece30af4d4ca998f0378d6ba69923',NULL,NULL,'{\n  "properties": {\n    "gaLocalSessionAdapter": "v1"\n  },\n  "id": "72bece30af4d4ca998f0378d6ba69923",\n  "script": null,\n  "groupId": "8b441ce693f44c30af90b26d85743384",\n  "name": "02.强制下线",\n  "createTime": 1785640211460,\n  "updateTime": 1787182300196,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/kickout",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"sessionKey\\": \\"SHA-256 session key from page API\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "强制下线（POST /sym/user/online/kickout）。仅允许管理当前租户会话，不允许下线当前管理会话；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 sessionKey。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.强制下线\n// 路由：POST /sym/user/online/kickout\n// 业务说明：强制下线（POST /sym/user/online/kickout）。仅允许管理当前租户会话，不允许下线当前管理会话；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 sessionKey。\nimport tenantAccounts\n\nimport cn.dev33.satoken.stp.StpUtil\nimport java.nio.charset.StandardCharsets\nimport java.security.MessageDigest\nimport java.util.HexFormat\nimport tenantRuntime\n\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar currentTenantId = text(tenantRuntime.id())\nif (currentTenantId == \'\') {\n  exit 401, \'未获取到当前租户\'\n}\nvar sessionKey = text(body == null ? null : body.sessionKey)\nif (sessionKey == \'\') {\n  exit 400, \'会话标识不能为空\'\n}\nvar logic = StpUtil.getStpLogic()\nvar fingerprint = token => HexFormat.of().formatHex(MessageDigest.getInstance(\'SHA-256\').digest((token + \'\').getBytes(StandardCharsets.UTF_8)))\nfor (token in tenantAccounts.tokens()) {\n  try {\n    if (!logic.isValidToken(token) || fingerprint(token) != sessionKey) {\n      continue\n    }\n    var tokenSession = logic.getTokenSessionByToken(token, false)\n    if (tokenSession == null || text(tokenSession.get(\'tenantId\')) != currentTenantId || (tenantAccounts.isLocal(currentTenantId) && tokenSession.get(\'authRealm\')!=\'tenant-local-v1\')) {\n      continue\n    }\n    if (token == StpUtil.getTokenValue()) {\n      exit 400, \'不能强制下线当前会话\'\n    }\n    logic.kickoutByTokenValue(token)\n    return { kicked: true }\n  } catch (e) {\n    if (e.message != null && e.message.contains(\'不能强制下线\')) {\n      throw e\n    }\n  }\n}\nexit 404, \'在线会话不存在、已失效或不属于当前租户\'\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/08.在线用户/02.强制下线.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8b441ce693f44c30af90b26d85743384',NULL,'api','{\n  "properties" : { },\n  "id" : "8b441ce693f44c30af90b26d85743384",\n  "name" : "08.在线用户",\n  "type" : "api",\n  "parentId" : "1ac60b4ccbc142e89dc1bf575e674d20",\n  "path" : "/online",\n  "createTime" : 1785575697577,\n  "updateTime" : 1785575697577,\n  "createBy" : "codex",\n  "updateBy" : "codex",\n  "paths" : [ ],\n  "options" : [ ]\n}\n================================\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/08.在线用户/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('user_role_save_01',NULL,NULL,'{\n  "properties": {},\n  "id": "user_role_save_01",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "08.用户角色保存",\n  "path": "/saveRoles",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"userId\\": \\"用户ID\\",\\n  \\"roleIds\\": [\\"角色ID\\"]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"roleIds\\": []\\n}",\n  "description": "用户角色保存：POST /sym/user/saveRoles。替换当前租户内用户的角色关联；只允许选择当前应用存在的角色；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 userId、appId、roleIds；涉及 rm_role_t、rm_user_role_rela_t 等业务表。"\n}\n================================\n// 接口：08.用户角色保存\n// 路由：POST /sym/user/saveRoles\n// 业务说明：用户角色保存：POST /sym/user/saveRoles。替换当前租户内用户的角色关联；只允许选择当前应用存在的角色；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 userId、appId、roleIds；涉及 rm_role_t、rm_user_role_rela_t 等业务表。\nimport \'@/tenant-account/roles\' as localRoles\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\nif(tenantAccounts.isLocal(tenantRuntime.id())) {return localRoles(body||{});}\n\n\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit 401, \'账号未登录或登录已过期\'\n}\n\nvar userId = body?.userId == null ? \'\' : (body.userId + \'\').trim()\nif (userId == \'\') {\n    exit 400, \'用户ID不能为空\'\n}\nif (tenantAccounts.find(tenantRuntime.id(), userId) == null) {\n    exit 404, \'用户不存在或不属于当前租户\'\n}\n\nvar appId = body?.appId || tenantAccounts.session().get(\'appId\')\nif (appId == null || (appId + \'\').trim() == \'\') {\n    exit 400, \'未获取到当前应用\'\n}\n\nvar availableRoles = db.table(\'rm_role_t\').where()\n    .eq(\'app_id\', appId)\n    .eq(\'deleted\', 0)\n    .select()\nvar availableRoleIds = {}\nfor (role in (availableRoles || [])) {\n    availableRoleIds[role.id + \'\'] = true\n}\n\nvar roleIds = []\nfor (roleId in (body?.roleIds || [])) {\n    var normalizedRoleId = roleId == null ? \'\' : (roleId + \'\').trim()\n    if (normalizedRoleId == \'\') {\n        continue\n    }\n    if (availableRoleIds[normalizedRoleId] != true) {\n        exit 400, \'所选角色不存在或不属于当前应用\'\n    }\n    if (!roleIds.contains(normalizedRoleId)) {\n        roleIds.add(normalizedRoleId)\n    }\n}\n\n// 用户角色是当前租户业务关系；全量替换使取消勾选立即生效。\ndb.table(\'rm_user_role_rela_t\').where().eq(\'user_id\', userId).delete()\nvar now = new Date()\nfor (roleId in roleIds) {\n    db.table(\'rm_user_role_rela_t\').insert({\n        id: IdUtil.getSnowflakeNextIdStr(),\n        role_id: roleId,\n        user_id: userId,\n        auth_from: 0,\n        edit_time: now,\n        is_temporary: 0\n    })\n}\nreturn { userId: userId, roleIds: roleIds }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/08.用户角色保存.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('user_role_assignments_01',NULL,NULL,'{\n  "properties": {},\n  "id": "user_role_assignments_01",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "09.用户角色查询",\n  "path": "/roles",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"userId\\": \\"用户ID\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"roleIds\\": []\\n}",\n  "description": "用户角色查询：POST /sym/user/roles。返回当前租户内指定用户的已关联角色 ID，用于自动勾选；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 userId；涉及 rm_user_role_rela_t 等业务表。"\n}\n================================\n// 接口：09.用户角色查询\n// 路由：POST /sym/user/roles\n// 业务说明：用户角色查询：POST /sym/user/roles。返回当前租户内指定用户的已关联角色 ID，用于自动勾选；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 userId；涉及 rm_user_role_rela_t 等业务表。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil\nimport tenantRuntime\n\n\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit 401, \'账号未登录或登录已过期\'\n}\n\n// 读取请求中的业务标识与筛选条件，供下面的校验和查询使用。\nvar userId = body?.userId == null ? \'\' : (body.userId + \'\').trim()\nif (userId == \'\') {\n    exit 400, \'用户ID不能为空\'\n}\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nif (tenantAccounts.find(tenantRuntime.id(), userId) == null) {\n    exit 404, \'用户不存在或不属于当前租户\'\n}\n\n// 以下从 rm_user_role_rela_t 业务表读取或维护当前操作涉及的记录。\nvar relations = db.table(\'rm_user_role_rela_t\').where().eq(\'user_id\', userId).select()\nvar roleIds = []\nfor (relation in (relations || [])) {\n    var roleId = relation.roleId == null ? relation[\'role_id\'] : relation.roleId\n    if (roleId != null && (roleId + \'\').trim() != \'\') {\n        roleIds.add(roleId + \'\')\n    }\n}\nreturn { roleIds: roleIds }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/09.用户角色查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('user_role_options_01',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "user_role_options_01",\n  "script": null,\n  "groupId": "1ac60b4ccbc142e89dc1bf575e674d20",\n  "name": "10.用户角色选项",\n  "path": "/role-options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"list\\": []\\n}",\n  "description": "用户角色选项：POST /sym/user/role-options。返回当前租户、当前应用下全部未删除角色，用于用户角色维护；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 appId；涉及 rm_role_t 等业务表。"\n}\n================================\n// 接口：10.用户角色选项\n// 路由：POST /sym/user/role-options\n// 业务说明：用户角色选项：POST /sym/user/role-options。返回当前租户、当前应用下全部未删除角色，用于用户角色维护；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 appId；涉及 rm_role_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport cn.dev33.satoken.stp.StpUtil\n\n\n\ntry {\n    tenantAccounts.session()\n} catch (e) {\n    exit 401, \'账号未登录或登录已过期\'\n}\n\nvar appId = body?.appId || tenantAccounts.session().get(\'appId\')\nif (appId == null || (appId + \'\').trim() == \'\') {\n    exit 400, \'未获取到当前应用\'\n}\n\n// 租户数据源会自动限定当前租户；不引入平台或租户管理员角色判断。\nvar list = db.table(\'rm_role_t\').where()\n    .eq(\'app_id\', appId)\n    .eq(\'deleted\', 0)\n    .orderBy(\'sort_num\')\n    .select()\n\nif(tenantAccounts.isLocal(tenantRuntime.id())) {list=(list||[]).filter(r=>r.status==0);}\nreturn {list:list||[],total:list==null?0:list.size()};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/10.用户角色选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1ac60b4ccbc142e89dc1bf575e674d20',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "1ac60b4ccbc142e89dc1bf575e674d20",\r\n  "name" : "02.用户管理",\r\n  "type" : "api",\r\n  "parentId" : "9a18bf0b6a994f5aa56aa775f3de9f3d",\r\n  "path" : "/user",\r\n  "createTime" : 1781960047022,\r\n  "updateTime" : 1784437771090,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/02.用户管理/group.json');
