INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b3519d0888524b2d990c3e09822f6e73',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "b3519d0888524b2d990c3e09822f6e73",\n  "script": null,\n  "groupId": "af8d73aa8a2244a88474123d966e8ae5",\n  "name": "01.角色分页",\n  "createTime": 1782660726713,\n  "updateTime": 1784437771459,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "角色分页查询（含关联用户数、权限数、用户ID列表）；使用请求参数 appId、pageNum、pageSize、name、codeNum、ids；涉及 rm_role_t、rm_user_role_rela_t、rm_user_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.角色分页\n// 路由：POST /sym/role/page\n// 业务说明：角色分页查询（含关联用户数、权限数、用户ID列表）；使用请求参数 appId、pageNum、pageSize、name、codeNum、ids；涉及 rm_role_t、rm_user_role_rela_t、rm_user_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport cn.hutool.db.PageResult\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.NumberUtil;\n\n\n// 角色分页查询（含关联用户数、权限数、用户ID列表）\n// 路径: /sym/role/page\n// 方法: POST\n// 参数（均为 body 字段）:\n//   appId     - 应用ID（可选，默认取session中的appId）\n//   pageNum   - 页码（默认1）\n//   pageSize  - 每页条数（默认10）\n//   name      - 角色名称模糊查询（可选）\n//   codeNum   - 角色编码模糊查询（可选）\n//   ids       - 角色ID列表，逗号分隔（可选）\n\n\ntry {\n  tenantAccounts.session();\n} catch (e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 从 body 获取查询参数 ====================\nvar appId    = body?.appId || tenantAccounts.session().get("appId");\nvar pageNum  = (body?.pageNum || 1).asInt();\nvar pageSize = (body?.pageSize || 10).asInt();\nvar name     = body?.name;      // POST body 字段需通过 body?. 获取\nvar codeNum  = body?.codeNum;\nvar ids      = body?.ids;\n\n// 将页码转换为偏移量\nvar offset = (pageNum - 1) * pageSize;\nvar limit = pageSize;\n\n// ==================== 构建查询条件 ====================\nvar result = db.table("rm_role_t").where().eq("deleted", 0).eq("app_id", appId);\n\n// 根据ID列表查询\nif (ids != null && ids != "") {\n    var idList = ids.split(",");\n    result = result.in("id", idList);\n}\n\n// 角色编码模糊查询\nif (codeNum != null && codeNum != "") {\n    result = result.like("code_num", "%" + codeNum + "%");\n}\n\n// 角色名称模糊查询\nif (name != null && name != "") {\n    result = result.like("name", "%" + name + "%");\n}\n\n// ==================== 分页查询 ====================\nvar roleList = result.orderBy("sort_num")\n                     .page(limit, offset);\n\n// ==================== 收集角色ID，初始化默认值 ====================\nvar roleIds = [];\nvar list = roleList.list;\nif (list != null) {\n    for (role in list) {\n        roleIds.push(role.id);\n        role.userCount = 0;\n        role.permCount = 0;\n        role.userIds = "";              // 关联用户ID，逗号分割\n    }\n}\n\n// ==================== 查询关联用户数、权限数、用户ID列表 ====================\nif (roleIds.size() > 0) {\n\n    // --- 查询角色关联用户记录 ---\n    // .lower() 确保返回字段名为 snake_case，与 bracket 访问保持一致\n    var userRecords = db.lower().table("rm_user_role_rela_t")\n        .where()\n        .in("role_id", roleIds)\n        .select();\n\n    if(tenantAccounts.isLocal(tenantRuntime.id())) {\n      var localTenantId=tenantRuntime.id();\n      userRecords=db.lower().select("""\nselect rel.*\nfrom rm_user_role_rela_t rel\njoin rm_user_t u on u.id=rel.user_id\nand u.tenant_id=#{localTenantId}\nwhere rel.tenant_id=#{localTenantId}\n    and rel.role_id in (#{roleIds})\n    and u.deleted=0\n""");\n      var seenLocalUsers={};userRecords=userRecords.filter(r=>{\n        var key=r[\'role_id\']+\':\'+r[\'user_id\'];if(seenLocalUsers[key]==true) {return false;} seenLocalUsers[key]=true;return true;\n      });\n    }\n    var userCountMap = {};\n    var userIdsMap = {};             // roleId → [userId1, userId2, ...]\n    for (ur in userRecords) {\n        var rid = ur["role_id"];\n        var uid = ur["user_id"];\n        if (rid != null && uid != null && uid != "") {\n            // 计数\n            if (userCountMap[rid] == null) {\n                userCountMap[rid] = 0;\n            }\n            userCountMap[rid] = userCountMap[rid] + 1;\n\n            // 收集用户ID\n            if (userIdsMap[rid] == null) {\n                userIdsMap[rid] = [];\n            }\n            userIdsMap[rid].push(uid);\n        }\n    }\n\n    // --- 查询角色关联权限数 ---\n    var permRecords = db.lower().table("rm_role_menu_rela_t")\n        .where()\n        .in("role_id", roleIds)\n        .select();\n\n    var permCountMap = {};\n    for (pr in permRecords) {\n        var rid = pr["role_id"];\n        if (rid != null) {\n            if (permCountMap[rid] == null) {\n                permCountMap[rid] = 0;\n            }\n            permCountMap[rid] = permCountMap[rid] + 1;\n        }\n    }\n\n    // --- 填充到角色列表 ---\n    for (role in roleList.list) {\n        // 用户数\n        if (userCountMap[role.id] != null) {\n            role.userCount = userCountMap[role.id];\n        }\n        // 权限数\n        if (permCountMap[role.id] != null) {\n            role.permCount = permCountMap[role.id];\n        }\n        // 关联用户ID列表（逗号分割）\n        if (userIdsMap[role.id] != null) {\n            role.userIds = userIdsMap[role.id].join(",");\n        }\n    }\n}\n\n// ==================== 返回结果 ====================\nif (roleList.list == null) {\n    roleList.list = [];\n}\n// 返回当前业务分支的标准结果。\nreturn roleList;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/03.角色管理/01.角色分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('347601b7dc2b45c8a52dd14221e17518',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "347601b7dc2b45c8a52dd14221e17518",\n  "script": null,\n  "groupId": "af8d73aa8a2244a88474123d966e8ae5",\n  "name": "02.角色保存修改",\n  "createTime": 1782660726505,\n  "updateTime": 1784437771436,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "角色新增/编辑 + 关联用户保存；使用请求参数 roleName、codeNum、description、status、sortNum、id、userIds、appId；涉及 rm_role_t、rm_user_role_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.角色保存修改\n// 路由：POST /sym/role/saveOrUpdate\n// 业务说明：角色新增/编辑 + 关联用户保存；使用请求参数 roleName、codeNum、description、status、sortNum、id、userIds、appId；涉及 rm_role_t、rm_user_role_rela_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport \'@/tenant-account/role-admin\' as localRoleAdmin\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.date.DateUtil;\nif(tenantAccounts.isLocal(tenantRuntime.id())) {return localRoleAdmin(\'save\',body||{});}\n\n\n// 角色新增/编辑 + 关联用户保存\n// 路径: /sym/role/saveOrUpdate\n// 方法: POST\n// 参数:\n//   id          - 角色ID（有则编辑，无则新增）\n//   appId       - 应用ID（可选，默认取session中的appId）\n//   roleName    - 角色名称（必填，避免与magic-api内置变量name冲突）\n//   codeNum     - 角色编码（必填）\n//   description - 角色描述（可选）\n//   status      - 启用状态（0启用/1禁用）\n//   sortNum     - 排序号（可选，默认0）\n//   userIds     - 关联用户ID，逗号分隔字符串（如 "id1,id2,id3"）\n//\n// 关联表:\n\n\ntry {\n    tenantAccounts.session();\n} catch (e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 参数获取（POST body） ====================\nvar roleName = body?.roleName;\nvar codeNum = body?.codeNum;\nvar description = body?.description || "";\nvar status = body?.status;\nvar sortNum = body?.sortNum;\nvar id = body?.id;\nvar userIds = body?.userIds || "";\nvar appId = body?.appId || tenantAccounts.session().get("appId");\n\n// ==================== 参数校验 ====================\nvar currentUserId = StpUtil.getLoginId();\nvar now = DateUtil.now();\n\nif (roleName == null || roleName == "") {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "角色名称不能为空";\n}\nif (codeNum == null || codeNum == "") {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "角色编码不能为空";\n}\n\n// ==================== 保存角色信息 ====================\nvar isUpdate = (id != null && id != "");\nvar roleId;\n\nif (isUpdate) {\n    // --- 编辑角色 ---\n    roleId = id;\n    var updateMap = {};\n    updateMap["name"] = roleName;\n    updateMap["code_num"] = codeNum;\n    updateMap["description"] = description;\n    updateMap["status"] = status;\n    if (sortNum != null) {\n        updateMap["sort_num"] = sortNum;\n    }\n    updateMap["update_id"] = currentUserId;\n    updateMap["update_time"] = now;\n\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table("rm_role_t").where().eq("id", roleId).update(updateMap);\n\n} else {\n    // --- 新增角色 ---\n    roleId = IdUtil.getSnowflakeNextIdStr();\n    var insertMap = {};\n    insertMap["id"] = roleId;\n    insertMap["app_id"] = appId;\n    insertMap["name"] = roleName;\n    insertMap["code_num"] = codeNum;\n    insertMap["description"] = description;\n    insertMap["status"] = status != null ? status : 0;\n    insertMap["sort_num"] = sortNum != null ? sortNum : 0;\n    insertMap["deleted"] = 0;\n    insertMap["create_id"] = currentUserId;\n    insertMap["update_id"] = currentUserId;\n    insertMap["create_time"] = now;\n    insertMap["update_time"] = now;\n\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table("rm_role_t").insert(insertMap);\n}\n\n// ==================== 保存角色用户关联 ====================\n// 先删除该角色所有现有用户关联\ndb.table("rm_user_role_rela_t").where().eq("role_id", roleId).delete();\n\n// 再插入新关联\nif (userIds != null && userIds != "") {\n    var userIdArray = userIds.split(",");\n    for (uid in userIdArray) {\n        uid = uid.trim();\n        if (uid != "" && uid != null) {\n            var relMap = {};\n            relMap["id"] = IdUtil.getSnowflakeNextIdStr();\n            relMap["role_id"] = roleId;\n            relMap["user_id"] = uid;\n            relMap["auth_from"] = 0;\n            relMap["edit_time"] = now;\n            relMap["is_temporary"] = 0;\n\n            // 将校验后的业务数据写入 MySQL 主表。\n            db.table("rm_user_role_rela_t").insert(relMap);\n        }\n    }\n}\n\n// ==================== 返回 ====================\nreturn { success: true, id: roleId };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/03.角色管理/02.角色保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f0d7c425b9dc42619db0e70fa9bd546f',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "f0d7c425b9dc42619db0e70fa9bd546f",\n  "script": null,\n  "groupId": "af8d73aa8a2244a88474123d966e8ae5",\n  "name": "03.角色删除",\n  "createTime": 1782660726928,\n  "updateTime": 1784437771461,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按目标标识和当前状态执行角色删除，返回处理结果；使用请求参数 id；涉及 rm_role_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.角色删除\n// 路由：POST /sym/role/delete\n// 业务说明：按目标标识和当前状态执行角色删除，返回处理结果；使用请求参数 id；涉及 rm_role_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport \'@/tenant-account/role-admin\' as localRoleAdmin\nimport cn.dev33.satoken.stp.StpUtil;\nif(tenantAccounts.isLocal(tenantRuntime.id())) {return localRoleAdmin(\'delete\',body||{});}\n\n\n// 删除角色\n// 路径: /sym/role/delete\n// 方法: POST\n// 参数（均为 body 字段）:\n//   id       - 角色ID（必填）\n// 说明:\n//   角色主表 rm_role_t 执行软删除（deleted = 1）\n//   关联表 rm_user_role_rela_t 删除 auth_from = 0 的直接授权记录\n//   关联表 rm_role_menu_rela_t 删除角色对应的资源授权记录\n\n\ntry {\n  tenantAccounts.session();\n} catch (e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 从 body 获取参数 ====================\nvar id = body?.id;\n\n// ==================== 参数校验 ====================\nif (id == null || id == "") {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "角色ID不能为空";\n}\n\nvar currentUserId = StpUtil.getLoginId();\nvar now = new Date();\n\n// ==================== 1. 软删除角色主表 ====================\nvar updateMap = {};\nupdateMap["deleted"] = 1;\nupdateMap["update_id"] = currentUserId;\nupdateMap["update_time"] = now;\n\n// 将校验后的业务数据写入 MySQL 主表。\ndb.table("rm_role_t").where().eq("id", id).update(updateMap);\n\n// ==================== 2. 删除角色直接授权的用户关联 ====================\ndb.lower().table("rm_user_role_rela_t")\n    .where()\n    .eq("role_id", id)\n    .eq("auth_from", 0)\n    .delete();\n\n// ==================== 3. 删除角色关联的资源权限 ====================\ndb.lower().table("rm_role_menu_rela_t")\n    .where()\n    .eq("role_id", id)\n    .delete();\n\n// ==================== 返回结果 ====================\nreturn {\n    success: true,\n    msg: "删除成功"\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/03.角色管理/03.角色删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9793b13bdb0d4d09bc1f909e7d1bd122',NULL,NULL,'{\n  "properties": {},\n  "id": "9793b13bdb0d4d09bc1f909e7d1bd122",\n  "script": null,\n  "groupId": "af8d73aa8a2244a88474123d966e8ae5",\n  "name": "04.角色兼容分页",\n  "createTime": 1782660716040,\n  "updateTime": 1786711183521,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/pageRole",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "ids",\n      "value": null,\n      "description": "真实数据示例参数：ids",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "appId",\n      "value": null,\n      "description": "真实数据示例参数：appId",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "1995678661281710081",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "codeNum",\n      "value": null,\n      "description": "真实数据示例参数：codeNum",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": "角色编码",\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "name",\n      "value": null,\n      "description": "真实数据示例参数：name",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": "角色名称",\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "offset",\n      "value": null,\n      "description": "真实数据示例参数：offset",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "0",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "limit",\n      "value": null,\n      "description": "真实数据示例参数：limit",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "10",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "管理页默认查询当前租户全部角色；仅在调用方明确传入 appId 时按应用筛选；涉及 rm_role_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "0",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "success",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "true",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": [\n          {\n            "name": "total",\n            "value": "1",\n            "description": "",\n            "required": false,\n            "dataType": "Integer",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": []\n          },\n          {\n            "name": "list",\n            "value": "",\n            "description": "",\n            "required": false,\n            "dataType": "Array",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": [\n              {\n                "name": "",\n                "value": "",\n                "description": "",\n                "required": false,\n                "dataType": "Object",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": [\n                  {\n                    "name": "id",\n                    "value": "1995679968881147906",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "createId",\n                    "value": "ECF8E1513080B87F51B9285F491915EA",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "updateId",\n                    "value": "ECF8E1513080B87F51B9285F491915EA",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "deleted",\n                    "value": "0",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Integer",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "createTime",\n                    "value": "2025-12-02 10:22:37",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "updateTime",\n                    "value": "2025-12-02 10:22:37",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "status",\n                    "value": "0",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Integer",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "name",\n                    "value": "管理员",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "codeNum",\n                    "value": "admin",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "description",\n                    "value": "admin",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "appId",\n                    "value": "1995678661281710081",\n                    "description": "",\n                    "required": false,\n                    "dataType": "String",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "sortNum",\n                    "value": "0",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Integer",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  },\n                  {\n                    "name": "rowId",\n                    "value": "1",\n                    "description": "",\n                    "required": false,\n                    "dataType": "Integer",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": []\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：04.角色兼容分页\n// 路由：GET /sym/role/pageRole\n// 业务说明：管理页默认查询当前租户全部角色；仅在调用方明确传入 appId 时按应用筛选；涉及 rm_role_t 等业务表。\nimport tenantAccounts\nimport cn.hutool.db.PageResult\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.NumberUtil;\n\n\ntry{\n  tenantAccounts.session();\n}catch(e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";  \n}\n\n// 查询参数\n// 管理页默认查询当前租户全部角色；仅在调用方明确传入 appId 时按应用筛选。\nvar requestedAppId = body?.appId\nvar pageSizeValue = (pageSize || limit || 10).asInt()\nvar pageNo = (page || 1).asInt()\nvar offsetValue = (offset || ((pageNo - 1) * pageSizeValue)).asInt()\n\n// 构建查询条件\nvar result = db.table("rm_role_t").where().eq("deleted", 0);\nif (requestedAppId != null && (requestedAppId + \'\').trim() != \'\') {\n    result = result.eq("app_id", requestedAppId);\n}\n\n// 根据ID列表查询\nif (ids && ids != "") {\n    var idList = ids.split(",");\n    result = result.in("id", idList);\n}\n\n// 角色编码模糊查询\nif (codeNum && codeNum != "") {\n    result = result.like("code_num", "%" + codeNum + "%");\n}\n\n// 角色名称模糊查询\nif (name && name != "") {\n    result = result.like("name", "%" + name + "%");\n}\n\n// 分页查询\nvar roleList = result.orderBy("sort_num")\n                    .page(pageSizeValue, offsetValue);\n\n// 返回结果\nreturn roleList;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/03.角色管理/04.角色兼容分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('102ab47a48044492a06eed24a5321079',NULL,NULL,'{\n  "properties": {},\n  "id": "102ab47a48044492a06eed24a5321079",\n  "script": null,\n  "groupId": "af8d73aa8a2244a88474123d966e8ae5",\n  "name": "05.应用角色查询",\n  "createTime": 1782660716201,\n  "updateTime": 1784437771353,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/appRoleList",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"current\\": 1,\\n    \\"size\\": 10\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按应用标识及可选用户标识查询当前租户角色，补充角色与菜单的展示资料后返回。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.应用角色查询\n// 路由：POST /sym/role/appRoleList\n// 业务说明：按应用标识及可选用户标识查询当前租户角色，补充角色与菜单的展示资料后返回。\nimport tenantAccounts\nimport log\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.NumberUtil\nimport java.util.List\nimport com.linewell.dataelement.utils.MenuTreeUtil\nimport cn.hutool.json.JSONUtil\nimport com.linewell.dataelement.model.Menu\n\n\n\ntry{\n  tenantAccounts.session();\n}catch(e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";  \n}\n\n// 没有入参就注销退出登录\n//     exit 400, \'appId参数不能为空\';\n// }\n\n//优先读取body中的参数\nvar appId = body?.appId || tenantAccounts.session().get("appId");\nvar userId = body?.userId || StpUtil.getLoginId();\n//严格校验参数类型\n\n\nvar roleList = db.table("rm_role_t").where()\n             .eq("app_id",appId)\n             .select();\n\n// 返回当前业务分支的标准结果。\nreturn roleList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/03.角色管理/05.应用角色查询.ms');
