INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1f91899a67444ecb8cbdaae5485ef17f',NULL,NULL,'{\n  "properties": {},\n  "id": "1f91899a67444ecb8cbdaae5485ef17f",\n  "script": null,\n  "groupId": "c1736799c6af43359a75e6764601931f",\n  "name": "01.机构详情",\n  "createTime": 1782660716455,\n  "updateTime": 1784437771402,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/detail",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按机构标识读取当前租户的组织机构资料，返回查看和编辑页面所需字段。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.机构详情\n// 路由：POST /sym/org/detail\n// 业务说明：按机构标识读取当前租户的组织机构资料，返回查看和编辑页面所需字段。\n// 组织机构详情接口\n// 路径: /api/org/detail\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: id (必填,机构ID)\n\n// 获取入参\nvar id = body?.id || \'\';\n\n// 参数校验\nif (id == null || id == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'机构ID不能为空\';\n}\n\ntry {\n    // 从 MySQL 业务表读取当前有效数据。\n    var record = db.table("rm_org_t")\n        .where().eq("id", id).eq("deleted", 0).selectOne();\n\n    if (record == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'机构不存在: \' + id;\n    }\n\n    // 返回当前业务分支的标准结果。\n    return record;\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'查询失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/01.机构详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('885b78dbd4474a4cb47566030e050c76',NULL,NULL,'{\n  "properties": {},\n  "id": "885b78dbd4474a4cb47566030e050c76",\n  "script": null,\n  "groupId": "c1736799c6af43359a75e6764601931f",\n  "name": "02.机构保存修改",\n  "createTime": 1782660716404,\n  "updateTime": 1784437771383,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"name\\": \\"自然资源部\\",\\n    \\"shortName\\": \\"测试\\",\\n    \\"nature\\": \\"2\\",\\n    \\"status\\": 0,\\n    \\"parentId\\": \\"2067073568296509440\\",\\n    \\"sortNum\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行机构保存修改，返回保存或配置结果；使用请求参数 id、name、parentId、shortName、creditCode、standard、nature、status；涉及 rm_org_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.机构保存修改\n// 路由：POST /sym/org/saveOrUpdate\n// 业务说明：校验请求资料后执行机构保存修改，返回保存或配置结果；使用请求参数 id、name、parentId、shortName、creditCode、standard、nature、status；涉及 rm_org_t 等业务表。\n// 组织机构保存/更新接口\n// 路径: /api/org/saveOrUpdate\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: id(可选,有则更新无则新增), name, parentId, shortName, creditCode, standard, nature,\n//       nationalCode, nationalName, regionCode, nodeType, label, leaderOrgId\n\nimport cn.hutool.core.util.IdUtil\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar id            = body?.id || \'\';\nvar name          = body?.name || \'\';\nvar parentId      = body?.parentId || \'\';\nvar shortName     = body?.shortName || \'\';\nvar creditCode    = body?.creditCode || \'\';\nvar standard      = body?.standard || \'\';\nvar nature        = body?.nature != null ? body.nature : \'2\';  // 区域:1 部门:2 虚拟:3，默认部门\nvar status        = body?.status != null ? body.status : 0;    // 禁用:1 启用:0\nvar serialNumber  = body?.serialNumber || \'\';\nvar sortNum       = body?.sortNum != null ? body.sortNum : null;\nvar description   = body?.description || \'\';\nvar deptType      = body?.deptType || \'\';\nvar deptCode      = body?.deptCode || \'\';\nvar nationalCode  = body?.nationalCode || \'\';\nvar nationalName  = body?.nationalName || \'\';\nvar regionCode    = body?.regionCode || \'\';\nvar nodeType      = body?.nodeType || \'\';\nvar label         = body?.label || \'\';\nvar leaderOrgId   = body?.leaderOrgId || \'\';\nvar createId      = me().createId;\nvar updateId      = body?.updateId || \'\';\n\n\ntry {\n    // 构建字段数据（驼峰，与数据库字段一致）\n    var data = {\n        name: name,\n        parentId: parentId,\n        shortName: shortName,\n        creditCode: creditCode,\n        standard: standard,\n        nature: nature,\n        status: status,\n        serialNumber: serialNumber,\n        sortNum: sortNum,\n        description: description,\n        deptType: deptType,\n        deptCode: deptCode,\n        nationalCode: nationalCode,\n        nationalName: nationalName,\n        regionCode: regionCode,\n        nodeType: nodeType,\n        label: label,\n        leaderOrgId: leaderOrgId\n    };\n\n    if (id != null && id != \'\') {\n        // ========== 更新逻辑 ==========\n        var exist = db.table("rm_org_t")\n            .where().eq("id", id).eq("deleted", 0).selectOne();\n\n        if (exist == null) {\n            // 参数或业务状态不满足要求时立即终止请求。\n            exit 404, \'记录不存在: \' + id;\n        }\n\n        // 普通操作（如启用/禁用）也会复用本接口；未传字段必须保留原值，不能写成空串。\n        data.name = body?.name != null ? name : exist.name;\n        data.parentId = body?.parentId != null && parentId != \'\' ? parentId : exist.parentId;\n        data.shortName = body?.shortName != null ? shortName : exist.shortName;\n        data.creditCode = body?.creditCode != null ? creditCode : exist.creditCode;\n        data.standard = body?.standard != null ? standard : exist.standard;\n        data.nature = body?.nature != null ? nature : exist.nature;\n        data.status = body?.status != null ? status : exist.status;\n        data.serialNumber = exist.serialNumber;\n        data.sortNum = body?.sortNum != null ? sortNum : exist.sortNum;\n        data.description = body?.description != null ? description : exist.description;\n        data.deptType = body?.deptType != null ? deptType : exist.deptType;\n        data.deptCode = body?.deptCode != null ? deptCode : exist.deptCode;\n        data.nationalCode = body?.nationalCode != null ? nationalCode : exist.nationalCode;\n        data.nationalName = body?.nationalName != null ? nationalName : exist.nationalName;\n        data.regionCode = body?.regionCode != null ? regionCode : exist.regionCode;\n        data.nodeType = body?.nodeType != null ? nodeType : exist.nodeType;\n        data.label = body?.label != null ? label : exist.label;\n        data.leaderOrgId = body?.leaderOrgId != null ? leaderOrgId : exist.leaderOrgId;\n        data.updateId = createId || updateId || exist.updateId;\n        data.updateTime = now;\n\n        if (data.name == null || data.name == \'\') {\n            exit 400, \'机构名称不能为空\';\n        }\n\n        var oldParentId = exist.parentId || \'ROOT\';\n        var targetParentId = data.parentId || \'ROOT\';\n        var parentChanged = targetParentId != oldParentId;\n        var nameChanged = data.name != exist.name;\n        var oldOrgPath = exist.orgPath || \'\';\n        var oldSerialNumber = exist.serialNumber || \'\';\n        var newOrgPath = oldOrgPath;\n        var newSerialNumber = oldSerialNumber;\n\n        if (parentChanged) {\n            if (id == \'ROOT\') {\n                exit 400, \'全部机构为系统根节点，不能修改上级机构\';\n            }\n            if (targetParentId == id) {\n                exit 400, \'不能将机构设置为自身的上级机构\';\n            }\n\n            var parent = db.table("rm_org_t")\n                .where().eq("id", targetParentId).eq("deleted", 0).selectOne();\n            if (parent == null) {\n                exit 404, \'上级机构不存在: \' + targetParentId;\n            }\n\n            // 父级链反向检查，禁止把节点移动到自己的任意子孙节点下。\n            var ancestorId = targetParentId;\n            var visitedParents = {};\n            while (ancestorId && ancestorId != \'ROOT\') {\n                if (ancestorId == id) {\n                    exit 400, \'不能将机构设置为其子孙机构的下级\';\n                }\n                if (visitedParents[ancestorId] == true) {\n                    exit 400, \'上级机构层级存在循环，无法保存\';\n                }\n                visitedParents[ancestorId] = true;\n                var ancestor = db.table("rm_org_t")\n                    .where().eq("id", ancestorId).eq("deleted", 0).selectOne();\n                if (ancestor == null) {\n                    exit 404, \'上级机构链不完整\';\n                }\n                ancestorId = ancestor.parentId;\n            }\n\n            var siblings = db.table("rm_org_t")\n                .where().eq("parentId", targetParentId).eq("deleted", 0).select();\n            var nextNum = siblings.size() + 1;\n            var nextNumStr = nextNum < 10 ? (\'000\' + nextNum) : (nextNum < 100 ? (\'00\' + nextNum) : (nextNum < 1000 ? (\'0\' + nextNum) : (\'\' + nextNum)));\n            newSerialNumber = (parent.serialNumber || \'\') + nextNumStr;\n            newOrgPath = (parent.orgPath || \'\') != \'\' ? (parent.orgPath + \'/\' + data.name) : data.name;\n        } else if (nameChanged) {\n            var currentParent = db.table("rm_org_t")\n                .where().eq("id", targetParentId).eq("deleted", 0).selectOne();\n            newOrgPath = currentParent != null && (currentParent.orgPath || \'\') != \'\'\n                ? currentParent.orgPath + \'/\' + data.name\n                : data.name;\n        }\n\n        if (parentChanged || nameChanged) {\n            var duplicate = db.table("rm_org_t")\n                .where().eq("parentId", targetParentId).eq("name", data.name).eq("deleted", 0).ne("id", id).selectOne();\n            if (duplicate != null) {\n                exit 400, \'上级机构下已存在同名机构: \' + data.name;\n            }\n            data.orgPath = newOrgPath;\n            data.serialNumber = newSerialNumber;\n        }\n\n        // 先持久化当前机构，再重写全部子孙的路径前缀，保证父级修改后树路径保持一致。\n        db.table("rm_org_t").withBlank()\n            .where().eq("id", id)\n            .update(data);\n\n        if ((parentChanged || nameChanged) && oldOrgPath != \'\' && newOrgPath != oldOrgPath) {\n            var descendants = [];\n            var queue = [id];\n            while (queue.size() > 0) {\n                var currentId = queue.remove(0);\n                var children = db.table("rm_org_t")\n                    .where().eq("parentId", currentId).eq("deleted", 0).select();\n                for (child in children) {\n                    descendants.add(child);\n                    queue.add(child.id);\n                }\n            }\n\n            for (descendant in descendants) {\n                var descendantPath = descendant.orgPath || \'\';\n                var descendantData = { updateId: data.updateId, updateTime: now };\n                if (descendantPath.startsWith(oldOrgPath + \'/\')) {\n                    descendantData.orgPath = newOrgPath + descendantPath.substring(oldOrgPath.length());\n                }\n                var descendantSerial = descendant.serialNumber || \'\';\n                if (parentChanged && oldSerialNumber != \'\' && descendantSerial.startsWith(oldSerialNumber)) {\n                    descendantData.serialNumber = newSerialNumber + descendantSerial.substring(oldSerialNumber.length());\n                }\n                db.table("rm_org_t").where().eq("id", descendant.id).update(descendantData);\n            }\n        }\n\n        // 启用/禁用级联：更新该节点及所有子孙节点的status\n        if (body?.status != null && (body.status == 0 || body.status == 1)) {\n            var allIds = [id];\n            var queue = [id];\n\n            while (queue.size() > 0) {\n                var currentId = queue.remove(0);\n                // 从 MySQL 业务表读取当前有效数据。\n                var children = db.table("rm_org_t")\n                    .where().eq("parentId", currentId).eq("deleted", 0)\n                    .select();\n\n                for (child in children) {\n                    allIds.add(child.id);\n                    queue.add(child.id);\n                }\n            }\n\n            // 批量更新所有子孙节点status（自身已在上方更新）\n            if (allIds.size() > 1) {\n                // 从 MySQL 业务表读取当前有效数据。\n                db.table("rm_org_t")\n                    .where().in("id", allIds).ne("id", id)\n                    .update({ status: status, updateId: updateId, updateTime: now });\n            }\n        }\n\n        // 返回当前业务分支的标准结果。\n        return { id: id, parentId: targetParentId, orgPath: newOrgPath, serialNumber: newSerialNumber };\n\n    } else {\n        // ========== 新增逻辑 ==========\n        // 参数校验\n        if (name == null || name == \'\') {\n            // 参数或业务状态不满足要求时立即终止请求。\n            exit 400, \'机构名称不能为空\';\n        }\n\n        // parentId必传\n        parentId = parentId || "ROOT"\n\n        // 同级下同名校验\n        var sameName = db.table("rm_org_t")\n            .where().eq("parentId", parentId).eq("name", name).eq("deleted", 0).selectOne();\n        if (sameName != null) {\n            // 参数或业务状态不满足要求时立即终止请求。\n            exit 400, \'同级下已存在同名机构: \' + name;\n        }\n\n        var newId = IdUtil.getSnowflakeNextIdStr();\n\n        // 若未传sortNum，查同级最大值+1\n        if (!sortNum) {\n            // 从 MySQL 业务表读取当前有效数据。\n            var maxSortRow = db.table("rm_org_t")\n                .where().eq("parentId", parentId != \'\' ? parentId : \'ROOT\').eq("deleted", 0)\n                .orderBy("sortNum", "desc").selectOne();\n            sortNum = maxSortRow != null ? (maxSortRow.sortNum + 1) : 1;\n        }\n\n        // 计算orgPath和serialNumber\n        var orgPath = \'\';\n        var serialNumberNew = \'\';\n\n        // 从 MySQL 业务表读取当前有效数据。\n        var parent = db.table("rm_org_t")\n                .where().eq("id", parentId).eq("deleted", 0).selectOne();\n\n        if (!parent) {\n            // 参数或业务状态不满足要求时立即终止请求。\n            exit 500, \'父级节点不存在\';\n        }\n        \n        var parentPath = parent.orgPath || \'\';\n        orgPath = parentPath != \'\' ? (parentPath + \'/\' + name) : name;\n\n        var parentSerial = parent.serialNumber || \'\';\n        // 从 MySQL 业务表读取当前有效数据。\n        var siblingCount = db.table("rm_org_t")\n            .where().eq("parentId", parentId).eq("deleted", 0).select();\n        var nextNum = siblingCount.size() + 1;\n        // 4位补零格式：0001、0021、0102\n        var nextNumStr = nextNum < 10 ? (\'000\' + nextNum) : (nextNum < 100 ? (\'00\' + nextNum) : (nextNum < 1000 ? (\'0\' + nextNum) : (\'\' + nextNum)));\n        serialNumberNew = parentSerial + nextNumStr;\n\n        data.sortNum = sortNum;\n        data.id = newId;\n        data.parentId = parentId;\n        data.orgPath = orgPath;\n        data.serialNumber = serialNumberNew != \'\' ? serialNumberNew : serialNumber;\n        data.createId = createId;\n        data.createTime = now;\n        data.updateId = createId;\n        data.updateTime = now;\n        data.deleted = 0;\n\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table("rm_org_t").insert(data);\n\n        // 返回当前业务分支的标准结果。\n        return { id: newId };\n    }\n\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'操作失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/02.机构保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c5d287b565064b539aef7bf0587fa07a',NULL,NULL,'{\n  "properties": {},\n  "id": "c5d287b565064b539aef7bf0587fa07a",\n  "script": null,\n  "groupId": "c1736799c6af43359a75e6764601931f",\n  "name": "03.机构移动",\n  "createTime": 1782660716418,\n  "updateTime": 1784437771386,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/move",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "组织机构移动（修改父级部门）接口；使用请求参数 id、newParentId；涉及 rm_org_t 等业务表；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.机构移动\n// 路由：POST /sym/org/move\n// 业务说明：组织机构移动（修改父级部门）接口；使用请求参数 id、newParentId；涉及 rm_org_t 等业务表；执行数据库写入并返回处理结果。\n// 组织机构移动（修改父级部门）接口\n// 路径: /api/org/move\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: id (必填,要移动的机构ID), newParentId (必填,新父级机构ID,ROOT表示移到顶层)\n// 说明: 移动节点到新父级下，同步更新 orgPath/serialNumber，级联更新所有子孙的 orgPath\n\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar id          = body?.id || \'\';\nvar newParentId = body?.newParentId || \'\';\n\n// 参数校验\nif (!id) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'机构ID不能为空\';\n}\nif (!newParentId) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'新父级机构ID不能为空\';\n}\n\ntry {\n    var updateId = me().createId;\n\n    // 1. 校验要移动的机构是否存在\n    var org = db.table("rm_org_t")\n        .where().eq("id", id).eq("deleted", 0).selectOne();\n\n    if (org == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'机构不存在: \' + id;\n    }\n\n    // 2. 不能移到自身\n    if (id == newParentId) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'不能将机构移到自身下\';\n    }\n\n    // 3. 校验新父级是否存在（非ROOT时）\n    var newParent = null;\n    if (newParentId != \'ROOT\') {\n        // 从 MySQL 业务表读取当前有效数据。\n        newParent = db.table("rm_org_t")\n            .where().eq("id", newParentId).eq("deleted", 0).selectOne();\n\n        if (newParent == null) {\n            // 参数或业务状态不满足要求时立即终止请求。\n            exit 404, \'新父级机构不存在: \' + newParentId;\n        }\n\n        // 4. 防止循环：新父级不能是当前节点的子孙\n        var checkId = newParentId;\n        while (checkId && checkId != \'ROOT\') {\n            if (checkId == id) {\n                // 参数或业务状态不满足要求时立即终止请求。\n                exit 400, \'不能将机构移到其子孙节点下\';\n            }\n            // 从 MySQL 业务表读取当前有效数据。\n            var checkNode = db.table("rm_org_t")\n                .where().eq("id", checkId).eq("deleted", 0).selectOne();\n            if (checkNode == null) {\n                break;\n            }\n            checkId = checkNode.parentId;\n        }\n    }\n\n    // 5. 计算新 orgPath 和 serialNumber\n    var newOrgPath = \'\';\n    var newSerialNumber = \'\';\n\n    if (newParentId == \'ROOT\') {\n        newOrgPath = org.name;\n        newSerialNumber = org.serialNumber || \'\';\n    } else {\n        var parentPath = newParent.orgPath || \'\';\n        newOrgPath = parentPath ? (parentPath + \'/\' + org.name) : org.name;\n        // 从 MySQL 业务表读取当前有效数据。\n        var siblings = db.table("rm_org_t")\n            .where().eq("parentId", newParentId).eq("deleted", 0).select();\n        var nextNum = siblings.size() + 1;\n        var nextNumStr = nextNum < 10 ? (\'000\' + nextNum) : (nextNum < 100 ? (\'00\' + nextNum) : (nextNum < 1000 ? (\'0\' + nextNum) : (\'\' + nextNum)));\n        var parentSerial = newParent.serialNumber || \'\';\n        newSerialNumber = parentSerial + nextNumStr;\n    }\n\n    // 6. 更新自身：parentId、orgPath、serialNumber\n    var oldOrgPath = org.orgPath || \'\';\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table("rm_org_t")\n        .where().eq("id", id)\n        .update({\n            parentId: newParentId,\n            orgPath: newOrgPath,\n            serialNumber: newSerialNumber,\n            updateId: updateId,\n            updateTime: now\n        });\n\n    // 7. 级联更新所有子孙的 orgPath（替换旧前缀为新前缀）\n    if (oldOrgPath) {\n        var allDescendants = [];\n        var queue = [id];\n\n        while (queue.size() > 0) {\n            var currentId = queue.remove(0);\n            // 从 MySQL 业务表读取当前有效数据。\n            var children = db.table("rm_org_t")\n                .where().eq("parentId", currentId).eq("deleted", 0)\n                .select();\n\n            for (child in children) {\n                allDescendants.add(child);\n                queue.add(child.id);\n            }\n        }\n\n        for (desc in allDescendants) {\n            var descPath = desc.orgPath || \'\';\n            if (descPath.startsWith(oldOrgPath + \'/\')) {\n                var newDescPath = newOrgPath + descPath.substring(oldOrgPath.length());\n                // 从 MySQL 业务表读取当前有效数据。\n                db.table("rm_org_t")\n                    .where().eq("id", desc.id)\n                    .update({ orgPath: newDescPath, updateId: updateId, updateTime: now });\n            }\n        }\n    }\n\n    // 返回当前业务分支的标准结果。\n    return { id: id, newParentId: newParentId, orgPath: newOrgPath, serialNumber: newSerialNumber };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'移动失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/03.机构移动.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('288235e0cc4047b09933797f75ecfe12',NULL,NULL,'{\n  "properties": {},\n  "id": "288235e0cc4047b09933797f75ecfe12",\n  "script": null,\n  "groupId": "c1736799c6af43359a75e6764601931f",\n  "name": "04.机构排序",\n  "createTime": 1782660716444,\n  "updateTime": 1784437771401,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/sort",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验同级机构标识及当前租户范围，按请求顺序更新机构排序号并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.机构排序\n// 路由：POST /sym/org/sort\n// 业务说明：校验同级机构标识及当前租户范围，按请求顺序更新机构排序号并返回处理结果。\n// 组织机构排序接口\n// 路径: /api/org/sort\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: ids (必填,同级机构ID数组,按新顺序排列,如 ["id3","id1","id2"])\n\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar ids = body?.ids;\n\n// 参数校验\nif (ids == null || ids.size() == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'排序机构ID列表不能为空\';\n}\n\ntry {\n    var updateId = me().createId;\n\n    // 按传入顺序依次设置sortNum（for迭代的是元素，手动维护序号）\n    var sortNum = 0;\n    for (id in ids) {\n        sortNum = sortNum + 1;\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table("rm_org_t")\n            .where().eq("id", id)\n            .update({ sortNum: sortNum, updateId: updateId, updateTime: now });\n    }\n\n    // 返回当前业务分支的标准结果。\n    return { count: ids.size() };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'排序失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/04.机构排序.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d2ca261a63de4aa38188a0ed93c93acb',NULL,NULL,'{\n  "properties": {},\n  "id": "d2ca261a63de4aa38188a0ed93c93acb",\n  "script": null,\n  "groupId": "c1736799c6af43359a75e6764601931f",\n  "name": "05.机构删除",\n  "createTime": 1782660716431,\n  "updateTime": 1787278225032,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "组织机构删除接口（支持批量，并递归删除全部子机构）；使用请求参数 ids、id；涉及 rm_org_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.机构删除\n// 路由：POST /sym/org/delete\n// 业务说明：组织机构删除接口（支持批量，并递归删除全部子机构）；使用请求参数 ids、id；涉及 rm_org_t 等业务表。\n// 组织机构删除接口（支持批量，并递归删除全部子机构）\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\nvar ids = body?.ids;\nif (ids == null || ids.size() == 0) {\n    var singleId = body?.id || \'\';\n    if (singleId != \'\') {\n        ids = [singleId];\n    }\n}\nif (ids == null || ids.size() == 0) {\n    exit 400, \'机构ID不能为空\';\n}\n\ntry {\n    var updateId = me().create_id;\n    var rootIds = [];\n    for (id in ids) {\n        if (id != null && id != \'\' && !rootIds.contains(id)) {\n            rootIds.add(id);\n        }\n    }\n    if (rootIds.size() == 0) {\n        exit 400, \'机构ID不能为空\';\n    }\n    // ROOT 仅是“全部机构”的系统根节点，不是可删除的业务机构。\n    if (rootIds.contains(\'ROOT\')) {\n        exit 400, \'全部机构为系统根节点，不能删除\';\n    }\n\n    var existList = db.table(\'rm_org_t\').where().in(\'id\', rootIds).eq(\'deleted\', 0).select();\n    var existIds = [];\n    for (item in existList) {\n        existIds.add(item.id);\n    }\n    var notFound = [];\n    for (id in rootIds) {\n        if (!existIds.contains(id)) {\n            notFound.add(id);\n        }\n    }\n    if (notFound.size() > 0) {\n        exit 404, \'机构不存在或已删除: \' + notFound.join(\',\');\n    }\n\n    // 从待删机构向下遍历；visited 同时避免批量选择父子节点或异常循环造成重复处理。\n    var deleteIds = [];\n    var visited = {};\n    var queue = [];\n    for (id in rootIds) {\n        queue.add(id);\n    }\n    while (queue.size() > 0) {\n        var currentId = queue.remove(0);\n        if (visited[currentId] == true) {\n            continue;\n        }\n        visited[currentId] = true;\n        deleteIds.add(currentId);\n        var children = db.table(\'rm_org_t\').where().eq(\'parentId\', currentId).eq(\'deleted\', 0).select();\n        for (child in children) {\n            queue.add(child.id);\n        }\n    }\n\n    db.table(\'rm_org_t\').where().in(\'id\', deleteIds).update({\n        deleted: 1,\n        updateId: updateId,\n        updateTime: now\n    });\n    return {\n        ids: rootIds,\n        count: deleteIds.size(),\n        deleted: true,\n        recursive: true\n    };\n} catch (e) {\n    exit 500, \'删除失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/05.机构删除.ms');
