                   "required": false,\n                    "dataType": "Object",\n                    "type": null,\n                    "defaultValue": null,\n                    "validateType": "",\n                    "error": "",\n                    "expression": "",\n                    "children": [\n                      {\n                        "name": "id",\n                        "value": "2026504991392792578",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "name",\n                        "value": "情指中心",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "parentId",\n                        "value": "2026504929417756673",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "nature",\n                        "value": "2",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "status",\n                        "value": "0",\n                        "description": "",\n                        "required": false,\n                        "dataType": "Integer",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "serialNumber",\n                        "value": "000600010001",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "orgPath",\n                        "value": "福建省公安/省厅/情指中心",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n           