n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "deptCode",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "nationalCode",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "nationalName",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "regionCode",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "nodeType",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "originTypes",\n                        "value": "null",\n                        "description": "",\n                        "required": false,\n                        "dataType": "Object",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "originIds",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "label",\n                        "value": "情指中心",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "leaderOrgId",\n                        "value": "null",\n                        "description": "",\n                        "required": false,\n                        "dataType": "Object",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "value",\n                        "value": "2026504991392792578",\n                        "description": "",\n                        "required": false,\n                        "dataType": "String",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      },\n                      {\n                        "name": "children",\n                        "value": "",\n                        "description": "",\n                        "required": false,\n                        "dataType": "Array",\n                        "type": null,\n                        "defaultValue": null,\n                        "validateType": "",\n                        "error": "",\n                        "expression": "",\n                        "children": []\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  }\n}\n================================\n// 接口：10.组织机构树查询\n// 路由：POST /sym/org/getOrgTree\n// 业务说明：机构树查询：仅返回当前根机构下的有效子树；不包含虚拟“全部机构”节点；使用请求参数 parentId；涉及 rm_org_t 等业务表。\n// 机构树查询：仅返回当前根机构下的有效子树；不包含虚拟“全部机构”节点。\nimport "@post:/sym/user/me" as me\n\nvar rootId = body?.parentId || orgRootId || me().orgRootId || \'ROOT\';\nvar rows = db.table(\'rm_org_t\').where().eq(\'deleted\', 0).orderBy(\'sort_num\').select();\nvar nodes = {};\nfor (row in rows) {\n    var node = {};\n    node.putAll(row);\n    node.value = node.id;\n    node.label = node.name;\n    node.children = [];\n    nodes[node.id] = node;\n}\n\nvar roots = [];\nfor (nodeId in nodes.keySet()) {\n    var node = nodes[nodeId];\n    if (node.parentId == rootId) {\n        roots.add(node);\n    } else if (nodes[node.parentId] != null) {\n        nodes[node.parentId].children.add(node);\n    }\n}\nreturn roots;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/04.机构管理/10.组织机构树查询.ms');
