INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('57d488fe51404e37afe8528c348c87ee',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "57d488fe51404e37afe8528c348c87ee",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "01.菜单保存修改",\r\n  "createTime" : 1782660725684,\r\n  "updateTime" : 1791088093611,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/saveOrUpdate",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"resourceType\\": 0,\\n    \\"urlType\\": 0,\\n    \\"openType\\": 0\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "菜单保存修改（POST /sym/menu/saveOrUpdate）。支持新增、编辑和菜单层级移动；移动时校验循环引用并同步整棵子树的 top_id；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 rm_menu_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：01.菜单保存修改\n// 路由：POST /sym/menu/saveOrUpdate\n// 业务说明：菜单保存修改（POST /sym/menu/saveOrUpdate）。支持新增、编辑和菜单层级移动；移动时校验循环引用并同步整棵子树的 top_id；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 rm_menu_t 等业务表。\nimport tenantAccounts\nimport cn.hutool.core.util.IdUtil\nimport "@post:/sym/user/me" as me\nimport cn.dev33.satoken.stp.StpUtil\n\n// 菜单资源保存/更新接口。\n// 菜单层级调整时同步当前节点及全部后代的 top_id，防止导航树与权限树失配。\n\n\nvar now = new Date();\nvar id           = body?.id || \'\';\nvar name         = body?.name || \'\';\nvar parentId     = body?.parentId || \'ROOT\';\nvar integerValue = (value, defaultValue) => {\n    if (value == null || (value + \'\').trim() == \'\') {\n        return defaultValue;\n    }\n    return value.asInt();\n};\nvar resourceType = integerValue(body?.resourceType, 0);\nvar sno          = body?.sno || \'\';\nvar url          = body?.url || \'\';\nvar urlType      = integerValue(body?.urlType, 0);\nvar staticIcon   = body?.staticIcon || \'\';\nvar dynamicImg   = body?.dynamicImg || \'\';\nvar openType     = integerValue(body?.openType, 0);\nvar code         = body?.code || \'\';\nvar appId        = body?.appId || tenantAccounts.session().get("appId");\nvar sortNum      = body?.sortNum == null || (body.sortNum + \'\').trim() == \'\' ? null : body.sortNum;\nvar status       = integerValue(body?.status, 0);\nvar dataScopeEnabled = integerValue(body?.dataScopeEnabled, 0) == 1 ? 1 : 0;\n\nif (!name) {\n    exit 400, \'菜单名称不能为空\';\n}\n\ntry {\n    var updateId = me().createId;\n    var normalizedParentId = parentId ? parentId : \'ROOT\';\n    var data = {\n        name: name,\n        parentId: normalizedParentId,\n        resourceType: resourceType.asInt(),\n        sno: sno,\n        url: url,\n        urlType: urlType,\n        staticIcon: staticIcon,\n        dynamicImg: dynamicImg,\n        openType: openType,\n        code: code,\n        dataScopeEnabled: resourceType == 0 ? dataScopeEnabled : 0,\n        appId: appId\n    };\n\n    if (id) {\n        var exist = db.table("rm_menu_t")\n            .where().eq("id", id).eq("deleted", 0).selectOne();\n        if (exist == null) {\n            exit 404, \'记录不存在: \' + id;\n        }\n        if (normalizedParentId == id) {\n            exit 400, \'菜单不能设置自身为父级\';\n        }\n\n        var parentRecord = null;\n        var newTopId = id;\n        if (normalizedParentId != \'ROOT\') {\n            parentRecord = db.table("rm_menu_t")\n                .where().eq("id", normalizedParentId).eq("deleted", 0).selectOne();\n            if (parentRecord == null) {\n                exit 400, \'目标父级菜单不存在\';\n            }\n            if (parentRecord.resourceType == 1) {\n                exit 400, \'按钮节点不能作为父级菜单\';\n            }\n\n            // 沿目标父级向上检查，禁止把菜单移动到自己的后代节点下。\n            var cursor = parentRecord;\n            while (cursor != null && cursor.id != null) {\n                if (cursor.id == id) {\n                    exit 400, \'不能将菜单移动到自己的下级菜单中\';\n                }\n                if (!cursor.parentId || cursor.parentId == \'ROOT\') {\n                    cursor = null;\n                } else {\n                    cursor = db.table("rm_menu_t")\n                        .where().eq("id", cursor.parentId).eq("deleted", 0).selectOne();\n                }\n            }\n            newTopId = parentRecord.topId || parentRecord.id;\n        }\n\n        data.topId = newTopId;\n        if (sortNum != null) {\n            data.sortNum = sortNum.asInt();\n        }\n        data.updateId = updateId;\n        data.updateTime = now;\n\n        db.table("rm_menu_t").withBlank()\n            .where().eq("id", id)\n            .update(data);\n\n        // 父级变化后，所有后代必须继承新的顶级菜单 ID。\n        if (newTopId != exist.topId || normalizedParentId != exist.parentId) {\n            var queue = [id];\n            while (queue.size() > 0) {\n                var currentId = queue.remove(0);\n                var children = db.table("rm_menu_t")\n                    .where().eq("parent_id", currentId).eq("deleted", 0).select();\n                for (child in children) {\n                    db.table("rm_menu_t")\n                        .where().eq("id", child.id)\n                        .update({ topId: newTopId, updateId: updateId, updateTime: now });\n                    queue.add(child.id);\n                }\n            }\n        }\n\n        return {\n            id: id,\n            parentId: normalizedParentId,\n            topId: newTopId,\n            moved: normalizedParentId != exist.parentId\n        };\n    }\n\n    var newId = IdUtil.getSnowflakeNextIdStr();\n    if (!sortNum) {\n        var maxSortRow = db.table("rm_menu_t")\n            .where().eq("parent_id", normalizedParentId).eq("deleted", 0)\n            .orderBy("sort_num", "desc").selectOne();\n        sortNum = maxSortRow != null ? (maxSortRow.sortNum + 1) : 1;\n    }\n\n    var newTopId = newId;\n    if (normalizedParentId != \'ROOT\') {\n        var parentRecord = db.table("rm_menu_t")\n            .where().eq("id", normalizedParentId).eq("deleted", 0).selectOne();\n        if (parentRecord == null) {\n            exit 400, \'目标父级菜单不存在\';\n        }\n        if (parentRecord.resourceType == 1) {\n            exit 400, \'按钮节点不能作为父级菜单\';\n        }\n        newTopId = parentRecord.topId || parentRecord.id;\n    }\n\n    data.id = newId;\n    data.topId = newTopId;\n    data.sortNum = sortNum;\n    data.createId = updateId;\n    data.createTime = now;\n    data.updateId = updateId;\n    data.updateTime = now;\n    data.deleted = 0;\n    data.status = status;\n    db.table("rm_menu_t").insert(data);\n    return { id: newId, parentId: normalizedParentId, topId: newTopId };\n} catch(e) {\n    exit 500, \'操作失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/01.菜单保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ad79907ebe4c4acca241d7e740e9e91b',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "ad79907ebe4c4acca241d7e740e9e91b",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "02.菜单状态修改",\r\n  "createTime" : 1782660726068,\r\n  "updateTime" : 1791088093673,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/toggleStatus",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n    \\"status\\": 2\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "菜单资源启用/禁用接口（级联）；使用请求参数 id、status、deep；涉及 rm_menu_t 等业务表；执行数据库写入并返回处理结果。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：02.菜单状态修改\n// 路由：POST /sym/menu/toggleStatus\n// 业务说明：菜单资源启用/禁用接口（级联）；使用请求参数 id、status、deep；涉及 rm_menu_t 等业务表；执行数据库写入并返回处理结果。\n// 菜单资源启用/禁用接口（级联）\n// 路径: /sym/menu/toggleStatus\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: id (必填,菜单ID), status (必填,0启用/1禁用)\n// 说明: 级联更新该节点的status (或及所有子孙菜单)\n\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar id     = body?.id || \'\';\nvar status = body?.status ? body.status : 0;\nvar deep   = body?.deep // 是否操作其下所有子孙菜单\n\n// 参数校验\nif (!id) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'菜单ID不能为空\';\n}\n\nif (status != 0 && status != 1) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'status值无效，0=启用 1=禁用\';\n}\n\ntry {\n    var updateId = me().createId;\n\n    // 校验菜单是否存在\n    var exist = db.table("rm_menu_t")\n        .where().eq("id", id).eq("deleted", 0).selectOne();\n\n    if (exist == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'菜单不存在: \' + id;\n    }\n\n    // BFS 收集所有后代ID（自身+子孙）\n    var allIds = [id];\n    var queue = [id];\n\n    if (deep){\n        while (queue.size() > 0) {\n            var currentId = queue.remove(0);\n            // 从 MySQL 业务表读取当前有效数据。\n            var children = db.table("rm_menu_t")\n                .where().eq("parent_id", currentId).eq("deleted", 0)\n                .select();\n\n            for (child in children) {\n                allIds.add(child.id);\n                queue.add(child.id);\n            }\n        }\n    }\n\n    // 批量更新自身及所有子孙status\n    db.table("rm_menu_t")\n        .where().in("id", allIds)\n        .update({ status: status, updateId: updateId, updateTime: now });\n\n    // 返回当前业务分支的标准结果。\n    return { id: id, status: status, affectedCount: allIds.size() };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'操作失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/02.菜单状态修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('daaca32a76bd4787ba35d3d1ef4f871f',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "daaca32a76bd4787ba35d3d1ef4f871f",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "03.菜单排序",\r\n  "createTime" : 1782660726302,\r\n  "updateTime" : 1791088093750,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/sort",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "校验同级菜单标识及当前租户范围，按请求顺序更新菜单资源排序号并返回处理结果。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：03.菜单排序\n// 路由：POST /sym/menu/sort\n// 业务说明：校验同级菜单标识及当前租户范围，按请求顺序更新菜单资源排序号并返回处理结果。\n// 菜单资源排序接口\n// 路径: /sym/menu/sort\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: ids (必填,同级菜单ID数组,按新顺序排列,如 ["id3","id1","id2"])\n\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar ids = body?.ids;\n\n// 参数校验\nif (!ids || ids.size() == 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'排序菜单ID列表不能为空\';\n}\n\ntry {\n    var updateId = me().createId;\n\n    // 按传入顺序依次设置sortNum（for迭代的是元素，手动维护序号）\n    var sortNum = 0;\n    for (id in ids) {\n        sortNum = sortNum + 1;\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table("rm_menu_t")\n            .where().eq("id", id)\n            .update({ sortNum: sortNum, updateId: updateId, updateTime: now });\n    }\n\n    // 返回当前业务分支的标准结果。\n    return { count: ids.size() };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'排序失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/03.菜单排序.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c1e127f305fd44ac827bab7bb2c65550',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "c1e127f305fd44ac827bab7bb2c65550",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "04.菜单删除",\r\n  "createTime" : 1782660725883,\r\n  "updateTime" : 1791088093824,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/delete",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "说明: 软删除，deleted=1；存在子菜单时拒绝删除；使用请求参数 id；涉及 rm_menu_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：04.菜单删除\n// 路由：POST /sym/menu/delete\n// 业务说明：说明: 软删除，deleted=1；存在子菜单时拒绝删除；使用请求参数 id；涉及 rm_menu_t 等业务表。\n// 菜单资源删除接口（软删除）\n// 路径: /sym/menu/delete\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: id (必填,菜单ID)\n// 说明: 软删除，deleted=1；存在子菜单时拒绝删除\n\nimport "@post:/sym/user/me" as me\n\nvar now = new Date();\n\n// 获取入参\nvar id = body?.id || \'\';\n\n// 参数校验\nif (!id) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'菜单ID不能为空\';\n}\n\ntry {\n    // 检查记录是否存在且未删除\n    var exist = db.table("rm_menu_t")\n        .where().eq("id", id).eq("deleted", 0).selectOne();\n\n    if (exist == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'菜单不存在或已删除: \' + id;\n    }\n\n    // 检查是否存在未删除的子菜单\n    var children = db.table("rm_menu_t")\n        .where().eq("parent_id", id).eq("deleted", 0).select();\n\n    if (children.size() > 0) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 400, \'该菜单下存在\' + children.size() + \'个子菜单，请先删除子菜单\';\n    }\n\n    // 执行软删除\n    var updateId = me().createId;\n    // 从 MySQL 业务表读取当前有效数据。\n    db.table("rm_menu_t")\n        .where().eq("id", id)\n        .update({ deleted: 1, updateId: updateId, updateTime: now });\n\n    // 返回当前业务分支的标准结果。\n    return { id: id, deleted: true };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'删除失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/04.菜单删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1dc43be6fbe648ea979c59fa37da7fb8',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "1dc43be6fbe648ea979c59fa37da7fb8",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "05.菜单路由查询",\r\n  "createTime" : 1782660715939,\r\n  "updateTime" : 1791089851203,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/routes",\r\n  "method" : "GET",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : "{\\n    \\"code\\": 0,\\n    \\"msg\\": \\"success\\",\\n    \\"success\\": true,\\n    \\"data\\": [\\n        {\\n            \\"path\\": \\"/register\\",\\n            \\"name\\": \\"register\\",\\n            \\"component\\": \\"Layout\\",\\n            \\"meta\\": {\\n                \\"title\\": \\"数据盘点\\"\\n            },\\n            \\"children\\": [\\n                {\\n                    \\"path\\": \\"__group_数据来源盘点__\\",\\n                    \\"meta\\": {\\n                        \\"type\\": \\"group\\",\\n                        \\"title\\": \\"数据来源盘点\\"\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/register-yyxt\\",\\n                    \\"name\\": \\"register-register-yyxt\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"业务系统\\",\\n                        \\"icon\\": \\"menu-app\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/list\\",\\n                            \\"name\\": \\"register-register-yyxt-list\\",\\n                            \\"componentName\\": \\"my-app\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/detail\\",\\n                            \\"name\\": \\"register-register-yyxt-detail\\",\\n                            \\"componentName\\": \\"detail-page\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"详情\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                },\\n                {\\n                    \\"path\\": \\"/register-sjkb\\",\\n                    \\"name\\": \\"register-register-sjkb\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据探查\\",\\n                        \\"icon\\": \\"menu-find\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/list\\",\\n                            \\"name\\": \\"register-register-sjkb-list\\",\\n                            \\"componentName\\": \\"my-db\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/detail\\",\\n                            \\"name\\": \\"register-register-sjkb-detail\\",\\n                            \\"componentName\\": \\"detail-page\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"详情\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                },\\n                {\\n                    \\"path\\": \\"__group_数据目录登记__\\",\\n                    \\"meta\\": {\\n                        \\"type\\": \\"group\\",\\n                        \\"title\\": \\"数据目录登记\\"\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/register-sjml\\",\\n                    \\"name\\": \\"register-register-sjml\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据目录\\",\\n                        \\"icon\\": \\"menu-cata\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/list\\",\\n                            \\"name\\": \\"register-register-sjml-list\\",\\n                            \\"componentName\\": \\"my-catalog\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/detail\\",\\n                            \\"name\\": \\"register-register-sjml-detail\\",\\n                            \\"componentName\\": \\"detail-page\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"详情\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                },\\n                {\\n                    \\"path\\": \\"/register-sjdr\\",\\n                    \\"name\\": \\"register-register-sjdr\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据导入\\",\\n                        \\"icon\\": \\"menu-cata\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/list\\",\\n                            \\"name\\": \\"register-register-sjdr-list\\",\\n                            \\"componentName\\": \\"my-fileCatalog\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/detail\\",\\n                            \\"name\\": \\"register-register-sjdr-detail\\",\\n                            \\"componentName\\": \\"detail-page\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"详情\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                }\\n            ]\\n        },\\n        {\\n            \\"path\\": \\"/jr\\",\\n            \\"name\\": \\"jr\\",\\n            \\"component\\": \\"Layout\\",\\n            \\"meta\\": {\\n                \\"title\\": \\"数据接入\\"\\n            },\\n            \\"children\\": [\\n                {\\n                    \\"path\\": \\"__group_接入任务创建__\\",\\n                    \\"meta\\": {\\n                        \\"type\\": \\"group\\",\\n                        \\"title\\": \\"接入任务创建\\"\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/data-convergence\\",\\n                    \\"name\\": \\"jr-data-convergence\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据汇聚\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/list\\",\\n                            \\"name\\": \\"jr-data-convergence-list\\",\\n                            \\"componentName\\": \\"data-convergence\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/detail\\",\\n                            \\"name\\": \\"jr-data-convergence-detail\\",\\n                            \\"componentName\\": \\"detail-page\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"详情\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                },\\n                {\\n                    \\"path\\": \\"__group_数据接入保障__\\",\\n                    \\"meta\\": {\\n                        \\"type\\": \\"group\\",\\n                        \\"title\\": \\"数据接入保障\\"\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/data-access\\",\\n                    \\"name\\": \\"jr-data-access\\",\\n                    \\"componentName\\": \\"data-access\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据接入\\",\\n                        \\"hidden\\": true\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/access-monitoring\\",\\n                    \\"name\\": \\"jr-access-monitoring\\",\\n                    \\"componentName\\": \\"access-monitoring\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"任务管理\\",\\n                        \\"icon\\": \\"menu-monitor\\"\\n                    }\\n                },\\n                {\\n                    \\"path\\": \\"/data-dz\\",\\n                    \\"name\\": \\"jr-data-dz\\",\\n                    \\"meta\\": {\\n                        \\"title\\": \\"数据对账\\",\\n                        \\"icon\\": \\"menu-book\\"\\n                    },\\n                    \\"children\\": [\\n                        {\\n                            \\"path\\": \\"/data-dz-list\\",\\n                            \\"name\\": \\"jr-data-dz-data-dz-list\\",\\n                            \\"componentName\\": \\"data-dz\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"数据对账列表\\",\\n                                \\"hidden\\": true\\n                            }\\n                        },\\n                        {\\n                            \\"path\\": \\"/data-dz-dj\\",\\n                            \\"name\\": \\"jr-data-dz-data-dz-dj\\",\\n                            \\"componentName\\": \\"data-dz-dj\\",\\n                            \\"meta\\": {\\n                                \\"title\\": \\"新增对账策略\\",\\n                                \\"hidden\\": true\\n                            }\\n                        }\\n                    ]\\n                }\\n            ]\\n        }\\n    ]\\n}",\r\n  "description" : "当前用户菜单入口（GET /sym/menu）；读取或计算后返回业务结果。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：05.菜单路由查询\n// 路由：GET /sym/menu/routes\n// 业务说明：当前用户菜单入口（GET /sym/menu）；读取或计算后返回业务结果。\n/*\n * 当前用户菜单入口（GET /sym/menu）。\n *\n * 数据来源：复用 /sym/auth/userMenu 返回的权限菜单树。\n * 门户整理：仅移除已下线的个人工作台；其余入口由租户权限菜单配置决定，\n * 保持顶部导航与权限管理页一致。\n */\nimport "@post:/sym/auth/userMenu" as userMenu;\n\n// 个人中心保留资源申请，并把默认入口定位到资源申请。\nvar stripUnusedPersonalWorkbench = (nodes) => {\n    if (nodes == null) {\n        return [];\n    }\n    return nodes.filter(item => {\n        var path = item?.path == null ? "" : item.path + "";\n        var name = item?.name == null ? "" : item.name + "";\n        var componentName = item?.componentName == null ? "" : item.componentName + "";\n        return path != "/my-workplace" &&\n            name != "workplace-my-workplace" &&\n            componentName != "my-workplace";\n    }).map(item => {\n        if (item?.children != null) {\n            item.children = stripUnusedPersonalWorkbench(item.children);\n        }\n        if ((item?.path + "") == "/workplace") {\n            item.redirect = "/workplace/my-apply/list";\n        }\n        return item;\n    });\n};\n\nreturn stripUnusedPersonalWorkbench(userMenu());\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/05.菜单路由查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3b9d8682329c4311a28d5a343d19b91e',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "3b9d8682329c4311a28d5a343d19b91e",\r\n  "script" : null,\r\n  "groupId" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "06.菜单列表",\r\n  "createTime" : 1782660716338,\r\n  "updateTime" : 1791088093993,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/all",\r\n  "method" : "POST",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{\\n}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "权限管理默认查询当前租户全部菜单；明确传入 appId 时才按应用筛选；涉及 rm_menu_t 等业务表。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：06.菜单列表\n// 路由：POST /sym/menu/all\n// 业务说明：权限管理默认查询当前租户全部菜单；明确传入 appId 时才按应用筛选；涉及 rm_menu_t 等业务表。\nimport tenantAccounts\nimport log\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.NumberUtil\n\n\ntry{\n  tenantAccounts.session();\n}catch(e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";  \n}\n\n//优先读取body中的参数\n // 权限管理默认查询当前租户全部菜单；明确传入 appId 时才按应用筛选。\nvar requestedAppId = body?.appId;\n\n//先读取数据库，后面考虑读取缓存\nvar menuQuery = db.table("rm_menu_t").where().eq(\'deleted\', 0)\nif (requestedAppId != null && (requestedAppId + \'\').trim() != \'\') {\n    menuQuery = menuQuery.eq("app_id", requestedAppId)\n}\nvar menuList = menuQuery.orderBy(\'sortNum\').select()\n             \n// 返回当前业务分支的标准结果。\nreturn menuList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/06.菜单列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b3f641e93f574cc5a88009f84e695ab1',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "b3f641e93f574cc5a88009f84e695ab1",\r\n  "name" : "05.菜单管理",\r\n  "type" : "api",\r\n  "parentId" : "9a18bf0b6a994f5aa56aa775f3de9f3d",\r\n  "path" : "/menu",\r\n  "createTime" : 1781960047139,\r\n  "updateTime" : 1784437771090,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/05.菜单管理/group.json');
