INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c6ccbc4af86e4b599db7bf9cac8d774c',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "c6ccbc4af86e4b599db7bf9cac8d774c",\n  "script": null,\n  "groupId": "882093f918054984b1504ea77e58d3af",\n  "name": "01.用户菜单查询",\n  "createTime": 1782660716480,\n  "updateTime": 1784437771407,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/userMenu",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "获取当前用户菜单接口（基于角色权限，返回Vue路由树结构）；使用请求参数 appId；涉及 rm_user_role_rela_t、rm_role_t、rm_role_menu_rela_t、rm_menu_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.用户菜单查询\n// 路由：POST /sym/auth/userMenu\n// 业务说明：获取当前用户菜单接口（基于角色权限，返回Vue路由树结构）；使用请求参数 appId；涉及 rm_user_role_rela_t、rm_role_t、rm_role_menu_rela_t、rm_menu_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport "@post:/sym/user/me" as me\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.StrUtil\n\n\n// 获取当前用户菜单接口（基于角色权限，返回Vue路由树结构）\n// 路径: /sym/menu/userMenu\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: appId (可选,按应用过滤)\n// 说明: 根据当前用户→角色→菜单资源，构建Vue路由树\n//       resource_type: 0=菜单 1=按钮(跳过) 2=分组菜单\n//       open_type: 0=内嵌 1=iframe 2=新页面\n\n\n// 获取当前用户ID\nvar userId = me().id;\n// 解析请求体并为可选参数设置默认值。\nvar appId = body?.appId || tenantAccounts.session().get("appId");\n\ntry {\n    // 1. 查询用户所属角色\n    var userRoles = db.table("rm_user_role_rela_t")\n        .where().eq("user_id", userId)\n        .select();\n\n    if (!userRoles || userRoles.size() == 0) {\n        // 返回当前业务分支的标准结果。\n        return [];\n    }\n\n    var roleIds = [];\n    for (row in userRoles) {\n        roleIds.add(row.roleId);\n    }\n\n    if(tenantAccounts.isLocal(tenantRuntime.id())) {\n      var activeRoles=db.table(\'rm_role_t\').where().in(\'id\',roleIds).eq(\'app_id\',appId).eq(\'deleted\',0).eq(\'status\',0).select();\n      roleIds=activeRoles.map(r=>r.id);if(roleIds.size()==0) {return [];}\n    }\n    // 2. 查询角色关联的菜单资源ID\n    var roleResources = db.table("rm_role_menu_rela_t")\n        .where().in("role_id", roleIds)\n        .select();\n\n    if (!roleResources || roleResources.size() == 0) {\n        // 返回当前业务分支的标准结果。\n        return [];\n    }\n\n    var resourceIds = [];\n    for (row in roleResources) {\n        resourceIds.add(row.appResourceId);\n    }\n\n    // 3. 查询菜单资源详情（只取未删除的菜单和分组，排除按钮，status=1的标记hidden）\n    var query = db.table("rm_menu_t")\n        .where().in("id", resourceIds)\n        .eq("deleted", 0)\n        .ne("resource_type", 1);\n\n    if (appId) {\n        query = query.eq("app_id", appId);\n    }\n\n    var resources = query.orderBy("sort_num", "asc").select();\n\n    // 4. 构建Vue路由树\n    var itemMap = {};\n    for (res in resources) {\n        itemMap[res.id] = res;\n    }\n\n    // 构建每个节点的完整路径（向上递归拼接url）\n    var fullPathMap = {};\n    var getFullPath = (resId) => {\n        if (fullPathMap[resId]) { return fullPathMap[resId]; }\n        var res = itemMap[resId];\n        if (!res) { return ""; }\n        var url = res.url || "";\n        if (res.parentId == \'ROOT\' || !itemMap[res.parentId]) {\n            fullPathMap[resId] = url;\n            // 返回当前业务分支的标准结果。\n            return url;\n        }\n        var parentPath = getFullPath(res.parentId);\n        fullPathMap[resId] = parentPath + url;\n        // 返回当前业务分支的标准结果。\n        return fullPathMap[resId];\n    };\n    for (res in resources) {\n        getFullPath(res.id);\n    }\n\n    // 将单条资源转为Vue路由节点\n    var buildNode = (res) => {\n        var node = {};\n        if (res.resourceType == 2) {\n            var groupKey = res.sno ? res.sno : res.name;\n            node.path = "__group_" + groupKey + "__";\n            node.meta = { type: "group", title: res.name };\n            // 返回当前业务分支的标准结果。\n            return node;\n        }\n\n        node.path = res.url ? res.url : "";\n\n        // name: 完整路径去掉前导/，/替换为-\n        var fullPath = fullPathMap[res.id] || "";\n        if (res.url && res.url.startsWith("http")) {\n            // 外部链接保持原样\n            node.name = res.code ? res.code : res.sno;\n        } else {\n            var nameStr = fullPath.startsWith("/") ? fullPath.substring(1) : fullPath;\n            node.name = nameStr.replace(/\\//g, "-");\n        }\n\n        // sno决定component/componentName：inner_开头用componentName，否则用component，空则不设置\n        if (res.sno) {\n            if (res.sno.startsWith("inner_")) {\n                node.component = res.sno.substring(6);\n            } else {\n                node.componentName = res.sno;\n            }\n        }\n\n        node.meta = { title: res.name };\n        if (res.status == 1) {\n            node.meta.hidden = true;\n        }\n\n        // staticIcon → meta.icon\n        if (res.staticIcon) {\n            node.meta.icon = res.staticIcon;\n        }\n\n        // 外部链接\n        if (res.resourceType == 3 || StrUtil.startWith(res.url,\'http\')) {\n            if (res.openType == 0){\n                node.meta.target = "_self"\n            }\n            // open_type: 1=iframe打开\n            if (res.openType == 1) {\n                node.meta.openMode = "iframe";\n            }\n            // open_type: 2=新页面\n            if (res.openType == 2){\n                node.meta.target = "_blank"\n            }\n        }\n\n        // 返回当前业务分支的标准结果。\n        return node;\n    };\n\n    // 递归构建子树\n    var buildChildren = (parentId) => {\n        var children = [];\n        for (res in resources) {\n            if (res.parentId == parentId) {\n                var childNode = buildNode(res);\n\n                // 递归查找子节点的children\n                var subChildren = buildChildren(res.id);\n                if (subChildren && subChildren.size() > 0) {\n                    childNode.children = subChildren;\n                }\n\n                // 有子节点且非分组菜单、非外部链接，设component=Layout\n                //     && res.resourceType != 2\n                //     && (!res.url || !res.url.startsWith("http"))) {\n                //     } else {\n                //     }\n                // }\n\n                children.add(childNode);\n            }\n        }\n        // 返回当前业务分支的标准结果。\n        return children;\n    };\n\n    // 顶层节点：parentId=ROOT 或 parentId不在资源列表中\n    var tree = [];\n    for (res in resources) {\n        var isTopLevel = res.parentId == \'ROOT\' || !itemMap[res.parentId];\n        if (isTopLevel) {\n            var rootNode = buildNode(res);\n\n            var rootChildren = buildChildren(res.id);\n            if (rootChildren && rootChildren.size() > 0) {\n                rootNode.children = rootChildren;\n            }\n\n            // 有子节点的顶层菜单，设component=Layout\n            //     && res.resourceType != 2\n            //     && res.sno\n            //     && (!res.url || !res.url.startsWith("http"))) {\n            //     } else {\n            //     }\n            // }\n\n            tree.add(rootNode);\n        }\n    }\n\n    // 返回当前业务分支的标准结果。\n    return tree;\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'获取用户菜单失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/06.权限管理/01.用户菜单查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7cca7dbb12174db680af8e5b81aeca5d',NULL,NULL,'{\n  "properties": {},\n  "id": "7cca7dbb12174db680af8e5b81aeca5d",\n  "script": null,\n  "groupId": "882093f918054984b1504ea77e58d3af",\n  "name": "02.角色菜单查询",\n  "createTime": 1782660716505,\n  "updateTime": 1784437771408,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getRoleResource",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "返回: 该角色已关联的菜单资源ID列表；使用请求参数 roleId；涉及 rm_role_menu_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.角色菜单查询\n// 路由：POST /sym/auth/getRoleResource\n// 业务说明：返回: 该角色已关联的菜单资源ID列表；使用请求参数 roleId；涉及 rm_role_menu_rela_t 等业务表。\n// 获取角色菜单关联关系接口\n// 路径: /sym/auth/getRoleResource\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: roleId (必填,角色ID)\n// 返回: 该角色已关联的菜单资源ID列表\n\nvar roleId = body?.roleId || \'\';\n\nif (!roleId) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'角色ID不能为空\';\n}\n\ntry {\n    // 从 MySQL 业务表读取当前有效数据。\n    var list = db.table("rm_role_menu_rela_t")\n        .where().eq("role_id", roleId)\n        .select();\n\n    var resourceIds = [];\n    for (row in list) {\n        resourceIds.add(row.appResourceId);\n    }\n\n    // 返回当前业务分支的标准结果。\n    return { roleId: roleId, resourceIds: resourceIds };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'查询角色菜单关联失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/06.权限管理/02.角色菜单查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e4445190b9a543c89d23b3a6adacffc5',NULL,NULL,'{\n  "properties": {\n    "gaLocalRoleAdapter": "v1"\n  },\n  "id": "e4445190b9a543c89d23b3a6adacffc5",\n  "script": null,\n  "groupId": "882093f918054984b1504ea77e58d3af",\n  "name": "03.角色菜单保存",\n  "createTime": 1782660716468,\n  "updateTime": 1784437771404,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveRoleResource",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "说明: 先删后增——删除该角色所有旧关联，再批量插入新关联；使用请求参数 roleId、resourceIds；涉及 rm_role_t、rm_role_menu_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.角色菜单保存\n// 路由：POST /sym/auth/saveRoleResource\n// 业务说明：说明: 先删后增——删除该角色所有旧关联，再批量插入新关联；使用请求参数 roleId、resourceIds；涉及 rm_role_t、rm_role_menu_rela_t 等业务表。\nimport tenantAccounts\nimport tenantRuntime\nimport \'@/tenant-account/resources\' as localResources\nimport cn.hutool.core.util.IdUtil\nimport "@post:/sym/user/me" as me\nif(tenantAccounts.isLocal(tenantRuntime.id())) {return localResources(body||{});}\n\n// 角色菜单关联关系保存接口\n// 路径: /sym/sso/roleResource\n// 方法: POST\n// 数据源: sso (192.168.175.86:3306)\n// 参数: roleId (必填,角色ID), resourceIds (可选,菜单资源ID数组,传空数组表示清空所有关联)\n// 说明: 先删后增——删除该角色所有旧关联，再批量插入新关联\n\n\nvar now = new Date();\n\n// 获取入参\nvar roleId      = body?.roleId || \'\';\nvar resourceIds = body?.resourceIds;\n\n// 参数校验\nif (!roleId) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'角色ID不能为空\';\n}\n\ntry {\n    var updateId = me().createId;\n\n    // 检查角色是否存在\n    var role = db.table("rm_role_t")\n        .where().eq("id", roleId).eq("deleted", 0).selectOne();\n\n    if (role == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 404, \'角色不存在: \' + roleId;\n    }\n\n    // 先删除该角色所有旧关联\n    db.table("rm_role_menu_rela_t")\n        .where().eq("role_id", roleId)\n        .delete();\n\n    // 再批量插入新关联\n    var count = 0;\n    if (resourceIds && resourceIds.size() > 0) {\n        var insertList = [];\n        for (resourceId in resourceIds) {\n            insertList.push({\n                id: IdUtil.getSnowflakeNextIdStr(),\n                roleId: roleId,\n                appResourceId: resourceId,\n                extendId: \'\'\n            });\n            count = count + 1;\n        }\n        // 从 MySQL 业务表读取当前有效数据。\n        db.table("rm_role_menu_rela_t").batchInsert(insertList);\n    }\n\n    // 返回当前业务分支的标准结果。\n    return { roleId: roleId, count: count };\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'保存角色菜单关联失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/06.权限管理/03.角色菜单保存.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('882093f918054984b1504ea77e58d3af',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "882093f918054984b1504ea77e58d3af",\r\n  "name" : "06.权限管理",\r\n  "type" : "api",\r\n  "parentId" : "9a18bf0b6a994f5aa56aa775f3de9f3d",\r\n  "path" : "/auth",\r\n  "createTime" : 1781960046845,\r\n  "updateTime" : 1784437771090,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/06.权限管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/07.文件管理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9b187462901a488daf65d5d098d529c0',NULL,NULL,'{\n  "properties": {},\n  "id": "9b187462901a488daf65d5d098d529c0",\n  "script": null,\n  "groupId": "5716c78e9d9641528c2dfbd78b708e3b",\n  "name": "01.文件上传",\n  "createTime": 1782660716361,\n  "updateTime": 1784437771374,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/upload",\n  "method": "POST",\n  "parameters": [\n    {\n      "name": "file",\n      "value": {},\n      "description": "真实数据示例参数：file",\n      "required": false,\n      "dataType": "MultipartFile",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n    \\"file_name\\": \\"测试\\",\\n    \\"content\\": \\"测试\\",\\n    \\"belongType\\": \\"app\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "上传文件（头像等）- base64 直传方案；使用请求参数 file_name、content、belongType；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "user_no_login",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：01.文件上传\n// 路由：POST /sym/file/upload\n// 业务说明：上传文件（头像等）- base64 直传方案；使用请求参数 file_name、content、belongType；执行数据库写入并返回处理结果。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.StrUtil;\nimport cn.hutool.core.codec.Base64;\n\n// 上传文件（头像等）- base64 直传方案\n// 路径: /sym/file/upload\n// 方法: POST\n// 参数:\n//   file_name - 文件名 \n//   content   - 文件内容 base64 编码 \n\n\ntry {\n  tenantAccounts.session();\n} catch (e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 校验参数 ====================\nvar fileName = body.file_name;\nif (StrUtil.isBlank(fileName)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "文件名为空";\n}\n\nvar base64Content = body.content;\nif (StrUtil.isBlank(base64Content)) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "文件内容为空";\n}\n\nvar belongType = body.belongType || "AVATAR"\n\n// ==================== 解码 base64 → bytes ====================\nvar fileBytes = Base64.decode(base64Content);\nvar fileSize = fileBytes.length;\n\nif (fileSize <= 0) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "文件大小为0，请选择有效文件";\n}\n\n// ==================== 获取文件后缀 ====================\nvar fileSuffix = "";\nif (fileName.contains(".")) {\n    fileSuffix = fileName.substring(fileName.lastIndexOf(".") + 1);\n}\n\n// ==================== 当前用户 ====================\nvar currentUserId = StpUtil.getLoginId();\nvar now = new Date();\n\n// ==================== 存入 sym_file_t ====================\nvar fileId = IdUtil.getSnowflakeNextIdStr();\n\ndb.lower().table("sym_file_t").insert({\n    id: fileId,\n    file_name: fileName,\n    content: fileBytes,\n    create_id: currentUserId,\n    create_time: now,\n    belong_type: belongType,\n    deleted: 0,\n    has_temporary: 0\n});\n\n// ==================== 返回结果 ====================\nreturn {\n    id: fileId,\n    url: "/sym/file/preview?id=" + fileId,\n    name: fileName,\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/07.文件管理/01.文件上传.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a3413c9232f240c2b0cc98b99b9f2695',NULL,NULL,'{\n  "properties": {},\n  "id": "a3413c9232f240c2b0cc98b99b9f2695",\n  "script": null,\n  "groupId": "5716c78e9d9641528c2dfbd78b708e3b",\n  "name": "02.文件预览",\n  "createTime": 1782660716390,\n  "updateTime": 1784437771378,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/preview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "id - 文件ID（query 参数）。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.文件预览\n// 路由：GET /sym/file/preview\n// 业务说明：id - 文件ID（query 参数）。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.codec.Base64;\n\n// 预览/下载文件\n// 路径: /sym/file/preview\n// 方法: GET\n// 参数:\n//   id - 文件ID（query 参数）\n// 说明:\n//   根据文件ID从 sym_file_t 读取 content (BLOB)，编码为 base64 字符串返回\n//   前端拿到 base64 后解码为 Blob 再显示，彻底避开 magic-api 二进制输出问题\n\n\ntry {\n  tenantAccounts.session();\n} catch (e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 获取参数 ====================\nif (id == null || id == "") {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "文件ID不能为空";\n}\n\n// ==================== 查询文件记录 ====================\nvar fileRecord = db.lower().table("sym_file_t")\n    .where()\n    .eq("id", id)\n    .eq("deleted", 0)\n    .selectOne();\n\nif (fileRecord == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, "文件不存在或已被删除";\n}\n\nif (fileRecord.content == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, "文件内容为空";\n}\n\n// ==================== 根据文件名后缀判定 Content-Type ====================\nvar fileName = fileRecord.file_name || "file";\nvar contentType = "application/octet-stream";\n\nvar lowerName = fileName.toLowerCase();\nif (lowerName.endsWith(".png")) {\n    contentType = "image/png";\n} else if (lowerName.endsWith(".jpg") || lowerName.endsWith(".jpeg")) {\n    contentType = "image/jpeg";\n} else if (lowerName.endsWith(".gif")) {\n    contentType = "image/gif";\n} else if (lowerName.endsWith(".bmp")) {\n    contentType = "image/bmp";\n} else if (lowerName.endsWith(".webp")) {\n    contentType = "image/webp";\n} else if (lowerName.endsWith(".svg")) {\n    contentType = "image/svg+xml";\n} else if (lowerName.endsWith(".pdf")) {\n    contentType = "application/pdf";\n}\n\n// ==================== 将 BLOB 编码为 base64 返回 ====================\n// 前端解码 base64 → Blob → ObjectURL 显示\nvar base64Content = Base64.encode(fileRecord.content);\n\n// 返回当前业务分支的标准结果。\nreturn {\n    content: base64Content,\n    contentType: contentType,\n    fileName: fileName\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/07.文件管理/02.文件预览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('304c8bfbc2d445ba92686159208b19ae',NULL,NULL,'{\n  "properties": {},\n  "id": "304c8bfbc2d445ba92686159208b19ae",\n  "script": null,\n  "groupId": "5716c78e9d9641528c2dfbd78b708e3b",\n  "name": "03.文件删除",\n  "createTime": 1782660716378,\n  "updateTime": 1784437771376,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按目标标识和当前状态执行文件删除，返回处理结果；使用请求参数 id。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.文件删除\n// 路由：POST /sym/file/delete\n// 业务说明：按目标标识和当前状态执行文件删除，返回处理结果；使用请求参数 id。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\n\n// 删除文件\n// 路径: /sym/file/delete\n// 方法: POST\n// 参数:\n//   id - 文件ID（必填）\n\n\ntry {\n  tenantAccounts.session();\n} catch (e) {\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit -1, "账号未登入或登入已过期";\n}\n\n// ==================== 获取参数 ====================\nvar id = body?.id;\nif (id == null || id == "") {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, "文件ID不能为空";\n}\n\n// ==================== 校验文件是否存在 ====================\nvar fileRecord = db.lower().table("sym_file_t")\n    .where()\n    .eq("id", id)\n    .eq("deleted", 0)\n    .selectOne();\n\nif (fileRecord == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 404, "文件不存在或已被删除";\n}\n\n// ==================== 软删除 ====================\nvar currentUserId = StpUtil.getLoginId();\n\ndb.lower().table("sym_file_t")\n    .primary("id")\n    .update({\n        id: id,\n        deleted: 1,\n        update_id: currentUserId,\n        update_time: now\n    });\n\n// 返回当前业务分支的标准结果。\nreturn { id: id };\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/07.文件管理/03.文件删除.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5716c78e9d9641528c2dfbd78b708e3b',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "5716c78e9d9641528c2dfbd78b708e3b",\r\n  "name" : "07.文件管理",\r\n  "type" : "api",\r\n  "parentId" : "9a18bf0b6a994f5aa56aa775f3de9f3d",\r\n  "path" : "/file",\r\n  "createTime" : 1781960046213,\r\n  "updateTime" : 1784437771090,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/07.文件管理/group.json');
