INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e827efbdb789464ea6fbf4b8570f4a61',NULL,NULL,'{\n  "properties": {},\n  "id": "e827efbdb789464ea6fbf4b8570f4a61",\n  "script": null,\n  "groupId": "b2bc4c16954544a69d4bcb4700dadce1",\n  "name": "01.查看审批信息",\n  "createTime": null,\n  "updateTime": 1786951315306,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "info",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "审批详情（GET /sym/approval/info）。按租户校验流程参与人，只读取 Warm-Flow 与本地 sym_* 身份数据；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.查看审批信息\n// 路由：GET /sym/approval/info\n// 业务说明：审批详情（GET /sym/approval/info）。按租户校验流程参与人，只读取 Warm-Flow 与本地 sym_* 身份数据；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制。\nimport tenantRuntime\nimport approvalRuntime\nimport tenantAccounts\nimport jsons\n\n\nif ((businessId == null || businessId == \'\') && (instanceId == null || instanceId == \'\')) {\n    exit -1, \'businessId 和 instanceId 不能同时为空\'\n}\n\nvar principal = approvalRuntime.principal()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = tenantRuntime.id()\nvar instance = db.selectOne("""\n    select i.id, i.business_id, i.flow_status, i.definition_id, i.create_by,\n           i.node_code, i.node_name, i.ext, i.create_time, i.update_time,\n           d.flow_code, d.flow_name, null as create_by_name\n      from flow_instance i\n      join flow_definition d on d.id = i.definition_id and d.tenant_id = i.tenant_id\n     where i.tenant_id = #{tenantId}\n       and i.del_flag = \'0\'\n       <if test="businessId != null and businessId != \'\'">and i.business_id = #{businessId}</if>\n       <if test="instanceId != null and instanceId != \'\'">and i.id = #{instanceId}</if>\n""")\nif (instance == null) { exit -1, \'审批流程不存在或已删除\' }\n\nvar permissionList = principal.permissionKeys\nvar canView = instance.createBy + \'\' == principal.userId\nif (!canView) {\n    var involved = db.selectInt("""\n        select count(*) from flow_user fu\n          join flow_task t on t.id = fu.associated and t.tenant_id = fu.tenant_id\n         where t.instance_id = #{instance.id}\n           and fu.tenant_id = #{tenantId}\n           and fu.del_flag = \'0\' and t.del_flag = \'0\'\n           and fu.processed_by in\n           <foreach item="permission" collection="permissionList" open="(" separator="," close=")">\n             #{permission}\n           </foreach>\n    """)\n    var handled = db.selectInt("""\n        select count(*) from flow_his_task h\n         where h.instance_id = #{instance.id}\n           and h.tenant_id = #{tenantId}\n           and h.del_flag = \'0\'\n           and h.approver = #{principal.userId}\n    """)\n    canView = involved > 0 || handled > 0\n}\nif (!canView) { exit -1, \'您不是该流程的发起人或参与人，无权查看\' }\n\nvar currentTask = db.selectOne("""\n    select id, node_code, node_name, form_custom, form_path\n      from flow_task\n     where instance_id = #{instance.id}\n       and tenant_id = #{tenantId}\n       and del_flag = \'0\' and node_type = 1\n     order by create_time desc\n""")\nvar nodes = db.select("""\n    select h.id, h.node_code, h.node_name, h.node_type as skip_type,\n           h.approver, null as approver_name, h.message,\n           h.create_time, h.update_time\n      from flow_his_task h\n     where h.instance_id = #{instance.id}\n       and h.tenant_id = #{tenantId}\n       and h.del_flag = \'0\'\n     order by h.create_time\n""")\nnodes.each(item -> item.id = item.id + \'\')\nvar names = tenantAccounts.names(([instance.createBy] + nodes.map(item => item.approver)).filter(item => item != null))\ninstance.createByName = names[instance.createBy] || instance.createBy\nnodes.each(item -> item.approverName = names[item.approver] || item.approver)\n\nreturn {\n    approvalInfo: {\n        instanceId: instance.id + \'\',\n        businessId: instance.businessId == null ? null : instance.businessId + \'\',\n        flowStatus: instance.flowStatus,\n        flowCode: instance.flowCode,\n        flowName: instance.flowName,\n        definitionId: instance.definitionId + \'\',\n        createBy: instance.createBy + \'\',\n        createByName: instance.createByName,\n        createTime: instance.createTime,\n        updateTime: instance.updateTime,\n        nodeCode: currentTask?.nodeCode || instance.nodeCode,\n        nodeName: currentTask?.nodeName || instance.nodeName,\n        taskId: currentTask?.id == null ? null : currentTask.id + \'\',\n        ext: instance.ext == null || instance.ext == \'\' ? {} : jsons.toJSONObject(instance.ext)\n    },\n    flowNodes: nodes\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.查看审批信息.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('88f84dd78cbb42899740f49437a41148',NULL,NULL,'{\n  "properties": {},\n  "id": "88f84dd78cbb42899740f49437a41148",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "01.删除常用意见",\n  "createTime": 1782955344444,\n  "updateTime": 1784446270672,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/deleteSuggestion",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按目标标识和当前状态执行删除常用意见，返回处理结果；使用请求参数 tid；涉及 flow_suggestion 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.删除常用意见\n// 路由：POST /sym/approval/query/deleteSuggestion\n// 业务说明：按目标标识和当前状态执行删除常用意见，返回处理结果；使用请求参数 tid；涉及 flow_suggestion 等业务表。\n/*\n * 审批中心 - 删除常用意见\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport cn.dev33.satoken.stp.StpUtil;\n\nvar userId = StpUtil.getLoginIdDefaultNull();\nif (userId == null) {\n    // 返回当前业务分支的标准结果。\n    return []\n}\n\n// 解析请求体并为可选参数设置默认值。\ndb.table("flow_suggestion").where().eq("tid",body?.tid).update(\n    {\n        "is_del":"1"\n    }\n)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/01.删除常用意见.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f8a5b9d39f3a43dabb3ddcbd0c1a2aed',NULL,NULL,'{\n  "properties": {},\n  "id": "f8a5b9d39f3a43dabb3ddcbd0c1a2aed",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "02.常用意见列表",\n  "createTime": 1782955344452,\n  "updateTime": 1784446270673,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/suggestionList",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前登录人员读取审批中心常用意见，返回可复用的意见清单。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.常用意见列表\n// 路由：GET /sym/approval/query/suggestionList\n// 业务说明：按当前登录人员读取审批中心常用意见，返回可复用的意见清单。\n/*\n * 审批中心 - 常用意见列表\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport cn.dev33.satoken.stp.StpUtil;\n\nvar userId = StpUtil.getLoginId() + ""\nif (userId == null) {\n    // 返回当前业务分支的标准结果。\n    return []\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nreturn db.table("flow_suggestion")\n    .columns("tid", "content", "use_num", "create_time", "create_by", "update_time", "update_by", "tenant_id")\n    .where()\n    .eq("is_del", 0)\n    .eq("create_by", userId)\n    .orderBy("use_num", "desc")\n    .select()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/02.常用意见列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5464e3d758ff45b9b337258b587e5151',NULL,NULL,'{\n  "properties": {},\n  "id": "5464e3d758ff45b9b337258b587e5151",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "03.当前流程所有节点",\n  "createTime": 1782955344460,\n  "updateTime": 1784446270674,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/nodes",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"definitionId\\": \\"2034448996486922200\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "审批中心 - 当前流程所有节点；使用请求参数 definitionId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.当前流程所有节点\n// 路由：POST /sym/approval/query/nodes\n// 业务说明：审批中心 - 当前流程所有节点；使用请求参数 definitionId。\n/*\n * 审批中心 - 当前流程所有节点\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.json.JSONObject;\nimport cn.hutool.json.JSONUtil;\nimport org.dromara.warm.flow.core.dto.FlowParams;\nimport org.dromara.warm.flow.core.enums.SkipType;\nimport org.dromara.warm.flow.core.service.InsService as insService\nimport org.dromara.warm.flow.core.service.TaskService as taskService\nimport org.dromara.warm.flow.core.service.NodeService as nodeService\nimport log\n\n// 解析请求体并为可选参数设置默认值。\nvar list = nodeService.getByDefId(body?.definitionId::long)\n// 返回当前业务分支的标准结果。\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/03.当前流程所有节点.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('512ab6be54cc45b28f67828f280c3bd3',NULL,NULL,'{\n  "properties": {},\n  "id": "512ab6be54cc45b28f67828f280c3bd3",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "04.当前流程执行所有节点(包含未执行节点)",\n  "createTime": 1782955344470,\n  "updateTime": 1787153759554,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/executeNodes",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"instanceId\\": \\"2039888528212860929\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "审批中心 - 当前流程执行所有节点(包含未执行节点)；使用请求参数 instanceId；涉及 rm_user_org_rela_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.当前流程执行所有节点(包含未执行节点)\n// 路由：POST /sym/approval/query/executeNodes\n// 业务说明：审批中心 - 当前流程执行所有节点(包含未执行节点)；使用请求参数 instanceId；涉及 rm_user_org_rela_t 等业务表。\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.json.JSONObject;\nimport cn.hutool.json.JSONUtil;\nimport org.dromara.warm.flow.core.dto.FlowParams;\nimport org.dromara.warm.flow.core.enums.SkipType;\nimport org.dromara.warm.flow.core.service.InsService as insService\nimport org.dromara.warm.flow.core.service.TaskService as taskService\nimport org.dromara.warm.flow.core.service.NodeService as nodeService\nimport org.dromara.warm.flow.core.service.HisTaskService as hisTaskService\nimport org.dromara.warm.flow.orm.entity.FlowHisTask;\nimport org.dromara.warm.flow.orm.entity.FlowTask;\nimport log\nimport jsons\nimport tenantAccounts\n\n/*\n * 审批中心 - 当前流程执行所有节点(包含未执行节点)\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\n\n// 解析请求体并为可选参数设置默认值。\nvar instance = insService.getById(body?.instanceId::long)\n\nvar flowHisTasks = hisTaskService.orderById().list(new FlowHisTask().setInstanceId(instance.id));\n\nif(flowHisTasks != null)\n{\n    flowHisTasks = JSONUtil.parse(jsons.toJSONStr(flowHisTasks));\n}else {\n    flowHisTasks = []\n}\n\nvar nodeList = []\nvar nodeCodeList = []\nvar lastTargetNodeCode = "" \nflowHisTasks.forEach( item ->{\n    var node = {\n        "nodeCode": item.nodeCode,\n        "nodeName": item.nodeName,\n        "skipType": item.skipType,\n        "flowStatus": item.flowStatus,\n        "message": item.message,\n        "createTime": item.createTime,\n        "updateTime": item.updateTime,\n        "targetNodeCode": item.targetNodeCode,\n        "targetNodeName": item.targetNodeName\n    }\n    ext = jsons.toJSONObject(item.variable)\n    var orgSQL = """\n        SELECT\n        u.user_id,\n        org.id,\n        org.name,\n        org.serial_number,\n        org.org_path \n        FROM\n        rm_user_org_rela_t u,\n        rm_org_t org \n        WHERE\n        u.user_id = #{ext.handle} \n        AND u.job_type = 1 \n        AND u.org_id = org.id\n    """\n    // 从 MySQL 业务表读取当前有效数据。\n    var orgList = db.selectOne(orgSQL)\n\n    var userNames = tenantAccounts.names([ext.handle])\n    var user = { realName: userNames[ext.handle] || ext.handle }\n\n    node.orgName = orgList.name\n    node.userName = user.realName\n    node.message = ext.message == null ? "无":ext.message//审批意见\n    node.hisTaskId = item.id + ""//办理节点任务id 用于附件查看\n\n    nodeList.add(node)\n    nodeCodeList.add(item.nodeCode)\n    lastTargetNodeCode = item.targetNodeCode\n})\n\nif( lastTargetNodeCode == "end"){\n     var node = {\n                    "nodeCode": "end",\n                    "nodeName": "结束",\n                    "skipType": "PASS",\n                    "flowStatus": "2",\n                    "message": null,\n                    "createTime": flowHisTasks.last.createTime,\n                    "updateTime": flowHisTasks.last.updateTime\n                }\n    nodeList.add(node)\n}else {\n    if(flowHisTasks.size() != 0){\n        var node = {\n                        "nodeCode": flowHisTasks.last.targetNodeCode,\n                        "nodeName": flowHisTasks.last.targetNodeName,\n                        "skipType": null,\n                        "flowStatus": null,\n                        "message": null,\n                        "createTime": null,\n                        "updateTime": null\n                    }\n         nodeList.add(node)  \n\n        var list = nodeService.suffixNodeList(instance.definitionId, lastTargetNodeCode)\n        if( list != null && list.size() != 0){\n            list = JSONUtil.parse(jsons.toJSONStr(list))\n            list.forEach(item -> {\n                    var node = {\n                        "nodeCode": item.nodeCode,\n                        "nodeName": item.nodeName,\n                        "skipType": null,\n                        "flowStatus": null,\n                        "message": null,\n                        "createTime": null,\n                        "updateTime": null\n                    }\n                    nodeCodeList.add(item.nodeCode)\n                    nodeList.add(node)\n        })\n        }\n    }\n}\n\n// 返回当前业务分支的标准结果。\nreturn nodeList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/04.当前流程执行所有节点(包含未执行节点).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6efe69006a134fcda69d1838d0ab0701',NULL,NULL,'{\n  "properties": {},\n  "id": "6efe69006a134fcda69d1838d0ab0701",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "05.流程分类统计",\n  "createTime": 1782955344480,\n  "updateTime": 1787153759596,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "count",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "结合当前人员的角色和组织范围，统计其可见流程的分类与数量。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.流程分类统计\n// 路由：POST /sym/approval/query/count\n// 业务说明：结合当前人员的角色和组织范围，统计其可见流程的分类与数量。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\n\n/*\n * 审批中心 - 流程分类统计\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\n\nvar currentUserId = StpUtil.getLoginId() + ""\n\nvar addUnique = (list, value) => {\n    if (value == null || value == "") {\n        return\n    }\n    var strValue = value + ""\n    if (list.filter(item => item == strValue).size() == 0) {\n        list.add(strValue)\n    }\n}\n\nvar permissionList = []\naddUnique(permissionList, currentUserId)\nvar viewerUserIds = []\naddUnique(viewerUserIds, currentUserId)\n\nvar appId = tenantAccounts.session().get("appId")\n// 从 MySQL 业务表读取当前有效数据。\nvar userRoleList = db.table("rm_user_role_rela_t").where()\n    .eq("user_id", currentUserId)\n    .select()\n\nif (userRoleList != null && userRoleList.size() > 0) {\n    var roleIds = userRoleList.map(item => {\n        // 返回当前业务分支的标准结果。\n        return item.roleId\n    })\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var roleList = db.table("rm_role_t").where()\n        .eq("app_id", appId)\n        .in("id", roleIds)\n        .select()\n\n    if (roleList != null && roleList.size() > 0) {\n        roleList.each(item -> {\n            addUnique(permissionList, "role:" + item.codeNum)\n        })\n\n        // 从 MySQL 业务表读取当前有效数据。\n        var sameRoleUserList = db.table("rm_user_role_rela_t").where()\n            .in("role_id", roleIds)\n            .select()\n        if (sameRoleUserList != null && sameRoleUserList.size() > 0) {\n            sameRoleUserList.each(item -> {\n                addUnique(viewerUserIds, item.userId)\n            })\n        }\n    }\n}\n\nvar orgSQL = """\n    SELECT\n        org.id\n    FROM\n        rm_user_org_rela_t u,\n        rm_org_t org\n    WHERE\n        u.user_id = #{currentUserId}\n        AND u.job_type = 1\n        AND u.org_id = org.id\n"""\n// 从 MySQL 业务表读取当前有效数据。\nvar orgInfo = db.selectOne(orgSQL)\nif (orgInfo != null) {\n    addUnique(permissionList, "org:" + orgInfo.id)\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var sameOrgUserList = db.table("rm_user_org_rela_t").where()\n        .eq("org_id", orgInfo.id)\n        .select()\n    if (sameOrgUserList != null && sameOrgUserList.size() > 0) {\n        sameOrgUserList.each(item -> {\n            addUnique(viewerUserIds, item.userId)\n        })\n    }\n}\n\nvar allCountSql = """\n    SELECT COUNT(1) AS total\n    FROM flow_instance i\n    <where>\n        i.del_flag = \'0\'\n        AND i.create_by in\n        <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n            #{viewerUserId}\n        </foreach>\n        AND i.flow_status in (1, 2, 4, 6, 8, 9, 11)\n    </where>\n"""\n\nvar processCountSql = """\n    SELECT COUNT(1) AS total\n    FROM flow_instance i\n    <where>\n        i.del_flag = \'0\'\n        AND i.create_by in\n        <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n            #{viewerUserId}\n        </foreach>\n        AND i.flow_status in (1, 9)\n    </where>\n"""\n\nvar achieveCountSql = """\n    SELECT COUNT(1) AS total\n    FROM flow_instance i\n    <where>\n        i.del_flag = \'0\'\n        AND i.create_by in\n        <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n            #{viewerUserId}\n        </foreach>\n        AND i.flow_status in (4, 6, 8)\n    </where>\n"""\n\nvar doneCountSql = """\n    SELECT COUNT(1) AS total\n    FROM (\n        SELECT MAX(id) AS id\n        FROM flow_his_task\n        <where>\n            approver in\n            <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n                #{viewerUserId}\n            </foreach>\n            AND del_flag = \'0\'\n        </where>\n        GROUP BY instance_id\n    ) t\n"""\n\nvar todoCountSql = """\n    SELECT COUNT(DISTINCT t.id) AS total\n    FROM flow_task t\n    JOIN flow_user uu ON uu.associated = t.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    <where>\n        t.node_type = 1\n        AND t.del_flag = \'0\'\n        AND uu.del_flag = \'0\'\n        AND i.del_flag = \'0\'\n        AND t.flow_status != 4\n        AND uu.processed_by in\n        <foreach item="permission" collection="permissionList" open="(" separator="," close=")">\n            #{permission}\n        </foreach>\n    </where>\n"""\n\nvar queryCount = (sql) => {\n    // 从 MySQL 业务表读取当前有效数据。\n    var row = db.selectOne(sql)\n    if (row == null || row.total == null) {\n        // 返回当前业务分支的标准结果。\n        return 0\n    }\n    // 返回当前业务分支的标准结果。\n    return row.total::long(0)\n}\n\n// 返回当前业务分支的标准结果。\nreturn {\n    all: queryCount(allCountSql),\n    todo: queryCount(todoCountSql),\n    done: queryCount(doneCountSql),\n    process: queryCount(processCountSql),\n    achieve: queryCount(achieveCountSql)\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/05.流程分类统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5f6b55b2b62d4b7e9d964cb4a9db247b',NULL,NULL,'{\n  "properties": {},\n  "id": "5f6b55b2b62d4b7e9d964cb4a9db247b",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "06.流程分页查询",\n  "createTime": 1782955344488,\n  "updateTime": 1787153759644,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "page_copy",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": \\"1\\",\\n    \\"pageSize\\": \\"20\\",\\n    \\"flowSatusType\\": \\"achieve\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前人员的角色和组织范围，结合节点、实例、状态及分页条件查询审批流程。",\n  "requestBodyDefinition": {\n    "name": "root",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "pageNum",\n        "value": "1",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "pageSize",\n        "value": "20",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "nodeCode",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "nodeName",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "instanceId",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "flowSatusType",\n        "value": "todo",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  },\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "user_no_login",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：06.流程分页查询\n// 路由：POST /sym/approval/query/page_copy\n// 业务说明：按当前人员的角色和组织范围，结合节点、实例、状态及分页条件查询审批流程。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\n\n/*\n * 审批中心 - 流程分页查询\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\n\n// 解析请求体并为可选参数设置默认值。\nvar nodeCode = body?.nodeCode\nvar nodeName = body?.nodeName\nvar instanceId = body?.instanceId\n\nvar flowStatusType = body?.flowSatusType\nif (flowStatusType == null || flowStatusType == "") {\n    flowStatusType = "all"\n}\n\nvar currentUserId = StpUtil.getLoginId() + ""\n\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\nvar offsetLimit = pageNum == 0 ? 0 : (pageNum - 1) * pageSize\n\nvar addUnique = (list, value) => {\n    if (value == null || value == "") {\n        return\n    }\n    var strValue = value + ""\n    if (list.filter(item => item == strValue).size() == 0) {\n        list.add(strValue)\n    }\n}\n\nvar permissionList = []\naddUnique(permissionList, currentUserId)\nvar viewerUserIds = []\naddUnique(viewerUserIds, currentUserId)\n\nvar appId = tenantAccounts.session().get("appId")\n// 从 MySQL 业务表读取当前有效数据。\nvar userRoleList = db.table("rm_user_role_rela_t").where()\n    .eq("user_id", currentUserId)\n    .select()\n\nif (userRoleList != null && userRoleList.size() > 0) {\n    var roleIds = userRoleList.map(item => {\n        // 返回当前业务分支的标准结果。\n        return item.roleId\n    })\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var roleList = db.table("rm_role_t").where()\n        .eq("app_id", appId)\n        .in("id", roleIds)\n        .select()\n\n    if (roleList != null && roleList.size() > 0) {\n        roleList.each(item -> {\n            addUnique(permissionList, "role:" + item.codeNum)\n        })\n\n        // 从 MySQL 业务表读取当前有效数据。\n        var sameRoleUserList = db.table("rm_user_role_rela_t").where()\n            .in("role_id", roleIds)\n            .select()\n        if (sameRoleUserList != null && sameRoleUserList.size() > 0) {\n            sameRoleUserList.each(item -> {\n                addUnique(viewerUserIds, item.userId)\n            })\n        }\n    }\n}\n\nvar orgSQL = """\n    SELECT\n        org.id\n    FROM\n        rm_user_org_rela_t u,\n        rm_org_t org\n    WHERE\n        u.user_id = #{currentUserId}\n        AND u.job_type = 1\n        AND u.org_id = org.id\n"""\n// 从 MySQL 业务表读取当前有效数据。\nvar orgInfo = db.selectOne(orgSQL)\nif (orgInfo != null) {\n    addUnique(permissionList, "org:" + orgInfo.id)\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var sameOrgUserList = db.table("rm_user_org_rela_t").where()\n        .eq("org_id", orgInfo.id)\n        .select()\n    if (sameOrgUserList != null && sameOrgUserList.size() > 0) {\n        sameOrgUserList.each(item -> {\n            addUnique(viewerUserIds, item.userId)\n        })\n    }\n}\n\nvar todoPageSql = """\n    SELECT DISTINCT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.node_type,\n        t.definition_id,\n        t.instance_id,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.flow_status,\n        i.business_id,\n        i.activity_status,\n        d.flow_name,\n        t.form_custom,\n        t.form_path\n    FROM flow_task t\n    JOIN flow_user uu ON uu.associated = t.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    <where>\n        t.node_type = 1\n        AND t.del_flag = \'0\'\n        AND uu.del_flag = \'0\'\n        AND i.del_flag = \'0\'\n        AND uu.processed_by in\n        <foreach item="permission" collection="permissionList" open="(" separator="," close=")">\n            #{permission}\n        </foreach>\n        <if test="nodeCode != null and nodeCode != \'\'">AND t.node_code = #{nodeCode}</if>\n        <if test="nodeName != null and nodeName != \'\'">AND t.node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n        <if test="instanceId != null and instanceId != \'\'">AND t.instance_id = #{instanceId}</if>\n    </where>\n    ORDER BY t.create_time DESC\n"""\n\nvar myInstancePageSql = """\n    SELECT\n        i.id,\n        i.node_code,\n        i.node_name,\n        i.node_type,\n        i.definition_id,\n        i.id AS instance_id,\n        i.create_time,\n        i.update_time,\n        i.tenant_id,\n        i.flow_status,\n        i.business_id,\n        i.activity_status,\n        d.flow_name,\n        d.form_custom,\n        d.form_path\n    FROM flow_instance i\n    LEFT JOIN flow_definition d ON i.definition_id = d.id\n    <where>\n        i.del_flag = \'0\'\n        AND i.create_by in\n        <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n            #{viewerUserId}\n        </foreach>\n        <if test="nodeCode != null and nodeCode != \'\'">AND i.node_code = #{nodeCode}</if>\n        <if test="nodeName != null and nodeName != \'\'">AND i.node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n        <if test="instanceId != null and instanceId != \'\'">AND i.id = #{instanceId}</if>\n        <if test="flowStatusType == \'process\'">AND i.flow_status in (1, 6, 9)</if>\n        <if test="flowStatusType == \'achieve\'">AND i.flow_status in (2, 4, 8)</if>\n        <if test="flowStatusType == \'all\'">AND i.flow_status in (1, 2, 4, 6, 8, 9, 11)</if>\n    </where>\n    ORDER BY i.create_time DESC\n"""\n\nvar donePageSql = """\n    SELECT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.cooperate_type,\n        t.approver,\n        t.collaborator,\n        t.node_type,\n        t.target_node_code,\n        t.target_node_name,\n        t.definition_id,\n        t.instance_id,\n        i.flow_status,\n        t.message,\n        t.ext,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.business_id,\n        t.form_path,\n        d.flow_name\n    FROM (\n        SELECT MAX(id) AS id\n        FROM flow_his_task\n        <where>\n            approver in\n            <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n                #{viewerUserId}\n            </foreach>\n            AND del_flag = \'0\'\n            <if test="nodeCode != null and nodeCode != \'\'">AND node_code = #{nodeCode}</if>\n            <if test="nodeName != null and nodeName != \'\'">AND node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n            <if test="instanceId != null and instanceId != \'\'">AND instance_id = #{instanceId}</if>\n        </where>\n        GROUP BY instance_id\n    ) tmp\n    LEFT JOIN flow_his_task t ON t.id = tmp.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    ORDER BY t.create_time DESC\n"""\n\nvar representPageSql = """\n    SELECT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.cooperate_type,\n        t.approver,\n        t.collaborator,\n        t.node_type,\n        t.target_node_code,\n        t.target_node_name,\n        t.definition_id,\n        t.instance_id,\n        i.flow_status,\n        t.message,\n        t.ext,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.business_id,\n        t.form_path,\n        d.flow_name\n    FROM (\n        SELECT MAX(id) AS id\n        FROM flow_his_task\n        <where>\n            del_flag = \'0\'\n            AND (cooperate_type = 2 OR cooperate_type = 3)\n            AND (\n                approver in\n                <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n                    #{viewerUserId}\n                </foreach>\n                <if test="viewerUserIds != null and viewerUserIds.size() > 0">\n                    OR\n                    <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator=" OR " close=")">\n                        collaborator like concat(\'%\', #{viewerUserId}, \'%\')\n                    </foreach>\n                </if>\n            )\n            <if test="nodeCode != null and nodeCode != \'\'">AND node_code = #{nodeCode}</if>\n            <if test="nodeName != null and nodeName != \'\'">AND node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n            <if test="instanceId != null and instanceId != \'\'">AND instance_id = #{instanceId}</if>\n        </where>\n        GROUP BY instance_id\n    ) tmp\n    LEFT JOIN flow_his_task t ON t.id = tmp.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    ORDER BY t.create_time DESC\n"""\n\nvar pageSql = myInstancePageSql\nif (flowStatusType == "todo") {\n    pageSql = todoPageSql\n} else if (flowStatusType == "done") {\n    pageSql = donePageSql\n} else if (flowStatusType == "represent") {\n    pageSql = representPageSql\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar pageList = db.page(pageSql, pageSize, offsetLimit)\n\nif (pageList.total == 0) {\n    pageList.list = []\n} else {\n    pageList.list.each(item -> {\n        item.id = item.id + ""\n        item.definitionId = item.definitionId + ""\n        item.instanceId = item.instanceId + ""\n        if (item.businessId != null) {\n            item.businessId = item.businessId + ""\n        }\n    })\n}\n\n// 返回当前业务分支的标准结果。\nreturn pageList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/06.流程分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f23cef22cacc4a8cbe5ac3df7c3a1566',NULL,NULL,'{\n  "properties": {},\n  "id": "f23cef22cacc4a8cbe5ac3df7c3a1566",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "07.流程分页查询",\n  "createTime": 1786756145867,\n  "updateTime": 1786951315185,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"flowSatusType\\":\\"todo\\",\\"flowCode\\":\\"\\",\\"key\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前人员的角色和组织范围，结合节点、实例、状态及分页条件查询审批流程。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：07.流程分页查询\n// 路由：POST /sym/approval/query/page\n// 业务说明：按当前人员的角色和组织范围，结合节点、实例、状态及分页条件查询审批流程。\nimport tenantRuntime\nimport approvalRuntime\nimport tenantAccounts\nimport jsons\n\n\nvar principal = approvalRuntime.principal()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = tenantRuntime.id()\nvar currentUserId = principal.userId\nvar permissionList = principal.permissionKeys\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\nvar offset = (pageNum - 1) * pageSize\nvar view = body?.flowSatusType || "todo"\nvar flowCode = body?.flowCode\nvar keyword = body?.key\n\nvar todoSql = """\n    select distinct t.id, t.node_code, t.node_name, t.node_type,\n           t.definition_id, t.instance_id, t.create_time, t.update_time,\n           t.tenant_id, t.flow_status, i.business_id, i.activity_status,\n           i.create_by, i.ext, d.flow_code, d.flow_name, t.form_custom, t.form_path,\n           null as create_name\n      from flow_task t\n      join flow_user fu on fu.associated = t.id\n      join flow_instance i on i.id = t.instance_id\n      join flow_definition d on d.id = t.definition_id\n     where t.tenant_id = #{tenantId}\n       and fu.tenant_id = #{tenantId}\n       and i.tenant_id = #{tenantId}\n       and d.tenant_id = #{tenantId}\n       and t.del_flag = \'0\' and fu.del_flag = \'0\' and i.del_flag = \'0\'\n       and t.node_type = 1\n       and t.flow_status not in (\'4\', \'6\', \'8\')\n       and fu.processed_by in\n       <foreach item="permission" collection="permissionList" open="(" separator="," close=")">\n         #{permission}\n       </foreach>\n       <if test="flowCode != null and flowCode != \'\'">and d.flow_code = #{flowCode}</if>\n       <if test="keyword != null and keyword != \'\'">\n         and (d.flow_name like concat(\'%\', #{keyword}, \'%\') or i.ext like concat(\'%\', #{keyword}, \'%\'))\n       </if>\n     order by t.create_time desc\n"""\n\nvar instanceSql = """\n    select i.id, i.node_code, i.node_name, i.node_type, i.definition_id,\n           i.id as instance_id, i.create_time, i.update_time, i.tenant_id,\n           i.flow_status, i.business_id, i.activity_status, i.create_by, i.ext,\n           d.flow_code, d.flow_name, d.form_custom, d.form_path,\n           null as create_name\n      from flow_instance i\n      join flow_definition d on d.id = i.definition_id\n     where i.tenant_id = #{tenantId}\n       and d.tenant_id = #{tenantId}\n       and i.del_flag = \'0\'\n       and i.create_by = #{currentUserId}\n       <if test="view == \'process\'">and i.flow_status in (\'1\', \'9\')</if>\n       <if test="view == \'archive\' || view == \'achieve\'">and i.flow_status in (\'2\', \'4\', \'6\', \'8\')</if>\n       <if test="view == \'all\'">and i.flow_status in (\'1\', \'2\', \'4\', \'6\', \'8\', \'9\', \'11\')</if>\n       <if test="flowCode != null and flowCode != \'\'">and d.flow_code = #{flowCode}</if>\n       <if test="keyword != null and keyword != \'\'">\n         and (d.flow_name like concat(\'%\', #{keyword}, \'%\') or i.ext like concat(\'%\', #{keyword}, \'%\'))\n       </if>\n     order by i.create_time desc\n"""\n\nvar doneSql = """\n    select h.id, h.node_code, h.node_name, h.node_type, h.definition_id,\n           h.instance_id, h.create_time, h.update_time, h.tenant_id,\n           i.flow_status, i.business_id, i.activity_status, i.create_by, i.ext,\n           h.message, h.form_path, d.flow_code, d.flow_name,\n           null as create_name\n      from flow_his_task h\n      join flow_instance i on i.id = h.instance_id\n      join flow_definition d on d.id = h.definition_id\n     where h.tenant_id = #{tenantId}\n       and i.tenant_id = #{tenantId}\n       and d.tenant_id = #{tenantId}\n       and h.del_flag = \'0\'\n       and h.approver = #{currentUserId}\n       and h.id = (\n           select max(h2.id) from flow_his_task h2\n            where h2.instance_id = h.instance_id\n              and h2.approver = #{currentUserId}\n              and h2.tenant_id = #{tenantId}\n              and h2.del_flag = \'0\'\n       )\n       <if test="flowCode != null and flowCode != \'\'">and d.flow_code = #{flowCode}</if>\n       <if test="keyword != null and keyword != \'\'">\n         and (d.flow_name like concat(\'%\', #{keyword}, \'%\') or i.ext like concat(\'%\', #{keyword}, \'%\'))\n       </if>\n     order by h.create_time desc\n"""\n\nvar sql = view == "todo" ? todoSql : (view == "done" ? doneSql : instanceSql)\nvar result = db.page(sql, pageSize, offset)\nresult.list = result.list || []\nvar names = tenantAccounts.names(result.list.map(item => item.createBy))\nresult.list.each(item -> {\n    item.id = item.id == null ? null : item.id + ""\n    item.definitionId = item.definitionId == null ? null : item.definitionId + ""\n    item.instanceId = item.instanceId == null ? null : item.instanceId + ""\n    item.businessId = item.businessId == null ? null : item.businessId + ""\n    item.createName = names[item.createBy] || item.createBy\n    item.ext = item.ext == null || item.ext == "" ? {} : jsons.toJSONObject(item.ext)\n    item.businessName = item.ext?.businessName || item.flowName\n})\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/07.流程分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('89f08b343c4a4a41ac71c73e32c9ea36',NULL,NULL,'{\n  "properties": {},\n  "id": "89f08b343c4a4a41ac71c73e32c9ea36",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "08.流程列表",\n  "createTime": 1782955344513,\n  "updateTime": 1787153759682,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按当前人员的角色和组织范围筛选审批流程，支持节点、流程编码、关键词和状态条件。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.流程列表\n// 路由：POST /sym/approval/query/list\n// 业务说明：按当前人员的角色和组织范围筛选审批流程，支持节点、流程编码、关键词和状态条件。\nimport tenantAccounts\nimport cn.dev33.satoken.stp.StpUtil;\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport \'@/common/localCache\' as localCache\n\n/*\n * 审批中心 - 流程列表\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\n\n// 解析请求体并为可选参数设置默认值。\nvar nodeCode = body?.nodeCode\nvar nodeName = body?.nodeName\nvar instanceId = body?.instanceId\nvar flowCode = body?.flowCode\nvar key = body?.key\n\nvar flowStatusType = body?.flowSatusType\nif (flowStatusType == null || flowStatusType == "") {\n    flowStatusType = "all"\n}\n\nvar currentUserId = StpUtil.getLoginId() + ""\n\nvar addUnique = (list, value) => {\n    if (value == null || value == "") {\n        return\n    }\n    var strValue = value + ""\n    if (list.filter(item => item == strValue).size() == 0) {\n        list.add(strValue)\n    }\n}\n\nvar permissionList = []\naddUnique(permissionList, currentUserId)\nvar viewerUserIds = []\naddUnique(viewerUserIds, currentUserId)\n\nvar appId = tenantAccounts.session().get("appId")\n// 从 MySQL 业务表读取当前有效数据。\nvar userRoleList = db.table("rm_user_role_rela_t").where()\n    .eq("user_id", currentUserId)\n    .select()\n\nif (userRoleList != null && userRoleList.size() > 0) {\n    var roleIds = userRoleList.map(item => {\n        // 返回当前业务分支的标准结果。\n        return item.roleId\n    })\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var roleList = db.table("rm_role_t").where()\n        .eq("app_id", appId)\n        .in("id", roleIds)\n        .select()\n\n    if (roleList != null && roleList.size() > 0) {\n        roleList.each(item -> {\n            addUnique(permissionList, "role:" + item.codeNum)\n        })\n\n        // 从 MySQL 业务表读取当前有效数据。\n        var sameRoleUserList = db.table("rm_user_role_rela_t").where()\n            .in("role_id", roleIds)\n            .select()\n        if (sameRoleUserList != null && sameRoleUserList.size() > 0) {\n            sameRoleUserList.each(item -> {\n                addUnique(viewerUserIds, item.userId)\n            })\n        }\n    }\n}\n\nvar orgSQL = """\n    SELECT\n        org.id\n    FROM\n        rm_user_org_rela_t u,\n        rm_org_t org\n    WHERE\n        u.user_id = #{currentUserId}\n        AND u.job_type = 1\n        AND u.org_id = org.id\n"""\n// 从 MySQL 业务表读取当前有效数据。\nvar orgInfo = db.selectOne(orgSQL)\nif (orgInfo != null) {\n    addUnique(permissionList, "org:" + orgInfo.id)\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var sameOrgUserList = db.table("rm_user_org_rela_t").where()\n        .eq("org_id", orgInfo.id)\n        .select()\n    if (sameOrgUserList != null && sameOrgUserList.size() > 0) {\n        sameOrgUserList.each(item -> {\n            addUnique(viewerUserIds, item.userId)\n        })\n    }\n}\n\nvar todoPageSql = """\n    SELECT DISTINCT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.node_type,\n        t.definition_id,\n        t.instance_id,\n        i.create_by,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.flow_status,\n        i.business_id,\n        i.activity_status,\n        i.ext,\n        d.flow_name,\n        t.form_custom,\n        t.form_path\n    FROM flow_task t\n    JOIN flow_user uu ON uu.associated = t.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    <where>\n        t.node_type = 1\n        AND t.del_flag = \'0\'\n        AND uu.del_flag = \'0\'\n        AND i.del_flag = \'0\'\n        AND t.flow_status != 4\n        AND uu.processed_by in\n        <foreach item="permission" collection="permissionList" open="(" separator="," close=")">\n            #{permission}\n        </foreach>\n        <if test="flowCode != null and flowCode != \'\'">AND d.flow_code = #{flowCode}</if>\n        <if test="key != null and key != \'\'">AND i.ext like concat(\'%\', #{key}, \'%\')</if>\n        <if test="nodeCode != null and nodeCode != \'\'">AND t.node_code = #{nodeCode}</if>\n        <if test="nodeName != null and nodeName != \'\'">AND t.node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n        <if test="instanceId != null and instanceId != \'\'">AND t.instance_id = #{instanceId}</if>\n    </where>\n    ORDER BY t.create_time DESC\n"""\n\nvar myInstancePageSql = """\n    SELECT\n        t.id,\n        i.node_code,\n        i.node_name,\n        i.node_type,\n        i.definition_id,\n        i.id AS instance_id,\n        i.create_by,\n        i.create_time,\n        i.update_time,\n        i.tenant_id,\n        i.flow_status,\n        i.business_id,\n        i.activity_status,\n        i.ext,\n        d.flow_name,\n        d.form_custom,\n        d.form_path\n    FROM flow_instance i\n    LEFT JOIN flow_definition d ON i.definition_id = d.id\n    LEFT JOIN flow_task t ON t.instance_id = i.id\n    <where>\n        i.del_flag = \'0\'\n        AND i.create_by in\n        <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n            #{viewerUserId}\n        </foreach>\n        <if test="flowCode != null and flowCode != \'\'">AND d.flow_code = #{flowCode}</if>\n        <if test="key != null and key != \'\'">AND i.ext like concat(\'%\', #{key}, \'%\')</if>\n        <if test="nodeCode != null and nodeCode != \'\'">AND i.node_code = #{nodeCode}</if>\n        <if test="nodeName != null and nodeName != \'\'">AND i.node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n        <if test="instanceId != null and instanceId != \'\'">AND i.id = #{instanceId}</if>\n        <if test="flowStatusType == \'process\'">AND i.flow_status in (1, 9)</if>\n        <if test="flowStatusType == \'achieve\'">AND i.flow_status in (4,6,8)</if>\n        <if test="flowStatusType == \'all\'">AND i.flow_status in (1, 2, 4, 6, 8, 9, 11)</if>\n    </where>\n    ORDER BY i.create_time DESC\n"""\n\nvar donePageSql = """\n    SELECT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.cooperate_type,\n        t.approver,\n        t.collaborator,\n        t.node_type,\n        t.target_node_code,\n        t.target_node_name,\n        t.definition_id,\n        t.instance_id,\n        i.flow_status,\n        t.message,\n        i.ext,\n        i.create_by,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.business_id,\n        t.form_path,\n        d.flow_name\n    FROM (\n        SELECT MAX(id) AS id\n        FROM flow_his_task\n        <where>\n            approver in\n            <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n                #{viewerUserId}\n            </foreach>\n            AND del_flag = \'0\'\n            <if test="flowCode != null and flowCode != \'\'">AND definition_id in (SELECT id FROM flow_definition WHERE flow_code = #{flowCode} AND del_flag = \'0\')</if>\n            <if test="nodeCode != null and nodeCode != \'\'">AND node_code = #{nodeCode}</if>\n            <if test="nodeName != null and nodeName != \'\'">AND node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n            <if test="instanceId != null and instanceId != \'\'">AND instance_id = #{instanceId}</if>\n        </where>\n        GROUP BY instance_id\n    ) tmp\n    LEFT JOIN flow_his_task t ON t.id = tmp.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    <where>\n        <if test="key != null and key != \'\'">i.ext like concat(\'%\', #{key}, \'%\')</if>\n    </where>\n    ORDER BY t.create_time DESC\n"""\n\nvar representPageSql = """\n    SELECT\n        t.id,\n        t.node_code,\n        t.node_name,\n        t.cooperate_type,\n        t.approver,\n        t.collaborator,\n        t.node_type,\n        t.target_node_code,\n        t.target_node_name,\n        t.definition_id,\n        t.instance_id,\n        i.flow_status,\n        t.message,\n        i.ext,\n        i.create_by,\n        t.create_time,\n        t.update_time,\n        t.tenant_id,\n        i.business_id,\n        t.form_path,\n        d.flow_name\n    FROM (\n        SELECT MAX(id) AS id\n        FROM flow_his_task\n        <where>\n            del_flag = \'0\'\n            AND (cooperate_type = 2 OR cooperate_type = 3)\n            AND (\n                approver in\n                <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator="," close=")">\n                    #{viewerUserId}\n                </foreach>\n                <if test="viewerUserIds != null and viewerUserIds.size() > 0">\n                    OR\n                    <foreach item="viewerUserId" collection="viewerUserIds" open="(" separator=" OR " close=")">\n                        collaborator like concat(\'%\', #{viewerUserId}, \'%\')\n                    </foreach>\n                </if>\n            )\n            <if test="flowCode != null and flowCode != \'\'">AND definition_id in (SELECT id FROM flow_definition WHERE flow_code = #{flowCode} AND del_flag = \'0\')</if>\n            <if test="nodeCode != null and nodeCode != \'\'">AND node_code = #{nodeCode}</if>\n            <if test="nodeName != null and nodeName != \'\'">AND node_name like concat(\'%\', #{nodeName}, \'%\')</if>\n            <if test="instanceId != null and instanceId != \'\'">AND instance_id = #{instanceId}</if>\n        </where>\n        GROUP BY instance_id\n    ) tmp\n    LEFT JOIN flow_his_task t ON t.id = tmp.id\n    LEFT JOIN flow_definition d ON t.definition_id = d.id\n    LEFT JOIN flow_instance i ON t.instance_id = i.id\n    <where>\n        <if test="key != null and key != \'\'">i.ext like concat(\'%\', #{key}, \'%\')</if>\n    </where>\n    ORDER BY t.create_time DESC\n"""\n\nvar pageSql = myInstancePageSql\nif (flowStatusType == "todo") {\n    pageSql = todoPageSql\n} else if (flowStatusType == "done") {\n    pageSql = donePageSql\n} else if (flowStatusType == "represent") {\n    pageSql = representPageSql\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar list = db.select(pageSql)\n\nvar resultList = []\nif (list != null && list.size() > 0) {\n    list.each(item -> {\n        item.id = item.id + ""\n        item.definitionId = item.definitionId + ""\n        item.instanceId = item.instanceId + ""\n        if (item.businessId != null) {\n            item.businessId = item.businessId + ""\n        }\n        resultList.add(item)\n    })\n}\n\nvar names = tenantAccounts.names(resultList.map(item => item.createBy))\n\nresultList.each( item -> {\n    item.creatName = names[item.createBy] || item.createBy\n    ext = jsons.toJSONObject(item.ext)\n    item.ext = ext\n    if(ext != null ){\n        if(ext?.businessType == "asset" && ext.relaId != ""){\n            if( ext.relaId != null ){\n                // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n                var assetDoc = esCommonService.getDocument("dataassets", ext.relaId)\n                item.orgName = localCache(assetDoc.orgId, "org")            \n            }\n        }else {\n            if( ext.relaId != null && ext.relaId != ""){\n                // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n                var applyDoc = esCommonService.getDocument("dataassets_apply_form", ext.relaId)\n                item.orgName = localCache(applyDoc.applyOrgId, "org")\n            }\n        }\n    }\n})\n\n// 返回当前业务分支的标准结果。\nreturn resultList\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/08.流程列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6c3ab97a62ce4aec8b9fb91d17703726',NULL,NULL,'{\n  "properties": {},\n  "id": "6c3ab97a62ce4aec8b9fb91d17703726",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "09.流程定义列表",\n  "createTime": 1782955344534,\n  "updateTime": 1784446270714,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/definitionList",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取审批中心可用的流程定义，返回发起流程时可选择的定义清单。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.流程定义列表\n// 路由：GET /sym/approval/query/definitionList\n// 业务说明：读取审批中心可用的流程定义，返回发起流程时可选择的定义清单。\n/*\n * 审批中心 - 流程定义列表\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport log\n\n// 从 MySQL 业务表读取当前有效数据。\nvar list = db.table("flow_definition").where().eq("is_publish", "1").select()\n\n// 返回当前业务分支的标准结果。\nreturn list.map(el => ({\n    ...el,\n    id: el.id + ""\n}))\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/09.流程定义列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6826075b84dd4f2fb768993514383911',NULL,NULL,'{\n  "properties": {},\n  "id": "6826075b84dd4f2fb768993514383911",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "10.统计流程统计",\n  "createTime": 1782955344545,\n  "updateTime": 1784446270716,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/flowCount",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按流程实例状态统计审批流程数量，返回审批中心展示指标。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：10.统计流程统计\n// 路由：GET /sym/approval/query/flowCount\n// 业务说明：按流程实例状态统计审批流程数量，返回审批中心展示指标。\n/*\n * 审批中心 - 统计流程统计\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nlist = db.table("flow_instance").where().ne("flow_status",8).eq(\'business_id\',"order_000000000055").select()\n\n// 返回当前业务分支的标准结果。\nreturn  list[0]\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/10.统计流程统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ce1844634b80491c8aeb9c7da6ebec7e',NULL,NULL,'{\n  "properties": {},\n  "id": "ce1844634b80491c8aeb9c7da6ebec7e",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "11.资源申请分页",\n  "createTime": 1782955344554,\n  "updateTime": 1784657246159,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applyPage",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"pageNum\\": 1,\\n    \\"pageSize\\": 20,\\n    \\"sortField\\": \\"createdTime\\",\\n    \\"sortDir\\": \\"desc\\",\\n    \\"conditions\\": [\\n        {\\n            \\"field\\": \\"flowStatus\\",\\n            \\"value\\": \\"5\\",\\n            \\"type\\": \\"match\\"\\n        },\\n        {\\n            \\"field\\": \\"applyName\\",\\n            \\"value\\": \\"测试\\",\\n            \\"type\\": \\"like\\"\\n        }\\n    ]\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按请求目标与业务状态执行资源申请分页，返回本次操作结果；使用请求参数 pageNum、pageSize、sortField、sortDir、conditions；涉及 data_apply_form_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.资源申请分页\n// 路由：POST /sym/approval/query/applyPage\n// 业务说明：按请求目标与业务状态执行资源申请分页，返回本次操作结果；使用请求参数 pageNum、pageSize、sortField、sortDir、conditions；涉及 data_apply_form_t 等业务表。\n/*\n * 审批中心 - 资源申请分页\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport com.linewell.dataelement.elasticsearch.EsPageParam\nimport com.linewell.dataelement.elasticsearch.ConditionDTO\nimport "@post:/sym/user/me" as me;\nimport \'@/common/localCache\' as localCache\nimport jsons\nimport "@post:/dst/catalog/detail" as queryById\n\nvar userInfo = me()\nvar orgId = userInfo?.orgId\n\nbody == null ? body = {}: body\n\n// 从 MySQL 业务表读取当前有效数据。\ncount = db.table("data_apply_form_t").count();\nif(count == 0){\n  // 返回当前业务分支的标准结果。\n  return {\n        "pageNum": 1,\n        "pageSize": 20,\n        "total": 0,\n        "list":[]\n    }\n}\n\nEsPageParam es = new EsPageParam();\nes.setIndex("dataassets_apply_form");\n\n// 解析请求体并为可选参数设置默认值。\nvar pageNum = body?.pageNum::int(1)\nvar pageSize =  body?.pageSize::int(10)\nes.setPageNum(pageNum);\nes.setPageSize(pageSize);\n\nif(body?.sortField != null)\n{\n  es.setSortField(body?.sortField)\n}\nif(body?.sortDir != null)\n{\n  es.setSortDir(body?.sortDir)  \n}\n\nif(body?.conditions != null){\n    var list = new ArrayList();\n    var conditions = body?.conditions;\n    for(item in conditions){\n        var temp = new ConditionDTO()\n        temp.setField(item.field)\n        temp.setType(item.type)\n        temp.setValue(item.value)\n        list.add(temp)\n    }\n    es.setConditions(list)\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nexistInxex = esCommonService.indexExists("dataassets_apply_form");\nif(!existInxex){\n    // 返回当前业务分支的标准结果。\n    return {\n        "pageNum": 1,\n        "pageSize": 20,\n        "total": 0,\n        "list":[]\n    }\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nconst {total, list} = esCommonService.page(es);\n\nlist.forEach(item => {\n   if (item.catalogIds){\n        body = {tid: item.catalogIds}\n\n        var obj = item["detail"] = queryById();  \n\n        if (obj.assetType == "catalog"){\n            var res = []\n            !!obj.targetTableId && res.push("table")\n            !!obj.apiId && res.push("api")\n            !!obj.fileId && res.push("file")\n            !!obj.dirId && res.push("dir")\n            obj["resType"] = res\n            item["detail"]["resType"] = res\n        }\n\n        item.businessId = item.tid\n        // 从 MySQL 业务表读取当前有效数据。\n        var flowInfo = db.selectOne(`\n            SELECT\n              fd.flow_code,\n              fd.flow_name,\n              fi.business_id,\n              fi.id AS instance_id,\n              fi.definition_id AS definition_id,\n              ft.id AS task_id\n            FROM flow_instance fi\n            LEFT JOIN flow_definition fd\n              ON fi.definition_id = fd.id\n            LEFT JOIN flow_task ft\n              ON fi.id = ft.instance_id\n            WHERE\n              fi.business_id = \'${item.businessId}\'\n              AND fi.del_flag = \'0\'\n              AND fd.del_flag = \'0\'\n              AND ft.del_flag = \'0\'\n              AND ft.node_type = 1\n            ORDER BY ft.create_time DESC\n          `)\n        if (flowInfo){\n          item.taskId = flowInfo.taskId + ""\n          item.approveType = flowInfo.flowCode\n        }\n   }\n})\n\n// 返回当前业务分支的标准结果。\nreturn {\n  list, total\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/11.资源申请分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "a75efba824d64e6f9a3f12561f0a9f10",\n  "script": null,\n  "groupId": "208d0e4705354e9eba03d8d531396f82",\n  "name": "12.审批统计",\n  "createTime": 1785673588384,\n  "updateTime": 1786191951453,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "summary",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": null,\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "审批中心统计（GET /sym/approval/query/summary）。只读当前租户流程任务、实例和历史任务。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：12.审批统计\n// 路由：GET /sym/approval/query/summary\n// 业务说明：审批中心统计（GET /sym/approval/query/summary）。只读当前租户流程任务、实例和历史任务。\n// 审批统计：处理 GET summary 的核心查询和组装返回数据逻辑。\nimport approvalRuntime\nimport tenantRuntime\nvar principal = approvalRuntime.principal()\nvar tenantId = tenantRuntime.id()\nvar currentUserId = principal.userId\nvar permissionList = principal.permissionKeys\n\nvar todo = db.selectInt("""\n    select count(distinct t.id)\n      from flow_task t join flow_user u on u.associated = t.id\n     where t.tenant_id = #{tenantId} and u.tenant_id = #{tenantId}\n       and t.del_flag = \'0\' and u.del_flag = \'0\' and t.node_type = 1\n       and t.flow_status not in (\'4\', \'6\', \'8\')\n       and u.processed_by in\n       <foreach item="permission" collection="permissionList" open="(" separator="," close=")">#{permission}</foreach>\n""")\nvar process = db.selectInt("select count(*) from flow_instance where tenant_id = #{tenantId} and create_by = #{currentUserId} and del_flag = \'0\' and flow_status in (\'1\',\'9\')")\nvar done = db.selectInt("select count(distinct instance_id) from flow_his_task where tenant_id = #{tenantId} and approver = #{currentUserId} and del_flag = \'0\'")\nvar archive = db.selectInt("select count(*) from flow_instance where tenant_id = #{tenantId} and create_by = #{currentUserId} and del_flag = \'0\' and flow_status in (\'2\',\'4\',\'6\',\'8\')")\nreturn { todo, process, done, archive }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/12.审批统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('208d0e4705354e9eba03d8d531396f82',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "208d0e4705354e9eba03d8d531396f82",\r\n  "name" : "01.流程查询",\r\n  "type" : "api",\r\n  "parentId" : "b2bc4c16954544a69d4bcb4700dadce1",\r\n  "path" : "query",\r\n  "createTime" : 1781960049408,\r\n  "updateTime" : 1784446017728,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/01.流程查询/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b81216bf81ee41d8ad5d09526bf07703',NULL,NULL,'{\n  "properties": {},\n  "id": "b81216bf81ee41d8ad5d09526bf07703",\n  "script": null,\n  "groupId": "b2bc4c16954544a69d4bcb4700dadce1",\n  "name": "02.取消委托规则",\n  "createTime": 1786654822605,\n  "updateTime": 1786951315423,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delegation/delete",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "取消委托规则（POST /sym/approval/delegation/delete）。仅软删除当前租户当前用户自己的规则；使用请求参数 tid；涉及 wf_approval_delegation_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.取消委托规则\n// 路由：POST /sym/approval/delegation/delete\n// 业务说明：取消委托规则（POST /sym/approval/delegation/delete）。仅软删除当前租户当前用户自己的规则；使用请求参数 tid；涉及 wf_approval_delegation_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nif (body?.tid == null || body.tid == \'\') { exit -1, \'委托规则ID不能为空\' }\nvar principal = approvalRuntime.principal()\nvar tenantId = tenantRuntime.id()\nvar updated = db.update("""\n    update wf_approval_delegation_t\n       set is_del = 1, status = 0, updated_by = #{principal.userId}, updated_time = #{new Date()}\n     where tid = #{body.tid} and tenant_id = #{tenantId}\n       and delegator_user_id = #{principal.userId} and is_del = 0\n""")\nif (updated == 0) { exit -1, \'委托规则不存在或无权取消\' }\nreturn true\n',NULL,NULL,0,NULL,'/magic-api/api/09.系统管理/08.审批中心/02.取消委托规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/02.回调处理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c30f3718868148ce84e65217f49a7720',NULL,NULL,'{\n  "properties": {},\n  "id": "c30f3718868148ce84e65217f49a7720",\n  "script": null,\n  "groupId": "9f9e437fd903445f804353ea851c2fe5",\n  "name": "01.回调处理(节点处理结束回调)",\n  "createTime": 1782955344570,\n  "updateTime": 1784446270719,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/finshHandle",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "节点完成时按办理结果更新业务单与关联资产状态，并通知外部检索索引；回调可能由 Warm-Flow 内部触发。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：审批节点完成回调\n// 业务说明：节点完成时按办理结果更新业务单与关联资产状态，并通知外部检索索引；回调可能由 Warm-Flow 内部触发。\nimport approvalFlow\n\nif (body?.businessId == null || (\'\' + body.businessId).trim() == \'\') {\n    exit 500, \'businessId不能为空\'\n}\n\n// 业务状态和索引更新与引擎回调耦合，继续由 Java 事务/外部客户端完成。\nreturn approvalFlow.finshHandle(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/02.回调处理/01.回调处理(节点处理结束回调).ms');
