INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2e20af8a3d664efe8830927b3edc7ccc',NULL,NULL,'{\n  "properties": {},\n  "id": "2e20af8a3d664efe8830927b3edc7ccc",\n  "script": null,\n  "groupId": "d243e142e85d4a1ca63381f359831b8c",\n  "name": "01.根据userId获取流程权限",\n  "createTime": 1782955344583,\n  "updateTime": 1784446270720,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getPremissionById",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按会话中的人员和当前应用读取审批角色、机构、可处理权限；传入 appId 时改为查询该应用。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：查询当前人员的流程权限\n// 业务说明：按会话中的人员和当前应用读取审批角色、机构、可处理权限；传入 appId 时改为查询该应用。\n// 响应继续使用旧页面依赖的 id、roles、perms、orgId、orgIds 字段。\nimport cn.dev33.satoken.stp.StpUtil\nimport approvalRuntime\n\nvar userId = StpUtil.getLoginIdDefaultNull()\nif (userId == null) { exit -1, \'账号未登录或登录已过期\' }\n\n// 角色、机构和委托授权由同一个租户隔离的权限解析器计算，避免多处 SQL 算出不同结果。\nvar appId = body?.appId == null ? null : \'\' + body.appId\nvar principal = approvalRuntime.principalForApp(appId)\nvar organizationIds = principal.organizationIds == null ? [] : principal.organizationIds\n\nreturn {\n    id: \'\' + userId,\n    roles: principal.roleCodes,\n    perms: principal.permissionKeys,\n    orgId: organizationIds.size() == 0 ? null : organizationIds[0],\n    orgIds: organizationIds\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/03.基础信息/01.根据userId获取流程权限.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('52baada3264d4eb28ff0fc7bbc43c960',NULL,NULL,'{\n  "properties": {},\n  "id": "52baada3264d4eb28ff0fc7bbc43c960",\n  "script": null,\n  "groupId": "d243e142e85d4a1ca63381f359831b8c",\n  "name": "02.获取处理人角色机构",\n  "createTime": 1782955344593,\n  "updateTime": 1784446270721,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getAssignment",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "按登录人员与请求中的应用标识查询审批所需的角色、机构和权限键；应用未指定时采用会话应用。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：获取当前人员的处理权限资料\n// 业务说明：按登录人员与请求中的应用标识查询审批所需的角色、机构和权限键；应用未指定时采用会话应用。\nimport cn.dev33.satoken.stp.StpUtil\nimport approvalRuntime\n\nif (StpUtil.getLoginIdDefaultNull() == null) { exit -1, \'账号未登录或登录已过期\' }\n\nvar appId = body?.appId == null ? null : \'\' + body.appId\nreturn approvalRuntime.principalForApp(appId)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/03.基础信息/02.获取处理人角色机构.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b1dde9e625ac4f388dbd905b1aecbee2',NULL,NULL,'{\n  "properties": {},\n  "id": "b1dde9e625ac4f388dbd905b1aecbee2",\n  "script": null,\n  "groupId": "d243e142e85d4a1ca63381f359831b8c",\n  "name": "03.获取当前操作用户所有权限(后台调用)",\n  "createTime": 1782955344612,\n  "updateTime": 1784446270722,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "permissions",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "返回当前应用下本人、所属角色/机构及有效委托的权限键；未登录时返回空列表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：查询当前人员的流程权限键\n// 业务说明：返回当前应用下本人、所属角色/机构及有效委托的权限键；未登录时返回空列表。\nimport cn.dev33.satoken.stp.StpUtil\nimport approvalRuntime\n\nif (StpUtil.getLoginIdDefaultNull() == null) { return [] }\nreturn approvalRuntime.permissions()\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/03.基础信息/03.获取当前操作用户所有权限(后台调用).ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('approval_restore_asset_status_01',NULL,NULL,'{\n  "properties": {},\n  "id": "approval_restore_asset_status_01",\n  "script": null,\n  "groupId": "d243e142e85d4a1ca63381f359831b8c",\n  "name": "04.按流程单号恢复关联资产状态",\n  "path": "/restoreAssetStatusByFlowOrderId",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"flowOrderId\\": \\"流程单号\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "定位流程单关联资产，将登记或更新前的资产状态恢复并同步检索索引；只在明确调用时执行。"\n}\n================================\n// 接口：按流程单号恢复资产状态\n// 业务说明：定位流程单关联资产，将登记或更新前的资产状态恢复并同步检索索引；只在明确调用时执行。\nimport approvalFlow\n\nif (body?.flowOrderId == null || (\'\' + body.flowOrderId).trim() == \'\') {\n    exit -1, \'flowOrderId不能为空\'\n}\n\n// 资产持久化和 Elasticsearch 更新需要跨系统的补偿/事务逻辑，由框架服务执行。\nreturn approvalFlow.restoreAssetStatusByFlowOrderId(body)\n',NULL,NULL,0,NULL,'/magic-api/api/09.系统管理/08.审批中心/03.基础信息/04.按流程单号恢复关联资产状态.ms');
