INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8f4c71e2ae344e69a59682e86aed2661',NULL,NULL,'{\n  "properties": {},\n  "id": "8f4c71e2ae344e69a59682e86aed2661",\n  "script": null,\n  "groupId": "26a3fab0ca6147c19c07cd82345cc1fb",\n  "name": "01.办理",\n  "createTime": 1782955344620,\n  "updateTime": 1784446270723,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/handle",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"taskId\\": \\"2066790044328628225\\",\\n    \\"businessId\\": \\"order_000000000058\\",\\n    \\"handleType\\": \\"PASS\\",\\n    \\"message\\": \\"同意\\",\\n    \\"nodeCode\\": \\"测试\\",\\n    \\"approveType\\": \\"checkIn\\",\\n    \\"suggestionId\\": \\"838059686ff448d9afca95e9ad7b5906\\",\\n    \\"storageSuggestion\\": \\"1\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验任务标识和办理动作；普通动作完成任务，协作动作转办/委派/加签，由 Warm-Flow 原子写入节点、历史及资产状态。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：办理审批任务\n// 业务说明：校验任务标识和办理动作；普通动作完成任务，协作动作转办/委派/加签，由 Warm-Flow 原子写入节点、历史及资产状态。\nimport approvalFlow\n\nif (body?.taskId == null || (\'\' + body.taskId).trim() == \'\') { exit -1, \'taskId不能为空\' }\nvar action = body?.handleType == null ? \'\' : (\'\' + body.handleType).trim()\nvar allowed = [\'PASS\',\'UNPASS\',\'REJECT\',\'REVOKE\',\'TRANSFER\',\'DEPUTE\',\n               \'ADD_SIGNATURE\',\'REDUCTION_SIGNATURE\',\'TAKE_BACK\',\'PENDING\']\nif (!allowed.contains(action)) { exit -1, \'不支持的审批操作: \' + action }\n\n// 操作类型决定流程节点、回退状态和资产副作用，必须由引擎事务统一提交。\nreturn approvalFlow.handle(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/04.流程操作/01.办理.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c9342e84fe8a432082c56d6640e91049',NULL,NULL,'{\n  "properties": {},\n  "id": "c9342e84fe8a432082c56d6640e91049",\n  "script": null,\n  "groupId": "26a3fab0ca6147c19c07cd82345cc1fb",\n  "name": "02.启动",\n  "createTime": 1782955344640,\n  "updateTime": 1784446270724,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/start",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"flowType\\": \\"catalogSubscribe\\",\\n    \\"approveType\\": \\"catalogSubscribe\\",\\n    \\"flowOrderId\\": \\"30253579e54d4061bd95c7af602e17e7\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "受理流程启动请求；资产登记/更新可按当前审批模式直接通过或跳过，其余请求进入已发布的 Warm-Flow 定义并建立首个任务。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：启动审批流程\n// 业务说明：受理流程启动请求；资产登记/更新可按当前审批模式直接通过或跳过，其余请求进入已发布的 Warm-Flow 定义并建立首个任务。\nimport approvalFlow\n\nif (body == null) { exit -1, \'参数不能为空\' }\n\n// 流程引擎负责已发布定义校验、首节点入队以及当前人员和机构处理人解析。\n// 资产审批的 AUTO/OFF 分支也在同一事务服务中处理，避免 Magic 和引擎各写一半状态。\nreturn approvalFlow.start(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/04.流程操作/02.启动.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ee2487476fc7433c86de3b1ef8bbdba5',NULL,NULL,'{\n  "properties": {},\n  "id": "ee2487476fc7433c86de3b1ef8bbdba5",\n  "script": null,\n  "groupId": "26a3fab0ca6147c19c07cd82345cc1fb",\n  "name": "03.撤销",\n  "createTime": 1782955344652,\n  "updateTime": 1784446270725,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/revoke",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"3521505afe654916a146a1135a4a1203\\",\\n    \\"flowOrderId\\": \\"order_000000000603\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据资产记录和流程单号找到未结束的审批实例及首任务，执行 REVOKE 并同步关联资产状态。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：撤销审批流程\n// 业务说明：根据资产记录和流程单号找到未结束的审批实例及首任务，执行 REVOKE 并同步关联资产状态。\nimport approvalFlow\n\nif (body?.tid == null || (\'\' + body.tid).trim() == \'\') { exit -1, \'tid不能为空\' }\nif (body?.flowOrderId == null || (\'\' + body.flowOrderId).trim() == \'\') {\n    exit -1, \'flowOrderId不能为空\'\n}\n\n// 关联资产、实例和任务读取及撤销动作需要保持在同一流程服务边界内。\nreturn approvalFlow.revoke(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/04.流程操作/03.撤销.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d1a2e76b55c84370ab153b304a97b82d',NULL,NULL,'{\n  "properties": {},\n  "id": "d1a2e76b55c84370ab153b304a97b82d",\n  "script": null,\n  "groupId": "26a3fab0ca6147c19c07cd82345cc1fb",\n  "name": "04.终止",\n  "createTime": 1782955344660,\n  "updateTime": 1784446270726,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/termination",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"flow_order_id\\": \\"xxxx\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "核验流程实例标识，交由 Warm-Flow 终止实例并记录当前操作人和终止说明。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：终止审批流程\n// 业务说明：核验流程实例标识，交由 Warm-Flow 终止实例并记录当前操作人和终止说明。\nimport approvalFlow\n\nif (body?.instanceId == null || (\'\' + body.instanceId).trim() == \'\') {\n    exit -1, \'instanceId不能为空\'\n}\nreturn approvalFlow.termination(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/04.流程操作/04.终止.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('aa7ece2e7d394aea8e6d84b8c5ab1fb6',NULL,NULL,'{\n  "properties": {},\n  "id": "aa7ece2e7d394aea8e6d84b8c5ab1fb6",\n  "script": null,\n  "groupId": "26a3fab0ca6147c19c07cd82345cc1fb",\n  "name": "05.获取前驱节点(驳回使用)",\n  "createTime": 1782955344669,\n  "updateTime": 1784446270727,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "previousNodeList",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"definitionId\\": \\"2034456697161957377\\",\\n    \\"nodeCode\\": \\"d1ded9a6-c783-42dc-b4b1-55e8344cbd93\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据流程定义与当前节点，读取 Warm-Flow 允许退回的节点集合；无可用节点时明确报错。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：查询可退回的前驱节点\n// 业务说明：根据流程定义与当前节点，读取 Warm-Flow 允许退回的节点集合；无可用节点时明确报错。\nimport approvalFlow\n\nif (body?.definitionId == null || body?.nodeCode == null) {\n    exit -1, \'definitionId和nodeCode不能为空\'\n}\nreturn approvalFlow.previousNodeList(body)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/04.流程操作/05.获取前驱节点(驳回使用).ms');
