INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f058946e714846049e38be378047d1c6',NULL,NULL,'{\n  "properties": {},\n  "id": "f058946e714846049e38be378047d1c6",\n  "script": null,\n  "groupId": "86af6a92565d4dc38074fdc22b9127f6",\n  "name": "01.保存或修改流程",\n  "createTime": 1782955344677,\n  "updateTime": 1786191950313,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "saveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"flowName\\": \\"test\\",\\n    \\"flowCode\\": \\"test\\",\\n    \\"modelValue\\": \\"CLASSICS\\",\\n    \\"category\\": \\"测试\\",\\n    \\"listenerType\\": \\"app\\",\\n    \\"listenerPath\\": \\"测试\\",\\n    \\"id\\": \\"2036256483356024834\\",\\n    \\"version\\": \\"测试\\",\\n    \\"isPublish\\": true,\\n    \\"formCustom\\": \\"测试\\",\\n    \\"formPath\\": \\"测试\\",\\n    \\"activityStatus\\": 2,\\n    \\"tenantId\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "审批中心 - 保存或修改流程；使用请求参数 id、flowCode、flowName、modelValue、category、version、isPublish、formCustom；涉及 flow_definition 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.保存或修改流程\n// 路由：POST /sym/approval/config/saveOrUpdate\n// 业务说明：审批中心 - 保存或修改流程；使用请求参数 id、flowCode、flowName、modelValue、category、version、isPublish、formCustom；涉及 flow_definition 等业务表。\n/*\n * 审批中心 - 保存或修改流程\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport org.dromara.warm.flow.core.service.DefService as defService;\nimport cn.hutool.core.util.IdUtil\nimport "@post:/sym/user/me" as me\nimport tenantRuntime\n// 解析请求体并为可选参数设置默认值。\nvar id = body.id\nvar isUpdate = !!body.id\nif (!isUpdate){\n  id = IdUtil.getSnowflakeNextIdStr()\n}\n\nvar user = me\nvar tenantId = tenantRuntime.id()\n\n// 将校验后的业务数据写入 MySQL 主表。\nreturn db.table("flow_definition").primary("id").update({\n    id: id.asLong(),\n    flow_code: body.flowCode,\n    flow_name: body.flowName,\n    model_value: body.modelValue,\n    category: body.category,\n    version: body.version,\n    is_publish: body.isPublish,\n    form_custom: body.formCustom,\n    form_path: body.formPath,\n    activity_status: body.activityStatus,\n    listener_type: body.listenerType,\n    listener_path: body.listenerPath,\n    create_time: isUpdate ? null : new Date(),\n    create_by: "admin",\n    update_time: new Date(),\n    update_by: "admin",\n    tenant_id: tenantId,\n})\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/05.流程配置/01.保存或修改流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('03831b3087e643fca3665f5908ab126c',NULL,NULL,'{\n  "properties": {},\n  "id": "03831b3087e643fca3665f5908ab126c",\n  "script": null,\n  "groupId": "86af6a92565d4dc38074fdc22b9127f6",\n  "name": "02.导入流程",\n  "createTime": 1782955344686,\n  "updateTime": 1784446270728,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/import",\n  "method": "POST",\n  "parameters": [\n    {\n      "name": "file",\n      "value": null,\n      "description": "真实数据示例参数：file",\n      "required": false,\n      "dataType": "MultipartFile",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "校验请求资料后执行导入流程，返回保存或配置结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.导入流程\n// 路由：POST /sym/approval/config/import\n// 业务说明：校验请求资料后执行导入流程，返回保存或配置结果。\n// 核心业务逻辑：按接口约定编排当前请求并返回业务处理结果。\n/*\n * 审批中心 - 导入流程\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport org.dromara.warm.flow.core.service.DefService as defService;\n\ndefService.importIs(file.getInputStream());\nreturn;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/05.流程配置/02.导入流程.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('169959dd8fb148e68b4cfe4644f63c76',NULL,NULL,'{\n  "properties": {},\n  "id": "169959dd8fb148e68b4cfe4644f63c76",\n  "script": null,\n  "groupId": "86af6a92565d4dc38074fdc22b9127f6",\n  "name": "03.流程定义列表",\n  "createTime": null,\n  "updateTime": 1786191950796,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"pageNum\\":1,\\"pageSize\\":20,\\"keyword\\":\\"\\",\\"publishStatus\\":\\"\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "读取审批中心可用的流程定义，返回发起流程时可选择的定义清单。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.流程定义列表\n// 路由：POST /sym/approval/config/list\n// 业务说明：读取审批中心可用的流程定义，返回发起流程时可选择的定义清单。\n// 流程定义列表：处理 POST list 的核心查询和组装返回数据逻辑。\nimport approvalRuntime\nimport tenantRuntime\nvar principal = approvalRuntime.principal()\nvar tenantId = tenantRuntime.id()\nvar pageNum = body?.pageNum::long(1)\nvar pageSize = body?.pageSize::long(20)\nvar offset = (pageNum - 1) * pageSize\nvar keyword = body?.keyword\nvar publishStatus = body?.publishStatus\n\nvar result = db.page("""\n    select id, flow_code, flow_name, model_value, category, version,\n           is_publish, activity_status, form_custom, form_path,\n           create_by, update_by, create_time, update_time\n      from flow_definition\n     where tenant_id = #{tenantId} and del_flag = \'0\'\n       <if test="keyword != null and keyword != \'\'">\n         and (flow_code like concat(\'%\', #{keyword}, \'%\') or flow_name like concat(\'%\', #{keyword}, \'%\'))\n       </if>\n       <if test="publishStatus != null and publishStatus != \'\'">and is_publish = #{publishStatus}</if>\n     order by update_time desc, create_time desc\n""", pageSize, offset)\nresult.list = result.list || []\nresult.list.each(item -> item.id = item.id + "")\nreturn result\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/05.流程配置/03.流程定义列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c07b80ac993947689394afcb66e3efba',NULL,NULL,'{\n  "properties": {},\n  "id": "c07b80ac993947689394afcb66e3efba",\n  "script": null,\n  "groupId": "86af6a92565d4dc38074fdc22b9127f6",\n  "name": "04.流程操作",\n  "createTime": 1782955344704,\n  "updateTime": 1784446270733,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/exec",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"id\\": \\"2036256483356024834\\",\\n    \\"action\\": \\"copy\\",\\n    \\"file\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "根据 action 与流程标识调用审批流程服务执行对应操作，并返回操作结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.流程操作\n// 路由：POST /sym/approval/config/exec\n// 业务说明：根据 action 与流程标识调用审批流程服务执行对应操作，并返回操作结果。\n/*\n * 审批中心 - 流程操作\n * 本接口属于 /sym/approval 下的独立 Warm-Flow 基础能力。\n * 数据资产登记步骤不会自动调用或自动提交本接口。\n */\nimport org.dromara.warm.flow.core.service.DefService as defService;\nimport response;\nimport org.springframework.cglib.beans.BeanMap;\n\n// 解析请求体并为可选参数设置默认值。\nvar id = body.id;\naction = body.action;\n\nif (!action) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit - 1, "请指定操作"\n}\nif (!id){\n  // 参数或业务状态不满足要求时立即终止请求。\n  exit - 1, "流程定义id不能为空"\n}\n// 从 MySQL 业务表读取当前有效数据。\nvar flow = db.table("flow_definition").where().eq("id", id).selectOne()\nif (!flow) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit - 1, "不存在此流程定义"\n}\nflow.id = flow.id+""\nid = id.asLong();\n\nif (action == \'detail\'){\n    // 返回当前业务分支的标准结果。\n    return flow\n}\n\nif (action == \'export\'){\n    var json = defService.exportJson(id);\n    // 返回当前业务分支的标准结果。\n    return response.download(json,  flow.flowCode + \'.json\');\n}\n\nif (action == \'import\'){\n    defService.importIs(body.file.getInputStream());\n    return;\n}\n\nif (action == \'copy\'){\n    // 返回当前业务分支的标准结果。\n    return defService.copyDef(id);\n}\n\nif (action == \'publish\'){\n    // 返回当前业务分支的标准结果。\n    return defService.publish(id);\n}\n\nif (action == \'unPublish\'){\n    // 返回当前业务分支的标准结果。\n    return defService.unPublish(id);\n}\n\nif (action == \'unActive\'){\n    // 返回当前业务分支的标准结果。\n    return defService.unActive(id);\n}\n\nif (action == \'active\'){\n    // 返回当前业务分支的标准结果。\n    return defService.active(id);\n}\n\nif (action == \'delete\'){\n    // 返回当前业务分支的标准结果。\n    return defService.removeDef([id]);\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/05.流程配置/04.流程操作.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('86af6a92565d4dc38074fdc22b9127f6',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "86af6a92565d4dc38074fdc22b9127f6",\r\n  "name" : "05.流程配置",\r\n  "type" : "api",\r\n  "parentId" : "b2bc4c16954544a69d4bcb4700dadce1",\r\n  "path" : "config",\r\n  "createTime" : 1781960049983,\r\n  "updateTime" : 1784446017745,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}\n================================\n\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/08.审批中心/05.流程配置/group.json');
