INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b81216bf81ee41d8ad5d09526bf07702',NULL,NULL,'{\n  "properties": {},\n  "id": "b81216bf81ee41d8ad5d09526bf07702",\n  "script": null,\n  "groupId": "approval_delegation_group_01",\n  "name": "01.保存审批委托",\n  "createTime": 1786757000000,\n  "updateTime": 1786951315863,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delegation/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"delegateUserId\\": \\"受托人ID\\",\\n  \\"startTime\\": \\"2026-08-14 09:00:00\\",\\n  \\"endTime\\": \\"2026-08-15 18:00:00\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\n  \\"tid\\": \\"委托规则ID\\"\\n}",\n  "description": "保存审批委托规则（POST /sym/approval/delegation/save）。受托人归属由控制库身份服务校验，委托规则写入当前租户库；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 delegateUserId、startTime、endTime、flowCode、reason；涉及 wf_approval_delegation_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.保存审批委托\n// 路由：POST /sym/approval/delegation/save\n// 业务说明：保存审批委托规则（POST /sym/approval/delegation/save）。受托人归属由控制库身份服务校验，委托规则写入当前租户库；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 delegateUserId、startTime、endTime、flowCode、reason；涉及 wf_approval_delegation_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nimport tenantAccounts\nimport cn.hutool.core.util.IdUtil\n\n\nif (body?.delegateUserId == null || body.delegateUserId == \'\') { exit -1, \'请选择受托人\' }\nif (body?.startTime == null || body?.endTime == null) { exit -1, \'请选择委托有效期\' }\nvar principal = approvalRuntime.principal()\nvar tenantId = tenantRuntime.id()\nif (body.delegateUserId == principal.userId) { exit -1, \'不能委托给自己\' }\n\n// Membership is stored only in the control schema, never in the tenant database.\nif (!tenantAccounts.hasMembership(tenantId, body.delegateUserId + \'\')) {\n    exit -1, \'受托人不属于当前租户\'\n}\n\nvar overlap = db.selectInt("""\n    select count(*) from wf_approval_delegation_t\n     where tenant_id = #{tenantId}\n       and delegator_user_id = #{principal.userId}\n       and delegate_user_id = #{body.delegateUserId}\n       and is_del = 0 and status = 1\n       and start_time <= #{body.endTime} and end_time >= #{body.startTime}\n       <if test="body.flowCode != null and body.flowCode != \'\'">and (flow_code = #{body.flowCode} or flow_code is null)</if>\n""")\nif (overlap > 0) { exit -1, \'该时间段已存在重叠委托\' }\n\nvar now = new Date()\nvar id = IdUtil.getSnowflakeNextIdStr()\ndb.table(\'wf_approval_delegation_t\').insert({\n    tid: id,\n    tenant_id: tenantId,\n    delegator_user_id: principal.userId,\n    delegate_user_id: body.delegateUserId,\n    flow_code: body?.flowCode,\n    start_time: body.startTime,\n    end_time: body.endTime,\n    reason: body?.reason,\n    status: 1,\n    created_by: principal.userId,\n    updated_by: principal.userId,\n    created_time: now,\n    updated_time: now,\n    is_del: 0\n})\nreturn { tid: id }\n',NULL,NULL,0,NULL,'/magic-api/api/09.系统管理/08.审批中心/06.委托与催办/01.保存审批委托.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b81216bf81ee41d8ad5d09526bf07701',NULL,NULL,'{\n  "properties": {},\n  "id": "b81216bf81ee41d8ad5d09526bf07701",\n  "script": null,\n  "groupId": "approval_delegation_group_01",\n  "name": "02.审批委托列表",\n  "createTime": 1786757000000,\n  "updateTime": 1786951315648,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/delegation/list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[]",\n  "description": "查询当前用户的审批委托规则（GET /sym/approval/delegation/list）。委托规则读取当前租户库，受托人姓名由控制库身份服务批量补充；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 wf_approval_delegation_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.审批委托列表\n// 路由：GET /sym/approval/delegation/list\n// 业务说明：查询当前用户的审批委托规则（GET /sym/approval/delegation/list）。委托规则读取当前租户库，受托人姓名由控制库身份服务批量补充；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；涉及 wf_approval_delegation_t 等业务表。\nimport tenantRuntime\nimport approvalRuntime\nimport tenantAccounts\n\n\nvar principal = approvalRuntime.principal()\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId = tenantRuntime.id()\nvar rows = db.select("""\n    select d.tid, d.delegate_user_id, d.flow_code, d.start_time, d.end_time,\n           d.reason, d.status, d.created_time\n      from wf_approval_delegation_t d\n     where d.tenant_id = #{tenantId}\n       and d.delegator_user_id = #{principal.userId}\n       and d.is_del = 0\n     order by d.status desc, d.end_time desc\n""")\nvar names = tenantAccounts.names(rows == null ? [] : rows.map(item => item.delegateUserId))\nif (rows != null) {\n    rows.each(item -> item.delegateUserName = names[item.delegateUserId] || item.delegateUserId)\n}\nreturn rows || []\n',NULL,NULL,0,NULL,'/magic-api/api/09.系统管理/08.审批中心/06.委托与催办/02.审批委托列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('178666420950631242',NULL,NULL,'{\n  "id": "approval_delegation_group_01",\n  "name": "委托与催办",\n  "parentId": "b2bc4c16954544a69d4bcb4700dadce1",\n  "type": "api"\n}',NULL,NULL,0,NULL,'/magic-api/api/09.系统管理/08.审批中心/06.委托与催办/group.json');
