INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b5dd6283a2af4141ac6e53d31ed8f507',NULL,NULL,'{\n  "properties": {},\n  "id": "b5dd6283a2af4141ac6e53d31ed8f507",\n  "script": null,\n  "groupId": "49db77c12b24426ebf245e20ecb5b28e",\n  "name": "01.动态表单配置",\n  "createTime": null,\n  "updateTime": 1786498770383,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/form",\n  "method": "POST",\n  "parameters": [\n    {\n      "name": "action",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "get",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\"formName\\":\\"登记库\\",\\"env\\":\\"公安\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "动态表单配置（POST /sym/form）。表单定义按当前登录租户从对应业务库读取和保存。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.动态表单配置\n// 路由：POST /sym/form\n// 业务说明：动态表单配置（POST /sym/form）。表单定义按当前登录租户从对应业务库读取和保存。\n// 动态表单配置：处理 POST /form 的核心写入或状态变更逻辑。\nimport tenantForm\n\nvar validActions = [\'save\', \'delete\', \'get\']\nif (!validActions.contains(action)) {\n    exit -1, \'操作类型不合法，仅支持save/delete/get\'\n}\n\nvar request = body == null ? {} : body\nif (action == \'get\') {\n    return tenantForm.list(request.formName, request.env, request.tid)\n}\nif (action == \'save\') {\n    return tenantForm.save(request)\n}\nreturn tenantForm.delete(request.tid)\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/12.动态表单/01.动态表单配置.ms');
