INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fa5e60254452443a8d512df21c6eed53',NULL,NULL,'{\n  "properties": {},\n  "id": "fa5e60254452443a8d512df21c6eed53",\n  "script": null,\n  "groupId": "9668e1a8b17d458f8739c9558d60ca98",\n  "name": "01.数据字典查询",\n  "createTime": 1782660715884,\n  "updateTime": 1790479749699,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dict",\n  "method": "GET",\n  "parameters": [\n    {\n      "name": "code",\n      "value": "db",\n      "description": "字典编码；db 返回当前数据源选项，app 返回当前部门应用系统",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": "",\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [\n    {\n      "name": "code",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据字典查询（GET /sym/dict），只读接口。code=db 从 db_datasource_t 的 Elasticsearch 查询投影读取数据源，code=app 从应用系统投影读取并按当前登录部门过滤，code=catalog 读取目录资产；其他编码读取 sym_dict_t。请求示例：code=db；涉及 sym_application_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": {\n    "name": "",\n    "value": "",\n    "description": "",\n    "required": false,\n    "dataType": "Object",\n    "type": null,\n    "defaultValue": null,\n    "validateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "100120",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "您访问的内容需要登录账号后才能查看",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：01.数据字典查询\n// 路由：GET /sym/dict\n// 业务说明：数据字典查询（GET /sym/dict），只读接口。code=db 从 db_datasource_t 的 Elasticsearch 查询投影读取数据源，code=app 从应用系统投影读取并按当前登录部门过滤，code=catalog 读取目录资产；其他编码读取 sym_dict_t。请求示例：code=db；涉及 sym_application_t 等业务表。\nimport "@post:/dst/application/list" as applicationList;\nimport "@post:/dst/database/list" as databaseList;\nimport "@post:/dst/catalog/list" as assetList;\nimport "@post:/sym/org/getOrgTree" as ssoOrg;\nimport "@post:/sym/getDict" as getDict;\nimport "@post:/sym/user/me" as me;\nimport \'@/common/configData\' as configData\n\nif (code){\n    if (code === "app"){\n        // 编辑态必须以当前租户的应用主数据为准，不能依赖有索引延迟或缺项的 ES 列表。\n        var applications = db.table(\'sym_application_t\').where()\n            .eq(\'is_del\', 0).orderBy(\'sort_no\').select()\n        return applications.map(el => ({\n            label: el.appName || el.app_name,\n            value: el.tid,\n            assetStatus: el.assetStatus || el.asset_status,\n            ...el,\n            icon: el.assetType || \'app\'\n        }));\n    }\n    if (code === "db"){\n        // 数据源来自 db_datasource_t 的 ES 查询投影，不复用数据目录接口。\n        body = {}\n        return databaseList().map(el => ({\n            label: el.dbName || el.database || el.name,\n            value: el.tid || el.id,\n            assetStatus: el.assetStatus,\n            ...el,\n            icon: el.assetType || "db"\n        }));\n    }\n    if (code === "catalog"){\n        body = {"assetType": "catalog"}\n        // 返回当前业务分支的标准结果。\n        return assetList().map(el => ({label: el.catalogName, value: el.tid, assetStatus: el.assetStatus, ...el, icon: el.assetType}));\n    }\n    if (code === "org"){\n        body = {"parentId":configData().orgRootId}\n        return ssoOrg();\n    }\n    // 指定字典编码只返回当前租户的选项数组，不能落入下方全量字典分类分支。\n    // storageDomain 优先读取当前租户的新字典；公安等历史租户仍使用 SSWL 时再兼容回退。\n    var readDict = (dictCode) => {\n        body = {dictCode: dictCode}\n        try {\n            return getDict();\n        } catch (e) {\n            return []\n        }\n    }\n    var hasItems = (items) => {\n        if (items == null) { return false }\n        for (item in items) { return true }\n        return false\n    }\n    var dictItems = readDict(code)\n    if (code === "storageDomain" && !hasItems(dictItems)) {\n        dictItems = readDict("SSWL")\n    }\n    return dictItems || []\n}\n\n// 加载部门数据\nbody = {"parentId":configData().orgRootId}\nconst orgs = ssoOrg();\n\nbody = {"parentId": "0"}\nvar dicts = getDict()\nvar dictMap = {\n  // ...dictGa(),\n  "org": {\n    "label": "部门",\n    "options": orgs\n  },\n  "app": {\n    "label": "业务系统",\n    "options": null\n  },\n  "db": {\n    "label": "数据源",\n    "options": null\n  },\n  "catalog": {\n    "label": "数据目录",\n    "options": null\n  },\n  "broadcast_root": {\n    "label": "全部字典",\n    "options": null\n  }\n}\n\nfor (item in dicts) {\n    dictMap[item.dictCode] = {\n        label: item.dictName,\n        options: item.children\n    }\n}\n// 返回当前业务分支的标准结果。\nreturn dictMap\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/01.数据字典查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f7622ea4ac5547af954ae35a3ab56826',NULL,NULL,'{\n  "properties": {},\n  "id": "f7622ea4ac5547af954ae35a3ab56826",\n  "script": null,\n  "groupId": "9668e1a8b17d458f8739c9558d60ca98",\n  "name": "02.字典树查询",\n  "createTime": 1782955148933,\n  "updateTime": 1786191954494,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getDict",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "字典数据查询接口（树形结构）；使用请求参数 tid、parentId、dictCode、dictName、levelNo、isDel、showRow；涉及 sym_dict_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.字典树查询\n// 路由：POST /sym/getDict\n// 业务说明：字典数据查询接口（树形结构）；使用请求参数 tid、parentId、dictCode、dictName、levelNo、isDel、showRow；涉及 sym_dict_t 等业务表。\nimport tenantRuntime\n/**\n * 字典数据查询接口（树形结构）\n * 二级字典为字典类型，其dictCode 要唯一\n * GET /api/dict/query\n *\n * 满足需求：\n * 1. 根据 level_no 查询字典类型\n * 2. 根据 dict_code 查询【该节点 + 所有下级字典树】\n *\n * 调用示例：\n * /api/dict/query?dictCode=tv_program_type\n * 返回：电视节目类型 + 新闻类、综艺类、影视剧...\n */\n\n// 1. 参数获取\nvar tid = body?.tid || query?.tid\nvar parentId = body?.parentId || query?.parentId\nvar dictCode = body?.dictCode || query?.dictCode\nvar dictName = body?.dictName || query?.dictName\nvar levelNo = body?.levelNo || query?.levelNo\nvar tenantId = tenantRuntime.id()\nvar isDel = body?.isDel || query?.isDel\nvar showRow = body?.showRow // 返回列表结构，而非树形结构\n\nif (isDel == null) {\n    isDel = 0\n}\nconst toTree = (list, rootId) => {\n    const map = {}\n    list.forEach(i => {i.children = []; map[i.tid] = i})\n\n    // 返回当前业务分支的标准结果。\n    return list.filter(i => {\n        const p = map[i.parentId || root]\n        p ? p.children.push(i) : null\n        // 返回当前业务分支的标准结果。\n        return !p\n    }).sort((a, b) => a.sortNo - b.sortNo)\n}\n\n\n// =====================================================================\n// 有父节点，即根据 dicCode、parentId查询\n// =====================================================================\nvar rootNode;\nif (dictCode) {\n    // 1. 先查当前 dictCode 对应的节点\n    rootNode = db.table(\'sym_dict_t\')\n        .where()\n        .eq(\'is_del\', isDel)\n        .eq(\'dict_code\', dictCode)\n        .orderBy(\'sort_no\')\n        .selectOne()\n\n    if (!rootNode) {\n        // 页面侧可选字典缺失时返回空数组，不能因为一个字典项缺失阻断页面加载。\n        return []\n    }\n}\n\nif (parentId) {\n    // 从 MySQL 业务表读取当前有效数据。\n    rootNode = db.table(\'sym_dict_t\')\n        .where()\n        .eq(\'is_del\', isDel)\n        .eq(\'tid\', parentId)\n        .orderBy(\'sort_no\')\n        .selectOne()\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar list = db.table(\'sym_dict_t\')\n            .excludes(["updatedTime", "updatedBy", "createdTime", "createdBy", "isDel", "tenantId"])\n            .where()\n            .eq(\'is_del\', isDel)\n\n\nif (dictName) {\n    list = list.like(\'dict_name\', \'%\' + dictName + \'%\')\n}\n\n// 有根节点\nif (rootNode){\n    // 根据 tree_path 查询所有子孙节点（核心！）\n    var rows = list\n        .like(\'tree_path\', rootNode.treePath + \'.%\')\n        .orderBy(\'sort_no\')\n        .select()\n    rows.each(item => {\n        item.label = item.dictName\n        item.value = item.dictCode\n    })\n    // 返回当前业务分支的标准结果。\n    return showRow ? rows : toTree(rows, rootNode.tid)\n}\n\n// 多个根节点\nif (levelNo) {\n    list = list.eq(\'level_no\', levelNo)\n}\n\n// 单个节点\nif (tid) {\n    list = list.eq(\'tid\', tid)\n}\n\nvar rows = list.orderBy(\'sort_no\').select() || []\n\nrows.each(item => {\n    item.label = item.dictName\n    item.value = item.dictCode\n})\n\n// 返回当前业务分支的标准结果。\nreturn rows\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/02.字典树查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('05715b7dbe1b4bf5a0015cd11431a45a',NULL,NULL,'{\n  "properties": {},\n  "id": "05715b7dbe1b4bf5a0015cd11431a45a",\n  "script": null,\n  "groupId": "9668e1a8b17d458f8739c9558d60ca98",\n  "name": "03.字典保存修改",\n  "createTime": 1782660715681,\n  "updateTime": 1786191954954,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dictSaveOrUpdate",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"5cb5dade27db44bdbfe53d9d9bd01b76\\",\\n    \\"dictName\\": \\"1\\",\\n    \\"dictCode\\": \\"111\\",\\n    \\"parentId\\": \\"e9731ceff80a4d54be2fb3d06ddc207d\\",\\n    \\"sortNo\\": 0,\\n    \\"levelNo\\": 3,\\n    \\"treePath\\": \\"0.e9731ceff80a4d54be2fb3d06ddc207d.5cb5dade27db44bdbfe53d9d9bd01b76\\",\\n    \\"tagType\\": \\"app\\",\\n    \\"icon\\": \\"align\\",\\n    \\"children\\": [\\n    ],\\n    \\"hasChildren\\": true\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "数据字典 sym_dict_t 新增、修改、删除；使用请求参数 action、tid、dictName、dictCode、parentId、sortNo、levelNo、treePath。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.字典保存修改\n// 路由：POST /sym/dictSaveOrUpdate\n// 业务说明：数据字典 sym_dict_t 新增、修改、删除；使用请求参数 action、tid、dictName、dictCode、parentId、sortNo、levelNo、treePath。\nimport log\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\n/**\n * 数据字典 sym_dict_t 新增、修改、删除\n * POST /api/dict/saveOrUpdate\n * \n * 根据 action 或 tid 判断操作类型：\n *   - action=\'delete\' 且 tid 有值 → 逻辑删除\n *   - tid 有值 → 修改\n *   - tid 无值 → 新增\n * \n * 请求示例：\n * 新增: { "dict_name": "xxx", "dict_code": "xxx", "parent_id": "0", "sort_no": 1, "tenant_id": "xxx" }\n * 修改: { "tid": "xxx", "dict_name": "xxx", "dict_code": "xxx", "sort_no": 1 }\n * 删除: { "action": "delete", "tid": "xxx" }\n */\n\n// 获取请求参数\nvar action = body?.action\nvar tid = body?.tid\nvar dictName = body?.dictName\nvar dictCode = body?.dictCode\nvar parentId = body?.parentId\nvar sortNo = body?.sortNo\nvar levelNo = body?.levelNo\nvar treePath = body?.treePath\nvar tenantId = tenantRuntime.id()\nvar icon = body?.icon\nvar tagType = body?.tagType\nvar dictDesc = body?.dictDesc\nvar bizType = body?.bizType\nvar createdBy = body?.createdBy ? body?.createdBy : "system"\nvar updatedBy = body?.updatedBy ? body?.updatedBy : "system"\n\nvar now = new Date()\n\n// ========== 删除操作 ==========\nif (action == "delete") {\n    if (tid == null || tid == \'\') {\n        // 返回当前业务分支的标准结果。\n        return {\n            code: 400,\n            success: false,\n            message: "删除时 tid 不能为空"\n        }\n    }\n    \n    // 从 MySQL 业务表读取当前有效数据。\n    var delResult = db.table(\'sym_dict_t\')\n        .where()\n        .eq(\'tid\', tid)\n        .eq(\'is_del\', 0)\n        .update({\n            is_del: 1,\n            updated_by: updatedBy,\n            updated_time: date_format(now)\n        })\n    \n    log.info(\'字典逻辑删除成功, tid: {}\', tid)\n    return\n}\n\n// ========== 新增或修改 ==========\nvar isUpdate = tid != null && tid != \'\'\n\nif (isUpdate) {\n    // ========== 修改 ==========\n    var updateData = {\n        tid: tid,\n        updated_by: updatedBy,\n        updated_time: date_format(now)\n    }\n    if (dictName != null) {\n        updateData.dict_name = dictName\n    }\n    if (dictCode != null) {\n        updateData.dict_code = dictCode\n    }\n    if (parentId != null) {\n        updateData.parent_id = parentId\n    }\n    if (sortNo != null) {\n        updateData.sort_no = sortNo\n    }\n    if (levelNo != null) {\n        updateData.level_no = levelNo\n    }\n    if (treePath != null) {\n        updateData.tree_path = treePath\n    }\n    if (tenantId != null) {\n        updateData.tenant_id = tenantId\n    }\n    if (dictDesc != null) {\n        updateData.dict_desc = dictDesc\n    }\n    if (icon != null) {\n        updateData.icon = icon\n    }\n    if (tagType != null) {\n        updateData.tag_type = tagType\n    }\n    if (bizType != null) { updateData.biz_type = bizType }\n    \n    // 从 MySQL 业务表读取当前有效数据。\n    var updateResult = db.table(\'sym_dict_t\')\n        .where()\n        .eq(\'tid\', tid)\n        .update(updateData, true)\n    \n    if (updateResult == 0) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "更新的记录不存在或已删除"\n    }\n    \n    log.info(\'字典修改成功, tid: {}\', tid)\n    // 返回当前业务分支的标准结果。\n    return true\n} else {\n    // ========== 新增 ==========\n    if (!dictName || !dictCode) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "新增时 dictName或dictCode 不能为空"\n    }\n    \n    tid = IdUtil.getSnowflakeNextIdStr()\n\n    \n    // 计算 level_no 和 tree_path\n    var level = 1\n    var path = tid\n    if (!parentId){\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "parentId不能为空";\n    }\n\n    // 判断该父级字典下是否有相同dictCode\n    var isExist = db.table(\'sym_dict_t\')\n            .where()\n            .like(\'tree_path\', "%"+ parentId +"%")\n            .eq(\'dict_code\', dictCode)\n            .eq(\'is_del\', 0)\n            .selectOne();\n    if (isExist){\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "当前字典类型下存在相同的字典code"\n    }\n\n\n    // 从 MySQL 业务表读取当前有效数据。\n    var parent = db.table(\'sym_dict_t\')\n        .where()\n        .eq(\'tid\', parentId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n        if (parent == null) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, "parentId参数错误";\n        }   \n    \n    if (parent) {\n        var parentLevel = parent.levelNo ? parent.levelNo : 1\n        var parentPath = parent.treePath ? parent.treePath : parentId\n        level = parentLevel + 1\n        path = parentPath + \'.\' + tid\n    }\n    // }\n    // }\n    \n    var sortVal = 0\n    if (sortNo != null) {\n        sortVal = sortNo.toString()::int(0)\n    }\n    \n    // 从 MySQL 业务表读取当前有效数据。\n    db.table(\'sym_dict_t\')\n        .primary(\'tid\')\n        .insert({\n            tid: tid,\n            dict_name: dictName,\n            dict_code: dictCode != null ? dictCode : dictName,\n            parent_id: parentId != null ? parentId : \'root\',\n            sort_no: sortVal,\n            level_no: level,\n            tree_path: path,\n            icon: icon,\n            dict_desc: dictDesc,\n            biz_type: bizType,\n            tag_type: tagType,\n            created_by: createdBy,\n            created_time: date_format(now),\n            updated_by: updatedBy,\n            updated_time: date_format(now),\n            is_del: 0,\n            tenant_id: tenantId\n        })\n    \n    log.info(\'字典新增成功, tid: {}, dict_name: {}\', tid, dictName)\n    // 返回当前业务分支的标准结果。\n    return {"tid":tid}\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/03.字典保存修改.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fa050435331a44da84dafa64d74d39c5',NULL,NULL,'{\n  "properties": {},\n  "id": "fa050435331a44da84dafa64d74d39c5",\n  "script": null,\n  "groupId": "9668e1a8b17d458f8739c9558d60ca98",\n  "name": "04.字典拖拽排序",\n  "createTime": 1782660715695,\n  "updateTime": 1784437771321,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dictDragSort",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"tid\\": \\"4929b4a49206483e81ea9501fe6e670a\\",\\n    \\"targetParentId\\": \\"0\\",\\n    \\"targetTid\\": \\"ca77c1b09d344090baff16c2070bd02d\\",\\n    \\"dropType\\": \\"after\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "- tid:            被拖拽节点 ID（必填）；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.字典拖拽排序\n// 路由：POST /sym/dictDragSort\n// 业务说明：- tid:            被拖拽节点 ID（必填）；执行数据库写入并返回处理结果。\n// 树节点拖拽排序接口\n// 路径: /dictDragSort\n// 方法: POST\n// 入参:\n//   - tid:            被拖拽节点 ID（必填）\n//   - targetParentId: 拖拽完成后归属的父节点 ID（根节点传 \'0\'）\n//   - targetTid:      参照目标节点 ID（必填）\n//   - dropType:       放置类型：before / after / inner（必填）\n\nvar tid            = body?.tid || \'\';\nvar targetParentId = body?.targetParentId || \'0\';\nvar targetTid      = body?.targetTid || \'\';\nvar dropType       = body?.dropType || \'\';\n\n// ========== 1. 参数校验 ==========\nif (tid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'tid 不能为空\';\n}\nif (dropType == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'dropType 不能为空\';\n}\nif (dropType != \'before\' && dropType != \'after\' && dropType != \'inner\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'dropType 必须为 before/after/inner\';\n}\nif (targetTid == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'targetTid 不能为空\';\n}\n\n// ========== 2. 查询被拖拽节点 ==========\nvar curNode = db.lower().table("sym_dict_t")\n    .where().eq("tid", tid).eq("is_del", 0).selectOne();\nif (curNode == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'被拖拽节点不存在: \' + tid;\n}\n\n// ========== 3. 防循环嵌套校验 ==========\n// 若 dropType = inner，需确保 tid 不在 targetTid 的子孙链中\nif (dropType == \'inner\' && targetTid != \'0\') {\n    var checkTid = targetTid;\n    var hasCycle = false;\n    while (checkTid != null && checkTid != \'\' && checkTid != \'0\') {\n        if (checkTid == tid) {\n            hasCycle = true;\n            break;\n        }\n        // 从 MySQL 业务表读取当前有效数据。\n        var parentNode = db.lower().table("sym_dict_t")\n            .where().eq("tid", checkTid).eq("is_del", 0).selectOne();\n        if (parentNode == null) { break; }\n        checkTid = parentNode.parent_id;\n    }\n    if (hasCycle) {\n        // 参数或业务状态不满足要求时立即终止请求。\n        exit 500, \'不能将节点拖拽到其子孙节点下，会导致循环嵌套\';\n    }\n}\n\n// ========== 4. 查询参照目标节点 ==========\nvar targetNode = db.lower().table("sym_dict_t")\n    .where().eq("tid", targetTid).eq("is_del", 0).selectOne();\nif (targetNode == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'参照目标节点不存在: \' + targetTid;\n}\n\n// ========== 5. 执行拖拽 ==========\ntry {\n    // 目标父节点的 tree_path\n    var newParentTreePath = \'\';\n    if (targetParentId == \'0\' || targetParentId == \'root\') {\n        newParentTreePath = \'0\';\n    } else {\n        // 从 MySQL 业务表读取当前有效数据。\n        var newParentNode = db.lower().table("sym_dict_t")\n            .where().eq("tid", targetParentId).eq("is_del", 0).selectOne();\n        if (newParentNode != null) {\n            newParentTreePath = newParentNode.tree_path || targetParentId;\n        } else {\n            newParentTreePath = targetParentId;\n        }\n    }\n\n    // 查询参照目标节点的所有同级子节点（排除已删除和自身）\n    var targetSiblings = db.lower().table("sym_dict_t")\n        .where().eq("parent_id", targetParentId).eq("is_del", 0)\n        .ne("tid", tid).orderBy("sort_no").select();\n\n    var insertIdx = 0;\n    if (dropType == \'inner\') {\n        // inner: 成为目标节点子节点，排在最后\n        var targetChildren = db.lower().table("sym_dict_t")\n            .where().eq("parent_id", targetTid).eq("is_del", 0)\n            .ne("tid", tid).orderBy("sort_no").select();\n        insertIdx = targetChildren.size();\n        // 替换 siblings 为目标节点的子节点列表\n        targetSiblings = targetChildren;\n        targetParentId = targetTid;\n        newParentTreePath = targetNode.tree_path || targetTid;\n    } else {\n        // before / after: 同级插入，找到目标节点在 siblings 中的位置\n        var targetIdx = -1;\n        var idxCounter = 0;\n        for (s in targetSiblings) {\n            if (s.tid == targetTid) {\n                targetIdx = idxCounter;\n                break;\n            }\n            idxCounter = idxCounter + 1;\n        }\n        if (targetIdx < 0) {\n            // 目标不在 siblings 中（理论上不会发生），插入末尾\n            insertIdx = targetSiblings.size();\n        } else if (dropType == \'before\') {\n            insertIdx = targetIdx;\n        } else {\n            // after\n            insertIdx = targetIdx + 1;\n        }\n    }\n\n    // 在 insertIdx 位置插入被拖拽节点\n    var newChildren = [];\n    var inserted = false;\n    var ciCounter = 0;\n    for (s in targetSiblings) {\n        if (ciCounter == insertIdx && !inserted) {\n            newChildren.push(tid);\n            inserted = true;\n        }\n        newChildren.push(s.tid);\n        ciCounter = ciCounter + 1;\n    }\n    // 如果插入位置在末尾\n    if (!inserted) {\n        newChildren.push(tid);\n    }\n\n    // ========== 6. 批量更新 sort_no ==========\n    var sortCounter = 0;\n    for (childTid in newChildren) {\n        sortCounter = sortCounter + 1;\n        var newSortNo = sortCounter;\n        if (childTid == tid) {\n            // 更新被拖拽节点：parent_id + sort_no + level_no + tree_path\n            var newLevelNo = 1;\n            if (targetParentId != \'root\') {\n                // 从 MySQL 业务表读取当前有效数据。\n                var parentNode2 = db.lower().table("sym_dict_t")\n                    .where().eq("tid", targetParentId).eq("is_del", 0).selectOne();\n                if (parentNode2 != null) {\n                    newLevelNo = (parentNode2.level_no || 1) + 1;\n                } else {\n                    newLevelNo = 2;\n                }\n            }\n            var newTreePath = newParentTreePath + \'.\' + tid;\n            db.lower().table("sym_dict_t").primary("tid").update({\n                tid: tid,\n                parent_id: targetParentId,\n                sort_no: newSortNo,\n                level_no: newLevelNo,\n                tree_path: newTreePath\n            });\n        } else {\n            // 更新同级其他节点：仅 sort_no\n            db.lower().table("sym_dict_t").primary("tid").update({\n                tid: childTid,\n                sort_no: newSortNo\n            });\n        }\n    }\n\n    // ========== 7. 更新被拖拽节点所有子孙的 tree_path ==========\n    var oldTreePath = curNode.tree_path || \'\';\n    var newTreePathForUpdate = newParentTreePath + \'.\' + tid;\n\n    if (oldTreePath != \'\' && oldTreePath != newTreePathForUpdate) {\n        // 从 MySQL 业务表读取当前有效数据。\n        var descendants = db.lower().table("sym_dict_t")\n            .where().like("tree_path", oldTreePath + \'.%\').eq("is_del", 0).select();\n        for (node in descendants) {\n            var nodeOldPath = node.tree_path || \'\';\n            var nodeNewPath = nodeOldPath.replace(oldTreePath, newTreePathForUpdate);\n            db.lower().table("sym_dict_t").primary("tid").update({\n                tid: node.tid,\n                tree_path: nodeNewPath\n            });\n        }\n    }\n\n    // 返回当前业务分支的标准结果。\n    return true;\n} catch(e) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 500, \'拖拽排序失败: \' + e.message;\n}\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/04.字典拖拽排序.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2cd6a8dd790e4ac3aa16622893d90a47',NULL,NULL,'{\n  "properties": {},\n  "id": "2cd6a8dd790e4ac3aa16622893d90a47",\n  "script": null,\n  "groupId": "9668e1a8b17d458f8739c9558d60ca98",\n  "name": "05.字典导入",\n  "createTime": 1782660716008,\n  "updateTime": 1784437771345,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dict-import",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n    \\"dicts\\": \\"测试\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "说明: 将所有字典定义批量初始化插入 sym_dict_t 表（幂等：先清空再插入）；使用请求参数 dicts。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.字典导入\n// 路由：POST /sym/dict-import\n// 业务说明：说明: 将所有字典定义批量初始化插入 sym_dict_t 表（幂等：先清空再插入）；使用请求参数 dicts。\n// 初始化字典数据\n// 路径: /api/sym/initDict\n// 方法: GET\n// 说明: 将所有字典定义批量初始化插入 sym_dict_t 表（幂等：先清空再插入）\n\nimport "@post:/sym/getDict" as getDict;\nimport cn.hutool.core.util.IdUtil;\n\nvar now = new Date();\n\n\n// 解析请求体并为可选参数设置默认值。\nvar dicts = body.dicts || {\n    "sceneType": {\n        tid: "ddddddd",\n        "label": "应用场景类型",\n        "options": [\n            {\n                "tagType": "primary",\n                "label": "数据查询",\n                "value": "0"\n            },\n            {\n                "tagType": "warning",\n                "label": "统计分析",\n                "value": "1"\n            },\n            {\n                "tagType": "success",\n                "label": "业务流程支撑",\n                "value": "2",\n                "children": []\n            }\n        ]\n    },\n}  \n// -------------------------------------------------------\n// 构建插入记录\n// -------------------------------------------------------\n// 递归辅助：将树形节点及其 children 展开为平铺记录\n// parentTid: 父节点 tid; items: 当前层节点数组; parentPath: 父节点 tree_path; levelNo: 当前层级\nvar result = [];\nvar buildTree = (parentTid, items, parentPath, levelNo) => {\n  var sortIdx = 0;\n  for (node in items) {\n    var nodeTid = node.tid || IdUtil.getSnowflakeNextIdStr();\n    var hasChildren = (node.children != null && node.children.size() > 0);\n    result.push({\n      tid: nodeTid,\n      dict_name: node.label,\n      dict_code: node.value.asString(),\n      dict_desc: node.dictDesc,\n      parent_id: parentTid,\n      sort_no: sortIdx + 1,\n      level_no: levelNo,\n      tree_path: parentPath + \'.\' + nodeTid,\n      created_by: \'system\',\n      created_time: now,\n      updated_by: \'system\',\n      updated_time: now,\n      is_del: 0,\n      tag_type: (node.tagType != null && node.tagType != \'\') ? node.tagType : null,\n      icon: (node.icon != null && node.icon != \'\') ? node.icon : null,\n      biz_type: (node.bizType != null && node.bizType != \'\') ? node.bizType : null,\n    });\n    sortIdx = sortIdx + 1;\n    // 如果有 children，递归继续展开\n    if (hasChildren) {\n      buildTree(nodeTid, node.children, parentPath + \'.\' + nodeTid, levelNo + 1);\n    }\n  }\n};\n\nfor (dictCode in dicts.keySet()) {\n  var dict = dicts[dictCode];\n  var parentTid = dict.tid || IdUtil.getSnowflakeNextIdStr();\n  var parentPath = \'0.\' + parentTid;\n  result.push({\n    tid: parentTid,\n    dict_name: dict.label,\n    dict_code: dictCode,\n    dict_desc: dict.dictDesc,\n    parent_id: \'0\',\n    sort_no: 0,\n    level_no: 2,\n    tree_path: parentPath,\n    created_by: \'system\',\n    created_time: now,\n    updated_by: \'system\',\n    updated_time: now,\n    is_del: 0,\n    tag_type: dict.tagType,\n    icon: dict.icon,\n    biz_type: dict.bizType,\n  });\n\n  // 检测 options 是否为树形（第一项有 children 属性）\n  var options = dict.options;\n  if (options.size() > 0 && options[0].children != null) {\n    // 树形结构：递归展开，起始 level_no=3\n    buildTree(parentTid, options, parentPath, 3);\n  } else {\n    // 平铺结构：直接遍历插入 level_no=3\n    var sortIdx = 0;\n    for (item in options) {\n      var childTid = item.tid || IdUtil.getSnowflakeNextIdStr();\n      result.push({\n        tid: childTid,\n        dict_name: item.label,\n        dict_code: item.value.asString(),\n        dict_desc: item.dict_desc,\n        parent_id: parentTid,\n        sort_no: sortIdx + 1,\n        level_no: 3,\n        tree_path: parentPath + \'.\' + childTid,\n        created_by: \'system\',\n        created_time: now,\n        updated_by: \'system\',\n        updated_time: now,\n        is_del: 0,\n        tag_type: (item.tagType != null && item.tagType != \'\') ? item.tagType : null,\n        icon: (item.icon != null && item.icon != \'\') ? item.icon : null,\n        biz_type: (item.bizType != null && item.bizType != \'\') ? item.bizType : null,\n      });\n      sortIdx = sortIdx + 1;\n    }\n  }\n}\n// 返回当前业务分支的标准结果。\nreturn result\n\nif (result.size() == 0){\n  // 返回当前业务分支的标准结果。\n  return null;\n}\n// -------------------------------------------------------\n// 执行批量插入\n// -------------------------------------------------------\ndb.table(\'sym_dict_t\')\n  .primary(\'tid\')\n  .batchInsert(result);\n\n// 返回当前业务分支的标准结果。\nreturn {\n  code: 200,\n  message: \'字典初始化成功\',\n  total: result.size()\n};\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/05.字典导入.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9668e1a8b17d458f8739c9558d60ca98',NULL,'api','{\n  "properties" : { },\n  "id" : "9668e1a8b17d458f8739c9558d60ca98",\n  "name" : "13.数据字典",\n  "type" : "api",\n  "parentId" : "9a18bf0b6a994f5aa56aa775f3de9f3d",\n  "path" : "",\n  "createTime" : 1785575697736,\n  "updateTime" : 1785575697736,\n  "createBy" : "codex",\n  "updateBy" : "codex",\n  "paths" : [ ],\n  "options" : [ ]\n}\n================================\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/09.系统管理/13.数据字典/group.json');
