INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('tenant_list_magic_01',NULL,NULL,'{\n  "properties": {},\n  "id": "tenant_list_magic_01",\n  "script": null,\n  "groupId": "d28618bcdcca47279ce2c6f513002948",\n  "name": "01.租户列表",\n  "createTime": 1787162475819,\n  "updateTime": 1787182300277,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"pageNum\\": 1,\\n  \\"pageSize\\": 20,\\n  \\"keyword\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "POST /sym/tenant/list，分页查询租户；使用请求参数 pageNum、pageSize、keyword。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.租户列表\n// 路由：POST /sym/tenant/list\n// 业务说明：POST /sym/tenant/list，分页查询租户；使用请求参数 pageNum、pageSize、keyword。\nimport tenantRuntime\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar rowValue = (row, keys) => {\n  for (key in keys) {\n    if (row != null && row[key] != null) {\n      return row[key]\n    }\n  }\n  return null\n}\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar currentTenantId = text(tenantRuntime.id())\nif (currentTenantId == \'\') {\n  exit 401, \'未获取到当前租户\'\n}\nvar pageNum = body == null || body.pageNum == null ? 1 : body.pageNum::int\nvar pageSize = body == null || body.pageSize == null ? 20 : body.pageSize::int\npageNum = pageNum < 1 ? 1 : pageNum\npageSize = pageSize < 1 ? 20 : (pageSize > 200 ? 200 : pageSize)\nvar keyword = text(body == null ? null : body.keyword).toLowerCase()\nvar rows = []\n// 以下从 baseline 业务表读取或维护当前操作涉及的记录。\nfor (item in db.table(\'baseline.sym_tenant_t\').where().eq(\'is_del\', 0).orderBy(\'sort_no\',\'asc\').orderBy(\'created_time\',\'asc\').select()) {\n  var itemText = (text(rowValue(item,[\'code\'])) + \' \' + text(rowValue(item,[\'name\']))).toLowerCase()\n  if (keyword == \'\' || itemText.contains(keyword)) {\n    rows.add({ tid: rowValue(item,[\'tid\']), code: rowValue(item,[\'code\']), name: rowValue(item,[\'name\']), status: rowValue(item,[\'status\']), initFlag: rowValue(item,[\'initFlag\',\'init_flag\']), isolationMode: rowValue(item,[\'isolationMode\',\'isolation_mode\']), jsonConfig: rowValue(item,[\'jsonConfig\',\'json_config\']), sortNo: rowValue(item,[\'sortNo\',\'sort_no\']), createdTime: rowValue(item,[\'createdTime\',\'created_time\']), updatedTime: rowValue(item,[\'updatedTime\',\'updated_time\']) })\n  }\n}\nvar from = (pageNum - 1) * pageSize\nif (from > rows.size()) {\n  from = rows.size()\n}\nvar to = from + pageSize\nif (to > rows.size()) {\n  to = rows.size()\n}\nreturn { list: rows.subList(from,to), total: rows.size(), pageNum: pageNum, pageSize: pageSize }\n',NULL,NULL,0,'00000000000000000000000000000000','/magic-api/api/09.系统管理/14.租户管理/01.租户列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('tenant_save_magic_01',NULL,NULL,'{\n  "properties": {},\n  "id": "tenant_save_magic_01",\n  "script": null,\n  "groupId": "d28618bcdcca47279ce2c6f513002948",\n  "name": "02.保存租户",\n  "createTime": 1787162475891,\n  "updateTime": 1787182300446,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"tid\\": \\"\\",\\n  \\"code\\": \\"TENANT_CODE\\",\\n  \\"name\\": \\"租户名称\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "POST /sym/tenant/save，新增或维护租户；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 tid、code、name、status、sortNo、isolationMode、jsonConfig；执行数据库写入并返回处理结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.保存租户\n// 路由：POST /sym/tenant/save\n// 业务说明：POST /sym/tenant/save，新增或维护租户；公安LOCAL账号使用本地库与令牌会话，其他租户保留原机制；使用请求参数 tid、code、name、status、sortNo、isolationMode、jsonConfig；执行数据库写入并返回处理结果。\nimport cn.hutool.json.JSONUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport tenantRuntime\n\n\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar rowValue = (row, keys) => {\n  for (key in keys) {\n    if (row != null && row[key] != null) {\n      return row[key]\n    }\n  }\n  return null\n}\nvar currentTenantId = text(tenantRuntime.id())\nif (currentTenantId == \'\') {\n  exit 401, \'未获取到当前租户\'\n}\nvar operator = text(StpUtil.getLoginId())\nvar now = new Date()\nvar tenantRecordId = text(body == null ? null : body.tid)\nvar code = text(body == null ? null : body.code).toUpperCase()\nvar name = text(body == null ? null : body.name)\nif (code == \'\' || name == \'\') {\n  exit 400, \'租户编码和租户名称不能为空\'\n}\nif (!code.matches(\'[A-Z0-9_-]{2,64}\')) {\n  exit 400, \'租户编码仅允许大写字母、数字、下划线和短横线\'\n}\nvar status = body != null && (body.status == 0 || body.status == \'0\') ? 0 : 1\nvar sortNo = body == null || body.sortNo == null ? 0 : body.sortNo::int\nvar isolationMode = text(body == null ? null : body.isolationMode)\nif (isolationMode == \'\') {\n  isolationMode = \'ROW\'\n}\nif (isolationMode != \'ROW\' && isolationMode != \'DATABASE\') {\n  exit 400, \'隔离模式仅支持 ROW 或 DATABASE\'\n}\nvar jsonConfig = text(body == null ? null : body.jsonConfig)\nvar duplicate = db.table(\'baseline.sym_tenant_t\').where().eq(\'code\',code).eq(\'is_del\',0).selectOne()\nif (duplicate != null && (tenantRecordId == \'\' || text(duplicate.tid) != tenantRecordId)) {\n  exit 400, \'租户编码已存在\'\n}\nif (tenantRecordId == \'\') {\n  tenantRecordId = IdUtil.getSnowflakeNextIdStr()\n  db.table(\'baseline.sym_tenant_t\').primary(\'tid\').insert({ tid:tenantRecordId, code:code, name:name, init_flag:0, json_config:jsonConfig == \'\' ? null : jsonConfig, sort_no:sortNo, created_time:now, created_by:operator, updated_time:now, updated_by:operator, is_del:0, tenant_id:tenantRecordId, status:status, isolation_mode:isolationMode })\n} else {\n  var existed = db.table(\'baseline.sym_tenant_t\').where().eq(\'tid\',tenantRecordId).eq(\'is_del\',0).selectOne()\n  if (existed == null) {\n    exit 404, \'租户不存在或已删除\'\n  }\n  // Changing an account source requires a migration, never an ordinary tenant-settings save.\n  var previousConfig=JSONUtil.parseObj(rowValue(existed,[\'jsonConfig\',\'json_config\'])||\'{}\');\n  var nextConfig=JSONUtil.parseObj(jsonConfig==\'\'?\'{}\':jsonConfig);\n  if(previousConfig.containsKey(\'accountSource\')) {nextConfig.set(\'accountSource\',previousConfig.get(\'accountSource\'));}\n  else {nextConfig.remove(\'accountSource\');}\n  jsonConfig=JSONUtil.toJsonStr(nextConfig);\n  db.table(\'baseline.sym_tenant_t\').primary(\'tid\').update({ tid:tenantRecordId, code:code, name:name, json_config:jsonConfig == \'\' ? null : jsonConfig, sort_no:sortNo, updated_time:now, updated_by:operator, status:status, isolation_mode:isolationMode }, true)\n}\nreturn { tid: tenantRecordId }\n',NULL,NULL,0,'00000000000000000000000000000000','/magic-api/api/09.系统管理/14.租户管理/02.保存租户.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('tenant_user_page_magic_01',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "tenant_user_page_magic_01",\n  "script": null,\n  "groupId": "d28618bcdcca47279ce2c6f513002948",\n  "name": "03.用户租户分页",\n  "createTime": 1787162475917,\n  "updateTime": 1787184457874,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/user-page",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"targetTenantId\\": \\"目标租户ID\\",\\n  \\"keyword\\": \\"\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 targetTenantId、keyword。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.用户租户分页\n// 路由：POST /sym/tenant/user-page\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 targetTenantId、keyword。\nimport tenantAccounts;\nimport tenantRuntime;\nvar current=tenantRuntime.id();var target=(body?.targetTenantId||current)+\'\';\nif(target!=current) {exit 403,\'本地账号只能查询所属应用\';}\nvar rows=tenantAccounts.list(current,body?.keyword);\nreturn {list:rows.map(u=>({userId:u.id,userName:u.userName,realName:u.realName,phone:u.phone,assigned:true,defaultTenant:true})),total:rows.size(),accountSource:\'LOCAL\'};\n',NULL,NULL,0,'00000000000000000000000000000000','/magic-api/api/09.系统管理/14.租户管理/03.用户租户分页.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('tenant_assign_user_magic_01',NULL,NULL,'{\n  "properties": {\n    "localAccountRetirement": "v1"\n  },\n  "id": "tenant_assign_user_magic_01",\n  "script": null,\n  "groupId": "d28618bcdcca47279ce2c6f513002948",\n  "name": "04.保存用户租户关联",\n  "createTime": 1787162475946,\n  "updateTime": 1787184457941,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/assign-user",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\n  \\"targetTenantId\\": \\"目标租户ID\\",\\n  \\"userId\\": \\"用户ID\\"\\n}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 targetTenantId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.保存用户租户关联\n// 路由：POST /sym/tenant/assign-user\n// 业务说明：应用独立本地账号接口；业务规则由租户账号 Magic 函数执行。共享控制库账号及成员关系分支已退役；使用请求参数 targetTenantId。\nimport tenantRuntime;\nvar current=tenantRuntime.id();var target=(body?.targetTenantId||current)+\'\';\nif(target!=current) {exit 403,\'禁止跨应用维护账号\';}\nexit 409,\'账号直接归属本应用，请通过用户管理维护，无需配置共享成员关系\';\n',NULL,NULL,0,'00000000000000000000000000000000','/magic-api/api/09.系统管理/14.租户管理/04.保存用户租户关联.ms');
