dateType": "",\n    "error": "",\n    "expression": "",\n    "children": [\n      {\n        "name": "code",\n        "value": "-1",\n        "description": "",\n        "required": false,\n        "dataType": "Integer",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "msg",\n        "value": "服务暂时不可用，请检查网络连接或稍后再试",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "desc",\n        "value": "org.ssssssss.script.exception.MagicScriptException: 不支持的类型:class java.lang.String at Row:5~5,Col:10~30\\n\\n        .in(key?key:\\"tid\\", id)\\r\\n         ^^^^^^^^^^^^^^^^^^^^^ ",\n        "description": "",\n        "required": false,\n        "dataType": "String",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "success",\n        "value": "false",\n        "description": "",\n        "required": false,\n        "dataType": "Boolean",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      },\n      {\n        "name": "data",\n        "value": "null",\n        "description": "",\n        "required": false,\n        "dataType": "Object",\n        "type": null,\n        "defaultValue": null,\n        "validateType": "",\n        "error": "",\n        "expression": "",\n        "children": []\n      }\n    ]\n  }\n}\n================================\n// 接口：02.删除数据操作\n// 路由：DELETE /data/delete\n// 业务说明：按目标标识和当前状态执行删除数据操作，返回处理结果。\nimport java.util.Arrays;\n\n// 从 MySQL 业务表读取当前有效数据。\nvar result = db.table(tableName)\n        .where()\n        .in(key?key:"tid", Arrays.asList(id.split(",")))\n        .delete();\n\n// 返回当前业务分支的标准结果。\nreturn result;\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/10.通用数据操作/02.删除数据操作.ms');
