       "expression": "",\n        "children": [\n          {\n            "name": "",\n            "value": "",\n            "description": "",\n            "required": false,\n            "dataType": "Object",\n            "type": null,\n            "defaultValue": null,\n            "validateType": "",\n            "error": "",\n            "expression": "",\n            "children": [\n              {\n                "name": "colName",\n                "value": "12",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              },\n              {\n                "name": "colEn",\n                "value": "12",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              },\n              {\n                "name": "colType",\n                "value": "5",\n                "description": "",\n                "required": false,\n                "dataType": "String",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expression": "",\n                "children": []\n              },\n              {\n                "name": "colLength",\n                "value": "12",\n                "description": "",\n                "required": false,\n                "dataType": "Integer",\n                "type": null,\n                "defaultValue": null,\n                "validateType": "",\n                "error": "",\n                "expre