INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('799fcf05408b4d539a81ae65de0b3aa3',NULL,'api','{\n  "properties": {},\n  "id": "3f8671cf46bf332cbc87d93f0874d648",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "01.达梦业务库连通性",\n  "path": "/ods-health",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "验证智能搜索中心原有达梦业务库连接与剧目数据量。"\n}\n================================\n// 接口：01.达梦业务库连通性\n// 路由：GET /search/ods-health\n// 业务说明：验证智能搜索中心原有达梦业务库连接与剧目数据量。\nimport tenantRuntime;\nimport flowDataSource;\nvar tenantId=tenantRuntime.id();\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\');\nvar ods=db[sourceKey];\nreturn {tenantId:tenantId,dataSource:sourceKey,dramaCount:ods.selectInt(\'select count(*) from JC_DRAMA\')};\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/01.达梦业务库连通性.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1c5145c0554f4450bbc50e439bc5ade5',NULL,'api','{\n  "properties": {},\n  "id": "1087e21423643d4cad7d20e6364a4216",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "02.当前租户概览",\n  "path": "/overview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取当前租户的应用、数据源和数据表数量。"\n}\n================================\n// 接口：02.当前租户概览\n// 路由：GET /search/overview\n// 业务说明：读取当前租户的应用、数据源和数据表数量。\nimport tenantRuntime;\nvar tenantId=tenantRuntime.id();\nvar countSafely=(tableName)=>{try{return db.table(tableName).where({is_del:0}).count();}catch(error){return 0;}};\nreturn {tenantId:tenantId,metrics:{applications:countSafely(\'sym_application_t\'),datasources:countSafely(\'db_datasource_t\'),tables:countSafely(\'db_table_t\')}};\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/02.当前租户概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('52166acd5769444eb1a016f4bfd8d223',NULL,'api','{\n  "properties": {},\n  "id": "b1f927b6b5e134f2be07d52381540b7c",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "03.数据源清单",\n  "path": "/sources",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取当前租户已登记的数据源；涉及 db_datasource_t 等业务表。"\n}\n================================\n// 接口：03.数据源清单\n// 路由：GET /search/sources\n// 业务说明：读取当前租户已登记的数据源；涉及 db_datasource_t 等业务表。\nimport tenantRuntime;\nvar tenantId=tenantRuntime.id();\ntry{var items=db.table(\'db_datasource_t\').where({is_del:0}).select();return {tenantId:tenantId,items:items,total:items.size()};}catch(error){return {tenantId:tenantId,items:[],total:0};}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/03.数据源清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ca7c08e7bd8b49d8bda05b21633d41af',NULL,'api','{\n  "properties": {},\n  "id": "13dc2c3a16fe321b898f2828770b7671",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "04.数据资产统计",\n  "path": "/assets",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取当前租户的数据资产统计。"\n}\n================================\n// 接口：04.数据资产统计\n// 路由：GET /search/assets\n// 业务说明：读取当前租户的数据资产统计。\nimport tenantRuntime;\nvar tenantId=tenantRuntime.id();\nvar countSafely=(tableName)=>{try{return db.table(tableName).where({is_del:0}).count();}catch(error){return 0;}};\nreturn {tenantId:tenantId,metrics:{catalogs:countSafely(\'da_catalog_t\'),tables:countSafely(\'db_table_t\'),columns:countSafely(\'db_table_column_t\')}};\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/04.数据资产统计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('03ce1e897f814a0fa21fc87024ef2bff',NULL,'api','{\n  "properties": {},\n  "id": "a6d5af9c71f53a8382fb954d5da47d26",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "05.门户页面数据",\n  "createTime": null,\n  "updateTime": 1789857884530,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/portal-view",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "兼容原门户页面数据契约，从当前租户 Elasticsearch 门户读模型读取；达梦 linewell_ods 是其唯一投影来源。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.门户页面数据\n// 路由：GET /search/portal-view\n// 业务说明：兼容原门户页面数据契约，从当前租户 Elasticsearch 门户读模型读取；达梦 linewell_ods 是其唯一投影来源。\nimport tenantRuntime\nimport searchEs\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nif(tenantId==null||(\'\'+tenantId).trim()==\'\'){throw new IllegalStateException(\'登录会话缺少租户信息，请重新登录\')}\nvar tenantKey=(\'\'+tenantId).toLowerCase()\nvar portalRead=\'jcc-search-portal-\'+tenantKey+\'-read\'\nif(!searchEs.exists(portalRead)){throw new IllegalStateException(\'门户搜索索引尚未就绪，请先执行“搜索索引全量重建”\')}\nvar response=searchEs.search(portalRead,{size:10000,track_total_hits:true,query:{match_all:{}}})\nvar hits=response.hits==null?[]:response.hits.hits\nvar institutions=[];var dramas=[];var awards=[];var records=[]\nfor(hit in hits){\n var doc=hit._source\n if(doc.entityType==\'org\'){\n  var orgType=doc.orgType==null?\'social\':(\'\'+doc.orgType).toLowerCase();if([\'production\',\'transmission\',\'broadcast\',\'social\'].indexOf(orgType)<0){orgType=\'social\'}\n  institutions.add({id:doc.id,name:doc.name==null?\'\':doc.name,shortName:doc.shortName==null||doc.shortName==\'\'?doc.name:doc.shortName,entityType:\'org\',type:orgType,level:doc.level==null?\'待确认\':doc.level,establishedYear:doc.establishedYear==null?0:doc.establishedYear,legalPerson:doc.legalPerson==null?\'\':doc.legalPerson,creditCode:doc.creditCode==null?\'\':doc.creditCode,scope:doc.scope==null?\'\':doc.scope,region:doc.region==null?\'\':doc.region,tags:doc.tags==null?[]:doc.tags,dataQuality:0,activeYears:doc.activeYears==null?0:doc.activeYears,transmissionMode:[],updatedAt:doc.updatedAt})\n }else if(doc.entityType==\'drama\'){\n  var links=doc.awardLinks==null?[]:doc.awardLinks;for(link in links){records.add(link)}\n  dramas.add({id:doc.id,title:doc.title==null||doc.title==\'\'?doc.name:doc.title,entityType:\'drama\',genre:doc.genre==null?\'\':doc.genre,episodes:doc.episodes==null?0:doc.episodes,year:doc.year==null?0:doc.year,region:doc.region==null?\'\':doc.region,status:doc.status==null?\'待播\':doc.status,synopsis:doc.synopsis==null?\'\':doc.synopsis,tags:doc.tags==null?[]:doc.tags,doubanScore:0,rating:0,productionOrgIds:doc.productionOrgIds==null?[]:doc.productionOrgIds,broadcastOrgIds:doc.broadcastOrgIds==null?[]:doc.broadcastOrgIds,transmissionOrgIds:doc.transmissionOrgIds==null?[]:doc.transmissionOrgIds,awards:links,credits:[],license:{distributionNo:\'\',filingNo:\'\',filingDate:\'\',productionNo:\'\',copyright:doc.copyright==null?\'\':doc.copyright,duration:doc.duration==null?\'\':doc.duration,verified:false},dataQuality:0,updatedAt:doc.updatedAt})\n }else if(doc.entityType==\'award\'){\n  var hosts=doc.hostOrgIds==null?[]:doc.hostOrgIds\n  awards.add({id:doc.id,name:doc.name==null?\'\':doc.name,shortName:doc.shortName==null||doc.shortName==\'\'?doc.name:doc.shortName,entityType:\'award\',level:doc.level==null?\'行业级\':doc.level,hostOrgId:hosts.size()==0?\'\':hosts[0],hostOrgIds:hosts,founded:doc.founded==null?0:doc.founded,cycle:doc.cycle==null?\'\':doc.cycle,desc:doc.description==null?\'\':doc.description,region:doc.region==null?\'\':doc.region,dataQuality:0,updatedAt:doc.updatedAt})\n }\n}\nvar stats={dramaCount:dramas.size(),orgCount:institutions.size(),awardCount:awards.size(),reviewRecordCount:records.size(),wonRecordCount:records.filter(item=>item.result==\'获奖\').size(),orgCounts:{production:institutions.filter(item=>item.type==\'production\').size(),transmission:institutions.filter(item=>item.type==\'transmission\').size(),broadcast:institutions.filter(item=>item.type==\'broadcast\').size(),social:institutions.filter(item=>item.type==\'social\').size()},source:\'elasticsearch\',tenantId:tenantId,index:portalRead}\nvar libraries={};for(id in [\'production\',\'transmission\',\'broadcast\',\'social\',\'drama\',\'award\']){libraries[id]={id:id,title:id==\'drama\'?\'剧目档案库\':id==\'award\'?\'评审评奖库\':\'机构资料库\',desc:\'Elasticsearch 门户读模型，来源为达梦 linewell_ods\',coverage:\'原业务库\',updatedAt:new Date()+\'\',recordLabel:id==\'drama\'?\'剧目\':id==\'award\'?\'奖项\':\'机构\',recordCount:id==\'drama\'?dramas.size():id==\'award\'?awards.size():institutions.filter(item=>item.type==id).size(),tables:[]}}\nvar hotOrgs=institutions.subList(0,institutions.size()>8?8:institutions.size());var hotDramas=dramas.subList(0,dramas.size()>8?8:dramas.size());var hotAwards=awards.subList(0,awards.size()>8?8:awards.size())\nreturn {snapshot:{institutions:institutions,dramas:dramas,awards:awards,stats:stats},home:{hot:{all:[],org:hotOrgs.map(item=>item.name),drama:hotDramas.map(item=>item.title),award:hotAwards.map(item=>item.name)},changes:[]},graphs:{},libraries:libraries,analysis:{recordCount:records.size(),records:records}}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/05.门户页面数据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('65182eb20086417db38fc5ee4027dc28',NULL,'api','{\n  "properties": {},\n  "id": "cdf552bb6a86329bb82c74b5b04c94d2",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "06.门户版本",\n  "path": "/portal-revision",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取达梦业务数据版本标识。"\n}\n================================\n// 接口：06.门户版本\n// 路由：GET /search/portal-revision\n// 业务说明：读取达梦业务数据版本标识。\nimport flowDataSource;\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\');\nvar ods=db[sourceKey];\nreturn {revision:ods.selectInt(\'select count(*) from JC_ENTITY\'),generation:\'linewell_ods\'};\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/06.门户版本.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3bddb5ea07cf4c1fbaa18e7dd28a8ee4',NULL,'api','{\n  "properties": {},\n  "id": "a153768b92a93407984c700348294a51",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "07.门户联想",\n  "path": "/portal-suggestions",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取达梦业务库的门户搜索联想。"\n}\n================================\n// 接口：07.门户联想\n// 路由：GET /search/portal-suggestions\n// 业务说明：读取达梦业务库的门户搜索联想。\nimport flowDataSource\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar keyword=(q==null?\'\':q).trim()\nif(keyword==\'\'){return {items:[]}}\nvar category=category==null?\'drama\':category\nvar type=category==\'org\'?\'org\':category==\'award\'?\'award\':\'drama\'\nvar rows=ods.select("""\nselect id,name,short_name\nfrom JC_ENTITY\nwhere lower(entity_type)=#{type}\n    and publication_status=\'PUBLISHED\'\n    and lower(name) like lower(\'%\'||#{keyword}||\'%\') fetch first 5 rows only\n""")\nfor(row in rows){row.entityType=type;row.title=row.name;row.shortName=row.shortName==null?row.name:row.shortName}\nreturn {items:rows}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/07.门户联想.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3d76c5eb1158405daf123b4af12e5175',NULL,'api','{\n  "properties": {},\n  "id": "db78c52fd4b93c8b912260e3219b3dbb",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "08.门户查询",\n  "createTime": null,\n  "updateTime": 1789857609185,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/query",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "按原门户查询契约从当前租户 Elasticsearch 投影读取；索引未就绪时明确提示执行全量重建。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：08.门户查询\n// 路由：POST /search/query\n// 业务说明：按原门户查询契约从当前租户 Elasticsearch 投影读取；索引未就绪时明确提示执行全量重建。\nimport tenantRuntime\nimport searchEs\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nif(tenantId==null||(\'\'+tenantId).trim()==\'\'){throw new IllegalStateException(\'登录会话缺少租户信息，请重新登录\')}\nvar tenantKey=(\'\'+tenantId).toLowerCase()\nvar catalogRead=\'jcc-search-catalog-\'+tenantKey+\'-read\'\nif(!searchEs.exists(catalogRead)){throw new IllegalStateException(\'搜索索引尚未就绪，请先执行“搜索索引全量重建”\')}\nvar request=body==null?{}:body\nvar category=request.category==null?\'drama\':request.category\nvar type=category==\'org\'?\'org\':category==\'award\'?\'award\':\'drama\'\nvar keyword=request.q==null?\'\':request.q.trim()\nvar pageSize=request.pageSize==null?40:Integer.parseInt(\'\'+request.pageSize)\nif(pageSize<1){pageSize=1};if(pageSize>100){pageSize=100}\nvar offset=request.cursor==null||request.cursor==\'\'?0:Integer.parseInt(\'\'+request.cursor)\nif(offset<0){offset=0}\nvar boolQuery={filter:[{term:{entityType:type}}]}\nif(keyword!=\'\'){boolQuery.must=[{multi_match:{query:keyword,fields:[\'name^3\',\'title^3\',\'shortName^2\',\'synopsis\',\'description\'],type:\'best_fields\'}}]}\nvar result=searchEs.search(catalogRead,{from:offset,size:pageSize,track_total_hits:true,query:{bool:boolQuery}})\nvar hits=result.hits==null?[]:result.hits.hits\nvar items=[]\nfor(hit in hits){var item=hit._source;item.entityType=type;item.title=item.title==null||item.title==\'\'?item.name:item.title;item.shortName=item.shortName==null||item.shortName==\'\'?item.name:item.shortName;items.add(item)}\nvar totalRaw=result.hits==null?0:result.hits.total\nvar total=totalRaw instanceof Map?totalRaw.value:totalRaw\nvar hasNext=offset+items.size()<total\nreturn {items:items,total:total,facets:{},facetLabels:{},hasNext:hasNext,nextCursor:hasNext?\'\'+(offset+items.size()):null,snapshot:{institutions:type==\'org\'?items:[],dramas:type==\'drama\'?items:[],awards:type==\'award\'?items:[],stats:{source:\'elasticsearch\',tenantId:tenantId,index:catalogRead}}}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/08.门户查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9bc8d8b1b01f3c9bb520344ed6c2576b',NULL,NULL,'{\n  "properties": {},\n  "id": "78f6164deec33da899f773493649d31f",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "09.后台资源定义",\n  "createTime": null,\n  "updateTime": 1789860127555,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/admin/resources",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "完整后台资源目录：表结构与数据均读取达梦 linewell_ods。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：09.后台资源定义\n// 路由：GET /search/admin/resources\n// 业务说明：完整后台资源目录：表结构与数据均读取达梦 linewell_ods。\nimport tenantRuntime\nimport flowDataSource\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar catalog=[{"key":"institutions","table":"jc_institution","title":"机构档案","group":"业务资料","readonly":false,"entityType":"org"},{"key":"dramas","table":"jc_drama","title":"剧目档案","group":"业务资料","readonly":false,"entityType":"drama"},{"key":"awards","table":"jc_award","title":"奖项档案","group":"业务资料","readonly":false,"entityType":"award"},{"key":"institution-licenses","table":"jc_institution_license","title":"机构证照","group":"业务资料","readonly":false,"entityType":null},{"key":"institution-stats","table":"jc_institution_stat","title":"机构统计","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-licenses","table":"jc_drama_license","title":"剧目许可","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-credits","table":"jc_drama_credit","title":"主创条目","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-organizations","table":"jc_drama_org","title":"剧目机构关系","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-metrics","table":"jc_drama_metric","title":"剧目指标","group":"业务资料","readonly":false,"entityType":null},{"key":"award-editions","table":"jc_award_edition","title":"奖项届次","group":"业务资料","readonly":false,"entityType":null},{"key":"award-categories","table":"jc_award_category","title":"奖项类别","group":"业务资料","readonly":false,"entityType":null},{"key":"award-organizations","table":"jc_award_org","title":"奖项组织关系","group":"业务资料","readonly":false,"entityType":null},{"key":"award-records","table":"jc_award_record","title":"评审记录","group":"业务资料","readonly":false,"entityType":null},{"key":"record-organizations","table":"jc_award_record_org","title":"评审机构","group":"业务资料","readonly":false,"entityType":null},{"key":"process-instances","table":"jc_process_instance","title":"实际流程记录","group":"业务资料","readonly":false,"entityType":null},{"key":"process-steps","table":"jc_process_step","title":"实际流程步骤","group":"业务资料","readonly":false,"entityType":null},{"key":"libraries","table":"jc_library","title":"六库配置","group":"基础配置","readonly":false,"entityType":null},{"key":"library-tables","table":"jc_library_table","title":"资料集说明","group":"基础配置","readonly":false,"entityType":null},{"key":"dictionary-items","table":"jc_dictionary_item","title":"业务字典","group":"基础配置","readonly":false,"entityType":null},{"key":"tags","table":"jc_tag","title":"业务标签","group":"基础配置","readonly":false,"entityType":null},{"key":"hot-keywords","table":"jc_hot_keyword","title":"推荐词","group":"基础配置","readonly":false,"entityType":null},{"key":"contents","table":"jc_content_item","title":"门户内容","group":"基础配置","readonly":false,"entityType":null},{"key":"process-templates","table":"jc_process_template","title":"流程模板","group":"基础配置","readonly":false,"entityType":null},{"key":"process-template-steps","table":"jc_process_template_step","title":"模板节点","group":"基础配置","readonly":false,"entityType":null},{"key":"sources","table":"jc_source_system","title":"数据来源","group":"数据管理","readonly":false,"entityType":null}