ll},{"key":"kg-datasets","table":"jc_kg_dataset","title":"图谱数据集","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-schemas","table":"jc_kg_schema","title":"图谱模式","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-mappings","table":"jc_kg_mapping","title":"图谱映射","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-rules","table":"jc_kg_inference_rule","title":"推导规则","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-themes","table":"jc_kg_theme","title":"图谱主题","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"profile-templates","table":"jc_profile_template","title":"实体画像模板","group":"画像与群组","readonly":false,"entityType":null},{"key":"label-rules","table":"jc_label_rule","title":"标签规则","group":"画像与群组","readonly":false,"entityType":null},{"key":"groups","table":"jc_group_definition","title":"群组定义","group":"画像与群组","readonly":false,"entityType":null},{"key":"subscription-apps","table":"jc_subscription_app","title":"调用应用","group":"服务订阅","readonly":false,"entityType":null},{"key":"subscriptions","table":"jc_subscription","title":"服务订阅","group":"服务订阅","readonly":false,"entityType":null},{"key":"outbox-events","table":"jc_outbox_event","title":"同步任务","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"ingest-jobs","table":"jc_ingest_job","title":"导入任务","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"ingest-items","table":"jc_ingest_item","title":"逐行导入结果","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"service-call-logs","table":"jc_service_call_log","title":"服务调用日志","group":"任务与运行记录","readonly":true,"entityType":null}]\nvar primary={institutions:{profileFields:[{name:\'name\',type:\'VARCHAR\',nullable:false,desc:\'机构名称\'},{name:\'short_name\',type:\'VARCHAR\',nullable:true,desc:\'机构简称\'}],fields:[{name:\'org_type\',type:\'VARCHAR\',nullable:false,desc:\'机构类型\'},{name:\'level_code\',type:\'VARCHAR\',nullable:false,desc:\'机构层级\'},{name:\'region_display\',type:\'VARCHAR\',nullable:true,desc:\'所在地区\'},{name:\'established_year\',type:\'INTEGER\',nullable:true,desc:\'成立年份\'},{name:\'verification_status\',type:\'VARCHAR\',nullable:true,desc:\'核验状态\'}]},dramas:{profileFields:[{name:\'name\',type:\'VARCHAR\',nullable:false,desc:\'剧目名称\'}],fields:[{name:\'genre_display\',type:\'VARCHAR\',nullable:true,desc:\'剧目题材\'},{name:\'premiere_year\',type:\'INTEGER\',nullable:true,desc:\'首播年份\'},{name:\'episodes\',type:\'INTEGER\',nullable:true,desc:\'集数\'},{name:\'region_display\',type:\'VARCHAR\',nullable:true,desc:\'播出地区\'},{name:\'broadcast_status\',type:\'VARCHAR\',nullable:true,desc:\'播出状态\'}]},awards:{profileFields:[{name:\'name\',type:\'VARCHAR\',nullable:false,desc:\'奖项名称\'},{name:\'short_name\',type:\'VARCHAR\',nullable:true,desc:\'奖项简称\'}],fields:[{name:\'level_code\',type:\'VARCHAR\',nullable:false,desc:\'奖项级别\'},{name:\'founded_year\',type:\'INTEGER\',nullable:true,desc:\'创办年份\'},{name:\'cycle_display\',type:\'VARCHAR\',nullable:true,desc:\'举办周期\'},{name:\'region_display\',type:\'VARCHAR\',nullable:true,desc:\'举办地区\'}]}}\nvar technical=[\'created_at\',\'updated_at\',\'created_by\',\'updated_by\',\'is_del\',\'tenant_id\',\'row_version\']\nreturn catalog.map(spec=>{\n var base=primary[spec.key]\n if(base!=null){return {key:spec.key,title:spec.title,group:spec.group,entityType:spec.entityType,canEdit:true,canPublish:false,foreignKeys:[],profileFields:base.profileFields,fields:base.fields}}\n var columns=ods.select("""\nselect lower(column_name) name,data_type type,nullable,data_default default_value\nfrom user_tab_columns\nwhere upper(table_name)=upper(#{spec.table})\norder by column_id\n""")\n var fields=[]\n for(column in columns){if(technical.indexOf(column.name)<0){fields.add({name:column.name,type:column.type==null?\'VARCHAR\':column.type,nullable:column.nullable==\'Y\',default:column.defaultValue,desc:column.name})}}\n return {key:spec.key,title:spec.title,group:spec.group,entityType:null,canEdit:!spec.readonly,canPublish:false,foreignKeys:[],profileFields:[],fields:fields}\n})\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/09.后台资源定义.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('10ea39c44a5231b7b8231128e9237547',NULL,NULL,'{\n  "properties": {},\n  "id": "1ec65b448e683ecfb8829d9fa84c9392",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "10.后台概览",\n  "path": "/admin/dashboard",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "智能搜索中心后台工作台：直接读取达梦 linewell_ods。"\n}\n================================\n// 接口：10.后台概览\n// 路由：GET /search/admin/dashboard\n// 业务说明：智能搜索中心后台工作台：直接读取达梦 linewell_ods。\nimport tenantRuntime\nimport flowDataSource\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar orgRows=ods.select("""\nselect lower(i.org_type) org_type,count(1) total\nfrom JC_ENTITY e\njoin JC_INSTITUTION i on i.ID=e.ID\nwhere lower(e.entity_type) in (\'org\',\'institution\')\n    and e.publication_status=\'PUBLISHED\'\ngroup by lower(i.org_type)\n""")\nvar orgCounts={production:0,transmission:0,broadcast:0,social:0};for(row in orgRows){if(row.orgType!=null){orgCounts[row.orgType]=row.total}}\nvar orgCount=ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY e\njoin JC_INSTITUTION i on i.ID=e.ID\nwhere lower(e.entity_type) in (\'org\',\'institution\')\n    and e.publication_status=\'PUBLISHED\'\n""")\nvar dramaCount=ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY e\njoin JC_DRAMA d on d.ID=e.ID\nwhere lower(e.entity_type)=\'drama\'\n    and e.publication_status=\'PUBLISHED\'\n""")\nvar awardRecordCount=ods.selectInt("""\nselect count(1)\nfrom JC_AWARD_RECORD\nwhere publication_status=\'PUBLISHED\'\n""")\nvar relationCount=ods.selectInt("""\nselect count(1)\nfrom JC_DRAMA_ORG\n""")+ods.selectInt("""\nselect count(1)\nfrom JC_AWARD_RECORD\n""")\nreturn {engine:\'DAMENG_LINEWELL_ODS\',stats:{orgCount:orgCount,dramaCount:dramaCount,awardRecordCount:awardRecordCount,relationCount:relationCount,orgCounts:orgCounts},pendingReviews:0,drafts:0,sync:{indexed_security_epoch:\'数据库实时读取\',required_security_epoch:\'达梦 linewell_ods\'},lastProjectionError:\'\',recentChanges:[]}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/10.后台概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('10bfe5bbac2e36859ba4867dda94c9fc',NULL,NULL,'{\n  "properties": {},\n  "id": "5e6f96b9586f36d3a85447f4fff98a09",\n  "script": null,\n  "groupId": "31808ca3357c3f359b69a090101ffcdc",\n  "name": "11.后台资源列表",\n  "createTime": null,\n  "updateTime": 1789860043566,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/admin/resource-list",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "完整后台资源列表：达梦 linewell_ods 真实查询。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：11.后台资源列表\n// 路由：GET /search/admin/resource-list\n// 业务说明：完整后台资源列表：达梦 linewell_ods 真实查询。\nimport tenantRuntime\nimport flowDataSource\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar catalog=[{"key":"institutions","table":"jc_institution","title":"机构档案","group":"业务资料","readonly":false,"entityType":"org"},{"key":"dramas","table":"jc_drama","title":"剧目档案","group":"业务资料","readonly":false,"entityType":"drama"},{"key":"awards","table":"jc_award","title":"奖项档案","group":"业务资料","readonly":false,"entityType":"award"},{"key":"institution-licenses","table":"jc_institution_license","title":"机构证照","group":"业务资料","readonly":false,"entityType":null},{"key":"institution-stats","table":"jc_institution_stat","title":"机构统计","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-licenses","table":"jc_drama_license","title":"剧目许可","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-credits","table":"jc_drama_credit","title":"主创条目","group":"业务资料","readonly":false,"entityType":null},{"key":"drama-organizations","table":"jc_drama_org","title":"剧目机构关系","group":"业务资料","readonly":false,"en