,{"key":"source-records","table":"jc_source_record","title":"来源记录","group":"数据管理","readonly":false,"entityType":null},{"key":"services","table":"jc_service","title":"共享服务目录","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"service-versions","table":"jc_service_version","title":"服务版本","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"service-bindings","table":"jc_service_binding","title":"前台服务绑定","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"search-collections","table":"jc_search_collection","title":"检索资源","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"search-fields","table":"jc_search_field","title":"查询字段","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"search-lexicons","table":"jc_search_lexicon","title":"搜索词库","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"lexicon-terms","table":"jc_search_lexicon_term","title":"词条","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"query-models","table":"jc_query_model","title":"组合检索模型","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"detail-sections","table":"jc_detail_section","title":"详情扩展","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"portal-pages","table":"jc_portal_page","title":"门户配置","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"portal-topics","table":"jc_portal_topic","title":"应用专题","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"hot-policies","table":"jc_hot_policy","title":"热门策略","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"search-eval-cases","table":"jc_search_eval_case","title":"评测用例","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"geo-places","table":"jc_geo_place","title":"业务地点","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"geo-events","table":"jc_geo_event","title":"时空事件","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"geo-fences","table":"jc_geo_fence","title":"电子围栏","group":"智能搜索中心","readonly":false,"entityType":null},{"key":"kg-datasets","table":"jc_kg_dataset","title":"图谱数据集","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-schemas","table":"jc_kg_schema","title":"图谱模式","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-mappings","table":"jc_kg_mapping","title":"图谱映射","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-rules","table":"jc_kg_inference_rule","title":"推导规则","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"kg-themes","table":"jc_kg_theme","title":"图谱主题","group":"知识图谱中心","readonly":false,"entityType":null},{"key":"profile-templates","table":"jc_profile_template","title":"实体画像模板","group":"画像与群组","readonly":false,"entityType":null},{"key":"label-rules","table":"jc_label_rule","title":"标签规则","group":"画像与群组","readonly":false,"entityType":null},{"key":"groups","table":"jc_group_definition","title":"群组定义","group":"画像与群组","readonly":false,"entityType":null},{"key":"subscription-apps","table":"jc_subscription_app","title":"调用应用","group":"服务订阅","readonly":false,"entityType":null},{"key":"subscriptions","table":"jc_subscription","title":"服务订阅","group":"服务订阅","readonly":false,"entityType":null},{"key":"outbox-events","table":"jc_outbox_event","title":"同步任务","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"ingest-jobs","table":"jc_ingest_job","title":"导入任务","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"ingest-items","table":"jc_ingest_item","title":"逐行导入结果","group":"任务与运行记录","readonly":true,"entityType":null},{"key":"service-call-logs","table":"jc_service_call_log","title":"服务调用日志","group":"任务与运行记录","readonly":true,"entityType":null}]\nvar spec=catalog.filter(item=>item.key==resource)[0]\nif(spec==null){throw new IllegalArgumentException(\'不支持的后台资源\')}\nif([\'institutions\',\'dramas\',\'awards\'].indexOf(resource)<0){\n var allRows=ods.select(\'select * from \'+spec.table)\n var keyword=q==null?\'\':(\'\'+q).trim().toLowerCase()\n if(keyword!=\'\'){allRows=allRows.filter(row=>JSON.stringify(row).toLowerCase().indexOf(keyword)>=0)}\n var requestedPage=page==null?1:Integer.parseInt(\'\'+page);var requestedSize=pageSize==null?25:Integer.parseInt(\'\'+pageSize);if(requestedPage<1){requestedPage=1};if(requestedSize<1){requestedSize=25};if(requestedSize>100){requestedSize=100}\n var total=allRows.size();var start=(requestedPage-1)*requestedSize;var end=start+requestedSize;var resultRows=start>=total?[]:allRows.subList(start,end>total?total:end)\n return {items:resultRows,total:total,page:requestedPage,pageSize:requestedSize,source:\'linewell_ods\',table:spec.table}\n}\nvar keyword=q==null?\'\':q.trim()\nvar rows=[]\nif(resource==\'institutions\'){rows=ods.select("""\nselect e.id id,e.name name,e.short_name short_name,i.org_type org_type,i.level_code level_code,\n       i.region_display region_display,i.established_year established_year,i.verification_status verification_status,\n       e.publication_status publication_status,e.updated_at updated_at\nfrom JC_ENTITY e\njoin JC_INSTITUTION i on i.ID=e.ID\nwhere lower(e.entity_type) in (\'org\',\'institution\')\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\norder by e.updated_at desc\n""")}\nif(resource==\'dramas\'){rows=ods.select("""\nselect e.id id,e.name name,e.short_name short_name,d.genre_display genre_display,\n       d.premiere_year premiere_year,d.episodes episodes,d.region_display region_display,d.broadcast_status broadcast_status,\n       e.publication_status publication_status,e.updated_at updated_at\nfrom JC_ENTITY e\njoin JC_DRAMA d on d.ID=e.ID\nwhere lower(e.entity_type)=\'drama\'\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\norder by e.updated_at desc\n""")}\nif(resource==\'awards\'){rows=ods.select("""\nselect e.id id,e.name name,e.short_name short_name,a.level_code level_code,a.founded_year founded_year,\n       a.cycle_display cycle_display,a.region_display region_display,e.publication_status publication_status,\n       e.updated_at updated_at\nfrom JC_ENTITY e\njoin JC_AWARD a on a.ID=e.ID\nwhere lower(e.entity_type)=\'award\'\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\norder by e.updated_at desc\n""")}\nvar requestedPage=page==null?1:Integer.parseInt(page);var requestedSize=pageSize==null?25:Integer.parseInt(pageSize);var start=(requestedPage-1)*requestedSize;var end=start+requestedSize;if(start>=rows.size()){rows=[]}else{rows=rows.subList(start,end>rows.size()?rows.size():end)}\nreturn {items:rows,total:resource==\'institutions\'?ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY e\njoin JC_INSTITUTION i on i.ID=e.ID\nwhere lower(e.entity_type) in (\'org\',\'institution\')\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\n"""):resource==\'dramas\'?ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY e\njoin JC_DRAMA d on d.ID=e.ID\nwhere lower(e.entity_type)=\'drama\'\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\n"""):ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY e\njoin JC_AWARD a on a.ID=e.ID\nwhere lower(e.entity_type)=\'award\'\n    and e.publication_status=\'PUBLISHED\'\n    and (#{keyword}=\'\'\n         or lower(e.name) like lower(\'%\'||#{keyword}||\'%\')\n         or lower(e.short_name) like lower(\'%\'||#{keyword}||\'%\'))\n"""),page:requestedPage,pageSize:requestedSize}\n',NULL,NULL,0,NULL,'/magic-api/api/11.智能搜索中心/11.后台资源列表.ms');
