INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_ztgw_config_01','ga_ztgw_config_01','api','{\n  "properties": {},\n  "id": "ga_ztgw_config_01",\n  "script": null,\n  "groupId": "ga_ztgw_group_02",\n  "name": "01.网关配置检查",\n  "createTime": 1789560000000,\n  "updateTime": 1789608368078,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/config-check",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": null,\n  "description": "零信任网关调试配置检查。配置暂时写在脚本顶部的变量中，不读取系统配置、Redis 或环境变量。GET /ga/gateway/config-check。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.网关配置检查\n// 路由：GET /gateway/config-check\n// 业务说明：零信任网关调试配置检查。配置暂时写在脚本顶部的变量中，不读取系统配置、Redis 或环境变量。GET /ga/gateway/config-check。\n// 零信任网关调试配置检查。\n// 调试阶段：所有待调参数集中放在 gatewayConfig；不读取 sym_config_t、Redis 或服务端环境变量。\n// 投产前：将这些变量迁移到部署配置，并把 clientSecret 从脚本中移除。\nimport tenantRuntime\n\nvar gatewayConfig = {\n  // OAuth2 Token 完整地址，例如 https://<gateway-host>/sso/oauth2/token\n  tokenUrl: \'\',\n  // 服务网关已挂载的统一推送完整地址，例如 https://<gateway-host>/api/v1/data-push\n  pushUrl: \'\',\n  // 仅用于本地联调。请自行填入网关分配的值，禁止提交真实生产密钥。\n  clientId: \'wUHx3xkFHFYWGXZFqZUTJQ\',\n  clientSecret: \'G9WfhrEkTGShBNgtXDS6AE\',\n  tokenRefreshAheadSeconds: 300,\n  // 调试时固定填写；正式接入时可按调用人上下文动态补充。\n  requesterIp: \'127.0.0.1\',\n  auditDefaults: {\n    Reg_Role: \'002\',\n    Data_Usage: \'001\',\n    User_Name: \'\',\n    User_Id_Card: \'\',\n    User_Type: \'001\',\n    User_Dept: \'\',\n    User_Terminal_Network: \'001\',\n    User_Terminal_Type: \'001\',\n    Requester_Organization: \'\',\n    Requester_Organization_ID: \'\',\n    Requester_Name: \'数据元素平台\',\n    Requester_ID: \'\',\n    Service_No: \'\',\n    Service_Name: \'统一数据推送服务\',\n    Final_Organization_Name: \'\',\n    Final_Organization_ID: \'\',\n    Final_Organization_Sys_Id: \'\',\n    Final_Organization_Sys_Name: \'\'\n  }\n}\n\nvar tenantId = tenantRuntime.id()\nvar missing = []\nif ((gatewayConfig.tokenUrl || \'\').trim() == \'\') { missing.add(\'gatewayConfig.tokenUrl\') }\nif ((gatewayConfig.pushUrl || \'\').trim() == \'\') { missing.add(\'gatewayConfig.pushUrl\') }\nif ((gatewayConfig.clientId || \'\').trim() == \'\') { missing.add(\'gatewayConfig.clientId\') }\nif ((gatewayConfig.clientSecret || \'\').trim() == \'\') { missing.add(\'gatewayConfig.clientSecret\') }\n\nvar requiredAuditFields = [\'Reg_Role\', \'Data_Usage\', \'User_Name\', \'User_Id_Card\', \'User_Type\', \'User_Dept\', \'User_Terminal_Network\', \'User_Terminal_Type\', \'Requester_Organization\', \'Requester_Organization_ID\', \'Requester_Name\', \'Requester_ID\', \'Service_No\', \'Service_Name\', \'Final_Organization_Name\', \'Final_Organization_ID\', \'Final_Organization_Sys_Id\', \'Final_Organization_Sys_Name\']\nvar missingAuditFields = []\nfor (field in requiredAuditFields) {\n  if (gatewayConfig.auditDefaults[field] == null || (gatewayConfig.auditDefaults[field] + \'\').trim() == \'\') { missingAuditFields.add(field) }\n}\n\nreturn {\n  tenantId: tenantId,\n  configured: missing.size() == 0 && missingAuditFields.size() == 0,\n  mode: \'脚本内调试变量\',\n  missingVariables: missing,\n  missingAuditFields: missingAuditFields,\n  tokenCacheEnabled: false,\n  nextStep: \'填写 gatewayConfig 后，调用 POST /ga/gateway/token-status，先传 {"dryRun":true} 检查请求构造。\'\n}\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制-GA/02.零信任网关对接/01.网关配置检查.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_ztgw_token_02','ga_ztgw_token_02','api','{\n  "properties": {},\n  "id": "ga_ztgw_token_02",\n  "script": null,\n  "groupId": "ga_ztgw_group_02",\n  "name": "02.网关令牌状态",\n  "createTime": 1789560000000,\n  "updateTime": 1789560000000,\n  "path": "/token-status",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "零信任 OAuth2 client_credentials Token 调试接口。支持 dryRun，不读取系统配置、Redis 或环境变量。POST /ga/gateway/token-status。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.网关令牌状态\n// 路由：POST /gateway/token-status\n// 业务说明：零信任 OAuth2 client_credentials Token 调试接口。支持 dryRun，不读取系统配置、Redis 或环境变量。POST /ga/gateway/token-status。\n// 零信任 OAuth2 client_credentials Token 调试接口。\n// 调试阶段不缓存 Token，避免 Redis、系统配置和环境变量干扰问题定位。\n// 正式投产前，将 gatewayConfig 迁移到受控配置，并恢复 Redis 缓存。\nimport tenantRuntime\nimport cn.hutool.core.codec.Base64\nimport http\n\nvar gatewayConfig = {\n  tokenUrl: \'\',\n  clientId: \'\',\n  clientSecret: \'\'\n}\n\nvar tenantId = tenantRuntime.id()\nvar requestBody = body == null ? {} : body\nvar dryRun = requestBody.dryRun == true\nvar missing = []\nif ((gatewayConfig.tokenUrl || \'\').trim() == \'\') { missing.add(\'gatewayConfig.tokenUrl\') }\nif ((gatewayConfig.clientId || \'\').trim() == \'\') { missing.add(\'gatewayConfig.clientId\') }\nif ((gatewayConfig.clientSecret || \'\').trim() == \'\') { missing.add(\'gatewayConfig.clientSecret\') }\n\nif (dryRun) {\n  return {\n    tenantId: tenantId,\n    dryRun: true,\n    configured: missing.size() == 0,\n    missingVariables: missing,\n    request: {\n      method: \'POST\',\n      grantType: \'client_credentials\',\n      authorizationScheme: \'Basic clientId:clientSecret（已脱敏）\'\n    }\n  }\n}\n\nif (missing.size() > 0) { exit 503, \'零信任网关调试变量未填写：\' + missing.join(\', \') }\n\nvar separator = gatewayConfig.tokenUrl.indexOf(\'?\') >= 0 ? \'&\' : \'?\'\nvar tokenResponse = null\ntry {\n  tokenResponse = http.connect(`${gatewayConfig.tokenUrl}${separator}grant_type=client_credentials`)\n    .contentType(\'application/json;charset=utf-8\')\n    .header(\'Authorization\', \'Basic \' + Base64.encode(`${gatewayConfig.clientId}:${gatewayConfig.clientSecret}`))\n    .post()\n    .getBody()\n} catch (error) {\n  exit 502, \'零信任认证服务请求失败：\' + (error.message || error)\n}\n\nvar accessToken = tokenResponse == null ? \'\' : (tokenResponse.access_token || \'\').trim()\nif (accessToken == \'\') {\n  var gatewayMessage = tokenResponse == null ? \'认证服务未返回响应\' : (tokenResponse.message || tokenResponse.msg || \'认证服务未返回 access_token\')\n  exit 502, \'零信任认证失败：\' + gatewayMessage\n}\n\nreturn {\n  tenantId: tenantId,\n  dryRun: false,\n  tokenAvailable: true,\n  tokenExposed: false,\n  tokenType: tokenResponse.token_type || \'Bearer\',\n  expiresIn: tokenResponse.expires_in || null,\n  eCode: tokenResponse.eCode || null\n}\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制-GA/02.零信任网关对接/02.网关令牌状态.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_ztgw_push_03','ga_ztgw_push_03','api','{\n  "properties": {},\n  "id": "ga_ztgw_push_03",\n  "script": null,\n  "groupId": "ga_ztgw_group_02",\n  "name": "03.统一数据推送",\n  "createTime": 1789560000000,\n  "updateTime": 1789560000000,\n  "path": "/data-push",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [\n    {\n      "name": "X-Api-Key",\n      "required": true,\n      "dataType": "String",\n      "description": "登记数据源签发的业务调用密钥；透传至统一数据推送服务。"\n    },\n    {\n      "name": "Idempotency-Key",\n      "required": true,\n      "dataType": "String",\n      "description": "表批次幂等标识；透传至统一数据推送服务。"\n    }\n  ],\n  "paths": [],\n  "description": "零信任网关统一数据推送调试代理。支持 dryRun；调试变量写在脚本顶部，不读取系统配置、Redis 或环境变量。POST /ga/gateway/data-push。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.统一数据推送\n// 路由：POST /gateway/data-push\n// 业务说明：零信任网关统一数据推送调试代理。支持 dryRun；调试变量写在脚本顶部，不读取系统配置、Redis 或环境变量。POST /ga/gateway/data-push。\n// 零信任网关统一数据推送调试代理。\n// 调试阶段：所有配置写在 gatewayConfig；每次真实调用都申请一个 Token，不依赖 Redis。\n// 正式投产前：把 gatewayConfig 迁移到受控配置，clientSecret 迁移到服务端密钥，并启用 Token 缓存。\nimport tenantRuntime\nimport cn.hutool.core.codec.Base64\nimport cn.hutool.core.date.DateUtil\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.core.util.RandomUtil\nimport http\nimport request\n\nvar gatewayConfig = {\n  tokenUrl: \'\',\n  pushUrl: \'\',\n  clientId: \'\',\n  clientSecret: \'\',\n  requesterIp: \'127.0.0.1\',\n  auditDefaults: {\n    Reg_Role: \'002\',\n    Data_Usage: \'001\',\n    User_Name: \'\',\n    User_Id_Card: \'\',\n    User_Type: \'001\',\n    User_Dept: \'\',\n    User_Terminal_Network: \'001\',\n    User_Terminal_Type: \'001\',\n    Requester_Organization: \'\',\n    Requester_Organization_ID: \'\',\n    Requester_Name: \'数据元素平台\',\n    Requester_ID: \'\',\n    Service_No: \'\',\n    Service_Name: \'统一数据推送服务\',\n    Final_Organization_Name: \'\',\n    Final_Organization_ID: \'\',\n    Final_Organization_Sys_Id: \'\',\n    Final_Organization_Sys_Name: \'\'\n  }\n}\n\nvar tenantId = tenantRuntime.id()\nif (body == null) { exit 400, \'请求体不能为空\' }\nvar dryRun = body.dryRun == true\n\nvar requiredBusinessFields = [\'deliveryType\', \'datasourceId\', \'tableName\', \'records\']\nvar missingBusiness = []\nfor (field in requiredBusinessFields) {\n  if (body[field] == null || (field != \'records\' && (body[field] + \'\').trim() == \'\')) { missingBusiness.add(field) }\n}\nif (missingBusiness.size() > 0) { exit 400, \'统一数据推送请求缺少字段：\' + missingBusiness.join(\', \') }\nif (body.records == null || body.records.size() == 0) { exit 400, \'records 至少需要一条数据\' }\n\nvar apiKeyValues = request.getHeaders(\'X-Api-Key\')\nvar idempotencyKeyValues = request.getHeaders(\'Idempotency-Key\')\nvar apiKey = apiKeyValues == null || apiKeyValues.size() == 0 ? \'\' : (apiKeyValues[0] + \'\').trim()\nvar idempotencyKey = idempotencyKeyValues == null || idempotencyKeyValues.size() == 0 ? \'\' : (idempotencyKeyValues[0] + \'\').trim()\nvar missingHeaders = []\nif (apiKey == \'\') { missingHeaders.add(\'X-Api-Key\') }\nif (idempotencyKey == \'\') { missingHeaders.add(\'Idempotency-Key\') }\nif (missingHeaders.size() > 0) { exit 400, \'请求头必填：\' + missingHeaders.join(\', \') }\n\nvar missingConfig = []\nif ((gatewayConfig.tokenUrl || \'\').trim() == \'\') { missingConfig.add(\'gatewayConfig.tokenUrl\') }\nif ((gatewayConfig.pushUrl || \'\').trim() == \'\') { missingConfig.add(\'gatewayConfig.pushUrl\') }\nif ((gatewayConfig.clientId || \'\').trim() == \'\') { missingConfig.add(\'gatewayConfig.clientId\') }\nif ((gatewayConfig.clientSecret || \'\').trim() == \'\') { missingConfig.add(\'gatewayConfig.clientSecret\') }\n\nvar payload = {}\nbody.each((key, value) => { if (key != \'gatewayAudit\' && key != \'dryRun\') { payload[key] = value } })\ngatewayConfig.auditDefaults.each((key, value) => { payload[key] = value })\n\nvar inputAudit = body.gatewayAudit == null ? {} : body.gatewayAudit\nvar allowedAuditFields = [\'User_Name\', \'User_Id_Card\', \'User_Cert_Id\', \'User_Type\', \'User_Dept\', \'User_Terminal_Network\', \'User_Terminal_Mac\', \'User_Mobile\', \'User_Terminal_Type\', \'User_Phone_IMEI\', \'Query_Resume\', \'Interface_Condition\']\nfor (field in allowedAuditFields) {\n  if (inputAudit[field] != null && (inputAudit[field] + \'\').trim() != \'\') { payload[field] = inputAudit[field] }\n}\n\nvar requestId = `${DateUtil.current()}${RandomUtil.randomString(6)}`\npayload.Num_ID = IdUtil.getSnowflakeNextIdStr()\npayload.Request_ID = requestId\npayload.Requester_IP = gatewayConfig.requesterIp\npayload.Query_Datetime = DateUtil.now()\npayload.Request_Type = \'003\'\npayload.Record_Type = \'interface\'\npayload.Log_Seq_Id = requestId\nif (payload.Interface_Condition == null || (payload.Interface_Condition + \'\').trim() == \'\') {\n  payload.Interface_Condition = `datasourceId=${body.datasourceId};tableName=${body.tableName};records=${body.records.size()}`\n}\n\nvar requiredAuditFields = [\'Reg_Role\', \'Data_Usage\', \'User_Name\', \'User_Id_Card\', \'User_Type\', \'User_Dept\', \'User_Terminal_Network\', \'User_Terminal_Type\', \'Requester_Organization\', \'Requester_Organization_ID\', \'Requester_Name\', \'Requester_ID\', \'Service_No\', \'Service_Name\', \'Final_Organization_Name\', \'Final_Organization_ID\', \'Final_Organization_Sys_Id\', \'Final_Organization_Sys_Name\', \'Query_Resume\']\nvar missingAudit = []\nfor (field in requiredAuditFields) {\n  if (payload[field] == null || (payload[field] + \'\').trim() == \'\') { missingAudit.add(field) }\n}\n\nif (dryRun) {\n  return {\n    tenantId: tenantId,\n    dryRun: true,\n    businessValid: true,\n    headerValid: true,\n    configValid: missingConfig.size() == 0,\n    auditValid: missingAudit.size() == 0,\n    missingVariables: missingConfig,\n    missingAuditFields: missingAudit,\n    requestId: requestId,\n    outbound: {\n      method: \'POST\',\n      urlConfigured: (gatewayConfig.pushUrl || \'\').trim() != \'\',\n      authorizationScheme: \'Bearer access_token（不返回）\',\n      headersForwarded: [\'X-Api-Key\', \'Idempotency-Key\'],\n      recordCount: body.records.size()\n    }\n  }\n}\n\nif (missingConfig.size() > 0) { exit 503, \'零信任网关调试变量未填写：\' + missingConfig.join(\', \') }\nif (missingAudit.size() > 0) { exit 400, \'零信任网关审计字段未填写：\' + missingAudit.join(\', \') }\n\nvar separator = gatewayConfig.tokenUrl.indexOf(\'?\') >= 0 ? \'&\' : \'?\'\nvar tokenResponse = null\ntry {\n  tokenResponse = http.connect(`${gatewayConfig.tokenUrl}${separator}grant_type=client_credentials`)\n    .contentType(\'application/json;charset=utf-8\')\n    .header(\'Authorization\', \'Basic \' + Base64.encode(`${gatewayConfig.clientId}:${gatewayConfig.clientSecret}`))\n    .post()\n    .getBody()\n} catch (error) {\n  exit 502, \'零信任认证服务请求失败：\' + (error.message || error)\n}\n\nvar accessToken = tokenResponse == null ? \'\' : (tokenResponse.access_token || \'\').trim()\nif (accessToken == \'\') {\n  var tokenMessage = tokenResponse == null ? \'认证服务未返回响应\' : (tokenResponse.message || tokenResponse.msg || \'认证服务未返回 access_token\')\n  exit 502, \'零信任认证失败：\' + tokenMessage\n}\n\nvar gatewayResponse = null\ntry {\n  gatewayResponse = http.connect(gatewayConfig.pushUrl)\n    .contentType(\'application/json;charset=utf-8\')\n    .header(\'Authorization\', \'Bearer \' + accessToken)\n    .header(\'X-Api-Key\', apiKey)\n    .header(\'Idempotency-Key\', idempotencyKey)\n    .body(payload)\n    .post()\n    .getBody()\n} catch (error) {\n  exit 502, \'统一数据推送网关请求失败：\' + (error.message || error)\n}\n\nreturn {\n  tenantId: tenantId,\n  requestId: requestId,\n  deliveryType: body.deliveryType,\n  tableName: body.tableName,\n  recordCount: body.records.size(),\n  downstream: gatewayResponse\n}\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制-GA/02.零信任网关对接/03.统一数据推送.ms');
