INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_sync_01','ga_pinggao_sync_01','api','{\n  "properties": {},\n  "id": "ga_pinggao_sync_01",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "01.品高应用同步",\n  "path": "/sync",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "品高应用全量同步（POST /ga/pinggao/sync）。同步由服务端适配器调用品高私网接口；凭据不返回、不记录。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.品高应用同步\n// 路由：POST /ga/pinggao/sync\n// 业务说明：品高应用全量同步（POST /ga/pinggao/sync）。同步由服务端适配器调用品高私网接口；凭据不返回、不记录。\nimport cn.hutool.extra.spring.SpringUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationProperties\nvar properties = SpringUtil.getBean(PingaoApplicationProperties.class)\nStpUtil.checkPermission(properties.getManualSyncPermission())\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\nreturn service.syncCurrentTenant()\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/01.品高应用同步.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_status_02','ga_pinggao_status_02','api','{\n  "properties": {},\n  "id": "ga_pinggao_status_02",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "02.同步状态",\n  "path": "/sync-status",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "查询当前租户品高应用同步状态（GET /ga/pinggao/sync-status）。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.同步状态\n// 路由：GET /ga/pinggao/sync-status\n// 业务说明：查询当前租户品高应用同步状态（GET /ga/pinggao/sync-status）。\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\nreturn service.syncState()\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/02.同步状态.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_duplicate_03','ga_pinggao_duplicate_03','api','{\n  "properties": {},\n  "id": "ga_pinggao_duplicate_03",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "03.重复应用预览",\n  "path": "/duplicate-preview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "预览历史应用与品高应用的同名重复项（GET /ga/pinggao/duplicate-preview）。只读。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.重复应用预览\n// 路由：GET /ga/pinggao/duplicate-preview\n// 业务说明：预览历史应用与品高应用的同名重复项（GET /ga/pinggao/duplicate-preview）。只读。\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\nreturn service.duplicatePreview()\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/03.重复应用预览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_legacy_preview_04','ga_pinggao_legacy_preview_04','api','{\n  "properties": {},\n  "id": "ga_pinggao_legacy_preview_04",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "04.历史应用清理预览",\n  "path": "/legacy-purge-preview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "预览可清理和被数据源引用的历史应用（GET /ga/pinggao/legacy-purge-preview）。只读。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：04.历史应用清理预览\n// 路由：GET /ga/pinggao/legacy-purge-preview\n// 业务说明：预览可清理和被数据源引用的历史应用（GET /ga/pinggao/legacy-purge-preview）。只读。\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\nreturn service.legacyPurgePreview()\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/04.历史应用清理预览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_legacy_purge_05','ga_pinggao_legacy_purge_05','api','{\n  "properties": {},\n  "id": "ga_pinggao_legacy_purge_05",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "05.清理历史应用",\n  "path": "/legacy-purge",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "软删除未被数据源引用的历史应用（POST /ga/pinggao/legacy-purge）。可传 body.ids 指定范围；不会删除被引用记录。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：05.清理历史应用\n// 路由：POST /ga/pinggao/legacy-purge\n// 业务说明：软删除未被数据源引用的历史应用（POST /ga/pinggao/legacy-purge）。可传 body.ids 指定范围；不会删除被引用记录。\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\n\nvar rawIds = body == null ? null : body.ids\nvar ids = []\nif (rawIds != null) {\n    for (item in rawIds) {\n        if (item != null && (item + \'\').trim() != \'\') { ids.add(item + \'\') }\n    }\n}\nreturn service.purgeLegacy(ids)\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/05.清理历史应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ga_pinggao_options_06','ga_pinggao_options_06','api','{\n  "properties": {},\n  "id": "ga_pinggao_options_06",\n  "script": null,\n  "groupId": "4715f94aac854f9da269d34928f47c4e",\n  "name": "06.应用系统选择项",\n  "path": "/options",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "headers": [],\n  "paths": [],\n  "description": "返回当前租户可登记的数据源所属应用系统（POST /ga/pinggao/options）。首次同步前仅返回历史项；成功同步后只返回已上线品高应用。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：06.应用系统选择项\n// 路由：POST /ga/pinggao/options\n// 业务说明：返回当前租户可登记的数据源所属应用系统（POST /ga/pinggao/options）。首次同步前仅返回历史项；成功同步后只返回已上线品高应用。\nimport cn.hutool.extra.spring.SpringUtil\nimport com.linewell.dataelement.platform.integration.pingao.PingaoApplicationSyncService\nvar service = SpringUtil.getBean(PingaoApplicationSyncService.class)\nreturn service.selectableOptions()\n',NULL,NULL,0,NULL,'/magic-api/api/11.省厅公安定制/01.品高对接/06.应用系统选择项.ms');
