INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dc94f88efd754460aee99088667c3c87',NULL,'api','{\n  "properties": {},\n  "id": "a0e07289fcee3edc9c4227df25e871e5",\n  "script": null,\n  "groupId": "f98b9807bf683fc6ac5d9f1233e876cc",\n  "name": "01.当前租户概览",\n  "createTime": null,\n  "updateTime": 1789860655218,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/overview",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "知识图谱中心概览：达梦 linewell_ods 的图谱配置、实体与真实业务关系；读取或计算后返回业务结果。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.当前租户概览\n// 路由：GET /graph/overview\n// 业务说明：知识图谱中心概览：达梦 linewell_ods 的图谱配置、实体与真实业务关系；读取或计算后返回业务结果。\nimport tenantRuntime\nimport flowDataSource\n// 业务租户从当前会话读取，不采用请求体中的租户标识。\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar datasets=ods.selectInt("""\nselect count(1)\nfrom JC_KG_DATASET\n""")\nvar themes=ods.selectInt("""\nselect count(1)\nfrom JC_KG_THEME\n""")\nvar entities=ods.selectInt("""\nselect count(1)\nfrom JC_ENTITY\n""")\nvar relations=ods.selectInt("""\nselect count(1)\nfrom JC_DRAMA_ORG\n""")+ods.selectInt("""\nselect count(1)\nfrom JC_AWARD_RECORD\n""")+ods.selectInt("""\nselect count(1)\nfrom JC_AWARD_ORG\n""")\nreturn {tenantId:tenantId,metrics:{repositories:themes,datasets:datasets,entities:entities,relations:relations,source:\'linewell_ods\'}}\n',NULL,NULL,0,NULL,'/magic-api/api/12.知识图谱中心/01.当前租户概览.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9e6488361d3643879dba7acac0581d19',NULL,'api','{\n  "properties": {},\n  "id": "5926ed16750f381d8a3cddb00f4d919f",\n  "script": null,\n  "groupId": "f98b9807bf683fc6ac5d9f1233e876cc",\n  "name": "02.数据集清单",\n  "createTime": null,\n  "updateTime": 1789860655283,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/datasets",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "知识图谱数据集：读取达梦 linewell_ods。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.数据集清单\n// 路由：GET /graph/datasets\n// 业务说明：知识图谱数据集：读取达梦 linewell_ods。\nimport tenantRuntime\nimport flowDataSource\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nreturn {tenantId:tenantId,items:ods.select("""\nselect *\nfrom JC_KG_DATASET\n"""),source:\'linewell_ods\'}\n',NULL,NULL,0,NULL,'/magic-api/api/12.知识图谱中心/02.数据集清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9c3f16b0d8f6452bb3988b6b81884c6e',NULL,'api','{\n  "properties": {},\n  "id": "e0ffa8c19d633605b338634cffa6d617",\n  "script": null,\n  "groupId": "f98b9807bf683fc6ac5d9f1233e876cc",\n  "name": "03.实体清单",\n  "createTime": null,\n  "updateTime": 1789860655405,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/entities",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "知识图谱实体清单：读取达梦 linewell_ods 的统一实体主档。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.实体清单\n// 路由：GET /graph/entities\n// 业务说明：知识图谱实体清单：读取达梦 linewell_ods 的统一实体主档。\nimport tenantRuntime\nimport flowDataSource\nvar tenantId=tenantRuntime.id()\nvar sourceKey=flowDataSource.ensureRuntime(\'linewell_ods\')\nvar ods=db[sourceKey]\nvar size=pageSize==null?100:Integer.parseInt(\'\'+pageSize);if(size<1){size=1};if(size>500){size=500}\nreturn {tenantId:tenantId,items:ods.select(`select ID id,ENTITY_TYPE entity_type,NAME name,SHORT_NAME short_name,UPDATED_AT updated_at from JC_ENTITY order by UPDATED_AT desc fetch first ${size} rows only`),source:\'linewell_ods\'}\n',NULL,NULL,0,NULL,'/magic-api/api/12.知识图谱中心/03.实体清单.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('872eeca6fd5c44ea94c2c42ab5340c6f',NULL,'api','{\n  "properties": {},\n  "id": "bc2c6a9145453e7aa5eb5621a191c891",\n  "script": null,\n  "groupId": "f98b9807bf683fc6ac5d9f1233e876cc",\n  "name": "04.关系清单",\n  "path": "/relations",\n  "method": "GET",\n  "parameters": [],\n  "options": [],\n  "requestBody": "",\n  "headers": [],\n  "paths": [],\n  "responseBody": "",\n  "description": "读取当前租户的知识图谱关系；涉及 kg_relation 等业务表。"\n}\n================================\n// 接口：04.关系清单\n// 路由：GET /graph/relations\n// 业务说明：读取当前租户的知识图谱关系；涉及 kg_relation 等业务表。\nimport tenantRuntime;\nvar tenantId=tenantRuntime.id();\ntry{return {tenantId:tenantId,items:db.table(\'kg_relation\').where({is_del:0}).select()};}catch(error){return {tenantId:tenantId,items:[]};}\n',NULL,NULL,0,NULL,'/magic-api/api/12.知识图谱中心/04.关系清单.ms');
