INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('78e703d8a47d4b2883e79f7b14566e7f',NULL,'api','{\n  "properties": {},\n  "id": "b04b913d36315a339c11a2a5c462fca6",\n  "script": null,\n  "groupId": "846e66f7a9365dc4a13942533f262c0a",\n  "name": "01.登录管理控制台",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/login",\n  "description": "根据平台操作账号读取独立凭据与安全状态，检查失败锁定、密码和多因子挑战，成功后签发平台会话并记录登录审计；租户本地账号不能在此登录。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.登录管理控制台\n// 路由：POST /idaas/auth/login\n// 业务说明：根据平台操作账号读取独立凭据与安全状态，检查失败锁定、密码和多因子挑战，成功后签发平台会话并记录登录审计；租户本地账号不能在此登录。\nimport db;\nimport request;\nimport platformSession;\nimport iamSecurity;\nimport iamMfa;\nimport \'@/idaas/session\' as sessionInfo;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var payload = body||{};\n\n    // 平台账号与租户本地账号分离；失败次数限制、密码核验和多因子挑战均在本接口完成。\n    // 独立operator登录；保留旧摘要兼容，新增/改密使用框架PBKDF2，不依赖rm账号。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var username=(p.username||\'\').trim().toLowerCase();\n    var password=p.password||\'\';\n    if(p.domain!=\'workforce\' || username==\'\' || username.length()>50 || password==\'\' || password.length()>256) {\n        exit 400,\'请输入有效的平台账号与密码\';\n    }\n    var fingerprint=DigestUtil.sha256Hex(username);\n    var ip=request.getClientIP();\n    var limited=sql.selectOne("""\nselect count(*) as total\nfrom iam_audit_event_t\nwhere event_type=\'AUTH\'\n    and result!=\'SUCCESS\'\n    and (account_fingerprint=#{fingerprint}\n         or ip=#{ip})\n    and event_time>date_sub(utc_timestamp(6),interval 10 minute)\n""");\n    if(limited.total>=30) {\n        exit 429,\'尝试次数过多，请稍后重试\';\n    }\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var outcome=sql.transaction(()=>{\n        var u=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n    and status=\'ACTIVE\'\n    for update\n""");\n        if(u==null) {\n            return {\n                error:\'INVALID\'\n            };\n        }\n        var s=sql.selectOne("""\nselect *,tid as id,case when locked_until>utc_timestamp(6) then 1 else 0\n                   end as locked\nfrom iam_account_security_t\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{u.id}\n    for update\n""");\n        if(s==null) {\n            return {\n                error:\'INVALID\'\n            };\n        }\n        if(s.locked==1) {\n            return {\n                error:\'LOCKED\',userId:u.id\n            };\n        }\n        var policy=sql.selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'SECURITY\'\n    and config_key=\'password\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n        var config=policy==null?{}:policy.value_json;\n        if(policy!=null) {\n            config=JSONUtil.parseObj(policy.value_json);\n        }\n        var threshold=config.lockThreshold||5;\n        var minutes=config.lockMinutes||15;\n        var cred=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{u.id}\n    and credential_type=\'PASSWORD\'\n    and slot=\'primary\'\n    and status=\'ACTIVE\'\n    and (not_before is null\n         or not_before<=utc_timestamp(6))\n    and (expires_at is null\n         or expires_at>utc_timestamp(6))\n""");\n        // 核对凭据时兼容已登记的摘要算法，失败只更新安全状态而不创建会话。\n        if(cred==null || !iamSecurity.verify(password,cred.algorithm,cred.secret_hash)) {\n            var failures=s.failed_count+1;\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=#{failures},locked_until=case\n        when #{failures}>=#{threshold} then date_add(utc_timestamp(6),interval #{minutes} minute) else null\n        end,updated_time=utc_timestamp(6)\nwhere tid=#{s.id}\n""");\n            return {\n                error:\'INVALID\',userId:u.id\n            };\n        }\n        sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,updated_time=utc_timestamp(6)\nwhere tid=#{s.id}\n""");\n        sql.update("""\nupdate iam_operator_t\nset last_login_time=utc_timestamp(6)\nwhere tid=#{u.id}\n""");\n        return {\n            id:u.id,securityVersion:s.security_version\n        };\n    });\n    // 记录操作主体、目标及结果，供审计与故障追踪。\n    var trace=audit(outcome.id==null?null:{\n        userId:outcome.id\n    },outcome.error==null?\'SUCCESS\':\'FAILED\',\'auth:login\',outcome.userId,outcome.error,null);\n    sql.update("""\nupdate iam_audit_event_t\nset account_fingerprint=#{fingerprint}\nwhere tid=#{trace}\n""");\n    if(outcome.error==\'LOCKED\') {\n        exit 429,\'账号暂时锁定，请稍后重试或申请解锁\';\n    }\n    if(outcome.error!=null) {\n        exit 401,\'平台账号或密码不正确\';\n    }\n    var mfa=sql.selectOne("""\nselect tid as id\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{outcome.id}\n    and credential_type=\'TOTP\'\n    and status=\'ACTIVE\'\n""");\n    var mfaPolicy=sql.selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere category=\'SECURITY\'\n    and config_key=\'password\'\n    and scope_key=\'global\'\n    and is_del=0\n""");\n    if(mfa!=null) {\n        return {\n            mfaRequired:true,realm:\'platform\',challenge:iamMfa.challenge(\'OPERATOR\',outcome.id,outcome.securityVersion,\'LOGIN\')\n        };\n    }\n    if(mfaPolicy!=null && JSONUtil.parseObj(mfaPolicy.value_json).mfaRequired==true) {\n        exit 403,\'账号尚未绑定动态口令，请联系管理员\';\n    }\n    // 密码及附加挑战通过后才签发独立的平台会话。\n    platformSession.login(outcome.id,1800);\n    platformSession.session().set(\'securityVersion\',outcome.securityVersion);\n    try {\n        return {\n            token:platformSession.token(),session:sessionInfo()\n        };\n    }\n    catch(e) {\n        platformSession.logout();\n        throw e;\n    }\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/01.认证会话/01.登录管理控制台.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('eb2532b6f1b14c7997939892ef542c21',NULL,'api','{\n  "properties": {},\n  "id": "4bd2f846272751cab344701a3258027c",\n  "script": null,\n  "groupId": "846e66f7a9365dc4a13942533f262c0a",\n  "name": "02.退出管理控制台",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/logout",\n  "description": "识别当前平台会话并撤销服务端令牌，记录退出事件，后续使用该令牌访问平台接口将失败。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.退出管理控制台\n// 路由：POST /idaas/auth/logout\n// 业务说明：识别当前平台会话并撤销服务端令牌，记录退出事件，后续使用该令牌访问平台接口将失败。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport platformSession;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/audit\' as audit;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var ctx=context();\n    audit(ctx,\'SUCCESS\',\'auth:logout\',ctx.userId,null,null);\n    platformSession.logout();\n    return true;\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/01.认证会话/02.退出管理控制台.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3b13b476daa042d0911f4de52da35158',NULL,'api','{\n  "properties": {},\n  "id": "c5e8f3f5dc9d52d5b23709f6e3c2ec15",\n  "script": null,\n  "groupId": "846e66f7a9365dc4a13942533f262c0a",\n  "name": "03.读取登录页设置",\n  "createTime": 1790612165860,\n  "updateTime": 1790948254995,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/public-settings",\n  "description": "匿名读取登录页可公开的品牌与安全设置，仅返回允许公开的字段，不暴露密钥及内部认证策略。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.读取登录页设置\n// 路由：GET /idaas/auth/public-settings\n// 业务说明：匿名读取登录页可公开的品牌与安全设置，仅返回允许公开的字段，不暴露密钥及内部认证策略。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport db;\nimport cn.hutool.json.JSONUtil;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var r=db.normal().selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'BRANDING\'\n    and config_key=\'brand\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var v=r==null?{}:JSONUtil.parseObj(r.value_json);\n    return {\n        title:v.title,subtitle:v.subtitle,logoUrl:v.logoUrl\n    };\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/01.认证会话/03.读取登录页设置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('984da8c316b44771867662f1469823d3',NULL,NULL,'{\n  "properties": {},\n  "id": "846e66f7a9365dc4a13942533f262c0a",\n  "name": "01.认证会话",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/auth",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/01.认证会话/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('669919e2c67248348c9f31d7b0fd09fa',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/02.当前会话/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('76457ab635814e0a8dd6ebc6e564df4c',NULL,'api','{\n  "properties": {},\n  "id": "787f8928738b51ad96291bd03969907e",\n  "script": null,\n  "groupId": "38dfb5ef9c2052b0acee3e477054544d",\n  "name": "01.读取当前操作账号",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/me",\n  "description": "校验平台会话，读取本人资料、身份域、功能权限及应用管理范围，供控制台展示当前登录状态。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.读取当前操作账号\n// 路由：GET /idaas/session/me\n// 业务说明：校验平台会话，读取本人资料、身份域、功能权限及应用管理范围，供控制台展示当前登录状态。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/session\' as execute;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    return execute();\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/02.当前会话/01.读取当前操作账号.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cc39ca29f8c549e1a84038385cb7f9e6',NULL,'api','{\n  "properties": {},\n  "id": "e52368d8d58458c096bd3323746f85b9",\n  "script": null,\n  "groupId": "38dfb5ef9c2052b0acee3e477054544d",\n  "name": "02.切换当前身份域",\n  "createTime": 1790635007936,\n  "updateTime": 1790948254995,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/domain",\n  "description": "校验当前账号具备目标身份域的管理范围，切换会话使用的域并返回更新后的上下文；不改变账号本身权限。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.切换当前身份域\n// 路由：POST /idaas/session/domain\n// 业务说明：校验当前账号具备目标身份域的管理范围，切换会话使用的域并返回更新后的上下文；不改变账号本身权限。\nimport platformSession;\nimport db;\nimport request;\nimport \'@/idaas/public-entities\' as publicEntities;\nimport \'@/idaas/session\' as sessionInfo;\nimport \'@/idaas/applications\' as applications;\nimport \'@/idaas/settings\' as settings;\nimport \'@/idaas/directory\' as directory;\nimport \'@/idaas/directory-config\' as directoryConfig;\nimport \'@/idaas/business-catalog\' as businessCatalog;\nimport \'@/idaas/business-grants\' as businessGrants;\nimport \'@/idaas/permission-groups\' as permissionGroups;\nimport \'@/idaas/effective-access\' as effectiveAccess;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var payload = body;\n\n    var p=payload||{};\n    var ctx=context();\n    var domain=p.domain;\n    if(![\'workforce\',\'public\'].contains(domain) || ctx.account.must_change_password==1) {\n        exit 403,\'当前账号不能切换身份域\';\n    }\n    if(ctx.pairs.filter(pair=>pair.scopes.filter(s=>s.identity_domain==domain).size()>0).size()==0) {\n        exit 403,\'当前账号没有目标身份域的管理范围\';\n    }\n    platformSession.session().set(\'identityDomain\',domain);\n    ctx.requiredDomain=domain;\n    // 记录操作主体、目标及结果，供审计与故障追踪。\n    audit(ctx,\'SUCCESS\',\'profile:domain\',ctx.userId,null,{\n        domain:domain\n    });\n    // 切换成功后在本接口重建目标身份域的工作区数据。\n    // 有界读取中央目录及当前应用授权；不查询旧共享账号或应用本地账号。\n    var http=request.get();\n    var previousSnapshot=http.getAttribute(\'idaas.bootstrap.permissionSnapshot\');\n    http.setAttribute(\'idaas.bootstrap.permissionSnapshot\',{\n        operatorId:platformSession.id(),context:null\n    });\n    try {\n        var sql=db.normal();\n        var session=sessionInfo();\n        var database={\n            schema:1,users:[],orgs:[],apps:[],roles:[],resources:[],groups:[],grants:[],syncConfigs:[],tasks:[],logs:[],catalog:[],legalEntities:[],settings:{\n                workforce:{},public:{}\n            }\n        };\n        var settingVersions={};\n        if(session.capabilities.contains(\'apps\')) {\n            database.apps=applications(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'users\')) {\n            database.users=directory(\'subjects\',\'list\',{\n                domain:session.domain,size:250\n            }).list;\n        }\n        if(session.capabilities.contains(\'orgs\')) {\n            database.orgs=directory(\'orgs\',\'list\',{\n                domain:session.domain,size:250\n            }).list;\n        }\n        if(!session.mustChangePassword && session.permissions.contains(\'settings:read\')) {\n            for(r in settings(\'read\',{})) {\n                database.settings.get(session.domain).putAll(r.value);\n                settingVersions[r.category]=r.version;\n            }\n        }\n        if(session.permissions.contains(\'apps:read\')) {\n            var groups=sql.select("""\nselect *,tid as id,date_format(created_time, \'%Y-%m-%dT%H:%i:%sZ\') as created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') as updated_utc\nfrom iam_application_group_t\nwhere is_del=0\norder by sort_no,code\n""");\n            database.catalog=groups.map(g=>({\n                id:g.id,domain:\'workforce\',name:g.name,code:g.code,category:\'app-group\',description:\'\',status:\'enabled\',version:g.version,\n                createdAt:g.created_utc,updatedAt:g.updated_utc,permissions:[],memberIds:[],appId:\'\',orgId:\'\',userId:\'\',parentId:\'\',value:\'\',expiresAt:\'\',subjectType:\'\'\n            }));\n        }\n        if(session.globalPermissions.contains(\'directory:read\')) {\n            database.catalog.addAll(directoryConfig(\'dictionaries\',\'list\',{\n                domain:session.domain\n            }));\n            database.catalog.addAll(directoryConfig(\'field-definitions\',\'list\',{\n                domain:session.domain\n            }));\n        }\n        if(session.capabilities.contains(\'roles\')) {\n            database.roles=businessCatalog(\'roles\',\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'resources\')) {\n            database.resources=businessCatalog(\'resources\',\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'grants\')) {\n            database.grants=businessGrants(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.globalPermissions.contains(\'grants:read\')) {\n            database.groups=permissionGroups(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'grants\')) {\n            database.authoritativeAccess={};\n            for(user in database.users) {\n                var access=[];\n                for(app in database.apps) {\n                    if(!(session.appPermissions.get(app.id)||[]).contains(\'grants:read\')) {\n                        continue;\n                    }\n                    var value=effectiveAccess(user.id,app.id,session.domain);\n                    if(value.hasAccess) {\n                        access.add(value);\n                    }\n                }\n                database.authoritativeAccess.put(user.id,access);\n            }\n        }\n        if(session.domain==\'public\' && session.capabilities.contains(\'public-identity\')) {\n            database.legalEntities=publicEntities(\'list\',{});\n        }\n        if(session.capabilities.contains(\'audit\')) {\n            database.logs=sql.select("""\nselect *,tid as id,date_format(event_time, \'%Y-%m-%dT%H:%i:%sZ\') as event_utc\nfrom iam_audit_event_t\norder by event_time desc\nlimit 200\n""").map(e=>({\n                id:e.id,domain:e.identity_domain||\'workforce\',name:e.action,status:\'enabled\',version:1,\n                createdAt:e.event_utc,updatedAt:e.event_utc,type:e.event_type==\'AUTH\'?\'login\':e.event_type==\'API\'?\'api\':\'operation\',actor:e.actor_id||\'未知账号\',module:\'统一身份管理\',\n                action:e.action,target:e.object_id||\'\',result:e.result==\'SUCCESS\'?\'成功\':e.result==\'DENIED\'?\'拒绝\':\'失败\',ip:e.ip||\'\',appId:e.app_id||\'\',traceId:e.trace_id,\n                before:\'\',after:e.snapshot_json||\'\',httpStatus:e.http_status,durationMs:e.duration_ms\n            }));\n        }\n        return {\n            session:session,database:database,capabilities:session.capabilities,settingVersions:settingVersions,directoryPageSize:250,auditPageSize:200\n        };\n    }\n    finally {\n        http.setAttribute(\'idaas.bootstrap.permissionSnapshot\',previousSnapshot);\n    }\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/02.当前会话/02.切换当前身份域.ms');
