INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('578bf90235974c5b9db24e67158916a5',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/03.工作区/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e789f62c9eba4a76abc9fe5cdc833931',NULL,'api','{\n  "properties": {},\n  "id": "9d76df5fd4ad5e05ba9ff2f10dfa75e4",\n  "script": null,\n  "groupId": "af2400b9cd0d518c8a01dfc98665b222",\n  "name": "01.加载平台工作区",\n  "createTime": 1790612165860,\n  "updateTime": 1790948254995,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/bootstrap",\n  "description": "按当前会话的身份域和应用范围汇总工作区指标、应用和目录数据，返回页面初始化所需资料；不读取租户本地账号。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.加载平台工作区\n// 路由：GET /idaas/workspace/bootstrap\n// 业务说明：按当前会话的身份域和应用范围汇总工作区指标、应用和目录数据，返回页面初始化所需资料；不读取租户本地账号。\nimport db;\nimport request;\nimport platformSession;\nimport \'@/idaas/public-entities\' as publicEntities;\nimport \'@/idaas/session\' as sessionInfo;\nimport \'@/idaas/applications\' as applications;\nimport \'@/idaas/settings\' as settings;\nimport \'@/idaas/directory\' as directory;\nimport \'@/idaas/directory-config\' as directoryConfig;\nimport \'@/idaas/business-catalog\' as businessCatalog;\nimport \'@/idaas/business-grants\' as businessGrants;\nimport \'@/idaas/permission-groups\' as permissionGroups;\nimport \'@/idaas/effective-access\' as effectiveAccess;\nimport cn.hutool.json.JSONUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n\n    // 有界读取中央目录及当前应用授权；不查询旧共享账号或应用本地账号。\n    var http=request.get();\n    var previousSnapshot=http.getAttribute(\'idaas.bootstrap.permissionSnapshot\');\n    http.setAttribute(\'idaas.bootstrap.permissionSnapshot\',{\n        operatorId:platformSession.id(),context:null\n    });\n    try {\n        // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n        var sql=db.normal();\n        var session=sessionInfo();\n        var database={\n            schema:1,users:[],orgs:[],apps:[],roles:[],resources:[],groups:[],grants:[],syncConfigs:[],tasks:[],logs:[],catalog:[],legalEntities:[],settings:{\n                workforce:{},public:{}\n            }\n        };\n        var settingVersions={};\n        if(session.capabilities.contains(\'apps\')) {\n            database.apps=applications(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'users\')) {\n            database.users=directory(\'subjects\',\'list\',{\n                domain:session.domain,size:250\n            }).list;\n        }\n        if(session.capabilities.contains(\'orgs\')) {\n            database.orgs=directory(\'orgs\',\'list\',{\n                domain:session.domain,size:250\n            }).list;\n        }\n        if(!session.mustChangePassword && session.permissions.contains(\'settings:read\')) {\n            for(r in settings(\'read\',{})) {\n                database.settings.get(session.domain).putAll(r.value);\n                settingVersions[r.category]=r.version;\n            }\n        }\n        if(session.permissions.contains(\'apps:read\')) {\n            var groups=sql.select("""\nselect *,tid as id,date_format(created_time, \'%Y-%m-%dT%H:%i:%sZ\') as created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') as updated_utc\nfrom iam_application_group_t\nwhere is_del=0\norder by sort_no,code\n""");\n            database.catalog=groups.map(g=>({\n                id:g.id,domain:\'workforce\',name:g.name,code:g.code,category:\'app-group\',description:\'\',status:\'enabled\',version:g.version,\n                createdAt:g.created_utc,updatedAt:g.updated_utc,permissions:[],memberIds:[],appId:\'\',orgId:\'\',userId:\'\',parentId:\'\',value:\'\',expiresAt:\'\',subjectType:\'\'\n            }));\n        }\n        if(session.globalPermissions.contains(\'directory:read\')) {\n            database.catalog.addAll(directoryConfig(\'dictionaries\',\'list\',{\n                domain:session.domain\n            }));\n            database.catalog.addAll(directoryConfig(\'field-definitions\',\'list\',{\n                domain:session.domain\n            }));\n        }\n        if(session.capabilities.contains(\'roles\')) {\n            database.roles=businessCatalog(\'roles\',\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'resources\')) {\n            database.resources=businessCatalog(\'resources\',\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'grants\')) {\n            database.grants=businessGrants(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.globalPermissions.contains(\'grants:read\')) {\n            database.groups=permissionGroups(\'list\',{\n                domain:session.domain\n            });\n        }\n        if(session.capabilities.contains(\'grants\')) {\n            database.authoritativeAccess={};\n            for(user in database.users) {\n                var access=[];\n                for(app in database.apps) {\n                    if(!(session.appPermissions.get(app.id)||[]).contains(\'grants:read\')) {\n                        continue;\n                    }\n                    var value=effectiveAccess(user.id,app.id,session.domain);\n                    if(value.hasAccess) {\n                        access.add(value);\n                    }\n                }\n                database.authoritativeAccess.put(user.id,access);\n            }\n        }\n        if(session.domain==\'public\' && session.capabilities.contains(\'public-identity\')) {\n            database.legalEntities=publicEntities(\'list\',{});\n        }\n        if(session.capabilities.contains(\'audit\')) {\n            database.logs=sql.select("""\nselect *,tid as id,date_format(event_time, \'%Y-%m-%dT%H:%i:%sZ\') as event_utc\nfrom iam_audit_event_t\norder by event_time desc\nlimit 200\n""").map(e=>({\n                id:e.id,domain:e.identity_domain||\'workforce\',name:e.action,status:\'enabled\',version:1,\n                createdAt:e.event_utc,updatedAt:e.event_utc,type:e.event_type==\'AUTH\'?\'login\':e.event_type==\'API\'?\'api\':\'operation\',actor:e.actor_id||\'未知账号\',module:\'统一身份管理\',\n                action:e.action,target:e.object_id||\'\',result:e.result==\'SUCCESS\'?\'成功\':e.result==\'DENIED\'?\'拒绝\':\'失败\',ip:e.ip||\'\',appId:e.app_id||\'\',traceId:e.trace_id,\n                before:\'\',after:e.snapshot_json||\'\',httpStatus:e.http_status,durationMs:e.duration_ms\n            }));\n        }\n        return {\n            session:session,database:database,capabilities:session.capabilities,settingVersions:settingVersions,directoryPageSize:250,auditPageSize:200\n        };\n    }\n    finally {\n        http.setAttribute(\'idaas.bootstrap.permissionSnapshot\',previousSnapshot);\n    }\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/03.工作区/01.加载平台工作区.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('873c3d5ef8004bb8a87189b58781b0b7',NULL,NULL,'{\n  "properties": {},\n  "id": "af2400b9cd0d518c8a01dfc98665b222",\n  "name": "03.工作区",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/workspace",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/03.工作区/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bdce0c67f9fa45c3a8aa451c7cdde059',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6cbf83a89d534737b8cc9200cbb48144',NULL,'api','{\n  "properties": {},\n  "id": "1c1cbd2c3b35549e9ded9eb532e5db53",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "01.查询应用列表",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用，应用权限及身份域过滤后返回可展示字段；不发生写入。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用列表\n// 路由：GET /idaas/applications/list\n// 业务说明：读取符合请求筛选条件的应用，应用权限及身份域过滤后返回可展示字段；不发生写入。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n    var payload = param||{};\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    if(operation==\'list\') {\n        import \'@/idaas/session\' as sessionInfo;\n        var session=sessionInfo();\n        var ids=session.allowedAppIds;\n        if(ids.size()==0) {\n            // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n            guard(\'apps:read\',null,domain);\n            return [];\n        }\n        guard(\'apps:read\',ids[0],domain);\n        var configRows=sql.select("""\nselect app_id,config_code,config_value,value_type\nfrom iam_application_config_t\nwhere config_group=\'PORTAL\'\n    and is_del=0\n    and app_id in (#{ids})\n""");\n        return sql.select("""\nselect a.*,a.tid as id,date_format(a.created_time, \'%Y-%m-%dT%H:%i:%sZ\') as created_utc,\n       date_format(a.updated_time, \'%Y-%m-%dT%H:%i:%sZ\') as updated_utc,g.name as group_name,o.display_name as owner_name,rt.runtime_tenant_id,\n       date_format(rt.verified_time, \'%Y-%m-%dT%H:%i:%sZ\') as verified_utc,rt.binding_status,rt.local_permission_app_id,rt.backend_code,rt.environment\nfrom iam_application_t a\nleft join iam_application_group_t g on g.tid=a.group_id\nand g.is_del=0\nleft join iam_operator_profile_v o on o.tid=a.owner_operator_id\nand o.is_del=0\nleft join iam_application_runtime_t rt on rt.app_id=a.tid\nwhere a.kind=\'BUSINESS\'\n    and a.is_del=0\n    and a.tid in (#{ids})\norder by a.sort_no,a.code\n""").map(a=>{\n            var portal=JSONUtil.createObj();\n            for(config in configRows) {\n                if(config.app_id==a.id) {\n                    portal.put(config.config_code,config.value_type==\'BOOLEAN\'?config.config_value==\'true\':config.config_value);\n                }\n            }\n            return {\n                id:a.id,domain:domain,name:a.name,code:a.code,status:a.status==\'ACTIVE\'?\'enabled\':a.status==\'DRAFT\'?\'pending\':\'disabled\',\n                createdAt:a.created_utc,updatedAt:a.updated_utc,version:a.version,sortNo:a.sort_no,group:a.group_name||\'未分组\',groupId:a.group_id,\n                description:a.description||\'\',homepage:a.homepage||\'\',owner:a.owner_name||\'\',ownerOperatorId:a.owner_operator_id,\n                protocol:a.auth_mode==\'FEDERATED\'?\'OIDC\':\'本地账号\',environment:a.environment||\'\',runtimeTenantId:a.runtime_tenant_id,bindingStatus:a.binding_status||\'PENDING\',\n                bindingVerifiedAt:a.verified_utc,localPermissionAppId:a.local_permission_app_id,authMode:a.auth_mode,provisioningMode:a.provisioning_mode,\n                redirectUris:\'\',logoutUri:\'\',clientId:\'\',clientType:\'public\',mfa:false,accessTtl:0,scopes:[],secretVersion:0,\n                logoUrl:portal.logo||\'\',portalConfig:portal\n            };\n        });\n    }\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/01.查询应用列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e843b9498b304966a295cfdd44ff760b',NULL,'api','{\n  "properties": {},\n  "id": "7a008c9916c45a4aaa460d2085bf954c",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "02.保存应用",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用及必要关联记录，写入审计并返回保存结果。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用\n// 路由：POST /idaas/applications/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用及必要关联记录，写入审计并返回保存结果。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/02.保存应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('03a83c79d2a948a48cff3aa3bf50400c',NULL,'api','{\n  "properties": {},\n  "id": "a760b9ee968459319e61298b087f200e",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "03.归档应用",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用\n// 路由：POST /idaas/applications/remove\n// 业务说明：按标识加载应用并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。限定当前身份域与可管理应用范围；应用主档、运行绑定及界面配置分别持久化，绝不写租户本地登录凭据。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n    var payload = body||{};\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/03.归档应用.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0d0ffb408ee74cc6812957fd91ab3723',NULL,'api','{\n  "properties": {},\n  "id": "dd8968d7f8b15b97a01ade4c88d10c34",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "04.调整应用展示顺序",\n  "createTime": 1790822603348,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/reorder",\n  "description": "核验当前操作人对应用的管理范围，按提交的应用顺序更新控制库排序号；不会触发租户数据同步。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.调整应用展示顺序\n// 路由：POST /idaas/applications/reorder\n// 业务说明：核验当前操作人对应用的管理范围，按提交的应用顺序更新控制库排序号；不会触发租户数据同步。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'reorder\';\n    var payload = body||{};\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    if(operation==\'reorder\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(\'apps:write\',null,domain);\n        var ids=p.ids||[];\n        if(ids.size()<1 || ids.size()>200) {\n            exit 400,\'请提供当前身份域的应用顺序\';\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'applications:reorder\',p,()=>{\n            var rows=sql.select("""\nselect tid as id\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\n    for update\n""");\n            if(rows.size()!=ids.size()) {\n                exit 409,\'应用清单已变化，请刷新后重新排序\';\n            }\n            var expected=rows.map(row=>row.id);\n            var seen=[];\n            for(id in ids) {\n                if(!expected.contains(id) || seen.contains(id)) {\n                    exit 400,\'应用顺序包含重复或无效对象\';\n                }\n                seen.add(id);\n            }\n            var position=0;\n            for(id in ids) {\n                position=position+1;\n                var sortNo=position*10;\n                sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:reorder\',null,null,{\n                count:ids.size()\n            });\n            return {\n                ids:ids\n            };\n        });\n    }\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/04.调整应用展示顺序.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0467f3cb42f0472cbdfcda2c75ef5110',NULL,'api','{\n  "properties": {},\n  "id": "73262d432a0458d8b47bcf3b3fb90037",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "05.查看应用运行绑定",\n  "createTime": 1790618621046,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/runtime-inspection",\n  "description": "读取应用的运行租户、权限应用标识和最近核验结果，并与控制库应用主档关联展示；只读。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.查看应用运行绑定\n// 路由：GET /idaas/applications/runtime-inspection\n// 业务说明：读取应用的运行租户、权限应用标识和最近核验结果，并与控制库应用主档关联展示；只读。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'inspect\';\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    if(operation==\'inspect\') {\n        // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n        guard(\'apps:bind\',target,\'workforce\');\n        var runtime=sql.selectOne("""\nselect runtime_tenant_id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n        if(runtime==null) {\n            exit 409,\'尚未登记运行租户\';\n        }\n        return identityRuntime.inspectTenantBinding(runtime.runtime_tenant_id);\n    }\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/05.查看应用运行绑定.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3e613aa0cea445ed9ee5591ef7ba67e9',NULL,'api','{\n  "properties": {},\n  "id": "b1e014a17e445892a5a311480b75a2d6",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "06.保存应用运行绑定",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/runtime-binding",\n  "description": "校验应用和运行租户标识、权限应用标识的关联，维护控制库运行绑定及核验状态；不创建租户本地账号。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：06.保存应用运行绑定\n// 路由：POST /idaas/applications/runtime-binding\n// 业务说明：校验应用和运行租户标识、权限应用标识的关联，维护控制库运行绑定及核验状态；不创建租户本地账号。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'bind\';\n    var payload = body||{};\n\n    // 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n    // 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n    var permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=guard(permission,p.creating==true?null:target,domain);\n    if(operation==\'save\' && r.sortPosition!=null) {\n        guard(\'apps:write\',null,domain);\n    }\n    var inspection=null;\n    if(operation==\'bind\') {\n        var tenantId=(p.runtimeTenantId||\'\').trim();\n        var localApp=(p.localPermissionAppId||\'\').trim();\n        if(localApp==\'\' || localApp.length()>64 || sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""")==null) {\n            exit 400,\'运行租户或本地权限应用标识不正确\';\n        }\n        inspection=identityRuntime.inspectTenantBinding(tenantId);\n        // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n        var permissionApp=identityRuntime.inTenant(tenantId,()=>db.normal().selectOne("""\nselect id\nfrom rm_menu_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\nlimit 1\n"""));\n        if(permissionApp==null) {\n            exit 400,\'本地权限应用未登记有效菜单，请核对标识\';\n        }\n    }\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'applications:\'+operation,p,()=>{\n        var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(existing!=null && existing.kind!=\'BUSINESS\') {\n            exit 403,\'平台内部应用不在此维护\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(existing!=null && r.version!=existing.version) {\n            exit 409,\'应用已被修改，请刷新后重试\';\n        }\n        if(existing==null && p.creating!=true) {\n            exit 404,\'应用不存在\';\n        }\n        if(operation==\'bind\') {\n            var tenantId=(p.runtimeTenantId||\'\').trim();\n            var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n            if(tid==null) {\n                exit 400,\'运行租户不存在或已停用\';\n            }\n            var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n            if(linked!=null) {\n                exit 409,\'该运行租户已绑定其他应用\';\n            }\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(current!=null && current.runtime_tenant_id!=tenantId) {\n                exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n            }\n            var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n            var localApp=(p.localPermissionAppId||\'\').trim();\n            if(localApp==\'\' || localApp.length()>64) {\n                exit 400,\'请填写本地权限应用标识\';\n            }\n            if(current==null) {\n                sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n                id:target\n            });\n            sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n            return {\n                id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n            };\n        }\n        else if(operation==\'remove\') {\n            var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n            if(binding!=null) {\n                exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n            }\n            sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n        }\n        else if(operation==\'save\') {\n            var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n            var name=(r.name||\'\').trim();\n            var code=(r.code||\'\').trim();\n            var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n            var description=r.description||\'\';\n            var homepage=r.homepage||\'\';\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n            || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n                exit 400,\'请填写有效的应用名称、编码和首页\';\n            }\n            if(existing!=null && code!=existing.code) {\n                exit 400,\'应用编码登记后保持稳定\';\n            }\n            var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n            if(duplicate!=null) {\n                exit 409,\'应用编码已使用\';\n            }\n            var groupId=r.groupId||null;\n            if(r.group!=null && r.group!=\'未分组\') {\n                var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n                groupId=group==null?null:group.id;\n                if(groupId==null) {\n                    exit 400,\'请先在应用分组中登记该分组\';\n                }\n            }\n            if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n                exit 400,\'应用分组不存在\';\n            }\n            var ownerId=r.ownerOperatorId||null;\n            if(r.owner!=null && r.owner!=\'\') {\n                var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(owners.size()!=1) {\n                    exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n                }\n                ownerId=owners[0].id;\n            }\n            if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人不存在或已停用\';\n            }\n            var portal=r.portalConfig;\n            if(portal!=null) {\n                var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n                for(key in portal.keySet()) {\n                    if(!allowed.contains(key) || portal.get(key)==null) {\n                        exit 400,\'应用界面配置包含不支持的字段\';\n                    }\n                    var value=\'\'+portal.get(key);\n                    if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                        if(![\'true\',\'false\'].contains(value)) {\n                            exit 400,\'界面开关配置不正确\';\n                        }\n                    }\n                    else if(key==\'logo\') {\n                        if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                            exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                        }\n                    }\n                    else if(key==\'themeColor\') {\n                        if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                            exit 400,\'主题颜色须为六位十六进制颜色\';\n                        }\n                    }\n                    else if(key==\'systemCode\') {\n                        if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                            exit 400,\'租户系统代码不正确\';\n                        }\n                    }\n                    else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                        exit 400,\'应用界面配置长度超出限制\';\n                    }\n                }\n            }\n            if(existing==null) {\n                sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            target=id;\n            if(portal!=null) {\n                var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n                for(item in saved) {\n                    var retained=false;\n                    for(key in portal.keySet()) {\n                        if(key==item.config_code) {\n                            retained=true;\n                        }\n                    }\n                    if(!retained && item.is_del==0) {\n                        sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                    }\n                }\n                for(key in portal.keySet()) {\n                    var value=\'\'+portal.get(key);\n                    var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                    var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                    if(previous==null) {\n                        var configId=IdUtil.fastSimpleUUID();\n                        sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                    }\n                    else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                        sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                    }\n                }\n            }\n            if(r.sortPosition!=null) {\n                if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                    exit 400,\'显示位置格式不正确\';\n                }\n                var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n                var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n                if(position<1 || position>ordered.size() || position>200) {\n                    exit 400,\'显示位置不在应用清单范围内\';\n                }\n                var next=[];\n                var index=1;\n                for(row in ordered) {\n                    if(row.id!=id) {\n                        if(index==position) {\n                            next.add(id);\n                        }\n                        next.add(row.id);\n                        index=index+1;\n                    }\n                }\n                if(next.size()<ordered.size()) {\n                    next.add(id);\n                }\n                var rank=0;\n                for(appId in next) {\n                    rank=rank+1;\n                    var sortNo=rank*10;\n                    var previous=ordered.filter(row=>row.id==appId)[0];\n                    if(previous.sort_no!=sortNo) {\n                        sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                    }\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(target,\'workforce\');\n            rebuild(target,\'public\');\n        }\n        audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n            id:target\n        });\n        return {\n            id:target\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/06.保存应用运行绑定.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3be72a759ed24404a0f2b6186fd08255',NULL,'api','{\r\n  "properties" : { },\r\n  "id" : "7e158ace27ea5f6d89811d934a5588e0",\r\n  "script" : null,\r\n  "groupId" : "8e1839fbe6a55ce7aafaae3dcf2d15b4",\r\n  "name" : "07.读取应用本地资料",\r\n  "createTime" : 1790728570302,\r\n  "updateTime" : 1791110563416,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/local-inventory",\r\n  "method" : "GET",\r\n  "parameters" : [ ],\r\n  "options" : [ ],\r\n  "requestBody" : "{}",\r\n  "headers" : [ ],\r\n  "paths" : [ ],\r\n  "responseBody" : null,\r\n  "description" : "通过已核验的运行绑定只读查询指定租户的人员、机构、角色、资源及授权现状；读取失败明确报错，不修改平台或租户数据。",\r\n  "requestBodyDefinition" : null,\r\n  "responseBodyDefinition" : null\r\n}\r\n================================\r\n// 接口：07.读取应用本地资料\n// 路由：GET /idaas/applications/local-inventory\n// 业务说明：通过已核验的运行绑定只读查询指定租户的人员、机构、角色、资源及授权现状；读取失败明确报错，不修改平台或租户数据。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'appId\',\'appIds\',\'domain\',\'summary\']) {\n        var values=request.getValues(key);\n        if(values!=null && values.size()>0) {\n            payload.put(key,values[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = payload.summary==\'1\'?\'counts\':\'live\';\n\n    if(payload.appIds!=null) {\n        // 应用卡片只取概要：一次校验权限、一次查运行绑定，并按租户分组聚合本地人数。\n        if(operation!=\'counts\') { exit 400,\'批量读取只支持概要模式\'; }\n        var domain=payload.domain||\'workforce\';\n        if(domain!=\'workforce\') { exit 400,\'身份域不正确\'; }\n        var requestedIds=[];\n        for(rawId in (\'\'+payload.appIds).split(\',\')) {\n            var appId=(\'\'+rawId).trim();\n            if(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\')) { exit 400,\'应用标识不正确\'; }\n            if(!requestedIds.contains(appId)) { requestedIds.add(appId); }\n        }\n        if(requestedIds.size()==0 || requestedIds.size()>50) { exit 400,\'每批应用数量须为 1 至 50 个\'; }\n        var ctx=context();\n        if(ctx.account.must_change_password==1) { exit 403,\'请先在个人中心修改初始密码\'; }\n        var allowed=(appId,permission)=>{\n            for(pair in ctx.pairs) {\n                if(!pair.codes.contains(permission)) { continue; }\n                for(scope in pair.scopes) {\n                    if(scope.identity_domain==domain &&\n                        (scope.scope_kind==\'ALL\' || (scope.scope_kind==\'APPLICATION\' && scope.app_id==appId))) {\n                        return true;\n                    }\n                }\n            }\n            return false;\n        };\n        for(appId in requestedIds) {\n            for(permission in [\'apps:read\',\'users:read\',\'grants:read\']) {\n                if(!allowed(appId,permission)) {\n                    audit(ctx,\'DENIED\',permission,appId,\'SCOPE_OR_PERMISSION\',null);\n                    exit 403,\'当前平台账号无此功能或对象范围权限\';\n                }\n            }\n        }\n        var sql=db.normal();\n        var bindings=sql.select("""\nselect rt.app_id,rt.runtime_tenant_id,rt.local_permission_app_id,rt.binding_status\nfrom iam_application_runtime_t rt\njoin iam_application_t a on a.tid=rt.app_id\nand a.kind=\'BUSINESS\'\nand a.is_del=0\nwhere rt.app_id in\n    <foreach collection="requestedIds" item="id" open="(" close=")" separator=",">#{id}</foreach>\n""");\n        var results={};\n        var tenantIds=[];\n        var bindingsByTenant={};\n        for(appId in requestedIds) {\n            results[appId]={appId:appId,available:false,reason:\'请先核验应用连接\',counts:{\n                users:0,orgs:0,roles:0,resources:0,authorizedUsers:0\n            }};\n        }\n        for(binding in bindings) {\n            var appId=\'\'+(binding.app_id||binding.appId);\n            var tenantId=\'\'+(binding.runtime_tenant_id||binding.runtimeTenantId||\'\');\n            var localApp=\'\'+(binding.local_permission_app_id||binding.localPermissionAppId||\'\');\n            if((binding.binding_status||binding.bindingStatus)!=\'VERIFIED\' || tenantId==\'\' || localApp==\'\') {\n                continue;\n            }\n            if(bindingsByTenant[tenantId]==null) {\n                bindingsByTenant[tenantId]=[];\n                tenantIds.add(tenantId);\n            }\n            bindingsByTenant[tenantId].add({appId:appId,localApp:localApp});\n        }\n        if(tenantIds.size()>10) { exit 400,\'单批跨租户数量不能超过 10 个\'; }\n        for(tenantId in tenantIds) {\n            identityRuntime.inspectTenantBinding(tenantId);\n            var tenantBindings=bindingsByTenant[tenantId];\n            var localApps=tenantBindings.map(x=>x.localApp).distinct();\n            var counts=identityRuntime.inTenant(tenantId,()=>{\n                var tenantSql=db.normal();\n                var people=tenantSql.selectOne("""\nselect count(*) n from rm_user_t\nwhere tenant_id=#{tenantId} and deleted=0\n""");\n                var authorized=tenantSql.select("""\nselect r.app_id as local_app_id,count(distinct u.user_id) n\nfrom rm_user_role_rela_t u\njoin rm_user_t person on person.id=u.user_id\nand person.tenant_id=u.tenant_id\nand person.deleted=0\nand person.status=0\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.app_id in\n    <foreach collection="localApps" item="localApp" open="(" close=")" separator=",">#{localApp}</foreach>\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null or u.end_time>current_timestamp)\ngroup by r.app_id\n""");\n                return {users:people.n,authorized:authorized};\n            });\n            var authorizedByApp={};\n            for(row in counts.authorized) {\n                authorizedByApp[\'\'+(row.local_app_id||row.localAppId)]=row.n;\n            }\n            for(binding in tenantBindings) {\n                results[binding.appId]={appId:binding.appId,available:true,source:\'TENANT_LOCAL\',counts:{\n                    users:counts.users,authorizedUsers:authorizedByApp[binding.localApp]||0\n                }};\n            }\n        }\n        return {items:requestedIds.map(appId=>results[appId])};\n    }\n\n    // 从已核验的运行绑定只读租户本地目录；写入只能由显式的手动导入接口处理。\n    // 本地账号、密码、角色授权与中央人员/授权始终是两个体系。\n    var p=payload||{};\n    var appId=\'\'+(p.appId||\'\');\n    var domain=p.domain||\'workforce\';\n    if(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\') || domain!=\'workforce\') {\n        exit 400,\'应用或身份域不正确\';\n    }\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    guard(\'apps:read\',appId,domain);\n    guard(\'users:read\',appId,domain);\n    guard(\'grants:read\',appId,domain);\n    if(operation!=\'counts\') {\n        guard(\'orgs:read\',appId,domain);\n        guard(\'roles:read\',appId,domain);\n        guard(\'resources:read\',appId,domain);\n    }\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var binding=sql.selectOne("""\nselect rt.runtime_tenant_id,rt.local_permission_app_id,rt.binding_status\nfrom iam_application_runtime_t rt\njoin iam_application_t a on a.tid=rt.app_id\nand a.kind=\'BUSINESS\'\nand a.is_del=0\nwhere rt.app_id=#{appId}\n""");\n    if(binding==null || binding.binding_status!=\'VERIFIED\' || binding.local_permission_app_id==null) {\n        return {\n            available:false,reason:\'请先核验应用连接\',counts:{\n                users:0,orgs:0,roles:0,resources:0,authorizedUsers:0\n            }\n        };\n    }\n    var tenantId=binding.runtime_tenant_id;\n    var localApp=binding.local_permission_app_id;\n    identityRuntime.inspectTenantBinding(tenantId);\n    if(operation==\'counts\') {\n        // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n        return identityRuntime.inTenant(tenantId,()=>{\n            var tenantSql=db.normal();\n            var people=tenantSql.selectOne("""\nselect count(*) n\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\n""");\n            var authorized=tenantSql.selectOne("""\nselect count(distinct u.user_id) n\nfrom rm_user_role_rela_t u\njoin rm_user_t person on person.id=u.user_id\nand person.tenant_id=u.tenant_id\nand person.deleted=0\nand person.status=0\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null\n         or u.end_time>current_timestamp)\n""");\n            return {\n                available:true,source:\'TENANT_LOCAL\',counts:{\n                    users:people.n,authorizedUsers:authorized.n\n                }\n            };\n        });\n    }\n    var local=identityRuntime.inTenant(tenantId,()=>{\n        var tenantSql=db.normal();\n        var people=tenantSql.select("""\nselect id,real_name name,user_name account,status\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\norder by id\n""");\n        var organizations=tenantSql.select("""\nselect id,name,dept_code code,parent_id,status\nfrom rm_org_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\n    and id<>\'ROOT\'\norder by org_path,id\n""");\n        var roles=tenantSql.select("""\nselect id,name,code_num code,status\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\norder by id\n""");\n        var menus=tenantSql.select("""\nselect id,name,code,url,status,resource_type\nfrom rm_menu_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\norder by sort_num,id\n""");\n        var userOrgs=tenantSql.select("""\nselect u.user_id,u.org_id\nfrom rm_user_org_rela_t u\njoin rm_org_t o on o.id=u.org_id\nand o.tenant_id=u.tenant_id\nand o.deleted=0\nwhere u.tenant_id=#{tenantId}\norder by u.user_id,u.job_type,u.id\n""");\n        var userRoles=tenantSql.select("""\nselect distinct u.user_id,u.role_id\nfrom rm_user_role_rela_t u\njoin rm_user_t person on person.id=u.user_id\nand person.tenant_id=u.tenant_id\nand person.deleted=0\nand person.status=0\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null\n         or u.end_time>current_timestamp)\norder by u.user_id,u.role_id\n""");\n        var roleMenus=tenantSql.select("""\nselect distinct x.role_id,x.app_resource_id\nfrom rm_role_menu_rela_t x\njoin rm_role_t r on r.id=x.role_id\nand r.tenant_id=x.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\njoin rm_menu_t m on m.id=x.app_resource_id\nand m.tenant_id=x.tenant_id\nand m.app_id=#{localApp}\nand m.deleted=0\nwhere x.tenant_id=#{tenantId}\norder by x.role_id,x.app_resource_id\n""");\n        var orgName=(id)=>{\n            if(id==null || id==\'ROOT\') {\n                return \'根机构\';\n            }\n            var found=organizations.filter(row=>row.id==id);\n            return found.size()==0?\'关联机构已移除\':found[0].name;\n        };\n        var roleName=(id)=>{\n            var found=roles.filter(row=>row.id==id);\n            return found.size()==0?\'关联角色已移除\':found[0].name;\n        };\n        var userRows=people.map(row=>{\n            var orgIds=userOrgs.filter(link=>link.user_id==row.id).map(link=>link.org_id).distinct();\n            var roleIds=userRoles.filter(link=>link.user_id==row.id).map(link=>link.role_id).distinct();\n            return {\n                id:row.id,name:row.name,account:row.account,status:row.status==0?\'enabled\':\'disabled\',orgIds:orgIds,orgNames:orgIds.map(orgName),roleNames:roleIds.map(roleName),authorized:row.status==0 && roleIds.size()>0\n            };\n        });\n        var orgRows=organizations.map(row=>({\n            id:row.id,name:row.name,code:row.code,parentId:row.parent_id,parentName:orgName(row.parent_id),status:row.status==0?\'enabled\':\'disabled\'\n        }));\n        var roleRows=roles.map(row=>({\n            id:row.id,name:row.name,code:row.code,status:row.status==0?\'enabled\':\'disabled\',userCount:userRoles.filter(link=>link.role_id==row.id).map(link=>link.user_id).distinct().size(),resourceCount:roleMenus.filter(link=>link.role_id==row.id).size()\n        }));\n        var resourceRows=menus.map(row=>({\n            id:row.id,name:row.name,code:row.code,path:row.url,status:row.status==0?\'enabled\':\'disabled\',type:row.resource_type\n        }));\n        return {\n            users:userRows,orgs:orgRows,roles:roleRows,resources:resourceRows,counts:{\n                users:userRows.size(),orgs:orgRows.size(),roles:roleRows.size(),resources:menus.size(),authorizedUsers:userRows.filter(row=>row.authorized).size()\n            }\n        };\n    });\n    if(operation!=\'live\') {\n        exit 400,\'操作不正确\';\n    }\n    return {\n        available:true,source:\'TENANT_LOCAL\',runtimeTenantId:tenantId,localPermissionAppId:localApp,counts:local.counts,\n        users:local.users,orgs:local.orgs,roles:local.roles,resources:local.resources,authorizedUsers:local.users.filter(row=>row.authorized)\n    };\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/07.读取应用本地资料.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7bd0afaff84b478090be4771a3ee8549',NULL,'api','{\n  "properties": {},\n  "id": "2ee9fcbb39945c999ac6ac109947d492",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "08.比较应用目录差异",\n  "createTime": 1790848802248,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/directory-compare",\n  "description": "用户手动触发租户与控制库的人员、机构、角色和资源定义比对，按应用与身份域列出仅存在一侧或字段不一致的资料；不自动同步。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：08.比较应用目录差异\n// 路由：GET /idaas/applications/directory-compare\n// 业务说明：用户手动触发租户与控制库的人员、机构、角色和资源定义比对，按应用与身份域列出仅存在一侧或字段不一致的资料；不自动同步。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/local-inventory\' as localInventory;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nvar ids=request.getValues(\'appId\');\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'preview\';\n    var payload = {\n    appId:ids==null || ids.size()==0?\'\':ids[0]\n};\n\n    // 此流程仅由明确的接口请求触发，不在后台自动扫描或下发租户数据。\n    // 人工对比和按所选差异导入。不得同步账号密码、本地角色、本地授权或自动执行。\n    var p=payload||{};\n    var appId=\'\'+(p.appId||\'\');\n    var domain=\'workforce\';\n    if(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\')) {\n        exit 400,\'应用不正确\';\n    }\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    guard(\'apps:read\',appId,domain);\n    var local=localInventory(\'live\',{\n        appId:appId,domain:domain\n    });\n    if(!local.available) {\n        return {\n            available:false,reason:local.reason\n        };\n    }\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var people=sql.select("""\nselect s.tid as id,s.name,s.account_hint account,a.account_alias appAccount,s.status,s.version\nfrom iam_subject_app_t a\njoin iam_subject_t s on s.tid=a.subject_id\nand s.identity_domain=\'workforce\'\nand s.is_del=0\nwhere a.app_id=#{appId}\n    and a.directory_assigned=1\norder by s.tid\n""");\n    var orgs=sql.select("""\nselect o.tid as id,o.name,o.code,o.parent_id parentId,o.status,o.version\nfrom iam_app_org_t a\njoin iam_org_t o on o.tid=a.org_id\nand o.identity_domain=\'workforce\'\nand o.is_del=0\nwhere a.app_id=#{appId}\n    and a.status=\'ACTIVE\'\norder by o.depth,o.tid\n""");\n    var links=sql.select("""\nselect object_type,local_id,central_id\nfrom iam_tenant_directory_link_t\nwhere app_id=#{appId}\n""");\n    var match=(type,id,central)=>{\n        var mapped=links.filter(x=>x.object_type==type && x.local_id==id);\n        if(mapped.size()>0) {\n            var found=central.filter(x=>x.id==mapped[0].central_id);\n            return found.size()>0?found[0]:null;\n        }\n        // Historical 公安初始化保留了源 ID；仅在该应用已经正式分配的资料中承认同 ID。\n        var same=central.filter(x=>x.id==id);\n        return same.size()>0?same[0]:null;\n    };\n    var compare=(type,localRows,centralRows)=>localRows.map(row=>{\n        var target=match(type,row.id,centralRows);\n        var changed=target!=null && (target.name!=row.name || (target.status==\'ACTIVE\'?\'enabled\':\'disabled\')!=row.status || (type==\'SUBJECT\' && (target.appAccount||target.account||\'\')!=(row.account||\'\')));\n        return {\n            type:type,localId:row.id,localName:row.name,localCode:type==\'ORG\'?row.code:row.account,\n            centralId:target==null?null:target.id,centralName:target==null?null:target.name,\n            state:target==null?\'local_only\':changed?\'different\':\'same\'\n        };\n    });\n    var localPeople=compare(\'SUBJECT\',local.users,people);\n    var localOrgs=compare(\'ORG\',local.orgs,orgs);\n    var mappedPeople=localPeople.filter(x=>x.centralId!=null).map(x=>x.centralId);\n    var mappedOrgs=localOrgs.filter(x=>x.centralId!=null).map(x=>x.centralId);\n    var centralOnly={\n        users:people.filter(x=>!mappedPeople.contains(x.id)).map(x=>({\n            id:x.id,name:x.name,code:x.account||\'\'\n        })),\n        orgs:orgs.filter(x=>!mappedOrgs.contains(x.id)).map(x=>({\n            id:x.id,name:x.name,code:x.code\n        }))\n    };\n    var revision=DigestUtil.sha256Hex(JSONUtil.toJsonStr({\n        localUsers:local.users,localOrgs:local.orgs,people:people,orgs:orgs,links:links\n    }));\n    if(operation==\'preview\') {\n        return {\n            available:true,revision:revision,local:{\n                users:localPeople,orgs:localOrgs\n            },centralOnly:centralOnly,\n            counts:{\n                localUsers:local.users.size(),localOrgs:local.orgs.size(),centralUsers:people.size(),centralOrgs:orgs.size()\n            }\n        };\n    }\n    if(operation!=\'pull\') {\n        exit 400,\'操作不正确\';\n    }\n    guard(\'users:write\',appId,domain);\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'orgs:write\',appId,domain);\n    var selected=p.items||[];\n    if(selected.size()<1 || selected.size()>500) {\n        exit 400,\'请选择 1 至 500 条人员或机构差异\';\n    }\n    if(p.revision!=revision) {\n        exit 409,\'租户或平台资料已变化，请重新查看差异\';\n    }\n    var chosenPeople=selected.filter(x=>x.type==\'SUBJECT\');\n    var chosenOrgs=selected.filter(x=>x.type==\'ORG\');\n    if(chosenPeople.size()+chosenOrgs.size()!=selected.size()) {\n        exit 400,\'对象类型不正确\';\n    }\n    var selectionKeys=selected.map(x=>x.type+\':\'+x.localId);\n    if(selectionKeys.distinct().size()!=selected.size()) {\n        exit 400,\'所选资料重复\';\n    }\n    for(item in selected) {\n        var rows=item.type==\'SUBJECT\'?local.users:local.orgs;\n        if(rows.filter(x=>x.id==item.localId).size()!=1) {\n            exit 400,\'所选租户资料不存在\';\n        }\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'tenant-directory:pull\',p,()=>{\n        guard(\'users:write\',appId,domain);\n        guard(\'orgs:write\',appId,domain);\n        var createdOrgs=[];\n        var createdPeople=[];\n        var updatedOrgs=[];\n        var updatedPeople=[];\n        var ensureOrg=(localId,depth)=>{\n            if(depth>50) {\n                exit 409,\'本地机构层级超过 50 层\';\n            }\n            var sourceRows=local.orgs.filter(x=>x.id==localId);\n            if(sourceRows.size()!=1) {\n                return null;\n            }\n            var source=sourceRows[0];\n            var existing=match(\'ORG\',localId,orgs);\n            if(existing!=null) {\n                return existing.id;\n            }\n            var parentId=source.parentId==null || source.parentId==\'ROOT\'?null:ensureOrg(source.parentId,depth+1);\n            var parent=parentId==null?null:sql.selectOne("""\nselect path,depth\nfrom iam_org_t\nwhere tid=#{parentId}\n    and is_del=0\n""");\n            var centralId=IdUtil.fastSimpleUUID();\n            var linkId=IdUtil.fastSimpleUUID();\n            var candidate=(source.code||\'\').trim();\n            if(!candidate.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\') || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=\'workforce\'\n    and code=#{candidate}\n""")!=null) {\n                candidate=\'TO_\'+DigestUtil.sha256Hex(appId+\':\'+localId).substring(0,60);\n            }\n            var path=(parent==null?\'/\':parent.path)+centralId+\'/\';\n            var level=parent==null?0:parent.depth+1;\n            var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n            sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, status, created_by, updated_by)\nvalues(#{centralId},\'workforce\',#{candidate},#{source.name},#{parentId},#{path},#{level},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            var assignmentId=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_app_org_t(tid, app_id, org_id, include_children, status)\nvalues(#{assignmentId},#{appId},#{centralId},0,\'ACTIVE\')\n""");\n            sql.update("""\ninsert into iam_tenant_directory_link_t(tid,\n                app_id, object_type, local_id, central_id)\nvalues(#{linkId},#{appId},\'ORG\',#{localId},#{centralId})\n""");\n            orgs.add({\n                id:centralId,name:source.name,code:candidate,status:status\n            });\n            links.add({\n                object_type:\'ORG\',local_id:localId,central_id:centralId\n            });\n            createdOrgs.add(centralId);\n            return centralId;\n        };\n        for(item in chosenOrgs) {\n            var source=local.orgs.filter(x=>x.id==item.localId)[0];\n            var target=match(\'ORG\',source.id,orgs);\n            if(target==null) {\n                ensureOrg(source.id,0);\n            }\n            else {\n                var targetId=target.id;\n                var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n                if(target.name!=source.name || target.status!=status) {\n                    sql.update("""\nupdate iam_org_t\nset name=#{source.name},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{targetId}\n""");\n                    updatedOrgs.add(targetId);\n                }\n            }\n        }\n        for(item in chosenPeople) {\n            var source=local.users.filter(x=>x.id==item.localId)[0];\n            var target=match(\'SUBJECT\',source.id,people);\n            var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n            var centralId=target==null?IdUtil.fastSimpleUUID():target.id;\n            if(target==null) {\n                var code=\'TU_\'+DigestUtil.sha256Hex(appId+\':\'+source.id).substring(0,60);\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, status, created_by, updated_by)\nvalues(#{centralId},\'workforce\',#{code},#{source.account},#{source.name},#{status},#{ctx.userId},#{ctx.userId})\n""");\n                var assignmentId=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_app_t(tid,\n                subject_id, app_id, account_alias, directory_assigned, assignment_mode, assignment_status,\n                desired_enabled)\nvalues(#{assignmentId},#{centralId},#{appId},#{source.account},1,\'DIRECTORY_ONLY\',\'ACTIVE\',0)\n""");\n                var linkId=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_tenant_directory_link_t(tid,\n                app_id, object_type, local_id, central_id)\nvalues(#{linkId},#{appId},\'SUBJECT\',#{source.id},#{centralId})\n""");\n                createdPeople.add(centralId);\n            }\n            else if(target.name!=source.name || (target.appAccount||target.account||\'\')!=(source.account||\'\') || target.status!=status) {\n                sql.update("""\nupdate iam_subject_t\nset name=#{source.name},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{centralId}\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset account_alias=#{source.account},desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere app_id=#{appId}\n    and subject_id=#{centralId}\n""");\n                updatedPeople.add(centralId);\n            }\n            // New personnel get their organization membership. Existing central appointments remain untouched.\n            if(target==null) {\n                var primary=true;\n                for(localOrgId in source.orgIds||[]) {\n                    var orgId=ensureOrg(localOrgId,0);\n                    if(orgId==null) {\n                        continue;\n                    }\n                    var appointmentId=IdUtil.fastSimpleUUID();\n                    var isPrimary=primary?1:0;\n                    primary=false;\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, is_primary, status, valid_from)\nvalues(#{appointmentId},#{centralId},#{orgId},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'tenant-directory:pull\',appId,null,{\n            createdUsers:createdPeople.size(),updatedUsers:updatedPeople.size(),createdOrgs:createdOrgs.size(),updatedOrgs:updatedOrgs.size()\n        });\n        return {\n            createdUsers:createdPeople.size(),updatedUsers:updatedPeople.size(),createdOrgs:createdOrgs.size(),updatedOrgs:updatedOrgs.size()\n        };\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/08.比较应用目录差异.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e57b1b0990d74f6d8fb539f93b7472ed',NULL,'api','{\n  "properties": {},\n  "id": "70125b723bc452648ef74d6ec085f2ca",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "09.确认导入应用目录",\n  "createTime": 1790848802311,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/directory-pull",\n  "description": "根据用户确认的差异项把租户人员、机构、角色和资源定义导入控制库，校验应用范围与版本并返回结果；不复制租户密码。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：09.确认导入应用目录\n// 路由：POST /idaas/applications/directory-pull\n// 业务说明：根据用户确认的差异项把租户人员、机构、角色和资源定义导入控制库，校验应用范围与版本并返回结果；不复制租户密码。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/local-inventory\' as localInventory;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'pull\';\n    var payload = body||{};\n\n    // 此流程仅由明确的接口请求触发，不在后台自动扫描或下发租户数据。\n    // 人工对比和按所选差异导入。不得同步账号密码、本地角色、本地授权或自动执行。\n    var p=payload||{};\n    var appId=\'\'+(p.appId||\'\');\n    var domain=\'workforce\';\n    if(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\')) {\n        exit 400,\'应用不正确\';\n    }\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    guard(\'apps:read\',appId,domain);\n    var local=localInventory(\'live\',{\n        appId:appId,domain:domain\n    });\n    if(!local.available) {\n        return {\n            available:false,reason:local.reason\n        };\n    }\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var people=sql.select("""\nselect s.tid as id,s.name,s.account_hint account,a.account_alias appAccount,s.status,s.version\nfrom iam_subject_app_t a\njoin iam_subject_t s on s.tid=a.subject_id\nand s.identity_domain=\'workforce\'\nand s.is_del=0\nwhere a.app_id=#{appId}\n    and a.directory_assigned=1\norder by s.tid\n""");\n    var orgs=sql.select("""\nselect o.tid as id,o.name,o.code,o.parent_id parentId,o.status,o.version\nfrom iam_app_org_t a\njoin iam_org_t o on o.tid=a.org_id\nand o.identity_domain=\'workforce\'\nand o.is_del=0\nwhere a.app_id=#{appId}\n    and a.status=\'ACTIVE\'\norder by o.depth,o.tid\n""");\n    var links=sql.select("""\nselect object_type,local_id,central_id\nfrom iam_tenant_directory_link_t\nwhere app_id=#{appId}\n""");\n    var match=(type,id,central)=>{\n        var mapped=links.filter(x=>x.object_type==type && x.local_id==id);\n        if(mapped.size()>0) {\n            var found=central.filter(x=>x.id==mapped[0].central_id);\n            return found.size()>0?found[0]:null;\n        }\n        // Historical 公安初始化保留了源 ID；仅在该应用已经正式分配的资料中承认同 ID。\n        var same=central.filter(x=>x.id==id);\n        return same.size()>0?same[0]:null;\n    };\n    var compare=(type,localRows,centralRows)=>localRows.map(row=>{\n        var target=match(type,row.id,centralRows);\n        var changed=target!=null && (target.name!=row.name || (target.status==\'ACTIVE\'?\'enabled\':\'disabled\')!=row.status || (type==\'SUBJECT\' && (target.appAccount||target.account||\'\')!=(row.account||\'\')));\n        return {\n            type:type,localId:row.id,localName:row.name,localCode:type==\'ORG\'?row.code:row.account,\n            centralId:target==null?null:target.id,centralName:target==null?null:target.name,\n            state:target==null?\'local_only\':changed?\'different\':\'same\'\n        };\n    });\n    var localPeople=compare(\'SUBJECT\',local.users,people);\n    var localOrgs=compare(\'ORG\',local.orgs,orgs);\n    var mappedPeople=localPeople.filter(x=>x.centralId!=null).map(x=>x.centralId);\n    var mappedOrgs=localOrgs.filter(x=>x.centralId!=null).map(x=>x.centralId);\n    var centralOnly={\n        users:people.filter(x=>!mappedPeople.contains(x.id)).map(x=>({\n            id:x.id,name:x.name,code:x.account||\'\'\n        })),\n        orgs:orgs.filter(x=>!mappedOrgs.contains(x.id)).map(x=>({\n            id:x.id,name:x.name,code:x.code\n        }))\n    };\n    var revision=DigestUtil.sha256Hex(JSONUtil.toJsonStr({\n        localUsers:local.users,localOrgs:local.orgs,people:people,orgs:orgs,links:links\n    }));\n    if(operation!=\'pull\') {\n        exit 400,\'操作不正确\';\n    }\n    guard(\'users:write\',appId,domain);\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'orgs:write\',appId,domain);\n    var selected=p.items||[];\n    if(selected.size()<1 || selected.size()>500) {\n        exit 400,\'请选择 1 至 500 条人员或机构差异\';\n    }\n    if(p.revision!=revision) {\n        exit 409,\'租户或平台资料已变化，请重新查看差异\';\n    }\n    var chosenPeople=selected.filter(x=>x.type==\'SUBJECT\');\n    var chosenOrgs=selected.filter(x=>x.type==\'ORG\');\n    if(chosenPeople.size()+chosenOrgs.size()!=selected.size()) {\n        exit 400,\'对象类型不正确\';\n    }\n    var selectionKeys=selected.map(x=>x.type+\':\'+x.localId);\n    if(selectionKeys.distinct().size()!=selected.size()) {\n        exit 400,\'所选资料重复\';\n    }\n    for(item in selected) {\n        var rows=item.type==\'SUBJECT\'?local.users:local.orgs;\n        if(rows.filter(x=>x.id==item.localId).size()!=1) {\n            exit 400,\'所选租户资料不存在\';\n        }\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'tenant-directory:pull\',p,()=>{\n        guard(\'users:write\',appId,domain);\n        guard(\'orgs:write\',appId,domain);\n        var createdOrgs=[];\n        var createdPeople=[];\n        var updatedOrgs=[];\n        var updatedPeople=[];\n        var ensureOrg=(localId,depth)=>{\n            if(depth>50) {\n                exit 409,\'本地机构层级超过 50 层\';\n            }\n            var sourceRows=local.orgs.filter(x=>x.id==localId);\n            if(sourceRows.size()!=1) {\n                return null;\n            }\n            var source=sourceRows[0];\n            var existing=match(\'ORG\',localId,orgs);\n            if(existing!=null) {\n                return existing.id;\n            }\n            var parentId=source.parentId==null || source.parentId==\'ROOT\'?null:ensureOrg(source.parentId,depth+1);\n            var parent=parentId==null?null:sql.selectOne("""\nselect path,depth\nfrom iam_org_t\nwhere tid=#{parentId}\n    and is_del=0\n""");\n            var centralId=IdUtil.fastSimpleUUID();\n            var linkId=IdUtil.fastSimpleUUID();\n            var candidate=(source.code||\'\').trim();\n            if(!candidate.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\') || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=\'workforce\'\n    and code=#{candidate}\n""")!=null) {\n                candidate=\'TO_\'+DigestUtil.sha256Hex(appId+\':\'+localId).substring(0,60);\n            }\n            var path=(parent==null?\'/\':parent.path)+centralId+\'/\';\n            var level=parent==null?0:parent.depth+1;\n            var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n            sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, status, created_by, updated_by)\nvalues(#{centralId},\'workforce\',#{candidate},#{source.name},#{parentId},#{path},#{level},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            var assignmentId=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_app_org_t(tid, app_id, org_id, include_children, status)\nvalues(#{assignmentId},#{appId},#{centralId},0,\'ACTIVE\')\n""");\n            sql.update("""\ninsert into iam_tenant_directory_link_t(tid,\n                app_id, object_type, local_id, central_id)\nvalues(#{linkId},#{appId},\'ORG\',#{localId},#{centralId})\n""");\n            orgs.add({\n                id:centralId,name:source.name,code:candidate,status:status\n            });\n            links.add({\n                object_type:\'ORG\',local_id:localId,central_id:centralId\n            });\n            createdOrgs.add(centralId);\n            return centralId;\n        };\n        for(item in chosenOrgs) {\n            var source=local.orgs.filter(x=>x.id==item.localId)[0];\n            var target=match(\'ORG\',source.id,orgs);\n            if(target==null) {\n                ensureOrg(source.id,0);\n            }\n            else {\n                var targetId=target.id;\n                var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n                if(target.name!=source.name || target.status!=status) {\n                    sql.update("""\nupdate iam_org_t\nset name=#{source.name},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{targetId}\n""");\n                    updatedOrgs.add(targetId);\n                }\n            }\n        }\n        for(item in chosenPeople) {\n            var source=local.users.filter(x=>x.id==item.localId)[0];\n            var target=match(\'SUBJECT\',source.id,people);\n            var status=source.status==\'enabled\'?\'ACTIVE\':\'DISABLED\';\n            var centralId=target==null?IdUtil.fastSimpleUUID():target.id;\n            if(target==null) {\n                var code=\'TU_\'+DigestUtil.sha256Hex(appId+\':\'+source.id).substring(0,60);\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, status, created_by, updated_by)\nvalues(#{centralId},\'workforce\',#{code},#{source.account},#{source.name},#{status},#{ctx.userId},#{ctx.userId})\n""");\n                var assignmentId=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_app_t(tid,\n                subject_id, app_id, account_alias, directory_assigned, assignment_mode, assignment_status,\n                desired_enabled)\nvalues(#{assignmentId},#{centralId},#{appId},#{source.account},1,\'DIRECTORY_ONLY\',\'ACTIVE\',0)\n""");\n                var linkId=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_tenant_directory_link_t(tid,\n                app_id, object_type, local_id, central_id)\nvalues(#{linkId},#{appId},\'SUBJECT\',#{source.id},#{centralId})\n""");\n                createdPeople.add(centralId);\n            }\n            else if(target.name!=source.name || (target.appAccount||target.account||\'\')!=(source.account||\'\') || target.status!=status) {\n                sql.update("""\nupdate iam_subject_t\nset name=#{source.name},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{centralId}\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset account_alias=#{source.account},desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere app_id=#{appId}\n    and subject_id=#{centralId}\n""");\n                updatedPeople.add(centralId);\n            }\n            // New personnel get their organization membership. Existing central appointments remain untouched.\n            if(target==null) {\n                var primary=true;\n                for(localOrgId in source.orgIds||[]) {\n                    var orgId=ensureOrg(localOrgId,0);\n                    if(orgId==null) {\n                        continue;\n                    }\n                    var appointmentId=IdUtil.fastSimpleUUID();\n                    var isPrimary=primary?1:0;\n                    primary=false;\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, is_primary, status, valid_from)\nvalues(#{appointmentId},#{centralId},#{orgId},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'tenant-directory:pull\',appId,null,{\n            createdUsers:createdPeople.size(),updatedUsers:updatedPeople.size(),createdOrgs:createdOrgs.size(),updatedOrgs:updatedOrgs.size()\n        });\n        return {\n            createdUsers:createdPeople.size(),updatedUsers:updatedPeople.size(),createdOrgs:createdOrgs.size(),updatedOrgs:updatedOrgs.size()\n        };\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/09.确认导入应用目录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('27deb428c52b4ea7a7c3508c6bc2a593',NULL,'api','{\n  "properties": {},\n  "id": "7cb4e9d431d85d5a8c2c865c98c80b96",\n  "script": null,\n  "groupId": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "10.手动下发应用界面配置",\n  "createTime": 1790827272222,\n  "updateTime": 1790948254995,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/push-portal-config",\n  "description": "用户显式发起后读取应用配置表的界面配置，核验运行绑定并调用租户接收端写入；返回每次下发结果，不后台轮询。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：10.手动下发应用界面配置\n// 路由：POST /idaas/applications/push-portal-config\n// 业务说明：用户显式发起后读取应用配置表的界面配置，核验运行绑定并调用租户接收端写入；返回每次下发结果，不后台轮询。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var payload = body||{};\n\n    // 此流程仅由明确的接口请求触发，不在后台自动扫描或下发租户数据。\n    // 用户显式操作才下发；沿用已测试的接收地址、HMAC信任和签名回执。\n    var p=payload||{};\n    var appId=\'\'+(p.appId||\'\');\n    if(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\')) {\n        exit 400,\'应用不正确\';\n    }\n    if(p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请提供有效请求号\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'apps:write\',appId,\'workforce\');\n    guard(\'sync:write\',appId,\'workforce\');\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var app=sql.selectOne("""\nselect tid as id,version\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n    if(app==null) {\n        exit 404,\'应用不存在\';\n    }\n    if(p.appVersion!=app.version) {\n        exit 409,\'应用配置已更新，请刷新后再下发\';\n    }\n    var portal=JSONUtil.createObj();\n    for(item in sql.select("""\nselect config_code,config_value,value_type\nfrom iam_application_config_t\nwhere app_id=#{appId}\n    and config_group=\'PORTAL\'\n    and is_del=0\n""")) {\n        portal.put(item.config_code,item.value_type==\'BOOLEAN\'?item.config_value==\'true\':item.config_value);\n    }\n    if(portal.size()==0) {\n        exit 409,\'请先保存应用界面配置\';\n    }\n    var config=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n    and is_del=0\n    and enabled=1\n    and last_test_result=\'SUCCESS\'\n""");\n    if(config==null) {\n        exit 409,\'请先在同步管理中配置并测试该应用的接收地址\';\n    }\n    var key=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{config.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 409,\'接收端密钥尚未配置\';\n    }\n    var event={\n        eventId:IdUtil.fastSimpleUUID(),appId:appId,receiverInstanceId:config.receiver_instance_id,objectType:\'PORTAL_CONFIG\',objectId:appId,sourceVersion:app.version,action:\'UPSERT\',data:portal\n    };\n    var encoded=identityTransport.canonicalJson(event);\n    var hash=DigestUtil.sha256Hex(encoded);\n    var keyId=JSONUtil.parseObj(key.public_data).keyId;\n    // 仅在本次人工请求中向已配置接收地址发送签名事件。\n    var response=identityTransport.send2(config.endpoint,key.secret_cipher,keyId,appId,config.receiver_instance_id,encoded,config.timeout_seconds);\n    var receipt=response.data==null?null:response.data.receipt;\n    // 核对签名回执的事件号、版本和目标实例，成功后才确认下发结果。\n    var valid=response.code==0 && receipt!=null && receipt.protocol==\'IDAAS/2\' && receipt.appId==appId && receipt.receiverInstanceId==config.receiver_instance_id && receipt.eventId==event.eventId && receipt.objectType==\'PORTAL_CONFIG\' && receipt.objectId==appId && receipt.sourceVersion==app.version && receipt.payloadHash==hash && identityTransport.verifyReceipt(key.secret_cipher,receipt,response.data.receiptSignature);\n    var synced=valid && [\'APPLIED\',\'DUPLICATE\'].contains(receipt.result);\n    var code=valid?receipt.result:\'INVALID_RECEIPT\';\n    var reason=valid?receipt.message||\'\': \'接收地址未返回有效的签名回执\';\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'applications:push-portal\',p,()=>{\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,synced?\'SUCCESS\':\'FAILED\',\'applications:push-portal\',appId,code,{\n            appId:appId,configKeys:portal.keySet(),receiverInstanceId:config.receiver_instance_id\n        });\n        return {\n            synced:synced,result:code,message:reason,appId:appId,version:app.version\n        };\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/10.手动下发应用界面配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8d9ef0889ec24b27b3f3c34f4007344a',NULL,NULL,'{\n  "properties": {},\n  "id": "8e1839fbe6a55ce7aafaae3dcf2d15b4",\n  "name": "04.应用管理",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/applications",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/04.应用管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2ca2490e690b44079c08fe0ad551b2d6',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/05.应用分组/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('93f2001edb444583989136abe1ac84b3',NULL,'api','{\n  "properties": {},\n  "id": "5f940f70f14c5e8ba50ce9133a4f9a24",\n  "script": null,\n  "groupId": "66a86e6604e9528e80208f8083448b77",\n  "name": "01.查询应用分组列表",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用分组，应用权限及身份域过滤后返回可展示字段；不发生写入。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用分组列表\n// 路由：GET /idaas/application-groups/list\n// 业务说明：读取符合请求筛选条件的应用分组，应用权限及身份域过滤后返回可展示字段；不发生写入。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n    var payload = param||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'apps:read\':\'apps:write\',null,\'workforce\');\n    if(operation==\'list\') {\n        return sql.select("""\nselect tid as id,code,name,sort_no,version\nfrom iam_application_group_t\nwhere is_del=0\norder by sort_no,code\n""");\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'groups:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=r.version) {\n            exit 409,\'分组已被修改，请刷新\';\n        }\n        if(old==null && p.creating!=true) {\n            exit 404,\'分组不存在\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere group_id=#{id}\n    and is_del=0\nlimit 1\n""")!=null) {\n                exit 409,\'分组仍有关联应用\';\n            }\n            sql.update("""\nupdate iam_application_group_t\nset is_del=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            var code=(r.code||\'\').trim();\n            var name=(r.name||\'\').trim();\n            var sort=r.sortNo||0;\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\')) {\n                exit 400,\'分组名称或编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'已登记分组编码保持稳定\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere code=#{code}\n    and tid<>#{id}\n""")!=null) {\n                exit 409,\'分组编码已使用\';\n            }\n            if(old==null) {\n                sql.update("""\ninsert into iam_application_group_t(tid, code, name, sort_no)\nvalues(#{id},#{code},#{name},#{sort})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_group_t\nset name=#{name},sort_no=#{sort},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'groups:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/05.应用分组/01.查询应用分组列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ad143714faa6495787cb4fc6504f3d8f',NULL,'api','{\n  "properties": {},\n  "id": "e61411e62bc5562fb8e3e453e3b63340",\n  "script": null,\n  "groupId": "66a86e6604e9528e80208f8083448b77",\n  "name": "02.保存应用分组",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用分组及必要关联记录，写入审计并返回保存结果。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用分组\n// 路由：POST /idaas/application-groups/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用分组及必要关联记录，写入审计并返回保存结果。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'apps:read\':\'apps:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'groups:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=r.version) {\n            exit 409,\'分组已被修改，请刷新\';\n        }\n        if(old==null && p.creating!=true) {\n            exit 404,\'分组不存在\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere group_id=#{id}\n    and is_del=0\nlimit 1\n""")!=null) {\n                exit 409,\'分组仍有关联应用\';\n            }\n            sql.update("""\nupdate iam_application_group_t\nset is_del=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            var code=(r.code||\'\').trim();\n            var name=(r.name||\'\').trim();\n            var sort=r.sortNo||0;\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\')) {\n                exit 400,\'分组名称或编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'已登记分组编码保持稳定\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere code=#{code}\n    and tid<>#{id}\n""")!=null) {\n                exit 409,\'分组编码已使用\';\n            }\n            if(old==null) {\n                sql.update("""\ninsert into iam_application_group_t(tid, code, name, sort_no)\nvalues(#{id},#{code},#{name},#{sort})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_group_t\nset name=#{name},sort_no=#{sort},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'groups:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/05.应用分组/02.保存应用分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99662f5070e04e968cefb4f595acf6ee',NULL,'api','{\n  "properties": {},\n  "id": "ab76991d24435043bff63e1fef264ddd",\n  "script": null,\n  "groupId": "66a86e6604e9528e80208f8083448b77",\n  "name": "03.归档应用分组",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用分组并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用分组\n// 路由：POST /idaas/application-groups/remove\n// 业务说明：按标识加载应用分组并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只操作控制库的应用分组，并维护排序和软删除状态；关联应用仍按独立应用记录管理。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n    var payload = body||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'apps:read\':\'apps:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'groups:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=r.version) {\n            exit 409,\'分组已被修改，请刷新\';\n        }\n        if(old==null && p.creating!=true) {\n            exit 404,\'分组不存在\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere group_id=#{id}\n    and is_del=0\nlimit 1\n""")!=null) {\n                exit 409,\'分组仍有关联应用\';\n            }\n            sql.update("""\nupdate iam_application_group_t\nset is_del=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            var code=(r.code||\'\').trim();\n            var name=(r.name||\'\').trim();\n            var sort=r.sortNo||0;\n            if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\')) {\n                exit 400,\'分组名称或编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'已登记分组编码保持稳定\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere code=#{code}\n    and tid<>#{id}\n""")!=null) {\n                exit 409,\'分组编码已使用\';\n            }\n            if(old==null) {\n                sql.update("""\ninsert into iam_application_group_t(tid, code, name, sort_no)\nvalues(#{id},#{code},#{name},#{sort})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_application_group_t\nset name=#{name},sort_no=#{sort},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'groups:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/05.应用分组/03.归档应用分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b0c39b84a76b4f329dd2b212d2db73bb',NULL,NULL,'{\n  "properties": {},\n  "id": "66a86e6604e9528e80208f8083448b77",\n  "name": "05.应用分组",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/application-groups",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/05.应用分组/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('13a88c47a80641888772cd2b977db2d3',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('001fd31ec98348ffba3a393da9a103dc',NULL,'api','{\n  "properties": {},\n  "id": "5e04ef923b49583a816bb928384d2985",\n  "script": null,\n  "groupId": "64e411148c13506897632e1f5bbe2c15",\n  "name": "01.查询平台操作账号列表",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的平台操作账号，应用权限及身份域过滤后返回可展示字段；不发生写入。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询平台操作账号列表\n// 路由：GET /idaas/operators/list\n// 业务说明：读取符合请求筛选条件的平台操作账号，应用权限及身份域过滤后返回可展示字段；不发生写入。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n    var payload = param||{};\n\n    // 平台账号生命周期；凭据仅写安全表，停用/重置导致安全版本失效。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'operators:read\':\'operators:write\',null,\'workforce\');\n    if(operation==\'list\') {\n        return sql.select("""\nselect o.tid as id,o.username,o.display_name,o.subject_id,o.subject_version,o.status,o.version,o.must_change_password,\n       date_format(o.last_login_time, \'%Y-%m-%dT%H:%i:%sZ\') as last_login_time, s.failed_count,date_format(s.locked_until,\n\n        \'%Y-%m-%dT%H:%i:%sZ\') as locked_until,\n       s.security_version\nfrom iam_operator_profile_v o\nleft join iam_account_security_t s on s.principal_kind=\'OPERATOR\'\nand s.principal_id=o.tid\nwhere o.is_del=0\norder by o.username\n""");\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'operators:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'平台账号不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && r.version!=old.version) {\n            exit 409,\'账号已被修改，请刷新\';\n        }\n        if(id==ctx.userId && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            exit 409,\'不能在当前会话停用或删除自己\';\n        }\n        if(id==ctx.userId && operation==\'reset-password\') {\n            exit 400,\'请在个人中心修改自己的密码\';\n        }\n        if(old!=null && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t rr on rr.tid=a.role_id\nand rr.status=\'ACTIVE\'\nand rr.is_del=0\njoin iam_role_resource_rela_t rel on rel.role_id=rr.tid\njoin iam_resource_t res on res.tid=rel.resource_id\njoin iam_operator_scope_t sc on sc.assignment_id=a.tid\nand sc.scope_kind=\'ALL\'\nand sc.identity_domain=\'workforce\'\nwhere o.is_del=0\n    and o.status=\'ACTIVE\'\n    and o.tid<>#{id}\n    and res.code=\'operators:grant\'\n    and res.is_del=0\n    and res.status=\'ACTIVE\'\n""");\n            if(managers.total==0) {\n                exit 409,\'不能移除最后一个有效的权限管理账号\';\n            }\n        }\n        if(operation==\'reset-password\') {\n            passwordPolicy(r.password);\n            var encoded=iamSecurity.hash(r.password);\n            var credId=IdUtil.fastSimpleUUID();\n            var current=sql.selectOne("""\nselect coalesce(max(revision), 0)+1 as revision\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n""");\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_hash, status)\nvalues(#{credId},\'OPERATOR\',#{id},\'PASSWORD\',\'primary\',#{current.revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null,password_changed_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'unlock\') {\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            sql.update("""\nupdate iam_operator_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var username=(r.username||\'\').trim().toLowerCase();\n            var name=(r.displayName||r.display_name||\'\').trim();\n            var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || name==\'\' || name.length()>100) {\n                exit 400,\'账号或显示名称不正确\';\n            }\n            if(old!=null && username!=old.username) {\n                exit 400,\'登录账号创建后保持稳定\';\n            }\n            if(old!=null && r.subjectId!=null && r.subjectId!=old.subject_id) {\n                exit 400,\'关联人员创建后保持稳定\';\n            }\n            if(old==null) {\n                var subjectId=r.subjectId||null;\n                var storedName=name;\n                if(subjectId!=null) {\n                    var person=sql.selectOne("""\nselect tid as id,name\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and status=\'ACTIVE\' and is_del=0\n""");\n                    if(person==null || person.name!=name) {\n                        exit 400,\'关联人员不存在或姓名已变更\';\n                    }\n                    var scope=directoryScope(\'users:read\',\'workforce\');\n                    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n                    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n                        exit 403,\'关联人员超出中央资料可见范围\';\n                    }\n                    storedName=null;\n                }\n                var mustChange=passwordPolicy(r.password).forceChange==false?0:1;\n                id=IdUtil.fastSimpleUUID();\n                var securityId=IdUtil.fastSimpleUUID();\n                var credentialId=IdUtil.fastSimpleUUID();\n                var encoded=iamSecurity.hash(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n""")!=null) {\n                    exit 409,\'平台账号已存在\';\n                }\n                sql.update("""\ninsert into iam_operator_t(tid,\n                username, display_name, subject_id, status, must_change_password, created_by, updated_by)\nvalues(#{id},#{username},#{storedName},#{subjectId},#{status},#{mustChange},#{ctx.userId},#{ctx.userId})\n""");\n                sql.update("""\ninsert into iam_account_security_t(tid,\n                principal_kind, principal_id, password_changed_time)\nvalues(#{securityId},\'OPERATOR\',#{id},utc_timestamp(6))\n""");\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                operatorName(id,old.subject_id,name,r.subjectVersion,ctx.userId,false);\n                sql.update("""\nupdate iam_operator_t\nset status=#{status},version=version+1,\n        updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{id}\n""");\n                if(old.status!=status) {\n                    sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'operators:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/01.查询平台操作账号列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1d4ebb3c875d439eb3e84c80b733bf23',NULL,'api','{\n  "properties": {},\n  "id": "5c56009a3c805d3a90bd53cf23e8245c",\n  "script": null,\n  "groupId": "64e411148c13506897632e1f5bbe2c15",\n  "name": "02.保存平台操作账号",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新平台操作账号及必要关联记录，写入审计并返回保存结果。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存平台操作账号\n// 路由：POST /idaas/operators/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新平台操作账号及必要关联记录，写入审计并返回保存结果。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 平台账号生命周期；凭据仅写安全表，停用/重置导致安全版本失效。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'operators:read\':\'operators:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'operators:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'平台账号不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && r.version!=old.version) {\n            exit 409,\'账号已被修改，请刷新\';\n        }\n        if(id==ctx.userId && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            exit 409,\'不能在当前会话停用或删除自己\';\n        }\n        if(id==ctx.userId && operation==\'reset-password\') {\n            exit 400,\'请在个人中心修改自己的密码\';\n        }\n        if(old!=null && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t rr on rr.tid=a.role_id\nand rr.status=\'ACTIVE\'\nand rr.is_del=0\njoin iam_role_resource_rela_t rel on rel.role_id=rr.tid\njoin iam_resource_t res on res.tid=rel.resource_id\njoin iam_operator_scope_t sc on sc.assignment_id=a.tid\nand sc.scope_kind=\'ALL\'\nand sc.identity_domain=\'workforce\'\nwhere o.is_del=0\n    and o.status=\'ACTIVE\'\n    and o.tid<>#{id}\n    and res.code=\'operators:grant\'\n    and res.is_del=0\n    and res.status=\'ACTIVE\'\n""");\n            if(managers.total==0) {\n                exit 409,\'不能移除最后一个有效的权限管理账号\';\n            }\n        }\n        if(operation==\'reset-password\') {\n            passwordPolicy(r.password);\n            var encoded=iamSecurity.hash(r.password);\n            var credId=IdUtil.fastSimpleUUID();\n            var current=sql.selectOne("""\nselect coalesce(max(revision), 0)+1 as revision\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n""");\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_hash, status)\nvalues(#{credId},\'OPERATOR\',#{id},\'PASSWORD\',\'primary\',#{current.revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null,password_changed_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'unlock\') {\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            sql.update("""\nupdate iam_operator_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var username=(r.username||\'\').trim().toLowerCase();\n            var name=(r.displayName||r.display_name||\'\').trim();\n            var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || name==\'\' || name.length()>100) {\n                exit 400,\'账号或显示名称不正确\';\n            }\n            if(old!=null && username!=old.username) {\n                exit 400,\'登录账号创建后保持稳定\';\n            }\n            if(old!=null && r.subjectId!=null && r.subjectId!=old.subject_id) {\n                exit 400,\'关联人员创建后保持稳定\';\n            }\n            if(old==null) {\n                var subjectId=r.subjectId||null;\n                var storedName=name;\n                if(subjectId!=null) {\n                    var person=sql.selectOne("""\nselect tid as id,name\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and status=\'ACTIVE\' and is_del=0\n""");\n                    if(person==null || person.name!=name) {\n                        exit 400,\'关联人员不存在或姓名已变更\';\n                    }\n                    var scope=directoryScope(\'users:read\',\'workforce\');\n                    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n                    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n                        exit 403,\'关联人员超出中央资料可见范围\';\n                    }\n                    storedName=null;\n                }\n                var mustChange=passwordPolicy(r.password).forceChange==false?0:1;\n                id=IdUtil.fastSimpleUUID();\n                var securityId=IdUtil.fastSimpleUUID();\n                var credentialId=IdUtil.fastSimpleUUID();\n                var encoded=iamSecurity.hash(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n""")!=null) {\n                    exit 409,\'平台账号已存在\';\n                }\n                sql.update("""\ninsert into iam_operator_t(tid,\n                username, display_name, subject_id, status, must_change_password, created_by, updated_by)\nvalues(#{id},#{username},#{storedName},#{subjectId},#{status},#{mustChange},#{ctx.userId},#{ctx.userId})\n""");\n                sql.update("""\ninsert into iam_account_security_t(tid,\n                principal_kind, principal_id, password_changed_time)\nvalues(#{securityId},\'OPERATOR\',#{id},utc_timestamp(6))\n""");\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                operatorName(id,old.subject_id,name,r.subjectVersion,ctx.userId,false);\n                sql.update("""\nupdate iam_operator_t\nset status=#{status},version=version+1,\n        updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{id}\n""");\n                if(old.status!=status) {\n                    sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'operators:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/02.保存平台操作账号.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4359ab0ebf514650a9b484c5cce190fc',NULL,'api','{\n  "properties": {},\n  "id": "bbe37153132b5ba3b39df56f5c772286",\n  "script": null,\n  "groupId": "64e411148c13506897632e1f5bbe2c15",\n  "name": "03.归档平台操作账号",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载平台操作账号并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档平台操作账号\n// 路由：POST /idaas/operators/remove\n// 业务说明：按标识加载平台操作账号并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。平台操作账号只用于统一身份管理控制台；凭据与安全状态独立保存，不创建或修改租户本地账号。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n    var payload = body||{};\n\n    // 平台账号生命周期；凭据仅写安全表，停用/重置导致安全版本失效。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'operators:read\':\'operators:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'operators:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'平台账号不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && r.version!=old.version) {\n            exit 409,\'账号已被修改，请刷新\';\n        }\n        if(id==ctx.userId && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            exit 409,\'不能在当前会话停用或删除自己\';\n        }\n        if(id==ctx.userId && operation==\'reset-password\') {\n            exit 400,\'请在个人中心修改自己的密码\';\n        }\n        if(old!=null && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t rr on rr.tid=a.role_id\nand rr.status=\'ACTIVE\'\nand rr.is_del=0\njoin iam_role_resource_rela_t rel on rel.role_id=rr.tid\njoin iam_resource_t res on res.tid=rel.resource_id\njoin iam_operator_scope_t sc on sc.assignment_id=a.tid\nand sc.scope_kind=\'ALL\'\nand sc.identity_domain=\'workforce\'\nwhere o.is_del=0\n    and o.status=\'ACTIVE\'\n    and o.tid<>#{id}\n    and res.code=\'operators:grant\'\n    and res.is_del=0\n    and res.status=\'ACTIVE\'\n""");\n            if(managers.total==0) {\n                exit 409,\'不能移除最后一个有效的权限管理账号\';\n            }\n        }\n        if(operation==\'reset-password\') {\n            passwordPolicy(r.password);\n            var encoded=iamSecurity.hash(r.password);\n            var credId=IdUtil.fastSimpleUUID();\n            var current=sql.selectOne("""\nselect coalesce(max(revision), 0)+1 as revision\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n""");\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_hash, status)\nvalues(#{credId},\'OPERATOR\',#{id},\'PASSWORD\',\'primary\',#{current.revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null,password_changed_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'unlock\') {\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            sql.update("""\nupdate iam_operator_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var username=(r.username||\'\').trim().toLowerCase();\n            var name=(r.displayName||r.display_name||\'\').trim();\n            var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || name==\'\' || name.length()>100) {\n                exit 400,\'账号或显示名称不正确\';\n            }\n            if(old!=null && username!=old.username) {\n                exit 400,\'登录账号创建后保持稳定\';\n            }\n            if(old!=null && r.subjectId!=null && r.subjectId!=old.subject_id) {\n                exit 400,\'关联人员创建后保持稳定\';\n            }\n            if(old==null) {\n                var subjectId=r.subjectId||null;\n                var storedName=name;\n                if(subjectId!=null) {\n                    var person=sql.selectOne("""\nselect tid as id,name\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and status=\'ACTIVE\' and is_del=0\n""");\n                    if(person==null || person.name!=name) {\n                        exit 400,\'关联人员不存在或姓名已变更\';\n                    }\n                    var scope=directoryScope(\'users:read\',\'workforce\');\n                    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n                    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n                        exit 403,\'关联人员超出中央资料可见范围\';\n                    }\n                    storedName=null;\n                }\n                var mustChange=passwordPolicy(r.password).forceChange==false?0:1;\n                id=IdUtil.fastSimpleUUID();\n                var securityId=IdUtil.fastSimpleUUID();\n                var credentialId=IdUtil.fastSimpleUUID();\n                var encoded=iamSecurity.hash(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n""")!=null) {\n                    exit 409,\'平台账号已存在\';\n                }\n                sql.update("""\ninsert into iam_operator_t(tid,\n                username, display_name, subject_id, status, must_change_password, created_by, updated_by)\nvalues(#{id},#{username},#{storedName},#{subjectId},#{status},#{mustChange},#{ctx.userId},#{ctx.userId})\n""");\n                sql.update("""\ninsert into iam_account_security_t(tid,\n                principal_kind, principal_id, password_changed_time)\nvalues(#{securityId},\'OPERATOR\',#{id},utc_timestamp(6))\n""");\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                operatorName(id,old.subject_id,name,r.subjectVersion,ctx.userId,false);\n                sql.update("""\nupdate iam_operator_t\nset status=#{status},version=version+1,\n        updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{id}\n""");\n                if(old.status!=status) {\n                    sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'operators:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/03.归档平台操作账号.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0c11eeaf3a83472880cc761b84ae4e6e',NULL,'api','{\n  "properties": {},\n  "id": "2049857ef4b552d5a47490851cb25d97",\n  "script": null,\n  "groupId": "64e411148c13506897632e1f5bbe2c15",\n  "name": "04.重置平台操作账号密码",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/reset-password",\n  "description": "核验平台账号管理范围与密码策略，更新独立安全凭据并提升安全版本，使旧会话失效并记录审计。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.重置平台操作账号密码\n// 路由：POST /idaas/operators/reset-password\n// 业务说明：核验平台账号管理范围与密码策略，更新独立安全凭据并提升安全版本，使旧会话失效并记录审计。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'reset-password\';\n    var payload = body||{};\n\n    // 平台账号生命周期；凭据仅写安全表，停用/重置导致安全版本失效。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'operators:read\':\'operators:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'operators:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'平台账号不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && r.version!=old.version) {\n            exit 409,\'账号已被修改，请刷新\';\n        }\n        if(id==ctx.userId && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            exit 409,\'不能在当前会话停用或删除自己\';\n        }\n        if(id==ctx.userId && operation==\'reset-password\') {\n            exit 400,\'请在个人中心修改自己的密码\';\n        }\n        if(old!=null && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t rr on rr.tid=a.role_id\nand rr.status=\'ACTIVE\'\nand rr.is_del=0\njoin iam_role_resource_rela_t rel on rel.role_id=rr.tid\njoin iam_resource_t res on res.tid=rel.resource_id\njoin iam_operator_scope_t sc on sc.assignment_id=a.tid\nand sc.scope_kind=\'ALL\'\nand sc.identity_domain=\'workforce\'\nwhere o.is_del=0\n    and o.status=\'ACTIVE\'\n    and o.tid<>#{id}\n    and res.code=\'operators:grant\'\n    and res.is_del=0\n    and res.status=\'ACTIVE\'\n""");\n            if(managers.total==0) {\n                exit 409,\'不能移除最后一个有效的权限管理账号\';\n            }\n        }\n        if(operation==\'reset-password\') {\n            passwordPolicy(r.password);\n            var encoded=iamSecurity.hash(r.password);\n            var credId=IdUtil.fastSimpleUUID();\n            var current=sql.selectOne("""\nselect coalesce(max(revision), 0)+1 as revision\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n""");\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_hash, status)\nvalues(#{credId},\'OPERATOR\',#{id},\'PASSWORD\',\'primary\',#{current.revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null,password_changed_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'unlock\') {\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            sql.update("""\nupdate iam_operator_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var username=(r.username||\'\').trim().toLowerCase();\n            var name=(r.displayName||r.display_name||\'\').trim();\n            var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || name==\'\' || name.length()>100) {\n                exit 400,\'账号或显示名称不正确\';\n            }\n            if(old!=null && username!=old.username) {\n                exit 400,\'登录账号创建后保持稳定\';\n            }\n            if(old!=null && r.subjectId!=null && r.subjectId!=old.subject_id) {\n                exit 400,\'关联人员创建后保持稳定\';\n            }\n            if(old==null) {\n                var subjectId=r.subjectId||null;\n                var storedName=name;\n                if(subjectId!=null) {\n                    var person=sql.selectOne("""\nselect tid as id,name\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and status=\'ACTIVE\' and is_del=0\n""");\n                    if(person==null || person.name!=name) {\n                        exit 400,\'关联人员不存在或姓名已变更\';\n                    }\n                    var scope=directoryScope(\'users:read\',\'workforce\');\n                    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n                    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n                        exit 403,\'关联人员超出中央资料可见范围\';\n                    }\n                    storedName=null;\n                }\n                var mustChange=passwordPolicy(r.password).forceChange==false?0:1;\n                id=IdUtil.fastSimpleUUID();\n                var securityId=IdUtil.fastSimpleUUID();\n                var credentialId=IdUtil.fastSimpleUUID();\n                var encoded=iamSecurity.hash(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n""")!=null) {\n                    exit 409,\'平台账号已存在\';\n                }\n                sql.update("""\ninsert into iam_operator_t(tid,\n                username, display_name, subject_id, status, must_change_password, created_by, updated_by)\nvalues(#{id},#{username},#{storedName},#{subjectId},#{status},#{mustChange},#{ctx.userId},#{ctx.userId})\n""");\n                sql.update("""\ninsert into iam_account_security_t(tid,\n                principal_kind, principal_id, password_changed_time)\nvalues(#{securityId},\'OPERATOR\',#{id},utc_timestamp(6))\n""");\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                operatorName(id,old.subject_id,name,r.subjectVersion,ctx.userId,false);\n                sql.update("""\nupdate iam_operator_t\nset status=#{status},version=version+1,\n        updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{id}\n""");\n                if(old.status!=status) {\n                    sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'operators:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/04.重置平台操作账号密码.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4b7a0c6290974f9b8080efdf0163c987',NULL,'api','{\n  "properties": {},\n  "id": "8f03bf6ef638590086272b685efc3035",\n  "script": null,\n  "groupId": "64e411148c13506897632e1f5bbe2c15",\n  "name": "05.解除平台账号锁定",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/unlock",\n  "description": "校验平台账号管理权限，清除失败登录锁定状态，保留安全审计；不会修改租户本地账号。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.解除平台账号锁定\n// 路由：POST /idaas/operators/unlock\n// 业务说明：校验平台账号管理权限，清除失败登录锁定状态，保留安全审计；不会修改租户本地账号。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'unlock\';\n    var payload = body||{};\n\n    // 平台账号生命周期；凭据仅写安全表，停用/重置导致安全版本失效。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'operators:read\':\'operators:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'operators:\'+operation,p,()=>{\n        var id=r.id;\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'平台账号不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && r.version!=old.version) {\n            exit 409,\'账号已被修改，请刷新\';\n        }\n        if(id==ctx.userId && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            exit 409,\'不能在当前会话停用或删除自己\';\n        }\n        if(id==ctx.userId && operation==\'reset-password\') {\n            exit 400,\'请在个人中心修改自己的密码\';\n        }\n        if(old!=null && (operation==\'remove\' || r.status==\'DISABLED\' || r.status==\'disabled\')) {\n            var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t rr on rr.tid=a.role_id\nand rr.status=\'ACTIVE\'\nand rr.is_del=0\njoin iam_role_resource_rela_t rel on rel.role_id=rr.tid\njoin iam_resource_t res on res.tid=rel.resource_id\njoin iam_operator_scope_t sc on sc.assignment_id=a.tid\nand sc.scope_kind=\'ALL\'\nand sc.identity_domain=\'workforce\'\nwhere o.is_del=0\n    and o.status=\'ACTIVE\'\n    and o.tid<>#{id}\n    and res.code=\'operators:grant\'\n    and res.is_del=0\n    and res.status=\'ACTIVE\'\n""");\n            if(managers.total==0) {\n                exit 409,\'不能移除最后一个有效的权限管理账号\';\n            }\n        }\n        if(operation==\'reset-password\') {\n            passwordPolicy(r.password);\n            var encoded=iamSecurity.hash(r.password);\n            var credId=IdUtil.fastSimpleUUID();\n            var current=sql.selectOne("""\nselect coalesce(max(revision), 0)+1 as revision\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n""");\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_hash, status)\nvalues(#{credId},\'OPERATOR\',#{id},\'PASSWORD\',\'primary\',#{current.revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null,password_changed_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'unlock\') {\n            sql.update("""\nupdate iam_account_security_t\nset failed_count=0,locked_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            sql.update("""\nupdate iam_operator_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var username=(r.username||\'\').trim().toLowerCase();\n            var name=(r.displayName||r.display_name||\'\').trim();\n            var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || name==\'\' || name.length()>100) {\n                exit 400,\'账号或显示名称不正确\';\n            }\n            if(old!=null && username!=old.username) {\n                exit 400,\'登录账号创建后保持稳定\';\n            }\n            if(old!=null && r.subjectId!=null && r.subjectId!=old.subject_id) {\n                exit 400,\'关联人员创建后保持稳定\';\n            }\n            if(old==null) {\n                var subjectId=r.subjectId||null;\n                var storedName=name;\n                if(subjectId!=null) {\n                    var person=sql.selectOne("""\nselect tid as id,name\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and status=\'ACTIVE\' and is_del=0\n""");\n                    if(person==null || person.name!=name) {\n                        exit 400,\'关联人员不存在或姓名已变更\';\n                    }\n                    var scope=directoryScope(\'users:read\',\'workforce\');\n                    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n                    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n                        exit 403,\'关联人员超出中央资料可见范围\';\n                    }\n                    storedName=null;\n                }\n                var mustChange=passwordPolicy(r.password).forceChange==false?0:1;\n                id=IdUtil.fastSimpleUUID();\n                var securityId=IdUtil.fastSimpleUUID();\n                var credentialId=IdUtil.fastSimpleUUID();\n                var encoded=iamSecurity.hash(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere active_username=#{username}\n""")!=null) {\n                    exit 409,\'平台账号已存在\';\n                }\n                sql.update("""\ninsert into iam_operator_t(tid,\n                username, display_name, subject_id, status, must_change_password, created_by, updated_by)\nvalues(#{id},#{username},#{storedName},#{subjectId},#{status},#{mustChange},#{ctx.userId},#{ctx.userId})\n""");\n                sql.update("""\ninsert into iam_account_security_t(tid,\n                principal_kind, principal_id, password_changed_time)\nvalues(#{securityId},\'OPERATOR\',#{id},utc_timestamp(6))\n""");\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                operatorName(id,old.subject_id,name,r.subjectVersion,ctx.userId,false);\n                sql.update("""\nupdate iam_operator_t\nset status=#{status},version=version+1,\n        updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{id}\n""");\n                if(old.status!=status) {\n                    sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n                }\n            }\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'operators:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/05.解除平台账号锁定.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ff41f380ea624c2ea333eb1e991c8856',NULL,NULL,'{\n  "properties": {},\n  "id": "64e411148c13506897632e1f5bbe2c15",\n  "name": "06.平台账号",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/operators",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/06.平台账号/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('be60554785384db3992339b1331d196d',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4066ea85777a497287b4b155f17c534b',NULL,'api','{\n  "properties": {},\n  "id": "0f9b0c2c3dc4513686c90ec2bfedf5e6",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "01.查询平台角色列表",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的平台角色，应用权限及身份域过滤后返回可展示字段；不发生写入。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询平台角色列表\n// 路由：GET /idaas/platform-roles/list\n// 业务说明：读取符合请求筛选条件的平台角色，应用权限及身份域过滤后返回可展示字段；不发生写入。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n    var payload = param||{};\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    if(operation==\'list\') {\n        return sql.select("""\nselect *,tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and is_del=0\norder by code\n""").map(role=>{\n            role.resourceIds=sql.select("""\nselect resource_id\nfrom iam_role_resource_rela_t\nwhere role_id=#{role.id}\n""").map(x=>x.resource_id);\n            return role;\n        });\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/01.查询平台角色列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('398dfee984f14f7996c538a42837a8cd',NULL,'api','{\n  "properties": {},\n  "id": "8ee3dabd4da15e23be8e7d24c8ccdf5b",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "02.保存平台角色",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新平台角色及必要关联记录，写入审计并返回保存结果。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存平台角色\n// 路由：POST /idaas/platform-roles/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新平台角色及必要关联记录，写入审计并返回保存结果。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/02.保存平台角色.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1001a723471b403590882dd7037ec8d3',NULL,'api','{\n  "properties": {},\n  "id": "91e2746dfab0586d9ed0dad2a647f3c3",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "03.归档平台角色",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载平台角色并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档平台角色\n// 路由：POST /idaas/platform-roles/remove\n// 业务说明：按标识加载平台角色并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。核验平台功能权限与对象范围；角色资源和分配范围不得超过当前操作人的可管理权限。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n    var payload = body||{};\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/03.归档平台角色.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cea95a2e4cd349ba924441d847979e0b',NULL,'api','{\n  "properties": {},\n  "id": "06d8db502b255e098024ef3a7ef595f1",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "04.查询平台功能资源",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/resources",\n  "description": "读取平台角色可配置的功能资源树，按当前操作人可授予范围过滤，供角色授权界面使用。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.查询平台功能资源\n// 路由：GET /idaas/platform-roles/resources\n// 业务说明：读取平台角色可配置的功能资源树，按当前操作人可授予范围过滤，供角色授权界面使用。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'resources\';\n    var payload = param||{};\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    if(operation==\'resources\') {\n        return sql.select("""\nselect tid as id,code,name,resource_type,path\nfrom iam_resource_t\nwhere app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\norder by code\n""");\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/04.查询平台功能资源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d46af7e9162543d1bbf6cd320a69f916',NULL,'api','{\n  "properties": {},\n  "id": "703537903bf65870bad007eea877180b",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "05.查询平台角色分配",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/assignments",\n  "description": "读取平台角色与操作账号的分配及应用对象范围，按当前操作人的管理权限过滤；只读。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.查询平台角色分配\n// 路由：GET /idaas/platform-roles/assignments\n// 业务说明：读取平台角色与操作账号的分配及应用对象范围，按当前操作人的管理权限过滤；只读。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\nimport request;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var values=request.getValues(\'operatorId\');\n    if(values==null || values.size()!=1) {\n        exit 400,\'请提供平台操作账号标识\';\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'assignments\';\n    var payload = {\n        operatorId:values[0]\n    };\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    if(operation==\'assignments\') {\n        guard(\'operators:read\',null,\'workforce\');\n        var operatorId=p.operatorId;\n        if(operatorId==null || sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n""")==null) {\n            exit 404,\'平台操作账号不存在\';\n        }\n        return sql.select("""\nselect tid as id,operator_id,role_id,status,version,\n       date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\') as valid_from, date_format(valid_until,\n        \'%Y-%m-%dT%H:%i:%sZ\') as valid_until\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and status=\'ACTIVE\'\n""").map(a=>{\n            a.scopes=sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            return a;\n        });\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/05.查询平台角色分配.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4d4b36cc5cf74b62a433a484427c4b8a',NULL,'api','{\n  "properties": {},\n  "id": "0ebea9ab19a951019a530accee61f353",\n  "script": null,\n  "groupId": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "06.分配平台角色与范围",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/assign",\n  "description": "逐项核验被授予的功能及对象范围不超过当前操作人权限，更新平台角色分配并记录审计。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：06.分配平台角色与范围\n// 路由：POST /idaas/platform-roles/assign\n// 业务说明：逐项核验被授予的功能及对象范围不超过当前操作人权限，更新平台角色分配并记录审计。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport cn.hutool.core.util.IdUtil;\nimport java.time.Instant;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'assign\';\n    var payload = body||{};\n\n    // 平台内部角色与显式管理范围；所有转授逐项验证功能及范围上限。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var internal=\'idaas-platform-internal\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\' || operation==\'resources\' || operation==\'assignments\'?\'platform-roles:read\':operation==\'assign\'?\'operators:grant\':\'platform-roles:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'platform-roles:\'+operation,p,()=>{\n        var id=r.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        if(operation==\'assign\') {\n            var operatorId=p.operatorId;\n            var target=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{operatorId}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(target==null) {\n                exit 400,\'目标平台账号不存在或已停用\';\n            }\n            if(target.version!=p.version) {\n                exit 409,\'平台账号已被修改，请刷新\';\n            }\n            var assignments=p.assignments||[];\n            if(assignments.size()>30) {\n                exit 400,\'角色分配数量过多\';\n            }\n            var verified=[];\n            var roleIds=[];\n            for(a in assignments) {\n                if(roleIds.contains(a.roleId)) {\n                    exit 400,\'同一角色不能重复分配\';\n                }\n                roleIds.add(a.roleId);\n                var role=sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{a.roleId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(role==null) {\n                    exit 400,\'所选角色不是有效的平台角色\';\n                }\n                var codes=sql.select("""\nselect r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\nwhere rr.role_id=#{a.roleId}\n""").map(x=>x.code);\n                var scopes=a.scopes||[];\n                if(scopes.size()==0 || scopes.size()>30) {\n                    exit 400,\'请提供明确管理范围\';\n                }\n                for(s in scopes) {\n                    if(![\'workforce\',\'public\'].contains(s.identityDomain) || ![\'ALL\',\'APPLICATION\',\'ORG\'].contains(s.scopeKind)) {\n                        exit 400,\'身份域或范围类型不正确\';\n                    }\n                    if(s.scopeKind==\'ALL\' && s.appId!=null) {\n                        exit 400,\'全局范围不能同时指定应用\';\n                    }\n                    if(s.scopeKind==\'APPLICATION\' && sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{s.appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'范围应用不存在\';\n                    }\n                    if(s.scopeKind!=\'ORG\' && s.orgId!=null) {\n                        exit 400,\'非机构范围不能指定机构\';\n                    }\n                    if(s.scopeKind==\'ORG\' && (s.appId!=null || sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{s.orgId}\n    and identity_domain=#{s.identityDomain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null)) {\n                        exit 400,\'机构范围须为同域有效机构，不能借此修改应用配置\';\n                    }\n                    for(permission in codes) {\n                        if(s.scopeKind==\'ORG\') {\n                            var boundary=directoryScope(permission,s.identityDomain);\n                            if(!boundary.all && !boundary.orgIds.contains(s.orgId)) {\n                                exit 403,\'机构范围超出可转授权上限\';\n                            }\n                            if(s.includeChildren==true && !boundary.all) {\n                                var root=sql.selectOne("""\nselect path\nfrom iam_org_t\nwhere tid=#{s.orgId}\n""");\n                                var nodes=sql.select("""\nselect tid as id\nfrom iam_org_t\nwhere path like concat(#{root.path}, \'%\')\n    and is_del=0\n""");\n                                if(nodes.filter(n=>!boundary.orgIds.contains(n.id)).size()>0) {\n                                    exit 403,\'下级范围超出可转授权上限\';\n                                }\n                            }\n                        }\n                        else {\n                            guard(permission,s.scopeKind==\'ALL\'?null:s.appId,s.identityDomain);\n                        }\n                    }\n                }\n                // API dates are UTC ISO-8601. Bind canonical strings to avoid JDBC/session timezone conversion.\n                var start=null;\n                var end=null;\n                try {\n                    if(a.validFrom!=null && a.validFrom!=\'\') {\n                        start=Instant.parse(a.validFrom).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                    if(a.validUntil!=null && a.validUntil!=\'\') {\n                        end=Instant.parse(a.validUntil).toString().substring(0,19).replace(\'T\',\' \');\n                    }\n                }\n                catch(e) {\n                    exit 400,\'授权时间须为有效UTC时间\';\n                }\n                if(end!=null && sql.selectOne("""\nselect case\n           when #{end}<=coalesce(#{start},\n        utc_timestamp(6))\n                or #{end}<=utc_timestamp(6) then 1 else 0\n       end as invalid\n""").invalid==1) {\n                    exit 400,\'到期时间须晚于生效时间及当前时间\';\n                }\n                verified.add({\n                    roleId:a.roleId,scopes:a.scopes,validFrom:start,validUntil:end\n                });\n            }\n            // 校验完全部对象后才替换，不允许部分成功。\n            var old=sql.select("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n""");\n            for(a in old) {\n                sql.update("""\ndelete\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""");\n            }\n            sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere operator_id=#{operatorId}\n""");\n            for(a in verified) {\n                var present=sql.selectOne("""\nselect tid as id\nfrom iam_operator_role_rela_t\nwhere operator_id=#{operatorId}\n    and role_id=#{a.roleId}\n""");\n                var assignmentId=present==null?IdUtil.fastSimpleUUID():present.id;\n                if(present==null) {\n                    sql.update("""\ninsert into iam_operator_role_rela_t(tid,\n                operator_id, role_id, status, valid_from, valid_until)\nvalues(#{assignmentId},#{operatorId},#{a.roleId},\'ACTIVE\',coalesce(#{a.validFrom},utc_timestamp(6)),#{a.validUntil})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_operator_role_rela_t\nset status=\'ACTIVE\',valid_from=coalesce(#{a.validFrom}, utc_timestamp(6)),valid_until=#{a.validUntil},\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{assignmentId}\n""");\n                }\n                for(s in a.scopes) {\n                    var scopeId=IdUtil.fastSimpleUUID();\n                    var appId=s.scopeKind==\'APPLICATION\'?s.appId:null;\n                    var orgId=s.scopeKind==\'ORG\'?s.orgId:null;\n                    var children=s.includeChildren==true?1:0;\n                    sql.update("""\ninsert into iam_operator_scope_t(tid,\n                assignment_id, identity_domain, scope_kind, app_id, org_id, include_children)\nvalues(#{scopeId},#{assignmentId},#{s.identityDomain},#{s.scopeKind},#{appId},#{orgId},#{children})\n""");\n                }\n            }\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{operatorId}\n""");\n            id=operatorId;\n        }\n        else {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_role_t\nwhere tid=#{id}\n    and app_id=#{internal}\n    and is_del=0\n    for update\n""");\n            if(old==null && p.creating!=true) {\n                exit 404,\'平台角色不存在\';\n            }\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=r.version) {\n                exit 409,\'角色已被修改，请刷新\';\n            }\n            var references=old==null?[]:sql.select("""\nselect a.tid as id\nfrom iam_operator_role_rela_t a\nwhere role_id=#{id}\n    and status=\'ACTIVE\'\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n            if(operation==\'remove\') {\n                if(references.size()>0) {\n                    exit 409,\'角色仍被账号使用，请先处理分配\';\n                }\n                sql.update("""\nupdate iam_role_t\nset is_del=1,status=\'DISABLED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,99}\')) {\n                    exit 400,\'平台角色名称或编码不正确\';\n                }\n                if(old!=null && code!=old.code) {\n                    exit 400,\'角色编码保持稳定\';\n                }\n                var resourceIds=r.resourceIds||[];\n                var verified=[];\n                for(resourceId in resourceIds) {\n                    var resource=sql.selectOne("""\nselect code\nfrom iam_resource_t\nwhere tid=#{resourceId}\n    and app_id=#{internal}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                    if(resource==null || !ctx.permissions.contains(resource.code)) {\n                        exit 403,\'不能授予超出自身权限的资源\';\n                    }\n                    for(a in references) {\n                        for(s in sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id=#{a.id}\n""")) {\n                            guard(resource.code,s.scope_kind==\'ALL\'?null:s.app_id,s.identity_domain);\n                        }\n                    }\n                    if(!verified.contains(resourceId)) {\n                        verified.add(resourceId);\n                    }\n                }\n                var status=r.status==\'DISABLED\' || r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n                var description=r.description||\'\';\n                if(description.length()>1000) {\n                    exit 400,\'说明过长\';\n                }\n                if(old==null) {\n                    id=IdUtil.fastSimpleUUID();\n                    if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere app_id=#{internal}\n    and code=#{code}\n""")!=null) {\n                        exit 409,\'角色编码已使用\';\n                    }\n                    sql.update("""\ninsert into iam_role_t(tid, app_id, code, name, identity_domain, status, description)\nvalues(#{id},#{internal},#{code},#{name},\'workforce\',#{status},#{description})\n""");\n                }\n                else {\n                    sql.update("""\nupdate iam_role_t\nset name=#{name},status=#{status},description=#{description},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n                }\n                sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n                for(resourceId in verified) {\n                    var linkId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{linkId},#{id},#{resourceId},#{internal})\n""");\n                }\n            }\n        }\n        var managers=sql.selectOne("""\nselect count(distinct o.tid) as total\nfrom iam_operator_t o\njoin iam_operator_role_rela_t a on a.operator_id=o.tid\nand a.status=\'ACTIVE\'\nand a.valid_from<=utc_timestamp(6)\nand (a.valid_until is null\n     or a.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=a.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_role_resource_rela_t rr on rr.role_id=r.tid\njoin iam_resource_t res on res.tid=rr.resource_id\njoin iam_operator_scope_t s on s.assignment_id=a.tid\nand s.scope_kind=\'ALL\'\nand s.identity_domain=\'workforce\'\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and res.code=\'operators:grant\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""");\n        if(managers.total==0) {\n            exit 409,\'必须保留一个有效的全局权限管理入口\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'platform-roles:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/06.分配平台角色与范围.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3f8bb2960a474d11aeebe0c573ab6f0c',NULL,NULL,'{\n  "properties": {},\n  "id": "1e0dee785fc65df8a070fb6a38c924ad",\n  "name": "07.平台角色",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/platform-roles",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/07.平台角色/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ce5c0c5de9ac40cda9446fb663535111',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/08.平台配置/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9f6df16ef5ed45b891276a63f4fb0e74',NULL,'api','{\n  "properties": {},\n  "id": "e5ba32a9e302572fa4ff6a7cddb4fb23",\n  "script": null,\n  "groupId": "b131d8f0696755519b08adfc5918a7c7",\n  "name": "01.读取平台策略",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "按类别读取控制库已保存的平台安全与业务策略，过滤敏感配置值并返回可编辑项；不读取租户系统配置。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.读取平台策略\n// 路由：GET /idaas/settings/list\n// 业务说明：按类别读取控制库已保存的平台安全与业务策略，过滤敏感配置值并返回可编辑项；不读取租户系统配置。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport identityApi;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'read\';\n    var payload = param||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'read\'?\'settings:read\':\'settings:write\',null,\'workforce\');\n    if(operation==\'read\') {\n        var rows=sql.select("""\nselect tid as id,category,config_key,value_json,version\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n    and ((category=\'SECURITY\'\n          and config_key=\'password\')\n         or (category=\'BRANDING\'\n             and config_key=\'brand\')\n         or (category=\'API_ACCESS\'\n             and config_key=\'access\')\n         or (category=\'SSO\'\n             and config_key=\'session\'))\n""").map(r=>{\n            r.value=JSONUtil.parseObj(r.value_json);\n            r.value_json=null;\n            return r;\n        });\n        if(rows.filter(r=>r.category==\'SSO\').size()==0) {\n            rows.add({\n                id:\'global-sso-default\',category:\'SSO\',config_key:\'session\',version:null,value:{\n                    accessTtl:600,refreshTtl:86400,idleMinutes:30,allowConcurrent:true\n                }\n            });\n        }\n        return rows;\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'settings:save\',p,()=>{\n        var category=p.category;\n        var key=p.configKey;\n        var values=p.values||{};\n        if(![\'SECURITY\',\'BRANDING\',\'API_ACCESS\',\'SSO\'].contains(category) || (category==\'SECURITY\' && key!=\'password\') || (category==\'BRANDING\' && key!=\'brand\') || (category==\'API_ACCESS\' && key!=\'access\') || (category==\'SSO\' && key!=\'session\')) {\n            exit 400,\'此策略尚未开通\';\n        }\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=#{category}\n    and config_key=#{key}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old==null && p.version!=null || old!=null && old.version!=p.version) {\n            exit 409,\'配置已被修改，请刷新\';\n        }\n        var allowed=category==\'SECURITY\'?[\'minLength\',\'lockThreshold\',\'lockMinutes\',\'forceChange\',\'passwordBlacklist\',\'mfaRequired\']:category==\'API_ACCESS\'?[\'apiWhitelist\',\'ipBlacklist\',\'apiRateLimit\']:category==\'SSO\'?[\'accessTtl\',\'refreshTtl\',\'idleMinutes\',\'allowConcurrent\']:[\'title\',\'subtitle\',\'logoUrl\'];\n        for(k in values.keySet()) {\n            if(!allowed.contains(k)) {\n                exit 400,\'配置包含尚未开通的字段\';\n            }\n        }\n        if(category==\'SECURITY\') {\n            if(!(values.minLength instanceof Number) || !(values.lockThreshold instanceof Number) || !(values.lockMinutes instanceof Number)\n            || values.minLength.doubleValue()!=values.minLength.intValue() || values.lockThreshold.doubleValue()!=values.lockThreshold.intValue()\n            || values.lockMinutes.doubleValue()!=values.lockMinutes.intValue()) {\n                exit 400,\'安全策略数值须填写完整整数\';\n            }\n            if(values.minLength<8 || values.minLength>64 || values.lockThreshold<3 || values.lockThreshold>20 || values.lockMinutes<5 || values.lockMinutes>1440\n            || values.passwordBlacklist==null || values.passwordBlacklist.length()>10000 || ![true,false].contains(values.forceChange)) {\n                exit 400,\'安全策略范围不正确\';\n            }\n            if(values.mfaRequired==true && sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t o\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and not exists\n        (select 1\n         from iam_credential_t c\n         where c.owner_kind=\'OPERATOR\'\n             and c.owner_id=o.tid\n             and c.credential_type=\'TOTP\'\n             and c.status=\'ACTIVE\')\n""").n>0) {\n                exit 409,\'请先为全部启用的平台操作账号绑定动态口令，再开启强制策略\';\n            }\n        }\n        else if(category==\'API_ACCESS\') {\n            if(!(values.apiRateLimit instanceof Number) || values.apiRateLimit.doubleValue()!=values.apiRateLimit.intValue() || values.apiRateLimit<1 || values.apiRateLimit>100000 || (values.apiWhitelist||\'\').length()>4000 || (values.ipBlacklist||\'\').length()>4000) {\n                exit 400,\'接口配额或来源规则不正确\';\n            }\n            for(list in [values.apiWhitelist||\'\',values.ipBlacklist||\'\']) {\n                for(rule in list.split(\'\\n\')) {\n                    if(rule.trim()!=\'\') {\n                        try {\n                            identityApi.matchesAddress(rule.trim(),\'127.0.0.1\');\n                        }\n                        catch(e) {\n                            exit 400,\'接口来源须使用有效IP或CIDR\';\n                        }\n                    }\n                }\n            }\n        }\n        else if(category==\'SSO\') {\n            for(k in [\'accessTtl\',\'refreshTtl\',\'idleMinutes\']) {\n                var value=values.get(k);\n                if(!(value instanceof Number) || value.doubleValue()!=value.intValue()) {\n                    exit 400,\'会话有效期须为完整整数\';\n                }\n            }\n            if(values.accessTtl<60 || values.accessTtl>3600 || values.refreshTtl<values.accessTtl || values.refreshTtl>604800 || values.idleMinutes<5 || values.idleMinutes>30 || ![true,false].contains(values.allowConcurrent)) {\n                exit 400,\'会话策略范围不正确\';\n            }\n        }\n        else if(values.title==null || values.title.trim()==\'\' || values.title.length()>30 || (values.subtitle||\'\').length()>100\n        || ((values.logoUrl||\'\')!=\'\' && !values.logoUrl.matches(\'https://[^\\\\s]+\'))) {\n            exit 400,\'品牌配置不正确\';\n        }\n        var encoded=JSONUtil.toJsonStr(values);\n        if(old==null) {\n            var id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status, created_by)\nvalues(#{id},\'GLOBAL\',\'global\',#{category},#{key},#{encoded},\'ACTIVE\',#{ctx.userId})\n""");\n            old={\n                id:id\n            };\n        }\n        else {\n            sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1,updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{old.id}\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'settings:save\',old.id,null,{\n            category:category,key:key\n        });\n        return {\n            id:old.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/08.平台配置/01.读取平台策略.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('604c7dd98ab546f1b186bd819ec35641',NULL,'api','{\n  "properties": {},\n  "id": "b6989040ccbe588abe6c9169ad23ee82",\n  "script": null,\n  "groupId": "b131d8f0696755519b08adfc5918a7c7",\n  "name": "02.保存平台策略",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验配置类别、允许字段和版本后写入控制库平台策略，记录操作者及审计；不自动覆盖租户配置。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存平台策略\n// 路由：POST /idaas/settings/save\n// 业务说明：校验配置类别、允许字段和版本后写入控制库平台策略，记录操作者及审计；不自动覆盖租户配置。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport identityApi;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'read\'?\'settings:read\':\'settings:write\',null,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'settings:save\',p,()=>{\n        var category=p.category;\n        var key=p.configKey;\n        var values=p.values||{};\n        if(![\'SECURITY\',\'BRANDING\',\'API_ACCESS\',\'SSO\'].contains(category) || (category==\'SECURITY\' && key!=\'password\') || (category==\'BRANDING\' && key!=\'brand\') || (category==\'API_ACCESS\' && key!=\'access\') || (category==\'SSO\' && key!=\'session\')) {\n            exit 400,\'此策略尚未开通\';\n        }\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=#{category}\n    and config_key=#{key}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old==null && p.version!=null || old!=null && old.version!=p.version) {\n            exit 409,\'配置已被修改，请刷新\';\n        }\n        var allowed=category==\'SECURITY\'?[\'minLength\',\'lockThreshold\',\'lockMinutes\',\'forceChange\',\'passwordBlacklist\',\'mfaRequired\']:category==\'API_ACCESS\'?[\'apiWhitelist\',\'ipBlacklist\',\'apiRateLimit\']:category==\'SSO\'?[\'accessTtl\',\'refreshTtl\',\'idleMinutes\',\'allowConcurrent\']:[\'title\',\'subtitle\',\'logoUrl\'];\n        for(k in values.keySet()) {\n            if(!allowed.contains(k)) {\n                exit 400,\'配置包含尚未开通的字段\';\n            }\n        }\n        if(category==\'SECURITY\') {\n            if(!(values.minLength instanceof Number) || !(values.lockThreshold instanceof Number) || !(values.lockMinutes instanceof Number)\n            || values.minLength.doubleValue()!=values.minLength.intValue() || values.lockThreshold.doubleValue()!=values.lockThreshold.intValue()\n            || values.lockMinutes.doubleValue()!=values.lockMinutes.intValue()) {\n                exit 400,\'安全策略数值须填写完整整数\';\n            }\n            if(values.minLength<8 || values.minLength>64 || values.lockThreshold<3 || values.lockThreshold>20 || values.lockMinutes<5 || values.lockMinutes>1440\n            || values.passwordBlacklist==null || values.passwordBlacklist.length()>10000 || ![true,false].contains(values.forceChange)) {\n                exit 400,\'安全策略范围不正确\';\n            }\n            if(values.mfaRequired==true && sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t o\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and not exists\n        (select 1\n         from iam_credential_t c\n         where c.owner_kind=\'OPERATOR\'\n             and c.owner_id=o.tid\n             and c.credential_type=\'TOTP\'\n             and c.status=\'ACTIVE\')\n""").n>0) {\n                exit 409,\'请先为全部启用的平台操作账号绑定动态口令，再开启强制策略\';\n            }\n        }\n        else if(category==\'API_ACCESS\') {\n            if(!(values.apiRateLimit instanceof Number) || values.apiRateLimit.doubleValue()!=values.apiRateLimit.intValue() || values.apiRateLimit<1 || values.apiRateLimit>100000 || (values.apiWhitelist||\'\').length()>4000 || (values.ipBlacklist||\'\').length()>4000) {\n                exit 400,\'接口配额或来源规则不正确\';\n            }\n            for(list in [values.apiWhitelist||\'\',values.ipBlacklist||\'\']) {\n                for(rule in list.split(\'\\n\')) {\n                    if(rule.trim()!=\'\') {\n                        try {\n                            identityApi.matchesAddress(rule.trim(),\'127.0.0.1\');\n                        }\n                        catch(e) {\n                            exit 400,\'接口来源须使用有效IP或CIDR\';\n                        }\n                    }\n                }\n            }\n        }\n        else if(category==\'SSO\') {\n            for(k in [\'accessTtl\',\'refreshTtl\',\'idleMinutes\']) {\n                var value=values.get(k);\n                if(!(value instanceof Number) || value.doubleValue()!=value.intValue()) {\n                    exit 400,\'会话有效期须为完整整数\';\n                }\n            }\n            if(values.accessTtl<60 || values.accessTtl>3600 || values.refreshTtl<values.accessTtl || values.refreshTtl>604800 || values.idleMinutes<5 || values.idleMinutes>30 || ![true,false].contains(values.allowConcurrent)) {\n                exit 400,\'会话策略范围不正确\';\n            }\n        }\n        else if(values.title==null || values.title.trim()==\'\' || values.title.length()>30 || (values.subtitle||\'\').length()>100\n        || ((values.logoUrl||\'\')!=\'\' && !values.logoUrl.matches(\'https://[^\\\\s]+\'))) {\n            exit 400,\'品牌配置不正确\';\n        }\n        var encoded=JSONUtil.toJsonStr(values);\n        if(old==null) {\n            var id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status, created_by)\nvalues(#{id},\'GLOBAL\',\'global\',#{category},#{key},#{encoded},\'ACTIVE\',#{ctx.userId})\n""");\n            old={\n                id:id\n            };\n        }\n        else {\n            sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1,updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{old.id}\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'settings:save\',old.id,null,{\n            category:category,key:key\n        });\n        return {\n            id:old.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/08.平台配置/02.保存平台策略.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a00d5d2ff9cf4f0f9c2f8a9c793339b3',NULL,NULL,'{\n  "properties": {},\n  "id": "b131d8f0696755519b08adfc5918a7c7",\n  "name": "08.平台配置",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/settings",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/08.平台配置/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e758ed3401194452a89fa0af819ac789',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/09.个人中心/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ab7d5fe5332e43fca75145df2540dbf2',NULL,'api','{\n  "properties": {},\n  "id": "58695a5f7a255701bfa51ae44c00b26e",\n  "script": null,\n  "groupId": "1813da709f3a559fa44c0f77be8cb11a",\n  "name": "01.修改本人资料",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "以当前平台会话确定账号，仅更新允许本人修改的资料字段，防止越权修改角色或身份域。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.修改本人资料\n// 路由：POST /idaas/profile/save\n// 业务说明：以当前平台会话确定账号，仅更新允许本人修改的资料字段，防止越权修改角色或身份域。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n    var payload = body||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var ctx=context();\n    var id=ctx.userId;\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'profile:\'+operation,p,()=>{\n        var operator=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n        if(operator.version!=p.version) {\n            exit 409,\'个人资料已被修改，请刷新\';\n        }\n        if(operation==\'password\') {\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            // 核对凭据时兼容已登记的摘要算法，失败只更新安全状态而不创建会话。\n            if(current==null || !iamSecurity.verify(p.oldPassword,current.algorithm,current.secret_hash)) {\n                exit 400,\'当前密码不正确\';\n            }\n            passwordPolicy(p.password);\n            if(p.oldPassword==p.password) {\n                exit 400,\'新密码需要与当前密码不同\';\n            }\n            var encoded=iamSecurity.hash(p.password);\n            var credentialId=IdUtil.fastSimpleUUID();\n            var revision=current.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere tid=#{current.id}\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,password_changed_time=utc_timestamp(6),failed_count=0,locked_until=null\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=0,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var name=(p.name||\'\').trim();\n            if(name==\'\' || name.length()>100) {\n                exit 400,\'显示名称不正确\';\n            }\n            operatorName(id,operator.subject_id,name,p.subjectVersion,id,true);\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'profile:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id,relogin:operation==\'password\'\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/09.个人中心/01.修改本人资料.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9b1a2cd222d844ff8770de50e4256ba4',NULL,'api','{\n  "properties": {},\n  "id": "b053321931715e798c0c032e180ca907",\n  "script": null,\n  "groupId": "1813da709f3a559fa44c0f77be8cb11a",\n  "name": "02.修改本人密码",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/password",\n  "description": "核验当前会话、原密码和新密码策略，更新平台账号安全凭据并使旧会话失效。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.修改本人密码\n// 路由：POST /idaas/profile/password\n// 业务说明：核验当前会话、原密码和新密码策略，更新平台账号安全凭据并使旧会话失效。\nimport db;\nimport platformSession;\nimport iamSecurity;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport \'@/idaas/operator-name\' as operatorName;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 请求参数与本接口业务处理。\n    var operation = \'password\';\n    var payload = body||{};\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var ctx=context();\n    var id=ctx.userId;\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'profile:\'+operation,p,()=>{\n        var operator=sql.selectOne("""\nselect *,tid as id\nfrom iam_operator_t\nwhere tid=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    for update\n""");\n        if(operator.version!=p.version) {\n            exit 409,\'个人资料已被修改，请刷新\';\n        }\n        if(operation==\'password\') {\n            var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'OPERATOR\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            // 核对凭据时兼容已登记的摘要算法，失败只更新安全状态而不创建会话。\n            if(current==null || !iamSecurity.verify(p.oldPassword,current.algorithm,current.secret_hash)) {\n                exit 400,\'当前密码不正确\';\n            }\n            passwordPolicy(p.password);\n            if(p.oldPassword==p.password) {\n                exit 400,\'新密码需要与当前密码不同\';\n            }\n            var encoded=iamSecurity.hash(p.password);\n            var credentialId=IdUtil.fastSimpleUUID();\n            var revision=current.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',updated_time=utc_timestamp(6)\nwhere tid=#{current.id}\n""");\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{credentialId},\'OPERATOR\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,password_changed_time=utc_timestamp(6),failed_count=0,locked_until=null\nwhere principal_kind=\'OPERATOR\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_operator_t\nset must_change_password=0,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var name=(p.name||\'\').trim();\n            if(name==\'\' || name.length()>100) {\n                exit 400,\'显示名称不正确\';\n            }\n            operatorName(id,operator.subject_id,name,p.subjectVersion,id,true);\n            sql.update("""\nupdate iam_operator_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            exit 400,\'操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'profile:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id,relogin:operation==\'password\'\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/09.个人中心/02.修改本人密码.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('902365dfa82442b1a9288f59848ecdc3',NULL,NULL,'{\n  "properties": {},\n  "id": "1813da709f3a559fa44c0f77be8cb11a",\n  "name": "09.个人中心",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/profile",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/09.个人中心/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7151ec43f04348e6abce0947cb7ab6f0',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/10.审计查询/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('857f1867fdb64756aa1f2584c325fd6d',NULL,'api','{\n  "properties": {},\n  "id": "442547f994c85528842eaab529f84850",\n  "script": null,\n  "groupId": "a2d73d152a83535d9993586812fb257f",\n  "name": "01.分页查询审计记录",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "按身份域、应用、事件和时间范围分页查询控制库审计记录，校验可见范围并对敏感字段脱敏。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.分页查询审计记录\n// 路由：GET /idaas/audit/list\n// 业务说明：按身份域、应用、事件和时间范围分页查询控制库审计记录，校验可见范围并对敏感字段脱敏。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport db;\nimport request;\nimport java.lang.Long;\nimport \'@/idaas/guard\' as guard;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=guard(\'audit:read\',null,\'workforce\');\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var query=(name,fallback)=>{\n        var values=request.getValues(name);\n        return values==null || values.size()==0?fallback:values[0];\n    };\n    var pageText=query(\'page\',\'1\');\n    var sizeText=query(\'size\',\'30\');\n    if(!pageText.matches(\'[0-9]{1,5}\') || !sizeText.matches(\'[0-9]{1,3}\')) {\n        exit 400,\'分页参数不正确\';\n    }\n    var page=Long.parseLong(pageText);\n    var size=Long.parseLong(sizeText);\n    if(page<1 || page>10000 || size<1 || size>200) {\n        exit 400,\'分页参数不正确\';\n    }\n    var offset=(page-1)*size;\n    var type=query(\'type\',null);\n    if(type!=null && ![\'AUTH\',\'API\',\'OPERATION\',\'MIGRATION\'].contains(type)) {\n        exit 400,\'审计类型不正确\';\n    }\n    var search=query(\'q\',\'\');\n    var result=query(\'result\',null);\n    if(search.length()>100 || (result!=null && ![\'SUCCESS\',\'FAILED\',\'DENIED\'].contains(result))) {\n        exit 400,\'审计查询条件不正确\';\n    }\n    var count=sql.selectOne("""\nselect count(*) total\nfrom iam_audit_event_t a\nleft join iam_operator_profile_v o on o.tid=a.actor_id\nwhere (#{type} is null\n       or a.event_type=#{type})\n    and (#{result} is null\n         or a.result=#{result})\n    and (#{search}=\'\'\n         or locate(lower(#{search}),\n\n                lower(concat_ws(\' \',\n        a.action, a.actor_id, o.username, o.display_name, a.object_id, a.trace_id, a.ip,\n        a.request_path)))>0)\n""");\n    var rows=sql.select("""\nselect a.tid as id,a.event_type,a.identity_domain,a.actor_kind,a.actor_id,o.display_name as actor_name,\n       o.username as actor_username, a.app_id,a.action,a.object_type,a.object_id,a.result,a.reason_code,a.trace_id,a.ip,\n       a.request_path,a.http_method,a.http_status,a.duration_ms,a.snapshot_json,\n       date_format(a.event_time, \'%Y-%m-%dT%H:%i:%sZ\') as event_time\nfrom iam_audit_event_t a\nleft join iam_operator_profile_v o on o.tid=a.actor_id\nwhere (#{type} is null\n       or a.event_type=#{type})\n    and (#{result} is null\n         or a.result=#{result})\n    and (#{search}=\'\'\n         or locate(lower(#{search}),\n\n                lower(concat_ws(\' \',\n        a.action, a.actor_id, o.username, o.display_name, a.object_id, a.trace_id, a.ip,\n        a.request_path)))>0)\norder by a.event_time desc,a.tid desc\nlimit #{size}\noffset #{offset}\n""");\n    return {\n        list:rows,total:count.total,page:page,size:size\n    };\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/10.审计查询/01.分页查询审计记录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b5d54c2cb8b14972aabf741ef5de5124',NULL,NULL,'{\n  "properties": {},\n  "id": "a2d73d152a83535d9993586812fb257f",\n  "name": "10.审计查询",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/audit",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/10.审计查询/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('589071a470ab47f89cd75f3f1a5e8a3a',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e1cc0858d35f469ab8919e5b61a412d3',NULL,'api','{\n  "properties": {},\n  "id": "a933e818d7bf53468de98461fe26d5f9",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "01.查询中央人员列表",\n  "createTime": 1790612165860,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的中央人员，应用权限及身份域过滤后返回可展示字段；不发生写入。处理控制库的中央人员资料，保持人员资料与租户本地账号隔离；仅显式下发时才影响租户。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：查询中央人员列表\n// 路由：GET /idaas/users/list\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory\' as directory;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'status\',\'orgId\',\'includeChildren\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    return directory(\'subjects\',\'list\',payload);\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/01.查询中央人员列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('61bb3b703754417d9a4059dc19c637b7',NULL,'api','{\n  "properties": {},\n  "id": "8dedf6d666c55613a4cf9c1b46001b15",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "02.保存中央人员",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新中央人员及必要关联记录，写入审计并返回保存结果。处理控制库的中央人员资料，保持人员资料与租户本地账号隔离；仅显式下发时才影响租户。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存中央人员\n// 路由：POST /idaas/users/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新中央人员及必要关联记录，写入审计并返回保存结果。处理控制库的中央人员资料，保持人员资料与租户本地账号隔离；仅显式下发时才影响租户。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'subjects\';\n    var operation = \'save\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/02.保存中央人员.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5a537c02af344ae9a51ef8b632b25449',NULL,'api','{\n  "properties": {},\n  "id": "e064863bbc0d537d909fbba98c60b2e0",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "03.归档中央人员",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载中央人员并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央人员资料，保持人员资料与租户本地账号隔离；仅显式下发时才影响租户。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档中央人员\n// 路由：POST /idaas/users/remove\n// 业务说明：按标识加载中央人员并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央人员资料，保持人员资料与租户本地账号隔离；仅显式下发时才影响租户。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'subjects\';\n    var operation = \'remove\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/03.归档中央人员.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8d16429080e44e21a6283ca7f1816f84',NULL,'api','{\n  "properties": {},\n  "id": "dc4619ca6349542791baee8cb1cb9f25",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "04.人员目录操作占位查询",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/operations",\n  "description": "当前仅核验平台会话具有中央人员写入权限，然后返回空列表；尚未读取或生成操作记录，此接口保留旧调用兼容。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.人员目录操作占位查询\n// 路由：GET /idaas/users/operations\n// 业务说明：当前仅核验平台会话具有中央人员写入权限，然后返回空列表；尚未读取或生成操作记录，此接口保留旧调用兼容。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory-scope\' as directoryScope;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    directoryScope(\'users:write\',\'workforce\');\n    return [];\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/04.人员目录操作占位查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('42ac64480d1f474b83f139d8d8c8a121',NULL,'api','{\n  "properties": {},\n  "id": "ce1b7dafa9405755b263b849c2c9dc96",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "05.人员目录重试待开通",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/retry",\n  "description": "当前直接返回业务错误 503，说明旧人员目录重试流程尚未开通；不读取或修改人员资料，也不会后台执行任务。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.人员目录重试待开通\n// 路由：POST /idaas/users/retry\n// 业务说明：当前直接返回业务错误 503，说明旧人员目录重试流程尚未开通；不读取或修改人员资料，也不会后台执行任务。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    exit 503,\'中央目录写入将在第二阶段开通\';\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/05.人员目录重试待开通.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ec4feceafbe94977943f17ecde63d723',NULL,'api','{\n  "properties": {},\n  "id": "062a1e8f5b825797baf08ddc8654daa8",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "06.批量停用中央人员",\n  "createTime": 1791193400395,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/batch-disable",\n  "description": "单次最多停用 100 人；在同一事务中逐 ID 校验身份域、版本及机构范围，批量写入人员与应用期望状态。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：批量停用中央人员\n// 路由：POST /idaas/users/batch-disable\nimport db;\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var p=body||{};\n    var domain=p.domain||\'workforce\';\n    var rights=directoryScope(\'users:write\',domain);\n    var entries=p.entries||[];\n    if(entries.size()<1 || entries.size()>100) {\n        exit 400,\'每次请选择 1 至 100 人\';\n    }\n    var ids=entries.map(e=>e.id);\n    if(ids.filter(id=>id==null || !(\'\'+id).matches(\'[A-Za-z0-9_-]{1,64}\')).size()>0\n        || ids.distinct().size()!=ids.size()) {\n        exit 400,\'人员标识重复或不正确\';\n    }\n    var sql=db.normal();\n    return mutate(rights.ctx,\'users:batch-disable\',p,()=>{\n        var fresh=directoryScope(\'users:write\',domain);\n        var people=sql.select("""\nselect tid as id,identity_domain,status,version\nfrom iam_subject_t\nwhere tid in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n  and identity_domain=#{domain} and is_del=0\nfor update\n""");\n        if(people.size()!=ids.size()) {\n            exit 404,\'人员不存在或不属于当前身份域\';\n        }\n        var appointments=sql.select("""\nselect subject_id,org_id\nfrom iam_appointment_t\nwhere subject_id in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n  and is_del=0 and status=\'ACTIVE\' and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n        for(entry in entries) {\n            var matches=people.filter(person=>person.id==entry.id);\n            if(matches.size()!=1 || matches[0].version!=entry.version) {\n                exit 409,\'人员版本已变更，请刷新后重试\';\n            }\n            var orgs=appointments.filter(job=>job.subject_id==entry.id).map(job=>job.org_id);\n            if(!fresh.all && (orgs.size()==0 || orgs.filter(id=>!fresh.orgIds.contains(id)).size()>0)) {\n                exit 403,\'选中的人员超出当前管理范围\';\n            }\n        }\n        sql.update("""\nupdate iam_subject_t set status=\'DISABLED\',version=version+1,\n    updated_by=#{fresh.ctx.userId},updated_time=utc_timestamp(6)\nwhere tid in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n""");\n        sql.update("""\nupdate iam_subject_app_t set desired_enabled=0,desired_version=desired_version+1,\n    version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n""");\n        audit(fresh.ctx,\'SUCCESS\',\'users:batch-disable\',null,null,{count:ids.size()});\n        return {count:ids.size()};\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/06.批量停用中央人员.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('46238b0f3ae244fa946ea94e313bcab4',NULL,'api','{\n  "properties": {},\n  "id": "29012d6e76a753cfa2d44cc5d086165c",\n  "script": null,\n  "groupId": "b3202123a27e56198aed6211ec0f770f",\n  "name": "07.批量导入中央人员",\n  "createTime": 1791193400395,\n  "updateTime": 1791194872495,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/import",\n  "description": "单次最多导入 500 人；批量校验机构、岗位、身份域和操作人范围，一次写入人员与任职档案，不创建登录凭据。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：批量导入中央人员档案（不创建登录凭据）\n// 路由：POST /idaas/users/import\nimport db;\nimport identityRuntime;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var p=body||{};\n    var domain=p.domain||\'workforce\';\n    var rights=directoryScope(\'users:write\',domain);\n    var rows=p.rows||[];\n    if(rows.size()<1 || rows.size()>500) {\n        exit 400,\'每次可导入 1 至 500 人\';\n    }\n    var sql=db.normal();\n    return mutate(rights.ctx,\'users:import\',p,()=>{\n        var fresh=directoryScope(\'users:write\',domain);\n        var codes=rows.map(row=>(row.orgCode||\'\').trim()).filter(code=>code!=\'\').distinct();\n        var posts=rows.map(row=>(row.post||\'\').trim()).filter(code=>code!=\'\').distinct();\n        var orgs=codes.size()==0?[]:sql.select("""\nselect tid as id,code\nfrom iam_org_t\nwhere identity_domain=#{domain} and is_del=0 and status=\'ACTIVE\'\n  and code in <foreach collection="codes" item="code" open="(" close=")" separator=",">#{code}</foreach>\n""");\n        var validPosts=posts.size()==0?[]:sql.select("""\nselect code\nfrom iam_dict_item_t\nwhere identity_domain=#{domain} and category=\'POST\' and is_del=0 and status=\'ACTIVE\'\n  and code in <foreach collection="posts" item="post" open="(" close=")" separator=",">#{post}</foreach>\n""");\n        var accounts=[];\n        var prepared=[];\n        var jobs=[];\n        for(row in rows) {\n            var name=(row.name||\'\').trim();\n            var account=(row.account||\'\').trim();\n            var email=(row.email||\'\').trim();\n            var phone=(row.phone||\'\').trim();\n            var orgCode=(row.orgCode||\'\').trim();\n            var post=(row.post||\'\').trim();\n            if(name==\'\' || name.length()>100 || !account.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\')\n                || email.length()>512 || phone.length()>256 || accounts.contains(account)) {\n                exit 400,\'CSV 中存在无效或重复的人员资料\';\n            }\n            accounts.add(account);\n            var matched=orgs.filter(org=>org.code==orgCode);\n            if(domain==\'workforce\' && matched.size()!=1 || domain==\'public\' && orgCode!=\'\' && matched.size()!=1) {\n                exit 400,\'CSV 机构编码不存在或未启用\';\n            }\n            if(post!=\'\' && validPosts.filter(item=>item.code==post).size()!=1) {\n                exit 400,\'CSV 岗位编码无效\';\n            }\n            if(!fresh.all && (matched.size()!=1 || !fresh.orgIds.contains(matched[0].id))) {\n                exit 403,\'CSV 人员超出当前机构管理范围\';\n            }\n            var id=IdUtil.fastSimpleUUID();\n            prepared.add({id:id,code:\'SUB_\'+id,name:name,account:account,email:email,phone:phone});\n            if(matched.size()==1) {\n                jobs.add({id:IdUtil.fastSimpleUUID(),subjectId:id,orgId:matched[0].id,post:post});\n            }\n        }\n        sql.update("""\ninsert into iam_subject_t(tid,identity_domain,subject_code,account_hint,name,email,phone,\n    employment_type,status,created_by,updated_by)\nvalues <foreach collection="prepared" item="row" open="(" close=")" separator="),(">\n    #{row.id},#{domain},#{row.code},#{row.account},#{row.name},#{row.email},#{row.phone},\n     \'EMPLOYEE\',\'ACTIVE\',#{fresh.ctx.userId},#{fresh.ctx.userId}\n</foreach>\n""");\n        if(jobs.size()>0) {\n            sql.update("""\ninsert into iam_appointment_t(tid,subject_id,org_id,post_code,is_primary,status,valid_from)\nvalues <foreach collection="jobs" item="job" open="(" close=")" separator="),(">\n    #{job.id},#{job.subjectId},#{job.orgId},#{job.post},1,\'ACTIVE\',utc_timestamp(6)\n</foreach>\n""");\n        }\n        audit(fresh.ctx,\'SUCCESS\',\'users:import\',null,null,{count:prepared.size()});\n        return {count:prepared.size()};\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/07.批量导入中央人员.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1502f30aa65b47f48264c18858cd82b6',NULL,NULL,'{\n  "properties": {},\n  "id": "b3202123a27e56198aed6211ec0f770f",\n  "name": "11.人员目录",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/users",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/11.人员目录/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d33cc92b15d64457b798a33150a9fd41',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('97185300caf4464393562688be29d992',NULL,'api','{\n  "properties": {},\n  "id": "142663c78c48525fa8dcda96fba493f2",\n  "script": null,\n  "groupId": "862919dc32c65a92b119a012b4e39477",\n  "name": "01.查询中央机构列表",\n  "createTime": 1790612165860,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的中央机构，应用权限及身份域过滤后返回可展示字段；不发生写入。处理控制库的中央机构和层级关系；不因本次读写自动修改租户机构。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：查询中央机构列表\n// 路由：GET /idaas/orgs/list\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory\' as directory;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'status\',\'orgId\',\'includeChildren\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    return directory(\'orgs\',\'list\',payload);\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/01.查询中央机构列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4d99ef0127e242c895da05452a0e8663',NULL,'api','{\n  "properties": {},\n  "id": "f35cf38baa1455b085cfc3ae6d7473b3",\n  "script": null,\n  "groupId": "862919dc32c65a92b119a012b4e39477",\n  "name": "02.保存中央机构",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新中央机构及必要关联记录，写入审计并返回保存结果。处理控制库的中央机构和层级关系；不因本次读写自动修改租户机构。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存中央机构\n// 路由：POST /idaas/orgs/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新中央机构及必要关联记录，写入审计并返回保存结果。处理控制库的中央机构和层级关系；不因本次读写自动修改租户机构。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'orgs\';\n    var operation = \'save\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/02.保存中央机构.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ece2f57de7e04b1b918c4d634ddcfb9b',NULL,'api','{\n  "properties": {},\n  "id": "67cd460119445b64a9652e73c102e0eb",\n  "script": null,\n  "groupId": "862919dc32c65a92b119a012b4e39477",\n  "name": "03.归档中央机构",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载中央机构并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央机构和层级关系；不因本次读写自动修改租户机构。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档中央机构\n// 路由：POST /idaas/orgs/remove\n// 业务说明：按标识加载中央机构并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央机构和层级关系；不因本次读写自动修改租户机构。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'orgs\';\n    var operation = \'remove\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/03.归档中央机构.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99a49ff9a3a44f7fa115c9710b9429f6',NULL,'api','{\n  "properties": {},\n  "id": "b359f3c8593055f9aa8bcd4228f59504",\n  "script": null,\n  "groupId": "862919dc32c65a92b119a012b4e39477",\n  "name": "04.机构目录操作待开通",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/operations",\n  "description": "当前直接返回业务错误 503，说明旧机构目录操作记录查询尚未开通；不读取或修改机构资料。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.机构目录操作待开通\n// 路由：GET /idaas/orgs/operations\n// 业务说明：当前直接返回业务错误 503，说明旧机构目录操作记录查询尚未开通；不读取或修改机构资料。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    exit 503,\'中央目录写入将在第二阶段开通\';\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/04.机构目录操作待开通.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f19cbc92ec4141428491e5337b629198',NULL,'api','{\n  "properties": {},\n  "id": "c663226508655ed98fc46eeb20b051e6",\n  "script": null,\n  "groupId": "862919dc32c65a92b119a012b4e39477",\n  "name": "05.机构目录重试待开通",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/retry",\n  "description": "当前直接返回业务错误 503，说明旧机构目录重试流程尚未开通；不读取或修改机构资料，也不会后台执行任务。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.机构目录重试待开通\n// 路由：POST /idaas/orgs/retry\n// 业务说明：当前直接返回业务错误 503，说明旧机构目录重试流程尚未开通；不读取或修改机构资料，也不会后台执行任务。\nimport identityRuntime;\nimport \'@/idaas/api-call\' as apiCall;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    exit 503,\'中央目录写入将在第二阶段开通\';\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/05.机构目录重试待开通.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('36c3cf9f9ab84ee28c210d82d0bfeba3',NULL,NULL,'{\n  "properties": {},\n  "id": "862919dc32c65a92b119a012b4e39477",\n  "name": "12.机构目录",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/orgs",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/12.机构目录/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('16070f718c3747cdb0dcf1c288951473',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('89c14d76c74a4374a2030298c2dc1064',NULL,'api','{\n  "properties": {},\n  "id": "696383013abe5008aae8fe5ed01ac834",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "01.读取下发目标选项",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/options",\n  "description": "按当前操作人的应用范围列出可配置下发接收端的应用、资料类型与可用目标，不发起下发。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.读取下发目标选项\n// 路由：GET /idaas/provision/options\n// 业务说明：按当前操作人的应用范围列出可配置下发接收端的应用、资料类型与可用目标，不发起下发。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'appId\',\'configId\',\'id\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'options\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var id=p.configId||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?p.appId||p.targetTenantId:old.app_id;\n    var permission=operation==\'configs\' || operation==\'options\'?\'sync:read\':\'sync:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'configs\' || operation==\'options\'?listContext(permission,appId,\'workforce\'):guard(permission,appId,\'workforce\');\n    var visible=x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x)).size()>0).size()>0;\n    if(operation==\'options\') {\n        return sql.select("""\nselect a.tid appId,a.tid tenantId,a.name tenantName,a.code tenantCode\nfrom iam_application_t a\nwhere a.kind=\'BUSINESS\'\n    and a.is_del=0\n""").filter(a=>visible(a.appId));\n    }\n    if(old==null && operation!=\'save-config\') {\n        exit 404,\'接收配置不存在\';\n    }\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(operation!=\'save-config\' && operation!=\'rotate\') {\n            exit 400,\'配置操作不正确\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=p.version) {\n            exit 409,\'配置版本已变更\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'只能配置业务应用\';\n        }\n        var keyId=p.keyId;\n        var secret=p.secret;\n        var key=old==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(keyId==null && key!=null) {\n            keyId=JSONUtil.parseObj(key.public_data).keyId;\n        }\n        if(keyId==null || !keyId.matches(\'[A-Za-z0-9_-]{3,64}\')) {\n            exit 400,\'密钥标识不正确\';\n        }\n        if(operation==\'rotate\') {\n            if(secret==null || secret==\'\') {\n                exit 400,\'轮换密钥不能为空\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset enabled=0,last_test_result=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=\'OFF\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        else {\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var instance=p.receiverInstanceId;\n            var name=(p.name||\'接收配置\').trim();\n            var timeout=p.timeout||10;\n            if(instance==null || !instance.matches(\'[A-Za-z0-9_.-]{3,100}\') || name==\'\' || name.length()>100 || timeout<1 || timeout>30 || p.mapping!=null && p.mapping!=\'{}\') {\n                exit 400,\'实例、名称、超时或映射配置不正确\';\n            }\n            var enabled=p.enabled==true?1:0;\n            var changed=old==null || old.endpoint!=endpoint || old.receiver_instance_id!=instance || secret!=null && secret!=\'\';\n            if(enabled==1 && (changed || old.last_test_result!=\'SUCCESS\')) {\n                exit 409,\'请先保存关闭状态并测试接收实例，再启用\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n""")!=null) {\n                    exit 409,\'应用已有接收配置，请使用原配置修改\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_sync_config_t(tid,\n                app_id, display_name, endpoint, protocol_version, receiver_instance_id, timeout_seconds,\n                object_types, enabled)\nvalues(#{id},#{appId},#{name},#{endpoint},\'IDAAS/2\',#{instance},#{timeout},\'["ORG","RESOURCE","ROLE","SUBJECT"]\',#{enabled})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_sync_config_t\nset display_name=#{name},endpoint=#{endpoint},receiver_instance_id=#{instance},\n    timeout_seconds=#{timeout},enabled=#{enabled},last_test_result=case\n        when #{changed} then null\n        else last_test_result\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var mode=enabled==1?\'HTTP\':\'OFF\';\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        if(secret!=null && secret!=\'\') {\n            var cipher=identityTransport.encrypt(secret);\n            var revision=key==null?1:key.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',version=version+1\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            var kid=IdUtil.fastSimpleUUID();\n            var data=JSONUtil.toJsonStr({\n                keyId:keyId\n            });\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_cipher, public_data,\n                status)\nvalues(#{kid},\'SYNC_CONFIG\',#{id},\'HMAC_KEY\',\'primary\',#{revision},\'HMAC_SHA256_AES256_GCM\',#{cipher},#{data},\'ACTIVE\')\n""");\n        }\n        else if(key==null) {\n            exit 400,\'接入密钥不能为空\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/01.读取下发目标选项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2ef28179052c4bed8d5a41ef41133eb1',NULL,'api','{\n  "properties": {},\n  "id": "01aae8ea3467573180daa39b2c0f2480",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "02.查询下发接入配置",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/configs",\n  "description": "读取指定应用的接收地址、认证方式和启用状态；对接入凭据脱敏，不主动连接租户。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.查询下发接入配置\n// 路由：GET /idaas/provision/configs\n// 业务说明：读取指定应用的接收地址、认证方式和启用状态；对接入凭据脱敏，不主动连接租户。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'appId\',\'configId\',\'id\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'configs\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var id=p.configId||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?p.appId||p.targetTenantId:old.app_id;\n    var permission=operation==\'configs\' || operation==\'options\'?\'sync:read\':\'sync:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'configs\' || operation==\'options\'?listContext(permission,appId,\'workforce\'):guard(permission,appId,\'workforce\');\n    var visible=x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x)).size()>0).size()>0;\n    if(operation==\'configs\') {\n        return sql.select("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere is_del=0\n""").filter(x=>visible(x.app_id)).map(x=>{\n            var key=sql.selectOne("""\nselect public_data\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{x.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            return {\n                id:x.id,appId:x.app_id,targetTenantId:x.app_id,name:x.display_name,endpoint:x.endpoint,receiverInstanceId:x.receiver_instance_id,enabled:x.enabled==1,timeout:x.timeout_seconds,version:x.version,keyId:key==null?\'\':JSONUtil.parseObj(key.public_data).keyId,hasSecret:key!=null,lastTestResult:x.last_test_result,protocol:x.protocol_version\n            };\n        });\n    }\n    if(old==null && operation!=\'save-config\') {\n        exit 404,\'接收配置不存在\';\n    }\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(operation!=\'save-config\' && operation!=\'rotate\') {\n            exit 400,\'配置操作不正确\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=p.version) {\n            exit 409,\'配置版本已变更\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'只能配置业务应用\';\n        }\n        var keyId=p.keyId;\n        var secret=p.secret;\n        var key=old==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(keyId==null && key!=null) {\n            keyId=JSONUtil.parseObj(key.public_data).keyId;\n        }\n        if(keyId==null || !keyId.matches(\'[A-Za-z0-9_-]{3,64}\')) {\n            exit 400,\'密钥标识不正确\';\n        }\n        if(operation==\'rotate\') {\n            if(secret==null || secret==\'\') {\n                exit 400,\'轮换密钥不能为空\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset enabled=0,last_test_result=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=\'OFF\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        else {\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var instance=p.receiverInstanceId;\n            var name=(p.name||\'接收配置\').trim();\n            var timeout=p.timeout||10;\n            if(instance==null || !instance.matches(\'[A-Za-z0-9_.-]{3,100}\') || name==\'\' || name.length()>100 || timeout<1 || timeout>30 || p.mapping!=null && p.mapping!=\'{}\') {\n                exit 400,\'实例、名称、超时或映射配置不正确\';\n            }\n            var enabled=p.enabled==true?1:0;\n            var changed=old==null || old.endpoint!=endpoint || old.receiver_instance_id!=instance || secret!=null && secret!=\'\';\n            if(enabled==1 && (changed || old.last_test_result!=\'SUCCESS\')) {\n                exit 409,\'请先保存关闭状态并测试接收实例，再启用\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n""")!=null) {\n                    exit 409,\'应用已有接收配置，请使用原配置修改\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_sync_config_t(tid,\n                app_id, display_name, endpoint, protocol_version, receiver_instance_id, timeout_seconds,\n                object_types, enabled)\nvalues(#{id},#{appId},#{name},#{endpoint},\'IDAAS/2\',#{instance},#{timeout},\'["ORG","RESOURCE","ROLE","SUBJECT"]\',#{enabled})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_sync_config_t\nset display_name=#{name},endpoint=#{endpoint},receiver_instance_id=#{instance},\n    timeout_seconds=#{timeout},enabled=#{enabled},last_test_result=case\n        when #{changed} then null\n        else last_test_result\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var mode=enabled==1?\'HTTP\':\'OFF\';\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        if(secret!=null && secret!=\'\') {\n            var cipher=identityTransport.encrypt(secret);\n            var revision=key==null?1:key.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',version=version+1\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            var kid=IdUtil.fastSimpleUUID();\n            var data=JSONUtil.toJsonStr({\n                keyId:keyId\n            });\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_cipher, public_data,\n                status)\nvalues(#{kid},\'SYNC_CONFIG\',#{id},\'HMAC_KEY\',\'primary\',#{revision},\'HMAC_SHA256_AES256_GCM\',#{cipher},#{data},\'ACTIVE\')\n""");\n        }\n        else if(key==null) {\n            exit 400,\'接入密钥不能为空\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/02.查询下发接入配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('85966ac37bc14515981687731b788f0c',NULL,'api','{\n  "properties": {},\n  "id": "d3584c2bbce4543ca25ffbc5654a8c46",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "03.查询下发任务记录",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/tasks",\n  "description": "按应用和状态查询手动创建的资料下发任务、执行结果与失败原因；不执行待处理任务。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.查询下发任务记录\n// 路由：GET /idaas/provision/tasks\n// 业务说明：按应用和状态查询手动创建的资料下发任务、执行结果与失败原因；不执行待处理任务。\nimport db;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'appId\',\'configId\',\'id\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'tasks\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'tasks\') {\n        // 按操作员的应用管理范围过滤可见数据。\n        var ctx=listContext(\'sync:read\',p.appId||null,\'workforce\');\n        return sql.select("""\nselect t.*,t.tid as id,c.display_name,date_format(t.created_time,\n        \'%Y-%m-%dT%H:%i:%sZ\') created_utc\nfrom iam_sync_task_t t\njoin iam_sync_config_t c on c.tid=t.config_id\norder by t.created_time desc\nlimit 200\n""").filter(t=>(p.appId==null || t.app_id==p.appId) && ctx.pairs.filter(pair=>pair.codes.contains(\'sync:read\') && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==t.app_id)).size()>0).size()>0).map(t=>({\n            id:t.id,version:t.version,appId:t.app_id,targetTenantId:t.app_id,configId:t.config_id,name:t.display_name,createdAt:t.created_utc,status:t.status==\'SUCCEEDED\'?\'success\':[\'FAILED\',\'PARTIAL\'].contains(t.status)?\'failed\':t.status==\'CANCELED\'?\'cancelled\':\'pending\',serverStatus:t.status,items:sql.select("""\nselect *,tid as id\nfrom iam_sync_item_t\nwhere task_id=#{t.id}\norder by sequence_no\n""").map(i=>({\n                eventId:i.id,objectId:i.object_id,type:i.object_type==\'SUBJECT\'?\'user\':i.object_type.toLowerCase(),version:i.source_version,attempt:i.attempt_count,status:[\'APPLIED\',\'DUPLICATE\'].contains(i.status)?\'success\':[\'FAILED\',\'CONFLICT\'].contains(i.status)?\'failed\':i.status==\'CANCELED\'?\'cancelled\':\'pending\',result:i.result_json==null?null:JSONUtil.parseObj(i.result_json)\n            }))\n        }));\n    }\n    var task=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n""");\n    if(task==null) {\n        exit 404,\'任务不存在\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'sync:execute\',task.app_id,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(current.version!=p.version) {\n            exit 409,\'任务版本已变更\';\n        }\n        if(operation==\'cancel\') {\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'CANCELED\',version=version+1\nwhere tid=#{p.id}\n""");\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'CANCELED\'\nwhere task_id=#{p.id}\n    and status in (\'PENDING\',\'FAILED\',\'CONFLICT\')\n""");\n        }\n        else if(operation==\'retry\') {\n            if(current.status==\'CANCELED\') {\n                exit 409,\'已取消的任务须重新预览\';\n            }\n            if(sql.selectOne("""\nselect i.tid as id\nfrom iam_sync_item_t i\njoin iam_sync_config_t c on c.tid=#{current.config_id}\nwhere i.task_id=#{p.id}\n    and i.status in (\'FAILED\',\'CONFLICT\')\n    and i.attempt_count>=c.max_attempts\nlimit 1\n""")!=null) {\n                exit 409,\'已达尝试上限，请修正原因并重新预览创建任务\';\n            }\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'PENDING\',next_retry_time=null\nwhere task_id=#{p.id}\n    and status in (\'FAILED\',\'CONFLICT\')\n""");\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'PENDING\',version=version+1\nwhere tid=#{p.id}\n""");\n        }\n        else {\n            exit 400,\'任务操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,p.id,null,{\n            id:p.id\n        });\n        return {\n            id:p.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/03.查询下发任务记录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('78e3e30a0cfd44a9895102855377a3f2',NULL,'api','{\n  "properties": {},\n  "id": "ba7b2a02b6ff551186d4dee95781f743",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "04.保存下发接入配置",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save-config",\n  "description": "校验应用管理权限、接收地址和认证参数，将接入配置写入控制库；仅保存配置，不发起数据传输。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.保存下发接入配置\n// 路由：POST /idaas/provision/save-config\n// 业务说明：校验应用管理权限、接收地址和认证参数，将接入配置写入控制库；仅保存配置，不发起数据传输。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save-config\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var id=p.configId||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?p.appId||p.targetTenantId:old.app_id;\n    var permission=operation==\'configs\' || operation==\'options\'?\'sync:read\':\'sync:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'configs\' || operation==\'options\'?listContext(permission,appId,\'workforce\'):guard(permission,appId,\'workforce\');\n    var visible=x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x)).size()>0).size()>0;\n    if(old==null && operation!=\'save-config\') {\n        exit 404,\'接收配置不存在\';\n    }\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(operation!=\'save-config\' && operation!=\'rotate\') {\n            exit 400,\'配置操作不正确\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=p.version) {\n            exit 409,\'配置版本已变更\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'只能配置业务应用\';\n        }\n        var keyId=p.keyId;\n        var secret=p.secret;\n        var key=old==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(keyId==null && key!=null) {\n            keyId=JSONUtil.parseObj(key.public_data).keyId;\n        }\n        if(keyId==null || !keyId.matches(\'[A-Za-z0-9_-]{3,64}\')) {\n            exit 400,\'密钥标识不正确\';\n        }\n        if(operation==\'rotate\') {\n            if(secret==null || secret==\'\') {\n                exit 400,\'轮换密钥不能为空\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset enabled=0,last_test_result=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=\'OFF\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        else {\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var instance=p.receiverInstanceId;\n            var name=(p.name||\'接收配置\').trim();\n            var timeout=p.timeout||10;\n            if(instance==null || !instance.matches(\'[A-Za-z0-9_.-]{3,100}\') || name==\'\' || name.length()>100 || timeout<1 || timeout>30 || p.mapping!=null && p.mapping!=\'{}\') {\n                exit 400,\'实例、名称、超时或映射配置不正确\';\n            }\n            var enabled=p.enabled==true?1:0;\n            var changed=old==null || old.endpoint!=endpoint || old.receiver_instance_id!=instance || secret!=null && secret!=\'\';\n            if(enabled==1 && (changed || old.last_test_result!=\'SUCCESS\')) {\n                exit 409,\'请先保存关闭状态并测试接收实例，再启用\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n""")!=null) {\n                    exit 409,\'应用已有接收配置，请使用原配置修改\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_sync_config_t(tid,\n                app_id, display_name, endpoint, protocol_version, receiver_instance_id, timeout_seconds,\n                object_types, enabled)\nvalues(#{id},#{appId},#{name},#{endpoint},\'IDAAS/2\',#{instance},#{timeout},\'["ORG","RESOURCE","ROLE","SUBJECT"]\',#{enabled})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_sync_config_t\nset display_name=#{name},endpoint=#{endpoint},receiver_instance_id=#{instance},\n    timeout_seconds=#{timeout},enabled=#{enabled},last_test_result=case\n        when #{changed} then null\n        else last_test_result\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var mode=enabled==1?\'HTTP\':\'OFF\';\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        if(secret!=null && secret!=\'\') {\n            var cipher=identityTransport.encrypt(secret);\n            var revision=key==null?1:key.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',version=version+1\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            var kid=IdUtil.fastSimpleUUID();\n            var data=JSONUtil.toJsonStr({\n                keyId:keyId\n            });\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_cipher, public_data,\n                status)\nvalues(#{kid},\'SYNC_CONFIG\',#{id},\'HMAC_KEY\',\'primary\',#{revision},\'HMAC_SHA256_AES256_GCM\',#{cipher},#{data},\'ACTIVE\')\n""");\n        }\n        else if(key==null) {\n            exit 400,\'接入密钥不能为空\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/04.保存下发接入配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8adfbefd60384b348184e1f06f883c91',NULL,'api','{\n  "properties": {},\n  "id": "440df30da8fa582e9ce22c24c6693e06",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "05.测试下发接收端",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/test",\n  "description": "由用户触发连接测试，使用已保存的接收配置验证目标接口可达性与鉴权并返回测试结果。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.测试下发接收端\n// 路由：POST /idaas/provision/test\n// 业务说明：由用户触发连接测试，使用已保存的接收配置验证目标接口可达性与鉴权并返回测试结果。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'test\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var id=p.configId||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?p.appId||p.targetTenantId:old.app_id;\n    var permission=operation==\'configs\' || operation==\'options\'?\'sync:read\':\'sync:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'configs\' || operation==\'options\'?listContext(permission,appId,\'workforce\'):guard(permission,appId,\'workforce\');\n    var visible=x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x)).size()>0).size()>0;\n    if(old==null && operation!=\'save-config\') {\n        exit 404,\'接收配置不存在\';\n    }\n    if(operation==\'test\') {\n        var key=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(key==null) {\n            exit 409,\'没有活动接入密钥\';\n        }\n        var event={\n            eventId:IdUtil.fastSimpleUUID(),appId:appId,receiverInstanceId:old.receiver_instance_id,objectType:\'PING\',objectId:\'receiver\',sourceVersion:1,action:\'UPSERT\',data:{}\n        };\n        var encoded=identityTransport.canonicalJson(event);\n        var keyId=JSONUtil.parseObj(key.public_data).keyId;\n        // 仅在本次人工请求中向已配置接收地址发送签名事件。\n        var response=identityTransport.send2(old.endpoint,key.secret_cipher,keyId,appId,old.receiver_instance_id,encoded,old.timeout_seconds);\n        var receipt=response.data==null?null:response.data.receipt;\n        // 核对签名回执的事件号、版本和目标实例，成功后才确认下发结果。\n        var ok=response.code==0 && receipt!=null && receipt.appId==appId && receipt.receiverInstanceId==old.receiver_instance_id && receipt.eventId==event.eventId && receipt.result==\'APPLIED\' && identityTransport.verifyReceipt(key.secret_cipher,receipt,response.data.receiptSignature);\n        var result=ok?\'SUCCESS\':\'FAILED\';\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'sync:test\',p,()=>{\n            var latest=sql.selectOne("""\nselect version\nfrom iam_sync_config_t\nwhere tid=#{id}\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(latest.version!=old.version) {\n                exit 409,\'测试期间配置已变更\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset last_test_time=utc_timestamp(6),last_test_result=#{result}\nwhere tid=#{id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,ok?\'SUCCESS\':\'FAILED\',\'sync:test\',id,result,{\n                id:id\n            });\n            if(!ok) {\n                return {\n                    verified:false,result:\'FAILED\'\n                };\n            }\n            return {\n                verified:true,result:\'SUCCESS\',appId:appId,receiverInstanceId:old.receiver_instance_id\n            };\n        });\n    }\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(operation!=\'save-config\' && operation!=\'rotate\') {\n            exit 400,\'配置操作不正确\';\n        }\n        if(old!=null && old.version!=p.version) {\n            exit 409,\'配置版本已变更\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'只能配置业务应用\';\n        }\n        var keyId=p.keyId;\n        var secret=p.secret;\n        var key=old==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(keyId==null && key!=null) {\n            keyId=JSONUtil.parseObj(key.public_data).keyId;\n        }\n        if(keyId==null || !keyId.matches(\'[A-Za-z0-9_-]{3,64}\')) {\n            exit 400,\'密钥标识不正确\';\n        }\n        if(operation==\'rotate\') {\n            if(secret==null || secret==\'\') {\n                exit 400,\'轮换密钥不能为空\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset enabled=0,last_test_result=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=\'OFF\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        else {\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var instance=p.receiverInstanceId;\n            var name=(p.name||\'接收配置\').trim();\n            var timeout=p.timeout||10;\n            if(instance==null || !instance.matches(\'[A-Za-z0-9_.-]{3,100}\') || name==\'\' || name.length()>100 || timeout<1 || timeout>30 || p.mapping!=null && p.mapping!=\'{}\') {\n                exit 400,\'实例、名称、超时或映射配置不正确\';\n            }\n            var enabled=p.enabled==true?1:0;\n            var changed=old==null || old.endpoint!=endpoint || old.receiver_instance_id!=instance || secret!=null && secret!=\'\';\n            if(enabled==1 && (changed || old.last_test_result!=\'SUCCESS\')) {\n                exit 409,\'请先保存关闭状态并测试接收实例，再启用\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n""")!=null) {\n                    exit 409,\'应用已有接收配置，请使用原配置修改\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_sync_config_t(tid,\n                app_id, display_name, endpoint, protocol_version, receiver_instance_id, timeout_seconds,\n                object_types, enabled)\nvalues(#{id},#{appId},#{name},#{endpoint},\'IDAAS/2\',#{instance},#{timeout},\'["ORG","RESOURCE","ROLE","SUBJECT"]\',#{enabled})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_sync_config_t\nset display_name=#{name},endpoint=#{endpoint},receiver_instance_id=#{instance},\n    timeout_seconds=#{timeout},enabled=#{enabled},last_test_result=case\n        when #{changed} then null\n        else last_test_result\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var mode=enabled==1?\'HTTP\':\'OFF\';\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        if(secret!=null && secret!=\'\') {\n            var cipher=identityTransport.encrypt(secret);\n            var revision=key==null?1:key.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',version=version+1\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            var kid=IdUtil.fastSimpleUUID();\n            var data=JSONUtil.toJsonStr({\n                keyId:keyId\n            });\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_cipher, public_data,\n                status)\nvalues(#{kid},\'SYNC_CONFIG\',#{id},\'HMAC_KEY\',\'primary\',#{revision},\'HMAC_SHA256_AES256_GCM\',#{cipher},#{data},\'ACTIVE\')\n""");\n        }\n        else if(key==null) {\n            exit 400,\'接入密钥不能为空\';\n        }\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/05.测试下发接收端.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('22fd880d7d914031911b844f2f1f25b6',NULL,'api','{\n  "properties": {},\n  "id": "d2ae39bdaaf355b98c48d3f1ae366416",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "06.创建手动下发任务",\n  "createTime": 1790612165860,\n  "updateTime": 1791194872495,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/create",\n  "description": "核验应用与资料范围，生成待执行的下发任务及目标快照；创建记录本身不通过后台轮询执行。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：06.创建手动下发任务\n// 路由：POST /idaas/provision/create\n// 业务说明：核验应用与资料范围，生成待执行的下发任务及目标快照；创建记录本身不通过后台轮询执行。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/effective-access-batch\' as effectiveBatch;\nimport \'@/idaas/resource-enabled\' as enabled;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n\n    // 此流程仅由明确的接口请求触发，不在后台自动扫描或下发租户数据。\n    // 冻结规范JSON和目标实例。仅同步明确分配的资料，不把全库人员隐含分配到应用。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    context();\n    var config=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{p.configId}\n    and is_del=0\n""");\n    if(config==null) {\n        exit 404,\'配置不存在\';\n    }\n    var appId=config.app_id;\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'sync:write\',appId,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'sync:create\',p,()=>{\n        config=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{p.configId}\n    and is_del=0\n    for update\n""");\n        if(config.enabled!=1 || config.last_test_result!=\'SUCCESS\') {\n            exit 409,\'接收配置尚未测试并启用\';\n        }\n        rebuild(appId,\'workforce\');\n        var selected=p.selectedIds||[];\n        if(selected.size()>1000) {\n            exit 400,\'选中对象过多\';\n        }\n        var subjects=sql.select("""\nselect s.*,s.tid as id,sa.account_alias,sa.desired_enabled,sa.desired_version,sa.assignment_status\nfrom iam_subject_app_t sa\njoin iam_subject_t s on s.tid=sa.subject_id\nwhere sa.app_id=#{appId}\n    and s.identity_domain=\'workforce\'\n""");\n        if(p.kind==\'user\' && selected.size()>0) {\n            if(selected.filter(id=>subjects.filter(s=>s.id==id).size()==0).size()>0) {\n                exit 400,\'请先在应用中分配所选人员\';\n            }\n            subjects=subjects.filter(s=>selected.contains(s.id));\n        }\n        if(p.kind==\'org\') {\n            subjects=[];\n        }\n        var orgIds=[];\n        var ranges=sql.select("""\nselect o.path,ao.include_children\nfrom iam_app_org_t ao\njoin iam_org_t o on o.tid=ao.org_id\nwhere ao.app_id=#{appId}\n    and ao.status=\'ACTIVE\'\n""");\n        var orgs=sql.select("""\nselect *,tid as id\nfrom iam_org_t\nwhere identity_domain=\'workforce\'\norder by depth,tid\n""");\n        for(org in orgs) {\n            if(ranges.filter(r=>r.path==org.path || r.include_children==1 && org.path.startsWith(r.path)).size()>0) {\n                orgIds.add(org.id);\n            }\n        }\n        var subjectIds=subjects.map(subject=>subject.id);\n        var allJobs=subjectIds.size()==0?[]:sql.select("""\nselect subject_id,org_id,valid_from,valid_until,is_primary\nfrom iam_appointment_t\nwhere subject_id in <foreach collection="subjectIds" item="subjectId" open="(" close=")" separator=",">#{subjectId}</foreach>\n    and status=\'ACTIVE\' and is_del=0\n""");\n        for(subject in subjects) {\n            for(job in allJobs.filter(row=>row.subject_id==subject.id)) {\n                if(!orgIds.contains(job.org_id)) {\n                    orgIds.add(job.org_id);\n                }\n            }\n        }\n        if(p.kind==\'org\' && selected.size()>0) {\n            if(selected.filter(id=>!orgIds.contains(id)).size()>0) {\n                exit 403,\'机构不在应用分配范围内\';\n            }\n            orgIds=orgIds.filter(id=>selected.contains(id));\n        }\n        // 每个任职机构需要的祖先也进入同一依赖顺序。\n        for(org in orgs) {\n            if(orgIds.contains(org.id)) {\n                for(parent in orgs) {\n                    if(org.path.startsWith(parent.path) && !orgIds.contains(parent.id)) {\n                        orgIds.add(parent.id);\n                    }\n                }\n            }\n        }\n        var roleRows=sql.select("""\nselect *,tid as id\nfrom iam_role_t\nwhere app_id=#{appId}\n    and identity_domain=\'workforce\'\norder by tid\n""");\n        var resourceRows=sql.select("""\nselect *,tid as id\nfrom iam_resource_t\nwhere app_id=#{appId}\n    and identity_domain=\'workforce\'\norder by tid\n""");\n        var roleResources=sql.select("""\nselect rr.role_id,rr.resource_id\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id and r.app_id=rr.app_id\n  and r.status=\'ACTIVE\' and r.is_del=0\nwhere rr.app_id=#{appId}\norder by rr.role_id,rr.resource_id\n""");\n        var enabledResourceIds=enabled(appId,\'workforce\',roleResources.map(row=>row.resource_id).distinct());\n        var accessBySubject=subjectIds.size()==0?{}:effectiveBatch(appId,\'workforce\',subjectIds);\n        var validJobs=subjectIds.size()==0?[]:sql.select("""\nselect subject_id,org_id,is_primary\nfrom iam_appointment_t\nwhere subject_id in <foreach collection="subjectIds" item="subjectId" open="(" close=")" separator=",">#{subjectId}</foreach>\n    and status=\'ACTIVE\' and is_del=0 and valid_from<=utc_timestamp(6)\n    and (valid_until is null or valid_until>utc_timestamp(6))\norder by subject_id,org_id\n""");\n        var ordered=[];\n        var remaining=resourceRows;\n        var visited=[];\n        while(remaining.size()>0) {\n            var round=remaining.filter(r=>r.parent_id==null || visited.contains(r.parent_id));\n            if(round.size()==0) {\n                exit 409,\'资源依赖不完整\';\n            }\n            for(r in round) {\n                ordered.add(r);\n                visited.add(r.id);\n            }\n            remaining=remaining.filter(r=>!visited.contains(r.id));\n        }\n        var taskId=IdUtil.fastSimpleUUID();\n        var key=sql.selectOne("""\nselect public_data\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{config.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(key==null) {\n            exit 409,\'没有活动接入凭据\';\n        }\n        var snapshot=identityTransport.canonicalJson({\n            endpoint:config.endpoint,instance:config.receiver_instance_id,protocol:config.protocol_version,mapping:config.mapping_json,keyId:JSONUtil.parseObj(key.public_data).keyId\n        });\n        var mode=p.mode||\'FULL\';\n        if(![\'FULL\',\'DELTA\',\'RECONCILE\'].contains(mode)) {\n            exit 400,\'任务模式不正确\';\n        }\n        var candidateIds=[];\n        for(id in orgIds) {\n            if(!candidateIds.contains(id)) {\n                candidateIds.add(id);\n            }\n        }\n        for(row in resourceRows) {\n            if(!candidateIds.contains(row.id)) {\n                candidateIds.add(row.id);\n            }\n        }\n        for(row in roleRows) {\n            if(!candidateIds.contains(row.id)) {\n                candidateIds.add(row.id);\n            }\n        }\n        for(id in subjectIds) {\n            if(!candidateIds.contains(id)) {\n                candidateIds.add(id);\n            }\n        }\n        if(candidateIds.size()>1000) {\n            exit 400,\'任务超过1000项，请缩小应用分配范围\';\n        }\n        var previousRows=candidateIds.size()==0?[]:sql.select("""\nselect object_type,object_id,source_version,payload_json\nfrom (select object_type,object_id,source_version,payload_json,\n    row_number() over(partition by object_type,object_id\n      order by source_version desc,created_time desc) rn\n  from iam_sync_item_t\n  where app_id=#{appId}\n    and object_id in <foreach collection="candidateIds" item="candidateId" open="(" close=")" separator=",">#{candidateId}</foreach>) latest\nwhere rn=1\n""");\n        var links=candidateIds.size()==0?[]:sql.select("""\nselect *,tid as id\nfrom iam_external_link_t\nwhere app_id=#{appId} and receiver_instance_id=#{config.receiver_instance_id}\n  and source_id in <foreach collection="candidateIds" item="candidateId" open="(" close=")" separator=",">#{candidateId}</foreach>\n""");\n        var ackRows=mode!=\'DELTA\' || candidateIds.size()==0?[]:sql.select("""\nselect object_type,object_id,payload_json\nfrom (select i.object_type,i.object_id,i.payload_json,\n    row_number() over(partition by i.object_type,i.object_id order by i.created_time desc) rn\n  from iam_sync_item_t i\n  join iam_external_link_t l on l.app_id=i.app_id and l.object_type=i.object_type\n    and l.source_id=i.object_id and l.ack_version=i.source_version\n    and l.receiver_instance_id=#{config.receiver_instance_id}\n  where i.app_id=#{appId} and i.status in (\'APPLIED\',\'DUPLICATE\')\n    and i.object_id in <foreach collection="candidateIds" item="candidateId" open="(" close=")" separator=",">#{candidateId}</foreach>) ack\nwhere rn=1\n""");\n        sql.update("""\ninsert into iam_sync_task_t(tid,\n                app_id, config_id, config_version, config_snapshot_json, mode, request_id, created_by)\nvalues(#{taskId},#{appId},#{config.id},#{config.version},#{snapshot},#{mode},#{p.requestId},#{ctx.userId})\n""");\n        var sequence=0;\n        var events={};\n        var pendingItems=[];\n        var add=(type,id,version,data,parent)=>{\n            var prior=previousRows.filter(row=>row.object_type==type && row.object_id==id);\n            var previous=prior.size()==0?null:prior[0];\n            if(previous!=null) {\n                var oldData=identityTransport.parseJson(previous.payload_json).data;\n                var equal=identityTransport.canonicalJson(data)==identityTransport.canonicalJson(oldData);\n                var floor=previous.source_version+(equal?0:1);\n                if(version<floor) {\n                    version=floor;\n                }\n            }\n            // DELTA只跳过同实例已经确认且内容相同的对象；未确认失败事件仍需重发。\n            var found=links.filter(row=>row.object_type==type && row.source_id==id);\n            var link=found.size()==0?null:found[0];\n            if(mode==\'DELTA\' && link!=null) {\n                var confirmed=ackRows.filter(row=>row.object_type==type && row.object_id==id);\n                var ack=confirmed.size()==0?null:confirmed[0];\n                if(ack!=null && identityTransport.parseJson(ack.payload_json).receiverInstanceId==config.receiver_instance_id && identityTransport.canonicalJson(data)==identityTransport.canonicalJson(identityTransport.parseJson(ack.payload_json).data)) {\n                    return;\n                }\n            }\n            var eventId=IdUtil.fastSimpleUUID();\n            sequence=sequence+1;\n            var event={\n                eventId:eventId,appId:appId,receiverInstanceId:config.receiver_instance_id,objectType:type,objectId:id,sourceVersion:version,action:data.enabled==true?\'UPSERT\':\'DISABLE\',data:data\n            };\n            var encoded=identityTransport.canonicalJson(event);\n            var hash=DigestUtil.sha256Hex(encoded);\n            var dependency=parent==null?null:events.get(type+\'/\'+parent);\n            pendingItems.add({id:eventId,type:type,objectId:id,version:version,action:event.action,\n                sequence:sequence,dependency:dependency,encoded:encoded,hash:hash});\n            events.put(type+\'/\'+id,eventId);\n        };\n        for(org in orgs) {\n            if(orgIds.contains(org.id)) {\n                add(\'ORG\',org.id,org.version,{\n                    name:org.name,code:org.code,parentId:org.parent_id,enabled:org.status==\'ACTIVE\' && org.is_del==0\n                },org.parent_id);\n            }\n        }\n        for(resource in ordered) {\n            add(\'RESOURCE\',resource.id,resource.version,{\n                name:resource.name,code:resource.code,parentId:resource.parent_id,type:resource.resource_type.toLowerCase(),path:resource.path||\'\',method:resource.http_method||\'GET\',enabled:resource.status==\'ACTIVE\' && resource.is_del==0\n            },resource.parent_id);\n        }\n        for(role in roleRows) {\n            var resources=roleResources.filter(row=>row.role_id==role.id && enabledResourceIds.contains(row.resource_id)).map(row=>row.resource_id);\n            add(\'ROLE\',role.id,role.version,{\n                name:role.name,code:role.code,resourceIds:resources,enabled:role.status==\'ACTIVE\' && role.is_del==0\n            },null);\n        }\n        for(subject in subjects) {\n            var access=accessBySubject.get(subject.id);\n            var jobs=validJobs.filter(row=>row.subject_id==subject.id).map(j=>({\n                orgId:j.org_id,primary:j.is_primary==1\n            }));\n            add(\'SUBJECT\',subject.id,subject.desired_version,{\n                name:subject.name,account:subject.account_alias||subject.account_hint,phone:subject.phone||\'\',email:subject.email||\'\',appointments:jobs,roleIds:access.roleIds,enabled:access.hasAccess && subject.assignment_status==\'ACTIVE\'\n            },null);\n        }\n        if(sequence>1000 || sequence==0 && mode!=\'DELTA\') {\n            exit 400,\'没有可下发对象或任务超过1000项，请先配置应用分配范围\';\n        }\n        if(pendingItems.size()>0) {\n            sql.update("""\ninsert into iam_sync_item_t(tid,task_id,app_id,object_type,object_id,source_version,\n    event_action,sequence_no,depends_on_id,payload_json,payload_hash)\nvalues <foreach collection="pendingItems" item="item" open="(" close=")" separator="),(">\n    #{item.id},#{taskId},#{appId},#{item.type},#{item.objectId},#{item.version},\n     #{item.action},#{item.sequence},#{item.dependency},#{item.encoded},#{item.hash}\n</foreach>\n""");\n        }\n        var taskStatus=sequence==0?\'SUCCEEDED\':\'PENDING\';\n        sql.update("""\nupdate iam_sync_task_t\nset total_count=#{sequence},status=#{taskStatus}\nwhere tid=#{taskId}\n""");\n        sql.update("""\nupdate iam_subject_app_t\nset sync_status=\'PENDING\'\nwhere app_id=#{appId}\n    and subject_id in\n        (select object_id\n         from iam_sync_item_t\n         where task_id=#{taskId}\n             and object_type=\'SUBJECT\')\n""");\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:create\',taskId,null,{\n            id:taskId,items:sequence\n        });\n        return {\n            id:taskId,total:sequence\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/06.创建手动下发任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2f1fb391afcc47ea9a4265b2189e6c0e',NULL,'api','{\n  "properties": {},\n  "id": "98326ef1fc5558f4816375a354792250",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "07.执行手动下发任务",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/execute",\n  "description": "用户显式触发后领取指定任务，构造标准人员或机构报文，调用接收端并保存回执与失败原因。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：07.执行手动下发任务\n// 路由：POST /idaas/provision/execute\n// 业务说明：用户显式触发后领取指定任务，构造标准人员或机构报文，调用接收端并保存回执与失败原因。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.System;\nimport java.lang.IllegalStateException;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n\n    // 此流程仅由明确的接口请求触发，不在后台自动扫描或下发租户数据。\n    // 租约在本库事务中取得，HTTP在提交后执行。只有签名且完整匹配的回执能推进ack。\n    var sql=db.normal();\n    var p=payload||{};\n    var task=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n""");\n    if(task==null) {\n        exit 404,\'任务不存在\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'sync:execute\',task.app_id,\'workforce\');\n    var lease=IdUtil.fastSimpleUUID();\n    var taskId=task.id;\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var claimed=sql.transaction(()=>{\n        var row=sql.selectOne("""\nselect *,tid as id,lease_until>utc_timestamp(6) live_lease\nfrom iam_sync_task_t\nwhere tid=#{taskId}\n    for update\n""");\n        if([\'SUCCEEDED\',\'CANCELED\'].contains(row.status)) {\n            return false;\n        }\n        if(row.live_lease==1 && row.lease_token!=null) {\n            exit 409,\'任务正在执行，请稍后查看\';\n        }\n        var config=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{row.config_id}\n    and is_del=0\n""");\n        if(config==null || config.enabled!=1 || config.version!=row.config_version) {\n            exit 409,\'接收配置已关闭或变更，请重新预览创建任务\';\n        }\n        sql.update("""\nupdate iam_sync_item_t\nset status=\'FAILED\',result_json=\'{"message":"执行中断，使用原事件重新确认"}\'\nwhere task_id=#{taskId}\n    and status=\'RUNNING\'\n""");\n        sql.update("""\nupdate iam_sync_task_t\nset status=\'RUNNING\',lease_token=#{lease},lease_until=date_add(utc_timestamp(6),interval 60 second),\n    version=version+1\nwhere tid=#{taskId}\n""");\n        return true;\n    });\n    if(!claimed) {\n        return {\n            id:taskId,status:task.status\n        };\n    }\n    var items=sql.select("""\nselect i.*,i.tid as id\nfrom iam_sync_item_t i\njoin iam_sync_config_t c on c.tid=#{task.config_id}\nwhere i.task_id=#{taskId}\n    and i.status=\'PENDING\'\n    and i.attempt_count<c.max_attempts\norder by i.sequence_no\nlimit 20\n""");\n    for(item in items) {\n        var config=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{task.config_id}\n    and is_del=0\n""");\n        var snapshot=JSONUtil.parseObj(task.config_snapshot_json);\n        if(config==null || config.enabled!=1 || config.version!=task.config_version || config.endpoint!=snapshot.endpoint || config.receiver_instance_id!=snapshot.instance) {\n            break;\n        }\n        var key=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{config.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(key==null) {\n            break;\n        }\n        var keyId=JSONUtil.parseObj(key.public_data).keyId;\n        if(keyId!=snapshot.keyId) {\n            break;\n        }\n        // 树父项、角色资源、人员任职及角色均为依赖；增量中省略的项已由同实例确认。\n        var frozen=identityTransport.parseJson(item.payload_json);\n        var references=[];\n        if(frozen.data.parentId!=null) {\n            references.add({\n                type:item.object_type,id:frozen.data.parentId\n            });\n        }\n        if(item.object_type==\'ROLE\') {\n            for(rid in frozen.data.resourceIds||[]) {\n                references.add({\n                    type:\'RESOURCE\',id:rid\n                });\n            }\n        }\n        if(item.object_type==\'SUBJECT\') {\n            for(job in frozen.data.appointments||[]) {\n                references.add({\n                    type:\'ORG\',id:job.orgId\n                });\n            }\n            for(rid in frozen.data.roleIds||[]) {\n                references.add({\n                    type:\'ROLE\',id:rid\n                });\n            }\n        }\n        var dependencies=references.map(ref=>sql.selectOne("""\nselect status,attempt_count\nfrom iam_sync_item_t\nwhere task_id=#{taskId}\n    and object_type=#{ref.type}\n    and object_id=#{ref.id}\n""")).filter(d=>d!=null);\n        if(dependencies.filter(d=>d.status==\'CONFLICT\' || d.status==\'FAILED\' && d.attempt_count>=config.max_attempts).size()>0) {\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'CONFLICT\',result_json=\'{"result":"DEPENDENCY_BLOCKED","message":"前置对象未能完成，请处理前置失败后重新预览"}\',version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n    and status in (\'PENDING\',\'FAILED\')\n""");\n            continue;\n        }\n        if(dependencies.filter(d=>![\'APPLIED\',\'DUPLICATE\'].contains(d.status)).size()>0) {\n            continue;\n        }\n        var started=System.currentTimeMillis();\n        var attempt=item.attempt_count+1;\n        var attemptId=IdUtil.fastSimpleUUID();\n        var active=sql.transaction(()=>{\n            var current=sql.selectOne("""\nselect lease_token,status\nfrom iam_sync_task_t\nwhere tid=#{taskId}\n    for update\n""");\n            if(current.lease_token!=lease || current.status!=\'RUNNING\') {\n                return false;\n            }\n            sql.update("""\nupdate iam_sync_task_t\nset lease_until=date_add(utc_timestamp(6),interval 60 second)\nwhere tid=#{taskId}\n""");\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'RUNNING\',attempt_count=attempt_count+1\nwhere tid=#{item.id}\n""");\n            sql.update("""\ninsert into iam_sync_attempt_t(tid,\n                item_id, attempt_no, credential_id, started_time, transport_status)\nvalues(#{attemptId},#{item.id},#{attempt},#{key.id},utc_timestamp(6),\'SENT\')\n""");\n            return true;\n        });\n        if(!active) {\n            break;\n        }\n        var httpStatus=null;\n        var payload=identityTransport.canonicalText(item.payload_json);\n        var ok=false;\n        var receipt=null;\n        var code=\'TRANSPORT_OR_RECEIPT_INVALID\';\n        var message=\'网络或回执校验失败\';\n        try {\n            if(DigestUtil.sha256Hex(payload)!=item.payload_hash) {\n                throw new IllegalStateException(\'冻结事件摘要不一致\');\n            }\n            // 仅在本次人工请求中向已配置接收地址发送签名事件。\n            var response=identityTransport.send2(snapshot.endpoint,key.secret_cipher,keyId,task.app_id,snapshot.instance,payload,config.timeout_seconds);\n            httpStatus=response.httpStatus;\n            receipt=response.data==null?null:response.data.receipt;\n            // 核对签名回执的事件号、版本和目标实例，成功后才确认下发结果。\n            if(response.code==0 && receipt!=null && identityTransport.verifyReceipt(key.secret_cipher,receipt,response.data.receiptSignature) && receipt.protocol==\'IDAAS/2\' && receipt.appId==task.app_id && receipt.receiverInstanceId==snapshot.instance && receipt.eventId==item.id && receipt.objectType==item.object_type && receipt.objectId==item.object_id && receipt.sourceVersion==item.source_version && receipt.payloadHash==item.payload_hash && receipt.localId!=null && receipt.localId!=\'\') {\n                code=receipt.result;\n                message=receipt.message||\'\';\n                ok=[\'APPLIED\',\'DUPLICATE\'].contains(code);\n            }\n        }\n        catch(e) {\n            receipt=null;\n        }\n        var status=ok?code:code==\'CONFLICT\' || code==\'DETACHED\' || code==\'STALE\'?\'CONFLICT\':\'FAILED\';\n        var safe=JSONUtil.toJsonStr({\n            result:code,message:message,localId:receipt==null?null:receipt.localId,sourceVersion:receipt==null?null:receipt.sourceVersion\n        });\n        var duration=System.currentTimeMillis()-started;\n        var transportStatus=ok?\'ACKNOWLEDGED\':\'REJECTED\';\n        sql.transaction(()=>{\n            sql.update("""\nupdate iam_sync_attempt_t\nset finished_time=utc_timestamp(6),transport_status=#{transportStatus},http_status=#{httpStatus},\n    result_code=#{code},safe_message=#{message},duration_ms=#{duration}\nwhere tid=#{attemptId}\n""");\n            sql.update("""\nupdate iam_sync_item_t\nset status=#{status},result_json=#{safe},version=version+1,\n        next_retry_time=null,\n        updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n            if(ok) {\n                var link=sql.selectOne("""\nselect *,tid as id\nfrom iam_external_link_t\nwhere app_id=#{task.app_id}\n    and object_type=#{item.object_type}\n    and source_id=#{item.object_id}\n    for update\n""");\n                if(link!=null && (link.receiver_instance_id!=snapshot.instance || link.local_id!=receipt.localId)) {\n                    sql.update("""\nupdate iam_sync_item_t\nset status=\'CONFLICT\',result_json=\'{"message":"接收实例或本地映射不一致"}\'\nwhere tid=#{item.id}\n""");\n                }\n                else {\n                    var lid=link==null?IdUtil.fastSimpleUUID():link.id;\n                    if(link==null) {\n                        sql.update("""\ninsert into iam_external_link_t(tid,\n                app_id, receiver_instance_id, object_type, source_id, local_id, ack_version, ack_hash,\n                last_ack_time)\nvalues(#{lid},#{task.app_id},#{snapshot.instance},#{item.object_type},#{item.object_id},#{receipt.localId},#{item.source_version},#{receipt.stateHash},utc_timestamp(6))\n""");\n                    }\n                    else if(item.source_version>=link.ack_version) {\n                        sql.update("""\nupdate iam_external_link_t\nset ack_version=#{item.source_version},ack_hash=#{receipt.stateHash},last_ack_time=utc_timestamp(6),version=version+1\nwhere tid=#{lid}\n""");\n                    }\n                    if(item.object_type==\'SUBJECT\') {\n                        sql.update("""\nupdate iam_subject_app_t\nset ack_version=greatest(ack_version, #{item.source_version}),sync_status=case\n        when desired_version<=#{item.source_version} then \'IN_SYNC\' else \'PENDING\'\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere app_id=#{task.app_id}\n    and subject_id=#{item.object_id}\n""");\n                    }\n                }\n            }\n            else if(item.object_type==\'SUBJECT\') {\n                var syncStatus=status==\'CONFLICT\'?\'CONFLICT\':\'FAILED\';\n                sql.update("""\nupdate iam_subject_app_t\nset sync_status=#{syncStatus},version=version+1\nwhere app_id=#{task.app_id}\n    and subject_id=#{item.object_id}\n""");\n            }\n        });\n    }\n    return sql.transaction(()=>{\n        var counts=sql.selectOne("""\nselect sum(status in (\'APPLIED\', \'DUPLICATE\')) success,sum(status in (\'FAILED\',\n        \'CONFLICT\')) failure,sum(status in (\'PENDING\',\n\n        \'RUNNING\')) pending\nfrom iam_sync_item_t\nwhere task_id=#{taskId}\n""");\n        var status=counts.pending>0?\'PENDING\':counts.failure>0?counts.success>0?\'PARTIAL\':\'FAILED\':\'SUCCEEDED\';\n        sql.update("""\nupdate iam_sync_task_t\nset status=#{status},success_count=#{counts.success},failure_count=#{counts.failure},lease_token=null,\n    lease_until=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{taskId}\n    and lease_token=#{lease}\n""");\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,status==\'SUCCEEDED\'?\'SUCCESS\':\'FAILED\',\'sync:execute\',taskId,status,{\n            id:taskId,success:counts.success,failure:counts.failure\n        });\n        return {\n            id:taskId,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/07.执行手动下发任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('97e8719ec9f84894a21fd011c8e32e60',NULL,'api','{\n  "properties": {},\n  "id": "e5386a37bfe154c8b5735fab907f40e2",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "08.轮换下发接入凭据",\n  "createTime": 1790618621046,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/rotate",\n  "description": "校验目标应用权限并生成新接入凭据，更新控制库配置及生效版本，旧凭据按策略失效。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：08.轮换下发接入凭据\n// 路由：POST /idaas/provision/rotate\n// 业务说明：校验目标应用权限并生成新接入凭据，更新控制库配置及生效版本，旧凭据按策略失效。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'rotate\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var id=p.configId||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?p.appId||p.targetTenantId:old.app_id;\n    var permission=operation==\'configs\' || operation==\'options\'?\'sync:read\':\'sync:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'configs\' || operation==\'options\'?listContext(permission,appId,\'workforce\'):guard(permission,appId,\'workforce\');\n    var visible=x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==\'workforce\' && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x)).size()>0).size()>0;\n    if(old==null && operation!=\'save-config\') {\n        exit 404,\'接收配置不存在\';\n    }\n    // 在事务内完成校验与写入；重复请求及并发版本冲突由共享事务规则处理。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_config_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(operation!=\'save-config\' && operation!=\'rotate\') {\n            exit 400,\'配置操作不正确\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && old.version!=p.version) {\n            exit 409,\'配置版本已变更\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'只能配置业务应用\';\n        }\n        var keyId=p.keyId;\n        var secret=p.secret;\n        var key=old==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n        if(keyId==null && key!=null) {\n            keyId=JSONUtil.parseObj(key.public_data).keyId;\n        }\n        if(keyId==null || !keyId.matches(\'[A-Za-z0-9_-]{3,64}\')) {\n            exit 400,\'密钥标识不正确\';\n        }\n        if(operation==\'rotate\') {\n            if(secret==null || secret==\'\') {\n                exit 400,\'轮换密钥不能为空\';\n            }\n            sql.update("""\nupdate iam_sync_config_t\nset enabled=0,last_test_result=null,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=\'OFF\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        else {\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var instance=p.receiverInstanceId;\n            var name=(p.name||\'接收配置\').trim();\n            var timeout=p.timeout||10;\n            if(instance==null || !instance.matches(\'[A-Za-z0-9_.-]{3,100}\') || name==\'\' || name.length()>100 || timeout<1 || timeout>30 || p.mapping!=null && p.mapping!=\'{}\') {\n                exit 400,\'实例、名称、超时或映射配置不正确\';\n            }\n            var enabled=p.enabled==true?1:0;\n            var changed=old==null || old.endpoint!=endpoint || old.receiver_instance_id!=instance || secret!=null && secret!=\'\';\n            if(enabled==1 && (changed || old.last_test_result!=\'SUCCESS\')) {\n                exit 409,\'请先保存关闭状态并测试接收实例，再启用\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_sync_config_t\nwhere app_id=#{appId}\n""")!=null) {\n                    exit 409,\'应用已有接收配置，请使用原配置修改\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_sync_config_t(tid,\n                app_id, display_name, endpoint, protocol_version, receiver_instance_id, timeout_seconds,\n                object_types, enabled)\nvalues(#{id},#{appId},#{name},#{endpoint},\'IDAAS/2\',#{instance},#{timeout},\'["ORG","RESOURCE","ROLE","SUBJECT"]\',#{enabled})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_sync_config_t\nset display_name=#{name},endpoint=#{endpoint},receiver_instance_id=#{instance},\n    timeout_seconds=#{timeout},enabled=#{enabled},last_test_result=case\n        when #{changed} then null\n        else last_test_result\n        end,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var mode=enabled==1?\'HTTP\':\'OFF\';\n            sql.update("""\nupdate iam_application_t\nset provisioning_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n        }\n        if(secret!=null && secret!=\'\') {\n            var cipher=identityTransport.encrypt(secret);\n            var revision=key==null?1:key.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\',version=version+1\nwhere owner_kind=\'SYNC_CONFIG\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n            var kid=IdUtil.fastSimpleUUID();\n            var data=JSONUtil.toJsonStr({\n                keyId:keyId\n            });\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, slot, revision, algorithm, secret_cipher, public_data,\n                status)\nvalues(#{kid},\'SYNC_CONFIG\',#{id},\'HMAC_KEY\',\'primary\',#{revision},\'HMAC_SHA256_AES256_GCM\',#{cipher},#{data},\'ACTIVE\')\n""");\n        }\n        else if(key==null) {\n            exit 400,\'接入密钥不能为空\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/08.轮换下发接入凭据.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f9f95ac48c504f4982971abba618889c',NULL,'api','{\n  "properties": {},\n  "id": "7b1d8aae55725bdda939675bd29b2c2a",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "09.取消下发任务",\n  "createTime": 1790618621046,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/cancel",\n  "description": "校验任务所属应用及当前状态，取消尚未完成的手动下发任务并记录操作者。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：09.取消下发任务\n// 路由：POST /idaas/provision/cancel\n// 业务说明：校验任务所属应用及当前状态，取消尚未完成的手动下发任务并记录操作者。\nimport db;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'cancel\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var task=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n""");\n    if(task==null) {\n        exit 404,\'任务不存在\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'sync:execute\',task.app_id,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(current.version!=p.version) {\n            exit 409,\'任务版本已变更\';\n        }\n        if(operation==\'cancel\') {\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'CANCELED\',version=version+1\nwhere tid=#{p.id}\n""");\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'CANCELED\'\nwhere task_id=#{p.id}\n    and status in (\'PENDING\',\'FAILED\',\'CONFLICT\')\n""");\n        }\n        else if(operation==\'retry\') {\n            if(current.status==\'CANCELED\') {\n                exit 409,\'已取消的任务须重新预览\';\n            }\n            if(sql.selectOne("""\nselect i.tid as id\nfrom iam_sync_item_t i\njoin iam_sync_config_t c on c.tid=#{current.config_id}\nwhere i.task_id=#{p.id}\n    and i.status in (\'FAILED\',\'CONFLICT\')\n    and i.attempt_count>=c.max_attempts\nlimit 1\n""")!=null) {\n                exit 409,\'已达尝试上限，请修正原因并重新预览创建任务\';\n            }\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'PENDING\',next_retry_time=null\nwhere task_id=#{p.id}\n    and status in (\'FAILED\',\'CONFLICT\')\n""");\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'PENDING\',version=version+1\nwhere tid=#{p.id}\n""");\n        }\n        else {\n            exit 400,\'任务操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,p.id,null,{\n            id:p.id\n        });\n        return {\n            id:p.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/09.取消下发任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('033a341f797d45458eb1a683bb7417d2',NULL,'api','{\n  "properties": {},\n  "id": "bdadee3c54325c0c8c04c28dc02c0281",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "10.重试下发任务",\n  "createTime": 1790618621046,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/retry",\n  "description": "校验失败任务及应用权限，重新准备可重试下发步骤；由本次请求触发，不创建自动轮询。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：10.重试下发任务\n// 路由：POST /idaas/provision/retry\n// 业务说明：校验失败任务及应用权限，重新准备可重试下发步骤；由本次请求触发，不创建自动轮询。\nimport db;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/app-list-context\' as listContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'retry\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var task=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n""");\n    if(task==null) {\n        exit 404,\'任务不存在\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'sync:execute\',task.app_id,\'workforce\');\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'sync:\'+operation,p,()=>{\n        var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_sync_task_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(current.version!=p.version) {\n            exit 409,\'任务版本已变更\';\n        }\n        if(operation==\'cancel\') {\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'CANCELED\',version=version+1\nwhere tid=#{p.id}\n""");\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'CANCELED\'\nwhere task_id=#{p.id}\n    and status in (\'PENDING\',\'FAILED\',\'CONFLICT\')\n""");\n        }\n        else if(operation==\'retry\') {\n            if(current.status==\'CANCELED\') {\n                exit 409,\'已取消的任务须重新预览\';\n            }\n            if(sql.selectOne("""\nselect i.tid as id\nfrom iam_sync_item_t i\njoin iam_sync_config_t c on c.tid=#{current.config_id}\nwhere i.task_id=#{p.id}\n    and i.status in (\'FAILED\',\'CONFLICT\')\n    and i.attempt_count>=c.max_attempts\nlimit 1\n""")!=null) {\n                exit 409,\'已达尝试上限，请修正原因并重新预览创建任务\';\n            }\n            sql.update("""\nupdate iam_sync_item_t\nset status=\'PENDING\',next_retry_time=null\nwhere task_id=#{p.id}\n    and status in (\'FAILED\',\'CONFLICT\')\n""");\n            sql.update("""\nupdate iam_sync_task_t\nset status=\'PENDING\',version=version+1\nwhere tid=#{p.id}\n""");\n        }\n        else {\n            exit 400,\'任务操作不正确\';\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'sync:\'+operation,p.id,null,{\n            id:p.id\n        });\n        return {\n            id:p.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/10.重试下发任务.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4075121696d141b3b46f6f314d8f2803',NULL,'api','{\n  "properties": {},\n  "id": "43af23446f825dd09c5c88784e8d0425",\n  "script": null,\n  "groupId": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "11.分页查询可下发对象",\n  "createTime": 1791193400395,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/objects",\n  "description": "按目标应用和 sync:write 权限分页列出中央人员或机构，供手动下发选择。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：按应用和当前操作人权限分页查询可手动下发的对象\n// 路由：GET /idaas/provision/objects\nimport db;\nimport identityRuntime;\nimport request;\nimport java.lang.Long;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/context\' as context;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var param=(key,fallback)=>{\n        var values=request.getValues(key);\n        return values==null || values.size()==0?fallback:values[0];\n    };\n    var configId=param(\'configId\',null);\n    var kind=param(\'kind\',null);\n    var pageText=param(\'page\',\'1\');\n    var sizeText=param(\'size\',\'20\');\n    var q=(param(\'q\',\'\')||\'\').trim();\n    if(configId==null || ![\'user\',\'org\'].contains(kind) || q.length()>100\n        || !pageText.matches(\'[0-9]{1,5}\') || !sizeText.matches(\'[0-9]{1,3}\')) {\n        exit 400,\'对象查询参数不正确\';\n    }\n    var page=Long.parseLong(pageText);\n    var size=Long.parseLong(sizeText);\n    if(page<1 || size<1 || size>100) {\n        exit 400,\'分页范围不正确\';\n    }\n    var sql=db.normal();\n    context();\n    var config=sql.selectOne("""\nselect app_id from iam_sync_config_t\nwhere tid=#{configId} and is_del=0\n""");\n    if(config==null) {\n        exit 404,\'下发配置不存在\';\n    }\n    var appId=config.app_id;\n    guard(\'sync:write\',appId,\'workforce\');\n    var keyword=\'%\'+q+\'%\';\n    var offset=(page-1)*size;\n    var filter=kind==\'user\'?"""\nfrom iam_subject_app_t sa\njoin iam_subject_t t on t.tid=sa.subject_id\nwhere sa.app_id=#{appId} and t.identity_domain=\'workforce\' and t.is_del=0\n  and (t.name like #{keyword} or t.account_hint like #{keyword})\n""":"""\nfrom iam_org_t t\nwhere t.identity_domain=\'workforce\' and t.is_del=0 and t.name like #{keyword}\n  and exists (\n    select 1 from iam_app_org_t ao\n    join iam_org_t root on root.tid=ao.org_id\n    where ao.app_id=#{appId} and ao.status=\'ACTIVE\'\n      and (t.tid=root.tid or (ao.include_children=1 and t.path like concat(root.path,\'%\')))\n  )\n""";\n    var total=sql.selectOne(\'select count(*) total \'+filter).total;\n    var rows=sql.select("""\nselect t.tid as id,t.name,t.version,t.status,\n  """+(kind==\'user\'?\'t.account_hint as account\':\'t.code\')+"""\n"""+filter+" order by t.tid limit #{size} offset #{offset}");\n    return {list:rows.map(row=>({\n        id:row.id,name:row.name,version:row.version,\n        status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',\n        account:kind==\'user\'?row.account:null,code:kind==\'org\'?row.code:null\n    })),total:total,page:page,size:size};\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/11.分页查询可下发对象.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5491e73333154a99b8357b61f5f6babd',NULL,NULL,'{\n  "properties": {},\n  "id": "07899fe85f4d59fd90de0507c7f4d188",\n  "name": "13.标准下发",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/provision",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/13.标准下发/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b44f206f46774faa9de1a5e1cc9ed1bd',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/14.人员身份资料/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7da56c4a95b041a3a62de9b2d7a93d97',NULL,'api','{\n  "properties": {},\n  "id": "a52a5aa316e35c7783ce6820cdfa9435",\n  "script": null,\n  "groupId": "7594148e987057f087c5dca083c0c93c",\n  "name": "01.查询人员身份资料列表",\n  "createTime": 1790615423659,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的人员身份资料，应用权限及身份域过滤后返回可展示字段；不发生写入。处理控制库的中央人员身份资料及版本，遵守身份域和机构范围，不生成租户本地密码。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：查询中央人员列表\n// 路由：GET /idaas/subjects/list\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory\' as directory;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'status\',\'orgId\',\'includeChildren\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    return directory(\'subjects\',\'list\',payload);\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/14.人员身份资料/01.查询人员身份资料列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('34458919089a4e42b2416d20a0dadbf4',NULL,'api','{\n  "properties": {},\n  "id": "9746931c9b6d5596b88f1734394651c6",\n  "script": null,\n  "groupId": "7594148e987057f087c5dca083c0c93c",\n  "name": "02.保存人员身份资料",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新人员身份资料及必要关联记录，写入审计并返回保存结果。处理控制库的中央人员身份资料及版本，遵守身份域和机构范围，不生成租户本地密码。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存人员身份资料\n// 路由：POST /idaas/subjects/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新人员身份资料及必要关联记录，写入审计并返回保存结果。处理控制库的中央人员身份资料及版本，遵守身份域和机构范围，不生成租户本地密码。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'subjects\';\n    var operation = \'save\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/14.人员身份资料/02.保存人员身份资料.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bb5b3bb083434b47a77d636364c2fc2c',NULL,'api','{\n  "properties": {},\n  "id": "e1f81966156f5ce884e1557169504b73",\n  "script": null,\n  "groupId": "7594148e987057f087c5dca083c0c93c",\n  "name": "03.归档人员身份资料",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载人员身份资料并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央人员身份资料及版本，遵守身份域和机构范围，不生成租户本地密码。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档人员身份资料\n// 路由：POST /idaas/subjects/remove\n// 业务说明：按标识加载人员身份资料并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。处理控制库的中央人员身份资料及版本，遵守身份域和机构范围，不生成租户本地密码。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'subjects\';\n    var operation = \'remove\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/14.人员身份资料/03.归档人员身份资料.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3156189003b441959991bbb4c085bd54',NULL,NULL,'{\n  "properties": {},\n  "id": "7594148e987057f087c5dca083c0c93c",\n  "name": "14.人员身份资料",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/subjects",\n  "createTime": 1790615423659,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/14.人员身份资料/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6118d72da2cc47b6a188b7fe4bead626',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/15.目录字典/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6a481ed6a88842bb95e5a793695d0d93',NULL,'api','{\n  "properties": {},\n  "id": "ccb4cb6bb5d35676b5fbf1e2be84e427",\n  "script": null,\n  "groupId": "60b5f490ea45578aa23c7d583cb788ce",\n  "name": "01.查询目录字典列表",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的目录字典，应用权限及身份域过滤后返回可展示字段；不发生写入。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询目录字典列表\n// 路由：GET /idaas/dictionaries/list\n// 业务说明：读取符合请求筛选条件的目录字典，应用权限及身份域过滤后返回可展示字段；不发生写入。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'appId\',\'subjectId\',\'category\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var entity = \'dictionaries\';\n    var operation = \'list\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    if(operation==\'list\') {\n        var rows=sql.select(\'select *,tid as id,date_format(created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+\' where identity_domain=#{domain} and is_del=0 order by tid\');\n        return rows.map(x=>({\n            id:x.id,domain:x.identity_domain,name:fields?x.label:x.name,code:fields?x.field_key:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,category:fields?\'extension\':x.category==\'LINE\'?\'line\':\'dictionary\',value:fields?x.value_type:x.category,parentId:fields?\'\':x.parent_id||\'\',subjectType:fields?x.entity_type:\'\',required:fields?x.required_flag==1:false,sensitive:fields?x.sensitive_flag==1:false,validation:fields && x.validation_json!=null?JSONUtil.parseObj(x.validation_json):{},description:\'\',permissions:[],memberIds:[],appId:\'\',orgId:\'\',userId:\'\',expiresAt:\'\'\n        }));\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/15.目录字典/01.查询目录字典列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('965fb491e17344a3a9cf8921e4b6ce91',NULL,'api','{\n  "properties": {},\n  "id": "e2e6dfb77ad95241aba08dd2a4c3fb53",\n  "script": null,\n  "groupId": "60b5f490ea45578aa23c7d583cb788ce",\n  "name": "02.保存目录字典",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新目录字典及必要关联记录，写入审计并返回保存结果。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存目录字典\n// 路由：POST /idaas/dictionaries/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新目录字典及必要关联记录，写入审计并返回保存结果。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'dictionaries\';\n    var operation = \'save\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/15.目录字典/02.保存目录字典.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7274eddd4bfb4418aeed42cd2d057fb0',NULL,'api','{\n  "properties": {},\n  "id": "a3821384bf4151ce85fdb396aa898d9b",\n  "script": null,\n  "groupId": "60b5f490ea45578aa23c7d583cb788ce",\n  "name": "03.归档目录字典",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载目录字典并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档目录字典\n// 路由：POST /idaas/dictionaries/remove\n// 业务说明：按标识加载目录字典并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。仅接受目录字典允许的字段与值；写入控制库并校验版本，不允许传入任意 SQL 或表名。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'dictionaries\';\n    var operation = \'remove\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/15.目录字典/03.归档目录字典.ms');
