INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d75161dce1444782a688325ead428595',NULL,'api','{\n  "properties": {},\n  "id": "58bdf890d5e25cfa86912ce20f1a12e6",\n  "script": null,\n  "groupId": "d2672fef1964556f8f5fcdc1f380d090",\n  "name": "01.查询扩展字段定义列表",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的扩展字段定义，应用权限及身份域过滤后返回可展示字段；不发生写入。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询扩展字段定义列表\n// 路由：GET /idaas/field-definitions/list\n// 业务说明：读取符合请求筛选条件的扩展字段定义，应用权限及身份域过滤后返回可展示字段；不发生写入。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'appId\',\'subjectId\',\'category\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var entity = \'field-definitions\';\n    var operation = \'list\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    if(operation==\'list\') {\n        var rows=sql.select(\'select *,tid as id,date_format(created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+\' where identity_domain=#{domain} and is_del=0 order by tid\');\n        return rows.map(x=>({\n            id:x.id,domain:x.identity_domain,name:fields?x.label:x.name,code:fields?x.field_key:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,category:fields?\'extension\':x.category==\'LINE\'?\'line\':\'dictionary\',value:fields?x.value_type:x.category,parentId:fields?\'\':x.parent_id||\'\',subjectType:fields?x.entity_type:\'\',required:fields?x.required_flag==1:false,sensitive:fields?x.sensitive_flag==1:false,validation:fields && x.validation_json!=null?JSONUtil.parseObj(x.validation_json):{},description:\'\',permissions:[],memberIds:[],appId:\'\',orgId:\'\',userId:\'\',expiresAt:\'\'\n        }));\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/16.扩展字段定义/01.查询扩展字段定义列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0d618d3163ed4c6ebf7e017f23f0aa01',NULL,'api','{\n  "properties": {},\n  "id": "419dd6a6040c519c83df3583bad95aa2",\n  "script": null,\n  "groupId": "d2672fef1964556f8f5fcdc1f380d090",\n  "name": "02.保存扩展字段定义",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新扩展字段定义及必要关联记录，写入审计并返回保存结果。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存扩展字段定义\n// 路由：POST /idaas/field-definitions/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新扩展字段定义及必要关联记录，写入审计并返回保存结果。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'field-definitions\';\n    var operation = \'save\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/16.扩展字段定义/02.保存扩展字段定义.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2ba12965514f457e89f43406d7169172',NULL,'api','{\n  "properties": {},\n  "id": "7b835c29c6115af8a691831c8fb631df",\n  "script": null,\n  "groupId": "d2672fef1964556f8f5fcdc1f380d090",\n  "name": "03.归档扩展字段定义",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载扩展字段定义并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档扩展字段定义\n// 路由：POST /idaas/field-definitions/remove\n// 业务说明：按标识加载扩展字段定义并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只维护白名单内的人员或机构扩展字段定义；校验字段类型与版本，并保护保留字段。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'field-definitions\';\n    var operation = \'remove\';\n\n    // 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n        exit 400,\'配置类型不正确\';\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\n    var fields=entity==\'field-definitions\';\n    var table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'配置不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'配置身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            if(!fields) {\n                var code=old.code;\n                var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n                if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'字典仍被资料或下级引用\';\n                }\n            }\n            else {\n                if(old.entity_type==\'APPLICATION\') {\n                    exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n                }\n                var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var jsonPath=\'$.\'+old.field_key;\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                    exit 409,\'扩展字段已有数据，请先迁移或停用\';\n                }\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=(fields?old.field_key:old.code)) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(fields) {\n            var typeMap={\n                用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n            };\n            var valueMap={\n                文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n            };\n            var entityType=typeMap.get(r.subjectType)||r.subjectType;\n            var valueType=valueMap.get(r.value)||r.value;\n            if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n                exit 400,\'扩展对象、类型或字段键不允许\';\n            }\n            if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n                exit 409,\'已有字段类型和对象保持稳定\';\n            }\n            var validation=r.validation||{};\n            for(k in validation.keySet()) {\n                if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                    exit 400,\'校验规则不允许\';\n                }\n            }\n            if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n                exit 400,\'文本长度须为1至4096的整数\';\n            }\n            for(k in [\'min\',\'max\']) {\n                var value=validation.get(k);\n                if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                    exit 400,\'数值边界须为有限数字\';\n                }\n            }\n            if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n                exit 400,\'数值范围不正确\';\n            }\n            if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n                exit 400,\'枚举选项须为文本\';\n            }\n            if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n                exit 400,\'枚举字段需要1至100项选项\';\n            }\n            var encoded=JSONUtil.toJsonStr(validation);\n            var required=r.required==true?1:0;\n            var sensitive=r.sensitive==true?1:0;\n            if(sensitive==1 && validation.containsKey(\'default\')) {\n                exit 400,\'敏感字段不能在配置中保存默认值\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                    exit 409,\'字段键已使用\';\n                }\n                if(required==1 && !validation.containsKey(\'default\')) {\n                    var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                    if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                        exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                    }\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(status==\'ACTIVE\') {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n                for(item in records) {\n                    var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                    var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                    var text=JSONUtil.toJsonStr(adjusted);\n                    if(text!=JSONUtil.toJsonStr(existing)) {\n                        sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                    }\n                }\n            }\n        }\n        else {\n            var kindMap={\n                岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n            };\n            var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n            if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n                exit 400,\'字典类型不正确\';\n            }\n            if(old!=null && category!=old.category) {\n                exit 400,\'字典类型保持稳定\';\n            }\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'父字典无效\';\n            }\n            var visited=[id];\n            var cursor=parent;\n            while(cursor!=null) {\n                if(visited.contains(cursor.id)) {\n                    exit 400,\'字典层级不能循环\';\n                }\n                visited.add(cursor.id);\n                var next=cursor.parent_id;\n                cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                    exit 409,\'字典编码已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/16.扩展字段定义/03.归档扩展字段定义.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5add55ba41de407bbfd6004ef85d40cb',NULL,NULL,'{\n  "properties": {},\n  "id": "d2672fef1964556f8f5fcdc1f380d090",\n  "name": "16.扩展字段定义",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/field-definitions",\n  "createTime": 1790615423659,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/16.扩展字段定义/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('66bbb5eee75d4c12a13dcd201de670a4',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/17.应用资料分配/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('40155c8e7414425aacc4f2b5d9b9d70f',NULL,'api','{\n  "properties": {},\n  "id": "3bb4ca383d1e58e6971c458ef78eb6b8",\n  "script": null,\n  "groupId": "58dc0d18e4185b67bf18980e9a47e878",\n  "name": "01.查询应用人员资料分配列表",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用人员资料分配，应用权限及身份域过滤后返回可展示字段；不发生写入。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用人员资料分配列表\n// 路由：GET /idaas/assignments/list\n// 业务说明：读取符合请求筛选条件的应用人员资料分配，应用权限及身份域过滤后返回可展示字段；不发生写入。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'appId\',\'subjectId\',\'category\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 人员/机构资料分配与访问授权独立。未得到接收回执不得写ack_version。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var appId=r.appId||p.appId;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'assignments:read\':\'assignments:write\',appId,domain);\n    var app=sql.selectOne("""\nselect tid as id,identity_domains\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n    if(app==null) {\n        exit 400,\'有效业务应用不存在\';\n    }\n    if(!JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n        exit 400,\'应用尚未支持该身份域\';\n    }\n    if(operation==\'list\') {\n        return {\n            subjects:sql.select("""\nselect sa.*,sa.tid as id,s.name,s.identity_domain\nfrom iam_subject_app_t sa\njoin iam_subject_t s on s.tid=sa.subject_id\nwhere app_id=#{appId}\n    and s.identity_domain=#{domain}\n"""),orgs:sql.select("""\nselect ao.*,ao.tid as id,o.name,o.identity_domain\nfrom iam_app_org_t ao\njoin iam_org_t o on o.tid=ao.org_id\nwhere app_id=#{appId}\n    and o.identity_domain=#{domain}\n""")\n        };\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'assignments:\'+operation,p,()=>{\n        var type=r.type||\'subject\';\n        if(![\'org\',\'subject\'].contains(type)) {\n            exit 400,\'分配类型不正确\';\n        }\n        var id=r.id;\n        var table=type==\'org\'?\'iam_app_org_t\':\'iam_subject_app_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} for update\');\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=appId || old.version!=r.version)) {\n            exit 409,\'分配归属或版本已变更\';\n        }\n        var objectId=type==\'org\'?r.orgId:r.subjectId;\n        var objectTable=type==\'org\'?\'iam_org_t\':\'iam_subject_t\';\n        var object=sql.selectOne(\'select tid as id,status from \'+objectTable+\' where tid=#{objectId} and identity_domain=#{domain} and is_del=0\');\n        if(object==null || (operation!=\'remove\' && object.status!=\'ACTIVE\')) {\n            exit 400,\'同域有效资料不存在\';\n        }\n        if(old==null) {\n            old=sql.selectOne(\'select *,tid as id from \'+table+\' where app_id=#{appId} and \'+(type==\'org\'?\'org_id\':\'subject_id\')+\'=#{objectId} for update\');\n            if(old!=null) {\n                exit 409,\'已有分配请使用原ID及版本\';\n            }\n        }\n        if(operation==\'remove\' && old==null) {\n            exit 404,\'分配不存在\';\n        }\n        if(old!=null && (type==\'org\'?old.org_id:old.subject_id)!=objectId) {\n            exit 400,\'分配对象保持稳定\';\n        }\n        if(type==\'org\') {\n            var status=operation==\'remove\'?\'REVOKED\':\'ACTIVE\';\n            var include=r.includeChildren==true?1:0;\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_app_org_t(tid, app_id, org_id, include_children, status)\nvalues(#{id},#{appId},#{objectId},#{include},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_app_org_t\nset include_children=#{include},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            var alias=(r.accountAlias||\'\').trim();\n            if(alias!=\'\' && !alias.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\')) {\n                exit 400,\'应用拟用账号不正确\';\n            }\n            var assigned=operation==\'remove\'?0:1;\n            var mode=old==null?\'DIRECTORY_ONLY\':old.assignment_mode;\n            var status=assigned==1 || mode==\'GRANT_DERIVED\'?\'ACTIVE\':\'REVOKED\';\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_app_t(tid,\n                subject_id, app_id, account_alias, directory_assigned, assignment_mode, assignment_status,\n                desired_enabled, sync_status)\nvalues(#{id},#{objectId},#{appId},#{alias},#{assigned},\'DIRECTORY_ONLY\',#{status},0,\'NOT_CONNECTED\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_app_t\nset account_alias=#{alias},directory_assigned=#{assigned},assignment_status=#{status},\n    desired_version=desired_version+1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'assignments:\'+operation,id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/17.应用资料分配/01.查询应用人员资料分配列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8e7e5884ea6d4fcea5c6e624381eb904',NULL,'api','{\n  "properties": {},\n  "id": "6f389c31a29c5cbea2ee5f94acdc70ec",\n  "script": null,\n  "groupId": "58dc0d18e4185b67bf18980e9a47e878",\n  "name": "02.保存应用人员资料分配",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用人员资料分配及必要关联记录，写入审计并返回保存结果。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用人员资料分配\n// 路由：POST /idaas/assignments/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用人员资料分配及必要关联记录，写入审计并返回保存结果。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n\n    // 人员/机构资料分配与访问授权独立。未得到接收回执不得写ack_version。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var appId=r.appId||p.appId;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'assignments:read\':\'assignments:write\',appId,domain);\n    var app=sql.selectOne("""\nselect tid as id,identity_domains\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n    if(app==null) {\n        exit 400,\'有效业务应用不存在\';\n    }\n    if(!JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n        exit 400,\'应用尚未支持该身份域\';\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'assignments:\'+operation,p,()=>{\n        var type=r.type||\'subject\';\n        if(![\'org\',\'subject\'].contains(type)) {\n            exit 400,\'分配类型不正确\';\n        }\n        var id=r.id;\n        var table=type==\'org\'?\'iam_app_org_t\':\'iam_subject_app_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} for update\');\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=appId || old.version!=r.version)) {\n            exit 409,\'分配归属或版本已变更\';\n        }\n        var objectId=type==\'org\'?r.orgId:r.subjectId;\n        var objectTable=type==\'org\'?\'iam_org_t\':\'iam_subject_t\';\n        var object=sql.selectOne(\'select tid as id,status from \'+objectTable+\' where tid=#{objectId} and identity_domain=#{domain} and is_del=0\');\n        if(object==null || (operation!=\'remove\' && object.status!=\'ACTIVE\')) {\n            exit 400,\'同域有效资料不存在\';\n        }\n        if(old==null) {\n            old=sql.selectOne(\'select *,tid as id from \'+table+\' where app_id=#{appId} and \'+(type==\'org\'?\'org_id\':\'subject_id\')+\'=#{objectId} for update\');\n            if(old!=null) {\n                exit 409,\'已有分配请使用原ID及版本\';\n            }\n        }\n        if(operation==\'remove\' && old==null) {\n            exit 404,\'分配不存在\';\n        }\n        if(old!=null && (type==\'org\'?old.org_id:old.subject_id)!=objectId) {\n            exit 400,\'分配对象保持稳定\';\n        }\n        if(type==\'org\') {\n            var status=operation==\'remove\'?\'REVOKED\':\'ACTIVE\';\n            var include=r.includeChildren==true?1:0;\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_app_org_t(tid, app_id, org_id, include_children, status)\nvalues(#{id},#{appId},#{objectId},#{include},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_app_org_t\nset include_children=#{include},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            var alias=(r.accountAlias||\'\').trim();\n            if(alias!=\'\' && !alias.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\')) {\n                exit 400,\'应用拟用账号不正确\';\n            }\n            var assigned=operation==\'remove\'?0:1;\n            var mode=old==null?\'DIRECTORY_ONLY\':old.assignment_mode;\n            var status=assigned==1 || mode==\'GRANT_DERIVED\'?\'ACTIVE\':\'REVOKED\';\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_app_t(tid,\n                subject_id, app_id, account_alias, directory_assigned, assignment_mode, assignment_status,\n                desired_enabled, sync_status)\nvalues(#{id},#{objectId},#{appId},#{alias},#{assigned},\'DIRECTORY_ONLY\',#{status},0,\'NOT_CONNECTED\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_app_t\nset account_alias=#{alias},directory_assigned=#{assigned},assignment_status=#{status},\n    desired_version=desired_version+1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'assignments:\'+operation,id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/17.应用资料分配/02.保存应用人员资料分配.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ba9e1879ced84ea182f925c75840d755',NULL,'api','{\n  "properties": {},\n  "id": "130e0dc6612c5250b7abfd777d1fd1be",\n  "script": null,\n  "groupId": "58dc0d18e4185b67bf18980e9a47e878",\n  "name": "03.归档应用人员资料分配",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用人员资料分配并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用人员资料分配\n// 路由：POST /idaas/assignments/remove\n// 业务说明：按标识加载应用人员资料分配并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。管理中央人员资料与指定应用的分配关系；资料分配和访问授权分别维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n\n    // 人员/机构资料分配与访问授权独立。未得到接收回执不得写ack_version。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var appId=r.appId||p.appId;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'assignments:read\':\'assignments:write\',appId,domain);\n    var app=sql.selectOne("""\nselect tid as id,identity_domains\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n    if(app==null) {\n        exit 400,\'有效业务应用不存在\';\n    }\n    if(!JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n        exit 400,\'应用尚未支持该身份域\';\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'assignments:\'+operation,p,()=>{\n        var type=r.type||\'subject\';\n        if(![\'org\',\'subject\'].contains(type)) {\n            exit 400,\'分配类型不正确\';\n        }\n        var id=r.id;\n        var table=type==\'org\'?\'iam_app_org_t\':\'iam_subject_app_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} for update\');\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=appId || old.version!=r.version)) {\n            exit 409,\'分配归属或版本已变更\';\n        }\n        var objectId=type==\'org\'?r.orgId:r.subjectId;\n        var objectTable=type==\'org\'?\'iam_org_t\':\'iam_subject_t\';\n        var object=sql.selectOne(\'select tid as id,status from \'+objectTable+\' where tid=#{objectId} and identity_domain=#{domain} and is_del=0\');\n        if(object==null || (operation!=\'remove\' && object.status!=\'ACTIVE\')) {\n            exit 400,\'同域有效资料不存在\';\n        }\n        if(old==null) {\n            old=sql.selectOne(\'select *,tid as id from \'+table+\' where app_id=#{appId} and \'+(type==\'org\'?\'org_id\':\'subject_id\')+\'=#{objectId} for update\');\n            if(old!=null) {\n                exit 409,\'已有分配请使用原ID及版本\';\n            }\n        }\n        if(operation==\'remove\' && old==null) {\n            exit 404,\'分配不存在\';\n        }\n        if(old!=null && (type==\'org\'?old.org_id:old.subject_id)!=objectId) {\n            exit 400,\'分配对象保持稳定\';\n        }\n        if(type==\'org\') {\n            var status=operation==\'remove\'?\'REVOKED\':\'ACTIVE\';\n            var include=r.includeChildren==true?1:0;\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_app_org_t(tid, app_id, org_id, include_children, status)\nvalues(#{id},#{appId},#{objectId},#{include},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_app_org_t\nset include_children=#{include},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            var alias=(r.accountAlias||\'\').trim();\n            if(alias!=\'\' && !alias.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\')) {\n                exit 400,\'应用拟用账号不正确\';\n            }\n            var assigned=operation==\'remove\'?0:1;\n            var mode=old==null?\'DIRECTORY_ONLY\':old.assignment_mode;\n            var status=assigned==1 || mode==\'GRANT_DERIVED\'?\'ACTIVE\':\'REVOKED\';\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_app_t(tid,\n                subject_id, app_id, account_alias, directory_assigned, assignment_mode, assignment_status,\n                desired_enabled, sync_status)\nvalues(#{id},#{objectId},#{appId},#{alias},#{assigned},\'DIRECTORY_ONLY\',#{status},0,\'NOT_CONNECTED\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_app_t\nset account_alias=#{alias},directory_assigned=#{assigned},assignment_status=#{status},\n    desired_version=desired_version+1,version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'assignments:\'+operation,id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/17.应用资料分配/03.归档应用人员资料分配.ms');
