INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6cedb7b11d634a43affa9ec17020e81d',NULL,'api','{\n  "properties": {},\n  "id": "1f4fe3caa35253c4b54dbe1a13909ed4",\n  "script": null,\n  "groupId": "7e715ce4956a53b6a2ff54bbe74211af",\n  "name": "01.查询人员任职列表",\n  "createTime": 1790615423659,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的人员任职，应用权限及身份域过滤后返回可展示字段；不发生写入。管理人员与机构之间的任职关系，校验人员、机构和身份域后维护控制库记录。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：查询中央人员与任职列表\n// 路由：GET /idaas/appointments/list\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/directory\' as directory;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'page\',\'size\',\'q\',\'status\',\'orgId\',\'includeChildren\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    return directory(\'subjects\',\'list\',payload);\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/18.人员任职/01.查询人员任职列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fee8e4182bd54622bc6898618f2dd6f4',NULL,'api','{\n  "properties": {},\n  "id": "ac42656e1e27535c80114b37d8493334",\n  "script": null,\n  "groupId": "7e715ce4956a53b6a2ff54bbe74211af",\n  "name": "02.保存人员任职",\n  "createTime": 1790615423659,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新人员任职及必要关联记录，写入审计并返回保存结果。管理人员与机构之间的任职关系，校验人员、机构和身份域后维护控制库记录。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存人员任职\n// 路由：POST /idaas/appointments/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新人员任职及必要关联记录，写入审计并返回保存结果。管理人员与机构之间的任职关系，校验人员、机构和身份域后维护控制库记录。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'subjects\';\n    var operation = \'save\';\n\n    // 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    if(![\'subjects\',\'orgs\'].contains(entity)) {\n        exit 400,\'目录对象不正确\';\n    }\n    var permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var rights=directoryScope(permission,domain);\n    var ctx=rights.ctx;\n    var extensionViews={};\n    var allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\n    var appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\n    var dto=(row)=>{\n        if(entity==\'orgs\') {\n            return {\n                id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n            };\n        }\n        var profile=row.identity_domain==\'public\' && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null?sql.selectOne("""\nselect p.verification_status,p.verification_id,v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id=#{row.id}\n"""):null;\n        var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n        var jobs=appointments(row.id);\n        var primary=jobs.filter(a=>a.is_primary==1);\n        var main=primary.size()==0?null:primary[0];\n        return {\n            id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n            createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n            appointments:jobs.map(a=>({\n                id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n            })),ext:extensionViews.get(row.id)||{}\n        };\n    };\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        var fresh=directoryScope(permission,domain);\n        var id=r.id||p.id;\n        var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n        var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'目录记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'目录记录身份域或版本已变更\';\n        }\n        var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n        if(old!=null && !allowed(originalOrgs,fresh)) {\n            exit 403,\'记录超出中央资料管理范围\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'orgs\') {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                    exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n                }\n            }\n            else {\n                if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                    exit 409,\'人员仍被负责人或平台账号引用\';\n                }\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n                sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n            }\n            sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n            if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n                rebuild(null,domain);\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        if(operation!=\'save\') {\n            exit 400,\'目录操作不正确\';\n        }\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n            exit 400,\'名称不正确\';\n        }\n        if(entity==\'orgs\') {\n            var parentId=r.parentId||null;\n            var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(parentId!=null && parent==null) {\n                exit 400,\'上级机构不存在、停用或跨域\';\n            }\n            if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n                exit 400,\'机构不能移入自身或下级\';\n            }\n            if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n                exit 403,\'上级机构超出管理范围\';\n            }\n            var code=(r.code||\'\').trim();\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n                exit 400,\'机构编码不正确\';\n            }\n            if(old!=null && code!=old.code) {\n                exit 400,\'机构编码保持稳定\';\n            }\n            if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'机构编码已使用\';\n            }\n            var leader=r.leader||null;\n            var line=r.line||null;\n            if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'负责人须为同域有效人员\';\n            }\n            if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'条线须选择有效字典\';\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n            }\n            var path=(parent==null?\'/\':parent.path)+id+\'/\';\n            var depth=parent==null?0:parent.depth+1;\n            if(path.length()>2000 || depth>50) {\n                exit 400,\'机构层级超限\';\n            }\n            if(old!=null) {\n                var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                    exit 403,\'移动机构涉及超出范围的下级\';\n                }\n                for(child in children) {\n                    var newPath=path+child.path.substring(old.path.length());\n                    if(newPath.length()>2000) {\n                        exit 400,\'下级机构路径超限\';\n                    }\n                }\n                sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n                sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n        }\n        else {\n            var jobs=r.appointments||[];\n            if(jobs.size()>30) {\n                exit 400,\'任职数量过多\';\n            }\n            var primary=jobs.filter(a=>a.primary==true);\n            if(jobs.size()>0 && primary.size()!=1) {\n                exit 400,\'任职必须且只能有一个主职\';\n            }\n            var orgIds=[];\n            var checked=[];\n            for(a in jobs) {\n                var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n                if(org==null || orgIds.contains(a.orgId)) {\n                    exit 400,\'任职机构无效、跨域或重复\';\n                }\n                orgIds.add(a.orgId);\n                for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                    var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                    if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                        exit 400,\'岗位职务须使用有效字典编码\';\n                    }\n                }\n                checked.add(a);\n            }\n            if(!allowed(orgIds,fresh)) {\n                exit 403,\'拟任职机构超出中央资料管理范围\';\n            }\n            var hint=(r.account||\'\').trim();\n            if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n                exit 400,\'拟用账号不正确\';\n            }\n            var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n            if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n                exit 400,\'人员编号不正确\';\n            }\n            var phone=r.phone||null;\n            var email=r.email||null;\n            var employee=r.employeeId||null;\n            var employment=(r.employmentType||\'employee\').toUpperCase();\n            var join=r.joinDate||null;\n            if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n                exit 400,\'人员资料不正确\';\n            }\n            try {\n                if(join!=null) {\n                    LocalDate.parse(join);\n                }\n            }\n            catch(e) {\n                exit 400,\'入职日期不正确\';\n            }\n            if(old==null) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                    exit 409,\'人员编号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n                sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n            }\n            var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            for(a in checked) {\n                var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n                var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n                var isPrimary=a.primary==true?1:0;\n                if(prior.size()>0) {\n                    sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n                }\n                else {\n                    sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n                }\n            }\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n        var encoded=JSONUtil.toJsonStr(ext);\n        sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,status:status\n        });\n        var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n        return {\n            id:id,version:saved.version\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/18.人员任职/02.保存人员任职.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9a47ed6715094d34b24829c54bb1f83c',NULL,NULL,'{\n  "properties": {},\n  "id": "7e715ce4956a53b6a2ff54bbe74211af",\n  "name": "18.人员任职",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/appointments",\n  "createTime": 1790615423659,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/18.人员任职/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e2a5a13f605c4425ad53187421c159c8',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/19.应用业务角色/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('76589d3de3f143cbba173890edb9a890',NULL,'api','{\n  "properties": {},\n  "id": "b3c53db488755c1e93d8f67afb2c4b97",\n  "script": null,\n  "groupId": "b34c35bb56695d918186c7c7928a69cf",\n  "name": "01.查询应用业务角色列表",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用业务角色，应用权限及身份域过滤后返回可展示字段；不发生写入。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用业务角色列表\n// 路由：GET /idaas/roles/list\n// 业务说明：读取符合请求筛选条件的应用业务角色，应用权限及身份域过滤后返回可展示字段；不发生写入。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var entity = \'roles\';\n    var operation = \'list\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    if(operation==\'list\') {\n        // 按操作员的应用管理范围过滤可见数据。\n        var ctx=listContext(permission,p.appId||null,domain);\n        var rows=sql.select(\'select t.*,t.tid as id,date_format(t.created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(t.updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+" t join iam_application_t a on a.tid=t.app_id and a.kind=\'BUSINESS\' and a.is_del=0 where t.is_del=0 and t.identity_domain=#{domain} order by t.tid");\n        var visible=rows.filter(x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.app_id)).size()>0).size()>0 && (p.appId==null || x.app_id==p.appId));\n        return visible.map(x=>({\n            id:x.id,appId:x.app_id,domain:x.identity_domain,name:x.name,code:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,description:entity==\'roles\'?x.description||\'\':\'\',resourceIds:entity==\'roles\'?sql.select("""\nselect resource_id\nfrom iam_role_resource_rela_t\nwhere role_id=#{x.id}\n""").map(v=>v.resource_id):[],parentId:entity==\'resources\'?x.parent_id:null,type:entity==\'resources\'?x.resource_type.toLowerCase():\'\',path:entity==\'resources\'?x.path||\'\':\'\',method:entity==\'resources\'?x.http_method||\'GET\':\'\',ext:entity==\'resources\'?fieldValues(\'view\',\'RESOURCE\',domain,x.id,x.ext_json==null?{}:JSONUtil.parseObj(x.ext_json),{}):{}\n        }));\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/19.应用业务角色/01.查询应用业务角色列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4eef540ec9194331a3e2fc357425434b',NULL,'api','{\n  "properties": {},\n  "id": "198cc4bcf30754adb17aafd004e44b34",\n  "script": null,\n  "groupId": "b34c35bb56695d918186c7c7928a69cf",\n  "name": "02.保存应用业务角色",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用业务角色及必要关联记录，写入审计并返回保存结果。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用业务角色\n// 路由：POST /idaas/roles/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用业务角色及必要关联记录，写入审计并返回保存结果。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'roles\';\n    var operation = \'save\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/19.应用业务角色/02.保存应用业务角色.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a55fddb41b3445e8a4da899f9caa2b9e',NULL,'api','{\n  "properties": {},\n  "id": "b9c145c0fe395dadb51ee4eb896d7b78",\n  "script": null,\n  "groupId": "b34c35bb56695d918186c7c7928a69cf",\n  "name": "03.归档应用业务角色",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用业务角色并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用业务角色\n// 路由：POST /idaas/roles/remove\n// 业务说明：按标识加载应用业务角色并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只管理业务应用角色及其资源关联；平台控制台角色由平台角色接口独立维护。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'roles\';\n    var operation = \'remove\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/19.应用业务角色/03.归档应用业务角色.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b2ceb74a096748e1bdbea4b2ae2e5f8f',NULL,NULL,'{\n  "properties": {},\n  "id": "b34c35bb56695d918186c7c7928a69cf",\n  "name": "19.应用业务角色",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/roles",\n  "createTime": 1790617158595,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/19.应用业务角色/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('83a3ceb0c1be4c4abff500cd9304c7dd',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/20.应用资源/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b36aa51158f440e68dc793c1a73d732b',NULL,'api','{\n  "properties": {},\n  "id": "11ad79c418c65def899746ea5c69681c",\n  "script": null,\n  "groupId": "dfa10519bbb5591d9fbf0f7215f608f3",\n  "name": "01.查询应用资源列表",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用资源，应用权限及身份域过滤后返回可展示字段；不发生写入。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用资源列表\n// 路由：GET /idaas/resources/list\n// 业务说明：读取符合请求筛选条件的应用资源，应用权限及身份域过滤后返回可展示字段；不发生写入。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var entity = \'resources\';\n    var operation = \'list\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    if(operation==\'list\') {\n        // 按操作员的应用管理范围过滤可见数据。\n        var ctx=listContext(permission,p.appId||null,domain);\n        var rows=sql.select(\'select t.*,t.tid as id,date_format(t.created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(t.updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+" t join iam_application_t a on a.tid=t.app_id and a.kind=\'BUSINESS\' and a.is_del=0 where t.is_del=0 and t.identity_domain=#{domain} order by t.tid");\n        var visible=rows.filter(x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.app_id)).size()>0).size()>0 && (p.appId==null || x.app_id==p.appId));\n        return visible.map(x=>({\n            id:x.id,appId:x.app_id,domain:x.identity_domain,name:x.name,code:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,description:entity==\'roles\'?x.description||\'\':\'\',resourceIds:entity==\'roles\'?sql.select("""\nselect resource_id\nfrom iam_role_resource_rela_t\nwhere role_id=#{x.id}\n""").map(v=>v.resource_id):[],parentId:entity==\'resources\'?x.parent_id:null,type:entity==\'resources\'?x.resource_type.toLowerCase():\'\',path:entity==\'resources\'?x.path||\'\':\'\',method:entity==\'resources\'?x.http_method||\'GET\':\'\',ext:entity==\'resources\'?fieldValues(\'view\',\'RESOURCE\',domain,x.id,x.ext_json==null?{}:JSONUtil.parseObj(x.ext_json),{}):{}\n        }));\n    }\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/20.应用资源/01.查询应用资源列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4c7b8ff6ccfb476299f75469b112bfc8',NULL,'api','{\n  "properties": {},\n  "id": "81d9266d4fe052f090cc0631d8e3cd2c",\n  "script": null,\n  "groupId": "dfa10519bbb5591d9fbf0f7215f608f3",\n  "name": "02.保存应用资源",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用资源及必要关联记录，写入审计并返回保存结果。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用资源\n// 路由：POST /idaas/resources/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用资源及必要关联记录，写入审计并返回保存结果。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'resources\';\n    var operation = \'save\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/20.应用资源/02.保存应用资源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8c9d4d51e6334677a69e7233c714c4e2',NULL,'api','{\n  "properties": {},\n  "id": "551fcded58c1543ea75dfd5a72b9f0c0",\n  "script": null,\n  "groupId": "dfa10519bbb5591d9fbf0f7215f608f3",\n  "name": "03.归档应用资源",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用资源并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用资源\n// 路由：POST /idaas/resources/remove\n// 业务说明：按标识加载应用资源并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。只管理业务应用菜单、按钮和接口资源；校验所属应用和资源唯一性。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var entity = \'resources\';\n    var operation = \'remove\';\n\n    // 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    if(![\'roles\',\'resources\'].contains(entity)) {\n        exit 400,\'对象类型不正确\';\n    }\n    var table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\n    var appId=old==null?r.appId:old.app_id;\n    var permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,entity+\':\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n        if(old==null && p.creating!=true) {\n            exit 404,\'记录不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'应用、身份域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'目标不是此身份域的业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n                exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n            }\n            if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n                exit 409,\'资源仍被下级或角色引用\';\n            }\n            sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var code=(r.code||\'\').trim();\n        var name=(r.name||\'\').trim();\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n            exit 400,\'名称或编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'编码保持稳定\';\n        }\n        if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n            exit 409,\'编码已经使用\';\n        }\n        if(entity==\'roles\') {\n            var description=r.description||\'\';\n            if(description.length()>1000) {\n                exit 400,\'说明过长\';\n            }\n            var resources=r.resourceIds||[];\n            if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n                exit 400,\'资源引用重复或过多\';\n            }\n            for(rid in resources) {\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'资源必须属于同应用和身份域且启用\';\n                }\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n            for(rid in resources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n            }\n        }\n        else {\n            var type=(r.type||\'\').toUpperCase();\n            var parentId=r.parentId||null;\n            var path=r.path||\'\';\n            var method=(r.method||\'GET\').toUpperCase();\n            if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n                exit 400,\'资源类型或接口路径不正确\';\n            }\n            var visited=[id];\n            var cursor=parentId;\n            while(cursor!=null) {\n                if(visited.contains(cursor)) {\n                    exit 400,\'资源层级不能循环\';\n                }\n                visited.add(cursor);\n                var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n                if(parent==null || parent.resource_type!=\'MENU\') {\n                    exit 400,\'父资源须为同应用同域菜单\';\n                }\n                cursor=parent.parent_id;\n            }\n            if(old==null) {\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n            var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n            sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/20.应用资源/03.归档应用资源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0f02bce56bed4cf69be06e7b1f4eb930',NULL,NULL,'{\n  "properties": {},\n  "id": "dfa10519bbb5591d9fbf0f7215f608f3",\n  "name": "20.应用资源",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/resources",\n  "createTime": 1790617158595,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/20.应用资源/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('804c8588606948ad9d2a2a6ebd084756',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('50cc96b1a65e4e80b09178f53d9500f5',NULL,'api','{\n  "properties": {},\n  "id": "8232e18d8d865a988cd03e411baef392",\n  "script": null,\n  "groupId": "d7e5646b56d156198bbf3826dfe4771c",\n  "name": "01.查询应用访问授权列表",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用访问授权，应用权限及身份域过滤后返回可展示字段；不发生写入。对指定业务应用的人员或组织颁发访问授权，核验身份域、角色、有效期与对象范围。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用访问授权列表\n// 路由：GET /idaas/grants/list\n// 业务说明：读取符合请求筛选条件的应用访问授权，应用权限及身份域过滤后返回可展示字段；不发生写入。对指定业务应用的人员或组织颁发访问授权，核验身份域、角色、有效期与对象范围。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/effective-access\' as effective;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=\'grants:\'+(operation==\'list\' || operation==\'explain\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    if(operation==\'list\') {\n        var rows=sql.select("""\nselect *,tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\') start_utc,\n       date_format(valid_until, \'%Y-%m-%dT%H:%i:%sZ\') end_utc,date_format(created_time,\n        \'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') updated_utc\nfrom iam_access_grant_t\nwhere identity_domain=#{domain}\n    and is_del=0\norder by tid\n""");\n        return rows.filter(x=>(appId==null || x.app_id==appId) && ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.app_id)).size()>0).size()>0).map(x=>({\n            id:x.id,domain:x.identity_domain,appId:x.app_id,name:\'应用访问授权\',source:x.principal_type==\'SUBJECT\'?\'user\':x.principal_type.toLowerCase(),subjectId:x.subject_id||x.org_id||x.group_id||x.client_id,roleIds:sql.select("""\nselect role_id\nfrom iam_grant_role_rela_t\nwhere grant_id=#{x.id}\n""").map(t=>t.role_id),includeChildren:x.include_children==1,status:x.status==\'ACTIVE\'?\'enabled\':\'revoked\',startsAt:x.start_utc,expiresAt:x.end_utc,reason:x.reason||\'\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc\n        }));\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'grants:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'授权不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id || old.identity_domain!=domain)) {\n            exit 409,\'授权应用、域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'仅允许此身份域的业务应用授权\';\n        }\n        if(operation==\'remove\' || r.status==\'revoked\') {\n            if(old==null) {\n                exit 404,\'授权不存在\';\n            }\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'grants:revoke\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var types={\n            user:\'SUBJECT\',org:\'ORG\',group:\'GROUP\',client:\'CLIENT\'\n        };\n        var type=types.get(r.source);\n        var principal=r.subjectId;\n        if(type==null || principal==null || old!=null && (old.principal_type!=type || (old.subject_id||old.org_id||old.group_id||old.client_id)!=principal)) {\n            exit 400,\'授权主体不能变更\';\n        }\n        var table=type==\'SUBJECT\'?\'iam_subject_t\':type==\'ORG\'?\'iam_org_t\':type==\'GROUP\'?\'iam_permission_group_t\':\'iam_auth_client_t\';\n        var target=sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{principal} and is_del=0\');\n        if(target==null || type!=\'CLIENT\' && (target.identity_domain!=domain || target.status!=\'ACTIVE\') || type==\'CLIENT\' && (target.client_type!=\'SERVICE\' || target.status==\'DISABLED\')) {\n            exit 400,\'主体须为启用的同域人员、机构、权限组或机器客户端\';\n        }\n        var roles=r.roleIds||[];\n        if(roles.size()>100 || roles.distinct().size()!=roles.size()) {\n            exit 400,\'角色引用重复或过多\';\n        }\n        for(rid in roles) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'角色必须属于同业务应用和身份域\';\n            }\n            if(type==\'CLIENT\' && sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t re on re.tid=rr.resource_id\nwhere rr.role_id=#{rid}\n    and re.resource_type!=\'API\'\n    and re.is_del=0\n""").n>0) {\n                exit 400,\'机器身份只能授予API资源角色\';\n            }\n        }\n        var times=window(r.startsAt,r.expiresAt);\n        var reason=r.reason||\'\';\n        if(reason.length()>1000) {\n            exit 400,\'授权说明过长\';\n        }\n        var include=type==\'ORG\' && r.includeChildren==true?1:0;\n        var sid=type==\'SUBJECT\'?principal:null;\n        var oid=type==\'ORG\'?principal:null;\n        var gid=type==\'GROUP\'?principal:null;\n        var cid=type==\'CLIENT\'?principal:null;\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_access_grant_t(tid,\n                app_id, identity_domain, principal_type, subject_id, org_id, group_id, client_id,\n                include_children, valid_from, valid_until, reason, created_by)\nvalues(#{id},#{appId},#{domain},#{type},#{sid},#{oid},#{gid},#{cid},#{include},#{times.start},#{times.end},#{reason},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_access_grant_t\nset include_children=#{include},valid_from=#{times.start},valid_until=#{times.end},reason=#{reason},\n    status=\'ACTIVE\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\ndelete\nfrom iam_grant_role_rela_t\nwhere grant_id=#{id}\n""");\n        for(rid in roles) {\n            var link=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_grant_role_rela_t(tid, grant_id, role_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',\'grants:save\',id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/01.查询应用访问授权列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cb87e645421945b4b956b2626950af51',NULL,'api','{\n  "properties": {},\n  "id": "3271b28c612650c88db8832fc5eda9b0",\n  "script": null,\n  "groupId": "d7e5646b56d156198bbf3826dfe4771c",\n  "name": "02.保存应用访问授权",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用访问授权及必要关联记录，写入审计并返回保存结果。对指定业务应用的人员或组织颁发访问授权，核验身份域、角色、有效期与对象范围。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用访问授权\n// 路由：POST /idaas/grants/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用访问授权及必要关联记录，写入审计并返回保存结果。对指定业务应用的人员或组织颁发访问授权，核验身份域、角色、有效期与对象范围。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/effective-access\' as effective;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=\'grants:\'+(operation==\'list\' || operation==\'explain\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'grants:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'授权不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id || old.identity_domain!=domain)) {\n            exit 409,\'授权应用、域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'仅允许此身份域的业务应用授权\';\n        }\n        if(operation==\'remove\' || r.status==\'revoked\') {\n            if(old==null) {\n                exit 404,\'授权不存在\';\n            }\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'grants:revoke\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var types={\n            user:\'SUBJECT\',org:\'ORG\',group:\'GROUP\',client:\'CLIENT\'\n        };\n        var type=types.get(r.source);\n        var principal=r.subjectId;\n        if(type==null || principal==null || old!=null && (old.principal_type!=type || (old.subject_id||old.org_id||old.group_id||old.client_id)!=principal)) {\n            exit 400,\'授权主体不能变更\';\n        }\n        var table=type==\'SUBJECT\'?\'iam_subject_t\':type==\'ORG\'?\'iam_org_t\':type==\'GROUP\'?\'iam_permission_group_t\':\'iam_auth_client_t\';\n        var target=sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{principal} and is_del=0\');\n        if(target==null || type!=\'CLIENT\' && (target.identity_domain!=domain || target.status!=\'ACTIVE\') || type==\'CLIENT\' && (target.client_type!=\'SERVICE\' || target.status==\'DISABLED\')) {\n            exit 400,\'主体须为启用的同域人员、机构、权限组或机器客户端\';\n        }\n        var roles=r.roleIds||[];\n        if(roles.size()>100 || roles.distinct().size()!=roles.size()) {\n            exit 400,\'角色引用重复或过多\';\n        }\n        for(rid in roles) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'角色必须属于同业务应用和身份域\';\n            }\n            if(type==\'CLIENT\' && sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t re on re.tid=rr.resource_id\nwhere rr.role_id=#{rid}\n    and re.resource_type!=\'API\'\n    and re.is_del=0\n""").n>0) {\n                exit 400,\'机器身份只能授予API资源角色\';\n            }\n        }\n        var times=window(r.startsAt,r.expiresAt);\n        var reason=r.reason||\'\';\n        if(reason.length()>1000) {\n            exit 400,\'授权说明过长\';\n        }\n        var include=type==\'ORG\' && r.includeChildren==true?1:0;\n        var sid=type==\'SUBJECT\'?principal:null;\n        var oid=type==\'ORG\'?principal:null;\n        var gid=type==\'GROUP\'?principal:null;\n        var cid=type==\'CLIENT\'?principal:null;\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_access_grant_t(tid,\n                app_id, identity_domain, principal_type, subject_id, org_id, group_id, client_id,\n                include_children, valid_from, valid_until, reason, created_by)\nvalues(#{id},#{appId},#{domain},#{type},#{sid},#{oid},#{gid},#{cid},#{include},#{times.start},#{times.end},#{reason},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_access_grant_t\nset include_children=#{include},valid_from=#{times.start},valid_until=#{times.end},reason=#{reason},\n    status=\'ACTIVE\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\ndelete\nfrom iam_grant_role_rela_t\nwhere grant_id=#{id}\n""");\n        for(rid in roles) {\n            var link=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_grant_role_rela_t(tid, grant_id, role_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',\'grants:save\',id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/02.保存应用访问授权.ms');
