/ 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'grants:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'授权不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id || old.identity_domain!=domain)) {\n            exit 409,\'授权应用、域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'仅允许此身份域的业务应用授权\';\n        }\n        if(operation==\'remove\' || r.status==\'revoked\') {\n            if(old==null) {\n                exit 404,\'授权不存在\';\n            }\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'grants:revoke\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var types={\n            user:\'SUBJECT\',org:\'ORG\',group:\'GROUP\',client:\'CLIENT\'\n        };\n        var type=types.get(r.source);\n        var principal=r.subjectId;\n        if(type==null || principal==null || old!=null && (old.principal_type!=type || (old.subject_id||old.org_id||old.group_id||old.client_id)!=principal)) {\n            exit 400,\'授权主体不能变更\';\n        }\n        var table=type==\'SUBJECT\'?\'iam_subject_t\':type==\'ORG\'?\'iam_org_t\':type==\'GROUP\'?\'iam_permission_group_t\':\'iam_auth_client_t\';\n        var target=sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{principal} and is_del=0\');\n        if(target==null || type!=\'CLIENT\' && (target.identity_domain!=domain || target.status!=\'ACTIVE\') || type==\'CLIENT\' && (target.client_type!=\'SERVICE\' || target.status==\'DISABLED\')) {\n            exit 400,\'主体须为启用的同域人员、机构、权限组或机器客户端\';\n        }\n        var roles=r.roleIds||[];\n        if(roles.size()>100 || roles.distinct().size()!=roles.size()) {\n            exit 400,\'角色引用重复或过多\';\n        }\n        for(rid in roles) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'角色必须属于同业务应用和身份域\';\n            }\n            if(type==\'CLIENT\' && sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t re on re.tid=rr.resource_id\nwhere rr.role_id=#{rid}\n    and re.resource_type!=\'API\'\n    and re.is_del=0\n""").n>0) {\n                exit 400,\'机器身份只能授予API资源角色\';\n            }\n        }\n        var times=window(r.startsAt,r.expiresAt);\n        var reason=r.reason||\'\';\n        if(reason.length()>1000) {\n            exit 400,\'授权说明过长\';\n        }\n        var include=type==\'ORG\' && r.includeChildren==true?1:0;\n        var sid=type==\'SUBJECT\'?principal:null;\n        var oid=type==\'ORG\'?principal:null;\n        var gid=type==\'GROUP\'?principal:null;\n        var cid=type==\'CLIENT\'?principal:null;\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_access_grant_t(tid,\n                app_id, identity_domain, principal_type, subject_id, org_id, group_id, client_id,\n                include_children, valid_from, valid_until, reason, created_by)\nvalues(#{id},#{appId},#{domain},#{type},#{sid},#{oid},#{gid},#{cid},#{include},#{times.start},#{times.end},#{reason},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_access_grant_t\nset include_children=#{include},valid_from=#{times.start},valid_until=#{times.end},reason=#{reason},\n    status=\'ACTIVE\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\ndelete\nfrom iam_grant_role_rela_t\nwhere grant_id=#{id}\n""");\n        for(rid in roles) {\n            var link=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_grant_role_rela_t(tid, grant_id, role_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',\'grants:save\',id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/03.归档应用访问授权.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d3d563a66dad411c89f04769514a9e47',NULL,'api','{\n  "properties": {},\n  "id": "793fcd8252c55db593deb2b44977b569",\n  "script": null,\n  "groupId": "d7e5646b56d156198bbf3826dfe4771c",\n  "name": "04.解释人员有效授权",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/explain",\n  "description": "根据人员、应用和身份域计算当前有效角色与资源，并返回各项授权来源及有效期，便于审查访问原因。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.解释人员有效授权\n// 路由：GET /idaas/grants/explain\n// 业务说明：根据人员、应用和身份域计算当前有效角色与资源，并返回各项授权来源及有效期，便于审查访问原因。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/effective-access\' as effective;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'explain\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=\'grants:\'+(operation==\'list\' || operation==\'explain\'?\'read\':\'write\');\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    if(operation==\'explain\') {\n        var person=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{p.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n        if(person==null) {\n            exit 404,\'人员不存在\';\n        }\n        return effective(p.subjectId,appId,domain);\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'grants:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'授权不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id || old.identity_domain!=domain)) {\n            exit 409,\'授权应用、域或版本不一致\';\n        }\n        var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n        if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n            exit 400,\'仅允许此身份域的业务应用授权\';\n        }\n        if(operation==\'remove\' || r.status==\'revoked\') {\n            if(old==null) {\n                exit 404,\'授权不存在\';\n            }\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            rebuild(appId,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'grants:revoke\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var types={\n            user:\'SUBJECT\',org:\'ORG\',group:\'GROUP\',client:\'CLIENT\'\n        };\n        var type=types.get(r.source);\n        var principal=r.subjectId;\n        if(type==null || principal==null || old!=null && (old.principal_type!=type || (old.subject_id||old.org_id||old.group_id||old.client_id)!=principal)) {\n            exit 400,\'授权主体不能变更\';\n        }\n        var table=type==\'SUBJECT\'?\'iam_subject_t\':type==\'ORG\'?\'iam_org_t\':type==\'GROUP\'?\'iam_permission_group_t\':\'iam_auth_client_t\';\n        var target=sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{principal} and is_del=0\');\n        if(target==null || type!=\'CLIENT\' && (target.identity_domain!=domain || target.status!=\'ACTIVE\') || type==\'CLIENT\' && (target.client_type!=\'SERVICE\' || target.status==\'DISABLED\')) {\n            exit 400,\'主体须为启用的同域人员、机构、权限组或机器客户端\';\n        }\n        var roles=r.roleIds||[];\n        if(roles.size()>100 || roles.distinct().size()!=roles.size()) {\n            exit 400,\'角色引用重复或过多\';\n        }\n        for(rid in roles) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'角色必须属于同业务应用和身份域\';\n            }\n            if(type==\'CLIENT\' && sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t re on re.tid=rr.resource_id\nwhere rr.role_id=#{rid}\n    and re.resource_type!=\'API\'\n    and re.is_del=0\n""").n>0) {\n                exit 400,\'机器身份只能授予API资源角色\';\n            }\n        }\n        var times=window(r.startsAt,r.expiresAt);\n        var reason=r.reason||\'\';\n        if(reason.length()>1000) {\n            exit 400,\'授权说明过长\';\n        }\n        var include=type==\'ORG\' && r.includeChildren==true?1:0;\n        var sid=type==\'SUBJECT\'?principal:null;\n        var oid=type==\'ORG\'?principal:null;\n        var gid=type==\'GROUP\'?principal:null;\n        var cid=type==\'CLIENT\'?principal:null;\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_access_grant_t(tid,\n                app_id, identity_domain, principal_type, subject_id, org_id, group_id, client_id,\n                include_children, valid_from, valid_until, reason, created_by)\nvalues(#{id},#{appId},#{domain},#{type},#{sid},#{oid},#{gid},#{cid},#{include},#{times.start},#{times.end},#{reason},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_access_grant_t\nset include_children=#{include},valid_from=#{times.start},valid_until=#{times.end},reason=#{reason},\n    status=\'ACTIVE\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\ndelete\nfrom iam_grant_role_rela_t\nwhere grant_id=#{id}\n""");\n        for(rid in roles) {\n            var link=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_grant_role_rela_t(tid, grant_id, role_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n        }\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',\'grants:save\',id,null,{\n            id:id,appId:appId,type:type\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/04.解释人员有效授权.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e61569d786034fdf89f603c8ae5e0b42',NULL,NULL,'{\n  "properties": {},\n  "id": "d7e5646b56d156198bbf3826dfe4771c",\n  "name": "21.访问授权",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/grants",\n  "createTime": 1790617158595,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/21.访问授权/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('37bab961fb544e88a76e477a3e899629',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/22.权限组/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9d829bc730c5409db1cc34450c328d3d',NULL,'api','{\n  "properties": {},\n  "id": "a5584240beda57e78864346269255c83",\n  "script": null,\n  "groupId": "b2dabd7a0ef25609852aa2dc1d6eadb1",\n  "name": "01.查询权限组列表",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的权限组，应用权限及身份域过滤后返回可展示字段；不发生写入。维护业务应用的权限组及成员关系，用于聚合可授权的人员范围。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询权限组列表\n// 路由：GET /idaas/permission-groups/list\n// 业务说明：读取符合请求筛选条件的权限组，应用权限及身份域过滤后返回可展示字段；不发生写入。维护业务应用的权限组及成员关系，用于聚合可授权的人员范围。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/business-grants\' as grants;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'grants:read\':\'grants:write\',null,domain);\n    if(operation==\'list\') {\n        var rows=sql.select("""\nselect *,tid as id,date_format(created_time, \'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') updated_utc\nfrom iam_permission_group_t\nwhere identity_domain=#{domain}\n    and is_del=0\norder by tid\n""");\n        return rows.map(x=>({\n            id:x.id,domain:x.identity_domain,name:x.name,code:x.code,description:x.description||\'\',status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,userIds:sql.select("""\nselect subject_id\nfrom iam_group_member_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n""").map(m=>m.subject_id),members:sql.select("""\nselect subject_id subjectId,date_format(valid_from,\n        \'%Y-%m-%dT%H:%i:%sZ\') startsAt,\n       date_format(valid_until, \'%Y-%m-%dT%H:%i:%sZ\') expiresAt\nfrom iam_group_member_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n"""),items:sql.select("""\nselect tid as id,app_id\nfrom iam_access_grant_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").map(g=>({\n                appId:g.app_id,roleIds:sql.select("""\nselect role_id\nfrom iam_grant_role_rela_t\nwhere grant_id=#{g.id}\n""").map(y=>y.role_id)\n            }))\n        }));\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'permission-groups:\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_permission_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'权限组不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'权限组身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            sql.update("""\nupdate iam_permission_group_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n            sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n            rebuild(null,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'permission-groups:remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var description=r.description||\'\';\n        var code=old==null?(r.code||\'GROUP_\'+IdUtil.fastSimpleUUID()):old.code;\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        var users=r.userIds||[];\n        var items=r.items||[];\n        if(name==\'\' || name.length()>200 || description.length()>1000 || !code.matches(\'[A-Za-z][A-Za-z0-9_.:-]{1,99}\') || users.size()>1000 || users.distinct().size()!=users.size() || items.size()>50 || items.map(i=>i.appId).distinct().size()!=items.size()) {\n            exit 400,\'名称、成员或应用组合不正确\';\n        }\n        for(sid in users) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{sid}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'成员须为同域中央人员\';\n            }\n        }\n        // 先校验全部组合，组写入与来源、成员都在同一事务内。\n        for(item in items) {\n            guard(\'grants:write\',item.appId,domain);\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{item.appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'组合仅允许有效业务应用\';\n            }\n        }\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_permission_group_t(tid,\n                identity_domain, code, name, description, status)\nvalues(#{id},#{domain},#{code},#{name},#{description},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_permission_group_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n        for(sid in users) {\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_group_member_t\nwhere group_id=#{id}\n    and subject_id=#{sid}\n""");\n            var details=(r.members||[]).filter(m=>m.subjectId==sid);\n            var times=details.size()>0?window(details[0].startsAt,details[0].expiresAt):window(null,null);\n            var mid=prior==null?IdUtil.fastSimpleUUID():prior.id;\n            if(prior==null) {\n                sql.update("""\ninsert into iam_group_member_t(tid,\n                group_id, subject_id, valid_from, valid_until)\nvalues(#{mid},#{id},#{sid},#{times.start},#{times.end})\n""");\n            }\n            else if(details.size()>0) {\n                sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',valid_from=#{times.start},valid_until=#{times.end},version=version+1\nwhere tid=#{mid}\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',version=version+1\nwhere tid=#{mid}\n""");\n            }\n        }\n        var current=sql.select("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere group_id=#{id}\n    and is_del=0\n""");\n        for(g in current) {\n            if(items.filter(i=>i.appId==g.app_id).size()==0 || status!=\'ACTIVE\') {\n                sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere tid=#{g.id}\n""");\n            }\n        }\n        if(status==\'ACTIVE\') {\n            for(item in items) {\n                var existing=current.filter(g=>g.app_id==item.appId);\n                var prior=existing.size()>0?existing[0]:null;\n                grants(\'save\',{\n                    requestId:IdUtil.fastSimpleUUID(),creating:prior==null,record:{\n                        id:prior==null?null:prior.id,version:prior==null?1:prior.version,domain:domain,source:\'group\',subjectId:id,appId:item.appId,roleIds:item.roleIds||[],reason:\'权限组组合\',status:\'enabled\'\n                    }\n                });\n            }\n        }\n        rebuild(null,domain);\n        audit(ctx,\'SUCCESS\',\'permission-groups:save\',id,null,{\n            id:id,memberCount:users.size()\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/22.权限组/01.查询权限组列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('91b5cb16f40b4e7ebce295eefe59c98b',NULL,'api','{\n  "properties": {},\n  "id": "0ce64f83f20e56769be48ddba696af99",\n  "script": null,\n  "groupId": "b2dabd7a0ef25609852aa2dc1d6eadb1",\n  "name": "02.保存权限组",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新权限组及必要关联记录，写入审计并返回保存结果。维护业务应用的权限组及成员关系，用于聚合可授权的人员范围。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存权限组\n// 路由：POST /idaas/permission-groups/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新权限组及必要关联记录，写入审计并返回保存结果。维护业务应用的权限组及成员关系，用于聚合可授权的人员范围。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/business-grants\' as grants;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'grants:read\':\'grants:write\',null,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'permission-groups:\'+operation,p,()=>{\n        var id=r.id||p.id;\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_permission_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'权限组不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'权限组身份域或版本已变更\';\n        }\n        if(operation==\'remove\') {\n            sql.update("""\nupdate iam_permission_group_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n            sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n            rebuild(null,domain);\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'permission-groups:remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var description=r.description||\'\';\n        var code=old==null?(r.code||\'GROUP_\'+IdUtil.fastSimpleUUID()):old.code;\n        var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n        var users=r.userIds||[];\n        var items=r.items||[];\n        if(name==\'\' || name.length()>200 || description.length()>1000 || !code.matches(\'[A-Za-z][A-Za-z0-9_.:-]{1,99}\') || users.size()>1000 || users.distinct().size()!=users.size() || items.size()>50 || items.map(i=>i.appId).distinct().size()!=items.size()) {\n            exit 400,\'名称、成员或应用组合不正确\';\n        }\n        for(sid in users) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{sid}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n                exit 400,\'成员须为同域中央人员\';\n            }\n        }\n        // 先校验全部组合，组写入与来源、成员都在同一事务内。\n        for(item in items) {\n            guard(\'grants:write\',item.appId,domain);\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{item.appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'组合仅允许有效业务应用\';\n            }\n        }\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_permission_group_t(tid,\n                identity_domain, code, name, description, status)\nvalues(#{id},#{domain},#{code},#{name},#{description},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_permission_group_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n        for(sid in users) {\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_group_member_t\nwhere group_id=#{id}\n    and subject_id=#{sid}\n""");\n            var details=(r.members||[]).filter(m=>m.subjectId==sid);\n            var times=details.size()>0?window(details[0].startsAt,details[0].expiresAt):window(null,null);\n            var mid=prior==null?IdUtil.fastSimpleUUID():prior.id;\n            if(prior==null) {\n                sql.update("""\ninsert into iam_group_member_t(tid,\n                group_id, subject_id, valid_from, valid_until)\nvalues(#{mid},#{id},#{sid},#{times.start},#{times.end})\n""");\n            }\n            else if(details.size()>0) {\n                sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',valid_from=#{times.start},valid_until=#{times.end},version=version+1\nwhere tid=#{mid}\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',version=version+1\nwhere tid=#{mid}\n""");\n            }\n        }\n        var current=sql.select("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere group_id=#{id}\n    and is_del=0\n""");\n        for(g in current) {\n            if(items.filter(i=>i.appId==g.app_id).size()==0 || status!=\'ACTIVE\') {\n                sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere tid=#{g.id}\n""");\n            }\n        }\n        if(status==\'ACTIVE\') {\n            for(item in items) {\n                var existing=current.filter(g=>g.app_id==item.appId);\n                var prior=existing.size()>0?existing[0]:null;\n                grants(\'save\',{\n                    requestId:IdUtil.fastSimpleUUID(),creating:prior==null,record:{\n                        id:prior==null?null:prior.id,version:prior==null?1:prior.version,domain:domain,source:\'group\',subjectId:id,appId:item.appId,roleIds:item.roleIds||[],reason:\'权限组组合\',status:\'enabled\'\n                    }\n                });\n            }\n        }\n        rebuild(null,domain);\n        audit(ctx,\'SUCCESS\',\'permission-groups:save\',id,null,{\n            id:id,memberCount:users.size()\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/22.权限组/02.保存权限组.ms');
