INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0ce0a869b2564c20a32f15a12122b6b6',NULL,'api','{\n  "properties": {},\n  "id": "a00b226b4fd35e91a584718eb4b9a2f1",\n  "script": null,\n  "groupId": "22234a256a485757b6f81c2c1c3885ed",\n  "name": "01.查询应用客户端列表",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的应用客户端，应用权限及身份域过滤后返回可展示字段；不发生写入。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询应用客户端列表\n// 路由：GET /idaas/clients/list\n// 业务说明：读取符合请求筛选条件的应用客户端，应用权限及身份域过滤后返回可展示字段；不发生写入。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'domain\',\'appId\',\'subjectId\',\'page\',\'size\',\'q\']) {\n        var input=request.getValues(key);\n        if(input!=null && input.size()>0) {\n            payload.put(key,input[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=operation==\'list\'?\'clients:read\':\'clients:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    if(operation==\'list\') {\n        var rows=sql.select("""\nselect tid as id,app_id appId,client_key clientKey,name,client_type clientType,protocol,status,\n       require_pkce requirePkce,access_ttl_seconds accessTtl,refresh_ttl_seconds refreshTtl,version\nfrom iam_auth_client_t\nwhere is_del=0\n""");\n        return rows.filter(x=>(appId==null || x.appId==appId) && ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.appId)).size()>0).size()>0);\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'clients:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'客户端不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id)) {\n            exit 409,\'客户端应用或版本不一致\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'客户端只能属于业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect count(*) n\nfrom iam_access_grant_t\nwhere client_id=#{id}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").n>0) {\n                exit 409,\'机器身份仍有有效授权\';\n            }\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'clients:remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var key=(r.clientKey||\'\').trim();\n        var type=r.clientType||\'PUBLIC\';\n        if(name==\'\' || name.length()>100 || !key.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || ![\'PUBLIC\',\'CONFIDENTIAL\',\'SERVICE\'].contains(type)) {\n            exit 400,\'客户端名称、编码或类型不正确\';\n        }\n        if(old!=null && (key!=old.client_key || type!=old.client_type)) {\n            exit 400,\'客户端编码和类型保持稳定\';\n        }\n        if(r.protocol!=null && r.protocol!=\'NONE\' || r.status==\'ACTIVE\') {\n            exit 400,\'登记接口不开放认证协议，请在认证接入配置中启用\';\n        }\n        var status=r.status==\'DISABLED\'?\'DISABLED\':\'REGISTERED\';\n        var access=r.accessTtl||600;\n        var refresh=r.refreshTtl||86400;\n        if(access<60 || access>3600 || refresh<access || refresh>604800) {\n            exit 400,\'令牌有效期超限\';\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere client_key=#{key}\n""")!=null) {\n                exit 409,\'客户端编码已经使用\';\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_auth_client_t(tid,\n                app_id, client_key, name, client_type, token_auth_method, access_ttl_seconds,\n                refresh_ttl_seconds, status)\nvalues(#{id},#{appId},#{key},#{name},#{type},#{type==\'PUBLIC\'?\'none\':\'client_secret_basic\'},#{access},#{refresh},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_auth_client_t\nset name=#{name},status=#{status},access_ttl_seconds=#{access},\n    refresh_ttl_seconds=#{refresh},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        audit(ctx,\'SUCCESS\',\'clients:save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/23.应用客户端/01.查询应用客户端列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cd43b34d94f84938bab7b9ef685648d7',NULL,'api','{\n  "properties": {},\n  "id": "3fbdbbf3b526546f9c9fbcb38a38784d",\n  "script": null,\n  "groupId": "22234a256a485757b6f81c2c1c3885ed",\n  "name": "02.保存应用客户端",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新应用客户端及必要关联记录，写入审计并返回保存结果。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存应用客户端\n// 路由：POST /idaas/clients/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新应用客户端及必要关联记录，写入审计并返回保存结果。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=operation==\'list\'?\'clients:read\':\'clients:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'clients:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'客户端不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id)) {\n            exit 409,\'客户端应用或版本不一致\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'客户端只能属于业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect count(*) n\nfrom iam_access_grant_t\nwhere client_id=#{id}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").n>0) {\n                exit 409,\'机器身份仍有有效授权\';\n            }\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'clients:remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var key=(r.clientKey||\'\').trim();\n        var type=r.clientType||\'PUBLIC\';\n        if(name==\'\' || name.length()>100 || !key.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || ![\'PUBLIC\',\'CONFIDENTIAL\',\'SERVICE\'].contains(type)) {\n            exit 400,\'客户端名称、编码或类型不正确\';\n        }\n        if(old!=null && (key!=old.client_key || type!=old.client_type)) {\n            exit 400,\'客户端编码和类型保持稳定\';\n        }\n        if(r.protocol!=null && r.protocol!=\'NONE\' || r.status==\'ACTIVE\') {\n            exit 400,\'登记接口不开放认证协议，请在认证接入配置中启用\';\n        }\n        var status=r.status==\'DISABLED\'?\'DISABLED\':\'REGISTERED\';\n        var access=r.accessTtl||600;\n        var refresh=r.refreshTtl||86400;\n        if(access<60 || access>3600 || refresh<access || refresh>604800) {\n            exit 400,\'令牌有效期超限\';\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere client_key=#{key}\n""")!=null) {\n                exit 409,\'客户端编码已经使用\';\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_auth_client_t(tid,\n                app_id, client_key, name, client_type, token_auth_method, access_ttl_seconds,\n                refresh_ttl_seconds, status)\nvalues(#{id},#{appId},#{key},#{name},#{type},#{type==\'PUBLIC\'?\'none\':\'client_secret_basic\'},#{access},#{refresh},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_auth_client_t\nset name=#{name},status=#{status},access_ttl_seconds=#{access},\n    refresh_ttl_seconds=#{refresh},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        audit(ctx,\'SUCCESS\',\'clients:save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/23.应用客户端/02.保存应用客户端.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d45b385d7a6e415e90eb4e03b137c972',NULL,'api','{\n  "properties": {},\n  "id": "db01a757fc205fee8debb0e3cdf6da31",\n  "script": null,\n  "groupId": "22234a256a485757b6f81c2c1c3885ed",\n  "name": "03.归档应用客户端",\n  "createTime": 1790617158595,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载应用客户端并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档应用客户端\n// 路由：POST /idaas/clients/remove\n// 业务说明：按标识加载应用客户端并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。维护应用接入客户端及其协议配置；客户端凭据不随普通列表接口明文返回。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/app-list-context\' as listContext;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n""");\n    var appId=old==null?r.appId||p.appId:old.app_id;\n    var permission=operation==\'list\'?\'clients:read\':\'clients:write\';\n    // 核验会话的功能权限及对象范围，超出范围的请求在读取或写入前拒绝。\n    var ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'clients:\'+operation,p,()=>{\n        old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        if(old==null && p.creating!=true) {\n            exit 404,\'客户端不存在\';\n        }\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id)) {\n            exit 409,\'客户端应用或版本不一致\';\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""")==null) {\n            exit 400,\'客户端只能属于业务应用\';\n        }\n        if(operation==\'remove\') {\n            if(sql.selectOne("""\nselect count(*) n\nfrom iam_access_grant_t\nwhere client_id=#{id}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").n>0) {\n                exit 409,\'机器身份仍有有效授权\';\n            }\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'clients:remove\',id,null,{\n                id:id\n            });\n            return {\n                id:id\n            };\n        }\n        var name=(r.name||\'\').trim();\n        var key=(r.clientKey||\'\').trim();\n        var type=r.clientType||\'PUBLIC\';\n        if(name==\'\' || name.length()>100 || !key.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || ![\'PUBLIC\',\'CONFIDENTIAL\',\'SERVICE\'].contains(type)) {\n            exit 400,\'客户端名称、编码或类型不正确\';\n        }\n        if(old!=null && (key!=old.client_key || type!=old.client_type)) {\n            exit 400,\'客户端编码和类型保持稳定\';\n        }\n        if(r.protocol!=null && r.protocol!=\'NONE\' || r.status==\'ACTIVE\') {\n            exit 400,\'登记接口不开放认证协议，请在认证接入配置中启用\';\n        }\n        var status=r.status==\'DISABLED\'?\'DISABLED\':\'REGISTERED\';\n        var access=r.accessTtl||600;\n        var refresh=r.refreshTtl||86400;\n        if(access<60 || access>3600 || refresh<access || refresh>604800) {\n            exit 400,\'令牌有效期超限\';\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere client_key=#{key}\n""")!=null) {\n                exit 409,\'客户端编码已经使用\';\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_auth_client_t(tid,\n                app_id, client_key, name, client_type, token_auth_method, access_ttl_seconds,\n                refresh_ttl_seconds, status)\nvalues(#{id},#{appId},#{key},#{name},#{type},#{type==\'PUBLIC\'?\'none\':\'client_secret_basic\'},#{access},#{refresh},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_auth_client_t\nset name=#{name},status=#{status},access_ttl_seconds=#{access},\n    refresh_ttl_seconds=#{refresh},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        audit(ctx,\'SUCCESS\',\'clients:save\',id,null,{\n            id:id,appId:appId\n        });\n        return {\n            id:id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/23.应用客户端/03.归档应用客户端.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c44931a9d2d84687a85df97cb6a5d217',NULL,NULL,'{\n  "properties": {},\n  "id": "22234a256a485757b6f81c2c1c3885ed",\n  "name": "23.应用客户端",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/clients",\n  "createTime": 1790617158595,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/23.应用客户端/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9e20352c7af04f3daf0e3159597ef5fc',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/24.租户资料接收/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c032f0402a39415f8b07bea82b007fb6',NULL,'api','{\n  "properties": {},\n  "id": "d523319ceb2b56edbabedb12112417d7",\n  "script": null,\n  "groupId": "955acd903650573fbe414d610962a487",\n  "name": "01.接收中央资料下发",\n  "createTime": 1790618621046,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/v2",\n  "description": "验证标准报文、来源签名或凭据及幂等号，在租户上下文中更新中央来源拥有的人员、机构等字段并返回回执；保留本地密码、角色与停用状态。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.接收中央资料下发\n// 路由：POST /idaas/receiver/v2\n// 业务说明：验证标准报文、来源签名或凭据及幂等号，在租户上下文中更新中央来源拥有的人员、机构等字段并返回回执；保留本地密码、角色与停用状态。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport systemConfig;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nreturn identityRuntime.control(()=>apiCall(()=>{\n    // 34.receiver-apply：仅供本接收接口处理对应的下发对象。\n    var apply=(binding, event, payloadHash)=>{\n        // 本地持久化适配：只替换当前中央来源拥有的字段/关联。密码、本地角色和本地停用不在报文内。\n        // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n        var sql=db.normal();\n        var type=event.objectType;\n        var source=event.objectId;\n        var data=event.data||{};\n        var app=binding.app_id;\n        var tenant=binding.tenant_id;\n        var localApp=binding.local_permission_app_id;\n        var keys=type==\'SUBJECT\'?[\'name\',\'account\',\'phone\',\'email\',\'appointments\',\'roleIds\',\'enabled\']:type==\'ORG\'?[\'name\',\'code\',\'parentId\',\'enabled\']:type==\'ROLE\'?[\'name\',\'code\',\'resourceIds\',\'enabled\']:[\'name\',\'code\',\'parentId\',\'type\',\'path\',\'method\',\'enabled\'];\n        for(k in data.keySet()) {\n            if(!keys.contains(k)) {\n                exit 400,\'报文包含不允许的资料字段\';\n            }\n        }\n        if(event.action!=\'UPSERT\' && data.enabled==true) {\n            exit 400,\'停用或删除事件不能声明来源启用\';\n        }\n        var map=sql.selectOne("""\nselect *\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=#{type}\n    and source_id=#{source}\n    for update\n""");\n        if(map!=null && map.instance_id!=binding.instance_id) {\n            return {\n                result:\'CONFLICT\',message:\'已有映射属于其他接收实例，请办理迁移\',localId:map.local_id\n            };\n        }\n        if(map!=null && map.management_state!=\'MANAGED\') {\n            return {\n                result:\'DETACHED\',message:\'对象已移交本地维护\',localId:map.local_id\n            };\n        }\n        if(map!=null && event.sourceVersion<map.source_version) {\n            return {\n                result:\'STALE\',message:\'接收端已有更高来源版本\',localId:map.local_id,sourceVersion:map.source_version,payloadHash:map.payload_hash\n            };\n        }\n        if(map!=null && event.sourceVersion==map.source_version) {\n            return {\n                result:map.payload_hash==payloadHash?\'DUPLICATE\':\'CONFLICT\',message:map.payload_hash==payloadHash?\'相同来源版本已接收\':\'同版本资料不一致\',localId:map.local_id\n            };\n        }\n        var id=map==null?IdUtil.fastSimpleUUID():map.local_id;\n        var name=(data.name||\'\').trim();\n        var enabled=data.enabled==true?1:0;\n        var prior=map==null || map.snapshot_json==null?{\n            fields:{},orgRelations:[],roleRelations:[],resourceRelations:[]\n        }\n        :identityTransport.parseJson(map.snapshot_json);\n        var table=type==\'ORG\'?\'rm_org_t\':type==\'SUBJECT\'?\'rm_user_t\':type==\'ROLE\'?\'rm_role_t\':\'rm_menu_t\';\n        var local=map==null?null:sql.selectOne(\'select * from \'+table+\' where tenant_id=#{tenant} and id=#{id} and deleted=0 for update\');\n        if(map!=null && local==null) {\n            return {\n                result:\'CONFLICT\',message:\'映射的本地对象已删除\',localId:id\n            };\n        }\n        if(local!=null) {\n            for(k in prior.fields.keySet()) {\n                if(identityTransport.canonicalJson(local.get(k))!=identityTransport.canonicalJson(prior.fields.get(k))) {\n                    return {\n                        result:\'CONFLICT\',message:\'中央拥有字段已在本地修改，请选择脱管或协调资料\',localId:id\n                    };\n                }\n            }\n        }\n        if(name==\'\' || name.length()>(type==\'RESOURCE\'?64:type==\'ROLE\'?100:type==\'SUBJECT\'?50:200)) {\n            return {\n                result:\'CONFLICT\',message:\'资料名称超出本地字段约束\',localId:id\n            };\n        }\n        var fields={};\n        var next={\n            fields:fields,orgRelations:[],roleRelations:[],resourceRelations:[]\n        };\n        var parents=[];\n        var localResources=[];\n        var localRoles=[];\n        var username=null;\n        var code=\'IAM_\'+source;\n        var parentId=null;\n        var path=null;\n        var serial=null;\n        var nature=null;\n        if(type==\'ORG\' || type==\'RESOURCE\') {\n            if(data.parentId!=null && data.parentId!=\'\') {\n                var parent=sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=#{type}\n    and source_id=#{data.parentId}\n    and management_state=\'MANAGED\'\n""");\n                if(parent==null) {\n                    return {\n                        result:\'CONFLICT\',message:\'上级对象尚未接收\',localId:id\n                    };\n                }\n                parentId=parent.local_id;\n            }\n            if(type==\'ORG\') {\n                var parent=parentId==null?null:sql.selectOne("""\nselect org_path,serial_number\nfrom rm_org_t\nwhere tenant_id=#{tenant}\n    and id=#{parentId}\n""");\n                path=(parent==null?\'\':parent.org_path||\'\')+\'/\'+id;\n                serial=parent==null?(local!=null && local.serial_number!=null && local.serial_number.length()==4?local.serial_number:\'I\'+id.substring(0,3).toUpperCase()):parent.serial_number+id.substring(0,4).toUpperCase();\n                nature=parent==null?\'2\':local==null?\'1\':local.nature||\'1\';\n                if(parent==null) {\n                    parentId=\'ROOT\';\n                }\n                if(path.length()>500 || serial.length()>50 || sql.selectOne("""\nselect id\nfrom rm_org_t\nwhere tenant_id=#{tenant}\n    and serial_number=#{serial}\n    and id<>#{id}\n    and deleted=0\n""")!=null) {\n                    return {\n                        result:\'CONFLICT\',message:\'本地机构路径或运行编码冲突，请明确关联\',localId:id\n                    };\n                }\n                fields={\n                    name:name,dept_code:data.code,parent_id:parentId,org_path:path,serial_number:serial,nature:nature\n                };\n                next.fields=fields;\n            }\n            else {\n                var method=data.method||\'GET\';\n                var resourceType=data.type==\'menu\'?0:data.type==\'button\'?1:2;\n                var url=data.path||\'\';\n                if(url.length()>256 || ![\'menu\',\'button\',\'api\'].contains(data.type)) {\n                    return {\n                        result:\'CONFLICT\',message:\'资源类型或路径超出本地约束\',localId:id\n                    };\n                }\n                fields={\n                    name:name,parent_id:parentId,sno:code,url:url,method_name:data.code,status:enabled==1?0:1\n                };\n                next.fields=fields;\n            }\n        }\n        if(type==\'ROLE\') {\n            for(rid in (data.resourceIds||[])) {\n                var resource=sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=\'RESOURCE\'\n    and source_id=#{rid}\n    and management_state=\'MANAGED\'\n""");\n                if(resource==null) {\n                    return {\n                        result:\'CONFLICT\',message:\'角色资源尚未接收\',localId:id\n                    };\n                }\n                localResources.add(resource.local_id);\n            }\n            fields={\n                name:name,code_num:code,status:enabled==1?0:1\n            };\n            next.fields=fields;\n        }\n        if(type==\'SUBJECT\') {\n            username=(data.account||\'\').trim();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || (data.phone||\'\').length()>128 || (data.email||\'\').length()>255) {\n                return {\n                    result:\'CONFLICT\',message:\'拟用账号或联系方式不符合本地约束\',localId:id\n                };\n            }\n            if(sql.selectOne("""\nselect id\nfrom rm_user_t\nwhere tenant_id=#{tenant}\n    and user_name=#{username}\n    and deleted=0\n    and id<>#{id}\n""")!=null) {\n                return {\n                    result:\'CONFLICT\',message:\'同名本地账号须由接收端明确关联，不能自动接管\',localId:id\n                };\n            }\n            for(job in (data.appointments||[])) {\n                var org=sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=\'ORG\'\n    and source_id=#{job.orgId}\n    and management_state=\'MANAGED\'\n""");\n                if(org==null) {\n                    return {\n                        result:\'CONFLICT\',message:\'任职机构尚未接收\',localId:id\n                    };\n                }\n                parents.add({\n                    id:org.local_id,primary:job.primary\n                });\n            }\n            if(enabled==1) {\n                for(rid in (data.roleIds||[])) {\n                    var role=sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=\'ROLE\'\n    and source_id=#{rid}\n    and management_state=\'MANAGED\'\n""");\n                    if(role==null) {\n                        return {\n                            result:\'CONFLICT\',message:\'人员角色尚未接收\',localId:id\n                        };\n                    }\n                    localRoles.add(role.local_id);\n                }\n            }\n            fields={\n                real_name:name,user_name:username,phone:data.phone||\'\',email:data.email||\'\'\n            };\n            next.fields=fields;\n        }\n        // 检查所拥有的关联没有被本地修改；失败发生在任何替换之前。\n        for(pair in [{\n            table:\'rm_user_org_rela_t\',ids:prior.orgRelations||[]\n        },{\n            table:\'rm_user_role_rela_t\',ids:prior.roleRelations||[]\n        },{\n            table:\'rm_role_menu_rela_t\',ids:prior.resourceRelations||[]\n        }]) {\n            for(link in pair.ids) {\n                if(sql.selectOne(\'select id from \'+pair.table+\' where tenant_id=#{tenant} and id=#{link}\')==null) {\n                    return {\n                        result:\'CONFLICT\',message:\'中央来源关联已在本地修改\',localId:id\n                    };\n                }\n            }\n        }\n        if(type==\'ORG\') {\n            if(local==null && sql.selectOne("""\nselect id\nfrom rm_org_t\nwhere tenant_id=#{tenant}\n    and dept_code=#{data.code}\n    and deleted=0\n""")!=null) {\n                return {\n                    result:\'CONFLICT\',message:\'本地已有同编码机构，请明确关联\',localId:id\n                };\n            }\n            if(local==null) {\n                sql.update("""\ninsert into rm_org_t(tenant_id,\n                id, name, parent_id, dept_code, org_path, serial_number, nature, status, deleted, create_time,\n                update_time)\nvalues(#{tenant},#{id},#{name},#{parentId},#{data.code},#{path},#{serial},#{nature},0,0,utc_timestamp(6),utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate rm_org_t\nset name=#{name},parent_id=#{parentId},dept_code=#{data.code},org_path=#{path},\n    serial_number=#{serial},nature=#{nature},update_time=utc_timestamp(6)\nwhere tenant_id=#{tenant}\n    and id=#{id}\n""");\n            }\n        }\n        else if(type==\'RESOURCE\') {\n            if(local==null) {\n                sql.update("""\ninsert into rm_menu_t(tenant_id,\n                id, app_id, name, parent_id, sno, url, method_name, resource_type, status, deleted, create_time,\n                update_time)\nvalues(#{tenant},#{id},#{localApp},#{name},#{parentId},#{code},#{fields.url},#{data.code},#{resourceType},#{fields.status},0,utc_timestamp(6),utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate rm_menu_t\nset name=#{name},parent_id=#{parentId},url=#{fields.url},method_name=#{data.code},\n    resource_type=#{resourceType},status=#{fields.status},update_time=utc_timestamp(6)\nwhere tenant_id=#{tenant}\n    and id=#{id}\n""");\n            }\n        }\n        else if(type==\'ROLE\') {\n            if(local==null) {\n                sql.update("""\ninsert into rm_role_t(tenant_id,\n                id, app_id, name, code_num, status, deleted, create_time, update_time)\nvalues(#{tenant},#{id},#{localApp},#{name},#{code},#{fields.status},0,utc_timestamp(6),utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate rm_role_t\nset name=#{name},status=#{fields.status},update_time=utc_timestamp(6)\nwhere tenant_id=#{tenant}\n    and id=#{id}\n""");\n            }\n            for(link in (prior.resourceRelations||[])) {\n                sql.update("""\ndelete\nfrom rm_role_menu_rela_t\nwhere tenant_id=#{tenant}\n    and id=#{link}\n""");\n            }\n            for(rid in localResources) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into rm_role_menu_rela_t(tenant_id,\n                id, role_id, app_resource_id, extend_id)\nvalues(#{tenant},#{link},#{id},#{rid},\'IDAAS\')\n""");\n                next.resourceRelations.add(link);\n            }\n        }\n        else if(type==\'SUBJECT\') {\n            if(local==null) {\n                sql.update("""\ninsert into rm_user_t(tenant_id,\n                id, real_name, user_name, phone, email, status, deleted, pwd_status, create_time, update_time)\nvalues(#{tenant},#{id},#{name},#{username},#{fields.phone},#{fields.email},1,0,1,utc_timestamp(6),utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate rm_user_t\nset real_name=#{name},user_name=#{username},phone=#{fields.phone},email=#{fields.email},\n    update_time=utc_timestamp(6)\nwhere tenant_id=#{tenant}\n    and id=#{id}\n""");\n            }\n            for(link in (prior.orgRelations||[])) {\n                sql.update("""\ndelete\nfrom rm_user_org_rela_t\nwhere tenant_id=#{tenant}\n    and id=#{link}\n""");\n            }\n            for(org in parents) {\n                var link=IdUtil.fastSimpleUUID();\n                var jobType=org.primary==true?\'1\':\'2\';\n                sql.update("""\ninsert into rm_user_org_rela_t(tenant_id, id, user_id, org_id, job_type)\nvalues(#{tenant},#{link},#{id},#{org.id},#{jobType})\n""");\n                next.orgRelations.add(link);\n            }\n            for(link in (prior.roleRelations||[])) {\n                sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenant}\n    and id=#{link}\n""");\n            }\n            for(rid in localRoles) {\n                var link=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into rm_user_role_rela_t(tenant_id,\n                id, user_id, role_id, auth_from, authority_group_id, is_temporary, edit_time)\nvalues(#{tenant},#{link},#{id},#{rid},9,#{source},0,utc_timestamp(6))\n""");\n                next.roleRelations.add(link);\n            }\n        }\n        var snapshot=identityTransport.canonicalJson(next);\n        if(map==null) {\n            sql.update("""\ninsert into idaas_receiver_object_t(app_id,\n                instance_id, object_type, source_id, local_id, source_version, payload_hash, source_enabled,\n                snapshot_json)\nvalues(#{app},#{binding.instance_id},#{type},#{source},#{id},#{event.sourceVersion},#{payloadHash},#{enabled},#{snapshot})\n""");\n        }\n        else {\n            sql.update("""\nupdate idaas_receiver_object_t\nset source_version=#{event.sourceVersion},payload_hash=#{payloadHash},source_enabled=#{enabled},\n    snapshot_json=#{snapshot},updated_time=utc_timestamp(6)\nwhere app_id=#{app}\n    and object_type=#{type}\n    and source_id=#{source}\n""");\n        }\n        return {\n            result:\'APPLIED\',localId:id,localEnabled:type==\'SUBJECT\'?local!=null && local.status==0 && local.password!=null:false,sourceEnabled:enabled==1,message:\'资料和中央来源关联已提交；本地凭据与停用保持独立\'\n        };\n    };\n    // 54.接收租户公开界面配置：仅供本接收接口处理对应的下发对象。\n    var applyPortal=(binding, event, payloadHash)=>{\n        // 只接收 PORTAL 公开界面配置，不触碰 RUNTIME、账号或授权配置。\n        var sql=db.normal();\n        var app=binding.app_id;\n        var tenant=binding.tenant_id;\n        var data=event.data||{};\n        var names={\n            logo:\'系统标识\',systemName:\'系统名称\',systemCode:\'系统代码\',themeColor:\'主题颜色\',watermarkContent:\'水印内容\',needLogin:\'需要登录\',showShoppingCar:\'显示购物车\',showTagsView:\'显示标签页\',showWatermark:\'显示水印\',version:\'系统版本\'\n        };\n        if(event.action!=\'UPSERT\' || data.size()==0) {\n            exit 400,\'应用界面配置报文不能为空\';\n        }\n        for(code in data.keySet()) {\n            if(!names.containsKey(code) || data.get(code)==null) {\n                exit 400,\'报文包含不支持的应用界面配置\';\n            }\n            var value=\'\'+data.get(code);\n            if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(code)) {\n                if(![\'true\',\'false\'].contains(value)) {\n                    exit 400,\'界面开关配置不正确\';\n                }\n            }\n            else if(code==\'logo\') {\n                if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                    exit 400,\'应用标识格式不正确\';\n                }\n            }\n            else if(code==\'themeColor\') {\n                if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                    exit 400,\'主题颜色格式不正确\';\n                }\n            }\n            else if(code==\'systemCode\') {\n                if(!value.matches(\'[A-Za-z0-9_-]{1,64}\')) {\n                    exit 400,\'系统代码格式不正确\';\n                }\n            }\n            else if(value.length()>(code==\'systemName\'?100:code==\'watermarkContent\'?200:40)) {\n                exit 400,\'界面配置长度超出限制\';\n            }\n        }\n        var map=sql.selectOne("""\nselect *\nfrom idaas_receiver_object_t\nwhere app_id=#{app}\n    and object_type=\'PORTAL_CONFIG\'\n    and source_id=#{app}\n    for update\n""");\n        if(map!=null && (map.instance_id!=binding.instance_id || map.management_state!=\'MANAGED\')) {\n            return {\n                result:\'CONFLICT\',localId:app,message:\'界面配置来源已变更或移交本地维护\'\n            };\n        }\n        if(map!=null && event.sourceVersion<map.source_version) {\n            return {\n                result:\'STALE\',localId:app,sourceVersion:map.source_version,message:\'接收端已有更新的界面配置\'\n            };\n        }\n        if(map!=null && event.sourceVersion==map.source_version) {\n            return {\n                result:map.payload_hash==payloadHash?\'DUPLICATE\':\'CONFLICT\',localId:app,message:map.payload_hash==payloadHash?\'相同配置已接收\':\'同版本界面配置不一致\'\n            };\n        }\n        for(code in data.keySet()) {\n            var value=\'\'+data.get(code);\n            var kind=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(code)?\'BOOLEAN\':\'STRING\';\n            var row=sql.selectOne("""\nselect tid,is_encrypt,config_scope\nfrom sym_config_t\nwhere tenant_id=#{tenant}\n    and config_group=\'PORTAL\'\n    and config_code=#{code}\n    and (is_del=0\n         or is_del is null)\n    for update\n""");\n            if(row!=null && (row.is_encrypt==1 || row.config_scope!=\'PUBLIC\')) {\n                exit 409,\'接收配置与本地非公开配置冲突\';\n            }\n            if(row==null) {\n                var id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into sym_config_t(tid,\n                config_code, config_name, config_value, is_use, sort_no, is_encrypt, is_del, tenant_id,\n                config_group, value_type, config_scope, cache_ttl_seconds, version_no, create_time, update_time)\nvalues(#{id},#{code},#{names.get(code)},#{value},1,0,0,0,#{tenant},\'PORTAL\',#{kind},\'PUBLIC\',1800,1,utc_timestamp(6),utc_timestamp(6))\n""");\n            }\n            else {\n                sql.update("""\nupdate sym_config_t\nset config_value=#{value},is_use=1,value_type=#{kind},config_scope=\'PUBLIC\',version_no=version_no+1,\n    update_time=utc_timestamp(6)\nwhere tid=#{row.tid}\n    and tenant_id=#{tenant}\n    and config_group=\'PORTAL\'\n""");\n            }\n        }\n        var snapshot=JSONUtil.toJsonStr(data);\n        if(map==null) {\n            sql.update("""\ninsert into idaas_receiver_object_t(app_id,\n                instance_id, object_type, source_id, local_id, source_version, payload_hash, source_enabled,\n                snapshot_json)\nvalues(#{app},#{binding.instance_id},\'PORTAL_CONFIG\',#{app},#{app},#{event.sourceVersion},#{payloadHash},1,#{snapshot})\n""");\n        }\n        else {\n            sql.update("""\nupdate idaas_receiver_object_t\nset source_version=#{event.sourceVersion},payload_hash=#{payloadHash},source_enabled=1,snapshot_json=#{snapshot},\n    updated_time=utc_timestamp(6)\nwhere app_id=#{app}\n    and object_type=\'PORTAL_CONFIG\'\n    and source_id=#{app}\n""");\n        }\n        return {\n            result:\'APPLIED\',localId:app,sourceEnabled:true,message:\'公开界面配置已写入租户配置表\'\n        };\n    };\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    // 接收端只接受人工触发的标准下发；回执和随机数用于幂等与防重放。\n    var p=payload||{};\n    if(p.protocol!=\'IDAAS/2\' || p.keyId==null) {\n        exit 400,\'只接受IDAAS/2标准报文\';\n    }\n    var route=identityRuntime.receiverRoute(p.keyId);\n    if(p.targetAppId!=route.appId || p.receiverInstanceId!=route.instanceId) {\n        exit 403,\'接收应用或实例不一致\';\n    }\n    // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n    return identityRuntime.inTenant(route.tenantId,()=>{\n        var sql=db.normal();\n        // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n        var outcome=sql.transaction(()=>{\n            var binding=sql.selectOne("""\nselect *\nfrom idaas_receiver_binding_t\nwhere key_id=#{p.keyId}\n    for update\n""");\n            // 核对接收端密钥、签名、时效和目标实例后才处理下发内容。\n            if(binding==null || binding.enabled!=1 || binding.app_id!=route.appId || binding.instance_id!=route.instanceId || binding.tenant_id!=route.tenantId || !identityTransport.verify2(binding.secret_cipher,p.keyId,route.appId,route.instanceId,p.timestamp,p.nonce,p.payload,p.signature)) {\n                exit 403,\'接收签名、有效期或接入状态无效\';\n            }\n            var event=identityTransport.parseJson(p.payload);\n            var hash=DigestUtil.sha256Hex(p.payload);\n            if(event.appId!=route.appId || event.receiverInstanceId!=route.instanceId) {\n                exit 400,\'事件目标应用或实例不正确\';\n            }\n            if(event.eventId==null || !event.eventId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n                exit 400,\'事件号格式不正确\';\n            }\n            if(event.objectId==null || !event.objectId.matches(\'[A-Za-z0-9_.:-]{1,64}\') || ![\'PING\',\'ORG\',\'SUBJECT\',\'RESOURCE\',\'ROLE\',\'PORTAL_CONFIG\'].contains(event.objectType)) {\n                exit 400,\'对象ID或类型不正确\';\n            }\n            if(![\'UPSERT\',\'DISABLE\',\'REMOVE\'].contains(event.action)) {\n                exit 400,\'事件操作不正确\';\n            }\n            if(identityTransport.canonicalText(p.payload)!=p.payload) {\n                exit 400,\'事件未使用规范JSON\';\n            }\n            if(!(event.sourceVersion instanceof Number) || event.sourceVersion.longValue()!=event.sourceVersion.doubleValue() || event.sourceVersion<1 || event.sourceVersion>9007199254740991L) {\n                exit 400,\'来源版本必须是安全正整数\';\n            }\n            var nonceReceipt=sql.selectOne("""\nselect *\nfrom idaas_receiver_receipt_t\nwhere app_id=#{route.appId}\n    and instance_id=#{route.instanceId}\n    and nonce=#{p.nonce}\n""");\n            if(nonceReceipt!=null && (nonceReceipt.payload_hash!=hash || nonceReceipt.event_id!=event.eventId)) {\n                exit 409,\'随机数不能复用为不同报文\';\n            }\n            var previous=sql.selectOne("""\nselect *\nfrom idaas_receiver_receipt_t\nwhere app_id=#{route.appId}\n    and instance_id=#{route.instanceId}\n    and event_id=#{event.eventId}\norder by created_time desc\nlimit 1\n""");\n            if(previous!=null && (previous.payload_hash!=hash || previous.event_id!=event.eventId)) {\n                exit 409,\'事件号或随机数不能复用为不同报文\';\n            }\n            var result=null;\n            var stateHash=DigestUtil.sha256Hex(identityTransport.canonicalJson({\n                type:event.objectType,id:event.objectId,version:event.sourceVersion,action:event.action,data:event.data\n            }));\n            var prior=previous==null?null:JSONUtil.parseObj(previous.result_json);\n            if(prior!=null && [\'APPLIED\',\'DUPLICATE\'].contains(prior.result)) {\n                result={\n                    result:\'DUPLICATE\',localId:prior.localId,message:\'已持久接收，重复事件不重新写入\'\n                };\n            }\n            else if(event.objectType==\'PING\') {\n                result={\n                    result:\'APPLIED\',localId:\'receiver\',message:\'接收应用、实例与签名核验通过\',objectTypes:[\'ORG\',\'SUBJECT\',\'RESOURCE\',\'ROLE\',\'PORTAL_CONFIG\']\n                };\n            }\n            else if(event.objectType==\'PORTAL_CONFIG\') {\n                if(event.objectId!=route.appId) {\n                    exit 400,\'界面配置只能下发至目标应用\';\n                }\n                result=applyPortal(binding,event,stateHash);\n            }\n            else {\n                result=apply(binding,event,stateHash);\n            }\n            var receipt={\n                protocol:\'IDAAS/2\',appId:route.appId,receiverInstanceId:route.instanceId,eventId:event.eventId,objectType:event.objectType,objectId:event.objectId,sourceVersion:result.sourceVersion||event.sourceVersion,payloadHash:hash,stateHash:stateHash||null,result:result.result,localId:result.localId||\'\',message:result.message,localEnabled:result.localEnabled||false,sourceEnabled:result.sourceEnabled||false\n            };\n            var signature=identityTransport.receiptSignature(binding.secret_cipher,receipt);\n            var encoded=identityTransport.canonicalJson(receipt);\n            if(previous==null || previous.nonce!=p.nonce) {\n                var id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into idaas_receiver_receipt_t(id,\n                app_id, instance_id, event_id, nonce, payload_hash, object_type, source_id, source_version,\n                result_json)\nvalues(#{id},#{route.appId},#{route.instanceId},#{event.eventId},#{p.nonce},#{hash},#{event.objectType},#{event.objectId},#{event.sourceVersion},#{encoded})\n""");\n            }\n            return {\n                receipt:receipt,receiptSignature:signature\n            };\n        });\n        if(outcome.receipt.objectType==\'PORTAL_CONFIG\' && [\'APPLIED\',\'DUPLICATE\'].contains(outcome.receipt.result)) {\n            systemConfig.evict(\'PORTAL\');\n        }\n        return outcome;\n    });\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/24.租户资料接收/01.接收中央资料下发.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('1cb0fca6458d46af9541298b105daa82',NULL,'api','{\n  "properties": {},\n  "id": "8b7e7875e5f35f1bbd3b2ba81fea5373",\n  "script": null,\n  "groupId": "955acd903650573fbe414d610962a487",\n  "name": "02.管理本地接收配置",\n  "createTime": 1790618621046,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/admin",\n  "description": "使用租户本地管理会话维护当前接收实例的地址、凭据或开关；拒绝平台管理会话直接修改租户配置。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.管理本地接收配置\n// 路由：POST /idaas/receiver/admin\n// 业务说明：使用租户本地管理会话维护当前接收实例的地址、凭据或开关；拒绝平台管理会话直接修改租户配置。\nimport db;\nimport identityTransport;\nimport tenantAccounts;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n\n    // 本地系统配置权限仅维护此接收实例；不接受平台管理会话。\n    var sql=db.normal();\n    var p=payload||{};\n    if(!StpUtil.isLogin()) {\n        exit 401,\'请使用本地账号管理接收配置\';\n    }\n    var tenantId=tenantAccounts.session().get(\'tenantId\');\n    if(tenantId==null || !tenantAccounts.isLocal(tenantId)) {\n        exit 401,\'请使用本地账号管理接收配置\';\n    }\n    // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n    return identityRuntime.inTenant(tenantId,()=>{\n        var actor=StpUtil.getLoginId()+\'\';\n        var permissionApp=tenantAccounts.session().get(\'appId\');\n        if(sql.selectOne("""\nselect r.id\nfrom rm_user_role_rela_t u\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.deleted=0\nand r.status=0\njoin rm_role_menu_rela_t rr on rr.role_id=r.id\nand rr.tenant_id=r.tenant_id\njoin rm_menu_t m on m.id=rr.app_resource_id\nand m.tenant_id=rr.tenant_id\nand m.deleted=0\nand m.url=\'/setting\'\nwhere u.user_id=#{actor}\n    and u.tenant_id=#{tenantId}\n    and r.app_id=#{permissionApp}\n    and (u.end_time is null\n         or u.end_time>utc_timestamp(6))\nlimit 1\n""")==null) {\n            exit 403,\'需要本地系统配置权限\';\n        }\n        if((p.action||\'read\')==\'read\') {\n            return sql.select("""\nselect key_id keyId,app_id appId,instance_id instanceId,enabled,version,credential_version credentialVersion\nfrom idaas_receiver_binding_t\nwhere tenant_id=#{tenantId}\n""");\n        }\n        var route=identityRuntime.receiverRoute(p.keyId);\n        if(route.tenantId!=tenantId || route.appId!=p.appId || route.instanceId!=p.instanceId) {\n            exit 400,\'与部署登记的接收实例不一致\';\n        }\n        // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n        return sql.transaction(()=>{\n            var old=sql.selectOne("""\nselect *\nfrom idaas_receiver_binding_t\nwhere key_id=#{p.keyId}\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'接收配置已变更\';\n            }\n            var action=p.action;\n            var enabled=p.enabled==true?1:0;\n            if(old==null && action!=\'save\') {\n                exit 404,\'请先登记接收配置\';\n            }\n            var recordAction=(operation,source,kind)=>{\n                var aid=IdUtil.fastSimpleUUID();\n                var nonce=IdUtil.fastSimpleUUID();\n                var encoded=identityTransport.canonicalJson({\n                    action:operation,actor:actor,objectType:kind,sourceId:source\n                });\n                var hash=DigestUtil.sha256Hex(encoded);\n                sql.update("""\ninsert into idaas_receiver_receipt_t(id,\n                app_id, instance_id, event_id, nonce, payload_hash, object_type, source_id, source_version,\n                result_json)\nvalues(#{aid},#{route.appId},#{route.instanceId},#{aid},#{nonce},#{hash},\'ADMIN\',#{source},1,#{encoded})\n""");\n            };\n            if(action==\'inspect-link\' || action==\'link\') {\n                if(![\'SUBJECT\',\'ORG\'].contains(p.objectType) || p.sourceId==null || !p.sourceId.matches(\'[A-Za-z0-9_.:-]{1,64}\') || p.localId==null) {\n                    exit 400,\'只支持明确关联人员或机构\';\n                }\n                var table=p.objectType==\'SUBJECT\'?\'rm_user_t\':\'rm_org_t\';\n                var local=sql.selectOne(\'select * from \'+table+\' where tenant_id=#{tenantId} and id=#{p.localId} and deleted=0 for update\');\n                if(local==null) {\n                    exit 404,\'本地对象不存在\';\n                }\n                var fields=p.objectType==\'SUBJECT\'?{\n                    real_name:local.real_name,user_name:local.user_name,phone:local.phone,email:local.email\n                }\n                :{\n                    name:local.name,dept_code:local.dept_code,parent_id:local.parent_id,org_path:local.org_path\n                };\n                var proof=DigestUtil.sha256Hex(identityTransport.canonicalJson(fields));\n                if(action==\'inspect-link\') {\n                    return {\n                        localId:p.localId,objectType:p.objectType,proof:proof,requiresPrimaryConsent:p.objectType==\'SUBJECT\'\n                    };\n                }\n                if(p.proof!=proof || p.confirmOwnership!=true || p.objectType==\'SUBJECT\' && p.replacePrimary!=true) {\n                    exit 409,\'请核对本地资料并明确同意转交资料和主任职维护\';\n                }\n                if(sql.selectOne("""\nselect source_id\nfrom idaas_receiver_object_t\nwhere app_id=#{route.appId}\n    and ((object_type=#{p.objectType}\n          and source_id=#{p.sourceId})\n         or (object_type=#{p.objectType}\n             and local_id=#{p.localId}))\n""")!=null) {\n                    exit 409,\'中央或本地对象已有来源映射\';\n                }\n                var orgRelations=p.objectType==\'SUBJECT\'?sql.select("""\nselect id\nfrom rm_user_org_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{p.localId}\n    and job_type=\'1\'\n""").map(r=>r.id):[];\n                var snapshot=identityTransport.canonicalJson({\n                    fields:fields,orgRelations:orgRelations,roleRelations:[],resourceRelations:[]\n                });\n                sql.update("""\ninsert into idaas_receiver_object_t(app_id,\n                instance_id, object_type, source_id, local_id, source_version, payload_hash, source_enabled,\n                snapshot_json)\nvalues(#{route.appId},#{route.instanceId},#{p.objectType},#{p.sourceId},#{p.localId},0,#{proof},1,#{snapshot})\n""");\n                recordAction(\'link\',p.sourceId,p.objectType);\n                return {\n                    linked:true,localId:p.localId\n                };\n            }\n            if(action==\'detach\') {\n                var object=sql.selectOne("""\nselect *\nfrom idaas_receiver_object_t\nwhere app_id=#{route.appId}\n    and object_type=#{p.objectType}\n    and source_id=#{p.sourceId}\n    for update\n""");\n                if(object==null || object.source_version!=p.sourceVersion) {\n                    exit 409,\'来源对象版本已变更\';\n                }\n                sql.update("""\nupdate idaas_receiver_object_t\nset management_state=\'DETACHED\',source_enabled=1,updated_time=utc_timestamp(6)\nwhere app_id=#{route.appId}\n    and object_type=#{p.objectType}\n    and source_id=#{p.sourceId}\n""");\n                recordAction(\'detach\',p.sourceId,p.objectType);\n                return {\n                    detached:true\n                };\n            }\n            if(action!=\'save\') {\n                exit 400,\'配置操作不正确\';\n            }\n            var cipher=p.secret==null || p.secret==\'\'?old==null?null:old.secret_cipher:identityTransport.encrypt(p.secret);\n            if(cipher==null) {\n                exit 400,\'接收密钥不能为空\';\n            }\n            if(old==null) {\n                sql.update("""\ninsert into idaas_receiver_binding_t(key_id,\n                app_id, instance_id, tenant_id, local_permission_app_id, secret_cipher, enabled)\nvalues(#{p.keyId},#{route.appId},#{route.instanceId},#{tenantId},#{permissionApp},#{cipher},#{enabled})\n""");\n            }\n            else {\n                var rotation=p.secret!=null && p.secret!=\'\'?1:0;\n                sql.update("""\nupdate idaas_receiver_binding_t\nset secret_cipher=#{cipher},enabled=#{enabled},credential_version=credential_version+#{rotation},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere key_id=#{p.keyId}\n""");\n            }\n            recordAction(\'save\',p.keyId,\'CONFIG\');\n            return {\n                keyId:p.keyId,saved:true\n            };\n        });\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/24.租户资料接收/02.管理本地接收配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('eeb4a669e6104570b21b9bc76b670783',NULL,NULL,'{\n  "properties": {},\n  "id": "955acd903650573fbe414d610962a487",\n  "name": "24.租户资料接收",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/receiver",\n  "createTime": 1790618621046,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/24.租户资料接收/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('18ed293736b645abab4005f2435ee5c4',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('96ce839fed9446d38eca5cc63b24402d',NULL,'api','{\n  "properties": {},\n  "id": "868fca7d381256fd95e5d01079062df0",\n  "script": null,\n  "groupId": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "01.查询统一认证账号列表",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "读取符合请求筛选条件的统一认证账号，应用权限及身份域过滤后返回可展示字段；不发生写入。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询统一认证账号列表\n// 路由：GET /idaas/auth-accounts/list\n// 业务说明：读取符合请求筛选条件的统一认证账号，应用权限及身份域过滤后返回可展示字段；不发生写入。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。\nimport db;\nimport authSession;\nimport iamSecurity;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 统一认证账号不属于平台操作账号，也不写应用本地用户或本地密码。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'auth-accounts:read\':\'auth-accounts:write\',null,domain);\n    var id=r.id||p.id;\n    if(operation==\'list\') {\n        return sql.select("""\nselect a.tid as id,a.subject_id subjectId,a.identity_domain domain,a.username,a.status,\n        a.must_change_password mustChangePassword,a.legal_entity_id legalEntityId,\n        a.version,s.name\nfrom iam_auth_account_t a\njoin iam_subject_t s on s.tid=a.subject_id\nwhere a.identity_domain=#{domain}\n    and a.is_del=0\norder by a.created_time desc\nlimit 250\n""");\n    }\n    var output=mutate(ctx,\'auth-accounts:\'+operation,p,()=>{\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_account_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'账号范围或版本已变更\';\n        }\n        if(operation==\'bind-entity\') {\n            if(old==null || domain!=\'public\') {\n                exit 400,\'只允许绑定公众认证账号\';\n            }\n            var entityId=p.entityId;\n            if(entityId!=null && entityId!=\'\' && sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nwhere m.entity_id=#{entityId}\n    and m.subject_id=#{old.subject_id}\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n    and exists\n        (select 1\n         from iam_verification_t v\n         where v.target_type=\'LEGAL_ENTITY\'\n             and v.target_id=e.tid\n             and v.status=\'VERIFIED\'\n             and v.expires_at>utc_timestamp(6)\n             and v.tid=\n                 (select x.tid as id\n                  from iam_verification_t x\n                  where x.target_type=\'LEGAL_ENTITY\'\n                      and x.target_id=e.tid\n                  order by x.requested_time desc, x.tid desc\n                  limit 1))\nlimit 1\n""")==null) {\n                exit 403,\'法人核验或经办关系尚未生效\';\n            }\n            entityId=entityId==\'\'?null:entityId;\n            sql.update("""\nupdate iam_auth_account_t\nset legal_entity_id=#{entityId},version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            sql.update("""\nupdate iam_auth_account_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'reset\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            passwordPolicy(p.password);\n            sql.update("""\nupdate iam_auth_account_t\nset must_change_password=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{r.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n            if(subject==null) {\n                exit 400,\'必须关联同域人员\';\n            }\n            var username=(r.username||\'\').trim().toLowerCase();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || old!=null && (old.subject_id!=r.subjectId || old.username!=username)) {\n                exit 400,\'认证账号、主体和身份域保持稳定\';\n            }\n            var status=r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(old==null) {\n                if(p.creating!=true) {\n                    exit 404,\'认证账号不存在\';\n                }\n                passwordPolicy(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_account_t\nwhere identity_domain=#{domain}\n    and active_username=#{username}\n""")!=null) {\n                    exit 409,\'认证账号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_auth_account_t(tid,\n                subject_id, identity_domain, username, status, must_change_password)\nvalues(#{id},#{r.subjectId},#{domain},#{username},#{status},1)\n""");\n                var security=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_account_security_t(tid, principal_kind, principal_id)\nvalues(#{security},\'AUTH_ACCOUNT\',#{id})\n""");\n            }\n            else {\n                if(r.legalEntityId!=old.legal_entity_id && r.legalEntityId!=null) {\n                    exit 400,\'法人认证上下文须通过有效经办关系显式绑定\';\n                }\n                sql.update("""\nupdate iam_auth_account_t\nset status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            exit 400,\'账号操作不正确\';\n        }\n        if(old==null || operation==\'reset\') {\n            var password=operation==\'reset\'?p.password:r.password;\n            var encoded=iamSecurity.hash(password);\n            var prior=sql.selectOne("""\nselect revision\nfrom iam_credential_t\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var revision=prior==null?1:prior.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var cid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{cid},\'AUTH_ACCOUNT\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n        }\n        if(old!=null) {\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'ACCOUNT_ADMIN_CHANGED\'\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n    and revoked_at is null\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth-accounts:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n    if(output.id!=null) {\n        authSession.revoke(output.id);\n    }\n    return output;\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/01.查询统一认证账号列表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('460d3cd8cb4f4c27b4f582beedfb3de1',NULL,'api','{\n  "properties": {},\n  "id": "ac7b2ac7fc9155e7937e23909b279301",\n  "script": null,\n  "groupId": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "02.保存统一认证账号",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "description": "校验请求字段、所属范围和版本；新建或更新统一认证账号及必要关联记录，写入审计并返回保存结果。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存统一认证账号\n// 路由：POST /idaas/auth-accounts/save\n// 业务说明：校验请求字段、所属范围和版本；新建或更新统一认证账号及必要关联记录，写入审计并返回保存结果。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。\nimport db;\nimport authSession;\nimport iamSecurity;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save\';\n\n    // 统一认证账号不属于平台操作账号，也不写应用本地用户或本地密码。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'auth-accounts:read\':\'auth-accounts:write\',null,domain);\n    var id=r.id||p.id;\n    var output=mutate(ctx,\'auth-accounts:\'+operation,p,()=>{\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_account_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'账号范围或版本已变更\';\n        }\n        if(operation==\'bind-entity\') {\n            if(old==null || domain!=\'public\') {\n                exit 400,\'只允许绑定公众认证账号\';\n            }\n            var entityId=p.entityId;\n            if(entityId!=null && entityId!=\'\' && sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nwhere m.entity_id=#{entityId}\n    and m.subject_id=#{old.subject_id}\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n    and exists\n        (select 1\n         from iam_verification_t v\n         where v.target_type=\'LEGAL_ENTITY\'\n             and v.target_id=e.tid\n             and v.status=\'VERIFIED\'\n             and v.expires_at>utc_timestamp(6)\n             and v.tid=\n                 (select x.tid as id\n                  from iam_verification_t x\n                  where x.target_type=\'LEGAL_ENTITY\'\n                      and x.target_id=e.tid\n                  order by x.requested_time desc, x.tid desc\n                  limit 1))\nlimit 1\n""")==null) {\n                exit 403,\'法人核验或经办关系尚未生效\';\n            }\n            entityId=entityId==\'\'?null:entityId;\n            sql.update("""\nupdate iam_auth_account_t\nset legal_entity_id=#{entityId},version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            sql.update("""\nupdate iam_auth_account_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'reset\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            passwordPolicy(p.password);\n            sql.update("""\nupdate iam_auth_account_t\nset must_change_password=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{r.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n            if(subject==null) {\n                exit 400,\'必须关联同域人员\';\n            }\n            var username=(r.username||\'\').trim().toLowerCase();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || old!=null && (old.subject_id!=r.subjectId || old.username!=username)) {\n                exit 400,\'认证账号、主体和身份域保持稳定\';\n            }\n            var status=r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(old==null) {\n                if(p.creating!=true) {\n                    exit 404,\'认证账号不存在\';\n                }\n                passwordPolicy(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_account_t\nwhere identity_domain=#{domain}\n    and active_username=#{username}\n""")!=null) {\n                    exit 409,\'认证账号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_auth_account_t(tid,\n                subject_id, identity_domain, username, status, must_change_password)\nvalues(#{id},#{r.subjectId},#{domain},#{username},#{status},1)\n""");\n                var security=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_account_security_t(tid, principal_kind, principal_id)\nvalues(#{security},\'AUTH_ACCOUNT\',#{id})\n""");\n            }\n            else {\n                if(r.legalEntityId!=old.legal_entity_id && r.legalEntityId!=null) {\n                    exit 400,\'法人认证上下文须通过有效经办关系显式绑定\';\n                }\n                sql.update("""\nupdate iam_auth_account_t\nset status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            exit 400,\'账号操作不正确\';\n        }\n        if(old==null || operation==\'reset\') {\n            var password=operation==\'reset\'?p.password:r.password;\n            var encoded=iamSecurity.hash(password);\n            var prior=sql.selectOne("""\nselect revision\nfrom iam_credential_t\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var revision=prior==null?1:prior.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var cid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{cid},\'AUTH_ACCOUNT\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n        }\n        if(old!=null) {\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'ACCOUNT_ADMIN_CHANGED\'\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n    and revoked_at is null\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth-accounts:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n    if(output.id!=null) {\n        authSession.revoke(output.id);\n    }\n    return output;\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/02.保存统一认证账号.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('242c291792a64481bbe556fe83d10535',NULL,'api','{\n  "properties": {},\n  "id": "9bd42419c58f5ea19ebc0e16a230e07b",\n  "script": null,\n  "groupId": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "03.归档统一认证账号",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/remove",\n  "description": "按标识加载统一认证账号并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.归档统一认证账号\n// 路由：POST /idaas/auth-accounts/remove\n// 业务说明：按标识加载统一认证账号并检查所属范围与版本；执行软删除或撤销关联，保留审计历史。统一认证账号与平台操作账号、租户本地账号是三套隔离的身份体系。\nimport db;\nimport authSession;\nimport iamSecurity;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'remove\';\n\n    // 统一认证账号不属于平台操作账号，也不写应用本地用户或本地密码。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'auth-accounts:read\':\'auth-accounts:write\',null,domain);\n    var id=r.id||p.id;\n    var output=mutate(ctx,\'auth-accounts:\'+operation,p,()=>{\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_account_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'账号范围或版本已变更\';\n        }\n        if(operation==\'bind-entity\') {\n            if(old==null || domain!=\'public\') {\n                exit 400,\'只允许绑定公众认证账号\';\n            }\n            var entityId=p.entityId;\n            if(entityId!=null && entityId!=\'\' && sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nwhere m.entity_id=#{entityId}\n    and m.subject_id=#{old.subject_id}\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n    and exists\n        (select 1\n         from iam_verification_t v\n         where v.target_type=\'LEGAL_ENTITY\'\n             and v.target_id=e.tid\n             and v.status=\'VERIFIED\'\n             and v.expires_at>utc_timestamp(6)\n             and v.tid=\n                 (select x.tid as id\n                  from iam_verification_t x\n                  where x.target_type=\'LEGAL_ENTITY\'\n                      and x.target_id=e.tid\n                  order by x.requested_time desc, x.tid desc\n                  limit 1))\nlimit 1\n""")==null) {\n                exit 403,\'法人核验或经办关系尚未生效\';\n            }\n            entityId=entityId==\'\'?null:entityId;\n            sql.update("""\nupdate iam_auth_account_t\nset legal_entity_id=#{entityId},version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            sql.update("""\nupdate iam_auth_account_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'reset\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            passwordPolicy(p.password);\n            sql.update("""\nupdate iam_auth_account_t\nset must_change_password=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{r.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n            if(subject==null) {\n                exit 400,\'必须关联同域人员\';\n            }\n            var username=(r.username||\'\').trim().toLowerCase();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || old!=null && (old.subject_id!=r.subjectId || old.username!=username)) {\n                exit 400,\'认证账号、主体和身份域保持稳定\';\n            }\n            var status=r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(old==null) {\n                if(p.creating!=true) {\n                    exit 404,\'认证账号不存在\';\n                }\n                passwordPolicy(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_account_t\nwhere identity_domain=#{domain}\n    and active_username=#{username}\n""")!=null) {\n                    exit 409,\'认证账号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_auth_account_t(tid,\n                subject_id, identity_domain, username, status, must_change_password)\nvalues(#{id},#{r.subjectId},#{domain},#{username},#{status},1)\n""");\n                var security=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_account_security_t(tid, principal_kind, principal_id)\nvalues(#{security},\'AUTH_ACCOUNT\',#{id})\n""");\n            }\n            else {\n                if(r.legalEntityId!=old.legal_entity_id && r.legalEntityId!=null) {\n                    exit 400,\'法人认证上下文须通过有效经办关系显式绑定\';\n                }\n                sql.update("""\nupdate iam_auth_account_t\nset status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            exit 400,\'账号操作不正确\';\n        }\n        if(old==null || operation==\'reset\') {\n            var password=operation==\'reset\'?p.password:r.password;\n            var encoded=iamSecurity.hash(password);\n            var prior=sql.selectOne("""\nselect revision\nfrom iam_credential_t\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var revision=prior==null?1:prior.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var cid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{cid},\'AUTH_ACCOUNT\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n        }\n        if(old!=null) {\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'ACCOUNT_ADMIN_CHANGED\'\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n    and revoked_at is null\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth-accounts:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n    if(output.id!=null) {\n        authSession.revoke(output.id);\n    }\n    return output;\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/03.归档统一认证账号.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7396146c8ae54a34b7d406d631d7923c',NULL,'api','{\n  "properties": {},\n  "id": "0f99e70984075175aeb9b134185c0932",\n  "script": null,\n  "groupId": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "04.重置统一认证账号密码",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/reset",\n  "description": "校验统一认证账号及管理权限，按密码策略更新独立凭据并废止旧会话，不影响平台或租户本地账号。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.重置统一认证账号密码\n// 路由：POST /idaas/auth-accounts/reset\n// 业务说明：校验统一认证账号及管理权限，按密码策略更新独立凭据并废止旧会话，不影响平台或租户本地账号。\nimport db;\nimport authSession;\nimport iamSecurity;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'reset\';\n\n    // 统一认证账号不属于平台操作账号，也不写应用本地用户或本地密码。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'auth-accounts:read\':\'auth-accounts:write\',null,domain);\n    var id=r.id||p.id;\n    var output=mutate(ctx,\'auth-accounts:\'+operation,p,()=>{\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_account_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'账号范围或版本已变更\';\n        }\n        if(operation==\'bind-entity\') {\n            if(old==null || domain!=\'public\') {\n                exit 400,\'只允许绑定公众认证账号\';\n            }\n            var entityId=p.entityId;\n            if(entityId!=null && entityId!=\'\' && sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nwhere m.entity_id=#{entityId}\n    and m.subject_id=#{old.subject_id}\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n    and exists\n        (select 1\n         from iam_verification_t v\n         where v.target_type=\'LEGAL_ENTITY\'\n             and v.target_id=e.tid\n             and v.status=\'VERIFIED\'\n             and v.expires_at>utc_timestamp(6)\n             and v.tid=\n                 (select x.tid as id\n                  from iam_verification_t x\n                  where x.target_type=\'LEGAL_ENTITY\'\n                      and x.target_id=e.tid\n                  order by x.requested_time desc, x.tid desc\n                  limit 1))\nlimit 1\n""")==null) {\n                exit 403,\'法人核验或经办关系尚未生效\';\n            }\n            entityId=entityId==\'\'?null:entityId;\n            sql.update("""\nupdate iam_auth_account_t\nset legal_entity_id=#{entityId},version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            sql.update("""\nupdate iam_auth_account_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'reset\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            passwordPolicy(p.password);\n            sql.update("""\nupdate iam_auth_account_t\nset must_change_password=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{r.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n            if(subject==null) {\n                exit 400,\'必须关联同域人员\';\n            }\n            var username=(r.username||\'\').trim().toLowerCase();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || old!=null && (old.subject_id!=r.subjectId || old.username!=username)) {\n                exit 400,\'认证账号、主体和身份域保持稳定\';\n            }\n            var status=r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(old==null) {\n                if(p.creating!=true) {\n                    exit 404,\'认证账号不存在\';\n                }\n                passwordPolicy(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_account_t\nwhere identity_domain=#{domain}\n    and active_username=#{username}\n""")!=null) {\n                    exit 409,\'认证账号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_auth_account_t(tid,\n                subject_id, identity_domain, username, status, must_change_password)\nvalues(#{id},#{r.subjectId},#{domain},#{username},#{status},1)\n""");\n                var security=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_account_security_t(tid, principal_kind, principal_id)\nvalues(#{security},\'AUTH_ACCOUNT\',#{id})\n""");\n            }\n            else {\n                if(r.legalEntityId!=old.legal_entity_id && r.legalEntityId!=null) {\n                    exit 400,\'法人认证上下文须通过有效经办关系显式绑定\';\n                }\n                sql.update("""\nupdate iam_auth_account_t\nset status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            exit 400,\'账号操作不正确\';\n        }\n        if(old==null || operation==\'reset\') {\n            var password=operation==\'reset\'?p.password:r.password;\n            var encoded=iamSecurity.hash(password);\n            var prior=sql.selectOne("""\nselect revision\nfrom iam_credential_t\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var revision=prior==null?1:prior.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var cid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{cid},\'AUTH_ACCOUNT\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n        }\n        if(old!=null) {\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'ACCOUNT_ADMIN_CHANGED\'\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n    and revoked_at is null\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth-accounts:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n    if(output.id!=null) {\n        authSession.revoke(output.id);\n    }\n    return output;\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/04.重置统一认证账号密码.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('abaf6ff8b88e4755a7d45a267d680653',NULL,'api','{\n  "properties": {},\n  "id": "1fc70fed3a2c53f5af5fbd6dd694076d",\n  "script": null,\n  "groupId": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "05.绑定法人办理身份",\n  "createTime": 1790636427981,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/bind-entity",\n  "description": "核验统一认证账号和目标法人状态后建立成员关系，记录办理身份范围与审计。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.绑定法人办理身份\n// 路由：POST /idaas/auth-accounts/bind-entity\n// 业务说明：核验统一认证账号和目标法人状态后建立成员关系，记录办理身份范围与审计。\nimport db;\nimport authSession;\nimport iamSecurity;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/password-policy\' as passwordPolicy;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'bind-entity\';\n\n    // 统一认证账号不属于平台操作账号，也不写应用本地用户或本地密码。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var r=p.record||p;\n    var domain=r.domain||p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'list\'?\'auth-accounts:read\':\'auth-accounts:write\',null,domain);\n    var id=r.id||p.id;\n    var output=mutate(ctx,\'auth-accounts:\'+operation,p,()=>{\n        var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_account_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n        // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n        if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n            exit 409,\'账号范围或版本已变更\';\n        }\n        if(operation==\'bind-entity\') {\n            if(old==null || domain!=\'public\') {\n                exit 400,\'只允许绑定公众认证账号\';\n            }\n            var entityId=p.entityId;\n            if(entityId!=null && entityId!=\'\' && sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nwhere m.entity_id=#{entityId}\n    and m.subject_id=#{old.subject_id}\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n    and exists\n        (select 1\n         from iam_verification_t v\n         where v.target_type=\'LEGAL_ENTITY\'\n             and v.target_id=e.tid\n             and v.status=\'VERIFIED\'\n             and v.expires_at>utc_timestamp(6)\n             and v.tid=\n                 (select x.tid as id\n                  from iam_verification_t x\n                  where x.target_type=\'LEGAL_ENTITY\'\n                      and x.target_id=e.tid\n                  order by x.requested_time desc, x.tid desc\n                  limit 1))\nlimit 1\n""")==null) {\n                exit 403,\'法人核验或经办关系尚未生效\';\n            }\n            entityId=entityId==\'\'?null:entityId;\n            sql.update("""\nupdate iam_auth_account_t\nset legal_entity_id=#{entityId},version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'remove\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            sql.update("""\nupdate iam_auth_account_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'reset\') {\n            if(old==null) {\n                exit 404,\'账号不存在\';\n            }\n            passwordPolicy(p.password);\n            sql.update("""\nupdate iam_auth_account_t\nset must_change_password=1,version=version+1\nwhere tid=#{id}\n""");\n        }\n        else if(operation==\'save\') {\n            var subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{r.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n            if(subject==null) {\n                exit 400,\'必须关联同域人员\';\n            }\n            var username=(r.username||\'\').trim().toLowerCase();\n            if(!username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\') || old!=null && (old.subject_id!=r.subjectId || old.username!=username)) {\n                exit 400,\'认证账号、主体和身份域保持稳定\';\n            }\n            var status=r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n            if(old==null) {\n                if(p.creating!=true) {\n                    exit 404,\'认证账号不存在\';\n                }\n                passwordPolicy(r.password);\n                if(sql.selectOne("""\nselect tid as id\nfrom iam_auth_account_t\nwhere identity_domain=#{domain}\n    and active_username=#{username}\n""")!=null) {\n                    exit 409,\'认证账号已使用\';\n                }\n                id=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_auth_account_t(tid,\n                subject_id, identity_domain, username, status, must_change_password)\nvalues(#{id},#{r.subjectId},#{domain},#{username},#{status},1)\n""");\n                var security=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_account_security_t(tid, principal_kind, principal_id)\nvalues(#{security},\'AUTH_ACCOUNT\',#{id})\n""");\n            }\n            else {\n                if(r.legalEntityId!=old.legal_entity_id && r.legalEntityId!=null) {\n                    exit 400,\'法人认证上下文须通过有效经办关系显式绑定\';\n                }\n                sql.update("""\nupdate iam_auth_account_t\nset status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n            }\n        }\n        else {\n            exit 400,\'账号操作不正确\';\n        }\n        if(old==null || operation==\'reset\') {\n            var password=operation==\'reset\'?p.password:r.password;\n            var encoded=iamSecurity.hash(password);\n            var prior=sql.selectOne("""\nselect revision\nfrom iam_credential_t\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var revision=prior==null?1:prior.revision+1;\n            sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere owner_kind=\'AUTH_ACCOUNT\'\n    and owner_id=#{id}\n    and credential_type=\'PASSWORD\'\n    and status=\'ACTIVE\'\n""");\n            var cid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{cid},\'AUTH_ACCOUNT\',#{id},\'PASSWORD\',#{revision},\'PBKDF2_SHA256\',#{encoded},\'ACTIVE\')\n""");\n        }\n        if(old!=null) {\n            sql.update("""\nupdate iam_account_security_t\nset security_version=security_version+1,failed_count=0,locked_until=null\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'ACCOUNT_ADMIN_CHANGED\'\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{id}\n    and revoked_at is null\n""");\n        }\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth-accounts:\'+operation,id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    });\n    if(output.id!=null) {\n        authSession.revoke(output.id);\n    }\n    return output;\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/05.绑定法人办理身份.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('875ae4e7358a4aeb978e34e30e764ec9',NULL,NULL,'{\n  "properties": {},\n  "id": "e325afaf57bd5e38b68f38837525b3b0",\n  "name": "25.统一认证账号",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/auth-accounts",\n  "createTime": 1790635007936,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/25.统一认证账号/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b6eea3c03301468c944aceca2e7432c5',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/26.认证协议配置/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cfbf91170e874d92ac8e67a5f0989c5a',NULL,'api','{\n  "properties": {},\n  "id": "f4c91e5297f253d7a83356038bfbf6cd",\n  "script": null,\n  "groupId": "1e4c952752445b3b8a68635e161010ed",\n  "name": "01.读取应用认证协议配置",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/read",\n  "description": "读取指定应用的统一认证协议开通状态、客户端及回调配置，对密钥脱敏后供管理界面展示。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.读取应用认证协议配置\n// 路由：GET /idaas/protocol-config/read\n// 业务说明：读取指定应用的统一认证协议开通状态、客户端及回调配置，对密钥脱敏后供管理界面展示。\nimport db;\nimport identityProtocol;\nimport identityTransport;\nimport java.net.URI;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'read\';\n\n    // 显式启用客户端和可选统一认证。登记、协议开通、应用认证模式分别维护。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var client=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    and is_del=0\n""");\n    if(client==null) {\n        exit 404,\'请先登记客户端\';\n    }\n    var domain=p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'read\'?\'clients:read\':\'clients:write\',client.app_id,domain);\n    if(operation==\'read\') {\n        return {\n            id:client.id,version:client.version,protocol:client.protocol,status:client.status,clientType:client.client_type,grantTypes:client.grant_types==null?[]:JSONUtil.parseArray(client.grant_types),scopes:client.scopes==null?[]:JSONUtil.parseArray(client.scopes),redirects:sql.select("""\nselect uri,uri_type type\nfrom iam_auth_redirect_t\nwhere client_id=#{client.id}\n"""),hasSecret:sql.selectOne("""\nselect tid as id\nfrom iam_credential_t\nwhere owner_kind=\'CLIENT\'\n    and owner_id=#{client.id}\n    and credential_type=\'CLIENT_SECRET\'\n    and status=\'ACTIVE\'\n""")!=null\n        };\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'protocol:\'+operation,p,()=>{\n        var c=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(c.version!=p.version) {\n            exit 409,\'客户端配置已变更\';\n        }\n        if(operation==\'federation\') {\n            guard(\'apps:write\',c.app_id,domain);\n            var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{c.app_id}\n    and kind=\'BUSINESS\'\n    and is_del=0\n    for update\n""");\n            if(app==null || app.version!=p.appVersion) {\n                exit 409,\'应用版本已变更\';\n            }\n            if(p.enabled==true && sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere app_id=#{c.app_id}\n    and protocol=\'OIDC\'\n    and status=\'ACTIVE\'\n    and is_del=0\nlimit 1\n""")==null) {\n                exit 409,\'应用尚未配置活动认证客户端\';\n            }\n            var mode=p.enabled==true?\'FEDERATED\':\'LOCAL\';\n            sql.update("""\nupdate iam_application_t\nset auth_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.app_id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'protocol:federation\',c.app_id,null,{\n                id:c.app_id,mode:mode\n            });\n            return {\n                id:c.app_id,mode:mode\n            };\n        }\n        if(operation==\'disable\') {\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',version=version+1\nwhere tid=#{c.id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_DISABLED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n            audit(ctx,\'SUCCESS\',\'protocol:disable\',c.id,null,{\n                id:c.id\n            });\n            return {\n                id:c.id\n            };\n        }\n        if(operation!=\'configure\' && operation!=\'rotate\') {\n            exit 400,\'认证接入操作不正确\';\n        }\n        var grants=c.client_type==\'SERVICE\'?[\'client_credentials\']:c.client_type==\'PUBLIC\'?[\'authorization_code\']:[\'authorization_code\',\'refresh_token\'];\n        var scopes=p.scopes||[];\n        var allowed=[\'openid\',\'profile\',\'email\',\'api\'];\n        if(operation==\'configure\' && (scopes.size()==0 || scopes.filter(s=>!allowed.contains(s)).size()>0 || c.client_type==\'SERVICE\' && scopes.filter(s=>s!=\'api\').size()>0)) {\n            exit 400,\'认证范围只能选择已支持的范围\';\n        }\n        if(operation==\'configure\') {\n            var redirects=p.redirects||[];\n            if(c.client_type!=\'SERVICE\' && redirects.size()==0 || redirects.size()>30) {\n                exit 400,\'交互客户端须登记精确回调地址\';\n            }\n            var seen=[];\n            for(item in redirects) {\n                if(![\'LOGIN\',\'LOGOUT\'].contains(item.type)) {\n                    exit 400,\'回调类型不正确\';\n                }\n                var uri=new URI(item.uri);\n                if(uri.getHost()==null || uri.getUserInfo()!=null || uri.getFragment()!=null || !(uri.getScheme()==\'https\' || uri.getScheme()==\'http\' && uri.getHost()==\'localhost\') || item.uri.length()>2000 || item.uri.contains(\'*\')) {\n                    exit 400,\'回调地址须为精确HTTPS地址，开发仅接受localhost HTTP\';\n                }\n                var mark=item.type+\':\'+item.uri;\n                if(seen.contains(mark)) {\n                    exit 400,\'回调地址重复\';\n                }\n                seen.add(mark);\n            }\n            sql.update("""\ndelete\nfrom iam_auth_redirect_t\nwhere client_id=#{c.id}\n""");\n            for(item in redirects) {\n                var rid=IdUtil.fastSimpleUUID();\n                var hash=DigestUtil.sha256Hex(item.uri);\n                sql.update("""\ninsert into iam_auth_redirect_t(tid, client_id, uri_type, uri, uri_hash)\nvalues(#{rid},#{c.id},#{item.type},#{item.uri},#{hash})\n""");\n            }\n            var encodedGrants=JSONUtil.toJsonStr(grants);\n            var encodedScopes=JSONUtil.toJsonStr(scopes);\n            sql.update("""\nupdate iam_auth_client_t\nset protocol=\'OIDC\',grant_types=#{encodedGrants},scopes=#{encodedScopes},status=\'ACTIVE\',require_pkce=1,\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        if(c.client_type!=\'PUBLIC\') {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'CLIENT\'\n    and owner_id=#{c.id}\n    and credential_type=\'CLIENT_SECRET\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(old==null || operation==\'rotate\') {\n                    exit 400,\'请提供独立客户端密钥\';\n                }\n            }\n            else {\n                var hash=identityProtocol.hashClientSecret(p.secret);\n                if(old!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{old.id}\n""");\n                }\n                var rid=IdUtil.fastSimpleUUID();\n                var revision=old==null?1:old.revision+1;\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{rid},\'CLIENT\',#{c.id},\'CLIENT_SECRET\',#{revision},\'BCRYPT\',#{hash},\'ACTIVE\')\n""");\n            }\n        }\n        if(operation==\'rotate\') {\n            sql.update("""\nupdate iam_auth_client_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_CONFIG_CHANGED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n        audit(ctx,\'SUCCESS\',\'protocol:\'+operation,c.id,null,{\n            id:c.id\n        });\n        return {\n            id:c.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/26.认证协议配置/01.读取应用认证协议配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d63d05f49f7a455b894f2e08bb0759de',NULL,'api','{\n  "properties": {},\n  "id": "219e2839013d5af28fbc5ea6a701674e",\n  "script": null,\n  "groupId": "1e4c952752445b3b8a68635e161010ed",\n  "name": "02.配置应用认证协议",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/configure",\n  "description": "校验回调地址、客户端类型和应用权限，登记协议客户端并保存可选统一认证配置；不改变租户本地登录体系。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.配置应用认证协议\n// 路由：POST /idaas/protocol-config/configure\n// 业务说明：校验回调地址、客户端类型和应用权限，登记协议客户端并保存可选统一认证配置；不改变租户本地登录体系。\nimport db;\nimport identityProtocol;\nimport identityTransport;\nimport java.net.URI;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'configure\';\n\n    // 显式启用客户端和可选统一认证。登记、协议开通、应用认证模式分别维护。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var client=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    and is_del=0\n""");\n    if(client==null) {\n        exit 404,\'请先登记客户端\';\n    }\n    var domain=p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'read\'?\'clients:read\':\'clients:write\',client.app_id,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'protocol:\'+operation,p,()=>{\n        var c=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(c.version!=p.version) {\n            exit 409,\'客户端配置已变更\';\n        }\n        if(operation==\'federation\') {\n            guard(\'apps:write\',c.app_id,domain);\n            var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{c.app_id}\n    and kind=\'BUSINESS\'\n    and is_del=0\n    for update\n""");\n            if(app==null || app.version!=p.appVersion) {\n                exit 409,\'应用版本已变更\';\n            }\n            if(p.enabled==true && sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere app_id=#{c.app_id}\n    and protocol=\'OIDC\'\n    and status=\'ACTIVE\'\n    and is_del=0\nlimit 1\n""")==null) {\n                exit 409,\'应用尚未配置活动认证客户端\';\n            }\n            var mode=p.enabled==true?\'FEDERATED\':\'LOCAL\';\n            sql.update("""\nupdate iam_application_t\nset auth_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.app_id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'protocol:federation\',c.app_id,null,{\n                id:c.app_id,mode:mode\n            });\n            return {\n                id:c.app_id,mode:mode\n            };\n        }\n        if(operation==\'disable\') {\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',version=version+1\nwhere tid=#{c.id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_DISABLED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n            audit(ctx,\'SUCCESS\',\'protocol:disable\',c.id,null,{\n                id:c.id\n            });\n            return {\n                id:c.id\n            };\n        }\n        if(operation!=\'configure\' && operation!=\'rotate\') {\n            exit 400,\'认证接入操作不正确\';\n        }\n        var grants=c.client_type==\'SERVICE\'?[\'client_credentials\']:c.client_type==\'PUBLIC\'?[\'authorization_code\']:[\'authorization_code\',\'refresh_token\'];\n        var scopes=p.scopes||[];\n        var allowed=[\'openid\',\'profile\',\'email\',\'api\'];\n        if(operation==\'configure\' && (scopes.size()==0 || scopes.filter(s=>!allowed.contains(s)).size()>0 || c.client_type==\'SERVICE\' && scopes.filter(s=>s!=\'api\').size()>0)) {\n            exit 400,\'认证范围只能选择已支持的范围\';\n        }\n        if(operation==\'configure\') {\n            var redirects=p.redirects||[];\n            if(c.client_type!=\'SERVICE\' && redirects.size()==0 || redirects.size()>30) {\n                exit 400,\'交互客户端须登记精确回调地址\';\n            }\n            var seen=[];\n            for(item in redirects) {\n                if(![\'LOGIN\',\'LOGOUT\'].contains(item.type)) {\n                    exit 400,\'回调类型不正确\';\n                }\n                var uri=new URI(item.uri);\n                if(uri.getHost()==null || uri.getUserInfo()!=null || uri.getFragment()!=null || !(uri.getScheme()==\'https\' || uri.getScheme()==\'http\' && uri.getHost()==\'localhost\') || item.uri.length()>2000 || item.uri.contains(\'*\')) {\n                    exit 400,\'回调地址须为精确HTTPS地址，开发仅接受localhost HTTP\';\n                }\n                var mark=item.type+\':\'+item.uri;\n                if(seen.contains(mark)) {\n                    exit 400,\'回调地址重复\';\n                }\n                seen.add(mark);\n            }\n            sql.update("""\ndelete\nfrom iam_auth_redirect_t\nwhere client_id=#{c.id}\n""");\n            for(item in redirects) {\n                var rid=IdUtil.fastSimpleUUID();\n                var hash=DigestUtil.sha256Hex(item.uri);\n                sql.update("""\ninsert into iam_auth_redirect_t(tid, client_id, uri_type, uri, uri_hash)\nvalues(#{rid},#{c.id},#{item.type},#{item.uri},#{hash})\n""");\n            }\n            var encodedGrants=JSONUtil.toJsonStr(grants);\n            var encodedScopes=JSONUtil.toJsonStr(scopes);\n            sql.update("""\nupdate iam_auth_client_t\nset protocol=\'OIDC\',grant_types=#{encodedGrants},scopes=#{encodedScopes},status=\'ACTIVE\',require_pkce=1,\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        if(c.client_type!=\'PUBLIC\') {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'CLIENT\'\n    and owner_id=#{c.id}\n    and credential_type=\'CLIENT_SECRET\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(old==null || operation==\'rotate\') {\n                    exit 400,\'请提供独立客户端密钥\';\n                }\n            }\n            else {\n                var hash=identityProtocol.hashClientSecret(p.secret);\n                if(old!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{old.id}\n""");\n                }\n                var rid=IdUtil.fastSimpleUUID();\n                var revision=old==null?1:old.revision+1;\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{rid},\'CLIENT\',#{c.id},\'CLIENT_SECRET\',#{revision},\'BCRYPT\',#{hash},\'ACTIVE\')\n""");\n            }\n        }\n        if(operation==\'rotate\') {\n            sql.update("""\nupdate iam_auth_client_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_CONFIG_CHANGED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n        audit(ctx,\'SUCCESS\',\'protocol:\'+operation,c.id,null,{\n            id:c.id\n        });\n        return {\n            id:c.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/26.认证协议配置/02.配置应用认证协议.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ecab2bcb4133461493ca55b80dc38a15',NULL,'api','{\n  "properties": {},\n  "id": "39fd09d6db9a57e2ae07418bdfcbc784",\n  "script": null,\n  "groupId": "1e4c952752445b3b8a68635e161010ed",\n  "name": "03.轮换协议客户端凭据",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/rotate",\n  "description": "为指定客户端生成新的协议凭据，更新安全版本并返回一次性凭据，旧凭据按策略作废。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.轮换协议客户端凭据\n// 路由：POST /idaas/protocol-config/rotate\n// 业务说明：为指定客户端生成新的协议凭据，更新安全版本并返回一次性凭据，旧凭据按策略作废。\nimport db;\nimport identityProtocol;\nimport identityTransport;\nimport java.net.URI;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'rotate\';\n\n    // 显式启用客户端和可选统一认证。登记、协议开通、应用认证模式分别维护。\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    var client=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    and is_del=0\n""");\n    if(client==null) {\n        exit 404,\'请先登记客户端\';\n    }\n    var domain=p.domain||\'workforce\';\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(operation==\'read\'?\'clients:read\':\'clients:write\',client.app_id,domain);\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    return mutate(ctx,\'protocol:\'+operation,p,()=>{\n        var c=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_client_t\nwhere tid=#{p.id}\n    for update\n""");\n        if(c.version!=p.version) {\n            exit 409,\'客户端配置已变更\';\n        }\n        if(operation==\'federation\') {\n            guard(\'apps:write\',c.app_id,domain);\n            var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{c.app_id}\n    and kind=\'BUSINESS\'\n    and is_del=0\n    for update\n""");\n            if(app==null || app.version!=p.appVersion) {\n                exit 409,\'应用版本已变更\';\n            }\n            if(p.enabled==true && sql.selectOne("""\nselect tid as id\nfrom iam_auth_client_t\nwhere app_id=#{c.app_id}\n    and protocol=\'OIDC\'\n    and status=\'ACTIVE\'\n    and is_del=0\nlimit 1\n""")==null) {\n                exit 409,\'应用尚未配置活动认证客户端\';\n            }\n            var mode=p.enabled==true?\'FEDERATED\':\'LOCAL\';\n            sql.update("""\nupdate iam_application_t\nset auth_mode=#{mode},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.app_id}\n""");\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'protocol:federation\',c.app_id,null,{\n                id:c.app_id,mode:mode\n            });\n            return {\n                id:c.app_id,mode:mode\n            };\n        }\n        if(operation==\'disable\') {\n            sql.update("""\nupdate iam_auth_client_t\nset status=\'DISABLED\',version=version+1\nwhere tid=#{c.id}\n""");\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_DISABLED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n            audit(ctx,\'SUCCESS\',\'protocol:disable\',c.id,null,{\n                id:c.id\n            });\n            return {\n                id:c.id\n            };\n        }\n        if(operation!=\'configure\' && operation!=\'rotate\') {\n            exit 400,\'认证接入操作不正确\';\n        }\n        var grants=c.client_type==\'SERVICE\'?[\'client_credentials\']:c.client_type==\'PUBLIC\'?[\'authorization_code\']:[\'authorization_code\',\'refresh_token\'];\n        var scopes=p.scopes||[];\n        var allowed=[\'openid\',\'profile\',\'email\',\'api\'];\n        if(operation==\'configure\' && (scopes.size()==0 || scopes.filter(s=>!allowed.contains(s)).size()>0 || c.client_type==\'SERVICE\' && scopes.filter(s=>s!=\'api\').size()>0)) {\n            exit 400,\'认证范围只能选择已支持的范围\';\n        }\n        if(operation==\'configure\') {\n            var redirects=p.redirects||[];\n            if(c.client_type!=\'SERVICE\' && redirects.size()==0 || redirects.size()>30) {\n                exit 400,\'交互客户端须登记精确回调地址\';\n            }\n            var seen=[];\n            for(item in redirects) {\n                if(![\'LOGIN\',\'LOGOUT\'].contains(item.type)) {\n                    exit 400,\'回调类型不正确\';\n                }\n                var uri=new URI(item.uri);\n                if(uri.getHost()==null || uri.getUserInfo()!=null || uri.getFragment()!=null || !(uri.getScheme()==\'https\' || uri.getScheme()==\'http\' && uri.getHost()==\'localhost\') || item.uri.length()>2000 || item.uri.contains(\'*\')) {\n                    exit 400,\'回调地址须为精确HTTPS地址，开发仅接受localhost HTTP\';\n                }\n                var mark=item.type+\':\'+item.uri;\n                if(seen.contains(mark)) {\n                    exit 400,\'回调地址重复\';\n                }\n                seen.add(mark);\n            }\n            sql.update("""\ndelete\nfrom iam_auth_redirect_t\nwhere client_id=#{c.id}\n""");\n            for(item in redirects) {\n                var rid=IdUtil.fastSimpleUUID();\n                var hash=DigestUtil.sha256Hex(item.uri);\n                sql.update("""\ninsert into iam_auth_redirect_t(tid, client_id, uri_type, uri, uri_hash)\nvalues(#{rid},#{c.id},#{item.type},#{item.uri},#{hash})\n""");\n            }\n            var encodedGrants=JSONUtil.toJsonStr(grants);\n            var encodedScopes=JSONUtil.toJsonStr(scopes);\n            sql.update("""\nupdate iam_auth_client_t\nset protocol=\'OIDC\',grant_types=#{encodedGrants},scopes=#{encodedScopes},status=\'ACTIVE\',require_pkce=1,\n    version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        if(c.client_type!=\'PUBLIC\') {\n            var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'CLIENT\'\n    and owner_id=#{c.id}\n    and credential_type=\'CLIENT_SECRET\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(old==null || operation==\'rotate\') {\n                    exit 400,\'请提供独立客户端密钥\';\n                }\n            }\n            else {\n                var hash=identityProtocol.hashClientSecret(p.secret);\n                if(old!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{old.id}\n""");\n                }\n                var rid=IdUtil.fastSimpleUUID();\n                var revision=old==null?1:old.revision+1;\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_hash, status)\nvalues(#{rid},\'CLIENT\',#{c.id},\'CLIENT_SECRET\',#{revision},\'BCRYPT\',#{hash},\'ACTIVE\')\n""");\n            }\n        }\n        if(operation==\'rotate\') {\n            sql.update("""\nupdate iam_auth_client_t\nset version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{c.id}\n""");\n        }\n        sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CLIENT_CONFIG_CHANGED\'\nwhere client_id=#{c.id}\n    and revoked_at is null\n""");\n        audit(ctx,\'SUCCESS\',\'protocol:\'+operation,c.id,null,{\n            id:c.id\n        });\n        return {\n            id:c.id\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/26.认证协议配置/03.轮换协议客户端凭据.ms');
