INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('13b4c34d663f4cf1a37a257d7671d6cd',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e5f7bc383fa7460994bcae945950a135',NULL,'api','{\n  "properties": {},\n  "id": "548164e3c6de52b3b8e8b9563dcec75b",\n  "script": null,\n  "groupId": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "01.读取实名核验服务配置",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/provider",\n  "description": "读取已登记实名核验提供方及可展示状态，对密钥与回调凭据脱敏。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.读取实名核验服务配置\n// 路由：GET /idaas/verifications/provider\n// 业务说明：读取已登记实名核验提供方及可展示状态，对密钥与回调凭据脱敏。\nimport db;\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/auth-account-context\' as accountContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'provider\';\n\n    // 核验资料加密保存；只有受信任提供方的真实签名回执可以标记通过。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'provider\' || operation==\'save-provider\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(operation==\'provider\'?\'public:read\':\'public:write\',null,\'public\');\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n""");\n        if(operation==\'provider\') {\n            var value=old==null?{}:JSONUtil.parseObj(old.value_json);\n            return {\n                id:old==null?null:old.id,version:old==null?null:old.version,configured:old!=null && value.enabled==true,providerCode:value.providerCode||\'\',endpoint:value.endpoint||\'\',enabled:value.enabled||false,status:old==null || value.enabled!=true?\'UNCONFIGURED\':\'CONFIGURED\'\n            };\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'verification:save-provider\',p,()=>{\n            old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'核验配置已变更\';\n            }\n            var code=(p.providerCode||\'\').trim();\n            if(!code.matches(\'[A-Za-z][A-Za-z0-9_-]{2,63}\')) {\n                exit 400,\'核验渠道编码不正确\';\n            }\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var id=old==null?IdUtil.fastSimpleUUID():old.id;\n            var encoded=JSONUtil.toJsonStr({\n                providerCode:code,endpoint:endpoint,enabled:p.enabled==true\n            });\n            if(old==null) {\n                sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status)\nvalues(#{id},\'GLOBAL\',\'global\',\'VERIFICATION\',\'provider\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1\nwhere tid=#{id}\n""");\n            }\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(prior==null) {\n                    exit 400,\'核验接入密钥不能为空\';\n                }\n            }\n            else {\n                var cipher=identityTransport.encrypt(p.secret);\n                var revision=prior==null?1:prior.revision+1;\n                if(prior!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{prior.id}\n""");\n                }\n                var cid=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_cipher, status)\nvalues(#{cid},\'VERIFY_PROVIDER\',#{id},\'HMAC_KEY\',#{revision},\'AES256_GCM\',#{cipher},\'ACTIVE\')\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'verification:save-provider\',id,null,{\n                id:id,provider:code\n            });\n            return {\n                id:id\n            };\n        });\n    }\n    var ctx=accountContext();\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请使用已完成密码设置的公众认证账号\';\n    }\n    var provider=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var settings=provider==null?{}:JSONUtil.parseObj(provider.value_json);\n    if(settings.enabled!=true) {\n        exit 503,\'实名核验提供方尚未配置，不能完成实名核验\';\n    }\n    var key=sql.selectOne("""\nselect secret_cipher\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{provider.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 503,\'核验提供方凭据未配置\';\n    }\n    var type=p.targetType||\'SUBJECT\';\n    var target=type==\'SUBJECT\'?ctx.account.subject_id:p.targetId;\n    if(![\'SUBJECT\',\'LEGAL_ENTITY\'].contains(type) || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请明确同意核验并提供申请号\';\n    }\n    if(type==\'LEGAL_ENTITY\' && sql.selectOne("""\nselect tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{target}\n    and subject_id=#{ctx.account.subject_id}\n    and relation_type in (\'REPRESENTATIVE\',\'AGENT\')\n    and (status=\'ACTIVE\'\n         or status=\'PENDING\'\n         and created_by=#{ctx.userId})\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\nlimit 1\n""")==null) {\n        exit 403,\'没有此法人的有效经办资格\';\n    }\n    var document=(p.document||\'\').trim();\n    if(document==\'\' || document.length()>100 || (p.documentType||\'\').length()>32) {\n        exit 400,\'核验资料不正确\';\n    }\n    var identity=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n""");\n    if(identity==null || type==\'LEGAL_ENTITY\' && identity.registration_code!=document.toUpperCase()) {\n        exit 400,\'法人核验资料须匹配登记的信用代码\';\n    }\n    var requestId=DigestUtil.sha256Hex(ctx.userId+\':\'+p.requestId).substring(0,32);\n    var inputHash=identityTransport.protectedFingerprint(type+\':\'+target+\':\'+identity.name+\':\'+document+\':\'+p.documentType,\'verification\');\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var created=sql.transaction(()=>{\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere provider_code=#{settings.providerCode}\n    and provider_request_id=#{requestId}\n    for update\n""");\n        if(prior!=null) {\n            if(prior.consent_ref!=inputHash) {\n                exit 409,\'同一申请号的核验资料不一致\';\n            }\n            return prior;\n        }\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_verification_t(tid,\n                created_by, target_type, target_id, provider_code, provider_request_id, consent_ref,\n                requested_time)\nvalues(#{id},#{ctx.userId},#{type},#{target},#{settings.providerCode},#{requestId},#{inputHash},utc_timestamp(6))\n""");\n        if(type==\'SUBJECT\') {\n            var profile=sql.selectOne("""\nselect *,tid as id\nfrom iam_public_profile_t\nwhere subject_id=#{target}\n""");\n            var pid=profile==null?IdUtil.fastSimpleUUID():profile.id;\n            var cipher=identityTransport.protectValue(document,\'DOCUMENT:\'+target);\n            var fingerprint=identityTransport.protectedFingerprint(document,\'document:\'+p.documentType);\n            if(profile==null) {\n                sql.update("""\ninsert into iam_public_profile_t(tid,\n                subject_id, document_type, document_cipher, document_fingerprint, verification_status,\n                verification_id)\nvalues(#{pid},#{target},#{p.documentType},#{cipher},#{fingerprint},\'PENDING\',#{id})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_public_profile_t\nset document_type=#{p.documentType},document_cipher=#{cipher},document_fingerprint=#{fingerprint},\n    verification_status=\'PENDING\',verification_id=#{id},version=version+1\nwhere tid=#{pid}\n""");\n            }\n        }\n        else {\n            sql.update("""\nupdate iam_legal_entity_t\nset verification_status=\'PENDING\',version=version+1\nwhere tid=#{target}\n""");\n        }\n        return sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere tid=#{id}\n""");\n    });\n    if(created.status!=\'PENDING\') {\n        return {\n            id:created.id,status:created.status\n        };\n    }\n    var body=identityTransport.canonicalJson({\n        protocol:\'IDAAS_VERIFY/1\',providerCode:settings.providerCode,requestId:requestId,targetType:type,targetId:target,name:identity.name,documentType:p.documentType,document:document,consentRef:inputHash\n    });\n    var receipt=null;\n    try {\n        receipt=identityTransport.sendVerification(settings.endpoint,key.secret_cipher,settings.providerCode,requestId,body);\n    }\n    catch(e) {\n        sql.update("""\nupdate iam_verification_t\nset result_code=\'PROVIDER_UNAVAILABLE\',version=version+1\nwhere tid=#{created.id}\n""");\n        return {\n            id:created.id,status:\'PENDING\',resultCode:\'PROVIDER_UNAVAILABLE\'\n        };\n    }\n    if(receipt.protocol!=\'IDAAS_VERIFY/1\' || receipt.providerCode!=settings.providerCode || receipt.requestId!=requestId || receipt.targetType!=type || receipt.targetId!=target || ![\'VERIFIED\',\'REJECTED\',\'PENDING\'].contains(receipt.status) || (receipt.resultCode||\'\').length()>100) {\n        exit 502,\'核验回执目标或结果不正确\';\n    }\n    var expiry=null;\n    var evidence=receipt.evidenceRef;\n    if(receipt.status==\'VERIFIED\') {\n        try {\n            var end=Instant.parse(receipt.expiresAt);\n            var now=Instant.now();\n            if(!end.isAfter(now) || end.isAfter(now.plusSeconds(31536000)) || evidence==null || !evidence.matches(\'[A-Za-z0-9_.:/-]{1,1000}\')) {\n                exit 502,\'核验回执缺少有效期限或受控证据引用\';\n            }\n            expiry=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\').format(LocalDateTime.ofInstant(end,ZoneOffset.UTC));\n        }\n        catch(e) {\n            exit 502,\'核验回执有效期限不正确\';\n        }\n    }\n    return sql.transaction(()=>{\n        var current=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(current==null || current.name!=identity.name || type==\'LEGAL_ENTITY\' && current.registration_code!=identity.registration_code) {\n            sql.update("""\nupdate iam_verification_t\nset status=\'REJECTED\',result_code=\'IDENTITY_CHANGED\',version=version+1\nwhere tid=#{created.id}\n""");\n            return {\n                id:created.id,status:\'REJECTED\',resultCode:\'IDENTITY_CHANGED\'\n            };\n        }\n        var status=receipt.status;\n        sql.update("""\nupdate iam_verification_t\nset status=#{status},result_code=#{receipt.resultCode},completed_time=case\n        when #{status}=\'PENDING\' then null\n        else utc_timestamp(6)\n        end,\n        expires_at=#{expiry},\n        evidence_ref=#{evidence},version=version+1\nwhere tid=#{created.id}\n""");\n        if(type==\'SUBJECT\') {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=#{status},verified_time=case\n        when #{status}=\'VERIFIED\' then utc_timestamp(6) else null\n        end,version=version+1\nwhere subject_id=#{target}\n    and verification_id=#{created.id}\n""");\n        }\n        else {\n            var latest=sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{target}\norder by requested_time desc,tid desc\nlimit 1\n""");\n            if(latest!=null && latest.id==created.id) {\n                sql.update("""\nupdate iam_legal_entity_t\nset verification_status=#{status},version=version+1\nwhere tid=#{target}\n""");\n            }\n        }\n        audit(ctx,status==\'VERIFIED\'?\'SUCCESS\':\'FAILED\',\'auth:verification\',target,status,{\n            id:created.id,status:status\n        });\n        return {\n            id:created.id,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/01.读取实名核验服务配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a6a53f92c7c64d34b71d0a298eb9e936',NULL,'api','{\n  "properties": {},\n  "id": "cc4c1981178f58e3aa80aeff3ece02e8",\n  "script": null,\n  "groupId": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "02.保存实名核验服务配置",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save-provider",\n  "description": "校验提供方接口地址、验签材料与权限后保存配置；敏感材料加密存储。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.保存实名核验服务配置\n// 路由：POST /idaas/verifications/save-provider\n// 业务说明：校验提供方接口地址、验签材料与权限后保存配置；敏感材料加密存储。\nimport db;\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/auth-account-context\' as accountContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'save-provider\';\n\n    // 核验资料加密保存；只有受信任提供方的真实签名回执可以标记通过。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'provider\' || operation==\'save-provider\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(operation==\'provider\'?\'public:read\':\'public:write\',null,\'public\');\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n""");\n        if(operation==\'provider\') {\n            var value=old==null?{}:JSONUtil.parseObj(old.value_json);\n            return {\n                id:old==null?null:old.id,version:old==null?null:old.version,configured:old!=null && value.enabled==true,providerCode:value.providerCode||\'\',endpoint:value.endpoint||\'\',enabled:value.enabled||false,status:old==null || value.enabled!=true?\'UNCONFIGURED\':\'CONFIGURED\'\n            };\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'verification:save-provider\',p,()=>{\n            old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'核验配置已变更\';\n            }\n            var code=(p.providerCode||\'\').trim();\n            if(!code.matches(\'[A-Za-z][A-Za-z0-9_-]{2,63}\')) {\n                exit 400,\'核验渠道编码不正确\';\n            }\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var id=old==null?IdUtil.fastSimpleUUID():old.id;\n            var encoded=JSONUtil.toJsonStr({\n                providerCode:code,endpoint:endpoint,enabled:p.enabled==true\n            });\n            if(old==null) {\n                sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status)\nvalues(#{id},\'GLOBAL\',\'global\',\'VERIFICATION\',\'provider\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1\nwhere tid=#{id}\n""");\n            }\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(prior==null) {\n                    exit 400,\'核验接入密钥不能为空\';\n                }\n            }\n            else {\n                var cipher=identityTransport.encrypt(p.secret);\n                var revision=prior==null?1:prior.revision+1;\n                if(prior!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{prior.id}\n""");\n                }\n                var cid=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_cipher, status)\nvalues(#{cid},\'VERIFY_PROVIDER\',#{id},\'HMAC_KEY\',#{revision},\'AES256_GCM\',#{cipher},\'ACTIVE\')\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'verification:save-provider\',id,null,{\n                id:id,provider:code\n            });\n            return {\n                id:id\n            };\n        });\n    }\n    var ctx=accountContext();\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请使用已完成密码设置的公众认证账号\';\n    }\n    var provider=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var settings=provider==null?{}:JSONUtil.parseObj(provider.value_json);\n    if(settings.enabled!=true) {\n        exit 503,\'实名核验提供方尚未配置，不能完成实名核验\';\n    }\n    var key=sql.selectOne("""\nselect secret_cipher\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{provider.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 503,\'核验提供方凭据未配置\';\n    }\n    var type=p.targetType||\'SUBJECT\';\n    var target=type==\'SUBJECT\'?ctx.account.subject_id:p.targetId;\n    if(![\'SUBJECT\',\'LEGAL_ENTITY\'].contains(type) || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请明确同意核验并提供申请号\';\n    }\n    if(type==\'LEGAL_ENTITY\' && sql.selectOne("""\nselect tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{target}\n    and subject_id=#{ctx.account.subject_id}\n    and relation_type in (\'REPRESENTATIVE\',\'AGENT\')\n    and (status=\'ACTIVE\'\n         or status=\'PENDING\'\n         and created_by=#{ctx.userId})\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\nlimit 1\n""")==null) {\n        exit 403,\'没有此法人的有效经办资格\';\n    }\n    var document=(p.document||\'\').trim();\n    if(document==\'\' || document.length()>100 || (p.documentType||\'\').length()>32) {\n        exit 400,\'核验资料不正确\';\n    }\n    var identity=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n""");\n    if(identity==null || type==\'LEGAL_ENTITY\' && identity.registration_code!=document.toUpperCase()) {\n        exit 400,\'法人核验资料须匹配登记的信用代码\';\n    }\n    var requestId=DigestUtil.sha256Hex(ctx.userId+\':\'+p.requestId).substring(0,32);\n    var inputHash=identityTransport.protectedFingerprint(type+\':\'+target+\':\'+identity.name+\':\'+document+\':\'+p.documentType,\'verification\');\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var created=sql.transaction(()=>{\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere provider_code=#{settings.providerCode}\n    and provider_request_id=#{requestId}\n    for update\n""");\n        if(prior!=null) {\n            if(prior.consent_ref!=inputHash) {\n                exit 409,\'同一申请号的核验资料不一致\';\n            }\n            return prior;\n        }\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_verification_t(tid,\n                created_by, target_type, target_id, provider_code, provider_request_id, consent_ref,\n                requested_time)\nvalues(#{id},#{ctx.userId},#{type},#{target},#{settings.providerCode},#{requestId},#{inputHash},utc_timestamp(6))\n""");\n        if(type==\'SUBJECT\') {\n            var profile=sql.selectOne("""\nselect *,tid as id\nfrom iam_public_profile_t\nwhere subject_id=#{target}\n""");\n            var pid=profile==null?IdUtil.fastSimpleUUID():profile.id;\n            var cipher=identityTransport.protectValue(document,\'DOCUMENT:\'+target);\n            var fingerprint=identityTransport.protectedFingerprint(document,\'document:\'+p.documentType);\n            if(profile==null) {\n                sql.update("""\ninsert into iam_public_profile_t(tid,\n                subject_id, document_type, document_cipher, document_fingerprint, verification_status,\n                verification_id)\nvalues(#{pid},#{target},#{p.documentType},#{cipher},#{fingerprint},\'PENDING\',#{id})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_public_profile_t\nset document_type=#{p.documentType},document_cipher=#{cipher},document_fingerprint=#{fingerprint},\n    verification_status=\'PENDING\',verification_id=#{id},version=version+1\nwhere tid=#{pid}\n""");\n            }\n        }\n        else {\n            sql.update("""\nupdate iam_legal_entity_t\nset verification_status=\'PENDING\',version=version+1\nwhere tid=#{target}\n""");\n        }\n        return sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere tid=#{id}\n""");\n    });\n    if(created.status!=\'PENDING\') {\n        return {\n            id:created.id,status:created.status\n        };\n    }\n    var body=identityTransport.canonicalJson({\n        protocol:\'IDAAS_VERIFY/1\',providerCode:settings.providerCode,requestId:requestId,targetType:type,targetId:target,name:identity.name,documentType:p.documentType,document:document,consentRef:inputHash\n    });\n    var receipt=null;\n    try {\n        receipt=identityTransport.sendVerification(settings.endpoint,key.secret_cipher,settings.providerCode,requestId,body);\n    }\n    catch(e) {\n        sql.update("""\nupdate iam_verification_t\nset result_code=\'PROVIDER_UNAVAILABLE\',version=version+1\nwhere tid=#{created.id}\n""");\n        return {\n            id:created.id,status:\'PENDING\',resultCode:\'PROVIDER_UNAVAILABLE\'\n        };\n    }\n    if(receipt.protocol!=\'IDAAS_VERIFY/1\' || receipt.providerCode!=settings.providerCode || receipt.requestId!=requestId || receipt.targetType!=type || receipt.targetId!=target || ![\'VERIFIED\',\'REJECTED\',\'PENDING\'].contains(receipt.status) || (receipt.resultCode||\'\').length()>100) {\n        exit 502,\'核验回执目标或结果不正确\';\n    }\n    var expiry=null;\n    var evidence=receipt.evidenceRef;\n    if(receipt.status==\'VERIFIED\') {\n        try {\n            var end=Instant.parse(receipt.expiresAt);\n            var now=Instant.now();\n            if(!end.isAfter(now) || end.isAfter(now.plusSeconds(31536000)) || evidence==null || !evidence.matches(\'[A-Za-z0-9_.:/-]{1,1000}\')) {\n                exit 502,\'核验回执缺少有效期限或受控证据引用\';\n            }\n            expiry=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\').format(LocalDateTime.ofInstant(end,ZoneOffset.UTC));\n        }\n        catch(e) {\n            exit 502,\'核验回执有效期限不正确\';\n        }\n    }\n    return sql.transaction(()=>{\n        var current=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(current==null || current.name!=identity.name || type==\'LEGAL_ENTITY\' && current.registration_code!=identity.registration_code) {\n            sql.update("""\nupdate iam_verification_t\nset status=\'REJECTED\',result_code=\'IDENTITY_CHANGED\',version=version+1\nwhere tid=#{created.id}\n""");\n            return {\n                id:created.id,status:\'REJECTED\',resultCode:\'IDENTITY_CHANGED\'\n            };\n        }\n        var status=receipt.status;\n        sql.update("""\nupdate iam_verification_t\nset status=#{status},result_code=#{receipt.resultCode},completed_time=case\n        when #{status}=\'PENDING\' then null\n        else utc_timestamp(6)\n        end,\n        expires_at=#{expiry},\n        evidence_ref=#{evidence},version=version+1\nwhere tid=#{created.id}\n""");\n        if(type==\'SUBJECT\') {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=#{status},verified_time=case\n        when #{status}=\'VERIFIED\' then utc_timestamp(6) else null\n        end,version=version+1\nwhere subject_id=#{target}\n    and verification_id=#{created.id}\n""");\n        }\n        else {\n            var latest=sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{target}\norder by requested_time desc,tid desc\nlimit 1\n""");\n            if(latest!=null && latest.id==created.id) {\n                sql.update("""\nupdate iam_legal_entity_t\nset verification_status=#{status},version=version+1\nwhere tid=#{target}\n""");\n            }\n        }\n        audit(ctx,status==\'VERIFIED\'?\'SUCCESS\':\'FAILED\',\'auth:verification\',target,status,{\n            id:created.id,status:status\n        });\n        return {\n            id:created.id,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/02.保存实名核验服务配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f76eae703c024502bfcccad73f2b03e8',NULL,'api','{\n  "properties": {},\n  "id": "a8690a99453c517383574e097c0d5fc2",\n  "script": null,\n  "groupId": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "03.查询实名核验记录",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "description": "按账号、状态与时间范围查询核验记录，校验可见范围并对证件资料脱敏。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：03.查询实名核验记录\n// 路由：GET /idaas/verifications/list\n// 业务说明：按账号、状态与时间范围查询核验记录，校验可见范围并对证件资料脱敏。\nimport db;\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/auth-account-context\' as accountContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'list\';\n\n    // 核验资料加密保存；只有受信任提供方的真实签名回执可以标记通过。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'provider\' || operation==\'save-provider\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(operation==\'provider\'?\'public:read\':\'public:write\',null,\'public\');\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n""");\n        if(operation==\'provider\') {\n            var value=old==null?{}:JSONUtil.parseObj(old.value_json);\n            return {\n                id:old==null?null:old.id,version:old==null?null:old.version,configured:old!=null && value.enabled==true,providerCode:value.providerCode||\'\',endpoint:value.endpoint||\'\',enabled:value.enabled||false,status:old==null || value.enabled!=true?\'UNCONFIGURED\':\'CONFIGURED\'\n            };\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'verification:save-provider\',p,()=>{\n            old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'核验配置已变更\';\n            }\n            var code=(p.providerCode||\'\').trim();\n            if(!code.matches(\'[A-Za-z][A-Za-z0-9_-]{2,63}\')) {\n                exit 400,\'核验渠道编码不正确\';\n            }\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var id=old==null?IdUtil.fastSimpleUUID():old.id;\n            var encoded=JSONUtil.toJsonStr({\n                providerCode:code,endpoint:endpoint,enabled:p.enabled==true\n            });\n            if(old==null) {\n                sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status)\nvalues(#{id},\'GLOBAL\',\'global\',\'VERIFICATION\',\'provider\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1\nwhere tid=#{id}\n""");\n            }\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(prior==null) {\n                    exit 400,\'核验接入密钥不能为空\';\n                }\n            }\n            else {\n                var cipher=identityTransport.encrypt(p.secret);\n                var revision=prior==null?1:prior.revision+1;\n                if(prior!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{prior.id}\n""");\n                }\n                var cid=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_cipher, status)\nvalues(#{cid},\'VERIFY_PROVIDER\',#{id},\'HMAC_KEY\',#{revision},\'AES256_GCM\',#{cipher},\'ACTIVE\')\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'verification:save-provider\',id,null,{\n                id:id,provider:code\n            });\n            return {\n                id:id\n            };\n        });\n    }\n    if(operation==\'list\') {\n        guard(\'public:read\',null,\'public\');\n        return sql.select("""\nselect tid as id,version,target_type targetType,target_id targetId,provider_code providerCode,status,\n       result_code resultCode,requested_time requestedTime,completed_time completedTime,expires_at expiresAt\nfrom iam_verification_t\norder by requested_time desc\nlimit 250\n""");\n    }\n    var ctx=accountContext();\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请使用已完成密码设置的公众认证账号\';\n    }\n    var provider=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var settings=provider==null?{}:JSONUtil.parseObj(provider.value_json);\n    if(settings.enabled!=true) {\n        exit 503,\'实名核验提供方尚未配置，不能完成实名核验\';\n    }\n    var key=sql.selectOne("""\nselect secret_cipher\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{provider.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 503,\'核验提供方凭据未配置\';\n    }\n    var type=p.targetType||\'SUBJECT\';\n    var target=type==\'SUBJECT\'?ctx.account.subject_id:p.targetId;\n    if(![\'SUBJECT\',\'LEGAL_ENTITY\'].contains(type) || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请明确同意核验并提供申请号\';\n    }\n    if(type==\'LEGAL_ENTITY\' && sql.selectOne("""\nselect tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{target}\n    and subject_id=#{ctx.account.subject_id}\n    and relation_type in (\'REPRESENTATIVE\',\'AGENT\')\n    and (status=\'ACTIVE\'\n         or status=\'PENDING\'\n         and created_by=#{ctx.userId})\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\nlimit 1\n""")==null) {\n        exit 403,\'没有此法人的有效经办资格\';\n    }\n    var document=(p.document||\'\').trim();\n    if(document==\'\' || document.length()>100 || (p.documentType||\'\').length()>32) {\n        exit 400,\'核验资料不正确\';\n    }\n    var identity=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n""");\n    if(identity==null || type==\'LEGAL_ENTITY\' && identity.registration_code!=document.toUpperCase()) {\n        exit 400,\'法人核验资料须匹配登记的信用代码\';\n    }\n    var requestId=DigestUtil.sha256Hex(ctx.userId+\':\'+p.requestId).substring(0,32);\n    var inputHash=identityTransport.protectedFingerprint(type+\':\'+target+\':\'+identity.name+\':\'+document+\':\'+p.documentType,\'verification\');\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var created=sql.transaction(()=>{\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere provider_code=#{settings.providerCode}\n    and provider_request_id=#{requestId}\n    for update\n""");\n        if(prior!=null) {\n            if(prior.consent_ref!=inputHash) {\n                exit 409,\'同一申请号的核验资料不一致\';\n            }\n            return prior;\n        }\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_verification_t(tid,\n                created_by, target_type, target_id, provider_code, provider_request_id, consent_ref,\n                requested_time)\nvalues(#{id},#{ctx.userId},#{type},#{target},#{settings.providerCode},#{requestId},#{inputHash},utc_timestamp(6))\n""");\n        if(type==\'SUBJECT\') {\n            var profile=sql.selectOne("""\nselect *,tid as id\nfrom iam_public_profile_t\nwhere subject_id=#{target}\n""");\n            var pid=profile==null?IdUtil.fastSimpleUUID():profile.id;\n            var cipher=identityTransport.protectValue(document,\'DOCUMENT:\'+target);\n            var fingerprint=identityTransport.protectedFingerprint(document,\'document:\'+p.documentType);\n            if(profile==null) {\n                sql.update("""\ninsert into iam_public_profile_t(tid,\n                subject_id, document_type, document_cipher, document_fingerprint, verification_status,\n                verification_id)\nvalues(#{pid},#{target},#{p.documentType},#{cipher},#{fingerprint},\'PENDING\',#{id})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_public_profile_t\nset document_type=#{p.documentType},document_cipher=#{cipher},document_fingerprint=#{fingerprint},\n    verification_status=\'PENDING\',verification_id=#{id},version=version+1\nwhere tid=#{pid}\n""");\n            }\n        }\n        else {\n            sql.update("""\nupdate iam_legal_entity_t\nset verification_status=\'PENDING\',version=version+1\nwhere tid=#{target}\n""");\n        }\n        return sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere tid=#{id}\n""");\n    });\n    if(created.status!=\'PENDING\') {\n        return {\n            id:created.id,status:created.status\n        };\n    }\n    var body=identityTransport.canonicalJson({\n        protocol:\'IDAAS_VERIFY/1\',providerCode:settings.providerCode,requestId:requestId,targetType:type,targetId:target,name:identity.name,documentType:p.documentType,document:document,consentRef:inputHash\n    });\n    var receipt=null;\n    try {\n        receipt=identityTransport.sendVerification(settings.endpoint,key.secret_cipher,settings.providerCode,requestId,body);\n    }\n    catch(e) {\n        sql.update("""\nupdate iam_verification_t\nset result_code=\'PROVIDER_UNAVAILABLE\',version=version+1\nwhere tid=#{created.id}\n""");\n        return {\n            id:created.id,status:\'PENDING\',resultCode:\'PROVIDER_UNAVAILABLE\'\n        };\n    }\n    if(receipt.protocol!=\'IDAAS_VERIFY/1\' || receipt.providerCode!=settings.providerCode || receipt.requestId!=requestId || receipt.targetType!=type || receipt.targetId!=target || ![\'VERIFIED\',\'REJECTED\',\'PENDING\'].contains(receipt.status) || (receipt.resultCode||\'\').length()>100) {\n        exit 502,\'核验回执目标或结果不正确\';\n    }\n    var expiry=null;\n    var evidence=receipt.evidenceRef;\n    if(receipt.status==\'VERIFIED\') {\n        try {\n            var end=Instant.parse(receipt.expiresAt);\n            var now=Instant.now();\n            if(!end.isAfter(now) || end.isAfter(now.plusSeconds(31536000)) || evidence==null || !evidence.matches(\'[A-Za-z0-9_.:/-]{1,1000}\')) {\n                exit 502,\'核验回执缺少有效期限或受控证据引用\';\n            }\n            expiry=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\').format(LocalDateTime.ofInstant(end,ZoneOffset.UTC));\n        }\n        catch(e) {\n            exit 502,\'核验回执有效期限不正确\';\n        }\n    }\n    return sql.transaction(()=>{\n        var current=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(current==null || current.name!=identity.name || type==\'LEGAL_ENTITY\' && current.registration_code!=identity.registration_code) {\n            sql.update("""\nupdate iam_verification_t\nset status=\'REJECTED\',result_code=\'IDENTITY_CHANGED\',version=version+1\nwhere tid=#{created.id}\n""");\n            return {\n                id:created.id,status:\'REJECTED\',resultCode:\'IDENTITY_CHANGED\'\n            };\n        }\n        var status=receipt.status;\n        sql.update("""\nupdate iam_verification_t\nset status=#{status},result_code=#{receipt.resultCode},completed_time=case\n        when #{status}=\'PENDING\' then null\n        else utc_timestamp(6)\n        end,\n        expires_at=#{expiry},\n        evidence_ref=#{evidence},version=version+1\nwhere tid=#{created.id}\n""");\n        if(type==\'SUBJECT\') {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=#{status},verified_time=case\n        when #{status}=\'VERIFIED\' then utc_timestamp(6) else null\n        end,version=version+1\nwhere subject_id=#{target}\n    and verification_id=#{created.id}\n""");\n        }\n        else {\n            var latest=sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{target}\norder by requested_time desc,tid desc\nlimit 1\n""");\n            if(latest!=null && latest.id==created.id) {\n                sql.update("""\nupdate iam_legal_entity_t\nset verification_status=#{status},version=version+1\nwhere tid=#{target}\n""");\n            }\n        }\n        audit(ctx,status==\'VERIFIED\'?\'SUCCESS\':\'FAILED\',\'auth:verification\',target,status,{\n            id:created.id,status:status\n        });\n        return {\n            id:created.id,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/03.查询实名核验记录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8277b29531894dcca082566121af37dc',NULL,'api','{\n  "properties": {},\n  "id": "7e75adea4f3b53b2884b460faf58f385",\n  "script": null,\n  "groupId": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "04.查询本人实名核验",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/mine",\n  "description": "从当前统一认证会话读取本人的核验申请、状态及结果，不暴露原始敏感资料。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：04.查询本人实名核验\n// 路由：GET /idaas/verifications/mine\n// 业务说明：从当前统一认证会话读取本人的核验申请、状态及结果，不暴露原始敏感资料。\nimport db;\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/auth-account-context\' as accountContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'mine\';\n\n    // 核验资料加密保存；只有受信任提供方的真实签名回执可以标记通过。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'provider\' || operation==\'save-provider\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(operation==\'provider\'?\'public:read\':\'public:write\',null,\'public\');\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n""");\n        if(operation==\'provider\') {\n            var value=old==null?{}:JSONUtil.parseObj(old.value_json);\n            return {\n                id:old==null?null:old.id,version:old==null?null:old.version,configured:old!=null && value.enabled==true,providerCode:value.providerCode||\'\',endpoint:value.endpoint||\'\',enabled:value.enabled||false,status:old==null || value.enabled!=true?\'UNCONFIGURED\':\'CONFIGURED\'\n            };\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'verification:save-provider\',p,()=>{\n            old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'核验配置已变更\';\n            }\n            var code=(p.providerCode||\'\').trim();\n            if(!code.matches(\'[A-Za-z][A-Za-z0-9_-]{2,63}\')) {\n                exit 400,\'核验渠道编码不正确\';\n            }\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var id=old==null?IdUtil.fastSimpleUUID():old.id;\n            var encoded=JSONUtil.toJsonStr({\n                providerCode:code,endpoint:endpoint,enabled:p.enabled==true\n            });\n            if(old==null) {\n                sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status)\nvalues(#{id},\'GLOBAL\',\'global\',\'VERIFICATION\',\'provider\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1\nwhere tid=#{id}\n""");\n            }\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(prior==null) {\n                    exit 400,\'核验接入密钥不能为空\';\n                }\n            }\n            else {\n                var cipher=identityTransport.encrypt(p.secret);\n                var revision=prior==null?1:prior.revision+1;\n                if(prior!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{prior.id}\n""");\n                }\n                var cid=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_cipher, status)\nvalues(#{cid},\'VERIFY_PROVIDER\',#{id},\'HMAC_KEY\',#{revision},\'AES256_GCM\',#{cipher},\'ACTIVE\')\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'verification:save-provider\',id,null,{\n                id:id,provider:code\n            });\n            return {\n                id:id\n            };\n        });\n    }\n    var ctx=accountContext();\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请使用已完成密码设置的公众认证账号\';\n    }\n    if(operation==\'mine\') {\n        return sql.select("""\nselect tid as id,target_type targetType,target_id targetId,status,result_code resultCode,\n       requested_time requestedTime,completed_time completedTime,expires_at expiresAt\nfrom iam_verification_t\nwhere (target_type=\'SUBJECT\'\n       and target_id=#{ctx.account.subject_id})\n    or (target_type=\'LEGAL_ENTITY\'\n        and created_by=#{ctx.userId})\norder by requested_time desc\nlimit 100\n""");\n    }\n    var provider=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var settings=provider==null?{}:JSONUtil.parseObj(provider.value_json);\n    if(settings.enabled!=true) {\n        exit 503,\'实名核验提供方尚未配置，不能完成实名核验\';\n    }\n    var key=sql.selectOne("""\nselect secret_cipher\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{provider.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 503,\'核验提供方凭据未配置\';\n    }\n    var type=p.targetType||\'SUBJECT\';\n    var target=type==\'SUBJECT\'?ctx.account.subject_id:p.targetId;\n    if(![\'SUBJECT\',\'LEGAL_ENTITY\'].contains(type) || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请明确同意核验并提供申请号\';\n    }\n    if(type==\'LEGAL_ENTITY\' && sql.selectOne("""\nselect tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{target}\n    and subject_id=#{ctx.account.subject_id}\n    and relation_type in (\'REPRESENTATIVE\',\'AGENT\')\n    and (status=\'ACTIVE\'\n         or status=\'PENDING\'\n         and created_by=#{ctx.userId})\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\nlimit 1\n""")==null) {\n        exit 403,\'没有此法人的有效经办资格\';\n    }\n    var document=(p.document||\'\').trim();\n    if(document==\'\' || document.length()>100 || (p.documentType||\'\').length()>32) {\n        exit 400,\'核验资料不正确\';\n    }\n    var identity=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n""");\n    if(identity==null || type==\'LEGAL_ENTITY\' && identity.registration_code!=document.toUpperCase()) {\n        exit 400,\'法人核验资料须匹配登记的信用代码\';\n    }\n    var requestId=DigestUtil.sha256Hex(ctx.userId+\':\'+p.requestId).substring(0,32);\n    var inputHash=identityTransport.protectedFingerprint(type+\':\'+target+\':\'+identity.name+\':\'+document+\':\'+p.documentType,\'verification\');\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var created=sql.transaction(()=>{\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere provider_code=#{settings.providerCode}\n    and provider_request_id=#{requestId}\n    for update\n""");\n        if(prior!=null) {\n            if(prior.consent_ref!=inputHash) {\n                exit 409,\'同一申请号的核验资料不一致\';\n            }\n            return prior;\n        }\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_verification_t(tid,\n                created_by, target_type, target_id, provider_code, provider_request_id, consent_ref,\n                requested_time)\nvalues(#{id},#{ctx.userId},#{type},#{target},#{settings.providerCode},#{requestId},#{inputHash},utc_timestamp(6))\n""");\n        if(type==\'SUBJECT\') {\n            var profile=sql.selectOne("""\nselect *,tid as id\nfrom iam_public_profile_t\nwhere subject_id=#{target}\n""");\n            var pid=profile==null?IdUtil.fastSimpleUUID():profile.id;\n            var cipher=identityTransport.protectValue(document,\'DOCUMENT:\'+target);\n            var fingerprint=identityTransport.protectedFingerprint(document,\'document:\'+p.documentType);\n            if(profile==null) {\n                sql.update("""\ninsert into iam_public_profile_t(tid,\n                subject_id, document_type, document_cipher, document_fingerprint, verification_status,\n                verification_id)\nvalues(#{pid},#{target},#{p.documentType},#{cipher},#{fingerprint},\'PENDING\',#{id})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_public_profile_t\nset document_type=#{p.documentType},document_cipher=#{cipher},document_fingerprint=#{fingerprint},\n    verification_status=\'PENDING\',verification_id=#{id},version=version+1\nwhere tid=#{pid}\n""");\n            }\n        }\n        else {\n            sql.update("""\nupdate iam_legal_entity_t\nset verification_status=\'PENDING\',version=version+1\nwhere tid=#{target}\n""");\n        }\n        return sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere tid=#{id}\n""");\n    });\n    if(created.status!=\'PENDING\') {\n        return {\n            id:created.id,status:created.status\n        };\n    }\n    var body=identityTransport.canonicalJson({\n        protocol:\'IDAAS_VERIFY/1\',providerCode:settings.providerCode,requestId:requestId,targetType:type,targetId:target,name:identity.name,documentType:p.documentType,document:document,consentRef:inputHash\n    });\n    var receipt=null;\n    try {\n        receipt=identityTransport.sendVerification(settings.endpoint,key.secret_cipher,settings.providerCode,requestId,body);\n    }\n    catch(e) {\n        sql.update("""\nupdate iam_verification_t\nset result_code=\'PROVIDER_UNAVAILABLE\',version=version+1\nwhere tid=#{created.id}\n""");\n        return {\n            id:created.id,status:\'PENDING\',resultCode:\'PROVIDER_UNAVAILABLE\'\n        };\n    }\n    if(receipt.protocol!=\'IDAAS_VERIFY/1\' || receipt.providerCode!=settings.providerCode || receipt.requestId!=requestId || receipt.targetType!=type || receipt.targetId!=target || ![\'VERIFIED\',\'REJECTED\',\'PENDING\'].contains(receipt.status) || (receipt.resultCode||\'\').length()>100) {\n        exit 502,\'核验回执目标或结果不正确\';\n    }\n    var expiry=null;\n    var evidence=receipt.evidenceRef;\n    if(receipt.status==\'VERIFIED\') {\n        try {\n            var end=Instant.parse(receipt.expiresAt);\n            var now=Instant.now();\n            if(!end.isAfter(now) || end.isAfter(now.plusSeconds(31536000)) || evidence==null || !evidence.matches(\'[A-Za-z0-9_.:/-]{1,1000}\')) {\n                exit 502,\'核验回执缺少有效期限或受控证据引用\';\n            }\n            expiry=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\').format(LocalDateTime.ofInstant(end,ZoneOffset.UTC));\n        }\n        catch(e) {\n            exit 502,\'核验回执有效期限不正确\';\n        }\n    }\n    return sql.transaction(()=>{\n        var current=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(current==null || current.name!=identity.name || type==\'LEGAL_ENTITY\' && current.registration_code!=identity.registration_code) {\n            sql.update("""\nupdate iam_verification_t\nset status=\'REJECTED\',result_code=\'IDENTITY_CHANGED\',version=version+1\nwhere tid=#{created.id}\n""");\n            return {\n                id:created.id,status:\'REJECTED\',resultCode:\'IDENTITY_CHANGED\'\n            };\n        }\n        var status=receipt.status;\n        sql.update("""\nupdate iam_verification_t\nset status=#{status},result_code=#{receipt.resultCode},completed_time=case\n        when #{status}=\'PENDING\' then null\n        else utc_timestamp(6)\n        end,\n        expires_at=#{expiry},\n        evidence_ref=#{evidence},version=version+1\nwhere tid=#{created.id}\n""");\n        if(type==\'SUBJECT\') {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=#{status},verified_time=case\n        when #{status}=\'VERIFIED\' then utc_timestamp(6) else null\n        end,version=version+1\nwhere subject_id=#{target}\n    and verification_id=#{created.id}\n""");\n        }\n        else {\n            var latest=sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{target}\norder by requested_time desc,tid desc\nlimit 1\n""");\n            if(latest!=null && latest.id==created.id) {\n                sql.update("""\nupdate iam_legal_entity_t\nset verification_status=#{status},version=version+1\nwhere tid=#{target}\n""");\n            }\n        }\n        audit(ctx,status==\'VERIFIED\'?\'SUCCESS\':\'FAILED\',\'auth:verification\',target,status,{\n            id:created.id,status:status\n        });\n        return {\n            id:created.id,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/04.查询本人实名核验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2d2ed39f83724fad874e0f148c5c7430',NULL,'api','{\n  "properties": {},\n  "id": "55c1602a7e8856a8833195aa7be6d16c",\n  "script": null,\n  "groupId": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "05.提交实名核验申请",\n  "createTime": 1790635007936,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/submit",\n  "description": "校验账号与证件资料，保护敏感字段并请求可信提供方；只有验签通过的真实回执才能改变核验状态。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：05.提交实名核验申请\n// 路由：POST /idaas/verifications/submit\n// 业务说明：校验账号与证件资料，保护敏感字段并请求可信提供方；只有验签通过的真实回执才能改变核验状态。\nimport db;\nimport java.time.Instant;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/auth-account-context\' as accountContext;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'submit\';\n\n    // 核验资料加密保存；只有受信任提供方的真实签名回执可以标记通过。\n    var sql=db.normal();\n    var p=payload||{};\n    if(operation==\'provider\' || operation==\'save-provider\') {\n        // 先校验当前会话的功能权限、身份域和应用管理范围。\n        var ctx=guard(operation==\'provider\'?\'public:read\':\'public:write\',null,\'public\');\n        var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n""");\n        if(operation==\'provider\') {\n            var value=old==null?{}:JSONUtil.parseObj(old.value_json);\n            return {\n                id:old==null?null:old.id,version:old==null?null:old.version,configured:old!=null && value.enabled==true,providerCode:value.providerCode||\'\',endpoint:value.endpoint||\'\',enabled:value.enabled||false,status:old==null || value.enabled!=true?\'UNCONFIGURED\':\'CONFIGURED\'\n            };\n        }\n        // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n        return mutate(ctx,\'verification:save-provider\',p,()=>{\n            old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and is_del=0\n    for update\n""");\n            // 以当前版本校验修改目标，阻止旧页面覆盖已经变更的记录。\n            if(old!=null && old.version!=p.version) {\n                exit 409,\'核验配置已变更\';\n            }\n            var code=(p.providerCode||\'\').trim();\n            if(!code.matches(\'[A-Za-z][A-Za-z0-9_-]{2,63}\')) {\n                exit 400,\'核验渠道编码不正确\';\n            }\n            var endpoint=identityTransport.validateUrl(p.endpoint);\n            var id=old==null?IdUtil.fastSimpleUUID():old.id;\n            var encoded=JSONUtil.toJsonStr({\n                providerCode:code,endpoint:endpoint,enabled:p.enabled==true\n            });\n            if(old==null) {\n                sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status)\nvalues(#{id},\'GLOBAL\',\'global\',\'VERIFICATION\',\'provider\',#{encoded},\'ACTIVE\')\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1\nwhere tid=#{id}\n""");\n            }\n            var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n    for update\n""");\n            if(p.secret==null || p.secret==\'\') {\n                if(prior==null) {\n                    exit 400,\'核验接入密钥不能为空\';\n                }\n            }\n            else {\n                var cipher=identityTransport.encrypt(p.secret);\n                var revision=prior==null?1:prior.revision+1;\n                if(prior!=null) {\n                    sql.update("""\nupdate iam_credential_t\nset status=\'RETIRED\'\nwhere tid=#{prior.id}\n""");\n                }\n                var cid=IdUtil.fastSimpleUUID();\n                sql.update("""\ninsert into iam_credential_t(tid,\n                owner_kind, owner_id, credential_type, revision, algorithm, secret_cipher, status)\nvalues(#{cid},\'VERIFY_PROVIDER\',#{id},\'HMAC_KEY\',#{revision},\'AES256_GCM\',#{cipher},\'ACTIVE\')\n""");\n            }\n            // 记录操作主体、目标及结果，供审计与故障追踪。\n            audit(ctx,\'SUCCESS\',\'verification:save-provider\',id,null,{\n                id:id,provider:code\n            });\n            return {\n                id:id\n            };\n        });\n    }\n    var ctx=accountContext();\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请使用已完成密码设置的公众认证账号\';\n    }\n    var provider=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere category=\'VERIFICATION\'\n    and config_key=\'provider\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n    var settings=provider==null?{}:JSONUtil.parseObj(provider.value_json);\n    if(settings.enabled!=true) {\n        exit 503,\'实名核验提供方尚未配置，不能完成实名核验\';\n    }\n    var key=sql.selectOne("""\nselect secret_cipher\nfrom iam_credential_t\nwhere owner_kind=\'VERIFY_PROVIDER\'\n    and owner_id=#{provider.id}\n    and credential_type=\'HMAC_KEY\'\n    and status=\'ACTIVE\'\n""");\n    if(key==null) {\n        exit 503,\'核验提供方凭据未配置\';\n    }\n    var type=p.targetType||\'SUBJECT\';\n    var target=type==\'SUBJECT\'?ctx.account.subject_id:p.targetId;\n    if(![\'SUBJECT\',\'LEGAL_ENTITY\'].contains(type) || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请明确同意核验并提供申请号\';\n    }\n    if(type==\'LEGAL_ENTITY\' && sql.selectOne("""\nselect tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{target}\n    and subject_id=#{ctx.account.subject_id}\n    and relation_type in (\'REPRESENTATIVE\',\'AGENT\')\n    and (status=\'ACTIVE\'\n         or status=\'PENDING\'\n         and created_by=#{ctx.userId})\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\nlimit 1\n""")==null) {\n        exit 403,\'没有此法人的有效经办资格\';\n    }\n    var document=(p.document||\'\').trim();\n    if(document==\'\' || document.length()>100 || (p.documentType||\'\').length()>32) {\n        exit 400,\'核验资料不正确\';\n    }\n    var identity=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n""");\n    if(identity==null || type==\'LEGAL_ENTITY\' && identity.registration_code!=document.toUpperCase()) {\n        exit 400,\'法人核验资料须匹配登记的信用代码\';\n    }\n    var requestId=DigestUtil.sha256Hex(ctx.userId+\':\'+p.requestId).substring(0,32);\n    var inputHash=identityTransport.protectedFingerprint(type+\':\'+target+\':\'+identity.name+\':\'+document+\':\'+p.documentType,\'verification\');\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    var created=sql.transaction(()=>{\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere provider_code=#{settings.providerCode}\n    and provider_request_id=#{requestId}\n    for update\n""");\n        if(prior!=null) {\n            if(prior.consent_ref!=inputHash) {\n                exit 409,\'同一申请号的核验资料不一致\';\n            }\n            return prior;\n        }\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_verification_t(tid,\n                created_by, target_type, target_id, provider_code, provider_request_id, consent_ref,\n                requested_time)\nvalues(#{id},#{ctx.userId},#{type},#{target},#{settings.providerCode},#{requestId},#{inputHash},utc_timestamp(6))\n""");\n        if(type==\'SUBJECT\') {\n            var profile=sql.selectOne("""\nselect *,tid as id\nfrom iam_public_profile_t\nwhere subject_id=#{target}\n""");\n            var pid=profile==null?IdUtil.fastSimpleUUID():profile.id;\n            var cipher=identityTransport.protectValue(document,\'DOCUMENT:\'+target);\n            var fingerprint=identityTransport.protectedFingerprint(document,\'document:\'+p.documentType);\n            if(profile==null) {\n                sql.update("""\ninsert into iam_public_profile_t(tid,\n                subject_id, document_type, document_cipher, document_fingerprint, verification_status,\n                verification_id)\nvalues(#{pid},#{target},#{p.documentType},#{cipher},#{fingerprint},\'PENDING\',#{id})\n""");\n            }\n            else {\n                sql.update("""\nupdate iam_public_profile_t\nset document_type=#{p.documentType},document_cipher=#{cipher},document_fingerprint=#{fingerprint},\n    verification_status=\'PENDING\',verification_id=#{id},version=version+1\nwhere tid=#{pid}\n""");\n            }\n        }\n        else {\n            sql.update("""\nupdate iam_legal_entity_t\nset verification_status=\'PENDING\',version=version+1\nwhere tid=#{target}\n""");\n        }\n        return sql.selectOne("""\nselect *,tid as id\nfrom iam_verification_t\nwhere tid=#{id}\n""");\n    });\n    if(created.status!=\'PENDING\') {\n        return {\n            id:created.id,status:created.status\n        };\n    }\n    var body=identityTransport.canonicalJson({\n        protocol:\'IDAAS_VERIFY/1\',providerCode:settings.providerCode,requestId:requestId,targetType:type,targetId:target,name:identity.name,documentType:p.documentType,document:document,consentRef:inputHash\n    });\n    var receipt=null;\n    try {\n        receipt=identityTransport.sendVerification(settings.endpoint,key.secret_cipher,settings.providerCode,requestId,body);\n    }\n    catch(e) {\n        sql.update("""\nupdate iam_verification_t\nset result_code=\'PROVIDER_UNAVAILABLE\',version=version+1\nwhere tid=#{created.id}\n""");\n        return {\n            id:created.id,status:\'PENDING\',resultCode:\'PROVIDER_UNAVAILABLE\'\n        };\n    }\n    if(receipt.protocol!=\'IDAAS_VERIFY/1\' || receipt.providerCode!=settings.providerCode || receipt.requestId!=requestId || receipt.targetType!=type || receipt.targetId!=target || ![\'VERIFIED\',\'REJECTED\',\'PENDING\'].contains(receipt.status) || (receipt.resultCode||\'\').length()>100) {\n        exit 502,\'核验回执目标或结果不正确\';\n    }\n    var expiry=null;\n    var evidence=receipt.evidenceRef;\n    if(receipt.status==\'VERIFIED\') {\n        try {\n            var end=Instant.parse(receipt.expiresAt);\n            var now=Instant.now();\n            if(!end.isAfter(now) || end.isAfter(now.plusSeconds(31536000)) || evidence==null || !evidence.matches(\'[A-Za-z0-9_.:/-]{1,1000}\')) {\n                exit 502,\'核验回执缺少有效期限或受控证据引用\';\n            }\n            expiry=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\').format(LocalDateTime.ofInstant(end,ZoneOffset.UTC));\n        }\n        catch(e) {\n            exit 502,\'核验回执有效期限不正确\';\n        }\n    }\n    return sql.transaction(()=>{\n        var current=type==\'SUBJECT\'?sql.selectOne("""\nselect name\nfrom iam_subject_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n"""):sql.selectOne("""\nselect name,registration_code\nfrom iam_legal_entity_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n        if(current==null || current.name!=identity.name || type==\'LEGAL_ENTITY\' && current.registration_code!=identity.registration_code) {\n            sql.update("""\nupdate iam_verification_t\nset status=\'REJECTED\',result_code=\'IDENTITY_CHANGED\',version=version+1\nwhere tid=#{created.id}\n""");\n            return {\n                id:created.id,status:\'REJECTED\',resultCode:\'IDENTITY_CHANGED\'\n            };\n        }\n        var status=receipt.status;\n        sql.update("""\nupdate iam_verification_t\nset status=#{status},result_code=#{receipt.resultCode},completed_time=case\n        when #{status}=\'PENDING\' then null\n        else utc_timestamp(6)\n        end,\n        expires_at=#{expiry},\n        evidence_ref=#{evidence},version=version+1\nwhere tid=#{created.id}\n""");\n        if(type==\'SUBJECT\') {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=#{status},verified_time=case\n        when #{status}=\'VERIFIED\' then utc_timestamp(6) else null\n        end,version=version+1\nwhere subject_id=#{target}\n    and verification_id=#{created.id}\n""");\n        }\n        else {\n            var latest=sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{target}\norder by requested_time desc,tid desc\nlimit 1\n""");\n            if(latest!=null && latest.id==created.id) {\n                sql.update("""\nupdate iam_legal_entity_t\nset verification_status=#{status},version=version+1\nwhere tid=#{target}\n""");\n            }\n        }\n        audit(ctx,status==\'VERIFIED\'?\'SUCCESS\':\'FAILED\',\'auth:verification\',target,status,{\n            id:created.id,status:status\n        });\n        return {\n            id:created.id,status:status\n        };\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/05.提交实名核验申请.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dd31222bb38c45bd924a6ec8ffd1d680',NULL,NULL,'{\n  "properties": {},\n  "id": "36e1ceb97f9550bcb7092a621f8ee8bd",\n  "name": "30.实名核验",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/verifications",\n  "createTime": 1790635007936,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/30.实名核验/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d4d1496b4a3c47f18bb10e05d349cfd9',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/31.法人自主登记/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('406b39217e3044b0b847b944755d320f',NULL,'api','{\n  "properties": {},\n  "id": "c97fb943c17750e8a59547fbb5f9ca03",\n  "script": null,\n  "groupId": "2c7d2be6a1f65dcc917d9d26722a0a72",\n  "name": "01.自主登记法人",\n  "createTime": 1790636427981,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/register",\n  "description": "校验当前认证账号及法人登记资料，创建待核验法人和申请人与法人的成员关系。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.自主登记法人\n// 路由：POST /idaas/self-entities/register\n// 业务说明：校验当前认证账号及法人登记资料，创建待核验法人和申请人与法人的成员关系。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport \'@/idaas/auth-account-context\' as context;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload=body;\n    // 请求参数与本接口业务处理。\n    var operation = \'register\';\n\n    var ctx=context();\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请先登录并完成公众账号密码设置\';\n    }\n    if(operation!=\'register\' || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请同意法人资料登记并提供申请号\';\n    }\n    var name=(p.name||\'\').trim();\n    var registration=(p.registrationCode||\'\').trim().toUpperCase();\n    if(name==\'\' || name.length()>200 || !registration.matches(\'[0-9A-HJ-NPQRTUWXY]{18}\')) {\n        exit 400,\'法人名称或信用代码格式不正确\';\n    }\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    return sql.transaction(()=>{\n        sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=\'idaas-platform-internal\'\n    for update\n""");\n        var hash=identityTransport.protectedFingerprint(DigestUtil.sha256Hex(identityTransport.canonicalJson(p)),\'receipt:v2\');\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_request_receipt_t\nwhere operator_id=#{ctx.userId}\n    and operation_code=\'SELF_LEGAL_REGISTER\'\n    and request_id=#{p.requestId}\n""");\n        if(prior!=null) {\n            if(prior.request_hash!=hash) {\n                exit 409,\'申请号资料不一致\';\n            }\n            return JSONUtil.parseObj(prior.result_json);\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_legal_entity_t\nwhere registration_code=#{registration}\n""")!=null) {\n            exit 409,\'此法人已登记，请联系身份管理人员办理关联\';\n        }\n        var id=IdUtil.fastSimpleUUID();\n        var code=\'PUBLIC_LEGAL_\'+id;\n        var mid=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_legal_entity_t(tid,\n                created_by, code, name, registration_code, verification_status, status)\nvalues(#{id},#{ctx.userId},#{code},#{name},#{registration},\'UNVERIFIED\',\'ACTIVE\')\n""");\n        sql.update("""\ninsert into iam_legal_member_t(tid,\n                created_by, entity_id, subject_id, auth_account_id, relation_type, valid_from, status)\nvalues(#{mid},#{ctx.userId},#{id},#{ctx.account.subject_id},#{ctx.userId},\'AGENT\',utc_timestamp(6),\'PENDING\')\n""");\n        var result=identityTransport.canonicalJson({\n            id:id,memberId:mid,verificationStatus:\'UNVERIFIED\',relationStatus:\'PENDING\'\n        });\n        var rid=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_request_receipt_t(tid,\n                operator_id, operation_code, request_id, request_hash, status, result_json)\nvalues(#{rid},#{ctx.userId},\'SELF_LEGAL_REGISTER\',#{p.requestId},#{hash},\'SUCCEEDED\',#{result})\n""");\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth:legal-register\',id,null,{\n            id:id\n        });\n        return JSONUtil.parseObj(result);\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/31.法人自主登记/01.自主登记法人.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fcbd3dc7ec04416e83c9fe3f045d0315',NULL,'api','{\n  "properties": {},\n  "id": "54371175f20c5b8cb28c1769c05e2180",\n  "script": null,\n  "groupId": "2c7d2be6a1f65dcc917d9d26722a0a72",\n  "name": "02.查询本人法人登记",\n  "createTime": 1790636427981,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/mine",\n  "description": "按当前认证账号查询其申请或可办理的法人资料和审核状态，仅返回本人可见记录。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：02.查询本人法人登记\n// 路由：GET /idaas/self-entities/mine\n// 业务说明：按当前认证账号查询其申请或可办理的法人资料和审核状态，仅返回本人可见记录。\nimport db;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport \'@/idaas/auth-account-context\' as context;\nimport \'@/idaas/audit\' as audit;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\n\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var payload={};\n    for(key in [\'id\',\'appId\',\'domain\']) {\n        var value=request.getValues(key);\n        if(value!=null && value.size()>0) {\n            payload.put(key,value[0]);\n        }\n    }\n    // 请求参数与本接口业务处理。\n    var operation = \'mine\';\n\n    var ctx=context();\n    // 获取当前身份域的数据库连接；租户接收流程在租户上下文内取得对应库。\n    var sql=db.normal();\n    var p=payload||{};\n    if(ctx.account.identity_domain!=\'public\' || ctx.account.must_change_password==1) {\n        exit 403,\'请先登录并完成公众账号密码设置\';\n    }\n    if(operation==\'mine\') {\n        return sql.select("""\nselect e.tid as id,e.name,e.registration_code registrationCode,\n       case\n           when e.verification_status=\'VERIFIED\'\n                and not exists\n                    (select 1\n                     from iam_verification_t v\n                     where v.target_type=\'LEGAL_ENTITY\'\n        and v.target_id=e.tid\n        and v.status=\'VERIFIED\'\n        and v.expires_at>utc_timestamp(6)\n        and v.tid=\n        (select x.tid as id\n        from iam_verification_t x\n        where x.target_type=\'LEGAL_ENTITY\'\n        and x.target_id=e.tid\n        order by x.requested_time desc, x.tid desc\n        limit 1)) then \'EXPIRED\' else e.verification_status\n       end verificationStatus,m.tid memberId,\n       case\n           when m.status=\'ACTIVE\'\n                and (m.valid_from>utc_timestamp(6)\n                     or m.valid_until<=utc_timestamp(6)) then \'EXPIRED\' else m.status\n       end relationStatus,m.relation_type relationType\nfrom iam_legal_entity_t e\njoin iam_legal_member_t m on m.entity_id=e.tid\nand m.subject_id=#{ctx.account.subject_id}\nand m.is_del=0\nwhere e.is_del=0\norder by e.created_time desc\n""");\n    }\n    if(operation!=\'register\' || p.consent!=true || p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n        exit 400,\'请同意法人资料登记并提供申请号\';\n    }\n    var name=(p.name||\'\').trim();\n    var registration=(p.registrationCode||\'\').trim().toUpperCase();\n    if(name==\'\' || name.length()>200 || !registration.matches(\'[0-9A-HJ-NPQRTUWXY]{18}\')) {\n        exit 400,\'法人名称或信用代码格式不正确\';\n    }\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    return sql.transaction(()=>{\n        sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=\'idaas-platform-internal\'\n    for update\n""");\n        var hash=identityTransport.protectedFingerprint(DigestUtil.sha256Hex(identityTransport.canonicalJson(p)),\'receipt:v2\');\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_request_receipt_t\nwhere operator_id=#{ctx.userId}\n    and operation_code=\'SELF_LEGAL_REGISTER\'\n    and request_id=#{p.requestId}\n""");\n        if(prior!=null) {\n            if(prior.request_hash!=hash) {\n                exit 409,\'申请号资料不一致\';\n            }\n            return JSONUtil.parseObj(prior.result_json);\n        }\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_legal_entity_t\nwhere registration_code=#{registration}\n""")!=null) {\n            exit 409,\'此法人已登记，请联系身份管理人员办理关联\';\n        }\n        var id=IdUtil.fastSimpleUUID();\n        var code=\'PUBLIC_LEGAL_\'+id;\n        var mid=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_legal_entity_t(tid,\n                created_by, code, name, registration_code, verification_status, status)\nvalues(#{id},#{ctx.userId},#{code},#{name},#{registration},\'UNVERIFIED\',\'ACTIVE\')\n""");\n        sql.update("""\ninsert into iam_legal_member_t(tid,\n                created_by, entity_id, subject_id, auth_account_id, relation_type, valid_from, status)\nvalues(#{mid},#{ctx.userId},#{id},#{ctx.account.subject_id},#{ctx.userId},\'AGENT\',utc_timestamp(6),\'PENDING\')\n""");\n        var result=identityTransport.canonicalJson({\n            id:id,memberId:mid,verificationStatus:\'UNVERIFIED\',relationStatus:\'PENDING\'\n        });\n        var rid=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_request_receipt_t(tid,\n                operator_id, operation_code, request_id, request_hash, status, result_json)\nvalues(#{rid},#{ctx.userId},\'SELF_LEGAL_REGISTER\',#{p.requestId},#{hash},\'SUCCEEDED\',#{result})\n""");\n        // 记录操作主体、目标及结果，供审计与故障追踪。\n        audit(ctx,\'SUCCESS\',\'auth:legal-register\',id,null,{\n            id:id\n        });\n        return JSONUtil.parseObj(result);\n    });\n\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/31.法人自主登记/02.查询本人法人登记.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b6186494367447b0bd8808363e79b77a',NULL,NULL,'{\n  "properties": {},\n  "id": "2c7d2be6a1f65dcc917d9d26722a0a72",\n  "name": "31.法人自主登记",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/self-entities",\n  "createTime": 1790636427981,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/31.法人自主登记/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e8746ff555b749debc04e78940abd7fb',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/32.接口认证执行/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7f63412a549b40f7aef2b901c4219a5b',NULL,'api','{\n  "properties": {},\n  "id": "8733f3234268544bbe84d00927f55e99",\n  "script": null,\n  "groupId": "69d8099e140554c19b063ba451355aad",\n  "name": "01.查询接口调用身份",\n  "createTime": 1790636675438,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/whoami",\n  "description": "校验 Bearer 令牌的签名、受众、应用权限和撤销状态，返回当前接口调用身份及有效授权。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：01.查询接口调用身份\n// 路由：GET /idaas/api/whoami\n// 业务说明：校验 Bearer 令牌的签名、受众、应用权限和撤销状态，返回当前接口调用身份及有效授权。\nimport identityRuntime;\nimport identityApi;\nimport request;\nimport org.slf4j.LoggerFactory;\nimport \'@/idaas/api-call\' as apiCall;\n\n// Executable JWT integration contract. appId must match the token audience;\n// permissions and revocation are recalculated on the server for this real path.\nreturn identityRuntime.control(()=>apiCall(()=>{\n    try {\n        var values=request.getValues(\'appId\');\n        return identityApi.authorize(values==null || values.size()!=1?null:values[0]);\n    }\n    catch(e) {\n        LoggerFactory.getLogger(\'idaas.protocol\').warn(\'API integration rejected: \'+e.getClass().getSimpleName());\n        exit 403,\'访问令牌或当前接口授权无效\';\n    }\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/32.接口认证执行/01.查询接口调用身份.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('17e2e42333ac47f5b9de7e8b2de5bd9c',NULL,NULL,'{\n  "properties": {},\n  "id": "69d8099e140554c19b063ba451355aad",\n  "name": "32.接口认证执行",\n  "type": "api",\n  "parentId": "1ae52a0ba8565e9d820f00dec5d199af",\n  "path": "/api",\n  "createTime": 1790636675438,\n  "updateTime": 1790946845378,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/32.接口认证执行/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('25d9c342edda4c57b20df143e9f401a8',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/33.密码找回/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2a0e84408249413e92827738d5782813',NULL,'api','{\n  "properties": {},\n  "id": "16fe18be7f815f8a90784acaa3a32b12",\n  "script": null,\n  "groupId": "039920aa11d55b4faed04ad7b00bbf94",\n  "name": "01.提交密码找回申请",\n  "createTime": 1791193400395,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/request",\n  "description": "公开提交管理员核验申请，统一回执防止账号枚举；按来源和账号限频并记录脱敏审计。",\n  "parameters": [],\n  "method": "POST",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：提交管理员核验的密码找回申请；统一回执不暴露账号是否存在。\n// 路由：POST /idaas/password-recovery/request\nimport db;\nimport identityRuntime;\nimport request;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/audit\' as audit;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var p=body||{};\n    var realm=p.realm||\'platform\';\n    var domain=realm==\'platform\'?\'workforce\':p.domain||\'public\';\n    var username=(p.username||\'\').trim().toLowerCase();\n    if(![\'platform\',\'auth-account\'].contains(realm) || ![\'workforce\',\'public\'].contains(domain)\n        || username.length()<3 || username.length()>100\n        || !username.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\')) {\n        exit 400,\'请输入有效账号\';\n    }\n    var sql=db.normal();\n    var ip=request.getClientIP();\n    var generic={accepted:true,message:\'申请已提交。如账号存在，请联系对应管理员完成身份核验和重置。\'};\n    var recent=sql.selectOne("""\nselect count(*) n from iam_audit_event_t\nwhere action=\'password:recovery-request\' and ip=#{ip}\n  and event_time>date_sub(utc_timestamp(6),interval 1 hour)\n""");\n    if(recent.n>=20) {\n        return generic;\n    }\n    var principal=realm==\'platform\'?sql.selectOne("""\nselect tid as id from iam_operator_t\nwhere active_username=#{username} and status=\'ACTIVE\' and is_del=0\n"""):sql.selectOne("""\nselect tid as id from iam_auth_account_t\nwhere active_username=#{username} and identity_domain=#{domain}\n  and status=\'ACTIVE\' and is_del=0\n""");\n    var kind=realm==\'platform\'?\'OPERATOR\':\'AUTH_ACCOUNT\';\n    var principalId=principal==null?\'__unknown__\':principal.id;\n    var duplicate=sql.selectOne("""\nselect count(*) n from iam_audit_event_t\nwhere action=\'password:recovery-request\' and object_id=#{principalId}\n  and reason_code=#{kind}\n  and event_time>date_sub(utc_timestamp(6),interval 1 hour)\n""");\n    if(principal==null) {\n        audit({userId:null,actorKind:\'ANONYMOUS\',requiredDomain:domain},\'DENIED\',\n            \'password:recovery-request\',null,\'UNKNOWN\',{channel:\'ADMIN_VERIFICATION\'});\n        return generic;\n    }\n    if(duplicate.n>=1) {\n        return generic;\n    }\n    audit({userId:null,actorKind:\'ANONYMOUS\',requiredDomain:domain},\'SUCCESS\',\n        \'password:recovery-request\',principal.id,kind,{channel:\'ADMIN_VERIFICATION\'});\n    return generic;\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/33.密码找回/01.提交密码找回申请.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('02fce5215b7043e49d420d9a2590eda6',NULL,'api','{\n  "properties": {},\n  "id": "a7aa191e975b505e96298e4aacfb365f",\n  "script": null,\n  "groupId": "039920aa11d55b4faed04ad7b00bbf94",\n  "name": "02.分页查询待核验申请",\n  "createTime": 1791193400395,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/requests",\n  "description": "仅有操作账号或认证账号写入权限的管理员可按身份域查看待核验申请。",\n  "parameters": [],\n  "method": "GET",\n  "options": [],\n  "requestBody": "{}",\n  "headers": [],\n  "paths": [],\n  "responseBody": null\n}\n================================\n// 接口：分页查询待管理员核验的密码找回申请。\n// 路由：GET /idaas/password-recovery/requests\nimport db;\nimport identityRuntime;\nimport request;\nimport java.lang.Long;\nimport \'@/idaas/api-call\' as apiCall;\nimport \'@/idaas/guard\' as guard;\n\nreturn identityRuntime.control(()=>apiCall(()=>{\n    var param=(key,fallback)=>{\n        var values=request.getValues(key);\n        return values==null || values.size()==0?fallback:values[0];\n    };\n    var realm=param(\'realm\',\'platform\');\n    var domain=realm==\'platform\'?\'workforce\':param(\'domain\',\'public\');\n    var pageText=param(\'page\',\'1\');\n    var sizeText=param(\'size\',\'20\');\n    if(![\'platform\',\'auth-account\'].contains(realm) || ![\'workforce\',\'public\'].contains(domain)\n        || !pageText.matches(\'[0-9]{1,5}\') || !sizeText.matches(\'[0-9]{1,3}\')) {\n        exit 400,\'申请查询参数不正确\';\n    }\n    var page=Long.parseLong(pageText);\n    var size=Long.parseLong(sizeText);\n    if(page<1 || size<1 || size>100) {\n        exit 400,\'分页范围不正确\';\n    }\n    guard(realm==\'platform\'?\'operators:write\':\'auth-accounts:write\',null,domain);\n    var sql=db.normal();\n    var kind=realm==\'platform\'?\'OPERATOR\':\'AUTH_ACCOUNT\';\n    var resetAction=realm==\'platform\'?\'operators:reset-password\':\'auth-accounts:reset\';\n    var table=realm==\'platform\'?\'iam_operator_profile_v\':\'iam_auth_account_t\';\n    var nameColumn=realm==\'platform\'?\'a.display_name\':\'person.name\';\n    var filter="""\nfrom iam_audit_event_t e\njoin """+table+""" a on a.tid=e.object_id\n"""+(realm==\'platform\'?\'\':" join iam_subject_t person on person.tid=a.subject_id and person.identity_domain=#{domain} and person.is_del=0 ")+"""\nwhere e.action=\'password:recovery-request\' and e.result=\'SUCCESS\'\n  and e.reason_code=#{kind} and e.identity_domain=#{domain}\n  and e.event_time>date_sub(utc_timestamp(6),interval 7 day)\n  and a.status=\'ACTIVE\' and a.is_del=0\n  and not exists (select 1 from iam_audit_event_t finished\n    where finished.object_id=e.object_id and finished.action=#{resetAction}\n      and finished.result=\'SUCCESS\' and finished.event_time>e.event_time)\n  and not exists (select 1 from iam_audit_event_t newer\n    where newer.object_id=e.object_id and newer.action=\'password:recovery-request\'\n      and newer.reason_code=#{kind} and newer.result=\'SUCCESS\'\n      and newer.event_time>e.event_time)\n""";\n    if(realm==\'auth-account\') {\n        filter=filter+" and a.identity_domain=#{domain}";\n    }\n    var total=sql.selectOne(\'select count(*) total \'+filter).total;\n    var offset=(page-1)*size;\n    var rows=sql.select("select e.tid as id,e.object_id account_id,e.event_time requested_at,a.username,"\n        +nameColumn+" display_name,a.version "+filter+" order by e.event_time desc,e.tid desc limit #{size} offset #{offset}");\n    return {list:rows.map(row=>({\n        id:row.id,accountId:row.account_id,username:row.username,name:row.display_name,\n        version:row.version,requestedAt:row.requested_at,realm:realm,domain:domain\n    })),total:total,page:page,size:size};\n}));\n',NULL,NULL,0,NULL,'/magic-api/api/13.统一身份管理/33.密码找回/02.分页查询待核验申请.ms');
