务表\\",\\n                \\"orgPath\\": \\"000700020002\\",\\n                \\"tableType\\": \\"数据表\\",\\n                \\"tableNameCn\\": \\"标准库_海上执法人员信息表\\",\\n                \\"recordCount\\": \\"0\\"\\n            },\\n            {\\n                \\"id\\": \\"0776ca99e8b547fa99ba4df32bd27a2e\\",\\n                \\"tid\\": \\"0776ca99e8b547fa99ba4df32bd27a2e\\",\\n                \\"tenantId\\": null,\\n                \\"assetType\\": \\"table\\",\\n                \\"assetStatus\\": 0,\\n                \\"flowStatus\\": 0,\\n                \\"regTime\\": \\"2026-05-28 19:42:12\\",\\n                \\"createdTime\\": \\"2026-05-28 19:42:12\\",\\n                \\"updatedTime\\": \\"2026-05-28 19:42:12\\",\\n                \\"regTime_date\\": \\"2026-05-28 19:42:12\\",\\n                \\"createdTime_date\\": \\"2026-05-28 19:42:12\\",\\n                \\"updatedTime_date\\": \\"2026-05-28 19:42:12\\",\\n                \\"dataCatalogNum\\": null,\\n                \\"businessType\\": \\"业务表\\",\\n                \\"totalSizeFormatted\\": \\"0 B\\",\\n                \\"rowCount\\": \\"0\\",\\n                \\"ddlUpdateTime\\": \\"2026-05-28 19:37:39.0\\",\\n                \\"tableNameCn\\": \\"标准库_船员证件信息\\",\\n                \\"ddlCreatTime\\": null,\\n                \\"fieldCount\\": \\"17\\",\\n                \\"orgPath\\": \\"000700020002\\",\\n                \\"orgId\\": \\"2058493826078998529\\",\\n                \\"recordCount\\": \\"0\\"\\n            }\\n        ]\\n    }\\n}",\n  "description": "读取范围：ES dataassets 索引，按资产类型、状态、组织、关键字等条件过滤；使用请求参数 pageNum、pageSize、sortField、sortDir、conditions、keyword、noEnrich；涉及 sym_application_t、db_datasource_t、db_table_t、da_prop_t 等业务表。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.资产分页查询\n// 路由：POST /page\n// 业务说明：读取范围：ES dataassets 索引，按资产类型、状态、组织、关键字等条件过滤；使用请求参数 pageNum、pageSize、sortField、sortDir、conditions、keyword、noEnrich；涉及 sym_application_t、db_datasource_t、db_table_t、da_prop_t 等业务表。\nimport tenantEs\nimport \'@/common/configData\' as configData\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport java.util.List\n\n// 接口说明：资产分页查询。\n// 读取范围：ES dataassets 索引，按资产类型、状态、组织、关键字等条件过滤。\n// 写入行为：无写入。\n// 校验方式：用 pageNum/pageSize 和 assetType 验证 total 与 ES/da_asset_t 活跃资产口径一致。\n\n// 资产分页查询：直接查询 dataassets ES，少量读取 da_prop_t 补 app/db/table/catalog 名称。\n// 写入行为：无。数量统计统一走 ES count，避免页面分页被关系表循环查询拖慢。\n\nvar textOf = (value) => value == null ? null : value + \'\'\nvar blank = (value) => value == null || textOf(value).trim() == \'\'\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    for (key in keys) {\n        var value = row[key]\n        if (value != null) {\n            // 返回当前业务分支的标准结果。\n            return value\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return null\n}\nvar propValue = (assetId, propName) => {\n    if (blank(assetId) || blank(propName)) {\n        // 返回当前业务分支的标准结果。\n        return null\n    }\n    if (propName == \'appName\') {\n        // 从 MySQL 业务表读取当前有效数据。\n        return rowValue(db.table(\'sym_application_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne(), [\'appName\', \'app_name\'])\n    }\n    if (propName == \'dbName\') {\n        // 从 MySQL 业务表读取当前有效数据。\n        return rowValue(db.table(\'db_datasource_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne(), [\'dbName\', \'db_name\'])\n    }\n    if (propName == \'tableName\') {\n        // 从 MySQL 业务表读取当前有效数据。\n        return rowValue(db.table(\'db_table_t\').where().eq(\'tid\', assetId).eq(\'is_del\', 0).selectOne(), [\'tableNameCn\', \'table_name_cn\', \'tableName\', \'table_name\'])\n    }\n    // 从 MySQL 业务表读取当前有效数据。\n    var row = db.table(\'da_prop_t\').where().eq(\'parent_id\', assetId).eq(\'prop_name\', propName).eq(\'is_del\', 0).selectOne()\n    // 返回当前业务分支的标准结果。\n    return rowValue(row, [\'propValue\', \'prop_value\'])\n}\nvar boolFor = (field, value, assetType) => {\n    var filter = []\n    filter.add({ term: { [field]: value } })\n    if (!blank(assetType)) {\n        filter.add({ term: { assetType: assetType } })\n    }\n    // 返回当前业务分支的标准结果。\n    return { bool: { filter: filter } }\n}\nvar countEs = (field, value, assetType) => {\n    if (blank(value)) {\n        // 返回当前业务分支的标准结果。\n        return 0\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    return esCommonService.countByJsonQuery(\'dataassets\', jsons.toJSONStr(boolFor(field, value, assetType)))\n}\nvar idsEs = (field, value, assetType) => {\n    var ids = []\n    if (blank(value)) {\n        // 返回当前业务分支的标准结果。\n        return ids\n    }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    var result = tenantEs.index(configData().es_dataassets).search({ size: 10000, _source: [\'tid\'], query: boolFor(field, value, assetType) })\n    for (hit in (result?.hits?.hits || [])) {\n        if (!blank(hit?._source?.tid)) {\n            ids.add(hit._source.tid)\n        }\n    }\n    // 返回当前业务分支的标准结果。\n    return ids\n}\nvar countTablesByDbIds = (dbIds) => {\n    if (dbIds == null || dbIds.size() == 0) {\n        // 返回当前业务分支的标准结果。\n        return 0\n    }\n    var query = { bool: { filter: [ { terms: { dbId: dbIds } }, { term: { assetType: \'table\' } } ] } }\n    // 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\n    return esCommonService.countByJsonQuery(\'dataassets\', jsons.toJSONStr(query))\n}\nvar addCondition = (must, mustNot, item) => {\n    if (item == null || blank(item.field)) {\n        return\n    }\n    var type = item.type || \'match\'\n    var value = item.value\n    if (type == \'null\') {\n        mustNot.add({ exists: { field: item.field } })\n        return\n    }\n    if (blank(value) && type != \'null\') {\n        return\n    }\n    if (type == \'like\') {\n        must.add({ wildcard: { [item.field]: `*${value}*` } })\n    } else if (type == \'in\') {\n        var values = value instanceof List ? value : [value]\n        must.add({ terms: { [item.field]: values } })\n    } else {\n        must.add({ term: { [item.field]: value } })\n    }\n}\nvar enrich = (list) => {\n    for (item in list) {\n        var assetType = item.assetType\n        if (assetType == \'app\') {\n            var dbIds = idsEs(\'appId\', item.tid, \'db\')\n            item.dbNum = dbIds.size()\n            item.catalogNum = countEs(\'appId\', item.tid, \'catalog\')\n            item.tableNum = dbIds.size() > 0 ? countTablesByDbIds(dbIds) : countEs(\'appId\', item.tid, \'table\')\n        } else if (assetType == \'db\') {\n            if (!blank(item.appId)) {\n                item.appName = propValue(item.appId, \'appName\')\n            }\n            item.tableNum = countEs(\'dbId\', item.tid, \'table\')\n            item.catalogNum = countEs(\'dbId\', item.tid, \'catalog\')\n        } else if (assetType == \'table\') {\n            if (!blank(item.dbId)) {\n                item.dbName = propValue(item.dbId, \'dbName\')\n            }\n            if (!blank(item.appId)) {\n                item.appName = propValue(item.appId, \'appName\')\n            }\n        } else if (assetType == \'catalog\') {\n            if (!blank(item.sourceTableId)) {\n                item.sourceTableName = propValue(item.sourceTableId, \'tableName\')\n            }\n            if (!blank(item.dbId)) {\n                item.dbName = propValue(item.dbId, \'dbName\')\n            }\n            if (!blank(item.appId)) {\n                item.appName = propValue(item.appId, \'appName\')\n            }\n        }\n    }\n}\n\n// 解析请求体并为可选参数设置默认值。\nvar pageNum = (body?.pageNum || 1)::int(1)\nvar pageSize = (body?.pageSize || 20)::int(20)\nvar sortField = body?.sortField || \'updatedTime\'\nvar sortDir = body?.sortDir || \'desc\'\nvar must = []\nvar mustNot = []\nvar should = []\n\nif (body?.conditions != null) {\n    for (condition in body.conditions) {\n        addCondition(must, mustNot, condition)\n    }\n}\nfor (field in [\'tid\', \'assetType\', \'appId\', \'dbId\', \'orgId\', \'assetStatus\', \'flowStatus\', \'catalogId\', \'sourceTableId\']) {\n    if (!blank(body[field])) {\n        addCondition(must, mustNot, { field: field, value: body[field], type: \'match\' })\n    }\n}\nif (!blank(body?.keyword)) {\n    for (field in [\'appName\', \'dbName\', \'tableName\', \'tableNameCn\', \'catalogName\', \'assetDesc\']) {\n        should.add({ wildcard: { [field]: `*${body.keyword}*` } })\n    }\n}\n\nvar boolQuery = { must: must, must_not: mustNot }\nif (should.size() > 0) {\n    boolQuery.should = should\n    boolQuery.minimum_should_match = 1\n}\nvar sortOne = {}\nsortOne[sortField] = { order: sortDir }\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nvar result = tenantEs.index(configData().es_dataassets).search({\n    from: (pageNum - 1) * pageSize,\n    size: pageSize,\n    query: { bool: boolQuery },\n    sort: [sortOne]\n})\nvar list = []\nfor (hit in (result?.hits?.hits || [])) {\n    if (hit?._source != null) {\n        list.add(hit._source)\n    }\n}\nif (body?.noEnrich != true) {\n    enrich(list)\n}\nvar totalObj = result?.hits?.total\nvar total = totalObj?.value == null ? (totalObj || 0) : totalObj.value\n// 返回当前业务分支的标准结果。\nreturn { pageNum: pageNum, pageSize: pageSize, total: total, list: list }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/3.数据资产治理/04.数据资产管理/4.1 数据资产/01.资产分页查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,'2084109831678504960','/magic-api/api/3.数据资产治理/04.数据资产管理/4.1 数据资产/01.资源目录关系/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('547d0de1429b47ed9d76354a32086fd7',NULL,NULL,'{\n  "properties": {},\n  "id": "547d0de1429b47ed9d76354a32086fd7",\n  "script": null,\n  "groupId": "b19bcf15bd0b40d18f72372faeeb7e6a",\n  "name": "01.查询目录与表关联",\n  "createTime": 1782955343895,\n  "updateTime": 1784823254195,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"catalogId\\":\\"dbafce3deb6041febc7fb3260c1eec73\\"}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "[{\\"catalogId\\":\\"dbafce3deb6041febc7fb3260c1eec73\\",\\"tableId\\":\\"2903feee5161484cac3c8b0b2894bedc\\",\\"relaType\\":\\"业务表\\"}]",\n  "description": "查询目录与表关联（POST /dst/catalog/relations/list）。只读 da_prop_t 的 sourceTableId/targetTableId，并关联 db_table_t、db_datasource_t 返回兼容列表；使用请求参数 catalogId。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：01.查询目录与表关联\n// 路由：POST /list\n// 业务说明：查询目录与表关联（POST /dst/catalog/relations/list）。只读 da_prop_t 的 sourceTableId/targetTableId，并关联 db_table_t、db_datasource_t 返回兼容列表；使用请求参数 catalogId。\nimport cn.hutool.core.util.IdUtil\nimport \'@/common/localCache\' as localCache\n\n/*\n * 查询目录关联的数据表。\n * 关系以 da_prop_t.sourceTableId / targetTableId 为准，再关联 db_table_t、db_datasource_t。\n * 请求示例：{"catalogId":"dbafce3deb6041febc7fb3260c1eec73"}\n */\nvar catalogId = body == null ? null : body.catalogId\nif (catalogId == null || (catalogId + \'\').trim() == \'\') {\n    exit 400, \'catalogId不能为空\'\n}\n\n// 只读取当前目录的两类直接属性，保持旧接口的列表响应兼容。\nvar props = db.table(\'da_prop_t\').where()\n    .eq(\'parent_id\', catalogId)\n    .eq(\'data_type\', \'catalog\')\n    .in(\'prop_name\', [\'sourceTableId\', \'targetTableId\'])\n    .eq(\'is_del\', 0)\n    .select()\nvar list = []\nfor (prop in props) {\n    var tableId = prop.propValue\n    if (tableId == null || (tableId + \'\').trim() == \'\') {\n        continue\n    }\n    var tableInfo = db.table(\'db_table_t\').where().eq(\'tid\', tableId).eq(\'is_del\', 0).selectOne()\n    if (tableInfo == null) {\n        continue\n    }\n    var dbInfo = db.table(\'db_datasource_t\').where().eq(\'tid\', tableInfo.datasourceId).eq(\'is_del\', 0).selectOne()\n    var appId = dbInfo == null ? null : dbInfo.appId\n    list.add({\n        tid: prop.tid,\n        catalogId: catalogId,\n        tableId: tableId,\n        sortNo: prop.propName == \'sourceTableId\' ? 0 : 1,\n        relaType: prop.propName == \'sourceTableId\' ? \'业务表\' : \'贴源表\',\n        tableName: tableInfo.tableName,\n        tableNameCn: tableInfo.tableComment,\n        dbName: dbInfo == null ? null : dbInfo.dbName,\n        dbId: tableInfo.datasourceId,\n        appId: appId,\n        appName: appId == null ? null : localCache(appId, \'app\')\n    })\n}\nreturn list\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/3.数据资产治理/04.数据资产管理/4.1 数据资产/01.资源目录关系/01.查询目录与表关联.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('176b1ee40e0e4f448c54c964b2f885f6',NULL,NULL,'{\n  "properties": {},\n  "id": "176b1ee40e0e4f448c54c964b2f885f6",\n  "script": null,\n  "groupId": "b19bcf15bd0b40d18f72372faeeb7e6a",\n  "name": "02.目录保存并自动创建贴源表",\n  "createTime": 1782955343902,\n  "updateTime": 1784823254297,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/auto-create-table",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"tid\\":\\"dbafce3deb6041febc7fb3260c1eec73\\",\\"resultData\\":{\\"sourceTableId\\":\\"2903feee5161484cac3c8b0b2894bedc\\",\\"targetTableId\\":\\"cefd547f4c42459b84078996abc28dbc\\"}}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "{\\"catalogId\\":\\"dbafce3deb6041febc7fb3260c1eec73\\"}",\n  "description": "目录保存后同步表关系（POST /dst/catalog/relations/auto-create-table）。校验目录和数据表后写 da_prop_t.sourceTableId/targetTableId，不再维护重复关系表；使用请求参数 tid、resultData。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：02.目录保存并自动创建贴源表\n// 路由：POST /auto-create-table\n// 业务说明：目录保存后同步表关系（POST /dst/catalog/relations/auto-create-table）。校验目录和数据表后写 da_prop_t.sourceTableId/targetTableId，不再维护重复关系表；使用请求参数 tid、resultData。\nimport cn.hutool.core.util.IdUtil\nimport log\n\n/*\n * 保存目录时同步来源表和贴源表属性。\n * 目录表关系直接保存在 da_prop_t，供目录详情、列表和后续接入流程统一读取。\n * 请求示例：{"tid":"dbafce3deb6041febc7fb3260c1eec73","resultData":{"sourceTableId":"2903feee5161484cac3c8b0b2894bedc","targetTableId":"cefd547f4c42459b84078996abc28dbc"}}\n */\nvar catalogId = body == null ? null : body.tid\nvar resultData = body == null || body.resultData == null ? {} : body.resultData\nif (catalogId == null || (catalogId + \'\').trim() == \'\') {\n    exit 400, \'tid不能为空\'\n}\nvar catalog = db.table(\'da_asset_t\').where().eq(\'tid\', catalogId).eq(\'asset_type\', \'catalog\').eq(\'is_del\', 0).selectOne()\nif (catalog == null) {\n    exit 404, \'资源目录不存在\'\n}\n\nvar now = new Date()\nvar saveProp = (name, value) => {\n    var old = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', catalogId).eq(\'data_type\', \'catalog\')\n        .eq(\'prop_name\', name).selectOne()\n    if (value == null || (value + \'\').trim() == \'\') {\n        if (old != null && old.isDel == 0) {\n            db.table(\'da_prop_t\').where().eq(\'tid\', old.tid)\n                .update({ is_del: 1, updated_time: now })\n        }\n        return\n    }\n    var table = db.table(\'db_table_t\').where().eq(\'tid\', value).eq(\'is_del\', 0).selectOne()\n    if (table == null) {\n        exit 400, name + \'对应的数据表不存在\'\n    }\n    if (old == null) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({\n            tid: IdUtil.getSnowflakeNextIdStr(),\n            parent_id: catalogId,\n            prop_name: name,\n            prop_value: value,\n            prop_type: \'0\',\n            data_type: \'catalog\',\n            is_del: 0,\n            created_time: now,\n            updated_time: now\n        })\n    } else {\n        db.table(\'da_prop_t\').where().eq(\'tid\', old.tid).update({\n            prop_value: value,\n            prop_type: \'0\',\n            data_type: \'catalog\',\n            is_del: 0,\n            updated_time: now\n        })\n    }\n}\n\n// 两种关系分别落入明确属性，避免一份关系维护两套真值。\nsaveProp(\'sourceTableId\', resultData.sourceTableId)\nsaveProp(\'targetTableId\', resultData.targetTableId)\nlog.info(\'目录表关系属性同步完成, catalogId: {}\', catalogId)\nreturn { catalogId: catalogId }\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/3.数据资产治理/04.数据资产管理/4.1 数据资产/01.资源目录关系/02.目录保存并自动创建贴源表.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b2cf8630daa543c59579648992605a99',NULL,NULL,'{\n  "properties": {},\n  "id": "b2cf8630daa543c59579648992605a99",\n  "script": null,\n  "groupId": "b19bcf15bd0b40d18f72372faeeb7e6a",\n  "name": "03.保存目录与表关联",\n  "createTime": 1782955343911,\n  "updateTime": 1784823254245,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save",\n  "method": "POST",\n  "parameters": [],\n  "options": [],\n  "requestBody": "{\\"catalogId\\":\\"dbafce3deb6041febc7fb3260c1eec73\\",\\"relaTableList\\":[{\\"tableId\\":\\"2903feee5161484cac3c8b0b2894bedc\\",\\"relaType\\":\\"业务表\\"}]}",\n  "headers": [],\n  "paths": [],\n  "responseBody": "\\"dbafce3deb6041febc7fb3260c1eec73\\"",\n  "description": "保存目录与表关联（POST /dst/catalog/relations/save）。将一个业务表和一个贴源表分别保存到 da_prop_t.sourceTableId/targetTableId，保留旧路由兼容；使用请求参数 catalogId、relaTableList。",\n  "requestBodyDefinition": null,\n  "responseBodyDefinition": null\n}\n================================\n// 接口：03.保存目录与表关联\n// 路由：POST /save\n// 业务说明：保存目录与表关联（POST /dst/catalog/relations/save）。将一个业务表和一个贴源表分别保存到 da_prop_t.sourceTableId/targetTableId，保留旧路由兼容；使用请求参数 catalogId、relaTableList。\nimport cn.hutool.core.util.IdUtil\nimport log\nimport tenantRuntime\n\n/*\n * 保存目录与数据表关系。\n * 每个目录最多保存一个来源业务表和一个目标贴源表，分别落在 da_prop_t 的\n * sourceTableId、targetTableId 属性中，不再重复维护关系表。\n * 请求示例：{"catalogId":"dbafce3deb6041febc7fb3260c1eec73","relaTableList":[{"tableId":"2903feee5161484cac3c8b0b2894bedc","relaType":"业务表"}]}\n */\nvar catalogId = body == null ? null : body.catalogId\nvar tenantId = tenantRuntime.id()\nif (catalogId == null || (catalogId + \'\').trim() == \'\') {\n    exit 400, \'catalogId不能为空\'\n}\nvar catalog = db.table(\'da_asset_t\').where().eq(\'tid\', catalogId).eq(\'asset_type\', \'catalog\').eq(\'is_del\', 0).selectOne()\nif (catalog == null) {\n    exit 404, \'资源目录不存在\'\n}\n\nvar sourceTableId = null\nvar targetTableId = null\nvar sourceCount = 0\nvar targetCount = 0\nvar items = body.relaTableList == null ? [] : body.relaTableList\nfor (item in items) {\n    var tableId = item == null ? null : item.tableId\n    if (tableId == null || (tableId + \'\').trim() == \'\') {\n        continue\n    }\n    var type = item.relaType == null ? \'\' : (item.relaType + \'\').trim()\n    if (type == \'贴源表\' || type == \'target\' || type == \'1\') {\n        targetCount = targetCount + 1\n        targetTableId = tableId\n    } else {\n        sourceCount = sourceCount + 1\n        sourceTableId = tableId\n    }\n}\nif (sourceCount > 1 || targetCount > 1) {\n    exit 400, \'每个目录最多关联一个业务表和一个贴源表\'\n}\n\nvar now = new Date()\nvar saveProp = (name, value) => {\n    var old = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', catalogId).eq(\'data_type\', \'catalog\')\n        .eq(\'prop_name\', name).selectOne()\n    if (value == null || (value + \'\').trim() == \'\') {\n        if (old != null && old.isDel == 0) {\n            db.table(\'da_prop_t\').where().eq(\'tid\', old.tid)\n                .update({ is_del: 1, updated_time: now })\n        }\n        return\n    }\n    var table = db.table(\'db_table_t\').where().eq(\'tid\', value).eq(\'is_del\', 0).selectOne()\n    if (table == null) {\n        exit 400, name + \'对应的数据表不存在\'\n    }\n    if (old == null) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({\n            tid: IdUtil.getSnowflakeNextIdStr(),\n            tenant_id: tenantId,\n            parent_id: catalogId,\n            prop_name: name,\n            prop_value: value,\n            prop_type: \'0\',\n            data_type: \'catalog\',\n            is_del: 0,\n            created_time: now,\n            updated_time: now\n        })\n    } else {\n        db.table(\'da_prop_t\').where().eq(\'tid\', old.tid).update({\n            prop_value: value,\n            prop_type: \'0\',\n            data_type: \'catalog\',\n            is_del: 0,\n            updated_time: now\n        })\n    }\n}\n\n// 同一事务内分别保存来源表和目标表属性，删除操作通过 is_del 软删除。\nsaveProp(\'sourceTableId\', sourceTableId)\nsaveProp(\'targetTableId\', targetTableId)\nlog.info(\'目录表关系已保存到 da_prop_t, catalogId: {}\', catalogId)\nreturn catalogId\n',NULL,NULL,0,'2084109831678504960','/magic-api/api/3.数据资产治理/04.数据资产管理/4.1 数据资产/01.资源目录关系/03.保存目录与表关联.ms');
