INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('473f26c73d35445982c07897e97c1319',NULL,NULL,'{\n  "properties": {},\n  "id": "473f26c73d35445982c07897e97c1319",\n  "script": "// 共享函数：01.数据条件查询\\n// 函数路径：/common/table-search\\n// 业务说明：按调用方传入的表与过滤条件组装数据查询，返回匹配业务行；用于多个通用数据读取接口复用。\\n// 函数输入：tableName：目标业务表名；columns：查询字段，以,隔开；conditions：查询条件集合。\\nconst dbKey = dbKey || \\"\\";\\nvar result = db[dbKey].table(tableName);\\nif(columns){\\n    result.column(columns);\\n}\\nif(conditions){\\n    result = result.where();\\n    for(val in conditions){\\n        if(val.condition && val.condition == \'eq\'){// eq --> ==\\n            result.eq(val.field, val.value);\\n        }else if(val.condition == \'ne\'){// ne --> <>\\n            result.ne(val.field, val.value);\\n        }else if(val.condition == \'lt\'){// lt --> <\\n            result.lt(val.field, val.value);\\n        }else if(val.condition == \'gt\'){// gt --> >\\n            result.gt(val.field, val.value);\\n        }else if(val.condition == \'lte\'){// lte --> <=\\n            result.lte(val.field, val.value);\\n        }else if(val.condition == \'gte\'){// gte --> >=\\n            result.gte(val.field, val.value);\\n        }else if(val.condition == \'in\'){// in --> in\\n            result.in(val.field, val.value);\\n        }else if(val.condition == \'notIn\'){// notIn --> not in\\n            result.notIn(val.field, val.value);\\n        }else if(val.condition == \'like\'){// like --> like\\n            result.like(val.field, val.value);\\n        }else if(val.condition == \'notLike\'){// notLike --> not like\\n            result.notLike(val.field, val.value);\\n        }else if(val.condition == \'orderBy\'){// orderBy --> ORDER BY\\n            result.orderBy(val.field, val.value);\\n        }else if(val.condition == \'groupBy\'){// groupBy --> GROUP BY\\n            result.groupBy(val.field);\\n        }\\n    }\\n}\\nreturn result;\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "01.数据条件查询",\n  "createTime": 1782660730357,\n  "updateTime": 1762960094412,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/table-search",\n  "description": "按调用方传入的表与过滤条件组装数据查询，返回匹配业务行；用于多个通用数据读取接口复用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "tableName",\n      "value": null,\n      "description": "目标业务表名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "columns",\n      "value": null,\n      "description": "查询字段，以,隔开",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "conditions",\n      "value": null,\n      "description": "查询条件集合",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/01.数据条件查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0629b541c30b4bf6823fc29c5861f335',NULL,NULL,'{\n  "properties": {},\n  "id": "0629b541c30b4bf6823fc29c5861f335",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "02.保存数据对象",\n  "createTime": 1782660730380,\n  "updateTime": 1786498740258,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/save-data",\n  "description": "按传入的数据对象和目标表执行保存处理，供通用数据写接口复用；调用方负责限定可写表和字段。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "tableName",\n      "value": null,\n      "description": "目标业务表名",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "data",\n      "value": null,\n      "description": "需要保存的数据",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：02.保存数据对象\n// 函数路径：/common/save-data\n// 业务说明：按传入的数据对象和目标表执行保存处理，供通用数据写接口复用；调用方负责限定可写表和字段。\n// 函数输入：tableName：目标业务表名；data：需要保存的数据。\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.core.date.DateUtil\n\nString userId = StpUtil.getLoginId()\n// 默认字段赋值\ndata = {\n    ...data,\n    updatedTime: DateUtil.now(),\n    updatedBy: userId,\n}\nif(data.tid){\n    db.table(tableName).primary("tid").update(data)\n}else{\n    data = {\n        ...data,\n        createdTime: DateUtil.now(),\n        createdBy: userId,\n        isDel: 0\n    }\n    var tid = IdUtil.getSnowflakeNextIdStr()\n    db.table(tableName).primary("tid", tid).insert(data)\n    data.tid = tid\n}\nreturn data\n',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/02.保存数据对象.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('222af8050ddb4935be8d47a0669bce62',NULL,NULL,'{\n  "properties": {},\n  "id": "222af8050ddb4935be8d47a0669bce62",\n  "script": "// 共享函数：03.模型条件查询\\n// 函数路径：/common/model-search\\n// 业务说明：根据模型字段和筛选条件构造查询结果，供模型驱动的数据列表接口复用。\\n// 函数输入：modelCode：数据模型名；columns：查询字段，以,隔开；conditions：查询条件集合。\\nconst dbKey = dbKey || \\"\\";\\nvar model = db[dbKey].selectOne(\\"\\"\\"\\nselect model_script\\nfrom dataassets_baseline.db_model_t\\nwhere model_code=#{modelCode}\\n\\"\\"\\");\\nreturn model.modelScript + \\"\\"\\"\\n<!-- 所有有效的查询条件 -->\\n  <if test=\\"conditions != null and conditions.size() > 0\\">\\n    <trim prefix=\\"AND (\\" suffix=\\")\\" prefixOverrides=\\"AND\\" suffixOverrides=\\"AND\\">\\n      <foreach collection=\\"conditions\\" item=\\"item\\">\\n        <if test=\\"item.condition == \'eq\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} = #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'ne\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} &lt;&gt; #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'lt\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} &lt; #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'gt\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} &gt; #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'lte\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} &lt;= #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'gte\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} &gt;= #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'in\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} IN\\n          <foreach collection=\\"item.value\\" item=\\"val\\" open=\\"(\\" separator=\\",\\" close=\\")\\">\\n            #{val}\\n          </foreach> AND\\n        </if>\\n        <if test=\\"item.condition == \'notIn\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} NOT IN\\n          <foreach collection=\\"item.value\\" item=\\"val\\" open=\\"(\\" separator=\\",\\" close=\\")\\">\\n            #{val}\\n          </foreach> AND\\n        </if>\\n        <if test=\\"item.condition == \'like\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} LIKE #{item.value} AND\\n        </if>\\n        <if test=\\"item.condition == \'notLike\'\\">\\n          ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} NOT LIKE #{item.value} AND\\n        </if>\\n      </foreach>\\n    </trim>\\n  </if>\\n\\n<!-- 分组查询 -->\\n<if test=\\"conditions != null and conditions.size() > 0 \\n    and conditions.some(item => item.condition == \'groupBy\')\\">\\n  GROUP BY \\n  <trim suffixOverrides=\\",\\">\\n    <foreach collection=\\"conditions\\" item=\\"item\\" separator=\\",\\">\\n      <if test=\\"item.condition == \'groupBy\'\\">\\n        ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()}\\n      </if>\\n    </foreach>\\n  </trim>\\n</if>\\n\\n<!-- 排序查询 -->\\n<if test=\\"conditions != null and conditions.size() > 0 \\n    and conditions.some(item => item.condition == \'orderBy\')\\">\\n  ORDER BY \\n  <trim suffixOverrides=\\",\\">\\n    <foreach collection=\\"conditions\\" item=\\"item\\" separator=\\",\\">\\n      <if test=\\"item.condition == \'orderBy\'\\">\\n        ${item.field.replaceAll(\'([A-Z])\', \'_$1\').toLowerCase()} ${item.value}\\n      </if>\\n    </foreach>\\n  </trim>\\n</if>\\n\\"\\"\\"\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "03.模型条件查询",\n  "createTime": 1782660730368,\n  "updateTime": 1762877706217,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/model-search",\n  "description": "根据模型字段和筛选条件构造查询结果，供模型驱动的数据列表接口复用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "modelCode",\n      "value": null,\n      "description": "数据模型名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "columns",\n      "value": null,\n      "description": "查询字段，以,隔开",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "conditions",\n      "value": null,\n      "description": "查询条件集合",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/03.模型条件查询.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('59fc7ba68a7e4231a211e23423261c56',NULL,NULL,'{\n  "properties": {},\n  "id": "59fc7ba68a7e4231a211e23423261c56",\n  "script": "// 共享函数：04.按配置键读取配置值\\n// 函数路径：/common/getBykey\\n// 业务说明：按 configureKey 从 sys_configure 查询配置值，使用 Magic 缓存减少重复查询；配置不存在时返回空字符串。\\n// 函数输入：configureKey：sys_configure 中的配置键。\\nvar configure = db.cache(`configure:${configureKey}`).selectOne(\\"\\"\\"\\n     select configure_value from sys_configure where configure_key = #{configureKey}\\n\\"\\"\\")\\nreturn configure == null ? \\"\\" : configure.get(\\"configureValue\\")\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "04.按配置键读取配置值",\n  "createTime": 1782660730390,\n  "updateTime": 1763253090092,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getBykey",\n  "description": "按 configureKey 从 sys_configure 查询配置值，使用 Magic 缓存减少重复查询；配置不存在时返回空字符串。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "configureKey",\n      "value": null,\n      "description": "sys_configure 中的配置键",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/04.按配置键读取配置值.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c1a7019f5e4a4a92a34543c1f5290015',NULL,NULL,'{\n  "properties": {},\n  "id": "c1a7019f5e4a4a92a34543c1f5290015",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "05.保存网关接口资产",\n  "createTime": 1784450000000,\n  "updateTime": 1787153758049,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/saveGatewayAsset",\n  "description": "保存网关接口对应的资产资料，并维护数据库与检索索引中的可查询投影。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "apiId",\n      "value": null,\n      "description": "网关 API ID",\n      "required": true,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "data",\n      "value": null,\n      "description": "驼峰格式的 API 详情",\n      "required": true,\n      "dataType": "Object",\n      "type": "java.lang.Object",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "catalogId",\n      "value": null,\n      "description": "服务目录 ID",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：05.保存网关接口资产\n// 函数路径：/common/saveGatewayAsset\n// 业务说明：保存网关接口对应的资产资料，并维护数据库与检索索引中的可查询投影。\n// 函数输入：apiId：网关 API ID；data：驼峰格式的 API 详情；catalogId：服务目录 ID。\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport java.util.List\nimport java.util.Map\n\nif (apiId == null || (apiId + \'\').trim() == \'\') {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'apiId不能为空\'\n}\nif (data == null) {\n    // 参数或业务状态不满足要求时立即终止请求。\n    exit 400, \'API资产数据不能为空\'\n}\n\nvar now = new Date()\nvar apiKey = apiId + \'\'\ndata.tid = apiKey\ndata.assetType = \'api\'\ndata.createdTime = data.createdTime || date_format(now)\ndata.updatedTime = date_format(now)\n\n// 从 MySQL 业务表读取当前有效数据。\nif (catalogId != null && (catalogId + \'\').trim() != \'\' && db.table(\'da_asset_api_rela\').where()\n    .eq(\'api_id\', apiKey).eq(\'catalog_id\', catalogId).eq(\'is_del\', 0).count() == 0) {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'da_asset_api_rela\').primary(\'tid\').insert({\n        tid: IdUtil.getSnowflakeNextIdStr(),\n        api_id: apiKey,\n        catalog_id: catalogId,\n        is_del: 0,\n        created_time: now,\n        updated_time: now\n    })\n}\n\n// 从 MySQL 业务表读取当前有效数据。\nvar asset = db.table(\'da_asset_t\').where().eq(\'tid\', apiKey).selectOne()\nif (asset == null) {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'da_asset_t\').primary(\'tid\').insert({\n        tid: apiKey,\n        asset_type: \'api\',\n        asset_status: 2,\n        flow_status: 2,\n        is_del: 0,\n        reg_time: now,\n        created_time: now,\n        updated_time: now\n    })\n} else {\n    // 将校验后的业务数据写入 MySQL 主表。\n    db.table(\'da_asset_t\').where().eq(\'tid\', apiKey).update({\n        asset_type: \'api\',\n        asset_status: 2,\n        flow_status: 2,\n        is_del: 0,\n        updated_time: now\n    })\n}\n\nfor (entry in data.entrySet()) {\n    var propName = keyName + \'\'\n    var value = value[keyName]\n    var propValue = value instanceof Map || value instanceof List\n        ? jsons.toJSONStr(value)\n        : value == null ? null : value + \'\'\n    // 从 MySQL 业务表读取当前有效数据。\n    var prop = db.table(\'da_prop_t\').where()\n        .eq(\'parent_id\', apiKey).eq(\'prop_name\', propName).selectOne()\n    if (prop == null) {\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table(\'da_prop_t\').primary(\'tid\').insert({\n            tid: IdUtil.getSnowflakeNextIdStr(),\n            parent_id: apiKey,\n            prop_name: propName,\n            prop_value: propValue,\n            prop_type: \'0\',\n            data_type: \'api\',\n            is_del: 0,\n            created_time: now,\n            updated_time: now\n        })\n    } else {\n        // 将校验后的业务数据写入 MySQL 主表。\n        db.table(\'da_prop_t\').where().eq(\'tid\', prop.tid).update({\n            prop_value: propValue,\n            data_type: \'api\',\n            is_del: 0,\n            updated_time: now\n        })\n    }\n}\n\n// 执行 Elasticsearch 查询或索引同步，保持检索结果与主数据一致。\nesCommonService.saveOrUpdate(\'dataassets\', apiKey, jsons.toJSONStr(data), false)\n// 返回当前业务分支的标准结果。\nreturn data\n',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/05.保存网关接口资产.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c2a7019f5e4a4a92a34543c1f5290016',NULL,NULL,'{\n  "properties": {},\n  "id": "c2a7019f5e4a4a92a34543c1f5290016",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "06.查询网关接口详情",\n  "createTime": 1784450000000,\n  "updateTime": 1784450000000,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/gatewayApiDetail",\n  "description": "按网关接口标识读取对外接口详情，组装协议和展示字段供资产页面使用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "apiId",\n      "value": null,\n      "description": "网关 API ID",\n      "required": true,\n      "dataType": "String",\n      "type": "java.lang.String"\n    }\n  ],\n  "requestBody": "{\\n}"\n}\n================================\n// 共享函数：06.查询网关接口详情\n// 函数路径：/common/gatewayApiDetail\n// 业务说明：按网关接口标识读取对外接口详情，组装协议和展示字段供资产页面使用。\n// 函数输入：apiId：网关 API ID。\nimport cn.hutool.core.util.StrUtil\nimport com.linewell.dataelement.utils.GatewayUtils as gatewayUtils\nimport http\nimport jsons\nimport java.util.List\nimport java.util.Map\nimport org.springframework.core.env.Environment as environment\nimport log\n\nvar toCamel\ntoCamel = value => {\n    if (value instanceof Map) {\n        var result = {}\n        for (keyName in value.keySet()) {\n            result[StrUtil.toCamelCase(keyName + \'\')] = toCamel(value[keyName])\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    if (value instanceof List) {\n        var result = []\n        for (item in value) {\n            result.add(toCamel(item))\n        }\n        // 返回当前业务分支的标准结果。\n        return result\n    }\n    // 返回当前业务分支的标准结果。\n    return value\n}\n\nif (apiId == null || (apiId + \'\').trim() == \'\') {\n    // 返回当前业务分支的标准结果。\n    return null\n}\n// 调用外部网关并统一处理返回结果与异常。\nvar detail = toCamel(gatewayUtils.callGatewayApi(\'V2DescribeApi\', {api_id: apiId}))\nif (detail.errorCode == \'data_not_found\') {\n    // 返回当前业务分支的标准结果。\n    return null\n}\ndetail.serviceCreateType = \'api\'\nif (detail.serviceBuildId != null && detail.serviceBuildId != \'\') {\n    detail.serviceCreateType = \'apiBuild\'\n    try {\n        var response = http.connect(environment.getProperty(\'gateway.buildapi.url\') + \'/openapi/api/getServiceById\')\n            .contentType(\'application/json\')\n            .body(jsons.toJSONStr({id: detail.serviceBuildId}))\n            .post()\n        detail.buildApiInfo = toCamel(response.getBody()?.data)\n    } catch (e) {\n        log.warn(\'获取服务构建详情失败, serviceBuildId={}, message={}\', detail.serviceBuildId, e.message)\n    }\n}\ndetail.serviceName = detail.name || \'\'\n// 返回当前业务分支的标准结果。\nreturn detail\n',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/06.查询网关接口详情.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_registered_table_catalog_projection_01",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "07.维护登记表目录投影",\n  "createTime": 1787155322067,\n  "updateTime": 1787617853769,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/registeredTableCatalogProjection",\n  "description": "action=ensure 时维护指定登记表的目录投影；action=syncCompleted 时补偿当前租户已完成登记的表。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "action",\n      "value": null,\n      "description": "要执行的业务操作",\n      "required": true,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "tableId",\n      "value": null,\n      "description": "数据表 ID；syncCompleted 时为空",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "synchronizeIndex",\n      "value": null,\n      "description": "ensure 时是否同步 ES 索引",\n      "required": false,\n      "dataType": "Boolean",\n      "type": "java.lang.Boolean",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "maxRows",\n      "value": null,\n      "description": "syncCompleted 最大处理数，最大 10000",\n      "required": false,\n      "dataType": "Integer",\n      "type": "java.lang.Integer",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：07.维护登记表目录投影\n// 函数路径：/common/registeredTableCatalogProjection\n// 业务说明：action=ensure 时维护指定登记表的目录投影；action=syncCompleted 时补偿当前租户已完成登记的表。\n// 函数输入：action：要执行的业务操作；tableId：数据表 ID；syncCompleted 时为空；synchronizeIndex：ensure 时是否同步 ES 索引；maxRows：syncCompleted 最大处理数，最大 10000。\nimport cn.hutool.core.util.IdUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport jsons\nimport java.util.List\nimport java.util.Map\nimport log\n\n/*\n * 已登记数据表 -> 数据目录投影。\n *\n * 这是一份业务函数：目录的准入、字段取值、目录 ID 选择、属性与字段项同步、退役规则\n * 都可在 Magic 编辑器实时调整。db.table 使用当前请求绑定的租户元数据数据源，\n * 因而不依赖登记源（MySQL/达梦/Oracle 等）的 SQL 方言。\n */\nvar textOf = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || textOf(value).trim() == \'\'\nvar nowTime = () => new Date()\nvar newId = () => IdUtil.getSnowflakeNextIdStr()\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar firstText = values => {\n    for (value in values) {\n        if (!blank(value)) {\n            return textOf(value).trim()\n        }\n    }\n    return \'\'\n}\nvar boolValue = value => value == true || textOf(value).toLowerCase() == \'true\' || textOf(value) == \'1\'\nvar catalogEligible = businessType => {\n    var normalized = textOf(businessType).trim().toLowerCase()\n    return normalized == \'业务表\' || normalized == \'字典表\' || normalized == \'日志表\'\n        || normalized == \'business\' || normalized == \'dictionary\' || normalized == \'log\'\n}\nvar catalogNameOf = table => firstText([\n    rowValue(table, [\'catalogName\', \'catalog_name\']),\n    rowValue(table, [\'tableNameCn\', \'table_name_cn\']),\n    rowValue(table, [\'tableComment\', \'table_comment\']),\n    rowValue(table, [\'tableName\', \'table_name\'])\n])\nvar catalogNameEnOf = table => firstText([\n    rowValue(table, [\'catalogNameEn\', \'catalog_name_en\']),\n    rowValue(table, [\'tableName\', \'table_name\'])\n])\nvar assetDescOf = table => firstText([\n    rowValue(table, [\'assetDesc\', \'asset_desc\']),\n    rowValue(table, [\'tableComment\', \'table_comment\']),\n    catalogNameOf(table)\n])\nvar catalogPropRows = (catalogId, propName) => db.table(\'da_prop_t\').where()\n    .eq(\'parent_id\', catalogId).eq(\'data_type\', \'catalog\').eq(\'prop_name\', propName).eq(\'is_del\', 0).select()\nvar catalogProp = (catalogId, propName) => {\n    var rows = catalogPropRows(catalogId, propName)\n    return rows == null || rows.size() == 0 ? null : rows.get(0)\n}\nvar upsertCatalogProp = (catalogId, name, value, now) => {\n    var rows = catalogPropRows(catalogId, name)\n    if (rows == null || rows.size() == 0) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({\n            tid: newId(), parent_id: catalogId, prop_name: name, prop_value: value,\n            prop_type: \'0\', data_type: \'catalog\', is_del: 0, created_time: now, updated_time: now\n        })\n        return\n    }\n    var primary = rows.get(0)\n    db.table(\'da_prop_t\').primary(\'tid\').update({\n        tid: rowValue(primary, [\'tid\']), prop_value: value, prop_type: \'0\',\n        data_type: \'catalog\', is_del: 0, updated_time: now\n    }, true)\n    for (duplicate in rows) {\n        if (textOf(rowValue(duplicate, [\'tid\'])) != textOf(rowValue(primary, [\'tid\']))) {\n            db.table(\'da_prop_t\').primary(\'tid\').update({\n                tid: rowValue(duplicate, [\'tid\']), is_del: 1, updated_time: now\n            }, true)\n        }\n    }\n}\nvar catalogCanRepresentTable = (catalogId, sourceTableId) => {\n    if (blank(catalogId)) {\n        return false\n    }\n    var catalog = db.table(\'da_catalog_t\').where().eq(\'tid\', catalogId).eq(\'is_del\', 0).selectOne()\n    if (catalog == null) {\n        return false\n    }\n    var physicalSource = rowValue(catalog, [\'sourceTableId\', \'source_table_id\'])\n    if (!blank(physicalSource) && textOf(physicalSource) != textOf(sourceTableId)) {\n        return false\n    }\n    var prop = catalogProp(catalogId, \'sourceTableId\')\n    var propertySource = rowValue(prop, [\'propValue\', \'prop_value\'])\n    return blank(propertySource) || textOf(propertySource) == textOf(sourceTableId)\n}\nvar resolveCatalogId = table => {\n    var tableIdValue = textOf(rowValue(table, [\'tid\']))\n    var requested = rowValue(table, [\'sourceCatalogId\', \'source_catalog_id\'])\n    if (catalogCanRepresentTable(requested, tableIdValue)) {\n        return textOf(requested)\n    }\n    var physical = db.table(\'da_catalog_t\').where()\n        .eq(\'source_table_id\', tableIdValue).eq(\'is_del\', 0).select()\n    if (physical != null && physical.size() > 0) {\n        return textOf(rowValue(physical.get(0), [\'tid\']))\n    }\n    var props = db.table(\'da_prop_t\').where()\n        .eq(\'data_type\', \'catalog\').eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', tableIdValue).eq(\'is_del\', 0).select()\n    if (props != null && props.size() > 0) {\n        return textOf(rowValue(props.get(0), [\'parentId\', \'parent_id\']))\n    }\n    return newId()\n}\nvar catalogValues = (catalogId, table, now) => ({\n    tid: catalogId,\n    is_del: 0,\n    asset_status: 2,\n    flow_status: 2,\n    catalog_name: catalogNameOf(table),\n    catalog_name_en: catalogNameEnOf(table),\n    asset_desc: assetDescOf(table),\n    app_id: rowValue(table, [\'appId\', \'app_id\']),\n    app_name: rowValue(table, [\'appName\', \'app_name\']),\n    db_id: rowValue(table, [\'datasourceId\', \'datasource_id\']),\n    db_name: rowValue(table, [\'dbName\', \'db_name\']),\n    source_table_id: rowValue(table, [\'tid\']),\n    source_table_name: rowValue(table, [\'tableName\', \'table_name\']),\n    org_id: rowValue(table, [\'orgId\', \'org_id\']),\n    manage_unit: firstText([rowValue(table, [\'manageUnit\', \'manage_unit\']), rowValue(table, [\'orgId\', \'org_id\'])]),\n    business_type: rowValue(table, [\'businessType\', \'business_type\']),\n    data_source_type: firstText([rowValue(table, [\'dataSourceType\', \'data_source_type\']), \'database\']),\n    timestamp_field: rowValue(table, [\'timestampField\', \'timestamp_field\']),\n    dictionary_table_flag: rowValue(table, [\'dictionaryTableFlag\', \'dictionary_table_flag\']),\n    field_governance_config: rowValue(table, [\'fieldGovernanceConfig\', \'field_governance_config\']),\n    updated_time: now\n})\nvar upsertCatalog = (catalogId, table, now) => {\n    var values = catalogValues(catalogId, table, now)\n    var current = db.table(\'da_catalog_t\').where().eq(\'tid\', catalogId).selectOne()\n    if (current == null) {\n        values.created_time = now\n        values.reg_time = now\n        db.table(\'da_catalog_t\').primary(\'tid\').insert(values)\n    } else {\n        db.table(\'da_catalog_t\').primary(\'tid\').update(values, true)\n    }\n}\nvar syncCatalogProperties = (catalogId, table, now) => {\n    var properties = {\n        catalogName: catalogNameOf(table),\n        catalogNameEn: catalogNameEnOf(table),\n        assetDesc: assetDescOf(table),\n        appId: rowValue(table, [\'appId\', \'app_id\']),\n        appName: rowValue(table, [\'appName\', \'app_name\']),\n        dbId: rowValue(table, [\'datasourceId\', \'datasource_id\']),\n        dbName: rowValue(table, [\'dbName\', \'db_name\']),\n        sourceTableId: rowValue(table, [\'tid\']),\n        sourceTableName: rowValue(table, [\'tableName\', \'table_name\']),\n        orgId: rowValue(table, [\'orgId\', \'org_id\']),\n        manageUnit: firstText([rowValue(table, [\'manageUnit\', \'manage_unit\']), rowValue(table, [\'orgId\', \'org_id\'])]),\n        businessType: rowValue(table, [\'businessType\', \'business_type\']),\n        dataSourceType: firstText([rowValue(table, [\'dataSourceType\', \'data_source_type\']), \'database\']),\n        timestampField: rowValue(table, [\'timestampField\', \'timestamp_field\']),\n        dictionaryTableFlag: rowValue(table, [\'dictionaryTableFlag\', \'dictionary_table_flag\']),\n        fieldGovernanceConfig: rowValue(table, [\'fieldGovernanceConfig\', \'field_governance_config\'])\n    }\n    for (propertyName in properties.keySet()) {\n        upsertCatalogProp(catalogId, propertyName + \'\', properties[propertyName], now)\n    }\n}\nvar itemValues = (itemId, catalogId, source, now) => ({\n    tid: itemId,\n    catalog_id: catalogId,\n    is_del: 0,\n    col_name: firstText([rowValue(source, [\'catalogItemName\', \'catalog_item_name\']), rowValue(source, [\'columnComment\', \'column_comment\']), rowValue(source, [\'columnName\', \'column_name\'])]),\n    col_en: firstText([rowValue(source, [\'catalogItemEn\', \'catalog_item_en\']), rowValue(source, [\'columnName\', \'column_name\'])]),\n    col_type: firstText([rowValue(source, [\'catalogItemType\', \'catalog_item_type\']), rowValue(source, [\'columnType\', \'column_type\']), rowValue(source, [\'dataType\', \'data_type\'])]),\n    col_comment: rowValue(source, [\'columnComment\', \'column_comment\']),\n    col_length: rowValue(source, [\'length\']),\n    is_pk: rowValue(source, [\'primaryKey\', \'primary_key\']),\n    is_nullable: rowValue(source, [\'nullable\']),\n    sort_no: rowValue(source, [\'ordinalPosition\', \'ordinal_position\']),\n    data_standard_id: rowValue(source, [\'dataStandardId\', \'data_standard_id\']),\n    quality_rule: rowValue(source, [\'qualityRule\', \'quality_rule\']),\n    enable_code_table: rowValue(source, [\'enableCodeTable\', \'enable_code_table\']),\n    code_table_id: rowValue(source, [\'codeTableId\', \'code_table_id\']),\n    source_table_column_id: rowValue(source, [\'tid\']),\n    updated_time: now\n})\nvar syncCatalogItems = (catalogId, tableIdValue, now) => {\n    var existing = db.table(\'da_catalog_item_t\').where().eq(\'catalog_id\', catalogId).eq(\'is_del\', 0).select()\n    var existingByColumn = {}\n    for (item in (existing == null ? [] : existing)) {\n        var sourceColumnId = rowValue(item, [\'sourceTableColumnId\', \'source_table_column_id\'])\n        if (!blank(sourceColumnId)) {\n            existingByColumn[textOf(sourceColumnId)] = item\n        }\n    }\n    var retained = {}\n    var columns = db.table(\'db_table_column_t\').where().eq(\'table_id\', tableIdValue).eq(\'is_del\', 0)\n        .orderBy(\'ordinal_position\').select()\n    for (column in (columns == null ? [] : columns)) {\n        var columnId = textOf(rowValue(column, [\'tid\']))\n        retained[columnId] = true\n        var item = existingByColumn[columnId]\n        var values = itemValues(item == null ? newId() : rowValue(item, [\'tid\']), catalogId, column, now)\n        if (item == null) {\n            values.created_time = now\n            db.table(\'da_catalog_item_t\').primary(\'tid\').insert(values)\n        } else {\n            db.table(\'da_catalog_item_t\').primary(\'tid\').update(values, true)\n        }\n    }\n    for (columnId in existingByColumn.keySet()) {\n        var existingItem = existingByColumn[columnId]\n        if (retained[columnId] == null) {\n            db.table(\'da_catalog_item_t\').primary(\'tid\').update({\n                tid: rowValue(existingItem, [\'tid\']), is_del: 1, updated_time: now\n            }, true)\n        }\n    }\n}\nvar updateTableLink = (catalogId, table, now) => db.table(\'db_table_t\').primary(\'tid\').update({\n    tid: rowValue(table, [\'tid\']),\n    source_catalog_id: catalogId,\n    catalog_name: catalogNameOf(table),\n    catalog_name_en: catalogNameEnOf(table),\n    source_table_id: rowValue(table, [\'tid\']),\n    source_table_name: rowValue(table, [\'tableName\', \'table_name\']),\n    updated_time: now\n}, true)\nvar retireCatalogs = (tableIdValue, now) => {\n    var ids = {}\n    var physical = db.table(\'da_catalog_t\').where().eq(\'source_table_id\', tableIdValue).eq(\'is_del\', 0).select()\n    for (catalog in (physical == null ? [] : physical)) {\n        ids[textOf(rowValue(catalog, [\'tid\']))] = true\n    }\n    var props = db.table(\'da_prop_t\').where().eq(\'data_type\', \'catalog\').eq(\'prop_name\', \'sourceTableId\')\n        .eq(\'prop_value\', tableIdValue).eq(\'is_del\', 0).select()\n    for (prop in (props == null ? [] : props)) {\n        ids[textOf(rowValue(prop, [\'parentId\', \'parent_id\']))] = true\n    }\n    var retired = 0\n    for (catalogIdValue in ids.keySet()) {\n        var catalogId = catalogIdValue + \'\'\n        db.table(\'da_catalog_t\').primary(\'tid\').update({tid: catalogId, is_del: 1, updated_time: now}, true)\n        var catalogProps = db.table(\'da_prop_t\').where().eq(\'parent_id\', catalogId).eq(\'data_type\', \'catalog\').eq(\'is_del\', 0).select()\n        for (prop in (catalogProps == null ? [] : catalogProps)) {\n            db.table(\'da_prop_t\').primary(\'tid\').update({tid: rowValue(prop, [\'tid\']), is_del: 1, updated_time: now}, true)\n        }\n        var catalogItems = db.table(\'da_catalog_item_t\').where().eq(\'catalog_id\', catalogId).eq(\'is_del\', 0).select()\n        for (item in (catalogItems == null ? [] : catalogItems)) {\n            db.table(\'da_catalog_item_t\').primary(\'tid\').update({tid: rowValue(item, [\'tid\']), is_del: 1, updated_time: now}, true)\n        }\n        retired = retired + 1\n    }\n    db.table(\'db_table_t\').primary(\'tid\').update({tid: tableIdValue, source_catalog_id: null, updated_time: now}, true)\n    return retired\n}\nvar syncIndex = (catalogId, table) => {\n    var document = {\n        tid: catalogId, id: catalogId, assetType: \'catalog\',\n        catalogName: catalogNameOf(table), catalogNameEn: catalogNameEnOf(table),\n        sourceTableId: rowValue(table, [\'tid\']), sourceTableName: rowValue(table, [\'tableName\', \'table_name\']),\n        dbId: rowValue(table, [\'datasourceId\', \'datasource_id\']), dbName: rowValue(table, [\'dbName\', \'db_name\']),\n        appId: rowValue(table, [\'appId\', \'app_id\']), appName: rowValue(table, [\'appName\', \'app_name\']),\n        orgId: rowValue(table, [\'orgId\', \'org_id\']),\n        dataSourceType: firstText([rowValue(table, [\'dataSourceType\', \'data_source_type\']), \'database\']),\n        assetStatus: 2, flowStatus: 2\n    }\n    try {\n        esCommonService.saveOrUpdate(\'dataassets\', catalogId, jsons.toJSONStr(document), false)\n        return true\n    } catch (e) {\n        log.warn(\'数据目录索引同步失败，但关系投影已保留: catalogId={}, message={}\', catalogId, e.message)\n        return false\n    }\n}\nvar ensure = (requestedTableId, withIndex) => {\n    if (blank(requestedTableId)) {\n        exit 400, \'tableId不能为空\'\n    }\n    var table = db.table(\'db_table_t\').where().eq(\'tid\', textOf(requestedTableId).trim()).eq(\'is_del\', 0)\n        .eq(\'asset_status\', 2).selectOne()\n    if (table == null) {\n        exit 404, \'数据表不存在或尚未完成登记\'\n    }\n    var tableIdValue = textOf(rowValue(table, [\'tid\']))\n    var now = nowTime()\n    if (!catalogEligible(rowValue(table, [\'businessType\', \'business_type\']))) {\n        return {tableId: tableIdValue, retired: retireCatalogs(tableIdValue, now), eligible: false, indexed: false}\n    }\n    var datasourceId = rowValue(table, [\'datasourceId\', \'datasource_id\'])\n    var datasource = blank(datasourceId) ? null : db.table(\'db_datasource_t\').where().eq(\'tid\', datasourceId).eq(\'is_del\', 0).selectOne()\n    if (datasource != null) {\n        table.dbName = rowValue(datasource, [\'dbName\', \'db_name\'])\n        table.appId = rowValue(datasource, [\'appId\', \'app_id\'])\n        var applicationId = rowValue(datasource, [\'appId\', \'app_id\'])\n        if (!blank(applicationId)) {\n            var application = db.table(\'sym_application_t\').where().eq(\'tid\', applicationId).eq(\'is_del\', 0).selectOne()\n            if (application != null) {\n                table.appName = rowValue(application, [\'appName\', \'app_name\'])\n            }\n        }\n    }\n    var catalogId = resolveCatalogId(table)\n    upsertCatalog(catalogId, table, now)\n    syncCatalogProperties(catalogId, table, now)\n    syncCatalogItems(catalogId, tableIdValue, now)\n    updateTableLink(catalogId, table, now)\n    return {tableId: tableIdValue, catalogId: catalogId, catalogName: catalogNameOf(table), eligible: true, indexed: boolValue(withIndex) ? syncIndex(catalogId, table) : false}\n}\nvar syncCompleted = maximum => {\n    var requested = maximum == null ? 10000 : maximum::int\n    var limit = requested <= 0 ? 10000 : (requested > 10000 ? 10000 : requested)\n    var completed = db.table(\'db_table_t\').where().eq(\'is_del\', 0).eq(\'asset_status\', 2).orderByDesc(\'updated_time\').select()\n    var targets = []\n    for (table in (completed == null ? [] : completed)) {\n        if (catalogEligible(rowValue(table, [\'businessType\', \'business_type\']))) {\n            targets.add(textOf(rowValue(table, [\'tid\'])))\n            if (targets.size() >= limit) {\n                break\n            }\n        }\n    }\n    var failures = []\n    var synced = 0\n    for (targetId in targets) {\n        try {\n            db.transaction(() => ensure(targetId, false))\n            synced = synced + 1\n        } catch (e) {\n            failures.add({tableId: targetId, message: e.message == null ? (e + \'\') : e.message + \'\'})\n        }\n    }\n    return {total: targets.size(), synced: synced, failed: failures.size(), failures: failures}\n}\n\nif (action == \'ensure\') {\n    return db.transaction(() => ensure(tableId, synchronizeIndex))\n}\nif (action == \'syncCompleted\') {\n    return syncCompleted(maxRows)\n}\nexit 400, \'action仅支持 ensure 或 syncCompleted\'\n',NULL,NULL,0,NULL,'/magic-api/function/01.通用函数/07.维护登记表目录投影.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'{\n  "properties": {},\n  "id": "datapd_datasource_connection_config_01",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "08.读取或保存数据源连接配置",\n  "createTime": 1787155921712,\n  "updateTime": 1787587507117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/datasourceConnectionConfig",\n  "description": "从数据源主表及 pool_cfg 读取连接扩展属性，或按 action 保存允许配置；不使用旧动态属性表。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "action",\n      "value": null,\n      "description": "要执行的业务操作",\n      "required": true,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "datasourceId",\n      "value": null,\n      "description": "数据源标识",\n      "required": true,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "values",\n      "value": null,\n      "description": "save 时的连接参数对象",\n      "required": false,\n      "dataType": "Object",\n      "type": "java.util.Map",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "clearAll",\n      "value": null,\n      "description": "save 时是否清空全部连接参数",\n      "required": false,\n      "dataType": "Boolean",\n      "type": "java.lang.Boolean",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：08.读取或保存数据源连接配置\n// 函数路径：/common/datasourceConnectionConfig\n// 业务说明：从数据源主表及 pool_cfg 读取连接扩展属性，或按 action 保存允许配置；不使用旧动态属性表。\n// 函数输入：action：要执行的业务操作；datasourceId：数据源标识；values：save 时的连接参数对象；clearAll：save 时是否清空全部连接参数。\nimport cn.hutool.json.JSONUtil as jsons\nimport tenantRuntime\nimport java.util.Map\n\n/*\n * 数据源连接配置统一入口。\n *\n * 连接主字段保存在 db_datasource_t，完整的扩展配置保存在同一记录的 pool_cfg JSON 对象。\n * 本函数不读取、不写入 da_prop_t；保留 read/json/save 调用约定以兼容现有 Magic 接口。\n */\nvar textOf = value => value == null ? \'\' : value + \'\'\nvar blank = value => value == null || textOf(value).trim() == \'\'\nvar tenantId = textOf(tenantRuntime.id()).trim()\nif (blank(tenantId)) {\n    exit 401, \'无法识别当前租户，请重新登录\'\n}\nvar rowValue = (row, keys) => {\n    if (row == null) {\n        return null\n    }\n    for (key in keys) {\n        var value = row instanceof Map ? row.get(key) : row[key]\n        if (value != null) {\n            return value\n        }\n    }\n    return null\n}\nvar mainOf = datasourceId => {\n    if (blank(datasourceId)) {\n        return null\n    }\n    return db.table(\'db_datasource_t\').where()\n        .eq(\'tid\', textOf(datasourceId))\n        .eq(\'tenant_id\', tenantId)\n        .eq(\'is_del\', 0)\n        .selectOne()\n}\nvar poolOf = main => {\n    var raw = rowValue(main, [\'poolCfg\', \'pool_cfg\'])\n    if (blank(raw)) {\n        return {}\n    }\n    try {\n        var parsed = raw instanceof Map ? raw : jsons.parse(textOf(raw))\n        if (parsed == null) {\n            return {}\n        }\n        return parsed\n    } catch (e) {\n        exit 500, \'数据源连接配置 pool_cfg 不是有效 JSON 对象\'\n    }\n}\nvar copyMaster = (result, main) => {\n    var pairs = {\n        dbType: [\'dbType\', \'db_type\'],\n        jdbcURL: [\'jdbcURL\', \'jdbcUrl\', \'jdbc_url\'],\n        username: [\'username\'],\n        password: [\'password\'],\n        dbVersion: [\'dbVersion\', \'db_version\'],\n        nodeId: [\'nodeId\', \'node_id\'],\n        storageDomain: [\'storageDomain\', \'storage_domain\'],\n        showConnect: [\'showConnect\', \'show_connect\'],\n        connectionStatus: [\'connectionStatus\', \'connection_status\']\n    }\n    for (key in pairs.keySet()) {\n        var value = rowValue(main, pairs[key])\n        if (value != null) {\n            result[key] = value\n        }\n    }\n}\nvar read = datasourceId => {\n    var main = mainOf(datasourceId)\n    if (main == null) {\n        return {}\n    }\n    var result = {}\n    result.putAll(poolOf(main))\n    copyMaster(result, main)\n    return result\n}\nvar save = (datasourceId, values, clearAll) => {\n    var main = mainOf(datasourceId)\n    if (main == null) {\n        exit 404, \'数据源不存在或不属于当前租户\'\n    }\n    var config = clearAll == true ? {} : poolOf(main)\n    if (clearAll != true && values != null) {\n        // MagicScript cannot invoke Map.Entry#getKey/getValue on values passed\n        // across a function boundary. Iterate the map keys and read each value\n        // through the map instead, which also works for native script objects.\n        var valueKeys = values instanceof Map ? values.keySet() : values\n        for (keyItem in valueKeys) {\n            var key = textOf(keyItem)\n            var value = values instanceof Map ? values.get(keyItem) : values[keyItem]\n            if (!blank(key) && value != null) {\n                config[key] = value\n            }\n        }\n    }\n    var update = {\n        tid: rowValue(main, [\'tid\']),\n        pool_cfg: clearAll == true ? null : jsons.toJsonStr(config),\n        updated_time: new Date()\n    }\n    if (clearAll == true) {\n        update.jdbc_url = null\n        update.username = null\n        update.password = null\n        update.driver_class_name = null\n    } else {\n        var dbType = config.dbType\n        var jdbcUrl = config.jdbcURL == null ? config.jdbcUrl : config.jdbcURL\n        if (!blank(dbType)) {\n            update.db_type = textOf(dbType)\n        }\n        if (!blank(jdbcUrl)) {\n            update.jdbc_url = textOf(jdbcUrl)\n        }\n        if (config.username != null) {\n            update.username = textOf(config.username)\n        }\n        if (config.password != null) {\n            update.password = textOf(config.password)\n        }\n    }\n    db.table(\'db_datasource_t\').primary(\'tid\').update(update, true)\n    return read(datasourceId)\n}\n\nif (action == \'read\') {\n    return read(datasourceId)\n}\nif (action == \'json\') {\n    return jsons.toJSONStr(read(datasourceId))\n}\nif (action == \'save\') {\n    return save(datasourceId, values, clearAll == true)\n}\nexit 400, \'action 仅支持 read、json 或 save\'\n',NULL,NULL,0,NULL,'/magic-api/function/01.通用函数/08.读取或保存数据源连接配置.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('69f8ec0221c341a1ad8ac18138b5428d',NULL,NULL,'{\n  "properties": {},\n  "id": "69f8ec0221c341a1ad8ac18138b5428d",\n  "script": "// 共享函数：09.请求参数白名单校验\\n// 函数路径：/common/check-params\\n// 业务说明：逐项比较请求参数名与允许列表；出现未登记参数时抛出业务错误，合法或空参数返回校验通过。\\n// 函数输入：params：待校验的请求参数；validParams：允许的参数名集合。\\nimport com.linewell.dataasset.common.exception.BizException;\\nif (!!!params) {\\n  return true;\\n}\\nif (!!!validParams || validParams.size() <= 0) {\\n  return true;\\n}\\nfor (key,value in params) {\\n  if (!validParams.contains(key)) {\\n    throw new BizException(10081,\\"参数不合法\\",\\"参数不合法\\")\\n  }\\n}\\nreturn true\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "09.请求参数白名单校验",\n  "createTime": 1782660730398,\n  "updateTime": 1724118197703,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "check-params",\n  "description": "逐项比较请求参数名与允许列表；出现未登记参数时抛出业务错误，合法或空参数返回校验通过。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "params",\n      "value": null,\n      "description": "待校验的请求参数",\n      "required": false,\n      "dataType": "String",\n      "type": "java.util.Map",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "validParams",\n      "value": null,\n      "description": "允许的参数名集合",\n      "required": false,\n      "dataType": "String",\n      "type": "java.util.Collection",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/09.请求参数白名单校验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c495f88713a44e1eb0b43b1d3882b060',NULL,NULL,'{\n  "properties": {},\n  "id": "c495f88713a44e1eb0b43b1d3882b060",\n  "script": "// 共享函数：10.列表按标识分组\\n// 函数路径：/common/list-group-by-id\\n// 业务说明：按指定标识对列表分组，再把同组记录的分类计数折叠到一条结果，供统计展示复用。\\n// 函数输入：list：待处理列表；groupId：分组标识字段名；name：名称字段名；group：分类字段名；count：计数字段名。\\nif (!!!list) {\\n  return null;\\n}\\nvar map = list.group(it->it[groupId], list->list);\\nvar res = new ArrayList();\\nfor (key,value in map) {\\n    var obj = {}\\n    var arr = map[key];\\n    obj[\\"name\\"] = arr[0][name];\\n    obj[groupId] = arr[0][groupId];\\n    for (b in arr) {\\n      obj[b[group]] = b[count]\\n    }\\n    res.add(obj);\\n}\\nreturn res\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "10.列表按标识分组",\n  "createTime": 1782660730409,\n  "updateTime": 1662010846684,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list-group-by-id",\n  "description": "按指定标识对列表分组，再把同组记录的分类计数折叠到一条结果，供统计展示复用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "list",\n      "value": null,\n      "description": "待处理列表",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.Object",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "groupId",\n      "value": null,\n      "description": "分组标识字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "name",\n      "value": null,\n      "description": "名称字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "group",\n      "value": null,\n      "description": "分类字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "count",\n      "value": null,\n      "description": "计数字段名",\n      "required": false,\n      "dataType": "String",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/10.列表按标识分组.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9daad772b4da4fc0923d0d97bd719d22',NULL,NULL,'{\n  "properties": {},\n  "id": "9daad772b4da4fc0923d0d97bd719d22",\n  "script": "// 共享函数：11.列表字段分组映射\\n// 函数路径：/common/list-group-map\\n// 业务说明：遍历输入列表并按指定字段构建分组映射，返回每个字段值对应的原始记录集合。\\n// 函数输入：list：待处理列表；key：键字段名。\\nvar map = {\\n\\n};\\nfor (val in list) {\\n    var tmp = val[key];\\n    if (!!!map[tmp]) {\\n        map[tmp] = new ArrayList();\\n    }\\n    map[tmp].add(val);\\n}\\nreturn map\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "11.列表字段分组映射",\n  "createTime": 1782660730420,\n  "updateTime": 1667552802718,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list-group-map",\n  "description": "遍历输入列表并按指定字段构建分组映射，返回每个字段值对应的原始记录集合。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "list",\n      "value": null,\n      "description": "待处理列表",\n      "required": false,\n      "dataType": "String",\n      "type": "java.util.Collection",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "key",\n      "value": null,\n      "description": "键字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/11.列表字段分组映射.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0a3fae28bd16437aa2473eb2c31f6a7b',NULL,NULL,'{\n  "properties": {},\n  "id": "0a3fae28bd16437aa2473eb2c31f6a7b",\n  "script": "// 共享函数：12.列表转键值映射\\n// 函数路径：/common/list-to-map\\n// 业务说明：以指定字段作为键，将列表转为对象映射；可选择整行或指定值字段，空键记录被跳过。\\n// 函数输入：list：待处理列表；key：键字段名；value：值字段名。\\nvar res = {}\\nfor (val in list) {\\n    var tmpKey = val[key];\\n    if (!!!tmpKey) {\\n        continue;\\n    }\\n    if (!!!value) {\\n        res[tmpKey] = val\\n        continue;\\n    }\\n    res[tmpKey] = val[value]\\n}\\nreturn res;\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "12.列表转键值映射",\n  "createTime": 1782660730429,\n  "updateTime": 1662010846696,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/list-to-map",\n  "description": "以指定字段作为键，将列表转为对象映射；可选择整行或指定值字段，空键记录被跳过。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "list",\n      "value": null,\n      "description": "待处理列表",\n      "required": false,\n      "dataType": "String",\n      "type": "java.util.Collection",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "key",\n      "value": null,\n      "description": "键字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "value",\n      "value": null,\n      "description": "值字段名",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/12.列表转键值映射.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('655d56e94cdc4238ba0a7f7f942c8cb3',NULL,NULL,'{\n  "properties": {},\n  "id": "655d56e94cdc4238ba0a7f7f942c8cb3",\n  "script": "// 共享函数：13.存储单位换算\\n// 函数路径：/common/unit-compute\\n// 业务说明：按单位类别和输入数值换算存储容量等计量值，返回转换后的数值与单位。\\n// 函数输入：countNum：待换算数量；typeCode：单位类别；unit：如张 、 条 个。\\nimport java.math.BigDecimal\\nvar res = {\\n\\n}\\nif (typeCode == \'storage\') {\\n    if (countNum < 1024L) {\\n        res.value = countNum;\\n        res.unit = \'Kb\';\\n        return res;\\n    }\\n    if (countNum < 1024 * 1024L) {\\n        res.value = new BigDecimal(countNum).divide(new BigDecimal(1024L), 2,BigDecimal.ROUND_HALF_UP);\\n        res.unit = \'Mb\';\\n        return res;\\n    }\\n    if (countNum < 1024 * 1024 * 1024L) {\\n        res.value = new BigDecimal(countNum).divide(new BigDecimal(1024 * 1024L), 2,BigDecimal.ROUND_HALF_UP);\\n        res.unit = \'Gb\';\\n        return res;\\n    }\\n    res.value = new BigDecimal(countNum).divide(new BigDecimal(1024 * 1024 * 1024L), 2,BigDecimal.ROUND_HALF_UP);\\n    res.unit = \'Tb\';\\n    \\n    return res;\\n}\\nif (!!!unit) {\\n    unit = \'\';\\n}\\nif (countNum < 10000) {\\n    res.value = countNum;\\n    res.unit = unit;\\n    return res;\\n}\\nif (countNum < 100000000L) {\\n    res.value = new BigDecimal(countNum).divide(new BigDecimal(10000L), 2,BigDecimal.ROUND_HALF_UP);\\n    res.unit = \'万\'+unit;\\n    return res;\\n}\\nif (countNum < 1000000000000L) {\\n    res.value = new BigDecimal(countNum).divide(new BigDecimal(100000000L), 2,BigDecimal.ROUND_HALF_UP);\\n    res.unit = \'亿\'+unit;\\n    return res;\\n}\\nif (countNum < 10000000000000000L) {\\n    res.value = new BigDecimal(countNum).divide(new BigDecimal(1000000000000L), 2,BigDecimal.ROUND_HALF_UP);\\n    res.unit = \'万亿\'+unit;\\n    return res;\\n}\\nres.value = new BigDecimal(countNum).divide(new BigDecimal(10000000000000000L), 2,BigDecimal.ROUND_HALF_UP);\\nres.unit = \'亿亿\'+unit;\\nreturn res\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "13.存储单位换算",\n  "createTime": 1782660730439,\n  "updateTime": 1724119382041,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/unit-compute",\n  "description": "按单位类别和输入数值换算存储容量等计量值，返回转换后的数值与单位。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "countNum",\n      "value": null,\n      "description": "待换算数量",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.Number",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "typeCode",\n      "value": null,\n      "description": "单位类别",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "unit",\n      "value": null,\n      "description": "如张 、 条 个",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/13.存储单位换算.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('80c67a380dda4f0595e84d16e365f3db',NULL,NULL,'{\n  "properties": {},\n  "id": "80c67a380dda4f0595e84d16e365f3db",\n  "script": "// 共享函数：14.对象字段转映射\\n// 函数路径：/common/objConvertMap\\n// 业务说明：调用 BeanUtil.beanToMap 将传入 Java Bean 的属性转为映射，供需要键值结构的接口复用。\\n// 函数输入：bean ：对象。\\nimport cn.hutool.core.bean.BeanUtil\\nimport cn.hutool.core.util.StrUtil\\n\\nvar res = new HashMap();\\n// 假设 bean 是你的原始对象\\nvar temp = BeanUtil.beanToMap(bean,null)\\n\\nreturn temp\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "14.对象字段转映射",\n  "createTime": 1782660730450,\n  "updateTime": 1770273772417,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/objConvertMap",\n  "description": "调用 BeanUtil.beanToMap 将传入 Java Bean 的属性转为映射，供需要键值结构的接口复用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "bean ",\n      "value": null,\n      "description": "对象",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.Object",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/14.对象字段转映射.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('d38635c1476543c8bdccfcd5a767f275',NULL,NULL,'{\n  "properties": {},\n  "id": "d38635c1476543c8bdccfcd5a767f275",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "script": "// 共享函数：15.日期时间转换示例\\n// 函数路径：/common/dataTimeConverter\\n// 业务说明：历史演示函数：内部定义日期转换与安全转换方法，然后对脚本内固定样例逐项转换并返回结果列表；当前没有外部调用方。\\n// 函数输入：无显式参数。\\nimport java.time.LocalDateTime;\\nimport java.time.format.DateTimeFormatter;\\nimport java.time.format.DateTimeParseException;\\n\\n/**\\n * 时间格式转换工具类\\n * 支持多种时间格式，统一转换为 yyyy-MM-dd HH:mm:ss 格式\\n */\\n \\n// 目标格式\\nvar TARGET_FORMATTER = DateTimeFormatter.ofPattern(\\"yyyy-MM-dd HH:mm:ss\\");\\n\\n// 支持的时间格式列表\\nvar SUPPORTED_FORMATTERS = [\\n    // yyyyMMddHHmmss (14位数字，无分隔符)\\n    DateTimeFormatter.ofPattern(\\"yyyyMMddHHmmss\\"),\\n    // yyyy-MM-dd HH:mm:ss (标准格式)\\n    DateTimeFormatter.ofPattern(\\"yyyy-MM-dd HH:mm:ss\\"),\\n    // yyyy-MM-dd HH:mm:ss.S (带小数点)\\n    DateTimeFormatter.ofPattern(\\"yyyy-MM-dd HH:mm:ss.S\\"),\\n    // yyyy-MM-dd HH:mm:ss.SS (带两位小数)\\n    DateTimeFormatter.ofPattern(\\"yyyy-MM-dd HH:mm:ss.SS\\"),\\n    // yyyy-MM-dd HH:mm:ss.SSS (带三位小数)\\n    DateTimeFormatter.ofPattern(\\"yyyy-MM-dd HH:mm:ss.SSS\\")\\n]\\n\\n/**\\n * 将各种时间格式转换为 yyyy-MM-dd HH:mm:ss 格式\\n * \\n * @param dateTimeStr 输入的时间字符串\\n * @return 格式化后的时间字符串 (yyyy-MM-dd HH:mm:ss)\\n * @throws IllegalArgumentException 如果无法解析输入的时间格式\\n */\\nvar convert = (dateTimeStr) => {\\n    if (dateTimeStr == null || dateTimeStr.trim().isEmpty()) {\\n        throw new IllegalArgumentException(\\"时间字符串不能为空\\");\\n    }\\n    \\n    String trimmed = dateTimeStr.trim();\\n    \\n    // 尝试使用各种格式解析\\n    for ( formatter in SUPPORTED_FORMATTERS) {\\n        try {\\n            LocalDateTime dateTime = LocalDateTime.parse(trimmed, formatter);\\n            return dateTime.format(TARGET_FORMATTER);\\n        } catch (e) {\\n            // 继续尝试下一个格式\\n            continue;\\n        }\\n    }\\n    \\n    // 如果所有格式都解析失败，抛出异常\\n    throw new IllegalArgumentException(\\n        \\"无法解析时间格式: \\" + dateTimeStr + \\n        \\"。支持的格式: yyyyMMddHHmmss, yyyy-MM-dd HH:mm:ss, yyyy-MM-dd HH:mm:ss.S等\\");\\n}\\n\\n/**\\n * 将各种时间格式转换为 yyyy-MM-dd HH:mm:ss 格式（安全版本，解析失败返回null）\\n * \\n * @param dateTimeStr 输入的时间字符串\\n * @return 格式化后的时间字符串，如果解析失败则返回null\\n */\\nvar convertSafely = (dateTimeStr) => {\\n    try {\\n        return convert(dateTimeStr);\\n    } catch (e) {\\n        return null;\\n    }\\n}\\n    \\n    var testCases = {\\n            \\"20251204012100\\",\\n            \\"2024-04-08 02:27:54.0\\",\\n            \\"2024-04-08 02:27:56.0\\",\\n            \\"2019-09-23 16:30:15.0\\",\\n            \\"1970-01-01 08:00:00\\",\\n            \\"20251203232121\\",\\n            \\"2024-04-08 02:28:21.0\\",\\n            \\"20251203232552\\",\\n            \\"20251204234610\\",\\n            \\"20251204233933\\"\\n        };\\n\\n        \\n var tt = [];       \\n        \\n        System.out.println(\\"时间格式转换测试：\\");\\n        System.out.println(\\"==========================================\\");\\n        for (testCase in testCases) {\\n            try {\\n                String result = dataTimeConverter.convertSafely(testCase);\\n                print(result);\\n                tt.add(result);\\n            } catch (e) {\\n                tt.add(result);\\n            }\\n        }\\nreturn tt;\\n",\n  "name": "15.日期时间转换示例",\n  "createTime": 1782660730459,\n  "updateTime": 1765160217788,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/dataTimeConverter",\n  "description": "历史演示函数：内部定义日期转换与安全转换方法，然后对脚本内固定样例逐项转换并返回结果列表；当前没有外部调用方。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": []\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/15.日期时间转换示例.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a5a47aad30264c5da7990b3244f2a1d7',NULL,NULL,'{\n  "properties": {},\n  "id": "a5a47aad30264c5da7990b3244f2a1d7",\n  "script": "// 共享函数：16.读取通用配置项\\n// 函数路径：/common/configData\\n// 业务说明：读取公共和非敏感运行配置；敏感凭据由对应集成接口按需读取 Nacos，不在共享函数中返回。\\n// 函数输入：无显式参数。\\nimport systemConfig\\n\\nvar config = systemConfig.runtimeSettings()\\nreturn config\\n",\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "16.读取通用配置项",\n  "createTime": 1782660730502,\n  "updateTime": 1783321121140,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/configData",\n  "description": "读取公共和非敏感运行配置；敏感凭据由对应集成接口按需读取 Nacos，不在共享函数中返回。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": []\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/16.读取通用配置项.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7ce142655939405bbcd64abace9ba0a7',NULL,NULL,'{\n  "properties": {},\n  "id": "7ce142655939405bbcd64abace9ba0a7",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "17.按父节点读取属性映射",\n  "createTime": 1782660730470,\n  "updateTime": 1787153840799,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/getPropMap",\n  "description": "按父节点标识读取关联属性，组装为可按键访问的映射供表单和配置查询复用。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "parentId",\n      "value": null,\n      "description": "父节点标识",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：17.按父节点读取属性映射\n// 函数路径：/common/getPropMap\n// 业务说明：按父节点标识读取关联属性，组装为可按键访问的映射供表单和配置查询复用。\n// 函数输入：parentId：父节点标识。\nimport cn.hutool.json.JSONUtil\nimport log\nimport cn.hutool.core.util.IdUtil\nimport IdGenerator\nimport jsons\n\n\n// 1. 查询旧的动态属性数据\nvar oldProps = db.table(\'da_prop_t\')\n    .where()\n    .eq(\'parent_id\', parentId)\n    //.eq(\'data_type\', assetType)\n    .eq(\'is_del\', 0)\n    .select()\n\n// 2. 构建旧属性 Map: prop_name -> {tid, prop_value, prop_type}\nvar oldPropMap = {}\nif (oldProps != null && oldProps.size() > 0) {\n    for (prop in oldProps) {\n        // oldPropMap[prop.propName] = {\n        //     tid: prop.tid,\n        //     prop_value: prop.propValue,\n        //     prop_type: prop?.propType\n        // }\n        oldPropMap[prop.propName] = prop.propValue\n    }\n}\n\nvar oldAsset = db.table(\'da_asset_t\')\n    .where()\n    .eq(\'tid\', parentId)\n    //.eq(\'data_type\', assetType)\n    .eq(\'is_del\', 0)\n    .selectOne()\n\noldPropMap.tid = parentId\noldPropMap.assetType = oldAsset?.assetType\n\n\nlog.info(\'旧属性数量: {}\', oldPropMap.size())\n\nreturn oldPropMap\n',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/17.按父节点读取属性映射.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('08aba97010b949d39bafa1e13f71619a',NULL,NULL,'{\n  "properties": {},\n  "id": "08aba97010b949d39bafa1e13f71619a",\n  "script": null,\n  "groupId": "0f27d7cf99494ceca369c14f35fbb987",\n  "name": "18.读取本地应用表名缓存",\n  "createTime": 1782660730492,\n  "updateTime": 1787153840900,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/localCache",\n  "description": "先按 tid 查本地名称缓存；未命中时依 assetType 从资产属性、机构或接入任务表读取名称并写回缓存。",\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "tid",\n      "value": null,\n      "description": "目标记录主键",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "assetType",\n      "value": null,\n      "description": "待读取名称的资产、机构或接入任务类型",\n      "required": false,\n      "dataType": "String",\n      "type": "java.lang.String",\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 共享函数：18.读取本地应用表名缓存\n// 函数路径：/common/localCache\n// 业务说明：先按 tid 查本地名称缓存；未命中时依 assetType 从资产属性、机构或接入任务表读取名称并写回缓存。\n// 函数输入：tid：目标记录主键；assetType：待读取名称的资产、机构或接入任务类型。\n// LocalCache  bean 对象\nimport com.linewell.dataelement.utils.LocalCache as cache\nimport log\n//获取资产缓存\nvar value = cache.get(tid);\nif( value != null && value != "") { \n    return value\n}else {\n   if( assetType == "app" || assetType == "db" || assetType == "table" || assetType == "catalog") {\n      var assetPropValue = db.table("da_prop_t").column("prop_value").where()\n         .eq(assetType == "app", "prop_name","appName")\n         .eq(assetType == "db", "prop_name","dbName")\n         .eq(assetType == "table", "prop_name","tableName")\n         .eq(assetType == "catalog", "prop_name","catalogName")\n         .eq("parent_id",tid)\n         .selectOne()\n         log.info(assetPropValue);\n         if( assetPropValue != null){\n            cache.put(tid, assetPropValue.propValue);\n         }\n   }else {\n      //获取组织机构名称\n      if( assetType == "org" ){\n          var orgInfo= db.table(\'rm_org_t\')\n                .where()\n                .eq(\'id\', tid)\n                .eq(\'deleted\', \'0\').selectOne()\n         if( orgInfo != null){\n            cache.put(tid, orgInfo?.orgPath)\n         }\n      } \n      //获取组织机构路径\n      else  if( assetType == "orgPath" ){\n          id = tid.split(":")[0]\n          var orgInfo= db.table(\'rm_org_t\')\n                .where()\n                .eq(\'id\', id)\n                .eq(\'deleted\', \'0\').selectOne()\n         if( orgInfo != null){\n            cache.put(tid, orgInfo?.serialNumber)\n         }\n      } \n      // 接入任务\n      else if ( assetType == "accessTask" ){\n          var taskInfo= db.table(\'data_access_agg_task_t\')\n                .where()\n                .eq(\'tid\', tid)\n                .eq(\'is_del\', \'0\').selectOne()\n         if( taskInfo != null){\n            cache.put(tid, taskInfo?.taskName)\n         }  \n      }\n   }\n}\nreturn cache.get(tid)\n',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/18.读取本地应用表名缓存.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0f27d7cf99494ceca369c14f35fbb987',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "0f27d7cf99494ceca369c14f35fbb987",\r\n  "name" : "01.通用函数",\r\n  "type" : "function",\r\n  "parentId" : "0",\r\n  "path" : "/common",\r\n  "createTime" : 1782660713429,\r\n  "updateTime" : 1753943361800,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "paths" : [ ],\r\n  "options" : [ ]\r\n}',NULL,NULL,0,'2084109831678504960','/magic-api/function/01.通用函数/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bdb08194c25440e88dd66b44fe5dd5cd',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('320dd8606b1f481ebc245f56753a1ddb',NULL,NULL,'{\n  "id": "ga_local_login_01",\n  "groupId": "ga_local_accounts_functions_01",\n  "name": "01.租户本地登录",\n  "path": "/login",\n  "parameters": [\n    {\n      "name": "payload",\n      "dataType": "Object",\n      "type": null,\n      "required": false,\n      "value": null,\n      "description": "该动作所需的账号、角色或资源资料"\n    }\n  ],\n  "script": null,\n  "description": "在当前租户库核验本地账号、密码和状态，返回租户本地登录结果；不接受统一身份平台账号冒充本地账号。"\n}\n================================\n// 共享函数：01.租户本地登录\n// 函数路径：/tenant-account/login\n// 业务说明：在当前租户库核验本地账号、密码和状态，返回租户本地登录结果；不接受统一身份平台账号冒充本地账号。\n// 函数输入：payload：该动作所需的账号、角色或资源资料。\nimport db;\nimport identityRuntime;\nimport tenantAccounts;\nimport cn.hutool.core.util.IdUtil;\nimport com.linewell.dataelement.utils.PwdRuleUtil;\nimport \'@/idaas/receiver-account-check\' as sourceCheck;\n// 公安本地登录：仅校验显式绑定业务库的账号，不查询控制库用户或成员关系。\nvar p=payload||{};var tenantId=(p.tenantId||\'\')+\'\';\nvar account=(p.account||\'\').trim();var password=(p.password||\'\').trim().toUpperCase();\nif(tenantId==\'\' || account==\'\' || account.length()>50 || !password.matches(\'[0-9A-F]{64}\')) {exit 400,\'请输入有效的账号和密码\';}\nif(!tenantAccounts.isLocal(tenantId)) {exit 403,\'当前租户未启用本地账号\';}\nvar sql=db.normal();\nvar user=identityRuntime.inTenant(tenantId,()=>sql.selectOne("""\nselect id,password as "password",status\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and user_name=#{account}\n    and deleted=0\n"""));\nif(user==null || user.status!=0 || user.password==null || !PwdRuleUtil.checkPwdBySalt(password,user.password)) {exit -1,\'用户名或密码错误\';}\nif(!identityRuntime.inTenant(tenantId,()=>sourceCheck(user.id)).allowed) {exit -1,\'此账号的统一管理来源已停用，请联系管理员或办理脱管\';}\nvar token=tenantAccounts.loginLocal(tenantId,user.id,(p.appId||\'\')+\'\',account);\nvar logId=IdUtil.getSnowflakeNextIdStr();\nsql.update("""\ninsert into log_user_login_t(tid,\n                account, is_success, token, created_by, updated_by, created_time, updated_time, is_del,\n                tenant_id)\nvalues(#{logId},#{account},1,#{token},#{user.id},#{user.id},current_timestamp,current_timestamp,0,#{tenantId})\n""");\nreturn {token:token,url:\'/home\',authRealm:\'tenant-local-v1\',tenantId:tenantId};\n',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/01.租户本地登录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('01d4080a35c3490f9160b2c0db639c05',NULL,NULL,'{\n  "id": "ga_local_users_01",\n  "groupId": "ga_local_accounts_functions_01",\n  "name": "02.租户本地用户维护",\n  "path": "/users",\n  "parameters": [\n    {\n      "name": "operation",\n      "dataType": "Object",\n      "type": null,\n      "required": false,\n      "value": null,\n      "description": "要执行的本地账号业务动作"\n    },\n    {\n      "name": "payload",\n      "dataType": "Object",\n      "type": null,\n      "required": false,\n      "value": null,\n      "description": "该动作所需的账号、角色或资源资料"\n    }\n  ],\n  "script": null,\n  "description": "复用租户本地用户的查询、保存及状态规则，读写本地账号资料而不修改控制库统一认证账号。"\n}\n================================\n// 共享函数：02.租户本地用户维护\n// 函数路径：/tenant-account/users\n// 业务说明：复用租户本地用户的查询、保存及状态规则，读写本地账号资料而不修改控制库统一认证账号。\n// 函数输入：operation：要执行的本地账号业务动作；payload：该动作所需的账号、角色或资源资料。\nimport db;\nimport tenantRuntime;\nimport tenantAccounts;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.SmUtil;\nimport identityRuntime;\nimport cn.hutool.json.JSONUtil;\nimport com.linewell.dataelement.utils.PwdRuleUtil;\n// 租户本地用户：查询不返回密码摘要；账号及机构关系在同一业务库事务中维护。\nvar tenantId=tenantRuntime.id();var actor=StpUtil.getLoginId()+\'\';var p=payload||{};var sql=db.normal();\nif(!tenantAccounts.isLocal(tenantId)) {exit 403,\'当前租户未启用本地账号\';}\nvar text=value=>value==null?\'\':(value+\'\').trim();\nif(operation==\'page\' || operation==\'list\') {\n var page=Math.max(1,p.pageNum||1);var size=Math.min(200,Math.max(1,p.pageSize||200));var offset=(page-1)*size;\n var ids=p.ids;var account=\'%\'+text(p.userName)+\'%\';var name=\'%\'+text(p.realName)+\'%\';\n if(ids!=null && ids.size()==0) {return operation==\'list\'?[]:{list:[],total:0};}\n var where=`from rm_user_t u where u.tenant_id=#{tenantId} and u.deleted=0 and u.user_name like #{account} and u.real_name like #{name}`;\n if(ids!=null) {where=where+` and u.id in (#{ids})`;}\n var total=sql.selectOne(\'select count(*) as total \'+where).total;\n var rows=sql.select("""\nselect u.id,u.real_name as "realName",u.user_name as "userName",u.phone,u.gender,u.status,\n       \'******\' as "password", u.app_file_id as "appFileId",u.create_id as "createId",u.create_time as "createTime",\n       u.update_time as "updateTime", u.id_card as "idCard",u.date_birth as "dateBirth",u.nation,\n       u.office_address as "officeAddress",u.job_number as "jobNumber", u.authorized_strength as "authorizedStrength",\n       u.origin_position as "originPosition",u.origin_rank as "originRank"\n"""+where+` order by u.create_time,u.id limit #{size} offset #{offset}`);\n return operation==\'list\'?rows:{list:rows,total:total,pageNum:page,pageSize:size};\n}\nvar id=text(p.id);var creating=id==\'\';if(creating) {id=IdUtil.getSnowflakeNextIdStr();}\nvar password=text(p.password);var passwordChanged=password!=\'\' && password!=\'******\';\nvar result=sql.transaction(()=>{\n var old=sql.selectOne("""\nselect id,password as "password",status,app_file_id as "appFileId"\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n    and deleted=0\n    for update\n""");\n if(operation==\'delete\') {\n  if(old==null) {exit 404,\'用户不存在或不属于当前租户\';}\n  if(id==actor) {exit 409,\'不能删除当前登录账号\';}\n  sql.update("""\nupdate rm_user_t\nset deleted=1,status=1,update_id=#{actor},update_time=current_timestamp\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n""");\n  sql.update("""\ndelete\nfrom rm_user_org_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{id}\n""");\n  sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{id}\n""");\n  if(old.appFileId!=null && old.appFileId!=\'\') {sql.update("""\nupdate sym_file_t\nset deleted=1,update_id=#{actor},update_time=current_timestamp\nwhere tenant_id=#{tenantId}\n    and id=#{old.appFileId}\n""");}\n  return {id:id,accountDeleted:true};\n }\n if(operation!=\'save\') {exit 400,\'不支持的用户操作\';}\n if(!creating && old==null) {exit 404,\'用户不存在或不属于当前租户\';}\n var realName=text(p.realName);var account=text(p.userName);var phone=text(p.phone);var orgId=text(p.orgId);var status=p.status==null?-1:p.status::int;\n if(realName==\'\' || realName.length()>50 || !account.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,49}\') || phone==\'\' || phone.length()>128 || ![0,1].contains(status)) {exit 400,\'姓名、账号、手机号或账号状态无效\';}\n if(id==actor && status!=0) {exit 409,\'不能停用当前登录账号\';}\n var org=sql.selectOne("""\nselect id\nfrom rm_org_t\nwhere tenant_id=#{tenantId}\n    and id=#{orgId}\n    and deleted=0\n    and status=0\n""");\n if(org==null || orgId==\'ROOT\') {exit 400,\'请选择有效的所属机构\';}\n var managed=identityRuntime.hasTable(\'idaas_receiver_object_t\')?sql.selectOne("""\nselect snapshot_json\nfrom idaas_receiver_object_t\nwhere object_type=\'SUBJECT\'\n    and local_id=#{id}\n    and management_state=\'MANAGED\'\n"""):null;\n var ownedOrgIds=managed==null?[]:JSONUtil.parseObj(managed.snapshot_json).orgRelations||[];\n if(ownedOrgIds.size()>0 && sql.selectOne("""\nselect id\nfrom rm_user_org_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{id}\n    and id in (#{ownedOrgIds})\n    and job_type=\'1\'\n    and org_id=#{orgId}\n""")==null) {exit 409,\'统一管理的主职请在平台更新或先办理脱管\';}\n var duplicate=sql.selectOne("""\nselect id\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and lower(trim(user_name))=lower(#{account})\n    and deleted=0\n    and id<>#{id}\n""");\n if(duplicate!=null) {exit 409,\'用户账号已存在\';}\n if(creating && !passwordChanged) {exit 400,\'新增用户密码不能为空\';}\n var hash=old==null?null:old.password;\n if(passwordChanged) {\n  if(password.length()<6 || password.length()>128 || password.matches(\'(?i)[0-9a-f]{96}\')) {exit 400,\'密码应为6至128个字符，不能直接提交存储摘要\';}\n  var digest=password.matches(\'(?i)[0-9a-f]{64}\')?password.toUpperCase():SmUtil.sm3(password).toUpperCase();\n  hash=PwdRuleUtil.encryptPwdBySalt(digest);\n }\n // 保持现有用户表单字段和照片引用；不接受客户端指定租户或来源字段。\n var gender=p.gender;var idCard=p.idCard;var dateBirth=text(p.dateBirth)==\'\'?null:text(p.dateBirth).substring(0,10);var nation=p.nation;\n var office=p.officeAddress;var job=p.jobNumber;var strength=p.authorizedStrength;var position=p.originPosition;var rank=p.originRank;var file=p.appFileId;\n if(creating) {sql.update("""\ninsert into rm_user_t(tenant_id,\n                id, real_name, user_name, phone, password, status, deleted, create_id, update_id, create_time,\n                update_time)\nvalues(#{tenantId},#{id},#{realName},#{account},#{phone},#{hash},#{status},0,#{actor},#{actor},current_timestamp,current_timestamp)\n""");}\n sql.update("""\nupdate rm_user_t\nset real_name=#{realName},user_name=#{account},phone=#{phone},password=#{hash},\n    status=#{status},gender=#{gender}, id_card=#{idCard},date_birth=#{dateBirth},\n    nation=#{nation},office_address=#{office},job_number=#{job},\n    authorized_strength=#{strength}, origin_position=#{position},origin_rank=#{rank},\n    app_file_id=#{file},update_id=#{actor},update_time=current_timestamp\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n""");\n if(ownedOrgIds.size()==0) {\n  sql.update("""\ndelete\nfrom rm_user_org_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{id}\n    and job_type=\'1\'\n""");\n  var relationId=IdUtil.getSnowflakeNextIdStr();\n  sql.update("""\ninsert into rm_user_org_rela_t(tenant_id, id, user_id, org_id, job_type, sort_num)\nvalues(#{tenantId},#{relationId},#{id},#{orgId},\'1\',0)\n""");\n }\n return {id:id};\n});\nif(operation==\'delete\' || passwordChanged || p.status==1) {tenantAccounts.revoke(id);}\nreturn result;\n',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/02.租户本地用户维护.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('e0e3bcce07df4bc7bdf221712a44ccbd',NULL,NULL,'{\n  "id": "ga_local_roles_01",\n  "groupId": "ga_local_accounts_functions_01",\n  "name": "03.租户本地用户角色维护",\n  "path": "/roles",\n  "parameters": [\n    {\n      "name": "payload",\n      "dataType": "Object",\n      "type": null,\n      "required": false,\n      "value": null,\n      "description": "该动作所需的账号、角色或资源资料"\n    }\n  ],\n  "script": null,\n  "description": "读取或维护租户本地用户与角色的关联，校验关联对象后返回角色配置结果。"\n}\n================================\n// 共享函数：03.租户本地用户角色维护\n// 函数路径：/tenant-account/roles\n// 业务说明：读取或维护租户本地用户与角色的关联，校验关联对象后返回角色配置结果。\n// 函数输入：payload：该动作所需的账号、角色或资源资料。\nimport db;\nimport tenantRuntime;\nimport tenantAccounts;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\nimport cn.hutool.json.JSONUtil;\n// 仅替换当前应用角色关联；其他应用的角色关联保留。全部校验在事务写入前完成。\nvar tenantId=tenantRuntime.id();var p=payload||{};var userId=(p.userId||\'\')+\'\';\nvar appId=(p.appId||tenantAccounts.session().get(\'appId\')||\'\')+\'\';var sql=db.normal();\nif(userId==\'\' || appId==\'\') {exit 400,\'用户和应用不能为空\';}\nif(tenantAccounts.find(tenantId,userId)==null) {exit 404,\'用户不存在或不属于当前租户\';}\nvar available=sql.select("""\nselect id\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{appId}\n    and deleted=0\n    and status=0\n""").map(r=>r.id);\nvar ids=[];\nfor(id in (p.roleIds||[])) {\n var roleId=(id+\'\').trim();if(!available.contains(roleId)) {exit 400,\'所选角色不存在或不属于当前应用\';}\n if(!ids.contains(roleId)) {ids.add(roleId);}\n}\nif(userId==StpUtil.getLoginId()+\'\' && ids.size()==0) {exit 409,\'不能清空当前登录账号的应用角色\';}\nreturn sql.transaction(()=>{\n var managed=identityRuntime.hasTable(\'idaas_receiver_object_t\')?sql.selectOne("""\nselect snapshot_json\nfrom idaas_receiver_object_t\nwhere object_type=\'SUBJECT\'\n    and local_id=#{userId}\n    and management_state=\'MANAGED\'\n"""):null;\n var owned=managed==null?[]:JSONUtil.parseObj(managed.snapshot_json).roleRelations||[];\n var central=owned.size()==0?[]:sql.select("""\nselect role_id\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and id in (#{owned})\n""").map(r=>r.role_id);\n if(central.filter(id=>!ids.contains(id)).size()>0) {exit 409,\'不能移除中央来源角色，请在平台撤权或先脱管\';}\n if(owned.size()>0) {sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{userId}\n    and id not in (#{owned})\n    and role_id in\n        (select id\n         from rm_role_t\n         where tenant_id=#{tenantId}\n             and app_id=#{appId})\n""");}else {sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and user_id=#{userId}\n    and role_id in\n        (select id\n         from rm_role_t\n         where tenant_id=#{tenantId}\n             and app_id=#{appId})\n""");}\n for(roleId in ids) {\n  if(central.contains(roleId)) {continue;}\n  var id=IdUtil.getSnowflakeNextIdStr();sql.update("""\ninsert into rm_user_role_rela_t(tenant_id,\n                id, user_id, role_id, auth_from, edit_time, is_temporary)\nvalues(#{tenantId},#{id},#{userId},#{roleId},0,current_timestamp,0)\n""");\n }\n return {userId:userId,roleIds:ids};\n});\n',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/03.租户本地用户角色维护.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('759671a890994e50a7658c2d404317e9',NULL,NULL,'{\n  "id": "ga_local_role-admin_01",\n  "groupId": "ga_local_accounts_functions_01",\n  "path": "/role-admin",\n  "name": "04.租户本地角色维护",\n  "properties": {},\n  "parameters": [\n    {\n      "name": "operation",\n      "dataType": "Object",\n      "required": false,\n      "description": "要执行的本地账号业务动作"\n    },\n    {\n      "name": "payload",\n      "dataType": "Object",\n      "required": false,\n      "description": "该动作所需的账号、角色或资源资料"\n    }\n  ],\n  "description": "复用租户本地角色的查询与保存规则，限制角色操作在当前租户库。",\n  "script": null\n}\n================================\n// 共享函数：04.租户本地角色维护\n// 函数路径：/tenant-account/role-admin\n// 业务说明：复用租户本地角色的查询与保存规则，限制角色操作在当前租户库。\n// 函数输入：operation：要执行的本地账号业务动作；payload：该动作所需的账号、角色或资源资料。\nimport db;\nimport tenantRuntime;\nimport tenantAccounts;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\n// 本地角色的保存和删除：先验证本地账号与角色归属，再在单一租户事务中写入。\nvar tenantId=tenantRuntime.id();var actor=StpUtil.getLoginId()+\'\';var p=payload||{};var sql=db.normal();\nvar id=(p.id||\'\')+\'\';var appId=(p.appId||tenantAccounts.session().get(\'appId\')||\'\')+\'\';\nif(appId==\'\') {exit 400,\'应用不能为空\';}\nvar creating=id==\'\';if(creating) {id=IdUtil.getSnowflakeNextIdStr();}\nvar old=sql.selectOne("""\nselect id\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n    and app_id=#{appId}\n    and deleted=0\n""");\nif(identityRuntime.hasTable(\'idaas_receiver_object_t\') && sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere local_id=#{id}\n    and object_type=\'ROLE\'\n    and management_state=\'MANAGED\'\n""")!=null) {exit 409,\'中央拥有的角色请在平台维护或先脱管\';}\nif(!creating && old==null) {exit 404,\'角色不存在或不属于当前应用\';}\nvar selected=[];\nif(operation==\'save\') {\n for(userId in ((p.userIds||\'\')+\'\').split(\',\')) {\n  var uid=userId.trim();if(uid==\'\') {continue;}\n  if(tenantAccounts.find(tenantId,uid)==null) {exit 400,\'所选用户不是本租户的本地用户\';}\n  if(!selected.contains(uid)) {selected.add(uid);}\n }\n}\nvar self=sql.selectOne("""\nselect id\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and role_id=#{id}\n    and user_id=#{actor}\nlimit 1\n""");\nif(self!=null && (operation==\'delete\' || !selected.contains(actor))) {exit 409,\'不能删除或移除当前登录账号正在使用的角色\';}\nreturn sql.transaction(()=>{\n if(operation==\'delete\') {\n  if(old==null) {exit 404,\'角色不存在\';}\n  sql.update("""\nupdate rm_role_t\nset deleted=1,update_id=#{actor},update_time=current_timestamp\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n""");\n  sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and role_id=#{id}\n""");\n  sql.update("""\ndelete\nfrom rm_role_menu_rela_t\nwhere tenant_id=#{tenantId}\n    and role_id=#{id}\n""");\n  return {id:id,deleted:true};\n }\n if(operation!=\'save\') {exit 400,\'不支持的角色操作\';}\n var name=(p.roleName||\'\').trim();var code=(p.codeNum||\'\').trim();var description=(p.description||\'\')+\'\';\n var status=p.status==null?0:p.status::int;var sort=p.sortNum||0;\n if(name==\'\' || name.length()>255 || code==\'\' || code.length()>255 || ![0,1].contains(status)) {exit 400,\'角色名称、编码或状态无效\';}\n var duplicate=sql.selectOne("""\nselect id\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{appId}\n    and code_num=#{code}\n    and id<>#{id}\n    and deleted=0\n""");\n if(duplicate!=null) {exit 409,\'当前应用的角色编码已存在\';}\n if(creating) {sql.update("""\ninsert into rm_role_t(tenant_id,\n                id, app_id, name, code_num, description, status, sort_num, deleted, create_id, update_id,\n                create_time, update_time)\nvalues(#{tenantId},#{id},#{appId},#{name},#{code},#{description},#{status},#{sort},0,#{actor},#{actor},current_timestamp,current_timestamp)\n""");}\n else {sql.update("""\nupdate rm_role_t\nset name=#{name},code_num=#{code},description=#{description},status=#{status},\n    sort_num=#{sort},update_id=#{actor},update_time=current_timestamp\nwhere tenant_id=#{tenantId}\n    and id=#{id}\n""");}\n sql.update("""\ndelete\nfrom rm_user_role_rela_t\nwhere tenant_id=#{tenantId}\n    and role_id=#{id}\n""");\n for(uid in selected) {var rid=IdUtil.getSnowflakeNextIdStr();sql.update("""\ninsert into rm_user_role_rela_t(tenant_id,\n                id, user_id, role_id, auth_from, edit_time, is_temporary)\nvalues(#{tenantId},#{rid},#{uid},#{id},0,current_timestamp,0)\n""");}\n return {success:true,id:id};\n});\n',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/04.租户本地角色维护.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('cfbf499b180c4b9cb6e09d953790d01a',NULL,NULL,'{\n  "id": "ga_local_resources_01",\n  "groupId": "ga_local_accounts_functions_01",\n  "path": "/resources",\n  "name": "05.租户本地角色资源维护",\n  "properties": {},\n  "parameters": [\n    {\n      "name": "payload",\n      "dataType": "Object",\n      "required": false,\n      "description": "该动作所需的账号、角色或资源资料"\n    }\n  ],\n  "description": "维护租户本地角色与菜单资源的关联，供本地系统权限判断使用。",\n  "script": null\n}\n================================\n// 共享函数：05.租户本地角色资源维护\n// 函数路径：/tenant-account/resources\n// 业务说明：维护租户本地角色与菜单资源的关联，供本地系统权限判断使用。\n// 函数输入：payload：该动作所需的账号、角色或资源资料。\nimport db;\nimport tenantRuntime;\nimport cn.hutool.core.util.IdUtil;\nimport identityRuntime;\n// 本地角色菜单：无效资源在清理旧授权之前拒绝，替换操作使用同一个租户事务。\nvar tenantId=tenantRuntime.id();var p=payload||{};var roleId=(p.roleId||\'\')+\'\';var sql=db.normal();\nvar role=sql.selectOne("""\nselect id,app_id as "appId"\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and id=#{roleId}\n    and deleted=0\n""");\nif(identityRuntime.hasTable(\'idaas_receiver_object_t\') && sql.selectOne("""\nselect local_id\nfrom idaas_receiver_object_t\nwhere local_id=#{roleId}\n    and object_type=\'ROLE\'\n    and management_state=\'MANAGED\'\n""")!=null) {exit 409,\'中央拥有角色的资源请在平台维护或先脱管\';}\nif(role==null) {exit 404,\'角色不存在或不属于当前租户\';}\nvar ids=[];var appId=role.appId;\nfor(resourceId in (p.resourceIds||[])) {\n var id=resourceId+\'\';\n if(sql.selectOne("""\nselect id\nfrom rm_menu_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{appId}\n    and id=#{id}\n    and deleted=0\n""")==null) {exit 400,\'所选菜单不存在或不属于当前应用\';}\n if(!ids.contains(id)) {ids.add(id);}\n}\nreturn sql.transaction(()=>{\n sql.update("""\ndelete\nfrom rm_role_menu_rela_t\nwhere tenant_id=#{tenantId}\n    and role_id=#{roleId}\n""");\n for(resourceId in ids) {var id=IdUtil.getSnowflakeNextIdStr();sql.update("""\ninsert into rm_role_menu_rela_t(tenant_id,\n                id, role_id, app_resource_id, extend_id)\nvalues(#{tenantId},#{id},#{roleId},#{resourceId},\'\')\n""");}\n return {roleId:roleId,count:ids.size()};\n});\n',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/05.租户本地角色资源维护.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('99aaa72b0c7a455b8fd4ee94807779f5',NULL,NULL,'{"id": "ga_local_accounts_functions_01", "name": "09.租户账号", "type": "function", "path": "/tenant-account", "parentId": "0", "properties": {}, "paths": [], "options": []}',NULL,NULL,0,NULL,'/magic-api/function/09.租户账号/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ec23de1703b242bb8abd5c64ef0bacef',NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('dfa12930aadb466781b5bad533e4391a',NULL,'function','{\n  "properties": {},\n  "id": "c6d4f90ef64c535784d7f1df4030c92f",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "01.平台权限上下文",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/context",\n  "description": "从平台管理会话提取操作人、身份域、可管理应用和功能授权，供受保护接口建立统一的权限上下文。",\n  "parameters": [],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：01.平台权限上下文\n// 业务说明：从平台管理会话提取操作人、身份域、可管理应用和功能授权，供受保护接口建立统一的权限上下文。\n// 函数输入：无显式参数；从当前 Magic 执行上下文读取会话或请求信息。\n// 返回与副作用：从平台管理会话提取操作人、身份域、可管理应用和功能授权，供受保护接口建立统一的权限上下文。\nimport db;\nimport platformSession;\nimport request;\n\n// 平台会话与即时权限来源。仅查询baseline的IAM表，不查询行业账号或切换业务库。\nvar sql=db.normal();\nif(!platformSession.isLogin()) {\n    exit 401,\'请登录统一身份管理平台\';\n}\nvar operatorId=platformSession.id();\n// 仅bootstrap只读闭包启用请求内快照；普通读写接口每次仍重新校验。\nvar scope=request.get().getAttribute(\'idaas.bootstrap.permissionSnapshot\');\nvar copy=(value)=>({\n    userId:value.userId,account:value.account,permissions:value.permissions,pairs:value.pairs\n});\nif(scope!=null && scope.operatorId==operatorId && scope.context!=null) {\n    return copy(scope.context);\n}\nvar account=sql.selectOne("""\nselect o.*,o.tid as id,s.security_version\nfrom iam_operator_profile_v o\njoin iam_account_security_t s on s.principal_kind=\'OPERATOR\'\nand s.principal_id=o.tid\nwhere o.tid=#{operatorId}\n    and o.is_del=0\n    and o.status=\'ACTIVE\'\n""");\nif(account==null || platformSession.session().get(\'securityVersion\')!=account.security_version) {\n    platformSession.logout();\n    exit 401,\'平台账号或安全状态已变更，请重新登录\';\n}\nvar assignments=sql.select("""\nselect a.tid as id,a.role_id\nfrom iam_operator_role_rela_t a\njoin iam_role_t r on r.tid=a.role_id\nand r.is_del=0\nand r.status=\'ACTIVE\'\njoin iam_application_t app on app.tid=r.app_id\nand app.kind=\'INTERNAL\'\nand app.is_del=0\nand app.status=\'ACTIVE\'\nwhere a.operator_id=#{operatorId}\n    and a.status=\'ACTIVE\'\n    and a.valid_from<=utc_timestamp(6)\n    and (a.valid_until is null\n         or a.valid_until>utc_timestamp(6))\n""");\nvar permissions=[];\nvar pairs=[];\nvar assignmentIds=assignments.map(a=>a.id).distinct();\nvar roleIds=assignments.map(a=>a.role_id||a.roleId).distinct();\nvar codesByRole={};\nvar scopesByAssignment={};\nif(assignmentIds.size()>0) {\n    // 权限上下文按角色分配批量预取，不在每个 assignment 上查两次库。\n    var codeRows=sql.select("""\nselect rr.role_id,r.code\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.app_id=rr.app_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\nwhere rr.role_id in\n    <foreach collection="roleIds" item="roleId" open="(" close=")" separator=",">#{roleId}</foreach>\n""");\n    var scopeRows=sql.select("""\nselect *,tid as id\nfrom iam_operator_scope_t\nwhere assignment_id in\n    <foreach collection="assignmentIds" item="assignmentId" open="(" close=")" separator=",">#{assignmentId}</foreach>\n""");\n    for(row in codeRows) {\n        var roleId=\'\'+(row.role_id||row.roleId);\n        if(codesByRole[roleId]==null) { codesByRole[roleId]=[]; }\n        codesByRole[roleId].add(row.code);\n    }\n    for(row in scopeRows) {\n        var assignmentId=\'\'+(row.assignment_id||row.assignmentId);\n        if(scopesByAssignment[assignmentId]==null) { scopesByAssignment[assignmentId]=[]; }\n        scopesByAssignment[assignmentId].add(row);\n    }\n}\nfor(a in assignments) {\n    var codes=codesByRole[\'\'+(a.role_id||a.roleId)]||[];\n    var scopes=scopesByAssignment[\'\'+a.id]||[];\n    for(code in codes) {\n        if(!permissions.contains(code)) {\n            permissions.add(code);\n        }\n    }\n    pairs.add({\n        assignmentId:a.id,roleId:a.role_id,codes:codes,scopes:scopes\n    });\n}\nvar result={\n    userId:operatorId,account:account,permissions:permissions,pairs:pairs\n};\nif(scope!=null && scope.operatorId==operatorId) {\n    scope.context=result;\n    return copy(result);\n}\nreturn result;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/01.平台权限上下文.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('49a3a79b8a84449e8c0eb2dd68078acb',NULL,'function','{\n  "properties": {},\n  "id": "2bf4c74dcb665a279d05d04b96bf21ba",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "02.功能与对象范围校验",\n  "createTime": 1790612165860,\n  "updateTime": 1790946368174,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/guard",\n  "description": "按功能编码、应用和身份域校验操作人的权限及对象范围；越权时拒绝请求，成功时返回可用于后续查询的上下文。",\n  "parameters": [\n    {\n      "name": "permission",\n      "value": null,\n      "description": "待校验的功能权限编码",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：02.功能与对象范围校验\n// 业务说明：按功能编码、应用和身份域校验操作人的权限及对象范围；越权时拒绝请求，成功时返回可用于后续查询的上下文。\n// 函数输入：permission：待校验的功能权限编码；appId：目标业务应用标识；identityDomain：人员或公众身份域。\n// 返回与副作用：按功能编码、应用和身份域校验操作人的权限及对象范围；越权时拒绝请求，成功时返回可用于后续查询的上下文。\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/audit\' as audit;\n\n// 功能与范围必须来自同一角色分配，防止只读全域范围扩大局部写权限。\nvar ctx=context();\nvar domain=identityDomain||\'workforce\';\nif(![\'workforce\',\'public\'].contains(domain)) {\n    exit 400,\'身份域不正确\';\n}\nif(ctx.account.must_change_password==1) {\n    exit 403,\'请先在个人中心修改初始密码\';\n}\nfor(pair in ctx.pairs) {\n    if(!pair.codes.contains(permission)) {\n        continue;\n    }\n    for(scope in pair.scopes) {\n        if(scope.identity_domain!=domain) {\n            continue;\n        }\n        if(scope.scope_kind==\'ALL\' || (appId!=null && scope.scope_kind==\'APPLICATION\' && scope.app_id==appId)) {\n            ctx.requiredPermission=permission;\n            ctx.requiredAppId=appId;\n            ctx.requiredDomain=domain;\n            return ctx;\n        }\n    }\n}\naudit(ctx,\'DENIED\',permission,appId,\'SCOPE_OR_PERMISSION\',null);\nexit 403,\'当前平台账号无此功能或对象范围权限\';\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/02.功能与对象范围校验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('680e547a53bf4118ad8bada7a1770a42',NULL,'function','{\n  "properties": {},\n  "id": "6f5fe722a1bc5c7595107fbd4e6c7c1c",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "03.记录脱敏审计",\n  "createTime": 1790612165860,\n  "updateTime": 1790948254995,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/audit",\n  "description": "写入操作主体、对象、动作与结果，对请求摘要中的敏感字段脱敏，供多个写接口复用。",\n  "parameters": [\n    {\n      "name": "ctx",\n      "value": null,\n      "description": "已校验的操作上下文",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "result",\n      "value": null,\n      "description": "业务执行结果",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "action",\n      "value": null,\n      "description": "审计动作编码",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "objectId",\n      "value": null,\n      "description": "被操作对象标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "reason",\n      "value": null,\n      "description": "操作原因",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "summary",\n      "value": null,\n      "description": "脱敏后的审计摘要",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：03.记录脱敏审计\n// 业务说明：写入操作主体、对象、动作与结果，对请求摘要中的敏感字段脱敏，供多个写接口复用。\n// 函数输入：ctx：已校验的操作上下文；result：业务执行结果；action：审计动作编码；objectId：被操作对象标识；reason：操作原因；summary：脱敏后的审计摘要。\n// 返回与副作用：写入操作主体、对象、动作与结果，对请求摘要中的敏感字段脱敏，供多个写接口复用。\nimport db;\nimport request;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\n\n// 脱敏审计。调用方仅传入白名单摘要，严禁密码、密钥、令牌或请求原文。\nvar sql=db.normal();\nvar id=IdUtil.fastSimpleUUID();\nvar actor=ctx==null?null:ctx.userId;\nvar eventType=action.startsWith(\'auth:\')?\'AUTH\':action.startsWith(\'api:\')?\'API\':\'OPERATION\';\nvar snapshot=summary==null?null:JSONUtil.toJsonStr(summary);\nvar ip=request.getClientIP();\nvar actorKind=ctx==null?\'ANONYMOUS\':ctx.actorKind||\'OPERATOR\';\nvar domain=ctx==null?\'workforce\':ctx.requiredDomain||\'workforce\';\nsql.update("""\ninsert into iam_audit_event_t(tid,\n                event_type, identity_domain, actor_kind, actor_id, app_id, action, object_type, object_id,\n                result, reason_code, trace_id, ip, event_time, snapshot_json, created_time, updated_time)\nvalues(#{id},#{eventType},#{domain},#{actorKind},#{actor},null,#{action},\'IAM\',#{objectId},#{result},#{reason},#{id},#{ip},utc_timestamp(6),#{snapshot},utc_timestamp(6),utc_timestamp(6))\n""");\nreturn id;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/03.记录脱敏审计.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('36dd8ed7dadc443d8f2a598933c9ff79',NULL,'function','{\n  "properties": {},\n  "id": "cdebc557515854f7aff31170e0b6c630",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "04.幂等事务写入",\n  "createTime": 1790612165860,\n  "updateTime": 1790948852117,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/mutate",\n  "description": "将写操作、版本冲突处理、幂等键和审计封装在同一事务边界内，执行调用方提供的业务回调。",\n  "parameters": [\n    {\n      "name": "ctx",\n      "value": null,\n      "description": "已校验的操作上下文",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "callback",\n      "value": null,\n      "description": "在事务中执行的业务回调",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：04.幂等事务写入\n// 业务说明：将写操作、版本冲突处理、幂等键和审计封装在同一事务边界内，执行调用方提供的业务回调。\n// 函数输入：ctx：已校验的操作上下文；operation：本次执行的业务操作；payload：请求资料或筛选条件；callback：在事务中执行的业务回调。\n// 返回与副作用：将写操作、版本冲突处理、幂等键和审计封装在同一事务边界内，执行调用方提供的业务回调。\nimport identityTransport;\nimport db;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/context\' as context;\n\n// IAM同库事务：全局写入互斥用于首阶段权限/引用完整性，乐观版本、幂等、审计同事务。\nvar sql=db.normal();\nvar p=payload||{};\nif(p.requestId==null || !p.requestId.matches(\'[A-Za-z0-9_-]{8,64}\')) {\n    exit 400,\'请提供有效请求号\';\n}\nvar requestId=p.requestId;\nvar operatorId=ctx.userId;\nvar hash=identityTransport.protectedFingerprint(DigestUtil.sha256Hex(JSONUtil.toJsonStr(p)),\'receipt:v2\');\n// 把读取校验和状态写入放在同一事务，防止并发覆盖。\nvar output=sql.transaction(()=>{\n    // 单一小规模平台写入锁；角色变更与检查共享同一锁，阻止并发转授或清空最后授权入口。\n    sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=\'idaas-platform-internal\'\n    for update\n""");\n    var fresh=ctx.requiredPermission==null || ctx.requiredDirectory==true?context():guard(ctx.requiredPermission,ctx.requiredAppId,ctx.requiredDomain);\n    ctx.pairs=fresh.pairs;\n    ctx.permissions=fresh.permissions;\n    ctx.account=fresh.account;\n    var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_request_receipt_t\nwhere operator_id=#{operatorId}\n    and operation_code=#{operation}\n    and request_id=#{requestId}\n    for update\n""");\n    if(prior!=null) {\n        if(prior.request_hash!=hash) {\n            exit 409,\'相同请求号的内容不一致\';\n        }\n        return JSONUtil.parse(prior.result_json);\n    }\n    var result=callback();\n    var receiptId=IdUtil.fastSimpleUUID();\n    var encoded=JSONUtil.toJsonStr(result);\n    sql.update("""\ninsert into iam_request_receipt_t(tid,\n                operator_id, operation_code, request_id, request_hash, status, result_json)\nvalues(#{receiptId},#{operatorId},#{operation},#{requestId},#{hash},\'SUCCEEDED\',#{encoded})\n""");\n    return result;\n});\nreturn output;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/04.幂等事务写入.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('3684dfe27c9042f6aec310a10fd37bc1',NULL,'function','{\n  "properties": {},\n  "id": "f1b2b970b6195bf8aad27cdded34304d",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "05.读取平台会话",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/session",\n  "description": "核验平台令牌并读取当前操作账号与权限版本；只服务平台控制台身份，不接受租户本地会话。",\n  "parameters": [],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：05.读取平台会话\n// 业务说明：核验平台令牌并读取当前操作账号与权限版本；只服务平台控制台身份，不接受租户本地会话。\n// 函数输入：无显式参数；从当前 Magic 执行上下文读取会话或请求信息。\n// 返回与副作用：核验平台令牌并读取当前操作账号与权限版本；只服务平台控制台身份，不接受租户本地会话。\nimport db;\nimport platformSession;\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/directory-scope\' as directoryScope;\n\n// 基于当前平台会话重算身份域和功能范围，不读取租户本地账号。\nvar ctx=context();\nvar domain=platformSession.session().get(\'identityDomain\')||\'workforce\';\nvar permissions=[];\nfor(pair in ctx.pairs) {\n    if(pair.scopes.filter(s=>s.identity_domain==domain).size()>0) {\n        for(code in pair.codes) {\n            if(!permissions.contains(code)) {\n                permissions.add(code);\n            }\n        }\n    }\n}\nvar sql=db.normal();\n// 先读取控制库应用主档，再按同一角色分配的功能和范围筛选可见应用。\nvar apps=sql.select("""\nselect tid as id\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n""");\nvar allowed=[];\nvar writable=[];\nvar bindable=[];\nvar assignable=[];\nvar capabilities=[\'workspace\',\'profile\'];\nvar editable=[];\nvar appPermissions={};\nfor(a in apps) {\n    for(pair in ctx.pairs) {\n        for(s in pair.scopes) {\n            if(s.identity_domain==domain && (s.scope_kind==\'ALL\' || (s.scope_kind==\'APPLICATION\' && s.app_id==a.id))) {\n                if(!appPermissions.containsKey(a.id)) {\n                    appPermissions.put(a.id,[]);\n                }\n                for(code in pair.codes) {\n                    if(!appPermissions.get(a.id).contains(code)) {\n                        appPermissions.get(a.id).add(code);\n                    }\n                }\n                if(pair.codes.contains(\'apps:write\') && !writable.contains(a.id)) {\n                    writable.add(a.id);\n                }\n                if(pair.codes.contains(\'apps:bind\') && !bindable.contains(a.id)) {\n                    bindable.add(a.id);\n                }\n                if(pair.codes.contains(\'assignments:write\') && !assignable.contains(a.id)) {\n                    assignable.add(a.id);\n                }\n            }\n        }\n    }\n}\nfor(a in apps) {\n    for(pair in ctx.pairs) {\n        if(!pair.codes.contains(\'apps:read\')) {\n            continue;\n        }\n        for(s in pair.scopes) {\n            if(s.identity_domain==domain && (s.scope_kind==\'ALL\' || (s.scope_kind==\'APPLICATION\' && s.app_id==a.id))) {\n                if(!allowed.contains(a.id)) {\n                    allowed.add(a.id);\n                }\n            }\n        }\n    }\n}\nvar global=[];\nfor(pair in ctx.pairs) {\n    if(pair.scopes.filter(s=>s.identity_domain==domain && s.scope_kind==\'ALL\').size()>0) {\n        for(code in pair.codes) {\n            if(!global.contains(code)) {\n                global.add(code);\n            }\n        }\n    }\n}\nif(permissions.contains(\'apps:read\')) {\n    capabilities.add(\'apps\');\n}\nif(permissions.contains(\'users:read\')) {\n    capabilities.add(\'users\');\n}\nif(permissions.contains(\'orgs:read\')) {\n    capabilities.add(\'orgs\');\n}\nif(global.contains(\'directory:read\')) {\n    capabilities.add(\'org-settings\');\n}\nif(global.contains(\'operators:read\')) {\n    capabilities.add(\'delegates\');\n}\nif(permissions.contains(\'assignments:read\')) {\n    capabilities.add(\'assignments\');\n}\nif(permissions.contains(\'grants:read\')) {\n    capabilities.add(\'grants\');\n    capabilities.add(\'permission-groups\');\n}\nif(permissions.contains(\'roles:read\')) {\n    capabilities.add(\'roles\');\n}\nif(permissions.contains(\'resources:read\')) {\n    capabilities.add(\'resources\');\n}\nif(permissions.contains(\'clients:read\')) {\n    capabilities.add(\'clients\');\n}\nif(permissions.contains(\'sync:read\')) {\n    capabilities.add(\'provisioning\');\n}\nif(global.contains(\'public:read\')) {\n    capabilities.add(\'public-identity\');\n}\nif(global.contains(\'auth-accounts:read\')) {\n    capabilities.add(\'auth-accounts\');\n}\nif(global.contains(\'public:write\')) {\n    editable.add(\'legalEntities\');\n}\nif(global.contains(\'audit:read\')) {\n    capabilities.add(\'audit\');\n}\nif(global.contains(\'operators:read\') || global.contains(\'platform-roles:read\') || global.contains(\'settings:read\')) {\n    capabilities.add(\'system\');\n}\nif(permissions.contains(\'apps:write\')) {\n    editable.add(\'apps\');\n}\nif(global.contains(\'apps:write\')) {\n    editable.add(\'app-groups\');\n}\nif(global.contains(\'operators:write\') || global.contains(\'platform-roles:write\')) {\n    editable.add(\'system\');\n}\nif(permissions.contains(\'users:write\')) {\n    editable.add(\'users\');\n}\nif(permissions.contains(\'orgs:write\')) {\n    editable.add(\'orgs\');\n}\nif(global.contains(\'directory:write\')) {\n    editable.add(\'directory\');\n}\nif(permissions.contains(\'assignments:write\')) {\n    editable.add(\'assignments\');\n}\nfor(item in [{\n    code:\'roles:write\',table:\'roles\'\n},{\n    code:\'resources:write\',table:\'resources\'\n},{\n    code:\'grants:write\',table:\'grants\'\n},{\n    code:\'grants:write\',table:\'groups\'\n}]) {\n    if(permissions.contains(item.code)) {\n        editable.add(item.table);\n    }\n}\nif(permissions.contains(\'sync:write\')) {\n    editable.add(\'tasks\');\n}\n// 人员和机构目录权限分别求值，避免应用管理权限扩大共享目录范围。\nvar directoryRead=ctx.account.must_change_password==1 || !permissions.contains(\'users:read\')?{\n    all:false,orgIds:[]\n}\n:directoryScope(\'users:read\',domain);\nvar orgRead=ctx.account.must_change_password==1 || !permissions.contains(\'orgs:read\')?{\n    all:false,orgIds:[]\n}\n:directoryScope(\'orgs:read\',domain);\nvar visibleOrgIds=[];\nfor(id in directoryRead.orgIds) {\n    if(!visibleOrgIds.contains(id)) {\n        visibleOrgIds.add(id);\n    }\n}\nfor(id in orgRead.orgIds) {\n    if(!visibleOrgIds.contains(id)) {\n        visibleOrgIds.add(id);\n    }\n}\n// 统一控制台的只读菜单发现：每个身份域分别计算角色与范围的配对，不混入当前操作权限。\nvar navigationPermissions={};\nif(ctx.account.must_change_password!=1) {\n    for(identityDomain in [\'workforce\',\'public\']) {\n        var reads=[];\n        var globalReads=[];\n        var hasScope=false;\n        for(pair in ctx.pairs) {\n            var scopes=pair.scopes.filter(s=>s.identity_domain==identityDomain);\n            if(scopes.size()==0) {\n                continue;\n            }\n            hasScope=true;\n            for(code in pair.codes) {\n                if(!code.endsWith(\':read\')) {\n                    continue;\n                }\n                if(!reads.contains(code)) {\n                    reads.add(code);\n                }\n                if(scopes.filter(s=>s.scope_kind==\'ALL\').size()>0 && !globalReads.contains(code)) {\n                    globalReads.add(code);\n                }\n            }\n        }\n        if(hasScope) {\n            navigationPermissions.put(identityDomain,{\n                permissions:reads,globalPermissions:globalReads\n            });\n        }\n    }\n}\nif(ctx.account.must_change_password==1) {\n    capabilities=[\'workspace\',\'profile\'];\n    editable=[];\n    allowed=[];\n    writable=[];\n    bindable=[];\n    assignable=[];\n    global=[];\n}\nreturn {\n    userId:ctx.userId,username:ctx.account.username,name:ctx.account.display_name,realm:\'platform\',domain:domain,role:\'admin\',\n    permissions:permissions,globalPermissions:global,navigationPermissions:navigationPermissions,appPermissions:ctx.account.must_change_password==1?{}:appPermissions,appWriteIds:writable,appBindIds:bindable,appAssignableIds:assignable,\n    capabilities:capabilities,editableTables:editable,scopeMode:directoryRead.all || orgRead.all?\'tenant\':\'org\',allowedAppIds:allowed,orgIds:visibleOrgIds,\n    mustChangePassword:ctx.account.must_change_password==1,securityVersion:ctx.account.security_version,operatorVersion:ctx.account.version,subjectVersion:ctx.account.subject_version\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/05.读取平台会话.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('acb7457b556e4b42921a6511b446bec0',NULL,'function','{\n  "properties": {},\n  "id": "1e49d75e278f5e088ce49bc75ca81c15",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "06.应用共用业务规则",\n  "createTime": 1790612165860,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/applications",\n  "description": "维护应用登记、运行绑定与状态校验等多个接口复用的规则；将应用主档与租户本地数据分开。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：06.应用共用业务规则\n// 业务说明：维护应用登记、运行绑定与状态校验等多个接口复用的规则；将应用主档与租户本地数据分开。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：维护应用登记、运行绑定与状态校验等多个接口复用的规则；将应用主档与租户本地数据分开。\nimport db;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.core.util.NumberUtil;\nimport identityRuntime;\n\n// 应用主档、运行绑定与界面配置分开保存；界面配置由应用配置表维护。\n// 行业应用登记。修改IAM状态不修改运行租户，不直写应用库。\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\nvar target=operation==\'list\'?null:operation==\'inspect\'?p.appId:(r.id||null);\n// 详情分支：核验目标应用范围，汇总主档、绑定和配置的当前状态。\nif(operation==\'inspect\') {\n    guard(\'apps:bind\',target,\'workforce\');\n    var runtime=sql.selectOne("""\nselect runtime_tenant_id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n    if(runtime==null) {\n        exit 409,\'尚未登记运行租户\';\n    }\n    return identityRuntime.inspectTenantBinding(runtime.runtime_tenant_id);\n}\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    import \'@/idaas/session\' as sessionInfo;\n    var session=sessionInfo();\n    var ids=session.allowedAppIds;\n    if(ids.size()==0) {\n        guard(\'apps:read\',null,domain);\n        return [];\n    }\n    guard(\'apps:read\',ids[0],domain);\n    var configRows=sql.select("""\nselect app_id,config_code,config_value,value_type\nfrom iam_application_config_t\nwhere config_group=\'PORTAL\'\n    and is_del=0\n    and app_id in (#{ids})\n""");\n    return sql.select("""\nselect a.*,a.tid as id,date_format(a.created_time, \'%Y-%m-%dT%H:%i:%sZ\') as created_utc,\n       date_format(a.updated_time, \'%Y-%m-%dT%H:%i:%sZ\') as updated_utc,g.name as group_name,o.display_name as owner_name,rt.runtime_tenant_id,\n       date_format(rt.verified_time, \'%Y-%m-%dT%H:%i:%sZ\') as verified_utc,rt.binding_status,rt.local_permission_app_id,rt.backend_code,rt.environment\nfrom iam_application_t a\nleft join iam_application_group_t g on g.tid=a.group_id\nand g.is_del=0\nleft join iam_operator_profile_v o on o.tid=a.owner_operator_id\nand o.is_del=0\nleft join iam_application_runtime_t rt on rt.app_id=a.tid\nwhere a.kind=\'BUSINESS\'\n    and a.is_del=0\n    and a.tid in (#{ids})\norder by a.sort_no,a.code\n""").map(a=>{\n        var portal=JSONUtil.createObj();\n        for(config in configRows) {\n            if(config.app_id==a.id) {\n                portal.put(config.config_code,config.value_type==\'BOOLEAN\'?config.config_value==\'true\':config.config_value);\n            }\n        }\n        return {\n            id:a.id,domain:domain,name:a.name,code:a.code,status:a.status==\'ACTIVE\'?\'enabled\':a.status==\'DRAFT\'?\'pending\':\'disabled\',\n            createdAt:a.created_utc,updatedAt:a.updated_utc,version:a.version,sortNo:a.sort_no,group:a.group_name||\'未分组\',groupId:a.group_id,\n            description:a.description||\'\',homepage:a.homepage||\'\',owner:a.owner_name||\'\',ownerOperatorId:a.owner_operator_id,\n            protocol:a.auth_mode==\'FEDERATED\'?\'OIDC\':\'本地账号\',environment:a.environment||\'\',runtimeTenantId:a.runtime_tenant_id,bindingStatus:a.binding_status||\'PENDING\',\n            bindingVerifiedAt:a.verified_utc,localPermissionAppId:a.local_permission_app_id,authMode:a.auth_mode,provisioningMode:a.provisioning_mode,\n            redirectUris:\'\',logoutUri:\'\',clientId:\'\',clientType:\'public\',mfa:false,accessTtl:0,scopes:[],secretVersion:0,\n            logoUrl:portal.logo||\'\',portalConfig:portal\n        };\n    });\n}\n// 排序分支：只更新允许管理的应用展示顺序，不改变业务归属。\nif(operation==\'reorder\') {\n    // 先校验当前会话的功能权限、身份域和应用管理范围。\n    var ctx=guard(\'apps:write\',null,domain);\n    var ids=p.ids||[];\n    if(ids.size()<1 || ids.size()>200) {\n        exit 400,\'请提供当前身份域的应用顺序\';\n    }\n    // 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n    // 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,\'applications:reorder\',p,()=>{\n        var rows=sql.select("""\nselect tid as id\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\n    for update\n""");\n        if(rows.size()!=ids.size()) {\n            exit 409,\'应用清单已变化，请刷新后重新排序\';\n        }\n        var expected=rows.map(row=>row.id);\n        var seen=[];\n        for(id in ids) {\n            if(!expected.contains(id) || seen.contains(id)) {\n                exit 400,\'应用顺序包含重复或无效对象\';\n            }\n            seen.add(id);\n        }\n        var position=0;\n        for(id in ids) {\n            position=position+1;\n            var sortNo=position*10;\n            sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        audit(ctx,\'SUCCESS\',\'applications:reorder\',null,null,{\n            count:ids.size()\n        });\n        return {\n            ids:ids\n        };\n    });\n}\nvar permission=operation==\'bind\'?\'apps:bind\':\'apps:write\';\nvar ctx=guard(permission,p.creating==true?null:target,domain);\n// 保存分支：验证对象、版本和关联范围，再执行写入与审计。\nif(operation==\'save\' && r.sortPosition!=null) {\n    guard(\'apps:write\',null,domain);\n}\nvar inspection=null;\n// 绑定分支：检查目标运行租户与应用对应关系后保存绑定结果。\nif(operation==\'bind\') {\n    var tenantId=(p.runtimeTenantId||\'\').trim();\n    var localApp=(p.localPermissionAppId||\'\').trim();\n    if(localApp==\'\' || localApp.length()>64 || sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""")==null) {\n        exit 400,\'运行租户或本地权限应用标识不正确\';\n    }\n    inspection=identityRuntime.inspectTenantBinding(tenantId);\n    // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n    var permissionApp=identityRuntime.inTenant(tenantId,()=>db.normal().selectOne("""\nselect id\nfrom rm_menu_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\nlimit 1\n"""));\n    if(permissionApp==null) {\n        exit 400,\'本地权限应用未登记有效菜单，请核对标识\';\n    }\n}\nreturn mutate(ctx,\'applications:\'+operation,p,()=>{\n    var existing=target==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{target}\n    and is_del=0\n    for update\n""");\n    if(existing!=null && existing.kind!=\'BUSINESS\') {\n        exit 403,\'平台内部应用不在此维护\';\n    }\n    if(existing!=null && r.version!=existing.version) {\n        exit 409,\'应用已被修改，请刷新后重试\';\n    }\n    if(existing==null && p.creating!=true) {\n        exit 404,\'应用不存在\';\n    }\n    if(operation==\'bind\') {\n        var tenantId=(p.runtimeTenantId||\'\').trim();\n        var tid=sql.selectOne("""\nselect tid\nfrom sym_tenant_t\nwhere tid=#{tenantId}\n    and is_del=0\n    and status=1\n""");\n        if(tid==null) {\n            exit 400,\'运行租户不存在或已停用\';\n        }\n        var linked=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere runtime_tenant_id=#{tenantId}\n    and app_id<>#{target}\n""");\n        if(linked!=null) {\n            exit 409,\'该运行租户已绑定其他应用\';\n        }\n        var current=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n        if(current!=null && current.runtime_tenant_id!=tenantId) {\n            exit 409,\'已有绑定需要单独迁移，不能直接切换业务库\';\n        }\n        var rid=current==null?IdUtil.fastSimpleUUID():current.id;\n        var localApp=(p.localPermissionAppId||\'\').trim();\n        if(localApp==\'\' || localApp.length()>64) {\n            exit 400,\'请填写本地权限应用标识\';\n        }\n        if(current==null) {\n            sql.update("""\ninsert into iam_application_runtime_t(tid,\n                app_id, runtime_tenant_id, local_permission_app_id, binding_status, verified_time)\nvalues(#{rid},#{target},#{tenantId},#{localApp},\'VERIFIED\',utc_timestamp(6))\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_application_runtime_t\nset binding_status=\'VERIFIED\',local_permission_app_id=#{localApp}, verified_time=utc_timestamp(6),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{rid}\n""");\n        }\n        audit(ctx,\'SUCCESS\',\'applications:bind\',target,null,{\n            id:target\n        });\n        sql.update("""\nupdate iam_application_t\nset version=version+1,updated_time=utc_timestamp(6),updated_by=#{ctx.userId}\nwhere tid=#{target}\n""");\n        return {\n            id:target,bindingStatus:\'VERIFIED\',dataSourceKey:inspection.dataSourceKey,schema:inspection.schema\n        };\n    }\n    else if(operation==\'remove\') {\n        var binding=sql.selectOne("""\nselect tid as id\nfrom iam_application_runtime_t\nwhere app_id=#{target}\n""");\n        if(binding!=null) {\n            exit 409,\'应用仍有运行绑定，请使用停用而非删除\';\n        }\n        sql.update("""\nupdate iam_application_t\nset is_del=1,status=\'ARCHIVED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{target}\n""");\n    }\n    else if(operation==\'save\') {\n        var id=existing==null?IdUtil.fastSimpleUUID():existing.id;\n        var name=(r.name||\'\').trim();\n        var code=(r.code||\'\').trim();\n        var status=r.status==\'enabled\'?\'ACTIVE\':r.status==\'disabled\'?\'DISABLED\':\'DRAFT\';\n        var description=r.description||\'\';\n        var homepage=r.homepage||\'\';\n        if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_-]{1,63}\') || description.length()>1000\n        || (homepage!=\'\' && !homepage.matches(\'https?://[^\\\\s]+\'))) {\n            exit 400,\'请填写有效的应用名称、编码和首页\';\n        }\n        if(existing!=null && code!=existing.code) {\n            exit 400,\'应用编码登记后保持稳定\';\n        }\n        var duplicate=sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere code=#{code}\n    and tid<>#{id}\n""");\n        if(duplicate!=null) {\n            exit 409,\'应用编码已使用\';\n        }\n        var groupId=r.groupId||null;\n        if(r.group!=null && r.group!=\'未分组\') {\n            var group=sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere name=#{r.group}\n    and is_del=0\n""");\n            groupId=group==null?null:group.id;\n            if(groupId==null) {\n                exit 400,\'请先在应用分组中登记该分组\';\n            }\n        }\n        if(groupId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_application_group_t\nwhere tid=#{groupId}\n    and is_del=0\n""")==null) {\n            exit 400,\'应用分组不存在\';\n        }\n        var ownerId=r.ownerOperatorId||null;\n        if(r.owner!=null && r.owner!=\'\') {\n            var owners=sql.select("""\nselect tid as id\nfrom iam_operator_profile_v\nwhere display_name=#{r.owner}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(owners.size()!=1) {\n                exit 400,\'负责人必须对应唯一有效的平台操作账号\';\n            }\n            ownerId=owners[0].id;\n        }\n        if(ownerId!=null && sql.selectOne("""\nselect tid as id\nfrom iam_operator_t\nwhere tid=#{ownerId}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n            exit 400,\'负责人不存在或已停用\';\n        }\n        var portal=r.portalConfig;\n        if(portal!=null) {\n            var allowed=[\'logo\',\'systemName\',\'systemCode\',\'themeColor\',\'watermarkContent\',\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\',\'version\'];\n            for(key in portal.keySet()) {\n                if(!allowed.contains(key) || portal.get(key)==null) {\n                    exit 400,\'应用界面配置包含不支持的字段\';\n                }\n                var value=\'\'+portal.get(key);\n                if([\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)) {\n                    if(![\'true\',\'false\'].contains(value)) {\n                        exit 400,\'界面开关配置不正确\';\n                    }\n                }\n                else if(key==\'logo\') {\n                    if(value.length()>350000 || value!=\'\' && !value.matches(\'(?s)(https://[^\\\\s]+|data:image/(png|jpeg|webp|x-icon|svg\\\\+xml);base64,[A-Za-z0-9+/=]+)\')) {\n                        exit 400,\'应用标识须为HTTPS图片地址或支持的图片文件\';\n                    }\n                }\n                else if(key==\'themeColor\') {\n                    if(!value.matches(\'#[0-9a-fA-F]{6}\')) {\n                        exit 400,\'主题颜色须为六位十六进制颜色\';\n                    }\n                }\n                else if(key==\'systemCode\') {\n                    if(!value.matches(\'[A-Za-z0-9_一-龥-]{1,64}\')) {\n                        exit 400,\'租户系统代码不正确\';\n                    }\n                }\n                else if(value.length()>(key==\'systemName\'?100:key==\'watermarkContent\'?200:40)) {\n                    exit 400,\'应用界面配置长度超出限制\';\n                }\n            }\n        }\n        if(existing==null) {\n            sql.update("""\ninsert into iam_application_t(tid,\n                code, name, kind, group_id, description, owner_operator_id, homepage, identity_domains, status,\n                created_by, updated_by)\nvalues(#{id},#{code},#{name},\'BUSINESS\',#{groupId},#{description},#{ownerId},#{homepage},\'["workforce"]\',#{status},#{ctx.userId},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_application_t\nset name=#{name},group_id=#{groupId},description=#{description},\n    owner_operator_id=#{ownerId}, homepage=#{homepage},status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        target=id;\n        if(portal!=null) {\n            var saved=sql.select("""\nselect tid as id,config_code,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    for update\n""");\n            for(item in saved) {\n                var retained=false;\n                for(key in portal.keySet()) {\n                    if(key==item.config_code) {\n                        retained=true;\n                    }\n                }\n                if(!retained && item.is_del==0) {\n                    sql.update("""\nupdate iam_application_config_t\nset is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{item.id}\n""");\n                }\n            }\n            for(key in portal.keySet()) {\n                var value=\'\'+portal.get(key);\n                var valueType=[\'needLogin\',\'showShoppingCar\',\'showTagsView\',\'showWatermark\'].contains(key)?\'BOOLEAN\':\'STRING\';\n                var previous=sql.selectOne("""\nselect tid as id,config_value,value_type,is_del\nfrom iam_application_config_t\nwhere app_id=#{id}\n    and config_group=\'PORTAL\'\n    and config_code=#{key}\n    for update\n""");\n                if(previous==null) {\n                    var configId=IdUtil.fastSimpleUUID();\n                    sql.update("""\ninsert into iam_application_config_t(tid,\n                app_id, config_group, config_code, config_value, value_type, created_by, updated_by)\nvalues(#{configId},#{id},\'PORTAL\',#{key},#{value},#{valueType},#{ctx.userId},#{ctx.userId})\n""");\n                }\n                else if(previous.is_del!=0 || previous.config_value!=value || previous.value_type!=valueType) {\n                    sql.update("""\nupdate iam_application_config_t\nset config_value=#{value},value_type=#{valueType},is_del=0, version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{previous.id}\n""");\n                }\n            }\n        }\n        if(r.sortPosition!=null) {\n            if(!(\'\'+r.sortPosition).matches(\'[1-9][0-9]{0,2}\')) {\n                exit 400,\'显示位置格式不正确\';\n            }\n            var position=NumberUtil.parseInt(\'\'+r.sortPosition);\n            var ordered=sql.select("""\nselect tid as id,sort_no\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n    and json_contains(identity_domains, json_quote(#{domain}))\norder by sort_no,code\nfor update\n""");\n            if(position<1 || position>ordered.size() || position>200) {\n                exit 400,\'显示位置不在应用清单范围内\';\n            }\n            var next=[];\n            var index=1;\n            for(row in ordered) {\n                if(row.id!=id) {\n                    if(index==position) {\n                        next.add(id);\n                    }\n                    next.add(row.id);\n                    index=index+1;\n                }\n            }\n            if(next.size()<ordered.size()) {\n                next.add(id);\n            }\n            var rank=0;\n            for(appId in next) {\n                rank=rank+1;\n                var sortNo=rank*10;\n                var previous=ordered.filter(row=>row.id==appId)[0];\n                if(previous.sort_no!=sortNo) {\n                    sql.update("""\nupdate iam_application_t\nset sort_no=#{sortNo},version=version+1,updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{appId}\n""");\n                }\n            }\n        }\n    }\n    else {\n        exit 400,\'操作不正确\';\n    }\n    if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n        rebuild(target,\'workforce\');\n        rebuild(target,\'public\');\n    }\n    audit(ctx,\'SUCCESS\',\'applications:\'+operation,target,null,{\n        id:target\n    });\n    return {\n        id:target\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/06.应用共用业务规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9a4a133413a54a9794eb0bd734b9f65f',NULL,'function','{\n  "properties": {},\n  "id": "174d6987da7a505d88f618f165aaf3b1",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "07.平台策略共用规则",\n  "createTime": 1790612165860,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/settings",\n  "description": "按白名单读取或保存控制库平台配置，并执行类别、版本和敏感字段校验。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：07.平台策略共用规则\n// 业务说明：按白名单读取或保存控制库平台配置，并执行类别、版本和敏感字段校验。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：按白名单读取或保存控制库平台配置，并执行类别、版本和敏感字段校验。\nimport db;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport identityApi;\nimport cn.hutool.core.util.IdUtil;\n\nvar sql=db.normal();\nvar p=payload||{};\n// 先校验当前会话的功能权限、身份域和应用管理范围。\nvar ctx=guard(operation==\'read\'?\'settings:read\':\'settings:write\',null,\'workforce\');\n// 读取分支：按当前会话允许的范围返回策略或配置。\nif(operation==\'read\') {\n    var rows=sql.select("""\nselect tid as id,category,config_key,value_json,version\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n    and ((category=\'SECURITY\'\n          and config_key=\'password\')\n         or (category=\'BRANDING\'\n             and config_key=\'brand\')\n         or (category=\'API_ACCESS\'\n             and config_key=\'access\')\n         or (category=\'SSO\'\n             and config_key=\'session\'))\n""").map(r=>{\n        r.value=JSONUtil.parseObj(r.value_json);\n        r.value_json=null;\n        return r;\n    });\n    if(rows.filter(r=>r.category==\'SSO\').size()==0) {\n        rows.add({\n            id:\'global-sso-default\',category:\'SSO\',config_key:\'session\',version:null,value:{\n                accessTtl:600,refreshTtl:86400,idleMinutes:30,allowConcurrent:true\n            }\n        });\n    }\n    return rows;\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,\'settings:save\',p,()=>{\n    var category=p.category;\n    var key=p.configKey;\n    var values=p.values||{};\n    if(![\'SECURITY\',\'BRANDING\',\'API_ACCESS\',\'SSO\'].contains(category) || (category==\'SECURITY\' && key!=\'password\') || (category==\'BRANDING\' && key!=\'brand\') || (category==\'API_ACCESS\' && key!=\'access\') || (category==\'SSO\' && key!=\'session\')) {\n        exit 400,\'此策略尚未开通\';\n    }\n    var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=#{category}\n    and config_key=#{key}\n    and is_del=0\n    for update\n""");\n    if(old==null && p.version!=null || old!=null && old.version!=p.version) {\n        exit 409,\'配置已被修改，请刷新\';\n    }\n    var allowed=category==\'SECURITY\'?[\'minLength\',\'lockThreshold\',\'lockMinutes\',\'forceChange\',\'passwordBlacklist\',\'mfaRequired\']:category==\'API_ACCESS\'?[\'apiWhitelist\',\'ipBlacklist\',\'apiRateLimit\']:category==\'SSO\'?[\'accessTtl\',\'refreshTtl\',\'idleMinutes\',\'allowConcurrent\']:[\'title\',\'subtitle\',\'logoUrl\'];\n    for(k in values.keySet()) {\n        if(!allowed.contains(k)) {\n            exit 400,\'配置包含尚未开通的字段\';\n        }\n    }\n    if(category==\'SECURITY\') {\n        if(!(values.minLength instanceof Number) || !(values.lockThreshold instanceof Number) || !(values.lockMinutes instanceof Number)\n        || values.minLength.doubleValue()!=values.minLength.intValue() || values.lockThreshold.doubleValue()!=values.lockThreshold.intValue()\n        || values.lockMinutes.doubleValue()!=values.lockMinutes.intValue()) {\n            exit 400,\'安全策略数值须填写完整整数\';\n        }\n        if(values.minLength<8 || values.minLength>64 || values.lockThreshold<3 || values.lockThreshold>20 || values.lockMinutes<5 || values.lockMinutes>1440\n        || values.passwordBlacklist==null || values.passwordBlacklist.length()>10000 || ![true,false].contains(values.forceChange)) {\n            exit 400,\'安全策略范围不正确\';\n        }\n        if(values.mfaRequired==true && sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t o\nwhere o.status=\'ACTIVE\'\n    and o.is_del=0\n    and not exists\n        (select 1\n         from iam_credential_t c\n         where c.owner_kind=\'OPERATOR\'\n             and c.owner_id=o.tid\n             and c.credential_type=\'TOTP\'\n             and c.status=\'ACTIVE\')\n""").n>0) {\n            exit 409,\'请先为全部启用的平台操作账号绑定动态口令，再开启强制策略\';\n        }\n    }\n    else if(category==\'API_ACCESS\') {\n        if(!(values.apiRateLimit instanceof Number) || values.apiRateLimit.doubleValue()!=values.apiRateLimit.intValue() || values.apiRateLimit<1 || values.apiRateLimit>100000 || (values.apiWhitelist||\'\').length()>4000 || (values.ipBlacklist||\'\').length()>4000) {\n            exit 400,\'接口配额或来源规则不正确\';\n        }\n        for(list in [values.apiWhitelist||\'\',values.ipBlacklist||\'\']) {\n            for(rule in list.split(\'\\n\')) {\n                if(rule.trim()!=\'\') {\n                    try {\n                        identityApi.matchesAddress(rule.trim(),\'127.0.0.1\');\n                    }\n                    catch(e) {\n                        exit 400,\'接口来源须使用有效IP或CIDR\';\n                    }\n                }\n            }\n        }\n    }\n    else if(category==\'SSO\') {\n        for(k in [\'accessTtl\',\'refreshTtl\',\'idleMinutes\']) {\n            var value=values.get(k);\n            if(!(value instanceof Number) || value.doubleValue()!=value.intValue()) {\n                exit 400,\'会话有效期须为完整整数\';\n            }\n        }\n        if(values.accessTtl<60 || values.accessTtl>3600 || values.refreshTtl<values.accessTtl || values.refreshTtl>604800 || values.idleMinutes<5 || values.idleMinutes>30 || ![true,false].contains(values.allowConcurrent)) {\n            exit 400,\'会话策略范围不正确\';\n        }\n    }\n    else if(values.title==null || values.title.trim()==\'\' || values.title.length()>30 || (values.subtitle||\'\').length()>100\n    || ((values.logoUrl||\'\')!=\'\' && !values.logoUrl.matches(\'https://[^\\\\s]+\'))) {\n        exit 400,\'品牌配置不正确\';\n    }\n    var encoded=JSONUtil.toJsonStr(values);\n    if(old==null) {\n        var id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_setting_t(tid,\n                scope_kind, scope_key, category, config_key, value_json, status, created_by)\nvalues(#{id},\'GLOBAL\',\'global\',#{category},#{key},#{encoded},\'ACTIVE\',#{ctx.userId})\n""");\n        old={\n            id:id\n        };\n    }\n    else {\n        sql.update("""\nupdate iam_setting_t\nset value_json=#{encoded},version=version+1,updated_time=utc_timestamp(6),\n        updated_by=#{ctx.userId}\nwhere tid=#{old.id}\n""");\n    }\n    audit(ctx,\'SUCCESS\',\'settings:save\',old.id,null,{\n        category:category,key:key\n    });\n    return {\n        id:old.id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/07.平台策略共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('32c2cc94833d444cb8f46c3a10f0405a',NULL,'function','{\n  "properties": {},\n  "id": "d27a0bf45a1850a0bc5827cab4dc489f",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "08.校验密码策略",\n  "createTime": 1790612165860,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/password-policy",\n  "description": "复用密码长度、复杂度和禁用值校验；不存储明文密码。",\n  "parameters": [\n    {\n      "name": "password",\n      "value": null,\n      "description": "待校验的新密码",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：08.校验密码策略\n// 业务说明：复用密码长度、复杂度和禁用值校验；不存储明文密码。\n// 函数输入：password：待校验的新密码。\n// 返回与副作用：复用密码长度、复杂度和禁用值校验；不存储明文密码。\nimport db;\nimport cn.hutool.json.JSONUtil;\n\nvar sql=db.normal();\n// 读取可编辑的全局密码策略；未配置时采用受控的默认最短长度。\nvar row=sql.selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'SECURITY\'\n    and config_key=\'password\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\nvar policy=row==null?{}:JSONUtil.parseObj(row.value_json);\nvar min=policy.minLength||8;\nif(password==null || password.length()<min || password.length()>256) {\n    exit 400,\'新密码长度不符合平台策略\';\n}\n// 逐项比较弱密码禁用清单，不在此函数落库或记录明文。\nvar blacklist=(policy.passwordBlacklist||\'\').split(\'\\n\');\nfor(entry in blacklist) {\n    if(entry.trim()==password) {\n        exit 400,\'新密码属于禁止使用的弱密码\';\n    }\n}\nreturn policy;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/08.校验密码策略.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('75d94bf24e7142de89c7cabb9d9bc1fb',NULL,'function','{\n  "properties": {},\n  "id": "bf142250e1a35995a1041adb40ea5bf4",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "09.接口访问与审计封装",\n  "createTime": 1790612165860,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/api-call",\n  "description": "为多个平台接口统一校验请求来源、执行频率及调用审计，再执行调用方提供的业务回调。",\n  "parameters": [\n    {\n      "name": "callback",\n      "value": null,\n      "description": "在事务中执行的业务回调",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：09.接口访问与审计封装\n// 业务说明：为多个平台接口统一校验请求来源、执行频率及调用审计，再执行调用方提供的业务回调。\n// 函数输入：callback：在事务中执行的业务回调。\n// 返回与副作用：为多个平台接口统一校验请求来源、执行频率及调用审计，再执行调用方提供的业务回调。\nimport db;\nimport request;\nimport platformSession;\nimport authSession;\nimport identityApi;\nimport cn.hutool.json.JSONUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport java.lang.System;\nimport \'@/idaas/audit\' as audit;\n\n// 接口外层仅校验来源和频率，不保存请求正文、查询串或凭据；业务审计仍在写事务中完成。\nvar started=System.nanoTime();\nvar result=\'FAILED\';\nvar path=request.get().getRequestURI();\nvar method=request.get().getMethod();\ntry {\n    if(path.startsWith(\'/idaas/api/\')) {\n        var row=db.normal().selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere category=\'API_ACCESS\'\n    and config_key=\'access\'\n    and scope_key=\'global\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n        if(row!=null) {\n            var policy=JSONUtil.parseObj(row.value_json);\n            var address=identityApi.remoteAddress();\n            var deny=(policy.ipBlacklist||\'\').split(\'\\n\').filter(v=>v.trim()!=\'\');\n            var allow=(policy.apiWhitelist||\'\').split(\'\\n\').filter(v=>v.trim()!=\'\');\n            if(deny.filter(v=>identityApi.matchesAddress(v.trim(),address)).size()>0 || allow.size()>0 && allow.filter(v=>identityApi.matchesAddress(v.trim(),address)).size()==0) {\n                exit 403,\'接口来源不在允许范围\';\n            }\n            if(!identityApi.withinRate(DigestUtil.sha256Hex(address),policy.apiRateLimit)) {\n                exit 429,\'接口请求超过当前配额\';\n            }\n        }\n    }\n    var response=callback();\n    result=\'SUCCESS\';\n    return response;\n}\nfinally {\n    var ctx=platformSession.isLogin()?{\n        userId:platformSession.id()\n    }\n    :null;\n    if(ctx==null && authSession.isLogin()) {\n        var account=db.normal().selectOne("""\nselect identity_domain\nfrom iam_auth_account_t\nwhere tid=#{authSession.id()}\n""");\n        ctx={\n            userId:authSession.id(),actorKind:\'AUTH_ACCOUNT\',requiredDomain:account==null?\'public\':account.identity_domain\n        };\n    }\n    var id=audit(ctx,result,\'api:\'+path,null,result==\'SUCCESS\'?null:\'REQUEST_FAILED\',null);\n    var duration=(System.nanoTime()-started)/1000000;\n    var status=result==\'SUCCESS\'?200:null;\n    db.normal().update("""\nupdate iam_audit_event_t\nset request_path=#{path},http_method=#{method},http_status=#{status},\n    duration_ms=#{duration}\nwhere tid=#{id}\n""");\n}\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/09.接口访问与审计封装.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a201fc3780574dbdbdb7d331e6252c4e',NULL,'function','{\n  "properties": {},\n  "id": "bc768b6b6b405a21bc42cd88f24e4a54",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "10.中央资料范围校验",\n  "createTime": 1790615423659,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/directory-scope",\n  "description": "校验中央人员、机构和应用分配的可见及可写范围，防止跨身份域或跨应用操作。",\n  "parameters": [\n    {\n      "name": "permission",\n      "value": null,\n      "description": "待校验的功能权限编码",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：10.中央资料范围校验\n// 业务说明：校验中央人员、机构和应用分配的可见及可写范围，防止跨身份域或跨应用操作。\n// 函数输入：permission：待校验的功能权限编码；identityDomain：人员或公众身份域。\n// 返回与副作用：校验中央人员、机构和应用分配的可见及可写范围，防止跨身份域或跨应用操作。\nimport db;\nimport \'@/idaas/context\' as context;\n\n// 中央资料范围与应用范围分开。应用范围不能修改共用人员或机构。\nvar ctx=context();\nvar domain=identityDomain||\'workforce\';\nvar sql=db.normal();\nif(![\'workforce\',\'public\'].contains(domain)) {\n    exit 400,\'身份域不正确\';\n}\nif(ctx.account.must_change_password==1) {\n    exit 403,\'请先修改初始密码\';\n}\nvar all=false;\nvar roots=[];\nvar orgIds=[];\nfor(pair in ctx.pairs) {\n    if(!pair.codes.contains(permission)) {\n        continue;\n    }\n    for(s in pair.scopes) {\n        if(s.identity_domain!=domain) {\n            continue;\n        }\n        if(s.scope_kind==\'ALL\') {\n            all=true;\n        }\n        if(s.scope_kind==\'ORG\' && s.app_id==null) {\n            roots.add(s);\n        }\n    }\n}\nif(!all && roots.size()>0) {\n    var rootIds=roots.map(scope=>scope.org_id).distinct();\n    var childRootIds=roots.filter(scope=>scope.include_children==1).map(scope=>scope.org_id).distinct();\n    if(rootIds.size()>500) {\n        exit 400,\'机构管理范围超过批量上限\';\n    }\n    if(childRootIds.size()==0) {\n        childRootIds=[\'__none__\'];\n    }\n    var orgs=sql.select("""\nselect distinct o.tid as id\nfrom iam_org_t o\nwhere o.identity_domain=#{domain} and o.is_del=0\n  and exists (\n    select 1 from iam_org_t root\n    where root.tid in\n      <foreach collection="rootIds" item="rootId" open="(" close=")" separator=",">#{rootId}</foreach>\n      and root.identity_domain=#{domain} and root.is_del=0 and root.status=\'ACTIVE\'\n      and (o.tid=root.tid or (root.tid in\n        <foreach collection="childRootIds" item="rootId" open="(" close=")" separator=",">#{rootId}</foreach>\n        and o.path like concat(root.path,\'%\')))\n  )\n""");\n    orgIds=orgs.map(org=>org.id);\n}\nctx.requiredDirectory=true;\nctx.requiredPermission=permission;\nctx.requiredDomain=domain;\nreturn {\n    ctx:ctx,all:all,orgIds:orgIds\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/10.中央资料范围校验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('09c9b7e3fb6c4c3abfdf3a0a7ee5977f',NULL,'function','{\n  "properties": {},\n  "id": "6b934eef4c6756029a274852f9b15424",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "11.中央人员机构共用规则",\n  "createTime": 1790615423659,\n  "updateTime": 1791213392140,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/directory",\n  "description": "封装多处使用的人员、机构和任职资料校验与映射，保持中央目录与租户本地账号隔离。",\n  "parameters": [\n    {\n      "name": "entity",\n      "value": null,\n      "description": "中央目录对象类别",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：11.中央人员机构共用规则\n// 业务说明：封装多处使用的人员、机构和任职资料校验与映射，保持中央目录与租户本地账号隔离。\n// 函数输入：entity：中央目录对象类别；operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：封装多处使用的人员、机构和任职资料校验与映射，保持中央目录与租户本地账号隔离。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Long;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport \'@/idaas/directory-scope\' as directoryScope;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\n\n// 结构化中央人员、机构、任职。全部写入同库事务，绝不创建应用本地凭据。\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\nvar sql=db.normal();\nif(![\'subjects\',\'orgs\'].contains(entity)) {\n    exit 400,\'目录对象不正确\';\n}\nvar permission=(entity==\'subjects\'?\'users\':\'orgs\')+\':\'+(operation==\'list\'?\'read\':\'write\');\nvar rights=directoryScope(permission,domain);\nvar ctx=rights.ctx;\nvar extensionViews={};\nvar appointmentsBySubject={};\nvar profilesBySubject={};\nvar allowed=(ids,scope)=>scope.all || (ids.size()>0 && ids.filter(id=>!scope.orgIds.contains(id)).size()==0);\nvar appointments=(id)=>sql.select("""\nselect a.*,a.tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\')\nfrom iam_appointment_t a\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\norder by is_primary desc,tid\n""");\nvar dto=(row)=>{\n    if(entity==\'orgs\') {\n        return {\n            id:row.id,domain:row.identity_domain,code:row.code,name:row.name,parentId:row.parent_id,sortNo:row.sort_no,leader:row.leader_subject_id||\'\',line:row.line_code||\'\',status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,createdAt:row.created_utc,updatedAt:row.updated_utc,path:row.path,depth:row.depth,ext:extensionViews.get(row.id)||{}\n        };\n    }\n    var profile=profilesBySubject.get(row.id);\n    var verified=profile!=null && profile.verification_status==\'VERIFIED\' && profile.result_status==\'VERIFIED\' && profile.fresh==1;\n    var jobs=appointmentsBySubject.get(row.id)||[];\n    var primary=jobs.filter(a=>a.is_primary==1);\n    var main=primary.size()==0?null:primary[0];\n    return {\n        id:row.id,domain:row.identity_domain,name:row.name,subjectCode:row.subject_code,account:row.account_hint||\'\',email:row.email||\'\',phone:row.phone||\'\',employeeId:row.employee_no||\'\',employmentType:(row.employment_type||\'EMPLOYEE\').toLowerCase(),joinDate:row.join_date==null?\'\':row.join_date.toString(),status:row.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:row.version,\n        createdAt:row.created_utc,updatedAt:row.updated_utc,orgId:main==null?\'\':main.org_id,orgName:main==null?\'\':main.org_name||\'\',post:main==null?\'\':main.post_code||\'\',kind:row.identity_domain==\'public\'?\'citizen\':\'person\',locked:false,verified:verified,verificationStatus:profile==null?\'UNVERIFIED\':profile.verification_status==\'VERIFIED\' && !verified?\'EXPIRED\':profile.verification_status,history:[],\n        appointments:jobs.map(a=>({\n            id:a.id,orgId:a.org_id,post:a.post_code||\'\',position:a.position_code||\'\',rank:a.rank_code||\'\',title:a.title_code||\'\',primary:a.is_primary==1,version:a.version\n        })),ext:extensionViews.get(row.id)||{}\n    };\n};\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    var q=(p.q||\'\').trim();\n    if(q.length()>100) {\n        exit 400,\'查询文字过长\';\n    }\n    var pageText=\'\'+(p.page||\'1\');\n    var sizeText=\'\'+(p.size||\'250\');\n    if(!pageText.matches(\'[0-9]{1,5}\') || !sizeText.matches(\'[0-9]{1,4}\')) {\n        exit 400,\'分页参数不正确\';\n    }\n    var page=Long.parseLong(pageText);\n    var size=Long.parseLong(sizeText);\n    if(page<1 || size<1 || size>250) {\n        exit 400,\'分页参数不正确\';\n    }\n    var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n    var keyword=\'%\'+q+\'%\';\n    var requestedStatus=p.status||\'all\';\n    if(![\'all\',\'enabled\',\'disabled\'].contains(requestedStatus)) {\n        exit 400,\'状态筛选不正确\';\n    }\n    var wantedStatus=requestedStatus==\'enabled\'?\'ACTIVE\':requestedStatus==\'disabled\'?\'DISABLED\':\'ALL\';\n    var requestedOrgId=entity==\'subjects\' && p.orgId!=null && p.orgId!=\'all\'?\'\'+p.orgId:\'\';\n    if(requestedOrgId.length()>64) {\n        exit 400,\'机构筛选不正确\';\n    }\n    var includeChildren=p.includeChildren==true || p.includeChildren==\'true\'?1:0;\n    var requestedOrgPath=\'__none__\';\n    if(requestedOrgId!=\'\' && includeChildren==1) {\n        var requestedOrg=sql.selectOne("""\nselect path from iam_org_t\nwhere tid=#{requestedOrgId} and identity_domain=#{domain} and is_del=0\n""");\n        if(requestedOrg!=null) {\n            requestedOrgPath=requestedOrg.path;\n        }\n    }\n    var offset=(page-1)*size;\n    var allScope=rights.all?1:0;\n    var scopeIds=rights.orgIds.size()>0?rights.orgIds:[\'__none__\'];\n    // Apply the same domain and organization scope to count and page queries.\n    // A person is visible when an active appointment belongs to this scope.\n    var filter=entity==\'orgs\'?"""\nfrom iam_org_t t\nwhere t.identity_domain=#{domain} and t.is_del=0 and t.name like #{keyword}\n  and (#{wantedStatus}=\'ALL\' or t.status=#{wantedStatus})\n  and (#{allScope}=1 or t.tid in\n    <foreach collection="scopeIds" item="scopeId" open="(" close=")" separator=",">#{scopeId}</foreach>)\n""":"""\nfrom iam_subject_t t\nwhere t.identity_domain=#{domain} and t.is_del=0\n  and (t.name like #{keyword} or t.account_hint like #{keyword} or t.email like #{keyword})\n  and (#{wantedStatus}=\'ALL\' or t.status=#{wantedStatus})\n  and (#{requestedOrgId}=\'\' or exists (\n    select 1 from iam_appointment_t filterJob\n    join iam_org_t filterOrg on filterOrg.tid=filterJob.org_id\n    where filterJob.subject_id=t.tid and filterJob.is_del=0 and filterJob.status=\'ACTIVE\'\n      and filterJob.valid_from<=utc_timestamp(6)\n      and (filterJob.valid_until is null or filterJob.valid_until>utc_timestamp(6))\n      and (filterJob.org_id=#{requestedOrgId} or\n        (#{includeChildren}=1 and filterOrg.path like concat(#{requestedOrgPath},\'%\')))\n  ))\n  and (#{allScope}=1 or exists (\n    select 1 from iam_appointment_t a\n    where a.subject_id=t.tid and a.is_del=0 and a.status=\'ACTIVE\'\n      and a.valid_from<=utc_timestamp(6)\n      and (a.valid_until is null or a.valid_until>utc_timestamp(6))\n      and a.org_id in\n        <foreach collection="scopeIds" item="scopeId" open="(" close=")" separator=",">#{scopeId}</foreach>\n  ))\n""";\n    var total=sql.selectOne(\'select count(*) as total \'+filter).total;\n    var list=sql.select("""\nselect t.*,t.tid as id,\n       date_format(t.created_time,\'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(t.updated_time,\'%Y-%m-%dT%H:%i:%sZ\') updated_utc\n"""+filter+(entity==\'orgs\'?" order by t.sort_no,t.tid":" order by t.tid")+" limit #{size} offset #{offset}");\n    if(entity==\'subjects\' && list.size()>0) {\n        var subjectIds=list.map(row=>row.id);\n        var jobs=sql.select("""\nselect a.*,a.tid as id,o.name org_name\nfrom iam_appointment_t a\nleft join iam_org_t o on o.tid=a.org_id\nwhere a.subject_id in\n    <foreach collection="subjectIds" item="subjectId" open="(" close=")" separator=",">#{subjectId}</foreach>\n  and a.is_del=0 and a.status=\'ACTIVE\'\n  and a.valid_from<=utc_timestamp(6)\n  and (a.valid_until is null or a.valid_until>utc_timestamp(6))\norder by a.subject_id,a.is_primary desc,a.tid\n""");\n        for(job in jobs) {\n            var current=appointmentsBySubject.get(job.subject_id)||[];\n            current.add(job);\n            appointmentsBySubject.put(job.subject_id,current);\n        }\n        if(domain==\'public\') {\n            var profiles=sql.select("""\nselect p.subject_id,p.verification_status,p.verification_id,\n       v.status result_status,v.expires_at>utc_timestamp(6) fresh\nfrom iam_public_profile_t p\nleft join iam_verification_t v on v.tid=p.verification_id\nwhere p.subject_id in\n    <foreach collection="subjectIds" item="subjectId" open="(" close=")" separator=",">#{subjectId}</foreach>\n""");\n            for(profile in profiles) {\n                profilesBySubject.put(profile.subject_id,profile);\n            }\n        }\n    }\n    if(list.size()>0) {\n        extensionViews=fieldValues(\'view-many\',entity==\'orgs\'?\'ORG\':\'SUBJECT\',domain,null,list.map(row=>({\n            id:row.id,values:row.ext_json==null?{}:JSONUtil.parseObj(row.ext_json)\n        })),null);\n    }\n    return {\n        list:list.map(dto),total:total,page:page,size:size\n    };\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,entity+\':\'+operation,p,()=>{\n    var fresh=directoryScope(permission,domain);\n    var id=r.id||p.id;\n    var table=entity==\'subjects\'?\'iam_subject_t\':\'iam_org_t\';\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n    if(old==null && p.creating!=true) {\n        exit 404,\'目录记录不存在\';\n    }\n    if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n        exit 409,\'目录记录身份域或版本已变更\';\n    }\n    var originalOrgs=old==null?[]:entity==\'orgs\'?[id]:appointments(id).map(a=>a.org_id);\n    if(old!=null && !allowed(originalOrgs,fresh)) {\n        exit 403,\'记录超出中央资料管理范围\';\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\') {\n        if(entity==\'orgs\') {\n            if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere org_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_app_org_t\nwhere org_id=#{id}\n    and status=\'ACTIVE\'\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_scope_t\nwhere org_id=#{id}\n""").n>0) {\n                exit 409,\'机构仍有下级、任职、分配或管理范围引用\';\n            }\n        }\n        else {\n            if(sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere leader_subject_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_operator_t\nwhere subject_id=#{id}\n    and is_del=0\n""").n>0) {\n                exit 409,\'人员仍被负责人或平台账号引用\';\n            }\n            sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n            sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=0,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n        }\n        sql.update(\'update \'+table+" set status=\'ARCHIVED\',is_del=1,version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6) where tid=#{id}");\n        if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n            rebuild(null,domain);\n        }\n        audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    if(operation!=\'save\') {\n        exit 400,\'目录操作不正确\';\n    }\n    var name=(r.name||\'\').trim();\n    var status=r.status==\'disabled\' || r.status==\'DISABLED\'?\'DISABLED\':\'ACTIVE\';\n    if(name==\'\' || name.length()>(entity==\'subjects\'?100:200)) {\n        exit 400,\'名称不正确\';\n    }\n    if(entity==\'orgs\') {\n        var parentId=r.parentId||null;\n        var parent=parentId==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_org_t\nwhere tid=#{parentId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n        if(parentId!=null && parent==null) {\n            exit 400,\'上级机构不存在、停用或跨域\';\n        }\n        if((parentId!=null && parentId==id) || (old!=null && parent!=null && parent.path.startsWith(old.path))) {\n            exit 400,\'机构不能移入自身或下级\';\n        }\n        if((old==null || parentId!=old.parent_id) && !allowed(parent==null?[]:[parent.id],fresh)) {\n            exit 403,\'上级机构超出管理范围\';\n        }\n        var code=(r.code||\'\').trim();\n        if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,99}\')) {\n            exit 400,\'机构编码不正确\';\n        }\n        if(old!=null && code!=old.code) {\n            exit 400,\'机构编码保持稳定\';\n        }\n        if(old==null && sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and code=#{code}\n""")!=null) {\n            exit 409,\'机构编码已使用\';\n        }\n        var leader=r.leader||null;\n        var line=r.line||null;\n        if(leader!=null && sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{leader}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n            exit 400,\'负责人须为同域有效人员\';\n        }\n        if(line!=null && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=\'LINE\'\n    and code=#{line}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n            exit 400,\'条线须选择有效字典\';\n        }\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n        }\n        var path=(parent==null?\'/\':parent.path)+id+\'/\';\n        var depth=parent==null?0:parent.depth+1;\n        if(path.length()>2000 || depth>50) {\n            exit 400,\'机构层级超限\';\n        }\n        if(old!=null) {\n            var children=sql.select("""\nselect tid as id,path\nfrom iam_org_t\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n            if(!fresh.all && children.filter(o=>!fresh.orgIds.contains(o.id)).size()>0) {\n                exit 403,\'移动机构涉及超出范围的下级\';\n            }\n            for(child in children) {\n                var newPath=path+child.path.substring(old.path.length());\n                if(newPath.length()>2000) {\n                    exit 400,\'下级机构路径超限\';\n                }\n            }\n            sql.update("""\nupdate iam_org_t\nset path=concat(#{path}, substring(path,\n        length(#{old.path})+1)),depth=depth+#{depth}-#{old.depth},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere path like concat(#{old.path}, \'%\')\n    and tid<>#{id}\n    and is_del=0\n""");\n            sql.update("""\nupdate iam_org_t\nset name=#{name},parent_id=#{parentId},path=#{path},depth=#{depth},\n        leader_subject_id=#{leader},line_code=#{line},\n        status=#{status},version=version+1,\n        updated_by=#{ctx.userId},\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        else {\n            sql.update("""\ninsert into iam_org_t(tid,\n                identity_domain, code, name, parent_id, path, depth, leader_subject_id, line_code, status,\n                created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{name},#{parentId},#{path},#{depth},#{leader},#{line},#{status},#{ctx.userId},#{ctx.userId})\n""");\n        }\n    }\n    else {\n        var jobs=r.appointments||[];\n        if(jobs.size()>30) {\n            exit 400,\'任职数量过多\';\n        }\n        var primary=jobs.filter(a=>a.primary==true);\n        if(jobs.size()>0 && primary.size()!=1) {\n            exit 400,\'任职必须且只能有一个主职\';\n        }\n        var orgIds=[];\n        var checked=[];\n        for(a in jobs) {\n            var org=sql.selectOne("""\nselect tid as id\nfrom iam_org_t\nwhere tid=#{a.orgId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n            if(org==null || orgIds.contains(a.orgId)) {\n                exit 400,\'任职机构无效、跨域或重复\';\n            }\n            orgIds.add(a.orgId);\n            for(kind in [\'POST\',\'POSITION\',\'RANK\',\'TITLE\']) {\n                var value=kind==\'POST\'?a.post:kind==\'POSITION\'?a.position:kind==\'RANK\'?a.rank:a.title;\n                if(value!=null && value!=\'\' && sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{kind}\n    and code=#{value}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                    exit 400,\'岗位职务须使用有效字典编码\';\n                }\n            }\n            checked.add(a);\n        }\n        if(!allowed(orgIds,fresh)) {\n            exit 403,\'拟任职机构超出中央资料管理范围\';\n        }\n        var hint=(r.account||\'\').trim();\n        if(hint.length()>100 || (hint!=\'\' && !hint.matches(\'[A-Za-z][A-Za-z0-9_.-]{2,99}\'))) {\n            exit 400,\'拟用账号不正确\';\n        }\n        var code=old==null?(r.subjectCode||\'SUB_\'+IdUtil.fastSimpleUUID()):old.subject_code;\n        if(!code.matches(\'[A-Za-z0-9][A-Za-z0-9_.-]{1,63}\')) {\n            exit 400,\'人员编号不正确\';\n        }\n        var phone=r.phone||null;\n        var email=r.email||null;\n        var employee=r.employeeId||null;\n        var employment=(r.employmentType||\'employee\').toUpperCase();\n        var join=r.joinDate||null;\n        if((phone!=null && phone.length()>256) || (email!=null && email.length()>512) || (employee!=null && employee.length()>100) || ![\'EMPLOYEE\',\'PARTNER\',\'TEMPORARY\'].contains(employment)) {\n            exit 400,\'人员资料不正确\';\n        }\n        try {\n            if(join!=null) {\n                LocalDate.parse(join);\n            }\n        }\n        catch(e) {\n            exit 400,\'入职日期不正确\';\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and subject_code=#{code}\n""")!=null) {\n                exit 409,\'人员编号已使用\';\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_subject_t(tid,\n                identity_domain, subject_code, account_hint, name, phone, email, employee_no, employment_type,\n                join_date, status, created_by, updated_by)\nvalues(#{id},#{domain},#{code},#{hint},#{name},#{phone},#{email},#{employee},#{employment},#{join},#{status},#{ctx.userId},#{ctx.userId})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_subject_t\nset name=#{name},account_hint=#{hint},phone=#{phone},email=#{email},\n    employee_no=#{employee},employment_type=#{employment},join_date=#{join},status=#{status},\n    version=version+1,updated_by=#{ctx.userId},updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        if(domain==\'public\' && old!=null && old.name!=name && sql.selectOne("""\nselect table_name\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_public_profile_t\'\n""")!=null) {\n            sql.update("""\nupdate iam_public_profile_t\nset verification_status=\'UNVERIFIED\',verification_id=null,verified_time=null,version=version+1\nwhere subject_id=#{id}\n""");\n        }\n        var current=sql.select("""\nselect *,tid as id\nfrom iam_appointment_t\nwhere subject_id=#{id}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n        sql.update("""\nupdate iam_appointment_t\nset status=\'ENDED\',version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n    and status=\'ACTIVE\'\n""");\n        for(a in checked) {\n            var prior=current.filter(j=>j.org_id==a.orgId && (j.post_code||\'\')==(a.post||\'\') && (j.position_code||\'\')==(a.position||\'\') && (j.rank_code||\'\')==(a.rank||\'\') && (j.title_code||\'\')==(a.title||\'\'));\n            var aid=prior.size()>0?prior[0].id:IdUtil.fastSimpleUUID();\n            var isPrimary=a.primary==true?1:0;\n            if(prior.size()>0) {\n                sql.update("""\nupdate iam_appointment_t\nset status=\'ACTIVE\',is_primary=#{isPrimary},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{aid}\n""");\n            }\n            else {\n                sql.update("""\ninsert into iam_appointment_t(tid,\n                subject_id, org_id, post_code, position_code, rank_code, title_code, is_primary, status,\n                valid_from)\nvalues(#{aid},#{id},#{a.orgId},#{a.post},#{a.position},#{a.rank},#{a.title},#{isPrimary},\'ACTIVE\',utc_timestamp(6))\n""");\n            }\n        }\n        sql.update("""\nupdate iam_subject_app_t\nset desired_enabled=case\n        when #{status}=\'ACTIVE\'\n        and assignment_mode=\'GRANT_DERIVED\' then 1 else 0\n                    end,desired_version=desired_version+1,version=version+1,\n        updated_time=utc_timestamp(6)\nwhere subject_id=#{id}\n""");\n    }\n    var ext=fieldValues(\'encode\',entity==\'subjects\'?\'SUBJECT\':\'ORG\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json));\n    var encoded=JSONUtil.toJsonStr(ext);\n    sql.update(\'update \'+table+\' set ext_json=#{encoded} where tid=#{id}\');\n    if(sql.selectOne("""\nselect count(*) n\nfrom information_schema.tables\nwhere table_schema=database()\n    and table_name=\'iam_access_grant_t\'\n""").n>0) {\n        rebuild(null,domain);\n    }\n    audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n        id:id,status:status\n    });\n    var saved=sql.selectOne(\'select version from \'+table+\' where tid=#{id}\');\n    return {\n        id:id,version:saved.version\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/11.中央人员机构共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('96302c89f4b04876b5d23b6e2fcc7207',NULL,'function','{\n  "properties": {},\n  "id": "a8dfc37607b15248b4f91cadbde81ebb",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "12.目录配置共用规则",\n  "createTime": 1790615423659,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/directory-config",\n  "description": "校验字典与扩展字段的允许范围、类型和版本，供目录管理接口共用。",\n  "parameters": [\n    {\n      "name": "entity",\n      "value": null,\n      "description": "中央目录对象类别",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：12.目录配置共用规则\n// 业务说明：校验字典与扩展字段的允许范围、类型和版本，供目录管理接口共用。\n// 函数输入：entity：中央目录对象类别；operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：校验字典与扩展字段的允许范围、类型和版本，供目录管理接口共用。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.Double;\nimport java.lang.String;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\n\n// 字典、扩展定义只接受明确列和白名单类型，不允许任意表名、SQL或凭据字段。\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\nif(![\'dictionaries\',\'field-definitions\'].contains(entity)) {\n    exit 400,\'配置类型不正确\';\n}\n// 先校验当前会话的功能权限、身份域和应用管理范围。\nvar ctx=guard(operation==\'list\'?\'directory:read\':\'directory:write\',null,domain);\nvar fields=entity==\'field-definitions\';\nvar table=fields?\'iam_field_definition_t\':\'iam_dict_item_t\';\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    var rows=sql.select(\'select *,tid as id,date_format(created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+\' where identity_domain=#{domain} and is_del=0 order by tid\');\n    return rows.map(x=>({\n        id:x.id,domain:x.identity_domain,name:fields?x.label:x.name,code:fields?x.field_key:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,category:fields?\'extension\':x.category==\'LINE\'?\'line\':\'dictionary\',value:fields?x.value_type:x.category,parentId:fields?\'\':x.parent_id||\'\',subjectType:fields?x.entity_type:\'\',required:fields?x.required_flag==1:false,sensitive:fields?x.sensitive_flag==1:false,validation:fields && x.validation_json!=null?JSONUtil.parseObj(x.validation_json):{},description:\'\',permissions:[],memberIds:[],appId:\'\',orgId:\'\',userId:\'\',expiresAt:\'\'\n    }));\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,entity+\':\'+operation,p,()=>{\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n    if(old==null && p.creating!=true) {\n        exit 404,\'配置不存在\';\n    }\n    if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n        exit 409,\'配置身份域或版本已变更\';\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\') {\n        if(!fields) {\n            var code=old.code;\n            var referenced=sql.selectOne("""\nselect count(*) n\nfrom iam_appointment_t\nwhere is_del=0\n    and (post_code=#{code}\n         or position_code=#{code}\n         or rank_code=#{code}\n         or title_code=#{code})\n""").n;\n            if(referenced>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_org_t\nwhere identity_domain=#{domain}\n    and line_code=#{code}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_dict_item_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0) {\n                exit 409,\'字典仍被资料或下级引用\';\n            }\n        }\n        else {\n            if(old.entity_type==\'APPLICATION\') {\n                exit 409,\'应用扩展字段已迁入应用配置，请先迁移历史定义\';\n            }\n            var target=old.entity_type==\'SUBJECT\'?\'iam_subject_t\':old.entity_type==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n            var jsonPath=\'$.\'+old.field_key;\n            if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0 and json_contains_path(ext_json,\\\'one\\\',#{jsonPath})\').n>0) {\n                exit 409,\'扩展字段已有数据，请先迁移或停用\';\n            }\n        }\n        sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n        audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    var name=(r.name||\'\').trim();\n    var code=(r.code||\'\').trim();\n    var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n    if(name==\'\' || name.length()>100 || !code.matches(\'[A-Za-z][A-Za-z0-9_]{1,63}\')) {\n        exit 400,\'名称或编码不正确\';\n    }\n    if(old!=null && code!=(fields?old.field_key:old.code)) {\n        exit 400,\'编码保持稳定\';\n    }\n    if(fields) {\n        var typeMap={\n            用户:\'SUBJECT\',机构:\'ORG\',资源:\'RESOURCE\'\n        };\n        var valueMap={\n            文本:\'STRING\',数字:\'NUMBER\',日期:\'DATE\',枚举:\'ENUM\',布尔:\'BOOLEAN\'\n        };\n        var entityType=typeMap.get(r.subjectType)||r.subjectType;\n        var valueType=valueMap.get(r.value)||r.value;\n        if(![\'SUBJECT\',\'ORG\',\'RESOURCE\'].contains(entityType) || ![\'STRING\',\'NUMBER\',\'DATE\',\'BOOLEAN\',\'ENUM\'].contains(valueType) || [\'password\',\'secret\',\'token\',\'credential\',\'permissions\',\'roles\',\'tenant_id\',\'is_admin\'].contains(code.toLowerCase())) {\n            exit 400,\'扩展对象、类型或字段键不允许\';\n        }\n        if(old!=null && (entityType!=old.entity_type || valueType!=old.value_type)) {\n            exit 409,\'已有字段类型和对象保持稳定\';\n        }\n        var validation=r.validation||{};\n        for(k in validation.keySet()) {\n            if(![\'maxLength\',\'min\',\'max\',\'options\',\'default\'].contains(k)) {\n                exit 400,\'校验规则不允许\';\n            }\n        }\n        if(validation.maxLength!=null && (!(validation.maxLength instanceof Number) || validation.maxLength<1 || validation.maxLength>4096 || validation.maxLength.doubleValue()!=validation.maxLength.longValue())) {\n            exit 400,\'文本长度须为1至4096的整数\';\n        }\n        for(k in [\'min\',\'max\']) {\n            var value=validation.get(k);\n            if(value!=null && (!(value instanceof Number) || !Double.isFinite(value.doubleValue()))) {\n                exit 400,\'数值边界须为有限数字\';\n            }\n        }\n        if(validation.min!=null && validation.max!=null && validation.min>validation.max) {\n            exit 400,\'数值范围不正确\';\n        }\n        if(validation.options!=null && (validation.options.size()>100 || validation.options.filter(o=>!(o instanceof String) || o.length()>256).size()>0)) {\n            exit 400,\'枚举选项须为文本\';\n        }\n        if(valueType==\'ENUM\' && (validation.options==null || validation.options.size()==0 || validation.options.size()>100)) {\n            exit 400,\'枚举字段需要1至100项选项\';\n        }\n        var encoded=JSONUtil.toJsonStr(validation);\n        var required=r.required==true?1:0;\n        var sensitive=r.sensitive==true?1:0;\n        if(sensitive==1 && validation.containsKey(\'default\')) {\n            exit 400,\'敏感字段不能在配置中保存默认值\';\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and field_key=#{code}\n""")!=null) {\n                exit 409,\'字段键已使用\';\n            }\n            if(required==1 && !validation.containsKey(\'default\')) {\n                var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n                if(sql.selectOne(\'select count(*) n from \'+target+\' where is_del=0\').n>0) {\n                    exit 409,\'已有资料时新增必填字段须提供迁移默认值\';\n                }\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_field_definition_t(tid,\n                identity_domain, entity_type, field_key, label, value_type, required_flag, validation_json,\n                sensitive_flag, status)\nvalues(#{id},#{domain},#{entityType},#{code},#{name},#{valueType},#{required},#{encoded},#{sensitive},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_field_definition_t\nset label=#{name},required_flag=#{required},validation_json=#{encoded},\n    sensitive_flag=#{sensitive},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        if(status==\'ACTIVE\') {\n            var target=entityType==\'SUBJECT\'?\'iam_subject_t\':entityType==\'ORG\'?\'iam_org_t\':\'iam_resource_t\';\n            var records=sql.select(\'select tid as id,ext_json from \'+target+\' where is_del=0\'+([\'SUBJECT\',\'ORG\'].contains(entityType)?\' and identity_domain=#{domain}\':" and app_id in (select tid from iam_application_t where kind=\'BUSINESS\' and is_del=0)"));\n            for(item in records) {\n                var existing=item.ext_json==null?{}:JSONUtil.parseObj(item.ext_json);\n                var adjusted=fieldValues(\'encode\',entityType,domain,item.id,existing,existing);\n                var text=JSONUtil.toJsonStr(adjusted);\n                if(text!=JSONUtil.toJsonStr(existing)) {\n                    sql.update(\'update \'+target+\' set ext_json=#{text},version=version+1,updated_time=utc_timestamp(6) where tid=#{item.id}\');\n                }\n            }\n        }\n    }\n    else {\n        var kindMap={\n            岗位:\'POST\',职务:\'POSITION\',职级:\'RANK\',职称:\'TITLE\'\n        };\n        var category=r.category==\'line\'?\'LINE\':kindMap.get(r.value)||r.value;\n        if(![\'LINE\',\'POST\',\'POSITION\',\'RANK\',\'TITLE\'].contains(category)) {\n            exit 400,\'字典类型不正确\';\n        }\n        if(old!=null && category!=old.category) {\n            exit 400,\'字典类型保持稳定\';\n        }\n        var parentId=r.parentId||null;\n        var parent=parentId==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{parentId}\n    and category=#{category}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\n        if(parentId!=null && parent==null) {\n            exit 400,\'父字典无效\';\n        }\n        var visited=[id];\n        var cursor=parent;\n        while(cursor!=null) {\n            if(visited.contains(cursor.id)) {\n                exit 400,\'字典层级不能循环\';\n            }\n            visited.add(cursor.id);\n            var next=cursor.parent_id;\n            cursor=next==null?null:sql.selectOne("""\nselect tid as id,parent_id\nfrom iam_dict_item_t\nwhere tid=#{next}\n""");\n        }\n        if(old==null) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_dict_item_t\nwhere identity_domain=#{domain}\n    and category=#{category}\n    and code=#{code}\n""")!=null) {\n                exit 409,\'字典编码已使用\';\n            }\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_dict_item_t(tid,\n                identity_domain, category, code, name, parent_id, status)\nvalues(#{id},#{domain},#{category},#{code},#{name},#{parentId},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_dict_item_t\nset name=#{name},parent_id=#{parentId},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n    }\n    audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n        id:id\n    });\n    return {\n        id:id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/12.目录配置共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('75cbaac4859b498986a3d05c979fad9d',NULL,'function','{\n  "properties": {},\n  "id": "8cbd7ac406ed58a2be17e3e76cbefad5",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "13.扩展值校验与保护",\n  "createTime": 1790615423659,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/field-values",\n  "description": "按已登记字段定义验证扩展值格式和长度，过滤不允许写入的保留字段。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "entityType",\n      "value": null,\n      "description": "扩展字段所属对象类别",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "objectId",\n      "value": null,\n      "description": "被操作对象标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "values",\n      "value": null,\n      "description": "待校验的扩展字段值",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "prior",\n      "value": null,\n      "description": "修改前的扩展字段值",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：13.扩展值校验与保护\n// 业务说明：按已登记字段定义验证扩展值格式和长度，过滤不允许写入的保留字段。\n// 函数输入：operation：本次执行的业务操作；entityType：扩展字段所属对象类别；identityDomain：人员或公众身份域；objectId：被操作对象标识；values：待校验的扩展字段值；prior：修改前的扩展字段值。\n// 返回与副作用：按已登记字段定义验证扩展值格式和长度，过滤不允许写入的保留字段。\nimport db;\nimport identityTransport;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Number;\nimport java.lang.String;\nimport java.lang.Boolean;\nimport java.util.Map;\nimport java.time.LocalDate;\n\n// 资料扩展只采用已定义字段。敏感值使用框架原语和对象绑定AAD，读取只返回掩码。\nvar sql=db.normal();\nvar domain=identityDomain;\nvar incoming=values||{};\nvar previous=prior||{};\nvar definitions=sql.select("""\nselect *,tid as id\nfrom iam_field_definition_t\nwhere identity_domain=#{domain}\n    and entity_type=#{entityType}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n// 目录分页读取共享一次字段定义；只输出当前页已获授权对象的掩码值。\nif(operation==\'view-many\') {\n    var views={};\n    for(item in incoming) {\n        var view={};\n        var source=item.values||{};\n        for(d in definitions) {\n            var value=source.get(d.field_key);\n            if(value!=null) {\n                view.put(d.field_key,d.sensitive_flag==1?\'[受保护]\':value);\n            }\n        }\n        views.put(item.id,view);\n    }\n    return views;\n}\nvar known=definitions.map(d=>d.field_key);\nvar result={};\nfor(k in incoming.keySet()) {\n    if(operation!=\'view\' && !known.contains(k) && (!previous.containsKey(k) || JSONUtil.toJsonStr(previous.get(k))!=JSONUtil.toJsonStr(incoming.get(k)))) {\n        exit 400,\'扩展字段未定义或已停用\';\n    }\n}\nfor(d in definitions) {\n    var key=d.field_key;\n    var value=incoming.containsKey(key)?incoming.get(key):previous.get(key);\n    var rule=d.validation_json==null?{}:JSONUtil.parseObj(d.validation_json);\n    var aad=domain+\'/\'+entityType+\'/\'+objectId+\'/\'+key;\n    if(operation==\'view\') {\n        if(value!=null) {\n            result.put(key,d.sensitive_flag==1?\'[受保护]\':value);\n        }\n        continue;\n    }\n    if(value==\'[受保护]\' || (value!=null && value instanceof Map)) {\n        var original=previous.get(key);\n        if(original==null || (value!=\'[受保护]\' && JSONUtil.toJsonStr(value)!=JSONUtil.toJsonStr(original))) {\n            exit 400,\'不能提交受保护字段存储格式\';\n        }\n        if(original instanceof Map && original.containsKey(\'encrypted\')) {\n            value=JSONUtil.parseObj(identityTransport.unprotectValue(original.encrypted,aad)).value;\n        }\n        else {\n            value=original;\n        }\n    }\n    if(value==null && rule.containsKey(\'default\')) {\n        value=rule.get(\'default\');\n    }\n    if(value==null || value==\'\') {\n        if(d.required_flag==1) {\n            exit 400,\'必填扩展字段缺失\';\n        }\n        if(value!=null) {\n            result.put(key,value);\n        }\n        continue;\n    }\n    if(d.value_type==\'STRING\' && !(value instanceof String)) {\n        exit 400,\'扩展字段须为文本\';\n    }\n    if(d.value_type==\'NUMBER\' && !(value instanceof Number)) {\n        exit 400,\'扩展字段须为数字\';\n    }\n    if(d.value_type==\'BOOLEAN\' && !(value instanceof Boolean)) {\n        exit 400,\'扩展字段须为布尔值\';\n    }\n    if(d.value_type==\'DATE\') {\n        try {\n            LocalDate.parse(\'\'+value);\n        }\n        catch(e) {\n            exit 400,\'扩展日期不正确\';\n        }\n    }\n    if(d.value_type==\'ENUM\' && (rule.options==null || !rule.options.contains(value))) {\n        exit 400,\'扩展字段不在枚举范围\';\n    }\n    if((\'\'+value).length()>(rule.maxLength||4096) || (d.value_type==\'NUMBER\' && ((rule.min!=null && value<rule.min) || (rule.max!=null && value>rule.max)))) {\n        exit 400,\'扩展字段值超出范围\';\n    }\n    result.put(key,d.sensitive_flag==1?{\n        encrypted:identityTransport.protectValue(JSONUtil.toJsonStr({\n            value:value\n        }),aad)\n    }\n    :value);\n}\n// 停用定义保留历史值，不对调用方开放写入或解密。\nif(operation!=\'view\') {\n    for(k in previous.keySet()) {\n        if(!known.contains(k)) {\n            result.put(k,previous.get(k));\n        }\n    }\n}\nreturn result;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/13.扩展值校验与保护.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0d14c10619ff43bf8dd762b41cd27602',NULL,'function','{\n  "properties": {},\n  "id": "1dd6c825721a58eca0ebe748c1eacc38",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "14.授权有效期计算",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/time-window",\n  "description": "统一解析授权起止时间与当前有效状态，供角色、权限和登录访问计算复用。",\n  "parameters": [\n    {\n      "name": "startsAt",\n      "value": null,\n      "description": "授权或成员关系开始时间",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "expiresAt",\n      "value": null,\n      "description": "授权或成员关系截止时间",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：14.授权有效期计算\n// 业务说明：统一解析授权起止时间与当前有效状态，供角色、权限和登录访问计算复用。\n// 函数输入：startsAt：授权或成员关系开始时间；expiresAt：授权或成员关系截止时间。\n// 返回与副作用：统一解析授权起止时间与当前有效状态，供角色、权限和登录访问计算复用。\nimport java.time.Instant;\nimport db;\nimport java.time.LocalDateTime;\nimport java.time.ZoneOffset;\nimport java.time.format.DateTimeFormatter;\n\nvar start=null;\nvar end=null;\n// 以数据库 UTC 当前时间作为缺省生效时间，统一解析输入的时区。\ntry {\n    var now=db.normal().selectOne("""\nselect date_format(utc_timestamp(6), \'%Y-%m-%dT%H:%i:%s.%fZ\') now_utc\n""").now_utc;\n    start=startsAt==null || startsAt==\'\'?Instant.parse(now):Instant.parse(startsAt);\n    end=expiresAt==null || expiresAt==\'\'?null:Instant.parse(expiresAt);\n}\ncatch(e) {\n    exit 400,\'时间须为带时区的ISO日期\';\n}\n// 拒绝截止时间不晚于开始时间的授权窗口。\nif(end!=null && !end.isAfter(start)) {\n    exit 400,\'到期时间须晚于生效时间\';\n}\nvar format=DateTimeFormatter.ofPattern(\'yyyy-MM-dd HH:mm:ss.SSSSSS\');\nreturn {\n    start:format.format(LocalDateTime.ofInstant(start,ZoneOffset.UTC)),end:end==null?null:format.format(LocalDateTime.ofInstant(end,ZoneOffset.UTC))\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/14.授权有效期计算.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('55a2a4e217cb479985a15773330307e0',NULL,'function','{\n  "properties": {},\n  "id": "5ce8c6b8682853419b0fe1db8d286d9a",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "15.业务角色资源目录",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/business-catalog",\n  "description": "按应用读取或维护业务角色与菜单、按钮、接口资源的关联，并校验资源所属应用。",\n  "parameters": [\n    {\n      "name": "entity",\n      "value": null,\n      "description": "中央目录对象类别",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：15.业务角色资源目录\n// 业务说明：按应用读取或维护业务角色与菜单、按钮、接口资源的关联，并校验资源所属应用。\n// 函数输入：entity：中央目录对象类别；operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：按应用读取或维护业务角色与菜单、按钮、接口资源的关联，并校验资源所属应用。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/field-values\' as fieldValues;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\n\n// 应用业务角色与菜单/API资源。平台内部权限只能由platform-roles维护。\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\nif(![\'roles\',\'resources\'].contains(entity)) {\n    exit 400,\'对象类型不正确\';\n}\nvar table=entity==\'roles\'?\'iam_role_t\':\'iam_resource_t\';\nvar id=r.id||p.id;\nvar old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0\');\nvar appId=old==null?r.appId:old.app_id;\nvar permission=entity+\':\'+(operation==\'list\'?\'read\':\'write\');\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    // 按操作员的应用管理范围过滤可见数据。\n    var ctx=listContext(permission,p.appId||null,domain);\n    var rows=sql.select(\'select t.*,t.tid as id,date_format(t.created_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') created_utc,date_format(t.updated_time,\\\'%Y-%m-%dT%H:%i:%sZ\\\') updated_utc from \'+table+" t join iam_application_t a on a.tid=t.app_id and a.kind=\'BUSINESS\' and a.is_del=0 where t.is_del=0 and t.identity_domain=#{domain} order by t.tid");\n    var visible=rows.filter(x=>ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.app_id)).size()>0).size()>0 && (p.appId==null || x.app_id==p.appId));\n    return visible.map(x=>({\n        id:x.id,appId:x.app_id,domain:x.identity_domain,name:x.name,code:x.code,status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,description:entity==\'roles\'?x.description||\'\':\'\',resourceIds:entity==\'roles\'?sql.select("""\nselect resource_id\nfrom iam_role_resource_rela_t\nwhere role_id=#{x.id}\n""").map(v=>v.resource_id):[],parentId:entity==\'resources\'?x.parent_id:null,type:entity==\'resources\'?x.resource_type.toLowerCase():\'\',path:entity==\'resources\'?x.path||\'\':\'\',method:entity==\'resources\'?x.http_method||\'GET\':\'\',ext:entity==\'resources\'?fieldValues(\'view\',\'RESOURCE\',domain,x.id,x.ext_json==null?{}:JSONUtil.parseObj(x.ext_json),{}):{}\n    }));\n}\n// 先校验当前会话的功能权限、身份域和应用管理范围。\nvar ctx=guard(permission,appId,domain);\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,entity+\':\'+operation,p,()=>{\n    old=id==null?null:sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{id} and is_del=0 for update\');\n    if(old==null && p.creating!=true) {\n        exit 404,\'记录不存在\';\n    }\n    if(old!=null && (old.app_id!=r.appId && r.appId!=null || old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n        exit 409,\'应用、身份域或版本不一致\';\n    }\n    var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n    if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n        exit 400,\'目标不是此身份域的业务应用\';\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\') {\n        if(entity==\'roles\' && sql.selectOne("""\nselect count(*) n\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nwhere rr.role_id=#{id}\n    and g.is_del=0\n    and g.status=\'ACTIVE\'\n""").n>0) {\n            exit 409,\'角色仍被有效授权引用，请停用或先撤销来源\';\n        }\n        if(entity==\'resources\' && (sql.selectOne("""\nselect count(*) n\nfrom iam_resource_t\nwhere parent_id=#{id}\n    and is_del=0\n""").n>0 || sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t\nwhere resource_id=#{id}\n""").n>0)) {\n            exit 409,\'资源仍被下级或角色引用\';\n        }\n        sql.update(\'update \'+table+" set status=\'DISABLED\',is_del=1,version=version+1,updated_time=utc_timestamp(6) where tid=#{id}");\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',entity+\':remove\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    var code=(r.code||\'\').trim();\n    var name=(r.name||\'\').trim();\n    var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n    if(name==\'\' || name.length()>(entity==\'roles\'?100:200) || !code.matches(\'[A-Za-z][A-Za-z0-9_:.-]{1,99}\')) {\n        exit 400,\'名称或编码不正确\';\n    }\n    if(old!=null && code!=old.code) {\n        exit 400,\'编码保持稳定\';\n    }\n    if(old==null && sql.selectOne(\'select tid as id from \'+table+\' where app_id=#{appId} and code=#{code}\')!=null) {\n        exit 409,\'编码已经使用\';\n    }\n    if(entity==\'roles\') {\n        var description=r.description||\'\';\n        if(description.length()>1000) {\n            exit 400,\'说明过长\';\n        }\n        var resources=r.resourceIds||[];\n        if(resources.size()>500 || resources.distinct().size()!=resources.size()) {\n            exit 400,\'资源引用重复或过多\';\n        }\n        for(rid in resources) {\n            if(sql.selectOne("""\nselect tid as id\nfrom iam_resource_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n                exit 400,\'资源必须属于同应用和身份域且启用\';\n            }\n        }\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_role_t(tid, app_id, identity_domain, code, name, description, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{description},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_role_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        sql.update("""\ndelete\nfrom iam_role_resource_rela_t\nwhere role_id=#{id}\n""");\n        for(rid in resources) {\n            var link=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_role_resource_rela_t(tid,\n                role_id, resource_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n        }\n    }\n    else {\n        var type=(r.type||\'\').toUpperCase();\n        var parentId=r.parentId||null;\n        var path=r.path||\'\';\n        var method=(r.method||\'GET\').toUpperCase();\n        if(![\'MENU\',\'BUTTON\',\'API\'].contains(type) || path.length()>500 || type==\'API\' && (!path.matches(\'/[A-Za-z0-9_./{}:-]*\') || ![\'GET\',\'POST\',\'PUT\',\'PATCH\',\'DELETE\'].contains(method))) {\n            exit 400,\'资源类型或接口路径不正确\';\n        }\n        var visited=[id];\n        var cursor=parentId;\n        while(cursor!=null) {\n            if(visited.contains(cursor)) {\n                exit 400,\'资源层级不能循环\';\n            }\n            visited.add(cursor);\n            var parent=sql.selectOne("""\nselect tid as id,parent_id,resource_type\nfrom iam_resource_t\nwhere tid=#{cursor}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\n            if(parent==null || parent.resource_type!=\'MENU\') {\n                exit 400,\'父资源须为同应用同域菜单\';\n            }\n            cursor=parent.parent_id;\n        }\n        if(old==null) {\n            id=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_resource_t(tid,\n                app_id, identity_domain, code, name, resource_type, parent_id, path, http_method, status)\nvalues(#{id},#{appId},#{domain},#{code},#{name},#{type},#{parentId},#{path},#{method},#{status})\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_resource_t\nset name=#{name},resource_type=#{type},parent_id=#{parentId},path=#{path},\n        http_method=#{method},\n        status=#{status},\n        version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        }\n        var ext=JSONUtil.toJsonStr(fieldValues(\'encode\',\'RESOURCE\',domain,id,r.ext||{},old==null || old.ext_json==null?{}:JSONUtil.parseObj(old.ext_json)));\n        sql.update("""\nupdate iam_resource_t\nset ext_json=#{ext}\nwhere tid=#{id}\n""");\n    }\n    rebuild(appId,domain);\n    audit(ctx,\'SUCCESS\',entity+\':save\',id,null,{\n        id:id,appId:appId\n    });\n    return {\n        id:id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/15.业务角色资源目录.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('890b5ce54a6e40e58b5dd92c9950ce95',NULL,'function','{\n  "properties": {},\n  "id": "8d8e858f6ff057739f9bf1d0eab72bef",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "16.计算有效访问权限",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/effective-access",\n  "description": "汇合人员直授、机构继承及权限组等来源，应用有效期和状态规则，返回指定人员在应用内的有效角色与资源。",\n  "parameters": [\n    {\n      "name": "subjectId",\n      "value": null,\n      "description": "中央人员身份标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：16.计算有效访问权限\n// 业务说明：汇合人员直授、机构继承及权限组等来源，应用有效期和状态规则，返回指定人员在应用内的有效角色与资源。\n// 函数输入：subjectId：中央人员身份标识；appId：目标业务应用标识；identityDomain：人员或公众身份域。\n// 返回与副作用：汇合人员直授、机构继承及权限组等来源，应用有效期和状态规则，返回指定人员在应用内的有效角色与资源。\nimport db;\nimport cn.hutool.json.JSONUtil;\nimport java.util.Collections;\nimport \'@/idaas/resource-enabled\' as enabled;\n\n// 每次调用重新计算有效来源。此函数供投影、认证协议和受保护接口调用，不接受客户端权限缓存。\nvar sql=db.normal();\nvar domain=identityDomain||\'workforce\';\nvar result={\n    appId:appId,hasAccess:false,roleIds:[],resourceIds:[],sources:[]\n};\n// 先确认应用和人员在同一身份域均处于可用状态；任一无效即无访问资格。\nvar app=sql.selectOne("""\nselect tid as id,identity_domains\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\nvar subject=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""");\nif(app==null || subject==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n    return result;\n}\n// 只纳入有效任职及祖先机构均启用的组织，供机构继承授权匹配。\nvar orgs=sql.select("""\nselect o.tid as id,o.path\nfrom iam_appointment_t a\njoin iam_org_t o on o.tid=a.org_id\nand o.identity_domain=#{domain}\nand o.is_del=0\nand o.status=\'ACTIVE\'\nwhere a.subject_id=#{subjectId}\n    and a.is_del=0\n    and a.status=\'ACTIVE\'\n    and a.valid_from<=utc_timestamp(6)\n    and (a.valid_until is null\n         or a.valid_until>utc_timestamp(6))\n    and not exists\n        (select 1\n         from iam_org_t ancestor\n         where locate(concat(\'/\', ancestor.tid, \'/\'), o.path)>0\n             and (ancestor.is_del=1\n                  or ancestor.status!=\'ACTIVE\'))\n""");\n// 权限组成员关系必须在有效期内，停用组不参与授权计算。\nvar groups=sql.select("""\nselect g.tid as id,g.name\nfrom iam_group_member_t m\njoin iam_permission_group_t g on g.tid=m.group_id\nand g.identity_domain=#{domain}\nand g.status=\'ACTIVE\'\nand g.is_del=0\nwhere m.subject_id=#{subjectId}\n    and m.status=\'ACTIVE\'\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\n""");\nvar grants=sql.select("""\nselect g.*,g.tid as id,o.path org_path,o.name org_name,o.status org_status,o.is_del org_deleted\nfrom iam_access_grant_t g\nleft join iam_org_t o on o.tid=g.org_id\nwhere g.app_id=#{appId}\n    and g.identity_domain=#{domain}\n    and g.status=\'ACTIVE\'\n    and g.is_del=0\n    and g.valid_from<=utc_timestamp(6)\n    and (g.valid_until is null\n         or g.valid_until>utc_timestamp(6))\n""");\n// 逐条判断直接、机构和权限组授权来源；角色与资源去重后再检查资源祖先状态。\nfor(g in grants) {\n    var applies=g.principal_type==\'SUBJECT\' && g.subject_id==subjectId || g.principal_type==\'GROUP\' && groups.filter(x=>x.id==g.group_id).size()>0 || g.principal_type==\'ORG\' && g.org_status==\'ACTIVE\' && g.org_deleted==0 && orgs.filter(x=>x.id==g.org_id || g.include_children==1 && x.path.startsWith(g.org_path)).size()>0;\n    if(!applies) {\n        continue;\n    }\n    result.hasAccess=true;\n    result.sources.add({\n        grantId:g.id,source:g.principal_type==\'SUBJECT\'?\'user\':g.principal_type.toLowerCase(),label:g.principal_type==\'SUBJECT\'?\'直接授权\':g.principal_type==\'ORG\'?\'机构授权：\'+g.org_name:\'权限组授权\',subjectId:g.subject_id||g.org_id||g.group_id\n    });\n    var roles=sql.select("""\nselect r.tid as id\nfrom iam_grant_role_rela_t rr\njoin iam_role_t r on r.tid=rr.role_id\nand r.app_id=#{appId}\nand r.identity_domain=#{domain}\nand r.status=\'ACTIVE\'\nand r.is_del=0\nwhere rr.grant_id=#{g.id}\n    and rr.app_id=#{appId}\n""");\n    for(role in roles) {\n        if(!result.roleIds.contains(role.id)) {\n            result.roleIds.add(role.id);\n        }\n        var resources=sql.select("""\nselect r.tid as id\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id\nand r.app_id=#{appId}\nand r.identity_domain=#{domain}\nand r.status=\'ACTIVE\'\nand r.is_del=0\nwhere rr.role_id=#{role.id}\n    and rr.app_id=#{appId}\n""");\n        for(resource in resources) {\n            if(!result.resourceIds.contains(resource.id)) {\n                result.resourceIds.add(resource.id);\n            }\n        }\n    }\n}\nresult.resourceIds=enabled(appId,domain,result.resourceIds);\nCollections.sort(result.roleIds);\nCollections.sort(result.resourceIds);\nreturn result;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/16.计算有效访问权限.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('02561f58ca434f19a5821ad1530a31d1',NULL,'function','{\n  "properties": {},\n  "id": "10b412971f255f5cb7831b43cd182d46",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "17.重建授权结果投影",\n  "createTime": 1790617158595,\n  "updateTime": 1791194872495,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/rebuild-projections",\n  "description": "在明确的业务写入请求中重算受影响人员与应用的授权结果并更新投影；不启动后台轮询。",\n  "parameters": [\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：17.重建授权结果投影\n// 业务说明：在明确的业务写入请求中重算受影响人员与应用的授权结果并更新投影；不启动后台轮询。\n// 函数输入：appId：目标业务应用标识；identityDomain：人员或公众身份域。\n// 返回与副作用：在明确的业务写入请求中重算受影响人员与应用的授权结果并更新投影；不启动后台轮询。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/effective-access-batch\' as effectiveBatch;\n\nvar sql=db.normal();\nvar domain=identityDomain||\'workforce\';\n// 只在明确调用时枚举受影响应用，不安装周期扫描任务。\nvar apps=sql.select("""\nselect tid as id\nfrom iam_application_t\nwhere kind=\'BUSINESS\'\n    and is_del=0\n""");\nfor(app in apps) {\n    if(appId!=null && app.id!=appId) {\n        continue;\n    }\n    // 同时覆盖现有人员和已有投影人员，使授权撤销也能更新旧投影。\n    var subjects=sql.select("""\nselect tid as id\nfrom iam_subject_t\nwhere identity_domain=#{domain}\n    and is_del=0\nunion\nselect sa.subject_id tid\nfrom iam_subject_app_t sa\njoin iam_subject_t s on s.tid=sa.subject_id\nwhere s.identity_domain=#{domain}\n    and sa.app_id=#{app.id}\n""");\n    // 一次锁定现有投影；计算与写入每 500 人一组，SQL 数不按人员数逐项增长。\n    var priors=sql.select("""\nselect *,tid as id\nfrom iam_subject_app_t\nwhere app_id=#{app.id}\nfor update\n""");\n    var process=(batch)=>{\n        var accessById=effectiveBatch(app.id,domain,batch.map(row=>row.id));\n        var changes=[];\n        for(subject in batch) {\n            var access=accessById.get(subject.id);\n            var hash=DigestUtil.sha256Hex(JSONUtil.toJsonStr({\n                access:access.hasAccess,roles:access.roleIds,resources:access.resourceIds\n            }));\n            var found=priors.filter(row=>row.subject_id==subject.id);\n            var prior=found.size()==0?null:found[0];\n            if(prior==null && !access.hasAccess) {\n                continue;\n            }\n            var mode=access.hasAccess?\'GRANT_DERIVED\':\'DIRECTORY_ONLY\';\n            var status=access.hasAccess || prior!=null && prior.directory_assigned==1?\'ACTIVE\':\'REVOKED\';\n            var desired=access.hasAccess?1:0;\n            if(prior==null || prior.projection_hash!=hash || prior.desired_enabled!=desired\n                || prior.assignment_mode!=mode || prior.assignment_status!=status) {\n                changes.add({id:prior==null?IdUtil.fastSimpleUUID():prior.id,\n                    subjectId:subject.id,mode:mode,status:status,desired:desired,hash:hash});\n            }\n        }\n        if(changes.size()>0) {\n            sql.update("""\ninsert into iam_subject_app_t(tid,subject_id,app_id,assignment_mode,directory_assigned,\n    assignment_status,desired_enabled,projection_hash)\nvalues <foreach collection="changes" item="row" open="(" close=")" separator="),(">\n    #{row.id},#{row.subjectId},#{app.id},#{row.mode},0,#{row.status},#{row.desired},#{row.hash}\n</foreach>\non duplicate key update assignment_mode=values(assignment_mode),\n    assignment_status=values(assignment_status),desired_enabled=values(desired_enabled),\n    projection_hash=values(projection_hash),desired_version=desired_version+1,\n    version=version+1,sync_status=case when ack_version>0 then \'PENDING\' else \'NOT_CONNECTED\' end,\n    updated_time=utc_timestamp(6)\n""");\n        }\n    };\n    var batch=[];\n    for(subject in subjects) {\n        batch.add(subject);\n        if(batch.size()==500) {\n            process(batch);\n            batch=[];\n        }\n    }\n    if(batch.size()>0) {\n        process(batch);\n    }\n}\nreturn true;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/17.重建授权结果投影.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ec68bb9bca7a4c5187dc5f5387ea2500',NULL,'function','{\n  "properties": {},\n  "id": "9e888c8030275ef3aac1db63d8417f3f",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "18.业务访问授权共用规则",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/business-grants",\n  "description": "核验业务应用授权对象、角色、有效期及版本，更新授权与角色关联并记录审计。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：18.业务访问授权共用规则\n// 业务说明：核验业务应用授权对象、角色、有效期及版本，更新授权与角色关联并记录审计。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：核验业务应用授权对象、角色、有效期及版本，更新授权与角色关联并记录审计。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/effective-access\' as effective;\nimport \'@/idaas/rebuild-projections\' as rebuild;\nimport \'@/idaas/app-list-context\' as listContext;\n\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\nvar id=r.id||p.id;\nvar old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n""");\nvar appId=old==null?r.appId||p.appId:old.app_id;\nvar permission=\'grants:\'+(operation==\'list\' || operation==\'explain\'?\'read\':\'write\');\nvar ctx=operation==\'list\'?listContext(permission,appId,domain):guard(permission,appId,domain);\n// 授权解释分支：计算指定人员的有效访问来源并返回可阅读的依据。\nif(operation==\'explain\') {\n    var person=sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{p.subjectId}\n    and identity_domain=#{domain}\n    and is_del=0\n""");\n    if(person==null) {\n        exit 404,\'人员不存在\';\n    }\n    return effective(p.subjectId,appId,domain);\n}\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    var rows=sql.select("""\nselect *,tid as id,date_format(valid_from, \'%Y-%m-%dT%H:%i:%sZ\') start_utc,\n       date_format(valid_until, \'%Y-%m-%dT%H:%i:%sZ\') end_utc,date_format(created_time,\n        \'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') updated_utc\nfrom iam_access_grant_t\nwhere identity_domain=#{domain}\n    and is_del=0\norder by tid\n""");\n    return rows.filter(x=>(appId==null || x.app_id==appId) && ctx.pairs.filter(pair=>pair.codes.contains(permission) && pair.scopes.filter(s=>s.identity_domain==domain && (s.scope_kind==\'ALL\' || s.scope_kind==\'APPLICATION\' && s.app_id==x.app_id)).size()>0).size()>0).map(x=>({\n        id:x.id,domain:x.identity_domain,appId:x.app_id,name:\'应用访问授权\',source:x.principal_type==\'SUBJECT\'?\'user\':x.principal_type.toLowerCase(),subjectId:x.subject_id||x.org_id||x.group_id||x.client_id,roleIds:sql.select("""\nselect role_id\nfrom iam_grant_role_rela_t\nwhere grant_id=#{x.id}\n""").map(t=>t.role_id),includeChildren:x.include_children==1,status:x.status==\'ACTIVE\'?\'enabled\':\'revoked\',startsAt:x.start_utc,expiresAt:x.end_utc,reason:x.reason||\'\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc\n    }));\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,\'grants:\'+operation,p,()=>{\n    old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n    if(old==null && p.creating!=true) {\n        exit 404,\'授权不存在\';\n    }\n    if(old!=null && (old.version!=(r.version||p.version) || r.appId!=null && r.appId!=old.app_id || old.identity_domain!=domain)) {\n        exit 409,\'授权应用、域或版本不一致\';\n    }\n    var app=sql.selectOne("""\nselect *,tid as id\nfrom iam_application_t\nwhere tid=#{appId}\n    and kind=\'BUSINESS\'\n    and is_del=0\n""");\n    if(app==null || !JSONUtil.parseArray(app.identity_domains).contains(domain)) {\n        exit 400,\'仅允许此身份域的业务应用授权\';\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\' || r.status==\'revoked\') {\n        if(old==null) {\n            exit 404,\'授权不存在\';\n        }\n        sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n        rebuild(appId,domain);\n        audit(ctx,\'SUCCESS\',\'grants:revoke\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    var types={\n        user:\'SUBJECT\',org:\'ORG\',group:\'GROUP\',client:\'CLIENT\'\n    };\n    var type=types.get(r.source);\n    var principal=r.subjectId;\n    if(type==null || principal==null || old!=null && (old.principal_type!=type || (old.subject_id||old.org_id||old.group_id||old.client_id)!=principal)) {\n        exit 400,\'授权主体不能变更\';\n    }\n    var table=type==\'SUBJECT\'?\'iam_subject_t\':type==\'ORG\'?\'iam_org_t\':type==\'GROUP\'?\'iam_permission_group_t\':\'iam_auth_client_t\';\n    var target=sql.selectOne(\'select *,tid as id from \'+table+\' where tid=#{principal} and is_del=0\');\n    if(target==null || type!=\'CLIENT\' && (target.identity_domain!=domain || target.status!=\'ACTIVE\') || type==\'CLIENT\' && (target.client_type!=\'SERVICE\' || target.status==\'DISABLED\')) {\n        exit 400,\'主体须为启用的同域人员、机构、权限组或机器客户端\';\n    }\n    var roles=r.roleIds||[];\n    if(roles.size()>100 || roles.distinct().size()!=roles.size()) {\n        exit 400,\'角色引用重复或过多\';\n    }\n    for(rid in roles) {\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_role_t\nwhere tid=#{rid}\n    and app_id=#{appId}\n    and identity_domain=#{domain}\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n            exit 400,\'角色必须属于同业务应用和身份域\';\n        }\n        if(type==\'CLIENT\' && sql.selectOne("""\nselect count(*) n\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t re on re.tid=rr.resource_id\nwhere rr.role_id=#{rid}\n    and re.resource_type!=\'API\'\n    and re.is_del=0\n""").n>0) {\n            exit 400,\'机器身份只能授予API资源角色\';\n        }\n    }\n    var times=window(r.startsAt,r.expiresAt);\n    var reason=r.reason||\'\';\n    if(reason.length()>1000) {\n        exit 400,\'授权说明过长\';\n    }\n    var include=type==\'ORG\' && r.includeChildren==true?1:0;\n    var sid=type==\'SUBJECT\'?principal:null;\n    var oid=type==\'ORG\'?principal:null;\n    var gid=type==\'GROUP\'?principal:null;\n    var cid=type==\'CLIENT\'?principal:null;\n    if(old==null) {\n        id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_access_grant_t(tid,\n                app_id, identity_domain, principal_type, subject_id, org_id, group_id, client_id,\n                include_children, valid_from, valid_until, reason, created_by)\nvalues(#{id},#{appId},#{domain},#{type},#{sid},#{oid},#{gid},#{cid},#{include},#{times.start},#{times.end},#{reason},#{ctx.userId})\n""");\n    }\n    else {\n        sql.update("""\nupdate iam_access_grant_t\nset include_children=#{include},valid_from=#{times.start},valid_until=#{times.end},reason=#{reason},\n    status=\'ACTIVE\',version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n    }\n    sql.update("""\ndelete\nfrom iam_grant_role_rela_t\nwhere grant_id=#{id}\n""");\n    for(rid in roles) {\n        var link=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_grant_role_rela_t(tid, grant_id, role_id, app_id)\nvalues(#{link},#{id},#{rid},#{appId})\n""");\n    }\n    rebuild(appId,domain);\n    audit(ctx,\'SUCCESS\',\'grants:save\',id,null,{\n        id:id,appId:appId,type:type\n    });\n    return {\n        id:id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/18.业务访问授权共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('02cdf4780fd34d6cb710f4962aaa6554',NULL,'function','{\n  "properties": {},\n  "id": "9d08427e037b59d8ba66f337e68cfd68",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "19.权限组共用规则",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/permission-groups",\n  "description": "维护业务应用权限组、成员和授权关系，校验同一应用内的对象范围。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：19.权限组共用规则\n// 业务说明：维护业务应用权限组、成员和授权关系，校验同一应用内的对象范围。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：维护业务应用权限组、成员和授权关系，校验同一应用内的对象范围。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/business-grants\' as grants;\nimport \'@/idaas/time-window\' as window;\nimport \'@/idaas/rebuild-projections\' as rebuild;\n\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\nvar domain=r.domain||p.domain||\'workforce\';\n// 先校验当前会话的功能权限、身份域和应用管理范围。\nvar ctx=guard(operation==\'list\'?\'grants:read\':\'grants:write\',null,domain);\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    var rows=sql.select("""\nselect *,tid as id,date_format(created_time, \'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') updated_utc\nfrom iam_permission_group_t\nwhere identity_domain=#{domain}\n    and is_del=0\norder by tid\n""");\n    return rows.map(x=>({\n        id:x.id,domain:x.identity_domain,name:x.name,code:x.code,description:x.description||\'\',status:x.status==\'ACTIVE\'?\'enabled\':\'disabled\',version:x.version,createdAt:x.created_utc,updatedAt:x.updated_utc,userIds:sql.select("""\nselect subject_id\nfrom iam_group_member_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n""").map(m=>m.subject_id),members:sql.select("""\nselect subject_id subjectId,date_format(valid_from,\n        \'%Y-%m-%dT%H:%i:%sZ\') startsAt,\n       date_format(valid_until, \'%Y-%m-%dT%H:%i:%sZ\') expiresAt\nfrom iam_group_member_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n"""),items:sql.select("""\nselect tid as id,app_id\nfrom iam_access_grant_t\nwhere group_id=#{x.id}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").map(g=>({\n            appId:g.app_id,roleIds:sql.select("""\nselect role_id\nfrom iam_grant_role_rela_t\nwhere grant_id=#{g.id}\n""").map(y=>y.role_id)\n        }))\n    }));\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,\'permission-groups:\'+operation,p,()=>{\n    var id=r.id||p.id;\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_permission_group_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n    if(old==null && p.creating!=true) {\n        exit 404,\'权限组不存在\';\n    }\n    if(old!=null && (old.identity_domain!=domain || old.version!=(r.version||p.version))) {\n        exit 409,\'权限组身份域或版本已变更\';\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\') {\n        sql.update("""\nupdate iam_permission_group_t\nset status=\'DISABLED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n        sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n        rebuild(null,domain);\n        audit(ctx,\'SUCCESS\',\'permission-groups:remove\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    var name=(r.name||\'\').trim();\n    var description=r.description||\'\';\n    var code=old==null?(r.code||\'GROUP_\'+IdUtil.fastSimpleUUID()):old.code;\n    var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n    var users=r.userIds||[];\n    var items=r.items||[];\n    if(name==\'\' || name.length()>200 || description.length()>1000 || !code.matches(\'[A-Za-z][A-Za-z0-9_.:-]{1,99}\') || users.size()>1000 || users.distinct().size()!=users.size() || items.size()>50 || items.map(i=>i.appId).distinct().size()!=items.size()) {\n        exit 400,\'名称、成员或应用组合不正确\';\n    }\n    for(sid in users) {\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{sid}\n    and identity_domain=#{domain}\n    and is_del=0\n    and status=\'ACTIVE\'\n""")==null) {\n            exit 400,\'成员须为同域中央人员\';\n        }\n    }\n    // 先校验全部组合，组写入与来源、成员都在同一事务内。\n    for(item in items) {\n        guard(\'grants:write\',item.appId,domain);\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_application_t\nwhere tid=#{item.appId}\n    and kind=\'BUSINESS\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""")==null) {\n            exit 400,\'组合仅允许有效业务应用\';\n        }\n    }\n    if(old==null) {\n        id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_permission_group_t(tid,\n                identity_domain, code, name, description, status)\nvalues(#{id},#{domain},#{code},#{name},#{description},#{status})\n""");\n    }\n    else {\n        sql.update("""\nupdate iam_permission_group_t\nset name=#{name},description=#{description},status=#{status},version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n    }\n    sql.update("""\nupdate iam_group_member_t\nset status=\'REVOKED\',version=version+1\nwhere group_id=#{id}\n""");\n    for(sid in users) {\n        var prior=sql.selectOne("""\nselect *,tid as id\nfrom iam_group_member_t\nwhere group_id=#{id}\n    and subject_id=#{sid}\n""");\n        var details=(r.members||[]).filter(m=>m.subjectId==sid);\n        var times=details.size()>0?window(details[0].startsAt,details[0].expiresAt):window(null,null);\n        var mid=prior==null?IdUtil.fastSimpleUUID():prior.id;\n        if(prior==null) {\n            sql.update("""\ninsert into iam_group_member_t(tid,\n                group_id, subject_id, valid_from, valid_until)\nvalues(#{mid},#{id},#{sid},#{times.start},#{times.end})\n""");\n        }\n        else if(details.size()>0) {\n            sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',valid_from=#{times.start},valid_until=#{times.end},version=version+1\nwhere tid=#{mid}\n""");\n        }\n        else {\n            sql.update("""\nupdate iam_group_member_t\nset status=\'ACTIVE\',version=version+1\nwhere tid=#{mid}\n""");\n        }\n    }\n    var current=sql.select("""\nselect *,tid as id\nfrom iam_access_grant_t\nwhere group_id=#{id}\n    and is_del=0\n""");\n    for(g in current) {\n        if(items.filter(i=>i.appId==g.app_id).size()==0 || status!=\'ACTIVE\') {\n            sql.update("""\nupdate iam_access_grant_t\nset status=\'REVOKED\',version=version+1\nwhere tid=#{g.id}\n""");\n        }\n    }\n    if(status==\'ACTIVE\') {\n        for(item in items) {\n            var existing=current.filter(g=>g.app_id==item.appId);\n            var prior=existing.size()>0?existing[0]:null;\n            grants(\'save\',{\n                requestId:IdUtil.fastSimpleUUID(),creating:prior==null,record:{\n                    id:prior==null?null:prior.id,version:prior==null?1:prior.version,domain:domain,source:\'group\',subjectId:id,appId:item.appId,roleIds:item.roleIds||[],reason:\'权限组组合\',status:\'enabled\'\n                }\n            });\n        }\n    }\n    rebuild(null,domain);\n    audit(ctx,\'SUCCESS\',\'permission-groups:save\',id,null,{\n        id:id,memberCount:users.size()\n    });\n    return {\n        id:id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/19.权限组共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ccbe2d1cd44c4d989b6f6fd022a9e403',NULL,'function','{\n  "properties": {},\n  "id": "10eb9e1105a75214a5470e57852f430b",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "20.应用列表查询范围",\n  "createTime": 1790617158595,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/app-list-context",\n  "description": "根据平台会话权限与应用授权构造列表可见范围，供多个应用资源查询接口复用。",\n  "parameters": [\n    {\n      "name": "permission",\n      "value": null,\n      "description": "待校验的功能权限编码",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：20.应用列表查询范围\n// 业务说明：根据平台会话权限与应用授权构造列表可见范围，供多个应用资源查询接口复用。\n// 函数输入：permission：待校验的功能权限编码；appId：目标业务应用标识；identityDomain：人员或公众身份域。\n// 返回与副作用：根据平台会话权限与应用授权构造列表可见范围，供多个应用资源查询接口复用。\nimport \'@/idaas/context\' as context;\nimport \'@/idaas/guard\' as guard;\n\n// 先读取平台会话的功能与对象范围，不能把其他角色的范围拼接到本功能上。\nvar ctx=context();\nvar domain=identityDomain||\'workforce\';\n// 指定应用时直接按该应用核验；未指定时才从可见应用中寻找合法范围。\nif(appId!=null) {\n    return guard(permission,appId,domain);\n}\nfor(pair in ctx.pairs) {\n    if(!pair.codes.contains(permission)) {\n        continue;\n    }\n    for(scope in pair.scopes) {\n        if(scope.identity_domain==domain && [\'ALL\',\'APPLICATION\'].contains(scope.scope_kind)) {\n            return guard(permission,scope.scope_kind==\'ALL\'?null:scope.app_id,domain);\n        }\n    }\n}\nexit 403,\'当前账号没有应用功能范围权限\';\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/20.应用列表查询范围.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('76ec88741b5c49e5830f259bd5033d30',NULL,'function','{\n  "properties": {},\n  "id": "275494036ca45d1ea4eb856c7a5bef94",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "21.接收端账号安全校验",\n  "createTime": 1790619034459,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/receiver-account-check",\n  "description": "校验租户接收管理接口的本地账号、签名和请求范围，防止平台会话直接作为租户账号使用。",\n  "parameters": [\n    {\n      "name": "userId",\n      "value": null,\n      "description": "平台操作账号标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：21.接收端账号安全校验\n// 业务说明：校验租户接收管理接口的本地账号、签名和请求范围，防止平台会话直接作为租户账号使用。\n// 函数输入：userId：平台操作账号标识。\n// 返回与副作用：校验租户接收管理接口的本地账号、签名和请求范围，防止平台会话直接作为租户账号使用。\nimport db;\nimport identityRuntime;\nimport tenantRuntime;\n\n// 被框架实际应用于本地登录与现有本地会话。未接入或已脱管的账号完全按本地规则运行。\nvar tenantId=tenantRuntime.id();\nif(!identityRuntime.hasTable(\'idaas_receiver_object_t\')) {\n    return {\n        allowed:true\n    };\n}\nvar sql=db.normal();\nvar rows=sql.select("""\nselect o.source_enabled\nfrom idaas_receiver_object_t o\njoin idaas_receiver_binding_t b on b.app_id=o.app_id\nand b.tenant_id=#{tenantId}\nwhere o.object_type=\'SUBJECT\'\n    and o.local_id=#{userId}\n    and o.management_state=\'MANAGED\'\n""");\nif(rows.filter(x=>x.source_enabled!=1).size()==0) {\n    return {\n        allowed:true\n    };\n}\n// 撤销中央来源不撤销另行授予的本地资格。\nvar local=sql.selectOne("""\nselect count(*) n\nfrom rm_user_role_rela_t u\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and u.user_id=#{userId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null\n         or u.end_time>utc_timestamp(6))\n""");\nreturn {\n    allowed:local.n>0\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/21.接收端账号安全校验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('b84e56aa30834660a7a2d2820b6fdd7c',NULL,'function','{\n  "properties": {},\n  "id": "f919bae96dc45a398e97ad8bfbdf2dfc",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "22.协议客户端共用规则",\n  "createTime": 1790635007936,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/protocol-client",\n  "description": "校验协议客户端、回调和凭据轮换规则，供客户端配置及认证接口复用。",\n  "parameters": [\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：22.协议客户端共用规则\n// 业务说明：校验协议客户端、回调和凭据轮换规则，供客户端配置及认证接口复用。\n// 函数输入：payload：请求资料或筛选条件。\n// 返回与副作用：校验协议客户端、回调和凭据轮换规则，供客户端配置及认证接口复用。\nimport db;\nimport identityProtocol;\nimport cn.hutool.json.JSONUtil;\nimport java.lang.Math;\nimport \'@/idaas/auth-session-policy\' as sessionPolicy;\n\n// 协议配置仅供可信框架读取，避免普通接口获取客户端密钥摘要。\nif(!identityProtocol.isTrusted()) {\n    exit 403,\'协议配置只允许框架读取\';\n}\nvar p=payload||{};\nvar sql=db.normal();\n// 仅选择已启用业务应用下的已启用 OIDC 客户端。\nvar c=sql.selectOne("""\nselect c.*,c.tid as id\nfrom iam_auth_client_t c\njoin iam_application_t a on a.tid=c.app_id\nand a.kind=\'BUSINESS\'\nand a.auth_mode=\'FEDERATED\'\nand a.status=\'ACTIVE\'\nand a.is_del=0\nwhere c.is_del=0\n    and c.status=\'ACTIVE\'\n    and c.protocol=\'OIDC\'\n    and (c.tid=#{p.id}\n         or c.client_key=#{p.clientKey})\n""");\nif(c==null) {\n    return {\n        found:false\n    };\n}\n// 机密客户端必须存在有效凭据；公有客户端无需客户端密钥。\nvar key=sql.selectOne("""\nselect secret_hash\nfrom iam_credential_t\nwhere owner_kind=\'CLIENT\'\n    and owner_id=#{c.id}\n    and credential_type=\'CLIENT_SECRET\'\n    and status=\'ACTIVE\'\n    and (expires_at is null\n         or expires_at>utc_timestamp(6))\n""");\nif(c.client_type!=\'PUBLIC\' && key==null) {\n    return {\n        found:false\n    };\n}\nvar redirects=sql.select("""\nselect uri,uri_type\nfrom iam_auth_redirect_t\nwhere client_id=#{c.id}\n""");\nvar policy=sessionPolicy(\'read\',null);\nreturn {\n    found:true,id:c.id,appId:c.app_id,clientKey:c.client_key,name:c.name,clientType:c.client_type,secretHash:key==null?null:key.secret_hash,grants:JSONUtil.parseArray(c.grant_types),scopes:JSONUtil.parseArray(c.scopes),redirects:redirects.filter(r=>r.uri_type==\'LOGIN\').map(r=>r.uri),logoutRedirects:redirects.filter(r=>r.uri_type==\'LOGOUT\').map(r=>r.uri),accessTtl:Math.min(c.access_ttl_seconds,policy.accessTtl),refreshTtl:Math.min(c.refresh_ttl_seconds,policy.refreshTtl)\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/22.协议客户端共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bebfeef631034f65a51e93385507b8d0',NULL,'function','{\n  "properties": {},\n  "id": "b8e9f119f73a5c5d80fef296a2d55079",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "23.协议访问授权校验",\n  "createTime": 1790635007936,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/protocol-access",\n  "description": "验证统一认证令牌的应用受众、客户端状态和实时有效授权，拒绝已撤销访问。",\n  "parameters": [\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：23.协议访问授权校验\n// 业务说明：验证统一认证令牌的应用受众、客户端状态和实时有效授权，拒绝已撤销访问。\n// 函数输入：payload：请求资料或筛选条件。\n// 返回与副作用：验证统一认证令牌的应用受众、客户端状态和实时有效授权，拒绝已撤销访问。\nimport db;\nimport identityProtocol;\nimport authSession;\nimport \'@/idaas/effective-access\' as effective;\nimport \'@/idaas/resource-enabled\' as enabled;\nimport \'@/idaas/auth-session-policy\' as sessionPolicy;\n\n// 只有框架协议桥接可调用此函数，普通 Magic 请求不能伪造认证主体。\nif(!identityProtocol.isTrusted()) {\n    exit 403,\'认证主体判断只允许框架调用\';\n}\nvar sql=db.normal();\nvar p=payload||{};\nvar account=(id)=>sql.selectOne("""\nselect a.*,a.tid as id,s.status subject_status,s.is_del subject_deleted,sec.security_version\nfrom iam_auth_account_t a\njoin iam_subject_t s on s.tid=a.subject_id\nand s.identity_domain=a.identity_domain\njoin iam_account_security_t sec on sec.principal_kind=\'AUTH_ACCOUNT\'\nand sec.principal_id=a.tid\nwhere a.tid=#{id}\n    and a.status=\'ACTIVE\'\n    and a.is_del=0\n""");\n// 实时检查账号、人员及法人办理资格，不以令牌中的旧权限快照替代当前状态。\nvar eligible=(a)=>a!=null && a.subject_status==\'ACTIVE\' && a.subject_deleted==0 && a.must_change_password==0 && (a.legal_entity_id==null || sql.selectOne("""\nselect m.tid as id\nfrom iam_legal_member_t m\njoin iam_legal_entity_t e on e.tid=m.entity_id\nand e.status=\'ACTIVE\'\nand e.is_del=0\nand e.verification_status=\'VERIFIED\'\nand exists\n    (select 1\n     from iam_verification_t v\n     where v.target_type=\'LEGAL_ENTITY\'\n         and v.target_id=e.tid\n         and v.status=\'VERIFIED\'\n         and v.expires_at>utc_timestamp(6)\n         and v.tid=\n             (select x.tid as id\n              from iam_verification_t x\n              where x.target_type=\'LEGAL_ENTITY\'\n                  and x.target_id=e.tid\n              order by x.requested_time desc, x.tid desc\n              limit 1))\nwhere m.entity_id=#{a.legal_entity_id}\n    and m.subject_id=#{a.subject_id}\n    and (m.auth_account_id is null\n         or m.auth_account_id=#{a.id})\n    and m.status=\'ACTIVE\'\n    and m.is_del=0\n    and m.valid_from<=utc_timestamp(6)\n    and (m.valid_until is null\n         or m.valid_until>utc_timestamp(6))\nlimit 1\n""")!=null);\n// 主体解析先核验账号和会话，再把可用的认证身份返回协议桥接层。\nif(p.operation==\'principal\') {\n    var policy=sessionPolicy(\'read\',null);\n    var principal=authSession.principal(p.token,policy.idleSeconds);\n    if(principal.id==null) {\n        return {\n            allowed:false\n        };\n    }\n    var a=account(principal.id);\n    return eligible(a) && principal.securityVersion==a.security_version?{\n        allowed:true,accountId:a.id,subjectId:a.subject_id,domain:a.identity_domain\n    }\n    :{\n        allowed:false\n    };\n}\nvar client=sql.selectOne("""\nselect c.*,c.tid as id\nfrom iam_auth_client_t c\njoin iam_application_t app on app.tid=c.app_id\nand app.kind=\'BUSINESS\'\nand app.auth_mode=\'FEDERATED\'\nand app.status=\'ACTIVE\'\nand app.is_del=0\nwhere c.tid=#{p.clientId}\n    and c.status=\'ACTIVE\'\n    and c.protocol=\'OIDC\'\n    and c.is_del=0\n""");\nif(client==null) {\n    return {\n        allowed:false\n    };\n}\nvar finish=(result)=>{\n    if(p.operation!=\'api\') {\n        return result;\n    }\n    if(!result.allowed || p.appId!=result.appId) {\n        return {\n            allowed:false\n        };\n    }\n    var matched=sql.select("""\nselect tid as id\nfrom iam_resource_t\nwhere app_id=#{result.appId}\n    and identity_domain=#{result.domain}\n    and resource_type=\'API\'\n    and path=#{p.path}\n    and http_method=#{p.method}\n    and status=\'ACTIVE\'\n    and is_del=0\n""").filter(r=>result.resourceIds.contains(r.id));\n    if(matched.size()==0) {\n        return {\n            allowed:false\n        };\n    }\n    return {\n        allowed:true,appId:result.appId,domain:result.domain,principalId:result.principalId,principalKind:p.machine==true?\'CLIENT\':\'AUTH_ACCOUNT\',resourceIds:matched.map(r=>r.id)\n    };\n};\nif(p.machine==true) {\n    if(client.client_type!=\'SERVICE\') {\n        return {\n            allowed:false\n        };\n    }\n    var grants=sql.select("""\nselect tid as id,identity_domain\nfrom iam_access_grant_t\nwhere principal_type=\'CLIENT\'\n    and client_id=#{client.id}\n    and app_id=#{client.app_id}\n    and status=\'ACTIVE\'\n    and is_del=0\n    and valid_from<=utc_timestamp(6)\n    and (valid_until is null\n         or valid_until>utc_timestamp(6))\n""");\n    if(grants.size()==0) {\n        return {\n            allowed:false\n        };\n    }\n    var domains=[];\n    for(g in grants) {\n        if(!domains.contains(g.identity_domain)) {\n            domains.add(g.identity_domain);\n        }\n    }\n    if(domains.size()!=1) {\n        return {\n            allowed:false\n        };\n    }\n    var domain=domains[0];\n    var roles=sql.select("""\nselect distinct r.tid as id\nfrom iam_grant_role_rela_t rr\njoin iam_access_grant_t g on g.tid=rr.grant_id\nand g.principal_type=\'CLIENT\'\nand g.client_id=#{client.id}\nand g.app_id=#{client.app_id}\nand g.status=\'ACTIVE\'\nand g.is_del=0\nand g.valid_from<=utc_timestamp(6)\nand (g.valid_until is null\n     or g.valid_until>utc_timestamp(6))\njoin iam_role_t r on r.tid=rr.role_id\nand r.app_id=g.app_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\n""").map(r=>r.id);\n    var resources=sql.select("""\nselect distinct res.tid as id\nfrom iam_resource_t res\njoin iam_role_resource_rela_t rr on rr.resource_id=res.tid\nand rr.app_id=res.app_id\njoin iam_role_t r on r.tid=rr.role_id\nand r.status=\'ACTIVE\'\nand r.is_del=0\njoin iam_grant_role_rela_t gr on gr.role_id=r.tid\njoin iam_access_grant_t g on g.tid=gr.grant_id\nand g.client_id=#{client.id}\nand g.principal_type=\'CLIENT\'\nand g.app_id=#{client.app_id}\nand g.status=\'ACTIVE\'\nand g.is_del=0\nand g.valid_from<=utc_timestamp(6)\nand (g.valid_until is null\n     or g.valid_until>utc_timestamp(6))\nwhere res.app_id=#{client.app_id}\n    and res.resource_type=\'API\'\n    and res.status=\'ACTIVE\'\n    and res.is_del=0\n""").map(r=>r.id);\n    resources=enabled(client.app_id,domain,resources);\n    return finish({\n        allowed:true,appId:client.app_id,domain:domain,roleIds:roles,resourceIds:resources,principalId:client.id,securityVersion:client.version\n    });\n}\nvar a=account(p.principalName);\nif(!eligible(a)) {\n    return {\n        allowed:false\n    };\n}\n// 访问令牌最终权限以当前应用的实时有效授权为准，撤销后立即失效。\nvar access=effective(a.subject_id,client.app_id,a.identity_domain);\nreturn finish({\n    allowed:access.hasAccess,appId:client.app_id,accountId:a.id,subjectId:a.subject_id,domain:a.identity_domain,roleIds:access.roleIds,resourceIds:access.resourceIds,principalId:a.id,securityVersion:a.security_version\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/23.协议访问授权校验.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('6dc55d92351449aa806c2f784ac2dd7e',NULL,'function','{\n  "properties": {},\n  "id": "3abcf6298afb5031ab99f4c9897f4809",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "24.协议配置持久化",\n  "createTime": 1790635007936,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/protocol-store",\n  "description": "以控制库保存或读取协议客户端与联邦配置，保护敏感凭据和版本。",\n  "parameters": [\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：24.协议配置持久化\n// 业务说明：以控制库保存或读取协议客户端与联邦配置，保护敏感凭据和版本。\n// 函数输入：payload：请求资料或筛选条件。\n// 返回与副作用：以控制库保存或读取协议客户端与联邦配置，保护敏感凭据和版本。\nimport db;\nimport identityProtocol;\nimport identityTransport;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.crypto.digest.DigestUtil;\nimport \'@/idaas/protocol-access\' as access;\n\n// 框架状态、令牌摘要和轮换族均留在baseline；不向业务应用用户表写入凭据。\nif(!identityProtocol.isTrusted()) {\n    exit 403,\'协议状态只允许框架调用\';\n}\nvar sql=db.normal();\nvar p=payload||{};\nvar op=p.operation;\nvar hash=(v)=>v==null?null:DigestUtil.sha256Hex(v);\nif(op.endsWith(\'consent\')) {\n    var key=\'consent:\'+p.clientId+\':\'+p.principalName;\n    var fingerprint=hash(key);\n    if(op==\'find-consent\') {\n        var row=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_session_t\nwhere session_fingerprint=#{fingerprint}\n    and revoked_at is null\n    and expires_at>utc_timestamp(6)\n""");\n        return row==null?{}:identityTransport.parseJson(identityTransport.unprotectState(row.authorization_cipher,key));\n    }\n    // 把读取校验和状态写入放在同一事务，防止并发覆盖。\n    return sql.transaction(()=>{\n        if(op==\'remove-consent\') {\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CONSENT_REVOKED\'\nwhere session_fingerprint=#{fingerprint}\n""");\n            return {\n                removed:true\n            };\n        }\n        var id=IdUtil.fastSimpleUUID();\n        var encoded=identityTransport.protectState(identityTransport.canonicalJson({\n            authorities:p.authorities\n        }),key);\n        sql.update("""\ninsert into iam_auth_session_t(tid,\n                principal_kind, principal_id, client_id, session_fingerprint, security_version, issued_at,\n                expires_at, authorization_key, authorization_cipher)\nvalues(#{id},\'AUTH_ACCOUNT\',#{p.principalName},#{p.clientId},#{fingerprint},1,utc_timestamp(6),date_add(utc_timestamp(6),interval 30 day),#{key},#{encoded}) on duplicate key\nupdate authorization_cipher=#{encoded},revoked_at=null,expires_at=date_add(utc_timestamp(6),interval 30 day),version=version+1\n""");\n        return {\n            saved:true\n        };\n    });\n}\nif(op==\'remove\') {\n    sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'PROTOCOL_REVOKED\',version=version+1\nwhere authorization_key=#{p.id}\n""");\n    return {\n        removed:true\n    };\n}\nif(op==\'save\' && p.revoked==true) {\n    sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'TOKEN_REVOKED\',version=version+1\nwhere authorization_key=#{p.id}\n    and revoked_at is null\n""");\n    return {\n        saved:true\n    };\n}\nif(op==\'find\') {\n    var tokenHash=hash(p.token);\n    var row=p.id!=null?sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_session_t\nwhere authorization_key=#{p.id}\n"""):sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_session_t\nwhere code_fingerprint=#{tokenHash}\n    or access_fingerprint=#{tokenHash}\n    or refresh_fingerprint=#{tokenHash}\n    or state_fingerprint=#{tokenHash}\nlimit 1\n""");\n    if(row==null && p.token!=null) {\n        var consumed=sql.selectOne("""\nselect result_json\nfrom iam_request_receipt_t\nwhere operation_code=\'PROTOCOL_REFRESH_CONSUMED\'\n    and request_id=#{tokenHash}\n""");\n        if(consumed!=null) {\n            var family=identityTransport.parseJson(consumed.result_json).family;\n            sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'REFRESH_REPLAY\',version=version+1\nwhere family_id=#{family}\n""");\n        }\n        return {};\n    }\n    if(row==null || row.revoked_at!=null || sql.selectOne("""\nselect tid as id\nfrom iam_auth_session_t\nwhere tid=#{row.id}\n    and expires_at>utc_timestamp(6)\n""")==null) {\n        return {};\n    }\n    var ok=access({\n        operation:\'issue\',clientId:row.client_id,principalName:row.principal_id,machine:row.principal_kind==\'CLIENT\'\n    });\n    if(!ok.allowed || ok.securityVersion!=row.security_version) {\n        return {};\n    }\n    return {\n        state:identityTransport.unprotectState(row.authorization_cipher,row.authorization_key)\n    };\n}\nif(op!=\'save\') {\n    exit 400,\'协议状态操作不正确\';\n}\nreturn sql.transaction(()=>{\n    var permission=access({\n        operation:\'issue\',clientId:p.clientId,principalName:p.principalName,machine:p.grant==\'client_credentials\'\n    });\n    if(!permission.allowed) {\n        exit 403,\'认证资格已失效\';\n    }\n    var old=sql.selectOne("""\nselect *,tid as id\nfrom iam_auth_session_t\nwhere authorization_key=#{p.id}\n    for update\n""");\n    if(old!=null && old.revoked_at!=null) {\n        exit 403,\'认证会话已撤销\';\n    }\n    var id=old==null?IdUtil.fastSimpleUUID():old.id;\n    var principal=permission.principalId;\n    var kind=p.grant==\'client_credentials\'?\'CLIENT\':\'AUTH_ACCOUNT\';\n    var fingerprint=hash(\'authorization:\'+p.id);\n    var code=hash(p.code);\n    var token=hash(p.access);\n    var refresh=hash(p.refresh);\n    var stateHash=hash(p.stateValue);\n    var cipher=identityTransport.protectState(p.state,p.id);\n    var family=old==null?IdUtil.fastSimpleUUID():old.family_id;\n    var client=sql.selectOne("""\nselect access_ttl_seconds,refresh_ttl_seconds\nfrom iam_auth_client_t\nwhere tid=#{p.clientId}\n""");\n    var ttl=p.refresh==null?client.access_ttl_seconds:client.refresh_ttl_seconds;\n    if(old!=null && old.refresh_fingerprint!=null && old.refresh_fingerprint!=refresh) {\n        var rid=IdUtil.fastSimpleUUID();\n        var result=identityTransport.canonicalJson({\n            family:family\n        });\n        sql.update("""\ninsert into iam_request_receipt_t(tid,\n                operator_id, operation_code, request_id, request_hash, status, result_json)\nvalues(#{rid},#{principal},\'PROTOCOL_REFRESH_CONSUMED\',#{old.refresh_fingerprint},#{old.refresh_fingerprint},\'SUCCEEDED\',#{result}) on duplicate key\nupdate tid=tid\n""");\n    }\n    if(old==null) {\n        sql.update("""\ninsert into iam_auth_session_t(tid,\n                principal_kind, principal_id, client_id, app_id, session_fingerprint, family_id,\n                security_version, issued_at, expires_at, authorization_key, authorization_cipher, code_fingerprint,\n                access_fingerprint, refresh_fingerprint, state_fingerprint)\nvalues(#{id},#{kind},#{principal},#{p.clientId},#{permission.appId},#{fingerprint},#{family},#{permission.securityVersion},utc_timestamp(6),date_add(utc_timestamp(6),interval #{ttl} second),#{p.id},#{cipher},#{code},#{token},#{refresh},#{stateHash})\n""");\n    }\n    else {\n        sql.update("""\nupdate iam_auth_session_t\nset authorization_cipher=#{cipher},code_fingerprint=#{code},access_fingerprint=#{token},\n    previous_refresh_fingerprint=case\n        when refresh_fingerprint<>#{refresh} then refresh_fingerprint else previous_refresh_fingerprint\n        end,refresh_fingerprint=#{refresh},\n        state_fingerprint=#{stateHash},\n        expires_at=date_add(utc_timestamp(6),interval #{ttl} second),version=version+1,\n        updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n    }\n    return {\n        saved:true\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/24.协议配置持久化.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('40e59c357acf414982d15264c2714def',NULL,'function','{\n  "properties": {},\n  "id": "4d54c6e215625d9ca6220ca6477b5d6c",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "25.统一认证账号上下文",\n  "createTime": 1790635007936,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/auth-account-context",\n  "description": "核验统一认证账号会话并读取人员、法人办理身份和安全版本，区别于平台操作人上下文。",\n  "parameters": [],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：25.统一认证账号上下文\n// 业务说明：核验统一认证账号会话并读取人员、法人办理身份和安全版本，区别于平台操作人上下文。\n// 函数输入：无显式参数；从当前 Magic 执行上下文读取会话或请求信息。\n// 返回与副作用：核验统一认证账号会话并读取人员、法人办理身份和安全版本，区别于平台操作人上下文。\nimport db;\nimport authSession;\nimport \'@/idaas/auth-session-policy\' as sessionPolicy;\n\n// 统一认证会话按独立的空闲时长校验，不能复用管理控制台登录态。\nvar policy=sessionPolicy(\'read\',null);\nif(!authSession.isLogin(policy.idleSeconds)) {\n    exit 401,\'请使用统一认证账号登录\';\n}\nvar id=authSession.id();\nvar sql=db.normal();\nvar a=sql.selectOne("""\nselect a.*,a.tid as id,s.security_version,subject.name\nfrom iam_auth_account_t a\njoin iam_account_security_t s on s.principal_kind=\'AUTH_ACCOUNT\'\nand s.principal_id=a.tid\njoin iam_subject_t subject on subject.tid=a.subject_id\nand subject.identity_domain=a.identity_domain\nand subject.status=\'ACTIVE\'\nand subject.is_del=0\nwhere a.tid=#{id}\n    and a.status=\'ACTIVE\'\n    and a.is_del=0\n""");\n// 账号停用或安全版本变化时立即撤销旧会话，阻止旧令牌继续使用。\nif(a==null || authSession.session().get(\'securityVersion\')!=a.security_version) {\n    authSession.logout();\n    exit 401,\'统一认证账号的安全状态已变更\';\n}\nreturn {\n    userId:a.id,account:a,actorKind:\'AUTH_ACCOUNT\',requiredDomain:a.identity_domain,permissions:[],pairs:[]\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/25.统一认证账号上下文.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f18035420d13436dab32346d89f9d0e1',NULL,'function','{\n  "properties": {},\n  "id": "cf6a9cc605f155d0a54adfbb783abec6",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "26.公众法人共用规则",\n  "createTime": 1790635007936,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/public-entities",\n  "description": "校验法人资料及成员关系、办理身份和状态，供法人管理及自主登记接口复用。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：26.公众法人共用规则\n// 业务说明：校验法人资料及成员关系、办理身份和状态，供法人管理及自主登记接口复用。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：校验法人资料及成员关系、办理身份和状态，供法人管理及自主登记接口复用。\nimport db;\nimport cn.hutool.core.util.IdUtil;\nimport cn.hutool.json.JSONUtil;\nimport \'@/idaas/guard\' as guard;\nimport \'@/idaas/mutate\' as mutate;\nimport \'@/idaas/audit\' as audit;\nimport \'@/idaas/time-window\' as timeWindow;\n\nvar sql=db.normal();\nvar p=payload||{};\nvar r=p.record||p;\n// 先校验当前会话的功能权限、身份域和应用管理范围。\nvar ctx=guard(operation==\'list\'?\'public:read\':\'public:write\',null,\'public\');\nvar id=r.id||p.id;\n// 列表分支：先确定当前操作人可见的应用和身份域，再读取并映射业务记录。\nif(operation==\'list\') {\n    return sql.select("""\nselect *,tid as id,date_format(created_time, \'%Y-%m-%dT%H:%i:%sZ\') created_utc,\n       date_format(updated_time, \'%Y-%m-%dT%H:%i:%sZ\') updated_utc\nfrom iam_legal_entity_t\nwhere is_del=0\norder by created_time desc\nlimit 250\n""").map(e=>{\n        var members=sql.select("""\nselect m.*,m.tid as id,s.name,s.phone\nfrom iam_legal_member_t m\njoin iam_subject_t s on s.tid=m.subject_id\nand s.identity_domain=\'public\'\nwhere m.entity_id=#{e.id}\n    and m.is_del=0\n    and m.status in (\'PENDING\',\'ACTIVE\')\n""");\n        var contact=members.filter(m=>m.relation_type==\'AGENT\');\n        return {\n            id:e.id,version:e.version,domain:\'public\',name:e.name,code:e.code,registrationCode:e.registration_code||\'\',status:e.status==\'ACTIVE\'?\'enabled\':\'disabled\',contactId:contact.size()==0?\'\':contact[0].subject_id,contact:contact.size()==0?\'\':contact[0].name,phone:contact.size()==0?\'\':contact[0].phone||\'\',verified:e.verification_status==\'VERIFIED\' && sql.selectOne("""\nselect tid as id\nfrom iam_verification_t\nwhere target_type=\'LEGAL_ENTITY\'\n    and target_id=#{e.id}\n    and status=\'VERIFIED\'\n    and expires_at>utc_timestamp(6)\n    and tid=\n        (select x.tid as id\n         from iam_verification_t x\n         where x.target_type=\'LEGAL_ENTITY\'\n             and x.target_id=#{e.id}\n         order by x.requested_time desc,x.tid desc\n         limit 1)\n""")!=null,verificationStatus:e.verification_status,subAccountIds:members.filter(m=>m.relation_type==\'SUBACCOUNT\').map(m=>m.subject_id),members:members,createdAt:e.created_utc,updatedAt:e.updated_utc\n        };\n    });\n}\n// 写入通过共享的幂等事务处理，并记录审计；版本冲突直接返回。\n// 事务边界：通过共享幂等写入统一处理版本冲突、提交与审计。\nreturn mutate(ctx,\'public-entities:\'+operation,p,()=>{\n    var old=id==null?null:sql.selectOne("""\nselect *,tid as id\nfrom iam_legal_entity_t\nwhere tid=#{id}\n    and is_del=0\n    for update\n""");\n    if(old!=null && old.version!=(r.version||p.version)) {\n        exit 409,\'法人记录已变更\';\n    }\n    // 成员启用分支：校验法人及账号关系，再启用办理身份。\n    if(operation==\'activate-member\' || operation==\'revoke-member\') {\n        var member=sql.selectOne("""\nselect *,tid as id\nfrom iam_legal_member_t\nwhere tid=#{p.memberId}\n    and entity_id=#{id}\n    and is_del=0\n    for update\n""");\n        if(member==null || member.version!=p.memberVersion || p.reason==null || p.reason.trim()==\'\') {\n            exit 409,\'请核对关系版本并填写授权理由\';\n        }\n        var status=operation==\'activate-member\'?\'ACTIVE\':\'REVOKED\';\n        var window=timeWindow(p.validFrom,p.validUntil);\n        sql.update("""\nupdate iam_legal_member_t\nset status=#{status},valid_from=#{window.start},valid_until=#{window.end},version=version+1\nwhere tid=#{member.id}\n""");\n        audit(ctx,\'SUCCESS\',\'public-entities:\'+operation,member.id,null,{\n            entityId:id,memberId:member.id,reason:p.reason,validFrom:window.start,validUntil:window.end\n        });\n        return {\n            id:id\n        };\n    }\n    // 归档分支：验证版本及引用关系，保留历史记录并撤销有效关联。\n    if(operation==\'remove\') {\n        if(old==null) {\n            exit 404,\'法人记录不存在\';\n        }\n        sql.update("""\nupdate iam_legal_entity_t\nset status=\'ARCHIVED\',is_del=1,version=version+1\nwhere tid=#{id}\n""");\n        sql.update("""\nupdate iam_legal_member_t\nset status=\'REVOKED\',version=version+1\nwhere entity_id=#{id}\n""");\n        audit(ctx,\'SUCCESS\',\'public-entities:remove\',id,null,{\n            id:id\n        });\n        return {\n            id:id\n        };\n    }\n    var name=(r.name||\'\').trim();\n    var code=(r.code||\'\').trim();\n    var registration=(r.registrationCode||\'\').trim().toUpperCase();\n    if(name==\'\' || name.length()>200 || !code.matches(\'[A-Za-z0-9_.:-]{2,100}\') || old!=null && old.code!=code || registration!=\'\' && !registration.matches(\'[0-9A-HJ-NPQRTUWXY]{18}\')) {\n        exit 400,\'法人名称、稳定编码或信用代码格式不正确\';\n    }\n    if(r.verified==true && (old==null || old.verification_status!=\'VERIFIED\')) {\n        exit 400,\'登记和维护不能直接设置核验通过\';\n    }\n    var persons=r.subAccountIds||[];\n    if(r.contactId!=null && r.contactId!=\'\' && !persons.contains(r.contactId)) {\n        persons.add(r.contactId);\n    }\n    if(persons.size()>200) {\n        exit 400,\'关联人数超限\';\n    }\n    for(person in persons) {\n        if(sql.selectOne("""\nselect tid as id\nfrom iam_subject_t\nwhere tid=#{person}\n    and identity_domain=\'public\'\n    and is_del=0\n""")==null) {\n            exit 400,\'法人关系只能关联公众自然人\';\n        }\n    }\n    var credit=registration==\'\'?null:registration;\n    var status=r.status==\'disabled\'?\'DISABLED\':\'ACTIVE\';\n    if(old==null) {\n        if(p.creating!=true) {\n            exit 404,\'法人记录不存在\';\n        }\n        id=IdUtil.fastSimpleUUID();\n        sql.update("""\ninsert into iam_legal_entity_t(tid, code, name, registration_code, status)\nvalues(#{id},#{code},#{name},#{credit},#{status})\n""");\n    }\n    else {\n        sql.update("""\nupdate iam_legal_entity_t\nset verification_status=case\n        when name<>#{name}\n        or not(registration_code<=>#{credit}) then \'UNVERIFIED\' else verification_status\n        end,name=#{name},registration_code=#{credit},\n        status=#{status},version=version+1,updated_time=utc_timestamp(6)\nwhere tid=#{id}\n""");\n    }\n    var prior=sql.select("""\nselect *,tid as id\nfrom iam_legal_member_t\nwhere entity_id=#{id}\n    and is_del=0\n""");\n    for(member in prior) {\n        var type=member.subject_id==r.contactId?\'AGENT\':\'SUBACCOUNT\';\n        if(!persons.contains(member.subject_id) || type!=member.relation_type) {\n            sql.update("""\nupdate iam_legal_member_t\nset status=\'REVOKED\',is_del=1,version=version+1\nwhere tid=#{member.id}\n""");\n        }\n    }\n    for(person in persons) {\n        var type=person==r.contactId?\'AGENT\':\'SUBACCOUNT\';\n        if(prior.filter(m=>m.subject_id==person && m.relation_type==type && m.is_del==0 && m.status!=\'REVOKED\').size()==0) {\n            var mid=IdUtil.fastSimpleUUID();\n            sql.update("""\ninsert into iam_legal_member_t(tid,\n                entity_id, subject_id, relation_type, valid_from, status)\nvalues(#{mid},#{id},#{person},#{type},utc_timestamp(6),\'PENDING\')\n""");\n        }\n    }\n    audit(ctx,\'SUCCESS\',\'public-entities:save\',id,null,{\n        id:id,memberCount:persons.size()\n    });\n    return {\n        id:id\n    };\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/26.公众法人共用规则.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ceb5aa39a81f4a26b053797794476f1f',NULL,'function','{\n  "properties": {},\n  "id": "3171a186086b59bd9f7a06bfb8754286",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "27.资源启用状态判断",\n  "createTime": 1790636427981,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/resource-enabled",\n  "description": "按应用、角色和资源状态判断业务功能是否可用，供授权计算和接口保护共用。",\n  "parameters": [\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "人员或公众身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "resourceIds",\n      "value": null,\n      "description": "目标应用资源标识集合",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：27.资源启用状态判断\n// 业务说明：按应用、角色和资源状态判断业务功能是否可用，供授权计算和接口保护共用。\n// 函数输入：appId：目标业务应用标识；identityDomain：人员或公众身份域；resourceIds：目标应用资源标识集合。\n// 返回与副作用：按应用、角色和资源状态判断业务功能是否可用，供授权计算和接口保护共用。\nimport db;\n\n// 资源祖先也是授权条件；父级缺失、停用、删除或形成环时，子资源一并拒绝。\nvar rows=db.normal().select("""\nselect tid as id,parent_id,status,is_del\nfrom iam_resource_t\nwhere app_id=#{appId}\n    and identity_domain=#{identityDomain}\n""");\nreturn (resourceIds||[]).filter(id=>{\n    var seen=[];\n    var current=id;\n    // 沿父资源逐级检查；缺失、停用、删除或出现环均拒绝该资源。\n    while(current!=null) {\n        if(seen.contains(current) || seen.size()>=50) {\n            return false;\n        }\n        seen.add(current);\n        var row=rows.filter(r=>r.id==current);\n        if(row.size()!=1 || row[0].status!=\'ACTIVE\' || row[0].is_del!=0) {\n            return false;\n        }\n        current=row[0].parent_id;\n    }\n    return true;\n});\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/27.资源启用状态判断.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('9e4cb2e6e67748feb1cc74074a3391fd',NULL,'function','{\n  "properties": {},\n  "id": "3f620a5ff088578cac61376a5a48bf70",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "28.统一认证会话策略",\n  "createTime": 1790641170352,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/auth-session-policy",\n  "description": "按统一认证账号读取会话时长、并发数量和撤销策略，供登录、续期和会话管理共用；仅返回策略，不直接创建会话。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "accountId",\n      "value": null,\n      "description": "统一认证账号标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：28.统一认证会话策略\n// 业务说明：按统一认证账号读取会话时长、并发数量和撤销策略，供登录、续期和会话管理共用；仅返回策略，不直接创建会话。\n// 函数输入：operation：本次执行的业务操作；accountId：统一认证账号标识。\n// 返回与副作用：按统一认证账号读取会话时长、并发数量和撤销策略，供登录、续期和会话管理共用；仅返回策略，不直接创建会话。\nimport db;\nimport cn.hutool.json.JSONUtil;\n\n// 可编辑会话规则在Magic；Java只执行传入的空闲秒数与并发会话参数。\nvar sql=db.normal();\nvar row=sql.selectOne("""\nselect value_json\nfrom iam_setting_t\nwhere scope_kind=\'GLOBAL\'\n    and scope_key=\'global\'\n    and category=\'SSO\'\n    and config_key=\'session\'\n    and status=\'ACTIVE\'\n    and is_del=0\n""");\nvar value=row==null?{}:JSONUtil.parseObj(row.value_json);\nvar policy={\n    accessTtl:value.accessTtl||600,refreshTtl:value.refreshTtl||86400,idleSeconds:(value.idleMinutes||30)*60,allowConcurrent:value.allowConcurrent!=false\n};\n// 签发新会话且禁止并发时，先撤销同账号未撤销的旧会话。\nif(operation==\'issue\' && policy.allowConcurrent==false) {\n    sql.update("""\nupdate iam_auth_session_t\nset revoked_at=utc_timestamp(6),revoke_reason=\'CONCURRENT_LOGIN\',version=version+1\nwhere principal_kind=\'AUTH_ACCOUNT\'\n    and principal_id=#{accountId}\n    and revoked_at is null\n""");\n}\nreturn policy;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/28.统一认证会话策略.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7dab2c39c2904e6389770aa26049c8bf',NULL,'function','{\n  "properties": {},\n  "id": "ddfd5d8289e95bbc85e62d8708f45b6d",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "29.只读应用本地现状",\n  "createTime": 1790813253492,\n  "updateTime": 1790949884838,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/local-inventory",\n  "description": "按已核验的运行绑定读取租户人员、机构、角色及资源汇总；不向控制库导入或改写租户数据。",\n  "parameters": [\n    {\n      "name": "operation",\n      "value": null,\n      "description": "本次执行的业务操作",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "payload",\n      "value": null,\n      "description": "请求资料或筛选条件",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：29.只读应用本地现状\n// 业务说明：按已核验的运行绑定读取租户人员、机构、角色及资源汇总；不向控制库导入或改写租户数据。\n// 函数输入：operation：本次执行的业务操作；payload：请求资料或筛选条件。\n// 返回与副作用：按已核验的运行绑定读取租户人员、机构、角色及资源汇总；不向控制库导入或改写租户数据。\nimport db;\nimport identityRuntime;\nimport \'@/idaas/guard\' as guard;\n\n// 从已核验的运行绑定只读租户本地目录；写入只能由显式的手动导入接口处理。\n// 本地账号、密码、角色授权与中央人员/授权始终是两个体系。\nvar p=payload||{};\nvar appId=\'\'+(p.appId||\'\');\nvar domain=p.domain||\'workforce\';\nif(!appId.matches(\'[A-Za-z0-9_.:-]{1,64}\') || domain!=\'workforce\') {\n    exit 400,\'应用或身份域不正确\';\n}\nguard(\'apps:read\',appId,domain);\nguard(\'users:read\',appId,domain);\nguard(\'grants:read\',appId,domain);\nif(operation!=\'counts\') {\n    guard(\'orgs:read\',appId,domain);\n    guard(\'roles:read\',appId,domain);\n    guard(\'resources:read\',appId,domain);\n}\nvar sql=db.normal();\nvar binding=sql.selectOne("""\nselect rt.runtime_tenant_id,rt.local_permission_app_id,rt.binding_status\nfrom iam_application_runtime_t rt\njoin iam_application_t a on a.tid=rt.app_id\nand a.kind=\'BUSINESS\'\nand a.is_del=0\nwhere rt.app_id=#{appId}\n""");\nif(binding==null || binding.binding_status!=\'VERIFIED\' || binding.local_permission_app_id==null) {\n    return {\n        available:false,reason:\'请先核验应用连接\',counts:{\n            users:0,orgs:0,roles:0,resources:0,authorizedUsers:0\n        }\n    };\n}\nvar tenantId=binding.runtime_tenant_id;\nvar localApp=binding.local_permission_app_id;\nidentityRuntime.inspectTenantBinding(tenantId);\n// 汇总分支：只读取租户现有数据并统计，不执行导入或下发。\nif(operation==\'counts\') {\n    // 按已核验的运行绑定进入目标租户库，避免把租户数据写入控制库。\n    return identityRuntime.inTenant(tenantId,()=>{\n        var tenantSql=db.normal();\n        var people=tenantSql.selectOne("""\nselect count(*) n\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\n""");\n        var authorized=tenantSql.selectOne("""\nselect count(distinct u.user_id) n\nfrom rm_user_role_rela_t u\njoin rm_user_t person on person.id=u.user_id\nand person.tenant_id=u.tenant_id\nand person.deleted=0\nand person.status=0\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null\n         or u.end_time>current_timestamp)\n""");\n        return {\n            available:true,source:\'TENANT_LOCAL\',counts:{\n                users:people.n,authorizedUsers:authorized.n\n            }\n        };\n    });\n}\nvar local=identityRuntime.inTenant(tenantId,()=>{\n    var tenantSql=db.normal();\n    var people=tenantSql.select("""\nselect id,real_name name,user_name account,status\nfrom rm_user_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\norder by id\n""");\n    var organizations=tenantSql.select("""\nselect id,name,dept_code code,parent_id,status\nfrom rm_org_t\nwhere tenant_id=#{tenantId}\n    and deleted=0\n    and id<>\'ROOT\'\norder by org_path,id\n""");\n    var roles=tenantSql.select("""\nselect id,name,code_num code,status\nfrom rm_role_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\norder by id\n""");\n    var menus=tenantSql.select("""\nselect id,name,code,url,status,resource_type\nfrom rm_menu_t\nwhere tenant_id=#{tenantId}\n    and app_id=#{localApp}\n    and deleted=0\norder by sort_num,id\n""");\n    var userOrgs=tenantSql.select("""\nselect u.user_id,u.org_id\nfrom rm_user_org_rela_t u\njoin rm_org_t o on o.id=u.org_id\nand o.tenant_id=u.tenant_id\nand o.deleted=0\nwhere u.tenant_id=#{tenantId}\norder by u.user_id,u.job_type,u.id\n""");\n    var userRoles=tenantSql.select("""\nselect distinct u.user_id,u.role_id\nfrom rm_user_role_rela_t u\njoin rm_user_t person on person.id=u.user_id\nand person.tenant_id=u.tenant_id\nand person.deleted=0\nand person.status=0\njoin rm_role_t r on r.id=u.role_id\nand r.tenant_id=u.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\nand r.status=0\nwhere u.tenant_id=#{tenantId}\n    and coalesce(u.auth_from, 0)<>9\n    and (u.end_time is null\n         or u.end_time>current_timestamp)\norder by u.user_id,u.role_id\n""");\n    var roleMenus=tenantSql.select("""\nselect distinct x.role_id,x.app_resource_id\nfrom rm_role_menu_rela_t x\njoin rm_role_t r on r.id=x.role_id\nand r.tenant_id=x.tenant_id\nand r.app_id=#{localApp}\nand r.deleted=0\njoin rm_menu_t m on m.id=x.app_resource_id\nand m.tenant_id=x.tenant_id\nand m.app_id=#{localApp}\nand m.deleted=0\nwhere x.tenant_id=#{tenantId}\norder by x.role_id,x.app_resource_id\n""");\n    var orgName=(id)=>{\n        if(id==null || id==\'ROOT\') {\n            return \'根机构\';\n        }\n        var found=organizations.filter(row=>row.id==id);\n        return found.size()==0?\'关联机构已移除\':found[0].name;\n    };\n    var roleName=(id)=>{\n        var found=roles.filter(row=>row.id==id);\n        return found.size()==0?\'关联角色已移除\':found[0].name;\n    };\n    var userRows=people.map(row=>{\n        var orgIds=userOrgs.filter(link=>link.user_id==row.id).map(link=>link.org_id).distinct();\n        var roleIds=userRoles.filter(link=>link.user_id==row.id).map(link=>link.role_id).distinct();\n        return {\n            id:row.id,name:row.name,account:row.account,status:row.status==0?\'enabled\':\'disabled\',orgIds:orgIds,orgNames:orgIds.map(orgName),roleNames:roleIds.map(roleName),authorized:row.status==0 && roleIds.size()>0\n        };\n    });\n    var orgRows=organizations.map(row=>({\n        id:row.id,name:row.name,code:row.code,parentId:row.parent_id,parentName:orgName(row.parent_id),status:row.status==0?\'enabled\':\'disabled\'\n    }));\n    var roleRows=roles.map(row=>({\n        id:row.id,name:row.name,code:row.code,status:row.status==0?\'enabled\':\'disabled\',userCount:userRoles.filter(link=>link.role_id==row.id).map(link=>link.user_id).distinct().size(),resourceCount:roleMenus.filter(link=>link.role_id==row.id).size()\n    }));\n    var resourceRows=menus.map(row=>({\n        id:row.id,name:row.name,code:row.code,path:row.url,status:row.status==0?\'enabled\':\'disabled\',type:row.resource_type\n    }));\n    return {\n        users:userRows,orgs:orgRows,roles:roleRows,resources:resourceRows,counts:{\n            users:userRows.size(),orgs:orgRows.size(),roles:roleRows.size(),resources:menus.size(),authorizedUsers:userRows.filter(row=>row.authorized).size()\n        }\n    };\n});\nif(operation!=\'live\') {\n    exit 400,\'操作不正确\';\n}\nreturn {\n    available:true,source:\'TENANT_LOCAL\',runtimeTenantId:tenantId,localPermissionAppId:localApp,counts:local.counts,\n    users:local.users,orgs:local.orgs,roles:local.roles,resources:local.resources,authorizedUsers:local.users.filter(row=>row.authorized)\n};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/29.只读应用本地现状.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('8f4756ddc85a434cb8b1c6a0febce5cc',NULL,'function','{\n  "properties": {},\n  "id": "1d654cff904b5826baee18e59ff03346",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "30.批量计算有效访问权限",\n  "createTime": 1791193400395,\n  "updateTime": 1791193400395,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/effective-access-batch",\n  "description": "批量预取应用授权、任职、权限组和角色资源，再在内存中计算各人员有效访问。",\n  "parameters": [\n    {\n      "name": "appId",\n      "value": null,\n      "description": "目标业务应用标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "identityDomain",\n      "value": null,\n      "description": "身份域",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "subjectIds",\n      "value": null,\n      "description": "最多 1000 个中央人员标识",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 批量计算一个应用内人员的有效访问；输入应在调用方按 1000 人以内分组。\nimport db;\nimport cn.hutool.json.JSONUtil;\nimport java.util.Collections;\nimport \'@/idaas/resource-enabled\' as enabled;\n\nvar sql=db.normal();\nvar domain=identityDomain||\'workforce\';\nvar ids=(subjectIds||[]).distinct();\nif(ids.size()>1000) {\n    exit 400,\'每次最多计算 1000 人\';\n}\nvar result={};\nif(ids.size()==0) {\n    return result;\n}\nvar app=sql.selectOne("""\nselect identity_domains\nfrom iam_application_t\nwhere tid=#{appId} and kind=\'BUSINESS\' and is_del=0 and status=\'ACTIVE\'\n""");\nvar people=sql.select("""\nselect tid as id\nfrom iam_subject_t\nwhere tid in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n  and identity_domain=#{domain} and is_del=0 and status=\'ACTIVE\'\n""");\nvar orgs=sql.select("""\nselect a.subject_id,o.tid as id,o.path\nfrom iam_appointment_t a\njoin iam_org_t o on o.tid=a.org_id and o.identity_domain=#{domain}\n  and o.is_del=0 and o.status=\'ACTIVE\'\nwhere a.subject_id in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n  and a.is_del=0 and a.status=\'ACTIVE\' and a.valid_from<=utc_timestamp(6)\n  and (a.valid_until is null or a.valid_until>utc_timestamp(6))\n  and not exists (select 1 from iam_org_t ancestor\n    where locate(concat(\'/\',ancestor.tid,\'/\'),o.path)>0\n      and (ancestor.is_del=1 or ancestor.status!=\'ACTIVE\'))\n""");\nvar groups=sql.select("""\nselect m.subject_id,g.tid as id\nfrom iam_group_member_t m\njoin iam_permission_group_t g on g.tid=m.group_id and g.identity_domain=#{domain}\n  and g.status=\'ACTIVE\' and g.is_del=0\nwhere m.subject_id in <foreach collection="ids" item="id" open="(" close=")" separator=",">#{id}</foreach>\n  and m.status=\'ACTIVE\' and m.valid_from<=utc_timestamp(6)\n  and (m.valid_until is null or m.valid_until>utc_timestamp(6))\n""");\nvar grants=sql.select("""\nselect g.*,g.tid as id,o.path org_path,o.status org_status,o.is_del org_deleted\nfrom iam_access_grant_t g\nleft join iam_org_t o on o.tid=g.org_id\nwhere g.app_id=#{appId} and g.identity_domain=#{domain} and g.status=\'ACTIVE\'\n  and g.is_del=0 and g.valid_from<=utc_timestamp(6)\n  and (g.valid_until is null or g.valid_until>utc_timestamp(6))\n""");\nvar grantRoles=sql.select("""\nselect rr.grant_id,r.tid as id\nfrom iam_grant_role_rela_t rr\njoin iam_role_t r on r.tid=rr.role_id and r.app_id=#{appId}\n  and r.identity_domain=#{domain} and r.status=\'ACTIVE\' and r.is_del=0\nwhere rr.app_id=#{appId}\n""");\nvar roleResources=sql.select("""\nselect rr.role_id,r.tid as id\nfrom iam_role_resource_rela_t rr\njoin iam_resource_t r on r.tid=rr.resource_id and r.app_id=#{appId}\n  and r.identity_domain=#{domain} and r.status=\'ACTIVE\' and r.is_del=0\nwhere rr.app_id=#{appId}\n""");\nvar activeResources=enabled(appId,domain,roleResources.map(row=>row.id).distinct());\nvar appActive=app!=null && JSONUtil.parseArray(app.identity_domains).contains(domain);\nfor(id in ids) {\n    var access={appId:appId,hasAccess:false,roleIds:[],resourceIds:[]};\n    if(appActive && people.filter(person=>person.id==id).size()==1) {\n        var subjectOrgs=orgs.filter(org=>org.subject_id==id);\n        var subjectGroups=groups.filter(group=>group.subject_id==id).map(group=>group.id);\n        for(grant in grants) {\n            var applies=grant.principal_type==\'SUBJECT\' && grant.subject_id==id\n                || grant.principal_type==\'GROUP\' && subjectGroups.contains(grant.group_id)\n                || grant.principal_type==\'ORG\' && grant.org_status==\'ACTIVE\' && grant.org_deleted==0\n                    && subjectOrgs.filter(org=>org.id==grant.org_id\n                        || grant.include_children==1 && org.path.startsWith(grant.org_path)).size()>0;\n            if(!applies) {\n                continue;\n            }\n            access.hasAccess=true;\n            for(role in grantRoles.filter(item=>item.grant_id==grant.id)) {\n                if(!access.roleIds.contains(role.id)) {\n                    access.roleIds.add(role.id);\n                }\n                for(resource in roleResources.filter(item=>item.role_id==role.id && activeResources.contains(item.id))) {\n                    if(!access.resourceIds.contains(resource.id)) {\n                        access.resourceIds.add(resource.id);\n                    }\n                }\n            }\n        }\n        Collections.sort(access.roleIds);\n        Collections.sort(access.resourceIds);\n    }\n    result.put(id,access);\n}\nreturn result;\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/30.批量计算有效访问权限.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('bf274f161f724b508170d307d9b76046',NULL,'function','{\n  "properties": {},\n  "id": "fd9b1a6ef9195f87a4f9461c37272e11",\n  "script": null,\n  "groupId": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "31.平台账号姓名唯一来源",\n  "createTime": 1791205192024,\n  "updateTime": 1791205192024,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/operator-name",\n  "description": "关联人员只更新中央人员姓名；独立平台账号只更新平台显示名，保留版本与目录范围校验。",\n  "parameters": [\n    {\n      "name": "operatorId",\n      "value": null,\n      "description": "平台账号 ID",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "subjectId",\n      "value": null,\n      "description": "关联人员 ID，可空",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "displayName",\n      "value": null,\n      "description": "目标姓名",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "subjectVersion",\n      "value": null,\n      "description": "提交时的人员档案版本",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "actorId",\n      "value": null,\n      "description": "当前操作人 ID",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    },\n    {\n      "name": "selfEdit",\n      "value": null,\n      "description": "是否本人维护个人资料",\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ],\n  "returnType": null,\n  "mappingPath": null\n}\n================================\n// 共享函数：平台账号显示名写入唯一人员来源。\n// 关联人员的姓名只写 iam_subject_t；独立平台账号只写 iam_operator_t。\n// 调用者必须在 mutate 事务内校验平台账号版本与 operators:write 或本人身份。\nimport db;\nimport \'@/idaas/directory-scope\' as directoryScope;\n\nvar sql=db.normal();\nvar value=(displayName||\'\').trim();\nif(value==\'\' || value.length()>100) {\n    exit 400,\'姓名不正确\';\n}\nif(subjectId==null) {\n    sql.update("""\nupdate iam_operator_t\nset display_name=#{value}\nwhere tid=#{operatorId} and subject_id is null and is_del=0\n""");\n    return {name:value};\n}\nvar subject=sql.selectOne("""\nselect tid as id,name,version\nfrom iam_subject_t\nwhere tid=#{subjectId} and identity_domain=\'workforce\' and is_del=0\nfor update\n""");\nif(subject==null) {\n    exit 409,\'关联人员档案不存在或身份域已变更\';\n}\nif(subjectVersion==null || subject.version!=subjectVersion) {\n    exit 409,\'人员姓名已变更，请刷新后再保存\';\n}\nif(subject.name==value) {\n    return {name:value};\n}\nif(selfEdit!=true) {\n    var scope=directoryScope(\'users:write\',\'workforce\');\n    var orgs=sql.select("""\nselect distinct org_id\nfrom iam_appointment_t\nwhere subject_id=#{subjectId} and is_del=0 and status=\'ACTIVE\'\n  and valid_from<=utc_timestamp(6)\n  and (valid_until is null or valid_until>utc_timestamp(6))\n""");\n    if(!scope.all && (orgs.size()==0 || orgs.filter(o=>!scope.orgIds.contains(o.org_id)).size()>0)) {\n        exit 403,\'人员超出中央资料管理范围\';\n    }\n}\nsql.update("""\nupdate iam_subject_t\nset name=#{value},version=version+1,updated_by=#{actorId},updated_time=utc_timestamp(6)\nwhere tid=#{subjectId} and version=#{subjectVersion}\n""");\n// 姓名属于人工下发资料；只标记期望版本，不在保存时自动下发。\nsql.update("""\nupdate iam_subject_app_t\nset desired_version=desired_version+1,version=version+1,updated_time=utc_timestamp(6)\nwhere subject_id=#{subjectId}\n""");\nreturn {name:value};\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/31.平台账号姓名唯一来源.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('35cae7e8f2d24d98b90bc03ec426fa08',NULL,NULL,'{\n  "properties": {},\n  "id": "5cc0c0d466b0571a9fe288ca74f0c356",\n  "name": "13.统一身份管理",\n  "type": "function",\n  "parentId": "0",\n  "path": "/idaas",\n  "createTime": 1790612165860,\n  "updateTime": 1790612165860,\n  "createBy": null,\n  "updateBy": null,\n  "paths": [],\n  "options": []\n}\n================================\n',NULL,NULL,0,NULL,'/magic-api/function/13.统一身份管理/group.json');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES (NULL,NULL,NULL,'this is directory',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('0454d01c38ab5d66aafdaf02d9b547d6',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "0454d01c38ab5d66aafdaf02d9b547d6",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "01.catalog-command",\r\n  "createTime" : null,\r\n  "updateTime" : 1791031451415,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/catalog-command",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 04.数据中心目录编目：复用原目录保存接口，审核状态由 da_catalog_t 控制。\n// 旧发布与订阅路由仅保留兼容读取，不参与编目审核状态。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport com.linewell.dataelement.elasticsearch.EsCommonService as esCommonService\nimport log\nimport java.time.Instant\nimport java.lang.Math\nimport \'@/resource-center/catalog-read\' as readCatalog\nimport \'@/resource-center/planning-read\' as readPlanning\nimport \'@post:/dst/catalog/saveOrUpdate\' as saveCatalog\nimport \'@post:/dst/catalog/detail\' as detailCatalog\nimport \'@post:/dst/database/metadata/table/sample-data\' as sampleData\nimport \'@post:/sym/user/me\' as currentUser\n\nvar tenantId = tenantRuntime.id()\nvar actorId = StpUtil.getLoginIdAsString()\nvar user = currentUser()\nvar orgId = user.orgId == null ? \'\' : user.orgId + \'\'\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar val = (row, name) => row == null ? null : row[name] == null ?\n    row[name.toLowerCase()] == null ? row[name.toUpperCase()] : row[name.toLowerCase()] : row[name]\nvar parse = value => text(value) == \'\' ? {} : jsons.toJSONObject(value)\nvar payload = input.body == null ? {} : input.body\nvar kind = text(input.kind)\nvar id = text(input.id)\nvar action = text(input.action)\nvar method = text(input.method).toUpperCase()\nvar now = new Date()\nvar required = (value, title, max) => {\n    var result = text(value)\n    if (result == \'\' || result.length() > max) { exit 400, title + \'不能为空或超过长度限制\' }\n    return result\n}\nvar epoch = value => {\n    try { return Instant.parse(text(value)).toEpochMilli() }\n    catch (error) { exit 400, \'请提供带时区的有效日期时间\' }\n}\nvar checkVersion = row => {\n    if (input.version == null || text(input.version) != text(row.version)) { exit 409, \'记录已更新，请刷新后重试\' }\n}\nvar organization = value => {\n    var key = required(value, \'部门\', 32)\n    var result = db.selectOne("""SELECT id, name FROM rm_org_t\n        WHERE tenant_id = #{tenantId} AND id = #{key} AND deleted = 0""")\n    if (result == null) { exit 400, \'请选择当前租户的有效部门\' }\n    return result\n}\nvar ownProvider = provider => {\n    if (orgId == \'\' || orgId != text(provider)) { exit 403, \'只允许资源提供部门维护或审核此目录\' }\n}\nvar writeDraft = (catalogId, draft) => {\n    var old = db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', catalogId)\n        .eq(\'data_type\',\'catalog\').eq(\'prop_name\',\'resourceCenterDraft\').eq(\'is_del\',0).selectOne()\n    if (old == null) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({tid: IdUtil.getSnowflakeNextIdStr(), tenant_id: tenantId,\n            parent_id: catalogId, data_type: \'catalog\', prop_name: \'resourceCenterDraft\', prop_type: \'0\',\n            prop_value: jsons.toJSONStr(draft), is_del: 0, created_time: now, updated_time: now,\n            created_by: actorId, updated_by: actorId})\n    } else {\n        db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\',old.tid)\n            .update({prop_value: jsons.toJSONStr(draft), updated_time: now, updated_by: actorId})\n    }\n}\nvar bumpCatalog = (catalogId, version) => {\n    var changed = db.table(\'da_catalog_t\').where().eq(\'tid\',catalogId).eq(\'tenant_id\',tenantId)\n        .eq(\'resource_revision_no\',version).eq(\'is_del\',0)\n        .update({resource_revision_no: version + 1, updated_time: now, updated_by: actorId})\n    if (changed != 1) { exit 409, \'目录已被更新，请刷新\' }\n}\nvar validate = (draft, freeze) => {\n    for (key in [\'name\',\'code\',\'summary\',\'provider\',\'contact\',\'resourceId\',\'classificationId\']) {\n        if (text(draft[key]) == \'\') { exit 400, \'目录必填信息不完整：\' + key }\n    }\n    organization(draft.provider)\n    var classes = readPlanning({}).classifications\n    var hasClass = false\n    for (item in classes) { if (item.id == draft.classificationId) { hasClass = true } }\n    if (!hasClass) { exit 400, \'请选择有效的资源目录分类\' }\n    if (![\'CSV\',\'JSON\'].contains(draft.format)) { exit 400, \'请选择 CSV 或 JSON 交付格式\' }\n    if (![\'ONCE\',\'DAILY\',\'WEEKLY\',\'MONTHLY\'].contains(draft.frequency)) { exit 400, \'更新频率无效\' }\n    if (![\'CONDITIONAL\',\'UNCONDITIONAL\',\'NONE\'].contains(draft.shareMode)) { exit 400, \'共享方式无效\' }\n    if (draft.shareMode != \'UNCONDITIONAL\' && text(draft.conditions) == \'\') { exit 400, \'请填写共享条件或不共享原因\' }\n    if (![\'WORKSPACE\',\'DEPARTMENTS\'].contains(draft.visibility)) { exit 400, \'可见范围无效\' }\n    if (draft.visibility == \'DEPARTMENTS\') {\n        if (draft.visibleDepartments == null || draft.visibleDepartments.isEmpty()) { exit 400, \'请选择可见部门\' }\n        for (department in draft.visibleDepartments) { organization(department) }\n    }\n    var structure = readCatalog({mode: \'structure\', id: draft.resourceId})\n    var fieldById = {}\n    for (field in structure.fields) { fieldById[text(field.id)] = field }\n    if (draft.fieldIds == null || draft.fieldIds.isEmpty() || draft.fieldIds.size() > 500) { exit 400, \'请选择 1 至 500 个数据项\' }\n    var seen = []\n    var labels = []\n    for (fieldId in draft.fieldIds) {\n        var field = fieldById[text(fieldId)]\n        if (field == null || seen.contains(fieldId)) { exit 400, \'数据项不属于来源表或重复选择\' }\n        if (text(field.name).toLowerCase().matches(\'.*(password|passwd|secret|token|private_key|internal_note).*\')) {\n            exit 400, \'交付范围包含禁止公开的凭据或内部字段\'\n        }\n        var label = draft.fieldLabels == null ? \'\' : text(draft.fieldLabels[text(fieldId)])\n        if (label == \'\') { label = text(field.comment) == \'\' ? field.name : field.comment }\n        if (labels.contains(label)) { exit 400, \'对外数据项名称不能重复\' }\n        labels.add(label); seen.add(fieldId)\n    }\n    if (draft.structure != null && !freeze) {\n        for (prior in draft.structure.fields) {\n            if (!draft.fieldIds.contains(prior.id)) { continue }\n            var latest = fieldById[text(prior.id)]\n            if (latest == null || text(latest.name) != text(prior.name) || text(latest.nativeType) != text(prior.nativeType) ||\n                text(latest.length) != text(prior.length) || text(latest.scale) != text(prior.scale)) {\n                exit 409, \'批准的数据项结构已变化，请重新编制并审核目录版本\'\n            }\n        }\n    }\n    return structure\n}\nvar saveSub = (sub, version, flowStatus) => {\n    var changed = db.table(\'data_apply_form_t\').where().eq(\'tid\',sub.id).eq(\'tenant_id\',tenantId)\n        .eq(\'resource_revision_no\',version).eq(\'is_del\',0).update({resource_scope_json: jsons.toJSONStr(sub),\n            resource_revision_no: version + 1, flow_status: flowStatus, updated_time: now, updated_by: actorId})\n    if (changed != 1) { exit 409, \'订阅已被修改，请刷新后重试\' }\n}\nvar syncCatalogIndex = catalogId => {\n    try {\n        var previousBody = body\n        var projection = null\n        try { body = {tid: catalogId}; projection = detailCatalog() }\n        finally { body = previousBody }\n        esCommonService.saveOrUpdate(\'dataassets\', catalogId, jsons.toJSONStr(projection), false)\n    } catch (error) { log.warn(\'catalog search projection refresh failed, tid: {}, error: {}\', catalogId, error.message) }\n}\nvar writeAuditNote = (catalogId, opinion) => {\n    var old = db.table(\'da_prop_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', catalogId)\n        .eq(\'data_type\', \'catalog\').eq(\'prop_name\', \'resourceCenterAuditOpinion\').eq(\'is_del\', 0).selectOne()\n    if (old == null) {\n        db.table(\'da_prop_t\').primary(\'tid\').insert({tid:IdUtil.getSnowflakeNextIdStr(), tenant_id:tenantId,\n            parent_id:catalogId, data_type:\'catalog\', prop_name:\'resourceCenterAuditOpinion\', prop_type:\'0\',\n            prop_value:opinion, is_del:0, created_time:now, updated_time:now, created_by:actorId, updated_by:actorId})\n    } else {\n        db.table(\'da_prop_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',old.tid)\n            .update({prop_value:opinion, updated_time:now, updated_by:actorId})\n    }\n}\nif (kind == \'policy\') { exit 409, \'目录审核必须由提供部门办理；跨网同步尚未配置真实连接，不允许启用模拟结果\' }\nif (kind == \'catalogs\') {\n    var entry = id == \'\' ? null : readCatalog({mode:\'one\', id:id})\n    if (method == \'GET\') { return entry }\n    if (entry != null) { checkVersion(entry) }\n    if (action == \'\' && [\'POST\',\'PUT\'].contains(method)) {\n        if (entry != null && ![\'DRAFT\',\'RETURNED\'].contains(entry.draft.state)) {\n            exit 409, \'请先撤回审核或重新编目后再修改目录\'\n        }\n        var props = payload.propList\n        if (props == null) { exit 400, \'请填写目录编目信息\' }\n        required(props.catalogName, \'目录名称\', 255)\n        required(props.orgId, \'来源部门\', 32)\n        var tableId = required(props.sourceTableId, \'数据中心表\', 32)\n        var selectedTable = db.selectOne("""\n            SELECT t.tid, t.datasource_id AS sourceId, t.table_name AS tableName FROM db_table_t t\n            JOIN dwm_center_layer_source_t b ON b.datasource_id = t.datasource_id\n             AND b.tenant_id = t.tenant_id AND b.is_del = 0 AND b.target_type IN (\'layer\',\'domain\')\n            WHERE t.tenant_id = #{tenantId} AND t.tid = #{tableId} AND t.is_del = 0 LIMIT 1\n        """)\n        if (selectedTable == null) { exit 400, \'请选择数仓规划已关联数据源中的数据表\' }\n        var existingCatalog = db.selectOne("""\n            SELECT tid FROM da_catalog_t\n             WHERE tenant_id = #{tenantId} AND source_table_id = #{tableId}\n               AND is_del = 0 AND (#{id} = \'\' OR tid <> #{id}) LIMIT 1\n        """)\n        if (existingCatalog != null) { exit 409, \'这张数据表已有目录，请打开现有目录编目\' }\n        props.dbId = val(selectedTable,\'sourceId\')\n        props.sourceTableName = val(selectedTable,\'tableName\')\n        if (payload.catalogItems == null || payload.catalogItems.isEmpty()) { exit 400, \'请至少选择一项数据表字段\' }\n        for (item in payload.catalogItems) {\n            required(item.colName, \'数据项名称\', 255)\n            required(item.colEn, \'数据项英文名\', 255)\n            required(item.colType, \'数据项类型\', 255)\n        }\n        if (payload.dryRun == true) {\n            return {dryRun:true,sourceTableId:tableId,sourceId:val(selectedTable,\'sourceId\'),\n                itemCount:payload.catalogItems.size()}\n        }\n        var previousBody = body\n        var saved = null\n        try {\n            body = {tid:id == \'\' ? null : id, assetType:\'catalog\', reviewRequired:true,\n                propList:props, catalogItems:payload.catalogItems}\n            saved = saveCatalog()\n        } finally { body = previousBody }\n        var catalogId = text(saved.tid) == \'\' ? text(saved.id) : text(saved.tid)\n        if (catalogId == \'\') { exit 500, \'目录保存未返回有效标识\' }\n        return readCatalog({mode:\'one\', id:catalogId})\n    }\n    if (entry == null) { exit 404, \'资源目录不存在\' }\n    if (action == \'check\') {\n        var count = db.table(\'da_catalog_item_t\').where().eq(\'tenant_id\',tenantId)\n            .eq(\'catalog_id\',id).eq(\'is_del\',0).count()\n        return {id:id, checks:count > 0 ? [] : [{code:\'items\',level:\'ERROR\',message:\'请先编制目录数据项\'}]}\n    }\n    if (action == \'submit\') {\n        if (![\'DRAFT\',\'RETURNED\'].contains(entry.draft.state)) { exit 409, \'当前目录不可提交审核\' }\n        var count = db.table(\'da_catalog_item_t\').where().eq(\'tenant_id\',tenantId)\n            .eq(\'catalog_id\',id).eq(\'is_del\',0).count()\n        if (count == 0) { exit 400, \'请先编制目录数据项\' }\n        var expected = entry.version\n        var changed = db.update("""\n            UPDATE da_catalog_t SET asset_status=1, flow_status=1,\n                resource_revision_no=#{expected}+1, updated_time=#{now}, updated_by=#{actorId}\n             WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0\n               AND COALESCE(resource_revision_no,1)=#{expected} AND COALESCE(flow_status,0) IN (0,3,4)\n        """, {expected:expected,now:now,actorId:actorId,tenantId:tenantId,id:id})\n        if (changed != 1) { exit 409, \'目录状态已变化，请刷新\' }\n        syncCatalogIndex(id)\n        return {id:id,state:\'PENDING_REVIEW\'}\n    }\n    if (action == \'review\' || action == \'withdraw\') {\n        if (entry.draft.state != \'PENDING_REVIEW\') { exit 409, \'目录不在审核中\' }\n        if (action == \'review\' && text(entry.draft.submittedBy) == actorId) { exit 403, \'不可审核本人提交的目录\' }\n        if (action == \'withdraw\' && text(entry.draft.submittedBy) != actorId) { exit 403, \'只允许提交人撤回\' }\n        var approve = action == \'review\' && payload.approve == true\n        var opinion = action == \'withdraw\' ? \'提交人撤回\' : text(payload.opinion)\n        if (action == \'review\' && !approve) { opinion = required(payload.opinion,\'退回原因\',1000) }\n        var changed = db.transaction(() => {\n            var assetStatus = action == \'withdraw\' || !approve ? 0 : 2\n            var flowStatus = action == \'withdraw\' ? 4 : approve ? 2 : 3\n            var expected = entry.version\n            var updated = db.update("""\n                UPDATE da_catalog_t SET asset_status=#{assetStatus}, flow_status=#{flowStatus},\n                    resource_revision_no=#{expected}+1, updated_time=#{now}, updated_by=#{actorId}\n                 WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0\n                   AND flow_status=1 AND COALESCE(resource_revision_no,1)=#{expected}\n            """, {assetStatus:assetStatus,flowStatus:flowStatus,expected:expected,\n                now:now,actorId:actorId,tenantId:tenantId,id:id})\n            if (updated != 1) { exit 409, \'审核状态已变化，请刷新\' }\n            writeAuditNote(id, opinion)\n            return updated\n        })\n        syncCatalogIndex(id)\n        return {id:id,approved:approve,changed:changed}\n    }\n    if (action == \'new-version\') {\n        if (entry.draft.state != \'APPROVED\') { exit 409, \'只有已审核目录可以重新编目\' }\n        var expected = entry.version\n        var changed = db.update("""\n            UPDATE da_catalog_t SET asset_status=0, flow_status=0,\n                resource_revision_no=#{expected}+1, updated_time=#{now}, updated_by=#{actorId}\n             WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0\n               AND flow_status=2 AND asset_status=2 AND COALESCE(resource_revision_no,1)=#{expected}\n        """, {expected:expected,now:now,actorId:actorId,tenantId:tenantId,id:id})\n        if (changed != 1) { exit 409, \'目录已更新，请刷新\' }\n        syncCatalogIndex(id)\n        return {id:id,state:\'DRAFT\'}\n    }\n    exit 400, \'不支持的目录动作\'\n}\nif (kind == \'publications\') {\n    if (id == \'\' && method == \'POST\') {\n        var entry = readCatalog({mode:\'one\',id:required(payload.entryId,\'目录\',32)})\n        ownProvider(entry.draft.provider)\n        var revisionId = required(payload.revisionId,\'版本\',32)\n        if (entry.draft.id != revisionId || entry.draft.state != \'APPROVED\') { exit 409, \'只能发布当前已批准的冻结版本\' }\n        validate(entry.draft,false)\n        var changed = db.table(\'res_catalog_publish_request\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',revisionId)\n            .eq(\'request_status\',\'APPROVED\').eq(\'is_del\',0).update({request_status:\'PUBLISHED\',published_time:now,updated_time:now,updated_by:actorId,revision_no:2})\n        if (changed != 1) { exit 409, \'该版本已发布或状态已变化\' }\n        return {id:revisionId,state:\'PUBLISHED\'}\n    }\n    var publication = readCatalog({mode:\'publication\',id:id})\n    ownProvider(publication.revision.provider); checkVersion(publication)\n    if (action == \'sync\') { exit 409, \'未配置真实跨网目录同步连接，不能将模拟结果记为成功\' }\n    if (action != \'offline\') { exit 400, \'不支持的发布动作\' }\n    var reason = required(payload.reason,\'下线原因\',1000)\n    var changed = db.table(\'res_catalog_publish_request\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',id)\n        .eq(\'request_status\',\'PUBLISHED\').eq(\'revision_no\',publication.version).eq(\'is_del\',0)\n        .update({request_status:\'OFFLINE\',offline_reason:reason,revision_no:publication.version+1,updated_time:now,updated_by:actorId})\n    if (changed != 1) { exit 409, \'发布状态已变化，请刷新\' }\n    return {id:id,state:\'OFFLINE\'}\n}\nif (kind == \'subscriptions\' && id == \'\') {\n    var publication = readCatalog({mode:\'publication\',id:required(payload.publicationId,\'发布版本\',32)})\n    if (publication.state != \'PUBLISHED\' || publication.revision.shareMode == \'NONE\') { exit 409, \'此版本不允许申请\' }\n    organization(orgId)\n    var fields = payload.fieldIds\n    if (fields == null || fields.isEmpty()) { exit 400, \'请选择申请数据项\' }\n    var seen = []\n    for (field in fields) {\n        if (!publication.revision.fieldIds.contains(field) || seen.contains(field)) { exit 400, \'申请字段超出发布范围或重复\' }\n        seen.add(field)\n    }\n    var from=epoch(payload.validFrom)\n    var until=epoch(payload.validTo)\n    if (until <= now.getTime() || until <= from || until-from > 366*86400000L) { exit 400, \'请设置一年以内的有效申请期限\' }\n    if (payload.frequency != \'ONCE\') { exit 409, \'当前交付引擎支持单次真实导出，请选择单次交付；周期调度尚未启用\' }\n    id=IdUtil.getSnowflakeNextIdStr()\n    var sub={id:id,publicationId:publication.id,applicantId:actorId,department:orgId,\n        purpose:required(payload.purpose,\'业务用途\',1000),fieldIds:fields,approvedFields:[],frequency:\'ONCE\',\n        validFrom:text(payload.validFrom),validTo:text(payload.validTo),state:\'PENDING\'}\n    db.table(\'data_apply_form_t\').primary(\'tid\').insert({tid:id,tenant_id:tenantId,apply_user_id:actorId,\n        apply_user_name:text(user.name),apply_org_id:orgId,apply_name:publication.revision.name+\'订阅申请\',\n        catalog_ids:publication.entryId,type:\'catalogSubscribe\',flow_status:1,resource_scope_json:jsons.toJSONStr(sub),\n        resource_revision_no:1,created_by:actorId,updated_by:actorId,created_time:now,updated_time:now,is_del:0})\n    return {id:id,state:\'PENDING\'}\n}\nif (kind == \'subscriptions\' || kind == \'deliveries\') {\n    var delivery = kind == \'deliveries\' ? readCatalog({mode:\'delivery\',id:id}) : null\n    var sub = readCatalog({mode:\'subscription\',id:delivery == null ? id : delivery.subscriptionId})\n    var publication = readCatalog({mode:\'publication\',id:sub.publicationId})\n    if (kind == \'subscriptions\' && action == \'review\') {\n        ownProvider(publication.revision.provider); checkVersion(sub)\n        if (sub.applicantId == actorId) { exit 403, \'不得审批自己的订阅申请\' }\n        if (sub.state != \'PENDING\') { exit 409, \'申请已处理\' }\n        sub.opinion=required(payload.opinion,\'审批意见\',1000); sub.reviewer=actorId\n        if (payload.approve == true) {\n            if (publication.state != \'PUBLISHED\') { exit 409, \'目录已下线\' }\n            validate(publication.revision,false)\n            var fields=payload.fieldIds\n            if (fields == null || fields.isEmpty()) { exit 400, \'请选择批准数据项\' }\n            var seen=[]\n            for (field in fields) {\n                if (!sub.fieldIds.contains(field) || !publication.revision.fieldIds.contains(field) || seen.contains(field)) { exit 400, \'批准范围只能缩小\' }\n                seen.add(field)\n            }\n            var until = payload.validTo == null ? sub.validTo : text(payload.validTo)\n            if (epoch(until) > epoch(sub.validTo) || epoch(until) <= Math.max(now.getTime(),epoch(sub.validFrom))) { exit 400, \'批准期限只能缩短且必须仍有效\' }\n            sub.validTo=until; sub.approvedFields=fields; sub.grantId=IdUtil.getSnowflakeNextIdStr()\n            sub.state=epoch(sub.validFrom)>now.getTime() ? \'SCHEDULED\' : \'ACTIVE\'\n        } else { sub.state=\'RETURNED\' }\n        saveSub(sub,sub.version,payload.approve == true ? 2 : 4)\n        return {id:sub.id,state:sub.state}\n    }\n    if (kind == \'subscriptions\' && [\'revoke\',\'pause\'].contains(action)) {\n        checkVersion(sub)\n        if (sub.applicantId != actorId) { ownProvider(publication.revision.provider) }\n        sub.opinion=required(payload.reason,\'原因\',1000); sub.state=action == \'revoke\' ? \'REVOKED\' : \'PAUSED\'\n        saveSub(sub,sub.version,6)\n        return {id:sub.id,state:sub.state}\n    }\n    if (sub.applicantId != actorId) { exit 403, \'只允许申请人读取获批数据\' }\n    if (publication.state != \'PUBLISHED\' || sub.state != \'ACTIVE\' || epoch(sub.validFrom)>now.getTime() || epoch(sub.validTo)<=now.getTime()) {\n        exit 403, \'授权尚未生效、已撤销、已暂停或已到期\'\n    }\n    var latestStructure = validate(publication.revision,false)\n    if (kind == \'deliveries\') {\n        if (delivery.state != \'SUCCEEDED\') { exit 409, \'批次尚未生成成功\' }\n        return delivery\n    }\n    if (action != \'deliver\') { exit 400, \'不支持的订阅动作\' }\n    var columns=[]\n    var labels=[]\n    var masks=[]\n    for (fieldId in sub.approvedFields) {\n        if (!sub.fieldIds.contains(fieldId) || !publication.revision.fieldIds.contains(fieldId)) { exit 403, \'批准范围无效\' }\n        for (field in publication.revision.structure.fields) {\n            if (field.id != fieldId) { continue }\n            columns.add(field.name)\n            labels.add(publication.revision.fieldLabels[fieldId] == null ? field.name : publication.revision.fieldLabels[fieldId])\n            var latestMask = false\n            for (latestField in latestStructure.fields) {\n                if (latestField.id == field.id && (latestField.masking == true || text(latestField.masking) == \'1\')) { latestMask = true }\n            }\n            masks.add(text(field.name).toLowerCase().matches(\'.*(phone|mobile|email|identity|certificate).*\') || latestMask || field.masking == true || text(field.masking) == \'1\')\n        }\n    }\n    if (columns.isEmpty()) { exit 403, \'没有有效的批准字段\' }\n    var deliveryId=IdUtil.getSnowflakeNextIdStr()\n    var tableId=publication.revision.resourceId\n    db.table(\'data_distribution_task_t\').primary(\'tid\').insert({tid:deliveryId,tenant_id:tenantId,\n        apply_form_id:sub.id,catalog_id:publication.entryId,catalog_name:publication.revision.name,source_table_id:tableId,\n        source_table_name:publication.revision.structure.name,task_code:\'EXPORT-\'+deliveryId,task_name:publication.revision.name+\'批准范围导出\',\n        task_status:\'RUNNING\',progress:0,execution_engine:\'RESOURCE_EXPORT\',execution_mode:\'APPROVED_SNAPSHOT\',\n        started_time:now,created_time:now,updated_time:now,created_by:actorId,updated_by:actorId,is_del:0})\n    try {\n        var previousBody=body\n        var sampled=null\n        try { body={tableId:tableId,sampleSize:1001,columns:columns}; sampled=sampleData() }\n        finally { body=previousBody }\n        var raw=sampled.rows == null ? sampled.data : sampled.rows\n        if (raw == null) { exit 502, \'来源未返回可识别的数据行，未生成空白成功文件\' }\n        var rows=[]\n        var csvCell=value => {\n            var cell=value == null ? \'\' : value + \'\'\n            if (cell.matches(\'^[=+@-].*\')) { cell="\'"+cell }\n            return \'"\'+cell.replace(\'"\',\'""\')+\'"\'\n        }\n        var lines=[]\n        var header=[]\n        for (label in labels) { header.add(csvCell(label)) }\n        lines.add(header.join(\',\'))\n        var index=0\n        for (row in raw) {\n            if (index >= 1000) { break }\n            var output={}; var line=[]; var fieldIndex=0\n            for (column in columns) {\n                var value=row[column]\n                if (masks[fieldIndex] && value != null) { value=\'***\' }\n                output[labels[fieldIndex]]=value; line.add(csvCell(value)); fieldIndex=fieldIndex+1\n            }\n            rows.add(output); lines.add(line.join(\',\')); index=index+1\n        }\n        var result={subscriptionId:sub.id,publicationId:publication.id,grantId:sub.grantId,fieldIds:sub.approvedFields,\n            rows:rows.size(),availableRows:raw.size(),truncated:raw.size()>1000,format:publication.revision.format,\n            filename:\'resource_\'+publication.id+\'_\'+deliveryId+\'.\'+publication.revision.format.toLowerCase(),\n            content:publication.revision.format == \'JSON\' ? jsons.toJSONStr(rows) : \'\\ufeff\'+lines.join(\'\\r\\n\'),scheduledFor:now}\n        db.table(\'data_distribution_task_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',deliveryId)\n            .update({task_status:\'SUCCEEDED\',progress:100,resource_result_json:jsons.toJSONStr(result),\n                status_message:raw.size()>1000 ? \'已导出前1000行，来源记录更多\' : \'批准字段真实数据导出完成\',\n                finished_time:new Date(),updated_time:new Date()})\n        return {id:deliveryId,state:\'SUCCEEDED\',rows:rows.size(),truncated:raw.size()>1000}\n    } catch (error) {\n        db.table(\'data_distribution_task_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',deliveryId)\n            .update({task_status:\'FAILED\',status_message:\'来源读取失败，请检查数据源连接和字段结构\',finished_time:new Date(),updated_time:new Date()})\n        exit 502, \'真实来源读取失败，交付任务已记录失败，可检查连接后重试\'\n    }\n}\nexit 400, \'不支持的目录运营操作\'\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/01.catalog-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('084a92c02bd05f8bb8507cc4c4660e40',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "084a92c02bd05f8bb8507cc4c4660e40",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "02.catalog-read",\r\n  "createTime" : null,\r\n  "updateTime" : 1791030855462,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/catalog-read",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 03.读取数据中心编目及兼容的历史交付台账。编目和审核状态以 da_catalog_t 为准。\nimport tenantRuntime\nimport jsons\nimport cn.dev33.satoken.stp.StpUtil\nimport java.time.Instant\nimport \'@post:/sym/user/me\' as currentUser\n\nvar tenantId = tenantRuntime.id()\nvar actorId = StpUtil.getLoginIdAsString()\nvar user = currentUser()\nvar orgId = user.orgId == null ? \'\' : user.orgId + \'\'\nvar text = value => value == null ? \'\' : value + \'\'\nvar val = (row, name) => row == null ? null : row[name] == null ?\n    row[name.toLowerCase()] == null ? row[name.toUpperCase()] : row[name.toLowerCase()] : row[name]\nvar parse = value => text(value) == \'\' ? {} : jsons.toJSONObject(value)\nvar mode = input == null ? \'\' : text(input.mode)\nvar id = input == null ? \'\' : text(input.id)\nvar structure = tableId => {\n    var table = db.selectOne("""\n        SELECT tid AS id, datasource_id AS sourceId, table_name AS name,\n               table_name_cn AS displayName, table_comment AS comment, updated_time AS updatedAt\n          FROM db_table_t WHERE tenant_id = #{tenantId} AND tid = #{tableId} AND is_del = 0\n    """)\n    if (table == null) { exit 404, \'来源表已删除或不属于当前租户\' }\n    var fields = db.select("""\n        SELECT tid AS id, column_name AS name, column_comment AS comment, data_type AS nativeType,\n               length, scale, nullable, primary_key AS primaryKey, ordinal_position AS ordinal, is_masking AS masking\n          FROM db_table_column_t WHERE tenant_id = #{tenantId} AND table_id = #{tableId} AND is_del = 0\n         ORDER BY ordinal_position, tid\n    """)\n    for (field in fields) { field.path = field.name; field.typeFamily = field.nativeType }\n    table.fields = fields\n    table.kind = \'table\'\n    table.keys = []\n    return table\n}\nif (mode == \'structure\') { return structure(id) }\n// 数据中心目录只关联已纳入分层/分库规划的数据表。审核状态以目录主表为准，\n// 不再从资源发布申请或 resourceCenterDraft 属性推断。\nvar catalogRows = db.select("""\n    SELECT c.tid AS id, c.catalog_name AS name, c.catalog_name_en AS code,\n           c.asset_desc AS summary, c.org_id AS provider,\n           c.source_table_id AS resourceId, c.source_table_name AS resourceName,\n           c.db_id AS sourceId, c.asset_status AS assetStatus,\n           c.flow_status AS flowStatus,\n           COALESCE(c.resource_revision_no, 1) AS version,\n           c.created_by AS createdBy, c.created_time AS createdAt,\n           c.updated_by AS updatedBy, c.updated_time AS updatedAt\n      FROM da_catalog_t c\n     WHERE c.tenant_id = #{tenantId} AND c.is_del = 0\n       AND (#{mode} != \'one\' OR c.tid = #{id})\n       AND EXISTS (\n           SELECT 1 FROM db_table_t t\n           JOIN dwm_center_layer_source_t b\n             ON b.datasource_id = t.datasource_id AND b.tenant_id = t.tenant_id\n            AND b.is_del = 0 AND b.target_type IN (\'layer\', \'domain\')\n           WHERE t.tid = c.source_table_id AND t.tenant_id = c.tenant_id AND t.is_del = 0\n       )\n     ORDER BY c.updated_time DESC, c.tid DESC\n""")\nvar requestRows = db.select("""\n    SELECT tid AS id, catalog_id AS catalogId, request_status AS status, snapshot_json AS snapshot,\n           revision_number AS revisionNumber, revision_no AS version, created_by AS submittedBy,\n           created_time AS submittedAt, reviewer_id AS reviewer, reviewed_time AS reviewedAt,\n           review_comment AS opinion, published_time AS publishedAt, offline_reason AS reason,\n           sync_status AS busState, updated_time AS updatedAt\n      FROM res_catalog_publish_request WHERE tenant_id = #{tenantId} AND is_del = 0 AND snapshot_json IS NOT NULL\n     ORDER BY revision_number\n""")\nvar requests = []\nvar publications = []\nvar rowById = {}\nvar toRevision = row => {\n    var revision = parse(row.snapshot)\n    revision.id = text(row.id)\n    revision.number = row.revisionNumber\n    revision.state = row.status == \'PENDING\' ? \'PENDING_REVIEW\' : row.status == \'REJECTED\' ? \'RETURNED\' :\n        [\'APPROVED\',\'PUBLISHED\',\'OFFLINE\'].contains(row.status) ? \'APPROVED\' : \'SUPERSEDED\'\n    revision.submittedBy = row.submittedBy\n    revision.submittedAt = row.submittedAt\n    revision.reviewer = row.reviewer\n    revision.reviewedAt = row.reviewedAt\n    revision.opinion = row.opinion\n    if (revision.checks == null) { revision.checks = [] }\n    return revision\n}\nfor (row in requestRows) {\n    rowById[text(row.id)] = row\n    requests.add(row)\n    if ([\'PUBLISHED\',\'OFFLINE\'].contains(row.status)) {\n        var revision = toRevision(row)\n        var allowed = revision.visibility != \'DEPARTMENTS\' || revision.provider == orgId ||\n            (revision.visibleDepartments != null && revision.visibleDepartments.contains(orgId))\n        if (allowed) {\n            publications.add({id: text(row.id), entryId: text(row.catalogId), revisionId: text(row.id),\n                revision: revision, state: row.status == \'PUBLISHED\' ? \'PUBLISHED\' : \'OFFLINE\',\n                version: row.version, busState: row.busState == null ? \'NOT_CONFIGURED\' : row.busState,\n                publishedBy: row.reviewer, reason: row.reason, createdAt: row.publishedAt, updatedAt: row.updatedAt})\n        }\n    }\n}\nif (mode == \'publication\') {\n    for (publication in publications) { if (publication.id == id) { return publication } }\n    exit 404, \'发布版本不存在或当前部门不可见\'\n}\nvar itemRows = db.select("""\n    SELECT i.catalog_id AS catalogId, i.tid AS itemId,\n           i.source_table_column_id AS fieldId, i.col_name AS label\n      FROM da_catalog_item_t i\n      JOIN da_catalog_t c ON c.tid = i.catalog_id AND c.tenant_id = i.tenant_id AND c.is_del = 0\n     WHERE i.tenant_id = #{tenantId} AND i.is_del = 0\n       AND EXISTS (\n           SELECT 1 FROM db_table_t t\n           JOIN dwm_center_layer_source_t b ON b.datasource_id = t.datasource_id\n             AND b.tenant_id = t.tenant_id AND b.is_del = 0 AND b.target_type IN (\'layer\',\'domain\')\n           WHERE t.tid = c.source_table_id AND t.tenant_id = c.tenant_id AND t.is_del = 0\n       )\n     ORDER BY i.catalog_id, i.sort_no\n""")\nvar itemsByCatalog = {}\nfor (item in itemRows) {\n    var key = text(val(item, \'catalogId\'))\n    if (itemsByCatalog[key] == null) { itemsByCatalog[key] = [] }\n    itemsByCatalog[key].add(item)\n}\nvar catalogs = []\nfor (row in catalogRows) {\n    var items = itemsByCatalog[text(row.id)] == null ? [] : itemsByCatalog[text(row.id)]\n    var fieldIds = []\n    var labels = {}\n    for (item in items) {\n        var fieldId = text(val(item, \'fieldId\'))\n        if (fieldId == \'\') { fieldId = text(val(item, \'itemId\')) }\n        if (fieldId != \'\') { fieldIds.add(fieldId); labels[fieldId] = val(item, \'label\') }\n    }\n    var assetStatus = val(row, \'assetStatus\')\n    var flowStatus = val(row, \'flowStatus\')\n    var state = text(flowStatus) == \'1\' ? \'PENDING_REVIEW\' :\n        text(flowStatus) == \'3\' ? \'RETURNED\' :\n        text(assetStatus) == \'2\' && text(flowStatus) == \'2\' ? \'APPROVED\' : \'DRAFT\'\n    var draft = {id:text(val(row, \'id\')), number:val(row, \'version\'), state:state,\n        name:text(val(row, \'name\')), code:text(val(row, \'code\')), summary:text(val(row, \'summary\')),\n        provider:text(val(row, \'provider\')), contact:\'\', resourceId:text(val(row, \'resourceId\')),\n        resourceName:text(val(row, \'resourceName\')), sourceId:text(val(row, \'sourceId\')),\n        assetStatus:assetStatus, flowStatus:flowStatus,\n        submittedBy:val(row, \'updatedBy\'), submittedAt:state == \'PENDING_REVIEW\' ? val(row, \'updatedAt\') : null,\n        classificationId:\'\', keywords:[], frequency:\'ONCE\', shareMode:\'NONE\', conditions:\'\',\n        visibility:\'WORKSPACE\', visibleDepartments:[], format:\'CSV\',\n        fieldIds:fieldIds, fieldLabels:labels, note:\'\', checks:[]}\n    var entry = {id:text(val(row, \'id\')), version:val(row, \'version\'), draft:draft, revisions:[],\n        createdAt:val(row, \'createdAt\'), updatedAt:val(row, \'updatedAt\'), createdBy:val(row, \'createdBy\')}\n    catalogs.add(entry)\n    if (mode == \'one\' && entry.id == id) { return entry }\n}\nif (mode == \'one\') { exit 404, \'资源目录不存在\' }\nvar formRows = db.select("""\n    SELECT tid AS id, apply_user_id AS applicantId, apply_org_id AS department,\n           resource_scope_json AS scope, resource_revision_no AS version,\n           created_time AS createdAt, updated_time AS updatedAt\n      FROM data_apply_form_t WHERE tenant_id = #{tenantId} AND is_del = 0 AND resource_scope_json IS NOT NULL\n""")\nvar subscriptions = []\nvar allowedSubs = []\nfor (row in formRows) {\n    var sub = parse(row.scope)\n    var req = rowById[text(sub.publicationId)]\n    var provider = req == null ? \'\' : text(parse(req.snapshot).provider)\n    if (row.applicantId != actorId && provider != orgId) { continue }\n    sub.putAll({id: text(row.id), applicantId: row.applicantId, department: row.department,\n        version: row.version, createdAt: row.createdAt, updatedAt: row.updatedAt})\n    if ([\'ACTIVE\',\'SCHEDULED\'].contains(sub.state)) {\n        if (Instant.parse(sub.validTo).toEpochMilli() <= new Date().getTime()) { sub.state = \'EXPIRED\' }\n        else if (req == null || req.status != \'PUBLISHED\') { sub.state = \'PAUSED\' }\n        else if (Instant.parse(sub.validFrom).toEpochMilli() <= new Date().getTime()) { sub.state = \'ACTIVE\' }\n    }\n    if (mode == \'subscription\' && sub.id == id) { return sub }\n    subscriptions.add(sub)\n    allowedSubs.add(sub.id)\n}\nif (mode == \'subscription\') { exit 404, \'订阅不存在或无权查看\' }\nvar deliveries = []\nvar taskRows = db.select("""\n    SELECT tid AS id, apply_form_id AS subscriptionId, resource_result_json AS result,\n           task_status AS state, status_message AS error, created_time AS createdAt, updated_time AS updatedAt\n      FROM data_distribution_task_t WHERE tenant_id = #{tenantId} AND is_del = 0\n       AND execution_engine = \'RESOURCE_EXPORT\' ORDER BY created_time DESC\n""")\nfor (row in taskRows) {\n    if (!allowedSubs.contains(text(row.subscriptionId))) { continue }\n    var result = parse(row.result)\n    result.putAll({id: text(row.id), subscriptionId: text(row.subscriptionId), state: row.state,\n        error: row.error, version: 1, createdAt: row.createdAt, updatedAt: row.updatedAt})\n    if (mode == \'delivery\' && row.id == id) { return result }\n    result.remove(\'content\')\n    deliveries.add(result)\n}\nif (mode == \'delivery\') { exit 404, \'交付批次不存在或无权查看\' }\nreturn {catalogs: catalogs, publications: publications, subscriptions: subscriptions, deliveries: deliveries,\n    autoApprove: false, busConfigured: false, deliveryScheduling: false,\n    actor: {id: actorId, orgId: orgId, name: user.name},\n    capabilities: {scheduledDelivery: false, manualDelivery: true, crossNetworkSync: false, autoApprove: false}}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/02.catalog-read.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('2ebdc2a6af4b5e2989cd8add98c849fa',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "2ebdc2a6af4b5e2989cd8add98c849fa",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "03.materialization-command",\r\n  "createTime" : null,\r\n  "updateTime" : 1791068445365,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/materialization-command",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 06.逻辑模型物化：固定冻结版本及绑定，复用共享元数据建表接口执行真实 CREATE TABLE。\n// 创建/预检不连接业务库。execute/retry 必须显式确认，先乐观锁领取方案再逐项执行；绝不覆盖已存在表。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport com.linewell.dataelement.dataassets.runtime.DataSourceConnectionPropertyResolver as connectionProperties\nimport com.linewell.dataelement.metautil.service.MetadataRelationJdbcService as fusionJdbc\nimport \'@post:/dst/database/metadata/getCreateTableDDL\' as generateDDL\nimport \'@post:/dst/database/metadata/createTable\' as createPhysicalTable\nimport \'@/resource-center/planning-read\' as readPlanning\nimport \'@/resource-center/model-read\' as readModels\nimport \'@/resource-center/model-validate\' as validateModel\n\nvar tenantId=tenantRuntime.id()\nvar actorId=StpUtil.getLoginIdAsString()\nvar text=v=>v==null?\'\':(v+\'\').trim()\nvar clone=v=>JSONUtil.parse(jsons.toJSONStr(v))\nvar payload=input.body==null?{}:input.body\nvar id=text(input.id)\nvar action=text(input.action)\nvar method=text(input.method)\nvar key=v=>{var name=text(v);if(!name.matches(\'[A-Za-z_][A-Za-z0-9_]{0,62}\')){exit 400,\'表和字段技术名称须为安全标识符，最多63字符\'};return name}\nvar find=(items,objectId)=>{for(item in items){if(item.id==objectId){return item}};exit 404,\'对象不存在或不属于当前租户\'}\nvar unwrap=value=>{if(value instanceof java.util.Map && value.success==false){throw new java.lang.IllegalStateException(text(value.message)==\'\'?text(value.msg):text(value.message))};return value instanceof java.util.Map&&value.data!=null?value.data:value}\nvar audit=(verb,plan,detail)=>db.table(\'res_resource_operation_log\').primary(\'tid\').insert({tid:IdUtil.fastSimpleUUID(),tenant_id:tenantId,actor_id:actorId,action_name:verb,object_id:plan.id,object_name:plan.name,detail_text:detail,created_time:new Date()})\nvar readPlan=planId=>{\n var row=db.table(\'res_materialization_plan\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',planId).eq(\'is_del\',0).selectOne()\n if(row==null||text(row.planJson)==\'\'){exit 404,\'物化方案不存在或不属于当前租户\'}\n var plan=JSONUtil.parse(row.planJson);plan.id=text(row.tid);plan.version=row.revisionNo;plan.state=row.planStatus;plan.updatedAt=row.updatedTime;plan.createdAt=row.createdTime;return plan\n}\nvar save=(plan,expected)=>{\n var now=new Date();var encoded=jsons.toJSONStr(plan)\n var count=db.update(\'UPDATE res_materialization_plan SET plan_json=#{encoded},plan_status=#{state},revision_no=revision_no+1,updated_by=#{actorId},updated_time=#{now} WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0 AND revision_no=#{expected}\',{encoded:encoded,state:plan.state,actorId:actorId,now:now,tenantId:tenantId,id:plan.id,expected:expected})\n if(count!=1){exit 409,\'物化方案已更新，请刷新后重试\'}\n plan.version=expected+1;plan.updatedAt=now;return plan\n}\nvar bindingFor=plan=>{\n var planning=readPlanning({});var binding=find(planning.bindings,plan.bindingId);var domain=find(planning.databases,binding.databaseId)\n if(domain.state!=\'ACTIVE\'||domain.mode!=\'MANAGED\'||binding.category==\'REFERENCE\'){throw new java.lang.IllegalStateException(\'只有有效管理型分库可以物化\')}\n if(binding.state!=\'VALID\'||binding.checkedHash!=binding.currentHash){throw new java.lang.IllegalStateException(\'绑定配置已变化或尚未校验，请重新检查\')}\n if(plan.bindingHash!=null&&plan.bindingHash!=binding.currentHash){throw new java.lang.IllegalStateException(\'方案绑定快照已失效，请重新创建物化方案\')}\n var registered=connectionProperties.resolve(tenantId,binding.sourceId)\n if(registered==null||registered.isEmpty()){throw new java.lang.IllegalStateException(\'目标数据源不存在或不属于当前租户\')}\n var pick=keys=>{for(k in keys){if(text(registered[k])!=\'\'){return text(registered[k])}};return \'\'}\n var engine=pick([\'dbType\',\'databaseType\']).toLowerCase()\n var catalog=pick([\'database\',\'dbMetaDbName\',\'dbName\'])\n var schema=pick([\'schema\',\'defaultSchema\',\'currentSchema\',\'schemaName\'])\n if(schema==\'\'&&[\'oracle\',\'dameng\'].contains(engine)){schema=pick([\'username\',\'user\'])}\n if(schema==\'\'&&[\'postgresql\',\'kingbase\',\'kingbase8\',\'gaussdb\'].contains(engine)){schema=\'public\'}\n if(catalog==\'\'&&schema==\'\'){throw new java.lang.IllegalStateException(\'目标数据源未登记实际数据库或Schema\')}\n // 物化API使用已登记连接的范围，不允许页面填写另一个schema冒充目标。\n if(text(binding.catalog)!=\'\'&&text(binding.catalog).toLowerCase()!=catalog.toLowerCase()){throw new java.lang.IllegalStateException(\'绑定数据库与数据源登记配置不一致\')}\n var expectedSchema=[\'mysql\',\'mariadb\'].contains(engine)?catalog:schema\n if(text(binding.schema)!=\'\'&&text(binding.schema).toLowerCase()!=expectedSchema.toLowerCase()){throw new java.lang.IllegalStateException(\'绑定Schema与数据源登记配置不一致\')}\n return {binding:binding,domain:domain,engine:engine}\n}\nvar physical=(field,engine)=>{\n var logical=text(field.logicalType)\n if(logical==\'String\'){return ([\'oracle\',\'dameng\'].contains(engine)?\'VARCHAR2\':\'VARCHAR\')+\'(\'+field.length+\')\'}\n if(logical==\'Text\'){return [\'oracle\',\'dameng\'].contains(engine)?\'CLOB\':engine==\'sqlserver\'?\'NVARCHAR(MAX)\':\'TEXT\'}\n if(logical==\'Int32\'){return \'INTEGER\'}\n if(logical==\'Int64\'){return [\'oracle\',\'dameng\'].contains(engine)?\'NUMBER(19)\':\'BIGINT\'}\n if(logical==\'Decimal\'){return \'DECIMAL(\'+field.precision+\',\'+field.scale+\')\'}\n if(logical==\'Boolean\'){return [\'oracle\',\'dameng\'].contains(engine)?\'NUMBER(1)\':engine==\'sqlserver\'?\'BIT\':\'BOOLEAN\'}\n if(logical==\'Date\'){return \'DATE\'}\n if(logical==\'Timestamp\'){return engine==\'sqlserver\'?\'DATETIME2\':[\'mysql\',\'mariadb\'].contains(engine)?\'DATETIME\':\'TIMESTAMP\'}\n if(logical==\'UUID\'){return [\'postgresql\',\'kingbase\',\'kingbase8\'].contains(engine)?\'UUID\':\'CHAR(36)\'}\n if(logical==\'Binary\'){return [\'postgresql\',\'kingbase\',\'kingbase8\'].contains(engine)?\'BYTEA\':engine==\'sqlserver\'?\'VARBINARY(MAX)\':\'BLOB\'}\n if(logical==\'JSON\'&&[\'mysql\',\'mariadb\',\'postgresql\'].contains(engine)){return engine==\'postgresql\'?\'JSONB\':\'JSON\'}\n throw new java.lang.IllegalStateException(\'字段\'+text(field.name)+\'的\'+logical+\'类型没有目标方言映射\')\n}\nvar itemsFor=(entity,engine)=>{\n var columns=[];var primary=[];var unique=[]\n for(k in entity.keys==null?[]:entity.keys){if(k.kind==\'primary\'){primary.addAll(k.fieldIds)};if(k.kind==\'unique\'&&k.fieldIds.size()==1){unique.add(k.fieldIds[0])}}\n var ordinal=0\n for(f in entity.fields){ordinal=ordinal+1;var native=physical(f,engine);var base=native.contains(\'(\')?native.substring(0,native.indexOf(\'(\')):native\n  columns.add({columnName:key(f.name),columnComment:text(f.businessName)==\'\'?text(f.comment):text(f.businessName),dataType:base,columnType:native,length:f.length,precisionLength:f.precision,scale:f.scale,nullable:f.nullable==\'false\'?0:1,primaryKey:primary.contains(f.id)?1:0,isUnique:unique.contains(f.id)?1:0,autoIncrement:0,indexed:primary.contains(f.id)?1:0,ordinalPosition:ordinal,designFieldId:f.id,standardId:f.standard==null?null:f.standard.id})\n }\n return columns\n}\nvar precheck=plan=>{\n var errors=[];var ddlParts=[]\n var validation=validateModel(clone(plan.revision));errors.addAll(validation.errors)\n try{\n  var target=bindingFor(plan);var names=[]\n  for(item in plan.items){\n   if(item.state==\'SUCCEEDED\'){ddlParts.add(item.ddl);continue}\n   var name=key(item.targetName)\n   if(names.contains(name.toLowerCase())){throw new java.lang.IllegalStateException(\'方案中存在重复目标表名\')};names.add(name.toLowerCase())\n   var entity=find(plan.revision.entities,item.designEntityId)\n   if(entity.reference!=null){throw new java.lang.IllegalStateException(\'引用模型的只读实体不能物化\')}\n   var sourceId=target.binding.sourceId\n   var duplicate=db.selectOne(\'SELECT tid FROM db_table_t WHERE tenant_id=#{tenantId} AND datasource_id=#{sourceId} AND is_del=0 AND LOWER(table_name)=LOWER(#{name}) LIMIT 1\')\n   if(duplicate!=null){throw new java.lang.IllegalStateException(\'目标表已登记，不覆盖：\'+name)}\n   var columns=itemsFor(entity,target.engine)\n   var savedBody=body\n   try{body={canvas:true,propList:{dbId:sourceId,tableName:name,tableNameCn:text(entity.displayName)},tableItems:columns};item.ddl=text(unwrap(generateDDL()))}\n   finally{body=savedBody}\n   if(item.ddl==\'\'){throw new java.lang.IllegalStateException(\'共享DDL接口未返回建表脚本\')}\n   item.columns=columns;ddlParts.add(item.ddl)\n  }\n }catch(e){errors.add(text(e.getMessage()))}\n plan.errors=errors;plan.warnings=[\'预检只检查模型、命名、登记冲突和SQL方言；实际连接与实库同名检查在执行时完成。\',\'仅创建表结构；不装载数据，不生成跨来源物理外键，不覆盖已有表。\']\n plan.ddl=ddlParts.join(\'\\n\\n\');plan.state=errors.size()>0?\'BLOCKED\':\'READY\';return plan\n}\nif(method==\'POST\'&&id==\'\'){\n var models=readModels({entities:[]});var model=find(models.models,text(payload.modelId));var frozen=find(model.frozen,text(payload.revisionId))\n var planning=readPlanning({});var binding=find(planning.bindings,text(payload.bindingId))\n var chosen=payload.entityIds==null?[]:payload.entityIds\n if(chosen.size()==0||chosen.size()>300){exit 400,\'请选择1至300个物化实体\'}\n if(text(frozen.outputEntityId)!=\'\'){\n  if(chosen.size()!=1||text(chosen[0])!=text(frozen.outputEntityId)){exit 400,\'融合模型只能物化唯一输出表，来源表不可物化\'}\n  if(text(binding.databaseId)!=text(model.databaseId)){exit 409,\'物化目标必须是模型指定的目标分库\'}\n }\n var selected=[];var seen=[]\n for(eid in chosen){if(seen.contains(eid)){exit 400,\'实体选择不能重复\'};seen.add(eid);var entity=find(frozen.entities,eid);if(entity.reference!=null){exit 400,\'参照实体不能物化\'}\n  var name=payload.targetNames==null||payload.targetNames[eid]==null?text(binding.prefix)+entity.name:payload.targetNames[eid]\n  selected.add({id:IdUtil.fastSimpleUUID(),designEntityId:eid,targetName:key(name),state:\'PENDING\'})\n }\n var now=new Date();var plan={id:IdUtil.fastSimpleUUID(),version:1,name:text(payload.name)==\'\'?model.name+\'物化\':text(payload.name),modelId:model.id,revisionId:frozen.id,bindingId:binding.id,bindingHash:binding.currentHash,revision:clone(frozen),items:selected,attempt:0,createdAt:now,updatedAt:now,requestedBy:actorId}\n precheck(plan)\n db.table(\'res_materialization_plan\').primary(\'tid\').insert({tid:plan.id,tenant_id:tenantId,plan_code:\'PS_\'+plan.id,model_id:model.id,target_datasource_id:binding.sourceId,target_table_name:selected[0].targetName,plan_status:plan.state,risk_level:\'STRUCTURE_CREATE\',binding_id:binding.id,frozen_revision_id:frozen.id,plan_json:jsons.toJSONStr(plan),revision_no:1,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n var targetNames=[];for(item in selected){targetNames.add(item.targetName)}\n audit(\'创建物化方案\',plan,\'模型：\'+model.name+\'；冻结版本：v\'+frozen.number+\'；目标表：\'+targetNames.join(\'、\')+\'；预检结果：\'+(plan.state==\'READY\'?\'可执行\':\'存在阻断\'));return plan\n}\nvar plan=readPlan(id)\nif(method==\'GET\'){return plan}\nif(text(input.version)!=text(plan.version)){exit 409,\'物化方案已更新，请刷新后重试\'}\nif(action==\'cancel\'){\n if(![\'QUEUED\',\'RUNNING\'].contains(plan.state)){exit 409,\'任务已结束，不可取消\'}\n plan.state=\'CANCELLING\';save(plan,plan.version);audit(\'请求取消物化\',plan,\'当前单表操作不可中断，后续对象将停止\');return plan\n}\nif(action==\'precheck\'){\n if([\'RUNNING\',\'QUEUED\',\'CANCELLING\',\'SUCCEEDED\'].contains(plan.state)){exit 409,\'执行中或完成的方案不能重新预检\'}\n precheck(plan);save(plan,plan.version);audit(\'重新预检物化\',plan,\'预检结果：\'+(plan.state==\'READY\'?\'可执行\':\'存在阻断\')+\'；问题 \'+plan.errors.size()+\' 项\');return plan\n}\nif(action==\'load\'){\n if(payload.confirmExecution!=true){exit 400,\'请确认将冻结的字段映射装载到目标表\'}\n if(plan.state!=\'SUCCEEDED\'||text(plan.revision.outputEntityId)==\'\'){exit 409,\'请先完成融合模型唯一输出表 D 的物化建表\'}\n if(plan.items.size()!=1||plan.items[0].state!=\'SUCCEEDED\'||text(plan.items[0].resourceId)==\'\'){exit 409,\'目标表尚未完整创建与登记\'}\n if(plan.loadState==\'SUCCEEDED\'){exit 409,\'该冻结版本已装载，禁止重复写入\'}\n if(plan.loadState==\'RUNNING\'){exit 409,\'融合装载正在执行，请稍后刷新\'}\n var target=bindingFor(plan);var output=find(plan.revision.entities,plan.revision.outputEntityId)\n var fusion=plan.revision.fusion\n if(fusion==null||fusion.mappings==null||fusion.mappings.size()==0){exit 422,\'冻结版本没有可执行的字段映射\'}\n var validation=validateModel(clone(plan.revision));if(!validation.valid){exit 422,validation.errors.join(\'；\')}\n var sourceById={};var sources=[]\n for(e in plan.revision.entities){if(e.role!=\'SOURCE\'){continue}\n  if(e.origin==null||text(e.origin.entityId)==\'\'){exit 422,\'来源表缺少共享技术快照标识\'}\n  var original=db.selectOne(\'SELECT tid,datasource_id,table_name FROM db_table_t WHERE tenant_id=#{tenantId} AND tid=#{tableId} AND is_del=0\',{tenantId:tenantId,tableId:e.origin.entityId})\n  if(original==null||text(original.tableName)!=text(e.origin.tableName==null?e.name:e.origin.tableName)||e.origin.sourceId!=null&&text(original.datasourceId)!=text(e.origin.sourceId)){exit 409,\'来源技术表已变化，请重新逆向解析：\'+text(e.name)}\n  sourceById[e.id]=e;sources.add({entityId:e.id,sourceId:text(original.datasourceId),tableName:text(original.tableName)})\n }\n var currentName=(e,fid)=>{var f=find(e.fields,fid);var originalId=e.origin==null||e.origin.fieldMap==null?null:e.origin.fieldMap[fid]\n  if(text(originalId)==\'\'){exit 409,\'来源字段没有原始快照映射：\'+text(f.name)}\n  var column=db.selectOne(\'SELECT tid,column_name FROM db_table_column_t WHERE tenant_id=#{tenantId} AND tid=#{columnId} AND table_id=#{tableId} AND is_del=0\',{tenantId:tenantId,columnId:originalId,tableId:e.origin.entityId})\n  if(column==null||text(column.columnName)!=text(f.name)){exit 409,\'来源字段快照已变化，请重新解析：\'+text(f.name)}\n  return text(column.columnName)\n }\n var joins=[]\n for(j in fusion.joins){var left=sourceById[j.leftEntityId];var right=sourceById[j.rightEntityId];if(left==null||right==null){exit 422,\'融合关联引用了非来源表\'}\n  var pairs=[];for(pair in j.pairs){pairs.add({leftName:currentName(left,pair.leftFieldId),rightName:currentName(right,pair.rightFieldId)})}\n  joins.add({leftEntityId:j.leftEntityId,rightEntityId:j.rightEntityId,joinType:j.joinType,pairs:pairs,rightCardinality:j.rightCardinality,dedupe:j.dedupe,orderName:j.dedupe==\'LATEST\'?currentName(right,j.orderFieldId):null})\n }\n var mappings=[]\n for(mapping in fusion.mappings){var from=sourceById[mapping.sourceEntityId];if(from==null){exit 422,\'字段映射引用了非来源表\'}\n  var targetField=find(output.fields,mapping.targetFieldId)\n  mappings.add({sourceEntityId:from.id,sourceName:currentName(from,mapping.sourceFieldId),targetName:key(targetField.name),transform:mapping.transform})\n }\n var item=plan.items[0]\n plan.loadState=\'RUNNING\';plan.loadStartedAt=new Date();plan.loadError=null;save(plan,plan.version)\n try{\n  var result=fusionJdbc.loadModelFusion({targetSourceId:target.binding.sourceId,targetTable:item.targetName,baseEntityId:fusion.baseEntityId,sources:sources,joins:joins,mappings:mappings})\n  plan.loadedRows=result.insertedRows;plan.loadState=\'SUCCEEDED\';plan.loadedAt=new Date();plan.loadError=null\n  db.update(\'UPDATE db_table_t SET record_count=#{count},updated_time=#{now},updated_by=#{actorId} WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0\',{count:result.insertedRows,now:new Date(),actorId:actorId,tenantId:tenantId,id:item.resourceId})\n  save(plan,plan.version);audit(\'装载融合模型数据\',plan,\'目标表 \'+item.targetName+\'，写入 \'+result.insertedRows+\' 行\');return plan\n }catch(e){plan.loadState=\'FAILED\';plan.loadError=text(e.getMessage());save(plan,plan.version);audit(\'融合模型装载失败\',plan,\'目标表 \'+item.targetName+\'；原因：\'+plan.loadError);return plan}\n}\nif(![\'execute\',\'retry\'].contains(action)){exit 400,\'不支持的物化操作\'}\nif(payload.confirmExecution!=true){exit 400,\'请核对SQL后明确确认执行物化建表\'}\nif(![\'READY\',\'FAILED\',\'PARTIAL\',\'CANCELLED\'].contains(plan.state)){exit 409,\'方案不在可执行状态\'}\nvar previousState=plan.state\nprecheck(plan)\nif(plan.errors.size()>0){save(plan,plan.version);exit 409,\'预检未通过，请查看方案错误\'}\nplan.state=\'RUNNING\';plan.attempt=plan.attempt+1;plan.startedAt=new Date();plan.finishedAt=null\nfor(item in plan.items){if(item.state!=\'SUCCEEDED\'){item.state=\'PENDING\';item.error=null}}\n// 原子乐观锁领取；真实DDL不被长数据库事务包裹，避免取消请求无法读取状态。\nsave(plan,plan.version)\naudit(\'开始物化建表\',plan,\'已明确确认执行，尝试 \'+plan.attempt)\nvar target=bindingFor(plan)\nfor(item in plan.items){\n if(item.state==\'SUCCEEDED\'){continue}\n var latest=readPlan(plan.id)\n if(latest.state==\'CANCELLING\'){plan.version=latest.version;break}\n var executionId=IdUtil.fastSimpleUUID()\n db.table(\'res_materialization_execution\').primary(\'tid\').insert({tid:executionId,tenant_id:tenantId,plan_id:plan.id,item_id:item.id,execution_status:\'RUNNING\',execution_mode:\'PHYSICAL_CREATE\',ddl_text:item.ddl,physical_created:0,started_time:new Date(),created_by:actorId,created_time:new Date(),updated_by:actorId,updated_time:new Date(),is_del:0})\n try{\n  bindingFor(plan)\n  // 成功物理建表但登记失败的记录不得盲目重试CREATE；明确保留恢复依据。\n  var previous=db.selectOne(\'SELECT tid,target_table_id FROM res_materialization_execution WHERE tenant_id=#{tenantId} AND plan_id=#{planId} AND item_id=#{itemId} AND physical_created=1 AND is_del=0 ORDER BY created_time DESC LIMIT 1\',{tenantId:tenantId,planId:plan.id,itemId:item.id})\n  if(previous!=null){throw new java.lang.IllegalStateException(\'该对象此前已物理创建，请先核对并登记已有表，未重复执行DDL\')}\n  var savedBody=body;var created=null\n  try{body={canvas:true,dbId:target.binding.sourceId,tableName:item.targetName,ddl:item.ddl,skipIfExists:false};created=unwrap(createPhysicalTable())}\n  finally{body=savedBody}\n  if(!(created instanceof java.util.Map)||created.created!=true||created.status!=\'created\'){throw new java.lang.IllegalStateException(\'目标实库表已存在或建表未成功，未覆盖已有对象\')}\n  db.table(\'res_materialization_execution\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',executionId).update({physical_created:1,updated_time:new Date()})\n  var entity=find(plan.revision.entities,item.designEntityId);var tableId=IdUtil.fastSimpleUUID();var fieldMap={}\n  db.transaction(()=>{\n   var now=new Date()\n   db.table(\'db_table_t\').primary(\'tid\').insert({tid:tableId,tenant_id:tenantId,datasource_id:target.binding.sourceId,table_name:item.targetName,table_name_en:item.targetName,table_name_cn:text(entity.displayName),table_comment:text(entity.comment),table_type:\'TABLE\',business_type:target.domain.domain,field_count:entity.fields.size(),record_count:0,asset_desc:text(entity.comment),asset_status:2,flow_status:2,resource_domain_id:target.domain.id,resource_owner:target.domain.owner,resource_state:\'ACTIVE\',resource_model_id:plan.modelId,resource_plan_id:plan.id,resource_revision_no:1,revision:1,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n   for(column in item.columns){var columnId=IdUtil.fastSimpleUUID();fieldMap[column.designFieldId]=columnId\n    db.table(\'db_table_column_t\').primary(\'tid\').insert({tid:columnId,tenant_id:tenantId,table_id:tableId,column_name:column.columnName,column_comment:column.columnComment,data_type:column.dataType,column_type:column.columnType,length:column.length,precision_length:column.precisionLength,scale:column.scale,nullable:column.nullable,primary_key:column.primaryKey,is_unique:column.isUnique,indexed:column.indexed,ordinal_position:column.ordinalPosition,data_standard_id:column.standardId,revision:1,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n   }\n   db.table(\'db_table_t\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',tableId).update({resource_field_map:jsons.toJSONStr(fieldMap)})\n   db.table(\'res_materialization_execution\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',executionId).update({target_table_id:tableId,execution_status:\'SUCCEEDED\',execution_summary:\'物理表已创建，共享技术元数据和仓库归属已登记\',finished_time:now,updated_time:now})\n  })\n  item.entityId=tableId;item.resourceId=tableId;item.state=\'SUCCEEDED\';item.error=null\n }catch(e){\n  item.state=\'FAILED\';item.error=text(e.getMessage())\n  db.table(\'res_materialization_execution\').where().eq(\'tenant_id\',tenantId).eq(\'tid\',executionId).update({execution_status:\'FAILED\',failure_summary:item.error,finished_time:new Date(),updated_time:new Date()})\n }\n // 每个对象保存进度；取消请求保留其CANCELLING状态，不被执行线程覆盖。\n var latest=readPlan(plan.id);plan.version=latest.version;plan.state=latest.state==\'CANCELLING\'?\'CANCELLING\':\'RUNNING\';save(plan,plan.version)\n}\nvar succeeded=0;var failed=0;var cancelled=0\nfor(item in plan.items){if(item.state==\'SUCCEEDED\'){succeeded=succeeded+1};if(item.state==\'FAILED\'){failed=failed+1};if(item.state==\'PENDING\'){item.state=\'CANCELLED\';cancelled=cancelled+1}}\nvar latest=readPlan(plan.id);plan.version=latest.version\nplan.state=succeeded==plan.items.size()?\'SUCCEEDED\':succeeded>0?\'PARTIAL\':cancelled>0?\'CANCELLED\':\'FAILED\';plan.finishedAt=new Date()\nsave(plan,plan.version);audit(\'物化执行完成\',plan,\'成功 \'+succeeded+\' 项，失败 \'+failed+\' 项，取消 \'+cancelled+\' 项\');return plan\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/03.materialization-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ad740688aec155419e89ac237559c727',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "ad740688aec155419e89ac237559c727",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "04.model-command",\r\n  "createTime" : null,\r\n  "updateTime" : 1791068444380,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/model-command",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 05.逻辑建模、冻结版本和数据项候选。模型草稿与标准候选在当前租户事务内写入。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.crypto.digest.DigestUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport \'@/resource-center/model-read\' as readModels\nimport \'@/resource-center/model-validate\' as validateModel\nimport \'@/resource-center/technical-read\' as technicalRead\nimport \'@/resource-center/planning-read\' as readPlanning\nvar tenantId = tenantRuntime.id()\nvar actorId = StpUtil.getLoginIdAsString()\nvar now = new Date()\nvar text = v => v == null ? \'\' : (v + \'\').trim()\nvar clone = v => JSONUtil.parse(jsons.toJSONStr(v))\nvar required = (v, label, max) => { var s = text(v); if (s == \'\' || s.length() > max) { exit 400,label + \'不能为空或超过长度限制\' }; return s }\nvar key = v => { var s = text(v); if (!s.matches(\'[A-Za-z_][A-Za-z0-9_]{0,62}\')) { exit 400,\'技术代码格式无效\' }; return s }\nvar find = (rows,id) => { for (r in rows) { if (r.id == id) { return r } }; exit 404,\'对象不存在或不属于当前租户\' }\nvar payload = input.body == null ? {} : input.body\nvar kind = text(input.kind); var id = text(input.id); var action = text(input.action); var method = text(input.method)\nvar state = readModels({entities:[]})\nvar content = m => ({entities:m.entities,relationships:m.relationships,nodes:m.nodes,outputEntityId:m.outputEntityId,fusion:m.fusion})\nvar check = m => { if (text(input.version) != text(m.version)) { exit 409,\'模型已更新，请刷新后重试\' } }\nvar audit = (verb,m,detail) => db.table(\'res_resource_operation_log\').primary(\'tid\').insert({tid:IdUtil.fastSimpleUUID(),tenant_id:tenantId,\n    actor_id:actorId,action_name:verb,object_id:m.id,object_name:m.name,detail_text:text(detail),created_time:now})\nvar designSummary = m => {\n    var fields = 0; var sources = 0\n    for (e in m.entities) { fields = fields + e.fields.size(); if (e.role == \'SOURCE\') { sources = sources + 1 } }\n    var mappings = m.fusion == null || m.fusion.mappings == null ? 0 : m.fusion.mappings.size()\n    return \'来源表 \' + sources + \' 张，设计实体 \' + m.entities.size() + \' 个，字段 \' + fields + \' 个，关系 \' + m.relationships.size() + \' 条，字段映射 \' + mappings + \' 条\'\n}\nvar logical = f => {\n    var t = text(f.typeFamily).toLowerCase()\n    if (t == \'integer\') { return \'Int64\' }; if (t == \'decimal\' || t == \'float\') { return \'Decimal\' }\n    if (t == \'date\') { return \'Date\' }; if (t == \'timestamp\') { return \'Timestamp\' }; if (t == \'boolean\') { return \'Boolean\' }\n    if (t == \'binary\') { return \'Binary\' }; return \'String\'\n}\nvar reverse = (ids,sourceId,occupiedNames) => {\n    if (ids == null || ids.size() == 0 || ids.size() > 300) { exit 400,\'请选择1至300张来源表\' }\n    var result = {entities:[],relationships:[],nodes:[]}\n    var technical = technicalRead({entityIds:ids})\n    if (technical.entities.size() != ids.size()) { exit 404,\'部分来源表不存在或不属于当前租户\' }\n    var usedNames = occupiedNames == null ? [] : occupiedNames\n    for (source in technical.entities) {\n        if (text(sourceId) != \'\' && text(source.sourceId) != text(sourceId)) { exit 409,\'所选技术表不属于当前来源数据库\' }\n        var e = clone(source); var fmap = {}; var originMap = {}\n        e.id = IdUtil.fastSimpleUUID(); e.sourceId = \'panshi-design\'; e.grain = \'\'; e.role = \'SOURCE\'\n        var originalName = text(source.name)\n        var safeName = originalName.replaceAll(\'[^A-Za-z0-9_]\',\'_\')\n        if (!safeName.matches(\'[A-Za-z_].*\')) { safeName = \'SRC_\' + safeName }\n        if (safeName.length() > 63) { safeName = safeName.substring(0,63) }\n        var alias = safeName; var suffix = 2\n        while (usedNames.contains(alias.toLowerCase())) { var ending = \'_S\' + suffix; alias = safeName.substring(0,Math.min(safeName.length(),63-ending.length())) + ending; suffix = suffix + 1 }\n        e.name = alias; usedNames.add(alias.toLowerCase())\n        for (f in e.fields) { var oldId = f.id; f.id = IdUtil.fastSimpleUUID(); fmap[oldId] = f.id; originMap[f.id] = oldId\n            f.logicalType = logical(f); if (f.logicalType == \'String\' && (f.length == null || f.length < 1)) { f.length = 128 }\n            if (f.logicalType == \'String\' && f.length > 4000) { f.logicalType = \'Text\' }\n            f.businessName = text(f.comment); f.remove(\'standard\') }\n        for (k in e.keys == null ? [] : e.keys) { k.id = IdUtil.fastSimpleUUID(); var ids2 = []; for (fid in k.fieldIds) { ids2.add(fmap[fid]) }; k.fieldIds = ids2 }\n        e.origin = {entityId:source.id,sourceId:source.sourceId,tableName:originalName,snapshotId:technical.manifest[source.sourceId],fieldMap:originMap}\n        result.entities.add(e); result.nodes.add({entityId:e.id,position:{x:120 + (result.entities.size() % 4) * 340,y:120 + (result.entities.size() / 4)::int * 500}})\n    }\n    return result\n}\nvar outputFrom = (m, first) => {\n    var outputName = m.code; var suffix = 1; var occupied = true\n    while (occupied) {\n        occupied = false\n        for (source in m.entities) { if (text(source.name).toLowerCase() == outputName.toLowerCase()) { occupied = true } }\n        if (occupied) { var ending = suffix == 1 ? \'_D\' : \'_D\' + suffix; outputName = m.code.substring(0,Math.min(m.code.length(),63-ending.length())) + ending; suffix = suffix + 1 }\n    }\n    var e = {id:IdUtil.fastSimpleUUID(),sourceId:\'panshi-design\',role:\'OUTPUT\',name:outputName,displayName:m.name,\n        kind:\'table\',fields:[],keys:[],grain:\'\',comment:text(m.description)}\n    var mappings = []\n    if (first != null) {\n        var fieldIds = {}\n        for (f in first.fields) {\n            var field = clone(f); var previous = field.id; field.id = IdUtil.fastSimpleUUID(); field.path = field.name\n            field.remove(\'origin\'); e.fields.add(field); fieldIds[previous] = field.id\n            mappings.add({id:IdUtil.fastSimpleUUID(),targetFieldId:field.id,sourceEntityId:first.id,\n                sourceFieldId:previous,transform:\'DIRECT\'})\n        }\n        for (k in first.keys == null ? [] : first.keys) {\n            var members = []; for (fid in k.fieldIds) { if (fieldIds[fid] != null) { members.add(fieldIds[fid]) } }\n            if (members.size() > 0) { e.keys.add({id:IdUtil.fastSimpleUUID(),kind:k.kind,fieldIds:members,enforced:\'unknown\',scope:\'full\'}) }\n        }\n    }\n    m.entities.add(e); m.nodes.add({entityId:e.id,position:{x:Math.max(700,m.entities.size()*350),y:120}})\n    m.outputEntityId = e.id; m.fusion = {baseEntityId:first == null ? null : first.id,joins:[],mappings:mappings}\n    return e\n}\nvar save = (m, fresh) => {\n    var designJson = jsons.toJSONStr(content(m))\n    if (fresh) {\n        db.table(\'res_logical_model\').primary(\'tid\').insert({tid:m.id,tenant_id:tenantId,model_code:m.code,model_name:m.name,model_type:m.method,\n            domain_name:m.domain,database_id:m.databaseId,owner_name:m.owner,model_status:m.state,model_description:m.description,\n            design_json:designJson,revision_no:1,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n    } else {\n        var changed = db.update(\'UPDATE res_logical_model SET model_name=#{name}, model_description=#{description},design_json=#{designJson},model_status=#{state}, revision_no=revision_no+1,updated_by=#{actorId},updated_time=#{now} WHERE tid=#{id} AND tenant_id=#{tenantId} AND is_del=0 AND revision_no=#{version}\',\n            {name:m.name,description:m.description,designJson:designJson,state:m.state,actorId:actorId,now:now,id:m.id,tenantId:tenantId,version:m.version})\n        if (changed != 1) { exit 409,\'模型已更新，请刷新后重试\' }; m.version = m.version + 1\n    }\n    // 历史单实体字段表继续作为查询投影；entity_id将同名字段隔离到各自实体。\n    var modelId = m.id\n    db.update(\'DELETE FROM res_logical_model_field WHERE tenant_id=#{tenantId} AND model_id=#{modelId}\')\n    for (e in m.entities) { for (f in e.fields) {\n        var pk = false; for (k in e.keys == null ? [] : e.keys) { if (k.kind == \'primary\' && k.fieldIds.contains(f.id)) { pk = true } }\n        db.table(\'res_logical_model_field\').primary(\'tid\').insert({tid:IdUtil.fastSimpleUUID(),tenant_id:tenantId,model_id:m.id,entity_id:e.id,\n            design_field_id:f.id,field_code:f.name,field_name:text(f.businessName),data_type:f.logicalType,data_length:f.length,\n            data_precision:f.precision,numeric_scale:f.scale,nullable_flag:f.nullable == \'false\' ? 0 : 1,primary_key_flag:pk ? 1 : 0,\n            standard_id:f.standard == null ? null : f.standard.id,standard_revision:f.standard == null ? null : f.standard.revisionId,\n            field_description:text(f.comment),sort_no:f.ordinal,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n    } }\n    m.updatedAt = now; return m\n}\nif (kind == \'itemsets\') {\n    var set = find(state.itemSets,id); check(set)\n    if (action != \'submit\' || set.state != \'DRAFT\') { exit 409,\'数据项集已提交或操作不支持\' }\n    var m = find(state.models,set.modelId)\n    return db.transaction(() => {\n        var items = clone(set.items); var created = 0\n        for (item in items) {\n            if (item.standardId != null || item.candidateId != null) { continue }\n            var e = find(m.entities,item.entityId); var f = find(e.fields,item.fieldId); var candidateId = IdUtil.fastSimpleUUID()\n            var candidateCode = \'PS_\' + candidateId.substring(0,20).toUpperCase()\n            var candidateName = text(f.businessName) == \'\' ? text(f.name) : text(f.businessName)\n            if (candidateName.length() > 50) { candidateName = candidateName.substring(0,50) }\n            var definition = text(f.comment); if (definition.length() > 255) { definition = definition.substring(0,255) }\n            db.table(\'da_metadata_t\').primary(\'tid\').insert({tid:candidateId,tenant_id:tenantId,meta_name:candidateName,meta_code:candidateCode,\n                standard_encode:candidateCode,biz_def:definition,field_type:f.logicalType,field_length:f.length,numeric_precision:f.precision,\n                numeric_scale:f.scale,is_nullable:f.nullable == \'false\' ? 0 : 1,publish_status:0,version_no:\'1\',created_by:actorId,\n                created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n            item.candidateId = candidateId\n            created = created + 1\n        }\n        var changed = db.update(\'UPDATE res_model_itemset SET items_json=#{json},itemset_status=\\\'SUBMITTED\\\',revision_no=revision_no+1,updated_time=#{now},updated_by=#{actorId} WHERE tid=#{id} AND tenant_id=#{tenantId} AND revision_no=#{version} AND is_del=0\',\n            {json:jsons.toJSONStr(items),now:now,actorId:actorId,id:id,tenantId:tenantId,version:set.version})\n        if (changed != 1) { exit 409,\'数据项集已经更新\' }; audit(\'提交标准候选\',set,\'提交 \' + items.size() + \' 个数据项，新建 \' + created + \' 个未发布标准候选草稿\')\n        set.items = items; set.state = \'SUBMITTED\'; set.version = set.version + 1; return set\n    })\n}\nif (kind != \'models\') { exit 400,\'不支持的模型对象类型\' }\nif (method == \'POST\' && id == \'\') {\n    var code = key(payload.code); for (old in state.models) { if (text(old.code).toLowerCase() == code.toLowerCase()) { exit 409,\'模型代码已存在\' } }\n    var planning = readPlanning({})\n    var database = find(planning.databases,required(payload.databaseId,\'目标分库\',64))\n    if (database.state != \'ACTIVE\') { exit 409,\'目标分库已归档\' }\n    var layer = find(planning.layers,text(database.layerId))\n    if (layer.state != \'ACTIVE\') { exit 409,\'目标分层已归档\' }\n    if (text(payload.layerId) != \'\' && text(payload.layerId) != text(layer.id)) { exit 400,\'目标分库不属于所选分层\' }\n    var domain = text(database.domain) == \'\' ? text(database.name) : text(database.domain)\n    if (domain.length() > 128) { domain = domain.substring(0,128) }\n    var m = {id:IdUtil.fastSimpleUUID(),version:1,name:required(payload.name,\'模型名称\',255),code:code,domain:domain,\n        description:text(payload.description),databaseId:database.id,owner:text(payload.owner) == \'\' ? actorId : text(payload.owner),\n        method:text(payload.method) == \'\' ? \'MANUAL\' : payload.method,state:\'ACTIVE\',entities:[],relationships:[],nodes:[],frozen:[],createdAt:now,updatedAt:now}\n    if (![\'MANUAL\',\'STANDARD\',\'REVERSE\'].contains(m.method)) { exit 400,\'不支持的建模方式\' }\n    if (m.method == \'REVERSE\') { var r = reverse(payload.entityIds,payload.sourceId,[]); if(r.entities.size()==0){exit 400,\'请选择至少一张来源技术表\'}; m.entities = r.entities; m.nodes = r.nodes; outputFrom(m,m.entities[0]) }\n    if (m.method == \'STANDARD\') {\n        if (payload.standardIds == null || payload.standardIds.size() == 0) { exit 400,\'请选择已发布标准\' }\n        var standards = technicalRead({entityIds:[]}).standards\n        var e = outputFrom(m,null)\n        for (sid in payload.standardIds) {\n            var st = find(standards,sid); if (st.status != \'PUBLISHED\' || st.publishedRevisionId == null) { exit 409,\'仅可引用已发布标准\' }\n            var name = text(st.code).matches(\'[A-Za-z_][A-Za-z0-9_]{0,62}\') ? st.code : \'field_\' + (e.fields.size() + 1)\n            var f = {id:IdUtil.fastSimpleUUID(),name:name,path:name,ordinal:e.fields.size(),nativeType:st.type,typeFamily:st.typeFamily == null ? \'string\' : st.typeFamily,\n                nullable:\'true\',businessName:st.name,comment:st.definition,length:st.length,precision:st.precision,scale:st.scale,standard:{id:st.id,revisionId:st.publishedRevisionId}}\n            f.logicalType = logical(f)\n            if (f.logicalType == \'String\' && (f.length == null || f.length < 1)) { f.length = 128 }\n            if (f.logicalType == \'String\' && f.length > 4000) { f.logicalType = \'Text\' }\n            e.fields.add(f)\n        }\n    }\n    if (m.method == \'MANUAL\') { outputFrom(m,null) }\n    var methodName = m.method == \'REVERSE\' ? \'逆向解析\' : m.method == \'STANDARD\' ? \'依标建模\' : \'手工建模\'\n    return db.transaction(() => { save(m,true); audit(\'创建逻辑模型\',m,\'创建方式：\' + methodName + \'；目标分层：\' + layer.name + \'；目标分库：\' + database.name + \'；\' + designSummary(m)); return m })\n}\nvar m = find(state.models,id)\nif (method == \'GET\' && action == \'\') { return m }\nif (action == \'validate\') { return validateModel(clone(m)) }\ncheck(m)\nif (m.state != \'ACTIVE\' && action != \'copy\') { exit 409,\'模型已归档\' }\nvar logDetail = \'\'\nif (method == \'PUT\' && action == \'\') {\n    var previousName = m.name; var previousDescription = m.description; var previousDesign = jsons.toJSONStr(content(m))\n    if (payload.content != null) {\n        var c = payload.content\n        if (c.entities == null || c.entities.size() > 300 || c.relationships == null || c.nodes == null || jsons.toJSONStr(c).length() > 5000000) { exit 400,\'无效或过大的模型内容\' }\n        var ids = []\n        for (e in c.entities) { if (text(e.id) == \'\' || ids.contains(e.id) || e.fields == null || e.fields.size() > 1000) { exit 400,\'实体标识重复或字段不合法\' }; ids.add(e.id)\n            var original = null; for (old in m.entities) { if (old.id == e.id) { original = old } }\n            if (e.reference != null && (original == null || original.reference == null)) { exit 400,\'请通过引用入口添加参照实体\' }\n            if (original == null && m.outputEntityId != null) { exit 409,\'融合模型请通过逆向解析添加来源表，目标表 D 只能有一张\' }\n            if (original != null && original.reference != null && jsons.toJSONStr(original) != jsons.toJSONStr(e)) { exit 409,\'参照实体只读\' }\n            if (original != null && original.role == \'SOURCE\' && jsons.toJSONStr(original) != jsons.toJSONStr(e)) { exit 409,\'来源技术快照只读\' }\n        }\n        m.entities = c.entities; m.relationships = c.relationships; m.nodes = c.nodes\n        if (m.outputEntityId != null || c.outputEntityId != null) {\n            if (m.outputEntityId != null && text(c.outputEntityId) != text(m.outputEntityId)) { exit 409,\'目标输出表不能在保存时改写\' }\n            m.outputEntityId = c.outputEntityId; m.fusion = c.fusion\n        }\n    }\n    if (payload.name != null) { m.name = required(payload.name,\'模型名称\',255) }; if (payload.description != null) { m.description = text(payload.description) }\n    var changes = []\n    if (previousName != m.name) { changes.add(\'模型名称由“\' + previousName + \'”改为“\' + m.name + \'”\') }\n    if (previousDescription != m.description) { changes.add(\'业务说明已修改\') }\n    if (previousDesign != jsons.toJSONStr(content(m))) { changes.add(\'画布实体、字段、关系或映射已修改\') }\n    logDetail = (changes.size() == 0 ? \'未检测到设计内容变化\' : changes.join(\'；\')) + \'；\' + designSummary(m)\n} else if (action == \'freeze\') {\n    var validation = validateModel(clone(m)); if (!validation.valid) { exit 422,validation.errors.join(\'；\') }\n    var standards = technicalRead({entityIds:[]}).standards\n    for (e in m.entities) { for (f in e.fields) { if (f.standard != null) {\n        var st = find(standards,f.standard.id)\n        if (st.status != \'PUBLISHED\' || st.publishedRevisionId != f.standard.revisionId) { exit 409,\'引用标准已变化，请重新核对：\' + f.name }\n    } } }\n    return db.transaction(() => {\n        save(m,false)\n        var rev = content(clone(m)); rev.id = IdUtil.fastSimpleUUID(); rev.number = m.frozen.size() + 1\n        rev.note = required(payload.note,\'版本说明\',1000); rev.createdAt = now; rev.signature = DigestUtil.sha256Hex(jsons.toJSONStr(content(m)))\n        db.table(\'res_logical_model_revision\').primary(\'tid\').insert({tid:rev.id,tenant_id:tenantId,model_id:id,revision_number:rev.number,\n            content_json:jsons.toJSONStr(content(m)),content_hash:rev.signature,note:rev.note,created_by:actorId,created_time:now})\n        m.frozen.add(rev); audit(\'冻结设计版本\',m,\'冻结为 v\' + rev.number + \'；版本说明：\' + rev.note + \'；\' + designSummary(m)); return rev\n    })\n} else if (action == \'reverse\') {\n    var occupied = [];for(existing in m.entities){occupied.add(text(existing.name).toLowerCase())}\n    var r = reverse(payload.entityIds,payload.sourceId,occupied); for (e in r.entities) { for (existing in m.entities) { if (existing.origin != null && text(existing.origin.entityId) == text(e.origin.entityId)) { exit 409,\'该技术表已加入模型：\' + text(e.origin.tableName) } }; m.entities.add(e) }\n    m.nodes.addAll(r.nodes)\n    if (m.outputEntityId == null && r.entities.size() > 0) { outputFrom(m,r.entities[0]) }\n    logDetail = \'导入来源技术表 \' + r.entities.size() + \' 张；\' + designSummary(m)\n} else if (action == \'bind\') {\n    var e = find(m.entities,text(payload.entityId)); if (e.reference != null || e.role == \'SOURCE\') { exit 409,\'来源或参照实体只读\' }\n    var f = find(e.fields,text(payload.fieldId)); var st = find(technicalRead({entityIds:[]}).standards,text(payload.standardId))\n    if (st.status != \'PUBLISHED\') { exit 409,\'仅允许关联已发布标准\' }\n    f.standard = {id:st.id,revisionId:st.publishedRevisionId}\n    if (payload.apply == true) { f.businessName = st.name; f.nativeType = st.type; f.typeFamily = st.typeFamily == null ? \'string\' : st.typeFamily\n        f.length = st.length; f.precision = st.precision; f.scale = st.scale; f.logicalType = logical(f) }\n    logDetail = \'设计字段 \' + e.name + \'.\' + f.name + \' 绑定标准 \' + st.name + \'（\' + st.code + \'）\' + (payload.apply == true ? \'，并应用标准字段定义\' : \'，仅建立引用\')\n} else if (action == \'copy\' || action == \'reference\') {\n    var source = action == \'copy\' ? m : find(state.models,text(payload.modelId))\n    var sourceName = source.name\n    if (action == \'reference\' && source.id == m.id) { exit 409,\'模型不能引用自身\' }\n    var copied = action == \'copy\' ? content(clone(source)) : clone(find(source.frozen,text(payload.revisionId)))\n    var map = {}\n    for (e in copied.entities) { map[e.id] = IdUtil.fastSimpleUUID(); for (f in e.fields) { map[f.id] = IdUtil.fastSimpleUUID() } }\n    for (e in copied.entities) {\n        if (action == \'reference\' && e.reference != null && e.reference.modelId == m.id) { exit 409,\'不允许循环参照\' }\n        e.id = map[e.id]; for (f in e.fields) { f.id = map[f.id] }\n        for (k in e.keys == null ? [] : e.keys) { k.id = IdUtil.fastSimpleUUID(); var fields = []; for (fid in k.fieldIds) { fields.add(map[fid]) }; k.fieldIds = fields }\n        if (action == \'reference\') { e.reference = {modelId:source.id,revisionId:payload.revisionId} } else { e.remove(\'reference\') }\n    }\n    for (r in copied.relationships) { r.id = IdUtil.fastSimpleUUID(); r.sourceEntityId = map[r.sourceEntityId]; r.targetEntityId = map[r.targetEntityId]\n        for (p in r.mappings) { p.sourceFieldId = map[p.sourceFieldId]; p.targetFieldId = map[p.targetFieldId] } }\n    for (n in copied.nodes) { n.entityId = map[n.entityId] }\n    if (copied.outputEntityId != null) {\n        copied.outputEntityId = map[copied.outputEntityId]\n        if (copied.fusion != null) {\n            copied.fusion.baseEntityId = map[copied.fusion.baseEntityId]\n            for (j in copied.fusion.joins == null ? [] : copied.fusion.joins) {\n                j.id = IdUtil.fastSimpleUUID(); j.leftEntityId = map[j.leftEntityId]; j.rightEntityId = map[j.rightEntityId]\n                j.orderFieldId = j.orderFieldId == null ? null : map[j.orderFieldId]\n                for (p in j.pairs) { p.leftFieldId = map[p.leftFieldId]; p.rightFieldId = map[p.rightFieldId] }\n            }\n            for (mapping in copied.fusion.mappings == null ? [] : copied.fusion.mappings) {\n                mapping.id = IdUtil.fastSimpleUUID(); mapping.targetFieldId = map[mapping.targetFieldId]\n                mapping.sourceEntityId = map[mapping.sourceEntityId]; mapping.sourceFieldId = map[mapping.sourceFieldId]\n            }\n        }\n    }\n    if (action == \'copy\') {\n        m = clone(m); m.id = IdUtil.fastSimpleUUID(); m.name = required(payload.name,\'副本名称\',255); m.code = key(payload.code)\n        for (existing in state.models) { if (text(existing.code).toLowerCase() == text(m.code).toLowerCase()) { exit 409,\'副本代码已存在\' } }\n        m.version = 1; m.method = \'COPY\'; m.state = \'ACTIVE\'; m.frozen = []; m.createdAt = now\n        m.entities = copied.entities; m.relationships = copied.relationships; m.nodes = copied.nodes\n        m.outputEntityId = copied.outputEntityId; m.fusion = copied.fusion\n        return db.transaction(() => { save(m,true); audit(\'复制逻辑模型\',m,\'复制自模型 \' + sourceName + \'；\' + designSummary(m)); return m })\n    }\n    for (e in copied.entities) { for (old in m.entities) { if (text(old.name).toLowerCase() == text(e.name).toLowerCase()) { exit 409,\'引用实体名称已存在：\' + e.name } } }\n    m.entities.addAll(copied.entities); m.relationships.addAll(copied.relationships); m.nodes.addAll(copied.nodes)\n    logDetail = \'引用模型 \' + sourceName + \' 的冻结版本，共加入 \' + copied.entities.size() + \' 个只读实体；\' + designSummary(m)\n} else if (action == \'archive\') {\n    for (p in state.materializations) { if (p.modelId == id && [\'READY\',\'QUEUED\',\'RUNNING\',\'CANCELLING\'].contains(p.state)) { exit 409,\'尚有未完成物化方案\' } }; m.state = \'ARCHIVED\'\n    logDetail = \'模型已归档；历史版本和操作日志保留，后续不再参与设计与标准化\'\n} else if (action == \'items\') {\n    var items = []; for (e in m.entities) { if (e.reference != null || (m.outputEntityId != null && e.id != m.outputEntityId)) { continue }; for (f in e.fields) { items.add({entityId:e.id,fieldId:f.id,name:text(f.businessName) == \'\' ? f.name : f.businessName,standardId:f.standard == null ? null : f.standard.id}) } }\n    if (items.size() == 0) { exit 400,\'模型没有可生成数据项集的字段\' }\n    var bound = 0; for (item in items) { if (item.standardId != null) { bound = bound + 1 } }\n    var setId = IdUtil.fastSimpleUUID(); var name = m.name + \'数据项集\'\n    db.table(\'res_model_itemset\').primary(\'tid\').insert({tid:setId,tenant_id:tenantId,model_id:id,itemset_name:name,items_json:jsons.toJSONStr(items),itemset_status:\'DRAFT\',revision_no:1,created_by:actorId,created_time:now,updated_by:actorId,updated_time:now,is_del:0})\n    audit(\'生成模型数据项集\',{id:setId,name:name},\'来源模型：\' + m.name + \'；生成 \' + items.size() + \' 个数据项，其中已绑定标准 \' + bound + \' 个\'); return {id:setId,name:name,modelId:id,items:items,state:\'DRAFT\',version:1,createdAt:now,updatedAt:now}\n} else { exit 400,\'不支持的模型操作\' }\nreturn db.transaction(() => { save(m,false); audit(\'维护逻辑模型：\' + (action == \'\' ? \'保存\' : action),m,logDetail + \'；设计修订 v\' + m.version); return m })\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/04.model-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('7a5e47d9db00585f8d0feeefedcd6465',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "7a5e47d9db00585f8d0feeefedcd6465",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "05.model-read",\r\n  "createTime" : null,\r\n  "updateTime" : 1791068403811,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/model-read",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 03.读取逻辑模型、不可变版本、物化方案和共享库表资源。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport \'@/resource-center/technical-read\' as technicalRead\nvar tenantId = tenantRuntime.id()\nvar text = v => v == null ? \'\' : v + \'\'\nvar parse = v => text(v) == \'\' ? {} : JSONUtil.parse(v)\nvar models = []\nvar modelRows = db.select(\'SELECT * FROM res_logical_model WHERE tenant_id=#{tenantId} AND is_del=0 ORDER BY updated_time DESC\')\nvar revisionRows = db.select(\'SELECT * FROM res_logical_model_revision WHERE tenant_id=#{tenantId} ORDER BY revision_number\')\nfor (r in modelRows) {\n    var design = parse(r.designJson)\n    var frozen = []\n    for (v in revisionRows) { if (v.modelId == r.tid) {\n        var snapshot = parse(v.contentJson)\n        snapshot.id = text(v.tid); snapshot.number = v.revisionNumber; snapshot.note = v.note\n        snapshot.signature = v.contentHash; snapshot.createdAt = v.createdTime\n        frozen.add(snapshot)\n    } }\n    models.add({id:text(r.tid),version:r.revisionNo,createdAt:r.createdTime,updatedAt:r.updatedTime,\n        name:r.modelName,code:r.modelCode,domain:text(r.domainName),description:text(r.modelDescription),\n        databaseId:r.databaseId,owner:text(r.ownerName),method:text(r.modelType),state:r.modelStatus == \'ARCHIVED\' ? \'ARCHIVED\' : \'ACTIVE\',\n        entities:design.entities == null ? [] : design.entities,relationships:design.relationships == null ? [] : design.relationships,\n        nodes:design.nodes == null ? [] : design.nodes,outputEntityId:design.outputEntityId,fusion:design.fusion,frozen:frozen})\n}\nvar plans = []\nfor (r in db.select(\'SELECT * FROM res_materialization_plan WHERE tenant_id=#{tenantId} AND is_del=0 AND plan_json IS NOT NULL ORDER BY updated_time DESC\')) {\n    var plan = parse(r.planJson)\n    plan.id = text(r.tid); plan.version = r.revisionNo; plan.state = r.planStatus\n    plan.createdAt = r.createdTime; plan.updatedAt = r.updatedTime\n    plans.add(plan)\n}\nvar tables = db.select(\'SELECT * FROM db_table_t WHERE tenant_id=#{tenantId} AND is_del=0 AND resource_domain_id IS NOT NULL ORDER BY updated_time DESC\')\nvar ids = []; for (r in tables) { ids.add(text(r.tid)) }\nvar entities = input != null && input.entities != null ? input.entities : (ids.size() == 0 ? [] : technicalRead({entityIds:ids}).entities)\nvar entityMap = {}; for (e in entities) { entityMap[e.id] = e }\nvar resources = []\nfor (r in tables) {\n    var e = entityMap[text(r.tid)]\n    if (e == null) { continue }\n    resources.add({id:text(r.tid),entityId:text(r.tid),version:r.resourceRevisionNo,createdAt:r.createdTime,updatedAt:r.updatedTime,\n        structure:e,structureRevisionId:text(r.revision),name:text(r.tableNameCn) == \'\' ? r.tableName : r.tableNameCn,\n        databaseId:r.resourceDomainId,domain:r.businessType,owner:text(r.resourceOwner),description:text(r.assetDesc),\n        origin:r.resourcePlanId == null ? \'SNAPSHOT\' : \'MATERIALIZATION\',state:r.resourceState,\n        modelId:r.resourceModelId,deploymentId:r.resourcePlanId,designFieldMap:parse(r.resourceFieldMap)})\n}\nvar itemsets = []\nfor (r in db.select(\'SELECT * FROM res_model_itemset WHERE tenant_id=#{tenantId} AND is_del=0 ORDER BY updated_time DESC\')) {\n    itemsets.add({id:text(r.tid),version:r.revisionNo,createdAt:r.createdTime,updatedAt:r.updatedTime,\n        name:r.itemsetName,modelId:r.modelId,items:JSONUtil.parse(r.itemsJson),state:r.itemsetStatus})\n}\n// Magic\'s SQL mapper folds unquoted aliases; normalize both forms before returning logs.\nvar logs = db.select(\'SELECT tid AS `id`,actor_id AS `actorId`,action_name AS `action`,object_id AS `objectId`,object_name AS `name`,detail_text AS `detail`,created_time AS `time` FROM res_resource_operation_log WHERE tenant_id=#{tenantId} ORDER BY created_time DESC LIMIT 2000\')\nvar actorIds = []\nfor (log in logs) {\n    log.actorId = text(log.actorId) == \'\' ? text(log.actorid) : text(log.actorId)\n    log.objectId = text(log.objectId) == \'\' ? text(log.objectid) : text(log.objectId)\n    if (log.actorId != \'\' && !actorIds.contains(log.actorId)) { actorIds.add(log.actorId) }\n}\nif (actorIds.size() > 0) {\n    try {\n        // Resolve only users named in this tenant\'s audit records, without a collation-sensitive join.\n        var actorNames = {}\n        var users = db.table(\'rm_user_t\').where().eq(\'tenant_id\',tenantId).in(\'id\',actorIds).select()\n        for (u in users) {\n            var realName = text(u.realName) == \'\' ? text(u.real_name) : text(u.realName)\n            var userName = text(u.userName) == \'\' ? text(u.user_name) : text(u.userName)\n            actorNames[text(u.id)] = realName == \'\' ? userName : realName\n        }\n        for (log in logs) { log.actorName = actorNames[log.actorId] }\n    } catch(e) { /* retain actor IDs when a tenant has no local user directory */ }\n}\nreturn {models:models,materializations:plans,resources:resources,itemSets:itemsets,logs:logs}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/05.model-read.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('779419e5edd654dd9f851a610cdb6033',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "779419e5edd654dd9f851a610cdb6033",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "06.model-validate",\r\n  "createTime" : null,\r\n  "updateTime" : 1791019420687,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/model-validate",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 04.模型服务端校验。提交者不能以浏览器预检结果替代实体/字段/引用检查。\nimport tenantRuntime\nimport \'@/resource-center/technical-read\' as technicalRead\nvar tenantId = tenantRuntime.id()\nvar model = input\nvar errors = []\nvar text = v => v == null ? \'\' : v + \'\'\nvar entities = model.entities == null ? [] : model.entities\nif (entities.size() == 0 || entities.size() > 300) { errors.add(\'模型须包含1至300个实体\') }\nvar names = []; var allIds = []; var byId = {}\nfor (e in entities) {\n    if (!text(e.name).matches(\'[A-Za-z_][A-Za-z0-9_]{0,62}\')) { errors.add(\'实体技术名称不合法：\' + text(e.name)) }\n    if (names.contains(text(e.name).toLowerCase()) || allIds.contains(e.id)) { errors.add(\'实体名称或标识重复\') }\n    names.add(text(e.name).toLowerCase()); allIds.add(e.id); byId[e.id] = e\n    var fieldNames = []; var fieldIds = []\n    if (e.fields == null || e.fields.size() == 0 || e.fields.size() > 1000) { errors.add(\'每个实体须包含1至1000个字段\'); continue }\n    for (f in e.fields) {\n        if (!text(f.name).matches(\'[A-Za-z_][A-Za-z0-9_]{0,62}\')) { errors.add(\'字段技术名称不合法：\' + text(f.name)) }\n        if (fieldNames.contains(text(f.name).toLowerCase()) || fieldIds.contains(f.id)) { errors.add(\'字段名称或标识重复：\' + e.name) }\n        fieldNames.add(text(f.name).toLowerCase()); fieldIds.add(f.id)\n        if (![\'String\',\'Text\',\'Int32\',\'Int64\',\'Decimal\',\'Boolean\',\'Date\',\'Timestamp\',\'Binary\',\'UUID\',\'JSON\',\'Array\',\'Object\'].contains(f.logicalType)) { errors.add(\'字段逻辑类型无效：\' + f.name) }\n        if (f.length != null && (f.length < 1 || f.length > 1048576)) { errors.add(\'字段长度超出允许范围：\' + f.name) }\n        if (f.precision != null && (f.precision < 1 || f.precision > 38)) { errors.add(\'数值精度须为1至38：\' + f.name) }\n        if (f.scale != null && (f.scale < 0 || (f.precision != null && f.scale > f.precision))) { errors.add(\'数值小数位无效：\' + f.name) }\n    }\n    for (k in e.keys == null ? [] : e.keys) {\n        if (k.fieldIds == null || k.fieldIds.size() == 0) { errors.add(\'键必须包含字段：\' + e.name); continue }\n        for (fid in k.fieldIds) { if (!fieldIds.contains(fid)) { errors.add(\'键引用不存在的字段：\' + e.name) } }\n    }\n    e._validatedFields = fieldIds\n}\nfor (r in model.relationships == null ? [] : model.relationships) {\n    var source = byId[r.sourceEntityId]; var target = byId[r.targetEntityId]\n    if (source == null || target == null) { errors.add(\'关系端点不属于该模型\'); continue }\n    if (r.mappings == null || r.mappings.size() == 0) { errors.add(\'关系缺少字段映射\'); continue }\n    for (m in r.mappings) {\n        if (!source._validatedFields.contains(m.sourceFieldId) || !target._validatedFields.contains(m.targetFieldId)) { errors.add(\'关系映射引用不存在的字段\') }\n    }\n}\nif (text(model.outputEntityId) != \'\' || model.fusion != null) {\n    var output = byId[text(model.outputEntityId)]\n    if (output == null || output.role != \'OUTPUT\') { errors.add(\'模型必须指定唯一目标输出表\') }\n    var sources = []; var outputCount = 0\n    for (e in entities) { if (e.role == \'SOURCE\') { sources.add(e) }; if (e.role == \'OUTPUT\') { outputCount = outputCount + 1 } }\n    if (outputCount != 1) { errors.add(\'模型只能包含一张输出表\') }\n    var fusion = model.fusion == null ? {joins:[],mappings:[]} : model.fusion\n    var joins = fusion.joins == null ? [] : fusion.joins\n    var mappings = fusion.mappings == null ? [] : fusion.mappings\n    if (sources.size() > 0) {\n        var reached = [text(fusion.baseEntityId)]\n        if (byId[text(fusion.baseEntityId)] == null || byId[text(fusion.baseEntityId)].role != \'SOURCE\') { errors.add(\'请选择来源驱动表\') }\n        var joinedRight = []\n        for (j in joins) {\n            var left = byId[text(j.leftEntityId)]; var right = byId[text(j.rightEntityId)]\n            if (left == null || right == null || left.role != \'SOURCE\' || right.role != \'SOURCE\' || left.id == right.id) { errors.add(\'融合关联只能连接两张不同的来源表\'); continue }\n            if (joinedRight.contains(right.id) || right.id == fusion.baseEntityId) { errors.add(\'每张接入表只能有一条入向关联，驱动表不能作为右表\') }; joinedRight.add(right.id)\n            if (![\'LEFT\',\'INNER\'].contains(j.joinType)) { errors.add(\'关联方式仅支持 LEFT 或 INNER JOIN\') }\n            if (![\'ONE\',\'MANY\'].contains(j.rightCardinality) || ![\'NONE\',\'LATEST\'].contains(j.dedupe)) { errors.add(\'关联基数或重复取值方式无效\') }\n            if (j.pairs == null || j.pairs.size() == 0) { errors.add(\'融合关联缺少字段键\'); continue }\n            var pairKeys=[]\n            for (pair in j.pairs) {\n                if (!left._validatedFields.contains(pair.leftFieldId) || !right._validatedFields.contains(pair.rightFieldId)) { errors.add(\'融合关联引用了不存在的字段\') }\n                var leftField=null;var rightField=null\n                for(f in left.fields){if(f.id==pair.leftFieldId){leftField=f}}\n                for(f in right.fields){if(f.id==pair.rightFieldId){rightField=f}}\n                if(leftField!=null&&rightField!=null&&leftField.logicalType!=rightField.logicalType){errors.add(\'融合关联字段类型不一致：\'+text(leftField.name)+\' = \'+text(rightField.name))}\n                var pairKey=text(pair.leftFieldId)+\'/\'+text(pair.rightFieldId);if(pairKeys.contains(pairKey)){errors.add(\'融合关联键重复\')};pairKeys.add(pairKey)\n            }\n            if (j.rightCardinality == \'MANY\' && j.dedupe != \'LATEST\') { errors.add(\'右表可能多条时须指定取最新一条，避免结果行数膨胀\') }\n            if (j.rightCardinality == \'ONE\' && j.dedupe != \'NONE\') { errors.add(\'右表关联键唯一时不需要取最新记录\') }\n            if (j.dedupe == \'LATEST\' && !right._validatedFields.contains(j.orderFieldId)) { errors.add(\'取最新记录需要有效排序字段\') }\n        }\n        var pass = 0\n        while (pass < joins.size()) { pass = pass + 1; for (j in joins) {\n            if (!reached.contains(text(j.leftEntityId)) || reached.contains(text(j.rightEntityId))) { continue }\n            reached.add(text(j.rightEntityId))\n        } }\n        for (e in sources) { if (!reached.contains(text(e.id))) { errors.add(\'来源表未通过融合关联接入驱动表：\' + text(e.name)) } }\n        var mapped = []\n        for (mapping in mappings) {\n            var from = byId[text(mapping.sourceEntityId)]\n            if (from == null || from.role != \'SOURCE\' || !from._validatedFields.contains(mapping.sourceFieldId)) { errors.add(\'输出字段映射来源无效\'); continue }\n            if (output == null || !output._validatedFields.contains(mapping.targetFieldId)) { errors.add(\'输出字段映射目标无效\'); continue }\n            if (mapped.contains(mapping.targetFieldId)) { errors.add(\'输出字段重复映射：\' + text(mapping.targetFieldId)) }\n            if (![\'DIRECT\',\'TRIM\',\'UPPER\',\'LOWER\'].contains(mapping.transform)) { errors.add(\'输出字段转换方式无效\') }\n            var sourceField=null;for(f in from.fields){if(f.id==mapping.sourceFieldId){sourceField=f}}\n            var targetField=null;for(f in output.fields){if(f.id==mapping.targetFieldId){targetField=f}}\n            if(sourceField!=null&&targetField!=null&&sourceField.logicalType!=targetField.logicalType){errors.add(\'来源与目标字段类型不一致，请先调整目标字段：\'+text(targetField.name))}\n            if(sourceField!=null&&mapping.transform!=\'DIRECT\'&&![\'String\',\'Text\'].contains(sourceField.logicalType)){errors.add(\'文本转换只适用于字符字段：\'+text(sourceField.name))}\n            mapped.add(mapping.targetFieldId)\n        }\n        if (output != null) { for (f in output.fields) { if (!mapped.contains(f.id)) { errors.add(\'输出字段未映射：\' + text(f.name)) } } }\n    }\n}\nfor (e in entities) { e.remove(\'_validatedFields\') }\nreturn {valid:errors.size() == 0,errors:errors,checks:errors.size() == 0 ? [{level:\'INFO\',message:\'实体、字段、键与关系校验通过\'}] : []}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/06.model-validate.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('fa237a4aca795e95b6a1086b2e3ed012',NULL,'function','{\n  "properties": {},\n  "id": "fa237a4aca795e95b6a1086b2e3ed012",\n  "script": null,\n  "groupId": "8b36eff777cc5cc6a8cf7c3048cd8b82",\n  "name": "07.planning-command",\n  "createTime": null,\n  "updateTime": 1790989934805,\n  "lock": null,\n  "createBy": null,\n  "updateBy": null,\n  "path": "/planning-command",\n  "description": null,\n  "returnType": null,\n  "mappingPath": null,\n  "parameters": [\n    {\n      "name": "input",\n      "value": null,\n      "description": null,\n      "required": false,\n      "dataType": "Object",\n      "type": null,\n      "defaultValue": null,\n      "validateType": null,\n      "error": null,\n      "expression": null,\n      "children": null\n    }\n  ]\n}\n================================\n// 02.维护共享数仓规划：沿用字典层/域与单节点主数据源关联，不执行物理迁库。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.core.util.IdUtil\nimport cn.hutool.crypto.digest.DigestUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport \'@/resource-center/planning-read\' as readPlanning\n\nvar tenantId = tenantRuntime.id()\nvar actorId = StpUtil.getLoginIdAsString()\nvar text = value => value == null ? \'\' : (value + \'\').trim()\nvar payload = input.body == null ? {} : input.body\nvar kind = text(input.kind)\nvar id = text(input.id)\nvar action = text(input.action)\nvar method = text(input.method).toUpperCase()\nvar now = new Date()\nvar required = (value, name, max) => {\n    var result = text(value)\n    if (result == \'\' || result.length() > max) { exit 400, name + \'不能为空或超过长度限制\' }\n    return result\n}\nvar identifier = value => {\n    var result = text(value)\n    if (!result.matches(\'[A-Za-z][A-Za-z0-9_]{0,62}\')) { exit 400, \'技术代码须以字母开头，仅包含字母、数字和下划线\' }\n    return result\n}\nvar current = readPlanning({})\nvar find = (list, key) => {\n    for (item in list) { if (item.id == key) { return item } }\n    exit 404, \'记录不存在或不属于当前租户\'\n}\nvar checkVersion = row => {\n    if (input.version == null || text(input.version) != text(row.version)) { exit 409, \'记录已更新，请刷新后重试\' }\n}\nif (kind == \'bindings\') {\n    var targetType = text(payload.targetType)\n    if (targetType == \'\') { targetType = \'domain\' }\n    if (![\'layer\',\'domain\'].contains(targetType)) { exit 400, \'不支持的绑定节点类型\' }\n    var old = id == \'\' ? null : find(current.bindings, id)\n    var targetId = text(payload.targetId)\n    if (targetId == \'\') { targetId = old == null ? text(payload.databaseId) : old.databaseId }\n    var target = targetType == \'layer\' ? find(current.layers, targetId) : find(current.databases, targetId)\n    if (target.state != \'ACTIVE\') { exit 409, \'该规划节点已归档\' }\n    if (old != null && old.databaseId != targetId) { exit 409, \'绑定节点与原记录不一致\' }\n    var relation = db.selectOne("""\n        SELECT tid, datasource_id AS source_id, configuration_json AS config,\n               revision_no AS version\n          FROM dwm_center_layer_source_t\n         WHERE tenant_id = #{tenantId} AND target_type = #{targetType}\n           AND target_id = #{targetId} AND is_del = 0\n         ORDER BY updated_time DESC, tid DESC LIMIT 1\n    """)\n    if (input.version != null && (relation == null || text(input.version) != text(relation.version))) {\n        exit 409, \'绑定已更新，请刷新后重试\'\n    }\n    if (action == \'check\') {\n        if (targetType != \'domain\' || old == null) { exit 400, \'仅支持校验分库绑定\' }\n        if (old.category != \'RELATIONAL\') { exit 400, \'仅可核对已启用物化的分库\' }\n        var config = {environment: old.environment, catalog: old.catalog, schema: old.schema,\n            prefix: old.prefix, category: old.category, checkedHash: old.currentHash, checkedAt: now}\n        if (old.catalog == \'\' && old.schema == \'\') { exit 400, \'请先设置数据库或 Schema\' }\n        for (other in current.bindings) {\n            if (other.id != id && other.category != \'REFERENCE\' && old.category != \'REFERENCE\' &&\n                other.sourceId == old.sourceId && other.environment == old.environment &&\n                other.catalog == old.catalog && other.schema == old.schema) { exit 409, \'该命名空间已由另一分库管理\' }\n        }\n        var expected = old.version\n        var changed = db.update("""\n            UPDATE dwm_center_layer_source_t SET configuration_json = #{configJson},\n                   revision_no = revision_no + 1, updated_time = #{now}\n             WHERE tid = #{id} AND tenant_id = #{tenantId} AND is_del = 0 AND revision_no = #{expected}\n        """, {configJson: jsons.toJSONStr(config), now: now, id: id, tenantId: tenantId, expected: expected})\n        if (changed != 1) { exit 409, \'绑定配置已更新，请重新检查\' }\n        return {id: id, checked: true, connectionTested: false}\n    }\n    if (action != \'\' || ![\'POST\',\'PUT\'].contains(method)) { exit 400, \'不支持的绑定操作\' }\n    var sourceId = text(payload.sourceId)\n    if (sourceId.length() > 32) { exit 400, \'数据源标识过长\' }\n    if (sourceId == \'\') {\n        if (relation == null) { return {saved: true, cleared: true} }\n        var removed = db.update("""\n            UPDATE dwm_center_layer_source_t SET is_del = 1, revision_no = revision_no + 1,\n                   updated_time = #{now}\n             WHERE tid = #{relation.tid} AND tenant_id = #{tenantId}\n               AND revision_no = #{relation.version} AND is_del = 0\n        """)\n        if (removed != 1) { exit 409, \'绑定已更新，请刷新后重试\' }\n        return {id: text(relation.tid), saved: true, cleared: true}\n    }\n    var source = db.selectOne("""\n        SELECT tid, db_type AS profile FROM db_datasource_t\n         WHERE tid = #{sourceId} AND tenant_id = #{tenantId} AND is_del = 0\n    """)\n    if (source == null) { exit 404, \'共享数据源不存在\' }\n    var configurationSupplied = payload.environment != null || payload.catalog != null || payload.schema != null ||\n        payload.prefix != null || payload.category != null\n    if (relation != null && text(relation.sourceId) == sourceId && !configurationSupplied) {\n        return {id: text(relation.tid), saved: true, unchanged: true}\n    }\n    var previous = relation == null || text(relation.sourceId) != sourceId ? {} : jsons.toJSONObject(relation.config == null ? \'{}\' : relation.config)\n    var environment = text(payload.environment == null ? previous.environment : payload.environment)\n    if (environment == \'\') { environment = \'DEV\' }\n    if (![\'DEV\',\'TEST\',\'PROD\'].contains(environment)) { exit 400, \'请选择有效环境\' }\n    var catalog = text(payload.catalog == null ? previous.catalog : payload.catalog)\n    var schema = text(payload.schema == null ? previous.schema : payload.schema)\n    var prefix = text(payload.prefix == null ? previous.prefix : payload.prefix)\n    for (part in [catalog, schema]) { if (part != \'\' && !part.matches(\'[A-Za-z0-9_-]{1,128}\')) { exit 400, \'命名空间格式无效\' } }\n    if (prefix != \'\' && !prefix.matches(\'[A-Za-z_][A-Za-z0-9_]{0,31}\')) { exit 400, \'表名前缀格式无效\' }\n    var category = targetType == \'layer\' || target.mode == \'REFERENCE\' ? \'REFERENCE\' :\n        text(payload.category == null ? previous.category : payload.category)\n    if (category == \'\') { category = \'REFERENCE\' }\n    if (![\'RELATIONAL\',\'REFERENCE\'].contains(category)) { exit 400, \'请选择关系型数仓或外部引用\' }\n    var config = {environment: environment, catalog: catalog, schema: schema, prefix: prefix, category: category}\n    var configJson = jsons.toJSONStr(config)\n    var node = db.selectOne("""\n        SELECT d.tid FROM sym_dict_t d JOIN sym_dict_t p ON p.tid = d.parent_id AND p.tenant_id = d.tenant_id\n         WHERE d.tenant_id = #{tenantId} AND d.is_del = 0 AND p.is_del = 0\n           AND p.dict_code = \'nodeType\' AND d.dict_name = \'数据中心\' LIMIT 1\n    """)\n    if (node == null) { exit 409, \'缺少数据中心节点字典配置\' }\n    return db.transaction(() => {\n        if (relation == null) {\n            id = IdUtil.getSnowflakeNextIdStr()\n            db.table(\'dwm_center_layer_source_t\').primary(\'tid\').insert({tid: id, tenant_id: tenantId,\n                target_id: targetId, target_type: targetType, layer_code: target.code, datasource_id: sourceId,\n                configuration_json: configJson, revision_no: 1, created_time: now, updated_time: now, is_del: 0})\n        } else {\n            id = text(relation.tid)\n            var changed = db.table(\'dwm_center_layer_source_t\').where().eq(\'tid\', id).eq(\'tenant_id\', tenantId)\n                .eq(\'revision_no\', relation.version).eq(\'is_del\', 0).update({datasource_id: sourceId,\n                    layer_code: target.code, configuration_json: configJson,\n                    revision_no: relation.version + 1, updated_time: now})\n            if (changed != 1) { exit 409, \'绑定已被其他操作修改\' }\n        }\n        db.table(\'db_datasource_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', sourceId).eq(\'is_del\', 0)\n            .update({node_id: node.tid, updated_time: now})\n        return {id: id, saved: true}\n    })\n}\nif (![\'layers\',\'databases\',\'classifications\'].contains(kind)) { exit 400, \'不支持的规划对象\' }\nvar list = kind == \'layers\' ? current.layers : kind == \'databases\' ? current.databases : current.classifications\nvar old = id == \'\' ? null : find(list, id)\nif (old != null) { checkVersion(old) }\nif (action == \'move\' && kind == \'layers\') {\n    var nextOrder = old.order + (payload.direction == \'up\' ? -1 : 1)\n    if (nextOrder < 0 || nextOrder >= list.size()) { exit 409, \'已经位于边界\' }\n    return db.transaction(() => {\n        var neighbor = list[nextOrder]\n        var moved = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', id).eq(\'revision_no\', old.version)\n            .eq(\'is_del\', 0).update({sort_no: neighbor.sortNo, revision_no: old.version + 1, updated_time: now})\n        var swapped = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', neighbor.id).eq(\'revision_no\', neighbor.version)\n            .eq(\'is_del\', 0).update({sort_no: old.sortNo, revision_no: neighbor.version + 1, updated_time: now})\n        if (moved != 1 || swapped != 1) { exit 409, \'分层顺序已更新，请刷新后重试\' }\n        return {id: id, moved: true}\n    })\n}\nif (method == \'DELETE\' || action == \'archive\') {\n    if (old == null) { exit 404, \'记录不存在\' }\n    if (kind == \'layers\' && old.builtIn) { exit 409, \'默认分层不可删除\' }\n    var child = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'parent_id\', id).eq(\'is_del\', 0).count()\n    var binding = db.table(\'dwm_center_layer_source_t\').where().eq(\'tenant_id\', tenantId).eq(\'target_id\', id).eq(\'is_del\', 0).count()\n    if (child > 0 || binding > 0) { exit 409, \'该规划仍有子节点或存储绑定，请先处理引用\' }\n    if (kind == \'databases\') {\n        var used = db.selectOne("""SELECT COUNT(*) AS total FROM res_logical_model\n            WHERE tenant_id = #{tenantId} AND is_del = 0 AND database_id = #{id}""")\n        if (used.total > 0) { exit 409, \'该分库仍被逻辑模型引用\' }\n    }\n    if (kind == \'classifications\') {\n        var used = db.selectOne("""SELECT COUNT(*) AS total FROM da_prop_t\n            WHERE tenant_id = #{tenantId} AND is_del = 0 AND prop_name = \'resourceCenterDraft\'\n              AND JSON_VALID(prop_value) AND JSON_UNQUOTE(JSON_EXTRACT(prop_value, \'$.classificationId\')) = #{id}""")\n        if (used.total > 0) { exit 409, \'该分类已被资源目录引用\' }\n    }\n    db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', id).eq(\'revision_no\', old.version)\n        .update({is_del: 1, revision_no: old.version + 1, updated_time: now, updated_by: actorId})\n    return {id: id, removed: true}\n}\nif (action != \'\' || ![\'POST\',\'PUT\'].contains(method)) { exit 400, \'不支持的规划动作\' }\nvar rootCode = kind == \'classifications\' ? \'resourceCatalogClass\' : \'dataSourceType\'\nif (kind == \'databases\') { find(current.layers, text(payload.layerId)) }\nvar parentId = kind == \'databases\' ? text(payload.layerId) : \'\'\nvar parent = kind == \'databases\' ? db.selectOne("""\n    SELECT tid AS id, dict_code AS code, tree_path, level_no\n      FROM sym_dict_t WHERE tenant_id = #{tenantId} AND tid = #{parentId} AND is_del = 0 LIMIT 1\n""") : db.selectOne("""\n    SELECT tid AS id, dict_code AS code, tree_path, level_no\n      FROM sym_dict_t WHERE tenant_id = #{tenantId} AND dict_code = #{rootCode} AND is_del = 0 LIMIT 1\n""")\nif (parent == null) { exit 409, \'缺少规划根字典，请先初始化共享字典配置\' }\nvar name = required(payload.name, \'名称\', 100)\nvar code = identifier(payload.code)\nif (kind == \'layers\') { code = code.toUpperCase() }\nif (old != null && kind == \'layers\' && old.builtIn && code != old.code) { exit 409, \'默认层代码不可修改\' }\nparentId = text(parent.id)\nvar duplicate = db.selectOne("""SELECT tid FROM sym_dict_t WHERE tenant_id = #{tenantId}\n    AND parent_id = #{parentId} AND LOWER(dict_code) = LOWER(#{code}) AND is_del = 0 AND tid != #{id} LIMIT 1""")\nif (duplicate != null) { exit 409, \'同层级技术代码已存在\' }\nvar config = {owner: text(payload.owner), domain: text(payload.domain),\n    mode: kind == \'databases\' && (parent.code == \'DST\' || payload.mode == \'REFERENCE\') ? \'REFERENCE\' : \'MANAGED\', state: \'ACTIVE\'}\nvar values = {dict_name: name, dict_code: code, parent_id: parentId, dict_desc: text(payload.purpose),\n    planning_config_json: jsons.toJSONStr(config), updated_time: now, updated_by: actorId}\nif (old == null) {\n    id = IdUtil.getSnowflakeNextIdStr()\n    var siblings = db.selectOne("""SELECT COALESCE(MAX(sort_no), 0) AS max_sort FROM sym_dict_t\n        WHERE tenant_id = #{tenantId} AND parent_id = #{parentId} AND is_del = 0""")\n    values.putAll({tid: id, tenant_id: tenantId, sort_no: siblings.maxSort + 1,\n        level_no: parent.levelNo + 1, tree_path: text(parent.treePath) + \'.\' + id,\n        revision_no: 1, created_by: actorId, created_time: now, is_del: 0})\n    db.table(\'sym_dict_t\').primary(\'tid\').insert(values)\n} else {\n    values.revision_no = old.version + 1\n    values.tree_path = text(parent.treePath) + \'.\' + id\n    values.level_no = parent.levelNo + 1\n    if (kind == \'databases\' && old.layerId != parentId) {\n        var nextSibling = db.selectOne("""SELECT COALESCE(MAX(sort_no), 0) AS max_sort FROM sym_dict_t\n            WHERE tenant_id = #{tenantId} AND parent_id = #{parentId} AND is_del = 0""")\n        values.sort_no = nextSibling.maxSort + 1\n    }\n    var changed = db.table(\'sym_dict_t\').where().eq(\'tenant_id\', tenantId).eq(\'tid\', id)\n        .eq(\'revision_no\', old.version).eq(\'is_del\', 0).update(values)\n    if (changed != 1) { exit 409, \'规划已被修改，请刷新后重试\' }\n}\nreturn {id: id, saved: true}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/07.planning-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4e0ee97e906054229d56e22da830272e',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "4e0ee97e906054229d56e22da830272e",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "08.planning-read",\r\n  "createTime" : null,\r\n  "updateTime" : 1790989454788,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/planning-read",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 共享数仓规划投影：字典层/分域、节点数据源关联和已采集表均来自当前租户。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.crypto.digest.DigestUtil\n\nvar tenantId = tenantRuntime.id()\nvar text = value => value == null ? \'\' : value + \'\'\nvar json = value => text(value) == \'\' ? {} : jsons.toJSONObject(value)\nvar root = db.selectOne("""\n    SELECT tid, tree_path, level_no\n      FROM sym_dict_t\n     WHERE tenant_id = #{tenantId} AND dict_code = \'dataSourceType\' AND is_del = 0\n     LIMIT 1\n""")\nvar classRoot = db.selectOne("""\n    SELECT tid FROM sym_dict_t\n     WHERE tenant_id = #{tenantId} AND dict_code = \'resourceCatalogClass\' AND is_del = 0\n     LIMIT 1\n""")\nvar layerRows = root == null ? [] : db.select("""\n    SELECT tid, dict_name AS name, dict_code AS layer_code, parent_id,\n           tree_path, level_no, sort_no,\n           dict_desc AS purpose, planning_config_json AS config,\n           revision_no AS version, created_time, updated_time\n      FROM sym_dict_t\n     WHERE tenant_id = #{tenantId} AND parent_id = #{root.tid} AND is_del = 0\n     ORDER BY sort_no, dict_name, tid\n""")\nvar domainRows = root == null ? [] : db.select("""\n    SELECT d.tid, d.dict_name AS name, d.dict_code AS domain_code, d.parent_id,\n           d.tree_path, d.level_no, d.sort_no,\n           d.dict_desc AS purpose, d.planning_config_json AS config,\n           d.revision_no AS version, d.created_time, d.updated_time\n      FROM sym_dict_t d\n      JOIN sym_dict_t p ON p.tid = d.parent_id AND p.tenant_id = d.tenant_id AND p.is_del = 0\n     WHERE d.tenant_id = #{tenantId} AND d.is_del = 0 AND p.parent_id = #{root.tid}\n     ORDER BY p.sort_no, d.sort_no, d.dict_name, d.tid\n""")\nvar classRows = classRoot == null ? [] : db.select("""\n    SELECT tid, dict_name AS name, dict_code AS class_code,\n           revision_no AS version, created_time, updated_time\n      FROM sym_dict_t\n     WHERE tenant_id = #{tenantId} AND parent_id = #{classRoot.tid} AND is_del = 0\n     ORDER BY sort_no, dict_name, tid\n""")\nvar tableCounts = {}\nfor (row in db.select("""\n    SELECT datasource_id AS source_id, COUNT(*) AS table_count\n      FROM db_table_t WHERE tenant_id = #{tenantId} AND is_del = 0\n     GROUP BY datasource_id\n""")) { tableCounts[text(row.sourceId)] = row.tableCount }\nvar relationRows = db.select("""\n    SELECT b.tid, b.target_id, b.target_type,\n           b.datasource_id AS source_id, b.configuration_json AS config,\n           b.revision_no AS version, b.created_time, b.updated_time,\n           s.db_name AS source_name, s.db_type AS profile, s.updated_time AS source_updated_at\n      FROM dwm_center_layer_source_t b\n      LEFT JOIN db_datasource_t s ON s.tid = b.datasource_id AND s.tenant_id = b.tenant_id AND s.is_del = 0\n     WHERE b.tenant_id = #{tenantId} AND b.is_del = 0 AND b.target_type IN (\'layer\', \'domain\')\n     ORDER BY b.updated_time DESC, b.tid DESC\n""")\nvar relationByTarget = {}\nfor (row in relationRows) {\n    var key = text(row.targetType) + \':\' + text(row.targetId)\n    if (relationByTarget[key] == null) { relationByTarget[key] = row }\n}\nvar layers = []\nvar layerById = {}\nvar builtIns = [\'DST\', \'ODS\', \'DWD\', \'DWM\', \'DWS\', \'ODAS\']\nfor (row in layerRows) {\n    var config = json(row.config)\n    var source = relationByTarget[\'layer:\' + text(row.tid)]\n    var sourceId = source == null ? \'\' : text(source.sourceId)\n    var layer = {id:text(row.tid), name:row.name, code:text(row.layerCode).toUpperCase(),\n        purpose:text(row.purpose), owner:text(config.owner), order:layers.size(), sortNo:row.sortNo,\n        builtIn:builtIns.contains(text(row.layerCode).toUpperCase()),\n        state:config.state == \'ARCHIVED\' ? \'ARCHIVED\' : \'ACTIVE\',\n        sourceId:sourceId, sourceName:source == null ? \'\' : text(source.sourceName),\n        sourceDbType:source == null ? \'\' : text(source.profile),\n        bindingId:source == null ? \'\' : text(source.tid),\n        bindingVersion:source == null ? null : source.version,\n        tableCount:tableCounts[sourceId] == null ? 0 : tableCounts[sourceId],\n        version:row.version, createdAt:row.createdAt, updatedAt:row.updatedAt}\n    layers.add(layer)\n    layerById[layer.id] = layer\n}\nvar databases = []\nvar domainById = {}\nfor (row in domainRows) {\n    var parent = layerById[text(row.parentId)]\n    if (parent == null) { continue }\n    var config = json(row.config)\n    var source = relationByTarget[\'domain:\' + text(row.tid)]\n    var sourceId = source == null ? \'\' : text(source.sourceId)\n    var domain = {id:text(row.tid), name:row.name, code:text(row.domainCode), layerId:parent.id,\n        domain:config.domain == null ? text(row.name) : text(config.domain),\n        owner:text(config.owner), purpose:text(row.purpose),\n        mode:parent.code == \'DST\' || config.mode == \'REFERENCE\' ? \'REFERENCE\' : \'MANAGED\',\n        state:config.state == \'ARCHIVED\' ? \'ARCHIVED\' : \'ACTIVE\',\n        sourceId:sourceId, sourceName:source == null ? \'\' : text(source.sourceName),\n        sourceDbType:source == null ? \'\' : text(source.profile),\n        bindingId:source == null ? \'\' : text(source.tid),\n        bindingVersion:source == null ? null : source.version,\n        tableCount:tableCounts[sourceId] == null ? 0 : tableCounts[sourceId],\n        version:row.version, createdAt:row.createdAt, updatedAt:row.updatedAt}\n    databases.add(domain)\n    domainById[domain.id] = domain\n}\nvar bindings = []\nfor (row in relationRows) {\n    if (row.targetType != \'domain\' || domainById[text(row.targetId)] == null) { continue }\n    var config = json(row.config)\n    var environment = config.environment == null ? \'DEV\' : config.environment\n    var category = config.category == null ? \'REFERENCE\' : config.category\n    var hash = DigestUtil.sha256Hex(text(row.sourceId) + \'|\' + text(row.sourceUpdatedAt) + \'|\' + environment + \'|\' +\n        text(config.catalog) + \'|\' + text(config.schema) + \'|\' + text(config.prefix) + \'|\' + category)\n    bindings.add({id:text(row.tid), databaseId:text(row.targetId), sourceId:text(row.sourceId),\n        environment:environment, catalog:text(config.catalog), schema:text(config.schema), prefix:text(config.prefix),\n        category:category, profile:text(row.profile), sourceName:text(row.sourceName),\n        tableCount:tableCounts[text(row.sourceId)] == null ? 0 : tableCounts[text(row.sourceId)],\n        state:row.sourceName == null ? \'INVALID\' : config.checkedHash == hash ? \'VALID\' : \'NOT_CHECKED\',\n        checkedHash:config.checkedHash, checkedAt:config.checkedAt, currentHash:hash,\n        version:row.version, createdAt:row.createdAt, updatedAt:row.updatedAt})\n}\nvar classes = []\nfor (row in classRows) {\n    classes.add({id:text(row.tid), name:row.name, code:text(row.classCode), version:row.version,\n        createdAt:row.createdAt, updatedAt:row.updatedAt})\n}\nreturn {layers:layers, databases:databases, bindings:bindings, classifications:classes}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/08.planning-read.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('4049d07b6bcc53f2b88f544ff0f62d22',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "4049d07b6bcc53f2b88f544ff0f62d22",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "09.resource-command",\r\n  "createTime" : null,\r\n  "updateTime" : 1790982798850,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/resource-command",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 07.共享库表的资源归属登记。直接维护 db_table_t，不复制技术实体、不创建物理表。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.core.util.IdUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport \'@/resource-center/model-read\' as readModels\nimport \'@/resource-center/technical-read\' as technicalRead\nimport \'@/resource-center/planning-read\' as readPlanning\nimport \'@post:/dst/database/metadata/table/sample-data\' as sampleData\nvar tenantId = tenantRuntime.id()\nvar actorId = StpUtil.getLoginIdAsString()\nvar now = new Date()\nvar text = v => v == null ? \'\' : (v + \'\').trim()\nvar payload = input.body == null ? {} : input.body\nvar id = text(input.id); var action = text(input.action); var method = text(input.method)\nvar find = (rows,key) => { for (r in rows) { if (r.id == key) { return r } }; exit 404,\'对象不存在或不属于当前租户\' }\nif (id == \'\' && method == \'POST\') {\n    id = text(payload.entityId)\n    var table = db.selectOne(\'SELECT tid,table_name,table_name_cn,resource_domain_id,resource_state FROM db_table_t WHERE tenant_id=#{tenantId} AND tid=#{id} AND is_del=0\')\n    if (table == null) { exit 404,\'技术实体不存在\' }\n    if (text(table.resourceDomainId) != \'\' && table.resourceState == \'ACTIVE\') { exit 409,\'该技术实体已有有效资源登记\' }\n    var domain = find(readPlanning({}).databases,text(payload.databaseId))\n    if (domain.state != \'ACTIVE\') { exit 409,\'规划分库已归档\' }\n    var owner = text(payload.owner); if (owner == \'\' || owner.length() > 128) { exit 400,\'请填写责任方，最多128字\' }\n    var name = text(payload.name) == \'\' ? table.tableNameCn : text(payload.name)\n    if (name == null || text(name) == \'\') { name = table.tableName }\n    if (text(name).length() > 512 || text(payload.domain).length() > 64) { exit 400,\'名称或业务域超过长度限制\' }\n    var changed = db.update("UPDATE db_table_t SET resource_domain_id=#{domainId},resource_owner=#{owner},resource_state=\'ACTIVE\',resource_revision_no=resource_revision_no+1,table_name_cn=#{name},business_type=#{domain},asset_desc=#{description},asset_status=2,flow_status=2,reg_time=#{now},updated_time=#{now},updated_by=#{actorId} WHERE tid=#{id} AND tenant_id=#{tenantId} AND is_del=0 AND (resource_domain_id IS NULL OR resource_state=\'ARCHIVED\')",\n        {domainId:domain.id,owner:owner,name:name,domain:text(payload.domain),description:text(payload.description),now:now,actorId:actorId,id:id,tenantId:tenantId})\n    if (changed != 1) { exit 409,\'该技术实体已由另一请求登记\' }\n    db.table(\'res_resource_operation_log\').primary(\'tid\').insert({tid:IdUtil.fastSimpleUUID(),tenant_id:tenantId,actor_id:actorId,action_name:\'登记仓库资源\',object_id:id,object_name:name,detail_text:\'沿用共享技术实体，未复制数据表\',created_time:now})\n    return find(readModels({}).resources,id)\n}\nvar resource = find(readModels({}).resources,id)\nif (method == \'GET\') {\n    var technical = technicalRead({entityIds:[id]})\n    var record = resource; record.source = find(technical.sources,resource.structure.sourceId)\n    var allowed = []; var hidden = []; var masked = []\n    for (f in db.select(\'SELECT column_name,is_masking FROM db_table_column_t WHERE tenant_id=#{tenantId} AND table_id=#{id} AND is_del=0 ORDER BY ordinal_position\')) {\n        var n = text(f.columnName)\n        if (n.toLowerCase().matches(\'.*(password|secret|token|credential|private_key).*\')) { hidden.add(n) }\n        else { allowed.add(n); if (f.isMasking == 1 || n.toLowerCase().matches(\'.*(phone|mobile|email|identity|certificate_no).*\')) { masked.add(n) } }\n    }\n    record.records = []\n    if (allowed.size() > 0) {\n        var previousBody = body\n        try {\n            body = {tableId:id,sampleSize:10,columns:allowed}\n            var sample = sampleData()\n            var rows = sample.data == null ? (sample.rows == null ? [] : sample.rows) : sample.data\n            for (row in rows) { for (fieldName in masked) { if (row[fieldName] != null) { row[fieldName] = \'***\' } }; record.records.add(row) }\n        } catch (e) { record.previewError = \'读取数据预览失败：\' + e.getMessage() }\n        finally { body = previousBody }\n    }\n    return record\n}\nif (action != \'archive\') { exit 400,\'不支持的资源操作\' }\nif (text(input.version) != text(resource.version)) { exit 409,\'资源已更新，请刷新重试\' }\nvar linked = db.selectOne("SELECT p.tid FROM res_catalog_publish_request p JOIN da_catalog_t c ON p.catalog_id=c.tid AND c.tenant_id=p.tenant_id WHERE p.tenant_id=#{tenantId} AND p.is_del=0 AND c.is_del=0 AND c.source_table_id=#{id} AND p.request_status=\'PUBLISHED\' LIMIT 1")\nif (linked != null) { exit 409,\'仍有已发布目录引用该资源，请先下线目录\' }\nvar expected = resource.version\nvar changed = db.update("UPDATE db_table_t SET resource_state=\'ARCHIVED\',resource_revision_no=resource_revision_no+1,updated_time=#{now},updated_by=#{actorId} WHERE tid=#{id} AND tenant_id=#{tenantId} AND is_del=0 AND resource_revision_no=#{expected}",{now:now,actorId:actorId,id:id,tenantId:tenantId,expected:expected})\nif (changed != 1) { exit 409,\'资源已更新，请刷新重试\' }\nreturn {id:id,state:\'ARCHIVED\',version:expected + 1}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/09.resource-command.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('490931832d8a5b87a46bdb77544bb02c',NULL,'function','{\r\n  "properties" : { },\r\n  "id" : "490931832d8a5b87a46bdb77544bb02c",\r\n  "script" : null,\r\n  "groupId" : "8b36eff777cc5cc6a8cf7c3048cd8b82",\r\n  "name" : "10.technical-read",\r\n  "createTime" : null,\r\n  "updateTime" : 1790982798928,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "/technical-read",\r\n  "description" : null,\r\n  "returnType" : null,\r\n  "mappingPath" : null,\r\n  "parameters" : [ {\r\n    "name" : "input",\r\n    "value" : null,\r\n    "description" : null,\r\n    "required" : false,\r\n    "dataType" : "Object",\r\n    "type" : null,\r\n    "defaultValue" : null,\r\n    "validateType" : null,\r\n    "error" : null,\r\n    "expression" : null,\r\n    "children" : null\r\n  } ]\r\n}\r\n================================\r\n// 读取共享技术元数据投影。只读当前会话租户；数据源凭据、连接串和原始业务记录不进入响应。\n// input.entityIds 指定真实 db_table_t.tid 时加载完整字段；默认分页 200 张并补齐已登记的仓库资源。\nimport tenantRuntime\nimport jsons\nimport cn.hutool.json.JSONUtil\nimport cn.dev33.satoken.stp.StpUtil\nimport cn.hutool.core.util.NumberUtil\nimport cn.hutool.crypto.digest.DigestUtil\nimport \'@post:/sym/user/me\' as currentUser\n\nvar tenantId = tenantRuntime.id()\nvar text = value => value == null ? \'\' : value + \'\'\nvar number = value => text(value).matches(\'^[0-9]+$\') ? NumberUtil.parseInt(text(value)) : 0\nvar bool = value => [\'1\', \'true\', \'TRUE\', \'YES\', \'Y\', \'yes\', \'y\'].contains(text(value))\nvar nullable = value => value == null || text(value) == \'\' ? \'unknown\' : bool(value) ? \'true\' : [\'0\',\'false\',\'FALSE\',\'NO\',\'N\',\'no\',\'n\'].contains(text(value)) ? \'false\' : \'unknown\'\nvar family = value => {\n    var type = text(value).toLowerCase()\n    if (type.contains(\'timestamp\') || type.contains(\'datetime\')) { return \'timestamp\' }\n    if (type.startsWith(\'date\')) { return \'date\' }\n    if (type.contains(\'int\') || type == \'serial\' || type == \'bigserial\') { return \'integer\' }\n    if (type.contains(\'decimal\') || type.contains(\'numeric\') || type.contains(\'number\') || type.contains(\'money\')) { return \'decimal\' }\n    if (type.contains(\'float\') || type.contains(\'double\') || type == \'real\') { return \'float\' }\n    if (type.contains(\'bool\') || type == \'bit\') { return \'boolean\' }\n    if (type.contains(\'char\') || type.contains(\'text\') || type.contains(\'clob\') || type.contains(\'string\')) { return \'string\' }\n    if (type.contains(\'binary\') || type.contains(\'blob\') || type == \'bytea\') { return \'binary\' }\n    if (type.contains(\'uuid\')) { return \'uuid\' }\n    if (type.contains(\'json\')) { return \'object\' }\n    return \'unknown\'\n}\nvar sourceRows = db.select("""\n    SELECT tid, db_name, COALESCE(NULLIF(db_type,\'\'),database_type) AS engine,\n           connection_status, is_enable, org_id, app_id, revision, updated_time\n      FROM db_datasource_t\n     WHERE tenant_id = #{tenantId} AND is_del = 0\n     ORDER BY db_name, tid\n""")\nvar sources = []\nvar sourceById = {}\nvar sourceIds = []\nvar manifest = {}\nfor (row in sourceRows) {\n    var sourceId = text(row.tid)\n    var engine = text(row.engine).toUpperCase()\n    if (engine == \'DAMENG\') { engine = \'DM8\' }\n    if (engine == \'KINGBASE8\' || engine == \'KINGBASE\') { engine = \'KINGBASEES\' }\n    var source = {id:sourceId, name:text(row.dbName), engine:engine,\n        connectionStatus:text(row.connectionStatus), enabled:bool(row.isEnable),\n        status:bool(row.isEnable) ? \'READY\' : \'DISABLED\', orgId:text(row.orgId), applicationId:text(row.appId),\n        version:row.revision == null ? 1 : row.revision, updatedAt:row.updatedTime}\n    sources.add(source)\n    sourceById[sourceId] = source\n    sourceIds.add(sourceId)\n    manifest[sourceId] = \'metadata:\' + sourceId + \':\' + DigestUtil.sha256Hex(text(row.updatedTime))\n}\nvar entityIds = input == null || input.entityIds == null ? [] : input.entityIds\nif (entityIds.size() > 1000) { exit 400, \'一次最多加载 1000 张指定数据表\' }\nvar keyword = input == null ? \'\' : text(input.entityKeyword).trim()\nif (keyword.length() > 200) { exit 400, \'检索关键词过长\' }\nvar search = \'%\' + keyword + \'%\'\nvar pageNo = input == null ? 1 : number(input.pageNo)\nif (pageNo < 1) { pageNo = 1 }\nvar pageSize = input == null ? 200 : number(input.pageSize)\nif (pageSize < 1) { pageSize = 200 }\nif (pageSize > 500) { pageSize = 500 }\nvar offset = (pageNo - 1) * pageSize\nvar tableRows = []\nvar total = 0\nif (entityIds.size() > 0) {\n    tableRows = db.table(\'db_table_t\').where().eq(\'tenant_id\',tenantId).eq(\'is_del\',0).in(\'tid\',entityIds).select()\n    total = tableRows.size()\n} else {\n    var countRow = db.selectOne("""\n        SELECT COUNT(*) AS total\n          FROM db_table_t t\n          JOIN db_datasource_t d ON d.tid=t.datasource_id AND d.tenant_id=#{tenantId} AND d.is_del=0\n         WHERE t.tenant_id=#{tenantId} AND t.is_del=0\n           AND (#{keyword}=\'\' OR t.table_name LIKE #{search} OR t.table_name_cn LIKE #{search} OR t.table_comment LIKE #{search})\n    """)\n    total = countRow.total\n    tableRows = db.select("""\n        SELECT t.* FROM db_table_t t\n          JOIN db_datasource_t d ON d.tid=t.datasource_id AND d.tenant_id=#{tenantId} AND d.is_del=0\n         WHERE t.tenant_id=#{tenantId} AND t.is_del=0\n           AND (#{keyword}=\'\' OR t.table_name LIKE #{search} OR t.table_name_cn LIKE #{search} OR t.table_comment LIKE #{search})\n         ORDER BY t.table_name, t.tid LIMIT #{offset}, #{pageSize}\n    """)\n    var registered = db.select("""\n        SELECT t.* FROM db_table_t t\n          JOIN db_datasource_t d ON d.tid=t.datasource_id AND d.tenant_id=#{tenantId} AND d.is_del=0\n         WHERE t.tenant_id=#{tenantId} AND t.is_del=0\n           AND t.resource_domain_id IS NOT NULL AND t.resource_domain_id<>\'\'\n         ORDER BY t.table_name, t.tid\n    """)\n    var loaded = []\n    for (table in tableRows) { loaded.add(text(table.tid)) }\n    for (table in registered) { if (!loaded.contains(text(table.tid))) { tableRows.add(table); loaded.add(text(table.tid)) } }\n}\nvar tables = []\nvar tableIds = []\nfor (row in tableRows) {\n    if (sourceById[text(row.datasourceId)] != null) { tables.add(row); tableIds.add(text(row.tid)) }\n}\nif (entityIds.size() > 0 && tableIds.size() != entityIds.size()) { exit 404, \'部分技术表已删除或不属于当前租户\' }\nvar columnRows = tableIds.size() == 0 ? [] : db.table(\'db_table_column_t\').where().eq(\'tenant_id\',tenantId).eq(\'is_del\',0).in(\'table_id\',tableIds).orderBy(\'table_id\',\'asc\').orderBy(\'ordinal_position\',\'asc\').orderBy(\'tid\',\'asc\').select()\nvar fieldsByTable = {}\nvar primaryByTable = {}\nvar uniqueByTable = {}\nvar mappings = []\nvar standardRows = db.select("""\n    SELECT tid, meta_name, meta_code, standard_encode, biz_def, data_type_id,\n           field_type, field_length, numeric_precision, numeric_scale, data_category_name,\n           publish_status, version_no, updated_time, created_time, is_nullable\n      FROM da_metadata_t WHERE tenant_id=#{tenantId} AND is_del=0\n     ORDER BY meta_name, tid\n""")\nvar standards = []\nvar standardById = {}\nvar standardByCode = {}\nfor (row in standardRows) {\n    var standardId = text(row.tid)\n    var revision = text(row.versionNo) != \'\' ? \'v\' + text(row.versionNo) : DigestUtil.sha256Hex(text(row.updatedTime))\n    var nativeType = text(row.fieldType) == \'\' ? text(row.dataTypeId) : text(row.fieldType)\n    var published = text(row.publishStatus) == \'1\'\n    var standard = {id:standardId, name:text(row.metaName), code:text(row.metaCode), standardEncode:text(row.standardEncode),\n        definition:text(row.bizDef), type:family(nativeType), fieldType:nativeType, nativeType:nativeType,\n        length:row.fieldLength, precision:number(row.numericPrecision)>0 ? number(row.numericPrecision) : null,\n        scale:number(row.numericPrecision)>0 ? number(row.numericScale) : null, nullable:nullable(row.isNullable),\n        domain:text(row.dataCategoryName), status:published ? \'PUBLISHED\' : \'DRAFT\',\n        publishedRevisionId:published ? standardId + \':\' + revision : null,\n        revisionId:standardId + \':\' + revision, version:row.versionNo == null ? 1 : row.versionNo,\n        createdAt:row.createdTime, updatedAt:row.updatedTime}\n    standards.add(standard)\n    standardById[standardId] = standard\n    if (text(row.metaCode) != \'\') { standardByCode[text(row.metaCode).toUpperCase()] = standard }\n    if (text(row.standardEncode) != \'\') { standardByCode[text(row.standardEncode).toUpperCase()] = standard }\n}\nfor (row in columnRows) {\n    var tableId = text(row.tableId)\n    if (fieldsByTable[tableId] == null) { fieldsByTable[tableId] = []; primaryByTable[tableId] = []; uniqueByTable[tableId] = [] }\n    var fieldId = text(row.tid)\n    var nativeType = text(row.columnType) == \'\' ? text(row.dataType) : text(row.columnType)\n    var field = {id:fieldId, name:text(row.columnName), path:text(row.columnName), comment:text(row.columnComment),\n        nativeType:nativeType, typeFamily:family(nativeType), length:row.length,\n        precision:number(row.precisionLength)>0 ? number(row.precisionLength) : null,\n        scale:number(row.precisionLength)>0 ? number(row.scale) : null,\n        nullable:nullable(row.nullable), ordinal:row.ordinalPosition == null ? 0 : row.ordinalPosition}\n    fieldsByTable[tableId].add(field)\n    if (bool(row.primaryKey)) { primaryByTable[tableId].add(fieldId) }\n    if (bool(row.isUnique)) { uniqueByTable[tableId].add({id:\'unique:\'+fieldId, kind:\'unique\', fieldIds:[fieldId], enforced:\'unknown\'}) }\n    var reference = text(row.dataStandardId)\n    if (reference != \'\') {\n        var standard = standardById[reference]\n        if (standard == null) { standard = standardByCode[reference.toUpperCase()] }\n        mappings.add({id:\'mapping:\'+fieldId, fieldId:fieldId, field_id:fieldId, entityId:tableId, entity_id:tableId,\n            mapping_mode:\'STANDARD\', targetId:standard == null ? reference : standard.id,\n            target_id:standard == null ? reference : standard.id,\n            targetRevisionId:standard == null ? null : standard.publishedRevisionId,\n            state:standard == null ? \'MISSING\' : standard.status == \'PUBLISHED\' ? \'BOUND\' : \'UNPUBLISHED\'})\n    }\n}\nvar entities = []\nvar resources = []\nfor (row in tables) {\n    var tableId = text(row.tid)\n    var sourceId = text(row.datasourceId)\n    var fields = fieldsByTable[tableId] == null ? [] : fieldsByTable[tableId]\n    var keys = uniqueByTable[tableId] == null ? [] : uniqueByTable[tableId]\n    if (primaryByTable[tableId] != null && primaryByTable[tableId].size()>0) { keys.add({id:\'primary:\'+tableId,kind:\'primary\',fieldIds:primaryByTable[tableId],enforced:\'unknown\'}) }\n    var displayName = text(row.tableNameCn) != \'\' ? text(row.tableNameCn) : text(row.tableComment) != \'\' ? text(row.tableComment) : text(row.tableName)\n    var entity = {id:tableId, sourceId:sourceId, name:text(row.tableName), displayName:displayName,\n        comment:text(row.tableComment), kind:text(row.tableType).toLowerCase().contains(\'view\') ? \'view\' : \'table\',\n        shapeBasis:fields.size()>0 && number(row.fieldCount)==fields.size() ? \'declared_complete\' : \'unknown\',\n        constraintsAvailability:\'unknown\', fields:fields, keys:keys}\n    entities.add(entity)\n    var revisionId = \'table:\'+tableId+\':\'+text(row.revision)+\':\'+DigestUtil.sha256Hex(text(row.updatedTime))\n    if (text(row.resourceDomainId) != \'\') {\n        resources.add({id:tableId, entityId:tableId, structure:entity, structureRevisionId:revisionId,\n            name:displayName, databaseId:text(row.resourceDomainId), domain:\'\', owner:text(row.resourceOwner),\n            description:text(row.assetDesc), origin:text(row.resourcePlanId)==\'\' ? \'SNAPSHOT\' : \'MATERIALIZATION\',\n            state:row.resourceState==\'ARCHIVED\' ? \'ARCHIVED\' : \'ACTIVE\', modelId:row.resourceModelId,\n            deploymentId:row.resourcePlanId, designFieldMap:text(row.resourceFieldMap)==\'\' ? {} : JSONUtil.parse(row.resourceFieldMap),\n            version:row.resourceRevisionNo == null ? 1 : row.resourceRevisionNo, createdAt:row.createdTime, updatedAt:row.updatedTime})\n    }\n}\n// Quality results contain execution metadata only. Row snapshots and sensitive issue values remain behind the quality detail APIs.\nvar results = []\nvar issues = []\nvar qualityError = null\ntry {\nresults = db.select("""\n    SELECT r.tid AS id, t.table_id AS entity_id, t.table_id AS entityId, r.status,\n           r.checked_count AS checkedCount, r.violation_count AS violationCount,\n           CASE WHEN r.checked_count>0 THEN r.quality_score ELSE NULL END AS score,\n           r.started_at AS startedAt, r.finished_at AS finishedAt\n      FROM dq_quality_run_t r\n      JOIN dq_quality_task_t t ON t.tid=r.task_id AND t.tenant_id=#{tenantId} AND t.is_del=0\n     WHERE r.tenant_id=#{tenantId} AND r.is_del=0 ORDER BY r.created_time DESC LIMIT 200\n""")\nissues = db.select("""\n    SELECT i.tid AS id, t.table_id AS entity_id, i.run_id AS runId, i.column_name AS columnName,\n           i.severity, i.issue_status AS status, i.created_time AS createdAt\n      FROM dq_quality_issue_sample_t i\n      JOIN dq_quality_run_t r ON r.tid=i.run_id AND r.tenant_id=#{tenantId} AND r.is_del=0\n      JOIN dq_quality_task_t t ON t.tid=r.task_id AND t.tenant_id=#{tenantId} AND t.is_del=0\n     WHERE i.tenant_id=#{tenantId} ORDER BY i.created_time DESC LIMIT 200\n""")\n} catch (e) { qualityError = \'质量观测读取失败：\' + text(e.getMessage()) }\nvar user = currentUser()\nvar actorId = StpUtil.getLoginIdAsString()\nvar actorName = user.realName == null ? text(user.userName) : text(user.realName)\nvar members = [{principalId:actorId, name:actorName, orgId:text(user.orgId)}]\nreturn {sources:sources, entities:entities, resources:resources, standards:standards, mappings:mappings,\n    manifest:manifest, members:members, issues:issues, results:results, qualityError:qualityError,\n    entityPagination:{total:total,pageNo:pageNo,pageSize:pageSize,loaded:entities.size()},\n    actor:{principalId:actorId,name:actorName,orgId:text(user.orgId)}}\n',NULL,NULL,0,NULL,'/magic-api/function/14.磐石资源中心/10.technical-read.ms');
