INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('5e47680fc09447d6a200f542436cf7ac',NULL,NULL,'{\r\n  "properties" : { },\r\n  "id" : "5e47680fc09447d6a200f542436cf7ac",\r\n  "script" : "import scheduledTask\\r\\n\\r\\n//定时刷新表元数据、以及表字段\\r\\n//action：tableMetaRefreshTask 定时刷新表元数据、以及表字段固定传值\\r\\n//param：指定刷新的表id，不传则默认刷新全部挂接资源目录的表的元数据信息\\r\\nscheduledTask.scheduledRun(\\"tableMetaRefreshTask\\",\\"1881263750861074432\\");",\r\n  "groupId" : "87fdde50f33c4c139c40f0820af3083a",\r\n  "name" : "定时刷新表字段以及表元数据",\r\n  "createTime" : 1782660730535,\r\n  "updateTime" : 1737450778720,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "table-meta",\r\n  "cron" : "0 0 0 * * ?",\r\n  "enabled" : false,\r\n  "description" : null\r\n}',NULL,NULL,0,'2084109831678504960','/magic-api/task/03.表资产/01.定时刷新表字段以及表元数据.ms');
