INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a04f8a372f525a8594a1972cf697cd8f','a04f8a372f525a8594a1972cf697cd8f','task','{\r\n  "properties" : { },\r\n  "id" : "a04f8a372f525a8594a1972cf697cd8f",\r\n  "script" : null,\r\n  "groupId" : "30fc31e9c7e057f4983f7342850f1811",\r\n  "name" : "01.数据对账计划",\r\n  "createTime" : 1790900480658,\r\n  "updateTime" : 1790901094066,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "reconciliation-schedule",\r\n  "cron" : "*/30 * * * * ?",\r\n  "enabled" : true,\r\n  "description" : "扫描已启用且到期的对账策略并生成执行记录。单个策略的周期仍由策略自身的 Cron 表达式决定。"\r\n}\r\n================================\r\nimport systemJobs;\n\nsystemJobs.run("reconciliation-schedule");\n',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/01.数据对账计划.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ed0593273fc75b2c8f90e207b77bcab8','ed0593273fc75b2c8f90e207b77bcab8','task','{"properties": {}, "id": "ed0593273fc75b2c8f90e207b77bcab8", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"reconciliation-worker\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "02.数据对账执行", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "reconciliation-worker", "cron": "*/2 * * * * ?", "enabled": true, "description": "领取待处理的对账运行及分桶。所有任务共享一个执行器，不会为每条任务或每张表创建定时任务。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/02.数据对账执行.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('f5b058d07924559e94f899a97b48bc9e','f5b058d07924559e94f899a97b48bc9e','task','{"properties": {}, "id": "f5b058d07924559e94f899a97b48bc9e", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"data-quality-schedule\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "03.数据质量计划", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "data-quality-schedule", "cron": "*/30 * * * * ?", "enabled": true, "description": "扫描已启用且到期的质检任务并生成执行记录。单个质检任务的周期由其自身的 Cron 表达式决定。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/03.数据质量计划.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('96a88bf486045afb87fb439d24e25a0b','96a88bf486045afb87fb439d24e25a0b','task','{"properties": {}, "id": "96a88bf486045afb87fb439d24e25a0b", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"data-quality-worker\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "04.数据质量执行", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "data-quality-worker", "cron": "*/3 * * * * ?", "enabled": true, "description": "领取待处理的质检运行及分片。所有质检任务共享一个执行器。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/04.数据质量执行.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('615892f38d3e55e0ab568c7cff790dc0','615892f38d3e55e0ab568c7cff790dc0','task','{"properties": {}, "id": "615892f38d3e55e0ab568c7cff790dc0", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"leafy-bulletins\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "05.Leafy公告采集", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "leafy-bulletins", "cron": "*/3 * * * * ?", "enabled": true, "description": "把 ERROR/WARNING 公告留存为流程错误并更新异常状态；实时公告也可通过按需接口读取。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/05.Leafy公告采集.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('c57e2354a9455b698b337c8528df048d','c57e2354a9455b698b337c8528df048d','task','{"properties": {}, "id": "c57e2354a9455b698b337c8528df048d", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"leafy-latency\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "06.Leafy延迟快照", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "leafy-latency", "cron": "*/30 * * * * ?", "enabled": true, "description": "为历史趋势写入监控快照；只看当前运行状态可使用按需实时接口。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/06.Leafy延迟快照.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('ff8242923e2a5b078d51112bca453a94','ff8242923e2a5b078d51112bca453a94','task','{"properties": {}, "id": "ff8242923e2a5b078d51112bca453a94", "script": "import systemJobs;\\n\\nsystemJobs.run(\\"leafy-provenance\\");\\n", "groupId": "30fc31e9c7e057f4983f7342850f1811", "name": "07.Leafy执行历史", "createTime": 1790900480658, "updateTime": 1790900480658, "lock": null, "createBy": null, "updateBy": null, "path": "leafy-provenance", "cron": "0 * * * * ?", "enabled": true, "description": "从 Provenance 回写最近运行时间、执行结果与历史快照；执行事件也可按需实时查询。"}',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/07.Leafy执行历史.ms');
INSERT INTO `api_file_t` (`tid`,`api_id`,`file_kind`,`file_content`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`file_path`) VALUES ('a0934f8c5154518b8ce4c698ff7ee319','a0934f8c5154518b8ce4c698ff7ee319','task','{\r\n  "properties" : { },\r\n  "id" : "a0934f8c5154518b8ce4c698ff7ee319",\r\n  "script" : null,\r\n  "groupId" : "30fc31e9c7e057f4983f7342850f1811",\r\n  "name" : "08.查看执行状态",\r\n  "createTime" : 1790900656413,\r\n  "updateTime" : 1790900990908,\r\n  "lock" : null,\r\n  "createBy" : null,\r\n  "updateBy" : null,\r\n  "path" : "system-job-status",\r\n  "cron" : "0 0 0 * * ?",\r\n  "enabled" : false,\r\n  "description" : "在 Magic API 编辑器中手动执行，查看七个系统任务的最近执行时间、结果与累计次数。此项不会自动运行。"\r\n}\r\n================================\r\nimport systemJobs;\n\nreturn systemJobs.status();\n',NULL,NULL,0,NULL,'/magic-api/task/05.系统定时任务/08.查看执行状态.ms');
