\n  overflow: hidden;\n  margin-top: 4px;\n}\n.source-table[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] .pagination > span:first-child,\n.source-table[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] .pagination .el-pagination {\n  flex: 0 0 auto;\n  white-space: nowrap;\n}\n.task-name-cell[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.table-name-cell[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  max-width: 100%;\n  color: #17233d;\n  cursor: pointer;\n}\n.table-name-cell > div[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  flex: 1;\n  min-width: 0;\n}\n.table-name-cell strong[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed],\n.table-name-cell small[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  display: block;\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.table-name-cell strong[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  color: #17233d;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 20px;\n}\n.table-name-cell small[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  margin-top: 2px;\n  color: #8a98ad;\n  font-size: 12px;\n  line-height: 18px;\n}\n.table-name-cell:hover strong[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  color: var(--el-color-primary);\n}\n.table-name-cell:hover .table-name-cn[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n  color: #0b5fd6;\n}\n@container (max-width: 680px) {\n.source-table[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] .pagination > span:first-child,\n  .source-table[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] .pagination .el-pagination__jump {\n    display: none;\n}\n}\n@container (max-width: 480px) {\n.source-table[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] .pagination .el-pagination__sizes {\n    display: none;\n}\n}\n@media (max-width: 760px) {\n.list-toolbar[data-v-8bec26b77c7af8043ba59e5a0ecaa9ed] {\n    align-items: stretch;\n}\n.list-filters[data-v-8bec26b77c7a