          ]),\n              _: 1 /* STABLE */\n            }),\n            _createVNode(_component_el_table_column, {\n              label: "会话状态",\n              width: "105"\n            }, {\n              default: _withCtx(({ row }) => [\n                _createVNode(_component_el_tag, {\n                  type: row.current ? \'success\' : \'info\'\n                }, {\n                  default: _withCtx(() => [\n                    _createTextVNode(_toDisplayString(row.current ? \'当前会话\' : \'在线\'), 1 /* TEXT */)\n                  ]),\n                  _: 2 /* DYNAMIC */\n                }, 1032 /* PROPS, DYNAMIC_SLOTS */, ["type"])\n              ]),\n              _: 1 /* STABLE */\n            }),\n            _createVNode(_component_el_table_column, {\n              label: "操作",\n              width: "120",\n              fixed: "right"\n            }, {\n              default: _withCtx(({ row }) => [\n                _createVNode(_component_el_button, {\n                  link: "",\n                  type: "danger",\n                  disabled: row.current,\n                  onClick: $event => (kickout(row))\n                }, {\n                  default: _withCtx(() => [\n                    _createTextVNode(_toDisplayString(row.current ? \'不可下线\' : \'强制下线\'), 1 /* TEXT */)\n                  ]),\n                  _: 2 /* DYNAMIC */\n                }, 1032 /* PROPS, DYNAMIC_SLOTS */, ["disabled", "onClick"])\n              ]),\n              _: 1 /* STABLE */\n            })\n          ]),\n          _: 1 /* STABLE */\n        }, 8 /* PROPS */, ["data"])), [\n          [_directive_loading, loading.value]\n        ]),\n        _createElementVNode("div", _hoisted_4, [\n          _createElementVNode("span", null, "共 " + _toDisplayString(total.value) + " 个在线会话", 1 /* TEXT */),\n          _createVNode(_component_el_pagination, {\n            "current-page": pageNum.value,\n            "onUpdate:currentPage": _cache[1] || (_cache[1] = $event => ((page