INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2046880498703695872','2008730136700588032','access-apply_1','<template>\r\n  <el-drawer\r\n    v-model="open"\r\n    :title="drawerTitle"\r\n    size="950"\r\n    :body-class="\'access-apply\'"\r\n    :close-on-click-modal="false"\r\n    @close="handleCancel"\r\n  >\r\n    <div class="access-apply-content">\r\n      <u-title name="建表信息">\r\n        <template #right>\r\n          <el-button\r\n            type="primary"\r\n            :icon="\'el-icon-CopyDocument\'"\r\n            link\r\n            plain\r\n            @click="handleShowDDL"\r\n          >\r\n            查看DDL创建语句\r\n          </el-button>\r\n        </template>\r\n      </u-title>\r\n      <JsonForm\r\n        ref="jsonFormRef"\r\n        v-model="formData"\r\n        :rules="formRules"\r\n        bordered\r\n        class="mb-4"\r\n      ></JsonForm>\r\n      <v-table\r\n        ref="tableRef"\r\n        :options="tableColumns"\r\n        :editable="editable"\r\n        :show-operation="editable"\r\n        class="api-param-table"\r\n        @btn-click="handleTableBtnClick"\r\n      >\r\n        <template #primaryKey="{ row }">\r\n          <el-checkbox\r\n            :model-value="row.primaryKey === 1"\r\n            :disabled="!editable"\r\n            @update:model-value="(val) => (row.primaryKey = val ? 1 : 0)"\r\n          />\r\n        </template>\r\n        <template #nullable="{ row }">\r\n          <el-checkbox\r\n            :model-value="row.nullable === 1"\r\n            :disabled="!editable"\r\n            @update:model-value="(val) => (row.nullable = val ? 1 : 0)"\r\n          />\r\n        </template>\r\n      </v-table>\r\n    </div>\r\n\r\n    <template #footer>\r\n      <div class="flex" style="justify-content: flex-end">\r\n        <el-button v-if="editable" type="primary" :disabled="isSaveing" @click="handleSave">\r\n          <Icon icon="save" class="mr-1" />\r\n          提交\r\n        </el-button>\r\n\r\n        <el-button :icon="\'el-icon-Close\'" @click="handleCancel">关闭</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n\r\n  <!-- DDL创建语句弹窗 -->\r\n  <el-drawer\n    v-model="ddlDialogVisible"\n    v-if="ddlDialogVisible"\n    title="查看创建语句"\n    size="700"\n    class="ddl-preview-drawer"\n    :close-on-click-modal="false"\n  >\n    <div class="ddl-preview-content">\n      <div class="ddl-preview-editor">\n        <CodeEditor\n          v-model="ddlSql"\n          lang="sql"\n          theme="chrome"\n          :height="\'100%\'"\n          :show-option="false"\n          :read-only="true"\n        />\n      </div>\n    </div>\n    <template #footer>\r\n      <div class="flex" style="justify-content: flex-end">\r\n        <el-button :icon="\'el-icon-CopyDocument\'" type="primary" @click="handleCopyDDL">\r\n          一键复制\r\n        </el-button>\r\n        <el-button :icon="\'el-icon-Close\'" @click="ddlDialogVisible = false">关闭</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n\r\n  <!-- 默认字段弹窗 -->\r\n  <el-drawer\r\n    v-model="defaultFieldsVisible"\r\n    title="默认字段添加"\r\n    size="700"\r\n    :close-on-click-modal="false"\r\n  >\r\n    <DataTable\r\n      ref="defaultFieldsTableRef"\r\n      :columns="defaultFieldsColumns"\r\n      :data="defaultFieldsData"\r\n      :show-selection="true"\r\n      :show-page="false"\r\n      :flex-type="\'flex-[0_1_auto]\'"\r\n      :rowKey="\'columnName\'"\r\n      @selection-change="handleSelectionChange"\r\n    />\r\n    <template #footer>\r\n      <div class="flex justify-end">\r\n        <el-button type="primary" @click="handleConfirmDefaultFields">确定</el-button>\r\n        <el-button @click="defaultFieldsVisible = false">取消</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted, computed } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { ElMessage } from "element-plus";\r\nimport { useDictStore } from "@/store";\r\n\r\n// Props\r\nconst props = defineProps<{\r\n  modelValue: boolean;\r\n  type: string; // add/view\r\n  id: string;\r\n}>();\r\n\r\nconst emit = defineEmits<{\r\n  (e: "close"): void;\r\n  (e: "save"): void;\r\n  (e: "update:modelValue", value: boolean): void;\r\n}>();\r\n\r\nconst colTypeOptions = useDictStore().getDictItems("tableColType");\r\nconst formData = ref<any>({});\r\nconst jsonFormRef = ref<any>(null);\r\nconst drawerTitle = ref("接入申请");\r\nconst ddlDialogVisible = ref(false);\r\nconst defaultFieldsVisible = ref(false);\r\nconst ddlSql = ref("");\r\nconst isSaveing = ref(false);\r\n\r\n// 默认字段数据\r\nconst defaultFieldsData = ref([\r\n  {\r\n    columnComment: "创建时间",\r\n    columnName: "create_time",\r\n    length: 20,\r\n    dataType: "datetime",\r\n    columnType: "datetime",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "更新时间",\r\n    columnName: "update_time",\r\n    length: 20,\r\n    dataType: "datetime",\r\n    columnType: "datetime",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "创建人",\r\n    columnName: "created_by",\r\n    length: 64,\r\n    dataType: "varchar",\r\n    columnType: "varchar",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "更新人",\r\n    columnName: "updated_by",\r\n    length: 64,\r\n    dataType: "varchar",\r\n    columnType: "varchar",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "备注",\r\n    columnName: "remark",\r\n    length: 500,\r\n    dataType: "varchar",\r\n    columnType: "varchar",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "数据状态",\r\n    columnName: "data_status",\r\n    length: 32,\r\n    dataType: "int",\r\n    columnType: "int",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n  {\r\n    columnComment: "删除标志",\r\n    columnName: "is_del",\r\n    length: 1,\r\n    dataType: "int",\r\n    columnType: "int",\r\n    autoIncrement: 0,\r\n    charset: null,\r\n    collation: null,\r\n    defaultValue: null,\r\n    extra: "",\r\n    indexed: 1,\r\n    isUnique: 1,\r\n    nullable: 0,\r\n    ordinalPosition: 1,\r\n    precisionLength: 10,\r\n    primaryKey: 0,\r\n    scale: 0,\r\n  },\r\n]);\r\nconst editable = computed(() => props.type === "add");\r\nconst selectedDefaultFields = ref<any[]>([]);\r\nconst defaultFieldsTableRef = ref();\r\nconst formRules = FormUtils.fixJson([\r\n  {\r\n    field: "dbType",\r\n    title: "目标库类型",\r\n    type: "db-type-select",\r\n    $required: true,\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      disabled: !editable.value,\r\n    },\r\n  },\r\n  {\r\n    field: "dbId",\r\n    title: "目标数据库",\r\n    type: "select",\r\n    $required: true,\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      disabled: !editable.value,\r\n    },\r\n  },\r\n  {\r\n    field: "tableName",\r\n    title: "目标表名",\r\n    type: "input",\r\n    $required: true,\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      maxlength: 255,\r\n      disabled: !editable.value,\r\n    },\r\n  },\r\n  {\r\n    field: "tableNameCn",\r\n    title: "表注释",\r\n    type: "input",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      maxlength: 255,\r\n      disabled: !editable.value,\r\n    },\r\n  },\r\n]);\r\nconst tableRef = ref();\r\nconst tableColumns = ref({\r\n  columns: [\r\n    { type: "seq", width: 70 },\r\n    {\r\n      title: "字段名",\r\n      field: "columnName",\r\n      editRender: {\r\n        name: "VxeInput",\r\n        props: {\r\n          maxlength: 255,\r\n        },\r\n      },\r\n      showOverflow: true,\r\n    },\r\n    {\r\n      title: "业务备注",\r\n      field: "columnComment",\r\n      editRender: {\r\n        name: "VxeInput",\r\n        props: {\r\n          maxlength: 255,\r\n        },\r\n      },\r\n      showOverflow: true,\r\n    },\r\n    {\r\n      title: "数据类型",\r\n      field: "dataType",\r\n      editRender: { name: "ElSelect", options: colTypeOptions },\r\n    },\r\n    {\r\n      title: "主键",\r\n      field: "primaryKey",\r\n      width: 80,\r\n      slots: { default: "primaryKey" },\r\n    },\r\n    {\r\n      title: "不为空",\r\n      field: "nullable",\r\n      width: 80,\r\n      slots: { default: "nullable" },\r\n    },\r\n    {\r\n      title: "长度",\r\n      field: "length",\r\n      width: 100,\r\n      editRender: {\r\n        name: "VxeInput",\r\n        props: {\r\n          type: "number",\r\n          min: 0,\r\n        },\r\n      },\r\n    },\r\n  ],\r\n  editRules: {\r\n    columnName: [{ required: true, message: "字段名不能为空", trigger: "blur" }],\r\n    dataType: [{ required: true, message: "数据类型不能为空", trigger: "change" }],\r\n    length: [\r\n      { required: true, message: "长度不能为空", trigger: "blur" },\r\n      {\r\n        validator: ({ cellValue }: any) => {\r\n          if (cellValue === "" || cellValue === null || cellValue === undefined) {\r\n            return true;\r\n          }\r\n          const num = Number(cellValue);\r\n          return !isNaN(num) && num >= 0;\r\n        },\r\n        message: "长度必须为正数",\r\n        trigger: "blur",\r\n      },\r\n    ],\r\n  },\r\n  toolbarConfig: {\r\n    buttons: [\r\n      {\r\n        code: "append_edit", // 底部新增\r\n        icon: "vxe-icon-add",\r\n        name: "新增数据项",\r\n        status: "primary",\r\n        className: "btn-primary",\r\n      },\r\n      {\r\n        code: "default_field",\r\n        icon: "vxe-icon-setting",\r\n        name: "默认字段",\r\n        status: "primary",\r\n        className: "btn-plain",\r\n      },\r\n    ],\r\n    tools: [],\r\n  },\r\n});\r\n// 默认字段表格列配置\r\nconst defaultFieldsColumns = ref([\r\n  { prop: "columnName", label: "字段名", minWidth: 180 },\r\n  { prop: "columnComment", label: "字段注释", minWidth: 150 },\r\n  { prop: "length", label: "长度", width: 100 },\r\n  { prop: "dataType", label: "数据类型", options: "colTypeOptions" },\r\n]);\r\nconst open = computed({\r\n  get: () => props.modelValue,\r\n  set: (val: boolean) => emit("update:modelValue", val),\r\n});\r\n\r\nconst init = () => {\r\n  $common\r\n    .post("/dst/catalog/list", {\r\n      assetType: "db",\r\n    })\r\n    .then((res: any) => {\r\n      const options = res.map((item: any) => ({\r\n        label: item.database,\r\n        value: item.id,\r\n      }));\r\n      jsonFormRef.value?.updateFieldOptions("dbId", options);\r\n    });\r\n  const addUrl = "/ods/getTableTempalte";\r\n  const viewUrl = "/ods/queryTargetTableInfo";\r\n  $common\r\n    .post(props.type === "add" ? addUrl : viewUrl, {\r\n      tid: props.id,\r\n    })\r\n    .then((res: any) => {\r\n      // 设置表单数据(表信息)\r\n      jsonFormRef.value?.setValue(res.propList);\r\n      // 设置表格数据(字段列表)\r\n      if (res.tableItems?.length) {\r\n        tableRef.value?.setData(res.tableItems);\r\n      }\r\n    });\r\n};\r\n\r\nconst handleCopyDDL = () => {\r\n  if (ddlSql.value) {\r\n    $common.copyText(ddlSql.value);\r\n  } else {\r\n    ElMessage.warning("没有可复制的内容");\r\n  }\r\n};\r\n\r\nconst handleCancel = () => {\r\n  emit("close");\r\n  open.value = false;\r\n};\r\n\r\nconst handleShowDDL = async () => {\r\n  await jsonFormRef.value?.validate();\r\n  ddlDialogVisible.value = true;\r\n  const propList = await jsonFormRef.value?.getFormData();\r\n  const tableItems = tableRef.value?.getData() || [];\r\n  $common\r\n    .post("/dst/database/metadata/getCreateTableDDL", {\r\n      propList,\r\n      tableItems,\r\n    })\r\n    .then((res: any) => {\r\n      ddlSql.value = res;\r\n    });\r\n};\r\n\r\nconst handleSave = async () => {\r\n  try {\r\n    await jsonFormRef.value?.validate();\r\n    await tableRef.value?.validate();\r\n    isSaveing.value = true;\r\n\r\n    const tableFields = tableRef.value?.getData();\r\n    const formData = await jsonFormRef.value?.getFormData();\r\n    await $common.post("/ods/createTapleApply", {\r\n      propList: formData,\r\n      tableItems: tableFields,\r\n      tid: props.id,\r\n    });\r\n    ElMessage.success("提交成功");\r\n    emit("save");\r\n    isSaveing.value = false;\r\n  } catch (error: any) {\r\n    isSaveing.value = false;\r\n    ElMessage.error(error.message || "提交失败");\r\n  }\r\n};\r\n\r\n// Handle table button click\r\nconst handleTableBtnClick = async (params: any) => {\r\n  const { code } = params;\r\n\r\n  switch (code) {\r\n    case "default_field":\r\n      // 打开默认字段弹窗\r\n      handleOpenDefaultFieldsDrawer();\r\n      break;\r\n  }\r\n};\r\n\r\n// 打开默认字段弹窗，同步选中状态\r\nconst handleOpenDefaultFieldsDrawer = () => {\r\n  // 获取当前表格中的所有字段\r\n  const currentFields = tableRef.value?.getData() || [];\r\n\r\n  // 提取已存在的字段名\r\n  const existingFieldNames = new Set(currentFields.map((field: any) => field.columnName));\r\n\r\n  // 根据现有字段同步选中默认字段\r\n  const fieldsToSelect = defaultFieldsData.value.filter((item) =>\r\n    existingFieldNames.has(item.columnName)\r\n  );\r\n\r\n  // 打开弹窗\r\n  defaultFieldsVisible.value = true;\r\n\r\n  // 等待弹窗打开后，设置表格的选中行\r\n  setTimeout(() => {\r\n    if (defaultFieldsTableRef.value) {\r\n      const table = defaultFieldsTableRef.value.$table;\r\n      if (table) {\r\n        // 先清除所有选中\r\n        table.clearSelection();\r\n        // 设置选中行\r\n        fieldsToSelect.forEach((row) => {\r\n          table.toggleRowSelection(row, true);\r\n        });\r\n      }\r\n    }\r\n  }, 100);\r\n};\r\n\r\n// 处理选中变化\r\nconst handleSelectionChange = (selection: any[]) => {\r\n  selectedDefaultFields.value = selection;\r\n};\r\n\r\n// 确认添加默认字段\r\nconst handleConfirmDefaultFields = () => {\r\n  if (selectedDefaultFields.value.length === 0) {\r\n    ElMessage.warning("请至少选择一个字段");\r\n    return;\r\n  }\r\n\r\n  // 获取当前表格中的所有字段\r\n  const currentFields = tableRef.value?.getData() || [];\r\n  const existingFieldNames = new Set(currentFields.map((field: any) => field.columnName));\r\n\r\n  // 将选中的默认字段转换为表格所需的格式\r\n  const newFields = selectedDefaultFields.value.filter(\r\n    (item) => !existingFieldNames.has(item.columnName)\r\n  );\r\n\r\n  if (newFields.length === 0) {\r\n    ElMessage.info("所选字段已全部存在于表格中");\r\n    defaultFieldsVisible.value = false;\r\n    return;\r\n  }\r\n\r\n  // 将字段添加到表格末尾\r\n  newFields.forEach((field) => {\r\n    tableRef.value?.$grid?.insertAt(field, -1);\r\n  });\r\n\r\n  ElMessage.success(\r\n    `已添加 ${newFields.length} 个默认字段${\r\n      selectedDefaultFields.value.length > newFields.length\r\n        ? `（${selectedDefaultFields.value.length - newFields.length} 个已存在）`\r\n        : ""\r\n    }`\r\n  );\r\n  defaultFieldsVisible.value = false;\r\n};\r\n\r\nonMounted(() => {\r\n  if (props.id) {\r\n    init();\r\n  }\r\n});\r\n</script>\r\n\r\n<style lang="scss" scoped>\r\n.access-apply {\n  .access-apply-content {\r\n    :deep(.vxe-toolbar .vxe-button--item-wrapper) {\r\n      justify-content: end;\r\n    }\r\n    :deep(.btn-plain) {\r\n      background-color: #fff !important;\r\n      color: #1b67f8;\r\n      border: 1px solid #8db3fc;\r\n      &:hover {\r\n        color: #4985f9 !important;\r\n        border-color: #4985f9 !important;\r\n        outline: none;\r\n      }\r\n    }\r\n    :deep(.btn-primary) {\r\n      &:hover {\r\n        background-color: #5f95fa !important;\r\n        border-color: #5f95fa !important;\r\n        outline: none;\r\n      }\r\n    }\r\n  }\n}\n\n// DDL drawer uses the remaining body height all the way down to the Ace editor.\n:global(.ddl-preview-drawer .el-drawer__body) {\n  min-height: 0;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-content) {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor) {\n  min-height: 0;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor > .el-scrollbar) {\n  min-height: 0;\n  height: 100%;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__wrap),\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view) {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view) {\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .ace_editor) {\n  min-height: 0 !important;\n  height: 100% !important;\n  flex: 1 1 auto;\n}\n</style>\n','const _defineCo