ctedDefaultFields": "setup-ref",\n  "defaultFieldsTableRef": "setup-ref",\n  "formRules": "setup-maybe-ref",\n  "tableRef": "setup-ref",\n  "tableColumns": "setup-ref",\n  "defaultFieldsColumns": "setup-ref",\n  "open": "setup-ref",\n  "init": "setup-const",\n  "handleCopyDDL": "setup-const",\n  "handleCancel": "setup-const",\n  "handleShowDDL": "setup-const",\n  "handleSave": "setup-const",\n  "handleTableBtnClick": "setup-const",\n  "handleOpenDefaultFieldsDrawer": "setup-const",\n  "handleSelectionChange": "setup-const",\n  "handleConfirmDefaultFields": "setup-const",\n  "modelValue": "props",\n  "type": "props",\n  "id": "props"\n} */\n__sfc__.__scopeId = "data-v-ca3defa59d7489b7696996f4796a90fc"\n__sfc__.__file = "ca3defa59d7489b7696996f4796a90fc.vue"\nreturn __sfc__','.access-apply .access-apply-content[data-v-ca3defa59d7489b7696996f4796a90fc] .vxe-toolbar .vxe-button--item-wrapper {\n  justify-content: end;\n}\n.access-apply .access-apply-content[data-v-ca3defa59d7489b7696996f4796a90fc] .btn-plain {\n  background-color: #fff !important;\n  color: #1b67f8;\n  border: 1px solid #8db3fc;\n}\n.access-apply .access-apply-content[data-v-ca3defa59d7489b7696996f4796a90fc] .btn-plain:hover {\n  color: #4985f9 !important;\n  border-color: #4985f9 !important;\n  outline: none;\n}\n.access-apply .access-apply-content[data-v-ca3defa59d7489b7696996f4796a90fc] .btn-primary:hover {\n  background-color: #5f95fa !important;\n  border-color: #5f95fa !important;\n  outline: none;\n}\n.ddl-preview-drawer .el-drawer__body {\n  min-height: 0;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-content {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor {\n  min-height: 0;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor > .el-scrollbar {\n  min-height: 0;\n  height: 100%;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__wrap,.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n}\n.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view {\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor .ace_editor {\n  min-height: 0 !important;\n  height: 100% !important;\n  flex: 1 1 auto;\n}','1','接入申请',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016463450651824128','2008730136700588032','access-modal','<template>\r\n  <el-dialog\r\n    v-model="open"\r\n    destroy-on-close\r\n    fullscreen\r\n    class="access-modal__container"\r\n    body-class="px-20"\r\n    header-class="p-0!"\r\n    @close="onCancel"\r\n  >\r\n    <div class="flex flex-col h-full">\r\n      <div class="access-modal__header">\r\n        <div class="access-modal__title">数据接入</div>\r\n      </div>\r\n      <template v-if="!isFinish">\r\n        <el-scrollbar>\r\n          <div class="access-modal__body">\r\n            <el-skeleton :loading="loading" animated>\r\n              <JsonForm ref="formRef" bordered :rules="formRules">\r\n                <template #field-taskTypeId="scope">\r\n                  <el-tree-select\r\n                    v-model="scope.model.value"\r\n                    :data="eltCategoryOptions"\r\n                    :default-expand-all="true"\r\n                    placeholder="请选择数据库"\r\n                    @change="handleEltChange"\r\n                  ></el-tree-select>\r\n                </template>\r\n              </JsonForm>\r\n              <u-title name="数据库表配置" class="mt-4" />\r\n              <database-config\r\n                ref="databaseConfigRef"\r\n                :info="basicInfo"\r\n                :edit="!props.id"\r\n              ></database-config>\r\n              <u-title name="字段映射" class="mt-4 mapping-title">\r\n                <el-button type="text" class="ml-2" @click="handleAutoMapping">\r\n                  <Icon icon="el-icon-Refresh"></Icon>\r\n                  自动映射\r\n                </el-button>\r\n              </u-title>\r\n              <field-mapping\r\n                ref="fieldMappingRef"\r\n                :data="basicInfo.columnMapping"\r\n                :target-field-options="targetFieldOptions"\r\n              ></field-mapping>\r\n              <u-title name="执行调度策略" class="mt-4" />\r\n              <schedule-config ref="scheduleConfigRef" :info="basicInfo"></schedule-config>\r\n            </el-skeleton>\r\n          </div>\r\n        </el-scrollbar>\r\n        <div class="access-modal__footer">\r\n          <el-button @click="onCancel">取消</el-button>\r\n          <el-button type="primary" plain :disabled="isSaveing" @click="handleSave">\r\n            <icon :icon="\'save\'" class="mr-2" />\r\n            保存\r\n          </el-button>\r\n          <el-button type="primary" :disabled="taskLoading" @click="handleCreateTask">\r\n            <icon :icon="\'check-circle\'" class="mr-2" />\r\n            创建任务\r\n          </el-button>\r\n        </div>\r\n      </template>\r\n      <task-finish\r\n        v-else\r\n        :name="basicInfo.taskName"\r\n        :code="basicInfo.dataCatalogId"\r\n        :time="basicInfo.lastRunning"\r\n        :type="\'access\'"\r\n        title="创建成功"\r\n        @to-see="onToSee"\r\n      ></task-finish>\r\n    </div>\r\n  </el-dialog>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, computed, nextTick } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { ElMessage } from "element-plus";\r\n// import databaseConfig from "./databaseConfig.vue";\r\n// import fieldMapping from "./fieldMapping.vue";\r\n// import scheduleConfig from "./scheduleConfig.vue";\r\n// import taskFinish from "./task-finish.vue";\r\n\r\ninterface BasicInfo {\r\n  dataCatalogId?: string;\r\n  taskName?: string;\r\n  taskTypeName?: string;\r\n  taskTypeId?: string;\r\n  taskDesc?: string;\r\n  sourceDbId?: string;\r\n  sourceTableId?: string;\r\n  sourceTablePrimaryKey?: string;\r\n  sourceTableIncrementKey?: string;\r\n  targetDbId?: string;\r\n  targetTableId?: string;\r\n  targetTablePrimaryKey?: string;\r\n  scheduleStrategy?: number;\r\n  scheduleCycle?: number;\r\n  scheduleRunning?: string;\r\n  scheduleRunningStart?: string;\r\n  scheduleFaildRetry?: number;\r\n  cronExpress?: string;\r\n  taskStatus?: number;\r\n  lastRunning?: string;\r\n  lastStatusValue?: string;\r\n  endRunning?: string;\r\n  tenantId?: string;\r\n  columnMapping?: any[];\r\n}\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", value: boolean): void;\r\n  (e: "close", value: boolean): void;\r\n}>();\r\n\r\nconst props = defineProps({\r\n  modelValue: Boolean,\r\n  id: String, // 目录id\r\n  accessTaskId: String, // 任务id\r\n});\r\nconst formRules = ref([]);\r\nconst formRef = ref();\r\nconst databaseConfigRef = ref();\r\nconst fieldMappingRef = ref();\r\nconst scheduleConfigRef = ref();\r\nconst loading = ref(false);\r\nconst taskLoading = ref(false);\r\nconst basicInfo = ref<BasicInfo>({});\r\nconst isFinish = ref(false);\r\nconst isSaved = ref(false);\r\nconst isSaveing = ref(false);\r\nconst eltCategoryOptions = ref<any[]>([]);\r\n// 目标字段选项 - 从 databaseConfig 获取后传递给 fieldMapping\r\nconst targetFieldOptions = ref<any[]>([]);\r\n\r\nconst open = computed({\r\n  get: () => props.modelValue,\r\n  set: (val: boolean) => emit("update:modelValue", val),\r\n});\r\n\r\nformRules.value = FormUtils.fixJson([\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "任务基本要素",\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "任务名称",\r\n    field: "taskName",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "fieldComponent",\r\n    title: "ETL任务分类",\r\n    field: "taskTypeId",\r\n    props: {\r\n      data: [],\r\n      placeholder: "请选择ETL任务分类",\r\n      clearable: true,\r\n      filterable: true,\r\n      "check-strictly": false,\r\n      "default-expand-all": true,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    field: "taskDesc",\r\n    title: "任务描述",\r\n    props: {\r\n      type: "textarea",\r\n      maxlength: 255,\r\n      rows: 4,\r\n    },\r\n    col: {\r\n      span: 24,\r\n    },\r\n  },\r\n]);\r\n\r\nconst handleEltChange = (value: any) => {\r\n  formRef.value?.setValue({\r\n    taskTypeId: value,\r\n  });\r\n};\r\n\r\n// 获取ETL任务分类数据\r\nconst fetchEltCategoryOptions = async () => {\r\n  try {\r\n    const res = await $common.get("/ods/getEtlGroup");\r\n    const data = Array.isArray(res) ? res : [];\r\n    eltCategoryOptions.value = data;\r\n    // 强制更新表单的 field 数据\r\n    await nextTick();\r\n    formRef.value?.updateFieldOptions("taskTypeId", data);\r\n  } catch (error) {\r\n    console.error("获取ETL任务分类失败:", error);\r\n    ElMessage.error("获取ETL任务分类失败");\r\n  }\r\n};\r\n\r\nconst onCancel = (): void => {\r\n  emit("close", false);\r\n  open.value = false;\r\n};\r\n\r\nconst onToSee = () => {\r\n  emit("close", true);\r\n  open.value = false;\r\n};\r\n\r\n// 获取建表后去接入时的信息\r\nconst fetchAccessInfo = async (id?: string) => {\r\n  if (!id) return;\r\n  try {\r\n    loading.value = true;\r\n    $common\r\n      .post("/ods/task/autoMappingTemplate", {\n        tid: id,\r\n      })\r\n      .then((res: any) => {\r\n        basicInfo.value = res;\r\n      });\r\n    loading.value = false;\r\n  } catch (error) {\r\n    console.error("获取接入信息失败:", error);\r\n    loading.value = false;\r\n  }\r\n};\r\n\r\n// 处理自动映射\r\nconst handleAutoMapping = async () => {\r\n  try {\r\n    // 检查数据库表配置是否完成\r\n    await databaseConfigRef.value?.getConfig();\r\n    const sourceInfo = await databaseConfigRef.value?.getSourceFormData();\r\n    const targetInfo = await databaseConfigRef.value?.getTargetFormData();\r\n    const info = (await $common.post("/ods/task/columnAutoMapping", {\n      sourceTableId: sourceInfo.sourceTableId,\r\n      targetTableId: targetInfo.targetTableId,\r\n    })) as any;\r\n    if (!info || !Array.isArray(info)) {\r\n      ElMessage.error("自动映射失败");\r\n      return;\r\n    }\r\n    basicInfo.value.columnMapping = info;\r\n    ElMessage.success("字段自动映射完成");\r\n  } catch (error) {\r\n    console.error("自动映射失败:", error);\r\n    ElMessage.error("自动映射失败");\r\n  }\r\n};\r\n\r\n// 保存表单数据\r\nconst handleSave = async () => {\r\n  try {\r\n    await formRef.value?.validate();\r\n    isSaveing.value = true;\r\n    const databaseConfig = await databaseConfigRef.value?.getConfig();\r\n    const fieldMapping = await fieldMappingRef.value?.fieldMappingData;\r\n    const scheduleConfig = await scheduleConfigRef.value?.getConfig();\r\n    const formData = await formRef.value.getFormData();\r\n    await $common.post("/ods/task/saveOrUpdate", {\r\n      ...formData,\r\n      ...databaseConfig,\r\n      ...scheduleConfig,\r\n      columnMapping: fieldMapping,\r\n    });\r\n\r\n    // 保存成功后设置保存状态为 true\r\n    isSaved.value = true;\r\n    isSaveing.value = false;\r\n    ElMessage.success("保存成功");\r\n  } catch (error) {\r\n    isSaved.value = false;\r\n    isSaveing.value = false;\r\n    console.error("表单校验失败:", error);\r\n    ElMessage.error("保存失败，请检查表单");\r\n  }\r\n};\r\n\r\n// 创建任务\r\nconst handleCreateTask = async () => {\r\n  // 检查是否已经保存\r\n  if (!isSaved.value) {\r\n    ElMessage.warning("请先保存配置信息");\r\n    return;\r\n  }\r\n\r\n  try {\r\n    // 模拟创建任务的过程\r\n    taskLoading.value = true;\r\n    await new Promise((resolve) => setTimeout(resolve, 1500));\r\n    isFinish.value = true;\r\n    ElMessage.success("任务创建成功");\r\n  } catch (error) {\r\n    console.error("创建任务失败:", error);\r\n    ElMessage.error("创建任务失败，请重试");\r\n  } finally {\r\n    taskLoading.value = false;\r\n  }\r\n};\r\n\r\nwatch(\r\n  open,\r\n  (val: boolean) => {\r\n    if (val) {\r\n      // 模态框打开时重置保存状态\r\n      isSaved.value = false;\r\n      // 打开弹窗时加载ETL任务分类数据\r\n      fetchEltCategoryOptions();\r\n      fetchAccessInfo(props.id);\r\n    }\r\n  },\r\n  { immediate: true }\r\n);\r\n\r\n// 监听 databaseConfig 的目标字段选项变化，实时更新给 fieldMapping\r\nwatch(\r\n  () => databaseConfigRef.value?.targetFieldOptions,\r\n  (newOptions) => {\r\n    if (Array.isArray(newOptions) && newOptions.length > 0) {\r\n      targetFieldOptions.value = newOptions;\r\n    }\r\n  },\r\n  { immediate: true, deep: true }\r\n);\r\n</script>\r\n\r\n<style lang="scss">\r\n.access-modal__container {\r\n  padding: 0;\r\n  .el-dialog__body {\r\n    height: 100%;\r\n    padding: 0;\r\n  }\r\n  .el-dialog__header {\r\n    padding: 0;\r\n  }\r\n  .access-modal__body {\r\n    padding: 0.5rem 1.25rem;\r\n  }\r\n  .access-modal__header {\r\n    display: grid;\r\n    flex-shrink: 0;\r\n    grid-template-columns: 15% 1fr 15%;\r\n    align-items: center;\r\n    height: 45px;\r\n    padding: 0 15px 0 20px;\r\n    background-color: #fff;\r\n    border-bottom: 1px solid #ebeef5;\r\n  }\r\n  .access-modal__title {\r\n    font-family: Arial, sans-serif;\r\n    font-size: 16px;\r\n    font-weight: 700;\r\n    color: #000000e0;\r\n  }\r\n  .access-modal__footer {\r\n    display: flex;\r\n    justify-content: center;\r\n    padding: 10px 24px;\r\n    text-align: right;\r\n    background-color: #fff;\r\n    border-top: 1px solid #ebeef5;\r\n  }\r\n  .mapping-title {\r\n    & .title {\r\n      line-height: 32px !important;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "flex flex-col h-full"\n};\nconst _hoisted_2 = {\n  class: "access-modal__body"\n};\nconst _hoisted_3 = {\n  class: "access-modal__footer"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst ElMessage = ___magic__import__(\'element-plus\', \'ElMessage\');\n// import databaseConfig from "./databaseConfig.vue";\n// import fieldMapping from "./fieldMapping.vue";\n// import scheduleConfig from "./scheduleConfig.vue";\n// import taskFinish from "./task-finish.vue";\n\nconst __sfc__ = _defineComponent({\n  __name: \'533d9beaef24c0b2769caac3adca9a9d\',\n  props: {\n    modelValue: Boolean,\n    id: String,\n    // 目录id\n    accessTaskId: String // 任务id\n  },\n  emits: ["update:modelValue", "close"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const emit = __emit;\n    const props = __props;\n    const formRules = ref([]);\n    const formRef = ref();\n    const databaseConfigRef = ref();\n    const fieldMappingRef = ref();\n    const scheduleConfigRef = ref();\n    const loading = ref(false);\n    const taskLoading = ref(false);\n    const basicInfo = ref({});\n    const isFinish = ref(false);\n    const isSaved = ref(false);\n    const isSaveing = ref(false);\n    const eltCategoryOptions = ref([]);\n    // 目标字段选项 - 从 databaseConfig 获取后传递给 fieldMapping\n    const targetFieldOptions = ref([]);\n    const open = computed({\n      get: () => props.modelValue,\n      set: val => emit("update:modelValue", val)\n    });\n    formRules.value = FormUtils.fixJson([{\n      type: "UTitle",\n      props: {\n        name: "任务基本要素"\n      }\n    }, {\n      type: "input",\n      title: "任务名称",\n      field: "taskName",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "fieldComponent",\n      title: "ETL任务分类",\n      field: "taskTypeId",\n      props: {\n        data: [],\n        placeholder: "请选择ETL任务分类",\n        clearable: true,\n        filterable: true,\n        "check-strictly": false,\n        "default-expand-all": true\n      },\n      col: {\n        span: 12\n      }\n    }, {\n      type: "input",\n      field: "taskDesc",\n      title: "任务描述",\n      props: {\n        type: "textarea",\n        maxlength: 255,\n        rows: 4\n      },\n      col: {\n        span: 24\n      }\n    }]);\n    const handleEltChange = value => {\n      formRef.value?.setValue({\n        taskTypeId: value\n      });\n    };\n\n    // 获取ETL任务分类数据\n    const fetchEltCategoryOptions = async () => {\n      try {\n        const res = await $common.get("/ods/getEtlGroup");\n        const data = Array.isArray(res) ? res : [];\n        eltCategoryOptions.value = data;\n        // 强制更新表单的 field 数据\n        await nextTick();\n        formRef.value?.updateFieldOptions("taskTypeId", data);\n      } catch (error) {\n        console.error("获取ETL任务分类失败:", error);\n        ElMessage.error("获取ETL任务分类失败");\n      }\n    };\n    const onCancel = () => {\n      emit("close", false);\n      open.value = false;\n    };\n    const onToSee = () => {\n      emit("close", true);\n      open.value = false;\n    };\n\n    // 获取建表后去接入时的信息\n    const fetchAccessInfo = async id => {\n      if (!id) return;\n      try {\n        loading.value = true;\n        $common.post("/ods/task/autoMappingTemplate", {\n          tid: id\n        }).then(res => {\n          basicInfo.value = res;\n        });\n        loading.value = false;\n      } catch (error) {\n        console.error("获取接入信息失败:", error);\n        loading.value = false;\n      }\n    };\n\n    // 处理自动映射\n    const handleAutoMapping = async () => {\n      try {\n        // 检查数据库表配置是否完成\n        await databaseConfigRef.value?.getConfig();\n        const sourceInfo = await databaseConfigRef.value?.getSourceFormData();\n        const targetInfo = await databaseConfigRef.value?.getTargetFormData();\n        const info = await $common.post("/ods/task/columnAutoMapping", {\n          sourceTableId: sourceInfo.sourceTableId,\n          targetTableId: targetInfo.targetTableId\n        });\n        if (!info || !Array.isArray(info)) {\n          ElMessage.error("自动映射失败");\n          return;\n        }\n        basicInfo.value.columnMapping = info;\n        ElMessage.success("字段自动映射完成");\n      } catch (error) {\n        console.error("自动映射失败:", error);\n        ElMessage.error("自动映射失败");\n      }\n    };\n\n    // 保存表单数据\n    const handleSave = async () => {\n      try {\n        await formRef.value?.validate();\n        isSaveing.value = true;\n        const databaseConfig = await databaseConfigRef.value?.getConfig();\n        const fieldMapping = await fieldMappingRef.value?.fieldMappingData;\n        const scheduleConfig = await scheduleConfigRef.value?.getConfig();\n        const formData = await formRef.value.getFormData();\n        await $common.post("/ods/task/saveOrUpdate", {\n          ...formData,\n          ...databaseConfig,\n          ...scheduleConfig,\n          columnMapping: fieldMapping\n        });\n\n        // 保存成功后设置保存状态为 true\n        isSaved.value = true;\n        isSaveing.value = false;\n        ElMessage.success("保存成功");\n      } catch (error) {\n        isSaved.value = false;\n        isSaveing.value = false;\n        console.error("表单校验失败:", error);\n        ElMessage.error("保存失败，请检查表单");\n      }\n    };\n\n    // 创建任务\n    const handleCreateTask = async () => {\n      // 检查是否已经保存\n      if (!isSaved.value) {\n        ElMessage.warning("请先保存配置信息");\n        return;\n      }\n      try {\n        // 模拟创建任务的过程\n        taskLoading.value = true;\n        await new Promise(resolve => setTimeout(resolve, 1500));\n        isFinish.value = true;\n        ElMessage.success("任务创建成功");\n      } catch (error) {\n        console.error("创建任务失败:", error);\n        ElMessage.error("创建任务失败，请重试");\n      } finally {\n        taskLoading.value = false;\n      }\n    };\n    watch(open, val => {\n      if (val) {\n        // 模态框打开时重置保存状态\n        isSaved.value = false;\n        // 打开弹窗时加载ETL任务分类数据\n        fetchEltCategoryOptions();\n        fetchAccessInfo(props.id);\n      }\n    }, {\n      immediate: true\n    });\n\n    // 监听 databaseConfig 的目标字段选项变化，实时更新给 fieldMapping\n    watch(() => databaseConfigRef.value?.targetFieldOptions, newOptions => {\n      if (Array.isArray(newOptions) && newOptions.length > 0) {\n        targetFieldOptions.value = newOptions;\n      }\n    }, {\n      immediate: true,\n      deep: true\n    });\n    return (_ctx, _cache) => {\n      const _component_el_tree_select = _resolveComponent("el-tree-select");\n      const _component_JsonForm = _resolveComponent("JsonForm");\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_database_config = _resolveComponent("database-config");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_field_mapping = _resolveComponent("field-mapping");\n      const _component_schedule_config = _resolveComponent("schedule-config");\n      const _component_el_skeleton = _resolveComponent("el-skeleton");\n      const _component_el_scrollbar = _resolveComponent("el-scrollbar");\n      const _component_icon = _resolveComponent("icon");\n      const _component_task_finish = _resolveComponent("task-finish");\n      const _component_el_dialog = _resolveComponent("el-dialog");\n      return _openBlock(), _createBlock(_component_el_dialog, {\n        modelValue: open.value,\n        "onUpdate:modelValue": _cache[0] || (_cache[0] = $event => open.value = $event),\n        "destroy-on-close": "",\n        fullscreen: "",\n        class: "access-modal__container",\n        "body-class": "px-20",\n        "header-class": "p-0!",\n        onClose: onCancel\n      }, {\n        default: _withCtx(() => [_createElementVNode("div", _hoisted_1, [_cache[5] || (_cache[5] = _createElementVNode("div", {\n          class: "access-modal__heade