n  overflow: visible;\n}\n.task-actions[data-v-c5181550ec979488b76faa94673e940e] {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  width: 100%;\n  white-space: nowrap;\n}\n.task-actions[data-v-c5181550ec979488b76faa94673e940e] .el-button {\n  height: auto;\n  min-height: 28px;\n  padding: 0 2px;\n  margin-left: 0;\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 28px;\n}\n.task-actions[data-v-c5181550ec979488b76faa94673e940e] .el-dropdown {\n  display: inline-flex;\n  align-items: center;\n  line-height: 1;\n}\n@media (max-width: 900px) {\n.access-monitor-page[data-v-c5181550ec979488b76faa94673e940e] {\n    padding: 12px;\n}\n.access-toolbar[data-v-c5181550ec979488b76faa94673e940e] {\n    align-items: flex-start;\n    flex-direction: column;\n}\n.toolbar-actions[data-v-c5181550ec979488b76faa94673e940e] {\n    width: 100%;\n    flex-wrap: wrap;\n}\n.task-search[data-v-c5181550ec979488b76faa94673e940e] {\n    flex: 1;\n    width: min(100%, 360px);\n}\n}\n@media (max-width: 1180px) {\n.access-toolbar[data-v-c5181550ec979488b76faa94673e940e] { gap: 10px;\n}\n.toolbar-actions[data-v-c5181550ec979488b76faa94673e940e] { gap: 8px;\n}\n.task-search[data-v-c5181550ec979488b76faa94673e940e] { width: clamp(132px, 18vw, 220px);\n}\n}\n.sync-detail-panel[data-v-c5181550ec979488b76faa94673e940e] {\n  padding: 14px 0 16px 58px;\n  background: linear-gradient(180deg, #f7fbff 0%, #ffffff 100%);\n}\n.sync-detail-card[data-v-c5181550ec979488b76faa94673e940e] {\n  width: min(920px, calc(100vw - 220px));\n  padding: 16px;\n  background: #fff;\n  border: 1px solid #dbeafe;\n  border-radius: 12px;\n  box-shadow: 0 8px 22px rgba(20, 86, 180, 0.08);\n}\n.sync-detail-title[data-v-c5181550ec979488b76faa94673e940e] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 12px;\n  color: #1f2937;\n}\n.sync-detail-title strong[data-v-c5181550ec979488b76faa94673e940e] {\n  display: block;\n  margin-bottom: 4px;\n  font-size: 15px;\n}\n.sync-detail-title span[data-v-c5181550ec979488b76faa94673e940e] {\n  font-size: 13px;\n  color: #667085;\n}\n.sync-flow-list[data-v-c5181550ec979488b76faa94673e940e] {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n.sync-flow-card[data-v-c5181550ec979488b76faa94673e940e] {\n  padding: 14px;\n  background: #f8fbff;\n  border: 1px solid #e6efff;\n  border-radius: 10px;\n}\n.sync-flow-head[data-v-c5181550ec979488b76faa94673e940e] {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 12px;\n  min-width: 0;\n}\n.sync-flow-head strong[data-v-c5181550ec979488b76faa94673e940e] {\n  overflow: hidden;\n  color: #1d2939;\n  font-size: 14px;\n  font-weight: 600;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.sync-flow-index[data-v-c5181550ec979488b76faa94673e940e] {\n  width: 22px;\n  height: 22px;\n  flex: 0 0 22px;\n  color: #1677ff;\n  font-size: 12px;\n  font-weight: 700;\n  line-height: 22px;\n  text-align: center;\n  background: #eef6ff;\n  border-radius: 50%;\n}\n.sync-route[data-v-c5181550ec979488b76faa94673e940e] {\n  display: grid;\n  grid-template-columns: minmax(190px, 1fr) 92px minmax(190px, 1fr);\n  align-items: stretch;\n  gap: 12px;\n}\n.sync-node[data-v-c5181550ec979488b76faa94673e940e] {\n  min-width: 0;\n  padding: 10px 12px;\n  border-radius: 10px;\n}\n.sync-node-source[data-v-c5181550ec979488b76faa94673e940e] {\n  background: #f2f8ff;\n}\n.sync-node-target[data-v-c5181550ec979488b76faa94673e940e] {\n  background: #f4fbf7;\n}\n.sync-node-label[data-v-c5181550ec979488b76faa94673e940e] {\n  display: block;\n  margin-bottom: 6px;\n  color: #7a8aa0;\n  font-size: 12px;\n}\n.sync-node strong[data-v-c5181550ec979488b76faa94673e940e] {\n  display: block;\n  overflow: hidden;\n  color: #1f2937;\n  font-size: 14px;\n  font-weight: 600;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.sync-node span[data-v-c5181550ec979488b76faa94673e940e]:last-child {\n  display: block;\n  overflow: hidden;\n  margin-top: 4px;\n  color: #6b7280;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.sync-arrow[data-v-c5181550ec979488b76faa94673e940e] {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  color: #1677ff;\n  font-size: 12px;\n}\n.sync-meta-grid[data-v-c5181550ec979488b76faa94673e940e] {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px 12px;\n  margin-top: 12px;\n}\n.sync-meta-grid label[data-v-c5181550ec979488b76faa94673e940e] {\n  display: block;\n  margin-bottom: 2px;\n  color: #8a96a8;\n  font-size: 12px;\n}\n.sync-meta-grid span[data-v-c5181550ec979488b76faa94673e940e] {\n  display: block;\n  overflow: hidden;\n  color: #344054;\n  font-size: 13px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n@media (max-width: 1280px) {\n.sync-detail-card[data-v-c5181550ec979488b76faa94673e940e] {\n    width: min(820px, calc(100vw - 180px));\n}\n.sync-route[data-v-c5181550ec979488b76faa94673e940e] {\n    grid-template-columns: minmax(180px, 1fr);\n}\n.sync-arrow[data-v-c5181550ec979488b76faa94673e940e] {\n    flex-direction: row;\n}\n.sync-meta-grid[data-v-c5181550ec979488b76faa94673e940e] {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n}\n.danger-item[data-v-c5181550ec979488b76faa94673e940e] {\n  color: #f56c6c;\n}','1','2.3.2 接入监控',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2063874276488429568','2063874204568698880','api-build-content','<template>\r\n  <div class="api-build-content">\r\n    <!-- 表单 -->\r\n    <json-form ref="formRef" bordered :rules="formRules">\r\n      <!-- 基本要素标题栏：detail 场景下渲染编辑/取消/保存按钮 -->\r\n      <template #type-u-title="{ rule }">\r\n        <u-title :name="rule.props?.name" class="gap-4" style="height: 50px">\r\n          <div v-if="context === \'detail\' && rule.props.name === \'基本要素\'">\r\n            <template v-if="!isEditing">\r\n              <el-button type="primary" plain icon="edit" @click="startEdit">编辑修改</el-button>\r\n            </template>\r\n            <template v-else>\r\n              <el-button type="primary" link @click="handleCancel">取消</el-button>\r\n              <el-button type="primary" link :loading="saveLoading" @click="handleSave">\r\n                <Icon icon="save" class="mr-1" />\r\n                保存\r\n              </el-button>\r\n            </template>\r\n          </div>\r\n        </u-title>\r\n      </template>\r\n    </json-form>\r\n\r\n    <!-- 参数信息 -->\r\n    <u-title name="参数信息" />\r\n    <v-table\r\n      ref="paramsRef"\r\n      :options="paramsTableOptions"\r\n      :editable="currentMode === \'edit\'"\r\n      :show-operation="false"\r\n      class="api-params-table"\r\n      @data-change="handleParamsDataChange"\r\n    >\r\n      <template #req="{ row }">\r\n        <el-checkbox\r\n          :model-value="row.req === 1"\r\n          :disabled="currentMode === \'view\'"\r\n          @update:model-value="(val: CheckboxValueType) => handleReqChange(row, val)"\r\n        />\r\n      </template>\r\n      <template #res="{ row }">\r\n        <el-checkbox\r\n          :model-value="row.res === 1"\r\n          :disabled="currentMode === \'view\'"\r\n          @update:model-value="(val: CheckboxValueType) => handleResChange(row, val)"\r\n        />\r\n      </template>\r\n      <template #req_header="{ column }">\r\n        <el-checkbox\r\n          :model-value="allReq"\r\n          :indeterminate="indeterminateReq"\r\n          :disabled="currentMode === \'view\'"\r\n          class="header-checkbox"\r\n          @change="handleAllReqChange"\r\n        >\r\n          {{ column.title }}\r\n        </el-checkbox>\r\n      </template>\r\n      <template #res_header="{ column }">\r\n        <el-checkbox\r\n          :model-value="allRes"\r\n          :indeterminate="indeterminateRes"\r\n          :disabled="currentMode === \'view\'"\r\n          class="header-checkbox"\r\n          @change="handleAllResChange"\r\n        >\r\n          {{ column.title }}\r\n        </el-checkbox>\r\n      </template>\r\n      <template #required="{ row }">\r\n        <el-checkbox\r\n          v-if="currentMode === \'edit\'"\r\n          :model-value="row.required === 1"\r\n          @update:model-value="(val) => (row.required = val ? 1 : 0)"\r\n        />\r\n        <el-checkbox v-else :model-value="row.required === 1" disabled />\r\n      </template>\r\n      <template #columnOperator="{ row }">\r\n        <el-select\r\n          v-if="row.req === 1 && currentMode === \'edit\'"\r\n          v-model="row.columnOperator"\r\n          placeholder="请选择运算符"\r\n          clearable\r\n          size="small"\r\n        >\r\n          <el-option label="and" value="and" />\r\n          <el-option label="or" value="or" />\r\n        </el-select>\r\n        <span v-else class="text-gray-400">\r\n          {{ row.req === 1 ? row.columnOperator || "--" : "--" }}\r\n        </span>\r\n      </template>\r\n      <template #requestOperator="{ row }">\r\n        <el-select\r\n          v-if="row.req === 1 && currentMode === \'edit\'"\r\n          v-model="row.requestOperator"\r\n          placeholder="请选择操作符"\r\n          clearable\r\n          size="small"\r\n        >\r\n          <el-option label="=" value="=" />\r\n          <el-option label=">" value=">" />\r\n          <el-option label="<" value="<" />\r\n          <el-option label="in" value="in" />\r\n          <el-option label="like" value="like" />\r\n          <el-option label="between" value="between" />\r\n        </el-select>\r\n        <span v-else class="text-gray-400">\r\n          {{ row.req === 1 ? row.requestOperator || "--" : "--" }}\r\n        </span>\r\n      </template>\r\n    </v-table>\r\n\r\n    <!-- 响应示例（已注释） -->\r\n    <!-- <u-title name="响应示例" />\r\n    <div style="height: 300px">\r\n      <code-editor v-model="responseExample" :lang="\'json\'" :read-only="currentMode === \'view\'" />\r\n    </div> -->\r\n\r\n    <!-- 状态码（已注释） -->\r\n    <!-- <u-title name="状态码" />\r\n    <ServiceStatusTable\r\n      ref="statusRef"\r\n      :enable-drag="currentMode === \'edit\'"\r\n      :readonly="currentMode === \'view\'"\r\n    /> -->\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, reactive, computed, watch, nextTick } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { ElMessage } from "element-plus";\r\nimport type { CheckboxValueType } from "element-plus";\r\nimport { useDictStore } from "@/store";\r\n// import ServiceStatusTable from "./ServiceStatusTable.vue";\r\n\r\nconst props = withDefaults(\r\n  defineProps<{\r\n    /** 使用场景：modal=弹窗创建, detail=详情页查看/编辑 */\r\n    context: "modal" | "detail";\r\n    /** 详情页传入的已有数据（含 id 时为更新，无 id 时为新建） */\r\n    data?: Record<string, any>;\r\n  }>(),\r\n  {\r\n    context: "detail",\r\n    data: () => ({}),\r\n  }\r\n);\r\n\r\nconst emit = defineEmits<{\r\n  (e: "saved", data: Record<string, any>): void;\r\n}>();\r\n\r\n// ==================== 编辑状态（仅 detail 场景） ====================\r\nconst isEditing = ref(props.context === "modal");\r\nconst saveLoading = ref(false);\r\nconst currentMode = computed(() => {\r\n  if (props.context === "modal") return "edit";\r\n  return isEditing.value ? "edit" : "view";\r\n});\r\n\r\n// ==================== Refs ====================\r\nconst formRef = ref();\r\nconst paramsRef = ref();\r\n// const statusRef = ref();\r\n// const responseExample = ref("");\r\nconst tableOptions = ref<\r\n  { label: string; value: string; tableName: string; tableNameCn: string; tid: string }[]\r\n>([]);\r\n\r\n// ==================== 表单配置（双规则集：fixJson 预处理 → view=transFormText, edit=rawRules） ====================\r\nconst rawRules = FormUtils.fixJson([\r\n  { type: "UTitle", props: { name: "基本要素" } },\r\n  { type: "input", title: "服务名称", field: "serviceName", col: { span: 12 }, $required: true },\r\n  {\r\n    type: "dict-select",\r\n    title: "服务目录",\r\n    field: "catalogId",\r\n    props: {\r\n      placeholder: "请选择服务目录",\r\n      options: "catalog",\r\n      filterable: true,\r\n      filters: {\r\n        assetStatus: "2",\r\n      },\r\n    },\r\n    col: { span: 12 },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "dict-select",\r\n    title: "数据源",\r\n    field: "dataSourceId",\r\n    props: {\r\n      options: "db",\r\n      placeholder: "请选择所属数据源",\r\n      clearable: true,\r\n      filters: { orgId: "$user.orgId" },\r\n    },\r\n    on: {\r\n      change: (value: string) => {\r\n        fetchTables(value);\r\n      },\r\n    },\r\n    col: { span: 12 },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "表名",\r\n    field: "tableName",\r\n    col: { span: 12 },\r\n    props: {\r\n      filterable: true,\r\n      clearable: true,\r\n      placeholder: "请先选择数据源",\r\n      options: tableOptions.value,\r\n    },\r\n    on: {\r\n      change: (value: string) => {\r\n        fetchColumns(value);\r\n      },\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "操作类型",\r\n    field: "operationType",\r\n    col: { span: 12 },\r\n    props: {\r\n      options: [\r\n        { label: "查询(select)", value: "0" },\r\n        { label: "新增(insert)", value: "1" },\r\n        { label: "修改(update)", value: "2" },\r\n        { label: "删除(delete)", value: "3" },\r\n      ],\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "数据模式",\r\n    field: "model",\r\n    col: { span: 12 },\r\n    props: { options: [{ label: "标准模式", value: "0" }] },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "cascader",\r\n    field: "orgId",\r\n    title: "来源部门",\r\n    $dict: "org",\r\n    props: {\r\n      props: {\r\n        checkStrictly: false,\r\n        emitPath: false,\r\n      },\r\n      placeholder: "请选择来源部门",\r\n      clearable: true,\r\n    },\r\n    class: "w-full",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "el-input",\r\n    field: "description",\r\n    title: "服务描述",\r\n    props: { type: "textarea", maxlength: 500, rows: 4, showWordLimit: true },\r\n    col: { span: 24 },\r\n  },\r\n]);\r\n\r\nconst formRules = computed(() => {\r\n  if (currentMode.value === "view") return FormUtils.transFormText(rawRules);\r\n  return rawRules;\r\n});\r\n\r\n// ==================== 参数信息 v-table 配置 ====================\r\nconst paramsTableOptions = reactive({\r\n  importConfig: { mode: "covering" },\r\n  toolbarConfig: {\r\n    buttons: [],\r\n    tools: [],\r\n  },\r\n  columns: [\r\n    { type: "seq", width: 60, title: "序号" },\r\n    { field: "req", title: "入参", width: 80, slots: { default: "req", header: "req_header" } },\r\n    { field: "res", title: "出参", width: 80, slots: { default: "res", header: "res_header" } },\r\n    {\r\n      field: "columnName",\r\n      title: "参数名称",\r\n      editRender: { name: "VxeInput", props: { placeholder: "请输入参数名称" } },\r\n    },\r\n    {\r\n      field: "columnComment",\r\n      title: "参数说明",\r\n      editRender: { name: "VxeInput", props: { placeholder: "请输入参数说明", maxlength: 500 } },\r\n    },\r\n    {\r\n      field: "dataType",\r\n      title: "参数类型",\r\n      width: 150,\r\n      editRender: {\r\n        name: "ElSelect",\r\n        options: useDictStore().getDictItems("tableColType"),\r\n        props: { placeholder: "请选择参数类型" },\r\n      },\r\n    },\r\n    {\r\n      field: "columnOperator",\r\n      title: "请求运算符",\r\n      width: 150,\r\n      slots: { default: "columnOperator" },\r\n    },\r\n    {\r\n      field: "requestOperator",\r\n      title: "请求操作符",\r\n      width: 150,\r\n      slots: { default: "requestOperator" },\r\n    },\r\n    { field: "required", title: "必填属性", width: 150, slots: { default: "required" } },\r\n  ],\r\n});\r\n\r\n// ==================== 入参/出参 Checkbox 逻辑 ====================\r\nconst allReq = ref(false);\r\nconst allRes = ref(false);\r\nconst indeterminateReq = ref(false);\r\nconst indeterminateRes = ref(false);\r\n\r\nconst updateCheckAllState = () => {\r\n  const data = paramsRef.value?.getData() || [];\r\n  allReq.value = data.length > 0 && data.every((i: any) => i.req === 1);\r\n  allRes.value = data.length > 0 && data.every((i: any) => i.res === 1);\r\n  indeterminateReq.value = data.some((i: any) => i.req === 1) && !allReq.value;\r\n  indeterminateRes.value = data.some((i: any) => i.res === 1) && !allRes.value;\r\n};\r\n\r\nconst handleReqChange = (row: any, val: CheckboxValueType) => {\r\n  row.req = val ? 1 : 0;\r\n  if (row.req === 1) {\r\n    row.columnOperator = row.columnOperator || "and";\r\n    row.requestOperator = row.requestOperator || "=";\r\n    row.paramPosition = row.paramPosition || "body";\r\n    row.status = row.status || "required";\r\n  } else {\r\n    row.columnOperator = "";\r\n    row.requestOperator = "";\r\n    if (row.res !== 1) {\r\n      row.paramPosition = "";\r\n      row.status = undefined;\r\n    }\r\n  }\r\n  updateCheckAllState();\r\n};\r\n\r\nconst handleResChange = (row: any, val: CheckboxValueType) => {\r\n  row.res = val ? 1 : 0;\r\n  if (row.req !== 1 && row.res === 1) {\r\n    row.paramPosition = "";\r\n    row.status = undefined;\r\n  } else if (row.req === 1) {\r\n    row.paramPosition = row.paramPosition || "body";\r\n    row.status = row.status || "required";\r\n  }\r\n  updateCheckAllState();\r\n};\r\n\r\nconst handleAllReqChange = (val: CheckboxValueType) => {\r\n  allReq.value = !!val;\r\n  const data = paramsRef.value?.getData() || [];\r\n  const updated = data.map((row: any) => ({\r\n    ...row,\r\n    req: val ? 1 : 0,\r\n    columnOperator: val ? row.columnOperator || "and" : "",\r\n    requestOperator: val ? row.requestOperator || "=" : "",\r\n    paramPosition: !val && row.res === 1 ? "" : row.paramPosition || "body",\r\n    status: val ? row.status || "required" : row.status,\r\n  }));\r\n  paramsRef.value?.setData(updated);\r\n  updateCheckAllState();\r\n};\r\n\r\nconst handleAllResChange = (val: CheckboxValueType) => {\r\n  allRes.value = !!val;\r\n  const data = paramsRef.value?.getData() || [];\r\n  const updated = data.map((row: any) => ({\r\n    ...row,\r\n    res: val ? 1 : 0,\r\n    paramPosition: !val ? row.paramPosition || "body" : "",\r\n  }));\r\n  paramsRef.value?.setData(updated);\r\n  updateCheckAllState();\r\n};\r\n\r\nlet _normalizing = false;\r\nconst handleParamsDataChange = () => {\r\n  if (_normalizing) return;\r\n  const data = paramsRef.value?.getData() || [];\r\n  if (data.length === 0) {\r\n    allReq.value = false;\r\n    allRes.value = false;\r\n    indeterminateReq.value = false;\r\n    indeterminateRes.value = false;\r\n    return;\r\n  }\r\n  const needsFix = data.some(\r\n    (row: any) => typeof row.req === "boolean" || typeof row.res === "boolean"\r\n  );\r\n  if (needsFix) {\r\n    _normalizing = true;\r\n    paramsRef.value?.setData(\r\n      data.map((row: any) => ({\r\n        ...row,\r\n        req: row.req === true || row.req === 1 ? 1 : 0,\r\n        res: row.res === true || row.res === 1 ? 1 : 0,\r\n      }))\r\n    );\r\n    _normalizing = false;\r\n  }\r\n  updateCheckAllState();\r\n};\r\n\r\n// ==================== 数据源联动 ====================\r\nconst fetchTables = async (id: string) => {\r\n  formRef.value?.setValue({ tableName: "" });\r\n  if (!id) {\r\n    tableOptions.value = [];\r\n    updateTableOptions();\r\n    return;\r\n  }\r\n  try {\r\n    const res = await $common.get(`/dataassets/metadata/tables?dbId=${id}`);\r\n    const data = Array.isArray(res) ? res : res?.data || [];\r\n    tableOptions.value = data.map((item: any) => ({\r\n      label: item.tableName,\r\n      value: item.tableName,\r\n      ...item,\r\n    }));\r\n    updateTableOptions();\r\n  } catch {\r\n    tableOptions.value = [];\r\n    ElMessage.error("获取表列表失败");\r\n  }\r\n};\r\n\r\nconst updateTableOptions = () => {\r\n  formRef.value?.updateFieldOptions("tableName", tableOptions.value);\r\n};\r\n\r\nconst fetchColumns = async (tableName: string) => {\r\n  if (!tableName) {\r\n    paramsRef.value?.setData([]);\r\n    updateCheckAllState();\r\n    return;\r\n  }\r\n  try {\r\n    const id = tableOptions.value.find((item: any) => item.tableName === tableName)?.tid || "";\r\n    const res = await $common.get(`/dataassets/metadata/columns?tid=${id}`);\r\n    const data = Array.isArray(res) ? res : res?.data || [];\r\n    paramsRef.value?.setData(data);\r\n    updateCheckAllState();\r\n  } catch {\r\n    paramsRef.value?.setData([]);\r\n    updateCheckAllState();\r\n    ElMessage.error("获取列列表失败");\r\n  }\r\n};\r\n\r\n// ==================== 快照（取消时恢复） ====================\r\nlet _dataSnapshot: Record<string, any> = {};\r\n\r\n// ==================== 编辑状态控制（仅 detail 场景） ====================\r\nconst startEdit = () => {\r\n  // 更新非表单数据的快照（params、status、responseExample、tableOptions）\r\n  _dataSnapshot.paramsData = paramsRef.value?.getData() || [];\r\n  // _dataSnapshot.statusData = statusRef.value?.getData() || [];\r\n  // _dataSnapshot.responseExample = responseExample.value;\r\n  _dataSnapshot.tableOptions = [...tableOptions.value];\r\n  // formData 保持 setFormData 初始化时的原始数据，不从 view 模式 getFormData 获取\r\n  // （view 模式 form-text 组件返回的数据可能不完整）\r\n\r\n  isEditing.value = true;\r\n  nextTick(() => {\r\n    if (_dataSnapshot.formData && Object.keys(_dataSnapshot.formData).length > 0) {\r\n      formRef.value?.setValue(_dataSnapshot.formData);\r\n    }\r\n    updateTableOptions();\r\n  });\r\n};\r\n\r\nconst handleCancel = () => {\r\n  isEditing.value = false;\r\n  nextTick(() => {\r\n    // 恢复表选项\r\n    tableOptions.value = _dataSnapshot.tableOptions || [];\r\n    updateTableOptions();\r\n    // 恢复表单\r\n    if (_dataSnapshot.formData) formRef.value?.setValue(_dataSnapshot.formData);\r\n    paramsRef.value?.setData(_dataSnapshot.paramsData || []);\r\n    // statusRef.value?.setData(_dataSnapshot.statusData || []);\r\n    // responseExample.value = _dataSnapshot.responseExample || "";\r\n    updateCheckAllState();\r\n  });\r\n};\r\n\r\n// ==================== 保存（modal 和 detail 共用） ====================\r\n\r\n/** 生成 3-10 位随机字母+数字作为 publishAddress */\r\nconst generatePublishAddress = (): string => {\r\n  const len = Math.floor(Math.random() * 8) + 3; // 3~10\r\n  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";\r\n  return Array.from({ length: len }, () => chars[Math.floor(Math.random() * chars.length)]).join(\r\n    ""\r\n  );\r\n};\r\n\r\n/** req/res 组合值 → parameters 字符串 */\r\nconst toParameters = (req: number, res: number): string => {\r\n  if (req === 1 && res === 0) return "0";\r\n  if (req === 0 && res === 1) return "1";\r\n  if (req === 1 && res === 1) return "1,0";\r\n  return "";\r\n};\r\n\r\n/** parameters 字符串 → req/res */\r\nconst fromParameters = (params: string | undefined): { req: number; res: number } => {\r\n  if (!params || params.trim() === "") return { req: 0, res: 0 };\r\n  const set = params.split(",").map((s) => s.trim());\r\n  return {\r\n    req: set.includes("0") ? 1 : 0,\r\n    res: set.includes("1") ? 1 : 0,\r\n  };\r\n};\r\n\r\nconst handleSave = async (): Promise<boolean> => {\r\n  try {\r\n    saveLoading.value = true;\r\n    const valid = await validate();\r\n    if (!valid) {\r\n      ElMessage.warning("请检查表单填写是否完整");\r\n      return false;\r\n    }\r\n    const formData = (await formRef.value?.getFormData()) || {};\r\n    const paramList = paramsRef.value?.getData() || [];\r\n    // const statusList = statusRef.value?.getData() || [];\r\n    // const responseExampleStr = responseExample.value || "";\r\n\r\n    // 获取选中表的注释信息\r\n    const selectedTable = tableOptions.value.find(\r\n      (item: any) => item.tableName === formData.tableName\r\n    );\r\n\r\n    // 构建数据源信息（保持原逻辑）\r\n    const sourceList =\r\n      useDictStore()\r\n        .getDictItems("db")\r\n        .filter((item: any) => item.tid === formData.dataSourceId) || [];\r\n\r\n    // 按新 API 结构组装请求体\r\n    await $common.post("/v1/gateway/service/buildApi", {\r\n      extendInfo: {\r\n        catalogId: formData.catalogId,\r\n        orgId: formData.orgId,\r\n        description: formData.description || "",\r\n      },\r\n      serviceInfo: {\r\n        name: formData.serviceName,\r\n        dataSourceId: formData.dataSourceId,\r\n        operationType: formData.operationType,\r\n        tableComment: "",\r\n        publishAddress: generatePublishAddress(),\r\n        tableName: formData.tableName,\r\n        tableNames: [formData.tableName].filter(Boolean),\r\n        model: formData.model || "0",\r\n      },\r\n      serviceParameters: paramList.map((row: any) => ({\r\n        tableName: formData.tableName,\r\n        // paramType: row.paramType ?? row.dataType ?? "0",\r\n        paramType: 0,\r\n        aliasName: row.columnComment || "",\r\n        paramName: row.columnName || "",\r\n        operator: row.requestOperator || "=",\r\n        joiner: row.columnOperator || "and",\r\n        position: "0",\r\n        parameters: toParameters(row.req, row.res),\r\n        required: row.required === 1,\r\n        description: row.columnComment || "",\r\n      })),\r\n      dataSourcesAll:\r\n        sourceList.map((item: any) => ({\r\n          id: item.tid,\r\n          dataSourceAlias: item.label,\r\n          dataSourceName: item.dbName,\r\n          dataSourceType: item.dbType,\r\n          hostName: item.host,\r\n          port: item.port,\r\n          userName: item.username,\r\n          password: item.password,\r\n          databaseInstanceName: item.dbName,\r\n          isDefault: 0,\r\n          description: item.description || "",\r\n          status: 0,\r\n        })) || [],\r\n      serviceTableMappings: [],\r\n      serviceTables: selectedTable\r\n        ? [\r\n            {\r\n              tableName: selectedTable.tableName,\r\n              tableComment: "",\r\n              tableDetail: "",\r\n              tableRows: "",\r\n            },\r\n          ]\r\n        : [],\r\n      dataSourceConnectAttribute: [],\r\n      serviceRule: {},\r\n      // _api_build_statusList: statusList,\r\n      // _api_responseExample: responseExampleStr,\r\n    });\r\n\r\n    if (props.context === "detail") {\r\n      isEditing.value = false;\r\n      _dataSnapshot = {\r\n        formData: { ...formData },\r\n        paramsData: [...paramList],\r\n        // statusData: [...statusList],\r\n        // responseExample: responseExampleStr,\r\n        tableOptions: [...tableOptions.value],\r\n      };\r\n    }\r\n\r\n    emit("saved", formData);\r\n    ElMessage.success(props.context === "detail" ? "保存成功" : "服务构建成功");\r\n    return true;\r\n  } catch (error) {\r\n    console.error("保存失败:", error);\r\n    ElMessage.error("保存失败，请重试");\r\n    return false;\r\n  } finally {\r\n    saveLoading.value = false;\r\n  }\r\n};\r\n\r\n// ==================== 数据填充（适配新 API 详情出参结构） ====================\r\nconst setFormData = (data: Record<string, any>) => {\r\n  console.log("setFormData", data);\r\n  if (!data || !Object.keys(data).length) return;\r\n  nextTick(async () => {\r\n    // ---- 表单字段回填：从嵌套结构中提取 ----\r\n    const serviceInfo: any = data.serviceInfo || {};\r\n    const extendInfo: any = data.extendInfo || {};\r\n\r\n    formRef.value?.setValue({\r\n      serviceName: serviceInfo.name || "",\r\n      catalogId: extendInfo.catalogId || "",\r\n      dataSourceId: serviceInfo.dataSourceId || "",\r\n      tableName: serviceInfo.tableName || "",\r\n      operationType: serviceInfo.operationType || "",\r\n      model: serviceInfo.model ?? "0",\r\n      description: data.description || "",\r\n    });\r\n\r\n    // ---- 响应示例（已注释）----\r\n    // if (data.responseExample !== undefined) {\r\n    //   responseExample.value = data.responseExample;\r\n    // } else if (data._api_responseExample !== undefined) {\r\n    //   responseExample.value = data._api_responseExample;\r\n    // }\r\n\r\n    // ---- 状态码（已注释）----\r\n    // if (data.statusList) statusRef.value?.setData(data.statusList);\r\n    // else if (data._api_build_statusList) statusRef.value?.setData(data._api_build_statusList);\r\n\r\n    // ---- 参数列表：service_parameters → paramList（反向映射） ----\r\n    const rawParams: any[] = data.service_parameters || data.paramList || [];\r\n    if (rawParams.length > 0) {\r\n      const convertedParams = rawParams.map((p: any) => {\r\n        const { req, res } = fromParameters(p.parameters);\r\n        return {\r\n          columnName: p.paramName || "",\r\n          columnComment: p.aliasName || p.description || "",\r\n          dataType: p.paramType ?? "0",\r\n          req,\r\n          res,\r\n          requestOperator: p.operator || "=",\r\n          columnOperator: p.joiner || "and",\r\n          required: p.required ? 1 : 0,\r\n          // 保留原始数据以便后续使用\r\n          ...p,\r\n        };\r\n      });\r\n      paramsRef.value?.setData(convertedParams);\r\n    }\r\n\r\n    // ---- 数据源→表名联动 ----\r\n    if (serviceInfo.dataSourceId) await fetchTables(serviceInfo.dataSourceId);\r\n    updateCheckAllState();\r\n\r\n    _dataSnapshot = {\r\n      formData: { ...data },\r\n      paramsData: rawParams.length > 0 ? rawParams : [],\r\n      // statusData: data.statusList || data._api_build_statusList || [],\r\n      // responseExample: data.responseExample || data._api_responseExample || responseExample.value,\r\n      tableOptions: [...tableOptions.value],\r\n    };\r\n  });\r\n};\r\n\r\nwatch(\r\n  () => props.data,\r\n  () => {\r\n    nextTick(() => setFormData(props.data));\r\n  },\r\n  { immediate: true, deep: true }\r\n);\r\n\r\n// ==================== Validate ====================\r\nconst validate = async (): Promise<boolean> => {\r\n  try {\r\n    const paramsValid = await paramsRef.value?.validate();\r\n    // const statusValid = await statusRef.value?.validate();\r\n    const formValid = await formRef.value?.validate();\r\n    // return paramsValid !== false && statusValid !== false && formValid !== false;\r\n    return paramsValid !== false && formValid !== false;\r\n  } catch {\r\n    return false;\r\n  }\r\n};\r\n\r\n// ==================== Expose ====================\r\ndefineExpose({\r\n  getFormData: async () => (await formRef.value?.getFormData()) || {},\r\n  getParamsData: () => paramsRef.value?.getData() || [],\r\n  // getStatusData: () => statusRef.value?.getData() || [],\r\n  // getResponseExample: () => responseExample.value || "",\r\n  validate,\r\n  setFormData,\r\n  handleSave,\r\n  reset: () => {\r\n    formRef.value?.resetFields();\r\n    tableOptions.value = [];\r\n    // responseExample.value = "";\r\n    // statusRef.value?.reset();\r\n    paramsRef.value?.setData([]);\r\n    updateCheckAllState();\r\n  },\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.api-build-content {\r\n  .data-sources-table {\r\n    padding: 10px 0;\r\n  }\r\n  .api-status {\r\n    position: relative;\r\n    .vxe-grid--toolbar-wrapper {\r\n      position: absolute;\r\n      right: 0;\r\n      top: -39px;\r\n    }\r\n  }\r\n  .api-params-table {\r\n    min-height: 200px;\r\n    position: relative;\r\n    .vxe-grid--toolbar-wrapper {\r\n      position: absolute;\r\n      right: 0;\r\n      top: -39px;\r\n    }\r\n  }\r\n  .header-checkbox {\r\n    height: 40px;\r\n    color: #587aa8;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\nconst _hoisted_1 = {\n  class: "api-build-content"\n};\nconst _hoisted_2 = {\n  key: 0\n};\nconst _hoisted_3 = {\n  key: 1,\n  class: "text-gray-400"\n};\nconst _hoisted_4 = {\n  key: 1,\n  class: "text-gray-400"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst ElMessage = ___magic__import__(\'element-plus\', \'ElMessage\');\nconst useDictStore = ___magic__import__(\'@/store\', \'useDictStore\');\n// import ServiceStatusTable from "./ServiceStatusTable.vue";\n\nconst __sfc__ = _defineComponent({\n  __name: \'bd9a1f874cfb6dd2f89072c6403c9260\',\n  props: {\n    context: {\n      type: String,\n      required: true,\n      default: "detail"\n    },\n    data: {\n      type: Object,\n      required: false,\n      default: () => ({})\n    }\n  },\n  emits: ["saved"],\n  setup(__props, {\n    expose: __expose,\n    emit: __emit\n  }) {\n    const props = __props;\n    const emit = __emit;\n\n    // ==================== 编辑状态（仅 detail 场景） ====================\n    const isEditing = ref(props.context === "modal");\n    const saveLoading = ref(false);\n    const currentMode = computed(() => {\n      if (props.context === "modal") return "edit";\n      return isEditing.value ? "edit" : "view";\n    });\n\n    // ==================== Refs ====================\n    const formRef = ref();\n    const paramsRef = ref();\n    // const statusRef = ref();\n    // const responseExample = ref("");\n    const tableOptions = ref([]);\n\n    // ==================== 表单配置（双规则集：fixJson 预处理 → view=transFormText, edit=rawRules） ====================\n    const rawRules = FormUtils.fixJson([{\n      type: "UTitle",\n      props: {\n        name: "基本要素"\n      }\n    }, {\n      type: "input",\n      title: "服务名称",\n      field: "serviceName",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "dict-select",\n      title: "服务目录",\n      field: "catalogId",\n      props: {\n        placeholder: "请选择服务目录",\n        options: "catalog",\n        filterable: true,\n        filters: {\n          assetStatus: "2"\n        }\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "dict-select",\n      title: "数据源",\n      field: "dataSourceId",\n      props: {\n        options: "db",\n        placeholder: "请选择所属数据源",\n        clearable: true,\n        filters: {\n          orgId: "$user.orgId"\n        }\n      },\n      on: {\n        change: value => {\n          fetchTables(value);\n        }\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "表名",\n      field: "tableName",\n      col: {\n        span: 12\n      },\n      props: {\n        filterable: true,\n        clearable: true,\n        placeholder: "请先选择数据源",\n        options: tableOptions.value\n      },\n      on: {\n        change: value => {\n          fetchColumns(value);\n        }\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "操作类型",\n      field: "operationType",\n      col: {\n        span: 12\n      },\n      props: {\n        options: [{\n          label: "查询(select)",\n          value: "0"\n        }, {\n          label: "新增(insert)",\n          value: "1"\n        }, {\n          label: "修改(update)",\n          value: "2"\n        }, {\n          label: "删除(delete)",\n          value: "3"\n        }]\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "数据模式",\n      field: "model",\n      col: {\n        span: 12\n      },\n      props: {\n        options: [{\n          label: "标准模式",\n          value: "0"\n        }]\n      },\n      $required: true\n    }, {\n      type: "cascader",\n      field: "orgId",\n      title: "来源部门",\n      $dict: "org",\n      props: {\n        props: {\n          checkStrictly: false,\n          emitPath: false\n        },\n        placeholder: "请选择来源部门",\n        clearable: true\n      },\n      class: "w-full",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "el-input",\n      field: "description",\n      title: "服务描述",\n      props: {\n        type: "textarea",\n        maxlength: 500,\n        rows: 4,\n        showWordLimit: true\n      },\n      col: {\n        span: 24\n      }\n    }]);\n    const formRules = computed(() => {\n      if (currentMode.value === "view") return FormUtils.transFormText(rawRules);\n      return rawRules;\n    });\n\n    // ==================== 参数信息 v-table 配置 ====================\n    const paramsTableOptions = reactive({\n      importConfig: {\n        mode: "covering"\n      },\n      toolbarConfig: {\n        buttons: [],\n        tools: []\n      },\n      columns: [{\n        type: "seq",\n        width: 60,\n        title: "序号"\n      }, {\n        field: "req",\n        title: "入参",\n        width: 80,\n        slots: {\n          default: "req",\n          header: "req_header"\n        }\n      }, {\n        field: "res",\n        title: "出参",\n        width: 80,\n        slots: {\n          default: "res",\n          header: "res_header"\n        }\n      }, {\n        field: "columnName",\n        title: "参数名称",\n        editRender: {\n          name: "VxeInput",\n          props: {\n            placeholder: "请输入参数名称"\n          }\n        }\n      }, {\n        field: "columnComment",\n        title: "参数说明",\n        editRender: {\n          name: "VxeInput",\n          props: {\n            placeholder: "请输入参数说明",\n            maxlength: 500\n          }\n        }\n      }, {\n        field: "dataType",\n        title: "参数类型",\n        width: 150,\n        editRender: {\n          name: "ElSelect",\n          options: useDictStore().getDictItems("tableColType"),\n          props: {\n            placeholder: "请选择参数类型"\n          }\n        }\n      }, {\n        field: "columnOperator",\n        title: "请求运算符",\n        width: 150,\n        slots: {\n          default: "columnOperator"\n        }\n      }, {\n        field: "requestOperator",\n        title: "请求操作符",\n        width: 150,\n        slots: {\n          default: "requestOperator"\n        }\n      }, {\n        field: "required",\n        title: "必填属性",\n        width: 150,\n        slots: {\n          default: "required"\n        }\n      }]\n    });\n\n    // ==================== 入参/出参 Checkbox 逻辑 ====================\n    const allReq = ref(false);\n    const allRes = ref(false);\n    const indeterminateReq = ref(false);\n    const indeterminateRes = ref(false);\n    const updateCheckAllState = () => {\n      const data = paramsRef.value?.getData() || [];\n      allReq.value = data.length > 0 && data.every(i => i.req === 1);\n      allRes.value = data.length > 0 && data.every(i => i.res === 1);\n      indeterminateReq.value = data.some(i => i.req === 1) && !allReq.value;\n      indeterminateRes.value = data.some(i => i.res === 1) && !allRes.value;\n    };\n    const handleReqChange = (row, val) => {\n      row.req = val ? 1 : 0;\n      if (row.req === 1) {\n        row.columnOperator = row.columnOperator || "and";\n        row.requestOperator = row.requestOperator || "=";\n        row.paramPosition = row.paramPosition || "body";\n        row.status = row.status || "required";\n      } else {\n        row.columnOperator = "";\n        row.requestOperator = "";\n        if (row.res !== 1) {\n          row.paramPosition = "";\n          row.status = undefined;\n        }\n      }\n      updateCheckAllState();\n    };\n    const handleResChange = (row, val) => {\n      row.res = val ? 1 : 0;\n      if (row.req !== 1 && row.res === 1) {\n        row.paramPosition = "";\n        row.status = undefined;\n      } else if (row.req === 1) {\n        row.paramPosition = row.paramPosition || "body";\n        row.status = row.status || "required";\n      }\n      updateCheckAllState();\n    };\n    const handleAllReqChange = val => {\n      allReq.value = !!val;\n      const data = paramsRef.value?.getData() || [];\n      const updated = data.map(row => ({\n        ...row,\n        req: val ? 1 : 0,\n        columnOperator: val ? row.columnOperator || "and" : "",\n        requestOperator: val ? row.requestOperator || "=" : "",\n        paramPosition: !val && row.res === 1 ? "" : row.paramPosition || "body",\n        status: val ? row.status || "required" : row.status\n      }));\n      paramsRef.value?.setData(updated);\n      updateCheckAllState();\n    };\n    const handleAllResChange = val => {\n      allRes.value = !!val;\n      const data = paramsRef.value?.getData() || [];\n      const updated = data.map(row => ({\n        ...row,\n        res: val ? 1 : 0,\n        paramPosition: !val ? row.paramPosition || "body" : ""\n      }));\n      paramsRef.value?.setData(updated);\n      updateCheckAllState();\n    };\n    let _normalizing = false;\n    const handleParamsDataChange = () => {\n      if (_normalizing) return;\n      const data = paramsRef.value?.getData() || [];\n      if (data.length === 0) {\n        allReq.value = false;\n        allRes.value = false;\n        indeterminateReq.value = false;\n        indeterminateRes.value = false;\n        return;\n      }\n      const needsFix = data.some(row => typeof row.req === "boolean" || typeof row.res === "boolean");\n      if (needsFix) {\n        _normalizing = true;\n        paramsRef.value?.setData(data.map(row => ({\n          ...row,\n          req: row.req === true || row.req === 1 ? 1 : 0,\n          res: row.res === true || row.res === 1 ? 1 : 0\n        })));\n        _normalizing = false;\n      }\n      updateCheckAllState();\n    };\n\n    // ==================== 数据源联动 ====================\n    const fetchTables = async id => {\n      formRef.value?.setValue({\n        tableName: ""\n      });\n      if (!id) {\n        tableOptions.value = [];\n        updateTableOptions();\n        return;\n      }\n      try {\n        const res = await $common.get(`/dataassets/metadata/tables?dbId=${id}`);\n        const data = Array.isArray(res) ? res : res?.data || [];\n        tableOptions.value = data.map(item => ({\n          label: item.tableName,\n          value: item.tableName,\n          ...item\n        }));\n        updateTableOptions();\n      } catch {\n        tableOptions.value = [];\n        ElMessage.error("获取表列表失败");\n      }\n    };\n    const updateTableOptions = () => {\n      formRef.value?.updateFieldOptions("tableName", tableOptions.value);\n    };\n    const fetchColumns = async tableName => {\n      if (!tableName) {\n        paramsRef.value?.setData([]);\n        updateCheckAllState();\n        return;\n      }\n      try {\n        const id = tableOptions.value.find(item => item.tableName === tableName)?.tid || "";\n        const res = await $common.get(`/dataassets/metadata/columns?tid=${id}`);\n        const data = Array.isArray(res) ? res : res?.data || [];\n        paramsRef.value?.setData(data);\n        updateCheckAllState();\n      } catch {\n        paramsRef.value?.setData([]);\n        updateCheckAllState();\n        ElMessage.error("获取列列表失败");\n      }\n    };\n\n    // ==================== 快照（取消时恢复） ====================\n    let _dataSnapshot = {};\n\n    // ==================== 编辑状态控制（仅 detail 场景） ====================\n    const startEdit = () => {\n      // 更新非表单数据的快照（params、status、responseExample、tableOptions）\n      _dataSnapshot.paramsData = paramsRef.value?.getData() || [];\n      // _dataSnapshot.statusData = statusRef.value?.getData() || [];\n      // _dataSnapshot.responseExample = responseExample.value;\n      _dataSnapshot.tableOptions = [...tableOptions.value];\n      // formData 保持 setFormData 初始化时的原始数据，不从 view 模式 getFormData 获取\n      // （view 模式 form-text 组件返回的数据可能不完整）\n\n      isEditing.value = true;\n      nextTick(() => {\n        if (_dataSnapshot.formData && Object.keys(_dataSnapshot.formData).length > 0) {\n          formRef.value?.setValue(_dataSnapshot.formData);\n        }\n        updateTableOptions();\n      });\n    };\n    const handleCancel = () => {\n      isEditing.value = false;\n      nextTick(() => {\n        // 恢复表选项\n        tableOptions.value = _dataSnapshot.tableOptions || [];\n        updateTableOptions();\n        // 恢复表单\n        if (_dataSnapshot.formData) formRef.value?.setValue(_dataSnapshot.formData);\n        paramsRef.value?.setData(_dataSnapshot.paramsData || []);\n        // statusRef.value?.setData(_dataSnapshot.statusData || []);\n        // responseExample.value = _dataSnapshot.responseExample || "";\n        updateCheckAllState();\n      });\n    };\n\n    // ==================== 保存（modal 和 detail 共用） ====================\n\n    /** 生成 3-10 位随机字母+数字作为 publishAddress */\n    const generatePublishAddress = () => {\n      const len = Math.floor(Math.random() * 8) + 3; // 3~10\n      const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";\n      return Array.from({\n        length: len\n      }, () => chars[Math.floor(Math.random() * chars.length)]).join("");\n    };\n\n    /** req/res 组合值 → parameters 字符串 */\n    const toParameters = (req, res) => {\n      if (req === 1 && res === 0) return "0";\n      if (req === 0 && res === 1) return "1";\n      if (req === 1 && res === 1) return "1,0";\n      return "";\n    };\n\n    /** parameters 字符串 → req/res */\n    const fromParameters = params => {\n      if (!params || params.trim() === "") return {\n        req: 0,\n        res: 0\n      };\n      const set = params.split(",").map(s => s.trim());\n      return {\n        req: set.includes("0") ? 1 : 0,\n        res: set.includes("1") ? 1 : 0\n      };\n    };\n    const handleSave = async () => {\n      try {\n        saveLoading.value = true;\n        const valid = await validate();\n        if (!valid) {\n          ElMessage.warning("请检查表单填写是否完整");\n          return false;\n        }\n        const formData = (await formRef.value?.getFormData()) || {};\n        const paramList = paramsRef.value?.getData() || [];\n        // const statusList = statusRef.value?.getData() || [];\n        // const responseExampleStr = responseExample.value || "";\n\n        // 获取选中表的注释信息\n        const selectedTable = tableOptions.value.find(item => item.tableName === formData.tableName);\n\n        // 构建数据源信息（保持原逻辑）\n        const sourceList = useDictStore().getDictItems("db").filter(item => item.tid === formData.dataSourceId) || [];\n\n        // 按新 API 结构组装请求体\n        await $common.post("/v1/gateway/service/buildApi", {\n          extendInfo: {\n            catalogId: formData.catalogId,\n            orgId: formData.orgId,\n            description: formData.description || ""\n          },\n          serviceInfo: {\n            name: formData.serviceName,\n            dataSourceId: formData.dataSourceId,\n            operationType: formData.operationType,\n            tableComment: "",\n            publishAddress: generatePublishAddress()