: [{\n          code: "append_edit",\n          icon: "vxe-icon-add",\n          name: "新增参数",\n          status: "primary",\n          mode: "text"\n        }],\n        tools: []\n      },\n      columns: [{\n        field: "statusCode",\n        title: "状态码",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "statusDesc",\n        title: "状态描述",\n        editRender: {\n          name: "VxeInput"\n        }\n      }],\n      editRules: {\n        statusCode: [{\n          required: true,\n          content: "状态码不能为空",\n          trigger: "blur"\n        }],\n        statusDesc: [{\n          required: true,\n          content: "状态描述不能为空",\n          trigger: "blur"\n        }]\n      }\n    });\n    const defaultStatusCodes = [{\n      statusCode: "200",\n      statusDesc: "请求成功"\n    }, {\n      statusCode: "400",\n      statusDesc: "非法请求"\n    }, {\n      statusCode: "500",\n      statusDesc: "服务器错误"\n    }];\n    const defaultParams = [{\n      paramName: "id",\n      paramDesc: "主键ID",\n      paramType: "string",\n      paramPosition: "query",\n      instance: "",\n      req: true,\n      res: false,\n      status: "required",\n      paramComment: ""\n    }\n    // { paramName: "pageNum", paramDesc: "页码", paramType: "integer", paramPosition: "query", instance: "", req: false, res: false, status: "optional", paramComment: "" },\n    // { paramName: "pageSize", paramDesc: "每页条数", paramType: "integer", paramPosition: "query", instance: "", req: false, res: false, status: "optional", paramComment: "" },\n    // { paramName: "total", paramDesc: "总记录数", paramType: "integer", paramPosition: "", instance: "", req: false, res: true, status: "optional", paramComment: "" },\n    // { paramName: "list", paramDesc: "数据列表", paramType: "array", paramPosition: "", instance: "", req: false, res: true, status: "optional", paramComment: "" },\n    ];\n    const addDataSource = () => {\n      dataSources.value.push({\n        id: $common.uuid(),\n        data_source_alias: \'\',\n        data_source_name: \'\',\n        data_source_type: \'mysql\',\n        host_name: \'\',\n        port: \'3306\',\n        user_name: \'\',\n        password: \'\',\n        database_instance_name: \'\',\n        is_default: 0,\n        description: \'\',\n        status: 0\n      });\n    };\n    const removeDataSource = row => {\n      const idx = dataSources.value.indexOf(row);\n      if (idx > -1) {\n        dataSources.value.splice(idx, 1);\n      }\n    };\n    const handleSave = async () => {\n      try {\n        saveLoading.value = true;\n        const paramsValid = await paramsRef.value?.validate();\n        const statusValid = await statusRef.value?.validate();\n        const formValid = await formRef.value?.validate();\n        if (paramsValid && statusValid && formValid) {\n          await new Promise(resolve => setTimeout(resolve, 1000));\n          const paramsData = paramsRef.value?.getData();\n          const statusData = statusRef.value?.getData();\n          const formData = await formRef.value?.getFormData();\n          buildFormData.value = formData;\n          console.log("保存参数", paramsData);\n          console.log("保存状态码", statusData);\n          console.log("保存表单数据", formData);\n          isSaved.value = true;\n          ElMessage.success("保存成功");\n        }\n      } catch (error) {\n        console.error("保存失败:", error);\n        ElMessage.error("保存失败，请重试");\n      } finally {\n        saveLoading.value = false;\n      }\n    };\n    const handleRegister = async () => {\n      if (!isSaved.value) {\n        ElMessage.warning("请先保存配置信息");\n        return;\n      }\n      try {\n        taskLoading.value = true;\n        const formData = await formRef.value?.getFormData();\n        const paramList = paramsRef.value?.getData() || params.value;\n        const statusList = statusRef.value?.getData() || defaultStatusCodes;\n        const res = await $request({\n          url: \'/v1/gateway/service/buildApi\',\n          method: \'post\',\n          data: {\n            // 直接将所有表单信息平铺提交，由后端 assembleBuildApiRequest 封装\n            serviceName: formData.serviceName || \'\',\n            dataSourceId: formData.dataSourceId || \'\',\n            catalogId: formData.catalogId || \'\',\n            operationType: formData.operationType || \'0\',\n            tableName: formData.tableName || \'\',\n            model: formData.model || \'0\',\n            description: formData.description || \'\',\n            requestMethod: formData.requestMethod || \'\',\n            _paramList: paramList,\n            _statusList: statusList,\n            data_sources_all: dataSources.value.map(ds => ({\n              ...ds,\n              id: ds.id || $common.uuid()\n            })),\n            responseExample: responseExample.value || \'\'\n          }\n        });\n        console.log(\'服务构建成功，响应:\', res);\n        isFinish.value = true;\n        ElMessage.success(\'服务构建成功\');\n      } catch (error) {\n        console.error(\'构建服务失败:\', error);\n        ElMessage.error(\'构建服务失败，请重试\');\n      } finally {\n        taskLoading.value = false;\n      }\n    };\n    const onCancel = () => {\n      emit("close", false);\n      open.value = false;\n    };\n    const handleToSee = () => {\n      open.value = false;\n      emit("close", false);\n    };\n\n    // 初始化 mock 数据\n    params.value = defaultParams;\n\n    // 获取服务目录列表（下拉框数据）\n    const fetchCatalogs = async () => {\n      try {\n        const res = await $common.post("/dataassets/manage/assets/page", {\n          sortField: "updatedTime",\n          sortDir: "desc",\n          pageNum: 1,\n          pageSize: 1000,\n          conditions: [{\n            field: "assetType",\n            value: "catalog",\n            type: "match"\n          }]\n        });\n        const data = res.data || res;\n        const options = (data.list || []).map(item => ({\n          label: item.catalogName,\n          value: item.tid\n        }));\n        catalogOptions.value = options;\n        // 替换 formRules 触发重新渲染，使 select 的 options 生效\n        formRules.value = formRules.value.map(rule => rule.field === "catalogId" ? {\n          ...rule,\n          props: {\n            ...rule.props,\n            options\n          }\n        } : rule);\n      } catch (error) {\n        console.error("获取服务目录列表失败:", error);\n      }\n    };\n\n    // 弹窗打开时加载服务目录列表\n    watch(open, val => {\n      catalogOptions.value = [];\n      if (val) {\n        fetchCatalogs();\n        isSaved.value = false;\n      }\n    }, {\n      immediate: true\n    });\n    return (_ctx, _cache) => {\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_el_radio = _resolveComponent("el-radio");\n      const _component_el_radio_group = _resolveComponent("el-radio-group");\n      const _component_json_form = _resolveComponent("json-form");\n      const _component_api_params = _resolveComponent("api-params");\n      const _component_vxe_column = _resolveComponent("vxe-column");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_vxe_table = _resolveComponent("vxe-table");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_code_editor = _resolveComponent("code-editor");\n      const _component_v_table = _resolveComponent("v-table");\n      const _component_el_scrollbar = _resolveComponent("el-scrollbar");\n      const _component_icon = _resolveComponent("icon");\n      const _component_task_finish = _resolveComponent("task-finish");\n      const _component_el_dialog = _resolveComponent("el-dialog");\n      return _openBlock(), _createBlock(_component_el_dialog, {\n        modelValue: open.value,\n        "onUpdate:modelValue": _cache[1] || (_cache[1] = $event => open.value = $event),\n        "destroy-on-close": "",\n        fullscreen: "",\n        class: "api-modal__container",\n        "header-class": "p-0!",\n        onClose: onCancel\n  