INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2017170975672045568','2014615745029804032','api-modal','<template>\r\n  <el-dialog\r\n    v-model="open"\r\n    destroy-on-close\r\n    fullscreen\r\n    class="api-modal__container"\r\n    header-class="p-0!"\r\n    @close="onCancel"\r\n  >\r\n    <div class="flex flex-col h-full">\r\n      <div class="api-modal__header">\r\n        <div class="api-modal__title">创建服务</div>\r\n      </div>\r\n      <template v-if="!isFinish">\r\n        <div class="api-modal__body" style="grid-template-columns: 20% 80%">\r\n          <div class="left-panel h-full">\r\n            <left-select\r\n              v-model="currentCategoryDid"\r\n              :list="categoryList"\r\n              :title="\'服务目录列表\'"\r\n              :icon="\'api\'"\r\n              :field-name="{ title: \'catalogName\' }"\r\n              @select="handleSelect"\r\n              @delete="handleDelete"\r\n              @add="handleAdd"\r\n            />\r\n          </div>\r\n          <el-scrollbar>\r\n            <div class="pr-5 flex flex-col h-full">\r\n              <json-form ref="formRef" bordered :rules="formRules">\r\n                <template #field-requestMethod="scope">\r\n                  <el-radio-group\r\n                    v-model="scope.model.value"\r\n                    @change="\r\n                      (val: string | number | boolean | undefined) => handleChange(String(val))\r\n                    "\r\n                  >\r\n                    <el-radio\r\n                      v-for="item in scope.rule.props.options"\r\n                      :key="item.value"\r\n                      :label="item.value"\r\n                      :style="{\r\n                        borderColor: `${item.color}40`,\r\n                        backgroundColor: `${item.color}20`,\r\n                        width: \'90px\',\r\n                        height: \'26px\',\r\n                        marginRight: \'10px\',\r\n                        fontSize: \'12px\',\r\n                        borderRadius: \'4px\',\r\n                      }"\r\n                      border\r\n                    >\r\n                      {{ item.label }}\r\n                    </el-radio>\r\n                  </el-radio-group>\r\n                </template>\r\n              </json-form>\r\n              <u-title v-if="apiType === \'build\'" name="SQL脚本" class="mt-4" />\r\n              <code-editor\r\n                v-if="apiType === \'build\'"\r\n                v-model="scriptCode"\r\n                :lang="\'sql\'"\r\n                style="height: 300px"\r\n              ></code-editor>\r\n              <api-params ref="paramsRef" :params="params"></api-params>\r\n              <u-title name="响应示例" class="mt-4" />\r\n              <code-editor\r\n                v-model="responseExample"\r\n                :lang="\'sql\'"\r\n                style="height: 300px"\r\n              ></code-editor>\r\n              <u-title name="状态码" class="mt-4" />\r\n              <v-table\r\n                ref="statusRef"\r\n                class="api-status"\r\n                :options="statusTableOptions"\r\n                show-operation\r\n              ></v-table>\r\n            </div>\r\n          </el-scrollbar>\r\n        </div>\r\n        <div class="api-modal__footer">\r\n          <el-button @click="onCancel">取消</el-button>\r\n          <el-button type="primary" plain :disabled="saveLoading" @click="handleSave">\r\n            <icon :icon="\'save\'" class="mr-2" />\r\n            保存\r\n          </el-button>\r\n          <el-button type="primary" :disabled="taskLoading" @click="handleRegister">\r\n            <icon :icon="\'check-circle\'" class="mr-2" />\r\n            提交注册\r\n          </el-button>\r\n        </div>\r\n      </template>\r\n      <task-finish\r\n        v-else\r\n        :name="(currentCategoryInfo as any).catalogName"\r\n        :time="(currentCategoryInfo as any).latestUpdateTime"\r\n        :code="\'TSK_INGEST_20250102_001\'"\r\n        @to-see="handleToSee"\r\n      ></task-finish>\r\n    </div>\r\n    <category-drawer\r\n      v-model:visible="drawerVisible"\r\n      :selected-data="selectedData"\r\n      @confirm="handleDrawerConfirm"\r\n      @close="handleDrawerClose"\r\n    />\r\n  </el-dialog>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, nextTick, computed, reactive } from \'vue\'\r\nimport { FormUtils } from "@/utils/form";\r\nimport { cloneDeep } from "lodash-es";\r\nimport { ElMessage } from "element-plus";\r\nimport { useDictStore } from "@/store";\r\n// import apiParams from "./api-params.vue";\r\n// import categoryDrawer from "./category-drawer.vue";\r\n\r\nconst shareTypeOptions = useDictStore().getDictItems("shareType");\r\nconst levelOptions = useDictStore().getDictItems("dataSecurityLevel");\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", value: boolean): void;\r\n  (e: "close", value: boolean): void;\r\n}>();\r\n\r\nconst props = defineProps({\r\n  modelValue: Boolean,\r\n  categoryData: Array,\r\n  apiType: String, // register:登记API build:服务构建\r\n});\r\nconst formRules = ref<any[]>([]);\r\nconst formRef = ref();\r\nconst paramsRef = ref();\r\nconst categoryList = ref<any[]>([]);\r\nconst currentCategoryDid = ref("");\r\nconst currentCategoryInfo = ref<any>({});\r\nconst scriptCode = ref("");\r\nconst responseExample = ref("");\r\nconst params = ref<any[]>([]);\r\nconst catalogOptions = ref<any[]>([]);\r\nconst drawerVisible = ref(false);\r\nconst selectedData = ref<any[]>([]); // 选中的目录数据\r\nconst saveLoading = ref(false);\r\nconst taskLoading = ref(false);\r\nconst isFinish = ref(false);\r\nconst isSaved = ref(false);\r\nconst dictStore = useDictStore();\r\nconst open = computed({\r\n  get: () => props.modelValue,\r\n  set: (val: boolean) => emit("update:modelValue", val),\r\n});\r\n\r\nformRules.value = FormUtils.fixJson([\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "基本要素",\r\n    },\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "服务目录名称",\r\n    field: "catalogId",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      filterable: true,\r\n      clearable: true,\r\n      options: [],\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "DictSelect",\r\n    title: "数据所属领域",\r\n    field: "dataDomain",\r\n    props: {\r\n      options: "dataDomain",\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "cascader",\r\n    title: "数据所属分类",\r\n    field: "dataCategory",\r\n    props: {\r\n      options: dictStore.getDictItems("dataCategory"),\r\n    },\r\n    class: "w-full",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "DictSelect",\r\n    title: "来源事项名称",\r\n    field: "sourceBusinessName",\r\n    props: {\r\n      options: "sourceBusinessName",\r\n      fitInputWidth: true,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "来源事项业务项",\r\n    field: "sourceBusinessItem",\r\n    col: {\r\n      span: 12,\r\n    },\r\n  },\r\n  {\r\n    type: "DictSelect",\r\n    title: "数据所在层级",\r\n    field: "dataLevel",\r\n    props: {\r\n      options: "dataLevel",\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "el-input",\r\n    field: "assetDesc",\r\n    title: "服务摘要",\r\n    props: {\r\n      type: "textarea",\r\n      placeholder: "请简要描述数据服务的核心内容、覆盖范围及核心用途",\r\n      maxlength: 500,\r\n      rows: 4,\r\n      showWordLimit: true,\r\n    },\r\n    col: {\r\n      span: 24,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "技术要素",\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "服务名",\r\n    field: "serviceName",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "返回类型",\r\n    field: "returnType",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      options: [\r\n        {\r\n          label: "JSON",\r\n          value: "JSON",\r\n        },\r\n        {\r\n          label: "XML",\r\n          value: "XML",\r\n        },\r\n      ],\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "接入协议",\r\n    field: "accessProtocol",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      type: "select",\r\n      options: [\r\n        {\r\n          label: "HTTP",\r\n          value: "HTTP",\r\n        },\r\n        {\r\n          label: "HTTPS",\r\n          value: "HTTPS",\r\n        },\r\n      ],\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "DictSelect",\r\n    title: "更新周期",\r\n    field: "dataUpdateFreq",\r\n    props: {\r\n      options: "dataUpdateFreq",\r\n      placeholder: "请选择更新周期",\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "接口地址",\r\n    field: "apiUrl",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      placeholder: "请输入接口地址，例如 http://172.16.45.4/s/",\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "请求地址",\r\n    field: "requestUrl",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "fieldComponent",\r\n    title: "请求方式",\r\n    field: "requestMethod",\r\n    props: {\r\n      type: "radio",\r\n      options: [\r\n        {\r\n          label: "GET",\r\n          value: "GET",\r\n          color: "#fa8c16",\r\n        },\r\n        {\r\n          label: "POST",\r\n          value: "POST",\r\n          color: "#1677ff",\r\n        },\r\n        {\r\n          label: "PUT",\r\n          value: "PUT",\r\n          color: "#389e0d",\r\n        },\r\n        {\r\n          label: "DELETE",\r\n          value: "DELETE",\r\n          color: "#9254de",\r\n        },\r\n      ],\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "共享类型",\r\n    field: "shareType",\r\n    col: {\r\n      span: 12,\r\n    },\r\n    props: {\r\n      options: shareTypeOptions,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    title: "数据分级",\r\n    field: "dataLevel",\r\n    props: {\r\n      type: "select",\r\n      options: levelOptions,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "input",\r\n    field: "description",\r\n    title: "服务描述",\r\n    props: {\r\n      type: "textarea",\r\n      maxlength: 255,\r\n      rows: 4,\r\n    },\r\n    col: {\r\n      span: 24,\r\n    },\r\n  },\r\n]);\r\nconst statusRef = ref();\r\nconst statusTableOptions = reactive({\r\n  rowConfig: {\r\n    drag: true,\r\n  },\r\n  toolbarConfig: {\r\n    buttons: [\r\n      {\r\n        code: "append_edit", // 底部新增\r\n        icon: "vxe-icon-add",\r\n        name: "新增参数",\r\n        status: "primary",\r\n        mode: "text",\r\n      },\r\n    ],\r\n    tools: [],\r\n  },\r\n  columns: [\r\n    {\r\n      field: "statusCode", // 可编辑-插槽渲染\r\n      title: "状态码",\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "statusDesc", // 可编辑-插槽渲染\r\n      title: "状态描述",\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    statusCode: [{ required: true, content: "状态码不能为空", trigger: "blur" }],\r\n    statusDesc: [{ required: true, content: "状态描述不能为空", trigger: "blur" }],\r\n  },\r\n});\r\nconst statusCodeData = ref([\r\n  {\r\n    statusCode: "500",\r\n    statusDesc: "服务器错误",\r\n  },\r\n  {\r\n    statusCode: "400",\r\n    statusDesc: "非法请求",\r\n  },\r\n  {\r\n    statusCode: "401",\r\n    statusDesc: "认证失败",\r\n  },\r\n  {\r\n    statusCode: "403",\r\n    statusDesc: "禁止，没有权限操作",\r\n  },\r\n  {\r\n    statusCode: "404",\r\n    statusDesc: "找不到",\r\n  },\r\n  {\r\n    statusCode: "200",\r\n    statusDesc: "请求成功",\r\n  },\r\n]); // mock\r\nconst paramsData = ref([\r\n  {\r\n    paramName: "ID",\r\n    paramDesc: "ID",\r\n    paramType: "string",\r\n    paramPosition: "query",\r\n    instance: "",\r\n    req: true,\r\n    res: false,\r\n    status: "required",\r\n    paramComment: "",\r\n  },\r\n  {\r\n    paramName: "userId",\r\n    paramDesc: "用户ID",\r\n    paramType: "string",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "required",\r\n    paramComment: "广电用户唯一标识",\r\n  },\r\n  {\r\n    paramName: "deviceId",\r\n    paramDesc: "设备ID",\r\n    paramType: "string",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "required",\r\n    paramComment: "机顶盒或智能终端设备ID",\r\n  },\r\n  {\r\n    paramName: "channelId",\r\n    paramDesc: "频道ID",\r\n    paramType: "string",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "optional",\r\n    paramComment: "电视频道ID",\r\n  },\r\n  {\r\n    paramName: "startTime",\r\n    paramDesc: "开始时间",\r\n    paramType: "datetime",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "required",\r\n    paramComment: "查询开始时间",\r\n  },\r\n  {\r\n    paramName: "endTime",\r\n    paramDesc: "结束时间",\r\n    paramType: "datetime",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "required",\r\n    paramComment: "查询结束时间",\r\n  },\r\n  {\r\n    paramName: "watchDuration",\r\n    paramDesc: "观看时长",\r\n    paramType: "integer",\r\n    paramPosition: "",\r\n    instance: "",\r\n    req: false,\r\n    res: true,\r\n    status: "optional",\r\n    paramComment: "用户观看时长(分钟)",\r\n  },\r\n]);\r\n\r\nconst handleChange = (val: string) => {\r\n  formRef.value?.setValue({\r\n    requestMethod: val,\r\n  });\r\n};\r\n\r\nconst updateCategoryList = (data: any[]) => {\r\n  if (!data.length) return;\r\n  currentCategoryDid.value = data[0]?.id;\r\n  currentCategoryInfo.value = data[0];\r\n  categoryList.value = data.map((item) => ({\r\n    ...item,\r\n    did: item.id,\r\n  }));\r\n  nextTick(() => {\r\n    updateRightData(data[0]);\r\n  });\r\n};\r\n\r\nconst defaultFormData = {\r\n  catalogId: \'\',\r\n  catalogName: \'广电用户收视行为分析服务\',\r\n  apiUrl: \'http://172.16.45.4/s/\',\r\n  dataDomain: \'TVOD\',\r\n  dataCategory: [],\r\n  sourceBusinessName: \'广电运营支撑系统\',\r\n  sourceBusinessItem: \'用户收视行为分析\',\r\n  dataLevel: \'province\',\r\n  assetDesc: \'提供广电用户收视行为数据的查询与分析服务，覆盖用户观看记录、频道偏好、观看时长等多维度数据，支持运营决策与用户画像构建。\',\r\n  serviceName: \'user-watch-behavior-service\',\r\n  returnType: \'JSON\',\r\n  accessProtocol: \'HTTP\',\r\n  dataUpdateFreq: \'daily\',\r\n  requestUrl: \'/api/v1/user/watch/behavior\',\r\n  requestMethod: \'GET\',\r\n  shareType: \'有条件共享\',\r\n  description: \'本服务提供广电用户收视行为数据的标准化查询接口，支持按用户ID、设备ID、时间范围等维度进行数据检索，返回用户观看频道、时长及设备类型等详细信息。\',\r\n};\r\n\r\nconst updateRightData = (item: any) => {\r\n  // 合并默认 mock 数据与目录项数据，确保表单始终有展示内容\r\n  formRef.value?.setValue({\r\n    ...defaultFormData,\r\n    ...item,\r\n  });\r\n  statusRef.value?.setData(statusCodeData.value);\r\n  params.value = paramsData.value;\r\n\r\n  const fields = paramsData.value.map((param) => param.paramName).join(", ");\r\n  const tableName = item?.resources || \'user_watch_behavior\';\r\n  scriptCode.value = `select ${fields}\\nfrom ${tableName}\\nwhere userId = :userId\\n  and startTime >= :startTime\\n  and endTime <= :endTime\\norder by startTime desc;`;\r\n  responseExample.value = JSON.stringify(\r\n    {\r\n      code: 200,\r\n      message: "success",\r\n      data: [\r\n        {\r\n          userId: "U20240001",\r\n          deviceId: "STB20240001",\r\n          channelId: "CCTV-1",\r\n          startTime: "2024-01-15 19:30:00",\r\n          endTime: "2024-01-15 20:15:00",\r\n          watchDuration: 45,\r\n        },\r\n        {\r\n          userId: "U20240001",\r\n          deviceId: "STB20240002",\r\n          channelId: "CCTV-13",\r\n          startTime: "2024-01-15 20:20:00",\r\n          endTime: "2024-01-15 21:00:00",\r\n          watchDuration: 40,\r\n        },\r\n      ],\r\n    },\r\n    null,\r\n    2\r\n  );\r\n};\r\nconst resetRinghtData = () => {\r\n  formRef.value?.resetFields();\r\n  // paramsRef.value?.clear();\r\n  // statusRef.value?.clear();\r\n  params.value = [];\r\n  scriptCode.value = "";\r\n  responseExample.value = "";\r\n};\r\nconst onCancel = (): void => {\r\n  emit("close", false);\r\n  open.value = false;\r\n};\r\n\r\nconst handleSelect = (item: any) => {\r\n  currentCategoryDid.value = item.did;\r\n  currentCategoryInfo.value = item;\r\n  resetRinghtData();\r\n  updateRightData(item);\r\n};\r\n\r\nconst handleAdd = () => {\r\n  if (props.apiType === "build") {\r\n    drawerVisible.value = true;\r\n    selectedData.value = cloneDeep(categoryList.value);\r\n  } else {\r\n    categoryList.value.push({ did: $common.uuid() });\r\n  }\r\n};\r\n\r\nconst handleDelete = (item: any) => {\r\n  // 检查是否是最后一个目录\r\n  if (categoryList.value.length <= 1) {\r\n    ElMessage.warning("不能删除最后一个目录");\r\n    return;\r\n  }\r\n\r\n  // 执行删除操作\r\n  const index = categoryList.value.findIndex((category) => category.did === item.did);\r\n  if (index > -1) {\r\n    categoryList.value.splice(index, 1);\r\n    // 如果删除的是当前选中的目录，切换到第一个目录\r\n    if (currentCategoryDid.value === item.did && categoryList.value.length > 0) {\r\n      handleSelect(categoryList.value[0]);\r\n    }\r\n    ElMessage.success("目录删除成功");\r\n  }\r\n};\r\n\r\nconst handleDrawerConfirm = (data: any) => {\r\n  updateCategoryList(data);\r\n  drawerVisible.value = false;\r\n};\r\n\r\nconst handleDrawerClose = () => {\r\n  drawerVisible.value = false;\r\n};\r\n\r\nwatch(\r\n  open,\r\n  (val: boolean) => {\r\n    categoryList.value = [];\r\n    catalogOptions.value = [];\r\n    if (val) {\r\n      fetchCatalogs();\r\n      isSaved.value = false;\r\n      if (props.apiType === "build") {\r\n        updateCategoryList(props.categoryData || []);\r\n      } else {\r\n        handleAdd();\r\n      }\r\n    }\r\n  },\r\n  { immediate: true }\r\n);\r\n\r\nwatch(\r\n  () => props.categoryData,\r\n  (newData) => {\r\n    if (newData?.length) {\r\n      updateCategoryList(newData);\r\n    }\r\n  },\r\n  {\r\n    deep: true,\r\n  }\r\n);\r\n\r\n// 获取服务目录列表（下拉框数据）\r\nconst fetchCatalogs = async () => {\r\n  try {\r\n    const res = await $common.post("/dataassets/manage/assets/page", {\r\n      sortField: "updatedTime",\r\n      sortDir: "desc",\r\n      pageNum: 1,\r\n      pageSize: 1000,\r\n      conditions: [{ field: "assetType", value: "catalog", type: "match" }],\r\n    });\r\n    const data = res.data || res;\r\n    const options = (data.list || []).map((item: any) => ({\r\n      label: item.catalogName,\r\n      value: item.tid,\r\n    }));\r\n    catalogOptions.value = options;\r\n    // 替换 formRules 触发重新渲染，使 select 的 options 生效\r\n    formRules.value = formRules.value.map((rule: any) =>\r\n      rule.field === "catalogId"\r\n        ? { ...rule, props: { ...rule.props, options } }\r\n        : rule\r\n    );\r\n  } catch (error) {\r\n    console.error("获取服务目录列表失败:", error);\r\n  }\r\n};\r\n\r\n// 保存表单数据\r\nconst handleSave = async () => {\r\n  try {\r\n    // 设置加载状态\r\n    saveLoading.value = true;\r\n\r\n    // 验证所有表单\r\n    const paramsValid = await paramsRef.value?.validate();\r\n    const statusValid = await statusRef.value?.validate();\r\n    const formValid = await formRef.value?.validate();\r\n\r\n    if (paramsValid && statusValid && formValid) {\r\n      // 模拟接口加载过程\r\n      await new Promise((resolve) => setTimeout(resolve, 1000));\r\n\r\n      // 获取数据\r\n      const paramsData = paramsRef.value?.getData();\r\n      const statusData = statusRef.value?.getData();\r\n      const formData = await formRef.value?.getFormData();\r\n      categoryList.value.forEach((item) => {\r\n        if (item.did === currentCategoryDid.value) {\r\n          item.tid = currentCategoryDid.value;\r\n        }\r\n      });\r\n      console.log("保存参数", paramsData);\r\n      console.log("保存状态码", statusData);\r\n      console.log("保存表单数据", formData);\r\n\r\n      // 保存成功后设置保存状态为 true\r\n      isSaved.value = true;\r\n      // 显示成功提示\r\n      ElMessage.success("保存成功");\r\n    }\r\n  } catch (error) {\r\n    console.error("保存失败:", error);\r\n    ElMessage.error("保存失败，请重试");\r\n  } finally {\r\n    // 关闭加载状态\r\n    saveLoading.value = false;\r\n  }\r\n};\r\n\r\nconst handleRegister = async () => {\r\n  // 检查是否已经保存\r\n  if (!isSaved.value) {\r\n    ElMessage.warning("请先保存配置信息");\r\n    return;\r\n  }\r\n\r\n  try {\r\n    taskLoading.value = true;\r\n\r\n    // 获取表单、参数及状态码数据（原样传递到后端，由后端组装最终JSON）\r\n    const formData = await formRef.value?.getFormData();\r\n    const paramList = paramsRef.value?.getData() || params.value;\r\n    const statusList = statusRef.value?.getData() || statusCodeData.value;\r\n\r\n    const res = await $request({\r\n      url: \'/v1/gateway/service/save\',\r\n      method: \'post\',\r\n      data: {\r\n        // 表单字段作为独立 KV 传递\r\n        ...formData,\r\n        // 额外参数\r\n        groupId: currentCategoryDid.value || \'\',\r\n        _paramList: JSON.stringify(paramList),\r\n        _statusList: JSON.stringify(statusList),\r\n        _responseExample: responseExample.value || \'\',\r\n        _scriptCode: scriptCode.value || \'\',\r\n      },\r\n    });\r\n    console.log(\'创建服务成功，响应:\', res);\r\n    isFinish.value = true;\r\n    ElMessage.success(\'服务注册成功\');\r\n  } catch (error) {\r\n    console.error(\'注册服务失败:\', error);\r\n    ElMessage.error(\'注册服务失败，请重试\');\r\n  } finally {\r\n    taskLoading.value = false;\r\n  }\r\n};\r\n\r\n// 处理前往查看\r\nconst handleToSee = () => {\r\n  // 关闭模态框\r\n  open.value = false;\r\n  emit("close", false);\r\n};\r\n</script>\r\n\r\n<style lang="scss">\r\n.api-modal__container {\r\n  padding: 0;\r\n  .el-dialog__body {\r\n    height: 100%;\r\n    padding: 0;\r\n  }\r\n  .el-dialog__header {\r\n    padding: 0;\r\n  }\r\n  .api-modal__header {\r\n    display: grid;\r\n    flex-shrink: 0;\r\n    grid-template-columns: 15% 1fr 15%;\r\n    align-items: center;\r\n    height: 45px;\r\n    padding: 0 15px 0 20px;\r\n    background-color: #fff;\r\n    border-bottom: 1px solid #ebeef5;\r\n  }\r\n  .api-modal__title {\r\n    font-family: Arial, sans-serif;\r\n    font-size: 16px;\r\n    font-weight: 700;\r\n    color: #000000e0;\r\n  }\r\n  .api-modal__footer {\r\n    display: flex;\r\n    justify-content: center;\r\n    padding: 10px 24px;\r\n    text-align: right;\r\n    background-color: #fff;\r\n    border-top: 1px solid #ebeef5;\r\n  }\r\n  .api-modal__body {\r\n    height: calc(100% - 45px - 53px);\r\n    display: grid;\r\n    grid-template-columns: 20% 80%;\r\n    .el-radio__label {\r\n      font-size: 12px;\r\n    }\r\n  }\r\n  .api-status {\r\n    position: relative;\r\n    .vxe-grid--toolbar-wrapper {\r\n      position: absolute;\r\n      right: 0;\r\n      top: -39px;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\nconst _hoisted_1 = {\n  class: "flex flex-col h-full"\n};\nconst _hoisted_2 = {\n  class: "api-modal__body",\n  style: {\n    "grid-template-columns": "20% 80%"\n  }\n};\nconst _hoisted_3 = {\n  class: "left-panel h-full"\n};\nconst _hoisted_4 = {\n  class: "pr-5 flex flex-col h-full"\n};\nconst _hoisted_5 = {\n  class: "api-modal__footer"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst cloneDeep = ___magic__import__(\'lodash-es\', \'cloneDeep\');\nconst ElMessage = ___magic__import__(\'element-plus\', \'ElMessage\');\nconst useDictStore = ___magic__import__(\'@/store\', \'useDictStore\');\n// import apiParams from "./api-params.vue";\n// import categoryDrawer from "./category-drawer.vue";\n\nconst __sfc__ = _defineComponent({\n  __name: \'d7197530c1cd1bf6158819891f86f3d1\',\n  props: {\n    modelValue: Boolean,\n    categoryData: Array,\n    apiType: String // register:登记API build:服务构建\n  },\n  emits: ["update:modelValue", "close"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const shareTypeOptions = useDictStore().getDictItems("shareType");\n    const levelOptions = useDictStore().getDictItems("dataSecurityLevel");\n    const emit = __emit;\n    const props = __props;\n    const formRules = ref([]);\n    const formRef = ref();\n    const paramsRef = ref();\n    const categoryList = ref([]);\n    const currentCategoryDid = ref("");\n    const currentCategoryInfo = ref({});\n    const scriptCode = ref("");\n    const responseExample = ref("");\n    const params = ref([]);\n    const catalogOptions = ref([]);\n    const drawerVisible = ref(false);\n    const selectedData = ref([]); // 选中的目录数据\n    const saveLoading = ref(false);\n    const taskLoading = ref(false);\n    const isFinish = ref(false);\n    const isSaved = ref(false);\n    const dictStore = useDictStore();\n    const open = computed({\n      get: () => props.modelValue,\n      set: val => emit("update:modelValue", val)\n    });\n    formRules.value = FormUtils.fixJson([{\n      type: "UTitle",\n      props: {\n        name: "基本要素"\n      }\n    }, {\n      type: "select",\n      title: "服务目录名称",\n      field: "catalogId",\n      col: {\n        span: 12\n      },\n      props: {\n        filterable: true,\n        clearable: true,\n        options: []\n      },\n      $required: true\n    }, {\n      type: "DictSelect",\n      title: "数据所属领域",\n      field: "dataDomain",\n      props: {\n        options: "dataDomain"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "cascader",\n      title: "数据所属分类",\n      field: "dataCategory",\n      props: {\n        options: dictStore.getDictItems("dataCategory")\n      },\n      class: "w-full",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "DictSelect",\n      title: "来源事项名称",\n      field: "sourceBusinessName",\n      props: {\n        options: "sourceBusinessName",\n        fitInputWidth: true\n      },\n      col: {\n        span: 12\n      }\n    }, {\n      type: "input",\n      title: "来源事项业务项",\n      field: "sourceBusinessItem",\n      col: {\n        span: 12\n      }\n    }, {\n      type: "DictSelect",\n      title: "数据所在层级",\n      field: "dataLevel",\n      props: {\n        options: "dataLevel"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "el-input",\n      field: "assetDesc",\n      title: "服务摘要",\n      props: {\n        type: "textarea",\n        placeholder: "请简要描述数据服务的核心内容、覆盖范围及核心用途",\n        maxlength: 500,\n        rows: 4,\n        showWordLimit: true\n      },\n      col: {\n        span: 24\n      },\n      $required: true\n    }, {\n      type: "UTitle",\n      props: {\n        name: "技术要素"\n      }\n    }, {\n      type: "input",\n      title: "服务名",\n      field: "serviceName",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "返回类型",\n      field: "returnType",\n      col: {\n        span: 12\n      },\n      props: {\n        options: [{\n          label: "JSON",\n          value: "JSON"\n        }, {\n          label: "XML",\n          value: "XML"\n        }]\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "接入协议",\n      field: "accessProtocol",\n      col: {\n        span: 12\n      },\n      props: {\n        type: "select",\n        options: [{\n          label: "HTTP",\n          value: "HTTP"\n        }, {\n          label: "HTTPS",\n          value: "HTTPS"\n        }]\n      },\n      $required: true\n    }, {\n      type: "DictSelect",\n      title: "更新周期",\n      field: "dataUpdateFreq",\n      props: {\n        options: "dataUpdateFreq",\n        placeholder: "请选择更新周期"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "接口地址",\n      field: "apiUrl",\n      col: {\n        span: 12\n      },\n      props: {\n        placeholder: "请输入接口地址，例如 http://172.16.45.4/s/"\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "请求地址",\n      field: "requestUrl",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "fieldComponent",\n      title: "请求方式",\n      field: "requestMethod",\n      props: {\n        type: "radio",\n        options: [{\n          label: "GET",\n          value: "GET",\n          color: "#fa8c16"\n        }, {\n          label: "POST",\n          value: "POST",\n          color: "#1677ff"\n        }, {\n          label: "PUT",\n          value: "PUT",\n          color: "#389e0d"\n        }, {\n          label: "DELETE",\n          value: "DELETE",\n          color: "#9254de"\n        }]\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "共享类型",\n      field: "shareType",\n      col: {\n        span: 12\n      },\n      props: {\n        options: shareTypeOptions\n      },\n      $required: true\n    }, {\n      type: "select",\n      title: "数据分级",\n      field: "dataLevel",\n      props: {\n        type: "select",\n        options: levelOptions\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      field: "description",\n      title: "服务描述",\n      props: {\n        type: "textarea",\n        maxlength: 255,\n        rows: 4\n      },\n      col: {\n        span: 24\n      }\n    }]);\n    const statusRef = ref();\n    const statusTableOptions = reactive({\n      rowConfig: {\n        drag: true\n      },\n      toolbarConfig: {\n        buttons: [{\n          code: "append_edit",\n          // 底部新增\n          icon: "vxe-icon-add",\n          name: "新增参数",\n          status: "primary",\n          mode: "text"\n        }],\n        tools: []\n      },\n      columns: [{\n        field: "statusCode",\n        // 可编辑-插槽渲染\n        title: "状态码",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "statusDesc",\n        // 可编辑-插槽渲染\n        title: "状态描述",\n        editRender: {\n          name: "VxeInput"\n        }\n      }],\n      editRules: {\n        statusCode: [{\n          required: true,\n          content: "状态码不能为空",\n          trigger: "blur"\n        }],\n        statusDesc: [{\n          required: true,\n          content: "状态描述不能为空",\n          trigger: "blur"\n        }]\n      }\n    });\n    const statusCodeData = ref([{\n      statusCode: "500",\n      statusDesc: "服务器错误"\n    }, {\n      statusCode: "400",\n      statusDesc: "非法请求"\n    }, {\n      statusCode: "401",\n      statusDesc: "认证失败"\n    }, {\n      statusCode: "403",\n      statusDesc: "禁止，没有权限操作"\n    }, {\n      statusCode: "404",\n      statusDesc: "找不到"\n    }, {\n      statusCode: "200",\n      statusDesc: "请求成功"\n    }]); // mock\n    const paramsData = ref([{\n      paramName: "ID",\n      paramDesc: "ID",\n      paramType: "string",\n      paramPosition: "query",\n      instance: "",\n      req: true,\n      res: false,\n      status: "required",\n      paramComment: ""\n    }, {\n      paramName: "userId",\n      paramDesc: "用户ID",\n      paramType: "string",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "required",\n      paramComment: "广电用户唯一标识"\n    }, {\n      paramName: "deviceId",\n      paramDesc: "设备ID",\n      paramType: "string",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "required",\n      paramComment: "机顶盒或智能终端设备ID"\n    }, {\n      paramName: "channelId",\n      paramDesc: "频道ID",\n      paramType: "string",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "optional",\n      paramComment: "电视频道ID"\n    }, {\n      paramName: "startTime",\n      paramDesc: "开始时间",\n      paramType: "datetime",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "required",\n      paramComment: "查询开始时间"\n    }, {\n      paramName: "endTime",\n      paramDesc: "结束时间",\n      paramType: "datetime",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "required",\n      paramComment: "查询结束时间"\n    }, {\n      paramName: "watchDuration",\n      paramDesc: "观看时长",\n      paramType: "integer",\n      paramPosition: "",\n      instance: "",\n      req: false,\n      res: true,\n      status: "optional",\n      paramComment: "用户观看时长(分钟)"\n    }]);\n    const handleChange = val => {\n      formRef.value?.setValue({\n        requestMethod: val\n      });\n    };\n    const updateCategoryList = data => {\n      if (!data.length) return;\n      currentCategoryDid.value = data[0]?.id;\n      currentCategoryInfo.value = data[0];\n      categoryList.value = data.map(item => ({\n        ...item,\n        did: item.id\n      }));\n      nextTick(() => {\n        updateRightData(data[0]);\n      });\n    };\n    const defaultFormData = {\n      catalogId: \'\',\n      catalogName: \'广电用户收视行为分析服务\',\n      apiUrl: \'http://172.16.45.4/s/\',\n      dataDomain: \'TVOD\',\n      dataCategory: [],\n      sourceBusinessName: \'广电运营支撑系统\',\n      sourceBusinessItem: \'用户收视行为分析\',\n      dataLevel: \'province\',\n      assetDesc: \'提供广电用户收视行为数据的查询与分析服务，覆盖用户观看记录、频道偏好、观看时长等多维度数据，支持运营决策与用户画像构建。\',\n      serviceName: \'user-watch-behavior-service\',\n      returnType: \'JSON\',\n      accessProtocol: \'HTTP\',\n      dataUpdateFreq: \'daily\',\n      requestUrl: \'/api/v1/user/watch/behavior\',\n      requestMethod: \'GET\',\n      shareType: \'有条件共享\',\n      description: \'本服务提供广电用户收视行为数据的标准化查询接口，支持按用户ID、设备ID、时间范围等维度进行数据检索，返回用户观看频道、时长及设备类型等详细信息。\'\n    };\n    const updateRightData = item => {\n      // 合并默认 mock 数据与目录项数据，确保表单始终有展示内容\n      formRef.value?.setValue({\n        ...defaultFormData,\n        ...item\n      });\n      statusRef.value?.setData(statusCodeData.value);\n      params.value = paramsData.value;\n      const fields = paramsData.value.map(param => param.paramName).join(", ");\n      const tableName = item?.resources || \'user_watch_behavior\';\n      scriptCode.value = `select ${fields}\\nfrom ${tableName}\\nwhere userId = :userId\\n  and startTime >= :startTime\\n  and endTime <= :endTime\\norder by startTime desc;`;\n      responseExample.value = JSON.stringify({\n        code: 200,\n        message: "success",\n        data: [{\n          userId: "U20240001",\n          deviceId: "STB20240001",\n          channelId: "CCTV-1",\n          startTime: "2024-01-15 19:30:00",\n          endTime: "2024-01-15 20:15:00",\n          watchDuration: 45\n        }, {\n          userId: "U20240001",\n          deviceId: "STB20240002",\n          channelId: "CCTV-13",\n          startTime: "2024-01-15 20:20:00",\n          endTime: "2024-01-15 21:00:00",\n          watchDuration: 40\n        }]\n      }, null, 2);\n    };\n    const resetRinghtData = () => {\n      formRef.value?.resetFields();\n      // paramsRef.value?.clear();\n      // statusRef.value?.clear();\n      params.value = [];\n      scriptCode.value = "";\n      responseExample.value = "";\n    };\n    const onCancel = () => {\n      emit("close", false);\n      open.value = false;\n    };\n    const handleSelect = item => {\n      currentCategoryDid.value = item.did;\n      currentCategoryInfo.value = item;\n      resetRinghtData();\n      updateRightData(item);\n    };\n    const handleAdd = () => {\n      if (props.apiType === "build") {\n        drawerVisible.value = true;\n        selectedData.value = cloneDeep(categoryList.value);\n      } else {\n        categoryList.value.push({\n          did: $common.uuid()\n        });\n      }\n    };\n    const handleDelete = item => {\n      // 检查是否是最后一个目录\n      if (categoryList.value.length <= 1) {\n        ElMessage.warning("不能删除最后一个目录");\n        return;\n      }\n\n      // 执行删除操作\n      const index = categoryList.value.findIndex(category => category.did === item.did);\n      if (index > -1) {\n        categoryList.value.splice(index, 1);\n        // 如果删除的是当前选中的目录，切换到第一个目录\n        if (currentCategoryDid.value === item.did && categoryList.value.length > 0) {\n          handleSelect(categoryList.value[0]);\n        }\n        ElMessage.success("目录删除成功");\n      }\n    };\n    const handleDrawerConfirm = data => {\n      updateCategoryList(data);\n      drawerVisible.value = false;\n    };\n    const handleDrawerClose = () => {\n      drawerVisible.value = false;\n    };\n    watch(open, val => {\n      categoryList.value = [];\n      catalogOptions.value = [];\n      if (val) {\n        fetchCatalogs();\n        isSaved.value = false;\n        if (props.apiType === "build") {\n          updateCategoryList(props.categoryData || []);\n        } else {\n          handleAdd();\n        }\n      }\n    }, {\n      immediate: true\n    });\n    watch(() => props.categoryData, newData => {\n      if (newData?.length) {\n        updateCategoryList(newData);\n      }\n    }, {\n      deep: true\n    });\n\n    // 获取服务目录列表（下拉框数据）\n    const fetchCatalogs = async () => {\n      try {\n        const res = await $common.post("/dataassets/manage/assets/page", {\n          sortField: "updatedTime",\n          sortDir: "desc",\n          pageNum: 1,\n          pageSize: 1000,\n          conditions: [{\n            field: "assetType",\n            value: "catalog",\n            type: "match"\n          }]\n        });\n        const data = res.data || res;\n        const options = (data.list || []).map(item => ({\n          label: item.catalogName,\n          value: item.tid\n        }));\n        catalogOptions.value = options;\n        // 替换 formRules 触发重新渲染，使 select 的 options 生效\n        formRules.value = formRules.value.map(rule => rule.field === "catalogId" ? {\n          ...rule,\n          props: {\n            ...rule.props,\n            options\n          }\n        } : rule);\n      } catch (error) {\n        console.error("获取服务目录列表失败:", error);\n      }\n    };\n\n    // 保存表单数据\n    const handleSave = async () => {\n      try {\n        // 设置加载状态\n        saveLoading.value = true;\n\n        // 验证所有表单\n        const paramsValid = await paramsRef.value?.validate();\n        const statusValid = await statusRef.value?.validate();\n        const formValid = await formRef.value?.validate();\n        if (paramsValid && statusValid && formValid) {\n          // 模拟接口加载过程\n          await new Promise(resolve => setTimeout(resolve, 1000));\n\n          // 获取数据\n          const paramsData = paramsRef.value?.getData();\n          const statusData = statusRef.value?.getData();\n          const formData = await formRef.value?.getFormData();\n          categoryList.value.forEach(item => {\n            if (item.did === currentCategoryDid.value) {\n              item.tid = currentCategoryDid.value;\n            }\n          });\n          console.log("保存参数", paramsData);\n          console.log("保存状态码", statusData);\n          console.log("保存表单数据", formData);\n\n          // 保存成功后设置保存状态为 true\n          isSaved.value = true;\n          // 显示成功提示\n          ElMessage.success("保存成功");\n        }\n      } catch (error) {\n        console.error("保存失败:", error);\n        ElMessage.error("保存失败，请重试");\n      } finally {\n        // 关闭加载状态\n        saveLoading.value = false;\n      }\n    };\n    const handleRegister = async () => {\n      // 检查是否已经保存\n      if (!isSaved.value) {\n        ElMessage.warning("请先保存配置信息");\n        return;\n      }\n      try {\n        taskLoading.value = true;\n\n        // 获取表单、参数及状态码数据（原样传递到后端，由后端组装最终JSON）\n        const formData = await formRef.value?.getFormData();\n        const paramList = paramsRef.value?.getData() || params.value;\n        const statusList = statusRef.value?.getData() || statusCodeData.value;\n        const res = await $request({\n          url: \'/v1/gateway/service/save\',\n          method: \'post\',\n          data: {\n            // 表单字段作为独立 KV 传递\n            ...formData,\n            // 额外参数\n            groupId: currentCategoryDid.value || \'\',\n            _paramList: JSON.stringify(paramList),\n            _statusList: JSON.stringify(statusList),\n            _responseExample: responseExample.value || \'\',\n            _scriptCode: scriptCode.value || \'\'\n          }\n        });\n        console.log(\'创建服务成功，响应:\', res);\n        isFinish.value = true;\n        ElMessage.success(\'服务注册成功\');\n      } catch (error) {\n        console.error(\'注册服务失败:\', error);\n        ElMessage.error(\'注册服务失败，请重试\');\n      } finally {\n        taskLoading.value = false;\n      }\n    };\n\n    // 处理前往查看\n    const handleToSee = () => {\n      // 关闭模态框\n      open.value = false;\n      emit("close", false);\n    };\n    return (_ctx, _cache) => {\n      const _component_left_select = _resolveComponent("left-select");\n      const _component_el_radio = _resolveComponent("el-radio");\n      const _component_el_radio_group = _resolveComponent("el-radio-group");\n      const _component_json_form = _resolveComponent("json-form");\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_code_editor = _resolveComponent("code-editor");\n      const _component_api_params = _resolveComponent("api-params");\n      const _component_v_table = _resolveComponent("v-table");\n      const _component_el_scrollbar = _resolveComponent("el-scrollbar");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_icon = _resolveComponent("icon");\n      const _component_task_finish = _resolveComponent("task-finish");\n      const _component_category_drawer = _resolveComponent("category-drawer");\n      const _component_el_dialog = _resolveComponent("el-dialog");\n      return _openBlock(), _createBlock(_component_el_dialog, {\n        modelValue: open.value,\n        "onUpdate:modelValue": _cache[5] || (_cache[5] = $event => open.value = $event),\n        "destroy-on-close": "",\n        fullscreen: "",\n        class: "api-modal__container",\n        "header-class": "p-0!",\n        onClose: onCancel\n      }, {\n        default: _withCtx(() => [_createElementVNode("div", _hoisted_1, [_cache[9] || (_cache[9] = _createElementVNode("div", {\n          class: "api-modal__header"\n        }, [_createElementVNode("div", {\n          class: "api-modal__title"\n        }, "创建服务")], -1 /* CACHED */)), !isFinish.value ? (_ope