_sfc__','.api-modal__container {\n  padding: 0;\n}\n.api-modal__container .el-dialog__body {\n  height: 100%;\n  padding: 0;\n}\n.api-modal__container .el-dialog__header {\n  padding: 0;\n}\n.api-modal__container .api-modal__header {\n  display: grid;\n  flex-shrink: 0;\n  grid-template-columns: 15% 1fr 15%;\n  align-items: center;\n  height: 45px;\n  padding: 0 15px 0 20px;\n  background-color: #fff;\n  border-bottom: 1px solid #ebeef5;\n}\n.api-modal__container .api-modal__title {\n  font-family: Arial, sans-serif;\n  font-size: 16px;\n  font-weight: 700;\n  color: rgba(0, 0, 0, 0.8784313725);\n}\n.api-modal__container .api-modal__footer {\n  display: flex;\n  justify-content: center;\n  padding: 10px 24px;\n  text-align: right;\n  background-color: #fff;\n  border-top: 1px solid #ebeef5;\n}\n.api-modal__container .api-modal__body {\n  height: calc(100% - 45px - 53px);\n  display: grid;\n  grid-template-columns: 20% 80%;\n}\n.api-modal__container .api-modal__body .el-radio__label {\n  font-size: 12px;\n}\n.api-modal__container .api-status {\n  position: relative;\n}\n.api-modal__container .api-status .vxe-grid--toolbar-wrapper {\n  position: absolute;\n  right: 0;\n  top: -39px;\n}','1','api弹窗',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2019225341245599744','2007661287158910976','api-param','<template>\r\n  <div class="api-param card-container flex px-5 pt-5 flex-col">\r\n    <!--  请求参数  -->\r\n    <u-title class="api-param-title" name="请求参数">\r\n      <template #default>\r\n        <a v-if="!editStatus[0]" class="ml-3" @click="handleEdit(0)">\r\n          <Icon icon="edit" class="custom-icon editForm" />\r\n        </a>\r\n        <el-button v-if="editStatus[0]" type="text" class="ml-3" @click="handleCancel(0)">\r\n          取消\r\n        </el-button>\r\n        <el-button v-if="editStatus[0]" type="text" :loading="btnLoading[0]" @click="handleSave(0)">\r\n          保存\r\n        </el-button>\r\n      </template>\r\n      <template #right>\r\n        <el-button v-if="editStatus[0]" size="mini" type="primary" @click="handleAdd(0)">\r\n          新增\r\n        </el-button>\r\n      </template>\r\n    </u-title>\r\n    <v-table\r\n      ref="reqRef"\r\n      :options="reqOptions"\r\n      :editable="editStatus[0]"\r\n      :show-toolbar="false"\r\n      show-operation\r\n      class="api-param-table"\r\n    />\r\n\r\n    <!--  响应参数  -->\r\n    <u-title class="api-param-title" name="响应参数">\r\n      <template #default>\r\n        <a v-if="!editStatus[1]" class="ml-3" @click="handleEdit(1)">\r\n          <Icon icon="edit" class="custom-icon editForm" />\r\n        </a>\r\n        <el-button v-if="editStatus[1]" type="text" class="ml-3" @click="handleCancel(1)">\r\n          取消\r\n        </el-button>\r\n        <el-button v-if="editStatus[1]" type="text" :loading="btnLoading[1]" @click="handleSave(1)">\r\n          保存\r\n        </el-button>\r\n      </template>\r\n      <template #right>\r\n        <el-button v-if="editStatus[1]" size="mini" type="primary" @click="handleAdd(1)">\r\n          新增\r\n        </el-button>\r\n      </template>\r\n    </u-title>\r\n    <v-table\r\n      ref="resRef"\r\n      :options="resOptions"\r\n      :editable="editStatus[1]"\r\n      :show-toolbar="false"\r\n      show-operation\r\n      class="api-param-table"\r\n    />\r\n\r\n    <!--  响应状态码  -->\r\n    <u-title class="api-param-title" name="响应状态码">\r\n      <template #default>\r\n        <a v-if="!editStatus[2]" class="ml-3" @click="handleEdit(2)">\r\n          <Icon icon="edit" class="custom-icon editForm" />\r\n        </a>\r\n        <el-button v-if="editStatus[2]" type="text" class="ml-3" @click="handleCancel(2)">\r\n          取消\r\n        </el-button>\r\n        <el-button v-if="editStatus[2]" type="text" :loading="btnLoading[2]" @click="handleSave(2)">\r\n          保存\r\n        </el-button>\r\n      </template>\r\n      <template #right>\r\n        <el-button v-if="editStatus[2]" size="mini" type="primary" @click="handleAdd(2)">\r\n          新增\r\n        </el-button>\r\n      </template>\r\n    </u-title>\r\n    <v-table\r\n      ref="resCodeRef"\r\n      :options="resCodeOptions"\r\n      :editable="editStatus[2]"\r\n      :show-toolbar="false"\r\n      show-operation\r\n      class="api-param-table"\r\n    />\r\n\r\n    <!--  响应示例  -->\r\n    <u-title class="api-param-title" name="响应示例">\r\n      <template #default>\r\n        <a v-if="!editStatus[3]" class="ml-3" @click="handleEdit(3)">\r\n          <Icon icon="edit" class="custom-icon editForm" />\r\n        </a>\r\n        <el-button v-if="editStatus[3]" type="text" class="ml-3" @click="handleCancel(3)">\r\n          取消\r\n        </el-button>\r\n        <el-button v-if="editStatus[3]" type="text" :loading="btnLoading[3]" @click="handleSave(3)">\r\n          保存\r\n        </el-button>\r\n      </template>\r\n    </u-title>\r\n    <div class="api-param-table" style="height: 500px; margin-bottom: 0px">\r\n      <template v-if="editStatus[3]">\r\n        <code-editor\r\n          v-model="resultSampleTemp"\r\n          lang="javascript"\r\n          theme="chrome"\r\n          :read-only="!editStatus[3]"\r\n          placeholder="请输入响应示例..."\r\n        />\r\n      </template>\r\n      <template v-else>\r\n        <Empty v-if="!resultSampleTemp"></Empty>\r\n        <code-editor\r\n          v-else\r\n          v-model="resultSampleTemp"\r\n          lang="javascript"\r\n          theme="chrome"\r\n          :read-only="!editStatus[3]"\r\n          placeholder="请输入响应示例..."\r\n        />\r\n      </template>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted } from "vue";\r\nimport { useDictStore } from "@/store";\r\n\r\nconst resRef = ref(null);\r\nconst resCodeRef = ref(null);\r\nconst reqRef = ref(null);\r\nconst resultSampleTemp = ref("");\r\nconst editStatus = ref([false, false, false, false]);\r\nconst btnLoading = ref([false, false, false, false]);\r\nconst reqOptions = ref({\r\n  columns: [\r\n    {\r\n      title: "参数名称",\r\n      field: "paramName",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数中文名",\r\n      field: "paramNameZh",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数说明",\r\n      field: "paramDesc",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数类型",\r\n      field: "paramType",\r\n      width: 150,\r\n      editRender: { name: "ElSelect", options: useDictStore().getDictItems("tableColType") },\r\n    },\r\n    {\r\n      title: "参数位置",\r\n      field: "paramPosition",\r\n      width: 150,\r\n      editRender: { name: "ElSelect", options: useDictStore().getDictItems("paramPosition") },\r\n    },\r\n    {\r\n      title: "必填属性",\r\n      field: "status",\r\n      width: 150,\r\n      editRender: { name: "ElSelect", options: useDictStore().getDictItems("requiredAttribute") },\r\n    },\r\n    {\r\n      title: "默认值",\r\n      field: "instance",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    paramName: [{ required: true, content: "参数名称不能为空", trigger: "blur" }],\r\n    paramNameZh: [{ required: true, content: "参数中文名不能为空", trigger: "blur" }],\r\n    paramType: [{ required: true, content: "参数类型不能为空", trigger: "blur" }],\r\n    paramPosition: [{ required: true, content: "参数位置不能为空", trigger: "blur" }],\r\n    status: [{ required: true, content: "必填属性不能为空", trigger: "blur" }],\r\n  },\r\n});\r\nconst resOptions = ref({\r\n  columns: [\r\n    {\r\n      title: "参数名称",\r\n      field: "paramName",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数中文名",\r\n      field: "paramNameZh",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数说明",\r\n      field: "paramDesc",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "参数类型",\r\n      field: "paramType",\r\n      width: 150,\r\n      editRender: { name: "ElSelect", options: useDictStore().getDictItems("tableColType") },\r\n    },\r\n    {\r\n      title: "默认值",\r\n      field: "instance",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    paramName: [{ required: true, content: "参数名称不能为空", trigger: "blur" }],\r\n    paramNameZh: [{ required: true, content: "参数中文名不能为空", trigger: "blur" }],\r\n    paramType: [{ required: true, content: "参数类型不能为空", trigger: "blur" }],\r\n  },\r\n});\r\nconst resCodeOptions = ref({\r\n  columns: [\r\n    {\r\n      title: "状态码",\r\n      field: "statusCode",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      title: "状态码描述",\r\n      field: "statusDesc",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    statusCode: [{ required: true, content: "状态码不能为空", trigger: "blur" }],\r\n    statusDesc: [{ required: true, content: "状态码描述不能为空", trigger: "blur" }],\r\n  },\r\n});\r\n\r\nconst init = () => {\r\n  // @todo  api props.categoryId\r\n  // 请求参数 - 广电业务相关\r\n  reqRef.value.setData([\r\n    {\r\n      paramName: "channelId",\r\n      paramNameZh: "频道ID",\r\n      paramType: "varchar",\r\n      required: true,\r\n      paramDesc: "广电频道唯一标识",\r\n      paramPosition: "body",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "programId",\r\n      paramNameZh: "节目ID",\r\n      paramType: "varchar",\r\n      required: false,\r\n      paramDesc: "节目唯一标识",\r\n      paramPosition: "body",\r\n      status: "optional",\r\n    },\r\n    {\r\n      paramName: "startTime",\r\n      paramNameZh: "开始时间",\r\n      paramType: "datetime",\r\n      required: true,\r\n      paramDesc: "查询开始时间",\r\n      paramPosition: "body",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "endTime",\r\n      paramNameZh: "结束时间",\r\n      paramType: "datetime",\r\n      required: true,\r\n      paramDesc: "查询结束时间",\r\n      paramPosition: "body",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "regionCode",\r\n      paramNameZh: "区域编码",\r\n      paramType: "varchar",\r\n      required: false,\r\n      paramDesc: "广电覆盖区域编码",\r\n      paramPosition: "body",\r\n      status: "optional",\r\n    },\r\n  ]);\r\n\r\n  // 响应参数 - 广电业务相关\r\n  resRef.value.setData([\r\n    {\r\n      paramName: "channelId",\r\n      paramNameZh: "频道ID",\r\n      paramType: "varchar",\r\n      paramDesc: "广电频道唯一标识",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "channelName",\r\n      paramNameZh: "频道名称",\r\n      paramType: "varchar",\r\n      paramDesc: "广电频道名称",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "programList",\r\n      paramNameZh: "节目列表",\r\n      paramType: "array",\r\n      paramDesc: "频道节目列表",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "totalCount",\r\n      paramNameZh: "总条数",\r\n      paramType: "integer",\r\n      paramDesc: "节目总数",\r\n      status: "required",\r\n    },\r\n    {\r\n      paramName: "regionInfo",\r\n      paramNameZh: "区域信息",\r\n      paramType: "object",\r\n      paramDesc: "广电覆盖区域信息",\r\n      status: "optional",\r\n    },\r\n  ]);\r\n\r\n  // 响应状态码 - 广电业务相关\r\n  resCodeRef.value.setData([\r\n    {\r\n      statusCode: "200",\r\n      statusDesc: "成功",\r\n    },\r\n    {\r\n      statusCode: "400",\r\n      statusDesc: "请求参数错误",\r\n    },\r\n    {\r\n      statusCode: "401",\r\n      statusDesc: "未授权访问",\r\n    },\r\n    {\r\n      statusCode: "403",\r\n      statusDesc: "权限不足",\r\n    },\r\n    {\r\n      statusCode: "404",\r\n      statusDesc: "频道或节目不存在",\r\n    },\r\n    {\r\n      statusCode: "500",\r\n      statusDesc: "服务器内部错误",\r\n    },\r\n    {\r\n      statusCode: "502",\r\n      statusDesc: "广电服务暂时不可用",\r\n    },\r\n  ]);\r\n\r\n  // 响应示例 - 广电业务相关\r\n  //   resultSampleTemp.value = `{\r\n  //   "code": 200,\r\n  //   "message": "success",\r\n  //   "data": {\r\n  //     "channelId": "GDT10086",\r\n  //     "channelName": "广东卫视",\r\n  //     "programList": [\r\n  //       {\r\n  //         "programId": "PG20240101001",\r\n  //         "programName": "新闻联播",\r\n  //         "startTime": "2024-01-01 19:00:00",\r\n  //         "endTime": "2024-01-01 19:30:00",\r\n  //         "type": "news",\r\n  //         "description": "全国新闻联播节目"\r\n  //       },\r\n  //       {\r\n  //         "programId": "PG20240101002",\r\n  //         "programName": "天气预报",\r\n  //         "startTime": "2024-01-01 19:30:00",\r\n  //         "endTime": "2024-01-01 19:35:00",\r\n  //         "type": "life",\r\n  //         "description": "全国天气预报"\r\n  //       },\r\n  //       {\r\n  //         "programId": "PG20240101003",\r\n  //         "programName": "黄金剧场",\r\n  //         "startTime": "2024-01-01 20:00:00",\r\n  //         "endTime": "2024-01-01 22:00:00",\r\n  //         "type": "drama",\r\n  //         "description": "热播电视剧"\r\n  //       }\r\n  //     ],\r\n  //     "totalCount": 3,\r\n  //     "regionInfo": {\r\n  //       "regionCode": "440000",\r\n  //       "regionName": "广东省",\r\n  //       "coverageRate": "99.8%"\r\n  //     }\r\n  //   },\r\n  //   "timestamp": "2024-01-01 18:00:00"\r\n  // }`;\r\n};\r\n\r\nconst handleEdit = (index: number) => {\r\n  editStatus.value[index] = true;\r\n};\r\n\r\nconst handleCancel = (index: number) => {\r\n  editStatus.value[index] = false;\r\n};\r\n\r\nconst handleSave = async (index: number) => {\r\n  try {\r\n    btnLoading.value[index] = true;\r\n    if (index === 0) {\r\n      await reqRef.value.validate();\r\n      const data = reqRef.value.getData();\r\n      console.log("请求参数数据:", data);\r\n    } else if (index === 1) {\r\n      await resRef.value.validate();\r\n      const data = resRef.value.getData();\r\n      console.log("响应参数数据:", data);\r\n    } else if (index === 2) {\r\n      await resCodeRef.value.validate();\r\n      const data = resCodeRef.value.getData();\r\n      console.log("响应状态码数据:", data);\r\n    } else if (index === 3) {\r\n      console.log("响应示例数据:", resultSampleTemp.value);\r\n    }\r\n\r\n    // 保存成功后切换回只读状态\r\n    editStatus.value[index] = false;\r\n  } catch (error) {\r\n    console.error("保存失败:", error);\r\n  } finally {\r\n    btnLoading.value[index] = false;\r\n  }\r\n};\r\n\r\nconst handleAdd = (index: number) => {\r\n  if (index === 0) {\r\n    reqRef.value?.gridEvents.toolbarButtonClick({ code: "append_edit" });\r\n  } else if (index === 1) {\r\n    console.log("handleAdd", resRef.value?.gridEvents);\r\n    resRef.value?.gridEvents.toolbarButtonClick({ code: "append_edit" });\r\n  } else if (index === 2) {\r\n    resCodeRef.value?.gridEvents.toolbarButtonClick({ code: "append_edit" });\r\n  }\r\n};\r\n\r\nonMounted(() => {\r\n  init();\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.api-param {\r\n  overflow: auto;\r\n  .api-param-title {\r\n    height: 32px;\r\n    margin-bottom: 12px;\r\n  }\r\n  