INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2064226681117839360','2063874204568698880','api-register-modal','<template>\r\n  <ServiceDialogWrapper\r\n    v-model="open"\r\n    title="服务登记"\r\n    :is-finish="isFinish"\r\n    :finish-name="registeredFormData.serviceName || registeredFormData.name || \'\'"\r\n    :finish-time="registeredFormData.latestUpdateTime || \'\'"\r\n    @close="onCancel"\r\n    @to-see="handleToSee"\r\n  >\r\n    <ApiRegisterContent ref="contentRef" :data="apiDetail" context="modal" />\r\n\r\n    <template #footer>\r\n      <el-button @click="onCancel">取消</el-button>\r\n      <el-button type="primary" :disabled="taskLoading" @click="handleSubmit">\r\n        <icon :icon="\'check-circle\'" class="mr-2" />\r\n        提交登记\r\n      </el-button>\r\n    </template>\r\n  </ServiceDialogWrapper>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, computed } from "vue";\r\n// import ApiRegisterContent from "./components/ApiRegisterContent.vue";\r\n// import ServiceDialogWrapper from "./components/ServiceDialogWrapper.vue";\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", value: boolean): void;\r\n  (e: "close", value: "cancel" | "success"): void;\r\n}>();\r\n\r\nconst props = defineProps({\r\n  modelValue: Boolean,\r\n  apiDetail: Object as () => any,\r\n});\r\n\r\nconst contentRef = ref();\r\nconst taskLoading = ref(false);\r\nconst isFinish = ref(false);\r\nconst registeredFormData = ref<any>({});\r\n\r\nconst open = computed({\r\n  get: () => props.modelValue,\r\n  set: (val: boolean) => emit("update:modelValue", val),\r\n});\r\n\r\nconst onCancel = (): void => {\r\n  emit("close", "cancel");\r\n  open.value = false;\r\n};\r\n\r\nconst handleToSee = () => {\r\n  open.value = false;\r\n  emit("close", "success");\r\n};\r\n\r\nconst handleSubmit = async () => {\r\n  taskLoading.value = true;\r\n  try {\r\n    const ok = await contentRef.value?.handleSave();\r\n    if (ok) {\r\n      registeredFormData.value = (await contentRef.value?.getFormData()) || {};\r\n      isFinish.value = true;\r\n    }\r\n  } finally {\r\n    taskLoading.value = false;\r\n  }\r\n};\r\n\r\nconst fetchFormData = async () => {\r\n  if (props.apiDetail?.serviceBuildId) {\r\n    $common\r\n      .post("/dataassets/manage/assets/queryById", {\r\n        tid: props.apiDetail.serviceBuildId,\r\n      })\r\n      .then((res) => {\r\n        registeredFormData.value = res || {};\r\n      });\r\n  }\r\n};\r\n\r\nwatch(\r\n  open,\r\n  (val: boolean) => {\r\n    if (val) {\r\n      isFinish.value = false;\r\n      registeredFormData.value = {};\r\n      contentRef.value?.reset();\r\n      fetchFormData();\r\n    }\r\n  },\r\n  { immediate: true }\r\n);\r\n</script>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\n// import ApiRegisterContent from "./components/ApiRegisterContent.vue";\n// import ServiceDialogWrapper from "./components/ServiceDialogWrapper.vue";\n\nconst __sfc__ = _defineComponent({\n  __name: \'34751e3f60cfac5d8d36d1861cff1ae2\',\n  props: {\n    modelValue: Boolean,\n    apiDetail: Object\n  },\n  emits: ["update:modelValue", "close"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const emit = __emit;\n    const props = __props;\n    const conte