INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2026115170365382656','2026114126046601216','app-warehouse','<template>\r\n  <div class="app-warehouse card-container flex flex-col px-5 pt-5 pb-2">\r\n    <!-- 头部 -->\r\n    <div class="header mb-5 flex-x-between">\r\n      <el-segmented v-model="activeTab" :options="tabConfig" @change="handleTabChange" />\r\n\r\n      <div class="flex gap-2">\r\n        <el-input\r\n          v-model="searchText"\r\n          placeholder="搜索应用名称或者ID"\r\n          class="search-input"\r\n          clearable\r\n          @input="handleSearch"\r\n        >\r\n          <template #prefix>\r\n            <Icon icon="el-icon-search"></Icon>\r\n          </template>\r\n        </el-input>\r\n\r\n        <el-button type="primary" @click="openCreateModal">\r\n          <Icon icon="el-icon-Plus" class="mr-2"></Icon>\r\n          新建应用\r\n        </el-button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 中间内容区 -->\r\n    <div class="content">\r\n      <!-- 骨架屏 - 数据加载中显示 -->\r\n      <div v-if="loading" class="todo-cards">\r\n        <warehouse-card v-for="i in 12" :key="i" :loading="true"></warehouse-card>\r\n      </div>\r\n\r\n      <!-- 实际卡片内容 - 数据加载完成后显示 -->\r\n      <div v-else-if="todoItems.length > 0" class="todo-cards">\r\n        <warehouse-card\r\n          v-for="item in todoItems"\r\n          :key="item.tid"\r\n          :item="item"\r\n          class="todo-card"\r\n          @operation-click="handleOperation"\r\n        ></warehouse-card>\r\n      </div>\r\n\r\n      <!-- 空状态 - 数据加载完成但无数据时显示 -->\r\n      <div v-else class="empty-state">\r\n        <el-empty description="暂无数据"></el-empty>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 底部分页 -->\r\n    <div class="footer">\r\n      <el-pagination\r\n        v-model:current-page="currentPage"\r\n        v-model:page-size="pageSize"\r\n        :page-sizes="[12, 24, 36]"\r\n        layout="total, sizes, prev, pager, next, jumper"\r\n        :total="total"\r\n        @size-change="handleSizeChange"\r\n        @current-change="handleCurrentChange"\r\n      />\r\n    </div>\r\n    <create-app-modal\r\n      v-if="createVisible"\r\n      v-model="createVisible"\r\n      mode="create"\r\n      @submit="createApp"\r\n      @close="handleModalClose"\r\n    ></create-app-modal>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted } from "vue";\r\nimport { useRouter } from "vue-router";\r\nimport { ElMessage, ElMessageBox } from "element-plus";\r\n// import warehouseCard from "./warehouse-card.vue";\r\n// import createAppModal from "./createAppModal.vue";\r\n\r\n// 接口定义\r\ninterface AppItem {\r\n  tid: string;\r\n  tenantId?: string;\r\n  appName: string;\r\n  appType: number;\r\n  appIcon: string;\r\n  description: string;\r\n  publishStatus: number; // 0-待发布 1-已发布\r\n  createdBy?: string;\r\n  createdTime?: string;\r\n  updatedBy?: string;\r\n  updatedTime?: string;\r\n}\r\n\r\ninterface PageResult {\r\n  total: number;\r\n  list: AppItem[];\r\n}\r\n\r\n// API 路径\r\nconst API = {\r\n  PAGE: "/das/repository/page",\r\n  ADD: "/das/repository/add",\r\n  DELETE: "/das/repository/delete",\r\n  PUBLISH: "/das/repository/publish",\r\n};\r\n\r\n// 状态定义\r\nconst router = useRouter();\r\nconst createVisible = ref(false);\r\n\r\n// 标签页常量配置\r\nconst tabConfig = [\r\n  { label: "全部", value: -1 },\r\n  { label: "待发布", value: 0 },\r\n  { label: "已发布", value: 1 },\r\n];\r\n\r\n// 状态定义\r\nconst activeTab = ref(-1);\r\nconst searchText = ref("");\r\nconst currentPage = ref(1);\r\nconst pageSize = ref(12);\r\nconst total = ref(0);\r\nconst todoItems = ref<AppItem[]>([]);\r\nconst loading = ref(true); // 加载状态控制\r\n\r\n// 加载应用列表\r\nconst loadAppList = async () => {\r\n  loading.value = true;\r\n  try {\r\n    const params = {\r\n      pageNum: currentPage.value,\r\n      pageSize: pageSize.value,\r\n      appName: searchText.value,\r\n      publishStatus: activeTab.value === -1 ? null : activeTab.value,\r\n    };\r\n    // $common.post 直接返回接口的 data 部分\r\n    const data = (await $common.post(API.PAGE, params)) as unknown as PageResult;\r\n    todoItems.value = data?.list || [];\r\n    total.value = data?.total || 0;\r\n  } catch (error) {\r\n    console.error("加载应用列表失败:", error);\r\n  } finally {\r\n    loading.value = false;\r\n  }\r\n};\r\n\r\n// 新增应用\r\nconst createApp = async (formData: Record<string, any>) => {\r\n  try {\r\n    // $common.post 直接返回接口的 data 部分（新增接口返回的是 tid 字符串）\r\n    const data = (await $common.post(API.ADD, formData)) as unknown as AppItem;\r\n    ElMessage.success("创建应用成功");\r\n    handleModalClose();\r\n    // 跳转到编辑页面;\r\n    if (data.tid) {\r\n      router.push({\r\n        path: "editor",\r\n        query: {\r\n          type: "warehouse-editor",\r\n          appId: data.tid,\r\n          title: "应用编辑",\r\n        },\r\n      });\r\n    }\r\n  } catch (error) {\r\n    console.error("创建应用失败:", error);\r\n    ElMessage.error("创建应用失败");\r\n  }\r\n};\r\n\r\n// 删除应用\r\nconst deleteApp = async (appId: string) => {\r\n  try {\r\n    await ElMessageBox.confirm("确定要删除该应用吗？删除后不可恢复。", "删除应用", {\r\n      confirmButtonText: "确定",\r\n      cancelButtonText: "取消",\r\n      type: "warning",\r\n    });\r\n    // $common.post 直接返回接口的 data 部分\r\n    await $common.post(API.DELETE, { tid: appId });\r\n    ElMessage.success("删除应用成功");\r\n    loadAppList();\r\n  } catch (error: any) {\r\n    if (error !== "cancel") {\r\n      console.error("删除应用失败:", error);\r\n      ElMessage.error("删除应用失败");\r\n    }\r\n  }\r\n};\r\n\r\n// 事件处理函数\r\nconst handleTabChange = (key: number) => {\r\n  activeTab.value = key;\r\n  currentPage.value = 1;\r\n  loadAppList();\r\n};\r\n\r\nconst handleSearch = () => {\r\n  currentPage.value = 1;\r\n  loadAppList();\r\n};\r\n\r\nconst handleSizeChange = (size: number) => {\r\n  pageSize.value = size;\r\n  currentPage.value = 1;\r\n  loadAppList();\r\n};\r\n\r\nconst handleCurrentChange = (current: number) => {\r\n  currentPage.value = current;\r\n  loadAppList();\r\n};\r\n\r\n// 打开创建弹窗\r\nconst openCreateModal = () => {\r\n  createVisible.value = true;\r\n};\r\n\r\n// 关闭弹窗\r\nconst handleModalClose = () => {\r\n  createVisible.value = false;\r\n};\r\n\r\n// 处理操作\r\nconst handleOperation = (action: string, item: AppItem) => {\r\n  if (action === "edit") {\r\n    // 跳到编辑应用页面\r\n    router.push({\r\n      path: "editor",\r\n      query: {\r\n        type: "warehouse-editor",\r\n        appId: item.tid,\r\n        title: "应用编辑",\r\n      },\r\n    });\r\n  } else if (action === "delete") {\r\n    // 删除应用\r\n    deleteApp(item.tid);\r\n  } else if (action === "publish") {\r\n    $common.handle({\r\n      url: API.PUBLISH,\r\n      method: "POST",\r\n      action: item.publishStatus === 0 ? "发布" : "取消发布",\r\n      info: item.publishStatus === 0 ? "确认发布该应用？" : "确认取消发布该应用？",\r\n      data: { tid: item.tid, publishStatus: item.publishStatus === 0 ? 1 : 0 },\r\n      done: () => {\r\n        loadAppList();\r\n      },\r\n    });\r\n  }\r\n};\r\n\r\n// 页面加载时初始化数据\r\nonMounted(() => {\r\n  loadAppList();\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.app-warehouse {\r\n  .search-input {\r\n    width: 200px;\r\n  }\r\n\r\n  .content {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n  }\r\n\r\n  .todo-cards {\r\n    padding-top: 5px;\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 20px;\r\n  }\r\n\r\n  .empty-state {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 400px;\r\n  }\r\n\r\n  .footer {\r\n    display: flex;\r\n    justify-content: flex-end;\r\n    padding-top: 20px;\r\n  }\r\n\r\n  /* 响应式布局 */\r\n  @media (max-width: 1600px) {\r\n    .todo-cards {\r\n      grid-template-columns: repeat(3, 1fr);\r\n    }\r\n  }\r\n\r\n  @media (max-width: 1280px) {\r\n    .todo-cards {\r\n      grid-template-columns: repeat(2, 1fr);\r\n    }\r\n 