n.app-warehouse .empty-state[data-v-23a37bcabe22c59eade103ad098252f6] {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  height: 400px;\n}\n.app-warehouse .footer[data-v-23a37bcabe22c59eade103ad098252f6] {\n  display: flex;\n  justify-content: flex-end;\n  padding-top: 20px;\n}\n.app-warehouse[data-v-23a37bcabe22c59eade103ad098252f6] {\n  /* 响应式布局 */\n}\n@media (max-width: 1600px) {\n.app-warehouse .todo-cards[data-v-23a37bcabe22c59eade103ad098252f6] {\n    grid-template-columns: repeat(3, 1fr);\n}\n}\n@media (max-width: 1280px) {\n.app-warehouse .todo-cards[data-v-23a37bcabe22c59eade103ad098252f6] {\n    grid-template-columns: repeat(2, 1fr);\n}\n}\n@media (max-width: 992px) {\n.app-warehouse .todo-cards[data-v-23a37bcabe22c59eade103ad098252f6] {\n    grid-template-columns: 1fr;\n}\n}','1','2.4.1 应用仓库',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2041789646725767168','2017179897413832704','apply-json-form','<template>\r\n  <div class="apply-json-form">\r\n    <JsonForm ref="formRef" bordered :rules="formRules" label-width="250px"></JsonForm>\r\n\r\n    <!--  打印  -->\r\n    <apply-print-modal\r\n      ref="printRef"\r\n      v-model="printState.open"\r\n      :rules="printState.rules"\r\n      :data="{ ...formRef?.formData() }"\r\n    />\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { nextTick, onMounted, reactive, ref } from "vue";\r\nimport { cloneDeep } from "lodash-es";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { useRegisterStore } from "@/store";\r\n\r\nconst store = useRegisterStore();\r\nconst props = withDefaults(\r\n  defineProps<{\r\n    /** 初始数据（包含 applyResource 申请资源列表） */\r\n    initData?: Record<string, any>;\r\n    editable?: boolean;\r\n    /** 是否复制申请单 */\r\n    copy?: boolean;\r\n  }>(),\r\n  {\r\n    initData: () => ({}),\r\n    editable: true,\r\n  }\r\n);\r\n\r\n// refs\r\nconst formRef = ref();\r\nconst printRef = ref<HTMLElement>();\r\n\r\nconst formRules = ref<any[]>([]);\r\n\r\n// 打印相关\r\nconst printState = reactive({\r\n  open: false,\r\n  rules: [],\r\n});\r\n\r\n// 初始化\r\nonMounted(async () => {\r\n  await loadFormRules();\r\n  await initFormData();\r\n});\r\n\r\n/** 加载表单规则 */\r\nconst loadFormRules = async () => {\r\n  try {\r\n    formRules.value = await ($form as any).get("登记申请单");\r\n    if (!props.editable) {\r\n      formRules.value = FormUtils.transFormText(formRules.value);\r\n    }\r\n  } catch (error) {\r\n    console.error("加载表单规则失败:", error);\r\n  }\r\n};\r\n\r\n/** 初始化表单数据 */\r\nconst initFormData = async () => {\r\n  let initData: any = {\r\n    applyOrgId: ($user as any).orgId,\r\n    usci: ($user as any).usci,\r\n  };\r\n  let catalogs: any[] = [];\r\n\r\n  if (props.initData.tid) {\r\n    // 编辑已有申请单，查询详情\r\n    const detail = await ($common as any).post("/dws/market/applyForm/queryById", {\r\n      tid: props.initData.tid,\r\n    });\r\n    const { applyResource = [], ...rest } = detail || {};\r\n    initData = rest;\r\n    catalogs = applyResource;\r\n\r\n    if (props.copy) {\r\n      // 复制一份申请单\r\n      initData = { ...initData, tid: undefined };\r\n    }\r\n  } else {\r\n    // 非编辑模式：从 initData.applyResource 获取申请资源列表\r\n    catalogs = props.initData.applyResource || [];\r\n  }\r\n\r\n  catalogs = catalogs.map((el: any) => ({ ...el }));\r\n\r\n  // 同步设置表单中的申请资源字段\r\n  nextTick(() => {\r\n    formRef.value?.setValue({ ...initData, applyResource: catalogs });\r\n    formRef.value.api.on("change", (field: string, value: any) => {\r\n      if (field === "applyResource") {\r\n        handleResChange(value);\r\n      }\r\n    });\r\n  });\r\n};\r\n\r\n/** 资源选择变化 */\r\nconst handleResChange = (rows: string[]) => {\r\n  formRef.value?.setValue({ applyResource: rows });\r\n\r\n  // 资源类型中有api时需显示使用信息表单\r\n  const hasApi = rows?.some((el) => el.resType?.includes("api"));\r\n  // 提取使用信息范围的表单字段\r\n  const fields: string[] = [];\r\n  for (const el of formRules.value) {\r\n    if (fields.length > 0 && el.type === "UTitle") {\r\n      break;\r\n    }\r\n    if (el.field === "useTitle" || fields.length > 0) {\r\n      fields.push(el.field);\r\n    }\r\n  }\r\n\r\n  if (hasApi) {\r\n    formRef.value?.api?.hidden(false, fields);\r\n  } else {\r\n    formRef.value?.api?.hidden(true, fields);\r\n  }\r\n  // formRef.value?.refresh();\r\n};\r\n\r\n/** 获取表单数据（带校验） */\r\nconst getFormData = async () => {\r\n  await formRef.value?.validate();\r\n  const formData = formRef.value?.getSaveData() || {};\r\n  return { ...formData };\r\n};\r\n\r\n/** 获取表单数据（不带校验） */\r\nconst getSaveData = () => {\r\n  return formRef.value?.getSaveData() || {};\r\n};\r\n\r\n/** 验证表单 */\r\nconst validate = async () => {\r\n  const formData = await getFormData();\r\n  // 校验是否选择了申请资源\r\n  if (Array.isArray(formData.applyResource) && formData.applyResource.length > 0) {\r\n    return true;\r\n  }\r\n  throw "请选择申请资源";\r\n};\r\n\r\n/** 设置表单值 */\r\nconst setValue = (data: Record<string, any>) => {\r\n  formRef.value?.setValue(data);\r\n};\r\n\r\n/** 重置表单 */\r\nconst resetFields = () => {\r\n  formRef.value?.resetFields();\r\n};\r\n\r\n/** 刷新表单 */\r\nconst refresh = () => {\r\n  formRef.value?.refresh();\r\n};\r\n\r\n/** 打开打印弹框 */\r\nconst openPrint = () => {\r\n  printState.open = true;\r\n  printState.rules = FormUtils.fixJson(cloneDeep(formRef.value?.api.rule || []), "160px");\r\n  if (props.editable) {\r\n    printState.rules = FormUtils.transFormText(printState.rules);\r\n  }\r\n};\r\n\r\n// 暴露方法\r\ndefineExpose({\r\n  getFormData,\r\n  getSaveData,\r\n  validate,\r\n  setValue,\r\n  resetFields,\r\n  refresh,\r\n  openPrint,\r\n  formRef,\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.apply-json-form {\r\n  width: 100%;\r\n}\r\n\r\n.apply-print-modal {\r\n  .print-content {\r\n    background: #fff;\r\n    padding: 20px;\r\n    max-height: 60vh;\r\n    overflow-y: auto;\r\n  }\r\n\r\n  .form-preview {\r\n    margin-bottom: 20px;\r\n  }\r\n\r\n  .resource-preview {\r\n    .preview-title {\r\n      margin: 0 0 12px 0;\r\n      font-size: 14px;\r\n      font-weight: 500;\r\n      color: #303133;\r\n    }\r\n  }\r\n\r\n  .dialog-footer {\r\n    display: flex;\r\n    justify-content: flex-end;\r\n    gap: 12px;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\nconst _hoisted_1 = {\n  class: "