esource = [],\n          ...rest\n        } = detail || {};\n        initData = rest;\n        catalogs = applyResource;\n        if (props.copy) {\n          // 复制一份申请单\n          initData = {\n            ...initData,\n            tid: undefined\n          };\n        }\n      } else {\n        // 非编辑模式：从 initData.applyResource 获取申请资源列表\n        catalogs = props.initData.applyResource || [];\n      }\n      catalogs = catalogs.map(el => ({\n        ...el\n      }));\n\n      // 同步设置表单中的申请资源字段\n      nextTick(() => {\n        formRef.value?.setValue({\n          ...initData,\n          applyResource: catalogs\n        });\n        formRef.value.api.on("change", (field, value) => {\n          if (field === "applyResource") {\n            handleResChange(value);\n          }\n        });\n      });\n    };\n\n    /** 资源选择变化 */\n    const handleResChange = rows => {\n      formRef.value?.setValue({\n        applyResource: rows\n      });\n\n      // 资源类型中有api时需显示使用信息表单\n      const hasApi = rows?.some(el => el.resType?.includes("api"));\n      // 提取使用信息范围的表单字段\n      const fields = [];\n      for (const el of formRules.value) {\n        if (fields.length > 0 && el.type === "UTitle") {\n          break;\n        }\n        if (el.field === "useTitle" || fields.length > 0) {\n          fields.push(el.field);\n        }\n      }\n      if (hasApi) {\n        formRef.value?.api?.hidden(false, fields);\n      } else {\n        formRef.value?.api?.hidden(true, fields);\n      }\n      // formRef.value?.refresh();\n    };\n\n    /** 获取表单数据（带校验） */\n    const getFormData = async () => {\n      await formRef.value?.validate();\n      const formData = formRef.value?.getSaveData() || {};\n      return {\n        ...formData\n      };\n    };\n\n    /** 获取表单数据（不带校验） */\n    const getSaveData = () => {\n      return formRef.value?.getSaveData() || {};\n    };\n\n    /** 验证表单 */\n    const validate = async () => {\n      const formData = await getFormData();\n      // 校验是否选择了申请资源\n      if (Array.isArray(formData.applyResource) && formData.applyResource.length > 0) {\n        return true;\n      }\n      throw "请选择申请资源";\n    };\n\n    /** 设置表单值 */\n    const setValue = data => {\n      formRef.value?.setValue(data);\n    };\n\n    /** 重置表单 */\n    const resetFields = () => {\n      formRef.value?.resetFields();\n    };\n\n    /** 刷新表单 */\n    const refresh = () => {\n      formRef.value?.refresh();\n    };\n\n    /** 打开打印弹框 */\n    const openPrint = () => {\n      printState.open = true;\n      printState.rules = FormUtils.fixJson(cloneDeep(formRef.value?.api.rule || []), "160px");\n      if (props.editable) {\n        printState.rules = FormUtils.transFormText(printState.rules);\n      }\n    };\n\n    // 暴露方法\n    __expose({\n      getFormData,\n      getSaveData,\n      validate,\n      setValue,\n      resetFields,\n      refresh,\n      openPrint,\n      formRef\n    });\n    return (_ctx, _cache) => {\n      const _component_JsonForm = _resolveComponent("JsonForm");\n      const _component_apply_print_modal = _resolveComponent("apply-print-modal");\n      return _openBlock(), _createElementBlock("div", _hoisted_1, [_createVNode(_component_JsonForm, {\n        ref_key: "formRef",\n        ref: formRef,\n        bordered: "",\n        rules: formRules.value,\n        "label-width": "250px"\n      }, null, 8 /* PROPS */, ["rules"]), _createCommentVNode("  打印  "), _createVNode(_component_apply_print_modal, {\n        ref_key: "printRef",\n        ref: printRef,\n        modelValue: printState.open,\n        "onUpdate:modelValue": _cache[0] || (_cache[0] = $event => printState.open = $event),\n        rules: printState.rules,\n        data: {\n          ...formRef.value?.formData()\n        }\n      }, null, 8 /* PROPS */, ["modelValue", "rules", "data"])]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "nextTick": "setup-const",\n  "onMounted": "setup-const",\n  "reactive": "setup-const",\n  "ref": "setup-const",\n  "cloneDeep": "setup-maybe-ref",\n  "FormUtils": "setup-maybe-ref",\n  "useRegisterStore": "setup-maybe-ref",\n  "store": "setup-maybe-ref",\n  "props": "setup-const",\n  "formRef": "setup-ref",\n  "printRef": "setup-ref",\n  "formRules": "setup-ref",\n  "printState": "setup-reactive-const",\n  "loadFormRules": "setup-const",\n  "initFormData": "setup-const",\n  "handleResChange": "setup-const",\n  "getFormData": "setup-const",\n  "getSaveData": "setup-const",\n  "validate": "setup-const",\n  "setValue": "setup-const",\n  "resetFields": "setup-const",\n  "refresh": "setup-const",\n  "openPrint": "setup-const",\n  "initData": "props",\n  "editable": "props",\n  "copy": "props"\n} */\n__sfc__.__scopeId = "data-v-b60341cabadb74979240a39872ec2e6c"\n__sfc__.__file = "b60341cabadb74979240a39872ec2e6c.vue"\nreturn __sfc__','.apply-json-form[data-v-b60341cabadb74979240a39872ec2e6c] {\n  width: 100%;\n}\n.apply-print-modal .print-content[data-v-b60341cabadb74979240a39872ec2e6c] {\n  background: #fff;\n  padding: 20px;\n  max-height: 60vh;\n  overflow-y: auto;\n}\n.apply-print-modal .form-preview[data-v-b60341cabadb74979240a39872ec2e6c] {\n  margin-bottom: 20px;\n}\n.apply-print-modal .resource-preview .preview-title[data-v-b60341cabadb74979240a39872ec2e6c] {\n  margin: 0 0 12px 0;\n  font-size: 14px;\n  font-weight: 500;\n  color: #303133;\n}\n.apply-print-modal .dialog-footer[data-v-b60341cabadb74979240a39872ec2e6c] {\n  display: flex;\n  justify-content: flex-end;\n  gap: 12px;\n}','1','申请单表单',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2020438938227388416','2017179897413832704','apply-print-modal','<template>\r\n  <el-dialog v-model="open" width="1050">\r\n    <!-- 要打印的DOM区域 -->\r\n    <div ref="printRef" class="print-content">\r\n      <h2>订阅目录申请单</h2>\r\n      <JsonForm\r\n        ref="formRef"\r\n        bordered\r\n        :rules="formRules"\r\n        :options="{\r\n          form: {\r\n            labelWidth: \'160px\',\r\n          },\r\n        }"\r\n        :data="data"\r\n      >\r\n        <template #field-applyResource>\r\n          <table style="width: 100%; table-layout: fixed">\r\n            <tr>\r\n              <td\r\n                v-for="col in tableCols"\r\n                :key="col.prop"\r\n                style="font-weight: 500; text-align: center"\r\n              >\r\n                {{ col.label }}\r\n              </td>\r\n            </tr>\r\n            <tr v-for="(row, i) in data[\'applyResource\']" :key="i">\r\n              <td v-for="col in tableCols" :key="i + col.prop" style="text-align: center">\r\n                <dict-label :model-value="row[col.prop]" :options="col.options" :tag="false" />\r\n              </td>\r\n            </tr>\r\n          </table>\r\n        </template>\r\n      </JsonForm>\r\n      <div class="promise">\r\n        <p class="promise-info">\r\n          我单位承诺填写信息全部属实，依法依规使用服务接口，确保数据使用安全，\r\n          对违规使用数据、泄露数据等情况承担相关责任。\r\n        </p>\r\n        <div class="prove">\r\n          <p>经办人：</p>\r\n          <p>申请单位（盖章）：</p>\r\n          <p>申请日期：</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 打印按钮 -->\r\n    <template #footer>\r\n      <el-button type="primary" @click="handleDownload">下载</el-button>\r\n      <el-button @click="handlePrint">打印</el-button>\r\n    </template>\r\n  </el-dialog>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, onMounted, reactive } from "vue";\r\nimport { usePrint } from "@/composables";\r\nimport { cloneDeep, set } from "lodash-es";\r\n\r\nconst props = withDefaults(\r\n  defineProps<{\r\n    data?: Record<string, any>;\r\n    rules?: [];\r\n    tableCols?: [];\r\n  }>(),\r\n  {\r\n    data: () => ({}),\r\n    rules: () => [],\r\n    tableCols: [\r\n      {\r\n        label: "数据目录",\r\n        prop: "catalogName",\r\n        ellipsis: true,\r\n        minWidth: 120,\r\n      },\r\n      {\r\n        label: "资源类型",\r\n        prop: "resType",\r\n        options: "assetType",\r\n      },\r\n      {\r\n        label: "共享属性",\r\n        prop: "shareType",\r\n        options: "shareType",\r\n        width: 120,\r\n      },\r\n      {\r\n        label: "来源部门",\r\n        prop: "orgId",\r\n        options: "org",\r\n        width: 200,\r\n      },\r\n    ],\r\n  }\r\n);\r\nconst formRef = ref();\r\nconst open = defineModel("modelValue", {\r\n  type: Boolean,\r\n  required: true,\r\n});\r\n\r\nconst formRules = computed(() => {\r\n  return props.rules.map((el) => {\r\n    set(el, "props.tag", false);\r\n    return el;\r\n  });\r\n});\r\n\r\nconst tableState = reactive<{ selectedRows: any[]; list: any[]; cols: any[] }>({\r\n  selectedRows: [],\r\n  list: [],\r\n  cols: [],\r\n});\r\n\r\nconst printRef = ref(null); // 绑定要打印的DOM\r\nconst { printDOM, downloadPdf } = usePrint();\r\n\r\n// 打印处理函数\r\nconst handlePrint = async () => {\r\n  await printDOM(printRef, {\r\n    title: "申请单",\r\n    // 打印前回调（可修改数据/DOM）\r\n    beforePrint: () => {\r\n      $message.primary("正在准备打印...");\r\n    },\r\n  });\r\n};\r\n\r\nonMounted(() => {\r\n  tableState.list = [];\r\n});\r\nconst handleDownload = async () => {\r\n  await downloadPdf(printRef, {\r\n    filename: "申请单.pdf",\r\n    fitToA4: true, // 强制适配A4\r\n    orientation: "portrait", // 纵向（可选landscape横向）\r\n    // 下载前后回调\r\n    beforeDownload: () => {\r\n      $message.primary("正在下载，请稍后...");\r\n    },\r\n    afterDownload: () => {},\r\n  });\r\n};\r\ndefineExpose({\r\n  print: handlePrint,\r\n  download: handleDownload,\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.print-content {\r\n  background: #fff;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  padding: 12px 20px 0 20px;\r\n\r\n  table,\r\n  tr,\r\n  td,\r\n  th {\r\n    border: 0.5px solid #000000e0;\r\n    border-collapse: collapse;\r\n  }\r\n\r\n  :deep(.el-tag) {\r\n    background-color: transparent;\r\n    border: 0;\r\n    margin-left: 0;\r\n  }\r\n\r\n  :deep(.jf-border) {\r\n    width: calc(100% + 1px);\r\n    .u-title .title:before {\r\n      display: none;\r\n      font-weight: bolder;\r\n    }\r\n\r\n    .fc-form-col {\r\n      border: 1px solid #000000e0;\r\n      margin: -1px 1px 0 -1px;\r\n\r\n      /*防止表单右侧边框凹陷*/\r\n      &:nth-child(even) {\r\n        // border-right: 0;\r\n      }\r\n      &:nth-child(odd) {\r\n        border-right: 1px;\r\n      }\r\n      &.el-col-24 {\r\n        border: 1px solid #000000e0;\r\n      }\r\n\r\n      .el-form-item__content {\r\n        * {\r\n          color: #000000e0 !important;\r\n        }\r\n      }\r\n\r\n      .el-form-item .el-form-item__label {\r\n        background: #fff;\r\n        border-right: 1px solid #000000e0;\r\n        & > .fc-form-title {\r\n          overflow: hidden;\r\n          text-overflow: ellipsis;\r\n          font-weight: 400;\r\n          color: #000000e0 !important;\r\n          white-space: wrap;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.promise {\r\n  border: 1px solid #000000e0;\r\n  border-top: 0;\r\n  height: 250px;\r\n  text-indent: 32px;\r\n  font-size: 16px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  width: 100%;\r\n\r\n  .promise-info {\r\n    font-weight: 700;\r\n  }\r\n  .prove {\r\n    p {\r\n      margin-bottom: 32px;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _useModel = ___magic__import__(\'vue\', \'useModel\');\r\nconst _mergeM