INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2029851370624491520','2026115170365382656','base-table2','<template>\r\n  <div class="card-container flex flex-col px-5 pt-5 pb-2">\r\n    <SheetComponent\r\n      ref="s2Ref"\r\n      :data-cfg="s2DataConfig"\r\n      :options="s2Options"\r\n      sheet-type="gridAnalysis"\r\n      :header="headerConfig"\r\n      @data-cell-click="onDataCellClick"\r\n    />\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, shallowRef, reactive, onMounted, h } from "vue";\r\nimport { LayoutWidthType, isUpDataValue, type SpreadSheet } from "@antv/s2";\r\nimport { SheetComponent } from "@antv/s2-vue";\r\ninterface S2DataConfig {\r\n  fields: Record<string, any>;\r\n  data: Record<string, any>[];\r\n  meta?: Record<string, any>[];\r\n}\r\n\r\ninterface S2Options {\r\n  width: number;\r\n  height: number;\r\n  tooltip: {\r\n    enable: boolean;\r\n  };\r\n  style: {\r\n    layoutWidthType: LayoutWidthType;\r\n    dataCell: {\r\n      width: number;\r\n      height: number;\r\n      valuesCfg: {\r\n        widthPercent: number[];\r\n      };\r\n    };\r\n  };\r\n  conditions: Record<string, any>;\r\n}\r\n\r\n// 静态数据定义\r\nconst staticData = {\r\n  dataCfg: {\r\n    fields: {\r\n      rows: ["country", "city"],\r\n      columns: ["type", "sub_type"],\r\n      values: ["price", "cost", "rate", "growth"],\r\n      valueInCols: true,\r\n    },\r\n    data: [\r\n      {\r\n        country: "中国",\r\n        city: "成都",\r\n        type: "家具",\r\n        sub_type: "桌子",\r\n        price: 1000,\r\n        cost: 120,\r\n        rate: 0.23,\r\n        growth: 0.15,\r\n      },\r\n      {\r\n        country: "中国",\r\n        city: "成都",\r\n        type: "家具",\r\n        sub_type: "沙发",\r\n        price: 2000,\r\n        cost: 150,\r\n        rate: 0.15,\r\n        growth: 0.05,\r\n      },\r\n      {\r