INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2019722536331849728','2017179897413832704','car-list','<template>\r\n  <div class="pt-5 px-5">\r\n    <u-title class="py-0! flex-center" name="待申请数据目录">\r\n      <el-tag round class="ml-2">{{ filteredList?.length }}</el-tag>\r\n      <template #right>\r\n        <el-space :size="16">\r\n          <el-input\r\n            v-model="state.keyword"\r\n            style="width: 300px"\r\n            clearable\r\n            placeholder="请输入搜索关键词"\r\n            suffix-icon="search"\r\n          />\r\n\r\n          <el-badge :value="state.draftCount" :hidden="state.draftCount === 0" :max="99">\r\n            <el-tooltip\r\n              :content="state.draftCount === 0 ? \'暂无待提交申请单\' : \'\'"\r\n              :disabled="state.draftCount > 0"\r\n            >\r\n              <el-button\r\n                type="primary"\r\n                plain\r\n                :disabled="state.draftCount === 0"\r\n                @click="handleAction(\'草稿箱\')"\r\n              >\r\n                草稿箱\r\n              </el-button>\r\n            </el-tooltip>\r\n          </el-badge>\r\n        </el-space>\r\n      </template>\r\n    </u-title>\r\n    <page-list\r\n      v-model="state.selectList"\r\n      row-key="tid"\r\n      :list="filteredList"\r\n      :columns="state.fields"\r\n      selectable\r\n      @title-click="handleAction(\'detail\', $event)"\r\n    >\r\n      <template #toolbar></template>\r\n\r\n      <template #icon>\r\n        <Icon icon="category" size="18" />\r\n      </template>\r\n\r\n      <template #title="{ row }">\r\n        {{ row.catalogName }}\r\n      </template>\r\n\r\n      <template #status="{ row }">\r\n        <span></span>\r\n      </template>\r\n\r\n      <template #actions="{ row }">\r\n        <el-button type="danger" link icon="delete" @click="handleAction(\'删除\', row)">\r\n          删除\r\n        </el-button>\r\n      </template>\r\n\r\n      <template #pagination></template>\r\n    </page-list>\r\n\r\n    <el-drawer\r\n      v-model="state.open"\r\n      size="385"\r\n      resizable\r\n      title="待提交申请单"\r\n      header-class="draft-drawer__header"\r\n      body-class="draft-drawer__body"\r\n    >\r\n      <div class="draft-list">\r\n        <div v-for="it in state.drafts" :key="it.id" class="draft-card">\r\n          <div class="card-header">\r\n            <div class="card-title">\r\n              <Icon icon="todo2" size="18" class="mr-1" />\r\n              <span :title="it.applyName">{{ it.applyName }}</span>\r\n            </div>\r\n            <el-dropdown\r\n              trigger="hover"\r\n              placement="bottom-end"\r\n              :hide-on-click="true"\r\n              @command="(cmd) => handleDraftCommand(it, cmd)"\r\n            >\r\n              <el-button type="info" link style="rotate: 90deg; margin-right: -8px">\r\n                <Icon icon="el-icon-MoreFilled" size="14" />\r\n              </el-button>\r\n              <template #dropdown>\r\n                <el-dropdown-menu>\r\n                  <el-dropdown-item command="delete" style="color: var(--el-color-danger)">\r\n                    <Icon icon="el-icon-delete" />\r\n                    删除\r\n                  </el-dropdown-item>\r\n                </el-dropdown-menu>\r\n              </template>\r\n            </el-dropdown>\r\n          </div>\r\n          <div class="card-meta">\r\n            <div class="meta-row">\r\n              <span>资源数量：</span>\r\n\r\n              <span>{{ it.resCount }}个</span>\r\n            </div>\r\n            <div class="meta-row">\r\n              <span>更新时间：</span>\r\n              <span>{{ it.updatedTime }}</span>\r\n            </div>\r\n          </div>\r\n          <el-button type="primary" plain class="card-btn" @click="handleAction(\'继续申请\', it)">\r\n            <template #icon>\r\n              <Icon icon="apply" />\r\n            </template>\r\n            继续申请\r\n          </el-button>\r\n        </div>\r\n        <Empty v-if="!state.drafts?.length" />\r\n      </div>\r\n    </el-drawer>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { reactive, computed, onMounted, getCurrentInstance, ref, h } from "vue";\r\nimport { ElMessageBox, ElCheckbox } from "element-plus";\r\nimport { useRegisterStore } from "@/store";\r\nimport { useCartCount } from "@/composables";\r\n\r\nconst { decrement } = useCartCount();\r\n\r\nconst store = useRegisterStore();\r\nconst { proxy } = getCurrentInstance()!;\r\nconst $common = (proxy as any).$common;\r\n\r\nconst state = reactive<any>({\r\n  selectList: [],\r\n  open: false,\r\n  keyword: "",\r\n  data: [],\r\n  drafts: [],\r\n  draftCount: 0,\r\n  fields: [],\r\n});\r\n\r\nconst fetchList = async () => {\r\n  const data = await $common.post("/dws/market/shoppingCardList");\r\n  state.data = data || [];\r\n};\r\n\r\nonMounted(() => {\r\n  fetchList();\r\n  fetchDrafts();\r\n});\r\n\r\nconst fetchDrafts = async () => {\r\n  const data = await $common.post("/dws/market/applyForm/list", {\r\n    type: "catalogSubscribe",\r\n    flowStatus: 0,\r\n  });\r\n  state.drafts = (data || []).map((el: any) => ({\r\n    ...el,\r\n    id: el.tid,\r\n    title: el.applyTitle || el.title || el.formName,\r\n    resCount: el.resCount ?? el.catalogIds?.split(",")?.length, // 暂时先使用目录个数，因为一般一个目录一个资源\r\n  }));\r\n  state.draftCount = state.drafts.length;\r\n};\r\n\r\nconst handleAction = async (type: string, row?: any) => {\r\n  switch (type) {\r\n    case "草稿箱":\r\n      state.open = true;\r\n      fetchDrafts();\r\n      break;\r\n    case "删除":\r\n      await $common\r\n        .post("/dws/market/shoppingCardRemove", {\r\n          tid: row.shoppingCarId,\r\n        })\r\n        .then((res) => {\r\n          $message.success("删除成功");\r\n          decrement(1);\r\n        });\r\n      await fetchList();\r\n      break;\r\n    case "继续申请":\r\n      store.data = {\r\n        apply: { tid: row.tid },\r\n      };\r\n      store.handleAction("next");\r\n      break;\r\n    case "next": {\r\n      if (state.open) {\r\n        // 继续申请触发的next\r\n        state.open = false;\r\n        break;\r\n      }\r\n      // 申请单信息\r\n      const data = state.data.filter((el) => state.selectList.includes(el.tid));\r\n      if (data.length === 0) {\r\n        throw "请至少勾选一个数据目录";\r\n      }\r\n      store.data = {\r\n        apply: { applyResource: data },\r\n      };\r\n      break;\r\n    }\r\n  }\r\n};\r\n\r\nconst handleDraftCommand = async (item: any, cmd: string) => {\r\n  if (cmd === "delete") {\r\n    const addToCart = ref(false);\r\n\r\n    try {\r\n      await $dialog({\r\n        title: "删除申请",\r\n        message: () =>\r\n          h("div", null, [\r\n            h("p", { style: "margin-bottom: 12px" }, `确定删除申请单【${item.applyName}】？`),\r\n            h(\r\n              ElCheckbox,\r\n              {\r\n                modelValue: addToCart.value,\r\n                "onUpdate:modelValue": (v: boolean) => (addToCart.value = v),\r\n              },\r\n              () => `将申请目录重新加入购物车`\r\n            ),\r\n          ]),\r\n        showCancelButton: true,\r\n        confirmButtonText: "确定",\r\n        cancelButtonText: "取消",\r\n        type: "warning",\r\n      });\r\n    } catch {\r\n      return;\r\n    }\r\n\r\n    await $common.post("/dws/market/applyForm/deleteById", {\r\n      tid: item.tid,\r\n      addToCart: addToCart.value,\r\n    });\r\n\r\n    $message.success(addToCart.value ? "已删除，目录已重新加入购物车" : "删除成功");\r\n    state.drafts = state.drafts.filter((d: any) => d.id !== item.id);\r\n    state.draftCount = state.drafts.length;\r\n\r\n    if (addToCart.value) {\r\n      fetchList();\r\n    }\r\n  }\r\n};\r\n\r\ndefineExpose({\r\n  next: () => handleAction("next"),\r\n});\r\n\r\nstate.fields = [\r\n  { title: "数源单位", field: "orgId", options: "org" },\r\n  { title: "资源类型", field: "resType", options: "assetType" },\r\n  { title: "共享类型", field: "shareType", options: "shareType" },\r\n  { title: "更新周期", field: "updateCycle", options: "updateCycle" },\r\n  { title: "业务系统", field: "appId", options: "app" },\r\n  { title: "选购时间", field: "addTime" },\r\n];\r\n\r\nconst filteredList = computed(() => {\r\n  const kw = (state.keyword || "").trim().toLowerCase();\r\n  return state.data.filter((row: any) => {\r\n    const text = [row.catalogName, row.appName, row.orgName, row.shareType, row.belongField]\r\n      .filter(Boolean)\r\n      .join(" ")\r\n      .toLowerCase();\r\n    return text.includes(kw);\r\n  });\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n:deep(.pl-container) {\r\n  padding-top: 0px;\r\n  .pl-toolbar {\r\n    margin: 0 0;\r\n  }\r\n  .pl-row {\r\n    padding-left: 12px;\r\n    padding-right: 20px;\r\n  }\r\n  .pl-title:hover {\r\n    color: var(--title-color) !important;\r\n  }\r\n\r\n  .pl-actions {\r\n    visibility: hidden;\r\n  }\r\n  .pl-row:hover {\r\n    .pl-actions {\r\n      visibility: visible;\r\n    }\r\n  }\r\n}\r\n\r\n:deep(.el-drawer) {\r\n  border-radius: 12px 0 0 12px !important;\r\n}\r\n\r\n:deep(.draft-drawer__header) {\r\n  padding: 24px 28px 0 32px;\r\n  border-width: 0;\r\n}\r\n\r\n:deep(.draft-drawer__body) {\r\n  padding: 24px 32px;\r\n}\r\n\r\n.draft-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 24px;\r\n}\r\n.draft-card {\r\n  border: 1px solid var(--el-border-color);\r\n  border-radius: 10px;\r\n  background: #fff;\r\n  padding: 16px 20px;\r\n}\r\n.card-header {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  margin-bottom: 16px;\r\n}\r\n.card-title {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-family: "PingFang SC Medium";\r\n  font-weight: 500;\r\n  font-size: 16px;\r\n  color: #323643;\r\n  min-width: 0;\r\n\r\n  span {\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n  }\r\n}\r\n.card-meta {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n  margin-bottom: 16px;\r\n  font-family: "PingFang SC", sans-serif;\r\n  color: var(--el-text-color-secondary);\r\n}\r\n.card-btn {\r\n  width: 100%;\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\nconst _hoisted_1 = {\n  class: "pt-5 px-5"\n};\nconst _hoisted_2 = {\n  class: "draft-list"\n};\nconst _hoisted_3 = {\n  class: "card-header"\n};\nconst _hoisted_4 = {\n  class: "card-title"\n};\nconst _hoisted_5 = ["title"];\nconst _hoisted_6 = {\n  class: "card-meta"\n};\nconst _hoisted_7 = {\n  class: "meta-row"\n};\nconst _hoisted_8 = {\n  class: "meta-row"\n};\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst getCurrentInstance = ___magic__import__(\'vue\', \'getCurrentInstance\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst h = ___magic__import__(\'vue\', \'h\');\nconst ElCheckbox = ___magic__import__(\'element