 .pl-container .pl-title:hover {\n  color: var(--title-color) !important;\n}\n[data-v-f60384924477386b4356f571023082c3] .pl-container .pl-actions {\n  visibility: hidden;\n}\n[data-v-f60384924477386b4356f571023082c3] .pl-container .pl-row:hover .pl-actions {\n  visibility: visible;\n}\n[data-v-f60384924477386b4356f571023082c3] .el-drawer {\n  border-radius: 12px 0 0 12px !important;\n}\n[data-v-f60384924477386b4356f571023082c3] .draft-drawer__header {\n  padding: 24px 28px 0 32px;\n  border-width: 0;\n}\n[data-v-f60384924477386b4356f571023082c3] .draft-drawer__body {\n  padding: 24px 32px;\n}\n.draft-list[data-v-f60384924477386b4356f571023082c3] {\n  display: flex;\n  flex-direction: column;\n  gap: 24px;\n}\n.draft-card[data-v-f60384924477386b4356f571023082c3] {\n  border: 1px solid var(--el-border-color);\n  border-radius: 10px;\n  background: #fff;\n  padding: 16px 20px;\n}\n.card-header[data-v-f60384924477386b4356f571023082c3] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 16px;\n}\n.card-title[data-v-f60384924477386b4356f571023082c3] {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-family: "PingFang SC Medium";\n  font-weight: 500;\n  font-size: 16px;\n  color: #323643;\n  min-width: 0;\n}\n.card-title span[data-v-f60384924477386b4356f571023082c3] {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.card-meta[data-v-f60384924477386b4356f571023082c3] {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-bottom: 16px;\n  font-family: "PingFang SC", sans-serif;\n  color: var(--el-text-color-secondary);\n}\n.card-btn[data-v-f60384924477386b4356f571023082c3] {\n  width: 100%;\n}','1','购物车列表',NULL,NULL,0,'2084109831678504960',5);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2019722685447745536','2017179897413832704','car-register-apply','<template>\r\n  <div class="px-5 py-2">\r\n    <apply-json-form\r\n      ref="applyFormRef"\r\n      :init-data="applyData"\r\n      :copy="store.data.editType === \'再次申请\'"\r\n    />\r\n\r\n  </div>\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, onMounted } from "vue";\nimport { storeToRefs } from "pinia";\r\nimport { useRegisterStore } from "@/store";\r\nimport { useCartCount } from "@/composables";\r\nimport { get, set } from "lodash-es";\r\n\r\nconst { refresh: refreshCartCount } = useCartCount();\r\n\r\n// refs\r\nconst applyFormRef = ref();\r\nconst store = useRegisterStore();\r\nconst { state } = storeToRefs(store);\r\n\r\n// 当前申请单信息\r\nconst applyData = computed({\r\n  get: () => {\r\n    if (!get(store.data, "apply")) {\r\n      set(store.data, "apply", {});\r\n    }\r\n    return get(store.data, "apply", {});\r\n  },\r\n  set: (val) => set(store.data, "apply", val),\r\n});\r\n\r\n// 验证表单\r\nconst validate = async () => {\r\n  await applyFormRef.value?.validate();\r\n};\r\n\r\n// 保存单个申请单\r\nconst saveApi = (data: Record<string, any>) => {\r\n  // applyResource 保存为目录 tid 数组\r\n  return ($common as any).post("/dws/market/applyForm/saveOrUpdate", {\r\n    tid: data.tid,\r\n    type: "catalogSubscribe",\r\n    propList: {\r\n      ...data,\r\n    },\r\n  });\r\n};\r\n\r\nconst save = async (): Promise<any> => {\r\n  try {\r\n    state.value.loadStatus["main"] = true;\r\n    await validate();\r\n\r\n    const isUpdate = !!applyData.value.tid;\r\n    const saveData = await applyFormRef.value?.getFormData();\r\n\r\n    // 保持一个目录一条申请记录，便于后续分别维护和撤销。\n    let saveBatchList = [];\r\n    const catalogIds = saveData.applyResource?.map((el) => el.tid);\r\n\r\n    if (!isUpdate) {\r\n      // 新增：每个目录都是新申请单\r\n      saveBatchList = catalogIds.map((id: any) => ({\r\n        ...saveData,\r\n        applyResource: [id],\r\n        applyName: saveData.applyResource.find((el) => el.tid === id)?.catalogName,\r\n      }));\r\n    } else {\r\n      // 编辑：用逗号分隔的 tid 匹配\r\n      const tids = applyData.value.tid.split(",");\r\n      saveBatchList = catalogIds.map((id: any, ind: number) => ({\r\n        ...saveData,\r\n        applyResource: [id],\r\n        tid: tids[ind],\r\n        applyName: saveData.applyResource.find((el) => el.tid === id)?.catalogName,\r\n      }));\r\n    }\r\n\r\n    // 并行保存所有申请单\r\n    const res = await Promise.all(saveBatchList.map((el) => saveApi(el)));\r\n\r\n    // 新增申请单则更新购物车目录数\r\n    if (!isUpdate) {\r\n      refreshCartCount();\r\n    }\r\n\r\n    // 合并所有 tid 用逗号连接\r\n    applyData.value = Object.assign(applyData.value, saveData, {\r\n      tid: res.map((el: any) => el.tid).join(","),\r\n    });\r\n\r\n    return { success: true, msg: "保存成功" };\r\n  } catch (err: any) {\r\n    return { success: false, msg: (err.message || err) as string };\r\n  } finally {\r\n    state.value.loadStatus["main"] = false;\r\n  }\r\n};\r\n\r\nconst next = () => {\r\n  if (!applyData.value?.tid) {\r\n    throw "请保存";\r\n  }\r\n};\r\nconst commit = async () => {\n  next();\n\n  const saveData = await applyFormRef.value?.getFormData();\n  const finishData = saveData.applyResource?.map((el) => ({\n    ...el,\n    assetType: "catalog",\n    assetName: el.catalogName,\n    applyTime: saveData.applyTime,\n  }));\n  store.data["finish"] = finishData;\n  await finish();\n};\n\nconst finish = async () => {\n  next();\n\n  const tids = applyData.value.tid.split(",");\n  const apis = tids.map((tid) =>\n    $common.post("/dws/market/submit", {\n      flowOrderId: tid,\n    })\n  );\n  await Promise.all(apis);\n  $message.success("申请已直接生效");\n  store.handleAction("next");\n};\r\nconst print = () => {\r\n  applyFormRef.value?.openPrint();\r\n};\r\n\r\n// 暴露方法给父组件\r\ndefineExpose({ save, next, commit, print });\r\n\r\n</script>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\nconst _hoisted_1 = {\n  class: "px-5 py-2"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\nconst storeToRefs = ___magic__import__(\'pinia\', \'storeToRefs\');\nconst useRegisterStore = ___magic__import__(\'@/store\', \'useRegisterStore\');\nconst useCartCount = ___magic__import__(\'@/composables\', \'useCartCount\');\nconst get = ___magic__import__(\'lodash-es\', \'get\');\r\nconst set = ___magic__import__(\'lodash-es\', \'set\');\nconst __sfc__ = _defineComponent({\n  __name: \'ad3ae3d24d02f2931f4f4aa30505b0fe\',\n  setup(__props, {\n    expose: __expose\n  }) {\n    const {\n      refresh: refreshCartCount\n    } = useCartCount();\n\n    // refs\n    const applyFormRef = ref();\n    const store = useRegisterStore();\n    const {\n      state\n    } = storeToRefs(store);\n\n    // 当前申请单信息\n    const applyData = computed({\n      get: () => {\n        if (!get(store.data, "apply")) {\n          set(store.data, "apply", {});\n        }\n        return get(store.data, "apply", {});\n      },\n      set: val => set(store.data, "apply", val)\n    });\n\n    // 验证表单\n    const validate = async () => {\n      await applyFormRef.value?.validate();\n    };\n\n    // 保存单个申请单\n    const saveApi = data => {\n      // applyResource 保存为目录 tid 数组\n      return $common.post("/dws/market/applyForm/saveOrUpdate", {\n        tid: data.tid,\n        type: "catalogSubscribe",\n        propList: {\n          ...data\n        }\n      });\n    };\n    const save = async () => {\n      try {\n        state.value.loadStatus["main"] = true;\n        await validate();\n        const isUpdate = !!applyData.value.tid;\n        const saveData = await applyFormRef.value?.getFormData();\n\n        // 保持一个目录一条申请记录，便于后续分别维护和撤销。\n        let saveBatchList = [];\n        const catalogIds = saveData.applyResource?.map(el => el.tid);\n        if (!isUpdate) {\n          // 新增：每个目录都是新申请单\n          saveBatchList = catalogIds.map(id => ({\n            ...saveData,\n            applyResource: [id],\n            applyName: saveData.applyResource.find(el => el.tid === id)?.catalogName\n          }));\n        } else {\n          // 编辑：用逗号分隔的 tid 匹配\n          const tids = applyData.value.tid.split(",");\n          saveBatchList = catalogIds.map((id, ind) => ({\n            ...saveData,\n            applyResource: [id],\n            tid: tids[ind],\n            applyName: saveData.applyResource.find(el => el.tid === id)?.catalogName\n          }));\n        }\n\n        // 并行保存所有申请单\n        const res = await Promise.all(saveBatchList.map(el => saveApi(el)));\n\n        // 新增申请单则更新购物车目录数\n        if (!isUpdate) {\n          refreshCartCount();\n        }\n\n        // 合并所有 tid 用逗号连接\n        applyData.value = Object.assign(applyData.value, saveData, {\n          tid: res.map(el => el.tid).join(",")\n        });\n        return {\n          success: true,\n          msg: "保存成功"\n        };\n      } catch (err) {\n        return {\n          success: false,\n          msg: err.message || err\n        };\n      } finally {\n        state.value.loadStatus["main"] = false;\n      }\n    };\n    const next = () => {\n      if (!applyData.value?.tid) {\n        throw "请保存";\n      }\n    };\n    const commit = async () => {\n      next();\n      const saveData = await applyFormRef.value?.getFormData();\n      const finishData = saveData.applyResource?.map(el => ({\n        ...el,\n        assetType: "catalog",\n        assetName: el.catalogName,\n        applyTime: saveData.applyTime\n      }));\n      store.data["finish"] = finishData;\n      await finish();\n    };\n    const finish = async () => {\n      next();\n      const tids = applyData.value.tid.split(",");\n      const apis = tids.map(tid => $common.post("/dws/market/submit", {\n        flowOrderId: tid\n      }));\n      await Promise.all(apis);\n      $message.success("申请已直接生效");\n      store.handleAction("next");\n    };\n    const print = () => {\n      applyFormRef.value?.openPrint();\n    };\n\n    // 暴露方法给父组件\n    __expose({\n      save,\n      next,\n      commit,\n      print\n    });\n    return (_ctx, _cache) => {\n      const _component_apply_json_form = _resolveComponent("apply-json-form");\n      return _openBlock(), _createElementBlock("div", _hoisted_1, [_createVNode(_component_apply_json_form, {\n        ref_key: "applyFormRef",\n        ref: applyFormRef,\n        "init-data": applyData.value,\n        copy: _unref(store).data.editType === \'再次申请\'\n      }, null, 8 /* PROPS */, ["init-data", "copy"])]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "ref": "setup-const",\n  "computed": "setup-const",\n  "onMounted": "setup-const",\n  "storeToRefs": "setup-maybe-ref",\n  "useRegisterStore": "setup-maybe-ref",\n  "useCartCount": "setup-maybe-ref",\n  "get": "setup-maybe-ref",\n  "set": "setup-maybe-ref",\n  "refreshCartCount": "setup-maybe-ref",\n  "applyFormRef": "setup-ref",\n  "store": "setup-maybe-ref",\n  "state": "setup-maybe-ref",\n  "applyData": "setup-ref",\n  "validate": "setup-const",\n  "saveApi": "setup-const",\n  "save": "setup-const",\n  "next": "setup-const",\n  "commit": "setup-const",\n  "finish": "setup-const",\n  "print": "setup-const"\n} */\n__sfc__.__file = "ad3ae3d24d02f2931f4f4aa30505b0fe.vue"\nreturn __sfc__','/* No <style> tags present */','1','订阅申请单',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2008470019165982720','2007661287158910976','catalog-collect','<template>\r\n  <div v-loading="state.loading" class="card-container h-auto flex-1 flex flex-col pt-5 px-5 pb-2">\r\n    <data-table\r\n      ref="tableRef"\r\n      :key="state.cols.length"\r\n      :show-page="false"\r\n      :columns="state.cols"\r\n      :data="state.data"\r\n      :size="route.path.includes(\'/market\') ? \'large\' : \'default\'"\r\n      @filter-change="handleClick"\r\n    >\r\n      <template #empty>\r\n        <empty>\r\n          <template #description>{{ state.error || "暂无数据" }}</template>\r\n        </empty>\r\n      </template>\r\n    </data-table>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, reactive, computed } from "vue";\r\nimport { useRoute } from "vue-router";\r\nimport { useDebounceFn } from "@vueuse/core";\r\n\r\nconst route = useRoute();\r\nconst props = defineProps({\r\n  catalogId: { type: String, default: "0d50a16cf9b5458398a22f6fa158ea57" },\r\n});\r\n\r\n// refs\r\nconst tableRef = ref();\r\nconst state = reactive<any>({\r\n  catalogInfo: {},\r\n  cols: [],\r\n  data: [],\r\n  loading: false,\r\n  editing: false,\r\n  filters: {},\r\n  error: "",\r\n  targetTableId: "",\r\n});\r\nconst filterChange = (item?: any) => {\r\n  state.filters = item;\r\n  getData();\r\n};\r\n// 过滤触发防抖函数\r\nconst handleClick = useDebounceFn(filterChange, 500, {\r\n  // maxWait: 2000, // 最大等待时间（即使没到延迟，超过maxWait也会触发）\r\n});\r\nconst init = async () => {\r\n  if (!props.catalogId) {\r\n    return;\r\n  }\r\n  state.loading = true;\r\n  try {\r\n    if (state.catalogInfo.tid === props.catalogId) {\r\n      return;\r\n    }\r\n    const [catalog, cols = []] = await Promise.all([\r\n      $common.post("/dst/catalog/detail", {\r\n        tid: props.catalogId,\r\n      }),\r\n      $common.post("/dst/catalog/catalog-items/list", {\r\n        tid: props.catalogId,\r\n      }),\r\n    ]);\r\n    state.catalogInfo = catalog;\r\n\r\n    // 获取目录数据项 .filter((el) => el.targetTableColumnId)\r\n    // state.cols = cols.map((el) => ({\r\n    //   label: el.colName,\r\n    //   prop: "",\r\n    //   targetTableColumnId: el.targetTableColumnId,\r\n    //   filterable: true,\r\n    // }));\r\n\r\n    // 获取挂接表字段及数据\r\n    const targetTableId = catalog.targetTableId;\r\n    state.targetTableId = catalog.targetTableId;\r\n    if (!targetTableId) {\r\n      return;\r\n    }\r\n    await $common.get("/dst/database/metadata/columns", { tid: targetTableId }).then((data) => {\r\n      state.cols = data.map((el) => ({\r\n        label: el.columnName,\r\n        prop: el.columnName,\r\n        filterable: true,\r\n      }));\r\n      // // 根据挂接映射字段关系，修改cols中的 prop\r\n      // data.forEach((item) => {\r\n      //   const { columnName, tid } = item;\r\n      //   const col = state.cols.find((el) => el.targetTableColumnId === tid);\r\n      //   if (col) {\r\n      //     col.prop = columnName;\r\n      //   }\r\n      // });\r\n    });\r\n    getData();\r\n  } finally {\r\n    state.loading = false;\r\n  }\r\n};\r\nconst getData = (tableId = state.targetTableId) => {\r\n  if (!state.targetTableId) return;\r\n  state.loading = true;\r\n  $common\r\n    .post("/dst/database/metadata/table/preview-data", {\r\n      tableId,\r\n      pageNo: 1,\r\n      pageSize: 20,\r\n      conditions: state.filters,\r\n    })\r\n    .then((data: any) => {\r\n      const { rows } = data;\r\n      state.data = rows || [];\r\n      state.error = "";\r\n      state.loading = false;\r\n    })\r\n    .catch((err) => {\r\n      state.error = err.message || "获取数据失败";\r\n      state.loading = false;\r\n    });\r\n};\r\n\r\nwatch(\r\n  () => props.catalogId,\r\n  (newVal) => {\r\n    if (newVal) {\r\n      init();\r\n    }\r\n  },\r\n  { immediate: true }\r\n);\r\n</script>\r\n\r\n<style scoped la