 conditions: state.filters\n      }).then(data => {\n        const {\n          rows\n        } = data;\n        state.data = rows || [];\n        state.error = "";\n        state.loading = false;\n      }).catch(err => {\n        state.error = err.message || "获取数据失败";\n        state.loading = false;\n      });\n    };\n    watch(() => props.catalogId, newVal => {\n      if (newVal) {\n        init();\n      }\n    }, {\n      immediate: true\n    });\n    return (_ctx, _cache) => {\n      const _component_empty = _resolveComponent("empty");\n      const _component_data_table = _resolveComponent("data-table");\n      const _directive_loading = _resolveDirective("loading");\n      return _withDirectives((_openBlock(), _createElementBlock("div", _hoisted_1, [(_openBlock(), _createBlock(_component_data_table, {\n        ref_key: "tableRef",\n        ref: tableRef,\n        key: state.cols.length,\n        "show-page": false,\n        columns: state.cols,\n        data: state.data,\n        size: _unref(route).path.includes(\'/market\') ? \'large\' : \'default\',\n        onFilterChange: _unref(handleClick)\n      }, {\n        empty: _withCtx(() => [_createVNode(_component_empty, null, {\n          description: _withCtx(() => [_createTextVNode(_toDisplayString(state.error || "暂无数据"), 1 /* TEXT */)]),\n          _: 1 /* STABLE */\n        })]),\n        _: 1 /* STABLE */\n      }, 8 /* PROPS */, ["columns", "data", "size", "onFilterChange"]))])), [[_directive_loading, state.loading]]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "catalogId": "props",\n  "ref": "setup-const",\n  "watch": "setup-const",\n  "reactive": "setup-const",\n  "computed": "setup-const",\n  "useRoute": "setup-maybe-ref",\n  "useDebounceFn": "setup-maybe-ref",\n  "route": "setup-maybe-ref",\n  "props": "setup-reactive-const",\n  "tableRef": "setup-ref",\n  "state": "setup-reactive-const",\n  "filterChange": "setup-const",\n  "handleClick": "setup-maybe-ref",\n  "init": "setup-const",\n  "getData"