INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018613836888215552','2007661287158910976','catalog-market-res','<template>\r\n  <div v-loading="state.loading" class="card-container py-2 px-5">\r\n    <div>\r\n      <u-title name="库表资源信息"></u-title>\r\n      <data-table\r\n        show-index\r\n        :show-page="false"\r\n        :columns="state.cols"\r\n        :data="state.data"\r\n        size="large"\r\n      >\r\n        <template #column-tableNameCn="{ row }">\r\n          <el-text>\r\n            <Icon icon="table" />\r\n            {{ row.tableNameCn }}\r\n          </el-text>\r\n        </template>\r\n      </data-table>\r\n    </div>\r\n\r\n    <!--    <div>-->\r\n    <!--      <u-title name="接口资源信息"></u-title>-->\r\n    <!--    </div>-->\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { reactive, onMounted } from "vue";\r\n\r\nconst props = defineProps({\r\n  catalogId: String,\r\n});\r\n\r\nconst state = reactive<any>({\r\n  loading: false,\r\n  cols: [],\r\n  data: [],\r\n  api: {},\r\n  reqCols: [],\r\n  reqData: [],\r\n  respCols: [],\r\n  respData: [],\r\n});\r\n\r\nstate.cols = [\r\n  { label: "资源名称", prop: "tableNameCn" },\r\n  { label: "库表名称", prop: "tableName" },\r\n  { label: "数据库类型", prop: "dbType" },\r\n  { label: "字段数", prop: "fieldCount", maxWidth: 200, props: { suffix: "个" } },\r\n  { label: "数据量", prop: "recordCount", maxWidth: 120, props: { suffix: "条" } },\r\n];\r\n\r\nstate.data = [\r\n  {\r\n    assetName: "广电家庭用户收视行为统计数据表",\r\n    tableName: "statistical_radio_users_table",\r\n    dbType: "oracle",\r\n    columnTotal: "14",\r\n    dataTotal: "18",\r\n  },\r\n];\r\n\r\nonMounted(() => {\r\n  init();\r\n});\r\n\r\nconst init = async () => {\r\n  if (!props.catalogId) return;\r\n  state.loading = true;\r\n  try {\r\n    const catalog = await $common.post("/dst/catalog/detail", {\r\n      t