 break;\n        }\n        const newData = data?.list || [];\n        if (loadMore) {\n          state.rightList = [...state.rightList, ...newData];\n          state.rightPage++;\n        } else {\n          state.rightList = newData;\n        }\n        state.hasMoreRight = newData.length === state.pageSize;\n      } catch (error) {\n        console.error("加载列表失败", error);\n        $message.error("加载列表失败");\n      } finally {\n        state.loading[type] = false;\n        state.loading.rightLoadMore = false;\n      }\n    };\n\n    // 处理挂接操作\n    const handleAttach = async (type, item) => {\n      if (!props.catalogId) return;\n      if (type === "table" && state.catalogInfo.targetTableId) {\n        // 数据表挂接时，检查是否已存在挂接表\n        const confirmResult = await $dialog.confirm("当前目录已挂接数据表，重新挂接表可能会造成流程异常，请谨慎操作！", "是否替换为新表？", {\n          confirmButtonText: "确定",\n          cancelButtonText: "取消",\n          type: "warning"\n        });\n        if (confirmResult !== "confirm") {\n          return;\n        }\n      }\n      try {\n        // 调用挂接接口\n        await $common.post("/dst/catalog/saveOrUpdate", {\n          tid: props.catalogId,\n          assetType: "catalog",\n          propList: {\n            [type === "table" ? "targetTableId" : type === "api" ? "apiId" : "fileId"]: item.id\n          }\n        });\n        $message.success("挂接成功");\n\n        // 更新目录信息\n        $common.post("/dst/catalog/detail", {\n          tid: props.catalogId\n        }).then(data => {\n          nextTick(() => {\n            state.catalogInfo = {\n              ...data\n            };\n            useDetailStore().setData(data);\n          });\n        });\n        state.open = false;\n        // 重新初始化数据\n        if (type === "table") {\n          initTable();\n        } else if (type === "api") {\n          initApi();\n        } else if (type === "file") {\n          initFile();\n        }\n      } catch (error) {\n        console.error("挂接失败", error);\n        $message.error("挂接失败");\n      }\n    };\n\n    // 处理移除操作\n    const handleRemove = async (type, id) => {\n      if (!props.catalogId) return;\n      try {\n        // 显示确认提示\n        await $dialog.confirm(`确定要移除该${type === "table" ? "数据表" : type === "api" ? "API服务" : "文件"}吗？`, "确认移除", {\n          confirmButtonText: "确定",\n          cancelButtonText: "取消",\n          type: "warning"\n        });\n\n        // 调用移除接口\n        await $common.post("/dst/catalog/saveOrUpdate", {\n          tid: props.catalogId,\n          assetType: "catalog",\n          propList: {\n            [type === "table" ? "targetTableId" : type === "api" ? "apiId" : "fileId"]: ""\n          }\n        });\n        $message.success("移除成功");\n        // 重新初始化数据\n        if (type === "table") {\n          initTable();\n        } else if (type === "api") {\n          initApi();\n        } else if (type === "file") {\n          initFile();\n        }\n      } catch (error) {\n        console.error("移除失败", error);\n      }\n    };\n\n    // 删除建表\n    const handleDeleteTable = () => {\n      $common.handle({\n        url: "/ods/cleanup-rebuild",\n        info: "删除挂接资源，任务同步删除，是否继续？",\n        action: "移除",\n        data: {\n          tid: props.catalogId\n        },\n        done: () => {\n          state.catalogInfo.targetTableId = "";\n        }\n      });\n    };\n    return (_ctx, _cache) => {\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_text = _resolveComponent("el-text");\n      const _component_dict_label = _resolveComponent("dict-label");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_data_table = _resolveComponent("data-table");\n      const _component_el_link = _resolveComponent("el-link");\n      const _component_empty = _resolveComponent("empty");\n      const _component_el_input = _resolveComponent("el-input");\n      const _component_el_scrollbar = _resolveCo