INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2017170778183241728','2014615745029804032','category-drawer','<template>\r\n  <el-drawer\r\n    title="选择数据目录"\r\n    :size="600"\r\n    :model-value="visible"\r\n    :show-close="false"\r\n    :body-class="\'category-drawer_body\'"\r\n    @update:model-value="(val) => emit(\'update:visible\', val)"\r\n  >\r\n    <template #header>\r\n      <div class="category-drawer-header">\r\n        <h3 class="title">选择数据目录</h3>\r\n        <el-input\r\n          v-model="searchQuery"\r\n          placeholder="搜索目录"\r\n          clearable\r\n          style="width: 300px"\r\n          @input="handleSearch"\r\n        >\r\n          <template #prefix>\r\n            <Icon icon="el-icon-search"></Icon>\r\n          </template>\r\n        </el-input>\r\n      </div>\r\n    </template>\r\n\r\n    <div class="category-drawer-content">\r\n      <div class="category-drawer-search flex gap-2">\r\n        <el-select\r\n          v-model="appValue"\r\n          placeholder="选择应用系统"\r\n          clearable\r\n          style="width: 180px"\r\n          @change="handleSearch"\r\n        >\r\n          <el-option\r\n            v-for="item in appSystemOptions"\r\n            :key="item.value"\r\n            :label="item.label"\r\n            :value="item.value"\r\n          />\r\n        </el-select>\r\n        <el-tree-select\r\n          v-model="orgValue"\r\n          :data="orgOptions"\r\n          :node-key="\'value\'"\r\n          default-expand-all="true"\r\n          check-strictly="true"\r\n          placeholder="选择提供部门"\r\n          clearable\r\n          style="width: 180px"\r\n          @change="handleSearch"\r\n        ></el-tree-select>\r\n        <el-select\r\n          v-model="categoryTypeValue"\r\n          placeholder="选择目录类型"\r\n          clearable\r\n          style="width: 180px"\r\n          @change="handleSearch"\r\n        >\r\n          <el-option\r\n            v-for="item in categoryTypeOptions"\r\n            :key="item.value"\r\n            :label="item.label"\r\n            :value="item.value"\r\n          />\r\n        </el-select>\r\n      </div>\r\n      <div class="infinite-list-wrapper" style="overflow: auto">\r\n        <ul v-infinite-scroll="load" class="list" :infinite-scroll-disabled="disabled">\r\n          <li v-for="item in listData" :key="item.id" class="list-item">\r\n            <div class="list-item-content">\r\n              <div class="item-header">\r\n                <el-checkbox\r\n                  v-model="item.checked"\r\n                  :class="{ checked: item.checked }"\r\n                  @change="handleCheckboxChange(item)"\r\n                ></el-checkbox>\r\n                <Icon icon="category" class="ml-3 mr-1"></Icon>\r\n                <span class="catalog-name">{{ item.catalogName }}</span>\r\n              </div>\r\n              <div class="item-resources">{{ item.resources }}</div>\r\n            </div>\r\n          </li>\r\n        </ul>\r\n        <p v-if="loading">加载中...</p>\r\n        <p v-if="noMore">没有更多了</p>\r\n      </div>\r\n    </div>\r\n\r\n    <template #footer>\r\n      <div class="flex" style="justify-content: end">\r\n        <el-button type="primary" @click="handleConfirm">\r\n          <Icon icon="save" class="mr-2" />\r\n          确定\r\n        </el-button>\r\n        <el-button :icon="\'el-icon-Close\'" @click="handleCancel">取消</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, onMounted, computed } from "vue";\r\nimport { useDictStore } from "@/store";\r\nimport { ElMessage } from "element-plus";\r\n// Props\r\nconst props = defineProps({\r\n  visible: {\r\n    type: Boolean,\r\n    default: false,\r\n  },\r\n  selectedData: {\r\n    type: Array,\r\n    default: () => [],\r\n  },\r\n  useTree: {\r\n    type: Boolean,\r\n    default: false,\r\n  },\r\n});\r\n\r\n// Emits\r\nconst emit = defineEmits(["update:visible", "confirm", "close"]);\r\n\r\n// Refs\r\nconst appValue = ref("");\r\nconst orgValue = ref("");\r\nconst categoryTypeValue = ref("");\r\nconst appSystemOptions = ref([\r\n  { label: "电视剧管理系统", value: "1" },\r\n  { label: "政务服务门户", value: "2" },\r\n  { label: "政务服务运行管理系统", value: "3" },\r\n  { label: "合作制作电视剧审批系统", value: "4" },\r\n  { label: "接收设施进口证明核发系统", value: "5" },\r\n]);\r\nconst categoryTypeOptions = ref([\r\n  { label: "部门目录", value: "1" },\r\n  { label: "主题目录", value: "2" },\r\n]);\r\nconst orgOptions = useDictStore().getDictItems("org");\r\nconst searchQuery = ref("");\r\nconst selectedRows = ref([]);\r\nconst listData = ref([\r\n  {\r\n    id: "1",\r\n    catalogName: "一般题材备案数据目录",\r\n    resources: "ods_general_subject_data",\r\n    sourceAppSystem: "电视剧管理系统",\r\n    sourceTableName: "general_subject_data",\r\n    dataType: "1",\r\n    authorityUnit: "国家广播电视总局 / 电视剧司",\r\n    recordCount: "——",\r\n    updateCycle: "——",\r\n    latestUpdateTime: "——",\r\n    latestBusinessTime: "——",\r\n    relatedTask: "去接入>",\r\n  },\r\n  {\r\n    id: "2",\r\n    catalogName: "重大题材立项数据目录",\r\n    resources: "ods_major_subject_data",\r\n    sourceAppSystem: "电视剧管理系统",\r\n    sourceTableName: "major_subject_data",\r\n    dataType: "2",\r\n    authorityUnit: "国家广播电视总局 / 电视剧司",\r\n    recordCount: 30000,\r\n    updateCycle: "实时",\r\n    latestUpdateTime: "2025-12-26 11:30:00",\r\n    latestBusinessTime: "2025-12-26 10:20:00",\r\n    relatedTask: "重大题材立项数据增量取",\r\n  },\r\n  {\r\n    id: "3",\r\n    catalogName: "完成剧申报数据目录",\r\n    resources: "ods_completed_drama_data",\r\n    sourceAppSystem: "电视剧管理系统",\r\n    sourceTableName: "completed_drama_data",\r\n    dataType: "1",\r\n    authorityUnit: "国家广播电视总局 / 电视剧司",\r\n    recordCount: 5000,\r\n    updateCycle: "每周",\r\n    latestUpdateTime: "2025-12-24 08:00:00",\r\n    latestBusinessTime: "2025-12-20 22:00:00",\r\n  