,\n      field: "appIcon",\n      value: "logo1",\n      $required: true\n    }, {\n      type: "el-input",\n      field: "description",\n      title: "应用摘要",\n      props: {\n        type: "textarea",\n        placeholder: "简要描述该应用的业务场景与核心功能...",\n        maxlength: 500,\n        rows: 4,\n        showWordLimit: true\n      }\n    }]);\n    const formOptions = ref({\n      form: {\n        labelWidth: "100px"\n      }\n    });\n    const visible = computed({\n      get: () => props.modelValue,\n      set: value => {\n        emit("update:modelValue", value);\n      }\n    });\n\n    // 处理图标选择\n    const handleIconSelect = async (value, scope) => {\n      // 如果 value 是对象，使用其 url 属性\n      const iconValue = typeof value === "object" && value.url ? value.url : value;\n      scope.model.value = iconValue;\n      // 修正字段名为 appIcon，与表单配置一致\n      formRef.value?.setValue({\n        appIcon: iconValue\n      });\n      // 强制刷新表单，确保视图更新\n      await nextTick();\n      formRef.value?.refresh();\n    };\n\n    // 上传前校验\n    const handleBeforeUpload = async file => {\n      const isImage = file.type.startsWith("image/");\n      if (!isImage) {\n        ElMessage.warning("只能上传图片文件！");\n        return false;\n      }\n      const isLt10M = file.size / 1024 / 1024 < 10;\n      if (!isLt10M) {\n        ElMessage.warning("上传图片大小不能超过 10MB！");\n        return false;\n      }\n      return true;\n    };\n\n    // 处理文件上传\n    const handleUpload = options => {\n      return new Promise((resolve, reject) => {\n        FileAPI.uploadFile(options.file).then(res => {\n          resolve(res);\n        }).catch(err => {\n          reject(err);\n        });\n      });\n    };\n    const handleSuccess = async res => {\n      // 添加到图标库\n      await $common.post("/das/repository/icon/add", {\n        appIcon: res.preView\n      });\n      fetchUserIcons();\n    };\n\n    // 移除上传的图标\n    const removeUploadedIcon = async url => {\n      const index = imgList.value.findIndex(item => item.url === url);\n      if (index === -1) return;\n      const file = imgList.value[index];\n      const tid = file.tid || file.response?.tid || "";\n      if (!tid) return;\n      try {\n        // 调用图标库删除接口\n        await $common.post("/das/repository/icon/delete", {\n          tid\n        });\n        // 直接从 imgList 移除，v-for 自动更新视图\n        imgList.value.splice(index, 1);\n        await nextTick();\n        formRef.value?.refresh();\n      } catch (error) {\n        console.error("删除图标失败:", error);\n      }\n    };\n\n    // 提交表单\n    const handleSubmit = async () => {\n      try {\n        // 验证表单\n        await formRef.value.validate();\n        const formData = await formRef.value?.getFormData();\n        emit("submit", {\n          ...formData,\n          tid: props.appId\n        });\n        visible.value = false;\n      } catch (error) {\n        console.error("表单验证失败:", error);\n      }\n    };\n\n    // 关闭模态框\n    const handleClose = () => {\n      // 重置表单\n      formRef.value?.resetFields();\n      visible.value = false;\n      emit("close");\n    };\n\n    // 监听 appData 变化，设置表单值\n    watch(() => props.appData, newVal => {\n      if (newVal && props.modelValue) {\n        nextTick(() => {\n          formRef.value?.setValue(newVal);\n        });\n      }\n    });\n\n    // 监听 modal 显示状态\n    watch(() => props.modelValue, newVal => {\n      if (newVal && props.appData) {\n        nextTick(() => {\n          formRef.value?.setValue(props.appData);\n        });\n      }\n    });\n    onMounted(() => {\n      // 获取用户上传的图标列表\n      fetchUserIcons();\n      if (props.appData) {\n        nextTick(() => {\n          formRef.value?.setValue(props.appData);\n        });\n      }\n    });\n    return (_ctx, _cache) => {\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_icon = _resolveComponent("el-icon");\n      const _component_el_upload = _resolveComponent("el-upload");\n      const _component_json_form = _resolveComponent("json-form");\n   