ree-container .custom-tree-node[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  display: flex;\n  align-items: center;\n  width: 100%;\n  padding-right: 10px;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .node-label[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .node-icon-folder[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  color: #0b8bf9;\n  margin-right: 6px;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .node-icon-folder[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .icon {\n  width: 23px !important;\n  height: 23px !important;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .more-icon[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  opacity: 0;\n  cursor: pointer;\n  transition: opacity 0.2s;\n  font-size: 16px;\n  color: #909399;\n  padding: 4px;\n  border-radius: 4px;\n  outline: none;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .more-icon[data-v-2567d0afe2d7140dbf0f151ad7f2c866]:hover {\n  color: var(--el-color-primary);\n  background-color: var(--el-color-primary-light-9);\n  outline: none;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .more-icon[data-v-2567d0afe2d7140dbf0f151ad7f2c866]:focus {\n  outline: none;\n}\n.data-catalog-content .left-panel .tree-container .custom-tree-node .more-icon.visible[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  opacity: 1;\n}\n.data-catalog-content .left-panel .tree-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .el-tree-node__content:hover .more-icon {\n  opacity: 1;\n}\n.data-catalog-content .left-panel .tree-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .el-tree-node__content.is-current {\n  background-color: var(--el-color-primary-light-9) !important;\n  color: var(--el-color-primary);\n}\n.data-catalog-content .left-panel .tree-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .el-dropdown-menu__item.delete-item:hover {\n  background-color: #fef0f0;\n}\n.data-catalog-content .right-panel[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  width: 100%;\n  height: 100%;\n}\n.data-catalog-content .right-panel[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .el-button .el-icon + span {\n  margin-left: 3px;\n}\n[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .dialog-footer-custom {\n  border-top: none;\n}\n.category-info[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  position: relative;\n}\n.category-content[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  max-height: 300px;\n  overflow-y: auto;\n}\n.category-content .category-item[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  display: flex;\n  align-items: center;\n  margin-bottom: 5px;\n}\n.category-content .category-label[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  font-weight: 500;\n}\n.category-content .category-value[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  flex: 2;\n  margin-right: 10px;\n  word-break: break-all;\n}\n.category-content .category-value[data-v-2567d0afe2d7140dbf0f151ad7f2c866] .dict-text {\n  margin-right: 5px;\n}\n.category-content .remove-btn[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  flex-shrink: 0;\n  color: #f56c6c;\n}\n.loading-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866],\n.error-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866],\n.empty-category[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  padding: 20px;\n  text-align: center;\n}\n.loading-container[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  min-height: 150px;\n}\n.empty-category[data-v-2567d0afe2d7140dbf0f151ad7f2c866] {\n  color: #909399;\n}','1','2.5.2 数据目录',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2006256270447284224','2005563932859240448','data-category-drawer','<template>\r\n  <el-drawer\r\n    v-model="visible"\r\n    :title="isBatch ? \'批量分类\' : \'目录分类\'"\r\n    :size="600"\r\n    :destroy-on-close="true"\r\n    @close="handleClose"\r\n  >\r\n    <div class="category-drawer-content">\r\n      <!-- 已选资产列表（批量时显示） -->\r\n      <div v-if="isBatch" class="selected-assets">\r\n        <div v-for="(item, index) in selectedAssets" :key="index" class="asset-item">\r\n          <div class="asset-info">\r\n            <Icon icon="catalog" class="mr-2" />\r\n            <span class="data-asset-name">{{ item.catalogName }}</span>\r\n          </div>\r\n          <Icon icon="el-icon-Close" class="close-icon" @click="handleRemoveAsset(index)" />\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 非批量时的资产名称 -->\r\n      <div v-else class="single-asset-name">\r\n        <Icon icon="catalog" class="mr-2" />\r\n        <span>{{ selectedAssets[0]?.catalogName }}</span>\r\n      </div>\r\n\r\n      <el-divider />\r\n\r\n      <!-- 已选类目标签 -->\r\n      <div v-if="choosedCategoryList.length > 0" class="selected-categories">\r\n        <div class="category-label">已选:</div>\r\n        <div class="category-tags">\r\n          <template v-for="item in choosedCategoryList" :key="item.field">\r\n            <div v-for="(label, index) in item.label" :key="index" class="category-item">\r\n              <Icon icon="folder" :color="\'#0b8bf9\'" class="mr-1" />\r\n              <span>{{ label }}</span>\r\n            </div>\r\n          </template>\r\n        </div>\r\n      </div>\r\n\r\n      <el-divider v-if="choosedCategoryList.length > 0" />\r\n\r\n      <!-- 类目选择区域 -->\r\n      <div class="category-section">\r\n        <div class="category-title">所属类目:</div>\r\n        <div class="category-tree-container">\r\n          <el-tabs\r\n            v-if="props.categoryConfig.length > 0"\r\n            v-model="activeTab"\r\n            tab-position="left"\r\n            @tab-change="(name: any) => handleTabChange(name as string)"\r\n          >\r\n            <el-tab-pane\r\n              v-for="item in props.categoryConfig"\r\n              :key="item.field"\r\n              :label="item.title"\r\n              :name="item.field"\r\n            >\r\n              <div\r\n                v-if="!categoryTreeData[item.field] || categoryTreeData[item.field].length === 0"\r\n                class="empty-tree"\r\n              >\r\n                <el-empty description="暂无类目数据" :image-size="60" />\r\n              </div>\r\n              <el-tree\r\n                v-else\r\n                :ref="(el) => setTreeRef(item.field, el)"\r\n                :data="categoryTreeData[item.field]"\r\n                :props="treeProps"\r\n                :expand-on-click-node="false"\r\n                :check-strictly="true"\r\n                show-checkbox\r\n                node-key="value"\r\n                :default-expand-all="true"\r\n                :default-checked-keys="getCheckedKeys(item.field)"\r\n                @check-change="(_node: any, check: boolean) => handleTreeCheckChange(_node, check)"\r\n                @check="(_node: any, checkedStatus: any) => handleTreeCheck(checkedStatus, item)"\r\n              >\r\n                <template #default="{ node, data }">\r\n                  <div class="tree-node-label">\r\n                    <Icon v-if="!data.children?.length" :icon="\'file\'" class="mr-1" />\r\n                    <Icon\r\n                      v-else\r\n                      :icon="node.expanded ? \'folder-open\' : \'folder\'"\r\n                      :color="\'#0b8bf9\'"\r\n                      class="mr-1"\r\n                    />\r\n                    <span>{{ node.label }}</span>\r\n                  </div>\r\n                </template>\r\n              </el-tree>\r\n            </el-tab-pane>\r\n          </el-tabs>\r\n          <el-empty v-else description="暂无类目配置" :image-size="60" />\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <template #footer>\r\n      <div class="drawer-footer">\r\n        <el-button @click="handleClose">取消</el-button>\r\n        <el-button type="primary" :disabled="btnLoading" @click="handleSave">保存</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, computed } from "vue";\r\nimport { findTreeNodeByTid } from "@/utils";\r\n\r\ninterface CategoryItem {\r\n  field: string;\r\n  title: string;\r\n  label?: string;\r\n  $dict?: string;\r\n  fieldShow?: boolean;\r\n  fieldSortNo?: number;\r\n  props?: {\r\n    options?: any[];\r\n    multiple?: boolean;\r\n    filters?: {\r\n      [key: string]: string;\r\n    };\r\n    [key: string]: any;\r\n  };\r\n}\r\n\r\ninterface AssetItem {\r\n  tid: string;\r\n  catalogName: string;\r\n  [key: string]: any;\r\n}\r\n\r\nconst props = defineProps<{\r\n  modelValue: boolean;\r\n  selectedAssets: AssetItem[];\r\n  isBatch?: boolean;\r\n  categoryConfig: CategoryItem[];\r\n  categoryOptionsMap?: Record<string, any[]>;\r\n}>();\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", value: boolean): void;\r\n  (e: "update:selectedAssets", value: AssetItem[]): void;\r\n  (e: "success"): void;\r\n}>();\r\n\r\nconst visible = computed({\r\n  get: () => props.modelValue,\r\n  set: (val) => emit("update:modelValue", val),\r\n});\r\n\r\n// 类目树数据\r\nconst categoryTreeData = ref<Record<string, OptionType[]>>({});\r\n// 已选类目列表\r\nconst choosedCategoryList = ref<{ field: string; label: string[]; value: string[] }[]>([]);\r\n// 当前选中的 tab\r\nconst activeTab = ref("");\r\n// 按钮 loading\r\nconst btnLoading = ref(false);\r\n// 树组件引用\r\nconst treeRefs = ref<Record<string, any>>({});\r\n\r\n// 设置树组件引用\r\nconst setTreeRef = (field: string, el: any) => {\r\n  if (el) {\r\n    treeRefs.value[field] = el;\r\n  }\r\n};\r\n\r\n// 树组件配置\r\nconst treeProps = {\r\n  children: "children",\r\n  label: "label",\r\n  value: "value",\r\n};\r\n\r\n// 获取类目配置和树数据\r\nconst fetchCategoryData = async () => {\r\n  if (!props.selectedAssets || props.selectedAssets.length === 0) return;\r\n\r\n  // 直接使用父组件传入的已解析配置，不再重复请求\r\n  activeTab.value = props.categoryConfig[0]?.field || "";\r\n\r\n  // 从 categoryOptionsMap 中取已解析的 options\r\n  if (props.categoryOptionsMap) {\r\n    categoryTreeData.value = { ...props.categoryOptionsMap };\r\n  }\r\n\r\n  // 当不是批量分类时，才获取已选类目数据\r\n  if (!props.isBatch && props.selectedAssets.length > 0) {\r\n    await fetchCurrentCategories();\r\n  }\r\n};\r\n\r\n// 获取当前选中资产的类目数据\r\nconst fetchCurrentCategories = async () => {\r\n  const firstAsset = props.selectedAssets[0];\r\n  if (!firstAsset?.tid) return;\r\n\r\n  try {\r\n    const response = await $common.post("/dst/catalog/detail", {\r\n      tid: firstAsset.tid,\r\n    });\r\n    const data = response.data || response;\r\n\r\n    // 根据配置处理每个类目字段\r\n    choosedCategoryList.value = [];\r\n    props.categoryConfig.forEach((config) => {\r\n      const value = data[config.field];\r\n      if (value !== undefined && value !== null && value !== "") {\r\n        const values = value.includes(",") ? value.split(",") : [value];\r\n\r\n        choosedCategoryList.value.push({\r\n          field: config.field,\r\n          label: getCheckLabels(config.field, values),\r\n          value: values,\r\n        });\r\n      }\r\n    });\r\n  } catch (error) {\r\n    console.error("获取资产类目失败:", error);\r\n  }\r\n};\r\n\r\nconst getCheckLabels = (field: string, value: string[]) => {\r\n  const treeData = categoryTreeData.value[field];\r\n  if (!treeData || !treeData.length) return [];\r\n\r\n  const labels = value.map((v) => {\r\n    const node = findTreeNodeByTid(treeData, v, "value");\r\n    return node ? node.label : v;\r\n  });\r\n\r\n  return labels;\r\n};\r\n\r\n// 获取已选中的 key\r\nconst getCheckedKeys = (field: string): string[] => {\r\n  const category = choosedCategoryList.value.find((item) => item.field === field);\r\n  if (!category) return [];\r\n  return category.value;\r\n};\r\n\r\nlet currentCheckNode: any = {};\r\nconst handleTreeCheckChange = (node: any, check: boolean) => {\r\n  currentCheckNode = check ? node : {};\r\n};\r\n// 处理树节点选择\r\nconst handleTreeCheck = (checkedInfo: any, config: CategoryItem) => {\r\n  let checkedKeys = checkedInfo.checkedKeys;\r\n  let checkedNodes = checkedInfo.checkedNodes;\r\n  const isMultiple = config.props?.multiple;\r\n  if (!isMultiple) {\r\n    if (checkedKeys.length > 1 && currentCheckNode.value) {\r\n      // 处理单选逻辑\r\n      const treeRef = treeRefs.value[config.field];\r\n      treeRef.setCheckedKeys([currentCheckNode.value]);\r\n      checkedNodes = [currentCheckNode];\r\n      checkedKeys = [currentCheckNode.value];\r\n    }\r\n  }\r\n  const labels = checkedNodes.map((n: any) => n.label) || [];\r\n  const newCategory = {\r\n    field: config.field,\r\n    label: labels,\r\n    value: checkedKeys,\r\n  };\r\n\r\n  const categoryIndex = choosedCategoryList.value.findIndex((item) => item.field === config.field);\r\n  if (categoryIndex > -1) {\r\n    choosedCategoryList.value[categoryIndex] = newCategory;\r\n  } else {\r\n    choosedCategoryList.value.push(newCategory);\r\n  }\r\n};\r\n\r\n// 移除已选资产\r\nconst handleRemoveAsset = (index: number) => {\r\n  const newAssets = [...props.selectedAssets];\r\n  newAssets.splice(index, 1);\r\n  emit("update:selectedAssets", newAssets);\r\n\r\n  // 如果没有资产了，关闭抽屉\r\n  if (newAssets.length === 0) {\r\n    emit("update:modelValue", false);\r\n  }\r\n};\r\n\r\n// Tab 切换\r\nconst handleTabChange = (name: string) => {\r\n  activeTab.value = name;\r\n};\r\n\r\n// 关闭抽屉\r\nconst handleClose = () => {\r\n  visible.value = false;\r\n  choosedCategoryList.value = [];\r\n  categoryTreeData.value = {};\r\n  treeRefs.value = {};\r\n};\r\n\r\n// 保存\r\nconst handleSave = async () => {\r\n  btnLoading.value = true;\r\n\r\n  try {\r\n    // 构建类目 props\r\n    const categoryProps: Record<string, any> = {};\r\n    choosedCategoryList.value.forEach((item) => {\r\n      categoryProps[item.field] = item.value.join(",");\r\n    });\r\n\r\n    // 获取所有选中资产的 tid\r\n    const tids = props.selectedAssets.map((asset: AssetItem) => asset.tid);\r\n    await $common.post("/dst/catalog/properties/batch-save", {\r\n      tids,\r\n      props: categoryProps,\r\n    });\r\n\r\n    emit("success");\r\n    handleClose();\r\n  } catch (error) {\r\n    console.error("保存类目失败:", error);\r\n  } finally {\r\n    btnLoading.value = false;\r\n  }\r\n};\r\n\r\n// 监听抽屉显示\r\nwatch(\r\n  () => props.modelValue,\r\n  (val) => {\r\n    if (val) {\r\n      fetchCategoryData();\r\n    }\r\n  }\r\n);\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.category-drawer-content {\r\n  display: flex;\r\n  flex-direction: column;\r\n  height: 100%;\r\n  :deep(.el-divider--horizontal) {\r\n    margin: 15px 0;\r\n  }\r\n}\r\n\r\n.selected-assets {\r\n  max-height: 150px;\r\n  overflow-y: auto;\r\n\r\n  .asset-item {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    padding: 8px 12px;\r\n    margin-bottom: 8px;\r\n    background: #f4f7fc;\r\n    border-radius: 4px;\r\n\r\n    .asset-info {\r\n      display: flex;\r\n      align-items: center;\r\n      overflow: hidden;\r\n\r\n      .data-asset-name {\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n        white-space: nowrap;\r\n      }\r\n    }\r\n\r\n    .close-icon {\r\n      cursor: pointer;\r\n      color: #909399;\r\n\r\n      &:hover {\r\n        color: #f56c6c;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.single-asset-name {\r\n  display: flex;\r\n  align-items: center;\r\n  padding: 12px;\r\n  background: #f4f7fc;\r\n  border-radius: 4px;\r\n  font-weight: 500;\r\n}\r\n\r\n.selected-categories {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: flex-start;\r\n\r\n  .ca