ght: 22px;\n  color: #1677ff;\n  cursor: pointer;\n  border-radius: 6px;\n}\n.keyword-search-trigger[data-v-161fbab32b5a7ffcce4406566ce22b11]:hover {\n  color: var(--el-color-primary);\n  background: var(--el-color-primary-light-9);\n}\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  flex: 1;\n  min-height: 0;\n  width: 100%;\n  min-width: 0;\n  overflow: hidden;\n}\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .is-expanded-source {\n  background: #f8fbff;\n}\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .el-table__expanded-cell {\n  padding: 12px 18px 16px 58px;\n  background: #f8fbff;\n}\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .pagination {\n  container-type: inline-size;\n  display: flex;\n  flex-wrap: nowrap;\n  align-items: center;\n  gap: 10px;\n  min-width: 0;\n  overflow: hidden;\n  margin-top: 4px;\n}\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .pagination > span:first-child,\n.source-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .pagination .el-pagination {\n  flex: 0 0 auto;\n  white-space: nowrap;\n}\n.task-name-cell[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.table-name-cell[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  max-width: 100%;\n  color: #17233d;\n  cursor: pointer;\n}\n.table-name-cell > div[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  flex: 1;\n  min-width: 0;\n}\n.table-name-cell strong[data-v-161fbab32b5a7ffcce4406566ce22b11],\n.table-name-cell small[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: block;\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.table-name-cell strong[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  color: #17233d;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 20px;\n}\n.table-name-cell small[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  margin-top: 2p