n {\n  color: var(--el-color-primary);\n  text-decoration: underline;\n  text-underline-offset: 3px;\n}\n.task-table-wrap[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  border: 1px solid #dfe9f7;\n  border-radius: 10px;\n  background: #fff;\n  overflow: hidden;\n}\n.task-empty[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  color: #9aa6b2;\n  font-size: 12px;\n}\n.reject-modify-action[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  min-height: 20px;\n  padding: 0;\n  font-size: 14px;\n  line-height: 20px;\n}\n.child-table-head[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px 14px;\n  border-bottom: 1px solid #edf2f8;\n  background: linear-gradient(180deg, #fbfdff, #f6f9fe);\n}\n.child-table-head strong[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  margin-right: 10px;\n  color: #17233d;\n  font-size: 14px;\n}\n.child-table-head span[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  color: #78869d;\n  font-size: 12px;\n}\n.task-table[data-v-161fbab32b5a7ffcce4406566ce22b11] .el-button.is-link {\n  padding: 0 4px;\n}\n.source-select-empty[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  flex: 1;\n  min-height: 0;\n  border: 1px dashed #d9e4f2;\n  border-radius: 12px;\n  background: #fbfdff;\n}\n.muted[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  color: #98a2b3;\n}\n.table-detail-content[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  min-height: 220px;\n}\n.detail-table-heading[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 16px;\n}\n.detail-table-heading strong[data-v-161fbab32b5a7ffcce4406566ce22b11],\n.detail-table-heading small[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  display: block;\n}\n.detail-table-heading strong[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  color: #17233d;\n  font-size: 16px;\n  line-height: 1.5;\n}\n.detail-table-heading small[data-v-161fbab32b5a7ffcce4406566ce22b11] {\n  margin-top