m: 18px;\n}\n.detail-section[data-v-dataDz20260730] {\n  padding: 16px;\n  margin-bottom: 18px;\n  border: 1px solid var(--el-border-color-lighter);\n  border-radius: 6px;\n}\n.section-heading[data-v-dataDz20260730] {\n  justify-content: space-between;\n  margin-bottom: 14px;\n}\n.section-heading span[data-v-dataDz20260730] {\n  color: var(--el-text-color-secondary);\n}\n.bucket-list[data-v-dataDz20260730] {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n  max-height: 220px;\n  margin-top: 14px;\n  overflow: auto;\n}\n.bucket-item[data-v-dataDz20260730] {\n  display: grid;\n  grid-template-columns: 42px 86px 1fr auto;\n  gap: 8px;\n  align-items: center;\n  padding: 8px 10px;\n  font-size: 12px;\n  background: var(--el-fill-color-lighter);\n  border: 1px solid var(--el-border-color-lighter);\n  border-radius: 4px;\n}\n.diff-filter[data-v-dataDz20260730] {\n  width: 150px;\n}\n.diff-pagination[data-v-dataDz20260730] {\n  display: flex;\n  justify-content: flex-end;\n  margin-top: 14px;\n}\n.error-detail[data-v-dataDz20260730] {\n  margin-top: 16px;\n}\n.error-detail pre[data-v-dataDz20260730] {\n  max-height: 280px;\n  padding: 12px;\n  overflow: auto;\n  font-size: 12px;\n  line-height: 1.6;\n  white-space: pre-wrap;\n  background: var(--el-fill-color-light);\n  border: 1px solid var(--el-border-color-lighter);\n  border-radius: 4px;\n}\n.warning-item[data-v-dataDz20260730] {\n  margin-top: 10px;\n}\n.w-full[data-v-dataDz20260730] {\n  width: 100%;\n}\n@media (max-width: 1100px) {\n.status-strip[data-v-dataDz20260730] {\n    grid-template-columns: repeat(3, 1fr);\n}\n.status-filter[data-v-dataDz20260730]:nth-child(3) {\n    border-right: 0;\n}\n.status-filter[data-v-dataDz20260730]:nth-child(n + 4) {\n    border-top: 1px solid var(--el-border-color-lighter);\n}\n.metric-grid[data-v-dataDz20260730] {\n    grid-template-columns: repeat(2, 1fr);\n}\n.metric-grid > div[data-v-dataDz20260730]:nth-child(2) {\n    border-right: 0;\n}\n.metric-grid > div[data-v-dataDz20260730]:nth-child(-n + 2) {\n    border-bottom: 1px solid var(--el-border-color-lighter);\n}\n}','1','2.2.3 数据对账',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2006267215160610816','2006253365342310400','data-dz-dj','<template>\r\n  <div class="dj-container">\r\n    <breadcrumb class="bg-white bread"></breadcrumb>\r\n    <div class="main card-container py-2 px-5 flex flex-col flex-1">\r\n      <div>\r\n        <json-form ref="formRef" bordered :rules="state.rules" />\r\n        <u-title name="数据资源选择" style="margin-bottom: -8px">\r\n          <template #right>\r\n            <el-button type="primary" icon="plus">添加待对账资源</el-button>\r\n          </template>\r\n        </u-title>\r\n        <v-table ref="tableRef" :options="state.tableOptions">\r\n          <template #provider="{ row }">\r\n            <el-checkbox v-model="row.provider" />\r\n          </template>\r\n          <template #colType="{ row }">\r\n            <el-text>\r\n              <Icon icon="time" />\r\n              {{ row.colType }}\r\n            </el-text>\r\n          </template>\r\n          <template #action="{ row }">\r\n            <el-button type="primary" link>对账条件</el-button>\r\n            <el-button type="danger" link @click="tableRef.removeRow(row)">删除</el-button>\r\n          </template>\r\n          <template #empty>\r\n            <empty description="暂无数据，请点击“新增”按钮添加资源" />\r\n          </template>\r\n        </v-table>\r\n      </div>\r\n\r\n      <div class="action">\r\n        <el-button>\r\n          <template #icon>\r\n            <Icon icon="el-icon-back" />\r\n          </template>\r\n          取消并返回\r\n        </el-button>\r\n        <el-button type="primary">\r\n          <template #icon>\r\n            <Icon icon="save" />\r\n          </template>\r\n          发布对账策略\r\n        </el-button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n<script setup lang="ts">\r\nimport { ref, reactive, onMounted } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\n\r\nconst formRef = ref();\r\nconst tableRef = ref();\r\nconst state = reactive<any>({\r\n  tab: 1,\r\n  cols: [], // 申请单表格配置\r\n  rules: [],\r\n  tableOptions: {},\r\n});\r\n\r\nonMounted(() => {\r\n  formRef.value.setValue({\r\n    name: "新闻联播收视率每日对账策略",\r\n    type: 1, // 按日循环对账\r\n    range: ["2025-12-01", "2025-12-31"], // 对账时间区间\r\n    diff: 1,\r\n    remark: "该策略用于央视新闻联播每日收视率数据对账",\r\n  });\r\n  tableRef.value?.setData([\r\n    {\r\n      resEn: "tb_target_news",\r\n      resName: "新闻联播收视率",\r\n      time: "create_time",\r\n      colType: "TIMESTAMP",\r\n      provider: true,\r\n    },\r\n    {\r\n      resEn: "tb_source_news",\r\n      resName: "新闻联播收视率表",\r\n      time: "create_time",\r\n      colType: "TIMESTAMP",\r\n      provider: true,\r\n    },\r\n  ]);\r\n});\r\n\r\nstate.rules = FormUtils.fixJson([\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "基本信息",\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "策略名称",\r\n    field: "name",\r\n    props: {\r\n      maxlength: 30,\r\n      showWordLimit: true,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "DictSelect",\r\n    title: "对账方式",\r\n    field: "type",\r\n    props: {\r\n      options: [{ label: "单次对账", value: 1 }],\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "date-picker",\r\n    title: "时间区间",\r\n    field: "range",\r\n    props: {\r\n      type: "daterange",\r\n      startPlaceholder: "开始日期",\r\n      endPlaceholder: "结束日期",\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n  },\r\n  // {\r\n  //   type: "date-picker",\r\n  //   title: "对账频率",\r\n  //   field: "range",\r\n  //   props: {\r\n  //     type: "daterange",\r\n  //     startPlaceholder: "开始日期",\r\n  //     endPlaceholder: "结束日期",\r\n  //   },\r\n  //   col: {\r\n  //     span: 12,\r\n  //   },\r\n  //   $required: true,\r\n  // },\r\n  {\r\n    type: "radio",\r\n    title: "差异分析策略",\r\n    field: "diff",\r\n    info: "差异分析策略",\r\n    value: 1,\r\n    props: {\r\n      options: [\r\n        { label: "无", value: 1 },\r\n        { label: "主键差异分析", value: 2 },\r\n        { label: "内容差异分析", value: 3 },\r\n      ],\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "更新时间",\r\n    field: "updateTime",\r\n    props: {\r\n      disabled: true,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n    $required: true,\r\n    update(val, rule, api, { origin }) {\r\n      if (origin === "init") {\r\n        const t = new Date();\r\n        const year = t.getFullYear();\r\n        const month = (t.getMonth() + 1).toString().padStart(2, "0");\r\n        const day = t.getDate().toString().padStart(2, "0");\r\n        const hours = t.getHours().toString().padStart(2, "0");\r\n        const minutes = t.getMinutes().toString().padStart(2, "0");\r\n        const seconds = t.getSeconds().toString().padStart(2, "0");\r\n        rule.value = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;\r\n      }\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "备注",\r\n    field: "remark",\r\n    props: {\r\n      maxlength: 50,\r\n      showWordLimit: true,\r\n    },\r\n    col: {\r\n      span: 12,\r\n    },\r\n  },\r\n]);\r\nstate.tableOptions = {\r\n  toolbarConfig: {\r\n    buttons: [],\r\n    tools: [],\r\n  },\r\n  columns: [\r\n    { type: "seq", width: 70, field: "left" },\r\n    {\r\n      field: "resEn", // 可编辑-插槽渲染\r\n      title: "资源英文名称",\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "resName", // 可编辑-插槽渲染\r\n      title: "资源中文名称",\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "time", // 可编辑-插槽渲染\r\n      title: "时间字段",\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "colType", // 可编辑-插槽渲染\r\n      title: "字段类型",\r\n      editRender: {\r\n        name: "ElSelect",\r\n        options: [\r\n          { label: "VARCHAR", value: "VARCHAR" },\r\n          { label: "TEXT", value: "TEXT" },\r\n          { label: "DATETIME", value: "DATETIME" },\r\n          { label: "TIMESTAMP", value: "TIMESTAMP" },\r\n          { label: "DATE", value: "DATE" },\r\n          { label: "TINYINT", value: "TINYINT" },\r\n          { label: "BOOLEAN", value: "BOOLEAN" },\r\n          { label: "NUMBER", value: "NUMBER" },\r\n          { label: "INT", value: "INT" },\r\n          { label: "BIGINT", value: "BIGINT" },\r\n          { label: "DECIMAL(10,2)", value: "DECIMAL(10,2)" },\r\n        ],\r\n      },\r\n    },\r\n    {\r\n      field: "provider", // 可编辑-插槽渲染\r\n      title: "设置提供方",\r\n      slots: { default: "provider" },\r\n    },\r\n    {\r\n      field: "action", // 可编辑-插槽渲染\r\n      title: "操作",\r\n      slots: { default: "action" },\r\n    },\r\n  ],\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.dj-container {\r\n  flex: 1;\r\n  display: grid;\r\n  grid-template-rows: 40px 1fr;\r\n  gap: 16px;\r\n  .bread {\r\n    padding: 12px;\r\n    margin: -16px -16px 0;\r\n    background: #fff;\r\n  }\r\n\r\n  .main {\r\n    flex: 1;\r\n    position: relative;\r\n    display: grid;\r\n    grid-template-rows: 1fr 40px;\r\n    gap: 1rem;\r\n    .action {\r\n      display: flex;\r\n      justify-content: center;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createEl