   }, {\n      type: "date-picker",\n      title: "时间区间",\n      field: "range",\n      props: {\n        type: "daterange",\n        startPlaceholder: "开始日期",\n        endPlaceholder: "结束日期"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    },\n    // {\n    //   type: "date-picker",\n    //   title: "对账频率",\n    //   field: "range",\n    //   props: {\n    //     type: "daterange",\n    //     startPlaceholder: "开始日期",\n    //     endPlaceholder: "结束日期",\n    //   },\n    //   col: {\n    //     span: 12,\n    //   },\n    //   $required: true,\n    // },\n    {\n      type: "radio",\n      title: "差异分析策略",\n      field: "diff",\n      info: "差异分析策略",\n      value: 1,\n      props: {\n        options: [{\n          label: "无",\n          value: 1\n        }, {\n          label: "主键差异分析",\n          value: 2\n        }, {\n          label: "内容差异分析",\n          value: 3\n        }]\n      },\n      col: {\n        span: 12\n      }\n    }, {\n      type: "input",\n      title: "更新时间",\n      field: "updateTime",\n      props: {\n        disabled: true\n      },\n      col: {\n        span: 12\n      },\n      $required: true,\n      update(val, rule, api, {\n        origin\n      }) {\n        if (origin === "init") {\n          const t = new Date();\n          const year = t.getFullYear();\n          const month = (t.getMonth() + 1).toString().padStart(2, "0");\n          const day = t.getDate().toString().padStart(2, "0");\n          const hours = t.getHours().toString().padStart(2, "0");\n          const minutes = t.getMinutes().toString().padStart(2, "0");\n          const seconds = t.getSeconds().toString().padStart(2, "0");\n          rule.value = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;\n        }\n      }\n    }, {\n      type: "input",\n      title: "备注",\n      field: "remark",\n      props: {\n        maxlength: 50,\n        showWordLimit: true\n      },\n      col: {\n        span: 12\n      }\n    }]);\n    state.tableOptions = {\n      toolbarConfig: {\n        buttons: [],\n        tools: []\n      },\n      columns: [{\n        type: "seq",\n        width: 70,\n        field: "left"\n      }, {\n        field: "resEn",\n        // 可编辑-插槽渲染\n        title: "资源英文名称",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "resName",\n        // 可编辑-插槽渲染\n        title: "资源中文名称",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "time",\n        // 可编辑-插槽渲染\n        title: "时间字段",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "colType",\n        // 可编辑-插槽渲染\n        title: "字段类型",\n        editRender: {\n          name: "ElSelect",\n          options: [{\n            label: "VARCHAR",\n            value: "VARCHAR"\n          }, {\n            label: "TEXT",\n            value: "TEXT"\n          }, {\n            label: "DATETIME",\n            value: "DATETIME"\n          }, {\n            label: "TIMESTAMP",\n            value: "TIMESTAMP"\n          }, {\n            label: "DATE",\n            value: "DATE"\n          }, {\n            label: "TINYINT",\n            value: "TINYINT"\n          }, {\n            label: "BOOLEAN",\n            value: "BOOLEAN"\n          }, {\n            label: "NUMBER",\n            value: "NUMBER"\n          }, {\n            label: "INT",\n            value: "INT"\n          }, {\n            label: "BIGINT",\n            value: "BIGINT"\n          }, {\n            label: "DECIMAL(10,2)",\n            value: "DECIMAL(10,2)"\n          }]\n        }\n      }, {\n        field: "provider",\n        // 可编辑-插槽渲染\n        title: "设置提供方",\n        slots: {\n          default: "provider"\n        }\n      }, {\n        field: "action",\n        // 可编辑-插槽渲染\n        title: "操作",\n        slots: {\n          default: "action"\n        }\n      }]\n    };\n    return (_ctx, _cache) => {\n      const _component_breadcrumb =