  });\n          break;\n      }\n    };\n    handleAction("init");\n    const operationDrawer = ref(false);\n    const operationLoading = ref(false);\n    const operationSaving = ref(false);\n    const operationTab = ref("models");\n    const operationSummaryCards = ref([]);\n    const operationData = ref({\n      logicalModels: [],\n      logicalModelFields: [],\n      materializationPlans: [],\n      materializationExecutions: [],\n      catalogPublishRequests: []\n    });\n    const emptyModelForm = () => ({\n      tid: "",\n      modelCode: "",\n      modelName: "",\n      modelType: "DWD",\n      domainName: "",\n      targetDatasourceId: "",\n      modelStatus: "DRAFT",\n      modelDescription: ""\n    });\n    const emptyPlanForm = () => ({\n      tid: "",\n      planCode: "",\n      modelId: "",\n      targetDatasourceId: "",\n      targetTableName: "",\n      planStatus: "DRAFT",\n      riskLevel: "LOW",\n      changeSummary: ""\n    });\n    const modelEditor = ref({\n      visible: false,\n      form: emptyModelForm()\n    });\n    const planEditor = ref({\n      visible: false,\n      form: emptyPlanForm()\n    });\n    const setOperationSummary = summary => {\n      operationSummaryCards.value = [{\n        key: "models",\n        label: "逻辑模型",\n        value: summary?.logicalModelCount || 0\n      }, {\n        key: "fields",\n        label: "模型字段",\n        value: summary?.logicalModelFieldCount || 0\n      }, {\n        key: "plans",\n        label: "物化计划",\n        value: summary?.materializationPlanCount || 0\n      }, {\n        key: "executions",\n        label: "执行记录",\n        value: summary?.materializationExecutionCount || 0\n      }, {\n        key: "publish",\n        label: "发布申请",\n        value: summary?.catalogPublishRequestCount || 0\n      }];\n    };\n    const loadOperations = async () => {\n      operationLoading.value = true;\n      try {\n        const [overview, records] = await Promise.all([$common.get("/dwm/center/operations/overview"), $common.get("/dwm/center/operations/records")]);\n        setOperationSummary(overview);\n        operationData.value = {\n          logicalModels: records?.logicalModels || [],\n          logicalModelFields: records?.logicalModelFields || [],\n          materializationPlans: records?.materializationPlans || [],\n          materializationExecutions: records?.materializationExecutions || [],\n          catalogPublishRequests: records?.catalogPublishRequests || []\n        };\n      } finally {\n        operationLoading.value = false;\n      }\n    };\n    const openOperations = () => {\n      operationDrawer.value = true;\n      loadOperations();\n    };\n    const openModelEditor = row => {\n      modelEditor.value = {\n        visible: true,\n        form: row ? {\n          tid: row.tid,\n          modelCode: row.modelCode || "",\n          modelName: row.modelName || "",\n          modelType: row.modelType || "",\n          domainName: row.domainName || "",\n          targetDatasourceId: row.targetDatasourceId || "",\n          modelStatus: row.modelStatus || "DRAFT",\n          modelDescription: row.modelDescription || ""\n        } : emptyModelForm()\n      };\n      loadDataCenterSources();\n    };\n    const saveModel = async () => {\n      const form = modelEditor.value.form;\n      if (!form.modelCode.trim() || !form.modelName.trim() || !form.modelType.trim()) {\n        ElMessage.warning("请填写模型编码、名称和类型");\n        return;\n      }\n      operationSaving.value = true;\n      try {\n        await $common.post("/dwm/center/operations/record/save", {\n          recordType: "logicalModel",\n          tid: form.tid || undefined,\n          fields: {\n            ...form,\n            modelCode: form.modelCode.trim(),\n            modelName: form.modelName.trim(),\n            modelType: form.modelType.trim()\n          }\n        });\n        ElMessage.success("逻辑模型已保存");\n        modelEditor.value.visible = false;\n        await loadOperations();\n      } finally {\n        operationSaving.value = false;\n      }\n    };\n    const openPlanEditor = row => {\n      planEditor.value = {\n        visible: true,\n        form: row ? {\n          tid: row.tid,\n          planCode: row.planCode || "",\n          modelId: row.modelId || "",\n          targetDatasourceId: row.targetDatasourceId || "",\n          targetTableName: row.targetTableName || "",\n          planStatus: row.planStatus || "DRAFT",\n          riskLevel: row.riskLevel || "LOW",\n          changeSummary: row.changeSummary || ""\n        } : emptyPlanForm()\n      };\n      loadDataCenterSources();\n    };\n    const savePlan = async () => {\n      const form = planEditor.value.form;\n      if (!form.planCode.trim() || !form.modelId || !form.targetDatasourceId || !form.targetTableName.trim()) {\n        ElMessage.warning("请完整填写物化计划信息");\n        return;\n      }\n      operationSaving.value = true;\n      try {\n        await $common.post("/dwm/center/operations/record/save", {\n          recordType: "materializationPlan",\n          tid: form.tid || undefined,\n          fields: {\n            ...form,\n            planCode: form.planCode.trim(),\n            targetTableName: form.targetTableName.trim()\n          }\n        });\n        ElMessage.success("物化计划已保存");\n        planEditor.value.visible = false;\n        await loadOperations();\n      } finally {\n        operationSaving.value = false;\n      }\n    };\n    const deleteOperationRecord = (recordType, tid, name) => {\n      ElMessageBox.confirm("确定删除“" + name + "”吗？该操作不会影响已经登记的数据表或目录。", "删除资源运营记录", {\n        type: "warning",\n        confirmButtonText: "删除",\n        cancelButtonText: "取消"\n      }).then(async () => {\n        await $common.post("/dwm/center/operations/record/delete", {\n          recordType,\n          tid\n        });\n        ElMessage.success("已删除");\n        await loadOperations();\n      }).catch(() => undefined);\n    };\n    const loadDataCenterSources = (key