] {\n  display: flex;\n  align-items: center;\n  margin-bottom: 12px;\n}\n.domain-workbench-head .domain-workbench-title[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: block;\n  min-width: 0;\n}\n.domain-workbench-head strong[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: block;\n  color: #303133;\n  font-size: 15px;\n}\n.domain-workbench-empty[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  padding: 24px;\n  border: 1px dashed #dcdfe6;\n  border-radius: 6px;\n  text-align: center;\n  color: #909399;\n}\n.domain-create-row[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: grid;\n  grid-template-columns: 96px minmax(220px, 1fr) minmax(190px, 0.75fr);\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 12px;\n  padding: 12px;\n  border-radius: 6px;\n  background: #f8fafc;\n}\n.domain-workbench-row[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: grid;\n  grid-template-columns: 34px minmax(150px, 1fr) minmax(130px, 0.75fr) minmax(200px, 1.25fr) 126px;\n  gap: 12px;\n  align-items: center;\n  min-height: 58px;\n  padding: 10px 14px;\n  border: 1px solid #ebeef5;\n  border-radius: 6px;\n  background: #fff;\n}\n.domain-workbench-row + .domain-workbench-row[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  margin-top: 8px;\n}\n.domain-workbench-index[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  color: #2f6fed;\n  background: #eef5ff;\n  font-family: Arial, sans-serif;\n  font-size: 13px;\n  font-weight: 700;\n}\n.domain-workbench-name[data-v-9b0b824b81d4521454a2f46bb4f1dc2c],\n.domain-workbench-code[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: flex;\n  align-items: center;\n  min-width: 0;\n}\n.domain-row-actions[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: inline-flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 4px;\n  white-space: nowrap;\n}\n.domain-row-actions[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] .el-button {\n  margin-left: 0;\n  padding: 0 2px;\n}\n@media (max-width: 900px) {\n.layer-workbench-form[data-v-9b0b824b81d4521454a2f46bb4f1dc2c],\n  .domain-create-row[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-template-columns: 1fr;\n}\n.domain-workbench-row[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-template-columns: 34px 1fr;\n}\n.domain-workbench-name[data-v-9b0b824b81d4521454a2f46bb4f1dc2c],\n  .domain-workbench-code[data-v-9b0b824b81d4521454a2f46bb4f1dc2c],\n  .domain-workbench-row > .el-select[data-v-9b0b824b81d4521454a2f46bb4f1dc2c],\n  .domain-row-actions[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-column: 1/-1;\n}\n.domain-row-actions[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    justify-content: flex-start;\n}\n.layer-workbench-form .el-form-item[data-v-9b0b824b81d4521454a2f46bb4f1dc2c]:last-child {\n    grid-column: auto;\n}\n}\n.operation-workbench[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  padding: 0 2px 20px;\n}\n.operation-intro[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: flex;\n  justify-content: space-between;\n  gap: 20px;\n  align-items: flex-start;\n  margin-bottom: 16px;\n  padding: 16px;\n  border-radius: 10px;\n  background: linear-gradient(110deg, #eff6ff, #f8fbff);\n}\n.operation-intro strong[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  color: #1d4ed8;\n  font-size: 16px;\n}\n.operation-intro p[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  margin: 8px 0 0;\n  color: #64748b;\n  font-size: 13px;\n  line-height: 1.6;\n}\n.operation-summary-grid[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: grid;\n  grid-template-columns: repeat(5, minmax(0, 1fr));\n  gap: 10px;\n  margin-bottom: 18px;\n}\n.operation-summary-card[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  padding: 13px;\n  border: 1px solid #e5eaf3;\n  border-radius: 8px;\n  background: #fff;\n}\n.operation-summary-card span[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: block;\n  color: #64748b;\n  font-size: 12px;\n}\n.operation-summary-card strong[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: block;\n  margin-top: 6px;\n  color: #1e3a8a;\n  font-size: 23px;\n  line-height: 1;\n}\n.operation-tab-toolbar[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  margin: 0 0 12px;\n  color: #64748b;\n  font-size: 13px;\n}\n.operation-record-block + .operation-record-block[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  margin-top: 20px;\n}\n.operation-record-title[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 10px;\n  color: #334155;\n  font-weight: 600;\n}\n.operation-form-grid[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  column-gap: 18px;\n}\n.operation-form-wide[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n  grid-column: 1/-1;\n}\n@media (max-width: 820px) {\n.operation-summary-grid[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n.operation-form-grid[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-template-columns: 1fr;\n}\n.operation-form-wide[data-v-9b0b824b81d4521454a2f46bb4f1dc2c] {\n    grid-column: auto;\n}\n}','1','2.5.1 数据中心',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016463617438322688','2016463450651824128','database-config','<template>\r\n  <div class="database-config">\r\n    <div class="database-config-container">\r\n      <!-- 左侧：源数据库 -->\r\n      <div class="source-database images-workplace-bg2">\r\n        <div class="header">\r\n          <div class="header-left">\r\n            <div class="icon-wrapper source-icon">\r\n              <Icon icon="database-network" size="22" />\r\n            </div>\r\n            <h3>源数据信息 (Source)</h3>\r\n          </div>\r\n          <el-button type="text" class="detail-btn" @click="handleShowDrawer(\'source\')">\r\n            详情\r\n          </el-button>\r\n        </div>\r\n\r\n        <JsonForm ref="sourceFormRef" :rules="sourceFormRules" :options="formOptions">\r\n          <template #field-sourceDbId="scope">\r\n            <div class="flex items-center w-full gap-2">\r\n              <dict-select\r\n                v-model="scope.model.value"\r\n                :options="dbOptions"\r\n                :disabled="!props.edit"\r\n                style="flex: 1"\r\n                placeholder="请选择数据库"\r\n                @change="handleSourceDatabaseChange"\r\n              ></dict-select>\r\n              <el-button type="primary" plain @click="testConnection(scope.model.value)">\r\n                <Icon icon="shandian" class="mr-2"></Icon>\r\n                连通性\r\n              </el-button>\r\n            </div>\r\n          </template>\r\n        </JsonForm>\r\n      </div>\r\n\r\n      <!-- 中间：动效连线 -->\r\n      <div class="connection-line">\r\n        <div class="line-bg"></div>\r\n        <div class="line-animation">\r\n          <div class="arrow-container">\r\n            <div class="gradient-line"></div>\r\n            <svg\r\n              width="14"\r\n              height="14"\r\n              viewBox="0 0 24 24"\r\n              fill="none"\r\n              xmlns="http://www.w3.org/2000/svg"\r\n            >\r\n              <path\r\n                d="M9 18l6-6-6-6"\r\n                stroke="#165DFF"\r\n                stroke-width="2"\r\n                stroke-linecap="round"\r\n                stroke-linejoin="round"\r\n              />\r\n            </svg>\r\n          </div>\r\n        </div>\r\n        <svg\r\n          width="18"\r\n          height="18"\r\n          viewBox="0 0 24 24"\r\n          fill="none"\r\n          xmlns="http://www.w3.org/2000/svg"\r\n          class="chevron-icon"\r\n        >\r\n          <path\r\n            d="M9 18l6-6-6-6"\r\n            stroke="#165DFF"\r\n            stroke-opacity="0.2"\r\n            stroke-width="3"\r\n            stroke-linecap="round"\r\n            stroke-linejoin="round"\r\n          />\r\n        </svg>\r\n      </div>\r\n\r\n      <!-- 右侧：目标数据库 -->\r\n      <div class="target-database images-workplace-bg3">\r\n        <div class="header">\r\n          <div class="header-left">\r\n            <div class="icon-wrapper target-icon">\r\n              <Icon icon="data-switching" size="22" />\r\n            </div>\r\n            <h3>目标数据信息 (Target)</h3>\r\n          </div>\r\n          <el-button type="text" class="detail-btn" @click="handleShowDrawer(\'target\')">\r\n            详情\r\n          </el-button>\r\n        </div>\r\n\r\n        <JsonForm ref="targetFormRef" :rules="targetFormRules" :options="formOptions">\r\n          <template #field-targetDbId="scope">\r\n            <div class="flex items-center w-full gap-2">\r\n              <dict-select\r\n                v-model="scope.model.value"\r\n                :options="dbOptions"\r\n                :disabled="!props.edit"\r\n                style="flex: 1"\r\n                placeholder="请选择数据库"\r\n                @change="handleTargetDatabaseChange"\r\n              />\r\n              <el-button type="primary" plain @click="testConnection(scope.model.value)">\r\n                <Icon icon="shandian" class="mr-2"></Icon>\r\n                连通性\r\n              </el-button>\r\n            </div>\r\n          </template>\r\n        </JsonForm>\r\n      </div>\r\n    </div>\r\n    <detail-drawer v-if="drawerVisible" :title="drawerTitle" :tid="tid" @close="closeDrawer" />\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, onMounted, nextTick } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { ElMessage } from "element-plus";\r\n// import detailDrawer from "./detail-drawer.vue";\r\n\r\nconst props = defineProps({\r\n  info: {\r\n    type: Object,\r\n    default: () => ({}),\r\n  },\r\n  edit: {\r\n    type: Boolean,\r\n    default: true,\r\n  },\r\n  // dbOptions: {\r\n  //   type: Array,\r\n  //   default: () => [],\r\n  // },\r\n});\r\nconst sourceFormRef = ref();\r\nconst targetFormRef = ref();\r\nconst drawerVisible = ref(false);\r\nconst drawerTitle = ref("");\r\nconst tid = ref("");\r\nconst dbOptions = ref<any>([]);\r\n// 目标字段选项 - 用于传递给 fieldMapping 组件\r\nconst targetFieldOptions = ref<any[]>([]);\r\nconst formOptions = {\r\n  form: {\r\n    labelPosition: "top",\r\n  },\r\n};\r\n// 源数据表options\r\nconst sourceFormRules = FormUtils.fixJson([\r\n  {\r\n    type: "fieldComponent",\r\n    title: "选择数据库",\r\n    field: "sourceDbId",\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "sourceTableId",\r\n    title: "选择数据表",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请选择数据表",\r\n      filterable: true,\r\n      options: [],\r\n      disabled: !props.edit,\r\n    },\r\n    on: {\r\n      change: (value: string) => {\r\n        updateFieldsById(value, "source");\r\n      },\r\n    },\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "sourceTablePrimaryKey",\r\n    title: "主键字段",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请选择主键字段",\r\n      filterable: true,\r\n      options: [],\r\n    },\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "sourceTableIncrementKey",\r\n    title: "增量提取字段",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请选择增量提取字段",\r\n      filterable: true,\r\n      options: [],\r\n    },\r\n  },\r\n]);\r\n// 目标数据库form rules\r\nconst targetFormRules = FormUtils.fixJson([\r\n  {\r\n    type: "fieldComponent",\r\n    field: "targetDbId",\r\n    title: "选择数据库",\r\n    $required: true,\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "targetTableId",\r\n    title: "选择数据表",\r\n    $required: true,\r\n    props: {\r\n      disabled: !props.edit,\r\n    },\r\n    on: {\r\n      change: (value: string) => {\r\n        updateFieldsById(value, "target");\r\n      },\r\n    },\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "targetTablePrimaryKey",\r\n    title: "主键字段",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请选择主键",\r\n      filterable: true,\r\n      options: [],\r\n    },\r\n  },\r\n]);\r\n\r\n// 更新数据库下拉数据\r\nconst updateDbData = async () => {\r\n  try {\r\n    const res: any = await $common.post("/dst/catalog/list", {\r\n      assetType: "db",\r\n    });\r\n\r\n    if (!res || !Array.isArray(res)) {\r\n      console.warn("获取数据库列表返回数据格式不正确:", res);\r\n      return;\r\n    }\r\n\r\n    const options = res.map((item: any) => ({\r\n      label: item.dbName,\r\n      value: item.id,\r\n      icon: item.dbType?.toLowerCase(),\r\n    }));\r\n\r\n    // 等待表单初始化完成后再更新选项\r\n    await nextTick();\r\n\r\n    dbOptions.value = [...options];\r\n    sourceFormRef.value?.updateFieldOptions("sourceDbId", options);\r\n    targetFormRef.value?.updateFieldOptions("targetDbId", options);\r\n  } catch (error) {\r\n    console.error("更新数据库下拉数据失败:", error);\r\n  }\r\n};\r\n\r\n// 更新表数据_by数据库ID\r\nconst updateTableDataById = (dbId: string, type: "source" | "target") => {\r\n  $common.get("/dst/database/metadata/tables?dbId=" + dbId).then((res: any) => {\r\n    const options = res.map((item: any) => ({\r\n      label: item.tableName,\r\n      value: item.id,\r\n    }));\r\n    if (type === "source") {\r\n      sourceFormRef.value?.updateFieldOptions("sourceTableId", options);\r\n    } else {\r\n      targetFormRef.value?.updateFieldOptions("targetTableId", options);\r\n    }\r\n  });\r\n};\r\n\r\n// 更新字段数据_by表ID\r\nconst updateFieldsById = (tableId: string, type: "source" | "target") => {\r\n  $common.get("/dst/database/metadata/columns?tid=" + tableId).then((res: any) => {\r\n    // 字段选项 - 用于表单下拉框\r\n    const fieldOptions = res || [];\r\n    const options = fieldOptions.map((item: any) => ({\r\n      label: item.columnName,\r\n      value: item.tid,\r\n    }));\r\n\r\n    if (type === "source") {\r\n      sourceFormRef.value?.updateFieldOptions("sourceTablePrimaryKey", options);\r\n      sourceFormRef.value?.updateFieldOptions("sourceTableIncrementKey", options);\r\n    } else {\r\n      targetFormRef.value?.updateFieldOptions("targetTablePrimaryKey", options);\r\n      // 存储目标表字段信息，用于传递给 fieldMapping 组件\r\n      targetFieldOptions.value = fieldOptions;\r\n    }\r\n  });\r\n};\r\n\r\nconst handleShowDrawer = async (type: string) => {\r\n  if (type === "source") {\r\n    const form = await sourceFormRef.value?.formData();\r\n    if (!form.sourceDbId) {\r\n      ElMessage.error("请选择数据库");\r\n      return;\r\n    }\r\n    drawerVisible.value = true;\r\n    drawerTitle.value = "源数据详情";\r\n    tid.value = form.sourceDbId;\r\n  }\r\n  if (type === "target") {\r\n    const form = await targetFormRef.value?.formData();\r\n    if (!form.targetDbId) {\r\n      ElMessage.error("请选择数据库");\r\n      return;\r\n    }\r\n    drawerVisible.value = true;\r\n    drawerTitle.value = "目标数据详情";\r\n    tid.value = form.targetDbId;\r\n  }\r\n};\r\n\r\nconst closeDrawer = () => {\r\n  drawerVisible.value = false;\r\n  drawerTitle.value = "";\r\n  tid.value = "";\r\n};\r\n\r\n// 处理数据源类型变化\r\nconst handleSourceDatabaseChange = async (value: string) => {\r\n  try {\r\n    sourceFormRef.value?.setValue({\r