INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2066782132212649984','2008730136700588032','ddl-dialog','<template>\r\n  <el-drawer\r\n    :model-value="modelValue"\r\n    title="查看DDL创建语句"\r\n    size="700"\r\n    class="ddl-preview-drawer"\r\n    :close-on-click-modal="false"\r\n    @update:model-value="handleClose"\r\n  >\r\n    <div class="ddl-preview-content">\n      <div class="ddl-preview-editor">\n        <CodeEditor\r\n        v-model="ddlSql"\r\n        lang="sql"\r\n        theme="chrome"\r\n        :height="\'100%\'"\r\n        :show-option="false"\r\n        :read-only="true"\r\n        />\n      </div>\n    </div>\n    <template #footer>\r\n      <div class="flex" style="justify-content: flex-end">\r\n        <el-button :icon="\'el-icon-CopyDocument\'" type="primary" @click="handleCopy">\r\n          一键复制\r\n        </el-button>\r\n        <el-button :icon="\'el-icon-Close\'" @click="handleClose(false)">关闭</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch } from "vue";\r\n\r\nconst props = defineProps({\r\n  modelValue: {\r\n    type: Boolean,\r\n    default: false,\r\n  },\r\n  /** 数据表信息（tid, dbId, tableName, tableNameCn） */\r\n  tableInfo: {\r\n    type: Object,\r\n    default: () => ({}),\r\n  },\r\n  /** 数据库信息（dbType） */\r\n  dbInfo: {\r\n    type: Object,\r\n    default: () => ({}),\r\n  },\r\n  /** 表字段列表 */\r\n  tableFields: {\r\n    type: Array,\r\n    default: () => [],\r\n  },\r\n});\r\n\r\nconst emit = defineEmits(["update:modelValue"]);\r\n\r\nconst ddlSql = ref("");\r\n\r\n// 关闭弹窗\r\nconst handleClose = (val: boolean = false) => {\r\n  emit("update:modelValue", val);\r\n};\r\n\r\n// 打开时自动加载 DDL\r\nwatch(\r\n  () => props.modelValue,\r\n  async (visible) => {\r\n    if (!visible) return;\r\n\r\n    if (!props.tableInfo?.tid) {\r\n      $message.warning("暂无关联数据表");\r\n      handleClose(false);\r\n      return;\r\n    }\r\n\r\n    ddlSql.value = "";\r\n\r\n    try {\r\n      const propList = {\r\n        dbType: props.dbInfo?.dbType,\r\n        dbId: props.tableInfo?.dbId,\r\n        tableName: props.tableInfo?.tableName,\r\n        tableNameCn: props.tableInfo?.tableNameCn,\r\n      };\r\n\r\n      const tableItems = Array.isArray(props.tableFields) ? props.tableFields : [];\r\n\r\n      const res = await $common.post("/dst/database/metadata/getCreateTableDDL", {\r\n        propList,\r\n        tableItems,\r\n      });\r\n\r\n      ddlSql.value = res || "";\r\n    } catch (error) {\r\n      console.error("获取DDL失败", error);\r\n      $message.error("获取DDL创建语句失败");\r\n    }\r\n  }\r\n);\r\n\r\n// 复制 DDL 语句\r\nconst handleCopy = () => {\r\n  if (ddlSql.value) {\r\n    $common.copyText(ddlSql.value);\r\n  } else {\r\n    $message.warning("没有可复制的内容");\r\n  }\r\n};\r\n</script>\n\n<style lang="scss" scoped>\n// DDL drawer uses the remaining body height all the way down to the Ace editor.\n:global(.ddl-preview-drawer .el-drawer__body) {\n  min-height: 0;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-content) {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor) {\n  min-height: 0;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor > .el-scrollbar) {\n  min-height: 0;\n  height: 100%;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__wrap),\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view) {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view) {\n  display: flex;\n  flex-direction: column;\n}\n\n:global(.ddl-preview-drawer .ddl-preview-editor .ace_editor) {\n  min-height: 0 !important;\n  height: 100% !important;\n  flex: 1 1 auto;\n}\n</style>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "ddl-preview-content"\n};\nconst _hoisted_2 = {\n  class: "ddl-preview-editor"\n};\nconst _hoisted_3 = {\n  class: "flex",\n  style: {\n    "justify-content": "flex-end"\n  }\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\nconst __sfc__ = _defineComponent({\n  __name: \'a22632fdd0ec76374193187b08bbd03e\',\n  props: {\n    modelValue: {\n      type: Boolean,\n      default: false\n    },\n    /** 数据表信息（tid, dbId, tableName, tableNameCn） */\n    tableInfo: {\n      type: Object,\n      default: () => ({})\n    },\n    /** 数据库信息（dbType） */\n    dbInfo: {\n      type: Object,\n      default: () => ({})\n    },\n    /** 表字段列表 */\n    tableFields: {\n      type: Array,\n      default: () => []\n    }\n  },\n  emits: ["update:modelValue"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const props = __props;\n    const emit = __emit;\n    const ddlSql = ref("");\n\n    // 关闭弹窗\n    const handleClose = (val = false) => {\n      emit("update:modelValue", val);\n    };\n\n    // 打开时自动加载 DDL\n    watch(() => props.modelValue, async visible => {\n      if (!visible) return;\n      if (!props.tableInfo?.tid) {\n        $message.warning("暂无关联数据表");\n        handleClose(false);\n        return;\n      }\n      ddlSql.value = "";\n      try {\n        const propList = {\n          dbType: props.dbInfo?.dbType,\n          dbId: props.tableInfo?.dbId,\n          tableName: props.tableInfo?.tableName,\n          tableNameCn: props.tableInfo?.tableNameCn\n        };\n        const tableItems = Array.isArray(props.tableFields) ? props.tableFields : [];\n        const res = await $common.post("/dst/database/metadata/getCreateTableDDL", {\n          propList,\n          tableItems\n        });\n        ddlSql.value = res || "";\n      } catch (error) {\n        console.error("获取DDL失败", error);\n        $message.error("获取DDL创建语句失败");\n      }\n    });\n\n    // 复制 DDL 语句\n    const handleCopy = () => {\n      if (ddlSql.value) {\n        $common.copyText(ddlSql.value);\n      } else {\n        $message.warning("没有可复制的内容");\n      }\n    };\n    return (_ctx, _cache) => {\n      const _component_CodeEditor = _resolveComponent("CodeEditor");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_el_drawer = _resolveComponent("el-drawer");\n      return _openBlock(), _createBlock(_component_el_drawer, {\n        "model-value": __props.modelValue,\n        title: "查看DDL创建语句",\n        size: "700",\n        class: "ddl-preview-drawer",\n        "close-on-click-modal": false,\n        "onUpdate:modelValue": handleClose\n      }, {\n        footer: _withCtx(() => [_createElementVNode("div", _hoisted_3, [_createVNode(_component_el_button, {\n          icon: \'el-icon-CopyDocument\',\n          type: "primary",\n          onClick: handleCopy\n        }, {\n          default: _withCtx(() => [...(_cache[2] || (_cache[2] = [_createTextVNode(" 一键复制 ", -1 /* CACHED */)]))]),\n          _: 1 /* STABLE */\n        }), _createVNode(_component_el_button, {\n          icon: \'el-icon-Close\',\n          onClick: _cache[1] || (_cache[1] = $event => handleClose(false))\n        }, {\n          default: _withCtx(() => [...(_cache[3] || (_cache[3] = [_createTextVNode("关闭", -1 /* CACHED */)]))]),\n          _: 1 /* STABLE */\n        })])]),\n        default: _withCtx(() => [_createElementVNode("div", _hoisted_1, [_createElementVNode("div", _hoisted_2, [_createVNode(_component_CodeEditor, {\n          modelValue: ddlSql.value,\n          "onUpdate:modelValue": _cache[0] || (_cache[0] = $event => ddlSql.value = $event),\n          lang: "sql",\n          theme: "chrome",\n          height: \'100%\',\n          "show-option": false,\n          "read-only": true\n        }, null, 8 /* PROPS */, ["modelValue"])])])]),\n        _: 1 /* STABLE */\n      }, 8 /* PROPS */, ["model-value"]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "modelValue": "props",\n  "tableInfo": "props",\n  "dbInfo": "props",\n  "tableFields": "props",\n  "ref": "setup-const",\n  "watch": "setup-const",\n  "props": "setup-reactive-const",\n  "emit": "setup-const",\n  "ddlSql": "setup-ref",\n  "handleClose": "setup-const",\n  "handleCopy": "setup-const"\n} */\n__sfc__.__scopeId = "data-v-a22632fdd0ec76374193187b08bbd03e"\n__sfc__.__file = "a22632fdd0ec76374193187b08bbd03e.vue"\nreturn __sfc__','.ddl-preview-drawer .el-drawer__body {\n  min-height: 0;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-content {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor {\n  min-height: 0;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor > .el-scrollbar {\n  min-height: 0;\n  height: 100%;\n  width: 100%;\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__wrap,.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view {\n  min-height: 0;\n  height: 100%;\n  flex: 1 1 auto;\n}\n.ddl-preview-drawer .ddl-preview-editor .el-scrollbar__view {\n  display: flex;\n  flex-direction: column;\n}\n.ddl-preview-drawer .ddl-preview-editor .ace_editor {\n  min-height: 0 !important;\n  height: 100% !important;\n  flex: 1 1 auto;\n}','1','ddl弹窗',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2059545106555981824','2008730414761971712','delay-monitor','<template>\r\n  <el-dialog v-model="visible" :title="dialogTitle" :draggable="false" width="1400px" class="delay-monitor-dialog">\r\n    <div class="search-bar">\r\n      <JsonForm\r\n        ref="jsonFormRef"\r\n        :rules="searchRules"\r\n        :data="searchForm"\r\n        :options="jsonFormOptions"\r\n      />\r\n      <div class="search-actions">\r\n        <el-button type="primary" @click="handleSearch">\r\n          <Icon icon="el-icon-Search" class="mr-1" />\r\n          查询\r\n        </el-button>\r\n        <el-button @click="handleReset">\r\n          <Icon icon="el-icon-Refresh" class="mr-1" />\r\n          重置\r\n        </el-button>\r\n      </div>\r\n    </div>\r\n\r\n    <DataTable ref="tableRef" :columns="tableColumns" :data="fetchData" show-index>\r\n      <!-- 是否超时 -->\r\n      <template #column-isTimeout="{ row }">\r\n        <span\r\n          :style="{\r\n            color: row.isTimeout === 1 ? \'#f56c6c\' : \'#67c23a\',\r\n            fontWeight: row.isTimeout === 1 ? \'600\' : \'400\',\r\n          }"\r\n        >\r\n          {{ row.isTimeout === 1 ? "是" : "否" }}\r\n        </span>\r\n      </template>\r\n    </DataTable>\r\n\r\n    <template #footer>\r\n      <div class="dialog-footer">\r\n        <el-button @click="visible = false">关闭</el-button>\r\n      </div>\r\n    </template>\r\n  </el-dialog>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed } from "vue";\r\nimport dayjs from "dayjs";\r\nimport type { UColumnProps } from "@/components/data/data-table.vue";\r\nimport { FormUtils } from "@/utils/form";\r\n\r\n// ======================== Props & Emits ========================\r\nconst props = defineProps<{\r\n  modelValue: boolean;\r\n  taskId: string;\r\n  taskName?: string;\r\n}>();\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", val: boolean): void;\r\n}>();\r\n\r\n// ======================== 弹窗显隐 ========================\r\nconst visible = computed({\r\n  get: () => props.modelValue,\r\n  set: (val) => emit("update:modelValue", val),\r\n});\r\n\r\nconst dialogTitle = computed(() => {\r\n  return props.taskName ? `${props.taskName}` : "延时监控";\r\n});\r\n\r\n// ======================== 搜索表单（JsonForm） ========================\r\nconst today = dayjs().format("YYYY-MM-DD");\r\n\r\nconst searchForm = ref({\r\n  monitorStatus: "",\r\n  beginTime: `${today} 00:00:00`,\r\n  endTime: `${today} 23:59:59`,\r\n});\r\n\r\nconst jsonFormRef = ref();\r\n\r\nconst jsonFormOptions = {\r\n  form: {\r\n    inline: true,\r\n    labelWidth: "90px",\r\n    labelPosition: "right" as const,\r\n    colon: false,\r\n    showMessage: false,\r\n  },\r\n  submitBtn: false,\r\n  resetBtn: false,\r\n};\r\n\r\nconst searchRules = FormUtils.fixJson([\r\n  {\r\n    type: "dict-select",\r\n    field: "monitorStatus",\r\n    title: "监控状态",\r\n    props: {\r\n      options: "taskMonitorStatus",\r\n    },\r\n    style: {\r\n      width: "120px",\r\n    },\r\n  },\r\n  {\r\n    type: "datePicker",\r\n    field: "beginTime",\r\n    title: "开始时间",\r\n    props: {\r\n      type: "datetime",\r\n      format: "YYYY-MM-DD HH:mm:ss",\r\n      valueFormat: "YYYY-MM-DD HH:mm:ss",\r\n    },\r\n  },\r\n  {\r\n    type: "datePicker",\r\n    field: "endTime",\r\n    title: "结束时间",\r\n    props: {\r\n      type: "datetime",\r\n      format: "YYYY-MM-DD HH:mm:ss",\r\n      valueFormat: "YYYY-MM-DD HH:mm:ss",\r\n    },\r\n  },\r\n]);\r\n\r\n// ======================== DataTable ========================\r\nconst tableRef = ref();\r\n\r\nconst tableColumns = ref<UColumnProps[]>([\r\n  {\r\n    prop: "delayMsEstimate",\r\n    label: "估算延时(ms)",\r\n  },\r\n  {\r\n    prop: "thresholdMs",\r\n    label: "超时阈值(ms)",\r\n  },\r\n  {\r\n    prop: "isTimeout",\r\n    label: "是否超时",\r\n    width: 90,\r\n    align: "center",\r\n  },\r\n  {\r\n    prop: "queuedCount",\r\n    label: "排队数量",\r\n  },\r\n  {\r\n    prop: "queuedBytes",\r\n    label: "排队字节数",\r\n  },\r\n  {\r\n    prop: "activeThreadCount",\r\n    label: "活动线程数",\r\n  },\r\n  {\r\n    prop: "flowFilesIn",\r\n    label: "流入文件数",\r\n  },\r\n  {\r\n    prop: "flowFilesOut",\r\n    label: "流出文件数",\r\n  },\r\n  {\r\n    prop: "bytesIn",\r\n    label: "流入字节数",\r\n  },\r\n  {\r\n    prop: "bytesOut",\r\n    label: "流出字节数",\r\n  },\r\n  {\r\n    prop: "monitorStatus",\r\n    label: "监控状态",\r\n    width: 100,\r\n    align: "center",\r\n    options: "taskMonitorStatus",\r\n  },\r\n  {\r\n    prop: "monitorMsg",\r\n    label: "监控消息",\r\n    minWidth: 220,\r\n    showOverflowTooltip: true,\r\n  },\r\n  {\r\n    prop: "monitorTime",\r\n    label: "监控时间",\r\n    width: 180,\r\n  },\r\n]);\r\n\r\n// ======================== API 调用 ========================\r\n\r\n/** DataTable 的 data 函数 */\r\nconst fetchData = async ({\r\n  pageNo: pageNum,\r\n  pageSize,\r\n}: {\r\n  pageNo: number;\r\n  pageSize: number;\r\n}): Promise<{ list: any[]; total: number }> => {\r\n  // 从 JsonForm 获取实时表单值（搜索结果），回退到 searchForm ref\r\n  const formData = jsonFormRef.value?.formData() || searchForm.value;\r\n\r\n  const params: Record<string, any> = {\r\n    pageNum,\r\n    pageSize,\r\n    taskId: props.taskId,\r\n    monitorStatus: formData.monitorStatus,\r\n    beginTime: formData.beginTime || "",\r\n    endTime: formData.endTime || "",\r\n  };\r\n\r\n  const response = await (window as any).$common.post(\r\n    "/ods/task/monitorSnapPage",\n    params\r\n  );\r\n\r\n  const data = response.data || response;\r\n  return {\r\n    list: data.list || [],\r\n    total: data.total || 0,\r\n  };\r\n};\r\n\r\n// ======================== 搜索操作 ========================\r\n\r\n/** 查询：重置到第一页 */\r\nconst handleSearch = () => {\r\n  tableRef.value?.refresh(true);\r\n};\r\n\r\n/** 重置搜索条件并重新查询 */\r\nconst handleReset = () => {\r\n  const todayStr = dayjs().format("YYYY-MM-DD");\r\n  const defaults = {\r\n    monitorStatus: "",\r\n    beginTime: `${todayStr} 00:00:00`,\r\n    endTime: `${todayStr} 23:59:59`,\r\n  };\r\n  searchForm.value = { ...defaults };\r\n  jsonFormRef.value?.coverValue(defaults);\r\n  tableRef.value?.refresh(true);\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.delay-monitor-dialog {\r\n  :deep(.el-dialog__body) {\r\n    padding: 16px 20px 20px;\r\n  }\r\n\r\n  :deep(.el-dialog__footer) {\r\n    padding: 12px 20px;\r\n    border-top: 1px solid #f0f0f0;\r\n  }\r\n}\r\n\r\n.search-bar {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 12px;\r\n  padding: 12px 16px;\r\n  margin-bottom: 16px;\r\n  background: #fafafa;\r\n  border-radius: 8px;\r\n  border: 1px solid #f0f0f0;\r\n\r\n  > :deep(.json-form) {\r\n    flex: 1;\r\n  }\r\n\r\n  .search-actions {\r\n    flex-shrink: 0;\r\n    display: flex;\r\n    gap: 8px;\r\n    padding-top: 2px;\r\n  }\r\n}\r\n\r\n.dialog-footer {\r\n  display: flex;\r\n  justify-content: flex-end;\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "search-bar"\n};\nconst _hoisted_2 = {\n  class: "search-actions"\n};\nconst _hoisted_3 = {\n  class: "dialo