earch-input[data-v-f7e30049445ee8333c696d04831d7714] {\n    width: 100%;\n}\n.app-filter[data-v-f7e30049445ee8333c696d04831d7714] {\n    width: 100%;\n}\n.source-metrics[data-v-f7e30049445ee8333c696d04831d7714] {\n    padding-left: 16px;\n}\n.management-workspace[data-v-f7e30049445ee8333c696d04831d7714] {\n    grid-template-columns: 1fr;\n}\n.organization-tree-panel[data-v-f7e30049445ee8333c696d04831d7714] {\n    max-height: 220px;\n    overflow: auto;\n    border-right: 0;\n    border-bottom: 1px solid #e8edf5;\n}\n}\n@media (max-width: 640px) {\n.source-head[data-v-f7e30049445ee8333c696d04831d7714] {\n    padding: 12px 12px 8px;\n}\n.source-title[data-v-f7e30049445ee8333c696d04831d7714] {\n    gap: 10px;\n}\n.source-icon[data-v-f7e30049445ee8333c696d04831d7714] {\n    width: 36px;\n    height: 36px;\n    font-size: 20px;\n}\n.source-audit-meta[data-v-f7e30049445ee8333c696d04831d7714] {\n    gap: 2px 10px;\n}\n.source-actions[data-v-f7e30049445ee8333c696d04831d7714] {\n    width: 100%;\n    flex-wrap: wrap;\n    justify-content: flex-start;\n}\n.source-actions[data-v-f7e30049445ee8333c696d04831d7714] .el-button {\n    flex: 0 0 auto;\n}\n}','1','02.数据源管理列表',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018596040552812544','2007661287158910976','detail-breadcrumb','<template>\n<breadcrumb\n  :breadcrumbs="breadcrumbs"\n  :back="routeBack"\n/>\n</template>\n\n<script setup lang="ts">\nimport { onMounted, computed } from "vue";\nimport { useDetailStore, usePermissionStore } from "@/store";\nimport { storeToRefs } from "pinia";\nimport { useRoute, useRouter, onBeforeRouteUpdate, onBeforeRouteLeave } from "vue-router";\n\nconst route = useRoute();\nconst router = useRouter();\nconst detailStore = useDetailStore();\n  \n// 详情初始化\nconst type = (route.query.type as string) || "approve";\nconst title = (route.query.title as string);\n\n// 方便资产详情页添加mock数据\nconst breadcrumbs = computed(() => {\n  const matched = route.matched.filter((item) => item.meta && item.meta.title);\n  const a = matched.filter((item) => {\n    // 个人中心特殊，要显示在面包屑中\n    return (item.meta && item.meta.title && !item.meta.hidden) || item.name === "workplace";\n  });\n  return [...a, ...detailStore.history];\n});\n\n/**\n * 以下代码，实现详情面包屑嵌套\n */\nonMounted(() => {\n  const findIndex = detailStore.findHistory(route.query);\n  if (findIndex === -1) {\n    detailStore.history.push({\n      path: route.path,\n      query: route.query,\n      meta: {\n        title: route.query.title,\n        icon: route.query.type === "approve" ? null : route.query.type,\n      },\n    });\n  }\n  if (route.query.tab) {\n    detailStore.currentTab = (route.query.tab as string) || "";\n  } else {\n    detailStore.initTab();\n  }\n});\n\n// 面包屑返回方法重写\nconst routeBack = () => {\n  // 有两个及以上详情页\n  const { path, query } = breadcrumbs.value[breadcrumbs.value.length - 2] as any;\n  router.push({ path, query });\n};\n\n// 详情页间的跳转，则缓存或移除当前详情\nonBeforeRouteUpdate((to, from, next) => {\n  const findIndex = detailStore.findHistory(to.query);\n  // 若前往新详情则添加记录\n  if (findIndex === -1) {\n    // 缓存当前详情页签\n    const last = detailStore.history[detailStore.history.length - 1];\n    last.query = Object.assign({ tab: detailStore.currentTab }, last.query);\n\n    detailStore.history.push({\n      path: to.path,\n      query: to.query,\n      meta: { title: to.query.title, icon: to.query.type === "approve" ? null : to.query.type },\n    });\n  }\n  // 若前往历史详情，则移除后面的详情页\n  else {\n    detailStore.history = detailStore.history.slice(0, findIndex + 1);\n  }\n  next();\n});\n\n// 离开详情页，则销毁记录\nonBeforeRouteLeave((to, from, next) => {\n  next();\n  setTimeout(() => {\n    detailStore.$destroy();\n  }, 100);\n});\n</script>','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\nconst useDetailStore = ___magic__import__(\'@/store\', \'useDetailStore\');\nconst useRoute = ___magic__import__(\'vue-router\', \'useRoute\');\r\nconst useRouter = ___magic__import__(\'vue-router\', \'useRouter\');\r\nconst onBeforeRouteUpdate = ___magic__import__(\'vue-router\', \'onBeforeRouteUpdate\');\r\nconst onBeforeRouteLeave = ___magic__import__(\'vue-router\', \'onBeforeRouteLeave\');\nconst __sfc__ = _defineComponent({\n  __name: \'77eb6ca23b0f0b83523265dbd444c035\',\n  setup(__props) {\n    const route = useRoute();\n    const router = useRouter();\n    const detailStore = useDetailStore();\n\n    // 详情初始化\n    const type = route.query.type || "approve";\n    const title = route.query.title;\n\n    // 方便资产详情页添加mock数据\n    const breadcrumbs = computed(() => {\n      const matched = route.matched.filter(item => item.meta && item.meta.title);\n      const a = matched.filter(item => {\n        // 个人中心特殊，要显