,\r\n    history: JSON.parse(JSON.stringify(detailStore.history)),\r\n    config: JSON.parse(JSON.stringify(detailStore.config)),\r\n    currentTab: detailStore.currentTab,\r\n  };\r\n  renderPage.value = true;\r\n};\r\n\r\nconst handleClose = () => {\r\n  visible.value = false;\r\n  renderPage.value = false;\r\n  // 恢复快照，避免污染原页面的 detailStore\r\n  if (snapshot) {\r\n    detailStore.data = snapshot.data;\r\n    detailStore.state = snapshot.state;\r\n    detailStore.history = snapshot.history;\r\n    detailStore.config = snapshot.config;\r\n    detailStore.currentTab = snapshot.currentTab;\r\n    snapshot = null;\r\n  }\r\n  emit("close");\r\n};\r\n</script>\r\n\r\n<style lang="scss">\r\n.detail-dialog__container {\r\n  padding: 0;\r\n  overflow: hidden !important;\r\n  .el-dialog__header {\r\n    height: 55px;\r\n    padding: 15px 15px 0 20px;\r\n    background-color: #fff;\r\n    border-bottom: var(--border);\r\n  }\r\n  .el-dialog__body {\r\n    height: calc(100% - 55px);\r\n    padding: 15px 0 0 15px;\r\n    overflow: hidden !important;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\nconst useDetailStore = ___magic__import__(\'@/store\', \'useDetailStore\');\n// import DetailPage from "./detail-page.vue";\n\nconst __sfc__ = _defineComponent({\n  __name: \'fb26441693ed48df9dbabfa4d03fc744\',\n  props: {\n    modelValue: {\n      type: Boolean,\n      required: true\n    },\n    detailData: {\n      type: Object,\n      required: false,\n      default: () => ({\n        name: "",\n        id: "",\n        type: "catalog",\n        dataSourceType: ""\n      })\n    }\n  },\n  emits: ["update:modelValue", "close"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const props = __props;\n    const emit = __emit;\n    const detailStore = useDetailStore();\n\n    // 控制 detail-page 是否渲染（延迟到 opened 后，确保快照先于 setup 执行）\n    const renderPage = ref(false);\n\n    // 快照：保存打开 dialog 前的 detailStore 状态\n    let snapshot = null;\n    const visible = computed({\n      get: () => props.modelValue,\n      set: val => emit("update:modelValue", val)\n    });\n\n    // dialog 打开动画结束后触发，此时 detail-page 尚未渲染，可以安全快照\n    const onOpened = () => {\n      snapshot = {\n        data: JSON.parse(JSON.stringify(detailStore.data)),\n        state: JSON.parse(JSON.stringify(detailStore.state)),\n        history: JSON.parse(JSON.stringify(detailStore.history)),\n        config: JSON.parse(JSON.stringify(detailStore.config)),\n        currentTab: detailStore.currentTab\n      };\n      renderPage.value = true;\n    };\n    const handleClose = () => {\n      visible.value = false;\n      renderPage.value = false;\n      // 恢复快照，避免污染原页面的 detailStore\n      if (snapshot) {\n        detailStore.data = snapshot.data;\n        detailStore.state = snapshot.state;\n        detailStore.history = snapshot.history;\n        detailStore.config = snapshot.config;\n        detailStore.currentTab = snapshot.currentTab;\n        snapshot = null;\n      }\n      emit("close");\n    };\n    return (_ctx, _cache) => {\n      const _component_detail_page = _resolveComponent("detail-page");\n      const _component_el_dialog = _resolveComponent("el-dialog");\n      return _openBlock(), _createBlock(_component_el_dialog, {\n        modelValue: visible.value,\n        "onUpdate:modelValue": _cache[0] || (_cache[0] = $event => visible.value = $event),\n        title: props.detailData?.name || props.detailData?.title,\n        fullscreen: "",\n        "destroy-on-