lor-primary-light-9);\r\n\r\n            .dict-name {\r\n              color: var(--el-color-primary);\r\n              font-weight: 600;\r\n            }\r\n          }\r\n\r\n          &.drag-source {\r\n            opacity: 0.4;\r\n          }\r\n\r\n          &.drag-over-before {\r\n            border-top: 2px solid var(--el-color-primary);\r\n          }\r\n\r\n          &.drag-over-after {\r\n            border-bottom: 2px solid var(--el-color-primary);\r\n          }\r\n\r\n          &__header {\n            display: flex;\n            align-items: center;\n            gap: 8px;\n            flex-wrap: nowrap;\n\r\n            .drag-handle-icon {\n              color: var(--el-text-color-placeholder);\r\n              cursor: grab;\r\n              flex-shrink: 0;\r\n              &:active {\r\n                cursor: grabbing;\r\n              }\r\n            }\n\n            .dict-sequence {\n              width: 28px;\n              flex-shrink: 0;\n              color: var(--el-text-color-secondary);\n              font-size: 12px;\n              font-variant-numeric: tabular-nums;\n              text-align: center;\n            }\n\n            .dict-name {\n              flex: 1;\n              min-width: 0;\n              overflow: hidden;\n              text-overflow: ellipsis;\n              white-space: nowrap;\n              font-size: 14px;\n              font-weight: 500;\r\n              color: rgba(0, 0, 0, 0.88);\r\n              transition: color 0.2s;\r\n            }\r\n\r\n            .dict-code {\n              max-width: 92px;\n              flex-shrink: 1;\n              overflow: hidden;\n              text-overflow: ellipsis;\n              font-size: 11px;\r\n              color: var(--el-text-color-secondary);\r\n              font-weight: bolder;\r\n              border-color: var(--el-border-color);\r\n              background-color: transparent;\r\n              height: 20px;\r\n              line-height: 18px;\r\n              