ict-list-item.active .dict-name[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  color: var(--el-color-primary);\n  font-weight: 600;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item.drag-source[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  opacity: 0.4;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item.drag-over-before[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  border-top: 2px solid var(--el-color-primary);\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item.drag-over-after[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  border-bottom: 2px solid var(--el-color-primary);\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: nowrap;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .drag-handle-icon[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  color: var(--el-text-color-placeholder);\n  cursor: grab;\n  flex-shrink: 0;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .drag-handle-icon[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9]:active {\n  cursor: grabbing;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .dict-sequence[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  width: 28px;\n  flex-shrink: 0;\n  color: var(--el-text-color-secondary);\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  text-align: center;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .dict-name[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 14px;\n  font-weight: 500;\n  color: rgba(0, 0, 0, 0.88);\n  transition: color 0.2s;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .dict-code[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  max-width: 92px;\n  flex-shrink: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  font-size: 11px;\n  color: var(--el-text-color-secondary);\n  font-weight: bolder;\n  border-color: var(--el-border-color);\n  background-color: transparent;\n  height: 20px;\n  line-height: 18px;\n  padding: 0 6px;\n  transition: opacity 0.15s, visibility 0.15s;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .dict-item-count[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  flex-shrink: 0;\n  margin-left: auto;\n  color: var(--el-text-color-secondary);\n  font-size: 12px;\n  white-space: nowrap;\n  transition: opacity 0.2s;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__header .dict-actions[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  position: absolute;\n  right: 16px;\n  padding-left: 8px;\n  background: inherit;\n  opacity: 0;\n  transition: opacity 0.2s;\n  display: flex;\n  gap: 2px;\n}\n.dict-manage-page .dict-manage-body .dict-list-card .dict-list .dict-list-item__desc[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  margin-top: 4px;\n  padding-left: 36px;\n  font-size: 12px;\n  color: var(--el-text-color-secondary);\n  display: flex;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  overflow: hidden;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card .dict-table-body[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  display: flex;\n  flex-direction: column;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .dict-action-cell {\n  display: flex;\n  width: 100%;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  white-space: nowrap;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .dict-action-cell .el-button + .el-button {\n  margin-left: 0;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .dict-operation-column .vxe-cell {\n  padding-left: 6px;\n  padding-right: 6px;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card .dict-table-loading[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card .card-header[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  flex-shrink: 0;\n  height: 57px;\n  display: flex;\n  align-items: center;\n  padding: 0 20px;\n  margin-bottom: 16px;\n  border-bottom: 1px solid var(--el-border-color-light);\n  transition: background 0.3s;\n}\n.dict-manage-page .dict-manage-body .dict-detail-card .card-header .card-title[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 15px;\n  font-weight: 600;\n  color: rgba(0, 0, 0, 0.88);\n}\n.dict-manage-page .dict-manage-body .dict-detail-card .card-header .card-title .current-dict-type-tag[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] {\n  font-weight: 400;\n}\n[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .vxe-cell--drag-handle {\n  opacity: 0;\n  transition: opacity 0.2s;\n}\n[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .vxe-body--row:hover .vxe-cell--drag-handle {\n  opacity: 0.5;\n}\n[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .vxe-body--row:hover .vxe-cell--drag-handle:hover {\n  opacity: 1;\n}\n.sort-mode[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .vxe-cell--drag-handle {\n  opacity: 0.6;\n}\n.sort-mode[data-v-99d2ea70a7f8cd0a6e725602a3dd32c9] .vxe-body--row:hover .vxe-cell--drag-handle {\n  opacity: 1;\n}','1','1.4 字典管理',NULL,NULL,0,'2084109831678504960',6);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2014274065852338176','2013139484096925696','dst-detail','<template>\r\n  <div class="data-catalog-container card-container px-5 pt-5 pb-2">\r\n    <el-splitter style="width: 100%; height: 100%">\r\n      <el-splitter-panel size="360px" min="10%">\r\n        <div class="left-panel">\r\n          <div class="left-header flex items-center justify-between">\r\n            <h3>数源层 DTS</h3>\r\n          </div>\r\n\r\n          <div class="tree-container">\r\n            <UTree\r\n              ref="treeRef"\r\n              :data="treeData"\r\n              :node-key="\'value\'"\r\n              :highlight-key="orgId"\r\n              :search="true"\r\n              :expand="false"\r\n              :expand-on-click-node="false"\r\n              :search-placeholder="\'请输入关键字\'"\r\n              class="tree-container-custom"\r\n              @node-click="handleNodeClick"\r\n              @highlight-done="handleHighlightDone"\r\n            >\r\n              <template #node="{ node }">\r\n                <u-tree-node\r\n                  show-icon\r\n                  style="--gap: 0"\r\n                  :keyword="treeRef?.searchValue"\r\n                  :label="node.label"\r\n                >\r\n                  <template #count>\r\n                    <span\r\n                      v-if="get(countMap, `${node?.data.type || \'org\'}.${node.data.value}`, 0) > 0"\r\n                    >\r\n                      ({{ get(countMap, `${node?.data.type || "org"}.${node.data.value}`, 0) }})\r\n                    </span>\r\n                    <span v-else></span>\r\n                  </template>\r\n\r\n                  <template #icon>\r\n                    <Icon\r\n                      v-if="node?.data.type"\r\n                      :icon="node?.data.type === \'db\' ? node?.data.dbType : node?.data.type"\r\n                      class="mr-1"\r\n                    />\r\n                    <Icon\r\n                      v-else\r\n                      :icon="node.expanded ? \'folder-open\' : \'folder\'"\r\n                      color="#0b8bf9"\r\n                      class="mr-1"\r\n                      size="23"\r\n                    />\r\n                  </template>\r\n                </u-tree-node>\r\n              </template>\r\n            </UTree>\r\n          </div>\r\n        </div>\r\n      </el-splitter-panel>\r\n\r\n      <el-splitter-panel>\r\n        <div class="right-panel pl-4">\r\n          <DataTable\r\n            ref="tableRef"\r\n            :columns="tableColumns"\r\n            :data="fetchData"\r\n            :immediate="false"\r\n            :show-index="true"\r\n            style="height: 100%"\r\n          >\r\n            <template #toolbar>\r\n              <div class="flex justify-between items-center">\r\n                <div>\r\n                  <el-button type="primary" icon="refresh" @click="refreshData">\r\n                    刷新数据表\r\n                  </el-button>\r\n                </div>\r\n                <div>\r\n                  <el-input\r\n                    v-model.trim="searchQuery"\r\n                    :suffix-icon="\'el-icon-Search\'"\r\n                    placeholder="输入关键词搜索"\r\n                    clearable\r\n                    style="width: 250px"\r\n                    @keydown.enter="refreshData"\r\n                  />\r\n                </div>\r\n              </div>\r\n            </template>\r\n            <template #column-tableName="{ row }">\r\n              <el-link\r\n                type="primary"\r\n                cursor-pointer\r\n                @click="handleDetailClick(row.id, row.tableName, \'table\')"\r\n              >\r\n                <Icon icon="table"></Icon>\r\n                {{ row.tableName }}\r\n              </el-link>\r\n            </template>\r\n            <template #column-dbId="{ row }">\r\n              <el-link\r\n                type="primary"\r\n                cursor-pointer\r\n                @click="handleDetailClick(row.dbId, row.dbName, \'db\')"\r\n              >\r\n                <Icon :icon="row.dbType || \'db\'"></Icon>\r\n                {{ row.dbName || "-" }}\r\n              </el-link>\r\n            </template>\r\n            <template #column-appName="{ row }">\r\n              <el-link\r\n                type="primary"\r\n                cursor-pointer\r\n                @click="handleDetailClick(row.appId, row.appName, \'app\')"\r\n              >\r\n                <Icon icon="app"></Icon>\r\n                {{ row.appName }}\r\n              </el-link>\r\n            </template>\r\n          </DataTable>\r\n        </div>\r\n      </el-splitter-panel>\r\n    </el-splitter>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { get } from "lodash-es";\r\nimport { ref, onMounted } from "vue";\r\nimport { useRouter, useRoute } from "vue-router";\r\n\r\nconst router = useRouter();\r\nconst route = useRoute();\r\n\r\nconst orgId = route.query.orgId as string | undefined;\r\nconst treeRef = ref<any>(null);\r\n\r\n// 当前操作的节点\r\nconst currentNode = ref();\r\n\r\n// 树数据\r\nconst treeData = ref<any[]>([\r\n  {\r\n    name: "全部",\r\n    value: "",\r\n    children: [],\r\n  },\r\n]);\r\n\r\n// 表格列配置\r\nconst tableColumns = ref([\r\n  { prop: "tableName", label: "表名" },\r\n  { prop: "tableNameCn", label: "表注释" },\r\n  {\r\n    prop: "dbId",\r\n    label: "所属数据库",\r\n  },\r\n  { prop: "appName", label: "所属系统" },\r\n  {\r\n    prop: "fieldCount",\r\n    label: "字段数",\r\n    formatter: (row: any, column: any, cellValue: number) => {\r\n      if (cellValue === null || cellValue === undefined) {\r\n        return "0 个";\r\n      }\r\n      return cellValue + " 个";\r\n    },\r\n  },\r\n  {\r\n    prop: "storageSize",\r\n    label: "数据量",\r\n  },\r\n  {\r\n    prop: "recordCount",\r\n    label: "记录数",\r\n    type: "number",\r\n    formatter: (row: any, column: any, cellValue: number) => {\r\n      if (cellValue === null || cellValue === undefined || cellValue === 0) {\r\n        return "0 条";\r\n      }\r\n      if (cellValue >= 10000) {\r\n        return (cellValue / 10000).toFixed(2) + " 万条";\r\n      }\r\n      return cellValue + " 条";\r\n    },\r\n  },\r\n  { prop: "flowStatus", label: "状态", width: 100, options: "status" },\r\n  { prop: "updatedTime", label: "数据更新时间", width: 170 },\r\n  // {\r\n  //   prop: "actions",\r\n  //   label: "状态",\r\n  //   width: 120,\r\n  //   buttons: [\r\n  //     {\r\n  //       type: "primary",\r\n  //       label: "查看目录",\r\n  //       icon: "el-icon-view",\r\n  //       link: true,\r\n  //       if(row: any) {\r\n  //         return row.status === "已登记";\r\n  //       },\r\n  //     },\r\n  //     {\r\n  //       type: "primary",\r\n  //       label: "去登记",\r\n  //       icon: "el-icon-EditPen",\r\n  //       link: true,\r\n  //       if(row: any) {\r\n  //         return row.status === "待登记";\r\n  //       },\r\n  //     },\r\n  //   ],\r\n  // },\r\n]);\r\n\r\n// 搜索和筛选条件\r\nconst tableRef = ref<any>(null);\r\nconst searchQuery = ref("");\r\nconst countMap = ref({});\r\n\r\n/** 判断节点及其所有后代的统计值是否全为 0 */\r\nconst isAllZero = (node: any): boolean => {\r\n  const key = `${node.type || "org"}.${node.value}`;\r\n  const count = get(countMap.value, key, 0);\r\n  if (count !== 0) return false;\r\n  if (node.children?.length) {\r\n    return node.children.every((child: any) => isAllZero(child));\r\n  }\r\n  return true;\r\n};\r\n\r\n/** 递归过滤掉统计值为 0 且后代也全为 0 的节点 */\r\nconst filterZeroNodes = (nodes: any[]): any[] => {\r\n  return nodes\r\n    .filter((node) => !isAllZero(node))\r\n    .map((node) => ({\r\n      ...node,\r\n      children: node.children?.length ? filterZeroNodes(node.children) : node.children,\r\n    }));\r\n};\r\n\r\nconst fetchTreeData = async () => {\r\n  await Promise.all([\r\n    $common.post("/sym/org/getOrgAppDbTree", { parentId: $user.orgRootId }),\r\n    $common.post("/dwm/center/dstTable"),\r\n  ])\r\n    .then(([data, countRes]) => {\r\n      countMap.value = {\r\n        org: countRes.orgId,\r\n        app: countRes.appId,\r\n        db: countRes.dbId,\r\n      };\r\n      treeData.value[0].children = filterZeroNodes(data);\r\n    })\r\n    .catch((error) => {\r\n      console.error("API 请求失败:", error);\r\n    });\r\n};\r\n\r\nconst handleDetailClick = (id: string, title: string, type: string) => {\r\n  console.log("handleDetailClick", title, type);\r\n  router.push({\r\n    path: "detail",\r\n    query: { id, type, title },\r\n  });\r\n};\r\n\r\nconst fetchData = async ({ pageNo: pageNum, pageSize }: { pageNo: number; pageSize: number }) => {\r\n  const conditions = [\r\n    // 资产类型\r\n    {\r\n      field: "assetType",\r\n      value: "table",\r\n      type: "match",\r\n    },\r\n  ];\r\n  if (searchQuery.value) {\r\n    // 关键字查询\r\n    conditions.push({\r\n      field: "tableName",\r\n      value: searchQuery.value,\r\n      type: "like",\r\n    });\r\n  }\r\n\r\n  if (currentNode.value) {\r\n    // 左侧树查询\r\n    const { type = "org", value, serialNumber, children } = currentNode.value;\r\n\r\n    if (type === "org") {\r\n      // org 节点：查找该部门下nodeId为业务库的db\r\n      const dbList = await $common.post("/dst/database/table/list", {\r\n        nodeId: "业务库",\r\n        assetType: "db",\r\n        orgId: value || undefined, // 考虑查全部时，不传orgId\r\n        assetStatus: 2,\r\n      });\r\n      const dbIds = (dbList || []).map((child: any) => child.tid).filter(Boolean);\r\n      conditions.push({\r\n        field: "dbId",\r\n        value: dbIds?.length ? dbIds : [""],\r\n        type: dbIds?.length ? "in" : "match",\r\n      });\r\n    }\r\n\r\n    if (type === "app") {\r\n      // app 节点：查找app下nodeId为业务库的db\r\n      const dbList = await $common.post("/dst/database/table/list", {\r\n        nodeId: "业务库",\r\n        assetType: "db",\r\n        appId: value,\r\n        ass