\nconst _hoisted_4 = {\n  class: "left-header flex items-center justify-between"\n};\nconst _hoisted_5 = {\n  class: "tree-container"\n};\nconst _hoisted_6 = {\n  class: "tree-node-item"\n};\nconst _hoisted_7 = {\n  key: 0\n};\nconst _hoisted_8 = {\n  key: 1\n};\nconst _hoisted_9 = {\n  class: "pl-4 flex flex-col h-full w-full"\n};\nconst _hoisted_10 = {\n  class: "flex items-center justify-between"\n};\nconst _hoisted_11 = {\n  class: "right-header"\n};\nconst _hoisted_12 = {\n  class: "header-name"\n};\nconst _hoisted_13 = {\n  class: "flex items-center gap-3"\n};\nconst useRegisterModal = ___magic__import__(\'@/composables\', \'useRegisterModal\');\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\nconst useRouter = ___magic__import__(\'vue-router\', \'useRouter\');\nconst get = ___magic__import__(\'lodash-es\', \'get\');\n\n// 登记弹框\n\nconst __sfc__ = _defineComponent({\n  __name: \'1e601f81ee2ee5494f3dee615b7fd559\',\n  setup(__props) {\n    const {\n      openRegisterModal,\n      open\n    } = useRegisterModal();\n    const router = useRouter();\n    const taskTreeRef = ref();\n    const tableRef = ref();\n    const dialogFormRef = ref();\n\n    // ─── 树 ──────────────────────────────────────\n    const treeData = ref([]);\n    const treeLoading = ref(false);\n    const currentNodeKey = ref(null);\n    const currentNodeName = ref("");\n    const defaultExpandedKeys = ref([]);\n    const rootDictNode = ref(null);\n    const countMap = ref({});\n\n    // ─── 表格筛选状态 ────────────────────────────\n    const state = reactive({\n      keyword: "",\n      leftSelectNode: {}\n    });\n\n    // ─── 表格列配置 ──────────────────────────────\n    const tableColumns = ref([{\n      prop: "catalogName",\n      label: "基础表名称"\n    }, {\n      prop: "targetTableName",\n      label: "挂接表名"\n    }, {\n      prop: "sourceDir",\n      label: "关联源目录"\n    }, {\n      prop: "processLogic",\n      label: "加工逻辑概要"\n    }, {\n      prop: "shareType",\n      label: "共享属性",\n      options: "shareType",\n      width: 120\n    }, {\n      prop: "dataLevel",\n      label: "数据范围",\n      options: "dataLevel"\n    }, {\n      prop: "fieldCount",\n      label: "字段数",\n      props: {\n        suffix: "个"\n      },\n      align: "right"\n    }, {\n      prop: "recordCount",\n      label: "记录数",\n      props: {\n        suffix: "条"\n      },\n      align: "right"\n    }, {\n      prop: "updatedTime",\n      label: "最后更新时间"\n    }, {\n      prop: "status",\n      label: "对标状态",\n      options: "alignmentStatus"\n    }, {\n      prop: "operation",\n      label: "操作",\n      buttons: [{\n        label: "数据开发",\n        type: "primary",\n        link: true,\n        if: row => row.develop == "0",\n        click: row => handleAction("develop", row)\n      }, {\n        label: "开发任务",\n        type: "primary",\n        link: true,\n        if: row => row.develop == "1",\n        click: row => handleAction("task", row)\n      }, {\n        label: "数据质检",\n        type: "primary",\n        link: true,\n        if: row => row.quality == "0",\n        click: row => handleAction("check", row)\n      }, {\n        label: "质检结果",\n        type: "primary",\n        link: true,\n        if: row => row.quality == "1",\n        click: row => handleAction("result", row)\n      }, {\n        label: "删除",\n        type: "danger",\n        link: true,\n        click: row => handleAction("delete", row)\n      }]\n    }]);\n\n    // ─── 弹窗 ────────────────────────────────────\n    const dialogVisible = ref(false);\n    const dialogLoading = ref(false);\n    const dialogMode = ref("add");\n    const dialogEditTid = ref(null);\n    const dialogForm = ref({});\n    const dialogRules = {\n      dictName: [{\n        required: true,\n        message: "请输入字典名称",\n        trigger: "blur"\n      }],\n      dictCode: [{\n        required: true,\n        message: "请输入字典Code",\n        trigger: "blur"\n      }]\n    };\n    const dialogTitle = computed(() => dialogMode.value === "edit" ? "编辑" : "新增");\n\n    // ========================================================\n    //  handleAction — 统一操作入口\n    // ========================================================\n    const handleAction = (type, row) => {\n      switch (type) {\n        case "node-click":\n          state.leftSelectNode = row;\n          currentNodeKey.value = row.tid || row.value;\n          currentNodeName.value = row.label;\n          tableRef.value?.refresh(false);\n          break;\n        case "refresh":\n          tableRef.value?.refresh(true);\n          break;\n        case "详情":\n          router.push({\n            path: "detail",\n            query: {\n              id: row.id,\n              type: row.type,\n              title: row.title\n            }\n          });\n          break;\n        // 表格操作按钮（占位，后续实现）\n        case "add":\n          openRegisterModal({\n            registerClass: "table",\n            updateFormRule: [{\n              field: "dataSourceType",\n              value: state.leftSelectNode.value\n            }]\n          });\n        case "develop":\n        case "task":\n        case "check":\n        case "result":\n        case "delete":\n          console.log("[dwd-detail] handleAction:", type, row);\n          break;\n      }\n    };\n\n    // ─── 收集树中所有叶子节点的 value ───\n    const collectLeafValues = nodes => {\n      const values = [];\n      const traverse = list => {\n        for (const node of list) {\n          if (node.value) values.push(node.value);\n          if (node.children?.length) traverse(node.children);\n        }\n      };\n      traverse(nodes);\n      return values;\n    };\n\n    // ─── 加载左侧树统计 ───\n    const loadCountMap = () => {\n      const leafValues = collectLeafValues(treeData.value);\n      if (!leafValues.length) return;\n      $com