gend-items .legend-item .legend-item-icon.network[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  background: linear-gradient(221.87deg, #55b8f5 0%, #2d81e5 100%);\n}\n.legend .legend-items .legend-item .legend-item-icon.layers[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  background: linear-gradient(221.23deg, #ffc04a 0%, #f5a74b 100%);\n}\n.legend .legend-items .legend-item .legend-item-icon.check-square[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  background: linear-gradient(223.35deg, #bb90ff 0%, #6e66d1 100%);\n}\n.legend .legend-items .legend-item .legend-item-text[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  font-size: 12px;\n  font-weight: 500;\n  color: #4b5563;\n}\n\n/* ============================================================\n   动画效果\n   ============================================================ */\n@keyframes fadeIn-41745201f8d2ac21b47588e1dcafbd1d {\nfrom {\n    opacity: 0;\n    transform: translateY(-4px);\n}\nto {\n    opacity: 1;\n    transform: translateY(0);\n}\n}\n.fade-enter-active[data-v-41745201f8d2ac21b47588e1dcafbd1d],\n.fade-leave-active[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  transition: opacity 0.15s ease, transform 0.15s ease;\n}\n.fade-enter-from[data-v-41745201f8d2ac21b47588e1dcafbd1d],\n.fade-leave-to[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  opacity: 0;\n  transform: translateY(-4px);\n}\n\n/* ============================================================\n   图标内容\n   ============================================================ */\n.icon-minus-square[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "−";\n  font-weight: bold;\n  font-size: 16px;\n}\n.icon-plus-square[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "+";\n  font-weight: bold;\n  font-size: 16px;\n}\n.icon-plus[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "+";\n  font-weight: bold;\n}\n.icon-edit[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "✎";\n}\n.icon-delete[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "✕";\n}\n.icon-refresh[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "↻";\n}\n\n/* 拖拽手柄图标 - 使用竖排圆点 */\n.icon-drag-handle[data-v-41745201f8d2ac21b47588e1dcafbd1d]::before {\n  content: "⠿";\n  font-size: 13px;\n  line-height: 1;\n}\n\n/* ============================================================\n   加载遮罩\n   ============================================================ */\n.tree-loading-overlay[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  position: absolute;\n  inset: 0;\n  background-color: rgba(248, 250, 252, 0.85);\n  backdrop-filter: blur(2px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 100;\n}\n.tree-loading-overlay .tree-loading-content[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 12px;\n}\n.tree-loading-overlay .tree-loading-content .tree-loading-spinner[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  width: 28px;\n  height: 28px;\n  border: 3px solid #e5e7eb;\n  border-top-color: #2d81e5;\n  border-radius: 50%;\n  animation: spin-41745201f8d2ac21b47588e1dcafbd1d 0.8s linear infinite;\n}\n.tree-loading-overlay .tree-loading-content .tree-loading-text[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  font-size: 14px;\n  color: #64748b;\n}\n\n/* 图例刷新按钮 */\n.legend-refresh-btn[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  cursor: pointer;\n  color: #9ca3af;\n  font-size: 16px;\n  transition: all 0.2s;\n  margin-left: auto;\n  background: none;\n  border: none;\n}\n.legend-refresh-btn[data-v-41745201f8d2ac21b47588e1dcafbd1d]:hover {\n  color: #2d81e5;\n  background-color: #eff6ff;\n}\n.legend-refresh-btn.spinning .icon-refresh[data-v-41745201f8d2ac21b47588e1dcafbd1d] {\n  display: inline-block;\n  animation: spin-41745201f8d2ac21b47588e1dcafbd1d 0.8s linear infinite;\n  color: #2d81e5;\n}\n@keyframes spin-41745201f8d2ac21b47588e1dcafbd1d {\nfrom {\n    transform: rotate(0deg);\n}\nto {\n    transform: rotate(360deg);\n}\n}','1','规划图组件',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2064978903590064128','2013139484096925696','dws-detail','<template>\r\n  <div class="dws-detail card-container flex flex-col px-5 pt-5 pb-2">\r\n    <div class="h-full grid" style="grid-template-columns: 20% 80%">\r\n      <!-- ========== 左侧树 ========== -->\r\n      <div class="left-panel h-full">\r\n        <div class="left-header flex items-center justify-between">\r\n          <h3>专题库分类</h3>\r\n          <el-button type="primary" link icon="plus" @click="handleRootAdd" />\r\n        </div>\r\n        <div class="tree-container">\n          <u-tree\n            :loading="treeLoading"\n            ref="taskTreeRef"\r\n            class="task-tree-container"\r\n            :data="treeData"\r\n            :search="true"\r\n            :highlight-current="true"\r\n            :expand="false"\r\n            :default-expand-all="false"\r\n            :auto-expand-first-node="false"\r\n            :default-expanded-keys="defaultExpandedKeys"\r\n            :expand-on-click-node="false"\r\n            :default-props="{ label: \'label\', children: \'children\' }"\r\n            :node-key="\'tid\'"\r\n            :current-node-key="currentNodeKey"\r\n            @node-click="(node) => handleAction(\'node-click\', node)"\r\n          >\r\n            <template #node="{ node }">\r\n              <div class="tree-node-item">\r\n                <u-tree-node\r\n                  :label="node.label"\r\n                  :node="node"\r\n                  :show-icon="true"\r\n                  :wrap="false"\r\n                  class="tree-node-main"\r\n                >\r\n                  <template #count>\r\n                    <span v-if="get(countMap, `dataSourceType.${node?.data.value}`, 0) > 0">\r\n                      ({{ get(countMap, `dataSourceType.${node?.data.value}`, 0) }})\r\n                    </span>\r\n                    <span v-else></span>\r\n                  </template>\r\n                </u-tree-node>\r\n                <el-dropdown\r\n                  trigger="click"\r\n                  @command="(cmd: string) => handleNodeAction(cmd, node.data)"\r\n                >\r\n                  <span class="tree-node-more" @click.stop>\r\n                    <Icon icon="el-icon-MoreFilled" size="14px" />\r\n                  </span>\r\n                  <template #dropdown>\r\n                    <el-dropdown-menu>\r\n                      <el-dropdown-item command="add" icon="plus">新增</el-dropdown-item>\r\n                      <el-dropdown-item command="edit" icon="edit">编辑</el-dropdown-item>\r\n                      <el-dropdown-item\r\n                        command="delete"\r\n                        icon="delete"\r\n                        style="color: var(--el-color-danger)"\r\n                      >\r\n                        删除\r\n                      </el-dropdown-item>\r\n                    </el-dropdown-menu>\r\n                  </template>\r\n                </el-dropdown>\r\n              </div>\r\n            </template>\r\n          </u-tree>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- ========== 右侧表格 ========== -->\r\n      <div class="pl-4 flex flex-col h-full w-full">\r\n        <DataTable\r\n          ref="tableRef"\r\n          :columns="tableColumns"\r\n          :data="fetchData"\r\n          :immediate="false"\r\n          show-index\r\n          style="height: 100%"\r\n        >\r\n          <template #toolbar>\r\n            <div class="flex items-center justify-between">\r\n              <div class="right-header">\r\n                <span class="header-name">{{ currentNodeName }}</span>\r\n              </div>\r\n              <div class="flex items-center gap-3">\r\n                <el-input\r\n                  v-model.trim="state.keyword"\r\n                  placeholder="搜索目录名称"\r\n                  clearable\r\n                  prefix-icon="Search"\r\n                  style="width: 200px"\r\n                  @keydown.enter="handleAction(\'refresh\')"\r\n                  @clear="handleAction(\'refresh\')"\r\n                />\r\n                <el-button type="primary" @click="handleAction(\'add\')">\r\n                  <Icon :icon="\'el-icon-Plus\'" class="mr-2" />\r\n                  新建专题库目录\r\n                </el-button>\r\n              </div>\r\n            </div>\r\n          </template>\r\n          <template #column-catalogName="{ row }">\r\n            <el-text\r\n              type="primary"\r\n              cursor-pointer\r\n              @click="\r\n                handleAction(\'详情\', { id: row.tid, type: \'table\', title: row.catalogName })\r\n              "\r\n            >\r\n              <Icon icon="catalog" />\r\n              {{ row.catalogName }}\r\n            </el-text>\r\n          </template>\r\n          <template #column-targetTableName="{ row }">\r\n            <el-text\r\n              v-if="row.targetTableName"\r\n              type="primary"\r\n              cursor-pointer\r\n              @click="\r\n                handleAction(\'详情\', {\r\n                  id: row.targetTableId,\r\n                  type: \'table\',\r\n                  title: row.targetTableName,\r\n                })\r\n              "\r\n            >\r\n              <Icon icon="table" />\r\n              {{ row.targetTableName }}\r\n            </el-text>\r\n            <el-text v-else type="info">暂无挂接表</el-text>\r\n          </template>\r\n          <template #column-tableName="{ row }">\r\n            <el-text\r\n              type="primary"\r\n              cursor-pointer\r\n              @click="\r\n                handleAction(\'详情\', { id: row.sourceTableId, type: \'table\', title: row.tableName })\r\n              "\r\n            >\r\n              <Icon icon="hive" />\r\n              {{ row.tableName }}\r\n            </el-text>\r\n          </template>\r\n          <template #column-sourceDir="{ row }">\r\n            <el-text\r\n              type="primary"\r\n              cursor-pointer\r\n              @click="\r\n                handleAction(\'详情\', {\r\n                  id: row.sourceCatalogId,\r\n                  type: \'category\',\r\n                  title: row.sourceDir,\r\n                })\r\n              "\r\n            >\r\n              {{ row.sourceDir }}\r\n            </el-text>\r\n          </template>\r\n        </DataTable>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ========== 新增/编辑弹窗 ========== -->\r\n    <u-modal\r\n      v-model="dialogVisible"\r\n      :title="dialogTitle"\r\n      :confirm-loading="dialogLoading"\r\n      @confirm="handleDialogConfirm"\r\n    >\r\n      <el-form ref="dialogFormRef" :model="dialogForm" :rules="dialogRules" label-width="90px">\r\n        <el-form-item label="父级节点">\r\n          <dict-select\r\n            v-model="dialogForm.parentId"\r\n            type="cascader"\r\n            options="dataSourceType"\r\n            model-key="tid"\r\n            :props="{\r\n              checkStrictly: true,\r\n              emitPath: false,\r\n              value: \'tid\',\r\n            }"\r\n            :filters="{ value: \'dws\' }"\r\n            style="width: 100%"\r\n            placeholder="请选择父级节点"\r\n          />\r\n        </el-form-item>\r\n        <el-form-item label="字典名称" prop="dictName">\r\n          <el-input v-model="dialogForm.dictName" placeholder="请输入字典名称" />\r\n        </el-form-item>\r\n        <el-form-item label="字典Code" prop="dictCode">\r\n          <el-input\r\n            v-model="dialogForm.dictCode"\r\n            placeholder="请输入字典Code"\r\n            :disabled="dialogMode === \'edit\'"\r\n          />\r\n        </el-form-item>\r\n        <el-form-item label="排序">\r\n          <el-input-number\r\n            v-model="dialogForm.sortNo"\r\n            :min="0"\r\n            :step="1"\r\n            :precision="0"\r\n            controls-position="right"\r\n            placeholder="请输入排序值"\r\n          />\r\n        </el-form-item>\r\n        <el-form-item label="描述">\r\n          <el-input\r\n            v-model="dialogForm.dictDesc"\r\n            type="textarea"\r\n            :rows="3"\r\n            placeholder="请输入描述"\r\n          />\r\n        </el-form-item>\r\n      </el-form>\r\n    </u-modal>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { useRegisterModal } from "@/composables";\r\nimport { ref, reactive, computed, onMounted } from "vue";\r\nimport { useRouter } from "vue-router";\r\nimport { get } from "lodash-es";\r\n\r\n// 登记弹框\r\nconst { openRegisterModal, open } = useRegisterModal();\r\nconst router = useRouter();\r\nconst taskTreeRef = ref();\r\nconst tableRef = ref();\r\nconst dialogFormRef = ref();\r\n\r\n// ─── 树 ──────────────────────────────────────\r\nconst treeData = ref<any[]>([]);\r\nconst treeLoading = ref(false);\r\nconst currentNodeKey = ref<string | null>(null);\r\nconst currentNodeName = ref("");\r\nconst defaultExpandedKeys = ref<string[]>([]);\r\nconst rootDictNode = ref<any>(null);\r\nconst countMap = ref<Record<string, Record<string, number>>>({});\r\n\r\n// ─── 表格筛选状态 ────────────────────────────\r\nconst state = reactive({\r\n  keyword: "",\r\n  leftSelectNode: {} as any,\r\n});\r\n\r\n// ─── 表格列配置 ──────────────────────────────\r\nconst tableColumns = ref([\r\n  { prop: "catalogName", label: "服务表名称" },\r\n  { prop: "targetTableName", label: "挂接表名" },\r\n  { prop: "sourceCatalogName", label: "关联源目录" },\r\n  { prop: "shareType", label: "共享属性", options: "shareType", width: 120 },\r\n  { prop: "dataLevel", label: "数据范围", options: "dataLevel" },\r\n  { prop: "fieldCount", label: "字段数", props: { suffix: "个" }, align: "right", width: 120 },\r\n  { prop: "recordCount", label: "记录数", props: { suffix: "条" }, align: "right", width: 120 },\r\n  { prop: "updatedTime", label: "最后更新时间" },\r\n  {\r\n    prop: "operation",\r\n    label: "操作",\r\n    buttons: [\r\n      {\r\n        label: "数据开发",\r\n        type: "primary",\r\n        link: true,\r\n        if: (row: any) => row.develop == "0",\r\n        click: (row: any) => handleAction("develop", row),\r\n      },\r\n      {\r\n        label: "开发任务",\r\n        type: "primary",\r\n        link: true,\r\n        if: (row: any) => row.develop == "1",\r\n        click: (row: any) => handleAction("task", row),\r\n      },\r\n      {\r\n        label: "数据质检",\r\n        type: "primary",\r\n        link: true,\r\n        if: (row: any) => row.quality == "0",\r\n        click: (row: any) => handleAction("check", row),\r\n      },\r\n      {\r\n        label: "质检结果",\r\n        type: "primary",\r\n        link: true,\r\n        if: (row: any) => row.quality == "1",\r\n        click: (row: any) => handleAction("result", row),\r\n      },\r\n      {\r\n        label: "删除",\r\n        type: "danger",\r\n        link: true,\r\n        click: (row: any) => handleAction("delete", row),\r\n      },\r\n    ],\r\n  },\r\n]);\r\n\r\n// ─── 弹窗 ────────────────────────────────────\r\nconst dialogVisible = ref(false);\r\nconst dialogLoading = ref(false);\r\nconst dialogMode = ref<"add" | "edit">("add");\r\nconst dialogEditTid = ref<string | null>(null);\r\nconst dialogForm = ref<Record<string, any>>({});\r\n\r\nconst dialogRules = {\r\n  dictName: [{ required: true, message: "请输入字典名称", trigger: "blur" }],\r\n  dictCode: [{ required: true, message: "请输入字典Code", trigger: "blur" }],\r\n};\r\n\r\nconst dialogTitle = computed(() => (dialogMode.value === "edit" ? "编辑" : "新增"));\r\n\r\n// ========================================================\r\n//  handleAction — 统一操作入口\r\n// ========================================================\r\nconst handleAction = (type: string, row?: any) => {\r\n  switch (type) {\r\n    case "node-click":\r\n      state.leftSelectNode = row;\r\n      currentNodeKey.value = row.tid || row.value;\r\n      currentNodeName.value = row.label;\r\n      tableRef.value?.refresh(false);\r\n      break;\r\n    case "refresh":\r\n      tableRef.value?.refresh(true);\r\n      break;\r\n    case "详情":\r\n      router.push({\r\n        path: "detail",\r\n        query: { id: row.id, type: row.type, title: row.title },\r\n      });\r\n      break;\r\n    // 表格操作按钮（占位，后续实现）\r\n    case "add":\r\n      openRegisterModal({\r\n        registerClass: "table",\r\n        updateFormRule: [\r\n          {\r\n            field: "dataSourceType",\r\n            value: state.leftSelectNode.value,\r\n          },\r\n        ],\r\n      });\r\n    case "develop":\r\n    case "task":\r\n    case "check":\r\n    case "result":\r\n    case "delete":\r\n      console.log("[dws-detail] handleAction:", type, row);\r\n      break;\r\n  }\r\n};\r\n\r\n// ─── 收集树中所有叶子节点的 value ───\r\nconst collectLeafValues = (nodes: any[]): string[] => {\r\n  const values: string[] = [];\r\n  const traverse = (list: any[]) => {\r\n    for (const node of list) {\r\n      if (node.value) values.push(node.value);\r\n      if (node.children?.length) traverse(node.children);\r\n    }\r\n  };\r\n  traverse(nodes);\r\n  return values;\r\n};\r\n\r\n// ─── 加载左侧树统计 ───\r\nconst loadCountMap = () => {\r\n  const leafValues = collectLeafValues(treeData.value);\r\n  if (!leafValues.length) return;\r\n  $common\r\n    .post("/dst/statistics/common", {\r\n      conditions: [{ field: "dataSourceType", type: "in", value: leafValues }],\r\n      countFields: ["dataSourceType"],\r\n    })\r\n    .then((res) => {\r\n      countMap.value = res;\r\n    });\r\n};\r\n\r\n// ─── 加载树数据 ───\r\nconst fetchTreeData = async () => {\r\n  treeLoading.value = true;\r\n  try {\r\n    const dictTreeList = await $common.get("/sym/dict", { code: "dataSourceType" });\r\n    treeData.value = dictTreeList.filter((el: any) => el.value === "dws");\r\n    rootDictNode.value = treeData.value[0] || null;\r\n    if (rootDictNode.value?.tid) {\r\n      defaultExpandedKeys.value = [rootDictNode.value.tid];\r\n    }\r\n    // 加载统计\r\n    loadCountMap();\r\n  } catch (e) {\r\n    console.error("[dws-detail] 加载树数据失败", e);\r\n    treeData.value = [];\r\n  } finally {\r\n    treeLoading.value = false;\r\n  }\r\n};\r\n\r\n// ─── 刷新树并恢复选中 ───\r\nconst refreshTree = async () => {\r\n  const prevKey = currentNodeKey.value;\r\n  await fetchTreeData();\r\n\r\n  const findNodeByTid = (nodes: any[], tid: string): any => {\r\n    for (const n of nodes) {\r\n      if (n.tid === tid) return n;\r\n      if (n.children) {\r\n        const found = findNodeByTid(n.children, tid);\r\n        if (found) return found;\r\n      }\r\n    }\r\n    return null;\r\n  };\r\n\r\n  if (prevKey && treeData.value.length) {\r\n    const node = findNodeByTid(treeData.value, prevKey);\r\n    if (node) {\r\n      handleAction("node-click", node);\r\n    } else if (treeData.value.length) {\r\n      handleAction("node-click", treeData.value[0]);\r\n    }\r\n  } else if (treeData.value.length) {\r\n    handleAction("node-click", treeData.value[0]);\r\n  }\r\n};\r\n\r\n// ─── 根节点 + 按钮 → 新增子级 ───\r\nconst handleRootAdd = () => {\r\n  dialogMode.value = "add";\r\n  dialogForm.value = {\r\n    parentId: rootDictNode.value?.tid || null,\r\n    sortNo: 0,\r\n    dictName: "",\r\n    dictCode: "",\r\n    dictDesc: "",\r\n  };\r\n  dialogVisible.value = true;\r\n};\r\n\r\n// ─── 树节点 ... 菜单 ───\r\nconst handleNodeAction = (command: string, data: any) => {\r\n  switch (command) {\r\n    case "add":\r\n      dialogMode.value = "add";\r\n      dialogForm.value = {\r\n        parentId: data.tid || null,\r\n        sortNo: 0,\r\n        dictName: "",\r\n        dictCode: "",\r\n        dictDesc: "",\r\n      };\r\n      dialogVisible.value = true;\r\n      break;\r\n    case "edit":\r\n      dialogMode.value = "edit";\r\n      dialogEditTid.value = data.tid;\r\n      dialogForm.value = {\r\n        parentId: data.parentId || null,\r\n        dictName: data.label,\r\n        dictCode: data.value || data.dictCode,\r\n        dictDesc: data.dictDesc || "",\r\n        sortNo: data.sortNo || 0,\r\n      };\r\n      dialogVisible.value = true;\r\n      break;\r\n    case "delete":\r\n      handleDeleteNode(data);\r\n      break;\r\n  }\r\n};\r\n\r\n// ─── 删除节点 ───\r\nconst handleDeleteNode = (data: any) => {\r\n  if (data.children?.length) {\r\n    $message.warning("该节点下存在子级数据，请先删除子级");\r\n    return;\r\n  }\r\n  $common.handle({\r\n    url: "/sym/dictSaveOrUpdate",\r\n    info: `确认删除"${data.label}"？`,\r\n    action: "删除",\r\n    data: { tid: data.tid, action: "delete" },\r\n    done: () => {\r\n      refreshTree();\r\n    },\r\n  });\r\n};\r\n\r\n// ─── 弹窗确认 → 保存 ───\r\nconst handleDialogConfirm = async () => {\r\n  await dialogFormRef.value?.validate();\r\n  dialogLoading.value = true;\r\n  try {\r\n    const payload: Record<string, any> = {\r\n      parentId: dialogForm.value.parentId || null,\r\n      dictCode: dialogForm.value.dictCode,\r\n      dictName: dialogForm.value.dictName,\r\n      dictDesc: dialogForm.value.dictDesc || "",\r\n      sortNo: dialogForm.value.sortNo || 0,\r\n    };\r\n    if (dialogMode.value === "edit") {\r\n      payload.tid = dialogEditTid.value;\r\n    }\r\n    await $common.post("/sym/dictSaveOrUpdate", payload);\r\n    $message.success(dialogMode.value === "add" ? "新增成功" : "保存成功");\r\n    dialogVisible.value = false;\r\n    refreshTree();\r\n  } finally {\r\n    dialogLoading.value = false;\r\n  }\r\n};\r\n\r\n// ========================================================\r\n//  fetchData — 表格数据接口（由 DataTable 组件调用）\r\n// ========================================================\r\nconst fetchData = async ({ pageNo: pageNum, pageSize }: { pageNo: number; pageSize: number }) => {\r\n  const conditions: any[] = [];\r\n\r\n  // 树节点筛选：收集叶子节点 value 作为 category 过滤条件\r\n  if (state.leftSelectNode?.value) {\r\n    const leafValues: string[] = [];\r\n    $common.deepTree(state.leftSelectNode, (node) => {\r\n      if (node.value) leafValues.push(node.value);\r\n    });\r\n    if (leafValues.length > 0) {\r\n      conditions.push({ field: "dataSourceType", value: leafValues, type: "in" });\r\n    }\r\n  }\r\n\r\n  // 关键字搜索\r\n  if (state.keyword) {\r\n    conditions.push({ field: "catalogName", value: state.keyword, type: "like" });\r\n  }\r\n\r\n  const { list = [], total } = await $common.post("/dwm/center/dws-list", {\r\n    sortField: "updatedTime",\r\n    sortDir: "desc",\r\n    pageNum,\r\n    pageSize,\r\n    conditions,\r\n  });\r\n  return { list, total };\r\n};\r\n\r\n// ─── 初始化 ───\r\nonMounted(async () => {\r\n  await fetchTreeData();\r\n  const rootNode = treeData.value[0];\r\n  if (router.currentRoute.value.query.layerCode) {\r\n    handleAction(\r\n      "node-click",\r\n      rootNode.children.find((el) => el.value == router.currentRoute.value.query.layerCode) ||\r\n        rootNode\r\n    );\r\n  } else if (rootNode) {\r\n    handleAction("node-click", rootNode);\r\n  }\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.dws-detail {\r\n  .left-panel {\r\n    border-right: 1px solid rgba(5, 5, 5, 0.06);\r\n    overflow-y: auto;\r\n  }\r\n  .left-header {\r\n    border-bottom: 1px solid rgba(5, 5, 5, 0.06);\r\n    padding-bottom: 10px;\r\n    margin-bottom: 10px;\r\n    margin-right: 14px;\r\n    h3 {\r\n      margin: 0;\r\n      font-size: 16px;\r\n      font-weight: 700;\r\n      color: #464c64;\r\n    }\r\n  }\r\n  .right-header {\r\n    display: flex;\r\n    align-items: end;\r\n    height: 16px;\r\n    gap: 10px;\r\n    .header-name {\r\n      line-height: 1;\r\n      font-size: 16px;\r\n      font-weight: 700;\r\n      color: #464c64;\r\n    }\r\n  }\r\n  .tree-container {\r\n    height: calc(100% - 53px);\r\n    .task-tree-container {\r\n      height: 100%;\r\n      :deep(.u-tree-search) {\r\n        margin-right: 14px;\r\n      }\r\n      :deep(.el-tree) {\r\n        padding-right: 14px;\r\n      }\r\n      :deep(.el-tree-node__content) {\r\n        flex: 1;\r\n        overflow: hidden;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n// ─── 树节点自定义 ───\r\n.tree-node-item {\r\n  display: flex;\r\n  align-items: center;\r\n  flex: 1;\r\n  min-width: 0;\r\n\r\n  .tree-node-more {\r\n    flex-shrink: 0;\r\n    opacity: 0;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 24px;\r\n    height: 24px;\r\n    border-radius: 4px;\r\n    color: #909399;\r\n    cursor: pointer;\r\n    transition:\r\n      opacity 0.15s,\r\n      background-color 0.15s;\r\n  }\r\n}\r\n\r\n:deep(.el-tree-node__content:hover) {\r\n  .tree-node-more {\r\n    opacity: 1;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _withModifiers = ___magic__import__(\'vue\', \'withModifiers\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withKeys = ___magic__import__(\'vue\', \'withKeys\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "dws-detail card-container flex flex-col px-5 pt-5 pb-2"\n};\nconst _hoisted_2 = {\n  class: "h-full grid",\n  style: {\n    "grid-template-columns": "20% 80%"\n  }\n};\nconst _hoisted_3 = {\n  class: "left-panel h-full"\n};\nconst _hoisted_4 = {\n  class: "left-header flex items-center justify-between"\n};\n