: "setup-const",\n  "dialogTitle": "setup-ref",\n  "handleAction": "setup-const",\n  "collectLeafValues": "setup-const",\n  "loadCountMap": "setup-const",\n  "fetchTreeData": "setup-const",\n  "refreshTree": "setup-const",\n  "handleRootAdd": "setup-const",\n  "handleNodeAction": "setup-const",\n  "handleDeleteNode": "setup-const",\n  "handleDialogConfirm": "setup-const",\n  "fetchData": "setup-const"\n} */\n__sfc__.__scopeId = "data-v-346d49957e20d80b60df0157e1ac3d0f"\n__sfc__.__file = "346d49957e20d80b60df0157e1ac3d0f.vue"\nreturn __sfc__','.dws-detail .left-panel[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  border-right: 1px solid rgba(5, 5, 5, 0.06);\n  overflow-y: auto;\n}\n.dws-detail .left-header[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  border-bottom: 1px solid rgba(5, 5, 5, 0.06);\n  padding-bottom: 10px;\n  margin-bottom: 10px;\n  margin-right: 14px;\n}\n.dws-detail .left-header h3[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n}\n.dws-detail .right-header[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  display: flex;\n  align-items: end;\n  height: 16px;\n  gap: 10px;\n}\n.dws-detail .right-header .header-name[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  line-height: 1;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n}\n.dws-detail .tree-container[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  height: calc(100% - 53px);\n}\n.dws-detail .tree-container .task-tree-container[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  height: 100%;\n}\n.dws-detail .tree-container .task-tree-container[data-v-346d49957e20d80b60df0157e1ac3d0f] .u-tree-search {\n  margin-right: 14px;\n}\n.dws-detail .tree-container .task-tree-container[data-v-346d49957e20d80b60df0157e1ac3d0f] .el-tree {\n  padding-right: 14px;\n}\n.dws-detail .tree-container .task-tree-container[data-v-346d49957e20d80b60df0157e1ac3d0f] .el-tree-node__content {\n  flex: 1;\n  overflow: hidden;\n}\n.tree-node-item[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  display: flex;\n  align-items: center;\n  flex: 1;\n  min-width: 0;\n}\n.tree-node-item .tree-node-more[data-v-346d49957e20d80b60df0157e1ac3d0f] {\n  flex-shrink: 0;\n  opacity: 0;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 4px;\n  color: #909399;\n  cursor: pointer;\n  transition: opacity 0.15s, background-color 0.15s;\n}\n[data-v-346d49957e20d80b60df0157e1ac3d0f] .el-tree-node__content:hover .tree-node-more {\n  opacity: 1;\n}','1','服务层详情',NULL,NULL,0,'2084109831678504960',5);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2060165467882496000','2008730414761971712','error-log-panel','<template>\r\n  <el-dialog\r\n    v-model="visible"\r\n    :title="dialogTitle"\r\n    :draggable="false"\r\n    width="900px"\r\n    class="error-log-dialog"\r\n    destroy-on-close\r\n  >\r\n    <!-- 顶部工具栏 -->\r\n    <div class="error-toolbar">\r\n      <div class="toolbar-left">\r\n        <el-segmented v-model="filter" :options="filterOptions" @change="handleFilterChange" />\r\n      </div>\r\n      <div class="toolbar-right">\r\n        <el-button @click="fetchErrors">\r\n          <Icon icon="el-icon-refresh" class="mr-1" size="13"></Icon>\r\n          刷新\r\n        </el-button>\r\n        <el-button type="danger" :disabled="!errorList.length" plain @click="handleClear">\r\n          <Icon icon="el-icon-delete" class="mr-1" size="13"></Icon>\r\n          清空\r\n        </el-button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 错误列表 -->\r\n    <div v-loading="loading" class="error-list">\r\n      <empty v-if="!loading && filteredList.length === 0" />\r\n      <template v-else>\r\n        <div v-for="item in filteredList" :key="item.id" class="error-item">\r\n          <!-- 左侧色带 -->\r\n          <div class="error-band" :style="{ background: bandColor(item) }" />\r\n          <!-- 内容区 -->\r\n          <div class="error-content">\r\n            <!-- 标签行 -->\r\n            <div class="error-tags">\r\n              <el-tag\r\n                :type="item.level === \'ERROR\' ? \'danger\' : \'warning\'"\r\n                size="small"\r\n                effect="dark"\r\n              >\r\n                {{ item.level === "ERROR" ? "错误" : "警告" }}\r\n              </el-tag>\r\n              <el-tag size="small" effect="plain">{{ phaseLabel(item.phase) }}</el-tag>\r\n              <el-tag v-if="item.nodeLabel" size="small" effect="plain" type="primary">\r\n                {{ item.nodeLabel }}\r\n              </el-tag>\r\n              <el-tag v-if="item.fieldKey" size="small" effect="plain" type="info">\r\n                {{ item.fieldKey }}\r\n              </el-tag>\r\n              <span class="error-time">\r\n                <el-tooltip\r\n                  :content="dayjs(item.occurredAt).format(\'YYYY-MM-DD HH:mm:ss\')"\r\n                  placement="top"\r\n                >\r\n                  <span>{{ relativeTime(item.occurredAt) }}</span>\r\n                </el-tooltip>\r\n              </span>\r\n            </div>\r\n\r\n            <!-- 错误消息 -->\r\n            <div class="error-message">{{ item.message }}</div>\r\n\r\n            <!-- 详情 -->\r\n            <div v-if="item.detail" class="error-detail">{{ item.detail }}</div>\r\n\r\n            <!-- 建议 -->\r\n            <div v-if="item.suggestion" class="error-suggestion">建议：{{ item.suggestion }}</div>\r\n\r\n            <!-- 操作按钮 -->\r\n            <div class="error-actions">\r\n              <el-button\r\n                size="small"\r\n                plain\r\n                type="primary"\r\n                style="align-items: baseline"\r\n                @click="handleCopy(item)"\r\n              >\r\n                <Icon icon="el-icon-CopyDocument" class="mr-1" size="13"></Icon>\r\n                复制错误\r\n              </el-button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </template>\r\n    </div>\r\n\r\n    <template #footer>\r\n      <div class="dialog-footer">\r\n        <el-button @click="visible = false">关闭</el-button>\r\n      </div>\r\n    </template>\r\n  </el-dialog>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, watch } from "vue";\r\nimport { ElMessage, ElMessageBox } from "element-plus";\r\nimport dayjs from "dayjs";\r\n\r\n// ======================== 类型定义 ========================\r\n\r\ntype ErrorPhase = "VALIDATION" | "DEPLOYMENT" | "RUNTIME";\r\ntype ErrorLevel = "ERROR" | "WARNING";\r\n\r\ninterface FlowError {\r\n  id: string;\r\n  level: ErrorLevel;\r\n  phase: ErrorPhase;\r\n  nodeId?: string | null;\r\n  nodeLabel?: string | null;\r\n  fieldKey?: string | null;\r\n  message: string;\r\n  detail?: string | null;\r\n  suggestion?: string | null;\r\n  occurredAt: string;\r\n}\r\n\r\ntype FilterValue = "ALL" | ErrorPhase;\r\n\r\n// ======================== Props & Emits ========================\r\n\r\ninterface Props {\r\n  modelValue: boolean;\r\n  pipelineId: string;\r\n  taskName?: string;\r\n}\r\n\r\nconst props = withDefaults(defineProps<Props>(), {\r\n  taskName: "",\r\n});\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", val: boolean): void;\r\n}>();\r\n\r\n// ======================== 弹窗显隐 ========================\r\n\r\nconst visible = computed({\r\n  get: () => props.modelValue,\r\n  set: (val) => emit("update:modelValue", val),\r\n});\r\n\r\nconst dialogTitle = computed(() => {\r\n  const name = props.taskName || props.pipelineId || "";\r\n  return name ? `${name}` : "异常日志";\r\n});\r\n\r\n// ======================== 数据状态 ========================\r\n\r\nconst loading = ref(false);\r\nconst errorList = ref<FlowError[]>([]);\r\nconst filter = ref<FilterValue>("ALL");\r\n\r\n// ======================== 筛选选项 ========================\r\n\r\nconst filterOptions = computed(() => [\r\n  { label: `全部 (${errorList.value.length})`, value: "ALL" as FilterValue },\r\n  {\r\n    label: `部署 (${errorList.value.filter((e) => e.phase === "DEPLOYMENT").length})`,\r\n    value: "DEPLOYMENT" as FilterValue,\r\n  },\r\n  {\r\n    label: `运行 (${errorList.value.filter((e) => e.phase === "RUNTIME").length})`,\r\n    value: "RUNTIME" as FilterValue,\r\n  },\r\n  {\r\n    label: `配置 (${errorList.value.filter((e) => e.phase === "VALIDATION").length})`,\r\n    value: "VALIDATION" as FilterValue,\r\n  },\r\n]);\r\n\r\nconst filteredList = computed(() => {\r\n  if (filter.value === "ALL") return errorList.value;\r\n  return errorList.value.filter((e) => e.phase === filter.value);\r\n});\r\n\r\n// ======================== 工具函数 ========================\r\n\r\nconst relativeTime = (iso: string): string => {\r\n  const t = new Date(iso).getTime();\r\n  if (Number.isNaN(t)) return iso;\r\n  const diff = Math.floor((Date.now() - t) / 1000);\r\n  if (diff < 5) return "刚刚";\r\n  if (diff < 60) return `${diff}秒前`;\r\n  if (diff < 3600) return `${Math.floor(diff / 60)}分钟前`;\r\n  if (diff < 86400) return `${Math.floor(diff / 3600)}小时前`;\r\n  return new Date(iso).toLocaleString();\r\n};\r\n\r\nconst bandColor = (e: FlowError): string => {\r\n  if (e.level === "WARNING") return "#faad14";\r\n  switch (e.phase) {\r\n    case "VALIDATION":\r\n      return "#fa8c16";\r\n    case "DEPLOYMENT":\r\n      return "#ff4d4f";\r\n    case "RUNTIME":\r\n      return "#ff4d4f";\r\n  }\r\n};\r\n\r\nconst phaseLabel = (p: ErrorPhase): string => {\r\n  return p === "VALIDATION" ? "配置错误" : p === "DEPLOYMENT" ? "部署错误" : "运行错误";\r\n};\r\n\r\n// ======================== API 请求 ========================\r\n\r\nconst fetchErrors = async () => {\r\n  if (!props.pipelineId) return;\r\n  loading.value = true;\r\n  try {\r\n    const response = await $common.get(`/pipelines/${props.pipelineId}/errors`);\r\n    const data = response.data || response;\r\n    errorList.value = Array.isArray(data) ? data : [];\r\n  } catch (error) {\r\n    console.error("获取错误列表失败:", error);\r\n  } finally {\r\n    loading.value = false;\r\n  }\r\n};\r\n\r\nconst clearErrors = async () => {\r\n  if (!props.pipelineId) return;\r\n  try {\r\n    await $common.post(`/pipelines/delete/${props.pipelineId}/errors`);\r\n    ElMessage.success("已清空错误记录");\r\n    await fetchErrors();\r\n  } catch (error: any) {\r\n    ElMessage.error(`清空失败: ${error?.message ?? error}`);\r\n  }\r\n};\r\n\r\n// ======================== 操作处理 ========================\r\n\r\nconst handleFilterChange = () => {\r\n  // 筛选切换，无需额外处理\r\n};\r\n\r\nconst handleClear = async () => {\r\n  try {\r\n    await ElMessageBox.confirm("是否清空所有错误记录？", "提示", {\r\n      type: "warning",\r\n      confirmButtonText: "确定",\r\n      cancelButtonText: "取消",\r\n    });\r\n    await clearErrors();\r\n  } catch {\r\n    // 用户取消\r\n  }\r\n};\r\n\r\nconst handleCopy = (e: FlowError) => {\r\n  const txt = [\r\n    `[${phaseLabel(e.phase)}/${e.level}] ${e.message}`,\r\n    e.nodeLabel ? `节点: ${e.nodeLabel}` : null,\r\n    e.fieldKey ? `字段: ${e.fieldKey}` : null,\r\n    e.detail ? `详情: ${e.detail}` : null,\r\n    e.suggestion ? `建议: ${e.suggestion}` : null,\r\n    `时间: ${dayjs(e.occurredAt).format("YYYY-MM-DD HH:mm:ss")}`,\r\n  ]\r\n    .filter(Boolean)\r\n    .join("\\n");\r\n  $common.copyText(txt);\r\n};\r\n\r\nwatch(\r\n  () => [props.modelValue, props.pipelineId] as const,\r\n  ([visible, id]) => {\r\n    if (visible && id) {\r\n      fetchErrors();\r\n    }\r\n  }\r\n);\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.error-log-dialog :deep(.el-dialog__body) {\r\n  padding: 12px 20px 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-height: 0;\r\n}\r\n\r\n.error-log-dialog {\r\n  /* 工具栏 */\r\n  .error-toolbar {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    margin-bottom: 12px;\r\n  }\r\n\r\n  .toolbar-right {\r\n    display: flex;\r\n    gap: 8px;\r\n  }\r\n\r\n  /* 错误列表 */\r\n  .error-list {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n    min-height: 200px;\r\n    max-height: 480px;\r\n  }\r\n\r\n  /* 错误项 */\r\n  .error-item {\r\n    display: flex;\r\n    border-radius: 6px;\r\n    background: #fafafa;\r\n    border: 1px solid #f0f0f0;\r\n    overflow: hidden;\r\n    margin-bottom: 8px;\r\n  }\r\n\r\n  .error-item:last-child {\r\n    margin-bottom: 0;\r\n  }\r\n\r\n  .error-band {\r\n    width: 4px;\r\n    flex-shrink: 0;\r\n  }\r\n\r\n  .error-content {\r\n    flex: 1;\r\n    padding: 8px 12px;\r\n    min-width: 0;\r\n  }\r\n\r\n  /* 标签行 */\r\n  .error-tags {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n    margin-bottom: 4px;\r\n    flex-wrap: wrap;\r\n  }\r\n\r\n  .error-time {\r\n    margin-left: auto;\r\n    font-size: 12px;\r\n    color: #8c8c8c;\r\n    cursor: default;\r\n    white-space: nowrap;\r\n  }\r\n\r\n  /* 错误消息 */\r\n  .error-message {\r\n    font-size: 13px;\r\n    color: #262626;\r\n    word-break: break-word;\r\n    line-height: 1.5;\r\n  }\r\n\r\n  /* 详情 */\r\n  .error-detail {\r\n    font-size: 12px;\r\n    color: #595959;\r\n    margin-top: 4px;\r\n    word-break: break-word;\r\n    line-height: 1.5;\r\n  }\r\n\r\n  /* 建议 */\r\n  .error-suggestion {\r\n    font-size: 12px;\r\n    color: #1677ff;\r\n    margin-top: 4px;\r\n    line-height: 1.5;\r\n  }\r\n\r\n  /* 操作按钮 */\r\n  .error-actions {\r\n    margin-top: 6px;\r\n    display: flex;\r\n    gap: 8px;\r\n  }\r\n\r\n  /* 底栏 */\r\n  .dialog-footer {\r\n    display: flex;\r\n    justify-content: flex-end;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _u