r-suggestion[data-v-31032ccccf192c477266c39e2ec57348] {\n  font-size: 12px;\n  color: #1677ff;\n  margin-top: 4px;\n  line-height: 1.5;\n}\n.error-log-dialog[data-v-31032ccccf192c477266c39e2ec57348] {\n  /* 操作按钮 */\n}\n.error-log-dialog .error-actions[data-v-31032ccccf192c477266c39e2ec57348] {\n  margin-top: 6px;\n  display: flex;\n  gap: 8px;\n}\n.error-log-dialog[data-v-31032ccccf192c477266c39e2ec57348] {\n  /* 底栏 */\n}\n.error-log-dialog .dialog-footer[data-v-31032ccccf192c477266c39e2ec57348] {\n  display: flex;\n  justify-content: flex-end;\n}','1','异常日志',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2059535771591331840','2005563932859240448','field-display-drawer','<template>\r\n  <el-drawer\r\n    v-model="visible"\r\n    title="字段显示设置"\r\n    :size="600"\r\n    class="field-display-drawer"\r\n    @open="handleOpen"\r\n  >\r\n    <template #header>\r\n      <div class="drawer-header">\r\n        <span class="drawer-title">字段显示设置</span>\r\n        <span class="drawer-subtitle">拖拽调整顺序，勾选控制显示</span>\r\n      </div>\r\n    </template>\r\n\r\n    <div class="drawer-body">\r\n      <!-- 操作提示 -->\r\n      <div class="tips-bar">\r\n        <Icon class="tips-icon" icon="el-icon-InfoFilled" />\r\n        <span>勾选字段将在左侧树中显示，拖拽标签可调整排列顺序</span>\r\n      </div>\r\n\r\n      <!-- 全选 / 反选操作栏 -->\r\n      <div class="action-bar">\r\n        <el-checkbox\r\n          v-model="isAllChecked"\r\n          :indeterminate="isIndeterminate"\r\n          @change="handleCheckAll"\r\n        >\r\n          全选\r\n        </el-checkbox>\r\n        <span class="checked-count">已选 {{ checkedCount }} / {{ sortableItems.length }} 项</span>\r\n      </div>\r\n\r\n      <!-- 可拖拽标签列表 -->\r\n      <div ref="dragContainerRef" class="tag-list">\r\n        <div\r\n          v-for="(item, index) in sortableItems"\r\n          :key="item.field || item._id"\r\n          :data-index="index"\r\n          class="tag-item"\r\n          :class="{ \'tag-item--checked\': item.fieldShow, \'tag-item--dragging\': item._dragging }"\r\n          draggable="true"\r\n          @dragstart="handleDragStart($event, index)"\r\n          @dragover.prevent="handleDragOver($event, index)"\r\n          @dragend="handleDragEnd"\r\n          @drop.prevent="handleDrop($event)"\r\n        >\r\n          <!-- 拖拽手柄 -->\r\n          <Icon class="drag-handle" icon="el-icon-Rank" />\r\n\r\n          <!-- 复选框 -->\r\n          <el-checkbox v-model="item.fieldShow" @change="handleItemCheck" @click.stop />\r\n\r\n          <!-- 标签内容 -->\r\n          <div class="tag-content">\r\n            <span class="tag-title">{{ item.title }}</span>\r\n            <span v-if="item.field" class="tag-field">{{ item.field }}</span>\r\n          </div>\r\n\r\n          <!-- 排序序号标识 -->\r\n          <span class="sort-badge">{{ index + 1 }}</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <template #footer>\r\n      <div class="drawer-footer">\r\n        <el-button @click="handleReset">重置</el-button>\r\n        <el-button @click="visible = false">取消</el-button>\r\n        <el-button type="primary" :loading="saving" @click="handleSave">保存</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, watch } from "vue";\r\nimport { ElMessage } from "element-plus";\r\n\r\n// ======================== Props & Emits ========================\r\ninterface FormItem {\r\n  type: string;\r\n  field?: string;\r\n  title?: string;\r\n  fieldShow?: boolean;\r\n  fieldSortNo?: number;\r\n  display?: boolean;\r\n  props?: Record<string, any>;\r\n  col?: Record<string, any>;\r\n  [key: string]: any;\r\n}\r\n\r\ninterface CategoryItem {\r\n  field: string;\r\n  title: string;\r\n  label?: string;\r\n  fieldShow?: boolean;\r\n  fieldSortNo?: number;\r\n  props?: Record<string, any>;\r\n  [key: string]: any;\r\n}\r\n\r\ninterface SortableItem extends CategoryItem {\r\n  _id: string;\r\n  _dragging: boolean;\r\n}\r\n\r\nconst props = defineProps<{\r\n  modelValue: boolean;\r\n  /** 来自父组件 categoryConfig 的字段列表 */\r\n  categoryConfig: CategoryItem[];\r\n  /** 完整的 formJson（原始表单配置，用于保存时重建） */\r\n  formJson?: FormItem[];\r\n  /** 表单名称，用于调用保存接口 */\r\n  formName?: string;\r\n  /** 任务ID */\r\n  tid?: string;\r\n  /** 环境 */\r\n  env?: string;\r\n}>();\r\n\r\nconst emit = defineEmits<{\r\n  (e: "update:modelValue", val: boolean): void;\r\n  (e: "saved", items: SortableItem[]): void;\r\n}>();\r\n\r\n// ======================== State ========================\r\nconst visible = computed({\r\n  get: () => props.modelValue,\r\n  set: (val) => emit("update:modelValue", val),\r\n});\r\n\r\nconst saving = ref(false);\r\nconst sortableItems = ref<SortableItem[]>([]);\r\nconst dragSrcIndex = ref<number | null>(null);\r\n\r\n// ======================== Computed ========================\r\nconst checkedCount = computed(() => sortableItems.value.filter((i) => i.fieldShow).length);\r\n\r\nconst isAllChecked = computed({\r\n  get: () => sortableItems.value.length > 0 && sortableItems.value.every((i) => i.fieldShow),\r\n  set: () => {},\r\n});\r\n\r\nconst isIndeterminate = computed(() => {\r\n  const c = checkedCount.value;\r\n  return c > 0 && c < sortableItems.value.length;\r\n});\r\n\r\n// ======================== Methods ========================\r\n\r\n/** 初始化列表 */\r\nconst initItems = () => {\r\n  sortableItems.value = props.categoryConfig\r\n    .filter((item) => item.field && item.title)\r\n    .map((item, idx) => ({\r\n      ...item,\r\n      _id: `${item.field}_${idx}`,\r\n      _dragging: false,\r\n      fieldShow: item.fieldShow !== undefined ? item.fieldShow : true,\r\n      fieldSortNo: item.fieldSortNo !== undefined ? item.fieldSortNo : idx,\r\n    }))\r\n    .sort((a, b) => (a.fieldSortNo ?? 0) - (b.fieldSortNo ?? 0));\r\n};\r\n\r\nconst handleOpen = () => {\r\n  initItems();\r\n};\r\n\r\n/** 全选/取消全选 */\r\nconst handleCheckAll = (val: any) => {\r\n  sortableItems.value.forEach((item) => {\r\n    item.fieldShow = val;\r\n  });\r\n};\r\n\r\n/** 单个 checkbox 变化时更新全选状态 */\r\nconst handleItemCheck = () => {\r\n  // 由 computed 自动更新\r\n};\r\n\r\n// ======================== Drag & Drop ========================\r\nconst handleDragStart = (e: DragEvent, index: number) => {\r\n  dragSrcIndex.value = index;\r\n  sortableItems.value[index]._dragging = true;\r\n  if (e.dataTransfer) {\r\n    e.dataTransfer.effectAllowed = "move";\r\n    e.dataTransfer.setData("text/plain", String(index));\r\n  }\r\n};\r\n\r\nconst handleDragOver = (e: DragEvent, index: number) => {\r\n  e.preventDefault();\r\n  if (dragSrcIndex.value === null || dragSrcIndex.value === index) return;\r\n\r\n  // 实时交换位置，产生平滑效果\r\n  const items = [...sortableItems.value];\r\n  const [moved] = items.splice(dragSrcIndex.value, 1);\r\n  items.splice(index, 0, moved);\r\n  dragSrcIndex.value = index;\r\n  sortableItems.value = items;\r\n};\r\n\r\nconst handleDrop = (e: DragEvent) => {\r\n  e.preventDefault();\r\n};\r\n\r\nconst handleDragEnd = () => {\r\n  if (dragSrcIndex.value !== null) {\r\n    sortableItems.value[dragSrcIndex.value]._dragging = false;\r\n  }\r\n  sortableItems.value.forEach((item) => {\r\n    item._dragging = false;\r\n  });\r\n  dragSrcIndex.value = null;\r\n};\r\n\r\n// ======================== Reset ========================\r\nconst handleReset = () => {\r\n  initItems();\r\n  ElMessage.info("已重置为初始状态");\r\n};\r\n\r\n// ======================== Save ========================\r\nconst handleSave = async () => {\r\n  if (!props.formJson || props.formJson.length === 0) {\r\n    ElMessage.warning("表单配置数据为空，无法保存");\r\n    return;\r\n  }\r\n\r\n  saving.value = true;\r\n  try {\r\n    // 构建 field -> { fieldShow, fieldSortNo } 映射\r\n    const fieldMap = new Map<string, { fieldShow: boolean; fieldSortNo: number }>();\r\n    sortableItems.value.forEach((item, idx) => {\r\n      if (item.field) {\r\n        fieldMap.set(item.field, { fieldShow: !!item.fieldShow, fieldSortNo: idx + 1 });\r\n      }\r\n    });\r\n\r\n    // 基于原始 formJson 重建，写入 fieldShow 和 fieldSortNo\r\n    const newFormJson: FormItem[] = props.formJson.map((item) => {\r\n      if (item.field && fieldMap.has(item.field)) {\r\n        const meta = fieldMap.get(item.field)!;\r\n        return {\r\n          ...item,\r\n          fieldShow: meta.fieldShow,\r\n          fieldSortNo: meta.fieldSortNo,\r\n        };\r\n      }\r\n      return { ...item };\r\n    });\r\n\r\n    // 对有 fieldSortNo 的项按排序号整体排序（保留 UTitle 等无字段项的原始位置）\r\n    // 策略：只对有 field 的条目参与排序，无 field 条目保持原始穿插位置\r\n    const serialized = JSON.stringify(newFormJson, null, 2);\r\n\r\n    const params = {\r\n      tid: props.tid || "",\r\n      env: props.env || "",\r\n      formName: props.formName || "",\r\n      formJson: serialized,\r\n    };\r\n\r\n    await (window as any).$common.post("/sym/form?action=save", params);\r\n\r\n    ElMessage.success("保存成功");\r\n    emit("saved", sortableItems.value);\r\n    visible.value = false;\r\n  } catch (err: any) {\r\n    console.error("保存字段显示配置失败", err);\r\n    ElMessage.error(err?.message || "保存失败，请重试");\r\n  } finally {\r\n    saving.value = false;\r\n  }\r\n};\r\n\r\n// ======================== Watch ========================\r\nwatch(\r\n  () => props.categoryConfig,\r\n  () => {\r\n    if (visible.value) {\r\n      initItems();\r\n    }\r\n  },\r\n  { deep: true }\r\n);\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.field-display-drawer {\r\n  :deep(.el-drawer__header) {\r\n    padding: 16px 20px 12px;\r\n    margin-bottom: 0;\r\n    border-bottom: 1px solid #f0f0f0;\r\n  }\r\n\r\n  :deep(.el-drawer__body) {\r\n    padding: 0;\r\n    overflow: hidden;\r\n    display: flex;\r\n    flex-direction: column;\r\n  }\r\n\r\n  :deep(.el-drawer__footer) {\r\n    padding: 12px 20px;\r\n    border-top: 1px solid #f0f0f0;\r\n  }\r\n}\r\n\r\n.drawer-header {\r\n  display: flex;\r\n  flex-direction: column;\r\n\r\n  .drawer-title {\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    color: #1d2129;\r\n    line-height: 1.4;\r\n  }\r\n\r\n  .drawer-subtitle {\r\n    font-size: 12px;\r\n    color: #86909c;\r\n    margin-top: 2px;\r\n  }\r\n}\r\n\r\n.drawer-body {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  overflow: hidden;\r\n  padding: 0 16px;\r\n}\r\n\r\n.tips-bar {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 10px 12px;\r\n  margin: 12px 0 8px;\r\n  background: #e8f4ff;\r\n  border-radius: 6px;\r\n  font-size: 12px;\r\n  color: #1890ff;\r\n\r\n  .tips-icon {\r\n    flex-shrink: 0;\r\n    font-size: 14px;\r\n  }\r\n}\r\n\r\n.action-bar {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 8px 0;\r\n  border-bottom: 1px solid #f5f5f5;\r\n  margin-bottom: 8px;\r\n\r\n  .checked-count {\r\n    font-size: 12px;\r\n    color: #86909c;\r\n  }\r\n}\r\n\r\n.tag-list {\r\n  flex: 1;\r\n  overflow-y: auto;\r\n  padding: 4px 0;\r\n\r\n  &::-webkit-scrollbar {\r\n    width: 4px;\r\n  }\r\n  &::-webkit-scrollbar-thumb {\r\n    background: #d9d9d9;\r\n    border-radius: 2px;\r\n  }\r\n}\r\n\r\n.tag-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 10px 12px;\r\n  margin-bottom: 6px;\r\n  border: 1px solid #e8e8e8;\r\n  border-radius: 8px;\r\n  background: #fafafa;\r\n  cursor: grab;\r\n  transition: all 0.2s ease;\r\n  user-select: none;\r\n\r\n  &:hover {\r\n    background: #f0f7ff;\r\n    border-color: #91caff;\r\n    box-shadow: 0 2px 6px rgba(24, 144, 255, 0.1);\r\n  }\r\n\r\n  &--checked {\r\n    background: #f0f7ff;\r\n    border-color: #bae0ff;\r\n  }\r\n\r\n  &--dragging {\r\n    opacity: 0.5;\r\n    background: #e6f4ff;\r\n    border-color: #1890ff;\r\n    border-style: dashed;\r\n    cursor: grabbing;\r\n  }\r\n\r\n  .drag-handle {\r\n    color: #bfbfbf;\r\n    font-size: 16px;\r\n    cursor: grab;\r\n    flex-shrink: 0;\r\n\r\n    &:hover {\r\n      color: #1890ff;\r\n    }\r\n  }\r\n\r\n  :deep(.el-checkbox) {\r\n    flex-shrink: 0;\r\n    margin-right: 0;\r\n    height: auto;\r\n\r\n    .el-checkbox__label {\r\n      display: none;\r\n    }\r\n  }\r\n\r\n  .tag-content {\r\n    flex: 1;\r\n    min-width: 0;\r\n    display: flex;\r\n    flex-direction: column;\r\n\r\n    .tag-title {\r\n      font-size: 13px;\r\n      font-weight: 500;\r\n      color: #1d2129;\r\n      line-height: 1.4;\r\n      overflow: hidden;\r\n      text-overflow: ellipsis;\r\n      white-space: nowrap;\r\n    }\r\n\r\n    .tag-field {\r\n      font-size: 11px;\r\n      color: #86909c;\r\n      margin-top: 1px;\r\n      font-family: monospace;\r\n      overflow: hidden;\r\n      text-overflow: ellipsis;\r\n      white-space: nowrap;\r\n    }\r\n  }\r\n\r\n  .sort-badge {\r\n    flex-shrink: 0;\r\n    width: 20px;\r\n    height: 20px;\r\n    border-radius: 50%;\r\n    background: #f5f5f5;\r\n    border: 1px solid #e8e8e8;\r\n    font-size: 11px;\r\n    color: #86909c;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    line-height: 1;\r\n  }\r\n}\r\n\r\n.drawer-footer {\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  gap: 8px;\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _withModifiers = ___magic__import__(\'vue\', \'withModifiers\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "drawer-body"\n};\nconst _hoisted_2 = {\n  class: "tips-bar"\n};\nconst _hoisted_3 = {\n  class: "action-bar"\n};\nconst _hoisted_4 = {\n  class: "checked-count"\n};\nconst _hoisted_5 = {\n  ref: "dragContainerRef",\n  class: "tag-list"\n};\nconst _hoisted_6 = ["data-index", "onDragstart", "onDragover"];\nconst _hoisted_7 = {\n  class: "tag-content"\n};\nconst _hoisted_8 = {\n  class: "tag-title"\n};\nconst _hoisted_9 = {\n  key: 0,\n  class: "tag-field"\n};\nconst _hoisted_10 = {\n  class: "sort-badge"\n};\nconst _hoisted_11 = {\n  class: "drawer-footer"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\nconst ElMessage = ___magic__import__(\'element-plus\', \'ElMessage\');\n\n// ======================== Props & Emits ========================\n\nconst __sfc__ = _defineComponent({\n  __name: \'17d06b66dea9ee549b2a7cd32f3281fe\',\n  props: {\n    modelValue: {\n      type: Boolean,\n      required: true\n    },\n    categoryConfig: {\n      type: Array,\n      required: true\n    },\n    formJson: {\n      type: Array,\n      required: false\n    },\n    formName: {\n      type: String,\n      required: false\n    },\n    tid: {\n      type: String,\n      required: false\n    },\n    env: {\n      type: String,\n      required: false\n    }\n  },\n  emits: ["update:modelValue", "saved"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const props = __props;\n    const emit = __emit;\n\n    // ======================== State ========================\n    const visible = computed({\n      get: () => props.modelValue,\n      set: val => emit("update:modelValue", val)\n    });\n    const saving = ref(false);\n    const sortableItems = ref([]);\n    const dragSrcIndex = ref(null);\n\n    // ======================== Computed ========================\n    const checkedCount = computed(() => sortableItems.value.filter(i => i.fieldShow).length);\n    const isAllChecked = computed({\n      get: () => sortableItems.value.length > 0 && sortableItems.value.every(i => i.fieldShow),\n      set: () => {}\n    });\n    const isIndeterminate = computed(() => {\n      const c = checkedCount.value;\n      return c > 0 && c < sortableItems.value.length;\n    });\n\n    // ======================== Methods ========================\n\n    /** 初始化列表 */\n    const initItems = () => {\n      sortableItems.value = props.categoryConfig.filter(item => item.field && item.title).map((item, idx) => ({\n        ...item,\n        _id: `${item.field}_${idx}`,\n        _dragging: false,\n        fieldShow: item.fieldShow !== undefined ? item.fieldShow : true,\n        fieldSortNo: item.fieldSortNo !== undefined ? item.fieldSortNo : idx\n      })).sort((a, b) => (a.fieldSortNo ?? 0) - (b.fieldSortNo ?? 0));\n    };\n    const handleOpen = () => {\n      initItems();\n    };\n\n    /** 全选/取消全选 */\n    const handleCheckAll = val => {\n      sortableItems.value.forEach(item => {\n        item.fieldShow = val;\n      });\n    };\n\n    /** 单个 checkbox 变化时更新全选状态 */\n    const handleItemCheck = () => {\n      // 由 computed 自动更新\n    };\n\n    // ======================== Drag & Drop ========================\n    const handleDragStart = (e, index) => {\n      dragSrcIndex.value = index;\n      sortableItems.value[index]._dragging = true;\n      if (e.dataTransfer) {\n        e.dataTransfer.effectAllowed = "move";\n        e.dataTransfer.setData("text/plain", String(index));\n      }\n    };\n    const handleDragOver = (e, index) => {\n      e.preventDefault();\n      if (dragSrcIndex.value === null || dragSrcIndex.value === index) return;\n\n      // 实时交换位置，产生平滑效果\n      const items = [...sortableItems.value];\n      const [moved] = items.splice(dragSrcIndex.value, 1);\n      items.splice(index, 0, moved);\n      dragSrcIndex.value = index;\n      sortableItems.value = items;\n    };\n    const handleDrop = e => {\n      e.preventDefault();\n    };\n    const handleDragEnd = () => {\n      if (dragSrcIndex.value !== null) {\n        sortableItems.value[dragSrcIndex.value]._dragging = false;\n      }\n      sortableItems.value.forEach(item => {\n        item._dragging = false;\n      });\n      dragSrcIndex.value = null;\n    };\n\n    // ======================== Reset ========================\n    const handleReset = () => {\n      initItems();\n      ElMessage.info("已重置为初始状态");\n    };\n\n    // ======================== Save ========================\n    const handleSave = async () => {\n      if (!props.formJson || props.formJson.length === 0) {\n        ElMessage.warning("表单配置数据为空，无法保存");\n        return;\n      }\n      saving.value = true;\n      try {\n        // 构建 field -> { fieldShow, fieldSortNo } 映射\n        const fieldMap = new Map();\n        sortableItems.value.forEach((item, idx) => {\n          if (item.field) {\n            fieldMap.set(item.field, {\n              fieldShow: !!item.fieldShow,\n              fieldSortNo: idx + 1\n            });\n          }\n        });\n\n        // 基于原始 formJson 重建，写入 fieldShow 和 fieldSortNo\n        const newFormJson = props.formJson.map(item => {\n          if (item.field && fieldMap.has(item.field)) {\n            const meta = fieldMap.get(item.field);\n            return {\n              ...item,\n              fieldShow: meta.fieldShow,\n              fieldSortNo: meta.fieldSortNo\n            };\n          }\n          return {\n            ...item\n          };\n        });\n\n        // 对有 fieldSortNo 的项按排序号整体排序（保留 UTitle 等无字段项的原始位置）\n        // 策略：只对有 field 的条目参与排序，无 field 条目保持原始穿插位置\n        const serialized = JSON.stringify(newFormJson, null, 2);\n        const params = {\n          tid: props.tid || "",\n          env: props.env || "",\n          formName: props.formName || "",\n          formJson: serialized\n        };\n        await window.$common.post("/sym/form?action=save", params);\n        ElMessage.success("保存成功");\n        emit("saved", sortableItems.value);\n        visible.value = false;\n      } catch (err) {\n        console.error("保存字段显示配置失败", err);\n        ElMessage.error(err?.mess