INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016463732836208640','2016463450651824128','field-mapping','<template>\r\n  <div class="field-mapping">\r\n    <DataTable\r\n      :columns="columns"\r\n      :data="fieldMappingData"\r\n      :show-page="false"\r\n      flex-type="flex-[0_1_auto]"\r\n    >\r\n      <!-- 映射关系列 -->\r\n      <template #column-mapping>\r\n        <Icon icon="el-icon-Right"></Icon>\r\n      </template>\r\n      <!-- 码表配置列 -->\r\n      <template #column-dictValue="{ row }">\r\n        <el-select v-model="row.dictValue" clearable style="width: 100%">\r\n          <el-option\r\n            v-for="option in codeTableOptions"\r\n            :key="option.value"\r\n            :label="option.label"\r\n            :value="option.value"\r\n          />\r\n        </el-select>\r\n      </template>\r\n      <!-- 函数配置列 -->\r\n      <template #column-funcValue="{ row }">\r\n        <el-select v-model="row.funcValue" style="width: 100%">\r\n          <el-option\r\n            v-for="option in functionOptions"\r\n            :key="option.value"\r\n            :label="option.label"\r\n            :value="option.value"\r\n          />\r\n        </el-select>\r\n      </template>\r\n      <!-- 目标字段 -->\r\n      <template #column-targetField="{ row }">\r\n        <el-select\r\n          v-model="row.targetField"\r\n          style="width: 100%"\r\n          @change="handleTargetFieldChange(row, $event)"\r\n        >\r\n          <el-option\r\n            v-for="option in targetFields"\r\n            :key="option.tid"\r\n            :label="option.columnName"\r\n            :value="option.columnName"\r\n          />\r\n        </el-select>\r\n      </template>\r\n    </DataTable>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, onMounted } from "vue";\r\n// import { ElMessage } from "element-plus";\r