INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2031218842099359744','2007661287158910976','fileCatalog-data','<template>\r\n  <div v-loading="state.loading" class="card-container h-auto px-5 pt-2 flex-1 flex flex-col">\r\n    <div class="flex-1 pb-2">\r\n      <v-table\r\n        ref="colRef"\r\n        :options="tableOptions"\r\n        :page="{ total: state.total }"\r\n        show-page\r\n        show-toolbar\r\n        @page-change="handleAction(\'page-change\', $event)"\r\n      >\r\n        <template #toolbarButtons>\r\n          <u-title class="pb-1! pt-2!" :name="title">\r\n            <template #right>\r\n              <el-button\r\n                v-if="showUpload"\r\n                type="primary"\r\n                link\r\n                icon="RefreshRight"\r\n                :disabled="!colRef?.getCheckData().length"\r\n                @click="handleAction(\'批量上传\')"\r\n              >\r\n                批量上传\r\n              </el-button>\r\n              <el-button\r\n                v-if="showUpload"\r\n                type="primary"\r\n                link\r\n                icon="RefreshRight"\r\n                @click="handleAction(\'全量上传\')"\r\n              >\r\n                全量上传\r\n              </el-button>\r\n              <el-button\r\n                v-if="isStruct"\r\n                type="danger"\r\n                icon="delete"\r\n                link\r\n                :disabled="!colRef?.getCheckData().length"\r\n                @click="handleAction(\'批量删除\')"\r\n              >\r\n                批量删除\r\n              </el-button>\r\n              <el-button type="primary" link @click="handleAction(\'upload\')">\r\n                <template #icon>\r\n                  <Icon icon="el-icon-uploadFilled" size="16" />\r\n                </template>\r\n                {{ isStruct ? "导入数据" : "上传文件" }}\r\n              </el-button>\r\n            </template>\r\n          </u-title>\r\n        </template>\r\n\r\n        <template #action="{ row }">\r\n          <el-button v-if="!isStruct" type="primary" link>预览</el-button>\r\n          <el-button type="danger" link @click="handleAction(\'delete-row\', row)">删除</el-button>\r\n        </template>\r\n      </v-table>\r\n    </div>\r\n\r\n    <el-dialog\r\n      v-model="state.open"\r\n      width="800px"\r\n      title="导入数据"\r\n      :footer="null"\r\n      header-class="pb-2!"\r\n    >\r\n      <el-segmented v-if="isStruct" v-model="state.type" :options="[\'增量导入\', \'全量导入\']" />\r\n      <DragUpload\r\n        v-model="state.fileList"\r\n        class="mt-3"\r\n        :accept="isStruct ? \'.xlsx,xls\' : \'*\'"\r\n        :title="isStruct ? `上传表格` : \'上传文档、图片、音视频等自由格式\'"\r\n        :upload="upload"\r\n        @success="handleAction(\'upload-success\')"\r\n      >\r\n        <template v-if="isStruct" #tip>\r\n          <el-button\r\n            class="mt-3"\r\n            type="primary"\r\n            link\r\n            icon="download"\r\n            @click="handleAction(\'download\')"\r\n          >\r\n            下载模版\r\n          </el-button>\r\n        </template>\r\n      </DragUpload>\r\n    </el-dialog>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted, reactive, nextTick, computed } from "vue";\r\n\r\nconst props = defineProps({\r\n  fileCatalogId: {\r\n    type: String,\r\n    required: true,\r\n  },\r\n  showUpload: {\r\n    type: Boolean,\r\n    default: true,\r\n  },\r\n  title: {\r\n    type: String,\r\n    default: "数据预览",\r\n  },\r\n});\r\nconst state = reactive({\r\n  open: false,\r\n  loading: false,\r\n  type: "增量导入",\r\n  fileList: [],\r\n  fileCatalog: {},\r\n  total: 0,\r\n  pageNo: 1,\r\n  pageSize: 20,\r\n});\r\n// refs\r\nconst colRef = ref();\r\nconst isStruct = computed(() => true);\r\n\r\nonMounted(() => {\r\n  handleAction("init");\r\n});\r\n\r\nconst handleAction = (type: string, item?: any) => {\r\n  switch (type) {\r\n    case "init":\r\n      init();\r\n      break;\r\n    case "download": {\r\n      downloadApi(props.fileCatalogId);\r\n      break;\r\n    }\r\n    case "upload": {\r\n      state.open = true;\r\n      break;\r\n    }\r\n    case "upload-success": {\r\n      state.open = false;\r\n      handleAction("init");\r\n      break;\r\n    }\r\n    case "delete-row":\r\n      colRef.value?.setLoading(true);\r\n      deleteRowApi(props.fileCatalogId, item["unique_id"] || item["UNIQUE_ID"])\r\n        .then(() => {\r\n          $message.success("删除成功");\r\n          handleAction("init");\r\n        })\r\n        .catch(() => {\r\n          colRef.value?.setLoading(false);\r\n        });\r\n      break;\r\n    case "批量删除": {\r\n      const rowIds = colRef.value\r\n        ?.getCheckData()\r\n        ?.map((el) => {\r\n          return el["unique_id"] || el["UNIQUE_ID"];\r\n        })\r\n        .join(",");\r\n      colRef.value?.setLoading(true);\r\n      $common.handle({\r\n        url: "/dst/catalog/files/curd-data?action=delete",\r\n        method: "get",\r\n        params: {\r\n          tid: props.fileCatalogId,\r\n          rowId: rowIds,\r\n        },\r\n        info: "是否删除?",\r\n        action: "",\r\n        done: (data) => {\r\n          $message.success("删除成功");\r\n          handleAction("init");\r\n        },\r\n        fail: () => {\r\n          colRef.value?.setLoading(false);\r\n        },\r\n      });\r\n      break;\r\n    }\r\n    case "page-change":\r\n      state.pageNo = item.pageNo;\r\n      state.pageSize = item.pageSize;\r\n      handleAction("init");\r\n      break;\r\n\r\n    case "批量上传":\r\n      // 互联网操作\r\n      state.loading = true;\r\n      $common\r\n        .post("/dst/catalog/files/upload", {\r\n          tid: props.fileCatalogId,\r\n          data: colRef.value?.getCheckData().map((el) => {\r\n            const { _X_ROW_KEY, ...rest } = el;\r\n            return rest;\r\n          }),\r\n        })\r\n        .then((data) => {\r\n          $message.success(data);\r\n          state.loading = false;\r\n        })\r\n        .catch(() => {\r\n          state.loading = false;\r\n        });\r\n      break;\r\n\r\n    case "全量上传":\r\n      // 互联网操作\r\n      state.loading = true;\r\n      $common.handle({\r\n        url: "/dst/catalog/files/upload",\r\n        method: "POST",\r\n        data: {\r\n          op: "all",\r\n          tid: props.fileCatalogId,\r\n        },\r\n        info: "是否全量上传?",\r\n        action: "",\r\n        done: (data) => {\r\n          $message.success(data);\r\n          state.loading = false;\r\n        },\r\n        fail: () => {\r\n          state.loading = false;\r\n        },\r\n      });\r\n      break;\r\n  }\r\n};\r\n\r\nconst init = async () => {\r\n  if (!props.fileCatalogId) return;\r\n\r\n  state.loading = true;\r\n  colRef.value?.setLoading(true);\r\n  if (colRef.value) {\r\n    state.loading = false;\r\n  }\r\n  try {\r\n    // 加载详情\r\n    await detailApi(props.fileCatalogId).then((data) => {\r\n      const { columns = [], rows = [], total } = data;\r\n      // 分页处理\r\n      if (total > 0 && rows.length === 0 && state.pageNo > 1) {\r\n        state.pageNo = state.pageNo - 1;\r\n        handleAction("init");\r\n        return;\r\n      }\r\n      state.total = total;\r\n      const cols = columns?.map((col) => ({ title: col, field: col, minWidth: 120 }));\r\n\r\n      const tableCols = [{ type: "checkbox", width: 60, field: "left" }, ...cols];\r\n      tableCols.push({\r\n        title: "操作",\r\n        field: "action",\r\n        width: 80,\r\n        slots: { default: "action" },\r\n      });\r\n      // 转换数据格式\r\n      const tableData = rows;\r\n      nextTick(() => {\r\n        nextTick(() => {\r\n          colRef.value.gridOptions.columns = tableCols;\r\n          colRef.value.gridOptions.data = tableData;\r\n          colRef.value.setLoading(false);\r\n        });\r\n      });\r\n    });\r\n  } finally {\r\n    colRef.value?.setLoading(false);\r\n  }\r\n};\r\n\r\nconst upload = (file: File) => {\r\n  const formData = new FormData();\r\n  formData.append("tid", props.fileCatalogId);\r\n  formData.append("file", file);\r\n  formData.append("isFull", state.type === "全量导入");\r\n  return $common\r\n    .post("/dst/catalog/files/import", formData, {\r\n      "Content-Type": "multipart/form-data",\r\n    })\r\n    .then((data) => {\r\n      $message.success(data);\r\n    });\r\n};\r\n\r\nconst detailApi = (tid: string) => {\r\n  return $common.get("/dst/catalog/files/curd-data?action=get", {\r\n    tid,\r\n    pageNo: state.pageNo,\r\n    pageSize: state.pageSize,\r\n  });\r\n};\r\n\r\nconst deleteRowApi = (tid: string, rowId: string) => {\r\n  return $common.get("/dst/catalog/files/curd-data?action=delete", { tid, rowId });\r\n};\r\n\r\nconst downloadApi = (tid: string) => {\r\n  $common.download("/dst/catalog/files/download", {\r\n    tid,\r\n    isFull: state.type === "全量导入" ? "1" : "0",\r\n  });\r\n};\r\n\r\n// 表单规则\r\n// 表格配置\r\nconst tableOptions = reactive({\r\n  height: "100%",\r\n  cellConfig: {},\r\n  toolbarConfig: {\r\n    slots: {\r\n      buttons: "toolbarButtons",\r\n    },\r\n    buttons: [],\r\n    tools: [],\r\n  },\r\n  columns: [],\r\n});\r\n</script>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createElementVNode = ___magic__imp