INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2031218708510777344','2007661287158910976','fileCatalog-item','<template>\r\n  <div class="card-container h-auto px-5 pt-2 flex-1">\r\n    <u-title name="数据项信息"></u-title>\r\n    <v-table\r\n      ref="colRef"\r\n      :options="tableOptions"\r\n      show-operation\r\n      :show-toolbar="false"\r\n      @btn-click="({ code }) => handleAction(code)"\r\n    >\r\n      <template #colName="{ row }">\r\n        <el-text>\r\n          <Icon\r\n            v-if="row.isPk === \'1\'"\r\n            style="color: var(--el-color-warning); transform: rotate(35deg)"\r\n            icon="el-icon-key"\r\n          />\r\n          {{ row.colName }}\r\n        </el-text>\r\n      </template>\r\n      <template #isPk="{ row }">\r\n        <Icon v-if="row.isPk === \'1\'" icon="yes"></Icon>\r\n      </template>\r\n      <template #isNullable="{ row }">\r\n        <!--    isNullable为1表示可为空，0表示不能为空    -->\r\n        <Icon v-if="row.isNullable === \'0\'" icon="yes"></Icon>\r\n      </template>\r\n    </v-table>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted, reactive } from "vue";\r\n\r\nconst props = defineProps({\r\n  fileCatalogId: String,\r\n});\r\n\r\n// refs\r\nconst colRef = ref();\r\n\r\nonMounted(() => {\r\n  handleAction("init");\r\n});\r\n\r\nconst handleAction = (type: string, item?: any) => {\r\n  switch (type) {\r\n    case "init":\r\n      init();\r\n      break;\r\n    case "保存":\r\n      save();\r\n      break;\r\n  }\r\n};\r\n\r\nconst init = async () => {\r\n  if (!props.fileCatalogId) return;\r\n\r\n  colRef.value?.setLoading(true);\r\n  try {\r\n    const data = await $common.post("/dst/catalog/catalog-items/list", {\r\n      sortField: "sortNo",\r\n      sortDir: "asc",\r\n      tid: props.fileCatalogId,\r\n    });\r\n    colRef.value.setData(data || []);\r\n  } catch (error) {\r\n    console.error("获取catalog数据项失败", error);\r\n  } finally {\r\n    colRef.value?.setLoading(false);\r\n  }\r\n};\r\n\r\nconst save = async () => {\r\n  if (!props.fileCatalogId) return;\r\n\r\n  colRef.value?.setLoading(true);\r\n  try {\r\n    let catalogItems = colRef.value.getData();\r\n    // 重新设置sortNo\r\n    catalogItems = catalogItems.map((item, index) => ({\r\n      ...item,\r\n      sortNo: index + 1,\r\n    }));\r\n    await $common.post("/dst/catalog/saveOrUpdate", {\n      tid: props.fileCatalogId,\r\n      assetType: "catalog",\r\n      catalogItems,\r\n    });\r\n    $message.success("保存成功");\r\n  } finally {\r\n    colRef.value?.setLoading(false);\r\n  }\r\n};\r\n\r\n// 表单规则\r\nconst tableOptions = reactive({\r\n  rowConfig: {\r\n    drag: false,\r\n  },\r\n  toolbarConfig: {\r\n    buttons: [\r\n      {\r\n        code: "append_edit", // 底部新增\r\n        icon: "vxe-icon-add",\r\n        name: "新增数据项",\r\n        status: "primary",\r\n        mode: "text",\r\n      },\r\n      {\r\n        code: "保存",\r\n        icon: "vxe-icon-save",\r\n        name: "保存",\r\n        status: "primary",\r\n        mode: "text",\r\n      },\r\n    ],\r\n    tools: [\r\n      {\r\n        code: "custom",\r\n        icon: "vxe-icon-custom-column",\r\n        mode: "text",\r\n        status: "primary",\r\n        name: "显示列",\r\n      },\r\n      {\r\n        code: "open_export",\r\n        icon: "vxe-icon-download",\r\n        mode: "text",\r\n        status: "primary",\r\n        name: "导出",\r\n      },\r\n    ],\r\n  },\r\n  columns: [\r\n    { type: "seq", width: 70, dragSort: true },\r\n    {\r\n      field: "colName", // 可编辑-插槽渲染\r\n      title: "数据项信息",\r\n      minWidth: 200,\r\n      editRender: {},\r\n      slots: { default: "colName" },\r\n    },\r\n    {\r\n      field: "colEn", // 可编辑-插槽渲染\r\n      title: "数据项英文名",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "colType", // 可编辑-配置渲染\r\n      title: "数据项类型",\r\n      minWidth: 200,\r\n      editRender: { name: "ElSelect", options: $dict.getDictItems("colType"), enabled: false },\r\n    },\r\n    {\r\n      field: "colLength", // 可编辑-配置渲染\r\n      title: "长度",\r\n      width: 120,\r\n      editRender: { name: "ElInputNumber", enabled: false },\r\n    },\r\n    {\r\n      field: "isPk", // 可编辑-配置渲染\r\n      title: "主键",\r\n      width: 80,\r\n      align: "center",\r\n      slots: { default: "isPk" },\r\n    },\r\n    {\r\n      field: "isNullable", // 可编辑-配置渲染\r\n      title: "非空",\r\n      width: 80,\r\n      align: "center",\r\n      slots: { default: "isNullable" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    colName: [{ required: true, content: "数据项名称不能为空", trigger: "blur" }],\r\n    colEn: [{ required: true, content: "数据项英文名不能为空", trigger: "blur" }],\r\n    colType: [{ required: true, content: "数据项类型不能为空", trigger: "blur" }],\r\n  },\r\n});\r\n</script>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\nconst _hoisted_1 = {\n  class: "card-container h-auto px-5 pt-2 flex-1"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\nconst __sfc__ = _defineComponent({\n  __name