ext"\n        }],\n        tools: [{\n          code: "custom",\n          icon: "vxe-icon-custom-column",\n          mode: "text",\n          status: "primary",\n          name: "显示列"\n        }, {\n          code: "open_export",\n          icon: "vxe-icon-download",\n          mode: "text",\n          status: "primary",\n          name: "导出"\n        }]\n      },\n      columns: [{\n        type: "seq",\n        width: 70,\n        dragSort: true\n      }, {\n        field: "colName",\n        // 可编辑-插槽渲染\n        title: "数据项信息",\n        minWidth: 200,\n        editRender: {},\n        slots: {\n          default: "colName"\n        }\n      }, {\n        field: "colEn",\n        // 可编辑-插槽渲染\n        title: "数据项英文名",\n        minWidth: 200,\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "colType",\n        // 可编辑-配置渲染\n        title: "数据项类型",\n        minWidth: 200,\n        editRender: {\n          name: "ElSelect",\n          options: $dict.getDictItems("colType"),\n          enabled: false\n        }\n      }, {\n        field: "colLength",\n        // 可编辑-配置渲染\n        title: "长度",\n        width: 120,\n        editRender: {\n          name: "ElInputNumber",\n          enabled: false\n        }\n      }, {\n        field: "isPk",\n        // 可编辑-配置渲染\n        title: "主键",\n        width: 80,\n        align: "center",\n        slots: {\n          default: "isPk"\n        }\n      }, {\n        field: "isNullable",\n        // 可编辑-配置渲染\n        title: "非空",\n        width: 80,\n        align: "center",\n        slots: {\n          default: "isNullable"\n        }\n      }],\n      editRules: {\n        colName: [{\n          required: true,\n          content: "数据项名称不能为空",\n          trigger: "blur"\n        }],\n        colEn: [{\n          required: true,\n          content: "数据项英文名不能为空",\n          trigger: "blur"\n        }],\n        colType: [{\n          required: true,\n          content: "数据项类型不能为空",\n          trigger: "blur"\n        }]\n      }\n    });\n    return (_ctx, _cache) => {\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_text = _resolveComponent("el-text");\n      const _component_v_table = _resolveComponent("v-table");\n      return _openBlock(), _createElementBlock("div", _hoisted_1, [_createVNode(_component_u_title, {\n        name: "数据项信息"\n      }), _createVNode(_component_v_table, {\n        ref_key: "colRef",\n        ref: colRef,\n        options: tableOptions,\n        "show-operation": "",\n        "show-toolbar": false,\n        onBtnClick: _cache[0] || (_cache[0] = ({\n          code\n        }) => handleAction(code))\n      }, {\n        colName: _withCtx(({\n          row\n        }) => [_createVNode(_component_el_text, null, {\n          default: _withCtx(() => [row.isPk === \'1\' ? (_openBlock(), _createBlock(_component_Icon, {\n            key: 0,\n            style: {\n              "color": "var(--el-color-warning)",\n              "transform": "rotate(35deg)"\n            },\n            icon: "el-icon-key"\n          })) : _createCommentVNode("v-if", true), _createTextVNode(" " + _toDisplayString(row.colName), 1 /* TEXT */)]),\n          _: 2 /* DYNAMIC */\n        }, 1024 /* DYNAMIC_SLOTS */)]),\n        isPk: _withCtx(({\n          row\n        }) => [row.isPk === \'1\' ? (_openBlock(), _createBlock(_component_Icon, {\n          key: 0,\n          icon: "yes"\n        })) : _createCommentVNode("v-if", true)]),\n        isNullable: _withCtx(({\n          row\n        }) => [_createCommentVNode("    isNullable为1表示可为空，0表示不能为空    "), row.isNullable === \'0\' ? (_openBlock(), _createBlock(_component_Icon, {\n          key: 0,\n          icon: "yes"\n        })) : _createCommentVNode("v-if", true)]),\n        _: 1 /* STABLE */\n      }, 8 /* PROPS */, ["options"])]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "fileCatalogId": "props",\n  