INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2048677252751228928','ui_group_approval_20260802','flow-designer','<template>\n  <main class="flow-workbench card-container flex h-full flex-col">\n    <header class="workbench-header">\n      <div class="title-wrap">\n        <el-button circle plain icon="arrow-left" title="返回流程管理" @click="router.back()" />\n        <div>\n          <h2>{{ title }}</h2>\n          <span>业务流程设计</span>\n        </div>\n      </div>\n      <div class="header-actions">\n        <el-button plain icon="refresh" :loading="state.loading" @click="reload">重新加载</el-button>\n      </div>\n    </header>\n\n    <section v-if="flowId" class="workbench-body">\n      <aside class="flow-summary">\n        <div class="summary-title">流程概览</div>\n        <div class="summary-card">\n          <span class="summary-label">流程名称</span>\n          <strong :title="title">{{ title }}</strong>\n        </div>\n        <div class="summary-card">\n          <span class="summary-label">设计内容</span>\n          <div class="step-list">\n            <span><i class="step-dot start"></i>开始</span>\n            <span><i class="step-dot"></i>办理环节</span>\n            <span><i class="step-dot end"></i>结束</span>\n          </div>\n        </div>\n      </aside>\n      <section class="designer-stage" v-loading="state.loading" element-loading-text="正在加载流程设计器">\n        <iframe :key="state.frameKey" :src="designerUrl" title="业务流程设计" @load="state.loading = false"></iframe>\n      </section>\n    </section>\n    <el-empty v-else description="未找到需要设计的流程" />\n  </main>\n</template>\n\n<script setup>\nimport { computed, reactive } from \'vue\';\nimport { useRoute, useRouter } from \'vue-router\';\n\nconst route = useRoute();\nconst router = useRouter();\nconst state = reactive({ loading: true, frameKey: 0 });\nconst flowId = computed(() => String(route.query.id || \'\'));\nconst title = computed(() => String(route.query.title || \'未命名流程\'));\nconst designerUrl = computed(() => `/dev-api/warm-flow-ui/index.html?id=${encodeURIComponent(flowId.value)}&disabled=false`);\nconst reload = () => {\n  state.loading = true;\n  state.frameKey += 1;\n};\n</script>\n\n<style scoped lang="scss">\n.flow-workbench { min-width: 0; overflow: hidden; padding: 0; }\n.workbench-header { display: flex; align-items: center; justify-content: space-between; min-height: 68px; padding: 10px 20px; border-bottom: 1px solid #e4e7ed; background: #fff; }\n.title-wrap, .header-actions { display: flex; align-items: center; gap: 12px; }\n.title-wrap h2 { margin: 0; color: #1d2939; font-size: 18px; line-height: 26px; }\n.title-wrap span, .summary-label { color: #667085; font-size: 12px; }\n.workbench-body { display: grid; grid-template-columns: 204px minmax(0, 1fr); flex: 1; min-height: 0; background: #f5f7fa; }\n.flow-summary { padding: 16px; border-right: 1px solid #e4e7ed; background: #fff; }\n.summary-title { margin: 2px 0 14px; color: #1d2939; font-size: 14px; font-weight: 600; }\n.summary-card { display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; padding: 12px; border: 1px solid #e4e7ed; border-radius: 6px; }\n.summary-card strong { overflow: hidden; color: #344054; font-size: 13px; line-height: 20px; text-overflow: ellipsis; white-space: nowrap; }\n.step-list { display: flex; flex-direction: column; gap: 10px; color: #475467; font-size: 13px; }\n.step-list span { display: flex; align-items: center; gap: 8px; }\n.step-dot { width: 8px; height: 8px; border-radius: 50%; background: #2f6bff; }\n.step-dot.start { background: #12b76a; }.step-dot.end { background: #98a2b3; }\n.designer-stage { position: relative; min-width: 0; min-height: 0; padding: 12px; }\n.designer-stage iframe { display: block; width: 100%; height: 100%; min-height: 560px; border: 1px solid #e4e7ed; border-radius: 6px; background: #fff; }\n@media (max-width: 900px) { .workbench-body { grid-template-columns: 1fr; } .flow-summary { display: none; } .designer-stage { padding: 8px; } }\n</style>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _resolveDirective = ___magic__import__(\'vue\', \'resolveDirective\');\r\nconst _withDirectives = ___magic__import__(\'vue\', \'withDirectives\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = { class: "flow-designer card-container flex h-full flex-col" };\nconst _hoisted_2 = { class: "designer-header" };\nconst _hoisted_3 = { class: "title-wrap" };\nconst _hoisted_4 = { class: "header-actions" };\nconst _hoisted_5 = {\n    key: 0,\n    class: "designer-stage",\n    "element-loading-text": "正在加载流程设计器"\n};\nconst _hoisted_6 = ["src"];\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\nconst useRoute = ___magic__import__(\'vue-router\', \'useRoute\');\r\nconst useRouter = ___magic__import__(\'vue-router\', \'useRouter\');\nconst __sfc__ = _defineComponent({\n    __name: \'flowDesigner20260802\',\n    setup(__props) {\n        const route = useRoute();\n        const router = useRouter();\n        const state = reactive({ loading: true, frameKey: 0 });\n        const flowId = computed(() => String(route.query.id || ""));\n        const title = computed(() => String(route.query.title || "流程设计器"));\n        const designerUrl = computed(() => `/dev-api/warm-flow-ui/index.html?id=${encodeURIComponent(flowId.value)}&disabled=false`);\n        const reload = () => {\n            state.loading = true;\n            state.frameKey += 1;\n        };\n        return (_ctx, _cache) => {\n            const _component_el_button = _resolveComponent("el-button");\n            const _component_el_tag = _resolveComponent("el-tag");\n            const _component_el_empty = _resolveComponent("el-empty");\n            const _directive_loading = _resolveDirective("loading");\n            return (_openBlock(), _createElementBlock("div", _hoisted_1, [\n                _createElementVNode("div", _hoisted_2, [\n                    _createElementVNode("div", _hoisted_3, [\n                        _createVNode(_component_el_button, {\n                            circle: "",\n                            plain: "",\n                            icon: "arrow-left",\n                            title: "返回流程管理",\n                            onClick: _cache[0] || (_cache[0] = ($event) => (_unref(router).back()))\n                        }),\n                        _createElementVNode("div", null, [\n                            _createElementVNode("h3", null, _toDisplayString(title.value), 1 /* TEXT */),\n                            _cache[2] || (_cache[2] = _createElementVNode("span", null, "可视化流程设计", -1 /* CACHED */))\n                        ])\n                    ]),\n                    _createElementVNode("div", _hoisted_4, [\n                        _createVNode(_component_el_tag, {\n                            type: "success",\n                            effect: "plain"\n                        }, {\n                            default: _withCtx(() => [...(_cache[3] || (_cache[3] = [\n                                    _createTextVNode("Warm-Flow 1.8.7", -1 /* CACHED */)\n                                ]))]),\n                            _: 1 /* STABLE */\n                        }),\n                        _createVNode(_component_el_button, {\n                            circle: "",\n                            plain: "",\n                            icon: "refresh",\n                            title: "重新加载画布",\n                            onClick: reload\n                        })\n                    ])\n                ]),\n                (flowId.value)\n                    ? _withDirectives((_openBlock(), _createElementBlock("div", _hoisted_5, [\n                        (_openBlock(), _createElementBlock("iframe", {\n                            key: state.frameKey,\n                            src: designerUrl.value,\n                            title: "流程设计器",\n                            onLoad: _cache[1] || (_cache[1] = ($event) => (state.loading = false))\n                        }, null, 40 /* PROPS, NEED_HYDRATION */, _hoisted_6))\n                    ])), [\n                        [_directive_loading, state.loading]\n                    ])\n                    : (_openBlock(), _createBlock(_component_el_empty, {\n                        key: 1,\n                        description: "缺少流程定义ID，请从流程管理进入设计器"\n                    }))\n            ]));\n        };\n    }\n});\n\n__sfc__.__scopeId = "data-v-flowDesigner20260802"\n__sfc__.__file = "flowDesigner20260802.vue"\nreturn __sfc__','.flow-designer[data-v-flowDesigner20260802] {\n  min-width: 0;\n  overflow: hidden;\n  padding: 0;\n}\n.designer-header[data-v-flowDesigner20260802] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 64px;\n  padding: 10px 16px;\n  border-bottom: 1px solid #e4e7ed;\n  background: #fff;\n}\n.title-wrap[data-v-flowDesigner20260802], .header-actions[data-v-flowDesigner20260802] {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n.title-wrap h3[data-v-flowDesigner20260802] {\n  margin: 0;\n  color: #1d2939;\n  font-size: 16px;\n  line-height: 24px;\n}\n.title-wrap span[data-v-flowDesigner20260802] {\n  color: #98a2b3;\n  font-size: 12px;\n}\n.designer-stage[data-v-flowDesigner20260802] {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n  background: #f5f7fa;\n}\n.designer-stage iframe[data-v-flowDesigner20260802] {\n  display: block;\n  width: 100%;\n  height: 100%;\n  border: 0;\n  background: #fff;\n}','1','流程设计器',NULL,NULL,0,'2084109831678504960',3);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2021030351122022400','76d4913e8fd64fa4ba0a71a333ddd955','form-config','<template>\r\n  <div class="card-container">\r\n    <!-- 左侧边栏 -->\r\n    <aside class="sidebar">\r\n      <!-- 顶部标题 -->\n      <div class="sidebar-header">\n        <div class="sidebar-title">\n          <span class="sidebar-title__icon" aria-hidden="true"><Icon icon="document" /></span>\n          <span>表单配置</span>\n        </div>\n          <el-button\n            class="add-form-button"\n            type="text"\n            title="新增表单"\n            aria-label="新增表单"\n            @click="handleAddForm"\n          >\n            <Icon icon="el-icon-plus" />\n          </el-button>\n      </div>\n\r\n      <!-- 表单列表内容 -->\n      <div class="form-list-section">\n        <div class="form-list">\n          <div\r\n            v-for="form in formList"\r\n            :key="form.tid"\r\n            :class="[\'form-item\', currentFormName === form.formName ? \'form-item--active\' : \'\']"\r\n          >\r\n            <!-- 表单信息和点击区域 -->\r\n            <div class="form-item__body" @click="handleFormChange(form)">\r\n              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">\r\n                <path\r\n                  stroke-linecap="round"\r\n                  stroke-linejoin="round"\r\n                  stroke-width="2"\r\n                  d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"\r\n                />\r\n              </svg>\r\n              <div class="form-item__info">\r\n                <span class="form-item__name" :title="form.formName">\r\n                  {{ form.formName }}\r\n                </span>\r\n                <span class="form-item__count">{{ form.fieldCount }} 个字段</span>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- 编辑删除操作按钮 -->\r\n            <div class="form-item__actions">\r\n              <button\r\n                class="action-btn"\r\n                :title="`重命名 ${form.formName}`"\r\n                @click.stop="handleRenameForm(form)"\r\n              >\r\n                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">\r\n                  <path\r\n                    stroke-linecap="round"\r\n                    stroke-linejoin="round"\r\n                    stroke-width="2"\r\n                    d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"\r\n                  />\r\n                </svg>\r\n              </button>\r\n              <button\r\n                class="action-btn action-btn--delete"\r\n                :title="`删除 ${form.formName}`"\r\n                @click.stop="handleDeleteForm(form)"\r\n              >\r\n                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">\r\n                  <path\r\n                    stroke-linecap="round"\r\n                    stroke-linejoin="round"\r\n                    stroke-width="2"\r\n                    d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"\r\n                  />\r\n                </svg>\r\n              </button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </aside>\r\n\r\n    <!-- 右侧主内容区 -->\r\n    <main v-if="currentFormName" class="main-content">\r\n      <!-- 顶部操作栏 -->\r\n      <header class="main-header">\r\n        <div class="breadcrumb">\n          <span class="breadcrumb__title">\r\n            {{ currentFormName }}\r\n          </span>\r\n          <span v-if="isModified" class="unsaved-dot" title="有未保存的修改" />\r\n          <el-button text @click="handleRenameForm(currentFormObj)">\r\n            <Icon icon="el-icon-edit" />\r\n          </el-button>\r\n        </div>\r\n        <el-button :type="\'primary\'" :disabled="!isModified" @click="handleSave">\r\n          <template #icon><Icon icon="save" /></template>\r\n          保存\r\n        </el-button>\r\n      </header>\r\n\r\n      <!-- 内容区 -->\r\n      <el-splitter class="splitter-content">\r\n        <!-- 代码视图 -->\r\n        <el-splitter-panel class="code-panel" :size="30">\r\n          <CodeEditor\r\n            v-model="currentJson"\r\n            lang="json"\r\n            theme="monokai"\r\n            height="100%"\r\n            @change="handleEditorChange"\r\n          />\r\n        </el-splitter-panel>\r\n\r\n        <!-- 预览视图 -->\r\n        <el-splitter-panel class="preview-panel" :size="70">\r\n          <el-scrollbar>\r\n            <div v-if="previewError" class="preview-error">\r\n              {{ previewError }}\r\n            </div>\r\n            <JsonForm v-else ref="previewFormRef" bordered :rules="currentRules" />\r\n          </el-scrollbar>\r\n        </el-splitter-panel>\r\n      </el-splitter>\r\n    </main>\r\n\r\n    <div v-else class="empty-wrapper">\r\n      <empty />\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, reactive, computed, onMounted, onBeforeUnmount } from "vue";\n  import { cloneDeep } from "lodash-es";\n\r\ninterface FormListItem {\r\n  tid: string;\r\n  formName: string;\r\n  formJson: string;\r\n  env: string;\r\n  fieldCount: number;\r\n}\r\n\r\n// ─── 状态 ────────────────────────────────────────────────────────────────────\r\n\r\nconst configStore = reactive<Record<string, FormListItem[]>>({});\r\nconst currentEnv = ref<string>($setting.systemCode);\nconst currentForm = ref<FormListItem>();\r\nconst currentFormName = ref<string>("");\r\nconst currentJson = ref<string>("");\r\nconst isModified = ref<boolean>(false);\r\nconst formList = ref<FormListItem[]>([]);\r\nconst previewError = ref<string>("");\r\nconst previewFormRef = ref<any>(null);\r\n\r\nconst currentFormObj = computed(() =>\r\n  formList.value.find((f) => f.formName === currentFormName.value)\r\n);\r\n\r\nconst currentRules = computed(() => getRulesArray(currentJson.value));\r\n\r\n// ─── 工具函数 ────────────────────────────────────────────────────────────────\r\n\r\nconst getRulesArray = (value: any): any[] => {\r\n  previewError.value = "";\r\n  if (!value) {\r\n    previewError.value = "请编辑左侧JSON配置以预览表单";\r\n    return [];\r\n  }\r\n  if (Array.isArray(value)) return value;\r\n  if (typeof value === "string") {\r\n    try {\r\n      const parsed = eval(value);\r\n      return Array.isArray(parsed) ? parsed : [];\r\n    } catch (e: any) {\r\n      previewError.value = `配置格式错误，无法预览：${e?.message}`;\r\n      return [];\r\n    }\r\n  }\r\n  return [];\r\n};\r\n\r\n// ─── 表单加载与切换 ─────────────────────────────────────────────────────────\n\nconst loadForms = async (env = currentEnv.value) => {\n  try {\n    const data = await $common.post("/sym/form?action=get", { env });\n    configStore[env] = data.map((el) => {\n      const rules = getRulesArray(el.formJson);\n      return { ...el, fieldCount: Array.isArray(rules) ? rules.length : 0 };\n    });\n    formList.value = configStore[env];\n    if (!currentFormName.value) {\r\n      handleFormChange(formList.value[0]);\r\n    }\r\n    isModified.value = false;\r\n  } catch (error) {\r\n    $message.error("加载表单列表失败");\n    console.error(error);\r\n  }\r\n};\r\n\r\nconst handleFormChange = async (form?: FormListItem) => {\r\n  if (isModified.value) {\r\n    try {\r\n      await $dialog.confirm("当前配置未保存，是否放弃修改并切换表单？", "提示", {\r\n        type: "warning",\r\n      });\r\n    } catch {\r\n      return;\r\n    }\r\n  }\r\n  currentForm.value = form;\r\n  currentFormName.value = form?.formName ?? "";\r\n  currentJson.value = cloneDeep(form?.formJson);\r\n  isModified.value = false;\r\n  previewError.value = "";\r\n};\r\n\r\n// ─── 编辑器 ──────────────────────────────────────────────────────────────────\r\n\r\nconst handleEditorChange = (value: string) => {\r\n  isModified.value = currentForm.value?.formJson !== currentJson.value;\r\n  // 强制更新，否则表单渲染不会更新\r\n  currentRules.value = currentRules.value;\r\n};\r\n\r\n// ─── 保存 ────────────────────────────────────────────────────────────────────\r\n\r\nconst handleSave = async () => {\r\n  if (!currentFormName.value || !isModified.value) return;\r\n\r\n  getRulesArray(currentJson.value);\r\n  if (previewError.value) return;\r\n\r\n  try {\r\n    await $common.post("/sym/form?action=save", {\r\n      tid: currentFormObj.value?.tid,\r\n      env: currentEnv.value,\r\n      formName: currentFormName.value,\r\n      formJson: currentJson.value,\r\n    });\r\n\r\n    // 同步本地缓存\r\n    const envForms = configStore[currentEnv.value] || [];\r\n    const idx = envForms.findIndex((item) => item.formName === currentFormName.value);\r\n    if (idx > -1) {\r\n      envForms[idx].formJson = currentJson.value;\r\n    }\r\n\r\n    isModified.value = false;\r\n    $message.success("配置已保存");\r\n  } catch (error) {\r\n    $message.error("配置格式错误，无法保存");\r\n    console.error(error);\r\n  }\r\n};\r\n\r\n// ─── 新增表单 ────────────────────────────────────────────────────────────────\r\n\r\nconst DEFAULT_FORM_JSON = `[\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "基本信息",\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    title: "名称",\r\n    field: "name",\r\n    col: {\r\n      span: 24,\r\n    },\r\n    $required: true,\r\n  },\r\n]`;\r\n\r\nconst handleAddForm = () => {\r\n  $dialog\r\n    .prompt("", "新增表单", {\r\n      confirmButtonText: "确定",\r\n      cancelButtonText: "取消",\r\n      inputValue: "新表单",\r\n    })\r\n    .then(async ({ value }) => {\r\n      if (!value?.trim()) {\r\n        $message.error("表单名称不能为空");\r\n        return;\r\n      }\r\n      const isDuplicate = (configStore[currentEnv.value] || []).some(\r\n        (item) => item.formName === value\r\n      );\r\n      if (isDuplicate) {\r\n        $message.error(`"${value}" 表单已存在`);\r\n        return;\r\n      }\r\n      try {\r\n        await $common.post("/sym/form?action=save", {\r\n          env: currentEnv.value,\r\n          formName: value,\r\n          formJson: DEFAULT_FORM_JSON,\r\n        });\r\n        currentFormName.value = value;\r\n        currentJson.value = DEFAULT_FORM_JSON;\r\n        isModified.value = false;\r\n        loadForms();\n      } catch (error) {\r\n        console.error(error);\r\n      }\r\n    });\r\n};\r\n\r\n// ─── 重命名表单 ──────────────────────────────────────────────────────────────\r\n\r\nconst handleRenameForm = (form: FormListItem | undefined) => {\r\n  if (!form) return;\r\n  $dialog\r\n    .prompt("", "重命名表单", {\r\n      confirmButtonText: "确定",\r\n      cancelButtonText: "取消",\r\n      inputValue: form.formName,\r\n    })\r\n    .then(async ({ value }) => {\r\n      if (!value?.trim() || value === form.formName) return;\r\n      const isDuplicate = (configStore[currentEnv.value] || []).some(\r\n        (item) => item.formName === value && item.tid !== form.tid\r\n      );\r\n      if (isDuplicate) {\r\n        $message.error(`"${value}" 表单已存在`);\r\n        return;\r\n      }\r\n      try {\r\n        await $common.post("/sym/form?action=save", {\r\n          env: currentEnv.value,\r\n          formName: value,\r\n          tid: form.tid,\r\n        });\r\n        loadForms();\n      } catch (error) {\r\n        $message.error("重命名失败，请重试");\r\n        console.error(error);\r\n      }\r\n    })\r\n    .catch(() => {});\r\n};\r\n\r\n// ─── 删除表单 ────────────────────────────────────────────────────────────────\r\n\r\nconst handleDeleteForm = async (form: FormListItem) => {\r\n  try {\r\n    await $dialog.confirm(`确定要删除表单 【${form.formName}】 吗？`, "删除确认", {\r\n      type: "warning",\r\n      confirmButtonText: "删除",\r\n      cancelButtonText: "取消",\r\n      dangerMode: true,\r\n    });\r\n    await $common.post("/sym/form?action=delete", { tid: form.tid });\r\n\r\n    const newForms = (configStore[currentEnv.value] || []).filter((item) => it