 {\n  class: "result-card__body"\n};\nconst _hoisted_18 = {\n  key: 0,\n  class: "pagination"\n};\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst onActivated = ___magic__import__(\'vue\', \'onActivated\');\nconst useDictStore = ___magic__import__(\'@/store\', \'useDictStore\');\nconst get = ___magic__import__(\'lodash-es\', \'get\');\r\nconst cloneDeep = ___magic__import__(\'lodash-es\', \'cloneDeep\');\r\nconst isEmpty = ___magic__import__(\'lodash-es\', \'isEmpty\');\r\nconst isObject = ___magic__import__(\'lodash-es\', \'isObject\');\r\nconst isString = ___magic__import__(\'lodash-es\', \'isString\');\nconst genEsQueryField = ___magic__import__(\'@/utils\', \'genEsQueryField\');\nconst useRouter = ___magic__import__(\'vue-router\', \'useRouter\');\nconst useRegisterModal = ___magic__import__(\'@/composables\', \'useRegisterModal\');\nconst __sfc__ = _defineComponent({\n  __name: \'af6ee20e6e8d209f06162c811d4a0887\',\n  setup(__props) {\n    const {\n      open\n    } = useRegisterModal();\n    const router = useRouter();\n    const treeRef = ref();\n    const dictDict = useDictStore();\n    const state = reactive({\n      // 顶部\n      activeTop: "",\n      // 索引页签\n      keyword: "",\n      // 搜索关键字\n\n      // 侧边\n      activeSidebar: "",\n      // 侧边页签\n      sidebarKeyword: "",\n      // 侧边搜索关键字\n      valueSidebar: "",\n      // 侧边选中值\n\n      // 右侧\n      valueRight: {},\n      // 右侧选中值\n\n      // 排序\n      sortField: "",\n      sortOrder: "desc",\n      // 列表、分页\n      list: [],\n      total: 0,\n      loading: false,\n      sTime: 0,\n      pageNo: 1,\n      pageSize: 20,\n      // 部门筛选出的业务系统\n      apps: [],\n      // 申请单\n      open: false,\n      registerData: {},\n      // 聚合统计 { field: { key: count } }\n      countMap: {}\n    });\n    const leftValue = computed(() => {\n      return state.valueSidebar ? [state.valueSidebar] : [];\n    });\n\n    // 当前索引配置\n    const currentConfig = ref({});\n    // 索引页签\n    const tabs = computed(() => {\n      return config.search.map(el => el.title).map(el => ({\n        label: el,\n        value: el\n      }));\n    });\n    // 侧边筛选树\n    const sidebarItems = computed(() => {\n      return currentConfig.value.filter?.map(el => ({\n        ...el,\n        options: isString(el.options) ? dictDict.getDictItems(el.options) : el.options\n      })) || [];\n    });\n    // 右侧筛选标签\n    const rightItems = ref([]);\n\n    // 排序\n    const sorts = computed(() => {\n      return currentConfig.value.sort;\n    });\n    // 列表展示字段\n    const displayFields = computed(() => {\n      return currentConfig.value.displayFields;\n    });\n    onMounted(() => {\n      state.activeTop = config.search[0].title;\n      handleAction("init");\n    });\n    onActivated(() => {\n      handleSearch();\n    });\n\n    // 监听关闭登记弹框\n    watch(open, (newVal, oldVal) => {\n      if (newVal === false && oldVal) {\n        handleAction("search");\n      }\n    });\n    const handleAction = (type, item, item2) => {\n      switch (type) {\n        case "init":\n          {\n            // 确定索引配置\n            currentConfig.value = config.search.find(el => el.title === state.activeTop);\n            // 初始化排序\n            const {\n              field = "updatedTime",\n              order = "desc"\n            } = sorts.value.length > 0 ? sorts.value[0] : {};\n            state.sortField = field;\n            state.sortOrder = order;\n            // 设置左侧激活页签\n            state.activeSidebar = sidebarItems.value.length > 0 ? sidebarItems.value[0].title : "";\n            // 清空筛选值\n            state.valueSidebar = "";\n            state.valueRight = {};\n            state.sTime = 0;\n            state.countMap = {};\n            loadFilters();\n            handleAction("search");\n            break;\n          }\n        case "change-top":\n          handleAction("init");\n          break;\n        case "change-left-tab":\n          state.activeSidebar = item.title;\n          state.valueSidebar = "";\n          loadFilters();\n          break;\n        case "change-sort":\n          {\n            // 更新排序\n            const {\n              field,\n              order = "desc"\n            } = item;\n            if (state.sortField === field) {\n              // 切换排序方向\n              state.sortOrder = state.sortOrder === "asc" ? "desc" : "asc";\n            } else {\n              // 切换列，默认降序\n              state.sortField = field;\n              state.sortOrder = order;\n            }\n            handleAction("search");\n            break;\n          }\n        case "click-left":\n          if (state.valueSidebar !== item.value) {\n            state.valueSidebar = item.value;\n          } else {\n            state.valueSidebar = undefined;\n          }\n          // 左右筛选联动\n          loadFilters();\n        case "change-page":\n        case "change-tag":\n          handleAction("search");\n          break;\n        case "search":\n          handleSearch();\n          break;\n\n        // 列表项操作\n        case "apply":\n          $common.post("/dws/market/shoppingCard", {\n            catalogId: item.tid\n          }).then(res => {\n            handleAction("search");\n            $common.addToCart(item2);\n          });\n          break;\n        case "collect":\n          $common.post("/dws/market/collect", {\n            catalogId: item.tid\n          }).then(res => {\n            item.collected = !item.collected;\n            $message.success(res ? "收藏成功" : "取消收藏");\n          });\n          break;\n        case "detail":\n          router.push({\n            path: "detail",\n            query: {\n              id: item.tid,\n              type: item.assetType,\n              title: item.catalogName\n            }\n          });\n          break;\n      }\n    };\n    // 设置点击部门节点时，筛选右侧业务系统\n    const refreshApp = async () => {\n      await $common.post("/dst/catalog/list", {\n        assetType: "app"\n      }).then(data => {\n        state.apps = data.map(el => ({\n          label: el.appName,\n          value: el.tid,\n          orgId: el.orgId\n        }));\n      });\n    };\n\n    // 加载右侧筛选\n    const loadFilters = async () => {\n      const list = currentConfig.value.filter2?.map(el => {\n        const obj = {\n          ...el,\n          options: isString(el.options) ? dictDict.getDictItems(el.options) : el.options\n        };\n        return obj;\n      });\n\n      // 部门筛选业务系统\n      const ind = list.findIndex(el => el.title === "业务系统");\n      const flag = sidebarItems.value.find(el => el.title === state.activeSidebar)?.flag;\n      if (ind > -1) {\n        !state.apps?.length && (await refreshApp());\n        if (["org"].includes(flag) && !!state.valueSidebar) {\n          list[ind].options = state.apps.filter(el => el.orgId === state.valueSidebar);\n        } else {\n          list[ind].options = state.apps;\n        }\n\n        // 取消不存在于 新业务系统列表中的选择(考虑单选情况)\n        if (state.valueRight["业务系统"]?.length === 1) {\n          const appId = state.valueRight["业务系统"][0];\n          const indApp = list[ind].options.find(el => el.value === appId);\n          if (!indApp) {\n            state.valueRight["业务系统"] = [];\n          }\n        }\n      }\n      rightItems.value = list;\n    };\n\n    // 获取es查询语句\n    const getQueryParam = () => {\n      const valueKeys = Object.keys(state.valueRight);\n      if (valueKeys.length === 0) return [];\n      const queryParams = [];\n\n      // 左侧树筛选\n      if (leftValue.value.length > 0) {\n        const section = currentConfig.value.filter.find(section => section.title === state.activeSidebar);\n\n        // 获取es查询字段对象\n        const {\n          query,\n          field\n        } = section?.es || {};\n        const obj = genEsQueryField(query, field, leftValue.value);\n        queryParams.push(obj);\n      }\n\n      // 右侧筛选\n      for (const valueKey of valueKeys) {\n        // 找到字段的配置section\n        const section = currentConfig.value.filter2.find(section => section.title === valueKey);\n        const esValue = state.valueRight[valueKey];\n        if (!isObject(section) || esValue.length === 0) {\n          continue;\n        }\n\n        // 获取es查询字段对象\n        const {\n          query,\n          field\n        } = section?.es || {};\n        const obj = genEsQueryField(query, field, esValue);\n        queryParams.push(obj);\n      }\n      return queryParams;\n    };\n    const handleSearch = async () => {\n      state.loading = true;\n      const startTime = performance.now();\n      try {\n        // 1、提取搜索关键词参数\n        const kParam = state.keyword ? {\n          multi_match: {\n            query: state.keyword,\n            fields: currentConfig.value.searchFields\n          }\n        } : undefined;\n\n        // 2、提取筛选条件参数\n        const queryParams = getQueryParam() || {};\n\n        // 获取列表固定参数\n        const querys = [...currentConfig.value.params];\n        !isEmpty(kParam) && querys.push(kParam);\n        !isEmpty(queryParams) && querys.push(...queryParams);\n        querys.forEach(el => {\n          if (el["range"]) {\n            const fieldName = Object.keys(el["range"])[0];\n            if (el["range"][fieldName]["gte"]) {\n              el["range"][fieldName]["gte"] = $common.parseEsDate(el["range"][fieldName]["gte"]);\n            }\n            if (el["range"][fieldName]["lte"]) {\n              el["range"][fieldName]["lte"] = $common.parseEsDate(el["range"][fieldName]["lte"]);\n            }\n          }\n        });\n        if (state.sTime === 0) {\n          // 只加载一次\n          handleCount(querys);\n        }\n\n        // 执行查询\n        await list(currentConfig.value.indexType, {\n          pageNum: state.pageNo ?? 1,\n          pageSize: state.pageSize ?? 20,\n          query: querys,\n          sortField: state.sortField,\n          sortDir: state.sortOrder\n        }).then(res => {\n          state.list = res.list || [];\n          state.total = res.total;\n        });\n        return {\n          list: state.list,\n          total: state.total\n        };\n      } finally {\n        const endTime = performance.now();\n        state.sTime = Number(((endTime - startTime) * 0.001).toFixed(3));\n        state.loading = false;\n      }\n    };\n\n    /**\r\n     * 列表查询\r\n     * @param indexType\r\n     * @param param\r\n     */\n    const list = async (indexType, param) => {\n      return $common.post("/dws/market/list", param);\n    };\n    const handleCount = async query => {\n      const res = await $common.post("/dws/market/count", {\n        query: [...currentConfig.value.params],\n        aggs: currentConfig.value?.aggs\n      });\n      state.countMap = res;\n    };\n    const orgs = cloneDeep($dict.getDictItems("org"));\n    $common.deepTree(orgs, node => {\n      node.value = node.serialNumber;\n    });\n\n    // 页面配置\n    const config = {\n      // 页面标题\n      title: "数据超市",\n      // 是否只统计一次\n      onceCount: true,\n      // 页面筛选配置\n      search: [{\n        title: "部门目录",\n        /* 固定传参 */\n        params: [{\n          term: {\n            publishStatus: 1\n          }\n        }, {\n          term: {\n            assetType: "catalog"\n          }\n        }],\n        /* 返回字段选择 */\n        sourceFields: [],\n        /* 用于全文搜索字段，可设置权重 */\n        searchFields: ["catalogName^3", "catalogNameEn^2"],\n        /* 排序，order为默认排序 */\n        sort: [{\n          title: "准入时间",\n          field: "createdTime",\n          order: "desc"\n        }, {\n          title: "更新时间",\n          field: "updatedTime",\n          order: "asc"\n        }, {\n          title: "数据量",\n          field: "recordCount",\n          order: "asc"\n        }],\n        /* 左侧树筛选条件，筛选项包含组件类型、字段、选项值、es查询方法、图标配置 */\n        filter: [{\n          type: "