_nav-scroll {\n  overflow: visible;\n}\n.market__top .market__tabs[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tabs__active-bar::after {\n  position: absolute;\n  top: 100%;\n  left: 50%;\n  width: 7px;\n  aspect-ratio: 1/1;\n  margin-inline: auto;\n  content: "";\n  background-color: var(--el-color-primary);\n  clip-path: polygon(0% 0%, 100% 0%, 0% 100%);\n  transform: translateY(-3.5px) rotate(225deg);\n  transform-origin: 50%;\n}\n.market__body[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  display: grid;\n  grid-template-columns: 320px 1022px;\n  gap: 24px;\n}\n.market__sidebar[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  background-color: #fff;\n  border-radius: 8px;\n  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.0784313725);\n}\n.market__sidebar .sidebar-header[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  color: #1b1e26;\n  margin-bottom: 10px;\n}\n.market__sidebar .sidebar-header h3[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  margin-top: 20px !important;\n  margin-left: 20px !important;\n}\n.market__sidebar .sidebar-header .nav-title[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  display: flex;\n  align-items: center;\n  margin-left: 8px;\n  font-family: Source Han Sans SC Bold;\n  font-size: 18px;\n  font-weight: 700;\n  text-align: left;\n}\n.market__sidebar .sidebar-header .img-back.two-nav[data-v-af6ee20e6e8d209f06162c811d4a0887]::before {\n  transform: scaleX(-1); /* 水平镜像 */\n}\n.market__sidebar .sidebar-header .two-nav[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  position: relative;\n  height: 58px;\n}\n.market__sidebar .sidebar-header .two-nav[data-v-af6ee20e6e8d209f06162c811d4a0887]::before {\n  position: absolute;\n  top: 0;\n  left: 0;\n  z-index: 1;\n  width: 100%;\n  height: 100%;\n  content: "";\n  background-image: var(--images-market-tab);\n  transition: all 0.2s;\n}\n.market__sidebar .sidebar-header .left-nav[data-v-af6ee20e6e8d209f06162c811d4a0887],\n.market__sidebar .sidebar-header .right-nav[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  position: absolute;\n  z-index: 1;\n  justify-content: center;\n  width: 50%;\n  height: 100%;\n  cursor: pointer;\n  color: #454750;\n}\n.market__sidebar .sidebar-header .left-nav[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  left: 0;\n}\n.market__sidebar .sidebar-header .right-nav[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  left: 50%;\n}\n.market__sidebar .sidebar-header .active[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  color: var(--el-color-primary);\n}\n.market__sidebar .sidebar-card__search[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  padding: 0 16px 16px;\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  min-height: 444px;\n  padding: 0 16px;\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree {\n  --el-tree-node-content-height: 100%;\n  --tree-node-checked-color: var(--el-color-primary);\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree .el-tree-node__content > .el-tree-node__expand-icon {\n  --el-tree-expand-icon-color: #000000e0;\n  font-size: 16px;\n  padding: 0;\n  margin-top: 2px;\n  margin-right: 4px;\n  width: 24px;\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree .el-icon.is-leaf {\n  width: 10px;\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree .el-tree-node__content {\n  padding: 6px 0;\n  margin-bottom: 5px;\n  border-radius: 6px;\n  align-items: flex-start;\n  color: rgba(0, 0, 0, 0.8784313725);\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree .el-tree-node__content:hover {\n  color: var(--el-color-primary);\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-tree .el-tree-node__content:hover .el-tree-node__expand-icon {\n  color: var(--el-color-primary);\n}\n.market__sidebar .sidebar-card__list[data-v-af6ee20e6e8d209f06162c811d4a0887] .node-title {\n  gap: 16px;\n  align-items: flex-start;\n  justify-content: space-between;\n}\n.result-card[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  padding: 16px 24px 24px 24px;\n  margin-top: 24px;\n  background-color: #fff;\n  border-radius: 8px;\n  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.0784313725);\n}\n.result-card .result-card__header[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  padding-bottom: 16px;\n  padding-left: 7px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  border-bottom: 1px solid #edf0f4;\n  line-height: 20px;\n}\n.result-card .result-card__header .result-count[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  font-size: 14px;\n  color: #323643;\n}\n.result-card .result-card__header .result-count > span[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  color: #0090ff;\n  padding: 0 3px;\n}\n.result-card .result-card__header .result-count i[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  font-style: normal;\n  color: rgb(147, 153, 167);\n  margin-left: 5px;\n}\n.result-card .result-card__header .sort-options[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  display: flex;\n  gap: 16px;\n}\n.result-card .result-card__header .sort-options .sort-item[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  position: relative;\n  margin-right: 15px;\n  font-size: 14px;\n  font-weight: 400;\n  color: #686c80;\n}\n.result-card .result-card__header .sort-options .sort-item.active[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  color: var(--el-color-primary);\n}\n.result-card .result-card__header .sort-options .sort-item .sort-icon[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  position: absolute;\n  right: -18px;\n  cursor: pointer;\n  color: #c1c5d0;\n}\n.result-card .result-card__header .sort-options .sort-item .sort-icon.active[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  color: var(--el-color-primary);\n}\n.result-card .result-card__header .sort-options .sort-item .icon-top[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  top: -2px;\n}\n.result-card .result-card__header .sort-options .sort-item .icon-bottom[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  top: 5px;\n}\n.result-card .result-card__header .left .time[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  margin-left: 8px;\n  color: var(--el-text-color-secondary);\n}\n.result-card__body .pagination[data-v-af6ee20e6e8d209f06162c811d4a0887] {\n  text-align: center;\n  margin-top: 24px;\n  background: #fff;\n  padding: 16px;\n  border-radius: 8px;\n  display: flex;\n  justify-content: center;\n}\n.result-card__body .pagination[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-pagination.is-background .el-pager li.is-active {\n  background-color: transparent;\n  border-radius: 6px;\n  border: 1px solid var(--el-color-primary);\n  color: var(--el-color-primary);\n}\n.result-card__body .pagination[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-pagination.is-background .btn-prev:disabled {\n  background-color: transparent;\n}\n.result-card__body .pagination[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-pagination.is-background .btn-next:disabled {\n  background-color: transparent;\n}\n.result-card__body .pagination[data-v-af6ee20e6e8d209f06162c811d4a0887] .el-pagination.is-background .el-select__wrapper {\n  width: 100px;\n}','1','超市列表页',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018627213819711488','2015737170683826176','market-detail','<template>\r\n  <div\r\n    class="market-detail__container images-market-bg"\r\n    :class="{ \'market-detail__container-MixLayout\': isLayoutDetail }"\r\n  >\r\n    <div class="market-detail__header">\r\n      <detail-breadcrumb />\r\n    </div>\r\n\r\n    <div class="market-detail__body">\r\n      <div class="detail-info">\r\n        <div class="detail-info__icon">\r\n          <Icon :icon="leftIcon" size="83" />\r\n        </div>\r\n        <div class="detail-info-view">\r\n          <div class="detail-info-view-title">\r\n            <h2 :title="title">{{ title }}</h2>\r\n            <div style="margin-top: -8px">\r\n              <el-button type="primary" text @click="handleAction(\'apply\')">\r\n                <template #icon>\r\n                  <Icon icon="apply" />\r\n                </template>\r\n                申请\r\n              </el-button>\r\n              <el-button style="margin-left: -8px" text @click="handleAction(\'collect\')">\r\n                <template #icon>\r\n                  <Icon :icon="isCollected ? \'star-filled\' : \'star\'" style="margin-top: -2px" />\r\n                </template>\r\n                <span style="color: #000000e0">{{ isCollected ? "已收藏" : "收藏" }}</span>\r\n              </el-button>\r\n            </div>\r\n          </div>\r\n          <div class="detail-info-view-fields">\r\n            <div v-for="(item, index) in fields" :key="index" class="field">\r\n              <div class="field-label">{{ item.title }}：</div>\r\n              <div class="field-value">\r\n                <template v-if="item.field === \'resources\'">\r\n                  {{ detail["resType"]?.length > 0 ? "有资源" : "无资源" }}\r\n                </template>\r\n                <dict-label\r\n                  v-else\r\n                  :model-value="detail[item.field]"\r\n                  :options="item.options"\r\n                  :suffix="item.suffix"\r\n                  :tag="false"\r\n                />\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <detail-page class="detail-tabs" type="catalog" tab-type="market-catalog" />\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { computed, onMounted, ref } from "vue";\r\nimport { useRoute } from "vue-router";\r\nimport { usePermissionStore } from "@/store";\r\n\r\n// 判断是否Layout布局下的详情\r\nconst permissionStore = usePermissionStore();\r\nconst isLayoutDetail = computed(() => {\r\n  const matched = route.matched.filter((item) => item.meta && item.meta.title);\r\n  return (\r\n    permissionStore.mixLayoutTopMenus.find((el) => el.path === matched[0].path)?.component?.name ===\r\n    "Layout"\r\n  );\r\n});\r\n\r\nconst route = useRoute();\r\nconst assetType = computed(() => {\r\n  return route.query.type || "catalog";\r\n});\r\nconst title = computed<string>(() => {\r\n  return route.query.title as string; // 增加类型断言，避免TS警告\r\n});\r\nconst id = computed<string>(() => {\r\n  return route.query.id as string; // 增加类型断言\r\n});\r\nconst detail = ref<any>({});\r\nconst isCollected = computed(() => detail.value?.collected);\r\nconst config = computed(() => (assetType.value ? configs[assetType.value] : undefined));\r\n\r\nconst fields = computed(() => {\r\n  return config.value?.fields || []; // 改为数组默认值\r\n});\r\n\r\nconst updateBrowse = async () => {\r\n  if (!id.value) {\r\n    return;\r\n  }\r\n  $common.post("/dws/market/view", { tid: id.value });\r\n};\r\n\r\nconst leftIcon = computed<string | undefined>(() => (config.value as any)?.icon);\r\nonMounted(() => {\r\n  handleAction("init");\r\n});\r\n\r\nconst handleAction = (type: string) => {\r\n  switch (type) {\r\n    case "init":\r\n      updateBrowse();\r\n      //@todo 获取详情\r\n      $common.post("/dws/market/detail", { tid: id.value }).then((data) => {\r\n        detail.value = data;\r\n      });\r\n      break;\r\n    case "collect":\r\n      $common\r\n        .post("/dws/market/collect", {\r\n          catalogId: detail.value.tid,\r\n        })\r\n        .then((res) => {\r\n          detail.value.collected = !detail.value.collected;\r\n          $message.success(res ? "收藏成功" : "取消收藏");\r\n        });\r\n      break;\r\n    case "apply":\r\n      // 可补充申请逻辑\r\n      break;\r\n  }\r\n};\r\n\r\nconst configs = {\r\n  catalog: {\r\n    icon: "market-catalog",\r\n    fields: [\r\n      { title: "提供部门", field: "orgId", options: "org" },\r\n      { title: "资源情况", field: "resources", options: "" },\r\n      { title: "数据条数", field: "recordCount", suffix: "条" },\r\n      { title: "更新时间", field: "updatedTime" },\r\n      { title: "资源类型", field: "resType", options: "assetType" },\r\n      { title: "共享属性", field: "shareType", options: "shareType" },\r\n      { title: "更新周期", field: "updateCycle", options: "updateCycle" },\r\n      { title: "发布时间", field: "publishTime", options: "" },\r\n    ],\r\n  },\r\n  api: {\r\n    icon: "market-api",\r\n    fields: [\r\n      { title: "数源单位", field: "orgId", options: "org" },\r\n      { title: "共享属性", field: "shareType", options: "shareType" },\r\n      { title: "所属网域", field: "storageDomian", options: "" },\r\n      { title: "更新时间", field: "updatedTime", options: "" },\r\n      { title: "请求参数", field: "reqCount", options: "" },\r\n      { title: "响应参数", field: "resCount", options: "" },\r\n      { title: "更新周期", field: "updateCycle", options: "updateCycle" },\r\n      { title: "发布时间", field: "publishTime", options: "" },\r\n    ],\r\n  },\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.market-detail__container-MixLayout {\r\n  margin: -16px -16px 0;\r\n  padding-top: 0 !important;\r\n\r\n  :deep(.detail-container .detail-container__tab) {\r\n    padding: 0 24px !important;\r\n    margin: 0 16px !important;\r\n    border-radius: 8px 8px 0 0 !important;\r\n    .el-tabs__nav-wrap:after {\r\n      height: 1px;\r\n      background-color: rgb(229, 231, 234) !important;\r\n    }\r\n  }\r\n\r\n  :deep(.detail-container .detail-container__content) {\r\n    margin: 0 16px 0 !important;\r\n    border-radius: 0 0 8px 8px !important;\r\n    .card-container {\r\n      border-radius: 0;\r\n    }\r\n  }\r\n}\r\n\r\n.market-detail__container {\r\n  min-height: 100%;\r\n  padding-top: 55px;\r\n  padding-bottom: 8px;\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  background-color: var(--el-bg-color-page);\r\n  background-size: 100% auto;\r\n}\r\n\r\n.market-detail__header {\r\n  width: 1345px;\r\n  display: flex;\r\n  margin-top: 9px;\r\n  margin-bottom: 11px;\r\n}\r\n\r\n.market-detail__body {\r\n  width: 1345px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  flex: 1;\r\n\r\n  .detail-info {\r\n    display: flex;\r\n    flex-direction: row;\r\n    padding-right: 28px;\r\n    background-color: #fff;\r\n    border-radius: 8px;\r\n    flex: 0;\r\n\r\n    &__icon {\r\n      flex: 0 0 auto;\r\n      border: 1px solid #bfd4e3;\r\n      border-radius: 8px;\r\n      width: 85px;\r\n      height: 85px;\r\n      margin: 26px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      background: linear-gradient(180deg, #eef6ff 0%, #fbfdff 100%);\r\n      color: #0b8bf9;\r\n    }\r\n\r\n    &-view {\r\n      flex: 1;\r\n      margin-top: 21px;\r\n      &-title {\r\n        display: flex;\r\n        justify-content: space-between;\r\n        margin-bottom: 11px;\r\n\r\n        h2 {\r\n          color: #383838;\r\n          font-size: 16px;\r\n          margin: 0;\r\n          font-weight: 700;\r\n          word-break: break-all;\r\n          overflow: hidden;\r\n          white-space: nowrap;\r\n          text-overflow: ellipsis;\r\n          max-width: 500px;\r\n          line-height: 32px;\r