INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2015737672091897856','2015737231052443648','market-list','<template>\r\n  <div v-loading="loading" class="list-wrapper">\r\n    <div v-if="dataList.length === 0" class="empty-list">\r\n      <Empty />\r\n    </div>\r\n    <template v-for="(item, ind) in dataList" :key="ind">\r\n      <div class="asset-item">\r\n        <div class="asset-header">\r\n          <div class="header-left">\r\n            <span\r\n              class="title"\r\n              :class="{ new: isNewItem(item.publishTime) }"\r\n              @click="$emit(\'detail\', item)"\r\n            >\r\n              <Icon v-if="item.assetType" :icon="item.assetType" size="18" />\r\n              {{ item[`${item.assetType}Name`] }}\r\n            </span>\r\n            <el-tag\r\n              v-if="item.applyStatus != null"\r\n              size="small"\r\n              :type="getApplyTagConfig(item).type"\r\n              :effect="getApplyTagConfig(item).effect"\r\n              class="apply-status-inline-tag"\r\n              round\r\n            >\r\n              {{ getApplyTagConfig(item).text }}\r\n            </el-tag>\r\n          </div>\r\n          <div class="header-right">\r\n            <Icon icon="eye" style="color: var(--el-color-primary)"></Icon>\r\n            {{ item.viewCount }}\r\n          </div>\r\n        </div>\r\n\r\n        <div class="asset-info">\r\n          <div class="info-row">\r\n            <div\r\n              v-for="(field, index) in displayFields?.slice(0, 3)"\r\n              :key="index"\r\n              class="info-item"\r\n            >\r\n              <span class="field-label">{{ field.title }}:</span>\r\n              <span class="field-value" :title="getFieldValue(item, field.field)">\r\n                <dict-label\r\n                  :model-value="item[field.field]"\r\n                  :options="field.options"\r\n                  :tag="false"\r\n                />\r\n              </span>\r\n            </div>\r\n          </div>\r\n          <div class="info-row">\r\n            <div\r\n              v-for="(field, index) in displayFields?.slice(3, 6)"\r\n              :key="index"\r\n              class="info-item"\r\n            >\r\n              <span class="field-label">{{ field.title }}:</span>\r\n              <span class="field-value" :title="getFieldValue(item, field.field)">\r\n                <dict-label\r\n                  :model-value="item[field.field]"\r\n                  :options="field.options"\r\n                  :show-tag="false"\r\n                />\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class="asset-actions">\r\n          <div class="action-left">\r\n            <el-text\r\n              class="asset-type"\r\n              :class="{ \'resource-active\': hasResourceType(item, \'table\') }"\r\n            >\r\n              <icon icon="db1" size="14" />\r\n              库表\r\n            </el-text>\r\n            <el-text\r\n              class="asset-type"\r\n              :class="{ \'resource-active\': hasResourceType(item, \'api\') }"\r\n            >\r\n              <icon icon="api1" size="14" />\r\n              API\r\n            </el-text>\r\n            <el-text\r\n              class="asset-type"\r\n              :class="{ \'resource-active\': hasResourceType(item, \'file\') }"\r\n            >\r\n              <Icon icon="file1" size="14" />\r\n              文件\r\n            </el-text>\r\n            <el-text\r\n              class="asset-type"\r\n              :class="{ \'resource-active\': hasResourceType(item, \'dir\') }"\r\n            >\r\n              <Icon icon="dir" size="14" />\r\n              文件夹\r\n            </el-text>\r\n          </div>\r\n          <div class="action-right">\r\n            <ElButton\r\n              v-if="showCollect"\r\n              :class="{ collected: item.collected === \'1\' }"\r\n              @click="$emit(\'collect\', item)"\r\n            >\r\n              <template #icon>\r\n                <Icon v-if="item.collected" icon="star-filled" size="14" />\r\n                <Icon v-else icon="star" size="14" />\r\n              </template>\r\n              <span>{{ item.collected ? "已收藏" : "收藏" }}</span>\r\n            </ElButton>\r\n            <template v-if="item.applyStatus === 2">\r\n              <ElButton type="primary" plain @click="$emit(\'detail\', item)">\r\n                <template #icon><Icon icon="eye" /></template>\r\n                查看详情\r\n              </ElButton>\r\n            </template>\r\n            <template\r\n              v-else-if="\r\n                item.applyStatus === 0 || item.applyStatus === 1 || item.applyStatus === \'cart\'\r\n              "\r\n            >\r\n              <ElButton type="primary" plain disabled>\r\n                <template #icon><Icon icon="apply1" /></template>\r\n                申请\r\n              </ElButton>\r\n            </template>\r\n            <template v-else>\r\n              <ElButton type="primary" plain @click="$emit(\'apply\', item, $event)">\r\n                <template #icon><Icon icon="apply" /></template>\r\n                {{ showApply || "申请" }}\r\n              </ElButton>\r\n            </template>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </template>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed } from "vue";\r\n\r\nconst props = withDefaults(\r\n  defineProps<{\r\n    dataList: Array;\r\n    loading: boolean;\r\n    item: Record<string, any>;\r\n    displayFields: { title: string; field: string }[];\r\n    showApply?: string;\r\n    showCollect?: boolean;\r\n  }>(),\r\n  {\r\n    showApply: "申请",\r\n    showCollect: true,\r\n  }\r\n);\r\n\r\ndefineEmits(["collect", "apply", "page-change", "detail"]);\r\n\r\n// 获取字段值\r\nconst getFieldValue = (item: any, field: string) => {\r\n  return item[field];\r\n};\r\n\r\n// 判断是否为新上架项目（7天内）\r\nconst isNewItem = (dateStr: string) => {\r\n  if (!dateStr) return false;\r\n  const publishDate = new Date(dateStr);\r\n  const now = new Date();\r\n  const diffTime = now.getTime() - publishDate.getTime();\r\n  const diffDays = Math.ceil(diffTime / (1000 * 3600 * 24));\r\n  return diffDays <= 7;\r\n};\r\n\r\n// 判断是否包含特定资源类型\r\nconst hasResourceType = (item: any, typeName: string) => {\r\n  return item.resType && item.resType.includes(typeName);\r\n};\r\n\r\n// 申请状态 Tag 配置：根据 applyStatus 返回文字、类型、效果、图标\r\nconst getApplyTagConfig = (item: any) => {\r\n  const s = item.applyStatus;\r\n  if (s === 2) return { text: "已申请", type: "success", effect: "dark", icon: "check-circle" };\r\n  if (s === 1) return { text: "审核中", type: "warning", effect: "dark", icon: "el-icon-Timer" };\r\n  if (s === 0) return { text: "待提交", type: "primary", effect: "dark", icon: "el-icon-Edit" };\r\n  if (s === "cart")\r\n    return { text: "已加购", type: "warning", effect: "dark", icon: "el-icon-ShoppingCartFull" };\r\n  return { text: "申请", type: "primary", effect: "dark", icon: "apply" };\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.list-wrapper {\r\n  position: relative;\r\n}\r\n\r\n.empty-list {\r\n  background: #fff;\r\n  padding: 40px 0;\r\n  border-radius: 8px;\r\n  margin-bottom: 16px;\r\n}\r\n\r\n.asset-item {\r\n  background: #fff;\r\n  border-bottom: 1px solid #f0f0f0;\r\n  padding: 16px 0 16px 8px;\r\n\r\n  //box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);\r\n\r\n  .asset-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: 16px;\r\n\r\n    .header-left {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n\r\n      .apply-status-inline-tag {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 2px;\r\n        flex-shrink: 0;\r\n      }\r\n\r\n      .title {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 4px;\r\n        font-family: PingFang SC Medium;\r\n        font-size: 16px;\r\n        margin-right: 8px;\r\n        cursor: pointer;\r\n        line-height: 20px;\r\n        font-weight: 600;\r\n        color: #1b1e26;\r\n        &:hover {\r\n          color: var(--el-color-primary);\r\n        }\r\n      }\r\n    }\r\n\r\n    .header-right {\r\n      color: #999;\r\n      display: flex;\r\n      align-items: center;\r\n\r\n      .el-icon {\r\n        margin-right: 4px;\r\n      }\r\n    }\r\n  }\r\n\r\n  .asset-info {\r\n    padding-left: 25px;\r\n    line-height: 20px;\r\n    color: #686c80;\r\n    .info-row {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      gap: 6px;\r\n      margin-bottom: 6px;\r\n\r\n      .info-item {\r\n        flex: 1;\r\n        display: flex;\r\n        width: 33%;\r\n\r\n        .field-label {\r\n          min-width: 70px;\r\n          flex-shrink: 0;\r\n        }\r\n\r\n        .field-value {\r\n          overflow: hidden;\r\n          text-overflow: ellipsis;\r\n          white-space: nowrap;\r\n          flex: 1;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  .asset-actions {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    padding-top: 10px;\r\n    padding-left: 25px;\r\n\r\n    .action-left {\r\n      display: flex;\r\n      gap: 16px;\r\n\r\n      .asset-type {\r\n        background-color: #f9f9fc;\r\n        cursor: pointer;\r\n        padding: 8px 12px;\r\n        border-radius: 8px;\r\n        font-family: "Source Han Sans CN";\r\n        font-weight: 400;\r\n        font-size: 14px;\r\n        color: #323643;\r\n\r\n        &-active {\r\n          color: var(--el-color-primary);\r\n          background-color: var(--el-color-primary-light-9);\r\n        }\r\n      }\r\n\r\n      .resource-active {\r\n        color: var(--el-color-primary);\r\n        background-color: var(--el-color-primary-light-9);\r\n      }\r\n    }\r\n\r\n    .action-right {\r\n      display: flex;\r\n      gap: 8px;\r\n      align-items: center;\r\n\r\n      button {\r\n        min-width: 100px;\r\n      }\r\n\r\n      .apply-status-tag {\r\n        height: 32px;\r\n        padding: 0 12px;\r\n        font-size: 13px;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        gap: 4px;\r\n        cursor: default;\r\n        border-radius: 4px;\r\n      }\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _resolveDirective = ___magic__import__(\'vue\', \'resolveDirective\');\r\nconst _withDirectives = ___magic__import__(\'vue\', \'withDirectives\');\nconst _hoisted_1 = {\n  class: "list-wrapper"\n};\nconst _hoisted_2 = {\n  key: 0,\n  class: "empty-list"\n};\nconst _hoisted_3 = {\n  class: "asset-header"\n};\nconst _hoisted_4 = {\n  class: "header-left"\n};\nconst _hoisted_5 = ["onClick"];\nconst _hoisted_6 = {\n  class: "header-right"\n};\nconst _hoisted_7 = {\n