.applyStatus === 1 || item.applyStatus === \'cart\' ? (_openBlock(), _createBlock(_component_ElButton, {\n          key: 2,\n          type: "primary",\n          plain: "",\n          disabled: ""\n        }, {\n          icon: _withCtx(() => [_createVNode(_component_Icon, {\n            icon: "apply1"\n          })]),\n          default: _withCtx(() => [_cache[5] || (_cache[5] = _createTextVNode(" 申请 ", -1 /* CACHED */))]),\n          _: 1 /* STABLE */\n        })) : (_openBlock(), _createBlock(_component_ElButton, {\n          key: 3,\n          type: "primary",\n          plain: "",\n          onClick: $event => _ctx.$emit(\'apply\', item, $event)\n        }, {\n          icon: _withCtx(() => [_createVNode(_component_Icon, {\n            icon: "apply"\n          })]),\n          default: _withCtx(() => [_createTextVNode(" " + _toDisplayString(__props.showApply || "申请"), 1 /* TEXT */)]),\n          _: 1 /* STABLE */\n        }, 8 /* PROPS */, ["onClick"]))])])]);\n      }), 128 /* KEYED_FRAGMENT */))])), [[_directive_loading, __props.loading]]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "ref": "setup-const",\n  "computed": "setup-const",\n  "props": "setup-const",\n  "getFieldValue": "setup-const",\n  "isNewItem": "setup-const",\n  "hasResourceType": "setup-const",\n  "getApplyTagConfig": "setup-const",\n  "dataList": "props",\n  "loading": "props",\n  "item": "props",\n  "displayFields": "props",\n  "showApply": "props",\n  "showCollect": "props"\n} */\n__sfc__.__scopeId = "data-v-5b028fe4409aad5ecaf3c95698caa04f"\n__sfc__.__file = "5b028fe4409aad5ecaf3c95698caa04f.vue"\nreturn __sfc__','.list-wrapper[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  position: relative;\n}\n.empty-list[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  background: #fff;\n  padding: 40px 0;\n  border-radius: 8px;\n  margin-bottom: 16px;\n}\n.asset-item[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  background: #fff;\n  border-bottom: 1px solid #f0f0f0;\n  padding: 16px 0 16px 8px;\n}\n.asset-item .asset-header[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n.asset-item .asset-header .header-left[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.asset-item .asset-header .header-left .apply-status-inline-tag[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n  flex-shrink: 0;\n}\n.asset-item .asset-header .header-left .title[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-family: PingFang SC Medium;\n  font-size: 16px;\n  margin-right: 8px;\n  cursor: pointer;\n  line-height: 20px;\n  font-weight: 600;\n  color: #1b1e26;\n}\n.asset-item .asset-header .header-left .title[data-v-5b028fe4409aad5ecaf3c95698caa04f]:hover {\n  color: var(--el-color-primary);\n}\n.asset-item .asset-header .header-right[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  color: #999;\n  display: flex;\n  align-items: center;\n}\n.asset-item .asset-header .header-right .el-icon[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  margin-right: 4px;\n}\n.asset-item .asset-info[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  padding-left: 25px;\n  line-height: 20px;\n  color: #686c80;\n}\n.asset-item .asset-info .info-row[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  justify-content: space-between;\n  gap: 6px;\n  margin-bottom: 6px;\n}\n.asset-item .asset-info .info-row .info-item[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  flex: 1;\n  display: flex;\n  width: 33%;\n}\n.asset-item .asset-info .info-row .info-item .field-label[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  min-width: 70px;\n  flex-shrink: 0;\n}\n.asset-item .asset-info .info-row .info-item .field-value[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  flex: 1;\n}\n.asset-item .asset-actions[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  justify-content: space-between;\n  padding-top: 10px;\n  padding-left: 25px;\n}\n.asset-item .asset-actions .action-left[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  gap: 16px;\n}\n.asset-item .asset-actions .action-left .asset-type[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  background-color: #f9f9fc;\n  cursor: pointer;\n  padding: 8px 12px;\n  border-radius: 8px;\n  font-family: "Source Han Sans CN";\n  font-weight: 400;\n  font-size: 14px;\n  color: #323643;\n}\n.asset-item .asset-actions .action-left .asset-type-active[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  color: var(--el-color-primary);\n  background-color: var(--el-color-primary-light-9);\n}\n.asset-item .asset-actions .action-left .resource-active[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  color: var(--el-color-primary);\n  background-color: var(--el-color-primary-light-9);\n}\n.asset-item .asset-actions .action-right[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n.asset-item .asset-actions .action-right button[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  min-width: 100px;\n}\n.asset-item .asset-actions .action-right .apply-status-tag[data-v-5b028fe4409aad5ecaf3c95698caa04f] {\n  height: 32px;\n  padding: 0 12px;\n  font-size: 13px;\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  cursor: default;\n  border-radius: 4px;\n}','1','列表组件',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2059526782921035776','2013151015996035072','meta-detail-drawer','<template>\r\n  <el-drawer v-model="visible" :size="700" :with-header="true">\n    <template #header>\n      <div class="detail-drawer__header">\n        <strong>{{ drawerTitle }}</strong>\n        <span v-if="isReadonly">已发布，需下线后才可修改</span>\n      </div>\n    </template>\n    <div class="px-4" :class="{ \'readonly-form\': isReadonly }">\n      <json-form\r\n        ref="detailFormRef"\r\n        :rules="formRules"\r\n        :options="{ form: { labelWidth: \'110px\' } }"\n      />\r\n    </div>\r\n    <template #footer>\r\n      <el-button icon="close" @click="visible = false">关闭</el-button>\r\n      <el-button v-if="!isReadonly" type="primary" :loading="isLoading" @click="saveDetail">\r\n        <template #icon><Icon icon="save" /></template>\r\n        保存\r\n      </el-button>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, watch, nextTick, h } from "vue";\r\nimport { findTreeNodeByTid } from "@/utils";\r\n\r\n// ==================== Props ====================\r\nconst props = defineProps<{\r\n  treeData: any[];\r\n}>();\r\n\r\n// ==================== Emits ====================\r\nconst emit = defineEmits<{\r\n  (e: "saved"): void;\r\n}>();\r\n\r\n// ==================== State ====================\r\nconst visible = ref(false);\r\nconst isLoading = ref(false);\r\nconst metaId = ref<string | undefined>(undefined);\r\nconst isReadonly = ref(false);\r\nconst detailFormRef = ref<any>();\r\n\r\n// 抽屉标题\r\nconst drawerTitle = computed(() => {\r\n  if (isReadonly.value) return "查看数据元";\r\n  return metaId.value ? "编辑数据元" : "注册数据元";\r\n});\r\n\r\n// 质检规则选项\r\nconst qualityRules = ref<any[]>([]);\r\n// 值域（标准代码）选项\r\nconst standardCodes = ref<any[]>([]);\r\n\r\n// ==================== 计算属性：上级分类树选择数据 ====================\r\nconst treeSelectData = computed(() => {\r\n  return props.treeData?.[0]?.children || [];\r\n});\r\n\r\n// ==================== 表单配置 ====================\r\nconst formRules = computed(() => {\r\n  return [\r\n    {\r\n      type: "u-title",\r\n      title: "业务属性",\r\n    },\r\n    {\r\n      field: "metaName",\r\n      title: "数据元名称",\r\n      type: "input",\r\n      required: true,\r\n      col: { span: 24 },\r\n      props: { placeholder: "如：行政区划代码", maxLength: 50, readonly: isReadonly.value },\n      $required: true,\r\n    },\r\n    {\r\n      field: "metaCode",\r\n      title: "数据元英文名",\r\n      type: "input",\r\n      col: { span: 24 },\r\n      props: { placeholder: "如：DATA_ELEMENT_CODE", maxLength: 50, readonly: isReadonly.value },\n      $required: true,\r\n    },\r\n    {\r\n      field: "standardEncode",\r\n      title: "标准编码",\r\n      type: "input",\r\n      col: { span: 24 },\r\n      props: { placeholder: "手动输入或点击生成", maxLength: 50, readonly: isReadonly.value },\n      $required: true,\r\n      renderSlots: {\r\n        append() {\r\n          return h("div", {\r\n            class: "i-svg:idea cursor-pointer",\r\n            style: "font-size: 18px;margin: 0 -8px",\r\n            onClick: () => {\r\n              detailFormRef.value?.setValue({ standardEncode: `ID_${new Date().getTime()}` });\r\n            },\r\n          });\r\n        },\r\n      },\r\n    },\r\n    {\r\n      field: "bizDef",\r\n      title: "业务定义",\r\n      type: "textarea",\r\n      col: { span: 24 },\r\n      props: { placeholder: "描述该数据元的业务含义及应用场景", rows: 3, maxLength: 255, readonly: isReadonly.value },\n    },\r\n    {\r\n      type: "u-title",\r\n      title: "技术属性",\r\n    },\r\n    {\n      field: "dataTypeId",\n      title: "数据类型",\n      type: "DictSelect",\r\n      $required: true,\r\n      col: { span: 24 },\r\n      props: { placeholder: "请选择数据类型", options: "colType" },\n    },\n    {\n      field: "fieldType",\n      title: "规范字段类型",\n      type: "select",\n      col: { span: 12 },\n      options: [\n        { label: "VARCHAR", value: "varchar" },\n        { label: "CHAR", value: "char" },\n        { label: "INTEGER", value: "integer" },\n        { label: "BIGINT", value: "bigint" },\n        { label: "DECIMAL", value: "decimal" },\n        { label: "DATE", value: "date" },\n        { label: "DATETIME", value: "datetime" },\n        { label: "BOOLEAN", value: "boolean" },\n        { label: "TEXT", value: "text" },\n      ],\n      props: { placeholder: "请选择规范字段类型" },\n      $required: true,\n    },\n    {\n      field: "fieldLength",\n      title: "规范长度",\n      type: "input-number",\n      col: { span: 12 },\n      props: { min: 1, max: 65535, precision: 0, placeholder: "请输入最大长度", readonly: isReadonly.value },\n      $required: true,\n    },\n    {\n      field: "numericPrecision",\n      title: "数值精度",\n      type: "input-number",\n      col: { span: 12 },\n      props: { min: 1, max: 65, precision: 0, placeholder: "DECIMAL 可填写", readonly: isReadonly.value },\n    },\n    {\n      field: "numericScale",\n      title: "小数位",\n      type: "input-number",\n      col: { span: 12 },\n      props: { min: 0, max: 30, precision: 0, placeholder: "DECIMAL 可填写", readonly: isReadonly.value },\n    },\n    {\n      field: "formatPattern",\n      title: "格式规则",\n      type: "input",\n      col: { span: 24 },\n      props: { maxLength: 500, placeholder: "可填写正则表达式", readonly: isReadonly.value },\n    },\n    {\n      field: "exampleValue",\n      title: "示例值",\n      type: "input",\n      col: { span: 12 },\n      props: { maxLength: 500, placeholder: "例如：350102", readonly: isReadonly.value },\n    },\n    {\n      field: "standardCodeSet",\n      title: "关联标准代码集",\n      type: "input",\n      col: { span: 12 },\n      props: { maxLength: 100, placeholder: "例如：GB/T 2260", readonly: isReadonly.value },\n    },\n    {\r\n      field: "valueDomainId",\r\n      title: "值域",\r\n      type: "select",\r\n      col: { span: 24 },\r\n      $required: true,\r\n    },\r\n    {\r\n      field: "isNullable",\r\n      title: "可为空值",\r\n      type: "radio",\r\n      col: { span: 12 },\r\n      options: [\r\n        { label: "是", value: 1 },\r\n        { label: "否", value: 0 },\r\n      ],\r\n      value: 0,\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "u-title",\r\n      title: "安全属性",\r\n    },\r\n    {\r\n      type: "select",\r\n      title: "数据分级",\r\n      field: "dataLevel",\r\n      options: [\r\n        { label: "完全公开（L1）", value: "1" },\r\n        { label: "对内公开（L2）", value: "2" },\r\n        { label: "私密（L3）", value: "3" },\r\n        { label: "机密（L4）", value: "4" },\r\n      ],\r\n      props: { placeholder: "请选择数据分级" },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "elTreeSelect",\r\n      title: "数据分类",\r\n      field: "dataCategoryId",\r\n      props: {\r\n        data: treeSelectData,\r\n        valueKey: "tid",\r\n        placeholder: "请选择数据分类",\r\n        clearable: true,\r\n        filterable: true,\r\n        "check-strictly": true,\r\n        "default-expand-all": true,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "u-title",\r\n      title: "质检监控",\r\n    },\r\n    {\r\n      type: "select",\r\n      title: "质检规则",\r\n      field: "qualityRule",\r\n      props: {\r\n        options: [],\r\n        multiple: true,\r\n        placeholder: "请选择质检规则",\r\n      },\r\n    },\r\n    {\r\n      type: "code-editor",\r\n      title: "自定义规则",\r\n      field: "customRule",\r\n      props: {\r\n        showOption: false,\r\n        lang: "javascript",\r\n        readOnly: isReadonly.value,\r\n      },\r\n    },\r\n  ];\r\n});\r\n\r\n// ==================== 公开方法 ====================\r\n\r\n/** 打开新增数据元抽屉 */\r\nconst openAdd = (defaultCategoryId?: string) => {\r\n  metaId.value = undefined;\r\n  isReadonly.value = false;\r\n  visible.value = true;\r\n  nextTick(() => {\r\n    detailFormRef.value?.resetFields();\r\n    if (defaultCategoryId) {\r\n      detailFormRef.value?.setValue({ dataCategoryId: defaultCategoryId });\r\n    }\r\n  });\r\n};\r\n\r\n/** 打开编辑/详情数据元抽屉\r\n * @param row - 行数据\r\n * @param readonly - 是否只读（已发布状态传 true）\r\n */\r\nconst openDetail = (row: any, readonly = false) => {\r\n  metaId.value = row.tid;\r\n  isReadonly.value = readonly;\r\n  visible.value = true;\r\n  nextTick(() => {\r\n    const formData = { ...row };\r\n    formData.qualityRule = formData.qualityRule?.split(",") || [];\r\n    detailFormRef.value?.setValue(formData);\r\n  });\r\n};\r\n\r\ndefineExpose({ openAdd, openDetail });\r\n\r\nconst fetchQualityRules = async () => {\r\n  try {\r\n    const response = await $common.post("/dwm/quality/list");\r\n    if (response && Array.isArray(response)) {\r\n      qualityRules.value = response.map((item: any) => ({\r\n        ...item,\r\n        label: item.ruleName,\r\n        value: item.tid,\r\n      }));\r\n    }\r\n  } catch (error) {\r\n    console.error("Error fetching quality rules:", error);\r\n    qualityRules.value = [];\r\n  }\r\n};\r\n\r\n/** 获取值域（标准代码）列表 */\r\nconst fetchStandardCodes = async () => {\r\n  try {\r\n    const response = await $common.post("/dwm/standard/code/list");\r\n    if (response && Array.isArray(response)) {\r\n      standardCodes.value = response.map((item: any) => ({\r\n        ...item,\r\n        label: item.dictName,\r\n        value: item.tid,\r\n      }));\r\n    }\r\n  } catch (error) {\r\n    console.error("Error fetching standard codes:", error);\r\n    standardCodes.value = [];\r\n  }\r\n};\r\n\r\n// 抽屉打开时更新动态选项\r\nwatch(\r\n  () => visible.value,\r\n  async (newVal) => {\r\n    if (newVal) {\r\n      // 初次打开时若尚未加载，则先加载\r\n      if (!qualityRules.value.length) await fetchQualityRules();\r\n      if (!standardCodes.value.length) await fetchStandardCodes();\r\n      await nextTick();\r\n      detailFormRef.value?.updateFieldOptions("qualityRule", qualityRules.value);\r\n      detailFormRef.value?.updateFieldOptions("valueDomainId", standardCodes.value);\r\n    }\r\n  }\r\n);\r\n\r\n// ==================== 保存 ====================\r\nconst saveDetail = async () => {\r\n  try {\r\n    await detailFormRef.value.validate();\r\n    isLoading.value = true;\r\n    const saveData = await detailFormRef.value.getFormData();\r\n\r\n    const categoryNode = findTreeNodeByTid(props.treeData, saveData.dataCategoryId);\r\n    if (categoryNode) {\r\n      saveData.dataCategoryName = categoryNode.label;\r\n      saveData.dataCategoryPath = categoryNode.treePath;\r\n    }\r\n    if (saveData.qualityRule?.length) {\r\n      saveData.qualityRule = saveData.qualityRule.join(",");\r\n    } else {\r\n      saveData.qualityRule = null;\r\n    }\r\n\r\n    await $common.post("/dwm/standard/element/metaSaveOrUpdate", {\r\n      ...saveData,\r\n      publishStatus: metaId.value ? null : 1, // 新增时默认发布状态\r\n      tid: metaId.value,\r\n    });\r\n\r\n    ElMessage.success("保存成功");\r\n    visible.value = false;\r\n    emit("saved");\r\n  } catch (e) {\r\n    console.error("Error saving data:", e);\r\n  } finally {\r\n    isLoading.value = false;\r\n  }\r\n};\r\n</script>\n\n<style scoped>\n.detail-drawer__header {\n  display: flex;\n  align-items: baseline;\n  gap: 10px;\n}\n\n.detail-drawer__header span {\n  color: #909399;\n  font-size: 13px;\n  font-weight: normal;\n}\n\n.readonly-form :deep(.el-select),\n.readonly-form :deep(.el-input-number),\n.readonly-form :deep(.el-radio-group),\n.readonly-form :deep(.i-svg\\:idea),\n.readonly-form :deep(.code-editor) {\n  pointer-events: none;\n}\n</style>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _cr