lay: flex;\n  align-items: baseline;\n  gap: 10px;\n}\n.detail-drawer__header span[data-v-meta-detail-drawer] {\n  color: #909399;\n  font-size: 13px;\n  font-weight: normal;\n}\n.readonly-form[data-v-meta-detail-drawer] .el-select,\n.readonly-form[data-v-meta-detail-drawer] .el-input-number,\n.readonly-form[data-v-meta-detail-drawer] .el-radio-group,\n.readonly-form[data-v-meta-detail-drawer] .i-svg\\:idea,\n.readonly-form[data-v-meta-detail-drawer] .code-editor {\n  pointer-events: none;\n}','1','数据元抽屉',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2059526706911858688','2013151015996035072','meta-import-drawer','<template>\r\n  <el-drawer\r\n    v-if="visible"\r\n    v-model="visible"\r\n    :size="700"\r\n    :with-header="true"\r\n    title="导入数据元"\n    body-class="bg-gray-50"\r\n    @closed="onClosed"\r\n  >\r\n    <div>\r\n      <el-card shadow="never" body-class="flex flex-col gap-6">\r\n        <div class="import-notice">\r\n          <div class="flex-y-center gap-2 text-primary">\r\n            <Icon icon="info" class="text-primary" />\r\n            <span>导入说明</span>\r\n          </div>\r\n          <div class="ml-6 mt-2">\r\n            <el-text type="info">\r\n              <div>1. 模板包含“数据元”和“数据字典”两张工作表，数据字典通过数据元英文名关联。</div>\n              <div>2. 支持上传模板导出的 xlsx 文件；单次最多导入 200 个数据元。</div>\n              <div>3. 系统会先校验必填项、字段类型、重复代码及关联关系，校验通过后再保存。</div>\n            </el-text>\r\n          </div>\r\n        </div>\r\n        <div class="flex-x-between">\r\n          <h5>第一步：获取模板</h5>\r\n          <el-button type="primary" plain icon="download" @click="handleDownloadTemplate">\r\n            下载导入模板\n          </el-button>\r\n        </div>\r\n        <div>\r\n          <h5>第二步：上传填写好的文件</h5>\r\n          <el-upload\r\n            drag\r\n            :file-list="uploadFiles"\r\n            :auto-upload="false"\r\n            accept=".xlsx"\n            @change="onUploadChange"\r\n          >\r\n            <div class="flex flex-col items-center justify-center h-36">\r\n              <el-icon class="text-4xl mb-2"><UploadFilled /></el-icon>\r\n              <el-text>点击或拖拽文件到此处上传</el-text>\r\n              <el-text type="info">仅支持 .xlsx 格式文件</el-text>\n            </div>\r\n          </el-upload>\r\n        </div>\r\n      </el-card>\r\n    </div>\r\n    <template #footer>\r\n      <el-button type="primary" @click="handleParse">解析文件</el-button>\r\n      <el-button icon="close" @click="visible = false">关闭</el-button>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref } from "vue";\r\nimport { UploadFilled } from "@element-plus/icons-vue";\r\n\r\nconst emit = defineEmits<{\r\n  (e: "download-template"): void;\r\n  (e: "parse", files: any[]): void;\r\n}>();\r\n\r\nconst visible = ref(false);\r\nconst uploadFiles = ref<any[]>([]);\r\n\r\n/** 外部调用：打开抽屉 */\r\nconst open = () => {\r\n  uploadFiles.value = [];\r\n  visible.value = true;\r\n};\r\n\r\nconst onClosed = () => {\r\n  uploadFiles.value = [];\r\n};\r\n\r\nconst onUploadChange = (_file: any, files: any[]) => {\r\n  uploadFiles.value = files;\r\n};\r\n\r\nconst handleDownloadTemplate = () => {\r\n  emit("download-template");\r\n};\r\n\r\nconst handleParse = () => {\r\n  emit("parse", uploadFiles.value);\r\n};\r\n\r\nconst close = () => {\n  visible.value = false;\n};\n\ndefineExpose({ open, close });\n</script>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\nconst _hoisted_1 = { class: "import-notice" };\nconst _hoisted_2 = { class: "flex-y-center gap-2 text-primary" };\nconst _hoisted_3 = { class: "ml-6 mt-2" };\nconst _hoisted_4 = { class: "flex-x-between" };\nconst _hoisted_5 = { class: "flex flex-col items-center justify-ce