INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018969070206529536','2001578680197386240','my-apply','<template>\r\n  <div class="card-container flex-1">\r\n    <page-list\r\n      :loading="state.loading"\r\n      :list="state.data"\r\n      :total="state.total"\r\n      :columns="state.fields"\r\n      :page-no="state.pageNo"\r\n      :page-size="state.pageSize"\r\n      @title-click="handleAction(\'detail\', $event)"\r\n    >\r\n      <template #toolbar>\r\n        <div class="flex-x-between">\r\n          <el-segmented\r\n            v-model="state.seg"\r\n            :options="[\'审批通过\', \'审批中\', \'不通过\', \'被驳回\', \'撤回\', \'待提交\']"\r\n            @change="handleAction(\'refresh\')"\r\n          />\r\n          <el-space>\r\n            <el-input\r\n              v-model="state.keyword"\r\n              clearable\r\n              placeholder="请输入搜索关键词"\r\n              suffix-icon="search"\r\n              @keydown.enter="handleAction(\'refresh\')"\r\n            />\r\n          </el-space>\r\n        </div>\r\n      </template>\r\n\r\n      <template #icon>\r\n        <Icon icon="catalog" size="18" />\r\n      </template>\r\n\r\n      <template #title="{ row }">\r\n        {{ row.applyName }}\r\n      </template>\r\n\r\n      <template #status="{ row }">\r\n        <dict-label\r\n          v-if="row.flowStatus"\r\n          round\r\n          :model-value="row.flowStatus"\r\n          options="flowStatus"\r\n          tag-class="text-sm border-0"\r\n        >\r\n          {{ row.status }}\r\n        </dict-label>\r\n      </template>\r\n\r\n      <template #actions="{ row }">\r\n        <template v-if="state.seg === \'待提交\'">\r\n          <el-button type="primary" link icon="EditPen" @click="handleAction(\'继续申请\', row)">\r\n            继续申请\r\n          </el-button>\r\n          <el-button type="danger" link icon="delete" @click="handleAction(\'删除\', row)">\r\n            删除\r\n          </el-button>\r\n        </template>\r\n\r\n        <el-button\r\n          v-if="[\'审批中\', \'被驳回\', \'不通过\', \'撤回\'].includes(state.seg)"\r\n          type="primary"\r\n          link\r\n          icon="view"\r\n          @click="handleAction(\'查看进度\', row)"\r\n        >\r\n          查看进度\r\n        </el-button>\r\n\r\n        <el-button\r\n          v-if="[\'不通过\'].includes(state.seg)"\r\n          type="warning"\r\n          link\r\n          icon="EditPen"\r\n          @click="handleAction(\'再次申请\', row)"\r\n        >\r\n          再次申请\r\n        </el-button>\r\n\r\n        <el-button\r\n          v-if="[\'被驳回\', \'撤回\'].includes(state.seg)"\r\n          type="warning"\r\n          link\r\n          icon="EditPen"\r\n          @click="handleAction(\'修改申请\', row)"\r\n        >\r\n          修改申请\r\n        </el-button>\r\n\r\n        <!--        <el-button-->\r\n        <!--          v-if="state.seg === \'审批通过\'"-->\r\n        <!--          type="primary"-->\r\n        <!--          link-->\r\n        <!--          icon="download"-->\r\n        <!--          @click="handleAction(\'文件下载\', row)"-->\r\n        <!--        >-->\r\n        <!--          文件下载-->\r\n        <!--        </el-button>-->\r\n        <!--        <el-button-->\r\n        <!--          v-if="state.seg === \'审批通过\'"-->\r\n        <!--          type="primary"-->\r\n        <!--          link-->\r\n        <!--          icon="view"-->\r\n        <!--          @click="handleAction(\'查看调用信息\', row)"-->\r\n        <!--        >-->\r\n        <!--          查看调用信息-->\r\n        <!--        </el-button>-->\r\n        <el-button\r\n          v-if="state.seg === \'审批中\'"\r\n          type="danger"\r\n          link\r\n          @click="handleAction(\'申请撤回\', row)"\r\n        >\r\n          申请撤回\r\n        </el-button>\r\n        <el-button type="primary" link @click="handleAction(\'查看申请单\', row)">\r\n          查看申请单\r\n        </el-button>\r\n      </template>\r\n    </page-list>\r\n\r\n    <el-drawer v-model="state.open" size="400" title="查看进度">\r\n      <time-line\r\n        :list="state.nodes?.map((el) => ({ ...el, nodeType: el.skipType, org: el.orgName }))"\r\n      />\r\n    </el-drawer>\r\n\r\n    <el-dialog v-model="state.view" :title="`${state.applyData.applyName}申请单`" width="60%">\r\n      <apply-json-form :init-data="state.applyData" :editable="false" />\r\n    </el-dialog>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { reactive, onMounted, watch, ref, h } from "vue";\r\nimport { useRouter } from "vue-router";\r\nimport { useRegisterModal } from "@/composables";\r\nimport { ElCheckbox } from "element-plus";\r\n\r\n// 登记弹框\r\nconst { openRegisterModal, open } = useRegisterModal();\r\nconst router = useRouter();\r\nconst state = reactive<any>({\r\n  loading: false,\r\n  seg: "审批通过",\r\n  keyword: "",\r\n  data: [],\r\n  fields: [],\r\n  total: 0,\r\n  pageNo: 1,\r\n  pageSize: 20,\r\n  // 查看进度\r\n  open: false,\r\n  nodes: [],\r\n\r\n  // 查看申请单\r\n  view: false,\r\n  applyData: "",\r\n});\r\n\r\n// 监听关闭登记弹框\r\nwatch(open, (newVal, oldVal) => {\r\n  if (newVal === false && oldVal) {\r\n    handleAction("refresh");\r\n  }\r\n});\r\n\r\nonMounted(() => {\r\n  fetchList();\r\n});\r\n\r\nconst handleAction = (type: string, row?: any) => {\r\n  switch (type) {\r\n    case "refresh":\r\n      fetchList();\r\n      break;\r\n    case "detail":\r\n      router.push({\r\n        path: "detail",\r\n        query: { type: "catalog", id: row.detail.tid, title: row.detail.catalogName },\r\n      });\r\n      break;\r\n    case "再次申请":\r\n      openRegisterModal({\r\n        registerClass: "apply",\r\n        registerData: {\r\n          editType: "再次申请", // 复制一份申请单\r\n          apply: { tid: row.tid },\r\n        },\r\n      });\r\n      break;\r\n    case "继续申请":\r\n      openRegisterModal({\r\n        registerClass: "apply",\r\n        registerData: {\r\n          apply: { tid: row.tid },\r\n        },\r\n      });\r\n      break;\r\n    case "修改申请":\r\n      // 被驳回、撤回的申请单，处于节点1的审批中\r\n      openRegisterModal({\r\n        registerClass: "apply",\r\n        registerData: {\r\n          editType: "修改申请", // 修改同一份申请单\r\n          apply: { tid: row.tid },\r\n        },\r\n      });\r\n      break;\r\n    case "删除":\r\n      handleDraft(row);\r\n      break;\r\n    case "查看进度":\r\n      state.open = true;\r\n      $common\r\n        .get("/sym/approval/info", {\n          businessId: row.businessId,\r\n        })\r\n        .then(({ flowNodes }) => {\r\n          state.nodes = flowNodes;\r\n        });\r\n      break;\r\n    case "申请撤回":\r\n      $common.handle({\r\n        url: "/sym/approval/operate/handle",\n        info: `是否撤回该申请【${row.applyName}】`,\r\n        action: "撤回",\r\n        data: {\r\n          taskId: row.taskId,\r\n          businessId: row.businessId,\r\n          handleType: "REVOKE",\r\n          message: "",\r\n          approveType: row.approveType,\r\n        },\r\n        done: () => {\r\n          handleAction("refresh");\r\n        },\r\n      });\r\n      break;\r\n\r\n    case "查看申请单":\r\n      state.applyData = row;\r\n      state.view = true;\r\n      break;\r\n  }\r\n};\r\n\r\nconst fetchList = async () => {\r\n  state.loading = true;\r\n  try {\r\n    state.data = [];\r\n    const segMap: Record<string, number | null> = {\r\n      审批通过: "2",\r\n      审批中: "1",\r\n      不通过: "3",\r\n      被驳回: "5",\r\n      撤回: "4",\r\n      待提交: "0",\r\n    };\r\n    const targetStatus = segMap[state.seg] ?? undefined;\r\n\r\n    // 接口返回的数据\r\n    const { total, list } = await $common.post("/sym/approval/query/applyPage", {\n      pageNum: state.pageNo,\r\n      pageSize: state.pageSize,\r\n      sortField: "updatedTime",\r\n      sortDir: "desc",\r\n      conditions: [\r\n        {\r\n          field: "flowStatus",\r\n          value: targetStatus === undefined ? null : targetStatus,\r\n          type: "match",\r\n        },\r\n        {\r\n 