hoisted_1 = {\n  class: "card-container datasource-explorer-page flex flex-col px-5 pt-5 pb-2 w-full h-full"\n};\nconst _hoisted_2 = {\n  class: "left-panel"\n};\nconst _hoisted_3 = {\n  class: "tree-container"\n};\nconst _hoisted_4 = {\n  key: 0\n};\nconst _hoisted_5 = {\n  key: 1\n};\nconst _hoisted_6 = {\n  class: "list-toolbar"\n};\nconst _hoisted_7 = {\n  class: "list-toolbar__primary"\n};\nconst _hoisted_8 = {\n  class: "list-filters"\n};\nconst _hoisted_9 = {\n  class: "flex-y-center"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst onActivated = ___magic__import__(\'vue\', \'onActivated\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\nconst useRouter = ___magic__import__(\'vue-router\', \'useRouter\');\nconst useRegisterModal = ___magic__import__(\'@/composables\', \'useRegisterModal\');\r\nconst useDetailDialog = ___magic__import__(\'@/composables\', \'useDetailDialog\');\nconst get = ___magic__import__(\'lodash-es\', \'get\');\nconst __sfc__ = _defineComponent({\n  __name: \'9276d2e5fe1fccacff32a5b794f2a493\',\n  props: {\n    appId: {\n      type: String,\n      required: false\n    },\n    editable: {\n      type: Boolean,\n      required: false,\n      default: true\n    },\n    dataSourceType: {\n      type: String,\n      required: false\n    }\n  },\n  setup(__props) {\n    const props = __props;\n    const countMap = ref({});\n    const orgTreeSource = ref([]);\n    const treeStatistics = ref({\n      total: 0,\n      orgCounts: {},\n      orgApps: {}\n    });\n\n    // 登记弹框\n    const {\n      openRegisterModal,\n      open\n    } = useRegisterModal();\n    const {\n      openDetailDialog\n    } = useDetailDialog();\n    const router = useRouter();\n    const treeRef = ref();\n    const tableRef = ref();\n    const treeData = ref([{\n      name: "全部",\n      value: "",\n      serialNumber: $user.orgRootSerialNumber,\n      children: []\n    }]);\n    const state = reactive({\n      status: undefined,\n      keyword: undefined,\n      leftSelectNode: {},\n      deletingIds: [],\n      filters: {},\n      // 筛选条件\n      leftLoading: false,\n      rightLoading: false\n    });\n    const isLoadTree = computed(() => !props.appId && $user.isAdmin);\n\n    // 监听关闭登记弹框\n    watch(open, (newVal, oldVal) => {\n      if (newVal === false && oldVal) {\n        handleAction("query");\n      }\n    });\n    onActivated(() => {\n      tableRef.value?.refresh(false);\n    });\n    onMounted(() => {\n      handleAction("init");\n    });\n\n    /** 与数据源页相同：父部门包含所有后代，不重复累加业务系统节点。 */\n    const getTreeNodeCount = node => {\n      if (!node) return 0;\n      if (node.type === "app") return Number(node.count || 0);\n      if (!node.value) return Number(treeStatistics.value.total || 0);\n      const own = Number(get(countMap.value, `org.${node.value}`, 0)) || 0;\n      return own + (node.children || []).filter(child => child.type !== "app").reduce((sum, child) => sum + getTreeNodeCount(child), 0);\n    };\n    const isAllZero = node => getTreeNodeCount(node) === 0;\n    const collectTreeNodeIds = node => {\n      if (!node || node.type === "app") return [];\n      return [node.value, ...(node.children || []).filter(child => child.type !== "app").flatMap(child => collectTreeNodeIds(child))].filter(Boolean);\n    };\n\n    /** 递归过滤掉统计值为 0 且后代也全为 0 的节点 */\n    const filterZeroNodes = nodes => {\n      return nodes.filter(node => !isAllZero(node)).map(node => ({\n        ...node,\n        children: node.children?.length ? filterZeroNodes(node.children) : node.children\n      }));\n    };\n\n    /** 末级部门下显示业务系统，不再追加数据库层级。目录数量来自目录权威表。 */\n    const appendApplicationNodes = nodes => (nodes || []).map(node => {\n      const children = appendApplicationNodes(node.children || []);\n      const apps = children.length === 0 ? (treeStatistics.value.orgApps[node.value] || []).map(app => ({\n        ...app,\n        type: "app",\n        name: app.label,\n        ownerOrgId: node.value,\n        serialNumber: app.value,\n        children: []\n      })) : [];\n      return {\n        ...node,\n        type: "org",\n        children: [...children, ...apps]\n      };\n    });\n    const applyStatistics = result => {\n      treeStatistics.value = {\n        total: Number(result?.total || 0),\n        orgCounts: result?.orgCounts || {},\n        orgApps: result?.orgApps || {}\n      };\n      countMap.value = {\n        org: treeStatistics.value.orgCounts\n      };\n      treeData.value[0].children = appendApplicationNodes(filterZeroNodes(orgTreeSource.value));\n      // 用新树中的节点更新当前筛选对象，避免旧子树遗漏新登记的部门。\n      const findNode = (nodes, selected) => {\n        for (const node of nodes) {\n          if (node.value === selected.value && node.type === selected.type && (node.type !== "app" || node.ownerOrgId === selected.ownerOrgId)) return node;\n          const found = findNode(node.children || [], selected);\n          if (found) return found;\n        }\n      };\n      if (state.leftSelectNode.value) {\n        state.leftSelectNode = findNode(treeData.value[0].children, state.leftSelectNode) || {};\n      }\n      expandDefaultOrganizationPath();\n    };\n\n    /** 首屏仅展开“全部 → 第一层机构 → 内设机构”；更下级节点保持收起。 */\n    const expandDefaultOrganizationPath = () => {\n      nextTick(() => {\n        nextTick(() => {\n          const tree = treeRef.value?.getTree?.();\n          if (!tree) return;\n          let current = treeData.value[0];\n          for (let depth = 0; current && depth < 3; depth += 1) {\n            const treeNode = tree.getNode(current.value);\n            if (treeNode) treeNode.expanded = true;\n            current = (current.children || []).find(child => child.type !== "app");\n          }\n          tree.setCurrentNode?.(state.leftSelectNode.value ? state.leftSelectNode : treeData.value[0]);\n        });\n      });\n    };\n    const handleAction = async (type, row) => {\n      switch (type) {\n        case "init":\n          if (!isLoadTree.value) {\n            // 没有左侧树，刷新数据列表\n            handleAction("refresh");\n            break;\n          }\n\n          // 左侧加载树\n          state.leftLoading = true;\n          if (isLoadTree.value) {\n            Promise.all([$common.post("/sym/org/getOrgTree", {\n              parentId: $user.orgRootId\n            }), $common.post("/dst/catalog/treeStatistics", {\n              conditions: buildConditions(false)\n            })]).then(([data, result]) => {\n              orgTreeSource.value = data || [];\n              applyStatistics(result);\n            }).catch(error => {\n              console.error("加载数据目录组织机构树失败:", error);\n              $message.error("组织机构树加载失败，请稍后重试");\n            }).finally(() => {\n              state.leftLoading = false;\n            });\n          }\n          break;\n        case "node-click":\n          // 左侧树点击\n          state.leftSelectNode = row;\n          handleAction("refresh");\n          break;\n        case "filter-change":\n          // 筛选条件变化\n          state.filters = row || {};\n          handleAction("query");\n          break;\n        case "query":\n          if (isLoadTree.value) {\n            state.leftLoading = true;\n            $common.post("/dst/catalog/treeStatistics", {\n              conditions: buildConditions(false)\n            }).then(applyStatistics).then(() => tableRef.value?.refresh(true)).catch(error => {\n              console.error("刷新数据目录统计失败:", error);\n              $message.error("目录统计刷新失败，请稍后重试");\n            }).finally(() => {\n              state.leftLoading = false;\n            });\n          } else {\n            tableRef.value?.refresh(true);\n          }\n          break;\n        case "refresh":\n          tableRef.value?.refresh(true);\n          break;\n        case "详情":\n          if (props.dataSourceType === "dwm") {\n            openDetailDialog({\n              ...row,\n              dataSourceType: props.dataSourceType\n            });\n          } else {\n            router.push({\n              path: "detail",\n              query: {\n                id: row.id,\n                type: row.type,\n                title: row.title,\n                dataSourceType: row.type == "catalog" ? "ods" : undefined\n              }\n            });\n          }\n          break;\n        case "register":\n          if (!props.editable) return;\n          openRegisterModal({\n            registerClass: "catalog",\n            // 若在app详情中的catalog列表，登记需附带appId\n            registerData: props.appId ? {\n              app: {\n                tid: props.appId\n              }\n            } : {},\n            updateFormRule: [{\n              field: "dataSourceType",\n              value: "ods"\n            }]\n          });\n          break;\n        case "编辑":\n          if (!props.editable || !row?.tid) return;\n          openRegisterModal({\n            registerClass: "catalog",\n            registerData: {\n              catalog: [row]\n            }\n          });\n          break;\n        case "删除":\n          if (!props.editable || !row?.tid || state.deletingIds.includes(row.tid)) return;\n          state.deletingIds.push(row.tid);\n          try {\n            await $common.handle({\n              url: "/dst/catalog/delete",\n              info: `确认删除数据目录【${row.catalogName}】及其已登记数据项？此操作不会删除来源数据库中的物理表。`,\n              data: {\n                tid: row.tid\n              },\n              done: () => handleAction("query")\n            });\n          } finally {\n            state.deletingIds = state.deletingIds.filter(tid => tid !== row.tid);\n          }\n          break;\n      }\n    };\n\n    // 树统计与列表共用筛选条件；树分面不限制当前选中的部门。\n    const buildConditions = (includeTree = true) => {\n      const conditions = [\n      // 资产类型\n      {\n        field: "assetType",\n        value: "catalog",\n        type: "match"\n      },\n      // 读取ods层目录，手动登记目录均为ods\n      {\n        field: "dataSourceType",\n        value: props.dataSourceType || "ods",\n        type: "match"\n      }];\n      if (state.status) {\n        // 审批中由 flowStatus=1 判断，其余按 assetStatus 筛选\n        conditions.push(state.status === "1" ? {\n          field: "flowStatus",\n          value: "1",\n          type: "match"\n        } : {\n          field: "assetStatus",\n          value: state.status,\n          type: "match"\n        });\n      }\n      if (state.keyword) {\n        // 关键字查询\n        conditions.push({\n          field: "catalogName",\n          value: state.keyword,\n          type: "like"\n        });\n      }\n      if (includeTree && state.leftSelectNode.value) {\n        const {\n          type = "org",\n          value,\n          ownerOrgId\n        } = state.leftSelectNode;\n        if (type === "app") {\n          conditions.push({\n            field: "appId",\n            value,\n            type: "match"\n          });\n          if (ownerOrgId) conditions.push({\n            field: "orgId",\n            value: ownerOrgId,\n            type: "match"\n          });\n        } else {\n          conditions.push({\n            field: "orgIds",\n            value: collectTreeNodeIds(state.leftSelectNode),\n            type: "in"\n          });\n        }\n      }\n      if (props.appId) {\n        // 添加appId查询条件\n        conditions.push({\n          field: "appId",\n          value: props.appId,\n          type: "match"\n        });\n      }\n      // 处理筛选条件\n      if (state.filters) {\n        Object.keys(state.filters).forEach(key => {\n          const value = state.filters[key];\n          if (value !== undefined && value !== null && value !== "") {\n            conditions.push({\n              field: key,\n              value,\n              type: "match"\n            });\n          }\n        });\n      }\n\n      // 非管理员添加组织id条件\n      if (!$user.isAdmin) {\n        conditions.push({\n          field: "orgId",\n          value: $user.orgId,\n          type: "match"\n        });\n      }\n      return conditions;\n    };\n\n    // 列表接口仅查询保存的目录，无补建和源表状态准入。\n    const fetchData = async ({\n      pageNo: pageNum,\n      pageSize\n    }) => {\n      const {\n        list = [],\n        total\n      } = await $common.post("/dst/catalog/page", {\n        sortField: "updatedTime",\n        sortDir: "desc",\n        pageNum,\n        pageSize,\n        conditions: buildConditions()\n      });\n      return {\n        list: list.map(item => ({\n          ...item,\n          displayStatus: Number(item.flowStatus) === 1 ? 1 : Number(item.assetStatus)\n        })),\n        total\n      };\n    };\n\n    // 表格配置\n    const cols = [{\n      label: "数据目录名称",\n      prop: "catalogName",\n      minWidth: 250\n    }, {\n      label: "关联数据资源",\n      prop: "sourceTableName",\n      minWidth: 250\n    }, {\n      label: "数据组织",\n      prop: "dataSourceType",\n      options: "dataSourceType",\n      props: {\n        showPath: false\n      },\n      width: 120\n    }, {\n      label: "数据所在层级",\n      prop: "dataLevel",\n      options: "dataLevel",\n      width: 120\n    }, {\n      label: "共享属性",\n      prop: "shareType",\n      options: "shareType",\n      width: 120\n    }, {\n      label: "注册时间",\n      prop: "regTime",\n      type: "date"\n    }, {\n      label: "状态",\n      prop: "displayStatus",\n      options: "status",\n      width: 120\n    }, {\n      label: "操作",\n      prop: "action",\n      align: "right",\n      headerAlign: "center",\n      width: 120,\n      buttons: [{\n        if: () => props.editable,\n        type: "primary",\n        link: true,\n        label: "编辑",\n        disabled: row => state.deletingIds.includes(row.tid),\n        click: row => handleAction("编辑", row)\n      }, {\n        if: () => props.editable,\n        type: "danger",\n        link: true