ion .el-pagination__sizes {\n    display: none;\n}\n}\n@media (max-width: 760px) {\n.list-toolbar[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] {\n    align-items: stretch;\n}\n.list-filters[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] {\n    width: 100%;\n    flex-wrap: wrap;\n    margin-left: 0;\n}\n.filter-select[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] {\n    flex: 1 1 calc(50% - 5px);\n    width: auto;\n}\n.keyword-input[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] {\n    flex: 1 1 100%;\n    width: 100%;\n    max-width: none;\n}\n}\n@media (max-width: 840px) {\n[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] .catalog-register-drawer {\n    min-width: 100%;\n}\n.catalog-drawer-context[data-v-4ce32f23f9d8e22a4fded507eb36a1f8],\n  .catalog-selection-tip[data-v-4ce32f23f9d8e22a4fded507eb36a1f8] {\n    display: none;\n}\n}','1','2.2.2 数据探查',NULL,NULL,0,'2084109831678504960',2);
