_.__file = "7be8000ee17047806606b43cccbead08.vue"\nreturn __sfc__','.ods-detail .left-panel[data-v-7be8000ee17047806606b43cccbead08] {\n  border-right: 1px solid rgba(5, 5, 5, 0.06);\n  overflow-y: auto;\n}\n.ods-detail .left-header[data-v-7be8000ee17047806606b43cccbead08] {\n  border-bottom: 1px solid rgba(5, 5, 5, 0.06);\n  padding-bottom: 10px;\n  margin-bottom: 10px;\n  margin-right: 14px;\n}\n.ods-detail .left-header h3[data-v-7be8000ee17047806606b43cccbead08] {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n}\n.ods-detail .right-header[data-v-7be8000ee17047806606b43cccbead08] {\n  display: flex;\n  align-items: end;\n  height: 16px;\n  gap: 10px;\n}\n.ods-detail .right-header .header-name[data-v-7be8000ee17047806606b43cccbead08] {\n  line-height: 1;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n}\n.ods-detail .tree-container[data-v-7be8000ee17047806606b43cccbead08] {\n  height: calc(100% - 53px);\n}\n.ods-detail .tree-container .task-tree-container[data-v-7be8000ee17047806606b43cccbead08] {\n  height: 100%;\n}\n.ods-detail .tree-container .task-tree-container[data-v-7be8000ee17047806606b43cccbead08] .u-tree-search {\n  margin-right: 14px;\n}\n.ods-detail .tree-container .task-tree-container[data-v-7be8000ee17047806606b43cccbead08] .el-tree {\n  padding-right: 14px;\n}\n.ods-detail .tree-container .task-tree-container[data-v-7be8000ee17047806606b43cccbead08] .el-tree-node__content {\n  flex: 1;\n  overflow: hidden;\n}\n.tree-node-item[data-v-7be8000ee17047806606b43cccbead08] {\n  display: flex;\n  align-items: center;\n  flex: 1;\n  min-width: 0;\n}\n.tree-node-item .tree-node-more[data-v-7be8000ee17047806606b43cccbead08] {\n  flex-shrink: 0;\n  opacity: 0;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 4px;\n  color: #909399;\n  cursor: pointer;\n  transition: opacity 0.15s, background-color 0.15s;\n}\n[data-v-7be8000ee17047806606b43cccbead08] .el-tree-node__content:hover .tree-node-more {\n  opacity: 1;\n}','1','贴源层 ODS 数据表详情',NULL,NULL,0,'2084109831678504960',6);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2033838744941469696','2033838278811688960','org-manage','<template>\r\n  <div class="card-container flex flex-col px-5 pt-5 pb-2">\r\n    <!-- 操作区 -->\r\n    <div class="mb-5 flex-x-between">\r\n      <!-- 左侧操作按钮 -->\n      <div class="flex">\n        <el-button type="primary" icon="Plus" @click="handleAction(\'新增\')">新增</el-button>\n      </div>\n      <!-- 右侧搜索区域 -->\r\n      <div class="flex gap-2">\r\n        <el-input\n          v-model="searchKeyword"\n          placeholder="请输入机构名称"\n          clearable\n          @clear="handleSearch"\n          @keyup.enter="handleSearch"\n        >\n          <template #suffix>\n            <el-icon class="org-search-icon" role="button" aria-label="搜索机构" title="点击查询" @click="handleSearch"><Search /></el-icon>\n          </template>\n        </el-input>\n      </div>\r\n    </div>\r\n\r\n    <!-- 数据展示区 -->\r\n    <DataTable\r\n      ref="dataTableRef"\r\n      :columns="columns"\n      :data="fetchData"\n      :row-sort="false"\n      :show-page="false"\n      :row-key="\'id\'"\n      :tree-props="{ children: \'children\', hasChildren: \'hasChildren\' }"\n    >\r\n      <!-- 机构名称列：禁用状态显示灰色删除线 -->\r\n      <template #column-name="{ row }">\r\n        <span :class="{ \'is-disabled\': row.status === 1 }">{{ row.name }}</span>\r\n      </template>\r\n    </DataTable>\r\n\r\n    <!-- 排序弹框 -->\r\n    <el-dialog v-model="sortDialogVisible" title="调整排序" width="480px" destroy-on-close>\r\n      <div class="sort-dialog-content">\r\n        <div class="sort-tip mb-3 text-sm text-gray-500">拖拽调整顺序，排序号将自动更新</div>\r\n        <VueDraggable v-model="sortItems" :animation="200" handle=".sort-handle" class="sort-list">\r\n          <div v-for="(item, index) in sortItems" :key="item.id" class="sort-item">\r\n            <Icon class="sort-handle cursor-grab" icon="el-icon-rank" />\r\n            <span class="sort-index">{{ index + 1 }}</span>\r\n            <span class="sort-name">{{ item.name }}</span>\r\n            <span class="sort-current text-gray-400 text-xs ml-auto">\r\n              当前排序: {{ item.sortNum ?? "-" }}\r\n            </span>\r\n          </div>\r\n        </VueDraggable>\r\n      </div>\r\n      <template #footer>\r\n        <el-button @click="sortDialogVisible = false">取消</el-button>\r\n        <el-button type="primary" :disabled="sortSaving" @click="handleSortSave">\r\n          <template #icon><Icon icon="save" /></template>\r\n          保存排序\r\n        </el-button>\r\n      </template>\r\n    </el-dialog>\r\n\r\n    <!-- 机构配置抽屉：页签直接作为抽屉标题，便于在信息与用户间切换 -->\n    <el-drawer v-model="drawerVisible" :size="700">\n      <template #header>\n        <el-tabs v-model="drawerTab" class="drawer-tabs" @tab-change="handleDrawerTabChange">\n          <el-tab-pane label="机构信息" name="info" />\n          <el-tab-pane label="机构用户" name="users" :disabled="!formData.id" />\n        </el-tabs>\n      </template>\n      <div class="px-4">\n        <json-form\n          v-if="drawerTab === \'info\'"\n          ref="formRef"\n          :data="formData"\n          :rules="formRules"\n          :options="{ form: { labelWidth: \'130px\' } }"\r\n        >\r\n          <template #field-parentId="scope">\r\n            <dict-select\r\n              :model-value="\'\' + scope.model.value"\n              type="cascader"\n              :options="parentOrgOptions"\n              :props="{\r\n                checkStrictly: true,\r\n                emitPath: false,\r\n              }"\r\n              clearable\n              popper-class="my-app-org-select"\r\n              @change="(e) => scope.model.callback(e.target.value)"\r\n            />\n          </template>\n        </json-form>\n\n        <div v-else class="org-users-panel">\n          <el-table v-loading="orgUsersLoading" :data="orgUsers" class="w-full">\n            <el-table-column type="index" label="序号" width="70" align="center" />\n            <el-table-column prop="userName" label="用户账号" min-width="130" show-overflow-tooltip />\n            <el-table-column prop="realName" label="姓名" min-width="110" show-overflow-tooltip />\n            <el-table-column prop="phone" label="手机号" min-width="130" />\n            <el-table-column prop="roleNames" label="角色" min-width="150" show-overflow-tooltip>\n              <template #default="{ row }">{{ row.roleNames || "-" }}</template>\n            </el-table-column>\n            <el-table-column prop="status" label="状态" width="90" align="center">\n              <template #default="{ row }">\n                <el-tag :type="row.status === 1 ? \'info\' : \'success\'" size="small">\n                  {{ row.status === 1 ? "禁用" : "启用" }}\n                </el-tag>\n              </template>\n            </el-table-column>\n          </el-table>\n        </div>\n      </div>\n      <template #footer>\n        <el-button icon="close" @click="handleAction(\'关闭抽屉\')">关闭</el-button>\n        <el-button v-if="drawerTab === \'info\'" type="primary" :disabled="isLoading" @click="handleAction(\'保存\')">\n          <template #icon><Icon icon="save" /></template>\n          保存\n        </el-button>\r\n      </template>\r\n    </el-drawer>\r\n  </div>\r\n</template>\r\n\r\n<script lang="ts" setup>\r\nimport { computed, ref, nextTick } from "vue";\nimport { Search } from "@element-plus/icons-vue";\nimport { FormUtils } from "@/utils/form";\nimport { VueDraggable } from "vue-draggable-plus";\r\n\r\n// 接口地址\r\nconst API = {\r\n  LIST: "/sym/org/pageOrg",\r\n  SAVE_OR_UPDATE: "/sym/org/saveOrUpdate",\r\n  SORT: "/sym/org/sort",\n  DETAIL: "/sym/org/detail",\n  DELETE: "/sym/org/delete",\n  USER_PAGE: "/sym/user/page",\n};\n\r\n// 响应式数据\nconst searchKeyword = ref("");\nconst drawerVisible = ref(false);\nconst formData = ref({});\nconst drawerTab = ref<"info" | "users">("info");\nconst orgUsers = ref<any[]>([]);\nconst orgUsersLoading = ref(false);\nconst dataTableRef = ref<any>();\r\nconst formRef = ref<any>();\r\nconst isLoading = ref<boolean>(false);\nconst orgTree = ref<any[]>([]);\n\r\n// 记录树的展开状态\r\nconst expandedRowKeys = ref<Set<string>>(new Set());\r\n\r\n// 排序弹框相关\r\nconst sortDialogVisible = ref(false);\r\nconst sortItems = ref<any[]>([]);\r\nconst sortSaving = ref(false);\r\nconst sortParentId = ref<string>("");\r\n\r\n// 保存当前展开的行\r\nconst saveExpandState = () => {\r\n  const elTable = dataTableRef.value?.$table;\r\n  if (!elTable) return;\r\n\r\n  // 获取当前展开的行\r\n  const expandedRows = elTable.getExpandRows?.() || [];\r\n  expandedRowKeys.value = new Set(expandedRows.map((row: any) => row.id));\r\n  console.log("保存展开状态:", expandedRowKeys.value.size, "个节点");\r\n};\r\n\r\n// 恢复展开的行\r\nconst restoreExpandState = () => {\r\n  const elTable = dataTableRef.value?.$table;\r\n  if (!elTable || expandedRowKeys.value.size === 0) return;\r\n\r\n  // 递归查找并展开节点\r\n  const expandNodes = (data: any[]) => {\r\n    data.forEach((row) => {\r\n      if (expandedRowKeys.value.has(row.id) && row.children?.length) {\r\n        elTable.toggleRowExpansion(row, true);\r\n      }\r\n      if (row.children?.length) {\r\n        expandNodes(row.children);\r\n      }\r\n    });\r\n  };\r\n\r\n  // 延迟执行，确保数据已渲染\r\n  nextTick(() => {\r\n    expandNodes(dataTableRef.value?.tableData || []);\r\n    console.log("恢复展开状态:", expandedRowKeys.value.size, "个节点");\r\n  });\r\n};\r\n\r\n// 二次刷新：保存状态 → 刷新 → 恢复状态\r\nconst refreshWithState = async () => {\r\n  saveExpandState();\r\n  await dataTableRef.value?.refresh();\r\n  restoreExpandState();\r\n};\r\n\r\n// 加载当前机构直属用户；接口已按当前租户过滤，orgId 只用于查看该机构归属。\nconst loadOrgUsers = async () => {\n  if (!formData.value?.id) {\n    orgUsers.value = [];\n    return;\n  }\n  try {\n    orgUsersLoading.value = true;\n    const result = await $common.post(API.USER_PAGE, {\n      pageNum: 1,\n      pageSize: 200,\n      orgId: formData.value.id,\n    });\n    orgUsers.value = result?.list || [];\n  } catch (error) {\n    console.error("获取机构用户失败:", error);\n    $message.error("获取机构用户失败");\n    orgUsers.value = [];\n  } finally {\n    orgUsersLoading.value = false;\n  }\n};\n\nconst handleDrawerTabChange = (tab: string | number) => {\n  if (tab === "users") loadOrgUsers();\n};\n\r\n// 表格列配置\r\nconst columns = [\r\n  {\r\n    prop: "name",\r\n    label: "机构名称",\r\n  },\r\n  {\r\n    prop: "orgPath",\r\n    label: "机构全路径",\r\n  },\r\n  {\r\n    prop: "nature",\r\n    label: "机构类型",\r\n    options: "orgType",\r\n  },\r\n  {\r\n    prop: "updateTime",\r\n    label: "更新时间",\r\n  },\r\n  {\r\n    prop: "operation",\r\n    label: "操作",\r\n    type: "buttons",\r\n    buttons: [\r\n      {\r\n        label: "详情",\r\n        type: "primary",\r\n        link: true,\r\n        click: (row: any) => handleAction("详情", row),\r\n      },\r\n      {\r\n        label: "新增子机构",\r\n        type: "primary",\r\n        link: true,\r\n        click: (row: any) => handleAction("新增", row),\r\n      },\r\n      {\r\n        dropdown: true,\r\n        label: "更多",\r\n        type: "primary",\r\n        link: true,\r\n        icon: "more_horiz",\r\n        dropdownItems: [\r\n          {\r\n            label: "排序",\r\n            click: (row: any) => handleAction("排序", row),\r\n          },\r\n          {\r\n            label: "禁用",\r\n            if: (row: any) => !row.status,\r\n            click: (row: any) => handleAction("禁用", row),\r\n          },\r\n          {\r\n            label: "启用",\r\n            if: (row: any) => row.status == 1,\r\n            click: (row: any) => handleAction("启用", row),\r\n          },\r\n          {\r\n            label: "删除",\r\n            if: (row: any) => row.id !== "ROOT",\r\n            color: "#f56c6c",\r\n            click: (row: any) => handleAction("删除", row),\r\n          },\r\n        ],\r\n      },\r\n    ],\r\n  },\r\n];\r\n\r\n// 表单规则\r\nconst formRules = ref([]);\r\nformRules.value = FormUtils.fixJson([\r\n  {\r\n    type: "u-title",\r\n    title: "基本信息",\r\n  },\r\n  {\r\n    type: "form-text",\r\n    field: "id",\r\n    hidden: true,\r\n  },\r\n  {\r\n    field: "name",\r\n    title: "机构名称",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入机构名称",\r\n      maxlength: 200,\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    field: "parentId",\r\n    title: "上级机构",\r\n    type: "cascader",\r\n    props: {\r\n      placeholder: "请选择上级机构",\r\n      options: [],\r\n      props: {\r\n        checkStrictly: true,\r\n        emitPath: false,\r\n      },\r\n      popperClass: "my-app-org-select",\r\n      placement: "bottom",\r\n    },\r\n    $required: true,\r\n  },\r\n  // {\r\n  //   field: "shortName",\r\n  //   title: "机构简称",\r\n  //   type: "input",\r\n  //   props: {\r\n  //     placeholder: "请输入机构简称",\r\n  //     maxlength: 200,\r\n  //   },\r\n  // },\r\n  {\r\n    field: "nature",\r\n    title: "机构类型",\r\n    type: "dict-select",\r\n    props: {\r\n      placeholder: "请选择机构类型",\r\n      options: "orgType",\r\n    },\r\n    $required: true,\r\n  },\r\n  {\r\n    field: "serialNumber",\r\n    title: "序列号",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "自动生成序列号",\r\n      maxlength: 100,\r\n      disabled: true,\r\n    },\r\n  },\r\n  {\r\n    field: "standard",\r\n    title: "机构级别",\r\n    type: "dict-select",\r\n    props: {\r\n      placeholder: "请输入机构级别",\r\n      maxlength: 64,\r\n      options: "orgLevel",\r\n    },\r\n  },\r\n  {\r\n    field: "creditCode",\r\n    title: "统一社会信用代码",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入统一社会信用代码",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "originIds",\r\n    title: "外部ID",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入外部ID",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "sortNum",\r\n    title: "排序号",\r\n    type: "number",\r\n    props: {\r\n      placeholder: "请输入排序号",\r\n      min: 0,\r\n    },\r\n    style: "width: 200px",\r\n  },\r\n  // {\r\n  //   field: "status",\r\n  //   title: "状态",\r\n  //   type: "radio",\r\n  //   value: 1,\r\n  //   options: [\r\n  //     { value: 0, label: "启用" },\r\n  //     { value: 1, label: "禁用" },\r\n  //   ],\r\n  // },\r\n  /*{\r\n    type: "u-title",\r\n    title: "扩展信息",\r\n  },\r\n  {\r\n    field: "deptType",\r\n    title: "部门类型",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入部门类型",\r\n      maxlength: 64,\r\n    },\r\n  },\r\n  {\r\n    field: "deptCode",\r\n    title: "部门编码",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入部门编码",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "nationalCode",\r\n    title: "国家部门编码",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入国家部门编码",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "nationalName",\r\n    title: "国家部门名称",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入国家部门名称",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "regionCode",\r\n    title: "区域编码",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入区域编码",\r\n      maxlength: 100,\r\n    },\r\n  },\r\n  {\r\n    field: "nodeType",\r\n    title: "节点类型",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入节点类型",\r\n      maxlength: 16,\r\n    },\r\n  },\r\n  {\r\n    field: "label",\r\n    title: "标签",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入标签",\r\n      maxlength: 1000,\r\n    },\r\n  },\r\n  {\r\n    field: "leaderOrgId",\r\n    title: "上级领导机构",\r\n    type: "input",\r\n    props: {\r\n      placeholder: "请输入上级领导机构ID",\r\n      maxlength: 50,\r\n    },\r\n  },\r\n  {\r\n    field: "description",\r\n    title: "详细描述",\r\n    type: "textarea",\r\n    props: {\r\n      placeholder: "请输入详细描述",\r\n      maxlength: 1024,\r\n      rows: 3,\r\n    },\r\n  },*/\r\n]);\r\n\r\n// 扁平数据转树状结构\r\nconst buildTree = (flatList: any[], rootParentId = "ROOT") => {\n  const nodeMap = new Map<string, any>();\r\n  const tree: any[] = [];\r\n\r\n  // 第一次遍历：建立节点映射\r\n  flatList.forEach((item) => {\r\n    nodeMap.set(item.id, { ...item, children: [], value: item.id, label: item.name });\r\n  });\r\n\r\n  // 第二次遍历：构建树\r\n  flatList.forEach((item) => {\r\n    const node = nodeMap.get(item.id);\r\n    if (item.parentId === rootParentId || !nodeMap.has(item.parentId)) {\r\n      // 根节点\r\n      tree.push(node);\r\n    } else {\r\n      // 子节点，添加到父节点的 children\r\n      const parent = nodeMap.get(item.parentId);\r\n      if (parent) {\r\n        parent.children.push(node);\r\n      }\r\n    }\r\n  });\r\n\r\n  // “全部机构”是列表接口返回的虚拟根节点，不应作为可维护机构展示。\n  // 去掉该节点并提升其子机构，保留原有层级和展开行为。\n  const virtualRoot = tree.find((item) => item.name === "全部机构");\n  return virtualRoot?.children?.length ? virtualRoot.children : tree.filter((item) => item.name !== "全部机构");\n};\n\n// 编辑父机构时排除当前节点及其整棵子树，前端避免产生循环；服务端仍会再次校验。\nconst parentOrgOptions = computed(() => {\n  const currentId = (formData.value as any)?.id;\n  const filterTree = (nodes: any[]): any[] =>\n    (nodes || [])\n      .filter((node) => node.id !== currentId)\n      .map((node) => ({ ...node, children: filterTree(node.children) }));\n  return filterTree(orgTree.value);\n});\n\n// 机构详情可能由搜索结果打开，父级候选必须始终使用完整组织树。\nconst loadOrgTreeOptions = async () => {\n  const result = await fetchOrgList();\n  orgTree.value = buildTree(result?.list || []);\n};\n\r\n// 处理搜索\r\nconst handleSearch = () => {\r\n  refreshWithState();\r\n};\r\n\r\n// 统一操作处理方法\r\nconst handleAction = (type: string, row?: any) => {\r\n  switch (type) {\r\n    case "刷新":\r\n      refreshWithState();\r\n      break;\r\n    case "搜索":\r\n      handleSearch();\r\n      break;\r\n    case "新增":\n      formRef.value?.resetFields();\n      formData.value = { parentId: row?.id || $user.orgRootId };\n      drawerTab.value = "info";\n      orgUsers.value = [];\n      drawerVisible.value = true;\n      loadOrgTreeOptions().catch((error) => console.error("加载机构树失败:", error));\n      break;\n    case "详情":\n      fetchOrgDetail(row.id);\n      break;\r\n    case "排序":\r\n      handleOpenSortDialog(row);\r\n      break;\r\n    case "禁用":\r\n      $dialog\r\n        .confirm(`确定要禁用机构【${row?.name}】吗?`, "提示", {\r\n          confirmButtonText: "确定",\r\n          cancelButtonText: "取消",\r\n          type: "warning",\r\n        })\r\n        .then(async () => {\r\n          await $common.post(API.SAVE_OR_UPDATE, { id: row.id, status: 1 });\r\n          $message.success("禁用成功");\r\n          refreshWithState();\r\n        });\r\n      break;\r\n    case "启用":\r\n      $dialog\r\n        .confirm(`确定要启用机构【${row?.name}】吗?`, "提示", {\r\n          confirmButtonText: "确定",\r\n          cancelButtonText: "取消",\r\n          type: "warning",\r\n        })\r\n        .then(async () => {\r\n          await $common.post(API.SAVE_OR_UPDATE, { id: row.id, status: 0 });\r\n          $message.success("启用成功");\r\n          refreshWithState();\r\n        });\r\n      break;\r\n    case "删除":\r\n      $dialog\r\n        .confirm("确认要删除该机构及其全部子机构吗？删除后不可恢复。", "提示", {\r\n          confirmButtonText: "确定",\r\n          cancelButtonText: "取消",\r\n          type: "warning",\r\n        })\r\n        .then(() => {\r\n          handleDelete(row.id);\r\n        })\r\n        .catch(() => {});\r\n      break;\r\n    case "关闭抽屉":\n      drawerVisible.value = false;\n      drawerTab.value = "info";\n      orgUsers.value = [];\n      break;\r\n    case "保存":\r\n      handleSave();\r\n      break;\r\n    default:\r\n      console.warn("未处理的操作类型:", type);\r\n  }\r\n};\r\n\r\n// 获取机构详情\r\nconst fetchOrgDetail = async (id: string) => {\n  try {\n    const [res] = await Promise.all([\n      $common.post(API.DETAIL, { id }),\n      loadOrgTreeOptions(),\n    ]);\n    formData.value = res || {};\n    drawerTab.value = "info";\n    orgUsers.value = [];\n    drawerVisible.value = true;\n  } catch (error) {\r\n    console.error("获取机构详情失败:", error);\r\n    $message.error("获取机构详情失败");\r\n  }\r\n};\r\n\r\n// 处理保存\r\nconst handleSave = async () => {\r\n  try {\r\n    await formRef.value?.validate();\r\n    const data = await formRef.value?.getSaveData();\r\n    isLoading.value = true;\r\n\r\n    await $common.post(API.SAVE_OR_UPDATE, data);\r\n    $message.success("保存成功");\r\n    drawerVisible.value = false;\r\n    refreshWithState();\r\n  } catch (error) {\r\n    console.error("保存失败:", error);\r\n    $message.error("保存失败，请检查表单数据");\r\n  } finally {\r\n    isLoading.value = false;\r\n  }\r\n};\r\n\r\n// 处理删除\r\nconst handleDelete = async (id: string) => {\r\n  try {\r\n    await $common.post(API.DELETE, { ids: [id] });\r\n    $message.success("删除成功");\r\n    refreshWithState();\r\n  } catch (error) {\r\n    console.error("删除失败:", error);\r\n    $message.error("删除失败");\r\n  }\r\n};\r\n\r\n// 打开排序弹框：查找当前节点的所有同级节点\r\nconst handleOpenSortDialog = (row: any) => {\r\n  const parentId = row.parentId || "ROOT";\r\n  sortParentId.value = parentId;\r\n\r\n  // 从 orgTree 中查找同级节点\r\n  const findSiblings = (nodes: any[], targetParentId: string): any[] => {\r\n    // 如果是根级，直接返回顶层节点\r\n    if (targetParentId === "ROOT") {\r\n      return nodes.map((n) => ({ id: n.id, name: n.name, sortNum: n.sortNum }));\r\n    }\r\n    // 在子节点中查找\r\n    for (const node of nodes) {\r\n      if (node.id === targetParentId) {\r\n        return (node.children || []).map((n: any) => ({\r\n          id: n.id,\r\n          name: n.name,\r\n          sortNum: n.sortNum,\r\n        }));\r\n      }\r\n      if (node.children?.length) {\r\n        const result = findSiblings(node.children, targetParentId);\r\n        if (result.length) return result;\r\n      }\r\n    }\r\n    return [];\r\n  };\r\n\r\n  sortItems.value = findSiblings(orgTree.value, parentId);\r\n  if (sortItems.value.length === 0) {\r\n    $message.warning("未找到同级节点");\r\n    return;\r\n  }\r\n  sortDialogVisible.value = true;\r\n};\r\n\r\n// 保存排序\r\nconst handleSortSave = async () => {\r\n  try {\r\n    sortSaving.value = true;\r\n    // 逐个调用 saveOrUpdate 更新排序号\r\n    await $common.post(API.SORT, { ids: sortItems.value.map((item) => item.id) });\r\n\r\n    $message.success("排序保存成功");\r\n    sortDialogVisible.value = false;\r\n    refreshWithState();\r\n  } catch (error) {\r\n    console.error("排序保存失败:", error);\r\n    $message.error("排序保存失败");\r\n  } finally {\r\n    sortSaving.value = false;\r\n  }\r\n};\r\n\r\n// 获取组织机构列表\r\nconst fetchOrgList = async (params?: { name?: string }) => {\r\n  return $common.get(API.LIST, params || {});\r\n};\r\n\r\n// 获取数据函数（供 DataTable 调用）\r\nconst fetchData = async (params: { pageNo: number; pageSize: number }) => {\r\n  // 构建请求参数\r\n  const queryParams: any = {};\r\n  if (searchKeyword.value) {\r\n    queryParams.name = searchKeyword.value;\r\n  }\r\n\r\n  // 调用接口获取扁平数据\r\n  const res = await fetchOrgList(queryParams);\r\n  const flatList = res?.list || [];\r\n  // 转换为树状结构\r\n  const treeData = buildTree(flatList);\r\n  if (!searchKeyword.value) {\r\n    orgTree.value = treeData;\r\n    if (treeData.length == 1) {\r\n      nextTick(() => {\r\n        nextTick(() => {\r\n          expandedRowKeys.value.add(treeData[0].id);\r\n          restoreExpandState();\r\n        });\r\n      });\r\n    }\r\n  }\r\n\r\n  // 处理搜索过滤（接口未支持模糊搜索时，前端过滤）\r\n  let filteredData = treeData;\r\n  if (searchKeyword.value) {\r\n    const keyword = searchKeyword.value.toLowerCase();\r\n    const filterTree = (data: any[]) => {\r\n      return data.filter((item) => {\r\n        const matches = item.name?.toLowerCase().includes(keyword);\r\n        if (item.children && item.children.length > 0) {\r\n          item.children = filterTree(item.children);\r\n          return matches || item.children.length > 0;\r\n        }\r\n        return matches;\r\n      });\r\n    };\r\n    filteredData = filterTree(treeData);\r\n  }\r\n\r\n  return {\r\n    list: filteredData,\r\n    total: filteredData.length,\r\n  };\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.is-disabled {\n  color: var(--el-text-color-disabled);\n  text-decoration: line-through;\n}\n\n.org-search-icon {\n  color: #1677ff;\n  cursor: pointer;\n  font-size: 17px;\n\n  &:hover {\n    color: #409eff;\n  }\n}\n\n.drawer-tabs {\n  width: 100%;\n  height: 54px;\n\n  :deep(.el-tabs__header) {\n    height: 54px;\n    margin: 0;\n  }\n\n  :deep(.el-tabs__nav-wrap) {\n    height: 54px;\n  }\n\n  :deep(.el-tabs__item) {\n    height: 54px;\n    line-height: 54px;\n  }\n\n  :deep(.el-tabs__active-bar) {\n    bottom: -1px;\n    height: 2px;\n  }\n\n  :deep(.el-tabs__nav-wrap::after) {\n    display: none;\n  }\n\n  :deep(.el-tabs__content) {\n    display: none;\n  }\n}\n\n:deep(.el-drawer__header) {\n  height: 54px;\n  min-height: 54px;\n  margin-bottom: 0;\n  padding: 0 20px;\n  border-bottom: 1px solid var(--el-border-color-lighter);\n  box-sizing: border-box;\n}\n\n.org-users-panel {\n  min-height: 260px;\n}\n\n.sort-list {\n  max-height: 400px;\r\n  overflow-y: auto;\r\n}\r\n\r\n.sort-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  padding: 10px 12px;\r\n  border: 1px solid var(--el-border-color-lighter);\r\n  border-radius: 6px;\r\n  margin-bottom: 8px;\r\n  background: var(--el-bg-color);\r\n  transition: box-shadow 0.2s;\r\n\r\n  &:hover {\r\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);\r\n  }\r\n\r\n  .sort-handle {\r\n    color: var(--el-text-color-placeholder);\r\n    font-size: 18px;\r\n  }\r\n\r\n  .sort-index {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: 24px;\r\n    height: 24px;\r\n    border-radius: 50%;\r\n    background: var(--el-color-primary-light-9);\r\n    color: var(--el-color-primary);\r\n    font-size: 12px;\r\n    font-weight: 600;\r\n  }\r\n\r\n  .sort-name {\r\n    flex: 1;\r\n    font-size: 14px;\r\n    color: var(--el-text-color-regular);\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _withKeys = ___magic__import__(\'vue\', \'withKeys\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _resolveDirective = ___magic__import__(\'vue\', \'resolveDirective\');\r\nconst _withDirectives = ___magic__import__(\'vue\', \'withDirectives\');\nconst _hoisted_1 = {\n  class: "card-container flex flex-col px-5 pt-5 pb-2"\n};\nconst _hoisted_2 = {\n  class: "mb-5 flex-x-between"\n};\nconst _hoisted_3 = {\n  class: "flex"\n};\nconst _hoisted_4 = {\n  class: "flex gap-2"\n};\nconst _hoisted_5 = {\n  class: "sort-dialog-content"\n};\nconst _hoisted_6 = {\n  class: "sort-index"\n};\nconst _hoisted_7 = {\n  class: "sort-name"\n};\nconst _hoisted_8 = {\n  class: "sort-current text-gray-400 text-xs ml-auto"\n};\nconst _hoisted_9 = {\n  class: "px-4"\n};\nconst _hoisted_10 = {\n  key: 1,\n  class: "org-users-panel"\n};\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\nconst Search = ___magic__import__(\'@element-plus/icons-vue\', \'Search\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst VueDraggable = ___magic__import__(\'vue-draggable-plus\', \'VueDraggable\');\n\n// 接口地址\n\nconst __sfc__ = _defineComponent({\n  __name: \'64183123b0be4c262238978ccf1bff30\',\n  setup(__props) {\n    const API = {\n      LIST: "/sym/org/pageOrg",\n      SAVE_OR_UPDATE: "/sym/org/saveOrUpdate",\n      SORT: "/sym/org/sort",\n      DETAIL: "/sym/org/detail",\n      DELETE: "/sym/org/delete",\n      USER_PAGE: "/sym/user/page"\n    };\n\n    // 响应式数据\n    const searchKeyword = ref("");\n    const drawerVisible = ref(false);\n    const formData = ref({});\n    const drawerTab = ref("info");\n    const orgUsers = ref([]);\n    const orgUsersLoading = ref(false);\n    const dataTableRef = ref();\n    const formRef = ref();\n    const isLoading = ref(false);\n    const orgTree = ref([]);\n\n    // 记录树的展开状态\n    const expandedRowKeys = ref(new Set());\n\n    // 排序弹框相关\n    const sortDialogVisible = ref(false);\n    const sortItems = ref([]);\n    const sortSaving = ref(false);\n    const sortParentId = ref("");\n\n    // 保存当前展开的行\n    const saveExpandState = () => {\n      const elTable = dataTableRef.value?.$table;\n      if (!elTable) return;\n\n      // 获取当前展开的行\n      const expandedRows = elTable.getExpandRows?.() || [];\n      expandedRowKeys.value = new Set(expandedRows.map(row => row.id));\n      console.log("保存展开状态:", expandedRowKeys.value.size, "个节点");\n    };\n\n    // 恢复展开的行\n    const restoreExpandState = () => {\n      const elTable = dataTableRef.value?.$table;\n      if (!elTable || expandedRowKeys.value.size === 0) return;\n\n      // 递归查找并展开节点\n      const expandNodes = data => {\n        data.forEach(row => {\n          if (expandedRowKeys.value.has(row.id) && row.children?.length) {\n            elTable.toggleRowExpansion(row, true);\n          }\n          if (row.children?.length) {\n            expandNodes(row.children);\n          }\n        });\n      };\n\n      // 延迟执行，确保数据已渲染\n      nextTick(() => {\n        expandNodes(dataTableRef.value?.tableData || []);\n        console.log("恢复展开状态:", expandedRowKeys.value.size, "个节点");\n      });\n    };\n\n    // 二次刷新：保存状态 → 刷新 → 恢复状态\n    const refreshWithState = async () => {\n      saveExpandState();\n      await dataTableRef.value?.refresh();\n      restoreExpandState();\n    };\n\n    // 加载当前机构直属用户；接口已按当前租户过滤，orgId 只用于查看该机构归属。\n    const loadOrgUsers = async () => {\n      if (!formData.value?.id) {\n        orgUsers.value = [];\n        return;\n      }\n      try {\n        orgUsersLoading.value = true;\n        const result = await $common.post(API.USER_PAGE, {\n          pageNum: 1,\n          pageSize: 200,\n          orgId: formData.value.id\n        });\n        orgUsers.value = result?.list || [];\n      } catch (error) {\n        console.error("获取机构用户失败:", error);\n        $message.error("获取机构用户失败");\n        orgUsers.value = [];\n      } finally {\n        orgUsersLoading.value = false;\n      }\n    };\n    const handleDrawerTabChange = tab => {\n      if (tab === "users") loadOrgUsers();\n    };\n\n    // 表格列配置\n    const columns = [{\n      prop: "name",\n      label: "机构名称"\n    }, {\n      prop: "orgPath",\n      label: "机构全路径"\n    }, {\n      prop: "nature",\n      label: "机构类型",\n      options: "orgType"\n    }, {\n      prop: "updateTime",\n      label: "更新时间"\n    }, {\n      prop: "operation",\n      label: "操作",\n      type: "buttons",\n      buttons: [{\n        label: "详情",\n        type: "primary",\n        link: true,\n        click: row => handleAction("详情", row)\n      }, {\n        label: "新增子机构",\n        type: "primary",\n        link: true,\n        click: row => handleAction("新增", row)\n      }, {\n        dropdown: true,\n        label: "更多",\n        type: "primary",\n        link: true,\n        icon: "more_horiz",\n        dropdownItems: [{\n          label: "排序",\n          click: row => handleAction("排序", row)\n        }, {\n          label: "禁用",\n          if: row => !row.status,\n          click: row => handleAction("禁用", row)\n        }, {\n          label: "启用",\n          if: row => row.status == 1,\n          click: row => handleAction("启用", row)\n        }, {\n          label: "删除",\n          if: row => row.id !== "ROOT",\n          color: "#f56c6c",\n          click: row => handleAction("删除", row)\n        }]\n      }]\n    }];\n\n    // 表单规则\n    const formRules = ref([]);\n    formRules.value = FormUtils.fixJson([{\n      type: "u-title",\n      title: "基本信息"\n    }, {\n      type: "form-text",\n      field: "id",\n      hidden: true\n    }, {\n      field: "name",\n      title: "机构名称",\n      type: "input",\n      props: {\n        placeholder: "请输入机构名称",\n        maxlength: 200\n      },\n      $required: true\n    }, {\n      field: "parentId",\n      title: "上级机构",\n      type: "cascader",\n      props: {\n        placeholder: "请选择上级机构",\n        options: [],\n        props: {\n          checkStrictly: true,\n          emitPath: false\n        },\n        popperClass: "my-app-org-select",\n        placement: "bottom"\n      },\n      $required: true\n    },\n    // {\n    //   field: "shortName",\n    //   title: "机构简称",\n    //   type: "input",\n    //   props: {\n    //     placeholder: "请输入机构简称",\n    //     maxlength: 200,\n    //   },\n    // },\n    {\n      field: "nature",\n      title: "机构类型",\n      type: "dict-select",\n      props: {\n        placeholder: "请选择机构类型",\n        options: "orgType"\n      },\n      $required: true\n    }, {\n      field: "serialNumber",\n      title: "序列号",\n      type: "input",\n      props: {\n        placeholder: "自动生成序列号",\n        maxlength: 100,\n        disabled: true\n      }\n    }, {\n      field: "standard",\n      title: "机构级别",\n      type: "dict-select",\n      props: {\n        placeholder: "请输入机构级别",\n        maxlength: 64,\n        options: "orgLevel"\n      }\n    }, {\n      field: "creditCode",\n      title: "统一社会信用代码",\n      type: "input",\n      props: {\n        placeholder: "请输入统一社会信用代码",\n        maxlength: 100\n      }\n    }, {\n      field: "originIds",\n      title: "外部ID",\n      type: "input",\n      props: {\n        placeholder: "请输入外部ID",\n        maxlength: 100\n      }\n    }, {\n      field: "sortNum",\n      title: "排序号",\n      type: "number",\n      props: {\n        placeholder: "请输入排序号",\n        min: 0\n      },\n      style: "width: 200px"\n    }\n    // {\n    //   field: "status",\n    //   title: "状态",\n    //   type: "radio",\n    //   value: 1,\n    //   options: [\n    //     { value: 0, label: "启用" },\n    //     { value: 1, label: "禁用" },\n    //   ],\n    // },\n    /*{\r\n      type: "u-title",\r\n      title: "扩展信息",\r\n    },\r\n    {\r\n      field: "deptType",\r\n      title: "部门类型",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入部门类型",\r\n        maxlength: 64,\r\n      },\r\n    },\r\n    {\r\n      field: "deptCode",\r\n      title: "部门编码",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入部门编码",\r\n        maxlength: 100,\r\n      },\r\n    },\r\n    {\r\n      field: "nationalCode",\r\n      title: "国家部门编码",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入国家部门编码",\r\n        maxlength: 100,\r\n      },\r\n    },\r\n    {\r\n      field: "nationalName",\r\n      title: "国家部门名称",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入国家部门名称",\r\n        maxlength: 100,\r\n      },\r\n    },\r\n    {\r\n      field: "regionCode",\r\n      title: "区域编码",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入区域编码",\r\n        maxlength: 100,\r\n      },\r\n    },\r\n    {\r\n      field: "nodeType",\r\n      title: "节点类型",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入节点类型",\r\n        maxlength: 16,\r\n      },\r\n    },\r\n    {\r\n      field: "label",\r\n      title: "标签",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入标签",\r\n        maxlength: 1000,\r\n      },\r\n    },\r\n    {\r\n      field: "leaderOrgId",\r\n      title: "上级领导机构",\r\n      type: "input",\r\n      props: {\r\n        placeholder: "请输入上级领导机构ID",\r\n        maxlength: 50,\r\n      },\r\n    },\r\n    {\r\n      field: "description",\r\n      title: "详细描述",\r\n      type: "textarea",\r\n      props: {\r\n        placeholder: "请输入详细描述",\r\n        maxlength: 1024,\r\n        rows: 3,\r\n      },\r\n    },*/]);\n\n    // 扁平数据转树状结构\n    const buildTree = (flatList, rootParentId = "ROOT") => {\n      const nodeMap = new Map();\n      const tree = [];\n\n      // 第一次遍历：建立节点映射\n      flatList.forEach(item => {\n        nodeMap.set(item.id, {\n          ...item,\n          children: [],\n          value: item.id,\n          label: item.name\n        });\n      });\n\n      // 第二次遍历：构建树\n      flatList.forEach(item => {\n        const node = nodeMap.get(item.id);\n        if (item.parentId === rootParentId || !nodeMap.has(item.parentId)) {\n          // 根节点\n          tree.push(node);\n        } else {\n          // 子节点，添加到父节点的 children\n          const parent = nodeMap.get(item.parentId);\n          if (parent) {\n            parent.children.push(node);\n          }\n        }\n      });\n\n      // “全部机构”是列表接口返回的虚拟根节点，不应作为可维护机构展示。\n      // 去掉该节点并提升其子机构，保留原有层级和展开行为。\n      const virtualRoot = tree.find(item => item.name === "全部机构");\n      return virtualRoot?.children?.length ? virtualRoot.children : tree.filter(item => item.name !== "全部机构");\n    };\n\n    // 编辑父机构时排除当前节点及其整棵子树，前端避免产生循环；服务端仍会再次校验。\n    const parentOrgOptions = computed(() => {\n      const currentId = formData.value?.id;\n      const filterTree = nodes => (nodes || []).filter(node => node.id !== currentId).map(node => ({\n        ...node,\n        children: filterTree(node.children)\n      }));\n      return filterTree(orgTree.value);\n    });\n\n    // 机构详情可能由搜索结果打开，父级候选必须始终使用完整组织树。\n    const loadOrgTreeOptions = async () => {\n      const result = await fetchOrgList();\n      orgTree.value = buildTree(result?.list || []);\n    };\n\n    // 处理搜索\n    const handleSearch = () => {\n      refreshWithState();\n    };\n\n    // 统一操作处理方法\n    const handleAction = (type, row) => {\n      switch (type) {\n        case "刷新":\n          refreshWithState();\n          break;\n        case "搜索":\n          handleSearch();\n          break;\n        case "新增":\n          formRef.value?.resetFields();\n          formData.value = {\n            parentId: row?.id || $user.orgRootId\n          };\n          drawerTab.value = "info";\n          orgUsers.value = [];\n          drawerVisible.value = true;\n          loadOrgTreeOptions().catch(error => console.error("加载机构树失败:", error));\n          break;\n        case "详情":\n          fetchOrgDetail(row.id);\n          break;\n        case "排序":\n          handleOpenSortDialog(row);\n          break;\n        case "禁用":\n          $dialog.confirm(`确定要禁用机构【${row?.name}】吗?`, "提示", {\n            confirmButtonText: "确定",\n            cancelButtonText: "取消",\n            type: "warning"\n          }).then(async () => {\n            await $common.post(API.SAVE_OR_UPDATE, {\n              id: row.id,\n              status: 1\n            });\n            $message.success("禁用成功");\n            refreshWithState();\n          });\n          break;\n        case "启用":\n          $dialog.confirm(`确定要启用机构【${row?.name}】吗?`, "提示", {\n            confirmButtonText: "确定",\n            cancelButtonText: "取消",\n            type: "warning"\n          }).then(async () => {\n            await $common.post(API.SAVE_OR_UPDATE, {\n              id: row.id,\n              status: 0\n            });\n            $message.success("启用成功");\n            refreshWithState();\n          });\n          break;\n        case "删除":\n          $dialog.confirm("确认要删除该机构及其全部子机构吗？删除后不可恢复。", "提示", {\n            confirmButtonText: "确定",\n            cancelButtonText: "取消",\n           