INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2009565859053899776','2009529477967187968','preview-panel','<!-- 数据预览相关面板 -->\r\n<template>\r\n  <div class="data-preview-panel">\r\n    <el-tabs :model-value="activeTab" @update:model-value="handleTabChange">\r\n      <el-tab-pane label="数据预览" name="data-preview">\r\n        <data-table\r\n          v-if="previewData.length > 0"\r\n          :columns="previewColumns"\r\n          :data="previewData"\r\n          :show-page="false"\r\n          class="data-preview-table"\r\n        />\r\n        <div v-else class="empty-preview">\r\n          <el-empty description="执行任务后的数据预览" />\r\n        </div>\r\n      </el-tab-pane>\r\n\r\n      <el-tab-pane label="节点信息" name="node-info">\r\n        <div v-if="selectedNode" class="node-info-container">\r\n          <!-- <el-descriptions :column="1" border>\r\n            <el-descriptions-item label="节点ID">{{ selectedNode.id }}</el-descriptions-item>\r\n            <el-descriptions-item label="节点名称">\r\n              {{ selectedNode.name }}\r\n            </el-descriptions-item>\r\n            <el-descriptions-item label="节点类型">\r\n              {{ selectedNode.type }}\r\n            </el-descriptions-item>\r\n            <el-descriptions-item label="创建时间">\r\n              {{ selectedNode.createTime }}\r\n            </el-descriptions-item>\r\n          </el-descriptions> -->\r\n        </div>\r\n        <div v-else class="empty-node-info">\r\n          <el-empty description="点击画布节点查看信息" />\r\n        </div>\r\n      </el-tab-pane>\r\n\r\n      <el-tab-pane label="节点配置" name="node-config">\r\n        <div v-if="selectedNode" class="node-config-container">\r\n          <!-- <el-form label-width="100px">\r\n            <el-form-item label="节点名称" required>\r\n              <el-input v-model="localNode.name" @input="handleNodeChange" placeholder="请输入节点名称" />\r\n            </el-form-item>\r\n            <el-form-item label="节点描述">\r\n              <el-input\r\n                v-model="localNode.description"\r\n                type="textarea"\r\n                :rows="3"\r\n                @input="handleNodeChange"\r\n                placeholder="请输入节点描述"\r\n              />\r\n            </el-form-item>\r\n            <el-form-item label="配置参数">\r\n              <el-input\r\n                v-model="localNode.config"\r\n                type="textarea"\r\n                :rows="5"\r\n                @input="handleNodeChange"\r\n                placeholder="请输入配置参数"\r\n              />\r\n            </el-form-item>\r\n          </el-form> -->\r\n        </div>\r\n        <div v-else class="empty-node-config">\r\n          <el-empty description="点击画布节点配置信息" />\r\n        </div>\r\n      </el-tab-pane>\r\n    </el-tabs>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { defineProps, defineEmits, ref, watch } from "vue";\r\n\r\n// 定义组件属性\r\ninterface SelectedNode {\r\n  id: string;\r\n  name: string;\r\n  type: string;\r\n  createTime: string;\r\n  description?: string;\r\n  config?: string;\r\n}\r\n\r\nconst props = defineProps<{\r\n  activeTab: string;\r\n  selectedNode: SelectedNode | null;\r\n}>();\r\n\r\nconst previewData = ref([\r\n  {\r\n    id: "CCTV-01",\r\n    field1: "CCTV-1 综合频道",\r\n    field2: "《新闻联播》",\r\n    field3: "4.8",\r\n    field4: "18.5",\r\n    field5: "12568000",\r\n    field6: "2025-10-01 19:00:00",\r\n  },\r\n  {\r\n    id: "HUNAN-01",\r\n    field1: "湖南卫视",\r\n    field2: "《快乐大本营》",\r\n    field3: "2.3",\r\n    field4: "9.2",\r\n    field5: "6854000",\r\n    field6: "2025-10-01 20:20:00",\r\n  },\r\n  {\r\n    id: "SHANGHAI-01",\r\n    field1: "东方卫视",\r\n    field2: "《极限挑战》",\r\n    field3: "1.9",\r\n    field4: "7.8",\r\n    field5: "5245000",\r\n    field6: "2025-10-01 21:00:00",\r\n  },\r\n  {\r\n    id: "ZHEJIANG-01",\r\n    field1: "浙江卫视",\r\n    field2: "《奔跑吧兄弟》",\r\n  