INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2021822069937356800','2019673282695475200','quality-card','<template>\r\n  <el-card v-for="item in list" :key="item.label" class="report-item quality-card">\r\n    <div class="flex">\r\n      <div\r\n        class="report-item-icon flex items-center justify-center"\r\n        :style="{ backgroundColor: `${item.color}20` }"\r\n      >\r\n        <Icon :icon="item.icon" :color="item.color" :size="34"></Icon>\r\n      </div>\r\n      <div class="report-item-content">\r\n        <span class="result-item_title">{{ item.label }}</span>\r\n        <div class="result-item_body">\r\n          <span\r\n            class="result-item_value"\r\n            :style="{ color: item.type === \'error\' ? \'#dc2626\' : undefined }"\r\n          >\r\n            {{ item.value }}\r\n          </span>\r\n          <span\r\n            class="result-item_unit"\r\n            :style="{ color: item.type === \'error\' ? \'#dc2626\' : undefined }"\r\n          >\r\n            {{ item.unit }}\r\n          </span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class="report-item-footer flex justify-between">\r\n      <div v-for="(value, key) in item.extra" :key="key" class="result-item_extra">\r\n        <span>{{ `${key}：` }}</span>\r\n        <span>{{ value }}</span>\r\n      </div>\r\n    </div>\r\n  </el-card>\r\n</template>\r\n\r\n<script setup lang="ts">\r\ninterface ReportItem {\r\n  label: string;\r\n  value: string;\r\n  unit: string;\r\n  icon: string;\r\n  color: string;\r\n  type?: string;\r\n  extra: Record<string, any>;\r\n}\r\n\r\ndefineProps<{\r\n  list: ReportItem[];\r\n}>();\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.quality-card {\r\n  position: relative;\r\n  padding: 0 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  box-shadow: 0 0 12px #f3f4fa;\r\n  border-radius: 6px;\r\n\r\n  :deep(.el-card__body) {\r\n    padding: 0;\r\n  }\r\n\r\n  &:hover {\r\n    transform: translateY(-4px);\r\n  }\r\n\r\n  .report-item-icon {\r\n    width: 60px;\r\n    height: 60px;\r\n    margin: 15px 15px 15px 0;\r\n    border-radius: 12px;\r\n  }\r\n\r\n  .report-item-content {\r\n    flex: 1;\r\n    margin: 18px 0 0;\r\n\r\n    .result-item_title {\r\n      color: #8392a5;\r\n      font-weight: 400;\r\n      font-size: 14px;\r\n    }\r\n\r\n    .result-item_body {\r\n      padding-top: 6px;\r\n    }\r\n\r\n    .result-item_value {\r\n      font-size: 30px;\r\n      color: rgb(32, 39, 58);\r\n      font-weight: 700;\r\n      margin-right: 5px;\r\n    }\r\n\r\n    .result-item_unit {\r\n      color: #8392a5;\r\n      font-weight: 400;\r\n      font-size: 14px;\r\n    }\r\n  }\r\n\r\n  .report-item-footer {\r\n    border-top: 1px dashed #e0e0e0;\r\n  }\r\n\r\n  .result-item_extra {\r\n    margin: 13px 0;\r\n    color: #8392a5;\r\n    text-align: right;\r\n    line-height: 18px;\r\n    font-weight: 400;\r\n    font-size: 12px;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _hoisted_1 = {\n  class: "flex"\n}