ontent .result-item_unit[data-v-9c2f2cf3abcc734b208cecc6075c2093] {\n  color: #8392a5;\n  font-weight: 400;\n  font-size: 14px;\n}\n.quality-card .report-item-footer[data-v-9c2f2cf3abcc734b208cecc6075c2093] {\n  border-top: 1px dashed #e0e0e0;\n}\n.quality-card .result-item_extra[data-v-9c2f2cf3abcc734b208cecc6075c2093] {\n  margin: 13px 0;\n  color: #8392a5;\n  text-align: right;\n  line-height: 18px;\n  font-weight: 400;\n  font-size: 12px;\n}','1','质量卡片',NULL,NULL,0,'2084109831678504960',6);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2021465157593022464','2019673282695475200','quality-empty','<template>\r\n  <div class="quality-empty">\r\n    <div class="quality-content">\r\n      <!-- 左侧：微型仪表盘 -->\r\n      <div class="dashboard-container">\r\n        <div class="dashboard-card">\r\n          <div class="dashboard-circle">\r\n            <svg width="128" height="128" viewBox="0 0 128 128">\r\n              <circle\r\n                cx="64"\r\n                cy="64"\r\n                r="56"\r\n                stroke="#F1F5F9"\r\n                stroke-width="10"\r\n                fill="transparent"\r\n              />\r\n              <circle\r\n                cx="64"\r\n                cy="64"\r\n                r="56"\r\n                stroke="#1D61FF"\r\n                stroke-width="10"\r\n                stroke-dasharray="280"\r\n                stroke-dashoffset="280"\r\n                fill="transparent"\r\n                class="circle-progress"\r\n              />\r\n            </svg>\r\n            <div class="dashboard-content">\r\n              <span class="dashboard-score">--</span>\r\n              <span class="dashboard-label">Score</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- 右侧：紧凑规则矩阵 -->\r\n        <div class="rules-container">\r\n          <div class="rules-header">\r\n            <Icon icon="shandian" class="rules-icon"></Icon>\r\n            <span>数据质检</span>\r\n          </div>\r\n          <div class="rules-grid">\r\n            <div v-for="rule in miniRules" :key="rule.label" class="rule-card">\r\n              <div class="rule-icon" :style="{ backgroundColor: `${rule.color || \'#0190f9\'}20` }">\r\n                <Icon :icon="rule.icon" :color="rule.color" size="16"></Icon>\r\n              </div>\r\n              <div class="rule-content">\r\n      