lex;\r\n      align-items: center;\r\n      gap: 48px;\r\n      margin-bottom: 40px;\r\n      width: 100%;\r\n\r\n      .dashboard-card {\r\n        width: 160px;\r\n        height: 160px;\r\n        background-color: #ffffff;\r\n        border-radius: 24px;\r\n        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);\r\n        border: 1px solid #e0e7ff;\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        position: relative;\r\n        flex-shrink: 0;\r\n        transition: all 0.3s ease;\r\n\r\n        &:hover {\r\n          transform: translateY(-5px);\r\n          box-shadow: 0 12px 32px rgba(0, 0, 0, 0.15);\r\n        }\r\n\r\n        .dashboard-circle {\r\n          position: relative;\r\n          display: flex;\r\n          align-items: center;\r\n          justify-content: center;\r\n\r\n          svg {\r\n            width: 128px;\r\n            height: 128px;\r\n            transform: rotate(-90deg);\r\n          }\r\n\r\n          .circle-progress {\r\n            animation: dash 2s ease-out forwards;\r\n          }\r\n\r\n          .dashboard-content {\r\n            position: absolute;\r\n            inset: 0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n\r\n            .dashboard-score {\r\n              font-size: 36px;\r\n              font-weight: 900;\r\n              color: #1f2937;\r\n              line-height: 1;\r\n            }\r\n\r\n            .dashboard-label {\r\n              font-size: 10px;\r\n              color: #9ca3af;\r\n              font-weight: 900;\r\n              text-transform: uppercase;\r\n              letter-spacing: 0.2em;\r\n              margin-top: 4px;\r\n            }\r\n          }\r\n        }\r\n      }\r\n\r\n      .rules-container {\r\n        flex: 1;\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: