.rules-container .rules-grid .rule-card .rule-content .rule-progress .rule-progress-bar[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  height: 100%;\n  background-color: #e5e7eb;\n  border-radius: 9999px;\n  width: 33.33%;\n}\n.quality-empty .quality-content[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  /* 文案引导 */\n}\n.quality-empty .quality-content .guidance-section[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  text-align: center;\n  margin-top: 40px;\n  width: 100%;\n}\n.quality-empty .quality-content .guidance-section .guidance-title[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  margin-bottom: 24px;\n  color: #323643;\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  padding: 0 40px;\n  height: 56px;\n  background-color: #1d61ff;\n  color: #ffffff;\n  border-radius: 18px;\n  font-size: 15px;\n  font-weight: 900;\n  box-shadow: 0 20px 40px -10px rgba(29, 97, 255, 0.4);\n  transition: all 0.3s ease;\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  margin: 0 auto;\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn[data-v-f5dd7febf23e0a360e84568aa31b8f6d]:hover {\n  background-color: #1e40af;\n  transform: translateY(-4px);\n  box-shadow: 0 24px 48px -12px rgba(29, 97, 255, 0.5);\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn[data-v-f5dd7febf23e0a360e84568aa31b8f6d]:active {\n  transform: translateY(0) scale(0.95);\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn .button-icon[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  background-color: rgba(255, 255, 255, 0.2);\n  padding: 6px;\n  border-radius: 9999px;\n  transition: transform 0.3s ease;\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn .button-icon .el-icon[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  font-size: 18px;\n}\n.quality-empty .quality-content .guidance-section .guidance-button .start-quality-btn:hover .button-icon[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  transform: translateX(4px);\n}\n.quality-empty .quality-content[data-v-f5dd7febf23e0a360e84568aa31b8f6d] {\n  /* 动画 */\n}\n@keyframes dash-f5dd7febf23e0a360e84568aa31b8f6d {\nfrom {\n    stroke-dashoffset: 351;\n}\nto {\n    stroke-dashoffset: 0;\n}\n}','1','质检结果暂无',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2020410655368622080','2019673282695475200','quality-report','<template>\r\n  <div class="quality-report card-container flex flex-col px-5 pt-5 pb-2">\r\n    <template v-if="categoryId == \'1\'">\r\n      <quality-empty></quality-empty>\r\n    </template>\r\n    <template v-else>\r\n      <div class="quality-report-list">\r\n        <quality-card :list="list" />\r\n      </div>\r\n      <u-title name="质检规则执行明细" class="quality-report-detail">\r\n        <template #default>\r\n          <div class="flex items-center ml-2">\r\n            <Icon icon="el-icon-timer" :color="\'#8392a5\'"></Icon>\r\n            <span class="quality-report-time">{{ qualityTime }}</span>\r\n          </div>\r\n        </template>\r\n        <template #right>\r\n          <el-button type="danger" plain>\r\n            <Icon icon="info" class="mr-2"></Icon>\r\n            查看异常数据\r\n          </el-button>\r\n          <el-button type="primary" @click="handlerQuality">\r\n            <Icon icon="shandian" class="mr-2"></Icon>\r\n            去质检\r\n          </el-button>\r\n        </template>\r\n      </u-title>\r\n      <DataTable :columns="columns" :data="tableData" show-index class="flex-1">\r\n        <template #column-dataItemCode="{ row }">\r\n          <el-tag type="info" style="color: #8392a5">{{ row.dataItemCode }}</el-tag>\r\n        </template>\r\n        <template #column-rule="{ row }">\r\n          <template v-if="row.rule">\r\n            <el-tag v-for="item in row.rule.split(\',\')" :key="item" class="mr-2">\r\n              {{ item }}\r\n            </el-tag>\r\n          </template>\r\n        </template>\r\n      </DataTable>\r\n      <register-modal\r\n        v-if="registerModalVisible"\r\n        v-model="registerModalVisible"\r\n        :register-class="\'quality\'"\r\n        :quality-data="qualityData"\r\n        @close="closeRegisterModal"\r\n      ></register-modal>\r\n    </template>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, onMounted } from "vue";\r\nimport { useRoute } from "vue-router";\r\n// import QualityCard from "@/views/quality-card.vue";\r\n\r\n// 获取路由实例\r\nconst route = useRoute();\r\n\r\nconst categoryId = ref("");\r\nconst qualityTime = ref("2025-08-01 10:00:00");\r\n\r\n// 初始化时获取路由参数\r\nconst initCategoryId = () => {\r\n  categoryId.value = route.query?.categoryId || route.query?.id || "";\r\n};\r\n\r\nconst qualityData = ref({\r\n  name: "qualitycheck",\r\n  title: "创建成功",\r\n  code: "TSK_QUALITY_001",\r\n  time: "2025-08-01 16:11:00",\r\n  type: "quality",\r\n});\r\nconst list = ref([\r\n  {\r\n    label: "异常字段数",\r\n    value: "2",\r\n    unit: "个",\r\n    icon: "field2",\r\n    color: "#fda937",\r\n    extra: {\r\n      总字段: 9,\r\n      未质检: 7,\r\n    },\r\n  },\r\n  {\r\n    label: "异常数据量",\r\n    value: "1600",\r\n    unit: "条",\r\n    icon: "error",\r\n    type: "error",\r\n    color: "#f56c6c",\r\n    extra: {\r\n      总数据量: 3000,\r\n      异常率: "56%",\r\n    },\r\n  },\r\n  {\r\n    label: "字段对标率",\r\n    value: "80",\r\n    unit: "%",\r\n    icon: "align",\r\n    color: "#0190f9",\r\n    extra: {\r\n      对标数: 9,\r\n      未对标数: 1,\r\n    },\r\n  },\r\n  {\r\n    label: "质检规则数",\r\n    value: "6",\r\n    unit: "个",\r\n    icon: "rule",\r\n    color: "#8269f9",\r\n    extra: {\r\n      字段级: 5,\r\n      表级: 1,\r\n    },\r\n  },\r\n]);\r\nconst columns = ref([\r\n  {\r\n    prop: "dataItemName",\r\n    label: "数据项中文名",\r\n  },\r\n  {\r\n    prop: "dataItemCode",\r\n    label: "数据项英文名",\r\n  },\r\n  {\r\n    prop: "dimension",\r\n    label: "指标维度",\r\n    options: "qualityDimension",\r\n  },\r\n  {\r\n    prop: "rule",\r\n    label: "指标规则",\r\n  },\r\n  {\r\n    prop: "checkMethod",\r\n    label: "检查方式",\r\n  },\r\n  {\r\n    prop: "checkTotal",\r\n    label: "检查总量",\r\n    formatter: (row: any, column: any, cellValue: number) => {\r\n      if (cellValue === null || cellValue === undefined) {\r\n        return "0";\r\n      }\r\n      return cellValue.toLocaleString();\r\n    },\r\n  },\r\n  {\r\n    prop: "checkException",\r\n    label: "异常量",\r\n  },\r\n  {\r\n    prop: "checkExceptionRate",\r\n    label: "异常率",\r\n  },\r\n]);\r\nconst tableData = ref([\r\n  {\r\n    dataItemName: "客户名称",\r\n    dataItemCode: "customer_name",\r\n    dimension: "0",\r\n    rule: "非空校验,空字符串检查,长度检查",\r\n    checkMethod: "全量",\r\n    checkTotal: 1000,\r\n    checkException: 100,\r\n    checkExceptionRate: "10%",\r\n  },\r\n  {\r\n    dataItemName: "内容摘要",\r\n    dataItemCode: "content_summary",\r\n    dimension: "0",\r\n    rule: "空字符串检查",\r\n    checkMethod: "全量",\r\n    checkTotal: 3000,\r\n    checkException: 0,\r\n    checkExceptionRate: "0%",\r\n  },\r\n  {\r\n    dataItemName: "备案号",\r\n    dataItemCode: "record_number",\r\n    dimension: "1",\r\n    rule: "长度检查",\r\n    checkMethod: "增量",\r\n    checkTotal: 1200,\r\n    checkException: 110,\r\n    checkExceptionRate: "5%",\r\n  },\r\n  {\r\n    dataItemName: "审核日期",\r\n    dataItemCode: "approval_date",\r\n    dimension: "1",\r\n    rule: "日期格式检查",\r\n    checkMethod: "增量",\r\n    checkTotal: 1540,\r\n    checkException: 90,\r\n    checkExceptionRate: "6.5%",\r\n  },\r\n  {\r\n    dataItemName: "电视剧标识",\r\n    dataItemCode: "drama_id",\r\n    dimension: "3",\r\n    rule: "主键唯一性",\r\n    checkMethod: "增量",\r\n    checkTotal: 4640,\r\n    checkException: 80,\r\n    checkExceptionRate: "16.5%",\r\n  },\r\n]);\r\nconst registerModalVisible = ref(false);\r\n\r\nconst closeRegisterModal = () => {\r\n  registerModalVisible.value = false;\r\n};\r\nconst handlerQuality = () => {\r\n  registerModalVisible.value = true;\r\n};\r\n\r\n// 监听路由变化\r\nwatch(\r\n  () => route.query,\r\n  () => {\r\n    initCategoryId();\r\n  },\r\n  { deep: true }\r\n);\r\n\r\nonMounted(() => {\r\n  initCategoryId();\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.quality-report {\r\n  // width: 100%;\r\n  .quality-report-list {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, 1fr);\r\n    gap: 20px;\r\n    margin-bottom: 10px;\r\n    .report-item {\r\n      position: relative;\r\n      padding: 0 20px;\r\n      display: flex;\r\n      flex-direction: column;\r\n      :deep(.el-card__body) {\r\n        padding: 0;\r\n      }\r\n      &:hover {\r\n        transform: translateY(-4px);\r\n      }\r\n      .report-item-icon {\r\n        width: 60px;\r\n        height: 60px;\r\n        margin: 15px 15px 15px 0;\r\n        border-radius: 12px;\r\n      }\r\n      .report-item-content {\r\n        flex: 1;\r\n        margin: 18px 0 0;\r\n        .result-item_title {\r\n          color: #8392a5;\r\n          font-weight: 400;\r\n          font-size: 14px;\r\n        }\r\n        .result-item_body {\r\n          padding-top: 6px;\r\n        }\r\n        .result-item_value {\r\n          font-size: 30px;\r\n          color: rgb(32, 39, 58);\r\n          font-weight: 700;\r\n          margin-right: 5px;\r\n        }\r\n        .result-item_unit {\r\n          color: #8392a5;\r\n          font-weight: 400;\r\n          font-size: 14px;\r\n        }\r\n      }\r\n      .report-item-footer {\r\n        border-top: 1px dashed #e0e0e0;\r\n      }\r\n      .result-item_extra {\r\n        margin: 13px 0;\r\n        color: #8392a5;\r\n        text-align: right;\r\n        line-height: 18px;\r\n        font-weight: 400;\r\n        font-size: 12px;\r\n      }\r\n    }\r\n  }\r\n\r\n  .quality-report-title {\r\n    font-weight: 700;\r\n    margin: 0;\r\n  }\r\n  .quality-report-time {\r\n    color: #8392a5;\r\n    font-weight: 400;\r\n    font-size: 12px;\r\n    height: 10px;\r\n  }\r\n\r\n  .quality-report-card {\r\n    box-shadow: 0 0 12px #f3f4fa;\r\n    border-radius: 6px;\r\n  }\r\n  .quality-report-detail {\r\n    :deep(.toolbar) {\r\n      align-items: center;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _def