  checkTotal: 3000,\n      checkException: 0,\n      checkExceptionRate: "0%"\n    }, {\n      dataItemName: "备案号",\n      dataItemCode: "record_number",\n      dimension: "1",\n      rule: "长度检查",\n      checkMethod: "增量",\n      checkTotal: 1200,\n      checkException: 110,\n      checkExceptionRate: "5%"\n    }, {\n      dataItemName: "审核日期",\n      dataItemCode: "approval_date",\n      dimension: "1",\n      rule: "日期格式检查",\n      checkMethod: "增量",\n      checkTotal: 1540,\n      checkException: 90,\n      checkExceptionRate: "6.5%"\n    }, {\n      dataItemName: "电视剧标识",\n      dataItemCode: "drama_id",\n      dimension: "3",\n      rule: "主键唯一性",\n      checkMethod: "增量",\n      checkTotal: 4640,\n      checkException: 80,\n      checkExceptionRate: "16.5%"\n    }]);\n    const registerModalVisible = ref(false);\n    const closeRegisterModal = () => {\n      registerModalVisible.value = false;\n    };\n    const handlerQuality = () => {\n      registerModalVisible.value = true;\n    };\n\n    // 监听路由变化\n    watch(() => route.query, () => {\n      initCategoryId();\n    }, {\n      deep: true\n    });\n    onMounted(() => {\n      initCategoryId();\n    });\n    return (_ctx, _cache) => {\n      const _component_quality_empty = _resolveComponent("quality-empty");\n      const _component_quality_card = _resolveComponent("quality-card");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_el_tag = _resolveComponent("el-tag");\n      const _component_DataTable = _resolveComponent("DataTable");\n      const _component_register_modal = _resolveComponent("register-modal");\n      return _openBlock(), _createElementBlock("div", _hoisted_1, [categoryId.value == \'1\' ? (_openBlock(), _createBlock(_component_quality_empty, {\n        key: 0\n      })) : (_openBlock(), _createElementBlock(_Fragment, {\n        