INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2020696910199341056','2020696697363578880','quality-rule-config','<template>\r\n  <div class="quality-rule-config px-5 py-2">\r\n    <u-tabs v-model="pageTab" :tabs="tabs"></u-tabs>\r\n    <div class="filter-section">\r\n      <div class="filter-header">\r\n        <div class="filter-title mr-1">\r\n          <Icon :icon="\'el-icon-Filter\'"></Icon>\r\n          <span>数据过滤范围</span>\r\n        </div>\r\n        <el-tooltip\r\n          content="公式配置说明：留空表示全量。多行条件间默认为 AND 逻辑。支持变量如 ${bizdate}。"\r\n          placement="top"\r\n        >\r\n          <Icon :icon="\'info\'"></Icon>\r\n        </el-tooltip>\r\n      </div>\r\n      <div class="filter-rows">\r\n        <div v-for="(row, idx) in filterRows" :key="idx" class="filter-row">\r\n          <el-select\r\n            v-model="row.field"\r\n            placeholder="选择字段"\r\n            class="field-select"\r\n            @change="updateFilterRow(idx, \'field\', $event)"\r\n          >\r\n            <el-option\r\n              v-for="field in fields"\r\n              :key="field.name"\r\n              :label="field.name"\r\n              :value="field.name"\r\n            />\r\n          </el-select>\r\n          <el-select\r\n            v-model="row.op"\r\n            placeholder="运算符"\r\n            class="op-select"\r\n            @change="updateFilterRow(idx, \'op\', $event)"\r\n          >\r\n            <el-option\r\n              v-for="field in opOptions"\r\n              :key="field.name"\r\n              :label="field.name"\r\n              :value="field.name"\r\n            />\r\n          </el-select>\r\n          <el-input\r\n            v-model="row.value"\r\n            placeholder="输入过滤值..."\r\n            class="value-input"\r\n            @input="updateFilterRow(idx, \'value\', $event)"\r\n          />\r\n          <el-button\r\n            :type="idx === filterRows.length - 1 ? \'primary\' : \'danger\'"\r\n            link\r\n            @click="idx === filterRows.length - 1 ? handleAddFilter() : handleRemoveFilter(idx)"\r\n          >\r\n            <Icon\r\n              :icon="idx === filterRows.length - 1 ? \'el-icon-CirclePlus\' : \'el-icon-delete\'"\r\n              :size="20"\r\n            ></Icon>\r\n          </el-button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <template v-if="pageTab === \'rule\'">\r\n      <DataTable :columns="columns" :data="tableData" show-index :flex-type="\'flex-[0_1_auto]\'">\r\n        <template #columns-qualityRule="{ row }">\r\n          <el-tag>{{ row.qualityRule }}</el-tag>\r\n        </template>\r\n        <template #column-rule="{ row }">\r\n          <template v-if="row.rule">\r\n            <el-tag v-for="item in row.rule.split(\',\')" :key="item" class="mr-2">\r\n              {{ item }}\r\n            </el-tag>\r\n          </template>\r\n        </template>\r\n        <template #column-field="{ row }">\r\n          <el-text>{{ row.fieldName }}</el-text>\r\n          <div v-if="row.fieldCode">\r\n            <el-text type="info" size="small">{{ row.fieldCode }}</el-text>\r\n          </div>\r\n        </template>\r\n      </DataTable>\r\n    </template>\r\n    <template v-if="pageTab === \'table\'">\r\n      <div class="rule-list">\r\n        <div\r\n          v-for="rule in tableRules"\r\n          :key="rule.id"\r\n          :class="[\'rule-card\', { active: selectedRuleIds.includes(rule.id) }]"\r\n          @click="setSelectedRule(rule)"\r\n        >\r\n          <div class="rule-card-header">\r\n            <h4 class="rule-card-title">{{ rule.name }}</h4>\r\n          </div>\r\n          <p class="rule-card-desc">{{ rule.desc }}</p>\r\n          <div class="rule-card-footer">\r\n            <span class="rule-card-code">{{ rule.code }}</span>\r\n            <Icon\r\n              icon="el-icon-ArrowRight"\r\n              :color="selectedRuleId === rule.id ? \'#1b67f8\' : \'#94a3b8\'"\r\n              class="rule-card-arrow"\r\n            />\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </template>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref } from "vue";\r\n\r\nconst pageTab = ref("rule");\r\nconst tabs = ref([\r\n  {\r\n    label: "字段级规则",\r\n    value: "rule",\r\n  },\r\n  {\r\n    label: "表级规则",\r\n    value: "table",\r\n  },\r\n]);\r\n\r\n// 字段数据（模拟）\r\nconst fields = ref([\r\n  { name: "channel_code" },\r\n  { name: "channel_name" },\r\n  { name: "channel_type" },\r\n  { name: "create_time" },\r\n  { name: "update_time" },\r\n  { name: "delete_status" },\r\n]);\r\n// 运算符选项\r\nconst opOptions = ref([\r\n  { name: "=" },\r\n  { name: ">=" },\r\n  { name: "<=" },\r\n  { name: "!=" },\r\n  { name: "LIKE" },\r\n  { name: "IN" },\r\n]);\r\n\r\nconst columns = ref([\r\n  {\r\n    label: "字段信息",\r\n    prop: "fieldName",\r\n  },\r\n  {\r\n    label: "字段英文名",\r\n    prop: "fieldEnName",\r\n  },\r\n  {\r\n    label: "数据类型",\r\n    prop: "dataType",\r\n    options: "tableColType",\r\n  },\r\n  {\r\n    label: "质检规则",\r\n    prop: "rule",\r\n  },\r\n]);\r\n\r\nconst tableData = ref([\r\n  {\r\n    fieldName: "频道编号",\r\n    fieldCode: "CHANNEL_ID",\r\n    fieldEnName: "channel_code",\r\n    dataType: "int",\r\n    rule: "非空校验,空字符串检查,长度检查",\r\n  },\r\n  {\r\n    fieldName: "渠道名称",\r\n    fieldCode: "CHANNEL_NAME",\r\n    fieldEnName: "channel_name",\r\n    dataType: "string",\r\n    rule: "非空校验,空字符串检查,长度检查",\r\n  },\r\n  {\r\n    fieldName: "渠道类型",\r\n    fieldCode: "CHANNEL_TYPE",\r\n    fieldEnName: "channel_type",\r\n    dataType: "string",\r\n    rule: "非空校验",\r\n  },\r\n  {\r\n    fieldName: "创建时间",\r\n    fieldCode: "CREATE_TIME",\r\n    fieldEnName: "create_time",\r\n    dataType: "timestamp",\r\n    rule: "非空校验",\r\n  },\r\n  {\r\n    fieldName: "更新时间",\r\n    fieldCode: "UPDATE_TIME",\r\n    fieldEnName: "update_time",\r\n    dataType: "timestamp",\r\n    rule: "非空校验",\r\n  },\r\n  {\r\n    fieldName: "删除状态",\r\n    fieldCode: "DELETE_STATUS",\r\n    fieldEnName: "delete_status",\r\n    dataType: "int",\r\n    rule: "非空校验",\r\n  },\r\n]);\r\n\r\nconst tableRules = ref([\r\n  {\r\n    id: "R-INT-005",\r\n    name: "主键唯一性",\r\n    code: "primary_key_uniqueness",\r\n    dimension: "0",\r\n    level: "table",\r\n    desc: "主键去重后记录数应与总行数一致",\r\n    logic: "SELECT count(1) FROM ${table} WHERE ${column} IS NOT NULL AND ${column} <> \'\'",\r\n    scope: "主键字段",\r\n    params: "column: 校验字段",\r\n    exception: "记录异常日志并告警",\r\n  },\r\n  {\r\n    id: "R-STD-011",\r\n    name: "元数据一致性",\r\n    code: "metadata_consistency",\r\n    dimension: "1",\r\n    level: "table",\r\n    desc: "表结构（列数、类型）未发生非预期变更",\r\n    logic:\r\n      "SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE table_schema = \'${schema}\' AND table_name = \'${table}\' EXCEPT SELECT COUNT(*) FROM expected_metadata WHERE table_name = \'${table}\'",\r\n    scope: "所有需要元数据一致性检查的表",\r\n    params: "table: 检查表名, schema: 数据库模式",\r\n    exception: "记录异常日志并通知数据管理员",\r\n  },\r\n  {\r\n    id: "R-ACC-004",\r\n    name: "指标总和检查",\r\n    code: "sum_check",\r\n    dimension: "2",\r\n    level: "table",\r\n    desc: "验证特定数值字段的汇总结果是否落在预期的合理范围内",\r\n    logic:\r\n      "SELECT CASE WHEN SUM(${column}) BETWEEN ${min_sum} AND ${max_sum} THEN 0 ELSE 1 END FROM ${table}",\r\n    scope: "需要汇总校验的数值字段，如销售额、数量、金额等",\r\n    params: "column: 汇总字段, min_sum: 最小汇总值, max_sum: 最大汇总值, table: 表名",\r\n    exception: "生成质量缺陷单并通知数据管理员",\r\n  },\r\n  {\r\n    id: "R-ACC-005",\r\n    name: "逻辑勾稽校验",\r\n    code: "cross_field_check",\r\n    dimension: "2",\r\n    level: "table",\r\n    desc: "验证跨指标逻辑，如：总金额 = 净价 + 税额 的表级汇总",\r\n    logic:\r\n      "SELECT count(1) FROM ${table} WHERE ABS(${total_field} - (${field1} + ${field2})) > ${tolerance}",\r\n    scope: "需要字段间勾稽关系校验的财务、统计类数据表",\r\n    params: "total_field: 总计字段, field1: 字段1, field2: 字段2, tolerance: 容差值, table: 表名",\r\n    exception: "任务回滚并通知财务负责人",\r\n  },\r\n  {\r\n    id: "R-CON-002",\r\n    name: "跨源总数对账",\r\n    code: "cross_source_reconciliation",\r\n    dimension: "3",\r\n    level: "table",\r\n    desc: "比较源端 MySQL 与目标端 Hive 的总行数",\r\n    logic:\r\n      "SELECT CASE WHEN (SELECT count(1) FROM ${source_table}) = (SELECT count(1) FROM ${target_table}) THEN 0 ELSE 1 END",\r\n    scope: "需要进行数据同步对账的源表和目标表",\r\n    params:\r\n      "source_table: 源端表名, target_table: 目标端表名, source_schema: 源端数据库模式, target_schema: 目标端数据库模式",\r\n    exception: "生成对账差异报告并通知数据管理员",\r\n  },\r\n]);\r\n\r\nconst selectedRuleIds = ref([]);\r\n\r\n// 过滤条件行\r\nconst filterRows = ref([{ field: "", op: "", value: "" }]);\r\n\r\nconst setSelectedRule = (rule: any) => {\r\n  if (selectedRuleIds.value.includes(rule.id)) {\r\n    selectedRuleIds.value = selectedRuleIds.value.filter((id) => id !== rule.id);\r\n  } else {\r\n    selectedRuleIds.value.push(rule.id);\r\n  }\r\n};\r\n\r\n// 更新过滤条件行\r\nconst updateFilterRow = (idx: number, field: string, value: any) => {\r\n  filterRows.value[idx][field] = value;\r\n};\r\n\r\n// 添加过滤条件行\r\nconst handleAddFilter = () => {\r\n  filterRows.value.push({ field: "", op: "", value: "" });\r\n};\r\n\r\n// 删除过滤条件行\r\nconst handleRemoveFilter = (idx: number) => {\r\n  filterRows.value = filterRows.value.filter((_, i) => i !== idx);\r\n  // 确保至少有一行\r\n  if (filterRows.value.length === 0) {\r\n    filterRows.value.push({ field: "", op: "", value: "" });\r\n  }\r\n};\r\n\r\n// 保存表单数据\r\nconst save = async () => {\r\n  console.log("save:", selectedRuleIds.value, tableData.value);\r\n};\r\n\r\nconst next = async () => {\r\n  console.log("next:", selectedRuleIds.value, tableData.value);\r\n};\r\ndefineExpose({\r\n  save,\r\n  next,\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.quality-rule-config {\r\n  // width: 100%;\r\n  // height: 100%;\r\n  background-color: #fff;\r\n  .filter-section {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    margin: 20px 0;\r\n    gap: 10px;\r\n  }\r\n\r\n  .filter-header {\r\n    height: 32px;\r\n    display: flex;\r\n    align-items: center;\r\n  }\r\n\r\n  .filter-title {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    font-weight: bold;\r\n    color: #4b5563;\r\n    font-size: 14px;\r\n\r\n    .filter-icon {\r\n      color: #003399;\r\n    }\r\n  }\r\n\r\n  .filter-info {\r\n    color: #94a3b8;\r\n    cursor: help;\r\n    margin-top: 2px;\r\n  }\r\n\r\n  .filter-rows {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 12px;\r\n    flex: 1;\r\n  }\r\n\r\n  .filter-row {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n    animation: fadeIn 0.3s ease-in-out;\r\n  }\r\n\r\n  .field-select {\r\n    width: 140px;\r\n  }\r\n\r\n  .op-select {\r\n    width: 90px;\r\n  }\r\n\r\n  .value-input {\r\n    flex: 1;\r\n    min-width: 0;\r\n  }\r\n  .rule-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 12px;\r\n  }\r\n  .rule-card {\r\n    padding: 1rem;\r\n    border-radius: 4px;\r\n    background: #fff;\r\n    border: 1px solid #d8dee6;\r\n    cursor: pointer;\r\n    transition: all 0.2s ease;\r\n\r\n    &:hover {\r\n      border: 1px solid #bfdbfe;\r\n      box-shadow: 0 0 12px #bfdbfe26;\r\n      :deep(.rule-card-arrow) {\r\n        transform: translateX(4px);\r\n      }\r\n    }\r\n\r\n    &.active {\r\n      border: 1px solid #1b67f8;\r\n      box-shadow: 0 0 12px #1b67f826;\r\n    }\r\n\r\n    .rule-card-header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n\r\n      .rule-card-title {\r\n        font-weight: 500;\r\n        font-size: 15px;\r\n        text-align: left;\r\n        color: #0f172a;\r\n        margin: 0;\r\n      }\r\n\r\n      .el-tag {\r\n        font-size: 0.625rem;\r\n        font-weight: bold;\r\n      }\r\n    }\r\n\r\n    .rule-card-desc {\r\n      font-family: "Source Han Sans SC";\r\n      font-weight: 400;\r\n      font-size: 13px;\r\n      color: #94a3b8;\r\n      padding: 8px 0;\r\n      margin: 0;\r\n      display: -webkit-box;\r\n      -webkit-line-clamp: 2;\r\n      -webkit-box-orient: vertical;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .rule-card-footer {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n\r\n      .rule-card-code {\r\n        font-weight: 400;\r\n        font-size: 13px;\r\n        color: #94a3b8;\r\n      }\r\n\r\n      .rule-card-arrow {\r\n        transition: transform 0.2s ease;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n@keyframes fadeIn {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(-10px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\nconst _hoisted_1 = {\n  class: "quality-rule-config px-5 py-2"\n};\nconst _hoisted_2 = {\n  class: "filter-section"\n};\nconst _hoisted_3 = {\n  class: "filter-header"\n};\nconst _hoisted_4 = {\n  class: "f