INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2017179897413832704','1998313128624459776','register-apply','<template>\r\n  <div class="px-5 py-2">\r\n    <JsonForm\r\n      ref="formRef"\r\n      bordered\r\n      :rules="formRules"\r\n      :options="{\r\n        form: {\r\n          labelWidth: \'250px\',\r\n        },\r\n      }"\r\n    >\r\n      <template #type-apply-table>\r\n        <data-table\r\n          flex-type="flex-[0_1_200px]"\r\n          border\r\n          class="rounded-lg"\r\n          :show-page="false"\r\n          :data="tableState.list"\r\n          :columns="tableState.cols"\r\n        >\r\n          <template #column-radio="{ row }">\r\n            <el-radio\r\n              :model-value="tableState.check"\r\n              :value="row.tid"\r\n              @click="chooseRes(row)"\r\n            ></el-radio>\r\n          </template>\r\n          <template #column-assetName="{ row }">\r\n            <el-text>\r\n              <Icon :icon="row.assetClass" />\r\n              {{ row.assetName }}\r\n            </el-text>\r\n          </template>\r\n          <template #column-categoryName="{ row }">\r\n            <el-text>\r\n              <Icon icon="category" />\r\n              {{ row.categoryName }}\r\n            </el-text>\r\n          </template>\r\n        </data-table>\r\n      </template>\r\n    </JsonForm>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, onMounted, nextTick, reactive } from "vue";\r\nimport { storeToRefs } from "pinia";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { useRegisterStore } from "@/store";\r\nimport { get, set } from "lodash-es";\r\nimport dayjs from "dayjs";\r\n\r\n// refs\r\nconst formRef = ref();\r\nconst formRules = ref([]);\r\nconst store = useRegisterStore();\r\nconst { state } = storeToRefs(store);\r\n// 当前申请单信息\r\nconst apply = computed({\r\n  get: () => {\r\n    if (!get(store.data, "apply")) {\r\n      set(store.data, "apply", {});\r\n    }\r\n    return get(store.data, "apply");\r\n  },\r\n  set: (val) => set(store.data, "apply", val),\r\n});\r\n\r\nonMounted(() => {\r\n  // @TODO 第一步初始化信息，也可调接口更新数据\r\n  formRules.value = [...rule1, ...rule3];\r\n  nextTick(() => {\r\n    formRef.value?.setValue({\r\n      ...mock,\r\n      ...apply.value,\r\n    });\r\n    chooseRes(tableState.list[0]);\r\n  });\r\n});\r\n\r\nconst chooseRes = (row) => {\r\n  tableState.check = row.tid;\r\n  tableState.resName = row.assetName;\r\n  tableState.assetClass = row.assetClass;\r\n  tableState.resId = row.tid;\r\n  tableState.row = row;\r\n  if (row.assetClass === "api") {\r\n    formRules.value = [...rule1, ...rule2, ...rule3];\r\n    nextTick(() => {\r\n      formRef.value?.setValue({\r\n        ...mock,\r\n        ...apply.value,\r\n      });\r\n    });\r\n  } else {\r\n    formRules.value = [...rule1, ...rule3];\r\n    nextTick(() => {\r\n      formRef.value?.setValue({\r\n        ...mock,\r\n        ...apply.value,\r\n      });\r\n    });\r\n  }\r\n};\r\n\r\n// 验证表单\r\nconst validate = async () => {\r\n  if (!tableState.check) {\r\n    throw "请选择订阅资源";\r\n  }\r\n  if (!formRef.value) {\r\n    throw new Error("表单未初始化");\r\n  }\r\n  await formRef.value.validate();\r\n};\r\n\r\nconst saveApi = (data: Record<string, any>) => {\r\n  return new Promise((resolve) => {\r\n    setTimeout(() => {\r\n      resolve({ tid: $common.uuid(), ...data });\r\n    }, 1000);\r\n  });\r\n};\r\n\r\nconst save = async (): Promise<any> => {\r\n  try {\r\n    state.value.loadStatus["main"] = true;\r\n    await validate();\r\n    // 保存逻辑\r\n    const formData = formRef.value?.getSaveData() || {};\r\n    const data: any = await saveApi(formData); // 调用保存接口\r\n\r\n    set(store.data, "apply", Object.assign({}, formData, data, get(store.data, "apply", {})));\r\n    return {\r\n      success: true,\r\n      msg: "保存成功",\r\n    };\r\n  } catch (err: any) {\r\n    return {\r\n      success: false,\r\n      msg: (err.message || err) as string,\r\n    };\r\n  } finally {\r\n    state.value.loadStatus["main"] = false;\r\n  }\r\n};\r\nconst next = () => {\r\n  if (!apply.value?.tid) {\r\n    throw "请保存";\r\n  }\r\n};\r\nconst finish = () => {\r\n  next();\r\n  const list = [];\r\n  list.push({\r\n    ...tableState.row,\r\n    assetClass: tableState.row.assetClass,\r\n    assetName: tableState.resName,\r\n    applyTime: dayjs(new Date()).format("YYYY-MM-DD HH:mm:ss"),\r\n  });\r\n  return list;\r\n};\r\n\r\n// 暴露方法给父组件\r\ndefineExpose({\r\n  save,\r\n  next,\r\n  finish,\r\n});\r\n// 初始化表单规则\r\nconst rule1 = FormUtils.fixJson(\r\n  [\r\n    {\r\n      type: "UTitle",\r\n      title: "基本信息",\r\n    },\r\n    {\r\n      type: "form-text",\r\n      title: "订阅部门",\r\n      field: "orgId",\r\n      props: { options: "org" },\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "form-text",\r\n      title: "统一社会信用代码",\r\n      field: "usci",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "申请类型",\r\n      field: "applyType",\r\n      props: { options: "applyType" },\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "form-text",\r\n      title: "申请日期",\r\n      field: "applyTime",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "使用人姓名",\r\n      field: "userName",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "申请人姓名",\r\n      field: "applicantName",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "使用人联系方式",\r\n      field: "userPhone",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "申请人联系方式",\r\n      field: "applicantPhone",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "使用人邮箱",\r\n      field: "userEmail",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "申请人邮箱",\r\n      field: "applicantEmail",\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "apply-table",\r\n      title: "订阅资源",\r\n      field: "subscribeResources",\r\n      col: {\r\n        span: 24,\r\n      },\r\n      $required: true,\r\n    },\r\n  ],\r\n  "250px"\r\n);\r\nconst rule2 = FormUtils.fixJson(\r\n  [\r\n    {\r\n      type: "UTitle",\r\n      title: "使用信息",\r\n    },\r\n    {\r\n      type: "input",\r\n      field: "averageFrequency",\r\n      title: "服务接口每天使用频次(次)",\r\n      props: {\r\n        placeholder: "请输入服务接口调用频次(平均)次/天",\r\n      },\r\n      $required: true,\r\n      col: {\r\n        span: 12,\r\n      },\r\n    },\r\n    {\r\n      type: "input",\r\n      field: "peakFrequency",\r\n      title: "服务接口使用峰值（次）",\r\n      props: {\r\n        placeholder: "请输入服务接口调用频次(峰值)次/天",\r\n      },\r\n      col: {\r\n        span: 12,\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "ElDatePicker",\r\n      title: "使用时间",\r\n      field: "useTime",\r\n      props: {\r\n        type: "datetimerange",\r\n        showTime: true,\r\n      },\r\n      col: {\r\n        span: 12,\r\n      },\r\n      style: "width: 100%",\r\n    },\r\n    {\r\n      type: "input",\r\n      field: "useDays",\r\n      title: "接口使用期限（天）",\r\n      props: {\r\n        placeholder: "请输入接口使用期限，单位：天",\r\n      },\r\n      col: {\r\n        span: 12,\r\n      },\r\n    },\r\n    {\r\n      type: "input",\r\n      field: "otherRequests"