    return get(store.data, "apply");\n      },\n      set: val => set(store.data, "apply", val)\n    });\n    onMounted(() => {\n      // @TODO 第一步初始化信息，也可调接口更新数据\n      formRules.value = [...rule1, ...rule3];\n      nextTick(() => {\n        formRef.value?.setValue({\n          ...mock,\n          ...apply.value\n        });\n        chooseRes(tableState.list[0]);\n      });\n    });\n    const chooseRes = row => {\n      tableState.check = row.tid;\n      tableState.resName = row.assetName;\n      tableState.assetClass = row.assetClass;\n      tableState.resId = row.tid;\n      tableState.row = row;\n      if (row.assetClass === "api") {\n        formRules.value = [...rule1, ...rule2, ...rule3];\n        nextTick(() => {\n          formRef.value?.setValue({\n            ...mock,\n            ...apply.value\n          });\n        });\n      } else {\n        formRules.value = [...rule1, ...rule3];\n        nextTick(() => {\n          formRef.value?.setValue({\n            ...mock,\n            ...apply.value\n          });\n        });\n      }\n    };\n\n    // 验证表单\n    const validate = async () => {\n      if (!tableState.check) {\n        throw "请选择订阅资源";\n      }\n      if (!formRef.value) {\n        throw new Error("表单未初始化");\n      }\n      await formRef.value.validate();\n    };\n    const saveApi = data => {\n      return new Promise(resolve => {\n        setTimeout(() => {\n          resolve({\n            tid: $common.uuid(),\n            ...data\n          });\n        }, 1000);\n      });\n    };\n    const save = async () => {\n      try {\n        state.value.loadStatus["main"] = true;\n        await validate();\n        // 保存逻辑\n        const formData = formRef.value?.getSaveData() || {};\n        const data = await saveApi(formData); // 调用保存接口\n\n        set(store.data, "apply", Object.assign({}, formData, data, get(store.data, "apply", {})));\n        return {\n          success: true,\n          msg: "保存成功"\n        };\n      } catch (err) {\n        return {\n          success: false,\n          msg: err.message || err\n        };\n      } finally {\n        state.value.loadStatus["main"] = false;\n      }\n    };\n    const next = () => {\n      if (!apply.value?.tid) {\n        throw "请保存";\n      }\n    };\n    const finish = () => {\n      next();\n      const list = [];\n      list.push({\n        ...tableState.row,\n        assetClass: tableState.row.assetClass,\n        assetName: tableState.resName,\n        applyTime: dayjs(new Date()).format("YYYY-MM-DD HH:mm:ss")\n      });\n      return list;\n    };\n\n    // 暴露方法给父组件\n    __expose({\n      save,\n      next,\n      finish\n    });\n    // 初始化表单规则\n    const rule1 = FormUtils.fixJson([{\n      type: "UTitle",\n      title: "基本信息"\n    }, {\n      type: "form-text",\n      title: "订阅部门",\n      field: "orgId",\n      props: {\n        options: "org"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "form-text",\n      title: "统一社会信用代码",\n      field: "usci",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "申请类型",\n      field: "applyType",\n      props: {\n        options: "applyType"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "form-text",\n      title: "申请日期",\n      field: "applyTime",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "使用人姓名",\n      field: "userName",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "申请人姓名",\n      field: "applicantName",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "使用人联系方式",\n      field: "userPhone",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "申请人联系方式",\n      field: "applicantPhone",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "使用人邮箱",\n      field: "userEmail",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "input",\n      title: "申请人邮箱",\n      field: "applicantEmail",\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "apply-table",\n      title: "订阅资源",\n      field: "subscribeResources",\n      col: {\n        span: 24\n      },\n      $required: true\n    }], "250px");\n    const rule2 = FormUtils.fixJson([{\n      type: "UTitle",\n      title: "使用信息"\n    }, {\n      type: "input",\n      field: "averageFrequency",\n      title: "服务接口每天使用频次(次)",\n      props: {\n        placeholder: "请输入服务接口调用频次(平均)次/天"\n      },\n      $required: true,\n      col: {\n        span: 12\n      }\n    }, {\n      type: "input",\n      field: "peakFrequency",\n      title: "服务接口使用峰值（次）",\n      props: {\n        placeholder: "请输入服务接口调用频次(峰值)次/天"\n      },\n      col: {\n        span: 12\n      },\n      $required: true\n    }, {\n      type: "ElDatePicker",\n      title: "使用时间",\n      field: "useTime",\n      props: {\n        type: "datetimerange",\n        showTime: true\n      },\n      col: {\n        span: 12\n      },\n      style: "width: 100%"\n    }, {\n      type: "input",\n      field: "useDays",\n      title: "接口使用期限（天）",\n      props: {\n        placeholder: "请输入接口使用期限，单位：天"\n      },\n      col: {\n        span: 12\n      }\n    }, {\n      type: "input",\n      field: "otherRequests",\n      title: "其他技术请求",\n      props: {\n        placeholder: "请输入其他技术请求",\n        allowClear: true,\n        maxlength: 64\n      },\n      col: {\n        span: 24\n      }\n    }, {\n      type: "input",\n      field: "applyBasis",\n      title: "申请依据",\n      props: {\n        type: "textarea",\n        placeholder: "填写规范说明：建议填写国家、上级机构下发的政策文件或本级单位政策文件名称、发文机关、文号、具体条目内容等信息，便于提高审核通过率。具体如下内容：依据某个部门印发《文件名称》（文号），引用具体内容。",\n        maxlength: 255,\n        rows: 4\n      },\n      col: {\n        span: 24\n      },\n      $required: true\n    }], "250px");\n    const rule3 = FormUtils.fixJson([{\n      type: "UTitle",\n      title: "数据用途"\n    }, {\n      type: "select",\n      title: "应用系统",\n      field: "appSystem",\n      col: {\n        span: 24\n      },\n      $required: true,\n      placeholder: "请选择应用系统",\n      options: [{\n        label: "广电信号传输调度系统",\n        value: "broadcast_signal_dispatch"\n      }, {\n        label: "广电用户收视分析平台",\n        value: "user_view_analysis"\n      }, {\n        label: "广电内容审核管理系统",\n        value: "content_review_system"\n      }]\n    }, {\n      type: "select",\n      title: "使用范围说明",\n      field: "useScope",\n      col: {\n        span: 12\n      },\n      $required: true,\n      placeholder: "请选择使用范围说明",\n      options: [{\n        label: "内部业务支撑",\n        value: "internal_business"\n      }, {\n        label: "跨部门数据共享",\n        value: "cross_dept_share"\n      }, {\n        label: "对外服务接口",\n        value: "external_service"\n      }]\n    }, {\n      type: "select",\n      title: "应用场景类型",\n      field: "sceneType",\n      col: {\n        span: 12\n      },\n      $required: true,\n      placeholder: "应用场景类型",\n      options: [{\n        label: "数据查询",\n        value: "data_query"\n      }, {\n        label: "统计分析",\n        value: "stat_analysis"\n      }, {\n        label: "业务流程支撑",\n        value: "business_support"\n      }]\n    }, {\n      type: "textarea",\n      title: "办事场景",\n      field: "businessScene",\n      props: {\n        rows: 3\n      },\n      col: {\n        span: 24\n      },\n      $required: true,\n      placeholder: "填写规范说明：订阅使用某项数据资源，用于某个业务场景，实现某种程度的业务成效。示例：使用单位xx，用于xx系统办理xx等业务时，调用xx接口，实现xx，从而减免提交纸质材料。"\n    }, {\n      type: "file-upload",\n      title: "附件信息",\n      field: "attachment",\n      col: {\n        span: 24\n      },\n      $required: false,\n      props: {\n        accept: ".png,.jpg,.jpeg,.svg,.xlsx,.docx,.pdf,.txt",\n        placeholder: "请上传.png,.jpg,.jpeg,.svg,.xlsx,.docx,.pdf,.txt格式文件。"\n      }\n    }], "250px");\n\n    // 完整表单模拟数据（与表单配置的 field 完全对应，广电场景适配）\n    const mock = {\n      // 基本信息模块\n      orgId: "10400",\n      usci: "9111000071780321XQ",\n      // 真实格式的统一社会信用代码（模拟广电相关单位）\n      applyType: "政务服务",\n      // 对应 DictSelect 选项（新增申请，符合 applyType 字典规范）\n      applyTime: dayjs(new Date()).format("YYYY-MM-DD HH:mm:ss"),\n      // 申请日期，符合 DatePicker 格式\n      userName: "叶华",\n      applicantName: "李强",\n      userPhone: "13800138000",\n      applicantPhone: "13900139000",\n      userEmail: "zhangming@nrta.gov.cn",\n      applicantEmail: "liqiang@nrta.gov.cn",\n      subscribeResources: [\n      // 订阅资源表格数据（延续之前广电场景，匹配 apply-table 字段）\n      {\n        radio: "",\n        assetName: "广电全国卫视节目信号传输API",\n        categoryName: "一般题材备案数据目录",\n        assetClass: "API服务",\n        shareType: "内部共享",\n        orgName: "国家广播电视总局信息传输中心",\n        applyStatus: "已订阅"\n      }, {\n        radio: "",\n        assetName: "广电家庭用户收视行为统计数据表",\n        categoryName: "一般题材备案数据目录",\n        assetClass: "数据表",\n        shareType: "仅限广电系统内共享",\n        orgName: "广电网络股份有限公司大数据研究院",\n        applyStatus: "审批中"\n      }],\n      // 使用信息模块\n      averageFrequency: "5000",\n      // 日均使用频次\n      peakFrequency: "10000",\n      // 峰值使用频次\n      useTime: ["2026-02-01 08:00:00", "2027-01-31 18:00:00"],\n      // 时间范围，符合 ElDatePicker datetimerange 格式\n      useDays: "365",\n      // 接口使用期限（天）\n      otherRequests: "希望接口提供超高并发支持，保障节假日信号传输稳定",\n      // 其他技术请求（不超过64字）\n      applyBasis: "依据国家广播电视总局印发《全国广播电视信号传输保障管理办法》（广电发〔2025〕12号），其中第三章第十条明确要求：各级广电单位应保障全国卫视节目信号的稳定传输与数据统计，需调用统一信号传输API与用户收视统计数据。",\n      // 申请依据（符合填写规范，不超过255字）\n\n      // 数据用途模块\n      appSystem: "broadcast_signal_dispatch",\n      // 对应 select 选项（广电信号传输调度系统）\n      useScope: "internal_business",\n      // 对应 select 选项（内部业务支撑）\n      sceneType: "business_support",\n      // 对应 select 选项（业务流程支撑）\n      businessScene: "使用单位为国家广播电视总局广播电视传输中心，用于广电信号传输调度系统办理全国卫视节目信号传输与监控业务时，调用广电全国卫视节目信号传输API与收视行为统计数据表，实现信号传输状态的实时监控与用户收视数据的自动统计，从而减免人工填报传输报表与收视数据的纸质材料，提升业务办理效率80%以上。",\n      // 办事场景（符合填写规范）\n      attachment: [\n      // 附件信息（模拟已上传文件，符合 file-upload 格式）\n      {\n        name: "《广电信号传输API使用申请说明.docx》",\n        url: "https://example.com/attachment/1.docx",\n        size: 204800,\n        type: "docx"\n      }]\n    };\n    const tableState = reactive({\n      check: "",\n      list: [{\n        tid: "1",\n        assetClass: "api",\n        assetName: "广电全国卫视节目信号传输API",\n        categoryName: "一般题材备案数据目录",\n        shareType: "有条件共享",\n        orgName: "电视剧司",\n        applyStatus: "待订阅"\n      }, {\n        tid: "2",\n        assetClass: "table",\n        assetName: "广电家庭用户收视行为统计数据表",\n        categoryName: "一般题材备案数据目录",\n        shareType: "无条件共享",\n        orgName: "电视剧司",\n        applyStatus: "待订阅"\n      }],\n      cols: [{\n        label: "请选择",\n        prop: "radio",\n        align: "center",\n        width: 80\n      }, {\n        label: "资源名称",\n        prop: "assetName",\n        minWidth: 180\n      }, {\n        label: "所属目录",\n        prop: "categoryName",\n        ellipsis: true,\n        minWidth: 120\n      }, {\n        label: "资源类型",\n        prop: "assetClass",\n        width: 120,\n        options: "assetClass"\n      }, {\n        label: "共享属性",\n        prop: "shareType",\n        width: 120\n      }, {\n        label: "来源部门",\n        prop: "orgName",\n        width: 200\n      }, {\n        label: "订阅状态",\n        prop: "applyStatus"\n      }]\n    });\n    return (_ctx, _cache) => {\n      const _component_el_radio = _resolveComponent("el-radio");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_el_text = _resolveComponent("el-text");\n      const _component_data_table = _resolveComponent("data-table");\n      const _component_JsonForm = _resolveComponent("JsonForm");\n      return _openBlock(), _createElementBlock("div",