ve": "setup-const",\n  "storeToRefs": "setup-maybe-ref",\n  "FormUtils": "setup-maybe-ref",\n  "useRegisterStore": "setup-maybe-ref",\n  "get": "setup-maybe-ref",\n  "set": "setup-maybe-ref",\n  "dayjs": "setup-maybe-ref",\n  "formRef": "setup-ref",\n  "formRules": "setup-ref",\n  "store": "setup-maybe-ref",\n  "state": "setup-maybe-ref",\n  "apply": "setup-ref",\n  "chooseRes": "setup-const",\n  "validate": "setup-const",\n  "saveApi": "setup-const",\n  "save": "setup-const",\n  "next": "setup-const",\n  "finish": "setup-const",\n  "rule1": "setup-maybe-ref",\n  "rule2": "setup-maybe-ref",\n  "rule3": "setup-maybe-ref",\n  "mock": "setup-const",\n  "tableState": "setup-reactive-const"\n} */\n__sfc__.__file = "ecdefa750a6c0bdfba7bb1baf1c59c1f.vue"\nreturn __sfc__','/* No <style> tags present */','1','登记订阅申请单',NULL,NULL,0,'2084109831678504960',5);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2020739089332518912','2020738614931570688','register-body','<template>\n  <el-skeleton active :loading="loading">\n    <component :is="currentComponent" ref="comRef" v-bind="currentProps" />\n  </el-skeleton>\n</template>\n\n<script setup lang="ts">\nimport { nextTick, ref } from "vue";\nimport { useRegisterStore } from "@/store";\nimport { storeToRefs } from "pinia";\nimport { set } from "lodash-es";\n\nconst emit = defineEmits<{\n  (e: "finishTriggerFn", type: string | null): void;\n}>();\n\nconst store = useRegisterStore();\nconst { currentComponent, currentProps } = storeToRefs(store);\nconst comRef = ref();\nconst loading = ref(false);\nconst actionPending = ref(false);\n\nconst waitForCurrentComponent = async (actionName: string) => {\n  for (let index = 0; index < 10; index += 1) {\n    await nextTick();\n    if (comRef.value) return comRef.value;\n    await new Promise((resolve) => window.setTimeout(resolve, 30));\n  }\n  throw new Error(`当前步骤页面仍在加载，请稍后再${actionName}`);\n};\n\nconst callCurrentStepMethod = async (fnName: string, actionName: string) => {\n  const component = await waitForCurrentComponent(actionName);\n  if (!(component?.[fnName] instanceof Function)) {\n    throw new Error(`当前步骤暂不支持${actionName}`);\n  }\n  return component[fnName]();\n};\n\nconst customApi = async (\n  fnName: string,\n  callback: () => Promise<string | void>\n): Promise<void> => {\n  if (actionPending.value) return;\n  actionPending.value = true;\n  try {\n    store.setLoadStatus(fnName, true);\n    const finishType = await callback();\n    emit("finishTriggerFn", finishType || fnName);\n  } catch (err: any) {\n    console.error(`执行${fnName}事件异常, 原因:`, err instanceof Error ? err.message : String(err));\n    emit("finishTriggerFn", null);\n    $message.warning(err?.message || err);\n  } finally {\n    store.setLoadStatus(fnName, false);\n    await nextTick();\n    window.setTimeout(() => {\n      actionPending.value = false;\n    }, 120);\n  }\n};\n\nconst saveApi = (): Promise<void> =>\n  customApi("save", async () => {\n    const result: {\n      data?: Record<string, any>;\n      success: boolean;\n      refresh?: () => void;\n      msg?: string;\n    } = await callCurrentStepMethod("save", "保存");\n    if (!result) return;\n    if (result.success === false) {\n      throw new Error(result?.msg || "保存失败");\n    }\n    if (result.refresh && typeof result.refresh === "function") {\n      nextTick(() => result.refresh!());\n    }\n    $message.success(result.msg || "保存成功");\n  });\n\nconst nextApi = (): Promise<void> =>\n  customApi("next", async () => {\n    await callCurrentStepMethod("next", "进入下一步");\n  });\n\nconst finishApi = (): Promise<void> =>\n  customApi("finish", async () => {\n    const data = await callCurrentStepMethod("finish", "完成登记");\n    if (data && !["db", "dbTable"].includes(store.registerClass)) {\n      set(store.data, "finish", data);\n    }\n    if (comRef.value?.commit instanceof Function) {\n      await comRef.value.commit();\n    }\n    if (["db", "dbTable"].includes(store.registerClass)) {\n      return "completed";\n    }\n    store.setCurrentStep(store.state.steps.length);\n    return "finish";\n  });\n\nconst commonApi = (fnName: string): Promise<void> =>\n  customApi(fnName, async () => {\n    await callCurrentStepMethod(fnName, fnName);\n  });\n\nconst handleAction = async (type: string): Promise<void> => {\n  switch (type) {\n    case "save":\n      await saveApi();\n      break;\n    case "next":\n      await nextApi();\n      break;\n    case "finish":\n      await finishApi();\n      break;\n    default:\n      await commonApi(type);\n      break;\n  }\n};\n\ndefineExpose({ handleAction });\n</script>\n\n<style scoped lang="scss"></style>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _resolveDynamicComponent = ___magic__import__(\'vue\', \'resolveDynamicComponent\');\r\nconst _mergeProps = ___magic__import__(\'vue\', \'mergeProps\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\nconst useRegisterStore = ___magic__import__(\'@/store\', \'useRegisterStore\');\nconst storeToRefs = ___magic__import__(\'pinia\', \'storeToRefs\');\nconst set = ___magic__import__(\'lodash-es\', \'set\');\nconst __sfc__ = _defineComponent({\n  __name: \'dfebccc3fd5b4612ca81544f980ef903\',\n  emits: ["finishTriggerFn"],\n  setup(__props, {\n    expose: __expose,\n    emit: __emit\n  }) {\n    const emit = __emit;\n    const store = useRegisterStore();\n    const {\n      currentComponent,\n      currentProps\n    } = storeToRefs(store);\n    const comRef = ref();\n    const loading = ref(false);\n    const actionPending = ref(false);\n    const waitForCurrentComponent = async actionName => {\n      for (let index = 0; index < 10; index += 1) {\n        await nextTick();\n        if (comRef.value) return comRef.value;\n        await new Promise(resolve => window.setTimeout(resolve, 30));\n      }\n      throw new Error(`当前步骤页面仍在加载，请稍后再${actionName}`);\n    };\n    const callCurrentStepMethod = async (fnName, actionName) => {\n      const component = await waitForCurrentComponent(actionName);\n      if (!(component?.[fnName] instanceof Function)) {\n        throw new Error(`当前步骤暂不支持${actionName}`);\n      }\n      return component[fnName]();\n    };\n    const customApi = async (fnName, callback) => {\n      if (actionPending.value) return;\n      actionPending.value = true;\n      try {\n        store.setLoadStatus(fnName, true);\n        const finishType = await callback();\n        emit("finishTriggerFn", finishType || fnName);\n      } catch (err) {\n        console.error(`执行${fnName}事件异常, 原因:`, err instanceof Error ? err.message : String(err));\n        emit("finishTriggerFn", null);\n        $message.warning(err?.message || err);\n      } finally {\n        store.setLoadStatus(fnName, false);\n        await nextTick();\n        window.setTimeout(() => {\n          actionPending.value = false;\n        }, 120);\n      }\n    };\n    const saveApi = () => customApi("save", async () => {\n      const result = await callCurrentStepMethod("save", "保存");\n      if (!result) return;\n      if (result.success === false) {\n        throw new Error(result?.msg || "保存失败");\n      }\n      if (result.refresh && typeof result.refresh === "function") {\n        nextTick(() => result.refresh());\n      }\n      $message.success(result.msg || "保存成功");\n    });\n    const nextApi = () => customApi("next", async () => {\n      await callCurrentStepMethod("next", "进入下一步");\n    });\n    const finishApi = () => customApi("finish", async () => {\n      const data = await callCurrentStepMethod("finish", "完成登记");\n      if (data && !["db", "dbTable"].includes(store.registerClass)) {\n        set(store.data, "finish", data);\n      }\n      if (comRef.value?.commit instanceof Function) {\n        await comRef.value.commit();\n      }\n      if (["db", "dbTable"].includes(store.registerClass)) {\n        return "completed";\n      }\n      store.setCurrentStep(store.state.steps.length);\n      return "finish";\n    });\n    const commonApi = fnName => customApi(fnName, async () => {\n      await callCurrentStepMethod(fnName, fnName);\n    });\n    const handleAction = async type => {\n      switch (type) {\n        case "save":\n          await saveApi();\n          break;\n        case "next":\n          await nextApi();\n          break;\n        case "finish":\n          await finishApi();\n          break;\n        default:\n          await commonApi(type);\n          break;\n      }\n    };\n    __expose({\n      handleAction\n    });\n    return (_ctx, _cache) => {\n      const _component_el_skeleton = _resolveComponent("el-skeleton");\n      return _openBlock(), _createBlock(_component_el_skeleton, {\n        active: "",\n        loading: loading.value\n      }, {\n        default: _withCtx(() => [(_openBlock(), _createBlock(_resolveDynamicComponent(_unref(currentComponent)), _mergeProps({\n          ref_key: "comRef",\n          ref: comRef\n        }, _unref(currentProps)), null, 16 /* FULL_PROPS */))]),\n        _: 1 /* STABLE */\n      }, 8 /* PROPS */, ["loading"]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "nextTick": "setup-const",\n  "ref": "setup-const",\n  "useRegisterStore": "setup-maybe-ref",\n  "storeToRefs": "setup-maybe-ref",\n  "set": "setup-maybe-ref",\n  "emit": "setup-const",\n  "store": "setup-maybe-ref",\n  "currentComponent": "setup-maybe-ref",\n  "currentProps": "setup-maybe-ref",\n  "comRef": "setup-ref",\n  "loading": "setup-ref",\n  "actionPending": "setup-ref",\n  "waitForCurrentComponent": "setup-const",\n  "callCurrentStepMethod": "setup-const",\n  "customApi": "setup-const",\n  "saveApi": "setup-const",\n  "nextApi": "setup-const",\n  "finishApi": "setup-const",\n  "commonApi": "setup-const",\n  "handleAction": "setup-const"\n} */\n__sfc__.__file = "dfebccc3fd5b4612ca81544f980ef903.vue"\nreturn __sfc__','/* No <style> tags present */','1','登记中间件',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2004521750421377024','1998313128624459776','register-catalog','<template>\n  <div class="catalog-register-layout">\n    <LeftSelect\n      v-model="currentDid"\n      title="数据目录列表"\n      icon="catalog"\n      :list="leftList"\n      :field-name="{ title: \'catalogName\' }"\n      @add="(item) => handleAction(\'add\', item)"\n      @delete="(item) => handleAction(\'delete\', item)"\n      @select="(item) => handleAction(\'select\', item)"\n    />\n\n    <div class="catalog-register-main">\n      <el-alert\n        v-if="loadError"\n        class="catalog-register-alert"\n        type="warning"\n        show-icon\n        :closable="false"\n        :title="loadError"\n      />\n\n      <div v-if="currentDid" class="catalog-register-content" :aria-busy="loading || undefined">\n        <LoadingState\n          v-if="loading"\n          type="table"\n          compact\n          class="catalog-register-loading"\n          title="正在读取目录和字段信息"\n        />\n        <div :class="[\'catalog-register-fields\', { \'is-loading\': loading }]">\n          <JsonForm ref="formRef" class="catalog-register-form" bordered :rules="formRules">\n            <template #toolbar>\n              <el-popconfirm\n                title="给未填写的必填项填充默认值？"\n                confirm-button-text="确认"\n                cancel-button-text="取消"\n                @confirm="handleFillDefaults"\n              >\n                <template #reference>\n                  <el-button plain>\n                    <template #icon><Icon icon="apply1" /></template>\n                    快捷填充\n                  </el-button>\n                </template>\n              </el-popconfirm>\n            </template>\n          </JsonForm>\n          <v-table ref="colRef" :options="tableOptions" show-operation editable>\n          <template #toolbarButtons>\n            <u-title name="数据项" style="padding: 4px 0">\n              <div class="flex gap-2">\n                <el-button\n                  type="primary"\n                  plain\n                  class="ml-2"\n                  icon="aim"\n                  @click="handleAction(\'智能对标\')"\n                >\n                  智能对标\n                </el-button>\n                <el-progress\n                  v-if="percentage.show"\n                  class="w-400px"\n                  striped\n                  :stroke-width="10"\n                  :percentage="percentage.value"\n                />\n              </div>\n            </u-title>\n          </template>\n          <template #colName_default="{ row }">\n            <el-input v-model="row.colName" placeholder="请输入">\n              <template #prefix>\n                <Icon\n                  v-if="row.isPk"\n                  style="color: var(--el-color-warning); transform: rotate(35deg)"\n                  icon="el-icon-key"\n                />\n              </template>\n            </el-input>\n            <div><el-text type="info">{{ row.colEn }}</el-text></div>\n          </template>\n          <template #colType_default="{ row }">\n            <dict-label v-model="row.colType" options="colType" />\n          </template>\n          <template #colType_edit="{ row }">\n            <dict-select v-model="row.colType" options="colType" />\n          </template>\n          <template #dataStandardId="{ row }">\n            <dict-label :model-value="row.dataStandardId" options="dataStandard" />\n          </template>\n          <template #dataStandardId_edit="{ row }">\n            <dict-select\n              v-model="row.dataStandardId"\n              options="dataStandard"\n              placeholder="请选择数据标准"\n            />\n          </template>\n          <template #qualityRule="{ row }">\n            <div class="flex-center gap-2">\n              <dict-select\n                v-model="row.qualityRule"\n                options="qualityRule"\n                placeholder="默认空白"\n                multiple\n                collapse-tags\n                collapse-tags-tooltip\n                :max-collapse-tags="1"\n                tag-type="primary"\n                multiple-to-str\n              />\n            </div>\n          </template>\n          <template #codeTableId="{ row }">\n            <div class="flex-x-between gap-1">\n              <el-checkbox v-model="row.enableCodeTable" :label="\'\'" />\n              <dict-select\n                v-if="row.enableCodeTable"\n                v-model="row.codeTableId"\n                options="codeTable"\n              />\n            </div>\n          </template>\n          </v-table>\n        </div>\n      </div>\n\n      <div v-else class="catalog-register-empty">\n        <Empty />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang="ts">\nimport { ref, computed, reactive, nextTick, onMounted } from "vue";\nimport { useRegisterStore } from "@/store";\nimport { get, isString, set } from "lodash-es";\n\nconst loading = ref(false);\nconst loadError = ref("");\nconst formRef = ref();\nconst colRef = ref();\nconst formRules = ref([]);\nconst store = useRegisterStore();\nconst currentDid = ref("");\nconst formReady = ref(false);\nconst catalogLoadKey = ref("");\nconst percentage = reactive({ value: 0, show: false });\n\nconst app = computed(() => get(store.data, "app", {}));\nconst catalogs = computed({\n  get: () => {\n    if (!get(store.data, "catalog")) set(store.data, "catalog", []);\n    return get(store.data, "catalog", []);\n  },\n  set: (val) => set(store.data, "catalog", val),\n});\nconst tables = computed({\n  get: () => {\n    if (!get(store.data, "table")) set(store.data, "table", []);\n    return get(store.data, "table", []);\n  },\n  set: (val) => set(store.data, "table", val),\n});\nconst currentCatalog = computed(() =>\n  catalogs.value.find((item) => item.did === currentDid.value) || {}\n);\nconst leftList = computed(() => catalogs.value || []);\n\nconst normalizeCatalogs = () => {\n  const normalized = (catalogs.value || []).filter(Boolean).map((item) => ({\n    ...item,\n    did: item.did || item.tid || $common.uuid(),\n  }));\n  catalogs.value = normalized;\n  return normalized;\n};\n\nconst initData = computed(() => {\n  const value: Record<string, any> = {\n    orgId: $user.orgId,\n    manageUnit: $user.orgId,\n    concatName: $user.realName,\n    concatPhone: $user.phone,\n  };\n  if (app.value.tid) value.appId = app.value.tid;\n  return value;\n});\n\nconst getTableCols = async (catalog: Record<string, any>) => {\n  const sourceTable = tables.value.find(\n    (row) => (row.tid || row.tableId) === catalog.sourceTableId\n  );\n  const params = {\n    tid: catalog.sourceTableId,\n    dbId: catalog.dbId || sourceTable?.dbId || sourceTable?.datasourceId,\n    tableName:\n      catalog.sourceTableName ||\n      sourceTable?.tableName ||\n      sourceTable?.tableNameEn,\n  };\n  try {\n    return (await $common.get("/dst/database/metadata/columns", params)) || [];\n  } catch (error: any) {\n    $message.warning(error?.message || "数据表字段加载失败");\n    return [];\n  }\n};\n\nconst toCatalogItems = (columns: any[] = []) =>\n  columns.map((column, index) => ({\n    colName: column.columnComment || column.columnNameCn || column.columnName || `字段${index + 1}`,\n    colEn: column.columnName || column.columnNameEn || "",\n    colType: column.columnType || column.dataType || "varchar",\n    colLength: Number(column.length || column.columnLength || column.precisionLength || 0) || undefined,\n    isPk: column.primaryKey ? "1" : "0",\n    isNullable: column.nullable === false || column.nullable === 0 || column.nullable === "0" ? "0" : "1",\n    sourceTableColumnId: column.tid || column.id || column.columnId || "",\n    enableCodeTable: 0,\n  }));\n\nconst detailApi = (tid: string) =>\n  Promise.all([\n    $common.post("/dst/catalog/detail", { tid }),\n    $common.post("/dst/catalog/catalog-items/list", { tid }),\n  ]);\n\nconst applyCatalogItems = async (rows: any[] = []) => {\n  await nextTick();\n  colRef.value?.setData?.(rows);\n  await colRef.value?.loadData?.(rows);\n};\n\nconst selectCatalog = async (item: any) => {\n  if (!item) return;\n  if (!item.did) item.did = item.tid || $common.uuid();\n  currentDid.value = item.did;\n  if (!formReady.value) return;\n  const loadKey = `${item.did}:${item.tid || "new"}`;\n  if (loading.value && catalogLoadKey.value === loadKey) return;\n  catalogLoadKey.value = loadKey;\n  formRef.value?.resetFields?.();\n  loadError.value = "";\n\n  loading.value = true;\n  try {\n    await nextTick();\n    if (item.tid) {\n      const [data, catalogItems] = await detailApi(item.tid);\n      await nextTick();\n      formRef.value?.setValue?.(data || {});\n      await applyCatalogItems(catalogItems || []);\n      return;\n    }\n\n    const catalog = catalogs.value.find((row) => row.did === item.did) || {};\n    formRef.value?.setValue?.({ ...catalog, ...initData.value });\n    await applyCatalogItems(catalog.catalogItems || []);\n    if (!catalog.sourceTableId) return;\n    if (catalog.catalogItems?.length) return;\n\n    const columns = await getTableCols(catalog);\n    const catalogItems = toCatalogItems(columns);\n    catalog.catalogItems = catalogItems;\n    await applyCatalogItems(catalogItems);\n  } catch (error: any) {\n    loadError.value = error?.message || "生成目录数据项失败，请稍后重试";\n    await applyCatalogItems([]);\n  } finally {\n    if (catalogLoadKey.value === loadKey) loading.value = false;\n  }\n};\n\nconst handleAction = (type: string, item?: any) => {\n  switch (type) {\n    case "init": {\n      const list = normalizeCatalogs();\n      if (!list.length) {\n        const catalog = { did: $common.uuid(), catalogName: "待登记目录" };\n        catalogs.value.push(catalog);\n        currentDid.value = catalog.did;\n      } else {\n        const current = list.find((row) => row.did === currentDid.value) || list[0];\n        currentDid.value = current.did;\n      }\n      break;\n    }\n    case "add": {\n      const catalog = { did: $common.uuid(), catalogName: "待登记目录" };\n      catalogs.value.push(catalog);\n      currentDid.value = catalog.did;\n      nextTick(() => selectCatalog(catalog));\n      break;\n    }\n    case "delete":\n      catalogs.value = catalogs.value.filter((row) => row.did !== item.did);\n      tables.value = tables.value.filter((row) => item.sourceTableId !== row.tid);\n      if (currentDid.value === item.did) {\n        const next = catalogs.value[0];\n        currentDid.value = next?.did || "";\n        if (next) nextTick(() => selectCatalog(next));\n      }\n      break;\n    case "select":\n      selectCatalog(item);\n      break;\n    case "update": {\n      const index = catalogs.value.findIndex((row) => row.did === currentDid.value);\n      if (index === -1) catalogs.value.push({ did: currentDid.value, ...item });\n      else catalogs.value.splice(index, 1, { ...catalogs.value[index], ...item });\n      break;\n    }\n    case "智能对标": {\n      percentage.show = true;\n      percentage.value = 0;\n      const rows = colRef.value?.getData?.() || [];\n      rows.forEach((row) => {\n        if (["国籍"].includes(row.colName)) row.codeTableId = row.colName;\n        if (row.codeTableId) row.enableCodeTable = true;\n        if (["姓名", "国籍", "证件号码", "入境日期"].includes(row.colName)) {\n          row.dataStandardId = row.colName;\n        }\n        if (["姓名", "国籍", "证件号码", "主键"].includes(row.colName) || row.isNullable === "1") {\n          row.qualityRule = "数据空值校验";\n        }\n      });\n      window.setTimeout(() => { percentage.value = 50; }, 100);\n      window.setTimeout(() => {\n        percentage.value = 100;\n        colRef.value?.setData?.(rows);\n        window.setTimeout(() => { percentage.show = false; }, 500);\n      }, 300);\n      break;\n    }\n  }\n};\n\nonMounted(async () => {\n  // 先初始化左侧目录，表单和数据表始终挂载，加载骨架仅覆盖显示。\n  handleAction("init");\n  loading.value = true;\n  try {\n    const rules = (await $form.get("登记目录")) || [];\n    for (const rule of store.state.updateFormRule || []) {\n      if (!rule.field) continue;\n      const index = rules.findIndex((item) => item.field === rule.field);\n      if (index === -1) continue;\n      const finalProps = Object.assign(get(rules[index], "props", {}), rule.props || {});\n      Object.assign(rules[index], rule);\n      set(rules[index], "props", finalProps);\n    }\n    formRules.value = rules;\n    await nextTick();\n    formRef.value?.api?.display?.(true, ["appId", "dbId"]);\n    formReady.value = true;\n  } catch (error: any) {\n    console.error("目录登记表单加载失败", error);\n    loadError.value = error?.message || "目录登记表单加载失败，请稍后重试";\n  } finally {\n    loading.value = false;\n  }\n  const current = catalogs.value.find((item) => item.did === currentDid.value);\n  if (current) await selectCatalog(current);\n});\n\nconst handleFillDefaults = () => {\n  const currentData = formRef.value?.getSaveData?.() || {};\n  const defaultValues: Record<string, any> = {};\n  formRules.value.forEach((rule: any) => {\n    if (!rule.field || rule.display === false || !rule.$required) return;\n    const currentValue = get(currentData, rule.field);\n    if (currentValue !== undefined && currentValue !== null && currentValue !== "") return;\n    if (rule.type !== "dict-select") return;\n    const optionsKey = rule.props?.options;\n    const options = isString(optionsKey) ? $dict.getDictItems(optionsKey) : optionsKey;\n    if (options?.length) defaultValues[rule.field] = options[0].value;\n  });\n  if (Object.keys(defaultValues).length) {\n    formRef.value?.setValue?.(defaultValues);\n    $message.success(`已填充 ${Object.keys(defaultValues).length} 个字段的默认值`);\n  } else {\n    $message.info("没有需要填充的必填项字段");\n  }\n};\n\nconst saveApi = (data: Record<string, any>) => {\n  const { catalogItems, ...props } = data;\n  return $common.post("/dst/catalog/saveOrUp