s ease, box-shadow 0.16s ease;\n\n  :deep(.svg-icon) {\n    width: 15px;\n    height: 15px;\n  }\n\n  span {\n    color: #667085;\n  }\n\n  strong {\n    color: inherit;\n    font-size: 12px;\n    font-weight: 700;\n  }\n\n  small {\n    color: #98a2b3;\n    font-size: 11px;\n  }\n\n  &:hover:not(:disabled) {\n    border-color: currentColor;\n    background: #f8fafc;\n    box-shadow: 0 2px 8px rgba(16, 24, 40, 0.08);\n  }\n\n  &:disabled {\n    cursor: default;\n    opacity: 0.72;\n  }\n\n  &.is-danger {\n    color: #d92d20;\n    border-color: #fecdca;\n    background: #fffbfa;\n  }\n\n  &.is-warning {\n    color: #b54708;\n    border-color: #fedf89;\n    background: #fffaeb;\n  }\n\n  &.is-success {\n    color: #039855;\n    border-color: #abefc6;\n    background: #f6fef9;\n  }\n}\n\n.review-issue-popover-content {\n  display: grid;\n  gap: 7px;\n  max-height: 320px;\n  overflow: auto;\n}\n\n.review-issue-popover-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding-bottom: 7px;\n  border-bottom: 1px solid #eaecf0;\n\n  strong {\n    color: #1d2939;\n    font-size: 13px;\n  }\n\n  span {\n    padding: 2px 6px;\n    border-radius: 5px;\n    color: #667085;\n    font-size: 11px;\n    background: #f2f4f7;\n  }\n}\n\n.review-issue-popover-item {\n  display: grid;\n  grid-template-columns: 38px minmax(0, 1fr);\n  gap: 8px;\n  width: 100%;\n  padding: 8px;\n  border: 1px solid #eaecf0;\n  border-radius: 7px;\n  text-align: left;\n  background: #fff;\n  cursor: pointer;\n\n  &:hover {\n    border-color: #b2ccff;\n    background: #f8fbff;\n  }\n\n  em {\n    align-self: start;\n    padding: 2px 5px;\n    border-radius: 4px;\n    font-size: 11px;\n    font-style: normal;\n    font-weight: 700;\n  }\n\n  &.is-error em {\n    color: #d92d20;\n    background: #fff1f0;\n  }\n\n  &.is-warning em {\n    color: #b54708;\n    background: #fffaeb;\n  }\n\n  span {\n    min-width: 0;\n  }\n\n  strong,\n  small {\n    display: block;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  strong {\n    color: #344054;\n    font-size: 12px;\n    line-height: 18px;\n  }\n\n  small {\n    margin-top: 1px;\n    color: #667085;\n    font-size: 11px;\n    line-height: 16px;\n  }\n}\n\n@media (max-width: 1200px) {\n  .data-source-status-card .metric-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 640px) {\n  .data-source-status-card .metric-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.status-detail-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(330px, 0.65fr);\n  gap: 12px;\n  margin-top: 14px;\n  align-items: stretch;\n}\n\n.status-detail-grid .pending-registration-card {\n  min-width: 0;\n  margin: 0;\n  flex-direction: column;\n  align-items: stretch;\n  justify-content: flex-start;\n}\n\n.status-detail-grid .pending-registration-copy {\n  min-width: 0;\n}\n\n.status-detail-grid .pending-table-list {\n  justify-content: flex-start;\n  margin-top: 12px;\n}\n\n.status-issue-panel {\n  position: static;\n  overflow: hidden;\n  box-shadow: none;\n}\n\n.status-issue-panel .issue-nav-list {\n  max-height: 260px;\n  min-height: 0;\n  overflow: auto;\n}\n\n.status-issue-panel .review-panel-loading {\n  min-height: 160px;\n}\n\n.data-table-information-card {\n  margin-top: 14px;\n  padding: 16px;\n  border-color: #dbe3ee;\n  border-radius: 10px;\n}\n\n.data-table-workbench .data-table-information-card {\n  margin-top: 0;\n}\n\n.review-table {\n  width: 100%;\n  border: 1px solid #e4eaf2;\n  border-radius: 8px;\n  overflow: hidden;\n\n  :deep(.el-table__header th) {\n    height: 42px;\n    color: #475467;\n    font-size: 12px;\n    font-weight: 650;\n    background: #f8fafc;\n  }\n\n  :deep(.el-table__row td) {\n    padding: 10px 0;\n  }\n\n  :deep(.el-table__expanded-cell) {\n    padding: 0 16px 16px !important;\n    background: #fcfdff;\n  }\n\n  :deep(.review-expand-control-column) {\n    width: 0 !important;\n    min-width: 0 !important;\n    max-width: 0 !important;\n    padding: 0 !important;\n    border: 0 !important;\n\n    .cell,\n    .el-table__expand-icon {\n      display: none !important;\n    }\n  }\n}\n\n.review-table-name {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  min-width: 0;\n\n  > div {\n    min-width: 0;\n  }\n\n  strong,\n  small {\n    display: block;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  strong {\n    color: #1d2939;\n    font-size: 13px;\n    line-height: 20px;\n  }\n\n  strong.is-name-missing,\n  small {\n    color: #98a2b3;\n  }\n\n  small {\n    font-family: Consolas, "Courier New", monospace;\n    font-size: 11px;\n    line-height: 17px;\n  }\n}\n\n.review-table-expand-trigger {\n  display: inline-flex;\n  align-items: center;\n  min-width: 0;\n  gap: 4px;\n  padding: 0;\n  border: 0;\n  color: #1d2939;\n  text-align: left;\n  background: transparent;\n  cursor: pointer;\n\n  :deep(.svg-icon),\n  :deep(.el-icon) {\n    flex: 0 0 auto;\n    color: #344054;\n    font-size: 12px;\n    transition: color 0.16s ease, transform 0.16s ease;\n  }\n\n  strong {\n    min-width: 0;\n    transition: color 0.16s ease, text-decoration-color 0.16s ease;\n  }\n\n  &:hover,\n  &:focus-visible {\n    outline: none;\n\n    strong {\n      color: #155eef;\n      text-decoration: underline;\n      text-decoration-thickness: 1px;\n      text-underline-offset: 3px;\n    }\n\n    :deep(.svg-icon),\n    :deep(.el-icon) {\n      color: #155eef;\n    }\n  }\n}\n\n.review-table-stacked,\n.review-table-tags,\n.review-table-times {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 4px;\n  min-width: 0;\n}\n\n.review-table-tags {\n  flex-direction: row;\n  flex-wrap: wrap;\n}\n\n.review-table-stacked small,\n.review-table-times span {\n  overflow: hidden;\n  max-width: 100%;\n  color: #667085;\n  font-size: 11px;\n  line-height: 17px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.review-table-field-link {\n  padding: 0;\n  border: 0;\n  color: #155eef;\n  font-size: 11px;\n  line-height: 17px;\n  text-decoration: underline;\n  text-decoration-style: dotted;\n  text-underline-offset: 3px;\n  background: transparent;\n  cursor: pointer;\n\n  &:hover {\n    color: #004eea;\n    text-decoration-style: solid;\n  }\n\n  &:focus-visible {\n    outline: 2px solid rgba(21, 94, 239, 0.25);\n    outline-offset: 2px;\n    border-radius: 3px;\n  }\n}\n\n.table-issue-panel {\n  overflow: hidden;\n}\n\n.pending-registration-in-table {\n  margin: 12px 0 0;\n  padding: 12px 14px;\n  border-color: #fde3ad;\n  border-radius: 8px;\n  background: #fffaf0;\n}\n\n.pending-registration-in-table .pending-registration-copy {\n  min-width: 0;\n}\n\n.pending-registration-in-table .pending-registration-copy p {\n  margin-top: 3px;\n}\n\n.pending-registration-in-table .pending-table-list {\n  justify-content: flex-end;\n}\n\n.data-table-toolbar {\n  margin: 0 0 12px;\n  padding: 0;\n}\n\n.data-table-section-head {\n  margin-top: 12px;\n  margin-bottom: 0;\n  padding: 10px 12px;\n  border: 1px solid #e4eaf2;\n  border-bottom: 0;\n  border-radius: 7px 7px 0 0;\n  background: #f8fafc;\n}\n\n.data-table-section-content {\n  padding: 0;\n  border: 1px solid #e4eaf2;\n  border-radius: 0 0 7px 7px;\n}\n\n.data-table-section-content > .review-section-loading,\n.data-table-section-content > .business-empty {\n  margin: 0 16px;\n}\n\n.data-table-section-content > .nested-collapse {\n  border: 0;\n}\n\n/* 表级审查项保留“可展开卡片”而非刚性表格：长表名、状态标签和运行指标可以分别换行，\n * 同时仍保持每张表的审查详情与标题在同一个操作单元中。 */\n.nested-collapse :deep(.el-collapse-item__header) {\n  min-height: 92px;\n  padding: 8px 14px;\n}\n\n.table-title-row {\n  grid-template-columns: 30px minmax(156px, 0.72fr) minmax(460px, 1.7fr);\n  align-items: center;\n}\n\n.table-title-main {\n  align-items: stretch;\n  justify-content: center;\n  gap: 6px !important;\n}\n\n.table-title-main > .table-title-tags {\n  justify-content: flex-end;\n  flex-wrap: wrap;\n  row-gap: 4px;\n}\n\n.table-runtime-strip {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, max-content));\n  justify-content: end;\n  column-gap: 12px;\n  row-gap: 4px;\n  min-width: 0;\n  color: #667085;\n  font-size: 11px;\n  line-height: 18px;\n\n  &.is-pending {\n    color: #98a2b3;\n  }\n}\n\n.table-runtime-item {\n  display: inline-flex;\n  align-items: center;\n  min-width: 0;\n  gap: 4px;\n  white-space: nowrap;\n}\n\n.table-runtime-label {\n  flex: 0 0 auto;\n  color: #98a2b3;\n}\n\n.table-runtime-item strong {\n  max-width: 176px;\n  min-width: 0;\n  overflow: hidden;\n  color: #475467;\n  font-size: 11px;\n  font-weight: 600;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.table-runtime-status :deep(.el-tag) {\n  flex: 0 0 auto;\n}\n\n.metric-registration-pie-popover {\n  display: grid;\n  min-width: 378px;\n  gap: 11px;\n  padding: 5px;\n}\n\n/* 标题与说明单独归纳，饼图和图例左右并置，保证数量、名称、占比都一眼可读。 */\n.metric-registration-pie-head {\n  padding: 2px 2px 10px;\n}\n\n.metric-registration-pie-head > span {\n  display: inline-flex;\n  align-items: center;\n  height: 25px;\n  padding: 0 8px;\n  border-radius: 999px;\n  color: #155eef;\n  font-size: 12px;\n  font-weight: 700;\n  background: #eff6ff;\n}\n\n.metric-registration-pie-overview {\n  display: grid;\n  grid-template-columns: 146px minmax(0, 1fr);\n  align-items: center;\n  gap: 14px;\n}\n\n.metric-registration-pie-chart {\n  display: grid;\n  width: 146px;\n  height: 146px;\n  place-items: center;\n}\n\n.metric-registration-pie-chart .metric-hover-donut {\n  width: 138px;\n  height: 138px;\n}\n\n.metric-registration-pie-chart .metric-hover-donut::after {\n  inset: 36px;\n}\n\n.metric-registration-pie-total {\n  position: relative;\n  z-index: 1;\n  display: grid;\n  justify-items: center;\n  gap: 4px;\n  line-height: 1;\n}\n\n.metric-registration-pie-total small {\n  color: #667085;\n  font-size: 10px;\n  font-weight: 500;\n}\n\n.metric-registration-pie-total strong {\n  color: #1d2939;\n  font-size: 19px;\n  font-weight: 750;\n}\n\n.metric-registration-pie-legend {\n  display: grid;\n  gap: 8px;\n  min-width: 0;\n}\n\n.metric-registration-pie-legend-item {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  grid-template-rows: 18px 13px 5px;\n  column-gap: 8px;\n  row-gap: 2px;\n  min-width: 0;\n}\n\n.metric-registration-pie-legend-label {\n  display: inline-flex;\n  min-width: 0;\n  align-items: center;\n  gap: 6px;\n}\n\n.metric-registration-pie-legend-label i {\n  width: 8px;\n  height: 8px;\n  flex: 0 0 auto;\n  border-radius: 50%;\n  background: #1677ff;\n}\n\n.metric-registration-pie-legend-label i.is-deferred { background: #98a2b3; }\n.metric-registration-pie-legend-label i.is-warning { background: #f79009; }\n.metric-registration-pie-legend-label i.is-success { background: #12b76a; }\n\n.metric-registration-pie-legend-label b {\n  overflow: hidden;\n  color: #475467;\n  font-size: 12px;\n  font-weight: 600;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.metric-registration-pie-legend-item > strong {\n  color: #1d2939;\n  font-size: 13px;\n  line-height: 18px;\n  white-space: nowrap;\n}\n\n.metric-registration-pie-legend-item > small {\n  grid-column: 1 / -1;\n  color: #98a2b3;\n  font-size: 10px;\n  line-height: 13px;\n}\n\n.metric-registration-pie-track {\n  grid-column: 1 / -1;\n  height: 5px;\n  overflow: hidden;\n  border-radius: 999px;\n  background: #eef2f6;\n}\n\n.metric-registration-pie-track > i {\n  display: block;\n  height: 100%;\n  border-radius: inherit;\n}\n\n.metric-registration-pie-track > i.is-deferred { background: #98a2b3; }\n.metric-registration-pie-track > i.is-warning { background: #f79009; }\n.metric-registration-pie-track > i.is-success { background: #12b76a; }\n.metric-registration-pie-track > i.is-business { background: #1677ff; }\n\n.metric-hover-chart-only {\n  display: grid;\n  min-width: 224px;\n  min-height: 224px;\n  place-items: center;\n  padding: 8px;\n}\n\n.metric-hover-donut {\n  position: relative;\n  display: inline-flex;\n  width: 190px;\n  height: 190px;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  box-shadow: inset 0 0 0 1px rgba(16, 24, 40, 0.06);\n}\n\n.metric-hover-donut::after {\n  position: absolute;\n  inset: 34px;\n  border-radius: 50%;\n  background: #fff;\n  box-shadow: 0 0 0 1px #f1f4f8;\n  content: "";\n}\n\n.metric-hover-donut span {\n  position: relative;\n  z-index: 1;\n  color: #1d2939;\n  font-size: 18px;\n  font-weight: 700;\n  line-height: 1;\n}\n\n.review-table-preview-dialog :deep(.el-dialog__body) {\n  min-height: 350px;\n}\n\n.review-table-preview-dialog :deep(.el-tabs__content) {\n  min-height: 290px;\n}\n\n.review-table-preview-empty {\n  display: flex;\n  min-height: 278px;\n  align-items: center;\n  justify-content: center;\n}\n\n.metric-detail-popover {\n  display: grid;\n  gap: 12px;\n  padding: 2px;\n}\n\n.metric-field-issue-list,\n.metric-format-list {\n  display: grid;\n  gap: 8px;\n  max-height: 260px;\n  overflow-y: auto;\n}\n\n.metric-field-issue-item {\n  display: grid;\n  gap: 5px;\n  width: 100%;\n  padding: 10px;\n  border: 1px solid #fedf89;\n  border-radius: 7px;\n  text-align: left;\n  background: #fffcf5;\n  cursor: pointer;\n\n  &.is-error { border-color: #fecdca; background: #fffbfa; }\n  &:hover, &:focus-visible { border-color: #84adff; background: #f5f9ff; outline: 2px solid #d1e0ff; }\n  strong, small { overflow-wrap: anywhere; white-space: normal; }\n  strong { color: #344054; font-size: 12px; line-height: 18px; }\n  small { color: #667085; font-size: 11px; line-height: 17px; }\n  span { color: #175cd3; font-size: 11px; }\n}\n\n.metric-field-read-result,\n.metric-format-empty {\n  padding: 12px;\n  border-radius: 7px;\n  color: #027a48;\n  font-size: 12px;\n  line-height: 20px;\n  background: #ecfdf3;\n}\n\n.metric-field-read-result.is-pending,\n.metric-format-empty { color: #667085; background: #f8fafc; }\n\n.metric-format-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 9px 10px;\n  border-radius: 6px;\n  background: #f8fafc;\n  color: #475467;\n  font-size: 12px;\n\n  span { overflow-wrap: anywhere; }\n  strong { flex-shrink: 0; color: #175cd3; font-size: 12px; }\n}\n\n.metric-detail-head,\n.metric-detail-group-title,\n.metric-proportion-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.metric-detail-head {\n  padding: 2px 2px 10px;\n  border-bottom: 1px solid #e4eaf2;\n\n  > div {\n    display: grid;\n    gap: 3px;\n    min-width: 0;\n  }\n\n  strong {\n    color: #1d2939;\n    font-size: 13px;\n  }\n\n  small {\n    overflow: hidden;\n    color: #98a2b3;\n    font-size: 11px;\n    line-height: 15px;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  span {\n    color: #98a2b3;\n    font-size: 11px;\n  }\n}\n\n.metric-detail-group {\n  display: grid;\n  gap: 7px;\n}\n\n.metric-detail-group-title strong {\n  color: #475467;\n  font-size: 12px;\n}\n\n.metric-detail-group-title em {\n  padding: 1px 6px;\n  border-radius: 999px;\n  color: #b54708;\n  font-size: 11px;\n  font-style: normal;\n  background: #fffaeb;\n}\n\n.metric-detail-table-list {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 6px;\n}\n\n.metric-detail-table-list button,\n.table-issue-popover-content button {\n  min-width: 0;\n  border: 1px solid #eaecf0;\n  border-radius: 6px;\n  text-align: left;\n  background: #fff;\n  cursor: pointer;\n}\n\n.metric-detail-table-list button {\n  padding: 7px 8px;\n\n  &:hover,\n  &:focus-visible {\n    border-color: #b2ccff;\n    background: #f8fbff;\n    outline: none;\n  }\n\n  strong,\n  small {\n    display: block;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  strong {\n    color: #344054;\n    font-size: 12px;\n  }\n\n  small {\n    margin-top: 2px;\n    color: #98a2b3;\n    font-size: 10px;\n  }\n}\n\n.metric-detail-empty {\n  color: #98a2b3;\n  font-size: 12px;\n}\n\n.metric-proportion-popover {\n  gap: 15px;\n  padding: 9px 7px;\n}\n\n.metric-proportion-row {\n  display: grid;\n  grid-template-columns: 92px minmax(0, 1fr) 92px;\n  gap: 12px;\n\n  > span,\n  > strong {\n    color: #667085;\n    font-size: 13px;\n    font-weight: 600;\n  }\n\n  > strong {\n    color: #475467;\n    text-align: right;\n  }\n\n  > span {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    white-space: nowrap;\n\n    > i {\n      width: 9px;\n      height: 9px;\n      border-radius: 999px;\n      background: #98a2b3;\n    }\n\n    > i.is-dictionary { background: #7f56d9; }\n    > i.is-business { background: #1677ff; }\n    > i.is-log { background: #12b76a; }\n    > i.is-process { background: #f79009; }\n    > i.is-temporary { background: #64748b; }\n    > i.is-deferred { background: #98a2b3; }\n  }\n}\n\n.metric-proportion-track {\n  height: 14px;\n  overflow: hidden;\n  border-radius: 999px;\n  background: #eef2f6;\n  box-shadow: inset 0 1px 2px rgba(16, 24, 40, 0.06);\n\n  i {\n    display: block;\n    min-width: 0;\n    height: 100%;\n    border-radius: inherit;\n    transition: width 0.2s ease;\n    box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.08);\n  }\n\n  i.is-dictionary { background: #7f56d9; }\n  i.is-business { background: #1677ff; }\n  i.is-log { background: #12b76a; }\n  i.is-process { background: #f79009; }\n  i.is-temporary { background: #64748b; }\n  i.is-deferred { background: #98a2b3; }\n  i.is-success { background: #12b76a; }\n  i.is-warning { background: #f79009; }\n  i.is-danger { background: #f04438; }\n}\n\n.metric-statistics-popover {\n  gap: 14px;\n  padding: 7px 5px;\n}\n\n.metric-statistics-list {\n  display: grid;\n  gap: 10px;\n}\n\n.metric-statistics-row {\n  display: grid;\n  grid-template-columns: 112px minmax(0, 1fr) 82px;\n  align-items: center;\n  gap: 10px;\n\n  > span,\n  > strong {\n    color: #667085;\n    font-size: 12px;\n    line-height: 18px;\n  }\n\n  > strong {\n    color: #344054;\n    font-weight: 600;\n    text-align: right;\n    white-space: nowrap;\n  }\n\n  .metric-proportion-track {\n    height: 10px;\n  }\n}\n\n.metric-general-popover {\n  gap: 10px;\n}\n\n.metric-general-list {\n  display: grid;\n  gap: 5px;\n\n  > button {\n    display: grid;\n    grid-template-columns: 7px minmax(0, 1fr) 13px;\n    align-items: center;\n    gap: 8px;\n    width: 100%;\n    padding: 7px 8px;\n    border: 1px solid #e7ecf3;\n    border-radius: 7px;\n    text-align: left;\n    background: #fff;\n    cursor: pointer;\n    transition: border-color 0.16s ease, background 0.16s ease, transform 0.16s ease;\n\n    &:hover,\n    &:focus-visible {\n      border-color: #b7d1ff;\n      background: #f7faff;\n      outline: none;\n      transform: translateX(1px);\n    }\n\n    > div {\n      display: grid;\n      gap: 2px;\n      min-width: 0;\n    }\n\n    strong,\n    small {\n      overflow: hidden;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n\n    strong {\n      color: #344054;\n      font-size: 12px;\n      font-weight: 650;\n    }\n\n    small {\n      color: #98a2b3;\n      font-size: 10px;\n      line-height: 14px;\n    }\n\n    :deep(.el-icon) {\n      color: #98a2b3;\n      font-size: 12px;\n    }\n  }\n}\n\n.metric-general-row-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 999px;\n  background: #98a2b3;\n\n  &.is-success { background: #12b76a; }\n  &.is-warning { background: #f79009; }\n  &.is-danger { background: #f04438; }\n}\n\n.metric-general-more {\n  padding: 2px 3px 0;\n  color: #98a2b3;\n  font-size: 10px;\n}\n\n.metric-general-empty {\n  padding: 10px 11px;\n  border: 1px dashed #d0d5dd;\n  border-radius: 7px;\n  line-height: 18px;\n  background: #fafbfc;\n}\n\n.metric-related-issues {\n  display: grid;\n  gap: 5px;\n  padding-top: 9px;\n  border-top: 1px solid #eef1f5;\n\n  > div {\n    display: flex;\n    align-i