er: 1px solid #e4e7ec;\n  border-radius: 6px;\n  overflow: hidden;\n\n  :deep(.el-table__cell) {\n    padding: 8px 0;\n  }\n\n  :deep(.el-input__wrapper) {\n    box-shadow: 0 0 0 1px #d0d5dd inset;\n  }\n\n  code {\n    color: #344054;\n    font-family: Consolas, "Courier New", monospace;\n    font-size: 12px;\n  }\n}\n\n.probe-table-list {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.probe-table-item {\n  box-sizing: border-box;\n  width: 100%;\n  min-width: 0;\n  height: auto;\n  margin: 0;\n  padding: 10px 12px;\n  border: 1px solid #e4e7ec;\n  border-radius: 5px;\n  background: #fbfcfe;\n\n  :deep(.el-checkbox__label) {\n    min-width: 0;\n    white-space: normal;\n  }\n\n  span,\n  small,\n  strong {\n    display: block;\n    min-width: 0;\n  }\n\n  strong,\n  .probe-table-name {\n    color: #20273a;\n    font-size: 13px;\n    font-weight: 650;\n  }\n\n  small {\n    margin-top: 3px;\n    overflow: hidden;\n    color: #667085;\n    font-size: 12px;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  &.is-static {\n    display: grid;\n    grid-template-columns: 22px minmax(0, 1fr);\n    align-items: center;\n    gap: 8px;\n  }\n}\n\n.connection-error-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px 24px;\n  margin-bottom: 12px;\n}\n\n.connection-error-meta > div {\n  display: flex;\n  min-width: 0;\n  gap: 8px;\n  line-height: 22px;\n}\n\n.connection-error-meta span {\n  flex: none;\n  color: #667085;\n}\n\n.connection-error-meta strong {\n  min-width: 0;\n  overflow-wrap: anywhere;\n  color: #20273a;\n  font-weight: 600;\n}\n\n.connection-error-detail {\n  box-sizing: border-box;\n  max-height: 52vh;\n  margin: 0;\n  padding: 12px;\n  overflow: auto;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  border: 1px solid #dfe5ec;\n  border-radius: 6px;\n  background: #f8fafc;\n  color: #20273a;\n  font:\n    12px/1.6 Consolas,\n    Monaco,\n    monospace;\n}\n\n@keyfram