-overflow: ellipsis;\n  white-space: nowrap;\n}\n.field-type-cell :deep(.el-tag) {\n  white-space: nowrap;\n}\n\n/*\n * el-popover is teleported to body, so these styles must be global rather\n * than scoped. Keep every time-property option in its own grid row: the\n * previous absolutely positioned checkbox could overlap its description and\n * action text in the compact registration window.\n */\n.field-property-popover {\n  width: 360px !important;\n  max-width: calc(100vw - 24px);\n  max-height: calc(100vh - 24px);\n  padding: 12px !important;\n  overflow-y: auto;\n}\n.field-property-popover .time-property-options {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.field-property-popover .time-property-option.el-checkbox {\n  display: grid;\n  grid-template-columns: 18px minmax(0, 1fr);\n  align-items: start;\n  width: 100%;\n  min-height: 70px;\n  margin: 0;\n  padding: 10px;\n  border-radius: 7px;\n}\n.field-property-popover .time-property-option.el-checkbox:hover {\n  background: #f5f8ff;\n}\n.field-property-popover .time-property-option .el-checkbox__input {\n  position: static;\n  margin: 2px 0 0;\n}\n.field-property-popover .time-property-option .el-checkbox__label {\n  display: block;\n  min-width: 0;\n  padding-left: 8px;\n  white-space: normal;\n}\n.field-property-popover .time-property-option-copy {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 0;\n  line-height: 1.4;\n}\n.field-property-popover .time-property-option-copy small {\n  color: #667085;\n  font-size: 12px;\n  line-height: 18px;\n}\n.field-property-popover .time-property-option-action {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  min-height: 20px;\n  padding-left: 0;\n  gap: 8px;\n}\n.field-property-popover .time-property-option-action strong {\n  width: auto;\n  min-width: 84px;\n  color: #323643;\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 20px;\n}\n@media (max-width: 480px) {\n.field-property-popover {\n    width: calc(100vw - 16px) !important;\n    max-width: calc(100vw - 16px);\n}\n}','1','03.登记数据表',NULL,NULL,0,'2084109831678504960',3);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016026573025120256','1998313128624459776','register-fileCatalog','<template>\r\n  <div style="display: grid; grid-template-columns: 25% 75%" class="pr-5 py-2">\r\n    <LeftSelect\r\n      v-model="currentDid"\r\n      title="数据目录列表"\r\n      icon="fileCatalog"\r\n      :list="leftList"\r\n      :field-name="{ title: \'fileCatalogName\' }"\r\n      @add="(item) => handleAction(\'add\', item)"\r\n      @delete="(item) => handleAction(\'delete\', item)"\r\n      @select="(item) => handleAction(\'select\', item)"\r\n    />\r\n    <div>\r\n      <el-skeleton v-if="currentDid" :loading="loading" animated>\r\n        <JsonForm ref="formRef" bordered :rules="formRules" />\r\n        <v-table\r\n          ref="colRef"\r\n          :options="tableOptions"\r\n          :insert-data="{ colLength: \'255\', colType, isPk: 0, isNullable: 1 }"\r\n          show-operation\r\n          editable\r\n          @btn-click="(params) => handleAction(params.code, params)"\r\n        >\r\n          <template #toolbarButtons>\r\n            <u-title name="数据项" style="padding: 4px 0"></u-title>\r\n          </template>\r\n          <template #isPk="{ row }">\r\n            <el-checkbox v-model="row.isPk" true-value="1" false-value="0"></el-checkbox>\r\n          </template>\r\n          <template #isNullable="{ row }">\r\n            <!--    isNullable为1表示可为空，0表示不能为空    -->\r\n            <el-checkbox v-model="row.isNullable" true-value="0" false-value="1"></el-checkbox>\r\n          </template>\r\n        </v-table>\r\n      </el-skeleton>\r\n\r\n      <div v-else class="flex-x-center">\r\n        <Empty />\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, reactive, nextTick, onMounted } from "vue";\r\nimport { useRegisterStore } from "@/store";\r\nimport { get, set } from "lodash-es";\r\n\r\nconst loading = ref(false);\r\nconst formRef = ref();\r\nconst colRef = ref();\r\nconst formRules = ref([]);\r\nconst store = useRegisterStore();\r\nconst currentDid = ref("");\r\n\r\nconst fileCatalogs = computed({\r\n  get: () => {\r\n    if (!get(store.data, "fileCatalog")) {\r\n      set(store.data, "fileCatalog", []);\r\n    }\r\n    return get(store.data, "fileCatalog", []);\r\n  },\r\n  set: (val) => set(store.data, "fileCatalog", val),\r\n});\r\nconst currentData = computed(() => {\r\n  return fileCatalogs.value.find((el) => el.did === currentDid.value) || {};\r\n});\r\nconst leftList = computed(() => {\r\n  return fileCatalogs.value || [];\r\n});\r\nconst initData = reactive({\r\n  orgId: $user.orgId,\r\n});\r\n\r\nconst colType = computed(\r\n  () => $dict.getDictItems("colType").find((d) => d.label === "字符串型C")?.value\r\n);\r\n\r\n// 初始化表单规则\r\n$form.get("登记文件目录").then((data) => {\r\n  formRules.value = data;\r\n  onMounted(\r\n    nextTick(() => {\r\n      handleAction("init");\r\n    })\r\n  );\r\n});\r\n\r\nconst handleAction = (type: string, item?: any) => {\r\n  switch (type) {\r\n    case "init":\r\n      if (!leftList.value.length) {\r\n        handleAction("add");\r\n      }\r\n      break;\r\n    case "add":\r\n      fileCatalogs.value.push({ did: $common.uuid() });\r\n      break;\r\n    case "delete":\r\n      fileCatalogs.value = fileCatalogs.value.filter((el) => el.did !== item.did);\r\n      break;\r\n    case "select":\r\n      // 刷新右侧数据\r\n      formRef.value?.resetFields();\r\n      if (item.tid) {\r\n        // 请求数据，覆盖数据\r\n        loading.value = true;\r\n        detailApi(item.tid).then((res) => {\r\n          const [data, catalogItems] = res;\r\n          loading.value = false;\r\n          nextTick(() => {\r\n            formRef.value.setValue(data);\r\n            colRef.value.setData(catalogItems || []);\r\n          });\r\n        });\r\n      } else {\r\n        const fileCatalog = fileCatalogs.value.find((el) => el.did === item.did) || {};\r\n        nextTick(() => {\r\n          const init = { ...initData, ...fileCatalog };\r\n          formRef.value?.setValue({ ...init });\r\n          colRef.value?.setData(init.catalogItems || []);\r\n        });\r\n      }\r\n      break;\r\n    case "update": {\r\n      const cache = fileCatalogs.value;\r\n      const i = cache.findIndex((el) => el.did === currentDid.value);\r\n      if (i === -1) {\r\n        cache.push({ did: currentDid.value, ...item });\r\n      } else {\r\n        cache.splice(i, 1, Object.assign({}, cache[i], item));\r\n      }\r\n      break;\r\n    }\r\n  }\r\n};\r\n\r\nconst validate = async (): Promise<boolean> => {\r\n  if (formRef.value) {\r\n    await formRef.value.validate();\r\n  }\r\n  await colRef.value.validate();\r\n\r\n  if ((colRef.value.getData() || []).length === 0) {\r\n    throw "请添加数据项";\r\n  }\r\n};\r\n\r\nconst detailApi = (tid: string) => {\r\n  return Promise.all([\r\n    $common.post("/dst/catalog/detail", { tid }),\r\n    $common.post("/dst/catalog/catalog-items/list", { tid }),\r\n  ]);\r\n};\r\n\r\nconst saveApi = (data: Record<string, any>) => {\r\n  const { catalogItems, ...props } = data;\r\n  return $common.post("/dst/catalog/saveOrUpdate", {\n    tid: currentData.value.tid,\r\n    assetType: "fileCatalog",\r\n    propList: props,\r\n    catalogItems,\r\n  });\r\n};\r\n\r\nconst save = async () => {\r\n  try {\r\n    store.state.loadStatus["main"] = true;\r\n    await validate();\r\n    // 保存逻辑\r\n    const formData = formRef.value?.getSaveData() || {};\r\n    const catalogItems = colRef.value.getData();\r\n\r\n    const data: any = await saveApi({ ...formData, catalogItems }); // 调用保存接口\r\n    const newObj = Object.assign({ catalogItems }, formData, data);\r\n\r\n    // 更新数据目录编码唯一标识符，此编码由后端生成\r\n    const { uuid } = data;\r\n    if (uuid) {\r\n      formRef.value.setValue({ uuid });\r\n    }\r\n\r\n    handleAction("update", newObj);\r\n    return {\r\n      success: true,\r\n      msg: "保存成功",\r\n    };\r\n  } catch (err: any) {\r\n    return {\r\n      success: false,\r\n      msg: (err?.message || err) as string,\r\n    };\r\n  } finally {\r\n    store.state.loadStatus["main"] = false;\r\n  }\r\n};\r\n\r\nconst next = () => {\r\n  if (fileCatalogs.value.some((el) => !el.tid)) {\r\n    throw "请保存";\r\n  }\r\n};\r\n\r\nconst finish = () => {\r\n  next();\r\n  const list = [];\r\n  fileCatalogs.value.forEach((el) => {\r\n    list.push({ ...el, assetType: "fileCatalog" });\r\n  });\r\n  return list;\r\n};\r\n\r\n// 暴露方法\r\ndefineExpose({\r\n  save,\r\n  validate,\r\n  next,\r\n  finish,\r\n});\r\n\r\n// 表格配置\r\nconst tableOptions = reactive({\r\n  cellConfig: {},\r\n  toolbarConfig: {\r\n    slots: {\r\n      buttons: "toolbarButtons",\r\n    },\r\n    buttons: [],\r\n    tools: [\r\n      // {\r\n      //   code: "custom",\r\n      //   icon: "vxe-icon-custom-column",\r\n      //   mode: "text",\r\n      //   status: "primary",\r\n      //   name: "显示列",\r\n      // },\r\n      {\r\n        code: "import",\r\n        icon: "vxe-icon-cloud-upload",\r\n        mode: "text",\r\n        status: "primary",\r\n        name: "导入",\r\n      },\r\n      {\r\n        code: "open_export",\r\n        icon: "vxe-icon-download",\r\n        mode: "text",\r\n        status: "primary",\r\n        name: "导出",\r\n      },\r\n      {\r\n        code: "append_edit", // 底部新增\r\n        icon: "vxe-icon-add",\r\n        name: "新增数据项",\r\n        status: "primary",\r\n        mode: "text",\r\n      },\r\n    ],\r\n  },\r\n  columns: [\r\n    { type: "seq", width: 70, field: "left" },\r\n    {\r\n      field: "colName", // 可编辑-插槽渲染\r\n      title: "数据项信息",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "colEn", // 可编辑-插槽渲染\r\n      title: "数据项英文名",\r\n      minWidth: 200,\r\n      editRender: { name: "VxeInput" },\r\n    },\r\n    {\r\n      field: "colType", // 可编辑-配置渲染\r\n      title: "数据项类型",\r\n      width: 150,\r\n      editRender: { name: "ElSelect", options: $dict.getDictItems("colType"), enabled: false },\r\n    },\r\n    {\r\n      field: "colLength", // 可编辑-配置渲染\r\n      title: "长度",\r\n      width: 120,\r\n      editRender: { name: "ElInputNumber", enabled: false },\r\n    },\r\n    {\r\n      field: "isPk", // 可编辑-配置渲染\r\n      title: "主键",\r\n      width: 80,\r\n      align: "center",\r\n      // editRender: {},\r\n      slots: { default: "isPk" },\r\n    },\r\n    {\r\n      field: "isNullable", // 可编辑-配置渲染\r\n      title: "非空",\r\n      width: 80,\r\n      align: "center",\r\n      // editRender: {},\r\n      slots: { default: "isNullable" },\r\n    },\r\n  ],\r\n  editRules: {\r\n    colName: [{ required: true, content: "数据项名称不能为空", trigger: "blur" }],\r\n    colEn: [{ required: true, content: "数据项英文名不能为空", trigger: "blur" }],\r\n    colType: [{ required: true, content: "数据项类型不能为空", trigger: "blur" }],\r\n  },\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss"></style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\nconst _hoisted_1 = {\n  style: {\n    "display": "grid",\n    "grid-template-columns": "25% 75%"\n  },\n  class: "pr-5 py-2"\n};\nconst _hoisted_2 = {\n  key: 1,\n  class: "flex-x-center"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\