          content: "数据项英文名不能为空",\n          trigger: "blur"\n        }],\n        colType: [{\n          required: true,\n          content: "数据项类型不能为空",\n          trigger: "blur"\n        }]\n      }\n    });\n    return (_ctx, _cache) => {\n      const _component_LeftSelect = _resolveComponent("LeftSelect");\n      const _component_JsonForm = _resolveComponent("JsonForm");\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_el_checkbox = _resolveComponent("el-checkbox");\n      const _component_v_table = _resolveComponent("v-table");\n      const _component_el_skeleton = _resolveComponent("el-skeleton");\n      const _component_Empty = _resolveComponent("Empty");\n      return _openBlock(), _createElementBlock("div", _hoisted_1, [_createVNode(_component_LeftSelect, {\n        modelValue: currentDid.value,\n        "onUpdate:modelValue": _cache[0] || (_cache[0] = $event => currentDid.value = $event),\n        title: "数据目录列表",\n        icon: "fileCatalog",\n        list: leftList.value,\n        "field-name": {\n          title: \'fileCatalogName\'\n        },\n        onAdd: _cache[1] || (_cache[1] = item => handleAction(\'add\', item)),\n        onDelete: _cache[2] || (_cache[2] = item => handleAction(\'delete\', item)),\n        onSelect: _cache[3] || (_cache[3] = item => handleAction(\'select\', item))\n      }, null, 8 /* PROPS */, ["modelValue", "list"]), _createElementVNode("div", null, [currentDid.value ? (_openBlock(), _createBlock(_component_el_skeleton, {\n        key: 0,\n        loading: loading.value,\n        animated: ""\n      }, {\n        default: _withCtx(() => [_createVNode(_component_JsonForm, {\n          ref_key: "formRef",\n          ref: formRef,\n          bordered: "",\n          rules: formRules.value\n        }, null, 8 /* PROPS */, ["rules"]), _createVNode(_component_v_table, {\n          ref_key: "colRef",\n          ref: colRef,\n          options: tableOptions,\n          "insert-data": {\n      