ata": "setup-ref",\n  "leftList": "setup-ref",\n  "initData": "setup-reactive-const",\n  "colType": "setup-ref",\n  "handleAction": "setup-const",\n  "validate": "setup-const",\n  "detailApi": "setup-const",\n  "saveApi": "setup-const",\n  "save": "setup-const",\n  "next": "setup-const",\n  "finish": "setup-const",\n  "tableOptions": "setup-reactive-const"\n} */\n__sfc__.__file = "ba69ca594ceb050b29dde4c55b15c734.vue"\nreturn __sfc__','/* No <style> tags present */','1','登记文件目录',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016031237237968896','2016026573025120256','register-fileCatalog-data','<template>\r\n  <div style="display: grid; grid-template-columns: 25% 75%" class="pr-5 py-2 h-full">\r\n    <LeftSelect\r\n      v-model="currentDid"\r\n      title="数据目录列表"\r\n      icon="fileCatalog"\r\n      :list="leftList"\r\n      :show-add="false"\r\n      @add="(item) => handleAction(\'add\', item)"\r\n      @delete="(item) => handleAction(\'delete\', item)"\r\n      @select="(item) => handleAction(\'select\', item)"\r\n    />\r\n    <div class="h-full flex">\r\n      <el-skeleton v-if="currentDid" :loading="loading" animated>\r\n        <FileCatalogData\r\n          v-if="currentData"\r\n          class="class-clear"\r\n          title="导入数据"\r\n          :show-upload="false"\r\n          :file-catalog-id="currentData?.tid"\r\n        />\r\n        <!--        <v-table ref="colRef" :options="tableOptions">-->\r\n        <!--          <template #toolbarButtons>-->\r\n        <!--            <u-title class="pb-2! pt-0!" name="导入数据">-->\r\n        <!--              <template #right>-->\r\n        <!--                <el-button-->\r\n        <!--                  v-if="currentData.uploadType === \'1\'"-->\r\n        <!--                  type="danger"-->\r\n        <!--                  icon="delete"-->\r\n        <!--                  link-->\r\n        <!--                  :disabled="!colRef?.getCheckData().length"-->\r\n        <!--                  @click="handleAction(\'batch-delete-row\')"-->\r\n        <!--                >-->\r\n        <!--                  批量删除-->\r\n        <!--                </el-button>-->\r\n        <!--                <el-button type="primary" link @click="handleAction(\'upload\')">-->\r\n        <!--                  <template #icon>-->\r\n        <!--                    <Icon icon="el-icon-uploadFilled" size="16" />-->\r\n        <!--                  </template>-->\r\n        <!--                  {{ currentData.uploadType === "1" ? "导入数据" : "上传文件" }}-->\r\n        <!--                </el-button>-->\r\n        <!--              </template>-->\r\n        <!--            </u-title>-->\r\n        <!--          </template>-->\r\n\r\n        <!--          <template #action="{ row }">-->\r\n        <!--            <el-button v-if="currentData.uploadType === \'2\'" type="primary" link>预览</el-button>-->\r\n        <!--            <el-button type="danger" link @click="handleAction(\'delete-row\', row)">删除</el-button>-->\r\n        <!--          </template>-->\r\n        <!--        </v-table>-->\r\n      </el-skeleton>\r\n\r\n      <div v-if="!currentDid" class="flex-x-center">\r\n        <Empty />\r\n      </div>\r\n    </div>\r\n\r\n    <el-dialog\r\n      v-model="state.open"\r\n      width="800px"\r\n      title="导入数据"\r\n      :footer="null"\r\n      header-class="pb-2"\r\n    >\r\n      <el-segmented\r\n        v-if="currentData.uploadType !== \'2\'"\r\n        v-model="state.type"\r\n        :options="[\'增量导入\', \'全量导入\']"\r\n      />\r\n      <DragUpload\r\n        v-model="state.fileList"\r\n        class="mt-3"\r\n        :accept="currentData.uploadType === \'1\' ? \'.xlsx,xls\' : \'*\'"\r\n        :title="currentData.uploadType === \'1\' ? `上传表格` : \'上传文档、图片、音视频等自由格式\'"\r\n        :upload="upload"\r\n        @success="handleAction(\'upload-success\')"\r\n      >\r\n        <template v-if="currentData.uploadType !== \'2\'" #tip>\r\n          <el-button\r\n            class="mt-3"\r\n            type="primary"\r\n            link\r\n            icon="download"\r\n            @click="handleAction(\'download\')"\r\n          >\r\n            下载模版\r\n          </el-button>\r\n        </template>\r\n      </DragUpload>\r\n    </el-dialog>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { computed, nextTick, onMounted, reactive, ref } from "vue";\r\nimport { useRegisterStore } from "@/store";\r\nimport { get, set } from "lodash-es";\r\n\r\nconst loading = ref(false);\r\nconst colRef = ref();\r\nconst store = useRegisterStore();\r\nconst currentDid = ref("");\r\nconst state = reactive({\r\n  open: false,\r\n  type: "增量导入",\r\n  fileList: [],\r\n});\r\n\r\n// 表格配置\r\nconst tableOptions = reactive({\r\n  cellConfig: {},\r\n  toolbarConfig: {\r\n    slots: {\r\n      buttons: "toolbarButtons",\r\n    },\r\n    buttons: [],\r\n    tools: [],\r\n  },\r\n  columns: [],\r\n});\r\nconst fileCatalogs = computed({\r\n  get: () => {\r\n    if (!get(store.data, "fileCatalog")) {\r\n      set(store.data, "fileCatalog", []);\r\n    }\r\n    return get(store.data, "fileCatalog", []);\r\n  },\r\n  set: (val) => set(store.data, "fileCatalog", val),\r\n});\r\nconst leftList = computed(() => {\r\n  return fileCatalogs.value || [];\r\n});\r\nconst currentData = computed(() => {\r\n  return fileCatalogs.value.find((el) => el.did === currentDid.value) || {};\r\n});\r\n\r\nonMounted(() => {\r\n  handleAction("init");\r\n});\r\n\r\nconst handleAction = (type: string, item?: any) => {\r\n  switch (type) {\r\n    case "init":\r\n      if (!leftList.value.length) {\r\n        handleAction("add");\r\n      }\r\n      break;\r\n    case "add":\r\n      fileCatalogs.value.push({ did: $common.uuid() });\r\n      break;\r\n    case "delete":\r\n      fileCatalogs.value = fileCatalogs.value.filter((el) => el.did !== item.did);\r\n      break;\r\n    case "update": {\r\n      const cache = fileCatalogs.value;\r\n      const i = cache.findIndex((el) => el.did === currentDid.value);\r\n      if (i === -1) {\r\n        cache.push({ did: currentDid.value, ...item });\r\n      } else {\r\n        cache.splice(i, 1, Object.assign({}, cache[i], item));\r\n      }\r\n      break;\r\n    }\r\n    case "select":\r\n      // 刷新右侧数据\r\n      if (item.tid) {\r\n        select(item);\r\n      }\r\n      break;\r\n    case "download": {\r\n      $common.download("/dst/catalog/files/download", { tid: currentData.value.tid });\r\n      break;\r\n    }\r\n    case "upload": {\r\n      state.open = true;\r\n      break;\r\n    }\r\n    case "upload-success": {\r\n      if (currentData.value.uploadType === "1") {\r\n        // 刷新数据\r\n        handleAction("select", currentData.value);\r\n      } else {\r\n        // 非结构化数据\r\n        colRef.value.setData([]);\r\n      }\r\n      break;\r\n    }\r\n    case "delete-row":\r\n      colRef.value?.setLoading(true);\r\n\r\n      try {\r\n        const rowId = item["unique_id"] || item["UNIQUE_ID"];\r\n        deleteRowApi(currentData.value.tid, rowId).then((data) => {\r\n          $message.success("删除成功");\r\n          colRef.value.removeRow(item);\r\n        });\r\n      } finally {\r\n        colRef.value?.setLoading(false);\r\n      }\r\n      break;\r\n    case "batch-delete-row":\r\n      colRef.value?.setLoading(true);\r\n      try {\r\n        const rowIds = colRef.value\r\n          ?.getCheckData()\r\n          ?.map((el) => {\r\n            return el["unique_id"] || el["UNIQUE_ID"];\r\n          })\r\n          .join(",");\r\n        deleteRowApi(currentData.value.tid, rowIds).then((data) => {\r\n          $message.success("删除成功");\r\n          handleAction("select", currentData.value);\r\n        });\r\n      } finally {\r\n        colRef.value?.setLoading(false);\r\n      }\r\n      break;\r\n  }\r\n};\r\n\r\nconst select = (item: any) => {\r\n  try {\r\n    // 物化建表\r\n    if (!item.tableId) {\r\n      // 根据目录建表\r\n      createTable(item.tid).then((data) => {\r\n        nextTick(() => {\r\n          handleAction("update", { ...item, tableId: data.tableId });\r\n        });\r\n      });\r\n    }\r\n    if (colRef.value) {\r\n      colRef.value.setLoading(true);\r\n    }\r\n\r\n    // 获取表结构以及数据; 首次：结构化数据、非结构化数据-物化建表\r\n    detailApi(item.tid).then((data) => {\r\n      if (item.uploadType === "1") {\r\n        const { columns = [], rows = [] } = data;\r\n        const cols = columns?.map((col) => ({ title: col, field: col, minWidth: 120 }));\r\n\r\n        const tableCols = [{ type: "checkbox", width: 60, field: "left" }, ...cols];\r\n        tableCols.push({\r\n          title: "操作",\r\n          field: "action",\r\n          width: 80,\r\n          slots: { default: "action" },\r\n        });\r\n        // 转换数据格式\r\n        const tableData = rows;\r\n        nextTick(() => {\r\n          colRef.value.gridOptions.columns = tableCols;\r\n          colRef.value.gridOptions.data = tableData;\r\n          colRef.value.setLoading(false);\r\n        });\r\n      } else {\r\n        // 非结构化数据\r\n        tableOptions.columns = [\r\n          { type: "checkbox", width: 60, field: "left" },\r\n          { title: "文件名称", field: "name", slots: { default: "fileName" } },\r\n          { title: "文件类型", field: "type" },\r\n          { title: "文件大小", field: "size" },\r\n          {\r\n            title: "操作",\r\n            field: "action",\r\n            width: 140,\r\n            slots: { default: "action" },\r\n          },\r\n        ];\r\n\r\n        nextTick(() => {\r\n          colRef.value?.setData([\r\n            { name: "国产电视剧报审表", type: "docx", size: "2.2MB" },\r\n            { name: "电视剧拍摄制作备案公示表", type: "docx", size: "3.4MB" },\r\n            { name: "主题曲歌词模板", type: "pdf", size: "1.5MB" },\r\n          ]);\r\n        });\r\n      }\r\n    });\r\n  } finally {\r\n    if (colRef.value) {\r\n      colRef.value.setLoading(false);\r\n    }\r\n  }\r\n};\r\n\r\nconst upload = (file: File) => {\r\n  const formData = new FormData();\r\n  formData.append("tid", currentData.value.tid);\r\n  formData.append("file", file);\r\n  formData.append("isFull", state.type === "全量导入");\r\n  return $common.post("/dst/catalog/files/import", formData, {\r\n    "Content-Type": "multipart/form-data",\r\n  });\r\n};\r\n\r\nconst createTable = (tid: string) => {\r\n  return $common.get("/dst/catalog/files/create-table", { tid });\r\n};\r\n\r\nconst detailApi = (tid: string) => {\r\n  return $common.get("/dst/catalog/files/curd-data?action=get", { tid });\r\n};\r\n\r\nconst deleteRowApi = (tid: string, rowId: string) => {\r\n  return $common.get("/dst/catalog/files/curd-data?action=delete", { tid, rowId });\r\n};\r\n\r\nconst finish = () => {\r\n  const list = [];\r\n  fileCatalogs.value.forEach((el) => {\r\n    list.push({ ...el, assetType: "fileCatalog" });\r\n  });\r\n  return list;\r\n};\r\n\r\n// 暴露方法\r\ndefineExpose({\r\n  finish,\r\n  save: () => {\r\n    $message.success("保存成功");\r\n  },\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.class-clear {\r\n  box-shadow: none !important;\r\n  padding: 0 !important;\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _createSlots = ___magic__import__(\'vue\', \'createSlots\');\nconst _hoisted_1 = {\n  style: {\n    "display": "grid",\n    "grid-template-columns": "25% 75%"\n  },\n  class: "pr-5 py-2 h-full"\n};\nconst _hoisted_2 = {\n  class: "h-full flex"\n};\nconst _hoisted_3 = {\n  key: 1,\n  class: "flex-x-center"\n};\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\r\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\nconst useRegisterStore = ___magic__import__(\'@/store\', \'useRegisterStore\');\nconst get = ___magic__import__(\'lodash-es\', \'get\');\r\nconst set = ___magic__import__(\'lodash-es\', \'set\');\nconst __sfc__ = _defineComponent({\n  __name: \'63d5356bf92b68f0a8a698023c1a93d2\',\n  setup(__props, {\n    expose: __expose\n  }) {\n    const loading = ref(false);\n    const colRef = ref();\n    const store = useRegisterStore();\n    const currentDid = ref("");\n    const state = reactive({\n      open: false,\n      type: "增量导入",\n      fileList: []\n    });\n\n    // 表格配置\n    const tableOptions = reactive({\n      cellConfig: {},\n      toolbarConfig: {\n        slots: {\n          buttons: "toolbarButtons"\n        },\n        buttons: [],\n        tools: []\n      },\n      columns: []\n    });\n    const fileCatalogs = computed({\n      get: () => {\n        if (!get(store.data, "fileCatalog")) {\n          set(store.data, "fileCatalog", []);\n        }\n        return get(store.data, "fileCatalog", []);\n      },\n      set: val => set(store.data, "fileCatalog", val)\n    });\n    const leftList = computed(() => {\n      return fileCatalogs.value || [];\n    });\n    const currentData = computed(() => {\n      return fileCatalogs.value.find(el => el.did === currentDid.value) || {};\n    });\n    onMounted(() => {\n      handleAction("init");\n    });\n    const handleAction = (type, item) => {\n      switch (type) {\n        case "init":\n          if (!leftList.value.length) {\n            handleAction("add");\n          }\n          break;\n        case "add":\n          fileCatalogs.value.push({\n            did: $common.uuid()\n          });\n          break;\n        case "delete":\n          fileCatalogs.value = fileCatalogs.value.filter(el => el.did !== item.did);\n          break;\n        case "update":\n          {\n            const cache = fileCatalogs.value;\n            const i = cache.findIndex(el => el.did === currentDid.value);\n            if (i === -1) {\n              cache.push({\n                did: currentDid.value,\n                ...item\n              });\n            } else {\n              cache.splice(i, 1, Object.assign({}, cache[i], item));\n            }\n            break;\n          }\n        case "select":\n          // 刷新右侧数据\n          if (item.tid) {\n            select(item);\n          }\n          break;\n        case "download":\n          {\n            $common.download("/dst/catalog/files/download", {\n              tid: currentData.value.tid\n            });\n            break;\n          }\n        case "upload":\n          {\n            state.open = true;\n            break;\n          }\n        case "upload-success":\n          {\n            if (currentData.value.uploadType === "1") {\n              // 刷新数据\n              handleAction("select", currentData.value);\n            } else {\n              // 非结构化数据\n              colRef.value.setData([]);\n            }\n            break;\n          }\n        case "delete-row":\n          colRef.value?.setLoading(true);\n          try {\n            const rowId = item["unique_id"] || item["UNIQUE_ID"];\n            deleteRowApi(currentData.value.tid, rowId).then(data => {\n              $message.success("删除成功");\n              colRef.value.removeRow(item);\n            });\n          } finally {\n            colRef.value?.setLoading(false);\n          }\n          break;\n        case "batch-delete-row":\n          colRef.value?.setLoading(true);\n          try {\n            const rowIds = colRef.value?.getCheckData()?.map(el => {\n              return el["unique_id"] || el["UNIQUE_ID"];\n            }).join(",");\n            deleteRowApi(currentData.value.tid, rowIds).then(data => {\n              $message.success("删除成功");\n              handleAction("select", currentData.value);\n            });\n          } finally {\n            colRef.value?.setLoading(false);\n          }\n          break;\n      }\n    };\n    const select = item => {\n      try {\n        // 物化建表\n        if (!item.tableId) {\n          // 根据目录建表\n          createTable(item.tid).then(data => {\n            nextTick(() => {\n              handleAction("update", {\n                ...item,\n                tableId: data.tableId\n              });\n            });\n          });\n        }\n        if (colRef.value) {\n          colRef.value.setLoading(true);\n        }\n\n        // 获取表结构以及数据; 首次：结构化数据、非结构化数据-物化建表\n        detailApi(item.tid).then(data => {\n          if (item.uploadType === "1") {\n            const {\n              columns = [],\n              rows = []\n            } = data;\n            const cols = columns?.map(col => ({\n              title: col,\n              field: col,\n              minWidth: 120\n            }));\n            const tableCols = [{\n              type: "checkbox",\n              width: 60,\n              field: "left"\n            }, ...cols];\n            tableCols.push({\n              title: "操作",\n              field: "action",\n              width: 80,\n              slots: {\n                default: "action"\n              }\n            });\n            // 转换数据格式\n            const tableData = rows;\n            nextTick(() => {\n              colRef.value.gridOptions.columns = tableCols;\n              colRef.value.gridOptions.data = tableData;\n              colRef.value.setLoading(false);\n            });\n          } else {\n            // 非结构化数据\n            tableOptions.columns = [{\n              type: "checkbox",\n              width: 60,\n              field: "left"\n            }, {\n              title: "文件名称",\n              field: "name",\n              slots: {\n                default: "fileName"\n              }\n            }, {\n              title: "文件类型",\n              field: "type"\n            }, {\n              title: "文件大小",\n              field: "size"\n            }, {\n              title: "操作",\n              field: "action",\n              width: 140,\n              slots: {\n                default: "action"\n              }\n            }];\n            nextTick(() => {\n              colRef.value?.setData([{\n                name: "国产电视剧报审表",\n                type: "docx",\n                size: "2.2MB"\n              }, {\n                name: "电视剧拍摄制作备案公示表",\n                type: "docx",\n                size: "3.4MB"\n              }, {\n                name: "主题曲歌词模板",\n                type: "pdf",\n                size: "1.5MB"\n              }]);\n            });\n          }\n        });\n      } finally {\n        if (colRef.value) {\n          colRef.value.setLoading(false);\n        }\n      }\n    };\n    const upload = file => {\n      const formData = new FormData();\n      formData.append("tid", currentData.value.tid);\n      formData.append("file", file);\n      formData.append("isFull", state.type === "全量导入");\n      return $common.post("/dst/catalog/files/import", formData, {\n        "Content-Type": "multipart/form-data"\n      });\n    };\n    const createTable = tid => {\n      return $common.get("/dst/catalog/files/create-table", {\n        tid\n      });\n    };\n    const detailApi = tid => {\n      return $common.get("/dst/catalog/files/curd-data?action=get", {\n        tid\n      });\n    };\n    const deleteRowApi = (tid, rowId) => {\n      return $common.get("/dst/catalog/files/curd-data?action=delete", {\n        tid,\n        rowId\n      });\n    };\n    const finish = () => {\n      const list = [];\n      fileCatalogs.value.forEach(el => {\n        list.push({\n          ...el,\n          assetType: "fileCatalog"\n        });\n      });\n      return list;\n    };\n\n    // 暴露方法\n    __expose({\n      finish,\n      save: () => {\n        $message.success("保存成功");\n      }\n    });\n    return (_ctx, _cache) => {\n      const _component_LeftSelect = _r