            actions.value = [\n                    {\n                        code: "cancel",\n                        name: "取消",\n                        props: { type: "default" },\n                    },\n                    {\n                        // asset-register 的 finish 动作会在当前步骤保存成功后统一发出 completed 并关闭弹窗。\n                        code: "finish",\n                        name: "保存并完成",\n                        icon: "check-circle",\n                        props: { type: "primary" },\n                    },\n                ];\n                return;\n            }\n            store.state.hiddenStep = false;\n            if (type === "app") {\n                actions.value = [\n                    {\n                        code: "pre",\n                        name: "上一步",\n                        icon: "rollback",\n                        class: "btn-pre",\n                        props: {\n                            type: "default",\n                        },\n                        if({ isFirstStep, state }) {\n                            return !isFirstStep && !isRegisterFinishStep(state);\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                            plain: true,\n                        },\n                        code: "save",\n                        name: "保存",\n                        icon: "save",\n                        if({ state }) {\n                            // 第三步表登记，不需要保存按钮\n                            return state.currentStep !== 2;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "next",\n                        name: "下一步",\n                        icon: "right-circle",\n                        if({ isSecondLastStep }) {\n                            return !isSecondLastStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "finish",\n                        name: "完成登记",\n                        icon: "check-circle",\n                        if({ state, isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                ];\n            }\n            // 数据接入\n            if (type === "quality") {\n                actions.value = [\n                    {\n                        code: "cancel",\n                        name: "取消",\n                        props: {\n                            type: "default",\n                        },\n                    },\n                    {\n                        code: "pre",\n                        name: "上一步",\n                        icon: "rollback",\n                        class: "btn-pre",\n                        props: {\n                            type: "default",\n                        },\n                        if({ isFirstStep }) {\n                            return !isFirstStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                            plain: true,\n                        },\n                        code: "save",\n                        name: "保存",\n                        icon: "save",\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "next",\n                        name: "下一步",\n                        icon: "right-circle",\n                        if({ isSecondLastStep }) {\n                            return !isSecondLastStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "commit",\n                        name: "提交配置",\n                        icon: "check-circle",\n                        if({ isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                ];\n            }\n            // 订阅申请按钮配置\n            if (type === "apply") {\n                store.state.hiddenStep = true;\n                actions.value = [\n                    {\n                        code: "cancel",\n                        name: "取消",\n                        props: {\n                            type: "default",\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                            plain: true,\n                        },\n                        code: "save",\n                        name: "保存",\n                        icon: "save",\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "commit",\n                        name: "提交申请",\n                        icon: "check-circle",\n                        if({ isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                ];\n            }\n            // 订阅申请按钮配置\n            if (type === "car-apply") {\n                store.state.hiddenStep = true;\n                actions.value = [\n                    {\n                        code: "cancel",\n                        name: "取消",\n                        props: {\n                            type: "default",\n                        },\n                    },\n                    {\n                        code: "pre",\n                        name: "上一步",\n                        icon: "rollback",\n                        class: "btn-pre",\n                        props: {\n                            type: "default",\n                        },\n                        if({ isFirstStep }) {\n                            return !isFirstStep;\n                        },\n                    },\n                    {\n                        code: "print",\n                        name: "打印",\n                        props: {\n                            type: "dashed",\n                        },\n                        if({ isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                            plain: true,\n                        },\n                        code: "save",\n                        name: "保存",\n                        icon: "save",\n                        if({ isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "next",\n                        name: "下一步",\n                        icon: "right-circle",\n                        if({ isSecondLastStep }) {\n                            return !isSecondLastStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "commit",\n                        name: "提交申请",\n                        icon: "check-circle",\n                        if({ isSecondLastStep }) {\n                            return isSecondLastStep;\n                        },\n                    },\n                ];\n            }\n            if (["dbTable", "db"].includes(type)) {\n                actions.value = [\n                    {\n                        code: "pre",\n                        name: "上一步",\n                        icon: "rollback",\n                        class: "btn-pre",\n                        props: {\n                            type: "default",\n                        },\n                        if({ isFirstStep }) {\n                            return !isFirstStep;\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                            plain: true,\n                        },\n                        code: "save",\n                        name: "保存",\n                        icon: "save",\n                        if({ state }) {\n                            return [0, 2, 3].includes(state.currentStep) && !isRegisterFinishStep(state);\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        code: "next",\n                        name: "下一步",\n                        icon: "right-circle",\n                        if({ state }) {\n                            return state.currentStep !== 4 && !isRegisterFinishStep(state);\n                        },\n                    },\n                    {\n                        props: {\n                            type: "primary",\n                        },\n                        // asset-register 仅会在 finish 动作成功后推进到隐藏的 register-finish 步骤。\n                        code: "finish",\n                        name: "完成登记",\n                        icon: "check-circle",\n                        if({ state }) {\n                            return state.currentStep == 4;\n                        },\n                    },\n                ];\n            }\n        };\n        watch(open, (val) => {\n            store.data = props.registerData;\n            if (val)\n                completed.value = false;\n            if (val && props.registerClass) {\n                initData.value = {\n                    registerClass: props.registerClass,\n                    title: isExploreQuickEdit.value ? "编辑数据源" : config[props.registerClass]?.title,\n                    assets: props.assets?.length > 0 ? props.assets : [{ assetClass: props.registerClass }],\n                    // 轻量编辑只有一个数据源表单步骤；标准入口维持既有五步登记配置。\n                    steps: isExploreQuickEdit.value\n                        ? [{ title: "编辑数据源", component: "register-db" }]\n                        : config[props.registerClass]?.steps || [],\n                    currentStep: props.registerData.currentStep ?? props.currentStep ?? 0,\n                    updateFormRule: props.updateFormRule || [],\n                    registerMode: props.registerMode || "",\n                };\n            }\n            refreshState(props.registerClass);\n        }, { immediate: true });\n        return (_ctx, _cache) => {\n            const _component_Icon = _resolveComponent("Icon");\n            const _component_asset_register = _resolveComponent("asset-register");\n            const _component_el_dialog = _resolveComponent("el-dialog");\n            return (_openBlock(), _createBlock(_component_el_dialog, {\n                modelValue: open.value,\n                "onUpdate:modelValue": _cache[1] || (_cache[1] = ($event) => ((open).value = $event)),\n                "destroy-on-close": "",\n                fullscreen: "",\n                class: "register-modal__container",\n                "header-class": "p-0!",\n                "body-class": "px-20",\n                onClose: onCancel\n            }, {\n                default: _withCtx(() => [\n                    _createElementVNode("button", {\n                        class: "register-modal-back",\n                        type: "button",\n                        title: "返回",\n                        "aria-label": "返回并关闭登记弹框",\n                        onClick: onCancel\n                    }, [\n                        _createVNode(_component_Icon, { icon: "el-icon-ArrowLeft" })\n                    ]),\n                    _createCommentVNode(" asset-register中点击取消会触发对话框的@close事件 "),\n                    (loaded.value)\n                        ? (_openBlock(), _createBlock(_component_asset_register, {\n                            key: 0,\n                            class: "register-content",\n                            "init-store": initData.value,\n                            config: config,\n                            actions: actions.value,\n                            onCompleted: onCompleted,\n                            onCancel: _cache[0] || (_cache[0] = ($event) => { open.value = false; })\n                        }, null, 8 /* PROPS */, ["init-store", "actions"]))\n                        : _createCommentVNode("v-if", true)\n                ]),\n                _: 1 /* STABLE */\n            }, 8 /* PROPS */, ["modelValue"]));\n        };\n    }\n});','.register-modal__container {\n  padding: 0;\n}\n.register-modal__container .register-modal-back {\n  position: fixed;\n  top: 17px;\n  left: 14px;\n  z-index: 3001;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  border: 0;\n  border-radius: 10px;\n  background: #eaf3ff;\n  color: #1677ff;\n  cursor: pointer;\n  font-size: 18px;\n  box-shadow: 0 8px 18px rgba(22, 119, 255, 0.16);\n  transition: background-color 0.16s ease, color 0.16s ease, transform 0.16s ease, box-shadow 0.16s ease;\n}\n.register-modal__container .register-modal-back:hover {\n  background: #1677ff;\n  color: #fff;\n  transform: translateX(-1px);\n  box-shadow: 0 10px 22px rgba(22, 119, 255, 0.26);\n}\n.register-modal__container .register-container__top {\n  align-items: center;\n}\n.register-modal__container .register-container__top .register-container__title {\n  display: flex;\n  align-items: center;\n  min-height: 32px;\n  padding-left: 50px;\n  line-height: 32px;\n}\n.register-modal__container .el-dialog__header {\n  padding: 0;\n}\n.register-modal__container .el-dialog__body {\n  height: 100%;\n  padding: 0;\n}','1','登记组件',NULL,NULL,0,'2084109831678504960',2);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2033843620580794368','2033838278811688960','role-manage','<template>\r\n  <div class="role-manage-content card-container flex flex-col px-5 pt-5 pb-2">\r\n    <DataTable\r\n      ref="tableRef"\r\n      :columns="tableColumns"\r\n      :data="fetchRoleData"\r\n      :show-index="true"\r\n      :immediate="true"\r\n      style="height: 100%"\r\n    >\r\n      <template #toolbar>\r\n        <div class="flex justify-between items-center w-full">\r\n          <div class="flex">\n            <el-button type="primary" :icon="\'el-icon-Plus\'" @click="handleAdd">新增角色</el-button>\n          </div>\n          <div class="flex items-center gap-2">\n            <el-input\n              v-model="searchKeyword"\n              placeholder="搜索角色名称/编码"\n              clearable\n              style="width: 220px"\n              @keyup.enter="refreshTableData"\n              @clear="refreshTableData"\n            >\n              <template #suffix>\n                <Icon class="role-search-icon" icon="el-icon-Search" @click.stop="refreshTableData" />\n              </template>\n            </el-input>\n          </div>\n        </div>\n      </template>\n\n      <!-- 角色名称：进入角色信息 -->\n      <template #column-name="{ row }">\n        <button class="role-link" type="button" @click="handleDetail(row)">{{ row.name }}</button>\n      </template>\n\r\n      <!-- 角色编码列 -->\r\n      <template #column-codeNum="{ row }">\r\n        <el-tag\r\n          :type="row.codeNum === \'admin\' ? undefined : \'info\'"\r\n          :effect="row.codeNum === \'admin\' ? \'dark\' : \'plain\'"\r\n        >\r\n          {{ row.codeNum }}\r\n        </el-tag>\r\n      </template>\r\n\r\n      <!-- 状态开关列 -->\r\n      <template #column-status="{ row }">\r\n        <ElSwitch\r\n          :model-value="row.status"\r\n          :active-value="0"\r\n          :inactive-value="1"\r\n          :loading="row._statusLoading"\r\n          @click.prevent="handleStatusClick(row)"\r\n        ></ElSwitch>\r\n      </template>\r\n\r\n      <!-- 权限数列 -->\n      <template #column-permCount="{ row }">\n        <button class="role-stat-link" type="button" @click="handleDetail(row, \'permissions\')">\n          <Icon icon="captcha" />\n          {{ row.permCount }}\n        </button>\n      </template>\n\n      <!-- 用户数列 -->\n      <template #column-userCount="{ row }">\n        <button class="role-stat-link" type="button" @click="handleDetail(row, \'users\')">\n          <Icon icon="el-icon-User" />\n          {{ row.userCount }}\n        </button>\n      </template>\r\n    </DataTable>\r\n\r\n    <!-- 新增/详情抽屉 -->\n    <el-drawer\n      v-model="drawerVisible"\n      size="600"\n      :with-header="false"\n      :close-on-click-modal="true"\n      :destroy-on-close="true"\n      @close="handleDrawerClose"\n    >\n      <div class="drawer-body">\n        <button class="drawer-close" type="button" aria-label="关闭" @click="drawerVisible = false">\n          ×\n        </button>\n        <el-tabs v-model="activeTab" class="role-tabs" @tab-change="handleRoleTabChange">\n          <!-- 角色信息 Tab -->\n          <el-tab-pane label="角色信息" name="basic">\n            <div class="tab-content">\r\n              <JsonForm ref="jsonFormRef" :rules="formRules" :options="formOptions" />\r\n            </div>\r\n          </el-tab-pane>\r\n\r\n          <!-- 角色用户 Tab -->\r\n          <el-tab-pane label="角色用户" name="users">\r\n            <div class="tab-content user-tab">\r\n              <!-- 搜索框 -->\r\n              <div class="user-search">\r\n                <el-input\r\n                  v-model="userSearchKeyword"\r\n                  placeholder="请输入搜索内容"\r\n                  :prefix-icon="\'el-icon-Search\'"\r\n                  clearable\r\n                  @input="onUserSearch"\r\n                  @clear="onUserSearch"\r\n                />\r\n              </div>\r\n\r\n              <!-- 用户列表（带复选框，滚动分页加载） -->\r\n              <el-scrollbar ref="userScrollRef" class="user-scroll" @scroll="onUserScroll">\r\n                <div v-loading="userLoading" class="user-list-body">\r\n                  <div\r\n                    v-for="user in userList"\r\n                    :key="user.id"\r\n                    class="user-item"\r\n                    @click="toggleUserSelect(user)"\r\n                  >\r\n                    <el-checkbox\r\n                      :model-value="selectedUserIds.includes(String(user.id))"\r\n                      @change="toggleUserSelect(user)"\r\n                      @click.stop\r\n                    />\r\n                    <span\r\n                      class="user-name"\r\n                      :class="{ \'text-primary\': selectedUserIds.includes(String(user.id)) }"\r\n                    >\r\n                      {{ user.realName || user.userName }}\r\n                    </span>\r\n                  </div>\r\n                  <div v-if="userNoMore && userList.length > 0" class="no-more">\r\n                    —没有更多数据了—\r\n                  </div>\r\n                  <div v-if="!userLoading && userList.length === 0" class="empty-users">\r\n                    <empty />\r\n                  </div>\r\n                </div>\r\n              </el-scrollbar>\r\n            </div>\r\n          </el-tab-pane>\n\n          <!-- 角色权限 Tab：完整菜单/按钮树，已关联资源自动勾选 -->\n          <el-tab-pane label="角色权限" name="permissions">\n            <div class="tab-content permission-tab" v-loading="permissionLoading">\n              <div class="permission-tip">勾选后保存即可更新该角色的菜单和操作权限。</div>\n              <el-tree\n                v-if="permissionTreeData.length"\n                ref="permissionTreeRef"\n                :data="permissionTreeData"\n                node-key="id"\n                show-checkbox\n                check-on-click-node\n                default-expand-all\n                :props="{ label: \'label\', children: \'children\' }"\n                @check="handlePermissionCheck"\n              >\n                <template #default="{ data }">\n                  <span class="permission-tree-node">\n                    <span>{{ data.label }}</span>\n                    <span v-if="data.resourceType === 1" class="permission-tree-node__type">操作</span>\n                    <span v-else-if="data.resourceType === 2" class="permission-tree-node__type">分组</span>\n                  </span>\n                </template>\n              </el-tree>\n              <el-empty v-else-if="!permissionLoading" description="暂无权限资源" :image-size="96" />\n            </div>\n          </el-tab-pane>\n        </el-tabs>\n      </div>\r\n\r\n      <template #footer>\r\n        <div class="flex justify-end">\r\n          <el-button @click="drawerVisible = false">取消</el-button>\r\n          <el-button type="primary" :loading="saveLoading" @click="handleSave">确定</el-button>\r\n        </div>\r\n      </template>\r\n    </el-drawer>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\nimport { ref, nextTick } from "vue";\nimport { ElMessage } from "element-plus";\r\nimport { FormUtils } from "@/utils/form";\r\nimport type { UColumnProps } from "@/components/data/data-table.vue";\r\n\r\n// ===================== 表格 =====================\r\nconst tableRef = ref();\r\nconst searchKeyword = ref("");\r\n\r\nconst tableColumns = ref<UColumnProps[]>([\r\n  {\r\n    prop: "name",\r\n    label: "角色名称",\r\n    showOverflowTooltip: true,\r\n  },\r\n  {\r\n    prop: "codeNum",\r\n    label: "角色编码",\r\n    showOverflowTooltip: true,\r\n  },\r\n  {\r\n    prop: "description",\r\n    label: "描述",\r\n    showOverflowTooltip: true,\r\n  },\r\n  {\r\n    prop: "userCount",\r\n    label: "用户数",\r\n    width: 100,\r\n  },\r\n  {\r\n    prop: "permCount",\r\n    label: "权限数",\r\n    width: 100,\r\n  },\r\n  {\r\n    prop: "status",\r\n    label: "状态",\r\n    width: 100,\r\n  },\r\n  {\r\n    prop: "createTime",\r\n    label: "创建时间",\r\n    width: 180,\r\n  },\r\n  {\n    prop: "operation",\n    label: "操作",\n    fixed: "right",\n    buttons: [\n      {\n        label: "删除",\n        type: "danger",\n        click: (row: any) => handleDelete(row),\n      },\n    ],\r\n  },\r\n]);\r\n\r\nconst fetchRoleData = async ({\r\n  pageNo: pageNum,\r\n  pageSize,\r\n}: {\r\n  pageNo: number;\r\n  pageSize: number;\r\n}) => {\r\n  const response = await $common.post("/sym/role/page", {\r\n    name: searchKeyword.value || undefined,\r\n    pageNum,\r\n    pageSize,\r\n  });\r\n\r\n  const data = response.data || response;\r\n  const list = data.list || [];\r\n  const total = data.total || 0;\r\n\r\n  return {\r\n    list,\r\n    total,\r\n  };\r\n};\r\n\r\nconst refreshTableData = () => {\r\n  tableRef.value?.refresh(false);\r\n};\r\n\r\nconst handleDelete = (row: any) => {\r\n  $common.handle({\r\n    url: "/sym/role/delete",\r\n    info: `是否删除角色 "${row.name}" 吗？`,\r\n    data: {\r\n      id: row.id,\r\n    },\r\n    done: () => {\r\n      // 刷新表格数据\r\n      refreshTableData();\r\n    },\r\n  });\r\n};\r\n\r\nconst handleStatusClick = async (row: any) => {\r\n  // @click.prevent 阻止了开关本身切换，手动计算目标状态：0↔1 互切\r\n  const targetStatus = row.status === 0 ? 1 : 0;\r\n  row._statusLoading = true;\r\n  try {\r\n    await $common.post("/sym/role/saveOrUpdate", {\r\n      id: row.id,\r\n      roleName: row.name,\r\n      codeNum: row.codeNum,\r\n      status: targetStatus,\r\n      description: row.description || "",\r\n      userIds: row.userIds || "",\r\n    });\r\n    row.status = targetStatus;\r\n    ElMessage.success(`已${targetStatus === 0 ? "启用" : "禁用"}`);\r\n  } catch (e: any) {\r\n    // 失败时开关视觉状态不变（click 已被 prevent），无需回滚\r\n    if (e?.message) ElMessage.error(e.message);\r\n  } finally {\r\n    row._statusLoading = false;\r\n  }\r\n};\r\n\r\n// ===================== 抽屉 =====================\r\nconst drawerVisible = ref(false);\r\nconst drawerType = ref<"add" | "detail">("add");\r\nconst activeTab = ref("basic");\r\nconst saveLoading = ref(false);\nconst jsonFormRef = ref<any>(null);\nconst currentRoleId = ref<string>("");\nconst permissionTreeRef = ref<any>(null);\nconst permissionTreeData = ref<any[]>([]);\nconst selectedResourceIds = ref<string[]>([]);\nconst permissionLoading = ref(false);\n// 仅当用户实际打开过权限页签后才提交资源关联，避免编辑基本信息时误清空原有权限。\nconst permissionsLoaded = ref(false);\n\r\nconst handleAdd = () => {\n  drawerType.value = "add";\r\n  activeTab.value = "basic";\r\n  currentRoleId.value = "";\n  selectedUserIds.value = [];\n  selectedResourceIds.value = [];\n  permissionTreeData.value = [];\n  permissionsLoaded.value = false;\n  drawerVisible.value = true;\r\n  loadUsers(true);\r\n  nextTick(() => {\r\n    jsonFormRef.value?.clearValue?.();\r\n    jsonFormRef.value?.setValue?.({ status: 0 });\r\n  });\r\n};\r\n\r\nconst handleDetail = (row: any, tab: "basic" | "users" | "permissions" = "basic") => {\n  drawerType.value = "detail";\n  activeTab.value = tab;\n  currentRoleId.value = row.id || "";\r\n  // 解析已关联的用户ID（接口返回逗号分割字符串）\r\n  selectedUserIds.value = row.userIds\n    ? row.userIds.split(",").filter((id: string) => id !== "")\n    : [];\n  selectedResourceIds.value = [];\n  permissionTreeData.value = [];\n  permissionsLoaded.value = false;\n  drawerVisible.value = true;\n  loadUsers(true);\n  nextTick(() => {\n    jsonFormRef.value?.setValue?.({\r\n      name: row.name,\r\n      codeNum: row.codeNum,\r\n      status: row.status,\n      description: row.description,\n    });\n    if (tab === "permissions") loadRolePermissions();\n  });\n};\n\r\nconst handleDrawerClose = () => {\n  drawerVisible.value = false;\n  userSearchKeyword.value = "";\n  activeTab.value = "basic";\n  permissionTreeData.value = [];\n  selectedResourceIds.value = [];\n  permissionsLoaded.value = false;\n};\n\r\nconst handleSave = async () => {\r\n  try {\r\n    saveLoading.value = true;\r\n\r\n    // 1. 获取表单数据\r\n    const formData = await jsonFormRef.value?.getFormData(true);\r\n    if (!formData) return;\r\n\r\n    // 2. 构建请求体\r\n    const payload: Record<string, any> = {\r\n      roleName: formData.name,\r\n      codeNum: formData.codeNum,\r\n      status: formData.status,\r\n      description: formData.description || "",\r\n      userIds: selectedUserIds.value.join(","),\r\n    };\r\n\r\n    // 编辑模式传 id\r\n    if (currentRoleId.value) {\r\n      payload.id = currentRoleId.value;\r\n    }\r\n\r\n    // 3. 调用保存接口\r\n    const savedRole = await $common.post("/sym/role/saveOrUpdate", payload);\n    const savedRoleData = savedRole?.data || savedRole || {};\n    const roleId = `${savedRoleData.id || currentRoleId.value || ""}`;\n    if (!roleId) {\n      throw new Error("角色保存后未返回角色ID");\n    }\n\n    // 角色信息和用户关联保存成功后，仅在用户查看过权限页签时保存勾选结果。\n    // 未查看权限页签的编辑不应覆盖既有的角色权限。\n    if (permissionsLoaded.value) {\n      await $common.post("/sym/auth/saveRoleResource", {\n        roleId,\n        resourceIds: selectedResourceIds.value,\n      });\n    }\n    currentRoleId.value = roleId;\n\r\n    ElMessage.success(drawerType.value === "add" ? "创建成功" : "保存成功");\r\n    drawerVisible.value = false;\r\n    refreshTableData();\r\n  } catch (e: any) {\r\n    console.error(e);\r\n  } finally {\r\n    saveLoading.value = false;\r\n  }\r\n};\n\n// ===================== 角色权限（菜单树） =====================\nconst buildPermissionTree = (resources: any[]) => {\n  const nodeMap = new Map<string, any>();\n  const roots: any[] = [];\n  for (const resource of resources || []) {\n    const id = `${resource.id}`;\n    nodeMap.set(id, {\n      ...resource,\n      id,\n      label: resource.name || resource.sno || id,\n      children: [],\n    });\n  }\n  for (const resource of resources || []) {\n    const id = `${resource.id}`;\n    const node = nodeMap.get(id);\n    const parentId = resource.parentId == null ? "ROOT" : `${resource.parentId}`;\n    const parent = nodeMap.get(parentId);\n    if (parent && parentId !== id) {\n      parent.children.push(node);\n    } else {\n      roots.push(node);\n    }\n  }\n  const sortTree = (nodes: any[]) => {\n    nodes.sort((a, b) => Number(a.sortNum || 0) - Number(b.sortNum || 0));\n    nodes.forEach((node) => sortTree(node.children));\n  };\n  sortTree(roots);\n  return roots;\n};\n\nconst loadRolePermissions = async () => {\n  if (permissionLoading.value) return;\n  try {\n    permissionLoading.value = true;\n    permissionsLoaded.value = false;\n    const menuResponse = await $common.post("/sym/menu/all", {});\n    const menuData = menuResponse?.data || menuResponse || [];\n    permissionTreeData.value = buildPermissionTree(Array.isArray(menuData) ? menuData : menuData.list || []);\n\n    if (currentRoleId.value) {\n      const selectedResponse = await $common.post("/sym/auth/getRoleResource", {\n        roleId: currentRoleId.value,\n      });\n      const selectedData = selectedResponse?.data || selectedResponse || {};\n      selectedResourceIds.value = (selectedData.resourceIds || []).map((id: any) => `${id}`);\n    } else {\n      selectedResourceIds.value = [];\n    }\n    await nextTick();\n    permissionTreeRef.value?.setCheckedKeys(selectedResourceIds.value);\n    permissionsLoaded.value = true;\n  } catch (e: any) {\n    console.error("获取角色权限失败:", e);\n    ElMessage.error("获取角色权限失败");\n    permissionTreeData.value = [];\n    selectedResourceIds.value = [];\n  } finally {\n    permissionLoading.value = false;\n  }\n};\n\nconst handlePermissionCheck = (_node: any, checked: any) => {\n  selectedResourceIds.value = (checked?.checkedKeys || []).map((id: any) => `${id}`);\n};\n\nconst handleRoleTabChange = (tab: string | number) => {\n  if (tab === "permissions") loadRolePermissions();\n};\n\r\n// ===================== 表单配置 =====================\r\nconst formOptions = {\r\n  form: {\r\n    labelWidth: "90px",\r\n    colon: true,\r\n  },\r\n};\r\n\r\nconst formRules = FormUtils.fixJson([\r\n  {\r\n    field: "name",\r\n    title: "角色名称",\r\n    type: "input",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请输入角色名称",\r\n      maxlength: 50,\r\n      showWordLimit: true,\r\n    },\r\n  },\r\n  {\r\n    field: "codeNum",\r\n    title: "角色编码",\r\n    type: "input",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "请输入角色编码",\r\n      maxlength: 50,\r\n      showWordLimit: true,\r\n    },\r\n  },\r\n  {\r\n    field: "status",\r\n    title: "启用状态",\r\n    type: "switch",\r\n    value: 0,\r\n    props: {\r\n      activeValue: 0,\r\n      inactiveValue: 1,\r\n    },\r\n    options: [\r\n      { label: "启用", value: 0 },\r\n      { label: "禁用", value: 1 },\r\n    ],\r\n  },\r\n  {\r\n    field: "description",\r\n    title: "角色描述",\r\n    type: "input",\r\n    props: {\r\n      type: "textarea",\r\n      placeholder: "请输入角色描述",\r\n      maxlength: 200,\r\n      rows: 4,\r\n      showWordLimit: true,\r\n    },\r\n  },\r\n]);\r\n\r\n// ===================== 角色用户（滚动分页加载） =====================\r\nconst PAGE_SIZE = 20;\r\nconst userSearchKeyword = ref("");\r\nconst selectedUserIds = ref<string[]>([]);\r\nconst userLoading = ref(false);\r\nconst userList = ref<any[]>([]);\r\nconst userPage = ref(1);\r\nconst userNoMore = ref(false);\r\nconst userScrollRef = ref<any>();\r\n\r\n// 分页加载用户列表\r\nconst loadUsers = async (reset = false) => {\r\n  if (userLoading.value) return;\r\n  if (!reset && userNoMore.value) return;\r\n  if (reset) {\r\n    userPage.value = 1;\r\n    userList.value = [];\r\n    userNoMore.value = false;\r\n  }\r\n  userLoading.value = true;\r\n  try {\r\n    const response = await $common.post("/sym/user/page", {\r\n      realName: userSearchKeyword.value || undefined,\r\n      pageNum: userPage.value,\r\n      pageSize: PAGE_SIZE,\r\n    });\r\n    const data = response.data || response;\r\n    const list = data.list || [];\r\n    userList.value = reset ? list : [...userList.value, ...list];\r\n    userNoMore.value = list.length < PAGE_SIZE;\r\n    userPage.value++;\r\n  } finally {\r\n    userLoading.value = false;\r\n  }\r\n};\r\n\r\n// 搜索时重置分页\r\nconst onUserSearch = () => loadUsers(true);\r\n\r\n// 滚动触底加载下一页\r\nconst onUserScroll = ({ scrollTop }: { scrollTop: number }) => {\r\n  const wrapEl = userScrollRef.value?.wrapRef;\r\n  if (!wrapEl) return;\r\n  if (wrapEl.scrollHeight - scrollTop - wrapEl.clientHeight < 40) {\r\n    loadUsers();\r\n  }\r\n};\r\n\r\nconst toggleUserSelect = (user: { id: string | number; userName: string }) => {\r\n  const uid = String(user.id);\r\n  const idx = selectedUserIds.value.indexOf(uid);\r\n  if (idx === -1) {\r\n    selectedUserIds.value.push(uid);\r\n  } else {\r\n    selectedUserIds.value.splice(idx, 1);\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.role-manage-content {\n  width: 100%;\n  height: 100%;\n\n  .role-link,\n  .role-stat-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    border: 0;\n    background: transparent;\n    color: #1677ff;\n    cursor: pointer;\n    font: inherit;\n    padding: 0;\n\n    &:hover,\n    &:focus-visible {\n      color: #0958d9;\n      text-decoration: underline;\n      text-underline-offset: 3px;\n      outline: none;\n    }\n  }\n\n  .role-search-icon {\n    color: #1b67f8;\n    cursor: pointer;\n\n    &:hover {\n      color: #0b54d8;\n    }\n  }\n}\n\r\n.drawer-body {\n  position: relative;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  padding: 0 4px;\n\n  .drawer-close {\n    position: absolute;\n    z-index: 1;\n    top: 2px;\n    right: 0;\n    width: 36px;\n    height: 36px;\n    border: 0;\n    border-radius: 4px;\n    background: transparent;\n    color: #606266;\n    cursor: pointer;\n    font-size: 24px;\n    line-height: 32px;\n\n    &:hover {\n      background: #f5f7fa;\n      color: #1b67f8;\n    }\n  }\n\n  .role-tabs {\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n    height: 100%;\n\n    :deep(.el-tabs__header) {\n      padding-right: 44px;\n    }\n\r\n    