 inherit;\n  padding: 0;\n}\n.role-manage-content .role-link[data-v-9a445e45d692397cd673908733cf384b]:hover, .role-manage-content .role-link[data-v-9a445e45d692397cd673908733cf384b]:focus-visible,\n.role-manage-content .role-stat-link[data-v-9a445e45d692397cd673908733cf384b]:hover,\n.role-manage-content .role-stat-link[data-v-9a445e45d692397cd673908733cf384b]:focus-visible {\n  color: #0958d9;\n  text-decoration: underline;\n  text-underline-offset: 3px;\n  outline: none;\n}\n.role-manage-content .role-search-icon[data-v-9a445e45d692397cd673908733cf384b] {\n  color: #1b67f8;\n  cursor: pointer;\n}\n.role-manage-content .role-search-icon[data-v-9a445e45d692397cd673908733cf384b]:hover {\n  color: #0b54d8;\n}\n.drawer-body[data-v-9a445e45d692397cd673908733cf384b] {\n  position: relative;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  padding: 0 4px;\n}\n.drawer-body .drawer-close[data-v-9a445e45d692397cd673908733cf384b] {\n  position: absolute;\n  z-index: 1;\n  top: 2px;\n  right: 0;\n  width: 36px;\n  height: 36px;\n  border: 0;\n  border-radius: 4px;\n  background: transparent;\n  color: #606266;\n  cursor: pointer;\n  font-size: 24px;\n  line-height: 32px;\n}\n.drawer-body .drawer-close[data-v-9a445e45d692397cd673908733cf384b]:hover {\n  background: #f5f7fa;\n  color: #1b67f8;\n}\n.drawer-body .role-tabs[data-v-9a445e45d692397cd673908733cf384b] {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n.drawer-body .role-tabs[data-v-9a445e45d692397cd673908733cf384b] .el-tabs__header {\n  padding-right: 44px;\n}\n.drawer-body .role-tabs[data-v-9a445e45d692397cd673908733cf384b] .el-tabs__content {\n  flex: 1;\n  overflow: hidden;\n}\n.drawer-body .role-tabs[data-v-9a445e45d692397cd673908733cf384b] .el-tab-pane {\n  height: 100%;\n}\n.drawer-body .tab-content[data-v-9a445e45d692397cd673908733cf384b] {\n  padding: 16px 0;\n  height: 100%;\n  overflow-y: auto;\n}\n.drawer-body .user-tab[data-v-9a445e45d692397cd673908733cf384b] {\n  padding: 8px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.drawer-body .user-tab .user-search[data-v-9a445e45d692397cd673908733cf384b] {\n  flex-shrink: 0;\n}\n.drawer-body .user-tab .user-scroll[data-v-9a445e45d692397cd673908733cf384b] {\n  flex: 1;\n}\n.drawer-body .user-tab .user-list-body[data-v-9a445e45d692397cd673908733cf384b] {\n  padding-bottom: 8px;\n}\n.drawer-body .user-tab .user-list-body .user-item[data-v-9a445e45d692397cd673908733cf384b] {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 16px;\n  cursor: pointer;\n  border-bottom: 1px solid #f0f0f0;\n  transition: background-color 0.2s;\n}\n.drawer-body .user-tab .user-list-body .user-item[data-v-9a445e45d692397cd673908733cf384b]:last-child {\n  border-bottom: none;\n}\n.drawer-body .user-tab .user-list-body .user-item[data-v-9a445e45d692397cd673908733cf384b]:hover {\n  background-color: #f5f7fa;\n}\n.drawer-body .user-tab .user-list-body .user-item .user-name[data-v-9a445e45d692397cd673908733cf384b] {\n  font-size: 14px;\n  color: #303133;\n}\n.drawer-body .user-tab .user-list-body .user-item .user-name.text-primary[data-v-9a445e45d692397cd673908733cf384b] {\n  color: #1b67f8;\n}\n.drawer-body .user-tab .user-list-body .empty-users[data-v-9a445e45d692397cd673908733cf384b] {\n  height: 400px;\n}\n.drawer-body .user-tab .user-list-body .no-more[data-v-9a445e45d692397cd673908733cf384b] {\n  text-align: center;\n  color: #909399;\n  font-size: 12px;\n  padding: 10px 0 16px;\n}\n.drawer-body .permission-tab[data-v-9a445e45d692397cd673908733cf384b] {\n  padding: 8px 0;\n}\n.drawer-body .permission-tab .permission-tip[data-v-9a445e45d692397cd673908733cf384b] {\n  margin: 0 0 10px;\n  color: #909399;\n  font-size: 13px;\n  line-height: 20px;\n}\n.drawer-body .permission-tab[data-v-9a445e45d692397cd673908733cf384b] .el-tree-node__content {\n  height: 34px;\n}\n.drawer-body .permission-tab .permission-tree-node[data-v-9a445e45d692397cd673908733cf384b] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex: 1;\n  min-width: 0;\n}\n.drawer-body .permission-tab .permission-tree-node__type[data-v-9a445e45d692397cd673908733cf384b] {\n  margin-right: 12px;\n  color: #909399;\n  font-size: 12px;\n}','1','角色管理',NULL,NULL,0,'2084109831678504960',7);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2019673658236678144','2019673282695475200','rule-library','<template>\r\n  <div class="rule-library-container card-container flex flex-col pl-5">\r\n    <div class="h-full grid" style="grid-template-columns: 20% 50% 30%">\r\n      <!-- 左栏：质检维度 -->\r\n      <div class="dimension-sidebar">\r\n        <div class="sidebar-header flex items-center">\r\n          <h3 class="header-title">质检维度</h3>\r\n        </div>\r\n        <nav class="dimension-nav">\r\n          <div v-for="dim in dimensions" :key="dim.value" class="pr-3 mb-2">\r\n            <div\r\n              :class="{ active: String(dim.value) === activeDimension }"\r\n              class="flex items-center justify-between p-3 cursor-pointer gap-2 dimension-item"\r\n              @click="setActiveDimension(dim.value, dim.count)"\r\n            >\r\n              <div class="flex gap-3 flex-1 items-center">\r\n                <div\r\n                  class="dimension-item-icon flex items-center justify-between"\r\n                  :style="{ backgroundColor: `${dim.tagType || \'#0190f9\'}20` }"\r\n                >\r\n                  <Icon\r\n                    :icon="dim.icon || \'el-icon-timer\'"\r\n                    :color="dim.tagType || \'#0190f9\'"\r\n                    size="26"\r\n                  />\r\n                </div>\r\n                <div class="flex-1">\r\n                  <p class="dimension-item-name">\r\n                    {{ dim.dictName }}\r\n                    <span class="dimension-item-count">\r\n                      {{ dim.count }}\r\n                    </span>\r\n                  </p>\r\n                  <p class="dimension-item-desc">{{ dim.desc }}</p>\r\n                </div>\r\n              </div>\r\n              <!-- <span class="dimension-item-count">\r\n                {{ dim.count }}\r\n              </span> -->\r\n            </div>\r\n          </div>\r\n        </nav>\r\n      </div>\r\n\r\n      <!-- 中栏：规则列表 -->\r\n      <div class="rule-list-container">\r\n        <div class="rule-list-header">\r\n          <el-input\r\n            v-model="searchQuery"\r\n            placeholder="搜索预设规则..."\r\n            prefix-icon="Search"\r\n            style="width: 200px"\r\n            @keyup.enter="getRuleData"\r\n          />\r\n          <el-button type="primary" @click="handleAddRule">\r\n            <icon :icon="\'el-icon-Plus\'" class="mr-2" />\r\n            自定义规则\r\n          </el-button>\r\n        </div>\r\n\r\n        <div class="rule-list-content">\r\n          <!-- 加载中状态 -->\r\n          <div\r\n            v-if="loading"\r\n            v-loading="loading"\r\n            :element-loading-text="\'加载中...\'"\r\n            class="loading-container"\r\n          ></div>\r\n\r\n          <!-- 错误状态 -->\r\n          <div v-else-if="error" class="loading-container">\r\n            <Empty description="获取数据失败，请重试" />\r\n          </div>\r\n\r\n          <!-- 空数据状态 -->\r\n          <div v-else-if="rules.length === 0" class="loading-container">\r\n            <Empty description="暂无规则数据" />\r\n          </div>\r\n\r\n          <!-- 规则列表 -->\r\n          <template v-else>\r\n            <div\r\n              v-for="rule in rules"\r\n              :key="rule.tid"\r\n              :class="[\'rule-card\', { active: selectedRuleId === rule.tid }]"\r\n              @click="setSelectedRule(rule)"\r\n            >\r\n              <div class="rule-card-header">\r\n                <h4 class="rule-card-title">{{ rule.ruleName }}</h4>\r\n                <div class="flex items-center">\r\n                  <dict-label v-model="rule.ruleLevel" :options="ruleLevelOptions"></dict-label>\r\n                  <div class="divider-vertical"></div>\r\n                  <el-dropdown trigger="hover" @command="handleRuleCommand" @click.stop>\r\n                    <Icon icon="el-icon-MoreFilled" class="more-icon" :size="13" />\r\n                    <template #dropdown>\r\n                      <el-dropdown-menu>\r\n                        <el-dropdown-item :command="{ type: \'edit\', rule }">\r\n                          <Icon icon="el-icon-Edit" class="mr-2" />\r\n                          编辑规则\r\n                        </el-dropdown-item>\r\n                        <el-dropdown-item\r\n                          :command="{ type: \'delete\', rule }"\r\n                          style="color: #ff4d4f"\r\n                        >\r\n                          <Icon icon="el-icon-Delete" class="mr-2" />\r\n                          删除规则\r\n                        </el-dropdown-item>\r\n                      </el-dropdown-menu>\r\n                    </template>\r\n                  </el-dropdown>\r\n                </div>\r\n              </div>\r\n              <p class="rule-card-desc">{{ rule.ruleDescription }}</p>\r\n              <div class="rule-card-footer">\r\n                <span class="rule-card-code">{{ rule.ruleCode }}</span>\r\n                <Icon\r\n                  icon="el-icon-ArrowRight"\r\n                  :color="selectedRuleId === rule.tid ? \'#1b67f8\' : \'#94a3b8\'"\r\n                  class="rule-card-arrow"\r\n                />\r\n              </div>\r\n            </div>\r\n          </template>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 右栏：规则详情展示 -->\r\n      <div class="rule-detail-container">\r\n        <div class="detail-header flex items-center justify-between">\r\n          <h3 class="header-title">{{ formType === "add" ? "规则定义" : "规则定义详情" }}</h3>\r\n          <div v-if="formType === \'add\'">\r\n            <el-button type="primary" :disabled="isSaving" @click="handleSaveRule">\r\n              <icon :icon="\'save\'" class="mr-2" />\r\n              保存\r\n            </el-button>\r\n            <el-button @click="handleCancelRule">\r\n              <icon :icon="\'el-icon-Close\'" class="mr-2" />\r\n              取消\r\n            </el-button>\r\n          </div>\r\n        </div>\r\n        <div class="detail-form">\r\n          <json-form ref="formRef" :rules="formRules" :options="formOptions"></json-form>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, h, nextTick, onMounted } from "vue";\r\nimport { ElMessage } from "element-plus";\r\nimport { FormUtils } from "@/utils/form";\r\nimport { useDictStore } from "@/store";\r\nimport Empty from "@/components/base/empty.vue";\r\n\r\nconst ruleLevelOptions = useDictStore().getDictItems("ruleLevel") || [];\r\nconst qualityDimension = useDictStore().getDictItems("qualityDimension") || [];\r\n\r\ninterface Rule {\r\n  tid: string;\r\n  ruleName: string;\r\n  ruleCode: string;\r\n  checkDimension: string;\r\n  ruleLevel: string;\r\n  ruleDescription: string;\r\n  checkLogic: string;\r\n  scopeOfApplication: string;\r\n  configParameters: string;\r\n  // exception: string;\r\n}\r\n\r\ninterface DimensionItem {\r\n  dictName: string;\r\n  value: string;\r\n  label: string;\r\n  tagType?: string;\r\n  name?: string;\r\n  color?: string;\r\n  icon?: string;\r\n  desc?: string;\r\n  count?: number;\r\n}\r\n\r\nconst activeDimension = ref("");\r\nconst selectedRuleId = ref("");\r\nconst searchQuery = ref("");\r\nconst formType = ref("view"); // add 或 view\r\nconst formRef = ref();\r\nconst currentEditRule = ref<Rule | null>(null);\r\nconst formOptions = {\r\n  form: {\r\n    labelPosition: "top",\r\n  },\r\n};\r\nconst formRules = computed(() => {\r\n  return FormUtils.fixJson([\r\n    {\r\n      type: "UTitle",\r\n      props: {\r\n        name: "基础信息",\r\n      },\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "规则名称",\r\n      field: "ruleName",\r\n      $required: true,\r\n      props: {\r\n        disabled: formType.value === "view",\r\n      },\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "规则编码",\r\n      field: "ruleCode",\r\n      $required: true,\r\n      props: {\r\n        disabled: formType.value === "view",\r\n      },\r\n      renderSlots: {\r\n        append() {\r\n          return h("div", {\r\n            class: "i-svg:idea cursor-pointer",\r\n            style: "font-size: 18px;",\r\n            title: "点击生成随机编码",\r\n            onClick: async () => {\r\n              if (formType.value === "view") return;\r\n              formRef.value.setValue({\r\n                ruleCode: `code_${Math.random().toString(36).substring(2, 10)}`,\r\n              });\r\n            },\r\n          });\r\n        },\r\n      },\r\n    },\r\n    {\r\n      type: "select",\r\n      title: "质检维度",\r\n      field: "checkDimension",\r\n      props: {\r\n        options: qualityDimension,\r\n        disabled: formType.value === "view",\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "select",\r\n      title: "规则层级",\r\n      field: "ruleLevel",\r\n      props: {\r\n        options: ruleLevelOptions,\r\n        disabled: formType.value === "view",\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      field: "ruleDescription",\r\n      title: "规则描述",\r\n      props: {\r\n        type: "textarea",\r\n        placeholder: "请简要描述规则的功能和作用",\r\n        maxlength: 500,\r\n        rows: 4,\r\n        showWordLimit: true,\r\n        disabled: formType.value === "view",\r\n      },\r\n      $required: true,\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "适用范围",\r\n      field: "scopeOfApplication",\r\n      $required: true,\r\n      props: {\r\n        disabled: formType.value === "view",\r\n      },\r\n    },\r\n    {\r\n      type: "input",\r\n      title: "配置参数",\r\n      field: "configParameters",\r\n      $required: true,\r\n      props: {\r\n        disabled: formType.value === "view",\r\n      },\r\n    },\r\n    {\r\n      type: "code-editor",\r\n      title: "校验逻辑",\r\n      field: "checkLogic",\r\n      $required: true,\r\n      props: {\r\n        readOnly: formType.value === "view",\r\n      },\r\n    },\r\n  ]);\r\n});\r\nconst rules = ref<Rule[]>([]);\r\nconst dimensions = ref<DimensionItem[]>([]);\r\nconst loading = ref(false);\r\nconst error = ref(false);\r\nconst isSaving = ref(false);\r\n\r\nconst handleAddRule = async () => {\r\n  formType.value = "add";\r\n  selectedRuleId.value = "";\r\n  currentEditRule.value = null;\r\n\r\n  // 等待DOM更新后再操作表单\r\n  await nextTick();\r\n\r\n  if (formRef.value) {\r\n    formRef.value.resetFields();\r\n    formRef.value.setValue({\r\n      ruleName: "",\r\n      ruleCode: "",\r\n      checkDimension: activeDimension.value,\r\n      ruleLevel: "",\r\n      ruleDescription: "",\r\n      checkLogic: "",\r\n      scopeOfApplication: "",\r\n      configParameters: "",\r\n    });\r\n  }\r\n};\r\n\r\nconst handleSaveRule = async () => {\r\n  await formRef.value?.validate();\r\n  isSaving.value = true;\r\n  try {\r\n    const formData = await formRef.value.getFormData();\r\n    // 如果是编辑模式，添加tid\r\n    if (currentEditRule.value) {\r\n      formData.tid = currentEditRule.value.tid;\r\n    }\r\n    const data = await $common.post("/dwm/quality/saveOrUpdate", formData);\r\n    console.log("handleSaveRule", data);\r\n    if (data) {\r\n      ElMessage.success(currentEditRule.value ? "更新成功" : "保存成功");\r\n      // 保存成功后切换到view模式并刷新数据\r\n      formType.value = "view";\r\n      currentEditRule.value = null;\r\n      // 先刷新维度数据\r\n      await getDimensionsData();\r\n      // 确保规则列表数据已更新，并选中最新添加的规则\r\n      await nextTick();\r\n      // 如果有返回的规则ID，选中该规则\r\n      const newRule: Rule | undefined = rules.value.find((r) => r.tid == data);\r\n      if (newRule) {\r\n        setSelectedRule(newRule);\r\n      } else {\r\n        if (rules.value.length > 0) {\r\n          setSelectedRule(rules.value[0]);\r\n        }\r\n      }\r\n    } else {\r\n      ElMessage.error("保存失败");\r\n    }\r\n  } catch (error) {\r\n    console.error("Save rule error:", error);\r\n    ElMessage.error("保存失败");\r\n  } finally {\r\n    isSaving.value = false;\r\n  }\r\n};\r\nconst handleCancelRule = async () => {\r\n  // 切换回view模式\r\n  formType.value = "view";\r\n\r\n  // 等待DOM更新后再操作表单\r\n  await nextTick();\r\n\r\n  // 如果当前维度有规则，选中第一个规则\r\n  if (rules.value.length > 0) {\r\n    setSelectedRule(rules.value[0]);\r\n  } else {\r\n    clearSelectedRule();\r\n  }\r\n};\r\n\r\nconst clearSelectedRule = () => {\r\n  selectedRuleId.value = "";\r\n  if (formRef.value) {\r\n    formRef.value.resetFields();\r\n    formRef.value.setValue({\r\n      ruleName: "",\r\n      ruleCode: "",\r\n      checkDimension: activeDimension.value,\r\n      ruleLevel: "",\r\n      ruleDescription: "",\r\n      checkLogic: "",\r\n      scopeOfApplication: "",\r\n      configParameters: "",\r\n    });\r\n  }\r\n};\r\n\r\nconst setActiveDimension = async (value: string, count?: number) => {\r\n  activeDimension.value = value;\r\n  // 重置选中的规则ID为当前维度的第一个规则\r\n  if (count && count > 0) {\r\n    await getRuleData();\r\n  } else {\r\n    rules.value = [];\r\n    clearSelectedRule();\r\n  }\r\n};\r\n\r\nconst setSelectedRule = (rule: Rule) => {\r\n  formType.value = "view";\r\n  selectedRuleId.value = rule.tid;\r\n  currentEditRule.value = null;\r\n  formRef.value?.setValue(rule);\r\n};\r\n\r\nconst getRuleData = async () => {\r\n  loading.value = true;\r\n  error.value = false;\r\n\r\n  try {\r\n    const res: any = await $common.post("/dwm/quality/list", {\r\n      checkDimension: activeDimension.value,\r\n      ruleName: searchQuery.value,\r\n    });\r\n\r\n    if (res) {\r\n      rules.value = res || [];\r\n      setSelectedRule(rules.value[0]);\r\n    } else {\r\n      rules.value = [];\r\n      clearSelectedRule();\r\n    }\r\n  } catch (err) {\r\n    console.error("Failed to get rule data:", err);\r\n    error.value = true;\r\n    rules.value = [];\r\n    ElMessage.error("获取规则数据失败");\r\n  } finally {\r\n    loading.value = false;\r\n  }\r\n};\r\n\r\nconst getDimensionsData = async () => {\r\n  const data: any =\r\n    (await $common.get("/dwm/quality/getQualityDimension")) || [];\r\n  dimensions.value = data || [];\r\n  // 初始化默认值\r\n  if (dimensions.value.length > 0) {\r\n    const dim =\r\n      activeDimension.value === ""\r\n        ? dimensions.value[0]\r\n        : dimensions.value.find((item) => item.value === activeDimension.value);\r\n    setActiveDimension(dim?.value || "", dim?.count || 0);\r\n  }\r\n};\r\n\r\nconst handleRuleCommand = async (command: { type: string; rule: Rule }) => {\r\n  const { type, rule } = command;\r\n\r\n  if (type === "edit") {\r\n    // 编辑规则\r\n    await handleEditRule(rule);\r\n  } else if (type === "delete") {\r\n    // 删除规则\r\n    await handleDeleteRule(rule);\r\n  }\r\n};\r\n\r\nconst handleEditRule = async (rule: Rule) => {\r\n  formType.value = "add";\r\n  currentEditRule.value = rule;\r\n  selectedRuleId.value = rule.tid;\r\n\r\n  // 等待DOM更新后再操作表单\r\n  await nextTick();\r\n\r\n  if (formRef.value) {\r\n    formRef.value.resetFields();\r\n    formRef.value.setValue(rule);\r\n  }\r\n};\r\n\r\nconst handleDeleteRule = async (rule: Rule) => {\r\n  $common.handle({\r\n    url: "/dwm/quality/deleteById",\r\n    info: `确定要删除规则【${rule.ruleName}】吗？`,\r\n    data: { tid: rule.tid },\r\n    done: async () => {\r\n      // 删除成功后刷新数据\r\n      await getDimensionsData();\r\n      // 如果删除的是当前选中的规则，清空表单\r\n      if (selectedRuleId.value === rule.tid) {\r\n        clearSelectedRule();\r\n      }\r\n    },\r\n  });\r\n};\r\n\r\nonMounted(async () => {\r\n  await getDimensionsData();\r\n});\r\n</script>\r\n\r\n<style scoped lang="scss">\r\n.rule-library-container {\r\n  height: 100%;\r\n  .dimension-sidebar {\r\n    display: flex;\r\n    flex-direction: column;\r\n    border-right: 1px solid rgba(5, 5, 5, 0.06);\r\n    // padding-right: 5px;\r\n    overflow-y: auto;\r\n\r\n    .sidebar-header {\r\n      border-bottom: 1px solid rgba(5, 5, 5, 0.06);\r\n      padding-bottom: 10px;\r\n      margin-bottom: 15px;\r\n      margin-top: 20px;\r\n      height: 43px;\r\n    }\r\n\r\n    .dimension-nav {\r\n      flex: 1;\r\n      overflow-y: auto;\r\n      .active {\r\n        background-color: #eff6ff;\r\n        .dimension-item-name {\r\n          font-size: 15px;\r\n          color: #1d4ed8;\r\n        }\r\n        // .dimension-item-count {\r\n        //   color: #ffffff;\r\n        //   font-size: 13px;\r\n        //   background-color: #2563eb;\r\n        // }\r\n      }\r\n      .dimension-item {\r\n        border-radius: 8px;\r\n        &:hover {\r\n          background-color: #f8fafc;\r\n        }\r\n        .dimension-item-icon {\r\n          padding: 9px;\r\n          border-radius: 8px;\r\n          height: 44px;\r\n          width: 44px;\r\n        }\r\n      }\r\n      .dimension-item-name {\r\n        margin: 0;\r\n        font-size: 15px;\r\n        font-weight: 500;\r\n        color: #0f172a;\r\n        line-height: 25px;\r\n      }\r\n      .dimension-item-desc {\r\n        margin: 0;\r\n        font-size: 13px;\r\n        line-height: 1.5;\r\n        color: #94a3b8;\r\n      }\r\n      .dimension-item-count {\r\n        font-size: 14px;\r\n        color: #64748b;\r\n      }\r\n    }\r\n  }\r\n  .rule-list-container {\r\n    display: flex;\r\n    flex-direction: column;\r\n    border-right: 1px solid rgba(5, 5, 5, 0.06);\r\n    overflow: auto;\r\n    background-color: #ffffff;\r\n\r\n    .rule-list-header {\r\n      padding: 15px;\r\n      border-bottom: 1px solid rgba(5, 5, 5, 0.06);\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      background-color: #ffffff;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .rule-list-content {\r\n      flex: 1;\r\n      overflow-y: auto;\r\n      padding: 15px;\r\n      gap: 0.75rem;\r\n      display: flex;\r\n      flex-direction: column;\r\n      background-color: #fafbff;\r\n\r\n      .loading-container {\r\n        flex: 1;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        min-height: 400px;\r\n      }\r\n\r\n      .rule-card {\r\n        padding: 1rem;\r\n        border-radius: 4px;\r\n        background: #fff;\r\n        border: 1px solid #d8dee6;\r\n        cursor: pointer;\r\n        transition: all 0.2s ease;\r\n\r\n        &:hover {\r\n          border: 1px solid #bfdbfe;\r\n          box-shadow: 0 0 12px #bfdbfe26;\r\n          :deep(.rule-card-arrow) {\r\n            transform: translateX(4px);\r\n          }\r\n        }\r\n\r\n        &.active {\r\n          border: 1px solid #1b67f8;\r\n          box-shadow: 0 0 12px #1b67f826;\r\n        }\r\n\r\n        .rule-card-header {\r\n          display: flex;\r\n          align-items: center;\r\n          justify-content: space-between;\r\n\r\n          .rule-card-title {\r\n            font-weight: 500;\r\n            font-size: 15px;\r\n            text-align: left;\r\n            color: #0f172a;\r\n            margin: 0;\r\n          }\r\n\r\n          .el-tag {\r\n            font-size: 0.625rem;\r\n            font-weight: bold;\r\n          }\r\n\r\n          .divider-vertical {\r\n            width: 1px;\r\n            height: 16px;\r\n            background-color: #d8dee6;\r\n            margin: 0 8px 0 12px;\r\n          }\r\n\r\n          .more-icon {\r\n            cursor: pointer;\r\n            color: #94a3b8;\r\n            transition: all 0.2s ease;\r\n            transform: rotate(90deg);\r\n            outline: none;\r\n\r\n            &:hover {\r\n              color: #1b67f8;\r\n            }\r\n          }\r\n        }\r\n\r\n        .rule-card-desc {\r\n          font-family: "Source Han Sans SC";\r\n          font-weight: 400;\r\n          font-size: 13px;\r\n          color: #94a3b8;\r\n          padding: 8px 0;\r\n          margin: 0;\r\n          display: -webkit-box;\r\n          -webkit-line-clamp: 2;\r\n          line-clamp: 2;\r\n          -webkit-box-orient: vertical;\r\n          overflow: hidden;\r\n        }\r\n\r\n        .rule-card-footer {\r\n          display: flex;\r\n          align-items: center;\r\n          justify-content: space-between;\r\n\r\n          .rule-card-code {\r\n            font-weight: 400;\r\n            font-size: 13px;\r\n            color: #94a3b8;\r\n          }\r\n\r\n          .rule-card-arrow {\r\n            transition: transform 0.2s ease;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n  .rule-detail-container {\r\n    display: flex;\r\n    flex-direction: column;\r\n    overflow: auto;\r\n    .detail-header {\r\n      padding: 0 15px;\r\n      height: 32px;\r\n      margin-top: 23px;\r\n      margin-bottom: 15px;\r\n    }\r\n    .detail-title {\r\n      margin: 0;\r\n      font-size: 16px;\r\n      font-weight: 700;\r\n      color: #464c64;\r\n      line-height: 32px;\r\n    }\r\n    .detail-form {\r\n      padding: 0 15px;\r\n      overflow: auto;\r\n    }\r\n  }\r\n  .header-title {\r\n    margin: 0;\r\n    font-size: 16px;\r\n    font-weight: 700;\r\n    color: #464c64;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\ncon