lex;\n  flex-direction: column;\n  border-right: 1px solid rgba(5, 5, 5, 0.06);\n  overflow: auto;\n  background-color: #ffffff;\n}\n.rule-library-container .rule-list-container .rule-list-header[data-v-752f811788de620aab554c1527e8a8b5] {\n  padding: 15px;\n  border-bottom: 1px solid rgba(5, 5, 5, 0.06);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background-color: #ffffff;\n  flex-shrink: 0;\n}\n.rule-library-container .rule-list-container .rule-list-content[data-v-752f811788de620aab554c1527e8a8b5] {\n  flex: 1;\n  overflow-y: auto;\n  padding: 15px;\n  gap: 0.75rem;\n  display: flex;\n  flex-direction: column;\n  background-color: #fafbff;\n}\n.rule-library-container .rule-list-container .rule-list-content .loading-container[data-v-752f811788de620aab554c1527e8a8b5] {\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 400px;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card[data-v-752f811788de620aab554c1527e8a8b5] {\n  padding: 1rem;\n  border-radius: 4px;\n  background: #fff;\n  border: 1px solid #d8dee6;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card[data-v-752f811788de620aab554c1527e8a8b5]:hover {\n  border: 1px solid #bfdbfe;\n  box-shadow: 0 0 12px rgba(191, 219, 254, 0.1490196078);\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card[data-v-752f811788de620aab554c1527e8a8b5]:hover .rule-card-arrow {\n  transform: translateX(4px);\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card.active[data-v-752f811788de620aab554c1527e8a8b5] {\n  border: 1px solid #1b67f8;\n  box-shadow: 0 0 12px rgba(27, 103, 248, 0.1490196078);\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header[data-v-752f811788de620aab554c1527e8a8b5] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header .rule-card-title[data-v-752f811788de620aab554c1527e8a8b5] {\n  font-weight: 500;\n  font-size: 15px;\n  text-align: left;\n  color: #0f172a;\n  margin: 0;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header .el-tag[data-v-752f811788de620aab554c1527e8a8b5] {\n  font-size: 0.625rem;\n  font-weight: bold;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header .divider-vertical[data-v-752f811788de620aab554c1527e8a8b5] {\n  width: 1px;\n  height: 16px;\n  background-color: #d8dee6;\n  margin: 0 8px 0 12px;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header .more-icon[data-v-752f811788de620aab554c1527e8a8b5] {\n  cursor: pointer;\n  color: #94a3b8;\n  transition: all 0.2s ease;\n  transform: rotate(90deg);\n  outline: none;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-header .more-icon[data-v-752f811788de620aab554c1527e8a8b5]:hover {\n  color: #1b67f8;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-desc[data-v-752f811788de620aab554c1527e8a8b5] {\n  font-family: "Source Han Sans SC";\n  font-weight: 400;\n  font-size: 13px;\n  color: #94a3b8;\n  padding: 8px 0;\n  margin: 0;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-footer[data-v-752f811788de620aab554c1527e8a8b5] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-footer .rule-card-code[data-v-752f811788de620aab554c1527e8a8b5] {\n  font-weight: 400;\n  font-size: 13px;\n  color: #94a3b8;\n}\n.rule-library-container .rule-list-container .rule-list-content .rule-card .rule-card-footer .rule-card-arrow[data-v-752f811788de620aab554c1527e8a8b5] {\n  transition: transform 0.2s ease;\n}\n.rule-library-container .rule-detail-container[data-v-752f811788de620aab554c1527e8a8b5] {\n  display: flex;\n  flex-direction: column;\n  overflow: auto;\n}\n.rule-library-container .rule-detail-container .detail-header[data-v-752f811788de620aab554c1527e8a8b5] {\n  padding: 0 15px;\n  height: 32px;\n  margin-top: 23px;\n  margin-bottom: 15px;\n}\n.rule-library-container .rule-detail-container .detail-title[data-v-752f811788de620aab554c1527e8a8b5] {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n  line-height: 32px;\n}\n.rule-library-container .rule-detail-container .detail-form[data-v-752f811788de620aab554c1527e8a8b5] {\n  padding: 0 15px;\n  overflow: auto;\n}\n.rule-library-container .header-title[data-v-752f811788de620aab554c1527e8a8b5] {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 700;\n  color: #464c64;\n}','1','质检规则库',NULL,NULL,0,'2084109831678504960',5);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2016463807998136320','2016463450651824128','schedule-config','<template>\r\n  <div class="schedule-config">\r\n    <div class="card-content">\r\n      <!-- 模式选择 -->\r\n      <div class="mode-selection">\r\n        <div\r\n          v-for="mode in modes"\r\n          :key="mode.value"\r\n          :class="[\'mode-card\', { active: selectedMode === mode.value }]"\r\n          @click="selectedMode = mode.value"\r\n        >\r\n          <div :class="[\'icon-wrapper\', { active: selectedMode === mode.value }]">\r\n            <Icon :icon="mode.icon" :color="mode.iconColor" :size="24"></Icon>\r\n          </div>\r\n          <div class="mode-info">\r\n            <h4 :class="{ active: selectedMode === mode.value }">{{ mode.label }}</h4>\r\n            <p>{{ mode.desc }}</p>\r\n          </div>\r\n          <div v-if="selectedMode === mode.value" class="check-icon flex items-center">\r\n            <Icon icon="el-icon-CircleCheckFilled" :size="18"></Icon>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 动态配置区域 -->\r\n      <div v-if="[1, 2].includes(selectedMode)" class="config-content">\r\n        <!-- 周期调度配置 -->\r\n        <div v-if="selectedMode === 1" class="periodic-config">\r\n          <JsonForm ref="periodicFormRef" :rules="periodicFormRules" :options="formOptions" />\r\n        </div>\r\n\r\n        <!-- Cron表达式配置 -->\r\n        <div v-if="selectedMode === 2" class="cron-config">\r\n          <JsonForm ref="cronFormRef" :rules="cronFormRules" :options="cornFormOptions">\r\n            <template #field-cronExpress="scope">\r\n              <div class="flex items-center w-full gap-2">\r\n                <el-input\r\n                  v-model="scope.model.value"\r\n                  placeholder="* * * * * ?"\r\n                  @input="handleExpressionChange"\r\n                  @change="handleExpressionChange"\r\n                />\r\n                <el-button class="predict-btn" plain @click="predictCron">最近 5 次预测</el-button>\r\n              </div>\r\n            </template>\r\n          </JsonForm>\r\n          <div class="form-extra">\r\n            <a href="https://crontab.guru/" target="_blank" class="help-link">在线校验工具</a>\r\n          </div>\r\n          <div v-if="currentExpression" class="info-card flex items-center">\r\n            <Icon icon="info" :color="\'#3b82f6\'"></Icon>\r\n            <div class="info-text">\r\n              Cron 表达式\r\n              <span class="cron-expression">{{ currentExpression }}</span>\r\n              表示\r\n              <span class="execution-time">{{ cronDescription }}</span>\r\n              触发任务。\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, watch, onMounted } from "vue";\r\nimport { useDictStore } from "@/store";\r\n\r\nconst props = defineProps({\r\n  info: {\r\n    type: Object,\r\n    default: () => ({}),\r\n  },\r\n});\r\n\r\n// interface Mode {\r\n//   scheduleStrategy?: number;\r\n//   scheduleCycle?: number;\r\n//   scheduleRunning?: string;\r\n//   scheduleRunningStart?: string;\r\n//   scheduleRunningEnd?: string;\r\n//   scheduleFaildRetry?: number;\r\n//   cronExpress?: string;\r\n//   taskStatus?: number;\r\n//   lastRunning?: string;\r\n//   lastStatusValue?: string;\r\n//   endRunning?: string;\r\n//   tenantId?: string;\r\n// }\r\n\r\nconst selectedMode = ref();\r\nconst periodicFormRef = ref();\r\n\r\nconst modes = useDictStore().getDictItems("scheduleStrategy");\r\nconst scheduleCycle = useDictStore().getDictItems("scheduleCycle");\r\n\r\nconst periodicFormRules = [\r\n  {\r\n    type: "radio",\r\n    field: "scheduleCycle",\r\n    title: "调度周期",\r\n    $required: true,\r\n    props: {\r\n      border: true,\r\n    },\r\n    options: scheduleCycle,\r\n  },\r\n  {\r\n    type: "datePicker",\r\n    field: "scheduleRunning",\r\n    title: "具体执行时间",\r\n    $required: true,\r\n    props: {\r\n      type: "date",\r\n      valueFormat: "YYYY-MM-DD HH:mm:ss",\r\n    },\r\n    style: {\r\n      width: "100%",\r\n    },\r\n  },\r\n  {\r\n    type: "datePicker",\r\n    field: "scheduleTimeRange",\r\n    title: "生效日期起始",\r\n    $required: true,\r\n    props: {\r\n      type: "daterange",\r\n      valueFormat: "YYYY-MM-DD HH:mm:ss",\r\n    },\r\n  },\r\n  {\r\n    type: "select",\r\n    field: "scheduleFaildRetry",\r\n    title: "失败重试次数",\r\n    props: {\r\n      placeholder: "请选择重试次数",\r\n    },\r\n    options: [\r\n      { label: "不重试", value: 0 },\r\n      { label: "1 次", value: 1 },\r\n      { label: "3 次", value: 3 },\r\n    ],\r\n  },\r\n];\r\n\r\nconst formOptions = {\r\n  col: {\r\n    span: 12,\r\n  },\r\n  row: {\r\n    gutter: 20,\r\n  },\r\n};\r\n\r\nconst cornFormOptions = {\r\n  form: {\r\n    labelPosition: "top",\r\n  },\r\n};\r\n\r\nconst cronFormRef = ref();\r\nconst currentExpression = ref(""); // 当前 Cron 表达式\r\nconst cronDescription = ref(""); // Cron 表达式描述\r\nconst cronFormRules = [\r\n  {\r\n    type: "fieldComponent",\r\n    field: "cronExpress",\r\n    title: "Cron 表达式",\r\n    $required: true,\r\n    validate: [\r\n      {\r\n        trigger: "change",\r\n        test: /^\\s*([^\\s]+)\\s+([^\\s]+)\\s+([^\\s]+)\\s+([^\\s]+)\\s+([^\\s]+)\\s+([^\\s]+)\\s*$/,\r\n        message: "无效的 Cron 表达式格式",\r\n      },\r\n    ],\r\n  },\r\n];\r\n\r\n// 解析 Cron 表达式\r\nconst parseCronExpression = (cron: string) => {\r\n  if (!cron || cron.trim() === "") {\r\n    return "请输入 Cron 表达式";\r\n  }\r\n\r\n  try {\r\n    const parts = cron.trim().split(/\\s+/);\r\n    if (parts.length !== 6) {\r\n      return "无效的 Cron 表达式格式";\r\n    }\r\n\r\n    const [second, minute, hour, dayOfMonth, month, dayOfWeek] = parts;\r\n\r\n    // 常见模式解析\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "2" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每天凌晨 02:00:00";\r\n    }\r\n\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "0" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每天凌晨 00:00:00";\r\n    }\r\n\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "12" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每天中午 12:00:00";\r\n    }\r\n\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "*" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每小时整点";\r\n    }\r\n\r\n    if (\r\n      second === "0" &&\r\n      minute === "*" &&\r\n      hour === "*" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每分钟";\r\n    }\r\n\r\n    if (\r\n      second === "*" &&\r\n      minute === "*" &&\r\n      hour === "*" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      return "每秒";\r\n    }\r\n\r\n    // 每周特定时间\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "9" &&\r\n      dayOfMonth === "*" &&\r\n      month === "*" &&\r\n      dayOfWeek !== "*" &&\r\n      dayOfWeek !== "?"\r\n    ) {\r\n      const dayNames = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];\r\n      const dayIndex = parseInt(dayOfWeek);\r\n      if (dayIndex >= 1 && dayIndex <= 7) {\r\n        return `${dayNames[dayIndex % 7]} 上午 09:00:00`;\r\n      }\r\n    }\r\n\r\n    // 每月特定日期\r\n    if (\r\n      second === "0" &&\r\n      minute === "0" &&\r\n      hour === "0" &&\r\n      dayOfMonth !== "*" &&\r\n      month === "*" &&\r\n      (dayOfWeek === "*" || dayOfWeek === "?")\r\n    ) {\r\n      const day = parseInt(dayOfMonth);\r\n      if (day >= 1 && day <= 31) {\r\n        return `每月 ${day} 日凌晨 00:00:00`;\r\n      }\r\n    }\r\n\r\n    // 通用解析\r\n    let description = "";\r\n\r\n    // 时间部分\r\n    if (second === "0" && minute !== "*" && hour !== "*") {\r\n      const hourStr = hour.padStart(2, "0");\r\n      const minuteStr = minute.padStart(2, "0");\r\n      description = `${hourStr}:${minuteStr}:00`;\r\n    } else if (second === "0" && minute === "*" && hour !== "*") {\r\n      const hourStr = hour.padStart(2, "0");\r\n      description = `${hourStr} 点每分钟`;\r\n    } else if (second === "0" && minute === "0" && hour === "*") {\r\n      description = "每小时整点";\r\n    } else if (second === "0" && minute === "*") {\r\n      description = "每分钟";\r\n    } else if (second === "*") {\r\n      description = "每秒";\r\n    }\r\n\r\n    // 日期部分\r\n    if (dayOfMonth === "*" && month === "*" && (dayOfWeek === "*" || dayOfWeek === "?")) {\r\n      description = `每天 ${description}`;\r\n    } else if (dayOfMonth !== "*" && month === "*" && (dayOfWeek === "*" || dayOfWeek === "?")) {\r\n      const day = parseInt(dayOfMonth);\r\n      if (day >= 1 && day <= 31) {\r\n        description = `每月 ${day} 日 ${description}`;\r\n      }\r\n    } else if (dayOfMonth === "*" && month !== "*" && (dayOfWeek === "*" || dayOfWeek === "?")) {\r\n      const monthNames = [\r\n        "",\r\n        "1月",\r\n        "2月",\r\n        "3月",\r\n        "4月",\r\n        "5月",\r\n        "6月",\r\n        "7月",\r\n        "8月",\r\n        "9月",\r\n        "10月",\r\n        "11月",\r\n        "12月",\r\n      ];\r\n      const monthIndex = parseInt(month);\r\n      if (monthIndex >= 1 && monthIndex <= 12) {\r\n        description = `${monthNames[monthIndex]} 每天 ${description}`;\r\n      }\r\n    } else if (dayOfWeek !== "*" && dayOfWeek !== "?") {\r\n      const dayNa