flex-shrink: 0;\n  grid-template-columns: 15% 1fr 15%;\n  align-items: center;\n  height: 45px;\n  padding: 0 15px 0 20px;\n  background-color: #fff;\n  border-bottom: 1px solid #ebeef5;\n}\n.api-modal__container .api-modal__title {\n  font-family: Arial, sans-serif;\n  font-size: 16px;\n  font-weight: 700;\n  color: rgba(0, 0, 0, 0.8784313725);\n}\n.api-modal__container .api-modal__footer {\n  display: flex;\n  justify-content: center;\n  padding: 10px 24px;\n  text-align: right;\n  background-color: #fff;\n  border-top: 1px solid #ebeef5;\n}\n.api-modal__container .api-modal__body {\n  height: calc(100% - 45px - 53px);\n  grid-template-columns: 100%;\n  overflow: hidden;\n}\n.api-modal__container .api-modal__body .el-scrollbar {\n  width: 100%;\n  height: 100%;\n}\n.api-modal__container .api-status {\n  position: relative;\n}\n.api-modal__container .api-status .vxe-grid--toolbar-wrapper {\n  position: absolute;\n  right: 0;\n  top: -39px;\n}\n.api-modal__container .api-params-table {\n  min-height: 200px;\n  position: relative;\n}\n.api-modal__container .api-params-table .vxe-grid--toolbar-wrapper {\n  position: absolute;\n  right: 0;\n  top: -39px;\n}\n.api-modal__container .header-checkbox {\n  height: 40px;\n  color: #587aa8;\n}','1','服务弹窗',NULL,NULL,0,'2084109831678504960',4);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2063874447825747968','2063874204568698880','service-status-table','<template>\r\n  <v-table\r\n    ref="tableRef"\r\n    class="api-status"\r\n    :options="statusTableOptions"\r\n    :editable="!readonly"\r\n    :show-operation="!readonly"\r\n  />\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { reactive, ref, onMounted } from "vue";\r\n\r\nconst props = defineProps<{\r\n  enableDrag?: boolean;\r\n  readonly?: boolean;\r\n}>();\r\n\r\nconst tableRef = ref();\r\n\r\n// 默认状态码（两个 Modal 完全相同）\r\nconst defaultStatusCodes = [\r\n  { statusCode: "500", statusDesc: "服务器错误" },\r\n  { statusCode: "400", statusDesc: "非法请求" },\r\n  { statusCode: "401", statusDesc: "认证失败" },\r\n  { statusCode: "403", statusDesc: "禁止，没有权限操作" },\r\n  { statusCode: "404", statusDesc: "找不到" },\r\n  { statusCode: "200", statusDesc: "请求成功" },\r\n];\r\n\r\nconst statusTableOptions = reactive({\r\n  rowConfig: props.enableDrag ? { drag: true } : {},\r\n  toolbarConfig: {\r\n    buttons: [\r\n      {\r\n        code: "append_edit",\r\n        icon: "vxe-icon-add",\r\n        name: "新增参数",\r\n        status: "primary",\r\n        mode: "text",\r\n      },\r\n    ],\r\n    tools: [],\r\n  },\r\n  columns: [\r\n    { field: "statusCode", title: "状态码", editRender: { name: "VxeInput" } },\r\n    { field: "statusDesc", title: "状态描述", editRender: { name: "VxeInput" } },\r\n  ],\r\n  editRules: {\r\n    statusCode: [{ required: true, content: "状态码不能为空", trigger: "blur" }],\r\n    statusDesc: [{ required: true, content: "状态描述不能为空", trigger: "blur" }],\r\n  },\r\n});\r\n\r\n// 初始化时填入默认状态码\r\nonMounted(() => {\r\n  tableRef.value?.setData([...defaultStatusCodes]);\r\n});\r\n\r\n// 暴露给父组件调用\r\ndefineExpose({\r\n  /** 设置表格数据 */\r\n  setData: (data: any[]) => tableRef.value?.setData(data),\r\n  /** 获取表格数据 */\r\n  getData: () => tableRef.value?.getData() || [],\r\n  /** 验证表格数据 */\r\n  validate: () => tableRef.value?.validate(),\r\n  /** 重置为默认状态码 */\r\n  reset: () => tableRef.value?.setData([...defaultStatusCodes]),\r\n  /** 获取默认状态码（用于提交时比对） */\r\n  getDefaultData: () => [...defaultStatusCodes],\r\n});\r\n</script>\r\n<style scoped lang="scss">\r\n.api-status {\r\n  position: relative;\r\n  :deep(.vxe-grid--toolbar-wrapper) {\r\n    position: absolute;\r\n    right: 0;\r\n    top: -39px;\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst reactive = ___magic__import__(\'vue\', \'reactive\');\r\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\nconst __sfc__ = _defineComponent({\n  __name: \'a1207486a4b6fbe0b6c5b8e773a8f355\',\n  props: {\n    enableDrag: {\n      type: Boolean,\n      required: false\n    },\n    readonly: {\n      type: Boolean,\n      required: false\n    }\n  },\n  setup(__props, {\n    expose: __expose\n  }) {\n    const props = __props;\n    const tableRef = ref();\n\n    // 默认状态码（两个 Modal 完全相同）\n    const defaultStatusCodes = [{\n      statusCode: "500",\n      statusDesc: "服务器错误"\n    }, {\n      statusCode: "400",\n      statusDesc: "非法请求"\n    }, {\n      statusCode: "401",\n      statusDesc: "认证失败"\n    }, {\n      statusCode: "403",\n      statusDesc: "禁止，没有权限操作"\n    }, {\n      statusCode: "404",\n      statusDesc: "找不到"\n    }, {\n      statusCode: "200",\n      statusDesc: "请求成功"\n    }];\n    const statusTableOptions = reactive({\n      rowConfig: props.enableDrag ? {\n        drag: true\n      } : {},\n      toolbarConfig: {\n        buttons: [{\n          code: "append_edit",\n          icon: "vxe-icon-add",\n          name: "新增参数",\n          status: "primary",\n          mode: "text"\n        }],\n        tools: []\n      },\n      columns: [{\n        field: "statusCode",\n        title: "状态码",\n        editRender: {\n          name: "VxeInput"\n        }\n      }, {\n        field: "statusDesc",\n        title: "状态描述",\n        editRender: {\n          name: "VxeInput"\n        }\n      }],\n      editRules: {\n        statusCode: [{\n          required: true,\n          content: "状态码不能为空",\n          trigger: "blur"\n        }],\n        statusDesc: [{\n          required: true,\n          content: "状态描述不能为空",\n          trigger: "blur"\n        }]\n      }\n    });\n\n    // 初始化时填入默认状态码\n    onMounted(() => {\n      tableRef.value?.setData([...defaultStatusCodes]);\n    });\n\n    // 暴露给父组件调用\n    __expose({\n      /** 设置表格数据 */\n      setData: data => tableRef.value?.setData(data),\n      /** 获取表格数据 */\n      getData: () => tableRef.value?.getData() || [],\n      /** 验证表格数据 */\n      validate: () => tableRef.value?.validate(),\n      /** 重置为默认状态码 */\n      reset: () => tableRef.value?.setData([...defaultStatusCodes]),\n      /** 获取默认状态码（用于提交时比对） */\n      getDefaultData: () => [...defaultStatusCodes]\n    });\n    return (_ctx, _cache) => {\n      const _component_v_table = _resolveComponent("v-table");\n      return _openBlock(), _createBlock(_component_v_table, {\n        ref_key: "tableRef",\n        ref: tableRef,\n        class: "api-status",\n        options: statusTableOptions,\n        editable: !__props.readonly,\n        "show-operation": !__props.readonly\n      }, null, 8 /* PROPS */, ["options", "editable", "show-operation"]);\n    };\n  }\n});\n/* Analyzed bindings: {\n  "reactive": "setup-const",\n  "ref": "setup-const",\n  "onMounted": "setup-const",\n  "props": "setup-reactive-const",\n  "tableRef": "setup-ref",\n  "defaultStatusCodes": "setup-const",\n  "statusTableOptions": "setup-reactive-const",\n  "enableDrag": "props",\n  "readonly": "props"\n} */\n__sfc__.__scopeId = "data-v-a1207486a4b6fbe0b6c5b8e773a8f355"\n__sfc__.__file = "a1207486a4b6fbe0b6c5b8e773a8f355.vue"\nreturn __sfc__','.api-status[data-v-a1207486a4b6fbe0b6c5b8e773a8f355] {\n  position: relative;\n}\n.api-status[data-v-a1207486a4b6fbe0b6c5b8e773a8f355] .vxe-grid--toolbar-wrapper {\n  position: absolute;\n  right: 0;\n  top: -39px;\n}','1','api状态表格',NULL,NULL,0,'2084109831678504960',3);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2019596591486808064','2015737170683826176','shopping-car','<template>\r\n  <div class="cart-animation-demo">\r\n    <el-badge\r\n      ref="cartTarget"\r\n      :value="cartCount"\r\n      :offset="[2, 0]"\r\n      style="line-height: 1"\r\n      @click="open"\r\n    >\r\n      <Icon icon="el-icon-ShoppingCart" size="20" />\r\n    </el-badge>\r\n\r\n    <!-- 动画容器（承载小圆球，纯 CSS 样式，保证小球可见） -->\r\n    <div ref="animateContainer" class="animate-container"></div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, unref, onMounted } from "vue";\r\nimport { useElementBounding } from "@vueuse/core";\r\nimport { throttle } from "lodash-es";\r\nimport { useRegisterModal, useCartCount } from "@/composables";\r\n\r\n// 申请单登记弹框\r\nconst { openRegisterModal } = useRegisterModal();\r\n\r\nconst open = () => {\r\n  openRegisterModal({\r\n    registerClass: "car-apply",\r\n    registerData: {},\r\n  });\r\n};\r\n\r\nfunction useCartAnimation(options: Record<string, any> = {}) {\r\n  // 默认配置\r\n  const defaultOptions = {\r\n    duration: 500,\r\n    throttleTime: 500,\r\n  };\r\n  const finalOptions = { ...defaultOptions, ...options };\r\n\r\n  // 动画容器 Ref（需在视图中绑定）\r\n  const animateContainer = ref(null);\r\n  // 购物车数量（使用外部传入的共享 ref，若未传则降级为局部 ref）\r\n  const cartCount = options.cartCount || ref(0);\r\n\r\n  // 校验配置项\r\n  if (!options.cartTarget) {\r\n    console.warn("useCartAnimation: 必须传入 cartTarget（购物车元素 Ref）");\r\n  }\r\n\r\n  /**\r\n   * 生成动画小圆球并执行滑动动画\r\n   * @param {MouseEvent} event 点击事件对象（用于获取点击位置）\r\n   * @param {string} [color=\'#ff4d4f\'] 小圆球颜色（可选）\r\n   */\r\n  const triggerCartAnimation = (event, color = "#ff4d4f") => {\r\n    const cartTarget = unref(options.cartTarget);\r\n    const container = unref(animateContainer);\r\n\r\n    // 校验必要元素\r\n    if (!event || !cartTarget || !container) return;\r\n\r\n    // 1. 获取点击位置（相对于视口）和购物车元素位置（使用 VueUse useElementBounding）\r\n    const { clientX: clickX, clientY: clickY } = event;\r\n    const bounds = useElementBounding(cartTarget);\r\n    const cartX = unref(bounds.x);\r\n    const cartY = unref(bounds.y);\r\n    const cartW = unref(bounds.width);\r\n    const cartH = unref(bounds.height);\r\n\r\n    // 2. 计算动画目标位置（购物车中心）\r\n    const targetX = cartX + cartW / 2 - 8; // 8 = 小圆球直径 16px / 2，居中对齐\r\n    const targetY = cartY + cartH / 2 - 8;\r\n\r\n    // 3. 创建小圆球动画元素（纯 CSS 样式，无 UnoCSS 依赖）\r\n    const ball = document.createElement("div");\r\n    ball.style.width = "16px"; // 小圆球直径 16px\r\n    ball.style.height = "16px";\r\n    ball.style.borderRadius = "50%"; // 圆形（小圆球核心样式）\r\n    ball.style.position = "absolute";\r\n    ball.style.pointerEvents = "none"; // 不遮挡交互\r\n    ball.style.zIndex = "9999"; // 提高层级，避免被其他元素遮挡\r\n    ball.style.willChange = "transform, opacity"; // 开启硬件加速\r\n    ball.style.left = "0px";\r\n    ball.style.top = "0px";\r\n\r\n    // 设置小圆球颜色和初始样式\r\n    ball.style.backgroundColor = color; // 小球颜色，默认红色，可自定义\r\n    ball.style.transform = `translate(${clickX - 8}px, ${clickY - 8}px) scale(1)`;\r\n    ball.style.opacity = "1";\r\n\r\n    // 4. 添加小圆球到动画容器\r\n    container.appendChild(ball);\r\n\r\n    const travelDuration = Math.max(0, Math.floor(finalOptions.duration * 0.84));\r\n    const bounceDuration = finalOptions.duration - travelDuration;\r\n\r\n    const duration = travelDuration;\r\n    const startX = clickX;\r\n    const startY = clickY;\r\n    const endX = targetX + 8; // 回到中心坐标再减去 8 的偏移，前面 transform 已经做了 -8\r\n    const endY = targetY + 8;\r\n    const midX = (startX + endX) / 2;\r\n    const marginTop = 24;\r\n    const marginBottom = 24;\r\n    const viewportH = window.innerHeight || document.documentElement.clientHeight || 800;\r\n    const clampY = (yy: number) => Math.max(marginTop, Math.min(yy, viewportH - marginBottom));\r\n    const desiredArc = Math.max(80, Math.abs(endX - startX) * 0.3);\r\n    const maxArc = Math.max(10, Math.min(desiredArc, Math.min(startY, endY) - marginTop));\r\n    const controlX = midX;\r\n    const controlY = clampY(Math.min(startY, endY) - maxArc);\r\n    const startTime = performance.now();\r\n    const ease = (t: number) => {\r\n      const p1y = 0.67,\r\n        p2y = 0.67;\r\n      const u = 1 - t;\r\n      const y = u * u * u * 0 + 3 * u * u * t * p1y + 3 * u * t * t * p2y + t * t * t * 1;\r\n      return y;\r\n    };\r\n\r\n    const step = (now: number) => {\r\n      const rawT = Math.min((now - startTime) / duration, 1);\r\n      const t = ease(rawT);\r\n      const invT = 1 - t;\r\n      const x = invT * invT * startX + 2 * invT * t * controlX + t * t * endX;\r\n      let y = invT * invT * startY + 2 * invT * t * controlY + t * t * endY;\r\n      y = clampY(y);\r\n      const scale = 1 - 0.3 * t;\r\n      const opacity = 1 - 0.6 * t;\r\n      ball.style.transform = `translate(${x - 8}px, ${y - 8}px) scale(${scale})`;\r\n      ball.style.opacity = String(opacity);\r\n\r\n      if (rawT < 1) {\r\n        requestAnimationFrame(step);\r\n      } else {\r\n        const overshoot = 10;\r\n        const dirX = endX - startX;\r\n        const dirY = endY - startY;\r\n        const len = Math.max(1, Math.hypot(dirX, dirY));\r\n        const ox = (dirX / len) * overshoot;\r\n        let oy = (dirY / len) * overshoot;\r\n        if (oy < 0) {\r\n          const availableTop = endY - marginTop;\r\n          oy = -Math.min(Math.abs(oy), Math.max(0, availableTop));\r\n        }\r\n        const bounceStart = performance.now();\r\n        const bounceStep = (now2: number) => {\r\n          const tb = Math.min((now2 - bounceStart) / bounceDuration, 1);\r\n          let bx, by;\r\n          if (tb < 0.5) {\r\n            const p = ease(tb * 2);\r\n            bx = endX + ox * p;\r\n            by = clampY(endY + oy * p);\r\n          } else {\r\n            const p = ease((tb - 0.5) * 2);\r\n            bx = endX + ox * (1 - p);\r\n            by = clampY(endY + oy * (1 - p));\r\n          }\r\n          const bScale = 0.7 + 0.3 * (1 - tb);\r\n          const bOpacity = 0.4 + 0.6 * (1 - tb);\r\n          ball.style.transform = `translate(${bx - 8}px, ${by - 8}px) scale(${bScale})`;\r\n          ball.style.opacity = String(bOpacity);\r\n          if (tb < 1) {\r\n            requestAnimationFrame(bounceStep);\r\n          } else {\r\n            if (container.contains(ball)) container.removeChild(ball);\r\n            cartCount.value++;\r\n          }\r\n        };\r\n        requestAnimationFrame(bounceStep);\r\n      }\r\n    };\r\n    requestAnimationFrame(step);\r\n  };\r\n\r\n  // 8. 节流包装动画方法，避免重复触发\r\n  const throttledTriggerCartAnimation = throttle(triggerCartAnimation, finalOptions.throttleTime);\r\n\r\n  // 9. 暴露对外方法和状态\r\n  return {\r\n    animateContainer,\r\n    cartCount,\r\n    throttledTriggerCartAnimation,\r\n    triggerCartAnimation,\r\n  };\r\n}\r\n\r\n// 1. 定义购物车目标元素 Ref（绑定到视图中的购物车）\r\nconst cartTarget = ref(null);\r\n\r\n// 共享购物车数量\r\nconst { cartCount, refresh } = useCartCount();\r\n\r\n// 2. 引入并使用封装的购物车动画 Composables\r\nconst {\r\n  animateContainer, // 动画容器 Ref\r\n  throttledTriggerCartAnimation, // 节流后的动画触发方法\r\n} = useCartAnimation({\r\n  cartTarget, // 传入购物车目标元素\r\n  cartCount, // 传入共享 ref，动画完成时自动 +1\r\n  duration: 800, // 动画时长（0.5s）\r\n  throttleTime: 500, // 节流时间（可选，默认 500ms）\r\n});\r\n\r\nonMounted(() => {\r\n  refresh();\r\n});\r\n\r\n// 3. 点击按钮触发动画\r\nconst addToCart = (event) => {\r\n  // 调用 Composables 提供的方法，传入点击事件和小圆球颜色（可选）\r\n  throttledTriggerCartAnimation(event, "var(--el-color-primary)"); // 蓝色小圆球\r\n};\r\n\r\n$common.addToCart = addToCart;\r\n</script>\r\n\r\n<style scoped>\r\n/* 关键：动画容器纯 CSS 样式，保证小球不被遮挡、正常渲染 */\r\n.animate-container {\r\n  position: fixed;\r\n  top: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  left: 0; /* 替换 UnoCSS 的 inset-0，纯 CSS 实现全屏固定 */\r\n  pointer-events: none; /* 不遮挡其他交互 */\r\n  z-index: 9998; /* 低于小球的 9999，保证小球在最上层 */\r\n}\r\n.el-badge__content {\r\n  transition: all 0.3s ease;\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\nconst _hoisted_1 = {\n  class: "cart-animation-demo"\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst unref = ___magic__import__(\'vue\', \'unref\');\r\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\nconst useElementBounding = ___magic__import__(\'@vueuse/core\', \'useElementBounding\');\nconst throttle = ___magic__import__(\'lodash-es\', \'throttle\');\nconst useRegisterModal = ___magic__import__(\'@/composables\', \'useRegisterModal\');\r\nconst useCartCount = ___magic__import__(\'@/composables\', \'useCartCount\');\n\n// 申请单登记弹框\n\nconst __sfc__ = _defineComponent({\n  __name: \'f686482b0834aebb374a730e78adc01b\',\n  setup(__props) {\n    const {\n      openRegisterModal\n    } = useRegisterModal();\n    const open = () => {\n      openRegisterModal({\n        registerClass: "car-apply",\n        registerData: {}\n      });\n    };\n    function useCartAnimation(options = {}) {\n      // 默认配置\n      const defaultOptions = {\n        duration: 500,\n        throttleTime: 500\n      };\n      const finalOptions = {\n        ...defaultOptions,\n        ...options\n      };\n\n      // 动画容器 Ref（需在视图中绑定）\n      const animateContainer = ref(null);\n      // 购物车数量（使用外部传入的共享 ref，若未传则降级为局部 ref）\