INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018613212184383488','2018593486175539200','tag-drawer','<template>\r\n  <el-drawer\r\n    v-model="isVisible"\r\n    :title="drawerTitle"\r\n    size="800"\r\n    :close-on-click-modal="false"\r\n    @close="handleCancel"\r\n  >\r\n    <div class="tag-content">\r\n      <u-title name="选择标签类型"></u-title>\r\n      <div class="mode-selection">\r\n        <div\r\n          v-for="mode in modes"\r\n          :key="mode.id"\r\n          :class="[\'mode-card\', { active: selectedMode === mode.id }]"\r\n          :style="{ cursor: readOnly ? \'not-allowed\' : \'pointer\' }"\r\n          @click="!readOnly && (selectedMode = mode.id)"\r\n        >\r\n          <div :class="[\'icon-wrapper\', { active: selectedMode === mode.id }]">\r\n            <Icon :icon="mode.icon" :color="mode.iconColor" :size="24"></Icon>\r\n          </div>\r\n          <div class="mode-info">\r\n            <h4 :class="{ active: selectedMode === mode.id }">{{ mode.name }}</h4>\r\n            <p :title="mode.desc">{{ mode.desc }}</p>\r\n          </div>\r\n          <div v-if="selectedMode === mode.id" class="check-icon flex items-center">\r\n            <Icon icon="el-icon-CircleCheckFilled" :size="18"></Icon>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <JsonForm\r\n        ref="jsonFormRef"\r\n        class="mt-4 w-full"\r\n        :options="formOptions"\r\n        :rules="formRules"\r\n      ></JsonForm>\r\n      <u-title name="规则逻辑配制" class="mt-4"></u-title>\r\n      <code-editor\r\n        v-model="scriptCode"\r\n        :read-only="readOnly"\r\n        :lang="\'sql\'"\r\n        style="height: 300px"\r\n      ></code-editor>\r\n      <u-title name="标签值" class="mt-4"></u-title>\r\n      <div class="flex gap-2 w-full" style="flex-wrap: wrap">\r\n        <el-tag\r\n          v-for="tag in dynamicTags"\r\n          :key="tag"\r\n          :closable="!readOnly"\r\n          :disable-transitions="false"\r\n          @close="!readOnly && handleClose(tag)"\r\n        >\r\n          {{ tag }}\r\n        </el-tag>\r\n        <el-input\r\n          v-if="inputVisible && !readOnly"\r\n          ref="InputRef"\r\n          v-model="inputValue"\r\n          style="width: 80px"\r\n          size="small"\r\n          @keyup.enter="handleInputConfirm"\r\n          @blur="handleInputConfirm"\r\n        />\r\n        <el-button v-else-if="!readOnly" class="button-new-tag" size="small" @click="showInput">\r\n          + New Tag\r\n        </el-button>\r\n      </div>\r\n    </div>\r\n    <template #footer>\r\n      <div class="flex gap-3" style="justify-content: end">\r\n        <el-button\r\n          v-if="props.type !== \'detail\'"\r\n          type="primary"\r\n          :disabled="loading"\r\n          @click="handleSave"\r\n        >\r\n          <Icon icon="save" class="mr-2" />\r\n          保存\r\n        </el-button>\r\n        <el-button :icon="\'el-icon-Close\'" @click="handleCancel">取消</el-button>\r\n      </div>\r\n    </template>\r\n  </el-drawer>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, computed, watch, nextTick, h } from "vue";\r\nimport { FormUtils } from "@/utils/form";\r\nimport type { InputInstance } from "element-plus";\r\nimport { useDictStore } from "@/store";\r\n\r\nconst tagUpdateFreq = useDictStore().getDictItems("tagUpdateFreq");\r\n// Props\r\nconst props = defineProps<{\r\n  visible: boolean;\r\n  type: "add" | "detail";\r\n  categoryId: string;\r\n  data?: any;\r\n  treeData: any[];\r\n}>();\r\n\r\n// Emits\r\nconst emit = defineEmits<{\r\n  (e: "close"): void;\r\n}>();\r\n\r\nconst readOnly = computed(() => props.type === "detail");\r\nconst drawerTitle = computed(() => {\r\n  return props.type === "add" ? "创建标签" : "标签详情";\r\n});\r\n\r\n// State\r\nconst isVisible = ref(false);\r\nconst jsonFormRef = ref<any>(null);\r\nconst scriptCode = ref("");\r\nconst selectedMode = ref("0");\r\nconst modes = [\r\n  {\r\n    id: "0",\r\n    name: "基础属性标签",\r\n    desc: "基于原始元数据属性直接映射，适用于性别、地域等静态特征",\r\n    icon: "db",\r\n    iconColor: "#3b82f6",\r\n    // iconColor: "#f97316",\r\n  },\r\n  {\r\n    id: "1",\r\n    name: "行为特征标签",\r\n    desc: "基于多维收祝行为事件进行统计计算，适用于活跃度、偏好等动态特征",\r\n    icon: "shandian",\r\n    iconColor: "#f97316",\r\n    // iconColor: "#3b82f6",\r\n  },\r\n];\r\nconst inputValue = ref("");\r\nconst dynamicTags = ref([]);\r\nconst inputVisible = ref(false);\r\nconst InputRef = ref<InputInstance>();\r\nconst loading = ref(false);\r\nconst formOptions = {\r\n  form: {\r\n    labelWidth: "100px",\r\n  },\r\n};\r\nconst formRules = FormUtils.fixJson([\r\n  {\r\n    type: "UTitle",\r\n    props: {\r\n      name: "基础信息配置",\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    field: "tagName",\r\n    title: "标签名称",\r\n    $required: true,\r\n    props: {\r\n      placeholder: "如：高潜付费受众",\r\n      disabled: readOnly.value,\r\n    },\r\n  },\r\n  {\r\n    field: "tagCode",\r\n    title: "标签标识",\r\n    type: "input",\r\n    $required: true,\r\n    props: {\r\n      disabled: readOnly.value,\r\n    },\r\n    renderSlots: {\r\n      append() {\r\n        return h("div", {\r\n          class: "i-svg:idea cursor-pointer",\r\n          style: "font-size: 18px;",\r\n          title: "点击生成随机标识",\r\n          onClick: async () => {\r\n            jsonFormRef.value.setValue({\r\n              tagCode: `tag_${Math.random().toString(36).substring(2, 10)}`,\r\n            });\r\n          },\r\n        });\r\n      },\r\n    },\r\n  },\r\n  {\r\n    field: "category",\r\n    title: "所属类目",\r\n    type: "cascader",\r\n    props: {\r\n      options: props.treeData,\r\n      props: {\r\n        label: "name",\r\n        value: "tid",\r\n        checkStrictly: true,\r\n        checkOnClickNode: true,\r\n      },\r\n      disabled: readOnly.value,\r\n    },\r\n    style: {\r\n      width: "100%",\r\n    },\r\n  },\r\n  {\r\n    field: "updateFrequency",\r\n    title: "更新频率",\r\n    type: "select",\r\n    props: {\r\n      options: tagUpdateFreq,\r\n      disabled: readOnly.value,\r\n    },\r\n  },\r\n  {\r\n    type: "input",\r\n    field: "description",\r\n    title: "业务描述说明",\r\n    props: {\r\n      type: "textarea",\r\n      maxlength: 255,\r\n      rows: 4,\r\n      disabled: readOnly.value,\r\n      placeholder: "描述该标签的业务意义，核心算法逻辅及建议应用场景...",\r\n    },\r\n  },\r\n]);\r\n\r\nconst handleClose = (tag: string) => {\r\n  dynamicTags.value.splice(dynamicTags.value.indexOf(tag), 1);\r\n};\r\n\r\nconst showInput = () => {\r\n  inputVisible.value = true;\r\n  nextTick(() => {\r\n    InputRef.value!.input!.focus();\r\n  });\r\n};\r\n\r\nconst handleInputConfirm = () => {\r\n  if (inputValue.value) {\r\n    dynamicTags.value.push(inputValue.value);\r\n  }\r\n  inputVisible.value = false;\r\n  inputValue.value = "";\r\n};\r\n\r\n// Initialize form data\r\nconst initFormData = () => {\r\n  if (props.type === "add") {\r\n    nextTick(() => {\r\n      jsonFormRef.value?.clearValue();\r\n      jsonFormRef.value?.setValue({\r\n        category: props.categoryId,\r\n      });\r\n    });\r\n  } else if (props.type === "detail" && props.data) {\r\n    nextTick(() => {\r\n      jsonFormRef.value?.setValue(props.data);\r\n      jsonFormRef.value?.setValue({\r\n        category: props.data.categoryId,\r\n      });\r\n      dynamicTags.value = props.data.tags || [];\r\n      selectedMode.value = props.data.tagType || "0";\r\n      inputVisible.value = false;\r\n    });\r\n  }\r\n};\r\n\r\n// Watch for prop changes\r\nwatch(\r\n  () => props.visible,\r\n  (newVisible) => {\r\n    isVisible.value = newVisible;\r\n    if (newVisible) {\r\n      initFormData();\r\n    }\r\n  },\r\n  { immediate: true }\r\n);\r\n// Handle cancel\r\nconst handleCancel = () => {\r\n  emit("close");\r\n};\r\n\r\n// Handle save\r\nconst handleSave = async () => {\r\n  try {\r\n    loading.value = true;\r\n    const formData = await jsonFormRef.value?.validate().then(() => {\r\n      return jsonFormRef.value?.formData();\r\n    });\r\n    console.log(formData, selectedMode.value, scriptCode.value, dynamicTags.value);\r\n    emit("close", true);\r\n  } catch (error) {\r\n    console.error("保存标签失败:", error);\r\n  } finally {\r\n    loading.value = false;\r\n  }\r\n};\r\n</script>\r\n\r\n<style lang="scss" scoped>\r\n.tag-content {\r\n  width: 100%;\r\n  .mode-selection {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    width: 100%; /* 确保不超出父容器宽度 */\r\n    box-sizing: border-box; /* 确保内边距和边框不增加总宽度 */\r\n\r\n    .mode-card {\r\n      width: 48.5%;\r\n      box-sizing: border-box; /* 确保内边距和边框不增加总宽度 */\r\n      position: relative;\r\n      padding: 1rem;\r\n      border: 1px solid #f1f5f9;\r\n      border-radius: 0.5rem;\r\n      background: white;\r\n      cursor: pointer;\r\n      transition: all 0.2s ease;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 1rem;\r\n\r\n      &:hover {\r\n        border-color: #bfdbfe;\r\n      }\r\n\r\n      &.active {\r\n        border-color: #165dff;\r\n        background: rgba(22, 93, 255, 0.05);\r\n        box-shadow:\r\n          0 1px 3px 0 rgba(0, 0, 0, 0.1),\r\n          0 1px 2px 0 rgba(0, 0, 0, 0.06);\r\n      }\r\n\r\n      .icon-wrapper {\r\n        width: 2.5rem;\r\n        height: 2.5rem;\r\n        border-radius: 0.5rem;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        flex-shrink: 0;\r\n        transition: transform 0.2s ease;\r\n        background: #f1f5f9;\r\n\r\n        &:hover {\r\n          transform: scale(1.05);\r\n        }\r\n\r\n        &.active {\r\n          background: white;\r\n          box-shadow:\r\n            0 1px 3px 0 rgba(0, 0, 0, 0.1),\r\n            0 1px 2px 0 rgba(0, 0, 0, 0.06);\r\n        }\r\n\r\n        svg {\r\n          width: 20px;\r\n          height: 20px;\r\n\r\n          &.orange {\r\n            color: #f97316;\r\n          }\r\n\r\n          &.blue {\r\n            color: #3b82f6;\r\n          }\r\n\r\n          &.purple {\r\n            color: #8b5cf6;\r\n          }\r\n        }\r\n      }\r\n\r\n      .mode-info {\r\n        min-width: 0;\r\n\r\n        h4 {\r\n          font-size: 0.875rem;\r\n          font-weight: 600;\r\n          color: #1e293b;\r\n          margin: 0 0 0.25rem 0;\r\n          overflow: hidden;\r\n          text-overflow: ellipsis;\r\n          white-space: nowrap;\r\n\r\n          &.active {\r\n            color: #165dff;\r\n          }\r\n        }\r\n\r\n        p {\r\n          font-size: 0.6875rem;\r\n          color: #94a3b8;\r\n          margin: 0;\r\n          overflow: hidden;\r\n          text-overflow: ellipsis;\r\n          white-space: nowrap;\r\n        }\r\n      }\r\n\r\n      .check-icon {\r\n        margin-left: auto;\r\n        color: #165dff;\r\n      }\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\r\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', \'normalizeStyle\');\r\nconst _unref = ___magic__import__(\'vue\', \'unref\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\r\nconst _withKeys = ___magic__import__(\'vue\', \'withKeys\');\nconst _hoisted_1 = {\n  class: "tag-content"\n};\nconst _hoisted_2 = {\n  class: "mode-selection"\n};\nconst _hoisted_3 = ["onClick"];\nconst _hoisted_4 = {\n  class: "mode-info"\n};\nconst _hoisted_5 = ["title"];\nconst _hoisted_6 = {\n  key: 0,\n  class: "check-icon flex items-center"\n};\nconst _hoisted_7 = {\n  class: "flex gap-2 w-full",\n  style: {\n    "flex-wrap": "wrap"\n  }\n};\nconst _hoisted_8 = {\n  class: "flex gap-3",\n  style: {\n    "justify-content": "end"\n  }\n};\nconst ref = ___magic__import__(\'vue\', \'ref\');\r\nconst computed = ___magic__import__(\'vue\', \'computed\');\r\nconst watch = ___magic__import__(\'vue\', \'watch\');\r\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\r\nconst h = ___magic__import__(\'vue\', \'h\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst useDictStore = ___magic__import__(\'@/store\', \'useDictStore\');\nconst __sfc__ = _defineComponent({\n  __name: \'31222ccb08c906daa14d031dcc601c08\',\n  props: {\n    visible: {\n      type: Boolean,\n      required: true\n    },\n    type: {\n      type: String,\n      required: true\n    },\n    categoryId: {\n      type: String,\n      required: true\n    },\n    data: {\n      type: null,\n      required: false\n    },\n    treeData: {\n      type: Array,\n      required: true\n    }\n  },\n  emits: ["close"],\n  setup(__props, {\n    emit: __emit\n  }) {\n    const tagUpdateFreq = useDictStore().getDictItems("tagUpdateFreq");\n    // Props\n    const props = __props;\n\n    // Emits\n    const emit = __emit;\n    const readOnly = computed(() => props.type === "detail");\n    const drawerTitle = computed(() => {\n      return props.type === "add" ? "创建标签" : "标签详情";\n    });\n\n    // State\n    const isVisible = ref(false);\n    const jsonFormRef = ref(null);\n    const scriptCode = ref("");\n    const selectedMode = ref("0");\n    const modes = [{\n      id: "0",\n      name: "基础属性标签",\n      desc: "基于原始元数据属性直接映射，适用于性别、地域等静态特征",\n      icon: "db",\n      iconColor: "#3b82f6"\n      // iconColor: "#f97316",\n    }, {\n      id: "1",\n      name: "行为特征标签",\n      desc: "基于多维收祝行为事件进行统计计算，适用于活跃度、偏好等动态特征",\n      icon: "shandian",\n      iconColor: "#f97316"\n      // iconColor: "#3b82f6",\n    }];\n    const inputValue = ref("");\n    const dynamicTags = ref([]);\n    const inputVisible = ref(false);\n    const InputRef = ref();\n    const loading = ref(false);\n    const formOptions = {\n      form: {\n        labelWidth: "100px"\n      }\n    };\n    const formRules = FormUtils.fixJson([{\n      type: "UTitle",\n      props: {\n        name: "基础信息配置"\n      }\n    }, {\n      type: "input",\n      field: "tagName",\n      title: "标签名称",\n      $required: true,\n      props: {\n        placeholder: "如：高潜付费受众",\n        disabled: readOnly.value\n      }\n    }, {\n      field: "tagCode",\n      title: "标签标识",\n      type: "input",\n      $required: true,\n      props: {\n        disabled: readOnly.value\n      },\n      renderSlots: {\n        append() {\n          return h("div", {\n            class: "i-svg:idea cursor-pointer",\n            style: "font-size: 18px;",\n            title: "点击生成随机标识",\n            onClick: async () => {\n              jsonFormRef.value.setValue({\n                tagCode: `tag_${Math.random().toString(36).substring(2, 10)}`\n              });\n            }\n          });\n        }\n      }\n    }, {\n      field: "category",\n      title: "所属类目",\n      type: "cascader",\n      props: {\n        options: props.treeData,\n        props: {\n          label: "name",\n          value: "tid",\n          checkStrictly: true,\n          checkOnClickNode: true\n        },\n        disabled: readOnly.value\n      },\n      style: {\n        width: "100%"\n      }\n    }, {\n      field: "updateFrequency",\n      title: "更新频率",\n      type: "select",\n      props: {\n        options: tagUpdateFreq,\n        disabled: readOnly.value\n      }\n    }, {\n      type: "input",\n      field: "description",\n      title: "业务描述说明",\n      props: {\n        type: "textarea",\n        maxlength: 255,\n        rows: 4,\n        disabled: readOnly.value,\n        placeholder: "描述该标签的业务意义，核心算法逻辅及建议应用场景..."\n      }\n    }]);\n    const handleClose = tag => {\n      dynamicTags.value.splice(dynamicTags.value.indexOf(tag), 1);\n    };\n    const showInput = () => {\n      inputVisible.value = true;\n      nextTick(() => {\n        InputRef.value.input.focus();\n      });\n    };\n    const handleInputConfirm = () => {\n      if (inputValue.value) {\n        dynamicTags.value.push(inputValue.value);\n      }\n      inputVisible.value = false;\n      inputValue.value = "";\n    };\n\n    // Initialize form data\n    const initFormData = () => {\n      if (props.type === "add") {\n        nextTick(() => {\n          jsonFormRef.value?.clearValue();\n          jsonFormRef.value?.setValue({\n            category: props.categoryId\n          });\n        });\n      } else if (props.type === "detail" && props.data) {\n        nextTick(() => {\n          jsonFormRef.value?.setValue(props.data);\n          jsonFormRef.value?.setValue({\n            category: props.data.categoryId\n          });\n          dynamicTags.value = props.data.tags || [];\n          selectedMode.value = props.data.tagType || "0";\n          inputVisible.value = false;\n        });\n      }\n    };\n\n    // Watch for prop changes\n    watch(() => props.visible, newVisible => {\n      isVisible.value = newVisible;\n      if (newVisible) {\n        initFormData();\n      }\n    }, {\n      immediate: true\n    });\n    // Handle cancel\n    const handleCancel = () => {\n      emit("close");\n    };\n\n    // Handle save\n    const handleSave = async () => {\n      try {\n        loading.value = true;\n        const formData = await jsonFormRef.value?.validate().then(() => {\n          return jsonFormRef.value?.formData();\n        });\n        console.log(formData, selectedMode.value, scriptCode.value, dynamicTags.value);\n        emit("close", true);\n      } catch (error) {\n        console.error("保存标签失败:", error);\n      } finally {\n        loading.value = false;\n      }\n    };\n    return (_ctx, _cache) => {\n      const _component_u_title = _resolveComponent("u-title");\n      const _component_Icon = _resolveComponent("Icon");\n      const _component_JsonForm = _resolveComponent("JsonForm");\n      const _component_code_editor = _resolveComponent("code-editor");\n      const _component_el_tag = _resolveComponent("el-tag");\n      const _component_el_input = _resolveComponent("el-input");\n      const _component_el_button = _resolveComponent("el-button");\n      const _component_el_drawer = _resolveComponent("el-drawer");\n      return _openBlock(), _createBlock(_component_el_drawer, {\n        modelValue: isVisible.value,\n        "onUpdate:modelValue": _cache[2] || (_cache[2] = $event => isVisible.value = $event),\n        title: drawerTitle.value,\n        size: "800",\n        "close-on-click-modal": false,\n        onClose: handleCancel\n      }, {\n        footer: _withCtx(() => [_createElementVNode("div", _hoisted_8, [props.type !== \'detail\' ? (_openBlock(), _createBlock(_component_el_button, {\n          key: 0,\n          type: "primary",\n          disabled: loading.value,\n          onClick: handleSave\n        }, {\n          default: _withCtx(() => [_createVNode(_component_Icon, {\n            icon: "save",\n            class: "mr-2"\n          }), _cache[4] || (_cache[4] = _createTextVNode(" 保存 ", -1 /* CACHED */))]),\n          _: 1 /* STABLE */\n        }, 8 /* PROPS */, ["disabled"])) : _createCommentVNode("v-if", true), _createVNode(_component_el_button, {\n          icon: \'el-icon-Close\',\n          onClick: handleCancel\n   