mode-selection .mode-card .mode-info h4[data-v-31222ccb08c906daa14d031dcc601c08] {\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: #1e293b;\n  margin: 0 0 0.25rem 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.tag-content .mode-selection .mode-card .mode-info h4.active[data-v-31222ccb08c906daa14d031dcc601c08] {\n  color: #165dff;\n}\n.tag-content .mode-selection .mode-card .mode-info p[data-v-31222ccb08c906daa14d031dcc601c08] {\n  font-size: 0.6875rem;\n  color: #94a3b8;\n  margin: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.tag-content .mode-selection .mode-card .check-icon[data-v-31222ccb08c906daa14d031dcc601c08] {\n  margin-left: auto;\n  color: #165dff;\n}','1','创建标签抽屉',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2018593486175539200','2013139484096925696','tags-detail','<template>\r\n  <div class="dws-detail card-container flex flex-col px-5 pt-5 pb-2">\r\n    <div class="h-full grid" style="grid-template-columns: 20% 80%">\r\n      <div class="left-panel h-full">\r\n        <div class="left-header flex items-center justify-between">\r\n          <h3>标签分类</h3>\r\n          <el-button type="text" class="left-header-btn" @click="addData">\r\n            <Icon icon="el-icon-plus" />\r\n          </el-button>\r\n        </div>\r\n\r\n        <div class="tree-container">\r\n          <UTree\r\n            ref="treeRef"\r\n            :data="treeData"\r\n            :search="true"\r\n            :expand="false"\r\n            :highlight-current="true"\r\n            :expand-on-click-node="false"\r\n            :search-placeholder="\'请输入关键字\'"\r\n            :default-expand-all="true"\r\n            :default-expanded-keys="[111]"\r\n            class="tree-container-custom"\r\n            @node-click="handleNodeClick"\r\n          >\r\n            <template #node="{ node }">\r\n              <div class="flex items-center">\r\n                <Icon\r\n                  :icon="node.expanded ? \'folder-open\' : \'folder\'"\r\n                  color="#0b8bf9"\r\n                  class="mr-1"\r\n                  size="23"\r\n                />\r\n                {{ node?.label }}\r\n              </div>\r\n            </template>\r\n          </UTree>\r\n        </div>\r\n      </div>\r\n\r\n      <div class="pl-4 flex flex-col h-full w-full">\r\n        <DataTable :columns="tableColumns" :data="tableData" show-index style="height: 100%">\r\n          <template #toolbar>\r\n            <div class="flex justify-between items-center">\r\n              <div class="right-header">\r\n                <span class="header-name">{{ currentNode?.name }}</span>\r\n                <span class="header-num">共{{ serviceCount }}个标签</span>\r\n              </div>\r\n              <div>\r\n                <el-input\r\n                  v-model="searchQuery"\r\n                  :suffix-icon="\'el-icon-Search\'"\r\n                  placeholder="搜索标签名称/标识"\r\n                  clearable\r\n                  class="mr-3"\r\n                  style="width: 250px"\r\n                  @input="handleSearch"\r\n                />\r\n                <el-button type="primary" :icon="\'el-icon-Plus\'" @click="handleCreateTask">\r\n                  创建标签\r\n                </el-button>\r\n              </div>\r\n            </div>\r\n          </template>\r\n          <template #column-tagName="{ row }">\r\n            <el-text type="primary" cursor-pointer @click="handleDetailClick(row, \'detail\')">\r\n              <Icon icon="tag"></Icon>\r\n              {{ row.tagName }}\r\n            </el-text>\r\n          </template>\r\n        </DataTable>\r\n      </div>\r\n    </div>\r\n    <tag-drawer\r\n      v-if="tagDrawerVisible"\r\n      :visible="tagDrawerVisible"\r\n      :type="tagDrawerType"\r\n      :tree-data="treeData"\r\n      :category-id="currentNodeId"\r\n      :data="tagData"\r\n      @close="handleCloseTag"\r\n    />\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, onMounted, nextTick } from "vue";\r\n// import tagDrawer from "./tag-drawer.vue";\r\n\r\nconst treeRef = ref(); // 树组件引用\r\nconst currentNodeId = ref(); // 当前选中的节点tid\r\nconst currentNode = ref(); // 当前操作的节点\r\nconst treeData = ref([\r\n  {\r\n    tid: "1",\r\n    name: "内容管理标签",\r\n    children: [\r\n      {\r\n        parentTid: "1",\r\n        tid: "11",\r\n        name: "内容基础信息",\r\n        children: [\r\n          {\r\n            parentTid: "11",\r\n            tid: "111",\r\n            name: "内容属性",\r\n            type: "content_property",\r\n          },\r\n          {\r\n            pare