perator-component-container .operator-list .operator-item .operator-icon[data-v-d43c31fd2ec0a849ef01a5afbbcb6c00] {\n  width: 25px;\n  height: 25px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  border-radius: 4px;\n}\n.operator-component-container .operator-list .operator-item .operator-icon .el-icon[data-v-d43c31fd2ec0a849ef01a5afbbcb6c00] {\n  font-size: 18px !important;\n}\n.operator-component-container .operator-list .operator-item.operator-item-blue[data-v-d43c31fd2ec0a849ef01a5afbbcb6c00]:hover {\n  background-color: rgba(27, 103, 248, 0.062745098);\n  border-color: #1b67f8;\n}\n.operator-component-container .operator-list .operator-item.operator-item-orange[data-v-d43c31fd2ec0a849ef01a5afbbcb6c00]:hover {\n  background-color: rgba(250, 84, 28, 0.062745098);\n  border-color: #fa541c;\n}\n.operator-component-container .operator-list .operator-item.operator-item-green[data-v-d43c31fd2ec0a849ef01a5afbbcb6c00]:hover {\n  background-color: rgba(6, 161, 126, 0.062745098);\n  border-color: #06a17e;\n}','1','任务面板',NULL,NULL,0,'2084109831678504960',1);
INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2033843576989392896','2033838278811688960','user-manage','<template>\r\n  <div class="user-manage-content card-container px-5 pt-5 pb-2">\r\n    <el-splitter style="width: 100%; height: 100%">\r\n      <!-- 左侧组织结构树 -->\r\n      <el-splitter-panel size="280px" min="10%">\r\n        <div class="left-panel">\r\n          <div class="panel-header">\r\n            <h3>组织架构</h3>\r\n          </div>\r\n          <div class="tree-container">\r\n            <UTree\r\n              ref="treeRef"\r\n              :data="treeData"\r\n              :search="true"\r\n              :expand="false"\r\n              :highlight-current="true"\r\n              :expand-on-click-node="false"\r\n              :search-placeholder="\'搜索部门\'"\r\n              node-key="value"\r\n              class="tree-container-custom"\r\n              @node-click="handleNodeClick"\r\n            ></UTree>\r\n          </div>\r\n        </div>\r\n      </el-splitter-panel>\r\n\r\n      <!-- 右侧用户列表 -->\r\n      <el-splitter-panel>\r\n        <div class="right-panel pl-4">\r\n          <DataTable\r\n            ref="tableRef"\r\n            :columns="tableColumns"\r\n            :data="fetchUserData"\r\n            :show-selection="false"\r\n            :show-index="true"\r\n            :immediate="true"\r\n            style="height: 100%"\r\n          >\r\n            <template #toolbar>\r\n              <div class="flex justify-between items-center w-full">\r\n                <div class="flex">\n                  <el-button type="primary" :icon="\'el-icon-Plus\'" @click="handleAdd">\n                    新增用户\n                  </el-button>\n                </div>\n                <div class="flex items-center gap-2">\n                  <el-input\n                    v-model="searchKeyword"\n                    placeholder="搜索用户名/姓名/手机号"\n                    clearable\n                    class="user-keyword-search"\n                    style="width: 220px"\n                    @keyup.enter="refreshTableData"\n                    @clear="refreshTableData"\n                  >\n                    <template #suffix>\n                      <el-icon class="toolbar-search-icon" title="搜索" @click="refreshTableData"><Search /></el-icon>\n                    </template>\n                  </el-input>\n                  <el-select\n                    v-model="filterOnline"\n                    placeholder="是否在线"\n                    clearable\n                    style="width: 110px"\n                    @change="refreshTableData"\n                  >\n                    <el-option label="在线" :value="true" />\n                    <el-option label="离线" :value="false" />\n                  </el-select>\n                </div>\n              </div>\n            </template>\n\n            <template #column-userName="{ row }">\n              <span class="user-account-cell">\n                <i class="online-status-dot" :class="row.online ? \'online-status-dot--online\' : \'online-status-dot--offline\'" />\n                <span>{{ row.userName || \'-\' }}</span>\n              </span>\n            </template>\n\n            <template #column-realName="{ row }">\n              <button type="button" class="user-name-link" @click="handleDetail(row)">{{ row.realName || \'-\' }}</button>\n            </template>\n\r\n            <!-- 角色列 —— 支持多个角色标签展示 -->\r\n            <template #column-roleNames="{ row }">\r\n              <div v-if="row.roleNames" class="flex flex-wrap gap-1">\r\n                <el-tag\r\n                  v-for="(role, idx) in row.roleNames.split(\',\').filter((r: string) => r)"\r\n                  :key="idx"\r\n                  :type="role === \'超级管理员\' ? undefined : \'info\'"\r\n                  :effect="role === \'超级管理员\' ? \'dark\' : \'plain\'"\r\n                  size="small"\r\n                >\r\n                  {{ role }}\r\n                </el-tag>\r\n              </div>\r\n              <span v-else class="text-gray-400">-</span>\r\n            </template>\r\n\r\n            <!-- 状态开关列 —— 参考 role-manage.vue 模式 -->\r\n            <template #column-status="{ row }">\r\n              <ElSwitch\r\n                :model-value="row.status"\r\n                :active-value="0"\r\n                :inactive-value="1"\r\n                :loading="row._statusLoading"\r\n                @click.prevent="handleStatusClick(row)"\r\n              ></ElSwitch>\r\n            </template>\r\n          </DataTable>\r\n        </div>\r\n      </el-splitter-panel>\r\n    </el-splitter>\r\n\r\n    <!-- 用户新增/详情抽屉 -->\n    <el-drawer\n      v-model="drawerVisible"\n      size="700"\n      :close-on-click-modal="true"\n      @close="handleDrawerClose"\n    >\n      <template #header>\n        <el-tabs v-model="drawerTab" class="drawer-tabs" @tab-change="handleDrawerTabChange">\n          <el-tab-pane label="用户详情" name="detail" />\n          <el-tab-pane label="用户角色" name="roles" :disabled="!currentUserId" />\n        </el-tabs>\n      </template>\n      <div class="px-4">\n        <!--\n          Keep the form mounted while browsing roles. JsonForm owns the entered\n          values internally, so a v-if here used to destroy the detail state\n          and recreate an empty form when the user returned to this tab.\n        -->\n        <JsonForm v-show="drawerTab === \'detail\'" ref="jsonFormRef" :rules="formRules" :options="formOptions" />\n\n        <section v-if="drawerTab === \'roles\'" class="user-roles-panel" v-loading="roleLoading">\n          <div class="role-panel-tip">勾选后保存即可更新该用户关联的角色。</div>\n          <el-checkbox-group v-if="roleOptions.length" v-model="selectedRoleIds" class="role-checkbox-list">\n            <el-checkbox v-for="role in roleOptions" :key="role.id" :label="role.id" border class="role-checkbox">\n              <span class="role-checkbox__name">{{ role.name }}</span>\n              <span v-if="role.codeNum" class="role-checkbox__code">{{ role.codeNum }}</span>\n              <el-tag v-if="role.status === 1" type="info" size="small">已禁用</el-tag>\n            </el-checkbox>\n          </el-checkbox-group>\n          <el-empty v-else-if="!roleLoading" description="暂无可关联角色" :image-size="96" />\n        </section>\n      </div>\n      <template #footer>\n        <div class="flex justify-end">\n          <el-button :icon="\'el-icon-Close\'" @click="drawerVisible = false">取消</el-button>\n          <el-button v-if="drawerTab === \'detail\'" type="primary" :loading="saveLoading" @click="handleSave">\n            <Icon icon="save" class="mr-2" />\n            保存\n          </el-button>\n          <el-button v-else type="primary" :loading="roleSaving" @click="handleSaveRoles">\n            <Icon icon="save" class="mr-2" />\n            保存角色\n          </el-button>\n        </div>\n      </template>\n    </el-drawer>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref, nextTick, h, onMounted } from "vue";\nimport { ElMessage, ElSwitch } from "element-plus";\nimport { Search } from "@element-plus/icons-vue";\nimport type { UploadRequestOptions } from "element-plus";\r\nimport { FormUtils } from "@/utils/form";\r\nimport type { UColumnProps } from "@/components/data/data-table.vue";\r\nimport request from "@/utils/request";\r\nimport { default as pinyin } from "js-pinyin";\r\n\r\nconst currentNode = ref<any>(null);\r\n\r\n/** 上传成功的头像文件 id，保存时直接读取此值，避免从表单 upload 字段解析 */\r\nconst uploadedAvatarId = ref<string>("");\r\n\r\n/** 根据 fileId 通过 axios（自动携带 token 头）获取图片，返回 Data URL */\r\nconst fetchAvatarUrl = async (fileId: string): Promise<string> => {\r\n  try {\r\n    // 后端返回标准 JSON：{ content: "base64...", contentType: "image/png", fileName: "xxx.png" }\r\n    const res = await request.get("/sym/file/preview", {\r\n      params: { id: fileId },\r\n    });\r\n    if (!res || !res.content) {\r\n      console.warn("[fetchAvatarUrl] 返回数据为空");\r\n      return "";\r\n    }\r\n    // 直接拼接 Data URL\r\n    return `data:${res.contentType || "image/png"};base64,${res.content}`;\r\n  } catch (e: any) {\r\n    console.error("获取头像失败:", e);\r\n    return "";\r\n  }\r\n};\r\n\r\nconst treeData = ref<any[]>([\r\n  {\r\n    name: "全部",\r\n    value: "",\r\n    children: [],\r\n  },\r\n]);\r\n\r\n/** 获取组织机构树 */\r\nconst fetchOrgTree = async () => {\r\n  try {\r\n    const res = await $common.post("/sym/org/getOrgTree", {\r\n      parentId: $user.orgRootId,\r\n    });\r\n    treeData.value[0].children = res?.data ?? res ?? [];\r\n  } catch (e) {\r\n    console.error("获取组织机构树失败:", e);\r\n    treeData.value[0].children = [];\r\n  }\r\n};\r\n\r\nonMounted(() => {\r\n  fetchOrgTree();\r\n});\r\n\r\nconst handleNodeClick = (node: any) => {\r\n  currentNode.value = node;\r\n  refreshTableData();\r\n};\r\n\r\n// ===================== 右侧表格 =====================\r\nconst tableRef = ref();\nconst searchKeyword = ref("");\nconst filterOnline = ref<boolean | "">("");\nconst currentUserId = ref("");\n\ntype OnlineUsers = {\n  ids: Set<string>;\n  userNames: Set<string>;\n};\n\nlet onlineUsersCache: OnlineUsers | null = null;\nlet onlineUsersCacheTime = 0;\nconst onlineUsersCacheTtl = 15 * 1000;\n\n/** 查询当前租户全部有效在线会话，并汇总为用户状态。 */\nconst fetchOnlineUsers = async (): Promise<OnlineUsers> => {\n  if (onlineUsersCache && Date.now() - onlineUsersCacheTime < onlineUsersCacheTtl) {\n    return onlineUsersCache;\n  }\n\n  const ids = new Set<string>();\n  const userNames = new Set<string>();\n  const pageSize = 200;\n  let pageNum = 1;\n  let total = 0;\n\n  do {\n    const response = await $common.post("/sym/user/online/page", { pageNum, pageSize });\n    const data = response?.data || response || {};\n    const rows = data.list || [];\n    total = Number(data.total || 0);\n    rows.forEach((session: any) => {\n      if (session.loginId != null) ids.add(`${session.loginId}`);\n      if (session.userName) userNames.add(`${session.userName}`);\n    });\n    if (!rows.length) break;\n    pageNum += 1;\n  } while ((pageNum - 1) * pageSize < total);\n\n  onlineUsersCache = { ids, userNames };\n  onlineUsersCacheTime = Date.now();\n  return onlineUsersCache;\n};\n\nconst isUserOnline = (user: any, onlineUsers: OnlineUsers) =>\n  onlineUsers.ids.has(`${user.id}`) || onlineUsers.userNames.has(`${user.userName || ""}`);\n\nconst buildUserParams = (pageNum: number, pageSize: number): Record<string, any> => {\n  const params: Record<string, any> = { pageNum, pageSize };\n  if (currentNode.value?.id) params.orgId = currentNode.value.id;\n  if (searchKeyword.value) params.realName = searchKeyword.value;\n  return params;\n};\n\nconst requestUserPage = async (pageNum: number, pageSize: number) => {\n  const response = await $common.post("/sym/user/page", buildUserParams(pageNum, pageSize));\n  return response.data || response || {};\n};\n\n/** 分页查询用户 */\nconst fetchUserData = async ({\n  pageNo: pageNum,\r\n  pageSize,\r\n}: {\r\n  pageNo: number;\r\n  pageSize: number;\r\n}) => {\n  try {\n    const onlineUsers = await fetchOnlineUsers();\n\n    if (filterOnline.value !== "") {\n      const allUsers: any[] = [];\n      const queryPageSize = 200;\n      let queryPageNum = 1;\n      let total = 0;\n      do {\n        const data = await requestUserPage(queryPageNum, queryPageSize);\n        const rows = data.list || [];\n        total = Number(data.total || 0);\n        allUsers.push(...rows);\n        if (!rows.length) break;\n        queryPageNum += 1;\n      } while ((queryPageNum - 1) * queryPageSize < total);\n\n      const rows = allUsers\n        .map((user) => ({ ...user, online: isUserOnline(user, onlineUsers) }))\n        .filter((user) => user.online === filterOnline.value);\n      const start = (pageNum - 1) * pageSize;\n      return { list: rows.slice(start, start + pageSize), total: rows.length };\n    }\n\n    const data = await requestUserPage(pageNum, pageSize);\n    return {\n      list: (data.list || []).map((user: any) => ({ ...user, online: isUserOnline(user, onlineUsers) })),\n      total: data.total || 0,\n    };\n  } catch (e) {\r\n    console.error("获取用户列表失败:", e);\r\n    return { list: [], total: 0 };\r\n  }\r\n};\r\n\r\nconst tableColumns = ref<UColumnProps[]>([\r\n  {\r\n    prop: "userName",\r\n    label: "用户账号",\r\n    showOverflowTooltip: true,\r\n  },\r\n  {\r\n    prop: "realName",\r\n    label: "姓名",\r\n  },\r\n  {\r\n    prop: "phone",\r\n    label: "手机号",\r\n    width: 130,\r\n  },\r\n  {\r\n    prop: "roleNames",\r\n    label: "角色",\r\n    minWidth: 130,\r\n  },\r\n  {\r\n    prop: "status",\r\n    label: "状态",\r\n    width: 80,\r\n  },\r\n  {\r\n    prop: "createTime",\r\n    label: "创建时间",\r\n    width: 170,\r\n  },\r\n  {\n    prop: "operation",\n    label: "操作",\n    width: 80,\n    fixed: "right",\n    buttons: [\n      {\n        label: "删除",\n        type: "danger",\n        click: (row: any) => handleDelete(row),\n      },\n    ],\r\n  },\r\n]);\r\n\r\nconst refreshTableData = () => {\r\n  tableRef.value?.refresh(false);\r\n};\r\n\r\n/** 状态切换 */\r\nconst handleStatusClick = async (row: any) => {\r\n  // @click.prevent 阻止了开关本身切换，手动计算目标状态：0↔1 互切\r\n  const targetStatus = row.status == 0 ? 1 : 0;\r\n  row._statusLoading = true;\r\n  try {\r\n    await $common.post("/sym/user/saveOrUpdate", {\r\n      ...row,\r\n      status: targetStatus,\r\n    });\r\n    row.status = targetStatus;\r\n    ElMessage.success(`已${targetStatus == 0 ? "启用" : "禁用"}`);\r\n  } catch (e: any) {\r\n    if (e?.message) ElMessage.error(e.message);\r\n  } finally {\r\n    row._statusLoading = false;\r\n  }\r\n};\r\n\r\n/** 删除用户 */\r\nconst handleDelete = (row: any) => {\r\n  $common.handle({\r\n    url: "/sym/user/delete",\r\n    info: `确定要删除用户 "${row.realName || row.userName}" 吗？`,\r\n    data: { id: row.id },\r\n    done: () => refreshTableData(),\r\n  });\r\n};\r\n\r\n// ===================== 抽屉表单 =====================\r\nconst drawerVisible = ref(false);\nconst drawerType = ref<"add" | "detail">("add");\nconst drawerTab = ref<"detail" | "roles">("detail");\nconst jsonFormRef = ref<any>(null);\nconst saveLoading = ref(false);\nconst roleLoading = ref(false);\nconst roleSaving = ref(false);\nconst roleOptions = ref<any[]>([]);\nconst selectedRoleIds = ref<string[]>([]);\n\nconst loadUserRoles = async () => {\n  if (!currentUserId.value) {\n    roleOptions.value = [];\n    selectedRoleIds.value = [];\n    return;\n  }\n  try {\n    roleLoading.value = true;\n    const [optionsResponse, selectedResponse] = await Promise.all([\n      $common.post("/sym/user/role-options", {}),\n      $common.post("/sym/user/roles", { userId: currentUserId.value }),\n    ]);\n    const optionsData = optionsResponse?.data || optionsResponse || {};\n    const selectedData = selectedResponse?.data || selectedResponse || {};\n    roleOptions.value = optionsData.list || [];\n    selectedRoleIds.value = (selectedData.roleIds || []).map((id: any) => `${id}`);\n  } catch (e: any) {\n    console.error("获取用户角色失败:", e);\n    ElMessage.error("获取用户角色失败");\n    roleOptions.value = [];\n    selectedRoleIds.value = [];\n  } finally {\n    roleLoading.value = false;\n  }\n};\n\nconst handleDrawerTabChange = (tab: string | number) => {\n  if (tab === "roles") loadUserRoles();\n};\n\nconst handleSaveRoles = async () => {\n  if (!currentUserId.value) return;\n  try {\n    roleSaving.value = true;\n    await $common.post("/sym/user/saveRoles", {\n      userId: currentUserId.value,\n      roleIds: selectedRoleIds.value,\n    });\n    ElMessage.success("用户角色已保存");\n    refreshTableData();\n  } catch (e: any) {\n    console.error("保存用户角色失败:", e);\n    ElMessage.error(e?.message || "保存用户角色失败");\n  } finally {\n    roleSaving.value = false;\n  }\n};\n\r\nconst handleAdd = () => {\n  drawerType.value = "add";\n  drawerTab.value = "detail";\n  currentUserId.value = "";\n  roleOptions.value = [];\n  selectedRoleIds.value = [];\n  passwordValue.value = "";\n  uploadedAvatarId.value = "";\n  uploadedDataUrl.value = "";\n  drawerVisible.value = true;\r\n  nextTick(() => {\r\n    jsonFormRef.value?.clearValue?.();\r\n    jsonFormRef.value?.setValue?.({ status: 0 });\r\n  });\r\n};\r\n\r\n/** 详情回填 */\r\nconst handleDetail = async (row: any) => {\n  drawerType.value = "detail";\n  drawerTab.value = "detail";\n  currentUserId.value = row.id || "";\n  roleOptions.value = [];\n  selectedRoleIds.value = [];\n  drawerVisible.value = true;\r\n  await nextTick();\r\n  jsonFormRef.value?.clearValue?.();\r\n\r\n  // 编辑模式：用已有头像文件 id 初始化 ref\r\n  uploadedAvatarId.value = row.appFileId || "";\r\n\r\n  // 头像回显：通过 axios 携带 token 头获取 Data URL，传给 el-upload 文件列表\r\n  let appFileId: any[] = [];\r\n  if (row.appFileId) {\r\n    const url = await fetchAvatarUrl(row.appFileId);\r\n    if (url) {\r\n      appFileId = [\r\n        {\r\n          url,\r\n          name: row.realName || "avatar",\r\n          id: row.appFileId,\r\n        },\r\n      ];\r\n    }\r\n  }\r\n  passwordValue.value = "";\n  jsonFormRef.value?.setValue?.({ ...row, password: "", appFileId, confirmPassword: "" });\n};\n\r\nconst handleDrawerClose = () => {\n  uploadedAvatarId.value = "";\n  uploadedDataUrl.value = "";\n  drawerTab.value = "detail";\n  roleOptions.value = [];\n  selectedRoleIds.value = [];\n  drawerVisible.value = false;\n};\r\n\r\n/** 保存用户 —— 表单字段与 API 字段一致，直接透传 */\r\nconst handleSave = async () => {\r\n  try {\r\n    saveLoading.value = true;\r\n    const formData = await jsonFormRef.value?.getFormData(true);\r\n    if (!formData) return;\r\n\r\n    const payload: Record<string, any> = { ...formData };\r\n\r\n    delete payload.confirmPassword;\r\n\r\n    payload.appFileId = uploadedAvatarId.value || undefined;\n    if (!payload.orgId) {\n      ElMessage.error("请选择所属机构");\n      return;\n    }\n\r\n    // 编辑模式传 id\r\n    if (currentUserId.value) {\r\n      payload.id = currentUserId.value;\r\n    }\r\n\r\n    await $common.post("/sym/user/saveOrUpdate", payload);\r\n    ElMessage.success(drawerType.value === "add" ? "创建成功" : "保存成功");\r\n    drawerVisible.value = false;\r\n    refreshTableData();\r\n  } catch (e: any) {\r\n    console.error(e);\r\n  } finally {\r\n    saveLoading.value = false;\r\n  }\r\n};\r\n\r\n// 用于确认密码校验的响应式密码引用\r\nconst passwordValue = ref("");\r\n\r\n// 正则表达式缓存\r\nconst phoneRegex = /^1[3-9]\\d{9}$/;\r\nconst idCardRegex = /^\\d{17}[\\dXx]$/;\r\n\r\n// 姓名转拼音缓存\r\nconst pinyinCache = new Map<string, string>();\r\n\r\n// 姓名转拼音账号\r\nconst nameToPinyin = (name: string): string => {\r\n  if (!name) return "";\r\n\r\n  if (pinyinCache.has(name)) {\r\n    return pinyinCache.get(name)!;\r\n  }\r\n\r\n  try {\r\n    const result = pinyin.getCamelChars?.(name);\r\n    const pinyinResult = (result || "").toLowerCase();\r\n    pinyinCache.set(name, pinyinResult);\r\n    return pinyinResult;\r\n  } catch {\r\n    return "";\r\n  }\r\n};\r\n\r\nconst formOptions = {\r\n  form: {\r\n    labelWidth: "100px",\r\n    colon: true,\r\n  },\r\n};\r\n\r\n/** 上传成功后的 data URL 缓存 */\r\nconst uploadedDataUrl = ref<string>("");\r\n\r\n/** 自定义头像上传 */\r\nconst customUpload = async (options: UploadRequestOptions) => {\r\n  try {\r\n    // FileReader 读取完整 data URL（含 "data:image/xxx;base64," 前缀）\r\n    // 同时用于：1) 提取 base64 上传  2) 作为缩略图预览地址（自包含，无需认证，无生命周期问题）\r\n    const dataUrl = await new Promise<string>((resolve, reject) => {\r\n      const reader = new FileReader();\r\n      reader.onload = () => resolve(reader.result as string);\r\n      reader.onerror = reject;\r\n      reader.readAsDataURL(options.file);\r\n    });\r\n\r\n    const base64 = dataUrl.split(",")[1];\r\n\r\n    // 直接 JSON POST，无需 FormData / Content-Type 特殊处理\r\n    const res = await request.post("/sym/file/upload", {\r\n      file_name: options.file.name,\r\n      content: base64,\r\n    });\r\n\r\n    // 如果之前有头像文件（编辑模式替换头像），删除旧文件避免产生孤儿记录\r\n    const oldFileId = uploadedAvatarId.value;\r\n    if (oldFileId) {\r\n      try {\r\n        await $common.post("/sym/file/delete", { id: oldFileId });\r\n      } catch (e) {\r\n        console.error("删除旧头像文件失败:", e);\r\n      }\r\n    }\r\n\r\n    // 存文件 id 到 ref（保存时直接读取）\r\n    uploadedAvatarId.value = res.id;\r\n\r\n    // 缓存 data URL，供 onSuccess 回调修复 file.url 使用\r\n    uploadedDataUrl.value = dataUrl;\r\n    options.onSuccess({ ...res, url: dataUrl });\r\n  } catch (e: any) {\r\n    const msg = e?.response?.data?.message || e?.message || "上传失败";\r\n    options.onError(new Error(msg));\r\n  }\r\n};\r\n\r\nconst formRules = FormUtils.fixJson([\r\n  // ---- 基本信息标题 ----\r\n  {\r\n    type: "UTitle",\r\n    props: { name: "基本信息" },\r\n  },\r\n  {\n    field: "orgId",\n    title: "所属机构",\n    type: "cascader",\n    $dict: "org",\n    $required: true,\n    props: {\n      props: {\n        // 机构树既可选择叶子部门，也允许把任意上级机构作为用户所属机构。\n        // emitPath 保持为 false，后端继续接收单个 orgId，不改变保存接口的数据格式。\n        checkStrictly: true,\n        emitPath: false,\n      },\n      placeholder: "请选择所属机构",\n      clearable: true,\n    },\n    class: "w-full",\n  },\n  {\n    field: "realName",\n    title: "用户姓名",\r\n    type: "input",\r\n    $required: true,\r\n    props: { placeholder: "请输入用户姓名" },\r\n    inject: true,\r\n    on: {\r\n      change: (inject: any, val: string) => {\r\n        const account = nameToPinyin(val);\r\n        if (account) {\r\n          inject.api.setValue("userName", account);\r\n        }\r\n      },\r\n    },\r\n  },\r\n  {\r\n    field: "phone",\r\n    title: "手机号码",\r\n    type: "input",\r\n    $required: true,\r\n    props: { placeholder: "请输入手机号码" },\r\n    validate: [\r\n      {\r\n          "type": "string",\r\n          "message": "请输入正确的手机号码",\r\n          "pattern": $common.regexps.phone\r\n      }\r\n    ],\r\n  },\r\n  {\r\n    field: "userName",\r\n    title: "用户账号",\r\n    type: "input",\r\n    $required: true,\r\n    props: { placeholder: "请输入用户账号" },\r\n    renderSlots: {\r\n      append() {\r\n        return h("div", {\r\n          class: "i-svg:idea cursor-pointer",\r\n          style: "font-size: 18px;",\r\n          title: "根据姓名自动生成",\r\n        });\r\n      },\r\n    },\r\n  },\r\n  {\n    field: "password",\n    title: "密码",\n    type: "input",\n    props: { placeholder: "新增必填，详情留空不修改", type: "password", showPassword: true },\n    inject: true,\n    on: {\n      change: (_inject: any, val: string) => {\n        passwordValue.value = val;\n      },\n    },\n    validate: [\n      {\n        validator: (_rule: any, value: string, callback: any) => {\n          const password = value == null ? "" : `${value}`;\n          if (drawerType.value === "add" && !password) {\n            return callback(new Error("请输入密码"));\n          }\n          callback();\n        },\n        trigger: "blur",\n      },\n    ],\n    renderSlots: {\n      append() {\r\n        return h("div", {\r\n          class: "i-svg:copy cursor-pointer",\r\n          style: "font-size: 18px;",\r\n          title: "复制密码",\r\n          onClick: () => {\r\n            $common.copyText(passwordValue.value);\r\n          },\r\n        });\r\n      },\r\n    },\r\n  },\r\n  {\n    field: "confirmPassword",\n    title: "确认密码",\n    type: "input",\n    props: { placeholder: "请再次输入新密码", type: "password", showPassword: true },\n    validate: [\n      {\n        validator: (_rule: any, value: string, callback: any) => {\n          const password = passwordValue.value || "";\n          if (!password && drawerType.value !== "add") return callback();\n          if (!value) return callback(new Error("请输入确认密码"));\n          if (value !== password) return callback(new Error("两次密码不一致"));\n          callback();\n        },\n        trigger: "blur",\r\n      },\r\n    ],\r\n  },\r\n  {\r\n    field: "status",\r\n    title: "账号状态",\r\n    type: "switch",\r\n    value: 0,\r\n    props: {\r\n      activeValue: 0,\r\n      inactiveValue: 1,\r\n    },\r\n    options: [\r\n      { label: "启用", value: 0 },\r\n      { label: "禁用", value: 1 },\r\n    ],\r\n  },\r\n\r\n  // ---- 其他信息标题 ----\r\n  {\r\n    type: "UTitle",\r\n    props: { name: "其他信息" },\r\n  },\r\n  // 编制 + 职级\r\n  {\r\n    field: "authorizedStrength",\r\n    title: "编制",\r\n    type: "switch",\r\n    value: "0",\r\n    props: {\r\n      activeValue: "0",\r\n      inactiveValue: "1",\r\n    },\r\n    options: [\r\n      { label: "是", value: "0" },\r\n      { label: "否", value: "1" },\r\n    ],\r\n  },\r\n  {\r\n    field: "originPosition",\r\n    title: "职级",\r\n    type: "dictSelect",\r\n    props: { placeholder: "请选择职级", options: "jobLevel", clearable: true },\r\n  },\r\n  // 职称 + 办公地址\r\n  {\r\n    field: "originRank",\r\n    title: "职称",\r\n    type: "dictSelect",\r\n    props: { placeholder: "请选择职称", options: "jobTitle", clearable: true },\r\n  },\r\n  {\r\n    field: "officeAddress",\r\n    title: "办公地址",\r\n    type: "input",\r\n    props: { placeholder: "请输入办公地址" },\r\n  },\r\n  {\r\n    field: "idCard",\r\n    title: "身份证号",\r\n    type: "input",\r\n    props: { placeholder: "请输入身份证号" },\r\n    validate: [\r\n      {\r\n        validator: (_rule: any, value: string, callback: any) => {\r\n          if (!value) return callback();\r\n          if (!idCardRegex.test(value)) return callback(new Error("身份证号格式不正确"));\r\n          callback();\r\n        },\r\n        trigger: "blur",\r\n      },\r\n    ],\r\n  },\r\n  {\r\n    field: "gender",\r\n    title: "性别",\r\n    type: "dictSelect",\r\n    props: { placeholder: "请选择性别", options: "gender", clearable: true },\r\n  },\r\n  {\r\n    field: "nation",\r\n    title: "民族",\r\n    type: "dictSelect",\r\n    props: { placeholder: "请选择民族", filterable: true, options: "ethnicity", clearable: true },\r\n  },\r\n  {\r\n    field: "dateBirth",\r\n    title: "出生日期",\r\n    type: "DatePicker",\r\n    props: {\r\n      placeholder: "选择日期",\r\n      type: "date",\r\n      format: "YYYY-MM-DD",\r\n      valueFormat: "YYYY-MM-DD",\r\n      style: "width: 100%",\r\n    },\r\n  },\r\n  {\r\n    field: "appFileId",\r\n    title: "头像",\r\n    type: "upload",\r\n    props: {\r\n      httpRequest: customUpload,\r\n      onRemove: async () => {\r\n        // 删除头像时调用后端软删除接口，清理 t_file 记录\r\n        const fileId = uploadedAvatarId.value;\r\n        if (fileId) {\r\n          try {\r\n            await $common.post("/sym/file/delete", { id: fileId });\r\n          } catch (e) {\r\n            console.error("删除头像文件失败:", e);\r\n          }\r\n        }\r\n        uploadedAvatarId.value = "";\r\n        uploadedDataUrl.value = "";\r\n      },\r\n      onSuccess: (_response: any, uploadFile: any) => {\r\n        const dataUrl = uploadedDataUrl.value;\r\n        if (dataUrl && uploadFile) {\r\n          uploadFile.url = dataUrl;\r\n        }\r\n      },\r\n      name: "file",\r\n      listType: "picture-card",\r\n      limit: 1,\r\n      accept: "image/*",\r\n    },\r\n  },\r\n]);\r\n</script>\r\n\r\n<style scoped lang="scss">\n.drawer-tabs {\n  height: 56px;\n  width: 100%;\n\n  :deep(.el-tabs__header) {\n    height: 100%;\n    margin: 0;\n  }\n\n  :deep(.el-tabs__nav-wrap),\n  :deep(.el-tabs__nav-scroll),\n  :deep(.el-tabs__nav) {\n    height: 100%;\n  }\n\n  :deep(.el-tabs__item) {\n    height: 100%;\n    line-height: 56px;\n  }\n\n  :deep(.el-tabs__active-bar) {\n    height: 2px;\n    bottom: 0;\n    z-index: 2;\n  }\n\n  :deep(.el-tabs__nav-wrap::after) {\n    z-index: 0;\n  }\n\n  :deep(.el-tabs__content) {\n    display: none;\n  }\n}\n\n:deep(.el-drawer__header) {\n  box-sizing: border-box;\n  height: 56px;\n  min-height: 56px;\n  margin-bottom: 0;\n  padding: 0 20px;\n  border-bottom: 1px solid var(--el-border-color-lighter);\n}\n\n.user-roles-panel {\n  min-height: 300px;\n}\n\n.role-panel-tip {\n  margin-bottom: 16px;\n  color: var(--el-text-color-secondary);\n  font-size: 13px;\n}\n\n.role-checkbox-list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.role-checkbox {\n  display: flex;\n  align-items: center;\n  width: 100%;\n  height: auto;\n  min-height: 44px;\n  margin-right: 0;\n  padding: 8px 12px;\n\n  :deep(.el-checkbox__label) {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    min-width: 0;\n    padding-left: 8px;\n  }\n}\n\n.role-checkbox__name {\n  color: var(--el-text-color-primary);\n  font-weight: 500;\n}\n\n.role-checkbox__code {\n  color: var(--el-text-color-secondary);\n  font-size: 12px;\n}\n\n.user-manage-content {\n  width: 100%;\r\n  height: 100%;\r\n\r\n  .left-panel {\r\n    width: 100%;\r\n    height: 100%;\r\n    border-right: 1px solid rgba(5, 5, 5, 0.06);\r\n    overflow-y: auto;\r\n\r\n    .panel-header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      border-bottom: 1px solid rgba(5, 5, 5, 0.06);\r\n      padding-bottom: 10px;\r\n      margin-bottom: 10px;\r\n      margin-right: 14px;\r\n      height: 43px;\r\n\r\n      h3 {\r\n        margin: 0;\r\n        font-size: 16px;\r\n        font-weight: 700;\r\n        color: #464c64;\r\n      }\r\n    }\r\n\r\n    .tree-container {\r\n      height: calc(100% - 53px);\r\n\r\n      .tree-container-custom {\r\n        height: 100%;\r\n\r\n        :deep(.u-tree-search) {\r\n          margin-right: 14px;\r\n        }\r\n\r\n        :deep(.el-tree) {\r\n          padding-right: 14px;\r\n        }\r\n      }\r\n\r\n      .custom-tree-node {\r\n        display: flex;\r\n        align-items: center;\r\n        width: 100%;\r\n\r\n        .node-label {\r\n          flex: 1;\r\n          overflow: hidden;\r\n          text-overflow: ellipsis;\r\n          white-space: nowrap;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  .right-panel {\n    width: 100%;\n    height: 100%;\n\n    :deep(.el-button .el-icon + span) {\n      margin-left: 3px;\n    }\n\n    .toolbar-search-icon {\n      color: var(--el-color-primary);\n      cursor: pointer;\n      font-size: 17px;\n      transition: color 0.2s ease;\n\n      &:hover {\n        color: var(--el-color-primary-light-3);\n      }\n    }\n\n    .user-account-cell {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      min-width: 0;\n    }\n\n    .online-status-dot {\n      flex: 0 0 auto;\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.85);\n    }\n\n    .online-status-dot--online {\n      background: #22c55e;\n    }\n\n    .online-status-dot--offline {\n      background: #f04438;\n    }\n\n    .user-name-link {\n      max-width: 100%;\n      padding: 0;\n      overflow: hidden;\n      color: var(--el-color-primary);\n      font: inherit;\n      line-height: inherit;\n      text-align: left;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n      vertical-align: top;\n      cursor: pointer;\n      background: transparent;\n      border: 0;\n\n      &:hover {\n        text-decoration: underline;\n      }\n    }\n  }\n}\n</style>\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\nconst _unref = ___magic__import__(\'vue\', \'unref\');\nconst _withKeys = ___magic__import__(\'vue\', \'withKeys\');\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\nconst _createBlock = ___magic__import__(\'vue\', \'createBlock\');\nconst _withModifiers = ___magic__import__(\'vue\', \'withModifiers\');\nconst _vShow = ___magic__import__(\'vue\', \'vShow\');\nconst _withDirectives = ___magic__import__(\'vue\', \'withDirectives\');\nconst _resolveDirective = ___magic__import__(\'vue\', \'resolveDirective\');\nconst _hoisted_1 = { class: "user-manage-content card-container px-5 pt-5 pb-2" };\nconst _hoisted_2 = { class: "left-panel" };\nconst _hoisted_3 = { class: "tree-container" };\nconst _hoisted_4 = { class: "right-panel pl-4" };\nconst _hoisted_5 = { class: "flex justify-between items-center w-full" };\nconst _hoisted_6 = { class: "flex" };\nconst _hoisted_7 = { class: "flex items-center gap-2" };\nconst _hoisted_8 = { class: "user-account-cell" };\nconst _hoisted_9 = ["onClick"];\nconst _hoisted_10 = {\n    key: 0,\n    class: "flex flex-wrap gap-1"\n};\nconst _hoisted_11 = {\n    key: 1,\n    class: "text-gray-400"\n};\nconst _hoisted_12 = { class: "px-4" };\nconst _hoisted_13 = {\n    key: 0,\n    class: "user-roles-panel"\n};\nconst _hoisted_14 = { class: "role-checkbox__name" };\nconst _hoisted_15 = {\n    key: 0,\n    class: "role-checkbox__code"\n};\nconst _hoisted_16 = { class: "flex justify-end" };\nconst ref = ___magic__import__(\'vue\', \'ref\');\nconst nextTick = ___magic__import__(\'vue\', \'nextTick\');\nconst h = ___magic__import__(\'vue\', \'h\');\nconst onMounted = ___magic__import__(\'vue\', \'onMounted\');\nconst ElMessage = ___magic__import__(\'element-plus\', \'ElMessage\');\nconst ElSwitch = ___magic__import__(\'element-plus\', \'ElSwitch\');\nconst Search = ___magic__import__(\'@element-plus/icons-vue\', \'Search\');\nconst FormUtils = ___magic__import__(\'@/utils/form\', \'FormUtils\');\nconst request = ___magic__import__(\'@/utils/request\', \'default\');\nconst pinyin = ___magic__import__(\'js-pinyin\', \'default\');\nconst onlineUsersCacheTtl = 15 * 1000;\n/** 查询当前租户全部有效在线会话，并汇总为用户状态。 */\nconst __sfc__ = _defineComponent({\n    __name: \'095470cda82e190be2919afbffbb1586\',\n    setup(__props) {\n        const currentNode = ref(null);\n        /** 上传成功的头像文件 id，保存时直接读取此值，避免从表单 upload 字段解析 */\n        const uploadedAvatarId = ref("");\n        /** 根据 fileId 通过 axios（自动携带 token 头）获取图片，返回 Data URL */\n        const fetchAvatarUrl = async (fileId) => {\n            try {\n                // 后端返回标准 JSON：{ content: "base64...", contentType: "image/png", fileName: "xxx.png" }\n                const res = await request.get("/sym/file/preview", {\n                    params: { id: fileId },\n                });\n                if (!res || !res.content) {\n                    console.warn("[fetchAvatarUrl] 返回数据为空");\n                    return "";\n                }\n                // 直接拼接 Data URL\n                return `data:${res.contentType || "image/png"};base64,${res.content}`;\n            }\n            catch (e) {\n                console.error("获取头像失败:", e);\n                return "";\n            }\n        };\n        const treeData = ref([\n            {\n                name: "全部",\n                value: "",\n                children: [],\n            },\n        ]);\n        /** 获取组织机构树 */\n        const fetchOrgTree = async () => {\n            try {\n                const res = await $common.post("/sym/org/getOrgTree", {\n                    parentId: $user.orgRootId,\n                });\n                treeData.value[0].children = res?.data ?? res ?? [];\n            }\n            catch (e) {\n                console.error("获取组织机构树失败:", e);\n                treeData.value[0].children = [];\n            }\n        };\n        onMounted(() => {\n            fetchOrgTree();\n        });\n        const handleNodeClick = (node) => {\n            currentNode.value = node;\n            refreshTableData();\n        };\n        // ===================== 右侧表格 =====================\n        const tableRef = ref();\n        const searchKeyword = ref("");\n        const filte