INSERT INTO `ui_component_t` (`tid`,`pid`,`name`,`source_code`,`compile_js`,`compile_css`,`type`,`remark`,`created_by`,`updated_by`,`is_del`,`tenant_id`,`sort_order`) VALUES ('2026182131778625536','2026115170365382656','warehouse-card','<template>\r\n  <el-card class="warehouse-card">\r\n    <el-skeleton :loading="loading || !item" animated :rows="4">\r\n      <template #template>\r\n        <div class="flex gap-4">\r\n          <div class="header-icon skeleton-icon"></div>\r\n          <div class="flex flex-col" style="flex: 1">\r\n            <el-skeleton-item\r\n              variant="text"\r\n              style="height: 24px; width: 120px; margin-bottom: 8px"\r\n            />\r\n            <el-skeleton-item variant="text" style="height: 16px; width: 80px" />\r\n          </div>\r\n        </div>\r\n        <div style="margin: 12px 0 20px 0">\r\n          <el-skeleton-item variant="text" style="height: 24px" />\r\n          <el-skeleton-item variant="text" style="height: 24px" />\r\n        </div>\r\n        <div class="flex justify-between items-center">\r\n          <el-skeleton-item variant="text" style="height: 32px; width: 60px" />\r\n          <div class="flex" style="width: 135px">\r\n            <el-skeleton-item variant="button" style="height: 32px; width: 100px" />\r\n            <el-skeleton-item\r\n              variant="button"\r\n              style="height: 32px; width: 32px; margin-left: 8px; border-radius: 50%"\r\n            />\r\n          </div>\r\n        </div>\r\n      </template>\r\n      <template #default>\r\n        <div v-if="item">\r\n          <el-skeleton :loading="loading" animated>\r\n            <!-- 实际卡片内容 -->\r\n            <template #default>\r\n              <div class="card-header">\r\n                <div\r\n                  class="header-icon flex items-center justify-center"\r\n                  :class="`images-warehouse-${item.appIcon}`"\r\n                ></div>\r\n                <div class="header-info">\r\n                  <div class="header-title" :title="item.appName">{{ item.appName }}</div>\r\n                  <div class="header-name flex items-center gap-1">\r\n                    <Icon :icon="\'role\'" :size="14" />\r\n                    {{ item.createdBy || "-" }}\r\n                  </div>\r\n                </div>\r\n              </div>\r\n              <div class="description" :title="item.description">{{ item.description || "-" }}</div>\r\n              <div class="flex justify-between items-center">\r\n                <el-tag :type="item.publishStatus === 1 ? \'success\' : \'warning\'">\r\n                  {{ item.publishStatus === 1 ? "已发布" : "待发布" }}\r\n                </el-tag>\r\n                <div class="flex" style="width: 135px">\r\n                  <el-button type="primary" plain @click="handleClick(\'edit\')">\r\n                    <Icon :icon="\'setting\'" class="mr-2" />\r\n                    编辑配置\r\n                  </el-button>\r\n                  <el-dropdown @command="handleDropdownCommand">\r\n                    <span class="footer-more">\r\n                      <Icon icon="el-icon-MoreFilled" size="14" />\r\n                    </span>\r\n                    <template #dropdown>\r\n                      <el-dropdown-menu>\r\n                        <el-dropdown-item\r\n                          v-for="i in contextmenu"\r\n                          :key="i.key"\r\n                          :command="i.key"\r\n                          :class="{ \'delete-item\': i.key === \'delete\' }"\r\n                          :style="i.key === \'delete\' ? { color: \'#f56c6c\' } : {}"\r\n                        >\r\n                          <Icon :icon="i.icon" class="mr-1" />\r\n                          {{ i.label }}\r\n                        </el-dropdown-item>\r\n                      </el-dropdown-menu>\r\n                    </template>\r\n                  </el-dropdown>\r\n                </div>\r\n              </div>\r\n            </template>\r\n\r\n            <!-- 骨架屏模板 -->\r\n            <template #template>\r\n              <div class="skeleton-content">\r\n                <!-- 头部骨架 -->\r\n                <div class="flex gap-4">\r\n                  <el-skeleton-item\r\n                    variant="rect"\r\n                    style="width: 64px; height: 64px; border-radius: 16px"\r\n                  />\r\n                  <div class="flex flex-col gap-2">\r\n                    <el-skeleton-item variant="text" style="width: 120px; height: 24px" />\r\n                    <el-skeleton-item variant="text" style="width: 80px; height: 16px" />\r\n                  </div>\r\n                </div>\r\n\r\n                <!-- 描述骨架 -->\r\n                <div class="skeleton-description">\r\n                  <el-skeleton-item\r\n                    variant="text"\r\n                    style="width: 100%; height: 16px; margin-bottom: 8px"\r\n                  />\r\n                  <el-skeleton-item variant="text" style="width: 80%; height: 16px" />\r\n                </div>\r\n\r\n                <!-- 底部骨架 -->\r\n                <div class="flex justify-between items-center">\r\n                  <el-skeleton-item variant="button" style="width: 70px; height: 28px" />\r\n                  <div class="flex gap-2">\r\n                    <el-skeleton-item variant="button" style="width: 90px; height: 32px" />\r\n                    <el-skeleton-item variant="circle" style="width: 24px; height: 24px" />\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </template>\r\n          </el-skeleton>\r\n        </div>\r\n      </template>\r\n    </el-skeleton>\r\n  </el-card>\r\n</template>\r\n\r\n<script setup lang="ts">\r\nimport { ref } from "vue";\r\n\r\n// 应用数据接口（匹配 API 返回字段）\r\ninterface AppItem {\r\n  tid: string;\r\n  tenantId?: string;\r\n  appName: string;\r\n  appType: number;\r\n  appIcon: string;\r\n  description: string;\r\n  publishStatus: number; // 0-待发布 1-已发布\r\n  createdBy?: string;\r\n  createdTime?: string;\r\n  updatedBy?: string;\r\n  updatedTime?: string;\r\n}\r\n\r\nconst props = defineProps<{\r\n  item?: AppItem;\r\n  loading?: boolean;\r\n}>();\r\n\r\nconst emit = defineEmits(["operation-click"]);\r\n\r\nconst contextmenu = ref([\r\n  {\r\n    label: props.item?.publishStatus === 0 ? "发布应用" : "取消发布",\r\n    key: "publish",\r\n    icon: "el-icon-Position",\r\n  },\r\n  {\r\n    label: "删除应用",\r\n    key: "delete",\r\n    icon: "el-icon-delete",\r\n  },\r\n]);\r\n\r\nconst handleClick = (action: string) => {\r\n  emit("operation-click", action, props.item);\r\n};\r\n\r\nconst handleDropdownCommand = (command: string) => {\r\n  emit("operation-click", command, props.item);\r\n};\r\n</script>\r\n\r\n<style lang="scss" scoped>\r\n.warehouse-card {\r\n  padding: 16px;\r\n  border-radius: 4px;\r\n  background: #fff;\r\n  border: 1px solid #eaedf7;\r\n  // box-shadow: none !important;\r\n  // border-radius: 6px;\r\n  box-shadow: 0 0 12px #f3f4fa;\r\n  &:hover {\r\n    transform: translateY(-4px);\r\n    border: 1px solid #5591ff;\r\n  }\r\n  .card-header {\r\n    display: flex;\r\n    gap: 16px;\r\n    align-items: flex-start;\r\n  }\r\n  .header-icon {\r\n    width: 64px;\r\n    min-width: 64px;\r\n    height: 64px;\r\n    border-radius: 16px;\r\n    background-size: cover;\r\n  }\r\n  .header-info {\r\n    flex: 1;\r\n    min-width: 0;\r\n  }\r\n  .header-title {\r\n    font-family: "PingFang SC Medium";\r\n    font-weight: 500;\r\n    font-size: 16px;\r\n    line-height: 40px;\r\n    text-align: left;\r\n    color: #323643;\r\n    white-space: nowrap;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n  }\r\n  .header-name {\r\n    font-family: "PingFang SC";\r\n    font-weight: 400;\r\n    font-size: 14px;\r\n    text-align: left;\r\n    color: #828691;\r\n  }\r\n  .description {\r\n    font-family: "PingFang SC";\r\n    font-weight: 400;\r\n    font-size: 14px;\r\n    line-height: 24px;\r\n    text-align: left;\r\n    color: #828691;\r\n    margin: 12px 0 20px 0;\r\n    height: 48px;\r\n    display: -webkit-box;\r\n    -webkit-box-orient: vertical;\r\n    -webkit-line-clamp: 2;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n  }\r\n  :deep(.el-card__body) {\r\n    padding: 0 !important;\r\n    overflow: hidden;\r\n  }\r\n  .footer-more {\r\n    outline: none;\r\n    cursor: pointer;\r\n    transform: rotate(90deg);\r\n  }\r\n  .skeleton-icon {\r\n    border-radius: 16px;\r\n    background: linear-gradient(90deg, #f0f2f5 25%, #e6e8eb 37%, #f0f2f5 63%);\r\n    background-size: 400% 100%;\r\n    animation: skeleton-loading 1.4s ease infinite;\r\n  }\r\n  @keyframes skeleton-loading {\r\n    0% {\r\n      background-position: 100% 50%;\r\n    }\r\n    100% {\r\n      background-position: 0 50%;\r\n    }\r\n  }\r\n\r\n  .skeleton-content {\r\n    .skeleton-description {\r\n      margin: 12px 0 20px 0;\r\n    }\r\n  }\r\n}\r\n</style>\r\n','const _defineComponent = ___magic__import__(\'vue\', \'defineComponent\');\nconst _createElementVNode = ___magic__import__(\'vue\', \'createElementVNode\');\r\nconst _resolveComponent = ___magic__import__(\'vue\', \'resolveComponent\');\r\nconst _createVNode = ___magic__import__(\'vue\', \'createVNode\');\r\nconst _createCommentVNode = ___magic__import__(\'vue\', \'createCommentVNode\');\r\nconst _normalizeClass = ___magic__import__(\'vue\', \'normalizeClass\');\r\nconst _toDisplayString = ___magic__import__(\'vue\', \'toDisplayString\');\r\nconst _createTextVNode = ___magic__import__(\'vue\', \'createTextVNode\');\r\nconst _withCtx = ___magic__import__(\'vue\', \'withCtx\');\r\nconst _renderList = ___magic__import__(\'vue\', \'renderList\');\r\nconst _Fragment = ___magic__import__(\'vue\', \'Fragment\');\r\nconst _openBlock = ___magic__import__(\'vue\', \'openBlock\');\r\nconst _createElementBlock = ___magic__import__(\'vue\', \'createElementBlock\');\r\nconst _normalizeStyle = ___magic__import__(\'vue\', 